INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 1, 1, 'U početku stvori Bog nebo i zemlju.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 1, 2, 'Zemlja bijaše pusta i prazna; tama se prostirala nad bezdanom i Duh Božji lebdio je nad vodama.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 1, 3, 'I reče Bog: \"Neka bude svjetlost!\" I bi svjetlost.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 1, 4, 'I vidje Bog da je svjetlost dobra; i rastavi Bog svjetlost od tame.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 1, 5, 'Svjetlost prozva Bog dan, a tamu prozva noć. Tako bude večer, pa jutro - dan prvi.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 1, 6, 'I reče Bog: \"Neka bude svod posred voda da dijeli vode od voda!\" I bi tako.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 1, 7, 'Bog načini svod i vode pod svodom odijeli od voda nad svodom.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 1, 8, 'A svod prozva Bog nebo. Tako bude večer, pa jutro - dan drugi.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 1, 9, 'I reče Bog: \"Vode pod nebom neka se skupe na jedno mjesto i neka se pokaže kopno!\" I bi tako.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 1, 10, 'Kopno prozva Bog zemlja, a skupljene vode mora. I vidje Bog da je dobro.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 1, 11, 'I reče Bog: \"Neka proklija zemlja zelenilom - travom sjemenitom, stablima plodonosnim, koja, svako prema svojoj vrsti, na zemlji donose plod što u sebi nosi svoje sjeme. I bi tako.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 1, 12, 'I nikne iz zemlje zelena trava što se sjemeni, svaka prema svojoj vrsti, i stabla koja rode plodovima što u sebi nose svoje sjeme, svako prema svojoj vrsti. I vidje Bog da je dobro.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 1, 13, 'Tako bude večer, pa jutro - dan treći.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 1, 14, 'I reče Bog: \"Neka budu svjetlila na svodu nebeskom da luče dan od noći, da budu znaci blagdanima, danima i godinama,');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 1, 15, 'i neka svijetle na svodu nebeskom i rasvjetljuju zemlju!\" I bi tako.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 1, 16, 'I načini Bog dva velika svjetlila - veće da vlada danom, manje da vlada noću - i zvijezde.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 1, 17, 'I Bog ih postavi na svod nebeski da rasvjetljuju zemlju,');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 1, 18, 'da vladaju danom i noću i da rastavljaju svjetlost od tame. I vidje Bog da je dobro.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 1, 19, 'Tako bude večer, pa jutro - dan četvrti.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 1, 20, 'I reče Bog: \"Nek\' povrvi vodom vreva živih stvorova, i ptice nek\' polete nad zemljom, svodom nebeskim!\" I bi tako.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 1, 21, 'Stvori Bog morske grdosije i svakovrsne žive stvorove što mile i vrve vodom i ptice krilate svake vrste. I vidje Bog da je dobro.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 1, 22, 'I blagoslovi ih govoreći: \"Plodite se i množite i napunite vode morske! I ptice neka se namnože na zemlji!\"');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 1, 23, 'Tako bude večer, pa jutro - dan peti.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 1, 24, 'I reče Bog: \"Neka zemlja izvede živa bića, svako prema svojoj vrsti: stoku, gmizavce i zvjerad svake vrste!\" I bi tako.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 1, 25, 'I stvori Bog svakovrsnu zvjerad, stoku i gmizavce svake vrste. I vidje Bog da je dobro.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 1, 26, 'I reče Bog: \"Načinimo čovjeka na svoju sliku, sebi slična, da bude gospodar ribama morskim, pticama nebeskim i stoci - svoj zemlji - i svim gmizavcima što puze po zemlji!\"');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 1, 27, 'Na svoju sliku stvori Bog čovjeka, na sliku Božju on ga stvori, muško i žensko stvori ih.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 1, 28, 'I blagoslovi ih Bog i reče im: \"Plodite se, i množite, i napunite zemlju, i sebi je podložite! Vladajte ribama u moru i pticama u zraku i svim živim stvorovima što puze po zemlji!\"');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 1, 29, 'I doda Bog: \"Evo, dajem vam sve bilje što se sjemeni, po svoj zemlji, i sva stabla plodonosna što u sebi nose svoje sjeme: neka vam budu za hranu!');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 1, 30, 'A zvijerima na zemlji i pticama u zraku i gmizavcima što puze po zemlji u kojima je dah života - neka je za hranu sve zeleno bilje!\" I bi tako.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 1, 31, 'I vidje Bog sve što je učinio, i bijaše veoma dobro. Tako bude večer, pa jutro - dan šesti.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 2, 1, 'Tako bude dovršeno nebo i zemlja sa svom svojom vojskom.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 2, 2, 'I sedmoga dana Bog dovrši svoje djelo koje učini. I počinu u sedmi dan od svega djela koje učini.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 2, 3, 'I blagoslovi Bog sedmi dan i posveti, jer u taj dan počinu od svega djela svoga koje učini.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 2, 4, 'To je postanak neba i zemlje, tako su stvarani. Kad je Jahve, Bog, sazdao nebo i zemlju,');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 2, 5, 'još nije bilo nikakva poljskoga grmlja po zemlji, još ne bijaše niklo nikakvo poljsko bilje, jer Jahve, Bog, još ne pusti dažda na zemlju i nije bilo čovjeka da zemlju obrađuje.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 2, 6, 'Ipak, voda je izvirala iz zemlje i natapala svu površinu zemaljsku.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 2, 7, 'Jahve, Bog, napravi čovjeka od praha zemaljskog i u nosnice mu udahne dah života. Tako postane čovjek živa duša.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 2, 8, 'I Jahve, Bog, zasadi vrt na istoku, u Edenu, i u nj smjesti čovjeka koga je napravio.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 2, 9, 'Tada Jahve, Bog, učini te iz zemlje nikoše svakovrsna stabla - pogledu zamamljiva a dobra za hranu - i stablo života, nasred vrta, i stablo spoznaje dobra i zla.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 2, 10, 'Rijeka je izvirala iz Edena da bi natapala vrt; odatle se granala u četiri kraka.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 2, 11, 'Prvom je ime Pišon, a optječe svom zemljom havilskom, u kojoj ima zlata.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 2, 12, 'Zlato je te zemlje dobro, a ima ondje i bdelija i oniksa.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 2, 13, 'Drugoj je rijeci ime Gihon, a optječe svu zemlju Kuš.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 2, 14, 'Treća je rijeka Tigris, a teče na istok od Ašura; četvrta je Eufrat.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 2, 15, 'Jahve, Bog, uzme čovjeka i postavi ga u edenski vrt da ga obrađuje i čuva.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 2, 16, 'Jahve, Bog, zapovjedi čovjeku: \"Sa svakoga stabla u vrtu slobodno jedi,');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 2, 17, 'ali sa stabla spoznaje dobra i zla da nisi jeo! U onaj dan u koji s njega okusiš, zacijelo ćeš umrijeti!\"');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 2, 18, 'I reče Jahve, Bog: \"Nije dobro da čovjek bude sam: načinit ću mu pomoć kao što je on.\"');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 2, 19, 'Tada Jahve, Bog, načini od zemlje sve životinje u polju i sve ptice u zraku i predvede ih čovjeku da vidi kako će koju nazvati, pa kako koje stvorenje čovjek prozove, da mu tako bude ime.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 2, 20, 'Čovjek nadjene imena svoj stoci, svim pticama u zraku i životinjama u polju. No čovjeku se ne nađe pomoć kao što je on.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 2, 21, 'Tada Jahve, Bog, pusti tvrd san na čovjeka te on zaspa, pa mu izvadi jedno rebro, a mjesto zatvori mesom.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 2, 22, 'Od rebra što ga je uzeo čovjeku napravi Jahve, Bog, ženu pa je dovede čovjeku.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 2, 23, 'Nato čovjek reče: \"Gle, evo kosti od mojih kostiju, mesa od mesa mojega! Ženom neka se zove, od čovjeka kad je uzeta!\"');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 2, 24, 'Stoga će čovjek ostaviti oca i majku da prione uza svoju ženu i bit će njih dvoje jedno tijelo.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 2, 25, 'A bijahu oboje goli - čovjek i njegova žena - ali ne osjećahu stida.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 3, 1, 'Zmija bijaše lukavija od sve zvjeradi što je stvori Jahve, Bog. Ona reče ženi: \"Zar vam je Bog rekao da ne smijete jesti ni s jednog drveta u vrtu?\"');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 3, 2, 'Žena odgovori zmiji: \"Plodove sa stabala u vrtu smijemo jesti.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 3, 3, 'Samo za plod stabla što je nasred vrta rekao je Bog: \'Da ga niste jeli! I ne dirajte u nj, da ne umrete!\'\"');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 3, 4, 'Nato će zmija ženi: \"Ne, nećete umrijeti!');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 3, 5, 'Nego, zna Bog: onog dana kad budete s njega jeli, otvorit će vam se oči, i vi ćete biti kao bogovi koji razlučuju dobro i zlo.\"');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 3, 6, 'Vidje žena da je stablo dobro za jelo, za oči zamamljivo, a za mudrost poželjno: ubere ploda njegova i pojede. Dade i svom mužu, koji bijaše s njom, pa je i on jeo.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 3, 7, 'Tada se obadvoma otvore oči i upoznaju da su goli. Spletu smokova lišća i naprave sebi pregače.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 3, 8, 'Uto čuju korak Jahve, Boga, koji je šetao vrtom za dnevnog povjetarca. I sakriju se - čovjek i njegova žena - pred Jahvom, Bogom, među stabla u vrtu.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 3, 9, 'Jahve, Bog, zovne čovjeka: \"Gdje si?\" - reče mu.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 3, 10, 'On odgovori: \"Čuo sam tvoj korak po vrtu; pobojah se jer sam go, pa se sakrih.\"');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 3, 11, 'Nato mu reče: \"Tko ti kaza da si go? Ti si, dakle, jeo sa stabla s kojega sam ti zabranio jesti?\"');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 3, 12, 'Čovjek odgovori: \"Žena koju si stavio uza me - ona mi je dala sa stabla pa sam jeo.\"');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 3, 13, 'Jahve, Bog, reče ženi: \"Što si to učinila?\" \"Zmija me prevarila pa sam jela\", odgovori žena.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 3, 14, 'Nato Jahve, Bog, reče zmiji: \"Kad si to učinila, prokleta bila među svim životinjama i svom zvjeradi divljom! Po trbuhu svome puzat ćeš i zemlju jesti sveg života svog!');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 3, 15, 'Neprijateljstvo ja zamećem između tebe i žene, između roda tvojeg i roda njezina: on će ti glavu satirati, a ti ćeš mu vrebati petu.\"');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 3, 16, 'A ženi reče: \"Trudnoći tvojoj muke ću umnožit, u mukama djecu ćeš rađati. Žudnja će te mužu tjerati, a on će gospodariti nad tobom.\"');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 3, 17, 'A čovjeku reče: \"Jer si poslušao glas svoje žene te jeo sa stabla s kojega sam ti zabranio jesti rekavši: S njega da nisi jeo! - evo: Zemlja neka je zbog tebe prokleta: s trudom ćeš se od nje hraniti svega vijeka svog!');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 3, 18, 'Rađat će ti trnjem i korovom, a hranit ćeš se poljskim raslinjem.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 3, 19, 'U znoju lica svoga kruh svoj ćeš jesti dokle se u zemlju ne vratiš: tÓa iz zemlje uzet si bio - prah si, u prah ćeš se i vratiti.\"');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 3, 20, 'Svojoj ženi čovjek nadjene ime Eva, jer je majka svima živima.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 3, 21, 'I načini Jahve, Bog, čovjeku i njegovoj ženi odjeću od krzna pa ih odjenu.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 3, 22, 'Zatim reče Bog: \"Evo, čovjek postade kao jedan od nas - znajući dobro i zlo! Da ne bi sada pružio ruku, ubrao sa stabla života pa pojeo i živio navijeke!\"');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 3, 23, 'Zato ga Jahve, Bog, istjera iz vrta edenskoga da obrađuje zemlju iz koje je i uzet.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 3, 24, 'Istjera, dakle, čovjeka i nastani ga istočno od vrta edenskog, pa postavi kerubine i plameni mač koji se svjetlucao - da straže nad stazom koja vodi k stablu života.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 4, 1, 'Čovjek pozna svoju ženu Evu, a ona zače i rodi Kajina, pa reče: \"Muško sam čedo stekla pomoću Jahve!\"');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 4, 2, 'Poslije rodi Abela, brata Kajinova; Abel postane stočar, a Kajin zemljoradnik.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 4, 3, 'I jednoga dana Kajin prinese Jahvi žrtvu od zemaljskih plodova.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 4, 4, 'A prinese i Abel od prvine svoje stoke, sve po izbor pretilinu. Jahve milostivo pogleda na Abela i njegovu žrtvu,');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 4, 5, 'a na Kajina i žrtvu njegovu ni pogleda ne svrati. Stoga se Kajin veoma razljuti i lice mu se namrgodi.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 4, 6, 'I Jahve reče Kajinu: \"Zašto si ljut? Zašto ti je lice namrgođeno?');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 4, 7, 'Jer ako pravo radiš, vedrinom odsijevaš. A ne radiš li pravo, grijeh ti je kao zvijer na pragu što na te vreba; još mu se možeš oduprijeti.\"');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 4, 8, 'Kajin pak reče svome bratu Abelu: \"Hajdemo van!\" I našavši se na polju, Kajin skoči na brata Abela te ga ubi.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 4, 9, 'Potom Jahve zapita Kajina: \"Gdje ti je brat Abel?\" \"Ne znam\", odgovori. \"Zar sam ja čuvar brata svoga?\"');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 4, 10, 'Jahve nastavi: \"Što si učinio? Slušaj! Krv brata tvoga iz zemlje k meni viče.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 4, 11, 'Stoga budi proklet na zemlji koja je rastvorila usta da proguta s ruke tvoje krv brata tvoga!');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 4, 12, 'Obrađivat ćeš zemlju, ali ti više neće davati svoga roda. Vječni ćeš skitalica na zemlji biti!\"');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 4, 13, 'A Kajin reče Jahvi: \"Kazna je moja odviše teška da se snosi.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 4, 14, 'Evo me tjeraš danas s plodnoga tla; moram se skrivati od tvoga lica i biti vječni lutalac na zemlji - tko me god nađe, može me ubiti.\"');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 4, 15, 'A Jahve mu reče: \"Ne! Nego tko ubije Kajina, sedmerostruka osveta na njemu će se izvršiti!\" I Jahve stavi znak na Kajina, da ga tko, našavši ga, ne ubije.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 4, 16, 'Kajin ode ispred lica Jahvina u zemlju Nod, istočno od Edena, i ondje se nastani.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 4, 17, 'Kajin pozna svoju ženu te ona zače i rodi Henoka. Podigao je grad i grad prozvao imenom svoga sina - Henok.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 4, 18, 'Henoku se rodio Irad, a od Irada potekao Mehujael; od Mehujaela poteče Metušael, od Metušaela Lamek.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 4, 19, 'Lamek uzme dvije žene. Jedna se zvala Ada, a druga Sila.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 4, 20, 'Ada rodi Jabala, koji je postao praocem onih što pod šatorima žive sa stokom.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 4, 21, 'Bratu mu bijaše ime Jubal. On je praotac svih koji sviraju na liru i sviralu.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 4, 22, 'Sila rodi Tubal-Kajina, praoca onih koji kuju bakar i željezo. Tubal-Kajinovoj sestri bijaše ime Naama.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 4, 23, 'Lamek prozbori svojim ženama: \"Ada i Sila, glas moj poslušajte! Žene Lamekove, čujte mi besjedu: Čovjeka sam ubio jer me ranio i dijete jer me udarilo.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 4, 24, 'Ako će Kajin biti osvećen sedmerostruko, Lamek će sedamdeset i sedam puta!\"');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 4, 25, 'Adam pozna svoju ženu te ona rodi sina i nadjenu mu ime Šet. Reče ona: \"Bog mi dade drugo dijete mjesto Abela, koga ubi Kajin.\"');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 4, 26, 'Šetu se rodi sin, komu on nadjenu ime Enoš. Tada se počelo zazivati ime Jahvino.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 5, 1, 'Ovo je povijest Adamova roda. Kad je Bog stvorio čovjeka, napravio ga je na priliku svoju;');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 5, 2, 'stvorio je muško i žensko. A kad ih je stvorio, blagoslovi ih i nazva - čovjek.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 5, 3, 'Kad je Adamu bilo sto i trideset godina, rodi mu se sin njemu sličan, na njegovu sliku; nadjenu mu ime Šet.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 5, 4, 'Po rođenju Šetovu Adam je živio osam stotina godina te mu se rodilo još sinova i kćeri.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 5, 5, 'Adam poživje u svemu devet stotina i trideset godina. Potom umrije.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 5, 6, 'Kad je Šetu bilo sto i pet godina, rodi mu se Enoš.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 5, 7, 'Po rođenju Enoševu Šet je živio osam stotina i sedam godina te mu se rodilo još sinova i kćeri.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 5, 8, 'Šet poživje u svemu devet stotina i dvanaest godina. Potom umrije.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 5, 9, 'Kad je Enošu bilo devedeset godina, rodi mu se Kenan.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 5, 10, 'Po rođenju Kenanovu Enoš je živio osam stotina i petnaest godina te mu se rodilo još sinova i kćeri.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 5, 11, 'Enoš poživje u svemu devet stotina i pet godina. Potom umrije.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 5, 12, 'Kad je Kenanu bilo sedamdeset godina, rodi mu se Mahalalel.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 5, 13, 'Po rođenju Mahalalelovu Kenan je živio osam stotina i četrdeset godina te mu se rodilo još sinova i kćeri.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 5, 14, 'Kenan poživje u svemu devet stotina i deset godina. Potom umrije.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 5, 15, 'Kad je Mahalalelu bilo šezdeset i pet godina, rodi mu se Jered.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 5, 16, 'Po rođenju Jeredovu Mahalalel je živio osam stotina i trideset godina te mu se rodilo još sinova i kćeri.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 5, 17, 'Mahalalel poživje u svemu osam stotina devedeset i pet godina. Potom umrije.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 5, 18, 'Kad je Jeredu bilo sto šezdeset i dvije godine, rodi mu se Henok.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 5, 19, 'Po rođenju Henokovu Jered je živio osam stotina godina te mu se rodilo još sinova i kćeri.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 5, 20, 'Jered poživje u svemu devet stotina šezdeset i dvije godine. Potom umrije.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 5, 21, 'Kad je Henoku bilo šezdeset i pet godina, rodi mu se Metušalah.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 5, 22, 'Henok je hodio s Bogom. Po rođenju Metušalahovu Henok je živio trista godina te mu se rodilo još sinova i kćeri.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 5, 23, 'Henok poživje u svemu trista šezdeset i pet godina.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 5, 24, 'Henok je hodio s Bogom, potom iščeznu; Bog ga uze.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 5, 25, 'Kad je Metušalahu bilo sto osamdeset i sedam godina, rodi mu se Lamek.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 5, 26, 'Po rođenju Lamekovu Metušalah je živio sedam stotina osamdeset i dvije godine te mu se rodilo još sinova i kćeri.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 5, 27, 'Metušalah poživje u svemu devet stotina šezdeset i devet godina. Potom umrije.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 5, 28, 'Kad su Lameku bile sto osamdeset i dvije godine, rodi mu se sin.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 5, 29, 'Nadjene mu ime Noa, govoreći: \"Ovaj će nam pribavljati, u trudu i naporu naših ruku, utjehu iz zemlje koju je Bog prokleo.\"');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 5, 30, 'Po rođenju Noinu Lamek je živio pet stotina devedeset i pet godina te mu se rodilo još sinova i kćeri.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 5, 31, 'Lamek poživje u svemu sedam stotina sedamdeset i sedam godina. Potom umrije.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 5, 32, 'Pošto je Noa proživio pet stotina godina, rode mu se Šem, Ham i Jafet.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 6, 1, 'Kad su se ljudi počeli širiti po zemlji i kćeri im se narodile,');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 6, 2, 'opaze sinovi Božji da su kćeri ljudske pristale, pa ih uzimahu sebi za žene koje su god htjeli.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 6, 3, 'Onda Jahve reče: \"Neće moj duh u čovjeku ostati dovijeka; čovjek je tjelesan, pa neka mu vijek bude stotinu dvadeset godina.\"');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 6, 4, 'U ona su vremena - a i kasnije - na zemlji bili Nefili, kad su Božji sinovi općili s ljudskim kćerima pa im one rađale djecu. To su oni od starine po snazi glasoviti ljudi.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 6, 5, 'Vidje Jahve kako je čovjekova pokvarenost na zemlji velika i kako je svaka pomisao u njegovoj pameti uvijek samo zloća.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 6, 6, 'Jahve se pokaja i u svom srcu ražalosti što je načinio čovjeka na zemlji.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 6, 7, 'Reče Jahve: \"Ljude koje sam stvorio izbrisat ću s lica zemlje - od čovjeka do zvijeri, puzavce i ptice u zraku - jer sam se pokajao što sam ih napravio.\"');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 6, 8, 'Ali je Noa našao milost u očima Jahvinim.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 6, 9, 'Ovo je povijest Noina: Noa je bio čovjek pravedan i neporočan u svom vremenu. S Bogom je Noa hodio.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 6, 10, 'Tri su se sina rodila Noi: Šem, Ham i Jafet.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 6, 11, 'U očima Božjim zemlja se bila iskvarila; nepravdom se napunila.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 6, 12, 'I kad je Bog vidio kako se zemlja iskvarila - tÓa svako se biće na zemlji izopačilo -');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 6, 13, 'reče Bog Noi: \"Odlučio sam da bude kraj svim bićima jer se zemlja napunila opačinom; i, evo, uništit ću ih zajedno sa zemljom.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 6, 14, 'Napravi sebi korablju od smolastoga drveta; korablju načini s prijekletima i obloži je iznutra i izvana paklinom.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 6, 15, 'A pravit ćeš je ovako: neka korablja bude trista lakata u duljinu, pedeset u širinu, a trideset lakata u visinu.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 6, 16, 'Na korablji načini otvor za svjetlo, završi ga jedan lakat od vrha. Vrata na korablji načini sa strane; neka ima donji, srednji i gornji kat.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 6, 17, 'Ja ću, evo, pustiti potop - vode na zemlju - da izgine svako biće pod nebom, sve u čemu ima dah života: sve na zemlji mora poginuti.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 6, 18, 'A s tobom ću učiniti Savez; ti ćeš ući u korablju - ti i s tobom tvoji sinovi, tvoja žena i žene tvojih sinova.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 6, 19, 'A od svega što je živo - od svih bića - uvedi u korablju od svakoga po dvoje da s tobom preživi, i neka budu muško i žensko.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 6, 20, 'Od ptica prema njihovim vrstama, od životinja prema njihovim vrstama i od svih stvorova što po tlu puze prema njihovim vrstama: po dvoje od svega neka uđe k tebi da preživi.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 6, 21, 'Sa sobom uzmi svega za jelo pa čuvaj da bude hrane tebi i njima.\"');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 6, 22, 'Noa učini tako. Sve kako mu je Bog naredio, tako je izvršio.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 7, 1, 'Onda Jahve reče Noi: \"Uđi ti i sva tvoja obitelj u korablju, jer sam uvidio da si ti jedini preda mnom pravedan u ovom vremenu.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 7, 2, 'Uzmi sa sobom od svih čistih životinja po sedam parova: mužjaka i njegovu ženku.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 7, 3, 'Isto tako od ptica nebeskih po sedam parova - mužjaka i ženku - da im se sjeme sačuva na zemlji.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 7, 4, 'Jer ću do sedam dana pustiti dažd po zemlji četrdeset dana i četrdeset noći te ću istrijebiti s lica zemlje svako živo biće što sam ga načinio.\"');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 7, 5, 'Noa učini sve kako mu je Jahve naredio.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 7, 6, 'Noi bijaše šest stotina godina kad je potop došao na zemlju.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 7, 7, 'I pred vodama potopnim uđu s Noom u korablju njegovi sinovi, njegova žena i žene sinova njegovih.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 7, 8, 'Od čistih životinja i od životinja koje nisu čiste, od ptica, od svega što zemljom puzi,');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 7, 9, 'uđe po dvoje - mužjak i ženka - u korablju s Noom, kako je Bog naredio Noi.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 7, 10, 'A sedmoga dana zapljušte potopne vode po zemlji.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 7, 11, 'U dan onaj - šestote godine Noina života, mjeseca drugog, dana u mjesecu sedamnaestog - navale svi izvori bezdana, rastvore se ustave nebeske.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 7, 12, 'I udari dažd na zemlju da pljušti četrdeset dana i četrdeset noći.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 7, 13, 'Onog dana uđe u korablju Noa i njegovi sinovi: Šem, Ham i Jafet, Noina žena i tri žene Noinih sinova s njima;');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 7, 14, 'oni, pa sve vrste životinja: stoka, gmizavci što po tlu gmižu, ptice i svakovrsna krilata stvorenja,');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 7, 15, 'uđu u korablju s Noom, po dvoje od svih bića što u sebi imaju dah života.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 7, 16, 'Što uđe, sve bijaše par, mužjak i ženka od svih bića, kako je Bog naredio Noi. Onda Jahve zatvori za njim vrata.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 7, 17, 'Pljusak je na zemlju padao četrdeset dana; vode sveudilj rasle i korablju nosile: digla se visoko iznad zemlje.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 7, 18, 'Vode su nad zemljom bujale i visoko rasle, a korablja plovila površinom.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 7, 19, 'Vode su sve silnije navaljivale i rasle nad zemljom, tako te prekriše sva najviša brda pod nebom.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 7, 20, 'Petnaest lakata dizale se vode povrh potonulih brda.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 7, 21, 'Izgiboše sva bića što se po zemlji kreću: ptice, stoka, zvijeri, svi gmizavci i svi ljudi.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 7, 22, 'Sve što u svojim nosnicama imaše dah života - sve što bijaše na kopnu - izgibe.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 7, 23, 'Istrijebi se svako biće s površja zemaljskog: čovjek, životinje, gmizavci i ptice nebeske, sve se izbrisa sa zemlje. Samo Noa ostade i oni što bijahu s njim u korablji.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 7, 24, 'Stotinu pedeset dana vladahu vode zemljom.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 8, 1, 'Onda se Bog sjeti Noe, svih zvijeri i sve stoke što bijaše s njim u korablji, pa pokrenu vjetar nad zemljom da uzbije vodu.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 8, 2, 'Zatvoriše se izvori bezdanu i ustave nebeske, i dažd s neba prestade.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 8, 3, 'Polako se povlačile vode sa zemlje. Nakon stotinu pedeset dana vode su jenjale,');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 8, 4, 'a sedmoga mjeseca, sedamnaestog dana u mjesecu korablja se zaustavi na brdima Ararata.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 8, 5, 'Vode su neprestano opadale do desetog mjeseca, a prvoga dana desetog mjeseca pokažu se brdski vrhunci.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 8, 6, 'Kad je izminulo četrdeset dana, Noa otvori prozor što ga je načinio na korablji;');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 8, 7, 'ispusti gavrana, a gavran svejednako odlijetaše i dolijetaše dok se vode sa zemlje nisu isušile.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 8, 8, 'Zatim ispusti golubicu da vidi je li voda nestala sa zemlje.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 8, 9, 'Ali golubica ne nađe uporišta nogama te se vrati k njemu u korablju, jer voda još pokrivaše svu površinu; on pruži ruku, uhvati golubicu te je unese k sebi u korablju.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 8, 10, 'Počeka još sedam dana pa opet pusti golubicu iz korablje.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 8, 11, 'Prema večeri golubica se vrati k njemu, i gle! u kljunu joj svjež maslinov list; tako je Noa doznao da su opale vode sa zemlje.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 8, 12, 'Još počeka sedam dana pa opet pusti golubicu: više mu se nije vratila.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 8, 13, 'Šest stotina prve godine Noina života, prvoga mjeseca, prvog dana u mjesecu uzmakoše vode sa zemlje. Noa skine pokrov s korablje i pogleda: površina okopnjela.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 8, 14, 'A drugoga mjeseca, sedamnaestog dana u mjesecu, zemlja bijaše suha.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 8, 15, 'Tada Bog reče Noi:');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 8, 16, '\"Iziđi iz korablje, ti, tvoja žena, tvoji sinovi i žene tvojih sinova s tobom.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 8, 17, 'Sa sobom izvedi sva živa bića, sva stvorenja što su s tobom: ptice, stoku i sve gmizavce što zemljom puze; neka zemljom vrve, plode se i na zemlji množe!\"');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 8, 18, 'I Noa iziđe, a s njime sinovi njegovi, žena njegova i žene sinova njegovih.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 8, 19, 'Sve životinje, svi gmizavci, sve ptice - svi stvorovi što se zemljom miču - iziđu iz korablje, vrsta za vrstom.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 8, 20, 'I podiže Noa žrtvenik Jahvi; uze od svih čistih životinja i od svih čistih ptica i prinese na žrtveniku žrtve paljenice.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 8, 21, 'Jahve omirisa miris ugodni pa reče u sebi: \"Nikad više neću zemlju u propast strovaliti zbog čovjeka, tÓa čovječje su misli opake od njegova početka; niti ću ikad više uništiti sva živa stvorenja, kako sam učinio.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 8, 22, 'Sve dok zemlje bude, sjetve, žetve, studeni, vrućine, ljeta, zime, dani, noći nikada prestati neće.\"');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 9, 1, 'Tada Bog blagoslovi Nou i njegove sinove i reče im: \"Plodite se i množite i zemlju napunite.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 9, 2, 'Neka vas se boje i od vas strahuju sve životinje na zemlji, sve ptice u zraku, sve što se po zemlji kreće i sve ribe u moru: u vaše su ruke predane.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 9, 3, 'Sve što se kreće i živi neka vam bude za hranu: sve vam dajem, kao što vam dadoh zeleno bilje.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 9, 4, 'Samo ne smijete jesti mesa u kojem je još duša, to jest njegova krv.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 9, 5, 'A za vašu krv, za vaš život, tražit ću obračun: tražit ću ga od svake životinje; i od čovjeka za njegova druga tražit ću obračun za ljudski život.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 9, 6, 'Tko prolije krv čovjekovu, njegovu će krv čovjek proliti! Jer na sliku Božju stvoren je čovjek!');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 9, 7, 'A vi, plodite se, i množite i zemlju napunite, i podložite je sebi!\"');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 9, 8, 'Još reče Bog Noi i njegovim sinovima s njim:');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 9, 9, '\"A ja, evo, sklapam svoj Savez s vama i s vašim potomstvom poslije vas');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 9, 10, 'i sa svim živim stvorovima što su s vama: s pticama, sa stokom, sa zvijerima - sa svime što je s vama izišlo iz korablje - sa svim živim stvorovima na zemlji.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 9, 11, 'Držat ću se ja svog Saveza s vama te nikada više vode potopne neće uništiti živa bića niti će ikad više potop zemlju opustošiti.\"');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 9, 12, 'I reče Bog: \"A ovo znamen je Saveza koji stavljam između sebe i vas i svih živih bića što su s vama, za naraštaje buduće:');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 9, 13, 'Dugu svoju u oblak stavljam, da zalogom bude Savezu između mene i zemlje.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 9, 14, 'Kad oblake nad zemlju navučem i duga se u oblaku pokaže,');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 9, 15, 'spomenut ću se Saveza svoga, Saveza između mene i vas i stvorenja svakoga živog: potopa više neće biti da uništi svako biće.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 9, 16, 'U oblaku kad se pojavi duga, ja ću je vidjeti i vjekovnog ću se sjećati Saveza između Boga i svake žive duše, svakog tijela na zemlji.\"');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 9, 17, 'I reče Bog Noi: \"To neka je znak Saveza koji sam postavio između sebe i svih živih bića što su na zemlji.\"');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 9, 18, 'Sinovi Noini, koji su iz korablje izišli, bijahu: Šem, Ham i Jafet. Ham je praotac Kanaanaca.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 9, 19, 'Ovo su trojica Noinih sinova i od njih se sav svijet razgranao.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 9, 20, 'Noa, zemljoradnik, zasadio vinograd.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 9, 21, 'Napio se vina i opio, pa se otkrio nasred šatora.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 9, 22, 'Ham, praotac Kanaanaca, opazi oca gola pa to kaza dvojici svoje braće vani.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 9, 23, 'Šem i Jafet uzmu ogrtač, obojica ga prebace sebi preko ramena pa njime, idući natraške, pokriju očevu golotinju. Lica im bijahu okrenuta na drugu stranu, tako te ne vidješe oca gola.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 9, 24, 'Kad se Noa otrijeznio od vina i saznao što mu je učinio najmlađi sin, reče:');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 9, 25, '\"Neka je proklet Kanaanac, braći svojoj najniži sluga nek\' bude!\"');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 9, 26, 'Onda nastavi: \"Blagoslovljen Jahve, Šemov Bog, Kanaanac nek\' mu je sluga!');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 9, 27, 'Nek Bog raširi Jafeta da prebiva pod šatorima Šemovim, Kanaanac nek\' mu je sluga!\"');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 9, 28, 'Poslije Potopa Noa poživje trista pedeset godina.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 9, 29, 'U svemu poživje Noa devet stotina pedeset godina; potom umrije.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 10, 1, 'Ovo je povijest Noinih sinova: Šema, Hama i Jafeta, kojima su se rodili sinovi poslije Potopa.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 10, 2, 'Sinovi su Jafetovi: Gomer, Magog, Madaj, Javan, Tubal, Mešak, Tiras.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 10, 3, 'A sinovi su Gomerovi: Aškenaz, Rifat i Togarma.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 10, 4, 'Javanovi su opet sinovi: Eliša, Taršiš, Kitijci i Dodanci.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 10, 5, 'Od njih su se razgranali narodi po otocima. To su Jafetovi sinovi prema svojim zemljama - svaki s vlastitim jezikom - prema svojim plemenima i narodima.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 10, 6, 'Sinovi su Hamovi: Kuš i Misrajim, Put i Kanaan.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 10, 7, 'Kuševi su: Seba, Havila, Sabta, Rama i Sabteka. Ramini su: Šeba i Dedan.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 10, 8, 'Od Kuša se rodio Nimrod, koji je postao prvi velmoža na zemlji.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 10, 9, 'Voljom Jahve bio je silan lovac. Zato se veli: \"Kao Nimrod, silan lovac voljom Jahve.\"');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 10, 10, 'Glavno uporište njegova kraljevstva bili su: Babilon, Erek, Akad i Kalne, svi u zemlji Šinearu.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 10, 11, 'Iz ove je zemlje došao Ašur. On je podigao Ninivu, Rehobot Ir, Kalah');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 10, 12, 'i Resen između Ninive i Kalaha (to je glavni grad).');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 10, 13, 'Od Misrajima potekli su Ludijci, Anamijci, Lehabijci, Naftuhijci,');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 10, 14, 'pa Patrušani, Kasluhijci i Kaftorci, od kojih su potekli Filistejci.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 10, 15, 'Od Kanaana potječe Sidon, njegov prvenac, i Het.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 10, 16, 'Dalje: Jebusejci, Amorejci, Girgašani,');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 10, 17, 'Hivijci, Arkijci, Sinijci,');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 10, 18, 'Arvađani, Semarjani i Hamaćani. Poslije se kanaanska plemena razgranaše,');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 10, 19, 'tako da se granica Kanaanaca protezala od Sidona prema Geraru sve do Gaze pa prema Sodomi, Gomori, Admi i Sebojimu sve do Leše.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 10, 20, 'To su sinovi Hamovi prema svojim plemenima i jezicima, po svojim zemljama i narodima.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 10, 21, 'A i Šemu - praocu svih sinova Eberovih i starijem bratu Jafetovu - rodili se sinovi.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 10, 22, 'Šemovi su sinovi: Elam, Ašur, Arpakšad, Lud i Aram.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 10, 23, 'A Aramovi su sinovi: Us, Hul, Geter i Maš.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 10, 24, 'Arpakšad rodi Šelaha, Šelah rodi Ebera.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 10, 25, 'Eberu su se rodila dva sina: jednomu bješe ime Peleg, jer se za njegova vijeka zemlja razdijelila. Njegovu je bratu bilo ime Joktan.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 10, 26, 'Od Joktana se rodiše: Almodad, Šelef, Hasarmavet, Jerah,');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 10, 27, 'Hadoram, Uzal, Dikla,');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 10, 28, 'Obal, Abimael, Šeba,');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 10, 29, 'Ofir, Havila i Jobab. Sve su to sinovi Joktanovi.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 10, 30, 'Njihova se naselja protezahu od Meše sve do Sefara, brdovitih krajeva na istoku.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 10, 31, 'To su sinovi Šemovi prema svojim plemenima, jezicima i zemljama, po svojim narodima.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 10, 32, 'To su rodovi Noinih sinova prema svojim lozama i narodima. Od njih su se razgranali narodi po zemlji poslije Potopa.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 11, 1, 'Sva je zemlja imala jedan jezik i riječi iste.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 11, 2, 'Ali kako su se ljudi selili s istoka, naiđu na jednu dolinu u zemlji Šinearu i tu se nastane.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 11, 3, 'Jedan drugome reče: \"Hajdemo praviti opeke te ih peći da otvrdnu!\" Opeke im bile mjesto kamena, a paklina im služila za žbuku.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 11, 4, 'Onda rekoše: \"Hajde da sebi podignemo grad i toranj s vrhom do neba! Pribavimo sebi ime, da se ne raspršimo po svoj zemlji!\"');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 11, 5, 'Jahve se spusti da vidi grad i toranj što su ga gradili sinovi čovječji.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 11, 6, 'Jahve reče. \"Zbilja su jedan narod, s jednim jezikom za sve! Ovo je tek početak njihovih nastojanja. Sad im ništa neće biti neostvarivo što god naume izvesti.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 11, 7, 'Hajde da siđemo i jezik im pobrkamo, da jedan drugome govora ne razumije.\"');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 11, 8, 'Tako ih Jahve rasu odande po svoj zemlji te ne sazidaše grada.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 11, 9, 'Stoga mu je ime Babel, jer je ondje Jahve pobrkao govor svima u onom kraju i odande ih je Jahve raspršio po svoj zemlji.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 11, 10, 'Ovo su potomci Šemovi: Kad je Šemu bilo sto godina - dvije godine poslije Potopa - rodi mu se Arpakšad.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 11, 11, 'Po rođenju Arpakšadovu Šem je živio petsto godina te mu se rodilo još sinova i kćeri.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 11, 12, 'Kad je Arpakšadu bilo trideset i pet godina, rodi mu se Šelah.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 11, 13, 'Po rođenju Šelahovu Arpakšad je živio četiri stotine i tri godine te mu se rodilo još sinova i kćeri.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 11, 14, 'Kad je Šelahu bilo trideset godina, rodi mu se Eber.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 11, 15, 'Po rođenju Eberovu Šelah je živio četiri stotine i tri godine te mu se rodilo još sinova i kćeri.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 11, 16, 'Kad su Eberu bile trideset i četiri godine, rodi mu se Peleg.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 11, 17, 'Po rođenju Pelegovu Eber je živio četiri stotine i trideset godina te mu se rodilo još sinova i kćeri.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 11, 18, 'Kad je Pelegu bilo trideset godina, rodi mu se Reu.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 11, 19, 'Po rođenju Reuovu Peleg je živio dvjesta i devet godina te mu se rodilo još sinova i kćeri.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 11, 20, 'Kad su Reuu bile trideset i dvije godine, rodi mu se Serug.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 11, 21, 'Po rođenju Serugovu Reu je živio dvjesta i sedam godina te mu se rodilo još sinova i kćeri.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 11, 22, 'Kad je Serugu bilo trideset godina, rodi mu se Nahor.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 11, 23, 'Po rođenju Nahorovu Serug je živio dvjesta godina te mu se rodilo još sinova i kćeri.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 11, 24, 'Kad je Nahoru bilo dvadeset i devet godina, rodi mu se Terah.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 11, 25, 'Po rođenju Terahovu Nahor je živio sto i devetnaest godina te mu se rodilo još sinova i kćeri.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 11, 26, 'Kad je Terahu bilo sedamdeset godina, rode mu se: Abram, Nahor i Haran.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 11, 27, 'Ovo je povijest Terahova. Terahu se rodio Abram, Nahor i Haran; a Haranu se rodio Lot.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 11, 28, 'Haran umrije za života svoga oca Teraha, u svome rodnom kraju, u Uru Kaldejskom.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 11, 29, 'Abram se i Nahor ožene. Abramovoj ženi bijaše ime Saraja, a Nahorovoj Milka; ova je bila kći Harana, oca Milke i Jiske.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 11, 30, 'Saraja bijaše nerotkinja - nije imala poroda.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 11, 31, 'Terah povede svoga sina Abrama, svog unuka Lota, sina Haranova, svoju snahu Saraju, ženu svoga sina Abrama, pa se zaputi s njima iz Ura Kaldejskoga u zemlju kanaansku. Kad stignu do Harana, ondje se nastane.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 11, 32, 'Dob Terahova dosegnu dvjesta i pet godina; a onda Terah umrije u Haranu.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 12, 1, 'Jahve reče Abramu: \"Idi iz zemlje svoje, iz zavičaja i doma očinskog, u krajeve koje ću ti pokazati.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 12, 2, 'Velik ću narod od tebe učiniti, blagoslovit ću te, ime ću ti uzveličati, i sam ćeš biti blagoslov.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 12, 3, 'Blagoslivljat ću one koji te blagoslivljali budu, koji te budu kleli, njih ću proklinjati; sva plemena na zemlji tobom će se blagoslivljati.\"');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 12, 4, 'Abram se zaputi kako mu je Jahve rekao. S njime krenu i Lot. Abramu je bilo sedamdeset i pet godina kad je otišao iz Harana.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 12, 5, 'Abram uze sa sobom svoju ženu Saraju, svoga bratića Lota, svu imovinu što su je namakli i svu čeljad koju su stekli u Haranu te svi pođu u zemlju kanaansku. Kad su stigli u Kanaan,');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 12, 6, 'Abram prođe zemljom do mjesta Šekema - do hrasta More. Kanaanci su onda bili u zemlji.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 12, 7, 'Jahve se javi Abramu pa mu reče: \"Tvome ću potomstvu dati ovu zemlju.\" Abram tu podigne žrtvenik Jahvi koji mu se objavio.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 12, 8, 'Odatle prijeđe u brdoviti kraj, na istok od Betela. Svoj šator postavi između Betela na zapadu i Aja na istoku. Ondje podigne žrtvenik Jahvi i zazva ime Jahvino.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 12, 9, 'Od postaje do postaje Abram se pomicao prema Negebu.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 12, 10, 'Ali kad je zemljom zavladala glad, Abram se spusti u Egipat da ondje proboravi, jer je velika glad harala zemljom.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 12, 11, 'Kad je bio na ulazu u Egipat, reče svojoj ženi Saraji: \"Znam da si lijepa žena.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 12, 12, 'Kad te Egipćani vide, reći će: \'To je njegova žena\', i mene će ubiti, a tebe na životu ostaviti.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 12, 13, 'Nego reci da si mi sestra, tako da i meni bude zbog tebe dobro i da, iz obzira prema tebi, poštede moj život.\"');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 12, 14, 'Zbilja, kad je Abram ušao u Egipat, Egipćani vide da je žena veoma lijepa.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 12, 15, 'Vide je faraonovi dvorani pa je pohvale faraonu i odvedu ženu na faraonov dvor.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 12, 16, 'Abramu pođe dobro zbog nje; steče on stoke i goveda, magaraca, slugu i sluškinja, magarica i deva.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 12, 17, 'Ali Jahve udari faraona i njegov dom velikim nevoljama zbog Abramove žene Saraje.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 12, 18, 'I faraon pozva Abrama pa reče: \"Što si mi to učinio? Zašto mi nisi kazao da je ona tvoja žena?');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 12, 19, 'Zašto si rekao: \'Ona mi je sestra\', pa je ja uzeh sebi za ženu? A sad, evo ti žene; uzmi je i hajde!\"');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 12, 20, 'Faraon ga onda preda momcima, a oni ga otprave s njegovom ženom i sa svime što bijaše njegovo.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 13, 1, 'Iz Egipta Abram ode gore u Negeb sa svojom ženom i sa svime što je imao. I Lot bješe s njim.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 13, 2, 'Abram je bio veoma bogat stokom, srebrom i zlatom.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 13, 3, 'Od postaje do postaje iz Negeba išao je do Betela,');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 13, 4, 'do mjesta na kojem je bio postavio šator, između Betela i Aja, gdje je prije podigao žrtvenik. Tu je Abram zazivao ime Jahvino.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 13, 5, 'I Lot, koji iđaše s Abramom, imaše ovaca, goveda i šatora,');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 13, 6, 'tako da ih kraj ne bi izdržavao kad bi zajedno ostali. Njihovo je blago bilo veliko, te zajedno nisu mogli boraviti.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 13, 7, 'Svađa je nastajala između pastira stoke Abramove i pastira stoke Lotove. Tada su zemlju nastavali Kanaanci i Perižani.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 13, 8, 'Zato Abram reče Lotu: \"Neka ne bude svađe između mene i tebe, između pastira mojih i tvojih - tÓa mi smo braća!');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 13, 9, 'Nije li sva zemlja pred tobom? Odvoji se od mene! Kreneš li ti nalijevo, ja ću nadesno; ako ćeš ti nadesno, ja ću nalijevo.\"');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 13, 10, 'Lot podiže oči i vidje kako je dobro posvuda natapana sva Jordanska dolina, kao kakav vrt Jahvin, kao zemlja egipatska prema Soaru. - Bilo je to prije nego što je Jahve uništio Sodomu i Gomoru. -');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 13, 11, 'Lot izabere za se svu Jordansku dolinu i ode na istok. Tako se odijele jedan od drugoga.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 13, 12, 'Abram ostade u kanaanskoj zemlji, dok je Lot živio po mjestima u dolini i razapeo svoje šatore do Sodome.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 13, 13, 'A žitelji Sodome bijahu veoma opaki, sami grešnici protiv Jahve.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 13, 14, 'Jahve reče Abramu, pošto se Lot od njega rastao: \"Oči svoje podigni i s mjesta na kojem si pogledaj prema sjeveru, jugu, istoku i zapadu;');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 13, 15, 'jer svu zemlju što je možeš vidjeti dat ću tebi i tvome potomstvu zauvijek.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 13, 16, 'Potomstvo ću tvoje učiniti kao prah na zemlji. Ako tko mogne prebrojiti prah zemlje, i tvoje će potomstvo moći prebrojiti.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 13, 17, 'Na noge! Prođi zemljom uzduž i poprijeko jer ću je tebi predati.\"');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 13, 18, 'Abram digne šatore i dođe pa se naseli kod hrasta Mamre, što je u Hebronu. Ondje podigne žrtvenik Jahvi.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 14, 1, 'Kad Amrafel bijaše kralj Šineara, Ariok kralj Elasara, Kedor-Laomer kralj Elama, Tidal kralj Gojima,');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 14, 2, 'povedoše oni rat protiv Bere, kralja Sodome, Birše, kralja Gomore, Šinaba, kralja Adme, Šemebera, kralja Sebojima, i protiv kralja u Beli, to jest Soaru.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 14, 3, 'I vojske se sliju u dolinu Sidim, gdje je danas Slano more.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 14, 4, 'Dvanaest su godina služili Kedor-Laomera, ali trinaeste godine dignu se na ustanak.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 14, 5, 'U četrnaestoj godini digne se Kedor-Laomer i kraljevi koji su bili s njim te potuku Refaimce u Ašterot Karnajimu, Zuzijce u Hamu, Emijce na ravnici Kirjatajimu,');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 14, 6, 'Horijce u brdskom kraju Seiru, blizu El Parana, koji je uz pustinju.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 14, 7, 'Onda se povuku natrag i stignu u En Mišpat, to jest Kadeš, i pokore sve krajeve Amalečana i Amorejaca, koji su nastavali Haseson Tamar.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 14, 8, 'Zatim istupi kralj Sodome, kralj Gomore, kralj Adme, kralj Sebojima i kralj Bele, odnosno Soara, te zapodjenu borbu protiv onih u dolini Sidimu:');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 14, 9, 'Kedor-Laomera, kralja Elama, Tidala, kralja Gojima, Amrafela, kralja Šineara, Arioka, kralja Elasara - četiri kralja protiv pet.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 14, 10, 'Dolina Sidim bila je puna provalija s paklinom, pa kraljevi Sodome i Gomore, na bijegu, u njih poskaču, a ostali izmaknu u planine.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 14, 11, 'Pobjednici pokupe sve blago po Sodomi i Gomori i svu hranu pa odu.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 14, 12, 'Pograbe i Lota, Abramova bratića - i on je živio u Sodomi - i njegovo blago pa otiđu.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 14, 13, 'A bjegunac neki - rođak Eškola i Anera, Abramovih saveznika - donese vijest Abramu Hebrejcu dok je boravio kod hrasta Amorejske Mamre.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 14, 14, 'Kad je Abram čuo da mu je bratić zarobljen, skupi svoju momčad - rođenu u njegovu domu - njih trista osamnaest, pa pođe u potjeru do Dana.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 14, 15, 'Podijeli svoje momke u dvije čete, napadne noću te one potuče. Progonio ih je do Hobe, sjeverno od Damaska.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 14, 16, 'Povrati sve blago, svoga bratića Lota i njegovo blago, žene i ostali svijet.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 14, 17, 'Pošto se vratio, porazivši Kedor-Laomera i kraljeve koji su bili s njim, u susret mu, u dolinu Šave, to jest u Kraljev dol, iziđe kralj Sodome.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 14, 18, 'A Melkisedek, kralj Šalema, iznese kruha i vina. On je bio svećenik Boga Svevišnjega.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 14, 19, 'Blagoslovi ga govoreći: \"Od Boga Svevišnjega, Stvoritelja neba i zemlje, neka je Abramu blagoslov!');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 14, 20, 'I Svevišnji Bog, što ti u ruke preda neprijatelje, hvaljen bio!\" Abram mu dade desetinu od svega.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 14, 21, 'Tada kralj Sodome reče Abramu: \"Meni daj ljude, a dobra uzmi sebi!\"');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 14, 22, 'Abram odgovori kralju Sodome: \"Ruku uzdižem pred Jahvom, Svevišnjim Stvoriteljem neba i zemlje,');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 14, 23, 'da neću uzeti ni končića, ni remena od obuće, niti išta što je tvoje da ne kažeš: na meni se Abram obogatio.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 14, 24, 'Ne, meni ništa, osim što su moji momci upotrijebili; i dio za momčad što je sa mnom išla: Aner, Eškol i Mamre, oni neka uzmu svoj dio.\"');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 15, 1, 'Poslije tih događaja Jahve uputi Abramu riječ u ukazanju: \"Ne boj se, Abrame, ja sam ti zaštita; a nagrada tvoja bit će vrlo velika!\"');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 15, 2, 'Abram odgovori: \"Gospodine moj, Jahve, čemu mi tvoji darovi kad ostajem bez poroda; kad je mojoj kući nasljednik Eliezer Damaščanin?');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 15, 3, 'Kako mi nisi dao potomstva - nastavi Abram - jedan će, eto, od mojih ukućana postati moj baštinik.\"');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 15, 4, 'Ali mu Jahve opet uputi riječ: \"Taj neće biti tvoj baštinik, nego će ti baštinik biti tvoj potomak.\"');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 15, 5, 'Izvede ga van i reče: \"Pogledaj na nebo i zvijezde prebroj ako ih možeš prebrojiti.\" A onda doda: \"Toliko će biti tvoje potomstvo.\"');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 15, 6, 'Abram povjerova Jahvi, i on mu to uračuna u pravednost.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 15, 7, 'Tada mu on reče: \"Ja sam Jahve koji sam te odveo iz Ura Kaldejskoga da ti predam ovu zemlju u posjed.\"');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 15, 8, 'A on odvrati: \"Gospodine moj, Jahve, kako ću ja doznati da ću je zaposjesti?\"');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 15, 9, 'Odgovori mu: \"Prinesi mi junicu od tri godine, kozu od tri godine, ovna od tri godine, jednu grlicu i jednog golubića.\"');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 15, 10, 'Sve mu to donese, rasiječe na pole i metnu sve pole jednu prema drugoj; ptica nije rasijecao.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 15, 11, 'Ptice grabežljivice obarale se na leševe, ali ih je Abram rastjerivao.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 15, 12, 'Kad je sunce bilo pri zalazu, dubok san obuzme Abrama, a onda se na nj spusti gust mrak pun jeze.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 15, 13, 'Tada Bog reče Abramu: \"Dobro znaj da će tvoji potomci biti stranci u tuđoj zemlji; robovat će i biti tlačeni četiri stotine godina,');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 15, 14, 'ali narodu kojem budu služili ja ću suditi; i konačno će izići s velikim blagom.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 15, 15, 'A ti ćeš k ocima svojim u miru poći, u sretnoj starosti bit ćeš sahranjen.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 15, 16, 'Oni će se ovamo vratiti za četvrtog naraštaja, jer mjera se zlodjela amorejskih još nije navršila.\"');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 15, 17, 'Kad je sunce zašlo i pao gust mrak, pojavi se zadimljen žeravnjak i goruća zublja te prođu između onih dijelova.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 15, 18, 'Toga je dana Jahve sklopio Savez s Abramom rekavši: \"Potomstvu tvojemu dajem zemlju ovu od Rijeke u Egiptu do Velike rijeke, rijeke Eufrata:');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 15, 19, 'Kenijce, Kenižane, Kadmonce,');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 15, 20, 'Hetite, Perižane, Refaimce,');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 15, 21, 'Amorejce, Kanaance, Girgašane, Jebusejce.\"');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 16, 1, 'Abramova žena Saraja nije mu rađala djece. A imaše ona sluškinju Egipćanku - zvala se Hagara.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 16, 2, 'I reče Saraja Abramu: \"Vidiš, Jahve me učinio nerotkinjom. Hajde k mojoj sluškinji, možda ću imati djece.\" Abram posluša riječ Sarajinu.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 16, 3, 'Tako, pošto je Abram proboravio deset godina u zemlji kanaanskoj, njegova žena Saraja uzme Hagaru, Egipćanku, sluškinju svoju, pa je dade svome mužu Abramu za ženu.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 16, 4, 'Uđe on k Hagari te ona zače. A kad je vidjela da je začela, s prezirom je gledala na svoju gospodaricu.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 16, 5, 'Tada reče Saraja Abramu: \"Nepravda što se meni nanosi tvoja je krivnja! Prepustila sam svoju sluškinju tvome zagrljaju, ali otkako opazi da je zanijela, s prezirom na me gleda. Jahve sudio i meni i tebi!\"');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 16, 6, 'Nato Abram odvrati Saraji: \"Tvoja je sluškinja u tvojoj ruci: kako ti se čini da je dobro, tako prema njoj postupi!\" Saraja postupi prema njoj tako loše da ona od nje pobježe.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 16, 7, 'Anđeo Jahvin nađe je kod izvora u pustinji - uz vrelo što je na putu prema Šuru -');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 16, 8, 'pa je zapita: \"Hagaro, sluškinjo Sarajina, odakle dolaziš i kamo ideš?\" \"Bježim, evo, od svoje gospodarice Saraje\", odgovori ona.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 16, 9, 'Nato joj anđeo Jahvin reče: \"Vrati se svojoj gospodarici i pokori joj se!\"');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 16, 10, 'Još joj reče anđeo Jahvin: \"Tvoje ću potomstvo silno umnožiti; od mnoštva se neće moći ni prebrojiti.\"');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 16, 11, 'Dalje joj je anđeo Jahvin rekao: \"Gle, zanijela si i rodit ćeš sina. Nadjeni mu ime Jišmael, jer Jahve ču jad tvoj.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 16, 12, 'On će biti kao divlje magare: ruka će se njegova dizati na svakoga i svačija ruka na njega; i pred licem sve mu braće on će stan sebi podići.\"');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 16, 13, 'A Jahvu koji joj govoraše nazva: \"Ti si El Roi - Svevid Bog\", jer - reče ona - \"vidjeh Boga i nakon viđenja - još živim!\"');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 16, 14, 'Stoga se taj zdenac zove Beer Lahaj Roi - Zdenac životvornog Svevida, a eno ga između Kadeša i Bereda.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 16, 15, 'Rodi Hagara Abramu sina, a Abram sinu što mu ga rodi Hagara nadjene ime Jišmael.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 16, 16, 'Abramu je bilo osamdeset i šest godina kad mu je Hagara rodila Jišmaela.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 17, 1, 'Kad je Abramu bilo devedeset i devet godina, ukaza mu se Jahve pa mu reče: \"Ja sam El Šadaj - Bog Svesilni, Mojim hodi putem i neporočan budi.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 17, 2, 'A Savez svoj ja sklapam s tobom i silno ću te razmnožiti.\"');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 17, 3, 'Abram pade ničice dok mu Bog govoraše dalje:');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 17, 4, '\"A ovo je Savez moj s tobom: postat ćeš ocem mnogim narodima;');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 17, 5, 'i nećeš se više zvati Abram - već Abraham će ti ime biti, jer naroda mnogih ocem ja te postavljam.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 17, 6, 'Silno ću te rodnim učiniti; narode ću iz tebe izvesti; i kraljevi će od tebe izaći.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 17, 7, 'Savez svoj sklapam između sebe i tebe i tvoga potomstva poslije tebe - Savez svoj za vjekove: ja ću biti Bogom tvojim i tvoga potomstva poslije tebe.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 17, 8, 'Tebi i tvome potomstvu poslije tebe dajem zemlju u kojoj boraviš kao pridošlica - svu zemlju kanaansku - u vjekovni posjed; a ja ću biti njihov Bog.\"');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 17, 9, 'Još reče Bog Abrahamu: \"A ti Savez čuvaj moj - ti i tvoje potomstvo poslije tebe u sve vijeke.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 17, 10, 'A ovo je Savez moj s tobom i tvojim potomstvom poslije tebe koji ćeš vršiti: svako muško među vama neka bude obrezano.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 17, 11, 'Obrezujte se, i to neka bude znak Saveza između mene i vas.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 17, 12, 'Svako muško među vama, kroz vaša pokoljenja, kad mu se navrši osam dana, neka bude obrezano; i rob, rođen u vašem domu, i onaj što bude kupljen od stranca, koji ne bude od vaše krvi.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 17, 13, 'Da, i rob rođen u tvome domu ili za novac kupljen mora se obrezati! Tako će moj Savez na vašem tijelu ostati vječnim Savezom.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 17, 14, 'Muško koje se ne bi obrezalo neka se odstrani od svoga roda: takav je prekršio moj Savez.\"');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 17, 15, 'Još reče Bog Abrahamu: \"Tvojoj ženi Saraji nije više ime Saraja: Sara će joj ime biti.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 17, 16, 'Nju ću ja blagosloviti i od nje ti dati sina; blagoslov ću na nju izliti te će se narodi od nje razviti; kraljevi će narodima od nje poteći.\"');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 17, 17, 'Abraham pade ničice pa se nasmija i reče u sebi: \"Onome komu je stotinu godina, zar se može roditi dijete? Zar će Sara u devedesetoj rod rađati!\"');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 17, 18, 'Abraham reče Bogu: \"Neka tvojom milošću Jišmael poživi!\"');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 17, 19, 'A Bog reče: \"Ipak će ti tvoja žena Sara roditi sina; nadjeni mu ime Izak. Savez svoj s njime ću sklopiti, Savez vječni s njime i s njegovim potomstvom poslije njega.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 17, 20, 'I za Jišmaela uslišah te. Evo ga blagoslivljam: rodnim ću ga učiniti i silno ga razmnožiti; dvanaest će knezova od njega postati i u velik će narod izrasti.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 17, 21, 'Ali ću držati svoj Savez s Izakom, koga će ti roditi Sara dogodine u ovo doba.\"');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 17, 22, 'Kad je završio razgovor s njim, od Abrahama Bog se podiže.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 17, 23, 'Uzme zatim Abraham svoga sina Jišmaela i sve robove koji su bili rođeni u njegovu domu i sve koje je kupio novcem - sve muške ukućane - pa ih toga istog dana obreže, kako mu je Bog rekao.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 17, 24, 'Abrahamu bijaše devedeset i devet godina kad se obrezao,');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 17, 25, 'a njegovu sinu Jišmaelu bijaše trinaest godina kad ga obreza.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 17, 26, 'Tako su toga istog dana bili obrezani Abraham i njegov sin Jišmael;');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 17, 27, 'i svi muškarci njegova doma, rođeni u njegovoj kući ili za novac kupljeni od stranca - svi s njim bijahu obrezani.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 18, 1, 'Jahve mu se ukaza kod hrasta Mamre dok je on sjedio na ulazu u šator za dnevne žege.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 18, 2, 'Podigavši oči, opazi tri čovjeka gdje stoje nedaleko od njega. Čim ih spazi, potrča s ulaza šatora njima u susret. Pade ničice na zemlju');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 18, 3, 'pa reče: \"Gospodine moj, ako sam stekao milost u tvojim očima, nemoj mimoići svoga sluge!');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 18, 4, 'Nek\' se donese malo vode: operite noge i pod stablom otpočinite.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 18, 5, 'Donijet ću kruha da se okrijepite prije nego pođete dalje. TÓa k svome ste sluzi navratili.\" Oni odgovore: \"Dobro, učini kako si rekao!\"');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 18, 6, 'Abraham se požuri u šator k Sari pa joj reče: \"Brzo! Tri mjerice najboljeg brašna! Zamijesi i prevrtu ispeci!\"');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 18, 7, 'Zatim Abraham otrča govedima, uhvati tele, mlado i debelo, i dade ga momku da ga brže zgotovi.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 18, 8, 'Poslije uzme masla, mlijeka i zgotovljeno tele pa stavi pred njih, a sam stajaše pred njima, pod stablom, dok su blagovali.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 18, 9, '\"Gdje ti je žena Sara?\" - zapitaju ga. \"Eno je pod šatorom\", odgovori.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 18, 10, 'Onda on reče: \"Vratit ću se k tebi kad isteče vrijeme trudnoće; a tvoja žena Sara imat će sina.\" Iza njega, na ulazu u šator, Sara je prisluškivala.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 18, 11, 'Abraham i Sara bijahu u odmakloj dobi, ostarjeli. U Sare bijaše prestalo što biva u žena.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 18, 12, 'Zato se u sebi Sara smijala i govorila: \"Pošto sam uvenula, sad da spoznam nasladu? A još mi je i gospodar star!\"');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 18, 13, 'Onda Jahve upita Abrahama: \"A zašto se Sara smijala i govorila: \'Kako ću rod roditi ja starica?\'');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 18, 14, 'Zar je Jahvi išta nemoguće? Navratit ću se k tebi kad isteče vrijeme trudnoće: Sara će imati sina.\"');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 18, 15, 'Sara se napravi nevještom govoreći: \"Nisam se smijala.\" Jer se prestrašila. Ali on reče: \"Jesi, smijala si se!\"');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 18, 16, 'Ljudi ustanu i krenu put Sodome. Abraham pođe s njima da ih isprati.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 18, 17, 'Jahve pomisli: \"Zar da sakrivam od Abrahama što ću učiniti');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 18, 18, 'kad će od Abrahama nastati velik i brojan narod te će se svi narodi zemlje njim blagoslivljati?');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 18, 19, 'Njega sam izlučio zato da pouči svoju djecu i svoju buduću obitelj kako će hoditi putem Jahvinim, radeći što je dobro i pravedno, tako da Jahve mogne ostvariti što je Abrahamu obećao.\"');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 18, 20, 'Onda Jahve nastavi: \"Velika je vika na Sodomu i Gomoru da je njihov grijeh pretežak.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 18, 21, 'Idem dolje da vidim rade li zaista kako veli tužba što je do mene stigla. Želim razvidjeti.\"');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 18, 22, 'Odande ljudi krenu prema Sodomi, dok je Abraham još stajao pred Jahvom.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 18, 23, 'Nato se Abraham primače bliže i reče: \"Hoćeš li iskorijeniti i nevinoga s krivim?');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 18, 24, 'Možda ima pedeset nevinih u gradu. Zar ćeš uništiti mjesto radije nego ga poštedjeti zbog pedeset nevinih koji budu ondje?');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 18, 25, 'Daleko to bilo od tebe da ubijaš nevinoga kao i krivoga, tako da i nevini i krivi prođu jednako! Daleko bilo od tebe! Zar da ni Sudac svega svijeta ne radi pravo?\"');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 18, 26, '\"Ako nađem u gradu Sodomi pedeset nevinih\", odvrati Jahve, \"zbog njih ću poštedjeti cijelo mjesto.\"');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 18, 27, '\"Ja se, evo, usuđujem govoriti Gospodinu\", opet progovori Abraham. - \"Ja, prah i pepeo!');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 18, 28, 'Da slučajno bude nevinih pet manje od pedeset, bi li uništio sav grad zbog tih pet?\" \"Neću ga uništiti ako ih ondje nađem četrdeset i pet\", odgovori.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 18, 29, '\"Ako ih se ondje možda nađe samo četrdeset?\" - opet će Abraham. \"Neću to učiniti zbog četrdesetorice\", odgovori.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 18, 30, '\"Neka se Gospodin ne ljuti ako nastavim. Ako ih se ondje nađe možda samo trideset?\" - opet će on. \"Neću to učiniti\", odgovori, \"ako ih ondje nađem samo trideset.\"');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 18, 31, '\"Evo se opet usuđujem govoriti Gospodinu\", nastavi dalje. \"Ako ih se slučajno ondje nađe samo dvadeset?\" \"Neću ga uništiti\", odgovori, \"zbog dvadesetorice.\"');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 18, 32, '\"Neka se Gospodin ne ljuti\", on će opet, \"ako rečem još samo jednom: Ako ih je slučajno ondje samo deset?\" \"Neću ga uništiti zbog njih deset\", odgovori.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 18, 33, 'Kad je Jahve završio razgovor s Abrahamom, ode, a Abraham se vrati u svoje mjesto.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 19, 1, 'Ona dva anđela stignu navečer u Sodomu dok je Lot sjedio na vratima Sodome. Kad ih Lot ugleda, ustade i pođe im u susret. Nakloni se licem do zemlje,');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 19, 2, 'a onda im reče: \"Molim, gospodo, svrnite u kuću svoga sluge da noć provedete i noge operete; a onda možete na put rano.\" A oni rekoše: \"Ne, noć ćemo provesti na trgu.\"');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 19, 3, 'Ali ih on uporno navraćaše, i oni se uvratiše k njemu i uđoše u njegovu kuću. On ih ugosti, ispeče pogaču te blagovaše.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 19, 4, 'Još ne bijahu legli na počinak, kad građani Sodome, mladi i stari, sav narod do posljednjeg čovjeka, opkole kuću.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 19, 5, 'Zovnu Lota pa mu reknu: \"Gdje su ljudi što su noćas došli k tebi? Izvedi nam ih da ih se namilujemo?\"');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 19, 6, 'Lot iziđe k njima na ulaz, a za sobom zatvori vrata.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 19, 7, '\"Braćo moja,\" reče on, \"molim vas, ne činite toga zla!');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 19, 8, 'Imam, evo, dvije kćeri s kojima još čovjek nije imao dodira: njih ću vam izvesti pa činite s njima što želite; samo ovim ljudima nemojte ništa učiniti jer su došli pod sjenu moga krova.\"');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 19, 9, '\"Odstupi odatle!\" - rekoše. - \"Došao kao dotepenac, a za suca se već postavlja. Sad ćemo mi s tobom gore nego s njima.\" I nasrnuše na jadnika Lota i navališe na vrata da ih razbiju.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 19, 10, 'Ali ona dvojica pruže ruke van, povukoše Lota k sebi u kuću i zatvore vrata;');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 19, 11, 'a ljude pred vratima, mlade i stare, zabliješte tako da nisu mogli naći vrata.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 19, 12, 'Onda ona dvojica upitaju Lota: \"Koga još ovdje imaš: sinove i kćeri, sve koje imaš u gradu iz mjesta izvedi!');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 19, 13, 'Jer mi ćemo zatrti ovo mjesto: vika je na njih pred Jahvom postala tolika te nas Jahve posla da ga uništimo.\"');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 19, 14, 'Iziđe Lot da to kaže svojima budućim zetovima koji namjeravahu uzeti njegove kćeri te reče: \"Na noge! Odlazite iz ovog mjesta jer će Jahve uništiti grad!\" Ali je u očima svojih budućih zetova ispao kao da zbija šalu.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 19, 15, 'Kako zora puče, anđeli navale na Lota govoreći: \"Na noge! Uzmi svoju ženu i svoje dvije kćeri koje su ovdje da ne budeš zatrt kaznom grada!\"');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 19, 16, 'Ali on oklijevaše. Zato ga oni uzeše za ruku, a tako i njegovu ženu i njegove dvije kćeri i - po smilovanju Jahvinu nad njim - odvedoše ih i ostaviše izvan grada.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 19, 17, 'Kad ih izvedoše u polje, jedan progovori: \"Bježi da život spasiš! Ne obaziri se niti se igdje u ravnici zaustavljaj! Bježi u brdo da ne budeš zatrt!\"');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 19, 18, 'Ali Lot odvrati: \"Nemoj, gospodine!');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 19, 19, 'Nego ako je tvoj sluga našao milost u tvojim očima - a toliko milosrđe već si mi iskazao spasivši mi život - ja ne mogu pobjeći u brdo a da me nesreća ne snađe i ne poginem.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 19, 20, 'Eno onamo grada; dosta je blizu da u nj pobjegnem, a mjesto je tako malo. Daj da onamo bježim - mjesto je zbilja maleno - daj da život spasim!\"');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 19, 21, 'Odgovori mu: \"Uslišat ću ti i tu molbu i neću zatrti grada o kojemu govoriš.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 19, 22, 'Brzo! Bježi onamo, jer ne mogu ništa činiti dok ti onamo ne stigneš.\" Zato se onaj grad zove Soar.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 19, 23, 'Kako je sunce na zemlju izlazilo i Lot ulazio u Soar,');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 19, 24, 'Jahve zapljušti s neba na Sodomu i Gomoru sumpornim ognjem');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 19, 25, 'i uništi one gradove i svu onu ravnicu, sve žitelje gradske i sve raslinstvo na zemlji.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 19, 26, 'A Lotova se žena obazre i pretvori se u stup soli.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 19, 27, 'Sutradan u rano jutro Abraham se požuri na mjesto gdje je stajao pred Jahvom,');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 19, 28, 'upravi pogled prema Sodomi i Gomori i svoj ravnici u daljini: i vidje kako se diže dim nad zemljom kao dim kakve klačine.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 19, 29, 'Tako se Bog, dok je zatirao gradove u ravnici u kojima je Lot boravio, sjetio Abrahama i uklonio Lota ispred propasti.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 19, 30, 'Lot se bojao boraviti u Soaru, pa sa svoje dvije kćeri ode gore iz Soara i nastani se u brdu. On i njegove dvije kćeri živjeli su u pećini.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 19, 31, 'Starija reče mlađoj: \"Otac nam ostarje, a muža na zemlji nema da bude s nama, kako je običaj po svem svijetu.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 19, 32, 'Hajdemo oca opiti vinom, pa s njime leći: tako ćemo s ocem sačuvati potomstvo.\"');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 19, 33, 'One noći opiju oca vinom, i starija ode te legne sa svojim ocem, a on nije znao kad je legla ni kad je ustala.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 19, 34, 'Sutradan starija reče mlađoj: \"Sinoć sam, eto, ležala ja s našim ocem; napojimo ga vinom i noćas, pa idi ti i s njim lezi: tako ćemo ocu sačuvati potomstvo.\"');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 19, 35, 'Opiju oca vinom i one noći te mlađa ode i s njim legne, a on nije znao kad je legla ni kad je ustala.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 19, 36, 'Tako obje Lotove kćeri zanesu s ocem.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 19, 37, 'Starija rodi sina i nadjenu mu ime Moab. On je praotac današnjih Moabaca.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 19, 38, 'I mlađa rodi sina i nadjene mu ime Ben-Ami. On je praotac današnjih Amonaca.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 20, 1, 'Odande Abraham krene u krajeve Negeba i nastani se između Kadeša i Šura. Dok je boravio kao pridošlica u Geraru,');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 20, 2, 'rekao je Abraham za svoju ženu Saru da mu je sestra. I Abimelek, kralj gerarski, uze Saru sebi.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 20, 3, 'Ali Bog dođe Abimeleku noću u snu te mu reče: \"Zbog žene koju si uzeo moraš umrijeti, jer je ona žena udata.\"');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 20, 4, 'A nije se Abimelek k njoj približavao. Zato reče: \"Gospodine, zar ćeš pravednika pogubiti?');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 20, 5, 'Zar mi on nije rekao: \'Ona mi je sestra.\' A ona mi je sama rekla: \'On je moj brat.\' Čiste sam savjesti i neokaljanih ruku ovo učinio.\"');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 20, 6, 'Bog mu odvrati u snu: \"Znam da si to učinio čiste savjesti; i ja sam te zadržavao da protiv mene ne griješiš; i nisam dopuštao da je dotakneš.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 20, 7, 'Sada vrati čovjeku ženu njegovu; prorok je on; molit će se za tebe da ostaneš na životu. Ako je ne vratiš, znaj da ćeš umrijeti, ti i svi tvoji.\"');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 20, 8, 'Rano ujutro Abimelek ustane, sazove sve svoje sluge i kaže im sve što je bilo, a ljudi se veoma uplaše.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 20, 9, 'Potom Abimelek dozva Abrahama te mu reče: \"Što si nam učinio! Čime sam se ja ogriješio prema tebi da izložiš mene i moje kraljevstvo velikoj grehoti? Ponio si se prema meni kako ne valja.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 20, 10, 'Što si, dakle na umu imao\", upita dalje Abimelek, \"kad si tako radio?\"');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 20, 11, 'Abraham uzvrati: \"Zbilja sam držao da nema Božjeg straha u ovome mjestu, pa će me ljudi ubiti zbog moje žene.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 20, 12, 'A onda, ona je uistinu moja sestra: kći je moga oca, iako ne i moje majke, pa je pošla za me.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 20, 13, 'A kad me Bog udaljio od doma očeva, rekoh joj: Ovu mi uslugu učini: kamo god dođemo, reci o meni da sam ti brat.\"');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 20, 14, 'Abimelek uzme ovaca i goveda, sluga i sluškinja pa ih dade Abrahamu; vrati mu i njegovu ženu Saru.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 20, 15, 'Abimelek zatim reče: \"Evo, moja ti je zemlja otvorena. Nastani se gdje ti se svidi!\"');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 20, 16, 'A Sari reče: \"Evo tisuću srebrnika što ih dajem tvome bratu: neka ti budu koprenom pred očima sviju što su s tobom. Ti si svakako opravdana.\"');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 20, 17, 'Abraham se pomoli Bogu, i Bog ozdravi Abimeleka, njegovu ženu i njegove sluškinje, tako te opet mogahu rađati.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 20, 18, 'Jer Jahve bijaše zbog Sare, Abrahamove žene, zatvorio svaku utrobu u domu Abimelekovu.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 21, 1, 'Jahve se sjeti Sare kako je rekao i učini joj kako je obećao:');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 21, 2, 'Sara zače i rodi Abrahamu sina u njegovoj starosti - u vrijeme koje je Bog označio.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 21, 3, 'Abraham nadjene ime Izak svome sinu što mu ga Sara rodi.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 21, 4, 'I poslije osam dana obreza Abraham svoga sina Izaka, kako mu je Bog naredio.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 21, 5, 'Abrahamu bijaše stotinu godina kad mu se rodio sin Izak.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 21, 6, 'Sara reče: \"Dade mi Bog da se nasmijem, i tko god to čuje nasmijat će mi se.\"');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 21, 7, 'Još doda: \"Tko bi ikad rekao Abrahamu: djecu će ti Sara dojiti! Ipak sina mu rodih u starosti\".');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 21, 8, 'Dijete je raslo i bilo od sise odbijeno. A u dan u koji Izak bijaše od sise odbijen Abraham priredi veliku gozbu.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 21, 9, 'Jednom opazi Sara gdje se sin koga je Egipćanka Hagara Abrahamu rodila igra s njezinim sinom Izakom,');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 21, 10, 'pa reče Abrahamu: \"Otjeraj tu sluškinju i njezina sina, jer sin sluškinje ne smije biti baštinik s mojim sinom - s Izakom!\"');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 21, 11, 'To je Abrahamu bilo nemilo, jer je i Jišmael bio njegov sin.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 21, 12, 'Ali Bog reče Abrahamu: \"Nemoj se uznemirivati zbog dječaka i zbog svoje sluškinje; sve što ti kaže Sara poslušaj, jer će Izakovo potomstvo tebi ovjekovječiti ime.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 21, 13, 'I od sina tvoje sluškinje podići ću velik narod, jer je tvoj potomak.\"');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 21, 14, 'Rano ujutro Abraham uze kruha i mješinicu vode pa dade Hagari; stavi to na njezina ramena, zajedno s dječakom, te je otpusti. Vrludala je amo-tamo po pustinji Beer Šebe.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 21, 15, 'Potrošivši vodu iz mješinice, ostavi dijete pod jednim grmom,');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 21, 16, 'a sama ode i sjede nasuprot, daleko koliko luk može dobaciti. Govorila je u sebi: \"Neću da vidim kako dijete umire.\" Sjedeći tako, udari u jecanje.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 21, 17, 'Bog ču plač dječaka te anđeo Božji zovne s neba Hagaru i reče joj: \"Što ti je, Hagaro? Ne boj se! Jer je Bog čuo plač dječaka u njegovoj nevolji.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 21, 18, 'Na noge! Digni dječaka i utješi ga, jer od njega ću podići velik narod.\"');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 21, 19, 'Tada joj Bog otvori oči pa ona opazi studenac. Ode i napuni vodom mješinicu pa napoji dječaka.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 21, 20, 'Bog je bio s dječakom te je rastao i odrastao. Živio je u pustinji te postao vješt u strijeljanju iz luka.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 21, 21, 'Dom mu bijaše u pustinji Paranu; a njegova mu majka dobavi ženu iz zemlje egipatske.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 21, 22, 'U to vrijeme Abimelek - koga je pratio Fikol, zapovjednik njegove vojske - reče Abrahamu: \"Bog je s tobom u svemu što radiš.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 21, 23, 'Stoga mi se ovdje i sada zakuni Bogom da nećeš varati ni mene ni moju rodbinu i prijatelje nego da ćeš se prema meni i prema zemlji u kojoj sad boraviš ponašati pošteno, kao što sam se ja prema tebi ponio.\"');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 21, 24, '\"Kunem se\", odgovori Abraham.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 21, 25, 'Onda Abraham prekori Abimeleka zbog zdenca vode što su ga Abimelekove sluge bile prisvojile.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 21, 26, 'A Abimelek reče: \"Ne znam tko je to učinio; ni ti me nisi o tome obavijestio, niti sam ja o tome čuo, osim danas.\"');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 21, 27, 'Abraham uzme ovaca i goveda pa ih dade Abimeleku te njih dvojica sklope savez.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 21, 28, 'Potom Abraham razluči napose sedam janjaca od stada.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 21, 29, 'Nato Abimelek zapita Abrahama: \"Što znači ovih sedam janjaca koje si na stranu stavio?\"');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 21, 30, 'A on odgovori: \"Primi ovih sedam janjaca iz moje ruke da mi bude dokazom da sam ja iskopao ovaj zdenac.\"');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 21, 31, 'Zato se ono mjesto nazvalo Beer Šeba; jer se njih dvojica ondje zakleše.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 21, 32, 'Pošto su sklopili savez kod Beer Šebe, Abimelek i zapovjednik njegove vojske Fikol odu i vrate se u zemlju Filistejaca.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 21, 33, 'Abraham zasadi kod Beer Šebe tamarisku i ondje zazove ime Jahve - Boga Vječnoga.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 21, 34, 'Dugo je vremena Abraham proveo u zemlji filistejskoj kao pridošlica.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 22, 1, 'Poslije tih događaja Bog stavi Abrahama na kušnju. Zovnu ga: \"Abrahame!\" On odgovori: \"Evo me!\"');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 22, 2, 'Bog nastavi: \"Uzmi svoga sina, jedinca svoga Izaka koga ljubiš, i pođi u krajinu Moriju pa ga ondje prinesi kao žrtvu paljenicu na brdu koje ću ti pokazati.\"');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 22, 3, 'Ujutro Abraham podrani, osamari magarca, sa sobom povede dvojicu svojih slugu i svog sina Izaka, pošto je prije nacijepao drva za žrtvu paljenicu, i uputi se na mjesto koje mu je Bog označio.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 22, 4, 'Treći dan Abraham podigne oči i opazi mjesto izdaleka.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 22, 5, 'Abraham onda reče slugama: \"Vi ostanite ovdje uz magarca, a ja i dječak odosmo gore da se poklonimo, pa ćemo se vratiti k vama\".');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 22, 6, 'Abraham uzme drva za žrtvu paljenicu, stavi ih na sina Izaka, a u svoju ruku uzme kremen i nož. Tako pođu obojica zajedno.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 22, 7, 'Onda Izak reče svome ocu Abrahamu: \"Oče!\" \"Evo me, sine!\" - javi se on. \"Evo kremena i drva,\" opet će sin, \"ali gdje je janje za žrtvu paljenicu?\"');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 22, 8, '\"Bog će već providjeti janje za žrtvu paljenicu, sine moj!\" - odgovori Abraham. I nastave put.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 22, 9, 'Stignu na mjesto o kojemu je Bog govorio. Ondje Abraham podigne žrtvenik, naslaže drva, sveže svog sina Izaka i položi ga po drvima na žrtvenik.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 22, 10, 'Pruži sad Abraham ruku i uzme nož da zakolje svog sina.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 22, 11, 'Uto ga zovne s neba anđeo Jahvin i poviče: \"Abrahame! Abrahame!\" \"Evo me!\" - odgovori on.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 22, 12, '\"Ne spuštaj ruku na dječaka\", reče, \"niti mu što čini! Sad, evo, znam da se Boga bojiš, jer nisi uskratio ni svog sina, jedinca svoga.\"');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 22, 13, 'Podiže Abraham oči i pogleda, i gle - za njim ovan, rogovima se zapleo u grmu. Tako Abraham ode, uzme ovna i prinese ga za žrtvu paljenicu mjesto svoga sina.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 22, 14, 'Onome mjestu Abraham dade ime \"Jahve proviđa\". Zato se danas veli: \"Na brdu Jahvina proviđanja.\"');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 22, 15, 'Anđeo Jahvin zovne Abrahama s neba drugi put');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 22, 16, 'i reče: \"Kunem se samim sobom, izjavljuje Jahve: Kad si to učinio i nisi mi uskratio svog jedinca sina,');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 22, 17, 'svoj ću blagoslov na te izliti i učiniti tvoje potomstvo brojnim poput zvijezda na nebu i pijeska na obali morskoj! A tvoji će potomci osvajati vrata svojih neprijatelja.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 22, 18, 'Budući da si poslušao moju zapovijed, svi će se narodi zemlje blagoslivljati tvojim potomstvom.\"');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 22, 19, 'Zatim se Abraham vrati k svojim slugama pa se zajedno upute u Beer Šebu. U Beer Šebi se Abraham nastani.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 22, 20, 'Poslije tih događaja obavijeste Abrahama: \"I tvome bratu Nahoru Milka je porodila djecu:');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 22, 21, 'njegova prvorođenca Usa, brata mu Buza i Kemuela - oca Aramova,');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 22, 22, 'Keseda, Haza, Pildaša, Jidlafa i Betuela.\"');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 22, 23, 'Betuel je bio otac Rebekin. Njih je osam rodila Milka Nahoru, Abrahamovu bratu.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 22, 24, 'A i njegova suložnica, kojoj bijaše ime Reuma, rodila je Tebaha, Gahama, Tahaša i Maaku.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 23, 1, 'Duljina Sarina života bila je stotinu dvadeset i sedam godina.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 23, 2, 'Sara umrije u Kirjat Arbi, to jest u Hebronu, u zemlji kanaanskoj; i Abraham uđe u žalost za Sarom i naricaše za njom.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 23, 3, 'Potom se Abraham digne ispred svoje pokojnice te prozbori sinovima Hetovim:');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 23, 4, '\"Premda sam ja među vama doseljeni stranac, prodajte mi zemljište za grob među vama, tako da mogu iznijeti svoju pokojnicu i sahraniti je.\"');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 23, 5, 'A sinovi Hetovi odgovore Abrahamu:');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 23, 6, '\"Gospodine, saslušaj nas! Ti si izabranik Božji u našoj sredini. Pokopaj svoju pokojnicu u našem najbiranijem grobu. Nitko ti od nas neće odbiti svoga groba da mogneš sahraniti svoju pokojnicu.\"');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 23, 7, 'Nato se Abraham diže pa se mještanima, sinovima Hetovim, duboko pokloni');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 23, 8, 'te im reče: \"Ako se slažete da svoju pokojnicu uklonim i sahranim, čujte me: zauzmite se za me kod Efrona, sina Soharova,');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 23, 9, 'da mi proda spilju Makpelu što njemu pripada a nalazi se na kraju njegova posjeda; neka mi je za punu cijenu, u vašoj nazočnosti, proda u vlasništvo za sahranjivanje.\"');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 23, 10, 'A Efron je sjedio sa sinovima Hetovim. Potom Efron, Hetit, odgovori Abrahamu da ga čuju sinovi Hetovi svojim ušima - svi koji su sjedili u vijeću onoga grada:');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 23, 11, '\"Ne, moj gospodine! Saslušaj mene! Ja tebi dajem poljanu i spilju što je na njoj; darujem ti to pred sinovima svoga naroda. Sahrani svoju pokojnicu.\"');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 23, 12, 'Abraham se duboko nakloni mještanima,');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 23, 13, 'a onda progovori Efronu da mještani čuju na svoje uši: \"Ded me samo poslušaj! Dajem ti cijenu za poljanu; primi je od mene da ondje mogu sahraniti svoju pokojnicu!\"');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 23, 14, 'Efron odgovori Abrahamu:');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 23, 15, '\"Čuj me, moj gospodine: zemljište u vrijednosti od četiri stotine srebrnika, što je to tebi i meni! Sahrani, dakle, svoju pokojnicu!\"');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 23, 16, 'Abraham se složi s Efronom; isplati Abraham Efronu novac što ga je spomenuo tako da su na svoje uši čuli sinovi Hetovi - četiri stotine srebrnika trgovačke mjere.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 23, 17, 'I tako Efronova poljana u Makpeli nasuprot Mamri - poljana, spilja i sva stabla što su bila na poljani -');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 23, 18, 'prijeđe u vlasništvo Abrahamovo u nazočnosti sinova Hetovih, sviju koji su sjedili u vijeću svoga grada.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 23, 19, 'A onda Abraham sahrani svoju ženu Saru u spilji na poljani Makpeli nasuprot Mamri - danas Hebronu - u zemlji kanaanskoj.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 23, 20, 'Tako je poljana i spilja na njoj prešla od sinova Hetovih u vlasništvo Abrahamovo za sahranjivanje.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 24, 1, 'Abraham bijaše već ostario, zašao u godine, Jahve je Abrahama blagoslovio u svemu.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 24, 2, 'Abraham prozbori svome najstarijem sluzi u kući, pod čijom je upravom bilo sve njegovo: \"Stavi svoju ruku pod moje stegno');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 24, 3, 'da te zakunem Jahvom, Bogom neba i Bogom zemlje, da mome sinu nećeš nabaviti za ženu ni jednu od kćeri Kanaanaca, među kojima boravim,');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 24, 4, 'nego ćeš otići u moj rodni kraj i dobaviti ženu mom sinu Izaku.\"');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 24, 5, 'A sluga mu reče: \"A što ako žena ne htjedne za mnom ići u ovu zemlju? Hoću li ja onda odvesti tvoga sina u zemlju iz koje si ti došao?\"');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 24, 6, 'Abraham mu odgovori: \"Dobro pripazi da onamo ne vodiš moga sina!');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 24, 7, 'Jahve, Bog nebesa, koji me odveo iz kuće moga oca i rodnog kraja i koji mi je pod zakletvom obećao: \'Tvome ću potomstvu dati ovu zemlju\', pred tobom će poslati svog anđela, i odande ćeš ti dovesti ženu mome sinu.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 24, 8, 'A ako žena ne bude htjela za tobom poći, ti ćeš biti oslobođen od ove moje zakletve; ali moga sina onamo ne vodi!\"');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 24, 9, 'Tako sluga stavi svoju ruku pod stegno Abrahamu, svom gospodaru, te mu se zakune.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 24, 10, 'Sluga opremi deset gospodarevih deva, ponese sa sobom svakog blaga svoga gospodara pa se zaputi u Aram Naharajim, u Nahorov grad.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 24, 11, 'Pusti deve da poliježu izvan grada, pokraj studenca. Bijaše večer, kad žene izlaze da crpu vodu.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 24, 12, 'Onda reče: \"Oh, Jahve, Bože moga gospodara Abrahama, molim te, iziđi mi danas u susret i mome gospodaru Abrahamu milost iskaži!');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 24, 13, 'Evo me kraj studenca, a kćeri onih iz grada dolaze crpsti vodu;');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 24, 14, 'pa neka djevojka kojoj ja rečem: \'Molim te, spusti svoj vrč da se napijem\', a ona odgovori: \'Pij! I deve ću ti napojiti\', bude ona koju si odredio za svoga slugu Izaka. Tako ću saznati da si iskazao milost mome gospodaru.\"');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 24, 15, 'Tek što on izreče svoje, gle, dođe Rebeka, kći Betuelova; taj Betuel bijaše sin Milke, žene Abrahamova brata Nahora. Dođe ona s krčagom na ramenu.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 24, 16, 'Djevojka je bila krasna, djevica koju muškarac nije dirnuo. Siđe ona k vrelu, napuni krčag i eto je opet gore.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 24, 17, 'Sluga joj potrča u susret i reče: \"Daj mi malo vode iz svog vrča!\"');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 24, 18, '\"Pij, gospodine!\" - odgovori ona. Brzo spusti krčag na ruku i dade mu piti.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 24, 19, 'Kad je njega napojila, reče: \"Nalit ću i tvojim devama da se napoje.\"');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 24, 20, 'Izlivši brzo krčag u korito, otrča natrag zdencu da ponovo zahvaća, i tako nali svim njegovim devama.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 24, 21, 'Čovjek ju je šutke motrio ne bi li saznao je li Jahve njegov put uspješno priveo kraju ili nije.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 24, 22, 'Kad su deve prestale piti, čovjek izvadi viticu od zlata, tešku pol šekela, i stavi je na njezine nosnice, a na ruke joj stavi dvije zlatne narukvice, teške deset šekela.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 24, 23, 'Zatim reče: \"Kaži mi čija si kći. Ima li u kući tvoga oca mjesta za nas da prenoćimo?\"');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 24, 24, 'Ona mu odgovori: \"Ja sam kći Betuela, koga je Milka rodila Nahoru.\"');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 24, 25, 'Još mu doda: \"Ima slame i p§iće kod nas u obilju, a i mjesta za prenoćište.\"');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 24, 26, 'Čovjek se onda duboko nakloni te iskaže poštovanje Jahvi');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 24, 27, 'i progovori: \"Neka je blagoslovljen Jahve, Bog moga gospodara Abrahama, što nije uskratio svoju ljubav i svoju vjernost mome gospodaru. Mene je Jahve vodio pravim putem, u kuću brata moga gospodara.\"');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 24, 28, 'Djevojka otrča i sve ovo ispripovjedi u kući svoje majke.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 24, 29, 'A Rebeka imala brata komu bijaše ime Laban. Laban se požuri van, k čovjeku kod studenca.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 24, 30, 'Čim je vidio nosnu viticu i narukvice na rukama svoje sestre te čuo kako je njegova sestra Rebeka rekla: \"Ovako mi je čovjek govorio\", on pođe onome koji je još stajao kod deva na studencu.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 24, 31, 'Reče on: \"Hajde unutra, blagoslovljeni od Jahve! Što stojiš vani kad sam ja spremio kuću i mjesto za deve.\"');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 24, 32, 'Tako čovjek uđe u kuću. Rastovare deve i dadu im slame i p§iće, a njemu i ljudima koji su ga pratili donesu vode da operu noge.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 24, 33, 'Ali kad su preda nj stavili hranu, reče: \"Neću jesti dok ne kažem što imam kazati.\" A Laban mu reče: \"Onda kazuj!\"');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 24, 34, '\"Ja sam sluga Abrahamov\", poče on.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 24, 35, '\"Jahve je uvelike blagoslovio moga gospodara te je postao bogat. Nadavao mu je ovaca i goveda, srebra i zlata, sluga i sluškinja, deva i magaradi.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 24, 36, 'Sara, žena moga gospodara, rodi mu sina pošto je ostarjela, i on mu ustupi sve svoje.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 24, 37, 'Potom mene moj gospodar zakune rekavši: \'Nemoj uzeti za ženu mome sinu djevojku Kanaanku, u zemlji u kojoj boravim kao stranac,');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 24, 38, 'nego otiđi k obitelji moga oca, k mojoj rodbini, da nađeš ženu mome sinu.\'');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 24, 39, 'A ja rekoh svome gospodaru: \'A što ako žena za mnom ne pođe?\'');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 24, 40, 'On mi odgovori: \'Jahve, pred čijim sam licem hodio, poslat će s tobom svog anđela i tvoje će putovanje dovesti k cilju, a ti ćeš naći ženu mome sinu od moje rodbine, od obitelji moga oca.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 24, 41, 'Jedino ćeš ovako biti oslobođen moje zakletve: ako dođeš k mojoj rodbini, i oni te odbiju, od moje si zakletve oslobođen.\'');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 24, 42, 'Danas dođoh na studenac i rekoh: \'Jahve, Bože moga gospodara Abrahama, ako si voljan da uspješno završim putovanje što sam ga poduzeo,');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 24, 43, 'ja, evo, stojim kraj studenca, a djevojka koja dođe vodu crpsti i ja joj rečem: Daj mi da se napijem malo vode iz tvog vrča! -');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 24, 44, 'i koja mi kaže: Pij ti, a i tvojim ću devama zahvatiti! - ona neka bude žena koju je Jahve odredio sinu moga gospodara.\'');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 24, 45, 'Tek što sam ja završio govor u sebi, kad se, evo, pojavi Rebeka s vrčem na ramenu; siđe k izvoru i zahvati. Ja joj rekoh: \'Daj mi da se napijem!\'');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 24, 46, 'Ona brzo spusti vrč i odvrati: \'Pij! A napojit ću i tvoje deve.\' Tako sam se ja napio, a ona napoji i moje deve.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 24, 47, 'Pitao sam je: \'Čija si kći?\' Odgovorila je: \'Kći sam Betuela, koga je Nahoru rodila Milka.\' Tada joj stavim viticu na nos a narukvice na ruke.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 24, 48, 'Duboko se naklonim i štovanje Jahvi iskažem te blagoslovim Jahvu, Boga gospodara moga, koji me vodio pravim putem da uzmem kćer brata moga gospodara njegovu sinu.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 24, 49, 'A sad, ako kanite iskazati ljubav i vjernost mome gospodaru, recite mi; ako li ne, to mi kažite, tako da mogu krenuti bilo desno bilo lijevo.\"');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 24, 50, 'Tada odgovore Laban i Betuel: \"Od Jahve to dolazi; mi tu ne možemo reći ni da ni ne.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 24, 51, 'Rebeka je, eto, pred tobom: uzmi je pa idi, neka bude ženom sinu tvoga gospodara, kako je Jahve rekao.\"');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 24, 52, 'Kad Abrahamov sluga ču njihov pristanak, do zemlje se nakloni Jahvi.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 24, 53, 'Sluga zatim izvadi srebrnih i zlatnih predmeta te haljina i dade ih Rebeki, a dade darova i njezinu bratu i majci.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 24, 54, 'Tada jedoše i piše on i ljudi koji su bili s njim i provedoše noć. Kad su ujutro ustali, on reče: \"Pustite me da se vratim svome gospodaru!\"');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 24, 55, 'A njezin brat i majka odgovore: \"Neka djevojka ostane s nama još desetak dana, pa poslije toga pođi!\"');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 24, 56, 'On im reče: \"Ne zadržavajte me kad je Jahve moje putovanje uspješno kraju priveo. Pustite me da se vratim svome gospodaru!\"');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 24, 57, 'Oni odgovore: \"Pozovimo djevojku i upitajmo što ona misli!\"');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 24, 58, 'Dozovu Rebeku pa je upitaju: \"Hoćeš li poći s ovim čovjekom?\" Ona odgovori: \"Hoću.\"');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 24, 59, 'I tako otpreme svoju sestru Rebeku i njezinu dojilju s Abrahamovim slugom i njegovim ljudima.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 24, 60, 'Blagoslove Rebeku i reknu joj: \"Sejo naša, budi mati nebrojenim tisućama, a dušmana svojih vrata potomci ti zaposjeli!\"');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 24, 61, 'Onda se diže Rebeka i njezine dvorkinje, zajahaše deve te pođoše za čovjekom. Tako sluga preuze Rebeku i ode.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 24, 62, 'Izak se vratio iz blizine Beer Lahaj Roja; živio je, naime, u kraju Negeba.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 24, 63, 'U predvečerje iziđe Izak da se poljem prošeta; diže oči i ugleda deve gdje dolaze.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 24, 64, 'Kad Rebeka, podigavši svoje oči, opazi Izaka, sjaha s deve');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 24, 65, 'pa zapita slugu: \"Tko je onaj čovjek što poljem ide nama u susret?\" A sluga odgovori: \"Ono je moj gospodar.\" Nato ona uze koprenu te se pokri.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 24, 66, 'Sluga ispriča Izaku sve što je učinio.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 24, 67, 'Tada Izak uvede Rebeku u svoj šator i uze je sebi za ženu. U ljubavi prema njoj Izak je nalazio utjehu nakon smrti svoje majke.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 25, 1, 'Abraham je sebi uzeo još jednu ženu; zvala se Ketura.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 25, 2, 'Ona mu je rodila Zimrana, Jokšana, Medana, Midjana, Jišbaka i Šuaha.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 25, 3, 'A od Jokšana rodili se Šeba i Dedan. Dedanovi su potomci: Ašurci, Letušci i Leumci.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 25, 4, 'Sinovi su Midjanovi: Efa, Efer, Hanok, Abida i Eldaa. Sve su to potomci Keturini.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 25, 5, 'Abraham prenese sav svoj imutak na Izaka;');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 25, 6, 'a sinovima od svojih suložnica dade Abraham samo darove i još ih za svoga života razašalje po istoku - daleko od svog sina Izaka - u Istočni kraj.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 25, 7, 'Ovo je duljina Abrahamova života što ga je proživio: stotinu sedamdeset i pet godina.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 25, 8, 'Zatim Abraham preminu, umrije u sretnoj dobi - star i pun godina - te bi pridružen svojim precima.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 25, 9, 'Njegovi sinovi, Izak i Jišmael, sahrane ga u spilji Makpeli, na poljani Efrona, sina Hetita Sohara, nasuprot Mamri:');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 25, 10, 'to je poljana što ju je Abraham kupio od Hetovih sinova. Ondje je sahranjen Abraham i njegova žena Sara.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 25, 11, 'Poslije Abrahamove smrti Bog je blagoslivljao njegova sina Izaka. Izak je živio blizu Beer Lahaj Roja.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 25, 12, 'Ovo je povijest Abrahamova sina Jišmaela, koga je Abrahamu rodila Sarina sluškinja, Egipćanka Hagara.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 25, 13, 'A ovo su sinovi Jišmaelovi, svaki po svom imenu i po svom rođenju: Jišmaelov prvenac Nebajot, Kedar, Adbeel, Mibsam,');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 25, 14, 'Mišma, Duma, Masa,');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 25, 15, 'Hadad, Tema, Jetur, Nafiš i Kedma.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 25, 16, 'To su Jišmaelovi sinovi i to su njihova imena prema njihovim naseljima i taborištima: dvanaest poglavica od isto toliko plemena.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 25, 17, 'A ovo je duljina Jišmaelova života: stotinu trideset i sedam godina. Zatim izdahnu; umrije i bi pridružen svojim precima.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 25, 18, 'Potomstvo mu se naselilo od Havile do Šura, koji je na istok Egiptu idući prema Ašuru. Nastaniše se nasuprot svojoj braći.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 25, 19, 'Ovo je povijest Abrahamova sina Izaka: Izak se rodio od Abrahama.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 25, 20, 'Izaku je bilo četrdeset godina kad se oženio Rebekom, kćerkom Aramejca Betuela iz Padan Arama, a sestrom Aramejca Labana.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 25, 21, 'Izak se obrati Jahvi za svoju ženu jer je bila nerotkinja. Jahve ga usliša te njegova žena Rebeka zače.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 25, 22, 'No djeca se u njezinoj utrobi tako sudarala te ona uzviknu: \"Ako je tako, zašto ću živjeti!\" Ode, dakle, da se posavjetuje s Jahvom.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 25, 23, 'I Jahve joj reče: \"Dva su svijeta u utrobi tvojoj; dva će se naroda iz tvog krila odijeliti. Narod će nad narodom gospodovati, stariji će služiti mlađemu.\"');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 25, 24, 'Došlo vrijeme da rodi, kad gle - blizanci u njezinoj utrobi.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 25, 25, 'Pojavi se prvi. Bio je crven; sav runjav kao ogrtač. Stoga mu nadjenuše ime Ezav.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 25, 26, 'Potom se pojavi njegov brat. Rukom se držao Ezavu za petu. Zato mu nadjenuše ime Jakov. Izaku je bilo šezdeset godina kad su oni rođeni.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 25, 27, 'Kad su dječaci odrasli, Ezav postane vješt lovac, čovjek pustare. Jakov je bio čovjek krotak i boravio je u šatorima.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 25, 28, 'Izaku je Ezav bio draži jer je volio divljač, a Rebeka je više voljela Jakova.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 25, 29, 'Jednom Jakov kuhaše jelo. Ezav stigne s polja, gladan.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 25, 30, 'Reče Ezav Jakovu: \"Daj mi toga crvenog variva da pojedem jer sam izgladnio.\" Stoga mu je ime Edom.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 25, 31, 'A Jakov odgovori: \"Ustupi mi prije svoje prvorodstvo!\"');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 25, 32, 'Ezav reče: \"Evo me skoro na smrti; što će mi prvorodstvo!\"');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 25, 33, 'Jakov nastavi: \"Prije mi se zakuni!\" On mu se zakune, i tako proda Jakovu svoje prvorodstvo.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 25, 34, 'Tada Jakov dade Ezavu kruha i čorbe od sočivice. Jeo je i pio, onda se digao i otišao. Tako Ezav pogazi svoje prvorodstvo.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 26, 1, 'U zemlji zavlada glad, različita od prijašnje što je bila za vrijeme Abrahama, pa Izak ode Abimeleku, kralju Filistejaca, u Geraru.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 26, 2, 'Jahve mu se ukaza i reče: \"Ne silazi u Egipat: boravi u zemlji koju ću ti označiti.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 26, 3, 'U ovoj se zemlji nastani, ja ću s tobom biti i blagoslivljati te; tebi i tvome potomstvu dat ću sve ove krajeve, da izvršim zakletvu kojom sam se zakleo tvome ocu Abrahamu.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 26, 4, 'Tvoje ću potomstvo umnožiti kao zvijezde na nebesima i tvome ću potomstvu predati sve ove krajeve, tako da će se tvojim potomstvom blagoslivljati svi narodi zemlje;');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 26, 5, 'a to zato što je Abraham slušao moj glas i pokoravao se mojim zapovijedima, mojim zakonima i odredbama!\"');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 26, 6, 'Tako Izak ostane u Geraru.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 26, 7, 'Kad su ga mještani pitali o njegovoj ženi, reče: \"Ona mi je sestra.\" Bojao se reći: \"Ona mi je žena\", misleći: \"Mještani bi me mogli ubiti zbog Rebeke jer je lijepa.\"');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 26, 8, 'Kako su se ondje duže zadržali, kralj Filistejaca Abimelek jednom pogleda kroz prozor i opazi kako Izak miluje svoju ženu Rebeku.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 26, 9, 'Nato Abimelek pozove Izaka te reče: \"Tako, ona ti je žena! Kako si mogao reći da ti je sestra?\" Izak mu odgovori: \"Jer sam mislio da bih zbog nje mogao poginuti.\"');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 26, 10, 'Abimelek reče: \"Zašto si nam to učinio? Umalo netko od ljudi nije legao s tvojom ženom. Tako bi na nas svalio krivnju.\"');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 26, 11, 'Onda Abimelek izda naredbu svemu narodu: \"Tko se god dotakne ovog čovjeka i njegove žene, glavu će izgubiti.\"');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 26, 12, 'Izak je sijao u onom kraju i one godine urodilo mu stostruko. Jahve ga blagoslivljao');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 26, 13, 'te je čovjek bivao sve bogatiji, dok nije postao vrlo bogat.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 26, 14, 'Stekao je stada ovaca i goveda i mnogu služinčad, tako da su mu Filistejci zavidjeli.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 26, 15, 'Zato Filistejci zasuše sve bunare što su ih sluge njegova oca bile iskopale - u vrijeme njegova oca Abrahama - i napuniše ih zemljom.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 26, 16, 'Onda Abimelek reče Izaku: \"Idi od nas jer si postao mnogo moćniji od nas!\"');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 26, 17, 'Tako Izak ode odande, postavi svoj šator u gerarskoj dolini i nastani se ondje.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 26, 18, 'Izak opet iskopa bunare za vodu što su bili iskopani u vrijeme njegova oca Abrahama, a Filistejci ih bili zasuli poslije Abrahamove smrti. On ih je nazvao istim imenima kojima ih je zvao i njegov otac.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 26, 19, 'Ali kad su Izakove sluge, dok su u dolini kopale, ondje našle bunar sa živom vodom,');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 26, 20, 'pastiri iz Gerara posvade se s Izakovim pastirima govoreći: \"Naša je voda!\" Bunaru je dao ime Esek, jer su se oni s njim svadili.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 26, 21, 'A kad su iskopali drugi bunar te se i zbog njega svađali, nazva ga imenom Sitna.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 26, 22, 'Odatle se preseli pa iskopa drugi bunar. Zbog njega se nisu svađali, pa ga nazove imenom Rehobot i protumači: \"Jer nam je Jahve dao prostor da se na zemlji umnožimo.\"');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 26, 23, 'Odande se popne u Beer Šebu.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 26, 24, 'Iste mu se noći ukaže Jahve i reče: \"Ja sam Bog oca tvoga Abrahama. Ne boj se, ja sam s tobom! Blagoslovit ću te, potomke ti umnožit, zbog Abrahama, sluge svojega.\"');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 26, 25, 'Izak tu podigne žrtvenik i zazove Jahvu po imenu; postavi ondje svoj šator, a njegove sluge počnu kopati bunar.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 26, 26, 'Uto mu dođe Abimelek iz Gerara sa svojim savjetnikom Ahuzatom i s Fikolom, zapovjednikom vojske.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 26, 27, 'Izak ih upita: \"Zašto ste došli k meni kad me mrzite i kad ste me otjerali od sebe?\"');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 26, 28, 'Oni odgovore: \"Jasno vidimo da je Jahve s tobom. Stoga pomislismo: neka zakletva bude veza između nas i tebe. Daj da s tobom sklopimo savez:');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 26, 29, 'ti nama nećeš zla nanositi, kao što mi tebe nismo zlostavljali, nego uvijek prema tebi lijepo postupali i s mirom te otpustili. A blagoslov Jahvin bio nad tobom.\"');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 26, 30, 'On im priredi gozbu te su jeli i pili.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 26, 31, 'Rano ujutro jedni se drugima zakunu. Potom ih Izak otpusti i oni od njega odu u miru.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 26, 32, 'Toga istog dana dođu Izakove sluge i obavijeste ga o bunaru što su ga iskopali te mu reknu: \"Našli smo vodu.\"');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 26, 33, 'On ga prozva Šiba. Zato je ime onom gradu do danas - Beer Šeba.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 26, 34, 'Kad je Ezavu bilo četrdeset godina, uzme za ženu Juditu, kćer Hetita Beerija, i Basematu, kćer Hetita Elona.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 26, 35, 'One postadoše izvor ogorčenja Izaku i Rebeki.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 27, 1, 'Ostarje Izak, vid mu se očinji gasio. Zato zovne svoga starijeg sina Ezava i reče mu: \"Sine!\" On mu odgovori: \"Evo me!\"');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 27, 2, 'A on nastavi: \"Vidiš, ostario sam, a ne znam dana svoje smrti.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 27, 3, 'Zato uzmi svoju opremu, svoj tobolac i luk, pa idi u pustaru i ulovi mi divljači.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 27, 4, 'Onda mi pripremi ukusan obrok, kako volim, te mi ga donesi da blagujem, pa da te mognem blagosloviti prije nego umrem.\"');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 27, 5, 'Rebeka je slušala dok je Izak govorio svome sinu Ezavu, i kad je Ezav otišao u pustaru da ulovi divljači svome ocu,');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 27, 6, 'Rebeka reče svome sinu Jakovu: \"Upravo sam čula kako tvoj otac govori tvome bratu Ezavu:');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 27, 7, '\'Donesi mi divljači te mi priredi ukusan obrok da blagujem pa da te pred licem Jahvinim blagoslovim prije nego umrem.\'');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 27, 8, 'A sad, sine moj, poslušaj me i učini kako ti naredim.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 27, 9, 'Otiđi k stadu i odande mi donesi dva lijepa kozleta, a ja ću od njih prirediti ukusan obrok tvome ocu, kako on voli.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 27, 10, 'Onda ti donesi svome ocu da jede te tebe mogne blagosloviti prije nego umre.\"');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 27, 11, 'Ali Jakov odgovori svojoj majci Rebeki: \"E, ali moj je brat Ezav runjav, a ja sam bez dlaka!');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 27, 12, 'Možda me se moj otac dotakne te ću u njegovim očima ispasti varalicom i na se svaliti prokletstvo, a ne blagoslov.\"');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 27, 13, 'Ali njegova mu majka odgovori: \"Sine moj, tvoje prokletstvo neka padne na mene! Samo ti mene poslušaj, otiđi i donesi!\"');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 27, 14, 'Ode on, nađe i donese svojoj majci, a njegova majka priredi ukusan obrok, kako je njegov otac volio.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 27, 15, 'Potom Rebeka uzme najljepše odijelo svoga starijeg sina Ezava što je u kući imala, pa u nj odjene svoga mlađeg sina Jakova.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 27, 16, 'U kožu kozleta zamota mu ruke i goli dio vrata.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 27, 17, 'Stavi zatim ukusan obrok i kruh što ga je pripravila na ruke svoga sina Jakova.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 27, 18, 'Ode on k ocu i reče: \"Oče!\" On odgovori: \"Evo me. Koji si ti moj sin?\"');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 27, 19, 'A Jakov odgovori svome ocu: \"Ja sam Ezav, tvoj prvorođenac; učinio sam kako si mi rekao. Sad ustaj, sjedi pa jedi moje lovine, da me onda mogneš blagosloviti.\"');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 27, 20, 'Izak upita svoga sina: \"Kako si tako brzo uspio, sine moj?\" On odgovori: \"Jer mi je Jahve, Bog tvoj, bio milostiv.\"');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 27, 21, 'Potom Izak reče Jakovu: \"Primakni se, sine moj, da opipam jesi li ti zbilja moj sin Ezav ili nisi.\"');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 27, 22, 'Jakov se primakne k svome ocu Izaku, koji ga opipa i reče: \"Glas je Jakovljev, ali su ruke Ezavove.\"');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 27, 23, 'Nije ga prepoznao jer su mu ruke bile runjave kao i ruke njegova brata Ezava. Kad ga je htio blagosloviti,');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 27, 24, 'upita još jednom: \"Jesi li ti zaista moj sin Ezav?\" Odgovori on: \"Jesam.\"');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 27, 25, 'Potom reče Izak: \"Stavi preda me da blagujem lovine svoga sina pa da te blagoslovi duša moja.\" Jakov ga posluži pa je jeo. Zatim mu donese i vina, pa je pio.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 27, 26, 'Poslije toga reče mu njegov otac Izak: \"Primakni se, sine moj, i poljubi me!\"');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 27, 27, 'Kad se primače i poljubi ga, Izak osjeti miris njegove odjeće pa ga blagoslovi: \"Gle, miris sina mog nalik je mirisu polja koje Jahve blagoslovi.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 27, 28, 'Neka ti Bog daje rosu s neba i rodnost zemlje: izobilje žita i mladoga vina.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 27, 29, 'Narodi ti služili, plemena ti se klanjala! Braćom svojom gospodari, nek sinci majke tvoje pred tobom padaju! Proklet bio tko tebe proklinje; blagoslovljen tko te blagoslivlje!\"');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 27, 30, 'Tek što se Jakov udaljio od svoga oca Izaka - pošto je Izak podijelio blagoslov Jakovu - njegov brat Ezav dođe iz lova.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 27, 31, 'I on priredi ukusan obrok i donese ga svome ocu. I reče svome ocu: \"Ustani, oče moj, i blaguj od lovine svoga sina da me onda mogneš blagosloviti!\"');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 27, 32, 'A njegov ga otac Izak zapita: \"Tko si ti?\" On odgovori: \"Ja sam tvoj prvorođenac Ezav!\"');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 27, 33, 'Izak se silno prepadne: \"Pa tko je onda bio onaj što je divljači ulovio i meni već donio? Blagovao sam je prije nego si ti došao; onoga sam blagoslovio i blagoslovljen će ostati.\"');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 27, 34, 'Kad je Ezav čuo riječi svoga oca, kriknu glasno i gorko zaplaka pa reče svome ocu: \"I mene blagoslovi, oče!\"');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 27, 35, 'A on odvrati: \"Brat tvoj dođe na prijevaru i odnese tvoj blagoslov.\"');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 27, 36, '\"Zato valjda što mu je ime Jakov, dvaput me već prevario\", reče Ezav. \"Oduzeo mi prvorodstvo, a sad mi evo oduze i blagoslov.\" Onda doda: \"Zar za me nisi sačuvao nikakva blagoslova?\"');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 27, 37, 'Izak odgovori Ezavu: \"Njega sam već postavio za tvoga gospodara; njemu sam svu njegovu braću predao za sluge; žitom sam ga i vinom opskrbio. A što sad za te mogu učiniti, sine moj?\"');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 27, 38, 'Ezav odgovori svome ocu: \"Zar ti, oče, raspolažeš samo jednim blagoslovom? Blagoslovi i mene, oče moj!\" Ezav jecaše na sav glas.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 27, 39, 'Tada otac njegov Izak progovori i reče: \"Daleko od plodna tla dom tvoj će biti, daleko od rose s neba.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 27, 40, 'Od mača svoga ćeš živjeti, brata svoga ćeš služiti. Ali jednom, kada se pobuniš, jaram ćeš njegov stresti sa svog vrata.\"');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 27, 41, 'Ezav zamrzi Jakova zbog blagoslova kojim ga je otac njegov blagoslovio pa reče u sebi: \"Čim dođu dani žalosti za mojim ocem, ubit ću ja svoga brata Jakova.\"');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 27, 42, 'Kada su Rebeki javili te riječi što ih je izrekao njezin stariji sin Ezav, zovne ona svoga mlađeg sina Jakova te mu reče: \"Pazi! Brat ti se Ezav nosi mišlju kako će te ubiti.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 27, 43, 'Ali ti, sine moj, poslušaj mene: odmah bježi mome bratu Labanu u Haran.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 27, 44, 'Ostani kod njega neko vrijeme, dok bijes brata tvoga na te jenja,');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 27, 45, 'dok se srdžba brata tvoga odvrati od tebe te on zaboravi što si mu učinio. Ja ću onda po te poslati i odande te dovesti. Zašto da vas obojicu izgubim u jedan dan!\"');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 27, 46, 'Potom Rebeka reče Izaku: \"Moj mi je život dosadio zbog ovih žena Hetitkinja. Ako se i Jakov oženi kojom kao što su ove urođenice, Hetitkinjom, što će mi onda život!\"');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 28, 1, 'Stoga Izak pozove Jakova, blagoslovi ga te mu naloži: \"Nemoj uzimati ženu od kanaanskih djevojaka.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 28, 2, 'Odmah se zaputi u Padan Aram, u dom Betuela, oca svoje majke, pa odande sebi uzmi ženu, od kćeri Labana, brata svoje majke.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 28, 3, 'A Bog Svemožni, El-Šadaj, neka te blagoslovi i neka te učini rodnim i brojnim, tako da postaneš mnoštvo naroda.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 28, 4, 'Neka protegne na te blagoslov Abrahamov, na te i na tvoje potomstvo, tako da zaposjedneš zemlju u kojoj boraviš kao pridošlica, a koju je Bog predao Abrahamu!\"');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 28, 5, 'Tako Izak otpremi Jakova, i on ode u Padan Aram Labanu, sinu Aramejca Betuela, bratu Rebeke, majke Jakova i Ezava.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 28, 6, 'Kad je Ezav vidio kako je Izak blagoslovio Jakova kad ga je otpremao u Padan Aram da odande sebi uzme ženu, naređujući mu kad ga je blagoslivljao: \"Ne smiješ uzeti ženu od kanaanskih djevojaka\",');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 28, 7, 'i da je Jakov poslušao svoga oca i svoju majku te otišao u Padan Aram,');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 28, 8, 'Ezav shvati koliko su djevojke kanaanske mrske njegovu ocu Izaku.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 28, 9, 'Stoga ode k Jišmaelu te se, uza žene koje već imaše, oženi Mahalatom, kćerju Jišmaela, sina Abrahamova, a sestrom Nebajotovom.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 28, 10, 'Jakov ostavi Beer Šebu i zaputi se u Haran.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 28, 11, 'Stigne u neko mjesto i tu prenoći, jer sunce bijaše već zašlo. Uzme jedan kamen s onog mjesta, stavi ga pod glavu i na tom mjestu legne.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 28, 12, 'I usne san: ljestve stoje na zemlji, a vrhom do neba dopiru, i anđeli Božji po njima se penju i silaze.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 28, 13, 'Uza nj je Jahve te mu govori: \"Ja sam Jahve, Bog tvoga praoca Abrahama i Bog Izakov. Zemlju na kojoj ležiš dat ću tebi i tvome potomstvu.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 28, 14, 'Tvojih će potomaka biti kao i praha na zemlji; raširit ćete se na zapad, istok, sjever i jug; tobom će se i tvojim potomstvom blagoslivljati svi narodi zemlje.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 28, 15, 'Dobro znaj: ja sam s tobom; čuvat ću te kamo god pođeš te ću te dovesti natrag u ovu zemlju; i neću te ostaviti dok ne izvršim što sam ti obećao.\"');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 28, 16, 'Jakov se probudi od sna te reče: \"Zaista se Jahve nalazi na ovome mjestu, ali ja nisam znao!\"');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 28, 17, 'Potresen, uzviknu: \"Kako je strašno ovo mjesto! Zaista, ovo je kuća Božja, ovo su vrata nebeska!\"');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 28, 18, 'Rano ujutro Jakov uzme onaj kamen što ga bijaše stavio pod glavu, uspravi ga kao stup i po vrhu mu izlije ulja.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 28, 19, 'Ono mjesto on nazva Betel, dok je ime tome gradu prije bilo Luz.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 28, 20, 'Tada učini zavjet: \"Ako Bog ostane sa mnom i uščuva me na ovom putu kojim idem, dade mi kruha da jedem i odijela da se oblačim,');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 28, 21, 'te se zdravo vratim kući svoga oca, Jahve će biti moj Bog.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 28, 22, 'A ovaj kamen koji sam uspravio kao stup bit će kuća Božja. A od svega što mi budeš davao za te ću odlagati desetinu.\"');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 29, 1, 'Jakov nastavi put i dođe u zemlju istočnu.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 29, 2, 'Najednom opazi studenac u polju. Tri su stada ovaca oko njega plandovala, jer se na tome studencu napajahu. Velik se kamen nalazio studencu na otvoru.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 29, 3, 'Jedino kad bi se svi pastiri ondje skupili, mogli bi odvaliti kamen s otvora i ovce napojiti; tada bi opet prevalili kamen na njegovo mjesto, na otvor studenca.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 29, 4, '\"Odakle ste, braćo moja?\" - zapita ih Jakov. \"Iz Harana\", odgovore.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 29, 5, '\"Poznajete li\", pitaše ih dalje, \"Nahorova sina Labana?\" \"Poznajemo\", odgovore.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 29, 6, '\"Je li zdravo?\" - opet ih upita. \"Zdravo je; a evo mu dolazi kći Rahela sa stadom\", odgovore.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 29, 7, '\"Još ima mnogo dana\", nastavi on, \"nije vrijeme spraćati blago. Zašto ga ne napojite i ne otjerate na pašu?\"');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 29, 8, '\"Ne možemo dok se ne skupe svi pastiri\", odgovoriše, \"da odvale kamen s otvora studenca, tako da mognemo napojiti ovce.\"');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 29, 9, 'Dok je on još s njima govorio, dođe Rahela s ovcama svoga oca. Bila je, naime, pastirica.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 29, 10, 'Kako Jakov ugleda Rahelu, kćer Labana, brata svoje majke, sa stadom svoga ujaka Labana, Jakov se primače i odvali kamen s otvora studenca te napoji stado svoga ujaka Labana.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 29, 11, 'Zatim Jakov poljubi Rahelu, a onda briznu u plač.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 29, 12, 'Potom Jakov kaza Raheli da je on sestrić njezina oca, sin Rebekin. Nato ona otrča i obavijesti oca.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 29, 13, 'Kad je Laban čuo vijest o Jakovu, sinu svoje sestre, potrča mu u susret. Zagrli ga i poljubi te dovede u svoju kuću. Ispriča Labanu sve što mu se dogodilo.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 29, 14, 'A onda Laban reče. \"Zbilja si ti moja kost i moje meso!\" Pošto je Jakov proboravio s Labanom mjesec dana,');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 29, 15, 'Laban reče Jakovu: \"Zar ćeš me zato što si mi sestrić badava služiti! Kaži mi koliko ćeš tražiti za najam?\"');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 29, 16, 'A Laban imaše dvije kćeri. Starijoj bijaše ime Lea, a mlađoj Rahela.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 29, 17, 'Lea imala slabe oči, a Rahela bila stasita i lijepa.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 29, 18, 'Kako je Jakov volio Rahelu, reče: \"Služit ću ti sedam godina za tvoju mlađu kćer Rahelu.\"');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 29, 19, 'Laban odvrati: \"Bolje je da je tebi dam nego kakvu strancu. Ostani sa mnom!\"');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 29, 20, 'Tako je Jakov služio za Rahelu sedam godina, ali mu se učinile, zbog ljubavi prema njoj, kao nekoliko dana.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 29, 21, 'Poslije toga Jakov reče Labanu: \"Daj mi moju ženu, jer se moje vrijeme navršilo pa bih htio k njoj.\"');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 29, 22, 'Laban sabra sav svijet onog mjesta i priredi gozbu.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 29, 23, 'Ali navečer uzme svoju kćer Leu pa nju uvede k Jakovu, i on priđe k njoj.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 29, 24, 'Laban dade svoju sluškinju Zilpu svojoj kćeri Lei za sluškinju.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 29, 25, 'Kad bi ujutro, a to, gle, Lea! Tada Jakov reče Labanu: \"Zašto si mi to učinio! Zar te ja nisam služio za Rahelu? Zašto si me prevario?\"');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 29, 26, 'Laban odgovori: \"U našem mjestu nije običaj da se mlađa udaje prije starije.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 29, 27, 'Završi s njom ovu ženidbenu sedmicu, a onda ću ti dati i drugu, za drugih sedam godina službe kod mene.\" Jakov pristane: navrši onu ženidbenu sedmicu.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 29, 28, 'Onda mu Laban dade i svoju kćer Rahelu za ženu.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 29, 29, 'Laban dade svoju sluškinju Bilhu svojoj kćeri Raheli za sluškinju.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 29, 30, 'Jakov nato priđe Raheli. Rahelu je više volio nego Leu. I tako je služio Labana još sedam godina.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 29, 31, 'Jahve je vidio da Lea nije voljena, te je učini plodnom, dok Rahela ostade nerotkinja.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 29, 32, 'Lea zače i rodi sina; nadjenu mu ime Ruben, a to znači, kako je ona protumačila: \"Jahve je vidio moju nevolju i stoga će me sada muž moj ljubiti.\"');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 29, 33, 'Opet zače i rodi sina te izjavi: \"Jahve je čuo da nisam voljena, stoga mi je dao i ovoga.\" Zato mu nadjenu ime Šimun.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 29, 34, 'Opet zače i rodi sina te izjavi: \"Sad će se moj muž meni prikloniti: tri sam mu sina rodila.\" Zato mu nadjenu ime Levi.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 29, 35, 'A kad je još jednom začela i sina rodila, izjavi: \"Ovaj put hvalit ću Jahvu.\" Stoga sinu nadjenu ime Juda. Potom prestade rađati.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 30, 1, 'Vidjevši Rahela da Jakovu ne rađa djece, postade zavidna svojoj sestri pa reče Jakovu: \"Daj mi djecu! Inače ću svisnuti!\"');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 30, 2, 'Jakov se razljuti na Rahelu te reče. \"Zar sam ja namjesto Boga koji ti je uskratio plod utrobe?\"');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 30, 3, 'A ona odgovori: \"Evo moje sluškinje Bilhe: uđi k njoj, pa neka rodi na mojim koljenima, da tako i ja steknem djecu po njoj.\"');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 30, 4, 'Dade mu dakle svoju sluškinju Bilhu za ženu, i Jakov priđe k njoj.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 30, 5, 'Bilha zače te Jakovu rodi sina.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 30, 6, 'Tada Rahela reče: \"Jahve mi je dosudio pravo. Uslišao je moj glas i dao mi sina.\" Stoga mu nadjenu ime Dan.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 30, 7, 'Rahelina sluškinja Bilha opet zače i rodi Jakovu drugoga sina.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 30, 8, 'Tada Rahela reče: \"Žestoko sam se borila sa sestrom, ali sam pobijedila.\" Tako mu nadjenu ime Naftali.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 30, 9, 'A vidjevši Lea da je prestala rađati, uzme svoju sluškinju Zilpu pa je dade Jakovu za ženu.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 30, 10, 'I kad je Leina sluškinja Zilpa rodila Jakovu sina,');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 30, 11, 'Lea uskliknu: \"Koje sreće!\" Tako mu nadjenu ime Gad.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 30, 12, 'Leina sluškinja Zilpa rodi Jakovu i drugog sina,');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 30, 13, 'i Lea opet uskliknu: \"Blago meni! Žene će me zvati blaženom!\" Tako mu nadjenu ime Ašer.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 30, 14, 'Jednoga dana, u vrijeme pšenične žetve, namjeri se Ruben u polju na ljubavčice te ih donese svojoj majci Lei. I Rahela reče Lei: \"Daj mi od ljubavčica svoga sina!\"');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 30, 15, 'A Lea odgovori: \"Zar ti nije dosta što si mi oduzela muža pa još hoćeš da od mene uzmeš i ljubavčice moga sina?\" Rahela odgovori: \"Pa dobro, neka s tobom noćas leži u zamjenu za ljubavčice tvog sina.\"');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 30, 16, 'Kad je Jakov navečer stigao iz polja, Lea mu iziđe u susret pa reče: \"Treba da dođeš k meni, jer sam te unajmila za ljubavčice moga sina.\" One je noći on s njom ležao.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 30, 17, 'Bog usliša Leu; ona zače te Jakovu rodi petog sina.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 30, 18, 'Onda Lea reče: \"Bog mi je uzvratio nagradom što sam ustupila svoju sluškinju svome mužu.\" Stoga sinu nadjenu ime Jisakar.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 30, 19, 'Lea opet zače i rodi Jakovu šestoga sina.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 30, 20, 'Onda Lea reče: \"Bog me obdari dragocjenim darom; sada će mi moj muž dati darove: tÓa rodila sam mu šest sinova.\" Tako mu nadjenu ime Zebulun.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 30, 21, 'Zatim rodi kćer te joj nadjenu ime Dina.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 30, 22, 'Uto se Bog sjeti Rahele: Bog je usliša i otvori njezinu utrobu.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 30, 23, 'Ona zače i rodi sina te reče: \"Ukloni Bog moju sramotu!\"');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 30, 24, 'Nadjene mu ime Josip, rekavši: \"Neka mi Jahve pridoda drugog sina!\"');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 30, 25, 'Pošto je Rahela rodila Josipa, Jakov reče Labanu: \"Pusti me da idem u svoj zavičaj!');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 30, 26, 'Daj mi moje žene za koje sam te služio i moju djecu da mogu otići: tÓa dobro znaš kako sam te služio.\"');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 30, 27, 'A Laban mu odgovori: \"Ne idi, ako si mi prijatelj. Znam da me Jahve blagoslivljao zbog tebe.\"');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 30, 28, 'I nadoda: \"Odredi plaću koju želiš od mene, i dat ću ti.\"');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 30, 29, 'On mu odgovori: \"Ti dobro znaš što je moja služba značila za te i kako je tvome blagu bilo sa mnom.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 30, 30, 'Malenkost što si je imao prije nego sam ja došao povećala se vrlo mnogo, jer kuda god sam prolazio Jahve te blagoslivljao na mojim koracima. A sad je vrijeme da poradim i za svoj dom.\"');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 30, 31, 'On upita: \"Koliko da ti platim?\" Jakov odgovori: \"Nemoj mi platiti ništa! Ako mi učiniš ovo, opet ću na pašu goniti i čuvati tvoje stado.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 30, 32, 'Daj da prođem danas kroz tvoje stado i od njega izlučim svaku garavu ovcu i svaku šarenu ili napruganu kozu! Neka to bude moja plaća!');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 30, 33, 'A ubuduće kad budeš svojim očima provjeravao moju naplatu, moje će poštenje biti svjedok za mene: nađe li se među mojim kozama ijedna koja ne bude šarena ili naprugana, ili među ovcama koja ne bi bila garava, neka se smatra ukradenom!\"');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 30, 34, 'Laban reče: \"Dobro, neka bude kako si kazao.\"');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 30, 35, 'Ali toga dana Laban izluči naprugane i šarene jarce i sve riđaste i šarene koze - svaku koja je na sebi imala bijelo - i sve garave ovce pa ih preda svojim sinovima.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 30, 36, 'I odande gdje je Jakov pasao ostatak Labanova stada udalji se za koja tri dana hoda.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 30, 37, 'A Jakov uzme zelenih mladica od topola, badema i platana; na njima izreza bijele pruge, otkrivši bjeliku na mladicama.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 30, 38, 'Pruće tako isprugano postavi u korita, u pojila iz kojih se stoka napajala. A kako se stoka parila kad je na vodu dolazila,');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 30, 39, 'to su se jarci parili uz pruće, pa su koze kozile prugaste, riđaste i šarene kozliće.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 30, 40, 'Tako je i ovce Jakov bio izlučio i glave im okrenuo prema prugastima ili posve garavima što su bile u Labanovu stadu. Tako je za se namicao posebna stada koja nije miješao s Labanovim stadima.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 30, 41, 'Osim toga, kad bi se god dobro uzrasla stoka parila, Jakov bi stavio pruće u korita, baš pred oči živine, tako da se pari pred prućem.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 30, 42, 'Ali ga pred kržljavu marvu nije stavljao. Tako je kržljava zapadala Labana, a dobro razvijena Jakova.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 30, 43, 'Čovjek se tako silno obogatio, stekao mnogu stoku, sluge i sluškinje, deve i magarad.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 31, 1, 'Uto Jakov dozna kako Labanovi sinovi govore: \"Sve dobro našega oca uze Jakov; i od onoga što bi moralo pripasti našem ocu namaknuo je sve ono bogatstvo.\"');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 31, 2, 'A opazi Jakov i na Labanovu licu da se on ne drži prema njemu kao prije.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 31, 3, 'Tada Jahve reče Jakovu: \"Vrati se u zemlju svojih otaca, u svoj zavičaj, i ja ću biti s tobom!\"');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 31, 4, 'Jakov onda pozove Rahelu i Leu u polje, k svome stadu,');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 31, 5, 'pa im reče: \"Ja vidim na licu vašega oca da se on ne drži prema meni kao prije; ali Bog oca moga sa mnom je bio.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 31, 6, 'I same znate da sam vašega oca služio koliko sam god mogao;');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 31, 7, 'pa ipak je vaš otac mene varao, deset mi je puta plaću mijenjao. Ali Bog nije dopuštao da mi nanese štetu.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 31, 8, 'Ako bi on rekao: \'Svaka šarena neka bude tebi za naplatu\', onda bi cijelo stado mladilo šarene; ako bi opet rekao: \'Prugasti neka budu tebi za plaću\', onda bi cijelo stado mladilo prugaste.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 31, 9, 'Tako je Bog uzimao blago od vašeg oca pa ga meni davao.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 31, 10, 'Jednom, kad se stado oplođivalo, nenadano vidjeh u snu da su jarci u stadu, dok su se parili, bili prugasti, mjestimično bijeli i šareni.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 31, 11, 'Još u snu anđeo Božji mene zovne: \'Jakove!\' \'Evo me!\' rekoh.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 31, 12, 'A on nastavi: \'Primijeti dobro da su jarci u stadu što se pare prugasti, mjestimično bijeli i šareni. Ja sam, naime, vidio sve što ti je Laban činio.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 31, 13, 'Ja sam Bog koji ti se ukazao u Betelu, gdje si uljem pomazao stup i gdje si mi učinio zavjet. Sad ustaj i idi iz ove zemlje; vrati se u svoj zavičaj!\'\"');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 31, 14, 'Nato mu Rahela i Lea odgovore: \"Zar još imamo baštinskog dijela u svome očinskom domu?');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 31, 15, 'Zar nas otac nije smatrao tuđinkama? TÓa on je nas prodao, a onda je pojeo novac što ga je za nas dobio!');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 31, 16, 'Sve bogatstvo što je Bog oduzeo našem ocu zbilja je naše i djece naše. Zato izvrši sve što ti je Bog rekao!\"');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 31, 17, 'Nato Jakov naprti na deve svoju djecu i svoje žene;');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 31, 18, 'pred sobom potjera sve svoje blago, sva svoja dobra što ih je stekao, stoku što ju je namaknuo u Padan Aramu: krenu u zemlju kanaansku, k svome ocu Izaku.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 31, 19, 'Laban bijaše otišao da striže svoje ovce, pa Rahela prisvoji kućne kumire koji su pripadali njezinu ocu.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 31, 20, 'Jakov zavara Aramejca Labana tako da nije ni slutio da će bježati.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 31, 21, 'I pobjegne sa svim što je bilo njegovo. Ubrzo prijeđe Eufrat i upravi put prema brdu Gileadu.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 31, 22, 'Trećeg dana obavijeste Labana da je Jakov pobjegao.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 31, 23, 'On povede sa sobom svoje rođake te je za Jakovom išao u potjeru sedam dana hoda; stiže ga na brdu Gileadu.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 31, 24, 'Ali se Bog ukaza Aramejcu Labanu, noću u snu, te mu reče. \"Pazi da protiv Jakova ne poduzimlješ ništa, ni dobro ni zlo!\"');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 31, 25, 'Uto Laban stigne Jakova. Jakov bijaše postavio svoj šator na Glavici, a Laban se utabori na brdu Gileadu.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 31, 26, 'Onda Laban reče Jakovu: \"Što si to htio zavaravajući me i odvodeći mi kćeri kao zarobljenice na maču?');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 31, 27, 'Zašto si potajno pobjegao, u bludnju me zaveo i nisi me obavijestio? Otpratio bih te s veseljem i pjesmom, uz bubnje i lire.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 31, 28, 'Nisi mi dopustio ni da izljubim svoje kćeri i svoju unučad! Zbilja si ludo postupio.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 31, 29, 'U mojoj je ruci da s tobom loše postupim. Ali Bog tvoga oca noćas mi reče: \'Pazi da protiv Jakova ne poduzmeš ništa, ni dobro ni zlo!\'');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 31, 30, 'Sada dobro, otišao si jer si čeznuo za svojim očinskim domom; ali zašto si mi kumire pokrao?\"');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 31, 31, 'Jakov odgovori Labanu: \"Strepio sam od pomisli da bi mi mogao silom oteti svoje kćeri.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 31, 32, 'A kumire svoje u koga nađeš, onaj neka pogine! Ovdje pred našom braćom kaži što je tvoga pri meni i nosi!\" Jakov nije znao da ih je Rahela prisvojila.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 31, 33, 'Tako Laban uđe u šator Jakovljev, pa u šator Lein, onda u šator dviju sluškinja, ali ništa ne nađe. Izišavši iz Leina šatora, uđe u šator Rahelin.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 31, 34, 'A Rahela bijaše uzela kumire i stavila ih u sjedalo svoje deve, a onda na njih sjela. Laban je premetao po svemu šatoru, ali ih ne nađe.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 31, 35, 'Ona je, naime, rekla svome ocu: \"Neka se moj gospodar ne ljuti što ne mogu pred njim ustati jer imam ono što je red kod žena.\" I tako je pretraživao, ali kumira nije našao.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 31, 36, 'Sad se Jakov ražesti i zađe u prepirku s Labanom. Otvoreno Jakov reče Labanu: \"Kakvo je moje zlodjelo, koja li je moja krivnja da me progoniš?');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 31, 37, 'Eto si premetnuo sve moje stvari, pa kakav si predmet našao od svega svog kućanstva? Položi ga tu pred moj i svoj rod pa neka oni budu suci među nama dvojicom.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 31, 38, 'Za ovih dvadeset godina što sam ih s tobom proveo ni tvoje ovce ni tvoje koze nisu se jalovile niti sam ja jeo ovnova iz tvoga stada.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 31, 39, 'Ono što bi zvijer razdrla, tebi nisam donosio, nego bih od svoga gubitak nadoknadio. Ti si to od mene tražio, bilo da je nestalo danju ili da je nestalo noću.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 31, 40, 'Često sam danju skapavao od žeđi, a obnoć od studeni. San je bježao od mojih očiju.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 31, 41, 'Od ovih dvadeset godina što sam ih proveo u tvojoj kući četrnaest sam ti godina služio za tvoje dvije kćeri, a šest godina za tvoju stoku, jer si mi mijenjao zaradu deset puta.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 31, 42, 'Da sa mnom nije bio Bog moga oca, Bog Abrahamov, Strah Izakov, otpravio bi me praznih ruku. Ali je Bog gledao moju nevolju i trud mojih ruku te je sinoć dosudio.\"');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 31, 43, 'Nato Laban odgovori Jakovu: \"Kćeri su moje kćeri; djeca su moja djeca; stada su moja stada, sve što gledaš moje je. Ali što danas mogu učiniti ovim svojim kćerima ili djeci koju su rodile?');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 31, 44, 'Pa dobro, hajde da ti i ja napravimo ugovor, tako da bude svjedok između mene i tebe.\"');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 31, 45, 'Nato Jakov uzme jedan kamen pa ga uspravi kao stup,');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 31, 46, 'a onda reče svojim ljudima: \"Skupite kamenja!\" Tako oni nakupe kamenja i nabace gomilu. Tu su na gomili blagovali.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 31, 47, 'Laban je nazva \"Jegar sahaduta\", a Jakov je nazva \"Gal-ed\".');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 31, 48, 'Onda Laban izjavi: \"Neka ova gomila danas bude svjedok između mene i tebe!\" Stoga je nazvana Gal-ed,');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 31, 49, 'ali i Mispa, jer je rekao. \"Neka Jahve bude na vidu i tebi i meni kad jedan drugog ne budemo gledali.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 31, 50, 'Ako budeš loše postupao prema mojim kćerima, ili ako uzmeš druge žene uz moje kćeri, sve da nitko drugi ne bude s nama, znaj da će Bog biti svjedok između mene i tebe.\"');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 31, 51, 'Potom Laban reče Jakovu: \"Ovdje je, evo, gomila; ovdje je stup koji sam uspravio između sebe i tebe:');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 31, 52, 'ova gomila i ovaj stup neka budu jamac da ja u zloj namjeri neću ići na te iza ove gomile i da ti nećeš ići na me iza ove gomile i ovog stupa.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 31, 53, 'Neka Bog Abrahamov i Bog Nahorov budu naši suci!\" Jakov se zakune Bogom - Strahom svoga oca Izaka.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 31, 54, 'Poslije toga Jakov prinese žrtvu na Glavici i pozva svoje ljude da blaguju. Poslije objeda proveli su noć na Glavici.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 32, 1, 'Ranim se jutrom Laban digne, izljubi svoje sinove i svoje kćeri te ih blagoslovi; onda se zaputi natrag u svoje mjesto.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 32, 2, 'Jakov je putovao svojim putem, kad mu u susret izađu anđeli Božji.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 32, 3, 'Kad ih Jakov opazi, reče: \"Ovo je Božje taborište!\" Zato nazva ono mjesto Mahanajim.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 32, 4, 'Jakov pošalje pred sobom glasnike svome bratu Ezavu u zemlju Seir, u Edomsku pustaru,');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 32, 5, 'i naloži im: \"Ovako ćete reći mome gospodaru Ezavu: \'Sluga tvoj Jakov poručuje ti: Boravio sam kod Labana i dosad se ondje zadržao.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 32, 6, 'Stekao sam goveda, magaradi, ovaca, sluga i sluškinja. Javljam to svome gospodaru, ne bih li našao naklonost u njegovim očima.\'\"');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 32, 7, 'Glasnici se vrate Jakovu te mu reknu: \"Bili smo kod tvoga brata Ezava; on sam dolazi ti u susret sa četiri stotine momaka.\"');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 32, 8, 'Jakov se silno uplaši. U zabrinutosti rastavi na dva tabora ljude, stada, krda i deve što ih je sa sobom imao.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 32, 9, 'Računao je: ako Ezav naiđe na jedan tabor i napadne ga, drugi bi se tabor mogao spasiti.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 32, 10, 'Onda se Jakov pomoli: \"O Bože oca moga Abrahama! Bože oca moga Izaka! O Jahve, koji si mi naredio: \'Vrati se u svoj rodni kraj, i ja ću ti biti dobrostiv!\'');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 32, 11, 'Nisam vrijedan sve dobrote koju si tako postojano iskazivao svome sluzi. TÓa samo sam sa svojim štapom nekoć prešao ovaj Jordan, a sad sam narastao u dva tabora.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 32, 12, 'Izbavi me od šaka moga brata, od šaka Ezavovih! Inače se bojim da bi mogao doći i umlatiti i mene, i majke, i djecu.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 32, 13, 'Ti si rekao: \'Obilnim ću te dobrima obasipati i tvoje potomstvo umnožiti poput pijeska u moru koji se ne da prebrojiti zbog množine.\'\"');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 32, 14, 'Ondje provede onu noć; a onda, od onog što je imao pri ruci, pripravi dar svome bratu Ezavu:');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 32, 15, 'dvjesta koza i dvadeset jaraca, dvjesta ovaca i dvadeset ovnova;');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 32, 16, 'trideset deva dojilica s njihovim mladima; četrdeset krava i deset junaca; dvadeset magarica i deset magaraca.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 32, 17, 'Stado po stado preda svojim slugama. Onda reče svojim slugama: \"Idite preda mnom, ali držite razmak među stadima!\"');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 32, 18, 'A prvom izda naredbu rekavši: \"Kad te sretne moj brat Ezav pa te upita: \'Čiji si ti? Kamo ideš? Čije je ovo pred tobom?\'');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 32, 19, 'odgovori: \'Tvoga sluge Jakova; ovo je dar koji šalje svome gospodaru Ezavu; on je tamo za nama.\'\"');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 32, 20, 'Tako je naredio i drugome, pa trećemu i svima drugima koji su išli za stadima: \"Ovo i ovako reci Ezavu kad ga sretneš.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 32, 21, 'Još mu dodaj: \'A sluga tvoj Jakov i sam je za nama.\'\" Mislio je naime: \"Ako ga unaprijed udobrostivim darovima, a onda se s njim suočim, možda će mi oprostiti.\"');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 32, 22, 'Tako darovi krenu naprijed, dok je on ostao one noći u taborištu.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 32, 23, 'One noći on ustane, uzme svoje obje žene, obje svoje sluškinje i svoje jedanaestero djece te prijeđe Jabok preko gaza.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 32, 24, 'Prebacivši njih na drugu stranu toka, prebaci zatim i ostalo što bijaše njegovo.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 32, 25, 'Jakov ostane sam. I neki se čovjek rvao s njim dok nije zora svanula.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 32, 26, 'Videći da ga ne može svladati, ugane mu bedro pri zglobu, tako da se Jakovu kuk iščašio dok su se rvali.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 32, 27, 'Potom reče: \"Pusti me jer zora sviće!\" Ali on odgovori: \"Neću te pustiti dok me ne blagosloviš.\"');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 32, 28, 'Nato ga onaj zapita: \"Kako ti je ime?\" Odgovori: \"Jakov.\"');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 32, 29, 'Onaj reče. \"Više se nećeš zvati Jakov nego Izrael, jer si se hrabro borio i s Bogom i s ljudima i nadvladao si.\"');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 32, 30, 'Onda zapita Jakov: \"Reci mi svoje ime!\" Odgovori onaj: \"Za moje me ime ne smiješ pitati!\" I tu ga blagoslovi.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 32, 31, 'Onom mjestu Jakov nadjene ime Penuel jer - reče - \"Vidjeh Boga licem u lice, i na životu ostadoh.\"');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 32, 32, 'Sunce je nad njim bilo ogranulo kad je prošao Penuel. Hramao je zbog kuka.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 32, 33, 'Zato Izraelci do današnjeg dana ne jedu kukovnu tetivu što se nalazi na bedrenom zglobu, budući da je Jakovljev bedreni zglob bio iščašen u kukovnoj tetivi.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 33, 1, 'Jakov podiže oči i opazi gdje dolazi Ezav i s njime četiri stotine ljudi. Onda on podijeli svoju djecu među Leu, Rahelu i dvije sluškinje;');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 33, 2, 'postavi sluškinje i njihovu djecu na čelo; iza njih Leu i njezinu djecu; a Rahelu i Josipa straga.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 33, 3, 'Sam prođe naprijed, nakloni se do zemlje sedam puta dok se ne primače svome bratu.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 33, 4, 'Ezav mu potrča u susret. Zagrli ga padnuvši mu oko vrata, poljubi ga i zaplaka.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 33, 5, 'Onda podiže oči i vidje žene i djecu. \"Tko su ovi s tobom?\" - zapita. On odgovori: \"Djeca kojom je Bog obdario tvoga slugu.\"');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 33, 6, 'Potom naprijed stupe sluškinje sa svojom djecom te se duboko naklone.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 33, 7, 'Naprijed stupi i Lea sa svojom djecom te se duboko nakloni. Najposlije stupe naprijed Josip i Rahela te se duboko naklone.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 33, 8, 'Ezav upita: \"Što kaniš sa svom ovom povorkom što sam je sreo?\" Odgovori: \"Naći naklonost svoga gospodara.\"');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 33, 9, 'Ezav odgovori: \"Ja imam dosta, brate moj. Neka ostane tebi što je tvoje.\"');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 33, 10, 'A Jakov reče: \"Nemoj tako! Ako sam našao naklonost u tvojim očima, primi dar iz moje ruke; jer meni je, što si me ljubezno primio, kao da gledam lice Božje.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 33, 11, 'Zato prihvati moj dar što sam ti ga donio; Bog mi je bio sklon te imam svega.\" Kako ga je uporno nagovarao, Ezav prihvati.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 33, 12, '\"Pođimo na put\", reče Ezav, \"i ja ću s tobom putovati.\"');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 33, 13, 'Ali mu on odvrati: \"Zna moj gospodar da su djeca nejaka. Osim toga, valja mi se brinuti o ovcama i kravama koje doje: ako bi se tjerale prebrzo samo jednog dana, sve bi pocrkale.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 33, 14, 'Neka moj gospodar ide ispred svoga sluge, a ja ću ići polako, uz korak marve pred sobom i uz korak djece, dok ne stignem k svome gospodaru u Seir.\"');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 33, 15, 'Onda reče Ezav: \"Da ti barem ostavim nekoliko ljudi koji se sa mnom nalaze.\" Ali on odgovori: \"Čemu to? Neka ja samo nađem milost u očima svoga gospodara!\"');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 33, 16, 'Tako se Ezav onog dana zaputi natrag u Seir,');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 33, 17, 'dok je Jakov otišao u Sukot, gdje sebi sagradi kuću, a svom blagu podigne staje. Stoga je onom mjestu dano ime Sukot.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 33, 18, 'Došavši tako iz Padan Arama, Jakov sretno stigne u grad Šekem, koji se nalazi u zemlji kanaanskoj, i postavi svoj šator pred gradom.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 33, 19, 'A komad zemlje na kojoj je postavio svoj šator kupi od sinova Hamora, Šekemova oca, za stotinu kesita.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 33, 20, 'Tu podiže žrtvenik i nazva ga \"El, Bog Izraelov\".');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 34, 1, 'Dina, kći koju je Lea rodila Jakovu, iziđe da posjeti neke žene onoga kraja.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 34, 2, 'Opazi je Hivijac Šekem, sin Hamora, poglavice kraja, pa je pograbi i na silu s njom leže.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 34, 3, 'Njegovo srce prione za Dinu, Jakovljevu kćer, i on se u djevojku zaljubi. Nastojao je pridobiti djevojčino srce.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 34, 4, 'Šekem je govorio i svom ocu Hamoru: \"Onu mi djevojku uzmi za ženu!\"');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 34, 5, 'Jakov sazna da je Šekem obeščastio njegovu kćer Dinu. Ali kako su njegovi sinovi bili uz blago na polju, Jakov nije poduzimao ništa dok oni ne dođu.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 34, 6, 'Uto dođe k Jakovu Šekemov otac Hamor da se s njim sporazumije,');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 34, 7, 'upravo kad su se Jakovljevi sinovi vraćali iz polja. Kad su čuli vijest, ljudi su bili ojađeni i vrlo ljuti. Što je Šekem učinio - legavši s Jakovljevom kćeri - u Izraelu je bila sramota. To se nije smjelo trpjeti.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 34, 8, 'Hamor im reče. \"Moj se sin Šekem svom dušom zaljubio u vašu kćer. Dajte mu je za ženu!');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 34, 9, 'Oprijateljite se s nama: dajite nam svoje kćeri, a naše kćeri uzimajte sebi!');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 34, 10, 'Tako možete živjeti među nama; zemlja je pred vama da se naselite, u njoj se slobodno krećete i stječete imovinu!\"');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 34, 11, 'Potom Šekem reče njezinu ocu i njezinoj braći: \"Da nađem milost u vašim očima, dat ću vam što zatražite.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 34, 12, 'Tražite od mene koliko hoćete: sve što god zapitate dat ću, samo mi dajte djevojku za ženu.\"');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 34, 13, 'Jakovljevi sinovi odgovore Šekemu i njegovu ocu Hamoru - govorili su s prijevarom jer je obeščastio njihovu sestru Dinu -');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 34, 14, 'te im rekoše: \"Ne možemo pristati da svoju sestru damo čovjeku koji nije obrezan, jer bi to za nas bila sramota.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 34, 15, 'Jedino ćemo je dati ako postanete kao i mi, ako obrežete sve svoje muškarce.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 34, 16, 'Onda vam možemo davati svoje kćeri i uzimati vaše sebi, s vama se naseliti i biti jedan rod.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 34, 17, 'A ako ne pristajete na obrezanje, uzet ćemo svoju kćer i otići.\"');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 34, 18, 'Hamoru i Šekemu, Hamorovu sinu, njihov se zahtjev učini povoljan.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 34, 19, 'Mladić nije časio da zahtjev izvrši, jer je čeznuo za Jakovljevom kćeri; a bio je najuvaženiji od svih u očevu domu.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 34, 20, 'Tako Hamor i njegov sin Šekem dođu u svoje gradsko vijeće i obrate se svojim sugrađanima ovako:');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 34, 21, '\"Ovaj je svijet prijazan; neka se među nama u zemlji nasele; neka se po njoj slobodno kreću; ima dosta prostora u zemlji za njih; možemo uzimati njihove kćeri sebi za žene, a njima davati svoje.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 34, 22, 'No ljudi će pristati da među nama žive i s nama budu jedan rod samo ako se svi naši muškarci obrežu kao što su oni obrezani.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 34, 23, 'Zar tako ne bi stoka koju su stekli, sve njihovo blago - bilo naše? Pristanimo, pa neka se među nama nasele!\"');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 34, 24, 'Svi odrasli muškarci koji imaju pravo izaći na gradska vrata poslušaše Hamora i njegova sina Šekema, pa bude obrezan svaki muškarac - svaki koji ima pravo izaći na gradska vrata.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 34, 25, 'A trećega dana, dok su oni još bili u bolovima, dva Jakovljeva sina, Šimun i Levi, Dinina braća, pograbe svaki svoj mač i nesmetano dođu u grad te poubijaju sve muškarce.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 34, 26, 'Sasijeku mačem Hamora i njegova sina Šekema, uzmu Dinu iz Šekemove kuće i odu.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 34, 27, 'Ostali Jakovljevi sinovi dođu na ubijene i opustoše grad što je njihova sestra bila obeščašćena.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 34, 28, 'Što je bilo krupne i sitne stoke i magaradi, u gradu i u polju, otjeraju;');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 34, 29, 'opljačkaju sva njihova dobra, a svu im djecu i žene - sve što je bilo po kućama - odvedu u roblje.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 34, 30, 'Jakov reče Šimunu i Leviju: \"Uveli ste me u nepriliku omrazivši me stanovnicima zemlje, Kanaancima i Perižanima. Ako se ujedine protiv mene i napadnu me, dok je nas ovako malo na broj, istrijebit će me s mojim domom.\"');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 34, 31, 'Oni odgovore: \"Zar da prema našoj sestri postupaju kao prema kakvoj bludnici?\"');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 35, 1, 'Bog reče Jakovu: \"Ustani, idi gore u Betel te ondje ostani! Načini ondje žrtvenik Bogu koji ti se objavio kad si bježao od svoga brata Ezava!\"');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 35, 2, 'I Jakov reče svojoj obitelji i svima koji bijahu s njime: \"Odbacite tuđe kumire koji se nalaze u vašoj sredini; očistite se i preobucite.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 35, 3, 'Idemo gore u Betel; ondje ću načiniti žrtvenik Bogu, koji me uslišao kad sam bio u nevolji i sa mnom bio na putu kojim sam hodio.\"');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 35, 4, 'Oni predaju Jakovu sve tuđe kumire što su ih imali i naušnice što su bile o njihovim ušima, pa ih Jakov zakopa pod hrast kod Šekema.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 35, 5, 'Kad su se zaputili, strah od Boga spopadne okolišna mjesta, tako da nisu išli u potjeru za Jakovljevim sinovima.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 35, 6, 'Jakov stigne u Luz, to jest Betel, u zemlji kanaanskoj, i sav puk što je bio s njim.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 35, 7, 'Ondje sagradi žrtvenik i mjesto nazva El Betel, jer mu se ondje Bog objavio kad on bježaše pred svojim bratom Ezavom.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 35, 8, 'Tada umre Rebekina dojilja Debora te je sahraniše pod Betelom, pod hrastom, koji se otad zove \"Tužni hrast\".');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 35, 9, 'Bog se opet objavi Jakovu kad je stigao iz Padan Arama, te ga blagoslovi.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 35, 10, 'Bog mu reče: \"Ime ti je Jakov, ali se odsad nećeš zvati Jakov nego će Izrael biti tvoje ime.\" Tako ga prozva Izraelom.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 35, 11, 'Onda mu Bog reče: \"Ja sam El Šadaj - Bog Svesilni! Budi rodan i množi se! Od tebe poteći će narod, mnoštvo naroda, i kraljevi iz tvog će izaći krila.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 35, 12, 'Zemlju što je dadoh Abrahamu i Izaku tebi predajem; i potomstvu tvojem poslije tebe zemlju ću ovu dati.\"');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 35, 13, 'A onda Bog ode od njega gore.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 35, 14, 'Na mjestu gdje je Bog s njim govorio Jakov uspravi stup, stup od kamena; na njemu prinese žrtvu i izli ulja.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 35, 15, 'A mjesto gdje mu je Bog govorio Jakov nazva Betel.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 35, 16, 'Potom odu iz Betela. Još bijaše malo puta do Efrate, a Rahela se nađe pri porođaju. Napali je teški trudovi.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 35, 17, 'Kad su joj porođajni bolovi bili najteži, reče joj babica: \"Ne boj se jer ti je i ovo sin!\"');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 35, 18, 'Kad se rastavljala s dušom - jer umiraše Rahela - nadjenu sinu ime Ben Oni; ali ga otac prozva Benjamin.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 35, 19, 'Tako umrije Rahela. Sahrane je na putu u Efratu, to jest Betlehem.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 35, 20, 'A na njezinu grobu Jakov podigne spomenik - onaj što je na Rahelinu grobu do danas.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 35, 21, 'Izrael krenu dalje te razape svoj šator s onu stranu Migdal-Edera.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 35, 22, 'Dok je Izrael boravio u onom kraju, ode Ruben i legne s Bilhom, priležnicom svoga oca. Sazna za to Izrael. Izrael je imao dvanaest sinova.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 35, 23, 'S Leom: Rubena, koji je Jakovljev prvorođenac, Šimuna, Levija, Judu, Jisakara i Zebuluna;');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 35, 24, 's Rahelom: Josipa i Benjamina;');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 35, 25, 's Bilhom, Rahelinom sluškinjom: Dana i Naftalija;');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 35, 26, 'sa Zilpom, sluškinjom Leinom: Gada i Ašera. To su Jakovljevi sinovi što su mu se rodili u Padan Aramu.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 35, 27, 'Jakov dođe k svome ocu Izaku u Mamru u Kirjat Arbu, to je Hebron - gdje su boravili Abraham i Izak kao pridošlice.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 35, 28, 'Kad je Izaku bilo sto i osamdeset godina, umrije.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 35, 29, 'Izak izdahne i umre, starac i godinama zasićen, te bude pridružen svojim precima. Sahrane ga njegovi sinovi, Ezav i Jakov.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 36, 1, 'Ovo su potomci Ezava, koji se zvao i Edom.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 36, 2, 'Ezav je uzeo sebi žene od kanaanskih djevojaka: Adu, kćer Hetita Elona; Oholibamu, kćer Ane, unuku Sibeona Horijca;');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 36, 3, 'i Basematu, kćer Jišmaelovu, sestru Nebajotovu.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 36, 4, 'Ada Ezavu rodi Elifaza, a Basemata rodi Reuela,');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 36, 5, 'Oholibama rodi Jeuša, Jalama i Koraha. To su Ezavovi sinovi koji se rodiše u zemlji kanaanskoj.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 36, 6, 'Ezav uzme svoje žene, svoje sinove, svoje kćeri, svu čeljad svoga doma; svoju stoku - krupnu i sitnu; svu imovinu što ju je namakao u zemlji kanaanskoj, pa ode u zemlju seirsku, daleko od svog brata Jakova.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 36, 7, 'Njihov se, naime, posjed jako uvećao te nisu mogli ostati zajedno: kraj u kojem su boravili nije ih mogao izdržavati zbog njihova blaga.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 36, 8, 'Tako se Ezav - Edom nazvani - naseli u brdskom kraju Seiru.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 36, 9, 'Ovo je, dakle, potomstvo Ezava, praoca Edomaca, u brdskom kraju Seiru.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 36, 10, 'Ovo su imena Ezavovih sinova: Elifaz, sin Ezavove žene Ade; Reuel, sin Ezavove žene Basemate.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 36, 11, 'Elifazovi su sinovi bili: Teman, Omar, Sefo, Gatam i Kenaz.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 36, 12, 'Timna je bila inoča Ezavova sina Elifaza; ona je Elifazu rodila Amaleka. To su potomci Ezavove žene Ade.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 36, 13, 'A ovo su sinovi Reuelovi: Nahat, Zerah, Šama i Miza. Oni su bili sinovi Ezavove žene Basemate.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 36, 14, 'A ovo su opet sinovi Ezavove žene Oholibame, Anine kćeri, unuke Sibeonove; ona je Ezavu rodila Jeuša, Jalama i Koraha.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 36, 15, 'Ovo su rodovske glave Ezavovih potomaka. Potomci Ezavova prvorođenca Elifaza: knez Teman, knez Omar, knez Sefo, knez Kenaz,');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 36, 16, 'knez Korah, knez Gatam i knez Amalek. To su rodovski glavari Elifazovi u zemlji edomskoj; to su potomci Adini.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 36, 17, 'A ovo su potomci Ezavova sina Reuela: knez Nahat, knez Zerah, knez Šama i knez Miza. To su rodovski glavari Reuelovi u zemlji edomskoj; to su potomci Ezavove žene Basemate.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 36, 18, 'A ovo su potomci Ezavove žene Oholibame: knez Jeuš, knez Jalam i knez Korah. To su rodovski glavari Ezavove žene Oholibame, kćeri Anine.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 36, 19, 'To su bili sinovi Ezava-Edoma, njihovi knezovi.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 36, 20, 'A ovo su sinovi Seira Horijca, žitelji one zemlje: Lotan, Šobal, Sibeon, Ana,');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 36, 21, 'Dišon, Eser i Dišan. To su koljenovići Horijci, sinovi Seirovi, u zemlji edomskoj.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 36, 22, 'Lotanovi sinovi bili su: Hori i Hemam; a sestra Lotanova bila je Timna.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 36, 23, 'Ovo su bili sinovi Šobalovi: Alvan, Manahat, Ebal, Šefo i Onam.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 36, 24, 'Sinovi Sibeonovi bijahu Aja i Ana. Ana je onaj koji je našao vruća vrela u pustari dok je čuvao magarad svoga oca Sibeona.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 36, 25, 'Ovo su bila djeca Ane: sin Dišon i Anina kći Oholibama.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 36, 26, 'Ovo su bili sinovi Dišonovi: Hemdan, Ešban, Jitran i Keran.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 36, 27, 'Ovo su bili sinovi Eserovi: Bilhan, Zaavan i Akan.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 36, 28, 'A sinovi Dišanovi bili su: Uz i Aran.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 36, 29, 'Ovo su knezovi Horijaca: knez Lotan, knez Šobal, knez Sibeon, knez Ana,');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 36, 30, 'knez Dišon, knez Eser i knez Dišan. To su bili knezovi Horijaca, glavar za glavarom, u zemlji seirskoj.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 36, 31, 'Evo kraljeva koji su kraljevali u edomskoj zemlji prije nego je zavladao kralj sinova Izraelovih.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 36, 32, 'Beorov sin Bela vladao je u Edomu; njegov se grad zvao Dinhaba.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 36, 33, 'Kad je umro Bela, na njegovo se mjesto zakraljio Jobab, sin Zeraha iz Bosre.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 36, 34, 'Kad je umro Jobab, zakraljio se na njegovo mjesto Hušam iz temanske zemlje.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 36, 35, 'Kad je umro Hušam, zakraljio se na njegovo mjesto Bedadov sin Hadad, koji je potukao Midjance na Moapskom polju. Ime je njegovu gradu bilo Avit.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 36, 36, 'Kad je umro Hadad, zakraljio se na njegovo mjesto Samla iz Masreke.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 36, 37, 'Kad je umro Samla, zakraljio se na njegovo mjesto Šaul iz Rehobota na Rijeci.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 36, 38, 'Kad umrije Šaul, zavlada Baal Hanan, Akborov sin.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 36, 39, 'Kad je umro Baal Hanan, Akborov sin, vladaše Hadad. Ime je njegovu gradu bilo Pai. Žena mu se zvala Mehetabela. Bila je kći Matredova, iz Me Zahaba.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 36, 40, 'Ovo su imena Ezavovih knezova s njihovim nazivima po rodovima i smještaju: knez Timna, knez Alva, knez Jetet,');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 36, 41, 'knez Oholibama, knez Ela, knez Pinon,');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 36, 42, 'knez Kenaz, knez Teman, knez Mibzar,');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 36, 43, 'knez Magdiel i knez Iram. To su bili knezovi edomski, prema njihovim naseljima u zemlji koju su zaposjeli. To je Ezav, praotac Edomaca.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 37, 1, 'A Jakov se bijaše nastanio u zemlji gdje je njegov otac boravio kao pridošlica - u zemlji kanaanskoj.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 37, 2, 'Evo nasljedstva Jakovljeva. Kao mladić, u dobi od sedamnaest godina, Josip je čuvao stada sa svojom braćom, sinovima Bilhe i Zilpe, koje bijahu žene njegova oca. Josip je ocu svome donosio zle glasove o njima.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 37, 3, 'Izrael je volio Josipa više nego ijednog svoga sina jer je bio dijete njegove staračke dobi; i on mu napravi kićenu haljinu.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 37, 4, 'Kako njegova braća opaze da ga njihov otac voli više od svih drugih svojih sinova, zamrze ga toliko da mu nisu mogli ni prijaznu riječ progovoriti.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 37, 5, 'Jednom Josip usni san i kaza ga svojoj braći, a oni ga zbog toga još više zamrze.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 37, 6, '\"Poslušajte\", reče im, \"san što sam ga usnio!');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 37, 7, 'Pomislite! Vezali smo nasred polja snopove, kadli se najednom moj snop uspravi i stade uzgor. Uto se vaši snopovi okupe okolo i duboko se poklone mom snopu.\"');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 37, 8, 'Njegova ga braća upitaše: \"Kaniš li nad nama zakraljevati? Hoćeš li nam biti gospodar?\" I još ga više zamrze zbog njegova pričanja o snovima.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 37, 9, 'Usni on još jedan san te ga ispriča svojoj braći: \"Još sam jedan san usnuo. Pazite! Sunce, mjesec i jedanaest zvijezda duboko mi se klanjahu!\"');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 37, 10, 'Kad je to ispričao svome ocu, ukori ga otac i reče mu: \"Što znači taj san što si ga usnuo? Zar ćemo doći ja, tvoja majka i tvoja braća pa ti se do zemlje klanjati?\"');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 37, 11, 'I dok su braća od zavisti bila ljuta na nj, njegov je otac razmišljao o svemu.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 37, 12, 'Jednom njegova braća odu čuvati očeva stada blizu Šekema.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 37, 13, 'Izrael reče Josipu: \"Tvoja braća čuvaju stada kod Šekema, pa hajde da te pošaljem k njima.\" On mu odgovori: \"Dobro, idem.\"');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 37, 14, 'Potom će mu otac: \"Hajde i vidi kako su ti braća i stoka pa mi javi.\" Tako ga otpremi iz doline Hebrona, i on stigne u Šekem.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 37, 15, 'Neki čovjek nađe ga gdje luta poljem pa ga upita: \"Što tražiš?\"');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 37, 16, '\"Tražim braću\", odgovori. \"Možeš li mi kazati gdje čuvaju stada?\"');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 37, 17, 'A čovjek reče: \"Odavde su otišli. Čuo sam ih gdje govore: \'Hajdemo u Dotan.\'\" Tako Josip ode za svojom braćom i nađe ih u Dotanu.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 37, 18, 'Oni ga opaze izdaleka; prije nego im se približio, počnu se dogovarati da ga ubiju.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 37, 19, 'I jedan drugom reče: \"Eno stiže onaj sanjar!');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 37, 20, 'Hajde da ga sad ubijemo i bacimo u kakvu čatrnju! Možemo kazati da ga je proždrla divlja zvijer. Vidjet ćemo što će biti od njegovih snova!\"');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 37, 21, 'Ali kad je to čuo Ruben, pokuša da ga izbavi iz njihovih šaka. I reče: \"Nemojmo oduzimati njegova života!');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 37, 22, 'Ne prolijevajte krvi\" - dalje je govorio Ruben. \"Bacite ga u čatrnju u pustari; ali ne dižite na nj ruke!\" Htio ga je tako izbaviti iz njihovih šaka i odvesti ocu.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 37, 23, 'Ali kad je Josip stigao braći, oni s Josipa svuku njegovu haljinu, haljinu kićenu što je bila na njemu;');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 37, 24, 'pograbe ga i bace u čatrnju. Čatrnja je bila prazna; nije bilo u njoj vode.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 37, 25, 'Potom sjednu da ručaju. Kako podignu svoje oči, opaze povorku Jišmaelaca gdje dolazi iz Gileada. Deve su im nosile mirodije, balzam i mirisavu smolu da ih preprodaju u Egipat.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 37, 26, 'Tada reče Juda svojoj braći: \"Što ćemo postići ako ubijemo svog brata a krv njegovu sakrijemo?');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 37, 27, 'Hajde da ga prodamo Jišmaelcima; ali ne dižimo na nj ruke. TÓa on je naš brat, naše meso.\" Braća ga poslušaju.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 37, 28, 'Uto naiđu ljudi, midjanski trgovci. Braća izvuku Josipa iz čatrnje i prodaju ga za dvadeset srebrnika Jišmaelcima, a oni Josipa dovedu u Egipat.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 37, 29, 'Kad se Ruben vratio k čatrnji i vidio da Josipa nema u čatrnji, razdere svoju odjeću.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 37, 30, 'A kad se vratio svojoj braći, povika: \"Dječaka nema! Kamo ću ja sad?\"');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 37, 31, 'A oni uzmu Josipovu haljinu, zakolju jedno kozle i haljinu zamoče u krv.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 37, 32, 'Kićenu haljinu otpreme ocu i poruče: \"Ovo smo našli; gledaj je li ovo haljina tvoga sina ili nije.\"');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 37, 33, 'Prepozna je on pa reče: \"Haljina je moga sina! Divlja ga je zvijer rastrgla! Na komade je Josip rastrgan!\"');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 37, 34, 'I razdere Jakov svoje haljine, stavi pokorničku kostrijet oko bokova i dugo vremena oplakivaše svoga sina.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 37, 35, 'Svi su ga njegovi sinovi i sve njegove kćeri nastojali utješiti, ali se on ne mogaše utješiti. Govorio je: \"Ne, sići ću k svome sinu u Šeol tugujući!\" Tako ga je oplakivao njegov otac.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 37, 36, 'A Midjanci ga prodaju u Egipat Potifaru, dvoraninu faraonovu, zapovjedniku straže.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 38, 1, 'Otprilike u to vrijeme Juda ode od svoje braće te okrenu nekom Adulamcu komu ime bijaše Hira.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 38, 2, 'Tu Juda zapazi kćer jednog Kanaanca - zvao se Šua - i njome se oženi. Priđe njoj');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 38, 3, 'te ona zače i rodi sina, komu dade ime Er.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 38, 4, 'Opet ona zače, rodi sina i dade mu ime Onan.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 38, 5, 'Još jednog sina rodi te mu nadjene ime Šela. Nalazila se u Kezibu kad je njega rodila.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 38, 6, 'Juda oženi svoga prvorođenca Era djevojkom kojoj bijaše ime Tamara.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 38, 7, 'Ali Judin prvorođenac Er uvrijedi Jahvu i Jahve ga pogubi.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 38, 8, 'Tada reče Juda Onanu: \"Priđi k udovici svoga brata, izvrši prema njoj djeversku dužnost i tako očuvaj lozu svome bratu!\"');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 38, 9, 'Ali Onan, znajući da se sjeme neće računati kao njegovo, ispuštaše ga na zemlju kad god bi prišao bratovoj udovici, tako da ne dade potomstva svome bratu.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 38, 10, 'To što je činio uvrijedilo je Jahvu, pa i njega pogubi.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 38, 11, 'Onda Juda reče svojoj nevjesti Tamari: \"Ostani kao udovica u domu svoga oca dok poodraste moj sin Šela.\" Bojao se, naime, da bi i on mogao umrijeti kao i njegova braća. I tako Tamara ode da živi u očevu domu.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 38, 12, 'Dugo vremena poslije toga umre Šuina kći, Judina žena. Kad je prošlo vrijeme žalosti, Juda ode, zajedno sa svojim prijateljem Adulamcem Hirom, u Timnu da striže svoje ovce.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 38, 13, 'Obavijeste Tamaru: \"Eno ti je svekar\", rekoše joj, \"na putu u Timnu da striže ovce.\"');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 38, 14, 'Ona svuče udovičko ruho, navuče koprenu i zamota se pa sjede na ulazu u Enajim, što je na putu k Timni. Vidjela je, naime, da je Šela odrastao, ali nju još ne udaše za nj.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 38, 15, 'Kad je Juda opazi, pomisli da je bludnica, jer je bila pokrila lice.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 38, 16, 'Svrati se on k njoj i reče: \"Daj da ti priđem!\" Nije znao da mu je nevjesta. A ona odgovori: \"Što ćeš mi dati da uđeš k meni?\"');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 38, 17, '\"Spremit ću ti jedno kozle od svoga stada\", odgovori. \"Treba da ostaviš jamčevinu dok ga ne pošalješ.\"');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 38, 18, 'A on zapita: \"Kakvu jamčevinu da ti ostavim?\" Ona odgovori: \"Svoj pečatnjak o vrpci i štap što ti je u ruci.\" Dade joj jedno i drugo, a onda priđe k njoj i ona po njem zače.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 38, 19, 'Potom ona ustade i ode; skide sa sebe koprenu i opet se odjenu u svoje udovičko ruho.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 38, 20, 'Uto Juda pošalje kozle po svom prijatelju Adulamcu da iskupi jamčevinu iz ruku žene, ali je nije mogao naći.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 38, 21, 'Upita ljude u mjestu: \"Gdje je bludnica što se nalazila uz put u Enajim?\" Oni mu odgovore: \"Ovdje nije nikad bilo bludnice.\"');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 38, 22, 'Tako se on vrati k Judi pa reče: \"Nisam je mogao naći. Osim toga, ljudi mi u mjestu rekoše da ondje nije nikad bilo bludnice.\"');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 38, 23, 'Onda reče Juda: \"Da ne ostanemo za ruglo, neka ih drži! Slao sam joj, eto, ovo kozle, ali je ti nisi našao.\"');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 38, 24, 'Otprilike poslije tri mjeseca donesoše vijest Judi: \"Tvoja nevjesta Tamara odala se bludništvu; čak je u bludničenju i začela.\" \"Izvedite je\", naredi Juda, \"pa neka se spali!\"');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 38, 25, 'Dok su je izvodili, ona poruči svekru: \"Začela sam po čovjeku čije je ovo.\" Još doda: \"Vidi čiji je ovaj pečatnjak o vrpci i ovaj štap!\"');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 38, 26, 'Juda ih prepozna pa reče: \"Ona je pravednija nego ja, koji joj nisam dao svoga sina Šelu.\" Ali više s njom nije imao posla.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 38, 27, 'Kad joj je došlo vrijeme da rodi, pokaže se da nosi blizance.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 38, 28, 'Dok je rađala, jedan od njih pruži ruku van. Nato babica priveže za njegovu ruku crven konac govoreći: \"Ovaj je izišao prvi.\"');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 38, 29, 'Ali baš tada on uvuče ruku te iziđe njegov brat. A ona reče: \"Kakav li proder napravi!\" Stoga mu nadjenu ime Peres.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 38, 30, 'Poslije iziđe njegov brat koji je oko ruke imao crveni konac. Njemu dadoše ime Zerah.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 39, 1, 'Josipa dovedoše u Egipat. Tu ga od Jišmaelaca koji su ga onamo doveli kupi Egipćanin Potifar, dvoranin faraonov i zapovjednik njegove tjelesne straže.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 39, 2, 'Jahve je bio s Josipom, zato je u svemu imao sreću: Egipćanin ga uzme k sebi u kuću.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 39, 3, 'Vidje njegov gospodar da je Jahve s njim i da svemu što mu ruka poduzme Jahve daje uspjeh;');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 39, 4, 'zavolje on Josipa, uze ga za dvoranina i postavi ga za upravitelja svoga doma i povjeri mu sav svoj imetak.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 39, 5, 'I otkad mu je povjerio upravu svoga doma i svega svog imetka, blagoslovi Jahve dom Egipćaninov zbog Josipa: blagoslov Jahvin bijaše na svemu što je imao - u kući i u polju.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 39, 6, 'I tako sve svoje prepusti brizi Josipovoj te se više ni za što nije brinuo, osim za jelo što je jeo. A Josip je bio mladić stasit i naočit.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 39, 7, 'Poslije nekog vremena žena njegova gospodara zagleda se u Josipa i reče mu: \"Legni sa mnom!\"');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 39, 8, 'On se oprije i reče ženi svoga gospodara: \"Gledaj! Otkako sam ja ovdje, moj se gospodar ne brine ni za što u kući; sve što ima meni je povjerio.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 39, 9, 'On u ovoj kući nema više vlasti negoli ja i ništa mi ne krati, osim tebe, jer si njegova žena. Pa kako bih ja mogao učiniti tako veliku opačinu i sagriješiti protiv Boga!\"');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 39, 10, 'Iako je Josipa salijetala iz dana u dan, on nije pristajao da uz nju legne; nije joj prilazio.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 39, 11, 'Jednog dana Josip uđe u kuću na posao. Kako nikog od služinčadi nije bilo u kući,');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 39, 12, 'ona ga uhvati za ogrtač i reče: \"Legni sa mnom!\" Ali on ostavi svoj ogrtač u njezinoj ruci, otrže se i pobježe van.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 39, 13, 'Vidjevši ona da je u njezinoj ruci ostavio ogrtač i pobjegao van,');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 39, 14, 'zovne svoje sluge te im reče: \"Gledajte! Trebalo je da nam dovede jednog Hebrejca da se s nama poigrava. Taj k meni dođe da sa mnom legne, ali sam ja na sav glas zaviknula.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 39, 15, 'A čim je čuo kako vičem, ostavi svoj ogrtač pokraj mene i pobježe van.\"');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 39, 16, 'Uza se je držala njegov ogrtač dok mu je gospodar došao kući.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 39, 17, 'Onda i njemu kaza istu priču: \"Onaj sluga Hebrejac koga si nam doveo dođe k meni da sa mnom ljubaka!');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 39, 18, 'Ali čim je čuo kako vičem, ostavi svoj ogrtač pokraj mene i pobježe van.\"');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 39, 19, 'Kad je njegov gospodar čuo pripovijest svoje žene koja reče: \"Eto, tako sa mnom tvoj sluga\", razgnjevi se.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 39, 20, 'Gospodar pograbi Josipa i baci ga u tamnicu - tamo gdje su bili zatvoreni kraljevi utamničenici. I osta u tamnici.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 39, 21, 'Ali je Jahve bio s njim, iskaza naklonost Josipu te on nađe milost u očima upravitelja tamnice.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 39, 22, 'Tako upravitelj tamnice preda u Josipove ruke sve utamničenike koji su se nalazili u tamnici; i ondje se ništa nije radilo bez njega.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 39, 23, 'Budući da je Jahve bio s njim, upravitelj tamnice nije nadgledao ništa što je Josipu bilo povjereno: Jahve bijaše s njim, i što god bi poduzeo, Jahve bi to okrunio uspjehom.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 40, 1, 'Poslije toga peharnik se i pekar egipatskog kralja ogriješe o svoga gospodara, kralja egipatskog.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 40, 2, 'Faraon se razljuti na svoja dva dvoranina, glavnog peharnika i glavnog pekara,');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 40, 3, 'te ih stavi u zatvor, u zgradu zapovjednika tjelesne straže - u istu tamnicu gdje je i Josip bio zatvoren.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 40, 4, 'Zapovjednik tjelesne straže odredi Josipa da ih poslužuje. Pošto su proveli u zatvoru neko vrijeme,');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 40, 5, 'obojica njih - peharnik i pekar egipatskog kralja, utamničenici - usnu san jedne te iste noći. Svaki je usnuo svoj san; i svaki je san imao svoje značenje.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 40, 6, 'Kad je Josip ujutro došao k njima, opazi da su neraspoloženi.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 40, 7, 'Upita faraonove dvorane koji su bili s njim u zatvoru u zgradi njegova gospodara: \"Zašto ste danas tako potišteni?\"');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 40, 8, 'Odgovore mu: \"Sne smo usnuli, ali nikog nema da nam ih protumači.\" Josip im reče: \"Zar tumačenje ne spada na Boga? Dajte, pričajte mi!\"');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 40, 9, 'Onda je glavni peharnik ispripovjedio Josipu svoj san: \"Sanjao sam da je preda mnom lozov trs.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 40, 10, 'Na trsu bile tri mladice. I tek što je propupao, procvjeta i na njegovim grozdovima sazru bobe.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 40, 11, 'Kako sam u ruci držao faraonov pehar, uzmem grožđa, istiještim ga u faraonov pehar, a onda stavim pehar u faraonovu ruku.\"');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 40, 12, 'Josip mu reče: \"Ovo ti je značenje: tri mladice tri su dana.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 40, 13, 'Poslije tri dana faraon će te pomilovati i vratiti na tvoje mjesto; opet ćeš stavljati pehar faraonu u ruku, kao i prije, dok si mu bio peharnik.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 40, 14, 'Kada ti bude opet dobro, sjeti se da sam i ja bio s tobom, pa mi učini ovu uslugu: spomeni me faraonu i pokušaj me izvesti iz ove kuće.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 40, 15, 'Jer, zbilja, bio sam silom odveden iz zemlje Hebreja; ni ovdje nisam ništa skrivio, a baciše me u tamnicu.\"');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 40, 16, 'Kad je glavni pekar vidio kako je Josip dao dobro tumačenje, reče mu: \"Usnuh da su mi na glavi tri bijele košare.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 40, 17, 'U najgornjoj bilo svakovrsna peciva što ga pekar pripravlja faraonu, ali su ptice jele iz košare povrh moje glave.\"');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 40, 18, 'Josip odgovori: \"Ovo je značenje: tri košare tri su dana.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 40, 19, 'Poslije tri dana faraon će uzdići tvoju glavu i o drvo te objesiti te će ptice jesti meso s tebe.\"');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 40, 20, 'I zaista, trećega dana, kad je faraon priredio gozbu za sve svoje službenike - bio mu je rođendan - iz sredine svojih službenika izluči glavnog peharnika i glavnog pekara.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 40, 21, 'Vrati glavnog peharnika u peharničku službu te je i dalje stavljao pehar u faraonovu ruku,');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 40, 22, 'a glavnog pekara objesi, kako je Josip protumačio.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 40, 23, 'Ipak se glavni peharnik nije sjetio Josipa - zaboravio je na nj.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 41, 1, 'Poslije dvije godine usnu faraon da stoji pokraj Nila.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 41, 2, 'Iz Nila iziđe sedam krava, lijepih i debelih; pasle su po šašu.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 41, 3, 'Ali odmah poslije njih iz Nila iziđe sedam drugih krava, ružnih i mršavih, te stanu uz one krave na obali Nila.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 41, 4, 'Ružne i mršave krave požderu ono sedam lijepih i pretilih, i uto se faraon probudi.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 41, 5, 'Opet zaspi te usnu drugi san: sedam punih i jedrih klasova izraste na jednoj stabljici.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 41, 6, 'Ali, eto, poslije njih uzraste sedam klasova šturih, istočnjakom opaljenih.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 41, 7, 'Šturi klasovi proždru sedam jedrih i punih klasova. I faraon se probudi, i gle: bio je to san.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 41, 8, 'Ujutro faraon bijaše uznemiren u duši, pa pozva sve čarobnjake i sve mudrace egipatske: ispriča im faraon svoje sne, ali mu ih nitko nije mogao protumačiti.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 41, 9, 'Onda progovori faraonov glavni peharnik: \"Moram danas spomenuti jedan svoj propust.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 41, 10, 'Jednom, kad se faraon razljutio na svoje službenike, mene i glavnog pekara stavio je u zatvor u zgradi glavnog upravitelja.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 41, 11, 'Usnusmo san iste noći, i ja i on, ali je svaki od nas usnuo san drugog značenja.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 41, 12, 'Onda je s nama bio neki mladi Hebrej, sluga zapovjednika straže. Ispričasmo njemu svoje sne, a on nam ih protumači: kaza svakom značenje njegova sna.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 41, 13, 'Kako nam ih je protumačio, tako nam se i dogodilo: mene vratiše na moje mjesto, a onoga objesiše.\"');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 41, 14, 'Faraon odmah pošalje po Josipa; izvuku ga brže-bolje iz tamnice; ošišaju mu kosu, obuku novo odijelo i on stupi pred faraona.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 41, 15, 'Onda faraon reče Josipu: \"Usnuo sam san, a nitko ga ne može protumačiti. Čuo sam o tebi da možeš protumačiti san čim ga čuješ.\"');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 41, 16, '\"Ništa ja ne mogu\", odgovori Josip faraonu, \"nego će Bog dati pravi odgovor faraonu.\"');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 41, 17, 'Onda je faraon pripovjedao Josipu: \"U svom snu stojim na obali Nila.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 41, 18, 'I gle! Iz Nila iziđe sedam debelih i lijepih krava. Pasle su po šašu.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 41, 19, 'Poslije njih izađe drugih sedam krava. Bile su mršave, vrlo ružne i koštunjave. Još nikad ne vidjeh onako ružnih krava u svoj zemlji egipatskoj!');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 41, 20, 'I sedam mršavih i ružnih krava proždru prvih sedam debelih krava.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 41, 21, 'Pa iako su ih progutale, nije se vidjelo da im je što u trbuhu: bile su ružne kao i prije. Uto se probudim.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 41, 22, 'Zatim sam u snu vidio kako na jednoj stabljici uzraste sedam punih i lijepih klasova.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 41, 23, 'Ali poslije njih uzraste sedam klasova zgrčenih, šturih, istočnjakom opaljenih.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 41, 24, 'I šturi klasovi proždru sedam jedrih klasova. Kazao sam ovo i vračarima, ali nema nikoga da mi razjasni.\"');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 41, 25, 'Onda Josip reče faraonu: \"Faraonov je san samo jedan: Bog javlja faraonu što kani učiniti.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 41, 26, 'Sedam lijepih krava, to je sedam godina; sedam lijepih klasova opet je sedam godina. Tako je samo jedan san.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 41, 27, 'Sedam mršavih i ružnih krava poslije njih, a tako i sedam praznih, istočnjakom opaljenih klasova, označuje sedam gladnih godina.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 41, 28, 'To je ono što sam već faraonu rekao: Bog objavljuje faraonu što kani učiniti.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 41, 29, 'Dolazi, evo, sedam godina velikog obilja svoj zemlji egipatskoj.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 41, 30, 'A poslije njih nastat će sedam gladnih godina, kada će se zaboraviti sve obilje u zemlji egipatskoj.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 41, 31, 'Kako glad bude harala zemljom, neće se ni znati da je u zemlji bilo obilje - zbog gladi koja će doći - jer će biti vrlo velika.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 41, 32, 'A što se faraonov san ponovio, znači da se Bog na to zaista odlučio i da će to uskoro provesti.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 41, 33, 'Zato neka faraon izabere sposobna i mudra čovjeka te ga postavi nad zemljom egipatskom.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 41, 34, 'Nadalje, neka se faraon pobrine da postavi nadglednika u zemlji koji će kÓupiti petinu sve žetve u zemlji egipatskoj za sedam godina obilja.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 41, 35, 'Neka skupljaju od svakog žita za sedam dobrih godina što dolaze; neka s ovlaštenjem faraonovim sabiru žito za hranu i pohranjuju ga po gradovima.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 41, 36, 'Neka zalihe služe za hranu u zemlji za sedam godina gladi što će snaći zemlju egipatsku, tako da za gladi zemlja ne propadne.\"');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 41, 37, 'Svidje se odgovor faraonu i svim njegovim službenicima.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 41, 38, 'Zato faraon reče svojim službenicima: \"Zar bismo mogli naći drugoga kao što je on, čovjeka koji bi bio tako obdaren duhom Božjim?\"');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 41, 39, 'A onda faraon reče Josipu: \"Otkako je sve to Bog tebi otkrio, nikoga nema sposobna i mudra kao što si ti.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 41, 40, 'Ti ćeš biti upravitelj moga dvora: sav će se moj narod pokoravati tvojim naredbama. Jedino prijestoljem ja ću biti veći od tebe.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 41, 41, 'Postavljam te, evo,\" reče faraon Josipu, \"nad svom zemljom egipatskom.\"');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 41, 42, 'Poslije toga skine faraon sa svoje ruke pečatni prsten i stavi ga Josipu na ruku. Zatim zaodjene Josipa odjećom od najljepše tkanine, a o vrat mu objesi zlatan lanac.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 41, 43, 'Vozio se on u kolima kao njegov zamjenik, a pred njim klicahu: \"Abrek! Na koljena!\" Tako ga postavi nad svu zemlju egipatsku.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 41, 44, 'Još faraon reče Josipu: \"Premda sam ja faraon, neće nitko dići svoje ruke ni noge bez tvog odobrenja u svoj zemlji egipatskoj.\"');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 41, 45, 'Faraon nazva Josipa \"Safenat Paneah\", a za ženu mu dade Asenatu, kćer Poti-Fere, svećenika u Onu. I Josip postade poznat po zemlji egipatskoj.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 41, 46, 'Josipu je bilo trideset godina kad je stupio u službu faraona, kralja egipatskog. A otišavši Josip ispred faraona, putovao je po svoj zemlji egipatskoj.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 41, 47, 'Za sedam rodnih godina zemlja je rađala u obilju;');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 41, 48, 'on je - u tih sedam godina što ih je egipatska zemlja uživala - kÓupio od različite ljetine i hranu pohranjivao u gradove, smještajući u svakom gradu urod iz okolnih polja.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 41, 49, 'Tako Josip nagomila mnogo žita, kao pijeska u moru, pa ga prestade i mjeriti jer mu mjere ne bijaše.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 41, 50, 'Dok još ne nasta gladna godina, Josip imade dva sina koje mu rodi Asenata, kći Poti-Fere, svećenika u Onu.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 41, 51, 'Prvorođencu Josip nadjenu ime Manaše, \"jer Bog je\", reče, \"dao te sam zaboravio svoje teškoće i svoj očinski dom.\"');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 41, 52, 'Drugomu nadjenu ime Efrajim, \"jer Bog me\", reče, \"učinio rodnim u zemlji moje nevolje.\"');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 41, 53, 'Sedam godina obilja koje je uživala zemlja egipatska dođe kraju,');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 41, 54, 'a primače se sedam gladnih godina, kako je Josip prorekao. U svim zemljama bijaše glad, a u svoj zemlji egipatskoj bijaše kruha.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 41, 55, 'A kad je i sva zemlja egipatska osjetila glad, puk zavapi faraonu za kruh; a faraon reče Egipćanima: \"Idite k Josipu i što god vam rekne, činite!\"');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 41, 56, 'Kad se glad proširi po svoj zemlji, Josip rastvori skladišta te je Egipćane opskrbljivao žitom, jer je glad postala žestoka i u zemlji egipatskoj.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 41, 57, 'Sav je svijet išao u Egipat k Josipu da kupuje žita, jer je strašna glad vladala po svem svijetu.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 42, 1, 'Kad je Jakov čuo da u Egiptu ima žita, reče svojim sinovima: \"Što tu zurite jedan u drugoga?');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 42, 2, 'Čujem da ima žita u Egiptu. Otiđite dolje te nam ga odande nabavite da ostanemo na životu i ne pomremo.\"');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 42, 3, 'Tako desetero Josipove braće siđe da nabavi žita iz Egipta.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 42, 4, 'Benjamina, Josipova pravog brata, Jakov ne posla s ostalima. \"Da ga ne bi zadesila kakva nesreća\", govorio je.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 42, 5, 'Među onima koji su išli nabavljati žito, jer u zemlji kanaanskoj vladaše glad, bijahu i sinovi Izraelovi.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 42, 6, 'Josip je bio namjesnik u zemlji; on je dijelio žito svemu svijetu. Dođu tako i Josipova braća i poklone mu se licem do zemlje.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 42, 7, 'Josip prepozna braću čim ih ugleda, ali se prema njima vladao kao stranac i oštro im govorio. Zapita ih: \"Odakle dolazite?\" Odgovore: \"Iz zemlje kanaanske došli smo da kupimo hrane.\"');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 42, 8, 'Iako je Josip prepoznao svoju braću, oni njega nisu prepoznali.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 42, 9, 'Josip se sjeti snova što ih je o njima sanjao. I reče im: \"Vi ste uhode! Došli ste da izvidite slaba mjesta ove zemlje.\"');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 42, 10, 'Oni mu odgovore: \"Ne, gospodaru! Tvoje su sluge došle da nabave hrane.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 42, 11, 'Svi smo sinovi jednog oca; pošteni smo ljudi; sluge tvoje nikad nisu bile uhode.\"');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 42, 12, 'On će im opet: \"Ne, nego ste došli da izvidite slaba mjesta ove zemlje.\"');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 42, 13, 'Nato oni uzvrate: \"Nas, tvojih slugu, bijaše dvanaestero braće - sinovi jednog oca, u zemlji kanaanskoj; najmlađi je sad s ocem, a jednoga više nema.\"');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 42, 14, 'No Josip im dobaci: \"Onako kako sam vam već rekao: vi ste uhode!');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 42, 15, 'Ovako ću vas iskušati: odavde, tako mi faraona, nećete izići ako vaš najmlađi brat ne dođe ovamo!');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 42, 16, 'Pošaljite jednoga između sebe da vam dovede brata, a vi ostali u zatvor! Tako ću iskušati vaše riječi i vidjeti je li u vas istina ili nije. Inače, tako mi faraona, vi ste uhode!\"');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 42, 17, 'Potom ih baci u zatvor na tri dana.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 42, 18, 'Treći im dan reče Josip: \"Izvršite to, i ostat ćete na životu, jer sam ja čovjek bogobojazan.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 42, 19, 'Ako ste pošteni, neka jedan od vas ostane u zatvoru, a vi ostali idite i nosite žito svojim izgladnjelim domovima.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 42, 20, 'Poslije toga dovedite mi svoga najmlađeg brata, tako da se obistine vaše riječi te da ne izginete.\" Oni pristanu.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 42, 21, 'Zatim je jedan drugom govorio: \"Jao nama! Stiže nas kazna zbog našega brata; gledali smo njegovu muku dok nas je molio za milost, ali ga nismo uslišali. Stoga nas je ova nevolja snašla.\"');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 42, 22, 'Ruben im odvrati: \"Zar vam nisam govorio: Ne ogrešujte se o mladića! Ali vi niste slušali. Sad se traži račun za njegovu krv.\"');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 42, 23, 'Nisu znali da ih Josip razumije, jer su se s njim razgovarali preko tumača.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 42, 24, 'On se od njih udalji te zaplaka. Opet se vrati i razgovaraše s njima. Onda izdvoji Šimuna između njih i naredi da bude svezan na njihove oči.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 42, 25, 'Potom Josip zapovjedi da im vreće napune žitom; da svakome njegov novac metnu u vreću i da im daju poputninu. Tako im učine.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 42, 26, 'Tada oni natovare žito na svoje magarce i krenu odande.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 42, 27, 'Kad na prenoćištu jedan od njih otvori svoju vreću da nahrani magarca, opazi svoj novac ozgo u vreći.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 42, 28, '\"Moj je novac vraćen!\" - povika braći. - \"Evo ga u mojoj vreći!\" Zadrhta srce u njima. Zgledaše se, uplašeni, i rekoše: \"Što nam ovo Bog uradi!\"');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 42, 29, 'Došavši k svome ocu Jakovu u zemlju kanaansku, kazaše mu sve što ih je snašlo.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 42, 30, '\"Čovjek koji je gospodar one zemlje\", rekoše, \"oštro nam je govorio i optužio nas kao uhode.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 42, 31, 'Pošteni smo ljudi, kazasmo mu, i nikad nismo bili uhode.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 42, 32, 'Bilo nas je dvanaestero braće, sinovi istog oca, ali jednoga više nema, dok se najmlađi sad nalazi s našim ocem u zemlji kanaanskoj.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 42, 33, 'Ali čovjek koji je gospodar one zemlje reče nam: \'Ovim ću doznati da ste pošteni ljudi: ostavite jednoga brata kod mene, a vi ostali uzmite što vam treba za izgladnjele domove, pa idite.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 42, 34, 'Onda mi dovedite svoga najmlađeg brata, tako da znam da niste uhode, nego pošteni ljudi. Poslije toga vratit ću vam vašeg brata, i vi ćete se moći slobodno kretati u ovoj zemlji.\'\"');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 42, 35, 'Kako su praznili svoje vreće, svaki nađe u vreći svoju kesu. Opazivši to, zapadoše u strah - i oni i njihov otac.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 42, 36, '\"Mene vi ostavljate bez djece!\" - reče im njihov otac. - \"Josipa je nestalo, Šimuna nema, a sad biste odveli i Benjamina. Sve se to na me svaljuje!\"');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 42, 37, 'Onda Ruben reče svome ocu: \"Ubij moja dva sina ako ti ga ja natrag ne dovedem! Predaj ga u moje ruke, i ja ću ti ga vratiti!\"');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 42, 38, '\"Moj sin neće s vama!\" - uzvrati on. - \"Njegov je pravi brat već mrtav, a on je ostao sam. Ako bi ga na putu na koji ćete poći snašla nesreća, u tuzi biste otpravili moju sijedu glavu dolje u Šeol.\"');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 43, 1, 'Strašna glad pritisla zemlju.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 43, 2, 'Kad su pojeli hranu koju bijahu donijeli iz Egipta, njihov im otac reče: \"Idite opet i nabavite nam malo hrane.\"');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 43, 3, 'Nato će mu Juda: \"Onaj nam je čovjek jasno rekao: \'Ne smijete preda me ako vaš brat ne bude s vama.\'');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 43, 4, 'Ako si, dakle, voljan s nama poslati našega brata, mi ćemo otići dolje i kupit ćemo ti žita.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 43, 5, 'Ali ako njega ne pustiš s nama, onda mi tamo i ne idemo, jer nam je onaj zaprijetio: \'Ne smijete preda me ako vaš brat ne bude s vama.\'\"');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 43, 6, '\"Zašto ste mi\", zapita Izrael, \"nanijeli jad rekavši onom čovjeku da imate još jednoga brata?\"');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 43, 7, 'Oni odgovore: \"Čovjek nas je neprestano zapitkivao o nama i o našoj obitelji: \'Je li vam još živ otac? Imate li još kojega brata?\' Mi smo mu odgovarali na pitanja. Kako smo mogli znati da će reći: \'Dovedite svoga brata!\'\"');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 43, 8, 'Potom Juda reče svome ocu Izraelu: \"Pusti dječaka sa mnom pa da se dignemo i krenemo; tako ćemo preživjeti, a ne pomrijeti, i mi, i ti, i naša djeca.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 43, 9, 'Ja za nj jamčim; mene drži odgovornim za nj. Ako ga tebi ne vratim i preda te ga ne dovedem, bit ću ti kriv svega vijeka.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 43, 10, 'TÓa da nismo toliko oklijevali, mogli smo se već i dvaput vratiti.\"');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 43, 11, 'Njihov otac Izrael reče im: \"Kad je tako, neka bude, ali učinite ovo: metnite u torbe najbiranijih proizvoda ove zemlje i ponesite na dar onom čovjeku: nešto balzama, nešto meda i mirodija, mirisne smole, pa lješnjaka i badema.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 43, 12, 'Sa sobom uzmite dvostruko novaca, jer treba vratiti novac koji ste našli u grlima svojih vreća. Možda je ono bila zabuna.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 43, 13, 'Uzmite svoga brata pa se opet zaputite onom čovjeku.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 43, 14, 'Neka Bog Svemogući, El Šadaj, potakne onog čovjeka na milosrđe prema nama te vam pusti i drugoga brata i Benjamina. A ja, moram li bez djece ostati, neka ostanem.\"');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 43, 15, 'Uzmu ljudi darove; uzmu sa sobom dvostruko novaca, povedu Benjamina te siđu u Egipat i stupe pred Josipa.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 43, 16, 'Kad Josip ugleda s njima Benjamina, reče upravitelju svoga kućanstva: \"Odvedi ljude u kuću, zakolji jedno živinče i pripremi, jer će ovi ljudi blagovati sa mnom o podne!\"');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 43, 17, 'Čovjek učini kako je Josip rekao i povede ljude u Josipov dom.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 43, 18, 'Ljudi se pobojaše kad su bili povedeni u dom Josipov te rekoše: \"Zbog novca koji se našao u našim vrećama prvi put vode nas unutra tako da nas napadnu i zajedno s našom magaradi uzmu za robove.\"');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 43, 19, 'Stoga se primaknu upravitelju Josipova doma te mu, na ulazu u kuću, reknu:');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 43, 20, '\"Oprosti, gospodaru! Mi smo i prije jednom dolazili da nabavimo hrane;');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 43, 21, 'i kad smo stigli na prenoćište i otvorili svoje vreće, a to novac svakoga od nas ozgo u njegovoj vreći, naš novac, ista svota. Sad smo ga donijeli sa sobom.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 43, 22, 'A ponijeli smo i drugog novca da kupimo hrane. Mi ne znamo tko nam je stavio novac u naše vreće.\"');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 43, 23, '\"Budite mirni\", reče im on. \"Ne bojte se! Bog vaš i Bog vašega oca stavio je blago u vaše vreće. Vaš je novac k meni stigao.\" Potom im izvede Šimuna.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 43, 24, 'Čovjek zatim uvede ljude u Josipovu kuću; dade im vode da operu noge, a njihovoj magaradi baci p§iće.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 43, 25, 'Potom priprave oni svoje darove za dolazak Josipov o podne, jer su čuli da će ondje ručati.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 43, 26, 'Kad je Josip došao u kuću, dadu mu darove koje su sa sobom donijeli i do zemlje mu se poklone.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 43, 27, 'Upita ih on za zdravlje te će dalje: \"A je li dobro vaš stari otac o kome ste mi govorili? Je li još dobra zdravlja?\"');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 43, 28, '\"Sluga tvoj, otac naš, dobro je i još je dobra zdravlja\", odgovore i duboko se naklone iskazujući poštovanje.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 43, 29, 'Podigavši svoje oči, Josip opazi svoga brata Benjamina - sina svoje majke - te upita: \"Je li ovo vaš najmlađi brat o kome ste mi govorili?\" Onda nastavi: \"Bog ti bio milostiv, sine moj!\"');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 43, 30, 'Josip se poslije toga požuri van jer mu se srce uzbudilo zbog brata; bilo mu je da zaplače. Uđe u jednu sobu i tu se isplaka.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 43, 31, 'Onda opere lice, ponovo se javi i, svladavajući se, naredi: \"Poslužite ručak!\"');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 43, 32, 'Staviše njemu napose, njima napose, a napose opet Egipćanima koji su s njim jeli. Egipćani ne bi mogli jesti s Hebrejima, jer bi to Egipćanima bilo odvratno.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 43, 33, 'I kad posjedaše pred njim, najstariji prema starosti svojoj, a najmlađi prema mladosti svojoj, samo se zgledahu.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 43, 34, 'I naređivaše on da jela ispred njega nose njima, a obrok Benjaminov bijaše pet puta veći od svih ostalih. I pili su i gostili se s njim.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 44, 1, 'Onda Josip naredi upravitelju svoga kućanstva: \"Napuni vreće ovih ljudi hranom koliko mogu ponijeti, a novac svakog stavi u grlo njegove vreće.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 44, 2, 'A moj pehar - onaj od srebra - stavi u grlo vreće najmlađega, zajedno s njegovim novcem za žito.\" On učini kako mu je Josip naredio.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 44, 3, 'Kad je svanulo, otpreme ljude i njihove magarce.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 44, 4, 'Tek što su izišli iz grada - nisu bili odmakli daleko - kad Josip reče upravitelju svoga kućanstva: \"Na noge! Pođi za onim ljudima! Kad ih stigneš, kaži im: \'Zašto uzvraćate zlo za dobro?');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 44, 5, 'Zar iz onog pehara ne pije moj gospodar i ne čita iz njega proricanje? Zlo ste učinili!\'\"');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 44, 6, 'Stigavši ih, ponovi im te riječi.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 44, 7, 'Oni odgovore: \"Zašto nam gospodar govori tako? Daleko bilo od slugu tvojih da učine takvo što!');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 44, 8, 'Čak i novac koji smo našli u svojim vrećama donijeli smo ti natrag iz zemlje kanaanske. Kako bismo onda mogli ukrasti srebra ili zlata iz kuće tvoga gospodara!');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 44, 9, 'Onaj u koga se od tvojih slugu nađe, neka se usmrti, a mi drugi postat ćemo robovi tvome gospodaru.\"');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 44, 10, '\"Premda je ono što predlažeš pravo\", preuzme on, \"ipak će samo onaj u koga se ukradeno pronađe biti moj rob, a ostali bit ćete slobodni.\"');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 44, 11, 'Brže spustiše vreće na zemlju i svaki svoju otvori.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 44, 12, 'On je pretraživao, počevši s najstarijim i završivši s najmlađim. Pehar se nađe u Benjaminovoj vreći.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 44, 13, 'Nato oni razdru svoje haljine; svaki ponovo natovari svoga magarca i vrate se u grad.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 44, 14, 'Kad su Juda i njegova braća ponovo stupili u Josipov dom, još je on bio ondje. Bace se preda nj na zemlju.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 44, 15, 'Onda im Josip reče: \"Kakvo je to djelo što ste ga učinili? Zar ne znate da se čovjek kao što sam ja bavi proricanjem?\"');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 44, 16, 'Nato Juda odgovori: \"Što bismo mogli reći svome gospodaru? Što možemo kazati, čime li se opravdati? Bog je otkrio zlodjelo tvojih slugu. Evo nas za robove svome gospodaru - jednako nas kao i onog u koga se našao pehar.\"');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 44, 17, '\"Daleko od mene da učinim tako!\" - odgovori. \"Nego, onaj u koga se našao pehar bit će moj rob, a vi drugi pođite mirno k svome ocu!\"');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 44, 18, 'Onda mu se Juda primače i reče: \"Gospodaru moj, molim te, dopusti sluzi svojem da rekne riječ ušima gospodara svojega i neka se tvoja srdžba ne razlijeva na tvog slugu. TÓa ti si ravan faraonu.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 44, 19, 'Pitao je moj gospodar svoje sluge: \'Imate li oca ili još kojega brata?\'');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 44, 20, 'Svome smo gospodaru odgovorili: \'Imamo stara oca; on još ima jednog sina, rođena u njegovoj staračkoj dobi. Taj je najmlađi. Njegov je pravi brat umro, tako da je on jedini ostao od svoje majke. Njegov ga otac osobito voli.\'');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 44, 21, 'Potom si rekao svojim slugama: \'Dovedite mi ga ovamo da ga vide moje oči?\'');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 44, 22, 'A mi smo odgovorili svome gospodaru: \'Dječak ne može ostaviti oca; kad bi ga ostavio, njegov bi otac umro.\'');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 44, 23, 'Nato si rekao svojim slugama: \'Ako vaš najmlađi brat s vama ne dođe ovamo, više ne smijete preda me.\'');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 44, 24, 'Kad smo se vratili tvome sluzi, ocu mome, kazali smo mu riječi moga gospodara.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 44, 25, 'Naš nam je otac rekao: \'Idite opet i nabavite nam malo hrane!\'');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 44, 26, 'Odgovorili smo: \'Ne možemo onamo. Samo ako s nama pođe naš najmlađi brat, sići ćemo, jer ne smijemo pred onoga čovjeka ako ne bude s nama naš najmlađi brat.\'');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 44, 27, 'Tvoj sluga, otac moj, odvrati nam: \'Kako znate, žena mi je rodila dva sina.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 44, 28, 'Jedan je nestao, te sam zaključio: sigurno je rastrgan! Odonda ga više nisam vidio.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 44, 29, 'Ako i ovoga od mene odvedete pa ga kakva nesreća snađe, moju ćete sijedu glavu s tugom strovaliti dolje u Šeol.\'');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 44, 30, 'Ako sad dođem k tvome sluzi, ocu svome, a mladić - čiji je život tako povezan s njegovim - ne bude s nama,');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 44, 31, 'on će svisnuti kad vidi da dječaka nema s nama; tako će tvoje sluge strovaliti u tuzi sijedu glavu tvoga sluge, oca našega, dolje u Šeol.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 44, 32, 'Jer tvoj je sluga zajamčio ocu svome za dječaka, rekavši: \'Ako ti ga ne vratim, bit ću kriv svome ocu svega vijeka.\'');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 44, 33, 'Zato, molim te, neka tvoj sluga ostane kao rob mome gospodaru, a dječak neka ide natrag s braćom.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 44, 34, 'Jer, kako mogu k svome ocu ako dječaka nema sa mnom! Ne bih mogao gledati jad što bi snašao moga oca.\"');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 45, 1, 'Josip se više nije mogo svladavati pred onima koji su ga okruživali pa povika: \"Neka svi odstupe!\" Tako nitko nije ostao s Josipom kad se očitovao svojoj braći.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 45, 2, 'Briznuo je u glasan plač, da su ga i Egipćani mogli čuti. Doznalo se za to i na faraonovu dvoru.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 45, 3, '\"Ja sam Josip\", reče Josip svojoj braći. \"Otac mi je, dakle, još na životu!\" Ali mu braća nisu mogla odgovoriti, toliko se zapanjiše pred njim.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 45, 4, 'Onda će opet Josip svojoj braći: \"Primaknite se k meni!\" Kad su se primakli, nastavi: \"Ja sam Josip, vaš brat; onaj koga ste prodali u Egipat.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 45, 5, 'Ali se nemojte uznemirivati i prekoravati što ste me ovamo prodali; jer Bog je onaj koji me pred vama poslao da vas održi u životu.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 45, 6, 'Dvije su već godine što je glad došla na zemlju, a još pet godina neće biti ni oranja ni žetve u zemlji.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 45, 7, 'Zato me Bog poslao pred vama da vam se sačuva ostatak na zemlji te da vam život spasi velikim izbavljenjem.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 45, 8, 'Tako niste vi mene poslali ovamo nego Bog; on me postavio faraonu za oca, gospodara nad svim njegovim domom i vladaocem nad svom zemljom egipatskom.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 45, 9, 'Žurite se k mome ocu te mu recite: \'Ovo ti poručuje tvoj sin Josip: Bog me postavio gospodarem nad svim Egiptom; siđi k meni bez oklijevanja.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 45, 10, 'Nastanit ćeš se u kraju Gošenu. Tako ćeš biti blizu mene: ti, tvoja djeca, tvoja unučad, tvoje ovce i goveda i sve što je tvoje.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 45, 11, 'Ondje ću se za te brinuti, jer će glad potrajati još pet godina. Tako nećeš oskudijevati ni ti, ni tvoja obitelj, niti itko tvoj.\'');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 45, 12, 'Ta svojim očima možete vidjeti, kao što vidi i moj brat Benjamin, da vam to moja usta govore.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 45, 13, 'Pripovjedite ocu o mome visokom položaju u Egiptu i sve što ste vidjeli; i brzo mi ovamo oca dovedite!\"');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 45, 14, 'Potom zagrli brata Benjamina te zaplaka; a plakao je i Benjamin obisnuvši mu oko vrata.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 45, 15, 'Izljubi zatim svu svoju braću, u naručju im se rasplaka. Poslije toga njegova braća zađu s njim u razgovor.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 45, 16, 'Glas se pročuje u faraonovu dvoru: \"Stigla Josipova braća!\" Bilo je to drago faraonu i njegovim dvoranima.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 45, 17, 'Onda faraon reče Josipu: \"Kaži svojoj braći neka učine ovo: \'Natovarite svoje živine i odmah se uputite u zemlju kanaansku.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 45, 18, 'Uzmite svoga oca i svoje obitelji i k meni dođite! Ja ću vam dati najbolju zemlju u Egiptu te ćete uživati od obilja ove zemlje.\'');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 45, 19, 'A naredi i ovo: \'Ovako učinite: Iz zemlje egipatske potjerajte kola za svoju djecu i svoje žene, uzmite oca i dođite.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 45, 20, 'Neka vam se oči ne rastužuju za vašim stvarima, jer sve što je u Egiptu najbolje bit će vaše.\'\"');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 45, 21, 'Sinovi Izraelovi tako učine. Po faraonovoj zapovijedi Josip im dade kola i popudbinu.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 45, 22, 'Svakom od njih dade nove haljine, a Benjaminu dade tri stotine srebrnika i petore haljine.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 45, 23, 'Isto tako pošalje svome ocu: deset magaraca natovarenih najboljim plodovima egipatskim i deset magarica natovarenih žitom, kruhom i namirnicama ocu za put.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 45, 24, 'Isprativši svoju braću na put, reče im: \"Nemojte se putem svađati!\"');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 45, 25, 'I tako oni odoše iz Egipta i stigoše u zemlju kanaansku, k svome ocu Jakovu.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 45, 26, 'Kad mu rekoše: \"Josip je živ i čak vlada nad svom zemljom egipatskom!\", njegovo se srce skameni jer im nije mogao vjerovati.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 45, 27, 'Ali kad mu ispripovjediše sve što im je Josip rekao i kad vidje kola što ih je Josip poslao da ga prevezu, duh njihova oca Jakova oživje.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 45, 28, '\"Dosta\", reče Izrael. \"Sin moj Josip još je živ! Moram poći i vidjeti ga prije nego umrem.\"');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 46, 1, 'Tako Izrael krene na put sa svim što bijaše njegovo i stigne u Beer Šebu te prinese žrtvu Bogu svoga oca Izaka.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 46, 2, 'U noćnom viđenju zovne Bog Izraela: \"Jakove! Jakove!\" On odgovori: \"Evo me!\"');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 46, 3, '\"Ja sam Bog, Bog tvoga oca. Ne boj se sići u Egipat, jer ću ondje od tebe proizvesti velik narod.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 46, 4, 'Ja ću sići u Egipat s tobom i sam ću te vratiti ovamo; a Josip će ti svojom rukom oči zaklopiti.\"');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 46, 5, 'I Jakov krene iz Beer Šebe. Sinovi Izraelovi postave svoga oca Jakova, svoju djecu i svoje žene u kola što ih je faraon poslao da ga prevezu.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 46, 6, 'Uzmu sa sobom svoje blago i dobra što ih bijahu stekli u zemlji kanaanskoj te stignu Jakov i sve njegovo potomstvo u Egipat.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 46, 7, 'Sa sobom je u Egipat poveo svoje sinove i unuke, svoje kćeri i kćeri svojih sinova, sve svoje potomstvo.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 46, 8, 'Ovo su imena Izraelaca - Jakova i njegovih potomaka - koji su stigli u Egipat: Jakovljev prvorođenac Ruben.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 46, 9, 'Rubenovi sinovi: Henok, Falu, Hesron i Karmi.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 46, 10, 'Sinovi Šimunovi: Jemuel, Jamin, Ohad, Jakin, Sohar i Šaul, sin Kanaanke.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 46, 11, 'Sinovi Levijevi: Geršon, Kehat i Merari.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 46, 12, 'Sinovi Judini: Er, Onan, Šela, Peres i Zerah. Er i Onan umrli su u zemlji kanaanskoj. Peresovi sinovi bili su Hesron i Hamul.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 46, 13, 'Sinovi Jisakarovi: Tola, Fuva, Jašub i Šimron.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 46, 14, 'Sinovi Zebulunovi: Sered, Elon i Jahleel.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 46, 15, 'To su sinovi koje je Lea imala s Jakovom u Padan Aramu i još kćerka Dina. U svemu je, dakle, imao sinova i kćeri trideset i troje.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 46, 16, 'Sinovi Gadovi: Sifjon, Hagi, Šuni, Esbon, Eri, Arodi i Areli.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 46, 17, 'Sinovi Ašerovi: Jimna, Jišva, Jišvi, Berija i sestra im Serah. Sinovi Berijini: Heber i Malkiel.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 46, 18, 'To su bili potomci Zilpe, koju je Laban darovao svojoj kćeri Lei. Ona je tako rodila Jakovu šesnaest duša.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 46, 19, 'Sinovi Jakovljeve žene Rahele: Josip i Benjamin.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 46, 20, 'Josipu su se u egipatskoj zemlji rodili Manaše i Efrajim. Rodila mu ih je kći onskog svećenika Poti-Fere.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 46, 21, 'Sinovi Benjaminovi: Bela, Beker, Ašbel, Gera, Naaman, Ehi, Roš, Mupim, Hupim i Ard.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 46, 22, 'To su bili potomci Rahelini koje je rodila Jakovu - u svemu njih četrnaest.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 46, 23, 'Danov je sin Hušim.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 46, 24, 'Sinovi Naftalijevi: Jahseel, Guni, Jeser i Šilem.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 46, 25, 'To su bili potomci Bilhe, koju je Laban dao svojoj kćeri Raheli. Ona je Jakovu rodila sedam potomaka.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 46, 26, 'Tako je sve Jakovljeve čeljadi što je od njega poteklo i u Egipat doselilo - ne uključujući žena Jakovljevih sinova - u svemu šezdeset i šest osoba.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 46, 27, 'I k tome dva sina Josipova što su mu se rodila u Egiptu. Prema tome, sve čeljadi Jakovljeva doma što se naseli u Egiptu bijaše sedamdeset duša.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 46, 28, 'Izrael posla Judu naprijed k Josipu da se pred njim pojavi u Gošenu. Kad stignu u gošenski kraj,');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 46, 29, 'Josip upregne svoja kola i zaputi se u Gošen - u susret svome ocu Izraelu. Stupivši preda nj, pade mu oko vrata i dugo je tako plakao.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 46, 30, 'Onda Izrael reče Josipu: \"Sada, pošto sam rođenim očima vidio da si još živ, mogu umrijeti.\"');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 46, 31, 'Zatim Josip reče svojoj braći i očevoj obitelji: \"Otići ću i obavijestiti faraona; reći ću mu: \'Moja braća i obitelj moga oca, koji su bili u zemlji kanaanskoj, došli su k meni.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 46, 32, 'Oni su ljudi pastiri, uvijek su se bavili stočarstvom; dotjerali su sa sobom svoja stada i sve što im pripada.\'');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 46, 33, 'Tako, kad vas faraon pozove i zapita: \'Čime se bavite?\'');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 46, 34, 'odgovorite: \'Ljudi smo, sluge tvoje, koji se od početka do sad bavimo stočarstvom; i mi i naši preci\', tako da se možete naseliti u gošenskom kraju. Svi su, naime, pastiri Egipćanima mrski.\"');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 47, 1, 'Ode, dakle, Josip te obavijesti faraona: \"Moj otac i moja braća stigoše sa svojim ovcama i govedima i sa svime što imaju iz zemlje kanaanske, i eno ih u gošenskom kraju.\"');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 47, 2, 'I uzevši petoricu između svoje braće, uvede ih faraonu.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 47, 3, 'Onda faraon zapita njegovu braću: \"Čime se bavite?\" Odgovore faraonu: \"Tvoje su sluge stočari, baš kao što su bili naši preci.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 47, 4, 'Došli smo da potražimo kratak boravak u ovoj zemlji\", rekoše faraonu, \"jer je nestalo paše za stada tvojih slugu, strašna glad pritište kanaansku zemlju. Dopusti da se tvoje sluge nastane u gošenskom kraju.\"');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 47, 5, '[5a] Faraon reče Josipu: [6b] \"Neka se, dakle, nastane u gošenskom kraju. A ako znaš da među njima ima prikladnih, postavi ih za nadglednike moga osobnog blaga.\" [5b] Tako, kad Jakov i njegovi sinovi stigoše u Egipat i kad faraon, kralj egipatski, to ču, reče Josipu: \"Budući da su tvoj otac i tvoja braća došli k tebi,');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 47, 6, '[6a] egipatska ti je zemlja na raspolaganju: smjesti svoga oca i svoju braću u najboljem kraju.\"');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 47, 7, 'Josip onda dovede svoga oca Jakova faraonu. Jakov blagoslovi faraona.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 47, 8, 'A faraon upita Jakova: \"Koliko ti je godina?\"');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 47, 9, 'Jakov odgovori faraonu: \"Godina moga lutalačkog življenja ima stotina i trideset. Malo ih je i nesretne su bile godine moga života; ne dostižu brojem godine življenja na zemlji mojih otaca.\"');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 47, 10, 'Poslije toga Jakov se oprosti s faraonom i ode od njega.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 47, 11, 'Tako Josip nastani svoga oca i svoju braću davši im u vlasništvo najljepši kraj egipatske zemlje, u kraju Ramsesovu, kako je faraon naredio.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 47, 12, 'A Josip opskrbi hranom svoga oca, svoju braću i svu očevu obitelj sve do najmanjega.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 47, 13, 'Nigdje nije bilo hrane jer je pritisla strašna glad: izmuči ona i zemlju egipatsku i zemlju kanaansku.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 47, 14, 'Josip pobra sav novac što se nalazio u zemlji egipatskoj i zemlji kanaanskoj u zamjenu za žito koje se prodavalo i odnese novac u faraonov dvor.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 47, 15, 'Kad je nestalo novca u zemlji egipatskoj i zemlji kanaanskoj, svi Egipćani dođu k Josipu te mu reknu: \"Daj nam kruha! Zašto da pomremo pred tvojim očima? Novca više nema.\"');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 47, 16, 'Josip odgovori: \"Predajte svoju stoku pa ću vam dati žita u zamjenu za stoku kad je novca nestalo.\"');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 47, 17, 'Tako su oni dovodili svoju stoku Josipu, a Josip im davaše kruh u zamjenu za konje, za sitnu i krupnu stoku i za magarad. Tako ih je one godine opskrbljivao kruhom u zamjenu za sve njihovo blago.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 47, 18, 'Kad je ona godina prošla, dođu k njemu i druge godine te mu reknu: \"Ne možemo sakriti od svoga gospodara: novca je nestalo, blaga su već ustupljena gospodaru; drugo ništa ne preostaje da gospodaru ustupimo nego sebe i svoje oranice.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 47, 19, 'Zašto da uništimo na tvoje oči i sebe i svoje zemlje? Uzmi i nas i naše zemlje u zakup za kruh, i tako ćemo zajedno sa svojom zemljom postati faraonovi kmetovi; daj sjemena da preživimo: da ne izginemo i da nam oranice ne postanu pustoš!\"');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 47, 20, 'Tako Josip steče faraonu u posjed sve egipatske oranice, jer je svaki Egipćanin, kako ih pritisnu glad, prodao svoje njive. Tako je zemlja postala faraonovo vlasništvo,');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 47, 21, 'a narod od jednog kraja Egipta do drugoga njegovim robljem.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 47, 22, 'Jedino nije preuzeo svećeničkih imanja, jer je faraon davao svećenicima određeni dio, i tako su živjeli od prihoda što im ga je faraon davao. Stoga nisu prodali svojih imanja.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 47, 23, 'Onda Josip reče svijetu: \"Budući da sam danas za faraona prekupio i vas i vašu zemlju, evo vam sjeme pa zasijte zemlju.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 47, 24, 'A kad bude pobiranje ljetine, faraonu ćete davati jednu petinu, dok će četiri petine ostajati vama: za zasijavanje polja, za hranu vama i onima koji su u vašim domovima i za hranu vašoj djeci.\"');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 47, 25, 'Oni odgovore: \"Život si nam spasio! Mi smo zahvalni svome gospodaru što možemo biti faraonovi robovi.\"');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 47, 26, 'Tako Josip napravi za Egipat zemljišni zakon koji i danas vrijedi: petina pripada faraonu; jedino svećenička imanja nisu prešla faraonu.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 47, 27, 'Izraelci se nastaniše u zemlji egipatskoj, u kraju gošenskom; u njem stekoše vlasništvo; bijahu rodni i broj im se veoma umnoži.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 47, 28, 'U zemlji egipatskoj poživje Jakov sedamnaest godina. Tako je duljina Jakovljeva života iznosila sto četrdeset i sedam godina.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 47, 29, 'A kad se približi vrijeme Izraelu da umre, pozva svoga sina Josipa te mu reče: \"Ako mi želiš ugoditi, stavi svoju ruku pod moje stegno kao jamstvo svoje odanosti meni: nemoj me sahraniti u Egiptu!');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 47, 30, 'Kad legnem dolje sa svojim ocima, prenesi me iz Egipta gore i sahrani me u njihovu grobnicu!\" \"Učinit ću kako si rekao\", odgovori.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 47, 31, '\"Zakuni mi se!\" - reče. I on mu se zakle. Tada se Izrael duboko prignu na uzglavlju.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 48, 1, 'Poslije nekog vremena jave Josipu: \"Eno ti je otac obolio.\" Nato on uzme sa sobom svoja dva sina, Manašea i Efrajima.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 48, 2, 'Kad Jakovu rekoše: \"Evo ti je došao sin Josip\", Izrael skupi svoje snage i sjede na postelju.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 48, 3, 'Reče Jakov Josipu: \"Bog Svemožni, El Šadaj, objavi mi se u Luzu, u zemlji kanaanskoj; blagoslov mi dade,');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 48, 4, 'a potom mi reče: \'Učinit ću te rodnim i mnogobrojnim, učinit ću da postaneš skup naroda, a tvome potomstvu poslije tebe dat ću ovu zemlju u posjed zauvijek.\'');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 48, 5, 'Sad, oba tvoja sina što su ti se rodila u zemlji egipatskoj, prije nego sam ja stigao k tebi u Egipat, neka budu moji - Efrajim i Manaše neka budu moji kao i Ruben i Šimun!');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 48, 6, 'A djeca što su ti se rodila poslije njih neka ostanu tvoja; a u svom nasljedstvu neka se zovu po imenu svoje braće.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 48, 7, 'Kad sam se, naime, vraćao iz Padana, na moju žalost, tvoja majka Rahela umrije na putovanju u kanaansku zemlju, tek u maloj udaljenosti od Efrate. Sahranio sam je ondje uz put u Efratu, sadašnji Betlehem.\"');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 48, 8, 'Opazivši Izrael Josipove sinove, zapita: \"Tko su ovi?\"');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 48, 9, 'Josip odgovori svome ocu: \"Sinovi su to moji koje mi je Bog dao ovdje.\" \"Dovedi mi ih da ih blagoslovim\", reče.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 48, 10, 'Izraelu oči oslabile od starosti, nije vidio. Zato mu privede sinove, a on ih poljubi i zagrli.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 48, 11, 'Potom Izrael reče Josipu: \"Nisam očekivao da ću još ikada vidjeti tvoje lice; kad, evo, Bog mi dade da vidim i tvoje potomke.\"');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 48, 12, 'Josip ih tada skine s njegovih koljena i duboko se, sve do zemlje, nakloni.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 48, 13, 'Nato ih uze Josip obojicu - Efrajima svojom desnicom, Izraelu nalijevo, a Manašea svojom ljevicom, Izraelu nadesno - te ih k njemu primače.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 48, 14, 'Ali Izrael ispruži svoju desnicu i stavi je na Efrajimovu glavu, premda je bio mlađi, a svoju ljevicu na glavu Manašeovu - tako je držao ruke unakrst - iako je Manaše bio prvorođenac.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 48, 15, 'Tako je davao svoj blagoslov Josipu govoreći: \"Bog, čijim su putovima hodili oci moji Abraham i Izak, Bog, koji mi je pastir bio otkako postah pa do danas,');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 48, 16, 'anđeo koji me od svakog zla izbavljao - djecu ovu neka blagoslovi! Neka se ime moje i mojih pređa Abrahama i Izaka po njima spominje! U mnoštva se mnogobrojna po zemlji razmnožili!\"');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 48, 17, 'Kad je Josip vidio da je njegov otac položio desnicu na Efrajimovu glavu, njegovim se očima to učini krivo; zato posegne za rukom svoga oca da je pomakne s Efrajimove glave na glavu Manašeovu.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 48, 18, '\"Ne tako, oče moj,\" reče Josip svome ocu, \"jer ovo je prvorođenac; zato stavi desnicu na njegovu glavu!\"');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 48, 19, 'Ali njegov otac to odbije rekavši: \"Znam ja, sine moj, znam; i od njega će postati narod i bit će velik. Ali njegov mlađi brat bit će veći od njega, a njegovo će potomstvo biti mnoštvo.\"');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 48, 20, 'Onoga ih, dakle, dana blagoslovi rekavši: \"Vama nek\' se Izrael blagoslivlja govoreći: Kao što je Efrajimu i Manašeu, nek\' i tebi Bog učini!\" Tako stavi Efrajima pred Manašea.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 48, 21, 'Poslije Izrael reče Josipu: \"Ja ću, evo, naskoro umrijeti; no Bog će biti s vama i opet vas dovesti u zemlju vaših otaca.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 48, 22, 'A tebi ostavljam Šekem, nešto više nego tvojoj braći, što sam ga svojim mačem i lukom osvojio od Amorejaca.\"');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 49, 1, 'Jakov zatim sazva svoje sinove te reče: \"Skupite se da vam kažem što će vas snaći u kasnije vrijeme:');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 49, 2, 'Okupite se, čujte, sinovi Jakovljevi, čujte oca svoga Izraela!');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 49, 3, 'Ti Rubene, moj prvorođenče, snaga ti si moja, prvenac moje muškosti. Ističeš, se ponosom, snagom se ističeš,');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 49, 4, 'no, poput vode nabujao, nećeš više imati prvenstva, jer na ležaj oca svog se pope, moj tad oskvrnu krevet.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 49, 5, 'Šimun i Levi braća su prava! Mačevi im oruđe nasilja.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 49, 6, 'Na njihova vijećanja ja ne silazio, u njihovim zborovima udjela ne imao! U srdžbi su svojoj ljude ubijali; u obijesti bikove sakatili.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 49, 7, 'Prokleta im srdžba, jer je prežestoka! Prokleta im obijest, jer je preokrutna! Razdijelit ću ih po Jakovu, Izraelom raspršiti.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 49, 8, 'Judo! Tvoja braća slavit će te; svagda ti je šaka na šiji dušmana, sinci oca tvoga tebi će se klanjat.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 49, 9, 'Judo, laviću mali! Plijenom si se, sine, udebljao; poput lava, poput lavice legao potrbuške! Tko bi ga dražiti smio?');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 49, 10, 'Od Jude žezlo se kraljevsko, ni palica vladalačka od nogu njegovih udaljiti neće dok ne dođe onaj kome pripada - kome će se narodi pokoriti.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 49, 11, 'Svog magarca za lozu privezuje, mlado magarice svoje za čokot. U vinu on kupa svoju odjeću svoju halju u krvi od grožđa.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 49, 12, 'Oči su mu od vina mutne, zubi bjelji od mlijeka.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 49, 13, 'Zebulun će stanovati uz obalu morsku, luka spasa bit će brodarima, uz bok njegov Sidon će ležati.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 49, 14, 'Jisakar je koščat magarac polegao među ogradama.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 49, 15, 'Vidje da je odmor ugodan, a zemlja lijepa, te leđa svoja pod teret podmetnu i na tlaku pristade.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 49, 16, 'Dan će narod svoj suditi kao svako pleme Izraelovo.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 49, 17, 'Nek\' Dan zmija bude na putu, guja pokraj staze što će konja za zglob ujesti, i njegov konjik nauznak će pasti.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 49, 18, 'U spas tvoj se, Jahve, uzdam!');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 49, 19, 'Gada će pljačkat razbojnici, pljačkom će im za petama biti.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 49, 20, 'U Ašera bit će hrane, poslastica za kraljeve.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 49, 21, 'Naftali je košuta lakonoga koja krasnu lanad mladi.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 49, 22, 'Josip je stablo plodno, plodno stablo kraj izvora, grane svoje grana preko zida.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 49, 23, 'Strijelci njega saletjeli, strijeljali ga, opljačkali.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 49, 24, 'Ali luk mu čvrst ostaje, mišice mu ojačale, rukom Jakog Jakovljeva, imenom Pastira, Stijene Izraela,');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 49, 25, 'Bogom, Ocem tvojim, koji ti pomaže, Svesilnim koji te blagoslivlje blagoslovom ozgo sa nebesa, blagoslovom ozdo iz dubina, blagoslovom iz svih prsa, iz svih utroba!');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 49, 26, 'Blagoslovom klasja i cvjetova, blagoslovom drevnih brda, želja vječnih brežuljaka - nek\' se oni spuste na Josipa, između braće posvećenog!');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 49, 27, 'Benjamin je vuk grabežljivi, lovinu on jutrom jede, a navečer plijen dijeli.\"');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 49, 28, 'Sve su to Izraelova plemena - dvanaest ih na broj - i to im je otac rekao kad ih je blagoslivljao; svakoga je od njih blagoslovio njegovim blagoslovom.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 49, 29, 'Poslije toga im dade ovu naredbu: \"Naskoro ću se pridružiti svojim precima. Sahranite me kraj mojih otaca,');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 49, 30, 'u spilji što se nalazi na polju Efrona, Hetita, u spilji na polju Makpeli, nasuprot Mamri, u zemlji kanaanskoj. To je ona koju je Abraham kupio s poljem od Hetita Efrona za mjesto sahranjivanja.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 49, 31, 'Ondje je sahranjen Abraham i njegova žena Sara; sahranjeni su ondje Izak i njegova žena Rebeka; ondje sam ja sahranio Leu.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 49, 32, 'Polje i spilja na njemu kupljeni su od Hetita.\"');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 49, 33, 'Kad je Jakov tako naputio svoje sinove, povuče noge natrag na postelju te izdahnu - pridruži se svojim precima.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 50, 1, 'Josip se baci na oca, suzama mu oblije lice, izljubi ga.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 50, 2, 'Poslije toga Josip naredi liječnicima koji su se nalazili u njegovoj službi da mu oca balzamiraju, i oni balzamiraše Izraela.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 50, 3, 'Trebalo je četrdeset dana: toliko, naime, traje balzamiranje. Sedamdeset su ga dana Egipćani oplakivali.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 50, 4, 'A kad je prošlo vrijeme oplakivanja, Josip reče onima u dvoru faraonovu: \"Učinite mi milost i prenesite faraonu ovo:');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 50, 5, 'Moj me otac zakleo govoreći: \'Kad umrem, sahrani me u grob koji sam sebi pripravio u zemlji kanaanskoj!\' Dopusti mi da odem gore i sahranim oca, a onda ću se vratiti.\"');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 50, 6, 'Faraon odgovori: \"Otiđi gore i sahrani svoga oca kako si mu se zakleo.\"');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 50, 7, 'Tako Josip ode da sahrani oca. S njim su pošli i svi faraonovi službenici - odličnici njegova dvora i svi dostojanstvenici egipatske zemlje;');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 50, 8, 'sva Josipova obitelj, njegova braća i očeva porodica. Jedino su u gošenskom kraju ostala njihova djeca, njihove ovce i goveda.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 50, 9, 'S njim su išla i kola i konjanici: bila je to vrlo duga povorka.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 50, 10, 'Stigavši u Goren Haatad, s onu stranu Jordana, održaše ondje veliko i svečano naricanje. Josip održa sedmodnevnu žalost za ocem.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 50, 11, 'Kad su stanovnici te zemlje, Kanaanci, vidjeli tugovanje u Goren Haatadu, rekoše: \"To ti je svečano naricanje Egipćana!\" Zato nazovu to mjesto Abel-Misrajim. Nalazi se s onu stranu Jordana.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 50, 12, 'Jakovljevi sinovi učine kako im je naredio otac:');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 50, 13, 'odnesu ga u zemlju kanaansku te ga sahrane u spilji na polju Makpeli kod Mamre, polju što ga je Abraham kupio od Hetita Efrona za sahranjivanje.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 50, 14, 'Pošto je sahranio svoga oca, Josip se vrati u Egipat - on, njegova braća i svi koji su s njim išli da mu oca pokopaju.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 50, 15, 'Kad su Josipova braća vidjela da im je otac umro, rekoše: \"Što ako je Josip na nas ljut i pokuša uzvratiti nam za sve zlo koje smo mi njemu nanijeli?\"');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 50, 16, 'Stoga poruče Josipu ovako: \"Pred svoju smrt tvoj je otac naredio:');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 50, 17, '\'Ovako recite Josipu: Oprosti braći svojoj zlo i grijeh što su onako okrutno prema tebi postupili.\' Oprosti, dakle, uvredu slugama Boga svoga oca!\" Na te riječi Josip brizne u plač.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 50, 18, 'Tada sama njegova braća dođu k njemu, bace se preda nj te mu reknu: \"Evo nas k tebi da budemo tvoji robovi!\"');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 50, 19, 'Josip im odvrati: \"Ne bojte se! TÓa zar sam ja namjesto Boga!');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 50, 20, 'Osim toga, iako ste vi namjeravali da meni naudite, Bog je bio ono okrenuo na dobro: da učini što se danas zbiva - da spasi život velikom narodu.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 50, 21, 'Zato se ne bojte! Ja ću se brinuti za vas i za vašu djecu.\" Tako ih je smirio ljubeznim riječima.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 50, 22, 'Josip ostane u Egiptu zajedno s rodom svojim i očevim. Poživje Josip stotinu i deset godina.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 50, 23, 'Tako je Josip gledao Efrajimovu djecu do trećeg koljena; a rađala se djeca i Makiru, Manašeovu sinu, na Josipovim koljenima.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 50, 24, 'Napokon reče Josip svojoj braći: \"Ja ću, evo, naskoro umrijeti. Ali će se Bog, zacijelo, sjetiti vas i odvesti vas iz ove zemlje u zemlju što ju je pod zakletvom obećao Abrahamu, Izaku i Jakovu.\"');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 50, 25, 'Tada Josip zakune Izraelove sinove: \"Bog će se vas doista sjetiti, i tada ponesite moje kosti odavde!\"');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 50, 26, 'Josip umrije kad mu bijaše sto i deset godina; balzamiraše ga i u Egiptu položiše u lijes.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 1, 1, 'Ovo su imena Izraelovih sinova koji su s Jakovom sišli u Egipat, svaki sa svojim domom:');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 1, 2, 'Ruben, Šimun, Levi i Juda;');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 1, 3, 'Jisakar, Zebulun i Benjamin;');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 1, 4, 'Dan i Naftali; Gad i Ašer.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 1, 5, 'U svemu Jakovljevih potomaka bijaše sedamdeset duša. A Josip je već bio u Egiptu.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 1, 6, 'I umre Josip, a pomru i sva njegova braća i sav onaj naraštaj.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 1, 7, 'Ali su Izraelci bili rodni, namnožili se i silno ojačali, tako da su napučili zemlju.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 1, 8, 'Uto u Egiptu zavlada novi kralj koji nije poznavao Josipa.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 1, 9, 'I reče on svome puku: \"Eto, sinovi su Izraelovi postali narod brojan i moćniji od nas.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 1, 10, 'Hajde, postupimo mudro s njima: spriječimo im porast, da se u slučaju rata ne pridruže našim neprijateljima, da ne udare na nas i napokon ne odu iz zemlje.\"');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 1, 11, 'I postaviše nad njima nadglednike da ih tlače teškim radovima. Tako su faraonu sagradili gradove-skladišta: Pitom i Ramses.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 1, 12, 'Ali što su ih više tlačili, oni se još više množili, napredovali i širili se, tako da su Egipćani strahovali od Izraelaca.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 1, 13, 'I Egipćani se okrutno obore na Izraelce.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 1, 14, 'Ogorčavali su im život teškim radovima: pravljenjem meljte i opeke, različitim poljskim poslovima i svakovrsnim naporima koje im nemilosrdno nametahu.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 1, 15, 'Egipatski se kralj obrati i na hebrejske babice, od kojih jednoj bijaše ime Šifra, a drugoj Pua, pa im naredi:');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 1, 16, '\"Kad u porodu pomažete Hebrejkama, dobro pogledajte oba kamena sjedala: ako je muško dijete, ubijte ga; ako je žensko, neka živi.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 1, 17, 'Ali su se babice bojale Boga i nisu činile kako im je naredio egipatski kralj, nego su ostavljale na životu mušku djecu.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 1, 18, 'Stoga egipatski kralj pozove babice pa im rekne: \"Zašto ste tako radile i na životu ostavljale mušku djecu?\"');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 1, 19, 'Nato babice odgovore faraonu: \"Hebrejke nisu kao egipatske žene. One su životne. Prije nego babica dođe k njima, one već rode.\"');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 1, 20, 'Bog je to babicama za dobro primio. Narod se množio i silno porastao.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 1, 21, 'A kako su se babice bojale Boga, on ih obdari potomstvom.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 1, 22, 'Onda faraon izda naredbu svemu svome narodu: \"Svako muško dijete koje se rodi Hebrejima bacite u Rijeku! Na životu ostavite samo žensku djecu.\"');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 2, 1, 'Neki čovjek od Levijeva koljena ode i oženi se djevojkom Levijkom.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 2, 2, 'Žena zače i rodi sina. Vidjevši kako je krasan, krila ga je tri mjeseca.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 2, 3, 'Kad ga nije mogla više sakrivati, nabavi košaricu od papirusove trstike, oblijepi je smolom i paklinom, u nju stavi dijete i položi ga u trstiku na obali Rijeke.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 2, 4, 'Njegova sestra stane podalje da vidi što će s njime biti.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 2, 5, 'Faraonova kći siđe k Rijeci da se kupa, dok su njezine sluškinje šetale uz obalu Rijeke. Opazi ona košaricu u trstici, pa pošalje sluškinju da je donese.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 2, 6, 'Otvori je i pogleda, a to u njoj dijete! Muško čedo. Plakalo je. Njoj se sažali na nj. \"Bit će to hebrejsko dijete\", reče.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 2, 7, 'Onda njegova sestra rekne faraonovoj kćeri: \"Hoćeš li da ti potražim dojilju među Hebrejkama da ti dijete doji?\"');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 2, 8, '\"Idi!\" - odgovori joj faraonova kći. Tako djevojka ode i pozove djetetovu majku.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 2, 9, '\"Uzmi ovo dijete\", rekne joj faraonova kći, \"i odgoji mi ga, a ja ću te plaćati.\" Tako žena uzme dijete i othrani ga.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 2, 10, 'Kad je dijete odraslo, ona ga odvede faraonovoj kćeri, koja ga posini. Nadjene mu ime Mojsije, \"jer sam ga\", reče, \"iz vode izvadila\".');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 2, 11, 'Jednog dana, kad je Mojsije već odrastao, dođe među svoj narod i vidje njegove muke. Spazi tada kako neki Egipćanin tuče jednoga Hebrejca - brata njegova.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 2, 12, 'Okrene se tamo-amo i, vidjevši da nikoga nema, ubije Egipćanina i zatrpa ga u pijesak.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 2, 13, 'Izađe on i sutradan te zateče dva Hebrejca kako se tuku. \"Zašto tučeš svoga druga?\" - rekne napadaču.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 2, 14, 'Ovaj odvrati: \"Tko te postavi za starješinu i suca našega? Kaniš li ubiti i mene kako si ubio onog Egipćanina?\" Mojsije se uplaši pa će u sebi: \"Tako! Ipak se saznalo.\"');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 2, 15, 'Kad je faraon to dočuo, htjede Mojsija pogubiti. Zato Mojsije pobjegne od faraona i skloni se u midjansku zemlju. Ondje sjedne kraj nekog studenca.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 2, 16, 'Midjanski je svećenik imao sedam kćeri. Dođu one da zahvate vode i naliju pojila, da napoje stado svoga oca.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 2, 17, 'Ali dođu i pastiri te ih potjeraju. Mojsije ustane, obrani ih i stado im napoji.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 2, 18, 'Kad su se vratile svome ocu Reuelu, on ih zapita: \"Kako ste se danas tako brzo vratile?\"');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 2, 19, 'One odgovore: \"Neki Egipćanin obrani nas od pastira i još nam zahvati vode i stado nam napoji.\"');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 2, 20, '\"Gdje je?\" - zapita on svoje kćeri. \"Zašto ste ostavile toga čovjeka? Pozovite ga na objed.\"');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 2, 21, 'Mojsije pristane da ostane kod toga čovjeka. On oženi Mojsija svojom kćeri Siporom.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 2, 22, 'A kad ona rodi sina, on mu nadjene ime Geršon, \"jer sam\", reče, \"stranac u tuđoj zemlji\".');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 2, 23, 'Poslije mnogo vremena umre egipatski kralj. Izraelci su još stenjali u ropstvu. Vapili su, a njihov vapaj za pomoć sred ropstva uzlazio je k Bogu.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 2, 24, 'Bog je čuo njihovo zapomaganje i sjetio se svoga Saveza s Abrahamom, Izakom i Jakovom.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 2, 25, 'I pogleda Bog na Izraelce i zauze se za njih.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 3, 1, 'Mojsije pasao ovce svoga tasta Jitra, midjanskoga svećenika. Goneći tako stado po pustari, dođe do Horeba, brda Božjega.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 3, 2, 'Anđeo mu se Jahvin ukaže u rasplamtjeloj vatri iz jednog grma. On se zagleda: grm sav u plamenu, a ipak ne izgara.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 3, 3, '\"Hajde da priđem, \" reče Mojsije, \"i promotrim ovaj čudni prizor: zašto grm ne sagorijeva.\"');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 3, 4, 'Kad je Jahve vidio kako prilazi da razmotri, iz grma ga Bog zovne: \"Mojsije! Mojsije!\" \"Evo me!\" - javi se.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 3, 5, '\"Ne prilazi ovamo!\" - reče. \"Izuj obuću s nogu! Jer mjesto na kojem stojiš sveto je tlo.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 3, 6, 'Ja sam\", nastavi, \"Bog tvoga oca; Bog Abrahamov, Bog Izakov, Bog Jakovljev.\" Mojsije zakloni lice: bojao se u Boga gledati.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 3, 7, '\"Vidio sam jade svoga naroda u Egiptu\", nastavi Jahve, \"i čuo mu tužbu na tlačitelje njegove. Znane su mi muke njegove.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 3, 8, 'Zato sam sišao da ga izbavim iz šaka egipatskih i odvedem ga iz te zemlje u dobru i prostranu zemlju - u zemlju kojom teče med i mlijeko: u postojbinu Kanaanaca, Hetita, Amorejaca, Perižana, Hivijaca i Jebusejaca.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 3, 9, 'Vapaji sinova Izraelovih dopriješe do mene. I sam vidjeh kako ih Egipćani tlače.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 3, 10, 'Zato, hajde! Ja te šaljem faraonu da izbaviš narod moj, Izraelce, iz Egipta.\"');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 3, 11, '\"Tko sam ja da se uputim faraonu\", odgovori Mojsije Bogu, \"i izvedem Izraelce iz Egipta!\"');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 3, 12, '\"Ja ću biti s tobom\", nastavi. \"I ovo će ti biti znak da sam te ja poslao: kad izvedeš narod iz Egipta, Bogu ćete iskazati štovanje na ovome brdu.\"');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 3, 13, 'Nato Mojsije reče Bogu: \"Ako dođem k Izraelcima pa im kažem: \'Bog otaca vaših poslao me k vama\', i oni me zapitaju: \'Kako mu je ime?\' - što ću im odgovoriti?\"');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 3, 14, '\"Ja sam koji jesam\", reče Bog Mojsiju. Onda nastavi: \"Ovako kaži Izraelcima: \'Ja jesam\' posla me k vama.\"');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 3, 15, 'Dalje je Bog Mojsiju rekao: \"Kaži Izraelcima ovako: \'Jahve, Bog vaših otaca, Bog Abrahamov, Bog Izakov i Bog Jakovljev, poslao me k vama.\' To mi je ime dovijeka, tako će me zvati od koljena do koljena.\"');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 3, 16, '\"Idi, skupi starješine Izraelaca pa im kaži: \'Jahve, Bog otaca - Bog Abrahamov, Izakov i Jakovljev - objavio mi se i rekao mi: Pohodio sam vas i razabrao što vam se čini u Egiptu.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 3, 17, 'Odlučio sam vas izvesti iz egipatske bijede u zemlju Kanaanaca, Hetita, Amorejaca, Perižana, Hivijaca i Jebusejaca - u zemlju kojom teče med i mlijeko!\'');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 3, 18, 'Oni će te poslušati. Onda pođi sa starješinama Izraelaca k egipatskom kralju i reci mu: \'Objavio nam se Jahve, Bog Hebreja. Pusti nas da odemo tri dana hoda u pustinju, da ondje prinesemo žrtvu Jahvi, Bogu svojemu.\'');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 3, 19, 'Znam ja da vas egipatski kralj neće pustiti ako ne bude natjeran teškom šakom.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 3, 20, 'Zato ću ja pružiti svoju šaku i pritisnuti Egipat svakovrsnim čudesima što ću ih u njemu izvesti. Poslije će vas pustiti.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 3, 21, 'Dobro ću raspoložiti Egipćane prema ovome narodu, pa kad pođete, nećete poći praznih ruku.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 3, 22, 'Svaka će žena zatražiti od svoje susjede i stanarke u svojoj kući nakita srebrnog i zlatnog i odjeće. To stavite na svoje sinove i kćeri. Tako ćete oplijeniti Egipćane.\"');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 4, 1, 'Mojsije uzvrati: \"Ali ako mi ne povjeruju i ne poslušaju me, nego mi reknu: \'Jahve ti se nije objavio?\'\"');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 4, 2, '\"Što ti je to u ruci?\" - zapita ga Jahve. \"Štap\", odgovori.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 4, 3, '\"Baci ga na zemlju!\" - naredi mu Jahve. On ga baci na zemlju, a štap se pretvori u zmiju. Mojsije pred njom uzmače.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 4, 4, 'Onda Jahve reče Mojsiju: \"Pruži ruku i uhvati je za rep.\" I on seže rukom i uhvati je za rep, a ona opet postade štap u njegovoj ruci.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 4, 5, '\"Tako moraju vjerovati da se Jahve, Bog njihovih otaca, Bog Abrahamov, Bog Izakov i Bog Jakovljev, tebi objavio.\"');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 4, 6, 'Još mu Jahve rekne: \"Uvuci ruku u njedra.\" On uvuče ruku u njedra. Kad ju je izvukao, gle - ruka mu gubava, bijela kao snijeg.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 4, 7, '\"Stavi opet ruku u njedra!\" - naredi mu Jahve. On opet ruku u njedra. Kad ju je iz njedara izvukao, gle - opet je bila kao i ostali dio tijela.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 4, 8, '\"Ako ti ne povjeruju i ne prihvate poruku prvoga znamenja, povjerovat će poruci drugoga znamenja.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 4, 9, 'A ako ih oba ova znamenja ne uvjere pa ti ne povjeruju, zahvati vode iz Rijeke i prolij je po suhu. Voda što je budeš iz Rijeke uzeo na suhu će se u krv pretvoriti.\"');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 4, 10, '\"Oprosti, Gospodine!\" - nastavi Mojsije Jahvi. \"Ja nikad nisam bio čovjek rječit; ni prije ni sada kad govoriš svome sluzi. Ja sam u govoru spor, a na jeziku težak.\"');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 4, 11, '\"Tko je dao čovjeku usta?\" - reče mu Jahve. \"Tko ga čini nijemim i gluhim; tko li mu vid daje ili ga osljepljuje? Zar to nisam ja, Jahve!');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 4, 12, 'Idi, dakle! Ja ću biti s tobom kad budeš govorio i kazivat ću ti što ćeš govoriti.\"');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 4, 13, '\"Oprosti, Gospodine\", opet će Mojsije, \"ne bi li poslao koga drugoga!\"');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 4, 14, 'Razljuti se Jahve na Mojsija i reče: \"Zar Aron, Levijevac, nije tvoj brat? Znam da je on vrlo rječit. Evo, baš ti izlazi u susret. Kad te vidi, obradovat će se u srcu.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 4, 15, 'Ti govori njemu i u njegova usta stavljaj riječi. Ja ću biti i s tobom i s njime dok budete govorili; kazivat ću obojici što ćete raditi.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 4, 16, 'Neka on mjesto tebe govori narodu. Tako, on će tebi biti mjesto usta, a ti ćeš njemu biti mjesto Boga.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 4, 17, 'Uzmi ovaj štap u ruku. Njim izvodi znamenja.\"');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 4, 18, 'Zatim se Mojsije vrati svome tastu Jitru te mu reče: \"Pusti me da se vratim braći u Egipat da vidim jesu li još na životu.\" \"Pođi u miru!\" - reče Jitro Mojsiju.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 4, 19, 'I Jahve reče Mojsiju u Midjanu: \"Vrati se u Egipat, jer su pomrli svi ljudi koji su tražili tvoj život.\"');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 4, 20, 'Tako Mojsije posadi na magarca svoju ženu i sinove i ode u zemlju egipatsku. A u ruku Mojsije uze Božji štap.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 4, 21, 'Jahve opet reče Mojsiju: \"Kad se vratiš u Egipat, pobrini se da pred faraonom izvedeš sva čudesa za koja sam ti dao moć, premda ću ja tvrdim učiniti njegovo srce, tako te neće pustiti narod da ode.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 4, 22, 'Tada reci faraonu: \'Ovako kaže Jahve: Izrael je moj prvorođenac.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 4, 23, 'Tražim od tebe da mi pustiš sina da mi iskaže štovanje. Ako odbiješ da ga pustiš, ja ću ubiti tvoga prvorođenca.\'\"');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 4, 24, 'Kad se na putu Mojsije zaustavi da prenoći, navali na nj Jahve da ga ubije.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 4, 25, 'Ali Sipora pograbi oštar kremen, obreza svoga sina i kožicom se dotakne Mojsijevih nogu: \"Zaista si mi ti krvav muž\", reče.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 4, 26, 'I Jahve ga pusti. Ona je to zbog obrezanja rekla \"krvav muž\".');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 4, 27, 'Onda rekne Jahve Aronu: \"Zaputi se prema pustinji, u susret Mojsiju!\" On ode i s njim se sastane na Božjem brdu. Poljubi ga.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 4, 28, 'Mojsije pripovjedi Aronu sve što mu je Jahve povjerio i sva znamenja koja mu je naredio da ih učini.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 4, 29, 'Sad odu Mojsije i Aron i skupe sve starješine Izraelaca.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 4, 30, 'Aron izloži sve što je Jahve govorio Mojsiju, a Mojsije izvede znamenja naočigled naroda.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 4, 31, 'Narod je bio uvjeren, i pošto čuše da je Jahve pohodio Izraelce i pogledao na njihove jade, popadaše ničice i pokloniše se.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 5, 1, 'Poslije toga odu Mojsije i Aron pa reknu faraonu: \"Ovako veli Jahve, Bog Izraelov: \'Pusti narod moj da ode i u moju čast slavi svetkovinu.\'\"');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 5, 2, '\"Tko je taj Jahve da ga ja poslušam\", odvrati faraon, \"i pustim Izraelce? Ja toga Jahvu ne znam niti ću pustiti Izraelce.\"');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 5, 3, '\"Bog Hebreja objavio nam se\", rekoše. \"Zato nas pusti da odemo tri dana hoda u pustinju i prinesemo žrtvu Jahvi, Bogu svome, da se na nas ne obori pomorom ili mačem.\"');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 5, 4, 'Nato im odvrati egipatski kralj: \"Mojsije i Arone, zašto odvraćate svijet od njegovih dužnosti? Idite na svoj posao.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 5, 5, 'Sad kad se svjetina tako umnožila\", nastavi faraon, \"vi biste ih od posla odvratili?\"');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 5, 6, 'Istoga dana izda faraon naredbu nadglednicima i bilježnicima:');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 5, 7, '\"Ne pribavljajte više ovome narodu slame kao do sada. Neka idu sami i sebi je skupljaju.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 5, 8, 'A zahtijevajte od njih istu količinu opeke koju su pravili i dosad. Ne smanjujte je! Lijenčine su. Zato viču: \'Hajdemo prinijeti žrtvu Bogu svome!\'');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 5, 9, 'Navalite poslove na taj svijet: neka rade, da ne obraćaju pažnje klevetama!\"');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 5, 10, 'Sad dođu nadglednici naroda i njegovi bilježnici te svijetu objave: \"Ovako poručuje faraon: \'Neću vam više nabavljati slame.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 5, 11, 'Vi sami morate ići i tražiti je gdje god je možete naći. Ali zato neću smanjiti vaš posao.\'\"');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 5, 12, 'Stoga se narod raziđe po svoj zemlji egipatskoj da skuplja strnjiku namjesto slame.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 5, 13, 'A nadglednici ih gonili: \"Morate svakoga dana svršiti jednako posla kao i onda dok ste slamu dobivali.\"');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 5, 14, 'A bilježnike koje faraonovi nadglednici bijahu postavili nad Izraelcima tukli su i korili: \"Zašto niste ni jučer ni danas napravili opeke koliko i prije?\"');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 5, 15, 'Onda bilježnici Izraelaca odu i potuže se faraonu: \"Zašto ovako postupaš sa svojim slugama?');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 5, 16, 'Tvoje sluge više ne dobivaju slame, a ipak se od nas traži: napravite opeku? Čak i tuku tvoje sluge, a kriv je tvoj narod!\"');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 5, 17, '\"Lijenčine ste vi! Lijenčine!\" - odgovori faraon. \"Stoga i kažete: \'Hajdemo da prinesemo žrtvu Jahvi!\'');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 5, 18, 'Nosite se na posao! Slama vam se neće davati, ali morate praviti određene količine opeke.\"');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 5, 19, 'Bilježnici Izraelaca nađu se na muci zbog naredbe: \"Svakodnevnu količinu opeke ne smijete smanjiti!\"');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 5, 20, 'Otišavši od faraona, naiđu na Mojsija i Arona, koji su ih čekali.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 5, 21, '\"Neka vas Jahve ima na oku i sudi vam!\" - dobace im. \"Omrazili ste nas kod faraona i njegovih dvorana; dali ste im mač u ruke da nas pobiju.\"');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 5, 22, 'Mojsije se vrati Jahvi i reče: \"Zašto, Gospodine, nanosiš štetu svome puku? Zašto si me poslao?');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 5, 23, 'Otkad sam ja stupio pred faraona i progovorio mu u tvoje ime, on još gore postupa s ovim narodom. A ti ništa ne poduzimaš da izbaviš svoj narod.\"');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 6, 1, 'Jahve reče Mojsiju: \"Naskoro ćeš vidjeti kako ću ja s faraonom! Pod jakom rukom pustit će ih da odu; pod jakom rukom sam će ih iz svoje zemlje istjerati.\"');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 6, 2, 'Još reče Bog Mojsiju: \"Ja sam Jahve.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 6, 3, 'Abrahamu, Izaku i Jakovu objavljivao sam se kao El Šadaj. Ali njima se nisam očitovao pod svojim imenom - Jahve.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 6, 4, 'I sklopio sam svoj Savez s njima da ću im dati kanaansku zemlju, zemlju gdje su živjeli kao pridošlice.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 6, 5, 'A sada, pošto sam čuo uzdisaje Izraelaca koje Egipćani drže u ropstvu, sjetih se svoga Saveza.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 6, 6, 'Kaži, dakle, Izraelcima da sam ja Jahve; da ću vas izbaviti od tereta što su vam ga Egipćani nametnuli. Oslobodit ću vas od ropstva u kojem vas drže; izbavit ću vas udarajući jako i kažnjavajući strogo.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 6, 7, 'Za svoj ću vas narod uzeti i bit ću vašim Bogom. Tada ćete znati da sam vas ja, Jahve, vaš Bog, izbavio od egipatske tlake.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 6, 8, 'Dovest ću vas u zemlju za koju sam se zakleo da ću je dati Abrahamu, Izaku i Jakovu i dat ću vam je u baštinu, ja, Jahve.\"');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 6, 9, 'Mojsije to kazivaše Izraelcima, ali ga ne htjedoše slušati: duhovi su im bili pomućeni od teškoga ropstva.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 6, 10, 'Onda Jahve reče Mojsiju:');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 6, 11, '\"Idi i reci faraonu, kralju egipatskome, da otpusti Izraelce iz svoje zemlje.\"');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 6, 12, 'Mojsije prozbori Jahvi: \"Kad me Izraelci nisu slušali, kako će me, spora u govoru, saslušati faraon!\"');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 6, 13, 'Ali je Jahve govorio Mojsiju i Aronu i slao ih sad k Izraelcima, a sad k faraonu, kralju egipatskome, da pusti Izraelce iz Egipta.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 6, 14, 'Ovo su glave njihovih domova. Sinovi Izraelova prvorođenca Rubena: Henok, Palu, Hesron i Karmi. To su obitelji potekle od Rubena.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 6, 15, 'A sinovi Šimunovi: Jemuel, Jamin, Ohad, Jakin, Sohar i Šaul, sin Kanaanke. To su obitelji potekle od Šimuna.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 6, 16, 'Ovo su imena Levijevih sinova s njihovim potomstvom: Geršon, Kehat i Merari. Levi je živio sto trideset i sedam godina.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 6, 17, 'Sinovi su Geršonovi: Libni i Šimi sa svojim obiteljima.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 6, 18, 'Sinovi su Kehatovi: Amram, Jishar, Hebron i Uziel. Kehat je živio sto trideset i tri godine.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 6, 19, 'Merarijevi su sinovi: Mahli i Muši. To su Levijeve obitelji s njihovim potomcima.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 6, 20, 'Amram se oženi svojom tetkom Jokebedom, koja mu rodi Arona i Mojsija. Amram je živio sto trideset i sedam godina.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 6, 21, 'Sinovi Jisharovi bijahu: Korah, Nefeg i Zikri.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 6, 22, 'A sinovi su Uzielovi: Mišael, Elsafan i Sitri.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 6, 23, 'Aron se oženi Elišebom, kćerkom Aminadabovom, a sestrom Nahšonovom, koja mu rodi: Nadaba, Abihua, Eleazara i Itamara.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 6, 24, 'Korahovi su sinovi: Asir, Elkana i Abiasaf. To su Korahovi potomci.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 6, 25, 'Aronov sin Eleazar oženi se jednom Putielovom kćeri, koja mu rodi Pinhasa. To su glave Levijevih domova prema njihovim koljenima.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 6, 26, 'To je onaj Aron i Mojsije kojima je Jahve zapovjedio da izvedu Izraelce iz Egipta po njihovim četama.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 6, 27, 'To su oni isti, Mojsije i Aron, koji su govorili faraonu, kralju egipatskome, da pusti Izraelce iz Egipta.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 6, 28, 'U dan kad je Jahve govorio s Mojsijem u egipatskoj zemlji,');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 6, 29, 'rekao mu je: \"Ja sam Jahve. Izvijesti faraona, egipatskoga kralja, o svemu što ti kažem.\"');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 6, 30, 'Mojsije se pred Jahvom ispričavao: \"Spor sam ja u govoru. Kako će me faraon poslušati?\"');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 7, 1, 'Mojsiju je Jahve odgovorio: \"Vidi! Faraonu ću te nametnuti kao božanstvo; tvoj brat Aron bit će tvoj prorok.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 7, 2, 'Ti kazuj sve što ti naređujem, a tvoj brat Aron neka faraonu ponovi da pusti Izraelce te odu iz njegove zemlje.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 7, 3, 'Ja ću učiniti da otvrdne srce faraonu i umnožit ću znakove i čudesa u zemlji egipatskoj.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 7, 4, 'Kako vas faraon neće poslušati, ja ću staviti svoju ruku na Egipat: strašno kažnjavajući, izbavit ću svoje čete, narod svoj, Izraelce, iz egipatske zemlje.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 7, 5, 'Kad pružim svoju ruku na Egipat i izvedem Izraelce iz njihove sredine, tada će Egipćani spoznati da sam ja Jahve.\"');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 7, 6, 'Mojsije i Aron poslušaše: kako im je Jahve naredio, upravo tako učiniše.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 7, 7, 'Mojsiju je bilo osamdeset, a Aronu osamdeset i tri godine kad su faraonu postavili svoje zahtjeve.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 7, 8, 'Još doda Jahve Mojsiju i Aronu:');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 7, 9, '\"Kad faraon zatraži od vas da izvedete kakvo znamenje, ti reci Aronu da uzme svoj štap i baci ga pred faraona, a štap će se pretvoriti u zmiju.\"');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 7, 10, 'Dođu Mojsije i Aron pred faraona i učine kako im je Jahve naredio. Aron baci pred faraona i njegove službenike svoj štap, koji se pretvori u zmiju.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 7, 11, 'Zovne faraon mudrace i vračare. I zaista, egipatski vračari svojim vračanjem učine isto:');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 7, 12, 'svaki baci svoj štap, koji se pretvori u zmiju. Ali Aronov štap proguta njihove štapove.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 7, 13, 'Faraon bijaše tvrdokorna srca: ne htjede poslušati Mojsija i Arona, kako je Jahve i kazao.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 7, 14, 'Tada Jahve reče Mojsiju: \"Faraonovo je srce okorjelo; odbija da pusti narod.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 7, 15, 'Ujutro pođi k faraonu. Kad izađe k vodi, stani preda nj na obali Rijeke. Uzmi u ruku štap što se bio u zmiju pretvorio.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 7, 16, 'Reci mu: \'Jahve, Bog Hebreja, poslao me k tebi s porukom da pustiš moj narod da mi iskaže štovanje u pustinji. Ali sve dosad ti nisi poslušao.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 7, 17, 'Ovako Jahve poručuje: Ovim ćeš spoznati da sam ja Jahve. Gledaj! Štapom koji imam u ruci mlatnut ću po vodi u Rijeci i pretvorit će se u krv.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 7, 18, 'Ribe će u Rijeci pocrkati; Rijeka će se usmrdjeti, i grstit će se Egipćanima piti vodu iz Rijeke.\'\"');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 7, 19, 'Još Jahve reče Mojsiju: \"Reci Aronu da uzme svoj štap i pruži svoju ruku povrh egipatskih voda: njihovih rijeka, njihovih prokopa, njihovih jezeraca, svih njihovih vodenih stjecišta, da se pretvore u krv; po svoj zemlji egipatskoj neka je krv, čak i u drvenim i kamenim posudama.\"');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 7, 20, 'Mojsije i Aron učiniše kako im je Jahve naredio. Podiže Aron svoj štap i naočigled faraona i njegovih službenika mlatnu po vodi u Rijeci. Sva se voda u Rijeci prometnu u krv.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 7, 21, 'Ribe u Rijeci pocrkaše; Rijeka se usmrdje, tako da Egipćani nisu mogli piti vodu iz Rijeke; krv bijaše po svoj zemlji egipatskoj.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 7, 22, 'Ali egipatski vračari svojim vračanjem učiniše isto. Tako faraon ostade tvrdokorna srca: nije htio poslušati Mojsija i Arona, kako je Jahve i kazao.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 7, 23, 'Faraon se okrenu i ode u svoj dvor, ne uzimajući ni to k srcu.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 7, 24, 'Svi su Egipćani počeli kopati oko Rijeke tražeći pitke vode jer nisu mogli piti vode iz Rijeke.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 7, 25, 'Kad je prošlo sedam dana kako je Jahve udario po Rijeci,');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 7, 26, 'opet Jahve reče Mojsiju: \"Pođi k faraonu i reci mu: \'Ovako govori Jahve: Pusti moj narod da ode i štovanje mi iskaže.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 7, 27, 'Ako odbiješ da ih pustiš, svu ću ti zemlju kazniti žabama.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 7, 28, 'Rijeka će vrvjeti žabama. One će izići i prodrijeti u tvoj dvor, u ložnicu, u tvoju postelju, u kuće tvojih službenika i tvoga naroda, pod sačeve i naćve tvoje.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 7, 29, 'Po tebi, po tvome narodu i svim tvojim službenicima skakat će žabe.\'\"');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 8, 1, 'Onda Jahve reče Mojsiju: \"Reci Aronu neka ispruži svoju ruku sa štapom povrh rijeka, prokopa i jezeraca i učini da žabe navale na egipatsku zemlju.\"');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 8, 2, 'Aron pruži svoju ruku povrh egipatskih voda, i žabe iziđoše i prekriše zemlju egipatsku.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 8, 3, 'Ali i vračari učiniše tako svojim vračanjem, te žabe navališe na egipatsku zemlju.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 8, 4, 'Zovne sad faraon Mojsija i Arona i rekne: \"Molite Jahvu da ukloni žabe od mene i moga puka, a ja ću pustiti narod da prinese žrtvu Jahvi.\"');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 8, 5, 'Mojsije uzvrati faraonu: \"Dostoj se odrediti mi kad hoćeš da molim za te, za tvoje službenike i za tvoj narod da se žabe odstrane od tebe i tvojih domova i ostanu samo u Rijeci.\"');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 8, 6, '\"Sutra\", reče. \"Neka bude kako kažeš\", odvrati Mojsije, \"da znaš kako nitko nije kao Jahve, Bog naš.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 8, 7, 'Žabe će otići od tebe, od tvojih službenika i tvoga naroda; ostat će samo u Rijeci.\"');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 8, 8, 'Mojsije i Aron odu od faraona, a onda Mojsije zazva Jahvu zbog žaba kojima je kaznio faraona.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 8, 9, 'I Jahve usliša Mojsija, te žabe pocrkaju po kućama, dvorištima i njivama.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 8, 10, 'Na hrpe su ih zgrtali, zemlja se njima usmrdjela.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 8, 11, 'Kad je faraon vidio da je nastupilo olakšanje, srce mu otvrdnu te ne posluša Mojsija i Arona, kako je Jahve i kazao.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 8, 12, 'Onda će opet Jahve Mojsiju: \"Reci Aronu neka zamahne svojim štapom i udari po prahu na tlu neka se pretvori u komarce po svoj zemlji egipatskoj.\"');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 8, 13, 'I učine tako: zamahne Aron rukom i štapom te udari po prahu na tlu. Komarci navale na ljude i životinje. Sav prah na tlu pretvori se u komarce po svoj zemlji egipatskoj.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 8, 14, 'Vračari pokušaše da svojim vračanjem stvore komarce, ali nisu mogli. Ljudi i životinje postanu plijenom komaraca.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 8, 15, 'Tada vračari reknu faraonu: \"To je prst Božji!\" Ali je faraonovo srce bilo okorjelo, pa nije poslušao Mojsija i Arona, kako je Jahve i kazao.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 8, 16, 'Onda Jahve reče Mojsiju: \"Podrani ujutro, iziđi pred faraona kad krene k vodi, i reci mu: \'Ovako poručuje Jahve: Pusti moj narod da ode i da mi štovanje iskaže.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 8, 17, 'Ako ne pustiš moga naroda, pripustit ću obade na te, na tvoje službenike, na tvoj puk i tvoje domove. Egipatski domovi i samo tlo na kojem stoje vrvjet će od obada.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 8, 18, 'Ali ću toga dana izuzeti gošenski kraj, u kojem živi moj narod, te se ondje obadi neće pojaviti, tako da znaš da sam ja Jahve u središtu zemlje.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 8, 19, 'Tu ću razliku napraviti između svoga i tvoga naroda. To će znamenje biti sutra.\'\"');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 8, 20, 'I učini Jahve tako. Rojevi obada nalete u faraonov dvor, na domove njegovih službenika i po svoj zemlji egipatskoj. Zemlja nastrada od obada.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 8, 21, 'Sad faraon pozove Mojsija i Arona pa im rekne: \"Idite, prinesite žrtvu svome Bogu, ali u ovoj zemlji.\"');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 8, 22, '\"Ne dolikuje da tako učinimo\", odgovori Mojsije. \"Žrtve koje mi prinosimo Jahvi, Bogu svome, za Egipćane su svetogrđe. Kad bismo, dakle, na njihove oči prinosili žrtve koje su Egipćanima svetogrdne, zar nas ne bi kamenovali?');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 8, 23, 'Zato moramo u pustinju tri dana hoda te prinijeti žrtvu Jahvi, Bogu svome, kako nam je zapovjedio.\"');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 8, 24, '\"Pustit ću vas da odete u pustinju\", odgovori faraon, \"i prinesete žrtvu Jahvi, svome Bogu, ali ne odlazite predaleko. Molite za me!\"');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 8, 25, 'Nato odvrati Mojsije: \"Čim odem od tebe, zazvat ću Jahvu da sutra nestane obada s faraona, njegovih službenika i njegova puka. Ali neka faraon više ne vara! Neka pusti narod da ide i prinese žrtvu Jahvi.\"');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 8, 26, 'Tako Mojsije ode od faraona i pomoli se Jahvi.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 8, 27, 'I Jahve učini kako je Mojsije tražio: s faraona, s njegovih službenika i s njegova puka nestane obada - ni jedan jedini nije ostao.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 8, 28, 'Ali opet ukruti faraon srce svoje i ne dopusti narodu da ode.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 9, 1, 'Tada Jahve reče Mojsiju: \"Idi k faraonu i reci mu: \'Ovako poručuje Jahve, Bog Hebreja: Pusti moj narod da ode i da mi štovanje iskaže.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 9, 2, 'Ako ga ne pustiš, nego ga i dalje budeš zadržavao,');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 9, 3, 'ruka Jahvina udarit će strašnim pomorom po tvome blagu što je u polju: po konjima, magaradi, devama, krupnoj i sitnoj stoci.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 9, 4, 'Razlikovat će Jahve stoku Izraelaca od stoke Egipćana, tako da ništa što pripada Izraelcima neće stradati.\'\"');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 9, 5, 'Jahve je odredio i vrijeme, rekavši: \"Sutra će Jahve izvesti ovo u zemlji.\"');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 9, 6, 'Sutradan Jahve tako i učini. Sva stoka Egipćana ugine, a od stoke Izraelaca nije uginulo ni jedno grlo.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 9, 7, 'Faraon je istraživao i uvjerio se da od izraelske stoke nije uginulo ni jedno grlo. Ali je srce faraonovo ipak otvrdlo i nije pustio naroda.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 9, 8, 'Reče Jahve Mojsiju i Aronu: \"Zagrabite pune pregršti pepela iz peći, pa neka ga Mojsije pred faraonovim očima baci prema nebu.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 9, 9, 'Od toga će nastati sitna prašina po svoj zemlji egipatskoj, i na ljudima će i na životinjama izazivati otekline i stvarati čireve s kraja na kraj Egipta.\"');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 9, 10, 'Tako oni uzeše pepela iz peći i dođoše pred faraona. Onda Mojsije rasu pepeo prema nebu, a otekline s čirevima prekriše ljude i životinje.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 9, 11, 'Ni čarobnjaci se nisu mogli pojaviti pred Mojsijem, jer su i čarobnjaci, kao i ostali Egipćani, bili prekriveni čirevima.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 9, 12, 'Ali je Jahve otvrdnuo srce faraonu, pa on ne posluša Mojsija i Arona, kako je Jahve Mojsiju i rekao.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 9, 13, 'Tada Jahve reče Mojsiju: \"Podrani ujutro, iziđi pred faraona i reci mu: \'Ovako poručuje Jahve, Bog Hebreja: Pusti narod da ode i da mi štovanje iskaže.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 9, 14, 'Ako ih ne pustiš, sva zla svoja navalit ću ovaj put na te, na tvoje službenike i tvoj puk, tako da spoznaš da nema nikoga na svoj zemlji kao što sam ja.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 9, 15, 'Da sam ruku svoju spustio i udario tebe i tvoj puk pomorom, nestalo bi te sa zemlje.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 9, 16, 'Poštedio sam te da ti pokažem svoju moć i da se hvali moje ime po svoj zemlji.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 9, 17, 'Ali se ti previše uzdižeš nad mojim narodom i priječiš mu da ode.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 9, 18, 'Sutra u ovo doba pustit ću tuču tako strašnu kakve u Egiptu još nije bilo otkad je postao do sada.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 9, 19, 'Zato naredi da pod krov utjeraju tvoje blago i sve što je vani, na otvorenu. Sve što se nađe u polju, bilo čovjek bilo živinče, ne bude li uvedeno unutra, poginut će kad tuča zaspe po njima.\'\"');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 9, 20, 'Faraonovi službenici, koji su se pobojali Jahvina govora, utjeraju svoje sluge i svoje blago unutra.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 9, 21, 'Oni koji nisu marili za Jahvinu prijetnju ostave vani i svoje sluge i stoku.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 9, 22, 'Onda rekne Jahve Mojsiju: \"Pruži ruku prema nebu da udari tuča po svoj zemlji egipatskoj: po ljudima, životinjama i svemu bilju u zemlji egipatskoj.\"');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 9, 23, 'Mojsije diže svoj štap prema nebu. Jahve zagrmje i pusti tuču i munje sastavi sa zemljom. Sipao je Jahve tuču po zemlji Egipćana.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 9, 24, 'Tuča je mlatila, kroz nju munje parale. Strahota se takva nije oborila na zemlju egipatsku otkako su ljudi u njoj.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 9, 25, 'Tuča pobi po svem Egiptu sve što je ostalo vani, ljude i životinje; uništi sve bilje po poljima i sva stabla poljska polomi.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 9, 26, 'Samo u gošenskom kraju, gdje su živjeli Izraelci, nije bilo tuče.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 9, 27, 'Faraon posla po Mojsija i Arona pa im reče: \"Ovaj put priznajem da sam kriv. Jahve ima pravo, a ja i moj narod krivo.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 9, 28, 'Molite Jahvu da ustavi gromove i tuču, a ja ću vas pustiti da idete. Nećete više dugo ostati.\"');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 9, 29, '\"Kad iziđem iz grada\", reče mu Mojsije, \"dići ću ruke prema Jahvi, pa će gromovi prestati, a ni tuče više neće biti, tako da znaš da zemlja pripada Jahvi.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 9, 30, 'Ali ni ti ni tvoji dvorani, znam ja, još se ne bojite Boga Jahve.\"');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 9, 31, 'I tako propade lan i ječam: jer ječam bijaše u klasu, a lan u cvatu.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 9, 32, 'Pšenica i raž nisu nastradali jer su ozima žita.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 9, 33, 'Otišavši od faraona, Mojsije iziđe iz grada i podigne ruke prema Jahvi. Prestane grmljavina i tuča, a ni kiša više nije padala na zemlju.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 9, 34, 'Kad je faraon vidio da je prestala grmljavina, tuča i kiša, opet padne u grijeh: i on i njegovi službenici opet otvrdnu srcem.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 9, 35, 'Otvrdnu srce faraonu i ne pusti on Izraelce, kako je Jahve i prorekao preko Mojsija.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 10, 1, 'Reče Jahve Mojsiju: \"Idi k faraonu. Učinio sam da njemu i njegovim službenicima otvrdne srce da izvedem svoja znamenja među njima;');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 10, 2, 'da možeš pripovjedati svome sinu i svome unuku što sam učinio Egipćanima i kakva sam znamenja izvodio među njima, kako biste znali da sam ja Jahve.\"');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 10, 3, 'Tako Mojsije i Aron odu k faraonu i kažu mu: \"Ovako poručuje Jahve, Bog Hebreja: \'Dokle ćeš odbijati da se preda mnom poniziš? Pusti moj narod da mi iskaže štovanje.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 10, 4, 'Jer ako ne pustiš moga naroda, sutra ću navesti skakavce na tvoju zemlju.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 10, 5, 'Tako će prekriti površinu da se zemlja od njih neće vidjeti. Pojest će ono što vam je iza tuče ostalo; i ogolit će vam sva stabla što po polju rastu.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 10, 6, 'Ispunit će ti sav dvor, kuće tvojih službenika i domove svih ostalih Egipćana - takvo što ne vidješe ni tvoji očevi ni očevi tvojih očeva u ovoj zemlji od svojih vremena do danas.\'\" Okrene se i ode od faraona.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 10, 7, '\"Dokle će nam ovaj čovjek biti stupica?\" - rekoše faraonu njegovi službenici. - \"Pusti te ljude neka idu i iskažu štovanje Jahvi, svome Bogu! Zar ne vidiš kako Egipat srlja u propast?\"');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 10, 8, 'Dovedu Mojsija i Arona natrag k faraonu, a on im reče: \"Idite! Iskažite štovanje Jahvi, svome Bogu! A tko će sve ići?\"');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 10, 9, '\"Svi idemo\", odgovori Mojsije, \"i mlado i staro. Odlazimo sa svojim sinovima i svojim kćerima; sa svojom krupnom i sitnom stokom, jer moramo održati svečanost Jahvi.\"');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 10, 10, '\"Jahve bio s vama isto kao što i ja pustio da s vama pođu i djeca!\" - odgovori im. \"Očito se vidi da vam nakana nije čista.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 10, 11, 'Nećemo tako! Nego muškarci neka odu i štovanje iskažu Jahvi. To ste i tražili.\" I otjeraju ih od faraona.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 10, 12, 'Tada reče Jahve Mojsiju: \"Pruži ruku povrh zemlje egipatske da navale skakavci na egipatsku zemlju i pojedu sve bilje što još ostade nakon tuče!\"');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 10, 13, 'Tako Mojsije podigne svoj štap povrh egipatske zemlje, a Jahve navrati istočni vjetar po zemlji; puhao je toga cijelog dana i cijele noći. A kad je jutro svanulo, vjetar nanio skakavce.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 10, 14, 'Oni se razlete po svoj egipatskoj zemlji i padnu po svim krajevima Egipta u silnoj gustoći: toliko ih mnoštvo nikad prije nije bilo niti će kada biti.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 10, 15, 'Pokriju sve tlo, tako da se od njih zacrnjelo. Pojedu sve bilje u polju i sve plodove sa stabala što su bili ostali iza tuče. Ništa se više nije zelenjelo: ni stabla ni poljska trava u svem Egiptu.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 10, 16, 'Brže-bolje dozva faraon Mojsija i Arona pa im reče: \"Sagriješio sam protiv Jahve, vašega Boga, i vas!');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 10, 17, 'Oprostite mi uvredu još samo ovaj put i molite Jahvu, Boga svoga, da samo otkloni od mene ovaj smrtonosni bič!\"');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 10, 18, 'Kad je Mojsije otišao od faraona, zazva Jahvu');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 10, 19, 'i Jahve promijeni vjetar u veoma jak zapadnjak, koji pothvati skakavce i odnese prema Crvenome moru. Ni jedan jedini skakavac nije ostao ni u kojem kraju Egipta.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 10, 20, 'Ali je Jahve otvrdnuo srce faraonu i ne pusti on Izraelaca.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 10, 21, '\"Pruži ruku prema nebu\", rekne Jahve Mojsiju, \"pa neka se tmina spusti na egipatsku zemlju, tmina koja će se moći opipati.\"');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 10, 22, 'Mojsije pruži ruku prema nebu i spusti se gusta tmina na svu zemlju egipatsku: tri je dana trajala.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 10, 23, 'Tri dana nisu ljudi jedan drugoga mogli vidjeti i nitko se sa svoga mjesta nije micao. A u mjestima gdje su Izraelci živjeli sjala svjetlost.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 10, 24, 'Pozva onda faraon Mojsija i reče: \"Idi i štovanje iskaži Jahvi! Ali vaša stoka, krupna i sitna, neka ostane ovdje. Vaša djeca neka idu s vama!\"');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 10, 25, '\"Ti nas sam moraš opskrbiti prinosima i žrtvama paljenicama koje ćemo prinijeti Jahvi, Bogu svojemu\", odgovori Mojsije.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 10, 26, '\"Zato ćemo sa sobom potjerati i svoja stada. Ni papak neće ostati ovdje. Od njih nam valja izabrati za žrtvovanje Jahvi, Bogu našemu, a ne znamo, dok onamo ne stignemo, što moramo Jahvi prinijeti.\"');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 10, 27, 'Jahve otvrdne faraonu srce i on ne pristane da odu.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 10, 28, '\"Odlazi!\" - vikne faraon na Mojsija. \"I da mi više na oči ne dolaziš! Onoga dana kad mi se opet pojaviš na oči, zaglavit ćeš!\"');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 10, 29, '\"Dobro si kazao!\" - uzvrati Mojsije. \"Lica tvoga više neću vidjeti!\"');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 11, 1, '\"Još ću samo jednom nedaćom udariti faraona i Egipat\", reče Jahve Mojsiju. \"Poslije toga pustit će vas odavde. I više: sam će vas odavde potjerati.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 11, 2, 'Kaži svijetu neka svaki čovjek ište od svoga susjeda i svaka žena od svoje susjede srebrnih i zlatnih dragocjenosti.\"');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 11, 3, 'Jahve učini te Egipćani bijahu naklonjeni narodu. Sam Mojsije postane vrlo uvažen u egipatskoj zemlji, u očima faraonovih službenika i u očima naroda.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 11, 4, 'A onda Mojsije navijesti: \"Ovako poručuje Jahve: \'O ponoći proći ću Egiptom.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 11, 5, 'Svaki će prvorođenac u egipatskoj zemlji umrijeti, od prvorođenca faraonova, koji bi imao sjediti na njegovu prijestolju, do prvorođenca ropkinje koja se nalazi uz mlinski kamen; a uginut će i sve prvine od stoke.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 11, 6, 'U svoj će zemlji egipatskoj nastati veliki jauk, kakva nije bilo niti će kad poslije biti.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 11, 7, 'Među Izraelcima ni pas neće zalajati na živo stvorenje: ni na čovjeka ni na životinju.\' Po tome ćete znati da Jahve luči Izraelca od Egipćanina.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 11, 8, 'Onda će svi ovi tvoji dvorani k meni doći, preda me se baciti i vikati: Nosi se i ti i sav puk koji za tobom ide! Poslije toga ću otići.\" I gnjevan ode od faraona.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 11, 9, '\"Neće vas faraon poslušati\", reče Jahve Mojsiju, \"a to da bi se umnožila moja znamenja u zemlji egipatskoj.\"');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 11, 10, 'Mojsije i Aron izveli su sva ta znamenja pred faraonom, ali je Jahve okorio srce faraonu, tako te on nije puštao Izraelaca da odu iz njegove zemlje.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 12, 1, 'Jahve reče Mojsiju i Aronu u zemlji egipatskoj:');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 12, 2, '\"Ovaj mjesec neka vam bude početak mjesecima; neka vam bude prvi mjesec u godini.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 12, 3, 'Ovo objavite svoj zajednici izraelskoj: Desetog dana ovoga mjeseca neka svatko za obitelj pribavi jedno živinče. Tako, jedno na obitelj.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 12, 4, 'Ako je obitelj premalena da ga potroši, neka se ona priključi svome susjedu, najbližoj kući, prema broju osoba. Podijelite živinče prema tome koliko koja osoba može pojesti.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 12, 5, 'Živinče neka bude bez mane, od jedne godine i muško. Možete izabrati bilo janje bilo kozle.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 12, 6, 'Čuvajte ga do četrnaestoga dana ovoga mjeseca. A onda neka ga sva izraelska zajednica zakolje kad se spusti suton.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 12, 7, 'Neka uzmu krvi i poškrope oba dovratnika i nadvratnik kuće u kojoj se bude blagovalo.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 12, 8, 'Meso, pečeno na vatri, neka se pojede te iste noći sa beskvasnim kruhom i gorkim zeljem.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 12, 9, 'Da ništa sirovo ili na vodi skuhano od njega niste jeli, nego na vatri pečeno: s glavom, nogama i ponutricom.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 12, 10, 'Ništa od njega ne smijete ostaviti za sutradan: što bi god do jutra ostalo, morate na vatri spaliti.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 12, 11, 'A ovako ga blagujte: opasanih bokova, s obućom na nogama i sa štapom u ruci. Jedite ga žurno: to je Jahvina pasha.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 12, 12, 'Te ću, naime, noći ja proći egipatskom zemljom i pobiti sve prvorođence u zemlji egipatskoj - i čovjeka i životinju. Ja, Jahve, kaznit ću i sva egipatska božanstva.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 12, 13, 'Krv neka označuje kuće u kojima vi budete. Gdje god spazim krv, proći ću vas; tako ćete vi izbjeći biču zatornomu kad se oborim na zemlju egipatsku.\"');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 12, 14, '\"Taj dan neka vam bude spomen-dan. Slavite ga kao blagdan u čast Jahvi. Svetkujte ga po trajnoj uredbi od koljena do koljena.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 12, 15, 'Sedam dana jedite beskvasan kruh. Prvoga već dana uklonite kvasac iz svojih kuća. Jer, tko bi god od prvoga do sedmoga dana jeo ukvasan kruh, taj se ima iskorijeniti između Izraelaca.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 12, 16, 'Prvoga dana držite sveto zborovanje, a tako i sedmoga dana. Nikakva posla tih dana nemojte raditi. Jedino jelo, što kome treba, možete pripraviti.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 12, 17, 'Držite blagdan beskvasnog kruha! Toga sam, naime, dana izveo vaše čete iz zemlje egipatske. Držite zato taj dan kao blagdan od koljena do koljena: to je vječna naredba.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 12, 18, 'Od večeri četrnaestoga dana prvoga mjeseca pa do večeri dvadeset prvoga dana toga mjeseca jedite beskvasan kruh.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 12, 19, 'Sedam dana ne smije biti kvasca u vašim domovima. Tko bi god jeo bilo što ukvasano, taj neka se ukloni iz izraelske zajednice, bio stranac ili domorodac.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 12, 20, 'Ništa ukvasano ne smijete jesti: u svim svojim prebivalištima jedite nekvasan kruh.\"');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 12, 21, 'Zatim sazva Mojsije sve starješine Izraelaca te im reče: \"Idite i pribavite janje za svoje obitelji i žrtvujte Pashu.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 12, 22, 'Onda uzmite kitu izopa, zamočite je u krv što je u zdjeli i poškropite krvlju iz zdjele nadvratnik i oba dovratnika. Neka nitko ne izlazi preko kućnih vrata do jutra.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 12, 23, 'Kad Jahve bude prolazio da pobije Egipćane, zapazit će krv na nadvratniku i na oba dovratnika, pa će mimoići ta vrata i neće dopustiti da Zatornik uđe u vaše kuće da hara.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 12, 24, 'Ovu uredbu držite u svim vremenima kao zakon za se i djecu svoju.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 12, 25, 'I kad dođete u zemlju koju će vam Jahve dati kako je obećao, vršite ovaj obred.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 12, 26, 'Kad vas vaša djeca zapitaju: Što vam taj obred označuje?');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 12, 27, 'odgovorite im: Ovo je pashalna žrtva u čast Jahvi koji je prolazio mimo kuće Izraelaca kad je usmrćivao Egipćane, a naše kuće pošteđivao.\" Tada narod popada ničice i pokloni se.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 12, 28, 'Potom Izraelci odu i poslušaju: kako je Jahve Mojsiju i Aronu naredio, tako i učine.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 12, 29, 'U ponoći Jahve pobije sve prvorođence po zemlji egipatskoj: od prvorođenca faraonova, koji je imao sjediti na prijestolju, do prvorođenca sužnja u tamnici, a tako i sve prvine od stoke.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 12, 30, 'Noću ustane faraon, on pa svi njegovi dvorani i svi Egipćani, jer se strašan jauk razlijegao Egiptom: ne bijaše kuće u kojoj nije ležao mrtvac.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 12, 31, 'Faraon pozva u noći Mojsija i Arona te im reče: \"Ustajte i odlazite od moga naroda i vi i vaši Izraelci! Idite! Odajte štovanje Jahvi, kako ste tražili.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 12, 32, 'Pokupite svoju i sitnu i krupnu stoku, kako ste zahtijevali: idite pa i mene blagoslovite!\"');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 12, 33, 'Egipćani nagonili narod da brže ide iz zemlje, \"jer izgibosmo svi\", govorahu oni.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 12, 34, 'Tako narod ponese svoje još neukislo tijesto; naćve, uvijene u ogrtače, ponesoše na ramenima.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 12, 35, 'I učiniše Izraelci kako im je Mojsije bio rekao: zatražiše od Egipćana srebrnine, i zlatnine, i odjeće.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 12, 36, 'Jahve je učinio te Egipćani bijahu naklonjeni narodu pa davahu. Tako su Egipćane oplijenili.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 12, 37, 'Pođu tako Izraelci iz Ramsesa prema Sukotu. Bilo je oko šest stotina tisuća pješaka, osim žena i djece.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 12, 38, 'A mnogo i drugoga svijeta pođe s njima, i mnoga stoka, krupna i sitna.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 12, 39, 'Ispeku beskvasne prevrte od tijesta što su ga iz Egipta ponijeli: nije se bilo ukvasalo. A kako su bili tjerani iz Egipta, nisu mogli odgađati, i tako nisu sebi spremili poputninu.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 12, 40, 'Vrijeme što su ga Izraelci proveli u Egiptu iznosilo je četiri stotine i trideset godina.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 12, 41, 'I kad se navrši četiri stotine i trideset godina - točno onoga dana - sve čete Jahvine iziđoše iz zemlje egipatske.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 12, 42, 'Ona noć koju je Jahve probdio da njih izbavi iz Egipta, odonda je svima Izraelcima, u sve naraštaje njihove, noć bdjenja u čast Jahvi.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 12, 43, 'Reče Jahve Mojsiju i Aronu: \"Neka je ovo pravilo za pashalnu žrtvu: ni jedan stranac ne smije od nje jesti!');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 12, 44, 'Svaki rob, kupljen novcem i obrezan, može je jesti.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 12, 45, 'Ni gost ni najamnik ne smiju je jesti!');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 12, 46, 'Blagujte je u jednoj te istoj kući; iz kuće ne smijete iznositi mesa niti na žrtvi smijete koju kost slomiti.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 12, 47, 'Sva zajednica Izraelaca neka je prikazuje!');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 12, 48, 'Ako bi stranac koji među vama boravi htio svetkovati Pashu u čast Jahvi, svi se njegovi muški moraju obrezati. Tek tada neka pristupi i slavi je, jer je tada kao i domorodac zemlje. Ali neobrezani ne smije od nje jesti.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 12, 49, 'Neka vrijedi isto pravilo za domoroca i pridošlicu koji među vama boravi.\"');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 12, 50, 'Svi Izraelci poslušaju: kako je Jahve naredio Mojsiju i Aronu, tako su i učinili.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 12, 51, 'Toga istog dana izbavio je Jahve Izraelce u njihovim četama iz zemlje egipatske.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 13, 1, 'Jahve reče Mojsiju:');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 13, 2, '\"Meni posvetite svakoga prvorođenca! Prvenci materina krila kod Izraelaca, i od ljudi i od životinja, meni pripadaju!\"');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 13, 3, 'A onda Mojsije reče narodu: \"Sjećajte se ovoga dana u koji ste izbavljeni iz Egipta, iz kuće ropstva, jer vas Jahve izbavi odande svojom jakom mišicom. Ukvasani kruh neka se ne jede!');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 13, 4, 'Ovoga dana mjeseca Abiba vaše je izbavljenje.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 13, 5, 'Stoga: kad te Jahve uvede u zemlju Kanaanaca, Hetita, Amorejaca, Hivijaca i Jebusejaca, za koju se zakleo tvojim precima da će ti je dati - zemlju kojom teče med i mlijeko - ovoga mjeseca obavi ovakav obred:');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 13, 6, 'sedam dana jedi nekvasan kruh, a sedmoga dana neka se slavi svetkovina u čast Jahvi.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 13, 7, 'Sedam dana neka se jede nekvasan kruh; ukvasanog kruha neka ne bude kod tebe; i neka se nigdje ne vidi kvasac na tvome području.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 13, 8, 'Svome sinu toga dana objasni: to je za ono što mi je Jahve učinio kad sam se iz Egipta izbavio.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 13, 9, 'Neka ti bude kao znak na tvojoj ruci i kao opomena na tvome čelu: da Jahvin zakon bude uvijek na tvojim ustima. Jer te rukom jakom Jahve izbavio iz Egipta.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 13, 10, 'Ovaj propis vršite svake godine u određeno vrijeme.\"');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 13, 11, '\"A kada te Jahve dovede u zemlju Kanaanaca - kako vam se zakle, tebi i tvojim ocima - i kada ti je preda,');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 13, 12, 'ustupajte Jahvi prvorođence materinjega krila, a tako i sve prvine što ih tvoja stoka dade - svako muško pripada Jahvi!');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 13, 13, 'Svaku prvinu magaradi otkupi janjetom ili jaretom. Ako je ne otkupiš, slomi joj vrat. A svakoga prvorođenca između svoje djece otkupi.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 13, 14, 'Kad te sin tvoj sutra zapita: Što znači to? - odgovori mu: Rukom jakom izvede nas Jahve iz Egipta, iz kuće ropstva.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 13, 15, 'Kako je faraon postao tvrdokoran pa nas nije htio pustiti, Jahve je poubijao sve prvorođence u zemlji egipatskoj: prvorođence ljudi i prvine stoke. Eto zato Jahvi žrtvujem svaku mušku prvinu materinjega krila, a svakoga prvorođenca od svojih sinova otkupljujem.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 13, 16, 'Neka ti to bude kao znak na tvojoj ruci i kao znamenje posred čela da nas je rukom jakom Jahve izbavio iz Egipta.\"');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 13, 17, 'Kad je faraon dopustio da narod ode, Bog ih nije poveo prema filistejskoj zemlji, iako je onuda bilo najbliže. Bog je, naime, rekao: \"Mogao bi se narod predomisliti i vratiti u Egipat kad vidi ratovanje.\"');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 13, 18, 'Stoga Bog povede narod zaobilaznim putem, kroz pustinju prema Crvenome moru. Izraelci su napustili zemlju egipatsku naoružani od glave do pete.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 13, 19, 'Mojsije ponese sa sobom Josipove kosti. Jer Josip bijaše zakleo Izraelce riječima: \"Bog će se zacijelo za vas zauzeti. Tada i moje kosti odavde ponesite sa sobom!\"');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 13, 20, 'Krenuvši iz Sukota, utabore se u Etamu, na kraju pustinje.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 13, 21, 'Jahve je išao pred njima, danju u stupu od oblaka da im put pokazuje, a noću u stupu od ognja da im svijetli. Tako su mogli putovati i danju i noću.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 13, 22, 'I nije ispred naroda nestajao stup od oblaka danju ni stup od ognja noću.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 14, 1, 'Jahve reče Mojsiju:');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 14, 2, '\"Reci Izraelcima da se vrate i utabore pred Pi-Hahirotom, između Migdola i mora, nasuprot Baal-Sefonu. Utaborite se nasuprot ovome mjestu, uz more.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 14, 3, 'Faraon će reći: \'Izraelci lutaju krajem tamo-amo; pustinja ih zatvorila.\'');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 14, 4, 'Ja ću otvrdnuti faraonu srce, i on će za njima poći u potjeru. Ali ja ću se proslaviti nad faraonom i svom njegovom vojskom. Tako će Egipćani spoznati da sam ja Jahve.\" Izraelci tako učine.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 14, 5, 'Kad su egipatskom kralju kazali da je narod pobjegao, faraon i njegovi dvorani predomisliše se o narodu. \"Što ovo učinismo!\" - rekoše. \"Pustismo Izraelce i više nam neće služiti.\"');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 14, 6, 'Zato opremi faraon svoja kola i povede svoju vojsku.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 14, 7, 'Uze šest stotina svojih kola sve poizbor i ostala kola po Egiptu. I u svima bijahu štitonoše.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 14, 8, 'Jahve otvrdnu srce faraonu, kralju egipatskom, te on krenu u potjeru za Izraelcima, koji su otišli uzdignute pesnice.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 14, 9, 'Egipćani, dakle, pođu za njima u potjeru. I dok su Izraelci taborovali uz more, blizu Pi-Hahirota nasuprot Baal-Sefonu, stignu ih svi faraonovi konji pod kolima, njegovi konjanici i njegovi ratnici.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 14, 10, 'Kako se faraon približavao, Izraelci pogledaju i opaze da su Egipćani za njima u potjeri, pa ih obuzme velik strah. I poviču Izraelci Jahvi:');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 14, 11, '\"Zar nije bilo grobova u Egiptu\", reknu Mojsiju, \"pa si nas izveo da pomremo u pustinji? Kakvu si nam uslugu učinio što si nas izveo iz Egipta!');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 14, 12, 'Zar ti nismo rekli baš ovo u Egiptu: Pusti nas! Služit ćemo Egipćane! Bolje nam je i njih služiti nego u pustinji poginuti.\"');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 14, 13, '\"Ne bojte se!\" - reče Mojsije narodu. \"Stojte čvrsto pa ćete vidjeti što će vam Jahve učiniti da vas danas spasi: Egipćane koje danas vidite nikad više nećete vidjeti.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 14, 14, 'Jahve će se boriti za vas. Budite mirni!\"');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 14, 15, '\"Zašto zapomažete prema meni?\" - reče Jahve Mojsiju. \"Reci Izraelcima da krenu na put.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 14, 16, 'A ti podigni svoj štap, ispruži svoju ruku nad morem i razdijeli ga nadvoje da Izraelci mogu proći posred mora po suhu.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 14, 17, 'Ja ću otvrdnuti srce Egipćana, i oni će poći za njima, a ja ću se onda proslaviti nad faraonom i njegovim ratnicima, njegovim kolima i konjanicima.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 14, 18, 'Neka znaju Egipćani da sam ja Jahve kad se proslavim nad faraonom, njegovim kolima i njegovim konjanicima.\"');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 14, 19, 'Anđeo Božji, koji je išao na čelu izraelskih četa, promijeni mjesto i stupi im za leđa. A i stup od oblaka pomakne se ispred njih i stade im za leđa.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 14, 20, 'Smjesti se između vojske egipatske i vojske izraelske te postade onima oblak taman, a ovima rasvjetljivaše noć, tako te ne mogoše jedni drugima prići cijele noći.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 14, 21, 'Mojsije je držao ruku ispruženu nad morem dok je Jahve svu noć na stranu valjao vode jakim istočnim vjetrom i more posušio. Kad su se vode razdvojile,');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 14, 22, 'Izraelci siđoše u more na osušeno dno, a vode stajahu kao bedem njima nadesno i nalijevo.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 14, 23, 'Egipćani: svi faraonovi konji, kola i konjanici, nagnu za njima u more, u potjeru.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 14, 24, 'Za jutarnje straže pogleda Jahve iz stupa od ognja i oblaka na egipatsku vojsku i u njoj stvori zbrku.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 14, 25, 'Zakoči točkove njihovih kola da su se jedva naprijed micali. \"Bježimo od Izraelaca!\" - poviču Egipćani, \"jer Jahve se za njih bori protiv Egipćana!\" Tada će Jahve Mojsiju:');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 14, 26, '\"Pruži ruku nad more da se vode vrate na Egipćane, na njihova kola i konjanike.\"');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 14, 27, 'Mojsije pruži ruku nad more i u cik zore more se vrati u svoje korito. Kako su Egipćani, bježeći, jurili prema moru, Jahve ih strmoglavi usred voda.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 14, 28, 'Tako vode, slijevajući se natrag, potope kola, konjanike i svu vojsku faraonovu koja bijaše pošla u potjeru za Izraelcima - u more. I ne ostade od njih ni jedan jedini.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 14, 29, 'A Izraelci išli suhim posred mora, vode im stale kao zid zdesna i slijeva.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 14, 30, 'Tako Jahve u onaj dan izbavi Izraela iz šaka egipatskih, i vidje Izrael pomorene Egipćane na morskome žalu.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 14, 31, 'Osvjedoči se Izrael i o silnoj moći koju Jahve pokaza nad Egipćanima. Narod se poboja Jahve i povjerova Jahvi i njegovu sluzi Mojsiju.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 15, 1, 'Tada Mojsije s Izraelcima zapjeva ovu pjesmu Jahvi u slavu: \"U čast Jahvi zapjevat ću, jer se slavom proslavio! Konja s konjanikom u more je survao.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 15, 2, 'Moja je snaga, moja pjesma - Jahve jer je mojim postao izbaviteljem. On je Bog moj, njega ja ću slaviti, on je Bog oca moga, njega ću veličati.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 15, 3, 'Jahve je ratnik hrabar, Jahve je ime njegovo.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 15, 4, 'Kola faraonova i vojsku mu u more baci; cvijet njegovih štitonoša More crveno proguta.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 15, 5, 'Valovi ih prekriše; poput kamena u morske potonuše dubine.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 15, 6, 'Desnica tvoja, Jahve, snagom se prodiči; desnica tvoja, Jahve, raskomada dušmana.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 15, 7, 'Veličanstvom svojim obaraš ti protivnike; puštaš svoj gnjev i on ih k\'o slamu proždire.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 15, 8, 'Od daha iz tvojih nosnica vode narastoše, valovi se u bedem uzdigoše, u srcu mora dubine se stvrdnuše.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 15, 9, 'Mislio je neprijatelj: \'Gonit ću ih, stići, plijen ću podijelit\', duša će moja sita ga biti; trgnut ću mač, uništit\' ih rukom svojom.\'');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 15, 10, 'A ti dahom svojim dahnu, more se nad njima sklopi; k\'o olovo potonuše silnoj vodi u bezdane.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 15, 11, 'Tko je kao ti, Jahve među bogovima, tko kao ti sija u svetosti, u djelima strašan, divan u čudima?');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 15, 12, 'Desnicu si pružio i zemlja ih proguta!');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 15, 13, 'Milošću svojom vodio si ovaj narod, tobom otkupljen, k svetom tvom Stanu snagom si ga svojom upravio.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 15, 14, 'Kada to čuše, prodrhtaše narodi; Filistejce muke spopadoše.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 15, 15, 'Užas je srvao edomske glavare, trepet je obuzeo moapske knezove i tresu se svi koji žive u Kanaanu.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 15, 16, 'Strah i prepast na njih se obaraju; snaga tvoje ruke skamenila ih je dok narod tvoj, Jahve, ne prođe, dok ne prođe narod tvoj koji si otkupio.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 15, 17, 'Dovest ćeš ih i posaditi na gori svoje baštine, na mjestu koje ti, Jahve, svojim učini Boravištem, Svetištem, o Jahve, tvojom rukom sazidanim.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 15, 18, 'Vazda i dovijeka Jahve će kraljevati.\"');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 15, 19, 'Kad su faraonovi konji, njegova kola i konjanici sašli u more, Jahve je na njih povratio morske vode pošto su Izraelci prošli posred mora po suhu.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 15, 20, 'Tada Aronova sestra, proročica Mirjam, uze bubanj u ruku, a sve žene pridruže joj se s bubnjem u ruci i plešući.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 15, 21, 'Mirjam je začinjala pjesmu: \"Zapjevajte Jahvi jer se slavom proslavio! Konja s konjanikom u more je survao.\"');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 15, 22, 'Pokrene Mojsije Izraelce od Crvenog mora i pođu na put kroz pustinju Šur. Tri su dana putovali pustinjom, a vode nisu našli.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 15, 23, 'Dođu k Mari, ali nisu mogli piti vode kod Mare jer je bila gorka. Stoga se i zove Mara.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 15, 24, 'Narod je mrmljao na Mojsija i govorio: \"Što ćemo piti?\"');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 15, 25, 'A on zazva Jahvu. Jahve mu pokaže neko drvo. Baci on to drvo u vodu i voda postane slatka. Tu im Jahve postavi zakon i pravo i tu ih stavi u kušnju.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 15, 26, 'Zatim reče: \"Budeš li zdušno slušao glas Jahve, Boga svoga, vršeći što je pravo u njegovim očima; budeš li pružao svoje uho njegovim zapovijedima i držao njegove zakone, nikakvih bolesti koje sam pustio na Egipćane na vas neću puštati. Jer ja sam Jahve koji dajem zdravlje.\"');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 15, 27, 'Zatim stignu u Elim, gdje je bilo dvanaest izvora i sedamdeset palma. Tu se, uz vodu, utabore.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 16, 1, 'Potom krenu iz Elima, i sva izraelska zajednica dođe u pustinju Sin, koja je između Elima i Sinaja, petnaestoga dana drugoga mjeseca nakon odlaska iz zemlje egipatske.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 16, 2, 'U pustinji sva izraelska zajednica počne mrmljati protiv Mojsija i Arona.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 16, 3, '\"Oh, da smo pomrli od ruke Jahvine u zemlji egipatskoj kad smo sjedili kod lonaca s mesom i jeli kruha do mile volje!\" - rekoše im. \"Izveli ste nas u ovu pustinju da sve ovo mnoštvo gladom pomorite!\"');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 16, 4, 'Tada reče Jahve Mojsiju: \"Učinit ću da vam daždi kruh s neba. Neka narod ide i skuplja svaki dan koliko mu za dan treba. Tako ću ih kušati i vidjeti hoće li se držati moga zakona ili neće.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 16, 5, 'A šestoga dana, kad spreme što su nakupili, bit će dvaput onoliko koliko su skupljali za svaki dan.\"');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 16, 6, 'Onda Mojsije i Aron progovore svim Izraelcima: \"Večeras ćete poznati da vas je Jahve izveo iz zemlje egipatske,');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 16, 7, 'a ujutro ćete vidjeti svojim očima Jahvinu slavu, jer vas je čuo Jahve kako ste protiv njega mrmljali. Što smo mi da protiv nas mrmljate?');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 16, 8, 'Večeras će vam Jahve dati mesa da jedete\", nastavi Mojsije, \"a ujutro kruha do mile volje, jer je Jahve čuo vaše mrmljanje protiv njega. Što smo mi? Vi ne mrmljate protiv nas nego protiv Jahve.\"');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 16, 9, 'Poslije toga rekne Mojsije Aronu: \"Reci svoj izraelskoj zajednici: \'Skupite se pred Jahvu, jer je čuo vaše mrmljanje!\'\"');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 16, 10, 'I dok je Aron svoj izraelskoj zajednici govorio, oni se okrenu prema pustinji, i gle! u oblaku pojavi se Jahvina slava.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 16, 11, 'Onda se Jahve oglasi Mojsiju i reče mu:');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 16, 12, '\"Čuo sam mrmljanje Izraelaca. Ovako im reci: \'Večeras ćete jesti meso, a ujutro ćete se nasititi kruha. Tada ćete poznati da sam ja Jahve, Bog vaš.\'\"');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 16, 13, 'I doista! Navečer se pojave prepelice i prekriju tabor. A ujutro obilna rosa sve orosila oko tabora.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 16, 14, 'Kad se prevlaka rose digla, površinom pustinje ležao tanak sloj, nešto poput pahuljica, kao da se slana uhvatila po zemlji.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 16, 15, 'Kad su Izraelci to vidjeli, pitali su jedan drugoga: \"Što je to?\" Jer nisu znali što je. Onda im Mojsije reče: \"To je kruh koji vam je Jahve pribavio za hranu.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 16, 16, 'A ovo je zapovijed koju je Jahve izdao: \'Nakupite koliko kome treba za jelo - jedan gomer po osobi, svatko prema broju članova koji su mu u šatoru.\'\"');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 16, 17, 'Izraelci tako uradiše. Neki nakupe više, neki manje.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 16, 18, 'Kad su izmjerili na gomer, pokaza se da nije ništa preteklo onome koji bijaše nakupio mnogo, a niti je nedostajalo onome koji bijaše nakupio manje: svatko je nakupio koliko mu je trebalo za jelo.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 16, 19, '\"Neka nitko ne ostavlja ništa za ujutro!\" - rekne im Mojsije.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 16, 20, 'Ali oni nisu poslušali Mojsija; neki ostave i za sutra. A to im se ucrva i usmrdje. Mojsije se na njih razljuti.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 16, 21, 'Tako su skupljali svako jutro koliko je kome trebalo za jelo. I kad bi sunce ogrijalo, mÓana bi se rastopila.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 16, 22, 'Onda šestoga dana nakupiše dvostruku količinu hrane - po dva gomera na svakoga. Kad su starješine zajednice došle da izvijeste Mojsija,');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 16, 23, 'on im reče: \"Ovo je zapovijed Jahvina: Sutra je dan potpunog odmora, subota Jahvi posvećena. Ispecite što želite peći; skuhajte što želite kuhati. Sve što vam preteče ostavite za sutra.\"');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 16, 24, 'Ostave to oni za sutra, kako je Mojsije naredio, i niti se usmrdjelo niti su se crvi pojavili.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 16, 25, '\"Jedite to danas\", reče im Mojsije, \"jer je ovaj dan subota u čast Jahve; danas nećete naći mÓane na polju.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 16, 26, 'Šest je dana skupljajte, a sedmoga, u subotu, neće je biti.\"');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 16, 27, 'Bijaše nekih koji su i sedmoga dana išli da je nakupe, ali ništa ne nađoše.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 16, 28, 'Zato Jahve reče Mojsiju: \"Dokle ćete odbijati da se pokorite mojim zapovijedima i mojim zakonima?');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 16, 29, 'Pogledajte! Zato što vam je Jahve dao subotu, daje vam hrane šestoga dana za dva dana. Neka svatko stoji gdje jest; neka nitko u sedmi dan ne izlazi iz svoga stana.\"');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 16, 30, 'Tako se sedmoga dana narod odmarao.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 16, 31, 'Dom je Izraelov tu hranu prozvao mÓanom. Bijaše kao zrno korijandra; bijela, a imala je ukus medenog kolačića.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 16, 32, 'Onda rekne Mojsije: \"Ovo je zapovijed koju je izdao Jahve: Napunite tim jedan gomer i čuvajte ga za svoje potomke da vide hranu kojom sam vas hranio u pustinji kad sam vas izbavio iz zemlje egipatske.\"');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 16, 33, 'I naredi Mojsije Aronu: \"Uzmi jednu posudu; stavi u nju cio gomer mane, a onda je položi pred Jahvu da se sačuva za vaše potomke.\"');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 16, 34, 'Kako je Jahve naredio Mojsiju, Aron je stavi pred Svjedočanstvo na čuvanje.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 16, 35, 'Izraelci su se hranili manom četrdeset godina, sve dok nisu došli u naseljenu zemlju: jeli su manu do dolaska na granicu zemlje kanaanske.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 16, 36, 'Gomer je deseti dio efe.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 17, 1, 'Sva izraelska zajednica po Jahvinoj zapovijedi krene dalje iz pustinje Sina. Utabore se kod Refidima. Tu nije bilo vode da narod pije.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 17, 2, 'Zato narod zapodjene prepirku s Mojsijem. Vikali su: \"Daj nam vode da pijemo!\" A Mojsije im odgovori: \"Zašto se sa mnom prepirete? Zašto kušate Jahvu?\"');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 17, 3, 'Ali je narod žeđao za vodom, pa je mrmljao na Mojsija i govorio: \"Zašto si nas iz Egipta izveo? Zar da nas žeđom pomoriš, nas, našu djecu i našu stoku?\"');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 17, 4, '\"Što ću s ovim narodom!\" - zazivao je Mojsije Jahvu. \"Još malo pa će me kamenovati.\"');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 17, 5, '\"Istupi pred narod!\" - rekne Jahve Mojsiju. \"Uzmi sa sobom nekoliko izraelskih starješina; uzmi u ruku štap kojim si udario Rijeku i pođi.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 17, 6, 'A ja ću stajati pred tobom ondje, na pećini na Horebu. Udari po pećini: iz nje će poteći voda, pa neka se narod napije.\" Mojsije učini tako naočigled izraelskih starješina.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 17, 7, 'Mjesto prozovu Masa i Meriba, zbog toga što su se Izraelci prepirali i kušali Jahvu govoreći: \"Je li Jahve među nama ili nije?\"');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 17, 8, 'Uto dođu Amalečani i zarate s Izraelcima kod Refidima.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 17, 9, 'A Mojsije reče Jošui: \"Odaberi momčad pa pođi i zapodjeni borbu s Amalečanima. Ja ću sutra stati na vrh brda, sa štapom Božjim u ruci.\"');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 17, 10, 'Jošua učini kako mu je Mojsije rekao te zađe u borbu s Amalečanima, a Mojsije, Aron i Hur uzađoše na vrh brda.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 17, 11, 'I dok bi Mojsije držao ruke uzdignute, Izraelci bi nadjačavali; a kad bi ruke spustio, nadjačavali bi Amalečani.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 17, 12, 'Ali Mojsiju ruke napokon klonu. Zato uzeše kamen, staviše ga poda nj i on sjede, dok mu Aron i Hur, jedan s jedne, a drugi s druge strane, držahu ruke, tako da mu izdržaše do sunčanog zalaska.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 17, 13, 'I Jošua oštricom mača svlada Amaleka i njegov narod.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 17, 14, 'Onda Jahve reče Mojsiju: \"Zapiši ovo u knjigu na sjećanje i utuvi u uši Jošui da ću ja spomen na Amalečane sasvim izbrisati pod nebom!\"');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 17, 15, 'Podiže zatim Mojsije žrtvenik i nazva ga: Jahve mi je stijeg!');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 17, 16, '\"Jer\", reče, \"Jahvin stijeg u ruku! Jahvin je boj protiv Amalečana od naraštaja do naraštaja!\"');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 18, 1, 'A Jitro, midjanski svećenik, tast Mojsijev, ču sve što učini Bog Mojsiju i svemu izraelskom narodu i kako Jahve izbavi Izraelce iz Egipta.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 18, 2, 'Tada tast Mojsijev Jitro povede Siporu, Mojsijevu ženu - koju Mojsije bijaše otpustio -');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 18, 3, 'i oba njezina sina. Jednomu je bilo ime Geršon, a to će reći: \"Bijah došljak u tuđoj zemlji.\"');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 18, 4, 'Drugi se zvao Eliezer, to jest: \"Bog oca moga bio mi je u pomoći i spasio me od faraonova mača.\"');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 18, 5, 'Tako Mojsijev tast Jitro povede k Mojsiju u pustinju, gdje se Mojsije bio utaborio na Božjem brdu, njegove sinove i njegovu ženu.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 18, 6, 'Poruči on Mojsiju: \"Ja, tvoj tast Jitro, dolazim k tebi s tvojom ženom i s oba njezina sina.\"');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 18, 7, 'Izađe Mojsije u susret svome tastu; duboko mu se nakloni i zagrli ga. Pošto su se upitali za zdravlje, uđu pod šator.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 18, 8, 'Mojsije je onda pripovijedao svome tastu o svemu što je Jahve učinio faraonu i Egipćanima zbog Izraelaca; o svim nezgodama što su ih snašle na putu, ali ih je Jahve od njih izbavio.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 18, 9, 'Jitro se radovao svemu dobru koje je Jahve učinio Izraelcima i što ih je oslobodio od egipatskih šaka.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 18, 10, '\"Neka je hvaljen Jahve koji vas je izbavio od egipatskih šaka i od šaka faraonovih\", reče Jitro.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 18, 11, '\"Sada znam da je Jahve veći od svih bogova jer je izbavio narod ispod egipatske vlasti kad su s njim okrutno postupali.\"');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 18, 12, 'Zatim Jitro, Mojsijev tast, prinese Bogu žrtvu paljenicu i prinos. Uto dođe Aron i sve izraelske starješine da s Mojsijevim tastom blaguju gozbu pred Bogom.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 18, 13, 'Sutradan Mojsije sjede da kroji pravdu narodu. Narod je oko njega stajao od jutra do mraka.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 18, 14, 'Vidjevši Mojsijev tast sav trud što ga on za narod čini, rekne mu: \"Što to imaš toliko s narodom? I zašto ti sam sjediš, a sav narod stoji oko tebe od jutra do mraka?\"');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 18, 15, '\"Narod dolazi k meni\", odgovori Mojsije, \"da se s Bogom posavjetuje.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 18, 16, 'Kad zađu u prepirku, dođu k meni. Ja onda rasudim između jednoga i drugoga; izložim im Božje zakone i odredbe.\"');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 18, 17, '\"Nije dobro kako radiš\", odgovori Mojsiju tast.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 18, 18, '\"I ti i taj narod s tobom potpuno ćete se iscrpsti. Taj je posao za te pretežak; sam ga ne možeš obavljati.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 18, 19, 'Poslušaj me. Svjetovat ću te, i Bog će biti s tobom! Ti zastupaj narod pred Bogom; podastiri Bogu njihove razmirice.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 18, 20, 'Poučavaj ih o zakonima i odredbama; svraćaj ih na put kojim moraju ići, upućuj ih na djela koja moraju vršiti.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 18, 21, 'Onda proberi između svega puka ljude sposobne, bogobojazne i pouzdane, koji mrze mito, te ih postavi za glavare puku: tisućnike, stotnike, pedesetnike i desetnike.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 18, 22, 'Neka sude narodu u svako doba. Sve veće slučajeve neka preda te iznose, a u manjima neka sami rasuđuju. Olakšaj sebi breme: neka ga oni s tobom nose.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 18, 23, 'Ako tako uradiš - i Bog ti to odobri - moći ćeš izdržati, a sav ovaj narod odlazit će kući u miru.\"');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 18, 24, 'Mojsije posluša savjet svoga tasta i učini sve kako ga svjetova.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 18, 25, 'Probere Mojsije sposobnih ljudi od svih Izraelaca pa ih postavi za glavare narodu: tisućnike, stotnike, pedesetnike i desetnike.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 18, 26, 'Oni su sudili narodu u svako doba. Teže slučajeve iznosili bi Mojsiju, a sve manje rješavali sami.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 18, 27, 'Zatim Mojsije otpusti svoga tasta i on ode u svoju zemlju.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 19, 1, 'Tri mjeseca nakon izlaska iz zemlje egipatske, istoga dana, stignu Izraelci u Sinajsku pustinju.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 19, 2, 'Idući od Refidima, dođu u Sinajsku pustinju i utabore se u pustinji. Postave Izraelci tabor tu pred brdom,');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 19, 3, 'a Mojsije se popne k Bogu. Jahve ga zovne s brda pa mu rekne: \"Ovako kaži domu Jakovljevu, proglasi djeci Izraelovoj:');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 19, 4, '\'Vi ste vidjeli što sam učinio Egipćanima; kako sam vas nosio na orlovskim krilima i k sebi vas doveo.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 19, 5, 'Stoga, budete li mi se vjerno pokoravali i držali moj Savez, vi ćete mi biti predraga svojina mimo sve narode - tÓa moj je sav svijet! -');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 19, 6, 'vi ćete mi biti kraljevstvo svećenika, narod svet.\' Tim riječima oslovi Izraelce.\"');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 19, 7, 'Mojsije se vrati i sazva narodne starješine te im izloži sve što mu je Jahve naredio.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 19, 8, 'A sav narod uzvrati jednoglasno: \"Vršit ćemo sve što je Jahve naredio.\" Onda Mojsije prenese odgovor naroda Jahvi.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 19, 9, 'Nato Jahve reče Mojsiju: \"Ja ću, evo, doći k tebi u gustom oblaku da narod čuje kad budem s tobom govorio i da ti zauvijek vjeruje.\" Tako je Mojsije prenio Jahvi odgovor naroda.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 19, 10, '\"Pođi k narodu\", reče Jahve Mojsiju, \"i posvećuj ga danas i sutra. Neka opere svoju odjeću;');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 19, 11, 'neka bude gotov prekosutra, jer će prekosutra sići Jahve na brdo Sinaj naočigled svega puka.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 19, 12, 'Postavi naokolo granicu za narod i izdaj naredbu: \'Pripazite da se na brdo ne penjete; da se ni podnožja ne dotičete! Tko se god brda dotakne, smrt će ga snaći.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 19, 13, 'Nikakva ruka neka ga se ne dotakne, nego neka bude kamenjem zasut ili strijelom ustrijeljen: bio čovjek ili živinče, neka na životu ne ostane.\' Na otegnuti zvuk trube neka se na brdo penju.\"');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 19, 14, 'Mojsije siđe s brda k narodu i poče posvećivati narod. Oni operu svoju odjeću.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 19, 15, '\"Budite gotovi za prekosutra!\" - rekne Mojsije narodu. \"Ne primičite se ženi!\"');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 19, 16, 'A prekosutra, u osvit dana, prolomi se grmljavina, munje zasijevaše, a gust se oblak nadvi nad brdo. Gromko zaječa truba, zadrhta sav puk koji bijaše u taboru.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 19, 17, 'Mojsije povede puk iz tabora u susret Bogu. Stadoše na podnožju brda.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 19, 18, 'Brdo Sinaj zavilo se u dim jer je Jahve u obliku ognja sišao na nj. Dizao se dim kao dim iz peći. Sve se brdo silno treslo.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 19, 19, 'Zvuk trube bivao sve jači. Mojsije je govorio, a Bog mu grmljavinom odgovarao.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 19, 20, 'Jahve siđe na Sinajsko brdo, na vrhunac, i pozva Jahve Mojsija na vrhunac brda. Mojsije se uspe.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 19, 21, 'Sad Jahve reče Mojsiju: \"Siđi i opomeni narod da ne bi provalio prema Jahvi da ga vidi. Mnogo bi ih poginulo.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 19, 22, 'I sami svećenici, koji dolaze blizu Jahvi, moraju se očistiti, da ih Jahve ne uništi.\"');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 19, 23, '\"Narod se ne može popeti na brdo Sinaj\", odgovori Mojsije Jahvi, \"jer si nas sam ti opomenuo: \'Postavi granice naokolo brda i proglasi ga svetim.\'\"');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 19, 24, '\"Siđi pa se opet popni zajedno s Aronom\", odgovori mu Jahve. \"Ali neka svećenici i narod ne navaljuju da se popnu prema Jahvi da ne izginu.\"');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 19, 25, 'Mojsije siđe k narodu i sve mu kaza.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 20, 1, 'Onda Bog izgovori sve ove riječi:');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 20, 2, '\"Ja sam Jahve, Bog tvoj, koji sam te izveo iz zemlje egipatske, iz kuće ropstva.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 20, 3, 'Nemoj imati drugih bogova uz mene.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 20, 4, 'Ne pravi sebi lika ni obličja bilo čega što je gore na nebu, ili dolje na zemlji, ili u vodama pod zemljom.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 20, 5, 'Ne klanjaj im se niti im služi. Jer ja, Jahve, Bog tvoj, Bog sam ljubomoran. Kažnjavam grijeh otaca - onih koji me mrze - na djeci do trećeg i četvrtog koljena,');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 20, 6, 'a iskazujem milosrđe tisućama koji me ljube i vrše moje zapovijedi.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 20, 7, 'Ne uzimaj uzalud imena Jahve, Boga svoga, jer Jahve ne oprašta onome koji uzalud izgovara ime njegovo.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 20, 8, 'Sjeti se da svetkuješ dan subotni.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 20, 9, 'Šest dana radi i obavljaj sav svoj posao.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 20, 10, 'A sedmoga je dana subota, počinak posvećen Jahvi, Bogu tvojemu. Tada nikakva posla nemoj raditi: ni ti, ni sin tvoj, ni kći tvoja, ni sluga tvoj, ni sluškinja tvoja, ni živina tvoja, niti došljak koji se nađe unutar tvojih vrata.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 20, 11, 'Ta i Jahve je šest dana stvarao nebo, zemlju i more i sve što je u njima, a sedmoga je dana počinuo. Stoga je Jahve blagoslovio i posvetio dan subotni.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 20, 12, 'Poštuj oca svoga i majku svoju da imadneš dug život na zemlji koju ti da Jahve, Bog tvoj.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 20, 13, 'Ne ubij!');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 20, 14, 'Ne učini preljuba!');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 20, 15, 'Ne ukradi!');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 20, 16, 'Ne svjedoči lažno na bližnjega svoga!');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 20, 17, 'Ne poželi kuće bližnjega svoga! Ne poželi žene bližnjega svoga; ni sluge njegova, ni sluškinje njegove, ni vola njegova, ni magarca njegova, niti išta što je bližnjega tvoga!\"');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 20, 18, 'Sav je puk bio svjedok grmljavine i sijevanja, svi čuše zvuk trube i vidješe kako se brdo dimi: gledali su i tresli se i stajali podalje.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 20, 19, 'Onda rekoše Mojsiju: \"Ti nam govori, a mi ćemo slušati. Neka nam Bog ne govori, da ne pomremo!\"');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 20, 20, '\"Ne bojte se\", reče Mojsije narodu. \"Bog je došao da vas samo iskuša; da strah pred njim ostane s vama te da ne griješite.\"');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 20, 21, 'Narod ostane podalje, a Mojsije pristupi gustom oblaku gdje se Bog nalazio.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 20, 22, '\"Ovako reci Izraelcima\", progovori Jahve Mojsiju. \"Sami ste vidjeli da sam s vama govorio s neba.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 20, 23, 'Ne pravite uza me kumira od srebra niti sebi pravite kumira od zlata.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 20, 24, 'Načini mi žrtvenik od zemlje i na njemu mi prinosi svoje žrtve paljenice i žrtve pričesnice, svoju sitnu i svoju krupnu stoku. Na svakome mjestu koje odredim da se moje ime spominje ja ću doći k tebi da te blagoslovim.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 20, 25, 'Ako mi budeš gradio kameni žrtvenik, nemoj ga graditi od klesanoga kamena, jer čim na nj spustiš svoje dlijeto, oskvrnit ćeš ga.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 20, 26, 'Ne uzlazi na moj žrtvenik po stepenicama, da se ne pokaže na njemu golotinja tvoja.\"');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 21, 1, '\"Ovo su propisi koje treba da im izložiš:');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 21, 2, 'Kad za roba kupiš jednoga Hebreja, neka služi šest godina. Sedme godine neka ode, bez otkupnine, slobodan.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 21, 3, 'Ako dođe sam, neka sam i ode; ako li je oženjen, neka s njim ide i njegova žena.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 21, 4, 'Ako mu gospodar nabavi ženu, pa mu ona rodi bilo sinova bilo kćeri, i žena i njezina djeca neka pripadnu njezinu gospodaru, a on neka ide sam.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 21, 5, 'Ali ako rob otvoreno izjavi: \'Volim svoga gospodara, svoju ženu i svoju djecu, neću da budem slobodan\',');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 21, 6, 'neka ga onda njegov gospodar dovede k Bogu. Kad ga dovede k vratima ili dovratku, neka mu gospodar šilom probuši uho i neka mu trajno ostane u službi.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 21, 7, 'Kad čovjek proda svoju kćer za ropkinju, neka se ona ne oslobađa kao i muški robovi.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 21, 8, 'Ako se ne svidi svome gospodaru, koji ju je sebi bio odredio, neka joj dopusti da se otkupi. Nema prava prodati je strancima kad joj nije bio vjeran.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 21, 9, 'A ako je odredi svome sinu, neka s njome postupa kao i sa kćeri.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 21, 10, 'Ako se oženi drugom, ne smije prvoj uskraćivati hrane, odjeće ili njezinih bračnih prava.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 21, 11, 'Ne bude li joj činio ovo troje, neka je slobodna da ode bez otkupnine.\"');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 21, 12, '\"Tko god udari čovjeka pa ga usmrti, neka se smrću kazni.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 21, 13, 'Ali ako to ne učini hotimično, nego Bog pripusti da padne u njegovu šaku, odredit ću ti mjesto kamo može pobjeći.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 21, 14, 'Tko hotimično navali na svoga bližnjega te ga podmuklo ubije, odvuci ga i s moga žrtvenika da se pogubi.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 21, 15, 'Tko udari svoga oca ili svoju majku, neka se kazni smrću.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 21, 16, 'Tko otme čovjeka - bilo da ga proda, bilo da ga u svojoj vlasti zadrži - neka se kazni smrću.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 21, 17, 'Tko prokune svoga oca ili svoju majku, neka se kazni smrću.\"');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 21, 18, '\"Ako se ljudi posvade, pa jedan od njih udari drugoga kamenom ili šakom, ali ovaj ne pogine nego padne u postelju,');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 21, 19, 'ali poslije ustane i mogne izlaziti, makar i sa štapom, onda onome koji ga je udario neka je oprošteno, samo neka mu plati njegov gubitak vremena i pribavi mu posvemašnje izlječenje.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 21, 20, 'Ako tko udari batinom svoga roba ili svoju ropkinju te umru pod njegovom šakom, mora snositi osvetu.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 21, 21, 'Ali ako rob preživi dan-dva, neka se osveta ne provodi, jer je rob njegovo vlasništvo.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 21, 22, 'Ako se ljudi pobiju i udare trudnu ženu te ona pobaci, ali druge štete ne bude, onda onaj koji ju je udario neka plati odštetu koju zatraži njezin muž. On neka plati kako suci odrede.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 21, 23, 'Bude li drugog zla, neka je kazna: život za život,');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 21, 24, 'oko za oko, zub za zub, ruka za ruku, noga za nogu,');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 21, 25, 'opeklina za opeklinu, rana za ranu, modrica za modricu.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 21, 26, 'Udari li tko svoga roba ili svoju ropkinju u oko i upropasti ga, neka ga oslobodi zbog oka.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 21, 27, 'Ako izbije zub svome robu - ili svojoj ropkinji - neka ga oslobodi zbog zuba.\"');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 21, 28, '\"Kad goveče ubode čovjeka ili ženu pa ih usmrti, neka se kamenjem kamenuje. Njegovo se meso tada ne smije pojesti, a vlasniku njegovu neka je oprošteno.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 21, 29, 'Ali ako je to goveče i prije bolo, a njegov vlasnik, iako opominjan, nije ga čuvao, pa ono usmrti čovjeka ili ženu, neka se to goveče kamenuje; a i njegov se vlasnik ima pogubiti.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 21, 30, 'Ako se vlasniku označi otkupna cijena da svoj život iskupi, neka plati koliko mu se odredi.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 21, 31, 'Ubode li goveče dječaka ili djevojčicu, neka se prema njemu postupi isto prema ovome pravilu.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 21, 32, 'Ako ubode roba ili ropkinju, neka vlasnik isplati njihovu gospodaru trideset srebrnih šekela, a goveče neka se kamenuje.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 21, 33, 'Kad tko ostavi bunar otvoren, ili tko iskopa bunar a ne pokrije ga, pa u nj upadne goveče ili magare, vlasnik bunara ima dati naknadu:');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 21, 34, 'neka isplati vlasniku u novcu, a uginula životinja neka njemu pripadne.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 21, 35, 'Kad nečije goveče ubode goveče drugome te ono ugine, onda neka prodaju živo goveče, a dobiveni novac neka podijele; i uginulo goveče neka među sebe podijele.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 21, 36, 'Ali ako se zna da je to goveče i prije bolo, a njegov ga gospodar nije čuvao, onda mora nadoknaditi goveče za goveče, dok će uginulo živinče biti njegovo.\"');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 21, 37, '\"Tko ukrade goveče ili marvinče od sitne stoke, pa bilo da ga zakolje, bilo da ga proda, onda za jedno goveče neka se vrati petero goveda, a za malo marvinče četvero marvinčadi.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 22, 1, 'Ako se lopov zateče gdje probija zid, pa mu se zada smrtan udarac, njegovu krv ne treba osvećivati.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 22, 2, 'No ako je već izišlo sunce, njegovu krv treba osvetiti. Lopov mora štetu nadoknaditi. Ako nema ništa, njega za njegovu krađu treba prodati.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 22, 3, 'Nađe li se ukradeno živinče živo u njegovu vlasništvu - goveče, magare ili koja glava sitne stoke - treba da ga plati dvostruko.\"');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 22, 4, '\"Tko opustoši njivu ili vinograd pustivši svoju stoku da obrsti tuđe, neka nadoknadi onim što najbolje nađe na svojoj njivi i u svome vinogradu.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 22, 5, 'Tko zapali vatru pa ona zahvati drač te izgori žito u snopu, u klasu ili na njivi, onaj tko je vatru zapalio mora štetu nadoknaditi.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 22, 6, 'Kad tko položi kod znanca novac ili stvari na čuvanje, pa budu pokradene iz njegove kuće, ako se lopov pronađe, mora dvostruko platiti.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 22, 7, 'Ako se lopov ne pronađe, vlasnik kuće neka se primakne k Bogu, da se dokaže kako on nije spustio svoje ruke na dobra svoga bližnjega.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 22, 8, 'Za svaki prekršaj pronevjere - radilo se o govečetu, magaretu, sitnoj stoci, odjeći ili bilo kojoj izgubljenoj stvari za koju se ustvrdi: to je ono! - treba spor iznijeti pred Boga. Onaj koga Bog proglasi krivim neka plati dvostruko drugome.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 22, 9, 'Kad tko povjeri svome susjedu magare, goveče, glavu sitne stoke ili bilo kakvo živinče, pa ono ugine, osakati se ili ga tko odvede a da ne bude svjedoka,');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 22, 10, 'zakletva pred Jahvom neka odluči među obojicom je li čuvar posegao za dobrom svoga bližnjega ili nije. Neka je vlasniku to dovoljno, a čuvar nije dužan da nadoknađuje.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 22, 11, 'Nađe li se da je on ukrao, mora štetu nadoknaditi.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 22, 12, 'Ako ga zvijer razdere, neka ga donese za dokaz, tako da za razderano ne daje odštete.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 22, 13, 'Kad tko posudi živinu na izor od svoga susjeda, pa se ona osakati ili ugine dok joj vlasnik nije bio s njom, neka plati odštetu.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 22, 14, 'Je li vlasnik bio s njom, odštete mu ne daje; ali ako je bila unajmljena na izor, neka dođe po svoju nadnicu.\"');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 22, 15, '\"Ako tko zavede djevojku koja nije zaručena i s njom legne, neka za nju dadne ženidbenu procjenu i uzme je za ženu.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 22, 16, 'Ako njezin otac odbije da mu je dadne, zavodnik mora odmjeriti srebra u vrijednosti ženidbene procjene za djevojku.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 22, 17, 'Ne dopuštaj da vračarica živi!');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 22, 18, 'Tko bi god sa živinom legao, treba ga kazniti smrću.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 22, 19, 'Tko bi prinosio žrtve kojemu kumiru - osim Jahvi jedinom - neka bude izručen prokletstvu, potpuno uništen.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 22, 20, 'Ne tlači pridošlicu niti mu nanosi nepravde, jer ste i sami bili pridošlice u zemlji egipatskoj.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 22, 21, 'Ne cvilite udovice i siročeta!');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 22, 22, 'Ako ih ucviliš i oni zavape k meni, sigurno ću njihove vapaje uslišati.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 22, 23, 'Moj će se gnjev raspaliti i mačem ću vas pogubiti. Tako će vam žene ostati udovice a djeca siročad.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 22, 24, 'Ako uzajmiš novca kome od moga naroda, siromahu koji je kod tebe, ne postupaj prema njemu kao lihvar! Ne nameći mu kamata!');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 22, 25, 'Uzmeš li svome susjedu ogrtač u zalog, moraš mu ga vratiti prije zalaza sunca.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 22, 26, 'TÓa to mu je jedini pokrivač kojim omata svoje tijelo i u kojem može leći. Ako k meni zavapi, uslišat ću ga jer sam ja milostiv!');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 22, 27, 'Ne huli Boga i ne psuj glavara svoga naroda.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 22, 28, 'Ne oklijevaj s prinosima od svoga obilja s gumna i od svoga mladog vina! Meni daj prvorođenca od svojih sinova.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 22, 29, 'Isto učini sa svojim govedima i sitnom stokom: sedam dana neka ostane sa svojom majkom, a osmoga dana da si ga meni dao!');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 22, 30, 'Budite narod meni posvećen! Zato nemojte jesti mesa od životinje koju je rastrgala zvjerad nego je bacite paščadi!\"');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 23, 1, '\"Nemojte davati lažne izjave! Ne pomaži zlikovcu svjedočeći krivo!');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 23, 2, 'Ne povodi se za mnoštvom da činiš zlo; niti svjedoči u parnici stajući na stranu većine protiv pravde.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 23, 3, 'Ne smiješ biti pristran prema siromahu u njegovoj parnici.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 23, 4, 'Kad nabasaš na zalutalo goveče ili magare svoga neprijatelja, moraš mu ga natrag dovesti.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 23, 5, 'Ako opaziš magarca onoga koji te mrzi kako je pao pod svojim tovarom, nemoj ga ostaviti: zajedno s njegovim gospodarom moraš mu pomoći da se digne.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 23, 6, 'Ne krnji prava svome siromahu u njegovoj parnici.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 23, 7, 'Stoj daleko od lažne optužbe; ne ubijaj nedužna i pravedna, jer ja zlikovcu ne praštam.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 23, 8, 'Ne primaj mita, jer mito zasljepljuje i one koji najjasnije gledaju i upropašćuje pravo pravednika.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 23, 9, 'Ne ugnjetavaj pridošlicu! TÓa znate kako je pridošlici; i sami ste bili pridošlice u zemlji egipatskoj.\"');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 23, 10, '\"Šest godina zasijavaj svoju zemlju i njezine plodove pobiri,');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 23, 11, 'a sedme je godine pusti da počiva neobrađena. Neka se s nje hrani sirotinja tvoga naroda, a što njoj ostane, neka pojede poljska živina. Radi tako i sa svojim vinogradom i svojim maslinikom.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 23, 12, 'Šest dana obavljaj svoj posao, ali sedmoga dana od posala odustani, da ti otpočine vo i magarac i da odahne sin tvoje sluškinje i pridošlica.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 23, 13, 'Pripazite na sve što sam vam rekao. Ne spominjite imena drugih bogova. Neka se to i ne čuje iz tvojih usta.\"');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 23, 14, '\"Triput na godinu održavaj u moju čast svetkovinu.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 23, 15, 'Slavi Blagdan beskvasnoga kruha. U određeno vrijeme u mjesecu Abibu - jer si u njemu iz Egipta izišao - sedam dana jedi beskvasan kruh, kako sam ti naredio. Neka nitko ne stupa preda me praznih ruku!');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 23, 16, 'Onda slavi Blagdan žetve - prvina što ih donose polja koja zasijavaš. Zatim Blagdan berbe na koncu godine, kad s polja pokupiš plodove svoga truda.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 23, 17, 'Triput na godinu neka svi tvoji muški stupe pred Gospodara Jahvu.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 23, 18, 'Krv žrtve koju u moju čast žrtvuješ nemoj prinositi s ukvasanim kruhom; salo od žrtve prinesene na moju svetkovinu ne ostavljaj za sutradan.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 23, 19, 'Donosi u kuću Jahve, svoga Boga, najbolje prvine sa svoje zemlje. Ne kuhaj kozleta u mlijeku njegove majke.\"');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 23, 20, '\"Šaljem, evo, svog anđela pred tobom da te čuva na putu i dovede te u mjesto koje sam priredio.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 23, 21, 'Poštuj ga i slušaj! Ne buni se protiv njega, jer vam neće opraštati prekršaje: tÓa moje je ime u njemu.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 23, 22, 'Ako mu se budeš vjerno pokoravao i budeš vršio sve što sam naredio, ja ću biti neprijatelj tvojim neprijateljima i protivnik tvojim protivnicima.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 23, 23, 'Anđeo će moj ići pred tobom i dovesti te do Amorejaca, Hetita, Perižana, Kanaanaca, Hivijaca i Jebusejaca da ih uništim.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 23, 24, 'Nemoj se klanjati njihovim kumirima niti im iskazuj štovanje; ne postupaj kako oni rade nego njihove kumire poruši i stupove im porazbijaj.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 23, 25, 'Iskazujte štovanje Jahvi, Bogu svome, pa ću blagoslivati tvoj kruh i tvoju vodu i uklanjati od tebe bolest.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 23, 26, 'U tvojoj zemlji neće biti pometkinje; ja ću učiniti punim broj tvojih dana.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 23, 27, 'Pred tobom ću odaslati stravu svoju; u metež ću baciti sav svijet među koji dospiješ i učinit ću da svi tvoji neprijatelji bježe pred tobom.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 23, 28, 'Stršljene ću pred tobom odašiljati da ispred tebe tjeraju u bijeg Hivijce, Kanaance i Hetite.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 23, 29, 'Neću ih otjerati ispred tebe u jednoj godini, da zemlja ne opusti i divlje se životinje ne razmnože na tvoju štetu.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 23, 30, 'Tjerat ću ih ispred tebe malo-pomalo dok ti potomstvo ne odraste, tako da zemlju zaposjedneš.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 23, 31, 'Postavit ću ti granicu: od Crvenoga do Filistejskoga mora, od pustinje pa do Rijeke. Predat ću, naime, stanovništvo zemlje u tvoje šake, a ti ga ispred sebe tjeraj.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 23, 32, 'Ne pravi savez ni s njima ni s njihovim kumirima.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 23, 33, 'Neka ne ostanu u tvojoj zemlji da te ne navode na grijeh protiv mene. Ako bi štovao njihove kumire, to bi ti bila stupica.\"');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 24, 1, 'Potom reče Mojsiju: \"Uzađi k Jahvi - ti, Aron, Nadab i Abihu i sedamdeset izraelskih starješina. Poklonite se izdaljega!');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 24, 2, 'Neka se sam Mojsije primakne k Jahvi! Oni neka se ne primiču, a puk neka se s njim ne penje.\"');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 24, 3, 'Dođe Mojsije i kaza narodu sve riječi Jahvine i sve odredbe. A sav puk odgovori u jedan glas: \"Sve riječi što ih Jahve reče, vršit ćemo.\"');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 24, 4, 'Tada Mojsije popiše sve riječi Jahvine. A ujutro podrani te podigne žrtvenik na podnožju brda i dvanaest stupova za dvanaest plemena Izraelovih.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 24, 5, 'Zatim naloži mladim Izraelcima da prinesu žrtve paljenice i da žrtvuju Jahvi junce kao žrtve pričesnice.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 24, 6, 'Mojsije uhvati krv; polovinu krvi ulije u posude, a polovinu izlije po žrtveniku.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 24, 7, 'Prihvati zatim Knjigu Saveza pa je narodu glasno pročita, a narod uzvrati: \"Sve što je Jahve rekao, izvršit ćemo i poslušat ćemo.\"');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 24, 8, 'Mojsije potom uzme krvi te poškropi narod govoreći: \"Ovo je krv Saveza koji je Jahve s vama uspostavio na temelju svih ovih riječi.\"');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 24, 9, 'Onda se uspne Mojsije s Aronom, Nadabom i Abihuom i sa sedamdeset starješina Izraelovih.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 24, 10, 'Oni vidješe Boga Izraelova: podnožje njegovim nogama kao da je bilo od dragoga kamena safira, sjajem nalik na samo nebo.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 24, 11, 'Ni ruke svoje nije pružio na izabranike Izraelaca: slobodno su Boga motrili i jeli i pili.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 24, 12, 'Onda Jahve reče Mojsiju: \"Popni se k meni na brdo i pričekaj ondje. Dat ću ti kamene ploče sa zakonom i zapovijedima koje sam za njihovu pouku napisao.\"');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 24, 13, 'Ustane Mojsije i njegov pomoćnik Jošua te se Mojsije popne na brdo Božje.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 24, 14, 'A starješinama reče: \"Čekajte nas ovdje dok se ne vratimo. Eto je s vama Aron i Hur. Tko imadne kakvu razmiricu, neka se obrati na njih.\"');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 24, 15, 'Zatim Mojsije uzađe na brdo, a onda oblak prekri brdo.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 24, 16, 'Slava se Jahvina nastani na Sinajskom brdu i oblak ga obavijaše šest dana. Sedmoga dana zovne Jahve Mojsija isred oblaka.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 24, 17, 'Slava Jahvina na vrhuncu brda bijaše očima Izraelaca kao vatra koja sažiže. Mojsije zađe u oblak i uspne se na brdo.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 24, 18, 'Četrdeset dana i četrdeset noći boravio je Mojsije na brdu.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 25, 1, 'Jahve reče Mojsiju:');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 25, 2, '\"Reci Izraelcima da me darivaju, a vi primajte darove u moju čast od svakoga koji daje od srca.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 25, 3, 'A primajte ove darove: zlato, srebro i tuč;');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 25, 4, 'ljubičasto, crveno i tamnocrveno predivo i prepredeni lan;');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 25, 5, 'učinjene ovnujske kože, pa fine kože; bagremovo drvo;');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 25, 6, 'ulje za svjetlo; mirodije za ulje pomazanja i miomirisno kađenje;');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 25, 7, 'oniks i drugo drago kamenje koje će se umetnuti u oplećak i naprsnik.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 25, 8, 'Neka mi sagrade Svetište da mogu boraviti među njima.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 25, 9, 'Pri gradnji Prebivališta i svega u njemu postupi točno prema uzorku koji ti pokažem.\"');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 25, 10, '\"Od bagremova drva neka naprave Kovčeg: dva i po lakta dug, lakat i po širok i lakat i po visok.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 25, 11, 'Okuj ga čistim zlatom, okuj ga izvana i iznutra; a oko njega stavi naokolo završni pojas od zlata.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 25, 12, 'Salij za nj četiri zlatna koluta; prikuj ih za četiri njegove noge; dva koluta s jedne strane, a dva s druge.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 25, 13, 'Od bagremova drva napravi i motke te ih u zlato okuj.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 25, 14, 'Onda provuci motke kroz kolutove sa strana Kovčega da se na njima Kovčeg nosi.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 25, 15, 'Neka motke ostanu u kolutima Kovčega; neka se iz njih ne izvlače.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 25, 16, 'Svjedočanstvo koje ću ti predati - u Kovčeg položi.\"');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 25, 17, '\"Pomirilište napravi također od čistoga zlata. Neka bude dugo dva i pol lakta, a široko lakat i pol.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 25, 18, 'Skuj i dva kerubina od zlata za oba kraja Pomirilišta.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 25, 19, 'Napravi jednoga kerubina za jedan kraj, a drugoga kerubina za drugi kraj. Pričvrsti ih na oba kraja Pomirilišta da s njim sačinjavaju jedan komad.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 25, 20, 'Kerubini neka dignu svoja krila uvis tako da svojim krilima zaklanjaju Pomirilište. Neka budu licem okrenuti jedan prema drugome, ali tako da lica kerubina gledaju u Pomirilište.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 25, 21, 'Stavi na Kovčeg Pomirilište, a u Kovčeg položi ploče Svjedočanstva što ću ti ih dati.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 25, 22, 'Tu ću se ja s tobom sastajati i ozgo ću ti, iznad Pomirilišta - između ona dva kerubina što su na Kovčegu ploča Svjedočanstva - saopćavati sve zapovijedi namijenjene Izraelcima.\"');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 25, 23, '\"Napravi od bagremova drva stol dva lakta dug, lakat širok, a lakat i pol visok.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 25, 24, 'U čisto ga zlato obloži i načini mu naokolo završni pojas od zlata.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 25, 25, 'Naokolo mu načini obrub, podlanicu širok, a onda po obrubu stavi završni pojas od zlata.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 25, 26, 'Nadalje, uspravi mu četiri koluta od zlata pa mu ih pričvrsti na njegova četiri nožna ugla.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 25, 27, 'Neka su kolutovi tik pod obrubom da služe kao kvake motkama za nošenje stola.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 25, 28, 'Motke napravi od bagremova drva i u zlato ih okuj. O njima će se stol nositi.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 25, 29, 'Za nj onda napravi: zdjele, varjače, vrčeve i pehare za izlijevanje prinosa. Načini ih od čistoga zlata.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 25, 30, 'Na stol svagda stavljaj pred moje lice prineseni kruh.\"');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 25, 31, '\"Načini svijećnjak od čistoga zlata. Svijećnjak neka bude skovan. Njegovo podnožje, njegov stalak, njegove čaše, čaške i latice - sve neka bude od jednoga komada.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 25, 32, 'Šest krakova neka mu izbija sa strana: tri kraka s jedne strane stalka, a tri kraka s druge strane stalka.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 25, 33, 'Na jednome kraku neka budu tri čaše u obliku bademova cvijeta, svaka s čaškom i laticama. Tako za svih šest krakova što budu izbijali iz stalka svijećnjaka.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 25, 34, 'Na samome svijećnjaku neka budu četiri čaše u obliku bademova cvijeta, svaka s čaškom i laticama.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 25, 35, 'Čaška ispod dva kraka, sačinjavajući jedan komad s njime; onda čaška ispod druga dva kraka, od jednoga komada s njime, pa čaška ispod dva posljednja kraka, od jednoga komada s njime. Tako za svih šest krakova što iz stalka budu izbijali.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 25, 36, 'Njihove čaške i njihovi krakovi sačinjavat će jedan komad s njim - sve skovano u jednome komadu od čistoga zlata.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 25, 37, 'Napravi i sedam svjetiljaka za njih. Svjetiljke neka tako budu postavljene da osvjetljuju prostor sprijeda.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 25, 38, 'Usekači i pepeljare za njih neka su od čistoga zlata.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 25, 39, 'Upotrijebi talenat čistoga zlata za svijećnjak i sav njegov pribor.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 25, 40, 'Pazi! Načini ih prema uzorku koji ti je na brdu pokazan.\"');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 26, 1, '\"Prebivalište načini od deset zavjesa: od ljubičastog, crvenog i tamnocrvenog prediva i prepredenog lana. Na njima neka budu vezeni likovi kerubina - djelo umjetnika.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 26, 2, 'Dužina svake zavjese neka je dvadeset i osam lakata, neka joj je širina četiri lakta. Sve zavjese neka su iste mjere.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 26, 3, 'Pet zavjesa neka su sastavljene jedna s drugom, a drugih pet zavjesa opet jedna s drugom.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 26, 4, 'Napravi petlje od ljubičaste vune pri rubu krajnje zavjese u sastavljenom komadu.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 26, 5, 'Napravi pedeset petlji na rubu jednoga sastavljenog komada od zavjesa, a pedeset pri rubu drugoga. Neka su petlje načinjene jedna spram druge.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 26, 6, 'Onda napravi pedeset kopča od zlata. Zavjese zatim kopčama sastavi jednu s drugom. Tako će Prebivalište biti jedna cjelina.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 26, 7, 'Načini zatim zavjese od kostrijeti za Šator povrh Prebivališta. Načini ih jedanaest.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 26, 8, 'Neka duljina svake zavjese bude trideset lakata, a širina svake zavjese četiri lakta. Tih jedanaest zavjesa neka bude iste mjere.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 26, 9, 'Sastavi pet zavjesa napose, a onda opet drugih šest zavjesa napose. Šestu zavjesu podvostruči na pročelju Šatora.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 26, 10, 'Ušij pedeset petlji na rubu jednoga sastavljenog komada od zavjesa, a pedeset na rubu drugoga.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 26, 11, 'Izradi pedeset kopča od tuča, zapni kopče za petlje da sastaviš Šator u cjelinu.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 26, 12, 'A kako će zavjese od Šatora pretjecati, neka se polovina zavjesa što preostane spušta na zadnjem dijelu Prebivališta.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 26, 13, 'Od onoga što preteče na dužini šatorskih zavjesa neka po jedan lakat visi na obje strane svetoga Šatora da ga zaklanja.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 26, 14, 'Napokon napravi Šatoru pokrov od učinjenih i u crveno obojenih ovnujskih koža, a povrh njega pokrov od finih koža.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 26, 15, 'Trenice što će nauzgor stajati za Prebivalište napravi od bagremova drva.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 26, 16, 'Svaka trenica neka bude deset lakata duga, a lakat i pol široka.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 26, 17, 'Svaka trenica neka ima dva klina da je uspravno drže. Tako napravi na svakoj trenici za Prebivalište.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 26, 18, 'Trenice za Prebivalište postavi: dvadeset trenica s juga, prema podnevu;');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 26, 19, 'onda pod dvadeset trenica napravi četrdeset podnožja od srebra, dva podnožja pod prvu trenicu za njezina dva klina, i tako redom, dva podnožja za dva klina svake slijedeće trenice.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 26, 20, 'Za drugu stranu Prebivališta, sa sjevera: dvadeset trenica');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 26, 21, 'i četrdeset srebrnih podnožja, dva podnožja za dva klina prve trenice, i tako redom, dva podnožja za svaku trenicu.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 26, 22, 'Na stražnjoj strani Prebivališta, sa zapada, postavi šest trenica.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 26, 23, 'Napravi i dvije trenice za stražnje uglove Prebivališta.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 26, 24, 'Neka budu rastavljene pri dnu, ali na vrhu kod prvoga koluta neka budu sastavljene. Neka tako obadvije prave dva ugla.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 26, 25, 'Neka dakle bude osam trenica s njihovim srebrnim podnožjima: šesnaest podnožja, dva podnožja pod prvom trenicom, a dva opet podnožja pod svakom slijedećom trenicom.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 26, 26, 'Nadalje napravi priječnice od bagremova drva: pet njih za trenice s jedne strane Prebivališta,');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 26, 27, 'a pet priječnica s druge strane Prebivališta; onda pet priječnica za trenice Prebivališta straga prema zapadu.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 26, 28, 'Srednja priječnica neka ide sredinom trenica s jednoga kraja na drugi.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 26, 29, 'Trenice obloži zlatom, a i kolutove za njih, kroz koje će se priječnice provlačiti, načini od zlata. Priječnice onda obloži zlatom.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 26, 30, 'Tako, dakle, podigni Prebivalište prema nacrtu koji ti je pokazan na brdu.\"');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 26, 31, '\"Napravi zavjesu od ljubičastog, crvenog i tamnocrvenog prediva i prepredenog lana. Neka su na njoj izvezeni kerubini.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 26, 32, 'Objesi je na četiri stupa od bagremova drva, zlatom obložena, s kopčama od zlata, a na četiri podnožja od srebra.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 26, 33, 'Objesi zavjesu za kvake. Onda unesi Kovčeg svjedočanstva tu za zavjesu. Neka ti tako zavjesa odjeljuje Svetište od Svetišta nad svetištima.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 26, 34, 'Stavi Pomirilište na Kovčeg svjedočanstva u Svetinji nad svetinjama.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 26, 35, 'Postavi zatim stol van pred zavjesu, a svijećnjak na južnu stranu Prebivališta, prema stolu. Stol stavi na sjevernu stranu.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 26, 36, 'A na ulazu u Šator napravi zastorak od ljubičastog, crvenog i tamnocrvenog prediva i prepredenog lana - vezom izvezen.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 26, 37, 'Za zastorak isteši pet stupčića od bagrenova drva pa ih obloži zlatom. Kopče za njih neka budu od zlata. Salij za njih pet podnožja od tuča.\"');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 27, 1, '\"Načini žrtvenik od bagremova drva, pet lakata dug, pet lakata širok - prava četvorina - i tri lakta visok.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 27, 2, 'Na njegova četiri ugla načini rogove. Neka mu rogovi budu u jednome komadu s njim. I tučem ga okuj.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 27, 3, 'Dalje, načini za žrtvenik posude za zgrtanje otpadaka: strugače, kotliće, viljuške i kadionike. Sve potrepštine za žrtvenik načini od tuča.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 27, 4, 'Onda načini za nj rešetku od tuča, u obliku mrežice,');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 27, 5, 'a na četiri ugla mrežicu ispod izbočine žrtvenika, tako da zahvati do sredine žrtvenika.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 27, 6, 'Napravi zatim motke za žrtvenik, motke od bagremova drva, pa ih tučem okuj.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 27, 7, 'Neka se motke provuku kroz kolutove, tako da dođu na obje strane žrtvenika kad se nosi.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 27, 8, 'Načini ga šuplja, od dasaka: kako ti je pokazano na brdu, onako neka je i napravljen.\"');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 27, 9, '\"Napravi i dvorište Prebivališta. Na južnoj strani napravi zavjese od prepredenog lana, sto lakata u dužinu s te strane.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 27, 10, 'Njihovih dvadeset stupova neka stoji na dvadeset podnožja od tuča i neka imaju kopče i šipke od srebra.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 27, 11, 'Isto tako za sjevernu stranu načini plahte sto lakata duge. Njihovih dvadeset stupova i dvadeset podnožja od tuča, ali kopče i šipke neka su od srebra.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 27, 12, 'Širini dvorišta sa zapadne strane trebat će zavjese pedeset lakata duge, sa deset stupova i deset podnožja.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 27, 13, 'Širina dvorišta prema istočnoj strani neka bude pedeset lakata.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 27, 14, 'Nadalje, zavjese s jedne strane vrata neka su petnaest lakata duge, sa svoja tri stupa i njihova tri podnožja.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 27, 15, 'A s druge strane neka su zavjese opet petnaest lakata, sa svoja tri stupa i njihova tri podnožja.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 27, 16, 'Za dvorišni ulaz: vezen zastor od dvadeset lakata, od ljubičastog, crvenog i tamnocrvenog prediva i prepredenog lana; i sa svoja četiri stupa i njihova četiri podnožja.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 27, 17, 'Svi stupovi naokolo dvorišta neka su povezani srebrnim šipkama. Neka su im kopče od srebra, a podnožja od tuča.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 27, 18, 'Neka je dvorište u duljinu sto lakata, u širinu pedeset, a u visinu pet lakata. Neka su mu plahte od prepredenog lana, podnožja od tuča.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 27, 19, 'Sve potrepštine u Prebivalištu za opću upotrebu i svi njegovi kočići, a tako i kočići u dvorištu, neka su od tuča.\"');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 27, 20, '\"Nadalje, naredi Izraelcima da ti za svjetlo donose čistoga ulja od istupanih maslina, tako da svjetlo neprestano gori.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 27, 21, 'Aron i njegovi sinovi neka ga postavljaju u Šator sastanka izvan zavjese što zaklanja Svjedočanstvo da gori pred Jahvom od večeri do jutra. Neka je to neopoziva naredba za izraelske naraštaje.\"');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 28, 1, '\"A onda dovedi k sebi između Izraelaca svoga brata Arona zajedno s njegovim sinovima: Nadabom, Abihuom, Eleazarom i Itamarom da mi služe kao svećenici.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 28, 2, 'Napravi svome bratu Aronu sveto ruho na čast i ukras.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 28, 3, 'Obrati se svim vještacima koje sam obdario mudrošću neka naprave haljine Aronu da bi se posvetio i vršio svećeničku službu u moju čast.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 28, 4, 'Neka ovu odjeću naprave: naprsnik, oplećak, ogrtač, košulju resama obrubljenu, mitru i pas; neka naprave svetu odjeću za tvoga brata Arona i njegove sinove da mi služe kao svećenici.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 28, 5, 'Stoga neka oni primaju zlato, ljubičasto, crveno i tamnocrveno predivo i prepredeni lan.\"');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 28, 6, '\"Oplećak neka naprave od zlata, od ljubičastog, crvenog i tamnocrvenog prediva i od prepredenog lana - vješto izrađen.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 28, 7, 'Neka na njemu budu dvije poramenice, pričvršćene za njegove krajeve.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 28, 8, 'Tkanica što bude na njemu neka je napravljena kao i on: od zlata, od ljubičastog, crvenog i tamnocrvenog prediva i od prepredenog lana, a neka s njim sačinjava jedan komad.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 28, 9, 'Zatim uzmi dva draga kamena oniksa i u njih ureži imena Izraelovih sinova:');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 28, 10, 'šest njihovih imena na jednome dragom kamenu, a preostalih šest imena na drugome dragom kamenu, prema njihovu rođenju.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 28, 11, 'Kao što rezbar dragulja urezuje pečate na prstene, tako ti ureži imena Izraelovih sinova. Oko njih navezi zlatan obrub,');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 28, 12, 'pa pričvrsti oba draga kamena za poramenice oplećka da budu spomen-dragulji na Izraelove sinove. Tako neka Aron nosi njihova imena o svoja dva ramena pred Jahvom da ih se sjeća.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 28, 13, 'Načini zlatne okvire');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 28, 14, 'i dva lančića od čistoga zlata. Načini ih kao zasukane uzice i onda zasukane lančiće pričvrsti za okvire.\"');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 28, 15, '\"Naprsnik za presuđivanje izradi umjetnički; izvedi to kao i posao na oplećku: od zlata, od ljubičastog, crvenog i tamnocrvenog prediva i od prepredenog lana.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 28, 16, 'Neka bude četvorinast i dvostruk; jedan pedalj neka mu je duljina, a pedalj širina.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 28, 17, 'Na njemu poredaj četiri reda dragulja. U prvome redu neka bude: rubin, topaz i alem;');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 28, 18, 'u drugome redu: smaragd, safir i ametist;');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 28, 19, 'u trećem redu: hijacint, ahat i ledac;');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 28, 20, 'a u četvrtom redu: krizolit, oniks i jaspis. Neka budu ukovani u zlatne okvire.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 28, 21, 'Tih dragulja neka bude dvanaest, koliko i imena Izraelovih sinova. Neka budu urezani kao i pečati na prstenju, svaki s imenom jednoga od dvanaest plemena.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 28, 22, 'Napravi za naprsnik lančiće od čistoga zlata, zasukane kao uzice.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 28, 23, 'Zatim napravi za naprsnik dva kolutića od zlata i pričvrsti ih na dva gornja ugla naprsnika.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 28, 24, 'Onda priveži dvije zlatne uzice za ta dva kolutića koja budu pričvršćena za uglove naprsnika.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 28, 25, 'Druga dva kraja uzica priveži za dva okvira. Sad ih tako pričvrsti za poramenice oplećka sprijeda.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 28, 26, 'Napravi dva kolutića od zlata pa ih pričvrsti za dva donja ugla naprsnika, uz rub iznutra koji je okrenut prema oplećku.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 28, 27, 'Napravi još dva kolutića od zlata i pričvrsti ih za donji, prednji kraj poramenice oplećka, uz njegov šav povrh tkanice oplećka.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 28, 28, 'Neka se naprsnik sveže za svoje kolutiće s kolutićima oplećka vrpcom od modroga grimiza, tako da naprsnik stoji iznad tkanice i da se ne može odvajati od oplećka.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 28, 29, 'Neka tako Aron, kada god ulazi u Svetište, na svome srcu nosi imena sinova Izraelovih na naprsniku za presuđivanje da ih uvijek doziva u sjećanje pred Jahvom.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 28, 30, 'U naprsnik za presuđivanje neka se stave i \'Urim\' i \'Tumim\' da i oni budu na Aronovu srcu kad bude dolazio pred Jahvu. Tako neka Aron uvijek na svom srcu pred Jahvom nosi presudu sinova Izraelovih.\"');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 28, 31, '\"Ogrtač za oplećak sav napravi od ljubičastog prediva.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 28, 32, 'Prorez za glavu na njemu neka bude na sredini. Rub naokolo proreza neka bude opšiven kao ovratnik na oklopu, tako da se ogrtač ne podere.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 28, 33, 'Na njegovu rubu sve naokolo načini šipke od ljubičastog, crvenog i tamnocrvenog prediva, a između njih zvonca od zlata naokolo;');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 28, 34, 'zlatno zvonce pa šipak, zlatno zvonce pa šipak naokolo ogrtača uz rub.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 28, 35, 'Neka budu na Aronu dok vrši službu, da se čuje kad ulazi u Svetište pred Jahvu i kad izlazi; tako neće umrijeti.\"');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 28, 36, '\"Napravi potom jednu ploču od čistoga zlata i na njoj ureži, kao što se urezuje na pečatnom prstenu: \'Jahvi posvećen\'.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 28, 37, 'Za mitru je priveži modrom vrpcom da stoji s pročelja mitre.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 28, 38, 'Neka stoji na Aronovu čelu. Tako neka Aron na se preuzme nedostatke koji bi mogli okaljati sve svete prinose što ih Izraelci posvećuju. Neka uvijek stoji na njegovu čelu da za njih stječe blagonaklonost Jahvinu.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 28, 39, 'Košulju s resama napravi od lana, od lana napravi i mitru, a pas vezom izvezi.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 28, 40, 'I za Aronove sinove napravi haljine, pasove i turbane, njima na čast i ukras.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 28, 41, 'U njih odjeni svoga brata Arona i njegove sinove; onda ih pomaži, ispuni im ruke vlašću i posveti ih da mi služe kao svećenici.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 28, 42, 'Napravi za njih gaćice od lana da im pokriju golo tijelo. Neka sežu od bedara do stegna.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 28, 43, 'Neka ih nosi Aron i njegovi sinovi kad ulaze u Šator sastanka ili kad se primiču žrtveniku za službu u Svetištu da ne navuku na se krivnju i umru. To neka bude vječna naredba za nj i za njegovo potomstvo poslije njega.\"');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 29, 1, '\"Ovo je obred koji ćeš obaviti na njima da ih posvetiš za moje svećenike: Uzmi jednog junca i dva ovna bez mane;');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 29, 2, 'onda beskvasnoga kruha, beskvasnih kolača zamiješenih u ulju i beskvasnih prevrta uljem namazanih. Napravi ih od bijeloga pšeničnog brašna.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 29, 3, 'Naslaži ih u košaricu i u košarici prinesi ih s juncem i oba ovna.\"');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 29, 4, '\"Dovedi Arona i njegove sinove k ulazu u Šator sastanka i operi ih u vodi.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 29, 5, 'Zatim uzmi odijelo i obuci Arona u košulju; stavi na nj ogrtač oplećka, oplećak i naprsnik i opaši ga tkanicom oplećka.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 29, 6, 'Ustakni mu mitru na glavu; na mitru stavi sveti vijenac.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 29, 7, 'Uzmi zatim ulja za pomazanje; izlij na njegovu glavu i pomaži ga.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 29, 8, 'Onda dovedi njegove sinove; obuci ih u košulje;');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 29, 9, 'opaši ih u pasove i obvij im turbane. Svećeništvo neka im pripada vječnom uredbom. Tako posveti Arona i njegove sinove!\"');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 29, 10, '\"Dovedi zatim junca pred Šator sastanka, pa neka Aron i njegovi sinovi stave ruke juncu na glavu.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 29, 11, 'Onda pred Jahvom, na ulazu u Šator sastanka, junca zakolji.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 29, 12, 'Uzmi junčeve krvi i svojim je prstom stavi na rogove žrtvenika. Ostatak krvi izlij podno žrtvenika.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 29, 13, 'Uzmi sav loj oko droba, privjesak na jetri i oba bubrega s lojem oko njih, pa spali na žrtveniku.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 29, 14, 'Meso od junca, njegovu kožu i njegovu nečist spali na vatri izvan taborišta. To je žrtva okajnica.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 29, 15, 'Poslije toga uzmi jednoga ovna, pa neka Aron i njegovi sinovi stave na njegovu glavu svoje ruke.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 29, 16, 'Onda ovna zakolji, uhvati mu krvi i zapljusni njome žrtvenik sa svih strana.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 29, 17, 'Isijeci zatim ovna u komade, operi mu drobinu i noge i položi ih na njegove ostale dijelove i glavu.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 29, 18, 'I onda cijeloga ovna spali na žrtveniku. Žrtva je to paljenica u čast Jahvi, miris ugodan, žrtva ognjena.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 29, 19, 'Uzmi onda drugoga ovna, pa neka Aron i njegovi sinovi stave svoje ruke ovnu na glavu.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 29, 20, 'Sad ovna zakolji; uzmi mu krvi i njome namaži resicu desnoga Aronova uha, resicu desnog uha njegovim sinovima, palac na njihovoj desnoj ruci pa palac na njihovoj desnoj nozi. Ostatkom krvi zapljusni žrtvenik naokolo.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 29, 21, 'Uzmi onda krvi što je ostala na žrtveniku i ulja za pomazanje i poškropi Arona i njegovo odijelo, njegove sinove i njihova odijela. Tako će biti posvećen on i njegovo odijelo, njegovi sinovi i odijela njegovih sinova.\"');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 29, 22, '\"Poslije toga uzmi s ovna loj, pretili rep, loj oko droba, privjesak s jetre, oba bubrega i loj oko njih; desno pleće - jer je to ovan prinesen za svećeničko posvećenje -');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 29, 23, 'zatim jedan okrugli kruh, jedan kolač na ulju i jednu prevrtu iz košarice beskvasnoga kruha što je pred Jahvom.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 29, 24, 'Sve to stavi na ruke Arona i njegovih sinova i prinesi žrtvu prikaznicu pred Jahvom.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 29, 25, 'Uzmi ih onda s njihovih ruku i spali na žrtveniku, povrh žrtve paljenice, da bude Jahvi na ugodan miris. To je paljena žrtva u čast Jahvi.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 29, 26, 'Zatim uzmi grudi ovna prinesena za Aronovo posvećenje i prinesi ih kao žrtvu prikaznicu pred Jahvom. Neka to bude tvoj dio.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 29, 27, 'Posveti grudi što su bile prinesene kao žrtva prikaznica i pleće što je bilo prineseno kao žrtva podizanica od ovna prinesena za posvećenje Arona i njegovih sinova.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 29, 28, 'Neka to bude pristojba Aronu i njegovim potomcima od Izraelaca za sva vremena. TÓa to je ujam koji će Izraelci davati od svojih pričesnica - ujam koji Jahvi pripada.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 29, 29, 'Aronova posvećena odijela neka pripadnu njegovim sinovima poslije njega da u njima budu pomazani i posvećeni.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 29, 30, 'Sin koji postane svećenikom mjesto njega, kad uđe u Šator sastanka da vrši službu u Svetištu, neka ih nosi sedam dana.\"');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 29, 31, '\"Uzmi onda ovna za posvećenje i skuhaj njegovo meso na posvećenome mjestu.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 29, 32, 'Aron i njegovi sinovi neka blaguju meso od toga ovna i kruh iz košarice na ulazu u Šator sastanka.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 29, 33, 'Neka jedu od onoga što je poslužilo za njihovo očišćenje, da im se ruke ispune vlašću i da budu posvećeni. Nijedan svjetovnjak neka ne jede od toga jer je posvećeno.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 29, 34, 'Ako bi ostalo što mesa od svećeničkog posvećenja ili što od onoga kruha do ujutro, spali na vatri. Ne smije se pojesti jer je posvećeno.\"');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 29, 35, '\"Točno tako učini Aronu i njegovim sinovima kako sam ti naredio. Posvećuj ih sedam dana.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 29, 36, 'Svakoga dana prinesi jednoga junca kao žrtvu okajnicu - za pomirenje. I prinesi žrtvu okajnicu za pomirenje oltara, zatim ga pomaži da bude posvećen.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 29, 37, 'Sedam dana prinosi žrtvu pomirnicu za žrtvenik i posvećuj ga. Tako će žrtvenik postati presvet, i sve što se žrtvenika dotakne bit će posvećeno.\"');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 29, 38, '\"A ovo treba da prinosiš na žrtveniku: dva janjca godinu dana stara, svaki dan bez prijekida.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 29, 39, 'Jedno janje žrtvuj ujutro, a drugo uvečer.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 29, 40, 'Prinesi s prvim janjetom jednu desetinu efe bijeloga brašna zamiješena u četvrtini hina istupanog ulja i žrtvu ljevanicu od četvrtine hina vina.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 29, 41, 'Drugo janje prinesi u suton. S njim prinesi žrtvu prinosnicu s njezinom žrtvom ljevanicom kao i izjutra - na ugodan miris, žrtvu u čast Jahvi paljenu.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 29, 42, 'Neka to bude trajna žrtva paljenica od koljena do koljena - na ulazu u Šator sastanka, pred Jahvom. Tu ću se ja s tobom sastajati da ti govorim.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 29, 43, 'I s Izraelcima ću se tu sastajati, i moja će ih slava posvećivati.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 29, 44, 'Ja ću posvetiti Šator sastanka i žrtvenik; posvetit ću Arona i njegove sinove da mi služe kao svećenici.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 29, 45, 'Ja ću prebivati među Izraelcima i biti njihov Bog.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 29, 46, 'Upoznat će oni tada da sam to ja, Jahve, Bog njihov koji ih je izbavio iz zemlje egipatske da prebivam među njima - ja, Jahve, Bog njihov.\"');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 30, 1, '\"Napravi i žrtvenik za paljenje tamjana; napravi ga od bagremova drva.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 30, 2, 'Neka bude lakat dug, lakat širok, u pravokut, i dva lakta visok. Neka mu roščići budu od jednoga komada s njim.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 30, 3, 'Obloži mu u čisto zlato: njegovu gornju plohu, njegove strane naokolo i njegove roščiće. Načini mu zlatan završni pojas naokolo.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 30, 4, 'Načini mu dva zlatna koluta. Pričvrsti mu ih s dviju suprotnih strana ispod završnog pojasa. Kroz njih će se provlačiti motke za nošenje.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 30, 5, 'Motke načini od bagremova drva i zlatom ih obloži.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 30, 6, 'Postavi žrtvenik pred zavjesu što zastire Kovčeg Svjedočanstva - nasuprot Pomirilištu nad Svjedočanstvom - gdje ću se ja s tobom sastajati.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 30, 7, 'Neka na njemu Aron pali miomirisni tamjan svako jutro kad priprema svjetla;');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 30, 8, 'neka ga Aron opet pali u suton kad svjetla zapaljuje, da to bude svagdašnje kadiono prinošenje pred Jahvom u sve vaše naraštaje.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 30, 9, 'Ne prinosi na njemu ni neposvećenoga tamjana, ni paljenice, ni prinosnice, ni ljevanice!');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 30, 10, 'Jednom u godini neka Aron obavi obred pomirenja na njegovim roščićima. Krvlju žrtve koja se prinosi za grijeh, jednom na godinu, neka obavi obred pomirenja za žrtvenik. Tako činite u sve naraštaje. Jer oltar je presveta svetinja Jahvina.\"');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 30, 11, 'Nadalje Jahve reče Mojsiju:');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 30, 12, '\"Kad budeš pravio popis Izraelaca prilikom novačenja, neka svatko da Jahvi otkupninu za se kad se upiše, da ih kakvo zlo ne snađe zbog novačenja.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 30, 13, 'Tko god potpada pod novačenje, ovoliko neka dadne: pola šekela - prema hramskom šekelu, gdje je dvadeset gera u šekelu. To pola šekela neka bude kao prinos Jahvi.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 30, 14, 'Tko god potpada pod novačenje, od dvadeset godina starosti pa naviše, neka dadne prinos Jahvi.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 30, 15, 'Bogataš neka ne plaća više niti siromah manje od pola šekela kad daju prinos Jahvi kao otkup za se.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 30, 16, 'Uzimaj otkupni novac od Izraelaca i određuj ga za potrebe Šatora sastanka. Neka to bude Jahvi na spomen da se sjeća Izraelaca i da im bude milostiv.\"');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 30, 17, 'Reče Jahve Mojsiju:');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 30, 18, '\"Napravi umivaonik od tuča i podnožje od tuča za umivanje. Postavi ga između Šatora sastanka i žrtvenika. Nalij u nj vode');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 30, 19, 'pa neka Aron i njegovi sinovi peru svoje ruke i noge vodom iz njega.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 30, 20, 'Kad moradnu ulaziti u Šator sastanka, ili kad se moradnu primicati žrtveniku za službu da spaljuju žrtve u čast Jahvi paljene, neka se vodom operu da ne poginu.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 30, 21, 'Neka operu ruke svoje i noge svoje da izbjegnu smrti: to je trajna naredba Aronu i njegovim potomcima u sve naraštaje.\"');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 30, 22, 'Još reče Jahve Mojsiju:');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 30, 23, '\"Nabavi najboljih mirodija: pet stotina šekela smirne samotoka, pola te težine - dvjesta pedeset - mirisavog cimeta, dvjesta pedeset mirisave trstike,');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 30, 24, 'pet stotina - prema hramskom šekelu - lovorike i jedan hin maslinova ulja.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 30, 25, 'Od toga napravi posvećeno ulje za pomazanje; da bude smjesa kao da ju je pravio pomastar. Neka to bude posvećeno ulje za pomazanje.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 30, 26, 'Time onda pomaži: Šator sastanka i Kovčeg Svjedočanstva;');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 30, 27, 'stol i sav njegov pribor; svijećnjak i sav njegov pribor; žrtvenik kadioni;');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 30, 28, 'žrtvenik za žrtve paljenice i sav njegov pribor; umivaonik i njegov stalak:');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 30, 29, 'posveti ih, i oni će tako postati posvećeni; i što god ih se dotakne, posvećeno će postati.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 30, 30, 'Pomaži Arona i njegove sinove i posveti ih meni za svećenike.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 30, 31, 'Onda kaži Izraelcima ovako: \'Ovo je moje posvećeno ulje za pomazanje od koljena do koljena.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 30, 32, 'Ne smije se polijevati po tijelu običnoga čovjeka; ne smijete praviti drugoga ovakva sastava! To je posvećeno i neka vam bude sveto!');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 30, 33, 'Tko god takvo napravi, ili tko ga stavi na kojeg svjetovnjaka, neka se odstrani od svog naroda!\'\"');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 30, 34, 'Jahve još reče Mojsiju: \"Nabavi mirodija: natafe, šeheleta i helebene. Od ovih mirodija i čistoga tamjana,');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 30, 35, 'sve u jednakim dijelovima, napravi tamjan za kađenje, smjesu mirodija kakvu pravi pomastar, opranu, čistu, svetu.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 30, 36, 'Od toga nešto smrvi u prah i jedan dio stavi pred Svjedočanstvo, u Šator sastanka, gdje ću se ja s tobom sastajati. Držite ovu mirodiju presvetom!');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 30, 37, 'A miomiris koji napraviš prema ovome sastavu za svoju upotrebu ne smijete praviti. To drži za svetinju Jahvi!');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 30, 38, 'Tko sebi napravi što takvo da mu miriše, neka se iskorijeni iz svoga naroda.\"');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 31, 1, 'Jahve reče Mojsiju:');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 31, 2, '\"Pozvao sam, gledaj, po imenu Besalela, sina Urijeva, od koljena Hurova iz plemena Judina.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 31, 3, 'Napunio sam ga duhom Božjim koji mu je dao umješnost, razumijevanje i sposobnost za svakovrsne poslove:');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 31, 4, 'da zamišlja nacrte za radove od zlata, srebra i tuča;');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 31, 5, 'za rezanje dragulja, za umetanje; za rezbarije u drvu i poslove svakakve.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 31, 6, 'Dodao sam još Oholiaba, sina Ahisamakova iz Danova plemena; vještinom sam obdario sve sposobne ljude da mognu napraviti sve što sam ti naredio:');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 31, 7, 'Šator sastanka, Kovčeg Svjedočanstva, povrh njega Pomirilište i sav namještaj Šatora;');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 31, 8, 'stol i sav njegov pribor, čisti svijećnjak sa svim njegovim priborom;');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 31, 9, 'kadioni žrtvenik, žrtvenik za žrtve paljenice i njegov pribor, onda umivaonik i njegovo podnožje;');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 31, 10, 'odijela za službu, posvećena odijela za svećenika Arona i odijela za njegove sinove, za njihovu svećeničku službu;');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 31, 11, 'pa ulje za pomazanje i miomirisni tamjan za Svetište. Sve neka načine kako sam ti naredio.\"');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 31, 12, 'Jahve opet reče Mojsiju:');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 31, 13, '\"Reci Izraelcima: Subote moje morate održavati, jer subota je znak između mene i vas od naraštaja do naraštaja, da budete svjesni da vas ja, Jahve, posvećujem.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 31, 14, 'Držite, dakle, subotu, jer je ona za vas sveta. Tko je oskvrne neka se pogubi; tko bude u njoj radio ikakav posao neka se odstrani iz svoga naroda.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 31, 15, 'Šest dana neka se vrše poslovi, ali sedmi dan neka bude dan posvemašnjeg odmora, Jahvi posvećen. Tko bi u dan subotni obavljao kakav posao neka se pogubi.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 31, 16, 'Stoga neka Izraelci drže subotu - svetkujući je od naraštaja do naraštaja - kao vječni savez.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 31, 17, 'Neka je ona znak, zauvijek, između mene i Izraelaca. TÓa Jahve je za šest dana sazdao nebo i zemlju, a sedmoga je dana prestao raditi i odahnuo.\"');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 31, 18, 'Kad Jahve svrši svoj razgovor s Mojsijem na Sinajskom brdu, dade mu dvije ploče Svjedočanstva, ploče kamene, ispisane prstom Božjim.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 32, 1, 'A narod, videći gdje Mojsije dugo ne silazi s brda, okupi se oko Arona pa mu rekne: \"Ustaj! Napravi nam boga, pa neka on pred nama ide! Ne znamo što se dogodi s tim čovjekom Mojsijem koji nas izvede iz zemlje egipatske.\"');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 32, 2, '\"Poskidajte zlatne naušnice što vise o ušima vaših žena, vaših sinova i vaših kćeri\", odgovori im Aron, \"pa ih meni donesite.\"');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 32, 3, 'Sav svijet skine zlatne naušnice što ih je o ušima imao i donese Aronu.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 32, 4, 'Primivši zlato iz njihovih ruku, rastopi kovinu u kalupu i načini saliveno tele. A oni poviču: \"Ovo je tvoj bog, Izraele, koji te izveo iz zemlje egipatske.\"');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 32, 5, 'Vidjevši to Aron, sagradi pred njim žrtvenik a onda najavi: \"Sutra neka se priredi svečanost u čast Jahvi!\"');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 32, 6, 'Sutradan rano ustanu i prinesu žrtve paljenice i donesu žrtve pričesnice. Onda svijet posjeda da jede i pije. Poslije toga ustade da se zabavlja.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 32, 7, '\"Požuri se dolje!\" - progovori Jahve Mojsiju. \"Narod tvoj, koji si izveo iz zemlje egipatske, pošao je naopako.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 32, 8, 'Brzo su zašli s puta koji sam im odredio. Napravili su sebi tele od rastopljene kovine, preda nj pali ničice i žrtve mu prinijeli uz poklike: \'Ovo je tvoj bog, Izraele, koji te izveo iz zemlje egipatske!\'');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 32, 9, 'Dobro vidim\", reče dalje Jahve Mojsiju, \"da je ovaj narod tvrde šije.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 32, 10, 'Pusti sada neka se moj gnjev na njih raspali da ih istrijebim. Onda ću od tebe razviti velik narod.\"');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 32, 11, 'Mojsije pak zapomagao pred Jahvom, Bogom svojim, i govorio: \"O Jahve! Čemu da gnjevom plamtiš na svoj narod koji si izbavio iz zemlje egipatske silom velikom i rukom jakom!');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 32, 12, 'Zašto bi Egipćani morali reći: \'U zloj ih je namjeri i odveo, tako da ih smakne u brdinama i izbriše s lica zemlje!\' Smiri svoj gnjev i ljutinu; odustani od zla svome narodu!');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 32, 13, 'Sjeti se Abrahama, Izaka i Izraela, slugu svojih, kojima si se samim sobom zakleo i obećao im: \'Razmnožit ću vaše potomstvo kao zvijezde na nebu i svu zemlju ovu što sam obećao dat ću vašem potomstvu i ona će zavazda biti njihova baština.\'\"');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 32, 14, 'I Jahve odustane da na svoj narod svali nesreću kojom mu bijaše zaprijetio.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 32, 15, 'Mojsije se okrene i siđe s brda. U rukama su mu bile dvije ploče Svjedočanstva, ploče ispisane na objema plohama; ispisane i s jedne i s druge strane.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 32, 16, 'Ploče su bile djelo Božje; pismo je bilo pismo Božje u pločama urezano.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 32, 17, 'A Jošua ču viku naroda koji je bučio pa reče Mojsiju: \"Bojna vika u taboru!\"');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 32, 18, 'Mojsije mu odgovori: \"Niti viču pobjednici, niti tuže pobijeđeni: tu ja samo pjesmu čujem.\"');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 32, 19, 'Čim se približi taboru te opazi tele i kako igraju, razgnjevi se Mojsije. Baci iz ruku ploče i razbije ih na podnožju brda.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 32, 20, 'Pograbi tele koje bijahu napravili, spali ga ognjem i u prah satre. Onda prah razbaca po vodi i natjera Izraelce da je piju.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 32, 21, '\"Što ti je ovaj puk učinio\", reče Mojsije Aronu, \"da si tako velik grijeh na nj svalio?\"');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 32, 22, '\"Neka se moj gospodar srdžbom ne raspaljuje\", odgovori Aron. \"Sam dobro znaš kako je ovaj narod na zlo sklon.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 32, 23, 'Rekoše mi: \'Napravi nam boga pa neka pred nama ide! Ne znamo što se dogodi s tim čovjekom Mojsijem koji nas izbavi iz zemlje egipatske.\'');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 32, 24, 'Na to im ja rekoh: \'Tko ima zlata, neka ga skine!\' Tako mi ga dadoše, a ja ga bacih u vatru te izađe ovo tele.\"');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 32, 25, 'Kad je Mojsije vidio kako je narod postao razuzdan - tÓa Aron ih je pustio da padnu u idolopoklonstvo među svojim neprijateljima -');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 32, 26, 'stade na taborskim vratima i povika: \"Tko je za Jahvu, k meni!\" Svi se sinovi Levijevi okupe oko njega.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 32, 27, 'On im reče: \"Ovako govori Jahve, Bog Izraela: \'Neka svatko pripaše mač o bedro i pođe taborom od vrata do vrata pa neka ubije tko svoga brata, tko svoga prijatelja, tko svoga susjeda.\'\"');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 32, 28, 'Sinovi Levijevi izvršiše Mojsijev nalog, i toga dana pade naroda oko tri tisuće ljudi.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 32, 29, '\"Danas ste se posvetili Jahvi za službu\", reče Mojsije, \"tko uz cijenu svoga sina, tko uz cijenu svoga brata, tako da vam danas daje blagoslov.\"');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 32, 30, 'Sutradan reče Mojsije narodu: \"Težak ste grijeh počinili. Ipak ću se Jahvi popeti. Možda za vaš grijeh oproštenje pribavim.\"');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 32, 31, 'Mojsije se vrati Jahvi pa reče: \"Jao! Narod onaj težak je grijeh počinio napravivši sebi boga od zlata.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 32, 32, 'Ipak im taj grijeh oprosti... Ako nećeš, onda i mene izbriši iz svoje knjige koju si napisao.\"');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 32, 33, 'Nato Jahve odgovori Mojsiju: \"Onoga koji je protiv mene sagriješio izbrisat ću iz svoje knjige.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 32, 34, 'Nego, idi sad! Povedi narod kamo sam ti rekao. Anđeo će moj pred tobom ići. Ali u dan kad ih pohodim, zbog njihova ću ih grijeha kazniti.\"');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 32, 35, 'Udari Jahve po narodu pomorom zbog teleta što im ga Aron načini.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 33, 1, 'Jahve reče Mojsiju: \"Idi! Putuj odavde, ti i narod koji si izveo iz zemlje egipatske, u zemlju za koju sam se zakleo Abrahamu, Izaku i Jakovu da ću je dati njihovim potomcima.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 33, 2, 'Pred tobom ću poslati anđela; istjerat ću Kanaance, Amorejce, Hetite, Perižane, Hivijce i Jebusejce.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 33, 3, 'Idite u zemlju kojom teče mlijeko i med. Ja s vama neću poći - jer ste narod tvrde šije - da vas putem ne istrijebim.\"');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 33, 4, 'Kad narod ču ove oštre riječi, poče tugovati. I nitko više ne stavi na se svoga nakita.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 33, 5, 'Jer reče Jahve Mojsiju: \"Kaži Izraelcima: \'Vi ste narod tvrde šije. Kad bih ja s vama išao samo čas, uništio bih vas. Stoga skinite svoj nakit, a ja ću vidjeti što ću s vama učiniti.\'\"');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 33, 6, 'Tako su od brda Horeba Izraelci bili bez nakita.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 33, 7, 'Mojsije uze Šator i razape ga izvan tabora, daleko od tabora. I nazva ga Šator sastanka. Tko bi se god htio obratiti Jahvi, pošao bi k Šatoru sastanka, koji se nalazio izvan tabora.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 33, 8, 'Kad bi god Mojsije pošao u Šator, sav bi se narod digao; svatko bi stajao kod ulaza u svoj šator i gledao za Mojsijem dok ne bi ušao u Šator.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 33, 9, 'A kad bi Mojsije ušao u Šator, stup bi se oblaka spustio i ostajao na ulazu u Šator dok je Jahve s Mojsijem razgovarao.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 33, 10, 'Videći kako stup oblaka stoji na ulazu Šatora, sav bi se narod tada dizao i svatko bi se duboko klanjao na vratima svoga šatora.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 33, 11, 'Tako bi Jahve razgovarao s Mojsijem licem u lice, kao što čovjek govori s prijateljem. Mojsije bi se poslije vratio u tabor, ali se njegov pomoćnik Jošua, sin Nunov, mlađarac, iz Šatora ne bi micao.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 33, 12, 'Mojsije oslovi Jahvu: \"Vidi, ti si meni rekao: \'Povedi ovaj narod\', ali mi nisi objavio koga ćeš sa mnom poslati. Još si mi rekao: \'Znam te po imenu, i ti uživaš moju blagonaklonost.\'');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 33, 13, 'Stoga, ako uživam tvoju blagonaklonost, objavi mi svoje putove da te shvatim i da dalje uživam tvoju blagonaklonost. Promisli također da je ova svjetina tvoj narod.\"');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 33, 14, '\"Ja ću osobno s tobom poći\", odgovori Jahve, \"i počinak ti priuštiti.\"');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 33, 15, '\"Ako ti ne pođeš\", nadoda Mojsije, \"odavde nas i ne izvodi.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 33, 16, 'TÓa kako će se znati da uživamo tvoju naklonost, ja i tvoj narod? Po tome što ideš s nama. Time ćemo se samo razlikovati ja i tvoj narod među svim narodima koji su na licu zemlje.\"');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 33, 17, '\"I ovo što si zatražio, učinit ću\", odgovori Jahve Mojsiju. \"TÓa ti uživaš moju blagonaklonost jer te po imenu poznajem.\"');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 33, 18, '\"Pokaži mi svoju slavu\", zamoli Mojsije.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 33, 19, '\"Dopustit ću da ispred tebe prođe sav moj sjaj\", odgovori, \"i pred tobom ću izustiti svoje ime Jahve. Bit ću milostiv kome hoću da milostiv budem; smilovat ću se komu hoću da se smilujem.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 33, 20, 'A ti\", doda, \"moga lica ne možeš vidjeti, jer ne može čovjek mene vidjeti i na životu ostati.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 33, 21, 'Evo mjesta ovdje uza me\", nastavi Jahve. \"Stani na pećinu!');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 33, 22, 'Dok moja slava bude prolazila, stavit ću te u pukotinu pećine i svojom te rukom zakloniti dok ne prođem.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 33, 23, 'Onda ću ja svoju ruku maknuti, pa ćeš me s leđa vidjeti. Ali se lice moje ne može vidjeti.\"');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 34, 1, 'Reče Jahve Mojsiju: \"Okleši dvije kamene ploče kao i prijašnje pa ću ja na ploče napisati riječi koje su bile na prvim pločama što si ih razbio.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 34, 2, 'Budi gotov do jutra. Onda, ujutro, popni se na brdo Sinaj i ondje ćeš, navrh brda, stupiti preda me.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 34, 3, 'Nitko drugi neka se s tobom ne penje; neka se nitko nigdje na brdu ne pokaže. Neka ni ovce ni goveda ne pasu podno brda.\"');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 34, 4, 'Mojsije okleše dvije kamene ploče kao i prijašnje; rano jutrom ustane i popne se na Sinajsko brdo, uzevši u ruke dvije kamene ploče, kako mu je Jahve naredio.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 34, 5, 'Jahve se spusti u liku oblaka, a on stade preda nj i zazva Ime: \"Jahve!\"');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 34, 6, 'Jahve prođe ispred njega te se javi: \"Jahve! Jahve! Bog milosrdan i milostiv, spor na srdžbu, bogat ljubavlju i vjernošću,');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 34, 7, 'iskazuje milost tisućama, podnosi opačinu, grijeh i prijestup, ali krivca nekažnjena ne ostavlja nego kažnjava opačinu otaca na djeci - čak na unučadi do trećega i četvrtog koljena.\"');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 34, 8, 'Mojsije smjesta pade na zemlju i pokloni se.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 34, 9, 'Onda reče: \"Gospodine moj! Ako sam stekao blagonaklonost u tvojim očima, onda, o Gospodine, pođi s nama! Premda je narod tvrde šije, oprosti naše grijehe i naše opačine i primi nas za svoju baštinu!\"');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 34, 10, '\"Dobro\", odgovori, \"sklapam Savez. Pred cijelim tvojim pukom činit ću čudesa kakva se nisu događala ni u kojoj zemlji, ni u kojem narodu. Sav narod koji te okružuje vidjet će što može Jahve, jer ono što ću s tobom učiniti bit će strašno.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 34, 11, 'Vrši, dakle, što ti danas nalažem! Gle, protjerat će ispred tebe Amorejce, Kanaance, Hetite, Perižane, Hivijce i Jebusejce.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 34, 12, 'Čuvaj se da ne praviš saveza sa stanovnicima zemlje u koju ideš; da ne budu zamkom u tvojoj sredini.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 34, 13, 'Nego porušite njihove žrtvenike, oborite njihove stupove, počupajte im ašere!');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 34, 14, 'Jer ne smiješ se klanjati drugome bogu. TÓa Jahve - ime mu je Ljubomorni - Bog je ljubomoran.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 34, 15, 'Ne pravi saveza sa stanovnicima one zemlje da te oni, kad se odaju bludnosti sa svojim bogovima i žrtve im budu prinosili, ne bi pozivali, a ti pristao da jedeš od prinesene žrtve;');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 34, 16, 'da ne bi uzimao njihove djevojke za žene svojim sinovima, da one - odajući se bludništvu sa svojim bogovima - ne bi za sobom povele i tvoje sinove.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 34, 17, 'Ne pravi sebi livenih bogova!');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 34, 18, 'Drži Blagdan beskvasnoga kruha - jedući beskvasni kruh sedam dana, kako sam ti naredio - u određeno vrijeme u mjesecu Abibu, jer si u mjesecu Abibu izišao iz Egipta.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 34, 19, 'Svako prvorođenče materinjega krila meni pripada: svako muško, svaki prvenac tvoga i sitnoga i krupnoga blaga.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 34, 20, 'Prvenca od magarice otkupi jednim grlom sitne stoke. Ako ga ne otkupiš, moraš mu šijom zavrnuti. A sve prvorođence od svojih sinova otkupljuj. Neka nitko preda me ne stupa praznih ruku!');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 34, 21, 'Šest dana radi, a sedmoga od poslova odustani, sve ako je u doba oranja ili u vrijeme žetve.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 34, 22, 'Svetkuj Blagdan sedmica - prvine pšenične žetve - i Blagdan berbe na prekretu godine.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 34, 23, 'Triput na godinu neka se svi muškarci pojave pred Gospodinom Jahvom, Bogom Izraelovim.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 34, 24, 'Jer ću protjerati narode ispred tebe i proširiti tvoje međe te nitko neće hlepiti za tvojom zemljom kad triput u godini budeš uzlazio da se pokažeš pred Jahvom, Bogom svojim.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 34, 25, 'Od žrtve koju mi namjenjuješ ne prinosi krvi ni s čim ukvasanim; niti ostavljaj žrtve prinesene na blagdan Pashe da prenoći do jutra.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 34, 26, 'U kuću Jahve, Boga svoga, donosi najbolje prvine plodova sa svoje zemlje. Ne kuhaj kozleta u mlijeku njegove majke.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 34, 27, 'Zapiši ove riječi\", reče Jahve Mojsiju, \"jer su one temelji na kojima sam s tobom i s Izraelom sklopio Savez.\"');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 34, 28, 'Mojsije ostade ondje s Jahvom četrdeset dana i četrdeset noći. Niti je kruha jeo niti je vode pio. Tada je na ploče ispisao riječi Saveza - Deset zapovijedi.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 34, 29, 'Napokon Mojsije siđe sa Sinajskog brda. Silazeći s brda, nosio je u rukama ploče Svjedočanstva. Nije ni znao da iz njegova lica, zbog razgovora s Jahvom, izbija svjetlost.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 34, 30, 'Kad su Aron i svi Izraelci vidjeli kako iz Mojsijeva lica izbija svjetlost, ne usudiše se k njemu pristupiti.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 34, 31, 'Onda ih Mojsije zovnu. Tada k njemu dođoše Aron i sve starješine zajednice. I Mojsije razgovaraše s njima.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 34, 32, 'Poslije k njemu dođoše i svi Izraelci, pa im on priopći sve što mu je naložio Jahve na Sinajskom brdu.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 34, 33, 'Kad je Mojsije završio razgovor s njima, prevuče preko svoga lica koprenu.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 34, 34, 'Kad bi god Mojsije ulazio pred Jahvu da s njim razgovara, koprenu bi skinuo dok opet ne bi izišao. Kad bi izlazio da Izraelcima kaže što mu je naređeno,');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 34, 35, 'Izraelci bi vidjeli kako iz Mojsijeva lica izbija svjetlost. Tada bi Mojsije opet prevukao koprenu preko lica dok ne uđe da s Jahvom govori.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 35, 1, 'Mojsije sazva svu zajednicu sinova Izraelovih pa im reče: \"Ovo vam je Jahve naložio da činite:');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 35, 2, 'Neka se posao obavlja šest dana. Sedmi dan neka vam bude sveti dan, dan potpunog počinka u čast Jahvi. Tko bi radio u taj dan neka se kazni smrću.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 35, 3, 'Na subotnji dan ni vatre ne ložite po svojim stanovima.\"');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 35, 4, 'Nadalje Mojsije reče svoj zajednici izraelskoj: \"Ovo je Jahve naredio:');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 35, 5, 'Među sobom pokupite prinos Jahvi! Tko god je plemenita srca neka Jahvi donese prinos: zlata, srebra i tuča;');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 35, 6, 'ljubičastog, crvenog i tamnocrvenog prediva i prepredenog lana;');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 35, 7, 'učinjenih ovnujskih koža, onda finih koža, bagremova drva,');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 35, 8, 'ulja za svjetlo, mirodija za ulje pomazanja i miomirisni tamjan;');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 35, 9, 'oniksa i drugoga dragog kamenja za umetanje u oplećak i naprsnik.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 35, 10, 'A svi koji su među vama vješti neka dođu praviti što je Jahve naredio:');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 35, 11, 'Prebivalište, njegov Šator i pokrov; njegove kuke i trenice, njegove priječnice i stupce; njegova podnožja;');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 35, 12, 'njegov Kovčeg i motke; Pomirilište pa zavjesu za zaklon;');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 35, 13, 'stol s njegovim motkama i sve njegove potrepštine; prinesene hljebove;');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 35, 14, 'svijećnjak za svjetlo, njegov pribor i njegove svijeće, onda ulje za svjetlo;');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 35, 15, 'kadioni žrtvenik i njegove motke; ulje za pomazanje i miomirisni tamjan; zastorak na ulazu u Prebivalište;');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 35, 16, 'žrtvenik za žrtve paljenice s njegovom rešetkom od tuča; motke za nj i sav njegov pribor; umivaonik i njegov stalak;');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 35, 17, 'zastore za dvorište; stupce i njihova podnožja, pa zastor na ulazu u dvorište;');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 35, 18, 'kočiće za Prebivalište i kočiće za dvorište s njihovim uzicama;');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 35, 19, 'svečano ruho za vršenje službe u Svetištu - posvećena odijela za svećenika Arona i odijela za svećeničku službu njegovih sinova.\"');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 35, 20, 'Nato se sva izraelska zajednica povuče ispred Mojsija.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 35, 21, 'A onda svatko koga je srce vuklo i duša poticala dođe noseći svoj prinos u čast Jahvi za gradnju Šatora sastanka, za svaku službu u njemu i za posvećena odijela.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 35, 22, 'Strčaše se muževi i žene: svi koje je srce vuklo donesoše zapinjača, naušnica, prstenja, narukvica, ogrlica i svakovrsna zlatnog nakita; svi koji bijahu zavjetovali kakvu zlatninu u čast Jahvi.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 35, 23, 'Svi kod kojih se našlo ljubičastog, crvenog i tamnocrvenog prediva i prepredenog lana, učinjenih ovnujskih koža ili finih koža donesoše svoje.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 35, 24, 'Nadalje, svatko tko je mogao dati kakav dar u srebru ili tuču donese to kao prinos u čast Jahvi. Svatko u koga se našlo bagremova drva za upotrebu u bilo kojem poslu, donese ga.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 35, 25, 'Sve žene koje su bile vješte prele su svojim rukama i donosile što bijahu oprele: ljubičastog, crvenog i tamnocrvenog prediva i prepredenog lana.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 35, 26, 'Sve opet žene koje je njihovo srce poticalo zbog njihove vještine prele su kostrijet.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 35, 27, 'Glavari su donosili oniksa i drugoga dragog kamenja za umetanje u oplećak i naprsnik;');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 35, 28, 'pa mirodije i ulje za svjetlo, ulje za pomazanje i miomirisni tamjan.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 35, 29, 'I tako Izraelci - svi ljudi i sve žene koje je srce poticalo da pridonesu bilo što poslu koji je Jahve po Mojsiju naredio da se izvrši - donesoše to kao dragovoljan prinos u čast Jahvi.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 35, 30, 'Potom reče Mojsije Izraelcima: \"Vidite! Jahve je po imenu pozvao Besalela, sina Urijeva, od koljena Hurova a iz plemena Judina.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 35, 31, 'Njega je napunio duhom Božjim, dao mu umješnost, sposobnost i razumijevanje u svim poslovima:');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 35, 32, 'da zamišlja nacrte i da radove izvodi od zlata, srebra i tuča;');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 35, 33, 'da reže dragulje za umetanje; da urezuje u drvetu i da umješno radi svaki posao.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 35, 34, 'Njemu i Oholiabu, sinu Ahisamakovu, od plemena Danova, udijeli i sposobnost da poučavaju druge.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 35, 35, 'Obdari ih umještvom u svakom poslu rezbarskom, krojačkom, veziljskom i tkalačkom; oni tkaju tkanine od ljubičastog, crvenog i tamnocrvenog prediva i prepredenog lana, sposobni su u svakom poslu i vješti u nacrtima.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 36, 1, 'Stoga neka Besalel, Oholiab i svi vještaci koje je Jahve obdario vještinom i sposobnošću da vješto izvedu sve poslove oko podizanja Svetišta obave sve kako je Jahve naredio.\"');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 36, 2, 'Mojsije onda pozva Besalela, Oholiaba i sve one što ih je Jahve obdario vještinom; sve koje je srce poticalo da se prihvate posla i izvedu ga.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 36, 3, 'Oni preuzmu od Mojsija sve prinose koje Izraelci bijahu donijeli da se izvedu poslovi oko podizanja Svetišta. Ali kako su oni i dalje donosili prinose jutro za jutrom,');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 36, 4, 'svi majstori koji su gradili Svetište dođu - svaki s posla na kojem je radio -');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 36, 5, 'i reknu Mojsiju: \"Svijet donosi mnogo više nego što je potrebno za izvođenje posla koji nam je Jahve naredio da izvedemo.\"');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 36, 6, 'Zato Mojsije izda naredbu koju po taboru proglase: \"Neka više nijedan čovjek ni žena ne donosi nikakva priloga za Svetište!\" Tako ustave narod te nije donosio novih darova.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 36, 7, 'Što imahu bijaše dosta da se izvede sve djelo; i još je pretjecalo.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 36, 8, 'I tako najvještiji ljudi među radnicima naprave Prebivalište. Načine ga od deset zavjesa od prepredenog lana i ljubičastog, crvenog i tamnocrvenog prediva. Na njima bijahu izvezeni likovi kerubina.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 36, 9, 'Dužina je svake zavjese iznosila dvadeset osam lakata, a širina svake zavjese četiri lakta. Sve su zavjese bile iste mjere.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 36, 10, 'Pet zavjesa sastave jednu s drugom, a pet drugih zavjesa sastave opet jednu s drugom.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 36, 11, 'Na rubu posljednje od zavjesa sastavljenih u jedno načine petlje od modre vune; jednako ih načine i na rubu posljednje zavjese drugoga dijela;');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 36, 12, 'načine pedeset petlji na jednome komadu, a pedeset na rubu zavjese drugoga komada. Petlje su stajale jedna spram druge.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 36, 13, 'Onda naprave pedeset zlatnih kopča pa sastave zavjese kopčama jednu s drugom. Tako je Prebivalište bilo kao jedna cjelina.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 36, 14, 'Zatim za Šator povrh Prebivališta načine zavjese od kostrijeti; načine ih jedanaest.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 36, 15, 'Dužina svake zavjese bila je trideset lakata, a širina četiri lakta. Tih jedanaest zavjesa bilo je iste mjere.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 36, 16, 'Sastave pet zavjesa za se, a šest drugih opet za se.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 36, 17, 'Naprave pedeset petlji na rubu zavjese jednoga komada, a pedeset načine na rubu drugoga komada.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 36, 18, 'Načine i pedeset kopča od tuča da sastave Šator zajedno, tako da bude jedna cjelina.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 36, 19, 'Zatim naprave pokrov za Šator od učinjenih ovnujskih koža, a povrh njega drugi, od finih koža.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 36, 20, 'Trenice nauzgor za Prebivalište izrade od bagremova drva.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 36, 21, 'Duljina je svake trenice bila deset lakata, a širina lakat i pol.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 36, 22, 'Svaka je trenica imala dva klina da je drže uspravno. To su napravili na svakoj trenici za Šator.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 36, 23, 'Trenice za Prebivalište napravili su ovako: dvadeset trenica za južnu stranu;');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 36, 24, 'napravili su četrdeset podnožja od srebra pod dvadeset trenica - dva podnožja pod prvu trenicu za njezina dva klina i dva podnožja pod svaku slijedeću trenicu za njezina dva klina.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 36, 25, 'Za drugu, sjevernu, stranu Prebivališta naprave dvadeset trenica');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 36, 26, 'i za njih četrdeset podnožja od srebra - dva podnožja pod prvu trenicu, a po dva podnožja pod svaku slijedeću trenicu.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 36, 27, 'Prebivalištu straga, prema zapadu, napraviše šest trenica.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 36, 28, 'Naprave i dvije trenice za uglove Prebivališta straga.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 36, 29, 'Pri dnu su bile rastavljene, ali su se pri vrhu, kod prvoga koluta, sastajale. Tako su ih obje postavili za dva ugla.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 36, 30, 'Bilo je osam trenica s njihovim podnožjima od srebra: šesnaest podnožja, pod svakom trenicom dva.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 36, 31, 'Načine priječnice od bagremova drva: pet njih za trenice s jedne strane Prebivališta,');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 36, 32, 'a pet opet priječnica za trenice s druge strane Prebivališta te pet priječnica za trenice Prebivalištu straga, prema zapadu.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 36, 33, 'Onda načine središnju priječnicu što je prolazila sredinom trenica s kraja na kraj.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 36, 34, 'Trenice oblože zlatom, a njihove kolutove, kroz koje su priječnice bile provučene, načine od zlata. I priječnice oblože zlatom.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 36, 35, 'Naprave zavjesu od ljubičastog, crvenog i tamnocrvenog prediva i prepredenog lana; načine je s izvezenim kerubinima.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 36, 36, 'Za nju naprave četiri stupa od bagremova drva i oblože ih zlatom. Kuke su im bile od zlata, a saliju im i četiri podnožja od srebra.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 36, 37, 'Na ulazu u Šator naprave zavjesu od ljubičastog, crvenog i tamnocrvenog prediva i prepredenog lana, umjetnički protkanu,');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 36, 38, 'i za nju pet stupčića s njihovim kukama. Vrhove stupčića i njihove šipke oblože zlatom, dok im pet podnožja naprave od tuča.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 37, 1, 'Besalel napravi Kovčeg od bagremova drva, dug dva i pol lakta, širok lakat i pol, a lakat i pol visok.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 37, 2, 'Iznutra ga i izvana okuje čistim zlatom. Naokolo mu napravi zlatan završni pojas.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 37, 3, 'I salije mu četiri koluta na njegova četiri ugla: dva koluta s jedne strane, a dva koluta s njegove druge strane.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 37, 4, 'Napravi i motke od bagremova drva i u zlato ih okuje;');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 37, 5, 'onda provuče motke kroz kolutove Kovčegu sa strane za nošenje Kovčega.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 37, 6, 'Zatim napravi Pomirilište od čistoga zlata, dva i pol lakta dugo, a lakat i pol široko.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 37, 7, 'Napravi i dva kerubina od kovanoga zlata, na dva kraja Pomirilišta:');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 37, 8, 'jednoga kerubina na jednome kraju, a drugoga kerubina na drugome kraju. Kerubine na oba kraja načini u jednome komadu s Pomirilištem.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 37, 9, 'Kerubini imali uzdignuta i raširena krila, zaklanjali njima Pomirilište. Bili su licem okrenuti jedan prema drugome, tako da su im lica gledala u Pomirilište.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 37, 10, 'Od bagremova drva načini stol, dva lakta dug, lakat širok, a lakat i pol visok.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 37, 11, 'Obloži ga čistim zlatom i od zlata mu naokolo načini završni pojas.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 37, 12, 'I načini mu obrub unaokolo, podlanicu širok. A za obrub naokolo načini zlatan završni pojas.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 37, 13, 'Salije mu četiri zlatna koluta. Kolutove onda pričvrsti za njegova četiri nožna ugla.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 37, 14, 'Kolutovi su bili tik pod obrubom, kao kvake za motke, da se stol može nositi.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 37, 15, 'Motke za nošenje stola načinio je od bagremova drva i zlatom ih obložio.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 37, 16, 'A pribor što se držao na stolu - njegove zdjele, varjače, vrčeve i pehare za izlijevanje prinosa - napravio je od čistoga zlata.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 37, 17, 'Od čistoga zlata načini i svijećnjak. Svijećnjak - njegovo podnožje i stalak - skova. Njegove čaše - čaške i latice - bile su u jednome komadu s njim.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 37, 18, 'Šest je krakova izbijalo s njegovih strana: tri kraka svijećnjaka s jedne strane, a tri kraka svijećnjaka s druge strane.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 37, 19, 'Na jednome kraku bile su tri čaše u obliku bademova cvijeta, svaka sa svojom čaškom i laticama. Na drugome opet kraku bile su tri čaše u obliku bademova cvijeta, svaka s čaškom i laticama. Tako je bilo na svih šest krakova što izbijahu iz svijećnjaka.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 37, 20, 'Na samome svijećnjaku bile su četiri čaše u obliku bademova cvijeta, svaka s čaškom i laticama:');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 37, 21, 'čaška, u jednom komadu s njim, pod prva dva kraka; pa konačno čaška, u jednom komadu s njim, pod zadnja dva kraka. Tako na svih šest krakova što su iz njega izbijali.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 37, 22, 'Njihove čaške i njihove peteljke bile su u jednom komadu s njim; sve to od čistoga kovanog zlata.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 37, 23, 'A od čistoga zlata napravi mu i sedam svjetiljaka, usekače i pepeljare.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 37, 24, 'Svijećnjak i sav njegov pribor načini od jednoga talenta čistoga zlata.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 37, 25, 'Kadioni je žrtvenik napravio od bagremova drva, lakat dug, lakat širok - u četvorinu - a dva lakta visok. Roščići su mu bili u jednom komadu s njim.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 37, 26, 'Obloži mu čistim zlatom plohu, strane naokolo i njegove roščiće. Načini mu naokolo završni pojas od zlata.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 37, 27, 'Na njemu načini i dva zlatna koluta na oprečnim stranama, ispod završnog pojasa, da služe motkama za kvake kad se na njima nosi.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 37, 28, 'Motke načini od bagremova drva pa ih obloži zlatom.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 37, 29, 'Onda pripravi posvećeno ulje za pomazanje i čisti kad mirisni, onako kako ga pravi pomastar.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 38, 1, 'Od bagremova drva napravi žrtvenik za žrtve paljenice, pet lakata dug, pet lakata širok - u četvorinu - a tri lakta visok.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 38, 2, 'Na njegova četiri ugla načini mu četiri roga. Rogovi su bili u jednom komadu s njim. Onda ga obloži tučem.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 38, 3, 'A načini i sav pribor za žrtvenik: lonce, strugače, kotliće, viljuške i kadionike; sav mu je ovaj pribor načinio od tuča.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 38, 4, 'Za žrtvenik zatim načini rešetku u obliku mrežice od tuča ispod izbočine; zahvaćala mu je do sredine.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 38, 5, 'Salije četiri koluta na četiri ugla tučane rešetke da služe kao kvake za motke.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 38, 6, 'Motke načini od bagremova drva pa ih obloži tučem.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 38, 7, 'Onda provuče motke kroz kolutove na objema stranama žrtvenika da se na njima nosi. Napravio ga je šuplja - od dasaka.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 38, 8, 'A zatim, od zrcala žena koje su posluživale na vratima Šatora sastanka, načini tučani umivaonik i tučani stalak za nj.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 38, 9, 'Onda načini dvorište. Na južnoj strani dvorišta bijahu zavjese od prepredenog lana, stotinu lakata duge.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 38, 10, 'Njihovih dvadeset stupova sa dvadeset podnožja bilo je od tuča, dok su kuke na stupovima i njihove šipke bile od srebra.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 38, 11, 'Od stotinu lakata bile su zavjese i sa sjeverne strane. Njihovih dvadeset stupova sa dvadeset podnožja bilo je od tuča, dok su kuke na stupovima i njihove šipke bile od srebra.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 38, 12, 'Sa zapadne strane bijahu zavjese od pedeset lakata, sa deset stupova i deset njihovih podnožja. Kuke su na stupovima i njihove šipke bile od srebra.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 38, 13, 'Sprijeda, s istoka, zavjese od pedeset lakata.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 38, 14, 'S jedne strane vrata zavjese su bile petnaest lakata, sa tri stupca i njihova tri podnožja.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 38, 15, 'Tako i s druge strane - dakle, na obje strane dvorišnih vrata - bile su zavjese od petnaest lakata, sa tri stupca i njihova tri podnožja.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 38, 16, 'Sve su zavjese oko dvorišta bile od prepredenog lana.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 38, 17, 'Podnožja za stupove bila su od tuča, a kuke na stupovima i njihove šipke od srebra. Vrhovi stupova bili su srebrom obloženi. Sve šipke na dvorišnim stupovima bijahu od srebra.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 38, 18, 'Zavjesa na dvorišnim vratima - izvezena - bila je od ljubičastog, crvenog i tamnocrvenog prediva i prepredenog lana. Dvadeset je lakata bila duga; visoka, po širini, pet lakata kao i dvorišne zavjese.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 38, 19, 'Bila su četiri njihova stupa sa četiri podnožja od tuča. Kuke na stupovima bile su od srebra. Vrhovi stupova bili su srebrom obloženi, a njihove šipke bile su srebrne.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 38, 20, 'Svi kočići unutar Prebivališta bili su od tuča.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 38, 21, 'To je popis stvari za Prebivalište - Prebivalište Svjedočanstva, koji je sastavljen na zapovijed Mojsijevu trudom levita pod vodstvom Itamara, sina svećenika Arona.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 38, 22, 'Besalel, Urijev sin, iz koljena Hurova od plemena Judina napravio je sve što je Jahve Mojsiju naredio.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 38, 23, 'S njim je bio Oholiab, sin Ahisamakov, iz plemena Danova, rezbar, krojač i vezilac za ljubičasto, crveno i tamnocrveno predivo i prepredeni lan.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 38, 24, 'Sve zlato što je utrošeno u radove oko Svetišta - zlato posvećeno prinosom - iznosilo je: dvadeset i devet talenata i sedam stotina trideset šekela u hramskim šekelima.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 38, 25, 'A srebro, sabrano prigodom upisivanja zajednice -');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 38, 26, 'to jest beku po glavi, odnosno pola šekela prema hramskom šekelu, od svakoga koji je bio upisan, od dvadeset godina pa naprijed - iznosilo je: stotinu talenata i tisuću sedam stotina sedamdeset i pet šekela u hramskim šekelima. Bilo je upisanih: šest stotina tri tisuće i petsto pedeset.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 38, 27, 'Stotinu talenata srebra otišlo je za salijevanje podnožja Svetištu i zavjesi: sto podnožja od sto talenata - talenat za podnožje.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 38, 28, 'A od tisuću sedam stotina sedamdeset i pet šekela načinio je kuke za stupove, obložio njihove vrhove i napravio šipke za njih.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 38, 29, 'Tuč od žrtve prikaznice iznosio je sedamdeset talenata i dvije tisuće četiri stotine šekela.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 38, 30, 'Od njega je načinio: podnožja za ulaz u Šator sastanka, žrtvenik od tuča s njegovom tučanom rešetkom i sav pribor za žrtvenik;');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 38, 31, 'dalje, podnožja oko dvorišta, podnožja za dvorišni ulaz; sve kočiće za Prebivalište i sve kočiće oko dvorišta.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 39, 1, 'Od ljubičastog, crvenog i tamnocrvenog prediva naprave lijepo izrađeno ruho za službu u Svetištu; naprave svetu odjeću Aronu, kako je Jahve naredio Mojsiju.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 39, 2, 'Oplećak naprave od zlata, ljubičastog, crvenog i tamnocrvenog prediva i prepredenog lana.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 39, 3, 'Skuju zlatne pločice, a onda ih na niti izrežu da ih vještački uvezu u ljubičasto, crveno i tamnocrveno predivo i prepredeni lan.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 39, 4, 'Za oplećak naprave poramenice koje su bile s njim sastavljene na svoja dva kraja;');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 39, 5, 'tkanica što je na njemu stajala bila je napravljena od zlata, ljubičastog, crvenog i tamnocrvenog prediva i prepredenog lana kao i on, i u jednome komadu s njim, kako je Jahve naredio Mojsiju.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 39, 6, 'Kamenje oniksa optoče obrubom od zlata. Na njima su, kao što se režu pečati, bila urezana imena Izraelovih sinova.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 39, 7, 'Njih stave na poramenice oplećka da budu spomen-kamenje sinovima Izraelovim, kako je Jahve naredio Mojsiju.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 39, 8, 'I naprsnik izrade radovima vještaka kao i oplećak: od zlata, ljubičastog, crvenog i tamnocrvenog prediva i prepredenog lana.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 39, 9, 'Naprsnik načiniše četverouglast, dvostruk; bio je pedalj dug, pedalj širok, a predvostručen.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 39, 10, 'Umetnu u nj četiri reda dragulja. Prvi red bijaše od rubina, topaza i alema;');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 39, 11, 'drugi red od smaragda, safira i ametista;');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 39, 12, 'treći red od hijacinta, ahata i leca;');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 39, 13, 'a četvrti red od krizolita, oniksa i jaspisa. Sve je bilo zlatom obrubljeno.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 39, 14, 'Na kamenima su bila imena Izraelovih sinova. Na broj ih je bilo dvanaest, kao i njihovih imena. Bila su urezana kao i pečati - svaki kamen s imenom jednoga od dvanaest plemena.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 39, 15, 'Za naprsnik naprave lančiće od čistoga zlata kao zasukane uzice.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 39, 16, 'Naprave zatim dva zlatna okvira i dva zlatna kolutića pa pričvrste oba kolutića za dva gornja ugla naprsnika.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 39, 17, 'Sad privežu ovdje zasukane uzice od zlata za dva kolutića što su bila pričvšćena za uglove naprsnika.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 39, 18, 'Druga dva kraja zasukanih uzica pričvrste za dva okvira. Tako ih povežu za poramenice oplećka sprijeda.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 39, 19, 'Potom načine dva zlatna kolutića pa ih pričvrste za dva kraja naprsnika uz nutarnji rub, okrenut prema oplećku.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 39, 20, 'Još naprave dva zlatna kolutića te ih pričvrste za donji, prednji kraj poramenice oplećka, pokraj mjesta gdje se veže, povrh tkanice oplećka.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 39, 21, 'Svežu kolutiće naprsnika s kolutićima oplećka modrom vrpcom, tako da naprsnik stoji nad tkanicom oplećka i da se s oplećka ne mogne odvojiti, kako je Jahve Mojsiju naredio.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 39, 22, 'Naprave i ogrtač za oplećak, sav satkan od ljubičastog prediva.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 39, 23, 'U sredini je ogrtača bio prorez kao otvor na oklopu, prorez naokolo opšiven, da se ogrtač ne podere.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 39, 24, 'O donjem rubu ogrtača načine šipke od ljubičastog, crvenog i tamnocrvenog prediva i prepredenog lana.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 39, 25, 'A načine i zvonca od čistog zlata, pa zvonca privežu među šipke; sve naokolo donjeg ruba ogrtača između šipaka:');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 39, 26, 'zvonce pa šipak, zvonce pa šipak okolo donjeg ruba ogrtača za vršenje službe, kako je Jahve naredio Mojsiju.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 39, 27, 'Zatim od otkanog lana načine košulje Aronu i njegovim sinovima;');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 39, 28, 'a naprave i mitru od lana i kape od lana; platnene gaće načine od prepredenog lana.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 39, 29, 'I pasovi su bili od prepredenog lana i od ljubičastog, crvenog i tamnocrvenog prediva, iglama izvezeni, kako je Jahve Mojsiju naredio.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 39, 30, 'Načine i ploču, sveti vijenac, od čistoga zlata i na njoj urežu natpis kako se urezuje na pečatnome prstenu: \"Posvećen Jahvi.\"');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 39, 31, 'Za nju privežu modru vrpcu da je mogu svezati na vrhu mitre, kako je Jahve naredio Mojsiju.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 39, 32, 'Tako su bili završeni svi radovi na Prebivalištu, Šatoru sastanka. Izraelci su sve načinili onako kako je Jahve Mojsiju naredio da načine.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 39, 33, 'Onda donesu Mojsiju Prebivalište, Šator i sav njegov pribor: njegove kuke, njegove trenice, njegove priječnice, njegove stupove i njegova podnožja;');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 39, 34, 'pokrov od učinjenih ovnujskih koža, pokrov od finih koža, zavjesu za zaklon;');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 39, 35, 'Kovčeg svjedočanstva s njegovim motkama i Pomirilištem;');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 39, 36, 'stol i sav njegov pribor, prinesene hljebove,');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 39, 37, 'svijećnjak od čistoga zlata s njegovim svijećama - svijeće već u red stavljene - i sav njegov pribor i ulje za svjetlo;');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 39, 38, 'zlatni žrtvenik, ulje za pomazanje, miomirisni tamjan i zavjesu za ulaz Šatora;');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 39, 39, 'žrtvenik od tuča s tučanom rešetkom; njegove motke i sav njegov pribor; umivaonik i njegov stalak;');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 39, 40, 'zavjese za dvorište; njihove stupove i njihova podnožja, zavjesu za dvorišni ulaz, njegova užeta i njihove kočiće - sav pribor za službu u Prebivalištu, za Šator sastanka;');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 39, 41, 'lijepo izrađeno ruho za službu u Svetištu - svetu odjeću za svećenika Arona i odijela za svećeničku službu njegovih sinova.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 39, 42, 'Upravo kako je Jahve Mojsiju naredio, tako su Izraelci sav posao obavili.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 39, 43, 'Mojsije pregleda sve radove i utvrdi da su ih dovršili: kako je Jahve naredio, onako su ih i napravili. I Mojsije ih blagoslovi.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 40, 1, 'Reče Jahve Mojsiju:');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 40, 2, '\"Na prvi dan prvoga mjeseca podigni Prebivalište, Šator sastanka.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 40, 3, 'Ondje postavi Kovčeg svjedočanstva, onda Kovčeg zakloni zavjesom.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 40, 4, 'Potom unesi stol i što na nj spada poredaj; unesi i svijećnjak i svijeće mu pripremi.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 40, 5, 'A zlatni žrtvenik za kađenje postavi pred Kovčeg svjedočanstva. Onda objesi zastor nad ulazom u Prebivalište.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 40, 6, 'Stavi žrtvenik za žrtve paljenice pred ulaz Prebivališta, Šatora sastanka.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 40, 7, 'Između Šatora sastanka i žrtvenika smjesti umivaonik i u nj nalij vode.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 40, 8, 'Naokolo napravi dvorište i objesi zastor nad dvorišnim ulazom.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 40, 9, 'Zatim uzmi ulja za pomazanje pa pomaži Prebivalište i sve što je u njemu; posveti ga i sav njegov pribor, pa će svetim postati.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 40, 10, 'Pomaži potom žrtvenik za žrtve paljenice i sav njegov pribor; posveti žrtvenik i presvetim će žrtvenik postati.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 40, 11, 'Pomaži umivaonik s njegovim stalkom: posveti ga!');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 40, 12, 'Dovedi zatim Arona i njegove sinove na ulaz Šatora sastanka pa ih operi vodom.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 40, 13, 'Stavi onda na Arona posvećenu odjeću; pomaži ga i posveti da mi služi kao svećenik.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 40, 14, 'Dovedi i njegove sinove, na njih stavi košulje');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 40, 15, 'i pomaži ih, kako si pomazao i njihova oca, da mi služe kao svećenici. Njihovo pomazanje neka ih uvede u vječno svećenstvo u sve njihove naraštaje.\"');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 40, 16, 'Tako Mojsije učini. Kako mu je Jahve naredio, sve je tako i učinio.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 40, 17, 'Prvoga dana prvoga mjeseca druge godine Prebivalište bi podignuto.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 40, 18, 'Ovako Mojsije namjesti Prebivalište: razmjesti njegova podnožja, onda uspravi njegove trenice, zatim postavi priječnice i podiže stupove.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 40, 19, 'Zatim raspne Šator nad Prebivalište, a povrh njega stavi pokrov Šatora, kako je Jahve Mojsiju naredio.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 40, 20, 'Uze onda Svjedočanstvo i stavi ga u Kovčeg; na Kovčeg postavi motke; onda stavi Pomirilište ozgo na Kovčeg.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 40, 21, 'Potom unese Kovčeg u Prebivalište; objesi zavjesu za zaklon. Tako zastre Kovčeg svjedočanstva, kako je Jahve i naredio Mojsiju.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 40, 22, 'Zatim postavi stol u Šator sastanka, Prebivalištu sa sjeverne strane, ali izvan zavjese.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 40, 23, 'Po njemu poreda kruhove pred Jahvom, kako je Jahve naredio Mojsiju.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 40, 24, 'Onda smjesti svijećnjak u Šator sastanka naprama stolu, na južnoj strani Prebivališta.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 40, 25, 'I postavi svjetiljke pred Jahvom, kako je Jahve naredio Mojsiju.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 40, 26, 'Zlatni žrtvenik smjesti u Šator sastanka, pred zavjesu.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 40, 27, 'Na njemu zapali miomirisnog tamjana, kako je Jahve naredio Mojsiju.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 40, 28, 'Poslije toga stavi zavjesu na ulaz u Prebivalište.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 40, 29, 'Kod ulaza u Prebivalište, u Šator sastanka, postavi žrtvenik za žrtve paljenice. Na njemu prinese žrtvu paljenicu i žrtvu od žita, kako je Jahve naredio Mojsiju.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 40, 30, 'Između Šatora sastanka i žrtvenika smjesti umivaonik pa u nj ulije vode za pranje.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 40, 31, 'Iz njega su Mojsije, Aron i njegovi sinovi prali svoje ruke i svoje noge.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 40, 32, 'A prali su se kad su ulazili u Šator sastanka i kad su pristupali k žrtveniku, kako je Jahve naredio Mojsiju.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 40, 33, 'Napokon Mojsije napravi dvorište oko Prebivališta i žrtvenika i postavi zavjesu na dvorišnim vratima. Tako Mojsije završi taj posao.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 40, 34, 'A onda oblak prekri Šator sastanka i slava Jahvina ispuni Prebivalište.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 40, 35, 'Mojsije nije mogao ući u Šator sastanka zbog oblaka koji je na njemu stajao i slave Jahvine koja je ispunjala Prebivalište.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 40, 36, 'Sve vrijeme njihova putovanja, kad god bi se oblak digao s Prebivališta, Izraelci bi krenuli;');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 40, 37, 'ali ako se oblak ne bi digao, ni oni ne bi na put polazili sve do dana dok se ne bi digao.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 40, 38, 'Jer sve vrijeme njihova putovanja oblak Jahvin danju stajaše nad Prebivalištem, a noću bi se u oblaku pojavila vatra vidljiva svemu domu Izraelovu.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 1, 1, 'Zovnu Jahve Mojsija te mu iz Šatora sastanka reče:');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 1, 2, '\"Govori Izraelcima i kaži im: \'Kad tko od vas želi prinijeti Jahvi žrtvu od stoke, prinijet će je ili od krupne ili od sitne stoke.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 1, 3, 'Ako njegov prinos za žrtvu paljenicu bude od krupne stoke, neka prinese muško bez mane. Neka ga dovede k ulazu u Šator sastanka da pred Jahvom bude primljen.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 1, 4, 'Neka stavi svoju ruku na glavu žrtve paljenice da mu za njegovo ispaštanje bude primljena.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 1, 5, 'Neka zatim zakolje junca pred Jahvom. A Aronovi sinovi, svećenici, neka prinesu krv. Neka njome zapljusnu sve strane žrtvenika koji stoji pred ulazom u Šator sastanka.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 1, 6, 'Potom neka se žrtva sadre i rasiječe na dijelove.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 1, 7, 'Neka sinovi Aronovi, svećenici, nalože vatru na žrtveniku i na vatru metnu drva.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 1, 8, 'Neka zatim sinovi Aronovi, svećenici, naslažu dijelove, s glavom i lojem, na drva što su na vatri na žrtveniku.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 1, 9, 'Drobina i noge neka se operu u vodi. A onda neka svećenik sve sažeže u kad na žrtveniku. To je žrtva paljenica, žrtva paljena Jahvi na ugodan miris.\'');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 1, 10, 'Ako bi htio prinijeti za žrtvu paljenicu od sitne stoke - od ovaca ili koza - neka prinese muško bez mane.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 1, 11, 'Neka ga zakolje pred Jahvom, na žrtveniku sa sjeverne strane. Neka zatim Aronovi sinovi, svećenici, zapljusnu žrtvenik krvlju sa svih strana.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 1, 12, 'Potom neka je rasijeku na dijelove, a svećenik neka ih, s glavom i lojem, naslaže na drva što su na vatri na žrtveniku.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 1, 13, 'Drobina i noge neka se operu u vodi. Onda svećenik neka sve prinese i na žrtveniku sažeže. To je žrtva paljenica, žrtva paljena Jahvi na ugodan miris.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 1, 14, 'Ako bi hto prinijeti Jahvi ptice kao žrtvu paljenicu, neka onda prinese grlicu ili golubića.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 1, 15, 'Neka ga svećenik prinese k žrtveniku i, zavrnuvši mu vratom, otkine glavu i na žrtveniku sažeže. Zatim neka mu krv iscijedi žrtveniku sa strane.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 1, 16, 'Neka mu gušu i perje ukloni i pobaca ih na istočnu stranu žrtvenika, na mjesto za otpatke.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 1, 17, 'Neka ga raspori duž obaju krila, ali neka ih ne rastavlja. Onda neka ga svećenik na žrtveniku sažeže na drvima što su na vatri. To je žrtva paljenica, žrtva paljena Jahvi na ugodan miris.\"');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 2, 1, '\"Kad tko želi prinijeti Jahvi žrtvu prinosnicu, neka njegov dar bude od najboljeg brašna; neka ga polije uljem i na nj stavi tamjana.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 2, 2, 'Neka ga onda donese Aronovim sinovima, svećenicima. Zatim neka zagrabi šaku od toga brašna i ulja i sav tamjan, pa neka svećenik na žrtveniku to sažeže u kad za spomen-žrtvu. To je žrtva paljena Jahvi na ugodan miris.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 2, 3, 'A što od žrtve prinosnice ostane, neka pripadne Aronu i njegovim sinovima - najsvetije od žrtava Jahvi paljenih.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 2, 4, 'Ako za žrtvu prinosnicu želiš prinijeti tijesta pečena u peći, neka to budu beskvasne pogače od najboljeg brašna, zamiješene u ulju, ili beskvasne prevrte uljem namazane.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 2, 5, 'Ako tvoj dar bude žrtva prinosnica pečena na tavi, neka bude od najboljeg brašna, neukvasana i u ulju zamiješena.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 2, 6, 'U komade je izlomi i po njima ulja polij: žrtva je to prinosnica.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 2, 7, 'Bude li tvoja prinosnica kuhana u kotluši, neka bude od najboljeg brašna, pripravljena s uljem.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 2, 8, 'Donosi Jahvi žrtvu prinosnicu tako pripravljenu! Neka se preda svećeniku, a on će je polagati na žrtvenik.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 2, 9, 'Neka svećenik odvoji od žrtve prinosnice dio kao spomen-žrtvu, pa neka ga sažeže u kad na žrtveniku - kao žrtvu paljenu Jahvi na ugodan miris!');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 2, 10, 'A što od žrtve prinosnice ostane, neka pripadne Aronu i njegovim sinovima - najsvetije od žrtava Jahvi paljenih.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 2, 11, 'Nikakva žrtva prinosnica koju budeš prinosio Jahvi neka ne bude priređivana s kvasom, jer ne smiješ u kad sažigati ni kvasa ni meda kao žrtvu paljenicu.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 2, 12, 'Prinosite ih Jahvi kao prvine plodova, ali neka se sa žrtvenika ne viju na ugodan miris.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 2, 13, 'Svaku svoju žrtvu prinosnicu posoli. Ne ostavljaj svoje žrtve prinosnice bez soli Saveza sa svojim Bogom: sa svakim svojim prinosom prinesi i sol.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 2, 14, 'Ako prinosiš Jahvi žrtvu prinosnicu od prvina, prinesi tu žrtvu od prvina svojih plodova u obliku klasa pržena na vatri ili brašna od samljevenog zrnja.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 2, 15, 'Dodaj još ulja i na nju stavi tamjana. To je žrtva prinosnica.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 2, 16, 'Onda neka svećenik sažeže u kad za spomen-žrtvu dio kruha i ulja i sav tamjan kao žrtvu Jahvi paljenu.\"');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 3, 1, '\"Ako tko prinosi žrtvu pričesnicu te ako prinosi goveče - žensko ili muško - neka je bez mane što prinosi pred Jahvom.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 3, 2, 'Neka stavi svoju ruku na glavu svoje žrtve i zakolje je na ulazu u Šator sastanka. Neka zatim Aronovi sinovi, svećenici, zapljusnu krvlju sve strane žrtvenika.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 3, 3, 'Od žrtve pričesne, kao žrtvu paljenu, neka prinese loj što omotava drobinu, sav loj što je oko drobine;');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 3, 4, 'oba bubrega i loj što je na njima i na slabinama; pa privjesak s jetre: neka i njega s bubrezima izvadi.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 3, 5, 'Zatim neka Aronovi sinovi te dijelove sažegu na žrtveniku sa žrtvom paljenicom koja bude na drvima na vatri. To neka je žrtva paljena Jahvi na ugodan miris.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 3, 6, 'Ako tko prinosi za žrtvu pričesnicu od sitne stoke Jahvi, neka prinese bez mane, bilo muško ili žensko.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 3, 7, 'Ako na dar prinosi ovcu, neka je prinese pred Jahvom.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 3, 8, 'Neka stavi svoju ruku na glavu svoje žrtve i neka je zakolje pred Šatorom sastanka. Zatim neka Aronovi sinovi zapljusnu njezinom krvlju sve strane žrtvenika.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 3, 9, 'Od žrtve pričesnice neka prinesu žrtvu paljenu Jahvi: njezin loj, cio pretili rep, otkinuvši ga tik uz hrptenjaču; loj što omotava drobinu, sav loj što je oko drobine;');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 3, 10, 'oba bubrega i loj što je na njima i na slabinama; pa privjesak s jetre: neka i njega s bubrezima izvadi.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 3, 11, 'Onda neka svećenik to sažeže na žrtveniku u kad - kao hranu vatre u čast Jahvi.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 3, 12, 'Ako li prinosi kozu, neka je prinese pred Jahvom:');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 3, 13, 'neka stavi svoju ruku na glavu svoje žrtve i neka je zakolje pred Šatorom sastanka. Neka zatim Aronovi sinovi zapljusnu njezinom krvlju sve strane žrtvenika.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 3, 14, 'Onda neka od nje prinese, kao paljenu žrtvu Jahvi, loj što omotava drobinu, sav loj što je oko drobine;');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 3, 15, 'oba bubrega i loj što je na njima i na slabinama; pa privjesak s jetre; neka i njega s bubrezima izvadi.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 3, 16, 'Onda neka ih svećenik sažeže na žrtveniku - žrtvu paljenu Jahvi na ugodan miris. Sav loj pripada Jahvi.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 3, 17, 'Neka ovo bude zakon za sva vremena svim vašim naraštajima u kojem god mjestu budete boravili: nipošto ne smijete jesti ni loja ni krvi.\"');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 4, 1, 'Jahve reče Mojsiju:');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 4, 2, '\"Ovako kaži Izraelcima: \'Ako se tko nehotice ogriješi o bilo koju Jahvinu zapovijed te učini što je zabranjeno činiti:');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 4, 3, 'Bude li to pomazanjem posvećeni svećenik koji pogriješi i navuče tako krivnju na narod, onda za grijeh koji učini neka prinese Jahvi jedno grlo krupne stoke, jednoga junca bez mane, kao žrtvu okajnicu.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 4, 4, 'Neka junca dovede pred Jahvu do ulaza u Šator sastanka; neka juncu na glavu položi svoju ruku i onda junca zakolje pred Jahvom.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 4, 5, 'Zatim neka pomazanjem posvećeni svećenik uzme krvi od junca i donese je u Šator sastanka.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 4, 6, 'Onda neka svećenik zamoči svoj prst u krv i tom krvlju neka sedam puta poškropi prednju stranu zavjese Svetišta, pred Jahvom.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 4, 7, 'Potom neka svećenik stavi te krvi na rogove žrtvenika za miomirisni kad koji se dimi pred Jahvom u Šatoru sastanka. Svu ostalu krv od junca neka izlije podno žrtvenika za žrtve paljenice što se nalazi na ulazu u Šator sastanka.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 4, 8, 'Iz junca što ga prinosi kao žrtvu okajnicu neka izvadi: loj što omotava drobinu, sav loj što je oko drobine;');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 4, 9, 'oba bubrega i loj što je na njima i na slabinama, privjesak s jetre; neka i njega izvadi s bubrezima;');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 4, 10, 'onako kako se uzima dio iz vola žrtve pričesnice. Neka ih zatim svećenik sažeže u kad na žrtveniku za žrtve paljenice.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 4, 11, 'Kožu od junca, sve meso od njega, njegovu glavu, njegove noge, drobinu i njegovu nečist');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 4, 12, '- svega junca - neka iznese na čisto mjesto izvan tabora gdje se pepeo izasiplje i neka ga spali na vatri od drva; tu na pepelu neka se junac spali.\'\"');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 4, 13, '\"Ako sva izraelska zajednica nehotično pogriješi počinivši štogod što je Jahve zabranio pa tako postanu krivi a ne budu svjesni krivnje,');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 4, 14, 'onda, kad se sazna za učinjeni prijestup, neka zajednica prinese jedno grlo krupne stoke - jednoga junca bez mane - kao žrtvu okajnicu. Neka ga dovedu pred Šator sastanka.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 4, 15, 'Tu pred Jahvom neka starješine zajednice polože svoje ruke juncu na glavu. Neka se onda junac zakolje pred Jahvom.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 4, 16, 'Neka zatim pomazanjem posvećeni svećenik donese krvi od junca u Šator sastanka;');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 4, 17, 'neka svećenik zamoči svoj prst u krv i sedam puta poškropi prednju stranu zavjese, pred Jahvom.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 4, 18, 'Neka zatim stavi krvi na rogove žrtvenika koji se nalazi pred Jahvom u Šatoru sastanka. Svu ostalu krv neka izlije podno žrtvenika za žrtve paljenice što se nalazi na ulazu u Šator sastanka.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 4, 19, 'S junca neka skine sav loj i sažeže ga u kad na žrtveniku.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 4, 20, 'I s juncem neka uradi kako je uradio s onim juncem žrtve okajnice - tako neka učini i s tim. I pošto svećenik nad članovima zajednice izvrši obred pomirenja, bit će im oprošteno.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 4, 21, 'Neka odnese junca izvan tabora i spali ga kako je spalio i prvoga junca. To je žtrva za prijestup zajednice.\"');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 4, 22, '\"Ako nehotično pogriješi glavar i učini štogod što je Jahve, Bog njegov, zabranio i tako sagriješi,');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 4, 23, 'onda, kad ga obznane o prijestupu koji je počinio, neka kao svoj prinos donese muško jare bez mane.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 4, 24, 'Položivši svoju ruku jaretu na glavu, neka ga zakolje na mjestu gdje se kolju pred Jahvom žrtve paljenice. To je žrtva okajnica.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 4, 25, 'Svećenik neka uzme na svome prstu krvi od žrtve okajnice pa je stavi na rogove žrtvenika za žrtve paljenice. A svu ostalu krv neka izlije podno žrtvenika za žrtve paljenice.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 4, 26, 'Sav loj neka sažeže u kad na žrtveniku kao i loj sa žrtve pričesnice. Neka tako svećenik nad glavarom izvrši obred pomirenja za njegov grijeh, pa će mu biti oprošteno.\"');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 4, 27, '\"Ako tko od običnoga puka nehotično pogriješi učinivši štogod što je Jahve zabranio i tako sagriješi,');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 4, 28, 'onda, kad ga obznane o prijestupu koji je počinio, neka kao svoj prinos za grijeh koji je počinio donese žensko jare bez mane.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 4, 29, 'Neka stavi svoju ruku na glavu okajnice i zakolje žrtvu okajnicu na mjestu za žrtve paljenice.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 4, 30, 'Neka svećenik uzme krvi na svome prstu pa je stavi na rogove žrtvenika za žrtve paljenice. A svu ostalu krv neka izlije podno žrtvenika.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 4, 31, 'Neka zatim izvadi sav njezin loj kao što se vadi loj iz žrtve pričesnice; neka ga onda svećenik sažeže u kad na žrtveniku kao ugodan miris Jahvi. Kad svećenik izvrši nad tim čovjekom obred pomirenja, bit će mu oprošteno.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 4, 32, 'Ako bi tko htio dovesti janje kao žrtvu okajnicu, neka dovede žensko bez mane.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 4, 33, 'Položivši svoju ruku na glavu žrtve okajnice, neka je zakolje kao žrtvu okajnicu na mjestu gdje se kolju žrtve paljenice.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 4, 34, 'Neka onda svećenik uzme krvi od žrtve okajnice na svome prstu pa je stavi na rogove žrtvenika za žrtve paljenice. A svu ostalu krv neka izlije podno žrtvenika.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 4, 35, 'Neka zatim izvadi sav njezin loj kao što se vadi loj iz žrtve pričesnice. Neka to svećenik sažeže u kad povrh žrtava paljenih Jahvi u čast. Neka tako svećenik izvrši nad tim čovjekom obred pomirenja za grijeh koji je počinio, pa će mu biti oprošteno.\"');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 5, 1, '\"Zgriješi li tko tako što čuje riječi proklinjanja a odbije da svjedoči iako je mogao biti svjedokom jer je ili sam vidio ili doznao pa tako nosi krivnju na sebi;');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 5, 2, 'ili ako tko dirne kakav nečist predmet, strv nečiste zvijeri, strv nečista živinčeta ili strv nečista puzavca - i u neznanju postane nečist i odgovoran;');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 5, 3, 'ili kad se tko dotakne nečistoće čovječje, bilo to što mu drago od čega se nečistim postaje i toga ne bude svjestan, kad dozna, biva odgovoran;');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 5, 4, 'nadalje, kad tko nepromišljeno izusti zakletvu na dobro ili zlo - na što se već čovjek nepromišljeno zaklinje - i toga ne bude svjestan, onda, kad dozna, biva odgovoran;');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 5, 5, 'ako, dakle, tko postane odgovoran u bilo čemu od toga, neka prizna počinjeni grijeh.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 5, 6, 'I neka prinese Jahvi kao žrtvu naknadnicu za počinjeni grijeh jednu ženku od sitne stoke, janje ili kozle, kao žrtvu okajnicu. Neka svećenik izvrši nad njim obred pomirenja koji će ga osloboditi od njegova grijeha.\"');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 5, 7, '\"Ako mu sredstva ne dopuštaju da pribavi glavu sitne stoke, neka Jahvi, kao naknadnicu za počinjeni grijeh, prinese dvije grlice ili dva golubića; jedno kao žrtvu okajnicu, a drugo kao žrtvu paljenicu.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 5, 8, 'Neka ih donese svećeniku, a on neka najprije prinese ono što je određeno kao žrtva okajnica. Stisnuvši ga za vrat, neka mu slomi šiju, ali neka glave ne otkida.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 5, 9, 'Neka krvlju žrtve poškropi žrtvenik sa strane, a ostatak krvi neka se iscijedi podno žrtvenika. To je žrtva okajnica.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 5, 10, 'Onda neka drugo prinese kao žrtvu paljenicu prema propisu. Neka tako svećenik nad tim čovjekom izvrši obred pomirenja za grijeh koji je počinio, i bit će mu oprošteno.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 5, 11, 'Ako mu sredstva ne dopuštaju da pribavi dvije grlice ili dva golubića, neka Jahvi, u zadovoljštinu za počinjeni grijeh, prinese jednu desetinu efe njaboljeg brašna. Ulja u nj neka ne ulijeva niti na nj tamjana stavlja jer je žrtva okajnica.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 5, 12, 'Kada to donese svećeniku, neka svećenik zagrabi punu pregršt kao spomen-žrtvu i na žrtveniku sažeže u čast Jahvi povrh paljenih žrtava. To je žrtva okajnica.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 5, 13, 'Neka tako svećenik izvrši nad tim čovjekom obred pomirenja za grijeh koji je počinio u bilo kojem od tih slučajeva, pa će mu biti oprošteno. Ono ostalo neka pripadne svećeniku kao i od žrtve prinosnice.\"');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 5, 14, 'Još reče Jahve Mojsiju:');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 5, 15, '\"Ako tko počini pronevjerenje ogriješivši se nehotično o svete stvari Jahvine, neka za naknadu, kao žrtvu naknadnicu, prinese Jahvi, iz svoga stada, ovna bez mane, vrijedna - po tvojoj procjeni - najmanje dva šekela srebra - prema cijeni hramskog šekela.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 5, 16, 'Neka nadoknadi koliko se ogriješio o svete stvari i tome doda još petinu i neka dadne svećeniku. Neka svećenik nad njim izvrši obred pomirenja ovnom žrtve naknadnice, i bit će mu oprošteno.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 5, 17, 'Ako tko i ne znajući pogriješi i učini štogod što je Jahve zabranio, kriv je, pa neka snosi posljedice svoje krivnje.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 5, 18, 'Neka svećeniku dovede za naknadnicu iz svoga stada ovna bez mane, prema tvojoj procjeni. Neka svećenik nad tim čovjekom izvrši obred pomirenja za pogrešku što je počinio u neznanju, i bit će mu oprošteno.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 5, 19, 'To je žrtva naknadnica; on je doista bio odgovoran Jahvi.\"');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 5, 20, 'Jahve još reče Mojsiju:');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 5, 21, '\"Kad se tko ogriješi i počini pronevjeru prema Jahvi prevarivši svoga bližnjega u pologu ili pohrani, a tako i krađom ili iskorištavanjem svoga bližnjega;');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 5, 22, 'ili, nađe li što je bilo izgubljeno pa slaže i krivo se zakune u bilo kojem grijehu što ga čovjek može učiniti;');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 5, 23, 'ako tko tako pogriješi i kriv postane, onda ono što je krađom oduzeo ili što je iskorištavanjem namakao; ili polog što mu je bio povjeren; ili izgubljenu stvar što ju je našao;');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 5, 24, 'ili ono za što se bio krivo zakleo - neka u cijelosti vrati i, dodavši tome petinu, neka dadne onome kome pripada istoga dana kad spozna svoju krivnju.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 5, 25, 'Neka potom svećeniku za naknadu, kao žrtvu naknadnicu Jahvi, dovede iz svog stada jednoga ovna bez mane, prema tvojoj procjeni,');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 5, 26, 'a svećenik neka nad tim čovjekom izvrši obred pomirenja pred Jahvom, i bit će mu oprošteno, ma kakvo bilo nedjelo kojega je krivac.\"');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 6, 1, 'Jahve još reče Mojsiju:');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 6, 2, '\"Naredi Aronu i njegovim sinovima: \'Ovakav je obred za žrtvu paljenicu: žrtva paljenica neka ostane na žeravi na žrtveniku svu noć do jutra; i vatra neka neprestano gori na žrtveniku.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 6, 3, 'Neka svećenik stavi na se lanenu košulju, na svoje tijelo neka navuče lanene gaće; zatim neka zgrne zamašćeni pepeo u što je vatra pretvorila žrtvu paljenicu na žrtveniku i neka ga stavi pokraj žrtvenika.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 6, 4, 'Potom neka svuče svoje ruho i na se obuče drugo te neka odnese zamašćeni pepeo na čisto mjesto izvan tabora.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 6, 5, 'Vatra na žrtveniku mora uvijek gorjeti; ne smije se gasiti. Neka svako jutro svećenik na nju naloži drva i onda na nju naslaže žrtvu paljenicu. Tu neka u kad sažiže loj sa žrtava pričesnica.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 6, 6, 'Neka na žrtveniku trajno gori vatra; neka se ne gasi.\'\"');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 6, 7, '\"Ovo je obred za žrtvu prinosnicu: neka je Aronovi sinovi pronose u nazočnosti Jahve pred žrtvenikom.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 6, 8, 'Pošto jedan od njih zagrabi pregršt najboljeg brašna i ulja sa žrtve prinosnice i sav tamjan što bude na njoj, pošto to sažeže na žrtveniku kao spomen-žrtvu, ugodan miris Jahvi,');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 6, 9, 'neka ostatak u obliku beskvasnih kruhova pojedu Aron i njegovi sinovi; neka ga jedu na posvećenu mjestu - u dvorištu Šatora sastanka.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 6, 10, 'Neka se ne peče s kvascem. To je dio žrtava meni paljenih što im ga ja dajem - dio najsvetiji, jednako kao i žrtva okajnica i kao žrtva naknadnica.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 6, 11, 'Svaki muškarac Aronova potomstva može jesti taj dio od žrtava paljenih Jahvi, i to je vječni zakon za sve vaše naraštaje: i tko ih se god dotakne, bit će posvećen.\"');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 6, 12, 'Jahve još reče Mojsiju:');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 6, 13, '\"Neka Aron i njegovi sinovi na dan svoga pomazanja prinesu Jahvi ovaj prinos: desetinu efe najboljeg brašna kao redovitu žrtvu prinosnicu, polovinu ujutro, a polovinu uvečer.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 6, 14, 'Neka bude pripravljena u tavi na ulju. Donesi je dobro namočenu i prinesi Jahvi kao ugodan miris, kao žrtvu prinosnicu od više komada.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 6, 15, 'Neka je tako pripravi svećenik koji od njegovih sinova bude pomazan da ga naslijedi. To je vječni zakon. Neka se ta žrtva Jahvi sva sažeže!');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 6, 16, 'Svaka svećenička žrtva prinosnica treba da bude posve spaljena; neka se od nje ne jede.\"');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 6, 17, 'Još reče Jahve Mojsiju:');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 6, 18, '\"Kaži Aronu i njegovim sinovima: \'Ovo je obred žrtvovanja za grijeh: žrtva okajnica neka se zakolje pred Jahvom na mjestu gdje se kolje žrtva paljenica - presveta je!');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 6, 19, 'Svećenik koji prinosi tu žrtvu okajnicu neka od nje i jede; neka se ona jede na posvećenu mjestu, u dvorištu Šatora sastanka.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 6, 20, 'Tko se god dotakne njezina mesa bit će posvećen; ako krv poštrapa odijelo, poštrapani dio neka se ispere na posvećenu mjestu.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 6, 21, 'A posuda od ilovače u kojoj bude meso kuhano neka se razbije; a ako bude kuhano u posudi od tuča, neka se istare i vodom ispere.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 6, 22, 'Svaki muški od svećeničke loze može od nje jesti - presveta je!');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 6, 23, 'Ali nijedna žrtva okajnica od koje je krv donesena u Šator sastanka za obred pomirenja u Svetištu neka se ne jede, nego na vatri spali.\'\"');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 7, 1, '\"Ovo je obred za žrtvu naknadnicu.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 7, 2, 'Nadasve je sveta! Neka se žrtva naknadnica zakolje na mjestu gdje se kolju žrtve paljenice, a njezinom krvlju neka svećenik zapljusne sve strane žtrvenika.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 7, 3, 'Zatim neka prinese sav loj s nje: pretili rep, loj što omotava drobinu,');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 7, 4, 'oba bubrega i loj što je na njima i na slabinama; pa privjesak s jetre: neka i njega izvadi s bubrezima!');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 7, 5, 'Neka ih svećenik sažeže na žrtveniku kao žrtvu u čast Jahvi paljenu. To je žrtva naknadnica.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 7, 6, 'Svaki muški od svećeničke loze može od nje jesti. Neka je jedu na posvećenu mjestu - presveta je!');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 7, 7, 'Kakva je žrtva okajnica, takva je i žrtva naknadnica; jedno je pravilo za njih: neka pripadne svećeniku koji njome vrši obred pomirenja.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 7, 8, 'Tako isto koža od žrtve koju tko preda svećeniku da bude prinesena za žrtvu paljenicu neka pripadne svećeniku.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 7, 9, 'Nadalje, svaka žrtva prinosnica što bude pečena u peći, kao i svaka što bude zgotovljena u kotluši ili na tavi, neka pripadne svećeniku koji je prinosi.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 7, 10, 'A svaka žrtva prinosnica, zamiješena s uljem ili nasuho, neka pripadne svim Aronovim sinovima bez razlike!\"');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 7, 11, '\"Ovo je obred za žrtvu pričesnicu koja će se prinositi Jahvi.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 7, 12, 'Ako se prinosi u zahvalu, neka se zajedno sa žrtvom zahvalnicom prinesu i beskvasne pogače uljem zamiješene; beskvasne prevrte uljem namazane i kolači od najboljeg brašna, zamiješeni uljem.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 7, 13, 'Ovaj prinos, nadopunjen kolačima od ukvasanoga tijesta, neka se prinosi zajedno sa žrtvom pričesnicom u zahvalu.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 7, 14, 'Od svake ovakve žrtve neka se prinese po jedan kolač na dar Jahvi. To neka bude za svećenika koji zapljuskuje krv od žrtve pričesnice.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 7, 15, 'A meso žrtve pričesnice neka se pojede istoga dana kad bude žrtvovana; neka se od nje ne ostavlja ništa za sutradan.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 7, 16, 'A bude li prinos žrtva zavjetnica ili žrtva dragovoljna, neka se jede na dan kad se žrtva prinosi. Što ostane od nje neka se jede sutradan.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 7, 17, 'A što još mesa od žrtve preteče, neka se treći dan na vatri spali.\"');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 7, 18, '\"Ako bi tko jeo meso žrtve pričesnice i treći dan, žrtva neće biti primljena niti će onome koji je prinosi biti uračunata. To je meso kvarno, i onaj koji od toga jede neka i posljedice krivnje snosi!');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 7, 19, 'Meso koje se dotakne bilo čega nečista neka se ne jede nego na vatri spali! Inače, tko je god čist može jesti meso.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 7, 20, 'A tko bi nečist jeo mesa od žrtve pričesnice što je bila Jahvi prinesena takav neka se iskorijeni iz svoga naroda.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 7, 21, 'Kad se tko dotakne bilo čega nečista - bila to nečist čovječja, kakva nečista životinja ili bilo kakvo nečisto stvorenje - pa pojede mesa od žrtve pričesnice koja je prinesena Jahvi takav neka se iskorijeni iz svoga naroda!\"');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 7, 22, 'Reče Jahve Mojsiju:');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 7, 23, '\"Ovako kaži Izraelcima: \'Ne jedite loja ni volujskoga, ni ovčjega, ni kozjega.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 7, 24, 'Loj sa životinje koja ugine, ili koju divlje zvijeri razderu, može se upotrijebiti za bilo što, ali ga ne smijete jesti.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 7, 25, 'Tko god jede loj od životinje koja se može prinijeti Jahvi kao žrtva paljenica takav neka se iskorijeni iz svoga naroda.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 7, 26, 'Ne smijete uživati krvi ni od ptica ni od stoke ni u kojem svome prebivalištu.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 7, 27, 'Tko bi god uživao bilo kakvu krv neka se iskorijeni iz svoga naroda.\'\"');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 7, 28, 'Jahve još reče Mojsiju:');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 7, 29, '\"Ovako kaži Izraelcima: \'Prinos Jahvi od žrtve pričesnice mora donijeti onaj koji Jahvi prinosi žrtvu pričesnicu.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 7, 30, 'Svojim vlastitim rukama neka prinese Jahvi žrtvu paljenicu; neka prinese loj i grudi; grudi neka se prinesu pred Jahvom kao žrtva prikaznica.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 7, 31, 'Neka svećenik sažeže loj na žrtveniku, a grudi neka pripadnu Aronu i njegovim sinovima.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 7, 32, 'Desno pleće od svojih žrtava pričesnica dajte svećeniku na dar.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 7, 33, 'Onome Aronovu sinu koji bude prinosio krv i loj sa žrtve pričesnice neka u dio pripadne desno pleće.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 7, 34, 'Jer ja uzimam od Izraelaca grudi od žrtava pričesnica što se prinose kao žrtva prikaznica i pleće žrtve podizanice te ih predajem svećeniku Aronu i njegovim sinovima. To je trajna odredba za Izraelce.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 7, 35, 'To je dohodak Aronov i njegovih sinova od žrtava paljenih u čast Jahvi; dodjeljuje im se od onog dana kad se dovedu da vrše svećeničku službu u čast Jahvi.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 7, 36, 'Jahve je naredio da im se od dana kad budu pomazani to daje kao pristojbina od Izraelaca. To je trajna odredba za njihove naraštaje\'.\"');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 7, 37, 'To je obred za žrtvu paljenicu, prinosnicu, okajnicu, naknadnicu, žrtvu posvetnicu i žrtvu pričesnicu');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 7, 38, 'koji je Jahve naredio Mojsiju na Sinajskom brdu kad je zapovjedio Izraelcima da Jahvi u Sinajskoj pustinji prinose žrtve.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 8, 1, 'Jahve reče Mojsiju:');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 8, 2, '\"Uzmi Arona, a s njim i njegove sinove; ruho, ulje pomazanja, junca žrtve okajnice, dva ovna i košaru beskvasnih kruhova');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 8, 3, 'te skupi svu zajednicu na ulazu u Šator sastanka.\"');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 8, 4, 'Mojsije učini kako mu je Jahve naredio, i zajednica se sabra na ulazu u Šator sastanka.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 8, 5, 'Tada Mojsije progovori zajednici: \"Ovo je Jahve zpovjedio da se učini.\"');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 8, 6, 'Izvede zatim Mojsije Arona i njegove sinove pa ih u vodi opra.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 8, 7, 'Obuče na nj haljinu, opasa ga pojasom, ogrnu ga ogrtačem i stavi mu oplećak. Zatim ga opasa tkanicom oplećka i njome pritegnu uza nj oplećak.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 8, 8, 'Stavi mu naprsnik, a u naprsnik metnu Urim i Tumim.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 8, 9, 'Na glavu mu stavi mitru, a sprijeda na mitru postavi zlatnu pločicu - sveti vijenac - kako je Jahve naredio Mojsiju.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 8, 10, 'Uzme zatim Mojsije ulje pomazanja te pomaže Prebivalište i sve što je u njemu da ih posveti.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 8, 11, 'Sedam puta poškropi njime žrtvenik te pomaže žrtvenik i sav njegov pribor, umivaonik s njegovim stalkom da ih posveti.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 8, 12, 'Izlije ulja pomazanja Aronu na glavu te ga pomaže da ga posveti.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 8, 13, 'Potom Mojsije dovede Aronove sinove; na njih obuče haljine, pasovima ih opaše i poveze im zavije, kako je Jahve Mojsiju naredio.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 8, 14, 'Dovede potom junce žrtve okajnice. Aron i njegovi sinovi stave svoje ruke na glavu juncu žrtve okajnice.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 8, 15, 'Zatim ga Mojsije zakolje. Onda uzme krvi pa je svojim prstom stavi na rogove oko žrtvenika. Tako žrtvenik očisti. Zatim izlije krv podno žrtvenika; posveti ga, izvršivši na njemu obred pomirenja.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 8, 16, 'Zatim Mojsije uzme sav loj što je bio oko drobine, privjesak s jetre, oba bubrega i njihov loj, pa to sažeže u kad na žrtveniku.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 8, 17, 'A kožu od junca, njegovo meso i njegovu nečist spali u vatri izvan tabora, kako je Jahve naredio Mojsiju.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 8, 18, 'Dovede potom ovna za žrtvu paljenicu. Aron i njegovi sinovi stave svoje ruke ovnu na glavu.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 8, 19, 'Sad ga Mojsije zakolje. Onda krvlju zapljusne žrtvenik sa svih strana.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 8, 20, 'Pošto isiječe ovna na dijelove, Mojsije sažeže u kad glavu, dijelove i loj.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 8, 21, 'U vodi opere drobinu i noge pa u kad sažeže na žrtveniku svega ovna. Bila je to žrtva paljenica na ugodan miris - žrtva u čast Jahvi paljena - kako je Jahve naredio Mojsiju.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 8, 22, 'Zatim dovede drugoga ovna, ovna za žrtvu posvetnicu. Aron i njegovi sinovi stave svoje ruke ovnu na glavu.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 8, 23, 'Mojsije ga zakolje. Onda uzme krvi pa stavi na resu Aronova desnog uha, na palac njegove desne ruke i na palac njegove desne noge.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 8, 24, 'Potom Mojsije dovede Aronove sinove, pa im stavi iste krvi na resu desnog uha, na palac desne ruke i na palac desne noge. Zatim Mojsije krvlju zapljusne žrtvenik sa svih strana.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 8, 25, 'Poslije toga uzme loj, pretili rep, loj što je bio oko drobine, privjesak s jetre, oba bubrega i njihov loj - i desno pleće;');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 8, 26, 'a iz košare beskvasnih kruhova, što je stajala pred Jahvom, uzme jednu beskvasnu pogaču, jednu prevrtu s uljem i jedan kolač i postavi ih na loj i desno pleće.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 8, 27, 'Sve to položi na ruke Arona i na ruke njegovih sinova pa to prinese kao žrtvu prikaznicu pred Jahvom.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 8, 28, 'Potom Mojsije opet to uzme s njihovih ruku i sažeže u kad na žrtveniku povrh žrtve paljenice. Bila je to žrtva posvetnica na ugodan miris, žrtva u čast Jahvi paljena.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 8, 29, 'Naposljetku Mojsije uzme grudi i prinese ih kao žrtvu prikaznicu pred Jahvom. To je bila pristojbina Mojsiju od ovna žrtve posvetnice, kako je Jahve Mojsiju naredio.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 8, 30, 'Zatim Mojsije uze ulja za pomazanje i krvi što je bila na žrtveniku te poškropi Arona i njegove haljine, a tako i njegove sinove i njihove haljine. Tako posveti Arona i njegove haljine; njegove sinove i njihove haljine.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 8, 31, 'Onda reče Mojsije Aronu i njegovim sinovima: \"Skuhajte to meso na ulazu u Šator sastanka i ondje ga blagujte s kruhom što je u košari za žrtvu posvetnicu, kako sam naredio. Neka ga jedu Aron i njegovi sinovi!');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 8, 32, 'A što od mesa i kruha ostane, spalite na vatri.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 8, 33, 'Sedam dana ne odlazite s ulaza Šatora sastanka - do dana kad se navrši rok vašega svećeničkog posvećenja. Jer sedam dana treba za vaše posvećenje.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 8, 34, 'Kako se radilo danas, Jahve je naredio da se tako radi dalje, da se nad vama izvrši obred pomirenja.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 8, 35, 'Zato ostanite na ulazu Šatora sastanka sedam dana, danju i noću vršeći što je Jahve naredio, da ne pomrete. Takvu sam ja zapovijed dobio.\"');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 8, 36, 'Aron i njegovi sinovi učiniše sve što je Jahve naredio preko Mojsija.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 9, 1, 'Osmoga dana Mojsije pozva Arona, njegove sinove i starješine Izraelove');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 9, 2, 'i reče Aronu: \"Uzmi jedno tele za žrtvu okajnicu, jednoga ovna za žrtvu paljenicu, oboje bez mane, i dovedi ih pred Jahvu.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 9, 3, 'A Izraelcima reci ovako: \'Uzmite jednoga jarca za žrtvu okajnicu, tele i janje od godine, oboje bez mane, za žrtvu paljenicu;');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 9, 4, 'a junca i ovna za žrtvu pričesnicu da žrtvujete pred Jahvom; napokon prinosnicu, s uljem zamiješenu; jer će vam se danas Jahve ukazati.\'\"');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 9, 5, 'Dovedu oni pred Šator sastanka što je Mojsije naredio; naprijed stupi sva zajednica i stane pred Jahvu.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 9, 6, '\"Ovo je zapovijed\", reče Mojsije, \"koju je Jahve izdao. Izvršite je, da vam se pokaže slava Jahvina.\"');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 9, 7, 'Zatim Mojsije reče Aronu: \"Stupi k žrtveniku, prinesi svoju žrtvu okajnicu i svoju žrtvu paljenicu i tako izvrši obred pomirenja za se i svoj dom; onda prinesi dar naroda i za nj izvrši obred pomirenja, kako je Jahve naredio.\"');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 9, 8, 'Aron se primače žrtveniku i zakla tele žrtve za svoj vlastiti grijeh.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 9, 9, 'Zatim mu Aronovi sinovi donesu krvi. On u nju zamoči svoj prst i stavi je na rogove žrtvenika. Potom ostalu krv izli podno žrtvenika.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 9, 10, 'A loj, bubrege i privjesak s jetre žrtve okajnice sažeže u kad na žrtveniku, kako je Jahve naredio Mojsiju.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 9, 11, 'Meso i kožu spali na vatri izvan tabora.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 9, 12, 'Zakolje poslije toga žrtvu paljenicu, od koje mu sinovi Aronovi pruže krv. On njome zapljusne žrtvenik sa svih strana.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 9, 13, 'Dodaju mu i žrtvu paljenicu, dio po dio, a tako i glavu, i on je sažeže u kad na žrtveniku.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 9, 14, 'Drobinu i noge opere pa i njih na žrtveniku sažeže u kad povrh žrtve paljenice.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 9, 15, 'Zatim prinese dar naroda. Uze jarca žrtve okajnice za grijehe naroda, zakla ga i prinese kao žrtvu okajnicu, isto onako kao i prijašnju.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 9, 16, 'Donese potom žrtvu paljenicu i prinese je prema propisu.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 9, 17, 'Donijevši poslije toga žrtvu prinosnicu, od nje zagrabi pregršt i sažeže na žrtveniku u kad povrh jutarnje žrtve paljenice.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 9, 18, 'Napokon zakolje junca i ovna kao žrtvu pričesnicu za narod. Aronovi mu sinovi pruže krv, a on zapljusne žrtvenik sa svih strana;');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 9, 19, 'dodaju mu i loj s junca i ovna, pretili rep, loj oko drobine, bubrege i privjesak s jetre.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 9, 20, 'Metnuvši te masne dijelove na grudi, sažga ih u kad na žrtveniku.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 9, 21, 'A grudi i desno pleće Aron prinese kao žrtvu prikaznicu pred Jahvom, kako je Mojsije naredio.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 9, 22, 'Tada Aron podiže ruke spram naroda i blagoslovi ga. Pošto prinese žrtvu okajnicu, paljenicu i pričesnicu, siđe.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 9, 23, 'Poslije toga Mojsije i Aron uđoše u Šator sastanka. Kad iziđoše, blagosloviše narod. Slava Jahvina pokaza se svemu narodu.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 9, 24, 'Ispred Jahve izbi oganj i sažga žrtvu paljenicu i masne komade na žrtveniku. A sav narod, vidjevši to, viknu od veselja i pade ničice.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 10, 1, 'A sinovi Aronovi Nadab i Abihu uzmu svaki svoj kadionik; stave u nj vatre i na nju metnu tamjana da prinesu pred Jahvom neposvećenu vatru, koju im on ne bijaše propisao.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 10, 2, 'Ali izbije plamen ispred Jahve te ih proguta - poginuše oni pred Jahvom.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 10, 3, 'Nato će Mojsije Aronu: \"To je ono što je Jahve navijestio: Po onima koji su mi blizu svetim ću se pokazati; pred svim ću se pukom proslaviti.\" Aron je šutio.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 10, 4, 'Mojsije zovnu Mišaela i Elsafana, sinove Aronova strica Uziela, pa im reče: \"Dođite i odnesite svoju braću ispred Svetišta u polje izvan tabora!\"');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 10, 5, 'Oni dođu i odnesu ih u njihovim košuljama u polje izvan tabora, kako je Mojsije rekao.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 10, 6, 'Poslije toga Mojsije reče Aronu i njegovim sinovima, Eleazaru i Itamaru: \"Ne raščupavajte svoje kose niti razdirite svojih haljina da ne poginete i da se On ne razljuti na svekoliku zajednicu. Vaša braća i sav dom Izraelov neka oplakuje one koje je vatra Jahvina sažegla.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 10, 7, 'Ne smijete odlaziti s ulaza u Šator sastanka da ne pomrete, jer na vama je Jahvino ulje pomazanja.\" Oni učine po riječi Mojsijevoj.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 10, 8, 'Jahve reče Aronu:');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 10, 9, '\"Kad ulazite u Šator sastanka, nemojte piti vina niti opojnoga pića, ni ti ni tvoji sinovi s tobom! Tako nećete poginuti. To je trajan zakon za vaše naraštaje;');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 10, 10, 'da možete lučiti posvećeno od običnoga, čisto od nečistoga;');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 10, 11, 'da možete učiti Izraelce svim zakonima što ih je Jahve predao preko Mojsija.\"');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 10, 12, 'Onda Mojsije rekne Aronu i njegovim preživjelim sinovima, Eleazaru i Itamaru: \"Uzimajte od žrtve prinosnice što preostaje nakon prinesene žrtve u čast Jahvi paljene i beskvasnu je uza žrtvenik jedite jer je vrlo sveta.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 10, 13, 'Blagujte je u svetom mjestu, jer to je - tako je meni naređeno - pristojbina tvoja i pristojbina tvojih sinova od žrtava paljenih u čast Jahvi.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 10, 14, 'A grudi žrtve prikaznice i pleće žrtve podizanice ti i tvoji sinovi i tvoje kćeri s tobom jedite na bilo kojem čistom mjestu. Jer to je dodijeljeno za pristojbinu tebi i tvojim sinovima od izraelskih žrtava pričesnica.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 10, 15, 'Pleće žrtve podizanice i grudi žrtve prikaznice što se donose zajedno s lojem, na vatri paljenim - pošto budu prineseni za žrtvu prikaznicu pred Jahvom - neka pripadnu tebi i tvojim sinovima s tobom. To je, kako je Jahve naredio, trajan zakon.\"');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 10, 16, 'Potom se Mojsije potanje raspita o jarcu žrtve okajnice. Već je bio spaljen. On se razljuti na Eleazara i Itamara, Aronove preživjele sinove, pa rekne:');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 10, 17, '\"Zašto ste jeli žrtvu okajnicu na svetome mjestu? Vrlo ja sveta! To vam je dao Jahve da uklanjate krivnju sa zajednice vršeći nad njom obred pomirenja pred Jahvom.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 10, 18, 'Budući da krv žrtve nije bila unesena unutar Svetišta, morali ste je blagovati u Svetištu, kako mi je bilo zapovjeđeno.\"');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 10, 19, 'Nato će Aron Mojsiju: \"Danas su, eto, prinijeli svoju žrtvu okajnicu i svoju žrtvu paljenicu pred Jahvom! Što bi se meni dogodilo da sam ja danas jeo od žrtve okajnice? Bi li to bilo milo Jahvi?\"');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 10, 20, 'Kad Mojsije to ču, odobri.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 11, 1, 'Jahve reče Mojsiju i Aronu:');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 11, 2, '\"Ovako kažite Izraelcima: \'Ovo su životinje koje između svih četveronožaca na zemlji možete jesti:');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 11, 3, 'svaku koja ima papke, ali papke razdvojene, i koja preživa možete jesti.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 11, 4, 'Ali ove, iako preživaju ili papke imaju, ne smijete jesti: devu, jer iako preživa, razdvojena papka nema - za vas je nečista;');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 11, 5, 'svisca, jer iako preživa, razdvojena papka nema - za vas je nečist;');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 11, 6, 'arnebeta, iako preživa, razdvojena papka nema - za vas je nečist.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 11, 7, 'A svinja, iako ima papak, i to papak razdvojen, ne preživa - za vas je nečista.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 11, 8, 'Njihova mesa nemojte jesti niti se njihove strvine doticati - za vas su one nečiste.\'\"');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 11, 9, 'Od svih vodenih životinja ove možete jesti: sve što živi u vodi, bilo u morima, bilo u rijekama, a ima peraje i ljuske možete jesti.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 11, 10, 'A što u morima i rijekama nema peraja i ljusaka - sve životinjice u vodi, sva živa vodena bića - neka su vam odvratna');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 11, 11, 'i odvratna neka vam ostanu! Mesa od njih nemojte jesti, a njihove strvine držite za odvratnost.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 11, 12, 'Sve, dakle, što je u vodi a nema peraja i ljusaka neka je za vas odvratno.\"');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 11, 13, '\"Od ptica neka su vam ove odvratne i neka se ne jedu - odvratnost su: orao, orao strvinar i jastreb,');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 11, 14, 'tetrijeb i sokol bilo koje vrste;');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 11, 15, 'gavran svih vrsta;');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 11, 16, 'noj, kobac i galeb; lastavica svake vrste;');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 11, 17, 'sova, gnjurac, ušara,');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 11, 18, 'labud, pelikan, droplja;');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 11, 19, 'roda, čaplja svake vrste; pupavac i šišmiš.\"');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 11, 20, '\"Svi krilati kukci što hodaju četveronoške neka su vam odvratni!');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 11, 21, 'Od svih tih krilatih kukaca što hodaju četveronoške možete jesti samo one koji imaju na svojim nožicama listove za skakutanje po zemlji.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 11, 22, 'Od njih možete jesti: svaku vrstu skakavaca, cvrčaka i zrikavaca.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 11, 23, 'A svi drugi krilati kukci na četiri nožice neka su vam odvratni!');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 11, 24, 'I od njih ćete se onečistiti: tko se god dotakne njihove crkotine, neka je nečist do večeri;');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 11, 25, 'tko god ponese crkotinu bilo koje od njih, neka opere svoju odjeću i nečistim se smatra do večeri;');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 11, 26, 'i životinje s nerazdvojenim papkom što ne preživaju za vas su nečiste, i tko ih se dotakne neka je nečist!');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 11, 27, 'Onda, četveronožne životinje koje hodaju na četiri šape za vas su nečiste. Tko se dotakne njihova strva, neka je nečist do večeri.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 11, 28, 'A onaj koji ponese njihov strv, neka opere svoju odjeću i bude nečist do večeri. Za vas su one nečiste.\"');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 11, 29, '\"Od životinja što po zemlji gmižu neka su za vas ove nečiste: krtica, miš i svaka vrsta guštera;');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 11, 30, 'zidni macaklin, kameleon, daždevnjak, zelembać i tinšamet.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 11, 31, 'Te su životinje od svih što gmižu za vas nečiste. Tko ih se mrtvih dotakne neka je nečist do večeri.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 11, 32, 'A na što koja od njih mrtva padne, neka je onečišćeno: bio to kakav drveni predmet ili odjeća, koža ili vreća. Svaki takav predmet koji se upotrebljava neka se zamoči u vodu i ostane nečist do večeri. Onda će postati čist.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 11, 33, 'Upadne li što od njih u kakvu zemljanu posudu, razbijte je; sve je u njoj onečišćeno.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 11, 34, 'A bilo kakva hrana što se jede, ako na nju kapne voda iz te posude, bit će onečišćena. Svaka tekućina što se pije u svakoj takvoj posudi neka se smatra nečistom.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 11, 35, 'A sve na što padne bilo što od njihove crkotine neka je nečisto; bude li to peć ili ognjište, neka se sruše: onečišćeni su za vas i neka nečisti budu.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 11, 36, 'A vrelo ili čatrnja koja drži vodu neka se smatraju čistima. Ali tko dirne strvinu životinje neka je nečist.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 11, 37, 'Ako što od njihova strva padne na žitno sjemenje što će se sijati, ono ostaje čisto;');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 11, 38, 'ali ako se sjemenje nakvasi vodom, a onda na nj padne što od njihove crkotine, neka je za vas nečisto.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 11, 39, 'Ako ugine koja životinja što vam služi za hranu, onaj koji dotakne njezinu strvinu neka je nečist do večeri;');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 11, 40, 'a koji pojede od njezine strvine neka opere svoju odjeću i bude nečist do večeri; koji ponese njezinu strvinu neka opere svoju odjeću i bude nečist do večeri.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 11, 41, 'Svaka životinja što po tlu gmiže odvratna je. Neka se ne jede!');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 11, 42, 'Ništa što puže na trbuhu, ništa što god ide na četiri noge ili na više nogu - nikakve puzavce što po tlu gmižu nemojte jesti jer su odvratni!');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 11, 43, 'Nemojte sami sebe poganiti svim tim puzavcima što gmižu; ne prljajte se njima, da i vi zbog njih ne postanete nečisti.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 11, 44, 'Ta ja - Jahve - Bog sam vaš! Posvećujte se, dakle, da sveti budete, jer svet sam ja! Nijednim se puzavcem što po tlu gmiže ne prljajte!');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 11, 45, 'Jest, ja sam Jahve; izveo sam vas iz zemlje egipatske da vam budem Bog. Budite, dakle, sveti jer sam svet ja!\"');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 11, 46, 'To je odredba koja se odnosi na ptice i sva živa bića što se u vodi kreću i na sve stvorove koji po zemlji gmižu.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 11, 47, 'Svrha joj je da se razlikuje nečisto od čistoga; životinja koja se može jesti od životinje koja se ne smije jesti.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 12, 1, 'Jahve reče Mojsiju:');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 12, 2, '\"Kaži Izraelcima: \'Kad koja žena zatrudni i rodi muško čedo, neka je nečista sedam dana, kako je nečista u vrijeme svoga mjesečnog pranja.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 12, 3, 'Osmoga dana neka se dijete obreže.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 12, 4, 'A ona neka ostane još trideset i tri dana da se očisti od svoje krvi; ne smije dirati ništa posvećeno niti dolaziti u Svetište dok se ne navrši vrijeme njezina čišćenja.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 12, 5, 'Ako rodi žensko čedo, neka je nečista dva tjedna, kao za svoga mjesečnog pranja, i neka ostane još šezdeset i šest dana da se očisti od svoje krvi.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 12, 6, 'A kad se navrši vrijeme njezina čišćenja - bilo za sinčića, bilo za kćerkicu - neka donese svećeniku na ulaz u Šator sastanka jednogodišnje janje za žrtvu paljenicu i jednoga golubića ili grlicu za žrtvu okajnicu.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 12, 7, 'Neka on to prinese pred Jahvom i nad njom izvrši obred pomirenja. Tako će ona biti očišćena od svoga krvarenja. To je odredba koja se odnosi na ženu kad rodi bilo muško bilo žensko čedo.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 12, 8, 'Ali ako ne može da nađe dovoljno sredstava za grlo od sitnoga stada, neka onda uzme dvije grlice ili dva golubića - jedno za žrtvu paljenicu, a drugo za žrtvu okajnicu. Neka svećenik izvrši nad njom obred pomirenja, i ona će biti očišćena\'.\"');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 13, 1, 'Reče Jahve Mojsiju i Aronu:');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 13, 2, '\"Ako se kome na koži pojavi oteklina ili lišaj ili bjelkasta pjega što bi bila nagovještaj gube na koži njegova tijela, neka se takav dovede svećeniku Aronu ili kojemu od njegovih sinova svećenika.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 13, 3, 'Neka svećenik pregleda zaraženo mjesto na koži njegova tijela. Ako je dlaka na zaraženom mjestu postala bijela i učini se da je ono dublje od kože njegova tijela, onda je to guba. Pošto ga svećenik pregleda, neka ga proglasi nečistim.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 13, 4, 'Ali ako se pokaže da bjelkasta pjega na koži njegova tijela nije dublja nego i koža, a dlaka na njoj nije pobijeljela, neka onda svećenik bolesnika osami sedam dana.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 13, 5, 'Neka ga sedmoga dana opet svećenik pregleda. Ako ustanovi svojim očima da zaraza još postoji, ali da se po koži dalje ne širi, neka ga osami još sedam dana.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 13, 6, 'Sedmoga dana neka ga opet pregleda. Bude li zaraženo mjesto manje upadno, a bolest se kožom ne bude proširila, neka ga proglasi čistim: to je samo lišaj. Pošto opere svoje haljine, bit će čist.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 13, 7, 'Ali ako se lišaj kožom proširi, pošto je svećenik bolesnika pregledao i proglasio ga čistim, neka se ponovo pokaže svećeniku.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 13, 8, 'Neka ga svećenik pregleda. Bude li se lišaj proširio po koži, neka ga svećenik proglasi nečistim: to je guba.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 13, 9, 'Ako se na čovjeku pokaže guba, neka ga dovedu svećeniku.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 13, 10, 'Neka ga svećenik pregleda. Ako po koži bude bjelkasta oteklina s pobijeljelom dlakom i napetim čirom,');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 13, 11, 'to je duboko ukorijenjena guba po koži njegova tijela. Neka ga svećenik proglasi nečistim. Ne treba ga osamljivati, jer je sigurno nečist.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 13, 12, 'Ako guba izbije po koži tako da bolesniku prekrije svu kožu od glave do pete - sve što svećenikove oči vide -');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 13, 13, 'neka svećenik obavi pregled. Bude li guba prekrila sve njegovo tijelo, neka ga proglasi čistim. Budući da je sav pobijelio, čist je.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 13, 14, 'Ali onog dana kad se na njemu pokaže čir, bit će nečist.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 13, 15, 'Kad svećenik vidi taj čir, neka bolesnika proglasi nečistim: čir je nečista stvar, to je guba.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 13, 16, 'Ali ako se čir promijeni u bijelo, neka čovjek dođe k svećeniku.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 13, 17, 'Svećenik neka ga pregleda. Bude li rana postala bijela, neka svećenik proglasi bolesnika čistim - čist i jest.\"');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 13, 18, '\"Kad se kome na koži napne čir i zacijeli,');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 13, 19, 'i ondje gdje je bio čir pojavi se bjelkasta oteklina ili mjesto izblijedi i postane bjelkasto, ili izbije bijelocrvenkasta pjega, neka se taj čovjek pokaže svećeniku.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 13, 20, 'Neka ga svećenik pregleda. Pronađe li da je tu koža udubljenija a dlaka pobijeljela, neka ga svećenik proglasi nečistim - to je onda guba što je izbila u čiru.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 13, 21, 'Ali ako svećenik ustanovi da tu dlaka nije pobijeljela, da koža nije udubljenija nego drugdje, da mjesto tamni, neka bolesnika osami sedam dana.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 13, 22, 'Proširi li mu se bolest po koži, neka ga svećenik proglasi nečistim - to je guba.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 13, 23, 'Ako pjega ostane na mjestu i ne proširi se, to je ožiljak od čira. Neka toga čovjeka svećenik proglasi čistim.\"');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 13, 24, '\"Kome na koži bude opeklina, pa mjesto opekline postane pjega bijelocrvenkasta ili bjelkasta,');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 13, 25, 'neka to svećenik pregleda. Ako dlaka na mjestu bude pobijeljela i učini se da je to mjesto udubljenije od kože, onda je to guba što je u opeklini izbila. Neka ga svećenik proglasi nečistim; to je guba.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 13, 26, 'Ali ako svećenik ustanovi da dlaka nije pobijeljela, da mjesto nije udubljenije od kože i da tamni, neka ga osami sedam dana.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 13, 27, 'Sedmoga dana neka ga pregleda. Ako se pjega po koži proširi, neka ga svećenik proglasi nečistim: to je guba.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 13, 28, 'Ostane li ozljeda na mjestu i proširi se po koži, to je onda oteklina od opekline. Neka čovjeka svećenik proglasi čistim: to je ožiljak od opekline.\"');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 13, 29, '\"Ako se na glavi ili na bradi kojega čovjeka ili žene pokaže bolest,');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 13, 30, 'neka svećenik bolest pregleda. Ustanovi li se da je dublje od kože i da je tu dlaka požutjela i otančala, neka bolesnika svećenik proglasi nečistim. To je šuga, to jest guba na glavi ili na bradi.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 13, 31, 'Ali ako svećenik, pregledavši oboljelo mjesto, ustanovi da nije dublje od kože, ali da tu ipak nema crne dlake, neka svećenik odstrani šugavca sedam dana.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 13, 32, 'Sedmoga dana neka ga svećenik pregleda. Ako se šuga nije proširila niti dlaka požutjela, te ako se čini da šuga nije dublja od kože,');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 13, 33, 'neka se bolesnik obrije - ali ošugano mjesto da ne brije! - i neka ga svećenik odstrani od drugih sedam dana.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 13, 34, 'Sedmoga dana neka opet svećenik pregleda šugavo mjesto. Ako se šuga kožom ne bude proširila i učini se da nije dublja od kože, neka tog bolesnika svećenik proglasi čistim. On neka opere svoju odjeću i bude čist.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 13, 35, 'Proširi li se šuga po koži pošto je bio čistim proglašen,');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 13, 36, 'neka ga svećenik ponovo pregleda. Ako se šuga kožom bude proširila - svećenik neka više i ne traži žute dlake - bolesnik ja nečist.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 13, 37, 'Ali ako opazi da je šuga stala i da je nikla crna dlaka, šuga je zacijeljela - on je čist. Neka ga svećenik proglasi čistim.\"');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 13, 38, '\"Ako se na koži kojeg čovjeka ili žene pokažu pjege te ako su te pjege bijele,');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 13, 39, 'neka ih svećenik pregleda. Ako te pjege po koži budu tamnobijele, onda je to osip što je izbio po koži: bolesnik je čist.\"');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 13, 40, '\"Ako čovjeku opadne kosa s glave, oćelavio mu je zatiljak, ali je čist.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 13, 41, 'Ako mu sprijeda opadne kosa s glave, oćelavio je na čelu, ali je čist.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 13, 42, 'Ali ako se po ćelavu zatiljku ili po oćelavljelu čelu pojavi crvenkastobijela bolest, to je guba što je izbila po njegovu ćelavom zatiljku ili oćelavljelu čelu.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 13, 43, 'Neka ga svećenik pregleda. Ako ustanovi da je osip na ćelavu zatiljku ili po oćelavljelu čelu bjelkastocrvenkast - naizgled kao i guba na koži tijela -');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 13, 44, 'čovjek se ogubavio, nečist je. Svećenik ga mora proglasiti nečistim - guba mu je na glavi.\"');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 13, 45, '\"Onaj koji se bude ogubavio, neka nosi rasparanu odjeću; kosa neka mu je raščupana; gornju usnu neka prekrije i viče: \"Nečist! Nečist!\"');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 13, 46, 'Sve dok na njemu bude bolest, neka nečistim ostane, a kako je nečist, neka stanuje nasamo: neka mu je stan izvan tabora.\"');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 13, 47, '\"Kad se zaraza gube pokaže na odijelu, bilo vunenu bilo lanenu,');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 13, 48, 'na osnovi ili na potki od lana ili vune; ili na koži; ili na bilo kakvu predmetu od kože;');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 13, 49, 'pa ako mrlja na odijelu ili koži, na osnovi ili na potki, ili na bilo kakvu predmetu od kože, bude zelenkasta ili crvenkasta, to je guba i neka se svećeniku pokaže.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 13, 50, 'Neka svećenik, pošto pregleda što je zaraženo, to stavi na osamu sedam dana.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 13, 51, 'Onda neka sedmoga dana zarazu pregleda. Ako se zaraza proširi po odijelu, po osnovi ili potki, ili po koži, ili po kakvu god predmetu od kože, to je zarazna guba. Stvar je nečista.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 13, 52, 'To odijelo - bilo osnova bilo potka, od vune ili lana - ili kakav kožni predmet za koji je zaraza prionula, gubom se zarazio; neka na vatri izgori.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 13, 53, 'Ali ako svećenik opazi da se zaraza nije proširila na odijelu - na osnovi ni na potki - niti na bilo kakvu kožnom predmetu,');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 13, 54, 'onda neka naredi da se zaražena stvar opere. Neka je zatim stavi nasamo drugih sedam dana.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 13, 55, 'A ako, pošto je stvar bila oprana, svećenik opazi da se zaraženo mjesto nije promijenilo, ipak, mada se bolest nije raširila, stvar je nečista. Neka se na vatri spali: trula je i iznutra i izvana.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 13, 56, 'Opazi li svećenik da se bolest smanjuje nakon pranja, neka to mjesto izreže, bilo ono na odijelu ili na koži, na osnovi ili na potki.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 13, 57, 'Ako se na odijelu opet pojavi, u osnovi ili potki, ili bilo kakvu kožnom predmetu, onda je to zaraza, i zaraženi predmet neka u vatri izgori.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 13, 58, 'Ako li bolest nestane s odijela - osnove ili potke - ili bilo kakva kožnoga predmeta pošto je bio opran, neka se opere opet, pa neka je čist.\"');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 13, 59, 'To su propisi za bolest gube na odijelu od vune ili lana - u osnovi ili potki - ili bilo kakvu predmetu od kože da se proglase čistim ili nečistim.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 14, 1, 'Jahve reče Mojsiju:');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 14, 2, '\"Neka ovo bude obred za gubavca na dan njegova čišćenja: neka se dovede svećeniku;');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 14, 3, 'neka svećenik iziđe iz tabora i obavi pregled. Ako ustanovi da je gubavac od gube ozdravio,');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 14, 4, 'neka naredi da se za čovjeka koji se ima čistiti uzmu dvije ptice, čiste i žive, cedrovine, grimiznog prediva i izopa.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 14, 5, 'Neka zatim svećenik naredi da se jedna ptica zakolje nad živom vodom u zemljanoj posudi.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 14, 6, 'Potom neka uzme živu pticu, a onda zajedno živu pticu, cedrovinu, grimizno predivo i izop zamoči u krv ptice što je bila zaklana povrh žive vode.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 14, 7, 'Sada neka sedam puta poškropi onoga koji se od gube čisti, a onda ga čistim proglasi. Poslije toga neka pusti živu pticu na otvorenu polju.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 14, 8, 'Onaj koji se čisti neka opere svoju odjeću, obrije sve svoje dlake i u vodi se okupa. Tako neka je čist. Poslije toga neka uđe u tabor, ali sedam dana neka stanuje izvan svoga šatora.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 14, 9, 'Sedmi dan neka obrije sve svoje dlake: kosu, bradu i obrve; neka obrije sve ostale svoje dlake. Pošto u vodi opere svoju odjeću i okupa se, neka je čist.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 14, 10, 'Osmoga dana neka uzme muško janje bez mane, jedno žensko janje od godine dana, također bez mane, tri desetine efe najboljeg brašna zamiješena u ulju za žrtvu prinosnicu i jedan log ulja.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 14, 11, 'Svećenik koji vrši čišćenje neka ih stavi pred Jahvu na ulazu u Šator sastanka s čovjekom koji se ima čistiti.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 14, 12, 'Neka zatim svećenik uzme jedno muško janje pa ga s ono ulja u logu prinese kao žrtvu naknadnicu. Neka ih prinese pred Jahvom kao žrtvu prikaznicu.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 14, 13, 'Neka janje zakolje ondje gdje se kolju žrtve okajnice i žrtve paljenice - na svetome mjestu, jer žrtva naknadnica kao i okajnica pripada svećeniku: vrlo je sveta!');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 14, 14, 'Potom neka svećenik uzme krvi od žrtve naknadnice, pa neka njome namaže resicu desnoga uha, palac desne ruke i palac desne noge onoga koji se čisti.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 14, 15, 'Poslije toga neka uzme log s uljem i izlije na dlan svoje lijeve ruke.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 14, 16, 'Zamočivši svećenik svoj desni prst u ulje na svojoj lijevoj ruci, neka uljem sa svoga prsta obavi škropljenje pred Jahvom sedam puta.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 14, 17, 'Od ulja što mu preostane u ruci neka svećenik, po krvi od žrtve naknadnice, pomaže resicu desnoga uha, palac desne ruke i palac desne noge onoga koji se čisti.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 14, 18, 'Ostatak ulja sa svoje ruke neka svećenik metne na glavu onoga koji se čisti. Tako će svećenik nad njim izvršiti obred pomirenja pred Jahvom.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 14, 19, 'Neka svećenik poslije toga prinese žrtvu okajnicu i nad onim koji se čisti neka obavi obred pomirenja za njegovu nečistoću. Napokon neka zakolje žrtvu paljenicu,');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 14, 20, 'a onda neka svećenik žrtvu paljenicu i žrtvu prinosnicu podigne na žrtvenik. Kad tako svećenik nad njim obavi obred pomirenja, neka je čist.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 14, 21, 'Ako bude siromašan te ne mogne to priskrbiti, neka uzme samo jedno muško janje za žrtvu naknadnicu i neka se ono prinese kao žrtva prinosnica da se nad tim čovjekom izvrši obred pomirenja. I neka uzme samo desetinu efe najboljeg brašna zamiješena u ulju za žrtvu prinosnicu, jedan log ulja,');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 14, 22, 'k tome dvije grlice ili dva golubića - prema svojim mogućnostima - jedno za žrtvu okajnicu, a drugo za žrtvu paljenicu.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 14, 23, 'Osam dana nakon svoga očišćenja neka ih donese svećeniku na ulaz u Šator sastanka pred Jahvu.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 14, 24, 'Neka svećenik uzme janje za žrtvu naknadnicu i log s uljem pa ih prinese pred Jahvom kao žrtvu prikaznicu.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 14, 25, 'Neka se onda zakolje janje žrtve naknadnice, a svećenik neka uzme njegove krvi i neka njome namaže resicu desnoga uha, palac desne ruke i palac desne noge onoga koji se čisti.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 14, 26, 'Poslije toga neka svećenik izlije ulje na dlan svoje lijeve ruke.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 14, 27, 'A onda neka od ulja što mu je na dlanu lijeve ruke obavi škropljenje sedam puta prstom svoje desne ruke pred Jahvom.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 14, 28, 'Od ulja iz svoje ruke neka svećenik, po krvi žrtve naknadnice, namaže resicu desnog uha, palac desne ruke i palac desne noge onoga koji se čisti.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 14, 29, 'Ostatak ulja što bude na dlanu neka svećenik stavi na glavu onoga koji se čisti, vršeći nad njim obred pomirenja pred Jahvom.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 14, 30, 'Neka zatim prinese jednu od dviju grlica ili jednoga od dvaju golubića - što je već mogao pribaviti -');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 14, 31, 'kao žrtvu okajnicu, a drugu kao žrtvu paljenicu zajedno sa žrtvom prinosnicom. Neka tako svećenik izvrši obred pomirenja pred Jahvom nad onim koji se čisti.\"');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 14, 32, 'To je propis za onoga koji je gubom zaražen a ne može priskrbiti sve za svoje očišćenje.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 14, 33, 'Jahve reče Mojsiju i Aronu:');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 14, 34, '\"Kad uđete u kanaansku zemlju koju ću vam dati u posjed, a ja pustim gubu na koju kuću u zemlji što je budete zaposjeli,');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 14, 35, 'onda onaj čija je kuća neka dođe svećeniku i kaže: \'Čini mi se da je moja kuća zaražena gubom.\'');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 14, 36, 'Neka svećenik naredi da se kuća isprazni prije nego on dođe da bolest pregleda, da ne bi sve što je u kući bilo proglašeno nečistim; poslije toga neka svećenik uđe da kuću pregleda.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 14, 37, 'Ako nakon pregleda zapazi da je bolest na kućnim zidovima od zelenkastih ili crvenkastih udubina i pričini mu se da idu dublje od površine zida,');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 14, 38, 'neka svećenik iziđe iz kuće na kućna vrata i neka kuću zatvori sedam dana.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 14, 39, 'Sedmi dan neka svećenik opet dođe i pregleda: ako se bolest bude proširila po zidovima kuće,');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 14, 40, 'neka svećenik naredi da se povadi zaraženo kamenje i baci na koje nečisto mjesto izvan grada.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 14, 41, 'Zatim neka zapovjedi da se svi unutarnji zidovi kuće ostružu i da se sastrugani prah baci na koje nečisto mjesto izvan grada.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 14, 42, 'Onda neka se uzme drugo kamenje i umetne namjesto onoga kamenja. Potom neka se uzme druga žbuka i kuća ponovo ožbuka.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 14, 43, 'Ako se pošast na kući opet pojavi pošto je kamenje bilo povađeno i kuća ostrugana i opet ožbukana,');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 14, 44, 'neka svećenik ode da pregleda: bude li se bolest po kući proširila, to je onda u kući zarazna guba; kuća je nečista.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 14, 45, 'Neka se kuća poruši, a njezino kamenje, njezina drvena građa i sva žbuka s kuće neka se odnese izvan grada na koje nečisto mjesto.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 14, 46, 'Tko uđe u kuću dok je zatvorena, neka je nečist do večeri.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 14, 47, 'Tko u kući legne, mora oprati svoju odjeću. I tko u kući objeduje, mora svoju odjeću oprati.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 14, 48, 'Ako li svećenik dođe i vidi da se bolest po kući nije proširila pošto je kuća opet bila ožbukana, neka svećenik kuću proglasi čistom, jer se bolest izliječila.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 14, 49, 'A za očišćenje kuće neka uzme: dvije ptice, cedrovine, grimizna prediva i izopa.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 14, 50, 'Jednu od ptica neka zakolje nad živom vodom u zemljanoj posudi.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 14, 51, 'Potom neka uzme: cedrovinu, izop, grimizno predivo i pticu živu te ih zamoči u krv ptice zaklane i u živu vodu pa kuću poškropi sedam puta.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 14, 52, 'Očistivši tako od grijeha kuću krvlju ptice, živom vodom, živom pticom, cedrovinom, izopom i grimiznim predivom,');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 14, 53, 'neka pticu živu pusti izvan grada na otvorenu polju. Kad tako obavi obred pomirenja nad kućom, bit će čista.\"');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 14, 54, 'To je propis za svaku vrst gube i šuge,');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 14, 55, 'za gubu odjeće ili kuće,');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 14, 56, 'za otekline, lišaje ili pjege.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 14, 57, 'On određuje vrijeme nečistoće i čistoće. To je zakon o gubi.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 15, 1, 'Jahve reče Mojsiju i Aronu:');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 15, 2, '\"Govorite Izraelcima i kažite im: \'Kad koji čovjek imadne izljev iz svoga tijela, njegov je izljev nečist.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 15, 3, 'Evo u čemu je njegova nečistoća ako ima taj izljev: ispusti li njegovo tijelo izljev ili ga zadrži, on je nečist.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 15, 4, 'Svaka postelja na koju legne onaj koji ima izljev neka je nečista; i svaki predmet na koji sjedne neka je nečist.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 15, 5, 'A svaki koji se dotakne njegove posteljine neka opere svoju odjeću, u vodi se okupa i nečistim ostane do večeri.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 15, 6, 'Tko god sjedne na predmet na kojemu je sjedio onaj koji je imao izljev neka opere svoju odjeću, u vodi se okupa i nečistim ostane do večeri.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 15, 7, 'Tko se dotakne tijela onoga koji je imao izljev neka opere svoju odjeću, u vodi se okupa i do večeri nečistim ostane.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 15, 8, 'Ako onaj koji ima izljev pljune na koga tko je čist neka taj opere svoju odjeću, u vodi se okupa i nečistim ostane do večeri.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 15, 9, 'Neka je nečisto i svako sjedalo na koje za vožnje sjedne onaj koji ima izljev;');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 15, 10, 'i tko se dotakne čega što je pod tim bolesnikom bilo neka je nečist do večeri. Tko ponese štogod takvo neka svoju odjeću opere, u vodi se okupa i ostane nečistim do večeri.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 15, 11, 'A svaki koga se onaj koji ima izljev dotakne neopranih ruku neka svoju odjeću opere, u vodi se okupa i ostane nečistim do večeri.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 15, 12, 'Zemljana posuda koje se dotakne onaj s izljevom neka se razbije, a svaki drveni sud neka se vodom ispere.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 15, 13, 'Kad se onaj koji ima izljev od toga izliječi, neka onda nabroji sedam dana za svoje oćišćenje; neka opere svoju odjeću, okupa se u živoj vodi i neka je čist.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 15, 14, 'Osmoga pak dana neka uzme dvije grlice ili dva golubića, dođe pred Jahvu na ulaz u Šator sastanka pa ih svećeniku preda.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 15, 15, 'Neka ih svećenik prinese jedno kao žrtvu okajnicu, a drugo kao žrtvu paljenicu. Time će svećenik izvršiti obred pomirenja nad tim čovjekom za njegov izljev.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 15, 16, 'Kad čovjek imadne sjemeni izljev, neka u vodi okupa cijelo svoje tijelo i ostane nečistim do večeri.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 15, 17, 'Svaka haljina i svaka koža na koju dospije takav sjemeni izljev neka se u vodi opere i ostane nečistom do večeri.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 15, 18, 'Ako koja žena legne s kojim čovjekom i on ispusti sjeme, neka se okupaju u vodi i budu nečisti do večeri\'.\"');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 15, 19, '\"Kad žena imadne krvarenje, izljev krvi iz svoga tijela, neka ostane u svojoj nečistoći sedam dana; tko se god nje dotakne neka je nečist do večeri.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 15, 20, 'Na što god bi legla za svoje nečistoće neka je nečisto; na što god sjedne neka je nečisto.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 15, 21, 'Tko se dotakne njezine posteljine neka opere svoju odjeću, u vodi se okupa i do večeri ostane nečistim.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 15, 22, 'Tko god dotakne bilo koji predmet na kojemu je ona sjedila neka svoju odjeću opere, u vodi se okupa i nečist ostane do večeri.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 15, 23, 'A ako bi se dotakao čega što je bilo na njezinoj postelji ili na predmetu na kojem je ona sjedila, neka je nečist do večeri.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 15, 24, 'Ako koji čovjek s njom legne, njezina nečistoća za nj prianja, pa neka je nečist sedam dana. Svaka postelja na koju on legne neka je nečista.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 15, 25, 'Ako žena imadne krvarenje dulje vremena izvan svoga mjesečnog pranja, ili ako se njezino mjesečno pranje produžuje, neka se smatra nečistom sve vrijeme krvarenja kao da su dani njezina mjesečnog pranja.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 15, 26, 'Svaka postelja na koju legne za sve vrijeme svoga krvarenja bit će joj kao i postelja za njezina mjesečnog pranja. I svaki predmet na koji sjedne neka postane nečistim kao što bi bio nečist u vrijeme njezina mjesečnog pranja.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 15, 27, 'A svatko tko ih se dotakne neka je nečist; neka opere svoju odjeću, okupa se u vodi i ostane nečistim do večeri.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 15, 28, 'Ako ozdravi od svog krvarenja, neka namiri sedam dana, a poslije toga neka je čista.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 15, 29, 'Osmoga dana neka uzme dvije grlice ili dva golubića te ih donese svećeniku na ulaz u Šator sastanka.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 15, 30, 'Neka jedno svećenik prinese kao žrtvu okajnicu, a drugo kao žrtvu paljenicu. Tako će svećenik obaviti pred Jahvom obred pomirenja nad njom, za njezino nečisto krvarenje.\"');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 15, 31, '\"Odvraćajte Izraelce od njihovih nečistoća, da ne bi zbog njih pomrli oskvrnjujući moje Prebivalište koje se nalazi među njima.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 15, 32, 'To je propis za čovjeka koji ima izljev; za onoga koga čini nečistim sjemeni izljev;');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 15, 33, 'za ženu u vrijeme nečistoće njezina mjesečnog pranja; za svakoga - bilo muško bilo žensko - tko imadne izljev, a tako i za čovjeka koji legne s onečišćenom ženom.\"');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 16, 1, 'Poslije smrti dvojice Aronovih sinova, koji su poginuli prinoseći pred Jahvom neposvećenu vatru, progovori Jahve Mojsiju.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 16, 2, 'Jahve reče Mojsiju: \"Kaži svome bratu Aronu da ne ulazi u svako doba u Svetište iza zavjese, pred Pomirilište koje se nalazi na Kovčegu, da ne pogine. Jer ja ću se pojavljivati nad Pomirilištem u oblaku.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 16, 3, 'Neka Aron ulazi u Svetište ovako: s juncem za žrtvu okajnicu i ovnom za žrtvu paljenicu.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 16, 4, 'Neka se obuče u posvećenu košulju od lana; na svoje tijelo neka navuče gaće od lana; neka se opaše lanenim pasom, a na glavu stavi mitru od lana. To je posvećeno ruho koje ima obući pošto se okupa u vodi.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 16, 5, 'Od zajednice izraelske neka primi dva jarca za žrtvu okajnicu i jednoga ovna za žrtvu paljenicu.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 16, 6, 'Pošto Aron prinese junca za žrtvu okajnicu za svoj grijeh i izvrši obred pomirenja za se i za svoj dom,');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 16, 7, 'neka uzme oba jarca i postavi ih pred Jahvu na ulaz u Šator sastanka.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 16, 8, 'Neka Aron baci kocke za oba jarca te jednoga odredi kockom Jahvi, a drugoga Azazelu.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 16, 9, 'Jarca na kojega je kocka pala da bude Jahvi neka Aron prinese za žrtvu okajnicu.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 16, 10, 'A jarac na kojega je kocka pala da bude Azazelu neka se smjesti živ pred Jahvu, da se nad njim obavi obred pomirenja i otpremi Azazelu u pustinju.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 16, 11, 'Zatim neka Aron prinese junca za žrtvu okajnicu za svoj grijeh; i obavi obred pomirenja za se i za svoj dom: i neka zakolje toga junca za žrtvu okajnicu za svoj grijeh.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 16, 12, 'Potom neka uzme kadionik pun užarena ugljevlja sa žrtvenika ispred Jahve i dvije pune pregršti miomirisnoga tamjana u prah smrvljenoga. Neka to unese iza zavjese.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 16, 13, 'Sad neka stavi tamjan na vatru pred Jahvom da oblak od tamjana zastre Pomirilište što je na Svjedočanstvu. Tako neće poginuti.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 16, 14, 'Poslije toga neka uzme krvi od junca i svojim prstom poškropi istočnu stranu Pomirilišta; a ispred Pomirilišta neka svojim prstom poškropi sedam puta tom krvlju.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 16, 15, 'Neka potom zakolje jarca za žrtvu okajnicu za grijeh naroda; neka unese njegovu krv za zavjesu te s njegovom krvi učini kako je učinio s krvlju od junca: neka njome poškropi po Pomirilištu i pred njim.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 16, 16, 'Tako će obaviti obred pomirenja nad Svetištem zbog nečistoća Izraelaca, zbog njihovih prijestupa i svih njihovih grijeha. A tako neka učini i za Šator sastanka što se među njima nalazi, sred njihovih nečistoća.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 16, 17, 'Kad on uđe da obavi obred pomirenja u Svetištu, neka nikoga drugog ne bude u Šatoru sastanka dok on ne iziđe. Obavivši obred pomirenja za se, za svoj dom i za svu izraelsku zajednicu,');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 16, 18, 'neka ode k žrtveniku koji se nalazi pred Jahvom te nad žrtvenikom obavi obred pomirenja. Neka uzme krvi od junca i krvi od jarca pa stavi na rogove oko žrtvenika.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 16, 19, 'Neka svojim prstom poškropi žrtvenik istom krvlju sedam puta. Tako će ga očistiti od nečistoća Izraelaca i posvetiti.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 16, 20, 'Kad svrši obred pomirenja Svetišta, Šatora sastanka i žrtvenika, neka primakne jarca živoga.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 16, 21, 'Neka mu na glavu Aron stavi obje svoje ruke i nad njim ispovjedi sve krivnje Izraelaca, sve njihove prijestupe i sve njihove grijehe. Položivši ih tako jarcu na glavu, neka ga pošalje u pustinju s jednim prikladnim čovjekom.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 16, 22, 'Tako će jarac na sebi odnijeti sve njihove krivnje u pusti kraj. Otpremivši jarca u pustinju,');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 16, 23, 'neka se Aron vrati u Šator sastanka, sa sebe svuče lanenu odjeću u koju se bio obukao kad je ulazio u Svetište i neka je ondje ostavi.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 16, 24, 'Neka potom opere svoje tijelo vodom na posvećenu mjestu, na se obuče svoju odjeću te iziđe da prinese svoju žrtvu paljenicu i žrtvu paljenicu naroda i obavi obred pomirenja za se i za narod.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 16, 25, 'Loj sa žrtve okajnice neka sažeže u kad na žrtveniku.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 16, 26, 'Onaj koji je odveo jarca Azazelu neka opere svoju odjeću, svoje tijelo u vodi okupa i poslije toga može opet doći u tabor.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 16, 27, 'A junca žrtve okajnice i jarca žrtve okajnice od kojih je krv bila donesena u Svetište da se obavi obred pomirenja neka odnesu izvan tabora pa neka na vatri spale njihove kože, njihovo meso i njihovu nečist.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 16, 28, 'Tko ih bude spaljivao, neka opere svoju odjeću, svoje tijelo okupa u vodi i poslije toga može opet doći u tabor.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 16, 29, 'Ovaj zakon neka za vas trajno vrijedi. U sedmom mjesecu, deseti dan toga mjeseca, postite i ne obavljajte nikakva posla: ni domorodac ni stranac koji među vama boravi.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 16, 30, 'Jer toga dana nad vama se ima izvršiti obred pomirenja da se očistite od svih svojih grijeha te da pred Jahvom budete čisti.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 16, 31, 'Neka je to za vas subotnji počinak kad postite. Trajan je to zakon.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 16, 32, 'Neka obred pomirenja obavi onaj svećenik koji bude pomazan i posvećen za vršenje svećeničke službe namjesto svoga oca. Neka se obuče u posvećeno laneno ruho;');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 16, 33, 'on neka obavi obred pomirenja za posvećeno Svetište, za Šator sastanka i za žrtvenik. Zatim neka izvrši obred pomirenja nad svećenicima i nad svim narodom zajednice.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 16, 34, 'Tako neka to bude za vas trajan zakon; jednom na godinu neka se nad Izraelcima obavi obred pomirenja za sve njihove grijehe.\" Mojsije je učinio kako mu je Jahve naredio.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 17, 1, 'Jahve reče Mojsiju:');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 17, 2, '\"Govori Aronu, njegovim sinovima i svima Izraelcima te im reci: \'Evo što je zapovjedio Jahve:');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 17, 3, 'svaki onaj od Izraelova doma koji u taboru ili izvan tabora zakolje vola, ili ovcu, ili kozu,');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 17, 4, 'a ne donese ih na ulaz u Šator sastanka da se prinesu na dar Jahvi pred njegovim Prebivalištem, svaki takav neka je odgovoran: prolio je krv i neka se odstrani iz svoga naroda.\'');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 17, 5, 'Zato neka Izraelci svoje žrtve koje bi htjeli klati vani u polju dovedu na ulaz u Šator sastanka, k svećeniku, i neka ih prinose kao žrtve pričesnice.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 17, 6, 'Neka svećenik izlije krv po Jahvinu žrtveniku koji se nalazi na ulazu u Šator sastanka, a loj spali na ugodan miris Jahvi,');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 17, 7, 'tako da ubuduće ne prinose svojih žrtava klanica jarcima s kojima se odaju bludu. Neka je ovo trajan zakon za njih i njihove naraštaje.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 17, 8, 'I kaži im: \'Svaki pojedinac od Izraelova doma, ili stranac koji među vama boravi, koji prinese paljenicu ili klanicu');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 17, 9, 'a ne donese je na ulaz u Šator sastanka da se prinese Jahvi, taj neka se odstrani iz svoga naroda.\'\"');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 17, 10, '\"Nadalje, protiv svakoga pojedinca od Izraelova doma, a tako i protiv svakoga pridošlice među vama koji bi blagovao bilo kakvu krv, ja ću se okrenuti, svakoga tko blaguje krv odstranit ću iz njegova naroda.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 17, 11, 'Jer je život živoga bića u krvi. Tu krv ja sam vama dao da na žrtveniku njome obavljate obred pomirenja za svoje živote. Jer krv je ono što ispašta za život.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 17, 12, 'Zato sam kazao Izraelcima: neka nitko od vas ne jede krvi; neka ni stranac koji među vama bude ne jede krvi.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 17, 13, 'Tko god, Izraelac ili stranac koji među vama boravi, uhvati u lovu kakvu zvijer ili pticu što se može jesti neka joj prolije krv i zatrpa zemljom.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 17, 14, 'Jer život svakoga živog bića jest njegova krv. Zato sam i rekao Izraelcima: ne smijete jesti krvi ni od kakva živog bića, jer život svakoga živog bića jest njegova krv. Tko god je bude jeo, neka se odstrani.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 17, 15, 'Tko bi god, Izraelac ili stranac, jeo što je uginulo ili što su zvijeri rastrgale neka opere svoju odjeću, u vodi se okupa i ostane nečistim do večeri. Tada će postati čist.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 17, 16, 'Ali ako je ne opere i ne okupa svoga tijela, neka snosi posljedice svoje krivnje.\"');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 18, 1, 'Jahve reče Mojsiju:');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 18, 2, '\"Govori Izraelcima i reci im: \'Ja sam Jahve, Bog vaš.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 18, 3, 'Nemojte raditi kako se radi u zemlji egipatskoj, gdje ste boravili; niti radite kako se radi u zemlji kanaanskoj, kamo vas vodim; ne povodite se za njihovim običajima!');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 18, 4, 'Vršite moje naredbe; vršite moje zapovijedi; prema njima hodite. Ja sam Jahve, Bog vaš.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 18, 5, 'Zato držite moje zakone i moje naredbe; tko ih vrši - u njima će naći život. Ja sam Jahve!');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 18, 6, 'Neka se nitko od vas ne približuje svojoj krvnoj rodbini da otkriva njezinu golotinju. Ja sam Jahve!');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 18, 7, 'Ne otkrivaj golotinje svoga oca ni golotinje svoje majke. Majka ti je, ne otkrivaj njezine golotinje!');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 18, 8, 'Ne otkrivaj golotinje žene svoga oca! I to je golotinja tvoga oca!');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 18, 9, 'Ne otkrivaj golotinje svoje sestre - kćeri svoga oca ili kćeri svoje majke - bila rođena u kući ili izvan nje!');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 18, 10, 'Ne otkrivaj golotinje kćeri svoga sina niti golotinje kćeri svoje kćeri! TÓa njihova je golotinja tvoja vlastita golotinja.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 18, 11, 'Ne otkrivaj golotinje kćeri žene svoga oca! Jer, rođena od tvog oca, ona ti je sestra.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 18, 12, 'Ne otkrivaj golotinje sestre svoga oca! Ona je krv tvoga oca.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 18, 13, 'Ne otkrivaj ni golotinje sestre svoje majke! Ta i ona je krv tvoje majke!');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 18, 14, 'Ne otkrivaj golotinje svoga strica! To jest, nemoj se približavati njegovoj ženi. Ta ona je tvoja strina.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 18, 15, 'Ne otkrivaj golotinje svoje snahe! Ona je žena tvoga sina. Ne otkrivaj golotinje njezine.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 18, 16, 'Ne otkrivaj golotinje žene svoga brata! Ta to je golotinja tvoga brata.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 18, 17, 'Ne otkrivaj golotinje koje žene i njezine kćeri! Nemoj se ženiti kćerju njezina sina niti kćerju njezine kćeri te im golotinju otkrivati. Oni su krvna rodbina. To bi bila pokvarenost.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 18, 18, 'Ne uzimaj sebi koju ženu u isto vrijeme kad i njezinu sestru da je ljubomorom žalostiš otkrivajući golotinju ovoj preko nje za njezina života!');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 18, 19, 'Ne približuj se ni jednoj ženi kad je u nečistoći svoga mjesečnog pranja da joj otkrivaš golotinju!');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 18, 20, 'Ne lijegaj sa ženom bližnjega svoga; od nje bi postao nečist.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 18, 21, 'Ne smiješ dopuštati da koje tvoje dijete bude žrtvovano Moleku; ne smiješ tako obeščašćivati ime Boga svoga. Ja sam Jahve!');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 18, 22, 'Ne lijegaj s muškarcem kako se liježe sa ženom! To bi bila grozota.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 18, 23, 'Da nisi legao ni s jednom životinjom - od nje bi postao nečist. Žena ne smije stati pred životinju da se s njom pari. To bi bila krajnja opačina.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 18, 24, 'Ničim se od toga nemojte onečišćavati! Ta svim su se tim onečišćavali narodi koje ja ispred vas tjeram.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 18, 25, 'I zemlja je postala nečista. Zato ću kazniti njezinu opačinu, i zemlja će ispljuvati svoje stanovnike.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 18, 26, 'Vi pak držite moje zakone i moje naredbe: ni jedne od tih opačina nemojte počinjati - ni vi ni stranac koji među vama boravi.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 18, 27, 'Sve je te zloće počinjao svijet koji je bio u toj zemlji prije vas te je zemlja postala nečista.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 18, 28, 'Neće li, ako je učinite nečistom, zemlja ispljuvati i vas kako je ispljuvala narod koji je bio prije vas?');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 18, 29, 'Jest, svi koji bi počinili bilo koju od tih zloća bit će odstranjeni iz svoga naroda.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 18, 30, 'Zato držite moje zapovijedi; nemojte se podavati ni jednome od onih odvratnih običaja što su se održavali prije vas; tako se njima nećete onečistiti. Ja sam Jahve, Bog vaš!\'\"');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 19, 1, 'Jahve reče Mojsiju:');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 19, 2, '\"Govori svoj zajednici Izraelaca i reci im: \'Sveti budite! Jer sam svet ja, Jahve, Bog vaš!');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 19, 3, 'Svoje se majke i svoga oca svaki bojte! Subote moje držite! Ja sam Jahve, Bog vaš!');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 19, 4, 'Ne obraćajte se na ništavila! Ne pravite sebi lijevanih kumira! Ja sam Jahve, Bog vaš!');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 19, 5, 'Kad prinosite Jahvi žrtvu pričesnicu, prinesite je tako da budete primljeni.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 19, 6, 'Neka se pojede na dan kad je prinosite ili sutradan. Što preostane za prekosutra neka se spali na vatri.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 19, 7, 'Kad bi se jelo od toga jela treći dan, bilo bi odvratno i žrtva ne bi bila primljena.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 19, 8, 'A onaj koji je ipak jede neka snosi posljedice svoje krivnje. Budući da je oskvrnuo ono što je Jahvi posvećeno, neka se takav odstrani iz svoga naroda.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 19, 9, 'Kad žetvu žanjete po svojoj zemlji, ne žanjite dokraja svoje njive; niti pabirčite ostatke poslije svoje žetve.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 19, 10, 'Ne paljetkuj svoga vinograda; ne kupi po svom vinogradu palih boba nego ih ostavljaj sirotinji i strancu! Ja sam Jahve, Bog vaš.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 19, 11, 'Nemojte krasti; nemojte lagati i varati svoga bližnjega.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 19, 12, 'Nemojte se krivo kleti mojim imenom i tako oskvrnjivati ime svoga Boga. Ja sam Jahve!');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 19, 13, 'Ne iskorišćuj svoga bližnjega niti ga pljačkaj! Radnikova zarada neka ne ostane pri tebi do jutra.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 19, 14, 'Nemoj psovati gluhoga niti pred slijepca stavljaj zapreku. Svoga se Boga boj! Ja sam Jahve!');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 19, 15, 'Ne počinjajte nepravde u osudama! Ne budi pristran prema neznatnome, niti popuštaj pred velikima; po pravdi sudi svome bližnjemu!');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 19, 16, 'Ne raznosi klevete među svojim narodom; ne izvrgavaj pogibli krv svoga bližnjega. Ja sam Jahve!');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 19, 17, 'Ne mrzi svoga brata u svom srcu! Dužnost ti je koriti svoga sunarodnjaka. Tako nećeš pasti u grijeh zbog njega.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 19, 18, 'Ne osvećuj se! Ne gaji srdžbe prema sinovima svoga naroda. Ljubi bližnjega svoga kao samoga sebe. Ja sam Jahve!');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 19, 19, 'Držite moje zapovijedi! Ne daj svome blagu da se pari s drugom vrstom. Svoga polja ne zasijavaj dvjema vrstama sjemena. Ne stavljaj na se odjeće od dvije vrste tkanine.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 19, 20, 'Ako bi tko legao s ropkinjom koja je zaručena za drugoga, a ona ne bude ni otkupljena ni oslobođena, treba ga kazniti, ali ne smrću, jer ona nije slobodna.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 19, 21, 'Neka on na ulazu u Šator sastanka prinese Jahvi žrtvu naknadnicu, to jest jednoga ovna kao žrtvu naknadnicu.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 19, 22, 'Neka svećenik tim ovnom žrtve naknadnice izvrši nad tim čovjekom obred pomirenja pred Jahvom za počinjeni grijeh. I grijeh koji je počinio bit će mu oprošten.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 19, 23, 'Kad uđete u zemlju i zasadite bilo kakvu voćku, smatrajte njezine plodove za neobrezane. Tri godine neka vam budu neobrezani: neka se ne jedu.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 19, 24, 'Četvrte godine neka se svi njezini plodovi posvete na svetkovinu zahvale Jahvi.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 19, 25, 'Istom pete godine jedite njezin plod i ubirite sebi njezin urod. Ja sam Jahve, Bog vaš!');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 19, 26, 'Ništa s krvlju nemojte jesti! Ne gatajte! Ne čarajte!');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 19, 27, 'Ne zaokružujte kose na svojim sljepoočnicama; ne šišajte okrajka svoje brade.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 19, 28, 'Ne urezujte zareza na svome tijelu za pokojnika; niti na sebi usijecajte kakvih biljega. Ja sam Jahve!');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 19, 29, 'Ne obeščašćuj svoje kćeri dajući je za javnu bludnicu. Tako se zemlja neće podati bludnosti niti će se napuniti pokvarenošću.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 19, 30, 'Držite moje subote; štujte moje Svetište. Ja sam Jahve!');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 19, 31, 'Ne obraćajte se na zazivače duhova i vračare; ne pitajte ih za savjet. Oni bi vas opoganili. Ja sam Jahve, Bog vaš!');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 19, 32, 'Ustani pred sijedom glavom; poštuj lice starca; boj se svoga Boga. Ja sam Jahve!');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 19, 33, 'Ako se stranac nastani u vašoj zemlji, nemojte ga ugnjetavati.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 19, 34, 'Stranac koji s vama boravi neka vam bude kao sunarodnjak; ljubi ga kao sebe samoga. TÓa i vi ste bili stranci u egipatskoj zemlji. Ja sam Jahve, Bog vaš.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 19, 35, 'Ne počinjajte nepravde u osudama, u mjerama za duljinu, težinu i obujam.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 19, 36, 'Neka su vam mjerila točna; utezi jednaki; efa prava; prav hin. Ja sam Jahve, Bog vaš, koji sam vas izveo iz zemlje egipatske.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 19, 37, 'Držite sve moje zakone i sve moje naredbe; vršite ih. Ja sam Jahve!\'\"');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 20, 1, 'Jahve reče Mojsiju:');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 20, 2, '\"Kaži Izraelcima: \'Tko god, Izraelac, ili stranac koji živi s Izraelcima, ustupi svoje čedo Moleku, mora se smaknuti; narod zemlje neka ga kamenuje.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 20, 3, 'Ja ću se okrenuti protiv toga čovjeka i odstraniti ga iz njegova naroda, jer je on, ustupivši svoje čedo Moleku, okaljao moje Svetište i obeščastio moje sveto ime.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 20, 4, 'A ako narod zatvori svoje oči nad tim čovjekom kad svoje čedo ustupi Moleku te ga ne smakne,');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 20, 5, 'ja ću se suprotstaviti tome čovjeku i njegovoj obitelji; odstranit ću ih iz njihova naroda, njega i sve koji poslije njega pođu za Molekom da se podaju bludu s Molekom.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 20, 6, 'Ako se tko obrati na zazivače duhova i vračare da se za njima poda javnom bludu, ja ću se okrenuti protiv takva čovjeka i odstranit ću ga iz njegova naroda.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 20, 7, 'Posvećujte se da budete sveti! TÓa ja sam Jahve, Bog vaš.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 20, 8, 'Držite moje zakone i vršite ih. Ja, Jahve, posvećujem vas\'.\"');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 20, 9, '\"Tko god prokune svoga oca i svoju majku, neka se smakne. Jer je oca svoga i majku svoju prokleo, neka njegova krv padne na nj.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 20, 10, 'Čovjek koji počini preljub sa ženom svoga susjeda neka se kazni smrću - i preljubnik i preljubnica.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 20, 11, 'Čovjek koji bi legao sa ženom svoga oca - otkrio bi golotinju svoga oca - neka se oboje kazne smrću, krv njihova neka padne na njih.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 20, 12, 'Legne li tko sa svojom snahom, neka se oboje kazne smrću. Učinili su rodoskvrnuće i neka krv njihova padne na njih.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 20, 13, 'Ako bi muškarac legao s muškarcem kao što se liježe sa ženom, obojica bi počinila odvratno djelo. Neka se smaknu i krv njihova neka padne na njih.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 20, 14, 'Čovjek koji se oženi kćerju i njezinom majkom - krajnja je to pokvarenost! - neka se u vatri spali i on i one, da među vama ne bude pokvarenosti.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 20, 15, 'Čovjek koji bi spolno općio sa životinjom ima se smaknuti. Životinju ubijte!');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 20, 16, 'Ako bi se žena primakla bilo kakvoj životinji da se s njom pari, ubij i ženu i životinju. Neka se smaknu i njihova krv neka padne na njih.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 20, 17, 'Čovjek koji bi se oženio svojom sestrom, kćerju svoga oca ili kćerju svoje majke te vidio njezinu golotinju, a ona vidjela njegovu - pogrdno je to djelo! - neka se istrijebe pred očima naroda. Otkrio je golotinju svoje sestre, pa neka snosi i posljedice svoje krivnje.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 20, 18, 'Čovjek koji bi legao sa ženom za njezina mjesečnog pranja te otkrio njezinu golotinju - razgolio izvor njezine krvi i ona sama otkrila izvor svoje krvi - neka se oboje odstrane iz svoga naroda.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 20, 19, 'Ne otkrivaj golotinje sestre svoje majke niti sestre svoga oca - to je otkrivanje golotinje svoga roda, neka snose posljedice svoje krivnje.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 20, 20, 'Čovjek koji bi legao sa svojom strinom otkrio bi golotinju svoga strica. Neka snose posljedice svoga grijeha: neka umru bez poroda.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 20, 21, 'Čovjek koji bi se oženio ženom svoga brata - golotinju bi svoga brata otkrio - i to je nečisto. Neka ostanu bez poroda.\"');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 20, 22, '\"Zato držite sve moje zakone, sve moje naredbe i vršite ih da vas ne ispljune zemlja u koju vas vodim da se u njoj nastanite.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 20, 23, 'Nemojte živjeti po zakonima naroda koje ja ispred vas tjeram. TÓa oni su činili sve to, i zato mi se zgadili.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 20, 24, 'A vama sam ja rekao: vi ćete zaposjesti njihovu zemlju; vama ću je predati u posjed - zemlju kojom teče mlijeko i med. Ja sam Jahve, vaš Bog, koji sam vas odvojio od tih naroda.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 20, 25, 'Pravite, dakle, razliku između čiste životinje i nečiste; između čiste ptice i nečiste. Nemojte sami sebe opoganjivati ni životinjom, ni pticom, ni bilo čim što zemljom puže: što sam vam ja odlučio kao nečisto.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 20, 26, 'Budite mi dakle sveti, jer sam ja, Jahve, svet; ja sam vas odvojio od tih naroda da budete moji.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 20, 27, 'Čovjek ili žena koji među vama postanu zazivači duhova ili vračari neka se kazne smrću; neka se kamenuju i neka njihova krv padne na njih.\"');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 21, 1, 'Jahve još reče Mojsiju: \"Govori svećenicima, Aronovim sinovima, i reci im: Neka se nitko ne okalja dodirom pokojnika u svome narodu,');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 21, 2, 'osim svoje najbliže rodbine: svoje majke, svoga oca, svoga sina, svoje kćeri i svojega brata.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 21, 3, 'I svojom sestrom, djevicom, koja mu je također najbliža, jer nije bila udata, može se okaljati.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 21, 4, 'Ali neka se ne okalja svojom svojtom i tako se oskvrne.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 21, 5, 'Neka ne briju glave; neka ne šišaju okrajke svojih brada niti prave ureze na svome tijelu.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 21, 6, 'Neka budu posvećeni svome Bogu; neka ne oskvrnjuju ime svoga Boga, jer oni prinose žrtve u čast Jahvi paljene, hranu Boga svoga. Zato moraju biti sveti.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 21, 7, 'Neka se ne žene javnom bludnicom i obeščašćenom ženom; niti se smiju ženiti onom koju je njezin muž otpustio. Jer je svećenik posvećen svome Bogu.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 21, 8, 'Svetim ga drži, jer on prinosi hranu tvoga Boga. Neka ti je svet, jer sam svet ja, Jahve, koji vas posvećujem.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 21, 9, 'Ako se kći kojeg svećenika oskvrne podavši se javnom bludništvu, ona oca svoga skvrne, pa se mora na vatri spaliti.\"');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 21, 10, '\"A svećenik koji je najveći među svojom braćom, na čiju je glavu bilo izliveno ulje pomazanja i koji je posvećen da nosi svetu odjeću, neka ne ide raščupane kose niti razdire svoje odjeće.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 21, 11, 'Neka ne ulazi nijednom mrtvacu; ne smije se okaljati ni za svojim ocem ni za svojom majkom.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 21, 12, 'Neka ne izlazi iz Svetišta, tako da ne oskvrne Svetište svoga Boga, jer na sebi nosi posvećenje uljem pomazanja Boga svoga. Ja sam Jahve!');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 21, 13, 'Neka za ženu uzme djevicu.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 21, 14, 'Udovicom, otpuštenicom, obeščašćenom i bludnicom ne smije se ženiti. Jedino djevicom između svoga naroda neka se ženi;');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 21, 15, 'tako neće oskvrnuti svoga potomstva među svojim narodom, jer ja, Jahve, njega posvećujem.\"');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 21, 16, 'Jahve reče Mojsiju:');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 21, 17, '\"Reci Aronu: \'Nitko od tvojih potomaka, za njihovih naraštaja, koji imadne kakvu tjelesnu manu ne smije se primaknuti da prinosi hranu svoga Boga.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 21, 18, 'Ni jedan na kome bude mane ne smije se primaknuti: nitko koji je slijep ili sakat; nitko izobličen ili iznakažena kojeg uda;');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 21, 19, 'nitko tko ima slomljenu nogu ili ruku;');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 21, 20, 'ni poguren, ni kržljav, ni bolesnih očiju, ni lišajav, ni krastav, niti uškopljenik.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 21, 21, 'Dakle, ni jedan od potomaka svećenika Arona koji imadne manu neka se ne primiče da prinosi u čast Jahvi paljenu žrtvu; budući da ima manu, neka se ne primiče da prinosi hranu svoga Boga.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 21, 22, 'Može blagovati hranu svoga Boga i od žrtava presvetih, i svetih,');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 21, 23, 'ali neka ne dolazi k zavjesi niti se žrtveniku primiče jer ima manu. Neka ne skvrne mojih svetih stvari, jer sam ih ja, Jahve, posvetio.\'\"');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 21, 24, 'Mojsije to kaza Aronu, njegovim sinovima i svim Izraelcima.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 22, 1, 'Jahve reče Mojsiju:');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 22, 2, '\"Reci Aronu i njegovim sinovima da sveto postupaju sa svetim prinosima Izraelaca; neka ne oskvrnjuju moje sveto ime koje oni - ta moje je! - moraju svetiti. Ja sam Jahve!');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 22, 3, 'Reci im: \'Ako se ikad tko od vaših naraštaja primakne u stanju nečistoće k svetim prinosima što ih Izraelci posvećuju Jahvi, taj će biti uklonjen od moje nazočnosti. Ja sam Jahve!\'');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 22, 4, 'Neka nitko od Aronovih potomaka koji bude gubav ili imadne izljev ne blaguje svetih prinosa dok ne postane čist. Onaj koji se dotakne bilo čega što je mrtvo tijelo okaljalo ili onaj koji iz sebe prospe sjemeni izljev;');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 22, 5, 'onaj koji se dotakne kakva puzavca koji ga onečisti; ili čovjeka od kojega se okalja bilo kakvom nečistoćom -');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 22, 6, 'onaj koji se dotakne čega takva neka je nečist do večeri i neka ne blaguje svetih prinosa dok ne okupa svoje tijelo u vodi.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 22, 7, 'Čim sunce zađe, čist je. Poslije toga može blagovati od svetih prinosa jer mu je to hrana.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 22, 8, 'Neka ne jede ni strva ni što je zvjerad rastrgla. Time bi se okaljao.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 22, 9, 'Neka drže moje naredbe, da ne navuku na se krivnju i zbog nje, oskvrnuvši se, ne poginu. Ta ja, Jahve, njih posvećujem.\"');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 22, 10, '\"Neka nijedan svjetovnjak ne blaguje od prinosa; ni ukućanin ni svećenikov sluga ne smije jesti od svetoga prinosa.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 22, 11, 'Ali ako svećenik steče koga novcem u svoje vlasništvo, taj to može jesti kao onaj što se rodi u njegovoj kući; oni mogu jesti od njegove hrane.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 22, 12, 'Ako se svećenikova kći uda za svjetovnjaka, ne smije blagovati od podizanih svetih prinosa.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 22, 13, 'Ali ako svećenikova kći obudovi ili bude otpuštena, a nema djece pa se vrati u očevu kuću, može se hraniti očevom hranom kao u svojoj mladosti. Nikakav svjetovnjak ne smije što od toga jesti.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 22, 14, 'Bude li tko iz neznanja jeo sveti prinos, neka ga nadoknadi svećeniku dodajući petinu.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 22, 15, 'Neka ne oskvrnjuju svetih prinosa što ih Izraelci Jahvi podižu.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 22, 16, 'Jedući ih, navukli bi na se krivnju koja bi ih obvezivala na nadoknadu, jer ja, Jahve, posvetio sam te prinose.\"');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 22, 17, 'Jahve reče Mojsiju:');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 22, 18, '\"Govori Aronu, njegovim sinovima i svim Izraelcima i reci im: \'Svaki čovjek doma Izraelova ili stranac u Izraelu koji donosi svoj prinos kao zavjet ili kao dragovoljan dar da se prinese Jahvi kao žrtva paljenica - da bude primljen -');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 22, 19, 'mora prinijeti muško bez mane, bilo to goveče, ovca ili koza.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 22, 20, 'Nikakvo s manom na njemu nemojte prinositi jer vam to neće biti primljeno.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 22, 21, 'Ako tko prinosi Jahvi žrtvu pričesnicu da izvrši kakav zavjet ili učini dragovoljan prinos, bilo od krupne ili sitne stoke, ta životinja, da bude primljena, mora biti bez mane; nikakve mane na njoj ne smije biti.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 22, 22, 'Nikakvu slijepu, ili hromu, ili osakaćenu, gušavu, šugavu ili krastavu životinju, nikakvu takvu Jahvi nemoj prinositi niti ikakvu takvu na žrtvenik kao paljenu žrtvu Jahvi polagati.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 22, 23, 'Junca ili ovcu s kakvim udom protegnutim ili prikaćenim možeš prinijeti kao dragovoljan prinos, ali kao žrtva zavjetnica neće biti primljena.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 22, 24, 'Jahvi nemojte prinositi životinje sa zgnječenim, stučenim, rastrgnutim ili odsječenim mošnjama. To u svoj zemlji ne činite');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 22, 25, 'niti takvo što primajte od stranca da to prinesete kao hranu svoga Boga. S manom su jer su osakaćene. Zato vam neće biti primljene.\'\"');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 22, 26, 'Jahve reče Mojsiju:');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 22, 27, '\"Kad se tele oteli, janje se ojanji ili se kozle okozi, sedam dana neka ostane uza svoju majku. Od osmoga dana može biti primljeno kao paljena žrtva Jahvi.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 22, 28, 'Ne koljite krave ni ovce u isti dan s njezinim mladim.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 22, 29, 'Kad Jahvi žrtvujete žrtvu zahvalnicu, žrtvujte je tako da budete primljeni.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 22, 30, 'Neka se žrtva blaguje onoga istog dana; od nje ništa ne ostavljajte za ujutro. Ja sam Jahve!\"');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 22, 31, '\"Moje zapovijedi držite i vršite ih. Ja sam Jahve!');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 22, 32, 'Ne oskvrnjujte moga svetog imena, nego neka budem proglašen svetim među Izraelcima - ja, Jahve, koji vas posvećujem.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 22, 33, 'Ja koji sam vas izbavio iz zemlje egipatske da budem vaš Bog, ja, Jahve.\"');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 23, 1, 'Jahve reče Mojsiju:');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 23, 2, '\"Kaži Izraelcima i reci im: Blagdani Jahvini koje imate sazivati jesu sveti zborovi. Ovo su moji blagdani:');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 23, 3, 'Šest dana neka se posao obavlja, a sedmi je dan subota - dan potpunog odmora, dan svetoga zbora, kad ne smijete raditi nikakva posla. Gdje god boravili, subota je Jahvina.\"');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 23, 4, '\"A ovo su blagdani Jahvini - sveti zborovi - koje imate proglasiti u njihovo određeno vrijeme:');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 23, 5, 'U prvom mjesecu četrnaestoga dana u suton jest Pasha u čast Jahvi;');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 23, 6, 'petnaestoga dana toga mjeseca jest Blagdan beskvasnih kruhova u čast Jahvi - sedam dana jedite beskvasan kruh.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 23, 7, 'Prvoga dana neka vam bude sveti zbor; nikakva težačkog posla nemojte raditi.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 23, 8, 'Sedam dana prinosite paljenu žrtvu u čast Jahvi, a sedmoga dana neka opet bude sveti zbor; nikakva težačkog posla ne radite.\"');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 23, 9, 'Jahve reče Mojsiju:');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 23, 10, '\"Kaži Izraelcima i reci im: \'Kad uđete u zemlju koju vam dajem i u njoj žetvu požanjete, prvi snop svoje žetve donesite svećeniku.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 23, 11, 'Neka ga on prinese kao žrtvu prikaznicu pred Jahvom da budete primljeni. Sutradan po suboti neka ga svećenik prinese kao žrtvu prikaznicu.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 23, 12, 'A u dan kad budete prinosili snop kao žrtvu prikaznicu, prinesite Jahvi jednogodišnjeg janjca bez mane kao žrtvu paljenicu.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 23, 13, 'Uz to žrtva prinosnica neka bude: dvije desetine efe najboljeg brašna zamiješena u ulju, kao paljena žrtva Jahvi na ugodan miris; a s njom ljevanica od vina neka bude četvrt hina.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 23, 14, 'Prije toga dana - dok ne donesete prinose svoga Boga - ne smijete jesti ni kruha, ni pržena zrnja, ni svježa klasja. To je trajan zakon za vaše naraštaje gdje god vi boravili.\'\"');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 23, 15, '\"A počevši od sutrašnjega dana po suboti - dana u koji donesete snop za žrtvu prikaznicu - nabrojte punih sedam tjedana.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 23, 16, 'Onda na dan po sedmoj suboti, na Pedesetnicu, prinesite Jahvi novu žrtvu.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 23, 17, 'Donesite iz svojih stanova po dva kruha za žrtvu prikaznicu. Neka svaki bude od dvije desetine efe najboljeg brašna; neka budu ispečeni ukvas, kao prvine Jahvi.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 23, 18, 'S kruhom prinesite sedam jednogodišnjih janjaca bez mane, jednoga junca i dva ovna kao žrtvu paljenicu Jahvi zajedno sa žrtvom prinosnicom i ljevanicom, žrtvom paljenom na ugodan miris Jahvi.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 23, 19, 'Prinesite i jednoga jarca kao žrtvu okajnicu, a dva janjca od godine dana za žrtvu pričesnicu.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 23, 20, 'Neka ih svećenik prinese pred Jahvom kao žrtvu prikaznicu povrh kruha od prvina. Uz oba janjca, i ovo je Jahvi sveto i neka pripadne svećeniku.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 23, 21, 'Toga istog dana sazovite zbor. Neka vam to bude posvećen zbor - nikakva težačkog posla ne radite. To je trajan zakon za vaše naraštaje gdje god vi boravili.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 23, 22, 'Kad budete želi žetvu sa svoje zemlje, nemoj žeti dokraja svoje njive niti pabirčiti poslije svoje žetve. Ostavi to sirotinji i strancu. Ja sam Jahve, Bog vaš.\"');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 23, 23, 'Jahve reče Mojsiju:');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 23, 24, '\"Govori Izraelcima i reci: \'Sedmoga mjeseca, prvoga dana u mjesecu, neka vam je potpun odmor, proglašen glasom trube, sveti zbor.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 23, 25, 'Nikakva teškog posla ne radite; u čast Jahvi paljenu žrtvu prinesite.\'\"');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 23, 26, 'Reče Jahve Mojsiju:');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 23, 27, '\"Povrh toga, u deseti dan toga sedmog mjeseca pada Dan pomirenja. Neka vam to bude prigoda za sveti zbor; postite i prinesite u čast Jahvi paljenu žrtvu.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 23, 28, 'Toga dana nemojte raditi nikakva posla. To je, naime, Dan pomirenja, kada će se za vas obaviti obred pomirenja pred Jahvom, Bogom vašim.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 23, 29, 'Jest, tko god ne bude postio toga dana, neka se odstrani iz svoga naroda.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 23, 30, 'A tko bi god radio kakav posao na taj dan, toga ću ja istrijebiti iz njegova naroda.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 23, 31, 'Nikakva posla nemojte raditi. To je trajan zakon za vaše naraštaje gdje god vi boravili.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 23, 32, 'Neka vam je to subotnji počinak. Postite! Navečer devetoga dana u mjesecu - od večeri do večeri - prestanite raditi.\"');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 23, 33, 'Jahve reče Mojsiju:');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 23, 34, '\"Reci Izraelcima: \'Od petnaestoga dana toga sedmog mjeseca neka se sedam dana drži Blagdan sjenica u čast Jahvi.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 23, 35, 'Prvoga dana, u dan svetoga zbora, nikakva težačkog posla nemojte raditi.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 23, 36, 'Sedam dana prinosite paljenu žrtvu u čast Jahvi. Osmi dan neka vam bude sveti zbor, kada ćete u čast Jahvi prinijeti paljenu žrtvu. To je svečani zbor; nikakva težačkog posla nemojte obavljati.\'\"');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 23, 37, '\"To su blagdani Jahvini koje imate sazvati - sveti zborovi određeni za prinošenje žrtava u čast Jahvi; žrtava paljenica, prinosnica, žrtava klanica i ljevanica; svaku na njezin pravi dan,');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 23, 38, 'povrh Jahvinih subota, povrh vlastitih prinosa, povrh svojih zavjetnih i dragovoljnih darova koje inače prinosite Jahvi.\"');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 23, 39, '\"Osim toga, petnaestoga dana mjeseca sedmoga, pošto pokupite sa zemlje plodove, svetkujte Jahvin blagdan sedam dana. Na prvi dan i na osmi dan neka je potpun počinak.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 23, 40, 'Uzmite već prvoga dana lijepih plodova, palmovih grana, grančica s lisnatih drveta i potočne vrbovine pa se veselite u nazočnosti Jahve, Boga svoga, sedam dana.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 23, 41, 'Svetkujte tako blagdan u čast Jahvi sedam dana svake godine. Neka je to trajan zakon za vaše naraštaje. Svetkujte taj blagdan sedmoga mjeseca.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 23, 42, 'Sedam dana stanujte u sjenicama. Svi Izraelovi domoroci neka proborave u sjenicama,');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 23, 43, 'da vaši potomci znaju kako sam ja učinio da Izraelci žive u sjenicama kad sam ih izbavio iz zemlje egipatske. Ja sam Jahve, Bog vaš.\"');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 23, 44, 'I tako Mojsije objavi Izraelcima Jahvine blagdane.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 24, 1, 'Jahve reče Mojsiju:');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 24, 2, '\"Naredi Izraelcima da ti za svijećnjak donose čistoga ulja od istupanih maslina, da se uvijek održava svjetlo.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 24, 3, 'Neka ga Aron svagda sprema pred Jahvom od večeri do jutra u Šatoru sastanka, pred zavjesom Svjedočanstva. Neka je ovo trajan zakon vašim naraštajima.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 24, 4, 'Neka Aron neprekidno održava svjetlila na čistome svijećnjaku pred Jahvom.\"');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 24, 5, '\"Potom uzmi najboljeg brašna i od njega ispeci dvanaest pogača. Neka u svakoj pogači budu dvije desetine efe.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 24, 6, 'Onda ih poredaj u dva reda - po šest u redu - na čistome stolu što je pred Jahvom.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 24, 7, 'Na svaki red stavi čistoga tamjana. Neka to bude hrana prinesena kao spomen - paljena žrtva Jahvi.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 24, 8, 'Svake subote, bez prijekida, neka se postavljaju pred Jahvu. To neka Izraelci vrše zbog vječnoga Saveza.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 24, 9, 'Neka pripadnu Aronu i njegovim sinovima. Oni ih imaju blagovati na posvećenu mjestu. To je njemu vrlo svet dio Jahvinih paljenih žrtava. To neka bude trajna odredba.\"');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 24, 10, 'A sin jedne Izraelke, komu otac bijaše Egipćanin, iziđe među Izraelce i zametne u taboru svađu s nekim Izraelcem.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 24, 11, 'Uto sin Izraelke pogrdi Ime i opsuje ga. Tada ga dovedu Mojsiju. - Mati mu se zvala Šelomit, a bila je kći Dibrijeva iz plemena Danova. -');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 24, 12, 'Stave ga u zatvor dok im se ne očituje volja Jahvina.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 24, 13, 'Onda Jahve reče Mojsiju:');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 24, 14, '\"Izvedi psovača iz tabora. Potom svi oni koji su ga čuli neka stave svoje ruke na njegovu glavu. A onda neka ga sva zajednica kamenuje.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 24, 15, 'Poslije toga ćeš ovako prozboriti Izraelcima: Tko god opsuje Boga svoga neka snosi svoju krivnju;');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 24, 16, 'tko izgovori hulu na ime Jahvino neka se smakne - neka ga sva zajednica kamenuje; bio stranac ili domorodac, ako pohuli ime Jahvino, mora mrijeti.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 24, 17, 'Ako čovjek zada smrtan udarac drugome, mora se smaknuti.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 24, 18, 'Tko usmrti živinče mora ga nadomjestiti: život za život.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 24, 19, 'Tko ozlijedi svoga bližnjega neka mu se učini kako je on učinio:');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 24, 20, 'lom za lom, oko za oko, zub za zub - rana koju je on zadao drugome neka se zada i njemu.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 24, 21, 'Tko usmrti živinče mora ga nadoknaditi, ali tko ubije čovjeka mora umrijeti.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 24, 22, 'Neka vam je jednak sud i strancu i domorocu. Jer ja sam Jahve, Bog vaš.\"');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 24, 23, 'Pošto je Mojsije to izložio Izraelcima, oni izvedu psovača izvan tabora i zaspu ga kamenjem. Učine, dakle, Izraelci kako je Jahve Mojsiju naredio.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 25, 1, 'Jahve reče Mojsiju na Sinajskom brdu:');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 25, 2, '\"Govori Izraelcima i kaži im: Kad uđete u zemlju koju vam dajem, neka ta zemlja održava Jahvin subotni počinak.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 25, 3, 'Šest godina zasijavaj svoju njivu, šest godina svoj vinograd obrezuj i beri njegov plod.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 25, 4, 'Ali sedme godine neka i zemlja uživa subotnji počinak, Jahvinu subotu: svoje njive ne zasijavaj niti obrezuj svoga vinograda.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 25, 5, 'Što samo od sebe uzraste na tvojoj njivi nemoj žeti niti beri grožđe s neobrezane loze. Neka to bude zemlji godina počivanja.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 25, 6, 'Zemljišni počinak neka vam priskrbi prehranu: tebi, tvome sluzi, tvojoj sluškinji, tvome najamniku koji s tobom živi;');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 25, 7, 'a i tvojoj stoci i zvjeradi u tvojoj zemlji neka njezini plodovi služe za hranu.\"');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 25, 8, '\"Nabroj sedam sedmica takvih godina, sedam puta sedam godina. Sedam sedmica godina iznosit će ti četrdeset devet godina.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 25, 9, 'A onda zaori u trubu! U sedmome mjesecu, desetoga dana toga mjeseca, na Dan pomirenja, zatrubite u trubu širom svoje zemlje.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 25, 10, 'Tu pedesetu godinu proglasite svetom! Zemljom proglasite oslobađanje svim njezinim stanovnicima. To neka vam bude jubilej, oprosna godina. Neka se svatko vaš vrati na svoju očevinu; neka se svatko vrati k svome rodu!');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 25, 11, 'Ta pedesetogodišnjica neka vam je jubilejska godina: nemojte sijati, nemojte žeti što samo od sebe uzraste niti berite grožđe s neobrezane loze.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 25, 12, 'Jer jubilej vam mora biti svet! Hranite se onim što njiva donese od sebe.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 25, 13, 'Te jubilejske godine neka se svatko vrati na svoju očevinu.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 25, 14, 'Zato, kad prodajete imanje svome sunarodnjaku ili kupujete od svoga sunarodnjaka, nemojte nanositi štete svome bratu!');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 25, 15, 'Od svoga sunarodnjaka kupuj, odbivši samo broj godina poslije jubileja, a on neka ti proda prema broju proizvodnih godina.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 25, 16, 'Što više godina, više i cijenu povisi; što manje godina, neka je i cijena manja. Jer, ono što ti on prodaje jest broj ljetina.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 25, 17, 'Neka nitko od vas ne nanosi štete svome sunarodnjaku, nego se boj Boga svoga! Jer ja sam Jahve, Bog vaš.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 25, 18, 'Vršite moje zakone i moje naredbe; vjerno ih provodite u djelo pa ćete u sigurnosti živjeti na zemlji.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 25, 19, 'Zemlja će davati svoj rod, jest ćete do sitosti i živjet ćete u sigurnosti.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 25, 20, 'Ako biste rekli: \'Čime ćemo se hraniti te sedme godine kad ne budemo ni sijali ni brali plodova?\'');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 25, 21, 'evo, blagoslov ću svoj pustiti na vas: šesta godina rodom će roditi za tri godine.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 25, 22, 'Kad budete sijali osme godine, hranit ćete se starim prihodom sve do devete godine; dok ne dođe njezin prihod, jest ćete stari.\"');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 25, 23, '\"Zemlja se ne smije prodati potpuno, jer zemlja pripada meni, dok ste vi samo stranci i gosti kod mene.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 25, 24, 'Zato u svakome kraju gdje imate zemljišne posjede morate dopustiti otkupljivanje zemlje.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 25, 25, 'Ako tvoj brat zapadne u škripac te moradne prodati dio svoje očevine, neka dođe njegov najbliži izbavitelj i otkupi što je njegov brat prodao.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 25, 26, 'Ako nema koga da mu ga otkupi, a poslije i sam postane imućan te stekne sredstva da je otkupi,');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 25, 27, 'neka prebroji godine od prodaje, isplati kupcu svotu za preostalo vrijeme i vrati se na svoju očevinu.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 25, 28, 'Ako nema sredstava da je vrati, onda prodano neka ostane u rukama kupca do jubilejske godine. A stupivši u jubilej, neka se vrati na svoju očevinu.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 25, 29, 'Ako tko proda stojnu kuću u gradu zidom obzidanu, može je otkupiti dokle se ne navrši godina poslije prodaje; otkupni rok neka je, dakle, jedna godina.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 25, 30, 'Ako je ne otkupi u roku od godine, onda kuća u gradu zidom opasana prelazi potpuno kupcu i njegovim potomcima: ni za jubileja neka se ne vraća.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 25, 31, 'Ali kuće po selima što nemaju zidova oko sebe neka se smatraju kao posjedi u polju; mogu se otkupljivati. U jubileju kupac mora iz njih izići.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 25, 32, 'Kuće koje u levitskim gradovima pripadaju levitima mogu leviti otkupiti u svako vrijeme.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 25, 33, 'Ako se koji levit ne posluži svojim pravom otkupa, onda će kuća što bude prodana u gradu njegova vlasništva biti za jubileja vraćena. Jer kod Izraelaca kuće u gradovima levita njihovo su vlasništvo.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 25, 34, 'Neograđena zemlja oko njihovih gradova ne može se prodati, jer je ona njihovo vlasništvo za sva vremena.\"');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 25, 35, '\"Ako tvoj brat zapadne u škripac i ne mogne održavati svoje odnose s tobom, primi ga; i neka s tobom živi kao stranac ili gost.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 25, 36, 'Ne uzimaj od njega ni lihve ni kamata. Boga se svoga boj, i neka tvoj brat živi s tobom!');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 25, 37, 'Ne uzajmljuj mu novac na kamate niti mu lihvarski davaj svoju hranu.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 25, 38, 'Ja, Jahve, Bog vaš, izbavio sam vas iz zemlje egipatske da vam dadem zemlju kanaansku i budem vaš Bog.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 25, 39, 'Ako li tvoj brat padne u škripac dok je s tobom u urednim odnosima te se moradne tebi prodati, nemoj ga prisiliti da služi kao rob; neka bude kod tebe kao najamnik ili nadničar.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 25, 40, 'Neka služi kod tebe do jubilejske godine.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 25, 41, 'Onda neka bude slobodan da ode od tebe - i on i njegova djeca s njim; neka ide natrag svome rodu i opet zaposjedne svoju djedovinu.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 25, 42, 'TÓa oni su moji službenici, ja sam ih izbavio iz zemlje egipatske; oni se ne smiju prodavati kao robovi.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 25, 43, 'Nemoj s njim grubo postupati! Boga se svoga boj!');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 25, 44, 'A robove i ropkinje, budeš li ih htio imati, možete kupiti, i muške i ženske, od naroda koji su oko vas.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 25, 45, 'Možete ih kupovati i od pridošlica koji s vama borave; od njihovih obitelji što žive s vama i rođeni su u vašoj zemlji. Takvi mogu postati vašim vlasništvom.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 25, 46, 'Njih možete predati u nasljedstvo svojoj djeci da ih zavazda naslijede u baštinu. Prema njima možete postupati kao prema robovima. Ali prema svojoj braći, Izraelcima, nitko ne smije grubo postupati.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 25, 47, 'Ako se stranac s tobom nastanjen obogati, a tvoj brat, u svojim odnosima prema njemu, zapadne u škripac te se proda strancu koji je s tobom nastanjen ili kojemu god potomku strančeve obitelji,');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 25, 48, 'on ima pravo i nakon prodaje biti otkupljen. Neka ga otkupi netko od njegove braće;');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 25, 49, 'ili neka ga otkupi njegov stric, njegov rođak ili bilo tko od njegove obitelji koji bude od njegove krvi. Ili, ako ima sredstava, neka se sam otkupi.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 25, 50, 'Sa svojim kupcem neka proračuna vrijeme od godine kad mu se prodao do jubilejske godine. Cijena za njegovo oslobođenje neka bude prema broju godina. Vrijeme što ga je proveo sa svojim vlasnikom neka se procijeni kao vrijeme jednog najamnika.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 25, 51, 'Ako ostaje još mnogo godina, neka isplati za svoju otkupninu u omjeru svoje prodajne svote.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 25, 52, 'A ako ostaje samo nekoliko godina do jubilejske godine, neka izračuna pa isplati za svoj otkup prema godinama službe.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 25, 53, 'Prema njemu neka bude kao prema najamniku koji se iznajmljuje od godine na godinu. Neka se na tvoje oči s njim ne postupa grubo.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 25, 54, 'Ne bude li iskupljen ovako, onda i on i njegova djeca s njim neka odu u jubilejskoj godini.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 25, 55, 'Jer Izraelci su moji službenici; oni su moji službenici koje sam ja izveo iz zemlje egipatske, ja, Jahve, Bog vaš.\"');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 26, 1, '\"Ne pravite sebi kumira; ne podižite sebi ni kipa ni spomen-stupa; ne postavljajte u svojoj zemlji kamenja s likovima da pred njih padate.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 26, 2, 'Održavajte moje subote; poštujte moje Svetište - jer ja sam Jahve, Bog vaš.\"');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 26, 3, '\"Budete li živjeli prema mojim zakonima, održavali moje zapovijedi i u djelo ih provodili,');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 26, 4, 'davat ću vam kiše u pravo vrijeme te će zemlja rađati rodom a stabla po polju donositi plodove.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 26, 5, 'Vršidba će vam stizati berbu, a berba stizati sjetvu. Jest ćete kruh svoj do sitosti i u svojoj ćete zemlji živjeti u sigurnosti.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 26, 6, 'Zemlji ću dati mir; tako ćete počivati a da vas nitko ne plaši. Štetne ću životinje iz zemlje ukloniti; mač neće prolaziti vašom zemljom.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 26, 7, 'U bijeg ćete nagoniti svoje neprijatelje, a oni će padati pred vama od mača.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 26, 8, 'Petorica vas nagonit će u bijeg stotinu njih, a stotina vas nagonit će u bijeg deset tisuća njih. Da, vaši će neprijatelji padati pred vama od mača.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 26, 9, 'K vama ću se okrenuti te vas rodnima činiti i razmnažati. Držat ću svoj Savez s vama.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 26, 10, 'Starom ćete se zalihom hraniti; štoviše, trebat će vam zalihe ispražnjavati da mognete sasipati novo žito.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 26, 11, 'Među vama ću postaviti svoje Prebivalište i neću vas odbaciti;');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 26, 12, 'među vama ću hoditi i bit ću vam Bog, a vi ćete mi biti narod.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 26, 13, 'Ja, Jahve, Bog vaš, izveo sam vas iz zemlje egipatske da im više ne budete roblje; polomio sam palice vaših jarmova i učinio da hodate uspravno.\"');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 26, 14, '\"Ali ako me ne poslušate i u djelo ne provedete sve ove moje zapovijedi;');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 26, 15, 'ako odbacite moje zakone, pogazite moje naredbe i prekršite moj Savez, ne provodeći u djelo sve moje zapovijedi,');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 26, 16, 'evo što ću ja učiniti vama: podvrgnut ću vas strepnji, iznemoglosti i groznici što oči troše a život gase.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 26, 17, 'Sjetve ćete svoje uzalud sijati - neprijatelji vaši njima će se hraniti. Ja ću se protiv vas okrenuti, a vaši će vas neprijatelji ametice tući. Oni koji vas mrze gospodarit će nad vama. Bježat ćete i onda kad vas nitko ne bude progonio.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 26, 18, 'Pa ako me i unatoč tome ne poslušate, ja ću vas sedmerostruko kažnjavati za vaše grijehe.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 26, 19, 'Slomit ću ja vašu drsku silu. Vaša ću nebesa učiniti poput gvožđa, a zemlju vašu poput tuča.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 26, 20, 'Uzalud će se trošiti vaša snaga. Zemlja vam više neće davati svoga roda niti će stabla na zemlji donositi svojih plodova.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 26, 21, 'Budete li se još i dalje protivili, ne htjednete li me poslušati, sedmerostruko ću još na vama povisiti rane za vaše grijehe.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 26, 22, 'Na vas ću pustiti šumsku zvjerad da vas liši djece, blago vam podavi a vas prorijedi tako da vam putovi postanu pusti.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 26, 23, 'Ako vas ni to ne popravi nego nastavite življenje koje se meni protivi,');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 26, 24, 'onda ću se i ja suprotstaviti vama i sam ću vas još sedmerostruko udariti za vaše grijehe.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 26, 25, 'Na vas ću dovesti mač neka se iskali osvetom za Savez. A kad se zbijete u svoje gradove, poslat ću na vas kugu i bit ćete predani u ruke neprijatelju.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 26, 26, 'Još kad vam obustavim namicanje kruha, deset žena moći će vam peći kruh u jednoj peći i na mjeru će vam kruh davati. Jest ćete, ali se nećete nasititi.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 26, 27, 'Ako me ni tada ne poslušate nego mi se dalje budete suprotstavljali,');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 26, 28, 'i ja ću se vama suprotstaviti - sedmerostruko ću vas kazniti za vaše grijehe.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 26, 29, 'Jest ćete meso od svojih sinova, jest ćete meso od svojih kćeri.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 26, 30, 'Porušit ću vaše idolske uzvišice; oborit ću vaše kadione žrtvenike, zgrnut ću vaša mrtva trupla na trupla vaših kumira i odbacit ću vas.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 26, 31, 'Gradove ću vaše pretvoriti u ruševine; svetišta ću vaša opustošiti, vaš ugodni miris neću više mirisati.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 26, 32, 'Zemlju ću ja pretvoriti u zgarište tako da će se vaši neprijatelji koji se u njoj nastane zaprepastiti nad njom.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 26, 33, 'Vas ću rasijati po narodima; izvući ću protiv vas mač iz korica tako da će vam se zemlja pretvoriti u pustaru a gradovi u ruševine.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 26, 34, 'Tada će zemlja namiriti svoje subote za sve vrijeme dok bude pusta i vi budete u zemlji svojih neprijatelja. Otpočinut će tada zemlja i moći će namiriti svoje subote.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 26, 35, 'Sve dok bude pusta, imat će počinak koji nije imala za vaših subota dok ste vi u njoj stanovali.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 26, 36, 'A onima od vas koji na životu ostanu po zemljama svojih neprijatelja, njima ću strah u srce utjerati. U bijeg će ih nagoniti šuštaj lista što zatrepti. Bježat će kao što se bježi od mača; padat će, iako ih nitko neće progoniti.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 26, 37, 'Spoticat će se jedan o drugoga kao kad se bježi ispred mača, premda ih nitko neće progoniti. Nećete se održati pred svojim neprijateljima;');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 26, 38, 'izginut ćete među narodima - proždrijet će vas zemlja vaših neprijatelja.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 26, 39, 'A koji od vas prežive venut će u zemljama svojih neprijatelja zbog svojih opačina; venut će i zbog opačina svojih otaca.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 26, 40, 'Priznat će tada svoju opačinu i opačinu svojih otaca što su je protiv mene počinili izdajom, što su mi se protivili.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 26, 41, 'I ja sam sa morao suprotstaviti njima i odvesti ih u zemlju njihovih neprijatelja.\" \"Onda će se napokon njihovo tvrdokorno srce poniziti; ispaštat će oni svoju krivnju.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 26, 42, 'Tada ću se ja sjetiti svoga Saveza s Jakovom i svoga Saveza s Izakom; sjetit ću se svoga Saveza s Abrahamom - zemlje ću se sjetiti.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 26, 43, 'Zemlja će, ostavljena od njih, namiriti svoje subote kad ostane pusta zbog njih. A oni će ispaštati svoju krivnju što su odbacili moje zapovijedi; što su prezreli moje zakone.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 26, 44, 'Ali ni onda dok budu u zemlji svojih neprijatelja, neću ih zabaciti niti ću ih prezreti tako da ih posve uništim i da prekršim svoj Savez s njima. TÓa ja sam Jahve, Bog njihov.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 26, 45, 'Radi njih sjetit ću se Saveza s njihovim precima koje sam izveo iz zemlje egipatske naočigled naroda da budem njihov Bog, ja Jahve.\"');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 26, 46, 'To su odredbe, uredbe i zakoni koje je Jahve uglavio između sebe i Izraelaca po Mojsiju na Sinajskome brdu.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 27, 1, 'Jahve reče Mojsiju:');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 27, 2, '\"Govori Izraelcima i reci im: \'Ako tko zaželi podmiriti Jahvi zavjet što vrijedi koliko čovjek,');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 27, 3, 'neka ti je mjerilo: muškarca od dvadeset do šezdeset godina starosti procijeni pedeset šekela u srebru, prema hramskom šekelu,');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 27, 4, 'a žensku procijeni trideset šekela.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 27, 5, 'A za dob od pet do dvadeset godina neka tvoja procjena bude: za muškarca dvadeset šekela, a za žensku deset šekela.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 27, 6, 'Je li dob od jednoga mjeseca do pet godina, neka ti je procjena: za muško pet šekela u srebru, a procjena za žensko tri šekela u srebru.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 27, 7, 'Bude li u starosti od šezdeset godina ili više, neka ti je procjena: za muškarca petnaest šekela, a za žensku deset šekela.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 27, 8, 'Ali ako je tko siromašan te ne može platiti svoju cijenu, neka ga dovedu pred svećenika i neka ga svećenik procijeni. Ali neka svećenik procijeni prema onome što zavjetovalac može dati.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 27, 9, 'Ako zavjetovani prinos bude od životinja koje se mogu Jahvi prinositi, svaki takav prinos Jahvi bit će posvećena stvar.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 27, 10, 'Neka se ne nadomješta niti zamjenjuje za što drugo - bilo dobro za loše, bilo loše za dobro. Ako li se napravi zamjena jednoga živinčeta za drugo, onda će i zavjetovano i ono koje ga je zamijenilo biti posvećena stvar.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 27, 11, 'Bude li zavjetovani prinos od nečiste životinje koja se ne može Jahvi prinositi, neka se takvo živinče dovede k svećeniku');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 27, 12, 'pa neka ga on procijeni. Bilo skupo, bilo jeftino, kako svećenik procijeni, neka tako bude.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 27, 13, 'Zaželi li ga tko otkupiti, neka doda njegovoj procjeni jednu petinu.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 27, 14, 'Ako tko posveti svoju kuću zavjetovavši je Jahvi, neka svećenik procijeni da li je dobra ili loša. Kako svećenik prosudi, neka tako ostane.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 27, 15, 'Ako onaj koji je svoju kuću zavjetovao zaželi da je otkupi, neka dometne jednu petinu svoti na koju je procijenjena pa neka bude njegova.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 27, 16, 'Ako tko zavjetuje Jahvi dio zemljišta od svoga vlasništva, procijeni ga prema njegovu usjevu: za jedan homer ječmena sjemena pedeset šekela u srebru.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 27, 17, 'Zavjetuje li zemljište za jubilejske godine, neka ostane prema ovoj procjeni.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 27, 18, 'Ali ako zemljište zavjetuje poslije jubilejske godine, neka svećenik proračuna cijenu prema godinama što preostaju do jubilejske godine i prema tome smanji procjenu.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 27, 19, 'Ako onaj tko je zemljište zavjetovao zaželi da ga otkupi, neka doda jednu petinu svoti na koju je procijenjeno pa neka mu ostane.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 27, 20, 'Ako zemljište ne otkupi nego ga proda drugome, ne može se više otkupiti.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 27, 21, 'Kad zemljište bude oslobođeno u jubilejskoj godini, neka se posveti Jahvi kao zavjetovano zemljište i postane svećenikov posjed.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 27, 22, 'Zavjetuje li tko Jahvi kupljeno zemljište koje nije dio njegove očevine,');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 27, 23, 'neka mu svećenik proračuna razmjernu procjenu do jubilejske godine. I toga istog dana neka isplati iznos kao stvar posvećenu Jahvi.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 27, 24, 'U jubilejskoj godini zemljište se ima vratiti onome od koga je kupljeno - kome pripada zemljišno vlasništvo.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 27, 25, 'Svaka procjena neka se vrši prema hramskom šekelu: dvadeset gera jedan šekel.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 27, 26, 'Ali neka nitko ne zavjetuje prvinu od stoke. TÓa prvina ionako pripada Jahvi - Jahvina je, pa bila od sitnoga bila od krupnoga blaga.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 27, 27, 'Bude li od nečiste stoke, može se otkupiti prema procjeni, dometnuvši petinu cijene. Ako se ne otkupi, neka se prema procjeni proda.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 27, 28, 'Ali ništa od \'herema\', od onog što je Jahvi izručeno, bio to čovjek ili živinče ili njegovo baštinjeno zemljište, ništa što je tko Jahvi zavjetom posvetio, ne može se niti prodati niti otkupiti. Svaka zavjetom posvećena stvar najveća je Jahvina svetinja.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 27, 29, 'Nijedno ljudsko biće koje bude \'heremom\' - prokletstvom - udareno ne smije se otkupljivati: mora se smaknuti.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 27, 30, 'Svaka desetina sa zemljišta, bilo od poljskih usjeva bilo od plodova sa stabala, pripada Jahvi; to je Jahvi posvećeno.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 27, 31, 'Ako bi tko htio otkupiti koji dio svoje desetine, mora tome dodati jednu petinu cijene.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 27, 32, 'Svaka desetina od krupnoga i sitnoga blaga, to jest svako deseto od svega što prolazi ispod pastirskog štapa, neka bude posvećeno Jahvi.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 27, 33, 'Neka se ne gleda je li dobro ili rđavo; i neka se ne zamjenjuje. Ako se ipak zamijeni, neka je onda i jedno i drugo posvećeno i ne smije se otkupljivati.\'\"');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 27, 34, 'To su zapovijedi koje je Jahve izdao Mojsiju za Izraelce na Sinajskome brdu.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 1, 1, 'U Sinajskoj pustinji, u Šatoru sastanka, reče Jahve Mojsiju prvoga dana drugoga mjeseca, druge godine po izlasku iz zemlje egipatske:');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 1, 2, '\"Obavite popis sve zajednice izraelske po rodovima i porodicama, navodeći imena svih muškaraca, glavu po glavu.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 1, 3, 'Od dvadeset godina naviše, za borbu sposobne u Izraelu, ti i Aron pobilježite prema njihovim jedinicama.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 1, 4, 'Neka s vama bude po jedan čovjek od svakoga plemena, glavari svoga pradjedovskog doma.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 1, 5, 'Ovo su imena ljudi koji će vam pomagati: Elisur, sin Šedeurov, za pleme Rubenovo;');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 1, 6, 'Šelumiel, sin Surišadajev, za pleme Šimunovo;');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 1, 7, 'Nahšon, sin Aminadabov, za pleme Judino;');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 1, 8, 'Netanel, sin Suarov, za pleme Jisakarovo;');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 1, 9, 'Eliab, sin Helonov, za pleme Zebulunovo.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 1, 10, 'Za Josipove sinove: Elišama, sin Amihudov, za pleme Efrajimovo; Gamliel, sin Pedahsurov, za pleme Manašeovo;');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 1, 11, 'Abidan, sin Gidonijev, za pleme Benjaminovo;');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 1, 12, 'Ahiezer, sin Amišadajev, za pleme Danovo;');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 1, 13, 'Pagiel, sin Okranov, za pleme Ašerovo;');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 1, 14, 'Elijasaf, sin Deuelov, za pleme Gadovo;');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 1, 15, 'Ahira, sin Enanov, za pleme Naftalijevo.\"');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 1, 16, 'To bijahu sazivači zajednice, knezovi pradjedovskih plemena i glavari rodova izraelskih.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 1, 17, 'Mojsije i Aron onda uzmu one ljude što su po imenu bili određeni');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 1, 18, 'te prvoga dana drugoga mjeseca sazovu svu zajednicu. Tada se u popis prema rodovima i porodicama po redu unosio broj osoba starijih od dvadeset godina.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 1, 19, 'Kako je Jahve naredio Mojsiju, tako ih je on pobilježio u Sinajskoj pustinji.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 1, 20, 'Kad se utvrdi potomstvo Rubena, Izraelova prvorođenca, prema njegovim rodovima i porodicama, pribilježiše, glavu po glavu, imena svih muškaraca od dvadeset godina naviše, svih za borbu sposobnih.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 1, 21, 'Popisanih od Rubenova plemena bilo je četrdeset i šest tisuća i pet stotina.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 1, 22, 'Bili su popisani Šimunovi potomci prema njihovim rodovima i porodicama: pribilježiše se, glava po glava, imena svih muškaraca od dvadeset godina naviše, svih za borbu sposobnih.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 1, 23, 'Popisanih od Šimunova plemena bilo je pedeset i devet tisuća i tri stotine.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 1, 24, 'Kad se utvrdi potomstvo sinova Gadovih prema njihovim rodovima i porodicama, pribilježiše se, glava po glava, imena onih od dvadeset godina i više, svih za borbu sposobnih.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 1, 25, 'Popisanih od Gadova plemena bilo je četrdeset i pet tisuća i šest stotina i pedeset.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 1, 26, 'Kad se utvrdi potomstvo sinova Judinih prema njihovim rodovima i porodicama, pribilježiše se, glava po glava, imena onih od dvadeset godina i više, svih za borbu sposobnih.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 1, 27, 'Popisanih od Judina plemena bilo je sedamdeset i četiri tisuće i šest stotina.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 1, 28, 'Kad se utvrdi potomstvo sinova Jisakarovih prema njihovim rodovima i porodicama, pribilježiše se, glava po glava, imena onih od dvadeset godina i više, svih za borbu sposobnih.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 1, 29, 'Popisanih od Jisakarova plemena bilo je pedeset i četiri tisuće i četiri stotine.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 1, 30, 'Kad se utvrdi potomstvo sinova Zebulunovih prema njihovim rodovima i porodicama, pribilježiše se, glava po glava, imena onih od dvadeset godina i više, svih za borbu sposobnih.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 1, 31, 'Popisanih od Zebulunova plemena bilo je pedeset i sedam tisuća i četiri stotine.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 1, 32, 'Josipovi sinovi: Kad se utvrdi potomstvo sinova Efrajimovih, prema njihovim rodovima i porodicama, pribilježiše se, glava po glava, imena onih od dvadeset godina i više, svih za borbu sposobnih.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 1, 33, 'Popisanih od Efrajimova plemena bilo je četrdeset tisuća i pet stotina.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 1, 34, 'Kad se utvrdi potomstvo sinova Manašeovih, prema njihovim rodovima i porodicama, pribilježiše se, glava po glava, imena onih od dvadeset godina i više, svih za borbu sposobnih.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 1, 35, 'Popisanih od Manašeova plemena bilo je trideset i dvije tisuće i dvjesta.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 1, 36, 'Kad se utvrdi potomstvo sinova Benjaminovih, prema njihovim rodovima i porodicama, pribilježiše se, glava po glava, imena onih od dvadeset godina i više, svih za borbu sposobnih.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 1, 37, 'Popisanih od Benjaminova plemena bilo je trideset i pet tisuća i četiri stotine.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 1, 38, 'Kad se utvrdi potomstvo sinova Danovih, prema njihovim rodovima i porodicama, pribilježiše se, glava po glava, imena onih od dvadeset godina i više, svih za borbu sposobnih.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 1, 39, 'Popisanih od Danova plemena bilo je šezdeset i dvije tisuće i sedam stotina.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 1, 40, 'Kad se utvrdi potomstvo sinova Ašerovih, prema njihovim rodovima i porodicama, pribilježiše se, glava po glava, imena onih od dvadeset godina i više, svih za borbu sposobnih.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 1, 41, 'Popisanih od Ašerova plemena bila je četrdeset i jedna tisuća i pet stotina.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 1, 42, 'Kad se utvrdi potomstvo sinova Naftalijevih, prema njihovim rodovima i porodicama, pribilježiše se, glava po glava, imena onih od dvadeset godina i više, svih za borbu sposobnih.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 1, 43, 'Popisanih od Naftalijeva plemena bilo je pedeset i tri tisuće i četiri stotine.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 1, 44, 'To su oni koje popisaše Mojsije i Aron sa dvanaest knezova izraelskih, po jedan na svaki pradjedovski dom.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 1, 45, 'Bili su popisani svi Izraelci, prema pradjedovskim domovima, od dvadeset godina i više, svi za borbu sposobni u Izraelu.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 1, 46, 'Bilo je, dakle, svih popisanih šest stotina i tri tisuće i pet stotina i pedeset.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 1, 47, 'Među te nisu se ubrojili Levijevci prema svojem pradjedovskom plemenu.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 1, 48, 'Jahve je, naime, rekao Mojsiju:');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 1, 49, '\"Nipošto nemoj popisivati Levijeva plemena niti ga unosi u popis Izraelaca.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 1, 50, 'Nego ti sam odredi Levijevce za službu u Prebivalištu svjedočanstva; za sav njegov namještaj i sve što na nj spada; neka oni nose Prebivalište i sav njegov namještaj; neka oni u njemu poslužuju i oko njega tabore.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 1, 51, 'Kad se Prebivalište mora premještati, neka ga Levijevci rastave; a kad se s Prebivalištem treba utaboriti, neka ga Levijevci opet podignu. Svjetovnjak koji bi mu se primakao neka se pogubi.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 1, 52, 'Neka Izraelci logoruju svatko u svome taboru; svatko kod svoje zastave, po četama.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 1, 53, 'Levijevci neka borave oko Prebivališta svjedočanstva, da se gnjev ne obori na izraelsku zajednicu. Neka tako Levijevci stražu straže oko Prebivališta svjedočanstva.\"');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 1, 54, 'Izraelci učine kako je Jahve Mojsiju naredio. U svemu tako urade.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 2, 1, 'Jahve reče Mojsiju i Aronu:');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 2, 2, '\"Neka Izraelci logoruju svatko kod svoje zastave, pod znakovima svojih pradjedovskih domova; neka se utabore oko Šatora sastanka, ali malo podalje.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 2, 3, 'Sprijeda, s istočne strane, zastava Judina tabora, prema njihovim četama. Glavar je Judinih potomaka Nahšon, sin Aminadabov.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 2, 4, 'Njegova vojska broji sedamdeset i četiri tisuće i šest stotina popisanih.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 2, 5, 'Do njega neka taboruje Jisakarovo pleme. Glavar je Jisakarovih potomaka Netanel, sin Suarov.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 2, 6, 'Njegova vojska broji pedeset četiri tisuće i četiri stotine popisanih.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 2, 7, 'Onda pleme Zebulunovo. Glavar je Zebulunovih potomaka Eliab, sin Helonov.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 2, 8, 'Njegova vojska broji pedeset i sedam tisuća i četiri stotine popisanih.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 2, 9, 'Prema njihovim četama, svih je upisanih u Judinu taboru sto osamdeset i šest tisuća i četiri stotine. Neka oni prvi stupaju!');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 2, 10, 'S juga je zastava tabora Rubenova, prema njihovim četama. Glavar je Rubenovih potomaka Elisur, sin Šedeurov.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 2, 11, 'Njegova vojska broji četrdeset i šest tisuća i pet stotina popisanih.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 2, 12, 'Do njega neka taboruje pleme Šimunovo. Glavar je Šimunovih potomaka Šelumiel, sin Surišadajev.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 2, 13, 'Njegova vojska broji pedeset i devet tisuća i tri stotine popisanih.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 2, 14, 'Onda pleme Gadovo. Glavar je Gadovih potomaka Elijasaf, sin Deuelov.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 2, 15, 'Njegova vojska broji četrdeset i pet tisuća šest stotina i pedeset popisanih.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 2, 16, 'Prema njihovim četama, svih je upisanih u taboru Rubenovu sto pedeset i jedna tisuća četiri stotine i pedeset. Neka oni stupaju drugi!');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 2, 17, 'Potom neka ide Šator sastanka, tako da tabor levitski bude usred drugih tabora. Kako taboruju, onako neka i stupaju: svatko pod svojom zastavom.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 2, 18, 'Sa zapada, zastava tabora Efrajimova, prema njihovim četama. Glavar je Efrajimovih potomaka Elišama, sin Amihudov.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 2, 19, 'Njegova vojska broji četrdeset tisuća i pet stotina popisanih.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 2, 20, 'Do njega je pleme Manašeovo. Glavar je Manašeovih potomaka Gamliel, sin Pedahsurov.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 2, 21, 'Njegova vojska broji trideset i dvije tisuće i dvjesta popisanih.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 2, 22, 'Onda je pleme Benjaminovo. Glavar je potomaka Benjaminovih Abidan, sin Gidonijev.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 2, 23, 'Njegova vojska broji trideset i pet tisuća i četiri stotine popisanih.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 2, 24, 'Prema njihovim četama, svih je upisanih u Efrajimovu taboru sto i osam tisuća i sto. Oni neka stupaju treći!');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 2, 25, 'Sa sjevera, zastava tabora Danova, prema njihovim četama. Glavar je Danovih potomaka Ahiezer, sin Amišadajev.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 2, 26, 'Njegova vojska broji šezdeset i dvije tisuće i sedam stotina popisanih.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 2, 27, 'Do njega neka se utabori pleme Ašerovo. Glavar je Ašerovih potomaka Pagiel, sin Okranov.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 2, 28, 'Njegova vojska broji četrdeset i jednu tisuću i pet stotina popisanih.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 2, 29, 'Onda pleme Naftalijevo. Glavar je Naftalijevih potomaka Ahira, sin Enanov.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 2, 30, 'Njegova vojska broji pedeset i tri tisuće i četiri stotine popisanih.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 2, 31, 'Svih je popisanih u taboru Danovu sto pedeset i sedam tisuća i šest stotina. Neka oni stupaju posljednji pod svojim zastavama.\"');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 2, 32, 'To su popisani Izraelci prema pradjedovskim domovima. Svih je upisanih u taborima, po njihovim četama, šest stotina i tri tisuće i pet stotina i pedeset.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 2, 33, 'Levijevci nisu bili upisivani s Izraelcima, kako je Jahve naredio Mojsiju.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 2, 34, 'U svemu su Izraelci učinili kako je Jahve naredio Mojsiju. Tako su taborovali pod svojim zastavama i tako išli, svatko prema svom rodu i porodici.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 3, 1, 'Ovo je potomstvo Aronovo i Mojsijevo iz vremena kad je Jahve Mojsiju govorio na Sinajskom brdu.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 3, 2, 'Ovo su bila imena Aronovih sinova: prvorođenac Nadab, zatim Abihu, Eleazar i Itamar.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 3, 3, 'To su imena Aronovih sinova, svećenika pomazanih, za svećeništvo posvećenih.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 3, 4, 'Ali Nadab i Abihu umriješe pred Jahvom kad su u Sinajskoj pustinji pred njim prinosili neposvećenu vatru. Kako nisu imali sinova, to su Eleazar i Itamar služili kao svećenici u nazočnosti svoga oca Arona.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 3, 5, 'Jahve reče Mojsiju:');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 3, 6, '\"Dozovi pleme Levijevo neka stane pred svećenika Arona. Neka mu poslužuju;');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 3, 7, 'neka vrše njegovu dužnost i dužnost sve zajednice pred Šatorom sastanka, služeći Prebivalištu.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 3, 8, 'Neka se brinu za sav namještaj u Šatoru sastanka, za dužnost sinova izraelovih, i obavljaju službu u Prebivalištu.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 3, 9, 'Podaj levite Aronu i njegovim sinovima. Neka mu ih Izraelci potpuno daruju.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 3, 10, 'Arona i njegove sinove postavi da vrše svoju svećeničku službu. A svjetovnjak koji bi se tome približio neka se pogubi.\"');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 3, 11, 'Jahve reče Mojsiju:');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 3, 12, '\"Ja, evo, uzimam Levijevce između Izraelaca namjesto svih prvorođenaca - onih koji otvaraju materinju utrobu kod Izraelaca. Moji su, dakle, Levijevci!');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 3, 13, 'Meni, naime, pripada svaki prvorođenac. Onoga dana kad sam pobio sve prvence u zemlji egipatskoj, sebi sam posvetio sve prvorođence u Izraelu - i od ljudi i od stoke. Oni su moji. Ja sam Jahve.\"');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 3, 14, 'Jahve reče Mojsiju u Sinajskoj pustinji:');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 3, 15, '\"Popiši Levijevce po njihovim porodicama i rodovima; popiši sve muškarce od jednoga mjeseca i više.\"');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 3, 16, 'Na zapovijed Jahvinu Mojsije ih popisa, kako mu je bilo naređeno.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 3, 17, 'Ovo su poimenice bili sinovi Levijevi: Geršon, Kehat i Merari.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 3, 18, 'A ovo su imena Geršonovih sinova po njihovim rodovima: Libni i Šimi.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 3, 19, 'A sinovi su Kehatovi po svojim rodovima: Amram, Jishar, Hebron i Uziel.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 3, 20, 'Sinovi su Merarijevi po svojim rodovima: Mahli i Muši. To su Levijevi rodovi po svojim porodicama.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 3, 21, 'Od Geršona lozu vuče rod Libnijev i rod Šimijev. To su rodovi Geršonovaca.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 3, 22, 'Njih je u popisu svih muškaraca od jednoga mjeseca naviše ubilježeno sedam tisuća i pet stotina.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 3, 23, 'Rodovi Geršonovaca taborovali su za Prebivalištem prema zapadu.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 3, 24, 'Glava porodice Geršonovaca bijaše Elijasaf, sin Laelov.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 3, 25, 'Geršonovci su se u Šatoru sastanka brinuli za Prebivalište, za Šator i njegov krov, za zavjese na ulazu u Šator sastanka;');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 3, 26, 'onda za dvorišne zavjese, za zavjesu na ulazu u dvorište što je oko Prebivališta i žrtvenika, za njihova užeta i za sve što spada na tu službu.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 3, 27, 'Od Kehata potječe rod Amramov, rod Jisharov, rod Hebronov i rod Uzielov. To su rodovi Kehatovaca.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 3, 28, 'Kad se popisaše svi muškarci od jednoga mjeseca naviše, bilo ih je osam tisuća i šest stotina. Oni su se brinuli za Svetište.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 3, 29, 'Rodovi Kehatovaca taborovali su s južne strane Prebivališta.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 3, 30, 'Glava rodova u domu Kehatovu bijaše Elisafan, sin Uzielov.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 3, 31, 'Oni su se brinuli za Kovčeg, stol, svijećnjak, žrtvenik i sveti pribor kojim su se služili i, konačno, za zavjesu i za sve što joj pripada.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 3, 32, 'Vrhovni poglavar levita bio je Eleazar, sin svećenika Arona. On je vršio nadzor nad onima koji su se brinuli za Svetište.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 3, 33, 'Od Merarija potječe rod Mahlijev i rod Mušijev. To su Merarijevi rodovi.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 3, 34, 'Njih je u popisu svih muškaraca od jednoga mjeseca i više ubilježeno šest tisuća i dvije stotine.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 3, 35, 'Glava rodova u domu Merarijevu bijaše Suriel, sin Abihajilov. Oni su taborovali sa sjeverne strane Prebivališta.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 3, 36, 'Merarijevci su se brinuli za trenice Prebivališta, za njegove priječnice, za stupce i njihova podnožja, za sav njegov pribor i za sve što spada na njegovu službu.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 3, 37, 'Povrh toga, za stupove uokolo predvorja, njihova podnožja, kočiće i užeta.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 3, 38, 'Pred Prebivalištem prema istoku, pred Šatorom sastanka s istočne strane, utaborivali se Mojsije, Aron i njihovi sinovi, kojima je u ime Izraelaca bila povjerena služba u Svetištu. Svjetovnjak koji bi se približio imao se pogubiti.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 3, 39, 'Svih popisanih Levijevaca od jednoga mjeseca naviše, koje je na Jahvinu zapovijed po njihovim rodovima popisao Mojsije i Aron, bijaše dvadeset i dvije tisuće.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 3, 40, 'Jahve rekne Mojsiju: \"Popiši sve muške prvorođence izraelske od jednoga mjeseca naviše te načini popis njihovih imena.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 3, 41, 'I levite dodijeli meni - ja sam Jahve - namjesto svih prvorođenaca izraelskih, a stoku levitsku namjesto sve prvenčadi stoke izraelske.\"');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 3, 42, 'Tako Mojsije popiše sve prvorođence izraelske, kako mu je Jahve naredio.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 3, 43, 'Svih muških prvorođenaca od jednoga mjeseca naviše bijaše u popisu imena dvadeset i dvije tisuće i dvije stotine sedamdeset i tri.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 3, 44, 'Tada Jahve reče Mojsiju:');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 3, 45, '\"Uzmi levite namjesto svih prvorođenaca izraelskih, a stoku levitsku namjesto stoke njihove; leviti neka budu moji. Ja sam Jahve.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 3, 46, 'A za otkupninu dvjesta sedamdeset i triju izraelskih prvorođenaca što ih je više nego levita,');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 3, 47, 'uzmi pet šekela po glavi, uzmi ih prema hramskom šekelu: dvadeset gera - jedan šekel.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 3, 48, 'Onda podaj taj novac Aronu i njegovim sinovima za otkupninu onih kojih je odviše.\"');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 3, 49, 'Tako Mojsije primi taj novac kao otkupninu za prvorođence koji su nadilazili broj onih koje su leviti otkupili.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 3, 50, 'Od izraelskih je prvorođenaca primio u srebru tisuću trista šezdeset i pet šekela hramske mjere.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 3, 51, 'Po nalogu Jahvinu Mojsije predade novac te otkupnine Aronu i njegovim sinovima, kako je Jahve Mojsiju naredio.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 4, 1, 'Jahve reče Mojsiju i Aronu:');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 4, 2, '\"Izdvojite između sinova Levijevih glavare Kehatovih sinova po rodovima i porodicama njihovim:');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 4, 3, 'od trideset godina naviše, sve do pedeset godina - sve koji mogu ući u red da vrše službe u Šatoru sastanka.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 4, 4, 'A služba je Kehatovih sinova u Šatoru sastanka: briga za svetinje nad svetinjama.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 4, 5, 'Kad se tabor diže na put, neka uđu Aron i njegovi sinovi te skinu zaštitnu zavjesu i njom pokriju Kovčeg svjedočanstva.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 4, 6, 'Neka onda na nj stave pokrivalo od fine kože, a po njemu neka razastru platno, potpuno ljubičasto. Potom neka Kovčegu namjeste motke.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 4, 7, 'Po stolu prinošenja neka prostru ljubičasto platno. Onda neka na nj stave zdjele, žlice, krčage i vrčeve za ljevanice. Kruh neprekidnog prinošenja neka također bude na njemu.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 4, 8, 'To neka prekriju tamnocrvenim platnom, a preko njega neka prebace pokrivalo od fine kože. Potom neka stolu namjeste motke.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 4, 9, 'Neka zatim uzmu ljubičasto platno i pokriju svijećnjak za svjetlo i njegove svjetiljke, njegove usekače, njegove lugare i sve posude za ulje kojima se ono poslužuje.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 4, 10, 'Neka ga stave sa svim njegovim priborom na pokrivalo od fine kože pa polože na nosiljku.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 4, 11, 'Po zlatnom žrtveniku neka razastru ljubičasto platno i prekriju ga pokrivalom od fine kože. Potom neka mu namjeste motke.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 4, 12, 'Neka sad uzmu sav pribor što se upotrebljava za službu u Svetištu pa ga stave na ljubičasto platno i onda prekriju pokrivačem od fine kože. Zatim neka sve to polože na nosiljku.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 4, 13, 'Neka pometu pepeo sa žrtvenika i po njemu razastru crveno platno.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 4, 14, 'Na nj neka postave sav pribor što se upotrebljava za službu: kadionike, viljuške, lopatice i zdjele - sve posuđe za žrtvenik. Po njemu onda neka razastru pokrivalo od fine kože. Zatim neka namjeste motke.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 4, 15, 'Pošto Aron i njegovi sinovi završe pokrivanje Svetišta i svega svetog posuđa, u času kad imadne tabor krenuti na put, neka dođu potomci Kehatovi da to ponesu. No svetih se predmeta ne smiju doticati da ne poginu. To je dužnost Kehatovih potomaka u Šatoru sastanka.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 4, 16, 'A Eleazar, sin svećenika Arona, neka se brine za ulje svijećnjaka, za mirisni kad, za trajnu prinosnicu i za ulje pomazanja; neka se brine za sve Prebivalište, za sve što je u njemu - za Svetište i njegovo posuđe.\"');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 4, 17, 'Jahve reče Mojsiju i Aronu:');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 4, 18, '\"Ne dopustite da nestane pleme rodova Kehatovih između levita.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 4, 19, 'Ovako postupajte s njima, da žive i ne izginu primičući se najvećim svetinjama: neka dođu Aron i njegovi sinovi da postave svakoga od njih na njegovu službu i uz njegovu dužnost.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 4, 20, 'Oni neka ne ulaze ni da začas pogledaju Svetište da ne bi poginuli.\"');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 4, 21, 'Jahve reče Mojsiju:');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 4, 22, '\"Popiši i Geršonove sinove po njihovim porodicama i njihovim rodovima, od trideset godina naviše, sve do pedesete godine;');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 4, 23, 'popiši ih sve koji mogu ići u red da vrše službu u Šatoru sastanka.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 4, 24, 'A ovo je služba rodova Geršonovaca pri radu i prenošenju:');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 4, 25, 'neka nose zavjese Prebivališta, Šator sastanka s njegovim krovom, pokrivalo od fine kože što je povrh njega, i zavjesu na ulazu u Šator sastanka;');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 4, 26, 'onda, dvorišne zavjese, zavjesu s vrata na ulazu u predvorje što opkoljuje Prebivalište i žrtvenik, konopce i sav pribor za njihovu službu; što god treba oko tih stvari raditi, neka učine.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 4, 27, 'Neka Geršonovci obavljaju sve svoje dužnosti - sve što imaju nositi i sve što imaju raditi - po nalogu Arona i njegovih sinova. Njihovoj brizi povjerite sve što treba da nose.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 4, 28, 'To je služba rodova Geršonovaca u Šatoru sastanka. Njihova služba neka bude pod vodstvom Itamara, sina svećenika Arona.\"');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 4, 29, '\"Sinove Merarijeve popiši po rodovima i porodicama njihovim.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 4, 30, 'Popiši ih od trideset godina naviše, sve do pedeset godina, koji mogu ući u red da vrše službu u Šatoru sastanka.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 4, 31, 'Za sve njihove službe u Šatoru sastanka dužnost im je da nose trenice za Prebivalište, njegove priječnice, njegove stupce i njegova podnožja;');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 4, 32, 'stupce što okružuju predvorje, njihova podnožja, njihove kočiće, njihove konopce, sa svim priborom za njihovu službu. Poimenično popišite predmete što su im povjereni da ih nose.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 4, 33, 'To je služba rodova Merarijevaca u svemu što imaju činiti u Šatoru sastanka pod vodstvom Itamara, sina svećenika Arona.\"');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 4, 34, 'Mojsije, Aron i glavari zajednice popisali su Kehatove sinove po njihovim rodovima i porodicama -');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 4, 35, 'sve koji mogu ući u red da vrše službu u Šatoru sastanka, od trideset godina naviše, sve do pedeset godina.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 4, 36, 'I popisanih po njihovim rodovima bijaše dvije tisuće sedam stotina i pedeset.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 4, 37, 'To je popis rodova Kehatovaca, svih koji su služili u Šatoru sastanka, a koje popisa Mojsije i Aron na zapovijed što je Jahve dade Mojsiju.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 4, 38, 'Popisanih sinova Geršonovih po njihovim rodovima i porodicama,');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 4, 39, 'od trideset godina naviše, sve do pedeset godina, svih koji mogu ući u red da vrše službu u Šatoru sastanka -');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 4, 40, 'popisanih, dakle, po njihovim rodovima i porodicama bijaše dvije tisuće šest stotina i pedeset.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 4, 41, 'To je popis rodova Geršonovaca, svih koji su služili u Šatoru sastanka, a koje popisa Mojsije i Aron na Jahvinu zapovijed.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 4, 42, 'Popis rodova Merarijevih sinova po njihovim rodovima i porodicama,');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 4, 43, 'od trideset godina naviše, sve do pedeset godina, svih koji mogu ući u red da vrše službu u Šatoru sastanka -');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 4, 44, 'popisanih, dakle, po njihovim rodovima bijaše tri tisuće dvjesta.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 4, 45, 'To je popis Merarijevaca što su ga sastavili Mojsije i Aron na zapovijed koju je Jahve dao Mojsiju.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 4, 46, 'Svih, dakle, popisanih levita koje su popisali Mojsije, Aron i glavari izraelski po njihovim rodovima i porodicama, od trideset godina naviše do pedeset godina -');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 4, 47, 'svih koji su ušli u službu posluživanja i službu prenošenja u Šatoru sastanka -');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 4, 48, 'bilo je osam tisuća pet stotina i osamdeset.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 4, 49, 'Na zapovijed koju je Jahve dao Mojsiju svakoga su unijeli u popis prema onom u čemu je služio i što je prenosio. Popisali su ih kako je Jahve zapovjedio Mojsiju.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 5, 1, 'Jahve reče Mojsiju:');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 5, 2, '\"Naredi Izraelcima da iz tabora odstrane svakoga gubavca, svakoga koji imadne izljev i svakoga koji se onečisti mrtvim tijelom.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 5, 3, 'Odstranite i muške i ženske! Izvan tabora ih istjerajte da ne onečiste svoje tabore u kojima ja boravim među njima.\"');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 5, 4, 'Izraelci tako učine: istjeraju ih iz tabora. Kako je Jahve rekao Mojsiju, tako Izraelci učine.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 5, 5, 'Jahve reče Mojsiju:');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 5, 6, '\"Kaži Izraelcima: Kad koji čovjek ili žena počini bilo kakav grijeh na štetu čovjeka ogriješivši se protiv Jahve, i osjeti se krivim,');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 5, 7, 'neka prizna počinjeni grijeh, nadoknadi štetu što bolje može te još doda tome petinu i dadne onome kome je nanio nepravdu.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 5, 8, 'Ako čovjek ne bi imao bližeg rođaka kome bi se nadoknada mogla uručiti, dužna nadoknada pripada Jahvi za svećenika, ne računajući u to pomirbenoga ovna kojim će svećenik izvršiti nad krivcem obred pomirenja.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 5, 9, 'I svaka podizanica od svih posvećenih stvari što ih Izraelci svećeniku donose njemu pripada.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 5, 10, 'Svakome idu stvari koje je posvetio; i neka svećeniku bude ono što njemu tko dadne.\"');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 5, 11, 'Jahve reče Mojsiju:');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 5, 12, '\"Govori Izraelcima i reci im: Ako nekome žena pođe stranputicom te mu se iznevjeri');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 5, 13, 'i netko s njom legne, ali to ostane sakriveno očima njezina muža i žena ostane neotkrivena iako se oskvrnula te protiv nje ne bude svjedoka budući da u činu nije bila uhvaćena -');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 5, 14, 'i sad muža obuzme duh ljubomore i on postane ljubomoran na svoju ženu koja se oskvrnula; ili ako ga spopadne duh ljubomore te postane ljubomoran na svoju ženu a da se ona nije oskvrnula -');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 5, 15, 'neka taj muž dovede svoju ženu svećeniku. Neka za nju donese prinos: desetinu efe ječmenog brašna. Neka po njemu ne polijeva ulja niti na nj stavlja tamjana, jer to je prinosnica za ljubomoru, spomen-prinosnica da podsjeti na grijeh.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 5, 16, 'Neka svećenik povede tu ženu i postavi je pred Jahvu.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 5, 17, 'Sad neka svećenik uzme posvećene vode u kakvu zemljanu posudu i, uzevši prašine što je na podu Prebivališta, neka je svećenik ubaci u vodu.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 5, 18, 'Pošto je svećenik postavio ženu pred Jahvu, neka joj otkrije glavu a na njezine ruke stavi spomen-prinosnicu, to jest žitnu prinosnicu za ljubomoru, s svećenik neka drži u ruci vodu gorčine i prokletstva.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 5, 19, 'Zatim neka svećenik ženu zakune. Neka joj reče: \'Ako nikad čovjek s tobom nije ležao te ako nisi išla stranputicom i oskvrnula se dok si bila pod vlašću svoga muža, budi pošteđena od ove vode gorčine i prokletstva!');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 5, 20, 'Ali ako si išla stranputicom dok si bila pod vlašću svoga muža te se oskvrnula; ako je koji čovjek osim tvoga muža legao s tobom...\'');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 5, 21, 'Ovdje neka svećenik zakune ženu ovom kletvom: neka joj rekne: Jahve te postavio za prokletstvo i kletvu među tvojim narodom, učinio da ti uvene rodnica i da ti se utroba nadme!');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 5, 22, 'Neka ova voda prokletstva zađe u tvoju utrobu! Trbuh ti se od nje naduo, a rodnica uvenula! - A žena neka poprati: Amen! Amen!');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 5, 23, 'Potom neka ta prokletstva svećenik napiše na list pa ih ispere u vodu gorčine.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 5, 24, 'Onda neka ženu napoji vodom gorčine i prokletstva, da bi se voda gorčine po njoj razišla i napunila je gorkošću.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 5, 25, 'Neka svećenik onda uzme iz ženine ruke prinosnicu za ljubomoru, prinese je pred Jahvom kao žrtvu prikaznicu te je donese na žrtvenik.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 5, 26, 'Zagrabivši od prinosnice punu pregršt kao spomen-žrtvu, neka to sažeže u kad na žrtveniku. Napokon, neka ženu napoji vodom.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 5, 27, 'Pošto je napoji vodom, bude li oskvrnuta iznevjerivši se svome mužu, voda prokletstva ući će u nju i napunit će je gorčinom; njezina će se utroba naduti a rodnica uvenuti - ta će žena postati prokletstvom u svome narodu.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 5, 28, 'A ako žena ne bude oskvrnuta nego nevina, neće joj biti ništa i imat će djece.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 5, 29, 'To je obred u slučaju ljubomore, kad žena pođe stranputicom i oskvrne se dok je pod vlašću svoga muža;');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 5, 30, 'ili kad kojega čovjeka obuzme duh ljubomore te postane ljubomoran na svoju ženu. Neka, dakle, postavi svoju ženu pred Jahvu, a svećenik neka nad njom izvrši sav ovaj obred.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 5, 31, 'Neka je muž slobodan od krivnje, a žena neka snosi svoju krivnju.\"');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 6, 1, 'Jahve reče Mojsiju:');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 6, 2, '\"Govori Izraelcima i reci im: \'Ako tko, bilo čovjek ili žena, položi nazirejski zavjet te se posveti Jahvi,');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 6, 3, 'neka se suzdržava od vina i svakoga opojnog pića. Neka ne pije ni ukiseljena vina niti ukiseljena opojnog pića; a niti kakva soka od grožđa neka ne pije; neka ne jede grožđa, ni svježa ni suha.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 6, 4, 'Sve vrijeme svoga nazireata ne smije jesti ništa što rađa lozov trs - od zelena grožđa do komine.\'');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 6, 5, 'Sve dok traje njegov nazirejski zavjet, neka britva ne prelazi preko njegove glave; dok se ne navrši vrijeme što ga je Jahvi zavjetovao, neka bude posvećen i pusti kose da mu slobodno rastu na glavi.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 6, 6, 'Za sve vrijeme svoga zavjeta Jahvi neka se ne primiče nikakvu mrtvacu.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 6, 7, 'Neka se ne onečišćuje ni zbog svoga oca, ni zbog svoje majke, svoga brata ili svoje sestre ako bi umrli, jer na svojoj glavi nosi posvećenje svoga Boga.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 6, 8, 'Sve vrijeme svoga nazireata on je posvećen Jahvi.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 6, 9, 'Umre li tko nenadanom smrću pokraj njega, onečistivši tako njegovu posvećenu glavu, neka na dan svoga očišćenja obrije svoju glavu - neka je obrije sedmoga dana.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 6, 10, 'A osmoga dana neka donese svećeniku, na ulazu u Šator sastanka, dvije grlice ili dva golubića.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 6, 11, 'Neka svećenik prinese jedno kao žrtvu okajnicu, a drugo kao žrtvu paljenicu, zatim neka nad njim izvrši obred pomirenja zbog ljage kojom se okaljao uz mrtvaca. Toga dana neka posveti svoju glavu;');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 6, 12, 'neka zavjetuje Jahvi dane svoga nazireata; neka donese jednogodišnjeg janjca kao žrtvu naknadnicu. Prijašnje vrijeme neka se ne računa, jer je njegov nazireat bio oskvrnjen.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 6, 13, 'Ovo je obred za nazirejca: na dan kad se navrši vrijeme njegova nazireata, neka ga dovedu na ulaz Šatora sastanka.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 6, 14, 'Kao svoj prinos neka Jahvi donese: jednogodišnjeg janjca bez mane za žrtvu paljenicu; jednogodišnje žensko janje, bez mane, za žrtvu okajnicu; jednoga ovna, bez mane, za žrtvu pričesnicu;');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 6, 15, 'nadalje, košaru neukvasanih pogača od najboljeg brašna, u ulju zamiješenih i neukvasanih kolača, namazanih uljem, s njihovim prinosnicama i ljevanicama.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 6, 16, 'Svećenik, pošto to donese pred Jahvu, neka prinese njegovu okajnicu i paljenicu.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 6, 17, 'Zatim neka prinese ovna Jahvi kao žrtvu pričesnicu zajedno s košarom neukvasanih pogača. I njegovu prinosnicu i njegovu ljevanicu neka prinese svećenik.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 6, 18, 'Na ulazu u Šator sastanka neka nazirejac obrije svoju posvećenu glavu i, uzevši uvojke sa svoje posvećene glave, neka ih stavi na vatru što gori pred žrtvom pričesnicom.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 6, 19, 'Zatim neka svećenik uzme kuhano pleće ovna, jednu neukvasanu pogaču iz košare i jedan neukvasani kolač i stavi to na ruke nazirejcu pošto ovaj obrije svoje posvećene kose.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 6, 20, 'Neka to svećenik prinese kao žrtvu prikaznicu pred Jahvom. To je svetinja što pripada svećeniku, osim grudi prikaznice i stegna podizanice. Poslije toga nazirejac može piti vina.\"');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 6, 21, 'Ovo je obred nazirejca, ne računajući ono što bi još mogla prinijeti njegova ruka. Ako je povrh svoga nazireata obećao kakav dar, neka povrh obreda svoga nazireata učini kako je zavjetovao.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 6, 22, 'Jahve reče Mojsiju:');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 6, 23, '\"Reci Aronu i njegovim sinovima: \'Ovako blagoslivljajte Izraelce govoreći im:');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 6, 24, 'Neka te blagoslovi Jahve i neka te čuva!');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 6, 25, 'Neka te Jahve licem svojim obasja, milostiv ti bude!');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 6, 26, 'Neka pogled svoj Jahve svrati na te i mir ti donese!\' Tako neka stavljaju moje ime nad sinove Izraelove, i ja ću ih blagoslivljati.\"');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 6, 27, '');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 7, 1, 'U onaj dan kad Mojsije završi podizanje Prebivališta i kad ga pomaza i posveti sa svim njegovim posuđem, a tako i žrtvenik sa svim njegovim priborom,');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 7, 2, 'pristupe glavari izraelski, starješine njihovih pradjedovskih domova, to jest knezovi plemenski koji su vodili popisivanje,');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 7, 3, 'i dovedu svoje prinose pred Jahvu: šestora teretna kola i dvanaest volova - jedna kola za dvojicu glavara i vola za svakoga pojedinoga. Dovedu ih pred Prebivalište.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 7, 4, 'Tada Jahve progovori Mojsiju:');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 7, 5, '\"Primi to od njih za upotrebu pri službi u Šatoru sastanka; onda to podaj svakome levitu prema njegovoj službi.\"');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 7, 6, 'Mojsije uze kola i volove pa ih dade levitima.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 7, 7, 'Dvoja kola i četiri vola dade Geršonovcima prema njihovoj službi,');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 7, 8, 'a četvera kola i osam volova dade Merarijevcima prema njihovoj službi pod vodstvom Itamara, sina svećenika Arona.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 7, 9, 'Kehatovcima nije dao ništa, jer je njihova zadaća bila nositi posvećene predmete na ramenima.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 7, 10, 'Tada glavari prinesu prinos za posvetu žrtvenika na dan njegova pomazanja. Dok su glavari prinosili svoje prinose pred žrtvenik,');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 7, 11, 'Jahve progovori Mojsiju: \"Svakoga dana neka po jedan glavar donese svoj prinos za posvetu žrtvenika!\"');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 7, 12, 'Prvoga dana donese svoj prinos Nahšon, sin Aminadabov, od plemena Judina.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 7, 13, 'Njegov je prinos bio: jedna srebrna zdjela teška sto trideset šekela i jedan srebrni kotlić od sedamdeset šekela, prema hramskom šekelu; jedno i drugo bijaše napunjeno najboljim brašnom, zamiješenim u ulju, za prinosnicu.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 7, 14, 'Onda jedna zlatna posudica od deset šekela puna tamjana;');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 7, 15, 'jedan junac, jedan ovan, jedno janje od godinu dana za paljenicu;');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 7, 16, 'jedan jarac za žrtvu okajnicu,');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 7, 17, 'a za žrtvu pričesnicu: dva vola, pet ovnova, pet kozlića i pet jednogodišnjih janjaca. To je bio prinos Nahšona, Aminadabova sina.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 7, 18, 'Drugoga dana donese svoj prinos Netanel, sin Suarov, glavar Jisakarovaca.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 7, 19, 'Za svoj prinos donio je: jednu srebrnu zdjelu tešku sto trideset šekela, jedan srebrni kotlić od sedamdeset šekela, prema hramskom šekelu; oboje puno najboljeg brašna, zamiješena u ulju, za prinosnicu;');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 7, 20, 'onda jednu zlatnu posudicu od deset šekela punu tamjana;');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 7, 21, 'jednog junca, jednoga ovna, jedno janje od godinu dana za paljenicu;');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 7, 22, 'jednog jarca za okajnicu,');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 7, 23, 'a za pričesnicu: dva vola, pet ovnova, pet kozlića i pet jednogodišnjih janjaca. To je bio prinos Netanela, Suarova sina.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 7, 24, 'Trećega dana donese svoj prinos glavar Zebulunovaca, Eliab, sin Helonov.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 7, 25, 'Njegov je prinos bio: jedna srebrna zdjela teška sto trideset šekela i jedan srebrni kotlić od sedamdeset šekela, prema hramskom šekelu; oboje puno najboljeg brašna, zamiješena u ulju, za prinosnicu;');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 7, 26, 'jedna zlatna posudica puna tamjana;');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 7, 27, 'jedan junac, jedan ovan, jedno janje od godinu dana za paljenicu;');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 7, 28, 'jedan jarac za okajnicu,');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 7, 29, 'a za pričesnicu: dva vola, pet ovnova, pet kozlića i pet jednogodišnjih janjaca. To je bio prinos Eliaba, Helonova sina.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 7, 30, 'Četvrtog dana donese svoj prinos glavar Rubenovaca, Elisur, sin Šedeurov.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 7, 31, 'Njegov je prinos bio: jedna srebrna zdjela teška sto trideset šekela, jedan srebrni kotlić od sedamdeset šekela, prema hramskom šekelu; oboje puno najboljeg brašna, zamiješena u ulju, za prinosnicu;');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 7, 32, 'onda jedna zlatna posudica od deset šekela puna tamjana;');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 7, 33, 'jedan junac, jedan ovan, jedno janje od godinu dana za paljenicu;');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 7, 34, 'jedan jarac za okajnicu,');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 7, 35, 'a za pričesnicu: dva vola, pet ovnova, pet kozlića i pet jednogodišnjih janjaca. To je bio prinos Elisura, Šedeurova sina.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 7, 36, 'Petoga dana donese svoj prinos glavar Šimunovaca, Šelumiel, sim Surišadajev.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 7, 37, 'Njegov je prinos bio: jedna srebrna zdjela teška sto trideset šekela, jedan srebrni kotlić od sedamdeset šekela, prema hramskom šekelu; oboje napunjeno najboljim brašnom, zamiješenim u ulju, za prinosnicu;');
