INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 7, 60, 'Devetoga dana donese svoj prinos glavar Benjaminovaca, Abidan, sin Gidonijev.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 7, 61, 'Njegov je prinos bio: jedna srebrna zdjela teška sto trideset šekela i jedan srebrni kotlić od sedamdeset šekela, prema hramskom šekelu; oboje napunjeno najboljim brašnom, zamiješenim u ulju, za prinosnicu;');
