INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 7, 66, 'Desetoga dana donese svoj prinos glavar Danovaca, Ahiezer, sin Amišadajev.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 7, 67, 'Njegov je prinos bio: jedna srebrna zdjela teška sto trideset šekela i jedan srebrni kotlić od sedamdeset šekela, prema hramskom šekelu; oboje napunjeno najboljim brašnom, zamiješenim u ulju, za prikaznicu;');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 7, 68, 'onda jedna zlatna posudica od deset šekela puna tamjana;');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 7, 69, 'jedan junac, jedan ovan, jedno janje od godinu dana za paljenicu;');
