INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 7, 72, 'Jedanaestoga dana donese svoj prinos glavar Ašerovaca, Pagiel, sin Okranov.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 7, 73, 'Njegov je prinos bio: jedna srebrna zdjela teška sto trideset šekela i jedan srebrni kotlić od sedamdeset šekela, prema hramskom šekelu; oboje napunjeno najboljim brašnom, zamiješenim u ulju, za prinosnicu;');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 7, 74, 'onda jedna zlatna posudica od deset šekela puna tamjana;');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 7, 75, 'jedan junac, jedan ovan, jedno janje od godinu dana za paljenicu;');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 7, 76, 'jedan jarac za okajnicu,');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 7, 77, 'a za pričesnicu: dva vola, pet ovnova, pet kozlića i pet jednogodišnjih janjaca. To je bio prinos Pagiela, Okranova sina.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 7, 78, 'Dvanaestoga dana donese svoj prinos glavar Naftalijevaca, Ahira, sin Enanov.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 7, 79, 'Njegov je prinos bio: jedna srebrna zdjela teška sto trideset šekela i jedan srebrni kotlić od sedamdeset šekela, prema hramskom šekelu; oboje napunjeno najboljim brašnom, zamiješenim u ulju, za prinosnicu;');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 7, 80, 'onda jedna zlatna posudica od deset šekela puna tamjana;');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 7, 81, 'jedan junac, jedan ovan, jedno janje od godinu dana za paljenicu;');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 7, 82, 'jedan jarac za okajnicu,');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 7, 83, 'a za pričesnicu: dva vola, pet ovnova, pet kozlića i pet jednogodišnjih janjaca. To je bio prinos Ahire, Enanova sina.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 7, 84, 'To su bili prinosi glavara izraelskih za posvetu žrtvenika na dan kad bijaše pomazan: dvanaest srebrnih zdjela, dvanaest srebrnih kotlića i dvanaest zlatnih posudica.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 7, 85, 'Svaka srebrna zdjela težila je sto trideset šekela; svaki kotlić sedamdeset šekela. Svega srebra u posuđu bilo je dvije tisuće i četiri stotine hramskih šekela.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 7, 86, 'Zlatnih posudica punih tamjana bilo je dvanaest, svaka posudica težila je deset hramskih šekela. Sve zlato u posudicama težilo je sto dvadeset šekela.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 7, 87, 'Sve stoke za paljenicu: dvanaest junaca, dvanaest ovnova, dvanaest jednogodišnjih janjaca s njihovim prinosima. Za okajnicu dvanaest jaraca.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 7, 88, 'Sve stoke za pričesnicu: dvadeset i četiri vola, šezdeset ovnova, šezdeset kozlića i šezdeset janjaca od godine dana. To je bio prinos za posvetu žrtvenika pošto bijaše pomazan.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 7, 89, 'Kad bi Mojsije ulazio u Šator sastanka da razgovara s Njim, slušao bi glas kako mu govori ozgo s Pomirilišta što je bilo na Kovčegu svjedočanstva, među dva kerubina. Tada bi mu govorio.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 8, 1, 'Jahve reče Mojsiju:');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 8, 2, '\"Govori Aronu i reci mu: \'Kad budeš palio svjetionice, neka sedam svjetionica svijetli na prednjoj strani svijećnjaka.\'\"');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 8, 3, 'Aron i učini tako: smjesti svjetionice na prednju stranu svijećnjaka, kako je Jahve Mojsiju naredio.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 8, 4, 'Svijećnjak bijaše skovan od zlata; skovan od svoga podnožja do svoje čaške. Svijećnjak je bio napravljen prema uzorku što ga je Jahve pokazao Mojsiju.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 8, 5, 'Jahve reče Mojsiju:');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 8, 6, '\"Uzmi levite između Izraelaca i očisti ih!');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 8, 7, 'Ovako s njima postupi da ih očistiš: poškropi ih vodom za okajavanje; a oni neka se obriju po svemu svome tijelu, neka operu svoju odjeću i bit će čisti.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 8, 8, 'Neka zatim uzmu jednog junca i prinosnicu od najboljeg brašna, zamiješena u ulju. A ti uzmi drugog junca za okajnicu.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 8, 9, 'Dovedi onda levite pred Šator sastanka i skupi svu izraelsku zajednicu.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 8, 10, 'Kad dovedeš levite pred Jahvu, neka Izraelci stave na njih svoje ruke.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 8, 11, 'Neka zatim Aron prinese levite, kao prikaznicu pred Jahvom, u ime Izraelaca. Tako će njihov posao biti da služe Jahvi.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 8, 12, 'Neka potom leviti stave svoje ruke juncima na glave; onda jednoga prinesi kao okajnicu, a drugoga kao paljenicu Jahvi, da se izvrši obred pomirenja nad levitima.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 8, 13, 'Stavivši levite pred Arona i njegove sinove, prikaži ih Jahvi žrtvom prikaznicom.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 8, 14, 'Odvoji tako levite između Izraelaca da budu moji.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 8, 15, 'Poslije toga, pošto ih očistiš i prineseš žrtvom prikaznicom, neka leviti uđu u službu Šatora sastanka.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 8, 16, 'Jer oni su između Izraelaca meni potpuno darovani; njih sam sebi uzeo namjesto svih koji otvaraju majčinu utrobu, svih izraelskih prvorođenaca.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 8, 17, 'Svako, naime, prvorođenče među Izraelcima, kako čedo tako i živinče, moje je; sebi sam ih posvetio onoga dana kad sam pobio svu prvorođenčad u zemlji egipatskoj.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 8, 18, 'Tako sam uzeo levite namjesto svih izraelskih prvorođenaca.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 8, 19, 'I predao sam levite između Izraelaca kao dar Aronu i njegovim sinovima da mjesto Izraelaca obavljaju službu u Šatoru sastanka; da nad njima obavljaju obred pomirenja, tako da kakva nedaća ne bi pogodila Izraelce što bi se približili Svetištu.\"');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 8, 20, 'Mojsije, Aron i sva izraelska zajednica učine tako s levitima; kako je Jahve naredio Mojsiju za levite, tako im Izraelci i učine.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 8, 21, 'Leviti se očiste i operu svoju odjeću; onda ih Aron prinese pred Jahvu žrtvom prikaznicom. Aron nad njima obavi obred pomirenja da ih očisti.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 8, 22, 'Poslije toga uđu leviti u službu u Šator sastanka, u nazočnosti Arona i njegovih sinova. Kako je Jahve naredio Mojsiju za levite, tako su s njima i uradili.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 8, 23, 'Jahve reče Mojsiju:');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 8, 24, '\"I ovo se tiče levita: od dvadeset i pet godina naviše neka leviti po redu preuzimaju službu u Šatoru sastanka.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 8, 25, 'A kad kome bude pedeset godina, neka istupi iz službe i neka više ne služi.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 8, 26, 'Ali može pomagati svojoj braći u vršenju njihovih dužnosti u Šatoru sastanka, no sam ne mora vršiti službe. Tako postupi prema levitima za njihove dužnosti!\"');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 9, 1, 'Prvoga mjeseca druge godine nakon izlaska iz zemlje egipatske Jahve reče Mojsiju u Sinajskoj pustinji:');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 9, 2, '\"Neka Izraelci slave Pashu u njezino vrijeme.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 9, 3, 'Slavite je u njezino vrijeme, u suton, četrnaestoga dana ovoga mjeseca; slavite je prema svim njezinim propisima i običajima.\"');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 9, 4, 'Tako Mojsije reče Izraelcima da slave Pashu.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 9, 5, 'I oni su je slavili u Sinajskoj pustinji, u suton, prvoga mjeseca, četrnaestoga dana u mjesecu. Kako je god Jahve Mojsiju naredio, tako su Izraelci i učinili.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 9, 6, 'A bijaše ljudi onečišćenih mrtvacem; ti nisu mogli slaviti Pashu onoga dana. Dođu tako pred Mojsija i Arona istoga dana');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 9, 7, 'pa reknu: \"Mrtvacem smo se onečistili; ipak, zašto bi nam bilo uskraćeno prinositi Jahvi žrtvu u njezino vrijeme usred Izraelovih sinova?\"');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 9, 8, 'Mojsije im reče: \"Strpite se da čujem što će Jahve za vas odrediti.\"');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 9, 9, 'I Jahve reče Mojsiju:');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 9, 10, '\"Ovako kaži Izraelcima: \'Kad se tko između vas ili vaših potomaka onečisti mrtvacem ili je na daleku putu, neka ipak slavi Pashu Jahvi.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 9, 11, 'Neka je slave u suton četrnaestog dana drugoga mjeseca. Neka je blaguju s neukvasanim kruhom i gorkim zeljem;');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 9, 12, 'neka ništa od nje ne ostavljaju za ujutro; neka ni jedne kosti na njoj ne lome. Neka je slave prema propisima Pashe.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 9, 13, 'Onaj koji je čist a ne bude na putovanju pa ipak propusti proslaviti Pashu, neka se iskorijeni iz svoga naroda. Budući da nije prinio Jahvi žrtve u njezino vrijeme, takav neka snosi svoju krivnju.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 9, 14, 'Ako s vama boravi stranac i Pashu prinosi Jahvi, neka je prinosi prema propisima i običajima njezinim. Neka bude jedan zakon za vas, bio to stranac ili domorodac.\'\"');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 9, 15, 'Na dan kad je podignuto Prebivalište oblak prekri Prebivalište, Šator svjedočanstva. Od večeri do jutra stajao je u obliku ognja nad Prebivalištem.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 9, 16, 'Tako ga je oblak neprestano zaklanjao, a noću bijaše poput ognja.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 9, 17, 'Kad bi se god oblak digao sa Šatora, Izraelci bi poslije toga krenuli. A gdje bi oblak stao, tu bi se i Izraelci utaborili.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 9, 18, 'Na zapovijed Jahvinu Izraelci su kretali na put i na Jahvinu se zapovijed utaborivali. Sve vrijeme što bi oblak stajao nad Prebivalištem oni su taborovali.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 9, 19, 'Ako bi oblak dugo stajao nad Prebivalištem, Izraelci su slušali Jahvin nalog i ne bi polazili na put.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 9, 20, 'Ali ako bi se dogodilo da oblak ostane nad Prebivalištem malo vremena, oni bi se na Jahvinu zapovijed utaborili i na Jahvinu zapovijed opet krenuli na put.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 9, 21, 'Ako bi se oblak digao pošto se zadržao od večeri do jutra, oni bi tada ujutro krenuli na put. Danju ili noću, kad bi se oblak digao, oni bi krenuli na put.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 9, 22, 'Dva dana ili mjesec ili godinu - dok bi oblak ostajao nad Prebivalištem - Izraelci su taborovali, ne krećući na put, a čim bi se digao, oni bi krenuli.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 9, 23, 'Po zapovijedi Jahvinoj stajahu u taboru i po zapovijedi Jahvinoj kretahu na put. Držali su se Jahvina naloga, kako Jahve bijaše zapovjedio Mojsiju.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 10, 1, 'Jahve reče Mojsiju:');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 10, 2, '\"Napravi sebi dvije trube; napravi ih od kovana srebra. Neka ti služe za sazivanje zajednice i za pokretanje tabora.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 10, 3, 'Kad se u njih zatrubi, neka se sva zajednica skupi k tebi na ulazu u Šator sastanka.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 10, 4, 'Ako li se zatrubi u jednu, neka se k tebi skupe glavari izraelski, tisućnici.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 10, 5, 'Kad popratite trubljenje bojnim poklikom, neka krenu logori utaboreni na istočnoj strani.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 10, 6, 'Kad popratite trubljenje bojnim poklikom po drugi put, neka krenu logori utaboreni s južne strane: neka se trubljenje poprati bojnim poklikom da oni krenu.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 10, 7, 'Trubite i da skupite zajednicu, ali bez bojnog poklika.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 10, 8, 'Neka u trube trube svećenici, sinovi Aronovi. Neka vam to bude trajnom uredbom za vaše naraštaje.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 10, 9, 'Kad u svojoj zemlji pođete u rat na neprijatelja koji vas pritisne, zaorite na trube s bojnim poklikom, i Jahve, Bog vaš, sjetit će se vas i bit ćete izbavljeni od svojih neprijatelja.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 10, 10, 'Na dan svoje svečanosti, svojih blagdana ili svojih mjesečevih mlađaka, dok prinosite svoje paljenice i pričesnice, trubite u trube. Neka to za vas bude spomen pred Bogom vašim. Ja sam Jahve, Bog vaš.\"');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 10, 11, 'Druge godine drugoga mjeseca dvadesetog dana u mjesecu diže se oblak iznad Prebivališta svjedočanstva.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 10, 12, 'Tada se Izraelci zapute iz Sinajske pustinje na svoja putovanja. Oblak se zaustavi u pustinji Paranu.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 10, 13, 'Tako na Jahvinu zapovijed danu Mojsiju krenuše prvi put.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 10, 14, 'Prva je krenula zastava tabora Judinih sinova u svojim četama. Nad njihovom vojskom bijaše Nahšon, sin Aminadabov;');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 10, 15, 'nad vojskom plemena Jisakarovaca stajaše Netanel, sin Suarov,');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 10, 16, 'a nad vojskom plemena Zebulunovaca bijaše Eliab, sin Helonov.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 10, 17, 'Zatim, pošto je rastavljeno Prebivalište, krenuše Geršonovci i Merarijevci noseći Prebivalište.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 10, 18, 'Potom krenu zastava tabora Rubenova u svojim četama. Nad njihovom vojskom bijaše Elisur, sin Šedeurov;');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 10, 19, 'nad vojskom plemena Šimunovaca stajao je Šelumiel, sin Surišadajev;');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 10, 20, 'nad vojskom plemena Gadovaca bio je Elijasaf, sin Deuelov.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 10, 21, 'Potom krenuše Kehatovci noseći posvećene predmete. Tako je Prebivalište bilo podignuto prije njihova dolaska.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 10, 22, 'Onda krenu zastava tabora Efrajimovaca u svojim četama. Nad njihovom vojskom bijaše Elišama, sin Amihudov,');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 10, 23, 'nad vojskom plemena Manašeovaca stajaše Gamliel, sin Pedahsurov;');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 10, 24, 'nad vojskom plemena Benjaminovaca bijaše Abidan, sin Gidonijev.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 10, 25, 'A kao zalazna straža za sve tabore krenu, u svojim četama, zastava tabora Danovaca. Nad njihovom je vojskom stajao Ahiezer, sin Amišadajev.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 10, 26, 'Nad vojskom plemena Ašerovaca bio je Pagiel, sin Okranov;');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 10, 27, 'a nad vojskom plemena Naftalijevaca bio je Ahira, sin Enanov.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 10, 28, 'Takav je bio red putovanja Izraelaca svrstanih u svoje čete. Tako su putovali.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 10, 29, 'Mojsije reče Hobabu, sinu Midjanca Reuela, Mojsijeva tasta: \"Zaputili smo se u kraj o kojemu je Jahve rekao: \'Dat ću vam ga!\' Pođi s nama i dobro ćemo ti činiti, jer je Jahve obećao sreću Izraelu.\"');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 10, 30, '\"Ne idem\", odgovori mu, \"nego se vraćam u svoju zemlju; k svojima se vraćam.\"');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 10, 31, '\"Molim te, ne ostavljaj nas!\" - reče. \"Budući da znaš gdje nam se treba u pustinji utaboriti, valjat ćeš nam kao oči.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 10, 32, 'Ako s nama pođeš, dobročinstva koja nam Jahve bude udijelio s tobom ćemo dijeliti.\"');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 10, 33, 'Od Jahvina brda putovali su tri dana hoda. Kovčeg Jahvina saveza išao je pred njima ta tri dana hoda da im potraži mjesto odmora.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 10, 34, 'Danju je opet Jahvin oblak bio nad njima, kako bi se iz tabora zaputili.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 10, 35, 'Kad bi Kovčeg polazio, Mojsije bi rekao: \"Ustani, Jahve! Neprijatelji tvoji neka se rasprše! Koji tebe mrze nek\' bježe pred tobom!\"');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 10, 36, 'A kad bi se zaustavljao, popratio bi: \"Vrati se, o Jahve! Izraelu ti si tisuće bezbrojne!\"');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 11, 1, 'I stade narod zlobno mrmljati u Jahvine uši. Kad to ču Jahve, planu gnjevom. Jahvin oganj izbi među njima i spali jedan kraj tabora.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 11, 2, 'Narod zavapi Mojsiju, a Mojsije se pomoli Jahvi i oganj se utiša.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 11, 3, 'Ono se mjesto prozva Tabera, jer je Jahvin oganj ondje zaplamtio na njih.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 11, 4, 'Svjetinu koja se oko njih skupila obuzme pohlepa za jelom. Izraelci se opet upuste u jadikovanje govoreći: \"Tko će nas nasititi mesom?');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 11, 5, 'Sjećamo se kako smo u Egiptu jeli badava ribe, krastavaca, dinje, prÓase, luka i češnjaka.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 11, 6, 'Sad nam život vene; nema ničega, osim mÓane, pred našim očima.\"');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 11, 7, 'MÓana je bila kao zrno korijandera i nalik na bdelij.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 11, 8, 'Narod išao naokolo, skupljao je, a onda tro kamenom na kamenoj ploči ili stÓupao u stÓupi. Kuhao ju je u loncu i od nje pravio kolače. Okus joj bijaše kao okus kolača zgotovljena u ulju.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 11, 9, 'Kad bi se noću spuštala rosa po taborištu, s njome bi se spustila i mÓana.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 11, 10, 'Mojsije je slušao kako jadikuje narod u svojim obiteljima, svatko na ulazu u svoj šator. Gnjev Jahvin žestoko planu i Mojsije se ražalosti.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 11, 11, '\"Zašto zlostavljaš slugu svoga?\" - upravi Mojsije riječ Jahvi. \"Zašto nisam stekao milost u tvojim očima kad si na me uprtio teret svega ovog naroda?');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 11, 12, 'Zar je od mene potekao sav ovaj narod? Zar sam ga ja rodio, kad veliš: \'Nosi ga u svome krilu, kao što dojilja nosi dojenče, u zemlju što sam je pod zakletvom obećao njihovim očevima!\'');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 11, 13, 'Odakle meni meso da ga dam svemu ovom puku koji plače oko mene govoreći: \'Daj nam mesa da jedemo!\'');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 11, 14, 'Ja sam ne mogu nositi sav ovaj narod. Preteško je to za me.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 11, 15, 'Ako ćeš ovako sa mnom postupati, radije me ubij, ako sam stekao milost u tvojim očima, da više ne gledam svoga jada.\"');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 11, 16, 'Onda Jahve reče Mojsiju: \"Skupi mi sedamdeset muževa između starješina izraelskih za koje znaš da su starješine narodu i njegovi nadglednici. Dovedi ih u Šator sastanka pa neka ondje zauzmu svoja mjesta s tobom.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 11, 17, 'Ja ću sići i ondje s tobom govoriti; uzet ću nešto duha koji je na tebi i stavit ću ga na njih. Tako će s tobom nositi teret naroda da ga ne nosiš sam.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 11, 18, 'Nadalje, kaži narodu: Za sutra se posvetite i jest ćete mesa, jer ste mrmljali u uši Jahvi govoreći: \'Tko će nas nasititi mesa? U Egiptu nam je bilo dobro.\' Jahve će vam, dakle, dati mesa da jedete.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 11, 19, 'Nećete ga jesti samo jedan dan, ni dva dana, ni pet dana, ni deset dana, ni dvadeset dana,');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 11, 20, 'nego cio mjesec, sve dok vam ne izbije na nosnice i ne ogadi vam se, jer ste odbacili Jahvu koji je među vama mrmljajući pred njim riječima: \'Zašto smo uopće odlazili iz Egipta!\'\"');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 11, 21, '\"Naroda u kojemu se nalazim\", odgovori Mojsije, \"ima šest stotina tisuća pješaka, a ti kažeš: \'Mesa ću im dati da jedu mjesec dana.\'');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 11, 22, 'Može li im se naklati sitne i krupne stoke da im dostane? Mogu li im se sve ribe iz mora zgrnuti da im bude dosta?\"');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 11, 23, 'Jahve reče Mojsiju: \"Zar je ruka Jahvina tako kratka? Sad ćeš vidjeti hoće li se obistiniti moja riječ ili neće.\"');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 11, 24, 'Mojsije izađe i kaza narodu Jahvine riječi. Onda skupi sedamdeset muževa između narodnih starješina i smjesti ih oko Šatora.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 11, 25, 'Jahve siđe u oblaku i poče s njim govoriti. Zatim uze od duha koji bijaše na njemu i stavi na onu sedamdesetoricu starješina. Kad duh počinu na njima, počeše prorokovati, ali to više nikad ne učiniše.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 11, 26, 'Dvojica ostadoše u taboru. Jednome je bilo ime Eldad, a drugome Medad. Duh je i na njima počinuo - bili su i oni među upisanima, premda nisu došli u tabor - te počeše u taboru prorokovati.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 11, 27, 'Neki mladić otrča te javi Mojsiju: \"Eldad i Medad\", reče, \"prorokuju u taboru!\"');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 11, 28, 'Jošua, sin Nunov, koji je posluživao Mojsija od svoje mladosti, prozbori i reče: \"Mojsije, gospodaru moj, ušutkaj ih!\"');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 11, 29, 'Mojsije mu odgovori: \"Zar si zavidan zbog mene! Oh, kad bi sav narod Jahvin postao prorok! Kad bi Jahve na njih izlio svoga duha!\"');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 11, 30, 'Potom se Mojsije i starješine izraelske vrate u tabor.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 11, 31, 'Tada Jahve zapovjedi te zapuhnu vjetar i nanese prepelice od mora i sasu ih na tabor, na dan hoda i s ove i s one strane tabora, na dva lakta iznad zemlje.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 11, 32, 'Narod je ustao te je toga cijeloga dana, svu noć i cio sutrašnji dan skupljao prepelice. Onaj tko ih je skupio najmanje imao je deset homera.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 11, 33, 'Zatim ih razastriješe oko tabora. Meso još bijaše među njihovim zubima - još ga nisu prožvakali - kadli planu Jahvin gnjev protiv naroda: Jahve udari narod strašnim pomorom.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 11, 34, 'Ono se mjesto prozva Kibrot Hataava, jer su ondje pokopali one koji se bijahu polakomili.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 11, 35, 'Iz Kibrot Hataave narod se zaputi u Haserot. I utabori se u Haserotu.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 12, 1, 'A Mirjam i Aron uzeše rogoboriti protiv Mojsija zbog žene Kušanke kojom se oženio; jer bijaše uzeo za ženu jednu Kušanku.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 12, 2, '\"Zar je samo Mojsiju govorio Jahve?\" - rekoše mu. \"Zar i nama nije govorio?\" Jahve to ču.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 12, 3, 'Mojsije je bio veoma skroman čovjek, najskromniji čovjek na zemlji.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 12, 4, 'I odmah reče Jahve Mojsiju, Aronu i Mirjami: \"Vas se troje pojavite u Šatoru sastanka.\" Njih se troje pojavi.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 12, 5, 'U stupu oblaka siđe Jahve te stade na ulazu u Šator. Zovnu Arona i Mirjamu. Kad njih dvoje istupi naprijed,');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 12, 6, 'reče Jahve: \"Saslušajte riječi moje: Nađe li se među vama prorok, u viđenju njemu ja se javljam, u snu njemu progovaram.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 12, 7, 'Ali nije tako sa slugom mojim Mojsijem. Od svih u kući mojoj najvjerniji je on.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 12, 8, 'Iz usta u usta njemu ja govorim, očevidnošću, a ne zagonetkama, i lik Jahvin on smije gledati. Kako se onda niste bojali govoriti protiv sluge moga Mojsija?\"');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 12, 9, 'Uskipjevši gnjevom na njih, Jahve ode.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 12, 10, 'Čim se od šatora oblak udaljio, gle! Mirjam ogubavi, kao snijegom posuta. Aron se okrenu prema Mirjami, a to guba na njoj.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 12, 11, 'Tada rekne Aron Mojsiju: \"Gospodaru moj, ne svaljuj na nas kazne za grijeh koji smo u ludosti počinili i kojega smo krivci.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 12, 12, 'Ne daj da ona ostane kao mrtvo dijete kojemu je već na izlasku iz majčine utrobe meso napol uništeno!\"');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 12, 13, 'Tada zavapi Mojsije Jahvi: \"Bože, molim te, ozdravi je!\"');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 12, 14, '\"Da joj je otac njezin pljunuo u lice\", reče Jahve Mojsiju, \"zar se ne bi morala stidjeti sedam dana? Neka i ona bude odvojena izvan tabora sedam dana, pa neka se poslije opet pripusti.\"');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 12, 15, 'Tako je Mirjam bila odvojena izvan tabora sedam dana. Narod nije na put polazio dok Mirjam nije opet bila pripuštena.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 12, 16, 'Poslije toga narod krenu iz Haserota i utabori se u pustinji Paranu.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 13, 1, 'Jahve reče Mojsiju:');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 13, 2, '\"Pošalji ljude, po jednoga čovjeka iz pojedinog pradjedovskog plemena, da izvide kanaansku zemlju, koju dajem Izraelcima. Pošaljite sve njihove glavare!\"');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 13, 3, 'Na Jahvinu zapovijed Mojsije ih posla iz pustinje Parana. Svi ti ljudi bijahu glavari Izraelaca.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 13, 4, 'A ovo su njihova imena: Šamua, sin Zakurov, od plemena Rubenova;');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 13, 5, 'Šafat, sin Horijev, od plemena Šimunova;');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 13, 6, 'Kaleb, sin Jefuneov, od plemena Judina;');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 13, 7, 'Jigal, sin Josipov, od plemena Jisakarova;');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 13, 8, 'Hošea, sin Nunov, od plemena Efrajimova;');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 13, 9, 'Palti, sin Rafuov, od plemena Benjaminova;');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 13, 10, 'Gadiel, sin Sodijev, od plemena Zebulunova;');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 13, 11, 'Gadi, sin Susijev, od plemena Josipova, od plemena Manašeova;');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 13, 12, 'Amiel, sin Gemalijev, od plemena Danova;');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 13, 13, 'Setur, sin Mikaelov, od plemena Ašerova;');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 13, 14, 'Nahbi, sin Vofsijev, od plemena Naftalijeva;');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 13, 15, 'Geuel, sin Makijev, od plemena Gadova.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 13, 16, 'To su imena ljudi koje je Mojsije poslao da izvide zemlju. A Hošeu, sina Nunova, Mojsije prozva Jošuom.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 13, 17, 'Posla ih Mojsije da izvide kanaansku zemlju pa im reče: \"Idite gore u Negeb, onda se popnite na brdo.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 13, 18, 'Razgledajte zemlju kakva je. Je li narod koji u njoj živi jak ili slab, malobrojan ili mnogobrojan?');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 13, 19, 'Kakva je zemlja u kojoj živi: dobra ili rđava? Kakvi su gradovi u kojima borave: otvoreni ili utvrđeni?');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 13, 20, 'Kakvo je tlo: plodno ili mršavo? Ima li po njemu drveća ili nema? Odvažni budite i ponesite plodova te zemlje.\" Bilo je upravo vrijeme ranog grožđa.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 13, 21, 'Odu oni gore da izvide zemlju od pustinje Sina do Rehoba, koji je na ulazu u Hamat.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 13, 22, 'Popnu se u Negeb i dođu do Hebrona, gdje su se nalazili Ahiman, Šešaj i Talmaj, Anakovi potomci. - Hebron je osnovan sedam godina prije nego Soan u Egiptu. -');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 13, 23, 'Kada stigoše u Dolinu Eškol, odrezaše ondje lozu s grozdom i ponesoše ga, udvoje, na motki; ponesoše i mogranja i smokava.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 13, 24, 'Ono se mjesto prozva Dolina Eškol zbog grozda koji su ondje Izraelci odrezali.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 13, 25, 'Nakon četrdeset dana vrate se iz zemlje koju su izviđali.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 13, 26, 'Odu k Mojsiju i Aronu i svoj izraelskoj zajednici u Kadeš, u Paranskoj pustinji. Podnesu njima i svoj zajednici izvještaj, a onda im pokažu plodove zemlje.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 13, 27, 'Izvijeste ga oni: \"Išli smo u zemlju u koju si nas poslao. Zaista njome teče med i mlijeko. Evo njezinih plodova.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 13, 28, 'Ali je jak narod koji u onoj zemlji živi, gradovi su utvrđeni i vrlo veliki. A vidjesmo ondje i potomke Anakove.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 13, 29, 'Amalečani borave u negepskom kraju: Hetiti, Jebusejci i Amorejci žive u brdu; a Kanaanci se nalaze uz more i duž Jordana.\"');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 13, 30, 'Kaleb ušutka narod oko Mojsija i progovori: \"Krenimo ne oklijevajući i zauzmimo je, jer je možemo nadvladati!\"');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 13, 31, 'Ali ljudi što su s njim išli odvratiše: \"Ne možemo ići na onaj narod jer je jači od nas.\"');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 13, 32, 'I počnu ozloglašivati Izraelcima zemlju koju su izviđali: \"Zemlja kroz koju smo prošli da je izvidimo zemlja je što proždire svoje stanovništvo. Sav narod što ga u njoj vidjesmo ljudi su krupna stasa.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 13, 33, 'Vidjesmo ondje i divove - Anakovo potomstvo od divova. Činilo nam se da smo prema njima kao skakavci. Takvi bijasmo i njima.\"');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 14, 1, 'Tada zagraja sva zajednica i poče vikati. I te noći narod plakaše.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 14, 2, 'Svi su Izraelci mrmljali protiv Mojsija i Arona. Sva im je zajednica govorila: \"Kamo sreće da smo pomrli u zemlji egipatskoj! Ili da smo pomrli u ovoj pustinji!');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 14, 3, 'Zašto nas Jahve vodi u tu zemlju da padnemo od mača a žene naše i djeca da postanu roblje! Zar nam ne bi bilo bolje da se vratimo u Egipat!\"');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 14, 4, 'Jedan je drugome govorio: \"Postavimo sebi vođu i vratimo se u Egipat!\"');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 14, 5, 'Mojsije i Aron padoše ničice pred svom okupljenom izraelskom zajednicom.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 14, 6, 'A Jošua, sin Nunov, i Kaleb, sin Jefuneov, koji bijahu među onima što su izviđali zemlju, razderaše svoju odjeću.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 14, 7, 'Zatim rekoše svoj zajednici izraelskoj: \"Zemlja kroz koju smo prošli da je istražimo izvanredno je dobra.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 14, 8, 'Ako nam Jahve bude dobrostiv, u tu će nas zemlju dovesti i dat će nam je. To je zemlja u kojoj teče med i mlijeko.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 14, 9, 'Samo, nemojte se buniti protiv Jahve! Ne bojte se naroda one zemlje: tÓa on je zalogaj za nas. Oni su bez zaštite, a s nama je Jahve! Ne bojte ih se!\"');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 14, 10, 'I dok je sva zajednica već mislila da ih kamenuje, pokaza se Slava Jahvina u Šatoru sastanka svima sinovima Izraelovim.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 14, 11, 'Tada reče Mojsiju: \"Dokle će me taj narod prezirati? Dokle mi neće vjerovati unatoč svim znamenjima što sam ih među njima izvodio?');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 14, 12, 'Udarit ću ih pomorom i istrijebiti, a od tebe ću učiniti narod veći i moćniji od njega.\"');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 14, 13, 'Onda Mojsije reče Jahvi: \"Egipćani su shvatili da si ti, svojom moći, izveo ovaj narod između njih.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 14, 14, 'Oni su to kazali žiteljima one zemlje. Već su saznali da si ti, Jahve, usred ovog naroda, kojemu se očituješ licem u lice, i da ti, Jahve, u oblaku stojiš nad njima; da obdan u stupu od oblaka, a obnoć u stupu od ognja ideš pred njima.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 14, 15, 'Zato, ako pobiješ ovaj narod kao jednoga čovjeka, narodi koji su čuli glas o tebi reći će:');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 14, 16, '\'Jahve je bio nemoćan da dovede ovaj narod u zemlju koju mu je pod zakletvom obećao, i zato ih je poubijao u pustinji.\'');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 14, 17, 'Zato neka se snaga moga Gospodina uzvisi, kako si najavio rekavši:');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 14, 18, '\'Jahve je spor na srdžbu, a bogat milosrđem; podnosi opačinu i prijestup, ali krivca ne ostavlja nekažnjena, nego opačinu otaca kažnjava na djeci do trećega i četvrtog koljena.\'');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 14, 19, 'Oprosti krivnju ovome narodu po veličini svoga milosrđa, kao što si vodio ovaj narod od Egipta dovde.\"');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 14, 20, '\"Opraštam po riječi tvojoj\", reče Jahve.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 14, 21, '\"Ali ipak, tako ja živ bio i slave se Jahvine napunila sva zemlja,');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 14, 22, 'ni jedan od ljudi koji su vidjeli slavu moju i znamenja što sam ih izveo u Egiptu i u pustinji, pa me ipak iskušavali već deset puta ne hoteći poslušati moj glas,');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 14, 23, 'neće vidjeti zemlje što sam je pod zakletvom obećao njihovim ocima; nitko od onih koji me preziru neće je vidjeti.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 14, 24, 'A slugu svoga Kaleba, jer je u njemu drukčiji duh i jer mi bijaše poslušan, njega ću ja dovesti u zemlju u koju je išao i njegovi će je potomci zaposjesti! Neka Amalečani i Kanaanci samo ostanu u dolini.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 14, 25, 'Sutra se vratite i krenite u pustinju put Crvenog mora.\"');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 14, 26, 'Još reče Jahve Mojsiju i Aronu:');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 14, 27, '\"Dokle će ta opaka zajednica mrmljati protiv mene? Čuo sam tužbe što ih Izraelci na me dižu.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 14, 28, 'Kaži im: Tako ja živ bio, objavljuje Jahve, kako ste na moje uši govorili, tako ću vam i učiniti.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 14, 29, 'U ovoj pustinji popadat će vaša mrtva tijela: svih vas koji ste ubilježeni u bilo koji vaš popis od dvadeset godina pa naprijed, koji ste rogoborili protiv mene.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 14, 30, 'Nećete ući u zemlju na koju sam svoju ruku digao da vas u njoj nastanim, osim Kaleba, sina Jefuneova, i Jošue, sina Nunova.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 14, 31, 'A vašu djecu, o kojoj kažete da bi postala roblje, njih ću uvesti da nastane zemlju što ste je vi prezreli.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 14, 32, 'A vi? Neka vam tjelesa popadaju u ovoj pustinji!');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 14, 33, 'Vaši sinovi neka lutaju pustinjom četrdeset godina, neka trpe zbog vaše nevjere dok vam ne ispropadaju tjelesa u ovoj pustinji.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 14, 34, 'Prema broju dana u koje ste istraživali zemlju - dana četrdeset, za svaki dan jednu godinu - ispaštajte svoje opačine četrdeset godina. Iskusite što znači mene napustiti.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 14, 35, 'Ja, Jahve, to kažem: tako ću postupiti s ovom opakom zajednicom što se sjatila protiv mene. U ovoj istoj pustinji neka završi! Tu neka izgine.\"');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 14, 36, 'A oni ljudi koje Mojsije bijaše poslao da istraže zemlju i koji su nakon povratka potakli svu zajednicu da rogobori protiv njega ozloglašujući zemlju;');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 14, 37, 'oni, dakle, ljudi koji su zlobno ozloglasili zemlju bijahu pomoreni pred Jahvom.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 14, 38, 'Od onih ljudi koji su išli da istraže zemlju ostadoše na životu jedino Jošua, sin Nunov, i Kaleb, sin Jefuneov.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 14, 39, 'Kad je Mojsije prenio te riječi svim Izraelcima, narod se uvelike ražalosti.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 14, 40, 'I uranivši ujutro počnu se uspinjati na vrh brda govoreći. \"Evo uzlazimo na mjesto o kojem je govorio Jahve jer smo zgriješili.\"');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 14, 41, 'A Mojsije rekne: \"Zašto kršite zapovijed Jahvinu? Nećete uspjeti.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 14, 42, 'Ne penjite se, da vas ne potuku vaši neprijatelji, jer Jahve nije među vama.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 14, 43, 'Ta ondje se pred vama nalaze Amalečani i Kanaanci te ćete od mača pasti jer ste se odvratili od Jahve i jer Jahve neće biti s vama.\"');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 14, 44, 'Ali se oni prkosno penjahu prema vrhu brda, iako se ni Kovčeg saveza Jahvina ni Mojsije nisu micali iz tabora.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 14, 45, 'Amalečani i Kanaanci koji su živjeli na onome brdu spuste se, udare po njima i rasprše ih sve do Horme.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 15, 1, 'Jahve reče Mojsiju:');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 15, 2, '\"Govori Izraelcima i reci im: \'Kad uđete u zemlju gdje ćete boraviti i koju vam ja dajem,');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 15, 3, 'pa budete prinosili Jahvi paljenu žrtvu, paljenicu ili klanicu, zavjetnicu ili dragovoljnu žrtvu, ili žrtvu prigodom svojih svetkovina - praveći tako od krupne ili sitne stoke ugodan miris Jahvi -');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 15, 4, 'neka prinositelj prinese svoj dar Jahvi: prinosnicu od desetine efe najboljeg brašna, zamiješena u četvrtini hina ulja.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 15, 5, 'Uz paljenicu ili uz klanicu prinesi čevrtinu hina vina za ljevanicu na svako janje.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 15, 6, 'Povrh ovna prinesi kao prinosnicu dvije desetine efe najboljeg brašna, zamiješena u jednoj trećini hina ulja;');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 15, 7, 'i vina za ljevanicu prinesi trećinu hina na ugodan miris Jahvi.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 15, 8, 'Ako Jahvi prinosiš junca kao paljenicu ili kao klanicu da izvršiš zavjet ili kao pričesnicu,');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 15, 9, 'neka se onda uz junca prinesu tri desetine efe najboljeg brašna, zamiješena u pola hina ulja,');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 15, 10, 'a za ljevanicu prinesi pola hina vina kao paljenu žrtvu na ugodan miris Jahvi.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 15, 11, 'Neka se tako postupi uza svakoga vola i uza svakoga ovna, uza svaku glavu sitne stoke, ovce ili koze:');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 15, 12, 'koliko ih god prinesete, za svako pojedino tako učinite, već prema njihovu broju.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 15, 13, 'Svaki domorodac neka postupa ovako kad prinosi žrtvu paljenu na ugodan miris Jahvi.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 15, 14, 'I ako koji stranac koji živi među vama, ili će biti među vašim potomcima, htjedne prinijeti žrtvu paljenu na ugodan miris Jahvi, neka radi kako i vi radite.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 15, 15, 'Neka je jedan zakon i za vas i za stranca koji s vama boravi. To je trajan zakon za vaše naraštaje: pred Jahvom, kako je s vama, tako neka bude i sa strancem.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 15, 16, 'Jedan zakon i jedno pravo neka vrijedi za vas i za stranca koji s vama boravi.\'\"');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 15, 17, 'Jahve reče Mojsiju:');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 15, 18, '\"Govori Izraelcima i reci im: \'Kad dođete u zemlju u koju vas vodim');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 15, 19, 'i budete jeli kruh te zemlje, prinesite podizanicu Jahvi.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 15, 20, 'Kao prvinu iz svojih naćava prinesite jedan kolač kao podizanicu; prinesite ga kao i podizanicu s gumna.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 15, 21, 'Od prvine svojih naćava davajte Jahvi podizanicu od naraštaja do naraštaja.\'\"');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 15, 22, '\"Ako nehotice pogriješite te ne budete obdržavali koju od zapovijedi što ih je Jahve objavio po Mojsiju -');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 15, 23, 'sve što vam je Jahve zapovjedio po Mojsiju, odonda kad vam je izdao zapovijedi pa dalje od koljena do koljena -');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 15, 24, 'onda: ako je to počinjeno nepažnjom zajednice, neka sva zajednica prinese jednoga junca kao paljenicu na ugodan miris Jahvi s propisanom prikaznicom i ljevanicom i jednoga jarca kao okajnicu.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 15, 25, 'Neka svećenik obavi obred pomirenja nad svom izraelskom zajednicom, pa će im biti oprošteno. Bila je samo nepažnja, a oni su prinijeli svoj dar - paljenu žrtvu Jahvi - i okajnicu pred Jahvom za svoju nepažnju.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 15, 26, 'Bit će oprošteno svoj izraelskoj zajednici, a tako i strancu koji među njima boravi, jer se sav narod iz nepažnje ogriješio.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 15, 27, 'Pogriješi li iz nepažnje pojedinac, neka prinese jedno žensko kozle od godine dana kao okajnicu.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 15, 28, 'Neka svećenik obavi obred pomirenja pred Jahvom nad osobom koja je nehotice pogriješila od nepažnje. Kad nad njom obavi obred pomirenja, bit će joj oprošteno.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 15, 29, 'Kada tko pogriješi nepažnjom, neka vam jedan zakon vrijedi i za domoroca i za stranca koji boravi među vama.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 15, 30, 'Ali onaj koji nešto učini naumice, bio on domorodac ili stranac, taj na Jahvu huli. Takav neka se istrijebi između svoga naroda');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 15, 31, 'jer je prezreo Jahvinu riječ i prekršio njegovu zapovijed. Neka se takav iskorijeni. Neka njegova krivnja padne na nj!\"');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 15, 32, 'Kad su Izraelci bili u pustinji, nađu čovjeka kako kupi drva u subotnji dan.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 15, 33, 'I oni koji su ga našli da kupi drva dovedu ga Mojsiju i Aronu i svoj zajednici.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 15, 34, 'Stave ga pod stražu, jer još nije bilo određeno što treba s njim učiniti.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 15, 35, '\"Toga čovjeka treba pogubiti!\" - reče Jahve Mojsiju. \"Neka ga kamenjem zaspe izvan tabora sva zajednica.\"');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 15, 36, 'Sva ga zajednica izvede izvan tabora i zasu ga kamenjem te on poginu, kako je Jahve zapovjedio Mojsiju.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 15, 37, 'Reče Jahve Mojsiju:');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 15, 38, '\"Govori Izraelcima i reci im: neka od naraštaja do naraštaja prave rese na skutovima svojih haljina, a za resu svakoga skuta neka privezuju ljubičastu vrpcu.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 15, 39, 'Imat ćete rese zato da vas pogled na njih sjeća svih Jahvinih zapovijedi. Vršite ih, a ne zanosite se svojim srcem i svojim očima, što vas tako lako zavode na bludnost.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 15, 40, 'Tako ćete se sjećati svih mojih zapovijedi, vršit ćete ih i bit ćete posvećeni svome Bogu.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 15, 41, 'Ja sam Jahve, Bog vaš, koji sam vas izveo iz zemlje egipatske da vam budem Bogom. Ja, Jahve, Bog vaš.\"');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 16, 1, 'Korah, sin Jisharov, sin Kehatov, sin Levijev, pa Datan i Abiram, sinovi Eliabovi, i On, sin Peletov - potomci Rubenovi -');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 16, 2, 'ustanu protiv Mojsija zajedno sa dvjesta pedeset Izraelaca, glavara zajednice, uglednih na skupštini i ljudi na glasu.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 16, 3, 'Oni se sjate oko Mojsija i Arona govoreći im: \"Vi prelazite mjeru! Sva je zajednica, svi njezini članovi, posvećena i među njima je Jahve. Zašto se onda uzvisujete iznad zajednice Jahvine!\"');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 16, 4, 'Kad to ču Mojsije, pade ničice.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 16, 5, 'Zatim reče Korahu i svoj njegovoj družini: \"Sutra će Jahve pokazati tko je njegov i tko je posvećen, kome dopušta da mu se približi. Koga sebi izabere, k sebi će ga i pustiti.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 16, 6, 'Učinite ovo: uzmite kadionike, Korah i sva njegova družina;');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 16, 7, 'sutra stavite u njih vatre i metnite odozgo tamjana pred Jahvom. Koga Jahve odabere, taj neka bude posvećen. Vi prelazite mjeru, Levijevci!\"');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 16, 8, 'Potom Mojsije reče Korahu: \"Poslušajte, Levijevci!');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 16, 9, 'Zar vam je malo što vas je Bog Izraelov izdvojio iz Izraelove zajednice da vas približi k sebi te da vršite službu u Jahvinu prebivalištu i da stojite pred zajednicom služeći joj?');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 16, 10, 'Promaknuo je tebe i s tobom svu tvoju braću Levijevce, a vi još tražite i svećeništvo!');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 16, 11, 'Ti i sva tvoja družina, dakle, sjatili ste se protiv Jahve; jer što je Aron da protiv njega rogoborite?\"');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 16, 12, 'Zatim posla Mojsije po Datana i Abirama, sinove Eliabove, ali oni odgovore: \"Nećemo doći!');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 16, 13, 'Zar je malo što si nas odveo iz zemlje kojom teče med i mlijeko da nas pobiješ u ovoj pustinji, pa hoćeš da nasilno zagospodariš nad nama?');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 16, 14, 'Nisi nas uveo u zemlju kojom teče med i mlijeko i nisi nam dao u posjed njive i vinograde! Misliš li iskopati oči ovim ljudima? Nećemo doći!\"');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 16, 15, 'Mojsije se vrlo razljuti i reče Jahvi: \"Ne obaziri se na njihovu prinosnicu! Ni jednoga njihova magarca nisam prisvojio niti sam ijednoga od njih oštetio.\"');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 16, 16, 'Zatim Mojsije reče Korahu: \"Ti i sva tvoja družina stupite sutra pred Jahvu; ti, i oni, i Aron.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 16, 17, 'Neka svaki uzme svoj kadionik, stavi u nj tamjana i neka svaki donese svoj kadionik pred Jahvu - dvjesta i pedeset kadionika. A i ti i Aron donesite svaki svoj kadionik.\"');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 16, 18, 'Svaki uzme svoj kadionik, stavi u nj vatre, onda odozgo metne tamjana i stane s Mojsijem i Aronom kod ulaza u Šator sastanka.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 16, 19, 'Kad, naprama njima, sabra Korah svu zajednicu na ulazu u Šator sastanka, onda se svoj zajednici pokaza slava Jahvina.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 16, 20, 'I reče Jahve Mojsiju i Aronu:');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 16, 21, '\"Odvojite se od te zajednice da je odmah satrem!\"');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 16, 22, 'Oni popadoše ničice i povikaše: \"Bože! Bože životnog duha u svakome tijelu! Zar ćeš se razgnjeviti na svu zajednicu kad je samo jedan sagriješio!\"');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 16, 23, 'Onda Jahve reče Mojsiju:');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 16, 24, '\"Reci toj zajednici: \'Uklonite se iz okolice prebivališta Koraha, Datana i Abirama!\'\"');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 16, 25, 'Mojsije ustade i pođe k Datanu i Abiramu. Za njim krenuše izraelske starješine.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 16, 26, 'Zatim ovako progovori zajednici: \"Odstupite od šatora tih opakih ljudi! Ne dotičite se ničega što je njihovo, da ne budete uništeni zbog svih njihovih grijeha.\"');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 16, 27, 'Tako se oni udalje iz okolice prebivališta Korahova, Datanova i Abiramova. Uto izađu Datan i Abiram te stanu na ulazu svojih šatora sa svojim ženama, svojim sinovima i svojom nejačadi.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 16, 28, '\"Po ovom ćete vidjeti\", reče Mojsije, \"da me Jahve poslao da vršim sva ova djela, a da ih ne činim sam od sebe:');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 16, 29, 'ako ovi ljudi umru kao što umru i svi ljudi; ako ih pohodi sudbina kakva pohodi sve ljude, onda me Jahve nije poslao.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 16, 30, 'Ali ako Jahve učini nečuveno: ako zemlja rastvori svoje ralje i proguta ih sa svim što je njihovo te živi siđu u Šeol, onda znajte da su ovi ljudi prezreli Jahvu.\"');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 16, 31, 'A kad on završi sve te riječi, tlo se pod njima raspukne;');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 16, 32, 'zemlja rastvori svoje ralje i proguta ih s njihovim domovima, sa svim Korahovim ljudima i svim njihovim imanjem.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 16, 33, 'Živi siđu u Šeol, oni i sve njihovo. Onda se nad njima zemlja zatvori i oni iščeznu iz zbora.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 16, 34, 'Na njihov vrisak svi Izraelci što su stajali oko njih pobjegoše govoreći: \"Da i nas zemlja ne proguta!\"');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 16, 35, 'Ali sukne oganj od Jahve te proždre dvjesta i pedeset ljudi koji su prinosili tamjan.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 17, 1, 'Jahve reče Mojsiju:');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 17, 2, '\"Kaži Eleazaru, sinu svećenika Arona, da ukloni kadionike - jer su posvećeni - iz toga zgarišta, a neposvećenu vatru iz njih neka razaspe podalje.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 17, 3, 'Kadionici onih koji su sagriješili i grijehom život pokopali neka se prekuju u pločice za oblaganje žrtvenika. Doneseni su, naime, pred Jahvu, pa su posvećeni. Neka budu opomenom Izraelcima!\"');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 17, 4, 'Tako svećenik Eleazar uze kadionike od tuča što su ih prinosili oni koji izgorješe; prekovaše ih u pločice za oblaganje žrtvenika.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 17, 5, 'One su opomena Izraelcima da se nitko nepozvan - nitko tko nije od Aronova potomstva - ne smije približiti da pali tamjan pred Jahvom, kako mu se ne bi dogodilo kao Korahu i njegovoj družini, prema onom što je kazao Jahve po Mojsiju.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 17, 6, 'Sutradan je sva zajednica rogoborila protiv Mojsija i Arona. \"Pobili ste Jahvin narod!\" - govorili su.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 17, 7, 'Dok se zajednica skupljala protiv Mojsija i Arona, oni se okrenuše prema Šatoru sastanka, i gle! oblak ga prekri i slava se Jahvina pokaza.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 17, 8, 'Tada Mojsije i Aron odoše pred Šator sastanka.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 17, 9, 'I Jahve reče Mojsiju:');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 17, 10, '\"Udaljite se od te zajednice; u tili ću je čas uništiti!\" Oni padoše ničice.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 17, 11, 'Zatim Mojsije reče Aronu: \"Uzmi kadionik, stavi u nj vatre sa žrtvenika, metni tamjana, a onda se žuri do zajednice da obaviš nad njom obred pomirenja. Gnjev je Jahvin već izbio i zlo je počelo!\"');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 17, 12, 'Aron uze što mu je Mojsije rekao te otrča usred zbora, a kad tamo: pomor među narodom već počeo. Stavi tamjana te obavi obred pomirenja nad narodom.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 17, 13, 'Zatim stade između mrtvih i živih i zlo se ustavi.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 17, 14, 'Bilo ih je mrtvih od toga zla četrnaest tisuća i sedam stotina, osim onih koji su poginuli zbog Koraha.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 17, 15, 'Aron se vrati k Mojsiju na ulaz u Šator sastanka: pomor se ustavi.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 17, 16, 'Jahve reče Mojsiju:');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 17, 17, '\"Razloži Izraelcima te od njih uzmi po jedan štap za svaki predjedovski dom; uzmi od svih njihovih starješina za njihove pradjedovske domove dvanaest štapova. Ime svakoga napiši na njegovu štapu.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 17, 18, 'A kako ima po jedan štap za svakoga starješinu pradjedovskih domova, Aronovo ime napiši na Levijevu štapu.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 17, 19, 'Onda ih pohrani u Šator sastanka pred Svjedočanstvo; ondje gdje se s tobom sastajem.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 17, 20, 'Štap onoga čovjeka koga izaberem propupat će. Tako ću maknuti od sebe rogoborenje Izraelaca kojim prigovaraju vama.\"');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 17, 21, 'Mojsije tako kaza Izraelcima. Sve njihove starješine dadoše mu štap, po jedan štap za svakoga starješinu - dakle, dvanaest štapova za njihove pradjedovske domove. Među njihovim štapovima bio je i štap Aronov.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 17, 22, 'Mojsije pohrani štapove pred Jahvu u Šatoru svjedočanstva.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 17, 23, 'Kad sutradan Mojsije uđe u Šator svjedočanstva, gle: štap Arona iz doma Levijeva propupao! Potjerala mladica, procvjetao cvijet i sazreli bademi.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 17, 24, 'Tada iznese Mojsije ispred Jahve sve štapove sinovima Izraelovim. Oni ih razgledaše, a onda svatko uze svoj štap.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 17, 25, 'Jahve reče Mojsiju: \"Opet stavi Aronov štap pred Svjedočanstvo, neka se čuva za znak buntovnim sinovima. Dokončaj tako njihovo rogoborenje protiv mene da ne izginu.\"');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 17, 26, 'I učini Mojsije: kako mu je Jahve zapovjedio, tako učini.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 17, 27, '\"Izgibosmo!\" - rekoše Izraelci Mojsiju. \"Propadosmo! Svi odreda propadosmo!');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 17, 28, 'Tko god priđe Jahvinu prebivalištu, umire... Zar ćemo svi izginuti?\"');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 18, 1, 'Tada Jahve reče Aronu: \"Ti, tvoji sinovi i tvoj pradjedovski dom s tobom bit ćete odgovorni za grijehe u Svetištu; ti i tvoji sinovi s tobom bit ćete odgovorni za grijehe svoga svećeništva.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 18, 2, 'Pridruži k sebi i svoju braću od Levijeva plemena - tvoga pradjedovskog doma - neka ti se priključe da ti poslužuju, tebi i tvojim sinovima s tobom, pred Šatorom svjedočanstva.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 18, 3, 'Neka stoje na službu tebi i svemu Šatoru, ali neka se ne približuju pokućstvu u Svetištu niti žrtveniku, da ne poginu i oni i vi.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 18, 4, 'Neka su, dakle, tebi pridruženi i neka preuzmu brigu za Šator sastanka, svaku službu oko Šatora. I neka se ni jedan svjetovnjak ne približuje vama,');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 18, 5, 'a vi vršite službu u Svetištu i službu oko žrtvenika da se više ne izlijeva gnjev na Izraelce.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 18, 6, 'Uzeh, evo, vašu braću levite između Izraelaca vama za dar; kao darovani pripadaju Jahvi da obavljaju službu oko Šatora sastanka.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 18, 7, 'Ti i tvoji sinovi s tobom preuzmite svećeničke poslove oko svega što spada na žrtvenik i iza zavjese. Službu koju dajem na dar vašem svećeništvu vi obavljajte. A svjetovnjak koji se primakne neka se pogubi.\"');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 18, 8, 'Još reče Jahve Aronu: \"Tebi, evo, povjeravam brigu o onom što se meni prinosi. Sve što Izraelci posvećuju dodjeljujem tebi i tvojim sinovima kao baštinu trajnim zakonom.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 18, 9, 'Ovo neka pripadne tebi od svetinja nad svetinjama: od paljenih žrtava svi njihovi darovi, za sve njihove prinosnice, za sve njihove okajnice i za sve njihove naknadnice što ih budu meni uzvraćali; ta vrlo sveta stvar neka pripadne tebi i tvojim sinovima!');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 18, 10, 'Blagujte ih kao najveće svetinje! Svaki muškarac može ih jesti. Neka ti budu svete!');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 18, 11, 'I ovo neka bude za te: ono što se uzima od izraelskih prinosa da se prinese kao prikaznica - trajnim zakonom predajem tebi, tvojim sinovima i tvojim kćerima s tobom. Svatko tko u tvome domu bude čist može od toga jesti.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 18, 12, 'Najbolje od novoga ulja i najbolje od novoga vina i žita - prvine koje se prinose Jahvi - predajem tebi.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 18, 13, 'Prvi rodovi svega u njihovoj zemlji što ih budu donosili Jahvi neka budu tvoji. Tko je god čist u tvome domu može ih jesti.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 18, 14, 'Sve što u Izraelu bude određeno za \'herem\' neka je tvoje.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 18, 15, 'Svako prvorođenče svih bića - kako ljudi tako i životinja - što se prinose Jahvi neka bude tvoje. Samo pusti da se otkupi prvenac od ljudi i prvenče od nečiste stoke.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 18, 16, 'Kad budu stari mjesec dana, pusti da ih otkupljuju. A njihovu otkupnu cijenu odredi: pet srebrnih šekela, prema hramskom šekelu, a to je dvadeset gera.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 18, 17, 'Ali prvenče kravlje, prvenče ovčje i prvenče kozje neka se ne otkupljuje. Oni su svetinja. Krv njihovu izlij na žrtvenik, a pretilinu njihovu sažeži u kad kao žrtvu spaljenu na ugodan miris Jahvi.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 18, 18, 'Njihovo meso neka pripadne tebi; kao i grudi žrtve prikaznice i desno pleće.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 18, 19, 'Sve posvećene prinose što ih Izraelci podižu Jahvi predajem trajnim zakonom tebi, tvojim sinovima i tvojim kćerima s tobom. To je savez osoljen, trajan pred Jahvom, tebi i tvome potomstvu s tobom.\"');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 18, 20, '\"Nemoj imati baštine u zemlji njihovoj\", reče Jahve Aronu, \"niti sebi stječi posjeda među njima! Ja sam tvoj dio i tvoja baština među Izraelcima.\"');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 18, 21, '\"Levijevim sinovima, evo, predajem u baštinu sve desetine u Izraelu za njihovu službu - za službu što je obavljaju u Šatoru sastanka.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 18, 22, 'A Izraelci neka se više ne primiču Šatoru sastanka, da ne navuku na se grijeh i ne poginu.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 18, 23, 'Neka samo leviti obavljaju službu u Šatoru sastanka; i neka oni budu odgovorni za svoj grijeh. Trajna je to odredba za vaše naraštaje; među Izraelcima neka nemaju posjeda,');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 18, 24, 'jer ja im predajem u posjed desetine što ih Izraelci prinose na dar Jahvi. Stoga sam za njih rekao: neka oni nemaju posjeda među Izraelcima.\"');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 18, 25, 'Jahve reče Mojsiju:');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 18, 26, '\"Levitima govori i reci im: \'Kad od Izraelaca primate desetinu, koju ja od njih dajem vama u baštinu, od toga onda vi prinesite podizanicu Jahvi: desetinu od desetine.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 18, 27, 'Prinos će vam biti zaračunan kao da je prinos s gumna i Óotoka iz badnja.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 18, 28, 'Tako isto prinosite podizanicu Jahvi i od svih svojih desetina što ih primate od Izraelaca. Od toga davajte podizanicu Jahvinu svećeniku Aronu.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 18, 29, 'Od svih darova koje budete primali podižite podizanicu Jahvi; od svega ono najbolje - onaj dio koji treba posvećivati.\'');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 18, 30, 'Još im reci: \'Pošto od toga prinesete najbolji dio, neka se to levitima uračuna kao prihod s gumna i prihod iz badnja.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 18, 31, 'Na svakome ga mjestu možete jesti, i vi i vaši ukućani, jer to vam je nagrada za vašu službu u Šatoru sastanka.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 18, 32, 'Pošto prinesete njegov najbolji dio, nećete navući na se grijeha; svetinja Izraelaca nećete oskvrnjivati te nećete ginuti.\'\"');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 19, 1, 'Jahve reče Mojsiju i Aronu:');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 19, 2, '\"Ovo je zakonska odredba što ju je Jahve naredio: Reci Izraelcima neka ti dovedu crvenu junicu, zdravu, na kojoj nema mane i na koju još nije stavljan jaram.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 19, 3, 'A vi je predajte svećeniku Eleazaru. Neka se zatim izvede izvan tabora i zakolje pred njim.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 19, 4, 'Svećenik Eleazar neka uzme njezine krvi na svoj prst pa njome poškropi sedam puta prema pročelju Šatora sastanka.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 19, 5, 'Neka se onda junica spali na njegove oči; neka joj se spale: koža, meso, krv i nečist.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 19, 6, 'Potom neka svećenik uzme cedrovine, izopa i crvenoga prediva pa ih baci usred vatre gdje se krava spaljuje.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 19, 7, 'Neka svećenik opere svoju odjeću, a svoje tijelo u vodi okupa. Poslije toga neka se svećenik vrati u tabor, ali neka je nečist do večeri.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 19, 8, 'I onaj koji ju je spaljivao neka svoju odjeću opere i okupa svoje tijelo u vodi te bude nečist do večeri.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 19, 9, 'A jedan čist čovjek neka pokupi pepeo od junice pa ga pohrani izvan tabora na čisto mjesto da se čuva izraelskoj zajednici za vodu očišćenja. To je žrtva okajnica.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 19, 10, 'I onaj koji skupi pepeo od junice neka opere svoju odjeću i bude nečist do večeri. Neka to bude trajan zakon i za Izraelce i za stranca koji među njima boravi.\"');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 19, 11, '\"Tko se dotakne mrtva ljudskog tijela neka je nečist sedam dana.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 19, 12, 'Takav neka se opere tom vodom trećega dana i sedmoga dana pa će biti čist. Ako se ne opere trećega dana i sedmoga dana, neće biti čist.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 19, 13, 'Tko se dotakne mrtvaca, tijela preminula čovjeka, a ne opere se, oskvrnjuje Jahvino prebivalište. Takav neka se iskorijeni iz Izraela. Budući da vodom za očišćenje nije bio poliven, nečist je; njegova je nečistoća još na njemu.\"');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 19, 14, '\"Ovo je zakon kad koji čovjek umre u šatoru; tko god uđe u šator i tko god bude u šatoru neka je nečist sedam dana.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 19, 15, 'Svaka otvorena posuda koja ne bude zatvorena poklopcem neka je nečista.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 19, 16, 'A na otvorenu polju tko se god dotakne poginuloga od mača, ili mrtvaca, ili ljudskih kostiju, ili groba neka je nečist sedam dana.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 19, 17, 'Neka se za onoga koji se onečistio uzme pepela od životinje spaljene za okajnicu i na nj, u kakvu sudu, nalije žive vode.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 19, 18, 'Onda neka čist čovjek uzme izopa, zamoči ga u vodu te poškropi po šatoru, po svemu posuđu, po ljudima koji su tu bili, po onome koji se dotakao kostiju, ili ubijenoga, ili preminuloga, ili groba.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 19, 19, 'Neka čisti čovjek škropi nečistoga trećega i sedmoga dana. Tako će ga na sedmi dan očistiti. Taj onda neka opere svoju odjeću, okupa se u vodi i neka je navečer čist.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 19, 20, 'A bude li tko nečist pa se ne očisti, neka se iskorijeni iz zajednice, jer je oskvrnuo Jahvino svetište; vodom za očišćenje nije bio poliven; nečist je!');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 19, 21, 'Neka im i ovo bude trajnim zakonom: i onaj koji je škropio vodom za očišćenje neka opere svoju odjeću; i onaj koji je dirnuo vodu za očišćenje neka je nečist do večeri.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 19, 22, 'Čega se god nečisti dotakne neka je nečisto; a osoba koja se njega dotakne neka je nečista do večeri.\"');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 20, 1, 'Potom stigoše Izraelci, sva zajednica, u pustinju Sin u prvome mjesecu. Narod se nastani u Kadešu. Ondje umrije Mirjam i ondje je sahraniše.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 20, 2, 'Nije bilo vode za zajednicu. Stoga se udruže protiv Mojsija i protiv Arona.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 20, 3, 'Narod se poče svađati s Mojsijem i govoriti: \"Da smo bar izginuli kad su nam i braća poginula pred Jahvom!');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 20, 4, 'Zašto ste doveli Jahvinu zajednicu u ovu pustinju da ovdje pomremo i mi i naša stoka?');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 20, 5, 'Zašto ste nas izveli iz Egipta da nas dovedete u ovo nesretno mjesto; mjesto u kojem nema ni žita, ni smokava, ni loze, ni mogranja? Nema ni vode da pijemo.\"');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 20, 6, 'Mojsije i Aron odu ispred zajednice do ulaza u Šator sastanka i padnu ničice. Tada im se pokaza slava Jahvina.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 20, 7, 'I Jahve reče Mojsiju:');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 20, 8, '\"Uzmi štap pa ti i tvoj brat Aron skupite zajednicu. Onda, na njihove oči, progovorite pećini da ustupi svoje vode. Iz pećine im izvedi vodu te napoj zajednicu i njezino blago.\"');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 20, 9, 'Mojsije uzme štap ispred Jahve kako mu je naredio.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 20, 10, 'Zatim Mojsije i Aron skupe zbor pred pećinu pa im Mojsije rekne: \"Čujte, buntovnici! Hoćemo li vam iz ove pećine izvesti vodu?\"');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 20, 11, 'Zatim Mojsije podigne ruku i dvaput udari štapom o pećinu: voda provali u obilju, pa su mogli piti i zajednica i njezino blago.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 20, 12, 'Potom će Jahve Mojsiju i Aronu: \"Budući da se niste pouzdavali u me i niste me svetim očitovali u očima sinova Izraelovih, nećete uvesti ovaj zbor u zemlju koju im dajem.\"');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 20, 13, 'To su Meripske vode, kraj njih su se Izraelci prepirali s Jahvom, a on se pokazao svetim.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 20, 14, 'Iz Kadeša pošalje Mojsije glasnike: \"Kralju Edoma. Ovako veli tvoj brat Izrael: \'Ti znaš sve jade koji su nas snašli.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 20, 15, 'Naši se preci spustiše u Egipat. U Egiptu smo proboravili mnogo vremena. Egipćani su s nama i s našim precima loše postupali.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 20, 16, 'Stoga smo vapili Jahvi, i on ču naš glas i posla anđela koji nas izbavi iz Egipta. Evo nas sad u Kadešu, gradu uz rub tvoga područja.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 20, 17, 'Pusti nas da prođemo kroz tvoju zemlju. Nećemo ići preko polja ni vinograda niti ćemo piti vodu iz bunara; ići ćemo Kraljevskim putem, ne skrećući ni desno ni lijevo, dok ne prođemo tvoje područje.\"');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 20, 18, 'Edom mu odgovori: \"Ne prolazi preko moje zemlje, jer eto me s mačem preda te!\"');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 20, 19, '\"Ići ćemo utrenikom\", rekoše Izraelci, \"a budemo li pili tvoje vode, mi i naša stada, za to ćemo ti platiti. Ništa više, samo da prođemo pješice.\"');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 20, 20, '\"Ne prolazi!\" - odgovori. I Edom mu izađe u susret s mnogo ljudi i s velikom silom.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 20, 21, 'Tako Edom nije dopustio Izraelu da prođe kroz njegovo područje i Izrael se okrenu od njega.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 20, 22, 'Zaputivši se od Kadeša, stigoše Izraelci, sva zajednica, k brdu Horu.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 20, 23, 'Kod brda Hora, uz među edomsku, reče Jahve Mojsiju i Aronu:');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 20, 24, '\"Neka se Aron pridruži svojim precima! Neće ući u zemlju koju dajem Izraelcima, jer ste se oprli mojoj zapovijedi kod Meripskih voda.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 20, 25, 'Uzmi Arona i njegova sina Eleazara, pa ih izvedi na brdo Hor.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 20, 26, 'I svuci Aronu njegove haljine pa ih obuci njegovu sinu Eleazaru. Aron će se pridružiti precima, umrijet će ondje.\"');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 20, 27, 'Mojsije učini kako naredi Jahve. Pred svom zajednicom popeše se na brdo Hor.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 20, 28, 'Mojsije svuče s Arona njegove haljine te ih obuče njegovu sinu Eleazaru. Ondje navrh brda umrije Aron. Zatim se Mojsije i Eleazar spustiše s brda.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 20, 29, 'Sva zajednica vidje da je Aron preminuo i sav dom Izraelov oplakivaše Arona trideset dana.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 21, 1, 'Kralj Arada, Kanaanac koji je živio u Negebu, ču da Izrael dolazi Atarimskim putem, pa navali na Izraela i neke njegove zarobi.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 21, 2, 'Tada se Izrael ovako zavjetova Jahvi: \"Ako u moje ruke izručiš ovaj narod, potpuno ću uništiti njegove gradove.\"');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 21, 3, 'Jahve usliša glas Izraela i predade mu Kanaance. A Izrael njih i njihove gradove \'heremom\' uništi. Stoga se ono mjesto prozva Horma.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 21, 4, 'Od brda Hora zapute se prema Crvenom moru da zaobiđu zemlju edomsku. Narod putem postane nestrpljiv.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 21, 5, 'I počne govoriti i protiv Boga i protiv Mojsija: \"Zašto nas izvedoste iz Egipta da pomremo u ovoj pustinji? Nema kruha, nema vode, a to bijedno jelo već se ogadilo dušama našim.\"');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 21, 6, 'Onda Jahve pošalje na narod ljute zmije; ujedale ih one, tako te pomrije mnogo naroda u Izraelu.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 21, 7, 'Dođe narod k Mojsiju pa reče: \"Sagriješili samo kad smo govorili protiv Jahve i protiv tebe. Pomoli se Jahvi da ukloni zmije od nas!\" Mojsije se pomoli za narod,');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 21, 8, 'i Jahve reče Mojsiju: \"Napravi otrovnicu i stavi je na stup: tko god bude ujeden, ostat će na životu ako je pogleda.\"');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 21, 9, 'Mojsije napravi zmiju od mjedi i postavi je na stup. Kad bi koga ujela ljutica, pogledao bi u mjedenu zmiju i ozdravio.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 21, 10, 'Pođu Izraelci i utabore se u Obotu.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 21, 11, 'Potom se zapute iz Obota i utabore se kraj Ije-Abarima, u pustinji što je nasuprot Moabu, sa strane sunčeva izlaska.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 21, 12, 'Odande otputuju te se utabore u dolini Zaredu.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 21, 13, 'Odande krenu i utabore se s onu stranu Arnona, koji je u pustinji a izvire u području Amorejaca. Jer je Arnon granica moapska između Moabaca i Amorejaca.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 21, 14, 'Zato se veli u \"Knjizi Jahvinih vojni\": \"Vaheb kod Sufe i doline arnonske');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 21, 15, 'i padine doline što se naginje prema mjestu Aru i naslanja se na granicu moapsku...\"');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 21, 16, 'Odande odoše u Beer. To je bunar o kojem je Jahve rekao Mojsiju: \"Skupi narod da im dam vode!\"');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 21, 17, 'Tada Izrael zapjeva ovu pjesmu: \"Proključaj, studenče! A vi ga uznosite:');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 21, 18, 'knezovi ga iskopali, prvaci narodni izdubli žezlom, štapom svojim.\" Iz pustinje odu u Matanu,');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 21, 19, 'iz Matane u Nahaliel, a iz Nahaliela u Bamot;');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 21, 20, 'iz Bamota u dolinu što se stere u moapskom polju, prema vrhuncu Pisge, s koje se pruža vidik na pustaru.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 21, 21, 'Sad Izrael posla glasnike Sihonu, amorejskome kralju, s porukom:');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 21, 22, '\"Pusti da prođem preko tvoje zemlje. Nećemo zalaziti u polja i u vinograde, niti ćemo piti vode iz bunara. Ići ćemo Kraljevskim putem dok ne prođemo tvoje područje.\"');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 21, 23, 'Ali Sihon ne dopusti Izraelu da prođe njegovim područjem, nego skupi sav svoj narod te izađe u pustinju da presretne Izraelce. Stigavši do Jahze, zavojuje na Izraela.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 21, 24, 'Ali ga Izrael potuče oštrim mačem i osvoji njegovu zemlju od Arnona do Jaboka, do Amonaca, jer je Az ležao na granici Amonaca.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 21, 25, 'Izrael zauzme sve one gradove i Izrael se nastani u svim onim gradovima Amorejaca; u Hešbonu i svim njegovim naseljima.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 21, 26, 'Kako je Hešbon bio glavni grad Sihona, amorejskog kralja, koji je ratovao protiv prijašnjega moapskoga kralja te osvojio svu njegovu zemlju do Arnona,');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 21, 27, 'kažu zato pjesnici: \"Hrabro, o Hešbone, dobro sazdani, čvrsto posađeni grade Sihonov!');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 21, 28, 'Iz Hešbona oganj suknu, plamen iz grada Sihonova, sažga Ar moapski, proždrije visove arnonske.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 21, 29, 'Teško tebi, Moabe! Propao si, narode Kemošev! Od sinova bjegunce učini, a od kćeri svojih ropkinje Sihonu, kralju amorejskom.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 21, 30, 'Pobili smo ih; propao je Hešbon do Dibona: sve smo razorili do Nofaha, što je blizu Medebe...\"');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 21, 31, 'Tako se Izrael nastani u zemlji Amorejaca.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 21, 32, 'Mojsije se uputi da izvidi Jazer. Potom zauzmu njegova naselja a rastjeraju Amorejce koji bijahu ondje.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 21, 33, 'Okrenu se onda i pođu prema Bašanu. A bašanski kralj Og presrete ih sa svim svojim narodom da zapodjene boj kod Edreja.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 21, 34, 'Ali Jahve reče Mojsiju: \"Ne boj ga se! Predao sam u tvoje ruke njega, sav njegov narod i njegovu zemlju. Postupi s njim kako si postupio s amorejskim kraljem Sihonom koji je boravio u Hešbonu.\"');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 21, 35, 'I potukoše ga, i sinove njegove, i sav njegov narod, tako da nitko ne uteče. Potom zaposjedoše njegovu zemlju.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 22, 1, 'Poslije toga Izraelci otputuju i utabore se na Moapskim poljanama, s onu stranu Jordana, nasuprot Jerihonu.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 22, 2, 'Balak, sin Siporov, vidje sve što Izrael učini Amorejcima.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 22, 3, 'Moab se uvelike poboja toga naroda jer je bio brojan. Moaba obuze strah od Izraelaca.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 22, 4, 'Zato reče Moab midjanskim starješinama: \"Sad će ova rulja oko nas sve popasti kao što vol popase travu po polju.\" Balak, sin Siporov, bijaše moapski kralj u ono vrijeme.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 22, 5, 'On pošalje glasnike Bileamu, sinu Beorovu, u Petoru, koji se nalazi na Rijeci, u zemlji Amonaca. Pozove ga rekavši: \"Evo je došao neki narod iz Egipta; evo je prekrio lice zemlje i naselio se uza me.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 22, 6, 'Zato dođi i prokuni mi ovaj narod jer je jači od mene. Tako ću ga moći svladati i istjerati iz zemlje. A znam da je blagoslovljen onaj koga blagosloviš, a proklet onaj koga prokuneš.\"');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 22, 7, 'Starješine moapske i starješine midjanske krenu s nagradom za vračanje u svojim rukama. Stignu Bileamu i prenesu mu Balakovu poruku.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 22, 8, 'On im rekne: \"Prenoćite ovdje te ću vam odgovoriti prema onome što mi Jahve kaže.\" Tako moapski knezovi ostanu kod Bileama.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 22, 9, 'Bog dođe Bileamu i upita: \"Tko su ti ljudi s tobom?\" Bileam odgovori Bogu:');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 22, 10, '\"Poslao ih k meni Balak, sin Siporov, moapski kralj, s porukom:');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 22, 11, '\'Evo je neki narod došao iz Egipta i prekrio lice zemlje. Dođi da ga prokuneš. Tako ću ga moći svladati i protjerati.\'\"');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 22, 12, 'Ali Bog reče Bileamu: \"Nemoj ići s njima! Nemoj proklinjati onaj narod jer je blagoslovljen.\"');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 22, 13, 'Ujutro Bileam ustane te će Balakovim knezovima: \"Odlazite u svoju zemlju jer mi ne da Jahve da pođem s vama.\"');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 22, 14, 'Moapski se knezovi dignu, odu Balaku pa mu reknu: \"Bileam nije htio poći s nama.\"');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 22, 15, 'Balak opet pošalje knezove, brojnije i uglednije od prvih.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 22, 16, 'Oni dođu Bileamu i reknu mu: \"Ovako je poručio Balak, sin Siporov: \'Ne skanjuj se nego dođi k meni.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 22, 17, 'Bogato ću te nagraditi i učinit ću sve što mi kažeš. Dođi, molim te, i prokuni mi ovaj narod!\'\"');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 22, 18, 'Ali Bileam odgovori Balakovim slugama: \"Da mi Balak dadne svoju kuću punu srebra i zlata, ne bih mogao prestupiti zapovijedi Jahve, Boga svoga, da učinim išta, bilo veliko bilo malo.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 22, 19, 'Ali provedite ovdje i vi noć da doznam što će mi Jahve još kazati.\"');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 22, 20, 'Noću Bog dođe Bileamu pa mu rekne: \"Ako su ti ljudi došli da te pozovu, ustani, pođi s njima! Ali da činiš samo što ti ja reknem!\"');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 22, 21, 'Ustane Bileam ujutro, osamari svoju magaricu i ode s moapskim knezovima.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 22, 22, 'No Božja srdžba usplamtje što je on pošao. Zato anđeo Jahvin stade na put da ga spriječi. On je jahao na svojoj magarici, a pratila ga njegova dva momka.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 22, 23, 'Kad magarica opazi anđela Jahvina kako stoji na putu s isukanim mačem u ruci, skrene sa staze i pođe preko polja. Bileam poče tući magaricu da je vrati na put.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 22, 24, 'Anđeo Jahvin tada stade na uskom prolazu, među vinogradima, a bijaše ograda i s ove i s one strane.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 22, 25, 'Magarica, spazivši Jahvina anđela, stisne se uza zid i o zid pritisne Bileamovu nogu. On je opet poče tući.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 22, 26, 'Anđeo Jahvin pođe naprijed te stade na usko mjesto gdje nije bilo prostora da se provuče ni desno ni lijevo.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 22, 27, 'Kad je magarica ugledala Jahvina anđela, legne pod Bileamom. Bileam pobjesni i poče tući magaricu štapom.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 22, 28, 'Tada Jahve otvori usta magarici te ona progovori Bileamu: \"Što sam ti učinila da si me tukao tri puta?\"');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 22, 29, 'Bileam odgovori magarici: \"Što sa mnom zbijaš šalu! Da mi je mač u ruci, sad bih te ubio!\"');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 22, 30, 'A magarica uzvrati Bileamu: \"Zar ja nisam tvoja magarica na kojoj si jahao svega svoga vijeka do danas? Jesam li ti običavala ovako?\" - \"Nisi!\" - odgovori on.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 22, 31, 'Tada Jahve otvori oči Bileamu i on opazi anđela Jahvina kako stoji na putu s golim mačem u ruci. Pognu on glavu i pade ničice.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 22, 32, 'Onda će mu anđeo Jahvin: \"Zašto si tukao svoju magaricu već tri puta? TÓa ja sam istupio da te spriječim, jer te put meni naočigled vodi u propast.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 22, 33, 'Magarica me opazila i preda mnom se uklonila sva tri puta. Da mi se nije uklanjala, već bih te ubio, a nju ostavio na životu.\"');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 22, 34, 'Onda će Bileam anđelu Jahvinu: \"Sagriješio sam! Nisam znao da ti preda mnom stojiš na putu. Ali sad, ako je zlo u tvojim očima, ja ću se vratiti.\"');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 22, 35, 'Ali anđeo Jahvin odvrati Bileamu: \"Idi s tim ljudima, ali samo ono govori što ti ja kažem.\" Tako Bileam ode s Balakovim knezovima.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 22, 36, 'Kad je Balak čuo da Bileam dolazi, iziđe mu u susret do grada Moaba što se nalazi na granici Arnona, na kraju područja.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 22, 37, '\"Zar nisam uporno po te slao i pozivao te? Zašto mi nisi došao?\" reče Balak Bileamu. \"Zar te zaista ne mogu bogato nagraditi?\"');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 22, 38, '\"Evo sam ti došao\", reče Bileam Balaku. \"Ali hoću li ti moći sada što kazati? Samo što mi Bog stavi na jezik, to ću govoriti.\"');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 22, 39, 'Pođe zatim Bileam s Balakom i dođoše u Kirjat Husot.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 22, 40, 'Žrtvova Balak i krupne i sitne stoke te od toga pruži Bileamu i knezovima koji su ga pratili.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 22, 41, 'Sutradan uze Balak Bileama i odvede ga gore na Bamot-Baal, odakle mogaše vidjeti krajnji dio naroda.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 23, 1, 'I Bileam reče Balaku: \"Ovdje mi načini sedam žrtvenika; ovdje mi pripravi sedam junaca i sedam ovnova.\"');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 23, 2, 'Balak učini kako je Bileam rekao. A onda Balak i Bileam prinesu po jednoga junca i ovna na svakome žrtveniku.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 23, 3, 'Potom će Bileam Balaku: \"Ti stoj kod svoje paljenice, a ja idem ne bih li se sreo s Jahvom, pa što mi očituje, kazat ću ti.\" I ode na osamljeno mjesto.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 23, 4, 'I Bog srete Bileama, koji mu reče: \"Sedam sam žrtvenika podigao i prinio na svakome po jednoga junca i ovna.\"');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 23, 5, 'A Jahve stavi riječi u usta Bileamu te mu zapovjedi: \"Vrati se Balaku i ovako govori.\"');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 23, 6, 'Bileam se vrati k njemu, a on stajaše uza svoju paljenicu i s njim svi knezovi moapski.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 23, 7, 'Tada on poče svoju pjesmu i reče: \"Iz Arama dovede me Balak, kralj Moaba, iz strana istočnih: \'Dođi, prokuni mi Jakova, dođi, gromom udri Izraela!\'');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 23, 8, 'Kako mogu proklinjati koga Bog ne proklinje? Kako gromom udarati koga Jahve ne udara?');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 23, 9, 'Jer s vrha hridi ja ga gledam, s visoka ga motrim brijega. Gle naroda koji odvojeno živi, među narode on se ne broji.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 23, 10, 'Prah Jakovljev tko će prebrojiti; pijesak Izraela tko će izmjeriti! O, da mi je umrijeti smrću pravednika! O, da svršetak moj bude kao njegov!\"');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 23, 11, '\"Što mi to uradi!\" - reče Balak Bileamu. \"Dovedoh te da prokuneš moje neprijatelje, a kad tamo, ti ih blagoslovom obasu!\"');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 23, 12, 'On odgovori: \"Zar mi nije dužnost kazati što mi Jahve stavlja u usta?\"');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 23, 13, '\"Hajde sa mnom na drugo mjesto, odakle ga možeš svega vidjeti\" zamoli ga Balak. \"Odavde mu vidiš samo jedan kraj, a ne vidiš ga svega. Odande mi ga prokuni!\"');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 23, 14, 'Povede ga zatim na Sede Sofim, na vrh Pisge. Tu sagradi sedam žrtvenika i na svakom žrtveniku prinese po jednoga junca i ovna.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 23, 15, 'Bileam tada rekne Balaku: \"Stoj ovdje kraj svoje paljenice, a ja odoh onamo na susret Bogu.\"');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 23, 16, 'Jahve sretne Bileama; stavi riječi u njegova usta te mu zapovjedi: \"Vrati se k Balaku i tako govori!\"');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 23, 17, 'I vrati se on Balaku, koji stajaše uza svoju paljenicu i s njim moapski knezovi. Balak ga zapita: \"Što je Jahve rekao?\"');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 23, 18, 'Tada Bileam započe svoju pjesmu i reče: \"Ustani, Balače, i poslušaj! Uhom me posluhni, sine Siporov!');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 23, 19, 'Bog nije čovjek da bi slagao, nije sin Adama da bi se kajao. Zar on kada rekne, a ne učini, zar obeća, pa ne ispuni?');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 23, 20, 'Gle, primih od Boga da blagoslovim, blagoslovit ću i povuć\' neću blagoslova.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 23, 21, 'U Jakovu nesreće ne nazreh, nit\' nevolje vidjeh u Izraelu. Jahve, Bog njegov, s njime je, poklik kralju u njemu odzvanja.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 23, 22, 'Iz Egipta Bog ga je izveo, on je njemu k\'o rozi bivola.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 23, 23, 'Gatanja nema protiv Jakova nit\' protiv Izraela vračanja. I kada budu rekli Jakovu i Izraelu: \'Što radi Bog?\'');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 23, 24, 'gle, ustat će narod k\'o lavica, dići će se poput lava: leći neće dok plijen ne proguta, dok ne popije krv pobijenih.\"');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 23, 25, 'Zatim Balak reče Bileamu: \"Nemoj ga ni kletvom kleti, ali ni blagoslovom blagoslivljati.\"');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 23, 26, 'Bileam odvrati Balaku. \"Zar ti nisam rekao: sve što Jahve kaže, to ću činiti.\"');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 23, 27, 'Potom Balak reče Bileamu: \"Hajde! Odvest ću te na drugo mjesto. Možda će Bogu biti pravo da mi ga odande prokuneš.\"');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 23, 28, 'I odvede Balak Bileama na vrh Peora, odakle se pruža vidik na pustaru.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 23, 29, '\"Sagradi mi ovdje sedam žrtvenika\", reče Bileam Balaku. \"Nadalje, pripremi mi ovdje sedam junaca i sedam ovnova.\"');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 23, 30, 'Balak učini kako je Bileam rekao i prinese po jednoga junca i ovna na svakome žrtveniku.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 24, 1, 'Kad opazi Bileam da je Jahvi drago što on blagoslivlja Izraela, ne htjede više ni ići kao prije u potragu za znamenjima, nego se licem okrenu prema pustari.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 24, 2, 'Bileam podiže oči i vidje Izraela utaborena po njegovim plemenima. Na nj siđe Duh Božji');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 24, 3, 'i on poče svoju pjesmu te reče: \"Proročanstvo Bileama, sina Beorova, proročanstvo čovjeka pronicava pogleda,');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 24, 4, 'proročanstvo onoga koji riječi Božje sluša, koji vidi viđenja Svesilnoga, koji pada i oči mu se otvaraju.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 24, 5, 'Kako su lijepi ti šatori, Jakove, i stanovi tvoji, Izraele!');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 24, 6, 'Kao dolovi što se steru, kao vrtovi uz obalu rijeke, kao aloje što ih Jahve posadi, kao cedri pokraj voda!');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 24, 7, 'Iz potomstva junak mu izlazi, nad mnogim on vlada narodima. Kralj će njegov nadvisit\' Agaga, uzdiže se kraljevstvo njegovo.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 24, 8, 'Iz Egipta Bog ga izveo, on je njemu k\'o rozi bivola. On proždire narode dušmanske, on njihove kosti drobi.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 24, 9, 'Skupio se, polegao poput lava, poput lavice: tko ga podići smije? Blagoslovljen bio tko te blagoslivlje, proklet da je tko tebe proklinje!\"');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 24, 10, 'I usplamtje srdžbom Balak na Bileama i udari rukom o ruku. \"Pozvao sam te da prokuneš moje neprijatelje\", reče Balak Bileamu, \"a kad tamo, ti ih blagoslovi evo triput!');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 24, 11, 'Nosi se odmah u svoj kraj. Bio sam rekao: dostojno ću te počastiti! A eto, Jahve te liši časti.\"');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 24, 12, 'Nato Bileam odgovori Balaku: \"Zar nisam rekao i tvojim glasnicima koje si k meni poslao:');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 24, 13, '\'Da mi Balak dadne svoju kuću punu srebra i zlata, ne bih mogao prestupiti zapovijed Jahvinu i po svojoj volji činiti bilo dobro, bilo zlo; ono što kaže Jahve, to ću i ja reći.\'');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 24, 14, 'A sada, kad, evo, odlazim k svome narodu, hajde da ti objavim što će ovaj narod učiniti tvome narodu u budućnosti!\"');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 24, 15, 'I poče svoju pjesmu i reče: \"Proročanstvo Bileama, sina Beorova, proročanstvo čovjeka pronicava pogleda,');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 24, 16, 'proročanstvo onoga koji riječi Božje sluša, koji poznaje mudrost Svevišnjega, koji vidi viđenja Svesilnoga, koji pada i oči mu se otvaraju.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 24, 17, 'Vidim ga, ali ne sada: motrim ga, al\' ne iz blizine: od Jakova zvijezda izlazi, od Izraela žezlo se diže. On Moabu razbija bokove i svu djecu Šetovu zatire!');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 24, 18, 'Edom će njegovim postati posjedom, a Seir zemljom osvojenom. Razvija snagu svoju Izrael,');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 24, 19, 'Jakov vlada nad neprijateljima i uništava preživjele iz Ira.\"');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 24, 20, 'Bileam se zagleda u Amaleka te poče svoju pjesmu i reče: \"Amalek je prvenac među narodima, ali vječna propast njegov je svršetak.\"');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 24, 21, 'Onda se zagleda u Kenijce te poče svoju pjesmu i reče: \"Tvrd je stan tvoj, Kajine, na timoru ti gnijezdo savijeno!');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 24, 22, 'Al\' gnijezdo pripada Beoru; dokle ćeš Ašuru robovati?\"');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 24, 23, 'Opet poče svoju pjesmu i reče: \"Narodi pomorski sabiru se sa sjevera,');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 24, 24, 'a brodovlje od strane Kitima. Podjarmljuju Ašur, podjarmljuju Heber, pa i njega će propast stići vječita.\"');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 24, 25, 'Potom ustade Bileam te se uputi natrag u svoj kraj. A i Balak ode svojim putem.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 25, 1, 'Dok je Izrael boravio u Šitimu, narod se upusti u blud s Moapkama.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 25, 2, 'One pozivahu narod na žrtvovanje svojim bogovima, a narod sudjelovaše u njihovim gozbama i klanjaše se njihovim bogovima.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 25, 3, 'Tako se Izrael osramoti s Baalom peorskim. I Jahve planu gnjevom na Izraela.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 25, 4, '\"Pokupi sve narodne glavare\", reče Jahve Mojsiju. \"Objesi ih Jahvi usred bijela dana da se Jahvin gnjev odvrati od Izraela.\"');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 25, 5, 'Onda Mojsije rekne izraelskim sucima: \"Neka svatko pobije one svoje ljude koji su se osramotili s Baalom peorskim.\"');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 25, 6, 'Baš tada neki Izraelac dođe i dovede k svojoj braći jednu Midjanku naočigled Mojsija i naočigled sve izraelske zajednice koja zaplaka na ulazu u Šator sastanka.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 25, 7, 'Kad to opazi Pinhas, sin Eleazara, sina svećenika Arona, ustade ispred zajednice: uze koplje u ruku');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 25, 8, 'i pođe za Izraelcem u odaje i probode ih oboje, Izraelca i ženu; nju kroza slabine. Tako pomor Izraelaca prestade.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 25, 9, 'A onih koji su od pomora pomrli bilo je dvadeset i četiri tisuće.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 25, 10, 'Jahve reče Mojsiju:');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 25, 11, '\"Pinhas, sin Eleazara, sina svećenika Arona, odvratio je moj gnjev od Izraelaca, obuzet među njima mojim revnovanjem. Zato u svome revnovanju nisam istrijebio izraelskoga naroda.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 25, 12, 'Kaži mu dakle: \'S njime, evo, sklapam savez mira.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 25, 13, 'Neka to bude za nj i njegove potomke poslije njega savez vječnoga svećeništva, jer je revnovao za svoga Boga i izvršio pomirenje za izraelski narod.\'\"');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 25, 14, 'Ime Izraelcu koji je bio ubijen - onome što je ubijen s Midjankom - bijaše Zimri. Bio je sin Salua, glavara jedne od Šimunovih porodica.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 25, 15, 'A ime ubijene žene Midjanke bijaše Kozbi. Bila je kći Surova. Sur je bio glavar jednog plemena, jedne porodice u Midjanu.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 25, 16, 'Jahve reče Mojsiju:');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 25, 17, '\"Navali na Midjance i potuci ih,');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 25, 18, 'jer su i oni navaljivali na vas svojim lukavštinama kad su lukavo radili protiv vas u slučaju Peora i svoje sestre Kozbi, kćeri glavara midjanskoga, koja je zaglavila u vrijeme pomora nastalog zbog Peora.\"');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 25, 19, '');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 26, 1, 'Poslije toga zla Jahve reče Mojsiju i Eleazaru, sinu svećenika Arona:');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 26, 2, '\"Obavite popis sve zajednice sinova Izraelovih, po njihovim porodicama, popišite sve, od dvadeset godina pa naviše, koji su u Izraelu sposobni za borbu.\"');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 26, 3, 'Mojsije, dakle, i svećenik Eleazar popišu ih na Moapskim poljanama, uz Jordan blizu Jerihona,');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 26, 4, 'sve od dvadeset godina pa naviše, kako je Jahve naredio Mojsiju i Izraelcima. Sinovi Izraelovi koji su izašli iz zemlje egipatske bili su:');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 26, 5, 'Izraelov prvorođenac Ruben. Sinovi Rubenovi: od Henoka rod Henokovaca; od Palua rod Paluovaca;');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 26, 6, 'od Hesrona rod Hesronovaca i od Karmija rod Karmijevaca.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 26, 7, 'To su rodovi Rubenovaca. Njih je bilo četrdeset i tri tisuće sedam stotina i trideset.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 26, 8, 'Paluov sin bijaše Eliab,');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 26, 9, 'a sinovi Eliabovi: Nemuel, Datan i Abiram. Taj Datan i Abiram bijahu ugledni članovi zajednice koji se podigoše protiv Mojsija i Arona u buni Korahovoj, kad se pobuniše protiv Jahve.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 26, 10, 'Nato je zemlja rastvorila svoje ralje i progutala ih zajedno s Korahom, kad je smrt pograbila tu skupinu i oganj proždro dvjesta i pedeset ljudi. Tako su postali opomenom.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 26, 11, 'No sinovi Korahovi ne izginuše.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 26, 12, 'Sinovi Šimunovi po svojim rodovima: od Nemuela rod Nemuelovaca; od Jamina rod Jaminovaca; od Jakina rod Jakinovaca;');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 26, 13, 'od Zeraha rod Zerahovaca i od Šaula rod Šaulovaca.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 26, 14, 'To su rodovi Šimunovaca, njih dvadeset i dvije tisuće i dvjesta.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 26, 15, 'Sinovi Gadovi po svojim rodovima: od Sefona rod Sefonovaca; od Hagija rod Hagijevaca; od Šunija rod Šunijevaca;');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 26, 16, 'od Oznija rod Oznijevaca; od Erija rod Erijevaca;');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 26, 17, 'od Aroda roda Arodovaca i od Arelija rod Arelijevaca.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 26, 18, 'To su rodovi Gadovih potomaka. Njih je upisano četrdeset tisuća i pet stotina.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 26, 19, 'Judini sinovi: Er i Onan. I Er i Onan umriješe u zemlji kanaanskoj.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 26, 20, 'Sinovi Judini po svojim rodovima bijahu: od Šele rod Šelinaca; od Peresa rod Peresovaca i od Zeraha rod Zerahovaca.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 26, 21, 'Peresovi su sinovi opet bili: od Hesrona rod Hesronovaca i od Hamula rod Hamulovaca.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 26, 22, 'To su Judini rodovi. Njih je upisano sedamdeset i šest tisuća i petsto.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 26, 23, 'Sinovi Jisakarovi, prema svojim rodovima: od Tole rod Tolinaca; od Puve rod Puvinaca;');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 26, 24, 'od Jašuba rod Jašubovaca i od Šimrona rod Šimronovaca.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 26, 25, 'To su Jisakarovi rodovi. Njih je upisano šezdeset i četiri tisuće i trista.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 26, 26, 'Sinovi Zebulunovi, po svojim rodovima: od Sereda rod Seredovaca; od Elona rod Elonovaca i od Jahleela rod Jahleelovaca.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 26, 27, 'To su rodovi Zebulunovaca. Njih je upisano šezdeset tisuća i pet stotina.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 26, 28, 'Sinovi Josipovi, po svojim rodovima: Manaše i Efrajim.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 26, 29, 'Sinovi Manašeovi: od Makira rod Makirovaca. Makiru se rodio Gilead. Od Gileada rod Gileadovaca.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 26, 30, 'Ovo su bili sinovi Gileadovi: od Jezera rod Jezerovaca; od Heleka rod Helekovaca;');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 26, 31, 'od Asriela rod Asrielovaca; od Šekema rod Šekemovaca;');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 26, 32, 'od Šemide rod Šemidinaca i od Hefera rod Heferovaca.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 26, 33, 'Heferov sin Selofhad nije imao sinova, nego kćeri. Imena Selofhadovih kćeri bila su: Mahla, Noa, Hogla, Milka i Tirsa.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 26, 34, 'To su Manašeovi rodovi. Njih je upisano pedeset i dvije tisuće i sedam stotina.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 26, 35, 'Ovo su opet sinovi Efrajimovi, po svojim rodovima: od Šutelaha rod Šutelahovaca; od Bekera rod Bekerovaca i od Tahana rod Tahanovaca.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 26, 36, 'Ovo su sinovi Šutelahovi: od Erana rod Eranovaca.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 26, 37, 'To su rodovi Efrajimovih sinova. Njih je upisano trideset i dvije tisuće i pet stotina. To su sinovi Josipovi, po svojim rodovima.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 26, 38, 'Sinovi Benjaminovi, po svojim rodovima: od Bele rod Belinaca; od Ašbela rod Ašbelovaca; od Ahirama rod Ahiramovaca;');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 26, 39, 'od Šefufama rod Šefufamovaca i od Hufama rod Hufamovaca.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 26, 40, 'Belini sinovi bili su: Ard i Naaman. I tako, od Arda rod Ardovaca, a od Naamana rod Naamanovaca.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 26, 41, 'To su sinovi Benjaminovi, po svojim rodovima. Njih je upisano četrdeset i pet tisuća i šest stotina.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 26, 42, 'Ovo su sinovi Danovi, po svojim rodovima: od Šuhama rod Šuhamovaca. To su sinovi Danovi, prema svojim rodovima.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 26, 43, 'Od svih rodova Šuhamovaca bilo je upisano šezdeset i četiri tisuće i četiri stotine.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 26, 44, 'Sinovi Ašerovi, po svojim rodovima: od Jimne rod Jimninaca; od Jišvija rod Jišvijevaca i od Berije rod Berijevaca.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 26, 45, 'Od sinova Berijinih: od Hebera rod Heberovaca i od Malkiela rod Malkielovaca.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 26, 46, 'Ašerovoj kćeri bilo je ime Serah.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 26, 47, 'To su rodovi Ašerovih sinova. Njih je upisano pedeset i tri tisuće i četiri stotine.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 26, 48, 'Sinovi Naftalijevi, po svojim rodovima: od Jahseela rod Jahseelovaca; od Gunija rod Gunijevaca;');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 26, 49, 'od Jesera rod Jeserovaca i od Šilema rod Šilemovaca.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 26, 50, 'To su rodovi Naftalijevaca. Po njihovim rodovima upisano ih je četrdeset i pet tisuća i četiri stotine.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 26, 51, 'Bilo je, dakle, upisanih Izraelaca šest stotina i jedna tisuća i sedam stotina i trideset.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 26, 52, 'Jahve reče Mojsiju:');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 26, 53, '\"Tima neka se razdijeli zemlja u baštinu prema broju osoba.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 26, 54, 'Većem broju povećaj njegovu baštinu, a manjem smanji njegovu baštinu; neka se svakomu dadne njegova baština prema broju upisanih.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 26, 55, 'Ali zemlja neka se podijeli kockom: neka se primi u baštinu prema djedovskim plemenskim imenima.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 26, 56, 'Baština se ima podijeliti kockom svakom plemenu prema njegovoj veličini.\"');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 26, 57, 'Ovo je popis Levijevaca, po njihovim rodovima: od Geršona rod Geršonovaca; od Kehata rod Kehatovaca i od Merarija rod Merarijevaca.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 26, 58, 'Ovo su rodovi Levijevaca: rod Libnijevaca, rod Hebronovaca, rod Mahlijevaca, rod Mušijevaca i rod Korahovaca. Kehatu se rodio Amram.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 26, 59, 'Amramovoj ženi bijaše ime Jokebeda. Bila je kći Levijeva, koja se Leviju rodila u Egiptu. Ona je Amramu rodila: Arona, Mojsija i njihovu sestru Mirjam.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 26, 60, 'Aronu se rodili: Nadab, Abihu, Eleazar i Itamar.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 26, 61, 'Nadab i Abihu poginuli su kad su prinosili neposvećenu vatru pred Jahvom.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 26, 62, 'Svih je popisanih muškaraca od jednog mjeseca pa naviše bilo dvadeset i tri tisuće. Oni nisu bili popisani s Izraelcima i nije im bila dodijeljena baština među Izraelcima.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 26, 63, 'To su, dakle, oni koje je popisao Mojsije i svećenik Eleazar; oni su obavili ovaj popis Izraelaca uz Jordan, na Moapskim poljanama nasuprot Jerihonu.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 26, 64, 'Među njima nije bilo ni jednoga od onih koje su popisali Mojsije i svećenik Aron kad su popisivali Izraelce u Sinajskoj pustinji.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 26, 65, 'Jer Jahve bijaše za njih rekao: \"Neka pomru u pustinji i neka nitko od njih ne ostane, osim Kaleba, sina Jefuneova, i Jošue, sina Nunova!\"');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 26, 66, '');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 27, 1, 'Tada pristupiše kćeri Selofhada, sina Heferova, sina Gileadova, sina Makirova, sina Manašeova iz roda Josipova sina Manašea. A imena kćeri bila su: Mahla, Noa, Hogla, Milka i Tirsa.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 27, 2, 'One stanu pred Mojsija, pred svećenika Eleazara, pred glavare i svu zajednicu na ulazu u Šator sastanka pa reknu:');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 27, 3, '\"Naš je otac umro u pustinji. Nije pripadao družini što se pobunila protiv Jahve - Korahovoj družini - nego je umro od svoga vlastitoga grijeha. Sinova nije imao.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 27, 4, 'Zašto bi se odstranilo ime našega oca iz njegova roda? Budući da nije imao sina, daj nama posjed među braćom našega oca!\"');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 27, 5, 'Mojsije iznese njihov slučaj pred Jahvu.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 27, 6, 'A Jahve reče Mojsiju:');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 27, 7, '\"Selofhadove kćeri pravo kažu. Treba svakako da im dadneš posjed koji će biti njihova baština među braćom njihova oca. Prenesi na njih baštinu njihova oca.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 27, 8, 'Nadalje, reci Izraelcima: \'Kad koji čovjek umre a ne imadne sina, prenesite njegovu baštinu na njegovu kćer.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 27, 9, 'Ne imadne li ni kćeri, predajte baštinu njegovoj braći.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 27, 10, 'Ako ne imadne ni braće, njegovu baštinu podajte braći njegova oca.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 27, 11, 'Ako mu otac ne imadne braće, baštinu njegovu podajte najbližem rođaku njegova roda: neka je on uzme u posjed.\' Neka to bude zakonska odredba Izraelcima, kako je Jahve naredio Mojsiju.\"');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 27, 12, 'Jahve reče Mojsiju: \"Popni se na ovo brdo Abarim i razgledaj zemlju koju dajem Izraelcima.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 27, 13, 'A kad budeš razgledao, pridružit ćeš se svojim precima i ti, kako se pridružio i tvoj brat Aron.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 27, 14, 'Jer ste se u pobuni zajednice u pustinji Sin usprotivili mojim ustima umjesto da vodom očitujete moju svetost pred njihovim očima.\" (To su Meripske vode kod Kadeša u Sinskoj pustinji.)');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 27, 15, 'A Jahvi Mojsije progovori ovako:');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 27, 16, '\"Neka Jahve, Bog duhova u svakom tijelu, postavi čovjeka nad ovom zajednicom');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 27, 17, 'koji će pred njom izlaziti; koji će pred njom stupati; koji će je izvoditi i uvoditi tako da Jahvina zajednica ne bude kao stado što nema pastira.\"');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 27, 18, '\"Uzmi Jošuu, sina Nunova!\" - reče Jahve Mojsiju. \"To je čovjek u kome ima duha. Na nj položi ruku svoju!');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 27, 19, 'Onda ga odvedi pred svećenika Eleazara i pred svu zajednicu te mu na njihove oči daj naredbe!');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 27, 20, 'Predaj mu dio svoje vlasti da ga sluša sva zajednica sinova Izraelovih.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 27, 21, 'Neka pristupa k svećeniku Eleazaru, koji će za nj tražiti odluke Urima pred Jahvom. Na njegovu zapovijed neka izlaze i na njegovu zapovijed neka ulaze, oni i svi Izraelci s njim - sva zajednica.\"');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 27, 22, 'Mojsije učini kako mu je Jahve naredio: uzme Jošuu te ga postavi pred svećenika Eleazara i pred svu zajednicu.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 27, 23, 'Položi zatim na nj svoje ruke i dade mu svoje naredbe, kako je Jahve zapovjedio preko Mojsija.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 28, 1, 'Jahve reče Mojsiju:');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 28, 2, '\"Naredi Izraelcima i reci im: \'Točno u određeno vrijeme prinosite mi moje prinose, moju hranu - žrtve paljene meni na ugodan miris.\'');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 28, 3, 'Reci im: Ovo su žrtve paljene koje ćete prinositi Jahvi: Svaki dan dva jednogodišnja janjca bez mane kao trajnu paljenicu.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 28, 4, 'Jedno janje prinosite jutrom, a drugo janje prinosite u suton.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 28, 5, 'A za prinosnicu desetinu efe najboljeg brašna, zamiješena u četvrtini hina čistoga ulja.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 28, 6, 'Trajna je to paljenica koja je već bila prinesena na Sinajskom brdu - žrtva spaljena na ugodan miris Jahvi.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 28, 7, 'Njezina ljevanica neka se sastoji od četvrtine hina za svako janje. Ljevanica vina neka se Jahvi izlijeva u Svetištu.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 28, 8, 'Drugo janje prinosite u suton. Prinosi ga kao i jutarnju prinosnicu i njezinu ljevanicu: kao žrtvu spaljenu Jahvi na ugodan miris.\"');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 28, 9, '\"Na subotnji dan: dva jednogodišnja janjeta bez mane i dvije desetine efe najboljeg brašna, zamiješena s uljem, za prinosnicu, s njezinom ljevanicom.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 28, 10, 'Neka se subotnja paljenica svake subote dodaje trajnoj paljenici i njezinoj ljevanici.\"');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 28, 11, '\"Na početku vaših mjeseci prinosite Jahvi za paljenicu: dva junca, jednoga ovna i sedam jednogodišnjih janjaca bez mane.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 28, 12, 'Za pojedinog junca kao prinosnicu: tri desetine najboljeg brašna zamiješena s uljem; za svakog ovna kao prinosnicu: dvije desetine efe najboljeg brašna zamiješena s uljem.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 28, 13, 'Za svako janje jednu desetinu efe najboljeg brašna zamiješena s uljem kao prinosnicu. To je paljenica spaljena na ugodan miris Jahvi.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 28, 14, 'Njihove ljevanice neka budu: na junca polovica hina vina; na ovna trećina hina; na janje četvrtina hina. To neka bude mjesečna paljenica na mlađak svakog mjeseca u godini.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 28, 15, 'Povrh trajne paljenice neka se Jahvi prinosi jedan jarac kao okajnica s njezinom ljevanicom.\"');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 28, 16, '\"Prvoga mjeseca, četrnaestoga dana u mjesecu, Jahvina je Pasha,');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 28, 17, 'a petnaestoga dana toga mjeseca jest blagdan. Neka se sedam dana jedu beskvasni hljebovi.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 28, 18, 'Prvog dana neka bude sveti saziv. Nikakva težačkog posla nemojte raditi.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 28, 19, 'Prinesite Jahvi žrtvu paljenu, žrtvu paljenicu: dva junca, jednoga ovna i sedam jednogodišnjih janjaca. Neka vam budu bez mane.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 28, 20, 'Njihova prinosnica, od najboljeg brašna zamiješena s uljem, neka bude: tri desetine efe na junca, dvije desetine efe na ovna,');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 28, 21, 'a na svakoga od onih sedam janjaca neka bude jedna desetina efe.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 28, 22, 'Neka bude jedan jarac kao okajnica, da se nad vama izvrši obred pomirenja.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 28, 23, 'Ovo prinosite povrh jutarnje paljenice, koje se prinosi kao trajna paljenica.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 28, 24, 'Tako činite svaki dan za sedam dana; to je hrana, žrtva paljena na ugodan miris Jahvi. To neka se prinosi povrh trajne paljenice i njezine ljevanice.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 28, 25, 'Sedmoga dana neka vam bude sveti savez. Nikakva težačkog posla nemojte raditi!\"');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 28, 26, '\"I na Dan prvina - na svoj Blagdan sedmica - kad budete Jahvi prinosili prinosnicu, imajte sveti saziv: nikakva težačkog posla nemojte raditi.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 28, 27, 'Za paljenicu na ugodan miris Jahvi prinesite dva junca, jednoga ovna i sedam jednogodišnjih janjaca.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 28, 28, 'Njihova prinosnica, od najboljeg brašna zamiješena s uljem, neka bude: na pojedinog junca tri desetine efe, na pojedinoga ovna dvije desetine efe,');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 28, 29, 'a jedna desetina efe na svakoga od onih sedam janjaca.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 28, 30, 'Neka bude i jedan jarac kao okajnica, da se nad vama izvrši obred pomirenja.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 28, 31, 'Prinosite ih povrh trajne paljenice i njezine prinosnice, a neka vam budu bez mane one i njihove ljevanice.\"');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 29, 1, '\"U sedmome mjesecu, na prvi dan mjeseca, imajte sveti saziv. Nikakva težačkog posla nemojte raditi. Neka vam to bude Dan sazivanja.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 29, 2, 'Za paljenicu na ugodan miris Jahvi prinesite: jednoga junca, jednoga ovna i sedam jednogodišnjih janjaca bez mane.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 29, 3, 'Njihova prinosnica, od najboljeg brašna zamiješena s uljem, neka bude: tri desetine efe na junca, dvije desetine efe na ovna');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 29, 4, 'i jedna desetina efe na svakoga od onih sedam janjaca.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 29, 5, 'Neka bude jedan jarac kao okajnica, da se nad vama izvrši obred pomirenja.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 29, 6, 'Neka to bude povrh paljenice o mlađaku mjesecu i njezine prinosnice, povrh trajne paljenice i njezine prinosnice i povrh njihovih propisanih ljevanica, žrtva spaljena na ugodan miris Jahvi.\"');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 29, 7, '\"A desetoga dana toga sedmog mjeseca imajte sveti saziv. Postite i nemojte raditi nikakva posla.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 29, 8, 'Prinesite paljenicu Jahvi na ugodan miris: jednoga junca, jednoga ovna i sedam jednogodišnjih janjaca. Neka su vam bez mane.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 29, 9, 'Njihova prinosnica, od najboljeg brašna zamiješena s uljem, neka bude: tri desetine efe na junca, dvije desetine na jednoga ovna');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 29, 10, 'i jedna desetina efe na svakoga od onih sedam janjaca.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 29, 11, 'Jedan jarac neka se prinese kao okajnica. To je povrh okajnice na Dan pomirenja, povrh trajne paljenice i njezine prinosnice i njihovih ljevanica.\"');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 29, 12, '\"Na petnaesti dan sedmoga mjeseca imajte sveti saziv. Nikakva težačkog posla nemojte raditi. Sedam dana svetkujte svečanost Jahvi.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 29, 13, 'A za paljenicu, spaljenu na ugodan miris Jahvi, prinesite: trinaest junaca, dva ovna i četrnaest jednogodišnjih janjaca. Neka su bez mane.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 29, 14, 'Njihova prinosnica, od najboljeg brašna zamiješena s uljem, neka bude: tri desetine efe na svakoga od trinaest junaca, dvije desetine efe na svakoga od dvaju ovnova');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 29, 15, 'i jedna desetina efe na svako pojedino od četrnaestero janjadi. Neka se nadoda jedan jarac kao okajnica.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 29, 16, 'To neka bude povrh trajne paljenice, njezine prinosnice i njezine ljevanice.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 29, 17, 'Drugog dana: dvanaest junaca, dva ovna, četrnaest jednogodišnjih janjaca bez mane.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 29, 18, 'Njihovu prinosnicu i njihove ljevanice prinesite propisno prema broju junaca, ovnova i janjaca.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 29, 19, 'Prinesite jednoga jarca kao okajnicu povrh trajne paljenice, njezine prinosnice i njezinih ljevanica.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 29, 20, 'Trećeg dana: jedanaest junaca, dva ovna, četrnaest jednogodišnjih janjaca bez mane.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 29, 21, 'Njihovu prinosnicu i njihove ljevanice prinesite propisno prema broju junaca, ovnova i janjaca.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 29, 22, 'Prinesite jednoga jarca kao okajnicu povrh trajne paljenice, njezine prinosnice i njezine ljevanice.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 29, 23, 'Četvrtog dana: deset junaca, dva ovna, četrnaest jednogodišnjih janjaca bez mane.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 29, 24, 'Njihovu prinosnicu i njihove ljevanice prinesite propisno prema broju junaca, ovnova i janjaca.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 29, 25, 'Jednog jarca prinesite kao okajnicu povrh trajne paljenice, njezine prinosnice i njezine ljevanice.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 29, 26, 'Petog dana: devet junaca, dva ovna, četrnaest jednogodišnjih janjaca bez mane.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 29, 27, 'Njihovu prinosnicu i njihove ljevanice prinesite propisno prema broju junaca, ovnova i janjaca.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 29, 28, 'Prinesite jednog jarca kao okajnicu povrh trajne paljenice, njezine prinosnice i njezine ljevanice.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 29, 29, 'Šestog dana: osam junaca, dva ovna, četrnaest jednogodišnjih janjaca bez mane.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 29, 30, 'Njihovu prinosnicu i njihove ljevanice prinesite propisno prema broju junaca, ovnova i janjaca.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 29, 31, 'Jednoga jarca prinesite kao okajnicu povrh trajne paljenice, njezine prinosnice i njezinih ljevanica.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 29, 32, 'Sedmog dana: sedam junaca, dva ovna, četrnaest jednogodišnjih janjaca bez mane.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 29, 33, 'Njihovu prinosnicu i njihove ljevanice prinesite propisno prema broju junaca, ovnova i janjaca.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 29, 34, 'Jednog jarca prinesite kao okajnicu povrh trajne paljenice, njezine prinosnice i njezine ljevanice.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 29, 35, 'Osmog dana imajte svečani zbor. Nikakva težačkog posla nemojte raditi.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 29, 36, 'A za paljenicu, spaljenu na ugodan miris Jahvi, prinesite: jednog junca, jednoga ovna i sedam jednogodišnjih janjaca bez mane.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 29, 37, 'Njihovu prinosnicu i njihove ljevanice prinesite propisno prema broju junaca, ovnova i janjaca.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 29, 38, 'Jednog jarca prinesite kao okajnicu povrh trajne paljenice, njezine prinosnice i njezine ljevanice.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 29, 39, 'Na svoje određene blagdane prinesite to Jahvi osim svojih zavjetnica i svojih dragovoljnih žrtava, svojih paljenica, prinosnica, ljevanica i svojih pričesnica.\"');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 30, 1, 'Sve kako mu je Jahve naredio Mojsije kaza Izraelcima.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 30, 2, 'Zatim reče Mojsije glavarima plemena Izraelovih: \"Ovo je Jahve naredio.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 30, 3, 'Ako koji čovjek učini zavjet ili se uz zakletvu obveže da će se nečega odreći, neka ne krši svoje riječi; neka izvrši sve što iz njegovih usta izađe!');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 30, 4, 'Ako koja žena učini Jahvi zavjet ili se obveže da će se nečega odreći dok je još mlada, u očevu domu,');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 30, 5, 'a otac joj sazna za zavjet i obećanje kojim se obvezala pa joj ništa ne rekne, tada su valjani svi njezini zavjeti i valjano je svako obećanje kojim se obvezala.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 30, 6, 'Ali ako joj se otac usprotivi kad sazna, nikakav njezin zavjet ni njezino obećanje kojim se vezala ne vrijedi. Jahve će joj oprostiti jer joj se otac usprotivio.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 30, 7, 'Ako se uda dok je pod svojim zavjetima ili pod obećanjem koje je nepromišljeno izišlo iz njezinih usta,');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 30, 8, 'pa njezin muž sazna i pošto je saznao ništa joj ne rekne, tada vrijede njezini zavjeti i vrijede obećanja kojima se obvezala.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 30, 9, 'No ako se njezin muž usprotivi kad o tom sazna, ukida se time njezin zavjet i obećanje što je nepromišljeno izišlo iz njezinih usta. I Jahve će joj oprostiti.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 30, 10, 'A zavjet udovice ili žene otpuštene i sve obveze koje je na se preuzela vrijede za nju.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 30, 11, 'Ako se zavjetuje ili se obveže zakletvom na obećanje dok je u kući svoga muža,');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 30, 12, 'pa njezin muž sazna i ništa joj ne rekne, ne usprotivi joj se, svaki je njezin zavjet valjan i valjano je svako obećanje kojim se obvezala.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 30, 13, 'Ali ako ih njezin muž proglasi ništetnim kad o njima sazna, tada ništa što je izišlo iz njezinih usta, njezini zavjeti ili preuzete obveze neće vrijediti. Muž ih je njezin poništio, i Jahve će joj oprostiti.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 30, 14, 'Svaki zavjet i svaku zakletvu koja obvezuje ženu na neko mrtvenje njezin muž može uzdržati na snazi ili poništiti.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 30, 15, 'Ako joj muž od dana do dana ništa ne rekne, time potvrđuje sve njezine zavjete i sva njezina obećanja kojima se obvezala; on ih je učinio valjanima ako ništa nije rekao kad je o njima čuo.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 30, 16, 'Ali ako ih poništi kasnije, pošto je o njima već čuo, neka snosi njezinu krivnju.\"');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 30, 17, 'To su uredbe koje je Jahve Mojsiju izdao za muža i njegovu ženu i za oca i njegovu kćer, koja, još mlada, živi u kući očevoj.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 31, 1, 'Jahve reče Mojsiju:');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 31, 2, '\"Iskali osvetu Izraelaca na Midjancima, a poslije toga pridružit ćeš se svojim precima.\"');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 31, 3, 'A Mojsije reče narodu: \"Opremite ljude između sebe za pohod na Midjance,');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 31, 4, 'da na Midjancima izvrše Jahvinu osvetu. Na vojnu opremite po jednu tisuću od svakoga izraelskog plemena!\"');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 31, 5, 'I tako su iz izraelskih porodica - tisuću po plemenu - za vojnu skupili dvanaest tisuća.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 31, 6, 'Posla ih Mojsije - tisuću po plemenu - na vojnu zajedno s Pinhasom, sinom svećenika Eleazara. On je nosio posvećene stvari i trube.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 31, 7, 'Oni zavojuju na Midjance, kako je Jahve naredio Mojsiju, i pobiju sve muškarce.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 31, 8, 'Među ostalima pobili su i midjanske kraljeve: Evija, Rekema, Sura, Hura i Rebu - pet midjanskih kraljeva. Mačem pogube i Bileama, Beorova sina.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 31, 9, 'Odvedu tada Izraelci u ropstvo midjanske žene s njihovom djecom i svu njihovu stoku, krupnu i sitnu, i zaplijene sve njihovo blago.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 31, 10, 'Ognjem spale sve gradove njihove u kojima se živjeli i sva njihova naselja,');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 31, 11, 'a sve njihovo uzmu za plijen i pljačku, i ljude i životinje.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 31, 12, 'Onda u tabor na Moapskim poljanama uz Jordan, nasuprot Jerihonu, dovedu Mojsiju, svećeniku Eleazaru i svoj izraelskoj zajednici zarobljenike, plijen i pljačku.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 31, 13, 'Mojsije, svećenik Eleazar i svi glavari zajednice izađu im u susret izvan tabora.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 31, 14, 'Mojsije se razljuti na zapovjednike vojske, tisućnike i satnike, koji se bijahu vratili s toga bojnog pohoda.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 31, 15, 'Reče im: \"Što! Na životu ste ostavili sve ženskinje!');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 31, 16, 'A baš su žene, po nagovoru Bileamovu, zavele Izraelce da u Peorovu slučaju istupe protiv Jahve. Tako dođe pomor na Jahvinu zajednicu.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 31, 17, 'Stoga svu mušku djecu pobijte! A ubijte i svaku ženu koja je poznala muškarca!');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 31, 18, 'A sve mlade djevojke koje nisu poznale muškarca ostavite na životu za se.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 31, 19, 'Vi pak proboravite izvan tabora sedam dana; svi vi koji ste koga ubili i koji ste se ubijenoga dotakli. Čistite se i vi i vaši zarobljenici trećega i sedmoga dana;');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 31, 20, 'očistite svu odjeću, sve mješine, sve od kostrijeti napravljeno i sve drvene predmete.\"');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 31, 21, 'Zatim svećenik Eleazar progovori borcima koji su se vratili iz boja: \"Ovo je odredba koju je izdao Jahve Mojsiju:');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 31, 22, '\'Zlato, srebro, bakar, gvožđe, mjed i olovo -');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 31, 23, 'sve što podnosi vatru - provucite kroz vatru i bit će očišćeno.\' Ipak, neka se očisti i vodom očišćenja. A sve što ne podnosi vatru provucite kroz vodu.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 31, 24, 'Sedmoga dana operite svoju odjeću i bit ćete čisti. Poslije toga možete se vratiti u tabor.\"');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 31, 25, 'Jahve reče Mojsiju:');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 31, 26, '\"Ti, svećenik Eleazar i obiteljske starješine zajednice napravite popis ratnoga plijena, ljudstva i stoke,');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 31, 27, 'a onda ratni plijen podijeli napola: na borce koji su išli u borbu i na svu ostalu zajednicu.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 31, 28, 'Od boraca koji su išli u borbu ustavi ujam za Jahvu: jednu glavu od svakih pet stotina, bilo ljudi, bilo krupnog blaga, magaradi ili sitne stoke.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 31, 29, 'Uzmi to od njihove polovice i podaj svećeniku Eleazaru kao podizanicu za Jahvu.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 31, 30, 'A od polovice što zapadne druge Izraelce uzmi po glavu od pedeset, bilo ljudi, bilo krupnog blaga, magaradi ili sitne stoke - od svih životinja - pa ih podaj levitima koji vode brigu o Jahvinu prebivalištu.\"');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 31, 31, 'Mojsije i svećenik Eleazar učine kako je Jahve naredio Mojsiju.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 31, 32, 'Ratnoga je plijena bilo, osim pljačke što su vojnici napljačkali: šest stotina sedamdeset i pet tisuća grla sitne stoke,');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 31, 33, 'sedamdeset i dvije tisuće grla krupne stoke,');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 31, 34, 'šezdeset i jedna tisuća magaradi,');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 31, 35, 'a ljudskih duša - žena koje nisu poznale muškarca - bijaše u svemu trideset i dvije tisuće.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 31, 36, 'Prema tome, polovica što je dodijeljena onima koji su išli u borbu bila je: tri stotine trideset i sedam tisuća i pet stotina grla sitne stoke;');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 31, 37, 'ujam za Jahvu od sitne stoke šest stotina sedamdeset i pet grla;');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 31, 38, 'krupne je stoke bilo trideset i šest tisuća grla, a njihov ujam za Jahvu sedamdeset i dva grla;');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 31, 39, 'magaradi je bilo trideset tisuća i pet stotina, a njihov ujam za Jahvu šezdeset i jedno.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 31, 40, 'Ljudskih je duša bilo šesnaest tisuća, a njihov ujam za Jahvu trideset i dvije osobe.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 31, 41, 'Ujam predade Mojsije svećeniku Eleazaru za podizanicu Jahvi, kako je Jahve naredio Mojsiju.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 31, 42, 'A od polovice koja je zapala druge Izraelce i koju Mojsije odijeli od one što je pripala ljudima koji su se borili -');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 31, 43, 'dakle, polovica što je pripala zajednici iznosila je: trista trideset i sedam tisuća i pet stotina grla sitne stoke,');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 31, 44, 'a krupne stoke trideset i šest tisuća grla;');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 31, 45, 'magaradi trideset tisuća i pet stotina,');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 31, 46, 'a ljudskih duša šesnaest tisuća.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 31, 47, 'Tako, od polovice što je pripala Izraelcima Mojsije ostavi po jedno od pedeset, i od ljudstva i od stoke, te ih predade levitima koji su se brinuli o Jahvinu prebivalištu, kako je Jahve naredio Mojsiju.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 31, 48, 'Onda pristupiše k Mojsiju vojnički zapovjednici, tisućnici i satnici,');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 31, 49, 'i rekoše mu: \"Tvoje sluge prebrojile su borce što bijahu pod našim zapovjedništvom i od nas nitko nije izgubljen.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 31, 50, 'Uz to smo donijeli svoje darove Jahvi: narukvica, orukvica, prstenja, naušnica i ogrlica - na kakvu je tko zlatninu već naišao - da se nad nama obavi obred pomirenja pred Jahvom.\"');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 31, 51, 'Mojsije i svećenik Eleazar prime od njih to zlato, to jest sve te izrađene predmete.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 31, 52, 'Bilo je svega zlata što su kao svoju podizanicu Jahvi donijeli tisućnici i satnici: šesnaest tisuća sedam stotina i pedeset šekela.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 31, 53, 'Svaki je vojnik za se zadržao svoj plijen.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 31, 54, 'Tako Mojsije i svećenik Eleazar uzmu zlato od tisućnika i satnika te ga donesu u Šator sastanka na spomen Izraelcima pred Jahvom.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 32, 1, 'Rubenovci i Gadovci imađahu mnogo, vrlo mnogo blaga. Opaze, međutim, da je zemlja jazerska i zemlja gileadska pogodna za stočarstvo.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 32, 2, 'Zato Gadovci i Rubenovci dođu k Mojsiju, svećeniku Eleazaru i glavarima zajednice pa reknu:');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 32, 3, '\"Atarot, Dibon, Jazer, Nimra, Hešbon, Eleale, Sebam, Nebo i Beon -');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 32, 4, 'kraj što ga Jahve osvoji pred izraelskom zajednicom - kraj je pogodan za stočarstvo; a sluge tvoje bave se stočarstvom.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 32, 5, 'Ako smo stekli blagonaklonost u tvojim očima\", nastave, \"neka se ovaj kraj dade u posjed tvojim slugama. Ne šalji nas preko Jordana!\"');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 32, 6, 'Mojsije odgovori Gadovcima i Rubenovcima: \"Zar da vaša braća idu u rat, a vi da ostanete ovdje?');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 32, 7, 'Zašto odvraćate srca Izraelaca da ne prijeđu u zemlju koju im je Jahve predao?');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 32, 8, 'Tako su učinili i vaši očevi kad sam ih poslao iz Kadeš Barnee da izvide zemlju.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 32, 9, 'Popeli su se do Eškola i razgledali zemlju, ali su onda ubili srčanost u Izraelcima da ne odu u zemlju koju im je Jahve dao.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 32, 10, 'Onog dana Jahve planu gnjevom. Zakle se i reče:');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 32, 11, '\'Ljudi što su izišli iz Egipta, kojima je dvadeset ili više godina, jer me nisu vjerno slijedili, nikad neće vidjeti zemlju što sam je pod zakletvom obećao Abrahamu, Izaku i Jakovu!\'');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 32, 12, 'Jahvu su jedino vjerno slijedili Kenižanin Kaleb, sin Jefuneov, i sin Nunov Jošua.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 32, 13, 'Jahve je gnjevom planuo na Izraelce pa ih je pustinjom povlačio četrdeset godina, sve dok ne pomrije sav naraštaj što je u očima Jahvinim zlo postupio.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 32, 14, 'A sad vi - grešni naraštaj - ustajete namjesto svojih očeva da još povećate srdžbu Jahvinu na Izraela.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 32, 15, 'Ako se od njega odvratite, on će još produžiti vaš boravak u pustinji; tako ćete upropastiti sav taj narod.\"');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 32, 16, 'Onda se oni primaknu k njemu i reknu: \"Mi bismo ovdje podigli torove za svoje blago i gradove za svoju nejačad,');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 32, 17, 'a sami ćemo pograbiti oružje i poći na čelu Izraelaca dok ih ne dovedemo na njihovo mjesto. Naša nejačad neka ostane - zbog stanovništva ove zemlje - u utvrđenim gradovima.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 32, 18, 'Mi se svojim kućama nećemo vraćati sve dok svaki Izraelac ne zaposjedne svoju baštinu.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 32, 19, 'S njima nećemo dijeliti svoje posjede s onu stranu Jordana niti dalje, jer će nas zapasti naša baština s ovu stranu, na istok od Jordana.\"');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 32, 20, 'Mojsije im reče: \"Ako tako uradite, ako pođete pred Jahvom u boj;');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 32, 21, 'ako vi svi naoružani prijeđete Jordan pred Jahvom dok on ne rastjera ispred sebe svoje neprijatelje:');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 32, 22, 'tada, kad zemlja bude pokorena Jahvi, vi ćete se moći vratiti. Tako ćete biti oslobođeni odgovornosti prema Jahvi i prema Izraelu, a ova će zemlja postati pred Jahvom vaše vlasništvo.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 32, 23, 'Ali ako tako ne uradite, sagriješit ćete protiv Jahve i znajte da će vas stići kazna za vaš grijeh.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 32, 24, 'Sazidajte, dakle, gradove za svoju nejačad i torove za svoju stoku, ali izvršite što ste obećali.\"');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 32, 25, 'Gadovci i Rubenovci odgovore Mojsiju: \"Tvoje će sluge učiniti kako gospodar naš nalaže.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 32, 26, 'Naša nejačad, naše žene, naša stoka i sve naše blago neka ostanu ondje u gileadskim gradovima,');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 32, 27, 'a tvoje sluge, svi koji su za boj sposobni, poći će pred Jahvom u boj, kako naš gospodar nalaže.\"');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 32, 28, 'Tada za njih Mojsije izda nalog svećeniku Eleazaru, Nunovu sinu Jošui i glavarima obitelji izraelskih plemena.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 32, 29, 'I reče im Mojsije: \"Ako Gadovci i Rubenovci, svi oni koji nose oružje, s vama prijeđu Jordan da se bore pred Jahvom i zemlja bude pokorena vama, onda im dajte gileadsku zemlju u vlasništvo.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 32, 30, 'Ali ako ne prijeđu naoružani s vama, neka dobiju baštinu među vama u zemlji kanaanskoj.\"');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 32, 31, 'Nato odgovore Gadovci i Rubenovci: \"Što je god Jahve rekao tvojim slugama, to ćemo učiniti.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 32, 32, 'Mi ćemo naoružani prijeći pred Jahvom u zemlju kanaansku, ali neka nam bude posjed naše baštine s ove strane Jordana.\"');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 32, 33, 'I tako njima - Gadovcima, Rubenovcima i polovici plemena Manašea, sina Josipova - dadne kraljevstvo amorejskoga kralja Sihona i kraljevstvo bašanskoga kralja Oga, zemlju s gradovima u njihovim granicama, gradove okolne zemlje.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 32, 34, 'Gadovci sagrade: Dibon, Atarot i Aroer,');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 32, 35, 'Atrot Šofan, Jazer, Jogbohu,');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 32, 36, 'Bet Nimru i Bet Haran, utvrđene gradove i torove za stada.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 32, 37, 'Rubenovci sagrade: Hešbon, Eleale, Kirjatajim,');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 32, 38, 'Nebo, Baal Meon - nazivi su izmijenjeni - i Šibmu. Oni prozovu svojim imenima gradove koje su oni podigli.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 32, 39, 'Sinovi Makira, sina Manašeova, odu u Gilead, osvoje ga i protjeraju Amorejce koji bijahu ondje.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 32, 40, 'Mojsije preda Gilead Manašeovu sinu Makiru, i on se u njemu nastani.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 32, 41, 'A Manašeov sin Jair ode te zauzme njihova sela pa ih prozva \"Jairova sela\".');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 32, 42, 'Potom ode Nobah i zauzme Kenat i njegova područja te ga nazove svojim imenom \"Nobah\".');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 33, 1, 'Ovo su postaje Izraelaca što ih prijeđoše kad iziđoše iz zemlje egipatske u svojim četama pod vodstvom Mojsijevim i Aronovim.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 33, 2, 'Na zapovijed Jahvinu Mojsije je bilježio polazne točke njihova putovanja. Ovo su njihove postaje prema njihovim polaznim točkama.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 33, 3, 'Iz Ramsesa krenuše u prvome mjesecu. Bio je petnaesti dan prvoga mjeseca - sutradan poslije Pashe - kad se Izraelci zaputiše uzdignutih pesnica i naočigled sviju Egipćana,');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 33, 4, 'dok su Egipćani pokopavali one koje je Jahve između njih pobio, to jest sve prvorođence, i tako nad njihovim božanstvima izvršio pravdu.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 33, 5, 'Krenu dakle Izraelci iz Ramsesa i utabore se u Sukotu.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 33, 6, 'Zatim odu iz Sukota i utabore se u Etamu, baš na rubu pustinje.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 33, 7, 'Pođu iz Etama, a onda okrenu prema Pi Hahirotu, koji se nalazi nasuprot Baal Sefona. Tabore postave pred Migdolom.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 33, 8, 'Krenu od Pi Hahirota i prijeđu posred mora u pustinju. Išli su tri dana pustinjom Etanom, a onda se utabore u Mari.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 33, 9, 'Zatim odu iz Mare i stignu u Elim. U Elimu je bilo dvanaest izvor-voda i sedamdeset palma. Tu su se utaborili.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 33, 10, 'Potom krenu iz Elima te se utabore uz Crveno more.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 33, 11, 'A otišavši od Crvenog mora, utabore se u pustinji Sinu.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 33, 12, 'Potom odu iz pustinje Sina i postave tabore u Dofki.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 33, 13, 'Otišavši iz Dofke, utabore se u Alušu.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 33, 14, 'Krenu iz Aluša i utabore se u Refidimu. Tu narod nije imao vode da pije.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 33, 15, 'Odu iz Refidima te se utabore u Sinajskoj pustinji.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 33, 16, 'Krenu iz Sinajske pustinje te se utabore u Kibrot Hataavi.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 33, 17, 'Odu iz Kibrot Hataave te se utabore u Haserotu.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 33, 18, 'Onda odu iz Haserota i utabore se u Ritmi.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 33, 19, 'Krenu iz Ritme i utabore se u Rimon Peresu.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 33, 20, 'Odu iz Rimon Peresa i utabore se u Libni.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 33, 21, 'Iz Libne odu i utabore se u Risi.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 33, 22, 'Odu iz Rise te se utabore u Kehelati.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 33, 23, 'Odu iz Kehelate i utabore se na brdu Šeferu.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 33, 24, 'Odu s brda Šefera i utabore se u Haradi.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 33, 25, 'Odu iz Harade i utabore se u Makhelotu.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 33, 26, 'Odu iz Makhelota te se utabore u Tahatu.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 33, 27, 'Odu iz Tahata i utabore se u Tarahu.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 33, 28, 'Iz Taraha odu i utabore se u Mitki.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 33, 29, 'Odu iz Mitke i utabore se u Hašmoni.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 33, 30, 'Iz Hašmone odu i utabore se u Moserotu.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 33, 31, 'Odu iz Moserota i utabore se u Bene Jaakanu.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 33, 32, 'Odu iz Bene Jaakana i utabore se u Hor Gidgadu.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 33, 33, 'Odu iz Hor Gidgada i utabore se u Jotbati.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 33, 34, 'Odu iz Jotbate i utabore se u Abroni.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 33, 35, 'Iz Abrone odu i utabore se u Esion Geberu.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 33, 36, 'Iz Esion Gebera odu i utabore se u pustinji Sinu, to jest u Kadešu.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 33, 37, 'Iz Kadeša krenu te se utabore na brdu Horu, na granici zemlje edomske.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 33, 38, 'Na zapovijed Jahvinu svećenik se Aron pope na brdo Hor i tu umre na prvi dan petoga mjeseca, u četrdesetoj godini nakon izlaska Izraelaca iz egipatske zemlje.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 33, 39, 'Aronu je bilo stotinu dvadeset i tri godine kad je preminuo na brdu Horu.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 33, 40, 'Aradski kralj, Kanaanac, koji je živio u kanaanskom kraju Negebu, čuo je o dolasku Izraelaca.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 33, 41, 'S brda Hora odu te se utabore u Salmoni.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 33, 42, 'Odu iz Salmone i utabore se u Punonu.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 33, 43, 'Odu iz Punona i utabore se u Obotu.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 33, 44, 'Odu iz Obota i utabore se na moapskom području u Ije-Abarimu.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 33, 45, 'Odu iz Ije-Abarima i utabore se u Dibon Gadu.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 33, 46, 'Iz Dibon Gada odu i utabore se u Almon Diblatajimu.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 33, 47, 'Iz Almon Diblatajima odu i utabore se na Abarimskim bregovima, pred Nebom.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 33, 48, 'Odu s Abarimskih bregova i utabore se na Moapskim poljanama, uz Jordan, nasuprot Jerihonu;');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 33, 49, 'taborovali su uz Jordan od Bet Haješimota sve do Abel Hašitima na Moapskim poljanama.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 33, 50, 'Na Moapskim poljanama uz Jordan, nasuprot Jerihonu, Jahve reče Mojsiju:');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 33, 51, '\"Ovako reci Izraelcima: \'Kad prijeđete preko Jordana u zemlju kanaansku,');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 33, 52, 'potjerajte ispred sebe sve stanovnike te zemlje, uništite sve njihove slike; uništite sve njihove salivene kumire i sve njihove uzvišice porušite.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 33, 53, 'Onda zaposjednite zemlju i u njoj se nastanite, jer sam vam je predao da je zaposjednete.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 33, 54, 'Zemlju razdijelite kockom među svoje rodove. Brojnijem povećajte dio, a manjem smanjite. Gdje god kocka padne, bilo za koga, neka je to njegovo, a prema otačkim plemenima dijelite im baštinu.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 33, 55, 'Ako stanovnike zemlje ispred sebe ne potjerate, onda će oni koje od njih na životu ostavite biti trnje u vašim očima i bodljike u vašim bokovima; dosađivat će vam u zemlji u kojoj budete živjeli');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 33, 56, 'i postupit ću s vama kako sam mislio postupiti s njima.\'\"');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 34, 1, 'Jahve reče Mojsiju:');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 34, 2, '\"Izdaj Izraelcima naredbu i reci im: \'Kad uđete u kanaansku zemlju, ta će vam zemlja pripasti u baštinu, zemlja kanaanska sa svojim granicama.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 34, 3, 'Južna strana protezat će vam se od pustinje Sina uz Edom. Južna će vam granica početi s kraja Slanog mora na istočnoj strani.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 34, 4, 'Onda će vam granica skrenuti na jug, prema Akrabimskoj strmini, i nastaviti se preko Sina. Doprijet će na jugu do Kadeš Barnee; zatim će izaći prema Hasar Adaru i nastaviti se do Asmone.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 34, 5, 'Od Asmone granica će skrenuti prema Egipatskom potoku i izaći će na more.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 34, 6, 'Zapadna granica bit će vam Veliko more; neka vam je to granica prema zapadu.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 34, 7, 'A ovo će vam biti sjeverna granica: od Velikog mora povucite crtu na brdo Hor;');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 34, 8, 's brda Hora onda potegnite crtu do ulaza u Hamat; završetak granice bit će Sedada.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 34, 9, 'Onda će se granica protegnuti do Zifrona i završiti u Hasar Enanu. To će vam biti sjeverna granica.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 34, 10, 'Za svoju istočnu granicu povucite crtu od Hasar Enana do Šefama.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 34, 11, 'Granica će se spuštati od Šefama do Rible, istočno od Ajina. Odande će se granica spustiti i doprijeti do istočne obale Kineretskog jezera.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 34, 12, 'Iza toga spustit će se granica niz Jordan da završi u Slanome moru. To će biti vaša zemlja sa svojim granicama naokolo.\'\"');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 34, 13, 'Tada Mojsije naredi Izraelcima: \"To je zemlja koju ćete kockom dobiti u baštinu, a za koju je zapovjedio Jahve da je dobije devet plemena i polovica jednog plemena.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 34, 14, 'Jer pleme Rubenovaca prema svojim porodicama, zatim pleme Gadovaca prema svojim porodicama već primiše svoju baštinu, kao što je svoju baštinu primila i polovica plemena Manašeova.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 34, 15, 'Ta dva plemena i pol primila su svoje baštine s one strane Jordana, nasuprot Jerihonu, s istočne strane.\"');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 34, 16, 'Jahve reče Mojsiju:');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 34, 17, '\"Ovo su imena ljudi koji će vam zemlju podijeliti: svećenik Eleazar i Nunov sin Jošua;');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 34, 18, 'i od svakoga plemena uzmi po jednoga glavara za razdiobu zemlje.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 34, 19, 'Ovo su imena tih ljudi: Kaleb, sin Jefuneov; od plemena Judina;');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 34, 20, 'Šemuel, sin Amihudov, od plemena Šimunova;');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 34, 21, 'Elidad, sin Kislonov, od plemena Benjaminova;');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 34, 22, 'knez Buki, sin Joglijev, od plemena Danovaca.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 34, 23, 'Od sinova Josipovih: knez Haniel, sin Efodov, od plemena Manašeovaca;');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 34, 24, 'knez Kemuel, sin Šiftanov, od plemena Efrajimovaca;');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 34, 25, 'knez Elisafan, sin Parnakov, od plemena Zebulunovaca;');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 34, 26, 'knez Paltiel, sin Azanov, od plemena Jisakarovaca;');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 34, 27, 'knez Ahihud, sin Šelomijev, od plemena Ašerovaca;');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 34, 28, 'knez Pedahel, sin Amihudov, od plemena Naftalijevaca.\"');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 34, 29, 'To su oni kojima je Jahve naložio da Izraelcima izdijele baštinu u zemlji kanaanskoj.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 35, 1, 'Reče Jahve Mojsiju na Moapskim poljanama kod Jordana, nasuprot Jerihonu:');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 35, 2, '\"Naredi Izraelcima da ustupe levitima od baštine koju posjeduju gradove gdje će stanovati i pašnjake oko gradova. To dajte levitima.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 35, 3, 'Neka gradovi budu njima za stanovanje, a okolni pašnjaci neka budu za njihova goveda, njihovo blago i sve njihove životinje.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 35, 4, 'Pašnjaci uz gradove koje ustupite levitima neka zahvate od gradskih zidina van do tisuću lakata naokolo.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 35, 5, 'Izmjerite od grada van dvije tisuće lakata s istočne strane, dvije tisuće lakata s južne strane, dvije tisuće lakata sa zapadne strane i sa sjeverne strane dvije tisuće lakata, tako da grad bude u sredini. To neka im budu gradski pašnjaci.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 35, 6, 'Od gradova koje budete dali levitima šest će ih biti gradovi-utočišta, koje ćete ustupiti da ubojica može tamo pobjeći. Ovima dodajte još četrdeset i dva grada.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 35, 7, 'Tako će svih gradova koje ustupite levitima biti četrdeset i osam gradova s njihovim pašnjacima.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 35, 8, 'A gradove koje budete izdvajali od vlasništva Izraelaca, od onih koji ih imaju mnogo uzmite više, a manje od onih koji imaju malo. Neka svatko ustupi gradove levitima prema omjeru baštine koju bude primio.\"');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 35, 9, 'Nadalje reče Jahve Mojsiju:');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 35, 10, '\"Govori Izraelcima i reci im: \'Kad prijeđete preko Jordana u zemlju kanaansku,');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 35, 11, 'označite sebi gradove koji će vam služiti kao gradovi-utočišta, kamo može pobjeći ubojica koji nehotice koga ubije.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 35, 12, 'Ti gradovi neka vam budu utočište od osvetnika, tako da ubojica ne moradne poginuti dok ne stane na sud pred zajednicu.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 35, 13, 'Od gradova koje ustupite bit će vam šest gradova za utočište.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 35, 14, 'Dodijelite tri grada s onu stranu Jordana, a tri grada u zemlji kanaanskoj. Neka to budu gradovi-utočišta.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 35, 15, 'Tih šest gradova neka budu za utočište kako Izraelcima tako i strancu i došljaku koji među njima borave, kamo može pobjeći tko god ubije koga nehotice.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 35, 16, 'Ali ako tko udari koga gvozdenim predmetom te ga usmrti, to je onda ubojica. Ubojica mora glavom platiti.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 35, 17, 'Udari li ga iz ruke kamenom od kojega čovjek može poginuti i zbilja pogine, to je opet ubojica. Ubojica mora glavom platiti.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 35, 18, 'Ili ako ga udari iz ruke kakvim drvenim predmetom od kojega može umrijeti i zbilja umre, i to je ubojica. Ubojica mora glavom platiti.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 35, 19, 'Krvni osvetnik mora sam ubojicu usmrtiti. Kad ga sretne, neka ga ubije.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 35, 20, 'Nadalje, ako tko koga gurne iz mržnje ili na nj nešto baci namjerno te ga usmrti,');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 35, 21, 'ili ga udari rukom iz zlobe te udareni umre, napadač mora zaglaviti - on je ubojica. Krvni osvetnik neka ubojicu ubije čim ga sretne.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 35, 22, 'No gurne li ga slučajno, ne iz neprijateljstva, ili nešto na nj baci, ali ne iz zasjede,');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 35, 23, 'ili iz nepažnje na njega obori kakav kamen od kojega čovjek može poginuti te ga usmrti, a nije mu bio neprijatelj niti mu je zlo želio -');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 35, 24, 'tada neka zajednica prosudi između ubojice i krvnog osvetnika prema ovim pravilima:');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 35, 25, 'Zajednica mora izbaviti ubojicu iz ruku krvnog osvetnika; onda neka ga zajednica vrati u grad-utočište kamo je pobjegao; tu neka on ostane do smrti velikoga svećenika koji je bio pomazan svetim uljem.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 35, 26, 'Ali ako ubojica ikad izađe izvan granice utočišta kamo je pobjegao,');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 35, 27, 'pa na nj nabasa krvni osvetnik izvan granica njegova grada-utočišta te krvni osvetnik ubije ubojicu, to mu se ne računa u krvoproliće,');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 35, 28, 'jer ubojica mora ostati u gradu-utočištu do smrti velikoga svećenika. A poslije smrti velikoga svećenika može se vratiti na svoj posjed.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 35, 29, 'Neka vam takvi budu sudbeni postupci od naraštaja do naraštaja svuda gdje budete boravili.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 35, 30, 'Za svako ubojstvo čovjeka kazna smrti nad ubojicom može se izvršiti na dokaz svjedoka. Nitko se ne može smrću kazniti na dokaz samo jednog svjedoka.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 35, 31, 'Ne smijete primati otkupnine za život ubojice koji je zaslužio smrt: on mora umrijeti.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 35, 32, 'Niti smijete primati otkupnine od bilo koga koji, pošto je pobjegao u svoj grad-utočište, hoće da se vrati i da živi na svome tlu prije smrti velikoga svećenika.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 35, 33, 'Nemojte oskvrnjivati zemlje u kojoj živite. A krvoprolićem zemlja se oskvrnjuje. Za zemlju na kojoj je krv prolivena pomirenje se ne može pribaviti, osim krvlju onoga koji ju je prolio.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 35, 34, 'Ne smije se obeščašćivati zemlja u kojoj živite i usred koje ja boravim, jer ja, Jahve, prebivam među sinovima Izraelovim.\'\"');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 36, 1, 'Tada pristupe obiteljski glavari od roda sinova Gileada, sina Makirova, sina Manašeova, jednoga roda Josipovih sinova, te pred Mojsijem i starješinama, glavarima obitelji,');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 36, 2, 'reknu: \"Jahve je naredio našemu gospodaru da kockom dade ovu zemlju u baštinu Izraelcima; nadalje, našem je gospodaru naredio Jahve da baštinu našega brata Selofhada dade njegovim kćerima.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 36, 3, 'Ali ako se one udaju za koga iz drugog izraelskoga plemena, onda će njihova baština biti otrgnuta od naše djedovske baštine i biti priključena baštini plemena kojemu one pripadnu. Tako će se okrnjiti baština koja kockom pripadne nama.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 36, 4, 'A kada nastupi jubilej Izraelcima, baština će se tih žena dodati baštini plemena kojemu pripadnu. Tako će njihova baština biti oduzeta od baštine našega pradjedovskog plemena.\"');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 36, 5, 'I po zapovijedi Jahvinoj Mojsije naredi Izraelcima: \"Pleme Josipovih sinova pravo govori.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 36, 6, 'Ovo naređuje Jahve za Selofhadove kćeri: Neka se one udaju za onoga koji im se učini dobar, samo neka se udaju u rod svoga očinskoga plemena.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 36, 7, 'Baština Izraelaca ne smije se prenositi iz jednoga plemena u drugo; i svaki Izraelac mora ostati privezan uz pradjedovsku baštinu svoga plemena.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 36, 8, 'Zato se svaka djevojka koja steče baštinu u izraelskim plemenima mora udati za nekoga u plemenu kojemu pripada rod joj očev, tako da bi svaki Izraelac sačuvao baštinu svoga oca.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 36, 9, 'Tako se baština neće prenositi iz jednoga plemena u drugo, nego će svako izraelsko pleme prianjati uza svoju baštinu.\"');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 36, 10, 'Kako je Jahve Mojsiju naredio, tako su i učinile kćeri Selofhadove:');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 36, 11, 'Mahla, Tirsa, Hogla, Milka i Noa, kćeri Selofhadove, udaše se za sinove svojih stričeva.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 36, 12, 'Kako su se udale u rod potomstva Manašea, Josipova sina, njihova je baština ostala u plemenu kojemu pripadaše rod im očev.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 36, 13, 'To su zapovijedi i zakoni koje je Jahve preko Mojsija izdao Izraelcima na Moapskim poljanama uz Jordan, nasuprot Jerihonu.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 1, 1, 'Ovo su riječi što ih je Mojsije upravio svemu Izraelu s onu stranu Jordana - u pustinji, u Arabi nasuprot Sufu, između Parana i Tofela, Labana, Hazerota i Di Zahaba -');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 1, 2, 'od Horeba do Kadeš Barnee, Seirskom gorom, jedanaest dana hoda.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 1, 3, 'Bilo je to godine četrdesete, prvog dana mjeseca jedanaestoga, kad Mojsije reče Izraelcima sve što mu je Jahve za njih naređivao.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 1, 4, 'Pošto je porazio amorejskoga kralja Sihona, koji je živio u Hešbonu, i bašanskoga kralja Oga, koji je živio u Aštarotu i Edreju,');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 1, 5, 'dakle s onu stranu Jordana, u zemlji moapskoj, poče Mojsije razlagati ovaj Zakon. Govoraše on:');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 1, 6, '\"Jahve, Bog naš, reče nam na Horebu: \'Dosta ste boravili na ovome brdu.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 1, 7, 'Krenite na put! Idite u gorski kraj Amorejaca i svih njihovih susjeda, u Arabu, u Gorje, u Šefelu i u Negeb, na morsku obalu, u zemlju kanaansku i u Libanon, sve do Velike rijeke, rijeke Eufrata.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 1, 8, 'Eto, pred vas stavljam ovu zemlju. Idite, dakle, i zauzmite zemlju za koju se Jahve zakle ocima vašim, Abrahamu, Izaku i Jakovu, da će je dati njima i njihovu potomstvu poslije njih.\'');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 1, 9, 'Tada sam vam rekao: \'Ne mogu vas voditi sam.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 1, 10, 'Jahve, Bog vaš, toliko vas je razmnožio da vas danas ima kao zvijezda na nebu.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 1, 11, 'Neka vas Jahve, Bog vaših otaca, umnoži još tisuću puta! Neka vas blagoslivlja kako vam je obećao!');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 1, 12, 'Ali kako bih ja sam mogao nositi vaš teret, vaše breme i vaše sporove?');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 1, 13, 'Izaberite stoga iz svojih plemena ljude pametne, iskusne i ugledne da vam ih postavim za poglavare.\'');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 1, 14, 'Vi ste mi odgovorili: \'Dobro je što predlažeš.\'');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 1, 15, 'Zato sam uzeo prvake iz vaših plemena, ljude pametne i ugledne, te ih postavio za poglavare: tisućnike, stotnike, pedesetnike, desetnike i vaše plemenske nadglednike.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 1, 16, 'U to isto vrijeme naložio sam i vašim sucima: \'Saslušajte svoju braću; sudite pravedno između čovjeka i njegova brata ili pridošlice.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 1, 17, 'U suđenju nemojte biti pristrani; saslušavajte maloga kao i velikoga. Ne bojte se nikoga! TÓa sud je Božji! Ako vam koji slučaj bude pretežak, iznesite ga meni, da ga ja razvidim.\'');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 1, 18, 'Tako sam vam onda naložio sve što vam je činiti.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 1, 19, 'Krenusmo iz Horeba i, na putu u gorske krajeve Amorejaca, kako nam je naredio Jahve, Bog naš, prijeđosmo svu onu veliku i strašnu pustinju koju ste vidjeli. Stigosmo u Kadeš Barneu.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 1, 20, 'Tada vam rekoh: \'Došli ste u gorski kraj Amorejaca, koji nam Jahve, Bog naš, daje.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 1, 21, 'Eto, Jahve, Bog tvoj, stavio je preda te tu zemlju. Ustaj! Zaposjedni je, kako ti je rekao Jahve, Bog otaca tvojih. Ne boj se! Ne strahuj!\'');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 1, 22, 'Svi ste onda došli k meni i rekli: \'Pošaljimo pred sobom ljude da izvide zemlju i jave nam o putu kojim ćemo ići i o gradovima u koje ćemo doći.\'');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 1, 23, 'Svidje mi se što rekoste. Zato uzeh dvanaest ljudi između vas, po jednoga iz svakog plemena.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 1, 24, 'Krenuli su na pogorje, stigli do Eškolske doline te izvidjeli kraj.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 1, 25, 'I nabraše plodova one zemlje, donesoše ih k nama i javiše: \'Zemlja koju nam daje Jahve, Bog naš, dobra je.\'');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 1, 26, 'Ali vi niste htjeli onamo; pobunili ste se protiv naredbe Jahve, Boga svoga.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 1, 27, 'Rogoborili ste u svojim šatorima i govorili: \'U svojoj mržnji na nas Jahve nas je izveo iz zemlje egipatske da nas preda u ruke Amorejaca, kako bi nas posve uništili.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 1, 28, 'Kamo da idemo? Naša su braća ubila u nama srčanost kad rekoše: Narod je i veći i jači nego mi; gradovi su veliki, i zidine im sežu do nebesa. A vidjeli smo ondje i Anakovce.\'');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 1, 29, '\'Ne bojte se!\' - rekoh vam. - \'Ne plašite ih se!');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 1, 30, 'Jahve, Bog vaš, koji ide pred vama, borit će se za vas kako je to učinio na vaše oči u Egiptu.\'');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 1, 31, 'A vidio si, uostalom, i u pustinji, gdje te Jahve, Bog tvoj, cijeloga puta što ste ga prevalili dok ste stigli do ovoga mjesta, nosio kao što čovjek nosi svoga sinčića.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 1, 32, 'Ali, unatoč tome, vi niste imali pouzdanja u Jahvu, Boga svoga,');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 1, 33, 'u onoga koji je na putu išao pred vama da vam potraži mjesto za taborovanje - u ognju obnoć da vam osvijetli put kojim ćete ići, a obdan u oblaku.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 1, 34, 'Jahve ču graju vašu i zakle se u svojoj srdžbi:');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 1, 35, '\'Ni jedan jedini od ovih ljudi, od ovoga opakog naraštaja, neće vidjeti ove dobre zemlje za koju sam se zakleo da ću je dati vašim ocima.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 1, 36, 'Izuzimam Kaleba, sina Jefuneova. On će je vidjeti; njemu i njegovim potomcima dat ću zemlju kojom je išao, jer je vjerno slijedio Jahvu.\'');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 1, 37, 'Zbog vas se Jahve i na mene razljutio te mi rekao: \'Ni ti onamo nećeš ući.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 1, 38, 'Ući će onamo Jošua, sin Nunov, koji te služi. Njega ti osokoli, jer će on uvesti Izraela u posjed.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 1, 39, 'A i vaši mališani, o kojima rekoste da će postati roblje, sinovi vaši koji još ne znaju razlikovati dobro i zlo, oni će u nju ući; njima ću je u posjed dati.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 1, 40, 'A vi se okrenite i zaputite u pustinju, prema Crvenome moru!\'');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 1, 41, 'Vi ste mi tada odgovorili riječima: \'Sagriješili smo protiv Jahve. Poći ćemo gore i boriti se kako nam je Jahve, Bog naš, zapovjedio.\' Svaki od vas dohvati svoje oružje i nepromišljeno pođe gore u brda.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 1, 42, 'Onda mi Jahve reče: \'Kaži im: Ne idite gore i ne stupajte u borbu da vas ne poraze vaši neprijatelji jer ja nisam među vama.\'');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 1, 43, 'Tako sam vam i govorio, ali niste poslušali. Oprli ste se zapovijedi Jahvinoj i, puni drskosti, krenuli u brda.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 1, 44, 'Ali Amorejci, koji žive u onome gorju, udariše na vas, pognaše vas, za vama se natisnuše kao pčele te su vas tukli od Seira do Horme.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 1, 45, 'Vrativši se, plakali ste pred Jahvom, ali Jahve nije slušao vašega jauka niti je okrenuo svoga uha k vama.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 1, 46, 'U Kadešu vam valjade ostati dugo vremena, onoliko koliko ste već ostali.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 2, 1, 'Onda se okrenusmo i pođosmo u pustinju prema Crvenome moru, kako mi je Jahve naredio. Dugo smo se vrtjeli oko gore Seira.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 2, 2, 'I reče mi Jahve:');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 2, 3, '\'Dosta ste se vrtjeli oko ovoga brda. Okrenite prema sjeveru!\'');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 2, 4, 'I narodu naloži ovako: \'Sad ćete proći preko područja svoje braće, potomaka Ezavovih, koji žive u Seiru. Oni se vas boje, ali vi dobro pripazite;');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 2, 5, 's njima ne zamećite boja jer vam neću dati ni stope njihove zemlje: goru Seir predao sam Ezavu u vlasništvo.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 2, 6, 'Hranu od njih kupujte za novac da imate što jesti; i vodu za piće kupujte od njih za novac.\'');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 2, 7, 'Ta Jahve te, Bog tvoj, blagoslovio u svim djelima tvojih ruku; on je bdio nad tvojim putovanjem onom velikom pustinjom; ovih četrdeset godina Jahve, Bog tvoj, bijaše s tobom i ništa ti nije nedostajalo.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 2, 8, 'Tako smo svoju braću, potomke Ezavove što žive u Seiru, zaobišli putem što vodi u Arabu, Elat i Esjon Geber, a onda udarismo prema Moapskoj pustinji.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 2, 9, 'Tada mi zapovjedi Jahve: \'Nemoj uznemirivati Moapce niti s njima zameći boja, jer ništa od njihove zemlje neću dati u tvoje vlasništvo: Lotovim sinovima predao sam Ar u posjed.\'');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 2, 10, 'Prije su ondje živjeli Emijci. Bio je to moćan narod i brojan; krupna stasa kao i Anakovci.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 2, 11, 'Poput Anakovaca, i njih smatraju Refaimcima, ali ih Moapci nazivaju Emijcima.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 2, 12, 'Isto su tako u Seiru živjeli prije Horijci, ali su ih Ezavovi potomci izvlastili, istrijebili ih i naselili se na njihovo, kako je, uostalom, učinio Izrael sa zemljom - baštinom svojom - koju mu je Jahve predao.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 2, 13, '\'A sada ustanite i prijeđite preko potoka Zereda!\' I prijeđosmo potok Zered.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 2, 14, 'Vrijeme što smo išli od Kadeš Barnee pa dok smo prešli preko potoka Zereda iznosilo je trideset i osam godina - sve dok nije izumro iz tabora sav onaj naraštaj ljudi sposobnih za borbu, kako im se Jahve i zakleo.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 2, 15, 'I zbilja! Ruka Jahvina bila je protiv njih: istrebljivala ih je isred tabora dok ih nije nestalo.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 2, 16, 'I tako, kad je smrt istrijebila iz naroda sve ljude sposobne za borbu,');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 2, 17, 'reče mi Jahve:');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 2, 18, '\'Danas prelaziš moapsku zemlju Ar.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 2, 19, 'A onda ćeš se približiti Amoncima. Nemoj ih uznemirivati niti s njima zameći boja. Ništa, naime, od zemlje Amonaca neću ustupiti tebi u vlasništvo jer sam je već predao u posjed Lotovim potomcima.\'');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 2, 20, 'I nju smatraju refaimskom zemljom. U njoj su prije živjeli Refaimci, koje Amonci zovu Zamzumijcima.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 2, 21, 'Bio je to narod moćan i brojan; krupna stasa kao i Anakovci. No Jahve ih uništi pred Amoncima - koji ih izvlastiše i naseliše se na njihovo,');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 2, 22, 'kako je, uostalom, učinio i potomcima Ezavovim, koji su nastanjeni u Seiru, kad je pred njima uništio Horijce, koje su oni otjerali s posjeda i do danas žive na njihovim mjestima.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 2, 23, 'I Avijce, koji su živjeli po zaseocima sve do Gaze, istrijebiše Kaftorci koji su došli iz Kaftora te se naseliše na njihovo mjesto.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 2, 24, '\'Ustajte! Na put krenite i prijeđite preko potoka Arnona. U ruke ti, eto, predajem Amorejca Sihona, kralja hešbonskoga, i njegovu zemlju. Počni s osvajanjem; izazovi ga na boj!');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 2, 25, 'Od danas počinjem ugoniti strah i trepet pred tobom u narode koji su pod svim nebesima, tako da će strepiti i tresti se pred tobom kad god čuju glas o tebi.\'');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 2, 26, 'Tada sam iz pustinje Kedmot uputio glasnike kralju hešbonskom Sihonu s miroljubivim riječima:');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 2, 27, '\'Pusti da prođem preko tvoje zemlje. Samo ću proći putem, ne skrećući ni desno ni lijevo.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 2, 28, 'Hranu mi prodavaj za novac da mogu jesti; i vodu za piće davaj mi za novac. Pusti me samo da pješice prođem,');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 2, 29, 'da prijeđem preko Jordana u zemlju koju nam daje Jahve, Bog naš - kao što su mi dopustili potomci Ezavovi, nastanjeni u Seiru, i Moapci, što žive u Aru.\'');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 2, 30, 'Ali hešbonski kralj Sihon ne htjede nas pustiti preko svoga; jer Jahve, Bog tvoj, duh mu zaslijepi a srce otvrdnu, da ga preda u tvoje šake, gdje je i danas.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 2, 31, 'Tada mi reče Jahve: \'Eto sam počeo da ti izručujem Sihona i njegovu zemlju. Počni osvajanje da mu zemljom zagospodariš.\'');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 2, 32, 'Kod Jahasa presrete nas Sihon.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 2, 33, 'Navali on i sav njegov narod. Ali Jahve, Bog naš, predade nam ga, tako da potukosmo njega, njegove sinove i sav njegov narod.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 2, 34, 'Tada osvojismo sve njegove gradove i prokletstvom udarismo sve gradove s ljudima, ženama i djecom, ništa ne štedeći,');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 2, 35, 'izuzev stoke, koju uzesmo kao plijen, skupa s plijenom iz gradova što smo ih osvojili.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 2, 36, 'Od Aroera, koji se nalazi na obali potoka Arnona, i od grada koji je u njegovoj dolini pa do Gileada nije bilo grada koji bi nam odolio: sve nam ih je Jahve, Bog naš, predao.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 2, 37, 'Jedino se nisi primicao zemlji Amonaca, kraju uz potok Jabok, i gradovima u pogorju, kako je Jahve, Bog naš, odredio.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 3, 1, 'Tada se okrenusmo i pođosmo prema Bašanu. Presrete nas bašanski kralj Og sa svim svojim narodom i nametnu nam boj kod Edreja.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 3, 2, 'Tada mi Jahve reče: \'Ne boj ga se! TÓa u tvoje sam ruke predao njega, sav njegov narod i njegovu zemlju. Učini s njim kako si učinio sa Sihonom, kraljem amorejskim, koji je živio u Hešbonu.\'');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 3, 3, 'Tako je Jahve, Bog naš, u ruke naše predao i bašanskoga kralja Oga sa svim njegovim narodom. Tukli smo ga tako da mu nitko na životu nije ostao.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 3, 4, 'Osvojili smo tada sve njegove gradove. Nije bilo grada koji im nismo oteli - šezdeset gradova, zapravo svu argopsku krajinu, Ogovo kraljevstvo u Bašanu.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 3, 5, 'Svi su oni gradovi bili utvrđeni visokim zidinama, vratima i prijevornicama. Uz njih je bilo veoma mnogo otvorenih zaselaka.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 3, 6, 'Udarismo ih prokletstvom - kako smo učinili i sa Sihonom, kraljem hešbonskim - zatrvši svaki grad, ljude, žene i djecu.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 3, 7, 'A svu stoku i plijen po tim gradovima zadržasmo za se.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 3, 8, 'Tako smo u ono vrijeme iz ruku dvaju amorejskih kraljeva uzeli zemlju što se nalazi s onu stranu Jordana, od potoka Arnona do brda Hermona (');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 3, 9, 'Sidonci zovu Hermon Sirjon, a Amorejci ga zovu Senir):');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 3, 10, 'sve gradove po Visoravni, sav Gilead i sav Bašan, sve do Salke i Edreja - gradove Ogova kraljevstva u Bašanu. (');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 3, 11, 'Bašanski kralj Og jedini je od preostalih Refaimovaca. Krevet njegov, odar od željeza, još se nalazi u Rabi, gradu sinova Amonovih: deset je lakata - običnih lakata - dug, a četiri lakta širok.)');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 3, 12, 'To je, dakle, bila zemlja koju smo zauzeli u ono vrijeme, počev od Aroera, koji je na potoku Arnonu. Polovicu gileadskog pogorja s njegovim gradovima dao sam Rubenovcima i Gadovcima.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 3, 13, 'Ostatak Gileada i sav Bašan, Ogovo kraljevstvo, dodijelio sam polovini Manašeova plemena. (Sva argopska krajina i sav Bašan zove se zemlja refaimska.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 3, 14, 'Manašeov sin Jair zauzeo je svu argopsku krajinu do međe Gešurovaca i Maakinovaca. On ta mjesta bašanska nazva svojim imenom, pa se još i danas zovu Jairova Sela.)');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 3, 15, 'Makiru sam dodijelio Gilead.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 3, 16, 'Rubenovcima i Gadovcima dao sam od Gileada do potoka Arnona - sredina potoka jest međa - i do potoka Jaboka, amonske granice.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 3, 17, 'A granicom su služile Araba i Jordan od Kinereta do mora uz Arabu - Slanog mora - na podnožju obronaka Pisge prema istoku.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 3, 18, 'U ono vam vrijeme naredih: \'Jahve, Bog vaš, daje vam ovu zemlju u posjed. Svi vi koji ste od boja pođite naoružani pred svojom braćom Izraelcima.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 3, 19, 'Jedino žene vaše, djeca vaša i stoka vaša - znam da imate mnogo stoke - neka ostanu u vašim gradovima što vam ih dodijelih');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 3, 20, 'dokle Jahve ne dadne miran boravak i vašoj braći kao i vama; tako da i oni zauzmu zemlju što im je Jahve, Bog vaš, daje s onu stranu Jordana. Istom onda neka se svaki od vas vrati na posjed što sam vam ga dodijelio.\'');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 3, 21, 'U ono sam vrijeme naredio Jošui: \'Svojim si očima vidio što je sve Jahve, Bog vaš, učinio onoj dvojici kraljeva. Tako će Jahve učiniti sa svim kraljevstvima preko kojih budeš prelazio.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 3, 22, 'Ne bojte se njih! TÓa Jahve, Bog vaš, bori se za vas.\'');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 3, 23, 'Tada zamolih milost u Jahve:');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 3, 24, '\'Gospodine moj, Jahve! Ti si počeo pokazivati svome sluzi svoju veličajnost i svoju moć. TÓa koji bog, na nebu ili na zemlji, može izvesti takva djela i čudesa kao što su tvoja!');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 3, 25, 'Dopusti mi da odem onamo i pogledam onu blaženu zemlju preko Jordana, onaj krasni gorski kraj i Libanon!\'');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 3, 26, 'Ali je Jahve, zbog vas, bio na me ljut, pa me nije uslišao. \'Dosta\', reče mi Jahve, \'ne govori mi više o tom!');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 3, 27, 'Popni se na vrhunac Pisge i upri oči svoje na zapad, sjever, jug i istok. Razmotri dobro očima svojim, jer preko Jordana nećeš prijeći.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 3, 28, 'Uputi Jošuu, osokoli ga i ohrabri! On neka ide na čelu ovoga naroda; neka ih on uvede u posjed zemlje koju vidiš.\'');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 3, 29, 'Tako smo ostali u toj dolini kraj Bet Peora.\"');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 4, 1, '\"A sada, Izraele, poslušaj zakone i uredbe kojima vas učim da biste ih vršili i tako poživjeli te unišli i zaposjeli zemlju koju vam daje Jahve, Bog otaca vaših.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 4, 2, 'Niti što nadodajite onome što vam zapovijedam niti što od toga oduzimljite; vršite zapovijedi Jahve, Boga svoga, što vam ih dajem.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 4, 3, 'Vidjeli ste svojim očima što je Jahve učinio s Baal Peorom: jer Jahve, Bog tvoj, iskorijenio je iz tvoje sredine svakoga koji je slijedio Baal Peora.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 4, 4, 'A svi vi koji se čvrsto držite Jahve, Boga svoga, živi ste i danas.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 4, 5, 'Ja sam vas, eto, poučio o zakonima i uredbama, kako mi je Jahve, Bog moj, naredio da ih vršite u zemlji u koju idete da je zaposjednete.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 4, 6, 'Držite ih i vršite: to će u očima naroda biti vaša mudrost i vaša razboritost. Kad oni čuju za sve ove zakone, reći će: \'Samo je jedan narod mudar i pametan, a to je ovaj veliki narod.\'');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 4, 7, 'Jer koji je to narod tako velik da bi mu bogovi bili tako blizu kao što je Jahve, Bog naš, nama kad god ga zazovemo?');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 4, 8, 'Koji je to narod tako velik da bi imao zakone i uredbe pravedne kao što je sav ovaj Zakon koji vam ja danas iznosim?');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 4, 9, 'Zato pazi i dobro se čuvaj da ne zaboraviš događaje što si ih svojim očima vidio; neka ti ne iščeznu iz srca ni jednoga dana tvoga života; naprotiv, pouči o njima svoje sinove i sinove svojih sinova.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 4, 10, 'Onog dana kad si stajao na Horebu pred Jahvom, Bogom svojim, Jahve mi je rekao: \'Skupi mi narod! Hoću da čuju moje riječi, da me se nauče bojati sve vrijeme što budu živjeli na zemlji te da o njima pouče i svoju djecu.\'');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 4, 11, 'Vi ste se onda primakli i stali pod brdo. S usplamtjeloga brda plamen je sukljao do sred neba zamračena tmastim oblakom.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 4, 12, 'Isred ognja Jahve je govorio vama; čuli ste zvuk riječi, ali lika niste nazreli - ništa osim glasa.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 4, 13, 'Objavio vam je svoj Savez i naložio vam da ga vršite - Deset zapovijedi, što ih ispisa na dvije kamene ploče.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 4, 14, 'A meni je Jahve naredio da vas poučim o zakonima i uredbama što ćete ih vršiti u zemlji u koju odlazite da je zaposjednete.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 4, 15, 'Pazite dobro! Onoga dana kad vam je Jahve, Bog vaš, govorio isred ognja na Horebu, niste vidjeli nikakva lika,');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 4, 16, 'da se ne biste pokvarili te da ne biste pravili sebi kakva klesana lika, kipa muškoga ili ženskoga obličja,');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 4, 17, 'ni obličja kakve životinje što je na zemlji, ni obličja kakve ptice što pod nebom lijeta,');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 4, 18, 'ni obličja bilo čega što po zemlji gmiže, ni obličja kakve ribe što je u vodi pod zemljom');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 4, 19, 'i da se ne bi, kad digneš svoje oči prema nebu te vidiš sunce, mjesec i zvijezde - svu nebesku vojsku - dao zavesti da im se klanjaš i da im iskazuješ štovanje. Njih je Jahve, Bog tvoj, dao svim narodima, svugdje pod nebom.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 4, 20, 'A vas je uzeo Jahve i izveo vas iz Egipta - iz one peći ražarene - da postanete narod njegove baštine, to što ste danas.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 4, 21, 'Ali se zbog vas Jahve na me razljutio i zakleo da ja neću prijeći preko Jordana i unići u blaženu zemlju koju ti Jahve, Bog tvoj, daje u baštinu.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 4, 22, 'Tako, ja ću umrijeti u ovoj zemlji; ja preko Jordana neću prijeći. A vi ćete prijeći i zaposjesti onu krasnu zemlju.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 4, 23, 'Zato pazite da ne zaboravljate Saveza što ga je Jahve, Bog vaš, sklopio s vama te sebi ne pravite klesanih likova bilo čega što je Jahve, Bog tvoj, zabranio.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 4, 24, 'Jer Jahve, Bog tvoj, oganj je što proždire; on je Bog ljubomoran.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 4, 25, 'Kad budete izrodili djecu i unučad i budete dulje u onoj zemlji proboravili, a pokvarite se praveći sebi bilo kakve klesane likove i čineći zlo u očima Jahve, Boga svojega, tako da ga na srdžbu izazovete,');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 4, 26, 'znajte - uzimam za svjedoke protiv vas nebesa i zemlju - da će vas brzo nestati sa zemlje u koju idete preko Jordana da je zaposjednete: nećete dugo u njoj živjeti nego ćete biti iskorijenjeni.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 4, 27, 'Jahve će vas raspršiti po narodima i ostat će vas samo malen broj među narodima među koje vas Jahve odvede.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 4, 28, 'Ondje ćete se klanjati bogovima što su ih ljudske ruke načinile od drveta i kamena, bogovima koji ne mogu ni vidjeti ni čuti, ni jesti ni mirisati.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 4, 29, 'Ondje ćeš tražiti Jahvu, Boga svoga. I naći ćeš ga ako ga budeš tražio svim srcem svojim i svom dušom svojom.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 4, 30, 'U nevolji tvojoj snaći će te sve to, ali u posljednje vrijeme ti ćeš se obratiti Jahvi, Bogu svomu, i poslušati njegov glas.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 4, 31, 'TÓa Jahve, Bog tvoj, Bog je milosrdan; neće te on zapustiti ni upropastiti niti će zaboraviti Saveza što ga je pod zakletvom sklopio s ocima tvojim.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 4, 32, 'Ispitaj samo prijašnja vremena što su protekla prije tebe, sve otkad je Bog stvorio čovjeka na zemlji: je li ikad, s jednoga kraja nebesa do drugoga, bilo ovako veličanstvena događaja? Je li se što takvo čulo?');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 4, 33, 'Je li ikad koji narod čuo glas Boga gdje govori isred ognja kao što si ti čuo i na životu ostao?');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 4, 34, 'Ili, pokuša li koji bog da ode i uzme sebi jedan narod isred drugog naroda kušnjama, znakovima, čudesima i ratom, jakom rukom i ispruženom mišicom, uza silne strahote, kao što je sve to, na vaše oči, učinio za vas Jahve, Bog vaš, u Egiptu?');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 4, 35, 'Tebi je to pokazano da znaš da je Jahve pravi Bog i da nema drugoga uz njega.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 4, 36, 'S neba ti se oglasio svojim glasom da te pouči; dopustio ti je da vidiš njegov veliki oganj na zemlji; i isred ognja čuo si njegove riječi.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 4, 37, 'Zbog toga što je ljubio očeve tvoje, izabrao je poslije njih njihovo potomstvo; on, glavom, izveo te iz Egipta svojom silnom moći;');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 4, 38, 'ispred tebe rastjerao je narode, i brojnije i jače od tebe, da te dovede u njihovu zemlju i preda je tebi u baštinu, kao što je i danas.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 4, 39, 'Danas, dakle, spoznaj i zasadi u svoje srce: Jahve je Bog gore na nebu i ovdje na zemlji - drugoga nema.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 4, 40, 'Drži njegove zakone i njegove zapovijedi koje ti dajem danas da dobro bude tebi i tvojoj djeci poslije tebe; da dugo poživiš na zemlji koju ti Jahve, Bog tvoj, daje zauvijek.\"');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 4, 41, 'Tada Mojsije izabra tri grada preko Jordana, na istočnoj strani,');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 4, 42, 'kamo će se moći skloniti ubojica koji nehotice ubije svoga bližnjega a da prije nije imao mržnje prema njemu: da bi, bježeći u koji od ovih gradova, mogao spasiti svoj život.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 4, 43, 'To su: Bezer u pustinji, u zemlji Mišoru, za Rubenovce; Ramot u Gileadu za Gadovce, i Golan u Bašanu za Manašeovce.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 4, 44, 'Ovo je Zakon što ga je Mojsije postavio pred Izraelce;');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 4, 45, 'ovo su upute, zakoni i uredbe što ih je Mojsije dao Izraelcima kad su izišli iz Egipta,');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 4, 46, 's one strane Jordana, u dolini nasuprot Bet Peoru, u zemlji amorejskoga kralja Sihona, koji je živio u Hešbonu i koga su potukli Mojsije i Izraelci pošto iziđoše iz Egipta.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 4, 47, 'Njegovu su zemlju zauzeli i zemlju bašanskoga kralja Oga, dvaju amorejskih kraljeva koji su živjeli preko Jordana na istoku,');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 4, 48, 'od Aroera, koji se nalazi na obali potoka Arnona, do brda Sirjona, to jest Hermona,');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 4, 49, 'i svu Arabu preko Jordana, s istoka do mora u Arabi, pod obroncima Pisge.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 5, 1, 'Mojsije sazva sav Izrael te im reče: \"Čuj, Izraele, naredbe i zapovijedi što ih danas izričem u tvoje uši! Naučite ih, držite i vršite.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 5, 2, 'Jahve, Bog naš, sklopio je s nama Savez na Horebu.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 5, 3, 'Nije Jahve sklopio taj Savez s našim očevima, nego baš s nama svima koji smo danas ovdje živi.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 5, 4, 'Licem je u lice Jahve govorio s vama na brdu isred ognja.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 5, 5, 'Ja sam u ono vrijeme stajao između Jahve i vas da vam objavim Jahvine riječi, jer se vi, u strahu od ognja, niste htjeli peti na brdo. Rekao je:');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 5, 6, '\'Ja sam Jahve, Bog tvoj, koji sam te izveo iz zemlje egipatske, iz kuće ropstva.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 5, 7, 'Nemoj imati drugih bogova uz mene!');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 5, 8, 'Ne pravi sebi lika ni obličja bilo čega što je gore na nebu, ili dolje na zemlji, ili u vodama pod zemljom.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 5, 9, 'Ne klanjaj im se niti im služi. Jer ja, Jahve, Bog tvoj, Bog sam ljubomoran. Kažnjavam grijeh otaca - onih koji me mrze - na djeci do trećeg i četvrtog koljena,');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 5, 10, 'a iskazujem milosrđe tisućama koji me ljube i vrše moje zapovijedi.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 5, 11, 'Ne uzimaj uzalud imena Jahve, Boga svoga, jer Jahve ne oprašta onome koji uzalud izgovara ime njegovo.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 5, 12, 'Dan subotnji obdržavaj i svetkuj, kako ti je naredio Jahve, Bog tvoj.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 5, 13, 'Šest dana radi i obavljaj sav svoj posao.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 5, 14, 'A sedmoga je dana subota, počinak posvećen Jahvi, Bogu tvome. Tada nikakva posla nemoj raditi: ni ti, ni sin tvoj, ni kći tvoja, ni sluga tvoj, ni sluškinja tvoja, ni vol tvoj, ni magarac tvoj, niti ikakvo živinče tvoje, niti došljak koji je unutar tvojih vrata; tako da mogne otpočinuti i sluga tvoj, i sluškinja tvoja kao i ti.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 5, 15, 'Sjeti se da si i ti bio rob u zemlji egipatskoj i da te odande izbavio Jahve, Bog tvoj, rukom jakom i ispruženom mišicom. Zato ti je zapovjedio Jahve, Bog tvoj, da držiš dan subotnji.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 5, 16, 'Poštuj oca svoga i majku svoju, kako ti je Jahve, Bog tvoj, zapovjedio, da dugo živiš i dobro ti bude na zemlji koju ti Jahve, Bog tvoj, daje.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 5, 17, 'Ne ubij!');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 5, 18, 'Ne učini preljuba!');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 5, 19, 'Ne ukradi!');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 5, 20, 'Ne svjedoči lažno na bližnjega svoga!');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 5, 21, 'Ne poželi žene bližnjega svoga! Ne poželi kuće bližnjega svoga, ni njive njegove, ni sluge njegova, ni sluškinje njegove, ni vola njegova, ni magarca njegova, niti išta što je bližnjega tvoga.\'');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 5, 22, 'Te je riječi na brdu, isred ognja, oblaka i guste tmine, jakim glasom upravio Jahve svemu vašem zboru. Ništa nije dodavao nego ih je ispisao na dvije kamene ploče te ih predao meni.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 5, 23, 'A onda, kad čuste glas iz tmine, dok je brdo plamtjelo u ognju, k meni pristupiše svi vaši plemenski glavari i vaše starješine');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 5, 24, 'pa rekoše: \'Jahve, Bog naš, očitovao nam je, eto, svoju slavu i svoju veličajnost; čuli smo njegov glas isred ognja; danas smo vidjeli da čovjek može ostati na životu iako mu Bog govori.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 5, 25, 'A sad, zašto da umremo? Ovaj bi nas veliki oganj mogao proždrijeti; budemo li dalje slušali glas Jahve, Boga svoga, mogli bismo umrijeti.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 5, 26, 'Jer, koji je smrtnik ikad slušao glas Boga živoga kako govori isred ognja - kao mi - i ostao na životu?');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 5, 27, 'Ti se primakni i slušaj sve što će ti reći Jahve, Bog naš. A onda ti nama kaži sve što tebi Jahve, Bog naš, rekne, i mi ćemo to poslušati i izvršiti.\'');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 5, 28, 'Jahve je čuo vaše riječi kad ste mi govorili pa mi reče: \'Čuo sam riječi što ih je taj narod tebi upravio. Sve što su rekli dobro je.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 5, 29, 'Kad bi samo njihova srca bila takva da me se uvijek boje i drže sve moje zapovijedi, da tako vazda budu sretni, oni i njihovo potomstvo!');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 5, 30, 'Hajde, reci im: Vratite se u svoje šatore!');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 5, 31, 'A ti ostani ovdje kod mene; kazat ću ti sve zapovijedi, zakone i uredbe kojima ćeš ih poučiti i koje će oni vršiti u zemlji što im je dajem u posjed.\'');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 5, 32, 'Pazite, dakle, da radite kako vam je Jahve, Bog vaš, naložio! Ne skrećite ni desno ni lijevo.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 5, 33, 'Slijedite potpuno put koji vam je Jahve, Bog vaš, označio, da tako uzmognete živjeti, imati sreću i dug život u zemlji koju ćete zaposjesti.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 6, 1, 'Ovo su zapovijedi, zakoni i uredbe koje mi Jahve, Bog vaš, zapovjedi da vas u njima poučim, kako biste ih vršili u zemlji u koju odlazite da je zaposjednete;');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 6, 2, 'da se svega svog vijeka bojiš Jahve, Boga svoga, ti, sin tvoj i sin tvoga sina, vršeći sve zakone njegove i sve zapovijedi njegove što ti ih danas propisujem, pa da imaš dug život.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 6, 3, 'Slušaj, Izraele, drži ih i vrši da ti dobro bude i da se razmnožiš u zemlji kojom teče med i mlijeko, kao što ti je obećao Jahve, Bog otaca tvojih.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 6, 4, 'Čuj, Izraele! Jahve je Bog naš, Jahve je jedan!');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 6, 5, 'Zato ljubi Jahvu, Boga svoga, svim srcem svojim, svom dušom svojom i svom snagom svojom!');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 6, 6, 'Riječi ove što ti ih danas naređujem neka ti se urežu u srce.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 6, 7, 'Napominji ih svojim sinovima. Govori im o njima kad sjediš u svojoj kući i kad ideš putem; kad liježeš i kad ustaješ.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 6, 8, 'Priveži ih na svoju ruku za znak i neka ti budu kao zapis među očima!');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 6, 9, 'Ispiši ih na dovratnicima kuće svoje i na vratima svojim!');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 6, 10, 'A kad te Jahve, Bog tvoj, dovede u zemlju za koju se zakleo tvojim ocima, Abrahamu, Izaku i Jakovu, da će je tebi dati - u velike i lijepe gradove kojih nisi zidao;');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 6, 11, 'u kuće pune svakog dobra kojih nisi punio; na iskopane čatrnje kojih nisi kopao; u vinograde i maslinike kojih nisi sadio - i sit se najedeš:');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 6, 12, 'pazi da ne zaboraviš Jahvu koji te izveo iz zemlje egipatske, iz kuće ropstva.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 6, 13, 'Boj se Jahve, Boga svoga; njemu iskazuj štovanje; njegovim imenom polaži prisegu.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 6, 14, 'Ne idite za drugim bogovima između bogova drugih naroda što su oko vas.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 6, 15, 'Jer je Jahve, Bog tvoj, što stoji u sredini tvojoj, ljubomoran Bog; gnjev bi Jahve, Boga tvoga, usplamtio protiv tebe i istrijebio te sa zemlje.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 6, 16, 'Ne iskušavajte Jahvu, Boga svoga, kao što ste ga iskušavali kod Mase.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 6, 17, 'Točno vršite zapovijedi Jahve, Boga svoga, upute njegove i zakone njegove koje je izdao.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 6, 18, 'Čini što je pravo i dobro u očima Jahve da ti dobro bude i da se domogneš dobre zemlje za koju se Jahve zakleo tvojim ocima');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 6, 19, 'da će iz nje protjerati sve tvoje neprijatelje ispred tebe; tako je obećao Jahve.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 6, 20, 'A kad te sutra zapita tvoj sin: što su te upute, zakoni i uredbe što ih je Jahve, Bog naš, vama propisao -');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 6, 21, 'kaži svome sinu: \'Bili smo faraonovi robovi u Egiptu, ali nas je Jahve izveo iz Egipta jakom rukom.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 6, 22, 'Na naše je oči Jahve učinio velike i strašne znakove i čudesa protiv Egipta, protiv faraona i protiv svega doma njegova,');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 6, 23, 'a nas je odande izveo da nas dovede i dade nam zemlju koju je zakletvom obećao ocima našim.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 6, 24, 'I naredio nam je Jahve da sve ove naredbe vršimo u strahopoštovanju prema Jahvi, Bogu svome, da bismo uvijek bili sretni i da živimo kao što je to danas.\'');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 6, 25, 'Naša će, dakle, pravednost biti: držati i vršiti sve ove zapovijedi pred Jahvom, Bogom našim, kako nam je naredio.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 7, 1, 'Kad te Jahve, Bog tvoj, uvede u zemlju u koju ideš da je zaposjedneš i kad ispred tebe otjera mnoge narode: Hetite, Girgašane, Amorejce, Kanaance, Perižane, Hivijce i Jebusejce - sedam naroda brojnijih i jačih od tebe -');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 7, 2, 'te kad ih Jahve, Bog tvoj, preda tebi i ti ih poraziš, udari ih prokletstvom; nemoj sklapati s njima saveza niti im iskazuj milosti.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 7, 3, 'Ne sklapaj ženidbe s njima, ne udavaj svoje kćeri za njihova sina niti ženi svoga sina njihovom kćeri;');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 7, 4, 'jer bi ona odvratila od mene sina tvoga; drugim bi bogovima on služio; Jahve bi se razgnjevio protiv vas i brzo bi te istrijebio.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 7, 5, 'Nego ovako učinite prema njima: porušite njihove žrtvenike, porazbijajte njihove stupove, njihove ašere počupajte a njihove kumire spalite.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 7, 6, 'TÓa ti si narod posvećen Jahvi, Bogu svome; tebe je Jahve, Bog tvoj, izabrao da među svim narodima koji su na zemlji budeš njegov predragi vlastiti narod.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 7, 7, 'Nije vas Jahve odabrao i prihvatio zato što biste vi bili brojniji od svih naroda - vi ste zapravo najmanji -');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 7, 8, 'nego zato što vas Jahve ljubi i drži zakletvu kojom se zakleo vašim ocima. Stoga vas je Jahve izveo jakom rukom i oslobodio vas iz kuće ropstva, ispod vlasti faraona, kralja egipatskoga.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 7, 9, 'Zato znaj da je Jahve, Bog tvoj, pravi Bog, Bog vjeran, koji drži svoj Savez i milost svoju iskazuje do tisuću koljena onima koji ga ljube i drže njegove zapovijedi.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 7, 10, 'A onima koji ga mrze uzvraća izravno njima samima; uništava bez odgađanja onoga koji ga mrzi: uzvraća izravno njemu samomu.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 7, 11, 'Stoga drži zapovijedi, zakone i uredbe koje ti danas nalažem da ih vršiš.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 7, 12, 'A za nagradu - budeš li slušao ove naloge, držao ih te izvršavao - Jahve, Bog tvoj, držat će ti Savez svoj i milost za koje se zakleo tvojim ocima.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 7, 13, 'Ljubit će te, blagoslivljati i razmnažati; blagoslivljat će plod utrobe tvoje i rod zemlje tvoje: žito tvoje, vino tvoje, ulje tvoje, mlad krava tvojih i prirast stoke tvoje u zemlji za koju se zakleo ocima tvojim da će je tebi dati.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 7, 14, 'Bit ćeš blagoslovljen nad sve narode; neće u tebe biti ni neplodna ni neplodne, ni među tvojom čeljadi ni među stokom tvojom.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 7, 15, 'Jahve će od tebe maknuti svaku bolest; neće na te pustiti ni jedno od strašnih zala egipatskih za koja znaš nego će njima pritiskati one koji te mrze.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 7, 16, 'Uništavaj sve narode koje ti Jahve, Bog tvoj, bude predavao. Neka ih ne sažaljuje oko tvoje. Nemoj se klanjati njihovim kumirima, jer bi ti to bilo zamkom.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 7, 17, 'Možda ćeš u svome srcu reći: \'Oni su narodi brojniji od mene, kako ću ih onda protjerati?\'');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 7, 18, 'Ne boj ih se! Sjeti se što je Jahve, Bog tvoj, učinio faraonu i svemu Egiptu!');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 7, 19, 'Pomisli na velike kušnje što si ih vidio na svoje oči; na one znakove i čudesa pa na jaku ruku i ispruženu mišicu kojima te Jahve, Bog tvoj, izveo. Tako će Jahve, Bog tvoj, učiniti sa svim narodima kojih se plašiš.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 7, 20, 'Povrh toga, među njih će Jahve, Bog tvoj, slati stršljene dok ne izginu koji bi preostali i sakrili se pred tobom.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 7, 21, 'Ne strepi, dakle, pred njima! TÓa Jahve, Bog tvoj, u sredini je tvojoj, Bog silan i strahovit.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 7, 22, 'Malo će pomalo Jahve, Bog tvoj, ispred tebe uništiti one narode; i nećeš ih moći ujedanput sve istrijebiti da se zvijeri ne bi protiv tebe razmnožile.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 7, 23, 'Ali Jahve, Bog tvoj, tebi će ih predati i među njih unositi stravu dok ne budu uništeni.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 7, 24, 'I njihove će kraljeve predati u tvoje ruke da zatreš ime njihovo pod nebom. Nijedan se neće održati pred tobom dok ih ne uništiš.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 7, 25, 'Likove njihovih kumira spali! Ne hlepi za srebrom i zlatom što je na njima; ne uzimlji ga da ne budeš njime zaveden; jer bi to bilo gadno Jahvi, Bogu tvome.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 7, 26, 'Ne unosi gnusobe u svoju kuću da ne budeš udaren prokletstvom kao i ona; duboko je prezri i grozi se od nje jer je prokleta.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 8, 1, 'Držite i vršite sve zapovijedi koje vam danas naređujem da biste živjeli i raznmožili se i da biste ušli i zaposjeli zemlju koju je Jahve pod zakletvom obećao ocima vašim.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 8, 2, 'Sjećaj se svega puta kojim te Jahve, Bog tvoj, vodio po pustinji ovih četrdeset godina da te ponizi, iskuša i dozna što ti je u srcu: hoćeš li držati zapovijedi njegove ili nećeš.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 8, 3, 'Ponižavao te i glađu morio, a onda te hranio manom - za koju nisi znao ni ti ni tvoji oci - da ti pokaže kako čovjek ne živi samo o kruhu nego da čovjek živi o svemu što izlazi iz usta Jahvinih.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 8, 4, 'Tvoja se odjeća na tebi nije izderala niti su ti noge oticale ovih četrdeset godina.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 8, 5, 'Priznaj onda u svome srcu da te Jahve, Bog tvoj, odgaja i popravlja, kao što čovjek odgaja sina svoga.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 8, 6, 'I drži zapovijedi Jahve, Boga svoga, hodeći putovima njegovim i bojeći se njega!');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 8, 7, 'TÓa Jahve, Bog tvoj, vodi te u dobru zemlju: zemlju potoka i vrela, dubinskih voda što izviru u dolinama i bregovima;');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 8, 8, 'zemlju pšenice i ječma, loze, smokava i šipaka, zemlju meda i maslina;');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 8, 9, 'zemlju u kojoj nećeš sirotinjski jesti kruha i gdje ti ništa neće nedostajati; zemlju gdje kamenje ima željeza i gdje ćeš iz njezinih brdina vaditi mjed.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 8, 10, 'Do sita ćeš jesti i blagoslivljati Jahvu, Boga svoga, zbog dobre zemlje koju ti je dao.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 8, 11, 'Čuvaj se da ne zaboraviš Jahvu, Boga svoga, zanemarujući njegove zapovijedi, njegove uredbe i njegove zakone koje ti danas dajem.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 8, 12, 'I pošto se najedeš do sitosti, posagradiš lijepe kuće i u njima se nastaniš;');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 8, 13, 'kad ti se krupna i sitna stoka namnoži; kad se nakupiš srebra i zlata i kada sve tvoje uznapreduje,');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 8, 14, 'nemoj da se uznese srce tvoje i da zaboraviš Jahvu, Boga svoga, koji te izveo iz zemlje egipatske, iz kuće ropstva;');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 8, 15, 'koji te proveo kroz onu veliku i strašnu pustinju, kroz zemlju plamenih zmija i štipavaca, suhim i bezvodnim krajem; koji ti je izveo vodu iz stijene tvrde kao kremen;');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 8, 16, 'koji te u pustinji hranio manom, nepoznatom tvojim ocima, da te ponizi i da te iskuša te da na kraju budeš sretan.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 8, 17, 'Ne reci tada u svome srcu: svojom sam moći i snagom svojih ruku sebi namakao ovo bogatstvo.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 8, 18, 'Sjeti se Jahve, Boga svoga! TÓa on ti je dao snagu da stječeš bogatstvo da tako ispuni - kao što je danas - svoj Savez za koji se zakleo tvojim ocima.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 8, 19, 'Ako li zaboraviš Jahvu, Boga svoga, i pođeš za drugim bogovima te njima budeš iskazivao štovanje, njima se klanjao, kunem vam se danas da ćete zacijelo izginuti;');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 8, 20, 'poput naroda koje će Jahve pogubiti pred vama, tako će i vas nestati jer niste poslušali glasa Jahve, Boga svoga.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 9, 1, 'Slušaj, Izraele! Danas prelaziš preko Jordana da sebi podvrgneš narode i veće i brojnije nego što si ti; velike gradove, s utvrdama do nebesa;');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 9, 2, 'narod velik i gorostasan poput Anakovaca, koje već poznaješ i o kojima si slušao: \'Tko da odoli Anakovcima?\'');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 9, 3, 'Znaj dakle danas da Jahve, Bog tvoj, ide pred tobom. On je vatra što proždire; on će ih oboriti, tebi ih podvrgnuti. A ti ćeš ih onda rastjerati i ubrzo pobiti, kako ti je Jahve i rekao.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 9, 4, 'Pošto ih otjera ispred tebe Jahve, Bog tvoj, nemoj reći u srcu svome: \'Jahve me uveo da zaposjednem ovu zemlju zbog moje pravednosti.\' Naprotiv, zbog opačina onih naroda Jahve ih tjera ispred tebe.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 9, 5, 'Ne ideš ti da zaposjedneš njihovu zemlju zbog svoje pravednosti i čestitosti svoga srca, nego zato što Jahve, Bog tvoj, zbog opačine onih naroda tjera njih ispred tebe da tako održi riječ kojom se zakleo tvojim ocima: Abrahamu, Izaku i Jakovu.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 9, 6, 'Znaj, dakle, da ti Jahve, Bog tvoj, ne daje ovu dobru zemlju u posjed zbog tvoje pravednosti, jer si ti narod tvrde šije!');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 9, 7, 'Sjećaj se i ne zaboravljaj kako si u pustinji ljutio Jahvu, Boga svoga. Od dana kad ste izašli iz zemlje egipatske do dolaska na ovo mjesto, Jahvi ste se opirali.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 9, 8, 'Na Horebu ste rasrdili Jahvu i Jahve je na vas tako planuo da vas je htio uništiti.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 9, 9, 'Popeo sam se na brdo da primim kamene ploče, ploče Saveza što ga s vama sklopi Jahve. Na brdu sam ostao četrdeset dana i četrdeset noći: niti sam jeo kruha niti pio vode.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 9, 10, 'I dade mi Jahve dvije kamene ploče, ispisane prstom Božjim, na kojima bijahu sve riječi što vam ih je Jahve isred ognja na brdu rekao na dan zbora.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 9, 11, 'Kad je prošlo četrdeset dana i četrdeset noći, Jahve mi dade dvije kamene ploče - ploče Saveza.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 9, 12, 'I reče mi Jahve: \'Ustaj! Žurno siđi odavde, jer se pokvario narod tvoj koji si izveo iz Egipta. Brzo su zašli s puta koji sam im označio: već su sebi napravili livenog kumira.\'');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 9, 13, 'Još mi reče Jahve: \'Promatrao sam taj narod. Zbilja je to narod tvrde šije!');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 9, 14, 'Pusti me da ih uništim i njihovo ime izbrišem pod nebesima, a od tebe da učinim narod i jači i brojniji nego što je ovaj!\'');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 9, 15, 'Okrenuh se i siđoh niz brdo, a brdo svejednako plamtjelo u ognju. Dvije ploče Saveza bijahu mi u rukama.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 9, 16, 'Pogledah: zbilja ste sagriješili protiv Jahve, Boga svoga. Salili ste sebi tele od kovine. Tako ste brzo zašli s puta što vam ga Jahve bijaše označio.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 9, 17, 'Pograbih dvije ploče te ih bacih od sebe objema rukama - razbih ploče pred vašim očima.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 9, 18, 'Onda se ničice bacih pred Jahvu. Četrdeset dana i četrdeset noći - kao i prije - niti sam jeo kruha niti pio vode zbog svih grijeha koje ste počinili radeći zlo u očima Jahve i srdeći ga.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 9, 19, 'Jer se bojah srdžbe i gnjeva kojim je Jahve usplamtio na vas da vas zatre. Ali me i tada Jahve usliša.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 9, 20, 'I na Arona se Jahve silno rasrdio, htio ga uništiti. Tada se zauzeh i za Arona.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 9, 21, 'Vaš grijeh, tele što bijaste načinili, uzeh i sažegoh ga u vatri. U prah ga satrh i prah mu bacih u potok što teče s brda.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 9, 22, 'Kod Tabere, kod Mase i Kibrot Hataave srdili ste Jahvu.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 9, 23, 'Kad vas je Jahve slao od Kadeš Barnee govoreći: \'Idite gore i uzmite zemlju koju sam vam dao\', pobunili ste se protiv riječi Jahve, Boga svoga; u nj se niste pouzdavali niti ste slušali njegov glas.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 9, 24, 'Nepokorni bijaste Jahvi otkad vas poznajem.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 9, 25, 'Zato sam pao ničice i ležao pred Jahvom četrdeset dana i četrdeset noći, jer Jahve bijaše rekao da će vas uništiti.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 9, 26, 'Jahvu sam molio i rekao: \'Gospodine moj, Jahve! Ne uništavaj naroda svoga, baštine svoje koju si izbavio u svojoj veličajnosti i svojom moćnom rukom izveo iz Egipta.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 9, 27, 'Sjeti se slugu svojih: Abrahama, Izaka i Jakova, a ne obaziri se na tvrdokornost ovoga naroda, na njegovu opačinu, na grijeh njegov,');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 9, 28, 'da se ne rekne u zemlji iz koje si nas izbavio: Jahve ih nije mogao uvesti u zemlju koju im je obećao, ili ih je mrzio pa ih je zato odveo da ih pomori u pustinji.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 9, 29, 'A oni su tvoj narod, tvoja baština, oni koje si izveo svojom velikom moći i ispruženom mišicom.\'');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 10, 1, 'U to vrijeme Jahve mi reče: \'Iskleši dvije kamene ploče kao i prijašnje pa se popni k meni na brdo; a napravi i drveni kovčeg.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 10, 2, 'Na ploče ću napisati riječi koje su bile na prvim pločama što si ih razbio. A onda ih položi u kovčeg.\'');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 10, 3, 'Načinih kovčeg od bagremovine, isklesah dvije kamene ploče kao što bijahu prve, pa se, s dvjema pločama u ruci, popeh na brdo.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 10, 4, 'I napisa na te ploče, kao i prije, Deset riječi koje vam je Jahve rekao na brdu, isred ognja, na dan zbora. Onda ih Jahve dade meni.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 10, 5, 'Okrenuh se i siđoh s brda. Položih ploče u kovčeg koji bijah napravio. I stadoše ondje, kako mi je Jahve naredio.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 10, 6, 'Od Beerota sinova Jaakanovih odoše Izraelci u Moseru. Ondje umrije Aron i ondje bi pokopan. Svećenikom mjesto njega postade njegov sin Eleazar.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 10, 7, 'Odande odoše u Gudgodu; iz Gudgode u Jotbatu, u kraj bogat potocima.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 10, 8, 'U to vrijeme odvoji Jahve pleme Levijevo da nosi Kovčeg saveza Jahvina; da pred Jahvom stoji u njegovoj službi te da u njegovo ime blagoslivlja, kako radi i danas.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 10, 9, 'Stoga Levi nema udjela ni baštine sa svojom braćom: Jahve je njegova baština, kako mu je Jahve, Bog tvoj, i rekao.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 10, 10, 'Na brdu sam ostao, kao i prvi put, četrdeset dana i četrdeset noći. I usliša me Jahve i taj put; nije htio da te uništi,');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 10, 11, 'nego mi Jahve reče: \'Ustaj! Idi pred ovim narodom da uđu i zaposjednu zemlju za koju sam se zakleo njihovim ocima da ću im je dati.\'');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 10, 12, 'Dakle, Izraele, što od tebe traži Jahve, Bog tvoj? Samo to da se bojiš Jahve, Boga svoga; da po svim putovima njegovim hodiš; da ga ljubiš i služiš Jahvi, Bogu svome, svim srcem svojim i svom dušom svojom;');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 10, 13, 'da držiš Jahvine zapovijedi i njegove zakone što ti ih danas za tvoje dobro dajem.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 10, 14, 'Evo, Jahvi, Bogu tvome, pripada nebo i nebo nad nebesima, zemlja i sve što je na njoj.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 10, 15, 'Ali Jahvi samo vaši oci omilješe i poslije njih izabrao je vas, potomke njihove, između svih naroda, kako je i danas.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 10, 16, 'Srce svoje obrežite; šiju više ne ukrućujte!');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 10, 17, 'Jer Jahve, Bog vaš, Bog je nad bogovima, Gospodar nad gospodarima, Bog velik, jak i strašan, koji nije pristran i ne da se podmititi;');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 10, 18, 'daje pravdu siroti i udovici; ljubi pridošlicu, daje mu hranu i odjeću.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 10, 19, 'Ljubite i vi pridošlicu, jer ste i sami bili pridošlice u zemlji egipatskoj.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 10, 20, 'Boj se Jahve, Boga svojeg; njemu služi; uza nj se priljubi; njegovim imenom priseži.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 10, 21, 'On je tvoja slava, Bog tvoj, koji je radi tebe učinio velika i čudesna djela što su ih vidjele tvoje oči.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 10, 22, 'Tvojih otaca, kad su se spustili u Egipat, bješe samo sedamdeset, a sad je Jahve, Bog tvoj, učinio te vas ima kao zvijezda na nebu.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 11, 1, 'Ljubi, dakle, Jahvu, Boga svoga, i vrši u sve dane njegove naredbe, njegove zakone, uredbe i zapovijedi.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 11, 2, 'Vi, a ne vaši sinovi, koji nisu ni upoznali ni vidjeli pouke Jahve, Boga vašega, danas ste se osvjedočili o njegovoj veličajnosti, o njegovoj moćnoj ruci, ispruženoj mišici,');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 11, 3, 'o znamenjima njegovima i o djelima što ih učini usred Egipta na faraonu, kralju egipatskom, i na svoj zemlji njegovoj;');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 11, 4, 'što je učinio egipatskoj vojsci, njihovim konjima i kolima; kako ih je preplavio vodama Crvenog mora kad su vas progonili i kako ih je zatro do današnjeg dana;');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 11, 5, 'što je za vas radio u pustinji dok ne stigoste do ovoga mjesta;');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 11, 6, 'što je učinio s Datanom i Abiramom, sinovima Eliaba, Rubenova potomka, kad zemlja rastvori ralje svoje te ih proguta sred svega Izraela, njih i njihove obitelji, njihove šatore i sve što imahu.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 11, 7, 'Vaše su oči vidjele sva ta velika djela što ih je Jahve učinio.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 11, 8, 'Zato držite sve zapovijedi što vam ih danas naređujem da budete jaki te uzmete u posjed zemlju u koju idete da je osvojite;');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 11, 9, 'napokon, da dugo živite u zemlji za koju se zakleo Jahve ocima vašim da će je dati njima i njihovu potomstvu - zemlju kojom teče med i mlijeko.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 11, 10, 'Jer zemlja u koju ideš da je zaposjedneš nije kao zemlja egipatska iz koje ste izašli, gdje si, posijavši sjeme, morao svoj usjev svojom nogom natapati kao što se natapa povrtnjak.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 11, 11, 'Zemlja u koju idete da je zaposjednete zemlja je bregova i dolova i natapa je dažd nebeski;');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 11, 12, 'zemlja nad kojom Jahve, Bog tvoj, bdi; na kojoj oči Jahve, Boga tvoga, uvijek počivaju, od početka do svršetka godine.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 11, 13, 'Zato, ako doista poslušate zapovijedi koje vam danas izdajem i budete ljubili Jahvu, Boga svoga, i služili mu svim srcem svojim i svom dušom svojom,');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 11, 14, 'davat ću vašoj zemlji kišu u pravo vrijeme: u jesen i u proljeće, i moći ćeš sabirati svoje žito, svoje vino i svoje ulje;');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 11, 15, 'travu ću davati po tvome polju tvome blagu. Tako ćeš jesti i biti sit.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 11, 16, 'Pazite da se vaše srce ne zavede, da ne pođete stranputicom, da drugim bogovima ne iskazujete štovanje i da im se ne klanjate.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 11, 17, 'Jer tada bi na vas Jahve usplamtio gnjevom: nebesa bi zatvorio; kiše ne bi bilo; zemlja ne bi davala roda i vas bi brzo nestalo s te dobre zemlje koju vam Jahve daje.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 11, 18, 'Utisnite ove moje riječi u svoje srce i svoju dušu; kao znak ih privežite na svoju ruku; neka vam budu kao zapis među očima!');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 11, 19, 'Poučite u njima svoje sinove; izgovarajte ih kad sjedite u svojoj kući i kad idete putem; kad liježete i kad ustajete.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 11, 20, 'Ispišite ih na dovratnike svoje kuće i na svoja vrata');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 11, 21, 'da vaši dani i dani vaših sinova u zemlji za koju se Jahve zakleo vašim ocima da će im je dati - budu brojni kao dani nebesa nad zemljom.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 11, 22, 'Ako budete vjerno držali sve ove zapovijedi koje vam naređujem, vršili ih i ljubili Jahvu, Boga svoga, hodili svim njegovim putovima i čvrsto se priljubili uz njega,');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 11, 23, 'Jahve će ispred vas protjerati sve te narode i vi ćete s posjeda odagnati narode brojnije i jače od sebe.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 11, 24, 'Svako mjesto na koje stupi vaša noga bit će vaše; od pustinje i Libanona, od Rijeke, rijeke Eufrata, do Zapadnog mora sterat će se vaše područje.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 11, 25, 'Nitko se neće održati pred vama; strah i trepet raširit će Jahve, Bog vaš, po svoj zemlji u koju stupite, kako vam je rekao.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 11, 26, 'Gledajte! Nudim vam danas blagoslov i prokletstvo:');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 11, 27, 'blagoslov, budete li slušali zapovijedi Jahve, Boga svoga, koje vam danas dajem;');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 11, 28, 'a prokletstvo, ne budete li slušali zapovijedi Jahve, Boga svoga, nego sađete s puta koji vam danas određujem te pođete za drugim bogovima kojih niste poznavali.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 11, 29, 'Kada te Jahve, Bog tvoj, uvede u zemlju u koju ideš da je zaposjedneš, tada nad gorom Gerizimom izreci blagoslov, a prokletstvo nad gorom Ebalom.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 11, 30, 'Te se gore izdižu, kako znate, s onu stranu Jordana, za putom prema zapadu, u zemlji Kanaanaca, koji žive u Arabi, nasuprot Gilgalu, uz Hrast More.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 11, 31, 'Eto ćete prijeći preko Jordana da zaposjednete zemlju koju vam daje Jahve, Bog vaš. Zaposjednite je i nastanite se u njoj.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 11, 32, 'Ali držite i vršite sve zakone i uredbe koje vam danas izlažem.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 12, 1, 'Ovo su zakoni i uredbe što vam ih valja držati i vršiti u zemlji koju vam Jahve, Bog otaca vaših, daje u posjed za sve dane što budete živjeli na zemlji.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 12, 2, 'Sravnite sa zemljom sva mjesta na kojima su narodi koje ćete protjerati iskazivali štovanje svojim bogovima, nalazila se ona na visokim brdima, na humovima ili pod kakvim zelenim drvetom.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 12, 3, 'Porušite njihove žrtvenike, porazbijajte njihove stupove, spalite im ašere; smrvite kipove njihovih bogova, zatrite im imena s onih mjesta.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 12, 4, 'Jahvi, Bogu svome, nemojte onako iskazivati štovanje.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 12, 5, 'Jahvu, Boga svoga, tražite jedino na mjestu koje je on odabrao, sred svih vaših plemena, da ondje stavi svoje ime i da ondje prebiva;');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 12, 6, 'onamo donosite svoje paljenice i svoje klanice, svoje desetine i darove svojih ruku, svoje zavjetne i dragovoljne prinose i prvine od svoga krupnoga i sitnoga blaga.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 12, 7, 'Blagujte ondje, vi i vaše obitelji, u nazočnosti Jahve, Boga svoga; veselite se svime što su vaše ruke namaknule i što vam je Jahve, Bog vaš, blagoslovom udijelio.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 12, 8, 'Nemojte raditi čak ni kako radimo ovdje danas - svatko što se njemu čini dobro -');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 12, 9, 'jer još niste stigli u Počivalište, u baštinu koju ti daje Jahve, Bog tvoj.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 12, 10, 'Ali kad prijeđete preko Jordana i nastanite se u zemlji koju vam Jahve, Bog vaš, daje u baštinu, kad vas smiri od svih neprijatelja koji budu oko vas te budete živjeli bez straha,');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 12, 11, 'onda ćete donositi sve što vam naređujem: svoje paljenice, svoje klanice, svoje desetine, darove svojih ruku i sve svoje izabrane zavjetnice koje budete zavjetovali Jahvi - na mjesto koje Jahve, Bog vaš, odabere da ondje nastani svoje ime.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 12, 12, 'Veselite se tada pred Jahvom, Bogom svojim, vi, vaši sinovi i kćeri, vaše sluge i sluškinje i levit koji bude u vašim gradovima, jer on nema s vama udjela ni baštine.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 12, 13, 'Pazi da ne prinosiš svojih žrtava paljenica na bilo kojem mjestu što ga zamijetiš,');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 12, 14, 'nego samo na mjestu što ga odabere Jahve, u jednome od tvojih plemena. Tu prinosi svoje paljenice i tu obavljaj sve što ti naređujem.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 12, 15, 'Ali svaki put kad ti srce zaželi, možeš zaklati i jesti mesa u svim svojim gradovima, prema blagoslovu koji ti Jahve, Bog tvoj, bude davao. I nečist i čist može ga jesti, kao da je od srne ili jelena.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 12, 16, 'Ali krvi nemojte blagovati; istočite je na zemlju kao vodu.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 12, 17, 'Po svojim gradovima nemojte jesti desetine svoga žita, svoga vina, svoga ulja ni prvine svoga krupnog ili sitnog blaga; niti išta od svojih zavjetovanih i od svojih dragovoljnih prinosa, ni od prinosa svojih ruku,');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 12, 18, 'nego ćeš to blagovati pred Jahvom, Bogom svojim, u mjestu koje Jahve, Bog tvoj, odabere, ti, tvoj sin, tvoja kći, tvoj sluga, tvoja sluškinja i levit koji bude u tvojim gradovima. Proveseli se u nazočnosti Jahve, Boga svoga, svime što ti ruka namakne.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 12, 19, 'Pazi da nikad ne zaboraviš levita dok si na svojoj zemlji.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 12, 20, 'Kad ti Jahve, Bog tvoj, proširi tvoje područje, kao što ti je rekao, i ti rekneš: \'Ja bih jeo mesa\' - jer želiš jesti mesa - možeš ga jesti koliko ti duša želi.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 12, 21, 'Bude li mjesto koje Jahve, Bog tvoj, odabere da u njemu svoje ime smjesti daleko od tebe, onda možeš zaklati bilo što od svoje krupne ili sitne stoke što ti je Jahve dadne - kako sam ti već naredio - te jesti u bilo kojem svome gradu koliko ti duša želi.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 12, 22, 'Jedi ga ipak onako kako se jede srna ili jelen: neka ga jedu zajedno čisti i nečisti.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 12, 23, 'Samo, pazi da ne jedeš krvi! Ta krv je život. Ne smiješ jesti život s mesom.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 12, 24, 'Ne blaguj je; istoči je na zemlju kao vodu.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 12, 25, 'Ne smiješ je jesti, da bude dobro i tebi i tvojim sinovima poslije tebe kad činiš što je pravo u očima Jahvinim.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 12, 26, 'Ali svoje posvećene prinose i svoje zavjetne prinose uzmi i nosi na mjesto koje Jahve odabere.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 12, 27, 'Tu prinesi svoje paljenice, meso i krv, na žrtveniku Jahve, Boga svoga. Ali krv od svojih klanica istoči na žrtvenik Jahve, Boga svoga, a meso pojedi.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 12, 28, 'Drži i vrši sve ove naredbe što ti ih propisujem, da bude dobro zauvijek tebi i tvojim sinovima poslije tebe kad činiš što je dobro i pravedno u očima Jahve, Boga svoga.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 12, 29, 'A kad Jahve, Bog tvoj, istrijebi narode na koje ideš da ih otjeraš s posjeda ispred sebe i kad ih otjeraš te se u njihovoj zemlji nastaniš,');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 12, 30, 'čuvaj se da ne padneš u zamku; ne pođi za njima pošto budu uništeni ispred tebe. Ne istražuj o njihovim bogovima i ne govori: \'Kako su oni narodi štovali svoje bogove, tako ću i ja.\'');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 12, 31, 'Nemoj onako postupati prema Jahvi, Bogu svome. TÓa Jahvi je zazorno i mrsko sve što su oni činili svojim bogovima. Čak su svoje sinove i kćeri spaljivali u čast svojim bogovima.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 13, 1, 'Sve što vam naređujem držite; tomu ništa ne domeći i ništa ne oduzimaj.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 13, 2, 'Ako se u tvojoj sredini pojavi kakav prorok ili čovjek sa snoviđenjima pa ti iznese kakvo znamenje ili čudo;');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 13, 3, 'i to se znamenje ili čudo o kojem ti je govorio ispuni i onda ti on rekne: \'Pođimo sad za drugim bogovima kojih dosad ne poznaješ i njima iskazujmo štovanje\',');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 13, 4, 'nemoj slušati riječi toga proroka ni sne toga sanjača: tÓa to vas iskušava Jahve, Bog vaš; hoće da dozna ljubite li zbilja Jahvu, Boga svoga, svim srcem svojim i svom dušom svojom.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 13, 5, 'Idite samo za Jahvom, Bogom svojim; njega se bojte; njegove zapovijedi vršite; njegov glas slušajte; njemu štovanje iskazujte; uz njega se priljubite.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 13, 6, 'A onaj prorok ili sanjač neka se pogubi jer je poticao na otpad od Jahve, Boga vašega, koji vas je izveo iz zemlje egipatske i otkupio vas iz kuće ropstva. Onaj te htio zavesti s puta kojim ti je Jahve, Bog tvoj, naredio da ideš. Tako treba da iskorijeniš zlo iz svoje sredine.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 13, 7, 'Kad bi te brat tvoj, sin majke tvoje, ili sin tvoj vlastiti, kći tvoja, žena u tvom naručju ili prijatelj tvoj koji ti je kao i život, potajno zavodio govoreći: \'Hajde da iskazujemo štovanje drugim bogovima\', kojih ne poznaješ ni ti niti su ih poznavali tvoji oci,');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 13, 8, 'bogovima onih naroda što oko vas budu, bilo tebi blizu bilo od tebe daleko, od jednoga kraja zemlje do drugoga -');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 13, 9, 'nemoj pristati niti ga slušaj! Neka ga tvoje oko ne sažaljuje; ne štedi ga i ne sakrivaj ga');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 13, 10, 'nego ga ubij! Neka se najprije tvoja ruka digne na nj da ga usmrtiš, a onda ruka svega naroda.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 13, 11, 'Zaspi ga kamenjem dok ne umre, jer je kušao da te odvrati od Jahve, Boga tvoga, koji te izvede iz zemlje egipatske, iz kuće ropstva.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 13, 12, 'Sav će se Izrael, kad to čuje, napuniti strahom te više neće počinjati takva zla u tvojoj sredini.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 13, 13, 'Ako u kojem tvome gradu što ti ga Jahve, Bog tvoj, dadne da se u njemu nastaniš, čuješ gdje govore:');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 13, 14, '\'Pojavile se ništarije iz tvoje sredine i zavedoše žitelje svoga grada kazujući: Hajde da služimo drugim bogovima! - kojih vi inače ne poznajete -');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 13, 15, 'tada dobro istraži, raspitaj se i temeljito izvidi. Bude li istina i doista se ta grozota učinila u tvojoj sredini,');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 13, 16, 'onda posijeci oštrim mačem stanovništvo toga grada, izvrši nad njim kleto uništenje i nad svime što bude u njemu.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 13, 17, 'Snesi onda sav plijen nasred trga te spali grad sa svim plijenom kao paljenicu Jahvi, Bogu svome. Neka zauvijek ostane ruševina i neka se više nikada ne sazida.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 13, 18, 'Od onoga što je bilo prokletstvom udareno neka ništa ne prione za tvoju ruku, da Jahve odustane od žestine svoga gnjeva; da ti iskaže milosrđe, smiluje ti se i razmnoži te, kako se zakleo tvojim ocima');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 13, 19, 'ako ti budeš slušao glas Jahve, Boga svoga, držeći sve njegove zapovijedi koje ti danas naređujem i vršeći što je pravo u očima Jahve, Boga tvoga.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 14, 1, 'Vi ste sinovi Jahve, Boga svoga. Nemojte na sebi praviti ureza ni podstriga na čelu za pokojnikom.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 14, 2, 'TÓa ti si narod posvećen Jahvi, Bogu svome; Jahve je odabrao tebe između svih naroda na zemlji da budeš njegov narod, njegova predraga svojina.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 14, 3, 'Ništa odvratno nemojte jesti.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 14, 4, 'Ovo su životinje koje možete jesti: vol, ovca, koza,');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 14, 5, 'jelen, srna, srndać, kozorog, antilopa, bivol i divokoza;');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 14, 6, 'možete jesti svaku životinju koja ima razdvojene papke - nadvoje posve razdvojene - i koja preživa.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 14, 7, 'Samo od preživača ili od životinja s razdvojenim čaporcima ne možete jesti ove: devu, arnebeta i svisca. Te, naime, iako preživaju, nemaju razdvojenih papaka; neka su za vas nečiste.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 14, 8, 'A svinja, premda ima papke razdvojene, ne preživa: neka je za vas nečista. Njezina mesa nemojte jesti niti se njezina strva doticati.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 14, 9, 'A od svega što u vodi živi ovo možete jesti: što god ima ljuske i peraje, možete jesti.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 14, 10, 'A što nema ljusaka i peraja, ne smijete jesti. To neka je za vas nečisto.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 14, 11, 'Svaku čistu pticu možete jesti.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 14, 12, 'Ali ovih ne smijete jesti: orla strvinara i jastreba,');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 14, 13, 'tetrijeba, sokola bilo koje vrste;');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 14, 14, 'gavrana bilo koje vrste;');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 14, 15, 'noja, kopca, galeba ni kraguja bilo koje vrste;');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 14, 16, 'sove, jejine i labuda;');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 14, 17, 'pelikana, bijelog strvinara i gnjurca;');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 14, 18, 'rode, čaplje bilo koje vrste; pupavca i šišmiša.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 14, 19, 'Svi krilati kukci neka su za vas nečisti - ne smijete ih jesti.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 14, 20, 'Sve krilato čisto možete jesti.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 14, 21, 'Ne smijete jesti ništa što crkne. Daj to pridošlici koji boravi u tvojim gradovima neka jede ili pak prodaj tuđincu. Jer ti si narod posvećen Jahvi, Bogu svome. Ne kuhaj kozleta u mlijeku njegove majke!');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 14, 22, 'Odvajaj desetinu dohotka svake godine od svega što tvoj usjev u polju donese.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 14, 23, 'A onda blaguj desetine svoga žita, svoga vina, svoga ulja i prvine svoje krupne i sitne stoke u nazočnosti Jahve, Boga svoga, na mjestu koje on odabere da svoje ime ondje nastani; da se tako naučiš zauvijek bojati se Jahve, Boga svoga.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 14, 24, 'Bude li ti put predug te ne mogneš donijeti desetine - jer je mjesto što ga Jahve odabere da u njemu nastani svoje ime previše daleko od tebe - tada, kad te Jahve, Bog tvoj, blagoslovi,');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 14, 25, 'prodaj to za novac, uzmi novac u ruku pa idi u mjesto što ga odabere Jahve, Bog tvoj.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 14, 26, 'Ondje za novac kupi što želiš: goveče, sitno živinče, vino ili opojno piće - što god ti duša zaželi. Ondje u nazočnosti Jahve, Boga svoga, blaguj i veseli se ti i tvoji ukućani.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 14, 27, 'Ne zanemaruj levita koji bude u tvojim gradovima, jer on nema udjela ni baštine s tobom.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 14, 28, 'Na kraju svake treće godine iznesi svu desetinu svoga prihoda od te godine i položi je na svoja vrata.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 14, 29, 'Pa neka dođe levit - jer nema udjela ni baštine s tobom - došljak, sirota i udovica koji budu živjeli u tvom gradu i neka jedu i neka se nasite. Tako će te blagoslivljati Jahve, Bog tvoj, u svim poslovima što ih tvoja ruka poduzme.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 15, 1, 'Na završetku sedme godine opraštaj dugove.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 15, 2, 'Ovako neka bude opraštanje: neka svatko oprosti dužniku svoje potraživanje; neka ne utjeruje duga od svoga bližnjega ni od svoga brata kad se jednom proglasi Jahvino otpuštanje dugova.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 15, 3, 'Možeš tražiti od tuđina, ali ono što se tvoga nađe kod tvoga brata treba da otpustiš,');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 15, 4, 'da ne bude siromaha kod tebe. TÓa Jahve će te obilno blagoslivljati u zemlji koju ti Jahve, Bog tvoj, daje u baštinu da je zaposjedneš,');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 15, 5, 'samo ako budeš dobro slušao glas Jahve, Boga svoga, držeći i vršeći sve ove zapovijedi što ti ih danas naređujem.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 15, 6, 'Jahve, Bog tvoj, blagoslivljat će te kako ti je obećao te ćeš moći zajmove davati mnogim narodima, a sam ih nećeš morati uzimati; i nad mnogim ćeš narodima vladati, dok oni nad tobom neće gospodariti.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 15, 7, 'Nađe li se kod tebe kakav siromah, netko od tvoje braće u kojem god gradu u zemlji što ti je Jahve, Bog tvoj, dadne, ne budi tvrda srca niti zatvaraj svoje ruke prema svome siromašnome bratu,');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 15, 8, 'nego mu širom rastvori svoju ruku i spremno mu daj što mu nedostaje.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 15, 9, 'Čuvaj se da ti se u srcu ne porodi opaka misao te rekneš: \'Sedma se godina, godina otpuštanja dugova, već približuje\' - i da prijekim okom pogledaš svoga siromašnog brata i ništa mu ne dadneš. On bi zazvao Jahvu protiv tebe i grijeh bi bio na tebi.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 15, 10, 'Daj mu rado, a ne da ti srce bude zlovoljno kad mu daješ, jer će te zbog toga blagoslivljati Jahve, Bog tvoj, u svakom poslu tvome i u svakom pothvatu ruku tvojih.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 15, 11, 'Kako siromaha nikad neće nestati iz zemlje, zapovijedam ti: širom otvaraj svoju ruku svome bratu, svome siromahu i potrebitu u zemlji svojoj.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 15, 12, 'Ako se tebi proda brat tvoj - Hebrejac ili Hebrejka - neka ti služi šest godina, a sedme ga godine otpusti od sebe slobodna.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 15, 13, 'Kad ga slobodna od sebe otpustiš, ne šalji ga praznih ruku.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 15, 14, 'Daruj ga čime između stoke svoje, s gumna svoga i iz badnja svoga; čime te već Jahve, Bog tvoj, blagoslovio, od toga i njemu daj.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 15, 15, 'Sjećaj se kako si bio rob u zemlji egipatskoj i kako te Jahve, Bog tvoj, otkupio. Zato ti ovo zapovijedam danas.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 15, 16, 'Ali ako ti on kaže: \'Neću da odlazim od tebe\', jer voli tebe i dom tvoj i jer mu je kod tebe bilo dobro -');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 15, 17, 'uzmi tada šilo i probuši mu uho na vratima, i neka ti bude robom zauvijek! Tako isto učini i sa svojom sluškinjom.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 15, 18, 'Kad ga budeš otpuštao od sebe slobodna, neka ti ne bude teško, jer je zavrijedio dvostruku najamničku plaću za šest godina što ti je služio. Zato će te Jahve, Bog tvoj, blagosloviti u svemu što budeš radio.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 15, 19, 'Sve muške prvine što ih omladi tvoja krupna i sitna stoka posveti Jahvi, Bogu svome! Stoga vola prvenca nemoj uprezati niti strići prvenca od svoje sitne stoke.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 15, 20, 'Blaguj ga ti i tvoj dom svake godine u nazočnosti Jahve, Boga svoga, u mjestu što ga odabere Jahve.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 15, 21, 'Ali ako bi imali kakvu manu, ako bi bili hromi ili slijepi ili imali kakvu god ružnu manu, nemoj ih žrtvovati Jahvi, Bogu svomu!');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 15, 22, 'Pojedi ih u svojoj kući. I nečist i čist mogu ih jesti, kao srnu i jelena.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 15, 23, 'Jedino krvi njihove ne smiješ jesti! Istoči je na zemlju kao vodu.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 16, 1, 'Drži mjesec Abib i slavi Pashu u čast Jahvi, Bogu svome, jer te Jahve, Bog tvoj, u mjesecu Abibu izveo noću iz Egipta.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 16, 2, 'Kao pashu u čast Jahvi, Bogu svome, žrtvuj ovce i goveda u mjestu koje Jahve odabere da u njemu nastani ime svoje.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 16, 3, 'Ništa ukvasano nemoj s njome jesti; nego sedam dana jedi beskvasan kruh - kruh nevoljnički - budući da si u žurbi izišao iz zemlje egipatske: da se svega svog vijeka sjećaš dana kad si izišao iz zemlje egipatske.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 16, 4, 'Neka se sedam dana u tebe ne vidi kvasac na svemu tvome području i ništa od mesa žrtve što je zakolješ navečer prvoga dana ne smije ostati preko noći do jutra.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 16, 5, 'Nije ti dopušteno žrtvovati pashu u bilo kojem gradu što ti ga dadne Jahve, Bog tvoj,');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 16, 6, 'nego u mjestu koje odabere Jahve, Bog tvoj, da ondje nastani ime svoje; samo tu žrtvuj pashu u predvečerje, o zalasku sunca, jer u to si vrijeme izišao iz Egipta.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 16, 7, 'Skuhaj je i pojedi na mjestu koje odabere Jahve, Bog tvoj. Ujutro se onda okreni i zaputi svojim šatorima.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 16, 8, 'Šest dana jedi beskvasan kruh, a sedmoga dana neka bude svečani zbor u čast Jahvi, Bogu tvome. Posla nikakva ne radi!');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 16, 9, 'Nabroj sedam tjedana; a tih sedam tjedana uzmi brojiti kad srp počne žeti klasje.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 16, 10, 'Tada drži Blagdan sedmica u čast Jahvi, Bogu svome, prinoseći dragovoljni prinos iz svoje ruke, kako te već Jahve, Bog tvoj, bude blagoslovio.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 16, 11, 'I proveseli se tada u nazočnosti Jahve, Boga svoga - na mjestu što ga Jahve, Bog tvoj, odabere da ondje nastani ime svoje - ti, sin tvoj i kći tvoja, sluga tvoj i sluškinja tvoja, levit koji bude u tvome gradu, došljak, sirota i udovica što budu kod tebe.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 16, 12, 'Sjećaj se da si i sam bio rob u Egiptu. Zato drži i vrši ove uredbe.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 16, 13, 'Blagdan sjenica slavi sedam dana pošto pokupiš plodove sa svoga gumna i iz svoga badnja.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 16, 14, 'Proveseli se na svoj blagdan ti, sin tvoj, kći tvoja, sluga tvoj, sluškinja tvoja, levit i došljak, sirota i udovica što se nađe u tvome gradu.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 16, 15, 'Svetkuj u čast Jahvi, Bogu svome, sedam dana na mjestu koje odabere Jahve, jer će te Jahve, Bog tvoj, blagoslovom obasipati u svim tvojim žetvama, u svakom poslu ruku tvojih, da budeš potpuno veseo.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 16, 16, 'Triput u godini neka se pokažu svi tvoji muškarci pred Jahvom, Bogom tvojim, na mjestu koje on odabere: na Blagdan beskvasnog kruha, na Blagdan sedmica i na Blagdan sjenica. Ali neka nitko ne dođe pred Jahvu praznih ruku,');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 16, 17, 'nego neka svatko prinese što može, prema blagoslovu koji ti je udijelio Jahve, Bog tvoj.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 16, 18, 'U svakom gradu koji ti dade Jahve, Bog tvoj, postavi suce i nadglednike za svoja plemena da narodom pravedno upravljaju.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 16, 19, 'Ne iskrivljuj pravde; ne budi pristran; ne primaj mita, jer mito zasljepljuje oči mudrih, a ugrožava stvar pravednih.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 16, 20, 'Teži za samom pravdom, da dugo živiš i zaposjedneš zemlju koju ti Jahve, Bog tvoj, daje.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 16, 21, 'Ne postavljaj ašere ni od kakva drveta oko žrtvenika Jahve, Boga svoga, koji podigneš;');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 16, 22, 'i ne podiži stupova, jer su na zazor Jahvi, Bogu tvome.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 17, 1, 'Ne žrtvuj Jahvi, Bogu svome, ni vola ni ovna koji bi na sebi imao manu ili kakvo zlo, jer bi to bilo ružno pred Jahvom, Bogom tvojim.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 17, 2, 'Ako se u tvojoj sredini - u bilo kojem tvojem gradu što ti ga dade Jahve, Bog tvoj - nađe čovjek ili žena da učini što je zlo u očima Jahve, Boga tvoga, i krši njegov Savez:');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 17, 3, 'otišavši da iskazuje štovanje drugim bogovima te se pokloni njima, suncu, mjesecu ili bilo čemu od nebeske vojske, a što sam ja zabranio,');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 17, 4, 'i tebi se to javi i ti to čuješ, onda pomno istraži; i bude li istina i doista se ta grozota učinila u Izraelu,');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 17, 5, 'onda toga čovjeka ili tu ženu koji učiniše takvu opačinu izvedi na gradska vrata te ih kamenuj da poginu.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 17, 6, 'Na smrt osuđeni neka se pogubi na iskaz dvojice ili trojice svjedoka. Na riječ jednoga svjedoka ne smije se pogubiti.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 17, 7, 'Neka najprije svjedoci dignu ruku na nj da ga smaknu, a poslije toga neka je digne sav narod. Tako ćeš iskorijeniti zlo iz svoje sredine.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 17, 8, 'Bude li ti preteško štogod rasuditi: ubojstvo, sukob o pravima, kakvu ozljedu ili svađu u tvome gradu, tada ustani i pođi u mjesto što ga odabere Jahve, Bog tvoj.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 17, 9, 'Obrati se svećenicima, levitima i sucu koji bude za ono vrijeme. Njih pitaj, oni će ti rasuditi.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 17, 10, 'I učini onako kako ti budu kazali u mjestu koje Jahve odabere. Pazi: sve učini kako te upute.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 17, 11, 'Uradi prema uputi koju ti dadnu i prema presudi koju donesu. Od presude koju ti kažu ne odstupaj ni desno ni lijevo.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 17, 12, 'Ako bi se tko drsko odupro i ne bi poslušao ni svećenika koji ondje stoji da služi Jahvi, Bogu tvome, ni suca, neka se taj čovjek pogubi. Tako ćeš iskorijeniti zlo iz Izraela,');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 17, 13, 'a sav će se narod, kad sazna, bojati i više se neće drsko odupirati.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 17, 14, 'Kad stigneš u zemlju koju ti Jahve, Bog tvoj, daje; kad je zaposjedneš i u njoj se nastaniš, pa onda kažeš: \'Želim da nad sobom postavim kralja, kako ga imaju svi drugi narodi oko mene\' -');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 17, 15, 'tada ćeš onoga koga Jahve, Bog tvoj, odabere, sebi postaviti za kralja. Nekoga od svoje braće postavi sebi za kralja, a ne smiješ postavljati nad sobom tuđina koji ti nije brat.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 17, 16, 'Samo neka ne drži mnogo konja i ne šalje naroda u Egipat da poveća broj konja. Jer vam je Jahve rekao: \'Ovim se putem nikada više ne vraćajte!\'');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 17, 17, 'I neka nema mnogo žena da mu srce ne pođe stranputicom; i neka sebi ne gomila srebra ni zlata!');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 17, 18, 'A kad sjedne na kraljevsko prijestolje, neka sebi na svitak prepiše ovaj Zakon od svećenika Levijevaca.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 17, 19, 'Neka ga drži uza se; neka ga čita sve vrijeme svoga života da nauči bojati se Jahve, Boga svoga, držati sve riječi ovoga Zakona i vršiti ove odredbe;');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 17, 20, 'da se svojim srcem ne uzdigne iznad svoje braće i da ne skrene od ove zapovijedi ni desno ni lijevo, kako bi dugo kraljevao, on i sinovi njegovi, u Izraelu.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 18, 1, 'Svećenici Levijevci - sve pleme Levijevo - neka nemaju udjela ni baštine s Izraelom; neka žive od žrtava paljenih Jahvi i od njegove baštine.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 18, 2, 'Neka, dakle, nemaju baštine među svojom braćom: Jahve je njihova baština, kako im je i rekao.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 18, 3, 'Ovo neka bude svećenička pristojba od naroda - od onih koji žrtve prinose, bilo to goveče ili što od sitne stoke: svećeniku treba dati pleće, vilice i želudac.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 18, 4, 'Davaj mu i prvine od svoga žita, od svoga vina, od svoga ulja i prvine od vune svojih ovaca,');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 18, 5, 'jer je njega odabrao Jahve, Bog tvoj, od svih tvojih plemena; njega i njegove sinove, da zauvijek stoje pred Jahvom, Bogom tvojim, te da obavljaju službu i blagoslivljaju u ime Jahve.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 18, 6, 'Ako bi koji levit što boravi u nekom tvome gradu, bilo gdje u Izraelu, svom dušom zaželio da dođe u mjesto što ga Jahve odabere,');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 18, 7, 'može tu službovati u ime Jahve, Boga svoga, kao i druga njegova braća Levijevci koji stoje ondje pred Jahvom.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 18, 8, 'Neka jede jednak dio kao i drugi, bez obzira na prodanu očevinu.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 18, 9, 'Kad uđeš u zemlju koju ti daje Jahve, Bog tvoj, nemoj se priučavati na odvratne čine onih naroda.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 18, 10, 'Neka se kod tebe ne nađe nitko tko bi kroz oganj gonio svoga sina ili svoju kćer; tko bi se bavio gatanjem, čaranjem, vračanjem i čarobnjaštvom;');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 18, 11, 'nitko tko bi bajao, zazivao duhove i duše predaka ili se obraćao na pokojnike.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 18, 12, 'Jer tko god takvo što čini gadi se Jahvi; zbog takvih odvratnosti njih i goni ispred tebe Jahve, Bog tvoj.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 18, 13, 'Budi posve vjeran Jahvi, Bogu svome.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 18, 14, 'Narodi koje ćeš naskoro otjerati s posjeda slušaju vračare i gatare, ali tebi to Jahve, Bog tvoj, ne dopušta.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 18, 15, 'Proroka kao što sam ja, iz tvoje sredine, od tvoje braće, podignut će ti Jahve, Bog tvoj: njega slušajte!');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 18, 16, 'Posve onako kako si i tražio od Jahve, Boga svoga, na Horebu, na dan zbora, kada si govorio: \'Neću više da slušam glas Jahve, Boga svoga, niti želim više gledati taj silni oganj da ne poginem!\'');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 18, 17, 'Nato mi reče Jahve: \'Pravo su rekli.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 18, 18, 'Podignut ću im proroka između njihove braće, kao što si ti. Stavit ću svoje riječi u njegova usta da im kaže sve što mu zapovjedim.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 18, 19, 'A ne bude li tko poslušao mojih riječi što ih prorok bude govorio u moje ime, taj će odgovarati preda mnom.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 18, 20, 'A prorok koji bi se usuđivao govoriti što u moje ime što ja ne budem zapovjedio da govori i koji bi govorio u ime drugih bogova, takav prorok neka se pogubi.\'');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 18, 21, 'Možda ćeš reći u svome srcu: \'Kako ćemo raspoznati riječ koju Jahve nije izrekao?\'');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 18, 22, 'Kad prorok govori u ime Jahve pa to ne bude i riječ se ne ispuni, onda je to riječ koje Jahve nije kazao. U drskosti je taj prorok govorio. Nemoj od njega strahovati.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 19, 1, 'Kad Jahve, Bog tvoj, istrijebi narode čiju zemlju tebi daje te kad ih istjeraš i nastaniš se u njihovim gradovima i domovima,');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 19, 2, 'u zemlji koju ti Jahve, Bog tvoj, daje u baštinu, odvoji tri grada.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 19, 3, 'Načini put onamo, a onda područje zemlje koju ti Jahve, Bog tvoj, daje u baštinu podijeli natroje, tako da svaki ubojica može onamo uteći.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 19, 4, 'Ovo je slučaj u kojemu ubojica može onamo pobjeći i spasiti svoj život: kad tko ubije svoga bližnjega nehotice, a da ga prije nije mrzio;');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 19, 5, 'primjerice, kad ode sa svojim bližnjim u šumu da siječe drva, zamahne sjekirom u ruci da obori drvo, gvožđe odleti s držalice i pogodi njegova druga te on pogine: takav ubojica neka uteče u jedan od tih gradova i spasit će život.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 19, 6, 'Inače bi krvni osvetnik, progoneći u svom bijesu ubojicu - kad bi put bio predug - mogao gonjenoga stići i pogubiti ga, iako taj nije zaslužio smrt budući da ubijenoga nije otprije mrzio.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 19, 7, 'Stoga ti nalažem: tri grada odvoji!');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 19, 8, 'A kad Jahve, Bog tvoj, proširi tvoje područje, kao što se zakleo ocima tvojim, i dadne ti svu zemlju koju je obećao tvojim ocima,');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 19, 9, 'budeš li držao i vršio sve ove zapovijedi što ti ih danas nalažem i ljubio Jahvu, Boga svoga, te hodio njegovim putovima sve vrijeme - onda ovim gradovima dodaj još tri grada:');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 19, 10, 'tako se neće prolijevati nedužna krv u tvojoj zemlji koju ti Jahve daje u baštinu i nećeš se krvlju okaljati.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 19, 11, 'Ali ako tko mrzi svoga bližnjega i vreba ga, skoči na nj i ubije ga, a zatim pobjegne u jedan od tih gradova,');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 19, 12, 'onda neka starješine onoga grada izvedu ubojicu i predaju ga u ruke krvnom osvetniku da ga pogubi.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 19, 13, 'Neka ga oko tvoje ne sažaljuje! Tako ćeš u Izraelu iskorijeniti prolijevanje nedužne krvi i bit ćeš sretan.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 19, 14, 'Nemoj pomicati susjedova međaša kojim su stari razmeđašili tvoj posjed što ćeš ga naslijediti u zemlji koju ti Jahve, Bog tvoj, daje u baštinu.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 19, 15, 'Neka ne ustaje jedan jedini svjedok protiv čovjeka ni za koju krivnju i ni za kakav zločin. Kakav god bio prekršaj, neka presuda počiva na iskazu dvojice ili trojice svjedoka.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 19, 16, 'Ako kakav krivi svjedok ustane protiv koga optužujući ga za pobunu,');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 19, 17, 'onda obojica koja se parbe neka stupe pred Jahvu, pred svećenika i suce koji budu vršili službu u to vrijeme.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 19, 18, 'Neka suci provedu temeljitu istragu. Bude li se pokazalo da je svjedok lažan i da je lažno svjedočio protiv svoga brata,');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 19, 19, 'učinite mu onako kako je on kanio svome bratu. Iskorijeni zlo iz svoje sredine!');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 19, 20, 'Drugi će, kad o tome čuju, pobojati se te više neće činiti takva zla u tvojoj sredini.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 19, 21, 'Neka ti se oko ne sažaljuje! Život za život; oko za oko; zub za zub; ruka za ruku; noga za nogu.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 20, 1, 'Ako pođeš u rat na svoje neprijatelje te vidiš konje, kola i narod brojniji od sebe, ne boj ih se! TÓa s tobom je Jahve, Bog tvoj, koji te izveo iz zemlje egipatske.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 20, 2, 'Prije boja neka svećenik istupi i govori narodu.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 20, 3, 'Neka im kaže: \'Čuj, Izraele! Danas polazite u boj na neprijatelje svoje. Neka vam srca ne klonu! Ne plašite se! Ne bojte se! Ne dršćite pred njima!');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 20, 4, 'TÓa Jahve, Bog vaš, ide s vama da se bori za vas protiv vaših neprijatelja i da vas spasi.\'');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 20, 5, 'Potom neka narodu progovore nadglednici: \'Ima li koga da je sagradio novu kuću a nije se u nju uselio? Neka se vrati kući svojoj da ne pogine u boju pa da se tko drugi u nju ne useli.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 20, 6, 'Ima li koga da je zasadio vinograd a još ga nije brao? Neka se vrati domu svome da u boju ne pogine te da mu drugi roda ne obere.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 20, 7, 'Ima li koga da se zaručio a nije se oženio? Neka se vrati domu svome da u boju ne pogine te da mu tko drugi zaručnice ne odvede.\'');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 20, 8, 'Neka nadglednici nastave te narodu kažu: \'Tko se boji i kome srce trne, neka se vrati domu svome da ne trne srce njegovoj braći kao njemu.\'');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 20, 9, 'Kad nadglednici završe govor narodu, neka vojni zapovjednici stanu na čelo naroda.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 20, 10, 'Kada dođeš pod koji grad da na nj navališ, najprije mu ponudi mir.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 20, 11, 'Ako ti odgovori mirom i otvori ti vrata svoja, sav narod što se nađe u njemu podvrgni tlaki neka za te radi.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 20, 12, 'Ali ako odbije tvoj mir i zarati s tobom, opsjedni ga.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 20, 13, 'Kad ti ga Jahve, Bog tvoj, preda u ruke, sve njegove muškarce pobij oštrim mačem!');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 20, 14, 'A žene, djecu, stoku, sve što bude u gradu - sav plijen - uzmi sebi i uživaj plijen od svojih neprijatelja što ti ga daje Jahve, Bog tvoj.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 20, 15, 'Tako čini sa svim gradovima koji budu vrlo daleko od tebe, koji ne budu gradovi ovih naroda odavde.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 20, 16, 'U gradovima onih naroda koje ti Jahve, Bog tvoj, preda u baštinu ništa ne ostavljaj na životu');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 20, 17, 'nego ih udari \'heremom\' - kletim uništenjem: Hetite i Amorejce, Kanaance i Perižane, Hivijce i Jebusejce, kako ti je Jahve, Bog tvoj, naredio,');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 20, 18, 'tako da vas ne nauče činiti sve one odvratnosti što ih čine svojim bogovima te da ne sagriješite protiv Jahve, Boga svoga.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 20, 19, 'Kad navališ na kakav grad pa ga moradneš dugo opsjedati da ga osvojiš, nemoj uništavati njegovih stabala zasijecajući u njih sjekirom. Možeš im jesti plod, a nemoj ih sjeći. Jer poljska stabla nisu ljudi da bi ispred tebe mogla bježati u utvrdu.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 20, 20, 'Jedino stabla za koja znaš da nisu voćke možeš ništiti; njih možeš sjeći i od njih praviti naprave za opsadu grada koji je u ratu protiv tebe dok ne padne.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 21, 1, 'Ako se u zemlji koju ti Jahve, Bog tvoj, daje da je zaposjedneš nađe tko ubijen gdje u polju leži - a ne zna se tko ga je ubio -');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 21, 2, 'onda neka odu tvoje starješine i suci te izmjere udaljenost od ubijenoga do okolnih gradova.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 21, 3, 'Tako će ustanoviti koji je grad najbliže ubijenom. Starješine toga grada neka tada uzmu junicu što još nije radila: što još pod jarmom nije vukla.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 21, 4, 'Neka zatim starješine onoga grada stjeraju junicu u kakav nepresušni potok, na mjesto koje se ne obrađuje i ne zasijava, i ondje, na potoku, neka junicu zakolju.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 21, 5, 'Zatim neka dođu svećenici, potomci Levijevi. Jer njih je odabrao Jahve, Bog tvoj, da mu služe i da u ime Jahvino blagoslivljaju; na njihovu se riječ rješava svaki spor i svako nasilje.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 21, 6, 'Zatim sve starješine iz onoga grada koji bude najbliži ubijenome neka operu ruke u potoku nad zaklanom junicom.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 21, 7, 'Potom neka izjave: \'Naše ruke nisu prolile ove krvi niti smo svojim očima išta vidjeli.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 21, 8, 'Zakrili, Jahve, svoj narod Izrael koji si oslobodio; ne dopusti da se prolijeva nedužna krv u tvome izraelskom narodu!\' Tako će biti zaštićeni od krvi.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 21, 9, 'A ti ćeš ukloniti prolijevanje nedužne krvi iz svoje sredine ako učiniš što je pravo u Jahvinim očima.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 21, 10, 'Kad odeš u rat na svoje neprijatelje pa ih Jahve, Bog tvoj, preda u ruke tvoje te ih zarobiš,');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 21, 11, 'ako među zarobljenicima opaziš lijepu ženu i u nju se zagledaš, možeš je uzeti za ženu.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 21, 12, 'Dovedi je svojoj kući pa neka obrije glavu, obreže nokte');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 21, 13, 'i odbaci haljine u kojima je zarobljena. Neka provede mjesec dana u tvome domu oplakujući svoga oca i svoju majku. Poslije toga možeš joj pristupiti kao muž i neka ti postane ženom.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 21, 14, 'Ako ti poslije ne bi bila po volji, pusti je kuda joj drago. Za novac je ne smiješ prodati niti s njom postupiti kao s ropkinjom jer ti je bila žena.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 21, 15, 'Ako koji čovjek imadne dvije žene: jednu koja mu je draga, a drugu koja mu je mrska, te mu i draga i mrska rode sinove, ali prvorođenac bude od one koja mu je mrska,');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 21, 16, 'onda, kad dođe dan da podijeli svoju imovinu među svoje sinove, ne smije postupiti prema prvorođencu od drage na štetu sina od mrske, koji je prvenac,');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 21, 17, 'nego mora za prvorođenca priznati sina od mrske i njemu dati dvostruk dio od svega što ima. Jer on je prvina njegove snage - njemu pripada pravo prvorodstva.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 21, 18, 'Ako tko imadne opaka i nepokorna sina koji neće da sluša ni oca ni majke - pa ni onda pošto ga kazne -');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 21, 19, 'neka ga njegov otac i njegova mati odvedu starješinama svoga grada, na vrata svoga mjesta,');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 21, 20, 'i neka kažu gradskim starješinama: \'Ovaj naš sin opak je i nepokoran; neće da nas sluša; ništarija je i pijanica.\'');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 21, 21, 'Potom neka ga svi ljudi, njegovi sugrađani, kamenjem zasiplju dok ne pogine. Tako ćeš iskorijeniti zlo iz svoje sredine: sav će Izrael to čuti i bojat će se.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 21, 22, 'Ako tko učini grijeh koji zaslužuje smrt te bude pogubljen vješanjem o stablo,');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 21, 23, 'njegovo mrtvo tijelo neka ne ostane na stablu preko noći nego ga pokopaj istoga dana, jer je obješeni prokletstvo Božje. Tako nećeš okaljati svoje zemlje, koju ti Jahve, Bog tvoj, daje u baštinu.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 22, 1, 'Kad vidiš kako luta vol ili ovca tvoga brata, nemoj proći mimo njih nego ih otjeraj svome bratu.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 22, 2, 'Ako ti brat nije blizu ili ga ne znaš, kući ih svojoj dotjeraj pa neka ostanu kod tebe dokle brat tvoj ne dođe po njih. Tada mu ih vrati.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 22, 3, 'Tako čini s njegovim magarcem, s njegovim ogrtačem i sa svime što brat tvoj izgubi, a ti nađeš. Nije ti dopušteno prolaziti mimo njegovo.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 22, 4, 'Kad opaziš kako se magarac tvoga brata ili njegov vol svalio na putu, ne kloni se nego mu pomozi da ih podigne.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 22, 5, 'Žena ne smije na se stavljati muške odjeće, a muškarac se ne smije oblačiti u ženske haljine. Tko bi to činio bio bi odvratan Jahvi, Bogu svome.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 22, 6, 'Ako putem naiđeš na ptičje gnijezdo sa ptićima ili s jajima, na stablu ili na zemlji, a majka bude ležala sa ptićima ili na jajima, nemoj uzimati majke sa ptićima:');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 22, 7, 'pusti majku na slobodu, a ptiće uzmi. Tako ćeš imati sreću i dug život.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 22, 8, 'Kad gradiš novu kuću, na krovu načini ogradu da svoju kuću, kad bi tko s nje pao, ne okaljaš krvlju.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 22, 9, 'Po svome vinogradu nemoj sijati drugog usjeva da ne bi bila posvećena čitava ljetina: i plod sjemena i rod vinograda.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 22, 10, 'Ne upreži u plug vola i magarca zajedno.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 22, 11, 'Ne oblači se u tkaninu otkanu od vune i lana zajedno.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 22, 12, 'Na četiri roglja ogrtača kojim se zaogrćeš napravi rese.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 22, 13, 'Ako koji čovjek uzme ženu i uđe k njoj, ali je potom zamrzi,');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 22, 14, 'pripiše joj ružnoće i ozloglasi je govoreći: \'Oženih se njome, ali kad joj priđoh, ne nađoh u nje znakova djevičanstva\' -');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 22, 15, 'neka tada djevojčin otac i majka uzmu dokaz djevojčina djevičanstva te ga iznesu pred gradske starješine na vrata.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 22, 16, 'Potom neka progovori starješinama djevojčin otac: \'Ovome sam čovjeku dao svoju kćer za ženu, ali mu je omrzla.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 22, 17, 'Stoga joj pripisuje svašta ružno i tvrdi: nisam u tvoje kćeri našao znakove djevičanstva. Ali evo djevičanskih znakova moje kćeri!\' I neka razastru plahtu pred gradskim starješinama.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 22, 18, 'Neka tada starješine onoga grada uzmu muža pa ga kazne;');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 22, 19, 'neka ga, zato što je pronio ružan glas o jednoj izraelskoj djevici, udare globom od stotinu srebrnika pa ih dadnu ocu mlade žene. I neka mu ona i dalje bude ženom da je ne može pustiti dok je živ.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 22, 20, 'Ali ako optužba - da se na mladoj ženi nije našlo djevičanstvo - bude istinita,');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 22, 21, 'neka djevojku izvedu na kućna vrata njezina oca pa neka je ljudi njezina grada kamenjem zasiplju dok ne umre, jer je počinila besramnost u Izraelu odajući se bludu u očevu domu. Tako ćeš iskorijeniti zlo iz svoje sredine.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 22, 22, 'Ako se koji čovjek zateče gdje leži sa ženom udatom za drugoga, neka oboje - i čovjek koji je ležao sa ženom i sama žena - budu smaknuti. Tako ćeš iskorijeniti zlo iz Izraela.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 22, 23, 'Ako mladu djevicu zaručenu za nekoga u gradu sretne drugi čovjek i s njom legne,');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 22, 24, 'oboje ih dovedite vratima toga grada pa ih kamenjem zasipljite dok ne umru: djevojku što nije zvala u pomoć u gradu, a čovjeka što je oskvrnuo ženu bližnjega svoga. Tako ćeš iskorijeniti zlo iz svoje sredine.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 22, 25, 'Ako čovjek u polju naiđe na zaručenu djevojku i silom legne s njom, onda neka se pogubi samo taj što je s njom legao;');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 22, 26, 'a djevojci nemoj ništa: nema na njoj krivnje kojom bi zasluživala smrt. Jer to je kao da navali tko na bližnjega svoga i ubije ga.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 22, 27, 'On ju je zatekao u polju; i premda je zaručena djevojka zapomagala, nije bilo nikoga da joj priskoči u pomoć.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 22, 28, 'Ako čovjek naiđe na mladu djevicu koja nije zaručena te je pograbi i s njom legne, pa budu uhvaćeni na djelu,');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 22, 29, 'tada čovjek koji je s njom ležao neka djevojčinu ocu dade pedeset srebrnika. A budući da ju je oskvrnuo, neka je uzme za ženu da je ne može pustiti dok je živ.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 23, 1, 'Neka se nitko ne ženi ženom oca svoga i neka ne odgrće očeva pokrivača.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 23, 2, 'Neka se u Jahvinu zajednicu ne prima onaj komu je stučena mošnjica ili odrezano udo.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 23, 3, 'Ni mješanac neka se ne prima u Jahvinu zajednicu; neka se njegovi ne primaju u zajednicu Jahvinu ni do desetog koljena.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 23, 4, 'Neka ne ulazi u Jahvinu zajednicu ni Amonac ni Moabac; nitko od njihovih, čak ni u deseto koljeno, ne smije nikad u zajednicu Jahvinu.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 23, 5, 'A sve zato što nisu izašli pred vas s kruhom i vodom kad bijaste na putu izišavši iz Egipta; i što su za novce najmili sina Beorova, Bileama iz Petora u Aram Naharajimu, da te prokune.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 23, 6, 'Ali Jahve, Bog tvoj, ne htjede uslišati Bileama nego ti Jahve, Bog tvoj, prometnu prokletstvo u blagoslov jer te ljubi Jahve, Bog tvoj.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 23, 7, 'Nikad ne promiči njihovo blagostanje i njihovo dobro u sve dane svoje dovijeka.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 23, 8, 'Nemoj prezirati Edomca, jer je on brat tvoj. Ne preziri ni Egipćanina, jer si bio došljak u zemlji njegovoj.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 23, 9, 'Njihovi potomci u trećem naraštaju mogu se primiti u Jahvinu zajednicu.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 23, 10, 'Kad pođeš s taborom na svoje neprijatelje, čuvaj se od svakoga zla.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 23, 11, 'Ako je među tvojima tko postao nečist zbog noćnog izljeva, neka iziđe iz tabora i neka se ne vraća u nj.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 23, 12, 'A predvečer neka se u vodi opere te u smiraje može opet u tabor.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 23, 13, 'Imaj izvan tabora mjesto gdje ćeš ići napolje.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 23, 14, 'Sa svojom opremom nosi i lopaticu: njome ćeš, kad ideš napolje, iskopati rupu i poslije zatrpati svoju nečist.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 23, 15, 'TÓa Jahve, Bog tvoj, ide posred tvoga tabora da te štiti i da ti predaje neprijatelje. Stoga i tvoj tabor treba da bude svet: neka Jahve ne zapazi u tebe ništa nedolično, da se ne bi odvratio od tebe.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 23, 16, 'Ne smiješ gospodaru izručivati roba koji je od svoga gospodara utekao k tebi.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 23, 17, 'Neka boravi s tobom u tvojoj sredini, u mjestu što ga odabere u jednome od tvojih gradova gdje mu se svidi. Nemoj s njime loše postupati.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 23, 18, 'Neka ne bude svetišne bludnice među izraelskim kćerima i neka ne bude svetišnog bludnika među izraelskim sinovima!');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 23, 19, 'Ne donosi u Dom Jahve, Boga svoga, ni za kakav zavjet bludničine plaće ni pasjeg novca, jer je oboje odvratno Jahvi, Bogu tvome.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 23, 20, 'Ne traži kamata od svoga brata, niti kamata za novac, niti kamata na jestvine, niti kamata na bilo što gdje se obično traže.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 23, 21, 'Od tuđinca možeš tražiti kamate, ali ih od svoga brata nemoj tražiti, da ti Jahve, Bog tvoj, udijeli blagoslov u svakom pothvatu tvoje ruke u zemlji u koju ideš da je zaposjedneš.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 23, 22, 'Kad zavjetuješ kakav zavjet Jahvi, Bogu svome, ne oklijevaj da ga ispuniš. Zacijelo će ga Jahve, Bog tvoj, od tebe tražiti; i bio bi ti grijeh.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 23, 23, 'Ako se ne zavjetuješ, neće ti biti grijeh.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 23, 24, 'Ali ispuni ono što prijeđe preko tvojih usana, zavjet koji si svojim ustima slobodno učinio Jahvi, Bogu svome.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 23, 25, 'Ako uđeš u vinograd svoga susjeda, slobodno ti je zobati grožđa do mile volje, ali u svoj sud ne smiješ stavljati.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 23, 26, 'Ako uđeš u žito svoga susjeda, možeš kidati klasove rukom, ali ne smiješ prinositi srpa susjedovu žitu.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 24, 1, 'Kada tko uzme ženu i s njome postupi kao muž, a potom na njoj otkrije što ružno te ona više ne nalazi milosti u njegovim očima i on joj napiše otpusno pismo, uruči joj ga i potjera je iz svoje kuće,');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 24, 2, 'a ona izađe iz njegove kuće, ode i pođe za drugoga');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 24, 3, 'pa omrzne i tome drugomu te joj i on napiše otpusno pismo, uruči joj ga i otjera je iz svoje kuće - ili pak umre taj koji ju je drugi uzeo -');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 24, 4, 'tada je, pošto se tako oskvrnula, ne može opet uzeti za ženu onaj prvi muž koji je bijaše otpustio. Bilo bi to odvratno pred Jahvom; ne smiješ uvaljivati u grijeh zemlju koju ti Jahve, Bog tvoj, daje u baštinu.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 24, 5, 'Kad se tko netom oženi, neka ne ide u vojsku; neka mu se ne dodjeljuje nikakva služba, nego, oslobođen, neka ostane kod kuće godinu dana da razveseljuje ženu koju je doveo.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 24, 6, 'Neka se ne uzima u zalog žrvanj, ni gornji ni donji: tÓa time bi se u zalog uzimao sam život.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 24, 7, 'Ako se nađe tko da otme koga između svoje braće Izraelaca te postupi s njim kao s robom ili ga proda, taj otmičar neka se smakne! Tako ćeš iskorijeniti zlo iz svoje sredine.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 24, 8, 'Javi li se guba, pazi da brižno držiš i vršiš sve što vas pouče levitski svećenici. Držite i vršite što njima naredim.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 24, 9, 'Sjećaj se što je Jahve, Bog tvoj, učinio Mirjami na putu kad ste izišli iz Egipta.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 24, 10, 'Kada bližnjemu svome daješ bilo kakav zajam, nemoj ulaziti u njegovu kuću da mu uzmeš zalog.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 24, 11, 'Stoj vani, a čovjek komu si dao zajam neka ti iznese zalog van.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 24, 12, 'A ako on bude siromah, nemoj lijegati s njegovim zalogom;');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 24, 13, 'o zalasku sunca moraš mu vratiti zalog da on mogne spavati u svome ogrtaču i tebe blagoslivljati. To će ti biti dobro djelo pred Jahvom, Bogom tvojim.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 24, 14, 'Nemoj zakidati jadnoga i bijednog najamnika, bio on tvoj sunarodnjak ili došljak iz kojega grada u tvojoj zemlji.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 24, 15, 'Svaki dan daj mu zaradu prije nego sunce zađe, jer je siromah i za njom uzdiše. Tako neće na te vapiti Jahvi i nećeš sagriješiti.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 24, 16, 'Neka se očevi ne osuđuju na smrt zbog sinova ni sinovi zbog očeva; neka svatko za svoj grijeh gine.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 24, 17, 'Ne izvrći pravice došljaku ni siroti i ne uzimaj u zalog haljine udovici.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 24, 18, 'Sjećaj se da si bio rob u Egiptu i da te odande izbavio Jahve, Bog tvoj; zato ti nalažem da ovu zapovijed vršiš.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 24, 19, 'Kad žanješ žito na svojoj njivi pa zaboraviš koji snop na njivi, ne vraćaj se po nj; neka ostane došljaku, siroti i udovici da te Jahve, Bog tvoj, blagoslovi u svakom pothvatu ruku tvojih.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 24, 20, 'Kad jednom omlatiš svoje masline, više iza sebe ne pretražuj; neka to ostane došljaku, siroti i udovici.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 24, 21, 'Kad obereš svoj vinograd, ne paljetkuj iza sebe; neka to bude za došljaka, sirotu i udovicu.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 24, 22, 'Sjećaj se kako si bio rob u zemlji egipatskoj; zato ti naređujem da ovu zapovijed vršiš.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 25, 1, 'Kad nastane svađa među ljudima i dođu na sud da im se sudi, neka se dade pravo onome koji je prav, a krivac neka se osudi.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 25, 2, 'Ako krivac zasluži da bude išiban, neka mu sudac naredi da legne i tu pred njim neka mu odbroje onoliko udaraca koliko odgovara njegovoj krivnji.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 25, 3, 'Do četrdeset udaraca može mu se dati, ali ne više, da modrica ne bi bila prevelika te se ne bi ponizio tvoj brat pred tobom kad bi mu udarali više udaraca.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 25, 4, 'Ne zavezuj usta volu kad vrše.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 25, 5, 'Kad braća stanuju zajedno pa jedan od njih umre a da nije imao sina, žena pokojnoga neka se ne preudaje izvan kuće, nego neka k njoj pristupi njezin djever i uzme je sebi za ženu te izvrši djeversku dužnost.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 25, 6, 'A prvi sin koga ona rodi neka ostane na ime njegova pokojnoga brata da njegovo ime ne izumre u Izraelu.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 25, 7, 'Ako, međutim, onaj čovjek ne želi da se oženi svojom snahom, onda njegova snaha neka dođe na vrata pred starješine i kaže: \'Neće djever moj da sačuva ime bratu svome u Izraelu; neće da mi učini djeversku dužnost.\'');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 25, 8, 'Neka ga pozovu starješine njegova grada i pitaju. Bude li uporan i kaže: \'Ne želim se njom ženiti\',');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 25, 9, 'neka njegova snaha k njemu pristupi na oči starješine pa mu skine s noge sandalu, pljune mu u lice i kaže ove riječi: \'Ovako se radi čovjeku koji neće da podigne doma svome bratu!\'');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 25, 10, 'Taj neka se prozove u Izraelu \'Dom bosoga\'.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 25, 11, 'Ako se dvojica potuku, pa žena jednoga pođe da izbavi svoga muža iz šaka onoga koji ga tuče i pruži ona svoju ruku i onoga uhvati za sram,');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 25, 12, 'odsijeci joj ruku i neka je ne sažaljuje oko tvoje.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 25, 13, 'U torbi nemoj nositi dvojak uteg, veći i manji.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 25, 14, 'U svojoj kući opet nemoj držati dvojaku efu: veću i manju.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 25, 15, 'Neka ti je uteg potpun i točan i neka ti je efa potpuna i točna, da dugo živiš na zemlji koju ti daje Jahve, Bog tvoj.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 25, 16, 'TÓa Jahvi je, Bogu tvome, odvratan tko to čini, tko god čini nepravdu.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 25, 17, 'Sjećaj se onoga što ti je učinio Amalek dok ste bili na putu pošto ste izišli iz Egipta;');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 25, 18, 'kako te dočeka na putu i pobi u tvom zaleđu sve nemoćne kad si bio umoran i iscrpljen jer se nije Boga bojao.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 25, 19, 'I zato kad te Jahve, Bog tvoj, smiri od svih tvojih neprijatelja naokolo u zemlji koju ti Jahve, Bog tvoj, daje u baštinu, izbriši pod nebom spomen na Amaleka. Ne zaboravi!');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 26, 1, 'Kad stigneš u zemlju koju ti Jahve, Bog tvoj, daje u baštinu, kad je zaposjedneš i u njoj se nastaniš,');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 26, 2, 'uzmi nešto prvina od svakoga ploda što ga budeš dobivao od zemlje koju ti Jahve, Bog tvoj, daje: stavi ih u košaru, otiđi u mjesto što ga Jahve, Bog tvoj, odabere da u njemu nastani svoje ime.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 26, 3, 'Stupi k svećeniku koji bude tada vršio službu i reci: \'Priznajem danas pred Jahvom, Bogom svojim, da sam stigao u zemlju za koju se Jahve zakleo našim ocima da će je nama dati.\'');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 26, 4, 'Zatim će svećenik uzeti iz tvoje ruke košaru i položiti je pred žrtvenik Jahve, Boga tvoga.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 26, 5, 'Ti onda nastavi i reci pred Jahvom, Bogom svojim: \'Moj je otac bio aramejski lutalac koji je sa malo čeljadi sišao u Egipat da se skloni. Ali je ondje postao velikim, brojnim i moćnim narodom.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 26, 6, 'Egipćani su s nama postupali loše; tlačili su nas i nametnuli nam teško ropstvo.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 26, 7, 'Vapili smo Jahvi, Bogu otaca svojih. Jahve je čuo vapaj naš; vidje naš jad, našu nevolju i našu muku.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 26, 8, 'Iz Egipta nas izvede Jahve moćnom rukom i ispruženom mišicom, velikom strahotom, znakovima i čudesima.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 26, 9, 'I dovede nas na ovo mjesto i dade nam ovu zemlju, zemlju kojom teče med i mlijeko.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 26, 10, 'I sad, evo, donosim prvine plodova sa tla što si mi ga, Jahve, dao.\' Stavi ih pred Jahvu, Boga svoga, i pred Jahvom, Bogom svojim, duboko se nakloni.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 26, 11, 'A onda zajedno s levitom i došljakom koji bude kod tebe uživaj sva dobra kojima je Jahve, Bog tvoj, obasuo tebe i dom tvoj.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 26, 12, 'A kad treće godine - godine desetine - završiš odjeljivanje sve desetine od svoga prihoda i dadeš levitu, došljaku, siroti i udovici po tvojim gradovima da jedu do sitosti,');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 26, 13, 'tada pred Jahvom, Bogom svojim, izjavi: \'Iz kuće sam uklonio ono što je bilo posvećeno. Dao sam još i levitu, došljaku, siroti i udovici, prema svim tvojim zapovijedima koje si mi izdao. Ni jedne tvoje zapovijedi nisam prekršio ni zaboravio.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 26, 14, 'Od toga nisam ništa jeo u žalosti; od toga nisam ništa žrtvovao u nečistoći, niti sam od toga što dao mrtvacu; slušao sam glas Jahve, Boga svoga; u svemu sam učinio kako si mi naredio.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 26, 15, 'Pogledaj s nebesa, iz svoga svetog prebivališta, i blagoslovi narod svoj izraelski i zemlju koju si nam dao, zemlju kojom teče med i mlijeko - kako si se zakleo ocima našim.\'');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 26, 16, 'Jahve, Bog tvoj, naređuje ti danas da vršiš ove zakone i uredbe. Drži ih, dakle, i vrši svim srcem svojim i svom dušom svojom.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 26, 17, 'Danas si ugovorio s Jahvom da će ti on biti Bog, a ti da ćeš ići njegovim putovima, držati njegove zakone, njegove zapovijedi i njegove uredbe i slušati njegov glas.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 26, 18, 'Danas je Jahve ugovorio s tobom da ćeš ti biti njegov narod, njegova predraga svojina, kako ti je obećao, i da ćeš držati sve njegove zapovijedi.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 26, 19, 'On će te uzvisiti čašću, imenom i slavom nad sve narode koje je stvorio; i ti ćeš biti narod posvećen Jahvi, Bogu svome, kako ti je rekao.\"');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 27, 1, 'Potom Mojsije i starješine izraelske nalože narodu: \"Vršite sve zapovijedi što vam ih danas naređujem.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 27, 2, 'Onog dana kad prijeđete preko Jordana u zemlju što ti je daje Jahve, Bog tvoj, podigni sebi veliko kamenje; krečom ga okreči');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 27, 3, 'i na njemu ispiši sve riječi ovoga Zakona u trenutku kad budeš ulazio u zemlju što ti je daje Jahve, Bog tvoj, u zemlju kojom teče med i mlijeko, kako ti je rekao Jahve, Bog otaca tvojih.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 27, 4, 'Kada, dakle, prijeđeš preko Jordana, onda to kamenje, kako ti danas zapovijedam, podigni na brdu Ebalu i okreči ga krečom.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 27, 5, 'Ondje sagradi i žrtvenik Jahvi, Bogu svome - žrtvenik od kamenja na koje nisi spuštao gvožđa.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 27, 6, 'Žrtvenik Jahvi, Bogu svome, sagradi od neklesana kamena. Na njemu prinosi paljenice Jahvi, Bogu svome.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 27, 7, 'Prinosi i pričesnice i ondje ih blaguj, radujući se pred Jahvom, Bogom svojim.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 27, 8, 'Ispiši na tom kamenju sve riječi ovoga Zakona: ureži ih dobro.\"');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 27, 9, 'Zatim Mojsije i levitski svećenici rekoše svemu Izraelu: \"Pozor, Izraele, i slušaj! Danas si postao narodom Jahve, Boga svoga.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 27, 10, 'Zato slušaj glas Jahve, Boga svoga, i vrši zapovijedi njegove i zakone njegove koje ti danas naređujem.\"');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 27, 11, 'Onoga dana naredi Mojsije narodu:');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 27, 12, '\"Kad prijeđete preko Jordana, neka ova plemena: Šimun, Levi, Juda, Jisakar, Josip i Benjamin stanu na brdu Gerizimu da blagoslivljaju narod.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 27, 13, 'A ova neka stanu na brdu Ebalu da proklinju: Ruben, Gad, Ašer, Zebulun, Dan i Naftali.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 27, 14, 'Neka onda Levijevci preuzmu riječ i jakim glasom reknu svim Izraelcima:');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 27, 15, '\'Proklet bio tko načini kumira, klesana ili livena - zazor Jahvi, djelo rukotvorca, sve ako ga stavi i na potajno mjesto.\' - I sav narod neka odgovori: \'Amen!\'');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 27, 16, '\'Proklet bio koji vrijeđa oca svoga i majku svoju!\' - I sav narod neka reče: \'Amen!\'');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 27, 17, '\'Proklet bio koji pomakne međaš susjedov!\' - I sav narod neka reče: \'Amen!\'');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 27, 18, '\'Proklet bio koji slijepca zavede na stranputicu!\' - I sav narod neka reče: \'Amen!\'');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 27, 19, '\'Proklet bio koji krnji prava došljaka, sirote i udovice!\' - I sav narod neka reče: \'Amen!\'');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 27, 20, '\'Proklet bio koji legne sa ženom oca svoga, jer je razgrnuo pokrivač oca svoga!\'- I sav narod neka reče: \'Amen!\'');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 27, 21, '\'Proklet bio koji legne s bilo kakvom životinjom!\' - I sav narod neka reče: \'Amen!\'');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 27, 22, '\'Proklet bio koji legne sa svojom sestrom, bila ona kći njegova oca ili kći njegove majke.\' - I sav narod neka reče: \'Amen!\'');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 27, 23, '\'Proklet bio koji legne s punicom svojom!\' - I sav narod neka reče: \'Amen!\'');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 27, 24, '\'Proklet bio koji ubije bližnjega svoga iz potaje!\' - I sav narod neka reče: \'Amen!\'');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 27, 25, '\'Proklet bio koji primi mito da smrt donese nevinome!\' - I sav narod neka reče: \'Amen!\'');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 27, 26, '\'Proklet bio koji ne bude držao riječi ovoga Zakona i vršio ih!\' - I sav narod neka reče: \'Amen!\'');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 28, 1, 'Ako zbilja poslušaš glas Jahve, Boga svoga, držeći i vršeći sve njegove zapovijedi što ti ih danas naređujem, Jahve, Bog tvoj, uzvisit će te nad sve narode na zemlji.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 28, 2, 'Svi ovi blagoslovi sići će na te i stići će te ako budeš slušao glas Jahve, Boga svoga.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 28, 3, 'Blagoslovljen ćeš biti u gradu, blagoslovljen u polju.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 28, 4, 'Blagoslovljen će biti plod utrobe tvoje, rod zemlje tvoje, plod blaga tvoga: mlad krava tvojih i prirast stada tvoga.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 28, 5, 'Blagoslovljen će biti tvoj koš i naćve tvoje.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 28, 6, 'Blagoslovljen ćeš biti kad ulaziš, blagoslovljen kad izlaziš.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 28, 7, 'Neprijatelje tvoje koji se dignu protiv tebe Jahve će položiti preda te potučene; jednim će putem izaći na te, a na sedam putova razbježat će se ispred tebe.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 28, 8, 'Jahve će narediti da blagoslov bude s tobom u žitnicama tvojim i u svakom pothvatu ruke tvoje i blagoslivljat će te u zemlji koju ti Jahve, Bog tvoj, daje.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 28, 9, 'Jahve će od tebe učiniti narod sebi posvećen, kako ti se zakleo, ako budeš držao zapovijedi Jahve, Boga svoga, i hodio njegovim putovima.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 28, 10, 'Svi narodi zemlje vidjet će da je nada te zazvano ime Jahvino te će strahovati od tebe.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 28, 11, 'Jahve će te obasuti obilnim dobrima: porodom utrobe tvoje, priraštajem blaga tvoga i rodom s tla tvoga u zemlji za koju se Jahve zakleo ocima tvojim da će ti je dati.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 28, 12, 'Jahve će ti otvoriti svoju bogatu riznicu - nebo - da daje kišu tvojoj zemlji u pravo vrijeme i blagoslovi svaki pothvat ruku tvojih. Mnogim ćeš narodima u zajam davati, a sam nećeš uzimati u zajam.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 28, 13, 'Jahve će te držati na pročelju, a ne u začelju; uvijek ćeš biti na vrhu, nikad na dnu, ako budeš slušao zapovijedi Jahve, Boga svoga, što ti ih danas naređujem da ih držiš i vršiš.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 28, 14, 'Ni od jedne riječi što vam je danas nalažem nemoj odstupati ni desno ni lijevo idući za drugim bogovima i iskazujući im štovanje.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 28, 15, 'Ali ako ne budeš slušao glasa Jahve, Boga svoga, ne držeći i ne vršeći svih njegovih zapovijedi i svih njegovih zakona što ti ih danas naređujem, sva će ova prokletstva doći na te i stići će te:');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 28, 16, 'Proklet ćeš biti u gradu, proklet u polju.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 28, 17, 'Proklet će biti koš tvoj i naćve tvoje.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 28, 18, 'Proklet će biti plod utrobe tvoje i rod zemlje tvoje, mlad krava tvojih i priraštaj stada tvoga.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 28, 19, 'Proklet ćeš biti kad ulaziš, proklet kad izlaziš.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 28, 20, 'Jahve će na te puštati prokletstvo, zabunu i kletvu u svemu na što pružiš ruku svoju da uradiš, sve dok ne budeš satrt i brzo ne propadneš zbog zloće svojih djela kojima si me napustio.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 28, 21, 'Kugu će Jahve za te privezati dok te ne nestane sa zemlje u koju ideš da je zaposjedneš.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 28, 22, 'Jahve će te udariti sušicom, groznicom, upalom, žegom i sušom, medljikom i snijeti; to će te goniti dok te ne nestane.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 28, 23, 'Nebesa nad tvojom glavom postat će mjedena, a tlo pod tvojim nogama postat će gvozdeno.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 28, 24, 'Kišu tvoje zemlje Jahve će pretvarati u pijesak i prašinu da na te pada s nebesa dok te ne uništi.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 28, 25, 'Jahve će od tebe učiniti pobijeđenoga pred tvojim neprijateljima; jednim ćeš putem prema njima izlaziti, a na sedam putova bježat ćeš ispred njih. Strašilo ćeš postati za sva zemaljska kraljevstva.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 28, 26, 'I mrtvo tijelo tvoje postat će hranom svim pticama nebeskim i svoj zvjeradi zemaljskoj. Nikoga neće biti da ih plaši.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 28, 27, 'Jahve će te udarati egipatskim prištevima, čirevima, krastama i svrabom, od kojih se nećeš moći izliječiti.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 28, 28, 'Jahve će te udarati bjesnilom, sljepoćom i ludilom;');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 28, 29, 'u po bijela dana tumarat ćeš kao što tumara slijepac po mraku; nećeš imati uspjeha u svojim pothvatima; sve vrijeme svoje bit ćeš izrabljivan i pljačkan, a neće biti nikoga da te spasi.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 28, 30, 'Sa ženom ćeš se zaručivati, ali će je drugi posjedovati. Kuću ćeš graditi, ali u njoj nećeš stanovati. Vinograd ćeš zasađivati, ali ga nećeš brati.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 28, 31, 'Tvoga će vola na tvoje oči zaklati, ali ti od njega nećeš jesti; tvoga će magarca ispred tebe otimati, ali ti ga neće vraćati; stado će tvoje neprijatelju tvome predavati, a neće biti nikoga da ti pritekne u pomoć.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 28, 32, 'Sinovi tvoji i kćeri tvoje bit će predavani drugome narodu. Oči će tvoje svaki dan kapati gledajući za njima, ali ruka tvoja neće moći ništa.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 28, 33, 'Narod koji i ne poznaješ jest će plod sa zemlje tvoje i svu muku tvoju, dok ćeš ti sve vrijeme svoje biti izrabljivan i gažen.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 28, 34, 'Ludovat ćeš od prizora što će ih oči tvoje gledati.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 28, 35, 'Jahve će te udarati ljutim prištevima po koljenima i po stegnima - od stopala nogu tvojih do tjemena na glavi tvojoj - od kojih se nećeš moći izliječiti.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 28, 36, 'Jahve će odvesti i tebe i tvoga kralja, koga budeš postavio nad sobom, među narod nepoznat i tebi i tvojim ocima te ćeš ondje iskazivati štovanje drugim bogovima, drvenim i kamenim.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 28, 37, 'Bit ćeš na zgražanje, porugu i ruglo svim narodima među koje te Jahve odvede.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 28, 38, 'Mnogo ćeš sjemena bacati u polje, ali ćeš malo žeti jer će ti urod skakavci ogolijevati.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 28, 39, 'Vinograde ćeš saditi i obrađivati, ali vina nećeš piti niti ćeš što brati jer će ih crv izjedati.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 28, 40, 'Imat ćeš masline po svemu svome području, ali se uljem nećeš mazati jer će ti masline opadati.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 28, 41, 'Sinove ćeš i kćeri rađati, ali tvoji neće biti jer će u sužanjstvo odlaziti.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 28, 42, 'Sva tvoja stabla i rod sa zemlje tvoje postat će plijenom kukaca.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 28, 43, 'Došljak koji bude u sredini tvojoj uzdizat će se nada te, a ti ćeš padati sve niže i niže.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 28, 44, 'On će uzaimati tebi, a ne ti njemu; on će biti glava, a ti rep.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 28, 45, 'Sva će te ova prokletstva snalaziti, progoniti i doseći dok te ne unište, jer nisi slušao glasa Jahve, Boga svoga, ni držao zapovijedi njegovih i zakona njegovih koje ti je dao.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 28, 46, 'Ona će služiti za čudesni znak na tebi i tvome potomstvu zauvijek.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 28, 47, 'Budući da nisi htio služiti Jahvi, Bogu svome, vesela i radosna srca zbog obilja svega,');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 28, 48, 'služit ćeš neprijatelju svome, koga će Jahve poslati na te, u gladu i žeđi, golotinji i oskudici svakoj. Na tvoju će šiju navaljivati jaram od gvožđa dok te ne satre.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 28, 49, 'Jahve će iz daljine, s kraja zemlje, dovesti na te narod koji će sletjeti kao orao. Bit će to narod kojemu jezika nećeš razumjeti;');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 28, 50, 'narod bezdušan, koji neće pokazivati obzira prema starima ni smilovanja prema mladima.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 28, 51, 'On će ti jesti mlado od tvoga blaga i rod tvoje njive dok te ne uništi; neće ti ostavljati ni žita, ni vina, ni ulja, ni mlado od krave, ni priraštaj od stada, sve dok te ne upropasti.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 28, 52, 'Opsjedat će te u svim tvojim gradovima širom zemlje tvoje dok ne obori visoke i utvrđene bedeme u koje si polagao nadu svoju; opsjednut će te u svim gradovima tvojim širom zemlje tvoje koju ti dadne Jahve, Bog tvoj.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 28, 53, 'U tjeskobi i jadu, kojima će te neprijatelj tvoj pritisnuti, jest ćeš plod utrobe svoje - meso sinova svojih i kćeri svojih koje ti dadne Jahve, Bog tvoj.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 28, 54, 'Čovjek najnježniji i najmekši u tebe zlobnim će okom gledati na vlastitog brata, ženu u svome naručju i djecu svoju što mu preostanu,');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 28, 55, 'ne hoteći ni s jednim od njih dijeliti mesa sinova svojih koje bude jeo, jer zbog tjeskobe i jada, kojima će te neprijatelj tvoj pritiskati po svim gradovima tvojim, drugo mu neće preostajati.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 28, 56, 'I žena najnježnija i najmekša što bude u tebe - toliko nježna i tankoćutna da se ne usuđuje spustiti stopala na zemlju - zlobnim će okom gledati na muža u svome naručju, i na sina svoga, i na kćer svoju,');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 28, 57, 'i na posteljicu svoju što joj iziđe između nogu, i na djecu što ih ima roditi, jer će ih potajno jesti, oskudna u svemu, zbog nevolje i jada kojim će te neprijatelj tvoj pritisnuti po svim gradovima tvojim.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 28, 58, 'Ako ne budeš držao i vršio riječi ovoga Zakona što su napisane u ovoj knjizi, ne poštujući ovo slavno i strašno Ime - Jahvu, Boga svoga -');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 28, 59, 'Jahve će tebe i tvoje potomstvo teško ošinuti velikim i dugotrajnim bičevima, pogubnim i dugim bolestima.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 28, 60, 'Pustit će na te sva zla egipatska kojih si se plašio, i ona će se prilijepiti za te.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 28, 61, 'A i svaku drugu bolest i bič, koji nije naveden u knjizi ovoga Zakona, Jahve će na te puštati dok te ne uništi.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 28, 62, 'Ostat će vas samo malo, vas što brojni bijaste kao zvijezde nebeske, a sve zato što nisi slušao glasa Jahve, Boga svoga.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 28, 63, 'Kako se Jahve nad vama radovao usrećujući vas i množeći, tako će se Jahve radovati nad vama rušeći vas i uništavajući da se iskorijenite sa zemlje u koju idete da je zaposjednete.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 28, 64, 'Jahve će vas razbacati po svim narodima, s kraja na kraj zemlje; ondje ćeš iskazivati štovanje drugim bogovima: drvenim i kamenim - koji su bili nepoznati i tebi i tvojim ocima.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 28, 65, 'Ali među tim narodima nećeš imati mira; ni tvome stopalu neće biti počivališta, nego će ti ondje Jahve dati srce uznemireno, oči utonule, dušu tjeskobnu.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 28, 66, 'Život tvoj visjet će o niti; bojat ćeš se i danju i noću i nećeš biti siguran za život svoj.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 28, 67, 'U strahu koji će ti stezati srce i od prizora što će ga oči tvoje gledati, jutrom ćeš govoriti: \'Oh, da je već večer!\' a navečer ćeš govoriti: \'Oh, da je već jutro!\'');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 28, 68, 'U Egipat će te na galijama natrag odvesti Jahve putem za koji sam ti rekao da ga više ne smiješ vidjeti. Ondje ćete se vi sami prodavati svojim neprijateljima za robove i ropkinje, ali neće biti kupca.\"');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 28, 69, 'To su riječi Saveza što ga propisa Jahve Mojsiju da ga sklopi s Izraelcima u zemlji moapskoj, povrh Saveza što ga je s njima sklopio na Horebu.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 29, 1, 'Mojsije sazva sav Izrael pa im reče: \"Vidjeli ste na rođene oči sve što je Jahve učinio u zemlji egipatskoj faraonu, svim službenicima njegovim i svoj zemlji njegovoj:');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 29, 2, 'velike kušnje što su ih vidjele tvoje oči, silne znakove i čudesa!');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 29, 3, 'Ali vam ne dade Jahve do danas razuma da shvatite, očiju da vidite ni ušiju da čujete.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 29, 4, 'Vodio sam vas pustinjom četrdeset godina; odjeća se na vama nije izderala niti su se sandale na vašim nogama raskidale.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 29, 5, 'Kruha niste jeli; vina ni drugoga opojnog pića niste pili, da biste znali da sam ja Jahve, Bog vaš.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 29, 6, 'Kad stigoste na novo mjesto, Sihon, kralj hešbonski, i Og, kralj bašanski, iziđoše pred nas u boj, ali smo ih potukli.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 29, 7, 'Zauzeli smo njihovu zemlju te je predali u baštinu Rubenovcima, Gadovcima i polovini plemena Manašeova.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 29, 8, 'Držite i vršite riječi ovog Saveza da uspijevate u svemu što poduzmete.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 29, 9, 'Danas stojite svi pred Jahvom, Bogom svojim: vaši plemenski glavari, vaše starješine i vaši nadglednici, svi muževi Izraela,');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 29, 10, 'djeca vaša, žene vaše i došljak koji je u tvome taboru - od onoga koji ti siječe drva do onoga koji ti nosi vodu -');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 29, 11, 'da stupite u Savez s Jahvom, Bogom svojim, u Savez zakletvom potvrđen, što ga Jahve, Bog tvoj, danas s tobom sklapa');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 29, 12, 'da danas od tebe učini svoj narod i da ti on bude Bog, kako ti je rekao i kako se zakleo tvojim ocima: Abrahamu, Izaku i Jakovu.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 29, 13, 'I ne sklapam danas ovaj Savez sa zakletvom samo s vama');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 29, 14, 'nego i sa svakim koji danas stoji ovdje s nama pred Jahvom, Bogom našim, i sa svakim koji danas nije ovdje s nama.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 29, 15, 'Sami znate kako smo boravili u zemlji egipatskoj i kako smo prošli posred naroda kroz koje ste morali proći.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 29, 16, 'Vidjeli ste njihove rugobe, njihove kumire od drveta i kamena, srebra i zlata što ih imaju.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 29, 17, 'Neka ne bude među vama čovjeka ni žene, roda ni plemena kojemu bi se srce danas odvratilo od Jahve, Boga našega, pa da ide iskazivati štovanje bogovima onih naroda. Neka ne bude među vama korijena koji rađa otrovom i pelinom.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 29, 18, 'Neka se nitko, čuvši riječi ovog prokletstva, ne nada blagoslovu kazujući u svome srcu: \'Bit će mi dobro ako poživim i po prohtjevima srca svoga. Nek\' povodanj utaži žeđ!\'');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 29, 19, 'Takvome neće Jahve nikad oprostiti, nego će se gnjev i ljubomornost Jahvina izliti na tog čovjeka, tako da će se sve prokletstvo zapisano u ovoj knjizi na nj oboriti te će Jahve izbrisati ime njegovo pod nebom.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 29, 20, 'Prema svim prokletstvima ovog Saveza, zapisanima u knjizi ovoga Zakona, Jahve će ga odstraniti, na njegovu propast, od svih plemena izraelskih.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 29, 21, 'Kasniji naraštaj, sinovi vaši poslije vas, i stranci koji dođu iz daleke zemlje, kad vide zla ove zemlje i bolesti što će ih Jahve pustiti na nju, reći će:');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 29, 22, '\'Sva je zemlja njegova samo sumpor i sol; niti se što sije niti što klija; nikakva travka na njoj ne raste; jednaka je srušenoj Sodomi i Gomori, Admi i Sebojimu, što ih Jahve sruši u svojoj ljutini i gnjevu.\'');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 29, 23, 'I svi će narodi pitati: \'Zašto učini Jahve ovako ovoj zemlji? Kakva je morala biti žestina toga silnoga gnjeva?\'');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 29, 24, 'Onda će im se reći: \'Jer su ostavili Savez što ga je Jahve, Bog otaca njihovih, bio sklopio s njima kad ih je izveo iz zemlje egipatske;');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 29, 25, 'i jer su otišli da iskazuju štovanje drugim bogovima i njima se klanjali, bogovima kojih nisu poznavali i kojih im on nije odredio.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 29, 26, 'Zato se Jahvin gnjev izlio na ovu zemlju i palo na nju sve prokletstvo zapisano u ovoj knjizi.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 29, 27, 'Jahve ih je iščupao iz njihove zemlje u ljutini, srdžbi i velikom gnjevu te ih bacio u drugu zemlju. Tako je i danas.\'');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 29, 28, 'Što je sakriveno, pripada Jahvi, Bogu našemu, a objava nama i sinovima našim zauvijek da vršimo sve riječi ovoga Zakona.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 30, 1, 'Kad te sve ove riječi, blagoslov i prokletstvo što ih danas preda te stavih, snađu i ti ih uzmeš k srcu među svim narodima među koje te Jahve, Bog tvoj, bude protjerao');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 30, 2, 'i obratiš se k Jahvi, Bogu svome, i poslušaš - i ti i tvoji sinovi - glas njegov iz svega srca svoga i iz sve duše svoje u svemu što sam ti danas naredio,');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 30, 3, 'tada će Jahve, Bog tvoj, vratiti tvoje izgnanike; smilovat će se tebi i opet ćete sabrati između svih naroda među koje te bude rastjerao Jahve, Bog tvoj.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 30, 4, 'Ako bi se koji izgnanik tvoj nalazio i na kraju svijeta, i odande će te sabrati Jahve, Bog tvoj - odande će te uzeti.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 30, 5, 'Jahve, Bog tvoj, dovest će te u zemlju koju su posjedovali oci tvoji da je ti zaposjedneš; učinit će te sretnijim i brojnijim od očeva tvojih.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 30, 6, 'Jahve, Bog tvoj, obrezat će tvoje srce, srce tvoga potomstva, tako da ljubiš Jahvu, Boga svoga, iz svega srca svoga i iz sve duše svoje i da živiš.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 30, 7, 'Jahve, Bog tvoj, svalit će sva ova prokletstva na neprijatelje tvoje, na mrzitelje tvoje koji su te progonili.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 30, 8, 'A ti ćeš ponovo slušati glas Jahvin i vršiti sve njegove zapovijedi koje ti danas dajem.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 30, 9, 'Jahve, Bog tvoj, obilno će te nagrađivati u svakom pothvatu ruku tvojih, u plodu utrobe tvoje, u plodu stoke tvoje i u urodu tvoga plodnog tla; jer Jahve će se opet radovati nad tvojim dobrom, kao što se radovao nad dobrom otaca tvojih,');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 30, 10, 'kad poslušaš glas Jahve, Boga svoga, držeći njegove zapovijedi i njegove naredbe zapisane u knjizi ovoga Zakona, to jest kada se obratiš Jahvi, Bogu svome, svim srcem svojim i svom dušom svojom.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 30, 11, 'Ova zapovijed što ti je danas dajem nije za te preteška niti je od tebe predaleko.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 30, 12, 'Nije na nebesima da bi rekao: \'Tko će se za nas popeti na nebesa, skinuti nam je te nam je objaviti da je vršimo?\'');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 30, 13, 'Nije ni preko mora da bi mogao reći: \'Tko će preko mora za nas poći, donijeti nam je te nam je objaviti da je vršimo?\'');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 30, 14, 'Jer, Riječ je posve blizu tebe, u tvojim ustima i u tvome srcu da je vršiš.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 30, 15, 'Gledaj! Danas preda te stavljam: život i sreću, smrt i nesreću.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 30, 16, 'Ako poslušaš zapovijedi Jahve, Boga svoga, koje ti danas dajem - ako ih poslušaš ljubeći Jahvu, Boga svoga, hodeći njegovim putovima, vršeći njegove zapovijedi, njegove zakone i njegove uredbe, živjet ćeš i razmnožit će te Jahve, Bog tvoj, i blagoslovit će te u zemlji u koju ulaziš da je zaposjedneš.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 30, 17, 'Ali ako se srce tvoje odvrati i ne poslušaš, nego zastraniš i budeš se klanjao drugim bogovima i njima iskazivao štovanje,');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 30, 18, 'ja vam danas izjavljujem da ćete zaista propasti; nećete dugo živjeti na zemlji u koju ćete, prešavši Jordan, ući da je zaposjednete.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 30, 19, 'Uzimam danas za svjedoke protiv vas nebo i zemlju da pred vas stavljam: život i smrt, blagoslov i prokletstvo. Život, dakle, biraj,');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 30, 20, 'ljubeći Jahvu, Boga svoga, slušajući njegov glas, prianjajući uz njega, da živiš ti i tvoje potomstvo. TÓa on je život tvoj, tvoj dugi vijek, da bi mirno mogao boraviti na zemlji za koju se Jahve zakle ocima tvojim Abrahamu, Izaku i Jakovu da će im je dati.\"');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 31, 1, 'Mojsije dođe da upravi ove riječi svemu Izraelu:');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 31, 2, '\"Meni je danas sto dvadeset godina\", - reče im. \"Ne mogu više izlaziti i ulaziti. A Jahve mi je rekao: \'Nećeš prijeći ovog Jordana!\'');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 31, 3, 'Sam Jahve, Bog tvoj, pred tobom će prijeći; on će pred tobom potući one narode da ih otjerate s posjeda. Jošua će pred tobom ići, kako je Jahve rekao.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 31, 4, 'Jahve će postupiti s njima kako je postupio sa Sihonom i Ogom, amorejskim kraljevima, i njihovom zemljom kad ih uništi.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 31, 5, 'Pred vas će ih Jahve položiti, a vi ćete s njima postupati prema svim naredbama koje sam vam dao.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 31, 6, 'Ohrabrite se i budite odlučni! Ne bojte se i nemojte prÓedati pred njima. TÓa sam Jahve, Bog tvoj, ide s tobom; neće te zapustiti niti će te ostaviti.\"');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 31, 7, 'Tada Mojsije zovnu Jošuu pa mu reče pred svim Izraelom: \"Ohrabri se i budi odlučan! Jer ti ćeš ići s ovim narodom u zemlju za koju se Jahve zakle ocima njihovim da će im je dati; ti ćeš im je predavati u baštinu.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 31, 8, 'Sam Jahve ide pred tobom; on će s tobom biti; neće te zapustiti niti će te ostaviti. Ne boj se i ne dršći!\"');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 31, 9, 'Mojsije napisa ovaj Zakon i predade ga svećenicima, sinovima Levijevim, koji su nosili Kovčeg saveza Jahvina, i svim izraelskim starješinama.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 31, 10, 'Mojsije im naredi: \"Svake sedme godine - godine oprosne - na Blagdan sjenica,');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 31, 11, 'kad dođe sav Izrael da vidi lice Jahve, Boga tvoga, na mjestu koje on odabere, pročitaj ovaj Zakon u nazočnosti svega Izraela.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 31, 12, 'Saberi narod - ljude, žene, djecu i došljaka što bude u tvojim gradovima - da čuju i da nauče bojati se Jahve, Boga vašega, pa da drže i vrše sve riječi ovog Zakona.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 31, 13, 'Sinovi njihovi, koji to još ne znaju, čut će i naučit će bojati se Jahve, Boga vašega, sve vrijeme dok budete živjeli na zemlji što ćete je, prešavši Jordan, zaposjesti.\"');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 31, 14, 'Jahve reče Mojsiju: \"Evo se bliži vrijeme tvoje smrti. Zovni Jošuu i nađite se u Šatoru sastanka da mu dam zapovijedi.\" Mojsije i Jošua dođu u Šator sastanka.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 31, 15, 'U Šatoru pokaže se Jahve u stupu od oblaka. Stup od oblaka stajao je na ulazu u Šator.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 31, 16, 'Jahve reče Mojsiju: \"Evo ćeš naskoro počinuti sa svojim ocima. A narod će se ovaj dići da čini blud idući za tuđim bogovima one zemlje u koju će naskoro ući; mene će napustiti i prekršit će moj Savez što ga s njim sklopih.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 31, 17, 'I onda će se izliti moj gnjev na nj. Ostavit ću ih tada i sakriti od njih svoje lice da budu proždirani. Snaći će ih mnoga zla i nevolje i onda će reći: \'Zar me ne snalaze ove nevolje zbog toga što Bog moj nije u mojoj sredini?\'');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 31, 18, 'A ja ću sasvim sakriti svoje lice u taj dan, zbog svega zla što ga budu činili okrećući se drugim bogovima.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 31, 19, 'Pišite sada sebi ovu pjesmu. Neka je nauče Izraelci! Stavi je u njihova usta da mi ova pjesma bude svjedokom protiv Izraelaca.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 31, 20, 'Kad ih dovedem u zemlju kojom teče med i mlijeko i za koju se zakleh ocima njihovim i kad se najedu, nasite i ugoje, okrenut će se oni drugim bogovima i njima će iskazivati štovanje; mene će prezreti i prekršiti moj Savez.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 31, 21, 'A kad ih snađu mnoge nesreće i nevolje, ova pjesma, jer je njihovo potomstvo neće nikada zaboraviti, pružit će svjedočanstvo protiv njih. Jer znam ja njihove osnove i što već danas snuju, prije nego sam ih i doveo u zemlju koju im pod zakletvom obećah.\"');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 31, 22, 'Toga dana napisa Mojsije ovu pjesmu i nauči Izraelce pjesmi.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 31, 23, 'Nunovu sinu Jošui naloži: \"Ohrabri se i budi odlučan! Jer ti ćeš uvesti Izraelce u zemlju za koju sam im se zakleo. I ja ću biti s tobom.\"');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 31, 24, 'Kad Mojsije napisa riječi ovoga Zakona u knjigu,');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 31, 25, 'tada naredi Levijevcima, koji su nosili Kovčeg saveza Jahvina:');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 31, 26, '\"Uzmite knjigu ovoga Zakona i položite je uz Kovčeg saveza Jahvina. Neka ondje bude svjedokom protiv tebe!');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 31, 27, 'TÓa znam ja tvoju buntovnost i tvoju tvrdu šiju. Evo i danas, dok još s vama živim, bunite se protiv Jahve. A kako li nećete kad ja umrem!');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 31, 28, 'Saberite k meni sve starješine svojih plemena i svoje nadglednike da na njihove uši kažem ove riječi te da protiv njih uzmem za svjedoke nebo i zemlju.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 31, 29, 'Jer znam ja da ćete se nakon moje smrti izopačiti i skrenuti s puta koji sam vam odredio; nesreća će vas snaći u budućim vremenima kad budete činili što je Jahvi nemilo i gnjevili ga djelima ruku svojih.\"');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 31, 30, 'A onda, na uši sve zajednice izraelske, Mojsije izgovori do kraja riječi ove pjesme:');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 32, 1, '\"Slušajte, nebesa, sad ću govoriti; čuj, zemljo, riječi usta mojih!');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 32, 2, 'Nek\' mi nauk daždi poput kiše, kao rosa riječ nek\' moja pada, kao kišica po mladoj zeleni, kao pljusak po travi velikoj!');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 32, 3, 'Jer, Jahvino ću ime uznositi, a vi Boga našeg veličajte!');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 32, 4, 'On je Stijena, djelo mu je savršeno, jer pravi su svi njegovi putovi. Bog je on vjeran i bez zloće, pravedan je on i pravičan.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 32, 5, 'Oni mu se iznevjeriše - nisu mu sinovi, već nakaze sinovske, porod izopačen i prepreden.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 32, 6, 'Tako li uzvraćaš Jahvi, narode glupi i bezumni! Nije li on Otac tvoj, Stvoritelj, koji te sazdao, po kom postojiš?');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 32, 7, 'Spomeni se dana pradavnih, promotri godine od naraštaja do naraštaja. Oca svoga pitaj, i poučit će te, pitaj starije, pa će ti kazati.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 32, 8, 'Kad je Višnji baštinu dijelio narodima, kad je razmještao sinove čovječje, odredi im međe po broju Božjih sinova:');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 32, 9, 'tad Jahvu njegov narod zapade, Jakov bi njegova baština.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 32, 10, 'U zemlji stepskoj on ga je našao, u pustinjskoj jezivoj pustoši. Obujmio ga, gajio ga i čuvao k\'o zjenu oka svoga.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 32, 11, 'Poput orla što bdi nad gnijezdom, nad svojim orlićima lebdeći, tako on krila širi, uzima ga, pa ga na svojim nosi perima.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 32, 12, 'Jahve sam njega je vodio, tuđeg boga s njim ne bijaše.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 32, 13, 'Povede ga po visočjima zemlje, nahrani ga plodovima poljskim, dade mu meda iz pećine i ulja iz tvrde stijene;');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 32, 14, 'kravljeg masla i ovčjeg mlijeka s pretilinom jaganjaca, ovnova bašanskih i jaraca, sa salom žitnih bubrega, i napoji ga pjenušavom krvlju grožđa.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 32, 15, 'Jeo je Jakov i nasitio se, ugojio se Ješurun pa se uzritao. Udebljao si se, utovio, usalio. Odbacio je Boga koji ga stvori i prezreo Stijenu svog spasenja.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 32, 16, 'Tuđim bozima učiniše ga ljubomornim, razjariše ga gnusobama.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 32, 17, 'Žrtvovahu zlodusima koji Bog nisu, bogovima kojih ne poznavahu prije, došljacima koji stigoše nedavno i koje oci njihovi ne štovahu.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 32, 18, 'Odnemaruješ Stijenu što te na svijet dade, ne sjećaš se više Boga koji te rodi!');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 32, 19, 'Vidje to Jahve i u gnjevu svojem odbaci sinove svoje i kćeri.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 32, 20, 'Lice ću im svoje sakriti, reče, i vidjet ću što će biti od njih. Jer izopačeno je to koljeno, sinovi u kojima vjernosti nema.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 32, 21, 'Ništavnim me bogom na ljubomor potakoše, razdražiše me ništavilima svojim, i ja ću njih ljubomornim učinit\', pukom ništavnim, razdražit ću ih glupim nekim narodom!');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 32, 22, 'Da, moga gnjeva požar je usplamtio i gorjet će do dubina šeolskih; proždrijet će zemlju i sve što ona rađa, sažeći joj brda do temelja.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 32, 23, 'Nevolje na njih ću svaliti, na njih ću svoje istrošiti strijele.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 32, 24, 'Od gladi će umirati, ognjica i pošast njih će trovati. Poslat ću na njih zub zvjerinji i otrov zmija što prahom gmižu.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 32, 25, 'Vani će mač zatirati djecu, a strava će vladati unutra. Ginut će jednako momak i djevojka, dojenče i starac sjedokos.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 32, 26, 'Rekoh: U prah ću ih smrviti, zbrisati im spomen izmed ljudi.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 32, 27, 'Ali se bojah ruga dušmanskoga: mogli bi im prevarit\' se protivnici, pa da kažu: \'Pobjeda je naša, nije to Jahvina izvela ruka.\'');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 32, 28, 'Jer narod je to neupućen, oštroumlja u njih nema.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 32, 29, 'Da su mudri, već bi se i dosjetili, razabrali što ih očekuje.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 32, 30, 'Kako da jedan tisuću u bijeg nagna, i deset tisuća da dvojica gone, da ih Stijena njina nije prodala, da ih Jahve nije izručio?');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 32, 31, 'Al\' stijena im nije poput naše Stijene; osuđeni su naši neprijatelji.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 32, 32, 'Jer trs je njihov od sodomskog trsa i od vinograda gomorskih; grožđe im je grožđe otrovno, grozdovi im grozdovi gorčine;');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 32, 33, 'njihovo je vino otrov zmijski, žestok jed otrovnice ljute.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 32, 34, 'Al\' nije li on u mene poput dragulja, zapečaćen u mojim riznicama?');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 32, 35, 'Moja je odmazda i nagrada u vrijeme kad im noga posrne. Jer blizu je dan njihove propasti, udes njihov brzo im se bliži!');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 32, 36, '(Pravdu će Jahve dati svome puku, sažalit se nad slugama svojim.) Vidjet će da im gine snaga, da je i robu i slobodnu kraj.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 32, 37, 'Tad će reći: \'Ta gdje su bozi njihovi, gdje stijena kojom se zaklanjahu?');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 32, 38, 'Oni što su jeli salo njihovih klanica i pili vino njihovih ljevanica?\' Neka se dignu i neka vam pomognu, nek\' vam budu zaklonište!');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 32, 39, 'Vidite sada da ja, ja jesam, i da drugog Boga pored mene nema! Ja usmrćujem i oživljujem; ja udaram i iscjeljujem (i nitko se iz ruke moje ne izbavlja).');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 32, 40, 'Da, svoju ruku ja dižem prema nebu i kažem: Ne bio ja živ vječito');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 32, 41, 'ako naoštrivši mač svoj blistavi ne uzmem sud u svoje ruke da svojim odmazdim dušmanima, da naplatim onima koji mene mrze.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 32, 42, 'Strijele svoje opojit ću krvlju i mač moj najest će se mesa, krvi ubijenih i zarobljenih, glava dušmanskih vrhovnika.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 32, 43, 'Kličite, o nebesa, s njime, obožavajte ga, sinovi Božji! Kličite, puci, s njegovim narodom, uznosite snagu njegovu, poslanici Jahvini. Jer će krv slugu svojih osvetiti, istom mjerom vratit\' dušmanima, naplatit će od onih koji njega mrze, očistit\' od grijeha zemlju svog naroda.\"');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 32, 44, 'Dođe Mojsije s Jošuom, sinom Nunovim, te izgovori u uši naroda riječi ove pjesme.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 32, 45, 'Kad Mojsije izgovori sve ove riječi svemu Izraelu,');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 32, 46, 'reče im: \"U srca svoja usadite sve riječi koje danas uzimam za svjedoka protiv vas; naredite sinovima svojim da ih drže vršeći sve riječi ovoga Zakona.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 32, 47, 'TÓa nije to za vas prazna riječ jer ona je vaš život. Zbog ove riječi živjet ćete dugo na zemlji koju ćete, prešavši Jordan, zaposjesti.\"');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 32, 48, 'Toga istog dana Jahve reče Mojsiju:');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 32, 49, '\"Popni se na goru Nebo u Abarskom gorju - ono je u moapskoj zemlji nasuprot Jerihonu - pa pogledaj zemlju kanaansku što ću je dati u posjed Izraelcima.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 32, 50, 'Onda umri na gori na koju se uspneš i pridruži se svojim precima kao što je i tvoj brat Aron, koji je umro na brdu Horu, bio pridružen svojima.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 32, 51, 'A to zato što ste mi se iznevjerili sred Izraelaca kod Meriba Kadeša, kod voda u pustinji Sinu: niste očitovali moju svetost među Izraelcima.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 32, 52, 'Zato ćeš samo izdaleka vidjeti onu zemlju, ali u nju nećeš ući - u zemlju koju dajem Izraelcima.\"');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 33, 1, 'Ovo je blagoslov kojim Mojsije - čovjek Božji - blagoslovi Izraelce pred svoju smrt.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 33, 2, 'Reče on: \"Dođe Jahve sa Sinaja, sa Seira im se pokaza i s gore Parana zasja. Zbog njih dođe od kadeških zborova, sa svoga juga sve do Obronaka.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 33, 3, 'Ipak ti ljubiš narode, svi sveti njihovi u tvojoj su ruci. Pred tvojim su ležali nogama, išli tobom predvođeni.\"');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 33, 4, '(Mojsije nam je odredio zakon.) \"Zbor Jakovljev njegovom posta baštinom;');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 33, 5, 'i bje kralj u Ješurunu kad se sakupiše glavari narodni, kad se sjediniše plemena Jakovljeva.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 33, 6, 'Nek\' živi Ruben i nikad nek\' ne izumre, nek\' živi šačica njegovih!');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 33, 7, 'Evo što reče za Judu: Uslišaj, Jahve, glas Judin i privedi ga k njegovu narodu. Nek mu ruke njegovo brane pravo, pomozi mu protiv dušmana njegovih.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 33, 8, 'O Leviju reče: Daj Leviju tvoje Urime i tvoje Tumime čovjeku milosti svoje, koga si u Masi iskušao, s kojim si se preo kod voda meripskih.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 33, 9, 'O ocu svome i majci reče on: Nisam ih vidio! Braće svoje ne poznaje, na svoju se djecu ne osvrće, jer tvoju riječ on je vršio i tvojega se držao Saveza.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 33, 10, 'On uči Jakova tvojim odredbama i Izraela tvojemu Zakonu. On podiže kad k tvojim nosnicama i paljenicu na žrtvenik ti stavlja.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 33, 11, 'O Jahve, snagu mu blagoslovi, milostivo primi djelo ruku njegovih. Slomi bedra njegovih neprijatelja; mrzitelji njegovi nek\' više ne ustanu.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 33, 12, 'O Benjaminu reče: Jahvin je on ljubimac i u miru svagda počiva. Višnji ga štiti svih njegovih dana, između njegovih prebiva bregova.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 33, 13, 'O Josipu reče: Zemlju mu je Jahve blagoslovio; njegovo je najbolje od onog što daje rosa nebeska i što se u bezdanima dolje krije!');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 33, 14, 'Najbolje od onog što daruje sunce i što mlađak novi nosi,');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 33, 15, 'prvine s drevnih planina i najbolje s vječnih brežuljaka,');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 33, 16, 'ponajbolji rod zemlje i svega što je na njoj i milost Onog što prebiva u grmu. Nek\' sve to dođe na glavu Josipovu, na tjeme posvećenog između sve braće!');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 33, 17, 'K\'o prvenac bika on je veličanstven, rozi su mu rogovi bivolji, njima on nabada narode sve do krajeva zemaljskih. Takva su mnoštva Efrajimova, takve su tisuće Manašeove.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 33, 18, 'O Zebulunu reče: Bio sretan, Zebulune, u pohodima, i ti, Jisakare, u šatorima svojim!');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 33, 19, 'Na brdu gdje dolaze zazivati narodi za uspjeh prinose oni prave žrtve jer sišu obilje mora i blago skriveno u pijesku.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 33, 20, 'O Gadu reče: Nek\' je blagoslovljen tko Gada raširi! Poput lavice on počiva razderavši mišicu i glavu.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 33, 21, 'Prvine je tad sebi dodijelio jer vidje da mu je sačuvan dio glavarev. Na čelu svega naroda on je došao, pravdu Jahvinu izvršivši i odluke njegove s Izraelom.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 33, 22, 'O Danu reče: Dan je lavić što skače iz Bašana.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 33, 23, 'O Naftaliju reče: Naftali, milostima nasićen, Jahvinim ispunjen blagoslovom: more i jug njegovo su vlasništvo.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 33, 24, 'O Ašeru reče: Blagoslovljen bio Ašer među sinovima! Nek\' miljenik bude među braćom svojom, i nek\' noge svoje u ulje umače!');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 33, 25, 'Nek\' ti zasuni budu od gvožđa i mjedi i nek\' ti mir traje koliko i život!');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 33, 26, 'Nitko nije kao Bog Ješurunov: po nebesima u pomoć ti jezdi i po oblacima u svom veličanstvu!');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 33, 27, 'Bog vječni tvoje je utočište, a na zemlji drevna njegova mišica pred tobom goni neprijatelja; on dovikuje: \'Uništi!\'');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 33, 28, 'U sigurnosti prebiva Izrael, a Jakovljev je izvor na osami u zemlji žita i vina, gdje nebesa rosom dažde.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 33, 29, 'Blago tebi, Izraele! Koji narod k\'o tebe Jahve spasava? On štit je tvoj što te brani i mač tvoj slavodobitni, dušmani ti se ulaguju, al\' ti ćeš im gazit\' po leđima.\"');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 34, 1, 'Poslije toga ode Mojsije s Moapskih poljana na brdo Nebo, na vrhunac Pisge nasuprot Jerihonu, gdje mu Jahve pokaza svu zemlju: Gilead do Dana,');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 34, 2, 'sav Naftali, kraj Efrajimov i Manašeov, svu Judinu krajinu do Zapadnog mora;');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 34, 3, 'zatim Negeb, područje doline Jerihona - grada palmi - do Soara.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 34, 4, 'Potom mu reče Jahve: \"Ovo je zemlja za koju sam se zakleo Abrahamu, Izaku i Jakovu da ću je dati tvome potomstvu. Dopustio sam da je pogledaš svojim očima, ali ti onamo nećeš prijeći.\"');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 34, 5, 'I Mojsije, sluga Jahvin, umrije ondje u zemlji moapskoj po Jahvinoj zapovijedi.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 34, 6, 'I ukopa ga on u dolini u zemlji nasuprot Bet Peoru. Do dana današnjega nitko nije doznao za njegov grob.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 34, 7, 'Mojsiju bijaše sto dvadeset godina kad umrije. Oko mu nije oslabilo niti mu je snaga popustila.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 34, 8, 'Izraelci oplakivahu Mojsija na Moapskim poljanama trideset dana. Potom prođoše i dani oplakivanja - tugovanja za Mojsijem.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 34, 9, 'A Jošua, sin Nunov, bio je ispunjen duhom mudrosti jer Mojsije bijaše na nj položio svoje ruke. Njega su Izraelci slušali i činili kako je Jahve naredio Mojsiju.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 34, 10, 'Ne pojavi se više prorok u Izraelu ravan Mojsiju - njega je Jahve poznavao licem u lice! -');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 34, 11, 'po svim onim znakovima i čudesima u zemlji egipatskoj za koja ga je Jahve slao da ih učini na faraonu, na svim službenicima njegovim i na svoj zemlji njegovoj,');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 34, 12, 'po onoj moćnoj ruci njegovoj i po svim onim velikim zastrašnim djelima koja učini na oči svega Izraela.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 1, 1, 'Poslije smrti Mojsija, sluge Jahvina, reče Jahve Jošui, sinu Nunovu, pomoćniku Mojsijevu:');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 1, 2, '\"Moj je sluga Mojsije umro; zato sada ustani, prijeđi preko toga Jordana, ti i sav taj narod, u zemlju koju dajem sinovima Izraelovim.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 1, 3, 'Svako mjesto na koje stupi vaša noga dajem vam, kao što obećah Mojsiju.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 1, 4, 'Od pustinje i od Libanona pa do Velike rijeke, rijeke Eufrata, i sve do Velikog mora na sunčanom zapadu - sve će to biti vaše područje.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 1, 5, 'Nitko neće odoljeti pred tobom u sve dane tvog života; ja ću biti s tobom, kao što sam bio s Mojsijem, i nikada te neću napustiti niti ću te ostaviti.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 1, 6, 'Budi odvažan i hrabar jer ćeš ti uvesti narod ovaj da primi u baštinu zemlju za koju se zakleh ocima njihovim da ću im je dati.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 1, 7, 'Samo budi odvažan i hrabar da sve učiniš vjerno prema naredbama koje ti je dao Mojsije, sluga moj. Ne skreći od toga ni desno ni lijevo da bi ti bilo sretno sve što poduzmeš.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 1, 8, 'Neka knjiga Zakona bude na ustima tvojim: razmišljaj o njoj danju i noću, kako bi vjerno držao sve što je u njoj napisano: samo ćeš tada biti sretan i uspjet ćeš u pothvatima. Nisam li ti zapovjedio:');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 1, 9, 'odvaži se i budi hrabar? Ne boj se i ne strahuj, jer kuda god pođeš, s tobom je Jahve, Bog tvoj.\"');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 1, 10, 'Tada zapovijedi Jošua glavarima narodnim:');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 1, 11, '\"Prođite kroz tabor i proglasite puku ovu zapovijed: \'Spremite sebi brašnenice jer ćete za tri dana prijeći preko Jordana da biste primili u posjed zemlju koju vam Jahve, Bog vaš, daje u baštinu.\'\"');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 1, 12, 'Zatim reče Jošua plemenu Rubenovu i Gadovu i polovini plemena Manašeova:');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 1, 13, '\"Sjetite se onoga što vam je zapovjedio Mojsije, sluga Jahvin, kada vam je rekao: \'Jahve, Bog vaš, hoće da počinete i daje vam ovu zemlju.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 1, 14, 'Vaše žene, djeca i stada mogu ostati u zemlji koju vam je dao Mojsije s onu stranu Jordana. Vi pak ratnici, za boj spremni, morate naoružani poći pred svojom braćom da im pomognete,');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 1, 15, 'sve dok Jahve ne dade da počinu i vaša braća, kao i vi, i dok ne zaposjednu zemlju koju im daje Jahve, Bog vaš. Tada se možete vratiti u zemlju koja vam pripada i koju vam je dao Jahvin sluga Mojsije, na drugoj strani Jordana, prema istoku sunca.\'\"');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 1, 16, 'Oni odgovore Jošui: \"Sve što nam zapovjediš, učinit ćemo, i kuda nas god pošalješ, poći ćemo.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 1, 17, 'Kao što smo slušali Mojsija, tako ćemo se pokoravati i tebi. Samo neka Jahve, Bog tvoj, bude s tobom kao što bijaše s Mojsijem!');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 1, 18, 'Tko se god usprotivi tvome glasu i ne posluša tvojih riječi u svemu što mu zapovjediš neka bude pogubljen. Samo ti budi odvažan i hrabar!\"');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 2, 1, 'Jošua, sin Nunov, posla potajno iz Šitima dvojicu uhoda s nalogom: \"Idite, izvidite područje, osobito Jerihon.\" Oni odu i stignu u kuću bludnice koja se zvala Rahaba i ondje prenoće.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 2, 2, 'To bude javljeno kralju jerihonskom: \"Evo, stigoše noćas ovamo neki ljudi od sinova Izraelovih da izvide zemlju.\"');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 2, 3, 'Tada kralj jerihonski poruči Rahabi: \"Izvedi ljude koji su došli k tebi, koji su ušli u tvoj dom, jer su došli uhoditi svu zemlju.\"');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 2, 4, 'Ali žena uze ona dva čovjeka, sakri ih i reče: \"Istina, ti su ljudi došli k meni, ali ja nisam znala odakle su.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 2, 5, 'Kada se u sumrak zatvarahu gradska vrata, oni odoše i ja ne znam kamo su krenuli. Požurite za njima jer ih još možete stići.\"');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 2, 6, 'A ona ih bijaše izvela na krov i sakrila pod netrveni lan što ga je ondje razastrla.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 2, 7, 'I požure se ljudi u potjeru za njima, prema Jordanu, sve do prijelaza preko rijeke; a kad je potjera izišla, zatvore se za njima gradska vrata.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 2, 8, 'Dok još oni gore ne bijahu zaspali, popne se Rahaba k njima na krov');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 2, 9, 'i reče im: \"Znam da vam je Jahve dao ovu zemlju, jer nas je sve uhvatio strah od vas i prezaju od vas svi žitelji ovoga kraja.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 2, 10, 'Jer čusmo kako je Jahve isušio vodu Crvenoga mora pred vama kada ste izašli iz Egipta, i ono što ste učinili dvojici kraljeva amorejskih s druge strane Jordana, Sihonu i Ogu, koje pogubiste.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 2, 11, 'Kad smo čuli sve to, zastalo nam srce i nitko da smogne snage da vam se suprotstavi jer Jahve, Bog vaš - on je Bog gore na nebesima i dolje na zemlji.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 2, 12, 'Zakunite mi se, dakle, Jahvom da ćete i vi učiniti milost domu oca moga, kao što i ja učinih milost vama, i dajte mi pouzdan znak');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 2, 13, 'da ćete ostaviti na životu moga oca i moju majku, braću moju i sestre moje i sve njihovo i da ćete nas izbaviti od smrti.\"');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 2, 14, 'Odgovoriše joj ljudi: \"Životom svojim jamčimo za vas, samo ako nas ne izdate. Kad nam Jahve dade zemlju, iskazat ćemo ti milost i vjernost.\"');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 2, 15, 'Rahaba ih zatim spusti po konopu kroz prozor jer joj je kuća bila uz bedem i ona je do bedema stanovala.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 2, 16, 'Još im reče: \"Pođite prema gori da vas potjera ne nađe i krijte se ondje tri dana dok se progonitelji ne vrate, a onda idite svojim putem.\"');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 2, 17, 'Ljudi joj odgovore: \"Evo, ovako ćemo ti ispuniti zakletvu kojom si nas zaklela:');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 2, 18, 'kad uđemo u zemlju, posluži se ovim znakom: priveži ovu crvenu vrpcu za prozor kroz koji nas spuštaš i sakupi kod sebe, u kući, svoga oca, i svoju majku, i svoju braću, i svu svoju rodbinu.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 2, 19, 'Tko god od vas stupi van preko praga tvoje kuće, krv njegova na glavu njegovu: nije krivnja na nama - sam je krivac svojoj smrti; a tko ostane s tobom u kući, krv njegova neka padne na glave naše - mi ćemo biti krivci ako ga se tko rukom dotakne.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 2, 20, 'Ako pak izdaš ovu našu stvar, slobodni smo od zakletve kojom si nas zaklela.\"');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 2, 21, 'A ona odgovori: \"Neka bude kako rekoste!\" Tada ih pusti i oni odoše, a ona zaveza na prozor crvenu vrpcu.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 2, 22, 'Oni odoše i dođoše u goru i ondje ostadoše tri dana dok se ne vrati potjera; tražila ih je potjera na svim putovima, ali ih nije nigdje našla.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 2, 23, 'Tada se vrate i one dvije uhode: siđu s gore, prijeđu preko rijeke i dođu k Jošui, sinu Nunovu, te ga izvijeste o svemu što im se dogodilo.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 2, 24, 'I rekoše Jošui: \"Jahve nam je svu tu krajinu predao u ruke; sve je njezine stanovnike uhvatio strah pred nama.\"');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 3, 1, 'Urani Jošua i sa svim sinovima Izraelovim krene od Šitima. I stignu do Jordana pa ondje prije prelaza prenoće.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 3, 2, 'Poslije tri dana prođu starješine kroz tabor i zapovjede puku:');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 3, 3, '\"Čim ugledate Kovčeg saveza Jahve, Boga vašega, i svećenike levite koji ga nose, krenite svi sa svoga mjesta i pođite za njim.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 3, 4, 'Tako ćete znati put kojim vam je ići, jer tim putem još nikada niste išli. Ali između vas i Kovčega neka bude razmak do dvije tisuće lakata. I da mu se niste približili.\"');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 3, 5, 'A Jošua zapovjedi narodu: \"Posvetite se za sutra, jer će sutra Jahve učiniti čudesa među vama.\"');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 3, 6, 'A svećenicima Jošua zapovjedi: \"Dignite Kovčeg saveza i nosite ga pred narodom.\" I digoše Kovčeg saveza i poniješe ga pred narodom.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 3, 7, 'Jahve reče Jošui: \"Danas te počinjem uzvisivati pred očima svega Izraela, neka znaju da sam s tobom kao što bijah s Mojsijem.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 3, 8, 'Ti pak zapovjedi svećenicima koji nose Kovčeg saveza:\' Kada stignete do voda jordanskih, u Jordanu se samom zaustavite.\'\"');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 3, 9, 'Tada reče Jošua Izraelcima: \"Priđite i čujte riječi Jahve, Boga svojega.\"');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 3, 10, 'I reče Jošua: \"Po ovomu ćete spoznati da je među vama Bog živi: on će goniti ispred vas Kanaance, Hetite, Hivijce, Perižane, Girgašane, Amorejce i Jebusejce.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 3, 11, 'Evo, Kovčeg saveza Gospodara sve zemlje proći će pred vama preko Jordana.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 3, 12, 'Izaberite odmah dvanaest ljudi iz plemena Izraelovih, po jednoga iz svakoga plemena.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 3, 13, 'Čim stopala svećenika koji nose Kovčeg Jahve, Gospodara sve zemlje, stupe u Jordan, razdijelit će se voda Jordana, i ona što teče odozgo ustavit će se kao nasip.\'\"');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 3, 14, 'Kad je narod krenuo iz svojih šatora da prijeđe preko Jordana, ponesu svećenici Kovčeg saveza pred njim.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 3, 15, 'A kad su nosači Kovčega stigli do Jordana i kada su svećenici koji su nosili Kovčeg zagazili u vodu na obali - a bilo je vrijeme žetve kad se Jordan prelijeva preko svojih obala -');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 3, 16, 'voda što je tekla odozgo daleko se, poput nasipa, ustavila kod grada Adame, koji se nalazi kraj Sartana; a voda što je otjecala dolje u Arabsko ili Slano more sasvim je otekla i narod je prelazio prema Jerihonu.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 3, 17, 'Svećenici koji su nosili Kovčeg saveza Jahvina stajahu na suhu usred Jordana i prelažaše Izrael po suhu sve dok sav narod ne prijeđe preko rijeke.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 4, 1, 'Pošto je sav narod prešao preko Jordana, reče Jahve Jošui:');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 4, 2, '\"Izaberite iz naroda dvanaest ljudi, od svakoga plemena po jednoga,');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 4, 3, 'i zapovjedite im: \'Dignite odavde, iz sredine Jordana - s mjesta gdje stoje noge svećenika - dvanaest kamenova koje ćete ponijeti sa sobom i položiti na mjestu gdje budete noćas prenoćili.\'\"');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 4, 4, 'Tada pozva Jošua dvanaest ljudi koje je bio izabrao između sinova Izraelovih, iz svakoga plemena po jednoga čovjeka,');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 4, 5, 'i reče im: \"Idite pred Kovčeg Jahve, Boga svoga, u sredinu Jordana, i neka svaki donese na svojim ramenima po jedan kamen prema broju plemena Izraelovih.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 4, 6, 'To će biti na spomen među vama. Kad vas jednoga dana budu pitala vaša djeca: \'Što vam znače ovi kamenovi?\'');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 4, 7, 'reći ćete im: \'Voda se Jordana razdijelila pred Kovčegom saveza Jahvina kad je prelazio preko Jordana.\' I ovo će kamenje biti vječni spomen sinovima Izraelovim.\"');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 4, 8, 'Izraelci učine kako im je zapovjedio Jošua, uzmu dvanaest kamenova iz sredine Jordana, prema broju plemena Izraelovih, kako je Jahve naredio Jošui: prenesu ih do svoga noćišta i polože ondje.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 4, 9, 'Zatim Jošua postavi usred Jordana dvanaest kamenova na mjesta gdje su stajale noge svećenika koji su nosili Kovčeg saveza. Ondje stoje i danas.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 4, 10, 'Svećenici koji su nosili Kovčeg saveza stajali su usred Jordana, sve dok se nije izvršilo sve što je Jahve zapovjedio Jošui da narod izvrši, sasvim onako kao što Mojsije bijaše naredio Jošui. A narod je žurno prelazio.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 4, 11, 'Pošto je sav narod prešao, prijeđu i svećenici s Kovčegom saveza Jahvina i krenu pred narodom.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 4, 12, 'Tada sinovi Rubenovi i sinovi Gadovi i polovina plemena Manašeova u bojnoj opremi stanu na čelo sinova Izraelovih, kao što im bijaše zapovjedio Mojsije.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 4, 13, 'Oko četrdeset tisuća naoružanih ljudi prešlo je pred Jahvom da se bori na Jerihonskim poljanama.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 4, 14, 'Toga dana uzvisi Jahve Jošuu pred svim Izraelom i svi ga se bojahu, kao nekoć Mojsija, u sve dane njegova života.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 4, 15, 'Jahve reče Jošui:');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 4, 16, '\"Zapovjedi svećenicima koji nose Kovčeg saveza neka izađu iz Jordana.\"');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 4, 17, 'Tada Jošua zapovjedi svećenicima: \"Izađite iz Jordana!\"');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 4, 18, 'A čim su svećenici koji su nosili Kovčeg saveza Jahvina izašli isred Jordana i stali nogama na suho, vrate se vode Jordana na svoje mjesto i poteku kao i prije preko svojih obala.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 4, 19, 'Narod je izašao iz Jordana desetog dana prvoga mjeseca. Tada se utaborio u Gilgalu, istočno od Jerihona.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 4, 20, 'A onih dvanaest kamenova što su ih uzeli sa sobom iz Jordana, Jošua postavi u Gilgalu.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 4, 21, 'Tada reče Izraelcima: \"Ako potomci vaši upitaju jednoga dana svoje očeve: \'Što znači ovo kamenje?\' -');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 4, 22, 'vi ih poučite ovako: \'Izrael je ovdje po suhu prešao preko Jordana');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 4, 23, 'jer je Jahve, Bog vaš, osušio pred vama vodu Jordana dok ne prijeđoste, kao što je učinio Jahve, Bog vaš, s Morem crvenim kad ga je osušio pred nama dok ne prijeđosmo.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 4, 24, 'A sve to, da bi znali svi narodi zemlje koliko je moćna ruka Jahvina, i vi sami da se svagda bojite Jahve, Boga svoga.\'\"');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 5, 1, 'Pošto su čuli svi kraljevi amorejski na zapadnoj strani Jordana i svi kraljevi kanaanski koji bijahu uz more da je Jahve osušio Jordan pred Izraelcima dok ne prijeđoše, zastade im srce i nestade im junaštva pred Izraelcima.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 5, 2, 'U to vrijeme Jahve reče Jošui: \"Načini sebi kamene noževe i ponovo obreži Izraelce.\"');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 5, 3, 'Jošua načini sebi kamene noževe i obreza Izraelce na brežuljku Aralotu.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 5, 4, 'A evo zašto ih je Jošua obrezao: sve ljudstvo što je izišlo iz Egipta, sve što mogaše nositi oružje, pomrlo je na putu kroz pustinju.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 5, 5, 'Svi oni bijahu obrezani, ali nije bio obrezan nitko koji se rodio na putu kroz pustinju, poslije izlaska iz Egipta,');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 5, 6, 'jer su četrdeset godina Izraelci lutali pustinjom dok ne pomriješe svi za oružje sposobni koji bijahu izišli iz Egipta; nisu slušali glasa Jahvina te im se Jahve zakleo da njihove oči neće vidjeti zemlju koju je obećao njihovim ocima - zemlju u kojoj teče mlijeko i med.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 5, 7, 'Na njihovo je mjesto podigao sinove njihove i njih je Jošua obrezao: nisu bili obrezani jer se na putu nije obrezivalo.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 5, 8, 'Kad je bio obrezan sav narod, počivali su u taboru sve dok nisu ozdravili.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 5, 9, 'Tada reče Jahve Jošui: \"Danas skidoh s vas sramotu egipatsku.\" I prozva se ono mjesto Gilgal sve do naših dana.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 5, 10, 'Izraelci se, dakle, utaboriše u Gilgalu i ondje na Jerihonskim poljanama proslaviše Pashu uvečer četrnaestoga dana u mjesecu.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 5, 11, 'A sutradan poslije Pashe, upravo toga dana, blagovali su od uroda one zemlje: beskvasna kruha i pržena zrnja.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 5, 12, 'I mÓana je prestala padati čim su počeli jesti plodove zemlje. Tako Izraelci nisu više imali mane, nego su se te godine hranili plodovima zemlje kanaanske.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 5, 13, 'Kad se Jošua približio gradu Jerihonu, podiže oči i ugleda čovjeka kako pred njim stoji s isukanim mačem u ruci. Jošua mu pristupi i upita ga: \"Jesi li ti s nama ili s našim neprijateljima?\"');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 5, 14, 'A on odgovori: \"Ne, ja sam vođa vojske Jahvine i upravo sam došao...\" Tada Jošua pade ničice, pokloni mu se i reče: \"Što zapovijedaš Gospodaru, sluzi svome?\"');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 5, 15, 'A vođa vojske Jahvine odgovori Jošui: \"Skini obuću s nogu svojih, jer je sveto mjesto na kojem stojiš.\" I Jošua učini tako.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 6, 1, 'A Jerihon stajaše silno utvrđen i zatvoren pred sinovima Izraelovim. Nitko nije izlazio niti je tko ulazio.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 6, 2, 'Tada Jahve reče Jošui: \"Evo, predajem ti u ruke Jerihon i kralja njegova s ratnicima.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 6, 3, 'Svi vi ratnici obiđite oko grada jedanput na dan. Tako činite šest dana.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 6, 4, 'A sedam svećenika neka nose pred Kovčegom sedam truba od ovnujskih rogova. Sedmoga dana obiđite sedam puta oko grada, a svećenici neka trube u trublje.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 6, 5, 'Pa kad otežući zatrube u rog ovnujski, neka sav narod, čim čuje glas trube, podigne silnu bojnu viku. I srušit će se gradski bedemi, a narod neka tada ulazi svaki odande gdje se nađe.\"');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 6, 6, 'Jošua, sin Nunov, pozva k sebi svećenike i reče im: \"Uzmite Kovčeg saveza, a sedam svećenika neka ponese sedam truba od rogova ovnujskih pred Kovčegom Jahvinim.\"');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 6, 7, 'A narodu reče: \"Pođite i obiđite oko grada, a ratnici neka idu pred Kovčegom Jahvinim.\"');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 6, 8, 'I bi kako je Jošua zapovjedio narodu. Pođe sedam svećenika noseći trube od rogova ovnujskih: trubili su u rogove, a Kovčeg Jahvin iđaše za njima.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 6, 9, 'Ratnici pođoše pred svećenicima koji su trubili u trube, a zalaznica krenu za Kovčegom. Stupali su tako dok se glas truba razlijegao.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 6, 10, 'A narodu bijaše zapovjedio Jošua govoreći: \"Ne vičite i ne dajte glasa od sebe i nijedna riječ neka se ne čuje iz vaših usta dok vam ne kažem: \'Vičite!\' Tada neka odjekne bojna vika.\"');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 6, 11, 'I naredi da Kovčeg Jahvin obiđe jednom oko grada pa da se vrate u tabor i ondje prenoće.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 6, 12, 'Sutradan urani Jošua, a svećenici ponesu Kovčeg saveza.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 6, 13, 'A sedam svećenika koji su nosili sedam truba od rogova ovnujskih pođu pred Kovčegom Jahvinim. Idući trubili su u trube, ratnici iđahu pred njima, a zalaznica pak za Kovčegom Jahvinim dok su trube odjekivale.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 6, 14, 'Tako i drugog dana obiđu jednom oko grada pa se vrate natrag u tabor. Tako su činili šest dana.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 6, 15, 'A sedmoga dana zorom ustanu i obiđu oko grada istim onakvim redom sedam puta. Samo su toga dana obišli oko grada sedam puta.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 6, 16, 'Za sedmog obilaska snažno zatrube svećenici u rogove, a Jošua reče narodu: \"Kličite bojne poklike jer vam je Jahve predao grad!');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 6, 17, 'Grad neka bude \'herem\' Jahvi - uklet i predan uništenju sa svime što je u njemu. Samo bludnica Rahaba da ostane živa i svi koji budu s njom u kući, jer je ona sakrila uhode koje smo poslali.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 6, 18, 'A čuvajte se svega ukletog u gradu da i sami ne budete prokleti što ste uzeli ukleto, jer biste time navukli prokletstvo na tabor i unesrećili ga.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 6, 19, 'Zato sve srebro i zlato, sve bakreno i željezno posuđe neka bude posvećeno Jahvi i pohranjeno u riznicu.\"');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 6, 20, 'Tada povika narod i odjeknuše trube. Kada se zaori glas truba i bojni povici naroda, padoše bedemi i narod prodrije u grad, svatko odande gdje se našao, i osvojiše ga.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 6, 21, 'I tada izvršiše kletvu ništeći oštricom mača sve što bijaše u gradu: muško i žensko, staro i mlado, volove, ovce i magarad.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 6, 22, 'A onoj dvojici što su uhodili zemlju reče Jošua: \"Idite u kuću one bludnice pa izvedite ženu sa svima njezinima, kako joj se zakleste.\"');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 6, 23, 'I mladi ljudi, uhode, odoše te izvedoše Rahabu, njezina oca i njezinu majku, braću i svu rodbinu. Izvedoše sve njezine i smjestiše ih izvan izraelskog tabora.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 6, 24, 'Spališe grad i sve što bijaše u njemu: uzeše samo srebro, zlato, tučano i željezno posuđe i staviše u riznicu Doma Jahvina.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 6, 25, 'Ali bludnicu Rahabu, svu njenu obitelj i sve njihovo poštedi Jošua. Ona ostade među Izraelcima sve do danas, jer je sakrila glasnike koje je poslao Jošua da uhode Jerihon.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 6, 26, 'Tada izreče Jošua ovu kletvu: \"Proklet bio pred licem Jahve čovjek koji pokuša da ponovo gradi Jerihon: gradio mu temelje na svom prvencu, podizao mu vrata na svome mezimcu!\"');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 6, 27, 'Jahve je bio s Jošuom te se pronio glas o njemu po svoj zemlji.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 7, 1, 'Ali se sinovi Izraelovi teško ogriješiše o \"herem\", jer je Akan, sin Karmija, sina Zabdijeva, sina Zerahova, od plemena Judina, uzeo od ukletih stvari, i Jahve se razgnjevi na sinove Izraelove.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 7, 2, 'Jošua pak posla ljude iz Jerihona u Aj, koji leži istočno od Betela, i reče im: \"Uziđite onamo, izvidite kraj!\" Ljudi odoše te izvidješe Aj.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 7, 3, 'Vrativši se k Jošui, rekoše mu: \"Ne treba da onamo uzlazi sav narod; dvije do tri tisuće ljudi neka idu da osvoje Aj. Ne muči onamo sav narod, jer je ondje malo svijeta.\"');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 7, 4, 'Pođe onamo oko tri tisuće ljudi od svega naroda, ali su morali pobjeći pred onima iz Aja.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 7, 5, 'Ajani pobiše oko trideset i šest ljudi i tjerali su ih ispred svojih vrata do Šebarima: pobili su ih na strmini. Klonu tada srce narodu kao da mu je voda u žilama.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 7, 6, 'Razdrije Jošua haljine svoje i baci se ničice pred Kovčegom Jahvinim, i ostade tako do večeri, on i starješine u Izraelu, posuvši glave pepelom.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 7, 7, 'Tada reče Jošua: \"Jao, Gospode Jahve, zašto si preveo ovaj narod preko Jordana? Da nas predaš u ruke Amorejaca da nas pobiju? Kamo sreće da smo stali s onu stranu Jordana!');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 7, 8, 'Oprosti, Gospode! Što drugo da rečem kad je Izrael okrenuo leđa pred svojim neprijateljima?');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 7, 9, 'Ako to čuju Kanaanci i ostali žitelji zemlje, udružit će se protiv nas da zbrišu ime naše sa zemlje. Što ćeš, dakle, učiniti za veliko ime svoje?\"');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 7, 10, 'A Jahve odgovori Jošui: \"Ustani! Zašto si pao ničice?');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 7, 11, 'Izrael je sagriješio: prekršili su Savez kojim sam ih vezao. Zaista, uzeše ukleto, porobiše, posakrivaše i prisvojiše.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 7, 12, 'I zato Izraelci ne mogu izdržati pred svojim neprijateljima, okreću leđa pred protivnicima jer su postali ukleti. Ja ne mogu više biti s vama ako iz svoje sredine ne maknete proklete.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 7, 13, 'Ustani! Sazovi narod na posvećenje i reci mu: Posvetite se za sutra, jer ovako govori Jahve, Bog Izraelov: \'Kletva je u tebi, Izraele; i nećeš izdržati pred svojim neprijateljima sve dok ne odstranite kletvu iz svoje sredine.\'');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 7, 14, 'Zato sutra zorom pristupite pleme za plemenom; iz plemena koje odredi Jahve prići će rod za rodom, a onda iz roda koji označi Jahve pristupit će obitelj po obitelj, a iz obitelji koju označi Jahve pristupit će čovjek za čovjekom.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 7, 15, 'I tko se tada nađe s ukletom stvari, neka se spali on i sve što mu pripada, jer je prekršio Savez Jahvin i osramotio Izraela.\"');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 7, 16, 'Urani Jošua ujutro i pozva Izraela po plemenima; pristupiše i otkri se pleme Judino.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 7, 17, 'Potom pristupi rod za rodom iz plemena Judina i pronađe se rod Zerahov. Pristupiše obitelji roda Zerahova, domaćin jedan za drugim, i pronađoše obitelj Zabdijevu.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 7, 18, 'Naposljetku naredi Jošua da pristupi obitelj Zabdijeva, muškarac jedan za drugim, i pronašao se Akan, sin Karmija, sina Zabdijeva, sina Zerahova, od plemena Judina.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 7, 19, 'Tada reče Jošua Akanu: \"Sine moj, daj slavu Jahvi, Bogu Izraelovu, i priznaj mu što si učinio; objasni što si učinio i nemoj mi ništa tajiti.\"');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 7, 20, 'Akan reče Jošui: \"Zaista, ja sagriješih Jahvi, Bogu Izraelovu, i evo što sam učinio:');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 7, 21, 'vidjeh u plijenu lijep šinearski plašt, dvije stotine srebrnjaka i zlatnu šipku vrijednu pedeset srebrnjaka, pa se polakomih i uzeh sebi. Eno je sve zakopano usred moga šatora, a srebro je odozdo.\"');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 7, 22, 'Tada uputi Jošua poslanike, koji otrčaše u šator. I gle, sve bijaše zakopano u šatoru, a odozdo srebro.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 7, 23, 'Uzmu sve iz šatora i donesu Jošui i starješinama Izraelovim i prostriješe sve pred Jahvu.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 7, 24, 'Tada uze Jošua Akana, sina Zerahova, i srebro, plašt i zlatnu šipku, i sve sinove i kćeri njegove, volove njegove i magarad, i ovce, šator njegov i sve što bijaše njegovo te ga izvede u dolinu Akor. Pratio ih sav Izrael.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 7, 25, 'Reče Jošua: \"Kako si ti nas unesrećio, tako danas tebe unesrećio Jahve!\" I kamenova ga sav Izrael.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 7, 26, 'Potom navališe na njega gomilu kamenja, koje stoji do danas. Tako se Jahve ublaži od svoga žestoka gnjeva. Zbog toga se događaja prozva ono mjesto dolina Akor i tako se zove do danas.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 8, 1, 'Tada reče Jahve Jošui: \"Ne boj se i ne strahuj! Uzmi sa sobom sve ratnike, ustani i navali na Aj. Gle, predajem ti u ruke ajskoga kralja, njegov narod, grad i zemlju njegovu.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 8, 2, 'Učini s Ajem i s njegovim kraljem kao što si učinio s Jerihonom i njegovim kraljem; ali vam je slobodno da prigrabite plijen iz njega i njegovu stoku. Postavi gradu zasjedu s leđa.\"');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 8, 3, 'Spremi se Jošua da navali na Aj i svi ratnici s njime. Izabrao je trideset tisuća junaka i poslao ih noću;');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 8, 4, 'dade im zapovijed: \"Pazite! Poći ćete u zasjedu gradu s leđa, ali da ne budete predaleko od grada i budite svi spremni.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 8, 5, 'A ja i sav narod koji me prati primaknut ćemo se gradu; i kada ljudi iz Aja izađu pred nas, mi ćemo kao i prije pobjeći ispred njih.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 8, 6, 'Oni će onda navaliti za nama dok ih ne odvedemo od grada jer će misliti: \'Bježe ispred nas kao i prije.\'');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 8, 7, 'Tada provalite iz zasjede i zauzmite grad: Jahve, Bog vaš, predat će vam ga u ruke.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 8, 8, 'Kad jednom osvojite grad, spalite ga ognjem. Učinite to po Jahvinoj zapovijedi. Pazite, to vam zapovjedih.\"');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 8, 9, 'Jošua ih posla i oni odoše u zasjedu te se smjestiše između Betela i Aja, gradu sa zapada. A Jošua provede noć među narodom.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 8, 10, 'Uranivši, Jošua ujutro prebroja narod i pođe sa starješinama Izraelovim pred narodom na Aj.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 8, 11, 'Svi ratnici krenu s njim i kad se primaknu gradu, utabore se Aju sa sjevera, tako da je između njih i mjesta bila ravnica.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 8, 12, 'Jošua uze oko pet tisuća ljudi i namjesti zasjedu između Betela i Aja, gradu sa zapadne strane.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 8, 13, 'A narod se smjesti u tabor, koji je bio na sjeveru grada, dok je njegova zalaznica bila na zapadu grada. Jošua opet provede noć usred naroda.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 8, 14, 'Kad je sve to vidio ajski kralj, požuri se te izađe on i sav njegov narod niz obronak prema Arabi u boj protiv Izraela. A nisu ni slutili da je iza grada namještena zasjeda.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 8, 15, 'Tada Jošua i sav Izrael nagnu bježati kao da su ih pobijedili. I bježali su putem prema pustinji.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 8, 16, 'Ajani nato pozvaše sve iz grada i dadoše se za njima u potjeru te, goneći Jošuu, odvoje se od grada.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 8, 17, 'I ne ostade nitko u Aju i Betelu da nije pošao za Izraelcima. Ostavili su grad otvoren i gonili Izraelce.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 8, 18, 'Tada reče Jahve Jošui: \"Zamahni kopljem što ti je u ruci prema Aju: predajem ti ga u ruke.\" I podiže Jošua koplje što mu bješe u ruci i zamahnu prema gradu.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 8, 19, 'I tek što je podigao ruku, dignu se ljudi iz zasjede i potrče prema gradu, osvoje ga i umah ga ognjem zapale.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 8, 20, 'Kada se oni iz Aja obazreše, imadoše što vidjeti: dim se dizao iz grada prema nebu. I nitko od njih nije imao kuda uteći ni tamo ni amo. Tada se narod koji je bježao prema pustinji okrenuo prema progoniteljima.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 8, 21, 'Vidjevši Jošua i sav Izrael da je zasjeda zauzela grad i da se diže dim iz grada, vrate se i udare na ljude iz Aja.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 8, 22, 'Njihovi su im izašli u susret iz grada, i tako se oni iz Aja nađoše posred Izraelaca, opkoljeni i s jedne i s druge strane: biše pobijeni tako te ni jedan ne ostade živ niti uteče.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 8, 23, 'A kralja Aja uhvatiše živa i dovedoše ga Jošui.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 8, 24, 'Kad su Izraelci pobili sve stanovnike Aja na otvorenu polju i u pustinji, kuda su ih gonili, i kada svi padoše od mača, vratiše se Izraelci u Aj i sasjekoše mačem sve što bješe u njemu.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 8, 25, 'Bilo je dvanaest tisuća onih koji su izginuli toga dana, ljudi i žena - sav Aj.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 8, 26, 'Jošua nije spuštao ruke kojom bijaše zamahnuo kopljem sve dok nisu poubijani svi stanovnici Aja.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 8, 27, 'Samo stoku i plijen iz onoga grada razdijele među sobom Izraelci, kao što je Jahve zapovjedio Jošui.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 8, 28, 'Jošua spali Aj i učini ga za sve vijeke ruševinom, pustim mjestom do danas.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 8, 29, 'Kralja ajskoga objesi o drvo do večeri. O zapadu sunčanom zapovjedi Jošua te skinuše truplo s drveta, baciše ga pred gradska vrata i nabacaše na nj veliku gomilu kamenja, koja stoji i danas.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 8, 30, 'Tada podiže Jošua žrtvenik Jahvi, Bogu Izraelovu, na gori Ebalu,');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 8, 31, 'kao što je zapovjedio Mojsije, sluga Jahvin, svim sinovima Izraelovim i kako je napisano u Mojsijevoj knjizi Zakona: žrtvenik od grubog kamena, neklesanog željezom. Na njemu bi prinesena Jahvi žrtva paljenica i pričesnica.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 8, 32, 'Tu na kamenju Jošua prepiše Zakon Mojsijev koji bješe napisan za sinove Izraelove.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 8, 33, 'I sav Izrael i njegove starješine, glavari narodni i suci, došljaci i domaći, stanu s obje strane Kovčega prema svećenicima i levitima koji su nosili Kovčeg saveza Jahvina - polovina prema gori Gerizimu, a polovina prema gori Ebalu - da bi se blagoslovio puk Izraelov prema obredu koji zapovjedi Mojsije.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 8, 34, 'Tada pročita Jošua svaku riječ Zakona, blagoslov i prokletstvo, sve kako je napisano u knjizi Zakona.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 8, 35, 'Nije Jošua propustio nijedne Mojsijeve naredbe, nego ih je sve pročitao pred saborom svih Izraelaca, pred ženama, djecom i došljacima koji su išli s njima.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 9, 1, 'O tim su događajima čuli svi kraljevi s onu stranu Jordana - u Gorju, u Šefeli i duž čitave obale Velikoga mora sve do Libanona: Hetiti, Amorejci, Kanaanci, Perižani, Hivijci, Jebusejci -');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 9, 2, 'pa se svi udružiše da složno udare protiv Jošue i Izraela.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 9, 3, 'A stanovnici Gibeona, poučeni onim što Jošua učini Jerihonu i Aju,');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 9, 4, 'dosjete se lukavstvu. Uzmu hiniti da su putnici: bace na svoje magarce stare vreće i vinske mješine, poderane i zakrpane.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 9, 5, 'Obuli su na noge rabljenu i pokrpanu obuću i vrgli na se staru odjeću. Sav kruh što su ga ponijeli na put bijaše suh i razdrobljen.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 9, 6, 'Stigoše Jošui u gilgalski tabor i rekoše njemu i ljudima Izraelcima: \"Dolazimo iz daleke zemlje, sklopite savez s nama.\"');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 9, 7, 'Ali ljudi Izraelci kažu tim Hivijcima: \"Tko zna ne živite li možda među nama? Kako ćemo, dakle, sklopiti savez s vama?\"');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 9, 8, 'A oni odgovore Jošui: \"Tvoje smo sluge!\" Jošua ih upita: \"Tko ste i odakle dolazite?\"');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 9, 9, 'Odgovore: \"Daleka je zemlja iz koje dolaze tvoje sluge u ime Jahve, Boga tvojega: čuli smo za slavu njegovu i za sve što je učinio u Egiptu');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 9, 10, 'i za ono što je učinio dvojici kraljeva amorejskih koji su vladali s onu stranu Jordana - Sihonu, kralju hešbonskom, i Ogu, kralju bašanskom u Aštarotu.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 9, 11, 'Tada nam rekoše naše starješine i svi u našoj zemlji: \'Opskrbite se hranom za put, pođite im u susret i recite im: Vaše smo sluge, sklopite dakle savez s nama.\'');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 9, 12, 'Evo našega kruha: vruć smo ponijeli na put od kuća svojih kada smo krenuli k vama, a sada je, evo, suh i razdrobljen.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 9, 13, 'A ovo su vinski mjehovi: nove smo ih nalili, pa su se, evo, već poderali; i haljine naše i obuća već su trošni od dalekog puta.\"');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 9, 14, 'I povjerovaše im ljudi po putnoj opskrbi, ne pitajući Jahvu što će im reći.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 9, 15, 'Jošua uglavi s njima mir i sklopi savez s njima da će ih poštedjeti. I glavari se na to zakunu.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 9, 16, 'A poslije tri dana, pošto su sklopili s njima savez, saznalo se da su im susjedi i da žive usred Izraela.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 9, 17, 'Tada krenu Izraelci iz tabora i stignu u njihove gradove, a to su bili Gibeon, Kefira, Beerot i Kirjat Jearim.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 9, 18, 'Ali ih nisu napali sinovi Izraelovi, jer su im se glavari zajednice zakleli Jahvom, Bogom Izraelovim. Ali sva zajednica poče rogoboriti protiv glavara.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 9, 19, 'Tada svi glavari rekoše zajednici: \"Mi smo im se zakleli Jahvom, Bogom Izraelovim, i zato ih ne smijemo dirati.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 9, 20, 'Evo što ćemo: pustimo ih da žive, kako nas ne bi stigla srdžba zbog zakletve kojom smo se zakleli.\"');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 9, 21, 'Još dometnuše glavari: \"Neka žive i neka budu drvosječe i vodonoše svoj zajednici.\" Sva zajednica prihvati što rekoše glavari.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 9, 22, 'Jošua pozva Gibeonce i reče im: \"Zašto nas prevariste govoreći: \'Vrlo smo daleko od vas\', kad eto živite usred nas?');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 9, 23, 'Zato će sada na vama biti kletva i nikada neće nestati među vama ropstva: bit ćete drvosječe i vodonoše za Dom Boga moga.\"');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 9, 24, 'Oni odgovore Jošui: \"Sa svih strana dolazili su glasovi nama, slugama tvojim, kako je Jahve, Bog tvoj, odredio Mojsiju, sluzi svomu, da će vam dati svu zemlju i da će istrijebiti ispred vas sve stanovnike ove zemlje; silno smo se uplašili od vas za svoje živote i zato smo učinili ovo.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 9, 25, 'I sada smo, evo, u tvojim rukama: učini s nama što misliš da je dobro i pravo.\"');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 9, 26, 'A on im je učinio ovako: izbavio ih iz ruku sinova Izraelovih te ih nisu pobili.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 9, 27, 'I od toga dana naredi im Jošua da sijeku drva i nose vodu, sve do danas, za zajednicu i za žrtvenik Jahvin na mjestu koje se god izabere.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 10, 1, 'A kad ču jeruzalemski kralj Adoni-Sedek da je Jošua zauzeo Aj i da ga je izručio \"heremu\", kletom uništenju, kao što je učinio s Jerihonom i njegovim kraljem, i da su stanovnici Gibeona učinili mir s Izraelom i uključili se među njih,');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 10, 2, 'vrlo se uplaši, jer je Gibeon bio značajan kao kakav kraljevski grad, veći od Aja, a svi žitelji njegovi bijahu ratnici.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 10, 3, 'Zato jeruzalemski kralj Adoni-Sedek poruči Hohamu, kralju hebronskom, Piramu, kralju jarmutskom, Jafiji, kralju lakiškom, i Debiru, kralju eglonskom:');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 10, 4, '\"Dođite k meni i pomozite mi da udarimo na Gibeon, jer je učinio mir s Jošuom i Izraelcima!\"');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 10, 5, 'Udruži se tada pet kraljeva amorejskih: kralj jeruzalemski, kralj hebronski, kralj jarmutski, kralj lakiški i kralj eglonski; krenu oni i sva njihova vojska, opsjednu grad Gibeon i počnu ga napadati.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 10, 6, 'Tada Gibeonci poručiše Jošui u tabor u Gilgalu: \"Ne napuštaj svojih slugu, nego se požuri k nama da nas izbaviš i da nam pomogneš, jer su se protiv nas udružili svi amorejski kraljevi koji žive u Gorju.\"');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 10, 7, 'I pođe Jošua iz Gilgala, a s njim i svi ratnici, sve vrsni junaci.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 10, 8, 'A Jahve reče Jošui: \"Ne boj se! Ja sam ih predao u tvoje ruke i nijedan od njih neće se održati pred tobom.\"');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 10, 9, 'I udari na njih Jošua iznenadno, pošto je svu noć išao od Gilgala.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 10, 10, 'I smete ih Jahve pred Izraelcima, koji ih teško poraziše kod Gibeona i potjeraše prema strmini kojom se uzlazi u Bet-Horon. Tukli su ih sve do Azeke i do Makede.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 10, 11, 'A dok su bježali pred Izraelom uz bethoronsku strminu, bacao je Jahve s neba na njih tuču kamenja sve do Azeke te su ginuli. I poginulo ih je više od tuče kamene nego što su ih pobili sinovi Izraelovi svojim mačevima.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 10, 12, 'Onoga dana kada Jahve predade Amorejce sinovima Izraelovim, obrati se Jošua Jahvi i poviče pred Izraelcima: \"Stani, sunce, iznad Gibeona, i mjeseče, iznad dola Ajalona!\"');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 10, 13, 'I stade sunce i zaustavi se mjesec sve dok se nije narod osvetio neprijateljima svojim. Ne piše li to u knjizi Pravednika? I stade sunce nasred neba i nije se nagnulo k zapadu gotovo cio dan.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 10, 14, 'Nije bilo takva dana ni prije ni poslije da bi se Jahve odazvao glasu čovječjem. Tako je Jahve vojevao za Izraela.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 10, 15, 'Potom se vrati Jošua i sav Izrael s njim u tabor gilgalski.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 10, 16, 'A onih pet kraljeva uteče i sakri se u pećinu kod Makede.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 10, 17, 'Javiše Jošui: \"Otkriveno je pet kraljeva sakrivenih u pećini kod Makede.\"');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 10, 18, 'A Jošua reče: \"Navalite veliko kamenje pećini na otvor i postavite ljude pred nju da je čuvaju.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 10, 19, 'A vi se drugi ne zadržavajte, nego tjerajte svoje neprijatelje i tucite ih s leđa; ne dajte im da uđu u svoje gradove, jer ih Jahve, Bog vaš, predade u vaše ruke.\"');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 10, 20, 'A kad Jošua i sinovi Izraelovi okončaše bitku teškim pokoljem - utekla im je samo nekolicina preživjelih u tvrde gradove -');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 10, 21, 'vrati se narod zdrav i čitav k Jošui u tabor u Makedi. I nitko više ni da pisne protiv sinova Izraelovih.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 10, 22, 'Tada reče Jošua: \"Otvorite ulaz u pećinu i odande mi izvedite onih pet kraljeva.\"');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 10, 23, 'I učine tako, izvedu k njemu iz pećine onih pet kraljeva: kralja jeruzalemskoga, kralja hebronskoga, kralja jarmutskoga, kralja lakiškog i kralja eglonskog.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 10, 24, 'A kad ih izvedoše, pozva Jošua sve Izraelce i reče vojskovođama koji su ga pratili: \"Priđite i stanite svojim nogama na vratove ovih kraljeva.\" Oni pristupe i stanu im svojim nogama na vratove.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 10, 25, 'Reče Jošua: \"Ne bojte se i ne plašite se! Hrabri budite i odlučni, jer će tako Jahve učiniti sa svim vašim neprijateljima s kojima se budete borili.\"');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 10, 26, 'Potom Jošua naredi da ih pogube i objese na pet stabala; i visjeli su ondje do večeri.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 10, 27, 'A o zalasku sunčanom zapovjedi Jošua te ih skidoše s drveća i baciše u istu onu pećinu u koju se bijahu sklonili te na otvor navališe golemo kamenje, koje je i danas ondje.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 10, 28, 'Istoga dana zauze Jošua Makedu: udari na grad oštricom mača i pogubi kralja njegova i sve živo u gradu izruči \"heremu\", kletom uništenju, ne puštajući da itko utekne. I učini s kraljem makedskim kao što je učinio s kraljem jerihonskim.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 10, 29, 'Ode zatim Jošua i sav Izrael iz Makede u Libnu i udari na nju.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 10, 30, 'I nju Jahve i njena kralja predade u ruke Izraelu, koji oštricom mača pobi sve živo u njoj; ne poštedje nikoga, a s kraljem Libne učini što i s kraljem jerihonskim.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 10, 31, 'Potom ode Jošua i svi Izraelci iz Libne u Lakiš, opsjede ga i napade.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 10, 32, 'Jahve predade Lakiš u ruke Izraela, koji ga osvoji sutradan: pobiše oštricom mača sve živo u njemu, onako kao što su učinili s Libnom.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 10, 33, 'Tada ustade Horam, kralj Gezera, da pomogne Lakišu, ali Jošua porazi njega i njegov narod tako te nitko ne preživje.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 10, 34, 'Jošua krenu zatim sa svim Izraelcima od Lakiša na Eglon. Opsjedoše grad i napadoše ga.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 10, 35, 'Osvojiše ga još istoga dana i pobiše sve oštricom mača. Sve živo izručiše kletom uništenju, kako su učinili s Lakišem.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 10, 36, 'Onda Jošua sa svim Izraelom krenu od Eglona na Hebron i napade ga.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 10, 37, 'Osvojiše ga i pobiše sve oštricom mača, kralja i stanovništvo u svim mjestima koja mu pripadaju, ne poštedjevši nikoga. Učini s njime kao s Eglonom. Grad sa svim svojim stanovništvom bi izručen kletom uništenju.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 10, 38, 'Napokon krenu Jošua i sav Izrael s njim na Debir i napadoše ga.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 10, 39, 'Osvojiše ga i razoriše; kralja njegova i žitelje okolnih mjesta pobiše oštricom mača. Kletom uništenju izručiše sve njegovo stanovništvo. Ne poštedješe nikoga. I učini Jošua s Debirom i njegovim kraljem kao što je učinio s Hebronom i njegovim kraljem, s Libnom i njezinim kraljem.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 10, 40, 'Tako je Jošua zauzeo sav onaj kraj: Gorje i Negeb, Šefelu i Visočje - i sve njihove kraljeve. Ne ostavi preživjelih, već izruči kletom uništenju sve što je disalo, kako je zapovjedio Jahve, Bog Izraelov.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 10, 41, 'I pobi ih Jošua sve od Kadeš Barnee do Gaze i sav kraj Gošen do Gibeona.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 10, 42, 'Sve tamošnje kraljeve i zemlje njihove zauze Jošua ujedanput, jer se za Izraela borio Jahve, Bog Izraelov.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 10, 43, 'Naposljetku se Jošua i sav Izrael vratiše u tabor u Gilgalu.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 11, 1, 'Kad je sve to čuo Jabin, kralj od Hasora, obavijesti Jobaba, kralja od Madona, i kralja od Šimrona, i kralja od Akšafa,');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 11, 2, 'i kraljeve na sjeveru, u Gorju, i u Arabi južno od Kinereta, i u Šefeli, i na uzvišicama Dora prema moru;');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 11, 3, 'Kanaance na istoku i zapadu, Amorejce, Hetite, Perižane i Jebusejce u planinama, Hivijce pod Hermonom u zemlji Mispi.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 11, 4, 'Svi oni izađu sa svim svojim četama, s mnoštvom što ga bijaše kao pijeska na obali morskoj i s mnogim konjima i kolima.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 11, 5, 'Udruže se, dakle, svi ti kraljevi i utabore se zajedno na vodama Meroma da se bore protiv Izraela.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 11, 6, 'Tada Jahve reče Jošui: \"Ne boj se njih, jer ću sutra u ovo doba učiniti te će svi biti pobijeni pred Izraelom; konje njihove osakati, a bojna im kola ognjem spali.\"');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 11, 7, 'Jošua povede na njih sve svoje ratnike, iznenada ih napade na vodama Meroma i udari na njih.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 11, 8, 'I Jahve ih dade u ruke Izraelcima te ih oni pobiše i protjeraše sve do Velikog Sidona i do Misrefot Majima i do ravnice Mispe na istoku; i poraziše ih tako te nitko ne preživje.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 11, 9, 'Jošua učini kako mu je Jahve zapovjedio: konje im osakati, a kola im ognjem spali.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 11, 10, 'U to se vrijeme vrati Jošua i zauze Hasor, a njegova kralja pogubi mačem. Hasor je nekoć bio glavni grad svima tim kraljevstvima.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 11, 11, 'Pobili su sve oštricom mača, izvršujući \"herem\", kletvu. Ne ostade ništa živo, a Hasor spališe ognjem.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 11, 12, 'Sve gradove onih kraljeva pokori Jošua i pobi kraljeve oštricom mača, izvršujući \"herem\", kletvu, kao što je bio zapovjedio Mojsije, sluga Jahvin.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 11, 13, 'Od ostalih gradova koji se dizahu na svojim brežuljcima Izraelci nisu spalili ni jednoga, osim Hasora, koji spali Jošua.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 11, 14, 'Sav plijen iz tih gradova i stoku razdijeliše sinovi Izraelovi među sobom, a sve ljude pobiše oštricom mača, istrijebiše ih i ni žive duše ne ostade.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 11, 15, 'Sve što Jahve bijaše zapovjedio svome sluzi Mojsiju, zapovjedio je Mojsije Jošui, a Jošua sve izvršio, ne izostavivši ništa od svega što Jahve bijaše zapovjedio Mojsiju.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 11, 16, 'Tako je Jošua zauzeo svu zemlju: Gorje, sav Negeb i svu zemlju Gošen, Šefelu, Arabu, Izraelsko gorje i njegove brežuljke,');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 11, 17, 'od gore Halaka, koja se diže prema Seiru, pa do Baal Gada, u ravnici libanonskoj pod gorom Hermonom; zarobio je sve njihove kraljeve, pobio ih i pogubio.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 11, 18, 'Dugo je vremena ratovao Jošua s tim kraljevima.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 11, 19, 'Nije bilo ni jednoga grada koji je sklopio mir s sinovima Izraelovim, osim Hivijaca, koji su živjeli u Gibeonu: sve ih zauzeše ratom.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 11, 20, 'Jahve im bijaše otvrdnuo srca te su izašli u boj protiv Izraela i pali pod \"herem\", kletvu bez smilovanja, da budu istrijebljeni, kako je to Jahve bio zapovjedio Mojsiju.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 11, 21, 'U ono vrijeme dođe Jošua i istrijebi Anakovce iz Gorja, iz Hebrona, iz Debira, iz Anaba, iz svega gorja Judina i iz svega gorja Izraelova: predade ih \"heremu\", uništenju, njih i sve njihove gradove.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 11, 22, 'Tako ne ostade nijedan Anakovac u svoj zemlji sinova Izraelovih, osim u Gazi, u Gatu i Ašdodu.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 11, 23, 'Jošua zauze svu zemlju, kao što je Jahve bio rekao Mojsiju, i dade je u baštinu Izraelu podijelivši je po plemenima. I konačno zemlja počinu od rata.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 12, 1, 'Ovo su zemaljski kraljevi što su ih pobijedili Izraelci i osvojili njihovu zemlju s onu stranu Jordana k istoku, od potoka Arnona do gore Hermona, sa svom Arabom na istoku:');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 12, 2, 'Sihon, kralj amorejski, koji je stolovao u Hešbonu; njegovo se kraljevstvo protezalo od Aroera, koji leži na rubu doline potoka Arnona, sredinom doline i polovinom Gileada pa do potoka Jaboka, gdje je graničilo s Amoncima;');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 12, 3, 'i na istoku mu bila Araba do Keneretskog mora s jedne strane i sve do Arabskog ili Slanog mora prema Bet Haješimotu; i dalje na jugu do obronaka Pisge.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 12, 4, 'Međašio s njime Og, kralj bašanski, jedan od posljednjih Refaimaca; stolovao je u Aštarotu i Edreju.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 12, 5, 'A vladao je gorom Hermonom i Salkom, čitavim Bašanom sve do gešurske i maakadske međe te drugom polovinom Gileada sve do granice Sihona, kralja hešbonskoga.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 12, 6, 'Mojsije, sluga Jahvin, i sinovi Izraelovi sve su ih pobili i predao je Mojsije, sluga Jahvin, tu zemlju u posjed plemenu Rubenovu i Gadovu plemenu te polovini plemena Manašeova.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 12, 7, 'A ovo su zemaljski kraljevi što su ih pobijedili Jošua i sinovi Izraelovi s ovu stranu Jordana k zapadu, od Baal Gada u libanonskoj ravnici pa do gore Halaka, koja se diže prema Seiru, a tu je zemlju Jošua dao u baštinu plemenima Izraelovim prema njihovim dijelovima,');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 12, 8, 'u Gorju, u Šefeli, u Arabi i po obroncima, u Pustinji te u Negebu: zemlju hetitsku, amorejsku i kanaansku, perižansku, hivijsku i jebusejsku:');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 12, 9, 'jerihonski kralj, jedan; kralj Aja kod Betela, jedan;');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 12, 10, 'jeruzalemski kralj, jedan; hebronski kralj, jedan;');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 12, 11, 'jarmutski kralj, jedan; lakiški kralj, jedan;');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 12, 12, 'eglonski kralj, jedan; gezerski kralj, jedan;');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 12, 13, 'debirski kralj, jedan; gederski kralj, jedan;');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 12, 14, 'hormski kralj, jedan; aradski kralj, jedan;');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 12, 15, 'kralj Libne, jedan; adulamski kralj, jedan;');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 12, 16, 'makedski kralj, jedan; betelski kralj, jedan;');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 12, 17, 'kralj Tapuaha, jedan; heferski kralj, jedan;');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 12, 18, 'afečki kralj, jedan; šaronski kralj, jedan;');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 12, 19, 'madonski kralj, jedan; hasorski kralj, jedan;');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 12, 20, 'šimron-meronski kralj, jedan; ahšafski kralj, jedan;');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 12, 21, 'tanaački kralj, jedan; megidski kralj, jedan;');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 12, 22, 'kedeški kralj, jedan; kralj Jokneama na Karmelu, jedan;');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 12, 23, 'dorski kralj u pokrajini dorskoj, jedan; gojski kralj u Gilgalu, jedan;');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 12, 24, 'tirški kralj, jedan. U svemu trideset i jedan kralj.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 13, 1, 'Kad je Jošua ostario i odmakao u svojim godinama, reče mu Jahve: \"Već si star i vremešan, a ostalo je mnogo zemlje da se osvoji.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 13, 2, 'Evo područja što još preostaju: sve pokrajine filistejske i sva zemlja gešurska;');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 13, 3, 'od Šihora, što je pred Egiptom, sve do granice Ekrona na sjeveru, a računa se kao područje Kanaanaca; pet kneževina filistejskih: Gaza, Ašdod, Aškelon, Git i Ekron; zatim Avijci');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 13, 4, 'na jugu. Sva zemlja kanaanska od Are koja pripada Sidoncima, pa do Afeka i do međe amorejske;');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 13, 5, 'onda zemlja Giblijaca i sav Libanon prema istoku, od Baal Gada u podnožju gore Hermona do Lebo Hamata.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 13, 6, 'Sve stanovnike gorja, od Libanona do Misrefota na zapadu - sve Sidonce otjerat ću ispred sinova Izraelovih. Samo razdijeli Izraelu zemlju u baštinu, kao što sam ti zapovjedio.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 13, 7, 'Razdijeli, dakle, tu zemlju u baštinu među devet plemena i polovinu plemena Manašeova.\"');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 13, 8, 'Druga polovina plemena Manašeova, a s njome pleme Rubenovo i Gadovo, primiše svoju baštinu koju im je predao Mojsije preko Jordana, na istoku. Mojsije, sluga Jahvin, dodijelio im je ovako:');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 13, 9, 'od Aroera, koji se nalazi uz obalu potoka Arnona, i od grada usred doline, svu visoravan od Medebe do Dibona;');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 13, 10, 'sve gradove Sihona, kralja amorejskoga, koji je vladao u Hešbonu, sve do međe sinova Amonovih;');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 13, 11, 'i Gilead, i krajinu gešursku i maakansku sa svom gorom Hermonom, i sav Bašan do Salke;');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 13, 12, 'a u Bašanu sve kraljevstvo Oga, koji je vladao u Aštarotu i Edreju i bio posljednji potomak Refaima. Mojsije ih je pobijedio i protjerao.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 13, 13, 'Ali sinovi Izraelovi nisu protjerali Gešurce i Maakance, pa tako ostadoše Gešurci i Maakanci usred Izraela sve do današnjega dana.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 13, 14, 'Samo plemenu Levijevu ne dade baštine: Jahve, Bog Izraelov, njegova je baština, kao što je rekao.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 13, 15, 'Mojsije dade plemenu sinova Rubenovih dijelove po njihovim porodicama.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 13, 16, 'Primili su zemlju od Aroera, koji leži uz obalu potoka Arnona, i od grada koji je u sredini doline i svu visoravan kod Medebe;');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 13, 17, 'Hešbon sa svim njegovim gradovima koji leže na visoravni: Dibon, Bamot Baal, Bet Baal Meon;');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 13, 18, 'Jahas, Kedemot, Mefaat;');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 13, 19, 'Kirjatajim, Sibmu i Seret Hašahar na gori iznad doline;');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 13, 20, 'Bet Peor, Ašdot Hapisgu, Bet Haješimot;');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 13, 21, 'sve gradove na visoravni i sve kraljevstvo Sihona, amorejskog kralja, koji je vladao u Hešbonu. Mojsije ga je pobijedio kao i knezove midjanske: Avija, Rekema, Sura, Hura, Reba, podanike Sihonove, koji su živjeli u toj zemlji;');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 13, 22, 'i vrača Bileama, sina Beorova, ubili su sinovi Izraelovi oštricom mača s ostalim žrtvama.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 13, 23, 'Međa sinova Rubenovih bijaše Jordan. To je bila baština sinova Rubenovih po njihovim porodicama: gradovi i sela njihova.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 13, 24, 'Onda dade Mojsije plemenu Gadovu, sinovima Gadovim, dijelove po porodicama njihovim.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 13, 25, 'Primili su u posjed: Jazer i sve gradove gileadske, polovinu zemlje sinova Amonovih sve do Aroera, nasuprot Rabi,');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 13, 26, 'i od Hešbona do Ramat Hamispe i Betonima, i od Mahanajima do pokrajine Lo-Debar;');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 13, 27, 'a u dolini: Bet Haram, Bet Nimru, Sukot i Safon, to jest ostatak kraljevstva Sihona, kralja hešbonskoga; Jordan s obalom sve do kraja Kineretskoga mora, na istočnoj strani Jordana.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 13, 28, 'To je baština sinova Gadovih, po njihovim porodicama, gradovi i sela njihova.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 13, 29, 'Mojsije je dao dio polovini plemena Manašeova po njegovim porodicama.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 13, 30, 'Dobili su u posjed zemlju od Mahanajima, sav Bašan, sve kraljevstvo Oga, kralja bašanskoga, i sva Sela Jairova što su u Bašanu - šezdeset gradova.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 13, 31, 'A polovina Gileada, Aštarot i Edrej, gradovi kraljevstva Ogova u Bašanu, pripali su sinovima Makira, sina Manašeova, i to polovini sinova Makirovih po njihovim porodicama.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 13, 32, 'Tako je Mojsije bio podijelio baštine na Moapskim poljanama, s druge strane Jordana, istočno od Jerihona.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 13, 33, 'Levijevu plemenu ne dade Mojsije baštine: Jahve, Bog Izraelov, njihova je baština, kao što im je sam rekao.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 14, 1, 'Ovo je što su dobili u baštinu sinovi Izraelovi u zemlji kanaanskoj - što su im razdijelili u baštinu svećenik Eleazar i Jošua, sin Nunov, i glavari porodica izraelskih plemena.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 14, 2, 'Ždrijebom su razdijelili baštinu, kao što je Jahve odredio preko Mojsija, među devet plemena i polovinu desetoga plemena.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 14, 3, 'Mojsije je odredio baštinu dvama plemenima i polovini desetog plemena s onu stranu Jordana, a levitima nije dao baštine među njima.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 14, 4, 'Jer bijahu dva plemena sinova Josipovih: Manašeovo i Efrajimovo. A levitima nisu dali dijela u zemlji nego gradove za prebivanje i pašnjake za njihovu stoku i za blago njihovo.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 14, 5, 'Kako je Jahve zapovjedio Mojsiju, tako su učinili sinovi Izraelovi pri diobi zemlje.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 14, 6, 'Sinovi Judini pristupe k Jošui u Gilgalu, a Kaleb, sin Jefuneov, Kenižanin, reče mu: \"Ti znaš što je Jahve rekao Mojsiju, čovjeku Božjem, za mene i za tebe u Kadeš Barnei.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 14, 7, 'Bilo mi je četrdeset godina kad me posla Mojsije, sluga Jahvin, iz Kadeš Barnee da uhodim zemlju. I donio sam mu izvješće kako sam najbolje znao.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 14, 8, 'Braća koja su pošla sa mnom uplašila su srce naroda, ali sam ja vršio volju Jahve, Boga svojega.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 14, 9, 'I onoga se dana zakle Mojsije: \'Zemlja kojom je stupala noga tvoja pripast će tebi i sinovima tvojim u vječnu baštinu, jer si vršio volju Jahve, Boga mojega.\'');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 14, 10, 'I vidiš, Jahve me sačuvao u životu, kao što je rekao. Već je prošlo četrdeset i pet godina kako je Jahve to obećao Mojsiju, dok je Izrael još išao pustinjom; sada mi je osamdeset i pet godina,');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 14, 11, 'ali sam još i danas snažan kao što sam bio onoga dana kad me Mojsije poslao kao uhodu. Kao nekoć, i sada je moja snaga u meni, za borbu, da odem i da se vratim.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 14, 12, 'Daj mi sada ovo gorje, koje mi je Jahve obećao onoga dana. Sam si čuo onoga dana. Ondje su Anakovci, a i gradovi su im veliki i tvrdi. Ako je Jahve sa mnom, protjerat ću ih, kako je to obećao Jahve.\"');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 14, 13, 'Tada ga Jošua blagoslovi i dade Kalebu, sinu Jefuneovu, Hebron u baštinu.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 14, 14, 'Hebron je pripao u baštinu Kalebu, sinu Jefuneovu, Kenižaninu, sve do danas, jer je Kaleb vršio volju Jahve, Boga Izraelova.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 14, 15, 'Hebron se prije zvao Kirjat Arba; a Arba bijaše velik čovjek među Anakovcima. I počinu zemlja od rata.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 15, 1, 'Dio što je pripao plemenu sinova Judinih, po njihovim porodicama, bijaše prema granici edomskoj, na jug do Sinske pustinje, na krajnjem jugu.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 15, 2, 'A južna im međa išla od kraja Slanoga mora od zaljeva što je na jugu;');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 15, 3, 'izlazila je onda južno od Akrabimskog uspona, pružala se preko Sina i uzlazila južno od Kadeš Barnee, prelazila Hesron, penjala se k Adari i odatle okretala prema Karkai,');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 15, 4, 'potom prelazila Asmon i dopirala do Potoka egipatskog i najposlije izbijala na more. To vam je južna međa.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 15, 5, 'Na istoku je međa bila: Slano more do ušća Jordana. Sjeverna je međa počinjala od Slanog mora kod ušća Jordana.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 15, 6, 'Odatle je međa uzlazila u Bet-Hoglu, tekla sjeverno uz Bet-Arabu, išla gore na Kamen Bohana, sina Rubenova.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 15, 7, 'Međa se zatim dizala od Akorske doline prema Debiru, okretala na sjever prema Gelilotu, koji leži naprama Adumimskom usponu, južno od Potoka; dalje je međa prolazila prema vodama En-Šemeša te izlazila kod En-Rogela.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 15, 8, 'Odatle se preko doline Ben-Hinom s juga dizala k Jebusejskom obronku, to jest k Jeruzalemu. Potom se uspinjala na vrh gore koja prema zapadu gleda na dolinu Hinon i leži na sjevernom kraju doline Refaima.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 15, 9, 'S vrha te gore zavijala je međa na izvor Neftoah te izlazila prema gradovima u gori Efronu da zatim okrene k Baali, to jest Kirjat Jearimu.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 15, 10, 'Od Baale međa je okretala na zapad prema gori Seiru i onda, prolazeći sjeverno od gore Jearima, to jest Kesalona, spuštala se u Bet-Šemeš te išla k Timni.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 15, 11, 'Dalje je međa tekla k sjevernom obronku Ekrona, okretala prema Šikronu, prelazila visove Baale, pružala se do Jabneela da konačno izbije na more.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 15, 12, 'Zapadna je međa Veliko more s obalom. To su bile zemlje sinova Judinih, unaokolo, po porodicama njihovim.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 15, 13, 'Kaleb, sin Jefuneov, primi dio među sinovima Judinim, kako je Jahve naredio Jošui. Dao mu je Kirjat Arbu, glavni grad sinova Anakovih - Hebron.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 15, 14, 'Kaleb protjera odatle tri sina Anakova: Šešaja, Ahimana i Talmaja, potomke Anakove.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 15, 15, 'Odatle krenu na stanovnike Debira, koji se nekoć zvao Kirjat Sefer.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 15, 16, 'Tada reče Kaleb: \"Tko pokori i zauzme Kirjat Sefer, dat ću mu svoju kćer Aksu za ženu.\"');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 15, 17, 'Zauze ga Otniel, sin Kenaza, brata Kalebova; i dade mu Kaleb svoju kćer Aksu za ženu.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 15, 18, 'Kad je prišla mužu, on je nagovori da u svoga oca zatraži polje. Ona siđe s magarca, a Kaleb je upita: \"Šta hoćeš?\"');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 15, 19, 'Ona odgovori: \"Daj mi blagoslov! Kad si mi dao kraj u Negebu, daj mi i koji izvor vode.\" I on joj dade Gornje i Donje izvore.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 15, 20, 'To je bila baština plemena sinova Judinih po porodicama njihovim.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 15, 21, 'Međašni su gradovi plemena sinova Judinih, duž edomske međe prema jugu, bili: Kabseel, Eder, Jagur;');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 15, 22, 'Kina, Dimona, Adada;');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 15, 23, 'Kedeš, Hasor Jitnan;');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 15, 24, 'Zif, Telem, Bealot;');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 15, 25, 'Novi Hasor, Kirjat Hesron (to jest Hasor);');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 15, 26, 'Amam, Šema, Molada;');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 15, 27, 'Hasar Gada, Hešmon, Bet-Pelet;');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 15, 28, 'Hasar Šual, Beer Šeba s pripadnim područjima;');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 15, 29, 'Baala, Ijim, Esem;');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 15, 30, 'Eltolad, Kesil, Horma;');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 15, 31, 'Siklag, Madmana, Sansana;');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 15, 32, 'Lebaot, Šelhim, En Rimon: svega dvadeset i devet gradova s njihovim selima.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 15, 33, 'U Dolini: Eštaol, Sora, Ašna;');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 15, 34, 'Zanoah, En Ganim, Tapuah, Haenam;');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 15, 35, 'Jarmut, Adulam, Soko, Azeka;');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 15, 36, 'Šaarajim, Aditajim, Hagedera i Gederotajim: četrnaest gradova s njihovim selima.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 15, 37, 'Senan, Hadaša, Migdal-Gad;');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 15, 38, 'Dilean, Hamispe, Jokteel;');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 15, 39, 'Lakiš, Boskat, Eglon;');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 15, 40, 'Kabon, Lahmas, Kitliš;');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 15, 41, 'Gederot, Bet-Dagon, Naama, Makeda: šesnaest gradova s njihovim selima.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 15, 42, 'Libna, Eter, Ašan;');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 15, 43, 'Jiftah, Ašna, Nesib;');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 15, 44, 'Keila, Akzib i Mareša: devet gradova s njihovim selima.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 15, 45, 'Ekron s naseljima i selima njegovim;');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 15, 46, 'od Ekrona pa do Mora, sve što se nalazi pokraj Ašdoda, s njihovim selima;');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 15, 47, 'Ašdod s naseljima i selima njegovim, Gaza s naseljima i selima njegovim do Egipatskog potoka i Velikog mora, koje je međa.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 15, 48, 'A u Gori: Šamir, Jatir, Soko;');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 15, 49, 'Dana, Kirjat Sefer (to je Debir);');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 15, 50, 'Anab, Eštemoa, Anim;');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 15, 51, 'Gošen, Holon, Gilo: jedanaest gradova s njihovim selima.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 15, 52, 'Arab, Duma, Ešean;');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 15, 53, 'Janum, Bet-Tapuah, Afeka,');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 15, 54, 'Humta, Kirjat Arba (to jest Hebron), Sior: devet gradova s njihovim selima.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 15, 55, 'Maon, Karmel, Zif, Juta;');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 15, 56, 'Jizreel, Jokdeam, Zanoah;');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 15, 57, 'Hakajin, Gibea, Timna: deset gradova s njihovim selima.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 15, 58, 'Halhul, Bet-Sur, Gedor;');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 15, 59, 'Maarat, Bet-Anot, Eltekon: šest gradova s njihovim selima. Tekoa, Efrata (to jest Betlehem), Peor, Etan, Kulon, Tatam, Sores, Karem, Galim, Beter, Manah: jedanaest gradova s njihovim selima.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 15, 60, 'Kirjat Baal (to jest Kirjat Jearim) i Haraba: dva grada s njihovim selima.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 15, 61, 'U pustinji: Bet Haaraba, Midin, Sekaka;');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 15, 62, 'Hanibšan, Slani grad i En-Gedi: šest gradova s njihovim selima.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 15, 63, 'A Jebusejce koji su živjeli u Jeruzalemu nisu mogli protjerati sinovi Judini. Tako su ostali sa sinovima Judinim u Jeruzalemu sve do danas.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 16, 1, 'Sinovima Josipovim pripao je ždrijebom posjed: od Jordana kod Jerihona, od Jerihonskih voda na istok, pa pustinjom k Betelskoj gori;');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 16, 2, 'od Betel-Luza međa se nastavljala područjem Arkijaca do Atarota.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 16, 3, 'Potom se spuštala na zapad do jafletske međe, sve do Donjeg Bet-Horona i do Gezera, odakle je izlazila na more.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 16, 4, 'To je bila baština Josipovih sinova: Manašea i Efrajima.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 16, 5, 'Područje sinova Efrajimovih po njihovim porodicama bilo je ovo: međa baštine njihove prema istoku išla je od Atrot Adara pa do Gornjega Bet-Horona.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 16, 6, 'Odatle se pružala do mora... (išla na) Mikmetat na sjeveru i zavijala dalje na istok prema Taanat Šilu i prolazila s istočne strane do Janoaha.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 16, 7, 'Od Janoaha spuštala se u Atarot i Naarat i onda, dotičući se Jerihona, udarala na Jordan.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 16, 8, 'Od Tapuaha išla je ta međa prema zapadu do potoka Kane te izbijala na more. To je bila baština plemena sinova Efrajimovih po njihovim porodicama.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 16, 9, 'A Efrajimovi su sinovi imali sve te gradove s njihovim selima i još odvojene gradove usred baštine sinova Manašeovih.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 16, 10, 'Ali nisu uspjeli otjerati Kanaanaca koji su živjeli u Gezeru. Tako su Kanaanci ostali među sinovima Efrajimovim do danas, ali im bijaše nametnuta tlaka.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 17, 1, 'Ždrijebom je dopao i dio plemenu Manašeovu, jer je Manaše bio prvenac Josipov. Makiru, prvencu Manašeovu, ocu Gileadovu - bijaše on ratnik bez premca - pripade Gilead i Bašan.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 17, 2, 'Dobili su svoj dio i ostali sinovi Manašeovi po svojim porodicama: sinovi Abiezerovi, sinovi Helekovi, sinovi Asrielovi; sinovi Šekemovi, sinovi Heferovi i sinovi Šemidini. To su muški potomci Manašea, sina Josipova, po svojim porodicama.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 17, 3, 'A Selofhad, sin Hefera, sina Gileada, sina Makira, sina Manašeova, nije imao sinova nego samo kćeri. Evo im imena: Mahla, Noa, Hogla, Milka i Tirsa.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 17, 4, 'One dođoše pred svećenika Eleazara i pred Jošuu, sina Nunova, i pred glavare govoreći: \"Jahve je zapovjedio Mojsiju da se i nama dade baština među našom braćom.\" I dadoše im po Jahvinoj zapovijedi baštinu među braćom njihova oca.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 17, 5, 'Tako je dopalo Manašeu deset dijelova, povrh gileadske i bašanske zemlje, koje su s onu stranu Jordana.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 17, 6, 'Kćeri Manašeove dobiše baštinu među njegovim sinovima, a zemlja gileadska pripala je drugim sinovima Manašeovim.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 17, 7, 'Međa je Manašeova išla od Ašera do Mikmetata, koji leži nasuprot Šekemu, a zatim zavijala desno prema Jašibu na izvoru Tapuahu.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 17, 8, 'Pokrajina Tapuah pripadaše Manašeu, ali sam Tapuah na međi Manašeovoj pripadaše sinovima Efrajimovim.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 17, 9, 'Međa je silazila do potoka Kane. Južno od potoka bili su i ovi gradovi što su Efrajimovim sinovima pripadali između Manašeovih gradova; a zemlja se Manašeova nalazila na sjeveru i izbijala na more.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 17, 10, 'Područje s juga pripadalo je Efrajimu, na sjeveru Manašeu, a more im bi međa; na sjeveru su graničili s Ašerom, a s Jisakarom na istoku.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 17, 11, 'Manašeu pripadahu u Jisakaru i Ašeru: Bet-Šean sa svojim selima, Jibleam sa svojim selima, stanovnici Dora sa svojim selima, stanovnici En-Dora sa svojim selima, stanovnici Taanaka sa svojim selima, stanovnici Megida sa svojim selima; dakle: tri područja.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 17, 12, 'Ali Manašeovi sinovi nisu mogli osvojiti te gradove i zato su Kanaanci ostali u tom kraju.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 17, 13, 'Ali kad su ojačali sinovi Izraelovi, nametnuše Kanaancima tlaku, ali ih nisu uspjeli protjerati.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 17, 14, 'Obrate se tada Josipovi sinovi Jošui i upitaju: \"Zašto si nam dao u baštinu prema jednom ždrijebu, samo jedan dio, kad smo mnogobrojni i Jahve nas dosad blagoslivljao?\"');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 17, 15, 'Jošua im odgovori: \"Kad ste narod mnogobrojan, pođite u šumu i krčite ondje sebi zemlje u periškoj i refaimskoj krajini, ako vam je pretijesna gora Efrajimova.\"');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 17, 16, 'A sinovi Josipovi rekoše: \"Gora nam ova neće biti dosta, a svi Kanaanci koji žive u ravnici imaju željezna kola, oni što su u Bet-Šeanu i selima njegovim i oni koji su u dolini jizreelskoj.\"');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 17, 17, 'Tada odgovori Jošua domu Josipovu, i Efrajimu i Manašeu: \"Vi ste brojan narod i imate silnu snagu. Zato nećeš dobiti samo jedan ždrijeb:');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 17, 18, 'neka gora bude tvoja. Ako je šumovita, iskrči je pa će obronci biti posjed doma tvoga. Istjerat ćeš sigurno Kanaance ako i imaju željezna kola, ako i jesu jaki.\"');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 18, 1, 'Sabrala se zajednica sinova Izraelovih u Šilo, i ondje razapeše Šator sastanka. Sva im se zemlja pokorila.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 18, 2, 'Ali ostade među sinovima Izraelovim još sedam plemena koja nisu primila svoje baštine.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 18, 3, 'Tada im reče Jošua: \"Dokle ćete oklijevati da pođete i zaposjednete zemlju koju vam je dao Jahve, Bog vaših otaca?');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 18, 4, 'Izaberite po tri čovjeka iz svakoga plemena, a ja ću ih poslati da popišu svu zemlju za diobu. Kad se vrate k meni,');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 18, 5, 'razdijelit ću zemlju na sedam dijelova. Neka Juda ostane na svome području na jugu, a Josipov dom neka ostane u svome kraju na sjeveru.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 18, 6, 'A vi raspišite zemlju na sedam dijelova i donesite mi amo da bacim ždrijeb za vas ovdje pred Jahvom, Bogom našim.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 18, 7, 'Leviti neće imati dijela među vama jer je svećeništvo Jahvino njihova baština; a Gad, Ruben i polovina plemena Manašeova primili su svoju baštinu na istočnoj strani Jordana - onu koju im je dao Mojsije, sluga Jahvin.\"');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 18, 8, 'Spreme se ti ljudi na put, a Jošua zapovjedi onima koji su pošli popisati zemlju: \"Idite i obiđite svu zemlju i opišite je, pa se onda vratite k meni da bacim ždrijeb ovdje pred Jahvom u Šilu.\"');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 18, 9, 'Odoše oni ljudi, prođoše zemljom i u knjigu popisaše sve gradove u sedam dijelova, pa se vratiše k Jošui u tabor u Šilu.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 18, 10, 'A Jošua baci za njih ždrijeb u Šilu pred Jahvom i ondje razdijeli Jošua zemlju sinovima Izraelovim po njihovim dijelovima plemenskim.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 18, 11, 'I pade ždrijeb na pleme sinova Benjaminovih po njihovim porodicama: utvrdi se da je njihov dio između dijela sinova Judinih i sinova Josipovih.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 18, 12, 'Sjeverna im se međa protezala od Jordana te išla uza sjeverni obronak Jerihona, uspinjala se sa zapada na goru i završavala se u pustinji Bet-Avenu.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 18, 13, 'Odatle je išla k Luzu, k južnom obronku Luza, to jest Betela; spuštala se zatim u Atrot-Adar, kraj brda koje je južno od Donjeg Bet-Horona.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 18, 14, 'Međa se dalje savijala i okretala sa zapada prema jugu, od gore koja se diže nasuprot Bet-Horonu s juga, i svršavala se kod Kirjat Baala, danas Kirjat Jearima, grada sinova Judinih. To je zapadna strana.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 18, 15, 'Južna se strana počinjala od granice Kirjat Jearima, pa se pružala na zapad k vrelu Neftoahu;');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 18, 16, 'potom se spuštala međa do kraja gore koja je prema dolini Ben-Hinomu, na sjeveru refaimske nizine, silazila zatim u dolinu Hinom uz Jebusejski obronak i dosegla do izvora Rogela.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 18, 17, 'Zatim se savijala od sjevera te izlazila na En-Šemeš i doticala Gelilot, koji se diže prema Adumimskom usponu, i silazila na Kamen Bohana, sina Rubenova.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 18, 18, 'Prolazila je zatim obronkom sa sjeverne strane prema Bet-Haarabi i silazila do Arabe.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 18, 19, 'Dalje je tekla međa uz obronak Bet-Hogle prema sjeveru i svršavala se na sjevernom Jeziku Slanog mora, do južnog kraja Jordana. To je južna međa.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 18, 20, 'Jordan je pak bio međa s istočne strane. To je baština sinova Benjaminovih, s njihovim međama unaokolo po porodicama njihovim.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 18, 21, 'Gradovi plemena sinova Benjaminovih po porodicama njihovim jesu: Jerihon, Bet-Hogla, Emek Kesis;');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 18, 22, 'Bet-Haaraba, Samarajim, Betel;');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 18, 23, 'Avim, Para, Ofra;');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 18, 24, 'Kefar Haamona, Ofni i Gaba: dvanaest gradova s njihovim selima.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 18, 25, 'Gibeon, Rama, Beerot;');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 18, 26, 'Mispe, Kefira i Mosa;');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 18, 27, 'Rekem, Jirpeel, Tarala;');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 18, 28, 'Sela Haelef, Jebus (to je Jeruzalem), Gibat i Kirjat: četrnaest gradova s njihovim selima. To je baština sinova Benjaminovih po porodicama njihovim.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 19, 1, 'Drugi ždrijeb izađe za Šimuna, za pleme sinova Šimunovih po porodicama njihovim: njihova je baština bila usred sinova Judinih.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 19, 2, 'Dodijeljena im je kao baština: Beer Šeba, Šeba, Molada;');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 19, 3, 'Hasar Šual, Bala, Esem;');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 19, 4, 'Eltolad, Betul, Horma,');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 19, 5, 'Siklag, Bet-Hamarkabot, Hasar Susa,');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 19, 6, 'Bet-Lebaot i Šaruhen: trinaest gradova i njihova sela.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 19, 7, 'Ajin, Rimon, Eter i Ašan: četiri grada s njihovim selima.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 19, 8, 'I sva naselja što su oko tih gradova, do Baalat Beera, Ramat Negeba. To je baština plemena sinova Šimunovih po porodicama njihovim.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 19, 9, 'Baština je sinova Šimunovih bila od dijela sinova Judinih, jer dio dodijeljen sinovima Judinim bijaše za njih prevelik. Zato su sinovi Šimunovi dobili svoju baštinu usred njihova područja.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 19, 10, 'Treći ždrijeb izađe za sinove Zebulunove po porodicama njihovim: njihovo je područje sezalo do Sarida,');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 19, 11, 'odakle im se međa na zapadu penjala do Marale, doticala Dabešet i dopirala do potoka koji je nasuprot Jokneamu.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 19, 12, 'Od Sarida je međa okretala prema istoku, sve do međe Kislot Tabora, odakle je izlazila do Dabrata i uspinjala se do Jafije.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 19, 13, 'A odatle je išla opet prema istoku, na Git Hefer i na Ita Kasin, izlazila na Rimon i vraćala se do Nee.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 19, 14, 'Onda je okretala sa sjevera oko Hanatona i završavala se u dolini Jiftah-Elu.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 19, 15, 'Pa Katat, Nahalal, Šimron, Jidalu i Betlehem: dvanaest gradova s njihovim selima.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 19, 16, 'To je bila baština sinova Zebulunovih po porodicama njihovim: ti gradovi s njihovim selima.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 19, 17, 'Četvrti je ždrijeb izašao za Jisakara, za sinove Jisakarove po njihovim porodicama.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 19, 18, 'A posjed im je bio: Jizreel, Hakesulot, Šunem;');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 19, 19, 'Hafarajim, Šion, Anaharat;');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 19, 20, 'Harabit, Kišjon, Ebes;');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 19, 21, 'Remet i En-Ganim, En-Hada i Bet-Pases.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 19, 22, 'Potom međa dotiče Tabor, Šahasimu i Bet-Šemeš i izlazi na Jordan: šesnaest gradova s njihovim selima.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 19, 23, 'To je baština plemena sinova Jisakarovih po porodicama njihovim: ti gradovi s njihovim selima.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 19, 24, 'Peti ždrijeb iziđe za pleme sinova Ašerovih po njihovim porodicama.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 19, 25, 'Njihova je zemlja bila: Helkat, Hali, Beten, Akšaf,');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 19, 26, 'Alamelek, Amad, Mišal. Na zapadu je međa doticala Karmel i Šihor Libnat.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 19, 27, 'Zatim je okretala prema sunčanom istoku do Bet-Dagona i doticala se Zebuluna i doline Jiftahela sa sjevera; protezala se dalje Bet-Haemekom i Neielom i dosezala slijeva Kabul,');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 19, 28, 'pa Abdon, Rehob, Hamon i Kanu sve do Velikog Sidona.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 19, 29, 'Međa je tada zavijala prema Rami i do tvrdoga grada Tira te je okretala prema Hosi i izlazila na more. Obuhvaćala je Mehaleb, Akzib,');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 19, 30, 'Ako, Afek i Rehob: dvadeset i dva grada s njihovim selima.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 19, 31, 'To je baština plemena sinova Ašerovih po porodicama njihovim: ti gradovi i njihova sela.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 19, 32, 'Šesti ždrijeb izađe za sinove Naftalijeve po njihovim porodicama.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 19, 33, 'Njihova međa ide od Helefa i od Hrasta u Saananimu, od Adami Hanekeba i Jabneela do Lakuma i izbija na Jordan.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 19, 34, 'Potom međa okreće na zapad k Aznot Taboru i pruža se odande prema Hukoku; na jugu se dotiče Zebuluna, na zapadu Ašera, na istoku Jordana.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 19, 35, 'Utvrđeni gradovi bijahu Hasidim, Ser, Hamat, Rakat, Kineret;');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 19, 36, 'Adama, Rama, Hasor,');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 19, 37, 'Kedeš, Edrej, En-Hasor;');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 19, 38, 'Jiron, Migdal-El, Horem, Bet-Anat, Bet-Šemeš: devetnaest gradova s njihovim selima.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 19, 39, 'To je baština plemena Naftalijevih sinova po porodicama njihovim: ti gradovi i njihova sela.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 19, 40, 'Izađe sedmi ždrijeb za pleme sinova Danovih po porodicama njihovim.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 19, 41, 'Područje baštine njihove bilo je: Sora, Eštaol, Ir Šemeš,');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 19, 42, 'Šaalabin, Ajalon, Jitla,');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 19, 43, 'Elon, Timna, Ekron,');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 19, 44, 'Elteke, Gibeton, Baalat,');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 19, 45, 'Jehud, Bene-Berak, Gat-Rimon,');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 19, 46, 'Me-Hajarkon i Harakon s područjem prema Jafi.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 19, 47, 'Ali područje sinova Danovih bilo je za njih pretijesno; zato udare Danovi sinovi na Lešem, osvoje ga i sve pobiju oštricom mača; zaposjednu grad, nastane se u njemu i Lešem prozovu Dan, po imenu Dana, oca svoga.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 19, 48, 'To je baština plemena sinova Danovih po porodicama njihovim: ti im gradovi i sela njihova.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 19, 49, 'Kada završe diobu zemlje ždrijebom i utvrde njezine međe, dadu Izraelci Jošui, sinu Nunovu, baštinu u svojoj sredini.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 19, 50, 'Po zapovijedi Jahvinoj dali su mu grad koji je sebi želio: Timnat-Serah u Efrajimovoj gori; on utvrdi taj grad i nastani se u njemu.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 19, 51, 'To su baštine koje su svećenik Eleazar i Jošua, sin Nunov, i glavari izraelskih plemena podijelili ždrijebom među plemena izraelska u Šilu, pred Jahvom, na vratima Šatora sastanka. Tako je zavšena razdioba zemlje.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 20, 1, 'Jahve reče Jošui:');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 20, 2, '\"Kaži sinovima Izraelovim i reci im: \'Odredite sebi gradove-utočišta za koje sam vam govorio preko Mojsija,');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 20, 3, 'da bi onamo mogao pobjeći ubojica koji nehotice ubije koga i da vam budu utočišta od krvnoga osvetnika.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 20, 4, 'Ako ubojica utekne u koji od tih gradova, neka stane pred gradska vrata i neka starješinama toga grada iznese svoju stvar. Oni neka ga prime u svoj grad i odrede mu mjesto gdje će prebivati među njima.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 20, 5, 'Ako ga krvni osvetnik progoni, ne smiju izručiti ubojicu u njegove ruke: tÓa nehotice je ubio svoga bližnjega, a ne iz mržnje.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 20, 6, 'Ubojica neka ostane u tom gradu sve dok ne stupi pred sud zajednice ili do smrti velikoga svećenika koji bude u ono vrijeme. Tada neka se ubojica vrati i neka ode u svoj grad i svome domu - u grad iz kojega je utekao.\'\"');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 20, 7, 'I posvete Kedeš u Galileji, u Naftalijevoj gori; Šekem u Efrajimovoj gori; Kirjat-Arbu, to jest Hebron, u Judinoj gori.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 20, 8, 'S druge strane Jordana, istočno od Jerihona, odrede Beser u pustinji, u ravnici plemena Rubenova, i Ramot u Gileadu od plemena Gadova, i Golan u Bašanu od plemena Manašeova.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 20, 9, 'To su bili gradovi određeni svim Izraelcima i došljacima koji borave među njima: ovamo je mogao uteći svaki koji nehotice drugoga ubije, a da sam ne pogine od osvetničke ruke dok ne izađe na sud, pred zajednicu.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 21, 1, 'Pođoše tada glavari levitskih obitelji k svećeniku Eleazaru i Jošui, sinu Nunovu, i plemenskim glavarima Izraela.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 21, 2, 'I rekoše im u Šilu, u zemlji kanaanskoj: \"Jahve je zapovjedio preko Mojsija da nam se dadu gradovi gdje ćemo živjeti i pašnjaci oko njih za našu stoku.\"');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 21, 3, 'Izraelci dadoše levitima od svoje baštine, po zapovijedi Jahvinoj, ove gradove s njihovim pašnjacima.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 21, 4, 'Iziđe, dakle, ždrijeb za porodice Kehatove: levitima, potomcima svećenika Arona, pripade trinaest gradova od plemena Judina, Šimunova i Benjaminova;');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 21, 5, 'ostalim sinovima Kehatovim pripalo je ždrijebom po porodicama deset gradova od plemena Efrajimova i Danova i od polovine plemena Manašeova.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 21, 6, 'Sinovi Geršonovi dobiše po porodicama trinaest gradova od plemena Jisakarova, Ašerova i Naftalijeva i od polovine plemena Manašeova u Bašanu.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 21, 7, 'Merarijevim sinovima po njihovim porodicama pripalo je dvanaest gradova od plemena Rubenova, Gadova i Zebulunova.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 21, 8, 'Tako Izraelci ždrijebom dodijeliše levitima te gradove s pašnjacima, kako bijaše zapovjedio Jahve preko Mojsija.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 21, 9, 'Od plemena sinova Judinih i od plemena sinova Šimunovih dodijeljeni su bili ovi gradovi koji se poimence navode:');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 21, 10, 'sinovima Aronovim u levitskim porodicama Kehatovim, jer je prvi ždrijeb bio za njih,');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 21, 11, 'pripade Kirjat-Arba, glavni grad Anakovaca, to jest Hebron, u Judinoj gori, s pašnjacima unaokolo.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 21, 12, 'Ali polja oko toga grada sa selima unaokolo bila su već dana u baštinu Kalebu, sinu Jefuneovu.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 21, 13, 'Sinovima svećenika Arona pripade grad-utočište Hebron s pašnjacima i Libna s pašnjacima;');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 21, 14, 'Jatir s pašnjacima, Eštemoa s pašnjacima,');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 21, 15, 'Holon s pašnjacima, Debir s pašnjacima,');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 21, 16, 'Ašan s pašnjacima, Juta s pašnjacima, Bet-Šemeš s pašnjacima. Dakle, devet gradova od ona dva plemena.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 21, 17, 'Od plemena Benjaminova: Gibeon s pašnjacima, Geba s pašnjacima,');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 21, 18, 'Anatot s pašnjacima, Almon s pašnjacima. Dakle, četiri grada.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 21, 19, 'Tako su svećenici, sinovi Aronovi, dobili svega trinaest gradova s njihovim pašnjacima.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 21, 20, 'Ostalim levitima u porodicama sinova Kehatovih ždrijebom su pripali gradovi plemena Efrajimova.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 21, 21, 'Dali su im grad-utočište Šekem s pašnjacima njegovim na Efrajimovoj gori, zatim Gezer s pašnjacima,');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 21, 22, 'Kibsajim s pašnjacima, Bet-Horon s pašnjacima. Dakle, četiri grada.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 21, 23, 'Od plemena Danova dobili su: Elteku s pašnjacima i Gibeton s pašnjacima,');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 21, 24, 'Ajalon s pašnjacima i Gat-Rimon s pašnjacima. Dakle, četiri grada.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 21, 25, 'Od polovine plemena Manašeova: Tanak s pašnjacima i Jibleam s pašnjacima. Dakle, dva grada.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 21, 26, 'U svemu: deset su gradova s pašnjacima dobile porodice ostalih sinova Kehatovih.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 21, 27, 'Geršonovim sinovima, porodicama levitskim, dadoše od polovine plemena Manašeova grad-utočište Golan u Bašanu i Aštarot s njihovim pašnjacima. Dakle, dva grada.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 21, 28, 'Od plemena Jisakarova: Kišon s pašnjacima, Dabrat s pašnjacima,');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 21, 29, 'Jarmut s pašnjacima i En-Ganim s pašnjacima. Dakle, četiri grada.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 21, 30, 'Od plemena Ašerova: Mišal s pašnjacima, Abdon s pašnjacima,');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 21, 31, 'Helkat s pašnjacima i Rehob s pašnjacima. Dakle, četiri grada.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 21, 32, 'Od plemena Naftalijeva: grad-utočište Kedeš u Galileji s pašnjacima, Hamot Dor s pašnjacima i Kartan s pašnjacima. Dakle, tri grada.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 21, 33, 'Svega Geršonovih gradova po porodicama njihovim bijaše trinaest gradova s pašnjacima.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 21, 34, 'Porodicama sinova Merarijevih, preostalim levitima, dali su od plemena Zebulunova: Jokneam s pašnjacima, Kartu s pašnjacima,');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 21, 35, 'Rimon s pašnjacima, Nahalal s pašnjacima. Dakle, četiri grada.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 21, 36, 'S onu stranu Jordana od plemena Rubenova dadoše im grad-utočište Beser s pašnjacima na pustinjskoj visoravni, Jahas s pašnjacima,');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 21, 37, 'Kedemot s pašnjacima, Mefaat s pašnjacima. Dakle, četiri grada.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 21, 38, 'Od plemena Gadova: grad-utočište Ramot u Gileadu s pašnjacima, Mahanajim s pašnjacima,');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 21, 39, 'Hešbon s pašnjacima, Jazer s pašnjacima. Dakle, četiri grada.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 21, 40, 'U svemu bijaše dodijeljeno ždrijebom porodicama sinova Merarijevih, preostalim levitima, dvanaest gradova.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 21, 41, 'Tako usred baštine sinova Izraelovih bijaše četrdeset i osam levitskih gradova s pašnjacima.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 21, 42, 'Svaki je taj grad imao pašnjake unaokolo. Tako je bilo sa svima spomenutim gradovima.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 21, 43, 'Tako je Jahve predao Izraelcima svu zemlju za koju se zakleo da će je dati ocima njihovim. Primili su je u posjed i nastanili se u njoj.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 21, 44, 'I dade im Jahve da otpočinu u miru na svim međama, kako se bijaše zakleo njihovim ocima. Nitko im od njihovih neprijatelja ne bijaše kadar odoljeti. Sve im je njihove neprijatelje predao Jahve u ruke.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 21, 45, 'Od svih obećanja što ih je Jahve dao domu Izraelovu nijedno ne osta neispunjeno. Sve se ispunilo.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 22, 1, 'Tada sazove Jošua sinove Rubenove i Gadove i polovinu plemena Manašeova');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 22, 2, 'i reče im: \"Izvršili ste sve što vam je Mojsije, sluga Jahvin, zapovjedio i poslušali ste me u svemu što sam vam zapovjedio.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 22, 3, 'Niste ostavili svoje braće unatoč dugom vojevanju do današnjega dana i vršili ste vjerno zapovijedi Jahve, Boga svojega.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 22, 4, 'Sada je Jahve, Bog vaš, dao mir braći vašoj, kako im bijaše obećao. Vratite se sada u svoje šatore, u zemlju koju vam je dao Mojsije, sluga Jahvin, u baštinu s onu stranu Jordana.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 22, 5, 'Samo pazite da vršite zapovijedi i Zakon što vam ga dade Mojsije, sluga Jahvin: da ljubite Jahvu, Boga svojega, da uvijek idete putovima njegovim, da čuvate zapovijedi njegove, da se držite uz njega i da mu služite svim srcem i svom dušom.\"');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 22, 6, 'I blagoslovi ih Jošua i otpusti, a oni se zatim vrate u svoje šatore.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 22, 7, 'Mojsije bijaše jednoj polovini plemena Manašeova dao baštinu u Bašanu; a drugoj polovini dade je Jošua usred njihove braće zapadno od Jordana. Otpuštajući ih u njihove šatore, Jošua ih blagoslovi.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 22, 8, 'I reče im: \"Vratite se u svoje šatore s velikim blagom i s mnogom stokom, sa srebrom, zlatom, tučem, željezom i haljinama u izobilju i podijelite plijen od neprijatelja svojih s braćom svojom.\"');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 22, 9, 'Vratiše se sinovi Rubenovi i sinovi Gadovi i polovina plemena Manašeova; odoše od sinova Izraelovih iz Šila u zemlji kanaanskoj da krenu u zemlju gileadsku, na svoju baštinu koju su zaposjeli, kako im je zapovjedio Jahve preko Mojsija.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 22, 10, 'Kad su stigli do jordanskog područja u zemlji kanaanskoj, podigoše sinovi Rubenovi, sinovi Gadovi i polovina plemena Manašeova žrtvenik na Jordanu, žrtvenik velik, izdaleka se vidio.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 22, 11, 'Čuli Izraelci gdje se govori: \"Evo, sinovi Rubenovi, sinovi Gadovi i polovina plemena Manašeova podigoše žrtvenik prema zemlji kanaanskoj, kod Jordana, na izraelskoj strani.\"');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 22, 12, 'Na to se skupi sva zajednica sinova Izraelovih u Šilu da pođu u boj na njih.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 22, 13, 'Izraelci sinovima Rubenovim, sinovima Gadovim i polovini plemena Manašeova u gileadsku zemlju poslaše Pinhasa, sina svećenika Eleazara,');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 22, 14, 'i s njime deset knezova, po jednoga rodovskog glavara od svakoga plemena Izraelova, a svaki je od njih bio glavar obitelji među tisućama porodica Izraelovih.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 22, 15, 'I kad oni dođoše k sinovima Rubenovim, sinovima Gadovim i polovini plemena Manašeova u zemlju gileadsku, rekoše im:');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 22, 16, '\"Evo što veli sva zajednica Jahvina: \'Što znači nevjera koju činite protiv Jahve, Boga Izraelova? Zašto se odvrgoste danas od Jahve i, podigavši žrtvenik, zašto se bunite protiv Jahve?');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 22, 17, 'Zar vam nije dosta zločina iz Peora, od kojega se nismo očistili do dana današnjega i zbog kojega je došao pomor na zajednicu Jahvinu?');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 22, 18, 'Ako se danas odvraćate od Jahve i bunite se danas protiv njega, neće li se sutra izliti njegov gnjev na svu zajednicu Izraelovu?');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 22, 19, 'Ili vam je možda zemlja vaše baštine nečista? Onda prijeđite u zemlju baštine Jahvine, u kojoj je Jahvino Prebivalište, i prebivajte među nama. Ali se ne bunite protiv Jahve i ne bunite se protiv nas dižući sebi žrtvenik mimo žrtvenik Jahve, Boga našega.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 22, 20, 'Nije li se Akan, Zerahov sin, sam ogriješio o \'herem\' te se oborila srdžba na svu zajednicu Izraelovu? Zar nije umro zbog krivice svoje?\'\"');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 22, 21, 'Tada odgovoriše sinovi Rubenovi, sinovi Gadovi i polovina plemena Manašeova govoreći plemenskim glavarima Izraelovim:');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 22, 22, '\"Bog, Bog Jahve, Bog nad bogovima, Jahve zna i neka zna Izrael: ako je to bila pobuna ili nevjernost prema Jahvi, neka nam uskrati svoju pomoć danas;');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 22, 23, 'ako smo podigli žrtvenik da se odvrgnemo od Jahve i da prinosimo žrtve paljenice, prinosnice i žrtve pričesnice, neka nam onda sudi Jahve!');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 22, 24, 'Učinismo to od brige i skrbi i rekosmo: \'Jednoga će dana sinovi vaši reći našima: Što vam je zajedničko s Jahvom, Bogom Izraelovim?');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 22, 25, 'Zar nije, sinovi Rubenovi i sinovi Gadovi, postavio Jahve između vas i nas među našu - Jordan? Vi nemate dijela s Jahvom.\' I tako bi sinovi vaši mogli učiniti da se sinovi naši odvrate te ne štuju Jahvu.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 22, 26, 'Zato smo rekli: \'Podignimo žrtvenik, ali ne za žrtve paljenice niti za klanice,');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 22, 27, 'nego da bude svjedočanstvo između nas i vas, među potomcima našim, da želimo služiti Jahvi paljenicama, klanicama i pričesnicama. Tako da ne mognu jednom vaši sinovi reći našima: Nemate dijela s Jahvom.\'');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 22, 28, 'Ako bi kada tako rekli nama i potomcima našim, mogli bismo odgovoriti: \'Pogledajte slog žrtvenika Jahvina što su ga podigli oci naši ne za žrtve paljenice ni klanice, nego za svjedočanstvo između nas i vas.\'');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 22, 29, 'Nije nam ni na kraj pameti pomisao da se bunimo protiv Jahve i da se odvraćamo od njega dižući žrtvenik za žrtve paljenice, prinosnice i klanice, mimo žrtvenik Jahve, Boga našega, koji je pred njegovim Prebivalištem!\"');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 22, 30, 'Kad svećenik Pinhas, knezovi zbora i glavari izraelskih plemena koji su bili s njim čuše riječi koje im rekoše sinovi Gadovi, sinovi Rubenovi i sinovi Manašeovi, umiriše se.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 22, 31, 'Tada svećenik Pinhas, sin Eleazarov, odgovori sinovima Rubenovim, sinovima Gadovim i sinovima Manašeovim: \"Spoznali smo sada da je Jahve među nama, jer mu se niste iznevjerili: tako ste sačuvali sinove Izraelove od kazne Jahvine.\"');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 22, 32, 'Svećenik Pinhas, sin Eleazarov, i knezovi odoše od sinova Rubenovih i sinova Gadovih i vratiše se iz zemlje gileadske u kanaansku k sinovima Izraelovim i kazaše im odgovor.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 22, 33, 'Izraelovim sinovima bijaše drag taj odgovor: hvalili su Boga i odustali su od nauma da udare na njih i da opustoše zemlju u kojoj su živjeli sinovi Rubenovi i sinovi Gadovi.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 22, 34, 'Sinovi Rubenovi i sinovi Gadovi nazvali su žrtvenik \"Ed\" - \"Svjedočanstvo\", jer rekoše: \"To je svjedočanstvo među nama: Jahve je Bog.\"');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 23, 1, 'Proteklo je mnogo dana kako je Jahve dao Izraelu da otpočine od svih neprijatelja unaokolo. I Jošua bijaše ostario, zašao u godine.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 23, 2, 'Dozva zato Jošua sve Izraelce, starješine, glavare, suce i upravitelje njihove i reče im: \"Ostario sam i odmakao u godinama.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 23, 3, 'Vi ste bili svjedoci svega što je Jahve, Bog vaš, pred vašim očima učinio svim narodima radi vas: Jahve, Bog vaš, borio se za vas.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 23, 4, 'Vidite, razdijelio sam ždrijebom u baštinu vašim plemenima sve narode koji su ostali i sve one narode koje sam istrijebio od Jordana do Velikog mora na zapadu.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 23, 5, 'Jahve, Bog vaš, sam će ih goniti ispred vas i otjerat će ih ispred vas i zaposjest ćete njihovu zemlju, kao što vam je obećao Jahve, Bog vaš.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 23, 6, 'Budite, dakle, postojani i sve čvršći u tome da čuvate i vršite sve što je napisano u Knjizi zakona Mojsijeva i da ne odstupite od toga ni desno ni lijevo.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 23, 7, 'Ne miješajte se s tim narodima koji ostadoše među vama; i ne spominjite imena njihovih bogova niti se kunite njima; nemojte im služiti i ne klanjajte se njima.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 23, 8, 'Nego se držite Jahve, Boga svoga, kako ste činili do danas.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 23, 9, 'Jahve je protjerao ispred vas velike i moćne narode i nitko se nije do danas mogao održati pred vama.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 23, 10, 'Jedan je od vas tjerao pred sobom tisuću, jer se Jahve, Bog vaš, borio za vas, kao što vam je obećao.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 23, 11, 'Brižno pazite da ljubite Jahvu, Boga svojega, jer se radi o vašem životu.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 23, 12, 'Jer ako se odmetnete i prionete uz ostatak onih naroda koji preostaše među vama i s njima se povežete tazbinom i pomiješate se s njima i oni s vama,');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 23, 13, 'znajte dobro da će Jahve, Bog vaš, prestati goniti te narode ispred vas; oni će vam postati zamka i mreža, bit će bič bokovima vašim i trnje očima vašim, sve dok se ne iselite iz ove dobre zemlje koju vam dade Jahve, Bog vaš.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 23, 14, 'Evo, ja krećem danas na put kojim je svima poći. Spoznajte i priznajte svim srcem svojim i svom dušom svojom: ni jedno od svih obećanja koja vam je dao Jahve, Bog vaš, nije ostalo neispunjeno.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 23, 15, 'I kao što vam se ispunilo svako obećanje što vam ga je dao Jahve, Bog vaš, tako će Jahve ispuniti i svaku prijetnju dok vas ne izbriše s lica ove dobre zemlje koju vam je dao Jahve, Bog vaš.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 23, 16, 'Ako prekršite Savez koji je Jahve, Bog vaš, sklopio s vama; ako budete služili drugim bogovima i klanjali se njima, buknut će gnjev Jahvin na vas i nestat će vas ubrzo iz dobre zemlje koju vam je Jahve dao.\"');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 24, 1, 'Jošua potom sabra sva plemena Izraelova u Šekem; i sazva starješine Izraelove, glavare, suce i upravitelje njihove i oni stadoše pred Bogom.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 24, 2, 'Tada reče Jošua svemu narodu: \"Ovako veli Jahve, Bog Izraelov: \'Nekoć su oci vaši, Terah, otac Abrahamov i Nahorov, živjeli s onu stranu Rijeke i služili drugim bogovima.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 24, 3, 'Ali sam ja uzeo oca vašega Abrahama s one strane Rijeke i proveo ga kroza svu zemlju kanaansku, umnožio mu potomstvo i dao mu Izaka.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 24, 4, 'Izaku dadoh Jakova i Ezava. Ezavu sam dao goru Seir u posjed. Jakov i sinovi njegovi otišli su u Egipat.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 24, 5, 'Tada sam poslao Mojsija i Arona i udario sam Egipat kaznama koje sam učinio u njemu i tada sam vas izveo.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 24, 6, 'Izveo sam oce vaše iz Egipta i stigli su na more; Egipćani su progonili vaše oce bojnim kolima i konjanicima sve do Mora crvenoga.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 24, 7, 'Zavapili su tada Jahvi i on je razvukao gustu maglu između njih i Egipćana i naveo ih u more koje ih je prekrilo. Vidjeli ste svojim očima što sam učinio Egipćanima; zatim ste ostali dugo vremena u pustinji.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 24, 8, 'Nato sam vas uveo u zemlju Amorejaca, koji žive s onu stranu Jordana. Zaratiše s vama i ja ih dadoh u vaše ruke; uzeli ste u baštinu zemlju njihovu jer sam ih ja ispred vas uništio.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 24, 9, 'Tada se digao moapski kralj Balak, sin Siporov, da ratuje s Izraelom i on pozva Bileama, sina Beorova, da vas prokune.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 24, 10, 'Ali ja ne htjedoh poslušati Bileama: morade vas on i blagosloviti, i spasih vas iz njegove ruke.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 24, 11, 'Onda ste prešli preko Jordana i došli u Jerihon, ali su glavari Jerihona poveli rat protiv vas - kao i Amorejci, Perižani, Kanaanci, Hetiti, Girgašani, Hivijci i Jebusejci - ali sam ih ja predao u vaše ruke.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 24, 12, 'Pred vama sam poslao stršljene koji su ispred vas tjerali dva kralja amorejska: nemaš što zahvaliti svome maču ni svome luku.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 24, 13, 'Dao sam vam zemlju za koju se niste trudili i gradove koje niste gradili i u njima se nastaniste; i vinograde vam dadoh i maslinike koje niste sadili, a danas vas hrane.\'');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 24, 14, 'I zato se sada bojte Jahve i služite mu savršeno i vjerno! Uklonite bogove kojima su služili oci vaši s onu stranu Rijeke i u Egiptu i služite Jahvi!');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 24, 15, 'Međutim, ako vam se ne sviđa služiti Jahvi, onda danas izaberite kome ćete služiti: možda bogovima kojima su služili vaši oci s onu stranu Rijeke ili bogovima Amorejaca u čijoj zemlji sada prebivate. Ja i moj dom služit ćemo Jahvi.\"');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 24, 16, 'Narod odgovori: \"Daleko neka je od nas da ostavimo Jahvu a služimo drugim bogovima.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 24, 17, 'Jahve, Bog naš, izveo je nas i naše oce iz Egipta, iz doma robovanja, i on je pred našim očima učinio velika čudesa i čuvao nas cijelim putem kojim smo išli i među svim narodima kroz koje smo prolazili.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 24, 18, 'Još više: Jahve je ispred nas protjerao sve narode i Amorejce, koji su živjeli u ovoj zemlji. I mi ćemo služiti Jahvi jer je on Bog naš.\"');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 24, 19, 'Tada reče Jošua narodu: \"Vi ne možete služiti Jahvi, jer je on Bog sveti, Bog ljubomorni, koji ne može podnijeti vaših prijestupa ni vaših grijeha.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 24, 20, 'Ako ostavite Jahvu da biste služili tuđim bogovima, okrenut će se protiv vas i uništit će vas, pošto vam je bio dobro činio.\"');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 24, 21, 'A narod odgovori Jošui: \"Ne, mi ćemo služiti Jahvi!\"');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 24, 22, 'Na to će Jošua narodu: \"Sami ste protiv sebe svjedoci da ste izabrali Jahvu da mu služite.\" Odgovoriše mu: \"Svjedoci smo.\"');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 24, 23, '\"Maknite, dakle, tuđe bogove koji su među vama i priklonite svoja srca Jahvi, Bogu Izraelovu.\"');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 24, 24, 'Odgovori narod Jošui: \"Služit ćemo Jahvi, Bogu svojemu, i glas ćemo njegov slušati.\"');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 24, 25, 'Tako sklopi Jošua toga dana Savez s narodom i utvrdi mu uredbu i zakon. Bilo je to u Šekemu.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 24, 26, 'Jošua upisa te riječi u Knjigu zakona Božjega. Zatim uze velik kamen i stavi ga ondje pod hrast koji bijaše u svetištu Jahvinu.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 24, 27, 'Zatim reče Jošua svemu narodu: \"Gle, ovaj kamen neka nam bude svjedokom jer je čuo riječi što ih je govorio Jahve; on će biti svjedok da ne zatajite Boga svoga.\"');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 24, 28, 'Tada Jošua otpusti narod, svakoga na njegovu baštinu.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 24, 29, 'Poslije ovih događaja umrije Jošua, sin Nunov, sluga Jahvin, u dobi od sto deset godina.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 24, 30, 'Sahraniše ga u kraju što ga je baštinio u Timnat Serahu, u Efrajimovoj gori, sjeverno od gore Gaaša.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 24, 31, 'Izrael je služio Jahvi svega vijeka Jošuina i svega vijeka starješina koje su Jošuu nadživjele i vidjele sva djela što ih je Jahve učinio Izraelu.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 24, 32, 'Kosti Josipove, koje su sinovi Izraelovi sa sobom donijeli iz Egipta, pokopali su u Šekemu, na zemljištu koje Jakov bijaše kupio od sinova Hamora, oca Šekemova, za stotinu srebrnjaka i koje je pripalo u baštinu sinova Josipovih.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 24, 33, 'Umrije i Eleazar, sin Aronov, i pokopaše ga u Gibei, koja je pripadala njegovu sinu Pinhasu a nalazila se u Efrajimovoj gori.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 1, 1, 'Poslije smrti Jošuine upitaše Izraelci Jahvu: \"Tko će od nas prvi poći na Kanaance da se protiv njih bori?\"');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 1, 2, 'A Jahve odgovori: \"Neka Juda prvi pođe; u njegove ruke stavljam zemlju.\"');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 1, 3, 'Tada Juda reče svome bratu Šimunu: \"Pođi sa mnom u zemlju koja mi je dosuđena u baštinu; borit ćemo se protiv Kanaanaca, a potom ću se ja uza te boriti na tvojoj zemlji.\" I Šimun ode s njim.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 1, 4, 'Ode Juda i Jahve im predade u ruke Kanaance i Perižane te pobiše u Bezeku deset tisuća ljudi.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 1, 5, 'U Bezeku zatekoše Adoni-Sedeka, udariše na nj i poraziše Kanaance i Perižane.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 1, 6, 'Kad je Adoni-Sedek nagnuo u bijeg, gonili su ga, uhvatili ga i odsjekli mu palce na rukama i nogama.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 1, 7, 'Tada reče Adoni-Sedek: \"Sedamdeset kraljeva odsječenih palaca na rukama i na nogama kupilo je mrvice pod mojim stolom. Kako sam činio, tako mi Bog vraća.\" Odveli su ga u Jeruzalem i ondje je umro.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 1, 8, 'Zatim Judini sinovi udariše na Jeruzalem, osvojiše ga, posjekoše mačem žitelje i spališe grad.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 1, 9, 'Poslije toga krenuše Judini sinovi da se bore protiv Kanaanaca koji su živjeli u Gorju, Negebu i u Šefeli.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 1, 10, 'Onda Juda ode na Kanaance koji su živjeli u Hebronu - Hebronu bijaše nekoć ime Kirjat Arba - i ondje potuče Šešaja, Ahimana i Talmaja.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 1, 11, 'Odatle krenu na stanovnike Debira, koji se nekoć zvao Kirjat Sefer.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 1, 12, 'Tada reče Kaleb: \"Tko pokori i zauzme Kirjat Sefer, dat ću mu svoju kćer Aksu za ženu.\"');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 1, 13, 'Zauze ga Otniel, sin Kenaza, mlađeg brata Kalebova, i Kaleb mu dade svoju kćer Aksu za ženu.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 1, 14, 'Kad je prišla mužu, on je nagovori da u svoga oca ište polje. Siđe ona s magarca, a Kaleb je upita: \"Što hoćeš?\"');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 1, 15, 'Ona mu odgovori: \"Daj mi blagoslov! Kad si mi dao kraj u Negebu, daj mi onda i koji izvor vode.\" I Kaleb joj dade Gornje i Donje izvore.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 1, 16, 'Sinovi Hobaba Kenijca, tasta Mojsijeva, odoše iz Palmova grada s Judinim sinovima u Judinu pustinju, koja je u Negebu, na jugu od Arada. Tu se nastaniše među Amalečanima.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 1, 17, 'Potom ode Juda s bratom Šimunom i pobiše Kanaance koji su živjeli u Sefatu i grad izručiše \"heremu\", prokletstvu. Zbog toga se grad prozva Horma.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 1, 18, 'Ali Juda nije uspio zauzeti Gaze s njenim područjem, ni Aškelona s njegovim područjem, ni Ekrona s njegovim područjem.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 1, 19, 'Jahve bijaše s njim te on osvoji gorje, ali ne mogaše potjerati onih u nizini jer imahu željezna kola.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 1, 20, 'Kao što bijaše odredio Mojsije, dadoše Hebron Kalebu, koji iz njega otjera tri sina Anakova.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 1, 21, 'A Benjaminovi sinovi ne uspješe otjerati Jebusejaca koji su živjeli u Jeruzalemu i tako Jebusejci ostadoše u Jeruzalemu s Benjaminovim sinovima do dana današnjega.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 1, 22, 'Krenu i pleme Josipovo na Betel i Jahve bijaše s njima.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 1, 23, 'I pleme Josipovo uze izviđati Betel. Grad se nekoć zvao Luz.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 1, 24, 'Uhode opaziše čovjeka gdje izlazi iz grada i rekoše mu: \"Pokaži nam kuda se može u grad, pa ćemo ti biti milostivi.\"');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 1, 25, 'On im pokaza kuda mogu u grad. I sve u gradu isjekoše mačem, a onoga čovjeka sa svom njegovom obitelji pustiše da ode.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 1, 26, 'Čovjek je otišao u zemlju Hetita i ondje sagradio grad i prozvao ga Luz. Tako se zove još i danas.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 1, 27, 'Manaše nije osvojio Bet-Šeana i njegovih sela ni Tanaka i njegovih sela. Nije potjerao ni stanovnika iz Dora i njegovih sela, ni stanovnika Jibleama i njegovih sela, ni stanovnika Megida i njegovih sela. Tako su Kanaanci ostali i živjeli u toj zemlji.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 1, 28, 'Kad je Izrael ojačao, nametnuo je Kanaancima tlaku, ali ih nije mogao otjerati.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 1, 29, 'Ni Efrajim nije otjerao Kanaanaca koji su živjeli u Gezeru, tako te su Kanaanci tu živjeli među njima.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 1, 30, 'Zebulun nije otjerao stanovnika Kitrona ni stanovnika Nahalola. Tako su Kanaanci ostali usred Zebulunovih sinova, ali im bijaše nametnuta tlaka.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 1, 31, 'Ni Ašer nije otjerao stanovnika Akona, ni stanovnika Sidona, ni onih iz Mahalaba, Akziba, Helbe, Afika i Rehoba.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 1, 32, 'Ašerovci su ostali tako među Kanaancima, stanovnicima te zemlje, jer ih nisu otjerali.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 1, 33, 'Naftali nije otjerao stanovnika Bet-Šemeša i Bet-Anata, nego je živio među Kanaancima koji su nastavali tu zemlju, ali je stanovnicima Bet-Šemeša i Bet-Anata nametnuta tlaka.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 1, 34, 'Amorejci su potisnuli Danove sinove u goru i nisu ih puštali da siđu u ravnicu.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 1, 35, 'Amorejci su se zadržali u Har-Heresu, Ajalonu i Šaalbimu, ali kad je ruka Josipova doma ojačala, bila im je nametnuta tlaka.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 1, 36, 'Područje Edomaca pruža se od Akrabimskog uspona do Stijene pa naviše.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 2, 1, 'Anđeo Jahvin dođe iz Gilgala u Bokim i reče: \"Izveo sam vas iz Egipta i doveo vas u zemlju koju sam vam obećao zaklevši se ocima vašim. Rekao sam: \'Neću raskinuti Saveza svog s vama dovijeka.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 2, 2, 'A vi ne sklapajte saveza sa stanovnicima ove zemlje; nego rušite njihove žrtvenike!\' Ali vi niste poslušali moga glasa. Što ste učinili?');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 2, 3, 'Zato vam kažem: neću ih odagnati pred vama. Nego, oni će vas tlačiti i bogovi njihovi bit će vam zamkom.\"');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 2, 4, 'Kad Anđeo Jahvin izreče te riječi svim Izraelcima, narod zakuka i zaplaka.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 2, 5, 'I tako prozvaše ono mjesto Bokim i ondje prinesoše žrtve Jahvi.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 2, 6, 'Tada Jošua otpusti narod i raziđoše se Izraelci svaki na svoju baštinu da zaposjednu zemlju.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 2, 7, 'Narod je služio Jahvi svega vijeka Jošuina i svega vijeka starješina koje su nadživjele Jošuu i vidjele sva velika djela što ih je Jahve učinio Izraelu.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 2, 8, 'Jošua, sin Nunov, sluga Jahvin, umrije u dobi od sto deset godina.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 2, 9, 'Sahraniše ga u kraju što ga je baštinio u Timnat Heresu, u Efrajimovoj gori, sjeverno od planine Gaaša.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 2, 10, 'A kada se sav onaj naraštaj pridružio svojim ocima, naslijedi ga drugi naraštaj koji nije mario za Jahvu ni za djela što ih je učinio Izraelu.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 2, 11, 'Tada su sinovi Izraelovi počeli činiti ono što Jahvi nije po volji i služili su baalima.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 2, 12, 'Ostaviše Jahvu, Boga otaca svojih, koji ih je izveo iz zemlje egipatske, i pođoše za drugim bogovima između bogova okolnih naroda. Klanjahu im se, razgnjeviše Jahvu.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 2, 13, 'Otpali su od Jahve da bi služili Baalu i Aštarti.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 2, 14, 'Zato Jahve izli gnjev svoj na Izraela: prepusti ih pljačkašima da ih plijene, izruči ih neprijateljima uokolo, tako te se ne mogoše oduprijeti.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 2, 15, 'Što bi god počeli, ruka se Jahvina okretala protiv njih na njihovu nesreću, kao što im je Jahve rekao i kao što im se zakleo. I tako zapadoše u veliku nevolju.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 2, 16, 'Tada im Jahve stade podizati suce da ih izbavljaju iz ruku onih koji su ih pljačkali.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 2, 17, 'Ali oni ni svojih sudaca nisu slušali, nego se iznevjeriše s drugim bogovima te im se klanjahu. Brzo su zašli s puta kojim su išli oci njihovi slušajući Jahvine zapovijedi; oni nisu činili tako.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 2, 18, 'Kada im je podizao suce, Jahve bijaše sa svakim sucem te ih izbavljaše iz ruku njihovih neprijatelja za svega vijeka sučeva, jer se sažalilo Jahvi koliko su uzdisali pod jarmom onih koji su ih ugnjetavali.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 2, 19, 'A kada bi sudac umro, oni bi opet zapadali u veću pokvarenost nego njihovi oci. Išli su za drugim bogovima, služili im i klanjali im se, ne odustajući od svojih opakih djela i postupaka.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 2, 20, 'Tada Jahve planu gnjevom na Izraela i reče: \"Kad je taj narod pogazio Savez kojim sam obvezao njihove očeve i nije poslušao glasa moga,');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 2, 21, 'ni ja odsad neću pred njim potjerati ni jednoga između naroda što ih je Jošua po svojoj smrti ostavio\",');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 2, 22, 'da bi njima stavio na kušnju Izraela: hoće li se ili neće držati Jahvinih putova kao što ih se držahu oci njihovi.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 2, 23, 'Zato Jahve bijaše ostavio te narode i nije ih odmah izagnao ni predao Jošui u ruke.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 3, 1, 'Ovo su narodi koje je Jahve pustio da ostanu kako bi njima iskušavao sinove Izraelove, sve one koji ne iskusiše ratova kanaanskih.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 3, 2, 'Bijaše to samo na korist pokoljenjima sinova Izraelovih da nauče vještinu ratovanja - barem oni koji nisu iskusili prijašnjih ratova:');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 3, 3, 'ostade pet knezova filistejskih i svi Kanaanci, Sidonci i Hivijci koji su živjeli na gori Libanonu od gore Baal-Hermona do ulaza u Hamat.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 3, 4, 'Oni su poslužili da se iskuša Izrael: da bi se vidjelo hoće li se držati zapovijedi što ih je Jahve preko Mojsija dao njihovim ocima.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 3, 5, 'Tako su Izraelci prebivali usred Kanaanaca, Hetita, Amorejaca, Perižana, Hivijaca i Jebusejaca;');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 3, 6, 'ženili se njihovim kćerima i davali svoje kćeri njihovim sinovima i služili njihovim bogovima.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 3, 7, 'I činili su Izraelci ono što Jahvi nije bilo po volji. Zaboravili su Jahvu, svoga Boga, da bi služili baalima i aštartama.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 3, 8, 'Tada Jahve planu gnjevom na Izraela i dade ih u ruke Kušanu Rišatajimu, kralju edomskom; i služiše Kušanu Rišatajimu osam godina.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 3, 9, 'Tad Izraelci zavapiše Jahvi i Jahve im podiže izbavitelja, Otniela, sina Kenaza, mlađega brata Kalebova, da ih oslobodi.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 3, 10, 'Duh Jahvin siđe na nj i on posta sucem Izraelu. I povede Izraela u boj. Jahve mu preda u ruke Kušana Rišatajima, kralja edomskog, i on pobijedi Kušana Rišatajima.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 3, 11, 'Zemlja je otad bila u miru četrdeset godina. Poslije smrti Otniela, sina Kenazova,');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 3, 12, 'Izraelci su počeli opet činiti što je zlo u očima Jahvinim. Zato Jahve dade Eglonu, kralju moapskom, moć nad Izraelom, jer su činili što je zlo pred Jahvom.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 3, 13, 'Eglon se ujedini sa sinovima Amonovim i Amalekovim, pođe na Izraela, potuče ga i osvoji Palmov grad.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 3, 14, 'Izraelci su služili moapskom kralju Eglonu osamnaest godina.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 3, 15, 'Tada Izraelci zavapiše Jahvi i Jahve im podiže izbavitelja - Ehuda, sina Gere iz Benjaminova plemena, čovjeka koji bijaše ljevak. I poslaše ga Izraelci da im odnese danak Eglonu, kralju moapskom.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 3, 16, 'A Ehud načini sebi bodež sa dvije oštrice, lakat dug, i pripasa ga pod haljine uz desno bedro.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 3, 17, 'I odnese danak Eglonu, kralju moapskom. Eglon bijaše vrlo debeo.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 3, 18, 'Predavši danak, Ehud ode s ljudima koji bijahu donijeli danak.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 3, 19, 'Ali kada je došao do idola u blizini Gilgala, vrati se i reče: \"Imam ti, kralju, reći jednu tajnu!\" Kralj mu odvrati: \"Tiho!\" I svi koji su uza nj bili izađu.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 3, 20, 'Ehud uđe. Kralj je sjedio u hladovitoj gornjoj sobi; bio je sam. Ehud mu reče: \"Imam, kralju, za tebe riječ od Boga!\" On odmah usta s prijestolja.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 3, 21, 'Tad Ehud lijevom rukom trgnu bodež s desnog bedra i satjera mu ga u trbuh.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 3, 22, 'Za oštricom uđe sav držak i salo se sklopi za oštricom, jer Ehud nije mogao izvući oštricu iz trbuha. Nečist je izlazila odande.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 3, 23, 'Ehud je otišao kroz trijem; za sobom je zatvorio vrata gornje sobe i zaključao ih.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 3, 24, 'Kada je on otišao, vrate se sluge da pogledaju. Kako vrata gornje sobe bijahu zaključana, rekoše: \"Bit će da je otišao na stranu, u klijet do hladovite sobe.\"');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 3, 25, 'Čekali su ga dugo, u nedoumici, jer on nije otvarao vrata gornje sobe. Naposljetku uzeše ključ i otvoriše: gospodar im ležao na tlu, mrtav.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 3, 26, 'Dok su oni čekali, Ehud je pobjegao, prošao već idole i sklonio se u Seiru.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 3, 27, 'Čim dođe u zemlju Izraelovu, zasvira u rog na Efrajimovoj gori; i siđoše Izraelci s njim s gore, a on im stajaše na čelu.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 3, 28, 'I reče im: \"Pođite za mnom! Jahve vam je u ruke predao Moapce, vaše neprijatelje.\" Oni krenuše za njim, zatvoriše Moapcima put preko gazova Jordana i ne dadoše nikome prijeko.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 3, 29, 'Pobili su u to vrijeme oko deset tisuća Moabaca, sve kršnih i hrabrih ljudi, i nijedan im nije umakao.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 3, 30, 'Toga su dana Moapci potpali pod ruku Izraelovu i zemlja bijaše mirna osamdeset godina.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 3, 31, 'Poslije njega bijaše Šamgar, sin Anatov. On je pobio šest stotina Filistejaca ostanom volujskim. Tako je i on spasio Izraela.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 4, 1, 'Poslije smrti Ehudove Izraelci su opet stali činiti što Jahvi nije po volji');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 4, 2, 'i Jahve ih predade u ruke Jabinu, kanaanskom kralju koji je vladao u Hasoru. Vojskovođa vojsci njegovoj bijaše Sisera, koji je živio u Harošetu Poganskom.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 4, 3, 'Tad Izraelci zavapiše Jahvi. Jer Jabin imaše devet stotina željeznih bojnih kola i teško je tlačio Izraelce dvadeset godina.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 4, 4, 'U to vrijeme Izraelu je sudila proročica Debora, žena Lapidotova.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 4, 5, 'Živjela je pod Deborinom palmom između Rame i Betela u Efrajimovoj gori i k njoj su dolazili Izraelci da presuđuje u njihovim sporovima.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 4, 6, 'Ona dozva Baraka, sina Abinoamova, iz Naftalijeva Kedeša i reče mu: \"Evo što ti Jahve, Bog Izraelov, zapovijeda: \'Idi, kreni na goru Tabor i uzmi sa sobom deset tisuća ljudi između Naftalijevih i Zebulunovih sinova.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 4, 7, 'Ja ću k tebi na Kišonski potok privući Siseru, vojskovođu Jabinove vojske, s njegovim bojnim kolima i svim ratnicima te ću ga predati u tvoje ruke.\'\"');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 4, 8, 'Barak joj odgovori: \"Ako ti pođeš sa mnom, ići ću; ako li ne pođeš sa mnom, ne idem.\"');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 4, 9, '\"Idem s tobom\", reče mu ona, \"ali na putu kojim ćeš poći slava neće tebi pripasti jer će Jahve ženi predati u ruke Siseru.\" Tada Debora ustane i pođe s Barakom u Kedeš.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 4, 10, 'Onamo je Barak pozvao Zebuluna i Naftalija. Deset tisuća ljudi pođe za njim, a išla je s njim i Debora.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 4, 11, 'Heber Kenijac bijaše se odvojio od Kajina, jednoga od sinova Hababa, tasta Mojsijeva; razapeo je svoj šator kod Hrasta u Saananimu, nedaleko od Kedeša.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 4, 12, 'Javiše Siseri da je Barak, sin Abinoamov, izašao na goru Tabor.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 4, 13, 'Nato Sisera sabra sva svoja kola, devet stotina željeznih kola, i sve ljude koje je doveo od Harošeta Poganskog do Kišonskog potoka.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 4, 14, 'Debora reče Baraku: \"Ustani, evo dana kada će Jahve predati Siseru u tvoje ruke! Sam Jahve ide pred tobom!\" I Barak siđe s gore Tabora sa deset tisuća ljudi za sobom.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 4, 15, 'Jahve zastraši Siseru, sva njegova kola i čitavu njegovu vojsku, koja naže u bijeg pred mačem Barakovim. Sisera siđe sa svojih kola i pobježe pješice.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 4, 16, 'Barak je gonio kola i vojsku sve do Harošeta Poganskog. Sva je Siserina vojska pala od oštrog mača i nijedan čovjek nije umakao.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 4, 17, 'Sisera je dotle bježao pješice prema šatoru Jaele, žene Hebera Kenijca, jer između Jabina, kralja hasorskog, i kuće Hebera Kenijca bijaše mir.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 4, 18, 'Jaela iziđe Siseri u susret i reče mu: \"Zaustavi se, gospodaru, svrati se k meni. Ne boj se ničega!\" On svrati k njoj pod šator, a ona ga pokri pokrivačem.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 4, 19, 'On joj reče: \"Daj mi malo vode jer sam žedan.\" Ona otvori mijeh s mlijekom, napoji ga i opet ga pokri.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 4, 20, '\"Stani na ulazu u šator\", reče joj on, \"pa ako tko naiđe i zapita te: \'Ima li tu koga?\' ti odgovori: \'Nema!\'\"');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 4, 21, 'A Jaela, žena Heberova, uze šatorski klin i čekić u ruke, tiho mu se približi i zabi mu klin kroza sljepoočice tako da se zario u zemlju. On od iscrpljenosti bijaše tvrdo zaspao i tako umrije.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 4, 22, 'I gle, dođe Barak progoneći Siseru. Jaela iziđe preda nj i reče mu: \"Dođi da ti pokažem čovjeka koga tražiš.\" On uđe k njoj, i gle - Sisera ležaše mrtav, s klinom u sljepoočici.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 4, 23, 'Tako je Bog u onaj dan ponizio Jabina, kralja kanaanskog, pred Izraelcima.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 4, 24, 'Ruka Izraelaca postajaše sve teža Jabinu, kralju kanaanskom, dok ga nije napokon zatrla.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 5, 1, 'Toga dana Debora i Barak, sin Abinoamov, zapjevaše ovu pjesmu:');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 5, 2, 'Ratoborno rasuše kose borci izraelski i dragovoljno krenu narod: blagoslivljajte Jahvu!');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 5, 3, 'Čujte, o kraljevi! Poslušajte, knezovi! Jahvi ja pjesmu pjevam, Jahvu, Boga Izraelova, ja slavim.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 5, 4, 'Sa Seira kad si silazio, Jahve, pobjednički kad si kročio iz polja edomskih, sva se zemlja tresla, lila se nebesa, oblaci curkom daždjeli.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 5, 5, 'Brda se tresla pred tobom, o Jahve, Jahve, Bože Izraelov!');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 5, 6, 'U dane Šamgara, sina Anatova, u dane Jaele opustješe putovi; i oni koji su putovali, obilažahu naokolo.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 5, 7, 'Pusta bijahu sela izraelska dok ne ustadoh ja, Debora, dok ne ustadoh kao majka Izraelu.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 5, 8, 'Tuđe bogove sebi izabraše, i zato im rat stade pred vrata. Za pet gradova ne bi nijednog štita! Nijednog kralja za četrdeset tisuća u Izraelu!');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 5, 9, 'Srce moje kuca za vođe izraelske, za narod što dragovoljno u boj kreće! Blagoslivljajte Jahvu!');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 5, 10, 'Vi koji na bijelim jašete magaricama, na sagovima sjedeći, i vi koji hodite putovima, pjevajte,');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 5, 11, 'uz povike razdraganih pastira kod pojila. Neka se slave dobročinstva Jahvina i vladavina njegova Izraelom! I narod Jahvin siđe na vrata.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 5, 12, 'Probudi se, Deboro, ustani! Ustani, pjesmu zapjevaj! Hrabro! Ustani, Barače, vodi u roblje porobljivače svoje, sine Abinoamov!');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 5, 13, 'Tad siđe na vrata Izrael, narod Jahvin pohrli junački.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 5, 14, 'Iz Efrajima potekoše u dolinu, za njima stiže među čete tvoje Benjamin. Iz Makira stupaju glavari, iz Zebuluna oni što nose štap zapovjednički.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 5, 15, 'Knezovi Jisakarovi s Deborom bjehu, a Naftali pođe s Barakom, pohrli da ga stigne u dolini. Kod Rubenovih potoka dugo se savjetuju.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 5, 16, 'Zašto si ostao u torovima da slušaš sred stada svirku frule? Kod Rubenovih potoka dugo se savjetuju.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 5, 17, 'Gilead osta s onu stranu Jordana. A zašto je Dan na stranim lađama? Zašto na obali mora Ašer sjedi, mirno prebiva u svojim zaljevima?');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 5, 18, 'Zebulun je narod što prkosi smrti s Naftalijem, na visoravnima.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 5, 19, 'Došli su kraljevi, boj zametnuli, boj bili kraljevi kanaanski, u Tanaku, na vodi megidskoj, al\' ni mrve srebra ne dobiše.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 5, 20, 'Sa nebeskih staza vojevahu, vojevahu zvijezde prot\' Siseri.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 5, 21, 'Sve otplavi potok Kišon, potok Kišon pradavni. Gazi čvrsto, moja dušo!');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 5, 22, 'Topot silan odjekuje: jure borci na konjima!');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 5, 23, '\"Proklinjite Meroz,\" Anđeo će Jahvin, \"proklinjite žitelje njegove što Jahvi nisu u pomoć pritekli, u pomoć Jahvi s junacima.\"');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 5, 24, 'Blagoslovljena među ženama bila Jaela, žena Hebera Kenijca, među ženama šatora nek\' je slavljena!');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 5, 25, 'On vode zaiska, mlijeka mu ona dade, u zdjelu dragocjenu nali mu povlake.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 5, 26, 'Rukom lijevom za klinom segnu, a desnom za čekićem kovačkim. Udari Siseru, glavu mu razmrska, probode mu, razbi sljepoočicu.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 5, 27, 'Do nogu pade joj, sruši se, leže, do nogu pade joj, sruši se; i gdje pade, mrtav osta.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 5, 28, 'Kroz prozor motri Siserina mati, kroz prozor motri, na rešetku jÓada: \"Dugo mu se kola ne vraćaju: što im je zapreg tako spor?\"');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 5, 29, 'Najmudrija zbori joj dvorkinja, sebi samoj ona odgovara:');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 5, 30, '\"Plijen su našli pa ga dijele: po djevojku na ratnika, po djevojku i po dvije, halju-dvije za Siseru, vezen rubac za moj vrat!\"');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 5, 31, 'Tako neka ginu, Jahve, svi neprijatelji tvoji! A oni koji te ljube nek budu kao sunce kada se diže u svojemu sjaju! I zemlja bijaše mirna četrdeset godina.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 5, 32, '');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 6, 1, 'Opet su Izraelci činili što je zlo u Jahvinim očima; i Jahve ih predade u ruke Midjancima za sedam godina.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 6, 2, 'Teška bijaše ruka Midjanaca nad Izraelom. Da bi izmakli Midjancima, Izraelci se sklanjahu u gorske pukotine, spilje i skrovišta.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 6, 3, 'I kada bi Izraelci posijali, dolazili bi na njih Midjanci i Amalečani i sinovi Istoka.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 6, 4, 'Utaborivši se na njihovoj zemlji, uništavali bi rod zemlje sve do Gaze. Ne ostavljahu Izraelu ništa da se prehrani, ni ovce ni koze, ni vola ni magarca,');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 6, 5, 'jer dolažahu sa svojim stadima i svojim šatorima u takvu mnoštvu kao skakavci; ne bijaše broja njima ni njihovim devama; preplavili bi zemlju, opustošili je.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 6, 6, 'Tako su Midjanci bacili Izraela u veliku bijedu te Izraelci zavapiše Jahvi.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 6, 7, 'Kad su Izraelci zavapili Jahvi zbog Midjanaca,');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 6, 8, 'Jahve posla Izraelcima proroka koji im reče: \"Ovako kaže Jahve, Bog Izraelov: \'Ja sam vas izveo iz Egipta, izbavio vas iz kuće ropstva.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 6, 9, 'Ja sam vas oslobodio od ruke Egipćana i od ruke svih vaših tlačitelja. Protjerao sam ih pred vama, dao vam njihovu zemlju');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 6, 10, 'i rekao vam: Ja sam Jahve, Bog vaš. Ne štujte bogova Amorejaca u kojih zemlji živite. Ali vi ne poslušaste moga glasa.\'\"');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 6, 11, 'Anđeo Jahvin dođe i sjede pod hrast kod Ofre koji pripadaše Joašu Abiezerovu. Njegov sin Gideon vrhao je pšenicu na tijesku da bi je sačuvao od Midjanaca.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 6, 12, 'I ukaza mu se Anđeo Jahvin i reče mu: \"Jahve s tobom, hrabri junače!\"');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 6, 13, 'Gideon mu odgovori: \"Oh, gospodaru, ako je Jahve s nama, zašto nas sve ovo snađe? Gdje su sva ona čudesa njegova o kojima nam pripovijedahu oci naši govoreći: \'Nije li nas Jahve iz Egipta izveo?\' A sada nas je Jahve ostavio, predao nas u ruke Midjancima.\"');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 6, 14, 'Jahve se tad okrenu prema njemu i reče mu: \"Idi s tom snagom u sebi i izbavit ćeš Izraela iz ruke Midjanaca. Ne šaljem li te ja?\"');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 6, 15, '\"Ali, gospodaru\", odgovori mu Gideon, \"kako ću izbaviti Izraela? Moj je rod najmanji u Manašeovu plemenu, a ja sam posljednji u kući svoga oca.\"');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 6, 16, 'Jahve mu reče: \"Ja ću biti s tobom te ćeš pobijediti Midjance kao jednoga.\"');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 6, 17, 'Gideon mu reče: \"Ako sam našao milost u tvojim očima, daj mi znak da ti govoriš sa mnom.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 6, 18, 'Nemoj otići odavde dok se ne vratim s darom i stavim ga preda te.\" A on odgovori: \"Ostat ću dok se ne vratiš.\"');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 6, 19, 'Gideon ode, zgotovi jare i od efe brašna načini beskvasne hljebove, stavi meso u košaricu i juhu u lonac pa donese sve to pod hrast.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 6, 20, 'Anđeo Jahvin reče mu: \"Uzmi meso i beskvasne hljebove, stavi ih na tu stijenu, a juhu prolij.\" On učini tako.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 6, 21, 'Anđeo Jahvin tad uze štap što ga je držao i vrhom dotaknu meso i beskvasne hljebove. Oganj planu iz stijene, spali meso i beskvasne hljebove. Anđeo Jahvin nato iščeze pred njegovim očima.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 6, 22, 'Tad Gideon vidje da je to bio Anđeo Jahvin i reče: \"Jao, Jahve, Gospode! Anđela Jahvina vidjeh licem u lice!\"');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 6, 23, 'Jahve mu odgovori: \"Mir s tobom! Ne boj se, nećeš umrijeti!\"');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 6, 24, 'Gideon podiže na tome mjestu žrtvenik Jahvi i nazva ga \"Jahve-Mir\". Žrtvenik još i danas stoji u Ofri Abiezerovoj.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 6, 25, 'Iste noći Jahve reče Gideonu: \"U svojega oca uzmi utovljena junca, junca od sedam godina, i razori Baalov žrtvenik i posijeci gaj pokraj njega.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 6, 26, 'Potom podigni žrtvenik Jahvi, Bogu svome, na vrhu te gorske stijene i dobro ga uredi. Uzmi junca i prinesi paljenicu na drvima Ašere što ih u gaju nasiječeš.\"');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 6, 27, 'Tada Gideon uze deset ljudi između svojih slugu i učini kako mu je zapovjedio Jahve. Ali kako se bojao svoje obitelji i građana, učini to noću.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 6, 28, 'Kad su građani sutradan poranili, a to razoren Baalov žrtvenik i gaj posječen pored njega, a junac žrtvovan kao paljenica na novom oltaru.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 6, 29, 'I pitahu jedni druge: \"Tko je to učinio?\" Ispitaše, istražiše pa rekoše: \"Gideon, Joašev sin, učini to.\"');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 6, 30, 'Tada građani rekoše Joašu: \"Izvedi sina da umre jer je razorio Baalov žrtvenik i posjekao gaj pored njega.\"');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 6, 31, 'Joaš odgovori svima koji stajahu oko njega: \"Zar ćete vi braniti Baala? Zar ćete ga vi spasavati? Tko brani Baala, bit će pogubljen prije sutrašnjeg dana. Ako je on bog, neka se sam brani od Gideona što mu je razorio žrtvenik.\"');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 6, 32, 'Toga dana prozvali su Gideona Jerubaal jer se govorilo: \"Neka sam Baal s njim obračuna što mu je srušio žrtvenik.\"');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 6, 33, 'Svi Midjanci, Amalečani i sinovi Istoka bijahu se sakupili i, prešavši Jordan, utaborili se u Jizreelskoj ravnici.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 6, 34, 'Duh Jahvin obuze Gideona i on zasvira u rog, a Abiezerov rod stade iza njega.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 6, 35, 'Posla on glasnike po svem plemenu Manašeovu te i oni stadoše iza njega. Posla glasnike i u pleme Ašerovo, Zebulunovo i Naftalijevo te im i oni krenuše u susret.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 6, 36, 'Gideon reče Bogu: \"Ako zaista hoćeš osloboditi Izraela mojom rukom, kao što si obećao,');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 6, 37, 'evo ću metnuti ovčje runo na gumno: ako bude rose samo na runu, a zemlja ostane suha, tada ću znati da ćeš mojom rukom izbaviti Izraela, kao što si obećao.\"');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 6, 38, 'I bi tako. Gideon urani sutradan te iscijedi rosu iz runa - punu zdjelu vode.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 6, 39, 'Opet Gideon reče Bogu: \"Ne razgnjevi se na me što ti progovaram još jednom. Dopusti mi da još ovaj put pokušam s runom: neka samo runo bude suho, a neka po svoj zemlji bude rosa!\"');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 6, 40, 'I Bog one noći učini tako: samo je runo ostalo suho, a po svoj zemlji pala rosa.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 7, 1, 'Urani Jerubaal, to jest Gideon, i sav narod bijaše s njim i utabori se kod En-Haroda; a tabor Midjanaca nalazio se na sjeveru od njegova, podno brijega More, u dolini.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 7, 2, 'Tada Jahve reče Gideonu: \"Previše je naroda s tobom a da bih predao Midjance u njegove ruke. Izrael bi se mogao pohvaliti i reći: \'Vlastita me ruka izbavila.\'');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 7, 3, 'Zato oglasi da narod čuje: \'Tko se boji i strahuje, neka se vrati.\'\" Gideon ih iskuša. Dvadeset i dvije tisuće ljudi iz naroda vrati se, a ostade ih deset tisuća.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 7, 4, 'Jahve reče Gideonu: \"Još je previše naroda. Povedi ih na vodu i ondje ću ih iskušati. Za koga ti kažem: \'Neka ide s tobom\', taj će s tobom ići. A za koga ti kažem: \'Neka ne ide s tobom\', taj neće ići.\"');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 7, 5, 'Gideon povede narod na vodu i Jahve mu reče: \"Koji bude laptao vodu jezikom kao što lapće pas, stavi ga na stranu. Koji klekne da pije, odvoji ga na drugu stranu.\"');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 7, 6, 'Onih koji su laptali vodu jezikom - prinoseći vodu rukom k ustima - bijaše tri stotine, a sav je ostali narod kleknuo da pije.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 7, 7, 'Tad Jahve reče Gideonu: \"Sa one tri stotine ljudi koji su laptali vodu ja ću vas izbaviti i predat ću Midjance u vaše ruke. Svi drugi neka se vrate svaki svojoj kući.\"');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 7, 8, 'Gideon tad naloži narodu da mu preda opskrbu i rogove, a onda otpusti Izraelce da ide svaki svome šatoru; zadrža samo one tri stotine. A midjanski se tabor prostirao niže njega u dolini.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 7, 9, 'One noći reče mu Jahve: \"Ustani, navali na tabor, jer ti ga predajem u ruke.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 7, 10, 'Ako se bojiš napasti, siđi najprije u tabor s Purom, momkom svojim;');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 7, 11, 'slušaj što govore; ohrabrit ćeš se i napast ćeš na tabor.\" On siđe sa svojim momkom Purom do prvih taborskih straža.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 7, 12, 'Midjanci, Amalečani i svi sinovi Istoka pali po dolini, brojni kao skakavci; njihovim devama ne bijaše broja, kao pijesku na obali mora.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 7, 13, 'Kad je Gideon došao, a to jedan baš pripovijedaše svome drugu što je sanjao: \"Usnuo sam kako se pogača ječmenog kruha kotrlja u midjanski tabor: dokotrlja se do jednog šatora i pogodi, a šator pade, prevrnu se.\"');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 7, 14, 'A drug mu odgovori: \"Nije to drugo nego mač Gideona, Joaševa sina, Izraelca. Bog mu je predao u ruke Midjance i sav tabor.\"');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 7, 15, 'Kada je Gideon čuo kako je onaj pripovjedio san i kako ga je drugi protumačio, baci se ničice, vrati se onda u tabor Izraelov i povika: \"Ustajte, jer vam je Jahve predao u ruke tabor midjanski!\"');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 7, 16, 'Gideon tad podijeli svoje tri stotine ljudi u tri čete. Svakome čovjeku dade u ruke rog, prazan vrč i luč u vrču:');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 7, 17, '\"Gledajte mene\", reče im, \"i činite što i ja! Kada dođem na rub tabora, činite što budem i ja činio!');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 7, 18, 'Kad zatrubim u rog ja i svi koji su sa mnom, tada i vi zasvirajte u rog oko sveg tabora i vičite: \'Za Jahvu i Gideona!\'\"');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 7, 19, 'Gideon i stotina ljudi što ga je pratila dođoše na rub tabora pri početku ponoćne straže; tek što su postavili straže, oni zatrubiše u rogove i razbiše vrčeve koje su imali u ruci.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 7, 20, 'Tako tri čete zasviraše u rogove i razbiše vrčeve; lijevom rukom držahu luči, a desnom rogove da trube i udariše vikati: \"Za Jahvu i Gideona!\"');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 7, 21, 'I svaki stajaše nepomično na svome mjestu uokrug tabora. Tada se probudi sav tabor i Midjanci vičući nagoše u bijeg.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 7, 22, 'Dok su one tri stotine trubile u rogove, učini Jahve te oni u taboru okrenuše mač jedan na drugoga. I sva se vojska razbježa do Bet-Hašita, prema Sartanu, do Abel-Meholske obale kod Tabata.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 7, 23, 'A Izraelci iz plemena Naftalijeva, Ašerova i iz svega plemena Manašeova sabraše se i pognaše Midjance.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 7, 24, 'Gideon posla glasnike po svoj Efrajimovoj gori da govore: \"Siđite pred Midjance i zauzmite prije njih sve gazove do Bet-Bara i Jordana.\" Svi se ljudi od plemena Efrajimova odazvaše i zauzeše gazove voda do Bet-Bara i Jordana.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 7, 25, 'I uhvatiše dva midjanska kneza, Oreba i Zeeba; Oreba ubiše na Orebovoj stijeni, a Zeeba kod Zeebova tijeska. Progonili su Midjance i donijeli Gideonu preko Jordana glavu Orebovu i Zeebovu.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 8, 1, 'Tada Efrajimovi ljudi rekoše Gideonu: \"Kako si postupio prema nama: nisi nas pozvao kada si pošao u boj protiv Midjanaca?\" I žestoko mu prigovoriše.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 8, 2, 'On im odgovori: \"Pa što sam ja učinio kad se usporedim s vama? Nije li Efrajimovo pabirčenje bolje od Abiezerove berbe?');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 8, 3, 'U vaše je ruke Jahve predao knezove midjanske, Oreba i Zeeba. Može li se usporediti moje djelo s onim što ste vi učinili?\" Na te riječi utiša se njihova srdžba prema njemu.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 8, 4, 'Kad je Gideon došao do Jordana, prijeđe ga, ali i on i tri stotine ljudi s njim bijahu iznemogli i gladni.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 8, 5, 'Stoga reče ljudima iz Sukota: \"Dajte kruha ljudima koji idu za mnom, iznemogli su. Ja gonim Zebaha i Salmunu, kraljeve midjanske.\"');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 8, 6, 'Ali mu sukotski glavari odgovoriše: \"Zar je Zebahova i Salmunina šaka već u tvojoj ruci da dademo kruha tvojoj vojsci?\"');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 8, 7, 'Gideon im reče: \"Dobro! Kad mi Jahve preda u ruke Zebaha i Salmunu, iskidat ću vam meso trnjem i dračem pustinjskim.\"');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 8, 8, 'Odatle ode u Penuel i zatraži isto od Penuelaca, a oni mu odgovore kao što su mu odgovorili i Sukoćani.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 8, 9, 'On zaprijeti i Penuelcima: \"Kad se vratim kao pobjednik, porušit ću ovu kulu.\"');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 8, 10, 'Zebah i Salmuna bijahu u Karkoru i vojska njihova s njima, oko petnaest tisuća ljudi, što ih god osta od vojske sinova Istoka; sto dvadeset tisuća ratnika bijaše palo.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 8, 11, 'Gideon pođe putem kojim prolaze oni što žive pod šatorima, istočno od Nobaha i Jogbohe, te potuče vojsku kad stajaše bezbrižna.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 8, 12, 'Zebah i Salmuna pobjegoše. On ih pogna i uhvati dva kralja midjanska, Zebaha i Salmunu. A vojsku im svu uništi.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 8, 13, 'Poslije bitke Gideon, sin Joašev, vrati se preko Hareške uzvisine.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 8, 14, 'I uhvati nekog momka iz Sukota te ga uze ispitivati; a on mu popisa imena sukotskih knezova i starješina, sedamdeset i sedam ljudi.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 8, 15, 'Potom Gideon ode Sukoćanima i reče: \"Evo Zebaha i Salmune zbog kojih ste mi se rugali govoreći: \'Je li Zebahova i Salmunina šaka već u tvojoj ruci pa da dademo kruha tvojim iznemoglim ljudima?\'\"');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 8, 16, 'I uhvati starješine gradske, nabra pustinjskog trnja i drača da ih oćute leđa Sukoćana.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 8, 17, 'Poruši Penuelsku kulu i pobi građane.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 8, 18, 'Onda reče Zebahu i Salmuni: \"Kakvi bijahu ljudi koje pobiste na Taboru?\" \"Bili su nalik na te\", odgovoriše. \"Svaki bijaše kao kraljev sin.\"');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 8, 19, '\"To su bila moja braća, sinovi moje matere\", reče Gideon. \"Tako mi Jahve, da ste ih ostavili na životu, ne bih vas ubio.\"');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 8, 20, 'Potom zapovjedi svom prvencu Jeteru: \"Ustani, pogubi ih!\" Ali dječak ne izvuče mača: bojao se, bijaše još mlad.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 8, 21, 'Tada rekoše Zebah i Salmuna: \"Ustani ti i navali na nas, jer kakav je čovjek, onakva mu i snaga.\" I ustavši, Gideon pogubi Zebaha i Salmunu i uze mjesečiće što su visjeli o vratu njihovih deva.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 8, 22, 'Izraelci rekoše Gideonu: \"Vladaj nad nama, ti, sin tvoj i unuk tvoj, jer si nas ti izbavio iz ruku Midjanaca.\"');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 8, 23, 'Ali im Gideon odgovori: \"Ne, neću ja vladati nad vama, a ni moj sin; Jahve će biti vaš vladar.\"');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 8, 24, 'Još im reče Gideon: \"Jedno samo od vas tražim: da mi svaki dade prsten od svog plijena.\" Pobijeđeni su nosili zlatne prstenove jer bijahu Jišmaelci.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 8, 25, '\"Vrlo rado\", odgovore oni. On nato razastrije svoj plašt, a svaki od njih baci od svog plijena po prsten.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 8, 26, 'Težina zlatnih prestenova što ih je zaiskao iznosila je tisuću i sedam stotina zlatnih šekela, osim mjesečića, naušnica i skrletnih haljina koje su nosili midjanski kraljevi i osim lančića što bijahu oko vrata njihovih deva.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 8, 27, 'Gideon načini od toga efod i postavi ga u svome gradu Ofri. I sav Izrael udari za njim u nevjeru i bijaše to zamka Gideonu i njegovu domu.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 8, 28, 'Tako su Midjanci bili poniženi pred Izraelcima. Više ne dizahu glave i zemlja bi mirna četrdeset godina, koliko još potraja vijek Gideonov.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 8, 29, 'Jerubaal, sin Joašev, otišao je i živio u svojoj kući.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 8, 30, 'Gideon je imao sedamdeset sinova koji su potekli od njega jer je imao mnogo žena.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 8, 31, 'Njegova inoča koja je živjela u Šekemu rodi mu sina komu nadjenu ime Abimelek.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 8, 32, 'Gideon, sin Joašev, umrije u dubokoj starosti; sahraniše ga u grobu njegova oca Joaša u Abiezerovoj Ofri.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 8, 33, 'Po Gideonovoj smrti Izraelci okrenuše u preljub s baalima te postaviše sebi za boga Baal-Berita.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 8, 34, 'Izraelci se nisu više sjećali Jahve, svoga Boga, koji ih je izbavio iz ruku svih njihovih neprijatelja unaokolo.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 8, 35, 'I nisu iskazivali zahvalnost domu Jerubaala Gideona za dobro što ga je učinio Izraelu.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 9, 1, 'Abimelek, sin Jerubaalov, otiđe u Šekem k braći svoje matere i reče njima i svemu rodu kuće svoje majke:');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 9, 2, '\"Upitajte sve šekemske građane: što vam je bolje - da nad vama vlada sedamdeset ljudi, svi sinovi Jerubaalovi, ili jedan čovjek? Sjetite se da sam ja od vašeg mesa i vaših kostiju!\"');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 9, 3, 'To braća njegove matere prenesoše ostalim šekemskim građanima i njihovo se srce prikloni Abimeleku jer govorahu: \"Naš je brat!\"');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 9, 4, 'I dadoše mu sedamdeset šekela srebra iz hrama Baal-Beritova; time Abimelek unajmi klatež i pustolove koji pođoše za njim.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 9, 5, 'Onda dođe u kuću svoga oca u Ofri i pobi svoju braću, sinove Jerubaalove, sedamdeset ljudi, na jednom kamenu. Izmakao mu je samo Jotam, najmlađi sin Jerubaalov jer se bijaše sakrio.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 9, 6, 'Tada se skupiše svi šekemski građani i sav Bet-Milo te postaviše Abimeleka za kralja kod hrasta koji stoji u Šekemu.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 9, 7, 'Kada su to dojavili Jotamu, ode on, stade na vrh gore Gerizima i povika im na sav glas: \"Čujte me, uglednici šekemski, tako vas čuo Bog!');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 9, 8, 'Jednom se zaputila stabla da pomažu kralja koji će vladati nad njima. Pa rekoše maslini: \'Budi nam kraljem!\'');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 9, 9, 'Odgovori im maslina: \'Zar da se svog ulja odreknem što je na čast bozima i ljudima da bih vladala nad drugim drvećem?\'');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 9, 10, 'Tad rekoše stabla smokvi: \'Dođi, budi nam kraljem!\'');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 9, 11, 'Odgovori im smokva: \'Zar da se odreknem slatkoće i krasnoga ploda svog da bih vladala nad drugim drvećem?\'');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 9, 12, 'Tad rekoše stabla lozi: \'Dođi, budi nam kraljem!\'');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 9, 13, 'Odgovori im loza: \'Zar da se odreknem vina što veseli bogove i ljude da bih vladala nad drugim drvećem?\'');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 9, 14, 'Sva stabla rekoše tad glogu: \'Dođi, budi nam kraljem!\'');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 9, 15, 'A glog odgovori stablima: \'Ako me doista hoćete pomazat\' za kralja, u sjenu se moju sklonite. Ako nećete, iz gloga će oganj planuti i sažeći cedrove libanonske!\'');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 9, 16, 'Sada, jeste li vjerno i čestito učinili kad ste izabrali Abimeleka za kralja? Jeste li se dobro ponijeli prema Jerubaalu i njegovoj kući? Jeste li mu uzvratili za djela što ih za vas učini?');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 9, 17, 'Moj se otac za vas borio izloživši svoj život te vas izbavio iz ruku Midjanaca,');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 9, 18, 'a vi danas ustaste protiv kuće moga oca, pobiste njegove sinove, sedamdeset ljudi na istom kamenu, i nad građanima Šekema učiniste kraljem Abimeleka, sina njegove robinje, zato što je vaš brat!');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 9, 19, 'Ako ste vjerno i pošteno danas radili prema Jerubaalu i prema njegovoj kući, radujte se s Abimelekom, a on neka se raduje s vama!');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 9, 20, 'Ako niste, neka oganj iziđe iz Abimeleka i sažeže građane Šekema i Bet-Mila i neka iziđe oganj iz građana Šekema i Bet-Mila i sažeže Abimeleka!\"');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 9, 21, 'Onda Jotam pobježe, skloni se i dođe u Beer, i ondje ostade, jer se bojao svoga brata Abimeleka.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 9, 22, 'Abimelek je vladao nad Izraelom tri godine.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 9, 23, 'Tada Bog posla duh razdora među Abimeleka i šekemske građane i šekemski se građani pobuniše protiv Abimeleka.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 9, 24, 'Bijaše to zato da bi se osvetio zločin počinjen nad sedamdeset Jerubaalovih sinova i da bi njihova krv pala na njihova brata Abimeleka, koji ih ubi, i na građane Šekema, koji mu pomogoše da ubije braću.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 9, 25, 'Hoteći mu napakostiti, šekemski su građani postavili zasjede po vrhovima planina i pljačkali svakoga tko bi prošao mimo njih onim putem. Javiše to Abimeleku.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 9, 26, 'Gaal, sin Ebedov, dođe sa svojom braćom i nastani se u Šekemu; a šekemski se građani pouzdaše u njega.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 9, 27, 'Otišavši u polje, trgali su u svojim vinogradima grožđe i gazili ga, a onda udarili u veselje; ušli su u hram svoga boga, jeli su, pili i proklinjali Abimeleka.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 9, 28, 'A Gaal, Ebedov sin, povika: \"Tko je Abimelek da mu služimo? Zar ne bi trebalo da Jerubaalov sin i Zebul, njegov namjesnik, služe ljude Hamora, Šekemova oca? Zašto da mi njemu služimo?');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 9, 29, 'O, kad bih imao ovaj narod u svojoj ruci, protjerao bih Abimeleka i rekao mu: \'Pojačaj svoju vojsku i iziđi u boj!\'\"');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 9, 30, 'A kad Zebul, gradski načelnik, doznade što je govorio Gaal, sin Ebedov, razgnjevi se.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 9, 31, 'Posla glasnike Abimeleku u Arumu i poruči mu: \"Evo, Gaal, sin Ebedov, došao u Šekem sa svojom braćom i bune građane protiv tebe.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 9, 32, 'Zato ustani noću, ti i narod što je s tobom, i stani u zasjedu u polju.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 9, 33, 'A ujutro, kad ograne sunce, digni se i udari na grad. Kada Gaal i njegovi ljudi iziđu preda te, ti učini s njima što ti prilike posavjetuju.\"');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 9, 34, 'Abimelek usta noću sa svim svojim ljudima i stade u zasjedu oko Šekema u četiri čete.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 9, 35, 'Kada je Gaal, sin Ebedov, izišao pred gradska vrata i zaustavio se, Abimelek i njegovi ljudi ustaše iz zasjede.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 9, 36, 'Gaal ugleda ljude i reče Zebulu: \"Eno silaze ljudi s gorskih vrhova.\" \"Od sjena gorskih vrhova\", odgovori mu Zebul, \"čine ti se ljudi.\"');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 9, 37, 'Opet progovori Gaal: \"Eno silaze ljudi s visa zvana Zemljin pupak, a četa jedna dolazi putem od Čarobnjačkog hrasta.\"');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 9, 38, 'Tad mu reče Zebul: \"Gdje ti je sada jezik? Pa ti si govorio: \'Tko je Abimelek da mu služimo?\' Nisu li ondje ljudi koje si prezirao? Iziđi sada i pobij se s Abimelekom.\"');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 9, 39, 'I Gaal iziđe na čelu šekemskih građana i pobi se s Abimelekom.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 9, 40, 'Abimelek potjera Gaala i on pobježe pred njim; i mnogi njegovi ljudi padoše mrtvi prije nego što su i došli do vrata.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 9, 41, 'Abimelek se tada vrati u Arumu, a Zebul potjera Gaala i njegovu braću i nije im više dao da ostanu u Šekemu.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 9, 42, 'Sutradan je narod izišao u polje i javiše to Abimeleku.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 9, 43, 'On uze svoju vojsku, podijeli je u tri čete i stade u zasjedu u polju. Kad bi vidio gdje ljudi izlaze iz grada, nasrnuo bi na njih i pobio ih.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 9, 44, 'Dok je Abimelek sa svojom četom udarao kod gradskih vrata, druge se dvije čete baciše na one koji bijahu u polju i tako ih pobiše.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 9, 45, 'Čitav je dan Abimelek opsjedao grad. Zauzevši ga, poubija sve stanovništvo, razori grad i posu sol po njemu.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 9, 46, 'Kad su to čuli gospodari Migdal Šekema, uđoše svi u tvrdi prostor hrama El-Berita.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 9, 47, 'Kada je Abimelek doznao da su se svi građani Migdal Šekema ondje sakupili,');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 9, 48, 'popne se na Salmonsku goru sa svom vojskom svojom. Uzevši u ruke sjekiru, odsječe granu od drveta, podiže je i metnu sebi na rame. A ljudima zapovjedi: \"Što vidjeste da sam ja učinio, učinite brzo i vi.\"');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 9, 49, 'I svi ljudi odsjekoše sebi po granu, a onda krenuše za Abimelekom, nabacaše granje na utvrdu i zapališe ga nad onima koji su se ondje nalazili. Tako izgiboše svi žitelji Migdal Šekema, oko tisuću ljudi i žena.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 9, 50, 'Potom Abimelek krenu na Tebes, opsjede ga i osvoji.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 9, 51, 'Bijaše ondje usred grada kula kamo su se sklonili svi ljudi i žene i svi uglednici gradski. Zatvorivši za sobom vrata, popeše se kuli na krov.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 9, 52, 'Abimelek dođe do kule i napade je. Dok je prilazio vratima kule da je zapali,');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 9, 53, 'neka žena baci mu žrvanj na glavu i razbi mu lubanju.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 9, 54, 'On brzo pozva svoga momka koji mu je nosio oružje i reče mu: \"Trgni mač i ubij me da se ne govori o meni: \'Žena ga je ubila.\'\" Njegov ga momak probode te on umrije.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 9, 55, 'Kad su Izraelci vidjeli da je Abimelek mrtav, svi se vratiše svojim kućama.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 9, 56, 'Tako je Bog svalio na Abimeleka zlo koje je on učinio svome ocu pobivši sedamdesetero svoje braće.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 9, 57, 'I sve zlo Šekemaca Bog svali na njihove glave i tako ih stiže kletva Jotama, sina Jerubaalova.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 10, 1, 'Poslije Abimeleka ustao je Tola, sin Pue, sina Dodova, da izbavi Izraela. On bijaše iz Jisakarova plemena, a živio je u Šamiru, u Efrajimovoj gori.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 10, 2, 'Bio je sudac Izraelu dvadeset i tri godine, a kad je umro, pokopali su ga u Šamiru.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 10, 3, 'Poslije njega ustao je Jair Gileađanin, koji je bio sudac Izraelu dvadeset i dvije godine.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 10, 4, 'Imao je trideset sinova koji su jahali na tridesetero magaradi i imali trideset gradova što se do dana današnjega zovu Sela Jairova, a nalaze se u gileadskoj zemlji.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 10, 5, 'Kad umrije Jair, pokopaše ga u Kamonu.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 10, 6, 'Izraelci su opet stali činiti ono što Jahvi nije po volji. Služili su baalima i aštartama, aramejskim bogovima i sidonskim bogovima, bogovima Moabaca, bogovima Amonaca i bogovima Filistejaca. A Jahvu su napustili i nisu mu više služili.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 10, 7, 'Tad planu Jahve gnjevom i predade ih u ruke Filistejcima i Amoncima.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 10, 8, 'Oni su od tada osamnaest godina satirali i tlačili Izraelce - sve Izraelce koji življahu s onu stranu Jordana, u zemlji amorejskoj, koja je u Gileadu.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 10, 9, 'Potom su Amonci prešli Jordan da zavojšte i na Judu, Benjamina i na Efrajima te se Izrael nađe u velikoj nevolji.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 10, 10, 'Tada zavapiše Izraelci Jahvi govoreći: \"Griješili smo prema tebi jer smo ostavili Jahvu, svoga Boga, da bismo služili baalima.\"');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 10, 11, 'A Jahve odgovori Izraelcima: \"Nisu li vas tlačili Egipćani i Amorejci, Amonci i Filistejci,');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 10, 12, 'Sidonci, Amalečani i Midjanci? Ali kad ste zavapili prema meni, nisam li vas izbavio iz njihovih ruku?');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 10, 13, 'Ali vi ostaviste mene i uzeste služiti drugim bogovima. Zbog toga vas neću više izbavljati.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 10, 14, 'Idite i vapite za pomoć onim bogovima koje ste izabrali! Neka vas oni izbave iz vaše nevolje!\"');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 10, 15, 'Izraelci odgovoriše Jahvi: \"Sagriješili smo! Čini s nama što ti drago, samo nas danas izbavi!\"');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 10, 16, 'I odstraniše tuđe bogove i počeše opet služiti Jahvi. A Jahve više ne mogaše trpjeti da Izraelci pate.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 10, 17, 'Kada su se Amonci sabrali i utaborili u Gileadu, skupiše se i Izraelci i utaboriše se u Mispi.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 10, 18, 'Tada narod i knezovi gileadski rekoše jedni drugima: \"Koji čovjek povede boj protiv Amonaca, neka bude poglavar svima koji žive u Gileadu.\"');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 11, 1, 'Gileađanin Jiftah bijaše hrabar ratnik. Rodila ga bludnica, a otac mu bijaše Gilead.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 11, 2, 'Ali je Gileadu i njegova žena rodila sinove, pa kada su sinovi te žene odrasli, otjeraše Jiftaha govoreći mu: \"Nećeš dobiti baštine od našeg oca jer si sin strane žene.\"');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 11, 3, 'Jiftah zato pobježe od svoje braće i naseli se u zemlji Tobu. Ondje se oko njega okupila hrpa beskućnika koji su s njim pljačkali.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 11, 4, 'Poslije nekog vremena Amonci zavojštiše na Izraela.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 11, 5, 'Kada su Amonci napali Izraela, krenuše gileadske starješine da trže Jiftaha u zemlji Tobu.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 11, 6, '\"Hodi\", rekoše mu, \"budi nam vojvoda da ratujemo protiv Amonaca.\"');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 11, 7, 'Ali Jiftah odgovori gileadskim starješinama: \"Niste li me vi mrzili i otjerali iz kuće moga oca? Zašto sada dolazite k meni kada ste u nevolji?\"');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 11, 8, 'Gileadske starješine rekoše Jiftahu: \"Zato smo sada došli tebi: pođi s nama, povedi rat protiv Amonaca i bit ćeš poglavar nama i svima u Gileadu.\"');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 11, 9, 'Jiftah upita gileadske starješine: \"Ako me odvedete natrag da ratujem protiv Amonaca te ako ih Jahve meni preda, hoću li biti vaš poglavar?\"');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 11, 10, '\"Jahve neka bude svjedokom među nama\", odgovore Jiftahu gradske starješine. \"Jao nama ako ne učinimo kako si rekao!\"');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 11, 11, 'I Jiftah ode sa starješinama Gileada. Narod ga postavi sebi za poglavara i vojvodu; a Jiftah je ponovio sve svoje uvjete pred Jahvom u Mispi.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 11, 12, 'Jiftah posla onda poslanike kralju Amonaca s porukom: \"Što ima između tebe i mene da si došao ratovati protiv moje zemlje?\"');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 11, 13, 'Kralj Amonaca odgovori Jiftahovim poslanicima: \"U vrijeme kada je izlazio iz Egipta, Izrael ja zaposjeo moju zemlju od Arnona do Jaboka i Jordana. Zato mi je sada dragovoljno vrati!\"');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 11, 14, 'Jiftah nanovo pošalje glasnike kralju Amonaca');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 11, 15, 'i poruči mu: \"Ovako govori Jiftah: Nije Izrael zaposjeo ni moapsku ni amonsku zemlju,');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 11, 16, 'nego je, izišavši iz Egipta, Izrael prešao pustinjom do Crvenog mora i došao u Kadeš.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 11, 17, 'Tada je poslao Izrael poslanike edomskom kralju s molbom: \'Htio bih proći kroz tvoju zemlju!\' Ali ga edomski kralj ne posluša. Poslao ih je i moapskom kralju, ali ni on ne htjede, te Izrael ostade u Kadešu.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 11, 18, 'Onda je preko pustinje zaobišao edomsku i moapsku zemlju i došao na istok od moapske zemlje. Narod se utaborio s one strane Arnona ne prelazeći granice Moaba, jer Arnon bijaše moapska međa.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 11, 19, 'Izrael posla zatim poslanike Sihonu, amorejskom kralju, koji je vladao u Hešbonu, i poruči mu: \'Pusti nas da prođemo kroz tvoju zemlju do mjesta koje nam je određeno.\'');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 11, 20, 'Ali Sihon ne dopusti Izraelu da prođe preko njegova područja, nego skupi svu svoju vojsku koja bijaše utaborena u Jahasu i zametnu boj s Izraelom.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 11, 21, 'Jahve, Bog Izraelov, predade Sihona i svu njegovu vojsku u ruke Izraelu, koji ih porazi, te Izrael zaposjede svu zemlju Amorejaca koji nastavahu to područje.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 11, 22, 'Zaposjeo je tako svu zemlju Amorejaca od Arnona do Jaboka i od pustinje do Jordana.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 11, 23, 'I sada kad je Jahve, Bog Izraelov, protjerao Amorejce pred svojim narodom Izraelom, ti bi nas htio odagnati?');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 11, 24, 'Zar ne posjeduješ sve što je tvoj bog Kemoš bio oteo starim posjednicima? Tako i sve ono što je Jahve, naš Bog, oteo starim posjednicima, mi sada posjedujemo!');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 11, 25, 'Po čemu si ti bolji od moapskog kralja Balaka, sina Siporova? Je li se i on sporio s Izraelom? Je li on ratovao protiv njega?');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 11, 26, 'Kada se Izrael nastanio u Hešbonu i u njegovim selima, u Aroeru i u njegovim selima, a tako i po svim gradovima na obali Jordana - evo, već tri stotine godina - zašto ih tada niste oteli?');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 11, 27, 'Nisam ja tebi skrivio nego ti meni činiš krivo ratujući protiv mene. Neka Jahve, Sudac, danas presudi između sinova Izraelovih i sinova Amonovih.\"');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 11, 28, 'Ali kralj Amonaca ne posluša riječi što mu ih je poručio Jiftah.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 11, 29, 'Duh Jahvin siđe na Jiftaha te on pođe kroz Gileadovo i Manašeovo pleme, prođe kroz gileadsku Mispu, a od gileadske Mispe dođe iza Amonaca.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 11, 30, 'I Jiftah se zavjetova Jahvi: \"Ako mi predaš u ruke Amonce,');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 11, 31, 'tko prvi iziđe na vrata moje kuće u susret meni kada se budem vraćao kao pobjednik iz boja s Amoncima bit će Jahvin i njega ću prinijeti kao paljenicu.\"');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 11, 32, 'Jiftah krenu protiv Amonaca da ih napadne i Jahve ih izruči u njegove ruke.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 11, 33, 'I porazi ih Jiftah od Aroera do blizu Minita - u dvadeset gradova - i sve do Abel Keramima. Bijaše to njihov veliki poraz; i Amonci bijahu poniženi pred Izraelom.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 11, 34, 'Kada se Jiftah vratio kući u Mispu, gle, iziđe mu u susret kći plešući uza zvuke bubnjeva. Bijaše mu ona jedinica, osim nje nije imao ni sina ni kćeri.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 11, 35, 'Ugledavši je, razdrije svoje haljine i zakuka: \"Jao, kćeri moja, u veliku me tugu bacaš! Zar mi baš ti moraš donijeti nesreću! Zavjetovah se Jahvi i ne mogu zavjeta poreći.\"');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 11, 36, 'Ona mu odgovori: \"Oče moj, ako si učinio zavjet Jahvi, učini sa mnom kako si se zavjetovao, jer ti je Jahve dao da se osvetiš Amoncima, svojim neprijateljima.\"');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 11, 37, 'Onda zamoli svog oca: \"Ispuni mi ovu molbu: pusti me da budem slobodna dva mjeseca; lutat ću po gorama sa svojim drugama i oplakivati svoje djevičanstvo.\"');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 11, 38, '\"Idi\", reče joj on i pusti je na dva mjeseca. Ona ode sa svojim drugama i oplakivaše na gorama svoje djevičanstvo.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 11, 39, 'Kada su prošla dva mjeseca, ona se vrati ocu i on izvrši na njoj zavjet što ga bijaše učinio. I nikada nije upoznala čovjeka. Otada je potekao običaj u Izraelu');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 11, 40, 'da svake godine odlaze Izraelove kćeri i oplakuju kćer Jiftaha Gileađanina četiri dana na godinu.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 12, 1, 'Uto se skupiše ljudi od Efrajimova plemena, prijeđoše Jordan put Safona i rekoše Jiftahu. \"Zašto si išao u boj protiv Amonaca a nas nisi pozvao da idemo s tobom? Spalit ćemo ti kuću i tebe!\"');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 12, 2, 'Jiftah im odgovori: \"Imali smo veliku parbu, ja i moj narod, i Amonci su nas teško tlačili. Pozvao sam vas u pomoć, ali me niste izbavili iz njihovih ruku.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 12, 3, 'Videći da mi nitko ne pritječe u pomoć, stavih svoj život na kocku, odoh sam na Amonce, i Jahve mi ih predade u ruke. Zašto ste, dakle, pošli danas da ratujete protiv mene?\"');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 12, 4, 'Tada skupi Jiftah sve Gileađane i udari na Efrajima. Gileađani potukoše Efrajima, jer su ovi govorili: \"Vi ste, Gileađani, Efrajimovi bjegunci koji ste živjeli usred Efrajima i Manašea.\"');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 12, 5, 'Zatim Gileađani presjekoše Efrajimu jordanske gazove, i kada bi koji bjegunac Efrajimov rekao: \"Pustite me da prijeđem\", Gileađani bi ga pitali: \"Jesi li Efrajimovac?\" A kada bi on odgovorio: \"Nisam\",');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 12, 6, 'oni bi mu kazali: \"Hajde reci: Šibolet!\" On bi rekao: \"Sibolet\" jer nije mogao dobro izgovoriti. Oni bi ga tada uhvatili i pogubili na jordanskim plićacima. Tako je poginulo četrdeset i dvije tisuće ljudi iz Efrajimova plemena.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 12, 7, 'Jiftah je sudio Izraelu šest godina. A kada je Gileađanin Jiftah umro, pokopaše ga u njegovu gradu, u Gileadu.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 12, 8, 'Poslije njega sudac u Izraelu bijaše Ibsan iz Betlehema.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 12, 9, 'On je imao trideset sinova i trideset kćeri, koje je poudao iz kuće, a trideset je snaha doveo izvana svojim sinovima. On je sudio Izraelu sedam godina.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 12, 10, 'Zatim umrije Ibsan i pokopaše ga u Betlehemu.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 12, 11, 'Poslije njega sudac u Izraelu bijaše Elon Zebulunac. On je sudio Izraelu deset godina.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 12, 12, 'Zatim umrije Zebulunac Elon i pokopaše ga u Ajalonu u zemlji Zebulunovoj.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 12, 13, 'Poslije njega sudac u Izraelu bijaše Abdon, sin Hilela iz Pireatona.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 12, 14, 'On je imao četrdeset sinova i trideset unuka koji su jahali na sedamdesetero magaradi. On je sudio Izraelu osam godina.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 12, 15, 'Zatim umrije Abdon, sin Hilela iz Pireatona, i pokopaše ga u Pireatonu u Efrajimovoj gori, u zemlji Šaalimu.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 13, 1, 'Izraelci su opet okrenuli da čine ono što Jahvi nije po volji i Jahve ih predade u ruke Filistejcima za čerdeset godina.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 13, 2, 'A bijaše neki čovjek iz Sore, od Danova plemena, po imenu Manoah. Žena mu bila nerotkinja i nije imala djece.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 13, 3, 'Toj se ženi ukaza Anđeo Jahvin i reče joj: \"Ti si neplodna i nisi rađala.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 13, 4, 'Ali se odsad pazi: da ne piješ ni vina ni žestoka pića i da ne jedeš ništa nečisto.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 13, 5, 'Jer, zatrudnjet ćeš, evo, i rodit ćeš sina. I neka mu britva ne prijeđe po glavi, jer će od majčine utrobe dijete biti Bogu posvećeno - bit će nazirej Božji i on će početi izbavljati Izraela iz ruke Filistejaca.\"');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 13, 6, 'Žena ode i kaza mužu: \"Božji čovjek došao k meni, lice mu kao u Božjeg anđela, puno dostojanstva. Nisam ga upitala odakle je došao, niti mi on kaza svog imena.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 13, 7, 'Ali mi je rekao: \'Ti ćeš začeti i roditi sina. Ne pij odsad ni vina ni žestoka pića i ne jedi ništa nečisto jer će ti dijete biti nazirej Božji od majčine utrobe do smrti.\'\"');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 13, 8, 'Tada se Manoah pomoli Jahvi i reče: \"Molim te, Gospode, neka Božji čovjek koga si jednom poslao dođe još jednom k nama i pouči nas što ćemo činiti s djetetom kad se rodi!\"');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 13, 9, 'Jahve usliši Manoaha i Anđeo Jahvin dođe opet k ženi dok je sjedila u polju. Manoah, muž njezin, ne bijaše kraj nje.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 13, 10, 'Žena brzo otrča da obavijesti muža i reče mu: \"Gle, ukazao mi se čovjek koji mi je došao onog dana.\"');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 13, 11, 'Manoah ustade, pođe za ženom i kada dođe k čovjeku, upita ga: \"Jesi li ti onaj što je govorio s ovom ženom?\" A on odgovori: \"Jesam.\"');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 13, 12, '\"Kada se ispuni ono što si rekao\", opet će Manoah, \"po kojim propisima i kako treba postupati s djetetom?\"');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 13, 13, 'Anđeo Jahvin odgovori Manoahu: \"Neka se žena čuva svega što sam joj zabranio.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 13, 14, 'Neka ne uživa ništa što dolazi od vinove loze, neka ne pije ni vina ni žestoka pića, neka ne jede ništa nečisto i neka se drži svega što sam joj zapovjedio.\"');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 13, 15, 'Tada reče Manoah Anđelu Jahvinu: \"Rado bismo te ustavili i pogostili jaretom.\"');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 13, 16, 'Anđeo Jahvin nato će Manoahu: \"Sve da me i ustaviš, ja ne bih jeo tvoga jela; nego ako želiš žrtvovati paljenicu, prinesi je Jahvi.\" Manoah, ne znajući da je to Anđeo Jahvin,');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 13, 17, 'reče tada Anđelu Jahvinu: \"Kako ti je ime, da te možemo častiti kada se ispuni što si obećao.\"');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 13, 18, 'Anđeo Jahvin odgovori mu: \"Zašto pitaš za moje ime? Ono je tajanstveno.\"');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 13, 19, 'Manoah nato uze jare i prinos te ga na stijeni kao paljenicu žrtvova Jahvi koji čini tajanstvene stvari.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 13, 20, 'Kada se poče dizati plamen sa žrtvenika k nebu, podiže se Anđeo Jahvin u tome plamenu. Kad to vidješe Manoah i njegova žena, padoše ničice.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 13, 21, 'Anđeo Jahvin nije se više ukazivao Manoahu i njegovoj ženi. Manoah tada shvati da je to Anđeo Jahvin.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 13, 22, '\"Zacijelo ćemo umrijeti\", reče ženi, \"jer smo vidjeli Boga.\"');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 13, 23, '\"Da nas je htio usmrtiti\", odgovori mu žena, \"ne bi iz naše ruke primio paljenice ni prinosa i ne bi nam dao da sve to vidimo niti da takvo što čujemo.\"');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 13, 24, 'Žena rodi sina i nadjenu mu ime Samson. Dijete odraste i Jahve ga blagoslovi.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 13, 25, 'I Jahvin duh bijaše s njim u Danovu taboru, između Sore i Eštaola.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 14, 1, 'I siđe Samson u Timnu i ugleda ondje djevojku među filistejskim kćerima.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 14, 2, 'Vrativši se, povjeri to ocu i majci: \"Opazio sam u Timni\", reče on, \"djevojku među filistejskim kćerima: oženite me njome.\"');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 14, 3, 'Otac i mati rekoše: \"Zar nema djevojaka među kćerima tvoga plemena i u svemu našem narodu da moraš uzeti ženu između neobrezanih Filistejaca?\" Ali Samson odgovori ocu: \"Oženi me njome jer mi ona omilje.\"');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 14, 4, 'Otac mu i majka nisu znali da je to od Jahve, koji je tražio zadjevicu s Filistejcima jer Filistejci u ono doba vladahu Izraelom.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 14, 5, 'Samson siđe tako u Timnu i kad dođe do timnjanskih vinograda, gle - odjednom preda nj iskoči mladi lav ričući.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 14, 6, 'Duh Jahvin zahvati Samsona, i on goloruk raskida lava kao što se raskida jare; ali ne reče ni ocu ni majci što je učinio.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 14, 7, 'Došavši, razgovori se s djevojkom i ona mu omilje.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 14, 8, 'Poslije nekog vremena, kada se vratio da je odvede, Samson skrenu da vidi mrtvog lava, a to u mrtvom lavu roj pčela i med.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 14, 9, 'On uze meda u ruke i jeo ga je idući putem. Kada se vratio k ocu i majci, dade ga i njima te i oni jedoše; ali im ne reče da ga je uzeo iz mrtvog lava.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 14, 10, 'Zatim ode ženi i ondje prirediše gozbu Samsonu; trajala je sedam dana, jer tako običavahu mladi ljudi.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 14, 11, 'Ali kako ga se bojahu, izabraše trideset svadbenih drugova da budu uza nj.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 14, 12, 'Tad im reče Samson: \"Hajde da vam zadam zagonetku. Ako je odgonetnete za sedam svadbenih dana, dat ću vam trideset truba finog platna i trideset svečanih haljina.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 14, 13, 'Ali ako je ne mognete odgonetnuti, vi ćete meni dati trideset truba platna i trideset svečanih haljina.\" \"Zadaj nam zagonetku\", odgovore mu oni, \"mi te slušamo.\"');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 14, 14, 'A on im reče: \"Od onog koji jede izišlo je jelo, od jakoga izišlo je slatko.\" Ali za tri dana nisu mogli odgonetnuti zagonetke.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 14, 15, 'Četvrtoga dana rekoše Samsonovoj ženi: \"Izvuci od muža na prijevaru rješenje zagonetke, ili ćemo spaliti i tebe i očev ti dom! Zar ste nas ovamo pozvali da nas oplijenite?\"');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 14, 16, 'Tada žena, uplakana, obisnu Samsonu oko vrata govoreći: \"Ti mene samo mrziš i ne ljubiš me. Zadao si zagonetku sinovima moga naroda, a meni je nisi objasnio.\" On joj odgovori: \"Nisam je objasnio ni ocu ni majci, a tebi da je kažem?\"');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 14, 17, 'Ona mu plakaše oko vrata sedam dana, koliko je trajala gozba. Sedmoga dana on joj kaza odgonetku: toliko je na nj navaljivala. I ona je odade sinovima svoga naroda.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 14, 18, 'Sedmoga dana, prije nego je zašlo sunce, ljudi iz toga grada rekoše Samsonu: \"Što ima slađe od meda i što ima jače od lava?\" A on im odgovori: \"Da niste s mojom junicom orali, ne biste zagonetke pogodili.\"');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 14, 19, 'Tada duh Jahvin dođe na njega, te on siđe u Aškelon i ondje pobi trideset ljudi, uze im odjeću i dade svečane haljine onima koji su odgonetnuli zagonetku, a onda se sav gnjevan vrati očevoj kući.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 14, 20, 'A Samsonovu ženu dadoše drugu koji mu bijaše svadbeni pratilac.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 15, 1, 'Poslije nekog vremena, o žetvi pšenice, Samson dođe da pohodi svoju ženu, donijevši joj kozle i reče: \"Želim ući k svojoj ženi u ložnicu.\" Ali mu tast ne dopusti.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 15, 2, '\"Mislio sam,\" reče mu on, \"da si je zamrzio, pa sam je dao tvome drugu. Ali zar njezina mlađa sestra nije ljepša od nje? Uzmi je namjesto one!\"');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 15, 3, 'Samson mu odgovori: \"Ovaj put neću biti krivac Filistejcima kad im učinim zlo.\"');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 15, 4, 'I ode Samson, ulovi tri stotine lisica, uze luči i, okrenuvši rep prema repu, stavi jednu luč među dva repa.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 15, 5, 'Tad zapali luči, pusti lisice u filistejska polja i popali im snopove, i nepokošeno žito, i vinograde, i maslinike.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 15, 6, 'Filistejci zapitaše: \"Tko je to učinio?\" Odgovoriše im: \"Samson, Timnjaninov zet, zato što mu tast oduze ženu i dade je njegovu drugu.\" Tad Filistejci odoše i spališe onu ženu i njenu obitelj.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 15, 7, '\"Kad ste to učinili\", reče im Samson, \"neću mirovati dok vam se ne osvetim.\"');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 15, 8, 'I sve ih izudara uzduž i poprijeko i žestoko ih porazi. Poslije toga ode u spilju Etamske stijene i ondje se nastani.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 15, 9, 'Tad Filistejci krenuše, utaboriše se u Judi i raširiše do Lehija.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 15, 10, '\"Zašto ste pošli na nas?\" - upitaše ih Judejci. A oni im odgovoriše: \"Pošli smo da svežemo Samsona i da mu učinimo kako je on učinio nama.\"');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 15, 11, 'Tri tisuće Judejaca odoše tada k spilji Etamske stijene i rekoše Samsonu: \"Zar ne znaš da Filistejci nama gospodare? Zašto si nam onda to učinio?\" On im odgovori: \"Kako oni meni, tako ja njima!\" A oni mu rekoše:');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 15, 12, '\"Dođosmo da te svežemo i predamo u ruke Filistejaca.\" \"Zakunite mi se\", reče im, \"da me nećete ubiti.\"');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 15, 13, '\"Ne\", odgovoriše mu, \"mi ćemo te samo svezati i predati u njihove ruke, ali te zacijelo ne želimo pogubiti.\" Onda ga svezaše sa dva nova užeta i odvedoše iz spilje.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 15, 14, 'Kad ga dovedoše u Lehi i kad Filistejci, vičući od radosti, pojuriše na nj, duh Jahvin zahvati ga i užeta na njegovim rukama postadoše kao laneni konci, spaljeni ognjem, i spadoše mu s ruku.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 15, 15, 'Spazivši još sirovu magareću čeljust, pruži on ruku, uze onu čeljust i pobi njome tisuću ljudi.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 15, 16, 'Tad reče Samson: \"Magarećom čeljusti gomile prebih, Magarećom čeljusti tisuću pobih.\"');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 15, 17, 'Rekavši to, baci čeljust iz ruke. Zato odonda ono mjesto zovu Ramat Lehi.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 15, 18, 'Kako bijaše jako ožednio, zavapi Jahvi govoreći: \"Ti si izvojštio ovu veliku pobjedu rukama svoga sluge, a zar sada moram umrijeti od žeđi i pasti u ruke neobrezanima?\"');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 15, 19, 'Tad Jahve rasiječe udubinu što je kod Lehija i voda poteče iz nje. Samson se napi i vrati mu se snaga, oživje mu duh. Zato su onom izvoru dali ime En Hakore, a postoji još i danas u Lehiju.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 15, 20, 'Samson bijaše sudac u Izraelu za vrijeme filistejske vladavine dvadeset godina.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 16, 1, 'Odatle ode Samson u Gazu; ondje vidje neku bludnicu i uđe k njoj.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 16, 2, 'Žiteljima Gaze javiše: \"Samson je došao ovamo!\" Opkoliše ga i vrebahu ga svu noć na gradskim vratima. Svu noć bijahu mirni. \"Pričekajmo do zore\", mišljahu, \"pa ćemo ga ubiti.\"');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 16, 3, 'Ali je Samson ležao samo do ponoći, a o ponoći ustade, dohvati gradska vrata s oba dovratnika, iščupa ih zajedno s prijevornicom, metnu ih na ramena i odnese na vrh gore koja je nasuprot Hebronu i položi ih ondje.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 16, 4, 'Poslije toga zamilova on neku ženu iz doline Soreka po imenu Delilu.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 16, 5, 'Filistejski knezovi dođoše k njoj i rekoše joj: \"Zavedi ga i doznaj gdje stoji njegova velika snaga, kako bismo ga mogli svladati pa da ga svežemo i učinimo nemoćnim. A dat će ti svaki od nas po tisuću i sto srebrnih šekela.\"');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 16, 6, 'Delila upita Samsona: \"Kaži mi gdje stoji tvoja velika snaga i čime bi se mogao svezati i svladati.\"');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 16, 7, 'Samson joj odgovori: \"Da me svežu sa sedam svježih još neosušenih žila od luka, onemoćao bih i postao kao običan čovjek.\"');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 16, 8, 'Filistejski knezovi donesu Delili sedam svježih još neosušenih žila i ona ga veza njima.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 16, 9, 'Kod nje u sobi bijaše zasjeda i ona viknu: \"Samsone, eto Filistejaca na te!\" On pokida žile kao što se prekine kučina kad se primakne ognju. I tako ne doznadoše za tajnu njegove snage.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 16, 10, 'Tad reče Delila Samsonu: \"Prevario si me i slagao mi. Ali mi sada kaži čime bi te trebalo vezati.\"');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 16, 11, 'On joj odgovori: \"Da me dobro svežu novim još neupotrijebljenim užetima, onemoćao bih i postao kao običan čovjek.\"');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 16, 12, 'Tada Delila uze nova užeta, sveza ga njima i viknu mu: \"Samsone, eto Filistejaca na te!\" Kod nje u sobi bijaše zasjeda, ali on prekide užeta na rukama kao da su konci.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 16, 13, 'Tada Delila reče Samsonu: \"Varaš me svejednako i lažeš mi. Kaži mi napokon čime bi te trebalo vezati.\" On joj odgovori: \"Da otkaš sedam pramenova moje kose na tkalačkom stanu i da ih zaglaviš klinom, onemoćao bih i postao kao običan čovjek.\"');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 16, 14, 'Ona ga uspava i otka sedam pramenova njegove kose na tkalačkom stanu, zabi klin i viknu mu: \"Eto Filistejaca na te, Samsone!\" On se probudi i istrgne i klin i tkalački stan. I nije otkrila tajnu njegove snage.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 16, 15, 'Delila mu reče: \"Kako možeš reći da me ljubiš kad tvoje srce nije sa mnom? Triput si me već prevario i nisi mi kazao gdje je tvoja velika snaga.\"');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 16, 16, 'Kako mu je svakog dana dodijavala molbama i mučila ga, njemu već dozlogrdje.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 16, 17, 'I otvori joj cijelo svoje srce: \"Nikada britva nije prešla po mojoj glavi jer sam od majčine utrobe nazirej Božji. Da me obriju, sva bi me snaga ostavila, onemoćao bih i postao bih kao običan čovjek.\"');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 16, 18, 'Delila tad shvati da joj je otvorio cijelo svoje srce; pozva filistejske knezove i reče im: \"Dođite sada jer mi je otvorio cijelo svoje srce.\" I filistejski knezovi dođoše k njoj i donesoše sa sobom novac.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 16, 19, 'Uspavavši Samsona na svojim koljenima, ona dozva čovjeka te mu obrija s glave sedam pramenova kose. Tako on poče slabiti i ostavi ga snaga.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 16, 20, 'Kad ona povika: \"Samsone, eto Filistejaca na te!\" on se probudi i pomisli: \"Izvući ću se kao i uvijek i oslobodit ću se.\" Ali nije znao da se Jahve od njega okrenuo.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 16, 21, 'Filistejci ga uhvatiše, iskopaše mu oči i odvedoše ga u Gazu. Okovaše ga dvostrukim mjedenim lancem te je okretao mlin u tamnici.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 16, 22, 'Ali kosa gdje mu je obrijaše počne opet rasti.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 16, 23, 'A knezovi se filistejski skupiše da prinesu veliku žrtvu svome bogu Dagonu i da se provesele. Govorahu oni: \"Bog naš predade nam u ruke Samsona, našeg neprijatelja.\"');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 16, 24, 'A narod, vidjevši ga, uze hvaliti svoga boga i klicati u njegovu čast govoreći: \"Bog naš predade nam u ruke Samsona, našeg neprijatelja, koji nam je zemlju pustošio i tolike naše usmrtio.\"');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 16, 25, 'Kad im se srce razigralo, povikaše: \"Dovedite Samsona da nas zabavlja!\" I dovedoše iz tamnice Samsona i on igraše pred njima; a onda ga postaviše među stupove.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 16, 26, 'Samson tada reče dječaku koji ga je vodio za ruku: \"Vodi me i pomozi mi da opipam stupove na kojima počiva zdanje da se naslonim na njih.\"');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 16, 27, 'A kuća bijaše puna ljudi i žena. Bijahu tu i svi filistejski knezovi, a na krovu tri tisuće ljudi koji su gledali kako Samson igra.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 16, 28, 'Samson zavapi Jahvi: \"Gospodine Jahve, spomeni me se i samo mi još sada podaj snagu da se Filistejcima odjednom osvetim za oba oka.\"');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 16, 29, 'I Samson napipa dva srednja stupa na kojima počivaše zdanje, oprije se o njih, desnom o jedan, a lijevom o drugi,');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 16, 30, 'i viknu: \"Neka poginem s Filistejcima!\" Nato uprije iz sve snage i sruši zdanje na knezove i na sav narod koji se ondje nalazio. Više ih ubi umirući nego što ih pobi za života.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 16, 31, 'Poslije dođoše njegova braća i sva kuća njegova oca, uzeše ga i odnesoše i pokopaše ga između Sore i Eštaola, u grobu Manoaha, oca njegova. On je sudio Izraelu dvadeset godina.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 17, 1, 'Bijaše u Efrajimovoj gori čovjek po imenu Mikajehu.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 17, 2, 'On reče majci: \"Tisuću i sto srebrnih šekela što su ti ukradeni i zbog kojih si izustila kletvu - uši su je moje čule - taj je novac kod mene, ja sam ga uzeo.\" Mati mu odgovori: \"Jahve te blagoslovio, sine moj!\"');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 17, 3, 'I Mikajehu vrati joj tisuću i sto srebrnih šekela. A mati mu njegova reče: \"Te sam novce posvetila Jahvi iz svoje ruke za tebe, sine moj, da se izdjela za to rezan ili ljeven idol. I evo, za to ih dajem.\"');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 17, 4, 'Majka uze dvije stotine srebrnih šekela i dade ih zlataru. On načini od njih rezani i ljeveni idol koji postaviše u Mikajehuovoj novoj kući.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 17, 5, 'On mu sagradi svetište, zatim načini efod i terafe te posveti jednoga od svojih sinova da mu bude svećenik.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 17, 6, 'U to vrijeme u Izraelu nije bilo kralja i svatko je radio po miloj volji.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 17, 7, 'Bijaše neki mladić iz Betlehema u Judi, iz Judina plemena; bio je levit i boravio je ondje kao došljak.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 17, 8, 'Taj čovjek ode iz grada Betlehema u Judi da se nastani na kakvu prikladnu mjestu kao došljak. Putujući, dođe u Efrajimovu goru do Mikine kuće.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 17, 9, 'Mika ga upita: \"Odakle dolaziš?\" \"Ja sam levit iz Judina Betlehema\", odgovori mu on, \"i putujem da se negdje nastanim.\"');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 17, 10, '\"Ostani kod mene\", reče mu Mika, \"i budi mi ocem i svećenikom, a ja ću ti davati deset srebrnih šekela na godinu, haljine i hranu.\" I levit uđe.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 17, 11, 'Levit je pristao da ostane u njega, i mladić mu bijaše kao jedan od sinova.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 17, 12, 'Mika posveti levita za svećenika; mladić je postao njegovim svećenikom i živio je u Mikinoj kući.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 17, 13, '\"Sad znam\", reče Mika, \"da će mi Jahve učiniti dobro kad imam levita za svećenika.\"');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 18, 1, 'U ono vrijeme ne bijaše kralja u Izraelu. Tada je Danovo pleme tražilo zemljište gdje da se naseli, jer mu do toga dana nije dopalo zemljište među Izraelovim plemenima.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 18, 2, 'Zato poslaše Danovci petoricu ljudi iz svoga plemena, ljude osobito hrabre iz Sore i Eštaola, da izvide i upoznaju zemlju. I rekoše im: \"Idite, istražite zemlju.\" I oni dođoše u Efrajimovu goru, do Mikine kuće, i ondje zanoćiše.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 18, 3, 'Kako bijahu blizu Mikine kuće, poznaše glas mladog levita; svratiše se onamo te ga upitaše: \"Tko te doveo ovamo? Što tu radiš? I što ćeš tu?\"');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 18, 4, 'A on im odgovori: \"Mika je učinio sa mnom tako i tako. On me najmio, a ja mu služim kao svećenik.\"');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 18, 5, '\"Upitaj Boga\", kazaše mu, \"da znamo hoće li nam uspjeti put koji smo poduzeli.\"');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 18, 6, '\"Idite u miru\", odgovori im svećenik, \"put na koji ste pošli po volji je Jahvi.\"');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 18, 7, 'Tada odoše ona petorica i stigoše u Lajiš. I vidješe da narod koji prebiva u njemu živi bez straha - po običaju Sidonaca - bezbrižno i mirno; imaju svega što rodi zemlja, daleko su od Sidonaca i nemaju nikakvih odnosa s Aramejcima.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 18, 8, 'Kad se vratiše svojoj braći u Sori i Eštaolu, braća ih upitaše: \"Što ste doznali?\"');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 18, 9, 'Oni odgovoriše: \"Na noge! Navalimo na njih! Zemlja koju smo vidjeli vrlo je dobra. O vi, lijenčine! Ne oklijevajte navaliti da osvojite tu zemlju.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 18, 10, 'Kada dođete, naći ćete ondje bezbrižan narod. Zemlja je prostrana. Bog je predao u vaše ruke mjesto koje ne oskudijeva ni u čemu što rodi zemlja!\"');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 18, 11, 'Tako je odande krenulo šest stotina naoružanih ljudi iz Danova plemena iz Sore i Eštaola.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 18, 12, 'Krenuli su i utaborili se u Kirjat Jearimu u Judi. Zato se to mjesto naziva do današnjeg dana Danovim taborom, a nalazi se na zapadu od Kirjat Jearima.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 18, 13, 'Odatle se zaputiše u Efrajimovu goru i dođoše do Mikine kuće.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 18, 14, 'A ona petorica što bijahu išla izviđati zemlju rekoše svojoj braći: \"Znate li da u ovim kućama imaju efod, terafe i ljeveni idol? Sada pazite što ćete raditi.\"');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 18, 15, 'Skrenuvši, oni uđoše u kuću mladog levita, u Mikinu kuću, i pozdraviše ga.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 18, 16, 'I dok je šest stotina naoružanih ljudi od Danovih sinova stajalo pred vratima,');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 18, 17, 'ona petorica što su išla izviđati zemlju uđoše, uzeše efod, terafe i ljeveni idol, a svećenik stajaše na pragu pokraj šest stotina naoružanih ljudi.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 18, 18, 'Kad su ušli u Mikinu kuću i uzeli efod, terafe, rezani i ljeveni idol, svećenik im reče: \"Što to radite?\"');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 18, 19, '\"Šuti\", odgovoriše mu. \"Stavi ruku na usta i hajde s nama. Bit ćeš nam otac i svećenik. Zar ti je bolje biti svećenikom u kući jednog čovjeka nego da budeš svećenikom jednog plemena i roda u Izraelu?\"');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 18, 20, 'Svećenik se obradova; uze on efod, terafe i rezani i ljeveni idol te ode s ljudima.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 18, 21, 'Vrativši se na put kojim su krenuli, odoše pustivši naprijed žene i djecu, stoku i dragocjenosti.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 18, 22, 'Bijahu već daleko od Mikine kuće, kad gle - ljudi što življahu u susjednim kućama, blizu Mikine, uzbunili se i krenuli u potjeru za Danovcima.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 18, 23, 'Kada počeše vikati za Danovim sinovima, oni se obazreše i rekoše Miki: \"Što ti je? Što ste se skupili?\"');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 18, 24, 'On odgovori: \"Uzeli ste moga boga koga sam sebi načinio i svećenika te odlazite. A što ostaje meni? I još mi kažete: \'Što ti je?\'\"');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 18, 25, 'Danovci mu odgovore: \"Da te više nismo čuli! Jer bi gnjevni ljudi mogli udariti na vas te bi upropastio sebe i svoju kuću!\"');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 18, 26, 'Danovci odoše dalje, a Mika, videći da su jači od njega, okrenu se i vrati kući.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 18, 27, 'I tako, uzevši boga što ga je načinio Mika i svećenika koga je najmio da mu služi, Danovci navališe na Lajiš, na mirne i spokojne ljude, te ih posjekoše oštrim mačem i spališe grad.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 18, 28, 'Nikoga ne bijaše da pomogne Lajišanima, jer bijahu daleko od Sidona i ne imahu nikakvih odnosa s Aramejcima, a osim toga grad bijaše u dolini koja se pruža prema Bet-Rehobu. Potom su opet sagradili grad i nastanili se u njemu.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 18, 29, 'I nazvaše ga Dan, po imenu svoga pretka Dana, koji se rodio Izraelu. A prije se grad zvao Lajiš.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 18, 30, 'I Danovci namjestiše sebi rezani i ljeveni idol. A Jonatan, sin Geršona, sina Mojsijeva, a zatim njegovi sinovi, bijahu svećenici Danova plemena do dana kada je narod bio odveden u izgnanstvo.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 18, 31, 'I stajaše im onaj rezani i ljeveni idol što ga je Mika načinio, i ostade ondje za sve vrijeme dokle Dom Božji bijaše u Šilu.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 19, 1, 'U ono vrijeme kad u Izraelu još ne bijaše kralja, živio neki čovjek, levit, kao došljak na kraju Efrajimove gore. Uzeo on za inoču ženu iz Judina Betlehema.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 19, 2, 'Rasrdivši se jednom, njegova ga inoča ostavi i vrati se u očevu kuću u Judin Betlehem i bila je ondje neko vrijeme, kakva četiri mjeseca.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 19, 3, 'Njen muž ode k njoj da je urazumi i dovede natrag; imao je sa sobom slugu i dva magarca. Dok je prilazio kući oca mlade žene, opazi ga tast i veselo mu iziđe u susret.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 19, 4, 'Tast, otac mlade žene, zadrži ga tri dana kod sebe te su jeli, pili i noćivali.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 19, 5, 'Četvrtoga dana uraniše; levit se spremao da ide, kad otac mlade žene reče zetu: \"Okrijepi se zalogajem kruha, pa onda idite.\"');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 19, 6, 'I tako sjedoše te su obojica jela i pila, a onda otac mlade žene reče čovjeku: \"Hajde, ostani još noćas i proveseli se!\"');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 19, 7, 'A kad čovjek ustade da pođe, tast uze navaljivati na njega te on još jednom ondje prenoći.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 19, 8, 'Petoga dana levit urani da krene, ali mu otac mlade žene reče: \"Okrijepi se najprije!\" Tako su proveli vrijeme jedući zajedno dok se nije nagnuo dan.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 19, 9, 'Muž ustade da ide, s inočom i slugom, kad mu tast, otac mlade žene, reče: \"Evo se dan nagnuo k večeru. Prenoći još ovdje i proveseli se, pa sutra uranite na put i vratite se svom šatoru.\"');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 19, 10, 'Ali čovjek ne htjede prenoćiti nego ustade i krenu. Tako je došao do pred Jebus, to jest Jeruzalem. S njim su bila dva osamarena magarca, inoča i sluga.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 19, 11, 'Kad su bili blizu Jeruzalema, dan se već jako nagnuo, pa sluga reče svome gospodaru: \"Hajde da se svratimo u taj jebusejski grad da tu prenoćimo.\"');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 19, 12, 'Ali mu gospodar odgovori: \"Nećemo se svraćati u grad tuđinaca koji nisu Izraelci, nego ćemo ići do Gibee.\"');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 19, 13, 'Još reče sluzi: \"Hajde, požurimo se da stignemo u koje od tih mjesta gdje ćemo prenoćiti, u Gibeu ili Ramu.\"');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 19, 14, 'I prođoše, nastavljajući put. Kad su stigli pred Benjaminovu Gibeu, sunce je zapadalo.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 19, 15, 'Oni skrenuše onamo da prenoće u Gibei. Ušavši, levit sjede na gradskom trgu, ali ne bijaše nikoga da ih primi u kuću da prenoće.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 19, 16, 'I dođe neki starac koji se predvečer vraćao s posla u polju. Bijaše to čovjek iz Efrajimove gore; življaše u Gibei kao došljak, a svi žitelji toga mjesta bijahu Benjaminovci.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 19, 17, 'Podigavši oči, ugleda putnika na gradskom trgu: \"Odakle dolaziš i kamo ćeš?\" - upita ga starac.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 19, 18, 'A on mu odgovori: \"Idemo od Judina Betlehema, na kraj Efrajimove gore. Ja sam odande. Išao sam u Judin Betlehem i vraćam se kući, ali nema nikoga da me primi k sebi u kuću.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 19, 19, 'Imam i slame i krme za svoje magarce, a i kruha i vina za sebe, za svoju ženu i za momka koji prati mene, tvoga slugu. Imamo svega dosta.\"');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 19, 20, '\"Mir s tobom i dobro mi došao\", odgovori starac. \"Moja je briga što ti je potrebno, samo nemoj noćiti na trgu.\"');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 19, 21, 'I uvede ga u svoju kuću i baci krme magarcima. Putnici su oprali noge, a onda jeli i pili.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 19, 22, 'Dok su se oni krijepili, gle, neki građani, opaki ljudi, okružiše kuću i, lupajući svom snagom o vrata, rekoše starcu, gospodaru kuće: \"Izvedi toga čovjeka što je ušao u tvoju kuću da ga se namilujemo.\"');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 19, 23, 'Tad iziđe domaćin iz kuće i reče im: \"Ne, braćo moja, ne činite zla. Taj je čovjek ušao u moju kuću, zato ne činite bezakonja.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 19, 24, 'Evo, moja je kći djevica, prepustit ću vam je. Činite od nje što vam drago, ali ovom čovjeku ne činite bezakonja.\"');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 19, 25, 'Ljudi ga ne htjedoše poslušati. Tad onaj čovjek uze inoču te im je izvede. Oni su je silovali i zlostavljali svu noć do jutra, a kad je zora zabijeljela, pustiše je.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 19, 26, 'Pred zoru žena dođe i pade na ulaz kuće onog čovjeka gdje je bio njen gospodar i ležala je ondje dok se nije razdanilo.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 19, 27, 'Njen je gospodar ujutro ustao, otvorio kućna vrata te izišao da nastavi put, kad spazi ženu, svoju inoču, kako leži na kućnim vratima s rukama na pragu.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 19, 28, '\"Ustani, idemo!\" - reče joj. Ali ne bijaše odgovora. Onda je uze, natovari na magarca i krenu na put da se vrati kući.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 19, 29, 'Kada je došao kući, trže nož i uze mrtvo tijelo inočino, rasiječe ga, ud po ud, na dvanaest dijelova te ih razasla u sve krajeve Izraela.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 19, 30, 'I tko god vidje reče: \"Ovakvo što se nije dogodilo od dana kada su Izraelci izašli iz Egipta do današnjeg dana. Valja o tome promisliti, vijećati i govoriti.\"');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 20, 1, 'Tada iziđe sav Izrael i sabra se sva zajednica kao jedan čovjek, od Dana do Beer Šebe i do gileadske zemlje, kod Jahve u Mispi.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 20, 2, 'Glavari svega naroda, svih Izraelovih plemena, dođoše na zbor Božjeg naroda, četiri stotine tisuća pješaka vičnih maču.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 20, 3, 'A Benjaminovci doznaše da su Izraelovi sinovi uzišli u Mispu. Sinovi Izraelovi zapitaše tada: \"Kažite nam kako se dogodio zločin!\"');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 20, 4, 'Levit, muž ubijene žene, uze riječ: \"Došao sam s inočom u Benjaminovu Gibeu da prenoćim.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 20, 5, 'A građani Gibee ustadoše na mene i noću opkoliše kuću u kojoj sam bio; mene su htjeli ubiti, a moju su inoču silovali tako da je umrla.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 20, 6, 'Zato sam uzeo mrtvu inoču, rasjekao je u komade i razaslao je u sve krajeve Izraelove baštine, jer su počinili sramotno djelo u Izraelu.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 20, 7, 'Izraelci, evo vas svih ovdje. Posavjetujte se i ovdje stvorite odluku.\"');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 20, 8, 'Sav narod ustade kao jedan čovjek govoreći: \"Neka se nitko od nas ne vraća svome šatoru, neka nitko ne ide svojoj kući!');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 20, 9, 'Nego da sada ovo učinimo Gibei: bacit ćemo ždrijeb;');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 20, 10, 'i uzet ćemo iz svih Izraelovih plemena po deset ljudi od stotine, po stotinu od tisuće i po tisuću od deset tisuća: oni će nositi hranu vojsci, onima koji će krenuti da kazne Benjaminovu Gibeu za sramotu što ju je počinila u Izraelu.\"');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 20, 11, 'I sabraše se svi Izraelci protiv onoga grada, udruženi kao jedan čovjek.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 20, 12, 'Tada Izraelova plemena razaslaše poslanike po svemu Benjaminovu plemenu s porukom: \"Kakav se to zločin dogodio među vama?');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 20, 13, 'Sada izručite one opake ljude što su u Gibei da ih smaknemo te iskorijenimo zlo iz Izraela!\" Ali Benjaminovci ne htjedoše poslušati svoje braće Izraelaca.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 20, 14, 'Benjaminovci se skupiše u Gibeu iz svojih gradova da se pobiju s Izraelcima.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 20, 15, 'A Benjaminovaca koji su došli iz raznih gradova nabrojiše toga dana dvadeset i šest tisuća ljudi vičnih maču, bez stanovnika Gibee.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 20, 16, 'Od svega toga naroda bijaše sedam stotina vrsnih ljudi, koji su bili ljevaci, i svaki je taj gađao kamenom iz praćke navlas točno, ne promašujući cilja.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 20, 17, 'A bijaše Izraelaca, osim sinova Benjaminovih, četiri stotine tisuća, sve ljudi vičnih maču i sve samih ratnika.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 20, 18, 'I sinovi Izraelovi, ustavši, pođoše u Betel da se posavjetuju s Bogom: \"Tko će od nas prvi u boj protiv Benjaminovaca?\" - zapitaše Izraelci. A Jahve odgovori: \"Neka Juda pođe prvi.\"');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 20, 19, 'Izjutra krenuše Izraelci te se utaboriše pred Gibeom.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 20, 20, 'Krenuvši u boj protiv Benjaminovaca, svrstaše se u bojni red pred Gibeom.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 20, 21, 'A Benjaminovci iziđoše iz Gibee i pobiše toga dana Izraelu dvadeset i dvije tisuće ljudi, koji ostadoše na onome polju.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 20, 22, 'Izraelci odoše i plakahu pred Jahvom sve do večeri, a onda upitaše Jahvu govoreći: \"Moramo li opet izići u boj protiv sinova svoga brata Benjamina?\" A Jahve im odgovori: \"Pođite na njega!\"');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 20, 23, 'Tada se vojska Izraelovih sinova ohrabri i nanovo svrsta u bojni red na istome mjestu gdje se svrstala prvog dana.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 20, 24, 'Drugoga se dana Izraelci približiše Benjaminovcima,');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 20, 25, 'ali toga drugog dana Benjamin iziđe iz Gibee pred njih i pobi Izraelcima još osamnaest tisuće ljudi, koji ostadoše na onome polju - sve sami poizbor ratnici, vični maču.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 20, 26, 'Tada svi Izraelci i sav narod odoše u Betel te plakahu i stajahu ondje pred Jahvom; cio su dan postili do večeri, prinosili paljenice i žrtve pomirnice pred Jahvom.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 20, 27, 'I tad opet Izraelci upitaše Jahvu, jer se u ono vrijeme Kovčeg saveza Božjega nalazio na tome mjestu,');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 20, 28, 'i Pinhas, sin Aronova sina Eleazara, posluživaše ga. Oni upitaše: \"Moramo li opet izići u boj protiv sinova našega brata Benjamina?\" A Jahve im odgovori: \"Pođite, jer ću ih sutra predati u vaše ruke.\"');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 20, 29, 'Tad Izrael postavi čete u zasjedu oko Gibee.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 20, 30, 'Trećega dana pođoše Izraelci protiv Benjaminovaca i svrstaše se u bojne redove pred Gibeom, kao i prije.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 20, 31, 'Benjaminovci iziđoše na njih, a oni ih odmamiše daleko od grada. Kao i prije, ubijahu Benjaminovci neke po putovima, od kojih jedan ide u Betel, a drugi u Gibeu; ubiše tako oko trideset Izraelaca.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 20, 32, 'I govorahu Benjaminovci: \"Evo ih tučemo kao i prvi put.\" A Izraelci rekoše: \"Bježimo dok ih ne odmamimo na otvorene putove, daleko od grada!\"');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 20, 33, 'Tada se glavnina Izraelove vojske pomakne sa svoga položaja i svrsta se u bojni red kod Baal Tamara, a zasjeda Izraelova iziđe iz svog skrovišta zapadno od Gibee.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 20, 34, 'Deset tisuća vrsnih ljudi izabranih iz sveg Izraela sleže se prema Gibei. Boj bijaše žestok. Benjaminovci nisu ni slutili da će ih zadesiti zlo.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 20, 35, 'I Jahve potuče Benjamina pred Izraelom toga dana te Izraelci pobiše Benjaminu dvadeset i pet tisuća i sto ljudi vičnih maču.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 20, 36, 'Benjaminovci vidješe da su pobijeđeni. Ljudi Izraelci bijahu se povukli sa svojih bojnih položaja pred Benjaminom uzdajući se u zasjedu što su je postavili oko Gibee.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 20, 37, 'A oni koji bijahu u zasjedi navališe brže na Gibeu i, ušavši u nju, posjekoše oštrim mačem sve stanovništvo.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 20, 38, 'Izraelovi se ljudi bijahu dogovorili s onima u zasjedi da ovi podignu iz grada stup dima kao znak:');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 20, 39, 'tada bi se Izraelovi ljudi povukli iz boja. Benjamin poče ubijati Izraelce i posiječe im tridesetak ljudi. \"Doista, padaju pred nama kao u prijašnjem boju.\"');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 20, 40, 'A kada se znak, stup dima, počeo dizati iz grada, obazre se Benjamin i vidje kako se plamen iz svega grada diže prema nebu.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 20, 41, 'Tada se Izraelovi ljudi okrenuše, a Benjaminovce obuze užas jer vidješe da ih je zadesilo zlo.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 20, 42, 'I pobjegoše ispred Izraelaca prema pustinji, ali im ratnici bijahu za petama, a oni što su dolazili iz grada ubijahu ih s leđa.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 20, 43, 'Tako su opkolili Benjamina i, goneći ga bez predaha, uništiše ga pred Gibeom na istočnoj strani.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 20, 44, 'I palo je Benjaminu osmnaest tisuća ljudi, sve samih vrsnih junaka.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 20, 45, 'Preživjeli se okrenuše i pobjegoše u pustinju prema Rimonskoj stijeni. Sijekući po cestama, Izraelci pobiše još pet tisuća ljudi; a onda pognaše Benjamina do Gideoma i pobiše još dvije tisuće ljudi.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 20, 46, 'Toga dana palo je Benjaminovaca dvadeset tisuća ljudi vičnih maču, sve samih vrsnih junaka.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 20, 47, 'Šest stotina ljudi pobjeglo je u pustinju prema Rimonskoj stijeni.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 20, 48, 'Izraelovi se ljudi vratiše potom Benjaminovcima, posjekoše oštrim mačem muškarce u gradovima, stoku i što se god našlo; i sve gradove na koje su naišli u Benjaminu popališe ognjem.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 21, 1, 'Izraelovi se ljudi bijahu ovako zakleli u Mispi: \"Nitko od nas neće dati svoju kćer za ženu Benjaminovu sinu.\"');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 21, 2, 'I ode narod u Betel i ostade ondje pred Bogom do večeri, naričući i jecajući.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 21, 3, 'Govorili su: \"Zašto se, o Jahve, Bože Izraelov, ova nesreća morala dogoditi da Izraelu danas nestane jednog plemena?\"');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 21, 4, 'Sutradan uraniše ljudi i sagradiše ondje žrtvenik; prinesoše paljenice i žrtve zahvalnice.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 21, 5, 'Tad zapitaše Izraelci: \"Ima li koga među svim plemenima Izraelovim da nije došao na zbor Jahvi?\" Jer su se svečano zakleli da će pogubiti onoga tko ne dođe u Mispu k Jahvi.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 21, 6, 'Izraelcima se sada sažalilo na brata Benjamina te rekoše: \"Danas je otkinuto jedno pleme od Izraela.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 21, 7, 'Kako ćemo dati žene onima koji su preostali kad se zaklesmo Jahvom da im nećemo dati svojih kćeri za žene?\"');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 21, 8, 'Zato zapitaše: \"Ima li koga među Izraelovim plemenima da nije došao k Jahvi u Mispu?\" I pronađe se da nije došao u tabor, na zbor, nitko od žitelja Jabeša u Gileadu.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 21, 9, 'Jer kada se narod prebrojio, ondje ne bijaše nikoga od žitelja Jabeša u Gileadu.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 21, 10, 'Zato zajednica posla onamo dvanaest tisuća hrabrih ljudi i zapovjedi im: \"Idite i posijecite oštrim mačem stanovnike Jabeša u Gileadu, zajedno sa ženama i djecom.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 21, 11, 'Evo što ćete učiniti: izručit ćete prokletstvu sve muškarce i sve žene što su dijelile postelju sa čovjekom, ali ćete sačuvati život djevicama.\" Tako i učiniše.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 21, 12, 'I našli su među stanovnicima Jabeša u Gileadu četiri stotine mladih djevojaka koje nisu dijelile postelje s čovjekom i doveli su ih u tabor u Šilu, koji je u Kanaanu.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 21, 13, 'Sva zajednica posla tada poslanike Benjaminovcima koji bijahu na Rimonskoj stijeni: objaviše im mir.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 21, 14, 'Tako se oporavi Benjamin. Dadoše im one među ženama iz Jabeša u Gileadu koje su ostavili na životu, ali ih ne bijaše dovoljno za sve.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 21, 15, 'Narodu se sažalio Benjamin što je Jahve načinio prazninu među Izraelovim plemenima.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 21, 16, '\"Kako ćemo naći žene onima što su ostali\", rekoše starješine zbora, \"kad su Benjaminu istrijebljene žene?\"');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 21, 17, 'Rekoše još: \"Kako sačuvati ostatak Benjaminu da se ne zatre jedno pleme iz Izraela?');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 21, 18, 'A ne možemo im dati svoje kćeri za žene.\" Jer se bijahu zakleli rekavši: \"Proklet bio onaj koji dade ženu Benjaminu!\"');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 21, 19, '\"Ali\", rekoše, \"svake se godine slavi u Šilu Jahvina svetkovina.\" Grad se nalazi na sjeveru od Betela, istočno od ceste koja vodi iz Betela u Šekem i južno od Lebone.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 21, 20, 'I zato svjetovaše Benjaminovce: \"Idite u zasjedu po vinogradima.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 21, 21, 'Pazite, pa kada djevojke iz Šila iziđu da plešu u kolu, vi iskočite iz vinograda, otmite svaki sebi ženu između šilskih kćeri pa otiđite u Benjaminovu zemlju.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 21, 22, 'A kad njihovi očevi ili njihova braća dođu da se prituže na vas, mi ćemo im reći: \'Oprostite im što je svaki uzeo po ženu kao u ratu; vi im ih niste dali, pa je tako krivnja na vama.\'\"');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 21, 23, 'Benjaminovci učiniše tako i od djevojaka koje oteše uzeše onoliki broj žena koliko bijaše njih. Onda odoše svaki na svoju baštinu, sagradiše opet gradove i naseliše se u njima.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 21, 24, 'Izraelci se tada raziđoše, svaki u svoje pleme i u svoj rod, i svaki se odande vrati na svoju baštinu.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 21, 25, 'U to vrijeme ne bijaše kralja u Izraelu i svatko je živio kako mu se činilo da je pravo.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (8, 1, 1, 'U ono vrijeme kada su vladali suci nastala glad u zemlji, pa iz Betlehema Judina jedan čovjek ode sa svojom ženom i sa svoja dva sina da se naseli na Moapskim poljanama.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (8, 1, 2, 'Taj se čovjek zvao Elimelek, žena mu Noemi, a dva njegova sina: Mahlon i Kiljon; svi bijahu Efraćani iz Betlehema Judina. Stigoše na Moapske poljane i tu se nastaniše.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (8, 1, 3, 'Tada Elimelek, Noemin muž, umrije, i ona osta sama sa svoja dva sina.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (8, 1, 4, 'Oni se oženiše Moapkama; jedna se zvala Orpa, a druga Ruta. I tu proboraviše deset godina.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (8, 1, 5, 'Onda umriješe i Mahlon i Kiljon, i tako Noemi osta i bez svoja dva sina i bez svoga muža.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (8, 1, 6, 'Tada se ona diže sa svojim snahama da ode s Moapskih poljana jer je čula na Moapskim poljanama da je Jahve pohodio narod svoj i dao mu kruha.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (8, 1, 7, 'Ode, dakle, ona iz mjesta gdje je živjela, a s njome i njezine snahe; krenuše na put da se vrate u zemlju Judinu.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (8, 1, 8, 'Noemi tada reče svojim dvjema snahama: \"Vratite se svaka domu majke svoje! Neka vam Jahve bude milostiv kao što vi bijaste pokojnicima i meni.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (8, 1, 9, 'Neka vam Jahve udijeli da obje nađete mir, svaka u domu svoga muža!\" I poljubi ih, a one briznuše u plač.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (8, 1, 10, 'I rekoše joj: \"Ne! Mi ćemo s tobom, tvome narodu.\"');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (8, 1, 11, 'Ali im reče Noemi: \"Vratite se natrag, kćeri moje! Zašto biste išle sa mnom? Zar ću još imati sinova u utrobi svojoj da vam budu muževi?');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (8, 1, 12, 'Vratite se natrag, kćeri moje, idite samo! Odviše sam stara, nisam za udaju. Pa i kad bih rekla: \'Imam nade da se udam još noćas i da rodim sinove\' -');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (8, 1, 13, 'zar biste mogle čekati da odrastu i zar biste radi njih ostale neudate? Ne, kćeri moje, tuga bi moja bila veća od vaše, jer se ruka Jahvina digla na me.\"');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (8, 1, 14, 'One i opet zaplakaše i zajecaše. Orpa poljubi svoju svekrvu i vrati se, a Ruta ostade s njom.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (8, 1, 15, 'Noemi joj reče: \"Eto vidiš, jetrva se tvoja vratila narodu svome i bogu svome: vrati se i ti za jetrvom svojom!\"');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (8, 1, 16, 'A Ruta joj odgovori: \"Nemoj me tjerati da te ostavim i da odem od tebe: jer kamo ti ideš, idem i ja i gdje se ti nastaniš, nastanit ću se i ja; tvoj narod moj je narod i tvoj Bog moj je Bog.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (8, 1, 17, 'Gdje ti umreš, umrijet ću i ja, gdje tebe pokopaju, pokopat će i mene. Neka mi Jahve uzvrati svakim zlom i nevoljom ako me što drugo, osim smrti, rastavi od tebe.\"');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (8, 1, 18, 'Videći gdje je tvrdo naumila da ide s njom, prestade je odvraćati.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (8, 1, 19, 'Tako su zajedno išle dok ne dođoše u Betlehem. A kad dođoše u Betlehem, sav se grad uzbudi zbog njih. \"Ma je li ovo Noemi?\" - pitahu žene.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (8, 1, 20, 'A ona im odgovaraše: \"Ne zovite me više Noemi nego me zovite Mara; jer me Šadaj gorčinom ispunio!');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (8, 1, 21, 'Odavde sam otišla punih ruku, a sad me Jahve vraća bez igdje ičega. Zašto me zovete Noemi kad Jahve posvjedoči protiv mene i Svemogući me u tugu zavi?\"');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (8, 1, 22, 'Tako se vrati Noemi s Rutom Moapkom, snahom svojom, s Moapskih poljana. Stigle su u Betlehem baš kad je počela žetva ječma.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (8, 2, 1, 'Noemi imaše rođaka po mužu, čovjeka vrlo imućna, iz porodice Elimelekove: zvao se Boaz.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (8, 2, 2, 'Tada Ruta Moapka reče Noemi: \"Htjela bih ići u polje pabirčiti klasje za onim u koga nađem milost.\" Ona joj odgovori: \"Hajde, kćeri moja!\"');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (8, 2, 3, 'I ode, dođe u polje te poče pabirčiti za žeteocima. A sreća je dovede u polje koje pripadaše Boazu, iz roda Elimelekova.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (8, 2, 4, 'I gle, dođe Boaz iz Betlehema. \"Jahve bio s vama!\" - pozdravi on žeteoce. A oni mu odgovoriše: \"Jahve te blagoslovio!\"');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (8, 2, 5, 'Boaz će nato momku koji je nadzirao žeteoce: \"Čija je ona mlada žena?\"');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (8, 2, 6, 'A momak koji bijaše nad žeteocima odgovori: \"Ono je mlada Moapka što je došla prateći Noemi s Moapskih poljana.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (8, 2, 7, 'Pitala je: \'Smijem li pabirčiti i kupiti klasje između snopova za žeteocima?\' I došla je, eto, i ostala od ranog jutra sve dosad; i samo je malo ušla u kuću.\"');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (8, 2, 8, 'Onda Boaz reče Ruti: \"Čuj me, kćeri moja, ne idi pabirčiti u drugoga nego se drži mojih njiva i mojih poslenika.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (8, 2, 9, 'Pazi na kojoj njivi oni žanju, pa idi za njima. A naredio sam momcima da te nitko ne dira. Kad ožedniš, idi k posudama i pij što moje sluge zahitaju.\"');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (8, 2, 10, 'Ona tada pade ničice, pokloni se do zemlje i reče: \"Čime sam stekla toliku milost u očima tvojim da mi posvećuješ pažnju kad sam tuđinka?\"');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (8, 2, 11, 'Boaz joj odgovori: \"Čuo sam što si sve učinila za svoju svekrvu poslije smrti svoga muža; kako si ostavila oca svoga, majku svoju i zavičaj svoj te došla u narod kojega do jučer ili prekjučer nisi poznavala.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (8, 2, 12, 'Neka ti Jahve plati sve što si učinila i neka ti udijeli pravu nagradu Jahve, Bog Izraelov, kad si došla da se pod krila njegova skloniš!\"');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (8, 2, 13, 'Ona preuze: \"Kad bih mogla uvijek nalaziti milost u tvojim očima, gospodaru, jer si me utješio i milostivo progovorio sluškinji svojoj, ako i nisam kao jedna od tvojih sluškinja.\"');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (8, 2, 14, 'Kad bijaše vrijeme ručku, Boaz joj reče: \"Hodi ovamo, jedi ovog kruha i umoči svoj zalogaj u ocat!\" Ona sjede pokraj žetelaca, a on stavi pred nju prženih zrna. Jela je i nasitila se i još joj preteče.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (8, 2, 15, 'Kad je ustala da pabirči dalje, Boaz zapovjedi svojim slugama: \"I među snopljem neka ona pabirči, a vi joj nemojte zanovijetati.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (8, 2, 16, 'Nego navlaš ispuštajte klasove iz svojih rukoveti i ostavljajte joj neka kÓupi i nemojte je koriti!\"');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (8, 2, 17, 'I tako je pabirčila sve do večeri, pa onda ovrše ono što je napabirčila: bijaše otprilike jedna efa ječma.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (8, 2, 18, 'Uze ona svoje i dođe u grad, a svekrva vidje koliko je napabirčila. Tada Ruta izvadi i dade joj što joj bijaše preteklo pošto se nasitila.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (8, 2, 19, 'Svekrva je upita: \"Gdje si pabirčila danas? Gdje si radila? Neka je blagoslovljen onaj koji je pogledao na te!\" Onda ona pripovjedi svekrvi kod koga je radila i reče: \"Čovjek u koga sam danas radila zove se Boaz.\"');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (8, 2, 20, 'Tada će Noemi svojoj snasi: \"Neka Jahve blagoslovi onoga koji ne uskraćuje dobrote svoje ni živima ni mrtvima!\" I dometnu Noemi: \"Taj je čovjek naš rod; jedan od naših skrbnika.\"');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (8, 2, 21, 'Ruta Moapka pripovjedi dalje: \"Još mi reče: \'Drži se mojih poslenika dokle ne požanju sve moje!\'\"');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (8, 2, 22, 'Noemi nato reče Ruti, snasi svojoj: \"Dobro je, kćeri moja, idi za njegovim poslenicima da ti ne bude neprilike na kojoj drugoj njivi.\"');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (8, 2, 23, 'I tako se držala poslenika Boazovih i pabirčila dokle ne požeše i ječam i pšenicu. I živjela je kod svekrve svoje.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (8, 3, 1, 'Onda će joj Noemi, svekrva njezina: \"Kćeri moja, da ti potražim mirno mjesto gdje bi mogla biti sretna?');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (8, 3, 2, 'Vidiš, Boaz, s čijim si se poslenicima našla, naš je rođak. Evo, on će noćas vijati ječam na gumnu.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (8, 3, 3, 'Umij se ti i namaži, lijepo se odjeni pa idi na gumno. Ne daj da te prepozna prije nego što se najede i napije.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (8, 3, 4, 'Kad bude lijegao, dobro pazi gdje će leći; pa kad legne, otiđi onamo, podigni mu pokrivač s nogu i lezi ondje! Tada će ti on reći što ti je činiti.\"');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (8, 3, 5, 'Ona joj odgovori: \"Učinit ću sve kako mi kažeš.\"');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (8, 3, 6, 'I siđe na gumno i učini sve kako joj je svekrva naredila.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (8, 3, 7, 'A Boaz, pošto je jeo i pio i tako se odobrovoljio, ode i leže kraj stoga. Onda ona priđe polako, otkri mu noge i leže.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (8, 3, 8, 'Kad bijaše oko ponoći, trže se čovjek i obrnu se, i gle: žena leži do njegovih nogu.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (8, 3, 9, '\"Tko si?\" - upita on, a ona odgovori: \"Ja sam Ruta, sluškinja tvoja. Raširi skut svoje haljine na sluškinju svoju jer si mi skrbnik.\"');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (8, 3, 10, '\"Blagoslovio te Jahve, kćeri moja!\" - dočeka on. \"Ovaj drugi tvoj čin milosti još je vredniji od prvoga, jer se nisi trudila da slijediš mlade poslenike, bili oni bogati ili siromašni.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (8, 3, 11, 'I zato se, kćeri moja, sada ne plaši: učinit ću ti sve što zatražiš, jer sva vrata moga naroda znaju da si čestita žena.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (8, 3, 12, 'Jest, uistinu sam ti skrbnik; ali postoji još bliži od mene.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (8, 3, 13, 'Ostani noćas; ako te sutra ujutro on kao skrbnik htjedne uzeti, dobro, neka te uzme; a ne htjedne li, uzet ću te ja, tako mi Jahve! Spavaj do jutra.\"');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (8, 3, 14, 'I spavaše ona do njegovih nogu do jutra. On ustade prije nego što mogaše čovjek čovjeka razaznati jer mišljaše: \"Ne treba da znaju da je žena bila na gumnu.\"');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (8, 3, 15, 'I kaza joj: \"Daj ogrtač što je na tebi i drži ga dobro.\" Ona ga pridrža, a on joj nasu šest mjerica ječma i naprti joj. I ode ona u grad.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (8, 3, 16, 'Kad je stigla, upita je svekrva: \"Što je s tobom, kćeri moja?\" A ona joj pripovjedi sve što je učinio za nju.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (8, 3, 17, 'I nadoveza: \"Ovih šest mjerica ječma dade mi kazujući: \'Ne smiješ se vratiti svekrvi praznih ruku.\'\"');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (8, 3, 18, 'Nato će joj Noemi: \"Budi mirna, kćeri moja, dok ne vidiš što će biti: jer neće on imati spokoja dok sve još danas ne dokrajči.\"');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (8, 4, 1, 'Boaz potom iziđe na gradska vrata i sjede ondje. I gle, naiđe onaj skrbnik o kome je govorio. I dozva ga Boaz: \"Ej, hodi ovamo i sjedni!\" Onaj dođe i sjede.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (8, 4, 2, 'Onda Boaz uze deset ljudi između starješina gradskih i reče: \"Posjedajte ovdje!\" I posjedaše.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (8, 4, 3, 'Zatim reče skrbniku: \"Noemi, koja se vratila s Moapskih polja, htjela bi prodati ono zemlje našega brata Elimeleka.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (8, 4, 4, 'Zato sam odlučio da se s tobom razgovorim i predložim ti: otkupi njivu pred ovima koji sjede ovdje i pred starješinama moga naroda. Ako je kaniš otkupiti, onda otkupi; ako ne kaniš, kaži mi da znam. Jer prije tebe nema nitko pravo na otkup; ja sam na redu tek iza tebe.\" A onaj reče: \"Hoću, otkupit ću je.\"');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (8, 4, 5, 'Onda kaza Boaz: \"Kad uzmeš zemlju iz ruke Noemi, treba da uzmeš i Rutu Moapku, pokojnikovu ženu, da se pokojniku sačuva ime na baštini.\"');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (8, 4, 6, 'Ali skrbnik reče: \"E, onda ne mogu biti otkupnik, da ne raspem svoje baštine. Otkupi ti po svome skrbničkom pravu jer ja ne mogu.\"');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (8, 4, 7, 'A bijaše od starine običaj u Izraelu: da se čemu potkrijepi valjanost otkupa ili zamjene, čovjek bi izuo sandalu i dao je drugome. To bijaše svjedočanstvo u Izraelu.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (8, 4, 8, 'Tako dakle i onaj skrbnik reče Boazu: \"Otkupi ti!\" te izu sandalu i dade mu je.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (8, 4, 9, 'Tada Boaz kaza starješinama i svemu narodu: \"Vi ste danas svjedoci da ja otkupljujem iz ruke Noemine sve ono što je bilo Elimelekovo, sve što je bilo Kiljonovo i Mahlonovo.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (8, 4, 10, 'Uz to uzimam za ženu Rutu Moapku, ženu Mahlonovu, da bi se sačuvalo ime pokojnikovo na baštini i da se ime njegovo ne bi zatrlo među braćom njegovom i nestalo s vrata zavičaja njegova. Vi ste danas tome svjedoci.\"');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (8, 4, 11, 'Sav narod koji se nalazio na vratima gradskim i starješine rekoše: \"Svjedoci smo! Dao Jahve da žena koja ulazi u dom tvoj bude kao Rahela i Lea, koje su obje podigle kuću Izraelovu! Obogati se u Efrati, a prodiči u Betlehemu!');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (8, 4, 12, 'Neka tvoja kuća, po potomstvu koje će ti dati Jahve od ove mlade žene, bude kao kuća Peresa, koga Judi rodi Tamara!\"');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (8, 4, 13, 'Tako Boaz uze Rutu i ona posta žena njegova. Uđe on k njoj i Jahve joj dade te ona zatrudnje i rodi sina.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (8, 4, 14, 'Onda žene rekoše Noemi: \"Blagoslovljen bio Jahve koji ti danas nije uskratio skrbnika! I prodičio njegovo ime u Izraelu!');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (8, 4, 15, 'On će biti tvoja utjeha i potpora starosti tvojoj; jer ga rodi snaha tvoja koja te ljubi i koja ti vrijedi više od sedam sinova.\"');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (8, 4, 16, 'Noemi uze dječaka, metnu ga sebi na krilo i bi mu odgojiteljicom.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (8, 4, 17, 'Susjede mu nadjenuše ime govoreći: \"Noemi se rodio sin!\" I prozvaše ga Obed; on je otac Jišaja, oca Davidova.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (8, 4, 18, 'A ovo je rodoslovlje Peresovo: Peres imade sina Hesrona,');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (8, 4, 19, 'Hesron Rama, Ram Aminadaba,');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (8, 4, 20, 'Aminadab Nahšona, Nahšon Salmona,');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (8, 4, 21, 'Salmon Boaza, Boaz Obeda,');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (8, 4, 22, 'Obed Jišaja, a Jišaj Davida.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 1, 1, 'Bio jedan čovjek iz Ramatajima, Sufovac iz Efrajimove gore, po imenu Elkana, sin Jerohama, sina Elihua, sina Tohua, sina Sufova, Efrajimljanin.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 1, 2, 'Imao je dvije žene: ime jednoj bijaše Ana, a drugoj bijaše ime Penina. Penina je imala djece, a Ana ih nije imala.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 1, 3, 'Taj je čovjek svake godine uzlazio iz svoga grada da se pokloni i prinese žrtvu Jahvi Sebaotu u Šilu. Ondje su bila dva sina Elijeva, Hofni i Pinhas, kao svećenici Jahvini.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 1, 4, 'Jednoga dana Elkana prinese žrtvu. On je obično svojoj ženi Penini i svim njezinim sinovima i kćerima davao više žrtvenih dijelova,');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 1, 5, 'a Ani je davao samo jedan dio, premda je više ljubio Anu, ali Jahve joj ne bijaše dao od srca poroda.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 1, 6, 'Uz to joj je suparnica njezina zanovijetala da je ponizi što joj Jahve ne bijaše dao od srca poroda.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 1, 7, 'Tako je bivalo svake godine kad god bi polazili u Dom Jahvin: Penina je zanovijetala Ani. Ana je stoga plakala i nije htjela jesti.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 1, 8, 'Tada joj reče Elkana, njezin muž: \"Zašto plačeš, Ana? I zašto ne jedeš? Zašto ti je srce rastuženo? Nisam li ti ja vredniji nego deset sinova?\"');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 1, 9, 'Ali Ana ustade, pošto su jeli i pili u sobi, i stupi pred Jahvu - a svećenik Eli sjeđaše na stolici na pragu svetišta Jahvina.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 1, 10, 'I ojađena u duši pomoli se Ana Jahvi, plačući gorko.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 1, 11, 'I zavjetova se ovako: \"Jahve Sebaote! Ako pogledaš na nevolju službenice svoje i opomeneš se mene i ne zaboraviš službenice svoje te dadeš službenici svojoj muško čedo, ja ću ga darovati Jahvi za sve dane njegova života i britva neće prijeći preko glave njegove.\"');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 1, 12, 'Tako se ona dugo molila pred Jahvom, a Eli je motrio usta njezina.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 1, 13, 'Ana govoraše u srcu; samo se usne njezine micahu, a glas joj se nije čuo. Zato Eli pomisli da je pijana.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 1, 14, 'I reče joj Eli: \"Dokle ćeš biti pijana? Otrijezni se od vina što je u tebi!\"');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 1, 15, 'Ali Ana odgovori i reče: \"Nisam pijana, gospodaru, nego sam velika nesretnica. Nisam pila ni vina ni opojna pića nego izlijevam dušu svoju pred Jahvom.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 1, 16, 'Ne sudi službenicu svoju kao ženu nevaljalu, jer sam od preteške tuge i žalosti tako dugo molila.\"');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 1, 17, 'Tada joj Eli odgovori ovako: \"Pođi u miru! A Bog Izraelov neka ti ispuni molitvu kojom si ga molila.\"');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 1, 18, 'A ona reče: \"Neka službenica tvoja nađe milost u očima tvojim!\" I žena ode svojim putem: jela je i lice joj nije više bilo tužno kao i prije.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 1, 19, 'Sutradan uraniše i pokloniše se Jahvi, a onda se vratiše i dođoše svojoj kući u Ramu. Elkana pozna Anu, ženu svoju, a Jahve je se opomenu.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 1, 20, 'Ana zatrudnje i, kad bi vrijeme, rodi sina koga nazva imenom Samuel, \"jer sam ga\", reče, \"izmolila od Jahve\".');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 1, 21, 'Poslije godine dana uziđe njezin muž Elkana sa svim domom svojim da prinese Jahvi godišnju žrtvu i da izvrši zavjet.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 1, 22, 'Ali Ana ne pođe s njim jer reče svome mužu: \"Neću poći dok se dijete ne odbije od prsiju, a onda ću ga odvesti da se pokaže pred Jahvom i da ostane ondje zauvijek.\"');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 1, 23, 'I odgovori joj Elkana, njezin muž: \"Čini kako misliš da je dobro; ostani dok ga ne odbiješ od prsiju; samo neka ti Jahve ispuni tvoju želju!\" I žena osta kod kuće dojeći sina svoga dok ga nije odbila od prsiju.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 1, 24, 'Čim ga je odbila od prsiju, povede ga sa sobom uzevši uz to trogodišnjeg junca, efu brašna i mijeh vina; i uvede ga u Dom Jahvin u Šilu. A dječak je bio još vrlo mlad.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 1, 25, 'Tada zaklaše junca, a majka dječakova pristupi k Eliju.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 1, 26, 'I reče Ana: \"Dopusti, gospodaru! Tako ti života tvoga, gospodaru, ja sam ona žena koja je stajala ovdje kraj tebe moleći se Jahvi.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 1, 27, 'Molila sam za ovo dijete, i Jahve mi je uslišio prošnju kojom sam ga prosila.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 1, 28, 'Zato i ja njega ustupam Jahvi za sve dane njegova života: ta isprošen je od Jahve.\" I pokloniše se ondje Jahvi.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 2, 1, 'Nato se Ana pomoli ovako: \"Kliče srce moje u Jahvi, raste snaga moja po Bogu mom. Šire mi se usta na dušmane moje, jer se radujem pomoći tvojoj.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 2, 2, 'Nitko nije svet kao što je Jahve (jer nema nikoga osim tebe), i nema hridi kao što Bog je naš.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 2, 3, 'Ne govorite mnogo hvastavih riječi, neka ne izlazi drskost iz usta vaših, jer Jahve je sveznajući Bog, pravo on prosuđuje djela.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 2, 4, 'Lomi se luk junacima, nemoćni se snagom opasuju.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 2, 5, 'Nekoć siti sad se za kruh muče, nekoć gladni ne gladuju više. Nerotkinja rađa sedam puta, majka brojne djece svježinu izgubi.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 2, 6, 'Jahve daje smrt i život, ruši u Šeol i odande diže.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 2, 7, 'Jahve čini uboga i bogata, obara čovjeka i uzvisuje.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 2, 8, 'Diže slabića iz prašine, iz bunjišta izvlači uboga, da ih posadi s knezovima i da im odredi počasna mjesta. Jer Jahvini su stupovi zemlje, na njih je stavio ovaj svijet.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 2, 9, 'Korake čuva svojih vjernika, zlikovce stiže propast u mraku (svojom snagom čovjek ne stječe pobjede).');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 2, 10, 'Koji se protive Jahvi, padaju, Svevišnji grmi s nebesa. Jahve sudi međama zemlje, daje silu svojemu kralju, uzdiže snagu pomazanika svoga.\"');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 2, 11, 'Potom se Ana vrati u Ramu, a dječak ostade da služi Jahvi pod okom svećenika Elija.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 2, 12, 'A Elijevi sinovi bijahu nevaljali ljudi jer nisu marili za Jahvu');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 2, 13, 'ni za prava svećenika nasuprot narodu: kad bi tko prinosio žrtvu, došao bi sluga svećenikov, dok se meso još kuhalo, s trorogom vilicom u ruci');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 2, 14, 'i zabadao njom u kotlić ili u lonac, u tavu ili u zdjelu, i što god bi se nabolo na vilicu, uzimao je svećenik sebi. Tako su činili svim Izraelcima što su dolazili onamo, u Šilo.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 2, 15, 'Tako i prije nego bi se spalilo salo, došao bi sluga svećenikov i rekao čovjeku koji je prinosio žrtvu: \"Daj mi mesa da ispečem svećeniku! On neće od tebe kuhana mesa nego samo sirovo.\"');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 2, 16, 'Ako bi mu čovjek tada rekao: \"Neka se najprije spali salo, a onda uzmi što ti duša želi\", on bi odgovorio: \"Ne, nego daj odmah! Ako ne daš, uzet ću silom.\"');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 2, 17, 'Grijeh je mladića bio vrlo velik pred Jahvom, jer su ljudi prezirali žrtvu koja se prinosila Jahvi.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 2, 18, 'A Samuel služaše pred Jahvom, još dijete u oplećku lanenom.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 2, 19, 'Mati bi mu njegova napravila dolamicu i donosila mu je svake godine kad bi dolazila s mužem svojim da prinese godišnju žrtvu.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 2, 20, 'A Eli bi blagoslovio Elkanu i njegovu ženu govoreći: \"Neka ti Jahve dade poroda od te žene na uzdarje za dar što ga je dala Jahvi.\" Nato bi se vraćali svojoj kući.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 2, 21, 'Jahve pohodi Anu i ona zatrudnje i rodi još tri sina i dvije kćeri. A mladi je Samuel rastao pred Jahvom.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 2, 22, 'Eli je bio već vrlo star, ali je ipak čuo sve što su njegovi sinovi činili svemu Izraelu.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 2, 23, 'I on im reče: \"Zašto radite takvo što da o tome moram slušati od svega ovog naroda?');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 2, 24, 'Nemojte tako, sinovi moji! Nisu dobri glasovi što ih čujem... Sablažnjujete narod Jahvin.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 2, 25, 'Ako čovjek zgriješi čovjeku, Bog će prosuditi. Ali ako čovjek zgriješi Jahvi, tko će se zauzeti za njega?\" Ali sinovi ne poslušaše glasa oca svojega, jer je Jahve odlučio da ih pogubi.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 2, 26, 'A mladi je Samuel sve više rastao u dobi i mudrosti i pred Jahvom i pred ljudima.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 2, 27, 'Uto dođe jedan Božji čovjek k Eliju i reče mu: \"Ovako govori Jahve: \'Nisam li se jasno objavio domu oca tvojega kad su bili u Egiptu, robovi u kući faraonovoj?');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 2, 28, 'Odabrao sam ih između svih plemena Izraelovih da mi budu svećenici, da se uspinju na moj žrtvenik, da prinose žrtve paljenice i da nose oplećak preda mnom: i dao sam domu oca tvojega sve paljene žrtve sinova Izraelovih.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 2, 29, 'Zašto gledaš zavidnim okom žrtvu i prinos što sam ih odredio za svoj Dom? I zašto paziš sinove svoje više nego mene, toveći ih najboljim dijelovima svih žrtvenih prinosa naroda moga Izraela?');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 2, 30, 'Zato sam - riječ je Jahve, Boga Izraelova - rekao doduše da će dom tvoj i dom oca tvojega stupati preda mnom dovijeka, ali sada - riječ je Jahvina - neka je to daleko od mene! Jer ja častim one koji mene časte, a koji mene preziru, bit će osramoćeni.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 2, 31, 'Gle, dolaze dani kad ću odsjeći mišicu tvoju i mišicu doma oca tvojega, tako da više neće biti starca u tvom domu.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 2, 32, 'Ti ćeš kivnim okom gledati na sve dobro kojim ću obasuti Izraela, i nikada više neće biti starca u tvom domu.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 2, 33, 'Zadržat ću ipak nekoga od tvojih kod oltara svoga, samo zato da mu sahnu oči i vene duša njegova, ali sve mnoštvo doma tvoga poginut će od ljudskoga mača.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 2, 34, 'Znak će ti biti ono što će stići oba tvoja sina, Hofnija i Pinhasa: obojica će poginuti istoga dana.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 2, 35, 'Ja ću sebi podići vjerna svećenika koji će raditi po mom srcu i po mojoj želji i njemu ću sazdati trajan dom, i on će svagda stupati pred pomazanikom mojim.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 2, 36, 'A koji god ostane od tvoga doma, dolazit će da mu se pokloni i da izmoli srebrn novčić ili hljeb kruha i kazat će: \'Molim te, primi me u kakvu god službu svećeničku, da imam zalogaj kruha.\'\"');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 3, 1, 'Mladi je Samuel služio Jahvi pod nadzorom Elijevim; u ono vrijeme Jahve je izrijetka govorio ljudima, a viđenja nisu bila česta.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 3, 2, 'No jednoga je dana Eli ležao u svojoj sobi - oči su njegove počele slabiti te više nije mogao vidjeti -');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 3, 3, 'svijećnjak Božji još ne bijaše ugašen i Samuel je spavao u svetištu Jahvinu, ondje gdje je bio Kovčeg Božji.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 3, 4, 'I Jahve zovnu: \"Samuele! Samuele!\" A on odgovori: \"Evo me!\"');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 3, 5, 'I otrča k Eliju i reče: \"Evo me! Ti si me zvao!\" A Eli reče: \"Ja te nisam zvao. Vrati se i spavaj!\" I on ode i leže.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 3, 6, 'I Jahve opet zovnu: \"Samuele! Samuele!\" Samuel usta, ode k Eliju i reče: \"Evo me! Ti si me zvao!\" A Eli odgovori: \"Ja te nisam zvao, sine! Vrati se i spavaj!\"');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 3, 7, 'Samuel još nije poznavao Jahve i još mu nikada ne bijaše objavljena riječ Jahvina.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 3, 8, 'I Jahve zovnu Samuela po treći put. On usta, ode k Eliju i reče: \"Evo me! Ti si me zvao!\" Sada Eli razumje da je Jahve zvao dječaka.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 3, 9, 'Zato reče Samuelu: \"Idi i lezi; a ako te zovne, ti reci: \'Govori, sluga tvoj sluša.\'\" I Samuel ode i leže na svoje mjesto.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 3, 10, 'I dođe Jahve i stade i zovnu kao prije: \"Samuele! Samuele!\" A Samuel odgovori: \"Govori, sluga tvoj sluša.\"');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 3, 11, 'Tada Jahve reče Samuelu: \"Evo, učinit ću nešto u Izraelu da će oba uha zujati svakome koji čuje.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 3, 12, 'U onaj ću dan ispuniti na Eliju sve što sam rekao za kuću njegovu, od početka do kraja.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 3, 13, 'Ti ćeš mu objaviti da osuđujem kuću njegovu dovijeka; on je znao da njegovi sinovi hule na Boga, a nije ih obuzdao.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 3, 14, 'Zato - kunem se domu Elijevu - neće oprati krivicu Elijeva doma nikakve žrtve ni prinosi dovijeka.\"');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 3, 15, 'Samuel je spavao do jutra, a onda otvori vrata Doma Jahvina. Samuel se bojao kazati viđenje Eliju.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 3, 16, 'Ali Eli zovnu Samuela govoreći: \"Samuele, sine!\" A on odgovori: \"Evo me!\"');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 3, 17, 'I on upita: \"Kakva je riječ koju ti reče? Nemoj mi zatajiti ništa! Tako ti Bog učinio zlo i dodao ti drugo ako mi zatajiš nešto od onoga što ti je kazao.\"');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 3, 18, 'Nato mu Samuel pripovjedi sve i ništa ne zataji od njega. A Eli reče: \"On je Jahve, neka čini što je dobro u očima njegovim!\"');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 3, 19, 'Samuel je rastao, a Jahve je bio s njim i nije pustio da ijedna od njegovih riječi padne na zemlju.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 3, 20, 'Sav Izrael, od Dana do Beer Šebe, spozna da je Samuel postavljen za proroka Jahvina.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 3, 21, 'Jahve se i dalje javljao u Šilu, jer se objavljivao Samuelu, [4:1] i riječ se Samuelova obraćala svemu Izraelu. (Eli je bio vrlo star, a njegovi su sinovi ustrajali u svome opakom postupku pred Jahvom.)');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 4, 1, 'U ono vrijeme skupiše Filistejci vojsku protiv Izraela. Izraelci iziđoše pred njih da se pobiju i utaboriše se kod Eben Haezera, dok su Filistejci udarili tabor kod Afeka.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 4, 2, 'Filistejci se svrstaše u bojni red protiv Izraela i nasta žestoka bitka. Izrael podleže Filistejcima: oko četiri tisuće ljudi pogibe na bojištu, na otvorenu polju.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 4, 3, 'Kad se narod vratio u tabor, rekoše starješine Izraelove: \"Zašto je Jahve dopustio da nas Filistejci danas pobijede? Pođimo u Šilo po Kovčeg saveza Jahvina neka dođe u našu sredinu i spasi nas iz ruku naših neprijatelja.\"');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 4, 4, 'Narod posla ljude u Šilo i donesoše odande Kovčeg saveza Jahve nad vojskama, koji stoluje nad kerubinima; oba sina Elijeva, Hofni i Pinhas, dođoše kao pratioci Kovčega.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 4, 5, 'Kad je Kovčeg Jahvin stigao u tabor, sav Izrael podiže gromki poklik, od kojega odjeknu zemlja.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 4, 6, 'Filistejci čuše taj gromki poklik i zapitaše: \"Što znači taj gromki poklik u taboru Hebreja?\" I shvatiše da je Kovčeg Jahvin stigao u njihov tabor.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 4, 7, 'Tada Filistejce obuze strah jer su govorili: \"Bog je došao u tabor!\" I povikaše: \"Jao nama! Tako nije bilo dosad.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 4, 8, 'Jao nama! Tko će nas izbaviti iz ruke toga silnog Boga? To je onaj koji je udario Egipat svakojakim nevoljama.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 4, 9, 'Ohrabrite se i budite junaci, Filistejci, da ne postanete robovi Hebrejima kao što su oni bili robovi vama; budite junaci i borite se!\"');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 4, 10, 'Tada Filistejci zametnuše bitku, Izraelci biše potučeni i pobjegoše svaki u svoj šator. Poraz je bio silan, jer je trideset tisuća pješaka poginulo na izraelskoj strani.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 4, 11, 'I Kovčeg Božji bi otet, i oba sina Elijeva poginuše, Hofni i Pinhas.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 4, 12, 'Jedan Benjaminovac otrča iz bojnih redova i stiže u Šilo još istoga dana, razderanih haljina i glave posute prašinom.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 4, 13, 'Kad je stigao, Eli je sjedio na svojoj stolici, pokraj vrata, pazeći na cestu, jer mu je srce strepilo za Kovčeg Božji. Taj dakle čovjek dođe da gradu donese glas, i nasta silna vika po svem gradu.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 4, 14, 'Kad je Eli čuo viku, upita: \"Kakva je to velika vika?\" Čovjek se požuri i dođe da obavijesti Elija. -');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 4, 15, 'A Eliju bijaše devedeset i osam godina, oči mu bijahu ukočene te ništa više nije vidio. -');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 4, 16, 'Čovjek reče Eliju: \"Dolazim s bojišta, danas sam utekao iz boja.\" Tada starac zapita: \"Što se dogodilo, sine?\"');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 4, 17, 'Glasnik odgovori: \"Izrael je pobjegao pred Filistejcima, bio je to težak poraz za narod i još su oba tvoja sina poginula i Kovčeg je Božji otet!\"');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 4, 18, 'Kad je spomenuo Kovčeg Božji, pade Eli sa stolice nauznak kraj vrata, slomi vrat i umrije, jer je bio star čovjek i težak. Bio je sudac u Izraelu četrdeset godina.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 4, 19, 'Njegova snaha, žena Pinhasova, bijaše trudna i pred porodom. Kad je čula vijest da je otet Kovčeg Božji i da je umro njezin svekar i poginuo njezin muž, savila se i rodila jer su je najednom uhvatili trudovi.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 4, 20, 'Kako je bila na samrti, rekoše joj žene koje stajahu oko nje: \"Budi bez brige jer si rodila sina!\" Ali ona ne odgovori niti obrati misli na to.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 4, 21, 'Djetetu nadjenu ime Ikabod govoreći: \"Otišla je slava od Izraela.\" Time je mislila na oteti Kovčeg Božji i na svoga svekra i svoga muža.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 4, 22, 'Zato reče: \"Otišla je slava od Izraela\" jer je otet Kovčeg Božji.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 5, 1, 'Kad su Filistejci osvojili Kovčeg Božji, prenesoše ga iz Eben Haezera u Ašdod.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 5, 2, 'Nato Filistejci uzeše Kovčeg Božji, unesoše ga u hram Dagonov i smjestiše pokraj Dagona.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 5, 3, 'Sutradan ujutro, kad su žitelji Ašdoda došli u hram Dagonov, gle, Dagon ležaše ničice na zemlji pred Kovčegom Jahvinim. Oni digoše Dagona i metnuše ga natrag na njegovo mjesto.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 5, 4, 'Ali kad su ujutro uranili, gle, Dagon opet ležaše ničice na zemlji pred Kovčegom Jahvinim; glava Dagona i obje njegove ruke ležahu odsječene na pragu: na mjestu je stajao samo Dagonov trup.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 5, 5, 'Zato Dagonovi svećenici i svi koji ulaze u Dagonov hram ne staju nogom na prag Dagonov u Ašdodu sve do današnjeg dana.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 5, 6, 'Tada ruka Jahvina teško pritisnu žitelje Ašdoda i natjera ih u silan strah: udari ih čirevima, Ašdod i njegovo područje.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 5, 7, 'Kad su ljudi u Ašdodu vidjeli što se dogodilo, rekoše: \"Kovčeg Boga Izraelova ne smije ostati kod nas jer se ruka njegova ispriječila protiv nas i protiv našega boga Dagona.\"');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 5, 8, 'Oni sazvaše i okupiše sve knezove filistejske k sebi i rekoše: \"Što da radimo s Kovčegom Boga Izraelova?\" A oni odgovoriše: \"U Gat neka se prenese Kovčeg Boga Izraelova.\" I prenesoše Kovčeg Boga Izraelova onamo.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 5, 9, 'Ali kad su ga prenijeli, ruka se Jahvina spusti na grad i nasta silna strava: udari građane, od najmanjega do najvećega, tako da im se pojaviše čirevi.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 5, 10, 'Oni tada poslaše Kovčeg Božji u Ekron. Ali kad je Kovčeg Božji stigao u Ekron, povikaše Ekronjani: \"Donesoše Kovčeg Boga Izraelova k meni da pomori mene i sav moj narod!\"');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 5, 11, 'Zato sazvaše i okupiše sve knezove filistejske i rekoše: \"Pošaljite natrag Kovčeg Boga Izraelova, neka se vrati na svoje mjesto da ne pomori mene i moj narod!\" Jer vladaše smrtna strava u svemu gradu, toliko ondje bijaše pritisnula ruka Božja.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 5, 12, 'Ljudi koji nisu pomrli bili su udareni čirevima i bolni se vapaj grada dizao do neba.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 6, 1, 'Kovčeg Jahvin bijaše sedam mjeseci u zemlji Filistejaca.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 6, 2, 'Tada Filistejci sazvaše svećenike i vrače i zapitaše ih: \"Što da radimo s Kovčegom Jahvinim? Poučite nas kako da ga pošaljemo natrag na njegovo mjesto.\"');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 6, 3, 'Oni odgovoriše: \"Ako hoćete vratiti Kovčeg Boga Izraelova, ne šaljite ga natrag prazna nego uza nj pošaljite i naknadnicu. Tada ćete se izliječiti i znat ćete zašto se njegova ruka nije okrenula od vas.\"');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 6, 4, 'Oni zapitaše: \"Kakvu naknadnicu treba da mu pošaljemo?\" Oni odgovoriše: \"Prema broju filistejskih knezova, pet zlatnih čireva i pet zlatnih štakora, jer je ista nevolja na vama i na vašim knezovima.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 6, 5, 'Načinite, dakle, likove svojih čireva i likove svojh štakora, koji vam zatiru zemlju, i dajte slavu Bogu Izraelovu. Možda će dignuti ruku svoju od vas, od vaših bogova i od vaše zemlje.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 6, 6, 'Zašto hoćete da vam srce otvrdne kao što je bilo otvrdnulo Egipćanima i faraonu? Kad ih je Bog pritisnuo, nisu li ih onda pustili da odu?');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 6, 7, 'Pripremite sada jedna nova kola i uzmite dvije krave dojilice koje još nisu nosile jarma: upregnite krave u kola, a njihovu telad odvedite natrag u staju.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 6, 8, 'Tada ćete uzeti Kovčeg Jahvin i staviti ga na kola. Zlatne predmete koje mu prinosite kao žrtvu naknadnicu stavit ćete u kovčežić kraj njega i tako neka pođe.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 6, 9, 'Zatim gledajte: ako krene prema svome kraju, put Bet Šemeša, onda je sigurno da nam je on zadao ovo veliko zlo; ako li ne krene tako, znat ćemo da nas nije udarila njegova ruka, nego da nam se to dogodilo slučajno.\"');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 6, 10, 'Ljudi učiniše tako: uzeše dvije krave dojilice i upregoše ih u kola, a njihovu telad zadržaše u staji.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 6, 11, 'Kovčeg Jahvin staviše na kola i kovčežić sa zlatnim štakorima i s likovima svojih čireva.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 6, 12, 'Krave udariše ravno cestom prema Bet Šemešu i jednako su išle istim putem, mukale su idući, a nisu skretale ni desno ni lijevo. Filistejski knezovi pratili su ih do granice Bet Šemeša.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 6, 13, 'Stanovnici Bet Šemeša upravo su bili zabavljeni žetvom pšenice u dolini. Digavši oči, ugledaše Kovčeg i potrčaše mu s veseljem u susret.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 6, 14, 'Kad su kola stigla na polje Jošue iz Bet Šemeša, zaustaviše se. Ondje bijaše velik kamen. Tada iscijepaše drvo od kola i prinesoše krave kao žrtvu paljenicu Jahvi.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 6, 15, 'Leviti bijahu skinuli Kovčeg Jahvin i kovčežić što je bio kraj njega i u kojem su bili zlatni predmeti i sve bijahu stavili na onaj veliki kamen. Stanovnici Bet Šemeša prinosili su toga dana žrtve paljenice i klali žrtve klanice Jahvi.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 6, 16, 'Kad je to vidjelo pet filistejskih knezova, vratiše se u Ekron isti dan.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 6, 17, 'A ovo je pet zlatnih čireva što su ih Filistejci poslali kao žrtvu naknadnicu Jahvi: za Ašdod jedan, za Gazu jedan, za Aškelon jedan, za Gat jedan, za Ekron jedan.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 6, 18, 'A zlatnih je štakora bilo toliko koliko svih gradova filistejskih, u svih pet kneževina, od utvrđenih gradova do otvorenih sela. Svjedok je veliki kamen na koji su položili Kovčeg Jahvin i koji još i danas stoji na polju Jošue iz Bet Šemeša.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 6, 19, 'Sinovi Jekonijini nisu se radovali sa stanovnicima Bet Šemeša kad su vidjeli Kovčeg Jahvin. Zato je Jahve pobio sedamdeset ljudi među njima. Narod je tugovao zbog toga što ga je Jahve tako teško iskušao.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 6, 20, 'Tada ljudi u Bet Šemešu rekoše: \"Tko bi mogao opstati pred Jahvom, ovim Svetim Bogom? Kome će otići sada od nas?\"');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 6, 21, 'I poslaše poslanike stanovnicima Kirjat Jearima i poručiše im: \"Filistejci su vratili Kovčeg Jahvin. Dođite i odnesite ga sebi.\"');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 7, 1, 'Tada dođoše ljudi iz Kirjat Jearima i odnesoše Kovčeg Jahvin sebi. Unesoše ga u kuću Abinadabovu, na uzvišici, i posvetiše njegova sina Eleazara da čuva Kovčeg Jahvin.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 7, 2, 'Od dana kad je Kovčeg bio postavljen u Kirjat Jearimu, prođe mnogo vremena - dvadeset godina - i sav je dom Izraelov uzdisao za Jahvom.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 7, 3, 'Tada Samuel progovori svemu domu Izraelovu ovako: \"Ako se od svega srca svoga vraćate Jahvi, uklonite iz svoje sredine tuđe bogove, baale i aštarte, i upravite srce svoje Jahvi i njemu jedinome služite. Tada će vas on izbaviti iz ruke Filistejaca.\"');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 7, 4, 'Sinovi Izraelovi ukloniše nato baale i aštarte i služahu jedinome Jahvi.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 7, 5, 'Samuel tada zapovjedi: \"Skupite sve sinove Izraelove u Mispu da se pomolim Jahvi za vas.\"');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 7, 6, 'Oni se dakle skupiše u Mispi; ondje su grabili vodu i izlijevali je pred Jahvom. I postili su onaj dan i priznavali: \"Sagriješili smo Jahvi!\" I Samuel je sudio sinovima Izraelovim u Mispi.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 7, 7, 'Kad su Filistejci čuli da su se sinovi Izraelovi skupili u Mispi, krenu filistejski knezovi da napadnu na Izraela. Kad to vidješe sinovi Izraelovi, uplašiše se Filistejaca.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 7, 8, 'I zamoliše sinovi Izraelovi Samuela: \"Ne prestaj vapiti za nas Jahvi, Bogu našemu, da nas izbavi iz ruke Filistejaca.\"');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 7, 9, 'Samuel uze jedno janje sisanče i prinese ga Jahvi kao žrtvu paljenicu i glasno se pomoli Jahvi za Izraela, i Jahve ga usliša.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 7, 10, 'Dok je Samuel prinosio žrtvu paljenicu, Filistejci su došli da udare na Izraela, ali Jahve toga dana zagrmi silnom grmljavinom na Filistejce i tako ih prestraši i smete da su podlegli Izraelu.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 7, 11, 'Ratnici izraelski iziđoše iz Mispe i potjeraše Filistejce, tukući ih sve do ispod Bet Kara.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 7, 12, 'A Samuel uze jedan kamen i postavi ga između Mispe i Ješane i nazva ga imenom Eben Haezer govoreći: \"Dovde nam je Jahve pomogao.\"');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 7, 13, 'Tako su Filistejci bili poniženi i nikada više ne navališe na zemlju Izraelovu, a ruka je Jahvina pritiskivala Filistejce svega vijeka Samuelova.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 7, 14, 'I gradove koje Filistejci bijahu zauzeli od Izraela vratiše se njemu, od Ekrona do Gata, i Izrael oslobodi njihovo područje iz ruke filistejske. I bio je mir između Izraela i Amorejaca.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 7, 15, 'Samuel je bio sudac u Izraelu svega svoga vijeka.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 7, 16, 'Svake je godine obilazio Betel, Gilgal i Mispu i u svim je tim mjestima sudio Izraelu.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 7, 17, 'Zatim se vraćao u Ramu, jer je ondje imao svoju kuću i ondje je sudio Izraelu. Ondje je podigao i žrtvenik Jahvi.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 8, 1, 'Kad je Samuel ostario, postavio je svoje sinove za suce u Izraelu.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 8, 2, 'Njegov prvorođenac zvao se Joel, a drugi sin Abija; oni su bili suci u Beer Šebi.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 8, 3, 'Ali sinovi nisu išli stopama očevim: gledali su na svoj dobitak, primali mito i izvrtali pravicu.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 8, 4, 'Tada se skupiše sve starješine izraelske i dođoše k Samuelu u Ramu.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 8, 5, 'I rekoše mu: \"Eto, ti si ostario, a tvoji sinovi ne idu tvojim stopama. Postavi nam, dakle, kralja da nam vlada, kao što je to kod svih naroda.\"');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 8, 6, 'Ali Samuelu nije bilo drago što su rekli: \"Daj nam kralja da nam vlada!\" Zato se Samuel pomoli Jahvi.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 8, 7, 'A Jahve reče Samuelu: \"Poslušaj glas naroda u svemu što od tebe traži, jer nisu odbacili tebe, nego su odbacili mene, ne želeći da ja kraljujem nad njima.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 8, 8, 'Sve što su činili meni od onoga dana kad sam ih izveo iz Egipta pa do današnjega dana - ostavili su mene i služili tuđim bogovima - tako oni čine i tebi.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 8, 9, 'Sada, dakle, poslušaj njihov zahtjev, ali ih svečano opomeni i pouči o pravima kralja koji će vladati nad njima.\"');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 8, 10, 'Samuel ponovi sve Jahvine riječi narodu koji je od njega tražio kralja.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 8, 11, 'I reče: \"Ovo će biti pravo kralja koji će kraljevati nad vama: uzimat će vaše sinove da mu služe kod bojnih kola i kod konja i oni će trčati pred njegovim bojnim kolima.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 8, 12, 'Postavljat će ih za tisućnike i pedesetnike; orat će oni njegovu zemlju, žeti njegovu žetvu, izrađivati mu bojno oružje i opremu za njegova bojna kola.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 8, 13, 'Uzimat će kralj vaše kćeri da mu priređuju mirisne pomasti, da mu kuhaju i peku.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 8, 14, 'Uzimat će najbolja vaša polja, vaše vinograde i vaše maslinike i poklanjat će ih svojim dvoranima.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 8, 15, 'Uzimat će desetinu od vaših usjeva i vaših vinograda i davat će je svojim dvoranima i svojim službenicima.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 8, 16, 'Uzimat će vaše sluge i vaše sluškinje, vaše najljepše volove i magarce i upotrebljavat će ih za svoj posao.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 8, 17, 'Uzimat će desetinu od vaše sitne stoke, a vi sami postat ćete mu robovi.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 8, 18, 'I kad jednoga dana budete vapili za pomoć zbog kralja koga ste sami izabrali, Jahve vas neće uslišati u onaj dan!\"');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 8, 19, 'Narod nije htio poslušati Samuelova glasa nego reče: \"Ne! Hoćemo da kralj vlada nad nama!');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 8, 20, 'Tako ćemo i mi biti kao svi narodi: sudit će nam naš kralj, bit će nam vođa i vodit će naše ratove.\"');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 8, 21, 'Kad je Samuel čuo što narod govori, kaza sve Jahvi.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 8, 22, 'A Jahve reče Samuelu: \"Poslušaj njihovu želju i postavi im kralja!\" Tada Samuel reče Izraelcima: \"Vratite se svaki u svoj grad!\"');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 9, 1, 'Živio u ono vrijeme jedan čovjek u Benjaminovu plemenu po imenu Kiš, sin Abiela, sina Serora, sina Bekorata, sina Afijahova; bio je iz plemena Benjaminova, čovjek imućan.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 9, 2, 'Imao je sina po imenu Šaula, koji je bio mlad i lijep. Među sinovima Izraelovim nije bilo ljepšega čovjeka od njega: za glavu bijaše viši od svega naroda.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 9, 3, 'Uto se Kišu, Šaulovu ocu, izgubilo nekoliko magarica, pa Kiš reče svome sinu Šaulu: \"Uzmi sa sobom jednoga momka pa ustani i idi tražiti magarice!\"');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 9, 4, 'I prođoše oni Efrajimovu goru i prođoše zemlju Šališu, ali ne nađoše ništa; prođoše zemlju Šaalim, ali magarica ne bijaše ondje; prođoše i zemlju Benjaminovu, ali ne nađoše ništa.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 9, 5, 'Kad su došli u zemlju Suf, reče Šaul momku koji ga je pratio: \"Hajde, vratimo se da se ne bi otac okanio magarica i zabrinuo se za nas!\"');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 9, 6, 'A on mu odgovori: \"Eno, u onom ondje gradu živi čovjek Božji; to je vrlo ugledan čovjek: što god rekne, sve se zacijelo ispunja. Pođimo, dakle, k njemu, možda će nas uputiti u ono zbog čega smo pošli na put.\"');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 9, 7, 'A Šaul reče svome momku: \"Ako zaista pođemo onamo, što ćemo ponijeti čovjeku? Kruha je nestalo u našim torbama, nemamo dara da ponesemo čovjeku Božjem. Što mu možemo dati?\"');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 9, 8, 'A momak opet progovori i reče Šaulu: \"Gle, imam u ruci četvrt šekela srebra: dat ću ga Božjem čovjeku da nas uputi kamo bismo išli.\"');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 9, 9, 'Nekoć se u Izraelu, kad bi išli pitati Boga za savjet, govorilo: \"Hajde, pođimo k vidiocu!\" Jer koga danas zovu prorokom nekoć se zvao vidjelac. -');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 9, 10, 'Šaul odvrati svome momku: \"Dobro veliš. Hajdemo!\" I krenuše u grad gdje je živio čovjek Božji.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 9, 11, 'Kad su se penjali usponom prema gradu, sretoše djevojke koje su izašle da zahvate vode. I zapitaše ih: \"Je li gore vidjelac?\" -');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 9, 12, 'One im odgovore ovako: \"Jest, vidjelac je pred vama. Upravo je stigao u grad, jer danas narod ima žrtvu na uzvišici.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 9, 13, 'Čim uđete u grad, naći ćete ga još prije nego što se popne na uzvišicu da sudjeluje na žrtvenoj gozbi. Narod neće jesti dok on ne dođe, jer on mora blagosloviti žrtvu, a onda će tek uzvanici jesti. Zato idite odmah gore, jer ćete ga sada još naći.\"');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 9, 14, 'Oni otiđoše gore u grad. Kad su ulazili na vrata, Samuel ih susrete polazeći na uzvišicu.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 9, 15, 'A dan prije nego što je Šaul došao bijaše Jahve objavio Samuelu:');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 9, 16, '\"Sutra u ovo doba poslat ću k tebi čovjeka iz Benjaminove zemlje. Ti ćeš ga pomazati za kneza nad mojim narodom Izraelom. On će izbaviti moj narod iz ruke filistejske. Vidio sam nevolju svoga naroda i njegov je vapaj dopro do mene.\"');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 9, 17, 'A kad je Samuel ugledao Šaula, Jahve mu progovori: \"Evo ti čovjeka za koga ti rekoh: \'Taj će vladati nad mojim narodom.\'\"');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 9, 18, 'Šaul pristupi Samuelu na vratima i reče: \"Daj mi kaži gdje je vidiočeva kuća.\"');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 9, 19, 'A Samuel odgovori Šaulu: \"Ja sam vidjelac. Pođi preda mnom na uzvišicu, danas ćete sa mnom jesti. Sutra ću te ujutro otpustiti i sve ću ti kazati što ti je na srcu.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 9, 20, 'A za magarice koje su ti se izgubile prije tri dana ne uznemiruj se jer su se našle. Uostalom, kome pripada sve što je najdragocjenije u Izraelu? Zar ne tebi i svemu domu tvoga oca?\"');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 9, 21, 'A Šaul odgovori ovako: \"Nisam li ja od Benjaminova plemena, najmanjega plemena Izraelova? A moj rod nije li najneznatniji između svih rodova Benjaminova plemena? Zašto mi, dakle, govoriš takve riječi?\"');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 9, 22, 'Samuel uze Šaula i njegova momka, odvede ih u sobu i dade im mjesto u pročelju među uzvanicima, kojih je bilo tridesetak.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 9, 23, 'Zatim Samuel reče kuharu: \"Donesi dio koji ti dadoh i za koji ti rekoh da ga staviš na stranu.\"');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 9, 24, 'Kuhar uze but, donese ga i stavi pred Šaula, a Samuel mu reče: \"Evo, pred tobom je ono što je sačuvano za tebe. Jedi, jer to ti je sačuvano baš za ovu zgodu.\" Tako je u onaj dan Šaul jeo sa Samuelom.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 9, 25, 'Potom odande siđoše u grad. Ondje prostriješe Šaulu na krovu.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 9, 26, 'I on leže na počinak. Čim je svanula zora, Samuel zovnu Šaula (na krovu) govoreći: \"Ustani da te otpustim!\" Kad je Šaul ustao, izađoše obojica, on i Samuel.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 9, 27, 'Kad su došli na kraj grada, reče Samuel Šaulu: \"Kaži momku neka pođe naprijed pred nama! A ti stani sada da ti objavim riječ Božju.\"');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 10, 1, 'Tada Samuel uze uljanicu s uljem te je izli na glavu Šaulu; zatim ga poljubi i reče: \"Ovim te Jahve pomazao za kneza nad svojim narodom Izraelom. Ti ćeš vladati nad narodom Jahvinim i izbavit ćeš ga iz ruke njegovih neprijatelja unaokolo. I evo ti znaka da te Jahve pomazao za kneza nad svojom baštinom.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 10, 2, 'Kad odeš sada od mene, naći ćeš dva čovjeka kod Rahelina groba, na granici zemlje Benjaminove, u Selsahu. Oni će ti reći: \'Našle su se magarice koje si pošao tražiti; i gle, tvoj je otac zaboravio na magarice, a zabrinut je za vas i govori: Što da učinim za svoga sina?\'');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 10, 3, 'A kad odeš odande dalje i dođeš do Taborskog Hrasta, srest ćeš ondje tri čovjeka koja će ići gore k Bogu u Betel. Jedan će nositi tri jareta, drugi tri okrugla kruha, a treći mijeh vina.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 10, 4, 'Oni će te pozdraviti i dat će ti dva kruha, a ti ih primi iz njihove ruke.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 10, 5, 'Poslije toga doći ćeš u Gibeu Božju (gdje se nalazi filistejski stup). Kad uđeš u grad, namjerit ćeš se na povorku proroka koji će silaziti s uzvišice, a pred njima harfe, bubnjevi, frule i citre; oni će biti u proročkom zanosu.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 10, 6, 'Tada će na te sići duh Jahvin te ćeš pasti u proročki zanos s njima i promijenit ćeš se u drugog čovjeka.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 10, 7, 'A kad ti se ispune ti znakovi, onda čini kako ti se prilika pruži jer je Bog s tobom.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 10, 8, 'Zatim ćeš sići preda mnom u Gilgal i ja ću sići k tebi da prinesem žrtve paljenice i žrtve pričesnice. Sedam dana čekaj dok ne dođem k tebi i ne poučim te što ćeš činiti.\"');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 10, 9, 'Čim je Šaul okrenuo leđa da ode od Samuela, Bog mu promijeni srce i svi se oni znakovi ispuniše u onaj dan.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 10, 10, 'Kad su, naime, došli u Gibeu, gle, dođe mu u susret povorka proroka i duh Božji siđe na njega te on pade u proročki zanos usred njih.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 10, 11, 'I kad su ga svi koji ga poznavahu otprije vidjeli gdje prorokuje s prorocima, počeše govoriti jedan drugome: \"Što se to dogodilo sa sinom Kiševim? Zar je Šaul među prorocima?\"');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 10, 12, 'A jedan od njih odvrati i reče: \"A tko je njihov otac?\" Otuda je nastala poslovica: \"Zar je i Šaul među prorocima?\"');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 10, 13, 'Kad je prošao njegov zanos, Šaul se vrati kući.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 10, 14, 'A Šaulov stric upita njega i njegova momka: \"Kamo ste išli?\" A Šaul odgovori: \"Da tražimo magarice; a kad smo vidjeli da ih nema, otišli smo k Samuelu.\"');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 10, 15, 'A njegov ga stric zamoli: \"Pripovijedaj mi što vam je rekao Samuel.\"');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 10, 16, 'A Šaul odgovori svome stricu: \"Rekao nam je da su se našle magarice.\" Ali mu ništa ne reče o kraljevskoj časti koju mu je prorekao Samuel.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 10, 17, 'Poslije toga Samuel sazva narod pred Jahvu u Mispu');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 10, 18, 'i reče sinovima Izraelovim: \"Ovako govori Jahve: \'Ja sam izveo Izraela iz Egipta i izbavio sam vas iz egipatske ruke i iz ruke svih kraljevstava koja su vas tlačila.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 10, 19, 'A vi ste danas odbacili svoga Boga, onoga koji vas je izbavljao od svih vaših zala i svih vaših nevolja i rekli ste mu: \'Ne, nego postavi kralja nad nama!\' Zato sada stanite pred Jahvom po svojim plemenima i rodovima.\'\"');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 10, 20, 'Potom Samuel privede sva plemena Izraelova i ždrijeb pade na pleme Benjaminovo.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 10, 21, 'Zatim privede pleme Benjaminovo po rodovima i ždrijeb pade na Matrijev rod; a kad privede Matrijev rod, čovjeka po čovjeka, ždrijeb pade na Šaula, sina Kiševa; ali kad ga potražiše, na nađoše ga.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 10, 22, 'Tada još jednom upitaše Jahvu: \"Je li taj čovjek došao ovamo?\" A Jahve odgovori: \"Eno ga, sakrio se za tovarom.\"');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 10, 23, 'Otrčaše i dovedoše ga odande; a kad je stao usred naroda, bijaše glavom i ramenima viši od sviju.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 10, 24, 'Tada Samuel reče svemu narodu: \"Vidite li koga je izabrao Jahve? Nema mu ravna u svemu narodu.\" I sav narod uze klicati i vikati: \"Živio kralj!\"');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 10, 25, 'Nato Samuel objavi narodu kraljevsko pravo i zapisa ga u knjigu koju položi pred Jahvu. Najposlije Samuel otpusti sav narod da ide svaki svojoj kući.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 10, 26, 'Šaul se također vrati kući u Gibeu, a s njim pođoše junaci kojima je Bog taknuo srce.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 10, 27, 'Ali neke ništarije rekoše: \"Kako će nas taj spasiti?\" I prezreše ga i ne donesoše mu nikakva dara.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 11, 1, 'Otprilike poslije mjesec dana dođe Amonac Nahaš i utabori se kod Jabeša Gileadskog. Svi Jabešani poručiše Nahašu: \"Sklopi savez s nama pa ćemo ti se pokoriti.\"');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 11, 2, 'Ali im Amonac Nahaš odgovori: \"Ovako ću sklopiti savez s vama: svakome ću od vas iskopati desno oko, i tako ću učiniti sramotu svemu Izraelu.\"');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 11, 3, 'A jabeške mu starješine rekoše: \"Ostavi nam sedam dana da pošaljemo glasnike u sve krajeve Izraelove, pa ako se ne nađe nitko da nas izbavi, predat ćemo se tebi.\"');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 11, 4, 'I dođoše poslanici u Šaulovu Gibeu te izložiše sve narodu da čuje. Tada sav narod zaplaka iza glasa.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 11, 5, 'A gle, Šaul je upravo išao za govedima iz polja pa upita: \"Što je ljudima te plaču?\" I pripovjediše mu što su rekli Jabešani.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 11, 6, 'Kad je Šaul čuo te riječi, duh Jahvin siđe na njega i silan gnjev uskipje u njemu.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 11, 7, 'I uze on dva vola, isiječe ih i komade razasla po poslanicima u sve krajeve Izraelove i poruči: \"Tko ne pođe za Šaulom, ovako će biti s njegovim govedima.\" I strah Božji obuze ljude te pođoše kao jedan čovjek.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 11, 8, 'Šaul ih izbroji u Bezeku: i bijaše sinova Izraelovih tri stotine tisuća, a Judinih ljudi trideset tisuća.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 11, 9, 'Zatim reče poslanicima koji bijahu došli: \"Ovako recite Jabešanima u Gileadu: sutra, kad sunce pripeče, stići će vam pomoć.\" Kad su se poslanici vratili, javiše sve to Jabešanima i oni se obradovaše.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 11, 10, 'I poručiše Nahašu: \"Sutra ćemo izaći k vama, pa učinite s nama što vam bude drago.\"');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 11, 11, 'Sutradan Šaul razdijeli narod u tri čete, koje provališe u tabor o jutarnjoj straži i tukoše Amonce do najveće dnevne žege; a što preživje, rasprša se da ni dvojica ne ostaše zajedno.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 11, 12, 'Tada narod reče Samuelu: \"Tko je onaj što je govorio: \'Zar će Šaul kraljevati nad nama?\' Dajte te ljude da ih pogubimo!\"');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 11, 13, 'Ali Šaul odgovori: \"Neka se ne pogubi u ovaj dan nitko, jer je danas Jahve izvojevao pobjedu u Izraelu.\"');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 11, 14, 'Tada Samuel reče narodu: \"Hajdemo u Gilgal da ondje potvrdimo kraljevstvo.\"');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 11, 15, 'I sav narod krenu u Gilgal i ondje postaviše Šaula za kralja pred Jahvom, u Gilgalu. Ondje žrtvovaše pred Jahvom žrtve pričesnice i ondje je Šaul sa svim Izraelcima slavio slavlje.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 12, 1, 'Tada Samuel reče svemu Izraelu: \"Evo, ispunio sam vašu želju u svemu što ste od mene tražili i postavih kralja nad vama.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 12, 2, 'I od sada će kralj ići pred vama. A ja sam ostario i osijedio i moji sinovi eto su među vama. Ja sam išao pred vama od svoje mladosti pa do današnjega dana.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 12, 3, 'Evo me! Posvjedočite protiv mene pred Jahvom i pred njegovim pomazanikom: kome sam oteo vola i kome sam oteo magarca? Koga sam prevario? Koga sam tlačio? Od koga sam primio mito da bih zažmirio na jedno oko? Ja ću vam sve natrag vratiti.\"');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 12, 4, 'A oni odgovoriše: \"Nisi nas prevario, nisi nas tlačio, nisi ni od koga primio ništa.\"');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 12, 5, 'Još im reče: \"Svjedok je Jahve protiv vas i svjedok je njegov pomazanik u ovaj dan da niste našli ništa u mojoj ruci.\" A oni odgovoriše: \"Tako je!\"');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 12, 6, 'Tada Samuel reče narodu: \"Jest, svjedok je Jahve koji je postavio Mojsija i Arona i koji je izveo vaše oce iz Egipta.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 12, 7, 'Stanite sada ovamo da probesjedim s vama pred Jahvom i da vas podsjetim na sva velika djela koja je učinio Jahve vama i vašim ocima.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 12, 8, 'Kad je Jakov došao u Egipat, Egipćani su ih pritisnuli, a vaši su oci vapili Jahvi za pomoć. I Jahve posla Mojsija i Arona, koji izvedoše oce vaše iz Egipta i naseliše ih na ovome mjestu.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 12, 9, 'Ali oni zaboraviše Jahvu, Boga svoga, i on ih predade u ruke Siseri, vojvodi hasorske vojske, i u ruke Filistejaca, i u ruke moapskome kralju, koji su vojevali na njih.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 12, 10, 'I opet su vapili Jahvi za pomoć govoreći: \'Zgriješili smo jer smo ostavili Jahvu i uzeli služiti baalima i aštartama; izbavi nas sada iz ruku naših neprijatelja pa ćemo ti služiti!\'');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 12, 11, 'I Jahve posla Jerubaala i Baraka, Jiftaha i Samuela te vas izbavi iz ruku vaših neprijatelja unaokolo, tako da ste mogli živjeti bez straha.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 12, 12, 'Ali kad vidjeste Nahaša, kralja amonskoga, kako ide na vas, rekoste mi: \'Ne, nego kralj neka vlada nad nama!\' Pa ipak je vaš kralj Jahve, vaš Bog!');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 12, 13, 'I eto vam sada kralja koga ste izabrali! Eto, Jahve je postavio kralja nad vama.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 12, 14, 'Ako se budete bojali Jahve i njemu budete služili, ako budete slušali njegov glas i ne budete se protivili njegovim zapovijedima, slijedit ćete Jahvu, Boga svoga, vi i kralj koji kraljuje nad vama.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 12, 15, 'Ako li ne budete slušali Jahvina glasa, ako se budete protivili njegovim zapovijedima, tada će se ruka Jahvina spustiti na vas i na vašega kralja da vas uništi.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 12, 16, 'Sada još jednom pristupite i vidite veliki znak koji će Jahve učiniti pred vašim očima.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 12, 17, 'Nije li sada pšenična žetva? Ali ja ću zazvati Jahvu i on će poslati gromove i kišu. I jasno ćete razabrati kako je veliko zlo koje ste učinili pred Jahvom tražeći sebi kralja.\"');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 12, 18, 'Tada Samuel zazva Jahvu i Jahve posla gromove i kišu u onaj dan i sav se narod vrlo poboja Jahve i Samuela.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 12, 19, 'I sav narod reče Samuelu: \"Moli se Jahvi, svome Bogu, za svoje sluge da ne pomremo, jer smo svim svojim grijesima dodali zlo tražeći sebi kralja.\"');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 12, 20, 'Ali Samuel reče narodu: \"Ne bojte se! Vi ste, doduše, učinili sve ovo zlo, ali sada ne ostavljajte više Jahvu, nego služite Jahvi svim svojim srcem.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 12, 21, 'Ne priklanjajte se više ništavim idolima koji vam ništa ne koriste, ništa vam ne pomažu jer su samo ništavila.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 12, 22, 'A Jahve neće odbaciti svoga naroda, radi velikog imena svoga, jer se Jahve udostojao da vas učini svojim narodom.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 12, 23, 'A od mene neka je daleko da zgriješim Jahvi prestajući moliti za vas i upućivati vas na dobar i pošten put.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 12, 24, 'Samo se bojte Jahve i njemu iskreno služite svim svojim srcem; jer, pogledajte kako se velikim očitovao među vama.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 12, 25, 'Ako li budete činili zlo, propast ćete vi i vaš kralj.\"');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 13, 1, 'Šaulu je bilo... godina kad je postao kralj, a kraljevao je... i dvije godine nad Izraelom.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 13, 2, 'Šaul izabra sebi tri tisuće Izraelaca: dvije tisuće od njih bijahu sa Šaulom u Mikmasu i u Betelskoj gori, a jedna tisuća bijaše s Jonatanom u Benjaminovoj Gebi. Ostali je narod Šaul otpustio svakoga u njegov šator.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 13, 3, 'Jonatan sruši filistejski stup koji je stajao u Gibei i Filistejci saznaše da su se Hebreji pobunili. Šaul zapovjedi te zatrubiše u rog po svoj zemlji');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 13, 4, 'i sav Izrael doznade novost: \"Šaul je srušio filistejski stup, Izrael se omrazio Filistejcima!\" I narod se poče skupljati oko Šaula u Gilgalu.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 13, 5, 'A Filistejci se skupiše da vojuju na Izraela: tri tisuće bojnih kola, šest tisuća konja, a mnoštvo naroda kao pijeska na morskoj obali. I utaboriše se kod Mikmasa, istočno od Bet Avena.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 13, 6, 'Kad su Izraelci vidjeli da su u nevolji i da je narod pritisnut od neprijatelja, posakrivaše se u pećine, jame, kamenjake, jarke i čatrnje.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 13, 7, 'Neki su prešli i preko gazova Jordana u zemlju Gadovu i Gileadovu. Šaul je još bio u Gilgalu, a sav je narod oko njega drhtao od straha.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 13, 8, 'On pričeka sedam dana kako mu je odredio Samuel; ali kad Samuel nije došao u Gilgal, narod se stade razilaziti od Šaula.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 13, 9, 'Tada reče Šaul: \"Donesite mi žrtvu paljenicu i žrtve pričesnice!\" I prinese žrtvu paljenicu.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 13, 10, 'I upravo je završavao žrtvu paljenicu, kad eto Samuela; Šaul mu iziđe u susret da ga pozdravi.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 13, 11, 'Samuel ga upita: \"Što si učinio?\" A Šaul odgovori: \"Kad sam vidio da se narod razilazi od mene, a ti da ne dolaziš do određenoga dana, a Filistejci se skupili u Mikmasu,');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 13, 12, 'pomislio sam: sad će udariti Filistejci na me u Gilgalu, a ja neću stići molitvom ublažiti Jahvu! Zato se odvažih i prinesoh žrtvu paljenicu.\"');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 13, 13, 'Samuel tada reče Šaulu: \"Ludo si radio! Da si održao zapovijed koju ti je dao Jahve, tvoj Bog, Jahve bi učvrstio tvoje kraljevstvo nad Izraelom dovijeka.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 13, 14, 'A sada se tvoje kraljevstvo neće trajno održati: Jahve je potražio sebi čovjeka po svom srcu i odredio ga za kneza nad svojim narodom, jer ti nisi održao što ti je Jahve zapovjedio.\"');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 13, 15, 'Nato Samuel ustade i ode iz Gilgala svojim putem. Što je naroda ostalo, pođe za Šaulom u susret ratnicima. Kad su došli iz Gilgala u Gebu Benjaminovu, Šaul pobroji narod koji je ostao uza nj i bijaše ga oko šest stotina ljudi.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 13, 16, 'Šaul i sin mu Jonatan s ljudima što bijahu s njima zaposjeli su Benjaminovu Gebu, a Filistejci se utaborili u Mikmasu.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 13, 17, 'Tada iz filistejskog tabora izađe četa pljačkaša u tri odjela: jedan odio udari prema Ofri u zemlju šualsku;');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 13, 18, 'drugi odio krenu prema Bet Horonu, a treći odio udari prema Gebi koja se uz Dolinu hijena diže nad pustinjom.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 13, 19, 'A po svoj zemlji Izraelovoj nije bilo kovača, jer su Filistejci rekli: \"Treba sve učiniti da Hebreji ne bi pravili sebi mačeva i kopalja.\"');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 13, 20, 'Zato su svi Izraelci išli k Filistejcima ako je tko htio da prekuje svoj raonik ili motiku, svoju sjekiru ili ostan za volove.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 13, 21, 'A cijena je bila dvije trećine šekela za raonike i motike, jedna trećina za oštrenje sjekire i za nasađivanje ostana.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 13, 22, 'Tako se dogodilo da na dan bitke kod Mikmasa nitko od svega naroda koji bijaše sa Šaulom i Jonatanom nije imao ni mača ni koplja u ruci; samo ih imahu Šaul i njegov sin Jonatan.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 13, 23, 'A dotle jedna straža filistejska bijaše izišla prema klancu kod Mikmasa.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 14, 1, 'Jednoga dana Šaulov sin Jonatan reče svome momku štitonoši: \"Hajde da prijeđemo do filistejske straže koja je ondje prijeko.\" Svome ocu nije ništa o tom javio.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 14, 2, 'Šaul je sjedio na međi Gebe, pod šipkom koji je stajao kraj gumna; a bilo je s njim oko šest stotina ljudi.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 14, 3, 'A Ahija, sin Ahituba, brata Ikaboda, sina Pinhasa, sina Elija, svećenika Jahvina u Šilu, nosio je u to vrijeme oplećak. Narod nije primijetio da je Jonatan otišao.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 14, 4, 'U sredini klanca kuda je Jonatan htio prijeći da dođe do filistejske straže bila je litica s jedne strane i litica s druge strane. Jedna se zvala Boses, a druga Sene.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 14, 5, 'Prva je litica stajala na sjeveru nasuprot Mikmasu, a druga na jugu nasuprot Gebi.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 14, 6, 'Jonatan reče svome štitonoši: \"Hajde da prijeđemo do straže onih neobrezanika. Možda će Jahve učiniti nešto za nas, jer ništa ne priječi Jahvu da udijeli pobjedu - bilo mnogo ljudi ili malo.\"');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 14, 7, 'A štitonoša mu odgovori: \"Čini sve na što te srce tvoje potiče. Ja ću s tobom, moje je srce kao tvoje srce.\"');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 14, 8, 'Jonatan mu reče: \"Evo, prijeći ćemo k tim ljudima i pokazat ćemo im se.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 14, 9, 'Ako nam reknu ovako: \'Ne mičite se dok ne dođemo do vas\', tada ćemo se ustaviti na mjestu i nećemo se uspinjati k njima.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 14, 10, 'Ako li nam reknu ovako: \'Uspnite se k nama\', tada ćemo se uspeti, jer ih je Jahve predao nama u ruke. To će nam biti znak.\"');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 14, 11, 'Kad su se obojica pokazala filistejskoj straži, rekoše Filistejci: \"Gle, Hebreji su počeli izlaziti iz rupa u koje su se skrili.\"');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 14, 12, 'I stražari doviknuše Jonatanu i njegovu štitonoši: \"Uspnite se k nama da vas nešto naučimo!\" A Jonatan reče svome štitonoši: \"Penji se za mnom, jer ih je Jahve predao u ruke Izraelove.\"');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 14, 13, 'Jonatan se poče penjati pomažući se rukama i nogama, a za njim njegov štitonoša. Filistejci su padali pred Jonatanom, a njegov ih je štitonoša ubijao za njim.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 14, 14, 'U tome prvom pokolju što ga učiniše Jonatan i njegov štitonoša pade dvadesetak ljudi na otprilike pola jutra izoranog polja.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 14, 15, 'Tada se proširi strah po taboru i po polju, a i stražare i četu pljačkaša obuze strava; i zemlja zadrhta i bijaše to silan strah Božji.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 14, 16, 'A Šaulovi stražari u Benjaminovoj Gebi opaziše da se mnoštvo u taboru uskomešalo na sve strane.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 14, 17, 'I Šaul reče ljudima koji su bili s njim: \"Prozovite ljude i vidite tko je otišao od nas.\" A kad prozvaše, gle, ne bijaše Jonatana i njegova štitonoše!');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 14, 18, 'Tada Šaul reče Ahiji: \"Primakni oplećak! Posavjetuj se s Jahvom!\" On je, naime, tada nosio oplećak pred sinovima Izraelovim.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 14, 19, 'Ali dok je Šaul govorio sa svećenikom, bivala je buka u filistejskom taboru sve veća, pa Šaul reče svećeniku: \"Povuci ruku!\"');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 14, 20, 'Nato Šaul i sav narod što je bio s njim krenuše zajedno na mjesto boja, i gle, ondje bijahu isukali mačeve jedni na druge i velika pomutnja vladaše među njima.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 14, 21, 'A oni Hebreji koji su već poodavno bili u službi Filistejaca i sada pošli s njima na vojsku, odmetnuše se od njih i pristadoše uz Izraelce koji bijahu sa Šaulom i Jonatanom.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 14, 22, 'I svi Izraelci koji se bijahu sakrili u Efrajimovoj gori, čuvši da Filistejci bježe, nagrnuše za njima u boj.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 14, 23, 'Tako je Jahve udijelio pobjedu Izraelu u onaj dan, a boj se raširio sve do preko Bet Horona.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 14, 24, 'Izraelci su onog dana bili vrlo izmoreni, jer je Šaul izrekao nad narodom ovu zakletvu: \"Proklet bio čovjek koji okusi hrane prije večeri, prije nego što se osvetim svojim neprijateljima!\" Tako sav narod ne okusi hrane toga dana.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 14, 25, 'Ali je ondje bilo medenoga saća na površini zemlje.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 14, 26, 'Kad je narod došao onamo, vidje gdje teče med, ali nitko ne prinese ruke k ustima, jer se narod bojao zakletve.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 14, 27, 'Samo Jonatan, koji nije čuo kad je njegov otac zakleo narod, primače vrh štapa koji mu bijaše u ruci i zamoči ga u medeno saće, zatim prinese ruku k ustima; i odmah mu se zasvijetliše oči.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 14, 28, 'Tada jedan iz naroda progovori i reče mu: \"Tvoj je otac zakleo narod govoreći: \'Proklet bio onaj koji okusi hrane danas!\'\"');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 14, 29, 'A Jonatan odgovori: \"Moj otac svaljuje nesreću na zemlju. Gledajte kako su mi se zasvijetlile oči jer sam okusio malo toga meda.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 14, 30, 'Što bi tek bilo da je narod slobodno jeo od plijena koji je zadobio od neprijatelja? Ne bi li filistejski poraz bio još veći?\"');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 14, 31, 'Onoga dana potukoše Filistejce od Mikmasa sve do Ajalona, a narod je bio na kraju svojih snaga.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 14, 32, 'Tada se narod baci na plijen, nahvata sitne stoke, goveda i teladi i poče ih klati na goloj zemlji i jesti meso s krvlju.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 14, 33, 'I javiše to Šaulu govoreći: \"Gle, narod griješi Jahvi jedući meso s krvlju!\" A on reče: \"Iznevjeriste se! Dovaljajte mi ovamo velik kamen!\"');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 14, 34, 'Zatim reče: \"Zađite među narod i recite svima neka svaki dovede k meni svoga vola ili ovcu; ovdje ćete ih klati i jesti, a nećete griješiti Jahvi jedući meso s krvlju.\" Tako sav narod još iste noći dovede što je tko imao i to su ondje klali.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 14, 35, 'A Šaul podiže žrtvenik Jahvi; bijaše to prvi žrtvenik koji je podigao Jahvi.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 14, 36, 'Nato reče Šaul: \"Pođimo još noćas u potjeru za Filistejcima i plijenimo ih dok ne svane jutro! Nećemo im ostaviti nijednoga čovjeka!\" A narod mu odgovori: \"Čini sve što misliš da je dobro!\" Ali svećenik reče: \"Pristupimo ovdje k Bogu!\"');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 14, 37, 'I Šaul upita Boga: \"Moram li poći u potjeru za Filistejcima? Hoćeš li ih predati u ruke Izraelu?\" Ali mu ne odgovori u onaj dan.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 14, 38, 'Zato Šaul reče: \"Pristupite ovamo, svi narodni glavari! Ispitajte i vidite u čemu je bio današnji prestupak.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 14, 39, 'Jer, živoga mi Jahve, koji daje pobjedu Izraelu, ako se nađe krivnja ma i na mome sinu Jonatanu, mora umrijeti!\" Ali nitko se iz naroda ne usudi odgovoriti Šaulu.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 14, 40, 'Šaul onda reče svemu Izraelu: \"Vi stanite na jednu stranu, a ja i moj sin Jonatan stat ćemo na drugu stranu.\" A narod odgovori Šaulu: \"Čini ono što misliš da je dobro!\"');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 14, 41, 'Tada se Šaul pomoli: \"Jahve, Bože Izraelov, zašto nisi danas odgovorio svome sluzi? Ako je krivnja na meni ili na mome sinu Jonatanu, Jahve, Bože Izraelov, daj Urim; ako li je krivnja na tvom narodu Izraelu, daj Tumim.\" I ždrijeb pade na Šaula i Jonatana, a narod izađe slobodan.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 14, 42, 'Šaul nastavi: \"Bacite ždrijeb između mene i moga sina Jonatana!\" I ždrijeb pade na Jonatana.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 14, 43, 'Tada Šaul reče Jonatanu: \"Priznaj mi što si učinio!\" Jonatan odgovori: \"Ja sam samo okusio malo meda vrškom štapa koji mi bijaše u ruci. Evo me, spreman sam umrijeti!\"');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 14, 44, 'Šaul odgovori: \"Tako mi Bog učinio zlo i dodao mi drugo ako doista ne umreš, Jonatane!\"');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 14, 45, 'Ali narod reče Šaulu: \"Zar da umre Jonatan, koji je izvojevao ovu veliku pobjedu u Izraelu? Ne smije to biti! Živoga nam Jahve, nijedna vlas neće pasti s njegove glave na zemlju jer je on s Bogom izvršio ovo djelo danas!\" Tako ga narod izbavi te Jonatan ne pogibe.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 14, 46, 'Šaul odusta od potjere za Filistejcima, a Filistejci se vratiše u svoj kraj.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 14, 47, 'Kad je Šaul učvrstio svoju kraljevsku vlast nad Izraelom, okrenu ratovati protiv svih svojih neprijatelja unaokolo: protiv Moaba, protiv Amonaca, protiv Edoma, protiv Bet Rehoba, protiv kralja Sobe i protiv Filistejaca; kuda god bi se okrenuo, svuda bi pobjeđivao.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 14, 48, 'Dao je mnogo dokaza svoje hrabrosti, potukao je Amalečane i izbavio Izraela iz ruku onih koji su ga pljačkali.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 14, 49, 'Šaulovi sinovi bijahu Jonatan, Išjo i Malki-Šua, a od njegovih dviju kćeri starija se zvala Meraba, a mlađa Mikala.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 14, 50, 'Šaulova se žena zvala Ahinoama, a bila je kći Ahimaasova. Vojvoda njegove vojske zvao se Abner, a bio je sin Nera, Šaulova strica.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 14, 51, 'Jer Kiš, Šaulov otac, i Ner, Abnerov otac, bijahu sinovi Abielovi.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 14, 52, 'Žestok se rat vodio protiv Filistejaca svega Šaulova vijeka. Koga bi god hrabra ili bojovna čovjeka Šaul vidio, svakoga bi uzimao u svoju službu.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 15, 1, 'Jednom Samuel reče Šaulu: \"Mene je Jahve poslao da te pomažem za kralja nad njegovim narodom Izraelom. Poslušaj, dakle, riječi Jahvine.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 15, 2, 'Ovako govori Jahve nad vojskama: \'Odlučio sam osvetiti ono što je Amalek učinio Izraelu zatvarajući mu put kad je izlazio iz Egipta.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 15, 3, 'Sada idi i udari na Amaleka, izvrši \"herem\", kleto uništenje, na njemu i na svemu što posjeduje; ne štedi ga, pobij muškarce i žene, djecu i dojenčad, goveda i ovce, deve i magarce!\'\"');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 15, 4, 'Šaul sazva narod te ih izbroji u Telamu: bijaše ih dvije stotine tisuća pješaka (i deset tisuća Judejaca).');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 15, 5, 'Šaul dođe do amalečkoga grada i postavi zasjedu u dolini potoka.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 15, 6, 'Potom Šaul poruči Kenijcima: \"Otiđite i odvojite se od Amalečana da vas ne bih istrijebio zajedno s njima, jer ste bili skloni svim Izraelcima kad su izlazili iz Egipta.\" I Kenijci se odvojiše od Amalečana.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 15, 7, 'Šaul potuče Amalečane od Havile pa sve do Šura, koji leži pred Egiptom.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 15, 8, 'I živa uhvati Agaga, amalečkog kralja, a sav narod zatre oštricom mača, izvršujući \"herem\", kleto uništenje.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 15, 9, 'Ali Šaul i narod poštedješe Agaga i najbolje ovce i najbolja goveda, ugojenu stoku i jaganjce i sve što je bilo dobro. Na svemu tome ne htjedoše izvršiti \"herem\"; nego što je god od stoke bilo bez cijene i vrijednosti, na tom izvršiše \"herem\".');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 15, 10, 'Zato dođe riječ Jahvina Samuelu ovako:');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 15, 11, '\"Kajem se što sam Šaula postavio za kralja: okrenuo se od mene i nije izvršio mojih zapovijedi.\" Samuel se ražalosti i svu je noć vapio Jahvi.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 15, 12, 'U rano jutro krenu Samuel da potraži Šaula. I javiše Samuelu ovako: \"Šaul je otišao u Karmel, i gle, podigao je ondje sebi spomenik; zatim je otišao dalje i sišao u Gilgal.\"');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 15, 13, 'Kad je Samuel došao k Šaulu, reče mu Šaul: \"Blagoslovljen da si od Jahve! Izvršio sam Jahvinu zapovijed.\"');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 15, 14, 'Ali Samuel upita: \"Kakvo je to ovčje blejanje što dopire do mojih ušiju i mukanje goveda koje čujem?\"');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 15, 15, 'A Šaul odgovori: \"Dognali su ih od Amalečana, jer je narod poštedio najbolje ovce i najbolja goveda da ih žrtvuje Jahvi, tvome Bogu. Na svemu drugome izvršili smo \'herem\'.\"');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 15, 16, 'A Samuel reče Šaulu: \"Stani da ti kažem što mi je noćas objavio Jahve.\" A on reče: \"Govori!\"');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 15, 17, 'Tada će Samuel: \"Koliko god si malen sam u svojim očima, ipak si postao glavar Izraelovih plemena. Jahve te pomazao za kralja nad Izraelom.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 15, 18, 'Jahve te poslao na vojni pohod i zapovjedio ti: \'Idi, izvrši \'herem\' na tim grešnicima, na Amalečanima, vojuj na njih do istrebljenja.\'');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 15, 19, 'Zašto nisi poslušao riječi Jahvine? Zašto si se bacio na plijen i učinio ono što je zlo u Jahvinim očima?\"');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 15, 20, 'Šaul odgovori Samuelu: \"Ja sam poslušao riječ Jahvinu: poduzeo sam pohod kamo me poslao, doveo sam Agaga, amalečkoga kralja, i izvršio \'herem\' na Amalečanima.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 15, 21, 'Ali je narod od plijena uzeo ovaca i goveda, i to najbolje na čemu se imao izvršiti \'herem\', da žrtvuje Jahvi, tvome Bogu, u Gilgalu.\"');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 15, 22, 'A Samuel odvrati: \"Jesu li Jahvi milije paljenice i klanice nego poslušnost njegovu glasu? Znaj, poslušnost je vrednija od najbolje žrtve, pokornost je bolja od ovnujske pretiline.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 15, 23, 'Nepokornost je kao grijeh čaranja, samovolja je kao zločin s idolima. Ti si odbacio riječ Jahvinu, zato je Jahve odbacio tebe da ne budeš više kralj!\"');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 15, 24, 'Tada Šaul odvrati Samuelu: \"Zgriješio sam što sam prekršio Jahvinu zapovijed i tvoje naredbe. Bojao sam se naroda i popustio njegovu zahtjevu.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 15, 25, 'A sada mi oprosti moj grijeh i vrati se sa mnom da se poklonim Jahvi.\"');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 15, 26, 'Ali Samuel odgovori Šaulu: \"Neću se vratiti s tobom: ti si odbacio Jahvinu riječ, zato je Jahve odbacio tebe da ne budeš više kralj nad Izraelom.\"');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 15, 27, 'Kad se Samuel okrenuo da ode, Šaul čvrsto uhvati skut njegova plašta, ali se skut otkide.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 15, 28, 'Tada mu reče Samuel: \"Danas ti je Jahve otkinuo kraljevstvo nad Izraelom i dao ga tvome susjedu, koji je bolji od tebe.\" -');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 15, 29, 'Ipak, Slava Izraelova ne laže i ne kaje se, jer nije čovjek da bi se kajao. -');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 15, 30, 'Šaul reče: \"Sagriješio sam; ali mi sada učini čast pred starješinama moga naroda i pred Izraelom i vrati se sa mnom da se poklonim Jahvi, tvome Bogu.\"');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 15, 31, 'I Samuel se vrati sa Šaulom i Šaul se pokloni Jahvi.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 15, 32, 'Potom zapovjedi Samuel: \"Dovedite k meni Agaga, amalečkoga kralja!\" I Agag dođe k njemu opirući se i reče: \"Zaista, smrt je gorka!\"');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 15, 33, 'Samuel mu odvrati: \"Kao što je tvoj mač mnogim ženama oteo djecu, tako će među ženama tvoja majka ostati bez djeteta!\" I Samuel posiječe Agaga pred Jahvom u Gilgalu.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 15, 34, 'Potom Samuel ode u Ramu, a Šaul se vrati svojoj kući u Šaulovu Gibeu.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 15, 35, 'I Samuel nije više vidio Šaula do svoga smrtnog dana. Samuel je tugovao zbog Šaula, ali se Jahve pokajao što je Šaula postavio za kralja nad Izraelom.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 16, 1, 'Jahve reče Samuelu: \"Dokle ćeš tugovati zbog Šaula, kad sam ga ja odbacio da ne kraljuje više nad Izraelom? Napuni uljem svoj rog i pođi na put! Ja te šaljem Betlehemcu Jišaju, jer sam između njegovih sinova izabrao sebi kralja.\"');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 16, 2, 'A Samuel reče: \"Kako bih mogao ići onamo? Šaul će to čuti i ubit će me!\" Ali mu Jahve odgovori: \"Uzmi sa sobom junicu pa reci: \'Došao sam da žrtvujem Jahvi!\'');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 16, 3, 'I pozovi Jišaja na žrtvu, a ja ću te sam poučiti što ćeš činiti: pomazat ćeš onoga koga ti kažem.\"');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 16, 4, 'Samuel učini kako mu je zapovjedio Jahve. Kad je došao u Betlehem, gradske mu starješine dršćući dođu u susret i zapitaju: \"Znači li tvoj dolazak dobro?\"');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 16, 5, 'Samuel odgovori: \"Da, dobro! Došao sam da žrtvujem Jahvi. Očistite se i dođite sa mnom na žrtvu!\" Potom očisti Jišaja i njegove sinove i pozva ih na žrtvu.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 16, 6, 'Kad su došli i kad je Samuel vidio Eliaba, reče u sebi: \"Jamačno, evo pred Jahvom stoji njegov pomazanik!\"');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 16, 7, 'Ali Jahve reče Samuelu: \"Ne gledaj na njegovu vanjštinu ni na njegov visoki stas, jer sam ga odbacio. Bog ne gleda kao što gleda čovjek: čovjek gleda na oči, a Jahve gleda što je u srcu.\"');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 16, 8, 'Zatim Jišaj dozva Abinadaba i dovede ga pred Samuela. A on reče: \"Ni ovoga Jahve nije izabrao.\"');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 16, 9, 'Tada Jišaj dovede Šamu, ali Samuel reče: \"Ni ovoga Jahve nije izabrao.\"');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 16, 10, 'Tako Jišaj dovede sedam svojih sinova pred Samuela, ali Samuel reče Jišaju: \"Jahve nije izabrao nijednoga od ovih.\"');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 16, 11, 'Potom zapita Jišaja: \"Jesu li to svi tvoji sinovi?\" A on odgovori: \"Ostao je još najmlađi, on je na paši, za stadom.\" Tada Samuel reče Jišaju: \"Pošalji po njega, jer nećemo sjedati za stol dok on ne dođe.\"');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 16, 12, 'Jišaj posla po njega: bio je to rumen momak, lijepih očiju i krasna stasa. I Jahve reče Samuelu: \"Ustani, pomaži ga: taj je!\"');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 16, 13, 'Samuel uze rog s uljem i pomaza ga usred njegove braće. Duh Jahvin obuze Davida od onoga dana. A Samuel krenu na put i ode u Ramu.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 16, 14, 'Duh Jahvin bijaše odstupio od Šaula, a jedan zao duh, od Jahve, stao ga je salijetati.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 16, 15, 'Tada rekoše Šaulu sluge njegove: \"Evo, zao duh Božji salijeće te.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 16, 16, 'Zato neka naš gospodar zapovjedi, pa će sluge tvoje potražiti čovjeka koji zna udarati u harfu: kad te napadne zao duh Božji, neka onaj udara u harfu pa će ti biti bolje.\"');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 16, 17, 'Šaul reče svojim slugama: \"Nađite mi čovjeka koji umije vješto udarati u harfu i dovedite ga k meni!\"');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 16, 18, 'Jedan od njegovih slugu odgovori i reče: \"Ja sam vidio jednog sina Betlehemca Jišaja: on umije udarati u harfu, hrabar je junak i čovjek ratnik, vješt je govornik, krasna je stasa i Jahve je s njim.\"');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 16, 19, 'Tada Šaul posla glasnike k Jišaju i poruči mu: \"Pošalji mi svoga sina Davida (koji je kod stada)!\"');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 16, 20, 'A Jišaj uze pet hljebova, mijeh vina i jedno jare i posla Šaulu po svome sinu Davidu.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 16, 21, 'Tako David dođe k Šaulu i stupi u njegovu službu. I Šaul ga veoma zavolje i David posta njegov štitonoša.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 16, 22, 'Potom Šaul posla k Jišaju i poruči mu: \"Neka David ostane kod mene u službi, jer je stekao moju naklonost.\"');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 16, 23, 'I kad god bi Božji duh napao Šaula, David bi uzeo harfu i svirao; tada bi Šaulu odlanulo i bilo bi mu bolje, a zao bi duh odlazio od njega.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 17, 1, 'Filistejci skupiše svoje čete za rat i sastaše se kod Soka u Judeji. Tabor udariše između Soka i Azeke kod Efes Damima.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 17, 2, 'A Šaul i Izraelci skupiše se i utaboriše u Terebintskoj dolini, i svrstaše se za boj protiv Filistejaca.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 17, 3, 'Filistejci su stajali na gori s jedne strane, Izraelci na gori s druge strane, a dolina bila među njima.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 17, 4, 'Iz filistejskih redova izađe jedan izazivač. Zvao se Golijat, a bio je iz Gata. Visok bijaše šest lakata i jedan pedalj.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 17, 5, 'Na glavi je imao mjedenu kacigu, obučen je bio u ljuskav oklop, a oklop mu težak pet tisuća mjedenih šekela.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 17, 6, 'Na nogama je imao mjedene nogavice, a na ramenima mjedenu sulicu.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 17, 7, 'Kopljača njegova koplja bila je kao tkalačko vratilo, a šiljak koplja težak šest stotina željeznih šekela. Pred njim je stupao štitonoša.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 17, 8, 'On se postavi pred izraelske bojne redove i dovikne im: \"Što ste izašli da se svrstate za bitku? Nisam li ja Filistejac, a vi Šaulove sluge? Izaberite između sebe jednoga čovjeka pa neka siđe k meni!');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 17, 9, 'Ako pobijedi u borbi sa mnom i pogubi me, mi ćemo biti vaše sluge. Ako li ja pobijedim njega i pogubim ga, onda ćete vi biti naše sluge i nama ćete robovati.\"');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 17, 10, 'Još je Filistejac rekao: \"Ja sam danas izazvao Izraelove bojne redove. Dajte mi čovjeka da se ogledamo u dvoboju!\"');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 17, 11, 'Kad je Šaul i sav Izrael čuo što je rekao Filistejac, obuze ih strah i drhat.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 17, 12, 'David je bio sin nekoga Efraćanina iz Betlehema u Judeji; taj se zvao Jišaj, a imao je osam sinova. Taj je čovjek u Šaulovo vrijeme bio star i odmakao u godinama.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 17, 13, 'Tri najstarija Jišajeva sina bijahu otišla u rat za Šaulom; a ta trojica njegovih sinova koji bijahu otišli u rat zvahu se: najstariji Eliab, drugi Abinadab, a treći Šama.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 17, 14, 'David bijaše najmlađi. A tri najstarija bijahu otišla za Šaulom. -');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 17, 15, 'David je odlazio k Šaulu i vraćao se iz njegove službe da pase stada svoga oca u Betlehemu.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 17, 16, 'A Filistejac izlazio svakoga jutra i večeri i postavljao se tako četrdeset dana. -');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 17, 17, 'A Jišaj reče svome sinu Davidu: \"Uzmi za svoju braću ovu efu prženoga žita i ovih deset hljebova i odnesi brže svojoj braći u tabor.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 17, 18, 'A ovih deset sireva odnesi njihovu tisućniku. Propitaj se za zdravlje svoje braće i donesi od njih znak da si izvršio nalog!');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 17, 19, 'Oni su sa Šaulom i svim Izraelom u Terebintskoj dolini: vojuju protiv Filistejaca.\"');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 17, 20, 'David ustade u rano jutro, ostavi stado jednom čuvaru, spremi se i ode kako mu bijaše zapovjedio Jišaj. U tabor je stigao kad je vojska izlazila u bojni red i dizala bojni poklik.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 17, 21, 'Izraelci i Filistejci svrstaše se u bojni red jedni prema drugima.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 17, 22, 'David ostavi svoje stvari čuvaru opreme pa otrča u bojni red. Došavši, zapita svoju braću za zdravlje.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 17, 23, 'Dok je s njima govorio, gle, onaj izazivač (zvao se Golijat, Filistejac iz Gata) iziđe iz filistejskih bojnih redova i ponovi iste riječi kao prije. I David ih je čuo.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 17, 24, 'A čim su Izraelci ugledali toga čovjeka, pobjegoše svi daleko od njega i strah ih uhvati.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 17, 25, 'Neki Izraelac reče: \"Jeste li vidjeli onoga čovjeka što je izišao? A izišao je da izaziva Izraela. Tko njega pogubi, kralj će mu dati silno blago i dat će mu svoju kćer i oslobodit će od poreza njegov očinski dom u Izraelu.\"');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 17, 26, 'Tada David zapita ljude koji stajahu oko njega: \"Što će to dobiti čovjek koji ubije toga Filistejca i skine sramotu s Izraela? I tko je taj neobrezani Filistejac da izaziva bojne redove živoga Boga?\"');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 17, 27, 'A narod mu odgovori istim riječima kao prije: \"Eto to će dobiti čovjek koji ga pogubi.\"');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 17, 28, 'A kad je Eliab, njegov najstariji brat, čuo kako se razgovara s ljudima, usplamtje gnjevom na Davida pa mu reče: \"A što si ti došao ovamo? Kome si ostavio ono malo ovaca u pustinji? Znam ja tvoju drskost i zlobu tvoga srca: došao si da vidiš bitku!\"');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 17, 29, 'A David odgovori: \"A što sam učinio? Zar se ne smije ni riječ reći?\"');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 17, 30, 'Tada se okrene od njega k drugome i zapita istim riječima kao prije. Narod mu odgovori isto kao prvi put.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 17, 31, 'Kad su ljudi čuli što je govorio David, jave to Šaulu, a on ga pozva preda se.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 17, 32, 'David reče Šaulu: \"Neka nikome ne klone srce zbog onoga čovjeka! Tvoj će sluga izaći i borit će se s tim Filistejcem.\"');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 17, 33, 'Ali Šaul odvrati Davidu: \"Ne možeš ti izaći na toga Filistejca da se boriš s njim jer si ti još dijete, a on ratnik od svoje mladosti.\"');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 17, 34, 'Ali David odgovori Šaulu: \"Tvoj je sluga čuvao ovce svome ocu, pa kad bi došao lav ili medvjed te uhvatio ovcu iz stada,');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 17, 35, 'ja bih potrčao za njim, udario ga i istrgao mu ovcu iz ralja. A ako bi se on digao na me, uhvatio bih ga za grivu i udarao ga dok ga ne bih ubio.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 17, 36, 'I lava je i medvjeda tvoj sluga ubio, pa će i taj neobrezani Filistejac proći kao jedan od njih jer je izazvao bojne čete Boga živoga.\"');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 17, 37, 'David još dometne: \"Jahve koji me izbavio iz lavlje pandže i medvjeđe šape izbavit će me i iz ruku toga Filistejca.\" Tada Šaul reče Davidu: \"Idi i Jahve neka bude s tobom!\"');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 17, 38, 'Šaul obuče Davida u svoju ratnu odoru, na glavu mu ustače mjedenu kacigu i stavi mu oklop.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 17, 39, 'Pripasa Davidu svoj mač preko odore, ali David uzalud pokuša hodati, jer ne bijaše navikao, pa reče Šaulu: \"Ne mogu hodati u tome jer nisam navikao.\" Zato sve skinu sa sebe.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 17, 40, 'David uze svoj štap u ruku, izabra u potoku pet glatkih kamenova i metnu ih u svoju pastirsku torbu, koja mu je služila kao torba za praćku, te s praćkom u ruci pođe prema Filistejcu.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 17, 41, 'A Filistejac se sve bliže primicao Davidu, dok je njegov štitonoša stupao pred njim.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 17, 42, 'A kad Filistejac pogleda i vidje Davida, prezre ga s njegove mladosti - bijaše David mladić, rumen, lijepa lica.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 17, 43, 'Zato Filistejac reče Davidu: \"Zar sam ja pseto te ideš na me sa štapovima?\" I uze proklinjati Davida svojim bogovima.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 17, 44, 'Zatim Filistejac reče Davidu: \"Dođi k meni da dam tvoje meso pticama nebeskim i zvijerima zemaljskim!\"');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 17, 45, 'A David odgovori Filistejcu: \"Ti ideš na me mačem, kopljem i sulicom, a ja idem na te u ime Jahve Sebaota, Boga Izraelovih četa koje si ti izazvao.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 17, 46, 'Danas će te Jahve predati u moju ruku, ja ću te ubiti, skinut ću tvoju glavu i još ću danas tvoje mrtvo tijelo i mrtva tjelesa filistejske vojske dati pticama nebeskim i zvijerima zemaljskim. Sva će zemlja znati da ima Bog u Izraelu.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 17, 47, 'I sav će ovaj zbor znati da Jahve ne daje pobjedu mačem ni kopljem, jer je Jahve gospodar bitke i on vas predaje u naše ruke.\"');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 17, 48, 'Kad se Filistejac približio i pošao prema Davidu, izađe David iz bojnih redova i krenu pred Filistejca.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 17, 49, 'David segnu rukom u torbu, izvadi iz nje kamen i hitnu ga iz praćke. I pogodi Filistejca u čelo; kamen mu se zabi u čelo i on pade ničice na zemlju.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 17, 50, 'Tako je David praćkom i kamenom nadjačao Filistejca: udario je Filistejca i ubio ga, a nije imao mača u ruci.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 17, 51, 'Zato David potrča i stade na Filistejca, zgrabi njegov mač, izvuče ga iz korica i pogubi Filistejca odsjekavši mu glavu. Kad Filistejci vidješe kako pogibe njihov junak, nagnuše u bijeg.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 17, 52, 'Tada ustadoše Izraelci i Judejci, digoše bojnu viku i potjeraše Filistejce do opkopa oko Gata i do gradskih vrata Ekrona; filistejski mrtvaci pokriše put od Šaarajima sve do Gata i do Ekrona.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 17, 53, 'Nato se Izraelci vratiše iz te žestoke potjere za Filistejcima i opljačkaše njihov tabor.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 17, 54, 'A David uze Filistejčevu glavu i odnese je u Jeruzalem, a oružje njegovo položi u svoj šator.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 17, 55, 'Kad je Šaul vidio Davida gdje izlazi pred Filistejca, upitao je svoga vojvodu Abnera: \"Čiji je sin taj mladić, Abnere?\" A Abner je odgovorio: \"Tako mi tvoga života, kralju, ne znam!\"');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 17, 56, 'A kralj mu reče: \"Raspitaj se čiji je sin taj mladić!\"');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 17, 57, 'A kad se David vratio pošto je pogubio Filistejca, uze ga Abner i dovede ga pred Šaula, a u ruci David još držaše Filistejčevu glavu.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 17, 58, 'Šaul ga upita: \"Čiji si ti sin, momče?\" A David odgovori: \"Sin sam tvoga sluge Betlehemca Jišaja.\"');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 18, 1, 'Kad je David završio razgovor sa Šaulom, Jonatanova se duša prikloni Davidovoj duši i Jonatan ga zavolje kao samoga sebe.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 18, 2, 'Šaul zadrža Davida onoga istog dana kod sebe i nije mu dao da se vrati kući svoga oca.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 18, 3, 'I Jonatan sklopi savez s Davidom jer ga je ljubio kao samoga sebe.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 18, 4, 'I skide Jonatan plašt koji je imao na sebi i dade ga Davidu; tako i svoju odoru, čak i svoj mač, svoj luk i svoj pojas.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 18, 5, 'Na svim svojim pohodima, kamo ga je god slao Šaul, David bijaše sretne ruke i Šaul ga postavi na čelo svojim ratnicima; omilje on svemu narodu, pa i Šaulovim dvoranima.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 18, 6, 'Za njihova povratka, kad se David vraćao ubivši Filistejca, izađoše žene iz svih gradova Izraelovih u susret kralju Šaulu veselo kličući, pjevajući i plešući uza zvuke bubnjeva i cimbala.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 18, 7, 'Žene su plešući pjevale: \"Pobi Šaul svoje tisuće, David na desetke tisuća.\"');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 18, 8, 'Šaul se vrlo ražestio, nije mu bila draga ta pjesma. Zato reče: \"Davidu su dale desetke tisuća, a meni samo tisuće! Još mu samo treba kraljevstvo!\"');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 18, 9, 'I od toga dana Šaul poprijeko gledaše Davida.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 18, 10, 'Sutradan zao duh Božji napade Šaula, tako da je bjesnio po kući. David je rukom udarao u harfu kao drugih dana, a Šaul je u ruci imao koplje.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 18, 11, 'I Šaul baci koplje govoreći u sebi: \"Sad ću pribiti Davida uza zid!\" Ali mu se David izmače dva puta.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 18, 12, 'Šaul se poče bojati Davida, jer je Jahve bio s njim a od Šaula je odstupio.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 18, 13, 'Zato ga Šaul ukloni iz svoje blizine i postavi ga za tisućnika: on je izlazio i vraćao se na čelu naroda.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 18, 14, 'David je imao uspjeha na svim svojim putovima jer Jahve bijaše s njim.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 18, 15, 'Kad je Šaul vidio da David ima mnogo uspjeha, obuze ga strah od njega.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 18, 16, 'Ali svemu Izraelu i Judi omilje David jer ih je on vodio na svim njihovim putovima.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 18, 17, 'Šaul reče Davidu: \"Evo svoju najstariju kćer Merabu dat ću ti za ženu, samo mi budi hrabar i vodi Jahvine bojeve!\" Mišljaše Šaul: \"Neću da padne od moje ruke, nego filistejska ruka neka se digne na njega!\"');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 18, 18, 'A David odgovori: \"Tko sam ja i što znači moj život, što li kuća oca mojega u Izraelu da budem kraljev zet?\"');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 18, 19, 'I kad dođe vrijeme da Šaulova kći Meraba pođe za Davida, dadoše je za ženu Adrielu iz Mehole.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 18, 20, 'Ali je Davida ljubila Šaulova kći Mikala; kad su to javili Šaulu, bilo mu je pravo.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 18, 21, 'Reče on u sebi: \"Dat ću mu je, ali će mu ona biti zamka i ruka filistejska dići će se na njega.\" (Šaul je po drugi put rekao Davidu: \"Danas ćeš mi biti zet.\")');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 18, 22, 'Tada Šaul zapovjedi svojim slugama ovako: \"Razgovarajte se s Davidom tajno i recite mu: \'Gle, omilio si kralju i svi te njegovi dvorani vole; zato budi kraljev zet.\'\"');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 18, 23, 'I Šaulove sluge ponoviše te riječi Davidu, ali im David odgovori: \"Zar je u vašim očima malenkost postati kraljev zet? Ja sam samo siromah i mali čovjek!\"');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 18, 24, 'Šaulove sluge dojaviše to Šaulu govoreći: \"Evo riječi što ih je rekao David.\"');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 18, 25, 'A Šaul odgovori: \"Ovako recite Davidu: \'Kralj ne traži nikakva ženidbenog dara nego samo sto filistejskih obrezaka da se osveti kraljevim neprijateljima.\'\" Šaul mišljaše da će tako Davida gurnuti u ruke Filistejcima.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 18, 26, 'Šaulove sluge dojaviše te riječi Davidu, a njemu bijaše po volji da postane kraljev zet. Još prije nego što je isteklo vrijeme,');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 18, 27, 'spremi se David i krenu sa svojim ljudima te ubi Filistejcima dvije stotine ljudi; i donese njihove obreske i predade ih kralju na broj da bi postao njegov zet. Tada mu Šaul dade svoju kćer Mikalu za ženu.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 18, 28, 'Šaul je jasno vidio da je Jahve s Davidom i da ga ljubi sav dom Izraelov.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 18, 29, 'I Šaul se još većma poboja Davida i posta neprijatelj Davidu zauvijek.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 18, 30, 'A filistejski su knezovi izlazili u boj, ali koliko su god puta izlazili, David je imao više uspjeha nego svi Šaulovi dvorani; i tako ime njegovo posta vrlo slavno.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 19, 1, 'Šaul razloži svome sinu Jonatanu i svim svojim dvoranima svoju namjeru da ubije Davida. Ali Jonatan, Šaulov sin, vrlo je volio Davida.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 19, 2, 'I Jonatan to javi Davidu ovako: \"Moj otac Šaul kani te ubiti. Budi, dakle, na oprezu sutra ujutro, ostani u skrovištu i pritaji se.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 19, 3, 'A ja ću izaći i stajat ću pokraj svoga oca u polju gdje ti budeš i govorit ću za tebe sa svojim ocem. Kad saznam kako je, javit ću ti.\"');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 19, 4, 'Jonatan pohvali Davida svome ocu Šaulu i reče mu ovako: \"Neka se kralj ne ogriješi o svoga slugu Davida jer se on nije ništa ogriješio o tebe; naprotiv, ono što je radio bilo je od velike koristi za tebe.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 19, 5, 'On je stavio život svoj na kocku, ubio je Filistejca i Jahve je pribavio veliku pobjedu svemu Izraelu: vidio si i radovao se. Zašto bi se, dakle, ogriješio o nevinu krv ubijajući Davida bez razloga?\"');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 19, 6, 'Šaul posluša Jonatanove riječi i zakle se: \"Živoga mi Jahve, David neće umrijeti!\"');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 19, 7, 'Tada Jonatan dozva Davida i kaza mu sve te riječi. Zatim Jonatan dovede Davida k Šaulu i David opet dobi službu koju je imao prije.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 19, 8, 'Kad je rat i opet buknuo, iziđe David na bojište da se bori s Filistejcima; i porazi ih tako da su pobjegli pred njim.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 19, 9, 'Tada zao duh Jahvin obuze Šaula: kad je sjedio u svojoj kući, s kopljem u ruci, a David rukom udarao u harfu,');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 19, 10, 'Šaul pokuša da svojim kopljem pribode Davida uza zid, ali on izmakne Šaulovu udarcu te se koplje zabode u zid. David pobježe i spasi se.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 19, 11, 'Iste noći Šaul posla glasnike da nadziru Davidovu kuću jer je htio da ubije Davida u rano jutro. Ali Davidova žena Mikala javi to Davidu govoreći: \"Ako noćas ne umakneš na sigurno mjesto, sutra ćeš biti mrtav!\"');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 19, 12, 'Tada Mikala spusti Davida kroz prozor. On ode i spasi se bijegom.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 19, 13, 'A Mikala uze idol, položi ga u postelju, stavi mu oko glave kozju dlaku i pokri ga pokrivačem.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 19, 14, 'Kad je Šaul poslao glasnike da uhvate Davida, ona im reče: \"Bolestan je.\"');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 19, 15, 'Ali Šaul vrati glasnike natrag da vide Davida i zapovjedi im: \"Donesite ga k meni u postelji da ga ubijem!\"');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 19, 16, 'A kad su glasnici ušli, gle: u postelji bješe idol, s kozjom dlakom oko glave!');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 19, 17, 'Tada Šaul reče Mikali: \"Zašto si me tako prevarila i pustila moga neprijatelja da pobjegne i da se spasi?\" A Mikala odgovori Šaulu: \"On mi je rekao: \'Pusti me da odem, ili ću te ubiti!\'\"');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 19, 18, 'Tako je David pobjegao i spasio se. I ode on k Samuelu u Ramu i javi mu sve što mu je učinio Šaul. Potom odoše on i Samuel i nastaniše se u Najotu.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 19, 19, 'A Šaulu javiše ovako: \"Eno Davida u Najotu u Rami.\"');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 19, 20, 'Tada Šaul posla glasnike da uhvate Davida. Kad su oni vidjeli zbor proroka u proročkom zanosu, a Samuela im na čelu, obuze Božji duh i Šaulove glasnike te i oni padoše u proročki zanos.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 19, 21, 'Kad su to javili Šaulu, on posla druge glasnike, ali i oni padoše u proročki zanos. Potom Šaul posla i treće glasnike, ali i oni padoše u proročki zanos.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 19, 22, 'Tada Šaul krenu sam u Ramu i kad dođe do velikog bunara kod Sekua, zapita: \"Gdje su Samuel i David?\" I odgovoriše mu: \"Eno ih u Najotu u Rami.\"');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 19, 23, 'On odmah pođe prema Najotu u Rami. Ali i njega obuze duh Božji te je išao u proročkom zanosu sve dok nije došao u Najot u Rami.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 19, 24, 'Tu i on svuče svoje haljine jer i njega obuze zanos pred Samuelom; zatim je legao gol i ostao tako cio onaj dan i svu noć. Tako je nastala uzrečica: \"Zar je i Šaul među prorocima?\"');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 20, 1, 'David pobježe iz Najota u Rami i dođe k Jonatanu te mu reče: \"Što sam učinio? Kakva je bila moja krivica i što sam zgriješio tvome ocu da traži moj život?\"');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 20, 2, 'A on mu odgovori: \"Daleko od tebe ta misao! Ti nećeš poginuti. Eto, moj otac ne poduzima ništa, bilo veliko ili ne bilo, a da to meni ne otkrije. Zašto bi, dakle, moj otac krio od mene upravo to? Neće to biti!\"');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 20, 3, 'Ali se David zakle i reče: \"Tvoj otac dobro zna da sam ja stekao tvoju naklonost, pa misli: \'Ne treba da Jonatan išta zna o tome, da ne bude žalostan.\' Ali živoga mi Jahve i života mi tvoga, ima samo jedan korak između mene i smrti.\"');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 20, 4, 'Tada Jonatan upita Davida: \"Što želiš da učinim za tebe?\"');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 20, 5, 'A David odgovori Jonatanu: \"Evo, sutra je mladi mjesec i ja bih morao jesti s kraljem za stolom; ali me ti pusti da odem, da se sakrijem u polju do večera.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 20, 6, 'Ako tvoj otac opazi da me nema, reći ćeš mu ovako: \'David me uporno molio da ga pustim da skokne u svoj grad Betlehem, jer se ondje slavi godišnja žrtva za svu njegovu obitelj.\'');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 20, 7, 'Ako on rekne: \'Dobro!\', tvoj je sluga spašen. Ako li plane gnjevom, znaj da je čvrsto naumio da me pogubi.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 20, 8, 'Iskaži, dakle, milost svome sluzi kad si slugu svoga uveo sa sobom u savez Jahvin. Ali ako ima kakva krivica na meni, ubij me sam; zašto bi me vodio k svome ocu?\"');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 20, 9, 'A Jonatan mu odgovori: \"Daleko od tebe ta misao! Kad bih ja pouzdano znao da je moj otac čvrsto naumio da na tebe svali nesreću, zar ti ja ne bih dojavio?\"');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 20, 10, 'David upita Jonatana: \"A tko će mi javiti ako ti tvoj otac odgovori što zlo?\"');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 20, 11, 'Jonatan odgovori Davidu: \"Hodi, izađimo u polje!\" I izađu obojica u polje.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 20, 12, 'Tada Jonatan reče Davidu: \"Jahve, Bog Izraelov, neka mi bude svjedok! Ja ću iskušati svoga oca sutra u ovo doba. Ako bude dobro po Davida, a ja ne pošaljem k tebi da te obavijestim,');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 20, 13, 'neka Jahve učini to zlo Jonatanu i neka mu doda drugo zlo! Ako li mome ocu bude drago da ti učini zlo, javit ću ti i pustit ću te da odeš u miru; i Jahve neka bude s tobom kao što je bio s mojim ocem!');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 20, 14, 'Ako ja još budem živ, moći ćeš mi iskazati milosrđe Jahvino; ako li umrem,');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 20, 15, 'ne uskrati svoje dobrote mome domu dovijeka! Kad Jahve redom iskorijeni Davidove neprijatelje s lica zemlje,');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 20, 16, 'neka ime Jonatanovo ne iščezne s domom Šaulovim, inače će Jahve tražiti o tome račun od Davida.\"');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 20, 17, 'Tada se Jonatan još jednom zakune Davidu ljubavlju svojom, jer ga je ljubio svom ljubavlju duše svoje.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 20, 18, 'Potom reče Jonatan Davidu: \"Sutra je mladi mjesec i opazit će se da te nema, jer će tvoje mjesto biti prazno.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 20, 19, 'Prekosutra će se još očitije vidjeti da te nema, a ti dođi na mjesto gdje si se bio sakrio u dan onoga događaja i sjedni kraj onoga humka što ga znaš.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 20, 20, 'A ja ću prekosutra izmetati strijele na onu stranu kao da gađam onamo.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 20, 21, 'A onda ću poslati momka i reći mu: \'Idi! Nađi strijelu!\' Ako onda doviknem momku: \'Pazi, strijela je ovamo bliže od tebe, donesi je!\' - ti onda dođi, jer je za tebe dobro i nema nikakve opasnosti, tako mi Jahve živoga!');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 20, 22, 'Ako li doviknem momku: \'Pazi, strijela je onamo dalje od tebe!\' - ti onda otiđi, jer te Jahve šalje odavde.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 20, 23, 'A za ovaj dogovor što smo ga ugovorili ja i ti neka je Jahve svjedok između mene i tebe dovijeka!\"');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 20, 24, 'Potom se David sakri u polju. Kad je došao mlađak, kralj je sjeo za stol da jede.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 20, 25, 'Kralj sjede na svoje obično mjesto, na mjesto uza zid, Jonatan se smjesti sučelice njemu, Abner sjede kraj Šaula, a Davidovo mjesto osta prazno.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 20, 26, 'Ali Šaul ne reče ništa onaj dan jer mišljaše: \"Dogodilo mu se štogod, bit će da nije čist.\"');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 20, 27, 'Sutradan iza mladog mjeseca, drugi dan u mjesecu, opet Davidovo mjesto osta prazno, i Šaul upita svoga sina Jonatana: \"Zašto Jišajev sin nije došao na objed ni jučer ni danas?\"');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 20, 28, 'A Jonatan odgovori Šaulu: \"David me uporno molio da ga pustim da ide u Betlehem.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 20, 29, 'Rekao mi je: \'Pusti me da idem jer slavimo obiteljsku žrtvu u mom gradu i moja su me braća pozvala da dođem. Ako sam, dakle, stekao tvoju naklonost, daj mi dopust da pohodim svoju braću.\' Eto, zato ga nema kod kraljeva stola.\"');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 20, 30, 'Tada Šaul planu gnjevom na Jonatana i reče mu: \"Izrode i propalico! Misliš da ne znam da si u savezu s Jišajevim sinom, na sramotu svoju i na sramotu majčinu krilu!');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 20, 31, 'Jer dokle god bude živ na zemlji Jišajev sin, nećeš biti siguran ni ti ni tvoje kraljevstvo. Zato sad pošalji po njega i dovedi ga k meni jer je osuđen na smrt.\"');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 20, 32, 'A Jonatan odvrati svome ocu Šaulu i reče mu: \"Zašto on mora umrijeti? Što je učinio?\"');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 20, 33, 'Tada Šaul izmetnu koplje na sina da ga probode. Jonatan vidje da je njegov otac odlučio da ubije Davida.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 20, 34, 'Jonatan ustade od stola sav jarostan i nije jeo ništa toga drugog dana u mjesecu jer se zabrinuo za Davida što ga je njegov otac pogrdio.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 20, 35, 'Sutradan ujutro izađe Jonatan u polje prema dogovoru s Davidom; s njim je išao mlad momak.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 20, 36, 'I on reče svome momku: \"Ti ćeš otrčati i naći strijele koje ću sada izmetnuti.\" I momak otrča, a Jonatan odape strijelu tako da je preletjela preko njega.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 20, 37, 'Kad je momak došao do mjesta gdje je bila strijela koju je izbacio Jonatan, viknu Jonatan za momkom: \"Nije li strijela onamo dalje od tebe?\"');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 20, 38, 'Još Jonatan viknu za momkom: \"Brže! Požuri se! Ne stoj!\" Jonatanov momak diže strijelu i donese je svome gospodaru.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 20, 39, 'Momak nije ništa opazio, samo su Jonatan i David znali o čemu se radi.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 20, 40, 'Nato Jonatan preda oružje momku i reče mu: \"Idi i odnesi to u grad!\"');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 20, 41, 'Kad je momak otišao, David iziđe iza humka, pade ničice na zemlju i pokloni se tri puta. Potom se izljubiše i plakahu zajedno dok se nisu isplakali.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 20, 42, 'Zatim Jonatan reče Davidu: \"Idi u miru! Što smo se obojica zakleli Jahvinim imenom, neka Jahve bude svjedok između mene i tebe, između moga potomstva i tvoga potomstva dovijeka!\"');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 21, 1, 'Nato David usta i ode, a Jonatan se vrati u grad.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 21, 2, 'David dođe u Nob k svećeniku Ahimeleku. Ovaj dršćući pođe u susret Davidu i upita ga: \"Zašto si sam i nema nikoga s tobom?\"');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 21, 3, 'A David odgovori svećeniku Ahimeleku: \"Kralj mi je dao nalog i rekao mi: \'Nitko neka ništa ne dozna zašto te šaljem i što sam ti zapovjedio!\' A momke sam poslao da me dočekaju na tom i tom mjestu.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 21, 4, 'A sada, ako imaš pri ruci pet hljebova, daj mi ih, ili što god se nađe!\"');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 21, 5, 'A svećenik odgovori Davidu: \"Nemam pri ruci običnoga kruha nego samo svetoga kruha; ali samo ako su se tvoji momci uzdržali od žena.\"');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 21, 6, 'David odgovori svećeniku ovako: \"Sasvim pouzdano! Žene su nam bile uskraćene, kao uvijek kad izlazimo na vojni pohod, i tijela su u momaka čista. Iako je ovo običan put, uistinu su danas čisti tijelom.\"');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 21, 7, 'Tada mu svećenik dade svetoga kruha, jer nije bilo drugoga kruha ondje osim žrtvenoga, onoga koji se uklanjao ispred Jahve da se zamijeni toplim kruhom u dan kad se uzima.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 21, 8, 'Ondje je istoga dana bio jedan od Šaulovih slugu, zadržao se pred Jahvom; zvao se Doeg Edomac, a bio je nadglednik Šaulovih pastira.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 21, 9, 'David upita Ahimeleka: \"A nemaš li ovdje pri ruci kakvo koplje ili mač? Nisam uzeo sa sobom ni svoga mača ni svoga oružja, jer je kraljev nalog bio hitan.\"');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 21, 10, 'A svećenik mu odgovori: \"Ovdje je mač Filistejca Golijata, onoga koga si ubio u Terebintskoj dolini; zamotan je u plašt i položen iza oplećka; ako ga hoćeš uzeti, uzmi ga samo, jer drugoga osim njega nema ovdje.\" A David odvrati: \"Takva više nema, daj mi ga!\"');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 21, 11, 'Potom David ustade i pobježe onaj dan daleko od Šaula i dođe Akišu, kralju Gata.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 21, 12, 'A dvorani Akiševi rekoše svome kralju: \"Nije li to David, kralj zemlje? To je onaj o kome su plešući pjevali: \'Pobi Šaul svoje tisuće, David na desetke tisuća.\'\"');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 21, 13, 'David se zamisli o tim riječima i silno se uplaši gatskoga kralja Akiša.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 21, 14, 'Tada se David poče pretvarati pred njima kao da je umobolan i vladati se kao luđak u njihovim rukama: bubnjao je po vratima i puštao da mu teče slina niz bradu.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 21, 15, 'Tada Akiš reče svojim dvoranima: \"Vidite dobro da je čovjek lud! Zašto ga dovodite k meni?');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 21, 16, 'Zar nemam dosta budala te mi dovodite ovoga da mi dosađuje svojim ludilom? Zar će taj ući u moju kuću?\"');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 22, 1, 'David ode odande i skloni se u spilju Adulam. A kad su to čula njegova braća i sva njegova obitelj, dođoše onamo da mu se priključe.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 22, 2, 'Osim toga skupiše se oko njega svi koji bijahu u nevolji, svi zaduženi, svi nezadovoljni, i on im posta vođom. A bijaše ih oko njega do četiri stotine ljudi.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 22, 3, 'Odande ode David u Mispu u zemlji moapskoj i reče kralju moapskome: \"Dopusti da se moj otac i moja mati sklonu kod vas dok ne vidim što će Bog učiniti sa mnom.\"');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 22, 4, 'I ostavi ih kod kralja moapskoga i oni ostadoše kod njega sve dok David bijaše u skrovištu.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 22, 5, 'Ali prorok Gad reče Davidu: \"Nemoj ostati u svome skrovištu, nego idi i zađi u zemlju Judinu.\" I David ode i zađe u Heretsku šumu.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 22, 6, 'Šaul doznade da se pojavio David s ljudima koji bijahu s njim. Šaul je upravo bio u Gibei; sjedio je pod tamariskom na uzvišici, s kopljem u ruci, a oko njega stajali svi njegovi dvorani.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 22, 7, 'I reče Šaul svojim dvoranima koji stajahu oko njega: \"Poslušajte me, sinovi Benjaminovi! Hoće li vam i Jišajev sin svima darovati njive i vinograde? Hoće li vas sve postaviti za tisućnike i stotnike?');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 22, 8, 'A zašto ste se onda svi urotili protiv mene? Nema nikoga da mi dojavi kad moj sin sklapa savez s Jišajevim sinom, nema nikoga među vama da me požali i da mi otkrije kako je moj sin podjario moga slugu na me, kao što se događa danas.\"');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 22, 9, 'Tada progovori Doeg Edomac, koji je stajao među Šaulovim dvoranima, i reče: \"Ja sam vidio Jišajeva sina kad je došao u Nob k Ahimeleku, Ahitubovu sinu.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 22, 10, 'Ovaj je zatražio za njega savjet od Jahve i dao mu hrane i predao mu mač Filistejca Golijata.\"');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 22, 11, 'Šaul nato zapovjedi da pozovu svećenika Ahimeleka, Ahitubova sina, i svu njegovu obitelj, svećenike u Nobu. I dođoše svi pred kralja.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 22, 12, 'Tada reče Šaul: \"Čuj me, Ahitubov sine!\" A on odgovori: \"Evo me, gospodaru!\"');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 22, 13, 'A Šaul ga upita: \"Zašto ste se urotili protiv mene, ti i Jišajev sin? Ti si mu dao kruha i mač i tražio si za njega savjet od Boga da se digne protiv mene kao neprijatelj, kao što se danas događa.\"');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 22, 14, 'Ahimelek odgovori kralju: \"A tko je među svim tvojim slugama ravan Davidu, tako vjeran, uz to kraljev zet, glavar tvoje tjelesne straže, čovjek koji je poštovan u tvojoj kući?');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 22, 15, 'Zar sam danas prvi put tražio za njega savjet od Boga? Daleko od mene svaka druga misao! Neka kralj ništa ne okrivljuje svoga sluge i sve njegove obitelji, jer sluga njegov nije znao od svega toga ništa!\"');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 22, 16, 'Ali kralj odvrati: \"Ti ćeš umrijeti, Ahimeleče, ti i sva tvoja obitelj!\"');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 22, 17, 'I kralj zapovjedi glasonošama koji stajahu oko njega: \"Pristupite i pogubite svećenike Jahvine jer su i oni pomogli Davidu: znali su da je na bijegu, a nisu mi to dojavili.\" Ali kraljevi stražari ne htjedoše dići ruke na Jahvine svećenike da ih smaknu.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 22, 18, 'Tada kralj zapovjedi Doegu: \"Pristupi ti i smakni svećenike!\" Doeg Edomac pristupi i smaknu svećenike: on pogubi u onaj dan osamdeset i pet ljudi koji su nosili laneni oplećak.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 22, 19, 'I Nob, svećenički grad, pohara oštricom mača, pobivši muškarce i žene, djecu i dojenčad, goveda, magarce i ovce.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 22, 20, 'Izbavio se samo jedan sin Ahimeleka, Ahitubova sina, po imenu Ebjatar i pobjegao k Davidu.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 22, 21, 'Ebjatar javi Davidu da je Šaul poklao Jahvine svećenike.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 22, 22, 'A David odvrati Ebjataru: \"Ja sam već onoga dana kad ondje bijaše Doeg Edomac znao da će on zacijelo javiti to Šaulu! Ja sam kriv za živote tvoga očinskog doma.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 22, 23, 'Ostani kod mene, ne boj se: tko bude tražio tvoj život, tražit će moj. Kod mene ćeš biti dobro čuvan.\"');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 23, 1, 'Javiše onda Davidu: \"Filistejci opsjedaju Keilu i pljačkaju gumna.\"');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 23, 2, 'David tada upita Jahvu: \"Treba li da idem na Filistejce i hoću li ih potući?\" A Jahve odgovori Davidu: \"Idi, potući ćeš Filistejce i oslobodit ćeš Keilu.\"');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 23, 3, 'Ali rekoše Davidu ljudi njegovi: \"Gle, mi smo već ovdje, u Judi, u neprestanom strahu; što će tek biti ako odemo u Keilu protiv filistejskih četa!\"');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 23, 4, 'Zato David još jednom upita Jahvu, a Jahve mu odgovori ovako: \"Ustani i siđi u Keilu jer ću predati Filistejce u tvoje ruke!\"');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 23, 5, 'David onda krenu sa svojim ljudima u Keilu, udari na Filistejce, otjera njihovu stoku i zada im težak poraz. Tako je David oslobodio građane Keile. -');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 23, 6, 'Kad je ono Ebjatar, Ahimelekov sin, pobjegao k Davidu, on je došao u Keilu noseći u ruci oplećak.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 23, 7, 'Kad su Šaulu javili da je David ušao u Keilu, reče Šaul: \"Bog ga je predao u moje ruke jer se sam uhvatio u zamku kad je ušao u grad s vratima i prijevornicama.\"');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 23, 8, 'I Šaul sazva sav narod na oružje da ide na Keilu i da opkoli Davida i njegove ljude.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 23, 9, 'Kad je David doznao da mu Šaul snuje zlo, reče svećeniku Ebjataru: \"Donesi oplećak!\"');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 23, 10, 'Nato se David pomoli: \"Jahve, Bože Izraelov, tvoj je sluga čuo da Šaul sprema navalu na Keilu da razori grad zbog mene.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 23, 11, 'Hoće li Šaul doći kao što je tvoj sluga čuo? Jahve, Bože Izraelov, odgovori svome sluzi!\" A Jahve odgovori: \"Doći će!\"');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 23, 12, 'David opet upita: \"Hoće li me prvaci Keile predati, mene i moje ljude, u Šaulove ruke?\" A Jahve odgovori: \"Predat će vas!\"');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 23, 13, 'Tada David ustade sa svojim ljudima, bijaše ih oko šest stotina; iziđoše iz Keile te lutahu kojekuda. A kad su Šaulu javili da je David utekao iz Keile, odusta od vojnog pohoda.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 23, 14, 'David se skloni u pustinju u gorska skloništa; nastani se na gori u pustinji Zifu. Šaul ga je neprestano tražio, ali ga Bog ne predade u njegove ruke.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 23, 15, 'David se bojao što je Šaul izišao na vojnu da napadne na njegov život. Zato je David ostao u pustinji Zifu, u Horši.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 23, 16, 'Tada Šaulov sin Jonatan krenu na put i dođe k Davidu u Horšu i ohrabri ga u ime Božje.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 23, 17, 'Reče mu: \"Ne boj se, jer te neće stići ruka moga oca Šaula. Ti ćeš kraljevati nad Izraelom, a ja ću biti drugi do tebe; i moj otac Šaul zna to dobro.\"');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 23, 18, 'I sklopiše njih dvojica savez pred Jahvom. David osta u Horši, a Jonatan ode svojoj kući.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 23, 19, 'Jednoga dana dođoše Zifejci k Šaulu u Gibeu i javiše mu: \"David se krije kod nas u gorskim skloništima u Horši, na brdu Hakili, što je južno od Ješimona.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 23, 20, 'Sada, kralju, kad god zaželiš sići, siđi, a naše je da ga predamo u ruke kralju.\"');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 23, 21, 'A Šaul odgovori: \"Blagoslovio vas Jahve što ste me požalili!');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 23, 22, 'Idite, dakle, raspitajte se još i dobro razvidite mjesto kamo ga donesu njegovi hitri koraci; rekli su mi da je vrlo lukav.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 23, 23, 'Zato pretražite sve rupe u koje se zavlači, pa se vratite k meni kad budete pouzdano znali. Tada ću ja poći s vama, pa ako bude gdje u zemlji, ići ću za njegovim tragom po svim Judinim rodovima.\"');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 23, 24, 'Tada krenuše na put i odoše u Zif, pred Šaulom. David je sa svojim ljudima bio u pustinji Maonu u Arabi, južno od Ješimona.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 23, 25, 'Potom i Šaul pođe sa svojim ljudima da traži Davida. Kad su to javili Davidu, siđe on u klanac koji leži u pustinji Maonu. Šaul to doznade i krenu u potjeru za Davidom u pustinju Maon.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 23, 26, 'Šaul je sa svojim ljudima išao jednom stranom planine, a David sa svojim ljudima drugom stranom planine. David se silno žurio da umakne Šaulu. Kad je Šaul sa svojim ljudima htio prijeći na drugu stranu da opkoli Davida i njegove ljude i da ih pohvata,');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 23, 27, 'dođe glasnik Šaulu s porukom: \"Dođi brže, Filistejci provališe u zemlju!\"');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 23, 28, 'Tada Šaul odusta od potjere za Davidom i okrenu se protiv Filistejaca. Zato se prozvalo ono mjesto \"Klanac razlaza\".');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 24, 1, 'David se odande uspe i nastani u engadskim gorskim skloništima.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 24, 2, 'Kad se Šaul vratio iz potjere za Filistejcima, javiše mu ovo: \"David je u Engadskoj pustinji!\"');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 24, 3, 'Tada Šaul uze tri tisuće odabranih ljudi iz svega Izraela i pođe da traži Davida i njegove ljude na istok od Litica divokoza.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 24, 4, 'Idući dođe k ovčjim torovima pokraj puta; ondje bijaše pećina i Šaul uđe da čučne; a David je sa svojim ljudima sjedio u dnu pećine.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 24, 5, 'I rekoše Davidu ljudi njegovi: \"Evo dana za koji ti je rekao Jahve: \'Ja ću predati tvoga neprijatelja u tvoje ruke, postupaj s njim kako ti se mili!\'\" A David ustade i neprimjetno odsiječe skut od Šaulova plašta.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 24, 6, 'Ali poslije zapeče Davida savjest što je odsjekao skut od Šaulova plašta,');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 24, 7, 'pa reče svojim ljudima: \"Očuvao me Jahve da takvo što učinim svome gospodaru, da dignem ruku na njega, jer je pomazanik Jahvin.\"');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 24, 8, 'I David oštrim riječima ukori svoje ljude i ne dopusti im da ustanu na Šaula. A Šaul izađe iz pećine i pođe svojim putem.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 24, 9, 'Zatim ustade David, iziđe iz pećine i vikne za Šaulom: \"Gospodaru kralju!\" A kad se Šaul obazre, David se baci ničice na zemlju i pokloni mu se.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 24, 10, 'Tada David reče Šaulu: \"Zašto slušaš ljude koji ti govore da David snuje tebi propast?');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 24, 11, 'Gle, upravo u ovaj dan tvoje su oči mogle vidjeti da te Jahve predao danas u moje ruke u ovoj pećini. Rekoše mi da te ubijem, ali te poštedjeh i rekoh: \'Neću dići svoje ruke na svoga gospodara, jer je Jahvin pomazanik.\'');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 24, 12, 'O, moj oče, pogledaj i vidi skut od svoga plašta u mojoj ruci: odsjekao sam skut od tvoga plašta, a tebe nisam ubio; spoznaj i vidi da u mojoj ruci nema ni zlobe ni opačine. Ja nisam zgriješio protiv tebe, a ti vrebaš na moj život da mi ga uzmeš!');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 24, 13, 'Jahve neka sudi između mene i tebe, Jahve neka me osveti na tebi, ali se moja ruka neće dići na tebe.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 24, 14, 'Kako kaže stara poslovica: od nepravednika dolazi nepravda, i zato se moja ruka neće dići protiv tebe.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 24, 15, 'Za kim je izišao izraelski kralj? Za kim ideš u potjeru? Za mrtvim psom, za običnom buhom!');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 24, 16, 'Jahve neka bude sudac, on neka sudi između mene i tebe, neka ispita i brani moju stvar i neka mi pribavi pravdu: neka me izbavi iz tvoje ruke!\"');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 24, 17, 'Kad je David izgovorio te riječi Šaulu, odvrati Šaul: \"Je li to tvoj glas, sine Davide?\" I Šaul glasno zaplaka.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 24, 18, 'Zatim reče Davidu: \"Pravedniji si od mene jer ti si meni učinio dobro, a ja sam tebi učinio zlo.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 24, 19, 'A danas si okrunio svoju dobrotu prema meni, jer me Jahve predao u tvoje ruke, a ti me nisi ubio.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 24, 20, 'Kad se čovjek namjeri na svoga neprijatelja, pušta li ga da ide mirno svojim putem? Neka ti Jahve naplati za ono dobro što si mi danas učinio!');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 24, 21, 'Sada pouzdano znam da ćeš zacijelo biti kralj i da će se kraljevstvo nad Izraelom trajno održati u tvojoj ruci.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 24, 22, 'Zato mi se sada zakuni Jahvom da nećeš zatrti moga potomstva poslije mene i da nećeš izbrisati moga imena iz moga očinskoga doma!\"');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 24, 23, 'David se zakle Šaulu, Šaul ode svojoj kući, a David se sa svojim ljudima vrati u gorska skloništa.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 25, 1, 'Uto umrije Samuel. Sav se Izrael skupi i oplaka ga naričući za njim; i pokopaše ga u njegovu zavičaju u Rami. A David usta i siđe u pustinju Paran.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 25, 2, 'U Maonu živio čovjek koji je imao svoje gospodarstvo u Karmelu; bio je to vrlo bogat čovjek, imao je tri tisuće ovaca i tisuću koza. Upravo je tada strigao svoje ovce u Karmelu.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 25, 3, 'Taj se čovjek zvao Nabal, a njegova žena Abigajila. Žena je bila mudra i vrlo lijepa, a čovjek surov i opak: bio je Kalebovac.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 25, 4, 'David je u pustinji čuo da Nabal striže svoje ovce.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 25, 5, 'Stoga posla deset momaka naloživši im: \"Idite gore u Karmel, otiđite k Nabalu i pozdravite ga u moje ime.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 25, 6, 'I recite ovako mome bratu: \'Mir tebi, mir tvome domu, mir svemu što imaš!');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 25, 7, 'Sada, čujem, strižeš ovce. A tvoji su pastiri bili kod nas, nismo ih dirali, ništa im nije nestalo dokle god su bili u Karmelu.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 25, 8, 'Pitaj svoje sluge i kazat će ti. Zato neka ovi momci nađu milost pred tobom, jer smo došli u svečan dan. Podaj svojim slugama i svome sinu Davidu što ti se nađe pri ruci.\'\"');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 25, 9, 'Dođoše momci Davidovi i ponoviše Nabalu u Davidovo ime sve ove riječi, a onda pričekaše.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 25, 10, 'Ali Nabal odgovori Davidovim slugama ovako: \"Tko je David, tko je Jišajev sin? Danas ima mnogo slugu koji su pobjegli od svojih gospodara.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 25, 11, 'Zar da uzmem svoj kruh, svoju vodu, svoju stoku koju sam poklao za svoje strigače pa da to poklonim ljudima o kojima ne znam ni odakle su?\"');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 25, 12, 'Davidovi se momci okrenuše i vratiše se svojim putem. Kad su se vratili, javiše sve ove riječi Davidu.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 25, 13, 'A David reče svojim ljudima: \"Pripašite svaki svoj mač!\" I pripasaše svaki svoj mač, i David pripasa svoj, i oko četiri stotine ljudi krenu za Davidom, dok ih dvije stotine osta kod tovara.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 25, 14, 'A ženi Nabalovoj, Abigajili, javio jedan od Nabalovih slugu ovo: \"Eto, David je poslao iz pustinje glasnike da pozdrave našega gospodara, a on ih potjerao.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 25, 15, 'A ti su ljudi bili vrlo dobri prema nama: nisu nas dirali, ništa nismo izgubili dokle god smo bili u njihovoj blizini kad smo bili u polju.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 25, 16, 'Noću i danju bili su nam kao bedem u sve vrijeme dok smo bili s njima pasući stada.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 25, 17, 'Razmisli sada i vidi što ćeš učiniti, jer je gotova pogibija našem gospodaru i svemu njegovu domu; a on je opak čovjek komu se ne može ništa kazati.\"');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 25, 18, 'Abigajila brzo uze dvije stotine hljebova, dva mijeha vina, pet zgotovljenih ovaca, pet mjera pržena žita, sto grozdova suhoga grožđa, dvije stotine smokovih kolača i sve to natovari na magarce.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 25, 19, 'I zapovjedi svojim slugama: \"Idite preda mnom, a ja ću za vama.\" Svome mužu Nabalu nije kazala ništa.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 25, 20, 'Dok je, jašući na magarcu, silazila iza gorskog zavoja, David je sa svojim ljudima silazio nasuprot njoj, tako da se ona susrela s njima.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 25, 21, 'A David je upravo mislio: \"Uzalud sam, dakle, zaštićivao u pustinji sve što je taj čovjek imao i ništa mu nije nestalo od svega što je posjedovao! Sada mi vraća zlo za dobro!');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 25, 22, 'Neka Bog učini Davidu ovo zlo i neka mu doda drugo ako Nabalu do zore od svega što ima ostavim i ono što mokri uza zid!\"');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 25, 23, 'Kad je Abigajila ugledala Davida, brzo sjaha s magarca i pade pred Davida ničice, poklonivši se do zemlje.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 25, 24, 'Bacivši mu se tako pred noge, reče: \"Gospodaru, neka na mene padne krivica! Dopusti da službenica tvoja progovori tvojim ušima i udostoj se poslušati riječi službenice svoje!');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 25, 25, 'Neka moj gospodar ne gleda na toga opakog čovjeka, na Nabala, jer on s pravom nosi svoje ime: zove se Luda i ludost je s njim. A ja, službenica tvoja, nisam vidjela momaka koje je poslao moj gospodar.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 25, 26, 'Zato sada, gospodaru, živoga mi Jahve, i tako živ bio ti, i tako ti Jahve koji te očuvao da ne svališ na se krvnu krivicu i da ne pribaviš sebi pravdu svojom rukom: neka prođu kao Nabal tvoji neprijatelji i oni koji snuju zlo mome gospodaru!');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 25, 27, 'A ovaj dar, što ga evo tvoja službenica nosi svome gospodaru, neka se dade momcima koji idu za mojim gospodarom na njegovim putovima.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 25, 28, 'Oprosti službenici svojoj njezinu krivnju! Zacijelo će Jahve osnovati trajan dom mome gospodaru, jer moj gospodar bije Jahvine bojeve i za svega tvoga života neće se naći zlo na tebi.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 25, 29, 'Ako se tko digne da te progoni i da ti radi o glavi, neka život moga gospodara bude pohranjen u škrinji života kod Jahve, tvoga Boga, a život tvojih neprijatelja neka on baci kao iz praćke.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 25, 30, 'I kad Jahve učini mome gospodaru svako dobro koje ti je obećao i kad te odredi da budeš knezom nad Izraelom,');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 25, 31, 'onda neka ne bude na smutnju ni na grižnju savjesti mome gospodaru da je ni za što prolio krv i da je sebi pribavio pravdu svojoj rukom. I kad Jahve učini dobro mome gospodaru, sjeti se tada službenice svoje!\"');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 25, 32, 'David odgovori Abigajili: \"Neka je blagoslovljen Jahve, Bog Izraelov, koji te danas poslao meni u susret!');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 25, 33, 'Neka je blagoslovljena tvoja mudrost i blagoslovljena bila ti što si me danas zadržala da ne svalim na se krvnu krivicu i da ne pribavim sebi pravdu svojom rukom.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 25, 34, 'Ali, tako mi živog Jahve, Boga Izraelova, koji nije dopustio da ti učinim zlo: da mi nisi tako brzo izišla u susret, zaista ne bi Nabalu do jutra ostalo ni ono što uza zid mokri!\"');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 25, 35, 'Nato David primi iz njezine ruke što mu bijaše donijela i reče joj: \"Vrati se s mirom svojoj kući. Gle, uslišao sam tvoj glas i obazreo se na tebe.\"');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 25, 36, 'Kad se Abigajila vratila k Nabalu, on je upravo imao gozbu u kući, pravu kraljevsku gozbu: Nabal bijaše veseo i sasvim pijan; zato mu ona ne reče ništa dok nije svanulo jutro.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 25, 37, 'A ujutro, kad se Nabal otrijeznio, pripovjedi mu njegova žena sve što se dogodilo, a njemu obamrije srce u grudima i on osta kao da se skamenio.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 25, 38, 'A desetak dana poslije toga Jahve udari Nabala te umrije.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 25, 39, 'Kad David ču da je umro Nabal, reče: \"Neka je blagoslovljen Jahve, koji mi je ispravio nepravdu što mi je učini Nabal; i Jahve je očuvao svoga slugu da ne učini zla, a svalio je Nabalovu zloću na njegovu glavu!\" Potom David posla poruku Abigajili da će je uzeti za ženu.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 25, 40, 'Davidove sluge dođoše k Abigajili u Karmel i rekoše joj: \"David nas je poslao k tebi da te uzme sebi za ženu.\"');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 25, 41, 'A ona ustade, pokloni se do zemlje i reče: \"Evo službenice tvoje koja je spremna da bude robinja i da pere noge slugama svoga gospodara!\"');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 25, 42, 'Potom Abigajila brzo ustade i zajaha na magarca, a za njom pođe pet njezinih dvorkinja. Tako je otišla za Davidovim poslanicima i postala njegovom ženom.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 25, 43, 'I Ahinoamom iz Jizreela bijaše se oženio David i obje mu bjehu žene.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 25, 44, 'Jer Šaul bijaše svoju kćer Mikalu, Davidovu ženu, dao Paltiju, sinu Lajiša iz Galima.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 26, 1, 'Ljudi iz Zifa dođoše Šaulu i javiše mu: \"David se krije na Hakilskom brdu, nasuprot Ješimonu.\"');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 26, 2, 'Šaul tada krenu na put i siđe u pustinju Zif, a s njim tri tisuće izabranih Izraelaca, da traži Davida u pustinji Zifu.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 26, 3, 'Šaul se utabori podno Hakilskog brda, koje je nasuprot Ješimonu, kraj puta. David, koji je boravio u pustinji, opazi da je Šaul došao onamo da ga progoni.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 26, 4, 'Zato David posla uhode i sazna da je Šaul zaista došao.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 26, 5, 'David se podiže i dođe do mjesta gdje se Šaul bio utaborio. Tu David ugleda mjesto gdje su spavali Šaul i Abner, sin Nerov, njegov vojvoda: Šaul je spavao usred tabora, a vojska ležala u krugu oko njega.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 26, 6, 'David se obrati Hetitu Ahimeleku i Abišaju, sinu Sarvijinu a bratu Joabovu, i reče im: \"Tko će sa mnom u tabor sve do Šaula?\" A Abišaj odgovori: \"Ja ću s tobom.\"');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 26, 7, 'I tako David i Abišaj dopriješe noću do vojske: i gle, Šaul ležaše i spavaše u taboru, a koplje mu kod uzglavlja zabodeno u zemlju. Abner i vojnici ležahu oko njega.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 26, 8, 'Tada Abišaj reče Davidu: \"Danas ti je Bog predao tvoga neprijatelja u tvoje ruke; zato sada dopusti da ga njegovim vlastitim kopljem pribodem za zemlju, jednim jedinim udarcem, drugoga mi neće trebati.\"');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 26, 9, 'Ali David odgovori Abišaju: \"Nemoj ga ubijati! Jer tko će dignuti ruku svoju na Jahvina pomazanika i ostati nekažnjen?\"');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 26, 10, 'Još nastavi David: \"Živoga mi Jahve, i udarit će ga Jahve, bilo da će mu doći njegov dan da umre, bilo da će otići u boj i poginuti.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 26, 11, 'Ne dao mi Jahve da dignem ruku na pomazanika Jahvina! Nego uzmi sada koplje što mu je kod uzglavlja i vrč za vodu, pa hajdemo!\"');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 26, 12, 'I uze David koplje i vrč za vodu što su bili kod Šaulova uzglavlja i oni odoše: nitko nije ništa vidio ni opazio, nitko se nije probudio, nego su svi spavali jer bijaše na njih pao dubok san od Jahve.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 26, 13, 'David prijeđe na drugu stranu i stade na vrh gore u nekoj daljini, tako da je među njima bio velik prostor.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 26, 14, 'Tada viknu vojsci i Abneru, Nerovu sinu, ovako: \"Zar se nećeš odazvati, Abnere?\" A Abner se odazva i upita: \"Tko si ti što uznemiruješ kralja?\"');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 26, 15, 'A David odgovori Abneru: \"Nisi li ti junak? I tko ti je ravan u Izraelu? Pa zašto onda nisi čuvao kralja, svoga gospodara? Jedan je od ratnika sišao do vas da ubije kralja, tvoga gospodara.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 26, 16, 'Nije lijepo to što si učinio. Tako mi živog Jahve, zaslužili ste smrt što niste čuvali svoga gospodara, pomazanika Jahvina. Pogledaj sada gdje je kraljevo koplje i gdje je vrč za vodu što mu bijaše do uzglavlja!\"');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 26, 17, 'Tada Šaul poznade Davidov glas i upita: \"Je li to tvoj glas, sine Davide?\" A David odgovori: \"Jest, kralju gospodaru!\"');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 26, 18, 'I nastavi: \"Zašto moj gospodar progoni svoga slugu? Što sam učinio? Kakva je krivica u mojoj ruci?');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 26, 19, 'Zato neka se sada moj gospodar i kralj udostoji poslušati riječi svoga sluge: ako te Jahve diže protiv mene, neka se prinosnicom ublaži; ako li to čine sinovi ljudski, neka su prokleti pred Jahvom jer su me izagnali, tako da ne mogu imati udjela u baštini Jahvinoj, kao da su mi govorili: \'Idi, služi tuđim bogovima!\'');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 26, 20, 'Zato neka ne padne moja krv na zemlju daleko od Jahvina lica. Jer kralj je Izraelov izišao u lov na moj život, kao kad tko goni jarebicu po planini.\"');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 26, 21, 'Tada Šaul reče: \"Zgriješio sam! Vrati mi se, sine Davide, neću ti više činiti zla, kad je danas moj život u očima tvojim bio tako drag. Jest, ludo sam radio i teško sam pogriješio!\"');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 26, 22, 'A David odgovori: \"Evo kraljeva koplja, neka dođe jedan od momaka i neka ga uzme!');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 26, 23, 'A Jahve će vratiti svakome po njegovoj pravdi i po njegovoj vjernosti: danas te Jahve bijaše predao u moje ruke, ali nisam htio dići ruke svoje na pomazanika Jahvina.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 26, 24, 'I gle, kako je danas tvoj život bio drag u mojim očima, tako neka moj život bude drag u Jahvinim očima! I neka me Jahve izbavi iz svake nevolje!\"');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 26, 25, 'A Šaul doviknu Davidu: \"Budi mi blagoslovljen, sine Davide! Zacijelo ćeš izvršiti svoje djelo i uspjet ćeš!\" Potom David ode svojim putem, a Šaul se vrati svojoj kući.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 27, 1, 'David reče u sebi: \"Ipak ću jednoga dana poginuti od Šaulove ruke. Zato nema ništa bolje za me nego da se spasim u zemlju Filistejaca. Tada će Šaul odustati da me dalje traži po svim krajevima Izraelovim i izbavit ću se iz njegove ruke.\"');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 27, 2, 'David se dakle podiže i prijeđe, sa šest stotina ljudi koje je imao, k Akišu, sinu Maokovu, kralju Gata.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 27, 3, 'David se nastani kod Akiša u Gatu, on i njegovi ljudi, svaki sa svojom obitelji, a David sa svoje dvije žene, Ahinoamom Jizreelkom i Abigajilom, Nabalovom ženom iz Karmela.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 27, 4, 'Kad je Šaul doznao da je David pobjegao u Gat, nije ga više progonio.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 27, 5, 'David reče Akišu: \"Ako sam našao milost u tvojim očima, neka mi dadu mjesto u jednom gradu u zemlji da se nastanim u njemu. Zašto da tvoj sluga stanuje kod tebe u kraljevskom gradu?\"');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 27, 6, 'Akiš mu još istoga dana dade Siklag. Stoga Siklag pripada do današnjega dana kraljevima Jude.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 27, 7, 'I osta David u filistejskoj zemlji godinu dana i četiri mjeseca.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 27, 8, 'David je sa svojim ljudima izlazio da pljačka Gešurce, Girzijce i Amalečane, jer su to bili stanovnici zemlje od Telama preko Šura sve do egipatske zemlje.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 27, 9, 'David je pustošio zemlju ne ostavljajući na životu ni čovjeka ni žene, otimao je ovce i goveda, magarce, deve i haljine i vraćao se da sve to donese Akišu.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 27, 10, 'Akiš bi ga pitao: \"Gdje ste danas pljačkali?\" A David bi odgovorio da su pljačkali u Negebu Judinu ili u Negebu Jerahmeelskom ili u Negebu Kenijskom.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 27, 11, 'David nije ostavljao na životu ni čovjeka ni žene da ih dovede u Gat jer mišljaše: \"Mogli bi nas optužiti i reći: \'Tako je David radio.\'\" Takav je imao običaj za sve vrijeme dok je boravio u filistejskoj zemlji.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 27, 12, 'Akiš je vjerovao Davidu i govorio u sebi: \"Baš se omrazio svome narodu, Izraelu! Zato će mi biti sluga dovijeka!\"');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 28, 1, 'U ono vrijeme Filistejci skupiše svoje čete za rat protiv Izraela. I Akiš reče Davidu: \"Znaj da ćeš ići sa mnom na vojsku, ti i tvoji ljudi!\"');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 28, 2, 'A David odgovori Akišu: \"Dobro! Sad ćeš vidjeti što će učiniti tvoj sluga!\" A Akiš odvrati Davidu: \"Dobro! Zato ću te postaviti da budeš mojim čuvarom zauvijek.\"');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 28, 3, 'Samuel bijaše umro, a sav ga Izrael bijaše oplakao naričući za njim. Ukopali su ga u njegovu gradu Rami. A Šaul bijaše istjerao iz zemlje sve zazivače duhova i vračeve.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 28, 4, 'Dok su se Filistejci skupljali te došli i utaborili se kod Šunema, Šaul skupi sve Izraelce te se utabori na Gilboi.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 28, 5, 'Kad Šaul ugleda filistejski tabor, uplaši se i srce mu snažno zadrhta.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 28, 6, 'Šaul upita za savjet Jahvu, ali mu Jahve ne dade odgovora - ni u snima, ni po Urimu, ni preko proroka.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 28, 7, 'Zato Šaul reče svojim slugama: \"Potražite mi ženu koja zaziva duhove da odem k njoj i upitam je.\" A sluge mu odgovoriše: \"Evo, u En Doru ima žena koja zaziva duhove.\"');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 28, 8, 'Tada se Šaul preruši, obuče druge haljine i otputi se sa dva čovjeka. I dođe noću k onoj ženi i reče joj: \"Daj mi vračaj pomoću duha i dozovi mi onoga koga ti reknem.\"');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 28, 9, 'A žena mu odgovori: \"Ta ti znaš što je učinio Šaul i kako je istrijebio iz zemlje zazivače duhova i vračeve. Zašto postavljaš zamke mome životu da me pogubiš?\"');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 28, 10, 'A Šaul joj se zakle Jahvom govoreći: \"Tako mi živog Jahve, nećeš biti ništa kriva za ovo!\"');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 28, 11, 'Tada žena zapita: \"Koga da ti dozovem?\" A on odgovori: \"Dozovi mi Samuela!\"');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 28, 12, 'Kad žena ugleda Samuela, povika iza glasa, a onda reče Šaulu: \"Zašto si me prevario? Ta ti si Šaul!\"');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 28, 13, 'A kralj joj odvrati: \"Ne boj se! Nego što vidiš?\" A žena odgovori Šaulu: \"Vidim nešto božansko što se diže iz zemlje.\"');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 28, 14, 'Šaul je upita: \"Kakva je obličja?\" A ona odgovori: \"Izlazi starac, ogrnut plaštem.\" Tada Šaul spozna da je to Samuel, pa pade licem do zemlje i pokloni se.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 28, 15, 'Samuel upita Šaula: \"Zašto si pomutio moj mir dozivajući me gore?\" A Šaul odgovori: \"U velikoj sam nevolji jer su Filistejci zavojštili na me, a Bog se okrenuo od mene i ne odgovara mi više ni preko proroka ni u snima. Zato sam dozvao tebe da me poučiš što da činim.\"');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 28, 16, 'A Samuel odvrati: \"Zašto mene pitaš kad se Jahve odvratio od tebe i postao ti neprijateljem?');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 28, 17, 'Jahve ti je učinio kako ti je kazao preko mene: istrgao je kraljevstvo iz tvoje ruke i dao ga tvome suparniku, Davidu,');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 28, 18, 'jer nisi poslušao riječi Jahvinih i jer nisi izvršio njegova žestokog gnjeva na Amaleku: stoga ti je Jahve danas ovako učinio.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 28, 19, 'Jahve će predati, zajedno s tobom, i Izraela u filistejske ruke. Sutra ćeš sa svojim sinovima biti sa mnom, a i tabor izraelski Jahve će predati u filistejske ruke.\"');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 28, 20, 'Šaul se užasnu i pade na zemlju kako je dug. Spopade ga silan strah od Samuelovih riječi. I ponestade mu snage, jer nije ništa jeo cijeli dan i cijelu noć.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 28, 21, 'Kad ona žena dođe k Šaulu i opazi kako je sav zaplašen, reče mu: \"Gle, tvoja je službenica poslušala tvoju riječ, stavila sam svoj život na kocku i poslušala tvoje zapovijedi koje si mi naložio.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 28, 22, 'Zato sada poslušaj i ti riječi službenice svoje: dopusti da ti pružim zalogaj kruha; jedi da ti se vrati snaga te uzmogneš poći svojim putem.\"');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 28, 23, 'Ali on ne htjede nego reče: \"Neću jesti!\" Ali kad ga zaokupiše njegove sluge, zajedno sa ženom, posluša ih, ustade sa zemlje i sjede na postelju.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 28, 24, 'Žena je imala kod kuće tele u tovu. Brzo ga zakla, zatim uze brašna, umijesi ga i napeče beskvasnoga kruha.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 28, 25, 'Potom stavi sve pred Šaula i njegove ljude. Pošto su jeli, ustadoše i još iste noći krenuše natrag.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 29, 1, 'Filistejci skupiše sve svoje čete u Afeku, a Izraelci se utaboriše kod izvora u Jizreelu.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 29, 2, 'Filistejski su knezovi prolazili sa svojim stotinama i tisućama, a David i njegovi ljudi išli su sasvim na kraju s Akišem.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 29, 3, 'Filistejski knezovi zapitaše: \"Što hoće ti Hebreji ovdje?\" A Akiš odgovori filistejskim knezovima: \"Pa ovo je David, sluga izraelskoga kralja Šaula! Već je godinu-dvije kod mene, ali nisam našao na njemu ništa sumnjivo od onoga dana kad je prebjegao k meni pa do današnjega dana.\"');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 29, 4, 'Ali filistejski knezovi planuše na njega i rekoše mu: \"Pošalji toga čovjeka natrag, neka se vrati na mjesto koje si mu označio. Neka ne ide s nama u boj, da se ne okrene protiv nas u boju! Čime bi se on opet umilio svome gospodaru ako ne glavama ovih naših ljudi?');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 29, 5, 'To je onaj isti David o kome se pjevalo igrajući: \'Pobi Šaul svoje tisuće, David na desetke tisuća!\'\"');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 29, 6, 'Tada Akiš dozva Davida i reče mu: \"Živoga mi Jahve, ti si pošten i meni bi drago bilo da me pratiš u pokretima moje vojske, jer nisam našao nikakva zla na tebi od onoga dana kad si došao k meni pa do današnjega dana. Ali nisi drag u očima knezova.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 29, 7, 'Zato se sada vrati i otiđi s mirom kući da ne ozlovoljiš filistejske knezove!\"');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 29, 8, 'David odvrati Akišu: \"Ta što sam učinio i što si zamjerio svome sluzi od onoga dana kad sam stupio u tvoju službu pa do današnjega dana da ne mogu ići da se bijem s neprijateljima svoga gospodara kralja?\"');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 29, 9, 'A Akiš odgovori Davidu: \"Ti znaš da si mi drag kao Božji anđeo, ali su filistejski knezovi rekli: \'Neka ne ide s nama u boj!\'');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 29, 10, 'Zato ustanite rano ujutro, ti i sluge tvoga gospodara koji su došli s tobom, i otiđite na mjesto koje sam vam označio. I nemoj gajiti u svom srcu nikakve mržnje jer si mi mio. Ustat ćete, dakle, u rano jutro, čim svane, i otići ćete!\"');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 29, 11, 'Tako David sa svojim ljudima ustade rano i krenu odmah ujutro i vrati se u filistejsku zemlju, a Filistejci odoše u Jizreel.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 30, 1, 'Kad je David sa svojim ljudima treći dan stigao u Siklag, a to Amalečani bijahu navalili na Negeb i na Siklag; opljačkali su Siklag i ognjem ga spalili.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 30, 2, 'Zarobili su žene i sve koji su bili ondje, malo i veliko. Nisu ubili nikoga, nego su samo odveli roblje i otišli svojim putem.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 30, 3, 'Kad je, dakle, David sa svojim ljudima došao u grad, vidješe da je grad spaljen, a njihove žene, njihovi sinovi i njihove kćeri odvedeni u ropstvo.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 30, 4, 'Tada David i ljudi koji bijahu s njim podigoše glas i plakahu dok im nije ponestalo snage za plač.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 30, 5, 'I obje Davidove žene bijahu odvedene u ropstvo - Ahinoama Jizreelka i Abigajila, Nabalova žena iz Karmela.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 30, 6, 'David se našao u velikoj nevolji jer su ljudi počeli govoriti da će ga kamenovati, budući da su svi bili ogorčeni, svaki zbog svojih sinova i zbog svojih kćeri. Ali se David ohrabri u Jahvi, svome Bogu.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 30, 7, 'David reče svećeniku Ebjataru, Ahimelekovu sinu: \"Donesi mi ovamo oplećak!\" I Ebjatar donese Davidu oplećak.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 30, 8, 'Tada David upita Jahvu za savjet govoreći: \"Hoću li u potjeru za onim razbojnicima i hoću li ih stići?\" A on mu odgovori: \"Idi u potjeru jer ćeš ih zacijelo stići i zarobljenike ćeš izbaviti.\"');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 30, 9, 'I pođe David sa šest stotina ljudi koji bijahu s njim i dođoše do potoka Besora.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 30, 10, 'Odavde David sa četiri stotine ljudi nastavi potjeru, a ostadoše dvije stotine ljudi što bijahu tako umorni da nisu mogli prijeći preko potoka Besora.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 30, 11, 'U polju naiđoše na nekog Egipćanina. Dovedoše ga k Davidu, dadoše mu kruha da jede i vode da pije.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 30, 12, 'Dadoše mu grudu smokava i dva grozda suhoga grožđa. Kad je to pojeo, vratio mu se život, jer tri dana i tri noći ne bijaše ništa jeo i ništa pio.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 30, 13, 'Tada ga David upita: \"Čiji si ti i odakle si?\" A on odgovori: \"Ja sam Egipćanin, sluga jednog Amalečanina. Moj me gospodar ostavio jer sam se razbolio prije tri dana.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 30, 14, 'Bili smo provalili u Negeb Keretski i Negeb Judejski, i u Negeb Kalebov, a Siklag smo zapalili ognjem.\"');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 30, 15, 'David ga upita: \"Hoćeš li me odvesti k toj razbojničkoj družbi?\" A on odgovori: \"Zakuni mi se Bogom da me nećeš pogubiti i da me nećeš predati u ruke mome gospodaru, pa ću te odvesti k njima!\"');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 30, 16, 'On ga, dakle, odvede, i gle, oni se bijahu razasuli po svem onom kraju, jedući, pijući i slaveći slavlje zbog svega velikog plijena što su ga oteli iz zemlje filistejske i iz zemlje Judine.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 30, 17, 'I David ih poče biti i tukao ih je od zore do mraka, izvršujući na njima \"herem\", kleto uništenje. Nitko od njih nije izmakao, osim četiri stotine momaka, koji zajahaše na deve i pobjegoše.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 30, 18, 'Tako je David izbavio sve što su bili oteli Amalečani; i obje svoje žene izbavi David.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 30, 19, 'I ništa im nije nestalo, od najmanjih stvari do najvećih, od plijena sve do sinova i kćeri, sve što im bijaše oteto: sve je vratio David.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 30, 20, 'Tada uzeše sve ovce i goveda, dotjeraše ih pred njega vičući: \"Ovo je plijen Davidov!\"');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 30, 21, 'Kad je David došao k onim dvjema stotinama ljudi koji bijahu sustali te ne mogahu ići za Davidom i koje on bijaše ostavio kod potoka Besora, iziđoše oni u susret Davidu i četi njegovoj: približivši se Davidu i četi, pozdraviše ih.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 30, 22, 'Tada progovoriše svi zlobnici i ništarije između ljudi koji su išli s Davidom i rekoše: \"Budući da nisu išli s nama, ne dajmo im ništa od plijena koji smo izbavili, nego samo svakome njegovu ženu i njegovu djecu, neka ih povedu sa sobom i neka idu!\"');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 30, 23, 'Ali David reče: \"Ne činite tako, braćo moja, poslije onoga što nam je dao Jahve: on nas je čuvao i predao nam u ruke razbojničku družbu koja bijaše izišla protiv nas.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 30, 24, 'Ta tko će vas poslušati u tome? Jer kakav je dio onome koji ide u boj, takav je dio onome koji ostaje kod tovara. Jednak dio neka imaju svi.\"');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 30, 25, 'Tako ostade od onoga dana unapredak. David to učini uredbom i zakonom u Izraelu sve do današnjeg dana.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 30, 26, 'Kad je David došao u Siklag, posla dio plijena starješinama Jude, po pojedinim njihovim gradovima, s porukom: \"Evo za vas dar od plijena Jahvinih neprijatelja!\"');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 30, 27, 'Onima u Betulu, onima u Rami u Negebu i onima u Jatiru;');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 30, 28, 'onima u Aroeru, onima u Sifmotu i onima u Eštemoi;');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 30, 29, 'onima u Karmelu, onima u jerahmeelskim gradovima i onima u kenijskim gradovima;');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 30, 30, 'onima u Hormi, onima u Bor Ašanu i onima u Eteru;');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 30, 31, 'onima u Hebronu i u svim onima mjestima u koja je dolazio David sa svojim ljudima.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 31, 1, 'Filistejci su zavojštili na Izraelce, a Izraelci su pobjegli pred njima i padali pobijeni po gori Gilboi.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 31, 2, 'Filistejci stisnuše Šaula i njegove sinove i pogubiše Šaulove sinove Jonatana, Abinadaba i Malki-Šuu.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 31, 3, 'Boj je postao žešći oko Šaula. Iznenadiše ga strijelci s lukovima i on pade teško ranjen od strijelaca.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 31, 4, 'Šaul tada reče svome štitonoši: \"Izvuci svoj mač i probodi me da ne dođu ti neobrezanici i ne narugaju mi se.\" Ali se njegov štitonoša prestravi i ne htjede toga učiniti. Zato Šaul uze mač i baci se na nj.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 31, 5, 'Kad je štitonoša vidio da je Šaul umro, baci se i on na svoj mač i umrije s njim.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 31, 6, 'Tako onoga dana pogiboše zajedno Šaul, njegova tri sina, njegov štitonoša i svi njegovi ljudi.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 31, 7, 'Kad Izraelci koji bijahu na drugoj strani doline i na drugoj strani Jordana vidješe da su sinovi Izraelovi pobjegli i da je poginuo Šaul sa sinovima, ostaviše svoje gradove te se razbježaše. Filistejci dođoše i nastaniše se u njima.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 31, 8, 'Kad su sutradan došli Filistejci da oplijene pobijeđene, nađoše Šaula i njegova tri sina gdje leže na gori Gilboi.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 31, 9, 'Oni mu odsjekoše glavu i skidoše s njega oružje, koje poslaše po svoj filistejskoj zemlji naokolo, javljajući veselu vijest svojim idolima i narodu.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 31, 10, 'Potom oružje metnuše u Aštartin hram, a Šaulovo mrtvo tijelo pribiše na zid grada Bet Šana.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 31, 11, 'Ali kad oni u Jabešu Gileadskom čuše što su Filistejci učinili od Šaula,');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 31, 12, 'ustadoše svi hrabri ljudi i, pošto su hodili svu noć, uzeše Šaulovo mrtvo tijelo i tjelesa njegovih sinova sa zida grada Bet Šana pa ih donesoše u Jabeš i ondje spališe.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 31, 13, 'Potom uzeše njihove kosti i ukopaše ih pod tamarisom u Jabešu i postiše sedam dana.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 1, 1, 'Poslije Šaulove smrti David se vratio kući pobijedivši Amalečane. Dva je dana proveo u Siklagu.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 1, 2, 'Trećega dana dođe neki čovjek iz Šaulova tabora, razdrtih haljina i prahom posute glave. Došavši k Davidu, baci se na zemlju i pokloni mu se.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 1, 3, 'David ga upita: \"Odakle dolaziš?\" A on mu odgovori: \"Umakao sam iz izraelskog tabora.\"');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 1, 4, 'A David ga upita: \"Što se dogodilo? Pripovijedaj mi!\" On odvrati: \"Narod je pobjegao iz boja, a mnogo je ljudi i poginulo. Mrtvi su i Šaul i njegov sin Jonatan.\"');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 1, 5, 'Nato David upita mladoga glasonošu: \"Kako znaš da je poginuo Šaul i njegov sin Jonatan?\"');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 1, 6, 'A mladi glasonoša odgovori: \"Slučajno sam došao na goru Gilbou i vidio Šaula kako se upro u svoje koplje, a bojna kola i konjanici natisnuli se za njim.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 1, 7, 'Šaul, obazrevši se, ugleda mene pa me zovnu, a ja mu se odazvah: \'Evo me!\'');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 1, 8, 'I upita me on: \'Tko si ti?\' A ja mu odgovorih: \'Amalečanin sam.\'');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 1, 9, 'Tada mi on reče: \'Dođi ovamo k meni pa me ubij, jer me obuzeo smrtni grč, a duša je još sva u meni!\'');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 1, 10, 'Pristupih k njemu i zadadoh mu smrtni udarac, jer sam znao da neće preživjeti nakon pada. Zatim uzeh kraljevski znak koji mu bijaše na glavi i narukvicu koju imaše na ruci i, evo, donesoh to svome gospodaru.\"');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 1, 11, 'Tada David zgrabi svoje haljine i razdrije ih, a tako i svi ljudi koji bijahu s njim.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 1, 12, 'I naricali su, plakali i postili do večera za Šaulom i za njegovim sinom Jonatanom, za Jahvinim narodom i za domom Izraelovim što izginuše od mača.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 1, 13, 'Potom David upita mladoga glasonošu: \"Odakle si ti?\" A on odgovori: \"Ja sam sin jednoga došljaka, Amalečanina.\"');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 1, 14, 'Tada mu reče David: \"Kako se nisi bojao dići ruku da ubiješ pomazanika Jahvina?\"');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 1, 15, 'I dozva David jednoga od momaka i zapovjedi mu: \"Dođi ovamo i smakni ga!\" Udari ga momak i on umrije.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 1, 16, 'A David mu još doviknu: \"Tvoja krv na tvoju glavu! Tvoja su usta posvjedočila protiv tebe kad si rekao: \'Ja sam ubio pomazanika Jahvina.\'\"');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 1, 17, 'Tada David zapjeva ovu tužaljku za Šaulom i za njegovim sinom Jonatanom.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 1, 18, 'Zapisana je u Knjizi Pravednikovoj da je uče sinovi Judini. David reče:');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 1, 19, '\"Oh, kako ti slava pade, Izraele, izginuše div-junaci na tvom visu!');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 1, 20, 'O porazu vi u Gatu ne pričajte, aškelonskim ulicama ne glasite, da se kćeri ne vesele filistejske, mlade žene da ne kliču nevjerničke.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 1, 21, 'O Gilbojske gore klete, rosa na vas ne padala nit vas kiša s neba prala! Vaša polja ne vraćala rod za sjeme, jer kod vas je osramoćen štit junaka! Štit Šaulov nije bio uljem mazan,');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 1, 22, 'nego krvlju ranjenika, mašću palih! Luk Jonate nikad nije promašio, mač Šaulov nikad bezuspješan bio!');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 1, 23, 'Šaul i Jonata, ljupki, ponositi, ni živi se ne rastaše, ni u smrti! Od orlova bjehu brži, od lavova snagom jači!');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 1, 24, 'Za Šaulom sad plačite, Izraelke, jer je u kras i u grimiz vas odijevo! Uz to zlatan nakit on je na ruho vam pričvršćivo.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 1, 25, 'Usred boja poginuše div-junaci! Smrt me tvoja, Jonatane, ožalosti!');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 1, 26, 'Žao mi je tebe, brate, Jonatane! Kako li mi drag bijaše ti veoma! Ljubav tvoja bješe meni još od ženske čudesnija.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 1, 27, 'Oh, kako su izginuli div-junaci, i oružje bojno kako skršeno je!\"');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 2, 1, 'Poslije toga David upita Jahvu ovako: \"Treba li da pođem u koji Judin grad?\" A Jahve mu odgovori: \"Pođi!\" David opet upita: \"Kamo da pođem?\" A odgovor bješe: \"U Hebron!\"');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 2, 2, 'Tako David ode onamo, a s njim i njegove dvije žene, Ahinoama iz Jizreela i Abigajila, Nabalova žena iz Karmela.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 2, 3, 'I ljudi koji bijahu s Davidom odoše s njim, svaki sa svojom obitelji, i nastaniše se u gradićima Hebrona.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 2, 4, 'Tada dođoše ljudi iz Jude i pomazaše ondje Davida za kralja nad domom Judinim. Tada javiše Davidu da su ljudi iz Jabeša u Gileadu pokopali Šaula.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 2, 5, 'Nato David posla glasnike k Jabešanima u Gileadu i poruči im: \"Budite blagoslovljeni od Jahve što ste izvršili to djelo ljubavi prema svome gospodaru Šaulu i što ste ga pokopali!');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 2, 6, 'Zato neka vam Jahve iskaže svoju ljubav i dobrotu, a i ja ću vam učiniti dobro zato što ste tako radili.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 2, 7, 'A sada se ohrabrite i budite junaci, jer je Šaul, vaš gospodar, poginuo, a mene je Judin dom pomazao za svoga kralja.\"');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 2, 8, 'Ali Abner, sin Nerov, vojvoda Šaulove vojske, bijaše uzeo Šaulova sina Išbaala i doveo ga prijeko u Mahanajim.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 2, 9, 'Ondje ga je postavio za kralja nad Gileadom, nad Ašeranima, nad Jizreelom, Efrajimom, Benjaminom i nad svim Izraelom.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 2, 10, 'Išbaalu, sinu Šaulovu, bijaše četrdeset godina kad je postao kraljem nad Izraelom, a kraljevao je dvije godine. Samo je Judin dom pristao uz Davida.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 2, 11, 'A David je kraljevao u Hebronu nad Judinim domom sedam godina i šest mjeseci.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 2, 12, 'Potom iziđe Abner, Nerov sin, s ljudima Šaulova sina Išbaala iz Mahanajima prema Gibeonu.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 2, 13, 'Ali i Joab, Sarvijin sin, iziđe s Davidovim ljudima iz Hebrona i srete se s njima kod Gibeonskog jezera. Tu se zaustaviše, ovi s jedne strane jezera, a oni s druge strane.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 2, 14, 'Tada Abner reče Joabu: \"Neka ustanu mladići i neka se bore pred nama!\" A Joab odgovori: \"Neka ustanu!\"');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 2, 15, 'I ustadoše, pa ih izbrojiše: dvanaest od Benjamina za Išbaala, Šaulova sina, i dvanaest od Davidovih ljudi.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 2, 16, 'I svaki dohvati svoga protivnika za glavu i zabode mu mač u bok, tako da su svi popadali zajedno. Zato se to mjesto prozvalo Polje bokova, a leži kod Gibeona.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 2, 17, 'Potom se zametnu onoga dana vrlo žestoka bitka i Davidove čete razbiše Abnera i Izraelce.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 2, 18, 'A bijahu ondje tri Sarvijina sina: Joab, Abišaj i Asahel; a Asahel bijaše brz u trku kao gazela u polju.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 2, 19, 'I jurnu Asahel u potjeru za Abnerom; u stopu je slijedio Abnera ne skrećući ni desno ni lijevo.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 2, 20, 'Abner se obazre i upita: \"Jesi li to ti, Asahele?\" A on odgovori: \"Jesam.\"');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 2, 21, 'A Abner mu reče: \"Okreni se nadesno ili nalijevo pa zgrabi jednoga od tih mladića i uzmi njegovu odoru!\" Ali Asahel nije htio da skrene od njega.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 2, 22, 'Abner opet reče Asahelu: \"Ukloni se od mene! Zašto da te sastavim sa zemljom? Kako bih onda još smio doći na oči tvome bratu Joabu?\"');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 2, 23, 'Ali on nikako nije htio da se ukloni. Zato ga Abner udari stražnjim krajem koplja u trbuh tako da mu je koplje izašlo kroz leđa van: on ondje pade i umrije na mjestu. I ustavljao se tko god je došao na ono mjesto gdje je pao i umro Asahel.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 2, 24, 'Ali Joab i Abišaj nastaviše da gone Abnera, a kad je sunce zašlo, stigoše do brežuljka Ame, koji leži istočno od doline, na putu prema Gebi.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 2, 25, 'Dotle se Benjaminovi sinovi skupiše za Abnerom, sastaviše četu i stadoše na vrh brežuljka Ame.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 2, 26, 'Tada Abner viknu Joabu: \"Zar će nas dovijeka proždirati mač? Ne znaš li da će to svršiti nesrećom? Kad ćeš napokon kazati svojim ljudima da se okane gonjenja svoje braće?\"');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 2, 27, 'A Joab odvrati: \"Tako mi živog Jahve, da ti nisi progovorio, tek bi se sutra ujutro ovi ljudi okanili gonjenja svoje braće.\"');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 2, 28, 'Nato Joab zatrubi u rog i sva vojska stade: prestadoše goniti Izraela i ne nastaviše boja.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 2, 29, 'Abner i njegovi ljudi išli su kroz Arabu cijelu onu noć; onda prijeđoše preko Jordana, nastaviše put cijelo jutro i stigoše napokon u Mahanajim.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 2, 30, 'Kad je Joab odustao od potjere za Abnerom i skupio svu vojsku, vidješe da između Davidovih ljudi nema devetnaestorice, i uz to Asahela.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 2, 31, 'A Davidovi su ljudi od Benjaminovih sinova, Abnerovih vojnika, pobili tri stotine i šezdeset ljudi.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 2, 32, 'Asahela ponesoše i pokopaše u grobu njegova oca u Betlehemu. A Joab i njegovi ljudi išli su svu noć i već se bijaše zadanilo kad stigoše u Hebron.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 3, 1, 'Rat između Šaulove kuće i Davidove kuće potrajao je još dugo vremena, ali je David sve više jačao, a Šaulova kuća postajala sve slabija.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 3, 2, 'Davidu se rodiše sinovi u Hebronu. Prvenac mu je bio Amnon, od Ahinoame Jizreelke;');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 3, 3, 'drugi mu je bio Kileab, od Abigajile, žene Nabalove iz Karmela; treći Abšalom, sin Maake, kćeri gešurskoga kralja Tolmaja;');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 3, 4, 'četvrti Adonija, sin Hagitin; peti Šefatja, sim Abitalin;');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 3, 5, 'šesti Jitream, od Egle, Davidove žene. Ti se Davidu rodiše u Hebronu.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 3, 6, 'Dok je trajao rat između Šaulove kuće i Davidove kuće, Abner je malo-pomalo prisvajao svu vlast u Šaulovoj kući.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 3, 7, 'A u kući bijaše Šaulova inoča po imenu Rispa, kći Ajina: nju Abner uze sebi. A Išbaal upita Abnera: \"Zašto si se približio inoči moga oca?\"');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 3, 8, 'Na te Išbaalove riječi Abner se razgnjevi i reče: \"Zar sam ja pasja glava u Judi? Do danas sam samo dobro činio domu tvoga oca Šaula, njegovoj braći i njegovim prijateljima; nisam dopustio da padneš u Davidove ruke, a ti me danas prekoravaš zbog obične žene!');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 3, 9, 'Neka Abneru Bog učini ovo zlo i neka mu doda drugo ako ne izvršim kako se Jahve zakleo Davidu:');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 3, 10, 'da će oduzeti kraljevstvo Šaulovoj kući i da će utvrditi Davidov prijesto nad Izraelom i nad Judom od Dana pa do Beer Šebe!\"');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 3, 11, 'Išbaal se ne usudi odgovoriti ni riječi Abneru jer ga se bojaše.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 3, 12, 'Nato Abner posla glasnike k Davidu i poruči mu: \"Čija je zemlja?\" Htio je reći: \"Učini savez sa mnom i moja će ti ruka pomoći da okupiš oko sebe svega Izraela.\"');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 3, 13, 'David odgovori Abneru: \"Dobro! Učinit ću savez s tobom! Ali samo jedno tražim od tebe: ne smiješ mi doći na oči ako ne dovedeš sa sobom Mikalu, Šaulovu kćer, kad dođeš da vidiš moje lice.\"');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 3, 14, 'Ujedno posla David glasnike i k Išbaalu, Šaulovu sinu, s porukom: \"Vrati mi moju ženu Mikalu, koju sam stekao stotinom filistejskih obrezaka.\"');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 3, 15, 'Išbaal posla po nju i uze je od njezina muža Paltiela, Lajiševa sina.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 3, 16, 'A njezin muž pođe s njom i pratio ju je plačući sve do Bahurima. Tada mu Abner reče: \"Hajde, vrati se sada kući!\" I on se vrati.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 3, 17, 'Abner je već bio razgovarao s Izraelovim starješinama i rekao im: \"Već odavna želite Davida za svoga kralja.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 3, 18, 'Učinite to sada, jer je Jahve rekao o Davidu ovo: \'Rukom svoga sluge Davida izbavit ću svoj narod Izraela iz ruke filistejske i iz ruku svih njegovih neprijatelja.\'\"');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 3, 19, 'Tako je Abner govorio i Benjaminovim sinovima, a onda je otišao u Hebron da javi Davidu sve što se svidjelo Izraelu i domu Benjaminovu.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 3, 20, 'Kad je Abner došao k Davidu u Hebron, i s njim dvadeset ljudi, David priredi gozbu Abneru i ljudima koji bijahu s njim.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 3, 21, 'Tada Abner reče Davidu: \"Hajdemo! Ja ću skupiti svega Izraela oko gospodara moga kralja: oni će sklopiti s tobom savez i ti ćeš kraljevati nad svim što budeš želio.\" David otpusti Abnera, koji ode u miru.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 3, 22, 'I gle, Davidovi se ljudi s Joabom upravo vraćali sa četovanja, noseći sa sobom bogat plijen, a Abner nije više bio kod Davida u Hebronu, jer ga David bijaše otpustio te je on otišao u miru.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 3, 23, 'Kad stiže Joab i sva vojska što je išla s njim, javiše Joabu da je Abner, Nerov sin, bio došao kralju i da ga je kralj otpustio da ode u miru.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 3, 24, 'Tada Joab dođe kralju i reče mu: \"Što si učinio? Abner je došao k tebi, zašto si ga otpustio da ode u miru?');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 3, 25, 'Zar ne znaš Abnera, Nerova sina? Došao je da te prevari, da dozna tvoje korake, da dozna sve što činiš!\"');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 3, 26, 'Potom izađe Joab od Davida i posla glasnike za Abnerom, koji ga vratiše, od studenca Sire, a David nije znao ništa o tome.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 3, 27, 'Kad se Abner vratio u Hebron, odvede ga Joab u stranu iza vrata, kao da želi s njim nesmetano govoriti, i ondje ga smrtno rani u slabine da se osveti za krv svoga brata Asahela.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 3, 28, 'Kad je David to poslije čuo, reče: \"Ja i moje kraljevstvo nevini smo pred Jahvom dovijeka za krv Abnera, sina Nerova.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 3, 29, 'Neka padne na Joabovu glavu i na sav njegov očinski dom! Nikad ne ponestalo u Joabovu domu ljudi bolesnih od gnojenja ili od gube, ljudi koji se laćaju vretena ili padaju od mača, ljudi koji nemaju kruha!\" -');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 3, 30, 'Joab i njegov brat Abišaj ubili su Abnera jer je on pogubio njihova brata Asahela u boju kod Gibeona. -');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 3, 31, 'Nato David reče Joabu i svoj vojsci koja je bila s njim: \"Razderite svoje haljine, obucite kostrijet i naričite za Abnerom!\" I kralj David pođe za nosilima.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 3, 32, 'Kad su ukopali Abnera u Hebronu, udari kralj u glasan plač na grobu Abnerovu, a plakao je i sav narod.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 3, 33, 'Tada kralj ispjeva ovu tužaljku za Abnerom: \"Zar morade umrijeti Abner kako umire luda?');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 3, 34, 'Ruke tvoje ne bijahu vezane, noge tvoje ne bijahu okovane. Pao si kao što se pada od zlikovaca!\" Tada sav narod još ljuće zaplaka za njim.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 3, 35, 'Nato pristupi sav narod nutkajući Davida da jede dok je još dana, ali se David zakle ovako: \"Neka mi Bog učini ovo zlo i neka mi doda drugo zlo ako okusim kruha ili što drugo prije zalaska sunca!\"');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 3, 36, 'Sav je narod to čuo, i bilo mu je po volji, kao što je narod i sve drugo odobravao što god je kralj činio.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 3, 37, 'Toga dana sav narod i sav Izrael spozna da kralj nije kriv u umorstvu Abnera, sina Nerova.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 3, 38, 'Nato kralj reče svojim dvoranima: \"Ne znate li da je danas pao knez i velik čovjek u Izraelu?');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 3, 39, 'Ali ja sam sada još slab, iako sam pomazani kralj, a ovi ljudi, Sarvijini sinovi, jači su od mene. Neka Jahve plati zločincu po njegovoj zloći!\"');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 4, 1, 'Kad je Šaulov sin Išbaal čuo da je poginuo Abner u Hebronu, klonuše mu ruke i sav se Izrael zaprepasti.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 4, 2, 'A Šaulov sin Išbaal imaše dvojicu vođa svojih četa; jedan se zvao Baana, a drugi Rekab; bili su sinovi Rimona Beeroćanina iz Benjaminova plemena, jer se Beerot pribraja k Benjaminu.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 4, 3, 'A Beeroćani bijahu pobjegli u Gitajim, gdje su ostali kao došljaci do današnjeg dana.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 4, 4, 'Šaulov sin Jonatan imao je sina hroma na obje noge. Njemu je bilo pet godina kad je iz Jizreela došao glas o Šaulovoj i Jonatanovoj pogibiji. Njegova ga dadilja uze i pobježe, ali u brzini bijega dijete pade i osta hromo. Ime mu bijaše Meribaal.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 4, 5, 'Sinovi Rimona Beeroćanina, Rekab i Baana, digoše se i dođoše za najveće dnevne vrućine Išbaalu do kuće, a on upravo spavaše podnevni počinak.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 4, 6, 'A vratarica, čisteći pšenicu, bijaše zadrijemala te je spavala. Rekab i njegov brat Baana prošuljaše se kraj nje.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 4, 7, 'Kad su ušli u kuću, on je ležao na postelji u svojoj spavaonici. Oni ga ubiše, odsjekoše mu glavu i uzeše je i cijelu su onu noć išli putem kroz Arabu.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 4, 8, 'Glavu Išbaalovu donesoše Davidu u Hebron i rekoše kralju: \"Evo glave Išbaala, sina Šaulova, tvoga neprijatelja koji ti je radio o glavi. Jahve je danas krvavo osvetio moga gospodara i kralja na Šaulu i njegovu rodu.\"');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 4, 9, 'Ali David odvrati Rekabu i njegovu bratu Baani, sinovima Rimona iz Beerota, i reče im: \"Tako mi živog Jahve koje me izbavio iz svake nevolje!');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 4, 10, 'Onaj koji mi je javio da je poginuo Šaul mislio je da mi javlja radosnu vijest, a ja sam ga uhvatio i pogubio u Siklagu da mu platim za njegovu dobru vijest!');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 4, 11, 'Što ću tek učiniti sa zlikovcima koji su ubili poštena čovjeka u njegovoj kući, na njegovoj postelji! Zar da ne tražim od vas račun za njegovu krv i da vas ne istrijebim sa zemlje?\"');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 4, 12, 'Nato David zapovjedi vojnicima te ih pogubiše. Potom im odsjekoše ruke i noge i objesiše ih kod jezera u Hebronu. Išbaalovu glavu uzeše i pokopaše u Abnerovu grobu u Hebronu.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 5, 1, 'Tada se sabraše sva izraelska plemena k Davidu u Hebron i rekoše: \"Evo, mi smo od tvoje kosti i od tvoga mesa.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 5, 2, 'Još prije, dok je još Šaul bio kralj nad nama, ti si upravljao svim pokretima Izraela, a Jahve ti je rekao: \'Ti ćeš pasti moj izraelski narod i ti ćeš biti knez nad Izraelom!\'\"');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 5, 3, 'Tako dođoše sve izraelske starješine kralju u Hebron, a kralj David sklopi s njima savez u Hebronu pred Jahvom; i pomazaše Davida za kralja nad Izraelom.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 5, 4, 'Trideset je godina bilo Davidu kad je postao kralj, a kraljevao je četrdeset godina.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 5, 5, 'U Hebronu je kraljevao nad Judom sedam godina i šest mjeseci, a u Jeruzalemu kraljevaše trideset i tri godine nad svim Izraelom i nad Judom.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 5, 6, 'David krene s ljudima na Jeruzalem protiv Jebusejaca, koji su živjeli u onoj zemlji. Ali oni poručiše Davidu: \"Nećeš ući ovamo! Slijepci će te i kljasti odbiti!\" (To je imalo značiti: David neće ući ovamo.)');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 5, 7, 'Ipak David osvoji Sionsku tvrđavu, to jest Davidov grad.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 5, 8, 'Onoga dana reče David: \"Tko god pobije Jebusejce i popne se kroz prorov...\" A kljaste i slijepe mrzi David iz sve duše. (Stoga se kaže: Slijepci i kljasti neka ne ulaze u Hram.)');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 5, 9, 'David se nastani u tvrđavi i prozva je Davidov grad. Tada David podiže zid unaokolo od Mila pa unutra.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 5, 10, 'David je postajao sve silniji, jer Jahve, Bog nad vojskama, bijaše s njim.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 5, 11, 'Tirski kralj Hiram posla k Davidu izaslanstvo i cedrova drveta, tesara i zidara, koji sagradiše dvor Davidu.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 5, 12, 'Tada David spozna da ga je Jahve potvrdio za kralja nad Izraelom i da je vrlo uzvisio njegovo kraljevstvo radi svojega izraelskog naroda.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 5, 13, 'Po dolasku iz Hebrona David uze još inoča i žena iz Jeruzalema; i rodi se Davidu još sinova i kćeri.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 5, 14, 'Evo imena djece koja mu se rodiše u Jeruzalemu: Šamua, Šobab, Natan, Salomon,');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 5, 15, 'Jibhar, Elišua, Nefeg, Jafija,');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 5, 16, 'Elišama, Beeljada i Elifelet.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 5, 17, 'Kad su Filistejci čuli da su Davida pomazali za kralja nad Izraelom, iziđoše svi da se dočepaju Davida. Čuvši to, David siđe u svoj zaklon.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 5, 18, 'Filistejci dođoše i raširiše se po Refaimskoj dolini.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 5, 19, 'Tada David upita Jahvu: \"Mogu li napasti Filistejce? Hoćeš li ih predati meni u ruke?\" Jahve odgovori Davidu: \"Napadni! Predat ću Filistejce tebi u ruke!\"');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 5, 20, 'Tada David dođe u Baal Perasim i ondje ih pobi. David reče: \"Jahve je preda mnom prodro među moje neprijatelje kao što voda prodire.\" Stoga se ono mjesto prozvalo Baal Perasim.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 5, 21, 'Ostavili su ondje svoje bogove; a David i njegovi ljudi odnesoše ih.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 5, 22, 'Filistejci opet dođoše i raširiše se po Refaimskoj dolini.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 5, 23, 'David opet upita Jahvu, a on mu odgovori: \"Ne idi pred njih, nego im zađi za leđa i navali na njih s protivne strane Bekaima.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 5, 24, 'Kad začuješ topot koraka po bekaimskim vrhovima, onda se požuri, jer će tada Jahve ići pred tobom da pobije filistejsku vojsku.\"');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 5, 25, 'David učini kako mu je zapovjedio Jahve i pobi Filistejce od Gibeona sve do ulaza u Gezer.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 6, 1, 'Jednoga dana David opet skupi svu izabranu momčad u Izraelu, trideset tisuća ljudi.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 6, 2, 'Zatim David i sva vojska što je bila s njim krenu na put i odoše u Baalu Judinu da odande donesu Kovčeg Božji, što nosi ime Jahve Sebaota koji stoluje nad kerubinima.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 6, 3, 'Kovčeg Božji metnuše na nova kola, iznijevši ga iz kuće Abinadabove, koja je stajala na brežuljku. Uza i Ahjo, Abinadabovi sinovi, pratili su kola.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 6, 4, 'Uza je stupao kraj Kovčega Božjeg, a Ahjo išao pred njim.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 6, 5, 'David i sav dom Izraelov igrahu pred Jahvom iz sve snage pjevajući uza zvuke citara, harfa, bubnjeva, udaraljki i cimbala.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 6, 6, 'Kad su došli do Nakonova gumna, posegnu Uza rukom za Kovčegom Božjim da ga pridrži jer ga volovi umalo ne prevrnuše.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 6, 7, 'Ali se Jahve razgnjevio na Uzu: Bog ga na mjestu udari za taj prijestup, tako da je umro ondje, kraj Kovčega Božjega.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 6, 8, 'Davidu bijaše žao što je Jahve onako udario Uzu, i on prozva ono mjesto Peres Uza, kako se zove i dan-danas.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 6, 9, 'Toga se dana David uplaši Jahve i reče u sebi: \"Kako bi mogao doći k meni Kovčeg Jahvin?\"');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 6, 10, 'Zato David ne htjede dovesti Kovčeg Jahvin k sebi, u Davidov grad, nego ga otpremi u kuću Obed-Edoma iz Gata.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 6, 11, 'I ostade Jahvin Kovčeg u kući Obed-Edomovoj u Gatu tri mjeseca i Jahve blagoslovi Obed-Edoma i svu njegovu obitelj.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 6, 12, 'Kad su kralju javili da je Jahve blagoslovio Obed-Edomovu obitelj i sav njegov posjed zbog Kovčega Božjeg, ode David i ponese Kovčeg Božji iz Obed-Edomove kuće gore u Davidov grad s velikim veseljem.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 6, 13, 'Tek što su nosioci Kovčega Božjeg pokročili šest koraka, David žrtvova vola i tovna ovna.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 6, 14, 'David je igrao iz sve snage pred Jahvom, a bio je ogrnut samo lanenim oplećkom.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 6, 15, 'Tako su David i sav Izraelov dom nosili gore Kovčeg Jahvin kličući i trubeći u rog.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 6, 16, 'A kad je Kovčeg Jahvin ulazio u Davidov grad, Šaulova je kći Mikala gledala kroz prozor i vidjela kralja Davida kako skače i vrti se pred Jahvom i prezre ga ona u svome srcu.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 6, 17, 'Tada unesoše Kovčeg Jahvin i postaviše ga usred šatora koji mu bijaše razapeo David. Onda David prinese pred Jahvom paljenice i pričesnice.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 6, 18, 'Pošto je prinio paljenice i pričesnice, David blagoslovi narod imenom Jahve Sebaota.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 6, 19, 'Potom razdijeli među sav narod, među sve mnoštvo Izraelovo, ljudima i ženama, svakome po jedan kruh, komad mesa i kolač od suhoga grožđa. Zatim se raziđe sav narod, svaki svojoj kući.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 6, 20, 'Kad se David vratio kući da blagoslovi svoju obitelj, Šaulova kći Mikala iziđe u susret Davidu i reče mu: \"Kako se časno danas ponio Izraelov kralj kad se otkrio pred očima sluškinja slugu svojih kao što se otkriva prost čovjek!\"');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 6, 21, 'Ali David odgovori Mikali: \"Pred Jahvom ja igram! Tako mi živoga Jahve, koji me izabrao mjesto tvog oca i mjesto svega njegova doma da me postavi za kneza nad Izraelom, narodom Jahvinim: pred Jahvom ću igrati!');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 6, 22, 'I još ću se dublje poniziti. Bit ću neznatan u tvojim očima, ali pred sluškinjama o kojima govoriš, pred njima ću biti u časti.\"');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 6, 23, 'A Mikala, Šaulova kći, ne imade poroda do dana svoje smrti.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 7, 1, 'Kad se David nastanio u svojem dvoru i kad mu je Jahve pribavio mir od svih njegovih neprijatelja unaokolo,');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 7, 2, 'reče kralj proroku Natanu: \"Pogledaj! Ja, evo, stojim u dvoru od cedrovine, a Kovčeg Božji stoji pod šatorom.\"');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 7, 3, 'A Natan odgovori kralju: \"Idi i čini sve što ti je na srcu jer je Jahve s tobom.\"');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 7, 4, 'Ali još iste noći dođe Natanu ova Jahvina riječ:');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 7, 5, '\"Idi i reci mome sluzi Davidu: Ovako govori Jahve: \'Zar ćeš mi ti sagraditi kuću da u njoj prebivam?');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 7, 6, 'Nisam nikad prebivao u kući otkako sam izveo iz Egipta sinove Izraelove pa do današnjega dana, nego sam bio lutalac pod šatorom i u prebivalištu.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 7, 7, 'Dok sam hodio sa svim Izraelovim sinovima, jesam li ijednu riječ rekao nekomu od Izraelovih sudaca kojima sam zapovjedio da budu pastiri mojem narodu izraelskom i kazao: \'Zašto mi ne sagradite kuću od cedrovine?\'');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 7, 8, 'Zato sad ovo reci mome sluzi Davidu: Ovako govori Jahve nad vojskama: Ja sam te doveo s pašnjaka, od ovaca i koza, da budeš knez nad mojim izraelskim narodom.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 7, 9, 'Bio sam s tobom kuda si god išao, iskorijenio sam sve tvoje neprijatelje pred tobom. Ja ću ti pribaviti veliko ime, kao što je velikaško ime na zemlji.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 7, 10, 'Odredit ću prebivalište svojem izraelskom narodu, posadit ću ga da živi na svojem mjestu i da ne luta više naokolo, niti da ga zlikovci muče kao prije,');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 7, 11, 'onda kad sam odredio suce nad svojim izraelskim narodom. Ja ću mu pribaviti mir od svih njegovih neprijatelja. Jahve će te učiniti velikim. Jahve će ti podići dom.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 7, 12, 'I kad se ispune tvoji dani i ti počineš kod svojih otaca, podići ću tvoga potomka nakon tebe, koji će se roditi od tvoga tijela, i utvrdit ću njegovo kraljevstvo.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 7, 13, 'On će sagraditi dom imenu mojem, a ja ću utvrditi njegovo prijestolje zauvijek.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 7, 14, 'Ja ću njemu biti otac, a on će meni biti sin: ako učini što zlo, kaznit ću ga ljudskom šibom i udarcima kako ih zadaju sinovi ljudski.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 7, 15, 'Ali svoje naklonosti neću odvratiti od njega, kao što sam je odvratio od Šaula koga sam uklonio ispred tebe.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 7, 16, 'Tvoja će kuća i tvoje kraljevstvo trajati dovijeka preda mnom, tvoje će prijestolje čvrsto stajati zasvagda.\'\"');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 7, 17, 'Natan prenese Davidu sve te riječi i cijelo viđenje.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 7, 18, 'Nato kralj David uđe u šator i stade pred Jahvom i pomoli se: \"Tko sam ja, Gospode Jahve, i što je moj dom te si me doveo dovde?');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 7, 19, 'Pa i to je još premalo u tvojim očima, Gospode Jahve, te daješ svoja obećanja kući svoga sluge za daleku budućnost i gledaš na me kao na ugledna čovjeka!');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 7, 20, 'Ali što bi ti David još mogao kazati, kad ti sam poznaješ svoga slugu, Gospode Jahve!');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 7, 21, 'Radi svoje riječi i po svome srcu učinio si sve ovo veliko djelo, obznanivši ove veličajnosti.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 7, 22, 'Zato si velik, Gospode Jahve; nema takvoga kakav si ti i nema Boga osim tebe, po svemu što smo ušima svojim čuli.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 7, 23, 'Postoji li ijedan narod na zemlji kao tvoj izraelski narod radi kojega je Bog išao da ga izbavi sebi za narod da tako stečeš sebi ime velikim i strašnim čudesima, izgoneći krivobožačka plemena pred svojim narodom koji si otkupio iz Egipta?');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 7, 24, 'Tako si učinio svoj izraelski narod svojim narodom zauvijek, a ti si mu, Jahve, postao Bogom.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 7, 25, 'Zato sada, Gospode Jahve, ispuni zauvijek obećanje koje si dao svome sluzi i njegovu domu i učini kako si obrekao.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 7, 26, 'Neka se veliča tvoje ime zauvijek i neka se govori: Jahve nad vojskama jest Bog Izraelov, a dom sluge tvoga Davida neka stoji čvrsto pred tobom.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 7, 27, 'Jer si ti, Jahve nad vojskama, Bože Izraelov, objavio svome sluzi ovo: \'Ja ću ti podići dom.\' Zato je tvoj sluga smogao hrabrosti da ti se pomoli ovom molitvom.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 7, 28, 'Uistinu, Gospode Jahve, ti si Bog, tvoje su riječi istinite i ti daješ ovo lijepo obećanje svome sluzi.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 7, 29, 'Udostoj se sada blagosloviti dom svoga sluge da ostane dovijeka pred tobom. Jer kad ti, Gospode Jahve, obrekneš i blagosloviš, kuća tvoga sluge bit će blagoslovljena zasvagda.\"');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 8, 1, 'Poslije toga David porazi Filistejce i pokori ih te ote Gat s njegovim selima iz filistejskih ruku.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 8, 2, 'Porazi i Moapce i izmjeri ih uzicom polegavši ih po zemlji: dvije uzice odmjeri onih koje treba pogubiti, a jednu punu uzicu onih koje treba ostaviti na životu. Tako Moapci postadoše Davidovi podanici koji su mu donosili danak.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 8, 3, 'David je porazio i Hadadezera, Rehobova sina, sopskoga kralja, kad je izišao da proširi svoju vlast do Rijeke.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 8, 4, 'David zarobi od njega tisuću i sedam stotina konjanika i dvadeset tisuća pješaka; ispresijecao je petne žile svim konjima od bojnih kola; ostavio ih je samo stotinu.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 8, 5, 'Damaščanski su Aramejci došli u pomoć Hadadezeru, sopskome kralju, ali je David pobio među Aramejcima dvadeset i dvije tisuće ljudi.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 8, 6, 'Postavio je namjesnike u Damaščanskom Aramu. Tako Aramejci postadoše Davidovi podanici i moradoše mu plaćati danak. Jahve je davao pobjedu Davidu kuda je god išao.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 8, 7, 'David zaplijeni zlatne štitove što ih imahu Hadadezerove sluge i donese ih u Jeruzalem.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 8, 8, 'Iz Tebaha i iz Berotaja, Hadadezerovih gradova, donese kralj David silni tuč.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 8, 9, 'Kad je čuo hamatski kralj Tou da je David porazio svu Hadadezerovu vojsku,');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 8, 10, 'poslao je svoga sina Hadorama kralju Davidu da ga pozdravi i da mu čestita što je vojevao protiv Hadadezera i porazio ga, jer je Hadadezer bio u ratu s Touom; Hadoram donese srebrnih, zlatnih i tučanih predmeta.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 8, 11, 'I njih kralj David posveti Jahvi sa srebrom i zlatom što ga bijaše uzeo od svih naroda koje je pokorio:');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 8, 12, 'od Aramaca, Moabaca, Amonaca, Filistejaca i od Amalečana te od plijena Hadadezera, Rehobova sina, kralja Sobe.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 8, 13, 'David steče novu slavu kad je na povratku porazio Edomce, u Slanoj dolini, osamnaest tisuća njih.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 8, 14, 'I postavi upravitelje u Edomu, i svi Edomci postadoše podanici Davidovi. I kuda je god David išao, Jahve mu davaše pobjedu.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 8, 15, 'David kraljevaše nad svim Izraelom, čineći pravo i pravicu svemu svome narodu.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 8, 16, 'Joab, sin Sarvijin, zapovijedaše vojskom, a Jošafat, sin Ahiludov, bijaše ljetopisac.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 8, 17, 'Sadok, sin Ahitubov, i Ebjatar, sin Ahimelekov, bijahu svećenici; Seraja bijaše državni pisar;');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 8, 18, 'Benaja, sin Jojadin, zapovijedaše Kerećanima i Pelećanima; Davidovi sinovi bijahu namjesnici.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 9, 1, 'Jednoga dana upita David: \"Ima li još koji preživjeli od Šaulove kuće da mu učinim milost zbog Jonatana?\"');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 9, 2, 'A bijaše u Šaulovoj kući sluga po imenu Siba: njega dozvaše pred Davida i kralj ga zapita: \"Jesi li ti Siba?\" A on odgovori: \"Jesam, tvoj sluga!\"');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 9, 3, 'A kralj nastavi: \"Zar nema više nikoga od Šaulove kuće da mu iskažem milost kao što je Božja milost?\" A Siba odgovori kralju: \"Ima još Jonatanov sin koji je hrom na obje noge.\"');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 9, 4, 'Kralj ga upita: \"Gdje je on?\" A Siba odgovori kralju: \"Eno ga u kući Makira, sina Amielova, u Lo Debaru.\"');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 9, 5, 'Tada kralj David posla po njega u kuću Makira, sina Amielova, iz Lo Debara.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 9, 6, 'Kad je Meribaal, sin Jonatana, sina Šaulova, došao k Davidu, pade ničice i pokloni se. A David reče: \"Meribaale!\" On odgovori: \"Evo tvoga sluge!\"');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 9, 7, 'A David mu reče: \"Ne boj se jer ti želim iskazati milost zbog tvoga oca Jonatana. Vratit ću ti sva polja tvoga djeda Šaula, a ti ćeš svagda jesti kruh za mojim stolom.\"');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 9, 8, 'Meribaal se pokloni i reče: \"Što je tvoj sluga te iskazuješ milost mrtvome psu kao što sam ja?\"');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 9, 9, 'Potom kralj dozva Sibu, Šaulova slugu, i reče mu: \"Sve što je pripadalo Šaulu i njegovoj kući, sve to dajem sinu tvoga gospodara.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 9, 10, 'Ti ćeš mu sa svojim sinovima i sa svojim slugama obrađivati zemlju, od nje ćeš skupljati žetvu da obitelj tvoga gospodara ima kruha; a Meribaal, sin tvoga gospodara, jest će svagda za mojim stolom.\" A Siba imaše petnaest sinova i dvadeset slugu.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 9, 11, 'Siba odgovori kralju: \"Tvoj će sluga učiniti sve što je moj gospodar i kralj zapovjedio svome sluzi.\" Meribaal je, dakle, jeo za Davidovim stolom kao jedan između kraljevih sinova.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 9, 12, 'Meribaal je imao maloga sina po imenu Mika. A svi koji su živjeli u Sibinoj kući bijahu u službi Meribaala.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 9, 13, 'A Meribaal je boravio u Jeruzalemu, jer je uvijek jeo za kraljevim stolom. Bio je hrom na obje noge.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 10, 1, 'Poslije toga umrije Nahaš, kralj Amonaca, a zakralji se njegov sin Hanun mjesto njega.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 10, 2, 'A David reče u sebi: \"Želio bih iskazati ljubav Nahaševu sinu Hanunu, kao što je njegov otac iskazao meni.\" Zato David posla svoje sluge da mu izraze sućut zbog njegova oca. Ali kad su Davidove sluge došle u zemlju Amonaca,');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 10, 3, 'rekoše knezovi Amonaca svome gospodaru Hanunu: \"Zar misliš da je David poslao ljude da ti izraze sućut zato što bi htio iskazati čast tvome ocu? Nije li možda zato David poslao svoje ljude k tebi da razvide grad da bi doznao njegovu obranu i potom ga oborio?\"');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 10, 4, 'Tada Hanun pograbi Davidove sluge, obrija im pola brade i skrati im haljine dopola, sve do zadnjice, i posla ih natrag.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 10, 5, 'Kad su to javili Davidu, posla on čovjeka pred njih, jer su ti ljudi bili teško osramoćeni, i poruči im: \"Ostanite u Jerihonu dok vam ne naraste brada, pa se onda vratite!\"');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 10, 6, 'Tada Amonci uvidješe da su se omrazili s Davidom; zato Amonci poslaše glasnike da za plaću unajme Aramejce iz Bet Rehoba i Aramejce iz Sobe, dvadeset tisuća pješaka, zatim kralja Maake, tisuću ljudi, i ljude iz Toba, dvanaest tisuća vojnika.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 10, 7, 'Kad je David to čuo, posla Joaba s vojskom i izabranim junacima.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 10, 8, 'Amonci iziđoše i svrstaše se u bojni red pred gradskim vratima, dok su Aramejci iz Sobe i iz Rehoba i ljudi iz Toba i iz Maake stajali zasebno na polju.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 10, 9, 'Vidjevši postavljene bojne redove prema sebi sprijeda i straga, probra Joab najvrsnije među Izraelcima i svrsta ih prema Aramejcima.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 10, 10, 'Ostalu vojsku predade bratu Abišaju da je svrsta prema Amoncima.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 10, 11, 'I reče mu: \"Ako Aramejci budu jači od mene, onda ti meni priskoči u pomoć; ako Amonci budu jači od tebe, ja ću tebi pohrliti u pomoć.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 10, 12, 'Budi hrabar i junački se držimo radi naroda i radi gradova svoga Boga; a Jahve neka učini što je dobro u njegovim očima.\"');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 10, 13, 'Tada se Joab i vojska koja je bila s njim počeše primicati da udare na Aramejce, ali oni pobjegoše pred njima.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 10, 14, 'Kad su Amonci vidjeli da su Aramejci pobjegli, umakoše i oni ispred Abišaja i povukoše se u grad. Tada Joab odustane od rata protiv Amonaca i vrati se u Jeruzalem.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 10, 15, 'Kad su Aramejci vidjeli gdje su ih Izraelci razbili, sabraše ponovo svoje čete.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 10, 16, 'Hadadezer posla glasnike i sabra Aramejce što su s one strane rijeke. Ovi dođoše u Helam pod vodstvom Šobaka, vojvode Hadadezerove vojske.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 10, 17, 'Pošto su to javili Davidu, on skupi sve Izraelce i, prešavši preko Jordana, dođe u Helam. Aramejci se svrstaše protiv Davida i zametnuše s njime boj.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 10, 18, 'Ali Aramejci udariše u bijeg ispred Izraelaca i David im pobi sedam stotina konja od bojnih kola i četrdeset tisuća pješaka; pogubi i njihova vojvodu Šobaka te je ondje umro.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 10, 19, 'A kad svi kraljevi, Hadadezerovi vazali, vidješe da ih je razbio Izrael, sklopiše mir s Izraelom i počeše mu služiti. A Aramejci se više nisu usuđivali pomagati Amoncima.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 11, 1, 'U početku slijedeće godine, u doba kad kraljevi izlaze u rat, posla David Joaba i s njim svoje ljude i svega Izraela: oni pobiše Amonce i podsjedoše Rabu. A David osta u Jeruzalemu.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 11, 2, 'A jednoga dana predveče usta David sa svoje postelje i prošeta se po krovu svoje palače. Opazi s krova ženu gdje se kupa. Ta žena bijaše izvanredno lijepa.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 11, 3, 'David se propita za tu ženu i rekoše mu: \"Pa to je Bat-Šeba, kći Eliamova i žena Urije Hetita!\"');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 11, 4, 'Nato David posla glasnika da je dovedu k njemu. Kad je došla, leže on s njom, upravo kad se bila očistila od svoje nečistoće. Zatim se ona vrati svojoj kući.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 11, 5, 'Žena zatrudnje te poruči Davidu: \"Trudna sam!\"');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 11, 6, 'Tada David posla poruku Joabu: \"Pošalji k meni Uriju Hetita!\" I Joab posla Uriju k Davidu.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 11, 7, 'Kad je Urija došao k njemu, zapita ga David kako je Joab, kako je vojska i kako napreduje rat.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 11, 8, 'Potom David reče Uriji: \"Siđi u svoju kuću i operi svoje noge!\" Urija iziđe iz kraljeva dvora, a za njim ponesoše dar s kraljeva stola.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 11, 9, 'Ali Urija osta da spava pred vratima kraljeva dvora sa stražarima svoga gospodara i ne ode svojoj kući.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 11, 10, 'Javiše to Davidu govoreći: \"Urija nije otišao svojoj kući!\" Tada David upita Uriju: \"Zar nisi došao s puta? Zašto ne ideš svojoj kući?\"');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 11, 11, 'A Urija odgovori Davidu: \"Kovčeg, Izrael i Juda borave pod šatorima, moj gospodar Joab i straža moga gospodara borave na otvorenu polju, a ja da uđem u svoju kuću da jedem i da pijem i da spavam sa svojom ženom? Živoga mi Jahve, i tako mi tvoga života, zaista neću učiniti nešto takvo!\"');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 11, 12, 'Tada David reče Uriji: \"Ostani još danas ovdje, a sutra ću te otpustiti.\" Tako Urija osta u Jeruzalemu onaj dan.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 11, 13, 'Sutradan David pozva Uriju da jede i da pije pred njim i on ga opi. A uvečer Urija iziđe i leže na svoju postelju sa stražama svoga gospodara, ali svojoj kući nije otišao.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 11, 14, 'Ujutro David napisa pismo Joabu i posla ga po Uriji.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 11, 15, 'A u tom pismu pisao je ovako: \"Postavite Uriju naprijed, gdje je najžešći boj, pa uzmaknite iza njega: neka bude pogođen i neka pogine!\"');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 11, 16, 'Zato Joab, opsjedajući grad, postavi Uriju na mjesto gdje je znao da stoje najhrabriji ratnici.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 11, 17, 'Kad su onda građani provalili van i pobili se s Joabom, pade nekoliko od njegove vojske, od Davidovih ljudi, a pogibe i Urija Hetit.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 11, 18, 'Potom Joab posla čovjeka i javi Davidu sve što se dogodilo u boju.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 11, 19, 'I zapovjedi glasniku ovako: \"Kad pripovjediš kralju sve što se dogodilo u boju,');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 11, 20, 'možda će se kralj razljutiti pa ti kazati: \'Zašto ste se primakli tako blizu gradu da navalite? Zar niste znali da se obično izmeću strijele sa zida?');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 11, 21, 'Tko je ubio Abimeleka, sina Jerubaalova? Nije li jedna žena bacila na njega mlinski kamen, ozgo sa zida, te je poginuo u Tebesu? Zašto ste se primakli tako blizu zidu?\' Ako ti tako kaže, a ti mu reci: \'Poginuo je i tvoj sluga Urija Hetit.\'\"');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 11, 22, 'Glasnik krenu na put, dođe k Davidu i pripovjedi mu sve što mu je naložio Joab. A David planu gnjevom na Joaba i reče glasniku: \"Zašto ste se primakli tako blizu zidu? Tko je ubio Abimeleka, sina Jerubaalova? Nije li jedna žena bacila na njega mlinski kamen, ozgo sa zida, te je poginuo u Tebesu? Zašto ste se primakli tako blizu zidu?\"');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 11, 23, 'Glasnik odgovori Davidu: \"Ti su ljudi silovito udarali na nas i izašli su protiv nas na otvoreno polje. Mi smo ih potisnuli natrag do gradskih vrata,');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 11, 24, 'ali su strijelci sa zida stali izmetati strijele na tvoje ljude te ih je poginulo nekoliko između kraljevih slugu; tako je poginuo i tvoj sluga Urija Hetit.\"');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 11, 25, 'Tada David reče glasniku: \"Ovako reci Joabu: \'Nemoj to uzimati toliko k srcu, jer mač proždire sad ovoga, sad onoga. Udaraj još jače na grad i obori ga!\' Tako ćeš mu vratiti srčanost!\"');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 11, 26, 'Kad je Urijina žena čula da je poginuo njezin muž Urija, žalila je za svojim mužem.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 11, 27, 'A kad je prošlo vrijeme žalosti, posla David po nju i uze je u svoj dvor, i ona mu posta ženom. I rodi mu sina. Ali djelo koje učini David bijaše zlo u očima Jahvinim.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 12, 1, 'Jahve posla proroka Natana k Davidu. On uđe k njemu i reče mu: \"U nekom gradu živjela dva čovjeka, jedan bogat, a drugi siromašan.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 12, 2, 'Bogati imaše ovaca i goveda u obilju.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 12, 3, 'A siromah nemaše ništa, osim jedne jedine ovčice koju bijaše kupio. Hranio ju je i ona je rasla kraj njega i s njegovom djecom; jela je od njegova zalogaja, pila iz njegove čaše; spavala ja na njegovu krilu: bila mu je kao kći.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 12, 4, 'I dođe putnik k bogatom čovjeku, a njemu bilo žao uzeti od svojih ovaca ili goveda da zgotovi gostu koji mu je došao. On ukrade ovčicu siromaha i zgotovi je za svog pohodnika.\"');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 12, 5, 'Tada David planu žestokim gnjevom na toga čovjeka i reče Natanu: \"Tako mi živog Jahve, smrt je zaslužio čovjek koji je to učinio!');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 12, 6, 'Četverostruko će naknaditi ovcu zato što je učinio to djelo i što nije znao milosrđa!\"');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 12, 7, 'Tada Natan reče Davidu: \"Ti si taj čovjek! Ovako govori Jahve, Bog Izraelov: \'Ja sam te pomazao za kralja nad Izraelom, ja sam te izbavio iz Šaulove ruke.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 12, 8, 'Predao sam ti kuću tvoga gospodara, položio sam žene tvoga gospodara na tvoje krilo, dao sam ti dom Izraelov i dom Judin; a ako to nije dosta, dodat ću ti još ovo ili ono.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 12, 9, 'Zašto si prezreo Jahvu i učinio ono što je zlo u njegovim očima? Ubio si mačem Uriju Hetita, a njegovu si ženu uzeo za svoju ženu. Jest, njega si ubio mačem Amonaca.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 12, 10, 'Zato se neće nikada više okrenuti mač od tvoga doma, jer si me prezreo i jer si uzeo ženu Urije Hetita da ti bude žena.\'');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 12, 11, 'Ovako govori Jahve: \'Evo ja ću podići na te zlo iz tvoga doma. Uzet ću tvoje žene ispred tvojih očiju i dat ću ih tvome bližnjemu, koji će spavati s tvojim ženama na vidiku ovome suncu.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 12, 12, 'Ti si doduše radio tajno, ali ja ću ovu prijetnju izvršiti pred svim Izraelom i pred ovim suncem!\'\"');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 12, 13, 'Tada David reče Natanu: \"Sagriješio sam protiv Jahve!\" A Natan odvrati Davidu: \"Jahve ti oprašta tvoj grijeh: nećeš umrijeti.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 12, 14, 'Ali jer si tim djelom prezreo Jahvu, neminovno će umrijeti dijete koje ti se rodilo!\"');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 12, 15, 'Potom Natan ode svojoj kući. A Jahve udari dijete koje je Urijina žena rodila Davidu i ono se teško razbolje.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 12, 16, 'David se molitvom obrati Bogu za dijete: postio je, vraćao se kući i ležao preko noći na goloj zemlji, pokriven vrećom.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 12, 17, 'A starješine njegova doma stajahu oko njega da ga podignu sa zemlje, ali on ne htjede i ne okusi s njima nikakva jela.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 12, 18, 'A sedmi dan umrije dijete. Davidovi dvorani ne usudiše se javiti mu da je dijete umrlo. Jer mišljahu: \"Dok je dijete bilo živo, govorili smo mu, a on nas nije htio slušati. A kako ćemo mu kazati da je dijete umrlo? Učinit će zlo!\"');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 12, 19, 'A David opazi da njegovi dvorani šapću među sobom i on shvati da je dijete umrlo. I upita David svoje dvorane: \"Je li dijete umrlo?\" A oni odgovoriše: \"Umrlo je.\"');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 12, 20, 'Tada David usta sa zemlje, okupa se, pomaza se i preobuče se u druge haljine. Zatim uđe u Dom Jahvin i pokloni se. Vrativši se potom svojoj kući, zatraži da mu dadu jela; i jeo je.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 12, 21, 'A njegovi dvorani upitaše ga: \"Što to radiš? Dok je dijete bilo živo, postio si i plakao; a sada, kad je dijete umrlo, ustaješ i jedeš!\"');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 12, 22, 'A on odgovori: \"Dok je dijete bilo živo, postio sam i plakao jer sam mislio: \'Tko zna? Jahve će se možda smilovati na me i dijete će ostati živo!\'');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 12, 23, 'A sada, kad je umrlo, čemu da postim? Mogu li ga vratiti? Ja ću otići k njemu, ali se ono neće vratiti k meni!\"');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 12, 24, 'Potom David utješi svoju ženu Bat-Šebu. Dođe k njoj i leže s njom. Ona zatrudnje i rodi sina komu nadjenu ime Salomon. Jahve ga zamilova');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 12, 25, 'i objavi to po proroku Natanu. Ovaj ga nazva imenom Jedidja, po riječi Jahvinoj.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 12, 26, 'Joab navali na Rabu sinova Amonovih i osvoji kraljevski grad.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 12, 27, 'Tada Joab posla glasnika k Davidu s porukom: \"Ja sam navalio na Rabu i osvojio grad uz vodu.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 12, 28, 'Sada ti saberi ostalu vojsku, opkoli grad i osvoji ga, da ne bih ja osvojio grada i dao mu svoje ime.\"');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 12, 29, 'I skupi David svu vojsku, krenu na Rabu, navali na grad i zauze ga.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 12, 30, 'Ondje skinu s Malkomove glave krunu, koja bijaše teška jedan zlatni talenat; u njoj je bio dragi kamen, koji posta ures na Davidovoj glavi. I vrlo bogat plijen odnese iz grada.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 12, 31, 'A narod koji bijaše u njemu izvede i stavi ga da radi kod pila, željeznim pijucima i željeznim sjekirama i upotrijebi ga za rad u ciglanama. I tako je isto činio svim gradovima sinova Amonovih. Potom se David sa svom vojskom vrati u Jeruzalem.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 13, 1, 'A potom se dogodi ovo: Davidov sin Abšalom imao je lijepu sestru po imenu Tamaru i u nju se zaljubio Davidov sin Amnon.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 13, 2, 'Amnon se toliko mučio da se gotovo razbolio radi svoje sestre Tamare: jer ona bijaše djevica, pa Amnon nije vidio mogućnosti da joj učini bilo što.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 13, 3, 'Ali imaše Amnon prijatelja po imenu Jonadaba, sina Davidova brata Šimeja; a Jonadab bijaše vrlo domišljat.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 13, 4, 'I upita on Amnona: \"Odakle to, kraljev sine, da si svako jutro mlitav? Ne bi li mi kazao?\" A Amnon mu odgovori: \"Zaljubljen sam u Tamaru, sestru svoga brata Abšaloma.\"');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 13, 5, 'A Jonadab mu reče: \"Lezi u postelju i pričini se bolestan, pa kad dođe tvoj otac da te pohodi, ti mu reci: \'Dopusti da dođe moja sestra Tamara da mi dade jesti; ako ona pred mojim očima zgotovi jelo da to vidim, onda ću iz njezine ruke jesti.\'\"');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 13, 6, 'Amnon, dakle, leže i pričini se bolestan. Kad je došao kralj da ga pohodi, reče Amnon kralju: \"Dopusti da dođe moja sestra Tamara da pred mojim očima zgotovi koji kolač i ja ću se okrijepiti iz njezine ruke.\"');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 13, 7, 'Tada David poruči Tamari u palaču: \"Idi u kuću svoga brata Amnona i priredi mu jelo!\"');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 13, 8, 'Tamara ode u kuću svoga brata Amnona. A on ležaše. Uze ona brašna, umijesi ga, načini kolače pred njegovim očima te ih ispeče.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 13, 9, 'Potom uze tavu i istrese je preda nj, ali Amnon ne htjede jesti nego reče: \"Otpremite sve odavde!\" I svi iziđoše od njega.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 13, 10, 'Tada Amnon reče Tamari: \"Donesi mi jelo u spavaonicu da se okrijepim iz tvoje ruke!\" I Tamara uze kolače koje bijaše zgotovila i donese ih svome bratu Amnonu u spavaonicu.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 13, 11, 'A kad mu je pružila da jede, on je uhvati rukom i reče joj: \"Dođi, sestro moja, lezi sa mnom!\"');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 13, 12, 'A ona mu reče: \"Nemoj, brate moj! Ne sramoti me jer se tako ne radi u Izraelu. Ne čini takve sramote!');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 13, 13, 'Kuda bih ja sa svojom sramotom? A i ti bi bio kao bestidnik u Izraelu! Nego govori s kraljem: on me neće uskratiti tebi!\"');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 13, 14, 'Ali je on ne htjede poslušati, nego je svlada i leže s njom.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 13, 15, 'Nato je odmah zamrzi silnom mržnjom te je mržnja kojom ju je zamrzio bila veća od ljubavi kojom ju je prije ljubio. I reče joj Amnon: \"Ustani! Odlazi!\"');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 13, 16, 'A ona mu odvrati: \"Ne, brate moj! Ako me sad otjeraš, bit će to veće zlo od onoga koje si mi učinio!\" Ali je on ne htjede slušati,');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 13, 17, 'nego dozva momka koji ga je služio i zapovjedi mu: \"Otjeraj ovu od mene, izbaci je i zaključaj vrata za njom!\"');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 13, 18, '(A ona je imala na sebi haljinu s dugim rukavima, jer su se nekoć u takve haljine oblačile kraljeve kćeri dok su bile djevojke.) Sluga je izvede van i zaključa vrata za njom.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 13, 19, 'Tada Tamara uze prašine i posu se njom po glavi, razdrije haljinu s dugim rukavima koju je imala na sebi, stavi ruku na glavu i ode vičući glasno dok je išla.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 13, 20, 'A njezin je brat Abšalom upita: \"Je li možda tvoj brat Amnon bio s tobom? Ali sada, sestro moja, šuti: brat ti je! Ne uzimaj to k srcu!\" Tako je Tamara ostala osamljena u kući svoga brata Abšaloma.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 13, 21, 'Kad je kralj David čuo sve što se dogodilo, vrlo se razgnjevi, ali ne htjede žalostiti svoga sina Amnona, koga je ljubio jer mu bijaše prvorođenac.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 13, 22, 'A Abšalom ne reče Amnonu ni riječi, ni zle ni dobre, jer je Abšalom zamrzio Amnona što mu osramoti sestru Tamaru.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 13, 23, 'A poslije dvije godine imao je Abšalom striženje ovaca u Baal Hasoru kod Efrajima; i Abšalom pozva svu kraljevu obitelj.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 13, 24, 'Abšalom dođe kralju i reče mu: \"Evo, tvoj sluga ima striženje ovaca, pa neka se kralj i njegovi dvorani udostoje doći svome sluzi.\"');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 13, 25, 'Ali kralj odgovori Abšalomu: \"Ne, sine, nećemo doći svi, da ti ne budemo na teret.\" Abšalom ustraja, ali kralj ne htjede ići, nego ga blagoslovi i otpusti.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 13, 26, 'Ali Abšalom nastavi: \"Ako ti nećeš, dopusti da bar moj brat Amnon pođe s nama.\" A kralj ga upita: \"Zašto da ide s tobom?\"');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 13, 27, 'Ali je Abšalom i dalje navaljivao te David naposljetku pusti s njim Amnona i sve kraljeve sinove. Abšalom priredi kraljevsku gozbu');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 13, 28, 'i zapovjedi svojim slugama ovako: \"Pazite! Kad se Amnonu razveseli srce od vina i ja vam viknem: \'Ubijte Amnona!\' tada ga pogubite! Ne bojte se, jer vam tako zapovijedam! Ohrabrite se i pokažite se junaci!\"');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 13, 29, 'I Abšalomove sluge učiniše s Amnonom kako im zapovjedi Abšalom. Tada skočiše svi kraljevi sinovi, pojahaše svaki svoju mazgu i pobjegoše.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 13, 30, 'Dok su oni još bili na putu, dođe ovakva vijest Davidu: \"Abšalom je pobio sve kraljeve sinove, nije ostao od njih ni jedan jedini.\"');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 13, 31, 'Kralj ustade, razdrije svoje haljine i baci se na zemlju; i svi njegovi dvorani koji stajahu oko njega razdriješe svoje haljine.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 13, 32, 'Ali Jonadab, sin Davidova brata Šimeja, progovori ovako: \"Neka ne govori moj gospodar da su pobili sve mladiće, kraljeve sinove, jer je poginuo samo Amnon: na Abšalomovu licu mogla se predviđati nesreća od onoga dana kad je Amnon osramotio njegovu sestru Tamaru.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 13, 33, 'Zato neka sada moj gospodar i kralj ne misli u srcu da su svi kraljevi sinovi poginuli. Poginuo je samo Amnon,');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 13, 34, 'a Abšalom je pobjegao.\" A momak koji bijaše na straži podiže oči i ugleda mnoštvo naroda gdje silazi cestom od Horonajima. Stražar dođe i javi kralju: \"Vidio sam ljude gdje silaze cestom od Horonajima po gorskom obronku.\"');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 13, 35, 'Tada Jonadab reče kralju: \"Evo stigoše kraljevi sinovi! Dogodilo se kako je rekao tvoj sluga.\"');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 13, 36, 'Tek što je to izrekao, a to kraljevi sinovi uđoše i zaplakaše u sav glas; a i kralj i svi njegovi dvorani plakahu.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 13, 37, 'Abšalom pak bijaše pobjegao i otišao k Talmaju, sinu Amihudovu, gešurskom kralju. A David tugovaše za svojim sinom bez prestanka.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 13, 38, 'A pošto je Abšalom pobjegao i otišao u Gešur, ostao je ondje tri godine.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 13, 39, 'Kralj David prestao se srditi na Abšaloma jer se utješio zbog smrti Amnonove.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 14, 1, 'A Joab, sin Sarvijin, opazi da se kraljevo srce okreće k Abšalomu.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 14, 2, 'Zato Joab pošalje u Tekou po jednu pametnu ženu i reče joj: \"Učini se kao da si u žalosti za mrtvim, obuci žalobne haljine, nemoj se mazati uljem, nego budi kao žena koja je već dugo vremena u žalosti za mrtvim.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 14, 3, 'Otići ćeš kralju i govorit ćeš mu ovako.\" I Joab je nauči što će govoriti.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 14, 4, 'Žena iz Tekoe ode kralju, pade ničice na zemlju i pokloni se, zatim reče: \"Pomozi, kralju!\"');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 14, 5, 'Kralj je upita: \"Što ti je?\" A ona odgovori: \"Ah, ja sam udovica. Muž mi je umro,');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 14, 6, 'a tvoja je službenica imala dva sina. Oni se posvadiše u polju, a nije bilo nikoga da ih razdvoji te je jedan od njih udario svoga brata i ubio ga.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 14, 7, 'I sad se podiže sav rod na tvoju službenicu i reče: \'Predaj nam toga što je ubio svoga brata: mi ćemo ga pogubiti za život njegova brata koga je ubio, a time ćemo zatrti i baštinika.\' Tako hoće da ugase žeravicu koja mi je ostala, da ne ostave mome mužu ni imena ni potomstva na zemlji.\"');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 14, 8, 'A kralj reče ženi: \"Idi svojoj kući, ja ću odrediti što treba za te.\"');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 14, 9, 'A žena iz Tekoe reče kralju: \"Gospodaru kralju! Neka na me i na moj očinski dom padne krivica; kralj i njegovo prijestolje nedužni su u tome!\"');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 14, 10, 'A kralj nastavi: \"Onoga koji ti se zaprijetio dovedi k meni! Taj te neće više dirnuti!\"');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 14, 11, 'A ona reče: \"Neka se kralj udostoji spomenuti ime Jahve, svoga Boga, da krvni osvetnik neće umnožiti zator i da neće pogubiti moga sina!\" A on obeća: \"Tako mi živog Jahve, nijedna vlas neće pasti s glave tvome sinu!\"');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 14, 12, 'A žena nastavi: \"Dopusti da tvoja službenica kaže jednu riječ svome gospodaru kralju.\" A on odvrati: \"Govori!\"');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 14, 13, 'A žena reče: \"Dakle, zašto je kralj - jer se izričući ovakvu presudu sam priznao krivim - donio protiv naroda Božjega odluku da ne pušta kući onoga koga je prognao?');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 14, 14, 'Mi smo svi osuđeni na smrt, slični smo vodi koja se prolije na zemlju i više se ne može skupiti, i Bog ne podiže mrtvaca: neka, dakle, kralj misli na to da prognanik ne ostane izagnan daleko od njega.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 14, 15, 'A razlog zašto sam došla da iznesem pred svoga gospodara kralja ovu stvar bio je taj što su me zaplašili ljudi, pa je mislila tvoja službenica: moram govoriti s kraljem, možda će kralj učiniti ono što mu njegova službenica kaže.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 14, 16, 'Jer će kralj poslušati svoju službenicu i izbaviti je iz ruku čovjeka koji hoće da me istrijebi zajedno s mojim sinom iz Božje baštine.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 14, 17, 'Zato je tvoja službenica pomislila: neka mi riječ moga gospodara i kralja bude na umirenje. Jer moj je gospodar i kralj kao Božji anđeo koji sluša dobro i zlo. Jahve, tvoj Bog, neka bude s tobom!\"');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 14, 18, 'Tada progovori kralj i reče ženi: \"Nemoj mi sada zatajiti ono što ću te pitati!\" A žena odgovori: \"Neka govori moj gospodar kralj!\"');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 14, 19, 'Tada kralj upita: \"Nisu li Joabovi prsti s tobom u svemu tome?\" A žena odgovori: \"Tako bio živ, gospodaru kralju, zaista se ne može ni desno ni lijevo od svega što je kazao moj gospodar i kralj! Jest, tvoj mi je sluga Joab zapovjedio, on je naučio tvoju službenicu sve ove riječi.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 14, 20, 'Tvoj je sluga Joab to učinio da bi svemu dao drugo lice, ali je moj gospodar mudar kao Božji anđeo, on zna sve što se zbiva na zemlji.\"');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 14, 21, 'Tada se kralj okrenu Joabu i reče mu: \"Dobro, učinit ću to. Idi i dovedi natrag mladića Abšaloma!\"');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 14, 22, 'A Joab pade licem na zemlju, pokloni se i zahvali kralju; zatim reče Joab: \"Danas vidi tvoj sluga da je našao milost u tvojim očima, gospodaru kralju, kad je kralj ispunio molbu svoga sluge.\"');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 14, 23, 'Potom se diže Joab, ode u Gešur i dovede Abšaloma natrag u Jeruzalem.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 14, 24, 'Ali kralj reče: \"Neka ide u svoju kuću, a meni neka ne dolazi na oči!\" I Abšalom se povuče u svoju kuću i ne dođe kralju na oči.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 14, 25, 'U svemu Izraelu ne bijaše čovjeka tako lijepa kao Abšalom komu bi se mogle izreći tolike pohvale: od pete do glave nije bilo na njemu mane.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 14, 26, 'A kad bi šišao kosu - a šišao ju je na koncu svake godine, jer mu je bila preteška pa ju je morao šišati - mjerio bi svoju kosu: bila bi teška dvije stotine šekela, po kraljevskoj mjeri.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 14, 27, 'Abšalomu se rodiše tri sina i jedna kći po imenu Tamara; bila je to vrlo lijepa žena.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 14, 28, 'Abšalom provede dvije godine u Jeruzalemu a da nije došao kralju na oči.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 14, 29, 'Tada Abšalom pozva Joaba k sebi da bi ga poslao kralju, ali Joab ne htjede doći k njemu; i posla drugi put po njega, ali on opet ne htjede doći.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 14, 30, 'Tada Abšalom zapovjedi slugama: \"Znate Joabovo polje koje je pokraj mojega i na kojem raste ječam: idite i zapalite ga!\" I Abšalomove sluge zapališe ono polje.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 14, 31, 'Tada se diže Joab, dođe k Abšalomu u kuću i upita ga: \"Zašto su tvoje sluge zapalile moje polje?\"');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 14, 32, 'A Abšalom odgovori Joabu: \"Ja sam poslao k tebi i poručio ti: \'Dođi ovamo, želio bih te poslati kralju s ovom porukom: Zašto sam se vratio iz Gešura?\' Bolje bi bilo za mene da sam još ondje. Zato sad hoću da dođem kralju na oči, pa ako ima na meni kakva krivica, neka me pogubi!\"');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 14, 33, 'Joab ode kralju i javi mu te riječi. Zatim kralj pozva Abšaloma. Dođe on pred kralja, pokloni mu se i pade ničice pred kralja. I kralj poljubi Abšaloma.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 15, 1, 'Poslije toga nabavi Abšalom sebi kola i konje i pedeset ljudi koji su trčali pred njim.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 15, 2, 'Abšalom je u rano jutro stajao kraj puta koji vodi do gradskih vrata; i tko god je imao kakvu parnicu te išao kralju na sud, Abšalom bi ga dozvao k sebi i pitao: \"Iz kojega si grada?\" A kad bi ovaj odgovorio: \"Tvoj je sluga iz toga i toga Izraelova plemena\",');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 15, 3, 'tada bi mu Abšalom rekao: \"Vidiš, tvoja je stvar dobra i pravedna, ali nećeš naći nikoga koji bi te saslušao kod kralja.\"');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 15, 4, 'Abšalom bi nastavljao: \"Ah, kad bi mene postavili za suca u zemlji! Svaki bi koji ima kakvu parnicu ili sud dolazio k meni i ja bih mu pribavio pravo!\"');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 15, 5, 'A kad bi mu se tko približio da mu se pokloni, on bi pružio ruku, privukao ga k sebi i poljubio.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 15, 6, 'Tako je činio Abšalom svim Izraelcima koji su dolazili na sud kralju. Time je Abšalom predobivao srca Izraelaca za sebe.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 15, 7, 'Kad su prošle četiri godine, Abšalom reče kralju: \"Dopusti da odem u Hebron i da izvršim zavjet kojim sam se zavjetovao Jahvi.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 15, 8, 'Jer kad bijah u Gešuru u Aramu, tvoj se sluga zavjetovao ovako: \'Ako me Jahve dovede natrag u Jeruzalem, iskazat ću čast Jahvi u Hebronu.\'\"');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 15, 9, 'A kralj mu odgovori: \"Idi u miru!\" I on krenu na put i ode u Hebron.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 15, 10, 'Abšalom razasla tajne glasnike po svim Izraelovim plemenima i poruči im: \"Kad čujete zvuk roga, tada recite: Abšalom je postao kralj u Hebronu.\"');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 15, 11, 'A ode s Abšalomom dvije stotine ljudi iz Jeruzalema; bijahu to uzvanici koji su bezazleno pošli ne znajući što se sprema.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 15, 12, 'Abšalom posla i po Gilonjanina Ahitofela, Davidova savjetnika, iz njegova grada Gilona, da pribiva prinošenju žrtava. Urota je bila jaka, a mnoštvo Abšalomovih pristaša sve je više raslo.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 15, 13, 'Tada stiže Davidu glasnik te mu javi: \"Srce Izraelaca priklonilo se Abšalomu.\"');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 15, 14, 'Tada David reče svim svojim dvoranima koji bijahu s njim u Jeruzalemu: \"Ustanite! Bježimo! Inače nećemo uteći od Abšaloma. Pohitite brzo, da on ne bude brži i ne stigne nas, da ne obori na nas zlo i ne pobije grada oštricom mača!\"');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 15, 15, 'A kraljevi dvorani odgovoriše kralju: \"Što god odluči naš gospodar kralj, evo tvojih slugu!\"');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 15, 16, 'I kralj iziđe pješice sa svim svojim dvorom; ipak ostavi kralj deset inoča da čuvaju palaču.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 15, 17, 'I kralj ode pješice sa svim narodom i zaustavi se kod posljednje kuće.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 15, 18, 'Svi njegovi dvorani stajahu uza nj. Tada svi Kerećani, svi Pelećani, Itaj i svi Gićani koji bijahu došli s njim iz Gata, šest stotina ljudi, prođoše pred kraljem.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 15, 19, 'Kralj upita Itaja Gićanina: \"Zašto i ti ideš s nama? Vrati se i ostani kod kralja! Ti si stranac, prognan iz svoje zemlje.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 15, 20, 'Jučer si došao, a danas da te vodim da se potucaš s nama kad ja idem kamo me sreća nanese. Vrati se i odvedi svoju braću natrag sa sobom, a Jahve neka ti iskaže ljubav i vjernost!\"');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 15, 21, 'Ali Itaj odgovori kralju ovako: \"Živoga mi Jahve i tako mi živ bio moj gospodar kralj: gdje god bude moj gospodar kralj, bilo na smrt ili na život, ondje će biti i tvoj sluga!\"');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 15, 22, 'Tada David reče Itaju: \"Hajde, prođi!\" I Itaj iz Gata prođe sa svim svojim ljudima i sa svom svojom pratnjom.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 15, 23, 'Svi plakahu iza glasa. Kralj je stajao na potoku Kidronu i sav je narod prolazio pred njim prema pustinji.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 15, 24, 'Bijaše ondje i Sadok i s njim svi leviti koji su nosili Kovčeg Božji. I oni spustiše Kovčeg Božji kraj Ebjatara dok sav narod nije izišao iz grada.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 15, 25, 'Tada kralj reče Sadoku: \"Odnesi Kovčeg Božji natrag u grad. Ako nađem milost u Jahve, on će me dovesti natrag i dopustiti mi da opet vidim njega i njegovo prebivalište.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 15, 26, 'A ako rekne ovako: \'Nisi mi po volji!\' - onda evo me, neka čini sa mnom što je dobro u njegovim očima!\"');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 15, 27, 'Još kralj reče svećeniku Sadoku: \"Hajde, ti i Ebjatar vratite se u miru u grad, i vaša dva sina s vama, tvoj sin Ahimaas i Ebjatarov sin Jonatan.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 15, 28, 'Evo, ja ću se zadržati na ravnicama pustinje dok ne dođe od vas glas da me obavijesti.\"');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 15, 29, 'Nato Sadok i Ebjatar odnesoše Kovčeg Božji natrag u Jeruzalem i ostadoše ondje.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 15, 30, 'David se uspinjao na Maslinsku goru, sve plačući, pokrivene glave i bos, i sav narod koji ga je pratio iđaše pokrivene glave i plačući.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 15, 31, 'Tada javiše Davidu da je i Ahitofel među urotnicima s Abšalomom. A David zavapi: \"Obezumi Ahitofelove savjete, Jahve!\"');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 15, 32, 'Kad je David došao na vrh gore, ondje gdje se klanja Bogu, dođe mu u susret Hušaj Arčanin, prijatelj Davidov, razdrte haljine i glave posute prahom.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 15, 33, 'David mu reče: \"Ako pođeš sa mnom, bit ćeš mi na teret.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 15, 34, 'Ali ako se vratiš u grad i kažeš Abšalomu: \'Bit ću tvoj sluga, gospodaru kralju; prije sam služio tvome ocu, a sada ću služiti tebi\', moći ćeš tada okretati Ahitofelove savjete u moju korist.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 15, 35, 'S tobom će biti i svećenici Sadok i Ebjatar. Sve što čuješ iz palače, javi svećenicima Sadoku i Ebjataru.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 15, 36, 'S njima su ondje i dva njihova sina, Ahimaas Sadokov i Jonatan Ebjatarov: po njima mi javljajte sve što čujete.\"');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 15, 37, 'Tako se Hušaj, prijatelj Davidov, vrati u grad upravo u času kad je Abšalom ulazio u Jeruzalem.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 16, 1, 'Kad je David prešao malo preko vrha, dođe mu u susret Siba, sluga Meribaalov, sa dva osamarena magarca koja su nosila dvije stotine kruhova, sto grozdova suhog grožđa, sto voćnjača i mijeh vina.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 16, 2, 'Kralj upita Sibu: \"Što ćeš s tim?\" A Siba odgovori: \"Magarci će poslužiti kraljevoj obitelji za jahanje, kruh i voće momcima za jelo, a vino za piće onima koji se umore u pustinji.\"');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 16, 3, 'Kralj dalje upita: \"A gdje je sin tvoga gospodara?\" A Siba odgovori kralju: \"Eno, ostao je u Jeruzalemu jer je mislio: \'Danas će mi dom Izraelov vratiti kraljevstvo moga oca.\'\"');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 16, 4, 'Tada kralj reče Sibi: \"Sve što posjeduje Meribaal neka je tvoje.\" A Siba odgovori: \"Bacam se ničice pred tobom. O, da bih i dalje bio dostojan milosti u tvojim očima, kralju gospodaru!\"');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 16, 5, 'Kad je kralj David došao do Bahurima, izađe odande čovjek od roda Šaulova. Zvao se Šimej, a bio je sin Gerin. Dok je izlazio, neprestano je proklinjao.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 16, 6, 'Bacao je kamenje na Davida i na sve dvorane kralja Davida, premda je sva vojska sa svim junacima okruživala kralja s desne i lijeve strane.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 16, 7, 'A Šimej je ovako govorio proklinjući: \"Odlazi, odlazi, krvniče, ništarijo!');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 16, 8, 'Jahve je okrenuo na tebe svu krv Šaulova doma, kojemu si ti oduzeo kraljevstvo. Ujedno je Jahve predao kraljevstvo u ruke tvome sinu Abšalomu. Evo, sad si zapao u nevolju jer si krvnik.\"');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 16, 9, 'Tada Sarvijin sin Abišaj zapita kralja: \"Zar da ovaj uginuli pas proklinje moga gospodara kralja? Dopusti da odem prijeko i da mu skinem glavu!\"');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 16, 10, 'Ali kralj odgovori: \"Što hoćete od mene, Sarvijini sinovi? Ako on proklinje te ako mu je Jahve zapovjedio: \'Proklinji Davida!\' - tko ga smije pitati: \'Zašto činiš tako?\'\"');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 16, 11, 'Nato David reče Abišaju i svim svojim dvoranima: \"Eto, moj sin koji je izašao od moga tijela radi mi o glavi, a kamoli neće sada ovaj Benjaminovac! Pustite ga neka proklinje ako mu je Jahve to zapovjedio.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 16, 12, 'Možda će Jahve pogledati na moju nevolju te mi vratiti dobro za njegovu današnju psovku.\"');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 16, 13, 'Zatim David sa svojim ljudima nastavi put, a Šimej iđaše gorskom stranom usporedo s njim, neprestano psujući, bacajući kamenje i dižući prašinu.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 16, 14, 'Kralj i sav narod koji ga je pratio stigoše umorni i ondje odahnuše.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 16, 15, 'Abšalom je međutim sa svim narodom izraelskim ušao u Jeruzalem; i Ahitofel bijaše s njim.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 16, 16, 'A kad je Hušaj Arčanin, Davidov prijatelj, došao k Abšalomu, reče Hušaj Abšalomu: \"Živio kralj! Živio kralj!\"');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 16, 17, 'A Abšalom upita Hušaja: \"Je li to tvoja vjernost prema tvome prijatelju? Zašto nisi otišao sa svojim prijateljem?\"');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 16, 18, 'A Hušaj odgovori Abšalomu: \"Ne, nego koga je izabrao Jahve i ovaj narod i svi Izraelci, njegov ću biti i s njim ću ostati.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 16, 19, 'A drugo: kome ću služiti? Zar ne njegovu sinu? Kako sam služio tvojemu ocu, tako ću služiti tebi.\"');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 16, 20, 'Potom se Abšalom obrati Ahitofelu: \"Savjetuj sada: što da činimo?\"');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 16, 21, 'Ahitofel odgovori Abšalomu: \"Uđi k inočama svoga oca, koje je ostavio da čuvaju palaču: tada će sav Izrael čuti da si u zavadi sa svojim ocem, pa će se ohrabriti svi oni koji su pristali uz tebe.\"');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 16, 22, 'Tada razapeše za Abšaloma šator na krovu i Abšalom uđe k inočama svoga oca na oči svemu Izraelu.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 16, 23, 'A savjet što bi ga dao Ahitofel u ono vrijeme vrijedio je kao odgovor Božji; toliko je vrijedio svaki Ahitofelov savjet i kod Davida i kod Abšaloma.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 17, 1, 'Nato Ahitofel reče Abšalomu: \"Dopusti da izaberem dvanaest tisuća ljudi pa da se dignem i pođem u potjeru za Davidom još noćas.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 17, 2, 'Navalit ću na njega kad bude umoran i bez snage; plašit ću ga i razbježat će se sav narod koji je s njim. Onda ću ubiti samoga kralja.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 17, 3, 'A sav ću narod dovesti natrag k tebi, kao što se mlada vraća svome mužu: ti radiš o glavi samo jednome čovjeku, a sav će narod onda biti miran.\"');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 17, 4, 'Svidje se to Abšalomu i svim starješinama Izraelovim.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 17, 5, 'Ali Abšalom reče: \"Pozovimo još Hušaja Arčanina da čujemo što će nam on kazati!\"');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 17, 6, 'Kad je Hušaj došao k Abšalomu, reče mu Abšalom: \"Ahitofel je svjetovao ovako. Hoćemo li učiniti kako je on predložio? Ako ne, govori ti!\"');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 17, 7, 'A Hušaj odgovori Abšalomu: \"Ovaj put savjet Ahitofelov nije dobar.\"');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 17, 8, 'I nastavi Hušaj: \"Ti znaš da su tvoj otac i njegovi ljudi junaci i da su ljuti kao medvjedica kojoj su oteli njezine medvjediće. Tvoj je otac ratnik, neće on dopustiti da narod počiva preko noći.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 17, 9, 'On se sada krije u kakvoj jami ili na kakvu drugom mjestu. Pa ako odmah u početku koji od naših padne, proširit će se glas o porazu u vojsci koja je pristala uz Abšaloma.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 17, 10, 'Tada će i najhrabriji, u koga je srce kao u lava, izgubiti srčanost. Jer sav Izrael zna da je tvoj otac junak i da su hrabri oni koji ga prate.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 17, 11, 'Zato ja svjetujem ovo: neka se sav Izrael, od Dana do Beer Šebe, okupi oko tebe, da ga bude kao pijeska na obali morskoj, a ti sam da stupaš u njihovoj sredini.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 17, 12, 'Tada ćemo navaliti na njega gdje se god bude nalazio, oborit ćemo se na nj kao što rosa pada na zemlju i nećemo ostaviti živa ni njega niti ikojega od njegovih ljudi.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 17, 13, 'Ako li se povuče u koji grad, sav će izraelski narod donijeti užeta pod onaj grad pa ćemo ga povlačiti do potoka, sve dok više ni kamenčića ne bude od njega.\"');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 17, 14, 'Tada Abšalom i svi Izraelci rekoše: \"Bolji je savjet Hušaja Arčanina nego savjet Ahitofelov.\" Jer Jahve bijaše odlučio da se osujeti izvrsna Ahitofelova osnova, kako bi navukao nesreću na Abšaloma.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 17, 15, 'Potom Hušaj javi svećenicima Sadoku i Ebjataru: \"Ahitofel je tako i tako savjetovao Abšaloma i starješine izraelske, a ja sam savjetovao tako i tako.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 17, 16, 'Zato sad brzo javite to Davidu i poručite mu: \'Nemoj noćas noćiti na ravnicama pustinje, nego brzo prijeđi na drugu stranu da ne bude uništen kralj i sva vojska koja je s njim.\'\"');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 17, 17, 'Jonatan i Ahimaas zadržavali se kod Rogelskog izvora; jedna je sluškinja dolazila i donosila im vijesti, a oni su odlazili da to jave kralju Davidu, jer se nisu smjeli odati ulazeći u grad.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 17, 18, 'Ali ih opazi neki momak te javi Abšalomu. Nato obojica žurno odoše i dođoše u kuću nekoga čovjeka u Bahurimu. U njegovu dvorištu bijaše studenac i oni se spustiše u nj.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 17, 19, 'A žena uze i razastrije pokrivač preko otvora studencu i posu po njem stučenoga zrnja, tako da se ništa nije moglo opaziti.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 17, 20, 'Abšalomove sluge dođoše k toj ženi u kuću i upitaše: \"Gdje su Ahimaas i Jonatan?\" A žena im odgovori: \"Otišli su dalje prema vodi.\" Potom su ih još tražili, ali ih ne nađoše pa se vratiše u Jeruzalem.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 17, 21, 'A kad su oni otišli, ona dvojica iziđoše iz studenca i odoše da donesu vijesti kralju Davidu. I rekoše mu: \"Ustajte i prijeđite brže preko vode, jer je tako i tako savjetovao protiv vas Ahitofel.\"');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 17, 22, 'Tada se David i sav narod što bijaše s njim diže i prijeđe preko Jordana; u zoru nije više bilo nijednoga koji nije prešao preko Jordana.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 17, 23, 'Kad je Ahitofel vidio da se nije izvršio njegov savjet, osamari svoga magarca, krenu na put i ode svojoj kući u svoj grad. Ondje se pobrinu za svoju kuću, zatim se objesi i umrije. Pokopaše ga u grobu njegova oca.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 17, 24, 'David je već bio došao u Mahanajim kad je Abšalom prešao preko Jordana sa svim Izraelcima koji bijahu s njim.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 17, 25, 'Abšalom bijaše postavio Amasu za zapovjednika nad vojskom namjesto Joaba. A Amasa je bio sin nekoga čovjeka po imenu Jitre, Jišmaelovca, koji je ušao k Abigajili, kćeri Jišajevoj i sestri Sarvije, Joabove majke.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 17, 26, 'Izrael i Abšalom udariše tabor u zemlji gileadskoj.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 17, 27, 'Kad je David došao u Mahanajim, tada Šobi, sin Nahašev iz Rabe Amonske, pa Makir, sin Amielov iz Lo Debara, i Barzilaj, Gileađanin iz Rogelima,');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 17, 28, 'donesoše postelja, pokrivača, čaša i zemljanog suđa, uz to pšenice, ječma, brašna, pržena žita, boba, leće,');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 17, 29, 'meda, kiseloga mlijeka i sira kravljeg i ovčjeg i ponudiše Davida i narod što bijaše s njim da jedu. Jer mišljahu: \"Ljudi su u pustinji trpjeli glad, umor i žeđu.\"');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 18, 1, 'Potom David pobroji narod što bijaše s njim i postavi nad njima tisućnike i stotnike.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 18, 2, 'Zatim podijeli vojsku na tri skupine: jednu trećinu predade Joabu, drugu trećinu Abišaju, sinu Sarvijinu, bratu Joabovu, a treću trećinu Itaju iz Gata. Tada David reče narodu: \"I ja ću s vama u rat.\"');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 18, 3, 'Ali se narod usprotivi: \"Ne smiješ ti ići. Jer ako mi i pobjegnemo, neće nitko na to obraćati pažnju, ili ako nas i pola izgine, neće se na to obraćati pažnja; ali ti sam vrijediš kao nas deset tisuća. Osim toga, bolje je da budeš pripravan da nam iz grada pomogneš.\"');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 18, 4, 'A kralj im odgovori: \"Učinit ću sve što vam se čini dobro.\" I kralj stade kod vrata dok je vojska izlazila po stotinama i tisućama.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 18, 5, 'A Joabu, Abišaju i Itaju dade zapovijed: \"Čuvajte mi mladića Abšaloma!\" I sav je narod čuo da je kralj tako zapovjedio svim vojvodama za Abšaloma.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 18, 6, 'Tako vojska iziđe za boj spremna pred Izraela i bitka se zametnu u Efrajimovoj šumi.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 18, 7, 'Izraelsku vojsku potukoše Davidovi ljudi; i velik poraz bijaše u onaj dan: dvadeset tisuća mrtvih.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 18, 8, 'Boj se proširio po svemu onom kraju i više je ljudi onoga dana progutala šuma nego mač.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 18, 9, 'Abšalom slučajno zapade u ruke Davidovim ljudima. Abšalom je jahao na mazgi, a mazga naiđe pod grane velika hrasta, tako te je Abšalomu glava zapela o grane i on osta viseći između neba i zemlje, dok je mazga ispod njega otišla dalje.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 18, 10, 'Vidje to neki čovjek i javi Joabu govoreći: \"Upravo sam vidio Abšaloma gdje visi o jednom hrastu.\"');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 18, 11, 'A Joab odvrati čovjeku koji mu je to javio: \"Kad si ga vidio, zašto ga na mjestu nisi sastavio sa zemljom? Moja bi onda bila dužnost da ti dam deset srebrnih šekela i jedan pojas!\"');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 18, 12, 'Ali čovjek odgovori Joabu: \"I kad bi mi na dlan izbrojio tisuću srebrnih šekela, ne bih digao ruku na kraljeva sina! Čuli smo na svoje uši kako je kralj zapovjedio tebi, Abišaju i Itaju govoreći: \'Čuvajte mi mladića Abšaloma!\'');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 18, 13, 'Da sam podmuklo napao na njega izlažući opasnosti svoj život - jer kralju ništa ne ostaje skriveno - onda bi se ti držao po strani.\"');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 18, 14, 'A Joab odvrati: \"Neću ja ovdje dangubiti s tobom!\" I uze tri sulice u ruke i zabode ih u srce Abšalomu, koji je bio još živ viseći o hrastu.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 18, 15, 'Nato priđe deset momaka, štitonoša Joabovih, i dotukoše Abšaloma i usmrtiše.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 18, 16, 'Tada Joab zapovjedi da zatrube u rog, i vojska prestade progoniti Izraela jer je Joab zaustavio vojsku.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 18, 17, 'Potom uzeše Abšaloma, baciše ga u duboku jamu usred šume i navaljaše na nj veliku gomilu kamenja. Izraelci pak pobjegoše svaki svome šatoru.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 18, 18, 'Abšalom bijaše još za života postavio sebi spomenik u Kraljevoj dolini jer mišljaše: \"Nemam sina koji bi sačuvao spomen mome imenu.\" I nazvao je taj spomenik po svome imenu te se još i danas zove \"Abšalomov spomenik\".');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 18, 19, 'Ahimaas, Sadokov sin, reče Joabu: \"Idem javiti kralju veselu vijest da mu je Jahve pribavio pravdu izbavivši ga iz ruku njegovih neprijatelja.\"');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 18, 20, 'Ali mu Joab reče: \"Ne možeš danas biti glasnik vesele vijesti, nego ćeš to biti koji drugi dan; danas ne možeš javiti dobru vijest jer je poginuo kraljev sin.\"');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 18, 21, 'Zatim Joab zapovjedi Etiopljaninu: \"Idi javi kralju što si vidio!\" Etiopljanin se pokloni Joabu i otrča.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 18, 22, 'A Sadokov sim Ahimaas opet zamoli Joaba: \"Dogodilo se što mu drago, dopusti da otrčim i ja za Etiopljaninom.\" A Joab upita: \"Zašto bi trčao, sine moj, kad ti ta vesela vijest neće pribaviti nagrade?\"');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 18, 23, 'A on ponovi: \"Dogodilo se što mu drago, trčat ću!\" A Joab mu odvrati: \"Trči!\" I Ahimaas otrča putem kroz ravnicu i preteče Etiopljanina.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 18, 24, 'David je upravo sjedio među dvojim gradskim vratima, a stražar se bio uspeo na krov iznad vrata. Podigavši oči, stražar ugleda čovjeka kako trči sam.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 18, 25, 'Stražar povika i javi kralju, a kralj mu reče: \"Ako je sam, nosi dobar glas na ustima.\" Čovjek je dolazio sve bliže.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 18, 26, 'Uto stražar ugleda drugoga čovjeka gdje trči. I povika stražar koji je bio nad vratima: \"Evo još jednoga čovjeka koji trči sam!\" A kralj odvrati: \"I taj nosi dobar glas.\"');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 18, 27, 'Stražar nastavi: \"Prepoznajem trk prvoga čovjeka: trči kao Sadokov sin Ahimaas.\" A kralj odvrati: \"To je dobar čovjek, dolazi s dobrim glasom.\"');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 18, 28, 'Ahimaas se približi kralju i pozdravi ga: \"Zdravo!\" Baci se licem na zemlju pred kraljem i nastavi: \"Blagoslovljen Jahve, tvoj Bog, koji je napustio ljude što su digli ruku na moga gospodara i kralja!\"');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 18, 29, 'A kralj upita: \"Je li spašen mladić Abšalom?\" A Ahimaas odgovori: \"Vidio sam veliku vrevu kad je kraljev sluga Joab slao tvoga slugu, ali ne znam što je bilo.\"');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 18, 30, 'Kralj mu reče: \"Odstupi i stani tamo!\" On odstupi i stade.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 18, 31, 'Uto stiže Etiopljanin i progovori: \"Neka moj gospodar kralj primi veselu vijest. Jahve ti je danas pribavio pravdu izbavivši te iz ruku svih onih koji su ustali na tebe.\"');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 18, 32, 'A kralj upita Etiopljanina: \"Je li spašen mladić Abšalom?\" A Etiopljanin odgovori: \"Neka neprijatelji moga gospodara i kralja i svi koji se dižu na tebe u zloj namjeri - prođu kao taj mladić!\"');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 19, 1, 'Kralj zadrhta, pope se u gornju odaju nad vratima i zaplaka; jecajući govoraše ovako: \"Sine Abšalome, sine moj! Sine moj Abšalome! Oh, da sam ja umro mjesto tebe! Abšalome, sine moj, sine moj!\"');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 19, 2, 'I javiše Joabu: \"Eno kralj plače i tuguje za Abšalomom.\"');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 19, 3, 'Tako se pobjeda u onaj dan pretvorila u žalost za svu vojsku, jer je vojska čula u onaj dan da kralj tuguje za svojim sinom.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 19, 4, 'I toga se dana vojskom kradom vrati u grad, kao što se kradom šulja vojska koja se osramotila bježeći iz boja.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 19, 5, 'A kralj je pokrio svoje lice i vapio iza glasa: \"Sine moj Abšalome! Abšalome, sine moj! Sine moj!\"');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 19, 6, 'Tada Joab dođe kralju u kuću i reče mu: \"Postiđuješ danas lice svih svojih slugu koji su danas spasili život tebi, život tvojim sinovima i tvojim kćerima, život tvojim ženama i život inočama tvojim,');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 19, 7, 'jer iskazuješ ljubav onima koji te mrze, a mržnju onima koji te ljube. Danas si pokazao da ti ništa nije ni do vojvoda ni do vojnika, jer vidim sada da bi ti sasvim pravo bilo kad bi Abšalom bio živ, a mi svi da smo danas poginuli.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 19, 8, 'Zato sada ustani, iziđi i prijazno progovori svojim vojnicima; jer, kunem ti se Jahvom, ako ne iziđeš, nijedan čovjek neće ostati noćas s tobom, i to će ti biti veća nesreća od svih koje su te snašle od tvoje mladosti pa do sada.\"');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 19, 9, 'Kralj ustade i sjede na vrata. Javiše to svemu narodu govoreći: \"Eno kralj sjedi na vratima.\" I sav narod dođe pred kralja. A Izraelci bijahu pobjegli svaki u svoj šator.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 19, 10, 'I sav se narod po svim Izraelovim plemenima prepirao govoreći: \"Kralj nas je izbavio iz ruku naših neprijatelja, on nas je izbavio iz ruku filistejskih, a sada je morao pobjeći iz zemlje ispred Abšaloma.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 19, 11, 'A Abšalom koga smo pomazali za kralja poginuo je u boju. Zašto se, dakle, kolebate dovesti kralja natrag?\"');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 19, 12, 'Te riječi svega Izraela dopru do kralja u njegovu kuću. Zato kralj David poruči svećenicima Sadoku i Ebjataru: \"Recite starješinama judejskim ovako: \'Zašto da vi budete posljednji koji će kralja dovesti u njegovu kuću?');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 19, 13, 'Vi ste moja braća, vi ste od moga mesa i od mojih kosti. Zašto biste, dakle, bili posljednji koji će dovesti kralja natrag?\'');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 19, 14, 'Recite i Amasi: \'Nisi li ti od mojih kosti i od moga mesa? Neka mi Bog učini zlo i neka mi doda drugo ako mi ne budeš zauvijek vojvoda nad mojom vojskom namjesto Joaba!\'\"');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 19, 15, 'Tada se složiše svi ljudi Judina roda kao jedan čovjek i poručiše kralju: \"Vrati se sa svim svojim ljudima!\"');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 19, 16, 'I tako se kralj vrati i dođe do Jordana, a Judejci bijahu stigli do Gilgala dolazeći u susret kralju da prate kralja na prijelazu preko Jordana.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 19, 17, 'Tada je pohitio i Šimej, sin Gerin, Benjaminovac iz Bahurima, i sišao s Judejcima u susret kralju Davidu.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 19, 18, 'Imao je sa sobom tisuću ljudi od Benjaminova plemena. I Siba, sluga Šaulova doma, sa petnaest svojih sinova i dvadeset svojih slugu, dođe do Jordana pred kralja.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 19, 19, 'Dovezli su splav da prevezu kraljevu čeljad i da učine sve što bi mu bilo drago. A Gerin sin Šimej baci se pred noge kralju kad je kralj htio prijeći preko Jordana;');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 19, 20, 'i reče kralju: \"Neka mi moj gospodar ne upiše u grijeh! Ne opominji se zla što ti ga je učinio tvoj sluga u onaj dan kad je moj gospodar i kralj izlazio iz Jeruzalema. Neka to kralj ne uzima k srcu!');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 19, 21, 'Tvoj sluga uviđa da je sagriješio; zato sam, evo, došao danas prvi iz svega Josipova doma da siđem u susret svome gospodaru i kralju.\"');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 19, 22, 'Ali Sarvijin sin Abišaj progovori i reče: \"Zar Šimej ne zaslužuje smrt što je proklinjao pomazanika Jahvina?\"');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 19, 23, 'A David odgovori: \"Što ja imam s vama, Sarvijini sinovi, te me danas uvodite u napast? Zar bi danas mogao tko biti pogubljen u Izraelu? TÓa sada znam da sam danas opet kralj nad Izraelom.\"');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 19, 24, 'Tada kralj reče Šimeju: \"Nećeš poginuti!\" I kralj mu se zakle.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 19, 25, 'I Šaulov sin Meribaal sišao je u susret kralju. On nije njegovao ni svojih nogu ni svojih ruku, nije uređivao svoje brade, nije prao svojih haljina od onoga dana kad je otišao kralj pa sve do dana kad se opet vratio u miru.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 19, 26, 'Kad je iz Jeruzalema došao u susret kralju, upita ga kralj: \"Zašto nisi pošao sa mnom, Meribaale?\"');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 19, 27, 'A on odgovori: \"Kralju gospodaru! Moj me sluga prevario. Tvoj mu je sluga rekao: \'Osamari mi magaricu da je uzjašem i pođem s kraljem!\' Jer tvoj je sluga hrom.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 19, 28, 'On je oklevetao tvoga slugu pred mojim gospodarom i kraljem. Ali moj je gospodar i kralj kao Božji anđeo: zato čini što je dobro u tvojim očima.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 19, 29, 'Jer sav moj očinski dom nije bio drugo zaslužio nego smrt od moga gospodara kralja, a ti si ipak primio svoga slugu među one koji jedu za tvojim stolom. Pa kako još imam pravo tužiti se kralju?\"');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 19, 30, 'A kralj mu odgovori: \"Čemu da još duljiš svoj govor? Određujem: ti i Siba podijelite njive!\"');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 19, 31, 'Meribaal reče kralju: \"Neka uzme i sve, kad se moj gospodar kralj sretno vratio u svoj dom!\"');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 19, 32, 'I Barzilaj Gileađanin dođe iz Rogelima i nastavi s kraljem da ga isprati preko Jordana.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 19, 33, 'Barzilaj bijaše vrlo star, bilo mu je osamdeset godina. Pribavljao je kralju opskrbu dok je boravio u Mahanajimu jer bijaše vrlo imućan čovjek.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 19, 34, 'Kralj reče Barzilaju: \"Pođi sa mnom, ja ću te u tvojim starim danima uzdržavati kod sebe u Jeruzalemu.\"');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 19, 35, 'A Barzilaj odgovori kralju: \"A koliko mi još godina života ostaje da idem s kraljem u Jeruzalem?');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 19, 36, 'Sada mi je osamdeset godina; mogu li još razlikovati što je dobro a što zlo? Može li tvojem sluzi još goditi što jede i pije? Mogu li još slušati glas pjevača i pjevačica? Zašto bi tvoj sluga bio još na teret mome gospodaru kralju?');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 19, 37, 'Tvoj će sluga još samo prijeći preko Jordana s kraljem, ali zašto bi mi kralj dao takvu nagradu?');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 19, 38, 'Dopusti svome sluzi da se vrati, da umrem u svom gradu kod groba svoga oca i svoje majke. Ali evo tvoga sluge Kimhama, neka ide dalje s mojim gospodarom kraljem, pa njemu učini što je dobro u tvojim očima!\"');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 19, 39, 'Kralj odgovori: \"Neka onda Kimham ide sa mnom dalje, a ja ću mu učiniti što bude tebi drago i što god me zamoliš sve ću mu učiniti za tebe.\"');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 19, 40, 'Kad je sav narod prešao preko Jordana, prijeđe i kralj, poljubi Barzilaja i blagoslovi ga, potom se ovaj vrati u svoje mjesto.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 19, 41, 'Kralj nastavi put u Gilgal, a Kimham iđaše s njim. Kralja je pratio sav narod Judin i polovina naroda Izraelova.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 19, 42, 'Uto svi Izraelci dođu pred kralja i upitaju ga: \"Zašto te naša braća Judejci ukradoše i zašto prevedoše preko Jordana našega kralja i njegov dom i sve Davidove ljude s njim?\"');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 19, 43, 'A Juda odgovori Izraelu: \"Kralj je meni rod. Zašto si se ražestio zbog toga? Jesam li jeo na kraljev račun? Ili sam si što prigrabio?\"');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 19, 44, 'Tada Izrael odgovori Judi ovako: \"Ja imam deset udjela na kralja i prema tebi ja sam prvorođenac. Zašto si me, dakle, prezreo? Nije li moja riječ bila prva kad je trebalo natrag dovesti moga kralja?\" Ali govor Judin bijaše tvrđi od govora Izraelova.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 20, 1, 'Ondje se slučajno našao opak čovjek po imenu Šeba, Bikrijev sin, Benjaminovac. On zatrubi u rog i viknu: \"Mi nemamo udjela na Davidu ni baštine na Jišajevu sinu! Svaki svome šatoru, Izraele!\"');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 20, 2, 'Tako svi Izraelci ostaviše Davida i pođoše za Bikrijevim sinom Šebom; a Judejci prionuše uza svoga kralja i otpratiše ga od Jordana do Jeruzalema.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 20, 3, 'Kad se David vratio u svoju palaču u Jeruzalem, uze deset inoča koje je bio ostavio da čuvaju palaču i stavi ih da budu čuvane. Brinuo im se za uzdržavanje, ali nije više išao k njima. Tako su one živjele zatvorene do svoje smrti, kao udovice živoga muža.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 20, 4, 'Potom kralj zapovjedi Amasi: \"Sazovi mi Judejce do tri dana, a i ti da budeš ovdje!\"');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 20, 5, 'Amasa ode da sazove Judejce, ali se zadrža preko vremena koje mu bijaše odredio kralj.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 20, 6, 'Tada David reče Abišaju: \"Sad će nam Bikrijev sin Šeba biti opasniji nego Abšalom. Zato uzmi ljude svoga gospodara i pođi za njim u potjeru da se ne domogne tvrdih gradova i ne izmakne nam iz očiju!\"');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 20, 7, 'Za Abišajem krenu na put Joab, Kerećani, Pelećani i svi junaci; oni iziđu iz Jeruzalema u potjeru za Bikrijevim sinom Šebom.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 20, 8, 'Kad su bili kod velikoga kamena što je kod Gibeona, dođe Amasa prema njima. Joab imaše na sebi ratnu haljinu, a preko nje imaše pripasan mač uz bedro, u koricama; ali mu se mač iskliznu i pade.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 20, 9, 'Joab pozdravi Amasu: \"Jesi li mi dobro, brate?\" I desnom rukom uhvati za bradu Amasu da ga poljubi.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 20, 10, 'Amasa se nije obazirao na mač koji bijaše Joabu u ruci, i on ga udari njim u trbuh i prosu mu utrobu na zemlju. Nije morao ponoviti udarac i Amasa umrije. Joab sa svojim bratom Abišajem nastavi potjeru za Bikrijevim sinom Šebom.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 20, 11, 'Jedan od Joabovih momaka osta na straži kod Amase i tu je vikao: \"Kome je mio Joab i tko je za Davida neka slijedi Joaba!\"');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 20, 12, 'A Amasa ležao u krvi nasred puta. Videći onaj čovjek gdje se ustavlja sav narod, odvuče Amasu s puta u polje i baci preko njega kabanicu jer je vidio gdje se zaustavlja svatko tko naiđe blizu njega.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 20, 13, 'Kad je Amasa bio uklonjen s puta, svi ljudi pođoše za Joabom da gone Bikrijeva sina Šebu.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 20, 14, 'Šeba je prošao kroza sva izraelska plemena sve do Abel Bet Maake i svi Bikrani s njim. Skupiše se oni i pođoše za njim.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 20, 15, 'Joab dođe i opsjede ga u Abel Bet Maaki. Dade nasuti nasip oko grada. Sva vojska koja bijaše s Joabom navali potkopavati zid da ga obori.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 20, 16, 'Tada se jedna mudra žena uspe na zid i povika iz grada: \"Čujte! Čujte! Recite Joabu: \'Priđi ovamo, da govorim s tobom!\'\"');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 20, 17, 'Kad je prišao, upita žena: \"Jesi li ti Joab?\" On odgovori: \"Jesam.\" A ona će: \"Poslušaj riječ sluškinje svoje!\" On odgovori: \"Slušam.\"');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 20, 18, 'Žena nastavi: \"Nekoć se govorilo ovako: \'Treba pitati u Abelu i u Danu');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 20, 19, 'je li svršeno s onim što su utvrdili vjernici u Izraelu.\' Ti bi htio uništiti jedan grad, i to jedan od matičnih gradova u Izraelu. Zašto zatireš baštinu Jahvinu?\"');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 20, 20, 'Joab odgovori ovako: \"Daleko, daleko bilo to od mene! Ne želim ni zatirati ni razarati.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 20, 21, 'Ne radi se o tome, nego je jedan čovjek iz Efrajimove gore, po imenu Šeba, Bikrijev sin, podigao ruku na kralja, na Davida. Predajte samo njega, pa ću otići od grada!\" Žena odgovori Joabu: \"Dobro. Odmah će ti njegovu glavu baciti preko zida!\"');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 20, 22, 'Žena se vrati u grad i progovori svemu narodu kako joj je govorila njezina mudrost. I odsjekoše glavu Bikrijevu sinu Šebi i baciše je Joabu. A on zapovjedi da zatrube u rog te se raziđoše od grada, svaki u svoj kraj. A Joab se vrati kralju u Jeruzalem.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 20, 23, 'Joab je bio zapovjednik nad svom vojskom. Jojadin sin Benaja bio je zapovjednik nad Kerećanima i Pelećanima.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 20, 24, 'Adoram je bio nadglednik nad radovima. Ahiludov sin Jošafat bio je pečatnik.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 20, 25, 'Seraja je bio državni pisar. Sadok i Ebjatar bijahu svećenici.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 20, 26, 'Uz to je Jairanin Ira bio zamjenik Davidov.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 21, 1, 'U dane Davidove vladaše jednom glad tri godine uzastopce. David se obrati Jahvi, a Jahve mu odgovori: \"Na Šaulu i njegovu domu leži krvna krivnja jer je pogubio Gibeonce.\"');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 21, 2, 'Tada kralj sazva Gibeonce da ih pita. Ti Gibeonci nisu pripadali Izraelcima, nego su bili ostatak Amorejaca, kojima se Izraelci bijahu zakleli zakletvom, ali je Šaul tražio da ih uništi u svojoj revnosti za Izraelce i Judejce.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 21, 3, 'David, dakle, upita Gibeonce: \"Što da vam učinim i čime da vam dadem zadovoljštinu da biste blagoslovili baštinu Jahvinu?\"');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 21, 4, 'Gibeonci odgovoriše: \"Ne tražimo mi ni srebra ni zlata od Šaula i njegova doma, niti nam je stalo da se pogubi koji čovjek u Izraelu.\" David će im nato: \"Što reknete učinit ću za vas.\"');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 21, 5, 'A oni odgovoriše kralju: \"Čovjek koji nas je zatirao i koji je smišljao da nas uništi, da nas ne bude nigdje u svemu izraelskom području,');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 21, 6, 'od njegovih potomaka neka nam se preda sedam ljudi da ih objesimo pred Jahvom u Gibeonu na gori Jahvinoj.\" Kralj odvrati: \"Dat ću vam ih.\"');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 21, 7, 'Kralj poštedje Meribaala, sina Šaulova sina Jonatana, zbog zakletve pred Jahvom koja ih je vezala, Davida i Jonatana, sina Šaulova.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 21, 8, 'Tako kralj uze oba sina Rispe, Ajine kćeri, koje je rodila Šaulu, Armonija i Meribaala, i svih pet sinova Merabe, Šaulove kćeri, koje je rodila Adrielu, sinu Barzilajevu, iz Mehole.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 21, 9, 'Njih dade u ruke Gibeoncima, a oni ih objesiše na gori pred Jahvom. Tako sva sedmorica poginuše zajedno, pogubljeni prvih dana žetve, na početku ječmene žetve.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 21, 10, 'Rispa, Ajina kći, uze kostrijet i prostrije je za sebe na stijeni od početka ječmene žetve sve dok nije kiša s neba pala na mrtva tijela, i tako nije dala nebeskim pticama da se spuštaju na njih danju ni poljskim zvijerima noću.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 21, 11, 'Kad su Davidu javili što je učinila Ajina kći Rispa, Šaulova inoča,');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 21, 12, 'ode David i uze Šaulove kosti i kosti njegova sina Jonatana od stanovnika Jabeša Gileadskog, koji ih bijahu potajno odnijeli s trga u Bet Šanu, gdje su ih objesili Filistejci u onaj dan kad su Filistejci porazili Šaula na Gilboi.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 21, 13, 'David prenese odande Šaulove kosti i kosti njegova sina Jonatana pa ih združi s kostima pogubljenih.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 21, 14, 'I ukopaše Šaulove kosti i kosti njegova sina Jonatana s kostima pogubljenih u zemlji Benjaminovoj, u Seli, u grobu Šaulova oca Kiša. Pošto izvršiše sve što je kralj zapovjedio, Bog se smilova zemlji.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 21, 15, 'Jednom opet nasta rat između Filistejaca i Izraelaca. David ode u boj sa svojim ljudima te su se borili s Filistejcima tako da se David umorio.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 21, 16, 'Išibenob, jedan od Rafinih potomaka, čije je koplje bilo teško tri stotine mjedenih šekela i koji o pripasu imaše nov mač, hvastao se tada da će ubiti Davida.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 21, 17, 'Ali Davidu priskoči u pomoć Sarvijin sin Abišaj; udari on Filistejca te ga ubi. Tada se Davidovi ljudi zakleše rekavši Davidu: \"Nećeš više ići s nama u boj, da ne ugasiš svjetiljke Izraelove!\"');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 21, 18, 'Poslije toga opet izbi rat s Filistejcima u Gobu; tada je Hušanin Sibkaj pogubio Sipaja, jednoga od Rafinih potomaka.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 21, 19, 'Uz to nasta rat s Filistejcima u Gobu; tada je Jairov sin Elhanan iz Betlehema pogubio Golijata Gitejca, koji je imao kopljaču kao tkalačko vratilo.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 21, 20, 'Potom opet izbi rat u Gatu, gdje je bio neki čovjek visoka rasta: imaše taj na svakoj ruci i nozi po šest prstiju, dakle dvadeset i četiri; i on bijaše potomak Rafin.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 21, 21, 'Kad je počeo ružiti Izraela, ubi ga Jonatan, sin Davidova brata Šimeja.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 21, 22, 'Ta četvorica bijahu potomci istoga Rafe iz Gata, a poginuše od ruke Davidove i od ruku njegovih slugu.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 22, 1, 'David upravi Jahvi riječi ove pjesme u dan kad ga je Jahve izbavio iz ruku svih njegovih neprijatelja i iz ruke Šaulove.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 22, 2, 'Pjevao je: \"Jahve, hridino moja, utvrdo moja, spase moj;');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 22, 3, 'Bože moj, pećino moja kojoj se utječem, štite moj, spasenje moje, tvrđavo moja! Ti me izbavljaš od nasilja.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 22, 4, 'Zazvat ću Jahvu hvale predostojna i od dušmana bit ću izbavljen.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 22, 5, 'Valovi smrti okružiše mene, prestraviše me bujice pogubne,');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 22, 6, 'Užad Podzemlja sputiše me, smrtonosne zamke padoše na me:');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 22, 7, 'u nevolji zazvah Jahvu i Bogu svome zavapih. Iz svog Doma zov mi začu, i vapaj moj mu do ušiju doprije.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 22, 8, 'I zemlja se potrese i uzdrhta, uzdrmaše se temelji nebesa, pokrenuše se, jer On gnjevom planu.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 22, 9, 'Iz nosnica mu dim se diže, iz usta mu oganj liznu, ugljevlje živo od njega plamsa.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 22, 10, 'On nagnu nebesa i siđe, pod nogama oblaci mu mračni.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 22, 11, 'Na keruba stade i poletje; na krilima vjetra zaplovi.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 22, 12, 'Ogrnu se mrakom kao koprenom, prekri se tamnim vodama i oblacima tmastim,');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 22, 13, 'od bljeska pred licem njegovim užga se ugljevlje plameno.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 22, 14, 'Jahve s neba zagrmje, Svevišnjega glas se ori.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 22, 15, 'Odape strijele i dušmane rasu, izbaci munje i na zemlju ih obori.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 22, 16, 'Morska dna se pokazaše, i temelji svijeta postaše goli od strašne prijetnje Jahvine, od olujna daha gnjeva njegova.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 22, 17, 'On pruži s neba ruku i mene prihvati, iz silnih voda on me izbavi.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 22, 18, 'Od protivnika moćnog mene oslobodi, od dušmana mojih jačih od mene.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 22, 19, 'Navališe na me u dan zlosretni, ali me Jahve zaštiti,');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 22, 20, 'na polje prostrano izvede me, spasi me jer sam mu mio.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 22, 21, 'Po pravednosti mojoj Jahve mi uzvrati, po čistoći ruku mojih on me nagradi,');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 22, 22, 'jer čuvah putove Jahvine, od Boga se svoga ne udaljih.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 22, 23, 'Odredbe njegove sve su mi pred očima, zapovijedi njegove nisam odbacio,');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 22, 24, 'do srži odan njemu sam bio, čuvam se grijeha svakoga.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 22, 25, 'Jahve mi po pravdi mojoj vrati, čistoću ruku mojih vidje.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 22, 26, 'S prijateljem ti si prijatelj, poštenu poštenjem uzvraćaš.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 22, 27, 'S čovjekom čistim ti si čist, a lukavca izigravaš,');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 22, 28, 'jer narodu poniženu spasenje donosiš a ponižavaš oči ohole.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 22, 29, 'Jahve, ti moju svjetiljku užižeš, Bože, tminu moju obasjavaš:');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 22, 30, 's tobom udaram na čete dušmanske, s Bogom svojim preskačem zidine.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 22, 31, 'Savršeni su puti Gospodnji, i riječ je Jahvina ognjem kušana. on je štit svima, samo on, koji se k njemu utječu.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 22, 32, 'Jer tko je Bog osim Jahve? Tko li je hridina osim Boga našega?');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 22, 33, 'Taj Bog me snagom opasuje, stere mi put besprijekoran.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 22, 34, 'Noge mi dade brze ko u košute i postavi me na visine sigurne,');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 22, 35, 'ruke mi za borbu uvježba i mišice da luk mjedeni napinju.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 22, 36, 'Daješ mi štit svoj koji spasava, tvoja me brižljivost uzvisi.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 22, 37, 'Pouzdanje daješ mom koraku, i noge mi više ne posrću.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 22, 38, 'Pognah svoje dušmane i dostigoh, i ne vratih se dok ih ne uništih.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 22, 39, 'Obaram ih, ne mogu se dići, padaju, pod nogama mi leže.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 22, 40, 'Ti me opasa snagom za borbu, a protivnike moje meni podloži.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 22, 41, 'Ti dušmane moje u bijeg natjera, i rasprših one koji su me mrzili.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 22, 42, 'Vapiju u pomoć, nikog da pomogne, vapiju Jahvi - ne odaziva se.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 22, 43, 'Smrvih ih kao prah na vjetru, zgazih ih ko blato na putu.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 22, 44, 'Ti me §izbavÄi od bune u mom narodu, postavi me glavarom pogana, puk koji ne poznavah služi mi.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 22, 45, 'Svaki moj šapat pokorno on sluša. Sinovi tuđinci meni laskaju,');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 22, 46, 'sinovi tuđinski gube srčanost izlaze dršćuć iz svojih utvrda.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 22, 47, 'Živio Jahve! Blagoslovljena hridina moja! Neka se uzvisi Bog, spasenje moje!');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 22, 48, 'Bog koji mi daje osvetu i narode meni pokorava.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 22, 49, 'Od dušmana me mojih izbavljaš i nad protivnike me moje izdižeš, ti mene od čovjeka silnika spasavaš.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 22, 50, 'Zato te slavim, Jahve, među pucima i psalam pjevam tvome Imenu:');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 22, 51, 'umnožio si pobjede kralju svojemu, pomazaniku svome milost si iskazao, Davidu i potomstvu njegovu navijeke.\"');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 23, 1, 'Ovo su posljednje Davidove riječi: \"Riječ Davida, sina Jišajeva, riječ čovjeka koji je bio visoko uzdignut, pomazanika Boga Jakovljeva, pjevača pjesama Izraelovih:');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 23, 2, 'Jahvin duh govori po meni, njegova je riječ na mom jeziku.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 23, 3, 'Reče mi Jakovljev Bog, reče mi Izraelova hrid: Tko vlada ljudima pravedno, i tko vlada u strahu Božjemu,');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 23, 4, 'taj je kao jutarnja svjetlost kad ograne sunce, jutro bez oblaka, na kojem se svjetluca zemaljska trava poslije kiše.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 23, 5, 'Da, moja kuća stoji čvrsto pred Bogom: on je učinio vječan Savez sa mnom, u svemu dobro uređen i utvrđen. Da, on će dati da napreduje sve moje spasenje i svaka moja želja.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 23, 6, 'Belijalovi ljudi svi su kao trnje u pustinji, jer ih nitko ne hvata rukom.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 23, 7, 'Nitko ih se ne dotiče, osim gvožđem i kopljačom, i potpuno se spaljuju u ognju.\"');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 23, 8, 'Ovo su imena Davidovih junaka: Išbaal, Hakmonac, prvak među trojicom; on je zavitlao svojim kopljem protiv osam stotina i pobio ih najedanput.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 23, 9, 'Za njim dolazi Eleazar, sin Dodonov, Ahoašanin, jedan od trojice junaka; on je bio s Davidom kod Pas Damina kad su se ondje skupili Filistejci za boj, a Izraelci se povukli pred njima.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 23, 10, 'Ali se on čvrsto držao i udarao Filistejce dok mu se ruka nije ukočila i ostala kao prirasla uz mač. Jahve je dao veliku pobjedu u onaj dan, pa se vojska vratila za Eleazarom, ali samo da pokupi plijen.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 23, 11, 'Za njim dolazi Šama, sin Elin, Hararac; kad su se Filistejci skupili u Lehiju, bijaše polje puno leće, a vojska je bila pobjegla ispred Filistejaca.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 23, 12, 'Tada je on stao usred polja i obranio ga i potukao Filistejce. Tako je Jahve dao veliku pobjedu.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 23, 13, 'Trojica između tridesetorice jednom su krenula na put i o početku žetve došla k Davidu u Adulamsku pećinu kad jedna filistejska četa bijaše utaborena u Refaimskoj dolini.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 23, 14, 'David je tada bio u svojoj kuli, a filistejska je posada bila tada u Betlehemu.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 23, 15, 'David uzdahnu: \"O, kad bi me tko napojio vodom iz betlehemskoga studenca što je kod vrata?\"');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 23, 16, 'Tada ta tri junaka prodriješe kroz filistejski tabor i, zahvativši vode iz betlehemskog studenca što je kod vrata, donesoše je i dadoše Davidu. Ali je David ne htjede piti, nego je proli kao ljevanicu Jahvi');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 23, 17, 'govoreći: \"Ne dao mi Jahve da to učinim! Zar da pijem krv ovih ljudi? TÓa izlažući život pogibli, donijeli su vode!\" I nije htio piti. To su, eto, učinila ta tri junaka.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 23, 18, 'Abišaj, Joabov brat a sin Sarvijin, bio je vojvoda nad tridesetoricom. On je zavitlao kopljem na tri stotine, pobio ih i proslavio se među tridesetoricom.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 23, 19, 'On se odlikovao među tridesetoricom i postao njihov glavar, ali nije dostigao trojice.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 23, 20, 'Jojadin sin Benaja, junak iz Kabseela, bogat junačkim djelima, ubio je dva sina Ariela iz Moaba; on je jednoga snježnog dana sišao i ubio lava usred jame.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 23, 21, 'Ubio je i nekog Egipćanina, čovjeka golema stasa. Egipćanin je imao koplje u ruci, a on izišao preda nj sa štapom: istrgavši Egipćaninu koplje iz ruke, ubi ga njegovim kopljem.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 23, 22, 'To je učinio Jojadin sin Benaja i proslavio se među tridesetoricom junaka.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 23, 23, 'Bio je najznamenitiji među tridesetoricom, ali one prve trojice nije dostigao; David ga postavi za zapovjednika svoje tjelesne straže.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 23, 24, 'Asahel, brat Joabov, bio je među tridesetoricom. Zatim: Elhanan, sin Dodonov, iz Betlehema;');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 23, 25, 'Šama iz Haroda; Elika iz Haroda;');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 23, 26, 'Heles iz Peleta; Ira, sin Ikešev, iz Tekoe;');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 23, 27, 'Abiezer iz Anatota; Sibekaj iz Huše;');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 23, 28, 'Salmon iz Ahoha; Mahraj iz Netofe;');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 23, 29, 'Heled, sin Baanin, iz Netofe; Itaj, sin Ribajev, iz Gibeje sinova Benjaminovih;');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 23, 30, 'Benaja iz Pireatona; Hidaj od Gaaških potoka;');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 23, 31, 'Abibaal iz Bet Haarabe; Azmavet iz Bahurima;');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 23, 32, 'Eljahba iz Šaalbona; Jašen, sin Jonatanov;');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 23, 33, 'Šama iz Harara; Ahiam, sin Šararov, iz Arara;');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 23, 34, 'Elifelet, sin Ahasbajev, iz Bet Maake; Eliam, sin Ahitofelov, iz Gilona;');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 23, 35, 'Hesraj iz Karmela; Paaraj iz Araba;');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 23, 36, 'Jigeal, sin Natanov, iz Sobe; Bani iz Gada;');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 23, 37, 'Selek Amonac; Nahraj iz Beerota, štitonoša Sarvijina sina Joaba;');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 23, 38, 'Ira iz Jatira; Gareb iz Jatira;');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 23, 39, 'Urija Hetit. Svega trideset i sedam.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 24, 1, 'Još je jednom srdžba Jahvina planula na Izraelce te potakla Davida protiv njih govoreći: \"Idi, izbroj Izraelce i Judejce!\"');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 24, 2, 'I kralj zapovjedi Joabu i vojvodama koji bijahu s njim: \"Obiđite sva Izraelova plemena od Dana do Beer Šebe i popišite narod da znam koliko ima naroda.\"');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 24, 3, 'Joab odgovori kralju: \"Neka Jahve, tvoj Bog, dade svome narodu još sto puta ovoliko koliko ga je sada i neka to još vidi svojim očima moj gospodar kralj, ali zašto moj gospodar kralj ima takvu želju?\"');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 24, 4, 'Ali kraljeva riječ bijaše jača od Joabove i od riječi vojvoda njegove vojske. Tako Joab i vojvode odoše ispred kralja da popišu izraelski narod.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 24, 5, 'Prijeđoše oni preko Jordana i počeše kod Aroera i kod grada što leži usred doline i krenuše odande prema Gaditima i prema Jazeru.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 24, 6, 'Potom dođoše u Gilead i u zemlju Hetita, u Kadeš; zatim stigoše u Dan, a iz Dana skrenuše prema Sidonu.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 24, 7, 'Zatim dođoše do tvrđave Tira i u sve gradove Hivijaca i Kanaanaca i završiše svoj put u Negebu Judinu, u Beer Šebi.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 24, 8, 'Prošavši svu zemlju, vratiše se poslije devet mjeseci i dvadeset dana u Jeruzalem.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 24, 9, 'Joab dade kralju popis naroda: Izraelaca bijaše osam stotina tisuća ratnika vičnih maču, a Judejaca pet stotina tisuća ljudi.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 24, 10, 'Poslije toga Davida zapeče savjest što je dao brojiti narod pa reče Jahvi: \"Veoma sam sagriješio što sam to učinio! Ali, Jahve, oprosti tu krivicu sluzi svome, jer sam vrlo ludo radio.\"');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 24, 11, 'Kad je David ujutro ustao, već je Jahvina riječ bila došla proroku Gadu, Davidovu vidiocu:');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 24, 12, '\"Idi i kaži Davidu: Ovako govori Jahve: \'Troje stavljam preda te, izaberi jedno od toga da ti učinim!\'\"');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 24, 13, 'Gad tako dođe Davidu i javi mu ovo: \"Hoćeš li da dođu tri gladne godine na tvoju zemlju, ili da tri mjeseca bježiš pred svojim neprijateljem koji će te goniti, ili da bude tri dana kuga u tvojoj zemlji? Sada promisli i gledaj što da odgovorim onome koji me poslao!\"');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 24, 14, 'David odgovori Gadu: \"Na velikoj sam muci! Ali neka padnemo u ruke Jahvine, jer je veliko njegovo milosrđe, a u ljudske ruke neka ne zapadnem!\"');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 24, 15, 'David, dakle, izabra kugu. Bilo je upravo vrijeme pšenične žetve. Jahve pusti kugu na Izraela od jutra pa do određenoga vremena; i pomor udari na narod i pomrije sedamdeset tisuća ljudi od Dana do Beer Šebe.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 24, 16, 'Kad je anđeo pružio svoju ruku na Jeruzalem da ga uništi, sažali se Jahvi zbog toga zla, pa reče anđelu koji je ubijao narod: \"Dosta je sada! Povuci svoju ruku!\" A Jahvin je anđeo bio upravo kod gumna Araune Jebusejca.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 24, 17, 'Kad David vidje anđela koji je ubijao narod, zavapi Jahvi: \"Evo, ja sam sagriješio, ja sam učinio zlo! A oni, ovce, što su skrivili? Neka tvoja ruka padne na mene i na moju obitelj!\"');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 24, 18, 'Istoga dana dođe Gad k Davidu i reče mu: \"Idi i podigni Jahvi žrtvenik na gumnu Araune Jebusejca!\"');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 24, 19, 'I ode David po Gadovoj riječi, kako mu je zapovjedio Jahve.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 24, 20, 'Kad Arauna pogleda, opazi kralja i njegove dvorane gdje idu prema njemu. Arauna iziđe i pokloni se kralju licem do zemlje.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 24, 21, 'Arauna upita: \"Zašto je moj gospodar kralj došao svome sluzi?\" A David odgovori: \"Da kupi od tebe ovo gumno, da sagradi žrtvenik Jahvi, kako bi prestao pomor u narodu.\"');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 24, 22, 'Arauna reče Davidu: \"Neka ga uzme moj gospodar kralj i neka žrtvuje ono što je u njegovim očima dobro! Evo goveda za paljenicu, mlatilice, i volujske opreme za drvo!');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 24, 23, 'Sve to sluga moga gospodara kralja poklanja kralju!\" Još reče Arauna kralju: \"Jahve, Bog tvoj, neka ti bude milostiv!\"');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 24, 24, 'Ali kralj odgovori Arauni: \"Ne, nego hoću da kupim od tebe i da platim; neću prinositi Jahvi, svome Bogu, paljenica koje su mi poklonjene.\" I tako David kupi ono gumno i goveda za pedeset srebrnih šekela.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 24, 25, 'Ondje David sagradi žrtvenik Jahvi i prinese paljenice i pričesnice. Tada se Jahve smilova zemlji i presta pomor u Izraelu.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 1, 1, 'Kralj David bijaše ostario i odmakao u godinama; premda su ga pokrivali mnogim pokrivačima, nije se mogao ugrijati.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 1, 2, 'Tada mu rekoše njegove sluge: \"Trebalo bi potražiti za gospodara mladu djevojku koja bi dvorila kralja i služila mu: kad bude spavala na njegovu krilu, to će ugrijati kralja gospodara.\"');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 1, 3, 'Potražiše, dakle, lijepu djevojku po svoj zemlji izraelskoj; i nađoše Abišagu Šunamku te je dovedoše kralju.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 1, 4, 'Djevojka je bila izvanredno lijepa; njegovala je kralja i služila mu, ali je on ne upozna.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 1, 5, 'Uto se Adonija, sin Hagitin, pooholi i pomisli: \"Ja ću biti kralj!\" Zato nabavi sebi kola i konjanika i pedeset ljudi koji su išli pred njim.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 1, 6, 'Njegov ga otac za svoga života nikad nije ukorio niti ga kad upitao: \"Zašto tako činiš?\" Bio je, osim toga, stasit i lijep, a mati ga rodila poslije Abšaloma.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 1, 7, 'On se dogovarao s Joabom, sinom Sarvijinim, i sa svećenikom Ebjatarom, pa se obojica priključiše Adoniji.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 1, 8, 'Ali svećenik Sadok i Jojadin sin Benaja, prorok Natan, Šimej i Rei i junaci Davidovi ne pristadoše uz Adoniju.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 1, 9, 'Jednom nakla Adonija ovaca, volova i tovljene teladi za žrtvu kod Zoheledskog kamena, blizu izvora Rogela, te pozva svu svoju braću, sinove kraljeve, i sve Judejce u kraljevoj službi;');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 1, 10, 'ali ne pozva proroka Natana, ni Benaje, ni ostalih junaka, a ni svoga brata Salomona.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 1, 11, 'Tada reče Natan Bat-Šebi, majci Salomonovoj: \"Zar nisi čula da je Adonija, sin Hagitin, postao kraljem, a da David, naš gospodar, o tome i ne zna?');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 1, 12, 'Dođi da te savjetujem kako bi mogla spasiti život svoj i svoga sina Salomona.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 1, 13, 'Hajde, otiđi kralju Davidu i reci mu: \'Zar se nisi ti, gospodaru moj kralju, zakleo svojoj službenici govoreći: Tvoj sin Salomon kraljevat će poslije mene, i on će sjediti na mome prijestolju! Kako sada Adonija posta kraljem?\'');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 1, 14, 'I dok ti budeš ondje i razgovorala se s kraljem, doći ću ja za tobom i potvrditi tvoje riječi.\"');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 1, 15, 'Bat-Šeba ode kralju u odaje - a on je bio vrlo star i Abišaga Šunamka služila mu.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 1, 16, 'Pokloni mu se Bat-Šeba i pade ničice pred kraljem, a kralj upita: \"Što želiš?\"');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 1, 17, 'Ona mu odgovori: \"Gospodaru, ti si se zakleo službenici svojoj Jahvom, Bogom svojim: \'Tvoj sin Salomon kraljevat će poslije mene, on će sjesti na moje prijestolje.\'');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 1, 18, 'A sada je, evo, Adonija postao kraljem, a ti, kralju, gospodaru moj, ništa o tome i ne znaš!');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 1, 19, 'Naklao je on mnogo volova, tovljene teladi i ovaca za žrtvu i pozvao je sve sinove kraljeve, svećenika Ebjatara i vojskovođu Joaba, ali slugu tvoga Salomona nije pozvao.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 1, 20, 'U tebe su sada, gospodaru moj i kralju, uprte oči svega Izraela da mu ti objaviš tko će te naslijediti na tvome prijestolju, kralju, gospodaru moj.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 1, 21, 'Inače, čim počine kralj, gospodar moj, kraj svojih otaca, ja i moj sin Salomon bit ćemo krivci.\"');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 1, 22, 'Dok je ona još govorila s kraljem, dođe prorok Natan.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 1, 23, 'Javiše kralju: \"Ovdje je prorok Natan.\" On uđe kralju i pade ničice pred njim.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 1, 24, 'Natan reče: \"Gospodaru moj i kralju, jesi li ti odredio: \'Adonija će kraljevati poslije mene i sjedit će na mome prijestolju?\'');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 1, 25, 'Jer evo danas je sišao i naklao volova, ugojene teladi i ovaca za žrtvu i pozvao je sve sinove kraljeve, vojskovođe i svećenika Ebjatara; eno ih gdje jedu i piju s njim i kliču: \'Živio kralj Adonija!\'');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 1, 26, 'Ali mene, tvoga slugu, svećenika Sadoka, a ni Benaju, sina Jojadina, ni tvoga slugu Salomona nije pozvao.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 1, 27, 'Zar se to dogodilo s voljom gospodara moga kralja, a da nisi obavijestio svoga vjernog sluge tko će biti nasljednik na prijestolju gospodara moga kralja?\"');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 1, 28, 'Tada progovori David i reče: \"Pozovite mi Bat-Šebu!\" Ona dođe kralju i stupi preda nj.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 1, 29, 'Kralj se tada zakle: \"Tako mi Jahve živoga koji me izbavio iz svih nevolja!');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 1, 30, 'Danas ću ti ispuniti kako sam ti se zakleo Jahvom, Bogom Izraelovim: tvoj će sin Salomon kraljevati poslije mene, on će sjediti na mome prijestolju!\"');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 1, 31, 'Nato se nakloni Bat-Šeba licem do zemlje, pokloni se pred kraljem i reče: \"Neka vječno živi gospodar moj kralj David!\"');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 1, 32, 'A kralj David reče: \"Pozovite mi svećenika Sadoka, proroka Natana i Benaju, sina Jojadina.\" I dođoše oni pred kralja,');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 1, 33, 'a on im reče: \"Uzmite sluge svoga gospodara sa sobom, posadite moga sina Salomona na moju mazgu i odvedite ga do Gihona.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 1, 34, 'Ondje neka ga svećenik Sadok i prorok Natan pomažu za kralja nad Izraelom. Zatrubite tada i obznanite: \'Živio kralj Salomon!\'');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 1, 35, 'Zatim se uspnite amo s njim i neka uđe i sjedne na moje prijestolje i neka kraljuje mjesto mene, jer moja je volja: on neka bude glava nad Izraelom i nad Judom.\"');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 1, 36, 'Benaja, sin Jojadin, reče kralju: \"Amen - tako neka bude! To je i riječ Jahve, Gospodara kraljeva!');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 1, 37, 'Kao što je Jahve bio s mojim gospodarem kraljem, tako neka bude i sa Salomonom! Neka uzvisi prijestolje njegovo još više nego prijestolje kralja Davida, gospodara moga!\"');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 1, 38, 'Svećenik Sadok, prorok Natan, Jojadin sin Benaja, Kerećani i Pelećani siđoše i posadiše Salomona na kraljevu mazgu i odvedoše ga na Gihon.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 1, 39, 'Svećenik Sadok donese iz Šatora rog s uljem i pomaza Salomona. Tada odjeknuše trube i sav narod povika: \"Živio kralj Salomon!\"');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 1, 40, 'I sav narod pođe za njim gore i sviraše puk u svirale i klicaše tako da se sva zemlja tresla.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 1, 41, 'Čuo to Adonija i svi njegovi uzvanici. Baš su bili pri kraju gozbe. I Joab je čuo trube pa upita: \"Čemu ta buka u gradu?\"');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 1, 42, 'Dok je on još govorio, stiže Jonatan, sin svećenika Ebjatara, i Adonija mu reče: \"Ti si valjan čovjek, zacijelo nosiš dobru vijest!\"');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 1, 43, 'Jonatan odgovori: \"Jest, naš gospodar, kralj David, učinio je Salomona kraljem!');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 1, 44, 'Kralj je poslao s njim svećenika Sadoka, proroka Natana i Jojadina sina Benaju, i Kerećane i Pelećane. Oni ga posadiše na kraljevu mazgu,');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 1, 45, 'i svećenik Sadok i prorok Natan pomazaše ga na Gihonu za kralja. Zatim su sišli radosno kličući, i sav je grad uzavreo; to je buka koju ste čuli.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 1, 46, 'Još više: Salomon je već sjeo na kraljevsko prijestolje');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 1, 47, 'i došle su sluge kraljeve čestitati našem gospodaru kralju Davidu govoreći: \'Neka Bog tvoj proslavi ime Salomonovo više od imena tvoga i prijestolje njegovo uzvisi više od tvoga.\' Kralj se tada poklonio na svojoj postelji');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 1, 48, 'i ovako rekao: \'Neka je blagoslovljen Jahve, Bog Izraelov, koji mi dade danas da mogu vidjeti svojim očima jednoga od mojih kako sjedi na mome prijestolju.\'\"');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 1, 49, 'Svi uzvanici Adonijini, uplašeni, ustadoše od stola i raziđoše se svaki svojim putem.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 1, 50, 'Adonija pak, u strahu od Salomona, usta i ode te se uhvati za rogove žrtvenika.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 1, 51, 'Javiše Salomonu: \"Gle, Adonija se uplašio kralja Salomona i eno se drži za rogove žrtvenika govoreći: \'Neka mi se danas kralj Salomon zakune da neće sluge svoga mačem pogubiti.\'\"');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 1, 52, 'Salomon reče nato: \"Ako se pokaže poštenim čovjekom, neće mu ni vlas s glave pasti na zemlju; a nađe li se u zlu, poginut će.\"');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 1, 53, 'Tada zapovjedi Salomon da ga odmaknu od žrtvenika; on dođe i pade ničice pred Salomonom, koji mu reče: \"Pođi svome domu!\"');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 2, 1, 'Kad su se dani Davidovi približavali svome svršetku, zapovjedi David svome sinu Salomonu:');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 2, 2, '\"Sada polazim na put sviju smrtnika. Ti budi hrabar i pokaži se čovjekom!');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 2, 3, 'Slušaj naredbe Jahve, Boga svoga, idi njegovim stazama, drži se njegovih zakona, zapovijedi, naredaba i njegovih pouka, kako je napisano u Zakonu Mojsijevu, da bi uspio u svemu što poduzmeš i svagdje kamo se okreneš;');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 2, 4, 'da bi Jahve ispunio svoje obećanje koje mi je dao: \'Ako sinovi tvoji budu pazili na svome putu, vjerno hodeći preda mnom, svim srcem svojim i svom dušom svojom, uvijek će jedan od njih sjediti na prijestolju Izraelovu.\'');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 2, 5, 'I sam znaš što mi je učinio Joab, sin Sarvijin, kako je učinio obojici vojskovođa Izraelovih: Abneru, sinu Nerovu, i Amasi, sinu Jeterovu, kad ih je ubio i time prolio krv u miru kao u ratu te omastio krvlju pojas oko bokova svojih i obuću na nogama svojim.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 2, 6, 'Ti postupi po svom razboru i ne daj da mu sijeda kosa mirno počine u Podzemlju.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 2, 7, 'A sinovima Barzilaja Gileađanina vrati ljubav: neka budu među onima koji jedu za tvojim stolom jer su mi pomogli kad sam bježao pred tvojim bratom Abšalomom.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 2, 8, 'Pred sobom imaš Šimeja, sina Gerina, Benjaminovca iz Bahurima, koji me užasnim kletvama proklinjao onoga dana kad sam bježao u Mahanajim. Ali mi je on sišao u susret na Jordan i zakleh mu se Jahvom: \'Neću te pogubiti mačem.\'');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 2, 9, 'Ali mu ti toga ne opraštaj, jer si čovjek razborit, i već ćeš znati kako treba da postupiš te mu sijedu kosu s krvlju u Podzemlje spremiš.\"');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 2, 10, 'I potom počinu David kraj otaca svojih i bi pokopan u Davidovu gradu.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 2, 11, 'David je kraljevao nad Izraelom četrdeset godina: u Hebronu je kraljevao sedam godina, u Jeruzalemu je kraljevao trideset i tri godine.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 2, 12, 'Salomon sjede na prijestolje Davida, svoga oca, i njegova se vlast veoma učvrsti.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 2, 13, 'Ali Adonija, sin Hagitin, dođe Bat-Šebi, majci Salomonovoj, i pade ničice pred njom. Ona ga upita: \"Je li miroljubiv tvoj dolazak?\" On odgovori: \"Jest, miroljubiv je.\"');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 2, 14, 'I nastavi: \"Imam ti nešto reći.\" Ona reče: \"Govori.\"');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 2, 15, 'Tada će on: \"Znaš i sama da je kraljevstvo pripadalo meni i da je sav Izrael očekivao da ću ja biti kralj. Ali mi je kraljevstvo izmaklo i pripalo je mome bratu, jer mu ga je Jahve namijenio.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 2, 16, 'Ja te sada samo jedno molim: nemoj me odbiti.\" Ona reče: \"Govori.\"');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 2, 17, 'A on nastavi: \"Reci, molim te, kralju Salomonu - jer tebe neće odbiti - neka mi dade za ženu Abišagu Šunamku!\"');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 2, 18, 'A Bat-Šeba odgovori: \"Dobro, govorit ću kralju o tebi.\"');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 2, 19, 'Kada dakle uđe Bat-Šeba kralju Salomonu da govori o Adoniji, ustade kralj i pođe joj u susret, pokloni se pred njom, zatim sjede na svoje prijestolje i zapovjedi te namjestiše sjedalicu za kraljicu majku, i ona mu sjede s desne strane.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 2, 20, 'Tada mu reče: \"Nešto bih zaiskala od tebe, nemoj me odbiti.\" Kralj joj odgovori: \"Traži, majko, jer te neću odbiti.\"');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 2, 21, 'Ona nastavi: \"Neka se dade Abišaga Šunamka tvome bratu Adoniji za ženu.\"');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 2, 22, 'Kralj Salomon odgovori i reče svojoj majci: \"Zašto tražiš Abišagu Šunamku za Adoniju? Traži odmah i kraljevstvo za njega! Jer on je moj stariji brat, a uz njega je svećenik Ebjatar i Joab, sin Sarvijin!\"');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 2, 23, 'Tada se kralj Salomon zakle Jahvom: \"Neka mi Bog učini ovo zlo i neka mi doda drugo ako Adonija nije to izrekao danas po cijenu svoga života!');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 2, 24, 'Živoga mi Jahve, koji me potvrdio i posadio na prijestolje oca moga Davida i koji mi je dao dom kako je obećao: još danas će Adonija umrijeti.\"');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 2, 25, 'I kralj Salomon posla Benaju, sina Jojadina, koji ga udari te Adonija umrije.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 2, 26, 'Svećeniku Ebjataru kralj zatim naredi: \"Idi u Anatot na svoj posjed. Zaslužio si smrt, ali te neću pogubiti danas jer si nosio Jahvin Kovčeg pred ocem mojim Davidom i podijelio si sve patnje s mojim ocem.\"');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 2, 27, 'I Salomon isključi Ebjatara iz svećenstva Jahvina da tako ispuni Jahvinu riječ koju je izrekao protiv doma Elijeva u Šilu.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 2, 28, 'Kada je glas stigao Joabu - Joab bijaše pristao uz Adoniju, premda se nije priključio Abšalomu - on uteče u Šator Jahvin i uhvati se za rogove žrtvenika.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 2, 29, 'I dojaviše kralju Salomonu: \"Joab je pobjegao u Šator Jahvin, eno ga pokraj žrtvenika.\" Tada Salomon poruči Joabu: \"Što se držiš žrtvenika?\" Joab odgovori: \"Uplašio sam se tebe i pobjegao sam pred Jahvu.\" Tada Salomon naredi Benaji, sinu Jojadinu: \"Idi i ubij ga!\"');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 2, 30, 'Benaja ode u Šator Jahvin i reče Joabu: \"Po naredbi kraljevoj: iziđi!\" On odgovori: \"Neću, želim ovdje umrijeti!\" Benaja javi kralju: \"Eto što mi je rekao Joab i što mi je odgovorio.\"');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 2, 31, 'Kralj mu reče: \"Učini kako je rekao: ubij ga, zatim pokopaj. Tako ćeš danas skinuti s mene i doma oca moga nevinu krv koju je Joab prolio.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 2, 32, 'Jahve će učiniti da krv njegova padne na njegovu glavu, jer je ubio dva čovjeka pravednika i bolja od sebe; ubio ih je mačem bez znanja moga oca Davida: Abnera, sina Nerova, vođu vojske Izraelove, i Amasu, sina Jeterova, vojvodu judejskoga.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 2, 33, 'Neka njihova krv padne na glavu Joaba i njegova potomstva dovijeka, a Davidu, njegovu potomstvu, vladalačkoj kući i prijestolju neka od Jahve bude trajan mir.\"');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 2, 34, 'I ode Benaja, sin Jojadin, obori se na Joaba i usmrti ga. Pokopali su Joaba u njegovu domu u pustinji.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 2, 35, 'Mjesto njega postavi kralj na čelo vojske Benaju, sina Jojadina, a na mjesto Ebjatara postavi svećenika Sadoka.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 2, 36, 'Salomon pozva Šimeja i reče mu: \"Sagradi sebi kuću u Jeruzalemu: tu stanuj, i nikamo odatle ne izlazi.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 2, 37, 'Onoga dana kad iziđeš i prijeđeš potok Kidron, znaj dobro da ćeš umrijeti. Krv tvoja na glavu tvoju.\"');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 2, 38, 'Šimej odgovori kralju: \"Dobro. Kako moj gospodar kralj kaže, tako će učiniti sluga tvoj.\" I Šimej dugo življaše u Jeruzalemu.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 2, 39, 'Ali poslije tri godine dogodi se te Šimeju pobjegoše dvojica slugu k Akišu, sinu Maakinu, kralju gatskom. I dojaviše Šimeju: \"Eno ti slugu u Gatu.\"');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 2, 40, 'Tada usta Šimej, osedla magarca i ode u Gat, k Akišu, da traži svoje sluge. I vratio se Šimej i doveo svoje sluge iz Gata.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 2, 41, 'I javiše Salomonu: \"Šimej otišao iz Jeruzalema u Gat i vratio se.\"');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 2, 42, 'Kralj pozva Šimeja i reče mu: \"Nisam li ti se zakleo Jahvom i strogo te opomenuo: \'Onoga dana kad budeš izišao i pošao bilo kamo, znaj dobro da ćeš umrijeti!\' A ti si mi tada odgovorio: \'Dobra je riječ koju sam čuo.\'');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 2, 43, 'Zašto nisi održao zakletvu Jahvinu i zapovijed koju sam ti dao?\"');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 2, 44, 'Još reče kralj Šimeju: \"Ti znaš sve zlo koje si učinio mome ocu Davidu. Tvoje je srce toga svjesno. Jahve neka učini da se tvoja zloća obori na tvoju glavu.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 2, 45, 'A blagoslovljen je kralj Salomon, i prijestolje će Davidovo biti čvrsto pred Jahvom dovijeka.\"');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 2, 46, 'I zapovjedi kralj Benaji, sinu Jojadinu, te on iziđe i udari Šimeja i tako Šimej umrije. Tako se učvrstilo kraljevstvo u ruci Salomonovoj.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 3, 1, 'Salomon se sprijatelji s faraonom, kraljem egipatskim: oženi se kćerju faraonovom i uvede je u Davidov grad dokle ne dovrši gradnju svoga dvora, Hrama Jahvina i zidova oko Jeruzalema.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 3, 2, 'Narod je pak prinosio žrtve na uzvišicama, jer još nije bio sagrađen do toga vremena dom imenu Jahvinu.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 3, 3, 'A Salomon je ljubio Jahvu: ravnao se prema naredbama svoga oca Davida, samo je prinosio klanice i kađenice na uzvišicama.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 3, 4, 'Kralj ode u Gibeon da prinese žrtvu, jer ondje bijaše najveća uzvišica. Salomon prinese tisuću paljenica na tom žrtveniku.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 3, 5, 'U Gibeonu se Jahve javi Salomonu noću u snu. Bog reče: \"Traži što da ti dadem.\"');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 3, 6, 'Salomon odgovori: \"Veoma si naklon bio svome sluzi Davidu, mome ocu, jer je hodio pred tobom u vjernosti, pravednosti i poštenju srca svoga; i sačuvao si mu tu veliku milost i dao si da jedan od njegovih sinova sjedi na njegovu prijestolju.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 3, 7, 'Sada, o Jahve, Bože moj, ti si učinio kraljem slugu svoga na mjesto moga oca Davida, a ja sam još sasvim mlad te još ne znam vladati.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 3, 8, 'Tvoj je sluga usred naroda koji si izabrao; naroda brojnog, koji se ne da izbrojiti ni popisati.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 3, 9, 'Podaj svome sluzi pronicavo srce da može suditi tvom narodu, razlikovati dobro od zla, jer tko bi mogao upravljati tvojim narodom koji je tako velik!\"');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 3, 10, 'Bijaše milo Jahvi što je Salomon to zamolio.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 3, 11, 'Zato mu Jahve reče: \"Jer si to tražio, a nisi iskao ni duga života, ni bogatstva, ni smrti svojih neprijatelja, nego pronicavost u prosuđivanju pravice,');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 3, 12, 'evo ću učiniti po riječima tvojim: dajem ti srce mudro i razumno, kakvo nije imao nitko prije tebe niti će ga imati itko poslije tebe,');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 3, 13, 'ali ti dajem i što nisi tražio: bogatstvo i slavu kakve nema nitko među kraljevima.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 3, 14, 'I ako budeš stupao mojim putovima i budeš se držao mojih zakona i zapovijedi, kao što je činio tvoj otac David, umnožit ću tvoje dane.\"');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 3, 15, 'Salomon se probudi, i gle: bijaše to san. On se vrati u Jeruzalem i stade pred Kovčeg saveza Jahvina; prinese paljenice i žrtve pričesnice i priredi gozbu svim slugama svojim.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 3, 16, 'Tada dođoše dvije bludnice kralju i stadoše preda nj.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 3, 17, 'I reče jedna žena: \"Dopusti, gospodaru moj! Ja i ova žena u istoj kući živimo i ja sam rodila kraj nje u kući.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 3, 18, 'A trećega dana poslije moga porođaja rodi i ova žena. Bile smo zajedno i nikoga stranog s nama; samo nas dvije u kući.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 3, 19, 'Jedne noći umrije sin ove žene jer bijaše legla na njega.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 3, 20, 'I ustade ona usred noći, uze moga sina o boku mojem, dok je tvoja sluškinja spavala, i stavi ga sebi u naručje, a svoga mrtvog sina stavi kraj mene.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 3, 21, 'A kad ujutro ustadoh da podojim svoga sina, gle: on mrtav! I kad sam pažljivije pogledala, razabrah: nije to moj sin koga sam ja rodila!\"');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 3, 22, 'Tada reče druga žena: \"Ne, nije tako. Moj je sin onaj živi, a tvoj je onaj koji je mrtav!\" A prva joj odvrati: \"Nije istina! Tvoj je sin onaj koji je mrtav, a moj je onaj koji živi!\" I tako se prepirahu pred kraljem.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 3, 23, 'A kralj onda progovori: \"Ova kaže: \'Ovaj živi moj je sin, a onaj mrtvi tvoj\'; druga pak kaže: \'Nije, nego je tvoj sin mrtav, a moj je onaj živi.\'');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 3, 24, 'Donesite mi mač!\" naredi kralj. I donesoše mač pred kralja,');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 3, 25, 'a on reče: \"Rasijecite živo dijete nadvoje i dajte polovinu jednoj, a polovinu drugoj.\"');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 3, 26, 'Tada ženu, majku živog djeteta, zabolje srce za sinom i povika ona kralju: \"Ah, gospodaru! Neka se njoj dade dijete, samo ga nemojte ubijati!\" A ona druga govoraše: \"Neka ne bude ni meni ni tebi: rasijecite ga!\"');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 3, 27, 'Onda progovori kralj i reče: \"Dajte dijete prvoj, nipošto ga ne ubijajte! Ona mu je majka.\"');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 3, 28, 'Sav je Izrael čuo presudu koju je izrekao kralj i poštovali su kralja, jer su vidjeli da je u njemu božanska mudrost u izricanju pravde.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 4, 1, 'Kralj Salomon bio je kralj nad svim Izraelom,');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 4, 2, 'a evo njegovih odličnika: Azarja, sin Sadokov, svećenik;');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 4, 3, 'Elihoref i Ahija, sinovi Šišini, bilježnici; Jošafat, sin Ahiludov, savjetnik;');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 4, 4, 'Benaja, sin Jojadin, vojskovođa; Sadok i Ebjatar, svećenici.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 4, 5, 'Azarja, sin Natanov, bio je nad namjesnicima; Zabud, sin Natanov, prijatelj kraljev;');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 4, 6, 'Ahišar, upravitelj dvora; Eliab, sin Joabov, zapovjednik vojske; Adoram, sin Abdin, nadstojnik za tlaku.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 4, 7, 'Salomon je imao po svem Izraelu dvanaest namjesnika koji su opskrbljivali kralja i njegov dom; za svakoga je dolazio red da po jedan mjesec u godini podmiruje to uzdržavanje.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 4, 8, 'Evo njihovih imena:...sin Hurov, u gori Efrajimovoj;');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 4, 9, '...sin Dekerov, u Makasu, Šaalbimu, Bet Šemešu, Elonu do Bet Hanana;');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 4, 10, '...sin Hesedov, u Arubotu; pod njim bijaše Soho i sav kraj heferski;');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 4, 11, '...sin Abinadabov, nad svim okružjem dorskim; žena mu je bila Tafata, kći Salomonova;');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 4, 12, 'Baana, sin Ahiludov, u Tanaku i Megidu i u svem Bet Šeanu, koji je pokraj Saretana niže Jizreela, od Bet Šeana do Abel Mekole, i preko Jokmeama.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 4, 13, '...sin Geberov, u Ramotu Gileadskom; njegova su bila Sela Jaira, sina Manašeova, koja su u Gileadu; imao je i područje Argob koje leži u Bašanu, šezdeset tvrdih gradova, opasanih zidovima i prijevornicama od tuča;');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 4, 14, 'Ahinabad, sin Idov, u Mahanajimu;');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 4, 15, 'Ahimaas u Naftaliju; i on se oženio jednom Salomonovom kćeri - Bosmatom.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 4, 16, 'Baana, sin Hušajev, u Ašeru i na visoravnima;');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 4, 17, 'Jošafat, sin Paruahov, u Jisakaru;');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 4, 18, 'Šimej, sin Elin, u Benjaminu;');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 4, 19, 'Geber, sin Urijin, u zemlji Gileadu, zemlji Sihona, kralja amorejskoga, i Oga, kralja bašanskoga. Povrh toga bio je još jedan namjesnik u zemlji.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 4, 20, 'Juda i Izrael bili su mnogobrojni, bijaše ih kao pijeska na obali morskoj. Jeli su i pili i bili sretni.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 5, 1, 'Salomon je proširio svoju vlast nad svim kraljevstvima od Rijeke sve do zemlje filistejske i do međe egipatske. Ona su donosila svoj danak i služila Salomonu sve dane njegova života.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 5, 2, 'Svakoga je dana trebalo Salomonu za hranu: trideset kora finoga brašna i šezdeset kora običnog brašna,');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 5, 3, 'deset ugojenih volova, dvadeset volova s paše, stotinu ovaca, osim jelena, srna, divokoza i ugojene peradi.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 5, 4, 'Jer on je vladao nad svime onkraj Rijeke - od Tafse do Gaze, nad svim kraljevima s onu stranu Eufrata - i imao je mir po svim granicama naokolo.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 5, 5, 'Juda i sav Izrael živjeli su bez straha, svaki pod svojom lozom i pod svojom smokvom, od Dana sve do Beer Šebe, svega vijeka Salomonova.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 5, 6, 'Salomon je imao četrdeset tisuća konja za vuču i dvanaest tisuća za jahanje.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 5, 7, 'Ti su se namjesnici brinuli o opskrbi kralja Salomona i sviju koji su imali dijela za kraljevim stolom, svaki po mjesec dana; i nisu dopuštali da ičega ponestane.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 5, 8, 'I ječam i slamu za konje i tegleću marvu donosili su na mjesto gdje se zadržavao, svaki kako bi ga zapalo.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 5, 9, 'Jahve je dao Salomonu mudrost i izuzetnu razboritost i srce široko kao pijesak na obali morskoj.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 5, 10, 'Mudrost je Salomonova bila veća od mudrosti svih sinova Istoka i od sve mudrosti Egipta.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 5, 11, 'Bio je mudriji od svih ljudi, od Etana Ezrahanina, od Hemana, Kalkola i Darde, sinova Maholovih; njegovo se ime pronosilo među svim narodima unaokolo.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 5, 12, 'Izrekao je tri tisuće mudrih izreka, a njegovih je pjesama bilo tisuću i pet.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 5, 13, 'Zborio je o drveću: od cedra što je na Libanonu pa do izopa što klija na zidu; raspravljao je o životinjama, o pticama, o gmazovima i o ribama.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 5, 14, 'Dolazili su od sviju naroda da čuju mudrost Salomonovu, od svih zemaljskih kraljeva koji su čuli glas o njegovoj mudrosti.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 5, 15, 'Tirski kralj Hiram posla svoje sluge Salomonu, jer bijaše čuo da su ga pomazali za kralja na mjesto njegova oca, a Hiram je svagda bio prijatelj Davidov.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 5, 16, 'Tada Salomon poruči Hiramu:');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 5, 17, '\"Ti znaš dobro da moj otac David nije mogao sagraditi Doma imenu Jahve, svoga Boga, zbog ratova kojima su ga okružili neprijatelji sa svih strana, sve dok ih Jahve nije položio pod stopala nogu njegovih.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 5, 18, 'Sada mi je Jahve, Bog moj, dao mir posvuda unaokolo: nemam neprijatelja ni zlih udesa.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 5, 19, 'Namjeravam, dakle, sagraditi Dom imenu Jahve, Boga svoga, kako je Jahve rekao mome ocu Davidu: \'Tvoj sin koga ću mjesto tebe postaviti na tvoje prijestolje, on će sagraditi Dom mome Imenu.\'');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 5, 20, 'Stoga sada zapovjedi da mi nasijeku cedrova na Libanonu; moje će sluge biti sa slugama tvojim, i ja ću platiti nadnicu tvojim slugama prema svemu kako mi odrediš. Ti znaš dobro da u nas nema ljudi koji umiju sjeći drva kao Sidonci.\"');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 5, 21, 'Kada je Hiram primio Salomonovu poruku, veoma se obradova i reče: \"Neka je blagoslovljen danas Jahve koji je dao mudra sina Davidu, koji upravlja ovim velikim narodom.\"');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 5, 22, 'I Hiram javi Salomonu: \"Primio sam tvoju poruku. Ispunit ću u svemu tvoju želju glede drva cedrova i drva čempresova.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 5, 23, 'Moje će ih sluge dopremiti s Libanona na more, složit ću ih u splavi i pustiti ih morem do mjesta koje ćeš mi označiti; ondje ću ih razložiti i ti ćeš ih uzeti. Ti ćeš pak ispuniti moju želju i dati hranu mojoj čeljadi.\"');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 5, 24, 'Hiram je davao Salomonu drva cedrova i čempresova koliko je htio,');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 5, 25, 'a Salomon je davao Hiramu dvadeset tisuća kora pšenice za hranu ljudstvu, i dvadeset tisuća kora ulja od tiještenih maslina. Toliko je Salomon davao Hiramu godinu za godinom.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 5, 26, 'Jahve je dao mudrost Salomonu, kako mu bijaše obećao; između Hirama i Salomona vladao je mir te oni sklopiše savez.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 5, 27, 'Tada diže kralj Salomon kulučare iz svega Izraela; kulučara je bilo u svemu trideset tisuća ljudi.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 5, 28, 'Slao ih je naizmjence na Libanon, svakog mjeseca deset tisuća ljudi: bili su mjesec dana na Libanonu, a dva mjeseca kod kuće. Adoniram je bio nad svim kulučarima.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 5, 29, 'Salomon je imao i sedamdeset tisuća nosača tereta, osamdeset tisuća kamenorezaca u gori,');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 5, 30, 'ne računajući glavara službeničkih koji su upravljali poslovima; njih je bilo tri tisuće i tri stotine, a upravljali su narodom zaposlenim na radovima.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 5, 31, 'Kralj je zapovjedio da lome gromade biranog kamena i da ih klešu za temelje Hrama.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 5, 32, 'Graditelji Salomonovi i Hiramovi, i oni iz Gibela, tesali su i pripremali drvo i klesali za gradnju Hrama.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 6, 1, 'Četiri stotine i osamdesete godine poslije izlaska Izraelaca iz zemlje egipatske, četvrte godine kraljevanja svoga nad Izraelom, mjeseca Ziva - to je drugi mjesec - počeo je Salomon graditi Dom Jahvin.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 6, 2, 'Hram što ga je kralj Salomon gradio Jahvi bio je dug šezdeset lakata, širok dvadeset, a visok dvadeset i pet lakata.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 6, 3, 'Trijem pred Hekalom Hrama bio je dvadeset lakata dug, prema širini Hrama, a deset lakata širok, prema dužini Hrama.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 6, 4, 'Na Hramu je napravio prozore zatvorene rešetkama.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 6, 5, 'Uza zid Hrama oko Hekala i Debira sagradio je prigradnju na katove, sve unaokolo.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 6, 6, 'Donji kat bio je pet lakata širok, srednji šest, a treći sedam lakata, jer je zasjeke rasporedio s vanjske strane naokolo Hrama da ih ne bi morao ugrađivati u hramske zidove.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 6, 7, 'Hram je građen od kamena koji je već u kamenolomu bio oklesan, tako da se za gradnje nije čuo ni čekić ni dlijeto, ni ikakvo željezno oruđe.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 6, 8, 'Ulaz u donji kat bio je s desne strane Hrama, a zavojnim se stubama uspinjalo na srednji kat i sa srednjega na treći.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 6, 9, 'Sagradio je tako Hram i dovršio ga; i pokrio ga cedrovim gredama i daskama.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 6, 10, 'I sagradi još prigradnju oko cijeloga Hrama; bila je pet lakata visoka, a vezana s Hramom cedrovim gredama.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 6, 11, 'I riječ Jahvina stiže Salomonu:');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 6, 12, '\"To je Dom što ga gradiš... Ako budeš hodio prema naredbama mojim, ako budeš vršio naredbe moje i držao se mojih zapovijedi, tada ću ispuniti tebi obećanje što sam ga dao tvome ocu Davidu:');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 6, 13, 'prebivat ću među sinovima Izraelovim i neću ostaviti naroda svoga Izraela.\"');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 6, 14, 'I tako Salomon sazida Hram i dovrši ga.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 6, 15, 'I obloži iznutra zidove Hrama cedrovim daskama - od poda do stropa obloži ih drvetom iznutra - a daskama čempresovim obloži pod Hrama.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 6, 16, 'I načini pregradu od dvadeset lakata, od cedrovih dasaka, s poda pod strop, i odijeli taj dio Hrama za Debir, za Svetinju nad svetinjama.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 6, 17, 'A Hekal - Svetište, dio Hrama ispred Debira - imaše četrdeset lakata.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 6, 18, 'A po cedrovini unutar Hrama bijahu urezani ukrasi - pleteri od pupoljaka i cvijeća; sve je bilo od cedrovine i nigdje se nije vidio kamen.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 6, 19, 'Debir je uredio unutra u Hramu da onamo smjesti Kovčeg saveza Jahvina.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 6, 20, 'Debir bijaše dvadeset lakata dug, dvadeset lakata širok i dvadeset lakata visok, a obložio ga je čistim zlatom. Napravio je i Žrtvenik od cedrovine,');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 6, 21, 'pred Debirom, i obložio ga čistim zlatom.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 6, 22, 'I sav je Hram obložio zlatom, sav Hram i sav oltar koji je pred Debirom obložio je zlatom.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 6, 23, 'U Debiru načini dva kerubina od maslinova drveta. Bili su visoki deset lakata.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 6, 24, 'Jedno je krilo u kerubina bilo pet lakata i drugo je krilo u kerubina bilo pet lakata; deset je lakata bilo od jednoga kraja krila do drugoga.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 6, 25, 'I drugi je kerubin bio od deset lakata: jednaka mjera i jednak oblik obaju kerubina.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 6, 26, 'Visina jednog kerubina bila je deset lakata, tako i drugoga.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 6, 27, 'Smjestio je kerubine usred nutarnje prostorije; širili su svoja krila, tako da je krilo jednoga ticalo jedan zid, a krilo drugoga ticalo drugi zid; u sredini prostorije krila im se doticahu.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 6, 28, 'I kerubine je obložio zlatom.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 6, 29, 'Po svim zidovima Hrama unaokolo, iznutra i izvana, urezao je likove kerubina, palma i rastvorenih cvjetova,');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 6, 30, 'zlatom je pokrio i pod Hramu iznutra i izvana.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 6, 31, 'A za ulaz u Debir načini dvokrilna vrata od maslinova drveta; dovraci s pragom bijahu na pet uglova.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 6, 32, 'Oba krila na vratima od maslinova drveta ukrasi likovima kerubina, palma i rastvorenih cvjetova, i sve ih obloži zlatom; listićima zlata oblijepi kerubine i palme.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 6, 33, 'Tako i za ulaz u Hekal načini vrata od maslinova drveta, sa četverokutnim dovracima.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 6, 34, 'Oba krila na vratima bijahu od čempresova drveta i oba se otvarahu na jednu i na drugu stranu.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 6, 35, 'Urezao je na njima kerubine, palme i rastvorene cvjetove i obložio zlatom sve što bijaše urezano.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 6, 36, 'Potom je sagradio unutrašnje predvorje od tri reda klesanog kamena i jednoga reda tesanih greda cedrovih.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 6, 37, 'Temelji su Hramu Jahvinu bili položeni četvrte godine, mjeseca Ziva;');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 6, 38, 'a jedanaeste godine, mjeseca Bula - to je osmi mjesec - Hram je dovršen sa svim dijelovima i sa svim što mu pripada. Salomon ga sagradi za sedam godina.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 7, 1, 'Salomon je sagradio i svoj dvor; u trinaest ga je godina potpuno dovršio.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 7, 2, 'Sagradio je dvor od libanonske šume: stotinu lakata dug, pedeset širok i trideset lakata visok, na četiri reda cedrovih stupova, a na stupovima bijahu cedrove grede.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 7, 3, 'Bio je pokriven cedrovinom iznad soba koje su počivale na stupovima. Ovih je bilo četrdeset i pet: petnaest u svakom redu.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 7, 4, 'Bila su tri reda prozora: po tri su prozora gledala jedan prema drugome.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 7, 5, 'Sva vrata s dovratnicima bila su četverokutna i po tri su prozora stajala jedan prema drugome.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 7, 6, 'Načinio je trijem od stupova, pedeset lakata dug i trideset širok.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 7, 7, 'Zatim je sagradio prijestolni trijem gdje je sudio; i sudački trijem, obložen cedrovinom od poda do stropa.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 7, 8, 'Njegovo prebivalište, u drugom dvorištu i unutar predvorja, bilo je istoga oblika. Sagradio je i kuću, nalik na onaj trijem, faraonovoj kćeri, kojom se bijaše oženio.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 7, 9, 'Sve su te građevine bile od biranog kamena, sječena po mjeri, a klesana iznutra i izvana, od temelja sve do drvenih spojnica, a vani sve do velikog predvorja.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 7, 10, 'Temelji su im bili od birana, velikog kamena: od deset i od osam lakata,');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 7, 11, 'a nadgradnja od birana, po mjeri klesana kamena i od cedrovine.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 7, 12, 'A tri su reda klesanog kamena i red cedrovih greda okruživali veliko predvorje, a tako i unutrašnje predvorje Doma Jahvina.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 7, 13, 'Salomon posla po Hirama iz Tira.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 7, 14, 'Bio je to sin udovice iz plemena Naftalijeva, ali mu otac bijaše iz Tira, kovač tuča. Bio je pun vještine, umijeća i znanja da svašta izrađuje od tuča. Dođe on kralju Salomonu i sav mu posao izradi.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 7, 15, 'Salio je dva stupa od tuča; jedan je stup bio visok osamnaest lakata, a koncem mjeren unaokolo imao je dvanaest lakata, isto tako i drugi.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 7, 16, 'I načini dvije glavice od tuča da se stave povrh stupova; jedna je glavica bila visoka pet lakata i druga je bila pet lakata visoka.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 7, 17, 'Načini dva opleta u obliku pletera i lančaste žice da pokriju glavice na vrhu stupova; sedam za jednu glavicu i sedam za drugu.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 7, 18, 'Onda izradi mogranje: bili su u dva reda oko svake mreže.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 7, 19, 'Glavice na vrhu stupova pred trijemom imale su oblik ljiljana, od četiri lakta.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 7, 20, 'Stajale su na oba stupa kod izbočine što je bila prema lančancu. Dvije stotine mogranja bilo je oko prve glavice i dvije stotine oko druge.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 7, 21, 'Podiže stupove pred trijemom Hekala; jedan postavi na desnu stranu i nazva ga Jahin; postavi drugi stup na lijevu stranu i dade mu ime Boaz.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 7, 22, 'Na samom vrhu stupova postavi izrađene ljiljane. I tako dovrši stupove.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 7, 23, 'Tada od rastaljene kovine izli more koje je od ruba do ruba mjerilo deset lakata; bilo je okruglo naokolo, pet lakata visoko, a u opsegu, mjereno vrpcom, imalo je trideset lakata.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 7, 24, 'Pod rubom mu bijahu uresi kao cvjetne čaške koje su ga optakale sasvim: po deset na lakat optakale su more unaokolo; cvjetne su čaške bile u dva reda i salivene s njim.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 7, 25, 'Počivalo je na dvanaest volova: tri su gledala na sjever, tri na zapad, tri na jug, a tri na istok; more je stajalo na njima i svi su stražnjim dijelom bili okrenuti unutra.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 7, 26, 'Bilo je debelo pedalj, rub mu kao rub u čaše, kao cvijet, a moglo je primiti tri tisuće bata.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 7, 27, 'Načinio je deset tučanih podnožja; svako je podnožje bilo četiri lakta dugo, četiri lakta široko, a tri lakta visoko.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 7, 28, 'Podnožja su bila ovako izrađena: imala su okvire, a okviri su stajali među preponama.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 7, 29, 'Na okvirima među preponama bili su lavovi, volovi i kerubini; a na samim preponama, kako iznad lavova i volova tako i pod njima, bijahu ukrasi poput vijenaca.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 7, 30, 'Svako je podnožje imalo četiri tučana točka i osovine od tuča; četiri su njihove noge imale držače; pod umivaonikom bijahu držači sliveni s ukrasima.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 7, 31, 'Gore, gdje su se držači sastavljali, bio je otvor podnožja; imao je lakat i pol; otvor je bio okrugao, u obliku ukrasne posude, a na njemu su bili uklesani i ukrasi; ali prepone bijahu četvrtaste, a ne okrugle.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 7, 32, 'Četiri su točka bila pod preponom. Osovine im izlazile na podnožju; svaki točak bijaše visok lakat i pol.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 7, 33, 'Točkovi su bili slični točkovima običnih kola: njihove osovine, naplaci, paoci i glavčine - sve bijaše liveno.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 7, 34, 'Bila su četiri držača na četiri ugla svakog podnožja; podnožje i držači sačinjavahu jednu cjelinu.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 7, 35, 'Pri vrhu podnožja bio je sve unaokolo krug visok pol lakta; povrh podnožja bili su klinovi; prepone su s njima sačinjavale cjelinu.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 7, 36, 'Po oplošjima klinova i prepona urezao je kerube, lavove i palme, već prema veličini praznog oplošja i vijenaca naokolo.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 7, 37, 'Tako načini deset podnožja: jednako salivenih, jednake veličine i oblika.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 7, 38, 'I načini deset umivaonika od tuča. Svaki je umivaonik sadržavao četrdeset bata, a svaki je umivaonik bio od četiri lakta; na svako od deset podnožja došao je po jedan umivaonik.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 7, 39, 'Postavi pet podnožja na desnoj strani Hrama, a pet na lijevoj strani Hrama; a more stavi s desne strane Hrama, prema jugoistoku.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 7, 40, 'Hiram načini lonce, lopate i kotliće. Dovrši on sav posao što ga je obavljao kralju Salomonu za Dom Jahvin:');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 7, 41, 'dva stupa, okrugle glavice što su bile navrh stupova; dva opleta da pokriju dvije glavice što bijahu navrh stupova;');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 7, 42, 'četiri stotine mogranja za oba opleta; dva reda mogranja za svaki oplet da prekriju dvije glavice navrh stupova;');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 7, 43, 'deset podnožja i deset umivaonika na podnožjima;');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 7, 44, 'jedno more i dvanaest volova pod njim;');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 7, 45, 'lonce, lopate i kotliće. Svi ti predmeti koje je Hiram načinio kralju Salomonu za Dom Jahvin bili su od sjajnog tuča.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 7, 46, 'Kralj je zapovjedio da sve to lijevaju u kalupima od gline, u Jordanskoj dolini, između Sukota i Sartana.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 7, 47, 'Na koncu je Salomon odredio da rasporede sve te predmete, a bijaše ih toliko da se nije mogla obračunati težina tuča.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 7, 48, 'Salomon načini sve predmete koji su bili u Domu Jahvinu: zlatni žrtvenik i zlatni stol na kojemu su stajali prineseni hljebovi;');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 7, 49, 'pet svijećnjaka s desne i pet s lijeve strane pred Debirom, od čistoga zlata; cvjetove, svjetiljke, usekače od zlata;');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 7, 50, 'vrčeve, noževe, kotliće, plitice i kadionice od čistoga zlata; stožere za vrata nutarnje dvorane - to je Svetinja nad svetinjama - i za vrata Hekala - to jest Hrama - sve od zlata.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 7, 51, 'Tako bi priveden kraju sav posao što ga Salomon obavi za Dom Jahvin. Salomon unese sve svete darove oca svoga Davida - srebro, zlato i posuđe - i stavi ih u riznicu Doma Jahvina.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 8, 1, 'Tada Salomon sazva u Jeruzalem sve starješine Izraelove, sve knezove plemenske i glavare obitelji da se prenese Kovčeg saveza Jahvina iz grada, Davidova grada, to jest sa Siona.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 8, 2, 'Svi se ljudi Izraelovi sabraše pred kraljem Salomonom na blagdan u mjesecu Etanimu (to je sedmi mjesec).');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 8, 3, 'I kad su došle Izraelove starješine, svećenici ponesoše Kovčeg');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 8, 4, 'i Šator sastanka sa svim posvećenim priborom što bješe u Šatoru. Prenosili su ih svećenici i leviti.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 8, 5, 'Kralj Salomon i sva zajednica Izraelova koja se sabrala oko njega žrtvovali su pred Kovčegom toliko ovaca i goveda da se ne mogahu prebrojiti ni procijeniti.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 8, 6, 'Svećenici donesoše Kovčeg saveza Jahvina na njegovo mjesto, u Debir Doma, to jest u Svetinju nad svetinjama, pod krila kerubina.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 8, 7, 'Kerubini su, naime, imali raširena krila nad mjestom gdje stajaše Kovčeg i zaklanjahu odozgo Kovčeg i njegove motke.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 8, 8, '[8a] Motke su bile tako dugačke da su im se krajevi vidjeli iz Svetišta nasuprot Debiru, ali se nisu vidjele izvana.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 8, 9, 'U Kovčegu nije bilo ništa, osim dviju kamenih ploča koje metnu Mojsije na Horebu, gdje Jahve sklopi Savez s Izraelcima pošto iziđoše iz Egipta. [8b] Ondje su ostale do danas.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 8, 10, 'A kad su svećenici izašli iz Svetišta, oblak ispuni Dom Jahvin,');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 8, 11, 'i svećenici ne mogoše od oblaka nastaviti službe: slava Jahvina ispuni Dom Božji!');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 8, 12, 'Tada reče Salomon: \"Jahve odluči prebivati u tmastu oblaku,');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 8, 13, 'a ja ti sagradih uzvišen Dom da u njemu prebivaš zauvijek.\"');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 8, 14, 'I, okrenuvši se, kralj blagoslovi sav izraelski zbor, a sav je izraelski zbor stajao.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 8, 15, 'Reče on: \"Neka je blagoslovljen Jahve, Bog Izraelov, koji je svojom rukom ispunio obećanje što ga na svoja usta dade ocu mome Davidu, rekavši:');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 8, 16, '\'Od dana kad izvedoh svoj narod iz zemlje egipatske, nisam izabrao grada ni iz kojega Izraelova plemena da se u njemu sagradi Dom gdje bi prebivalo moje Ime, nego sam izabrao Davida da on zapovijeda mojim narodom Izraelom.\'');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 8, 17, 'Otac mi David naumi podići Dom Imenu Jahve, Boga Izraelova,');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 8, 18, 'ali mu Jahve reče: \'Naumio si podići Dom mojem Imenu, i dobro učini,');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 8, 19, 'ali nećeš ti podići toga Doma, nego sin tvoj koji izađe iz tvoga krila, on će podići Dom mojem Imenu.\'');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 8, 20, 'Jahve ispuni obećanje svoje: naslijedio sam svoga oca Davida i sjeo na prijestolje Izraelovo, kako obeća Jahve, i podigao Dom Imenu Jahve, Boga Izraelova,');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 8, 21, 'i odredio sam da ondje bude mjesto Kovčegu u kojem je Savez što ga Jahve sklopi s našim ocima kad ih je izveo iz zemlje egipatske.\"');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 8, 22, 'Tada Salomon stupi, u nazočnosti svega zbora Izraelova, pred žrtvenik Jahvin, raširi ruke prema nebu');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 8, 23, 'i reče: \"Jahve, Bože Izraelov! Nijedan ti bog nije sličan ni na nebesima ni dolje na zemlji, tebi koji držiš Savez i ljubav svojim slugama što kroče pred tobom sa svim svojim srcem.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 8, 24, 'Sluzi svome Davidu, mome ocu, ti si ispunio što si mu obećao. Što si obećao na svoja usta, ispunio si svojom rukom upravo danas.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 8, 25, 'Sada, Jahve, Bože Izraelov, ispuni svome sluzi, ocu mome Davidu, što si obećao kad si rekao: \'Neće ti preda mnom nestati nasljednika koji bi sjedio na izraelskom prijestolju, samo ako tvoji sinovi budu čuvali svoje putove hodeći po mojem zakonu kako si ti hodio preda mnom.\'');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 8, 26, 'Sada, dakle, Jahve, Bože Izraelov, neka se ispuni tvoje obećanje koje si dao svome sluzi Davidu, mome ocu!');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 8, 27, 'Ali zar će Bog doista boraviti s ljudima na zemlji? TÓa nebesa ni nebesa nad nebesima ne mogu ga obuhvatiti, a kamoli ovaj Dom što sam ga sagradio!');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 8, 28, 'Pomno počuj molitvu i vapaj svoga sluge, Jahve, Bože moj, te usliši vapaj i molitvu što je tvoj sluga tebi upućuje!');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 8, 29, 'Neka tvoje oči obdan i obnoć budu otvorene nad ovim Domom, nad ovim mjestom za koje reče: \'Tu će biti moje Ime.\' Usliši molitvu koju će sluga tvoj izmoliti na ovome mjestu.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 8, 30, 'I usliši molitvu sluge svoga i naroda svojega izraelskog koju bude upravljao prema ovome mjestu. Usliši s mjesta gdje prebivaš, s nebesa; usliši i oprosti.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 8, 31, 'Ako tko zgriješi protiv bližnjega i naredi mu se da se zakune, a zakletva dođe pred tvoj žrtvenik u ovom Domu,');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 8, 32, 'tada je ti čuj u nebu i postupaj i sudi svojim slugama, osudi krivca okrećući njegova djela na njegovu glavu, a nevina oslobodi postupajući s njime po nevinosti njegovoj.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 8, 33, 'Ako narod tvoj bude potučen od neprijatelja jer se ogriješio o tebe, ali se ipak k tebi obrati i proslavi Ime tvoje i u ovom se Domu pomoli,');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 8, 34, 'onda ti čuj to s neba, oprosti grijehe svome narodu izraelskom i dovedi ga natrag u zemlju koju si dao njihovim očevima.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 8, 35, 'Kad se zatvori nebo i ne padne kiša jer su se ogriješili o tebe, pa ti se pomole na ovome mjestu i proslave Ime tvoje i obrate se od svojega grijeha kad ih ti poniziš,');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 8, 36, 'tada ti čuj na nebu i oprosti grijeh svojim slugama i svojem izraelskom narodu, pokazujući im valjan put kojim će ići, i pusti kišu na zemlju koju si svojem narodu dao u baštinu.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 8, 37, 'Kad u zemlji zavlada glad, kuga, snijet i rđa i kad navale skakavci, gusjenice, kad neprijatelj ovoga naroda pritisne koja od njegovih vrata, ili kad bude kakva druga nevolja ili boleština,');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 8, 38, 'ako koji čovjek, ili sav tvoj narod, Izrael, osjeti tjeskobu svoga srca pa upravi molitvu ili prošnju te raširi ruke prema ovom Hramu,');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 8, 39, 'ti čuj s neba, s mjesta gdje prebivaš, i oprosti i postupi; vrati svakome čovjeku prema putu njegovu, jer ti poznaješ srce njegovo - ti jedini poznaješ srce sviju -');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 8, 40, 'da te se uvijek boje sve dane dokle žive na zemlji što je ti dade našim očevima.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 8, 41, 'Pa i tuđinca, koji nije od tvojega naroda izraelskog, nego je stigao iz daleke zemlje radi Imena tvoga');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 8, 42, 'jer je čuo za veliko Ime tvoje, za tvoju snažnu ruku i za tvoju mišicu podignutu - ako dođe i pomoli se u ovom Hramu,');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 8, 43, 'usliši ga s neba gdje prebivaš, usliši sve vapaje njegove da bi upoznali svi zemaljski narodi Ime tvoje i bojali se tebe kao narod tvoj Izrael i da znaju da je tvoje Ime zazvano nad ovaj Dom koji sam sagradio.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 8, 44, 'Ako narod tvoj krene na neprijatelja putem kojim ga ti uputiš i pomoli se Jahvi, okrenut k ovom gradu što si ga izabrao i prema Domu koji sam podigao tvojem Imenu,');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 8, 45, 'usliši mu s neba molitvu i prošnju i učini mu pravdu.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 8, 46, 'Kad ti sagriješe, jer nema čovjeka koji ne griješi, a ti ih, rasrdiv se na njih, predaš neprijateljima da ih zarobe i odvedu kao roblje u daleku ili blizu zemlju,');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 8, 47, 'pa ako se pokaju srcem u zemlji u koju budu dovedeni te se obrate i počnu te moliti za milost u zemlji svojih osvajača govoreći: \'Zgriješili smo, bili smo zli i naopaki\',');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 8, 48, 'i tako se obrate k tebi svim srcem i svom dušom u zemlji svoga ropstva u koju budu dovedeni kao roblje, i pomole se okrenuti k zemlji što je ti dade njihovim očevima, i prema gradu koji si izabrao, i prema Domu što sam ga podigao tvom Imenu,');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 8, 49, 'usliši s neba, gdje prebivaš, njihovu molbu i njihove prošnje,');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 8, 50, 'učini im pravdu i oprosti svome narodu što je zgriješio protiv tebe, oprosti sve uvrede koje ti je nanio, učini da mu se smiluju osvajači i da budu milostivi prema njemu,');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 8, 51, 'jer su oni tvoj narod i baština tvoja, njih si izveo iz Egipta, iz užarenog kotla.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 8, 52, 'Neka oči tvoje budu otvorene na prošnju tvoga sluge i na prošnju naroda tvoga Izraela da čuješ sve njihove molbe što će ih tebi uputiti.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 8, 53, 'Jer ti si ih odvojio od svih naroda na zemlji sebi za baštinu, kako si objavio po svome sluzi Mojsiju, kada si izveo oce naše iz Egipta, o Gospode, Jahve!\"');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 8, 54, 'Pošto je Salomon dovršio svu ovu molitvu i prošnju pred Jahvom, diže se s mjesta gdje je klečao, raširenih ruku prema nebu, pred žrtvenikom Jahvinim,');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 8, 55, 'pa istupi te blagoslovi sav zbor Izraelov govoreći jakim glasom:');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 8, 56, '\"Blagoslovljen Jahve, koji je narodu svome Izraelu dao mir u svemu kako je obećao; nije propalo nijedno od njegovih lijepih obećanja koja je dao sluzi svome Mojsiju.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 8, 57, 'Neka Jahve, Bog naš, bude s nama kao što je bio s ocima našim i neka nas ne napusti i ne odbaci.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 8, 58, 'Neka prikloni naša srca k sebi da bismo hodili svim njegovim putovima i držali njegove zapovijedi, zakone i uredbe koje je dao ocima našim.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 8, 59, 'Bile ove moje riječi, koje sam smjerno iznio pred Jahvu, danju i noću nazočne pred Jahvom, Bogom našim, eda bi dan za danom činio pravdu sluzi svomu i pravicu narodu svome Izraelu,');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 8, 60, 'ne bi li tako svi narodi zemlje spoznali da je Jahve jedini Bog i da nema drugoga.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 8, 61, 'A vaše srce neka bude potpuno odano Jahvi, Bogu našemu, držeći se njegovih zakona i obdržavajući njegove zapovijedi kao danas!\"');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 8, 62, 'Kralj i sav Izrael s njim prinesu žrtvu Jahvi.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 8, 63, 'Kao žrtvu pričesnicu, koju je prikazao Jahvi, Salomon prinese dvadeset i dvije tisuće volova i stotinu i dvadeset tisuća ovaca; time kralj i svi Izraelci posvete Dom Jahvin.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 8, 64, 'Toga dana posveti kralj središte predvorja, koje je ispred Doma Jahvina, jer ondje je prinio paljenice, prinosnice i pretiline pričesnica, jer je tučani žrtvenik pred Jahvom bio premalen da primi paljenice, prinosnice, pretiline pričesnica.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 8, 65, 'Tu je svečanost u ono vrijeme Salomon slavio sedam dana, sa svim Izraelcima, zborom velikim od Ulaza u Hamat do Potoka Egipatskog, pred Jahvom, Bogom našim.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 8, 66, 'Zatim je osmoga dana otpustio ljude; oni su blagosivljali kralja i odlazili svojim kućama, veseli i zadovoljna srca zbog svega dobra što ga je Jahve učinio svome sluzi Davidu i narodu svome Izraelu.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 9, 1, 'Kad je Salomon dovršio gradnju Doma Jahvina, kraljevskog dvora i svega što je namislio graditi,');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 9, 2, 'javi se Jahve i drugi put Salomonu, kao što mu se bio javio u Gibeonu.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 9, 3, 'Jahve mu reče: \"Uslišio sam molitvu i prošnju koju si mi uputio. Posvetio sam ovaj Dom, koji si sagradio da u njemu prebiva Ime moje dovijeka; moje će oči i srce biti ovdje svagda.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 9, 4, 'A ti, ako budeš hodio preda mnom kako je hodio tvoj otac David, u nevinosti srca i pravednosti, postupao u svemu kako sam ti zapovjedio i ako budeš držao moje zakone i moje naredbe,');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 9, 5, 'ja ću učvrstiti zauvijek tvoje kraljevsko prijestolje nad Izraelom, kako sam obećao tvome ocu Davidu kad sam rekao: \'Nikada ti neće nestati nasljednika na prijestolju Izraelovu.\'');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 9, 6, 'Ali ako me ostavite, vi i vaši sinovi, ako ne budete držali mojih zapovijedi i zakona koje sam vam dao, ako se okrenete bogovima i budete im služili i klanjali im se,');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 9, 7, 'tada ću istrijebiti Izraela iz zemlje koju sam mu dao; ovaj ću Dom, koji sam posvetio svome Imenu, odbaciti od sebe, i Izrael će biti poruga i podsmijeh svim narodima.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 9, 8, 'Ovaj je Dom uzvišen, ali svi koji budu uza nj prolazili bit će zaprepašteni; zviždat će i govoriti: \'Zašto je Jahve tako učinio s ovom zemljom i s ovim Domom?\'');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 9, 9, 'A reći će im se: \'Jer su ostavili Jahvu, Boga svoga, koji je izveo oce njihove iz Egipta, a priklonili se drugim bogovima, častili ih i služili im, zato je Jahve pustio na njih sva ova zla.\'\"');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 9, 10, 'Poslije dvadeset godina, za kojih je Salomon sagradio obje zgrade, Dom Jahvin i kraljevski dvor,');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 9, 11, 'a Hiram, kralj Tira, dobavljao mu drvo cedrovo i čempresovo i zlata koliko je god želio, dade tada kralj Salomon Hiramu dvadeset gradova u zemlji galilejskoj.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 9, 12, 'Hiram izađe iz Tira da vidi gradove koje mu je Salomon darovao, ali mu se nisu svidjeli.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 9, 13, 'I reče: \"Kakvi su to gradovi što si mi ih dao, brate?\" I od tada ih zovu \"zemlja Kabul\" do današnjega dana.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 9, 14, 'A Hiram bijaše poslao kralju stotinu i dvadeset zlatnih talenata.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 9, 15, 'Ovako je bilo s rabotom koju je kralj Salomon digao da sagradi Dom Jahvin, svoj dvor, Milo i zidove Jeruzalema, Hasor, Megido i Gezer.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 9, 16, 'Faraon, kralj Egipta, krenu u vojni pohod, osvoji Gezer, popali i poubija Kanaance koji su ondje živjeli, zatim dade grad u miraz svojoj kćeri, ženi Salomonovoj,');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 9, 17, 'a Salomon obnovi Gezer, Bet Horon Donji,');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 9, 18, 'Baalat, Tamar u pustinji u zemlji,');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 9, 19, 'sve gradove-skladišta koje je Salomon imao, gradove za bojna kola i gradove za konjicu, i sve što je Salomon želio sagraditi u Jeruzalemu, na Libanonu i u svim zemljama koje su mu bile podložne.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 9, 20, 'Svim preostalim Amorejcima, Hetitima, Perižanima, Hivijcima i Jebusejcima, koji nisu bili Izraelci,');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 9, 21, 'sinovima njihovim koji ostadoše iza njih u zemlji i koje Izraelci nisu zatrli, Salomon nametnu tešku tlaku do današnjega dana.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 9, 22, 'Sinove Izraelove nije Salomon pretvarao u robove, nego su mu oni bili vojnici, dvorani, vojskovođe, tridesetnici, zapovjednici njegovih bojnih kola i konjice.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 9, 23, 'A evo nadzornika koji su upravljali Salomonovim radovima: njih pet stotina i pedeset koji su zapovijedali puku zaposlenu na radovima.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 9, 24, 'Čim je faraonova kći ušla iz Davidova grada u kuću koju joj Salomon bijaše sagradio, tada on podiže Milo.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 9, 25, 'Salomon je tri puta u godini prinosio paljenice i pričesnice na žrtveniku koji je podigao Jahvi i palio je kad pred Jahvom. Tako je dovršio Hram.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 9, 26, 'Kralj Salomon je sagradio brodovlje u Esjon-Geberu, koji je kralj Elata, na obali Crvenoga mora, u zemlji edomskoj.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 9, 27, 'Hiram je poslao na tim lađama svoje sluge, mornare koji su poznavali more, sa slugama Salomonovim.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 9, 28, 'Oni otploviše u Ofir, uzeše odande četiri stotine i dvadeset talenata zlata i donesoše ih kralju Salomonu.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 10, 1, 'Glas koji je u Jahvinu Imenu stekao Salomon dopro je do kraljice od Sabe; zato ona dođe da Salomona iskuša zagonetkama.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 10, 2, 'Došla je u Jeruzalem s golemom pratnjom, s devama koje su nosile mirise, nebrojeno zlato i drago kamenje. Došavši k Salomonu, porazgovori se s njim o svemu što joj bijaše na srcu.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 10, 3, 'Salomon joj odgovori na sva pitanja; nije mu bilo skriveno ništa da joj ne bi umio objasniti.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 10, 4, 'Kad kraljica od Sabe vidje mudrost Salomonovu, dvor koji bijaše sagradio,');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 10, 5, 'jela na njegovu stolu, odaje njegove i dvorane, otmjenost njegove posluge i njihova odijela, njegove peharnike i paljenice koje je prinio u Domu Jahvinu, zastade joj dah.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 10, 6, 'Tada reče kralju: \"Istina je bila što sam u svojoj zemlji čula o tebi i o tvojoj mudrosti.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 10, 7, 'Ali nisam htjela vjerovati što se pripovijeda dokle god nisam došla i vidjela na svoje oči; i doista, ni pola mi nije bilo rečeno: ti nadvisuješ u mudrosti i blagostanju slavu o kojoj sam čula.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 10, 8, 'Blago tvojim ženama, blago ovim tvojim slugama koji su neprestano pred tobom i slušaju tvoju mudrost!');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 10, 9, 'Neka je blagoslovljen Jahve, Bog tvoj, komu si tako omilio da te postavio na prijestolje Izraelaca; zato što Jahve uvijek ljubi Izraela, postavio te kraljem da činiš pravo i pravicu.\"');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 10, 10, 'Dade tada kralju stotinu i dvadeset zlatnih talenata, mnogo miomirisa i dragulja. Nikad više nije bilo takvih miomirisa kakve je kraljica od Sabe dala kralju Salomonu.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 10, 11, 'Pa i Hiramovo brodovlje, koje je donosilo zlato iz Ofira, dovezlo je odande mnogo sandalovine i dragulja.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 10, 12, 'Kralj je od sandalovine napravio ograde za Dom Jahvin i za kraljevski dvor, i citre i harfe za pjevače; nikada se više nije dovezlo toliko sandalova drveta niti se vidjelo do danas.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 10, 13, 'Kralj Salomon dade kraljici od Sabe što je god zaželjela i zatražila, a povrh toga kraljevski je obdari. Potom ona krenu i sa slugama vrati se u svoju zemlju.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 10, 14, 'Zlato što je dolazilo Salomonu svake godine bilo je teško šest stotina šezdeset i šest zlatnih talenata,');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 10, 15, 'osim onoga što je dolazilo od trgovaca i prodavača-potukača i od svih arapskih kraljeva i upravitelja zemaljskih.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 10, 16, 'Kralj Salomon načini tri stotine velikih štitova od kovanog zlata; za svaki je štit upotrijebio šest stotina zlatnih šekela;');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 10, 17, 'i načini trista štitića od kovanog zlata; za svaki je štitić utrošio tri zlatne mine. Pohranio je sve u kuću zvanu Libanonska šuma.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 10, 18, 'Kralj je još napravio veliko prijestolje od bjelokosti i obložio ga čistim zlatom.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 10, 19, 'Prijestolje je imalo šest stepenica, straga je na njemu bila teleća glava, a s obje strane sjedala bile su ručice, a kraj ručica stajala dva lava.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 10, 20, 'Dvanaest je lavova stajalo s obje strane onih šest stepenica. Takvo što nije bilo izrađeno ni u jednom kraljevstvu.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 10, 21, 'Sve posude iz kojih je pio kralj Salomon bijahu zlatne, i sve posuđe u kući zvanoj Libanonska šuma bijaše od suhoga zlata; ništa nije bilo od srebra, jer se ono smatralo bezvrijednim u Salomonovo vrijeme.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 10, 22, 'Kralj je imao taršiško brodovlje na moru zajedno s Hiramovim brodovljem, i svake treće godine dolazilo je taršiško brodovlje donoseći zlato, srebro i slonovu kost, majmune i paune.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 10, 23, 'Tako je kralj Salomon natkrilio sve zemaljske kraljeve bogatstvom i mudrošću.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 10, 24, 'Sav je svijet želio vidjeti Salomona i čuti mudrost koju mu je Bog ulio u srce.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 10, 25, 'Svatko mu je donosio dar: srebro i zlatno posuđe, haljine, oružje, miomirise, konje i mazge, iz godine u godinu.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 10, 26, 'Uz to je Salomon sakupio bojnih kola i konjanika; imao je tisuću i četiri stotine bojnih kola i dvanaest tisuća konja i rasporedio ih je po gradovima bojnih kola i kod kralja u Jeruzalemu.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 10, 27, 'Salomon je učinio da u Jeruzalemu bude srebra kao kamenja, a cedrova kao divljih smokava što rastu u Šefeli.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 10, 28, 'Salomon je uvozio konje iz Musrija i Koe: kraljevi nabavljači uvozili su ih iz Koe za određenu svotu.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 10, 29, 'Kola se dovozila iz Egipta po šest stotina srebrnih šekela; a konj se plaćao po stotinu i pedeset. Tako ih preko nabavljača dobivahu svi kraljevi hetitski i aramejski.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 11, 1, 'Kralj je Salomon - uz kćer faraonovu - volio mnoge žene tuđinke: Moapke, Amonke, Edomke, Sidonke i Hetitkinje,');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 11, 2, 'od svih naroda za koje je Jahve rekao Izraelcima: \"Nećete odlaziti k njima i oni neće dolaziti k vama; oni će zacijelo okrenuti vaša srca svojim bogovima.\" Njima se priklonio Salomon svojom ljubavlju.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 11, 3, 'Imao je sedam stotina kneževskih žena i tri stotine inoča. Njegove su žene zavodile njegovo srce.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 11, 4, 'I kada je Salomon ostario, njegove su mu žene okrenule srce prema drugim bogovima, i srce njegovo nije više potpuno pripadalo Jahvi kao što je pripadalo srce njegova oca Davida.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 11, 5, 'Salomon je išao za Aštartom, boginjom Sidonaca, i Milkomom, sramotom Amonaca.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 11, 6, 'Činio je ono što ne bijaše pravo u očima Jahvinim i nije se sasvim pokoravao Jahvi kao što se pokoravao njegov otac David.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 11, 7, 'Tako sagradi Salomon uzvišicu Kemošu, sramoti Moaba, na gori istočno od Jeruzalema, i Milkomu, sramoti Amonaca.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 11, 8, 'To učini za sve svoje žene tuđinke, koje su prinosile kad i žrtve svojim bogovima.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 11, 9, 'Jahve se razgnjevi na Salomona jer je okrenuo srce svoje od Jahve, Boga Izraelova, koji mu se bio dvaput javio');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 11, 10, 'i koji mu je baš tada zabranio štovati druge bogove, ali on nije održao te zapovijedi.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 11, 11, 'Tada Jahve reče Salomonu: \"Kada je tako s tobom te ne držiš moga Saveza i naredaba koje sam ti dao, ja ću sigurno oduzeti od tebe kraljevstvo i dat ću ga jednom od tvojih slugu.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 11, 12, 'Ali neću to učiniti za tvoga života, zbog oca tvojega Davida; uzet ću ga iz ruke tvoga sina.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 11, 13, 'Ipak neću od njega uzeti svega kraljevstva: ostavit ću jedno pleme tvome sinu, zbog sluge mojega Davida, zbog Jeruzalema koji izabrah.\"');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 11, 14, 'Tada diže Jahve protivnika Salomonu: Edomca Hadada, iz kraljevske kuće Edomaca.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 11, 15, 'Jer kada je David tukao Edomce i kad je Joab, vojskovođa, otišao da pokopa ubijene i dao pogubiti sve muškarce u Edomu -');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 11, 16, 'Joab i sav Izrael ostadoše ondje šest mjeseci dok nisu istrijebili sve muškarce u Edomu -');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 11, 17, 'Hadad je utekao u Egipat s Edomcima koji bijahu u službi njegova oca. Hadad je bio tada mladi dječak.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 11, 18, 'Otišli su iz Midjana i stigli u Paran. Poveli su sa sobom ljude iz Parana i otišli u Egipat pred faraona, kralja Egipta, koji mu dade kuću, odredi mu hranu i dodijeli zemlje.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 11, 19, 'Hadad je stekao veliku milost u faraona, koji mu dade sestru svoje žene, sestru velike kneginje Tafnese.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 11, 20, 'Sestra Tafnesina rodi mu sina Genubata, koga Tafnesa odgoji u kraljevskoj palači, i Genubat je ostao u palači među faraonovom djecom.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 11, 21, 'Kada je Hadad doznao u Egiptu da je David počinuo kod svojih otaca i da je vojskovođa Joab umro, reče faraonu: \"Dopusti mi da odem u svoju zemlju!\"');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 11, 22, 'Faraon mu reče: \"Što ti nedostaje u mene te želiš poći u svoju zemlju?\" A on mu odgovori: \"Ništa, ali me pusti da odem!\" [25b] To je bilo zlo što ga je učinio Hadad: mrzio je Izraela i vladao je Edomom.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 11, 23, 'Bog je protiv Salomona podigao protivnika mu Rezona, sina Elijadova, koji je pobjegao od svoga gospodara Hadadezera, kralja sopskoga;');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 11, 24, 'Rezon je skupio ljude oko sebe i postao im četovođa kada ih David ubijaše. Rezon zauze Damask, ondje se nastani i zavlada Damaskom.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 11, 25, '[25a] On je bio protivnik Izraelov za života Salomonova.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 11, 26, 'Jeroboam bijaše sin Efraćanina Nebata, iz Sareda, a majka mu bijaše udovica imenom Serva. On je bio u službi Salomonovoj i podigao je ruku protiv kralja.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 11, 27, 'Evo razloga njegove pobune. Salomon je gradio Milo da zatrpa kosinu u gradu Davida, oca svoga.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 11, 28, 'Taj Jeroboam bijaše valjan čovjek; Salomon opazi kako se mladi čovjek prihvaća posla i postavi ga nad svom rabotom kuće Josipove.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 11, 29, 'Tada se dogodi te Jeroboam ode iz Jeruzalema, i na putu ga susrete prorok Ahija iz Šila, ogrnut novim plaštem; bijahu sami njih dvojica u polju.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 11, 30, 'Ahija uze novi plašt koji je imao na sebi i razdrije ga na dvanaest komada.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 11, 31, 'I reče Jeroboamu: \"Uzmi sebi deset komada, jer ovako govori Jahve, Bog Izraelov: \'Evo ću istrgnuti kraljevstvo iz ruke Salomonove i dat ću tebi deset plemena.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 11, 32, 'On će imati jedno pleme, zbog sluge mojega Davida i Jeruzalema, grada koji sam izabrao između svih plemena Izraelovih.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 11, 33, 'To je zato što me ostavio i poklonio se Aštarti, boginji Sidonaca, Kemošu, bogu moapskom, i Milkomu, bogu Amonaca, i ne hodi više mojim putovima; ne čini što je pravo u mojim očima, niti izvršava moje zakone i naredbe kao što je činio njegov otac David.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 11, 34, 'Ali mu neću iz ruke uzeti sve kraljevstvo, jer sam ga postavio knezom za sveg njegova života, zbog sluge svoga Davida, koga sam izabrao i koji je držao moje zapovijedi i moje zakone.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 11, 35, 'Ali ću uzeti kraljevstvo iz ruke njegova sina i tebi ću ga dati, to jest deset plemena.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 11, 36, 'A njegovu ću sinu ostaviti jedno pleme da moj sluga David ima uvijek svjetiljku preda mnom u Jeruzalemu, gradu koji sam izabrao sebi da u njemu stoluje Ime moje.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 11, 37, 'Tebe ću uzeti da kraljuješ nad svim što budeš želio i da budeš kralj nad Izraelom.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 11, 38, 'Ako budeš poslušao sve što ti zapovjedim i stupao budeš putovima mojim te činio što je pravedno u očima mojim držeći moje zakone i zapovijedi moje, kako je to činio moj sluga David, tada ću ja biti s tobom i sagradit ću ti trajan dom, kao što sam sagradio Davidu, i dat ću ti Izraela.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 11, 39, 'Ponizit ću potomke Davidove; ali ne zauvijek.\'\"');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 11, 40, 'Salomon je zato tražio da ubije Jeroboama, ali on pobježe u Egipat k Šišaku i ostade u Egiptu do smrti Salomonove.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 11, 41, 'Ostala povijest Salomonova, sve što je učinio i njegova mudrost, zar nije zapisana u knjizi Povijesti Salomonove?');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 11, 42, 'A kraljevaše Salomon u Jeruzalemu nad svim Izraelom četrdeset godina.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 11, 43, 'Onda počinu Salomon kod otaca svojih i bi sahranjen u Davidovu gradu, a njegov sin Roboam zakralji se namjesto njega.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 12, 1, 'Roboam ode u Šekem, jer su u Šekem došli svi Izraelci da ga zakralje.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 12, 2, 'Čim to ču Nebatov sin Jeroboam - koji još bijaše u Egiptu, kamo je pobjegao pred kraljem Salomonom - vrati se iz Egipta, jer');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 12, 3, 'bijahu poslali po nj i dozvali ga. Kad dođoše Jeroboam i sav zbor Izraelov, rekoše Roboamu:');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 12, 4, '\"Tvoj nam je otac nametnuo teški jaram. Ti nam sada olakšaj tešku službu svoga oca, teški jaram koji metnu na nas, pa ćemo ti služiti!\"');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 12, 5, 'A on im odgovori: \"Za tri dana dođite opet k meni.\" I narod ode.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 12, 6, 'Tada se kralj Roboam posavjetova sa starcima koji su služili njegovu ocu Salomonu dok je bio živ i upita ih: \"Što savjetujete da odgovorim ovome narodu?\"');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 12, 7, 'Oni mu odgovoriše: \"Ako danas udovoljiš tim ljudima, budeš im blagonaklon i odgovoriš im lijepim riječima, oni će ti uvijek ostati sluge.\"');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 12, 8, 'Ali on odbaci savjet što mu ga dadoše starci i posavjetova se s mladićima koji su odrasli s njim i bili mu u službi.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 12, 9, 'Upita ih: \"Što savjetujete da odgovorim ovome narodu koji mi reče: \'Olakšaj jaram što nam ga nametnu tvoj otac?\'\"');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 12, 10, 'Mladići koji bijahu s njime odrasli odgovoriše mu: \"Narodu koji ti reče: \'Tvoj nam je otac nametnuo jaram, a ti nam ga olakšaj\', uzvrati ovako: \'Moj je mali prst deblji od bedara moga oca!');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 12, 11, 'Eto, moj vam je otac nametnuo teški jaram, a ja ću još otežati vaš jaram; moj vas je otac šibao bičevima, a ja ću vas šibati bičevima sa željeznim štipavcima.\'\"');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 12, 12, 'A treći dan dođe sav narod k Roboamu, kako im bijaše zapovjedio kralj rekavši im: \"Vratite se k meni trećega dana.\"');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 12, 13, 'Kralj im oštro odgovori, odbacivši savjet koji mu dadoše stariji.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 12, 14, 'I reče im po savjetu mladih: \"Moj je otac otežao vaš jaram, a ja ću još dodati na nj; moj vas je otac šibao bičevima, a ja ću vas šibati bičevima sa željeznim štipavcima.\"');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 12, 15, 'Kralj dakle ne htjede poslušati naroda, jer tako upriliči Jahve da se ispuni riječ što je preko Ahije iz Šila kaza Nebatovu sinu Jeroboamu.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 12, 16, 'Kad Izraelci vidješe gdje se kralj oglušio, odgovori mu narod: \"Kakav dio mi imamo s Davidom? Mi nemamo baštine s Jišajevim sinom. U šatore, Izraele! A sad se, Davide, brini za svoj dom!\" I sav Izrael ode pod svoje šatore.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 12, 17, 'Roboam zavlada samo nad Izraelovim sinovima koji su živjeli po judejskim gradovima.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 12, 18, 'Potom kralj Roboam posla Adorama, nadstojnika za tlaku, ali ga Izraelci kamenovaše i on umrije; a kralj se Roboam brže-bolje pope na kola i pobježe u Jeruzalem.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 12, 19, 'Tako se Izrael odijelio od doma Davidova sve do danas.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 12, 20, 'Kada su Izraelci doznali da se vratio Jeroboam, pozvaše ga u zajednicu i postaviše ga kraljem nad svim Izraelom. Uz kuću Davidovu nije pristajao nitko, osim samoga plemena Judina.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 12, 21, 'Došavši u Jeruzalem, Roboam skupi sav dom Judin i pleme Benjaminovo, sto i osamdeset tisuća vrsnih ratnika, da udare na dom Izraelov i da vrate kraljevstvo Roboamu, sinu Salomonovu.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 12, 22, 'Ali dođe Jahvina riječ Božjem čovjeku Šemaji:');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 12, 23, '\"Kaži Salomonovu sinu Roboamu, judejskom kralju, i svem domu Judinu i Benjaminovu i ostalom narodu:');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 12, 24, 'Ovako veli Jahve: \'Ne idite se tući s braćom, djecom Izraelovom! Neka se svatko vrati svojoj kući, jer je ovo poteklo od mene.\'\" I oni poslušaše riječ Jahvinu i vratiše se kako im reče Jahve.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 12, 25, 'Jeroboam utvrdi Šekem u Efrajimovoj gori i ondje se nastani. Poslije izađe odatle i utvrdi Penuel.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 12, 26, 'Jeroboam reče u svom srcu: \"Sad bi se kraljevstvo moglo vratiti domu Davidovu.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 12, 27, 'Ako ovaj narod bude nastavio uzlaziti u Dom Jahvin u Jeruzalemu da prinosi žrtve, srce će se naroda vratiti svome gospodaru, Roboamu, kralju judejskome, i mene će ubiti.\"');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 12, 28, 'Pošto se kralj posavjetovao, načini dva zlatna teleta i reče narodu: \"Dosta ste uzlazili u Jeruzalem! Evo, Izraele, tvoga boga koji te izveo iz zemlje egipatske.\"');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 12, 29, 'Zatim postavi jedno tele u Betelu, a drugo smjesti u Dan.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 12, 30, 'To je bila prigoda za grijeh: narod je odlazio jednome u Betel i drugome u Dan.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 12, 31, 'I podiže Jeroboam hram na uzvišicama i postavi iz puka svećenike koji nisu bili sinovi Levijevi.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 12, 32, 'Zatim je Jeroboam uveo blagdan u osmom mjesecu, petnaestoga dana tog mjeseca, kao što je blagdan koji se slavi u Judeji, i uzađe k žrtveniku. Tako je učinio u Betelu, žrtvujući teocima koje je načinio. U Betelu je postavio i svećenike uzvišica što ih bijaše podigao.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 12, 33, 'I uzađe k žrtveniku koji je načinio, petnaestoga dana osmog mjeseca, mjeseca koji je sam izabrao; i ustanovi blagdan za Izraelce i uzađe k žrtveniku da prinese kad.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 13, 1, 'A neki čovjek Božji dođe na riječ Jahvinu iz Judeje u Betel kada Jeroboam stajaše pred žrtvenikom da prinese kad.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 13, 2, 'I po Jahvinoj zapovijedi povika onaj prema žrtveniku: \"Žrtveniče, žrtveniče! Ovako veli Jahve: \'Evo će se roditi u kući Davidovoj sin po imenu Jošija. On će na tebi žrtvovati svećenike uzvišica, te koji na tebi prinose kad, i on će na tebi spaliti ljudske kosti!\'\"');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 13, 3, 'U isto im vrijeme dade znak: \"Ovo je znak da je Jahve govorio: gle, žrtvenik će se raspuknuti i prosut će se pepeo što je na njemu.\"');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 13, 4, 'Kada je kralj čuo što je čovjek Božji rekao protiv žrtvenika u Betelu, pruži ruku odande od žrtvenika i reče: \"Uhvatite ga!\" Ali se osušila ruka koju je ispružio prema čovjeku i nije je mogao vratiti k sebi.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 13, 5, 'Žrtvenik se raspuknuo i pepeo se prosuo sa žrtvenika, prema znaku što ga je dao čovjek Božji po naredbi Jahvinoj.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 13, 6, 'Kralj progovori i reče čovjeku Božjem: \"Umilostivi Jahvu, Boga svoga, da bih mogao vratiti ruku k sebi.\" Božji čovjek umilostivi Jahvu i ruka se kraljeva vrati k njemu i bila je kao prije.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 13, 7, 'Kralj onda reče čovjeku Božjem: \"Hodi sa mnom kući da se okrijepiš. I dat ću ti dar.\"');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 13, 8, 'Ali čovjek Božji odgovori kralju: \"Da mi dadeš polovinu svoje kuće, ne bih pošao s tobom. Ni jeo ni pio ne bih na ovom mjestu,');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 13, 9, 'jer mi je ovako zapovjeđeno riječju Jahvinom: \'Ne jedi kruha i ne pij vode, niti se vraćaj istim putem kojim si došao.\'\"');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 13, 10, 'I otišao je drugim putem, nije se vraćao putem kojim je došao u Betel.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 13, 11, 'A u Betelu živio star prorok. Došli njemu njegovi sinovi te mu pripovjedili sve što je onoga dana učinio čovjek Božji u Betelu; i riječi što ih je onaj kazao kralju pripovjediše sinovi ocu.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 13, 12, 'A on ih upita: \"Kojim je putem otišao?\" Sinovi pokazaše put kojim je otišao čovjek Božji što bijaše došao iz Judeje.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 13, 13, 'Prorok će nato sinovima: \"Osamarite mi magarca!\" I osamariše mu magarca, a on uzjaha.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 13, 14, 'Krenuo je za čovjekom Božjim i našao ga gdje sjedi pod hrastom; i upita ga: \"Jesi li ti čovjek Božji koji je došao iz Judeje?\" A on mu odgovori: \"Jesam.\"');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 13, 15, 'Prorok mu reče: \"Hodi sa mnom mome domu da štogod pojedeš.\"');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 13, 16, 'Ali on odgovori: \"Ne smijem se vratiti s tobom, niti smijem jesti kruha ni piti vode na ovome mjestu,');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 13, 17, 'jer mi je Jahvinom riječju naređeno ovo: \'Ne jedi ondje kruha, ne pij vode, niti se vraćaj putem kojim si onamo pošao\'.\"');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 13, 18, 'Nato će mu onaj: \"I ja sam prorok kao i ti, i anđeo mi je riječju Jahvinom rekao: \'Povedi ga sa sobom kući da jede kruha i pije vode.\'\" Slagao mu je.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 13, 19, 'Božji čovjek vrati se s njim, u njegovoj je kući jeo kruha i pio vode.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 13, 20, 'Dok su sjedili za stolom, dođe riječ Jahvina proroku koji ga je natrag doveo');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 13, 21, 'i povika on čovjeku Božjem koji je došao iz Judeje: \"Ovako veli Jahve: zato što nisi poslušao zapovijedi Jahvine i nisi držao naredbe koju ti je dao Jahve, Bog tvoj,');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 13, 22, 'nego si se vratio, jeo kruha i pio vode na mjestu gdje sam ti rekao da ne jedeš kruha i ne piješ vode, zato tijelo tvoje neće leći u grob otaca tvojih.\"');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 13, 23, 'Pošto se onaj koga bijaše doveo najeo kruha i napio vode, osedla mu magarca.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 13, 24, 'I ode onaj. A na putu ga zaskoči lav i usmrti ga. I tako je mrtvo tijelo ležalo ispruženo na putu, magarac stajao kraj njega, a i lav stajaše kraj tijela.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 13, 25, 'Ljudi prolazeći vidješe mrtvo tijelo ispruženo na putu i lava gdje stoji kraj njega; i odoše i javiše to u gradu gdje je živio stari prorok.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 13, 26, 'Kad je to čuo prorok koji bijaše onoga vratio s puta, reče: \"To je čovjek Božji koji se usprotivio riječi Jahvinoj! I Jahve ga je predao lavu, koji ga je napao i ubio, prema riječi koju je Jahve rekao.\"');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 13, 27, 'I reče svojim sinovima: \"Osamarite mi magarca!\" I oni mu ga osamariše.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 13, 28, 'Ode on i nađe mrtvo tijelo bačeno na putu i magarca i lava gdje stoje pokraj tijela: lav nije požderao tijelo niti je rastrgao magarca.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 13, 29, 'Tada prorok podiže mrtvo tijelo čovjeka Božjeg i prebaci ga na magarca; i vrati se u grad gdje je živio da mrtvoga ožali i pokopa.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 13, 30, 'Položio je mrtvo tijelo u svoju grobnicu i jecao je nad njim: \"Jao, brate moj!\"');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 13, 31, 'A kad ga je pokopao, reče svojim sinovima: \"Poslije moje smrti sahranite me u istu grobnicu gdje je pokopan čovjek Božji; stavite moje kosti kraj njegovih.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 13, 32, 'Jer će se sigurno ispuniti riječ koju je po zapovijedi Jahvinoj objavio protiv žrtvenika u Betelu i protiv svih svetišta na uzvišicama u gradovima Samarije.\"');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 13, 33, 'Ni poslije ovoga događaja ne obrati se Jeroboam za svoga zlog puta, nego je i dalje priproste ljude postavljao za svećenike na uzvišicama: tko je želio, davao mu je darove da postane svećenik uzvišica.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 13, 34, 'Takvim je postupkom padala u grijeh kuća Jeroboamova, rušila se i nestajala s lica zemlje.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 14, 1, 'U ono se vrijeme razbolje Abija, sin Jeroboamov,');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 14, 2, 'i Jeroboam reče svojoj ženi: \"Ustani i preobuci se da te ne bi prepoznali da si žena Jeroboamova; i idi u Šilo. Ondje je prorok Ahija: onaj koji mi je prorokovao da ću biti kraljem ovoga naroda.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 14, 3, 'I ponesi deset hljebova, kolača i posudu meda i otiđi k njemu! On će ti reći što će biti s dječakom.\"');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 14, 4, 'I učini tako žena Jeroboamova: ustade, ode u Šilo i uđe u kuću Ahijinu. A on nije više vidio, oslabile mu oči od duboke starosti.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 14, 5, 'Ali mu je Jahve rekao: \"Evo dolazi žena Jeroboamova da od tebe traži savjeta za svoga sina jer je bolestan; a ti ćeš joj reći tako i tako. Kad bude ulazila, pretvarat će se kao da je druga.\"');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 14, 6, 'Kad Ahija ču šum njenih koraka na vratima, reče joj: \"Uđi, ženo Jeroboamova! Što se pretvaraš da si druga, kad imam tešku vijest za tebe?');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 14, 7, 'Idi, reci Jeroboamu: \'Ovako kaže Jahve, Bog Izraelov: Podigao sam te isred naroda i učinio sam te knezom nad mojim narodom Izraelom,');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 14, 8, 'istrgnuo sam kraljevstvo iz kuće Davidove i dao ga tebi. Ali ti nisi bio kao moj sluga David, koji je držao moje zapovijedi i koji me slijedio svim srcem svojim i činio samo ono što je pravedno u mojim očima.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 14, 9, 'Ti si radio kudikamo gore od svojih prethodnika, otišao si i načinio sebi druge bogove, salio si im likove da me dražiš, mene si bacio za leđa.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 14, 10, 'Zato, evo, puštam zlo na kuću Jeroboamovu, istrijebit ću iz obitelji Jeroboamove sve što mokri uza zid, robove i slobodnjake u Izraelu; ja ću netragom pomesti kuću Jeroboamovu kao što se mete nečist, da ga ništa ne ostane.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 14, 11, 'One koji iz Jeroboamove obitelji umru u gradu, proždrijet će psi, a one koji umru u polju, pojest će ptice nebeske.\' - Eto tako je Jahve rekao.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 14, 12, 'A ti ustani i pođi svome domu: tek što nogama stupiš u grad, dječak će umrijeti.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 14, 13, 'Sav će ga Izrael oplakati i pokopat će ga. On će biti jedini iz obitelji Jeroboamove položen u grob, jer se jedino na njemu našlo nešto što se u kući Jeroboamovoj svidjelo Jahvi, Bogu Izraelovu.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 14, 14, 'Jahve će sebi postaviti kralja nad Izraelom i taj će istrijebiti kuću Jeroboamovu. Evo dana! Što? Čak i trenutka!');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 14, 15, 'Jahve će udariti Izraela te će se njihati kao trska u vodi. Iščupat će Izraela iz ove dobre zemlje koju je dao njihovim ocima i rasijat će ih s onu stranu Rijeke, jer su načinili sebi ašere koje srde Jahvu.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 14, 16, 'Odbacit će Izraela kao smeće, zbog grijeha što ih je učinio Jeroboam i na koje je navodio Izraela.\"');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 14, 17, 'Žena Jeroboamova ustade i ode. Stigla je u Tirsu, a kad je prelazila kućni prag, dječak bijaše mrtav.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 14, 18, 'Pokopali su ga i sav ga je Izrael oplakao prema riječi koju je Jahve rekao po sluzi svome proroku Ahiji.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 14, 19, 'Ostala povijest Jeroboamova, kako je ratovao i kraljevao, to je zapisano u knjizi Ljetopisa kraljeva izraelskih.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 14, 20, 'Jeroboamovo kraljevanje trajalo je dvadeset i dvije godine, zatim je Jeroboam počinuo kraj otaca svojih, a sin mu Nadab zakraljio se mjesto njega.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 14, 21, 'Roboam, sin Salomonov, bio je kralj Judejaca; bijaše mu četrdeset i jedna godina kad je postao kraljem, a sedamnaest je godina kraljevao u Jeruzalemu, u gradu koji Jahve izabra između svih izraelskih plemena da ondje postavi svoje Ime. Majka mu se zvala Naama, a bila je Amonka.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 14, 22, 'I Juda učini zlo u očima Jahvinim. Grijesima koje su počinili razjarili su ga više od svega što su učinili njihovi oci.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 14, 23, 'Jer su i oni podigli uzvišice, stupove i ašere na svakom brežuljku i pod svakim zelenim drvetom.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 14, 24, 'Bilo je čak posvećenih bludnica u zemlji. Oponašao je sve grozote naroda što ih je Jahve otjerao ispred sinova Izraelovih.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 14, 25, 'Pete godine Roboamova kraljevanja egipatski kralj Šišak navali na Jeruzalem.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 14, 26, 'Opljačka sve blago iz Doma Jahvina i riznicu kraljevskog dvora; sve je uzeo; uze i sve zlatne štitove što ih bijaše napravio Salomon.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 14, 27, 'Namjesto njih kralj Roboam napravi tučane štitove i povjeri ih zapovjednicima straže koja je čuvala vrata kraljevskog dvora.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 14, 28, 'Kad je god kralj išao u Jahvin Dom, stražari su ih uzimali, a poslije ih vraćali u stražaru.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 14, 29, 'Ostala povijest Roboamova, sve što je učinio, zar nije zapisano u knjizi Ljetopisa kraljeva judejskih?');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 14, 30, 'Za sve vrijeme bio je rat između Roboama i Jeroboama.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 14, 31, 'Roboam je počinuo sa svojim ocima i bi sahranjen sa svojim ocima u Davidovu gradu. Majka mu se zvala Naama, a bila je Amonka. Na njegovo se mjesto zakraljio sin mu Abijam.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 15, 1, 'Osamnaeste godine kraljevanja Jeroboama, sina Nebatova, zakraljio se Abijam u Judeji.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 15, 2, 'Tri je godine kraljevao u Jeruzalemu; njegova se majka zvala Maaka, a bila je kći Abšalomova.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 15, 3, 'On je hodio u svim grijesima što ih je njegov otac činio prije njega, i njegovo srce nije bilo potpuno odano Jahvi, Bogu svome, kao srce njegova praoca Davida.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 15, 4, 'Ipak, zbog Davida, dao mu je Jahve, Bog njegov, svjetiljku u Jeruzalemu, podigavši sinove njegove poslije njega i sačuvavši Jeruzalem.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 15, 5, 'Jer je David činio sve što je pravo u očima Jahvinim i za svega svoga života nije odstupio ni od čega što mu je zapovjedio, osim onog što je učinio Uriji Hetitu.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 15, 6, '#');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 15, 7, 'Ostala povijest Abijamova, sve što je učinio, zar to nije zapisano u knjizi Ljetopisa kraljeva judejskih? A bijaše rat između Abijama i Jeroboama.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 15, 8, 'Potom je Abijam počinuo sa svojim ocima. Sahraniše ga u Davidovu gradu; na njegovo se mjesto zakralji sin mu Asa.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 15, 9, 'Dvadesete godine Jeroboamova kraljevanja nad Izraelom postade Asa kraljem Judeje.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 15, 10, 'Kraljevao je četrdeset i jednu godinu u Jeruzalemu; njegova se baka zvala Maaka, a bila je kći Abšalomova.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 15, 11, 'Asa je činio što je pravo u očima Jahvinim, kao i njegov praotac David.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 15, 12, 'Protjerao je iz zemlje posvećene bludnice i uklonio sve idole koje njegovi oci bijahu načinili.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 15, 13, 'Sam je uklonio svoju baku s dostojanstva velike kneginje, jer bijaše načinila gada Ašeri. Asa je sasjekao njezina gada i spalio ga u potoku Kidronu.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 15, 14, 'Ali uzvišice nisu bile uklonjene; ipak je Asino srce bilo privrženo Jahvi svega njegova života.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 15, 15, 'Unio je u Dom Jahvin posvećene darove svoga oca i svoje: srebro, zlato i posuđe.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 15, 16, 'Bio je rat između Ase i Baše, kralja izraelskoga, u sve njihove dane.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 15, 17, 'Izraelski kralj Baša navali na Judeju i stade utvrđivati Ramu da spriječi svako kretanje judejskom kralju Asi.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 15, 18, 'Asa tada uze srebra i zlata koje je preostalo u riznicama Doma Jahvina i u riznicama kraljevskog dvora i dade ga svojim slugama te ih posla Ben-Hadadu, sinu Tabrimonovu, sinu Hezjonovu, aramejskom kralju, koji je stolovao u Damasku, i poruči mu:');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 15, 19, '\"Neka bude savez između mene i tebe, između moga i tvoga oca; evo, šaljem ti na dar srebra i zlata: hajde, raskini savez s izraelskim kraljem Bašom da bi otišao od mene.\"');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 15, 20, 'Ben-Hadad posluša kralja Asu i posla svoje vojskovođe na izraelske gradove te oni pokoriše Ijon, Dan, Abel Bet-Maaku, sav Kineret i svu zemlju Naftali.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 15, 21, 'A kada to Baša dozna, presta utvrđivati Ramu i vrati se u Tirsu.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 15, 22, 'Kralj Asa sazva sve Judejce, bez izuzetka, i oni odnesoše kamenje i drvo kojima je Baša utvrđivao Ramu, i kralj Asa utvrdi time Gebu Benjaminovu i Mispu.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 15, 23, 'Ostala povijest Asina, sve njegove pobjede i sve što je učinio i gradovi koje je utvrdio, zar to nije zapisano u knjizi Ljetopisa kraljeva judejskih? A u starosti bolovao je od nogu.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 15, 24, 'Asa je počinuo sa svojim ocima i sahranjen je sa svojim ocima u gradu Davida, svoga praoca. Njegov sin Jošafat zakralji se mjesto njega.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 15, 25, 'Nadab, sin Jeroboamov, postade kraljem Izraela druge godine Asina kraljevanja Judejom i vladao je dvije godine Izraelom.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 15, 26, 'Činio je zlo u očima Jahvinim. Hodio je putem svoga oca i oponašao njegov grijeh na koji je navodio Izraela.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 15, 27, 'Baša, sin Ahijin, iz kuće Jisakarove, uroti se protiv njega i ubi ga u Gibetonu, koji pripada Filistejcima i koji su opsjedali Nadab i sav Izrael.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 15, 28, 'Baša ga ubi treće godine Asina kraljevanja Judejom i zavlada mjesto njega.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 15, 29, 'Kad je postao kraljem, pobi svu kuću Jeroboamovu i ne poštedi nikoga od Jeroboamovih dokle sve ne istrijebi po riječi koju je Jahve rekao preko sluge svoga Ahije iz Šila.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 15, 30, 'Zbog grijeha što ih je učinio i na koje je naveo Izraela i zbog gnjeva kojim je raspalio Jahvu, Boga Izraelova.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 15, 31, 'Ostala povijest Nadabova, i sve što je učinio, zar to nije zapisano u knjizi Ljetopisa kraljeva izraelskih?');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 15, 32, 'Između Ase i Izraelova kralja Baše vladao je rat u sve njihove dane.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 15, 33, 'Treće godine Asina kraljevanja Judejom postade Baša, sin Ahijin, kraljem nad svim Izraelom u Tirsi i vladao je dvadeset i četiri godine.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 15, 34, 'Činio je zlo u očima Jahvinim i hodio je putem Jeroboama i njegovih grijeha kojima je zavodio Izraelce.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 16, 1, 'Tada bi upućena riječ Jahvina Jehuu, sinu Hananijevu, protiv Baše:');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 16, 2, '\"Iz praha sam te podigao i postavio knezom nad mojim narodom Izraelom, ali si ti krenuo Jeroboamovim putem i navodiš narod moj Izrael na grijehe te me razjaruješ njihovim grijesima;');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 16, 3, 'zato ću netragom pomesti Bašu i kuću njegovu: učinit ću s tvojom kućom kao i s kućom Jeroboama, sina Nebatova.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 16, 4, 'Tko iz obitelji Bašine umre u gradu, pojest će ga psi, a tko im umre u polju, pojest će ga ptice nebeske.\"');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 16, 5, 'Ostala povijest Bašina, što je učinio, njegova djela, zar sve to nije zapisano u knjizi Ljetopisa kraljeva izraelskih?');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 16, 6, 'Baša je počinuo sa svojim ocima i sahranjen je u Tirsi. Sin njegov Ela zakraljio se mjesto njega.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 16, 7, 'Ali riječ Jahvina po Jehuu proroku, sinu Hananijevu, nije bila upravljena protiv Baše i njegove kuće samo zbog toga što je činio zlo u očima Jahve i ljutio ga djelima svojih ruku te bio kao i kuća Jeroboamova nego i zbog toga što je i nju istrijebio.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 16, 8, 'Dvadeset i šeste godine kraljevanja Ase u Judeji postade Ela, sin Bašin, kraljem Izraela u Tirsi; vladao je svega dvije godine.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 16, 9, 'Njegov dvoranin Zimri, zapovjednik polovine bojnih kola, uroti se protiv njega. Kad je bio u Tirsi, opio se u kući Arse, upravitelja dvora u Tirsi.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 16, 10, 'Tada provali Zimri, udari na njega i ubi ga, dvadeset i sedme godine Asina kraljevanja Judejom, te zavlada mjesto njega.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 16, 11, 'Čim je zavladao i sjeo na prijestolje, poubija svu obitelj Bašinu; nije mu poštedio ni što uza zid mokri, ni njegovih rođaka ni prijatelja.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 16, 12, 'Tako Zimri iskorijeni svu kuću Bašinu po riječi koju je Jahve rekao protiv Baše preko sluge svoga proroka Jehua,');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 16, 13, 'zbog sviju grijeha što su ih činili Baša i sin mu Ela i tako zavodili Izraela, srdeći Jahvu, Boga Izraelova, svojim krivim bogovima.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 16, 14, 'Ostala povijest Elina, sve što je učinio, zar to nije zapisano u knjizi Ljetopisa kraljeva izraelskih?');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 16, 15, 'Dvadeset i sedme godine Asina kraljevanja Judejom postade Zimri kraljem u Tirsi i vladao je sedam dana. Narod je tada opsjedao Gibeton, koji je pripadao Filistejcima.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 16, 16, 'Kad je utaboreni narod čuo da se Zimri pobunio i ubio kralja, sav Izrael istoga dana u taboru proglasi kraljem nad Izraelom zapovjednika vojske Omrija.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 16, 17, 'Zatim Omri i sav Izrael s njime odoše od Gibetona i opsjedoše Tirsu.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 16, 18, 'Kad je Zimri vidio da će grad biti osvojen, uđe u utvrdu kraljevskoga dvora, zapali nad sobom kraljevski dvor i tako pogibe.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 16, 19, 'To je bilo zbog grijeha koje je počinio radeći što je zlo u očima Jahvinim i hodeći putem Jeroboama i njegovih grijeha kojima je zavodio Izraela.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 16, 20, 'Ostala povijest Zimrijeva i njegova urota koju je skovao, zar sve to nije zapisano u knjizi Ljetopisa kraljeva izraelskih?');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 16, 21, 'Tada se Izraelov narod razdijelio: polovica se odlučila za Tibnija, sina Ginatova, da ga učini kraljem, a druga polovica za Omrija.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 16, 22, 'Ali pristaše Omrijeve nadjačaše pristaše Tibnija, sina Ginatova, pa kad Tibni umrije, postade Omri kraljem.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 16, 23, 'Trideset i prve godine Asina kraljevanja Judejom postade Omri kraljem Izraela za dvanaest godina. U Tirsi je kraljevao šest godina.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 16, 24, 'Tada kupi od Šemera za dva talenta srebra brdo Samariju; sagradi grad koji po imenu Šemera, vlasnika brijega, nazva Samarija.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 16, 25, 'Ali je Omri činio zlo u očima Jahvinim i bio je gori od svojih prethodnika.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 16, 26, 'U svemu je slijedio Jeroboama, sina Nebatova, i njegove grijehe kojima je zavodio Izraela i srdio Jahvu, Boga Izraelova, svojim lažnim bogovima.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 16, 27, 'Ostala povijest Omrijeva, sve što je učinio, njegovi pothvati koje je izveo, zar to nije zapisano u knjizi Ljetopisa kraljeva izraelskih?');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 16, 28, 'Omri počinu sa svojim ocima i sahranjen je u Samariji. Njegov sin Ahab postade kraljem mjesto njega.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 16, 29, 'Ahab, sin Omrijev, postade izraelskim kraljem u trideset i osmoj godini Asina kraljevanja Judejom i vladao je dvadeset i dvije godine nad Izraelom u Samariji.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 16, 30, 'Ahab, sin Omrijev, činio je u očima Jahvinim više zla od svih svojih prethodnika.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 16, 31, 'I malo mu bijaše što je hodio u grijesima Jeroboama, sina Nebatova, nego se još oženi Izebelom, kćerju Etbaala, kralja sidonskog, i poče služiti Baalu i klanjati mu se;');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 16, 32, 'Baalu podiže žrtvenik u Baalovu hramu što ga bijaše sagradio u Samariji.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 16, 33, 'Ahab je podigao i Ašeru i učinio druga zlodjela i razljutio Jahvu, Boga Izraelova, više od svih kraljeva izraelskih koji bijahu prije njega.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 16, 34, 'Za njegova je vremena Hiel iz Betela sagradio Jerihon; uz žrtvu svoga prvorođenca Abirama podigao je temelje, a uz žrtvu svoga mezimca Seguba postavio je gradska vrata, po riječi koju je Jahve rekao po svome sluzi Jošui, sinu Nunovu.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 17, 1, 'Ilija Tišbijac, iz Tišbe Gileadske, reče Ahabu: \"Živoga mi Jahve, Boga Izraelova, komu služim, neće ovih godina biti ni rose ni kiše, osim na moju zapovijed.\"');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 17, 2, 'Upućena mu je riječ Jahvina ovako:');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 17, 3, '\"Idi odavde i kreni na istok i sakrij se na potoku Keritu, koji je nasuprot Jordanu.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 17, 4, 'Pit ćeš iz potoka, a gavranima sam zapovjedio da te ondje hrane.\"');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 17, 5, 'Ode on i učini po riječi Jahvinoj i nastani se na potoku Keritu, nasuprot Jordanu.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 17, 6, 'Gavrani su mu jutrom donosili kruha, a večerom mesa; iz potoka je pio.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 17, 7, 'Ali poslije nekog vremena presuši potok, jer nije bilo kiše u svoj zemlji.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 17, 8, 'Tada Iliji dođe riječ Jahvina:');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 17, 9, '\"Ustani, idi u Sarfatu Sidonsku i ondje ostani. Evo, ondje sam zapovjedio jednoj udovici da te hrani.\"');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 17, 10, 'Ustade on i krenu u Sarfatu. Kada je stigao do gradskih vrata, neka je udovica onuda skupljala drva; on joj se obrati i reče: \"Donesi mi malo vode u vrču da pijem!\"');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 17, 11, 'Kad je pošla da donese, on viknu za njom i reče joj: \"Donesi mi i malo kruha u ruci!\"');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 17, 12, 'Ona odgovori: \"Živoga mi Jahve, tvoga Boga, ja nemam pečena kruha, nemam do pregršti brašna u ćupu i malo ulja u vrču. I evo kupim drva, pa ću otići i ono pripremiti sebi i svome sinu da pojedemo i da umremo.\"');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 17, 13, 'Ali joj Ilija reče: \"Ništa se ne boj. Idi i uradi kako si rekla; samo najprije umijesi meni kolačić, pa mi donesi; a onda zgotovi za sebe i za svoga sina.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 17, 14, 'Jer ovako govori Jahve, Bog Izraelov: \'U ćupu neće brašna nestati ni vrč se s uljem neće isprazniti sve dokle Jahve ne pusti da kiša padne na zemlju.\'\"');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 17, 15, 'Ode ona i učini kako je rekao Ilija; i za mnoge dane imadoše jela, ona, on i njen sin.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 17, 16, 'Brašno se iz ćupa nije potrošilo i u vrču nije nestalo ulja, po riječi koju je Jahve rekao preko svoga sluge Ilije.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 17, 17, 'Poslije ovih događaja razbolio se sin domaćičin i bolest se njegova jako pogoršala, tako te u njemu nije ostalo daha.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 17, 18, 'Tada ona reče Iliji: \"Što ja imam s tobom, čovječe Božji? Zar si došao k meni da me podsjetiš na moj grijeh i da mi usmrtiš sina!\"');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 17, 19, 'On joj reče: \"Daj mi svoga sina!\" Tada ga uze iz njezina naručja, odnese ga u gornju sobu gdje je stanovao i položi ga na svoju postelju.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 17, 20, 'Tada zavapi Jahvi i reče: \"Jahve, Bože moj, zar zaista želiš udovicu koja me ugostila uvaliti u tugu umorivši joj sina?\"');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 17, 21, 'Zatim se tri puta pružio nad dječakom zazivajući Jahvu: \"Jahve, Bože, učini da se u ovo dijete vrati duša njegova!\"');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 17, 22, 'Jahve je uslišio molbu Ilijinu, u dijete se vratila duša i ono oživje.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 17, 23, 'Ilija ga uze, siđe iz gornje sobe u kuću i dade ga njegovoj materi; i reče Ilija: \"Evo, tvoj sin živi!\"');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 17, 24, 'Žena mu reče: \"Sada znam da si ti čovjek Božji i da je riječ Jahvina u tvojim ustima istinita!\"');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 18, 1, 'Prošlo je mnogo vremena i riječ Jahvina bi upravljena treće godine Iliji: \"Idi, pokaži se Ahabu, jer želim pustiti kišu na lice zemlje.\"');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 18, 2, 'I ode Ilija da se pokaže Ahabu. Kako je glad u Samariji bivala teža,');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 18, 3, 'pozva Ahab dvorskog upravitelja Obadiju. Taj se Obadija veoma bojao Jahve;');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 18, 4, 'jer kad je Izebela poubijala proroke Jahvine, on je uzeo stotinu proroka i sakrio ih po pedeset u jednu spilju, gdje ih je hranio kruhom i pojio vodom.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 18, 5, 'I reče Ahab Obadiji: \"Hajde, obići ćemo svu zemlju, sve izvore i sve potoke, možda ćemo naći trave da sačuvamo u životu konje i mazge i da nam ne propadne stoka.\"');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 18, 6, 'Podijelili su zemlju koju će pretražiti: Ahab je sam otišao jednim putem, a Obadija je pošao sam drugim putem.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 18, 7, 'I kad je Obadija bio na putu, eto mu u susret Ilije; poznavši ga, pade ničice i reče: \"Jesi li to ti, gospodaru Ilija!\"');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 18, 8, 'On mu odgovori: \"Ja sam! Idi i reci svome gospodaru: \'Evo Ilije!\'\"');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 18, 9, 'Odgovori mu Obadija: \"Što sam sagriješio te slugu svojega predaješ u ruke Ahabu da me ubije?');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 18, 10, 'Živoga mi Jahve, tvoga Boga, nema naroda ili kraljevstva kamo moj gospodar nije slao da te traže. I kad su mu rekli: \'Nema ga!\' zakleo je kraljevstvo i narod što te nisu našli.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 18, 11, 'I sada mi naređuješ: \'Idi, reci svome gospodaru: Evo Ilije!\'');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 18, 12, 'Ali kad ja odem od tebe, Duh Jahvin odnijet će te ne znam kamo, a ja ću doći i obavijestiti Ahaba. Pa kad te ne nađe, ubit će me! A tvoj se sluga boji Jahve od mladosti svoje!');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 18, 13, 'Zar nije poznato mome gospodaru što sam učinio kad je ono Izebela poubijala proroke Jahvine? Sakrio sam stotinu proroka, po pedeset u jednu spilju, i kruhom ih uzdržavao i vodom.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 18, 14, 'I sada ti naređuješ: \'Idi, reci svome gospodaru: Evo Ilije!\' Pa on će me ubiti!\"');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 18, 15, 'Ilija mu odgovori: \"Živoga mi Jahve Sebaota, komu služim, još ću mu se danas pokazati.\"');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 18, 16, 'Obadija pođe u susret Ahabu i donese mu vijest, a Ahab pođe u susret Iliji.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 18, 17, 'Kad Ahab ugleda Iliju, reče mu: \"Jesi li ti onaj koji upropašćuješ Izraela?\"');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 18, 18, 'Ilija odgovori: \"Ne upropašćujem ja Izraela, nego ti i tvoja obitelj, jer ste ostavili Jahvu, a ti si sljedbenik Baala.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 18, 19, 'Sada sakupi sav Izrael preda me na gori Karmelu i četiri stotine pedeset proroka Baalovih koji jedu za stolom Izebelinim.\"');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 18, 20, 'Ahab pozva sve sinove Izraelove i sakupi proroke na gori Karmelu.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 18, 21, 'Ilija pristupi svemu narodu i reče: \"Dokle ćete hramati na obje strane? Ako je Jahve Bog, slijedite ga; ako je Baal, slijedite njega.\" A narod mu nije ništa odgovorio.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 18, 22, 'Ilija nastavi: \"Ja sam još jedini ostao kao prorok Jahvin, a Baalovih je proroka četiri stotine i pedeset.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 18, 23, 'Dajte nam dva junca. Neka oni izaberu sebi jednoga, neka ga sasijeku i stave na drva, ali neka ne podmeću ognja. Ja ću spremiti drugoga junca i neću podmetati ognja.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 18, 24, 'Vi zazovite ime svoga boga, a ja ću zazvati ime Jahvino: bog koji odgovori ognjem pravi je Bog.\" Sav narod odgovori: \"Dobro!\"');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 18, 25, 'Potom reče Ilija prorocima Baalovim: \"Izaberite sebi jednoga junca i počnite, jer vas je mnogo više. Zazovite ime svoga boga, ali ne stavljajte ognja.\"');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 18, 26, 'Oni uzeše junca koji je njima pripao i pripremiše ga. Zazivali su ime Baalovo od jutra do podne govoreći: \"O Baale, usliši nas!\" Ali nije bilo ni glasa, ni odgovora. I skakahu i prigibahu koljena pred žrtvenikom koji su načinili.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 18, 27, 'U podne im se Ilija naruga i reče: \"Glasnije vičite, jer on je bog; zauzet je, ili ima posla, ili je na putu; možda spava, pa ga treba probuditi!\"');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 18, 28, 'A oni okrenuše vikati još glasnije i parati se noževima i sulicama, kako je u njih običaj, sve dok ih nije oblila krv.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 18, 29, 'Kad je prošlo podne, pali su u bunilo i bjesnjeli sve dok nije bilo vrijeme da se prinese žrtva; ali nije bilo nikakva glasa ni odgovora niti znaka da ih tkogod sluša.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 18, 30, 'Tada Ilija reče svemu narodu: \"Priđite k meni!\" I sav mu narod pristupi. On popravi žrtvenik Jahvin koji bijaše srušen.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 18, 31, 'Ilija uze dvanaest kamenova prema broju plemena sinova Jakova, kome je Bog rekao: \"Izrael će biti ime tvoje!\"');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 18, 32, 'I sagradi od toga kamenja žrtvenik Imenu Jahvinu i iskopa jarak oko žrtvenika, širok da bi se mogle posijati dvije mjere pšenice.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 18, 33, 'Složi drva, rasiječe junca i stavi ga na drva.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 18, 34, 'Tada reče: \"Napunite vodom četiri vrča i izlijte na paljenicu i na drva!\" Učiniše tako. Zapovjedi im: \"Ponovite\", i oni ponoviše. Tada reče: \"Učinite i treći put.\" Oni tako i treći put.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 18, 35, 'Voda je tekla oko žrtvenika i jarak se ispunio vodom.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 18, 36, 'Kad bijaše vrijeme da se prinese žrtva, pristupi prorok Ilija i reče: \"Jahve, Bože Abrahamov, Izakov i Izraelov, objavi danas da si ti Bog u Izraelu, da sam ja sluga tvoj i da sam po zapovijedi tvojoj učinio sve ovo.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 18, 37, 'Usliši me, Jahve; usliši me, da bi sav ovaj narod znao da si ti, Jahve, Bog i da ćeš ti obratiti njihova srca.\"');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 18, 38, 'I oganj Jahvin pade i proguta paljenicu i drva, kamenje i prašinu, čak i vodu u jarku isuši.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 18, 39, 'Sav narod se uplaši, ljudi padoše ničice i rekoše: \"Jahve je Bog! Jahve je Bog!\"');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 18, 40, 'Ilija im reče: \"Pohvatajte proroke Baalove da nijedan od njih ne utekne!\" I oni ih pohvataše. Ilija ih odvede do potoka Kišona i ondje ih pobi.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 18, 41, 'Ilija reče Ahabu: \"Idi gore, jedi i pij, jer čujem šumor kiše.\"');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 18, 42, 'Dok je Ahab otišao gore da jede i pije, Ilija se popeo na vrh Karmela, prignuo se zemlji i sakrio lice među koljena.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 18, 43, 'Rekao je zatim svome momku: \"Idi gore i pogledaj prema moru.\" On ode gore, pogleda i reče: \"Ništa nema ondje!\" Ilija odgovori: \"Vrati se sedam puta.\"');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 18, 44, 'Ali sedmoga puta reče momak: \"Eno se oblak, malen kao dlan čovječji, diže od mora.\" Tada reče Ilija: \"Idi, kaži Ahabu: \'Upregni i silazi da te kiša ne uhvati.\'\"');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 18, 45, 'Odjednom se nebo zamrači od oblaka i vihora i pade jaka kiša. Ahab se pope na kola i odveze u Jizreel.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 18, 46, 'Ruka je Jahvina bila nad Ilijom te on, opasavši se, otrča pred Ahabom sve do u blizinu Jizreela.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 19, 1, 'Ahab ispriča Izebeli sve što je Ilija učinio i kako je mačem poubijao sve proroke.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 19, 2, 'Tada Izebela posla Iliji glasnika s porukom: \"Neka mi bogovi učine sva zla i neka nadodadu, ako sutra u ovo doba ne učinim s tvojim životom kao što si ti učinio sa životom svakoga od njih!\"');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 19, 3, 'On se uplaši, ustade i ode da bi spasio život. Došao je u Beer Šebu, koja je u Judeji, i otpustio ondje svoga momka.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 19, 4, 'A sam ode dan hoda u pustinju; sjede ondje pod smreku, zaželje umrijeti i reče: \"Već mi je svega dosta, Jahve! Uzmi dušu moju, jer nisam bolji od otaca svojih.\"');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 19, 5, 'Zatim leže i zaspa. Ali gle, anđeo ga taknu i reče mu: \"Ustani i jedi.\"');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 19, 6, 'On pogleda, kad gle - kraj njegova uzglavlja na kamenu pečen kruh i vrč vode. Jeo je i pio, pa opet legao.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 19, 7, 'Ali se anđeo Jahvin javi i drugi put, dotače ga i reče: \"Ustani i jedi, jer je pred tobom dalek put!\"');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 19, 8, 'Ustao je, jeo i pio. Okrijepljen tom hranom, išao je četrdeset dana i četrdeset noći sve do Božje gore Horeba.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 19, 9, 'Ondje je ušao u neku spilju i prenoćio u njoj. I gle, eto k njemu riječi Jahvine: \"Što ćeš ti ovdje, Ilija?\"');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 19, 10, 'On odgovori: \"Revnovao sam gorljivo za Jahvu, Boga nad vojskama, jer su sinovi Izraelovi napustili tvoj Savez, srušili tvoje žrtvenike i pobili mačem tvoje proroke. Ostao sam sam, a oni traže da i meni uzmu život.\"');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 19, 11, 'Glas mu reče: \"Iziđi i stani u gori pred Jahvom. Evo Jahve upravo prolazi.\" Pred Jahvom je bio silan vihor, tako snažan da je drobio brda i lomio hridi, ali Jahve nije bio u olujnom vihoru; poslije olujnog vihora bio je potres, ali Jahve nije bio u potresu;');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 19, 12, 'a poslije potresa bio je oganj, ali Jahve nije bio u ognju; poslije ognja šapat laganog i blagog lahora.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 19, 13, 'Kad je to čuo Ilija, zakri lice plaštem, iziđe i stade na ulazu u pećinu. Tada mu progovori glas i reče: \"Što ćeš ovdje, Ilija?\"');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 19, 14, 'On odgovori: \"Revnovao sam veoma gorljivo za Jahvu nad vojskama, jer su sinovi Izraelovi napustili tvoj Savez, srušili tvoje žrtvenike i mačem poubijali tvoje proroke. Ostadoh sam, a oni traže da i meni oduzmu život.\"');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 19, 15, 'Jahve mu reče: \"Idi, vrati se istim putem u damaščansku pustinju. Kad dođeš, pomaži ondje Hazaela za kralja aramskog.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 19, 16, 'Pomaži Jehuu, sina Nimsijeva, za kralja izraelskoga i pomaži Elizeja, sina Šafatova, iz Abel Mehole, za proroka namjesto sebe.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 19, 17, 'Koji utekne od mača Hazaelova, njega će pogubiti Jehu; a tko utekne od Jehuova mača, njega će pogubiti Elizej.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 19, 18, 'Ali ću ostaviti u Izraelu sedam tisuća, sve koljena koja se nisu savila pred Baalom i sva usta koja ga nisu cjelivala.\"');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 19, 19, 'Ode on i na povratku naiđe na Elizeja, sina Šafatova, gdje ore: pred njim dvanaest jarmova, sam bijaše kod dvanaestoga. Ilija prođe kraj njega i baci na nj svoj plašt.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 19, 20, 'On ostavi volove, potrča za Ilijom i reče: \"Dopusti mi da zagrlim svoga oca i majku, pa ću poći za tobom.\" Ilija mu odgovori: \"Idi, vrati se, jer što sam ti učinio?\"');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 19, 21, 'On ga ostavi, uze jaram volova i žrtvova ih. Volujskim jarmom skuha meso i dade ga ljudima da jedu. Zatim ustade i pođe za Ilijom da ga poslužuje.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 20, 1, 'Ben-Hadad, kralj Arama, skupi svu vojsku svoju - s njim bijahu trideset i dva kralja, s konjima i bojnim kolima - i ode opsjedati Samariju i udari na nju.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 20, 2, 'Posla u grad glasnike izraelskom kralju Ahabu');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 20, 3, 'i reče mu: \"Ovako veli Ben-Hadad: \'Tvoje srebro i tvoje zlato moje je, a žene tvoje i djeca ostaju tebi.\'\"');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 20, 4, 'Izraelski kralj ovako mu odgovori: \"Na tvoju zapovijed, gospodaru kralju! Tvoj sam ja sa svime što mi pripada.\"');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 20, 5, 'Ali se glasnici vratiše i rekoše: \"Ovako kaže Ben-Hadad i poručuje ti: \'Daj mi svoje srebro i zlato, svoje žene i djecu.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 20, 6, 'Budi siguran da ću sutra u ovo doba poslati svoje sluge i oni će pretražiti tvoju kuću i kuće tvojih sluga i stavit će svoju ruku na sve što im se svidi i to će odnijeti.\'\"');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 20, 7, 'Izraelski kralj sazva sve starješine zemaljske i reče: \"Promislite i pogledajte! Ovaj nam sprema zlo! Traži od mene moje žene i djecu, premda mu nisam odbio svoje srebro i zlato.\"');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 20, 8, 'Starješine mu i sav narod odgovoriše: \"Nemoj poslušati! Nemoj pristati!\"');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 20, 9, 'Tada on ovako odgovori Ben-Hadadovim poslanicima: \"Recite gospodaru kralju: \'Sve što si prvi put tražio od svoga sluge, ja ću učiniti, ali ovo drugo ne mogu.\'\" I poslanici odoše i odnesoše odgovor.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 20, 10, 'Tada mu Ben-Hadad poruči: \"Neka mi bogovi učine zlo i neka pridaju još toliko, ako bude dosta praha Samarije da svi oni koji me slijede dobiju po pregršt!\"');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 20, 11, 'Ali mu kralj izraelski odgovori: \"Kaže se: \'Neka se ne hvali koji se opasuje kao onaj koji se raspasuje!\'\"');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 20, 12, 'A kad je Ben-Hadad to čuo - upravo je pio s kraljevima pod šatorima - zapovjedi svojim slugama: \"Na svoja mjesta!\" I oni zauzeše svoje položaje protiv grada.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 20, 13, 'Tada potraži jedan prorok Ahaba, kralja Izraela, i reče: \"Ovako veli Jahve: \'Jesi li vidio ono silno mnoštvo? Ja ću ti ga danas evo predati u ruke i ti ćeš spoznati da sam ja Jahve.\'\"');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 20, 14, 'Ahab reče: \"Po kome?\" On odgovori: \"Ovako veli Jahve: po momcima pokrajinskih namjesnika.\" Ahab upita: \"Tko će početi boj?\" On odgovori: \"Ti!\"');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 20, 15, 'Ahab izvrši smotru momaka pokrajinskih upravitelja. Bijaše ih dvije stotine trideset i dva. Poslije njih izvršio je smotru sve vojske svih Izraelaca. Bijaše ih sedam tisuća.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 20, 16, 'Oni iziđoše u podne, dok je Ben-Hadad pio u šatorima sa trideset i dva kralja koji mu bijahu saveznici.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 20, 17, 'Momci pokrajinskih upravitelja iziđoše prvi. Obavijestiše Ben-Hadada: \"Izišli su ljudi iz Samarije.\"');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 20, 18, 'On reče: \"Ako su izišli radi mira, pohvatajte ih žive; ako su izišli u boj, opet ih uhvatite žive!\"');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 20, 19, 'Ali kad su oni - momci pokrajinskih upravitelja - izišli iz grada, za njima je slijedila ostala vojska');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 20, 20, 'i svaki je udario na svog protivnika. Aramejci su bježali, a Izraelci ih progonili. Ben-Hadad, aramejski kralj, spasio se na konju zajedno s nekim konjanicima.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 20, 21, 'Tada je izišao izraelski kralj; zarobio je konje i kola i nanio Aramejcima težak poraz.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 20, 22, 'Tada pristupi prorok izraelskom kralju i reče mu: \"Hajdemo! Ohrabri se i razmisli dobro što ti je činiti, jer će dogodine aramejski kralj napasti na te.\"');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 20, 23, 'Sluge su savjetovale aramejskog kralja: Njihov bog je bog gora, i zato su bili jači od nas. Ali ako se pobijemo s njima u ravnici, sigurno ćemo mi biti jači od njih.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 20, 24, 'Učinimo dakle ovako: makni ove kraljeve i postavi na njihovo mjesto upravitelje.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 20, 25, 'Zatim skupi sebi veliku vojsku kolika je bila ona koju si izgubio, toliko konja i toliko kola. Tada ćemo se pobiti s njima u ravnici, i sigurno ćemo ih nadvladati.\" On ih posluša i učini tako.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 20, 26, 'Na početku godine Ben-Hadad podiže Aramejce i pođe na Afek da vojuje s Izraelom.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 20, 27, 'Izraelci se podigoše i krenuše protiv njih. I utaboriše se Izraelci pred njima kao dva mala stada koza, dok su Aramejci prekrili zemlju.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 20, 28, 'Tada pristupi Božji čovjek izraelskom kralju i reče: \"Ovako veli Jahve: \'Zato što Aramejci kažu za Jahvu da je Bog bregova i da nije Bog ravnica, ja ću predati u tvoje ruke ovo silno mnoštvo da spoznate da sam ja Jahve\'.\"');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 20, 29, 'Sedam dana bijahu utaboreni jedni sučelice drugima. Sedmoga dana zametnu se boj i Izraelci poubijaše Aramejce, stotinu tisuća pješaka u jedan jedini dan.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 20, 30, 'Ostatak pobježe u Afek, u grad, ali se sruši zidina na dvadeset i sedam tisuća ljudi koji su ostali. Pobjegao je i Ben-Hadad. U gradu je prelazio iz jednog skrovišta u drugo.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 20, 31, 'Njegove su mu sluge rekle: \"Gle! Mi smo čuli da su izraelski kraljevi milosrdni. Stavimo kostrijet oko bokova svojih i konope oko svojih glava, pa izađimo pred kralja izraelskog: možda će ti poštedjeti život.\"');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 20, 32, 'I svezaše kostrijeti oko bokova svojih i konopce oko svojih glava. Otišli su pred izraelskog kralja i rekli: \"Tvoj sluga Ben-Hadad kaže: \'Ostavi me na životu!\'\" On odgovori: \"Je li još živ? On je moj brat.\"');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 20, 33, 'Ljudi su to uzeli kao dobar znak i požurili se da ga uhvate za riječ govoreći: \"Ben-Hadad tvoj je brat.\" Ahab odgovori: \"Idite! Dovedite ga!\" Ben-Hadad dođe i on ga uze na kola.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 20, 34, 'Ben-Hadad reče mu tada: \"Vratit ću ti gradove koje je moj otac uzeo tvome ocu; stajat će ti na raspolaganju četvrti u Damasku, kao što ih je postavio moj otac u Samariji. Pod ovim me uvjetom otpusti.\" Ahab sklopi s njime savez i otpusti ga.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 20, 35, 'Neki od proročkih sinova reče po Jahvinoj zapovijedi svome drugu: \"Udari me!\" Ali čovjek ne htjede da ga tuče.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 20, 36, 'Tada mu onaj reče: \"Budući da nisi slušao glasa Jahvina, evo, kad odeš od mene, lav će te razderati.\" Tek što se udaljio od njega, naiđe na lava koji ga razdera.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 20, 37, 'Prorok nađe drugoga čovjeka i reče: \"Udari me!\" Čovjek ga izudara i izrani.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 20, 38, 'Prorok ode, postavi se kralju na put, a preko očiju navuče povez da ga ne prepoznaju.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 20, 39, 'Kad je kralj prolazio, on povika: \"Tvoj je sluga bio izišao u boj, kadli iz bojnih redova jedan istupi i dovede mi nekog čovjeka govoreći: \'Čuvaj ovoga čovjeka! Ako nestane, tvoj će život biti za njegov život, ili ćeš platiti srebrni talenat.\'');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 20, 40, 'I dok je tvoj sluga radio ovdje-ondje, njega je nestalo.\" Tada mu reče kralj Izraela: \"Eto ti presude! Sam si je izrekao!\"');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 20, 41, 'Nato onaj odmah ukloni povez s očiju i kralj izraelski vidje da je to jedan od proroka.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 20, 42, 'A on reče kralju: \"Ovako veli Jahve: \'Budući da si pustio da ti iz ruke utekne čovjek koga sam udario prokletstvom, tvoj će život biti za njegov život, tvoj narod za njegov narod.\'\"');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 20, 43, 'I kralj izraelski ode svojoj kući, mrk i srdit, i uđe u Samariju.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 21, 1, 'Nakon tih događaja dogodilo se ovo: Nabot Jizreelac imao vinograd kraj palače Ahaba, kralja samarijskog,');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 21, 2, 'i Ahab ovako reče Nabotu: \"Ustupi mi svoj vinograd da mi bude za povrtnjak jer je blizu moje kuće. Ja ću ti dati za nj bolji vinograd, ili, ako to želiš, dat ću ti novca koliko vrijedi.\"');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 21, 3, 'Ali Nabot reče Ahabu: \"Jahve me sačuvao od toga da ti ustupim baštinu svojih otaca!\"');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 21, 4, 'Ahab se vrati kući mrk i ljutit zbog riječi koju mu je Nabot Jizreelac rekao: \"Ne dam ti baštine svojih otaca.\" Legao je na postelju i okrenuo lice i nije htio okusiti hrane.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 21, 5, 'Dođe mu njegova žena Izebela i reče: \"Zašto si zlovoljan i ne mariš za hranu?\"');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 21, 6, 'On joj odgovori: \"Govorio sam Nabotu Jizreelcu i rekao mu: \'Ustupi mi svoj vinograd za novac, ili, ako ti je draže, dat ću ti drugi vinograd za taj.\' Ali mi je on rekao: \'Ne dam ti svoga vinograda.\'\"');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 21, 7, 'Tada mu žena Izebela reče: \"Jesi li ti onaj koji kraljuje nad Izraelom! Ustani i jedi i budi dobre volje. Ja ću ti pribaviti vinograd Nabota Jizreelca.\"');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 21, 8, 'I napisa ona pisma u ime Ahabovo i zapečati ih kraljevskim pečatom. Pisma je poslala starješinama i glavarima Nabotovim sugrađanima.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 21, 9, 'U tim je pismima napisala: \"Proglasite post i postavite Nabota na čelo naroda.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 21, 10, 'Postavite prema njemu dva nitkova koji će ga optužiti: \'Proklinjao si Boga i kralja!\' Tada ga izvedite i kamenujte ga da pogine.\"');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 21, 11, 'I učiniše ljudi Nabotova grada, starješine i glavari, kako im je Izebela zapovjedila i kako je pisalo u pismima koja im je uputila.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 21, 12, 'Proglasiše post i Nabota postaviše na čelo naroda.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 21, 13, 'Tada dođoše dva nitkova, sjedoše mu nasuprot i optužiše Nabota pred narodom: \"Nabot je proklinjao Boga i kralja.\" I tako izvedoše Nabota izvan grada, zasuše ga kamenjem i on pogibe.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 21, 14, 'Zatim poručiše Izebeli: \"Nabot je kamenovan i umro je.\"');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 21, 15, 'Pošto je Izebela čula da je Nabot kamenovan i da je umro, reče Ahabu: \"Ustani i zaposjedni vinograd što ti ga Nabot Jizreelac ne htjede ustupiti za novac. Nabot više nije živ, on je mrtav.\"');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 21, 16, 'Kada je Ahab doznao da je Nabot mrtav, ustade i siđe u vinograd Nabota Jizreelca da ga zaposjedne.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 21, 17, 'Tada bi upućena riječ Jahvina Iliji Tišbijcu:');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 21, 18, '\"Ustani i siđi u Samariju, u susret Ahabu, kralju izraelskom. Eno ga u vinogradu Nabotovu u koji je sišao da ga zaposjedne.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 21, 19, 'Reci mu: \'Ovako veli Jahve: Umorio si, oteo si! Zato ovako veli Jahve: Na mjestu gdje su psi lizali Nabotovu krv, lizat će psi i tvoju.\'\"');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 21, 20, 'Ahab reče Iliji: \"Nađe li me, neprijatelju moj?\" Ilija odgovori: \"Nađoh te, jer si se prodao da činiš što je zlo u očima Jahvinim.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 21, 21, 'Evo, tek što nisam navukao na te nesreću. Pomest ću tvoje potomstvo, istrijebiti Ahabu sve što mokri uza zid, robove i slobodnjake u Izraelu.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 21, 22, 'Učinit ću s tvojom kućom kao s kućom Jeroboama, sina Nebatova, i s kućom Baše, sina Ahijina, jer si me rasrdio i naveo Izraela na grijeh.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 21, 23, 'I nad Izebelom reče Jahve: psi će proždrijeti Izebelu na Jizreelskom polju.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 21, 24, 'Tko od obitelji Ahabove umre u gradu, psi će ga izjesti, a tko umre u polju, pojest će ga ptice nebeske.\"');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 21, 25, 'Doista, nitko se nije prodao tako kao Ahab da čini što je zlo u očima Jahvinim, jer ga je zavodila njegova žena Izebela.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 21, 26, 'Činio je vrlo odvratna djela: išao je za idolima baš kao što su činili Amorejci, koje je Jahve protjerao ispred Izraelaca.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 21, 27, 'Kad je Ahab čuo te riječi, razdrije svoje haljine i stavi kostrijet na tijelo; i postio je, u kostrijeti je spavao i naokolo išao tiho jecajući.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 21, 28, 'Tada dođe riječ Jahvina Iliji Tišbijcu:');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 21, 29, '\"Jesi li vidio kako se Ahab preda mnom ponizio? Budući da se tako ponizio preda mnom, neću zla pustiti za njegova života; u vrijeme njegova sina pustit ću zlo na kuću njegovu.\"');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 22, 1, 'Tri je godine vladao mir; nije bilo rata između Aramejaca i Izraela.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 22, 2, 'Treće godine Jošafat, kralj judejski, posjeti kralja izraelskoga.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 22, 3, 'Kralj Izraela reče svojim dvoranima: \"Znate li da je Ramot Gilead naš? A mi ne poduzimamo ništa da ga otmemo iz ruke aramejskog kralja.\"');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 22, 4, 'Zatim reče Jošafatu: \"Hoćeš li poći sa mnom na Ramot Gilead?\" Jošafat odgovori kralju izraelskom: \"Ja sam kao i ti, moj narod kao i tvoj, moji konji što i tvoji.\"');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 22, 5, 'Tada Jošafat reče kralju izraelskom: \"De posavjetuj se najprije s Jahvom.\"');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 22, 6, 'Tada kralj izraelski sakupi oko četiri stotine proroka i upita ih: \"Mogu li zavojštiti na Ramot Gilead ili da se okanim toga?\" Oni odgovoriše: \"Idi, jer će ga Jahve predati kralju u ruke.\"');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 22, 7, 'Ali Jošafat upita: \"Ima li ovdje još koji prorok Jahvin da i njega upitamo?\"');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 22, 8, 'Kralj izraelski odgovori Jošafatu: \"Ima još jedan čovjek preko koga bismo mogli upitati Jahvu, ali ga ne podnosim jer mi ne prorokuje ništa dobro nego samo zlo; to je Mihej, sin Jimlin.\" A Jošafat reče: \"Neka kralj ne govori tako!\"');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 22, 9, 'Tada kralj izraelski dozva jednoga dvoranina i reče mu: \"Brže dovedi Jimlina sina Miheja.\"');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 22, 10, 'Izraelski kralj i judejski kralj Jošafat sjedili su svaki na svome prijestolju, u svečanim haljinama pred Samarijskim vratima, a proroci proricali pred njima.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 22, 11, 'Kenaanin sin Sidkija napravi sebi željezne rogove i reče: \"Ovako govori Jahve: \'Njima ćeš nabosti sve Aramejce dok ih ne uništiš\'.\"');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 22, 12, 'Tako su i svi drugi proroci proricali govoreći: \"Idi na Ramot Gilead i uspjet ćeš: Jahve će ga predati kralju u ruke.\"');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 22, 13, 'Glasnik koji bijaše otišao da zove Miheja reče mu: \"Eno, svi proroci složno proriču dobro kralju. Govori i ti kao jedan od njih i proreci mu uspjeh!\"');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 22, 14, 'Ali Mihej odvrati: \"Živoga mi Jahve, govorit ću ono što mi Jahve kaže!\"');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 22, 15, 'Kad dođe pred kralja, upita ga kralj: \"Miheju, da pođem u rat na Ramot Gilead ili da se okanim toga?\" On odgovori: \"Pođi! Uspjet ćeš: Jahve će ga dati u ruke kraljeve.\"');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 22, 16, 'Ali mu kralj reče: \"Koliko ću te puta zaklinjati da mi kažeš samo istinu u Jahvino ime?\"');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 22, 17, 'Tada Mihej odgovori: \"Sav Izrael vidim rasut po gorama kao stado bez pastira. I Jahve veli: \'Nemaju više gospodara, neka se u miru kući vrate.\'\"');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 22, 18, 'Tada izraelski kralj reče Jošafatu: \"Nisam li ti rekao da mi neće proreći dobro nego zlo!\"');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 22, 19, 'A Mihej reče: \"Zato čuj riječ Jahvinu: vidio sam Jahvu gdje sjedi na svome prijestolju, a sva mu vojska nebeska stajaše zdesna i slijeva.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 22, 20, 'Jahve upita: \'Tko će zavesti Ahaba da otiđe i padne u Ramot Gileadu?\' Jedan reče ovo, drugi ono.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 22, 21, 'Tada uđe jedan duh i stade pred Jahvu. \'Ja ću ga\', reče, \'zavesti.\' Jahve ga upita: \'Kako?\'');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 22, 22, 'On odgovori: \'Izaći ću i bit ću lažljiv duh u ustima svih njegovih proroka.\' Jahve reče: \'Ti ćeš ga zavesti. I uspjet ćeš. Idi i učini tako!\'');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 22, 23, 'Tako je, evo, Jahve stavio lažljiva duha u usta svih ovih tvojih proroka, ali ti Jahve navješćuje zlo.\"');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 22, 24, 'Tada pristupi Kenaanin sin Sidkija i udari Miheja po obrazu pitajući: \"Zar je Jahvin duh napustio mene da bi s tobom govorio?\"');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 22, 25, 'Mihej odgovori: \"Vidjet ćeš onoga dana kad budeš bježao iz sobe u sobu da se sakriješ.\"');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 22, 26, 'Tada izraelski kralj naredi: \"Uhvati Miheja i odvedi ga gradskom zapovjedniku Amonu i kraljeviću Joašu.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 22, 27, 'Reci im: Ovako veli kralj: \'Bacite ovoga u tamnicu i držite ga na suhu kruhu i vodi dok se sretno ne vratim.\'\"');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 22, 28, 'Mihej reče: \"Ako se doista sretno vratiš, onda Jahve nije govorio iz mene.\" I nadoda: \"Čujte, svi puci!\"');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 22, 29, 'Izraelski kralj i judejski kralj Jošafat krenuše na Ramot Gilead.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 22, 30, 'Izraelski kralj reče Jošafatu: \"Ja ću se preobući i onda ući u boj, ali ti ostani u svojoj odjeći!\" Izraelski se kralj preobuče i pođe u boj.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 22, 31, 'Aramejski kralj naredi zapovjednicima bojnih kola: \"Ne napadajte ni na maloga ni na velikoga, nego jedino na izraelskog kralja!\"');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 22, 32, 'Kad zapovjednici bojnih kola ugledaše Jošafata, rekoše: \"To je kralj izraelski!\" I krenuše u boj prema njemu. A Jošafat povika.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 22, 33, 'A kad zapovjednici bojnih kola vidješe da to nije izraelski kralj, okrenuše se od njega.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 22, 34, 'Jedan nasumce odape luk i ustrijeli izraelskog kralja između nabora pojasa i oklopa. Kralj reče vozaču: \"Okreni, izvedi me iz boja jer mi nije dobro.\"');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 22, 35, 'Boj je onoga dana bio sve žešći, ali se kralj držao uspravno na bojnim kolima prema Aramejcima. A navečer umrije. Krv se iz rane izlila u kola.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 22, 36, 'O zalasku sunčevu odjeknu glas taborom: \"Svaki u svoj grad i svaki u svoju zemlju!');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 22, 37, 'Kralj je poginuo!\" Otišli su u Samariju i pokopali kralja u Samariji.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 22, 38, 'Njegova su kola oprali u samarijskom ribnjaku, psi su lizali njegovu krv i bludnice se ondje kupale, po riječi koju je rekao Jahve.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 22, 39, 'Ostala povijest Ahabova, sve što je učinio, o kući od bjelokosti, o svim gradovima koje je sagradio, zar sve to nije zapisano u knjizi Ljetopisa kraljeva izraelskih?');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 22, 40, 'Ahab je počinuo sa svojim ocima, a njegov sin Ahazja zakralji se mjesto njega.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 22, 41, 'Jošafat, sin Asin, postade kraljem Judeje četvrte godine kraljevanja Ahaba, kralja izraelskoga.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 22, 42, 'Jošafatu bijaše trideset i pet godina kad se zakraljio; kraljevao je dvadeset i pet godina u Jeruzalemu; mati mu se zvala Azuba, a bila je kći Šilhijeva.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 22, 43, 'Išao je sasvim putem oca Ase, ne skrećući s njega, nego čineći što je pravo u očima Jahvinim.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 22, 44, 'Samo, uzvišice nisu bile uklonjene, narod je još prinosio klanice i kađenice na uzvišicama.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 22, 45, 'Jošafat je bio u miru s izraelskim kraljem.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 22, 46, 'Ostala povijest Jošafatova, pothvati koje je izveo i kako je vojevao, zar to nije zapisano u knjizi Ljetopisa kraljeva judejskih?');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 22, 47, 'Istrijebio je iz zemlje preostale bludnice, koje su se održale iz vremena njegova oca Ase.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 22, 48, 'Nije bilo kralja u Edomu, nego je vladao namjesnik.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 22, 49, 'Kralj Jošafat sagradi taršiško brodovlje da ide u Ofir po zlato, ali nije otišlo jer se brodovlje razbilo kod Esjon Gebera.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 22, 50, 'Tada Ahazja, sin Ahabov, reče Jošafatu: \"Neka moje sluge pođu s tvojim slugama na lađama.\" Ali Jošafat to ne prihvati.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 22, 51, 'Jošafat počinu sa svojim ocima i sahranjen bi u gradu Davida, svoga praoca. Na njegovo se mjesto zakraljio sin mu Joram.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 22, 52, 'Ahazja, sin Ahabov, postade kraljem Izraela u Samariji sedamnaeste godine Jošafatova kraljevanja Judejom i kraljevao je dvije godine nad Izraelom.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 22, 53, 'On je činio što je zlo u očima Jahvinim i hodio je putem svoga oca i putem svoje majke i putem Jeroboama, sina Nebatova, koji je navodio Izraela na grijeh.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 22, 54, 'Služio je Baalu i klanjao se pred njim. Srdio je Jahvu, Boga Izraelova, sasvim onako kako je činio njegov otac.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 1, 1, 'Poslije smrti Ahabove pobuni se Moab protiv Izraela.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 1, 2, 'Kako Ahazja bijaše pao preko prozorske rešetke svoje gornje odaje u Samariji i ozlijedio se, posla glasnike kojima reče: \"Idite, pitajte Baal Zebuba, boga ekronskog, hoću li ozdraviti od ove bolesti.\"');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 1, 3, 'Ali je Anđeo Jahvin rekao Iliji Tišbijcu: \"Ustani! Idi u susret glasnicima samarijanskoga kralja i reci im: \'Zar nema Boga u Izraelu te se idete savjetovati s Baal Zebubom, bogom ekronskim?\'');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 1, 4, 'I zato veli Jahve ovako: \'Nećeš sići s postelje u koju si se popeo; sigurno ćeš umrijeti.\'\" I ode Ilija.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 1, 5, 'Glasnici se vratiše k Ahazji, a on im reče: \"Kako to da ste se već vratili?\"');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 1, 6, 'Oni mu odgovoriše: \"Sreo nas neki čovjek i rekao nam: \'Idite, vratite se pred kralja koji vas je poslao i recite mu: Ovako veli Jahve: Zar nema Boga u Izraelu te si poslao po savjet k Baal Zebubu, bogu ekronskom? Zato nećeš sići s postelje na koju si se popeo, nego ćeš umrijeti.\'\"');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 1, 7, 'On ih upita: \"Kakav bijaše na oči taj čovjek koji vas je sreo i rekao vam te riječi?\"');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 1, 8, 'A oni mu odgovoriše: \"Bio je to čovjek u kožuhu i s kožnim pojasom oko bedara.\" On reče: \"To je Ilija Tišbijac!\"');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 1, 9, 'Tada mu posla pedesetnika s njegovom pedesetoricom i ode taj k njemu i, našavši ga gdje sjedi na vrhu brijega, reče mu: \"Čovječe Božji! Kralj je naredio: Siđi!\"');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 1, 10, 'Ilija odgovori i reče pedesetniku: \"Ako sam čovjek Božji, neka oganj siđe s neba i neka te proguta, tebe i tvoju pedesetoricu.\" I oganj se spusti s neba i proguta ga, njega i njegovu pedesetoricu.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 1, 11, 'Kralj mu posla drugoga pedesetnika i njegovu pedesetoricu; a taj, kad dođe, reče mu: \"Čovječe Božji! Kralj je ovo zapovjedio: Brže siđi!\"');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 1, 12, 'Ilija odgovori i reče mu: \"Ako sam čovjek Božji, neka siđe oganj s neba i proguta tebe i tvoju pedesetoricu.\" I spusti se oganj s neba i proguta ga, njega i njegovu pedesetoricu.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 1, 13, 'Kralj posla opet trećega pedesetnika i njegovu pedesetoricu. Treći pedesetnik dođe, prignu koljena pred Ilijom i zamoli ga ovako: \"Čovječe Božji! Neka bude dragocjen u tvojim očima moj život i život ovih pedeset tvojih slugu!');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 1, 14, 'Oganj se spustio s neba i progutao je oba pedesetnika s njihovom pedesetoricom; ali sada neka barem moj život bude dragocjen u tvojim očima!\"');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 1, 15, 'Anđeo Jahvin reče Iliji: \"Siđi s njim, ne boj se!\" On ustade i siđe s njim pred kralja');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 1, 16, 'i reče mu: \"Ovako veli Jahve: zato što si slao glasnike Baal Zebubu, bogu ekronskom, po savjet, nećeš sići s postelje na koju si se popeo, nego ćeš umrijeti.\"');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 1, 17, 'I umrije po riječi Jahvinoj koju je objavio Ilija. A Joram, njegov brat, zakralji se mjesto njega druge godine Jorama, sina Jošafata, judejskoga kralja, jer ovaj nije imao sinova.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 1, 18, 'Ostala povijest Ahazje, sve što je učinio, zar to nije zapisano u knjizi Ljetopisa kraljeva izraelskih?');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 2, 1, 'Evo što se dogodilo kad je Jahve uznio Iliju na nebo u vihoru: Ilija i Elizej pošli iz Gilgala.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 2, 2, 'I reče Ilija Elizeju: \"Ostani ovdje jer me Jahve šalje do Betela.\" Elizej odgovori: \"Života mi Jahvina i tvoga: ja te neću ostaviti!\" I siđoše do Betela.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 2, 3, 'A proročki sinovi koji su boravili u Betelu iziđoše Elizeju u susret i rekoše mu: \"Znaš li da će danas Jahve uzeti tvoga gospodara iznad tvoje glave?\" On reče: \"I ja to znam; tiho!\"');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 2, 4, 'Ilija mu reče: \"Elizeju! Ostani ipak ovdje jer me Jahve šalje do Jerihona.\" Ali on odgovori: \"Života mi Jahvina i tvoga: ja te neću ostaviti!\" I uđoše u Jerihon.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 2, 5, 'Proročki sinovi koji su živjeli u Jerihonu priđoše Elizeju i rekoše mu: \"Znaš li da će danas Jahve uzeti tvoga gospodara iznad tvoje glave?\" On reče: \"I ja to znam; tiho!\"');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 2, 6, 'Ilija mu reče: \"Ostani ipak ovdje jer me Jahve šalje do Jordana.\" Ali on odgovori: \"Života mi Jahvina i tvoga: ja te neću ostaviti!\" I tako pođoše obojica.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 2, 7, 'I pedeset proročkih sinova pođe i zaustavi se podalje, dok su se njih dvojica zadržala na obali Jordana.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 2, 8, 'Tada Ilija uze svoj ogrtač, smota ga i udari njime po vodi, a voda se razdijeli na dvije strane. I obojica prijeđoše po suhu.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 2, 9, 'A kad prijeđoše, Ilija će Elizeju: \"Traži što da ti još učinim prije nego što budem uznesen ispred tebe!\" A Elizej odgovori: \"Neka mi u dio padne obilje tvoga duha!\"');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 2, 10, 'Ilija odgovori: \"Mnogo tražiš: ako me budeš vidio kad budem uznesen ispred tebe, bit će ti tako; ako pak ne budeš vidio, neće ti biti.\"');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 2, 11, 'I dok su tako išli i razgovarali, gle: ognjena kola i ognjeni konji stadoše među njih i Ilija u vihoru uziđe na nebo.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 2, 12, 'Elizej je gledao i vikao: \"Oče moj, oče moj! Kola Izraelova i konjanici njegovi!\" I više ga nije vidio. Uze tada svoje haljine i razdera ih nadvoje.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 2, 13, 'I podiže Ilijin plašt, koji bijaše pao s njega, te se vrati i zaustavi se na obali Jordana.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 2, 14, 'Uze onda Ilijin plašt i udari po vodi govoreći: \"Gdje je Jahve, Bog Ilijin?\" I kad udari po vodi, ona se razdijeli na dvije strane i Elizej prijeđe.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 2, 15, 'Proročki su sinovi to sa strane vidjeli pa rekoše: \"Duh je Ilijin počinuo na Elizeju!\" I krenuše mu u susret, baciše se pred njim na zemlju');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 2, 16, 'i rekoše mu: \"Evo ovdje s tvojim slugama pedeset junaka. Dopusti im da idu tražiti tvoga gospodara; možda ga je Duh Jahvin uzdigao i bacio na koju goru ili u kakvu dolinu.\" On im odgovori: \"Ne šaljite nikoga.\"');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 2, 17, 'Ali kako su oni svejednako navaljivali, reče im: \"Pošaljite!\" I poslaše pedesetoricu; tražili su ga tri dana, ali ga nisu našli.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 2, 18, 'Vratiše se Elizeju, koji je ostao u Jerihonu, i on im reče: \"Nisam li vam rekao: \'Nemojte ići!\'\"');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 2, 19, 'Ljudi iz grada rekoše Elizeju: \"Lijepo je u gradu, kako to može vidjeti i naš gospodar, ali je voda loša i zemlja neplodna.\"');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 2, 20, 'On reče: \"Donesite mi novu zdjelu i metnite soli u nju!\" I oni mu je donesoše.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 2, 21, 'On tada ode na izvor, baci u nj soli i reče: \"Ovako govori Jahve: \'Ozdravljam ovu vodu. Neće od nje više biti ni smrti ni neplodnosti.\'\"');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 2, 22, 'I voda postade zdrava i takva je do današnjeg dana, po riječi koju je izrekao Elizej.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 2, 23, 'Odatle je uzašao u Betel. Dok je išao putem, dječaci bijahu izišli iz grada i rugahu mu se govoreći: \"Hodi, ćelo! Hodi, ćelo!\"');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 2, 24, 'On se obazre, pogleda ih i prokle ih u ime Jahvino. I odmah iziđoše dva medvjeda iz šume i rastrgaše četrdeset i dvoje djece.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 2, 25, 'Odatle ode on na goru Karmel, a odande se vrati u Samariju.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 3, 1, 'Joram, sin Ahabov, zakralji se nad Izraelom u Samariji osamnaeste godine Jošafatova kraljevanja u Judeji. I vladao je dvanaest godina.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 3, 2, 'Činio je što je zlo u očima Jahvinim, ali ne kao njegov otac i mati, jer je uklonio Baalov stup što ga bijaše podigao njegov otac.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 3, 3, 'Ali je prianjao uz grijeh kojim je Jeroboam, sin Nebatov, zavodio Izraela; i nije odstupao od njega.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 3, 4, 'Meša, kralj moapski, bio je stočar i slao je izraelskom kralju u danak stotinu tisuća janjaca i vunu od stotine tisuća ovnova.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 3, 5, 'Ali kad je umro Ahab, pobuni se kralj moapski protiv izraelskog kralja.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 3, 6, 'U to je baš vrijeme kralj Joram izišao iz Samarije i izvršio smotru svih Izraelaca.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 3, 7, 'Zatim je poručio judejskom kralju Jošafatu: \"Moapski se kralj pobunio protiv mene. Hoćeš li sa mnom u rat protiv Moabaca?\" Judejski kralj odgovori: \"Hoću! Ja kao ti, moj narod kao tvoj narod, moji konji kao i tvoji konji.\"');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 3, 8, 'I doda: \"Kojim ćemo putem?\" A drugi mu odgovori: \"Kroz Edomsku pustinju.\"');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 3, 9, 'I tako krenu izraelski kralj s judejskim kraljem i s kraljem edomskim. Sedam su dana lutali, a nije bilo vode četama ni stoci koja je išla za njima.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 3, 10, 'Tada povika kralj izraelski: \"Jao, Jahve je pozvao ova tri kralja da ih preda u ruke Moapcima!\"');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 3, 11, 'Ali Jošafat reče: \"Nema li tu proroka Jahvina da se preko njega posavjetujemo s Jahvom?\" Tada odgovori jedan između slugu izraelskoga kralja: \"Ovdje je Elizej, sin Šafatov, koji je lijevao vodu na Ilijine ruke.\"');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 3, 12, 'Jošafat reče: \"U njega je riječ Božja.\" I kralj izraelski, kralj judejski i kralj edomski odoše Elizeju.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 3, 13, 'A Elizej reče kralju izraelskom: \"Što ja imam s tobom? Potraži proroke svoga oca i proroke svoje majke!\" Izraelski kralj odgovori mu: \"Ne! Jer Jahve je pozvao ova tri kralja da ih preda u ruke Moapcima.\"');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 3, 14, 'Elizej uzvrati: \"Tako mi živoga Jahve Sebaota, komu služim, kad ne bih gledao na judejskog kralja Jošafata, ne bih ti obraćao pažnje niti bih te pogledao.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 3, 15, 'Sada mi dovedite svirača.\" I dok je glazbenik svirao, siđe ruka Jahvina nada nj.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 3, 16, 'I on reče: \"Ovako veli Jahve: \'Iskopajte u ovoj dolini mnogo jama.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 3, 17, 'Jer ovako veli Jahve: nećete osjetiti vjetra niti ćete vidjeti dažda, a ova će se dolina napuniti vodom. I pit ćete vi, vaš marva i vaša stoka.\'');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 3, 18, 'Ali to još nije ništa u očima Jahve: on će predati Moab u vaše ruke.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 3, 19, 'Vi ćete zauzeti sve utvrđene gradove, posjeći sve plodno drveće, zatrpati sve izvore i opustošiti najbolja polja: kamenjem ćete ih zasijati.\"');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 3, 20, 'I doista, ujutro, u vrijeme kad se prinosi žrtva, dođe voda od Edoma i preplavi svu okolinu.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 3, 21, 'Kad su Moapci čuli da su kraljevi došli s njima ratovati, pozvaše sve koji bijahu sposobni za oružje i postaviše ih na granicu.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 3, 22, 'Kad su ujutro ustali i kad je sunce granulo nad onom vodom, Moapcima se sa strane voda učini crvenom kao krv.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 3, 23, 'I rekoše: \"To je krv! Zacijelo su se kraljevi međusobno pobili i jedan drugoga pogubili. A sada: na plijen, Moapci!\"');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 3, 24, 'Ali kad su stigli do izraelskog tabora, digoše se Izraelci i potukoše Moapce, tako te ovi pobjegoše pred njima. A Izraelci pojuriše da dotuku Moapce.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 3, 25, 'Razorili su im gradove, bacali svaki po kamen na najbolje njive da ih zaspu, zatrpali izvore i posjekli sve plodno drveće. Konačno, ostao je samo grad Kir Harešet; praćari su ga opkolili i tukli ga.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 3, 26, 'Kada je moapski kralj vidio da neće izdržati bitku, uze sa sobom sedam stotina ljudi naoružanih mačevima, pokuša se probiti i doći do kralja edomskog, ali ne uspje.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 3, 27, 'Tada uze svoga sina prvenca, koji ga imaše naslijediti, i prinese ga kao paljenicu na zidu. To se tako silno zgadilo Izraelcima te odoše od njih i vratiše se u svoju zemlju.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 4, 1, 'Žena jednoga od proročkih sinova zamoli Elizeja ovako: \"Tvoj sluga, moj muž, umro je; a znaš da se tvoj sluga bojao Jahve. Sada je došao vjerovnik da mi uzme oba sina i učini ih svojim robovima.\"');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 4, 2, 'Elizej joj reče: \"Što ti mogu učiniti! Reci mi što imaš u kući?\" Ona odgovori: \"Tvoja sluškinja nema ništa u kući, osim vrča ulja.\"');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 4, 3, 'Tada joj reče: \"Idi i posudi od svih svojih susjeda praznih sudova, ali neka ih ne bude premalo!');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 4, 4, 'Zatim se vrati kući, zatvori vrata za sobom i za svojim sinovima i nalijevaj ulje u sve te sudove i pune stavljaj na stranu.\"');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 4, 5, 'I ode ona od njega, zatvori vrata za sobom i za svojim sinovima. Oni su joj dodavali sudove, a ona ih punila.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 4, 6, 'I kad se sudovi napuniše, reče ona svome sinu: \"Dodaj mi još jedan sud!\" Ali joj on odgovori: \"Nema više sudova.\" I ulje stade.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 4, 7, 'Ona ode i kaza čovjeku Božjem, a on joj reče: \"Idi, prodaj ulje i podmiri svoj dug, a od ostatka živjet ćeš ti i tvoji sinovi!\"');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 4, 8, 'Jednoga je dana Elizej prolazio kroza Šunam. A živjela ondje ugledna žena i ona ga pozva k stolu. Odonda, kad god prolazaše onuda, uvratio bi se k njoj na jelo.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 4, 9, 'Ona reče svome mužu: \"Evo, znam i vidim da je svet onaj čovjek Božji što prolazi ovuda.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 4, 10, 'Načinimo mu sobicu na krovu, stavimo mu ondje postelju, stol, stolicu i svjetiljku: kad dođe k nama, povući će se onamo.\"');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 4, 11, 'Jednoga dana dođe on onamo, povuče se u gornju sobu i počinu ondje.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 4, 12, 'Reče zatim svome momku Gehaziju: \"Pozovi tu Šunamku!\" On je pozva te ona stade preda nj.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 4, 13, 'I još mu reče: \"Kaži joj: \'Lijepo se brineš za nas. Što možemo učiniti za te? Treba li reći riječ za te kralju ili vojskovođi?\'\" Ali ona odgovori: \"Ja živim usred svoga naroda.\"');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 4, 14, 'On nastavi: \"Dakle, što da učinimo za nju?\" Gehazi odgovori: \"Eto, nema sina, a muž joj je vremešan.\"');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 4, 15, 'A on reče: \"Pozovi je!\" Pozva je, a ona stade kod ulaza.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 4, 16, '\"Dogodine u ovo doba\", reče joj, \"zagrlit ćeš sina u naručju.\" A ona reče: \"Ne, gospodaru moj, ne varaj službenice svoje!\"');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 4, 17, 'Ali je žena doista zatrudnjela i rodila je sina druge godine u ono doba, kako joj je rekao Elizej.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 4, 18, 'Dječak je rastao. Jednoga dana ode ocu kod žetelaca.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 4, 19, 'I potuži se ocu: \"Jao, glava, glava moja!\" A otac zapovjedi jednom momku da ga odnese majci.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 4, 20, 'On ga uze i odvede ga njegovoj majci. Na njenim je koljenima ostao do podne i onda umrije.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 4, 21, 'Ona tada ode gore i položi ga u postelju Božjega čovjeka. Izišla je zatim i zaključala vrata.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 4, 22, 'Potom je pozvala svoga muža i rekla: \"Pošalji mi jednoga od momaka i jednu magaricu; otrčat ću do čovjeka Božjeg i vratit ću se.\"');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 4, 23, 'On je upita: \"Zašto da danas pođeš k njemu? Nije ni mlađak niti je subota.\" Ali ona odgovori: \"Ostaj u miru!\"');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 4, 24, 'Pošto joj je momak osamario magaricu, ona će mu: \"Povedi i pođi! Ne zadržavaj me na putu, osim ako ti naredim.\"');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 4, 25, 'Ode ona i dođe k čovjeku Božjem, na goru Karmel. Kada je čovjek Božji ugleda izdaleka, reče svome momku Gehaziju: \"Evo one Šunamke.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 4, 26, 'Otrči pred nju i pitaj je: \'Kako si? Je li ti muž dobro? Je li ti dijete zdravo?\'\" Ona odgovori: \"Zdravi smo.\"');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 4, 27, 'Kada je stigla do čovjeka Božjega na gori, obujmi mu noge. Gehazi pristupi da je odmakne, ali mu čovjek Božji reče: \"Pusti je jer joj je duša ojađena. Jahve mi krije, nije mi ništa objavio.\"');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 4, 28, 'A ona reče: \"Zar sam ja tražila sina od svoga gospodara? Nisam li ti govorila da me ne zavaravaš?\"');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 4, 29, 'On tada reče Gehaziju: \"Opaši se, uzmi u ruku moj štap pa idi! Ako koga susretneš, ne pozdravljaj ga; ako te tko pozdravi, ne odzdravljaj mu. Moj štap položi na dječaka.\"');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 4, 30, 'Ali dječakova majka reče: \"Života mi Jahvina i tvoga, neću te ostaviti!\" On tada ustade i pođe za njom.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 4, 31, 'Gehazi je otišao prije njih i položio štap na dječaka, ali ne bješe ni glasa ni odziva. Vrati se on pred Elizeja i javi mu: \"Dječak se nije probudio.\"');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 4, 32, 'Elizej uđe u kuću i nađe dječaka gdje mrtav leži na njegovoj postelji.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 4, 33, 'Ušavši, zatvori vrata za sobom i pomoli se Jahvi.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 4, 34, 'Zatim se pope na postelju, leže na dječaka, položi svoja usta na njegova usta, svoje oči na njegove oči, svoje ruke na njegove ruke; disao je nad njim te se ugrijalo tijelo dječakovo.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 4, 35, 'Potom ustade i prošeta se po kući tamo-amo, zatim se opet pope i disaše nad njim. A dječak tada kihnu sedam puta i otvori oči.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 4, 36, 'I zovnu Elizej Gehazija i reče: \"Pozovi tu Šunamku.\" On je pozva. Kad je stigla preda nj, reče joj: \"Uzmi svoga sina.\"');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 4, 37, 'Ona, ušavši, pade mu pred noge i pokloni se do zemlje. Zatim uze svoga sina te iziđe.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 4, 38, 'Elizej se vrati u Gilgal, a bijaše glad u zemlji. I kad su proročki sinovi sjedili pred njim, reče svome momku: \"Stavi veliki lonac na vatru i skuhaj jelo sinovima proročkim.\"');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 4, 39, 'Jedan od njih ode u polje da nabere zelja, ali nađe divlju povijušu i nabra s nje punu haljinu gorkih plodova. Vrati se i nareza ih u lonac, jer nije znao kakvi su.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 4, 40, 'Usuše ljudima da jedu. Ali kad su počeli jesti, povikaše: \"Čovječe Božji! Smrt je u loncu!\" I nisu mogli jesti.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 4, 41, 'Tada će Elizej: \"Donesite brašna!\" I baci ga u lonac i reče: \"Uspite ljudima neka jedu!\" I ništa više nije bilo štetno u loncu.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 4, 42, 'Neki čovjek došao iz Baal Šališe i donio čovjeku Božjem kruh od prvina, dvadeset ječmenih hljebova i kaše u torbi. A on zapovjedi: \"Daj ljudima neka jedu!\"');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 4, 43, 'Ali njegov momak odgovori: \"Kako to mogu postaviti pred stotinu ljudi?\" On odgovori: \"Podaj ljudima i neka jedu, jer ovako veli Jahve: \'Jest će i preostat će.\'\"');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 4, 44, 'I postavi on pred njih. I jedoše i još preosta, prema riječi Jahvinoj.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 5, 1, 'Naaman, vojskovođa aramskoga kralja, bijaše ugledan čovjek i poštovan pred svojim gospodarom, jer je po njemu Jahve dao pobjedu Aramejcima. Ali taj vrsni ratnik bješe gubav.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 5, 2, 'Jednom su Aramejci otišli u pljačku i na području izraelskom zarobili mladu djevojku, koja je zatim služila ženi Naamanovoj.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 5, 3, 'Ona reče svojoj gospodarici: \"Ah, kad bi se samo moj gospodar obratio proroku koji je u Samariji! On bi ga zacijelo oslobodio gube!\"');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 5, 4, 'Naaman ode i obavijesti svoga gospodara: \"Tako je i tako rekla djevojka koja je došla iz zemlje izraelske.\"');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 5, 5, 'Aramejski kralj odgovori: \"Idi onamo! Ja ću poslati pismo kralju izraelskom.\" Naaman ode; ponio je deset talenata srebra; šest tisuća zlatnih šekela i deset svečanih haljina.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 5, 6, 'I predade kralju izraelskom pismo što kazivaše: \"Uz pismo koje ti stiže, šaljem ti, evo, svoga slugu Naamana da ga izliječiš od gube.\"');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 5, 7, 'Kad je izraelski kralj pročitao pismo, razdera haljine na sebi i reče: \"Zar sam ja Bog da mogu usmrćivati i oživljavati te ga ovaj šalje k meni da ga izliječim od njegove gube? Gledajte samo kako traži povoda da me napadne!\"');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 5, 8, 'A kad je Elizej saznao da je kralj izraelski razderao na sebi odjeću, poruči kralju: \"Zašto si razderao haljine svoje? Neka onaj samo dođe k meni i neka se uvjeri da ima prorok u Izraelu.\"');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 5, 9, 'I tako Naaman stiže sa svojim konjima i kolima i stade pred vratima Elizejeve kuće.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 5, 10, 'A Elizej poruči dolazniku: \"Idi i okupaj se sedam puta u Jordanu i tijelo će ti opet biti čisto.\"');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 5, 11, 'Naaman se naljuti i pođe govoreći: \"Gle, ja mišljah, izići će preda me, zazvat će ime Jahve, Boga svoga, stavit će ruku na bolesno mjesto i odnijeti mi gubu.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 5, 12, 'Nisu li rijeke u Damasku, Abana i Parpar, bolje od svih voda izraelskih? Ne bih li se mogao u njima okupati da postanem čist?\" Okrenu se i ode odande ljutit.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 5, 13, 'Ali mu pristupiše sluge njegove i rekoše: \"Oče moj, da ti je prorok odredio i teže, zar ne bi učinio? A nekmoli kad ti je rekao: \'Okupaj se, i bit ćeš čist.\'\"');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 5, 14, 'I tako siđe, opra se sedam puta u Jordanu, prema riječi čovjeka Božjega; i tijelo mu posta opet kao u malog djeteta - očistio se!');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 5, 15, 'Vrati se on Elizeju sa svom svojom pratnjom, uđe, stade preda nj i reče mu: \"Evo, sad znam da nema Boga na svoj zemlji, osim u Izraelu. Zato te molim, primi dar od svoga sluge.\"');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 5, 16, 'Ali on odgovori: \"Tako mi živog Jahve, komu služim, ne primam.\" Naaman navaljivaše da primi, ali on ne htjede.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 5, 17, 'Tada Naaman reče: \"Dobro, kad nećeš. Ali barem dopusti da meni, tvome sluzi, dadu ove zemlje koliko mogu ponijeti dvije mazge. Jer sluga tvoj neće više prinositi pomirnica ni klanica drugim bogovima nego samo Jahvi.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 5, 18, 'A Jahve neka oprosti ovo sluzi tvome: kad moj gospodar pođe u hram Rimonov da se ondje pokloni, pa se nasloni na moju ruku, onda bih se i ja poklonio u hramu Rimonovu. Neka Jahve oprosti taj čin sluzi tvome.\"');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 5, 19, 'A on mu reče: \"Idi s mirom.\" I udalji se Naaman i prijeđe dio puta.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 5, 20, 'Gehazi, momak Elizeja, Božjega čovjeka, pomisli: \"Moj je gospodar poštedio Naamana, toga Aramejca, i nije primio ništa od onoga što mu je ponudio. Tako mi živog Jahve, potrčat ću ja za njim i uzet ću štogod od njega.\"');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 5, 21, 'I Gehazi pohitje za Naamanom. Kada ga je Naaman vidio da za njim trči, skoči mu sa svojih kola u susret i upita ga: \"Je li sve dobro?\"');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 5, 22, 'On odgovori: \"Dobro je. Moj gospodar šalje me da ti kažem: upravo su stigla dva mladića iz Efrajimove gore, dvojica od proročkih sinova. Daj za njih, molim te, talenat srebra i dvoje haljine.\"');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 5, 23, 'Naaman reče: \"Uzmi, molim te, dva telenta!\" I navaljivaše da uzme. I zaveza dva talenta srebra u dvije kese, i dvoje haljine, i predade ih dvojici svojih momaka da ih nose pred njim.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 5, 24, 'Kad je Gehazi stigao do Ofela, uze ih iz njihovih ruku i pohrani ih u kući. Zatim otpusti ljude i oni odoše.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 5, 25, 'Kad je došao, stao je pred svoga gospodara. Elizej ga upita \"Odakle, Gehazi?\" On odgovori: \"Tvoj sluga nije nikamo odlazio.\"');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 5, 26, 'Ali Elizej reče: \"Nije li Duh moj bio s tobom kad je netko sišao sa svojih kola te izišao preda te? Sad si primio srebro, pa možeš kupiti maslinike, vinograde, sitno i krupno blago, sluge i sluškinje.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 5, 27, 'Ali će se guba Naamanova prilijepiti za te i za tvoje potomstvo zauvijek.\" I Gehazi se udalji od njega, bijel od gube kao od snijega.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 6, 1, 'Proročki sinovi rekoše Elizeju: \"Gle, tijesan nam je prostor u tebe.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 6, 2, 'Nego da odemo do Jordana, pa da svaki ondje uzmemo po brvno i načinimo sebi ondje prebivalište.\" On odgovori: \"Idite.\"');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 6, 3, 'Jedan od njih reče mu: \"Udostoj se poći sa svojim slugama.\" On odgovori: \"Hoću.\"');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 6, 4, 'I pođe s njima. Kad su stigli do Jordana, uzeše sjeći drva.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 6, 5, 'A dok je jedan od njih tesao gredu, pade mu sjekira u vodu i on povika: \"Jao, gospodaru! I još je bila posuđena!\"');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 6, 6, 'A čovjek Božji upita ga: \"Gdje je pala?\" Onaj mu pokaza mjesto. Tada on odsiječe komad drveta, baci ga na ono mjesto i učini da sjekira ispliva.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 6, 7, 'I reče: \"Izvadi je!\" I čovjek pruži ruku te je uze.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 6, 8, 'Aramejski kralj bio u ratu s Izraelom. Posavjetovao se sa svojim časnicima i rekao: \"Podignite šatore na tom mjestu.\"');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 6, 9, 'Ali Elizej poruči izraelskom kralju: \"Čuvaj se onoga mjesta jer su se Aramejci ondje utaborili.\"');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 6, 10, 'I kralj izraelski upozori ljude na mjesto za koje mu je rekao čovjek Božji. On je upozoravao i kralj se čuvao; a bilo je to više puta.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 6, 11, 'Srce aramejskog kralja uznemiri se zbog toga, pa on pozva svoje časnike te ih upita: \"Nećete li mi reći tko od naših drži s kraljem Izraelovim?\"');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 6, 12, 'Jedan od časnika odgovori: \"Ne, gospodaru kralju; Elizej, prorok Izraelov, otkriva izraelskom kralju riječi koje kazuješ u svojoj spavaonici.\"');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 6, 13, 'On reče: \"Idite i pogledajte gdje je, pa ću već poslati da ga uhvate.\" I javiše mu: \"Eno ga u Dotanu.\"');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 6, 14, 'Tada kralj posla onamo konje, kola i jake čete. Oni stigoše noću i opkoliše grad.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 6, 15, 'Ujutro, ustavši, čovjek Božji iziđe, a to oko grada stoji vojska s konjima i kolima! Njegov mu momak reče: \"Ah, gospodaru moj, što nam je činiti?\"');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 6, 16, 'A on odgovori: \"Ne boj se jer ih ima više s nama nego s njima.\"');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 6, 17, 'I Elizej se pomoli ovako: \"Jahve, otvori mu oči da vidi!\" I Jahve otvori oči momku i on vidje: gora oko Elizeja sva prekrivena ognjenim konjima i kolima!');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 6, 18, 'Kad su Aramejci sišli prema njemu, Elizej se ovako pomoli Jahvi: \"Udari sljepoćom ove ljude!\" I na riječ Elizejevu udari ih sljepoćom.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 6, 19, 'Elizej im reče: \"Nije ovo put i nije ovo grad. Pođite za mnom, ja ću vas odvesti čovjeku koga tražite.\" Ali ih odvede u Samariju.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 6, 20, 'Kad su ulazili u Samariju, Elizej reče: \"Jahve, otvori ovima oči da progledaju.\" Jahve im otvori oči i oni vidješe da su usred Samarije!');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 6, 21, 'Kad ih vidje kralj Izraela, reče Elizeju: \"Treba li ih poubijati, oče moj?\"');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 6, 22, 'A on odgovori: \"Nemoj ih ubiti. Zar ćeš ubiti one koje nisi zarobio svojim lukom i mačem? Ponudi im kruha i vode; neka jedu i piju i neka se vrate svome gospodaru.\"');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 6, 23, 'Kralj im priredi veliku gozbu. Pošto su jeli i pili, otpusti ih. I vratiše se svome gospodaru. I tako aramejski pljačkaši nisu više zalazili na izraelsko tlo.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 6, 24, 'Dogodi se poslije toga te aramejski kralj Ben-Hadad skupi svu svoju vojsku i uzađe i opkoli Samariju.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 6, 25, 'I nasta velika glad u Samariji, a opsada potraja toliko da je magareća glava stajala osamdeset šekela srebra, a četvrt kaba golubinje nečisti pet šekela srebra.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 6, 26, 'Kada je kralj prolazio po zidinama, neka mu žena vikne: \"Pomozi, gospodaru kralju!\"');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 6, 27, 'On odgovori: \"Neka ti pomogne Jahve! Kako ću ti ja pomoći? Nečim s gumna ili iz tijeska?\"');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 6, 28, 'Još joj kralj reče: \"Što ti je?\" Ona odgovori: \"Ova mi je žena rekla: \'Daj svoga sina da ga pojedemo danas, a sutra ćemo pojesti moga!\'');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 6, 29, 'Skuhale smo moga sina i pojele ga. A sutradan rekoh joj: \'Daj svoga sina da ga pojedemo.\' Ali je ona sakrila svoga sina.\"');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 6, 30, 'Kada je kralj čuo riječi te žene, razdrije na sebi haljine. I kad je išao po zidinama, narod vidje da mu je na tijelu kostrijet.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 6, 31, 'I reče tada kralj: \"Neka mi Bog učini ovo zlo i doda drugo ako glava Elizeja, sina Šafatova, ostane danas na njegovim ramenima!\"');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 6, 32, 'Elizej sjedio u svojoj kući i starješine sjedile s njim. Kralj je ispred sebe poslao glasnika, ali Elizej reče starješinama, prije nego što je glasnik stigao do njega: \"Vidite li da je onaj krvnički sin naredio da mi skinu glavu? Pazite: kada glasnik stigne, zatvorite vrata i odbijte ga od vrata. Ne čuje li se topot koraka njegova gospodara za njim?\"');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 6, 33, 'Dok im je još govorio, kralj stupi preda nj i reče mu: \"Ova je nevolja, gle, od Jahve! Što da još očekujem od Jahve?\"');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 7, 1, 'Elizej reče tada: \"Čuj riječ Jahvinu! Ovako veli Jahve: \'Sutra će u ovo doba na vratima Samarije biti mjera finoga brašna za šekel, a dvije mjere ječmenog brašna za šekel.\'\"');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 7, 2, 'Dvorjanik, o čiju se ruku kralj oslanjao, odgovori čovjeku Božjemu: \"I kad bi Jahve načinio okna na nebu, bi li to moglo biti?\" A Elizej odgovori: \"Vidjet ćeš svojim očima, ali nećeš jesti.\"');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 7, 3, 'A pred gradskim vratima bijahu četiri gubavca; rekoše oni jedan drugome: \"Zašto stojimo ovdje i očekujemo smrt?');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 7, 4, 'Ako odlučimo ući u grad, glad je u gradu te ćemo ondje umrijeti; ako ostanemo ovdje, opet ćemo umrijeti. Hajde! Pobjegnimo i prijeđimo u aramejski tabor: ako nas ostave na životu, živjet ćemo; ako nas ubiju, pa dobro: umrijet ćemo!\"');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 7, 5, 'U sumračje, ustavši, krenuše odande u aramejski tabor. Stigoše do ruba tabora, i gle - ondje nikoga!');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 7, 6, 'Jer je Jahve učinio te se u taboru aramejskom čula buka kola i konja, buka goleme vojske. I govorili su među sobom: \"Eto, kralj Izraela najmio je protiv nas kraljeve hetitske i kraljeve egipatske da krenu protiv nas.\"');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 7, 7, 'Digli su se i pobjegli u sumraku: ostavili su svoje šatore, konje i magarce, sav tabor kakav bijaše. Pobjegli su da iznesu živu glavu.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 7, 8, 'Kad su gubavci, dakle, došli do ruba tabora, uvukoše se u jedan šator. Pošto su se najeli i napili, uzeše odande srebro, zlato i haljine pa odoše da ih sakriju. Vratiše se onda pa uđoše u drugi šator: uzeše plijen iz njega te odoše i sakriše ga.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 7, 9, 'Rekoše tada jedan drugome: \"Ne smijemo tako raditi. Današnji je dan pun dobrih vijesti, a mi šutimo. Ako dočekamo jutro, bit ćemo krivi. Zato pođimo! Javimo dvoru novost.\"');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 7, 10, 'I vratiše se, pozvaše gradsku stražu i javiše: \"Otišli smo u tabor aramejski, a ondje nigdje čovjeka ni ljudskoga glasa; samo konji privezani i magarci, a šatori ostavljeni kakvi jesu.\"');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 7, 11, 'Stražari viknuše i dojaviše u unutrašnjost dvora.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 7, 12, 'Kralj ustade noću i reče svojim časnicima: \"Ja ću vam objasniti što su nam učinili Aramejci. Kako znaju da smo gladni, izišli su iz tabora i sakrili se u polju, misleći: već će oni izići iz grada, a mi ćemo ih žive pohvatati i ući u grad.\"');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 7, 13, 'A jedan između njegovih časnika odgovori: \"Neka se uzme ipak pet od preostalih konja. S njima će biti kao sa svim mnoštvom Izraelovim koje je ovdje preostalo. Pošaljimo ih pa ćemo vidjeti.\"');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 7, 14, 'I uzeše dva konja kolska i kralj posla ljude za aramejskim taborom govoreći: \"Idite, izvidite!\"');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 7, 15, 'Išli su za njima do Jordana; put bijaše sav prekriven haljinama i stvarima koje su Aramejci pobacali u bijegu. Glasnici se vratiše i obavijestiše kralja.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 7, 16, 'I narod iziđe i uze pljačkati aramejski tabor: i bijaše mjera finoga brašna za šekel, a dvije mjere ječmenoga za jedan šekel, prema riječi Jahvinoj.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 7, 17, 'Kralj je postavio na gradska vrata onoga dvorjanika o čiju se ruku oslanjao; a narod ga izgazi na vratima i on umrije, prema riječi što ju je rekao Božji čovjek kad mu kralj bijaše došao.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 7, 18, 'Dogodilo se kako je čovjek Božji rekao kralju: \"Sutra u ovo doba na vratima Samarije bit će dvije mjere ječmenoga brašna za šekel i mjera finoga brašna za šekel.\"');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 7, 19, 'Dvorjanik je odgovorio Elizeju: \"Pa da Jahve načini i okna na nebu, bi li moglo biti što kažeš?\" Elizej mu je odgovorio: \"Vidjet ćeš svojim očima, ali nećeš jesti.\"');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 7, 20, 'I doista, tako mu se dogodilo: izgazio ga narod na vratima te on umrije.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 8, 1, 'Elizej bijaše savjetovao ženi kojoj je oživio sina: \"Ustani, pođi sa svojom obitelji i skloni se kao tuđinka bilo kamo, jer je Jahve pustio glad; već je došla u zemlju za sedam godina.\"');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 8, 2, 'Žena usta i učini kako joj je rekao čovjek Božji: otišla je, ona i njena obitelj, i ostala sedam godina u zemlji filistejskoj.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 8, 3, 'Na kraju sedme godine žena se vrati iz zemlje filistejske i ode kralju da zatraži svoju kuću i njivu.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 8, 4, 'Upravo je kralj razgovarao s Gehazijem, momkom Božjega čovjeka. Govorio mu je: \"Pripovijedaj mi o svim velikim djelima koja je Elizej učinio.\"');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 8, 5, 'I kad je pripovijedao kralju o uskrisenju djeteta, eto žene kojoj je Elizej oživio sina; ona se obrati kralju radi svoje kuće i njive. A Gezahi reče: \"Gospodaru kralju, evo one žene i evo njena sina koga je Elizej oživio.\"');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 8, 6, 'Kralj upita ženu i ona mu sve pripovjedi. Tada joj kralj dade jednoga slugu, komu naredi: \"Neka joj se vrati sve što je njeno i svi prihodi od njive od dana kada je ostavila zemlju do danas!\"');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 8, 7, 'Elizej dođe u Damask. Ben-Hadad, kralj aramejski, bijaše obolio. Odmah mu javiše: \"Božji čovjek došao ovamo.\"');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 8, 8, 'Tada reče kralj Hazaelu: \"Uzmi sa sobom dar pa idi pred Božjeg čovjeka. I preko njega se posavjetuj s Jahvom da bi saznao hoću li se izliječiti od ove bolesti.\"');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 8, 9, 'Hazael ode pred Elizeja i donese mu u dar što bijaše od ponajboljeg u Damasku, sve to natovareno na četrdeset deva. Dođe on i stade preda nj i reče: \"Tvoj sin Ben-Hadad, kralj aramejski, šalje me k tebi i pita hoće li ozdraviti od one bolesti.\"');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 8, 10, 'Elizej mu odgovori: \"Idi i reci mu: \'Ozdravit ćeš, dakako!\' Ali mi je Jahve pokazao da će umrijeti.\"');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 8, 11, 'I čovjek Božji uprije pogled preda se, smeten, i zaplaka.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 8, 12, 'Hazael reče: \"Zašto plačeš, moj gospodaru?\" Elizej odgovori: \"Zato što znam sva zla koja ćeš ti učiniti Izraelcima: spalit ćeš im utvrde, mačem ćeš poubijati njihove ratnike, njihovu ćeš djecu satirati, a trudne žene parati.\"');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 8, 13, 'Hazael reče: \"Ali što je tvoj sluga? Zar je pas da učini tako strašne stvari?\" Elizej odgovori: \"U jednoj Jahvinoj objavi vidio sam tebe kao kralja aramejskog.\"');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 8, 14, 'Hazael ode od Elizeja i vrati se svome gospodaru, koji ga upita: \"Što ti je rekao Elizej?\" On odgovori: \"Rekao mi je da ćeš ozdraviti.\"');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 8, 15, 'Ali sutradan uze pokrivač, namoči ga u vodi i pokri kralja preko lica te on umrije. A na njegovo mjesto zakralji se Hazael.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 8, 16, 'Pete godine kraljevanja Jorama, sina Ahabova, u Izraelu, postade judejskim kraljem Joram, sin Jošafatov.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 8, 17, 'Bile su mu trideset i dvije godine kad se zakraljio, a kraljevao je osam godina u Jeruzalemu.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 8, 18, 'Živio je poput izraelskih kraljeva, kao i dom Ahabov, jer mu je kći Ahabova bila žena; radio je što je zlo u Jahvinim očima.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 8, 19, 'Ipak Jahve ne htjede razoriti Judeje zbog sluge svoga Davida, zato što mu obeća da će dati svjetiljku njemu i njegovim sinovima zauvijek.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 8, 20, 'U njegovo se vrijeme Edomci odmetnuše ispod judejske vlasti i postaviše sebi kralja.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 8, 21, 'Joram ode u Seir i s njim sva bojna kola. Diže se noću i pobi Edomce koji su bili opkolili njega i zapovjednike bojnih kola. Narod pobježe u svoje šatore.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 8, 22, 'Ipak su se Edomci oslobodili ispod judejske vlasti sve do danas. U isto se doba odmetnu i Libna.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 8, 23, 'Ostala povijest Jorama, sve što je učinio, zar to nije zapisano u knjizi Ljetopisa kraljeva judejskih?');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 8, 24, 'Joram počinu kraj svojih otaca i bi pokopan k svojim ocima u Davidovu gradu. Njegov sin Ahazja zakralji se mjesto njega.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 8, 25, 'Dvanaeste godine Jorama, sina Ahabova, kralja Izraela, postade judejskim kraljem Ahazja, sin Joramov.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 8, 26, 'Ahazji bijahu dvadeset i dvije godine kad se zakraljio, a kraljevao je godinu dana u Jeruzalemu. Mati mu se zvala Atalija, a bila je kći izraelskog kralja Omrija.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 8, 27, 'I on je hodio putem obitelji Ahabove i činio je zlo u očima Jahvinim, kao i obitelj Ahabova, jer je s njom bio u rodu.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 8, 28, 'On je pošao s Joramom, sinom Ahabovim, u Ramot Gilead u boj protiv Hazaela, aramskog kralja.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 8, 29, 'Kralj Joram vratio se u Jizreel da se liječi od rana što mu ih zadadoše u Rami kad se borio s aramejskim kraljem Hazaelom. Joramov sin Ahazja, judejski kralj, sišao je u Jizreel da posjeti Ahabova sina Jorama jer se Joram razbolio.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 9, 1, 'Prorok Elizej pozva jednoga od proročkih sinova i reče mu: \"Opaši se, uzmi sa sobom ovu posudu s uljem pa idi u Ramot Gilead.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 9, 2, 'Kad onamo stigneš, potraži Jehua, sina Jošafatova, sina Nimšijeva. Kad ga nađeš, izvedi ga između njegovih drugova i uvedi ga u pokrajnju sobu.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 9, 3, 'I uzmi posudu s uljem, izlij mu je na glavu i reci: \'Ovako veli Jahve: Pomazao sam te za kralja izraelskoga.\' Zatim otvori vrata i bježi, ne oklijevaj.\"');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 9, 4, 'Tada mladi prorok ode u Ramot Gilead.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 9, 5, 'Kad je stigao, zapovjednici vojske upravo su sjedili na okupu. On reče: \"Imam ti riječ reći, zapovjedniče!\" Jehu upita: \"Komu od nas?\" On odgovori: \"Tebi, zapovjedniče!\"');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 9, 6, 'Jehu tada ustade i uđe u kuću. Mladi mu čovjek izli ulje na glavu i reče mu: \"Ovako veli Jahve, Bog Izraelov: \'Pomazao sam te za kralja nad Jahvinim narodom, nad Izraelom.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 9, 7, 'Ti ćeš pobiti obitelj Ahaba, gospodara tvoga, a ja ću osvetiti krv svojih slugu proroka i krv sviju službenika Jahvinih na Izebeli');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 9, 8, 'i na svoj obitelji Ahabovoj. Iskorijenit ću Ahabu sve što mokri uza zid, robove i slobodnjake u Izraelu.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 9, 9, 'Učinit ću s domom Ahabovim kao s domom Jeroboama, sina Nebatova, i kao s domom Baše, sina Ahijina.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 9, 10, 'A Izebelu će proždrijeti psi na polju jizreelskom i nitko je neće pokopati.\'\" - Zatim otvori vrata i pobježe.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 9, 11, 'Jehu iziđe k časnicima svoga gospodara. Oni ga upitaše: \"Je li sve u miru? Zašto je ta budala dolazila k tebi?\" On im odgovori: \"Znate čovjeka i besjedu njegovu.\"');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 9, 12, 'Oni rekoše: \"Ne znamo! Kazuj nam!\" On im reče: \"Govorio mi je tako i tako i rekao mi: \'Ovako veli Jahve: Pomazao sam te za kralja nad Izraelom.\'\"');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 9, 13, 'Odmah oni uzeše svoje ogrtače i prostriješe ih pred njim po stepenicama, zatrubiše u rogove i povikaše: \"Jehu je kralj!\"');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 9, 14, 'Tako Jehu, sin Jošafata, sina Nimšijeva, skova urotu protiv Jorama - Joram je tada branio Ramot Gilead sa svim Izraelcima protiv Hazaela, aramejskog kralja.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 9, 15, 'Ali se kralj Joram vratio u Jizreel da liječi rane koje su mu zadali Aramejci u boju s Hazaelom, aramejskim kraljem. - I reče Jehu: \"Ako vam je po volji, neka nitko ne utekne iz grada da odnese vijest u Jizreel.\"');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 9, 16, 'Jehu se tada pope na kola i ode prema Jizreelu, jer je Joram ondje bolovao, i Ahazja, kralj judejski, došao ga posjetiti.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 9, 17, 'Stražar koji je stajao na kuli u Jizreelu, videći da dolazi Jehuova četa, javi: \"Vidim nekakvu četu.\" Joram naredi: \"Uzmi konjanika i pošalji ga pred njih da upita: je li sve s mirom.\"');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 9, 18, 'Ode konjanik preda nj i reče: \"Ovako veli kralj: je li sve s mirom?\" - Jehu odgovori: \"Što te briga je li s mirom! Hajde za mnom.\" Stražar javi: \"Glasnik je stigao do njih, ali se ne vraća.\"');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 9, 19, 'Kralj posla drugoga konjanika. Taj dođe k njima i upita: \"Ovako veli kralj: je li sve s mirom?\" - Jehu mu odgovori: \"Što te briga je li s mirom! Hajde za mnom.\"');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 9, 20, 'Stražar opet javi: \"Došao je do njih, ali se ne vraća. A vožnja je kao vožnja Jehua, sina Nimšijeva: vozi kao mahnit!\"');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 9, 21, 'Joram reče: \"Preži!\" I upregoše u njegova kola. Joram, kralj Izraela, i judejski kralj Ahazja iziđoše, svaki u svojim kolima, u susret Jehuu. Susretoše ga u polju Nabota Jizreelca.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 9, 22, 'Kad Joram ugleda Jehua, upita ga: \"Je li sve u miru, Jehu?\" Ovaj odgovori: \"Kakvu miru dok traju bludništva tvoje majke Izebele i njena mnoga čaranja!\"');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 9, 23, 'Joram okrenu i udari u bijeg govoreći Ahazji: \"Izdaja, Ahazja!\"');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 9, 24, 'Jehu se lati luka, ustrijeli Jorama među pleća: strijela mu prođe posred srca te se on sruši u kola.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 9, 25, 'Jehu reče svome dvorjaniku Bidkaru: \"Digni ga i baci na njivu Nabota Jizreelca. Sjeti se: kad smo ja i ti jahali za njegovim ocem Ahabom, kako Jahve izreče protiv njega:');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 9, 26, '\'Kunem se: kako sinoć vidjeh krv Nabotovu i krv njegovih sinova,\' riječ je Jahvina, \'tako ću ti vratiti isto na ovome polju,\' riječ je Jahvina. Digni ga, dakle, i baci ga na to polje, prema riječi Jahvinoj.\"');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 9, 27, 'Kada je to vidio judejski kralj Ahazja, pobježe prema Bet Haganu, ali ga je Jehu gonio i naredio: \"Ubijte i njega!\" Ranili su ga u kolima na brdu Guru, koje se nalazi kod Jibleama. Ali je umakao u Megido i ondje umrije.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 9, 28, 'Njegove su ga sluge u kolima prenijele u Jeruzalem i sahranile ga u grobnici kraj njegovih otaca, u Davidovu gradu.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 9, 29, 'Jedanaeste godine kraljevanja Jorama, sina Ahabova, Ahazja postade kralj nad Judejom.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 9, 30, 'A Jehu bijaše ušao u Jizreel. Kad je to čula Izebela, namaza oči, uresi glavu i pogleda s prozora.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 9, 31, 'I kad je Jehu ulazio na vrata, ona reče: \"Kako je, Zimri, ubojico svoga gospodara?\"');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 9, 32, 'Jehu okrenu lice prema prozoru i reče: \"Tko je sa mnom, tko?\" I dva-tri dvoranina pogledaše prema njemu.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 9, 33, 'On reče: \"Bacite je dolje.\" I oni je baciše. Njena je krv poprskala zidove i konje, koji je pogaziše.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 9, 34, 'Ušao je on, jeo i pio, a zatim naredio: \"Pogledajte onu prokletnicu i sahranite je, jer je bila kraljevska kći.\"');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 9, 35, 'I odoše da je sahrane, ali ne nađoše ništa od nje, osim lubanje, nogu i ruku.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 9, 36, 'Vratiše se i javiše, a Jehu reče: \"To je riječ koju je Jahve objavio preko svoga sluge Ilije Tišbijca: \'U polju jizreelskom psi će proždrijeti Izebelino tijelo.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 9, 37, 'Izebelino truplo bit će kao gnoj u polju, da se neće moći kazati: Ovo je Izebela.\'\"');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 10, 1, 'U Samariji bijaše sedamdeset Ahabovih sinova. Jehu napisa pismo i posla ga u Samariju zapovjednicima grada, starješinama i skrbnicima Ahabove djece. Kazivaše u njemu:');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 10, 2, '\"Sada, kad vam stigne ovo pismo - vi, u kojih su sinovi vašeg gospodara, koji imate kola i konje, tvrde gradove i oružje -');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 10, 3, 'pogledajte koji je između sinova vašeg gospodara najbolji i najdostojniji, pa ga postavite na prijestolje njegova oca i borite se za dom svoga gospodara.\"');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 10, 4, 'Ali se oni veoma uplašiše i rekoše: \"Eto, dva mu kralja nisu mogla odoljeti, kako ćemo mu mi odoljeti?\"');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 10, 5, 'Upravitelj dvora, zapovjednik grada, starješine i skrbnici poručiše ovo Jehuu: \"Mi smo tvoje sluge, činit ćemo sve što nam budeš naredio; kraljem proglašavati nećemo nikoga. Čini što misliš da je dobro.\"');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 10, 6, 'Jehu im napisa drugo pismo i u njemu reče: \"Ako ste za mene i želite me slušati, uzmite glave ljudi, sinova svoga gospodara, i potražite me sutra u ovo doba u Jizreelu.\" Sedamdeset je naime kraljevih sinova bilo kod uglednih građana koji su ih odgajali.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 10, 7, 'I kad im je stiglo ovo pismo, uzeli su kraljeve sinove i pobili ih svih sedamdeset. Njihove su glave metnuli u košare i poslali su ih njemu u Jizreel.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 10, 8, 'Glasnik dođe i javi mu: \"Donijeli su glave kraljevih sinova.\" On reče: \"Stavite ih do sutra kod ulaznih vrata, u dvije hrpe.\"');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 10, 9, 'Ujutro iziđe, stade i reče svomu narodu: \"Vi ste pravedni! Ja sam se urotio protiv svoga gospodara i ja sam ga ubio, ali tko pobi sve ove?');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 10, 10, 'Znajte, dakle, da nije izostala nijedna riječ koju reče Jahve o obitelji Ahabovoj; nego je Jahve izvršio sve što je rekao preko sluge svoga Ilije.\"');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 10, 11, 'I Jehu pobi sve koji su u Jizreelu ostali iz kuće Ahabove, sve velikaše njegove, pouzdanike i svećenike njegove. Nije poštedio nikoga.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 10, 12, 'Potom usta Jehu i pođe u Samariju. Kad je bio na cesti kod Bet Ekeda pastirskoga,');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 10, 13, 'nađe braću judejskog kralja Ahazje te ih upita: \"Tko ste?\" Oni mu odgovoriše: \"Mi smo braća Ahazjina, a silazimo da pozdravimo sinove kraljeve i sinove kraljičine.\"');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 10, 14, 'Tada zapovjedi: \"Pohvatajte ih žive!\" I žive ih pohvataše i pobiše ih na studencu kod Bet Ekeda, njih četrdeset i dvojicu. Nije ostavio ni jednoga od njih.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 10, 15, 'Otišavši odatle, nađe Jonadaba, sina Rekabova, koji mu je dolazio u susret. On ga pozdravi i reče mu: \"Je li tvoje srce iskreno prema mome, kao što je moje prema tvome srcu?\" Jonadab odgovori: \"Jest.\" - \"Ako je tako, daj mi ruku.\" Jonadab mu pruži ruku i Jehu ga posadi kraj sebe na kola.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 10, 16, 'I reče mu: \"Hodi sa mnom, divit ćeš se mojoj revnosti za Jahvu.\" I odvede ga na svojim kolima.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 10, 17, 'Ušao je u Samariju i poubijao sve preživjele iz obitelji Ahabove u Samariji. Sve ih je iskorijenio po riječi koju Jahve bijaše rekao Iliji.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 10, 18, 'Jehu je sakupio sav narod i rekao mu: \"Ahab je malo poštivao Baala; Jehu će ga više poštivati.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 10, 19, 'Sada mi pozovite sve proroke Baalove, sve njegove sluge i sve njegove svećenike, neka ni jedan ne izostane, jer ću žrtvovati veliku žrtvu Baalu. Tko izostane, izgubit će život.\" Jehu je radio lukavo, da bi uništio Baalove vjernike.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 10, 20, 'Jehu reče: \"Sazovite svečani zbor Baalu.\" I sazvaše ga.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 10, 21, 'Jehu je nato poslao glasnike po svem Izraelu i došli su svi Baalovi vjernici: nije bilo ni jednoga da bi izostao. Skupili su se u Baalov hram, koji se ispunio od jednoga zida do drugoga.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 10, 22, 'Jehu reče čuvaru haljina: \"Iznesi haljine svim Baalovim vjernicima.\" I iznese im haljine.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 10, 23, 'Jehu uđe u hram Baalov s Jonadabom, sinom Rekabovim, i reče Baalovim vjernicima: \"Provjerite dobro da nema ovdje među vama Jahvina sluge nego samih Baalovih vjernika.\"');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 10, 24, 'I pođe žrtvovati klanice i paljenice. Ali je Jehu postavio vani osamdeset svojih ljudi i rekao im: \"Ako koji od vas pusti da utekne i jedan od ovih ljudi što ih predajem u vaše ruke, svojim će životom platiti njegov život.\"');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 10, 25, 'Kad je Jehu završio prinos paljenice, naredi tjelesnoj straži i dvoranima: \"Uđite, pobijte ih! Nitko neka ne iziđe!\" Tjelesna straža i dvorani uđoše, pobiše ih oštricom mača i prodriješe sve do svetišta Baalova hrama.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 10, 26, 'Iznesoše Baalov lik iz hrama i spališe ga.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 10, 27, 'Raskopaše žrtvenik Baalov, srušiše i hram Baalov i pretvoriše ga u jame za nečist, koje su ostale do danas.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 10, 28, 'Tako je Jehu istrijebio Baala iz Izraela.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 10, 29, 'Ali se Jehu nije okrenuo od grijeha Jeroboama, sina Nebatova, kojima je zavodio Izraela, od zlatnih telaca u Betelu i Danu.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 10, 30, 'Jahve je rekao Jehuu: \"Zato što si dobro izvršio ono što mi je po volji i što si učinio sve što sam nosio u srcu protiv kuće Ahabove, tvoji će sinovi sve do četvrtoga koljena sjediti na prijestolju Izraelovu.\"');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 10, 31, 'Ali Jehu nije vjerno i svim srcem svojim slijedio zakon Jahve, Boga Izraelova. Nije se odvratio od grijeha kojima je Jeroboam zavodio Izraela.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 10, 32, 'U ono je vrijeme Jahve počeo krnjiti zemlju izraelsku, i Hazael se tukao s Izraelcima na svom području,');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 10, 33, 'od Jordana prema sunčevu izlasku, u svoj zemlji Gileadu, u zemlji Gadovoj, Rubenovoj i Manašeovoj, sve od Aroera na obali Arnona, do Gileada i Bašana.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 10, 34, 'Ostala povijest Jehuova, sve što je učinio, sva njegova djela, zar to nije zapisano u knjizi Ljetopisa kraljeva izraelskih?');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 10, 35, 'Počinuo je kraj svojih otaca i pokopaše ga u Samariji. Joahaz, sin njegov, zakralji se mjesto njega.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 10, 36, 'Jehu je vladao u Samariji nad Izraelom dvadeset i osam godina.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 11, 1, 'Zato Ahazjina mati Atalija, vidjevši gdje joj sin poginu, ustade i posmica sav kraljevski rod.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 11, 2, 'Ali Jošeba, kći kralja Jorama i sestra Ahazjina, uze Ahazjina sina Joaša; ukravši ga između kraljevih sinova koje su ubijali, metnu ga s dojiljom u ložnicu. Tako ga je sakrila od Atalije te nije pogubljen.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 11, 3, 'Bio je sakriven u Domu Jahvinu šest godina, sve dok je zemljom vladala Atalija.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 11, 4, 'Sedme godine Jojada posla po satnike Karijaca i tjelesnu stražu i pozva ih k sebi u Dom Jahvin. Sklopi s njima savez, zakle ih i pokaza im kraljeva sina.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 11, 5, 'I reče im: \"Evo što valja da učinite: trećina vas koji subotom ulazite u službu neka čuva stražu kod kraljevskoga dvora.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 11, 6, 'Druga trećina, ona kod Surskih vrata, i treća trećina, ona kod stražnjih stražarskih vrata, neka čuvaju stražu kod ulaza u dvor;');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 11, 7, 'a ostala dva vaša odreda, svi koji subotom izlaze iz službe, neka čuvaju stražu u Domu Jahvinu kod kralja.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 11, 8, 'Tako ćete okružiti kralja, svaki s oružjem u ruci. I tko god pokuša proći kroz vaše redove, neka bude pogubljen. Budite uz kralja kamo god pođe ili izađe.\"');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 11, 9, 'Satnici su učinili sve kako im je naredio svećenik Jojada. Svaki je od njih uzeo svoje ljude koji subotom ulaze u službu s onima koji subotom izlaze. I svi su došli svećeniku Jojadi.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 11, 10, 'Svećenik dade satnicima koplja i štitove kralja Davida što su bili u Domu Jahvinu.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 11, 11, 'Stražari se svrstaše, s oružjem u ruci, od južne do sjeverne strane Doma i prema žrtveniku i Domu oko kralja unaokolo.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 11, 12, 'Tada Jojada izvede sina kraljeva, stavi mu krunu i dade mu Svjedočanstvo te ga pomaza za kralja. Pljeskali su i vikali: \"Živio kralj!\"');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 11, 13, 'Kad Atalija ču viku naroda, dođe k narodu u Dom Jahvin.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 11, 14, 'Pogleda bolje, kad gle, kralj, po običaju, stoji na svojem mjestu, a pred kraljem zapovjednici i svirači; sav puk klikće od radosti i trubi u trube. Tad Atalija razdrije haljine i povika: \"Izdaja! Izdaja!\"');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 11, 15, 'Svećenik Jojada naredi satnicima i vojnim zapovjednicima: \"Izvedite je kroz redove i tko krene za njom pogubite ga mačem.\" Još je svećenik dodao: \"Nemojte je smaknuti u Domu Jahvinu.\"');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 11, 16, 'Staviše ruke na nju; a kad je kroz Konjska vrata stigla do kraljevskog dvora, ondje je pogubiše.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 11, 17, 'Tada Jojada sklopi savez između Jahve, kralja i naroda da narod bude narod Jahvin.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 11, 18, 'Potom sav narod ode u Baalov hram i razoriše ga, porušiše žrtvenike i polomiše likove; a Baalova svećenika Matana ubiše pred žrtvenicima. A svećenik opet postavi straže kod Doma Jahvina.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 11, 19, 'Zatim uze satnike Karijaca, stražu i sav narod. Oni izvedoše kralja iz Doma Jahvina i uvedoše ga u dvor kroz Vrata stražarska. I Joaš sjede na kraljevsko prijestolje.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 11, 20, 'Sav se puk veselio i grad se smirio kad su Ataliju ubili mačem u kraljevskom dvoru.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 12, 1, 'Joašu je bilo sedam godina kad se zakraljio.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 12, 2, 'Sedme godine Jehuova kraljevanja Joaš je postao kraljem i kraljevao je četrdeset godina u Jeruzalemu. Majka mu se zvala Sibja i bila je iz Beer Šebe.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 12, 3, 'Joaš je činio što je pravo u očima Jahve svega svog vijeka jer ga je poučavao svećenik Jojada.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 12, 4, 'Ali uzvišica nisu srušili i narod je svejednako prinosio žrtve i kad na uzvišicama.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 12, 5, 'Joaš reče svećenicima: \"Sav novac od posvećenih darova što se donosi u Dom Jahvin, novac koji je nekomu nametnut procjenom i novac što ga tko od svoje volje donose u Dom Jahvin');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 12, 6, 'neka svećenici uzimaju svaki od svoga znanca i oni neka tim poprave Dom gdje god se nađe koje oštećenje.\"');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 12, 7, 'Ali u dvadeset i trećoj godini kraljevanja Joaševa svećenici nisu još popravili Doma.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 12, 8, 'Tada kralj Joaš pozva svećenika Jojadu i druge svećenike i reče im: \"Zašto ne popravljate Dom? Odsad ne smijete više sebi uzimati novac od svojih znanaca nego ga morate dati za popravak Doma.\"');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 12, 9, 'Svećenici pristadoše da ne uzimaju novac od naroda, ali ni Doma da ne popravljaju.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 12, 10, 'Tada svećenik Jojada uze kovčeg, proreza rupu na zaklopcu i stavi ga uza žrtvenik, zdesna od ulaza u Dom Jahvin. Svećenici, čuvari praga, stavljali su u nj sav novac sabran u Domu Jahvinu.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 12, 11, 'Kad bi se vidjelo da u kovčegu ima mnogo novaca, došao bi kraljev tajnik s velikim svećenikom te bi prebrojili i zavezali novac koji se nalazio u Domu Jahvinu.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 12, 12, 'Prebrojeni novac uručivao se upraviteljima poslova oko popravka Doma Jahvina, a oni su isplaćivali drvodjeljama i graditeljima koji su radili u Domu Jahvinu');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 12, 13, 'i zidarima i klesačima kamena, i za nabavu drveta i tesanog kamena određena za popravak Doma Jahvina, ukratko: za troškove oko popravka Doma.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 12, 14, 'Ali u Domu Jahvinu nisu se pravile srebrne čaše, ni noževi, ni plitice, ni trube, niti bilo kakav predmet od zlata ili srebra za novac koji je darovan,');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 12, 15, 'nego su ga davali radnicima koje su najmili za popravak Jahvina Doma.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 12, 16, 'Nije se tražio obračun od ljudi kojima su predavali novac da ga daju radnicima, jer su oni radili savjesno.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 12, 17, 'Novac naknadnice i okajnice nije se unosio u Dom Jahvin, nego je pripao svećenicima.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 12, 18, 'Tada Hazael, aramejski kralj, pođe u rat protiv Gata i osvoji ga. Zatim odluči poći protiv Jeruzalema.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 12, 19, 'Joaš, judejski kralj, uze sve posvećene darove koje su posvetili judejski kraljevi, njegovi oci: Jošafat, Joram i Ahazja, sve što je sam prikazao i sve zlato koje se našlo u riznicima Doma Jahvina i kraljevskog dvora. Sve to posla Hazaelu, aramejskom kralju, i tako se ovaj udalji od Jeruzalema.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 12, 20, 'Ostala povijest Joaševa i sve što je učinio, zar sve to nije zapisano u knjizi Ljetopisa kraljeva judejskih?');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 12, 21, 'Njegovi časnici ustadoše i skovaše zavjeru; ubiše Joaša u Bet Milu kad je u nj silazio.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 12, 22, 'Njegovi časnici Jozakar, sin Šimatov, i Jozabad, sin Šomerov, zadaše mu smrtni udarac. Pokopali su ga kraj njegovih otaca u Davidovu gradu, a njegov sin Amasja zakralji se mjesto njega.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 13, 1, 'Dvadeset i treće godine kraljevanja judejskog kralja Joaša, sina Ahazjina, postade Joahaz, sin Jehuov, izraelskim kraljem u Samariji. Kraljevao je sedamnaest godina.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 13, 2, 'On je činio što je zlo u očima Jahvinim i poveo se za grijesima Jeroboama, sina Nebatova, koji je zavodio Izraela. Od njih nije odstupao.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 13, 3, 'Tada Jahve uskipje gnjevom na Izraela i predade ga u ruke aramejskog kralja Hazaela i u ruke Ben-Hadada, sina Hazaelova, za sve ono vrijeme.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 13, 4, 'Ali je Joahaz ublažio lice Jahvino i Jahve ga je uslišio, jer je vidio nevolju koju je aramejski kralj nanosio Izraelu.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 13, 5, 'Jahve je dao Izraelu izbavitelja koji ga je izbavio od ruke aramejske te su Izraelci živjeli u svojim šatorima kao i prije.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 13, 6, 'Ali nisu odstupali od grijeha kojim Jeroboam bijaše zaveo Izraela: ustrajali su u njemu, pa i ašere ostadoše u Samariji.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 13, 7, 'Jahve je ostavio Joahazu samo pedeset konjanika kao vojsku, deset bojnih kola i deset tisuća pješaka; kralj aramejski bijaše ih uništio i zgazio ih kao prah u vršidbi.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 13, 8, 'Ostala povijest Joahazova, sve što je učinio i poduzimao, zar sve to nija zapisano u knjizi Ljetopisa kraljeva izraelskih?');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 13, 9, 'Joahaz je počinuo sa svojim ocima i bi pokopan u Samariji, a njegov sin Joaš zakralji se mjesto njega.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 13, 10, 'Trideset i sedme godine kraljevanja judejskoga kralja Joaša postade Joaš, sin Joahazov, izraelskim kraljem u Samariji; kraljevao je šesnaest godina.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 13, 11, 'Činio je što je zlo u očima Jahvinim. Nije odstupao od grijeha Jeroboama, sina Nebatova, koji je zaveo Izraela. Za njim se poveo.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 13, 12, 'Ostala povijest Joaševa, sve što je učinio, junaštva njegova, kako je ratovao s Amasjom, judejskim kraljem, zar sve to nije zapisano u knjizi Ljetopisa kraljeva izraelskih?');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 13, 13, 'Joaš je počinuo sa svojim ocima, a Jeroboam se popeo na njegovo prijestolje. Joaša pokopaše u Samariji uz izraelske kraljeve.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 13, 14, 'Kad se Elizej razbolio od bolesti od koje mu valjade umrijeti, dođe mu izraelski kralj Joaš, rasplaka se nad njim i reče mu: \"Oče moj, oče moj! Kola Izraelova i konjanici njegovi!\"');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 13, 15, 'Elizej mu reče: \"Uzmi luk i strijele.\" I on dohvati luk i strijele.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 13, 16, 'Elizej će tada kralju: \"Nategni luk!\" I on ga nateže. Elizej stavi ruke na ruke kraljeve,');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 13, 17, 'zatim reče: \"Otvori prozor prema istoku.\" I on ga otvori, a nato će Elizej: \"Odapni!\" I on odape, a Elizej reče: \"Pobjedonosna strijela Jahvina! Pobjednička strijela nad Aramejcima! Do nogu ćeš potući Aramejce kod Afeka.\"');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 13, 18, 'I nastavi: \"Uzmi strijele!\" On ih uze. Elizej tada reče kralju: \"Udri o zemlju!\" On udari tri puta i stade.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 13, 19, 'Tada se rasrdi na njega Božji čovjek i reče: \"Pet ili šest puta trebalo je da udariš! Tada bi potpuno potukao Aramejce; ovako ćeš ih pobijediti samo tri puta.\"');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 13, 20, 'Elizej zatim umrije i pokopaše ga. A pljačkaške čete Moabaca napadale zemlju svake godine.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 13, 21, 'Dogodilo se te su neki, sahranjujući čovjeka, opazili razbojnike: baciše mtrvaca u grob Elizejev i odoše. Mrtvac, dotakavši se Elizejevih kostiju, oživje i stade na noge.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 13, 22, 'Aramejski kralj Hazael ugnjetavaše Izraelce svega vijeka Joahazova.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 13, 23, 'Ali im se Jahve smilova i ražali se nad njima. Pogleda na njih zbog svoga Saveza koji je sklopio s Abrahamom, Izakom i Jakovom. Nije ih htio uništiti i nije ih odbacio daleko od svoga lica do danas.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 13, 24, 'Hazael, aramejski kralj, umrije, a njegov sin Ben-Hadad zavlada namjesto njega.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 13, 25, 'Tada Joaš, sin Joahazov, opet uze iz ruke Ben-Hadada, sina Hazaelova, gradove koje Hazael u ratu bijaše oteo njegovu ocu Joahazu. Joaš ga je tri puta potukao i vratio gradove Izraelove.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 14, 1, 'Druge godine kraljevanja Joaša, sina Joahazova, nad Izraelom, postade judejskim kraljem Amasja, sin Joašev.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 14, 2, 'Bilo mu je dvadeset i pet godina kad se zakraljio, a kraljevao je dvadeset i devet godina u Jeruzalemu. Mati mu se zvala Joadana i bila je iz Jeruzalema.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 14, 3, 'Činio je što je pravo u Jahvinim očima, ali ne sasvim kao praotac njegov David. U svemu je slijedio Joaša, svoga oca.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 14, 4, 'Ali uzvišica nije razrušio i narod je svejednako prinosio žrtve i kad na uzvišicama.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 14, 5, 'Kad je učvrstio kraljevstvo, smakao je one časnike koji su mu ubili oca.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 14, 6, 'Ali nije pogubio sinova onih ubojica, prema onome što je napisano u knjizi Zakona Mojsijeva, gdje Jahve zapovijeda: \"Neka se očevi ne pogubljuju za sinove ni sinovi za očeve, nego svatko neka gine za svoj grijeh.\"');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 14, 7, 'On je potukao Edomce u Slanoj dolini, deset tisuća njih, i u bitki je zauzeo Selu; dao joj je ime Jokteel, koje nosi do današnjega dana.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 14, 8, 'Tada Amasja posla glasnike izraelskom kralju Joašu, sinu Jehuova sina Joahaza, i poruči mu: \"Dođi da se ogledamo!\"');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 14, 9, 'A izraelski kralj Joaš odvrati judejskom kralju Amasji: \"Libanonski je trn jedanput poslao glasnike k libanonskom cedru: \'Daj kćer mome sinu za ženu\', ali su divlje zvijeri libanonske prošle i trn izgazile.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 14, 10, 'Potukao si Edomce, pa ti se srce uzobijestilo i tražiš slavu! Radije ostani kod kuće. Zašto izazivaš zlo i hoćeš da propadneš ti i svi Judejci s tobom?\"');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 14, 11, 'Ali Amasja ne posluša. Izađe izraelski kralj Joaš te se ogledaše u boju on i judejski kralj Amasja u Bet Šemešu u Judeji.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 14, 12, 'Izraelci poraziše Judejce i oni pobjegoše svaki pod svoj šator.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 14, 13, 'Izraelski kralj Joaš uhvati u Bet Šemešu judejskoga kralja Amasju, sina Joaševa, sina Ahazjina, i odvede ga u Jeruzalem. Tada sruši jeruzalemski zid od Efrajimovih vrata do Ugaonih vrata, u dužini od četiri stotine lakata.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 14, 14, 'Uzevši sve zlato, srebro i posuđe što se nalazilo u Domu Jahvinu i u riznici kraljevskog dvora, povrh toga i taoce, vrati se u Samariju.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 14, 15, 'Ostala povijest Joaševa, sve što je činio i poduzimao i kako je ratovao s Amasjom, judejskim kraljem, zar sve to nije zapisano u knjizi Ljetopisa izraelskih kraljeva?');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 14, 16, 'Joaš je počinuo sa svojim ocima i pokopan je u Samariji uz kraljeve izraelske. Sin njegov Jeroboam zakralji se mjesto njega.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 14, 17, 'Amasja, sin Joašev, judejski kralj, živio je još petnaest godina poslije smrti izraelskog kralja Joaša, sina Joahazova.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 14, 18, 'A ostala povijest Amasjina zar nije zapisana u knjizi Ljetopisa kraljeva judejskih?');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 14, 19, 'Protiv njega je skovana urota u Jeruzalemu. Iako je on pobjegao u Lakiš, poslaše za njim u Lakiš ljude koji ga ondje ubiše.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 14, 20, 'Odande su ga prenijeli na konjima i sahranili u Jeruzalemu kraj njegovih otaca, u Davidovu gradu.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 14, 21, 'Tada sav judejski narod uze Azahju, komu bijaše šesnaest godina, i zakralji ga namjesto njegova oca Amasje.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 14, 22, 'On opet sagradi Elat povrativši ga Judeji, pošto je kralj počinuo kod svojih otaca.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 14, 23, 'Petnaeste godine kraljevanja judejskog kralja Amasje, sina Joaševa, postade izraelskim kraljem u Samariji Jeroboam, sin Joašev. On je kraljevao četrdeset i jednu godinu.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 14, 24, 'Činio je što je zlo u očima Jahvinim, nije se ostavio nijednoga grijeha Jeroboama, sina Nebatova, koji je zaveo Izraela.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 14, 25, 'On je dobio natrag izraelsko područje od Ulaza u Hamat do Mrtvoga mora, prema riječi koju je Jahve, Bog Izraelov, rekao preko sluge svoga Jone, sina Amitajeva, proroka iz Gat Hahefera.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 14, 26, 'Jer je Jahve vidio ljutu nevolju Izraelovu da više nema ni slobodnih ni robova i nikoga da pomogne Izraelu.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 14, 27, 'Ali Jahve nije odlučio izbrisati ispod neba ime Izraelovo: spasio ga je rukom Jeroboama, sina Joaševa.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 14, 28, 'Ostala povijest Jeroboama, sve što je učinio i sve što je poduzimao, kako je ratovao i kako je vratio Damask Judi i Izraelu, zar sve to nije zapisano u knjizi Ljetopisa kraljeva izraelskih?');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 14, 29, 'Jeroboam je počinuo sa svojim ocima. Pokopali su ga u Samariji uz kraljeve izraelske, a njegov sin Zaharija zakralji se mjesto njega.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 15, 1, 'Dvadeset i sedme godine kraljevanja Jeroboama, kralja izraelskog, postade judejskim kraljem Azarja, sin Amasjin.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 15, 2, 'Bilo mu je šesnaest godina kad se zakraljio, a kraljevao je pedeset i dvije godine u Jeruzalemu. Mati mu se zvala Jekolija, a bila je iz Jeruzalema.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 15, 3, 'Činio je što je pravo u Jahvinim očima, sasvim kao i njegov otac Amasja.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 15, 4, 'Samo uzvišica nije srušio i narod je svejednako prinosio žrtve i kad na uzvišicama.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 15, 5, 'Ali Jahve udari kralja i ostade on gubav do smrti. Stanovao je u odvojenoj kući. Kraljev sin Jotam bio upravitelj dvora i sudio je puku zemlje.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 15, 6, 'Ostala povijest Azarjina i sve što je učinio, zar sve to nije zapisano u knjizi Ljetopisa kraljeva judejskih?');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 15, 7, 'Azarja je počinuo i sahraniše ga kraj njegovih otaca u Davidovu gradu. A na njegovo se mjesto zakralji sin mu Jotam.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 15, 8, 'Trideset i osme godine Azarjina kraljevanja u Judeji postade izraelskim kraljem u Samariji za šest mjeseci Zaharija, sin Jeroboamov.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 15, 9, 'On je činio što je zlo u očima Jahvinim, kao što su činili njegovi oci; nije odstupao od grijeha Jeroboama, sina Nebatova, koji je na grijeh naveo Izraela.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 15, 10, 'Šalum, sin Jabešov, uroti se protiv njega; udario ga je i usmrtio u Jibleamu te se zakraljio mjesto njega.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 15, 11, 'Ostala povijest Zaharijina zapisana je u knjizi Ljetopisa izraelskih kraljeva.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 15, 12, 'Ispunila se riječ koju je Jahve rekao Jehuu: \"Tvoji će sinovi sjediti na prijestolju Izraela sve do četvrtog koljena.\" I tako je bilo.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 15, 13, 'Šalum, sin Jabešov, postade kraljem trideset i devete godine kraljevanja Uzije, judejskog kralja, i kraljevao je mjesec dana u Samariji.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 15, 14, 'Menahem, sin Gadijev, ode iz Tirse, uđe u Samariju te udari Šaluma, sina Jabešova, usmrti ga i zakralji se mjesto njega.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 15, 15, 'Ostala povijest Šalumova i urota koju je skovao, sve je zapisano u knjizi Ljetopisa kraljeva izraelskih.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 15, 16, 'Tada je Menahem razorio Tifnah i sve što je u njem bilo i njegovo područje od Tirse jer mu nisu otvorili vrata. Razorio ga je i rasporio sve trudnice u njemu.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 15, 17, 'Trideset i devete godine kraljevanja Azarje u Judeji postade Menahem, sin Gadijev, kraljem Izraela. Kraljevao je deset godina u Samariji.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 15, 18, 'Činio je što je zlo u očima Jahvinim; nije odstupao od grijeha Jeroboama, sina Nebatova, koji je zaveo Izraela. U njegovo vrijeme');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 15, 19, 'Pul, kralj Asirije, osvoji zemlju. Menahem dade Pulu tisuću talenata srebra da mu pomogne učvrstiti kraljevsku vlast u njegovim rukama.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 15, 20, 'Menahem ubra taj novac od Izraela, od svih imućnih ljudi, da bi ga mogao dati asirskom kralju. Po osobi je bilo pedeset šekela srebra. Tako se asirski kralj vratio i nije ondje ostao u zemlji.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 15, 21, 'Ostala povijest Menahema i sve što je učinio, zar sve to nije zapisano u knjizi Ljetopisa kraljeva izraelskih?');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 15, 22, 'Menahem je počinuo sa svojim ocima, a sin njegov Pekahja zakralji se na njegovo mjesto.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 15, 23, 'Pedesete godine kraljevanja judejskog kralja Azarje postade kraljem izraelskim u Samariji Pekahja, sin Menahemov. Kraljevao je dvije godine.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 15, 24, 'On je činio što je zlo u očima Jahvinim; nije odstupao od grijeha Jeroboama, sina Nebatova, koji je zaveo Izraela.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 15, 25, 'Njegov dvoranin Pekah, sin Remalijin, uroti se protiv njega i ubi ga u Samariji, u kuli kraljevskog dvora, s Argobom i Arjeom. Imao je sa sobom pedeset ljudi iz Gileada. Ubio je kralja i zakraljio se mjesto njega.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 15, 26, 'Ostala povijest Pekahje i sve što je učinio, sve je to zapisano u knjizi Ljetopisa izraelskih kraljeva.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 15, 27, 'Pedeset i druge godine kraljevanja Azarje, judejskoga kralja, postade kraljem u Samariji Pekah, sin Remalijin. Kraljevao je dvadeset godina.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 15, 28, 'On je činio što je zlo u očima Jahvinim; nije odstupao od grijeha Jeroboama, sina Nebatova, koji je zaveo Izraela.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 15, 29, 'U vrijeme izraelskog kralja Pekaha došao je asirski kralj Tiglat Pileser i zauzeo Ijon, Abel Bet Maaku, Janoah, Kedeš, Hasor, Gilead, Galileju i svu zemlju Naftalijevu. I odveo je stanovništvo u Asiriju.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 15, 30, 'Hošea, sin Elin, uroti se protiv Pekaha, sina Remalijina, ubi ga i zakralji mjesto njega dvadesete godine Jotama, sina Uzijina.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 15, 31, 'Ostala povijest Pekahova, sve što je učinio, sve je to zapisano u knjizi Ljetopisa izraelskih kraljeva.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 15, 32, 'Druge godine kraljevanja Pekaha, sina Remalijina, nad Izraelom, postade judejskim kraljem Jotam, sin Uzijin.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 15, 33, 'Bilo mu je dvadeset i pet godina kad se zakraljio, a kraljevao je šesnaest godina u Jeruzalemu. Materi mu bješe ime Jeruša, Sadokova kći.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 15, 34, 'Činio je što je pravo u Jahvinim očima, sasvim kao i otac mu Uzija.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 15, 35, 'Ali ni on nije srušio uzvišica; narod je svejednako prinosio žrtve i kad na uzvišicama. On je sagradio Gornja vrata na Domu Jahvinu.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 15, 36, 'Ostala povijest Jotama i sve što je učinio, zar to nije sve zapisano u knjizi Ljetopisa judejskih kraljeva?');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 15, 37, 'U njegove je dane Jahve počeo slati protiv Judeje aramejskog kralja Resina i Pekaha, sina Remalijina.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 15, 38, 'Tada Jotam počinu kod otaca i sahraniše ga u gradu njegova praoca Davida. A na njegovo se mjesto zakralji sin mu Ahaz.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 16, 1, 'Sedamnaeste godine vladanja Pekaha, sina Remalijina, postade judejskim kraljem Ahaz, sin Jotamov.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 16, 2, 'Ahazu je bilo dvadeset godina kad se zakraljio, a kraljevao je šesnaest godina u Jeruzalemu, ali nije činio što je pravo u očima Jahve, Boga njegova, kao što je činio predak mu David.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 16, 3, 'Živio je poput izraelskih kraljeva i sam je proveo svoga sina kroz oganj po gnusnom običaju naroda što ih je Jahve protjerao pred Izraelovim sinovima.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 16, 4, 'Prinosio je žrtve i kad po uzvišicama i brežuljcima i pod svakim zelenim drvetom.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 16, 5, 'Tada aramejski kralj Resin i Pekah, sin Remalijin, kralj Izraela, pođoše u rat protiv Jeruzalema. Opsjedoše ga, ali ga ne mogoše osvojiti.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 16, 6, 'U to vrijeme aramejski kralj Resin vrati Elat Edomcima; protjerao je Judejce iz Elata; ušli su Edomci u njega i ondje su ostali do danas. -');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 16, 7, 'Tada Ahaz uputi poslanike asirskom kralju Tiglat-Pileseru da mu kažu: \"Ja sam tvoj sluga i sin tvoj! Dođi i izbavi me iz ruku aramejskog kralja i kralja Izraela, koji su se digli protiv mene.\"');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 16, 8, 'Ahaz je uzeo srebro i zlato što se nalazilo u Domu Jahvinu i u riznicama kraljevskog dvora i sve je poslao na dar asirskom kralju.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 16, 9, 'I posluša ga asirski kralj: otišao je na Damask i osvojio ga. Stanovništvo je odveo u sužanjstvo u Kir, a Resina je pogubio.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 16, 10, 'Kralj Ahaz otišao je u Damask u susret asirskom kralju Tiglat-Pileseru. I vidio je žrtvenik koji bijaše u Damasku. Tada kralj Ahaz posla svećeniku Uriji mjere žrtvenika, njegov nacrt i sve pojedinosti njegove građe.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 16, 11, 'Svećenik Urija sagradi žrtvenik; sve je upute što ih je kralj Ahaz uputio iz Damaska izvršio svećenik Urija prije nego što se kralj Ahaz vratio iz Damaska.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 16, 12, 'Pošto je kralj Ahaz stigao iz Damaska, vidio je žrtvenik, prišao mu i popeo se na nj.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 16, 13, 'Spalio je na žrtveniku svoju paljenicu i svoju prinosnicu, izlio svoju ljevanicu i krvlju pričesnica poškropio žrtvenik.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 16, 14, 'A mjedeni žrtvenik, koji bijaše pred Jahvom, maknuo je ispred Hrama, gdje je bio između novoga žrtvenika i Doma Jahvina. I postavio ga je pokraj novoga žrtvenika sa sjevera.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 16, 15, 'Kralj Ahaz zapovjedio je svećeniku Uriji: \"Na velikom ćeš žrtveniku spaljivati jutarnju paljenicu i večernju prinosnicu, kraljevu paljenicu i njegovu prinosnicu, i paljenice, prinosnice i ljevanice svega naroda. Po njemu ćeš izlijevati svu krv paljenica i klanica. A o žrtveniku od mjedi još ću razmisliti.\"');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 16, 16, 'Svećenik Urija učini sve što mu je naredio kralj Ahaz.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 16, 17, 'Kralj Ahaz skinuo je okvire s podnožja; s njih je skinuo i umivaonike. A mjedeno more skinuo je s volova koji su stajali pod njim i stavio ga na kameni pod.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 16, 18, 'Pred asirskim je kraljem uklonio iz Jahvina Doma Subotnji hodnik koji bijahu sagradili i vanjski kraljevski prilaz.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 16, 19, 'Ostala povijest Ahazova i sve što je učinio, zar to nije sve zapisano u knjizi Ljetopisa judejskih kraljeva?');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 16, 20, 'Ahaz je počinuo sa svojim ocima i sahranjen je u Davidovu gradu. Na njegovo se mjesto zakraljio sin mu Ezekija.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 17, 1, 'Dvanaeste godine kraljevanja Ahaza u Judeji, postao je Hošea, sin Elin, izraelskim kraljem u Samariji. Kraljevao je devet godina.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 17, 2, 'On je činio što je zlo u očima Jahvinim, ali ne kao izraelski kraljevi, njegovi prethodnici.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 17, 3, 'Asirski kralj Salmanasar pošao je protiv Hošee, koji mu se pokorio i plaćao mu danak.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 17, 4, 'Ali je asirski kralj otkrio da mu Hošea sprema zavjeru: još je Hošea poslao poslanike egipatskom kralju Sou i nije platio danaka asirskom kralju kao svake godine. Tada ga asirski kralj baci u tamnicu.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 17, 5, 'Asirski kralj osvoji svu zemlju i krenu opsjedati Samariju. Opsjedao ju je tri godine.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 17, 6, 'Devete godine Hošeine vladavine zauze asirski kralj Samariju i odvede Izraelce u sužanjstvo u Asiriju. Naselio ih je u Helahu, i na Haboru, rijeci u Gozanu, i u gradovima medijskim.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 17, 7, 'I tako se dogodilo zato što su Izraelci sagriješili protiv Jahve, Boga svoga, koji ih je izveo iz zemlje egipatske, ispod vlasti faraona, kralja egipatskog. Štovali su druge bogove,');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 17, 8, 'slijedili običaje naroda što ih je Jahve protjerao pred sinovima Izraelovim, živjeli po običajima što su ih uveli kraljevi Izraelovi.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 17, 9, 'Izraelci i njihovi kraljevi potajno su činili neprikladna djela protiv Jahve, Boga svoga. Podigli su uzvišice u svim svojim naseljima: od stražarskih kula pa do utvrđenih gradova.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 17, 10, 'Podizali su stupove i ašere na svakom humku i pod svakim zelenim drvetom.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 17, 11, 'Ondje su, na svim uzvišicama, palili kad po običaju naroda što ih je Jahve protjerao ispred njih i činili su zla djela te izazivali gnjev Jahvin.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 17, 12, 'Služili su idolima, premda im Jahve bijaše rekao: \"Ne činite toga!\"');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 17, 13, 'A Jahve opominjaše Izraelce i Judejce preko svih svojih proroka i sviju vidjelaca: \"Obratite se od zlog puta svoga\", govorio je, \"i pokoravajte se naredbama i zapovijedima mojim prema Zakonu koji sam naložio ocima vašim i prema svemu što sam vam objavio preko slugu svojih - proroka.\"');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 17, 14, 'Ali oni nisu poslušali nego su ostali tvrdovrati kao i njihovi oci, koji nisu vjerovali u Jahvu, Boga svoga.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 17, 15, 'Prezreli su njegove zakone i Savez koji je sklopio s njihovim ocima i opomene njegove koje im je upućivao. Težili su za ispraznošću, pa su i sami postali isprazni slijedeći narode oko sebe, premda im je Jahve zapovjedio da ne čine kao oni.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 17, 16, 'Odbacili su sve zapovijedi Jahve, Boga svoga, i načinili su sebi salivene idole, dva teleta. Podigli su ašere, klanjali se svoj vojsci nebeskoj i služili Baalu.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 17, 17, 'Provodili su svoje sinove i kćeri kroz oganj, odavali se vračanju i gatanju, čineći tako zlo u očima Jahvinim i razjarujući ga.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 17, 18, 'Tada se Jahve razgnjevi na Izraela i odbaci ga ispred svoga lica. Ostalo je samo pleme Judino.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 17, 19, 'Ali ni pleme Judino nije držalo zapovijedi Jahve, Boga svoga, i slijedilo je običaje kojih su se držali Izraelci.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 17, 20, 'I Jahve odbaci sav rod Izraela, ponizi ga i predade ga pljačkašima, dok ih konačno ne odbaci daleko od svoga lica.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 17, 21, 'On je, konačno, otrgnuo Izraelce od kuće Davidove, a Izrael je proglasio kraljem Jeroboama, sina Nebatova. Jeroboam je odvratio Izraela od Jahve i naveo ih na veliku grehotu.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 17, 22, 'Izraelci su slijedili svaki grijeh koji je Jeroboam počinio i od njega se nisu odvraćali,');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 17, 23, 'dok konačno Jahve nije odbacio Izraela ispred svoga lica, kako to bijaše objavio po svojim slugama, prorocima. Odveo je Izraelce iz njihove zemlje u sužanjstvo u Asiriju, gdje su do današnjega dana.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 17, 24, 'Asirski je kralj doveo ljude iz Babilona, iz Kute, iz Ave, Hamata i iz Sefarvajima, i naselio ih u gradovima Samarije mjesto Izraelaca. Oni su zaposjeli Samariju i nastanili se u gradovima njezinim.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 17, 25, 'U vrijeme naseljavanja u zemlju nisu štovali Jahve i on je poslao protiv njih lavove da ih rastrgaju.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 17, 26, 'Zato su rekli asirskom kralju: \"Narodi koje si preselio da ih nastaniš u gradovima Samarije ne znaju kako valja štovati Boga ove zemlje i on je na njih poslao lavove, koji ih usmrćuju, jer ti narodi ne poznaju bogoštovlja ove zemlje.\"');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 17, 27, 'Tada je asirski kralj izdao ovu zapovijed: \"Neka ide onamo jedan od svećenika koje sam odande doveo u sužanjstvo; neka ide, neka se ondje nastani i pouči ih u štovanju Boga one zemlje.\"');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 17, 28, 'Tako ode jedan od svećenika koji su bili odvedeni iz Samarije i nastani se u Betelu. On ih je poučio kako treba štovati Jahvu.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 17, 29, 'Svaki je narod imao likove svojih bogova i postavili su ih u hramove na uzvišicama koje su podigli Samarijanci, svaki narod u svojim gradovima u kojima življaše.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 17, 30, 'Babilonci načiniše Sukot Benota, Kušani Nergala, Hamaćani Ašimu;');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 17, 31, 'Avijci načiniše Nibhaza i Tartaka, a Sefarvajimci spaljivahu svoju djecu na ognju u čast Adrameleka i Anameleka, sefarvajimskih bogova.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 17, 32, 'Oni su štovali i Jahvu i postavili su neke između sebe za svećenike uzvišica koji su im prinosili žrtve u hramovima uzvišica.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 17, 33, 'Štovali su Jahvu i služili su svojim bogovima po običaju onih naroda između kojih su ih preselili.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 17, 34, 'Oni se još i danas drže starih običaja. Ne štuju Jahve i ne usklađuju svojih pravila i običaja sa Zakonom i zapovijedima što ih je Jahve naredio djeci Jakova komu je nadjenuo ime Izrael.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 17, 35, 'Jahve bijaše s njima sklopio Savez i zapovjedio im: \"Ne štujte tuđih bogova niti im se klanjajte. Nemojte ih štovati niti im žrtava prinositi.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 17, 36, 'Samo je Jahve onaj koji vas je velikom snagom svoje ispružene ruke izveo iz zemlje egipatske; njega štujte, njemu se klanjajte i njemu žrtve prinosite.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 17, 37, 'Držite se pravila i običaja, zakona i naredaba koje vam je propisao da ih vjerno ispunjavate uvijek i ne štujte tuđih bogova.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 17, 38, 'Nemojte zaboraviti Saveza koji sam sklopio s vama i nemojte štovati drugih bogova,');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 17, 39, 'samo Jahvu, Boga svoga, poštujte i on će vas izbaviti iz ruke svih vaših neprijatelja.\"');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 17, 40, 'Ali oni nisu poslušali, nego su se i dalje držali svoga starog običaja.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 17, 41, 'Tako su ti narodi štovali Jahvu, a služili su i svojim idolima. Njihovi sinovi i sinovi njihovih sinova čine do dana današnjega onako kako su činili njihovi oci.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 18, 1, 'Treće godine kraljevanja Hošee, sina Elina, u Izraelu, postao je judejskim kraljem Ezekija, sin Ahazov.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 18, 2, 'Bilo mu je dvadeset i pet godina kad se zakraljio. Kraljevao je dvadeset i devet godina u Jeruzalemu. Materi mu je bilo ime Abija, Zaharijina kći.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 18, 3, 'Činio je što je pravo u očima Jahvinim, sasvim kao njegov otac David.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 18, 4, 'On je uklonio uzvišice, srušio je stupove, sasjekao je ašere i razbio zmiju od mjedi koju bijaše načinio Mojsije. Izraelci su joj sve do tada prinosili žrtve. Zvali su je Nehuštan.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 18, 5, 'Pouzdavao se u Jahvu, Boga Izraelova. Ni prije njega ni poslije njega ne bijaše mu ravna među kraljevima judejskim.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 18, 6, 'Prionuo je uz Jahvu i nikada se nije okrenuo od njega. Držao je sve zapovijedi što ih je Jahve dao preko Mojsija.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 18, 7, 'I Jahve bijaše s njim, pomagaše ga u svim njegovim pothvatima. Pobunio se protiv asirskog kralja i nije mu više bio podložan.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 18, 8, 'On je potukao Filistejce do Gaze, opustošio njihovo područje od stražarskih kula sve do utvrđenih gradova.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 18, 9, 'Četvrte godine vladavine Ezekijine, a to je bila sedma godina kraljevanja izraelskog kralja Hošee, sina Elina, napade asirski kralj Salmanasar Samariju i opsjede je.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 18, 10, 'Osvojio ju je nakon tri godine. Šeste godine Ezekijine vladavine, a devete godine izraelskog kralja Hošee, pala je Samarija.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 18, 11, 'Asirski je kralj odveo Izraelce u sužanjstvo u Asiriju i naselio ih u Halahu, na Haboru, rijeci gozanskoj, i u medijskim gradovima.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 18, 12, 'Bijaše to stoga što nisu poslušali glas Jahve, Boga svoga, i što su prekršili njegov Savez i sve što im je naredio Mojsije, sluga Jahvin. Nisu ništa slušali niti vršili.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 18, 13, 'Četrnaeste godine Ezekijina kraljevanja asirski kralj Sanherib napade utvrđene judejske gradove i osvoji ih.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 18, 14, 'Tada judejski kralj Ezekija poruči asirskom kralju u Lakiš: \"Pogriješio sam! Obustavi svoje napade na me. Snosit ću sve što mi nametneš.\" Asirski kralj zatraži od Ezekije, judejskog kralja, tri stotine talenata srebra i trideset talenata zlata.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 18, 15, 'I dade Ezekija sve srebro što se našlo u Domu Jahvinu i u riznicama kraljevskog dvora.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 18, 16, 'U to je vrijeme Ezekija obio vrata i vratnice na Svetištu Jahvinu što ih bijaše pozlatio on sam, judejski kralj Ezekija, i posla to asirskom kralju.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 18, 17, 'Asirski je kralj poslao iz Lakiša u Jeruzalem kralju Ezekiji vrhovnog zapovjednika vojske, velikog dvoranina i peharnika s jakom vojskom. Krenuše oni, a kad su stigli u Jeruzalem, stadoše kod vodovoda Gornjeg ribnjaka, na putu u Valjarevo polje.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 18, 18, 'Oni pozvaše kralja. Pred njim je izašao upravitelj dvora Elijakim, sin Hilkijin, pisar Šebna i savjetnik Joah, sin Asafov.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 18, 19, 'Veliki peharnik reče im: \"Kažite Ezekiji: \'Ovako veli veliki kralj, kralj asirski: kakvo je to pouzdanje u koje se uzdaš?');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 18, 20, 'Misliš li da su prazne riječi već savjet i snaga za rat? U koga se uzdaš da si se pobunio protiv mene?');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 18, 21, 'Eto, oslanjaš se na Egipat, na slomljenu trsku koja probada i prodire dlan onomu tko se na nju nasloni. Takav je faraon, kralj egipatski, svima koji se uzdaju u njega.\'');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 18, 22, 'Možda ćete mi odgovoriti: \'Uzdamo se u Jahvu, Boga svojega.\' Ali nije li njemu Ezekija uklonio uzvišice i žrtvenike i zapovjedio Judejcima i Jeruzalemu: \'Samo se pred ovim žrtvenikom u Jeruzalemu klanjajte.\'');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 18, 23, 'Hajde, okladi se s mojim gospodarom, asirskim kraljem: dat ću ti dvije tisuće konja ako mogneš naći jahače za njih!');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 18, 24, 'Kako ćeš onda odoljeti jednome jedinom od najmanjih slugu moga gospodara? Ali se ti uzdaš u Egipat da će ti dati kola i konjanika.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 18, 25, 'Naposljetku, zar sam ja mimo volju Jahvinu krenuo protiv ovoga mjesta da ga razorim? Sam mi je Jahve rekao: \'Idi na tu zemlju i razori je!\'\"');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 18, 26, 'Elijakim, Šebna i Joah rekoše velikom peharniku: \"Molimo te, govori svojim slugama aramejski, jer mi razumijemo; ne govori s nama judejski da čuje narod koji je na zidinama!\"');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 18, 27, 'Ali im veliki peharnik odgovori: \"Zar me moj gospodar poslao da ovo kažem tvome gospodaru i tebi, a ne upravo onim ljudima koji sjede na zidinama, osuđeni da s vama jedu svoju nečist i piju svoju mokraću?\"');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 18, 28, 'Tada se veliki peharnik uspravi i u sav glas povika na judejskom ove riječi: \"Čujte riječ velikoga kralja, kralja asirskog!');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 18, 29, 'Ovako veli kralj: \'Neka vas Ezekija ne zavarava, jer vas ne može izbaviti iz moje ruke.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 18, 30, 'Neka vas Ezekija ne hrabri pouzdanjem u Jahvu govoreći: Jahve će nas sigurno izbaviti, ovaj grad neće pasti u ruke kralju asirskom.\'');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 18, 31, 'Ne slušajte Ezekije, jer ovako veli asirski kralj: \'Sklopite mir sa mnom, predajte mi se, pa neka svaki od vas jede plodove iz svoga vinograda i sa svoje smokve i neka pije vode iz svojega studenca');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 18, 32, 'dok ne dođem i ne odvedem vas u zemlju kao što je vaša, u zemlju pšenice i mošta, u zemlju kruha i vinograda, u zemlju ulja i meda da biste živjeli i da ne pomrete. Ne dajte da vas Ezekija zaludi govoreći vam: Jahve će vas izbaviti.\'');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 18, 33, 'Jesu li bogovi drugih naroda izbavili svoje zemlje iz ruku asirskoga kralja?');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 18, 34, 'Gdje su bogovi hamatski i arpadski, gdje su bogovi sefarvajimski, henski i ivski, gdje su bogovi samarijski da izbave Samariju iz ruke moje?');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 18, 35, 'Koji su među svim bogovima tih zemalja izbavili svoju zemlju iz moje ruke da bi Jahve izbavio Jeruzalem iz ruke moje?\"');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 18, 36, 'Šutjeli su i ni riječi mu nisu odgovorili, jer kralj bijaše zapovjedio: \"Ne odgovarajte mu!\"');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 18, 37, 'Upravitelj dvora Elijakim, sin Hilkijin, pisar Šebna i savjetnik Joah, sin Asafov, dođoše k Ezekiji, razdrijevši haljine, i saopćiše mu riječi velikoga peharnika');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 19, 1, 'Čuvši to, kralj Ezekija razdrije svoje haljine, obuče kostrijet i ode u Dom Jahvin.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 19, 2, 'Zatim posla Elijakima, upravitelja dvora, pisara Šebnu i svećeničke starješine, odjevene u kostrijet, k proroku Izaiji, sinu Amosovu.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 19, 3, 'Oni mu rekoše: \"Ovako veli Ezekija: \'Ovo je dan nevolje, kazne i rugla. Prispješe djeca do rođenja, a nema snage da se rode.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 19, 4, 'Možda je Jahve, Bog tvoj, čuo što je rekao veliki peharnik koga je asirski kralj, gospodar njegov, poslao da se izruguje Bogu živome i možda će Jahve, Bog tvoj, kazniti riječi koje je čuo! Pomoli se pobožno za Ostatak koji je još preostao.\'\"');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 19, 5, 'Kad su sluge kralja Ezekije stigle k Izaiji,');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 19, 6, 'on im reče: \"Kažite svome gospodaru: \'Ovako veli Jahve: Ne boj se riječi koje si čuo kada su na me hulile sluge kralja asirskoga.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 19, 7, 'Udahnut ću u njega duh i kad čuje jednu vijest, vratit će se u svoju zemlju. I učinit ću da u svojoj zemlji pogine od mača.\'\"');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 19, 8, 'Veliki peharnik vrati se i nađe asirskoga kralja gdje opsjeda Libnu, jer bijaše čuo da je kralj otišao iz Lakiša.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 19, 9, 'Dočuo je, naime, vijest o Tirhaku, kralju etiopskome: \"Evo, izašao je da se bori protiv tebe.\" Tada Sanherib ponovo uputi poslanike da kažu Ezekiji:');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 19, 10, '\"Ovako recite judejskom kralju Ezekiji: \'Neka te ne vara tvoj Bog, u koga se uzdaš, govoreći ti: Jeruzalem neće pasti u ruke asirskog kralja!');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 19, 11, 'Ti znaš što su asirski kraljevi učinili svim zemljama izručivši ih prokletstvu! A ti, ti li ćeš se spasiti?');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 19, 12, 'Jesu li bogovi spasili narode što su ih uništili moji oci: Gozance, Harane, Resefce i Edence, u Tel Basaru?');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 19, 13, 'Gdje je kralj hamatski, kralj arpadski, kralj Sefarvajima, Hene i Ive?\'\"');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 19, 14, 'Ezekija primi pismo iz ruke poslanikove i pročita ga. Zatim uđe u Dom Jahvin i razvi ga ondje pred Jahvom.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 19, 15, 'I pomoli se Ezekija Jahvi ovako: \"Jahve, Bože Izraelov, koji stoluješ nad kerubima, ti si Bog jedini nad svim zemaljskim kraljevstvima, ti si stvorio nebo i zemlju.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 19, 16, 'Prikloni uho, Jahve, i počuj, otvori oči, Jahve, i vidi! Sanheribove čujder riječi koje poruči da izruga Boga živoga.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 19, 17, 'Istina je, o Jahve, asirski su kraljevi zatrli narode i zemlje njihove;');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 19, 18, 'pobacali im u oganj bogove; jer ne bijahu bogovi to, već djela ruku ljudskih, od drveta i kamena; zato ih i uništiše.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 19, 19, 'Ali sada, Jahve, Bože naš, izbavi nas iz ruke njegove da spoznaju sva kraljevstva zemlje da si ti, Jahve, Bog jedini.\"');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 19, 20, 'Tada Izaija, sin Amosov, poruči Ezekiji: \"Ovako veli Jahve, Bog Izraelov: \'Uslišah molitvu koju mi uputi zbog Sanheriba, kralja asirskog.\'');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 19, 21, 'Evo riječi što je Jahve objavi protiv njega: Prezire te, ruga ti se djevica, kći sionska; za tobom maše glavom kći jeruzalemska.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 19, 22, 'Koga si grdio, hulio? Na koga si glasno vikao, ohol pogled dizao? Na Sveca Izraelova!');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 19, 23, 'Po slugama si svojim vrijeđao Gospoda. Govorio si: s mnoštvom kola ja popeh se na vrh gora, na najviše vrhunce Libanona. Posjekoh mu cedre najviše i čemprese ponajljepše. Dosegoh mu vrh najviši i vrt njegov šumoviti.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 19, 24, 'Kopao sam i pio sam vode tuđe; stopalima tad isuših sve rijeke egipatske.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 19, 25, 'Čuješ li dobro? Odavna to sam snovao, od iskona smišljao, sada to ostvarujem: na tebi je da prometneš gradove tvrde u razvaline.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 19, 26, 'Stanovnici njini, nemoćni, prepadnuti i smeteni, bjehu kao trava u polju, kao mlado zelenilo, kao trava vrh krovova opaljena vjetrom istočnim.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 19, 27, 'Znam kad se dižeš i kad sjedaš, kad izlaziš i kad se vraćaš.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 19, 28, 'Jer bjesnio si na me i jer obijest tvoja do ušiju mi dođe, prsten ću ti provuć\' kroz nozdrve, uzde stavit\' u žvale, vratit ću te putem kojim si i došao!');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 19, 29, 'A znak nek\' ti bude ovo: Ove će se godine jesti što se samo okrÄunÄi, dogodine što samo uzraste, a treće godine sijte i žanjite, sadite vinograde, jedite im rod.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 19, 30, 'Preživjeli iz kuće Judine žilje će pustit\' u dubinu, plodom rodit\' u visinu.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 19, 31, 'Jer će iz Jeruzalema izići Ostatak, Sačuvani s gore Siona. Sve će to učinit\' ljubomora Jahvina!');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 19, 32, 'Zato ovo govori Jahve o kralju asirskom: \'U ovaj grad on ući neće, ovamo strijele svoje neće izmetati, k njemu neće ni štit okrenuti, niti oko njega nasipe kopati.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 19, 33, 'Vratit će se putem kojim je i došao, u grad ovaj neće ući\' - Jahvina je riječ.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 19, 34, 'Grad ću ovaj štitit, spasiti ga, sebe radi i rad sluge svoga Davida.\"');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 19, 35, 'Te iste noći iziđe Anđeo Jahvin i pobi u asirskom taboru stotinu osamdeset i pet tisuća ljudi. Ujutro kad je valjalo ustati, gle, bijahu ondje sve sami mrtvaci.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 19, 36, 'Sanherib podiže tabor i ode. Vratio se u Ninivu.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 19, 37, 'Jednoga dana, dok se klanjao u hramu svoga boga Nisroka, njegovi ga sinovi Adramelek i Sareser ubiše mačem i pobjegoše u zemlju araratsku. Na njegovo se mjesto zakralji sin mu Asar-Hadon.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 20, 1, 'U ono se vrijeme Ezekija razbolje nasmrt. Prorok Izaija, sin Amosov, dođe mu i reče: \"Ovako veli Jahve: \'Uredi kuću svoju jer ćeš umrijeti; nećeš ozdraviti.\'\"');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 20, 2, 'Ezekija se okrenu zidu i ovako se pomoli Jahvi:');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 20, 3, '\"Ah, Jahve! Sjeti se milostivo da sam pred tobom hodio vjerno i poštena srca i da sam činio što je dobro u tvojim očima.\" I Ezekija briznu u gorak plač.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 20, 4, 'Izaija još ne bijaše izišao iz središnjeg predvorja kad mu je stigla riječ Jahvina:');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 20, 5, '\"Vrati se i reci Ezekiji, glavaru moga naroda. Ovako veli Jahve, Bog tvoga oca Davida: \'Uslišao sam tvoju molitvu, vidio sam tvoje suze. Izliječit ću te; za tri dana uzići ćeš u Dom Jahvin.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 20, 6, 'Dodat ću tvome vijeku još petnaest godina. Izbavit ću tebe i ovaj grad iz ruku asirskoga kralja; zakrilit ću ovaj grad radi sebe i sluge svoga Davida.\'\"');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 20, 7, 'Izaija naloži: \"Uzmite oblog od smokava, privijte mu ga na čir i on će ozdraviti.\"');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 20, 8, 'Ezekija upita Izaiju: \"Po kojem ću znaku prepoznati da će me Jahve izliječiti i da ću za tri dana uzići u Dom Jahvin?\"');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 20, 9, 'Izaija odgovori: \"Evo ti znaka od Jahve da će učiniti što je rekao: hoćeš li da se sjena pomakne za deset stupnjeva naprijed ili da se vrati za deset stupnjeva?\"');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 20, 10, 'Ezekija odgovori: \"Lako je sjeni pomaknuti se deset stupnjeva naprijed! Ne! Neka se sjena vrati natrag za deset stupnjeva!\"');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 20, 11, 'Prorok Izaija zazva Jahvu i on učini da se sjena vrati za deset stupnjeva. Sišla je za deset posljednjih stupnjeva na Ahazovu sunčaniku.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 20, 12, 'U to vrijeme posla babilonski kralj Merodak-Baladan, sin Baladanov, pisma s darom Ezekiji, jer bijaše čuo da se razbolio i ozdravio.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 20, 13, 'Ezekija se obradova tome i pokaza poslanicima svoju riznicu - srebro, zlato, miomirise, mirisavo ulje - svoju oružanu i sve što je bilo u skladištima. Nije bilo ničega u njegovu dvoru i svemu njegovu gospodarstvu što im Ezekija nije pokazao.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 20, 14, 'Tada prorok Izaija dođe kralju Ezekiji i upita ga: \"Što su rekli ti ljudi i odakle su došli k tebi?\" Ezekija odgovori: \"Došli su iz daleke zemlje, iz Babilona.\"');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 20, 15, 'Izaija upita dalje: \"Što su vidjeli u tvojem dvoru?\" Ezekija odgovori: \"Vidjeli su sve što je u mojem dvoru; nema u mojim skladištima ničega što im nisam pokazao.\"');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 20, 16, 'Tada Izaija reče Ezekiji: \"Čuj riječ Jahvinu:');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 20, 17, '\'Evo dolaze dani kada će sve što je u tvojem dvoru, sve što su tvoji oci nakupili do danas, biti odneseno u Babilon. Ništa neće ostati, \' kaže Jahve.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 20, 18, 'A od sinova što poteku od tebe, što ti se rode, neke će uzeti da budu uškopljeni dvorani u palači babilonskoga kralja.\"');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 20, 19, 'Ezekija odgovori Izaiji: \"Povoljna je riječ koju ti je Jahve objavio.\" A mislio je: \"Zašto ne? Ako bude mira i sigurnosti za moga života!\"');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 20, 20, 'Ostala povijest Ezekijina, svi njegovi pothvati i kako je sagradio ribnjak i prorov da dovede vodu u grad, zar sve to nije zapisano u knjizi Ljetopisa judejskih kraljeva?');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 20, 21, 'Ezekija je počinuo sa svojim ocima, a njegov sin Manaše zakralji se mjesto njega.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 21, 1, 'Manašeu je bilo dvanaest godina kad se zakraljio. Pedeset i pet godina kraljevao je u Jeruzalemu. Njegova se majka zvala Hefsi-Bah.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 21, 2, 'Činio je što je zlo u Jahvinim očima, povodeći se za gnusobama naroda što ih je Jahve protjerao pred Izraelovim sinovima.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 21, 3, 'Obnovio je uzvišice što ih bijaše oborio otac mu Ezekija, podigao je žrtvenik Baalu, načinio ašere kako bijaše učinio izraelski kralj Ahab; i stao se klanjati svoj vojsci nebeskoj i služiti joj.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 21, 4, 'Podigao je žrtvenike i u Domu Jahvinu, za koji bijaše rekao Jahve: \"U Jeruzalemu će prebivati moje Ime zauvijek.\"');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 21, 5, 'Sagradio je žrtvenike svoj nebeskoj vojsci u oba predvorja Doma Jahvina.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 21, 6, 'I sinove je svoje proveo kroz oganj. Vračao je, gatao, stvorio bajače i opsjenare, učinio je premnogo zla u očima Jahve i razjarivao ga.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 21, 7, 'Dao je načiniti lik Ašere i posadio ga u Domu, za koji Jahve bijaše rekao Davidu i njegovu sinu Salomonu: \"U ovom Domu i u Jeruzalemu, koji sam izabrao među svim izraelskim plemenima, postavit ću svoje Ime zauvijek.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 21, 8, 'Neću više dati da noga Izraelaca uzmakne iz zemlje koju sam dao u baštinu njihovim očevima, samo ako budu držali i provodili u djelo sve što sam im zapovjedio: Zakon što im ga je objavio moj sluga Mojsije.\"');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 21, 9, 'Ali oni nisu poslušali, Manaše ih je zaveo te su radili još gore nego narodi što ih je Jahve iskorijenio pred Izraelovim sinovima.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 21, 10, 'Tada je Jahve ovako govorio preko slugu svojih proroka:');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 21, 11, '\"Zato što je judejski kralj Manaše činio te gnusobe, zato što je učinio više zla nego što su prije njega radili Amorejci i što je zaveo Judejce svojim idolima,');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 21, 12, 'ovako veli Jahve, Bog Izraelov: \'Evo, učinit ću da dođe nevolja na Jeruzalem i Judeju, takva da će zazujati oba uha onima koji o njoj čuju.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 21, 13, 'Nategnut ću nad Jeruzalemom isto uže kao nad Samarijom, isto mjerilo kao nad kućom Ahabovom; zbrisat ću Jeruzalem kao što se briše zdjela pa se tad izvrne.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 21, 14, 'Odbacit ću ostatke svoje baštine, predat ću ih u ruke njihovih neprijatelja; služit će za plijen i grabež svim svojim neprijateljima');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 21, 15, 'jer su činili što je zlo u mojim očima jer su izazivali moj gnjev od dana kada su njihovi oci izišli iz Egipta pa sve do danas.\'\"');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 21, 16, 'I mnogo je nedužne krvi prolio Manaše, tako da se njome napunio Jeruzalem od jednoga kraja do drugoga, da se i ne spominje njegov grijeh kojim je zaveo Judu da čini što je zlo u očima Jahvinim.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 21, 17, 'Ostala povijest Manašeova, njegova djela i grijesi koje je počinio, zar sve to nije zapisano u knjizi Ljetopisa judejskih kraljeva?');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 21, 18, 'Manaše je počinuo kraj svojih otaca i sahranjen je u vrtu svojeg dvora, u vrtu Uzinu. Sin mu Amon zakralji se mjesto njega.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 21, 19, 'Amonu bijahu dvadeset i dvije godine kad je zavladao, a kraljevao je dvije godine u Jeruzalemu. Njegova se majka zvala Mešulemet, kći Harusova, i bila je iz Jotbe.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 21, 20, 'On je činio što je zlo u očima Jahvinim, kao što je činio njegov otac Manaše.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 21, 21, 'U svemu je slijedio put svoga oca, služio je idolima kojima je služio i njegov otac i klanjao im se.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 21, 22, 'On je ostavio Jahvu, Boga svojih praotaca, i nije hodio putem Jahvinim.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 21, 23, 'Amonovi se časnici urotiše protiv njega i ubiše kralja u dvoru.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 21, 24, 'Ali je prosti puk pobio sve one koji se bijahu urotili protiv kralja Amona i na njegovo mjesto zakraljio sina mu Jošiju.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 21, 25, 'Ostala povijest Amonova i sve što je činio, zar sve to nije zapisano u knjizi Ljetopisa judejskih kraljeva?');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 21, 26, 'Pokopali su ga u grobnicu njegova oca, u vrtu Uzinu, a njegov sin Jošija zakralji se mjesto njega.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 22, 1, 'Jošiji je bilo osam godina kad se zakraljio. Kraljevao je trideset i jednu godinu u Jeruzalemu. Mati mu se zvala Jedida, kći Adajina, i bila je iz Boskata.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 22, 2, 'Činio je što je pravo u Jahvinim očima. U svemu je hodio putem svoga oca Davida, ne skrećući ni desno ni lijevo.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 22, 3, 'Osamnaeste godine svoga kraljevanja Jošija posla svoga tajnika Šafana, sina Asalijahina, sina Mešulamova, u Dom Jahvin i reče mu:');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 22, 4, '\"Idi velikom svećeniku Hilkiji da ti pripremi novac koji je odnesen u Dom Jahvin i koji su čuvari praga sakupili od naroda.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 22, 5, 'Neka ga uruči poslovođama postavljenim u Domu Jahvinu, a oni neka isplate radnike koji popravljaju Dom Jahvin,');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 22, 6, 'drvodjelje, graditelje i zidare, i da se kupuje drvo i kamenje klesano što je potrebno za popravak Doma.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 22, 7, 'Ali neka se ne traži od njih račun za uručeni novac jer oni rade pošteno.\"');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 22, 8, 'Veliki svećenik Hilkija reče tajniku Šafanu: \"Našao sam Knjigu Zakona u Domu Jahvinu.\" I Hilkija dade knjigu Šafanu, koji ju je pročitao.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 22, 9, 'Tajnik Šafan dođe kralju te ga izvijesti: \"Tvoje sluge\", reče on, \"pokupile su novac koji se našao u Domu i predale su ga poslovođama postavljenim u Domu Jahvinu.\"');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 22, 10, 'Tada tajnik Šafan obavijesti kralja: \"Svećenik Hilkija dade mi jednu knjigu.\" I Šafan je poče čitati pred kraljem.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 22, 11, 'Čuvši riječi Knjige Zakona, kralj razdrije haljine svoje.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 22, 12, 'I naredi svećeniku Hilkiji, Šafanovu sinu Ahikamu, Mikinu sinu Akboru, tajniku Šafanu i kraljevu sluzi Asaji:');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 22, 13, '\"Idite i upitajte Jahvu o meni, i o narodu, i o svoj Judeji zbog ove knjige što je nađena, jer je velika Jahvina jarost što se izlila na nas zato što naši očevi nisu slušali riječi ove knjige, nisu vršili što nam je u njoj napisano.\"');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 22, 14, 'Svećenik Hilkija, Ahikam, Akbor, Šafan i Asaja odoše proročici Huldi, ženi Šaluma, sina Tikvina, sina Harkasova, čuvara odjeće; ona je živjela u Jeruzalemu, u novom gradu. Kad joj to kazaše,');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 22, 15, 'ona im reče: \"Ovako veli Jahve, Bog Izraelov: \'Kažite čovjeku koji vas je poslao k meni:');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 22, 16, 'Ovako veli Jahve: Evo, dovest ću nesreću na ovaj grad i na njegove stanovnike, izvršit ću sve što kaže knjiga koju je pročitao judejski kralj.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 22, 17, 'Jer su me ostavili i prinose žrtve tuđim bogovima da bi me ljutili svim djelima ruku svojih, planut će jarost moja na to mjesto i neće se ugasiti.\'');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 22, 18, 'A judejskom kralju, koji vas je poslao po Jahvin savjet, recite ovo: \'Ovako veli Jahve, Bog Izraelov: Riječi si čuo.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 22, 19, 'Ali kako ti je omekšalo srce i jer si se ponizio pred Jahvom čuvši što sam objavio tome gradu i njegovim stanovnicima, koje će pogoditi pustošenje i prokletstvo, i jer si razdro haljine svoje i plakao preda mnom, zato sam te uslišio\' - riječ je Jahvina.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 22, 20, '\'Evo, sjedinit ću te s ocima tvojim i s mirom ćeš leći u grob da ne vidiš svojim očima svu nesreću koju ću svaliti na ovo mjesto.\'\" Oni odnesoše taj odgovor kralju.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 23, 1, 'Tada kralj posla da se saberu kod njega sve judejske i jeruzalemske starješine.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 23, 2, 'Kralj potom uzađe u Dom Jahvin s Judejcima, Jeruzalemcima, svećenicima i prorocima i sa svim narodom, od najmanjega do najvećega. I pročita im sve riječi Knjige Saveza koja je nađena u Domu Jahvinu.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 23, 3, 'Kralj, stojeći na svome mjestu, obnovi pred Jahvom Savez da će slijediti Jahvu i držati se njegovih zapovijedi, pouka i uredaba svim srcem i svom dušom da bi ispunio sve stavke toga Saveza zapisane u ovoj knjizi. Sav je narod stupio u Savez.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 23, 4, 'Kralj je zapovjedio velikom svećeniku Hilkiji, svećenicima drugog reda i čuvarima hramskog praga da iz Svetišta Jahvina iznesu sve bogoslužne predmete što bijahu načinjeni za Baala, za Ašeru i za svu nebesku vojsku. Odredio je da sve to spale izvan Jeruzalema u poljima kidronskim, a pepeo je odnio u Betel.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 23, 5, 'Uklonio je lažne svećenike koje su judejski kraljevi postavili da pale kad na uzvišicama, u gradovima judejskim i u okolici Jeruzalema; i one koji su palili kad Baalu, suncu, mjesecu, zvijezdama i svoj vojsci nebeskoj.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 23, 6, 'Izvan Jeruzalema iznio je iz Doma Jahvina, u dolinu kidronsku, Ašeru i spalio ju je u dolini kidronskoj, satro u prah, a prah bacio na groblje sinova pučkih.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 23, 7, 'Razorio je stanove posvećenih bludnica koji su bili u Domu Jahvinu i u kojima su žene tkale haljine Ašeri.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 23, 8, 'Iz svih judejskih gradova doveo je svećenike i oskvrnuo je uzvišice gdje su ti svećenici prinosili kad, od Gebe do Beer Šebe. Zatim je srušio uzvišice pred vratima, one koje su bile na ulazu vrata Jošue, upravitelja grada, nalijevo kad se prilazi gradskim vratima.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 23, 9, 'Isto tako svećenici uzvišica nisu mogli uzlaziti žrtveniku Jahvinu u Jeruzalemu, ali su jeli kruhove bez kvasa među svojom braćom.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 23, 10, 'Oskvrnio je Tofet u dolini Ben Hinom, kako nitko ne bi svoga sina ili kćerku provodio kroz oganj u čast Moleku.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 23, 11, 'Razagnao je konje koje su judejski kraljevi prinijeli suncu na ulazu u Dom Jahvin, kraj sobe dvoranina Netan Meleka, koja se nalazila u blizini, i spalio je u ognju sunčana kola.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 23, 12, 'Žrtvenike na krovu koje bijahu sagradili judejski kraljevi i one koje je sagradio Manaše u oba predvorja Hrama Jahvina, kralj je srušio, uklonio ih odatle i bacio njihov prah u dolinu kidronsku.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 23, 13, 'Uzvišice koje su bile sučelice Jeruzalemu, na južnom dijelu Maslinske gore, i koje je izraelski kralj Salomon bio sagradio Aštarti, sramoti sidonskoj, Kemošu, sramoti moapskoj, i Milkomu, nakazi amonskoj - sve ih je kralj oskvrnio.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 23, 14, 'Razbio je stupove, iskorijenio ašere i njihova je mjesta ispunio ljudskim kostima.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 23, 15, 'Isto tako i žrtvenik u Betelu, uzvišicu koju je sagradio Jeroboam, sin Nebatov, koji je naveo Izraela na grijeh, kralj je srušio, oborio žrtvenik i tu uzvišicu, satro kamenje u prah, spalio ašere.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 23, 16, 'A kad se Jošija okrenuo i vidio grobove koji bijahu ondje na gori, posla da se sakupe kosti iz onih grobova i spali ih na žrtveniku. Tako ga je oskvrnuo, izvršavajući riječ Jahvinu, koju je objavio čovjek Božji (dok je Jeroboam bio na žrtveniku za vrijeme svečanosti). Okrenuvši se, Jošija baci oči na grob čovjeka Božjeg koji je objavio sve to');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 23, 17, 'i upita: \"Kakav je ono spomenik što ga vidim?\" Ljudi iz grada odgovoriše mu: \"To je grob čovjeka Božjeg koji je došao iz Judeje i koji je prorekao sve ovo što si ti učinio s betelskim žrtvenikom.\"');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 23, 18, '\"Pustite ga na miru\", reče kralj, \"i neka nitko ne dira njegove kosti.\" Tako su ostale njegove kosti netaknute s kostima proroka koji je došao iz Samarije.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 23, 19, 'Jošija je jednako razorio sve hramove uzvišica koje su izraelski kraljevi sagradili po gradovima Samarije da bi srdili Jahvu i učinio je s njima kao što je učinio u Betelu.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 23, 20, 'Sve svećenike uzvišica poklao je na žrtvenicima; na njima je spalio i ljudske kosti. Potom se vratio u Jeruzalem.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 23, 21, 'Kralj naredi svemu narodu: \"Svetkujte Pashu u čast Jahve, Boga svoga, po običaju koji je zapisan u ovoj Knjizi Saveza.\"');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 23, 22, 'Takva se Pasha nije svetkovala od vremena sudaca koji su sudili Izraelu i za sve vrijeme kraljeva izraelskih i judejskih.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 23, 23, 'Samo je osamnaeste godine kraljevanja Jošijina svetkovana takva Pasha u čast Jahve, u Jeruzalemu.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 23, 24, 'Osim toga, sve bajače i sve vračare, sve kućne bogove i idole i sve sramote koje se mogu vidjeti u zemlji judejskoj i Jeruzalemu - sve je to Jošija uklonio da izvrši riječi Zakona, zapisane u knjizi koju je našao Hilkija, svećenik Doma Jahvina.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 23, 25, 'Nije bilo prije njega takva kralja koji se obratio Jahvi svim srcem svojim, svom dušom svojom i svom snagom svojom, u svemu vjeran Zakonu Mojsijevu, a ni poslije njega nije mu bilo ravna.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 23, 26, 'Ipak Jahve nije odustao od plamena svoga velikoga gnjeva kojim je uskipio protiv Judejaca zbog svih izazova kojima ga je Manaše ljutio.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 23, 27, 'Jahve je odlučio: \"Maknut ću Judejce ispred sebe kao što sam maknuo Izraela; odbacit ću ovaj grad koji sam izabrao, Jeruzalem, i Dom o kojem rekoh: \'Tu će biti Ime moje.\'\"');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 23, 28, 'Ostala povijest Jošijina i sve što je učinio, zar sve to nije zapisano u knjizi Ljetopisa judejskih kraljeva?');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 23, 29, 'U njegvo je vrijeme faraon Neko, egipatski kralj, krenuo protiv asirskoga kralja na rijeci Eufratu. Kralj Jošija pošao je preda nj, ali ga on ubi u Megidu, pri prvom susretu.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 23, 30, 'Sluge njegove prenesoše mu tijelo kolima iz Megida, odvezoše ga u Jeruzalem i sahraniše u njegovoj grobnici. Sav narod zemlje primi Joahaza, sina Jošijina; pomazaše ga i proglasiše kraljem namjesto njegova oca.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 23, 31, 'Joahazu bijahu dvadeset i tri godine kad se zakraljio. Kraljevao je tri mjeseca u Jeruzalemu. Njegova se majka zvala Hamitah, kći Jeremije, i bila je iz Libne.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 23, 32, 'On je činio što je zlo u očima Jahvinim, sve kao što su činili oci njegovi.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 23, 33, 'Faraon Neko bacio ga je u okove u Ribli, na području Hamata, da ne vlada u Jeruzalemu i udario je na zemlju danak od stotinu talenata srebra i deset talenata zlata.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 23, 34, 'Faraon Neko postavio je za kralja Elijakima, sina Jošijina, na mjesto njegova oca Jošije. I ime mu je promijenio u Jojakim. A Joahaza je uzeo i odveo u Egipat te on umrije ondje.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 23, 35, 'Jojakim je dao faraonu srebro i zlato, ali je nametnuo zemlji porez da bi smogao svotu koju je faraon zahtijevao. Svakome je nametnuo prema njegovu stanju, uzimao srebro i zlato koje je morao davati faraonu Neku.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 23, 36, 'Jojakimu je bilo dvadeset i pet godina kad je postao kraljem i kraljevao je jedanaest godina u Jeruzalemu. Materi mu je bilo ime Zebida, kći Pedajina, i bila je iz Rume.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 23, 37, 'On je činio što je zlo u očima Jahvinim, sve kao što su činili i oci njegovi.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 24, 1, 'U njegovo je vrijeme došao Nabukodonozor, kralj babilonski, i Jojakim mu je bio podložan tri godine, zatim se ponovno pobunio protiv njega.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 24, 2, 'Ovaj pak posla protiv njega kaldejske pljačkaške čete, aramejske, moapske i amonske, sve ih posla protiv Judeje da je opustoše, potvrđujući riječ koju je Jahve bio objavio po slugama svojim prorocima.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 24, 3, 'To se dogodilo Judeji prema prijetnji Jahvinoj da će je istrijebiti ispred svoga lica zbog grijeha Manašeovih: zbog svega što je Manaše učinio');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 24, 4, 'i zbog nedužne krvi koju je prolio, natopio Jeruzalem krvlju nedužnom. Jahve nije htio oprostiti.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 24, 5, 'Ostala povijest Jojakimova i sve što je učinio, zar sve to nije zapisano u knjizi Ljetopisa judejskih kraljeva?');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 24, 6, 'Jojakim je počinuo kraj svojih otaca, a njegov sin Jojakin zavlada mjesto njega.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 24, 7, 'Egipatski kralj nije više izlazio iz zemlje, jer je babilonski kralj osvojio od Egipatskog potoka do rijeke Eufrata sve što je pripadalo egipatskom kralju.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 24, 8, 'Jojakinu je bilo osamnaest godina kad se zakraljio i kraljevao je tri mjeseca u Jeruzalemu. Materi mu je bilo ime Nehušta, kći Elnatana, i bila je iz Jeruzalema.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 24, 9, 'On je činio što je zlo u očima Jahvinim, sve kao što je činio i njegov otac.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 24, 10, 'U ono vrijeme krenu ljudstvo babilonskog kralja Nabukodonozora protiv Jeruzalema i grad je bio opkoljen.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 24, 11, 'Dođe i babilonski kralj Nabukodonozor da napadne grad, dok ga je njegovo ljudstvo opsjedalo.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 24, 12, 'Tada je judejski kralj Jojakin izišao pred babilonskoga kralja: on, njegova majka, njegove sluge, njegove vojskovođe i dvorani, a babilonski kralj zarobi ga - osme godine svoga kraljevanja.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 24, 13, 'On je odnio sve iz riznice Doma Jahvina i iz riznica kraljevskog dvora i razbio je sve zlatne predmete koje je Salomon, kralj Izraela, načinio za Svetište Jahvino. Tako se ispunila riječ Jahvina.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 24, 14, 'Odveo je u progonstvo sav Jeruzalem, sve vojskovođe i sve vrsne ratnike, oko deset tisuća prognanika, sa svim kovačima i bravarima. Jedino je preostao najsiromašniji narod zemlje.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 24, 15, 'Odveo je Jojakina u Babilon; tako isto i kraljevu majku i sve žene kraljeve, njegove dvorane, plemenitaše zemlje, sve ih je odveo iz Jeruzalema u progonstvo u Babilon.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 24, 16, 'Sve sposobne ljude, njih sedam tisuća na broju; kovače i bravare, tisuću na broju; sve ljude sposobne za boj, sve ih je kralj babilonski odveo u Babilon, u sužanjstvo.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 24, 17, 'Babilonski je kralj postavio za kralja mjesto Jojakina njegova strica Mataniju, ali mu je promijenio ime u Sidkija.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 24, 18, 'Sidkiji je bila dvadeset i jedna godina kad se zakraljio, a kraljevao je jedanaest godina u Jeruzalemu. Materi mu bijaše ime Hamitala, kći Jeremije, i bila je iz Libne.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 24, 19, 'Činio je što je zlo u očima Jahvinim, sve kao što je činio Jojakin.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 24, 20, 'To je zadesilo Jeruzalem i Judu zbog gnjeva Jahvina; Jahve ih napokon i odbaci ispred lica svoga. Sidkija se pobuni protiv babilonskog kralja.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 25, 1, 'Devete godine njegova kraljevanja, desetoga dana desetoga mjeseca, krenu sam babilonski kralj Nabukodonozor sa svom svojom vojskom na Jeruzalem. Utabori se pred gradom i opasa ga opkopom.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 25, 2, 'Grad osta opkoljen do jedanaeste godine Sidkijina kraljevanja.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 25, 3, 'Devetoga dana četvrtoga mjeseca, kad je u gradu zavladala takva glad da priprosti puk nije imao ni kruha,');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 25, 4, 'neprijatelj provali u grad. Tada kralj i svi ratnici pobjegoše noću kroz vrata između dva zida nad Kraljevim vrtom - Kaldejci bijahu opkolili grad - i krenuše putem prema Arabi.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 25, 5, 'Kaldejske čete nagnuše u potjeru za kraljem i sustigoše ga na Jerihonskim poljanama, a sva se njegova vojska razbježala.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 25, 6, 'Kaldejci uhvatiše kralja i odvedoše ga u Riblu pred kralja babilonskog, koji mu izreče presudu.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 25, 7, 'Sidkijine sinove pokla pred njegovim očima, Sidkiji iskopa oči, okova ga verigama i odvede u Babilon.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 25, 8, 'Sedmoga dana petoga mjeseca - devetnaeste godine kraljevanja Nabukodonozora, kralja babilonskog - uđe u Jeruzalem Nebuzaradan, zapovjednik kraljeve tjelesne straže i časnik babilonskog kralja.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 25, 9, 'On zapali Dom Jahvin, kraljevski dvor i sve kuće u Jeruzalemu.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 25, 10, 'Kaldejske čete, pod zapovjednikom kraljevske tjelesne straže, razoriše zidine koje su okruživale Jeruzalem.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 25, 11, 'Nebuzaradan, zapovjednik kraljeve tjelesne straže, odvede u sužanjstvo ostatak naroda koji bijaše ostao u gradu, a tako i prebjege babilonskom kralju i ostalu svjetinu.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 25, 12, 'Neke od malih ljudi ostavi zapovjednik u zemlji kao vinogradare i ratare.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 25, 13, 'Kaldejci razbiše tučane stupove u Domu Jahvinu, podnožja i mjedeno more koji su bili u Domu Jahvinu i tuč odniješe u Babilon.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 25, 14, 'Uzeše i lonce, lopate, noževe, posudice i uopće sav tučani pribor koji se upotrebljavao za bogoslužja.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 25, 15, 'Zapovjednik uze i kadionice i škropionice, uopće sve što bijaše od zlata i srebra,');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 25, 16, 'dva stupa, jedno more i podnožja, što je Salomon dao izraditi za Dom Jahvin. Nije moguće procijeniti koliko je tuča bilo u svim tim predmetima.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 25, 17, 'Prvi stup bijaše visok osamnaest lakata, imao je glavicu od tuča, visoku pet lakata; obvijaše je oplet i mogranji, sve od tuča. Takav je bio i drugi stup.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 25, 18, 'Zapovjednik straže odveo je svećeničkog poglavara Seraju, drugog svećenika, Sefaniju, i tri čuvara praga.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 25, 19, 'Iz grada je odveo jednog dvoranina, vojničkog zapovjednika, pet ljudi iz kraljeve pratnje koji se zatekoše u gradu, pisara zapovjednika vojske koji je novačio puk i šezdeset pučana koji se također zatekoše u gradu.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 25, 20, 'Zapovjednik kraljevske tjelesne straže Nebuzaradan odvede ih pred kralja babilonskoga u Riblu.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 25, 21, 'I kralj babilonski zapovjedi da ih pogube u Ribli, u zemlji hamatskoj. Tako su judejski narod odveli s njegove rodne grude.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 25, 22, 'Narodu što je ostao u zemlji judejskoj i što ga je ostavio babilonski kralj Nabukodonozor - postavio je ovaj za upravitelja Gedaliju, sina Ahikamova, unuka Šafanova.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 25, 23, 'Svi vojni zapovjednici i njihovi ljudi saznaše da je babilonski kralj postavio zemlji za namjesnika Gedaliju i dođoše pred njega u Mispu: Netanijin sin Jišmael; Kareahov sin Johanan; sin Tanhumeta iz Netofe, Seraja; Maakatijev sin Jaazanija - oni i svi njihovi ljudi.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 25, 24, 'Gedalija se zakle njima i njihovim ljudima i reče: \"Ne bojte se služiti Kaldejcima; ostanite u zemlji, budite podložni babilonskom kralju i bit će vam dobro.\"');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 25, 25, 'Ali sedmoga mjeseca Jišmael, sin Netanijin, unuk Elišamin, koji bijaše kraljevskog roda, i još deset ljudi s njim ubiše Gedaliju te on umrije kao i svi Judejci i Kaldejci koji bijahu s njim u Mispi.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 25, 26, 'Tada sav narod, od maloga do velikog, i svi zapovjednici četa ustadoše i odoše u Egipat jer se bojahu Kaldejaca.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 25, 27, 'Trideset i sedme godine otkako je zasužnjen judejski kralj Jojakin, dvadeset i sedmog dana dvanaestoga mjeseca, babilonski kralj Evil Merodak u prvoj godini svoje vladavine pomilova judejskog kralja Jojakina i pusti ga iz tamnice.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 25, 28, 'Ljubezno je s njime razgovarao i stolicu mu postavio više nego ostalim kraljevima koji bijahu s njim u Babilonu.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 25, 29, 'Jojakin je odložio svoje tamničke haljine i jeo s kraljem za istim stolom svega svoga vijeka.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 25, 30, 'Do kraja njegova života babilonski mu je kralj trajno, iz dana u dan, davao uzdržavanje.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 1, 1, 'Adam, Šet, Enoš,');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 1, 2, 'Kenan, Mahalalel, Jared,');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 1, 3, 'Henok, Metušalah, Lamek,');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 1, 4, 'Noa, Šem, Ham i Jafet.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 1, 5, 'Sinovi Jafetovi: Gomer, Magog, Madaj, Javan, Tubal, Mešek i Tiras.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 1, 6, 'Gomerovi sinovi: Aškenaz, Rifat i Togarma.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 1, 7, 'Javanovi sinovi: Eliša, Taršiš, Kitijci i Dodanci.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 1, 8, 'Hamovi sinovi: Kuš, Misrajim, Put i Kanaan.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 1, 9, 'Kuševi sinovi: Seba, Havila, Sabta, Rama i Sabteka; Ramini sinovi: Šeba i Dedan.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 1, 10, 'Kušu se rodi Nimrod, koji bijaše prvi vlastodržac na zemlji.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 1, 11, 'Od Misrajima potekli su Ludijci, Anamijci, Lehabijci, Neftuhijci,');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 1, 12, 'Patrušani i Kasluhijci, od kojih su potekli Filistejci i Kaftorci.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 1, 13, 'Kanaan rodi Sidona, svog prvenca, i Heta,');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 1, 14, 'i Jebusejce, Amorejce, Girgašane,');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 1, 15, 'Hivijce, Arkijce, Sinijce,');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 1, 16, 'Arvadijce, Semarijce i Hamatijce.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 1, 17, 'Šemovi sinovi: Elam, Ašur, Arpakšad, Lud i Aram. Aramovi sinovi: Us, Hul, Geter i Mešek.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 1, 18, 'Arpakšadu se rodi Šelah, Šelahu se rodi Eber.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 1, 19, 'Eberu se rodiše dva sina: jednom bješe ime Peleg, jer se za njegova doba razdijelila zemlja. Njegovu je bratu bilo ime Joktan.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 1, 20, 'Od Joktana se rodiše Almodad, Šelef, Hasarmavet, Jerah,');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 1, 21, 'Hadoram, Uzal, Dikla,');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 1, 22, 'Obal, Abimael, Šeba,');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 1, 23, 'Ofir, Havila i Jobab. Svi su to sinovi Joktanovi.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 1, 24, 'Šem, Arpakšad, Šalah,');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 1, 25, 'Eber, Peleg, Rau,');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 1, 26, 'Serug, Nahor, Tarah,');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 1, 27, 'Abram, to jest Abraham.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 1, 28, 'Abrahamovi sinovi: Izak i Jišmael.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 1, 29, 'Ovo je njihovo rodoslovlje: Jišmaelov prvenac Nebajot, zatim Kedar, Adbeel, Mibsam,');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 1, 30, 'Mišma, Duma, Masa, Hadad, Tema,');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 1, 31, 'Jetur, Nafiš i Kedma. To su Jišmaelovi sinovi.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 1, 32, 'Sinovi Keture, Abrahamove inoče: ona rodi Zimrana, Jokšana, Medana, Midjana, Jišbaka i Šuaha. Sinovi Jokšanovi jesu: Šeba i Dedan.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 1, 33, 'Midjanovi su sinovi bili: Efa, Efer, Henok, Abida i Eldaa. Svi su oni bili Keturini sinovi.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 1, 34, 'Abrahamu se rodi Izak; Izakovi su sinovi bili: Ezav i Izrael.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 1, 35, 'Ezavovi su sinovi bili: Elifaz, Reuel, Jeuš, Jalam i Korah.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 1, 36, 'Elifazovi su sinovi bili: Teman, Omar, Sefi, Gatan, Kenaz, Timna i Amalek.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 1, 37, 'Reuelovi su sinovi bili: Nahat, Zerah, Šama i Miza.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 1, 38, 'Seirovi su sinovi bili: Lotan, Šobal, Sibeon, Ana, Dišon, Eser i Dišan.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 1, 39, 'Lotanovi su sinovi bili: Hori i Homam; Lotanova je sestra bila Timna.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 1, 40, 'Šobalovi su sinovi bili: Alvan, Manahat, Ebal, Šefi i Onam. Sibeonovi su sinovi bili: Aja i Ana.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 1, 41, 'Anin je sin bio Dišon, a Dišonovi su sinovi bili: Hamram, Ešban, Jitran i Keran.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 1, 42, 'Eserovi su sinovi bili: Bilhan, Zaavan i Jaakan. Dišonovi su sinovi bili Us i Aran.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 1, 43, 'Evo kraljeva koji su kraljevali u zemlji edomskoj prije nego je zavladao kralj sinova Izraelovih: Bela, sin Beorov; gradu mu je bilo ime Dinhaba.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 1, 44, 'Kad je umro Bela, na njegovo se mjesto zakraljio Jobab, sin Zareha iz Bosre.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 1, 45, 'Kad je umro Jobab, zakraljio se na njegovo mjesto Hušam iz temanske zemlje.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 1, 46, 'Kad je umro Hušam, zakraljio se na njegovo mjesto Bedadov sin Hadad, koji je potukao Midjance na Moapskom polju; gradu mu je bilo ime Avit.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 1, 47, 'Kad je umro Hadad, zakraljio se na njegovo mjesto Samla iz Masreke.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 1, 48, 'Kad je umro Samla, zakraljio se na njegovo mjesto Šaul iz Rehobota na Rijeci.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 1, 49, 'Kad umrije Šaul, zavlada Baal Hanan, Akborov sin.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 1, 50, 'Kad je umro Baal Hanan, zavladao je Hadad; gradu mu je bilo ime Pai. Žena mu se zvala Mehetabela. Bila je kći Matredova iz Me Zahaba.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 1, 51, 'Kad je umro Hadad, nastali su knezovi u Edomu: knez Timna, knez Alva, knez Jetet,');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 1, 52, 'knez Oholibama, knez Ela, knez Pinon,');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 1, 53, 'knez Kenaz, knez Teman, knez Mibsar,');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 1, 54, 'knez Magdiel i knez Iram. To su bili knezovi edomski.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 2, 1, 'Evo Izraelovih sinova: Ruben, Šimun, Levi, Juda, Jisakar i Zebulun,');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 2, 2, 'Dan, Josip i Benjamin, Naftali, Gad i Ašer.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 2, 3, 'Judini sinovi: Er, Onan i Šela. Ta mu je tri rodila Kanaanka, Šuina kći. Ali Er, Judin prvenac, bijaše nevaljao u Jahvinim očima i Jahve ga pogubi.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 2, 4, 'Njegova nevjesta Tamara rodi mu Peresa i Zeraha. U svemu je bilo pet Judinih sinova.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 2, 5, 'Peresovi su sinovi bili: Hesron i Hamul.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 2, 6, 'Zerahovi su sinovi bili: Zimri, Etan, Heman, Kalkol i Dara; u svemu pet.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 2, 7, 'Karmijevi su sinovi bili: Akar, koji je nanio zlo Izraelu prekršivši kletvu.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 2, 8, 'A sinovi Etanovi: Azarja.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 2, 9, 'Hesronovi sinovi koji mu se rodiše bijahu: Jerahmeel, Ram i Kelubaj.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 2, 10, 'Ram rodi Aminadaba, a Aminadab rodi Nahšona, kneza Judinih sinova.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 2, 11, 'Nahšon rodi Salmu, Salma rodi Boaza.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 2, 12, 'Boaz rodi Obeda, Obed rodi Jišaja.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 2, 13, 'Jišaj rodi prvenca Eliaba, drugog Abinadaba, trećeg Šimu,');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 2, 14, 'četvrtog Netanela, petog Radaja,');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 2, 15, 'šestog Osema, sedmoga Davida.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 2, 16, 'Sestre im: Sarviju i Abigajilu. Sarvijini su sinovi bili: Abišaj, Joab, Asahel, trojica.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 2, 17, 'Abigajila je rodila Amasu, Amasin je otac bio Jišmaelac Jeter.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 2, 18, 'Hesronov sin Kaleb imao je sa ženom Azubom i s Jeriotom sinove, a sinovi su mu bili: Ješer, Šobab i Ardon.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 2, 19, 'Kad je umrla Azuba, uze Kaleb za ženu Efratu i ona mu rodi Hura.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 2, 20, 'Hur rodi Urija, a Uri rodi Besalelu.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 2, 21, 'Potom Hesron uze kćer Makira, oca Gileadova; uzeo ju je za ženu kad mu je bilo šezdeset godina i ona mu rodi Seguba.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 2, 22, 'Segub rodi Jaira, koji je imao dvadeset i tri grada u gileadskoj zemlji.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 2, 23, 'Ali su Gešurci i Aramejci osvojili od njih Jairova Sela, Kenat sa selima, šezdeset gradova. To su sve osvojili sinovi Makira, oca Gileadova.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 2, 24, 'Kad je umro Hesron u Kaleb Efrati, Hesronova žena Abija rodi mu Ašhura, oca Tekoina.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 2, 25, 'Sinovi Jerahmeela, Hesronova prvenca, bili su: prvenac Ram, pa Buna, Oren, Osem i Ahija.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 2, 26, 'Jerahmeel je imao i drugu ženu, zvala se Atara, koja je bila Onamova majka.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 2, 27, 'Sinovi Rama, Jerahmeelova prvenca, bili su Maas, Jamin i Eker.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 2, 28, 'Onamovi su sinovi bili: Šamaj i Jada; Šamajevi sinovi: Nadab i Abišur.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 2, 29, 'Abišurova se žena zvala Abihajla, koja mu rodi Ahbana i Molida.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 2, 30, 'Nadabovi su sinovi bili: Seled i Afajim, ali je Seled umro bez djece.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 2, 31, 'Sinovi su Afajimovi bili: Jiši; Jišijevi sinovi: Šešan; Šešanov sin Ahlaj.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 2, 32, 'Sinovi Jade, brata Šamajeva, bili su: Jeter i Jonatan; ali je Jeter umro bez djece.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 2, 33, 'Jonatanovi su sinovi bili: Pelet i Zaza. To su bili Jerahmeelovi sinovi.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 2, 34, 'Šešan nije imao sinova, nego kćeri; ali je Šešan imao slugu Egipćanina po imenu Jarhu.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 2, 35, 'Zato je Šešan dao kćer sluzi Jarhi za ženu i ona mu rodi Ataja.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 2, 36, 'Ataj rodi Natana, Natan rodi Zabada.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 2, 37, 'Zabad rodi Eflala, Eflal rodi Obeda;');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 2, 38, 'Obed rodi Jehua, Jehu rodi Azarju,');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 2, 39, 'Azarja rodi Helesa, Heles rodi Elasu;');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 2, 40, 'Elasa rodi Sismaja, Sismaj rodi Šaluma,');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 2, 41, 'Šalum rodi Jekamju, Jekamja rodi Elišamu.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 2, 42, 'Sinovi Kaleba, Jerahmeelova brata, bili su: njegov prvenac Meša, otac Zifov; sinovi oca Mareše bili su: Hebron.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 2, 43, 'Hebronovi sinovi Korah, Tapuah, Rekem i Šema.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 2, 44, 'Šema rodi Rahama, oca Jorkoamova, a Rekem rodi Šamaja.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 2, 45, 'Šamajev je sin bio Maon, a Maon je bio otac Bet-Sarov.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 2, 46, 'Efa, Kalebova inoča, rodila je Harana, Mosu i Gazeza; Haran je rodio Gazeza.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 2, 47, 'Johdajevi su sinovi bili: Regem, Jotam, Gešan, Felet, Efa i Šaaf.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 2, 48, 'Maaka, Kalebova inoča, rodila je Šebera i Tirhanu.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 2, 49, 'Rodila je Šaafa, oca Madmanina, Ševu, oca Makbenina, i oca Gibina; a Kalebova je kći bila Aksa.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 2, 50, 'To su bili sinovi Kalebovi. A sinovi Hura, Efratina prvenca: Šobal, otac Kirjat Jearimov,');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 2, 51, 'Salma, otac Betlehemov, i Haref, otac Bet-Gaderov.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 2, 52, 'A sinovi Šobala, oca Kirjat Jearimova: Reaja, polovica Manahaćana.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 2, 53, 'Kirjatjearimske su porodice bile: Jitrani, Pućani, Šumaćani i Mišrani; od njih su potekli Soraćani i Eštaoljani.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 2, 54, 'Salmini su sinovi: Betlehem, Netofaćani, Atrot, Bet Joab i polovina Manahaćana, Saraćani.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 2, 55, 'Književničke obitelji koje su živjele u Jabesu bile su: Tiraćani, Simeaćani, Sukaćani. To su Kinejci koji su potekli od Hamata, oca Rekabova doma.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 3, 1, 'Ovo su Davidovi sinovi koji mu se rodiše u Hebronu: prvenac Amnon od Jizreelke Ahinoame, drugi Daniel od Karmelke Abigajle,');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 3, 2, 'treći Abšalom, sin Maake, kćeri Talmaja, gešurskoga kralja, četvrti Adonija, sin Hagitin,');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 3, 3, 'peti Šefatja od Abitale, šesti Jitream od njegove žene Egle.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 3, 4, 'Šest mu se sinova rodilo u Hebronu, gdje je kraljevao sedam godina i šest mjeseci; a trideset je i tri godine kraljevao u Jeruzalemu.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 3, 5, 'Ovi mu se sinovi rodiše u Jeruzalemu: Šimeja, Šobab, Natan i Salomon; četiri od Bat-Šebe, kćeri Amielove.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 3, 6, 'Jibhar, Elišama, Elifalet,');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 3, 7, 'Nogah, Nefeg, Jafija,');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 3, 8, 'Elišama, Elijada, Elifelet: devet.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 3, 9, 'Sve Davidovi sinovi osim inočkih sinova i njihove sestre Tamare.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 3, 10, 'Salomonov je sin bio Roboam, njegov sin Abija, njegov sin Asa, njegov sin Jošafat,');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 3, 11, 'njegov sin Joram, njegov sin Ahazja, njegov sin Joaš,');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 3, 12, 'njegov sin Amasja, njegov sin Azarja, njegov sin Jotam,');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 3, 13, 'njegov sin Ahaz, njegov sin Ezekija, njegov sin Manaše,');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 3, 14, 'njegov sin Amon, njegov sin Jošija.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 3, 15, 'Jošijini su sinovi bili: prvenac Johanan, drugi Jojakim, treći Sidkija, četvrti Šalum.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 3, 16, 'Jojakimovi su sinovi bili: Jekonija, njegov sin, i Sidkija, njegov sin.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 3, 17, 'Sinovi sužnja Jekonje bili su Šealtiel, njegov sin,');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 3, 18, 'Malkiram, Pedaja, Šenasar, Jekamja, Jošama i Nebadja.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 3, 19, 'Pedajini su sinovi bili: Zerubabel i Šimej; Zerubabelovi sinovi: Mešulam i Hananija, i sestra im Šelomita.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 3, 20, 'Hašuba, Ohel, Berekja, Hasadja i Jušab-Hesed, njih petorica.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 3, 21, 'Hananijini su sinovi bili: Pelatja i Jišaja, Refajini sinovi, Arnanov sin, Obadjin sin, Šekanijin sin.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 3, 22, 'Šekanijini su sinovi bili: Šemaja, a Šemajini su sinovi bili: Hatuš, Jigal, Barijah, Nearja i Šafat, šestorica.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 3, 23, 'Nearjini su sinovi bili Elijoenaj, Ezekija i Azrikam, trojica.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 3, 24, 'Elijoenajevi su sinovi bili Hodavja, Elijašib, Felaja, Akub, Johanan, Delaja i Anani, sedmorica.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 4, 1, 'Judini su sinovi bili: Peres, Hesron, Karmi, Hur i Šobal.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 4, 2, 'Šobalov sin Reaja rodi Jahata, a Jahat rodi Ahumaja i Lahada. To su soratski rodovi.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 4, 3, 'Ovo su sinovi od oca Etama: Jizreel, Jišma i Jidbaš, a njihovoj je sestri bilo ime Haslelponija.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 4, 4, 'Fenuel je bio otac Gedoru, a Ezer je bio Hušin otac. To su bili sinovi Hura, prvenca Efrate, oca Betlehema.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 4, 5, 'A otac Tekoe Ašhur imao je dvije žene, Helu i Naaru.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 4, 6, 'Naara mu je rodila Ahuzama, Hefera, Temnance i Ahaštarce. To su Naarini sinovi.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 4, 7, 'Helini su sinovi bili: Seret, Sohar i Etnan.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 4, 8, 'Kos rodi Anuba i Hasobebu i porodice Harumova sina Aharhela.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 4, 9, 'Jabes je bio izvrsniji među braćom i mati mu je nadjela ime Jabes govoreći: \"Rodila sam ga s bolom.\"');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 4, 10, 'Jabes je prizvao Izraelova Boga govoreći: \"Ako me odista blagoslivljaš, raširi moje područje, neka bude tvoja ruka uza me i sačuvaj me oda zla, tako da se ne mučim!\" Ispuni mu Bog za što ga je molio.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 4, 11, 'Šuhin brat Kelub rodi Mehira; on je bio Eštonov otac.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 4, 12, 'Od Eštona poteče Bet Rafa, Paseah i Tehina, otac Ir Nahaša. To su Rekini ljudi.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 4, 13, 'A Kenazovi su sinovi bili: Otniel i Seraja. Otnielovi sinovi: Hatat i Meonotaj.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 4, 14, 'Meonotaj rodi Ofru; Šeraja rodi Joaba, oca onih što žive u Dolini rukotvoraca, jer bijahu rukotvorci.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 4, 15, 'Sinovi Jefuneova sina Kaleba bili su: Ir, Ela i Naam; Elin je sin bio Kenaz.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 4, 16, 'Jehalelelovi su sinovi bili Zif, Zifa, Tirja i Asrael.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 4, 17, 'Ezrini sinovi: Jeter, Mered, Efer i Jalon; Jeter rodi Mirjamu, Šamaja i Jišboha, Eštemoina oca.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 4, 18, 'Njegova žena Judejka rodila je Jereda, Gedorova oca, Hebera, Sokova oca, i Jekutiela, Zanoahova oca. To su bili sinovi Bitje, faraonove kćeri koju je za ženu uzeo Mered.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 4, 19, 'Sinovi Hodijine žene, sestre Nahama, Keilina oca, bili su: Šimun, otac Jomama Garmijca, i Eštemoa Maakaćanin.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 4, 20, 'Šimunovi su sinovi bili: Amnon, Rina, Ben-Hanan i Tilon. Išijevi sinovi: Zohet i Ben-Zohet.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 4, 21, 'Sinovi Judina sina Šele bili su: Er, Lekin otac, Lada, Marešin otac, i obitelji platnarske kuće u Bet Ašbeji;');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 4, 22, 'Jokim i ljudi iz Kozebe Joaš i Saraf, koji su vladali nad Moabom i vratili se u Betlehem. Ali su to stari događaji.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 4, 23, 'To su bili lončari koji su živjeli u Netajimu i u Gederi kod kralja i bili su ondje zaposleni u njega.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 4, 24, 'Šimunovi su sinovi bili Nemuel, Jamin, Jarib, Zerah i Šaul.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 4, 25, 'Njegov je sin bio Šalum, a njegov je sin Mibsam, njegov sin Mišma.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 4, 26, 'Mišmini su sinovi bili: Hamuel, sin mu, i njegov sin Zakur i njegov sin Šimej.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 4, 27, 'Šimej je imao šesnaest sinova i šest kćeri; njegova braća nisu imala mnogo sinova, i sve njihove porodice nije bilo tako mnogo kao Judinih sinova.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 4, 28, 'Živjeli su u Beer Šebi, Moladi i Hasar Šualu,');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 4, 29, 'u Bilhi, u Esemu, u Toladu,');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 4, 30, 'u Betuelu, u Hormi, u Siklagu,');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 4, 31, 'u Bet Markabotu, u Hasar Susimu, u Bet Biriju i u Šaarajimu. To su bili njihovi gradovi do Davidova kraljevanja.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 4, 32, 'A njihova su naselja bila: Etam i Ajin, Rimon, Token i Ašan, pet gradova.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 4, 33, 'I sva njihova naselja što su bila oko tih gradova do Baala. To su bili njihovi stanovi i njihovi plemenski popisi.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 4, 34, 'Mešobad, Jamlek i Amasjin sin Joša,');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 4, 35, 'Joel i Jehu, sin Jošibje, sina Serajina, sina Asielova,');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 4, 36, 'Elijoenaj, Jaakoba, Ješohaja, Asaja, Adiel, Jesimiel i Benaja,');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 4, 37, 'Ziza, sin Šifija, sina Alonova, sina Jedajeva, sina Šimrijeva, sina Šemajina.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 4, 38, 'Ti su imenovani bili starješine svojim rodovima i njihove su se porodice veoma umnožile.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 4, 39, 'Zato su otišli do mjesta kako se ide u Gedor do istočne strane doline da traže pašu stoci.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 4, 40, 'Našli su obilatu i dobru pašu i prostranu, sigurnu i mirnu zemlju. Budući da su ondje prije živjeli Hamovi potomci,');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 4, 41, 'Šimunovci, poimence popisani, navališe za vremena judejskoga kralja Ezekije te razbiše njihove šatore i njihove zaklone koji se nađoše ondje. Baciše na njih kletvu, koja traje do današnjega dana, i nastaniše se na njihovo mjesto jer su ondje bili pašnjaci za njihovu stoku.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 4, 42, 'Onda su neki među onima što su pripadali Šimunovim sinovima, njih pet stotina, izbili na planinu Seir, na čelu s Felatjom, Nearjom, Refajom i Uzielom, Išijevim sinovima.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 4, 43, 'Oni pobiše ostatak koji se spasio između Amalečana i naseliše se ondje do današnjega dana.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 5, 1, 'Sinovi Izraelova prvenca Rubena. On je doista bio prvenac; ali kad je oskvrnuo očevu postelju, njegovo je pravo prvorodstva bilo dano sinovima Izraelova sina Josipa, ali im nije bilo upisano u rodovnik,');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 5, 2, 'jer je Juda nadvladao među braćom, a od njega se rodio knez. Ipak je pravo prvorodstva pripalo Josipu.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 5, 3, 'Sinovi Izraelova prvenca Rubena bili su Henok, Falu, Hesron i Karmi.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 5, 4, 'Joelovi sinovi: njegov sin Šemaja, njegov sin Gog, njegov sin Šimej,');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 5, 5, 'njegov sin Mika, njegov sin Reaja, njegov sin Baal,');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 5, 6, 'njegov sin Beera, koga je odveo u sužanjstvo asirski kralj Tiglat Pileser; on je bio poglavar Rubenova plemena.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 5, 7, 'Njegovoj braći, po obiteljima, kad su se zapisali u plemenski rodovnik po naraštajima, bio je poglavar Jeiel, Zaharija,');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 5, 8, 'Bela, sin Azazov, sin Šemin, sin Joelov. On je živio u Aroeru i do Neba i Baal Meona.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 5, 9, 'Prema istoku njegova se zemlja prostirala do ulaza u pustinju, od rijeke Eufrata, jer mu se stoka umnožila u gileadskoj zemlji.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 5, 10, 'Za Šaulovih vremena vojevali su s Hagrijcima koji su izginuli od njihove ruke; tako su se naselili u njihove šatore po svemu istočnom području od Gileada.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 5, 11, 'Gadovi su sinovi živjeli blizu njih u bašanskoj zemlji do Salke.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 5, 12, 'Poglavar je bio Joel, a drugi Šafan, pa Janaj i Šafat u Bašanu.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 5, 13, 'Njihova su braća po svojim rodovima bila: Mihael, Mešulam, Šeba, Joraj, Jakan, Zija, Eber, sedmorica.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 5, 14, 'To su bili sinovi Abihajila, sina Hurija, sina Jaroaha, sina Gileada, sina Mihaela, sina Ješišaja, sina Jahdona, sina Buza.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 5, 15, 'Ahi, sin Abdiela, Gunijeva sina, bio je poglavar njihova roda.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 5, 16, 'Živjeli su u Gileadu i u njihovim zaseocima te po svim šaronskim pašnjacima do njihovih krajeva.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 5, 17, 'Svi su bili zapisani u plemenski rodovnik za vremena judejskoga kralja Jotama i za vremena izraelskoga kralja Jeroboama.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 5, 18, 'Rubenovih i Gadovih sinova, i polovine Manašeova plemena, hrabrih junaka koji su nosili štit i mač te zapinjali luk i bili vješti boju, bijaše četrdeset tisuća sedam stotina i šezdeset vojnika.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 5, 19, 'Ratovali su protiv Hagrijaca, Iturejaca, Nafišejaca i Nodabejaca.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 5, 20, 'U boju su zavapili k Bogu i on ih je uslišao jer su se pouzdali u nj: potpomognuti su protiv neprijatelja te su im predani u ruke Hagrijci sa svim njihovim saveznicima.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 5, 21, 'Zaplijenili su njihovu stoku - pedeset tisuća deva, dvije stotine i pedeset tisuća ovaca i koza i dvije tisuće magaraca - i odveli u ropstvo sto tisuća ljudi.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 5, 22, 'Pobijenih je mnogo palo, jer je taj boj bio od Boga; onda se naseliše na njihovo mjesto do sužanjstva.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 5, 23, 'Sinovi polovine Manašeova plemena nastanili su se u toj zemlji od Bašana do Baal Hermona i Šenira i do Hermonske gore. I bijahu se umnožili.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 5, 24, 'Ovo su bili poglavari njihovih rodova: Efer, Jiši, Eliel, Azriel, Jeremija, Hodavja i Jahdiel, hrabri junaci i ugledni muževi: poglavari u svojim rodovima.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 5, 25, 'Ali kad su se iznevjerili Bogu svojih otaca i odali se preljubu s bogovima naroda one zemlje koje je Bog iskorijenio pred njima,');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 5, 26, 'probudio je Izraelov Bog neprijateljstvo asirskoga kralja Pula i neprijateljstvo asirskoga kralja Tiglat Pilesera. Oni su odveli u sužanjstvo Rubenovo i Gadovo pleme i polovinu Manašeova plemena. Doveli su ih u Helah, Habor i Haru i na Gozansku rijeku do današnjega dana.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 5, 27, 'Levijevi su sinovi bili Geršom, Kehat i Merari.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 5, 28, 'Kehatovi sinovi: Amram, Jishar, Hebron i Uziel.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 5, 29, 'Amramovi sinovi: Aron, Mojsije i Mirjama. Aronovi sinovi: Nabad i Abihu, Eleazar i Itamar.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 5, 30, 'Eleazar rodi Pinhasa, Pinhas rodi Abišuu;');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 5, 31, 'Abišua rodi Bukija, Buki rodi Uziju;');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 5, 32, 'Uzija rodi Zerahju; Zerahja rodi Merajota.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 5, 33, 'Merajot rodi Amarju; Amarja rodi Ahituba;');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 5, 34, 'Ahitub rodi Sadoka; Sadok rodi Ahimaasa;');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 5, 35, 'Ahimaas rodi Azarju, Azarja rodi Johanana;');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 5, 36, 'Johanan rodi Azarju, koji je bio svećenik u Hramu što ga je sagradio Salomon u Jeruzalemu.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 5, 37, 'Azarja rodi Amarju; Amarja rodi Ahituba;');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 5, 38, 'Ahitub rodi Sadoka, Sadok rodi Šaluma;');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 5, 39, 'Šalum rodi Hilkiju, Hilkija rodi Azarju;');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 5, 40, 'Azarja rodi Seraju; Seraja rodi Josadaka.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 5, 41, 'Josadak je otišao kad je Jahve odveo u sužanjstvo Judu i Jeruzalem Nabukodonozorovom rukom.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 6, 1, 'Levijevi su sinovi bili Geršom, Kehat i Merari.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 6, 2, 'Evo imena Geršomovih sinova: Libni i Šimej.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 6, 3, 'Kehatovi su sinovi bili: Amram, Jishar, Hebron i Uziel.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 6, 4, 'Merarijevi sinovi: Mahli i Muši. Ovo su rodovi Levijevaca po svojim ocima.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 6, 5, 'Od Geršoma: sin mu Libni, njegov sin Jahat, njegov sin Zima,');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 6, 6, 'njegov sin Joah, njegov sin Ido, njegov sin Zerah, njegov sin Jeatraj.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 6, 7, 'Kehatovi sinovi: sin mu Aminadab, njegov sin Korah, njegov sin Asir,');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 6, 8, 'njegov sin Elkana, njegov sin Ebjasaf, njegov sin Asir;');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 6, 9, 'njegov sin Tahat, njegov sin Uriel, njegov sin Uzija, njegov sin Šaul.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 6, 10, 'Elkanini sinovi: Amasaj i Ahimot;');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 6, 11, 'njegov sin Elkana, njegov sin Sufaj, njegov sin Nahat;');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 6, 12, 'njegov sin Eliab, njegov sin Jeroham, njegov sin Elkana. Elkanini sinovi:');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 6, 13, 'Samuel, njegov prvenac, drugi Abija.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 6, 14, 'Merarijevi sinovi: Mahli, njegov sin Libni, njegov sin Šimej, njegov sin Uza,');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 6, 15, 'njegov sin Šima, njegov sin Hagija, njegov sin Asaja.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 6, 16, 'Ovo su oni koje je postavio David da se brinu za pjevanje u Domu Jahvinu kad je Kovčeg ondje našao svoje počivalište;');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 6, 17, 'oni koji su služili pred Prebivalištem, Šatorom sastanka, pjevajući, dok nije Salomon sagradio Dom Jahvin u Jeruzalemu i koji su obavljali službu po propisanom redoslijedu.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 6, 18, 'Evo onih što su obavljali službu i njihovih sinova: od Kehatovih sinova: pjevač Heman, sin Joela, sina Samuela,');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 6, 19, 'sina Elkane, sina Jerohama, sina Eliela, sina Toaha,');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 6, 20, 'sina Sifa, sina Elkane, sina Mahata, sina Amasaja,');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 6, 21, 'sina Elkane, sina Joela, sina Azarje, sina Sefanije,');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 6, 22, 'sina Tahata, sina Asira, sina Abjasafa, sina Koraha,');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 6, 23, 'sina Jishara, sina Kehata, sina Levija, sina Izraelova.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 6, 24, 'Brat mu Asaf stajao je s desne strane; Asaf je bio sin Berekje, sina Šime,');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 6, 25, 'sina Mihaela, sina Baaseja, sina Malkije,');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 6, 26, 'sina Etnija, sina Zeraha, sina Adaje,');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 6, 27, 'sina Etana, sina Zime, sina Šimeja,');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 6, 28, 'sina Jahata, sina Geršoma, sina Levijeva.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 6, 29, 'Merarijevi sinovi, njihova braća, stajala su mu s lijeve strane: Etan, sin Kušija, sina Abdija, sina Maluka,');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 6, 30, 'sina Hašabje, sina Amasje, sina Hilkije,');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 6, 31, 'sina Amsija, sina Banija, sina Šomera,');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 6, 32, 'sina Mahlija, sina Mušija, sina Merarija, sina Levijeva.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 6, 33, 'Njihova braća leviti bili su postavljeni za svu službu u svetom Prebivalištu, u Domu Božjem.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 6, 34, 'Aron i njegovi sinovi prinosili su kad na žrtveniku za paljenice i na kadionom žrtveniku, obavljajući sav posao u Svetinji nad svetinjama i izvršujući obred pomirenja nad Izraelom, prema svemu što je zapovjedio Božji sluga Mojsije.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 6, 35, 'Ovo su Aronovi sinovi: sin mu Eleazar, njegov sin Pinhas, njegov sin Abišua,');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 6, 36, 'njegov sin Buki, njegov sin Uzi, njegov sin Zerahja,');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 6, 37, 'njegov sin Merajot, njegov sin Amarja, njegov sin Ahitub,');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 6, 38, 'njegov sin Sadok, njegov sin Ahimaas.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 6, 39, 'Ovo su im boravišta po naseljima u njihovu području: Aronovim sinovima od Kehatove obitelji - jer na njih je pao ždrijeb -');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 6, 40, 'dali su Hebron u judejskoj zemlji s pašnjacima oko njega.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 6, 41, 'Gradsko polje i njegova sela dali su Jefuneovu sinu Kalebu.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 6, 42, 'Dali su, dakle, Aronovim sinovima gradove-utočišta Hebron i Libnu s pašnjacima, Jatir i Eštemou s pašnjacima,');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 6, 43, 'Hilez s pašnjacima, Debir s pašnjacima,');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 6, 44, 'Ašan s pašnjacima i Bet Šemeš s pašnjacima.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 6, 45, 'Od Benjaminova plemena: Gebu s pašnjacima, Alemet s pašnjacima i Anatot s pašnjacima; dakle trinaest gradova po njihovim rodovima.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 6, 46, 'Ostalim Kehatovim sinovima prema plemenskim rodovima pripalo je ždrijebom deset gradova od polovine Manašeova plemena.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 6, 47, 'Geršomovim sinovima po njihovim rodovima pripalo je od Jisakarova plemena, od Ašerova plemena, od Naftalijeva plemena i od Manašeova plemena u Bašanu trinaest gradova.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 6, 48, 'Merarijevim sinovima po njihovim rodovima pripalo je ždrijebom od Rubenova plemena, od Gadova plemena i od Zebulunova plemena dvanaest gradova.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 6, 49, 'Tako su Izraelovi sinovi dali levitima te gradove s pašnjacima.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 6, 50, 'Dali su ždrijebom od plemena Judinih sinova, od plemena Šimunovih sinova i od plemena Benjaminovih sinova te gradove koje su spomenuli poimence.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 6, 51, 'Onima koji su bili od rodova Kehatovih sinova te dobili ždrijebom gradove od Efrajimova plemena');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 6, 52, 'dali su kao gradove-utočišta Šekem s pašnjacima u Efrajimovoj gori i Gezer s pašnjacima,');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 6, 53, 'Jokmeam s pašnjacima, Bet Horon s pašnjacima,');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 6, 54, 'Ajalon s pašnjacima i Gat-Rimon s pašnjacima.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 6, 55, 'Od polovine Manašeova plemena dali su rodovima ostalih Kehatovih sinova: Aner s pašnjacima i Bileam s pašnjacima.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 6, 56, 'Geršomovim sinovima dali su od rodova polovine Manašeova plemena Golan u Bašanu s pašnjacima i Aštarot s pašnjacima.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 6, 57, 'Od Jisakarova plemena Kedeš s pašnjacima, Dobrat s pašnjacima,');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 6, 58, 'Ramot s pašnjacima i Anem s pašnjacima.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 6, 59, 'Od Ašerova plemena Mašal s pašnjacima, Abdon s pašnjacima,');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 6, 60, 'Hukok s pašnjacima i Rehob s pašnjacima.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 6, 61, 'Od Naftalijeva plemena Kedeš u Galileji s pašnjacima, Hamon s pašnjacima i Kirjatajim s pašnjacima.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 6, 62, 'Ostalim Merarijevim sinovima dali su od Zebulunova plemena Rimon s pašnjacima i Tabor s pašnjacima.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 6, 63, 'S onu stranu Jordana, prema Jerihonu, na istočnoj strani Jordana, dali su im od Rubenova plemena Beser u pustinji s pašnjacima, Jahsu s pašnjacima,');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 6, 64, 'Kedemot s pašnjacima i Mefaat s pašnjacima.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 6, 65, 'Od Gadova plemena Ramot u Gileadu s pašnjacima, Mahanajim s pašnjacima,');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 6, 66, 'Hešbon s pašnjacima i Jazer s pašnjacima.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 7, 1, 'Jisakarovi su sinovi bili Tola i Fua, Jašub i Šimron, njih četvorica.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 7, 2, 'Tolini sinovi: Uzi, Refaja, Jeriel, Jahmaj, Jibsam i Samuel, glavari obitelji od Tole, hrabri junaci svrstani po srodstvu; bilo ih je na broju za Davidova vremena dvadeset i dvije tisuće i šest stotina.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 7, 3, 'Uzijevi sinovi: Jizrahja; Jizrahjini sinovi: Mihael, Obadja, Joel i Jišija, u svemu pet glavara.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 7, 4, 'S njima je po obiteljima srodnih bilo u vojnim četama za rat trideset i šest tisuća ljudi, jer su imali mnogo žena i sinova.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 7, 5, 'Njihove braće po svim Jisakarovim rodovima, hrabrih junaka, bilo je svega osamdeset i sedam tisuća i svi su bili popisani u plemenskim rodovnicima.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 7, 6, 'Benjaminovi sinovi: Bela, Beker i Jediael, njih trojica.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 7, 7, 'Belini sinovi: Esbon, Uzi, Uziel, Jerimot i Iri, pet obiteljskih glavara, hrabrih junaka; u plemenskom popisu bilo je zapisanih dvadeset dvije tisuće i trideset četiri.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 7, 8, 'Bekerovi sinovi: Zimra, Joaš, Eliezer, Elijoenaj, Omri, Jerimot, Abija, Anatot i Alamet, svi Bekerovi sinovi.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 7, 9, 'U plemenskom popisu po koljenima, po obiteljskim glavarima, hrabrih junaka, bilo je zapisano dvadeset tisuća i dvije stotine.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 7, 10, 'Jediaelovi sinovi: Bilhan, Bilhanovi sinovi: Jeuš, Benjamin, Ahud, Kenaana, Zetan, Taršiš i Ahišahar.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 7, 11, 'Svih Jediaelovih sinova po obiteljskim glavarima, hrabrih junaka, bilo je sedamnaest tisuća i dvije stotine, sve za rat sposobnih.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 7, 12, 'Šupim i Hupim. Sinovi Irovi: Hušim; njegov sin Aher.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 7, 13, 'Naftalijevi sinovi: Jahasiel, Guni, Jeser i Šalum. Bilhini sinovi.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 7, 14, 'Manašeovi sinovi: Asriel, koga je rodila Manašeova inoča Aramejka; ona je rodila i Makira, Gileadova oca.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 7, 15, 'Makir je oženio Hupima i Šupima; sestra mu se zvala Maaka; ime drugome bilo je Selofhad, a Selofhad je imao kćeri.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 7, 16, 'Makirova žena Maaka rodila je sina, komu je nadjela ime Pereš. Bratu mu je dala ime Šareš, a njegovi su sinovi bili Ulam i Rakem.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 7, 17, 'Ulamovi sinovi: Bedan. To su sinovi Gileada, sina Makira, Manašeova sina.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 7, 18, 'Njegova sestra Hamoleketa rodila je Išhoda, Abiezera i Mahlu.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 7, 19, 'Šemidini su sinovi bili: Ahjan, Šekem, Likhi i Aniam.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 7, 20, 'Efrajimovi sinovi: Šutelah, njegov sin Bered, njegov sin Tahat, njegov sin Elada, njegov sin Tahat,');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 7, 21, 'njegov sin Zabad, njegov sin Šutelah, Ezer i Elad. Njih su ubili gatski građani, rođeni u zemlji, jer su sišli da im otmu stoku.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 7, 22, 'Zato je njihov otac Efrajim tugovao dugo vremena, a braća su mu odlazila da ga tješe.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 7, 23, 'Onda je ušao k svojoj ženi i ona je zatrudnjela i rodila sina, a on mu nadjenu ime Berija, jer se nesreća dogodila u njegovoj kući.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 7, 24, 'Kći mu je bila Šeera, koja je sagradila Donji i Gornji Bet Horon i Uzen Šeeru.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 7, 25, 'Sin mu je bio Refah i Rešef, njegov sin Telah, njegov sin Tahan,');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 7, 26, 'njegov sin Ladan, njegov sin Amihud, njegov sin Elišama,');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 7, 27, 'njegov sin Nun, njegov sin Jošua.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 7, 28, 'Njihov posjed i njihova naselja bili su Betel i njegova sela, s istoka Naaran, sa zapada Gazer i njegova sela, Šekem i njegova sela do Gaze s njezinim selima.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 7, 29, 'U rukama Manašeovih sinova bio je Bet Šean sa svojim selima, Tanak sa svojim selima, Megido sa svojim selima, Dor sa svojim selima. U njima su živjeli sinovi Izraelova sina Josipa.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 7, 30, 'Ašerovi su sinovi bili: Jimna, Jišva, Jišvi i Berija, i njihova sestra Seraha.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 7, 31, 'Berijini sinovi: Heber i Malkiel; on je bio Birzajitov otac.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 7, 32, 'Heber postade otac Jafletu, Šomeru, Hotamu i njihovoj sestri Šui.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 7, 33, 'Jafletovi su sinovi bili: Pasak, Bimhal i Ašvat; to su bili Jafletovi sinovi.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 7, 34, 'A sinovi njegova brata Šomera: Rohga, Huba i Aram.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 7, 35, 'Sinovi njegova brata Helema: Sofah, Jimna, Šeleš i Amal.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 7, 36, 'Sofahovi sinovi: Suah, Harnefer, Šual, Beri, Jimra,');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 7, 37, 'Beser, Hod, Šama, Šilša, Jitran i Bera.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 7, 38, 'Jeterovi sinovi: Jefune, Fispa i Ara.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 7, 39, 'Ulini sinovi: Arah, Haniel i Risja.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 7, 40, 'Svi su oni bili Ašerovi sinovi, obiteljski glavari, probrani hrabri junaci, glavari među knezovima; kad su bili popisani, bilo ih je dvadeset i šest tisuća ljudi u bojnim četama.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 8, 1, 'Benjamin rodi prvenca Belu, drugog Ašbela, trećeg Ahraba,');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 8, 2, 'četvrtog Nohu i petog Rafu.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 8, 3, 'Belini su sinovi bili: Adar, Gera, Ehudov otac,');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 8, 4, 'Abišua, Naaman, Ahoah,');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 8, 5, 'Gera, Šefufan i Huram.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 8, 6, 'Oni su bili Ehudovi sinovi i bili su obiteljski glavari onima koji su živjeli u Gebi, odakle su ih odveli u sužanjstvo u Manahat;');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 8, 7, 'Naaman, Ahija i Gera; on ih je vodio u sužanjstvo i rodio Uzu i Ahihuda.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 8, 8, 'Šaharajim, pošto je otpustio žene Hušimu i Baru, dobio je sinove u Moapskom polju:');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 8, 9, 'sa svojom ženom Hodešom imao je sinove Jobaba, Sibju, Mešu, Malkama,');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 8, 10, 'Jeusa, Sakju i Mirmu; to su bili njegovi sinovi, obiteljski glavari.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 8, 11, 'S Hušimom je rodio Abituba i Elpaala.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 8, 12, 'Elpaalovi su sinovi bili: Eber, Mišam i Šamed; on je sagradio Ono i Lod s njihovim selima.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 8, 13, 'Zatim Berija i Šema. Oni su bili obiteljski glavari onima koji su živjeli u Ajalonu i istjerali su gatske stanovnike.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 8, 14, 'Njegov brat: Šešak. Jeremot,');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 8, 15, 'Zabadja, Arad i Eder,');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 8, 16, 'Mihael, Jišpa i Joha bili su Berijini sinovi.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 8, 17, 'Zebadja, Mešulam, Hizki, Haber,');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 8, 18, 'Jišmeraj, Jizlia i Jobab bili su Elpaalovi sinovi.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 8, 19, 'Jakim, Zikri, Zabdi,');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 8, 20, 'Elijoenaj, Siltaj, Eliel,');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 8, 21, 'Adaja, Beraja i Šimrat bili su Šimijevi sinovi.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 8, 22, 'Jišpan, Eber, Eliel,');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 8, 23, 'Abdon, Zikri, Hanan,');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 8, 24, 'Hananija, Elam, Antotija,');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 8, 25, 'Jifdeja, Fenuel bili su Šešakovi sinovi.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 8, 26, 'Šamšeraj, Šeharja, Atalija,');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 8, 27, 'Jaarešja, Elija i Zikri bili su Jerohamovi sinovi.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 8, 28, 'To su bili glavari obitelji svrstanih po koljenima. Živjeli su u Jeruzalemu.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 8, 29, 'U Gibeonu su živjeli: praotac Gibeon, čija se žena zvala Maaka.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 8, 30, 'Njegov je sin prvenac bio Abdon, pa Sur, Kiš, Baal, Nadab,');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 8, 31, 'Gedor, Ahjo, Zaker,');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 8, 32, 'i Miklot, koji je rodio Šimu; pa su i oni živjeli kod svoje braće u Jeruzalemu, sa svojom braćom.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 8, 33, 'Ner rodi Kiša, a Kiš rodi Šaula, Šaul rodi Jonatana, Malki-Šua, Abinadaba, Ešbaala,');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 8, 34, 'Jonatanov je sin bio Merib Baal; Merib Baal rodi Miku.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 8, 35, 'Mikini su sinovi bili: Piton, Melek, Tarea i Ahaz.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 8, 36, 'Ahaz rodi Joadu; Joada rodi Alemeta, Azmaveta i Zimrija; Zimri rodi Mosu.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 8, 37, 'Mosa rodi Biniju, čiji je sin bio Rafa, a njegov sin Elasa, njegov sin Asel.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 8, 38, 'Asel je imao šest sinova, kojima su imena: Azrikam, njegov prvenac, Bokru, Jišmael, Šearja, Obadja i Hanan; svi su oni bili Aselovi sinovi.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 8, 39, 'Sinovi njegova brata Ešeka bili su: Ulam, prvenac mu, drugi Jehuš, treći Elifelet.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 8, 40, 'Ulamovi su sinovi bili hrabri junaci koji su zapinjali luk i imali mnogo sinova i unuka, sto pedeset. Svi su oni bili od Benjaminovih sinova.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 9, 1, 'Svi su Izraelci bili upisani u plemenskim rodovnicima, a zapisani su i u Knjizi izraelskih kraljeva. A Judejci su zbog nevjere bili odvedeni u sužanjstvo u Babilon.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 9, 2, 'Prvi su stanovnici na svojem posjedu i u svojim gradovima bili Izraelci, svećenici, leviti i netinci.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 9, 3, 'U Jeruzalemu su živjeli ljudi od Judinih sinova, od Benjaminovih sinova, od Efrajimovih i Manašeovih sinova, i to:');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 9, 4, 'Utaj, sin Amihuda, sina Omrija, sina Imrija, sina Banija, od sinova Judina sina Peresa.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 9, 5, 'Od Šilonaca: Asaja, prvenac, sa svojim sinovima.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 9, 6, 'Od Zarehovih sinova: Jeuel i njegova braća, šest stotina i devedeset.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 9, 7, 'Od Benjaminovih sinova Salu, sin Mešulama, sina Hodavje, Hasenuina sina;');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 9, 8, 'Ibneja, Jerohamov sin, i Ela, sin Uzije, Mokrijeva sina, i Mešulam, sin Šefatje, sina Reuela, Ibnijina sina.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 9, 9, 'Imali su po svojim rodovima devet stotina pedeset i šestero braće. Svi su oni bili glavari, svaki svoga roda.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 9, 10, 'Od svećenika: Jedaja, Jojarib i Jakin,');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 9, 11, 'Azarja, sin Hilkije, sina Mešulama, sina Sadoka, sina Merajota, Ahitubova sina, predstojnik Doma Božjeg.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 9, 12, 'Adaja, sin Jerohama, sina Pašhura, Malkijina sina, Masaj, sin Adiela, sina Jahzere, sina Mešulama, sina Mešilemita, Imerova sina.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 9, 13, 'Njihove braće, glava obitelji, boraca što su obavljali službu u Domu Božjem, bilo je tisuću sedam stotina i šezdeset.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 9, 14, 'Od levita Šemaja, sin Hašuba, sin Azrikama, Hašabjina sina, između Merarijevih sinova;');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 9, 15, 'Bakbakar, Hereš, Galal i Matanija, sin Mike, sina Zikrija, Asafova sina;');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 9, 16, 'Obadja, sin Šemaje, sina Galala, Jedutunova sina, i Berekja, sin Ase, Elkanina sina, koji je živio u Netofatskim selima.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 9, 17, 'Vratari: Šalum, Akub, Talmon i Ahiman, i njihova braća; Šalum je bio poglavar,');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 9, 18, 'i dosad je bio na kraljevskim vratima prema istoku. Oni su bili vratari po četama levita.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 9, 19, 'Šalum, sin Korea, sina Abjasafa, Korahova sina, sa svojom braćom Korahovcima iz njihove obitelji, bili su odgovorni za bogoslužje; oni su čuvali pragove Šatora, dok su njihovi oci čuvali ulaz u Jahvin tabor.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 9, 20, 'Eleazarov sin Pinhas bio je predstojnik nad njima nekada (Jahve bio s njim!).');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 9, 21, 'Mešelemjin sin Zaharija bio je vratar na vratima Šatora sastanka.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 9, 22, 'Svih izabranih vratara pragova bilo je dvjesta i dvanaest. Bili su upisani u rodovnike u svojim selima. Postavili su ih u službu David i vidjelac Samuel zbog njihove vjernosti.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 9, 23, 'Oni i njihovi sinovi čuvali su stražu na vratima Doma Jahvina, Doma Šatora.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 9, 24, 'Vratari su stajali na četiri strane: na istoku, na zapadu, na sjeveru i na jugu.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 9, 25, 'Njihova braća po selima dolazila su od vremena do vremena da im se pridruže po sedam dana.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 9, 26, 'Samo su četiri vratarska predstojnika bila neprestano u službi. Bili su leviti, postavljeni nad sobama i nad riznicama Božjega Doma.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 9, 27, 'Noćivali su oko Božjega Doma jer im je bila dužnost da stražare i da otključavaju svako jutro.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 9, 28, 'Neki su od njih bili odgovorni za bogoslužno posuđe. Prebrojavali su ga kad bi ga unosili i kad bi ga iznosili.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 9, 29, 'Neki su se od njih brinuli za pokućstvo, sve posvećene stvari, fino brašno, vino, ulje, tamjan i miomirise;');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 9, 30, 'a neki od svećeničkih sinova miješali su pomast od miomirisa.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 9, 31, 'Matitja, jedan od levita, prvenac Šaluma Korahovca, brinuo se za stvari koje se peku na tavi.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 9, 32, 'Neki od Kehatovaca, njihove braće, bili su odgovorni za kruhove što se postavljaju svake subote.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 9, 33, 'Oni su bili i pjevači, glavari levitskih obitelji. Kad su bili slobodni, živjeli su u hramskih sobama, jer su dan i noć bili na dužnosti.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 9, 34, 'To su bili glavari levitskih obitelji prema svom srodstvu. Ti su poglavari živjeli u Jeruzalemu.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 9, 35, 'U Gibeonu su živjeli: Gibeonov otac Jeiel, čijoj je ženi bilo ime Maaka.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 9, 36, 'Sin mu je prvenac bio Abdon, pa Sur, Kiš, Baal, Ner, Nadab,');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 9, 37, 'Gedor, Ahjo, Zaharija i Miklot.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 9, 38, 'Miklot rodi Šimeama. I oni su živjeli u Jeruzalemu, naprama svojoj braći.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 9, 39, 'Ner rodi Kiša; a Kiš rodi Šaula; Šaul rodi Jonatana, Malki-Šuu, Abinadaba i Ešbaala.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 9, 40, 'Jonatanov je sin bio Merib Baal. Merib Baal rodi Miku.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 9, 41, 'Mikini su sinovi bili: Piton, Melek, Tahrea i Ahaz.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 9, 42, 'Ahaz rodi Jaru; Jara rodi Alemeta, Azmaveta i Zimrija; Zimri rodi Mosu.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 9, 43, 'Mosa rodi Binu; njegov je sin bio Rafaja, njegov sin Elasa, njegov sin Asel.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 9, 44, 'Asel je imao šest sinova, kojima su imena: Azrikam, Bokru, Jišmael, Šearja, Obadja i Hanan; to su Aselovi sinovi.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 10, 1, 'Filistejci su zavojštili na Izraelce. Izraelci su pobjegli pred njima i padali pobijeni po gori Gilboi.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 10, 2, 'Filistejci stisnuše Šaula i njegove sinove i pogubiše Šaulove sinove Jonatana, Abinadaba i Malki-Šuu.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 10, 3, 'Boj je postao žešći oko Šaula. Iznenadiše ga strijelci s lukovima i on pade ranjen od strijelaca.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 10, 4, 'Tada Šaul reče svome štitonoši: \"Izvuci svoj mač i probodi me da ne dođu ti neobrezanci i ne narugaju mi se.\" Ali se njegov štitonoša prestravi i ne htjede toga učiniti. Zato Šaul uze mač i baci se na nj.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 10, 5, 'Kad je štitonoša vidio da je Šaul umro, baci se i on na svoj mač i umrije s njim.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 10, 6, 'Tako onog dana pogiboše zajedno Šaul, njegova tri sina i sav njegov dom.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 10, 7, 'Kad su svi Izraelci koji su bili u dolini vidjeli da su sinovi Izraelovi pobjegli i da je poginuo Šaul sa sinovima, ostavili su svoje gradove i razbježali se. Filistejci dođoše i nastaniše se u njima.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 10, 8, 'Kad su sutradan došli Filistejci da oplijene pobijene, našli su Šaula s njegovim sinovima gdje leže mrtvi na gori Gilboi.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 10, 9, 'Svukavši ga, uzeše mu glavu i oružje te poslaše po filistejskoj zemlji unaokolo javljajući veselu vijest svojim idolima i narodu.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 10, 10, 'Potom su oružje metnuli u hram svoga boga, a lubanju mu izložili u Dagonovu hramu.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 10, 11, 'Kad su čuli svi Jabeš-Gileađani što su Filistejci učinili od Šaula,');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 10, 12, 'ustali su svi hrabri ljudi i uzeli Šaulovo mrtvo tijelo i tjelesa njegovih sinova i, donijevši ih u Jabeš, pokopali su njihove kosti pod tamarisom u Jabešu; i postiše sedam dana.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 10, 13, 'Tako je poginuo Šaul za svoju nevjeru kojom se iznevjerio Jahvi: nije držao Jahvine zapovijedi i povrh toga je pitao za savjet bajačicu,');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 10, 14, 'a nije pitao Jahvu; zato ga je ubio i prenio kraljevstvo na Jišajeva sina Davida.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 11, 1, 'Tada se sabraše svi Izraelci k Davidu u Hebron i rekoše: \"Evo, mi smo od tvoje kosti i tvojeg mesa.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 11, 2, 'Još prije, dok je Šaul bio kralj, ti si upravljao svim pokretima Izraela; Jahve, tvoj Bog, rekao ti je: \'Ti ćeš pasti moj izraelski narod i ti ćeš biti knez nad mojim narodom Izraelom.\'\"');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 11, 3, 'Tako dođoše sve izraelske starješine kralju u Hebron, a kralj David s njima sklopi savez u Hebronu pred Jahvom i pomazaše Davida za kralja nad Izraelom, kako bijaše Jahve rekao Samuelu.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 11, 4, 'Onda je otišao David sa svim Izraelom na Jeruzalem, a to je Jebus, jer su ondje bili Jebusejci i živjeli su u onoj zemlji.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 11, 5, 'Ali su Jebusejci poručili Davidu: \"Nećeš ući ovamo!\" Ipak David osvoji Sionsku tvrđavu, to jest Davidov grad.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 11, 6, 'Jer je David rekao: \"Tko prvi porazi Jebusejce, bit će vrhovni vojvoda i knez.\" Prvi se popeo Sarvijin sin Joab i postao vojvoda.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 11, 7, 'Tada se David nastanio u toj tvrđavi; zato su je prozvali Davidovim gradom.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 11, 8, 'Sazidao je tada grad unaokolo, od Milona do ograde, a Joab je obnovio ostali dio grada.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 11, 9, 'David je postajao sve silniji, jer je Jahve nad vojskama bio s njim.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 11, 10, 'Evo vojvoda Davidovim junacima koji su junački radili uza nj za njegovo kraljevstvo sa svim Izraelom da ga po Jahvinoj riječi zakralje nad Izraelom.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 11, 11, 'Evo popisa Davidovih junaka: Hakmonijev sin Jašobam, glavar nad tridesetoricom; on je mahnuo svojim kopljem na tri stotine i pobio ih odjednom.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 11, 12, 'Za njim Dodonov sin Eleazar, Ahošanin, jedan između tri junaka.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 11, 13, 'On je bio s Davidom u Pas Damimu, kad su se Filistejci skupili na boj, a ondje je bilo polje puno ječma; kad je narod počeo bježati ispred Filistejaca,');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 11, 14, 'oni su stali usred toga polja i obranili ga pobivši Filistejce. Tako im Jahve dade veliku pobjedu.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 11, 15, 'Trojica su između tridesetorice jednom sišla do hridi k Davidu u Adulamsku pećinu kad su filistejske čete stajale u taboru u Refaimskoj dolini.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 11, 16, 'David je tada bio u svojoj kuli, a filistejska je posada tada bila u Betlehemu.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 11, 17, 'David uzdahnu: \"O kad bi me tko napojio vodom iz betlehemskoga studenca što je kod vrata!\"');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 11, 18, 'Tada ta trojica prodriješe kroz filistejski tabor i, zahvativši vode iz betlehemskoga studenca što je kod vrata, donesoše je i dadoše Davidu. Ali je David ne htjede piti nego je proli kao ljevanicu Jahvi');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 11, 19, 'govoreći: \"Ne dao mi moj Bog da to učinim! Zar da pijem krv ovih ljudi? TÓa izlažući život pogibli donijeli su vode.\" I nije htio piti. To su, eto, učinila ta tri junaka.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 11, 20, 'Abišaj, Joabov brat, bio je vojvoda nad tridesetoricom; on je vitlao kopljem na tri stotine, pobio ih i proslavio se među tridesetoricom.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 11, 21, 'Bio je među trojicom ugledniji od druge dvojice i bio im vojvoda, ali prve trojice nije dostigao.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 11, 22, 'Jojadin sin Benaja, junak iz Kabseela, bogat junačkim djelima, ubio je dva sina Ariela iz Moaba; on je jednoga snježnog dana sišao i ubio lava usred jame.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 11, 23, 'Ubio je i nekog Egipćanina, čovjeka od pet lakata. Egipćanin je imao u ruci koplje kao tkalačko vratilo, a on je izišao preda nj sa štapom i, istrgavši Egipćaninu koplje iz ruke, ubio ga njegovim kopljem.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 11, 24, 'To je učinio Jojadin sin Benaja i proslavio se imenom među ona tri junaka.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 11, 25, 'Bio je najznamenitiji među tridesetoricom, ali one prve trojice nije dostigao. David ga postavi za zapovjednika svoje tjelesne straže.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 11, 26, 'Hrabri su junaci bili: Joabov brat Asahel, Dodonov sin Elhanan iz Betlehema,');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 11, 27, 'Haroranin Šamot, Pelonjanin Heles;');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 11, 28, 'Akešov sin Ira, Tekoanin, Abiezer Anatoćanin;');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 11, 29, 'Sibkaj Hušaćanin, Ilaj Ahošanin;');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 11, 30, 'Mahraj Netofaćanin, Baanin sin Heled, Netofaćanin;');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 11, 31, 'Ribajev sin Itaj iz Gibeata sinova Benjaminovih, Benaja Piratonjanin;');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 11, 32, 'Huraj iz Gaaških potoka, Abiel Arbaćanin;');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 11, 33, 'Azmavet Bahurimljanin, Eljahba Šaalbonjanin.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 11, 34, 'Sinovi Hašema Gizonjanina: Sagejin sin Jonatan, Hararanin;');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 11, 35, 'Sakarov sin Ahiam, Hararanin, Urov sin Elipal;');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 11, 36, 'Hefer Mekeranin, Ahija Pelonjanin;');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 11, 37, 'Hesro Karmelac, Ezbajev sin Naaraj;');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 11, 38, 'Natanov brat Joel, Hagrijev sin Mibhar;');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 11, 39, 'Amonac Selek, Beroćanin Nahraj, štitonoša Sarvijina sina Joaba;');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 11, 40, 'Ira Jitranin, Gareb Jitranin;');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 11, 41, 'Urija Hetit, Ahlajev sin Zabad;');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 11, 42, 'Šizin sin Adina, Rubenovac, vojvoda Rubenova plemena, i s njime tridesetorica.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 11, 43, 'Maakin sin Hanan i Jošafat Mitnjanin.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 11, 44, 'Uzija Aštaroćanin, Šama i Jeiel, sinovi Aroerca Hotama;');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 11, 45, 'Šimrijev sin Jediael i njegov brat Joha Tišanin.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 11, 46, 'Mahavac Eliel i Elnaamovi sinovi Jeribaj i Jošavja i Moabac Jitma;');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 11, 47, 'Eliel i Obed i Mesobajanin Jaasiel.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 12, 1, 'Evo onih što dođoše k Davidu u Siklag dok se još uklanjao od Kiševa sina Šaula i bili su mu među junacima pomagači u boju;');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 12, 2, 'umjeli su rukovati lukom i desnicom i ljevicom i znali se služiti kamenjem i strijelama. Između Šaulove braće, Benjaminovaca:');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 12, 3, 'vojvoda Ahiezer i Joaš, sinovi Gibeanca Šemaje, pa Jeziel i Pelet, Azmavetovi sinovi, i Beraka i Jehu Anatoćanin;');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 12, 4, 'Gibeonac Išmaja, junak među tridesetoricom i nad tridesetoricom,');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 12, 5, 'Jeremija, Jahaziel, Johanan i Jozabad Gederoćanin;');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 12, 6, 'Eluzaj, Jerimot, Bealja, Šemarja i Šefatja Harufejac;');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 12, 7, 'Elkana, Jišija, Azarel, Joezer i Jašobam Korhinjani,');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 12, 8, 'Joel i Zebadja, sinovi Jerohama Gedorca.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 12, 9, 'Neki su Gadovci prešli k Davidu u tvrđavu u pustinju, hrabri junaci, ratnici vješti boju, naoružani štitom i kopljem; lica im bijahu kao lavovska, a brzi bijahu kao gazele po gorama:');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 12, 10, 'vojvoda Ezer, drugi Obadja, treći Eliab;');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 12, 11, 'četvrti Mišmana, peti Jeremija,');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 12, 12, 'šesti Ataj, sedmi Eliel;');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 12, 13, 'osmi Johanan, deveti Elzabad,');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 12, 14, 'deseti Jeremija, jedanaesti Makbanaj.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 12, 15, 'To su bile od Gadovih sinova vojne starješine, najmanji nad stotinom, a najveći nad tisućom.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 12, 16, 'To su oni koji su prvoga mjeseca prešli preko Jordana kad se razlio preko svih svojih obala i koji su rastjerali sve stanovnike iz dubokih dolina na istok i na zapad.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 12, 17, 'Došli su i od Benjaminovih i Judinih sinova k Davidu u tvrđavu.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 12, 18, 'David je izašao pred njih i, progovorivši, rekao im: \"Ako dolazite s mirom k meni da mi pomognete, moje će se srce ujediniti s vama; ako li ste došli da me izdate mojim neprijateljima, neka Bog naših otaca vidi i neka osudi, jer nema nepravde na mojim rukama!\"');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 12, 19, 'Tada duh obuze Amasaja, vojvodu nad tridesetoricom, i on reče: \"Tebi, Davide! S tobom, sine Jišajev, mir! Mir s tobom, mir s onim tko ti pomaže, jer tvoj pomoćnik jest tvoj Bog!\" Tako ih je David primio i postavio ih među vojvode nad četama.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 12, 20, 'Od Manašeovih su sinova neki prešli k Davidu kad je išao s Filistejcima na Šaula u boj, ali im nije pomogao, jer su ga filistejski knezovi, dobro promislivši, otpustili govoreći: \"Mogao bi prijeći k svome gospodaru Šaulu, a to bi nas stajalo glava.\"');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 12, 21, 'Kad se, dakle, vraćao u Siklag, prešli su k njemu od Manašeova plemena: Adna, Jozabad, Jedael, Mihael, Jozabad, Elihu i Siltaj, glavari tisućnici u Manašeovu plemenu.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 12, 22, 'Oni su pomagali Davidu protiv razbojničkih četa jer su svi bili hrabri junaci te su postali zapovjednici u njegovoj vojsci.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 12, 23, 'Iz dana u dan odista su dolazili k Davidu da mu pomažu, sve dok njegov tabor ne postade divovski, kao Božji tabor.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 12, 24, 'Evo broja ljudi naoružanih za rat koji su došli k Davidu u Hebron da Šaulovo kraljevstvo prenesu na nj po Jahvinoj zapovijedi:');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 12, 25, 'Judinih sinova, koji su nosili štit i koplje, šest tisuća i osam stotina naoružanih za rat.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 12, 26, 'Od Šimunovih sinova, hrabrih junaka za rat, sedam tisuća i sto.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 12, 27, 'Od Levijevih sinova četiri tisuće i šest stotina.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 12, 28, 'Tako i Jojada, poglavar Aronovim potomcima, i s njim tri tisuće i sedam stotina;');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 12, 29, 'i mladi Sadok, hrabar junak, i od njegova roda dvadeset i dva kneza.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 12, 30, 'A od Benjaminovih sinova, Šaulove braće, tri tisuće, jer ih je dotad najveći dio još ostao vjeran Šaulovoj kući.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 12, 31, 'Efrajimovih sinova dvadeset tisuća i osam stotina, sve hrabrih junaka, ljudi na glasu u svojim porodicama.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 12, 32, 'Od polovine Manašeova plemena osamnaest tisuća, poimence spomenutih, da dođu da zakralje Davida.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 12, 33, 'Od Jisakarovih sinova, koji su umjeli proniknuti svoje vrijeme i spoznati što treba da učini Izrael; njihovih poglavara dvije stotine. Sva su im njihova braća bila podložna.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 12, 34, 'Od Zebulunovih sinova, sposobnih za rat i naoružanih za boj svakojakim bojnim oružjem, pedeset tisuća, koji su se odvažna srca vrstali u bojne redove.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 12, 35, 'Od Naftalijeva plemena tisuću knezova i s njima trideset i sedam tisuća ljudi sa štitovima i kopljima;');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 12, 36, 'od Danova plemena dvadeset i osam tisuća i šest stotina naoružanih za boj,');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 12, 37, 'a od Ašerova plemena četrdeset tisuća sposobnih za vojsku i za boj opremljenih.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 12, 38, 'Od onih s onu stranu Jordana, od Rubenova, od Gadova i od polovine Manašeova plemena, sto i dvadeset tisuća ljudi sa svakojakim ratnim oružjem.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 12, 39, 'Svi ti vojnici, svrstani u bojne redove, dođoše poštena srca u Hebron da zakralje Davida nad svim Izraelom; i svi su ostali Izraelci bili jednodušni da Davida postave za kralja.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 12, 40, 'Proveli su s Davidom tri dana, jedući i pijući. Braća sve spremiše za njih.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 12, 41, 'Njihovi su najbliži susjedi, sve do Jisakara, Zebuluna i Naftalija, donosili hranu na magarcima, devama i mazgama, a na volovima jela: brašna, smokvenih kolača, suha grožđa, vina, ulja, krupne i sitne stoke izobila, jer je bilo veselje u Izraelu.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 13, 1, 'David je vijećao s tisućnicima, stotnicima i sa svim vođama.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 13, 2, 'I reče on svemu zboru Izraelovu: \"Ako vam je pravo te ako je naš Bog Jahve odlučio tako, poslat ćemo glasnike k svojoj ostaloj braći u svim izraelskim zemljama, a tako i svećenicima s njima i levitima po gradovima pašnjaka njihovih, da se ujedine s nama.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 13, 3, 'Prenijet ćemo k sebi Kovčeg svoga Boga, jer ga nismo doista tražili za Šaulovih dana.\"');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 13, 4, 'Sav zbor odluči da se tako učini, jer je to bilo pravo u očima svega naroda.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 13, 5, 'Tako je David sabrao sav narod Izraelov od Egipatskoga Šihora pa do Ulaza u Hamat da donesu Kovčeg Božji iz Kirjat Jearima.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 13, 6, 'Pošao je David sa svim Izraelom u Baalu, u Kirjat Jearim, koji je u Judi, da odande ponesu Kovčeg Božji nazvan imenom Jahve, koji stoluje nad kerubinima.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 13, 7, 'Povezli su Kovčeg Božji na novim kolima iz Abinadabove kuće; a Uza i Ahjo upravljali su kolima.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 13, 8, 'David i sav Izrael igrali su pred Bogom iz sve snage pjevajući uza zvuke citara, harfa, bubnjeva, cimbala i truba.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 13, 9, 'Kad su došli do Kidonova gumna, posegnu Uza rukom da pridrži Kovčeg jer ga volovi umalo ne prevrnuše.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 13, 10, 'Ali se Jahve razgnjevio na Uzu i udario ga zato što je pružio ruku prema Kovčegu. Umro je ondje pred Bogom.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 13, 11, 'Davidu bijaše žao što je Jahve onako udario Uzu i on prozva ono mjesto Peres Uza, kako se zove i dan-danas.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 13, 12, 'Toga se dana David uplaši Boga i reče: \"Kako ću donijeti k sebi Kovčeg Božji?\"');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 13, 13, 'Nije dao svratiti Kovčega k sebi u Davidov grad nego ga skloni u kuću Obed-Edoma Gitejca.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 13, 14, 'I ostade Kovčeg Božji kod Obed-Edomove obitelji, u njegovoj kući, tri mjeseca. Jahve stoga blagoslovi Obed-Edomovu kuću i sve što je imao.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 14, 1, 'Tirski kralj Hiram posla k Davidu izaslanstvo i cedrovih drva, zidara i tesara da mu grade dvor.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 14, 2, 'Tada David spozna da ga je Jahve potvrdio za kralja nad Izraelom i da je uzvisio njegovo kraljevstvo radi svojega izraelskog naroda.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 14, 3, 'David je uzeo još žena u Jeruzalemu i imao još sinova i kćeri.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 14, 4, 'Evo imena djece koja mu se rodiše u Jeruzalemu: Šamua, Šobab, Natan, Salomon,');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 14, 5, 'Jibhar, Elišua, Elpalet,');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 14, 6, 'Nogah, Nefeg, Jafija,');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 14, 7, 'Elišama, Beeljada i Elifelet.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 14, 8, 'Kad su Filistejci čuli da su Davida pomazali za kralja nad svim Izraelom, iziđoše svi da se dočepaju Davida. David, čuvši to, iziđe pred njih.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 14, 9, 'Filistejci dođoše i raširiše se po Refaimskoj dolini.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 14, 10, 'Tada David upita Boga: \"Mogu li napasti Filistejce? Hoćeš li ih predati meni u ruke?\" Jahve mu odgovori: \"Napadni, jer ću ih predati tebi u ruke!\"');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 14, 11, 'Tada krenuše u Baal Perasim i David ih ondje pobi. David reče: \"Bog je prodro među moje neprijatelje mojom rukom, kao što voda prodire.\" Stoga se ono mjesto prozvalo Baal Perasim.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 14, 12, 'Ostavili su ondje svoje bogove; a David zapovjedi da ih spale.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 14, 13, 'Opet se Filistejci raširiše po onoj dolini.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 14, 14, 'David opet upita Boga, a Bog mu odgovori: \"Ne idi za njima nego ih opkoli i navali na njih s protivne strane Bekaima.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 14, 15, 'Pa kad začuješ topot koraka po bekaimskim vrhovima, onda izađi u boj, jer će tada ići Bog pred tobom da pobije filistejsku vojsku.\"');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 14, 16, 'David učini kako mu je zapovjedio Bog; i pobili su filistejsku vojsku od Gibeona do Gezera.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 14, 17, 'Davidovo se ime pročulo po svim zemljama, a Jahve uli strah od njega svim narodima.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 15, 1, 'Onda je David sazidao dvore u Davidovu gradu, pripravio mjesto za Kovčeg Božji i razapeo mu Šator.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 15, 2, 'Potom je rekao David: \"Ne smije nositi Kovčeg Božji nitko osim levita, jer je njih izabrao Jahve da nose Kovčeg Jahvin i da mu služe dovijeka.\"');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 15, 3, 'David je sakupio sav Izrael u Jeruzalem da prenesu Kovčeg Jahvin gore na njegovo mjesto koje mu bijaše pripravio.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 15, 4, 'Skupio je David i Aronove sinove i levite.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 15, 5, 'Od Kehatovih sinova: kneza Uriela i sto dvadeset njegove braće;');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 15, 6, 'od Merarijevih sinova: kneza Asaju i dvjesta dvadeset njegove braće;');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 15, 7, 'od Geršomovih sinova: kneza Joela i sto trideset njegove braće.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 15, 8, 'Od Elisafanovih sinova: kneza Šemaju i dvjesta njegove braće.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 15, 9, 'Od Hebronovih sinova: kneza Eliela i osamdeset njegove braće;');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 15, 10, 'od Uzielovih sinova: kneza Aminadaba i sto dvanaest njegove braće.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 15, 11, 'Tada David pozva svećenike Sadoka i Ebjatara i levite Uriela, Asaju, Joela, Šemaju, Eliela i Aminadaba,');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 15, 12, 'pa im reče: \"Vi ste glavari levitskih porodica; posvetite sebe i svoju braću da prenesete gore Kovčeg Jahve, Izraelova Boga, na mjesto koje sam mu pripravio.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 15, 13, 'Jer nas je pobio Jahve, Bog naš, zato što prvi put vi niste bili nazočni i što ga nismo tražili onako kako je trebalo.\"');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 15, 14, 'Posvetiše se tada svećenici i leviti da prenesu gore Kovčeg Jahve, Izraelova Boga.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 15, 15, 'Levitski su sinovi ponijeli Božji Kovčeg, na svojim ramenima, o motkama, kako je zapovjedio Mojsije po Jahvinoj riječi.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 15, 16, 'Tada David reče levitskim knezovima da između svoje braće postave pjevače s glazbalima, s harfama, citrama i cimbalima da se čuje i da gromko odjekuje radosno pjevanje.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 15, 17, 'Leviti su postavili Joelova sina Hemana, a od njegove braće Berekjina sina Asafa, i od njihove braće, Merarijevih sinova, Kušajina sina Etana.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 15, 18, 'S njima njihovu braću drugoga reda: Zahariju, sina Jaazielova, Šemiramota, Jehiela, Unija, Eliaba, Benaju, Maaseju, Matitju, Eliflehua, Mikneju, Obed Edoma i Jeiela, vratare.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 15, 19, 'A pjevači, Heman, Asaf i Etan gromko su udarali u mjedene cimbale.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 15, 20, 'A Zaharija, Uziel, Šemiramot, Jehiel, Uni, Eliab, Maaseja i Benaja u harfe s visokim zvucima;');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 15, 21, 'a Matitja, Eliflehu, Mikneja, Obed Edom, Jeiel i Azazja u citre, u osminskoj pratnji.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 15, 22, 'Kenanja, knez onih levita koji su nosili Kovčeg, upravljao je prenošenjem jer je bio vješt u tome.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 15, 23, 'Berekja i Elkana bili su vratari kod Kovčega.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 15, 24, 'Šebanija, Jošafat, Netanel, Amasaj, Zaharija, Benaja i Eliezer, svećenici, trubili su u trube pred Božjim Kovčegom; Obed Edom i Jehija bili su vratari kod Kovčega.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 15, 25, 'Tako je David s izraelskim starješinama i tisućnicima radosno išao prenoseći gore Kovčeg saveza Jahvina iz Obed-Edomove kuće.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 15, 26, 'Kad je Bog pomogao levitima koji su nosili Kovčeg saveza Jahvina, žrtvovali su sedam junaca i sedam ovnova.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 15, 27, 'David bijaše ogrnut plaštem od tanka platna, a tako i svi leviti što su nosili Kovčeg, kao i pjevači i Kenanija koji je upravljao pjevačima. David je imao na sebi lanen oplećak.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 15, 28, 'Tako je sav Izrael prenosio gore Kovčeg saveza Jahvina, radosno kličući uz jeku rogova, truba i cimbala, igrajući uza zvuke harfe i citre.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 15, 29, 'Kad je Kovčeg saveza Jahvina ulazio u Davidov grad, Šaulova kći Mikala, gledajući s prozora, vidje kralja Davida kako skače i igra i prezre ga ona u svom srcu.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 16, 1, 'Tada unesoše Kovčeg Božji i postaviše ga usred šatora koji mu bijaše razapeo David. Onda su prinijeli paljenice i pričesnice pred Bogom.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 16, 2, 'Pošto je prinio paljenice i pričesnice, David blagoslovi narod Jahvinim imenom.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 16, 3, 'Onda razdijeli svim Izraelcima, ljudima i ženama, svakome po jedan okrugao kruh, komad mesa i kolač od suhoga grožđa.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 16, 4, 'Onda je postavio pred Jahvinim Kovčegom službenike među levitima da uznose, slave i hvale Jahvu, Boga Izraelova, i to:');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 16, 5, 'poglavara Asafa, a drugoga za njim Zahariju, zatim Jeiela, Šemiramota, Jehiela, Matitju, Eliaba, Benaju, Obed Edoma i Jeiela s harfama i citrama; Asaf je udarao u cimbale.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 16, 6, 'Svećenici Benaja i Jahaziel bili su bez prijekida s trubama pred Kovčegom saveza Jahvina.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 16, 7, 'Toga dana povjeri David prvi put Asafu i njegovoj braći da slave Jahvu ovom pohvalnicom:');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 16, 8, '\"Hvalite Jahvu, prizivajte mu ime; navješćujte među narodima djela njegova!');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 16, 9, 'Pjevajte mu, svirajte mu, propovijedajte sva njegova čudesa!');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 16, 10, 'Dičite se svetim imenom njegovim, neka se raduje srce onih što traže Jahvu!');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 16, 11, 'Tražite Jahvu i njegovu snagu, tražite svagda njegovo lice!');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 16, 12, 'Sjetite se čudesa koja učini, njegovih čuda i sudova usta njegovih.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 16, 13, 'Izraelov rod njegov je sluga, sinovi Jakovljevi njegovi izabranici.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 16, 14, 'On je Jahve, Bog naš; po svoj su zemlji njegovi sudovi!');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 16, 15, 'Sjećajte se uvijek njegova Saveza, Riječi koju objavi tisući naraštaja;');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 16, 16, 'Saveza koji sklopi s Abrahamom i njegove zakletve Izaku.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 16, 17, 'Ustanovi je kao zakon Jakovu, Izraelu vječni Savez.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 16, 18, 'Govoreći \'Tebi ću dati kanaansku zemlju kao dio u baštinu vašu,');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 16, 19, 'kad vas još bješe malo na broju, vrlo malo, i kad bjeste pridošlice u njoj.\'');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 16, 20, 'Išli su od naroda do naroda, iz jednoga kraljevstva k drugom narodu.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 16, 21, 'Ne dopusti nikom da ih tlači, kažnjavaše zbog njih kraljeve:');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 16, 22, '\'Ne dirajte u moje pomazanike, ne činite zla mojim prorocima!\'');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 16, 23, 'Pjevaj Jahvi, sva zemljo, Navješćujte iz dana u dan spasenje njegovo!');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 16, 24, 'Kazujte poganima njegovu slavu, svim narodima čudesa njegova.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 16, 25, 'Velik je Jahve, hvale predostojan, strašniji od svih bogova.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 16, 26, 'Ništavni su svi bozi naroda. Jahve stvori nebesa.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 16, 27, 'Slava je i veličanstvo pred njim, sila i radost u Svetištu njegovu.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 16, 28, 'Dajte Jahvi, narodna plemena, dajte Jahvi slavu i silu!');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 16, 29, 'Dajte Jahvi slavu imena njegova, nosite prinose i dolazite pred njegovo lice! Poklonite se Jahvi u sjaju svetosti njegove!');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 16, 30, 'Strepi pred njim, zemljo sva! Učvrstio je svemir da se ne poljulja.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 16, 31, 'Neka se vesele nebesa i neka klikće zemlja; neka se govori među poganima: \'Jahve kraljuje!\'');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 16, 32, 'Neka huči more i što je u njemu; nek\' se raduje polje i što je na njemu!');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 16, 33, 'Neka klikće šumsko drveće pred Jahvom, jer dolazi da sudi zemlji.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 16, 34, 'Slavite Jahvu jer je dobar, jer je vječna ljubav njegova.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 16, 35, 'I recite: \'Spasi nas, o Bože, Spasitelju naš, i saberi nas i izbavi nas od bezbožnih naroda, da slavimo tvoje sveto ime, da se ponosimo tvojom slavom.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 16, 36, 'Blagoslovljen Jahve, Bog Izraelov, od vijeka do vijeka!\' Sav narod neka kaže: \'Amen! Aleluja!\'\"');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 16, 37, 'I ondje pred Kovčegom saveza Jahvina ostaviše Asafa i njegovu braću da služe pred Kovčegom bez prestanka, koliko treba iz dana u dan;');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 16, 38, 'i Obed-Edoma s njegovom braćom, njih šezdeset i osam, i Obed-Edoma, Jedutunova sina, i Hosu, da budu vratari;');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 16, 39, 'a svećenika Sadoka s njegovom braćom svećenicima pred Jahvinim Prebivalištem na uzvišici u Gibeonu');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 16, 40, 'da prinose paljenice Jahvi na žrtveniku za paljenice bez prestanka, jutrom i večerom, i da vrše sve što je napisano u Zakonu koji je Jahve odredio Izraelu;');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 16, 41, 's njima Hemana i Jedutuna i ostale izabrane, koji su bili poimence spomenuti, da slave Jahvu, \"jer je vječna njegova ljubav\";');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 16, 42, 'i to Hemana i Jedutuna da trube u trube i udaraju u cimbale i druga glazbala Bogu na čast; a Jedutunove sinove da budu vratari.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 16, 43, 'Tada se razišao sav narod, svatko svojoj kući; a David se vratio da blagoslovi svoj dvor.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 17, 1, 'Kad se David nastanio u dvoru, rekao je proroku Natanu: \"Pogledaj! Ja, evo, stojim u dvoru od cedrovine, a Kovčeg saveza Jahvina pod zavjesama!\"');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 17, 2, 'Natan odgovori Davidu: \"Što ti je god na srcu, čini, jer je Bog s tobom.\"');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 17, 3, 'Ali još iste noći dođe Natanu ova Božja riječ:');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 17, 4, '\"Idi i reci mome sluzi Davidu: \'Ovako govori Jahve: Ti mi nećeš sagraditi kuće da prebivam u njoj.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 17, 5, 'Nisam nikad prebivao u kući otkako sam izveo Izraela iz Egipta pa do današnjega dana, nego sam išao od šatora do šatora i od prebivališta do prebivališta.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 17, 6, 'Dok sam hodio sa svim Izraelom, jesam li ijednu riječ rekao nekom od Izraelovih sudaca, kojima sam zapovjedio da budu pastiri mojem narodu, i kazao: Zašto mi ne sagradite kuću od cedrovine?\'');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 17, 7, 'Zato sad ovo reci mome sluzi Davidu: \'Ovako govori Jahve nad vojskama: Ja sam te doveo s pašnjaka, od ovaca i koza, da budeš knez nad mojim izraelskim narodom.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 17, 8, 'Bio sam s tobom kuda si god išao, iskorijenio sam sve tvoje neprijatelje pred tobom. Ja ću ti pribaviti veliko ime, kao što je velikaško ime na zemlji.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 17, 9, 'Odredit ću prebivalište svome izraelskom narodu i posadit ću ga da živi na svojem mjestu i da ne luta više naokolo niti da ga zlikovci muče kao prije,');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 17, 10, 'onda kad sam odredio suce nad svojim izraelskim narodom. Pokorit ću sve tvoje neprijatelje i učinit ću te velikim. Jahve će ti podići dom.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 17, 11, 'Jer kad se ispune tvoji životni dani i dođe vrijeme da počineš kod otaca, podići ću tvoga potomka nakon tebe, koji će biti između tvojih sinova, i utvrdit ću njegovo kraljevstvo.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 17, 12, 'On će mi sagraditi dom, a ja ću utvrditi njegovo prijestolje zauvijek.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 17, 13, 'Ja ću njemu biti otac, a on će meni biti sin: svoje naklonosti neću odvratiti od njega, kao što sam je odvratio od tvoga prethodnika.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 17, 14, 'Utvrdit ću ga u svojem domu i u svom kraljevstvu zauvijek, i prijestolje će mu čvrsto stajati zasvagda.\'\"');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 17, 15, 'Natan prenese Davidu sve te riječi i cijelo viđenje.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 17, 16, 'Tada kralj David dođe i stade pred Jahvu i reče: \"Tko sam ja, o Bože Jahve, i što je moj dom te si me doveo dovde?');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 17, 17, 'Pa i to je bilo premalo u tvojim očima, o Bože, nego si dao obećanja domu svoga sluge i za daleku budućnost i pogledao si na me kako se gleda na ugledna čovjeka, o Bože Jahve!');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 17, 18, 'Pa što da ti još David govori o slavi tvoga sluge; tÓa ti poznaješ svoga slugu!');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 17, 19, 'Jahve, radi svoga sluge i po svome srcu učinio si sve ovo veliko djelo, obznanivši ove veličajnosti.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 17, 20, 'Jahve, nema takvoga kakav si ti, niti ima Boga osim tebe, po svemu što smo ušima svojim čuli.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 17, 21, 'Postoji li ijedan narod na zemlji kao tvoj izraelski narod, radi kojega je Bog išao da ga izbavi sebi za narod, da tako stečeš sebi ime velikim i strašnim čudesima, izgoneći krivobožačka plemena pred svojim narodom koji si otkupio iz Egipta?');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 17, 22, 'Tako si učinio svoj izraelski narod svojim narodom zauvijek, a ti si mu, Jahve, postao Bogom.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 17, 23, 'Zato sada, Jahve, neka bude čvrsta dovijeka riječ koju si dao svome sluzi i njegovu domu i učini kako si obrekao.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 17, 24, 'Neka bude čvrsta, da se veliča tvoje ime zauvijek i da se govori: Jahve nad vojskama, Izraelov Bog, jest Bog nad Izraelom, a dom tvoga sluge Davida neka stoji čvrsto pred tobom.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 17, 25, 'Jer si ti, moj Bože, javio uhu svoga sluge da ćeš mu podići dom, zato je tvoj sluga smogao hrabrosti da se pomoli pred tobom.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 17, 26, 'Uistinu, Jahve, ti si Bog i ti si ovo lijepo obećanje dao svome sluzi.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 17, 27, 'Zato se sada udostoj blagosloviti dom svoga sluge da ostane dovijeka pred tobom, jer kad ti, Jahve, blagosloviš, bit će blagoslovljen zasvagda.\"');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 18, 1, 'Poslije toga David porazi Filistejce i pokori ih te ote Gat s njegovim selima iz filistejskih ruku.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 18, 2, 'Porazio je i Moapce i oni postadoše Davidovi podanici koji su mu donosili danak.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 18, 3, 'David je porazio i Hadadezera, sopskoga kralja u Hamatu, kad je izišao da utvrdi svoju vlast do rijeke Eufrata.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 18, 4, 'David zarobi od njega tisuću bojnih kola, sedam tisuća konjanika i dvadeset tisuća pješaka; ispresijecao je petne žile svim konjima od bojnih kola, ostavio ih je samo stotinu.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 18, 5, 'Damaščanski su Aramejci bili došli u pomoć Hadadezeru, sopskome kralju, ali je David pobio među Aramejcima dvadeset i dvije tisuće ljudi.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 18, 6, 'Postavio je namjesnike u Damaščanskom Aramu. Tako Aramejci postadoše Davidovi podanici i moradoše mu plaćati danak. Jahve je davao pobjedu Davidu kuda je god išao.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 18, 7, 'David zaplijeni zlatne štitove što ih imahu Hadadezerove sluge i donese ih u Jeruzalem.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 18, 8, 'I iz Hadadezerovih gradova Tibhata i Kuna odnio je silni tuč od kojega je Salomon načinio mjedeno more, stupove i tučano posuđe.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 18, 9, 'Kad je čuo hamatski kralj Tou da je David porazio svu vojsku Hadadezera, sopskoga kralja,');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 18, 10, 'posla svoga sina Hadorama kralju Davidu da ga pozdravi i da mu čestita što je vojevao protiv Hadadezera i porazio ga, jer je Tou bio u ratu s Hadadezerom; i da mu odnese svakojakih zlatnih, srebrnih i tučanih predmeta.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 18, 11, 'I njih je kralj David posvetio Jahvi sa srebrom i zlatom što ga bijaše uzeo od svih naroda, od Edomaca, Moabaca, Amonaca, Filistejaca i Amalečana.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 18, 12, 'Sarvijin sin Abišaj pobio je osamnaest tisuća Edomaca u Slanoj dolini.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 18, 13, 'David je postavio namjesnike po Edomu. Tako su svi Edomci postali Davidove sluge. I kuda je god David išao, Jahve mu davaše pobjedu.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 18, 14, 'David kraljevaše nad svim Izraelom čineći pravo i pravicu svemu svome narodu.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 18, 15, 'Sarvijin je sin Joab bio zapovjednik vojske; Ahiludov sin Jošafat bijaše tajni savjetnik.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 18, 16, 'Ahitubov sin Sadok i Ahimelekov sin Ebjatar bili su svećenici, Šavša pisar.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 18, 17, 'Jojadin sin Benaja bio je nad Kerećanima i Pelećanima, a Davidovi su sinovi bili prvi do kralja.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 19, 1, 'Poslije toga umrije Nahaš, kralj Amonaca, i zakralji mu se sin na njegovo mjesto.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 19, 2, 'David reče u sebi: \"Iskazat ću ljubav Nahaševu sinu Hanunu jer je i njegov otac iskazao milost meni.\" David uputi poslanike da mu izraze sućut zbog smrti njegova oca. Kad su Davidove sluge došle u zemlju Amonaca k Hanunu da mu izraze sućut,');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 19, 3, 'rekoše knezovi Amonaca Hanunu: \"Zar misliš da je David poslao ljude da ti izraze sućut zato što bi htio iskazati čast tvome ocu? Nisu li zato došle njegove sluge k tebi da razvide, istraže i uhode zemlju?\"');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 19, 4, 'Tada Hanun pograbi Davidove sluge i obrija ih, podreza im haljine dopola, do zadnjice, i posla ih natrag!');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 19, 5, 'Kad su to javili Davidu, posla on čovjeka pred njih, jer su bili vrlo osramoćeni, i poruči im: \"Ostanite u Jerihonu dok vam ne naraste brada pa se onda vratite.\"');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 19, 6, 'Kad su Amonovi sinovi vidjeli da su se omrazili s Davidom, poslao je Hanun s Amonovim sinovima tisuću srebrnih talenata da za plaću najme bojnih kola i konjanika iz Aram Naharajima, iz Aram Maake i iz Soba.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 19, 7, 'Najmili su za plaću trideset i dvije tisuće bojnih kola, i kralja Maake s njegovim narodom te su oni došli i utaborili se pred Medebom. Amonovi su se sinovi skupili iz svojih gradova i došli u boj.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 19, 8, 'Kad je to čuo David, poslao je Joaba sa svom svojom junačkom vojskom.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 19, 9, 'Amonovi sinovi iziđoše i svrstaše se u bojni red pred gradskim vratima; a kraljevi koji su došli stajali su zasebno na polju.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 19, 10, 'Vidjevši postavljene bojne redove prema sebi, sprijeda i straga, Joab probra najvrsnije među Izraelcima i svrsta ih prema Aramejcima.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 19, 11, 'Ostalu vojsku predade bratu Abišaju da je svrsta prema Amoncima.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 19, 12, 'I reče mu: \"Ako Aramejci budu jači od mene, onda ti meni priskoči u pomoć; ako li Amonci budu jači od tebe, ja ću tebi pohrliti u pomoć.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 19, 13, 'Budi hrabar i junački se držimo radi naroda i radi gradova svoga Boga; a Jahve neka učini što je dobro u njegovim očima.\"');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 19, 14, 'Tada se Joab i vojska koja je bila s njim počeše primicati da udare na Aramejce, ali oni pobjegoše pred njima.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 19, 15, 'Kad su Amonci vidjeli da su Aramejci pobjegli, umakoše i oni ispred njegova brata Abišaja i povukoše se u grad. Tada se Joab vrati u Jeruzalem.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 19, 16, 'A Aramejci, vidjevši gdje su ih potukli Izraelci, uputili su poslanike i doveli Aramejce što su s onu stranu Rijeke, na čelu sa Šofakom, vojvodom Hadadezerove vojske.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 19, 17, 'Pošto su to javili Davidu, on skupi sve Izraelce i, prešavši preko Jordana, primače se Aramejcima i svrsta se prema njima; kad se David svrstao prema Aramejcima u bojni red, oni zametnuše s njime boj.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 19, 18, 'Ali Aramejci udariše u bijeg ispred Izraelaca i David im pobi sedam tisuća konja od bojnih kola i četrdeset tisuća pješaka; pogubio je i vojvodu Šofaka.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 19, 19, 'Kad Hadadezerove sluge vidješe da ih je razbio Izrael, sklopiše mir s Davidom i počeše mu služiti. A Aramejci se više nisu usuđivali pomagati Amoncima.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 20, 1, 'Slijedeće godine, u doba kad kraljevi izlaze u rat, izvede Joab vojsku i poče pustošiti zemlju amonsku. Došavši, opsjeo je Rabu; David bijaše ostao u Jeruzalemu. Joab je osvojio Rabu i razorio je.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 20, 2, 'Tada je David uzeo njihovu kralju s glave krunu i vidio da je teška jedan zlatni talenat, a na njoj je bilo drago kamenje. Stavili su je na glavu Davidu, koji je iz grada odnio vrlo velik plijen.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 20, 3, 'Narod koji bijaše u gradu izvede van i stavi ga da radi pilama, gvozdenim pijucima i sjekirama. Tako je David učinio svim gradovima Amonovih sinova. Potom se vratio sa svim narodom u Jeruzalem.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 20, 4, 'Poslije toga opet izbi rat s Filistejcima u Gezeru; tada je Hušanin Sibkaj pogubio Sipaja, koji je bio od Refaimovih potomaka; i bili su pokoreni.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 20, 5, 'Uz to je nastao i rat s Filistejcima, u kojem je Jairov sin Elhanan pogubio Lahmija, brata Golijata Gitejca, koji je imao kopljaču kao tkalačko vratilo.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 20, 6, 'Potom opet izbi rat u Gatu, gdje je bio neki čovjek visoka rasta: imaše taj na svakoj ruci i nozi po šest prstiju, dakle dvadeset i četiri; i on bijaše Rafin potomak.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 20, 7, 'Kad je počeo ružiti Izraela, ubi ga Jonatan, sin Davidova brata Šimeja.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 20, 8, 'To su bili Rafini potomci u Gatu koji su izginuli od Davidove ruke i od ruke njegovih slugu.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 21, 1, 'Tada Satan ustade na Izraela i potače Davida da izbroji Izraelce.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 21, 2, 'Kralj reče Joabu i narodnim knezovima: \"Idite, izbrojte Izraelce od Beer Šebe pa do Dana, onda se vratite i kažite mi koliko ih je na broju.\"');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 21, 3, 'Joab reče: \"Neka Jahve dade svome narodu još sto puta ovoliko koliko ga je sada! Nisu li, moj gospodaru kralju, svi oni sluge mome gospodaru? Zašto traži to moj gospodar? Zašto da bude na krivicu Izraelu?\"');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 21, 4, 'Ali kraljeva riječ bijaše jača od Joabove. Tako je Joab otišao i počeo obilaziti sav Izrael, a onda se, najposlije, vrati u Jeruzalem.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 21, 5, 'Joab dade Davidu popis naroda; Izraelaca bijaše milijun i sto tisuća ljudi vičnih maču, a Judejaca četiri stotine i sedamdeset tisuća vičnih maču.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 21, 6, 'Ali nije pobrojio među njima ni Levijeva ni Benjaminova plemena, jer je Joabu bila odvratna kraljeva zapovijed.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 21, 7, 'Bilo je to mrsko i u Božjim očima, pa Bog udari Izraela.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 21, 8, 'David reče Bogu: \"Veoma sam sagriješio što sam to učinio. Ali oprosti krivicu svome sluzi jer sam vrlo ludo radio!\"');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 21, 9, 'Jahve reče Davidovu vidiocu Gadu:');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 21, 10, '\"Idi i kaži Davidu: \'Ovako veli Jahve: Troje stavljam preda te; izaberi sebi jedno od toga da ti učinim!\'\"');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 21, 11, 'Došavši k Davidu, Gad mu reče: \"Ovako veli Jahve: \'Biraj sebi');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 21, 12, 'ili glad za tri godine, ili da tri mjeseca bježiš pred neprijateljima i mač tvojih neprijatelja da te stiže, ili da tri dana Jahvin mač i kuga bude na zemlji i Jahvin anđeo da ubija po svim izraelskim krajevima.\' Sada promisli i gledaj što da odgovorim onome koji me poslao!\"');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 21, 13, 'David reče Gadu: \"Na velikoj sam muci! Ah, neka padnem u Jahvine ruke, jer je veliko njegovo milosrđe, a u ljudske ruke da ne zapadnem!\"');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 21, 14, 'Tako je Jahve poslao kugu na Izraela te pomrije sedamdeset tisuća Izraelaca.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 21, 15, 'Bog je poslao anđela na Jeruzalem da ga istrebljuje; a kad je počeo istrebljivati, pogledao je Jahve i sažalilo mu se zbog zla, pa je rekao anđelu zatorniku: \"Dosta je sada, spusti ruku!\" Jahvin je anđeo stajao kraj gumna Jebusejca Ornana.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 21, 16, 'David, podigavši oči, vidje Jahvina anđela kako stoji između zemlje i neba držeći u ruci isukan mač koji je podigao na Jeruzalem, i on pade ničice sa starješinama obučenim u kostrijet.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 21, 17, 'David reče Bogu: \"Nisam li ja zapovjedio da se izbroji narod? Ja sam, dakle, onaj koji sam sagriješio i grdno zlo načinio, a što učiniše te ovce? Jahve, Bože moj, neka tvoja ruka dođe na me i na moju obitelj, a ne na taj narod da ga pomori!\"');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 21, 18, 'Tada Jahvin anđeo reče Gadu da kaže Davidu neka uziđe i neka podigne žrtvenik Jahvi na gumnu Jebusejca Ornana.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 21, 19, 'David je otišao po riječi koju mu je Gad rekao u Jahvino ime.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 21, 20, 'A Ornan, okrenuvši se, opazi anđela, a njegova se četiri sina sakriše. Ornan je vrhao pšenicu.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 21, 21, 'Uto dođe David do Ornana, a on, pogledavši i opazivši Davida, dođe s gumna i pokloni se Davidu licem do zemlje.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 21, 22, 'Tada David reče Ornanu: \"Daj mi to gumno da sagradim na njemu žrtvenik Jahvi; za potpunu cijenu daj mi ga da bi prestao pomor u narodu!\"');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 21, 23, 'Ornan odgovori Davidu: \"Neka ga uzme i neka čini moj gospodar kralj što je dobro u njegovim očima; evo, dajem ti goveda za paljenice, i mlatilice za drva, i pšenicu za prinosnicu; sve ti to poklanjam.\"');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 21, 24, 'Kralj David reče Ornanu: \"Ne, nego hoću da kupim u tebe i da platim, jer neću da prinosim Jahvi što je tvoje, da prinosim paljenice koje su mi poklonjene.\"');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 21, 25, 'I David dade Ornanu za ono mjesto šest stotina zlatnih šekela na mjeru.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 21, 26, 'Tada sagradi ondje žrtvenik Jahvi i prinese paljenice i pričesnice; a kad je prizvao Jahvu, on ga usliša spustivši oganj s neba na žrtvenik za paljenice.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 21, 27, 'Jahve zapovjedi anđelu da vrati mač u korice.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 21, 28, 'U ono vrijeme, vidjevši da ga je Jahve uslišio na gumnu Jebusejca Ornana, David poče prinositi žrtve ondje.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 21, 29, 'Jahvino prebivalište, koje je napravio Mojsije u pustinji, i žrtvenik za paljenice bio je u to vrijeme na uzvisini u Gibeonu.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 21, 30, 'David nije mogao ići k njemu da traži Boga jer ga je bio spopao strah od mača Jahvina anđela.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 22, 1, 'Zato David reče: \"Ovo je Dom Jahve i ovo je žrtvenik za paljenice Izraelu!\"');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 22, 2, 'David zapovjedi da se skupe stranci koji su bili u izraelskoj zemlji i odredi klesare da propisno klešu kamenje za gradnju Doma Božjeg.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 22, 3, 'David je pripravio mnogo željeza za čavle na vratnim krilima i za kvačice; i bez mjere mnogo tuča.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 22, 4, 'Mnogo cedrovine, jer su Sidonci i Tirci dovozili mnogo cedrovih drva Davidu.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 22, 5, 'Jer David mišljaše: \"Moj je sin Salomon mlad i nježan, a Dom koji treba graditi Jahvi mora biti veličanstven, na slavu i čast po svim zemljama. Hajde da mu sve pripravim.\" I David je pripravio mnogo toga prije svoje smrti.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 22, 6, 'Potom dozva sina Salomona i zapovjedi mu da sagradi Dom Jahvi, Bogu Izraelovu.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 22, 7, 'Još David reče Salomonu: \"Sine! Bio sam nakanio u srcu da sagradim Dom imenu Jahve, svoga Boga.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 22, 8, 'Ali mi je došla Jahvina riječ: \'Mnogo si krvi prolio i velike si ratove vodio; nećeš ti graditi Doma mome imenu jer si mnogo krvi prolio na zemlju preda mnom.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 22, 9, 'Gle, rodit će ti se sin; on će biti miroljubac i dat ću mu mir od svih njegovih neprijatelja odasvud unaokolo; ime će mu biti Salomon. Mir i pokoj dat ću Izraelu za njegova vremena.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 22, 10, 'On će sagraditi Dom mome imenu, on će mi biti sin, a ja ću njemu biti otac i utvrdit ću njegovo kraljevsko prijestolje nad Izraelom zauvijek.\'');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 22, 11, 'Sada, moj sine, neka bude Jahve s tobom da izvršiš i sagradiš Dom Jahve, svoga Boga, kao što je rekao za te.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 22, 12, 'Samo neka ti Jahve poda razum i mudrost kad te postavi nad Izraelom zato da se držiš Zakona Jahve, svoga Boga!');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 22, 13, 'Bit ćeš sretan budeš li brižno vršio uredbe i zakone koje je Jahve preko Mojsija dao Izraelu. Budi junak i hrabar, ne boj se i ne plaši se!');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 22, 14, 'Ja sam, evo, svojim trudom pripravio za Dom Jahvin sto tisuća zlatnih talenata i milijun srebrnih talenata, a tuča i željeza bez mjere, jer ga je tako mnogo. Pripravio sam i drva i kamenja, a i ti dodaj nešto k tomu.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 22, 15, 'Imaš mnogo valjanih radnika, klesara, zidara, tesara i svakovrsnih vještaka u svakom umijeću;');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 22, 16, 'zlatu, srebru, tuču i željezu nema mjere; idi, dakle, i gradi, i neka Jahve bude s tobom!\"');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 22, 17, 'Tada David zapovjedi svim izraelskim knezovima da pomažu njegovu sinu Salomonu:');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 22, 18, '\"Nije li s vama Jahve, Bog vaš, koji vam je dao mir odasvud unaokolo jer je predao u moje ruke stanovnike ove zemlje i zemlja je pokorena pred Jahvom i pred njegovim narodom.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 22, 19, 'Sada, dakle, pregnite svojim srcem i svojom dušom da tražite Jahvu, svoga Boga; idite i gradite Svetište Bogu Jahvi, unesite Kovčeg saveza Jahvina i Božje sveto posuđe u Dom koji će se sagraditi Jahvinu imenu!\"');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 23, 1, 'Ostarjevši i nauživši se dana, postavi David svoga sina Salomona kraljem nad Izraelom.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 23, 2, 'Potom skupi sve izraelske knezove, svećenike i levite.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 23, 3, 'On izbroji levite od trideset godina naviše, i bilo ih je po muškim glavama trideset i osam tisuća.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 23, 4, 'Između njih bilo je dvadeset i četiri tisuće onih koji su upravljali poslom oko Jahvina Doma, a šest tisuća nadzornika i sudaca,');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 23, 5, 'četiri tisuće vratara i četiri tisuće onih koji su hvalili Jahvu uz glazbala što ih je napravio za hvalu.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 23, 6, 'David ih razdijeli na redove po Levijevim sinovima: Geršonu, Kehatu i Merariju.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 23, 7, 'Od Geršonova su koljena bili: Ladan i Šimej.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 23, 8, 'Ladanovi sinovi: poglavari Jehiel, Zetam i Joel, njih trojica.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 23, 9, 'Šimejevi sinovi: Šelomit, Haziel i Haram, njih trojica; to su poglavari Ladanovih obitelji.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 23, 10, 'Šimejevi sinovi: Jahat, Zina, Jeuš i Berija. Ta su četvorica Šimejevi sinovi.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 23, 11, 'Jahat je bio poglavar, a drugi Ziza; a Jeuš i Berija nisu imali mnogo djece, zato su se brojili u jednu obitelj, u jedan razred.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 23, 12, 'Kehatovi sinovi: Amram, Jishar, Hebron i Uziel, četvorica.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 23, 13, 'Amramovi sinovi: Aron i Mojsije. Aron je bio određen da posvećuje Svetinju nad svetinjama; on i njegovi sinovi dovijeka da kade pred Jahvom, da mu služe i da blagoslivljaju u njegovo ime dovijeka.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 23, 14, 'Mojsije je bio Božji čovjek. Njegovi se sinovi broje u Levijevo pleme.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 23, 15, 'Mojsijevi su sinovi Geršom i Eliezer.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 23, 16, 'Geršomovi sinovi: poglavar Šebuel.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 23, 17, 'Eliezerovi su sinovi bili: poglavar Rehabja. Eliezer nije imao drugih sinova, nego su se Rehabjini sinovi vrlo namnožili.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 23, 18, 'Jisharovi sinovi: poglavar Šelomit.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 23, 19, 'Hebronovi sinovi: poglavar Jerija, drugi Amarja, treći Jahaziel, četvrti Jekamam.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 23, 20, 'Uzielovi sinovi: poglavar Mika, drugi Ješija.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 23, 21, 'Merarijevi sinovi: Mahli i Muši. Mahlijevi sinovi: Eleazar i Kiš.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 23, 22, 'Eleazar je umro nemajući sinova, nego samo kćeri, koje su sebi uzeli za žene njihovi rođaci, Kiševi sinovi.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 23, 23, 'Mušijevi sinovi: Mahli, Eder i Jerimot, trojica.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 23, 24, 'To su bili Levijevi sinovi po obiteljima, poglavari porodica, koji su bili popisani poimence; oni su radili posao za službu Jahvina Doma u dobi od dvadeset godina naviše.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 23, 25, 'David je rekao: \"Jahve, Izraelov Bog, dao je mir svojem narodu i živjet će u Jeruzalemu zauvijek.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 23, 26, 'Zato ni leviti neće više nositi Prebivališta ni svakovrsnog pribora za njegovu službu.\"');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 23, 27, 'Po posljednjim Davidovim riječima, bili su izbrojeni Levijevi sinovi od dvadeset godina naviše.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 23, 28, 'Bili su određeni da budu kraj Aronovih sinova u službi u Jahvinu Domu, u predvorjima i u dvoranama, da čiste sve svete stvari, da rade u službi oko Jahvina Doma,');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 23, 29, 'oko prinesenih hljebova, oko sitnog brašna za prinos, oko beskvasnih kolača pripravljenih na tavi i u ulju zamiješenih i oko mjera za sadržaj i dužinu;');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 23, 30, 'da pristupaju svakoga jutra, da slave i hvale Jahvu; tako i večerom.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 23, 31, 'A kad se god prinose paljenice Jahvi, subotom, za mlađaka i na blagdane, da dolaze prema svom broju, po svom redu, svagdje pred Jahvu.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 23, 32, 'I da vrše što treba vršiti u Šatoru sastanka, službu u Svetištu i službu za svoju braću, Aronove sinove, u službi oko Jahvina Doma.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 24, 1, 'Aronovi su sinovi imali svoje redove. Sinovi Aronovi bili su: Nadab, Abihu, Eleazar i Itamar.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 24, 2, 'Ali su Nadab i Abihu umrli prije oca i nisu imali djece; zato su svećeničku službu vršili Eleazar i Itamar.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 24, 3, 'David je razdijelio na redove njih i Sadoka, od Eleazarovih sinova, i Ahimeleka, od Itamarovih sinova, po njihovu redu u njihovoj službi.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 24, 4, 'Ali se u Eleazarovih sinova našlo više muških poglavara nego u Itamarovih sinova, pa kad ih podijeliše, od Eleazarovih je sinova bilo šesnaest porodičnih poglavara, a od Itamarovih sinova samo osam porodičnih poglavara.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 24, 5, 'Zato su ih razdijelili ždrebovima, jedne i druge, jer su posvećeni knezovi i Božji knezovi bili i od Eleazarovih sinova i od Itamarovih sinova.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 24, 6, 'Popisao ih je Netanelov sin Šemaja, pisar od Levijeva plemena, pred kraljem, knezovima, svećenikom Sadokom, Ebjatarovim sinom Ahimelekom, pred poglavarima porodica među svećenicima i levitima, uzevši po jednu porodicu za Eleazara, a po jednu opet za Itamara.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 24, 7, 'Prvi je ždrijeb pao na Jojariba, drugi na Jedaju,');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 24, 8, 'treći na Harima, četvrti na Seorima,');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 24, 9, 'peti na Malkiju, šesti na Mijamina,');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 24, 10, 'sedmi na Hakosa, osmi na Abiju,');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 24, 11, 'deveti na Ješuu, deseti na Šekaniju,');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 24, 12, 'jedanaesti na Elijašiba, dvanaesti na Jakima,');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 24, 13, 'trinaesti na Hupu, četrnaesti na Ješebaba,');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 24, 14, 'petnaesti na Bilgu, šesnaesti na Imera,');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 24, 15, 'sedamnaesti na Hezira, osamnaesti na Hapisesa,');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 24, 16, 'devetnaesti na Petahju, dvadeseti na Ezekiela,');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 24, 17, 'dvadeset i prvi na Jakina, dvadeset i drugi na Gamula,');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 24, 18, 'dvadeset i treći na Delaju, dvadeset i četvrti na Maazju.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 24, 19, 'To je njihov red u službi kojim treba da idu u Jahvin Dom, po svom pravilu, primljenu od oca im Arona, kako mu je zapovjedio Jahve, Bog Izraelov.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 24, 20, 'Od ostalih Levijevih sinova bio je od Amramovih sinova Šubael; od Šubaelovih sinova Jehdeja;');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 24, 21, 'od Rehabje, od Rehabjinih sinova poglavar Jišija;');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 24, 22, 'od Jisharovaca Šelomot; od Šelomotovih sinova Jahat.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 24, 23, 'Od Jerijinih sinova: drugi Amarja, treći Jahaziel, četvrti Jekaman.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 24, 24, 'Od sinova Uzielovih Mika; od Mikinih sinova Šamir;');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 24, 25, 'Mikin brat Jišija; od Jišijinih sinova Zaharija;');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 24, 26, 'Merarijevi sinovi: Mahli i Muši; sinovi Jaazije, njegova sina.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 24, 27, 'Merarijevi sinovi po Jaaziji, njegovu sinu: Šoham, Zakur i Ibri;');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 24, 28, 'po Mahliju Eleazar, koji nije imao djece;');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 24, 29, 'po Kišu, Kišovi sinovi, Jerahmeel.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 24, 30, 'Mušijevi sinovi: Mahli, Eder i Jerimot. To su bili levitski sinovi po svojim porodicama.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 24, 31, 'I oni su bacali ždrebove kao njihovi rođaci, Aronovi sinovi, pred kraljem Davidom, Sadokom, Ahimelekom i porodičnim poglavarima među svećenicima i levitima, i to jednako glavar obitelji kao i njegov najmlađi brat.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 25, 1, 'David je s vojničkim zapovjednicima izabrao za službu Asafove, Hemanove i Jedutunove sinove koji će zanosno pjevati hvalu uz citre, harfe i cimbale; između njih su bili izbrojeni ljudi za posao u svojoj službi:');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 25, 2, 'od Asafovih sinova: Zakur, Josip, Netanija i Asarela; Asafovi sinovi pod upravom Asafa, koji je zanosno pjevao hvalu po kraljevoj uredbi.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 25, 3, 'Od Jedutuna: Jedutunovih šest sinova: Gedalija, Sori, Ješaja, Šimej, Hašabja i Matitja pod upravom svog oca Jedutuna koji je zanosno pjevao hvalu uz citru slaveći i hvaleći Jahvu.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 25, 4, 'Od Hemana: Hemanovi sinovi: Bukija, Matanija, Uziel, Šebuel, Jerimot, Hananija, Hanani, Eliata, Gidalti, Romamti-Ezer, Jošbekaša, Maloti, Hotir, Mahaziot.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 25, 5, 'Svi su oni bili sinovi kraljeva vidioca Hemana koji je objavljivao Božje stvari da uzvisi njegovu moć; a Bog je dao Hemanu četrnaest sinova i tri kćeri.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 25, 6, 'Svi su oni pod vodstvom svoga oca Asafa te Jedutuna i Hemana pjevali u Jahvinu Domu uz cimbale, harfe i citre za službu u Božjem Domu, po kraljevoj uredbi.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 25, 7, 'Bilo ih je, s njihovom braćom, uvježbanih u pjevanju Jahvinih pjesama, dvjesta osamdeset i osam, sve samih vještaka.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 25, 8, 'Bacili su ždrebove za svoju službenu dužnost, najmanji isto kao i najveći, učitelj kao i učenik.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 25, 9, 'Prvi je ždrijeb pao na Asafovca Josipa, drugi na Gedaliju s njegovom braćom i sinovima, njih dvanaest,');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 25, 10, 'treći na Zakura s njegovim sinovima i braćom, njih dvanaest;');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 25, 11, 'četvrti na Jisrija s njegovim sinovima i braćom, njih dvanaest;');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 25, 12, 'peti na Netaniju s njegovim sinovima i braćom, njih dvanaest;');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 25, 13, 'šesti na Bukiju s njegovim sinovima i braćom, njih dvanaest,');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 25, 14, 'sedmi na Isarelu s njegovim sinovima i braćom, njih dvanaest;');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 25, 15, 'osmi na Ješaja s njegovim sinovima i braćom, njih dvanaest;');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 25, 16, 'deveti na Mataniju s njegovim sinovima i braćom, njih dvanaest;');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 25, 17, 'deseti na Šimeja s njegovim sinovima i braćom, njih dvanaest;');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 25, 18, 'jedanaesti na Azarela s njegovim sinovima i braćom, njih dvanaest;');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 25, 19, 'dvanaesti na Hašabju s njegovim sinovima i braćom, njih dvanaest;');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 25, 20, 'trinaesti na Šubaela s njegovim sinovima i braćom, njih dvanaest;');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 25, 21, 'četrnaesti na Matitju s njegovim sinovima i braćom, njih dvanaest;');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 25, 22, 'petnaesti na Jeremota s njegovim sinovima i braćom, njih dvanaest;');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 25, 23, 'šesnaesti na Hananiju s njegovim sinovima i braćom, njih dvanaest;');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 25, 24, 'sedamnaesti na Jošbekaša s njegovim sinovima i braćom, njih dvanaest;');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 25, 25, 'osamnaesti na Hananija s njegovim sinovima i braćom, njih dvanaest;');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 25, 26, 'devetnaesti na Malotija s njegovim sinovima i braćom, njih dvanaest;');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 25, 27, 'dvadeseti na Elijatu s njegovim sinovima i braćom, njih dvanaest;');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 25, 28, 'dvadeset i prvi na Hotira s njegovim sinovima i braćom, njih dvanaest;');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 25, 29, 'dvadeset i drugi na Gidaltija s njegovim sinovima i braćom, njih dvanaest;');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 25, 30, 'dvadeset i treći na Mahaziota s njegovim sinovima i braćom, njih dvanaest;');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 25, 31, 'dvadeset i četvrti na Romamti-Ezera s njegovim sinovima i braćom, njih dvanaest.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 26, 1, 'Vratarski su redovi bili: od Korahovaca: Korahov sin Mešelemja između Asafovih sinova;');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 26, 2, 'a Mešelemjini sinovi: prvenac Zaharija, drugi Jediael, treći Zebadja, četvrti Jatniel;');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 26, 3, 'peti Elam, šesti Johanan, sedmi Elijoenaj.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 26, 4, 'Sinovi Obed-Edomovi: prvenac Šemaja, drugi Jozabad, treći Joah, četvrti Sakar, a peti Netanel,');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 26, 5, 'šesti Amiel, sedmi Jisakar, osmi Peuletaj, jer ga je blagoslovio Bog,');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 26, 6, 'a njegovu su se sinu Šemaji rodili sinovi koji su bili poglavari u porodici jer bijahu hrabri junaci.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 26, 7, 'Šemajini su sinovi bili: Otni, Rafael, Obed, Elzabad sa svojom braćom, vrsnim ljudima, Elihu i Semakja.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 26, 8, 'Svi su oni bili od Obed-Edomovih sinova, oni i njihovi sinovi i njihova braća, vrsni ljudi, sposobni za službu; bilo ih je šezdeset i dva od Obed-Edoma.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 26, 9, 'Mešelemjinih sinova i braće, vrsnih ljudi, bilo je osamnaest.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 26, 10, 'Hosini sinovi od Merarijevih sinova: poglavar Šimri, iako nije bio prvenac, njegov ga je otac postavio za poglavara;');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 26, 11, 'drugi Hilkija, treći Tebalija, četvrti Zaharija; Hosinih svih sinova i braće bilo je trinaest.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 26, 12, 'Ovo su vratarski redovi. Glavari ovih junaka bili su, kao i njihova braća, čuvari u službi Jahvina Doma.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 26, 13, 'Bacali su ždrebove, najmanji kao i najveći, po obiteljima za svaka pojedina vrata.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 26, 14, 'Ždrijeb na istok pao je Šelemji; njegov sin Zaharija bio je mudar savjetnik. Kad su bacili ždrebove, dopao mu je ždrijeb na sjever,');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 26, 15, 'Obed-Edomu na jug; a njegovim sinovima na spremište;');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 26, 16, 'Šufimu i Hosi na zapad Šaleketskim vratima, na putu koji vodi k usponu; straža je bila do straže.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 26, 17, 'S istoka šest levita, sa sjevera četiri na dan, s juga četiri na dan; a kod spremišta po dva.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 26, 18, 'Na hramskoj prigradnji, sa zapada, četiri na usponu, dva kod prigradnje.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 26, 19, 'To su vratarski redovi među Korahovim i Merarijevim sinovima.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 26, 20, 'Leviti, njihova braća, bili su: Ahija nad blagom Božjega Doma i nad blagom posvećenih stvari.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 26, 21, 'Ladanovi sinovi, Geršonovci po Ladanu, poglavari obitelji Ladana Geršonovca, bili su Jehielovci.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 26, 22, 'Jehielovci Zetam i brat mu Joel bili su nadstojnici nad blagom Jahvina Doma.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 26, 23, 'Od Amramovaca, Jisharovaca, Hebronovaca i Uzielovaca bili su:');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 26, 24, 'Šebuel, sin Mojsijeva sina Geršoma, nadstojnik nad blagom.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 26, 25, 'Njegova braća po Eliezeru: Rehabja, sin mu, njegov sin Izaija, njegov sin Joram, njegov sin Zikri, njegov sin Šelomit.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 26, 26, 'Taj je Šelomit sa svojom braćom bio odgovoran za sve blago od posvećenih stvari koje je posvetio kralj David s porodičnim poglavarima, s tisućnicima, stotnicima i vojnim zapovjednicima.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 26, 27, 'Posvetili su dio ratnog plijena da se bolje ojača Jahvin Dom.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 26, 28, 'Što je god bio posvetio vidjelac Samuel, Kišev sin Šaul, Nerov sin Abner i Sarvijin sin Joab, sve posvećeno, bilo je pod nadzorom Šelomita i njegove braće.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 26, 29, 'Jisharovci Kenanija i njegovi sinovi bili su nad svjetovnim poslovima kao nadzornici i suci u Izraelu.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 26, 30, 'Hebronovci Hašabja i njegova braća, tisuću i sedam stotina vrsnih ljudi, upravljali su Izraelom s ovu stranu Jordana na zapadu u svakom Jahvinu poslu i u kraljevskoj službi.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 26, 31, 'Poglavar Hebronovaca bio je Jerija. Četrdesete godine Davidova kraljevanja potražili su obiteljska rodoslovlja Hebronovaca i našlo se među njima vrsnih ljudi u Gileadskom Jazeru.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 26, 32, 'Njegove braće, vrsnih ljudi, bilo je dvije tisuće i sedam stotina porodičnih poglavara; kralj David postavio ih je nad Rubenovim i Gadovim plemenom i nad polovinom Manašeova plemena za sve Božje poslove i za kraljevske poslove.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 27, 1, 'Izraelovi sinovi po svome broju. Poglavari porodica, tisućnici, stotnici i nadzornici služili su kralju u svakom poslu. U redovima su dolazili i odlazili od mjeseca do mjeseca, u svim godišnjim mjesecima; svaki je red imao dvadeset i četiri tisuće ljudi.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 27, 2, 'Nad prvim je redom, prvoga mjeseca, bio Zabdielov sin Jašobam. U svom je redu imao dvadeset i četiri tisuće ljudi.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 27, 3, 'Pripadao je Peresovim sinovima i bio zapovjednik svih vojvoda u vojsci prvoga mjeseca.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 27, 4, 'Nad redom drugoga mjeseca bio je Ahošanin Dodaj, a predstojnik u njegovu redu bio je Mikelot. U svom je redu imao dvadeset i četiri tisuće ljudi.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 27, 5, 'Vojvoda treće vojske, trećega mjeseca, bio je sin svećenika Jojade, poglavar Benaja. U svom je redu imao dvadeset i četiri tisuće.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 27, 6, 'Taj je Benaja bio junak među tridesetoricom i nad tridesetoricom i u njegovu je redu bio sin mu Amizabad.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 27, 7, 'Četvrti, četvrtoga mjeseca, bio je Joabov brat Asahel, a za njim sin mu Zebadja. U svom je redu imao dvadeset i četiri tisuće.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 27, 8, 'Peti, petoga mjeseca, bio je vojvoda Jizrahanin Šamhut. U svom je redu imao dvadeset i četiri tisuće.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 27, 9, 'Šesti, šestoga mjeseca, bio je Ikešov sin Ira, Tekoanac. U svom je redu imao dvadeset i četiri tisuće.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 27, 10, 'Sedmi, sedmoga mjeseca, bio je Pelonjanin Heles od Efrajimovih sinova. U svom je redu imao dvadeset i četiri tisuće.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 27, 11, 'Osmi, osmoga mjeseca, bio je Hušaćanin Sibkaj, Zarhijevac. U svom je redu imao dvadeset i četiri tisuće.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 27, 12, 'Deveti, devetoga mjeseca, bio je Anatoćanin Abiezer, Benjaminovac. U svom je redu imao dvadeset i četiri tisuće.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 27, 13, 'Deseti, desetoga mjeseca, bio je Netofaćanin Mahraj, Zarhijevac. U svom je redu imao dvadeset i četiri tisuće.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 27, 14, 'Jedanaesti, jedanaestoga mjeseca, bio je Piratonjanin Benaja, Efrajimovac. U svom je redu imao dvadeset i četiri tisuće.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 27, 15, 'Dvanaesti, dvanaestoga mjeseca, bio je Netofaćanin Heldaj, Otnielovac. U svom je redu imao dvadeset i četiri tisuće.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 27, 16, 'Nad Izraelovim plemenima bili su knezovi: nad Rubenovim Zikrijev sin knez Eliezer; nad Šimunovim Maakin sin Šefatja;');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 27, 17, 'nad Levijevim Kemuelov sin Hašabja; nad Aronovim Sadok;');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 27, 18, 'nad Judinim Elihu od Davidove braće; nad Jisakarovim Mihaelov sin Omri;');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 27, 19, 'nad Zebulunovim Obadjin sin Jišmaja; nad Naftalijevim Azrielov sin Jerimot.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 27, 20, 'Nad Efrajimovim sinovima Azazjin sin Hošea; nad polovinom Manašeova plemena Pedajin sin Joel,');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 27, 21, 'nad drugom polovinom Manašeova plemena u Gileadu Zaharijin sin Jido; nad Benjaminom Abnerov sin Jaasiel;');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 27, 22, 'nad Danom Jerohamov sin Azarel. To su bili knezovi izraelskih plemena.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 27, 23, 'Ali David nije dao izbrojiti onih kojima bijaše dvadeset godina i manje, jer Jahve bijaše rekao da će umnožiti Izraelce kao nebeske zvijezde.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 27, 24, 'Sarvijin je sin Joab počeo vršiti popis, ali ga nije dovršio. Stoga je Srdžba došla na Izrael i zato taj broj nije bio primljen u brojčani izvještaj Ljetopisa kralja Davida.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 27, 25, 'Nadstojnik nad kraljevim blagom bio je Adielov sin Azmavet, a nadstojnik za blago u zemlji, u gradovima, selima i tvrđavama, bio je Uzijin sin Jonatan.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 27, 26, 'Nadstojnik nad poljskim radnicima koji su obrađivali zemlju bio je Kelubov sin Ezri.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 27, 27, 'Nadstojnik nad vinogradarima Ramaćanin Šimej. Nadstojnik nad vinogradrskim klijetima bio je Šifmejac Zabdi.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 27, 28, 'Nadstojnik nad maslinama i dudovima što su po Šefeli bio je Gederac Hanan; nadstojnik nad skladištima ulja Joaš.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 27, 29, 'Nadstojnik nad govedima što su pasla u Šaronu bio je Šaronac Šitraj. Nadstojnik nad krupnom stokom u dolinama bio je Edlajev sin Šafat.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 27, 30, 'Nadstojnik nad devama Jišmaelac Obil. Nadstojnik nad magaricama Meronoćanin Jehdeja.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 27, 31, 'Nadstojnik nad ovcama i kozama Hagrijac Jaziz. Svi su oni bili nadstojnici nad imanjem kralja Davida.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 27, 32, 'Savjetnik je bio Davidov stric Jonatan, mudar čovjek; bio je i književnik; a Hakmonijev sin Jehiel bio je s kraljevim sinovima.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 27, 33, 'Ahitofel je bio kraljev savjetnik, Arkijac Hušaj kraljev prijatelj.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 27, 34, 'Ahitofela su naslijedili Benajin sin Jojada i Ebjatar, kraljev je vojvoda bio Joab.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 28, 1, 'David sakupi u Jeruzalem sve izraelske knezove, plemenske knezove i poglavare od redova koji su služili kralja, tisućnike, stotnike i nadstojnike nad svim imanjem i blagom kraljevim i blagom njegovih sinova, zajedno s dvoranima i junacima i svim hrabrim vojnicima.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 28, 2, 'Ustavši na noge, kralj David reče: \"Čujte me, moja braćo i moj narode! Ja sam bio namislio u svom srcu da sagradim dom gdje bi počivao Kovčeg saveza Jahvina i da bude podnožje nogama našega Boga te sam pripravio što treba za gradnju.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 28, 3, 'Ali mi je Bog rekao: \'Nećeš ti sagraditi Doma mome imenu jer si ratnik i prolijevao si krv.\'');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 28, 4, 'Jahve, Izraelov Bog, izabrao je mene od sveg moga roda da budem kralj nad Izraelom zauvijek; jer je Judu izabrao za kneza, a iz Judina doma dom moga oca; između sinova moga oca bilo mu je drago da mene postavi kraljem nad svim Izraelom.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 28, 5, 'Tako je između mojih sinova, jer mi je mnogo sinova dao Jahve, izabrao moga sina Salomona da sjedi na prijestolju Jahvina kraljevstva nad Izraelom.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 28, 6, 'I rekao mi je: \'Tvoj sin Salomon sagradit će meni Dom i moja predvorja; jer sam njega izabrao sebi za sina i ja ću mu biti otac.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 28, 7, 'Utvrdit ću njegovo kraljevstvo zauvijek ako bude postojano vršio moje zapovijedi i moje zakone kao danas.\'');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 28, 8, 'Sada, dakle, pred očima sveg Izraela, Jahvina zbora, i pred svojim Bogom, koji nas sluša, velim: držite i tražite sve zapovijedi Jahve, svoga Boga, da biste zadržali u posjedu ovu dobru zemlju i ostavili je u baštinu svojim sinovima nakon sebe dovijeka.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 28, 9, 'A ti, sine moj Salomone, poznaj Boga, svoga oca, i služi mu čitavim srcem i spremnom dušom, jer Jahve ispituje sva srca i zna sve misli i namjere; ako ga budeš tražio, dat će ti se da ga nađeš; ako li ga ostaviš, odbacit će te zauvijek.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 28, 10, 'Uvidi sada da te Jahve izabrao da gradiš Dom za Svetište, budi junak i radi!\"');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 28, 11, 'Tada David predade sinu Salomonu uzorak trijema, njegovih kuća, riznica, gornjih soba, ćelija i doma Pomirilišta;');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 28, 12, 'uzorak svega što bijaše smislio u duhu za predvorja Jahvina Doma, za sve sobe unaokolo, za riznicu Doma Božjega, za riznicu posvećenih stvari,');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 28, 13, 'za svećeničke i levitske redove, za svaki posao u službi oko Doma Jahvina:');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 28, 14, 'zlato u šipkama, zlato potrebno za sve zlatno posuđe ove ili one službe; srebro u šipkama potrebno za sve srebrno posuđe, za sve posuđe ove ili one službe;');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 28, 15, 'šipke za zlatne svijećnjake sa zlatnim svjetiljkama, prema težini svakoga svijećnjaka i njegovih svjetiljaka, i za srebrne svijećnjake prema težini svakoga svijećnjaka i njegovih svjetiljaka i prema namjeni svakog svijećnjaka;');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 28, 16, 'zlato u šipkama za stolove na kojima će stajati prineseni hljebovi, za svaki stol; srebro za srebrne stolove,');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 28, 17, 'za viljuške i kotliće, za čaše od čista zlata, za zlatne pehare, zlato u šipkama za svaki pehar; za srebrne pehare, srebro u šipkama za svaki pehar,');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 28, 18, 'za kadioni žrtvenik žeženoga zlata u šipkama; za uzorak od kola sa zlatnim kerubinima koji će raširenim krilima zaklanjati Jahvin Kovčeg.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 28, 19, 'Sve to u skladu s onim što Jahve napisa vlastitom rukom da bi razjasnio cijelo djelo za koje on pribavi uzorak.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 28, 20, 'Tada David reče svome sinu Salomonu: \"Budi junak, hrabar, i radi! Ne boj se i ne plaši se, jer će Jahve, Bog, moj Bog, biti s tobom! Neće te napustiti niti te ostaviti dok ne svršiš sav posao za službu oko Jahvina Doma.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 28, 21, 'Evo svećeničkih i levitskih redova za svaku službu u Božjem Domu; imaš uza se za svaki posao svakovrsnih ljudi, spremnih i vještih svakoj službi, knezovi i sav narod pod tvojim su zapovjedništvom.\"');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 29, 1, 'Kralj David reče svemu zboru: \"Bog je izabrao moga sina Salomona, mlado i nježno momče, a ovo je velik posao, jer neće biti za čovjeka dvor nego za Boga Jahvu.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 29, 2, 'Pripremio sam, koliko sam mogao, za Dom svoga Boga zlata za zlatne stvari i srebra za srebrne, tuča za tučane, željeza za željezne, drva za drvene; oniksova kamenja i dragulja za ukivanje, dragulja za ukras i šarenih dragulja, svakojakoga dragog kamenja i izobila mramora.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 29, 3, 'Iz ljubavi prema Bogu dajem još i svoga zlata i srebra za Dom svoga Boga, osim svega što sam pripravio za sveti Dom.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 29, 4, 'Tri tisuće zlatnih talenata ofirskoga zlata i sedam tisuća talenata čistoga srebra da se oblože zidovi prostorija.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 29, 5, 'Zlato za zlatne stvari, a srebro za srebrne i za svako djelo umjetničkih ruku. Bi li danas još tko htio dragovoljno što priložiti svojom rukom Jahvi?\"');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 29, 6, 'Tada su dragovoljno priložili knezovi obitelji i knezovi izraelskih plemena, tisućnici, stotnici i nadstojnici nad kraljevskim poslovima.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 29, 7, 'Dali su za službu u Božjem Domu zlata pet tisuća talenata i deset tisuća zlatnih darika, srebra deset tisuća talenata, tuča osamnaest tisuća talenata, željeza sto tisuća talenata.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 29, 8, 'U koga se god našlo dragulja, svi su darivali u riznicu Jahvina Doma na ruke Jehiela Geršonovca.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 29, 9, 'Narod se veselio što su dragovoljno prilagali, jer su prilagali iskrena srca Jahvi; i kralj David radovao se od srca.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 29, 10, 'Potom David blagoslovi Jahvu pred svim zborom. I reče David: \"Blagoslovljen da si, Jahve, Bože našeg oca Izraela, od vijeka do vijeka!');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 29, 11, 'Tvoja je, Jahve, veličina, sila, slava, sjaj i veličanstvo, jer je tvoje sve što je na nebu i na zemlji; tvoje je, Jahve, kraljevstvo i ti si uzvišen povrh svega, Poglavar svega!');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 29, 12, 'Od tebe je bogatstvo i slava, ti vladaš nad svim, u tvojoj je ruci sila i moć, u tvojoj je vlasti da učiniš velikim i jakim sve.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 29, 13, 'I slavimo te, Bože naš, i hvalimo tvoje dično ime.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 29, 14, 'Tko sam ja i što je moj narod da bismo imali snage ovoliko prinijeti tebi dragovoljno? Od tebe je sve, i iz tvojih ruku primivši, dali smo tebi!');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 29, 15, 'Pridošlice smo pred tobom, naseljenici kao svi naši očevi; naši dani na zemlji prolaze kao sjena i nema nade.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 29, 16, 'Jahve, Bože naš, sve ovo mnogo blago koje smo pripravili za gradnju Doma tebi, tvome svetom imenu, iz tvoje je ruke i sve je tvoje!');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 29, 17, 'Ali znam, o Bože moj, da ti iskušavaš srca i da ljubiš iskrenost; ja sam iskrena srca dragovoljno prinio sve ovo i s radošću sam gledao tvoj narod koji je ovdje kako ti dragovoljno prinosi.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 29, 18, 'Jahve, Bože naših otaca Abrahama, Izaka i Jakova, sačuvaj dovijeka u srcu svoga naroda tu misao i namjeru i upravi njegovo srce k sebi!');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 29, 19, 'A mome sinu Salomonu daj pošteno srce da bi se držao tvojih zapovijedi, tvojih odredaba i tvojih uredaba, da bi vršio sve i da bi sagradio dvor za koji sam sve spremio!\"');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 29, 20, 'Tada David reče svemu zboru: \"Blagoslovite sada Jahvu, svoga Boga!\" I sav je zbor blagoslovio Jahvu, Boga svojih otaca, i, pavši ničice, poklonio se Jahvi i kralju.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 29, 21, 'Žrtvovali su Jahvi klanice i prinijeli Jahvi paljenice sutradan: tisuću junaca, tisuću ovnova, tisuću jaganjaca s njihovim ljevanicama, mnogo drugih žrtava za sav Izrael.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 29, 22, 'Jeli su i pili pred Jahvom onoga dana vrlo se radujući. Zakraljili su po drugi put Davidova sina Salomona i pomazali ga po Jahvinoj volji za kneza, a Sadoka za svećenika.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 29, 23, 'Tako je Salomon sjeo na Jahvino prijestolje da kraljuje namjesto svoga oca Davida. Bio je sretan i slušao ga je sav Izrael.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 29, 24, 'Svi su knezovi i junaci i svi sinovi kralja Davida pružili ruku kralju Salomonu i svečano mu obećali pokornost.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 29, 25, 'Jahve je vrlo uzvisio Salomona pred očima sveg Izraela i dao njegovu kraljevstvu veličanstvo kakvo nijedan kralj prije njega nije imao u Izraelu.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 29, 26, 'Tako je Jišajev sin David kraljevao nad svim Izraelom.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 29, 27, 'Nad Izraelom je kraljevao četrdeset godina; u Hebronu je kraljevao sedam godina, u Jeruzalemu je kraljevao trideset i tri godine.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 29, 28, 'Umro je u lijepoj starosti, nauživši se života, bogatstva i slave. Na njegovo se mjesto zakraljio sin mu Salomon.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 29, 29, 'Djela kralja Davida, od prvog do posljednjeg, zapisana su u povijesti vidioca Samuela, u povijesti proroka Natana i u povijesti vidioca Gada,');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 29, 30, 'sa svim njegovim kraljevanjem, njegovim junaštvom i događajima što prijeđoše preko njega i Izraela i svih drugih kraljevstava zemaljskih.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 1, 1, 'Salomon, sin Davidov, bio se učvrstio na prijestolju. Jahve, Bog njegov, bijaše s njim i uzvisi ga veoma.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 1, 2, 'Salomon se tada obrati svem Izraelu, tisućnicima, satnicima, sucima, svim knezovima izraelskim, glavama obitelji,');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 1, 3, 'te se on i s njim sav Zbor popeše na uzvišicu koja bješe u Gibeonu, jer je ondje bio Šator sastanka što ga u pustinji podiže Mojsije, sluga Božji.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 1, 4, 'David bijaše prenio Kovčeg Božji iz Kirjat Jearima do mjesta koje je sam pripravio za nj; jer je bio podigao Šator u Jeruzalemu.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 1, 5, 'Tučani žrtvenik što ga napravi Besalel, sin Hurova sina Urija, bijaše ondje pred Prebivalištem Jahvinim, kamo dođoše Salomon i zbor da mu se obrate.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 1, 6, 'Ondje se Salomon pred Jahvom pope na tučani žrtvenik, koji bješe tik do Šatora sastanka, i prinese na njemu tisuću paljenica.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 1, 7, 'Iste se noći Bog ukaza Salomonu i reče mu: \"Traži što da ti dadem.\"');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 1, 8, 'Salomon odgovori: \"Veoma si naklon bio mome ocu Davidu i zakraljio si mene na njegovo mjesto.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 1, 9, 'Bože Jahve, neka se ispuni sada obećanje što si ga dao mome ocu Davidu, jer si me zakraljio nad narodom kojega ima mnogo kao zemaljske prašine.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 1, 10, 'Daj mi sada mudrost i znanje da uzmognem upravljati ovim narodom, jer tko će upravljati tolikim narodom kao što je ovaj tvoj!\"');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 1, 11, 'Bog reče Salomonu: \"Budući da ti je to u srcu, a nisi iskao ni bogatstva, ni blaga, ni slave, ni smrti neprijatelja i jer nisi tražio duga života nego mudrosti i znanja kako bi upravljao mojim narodom nad kojim te zakraljih,');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 1, 12, 'dajem ti mudrost i znanje. Ali ti dajem i bogatstva, blaga i slave kakve nije imao nijedan kralj što bješe prije tebe i kakve neće imati ni oni koji dođu poslije tebe.\"');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 1, 13, 'Salomon s uzvišice u Gibeonu ode u Jeruzalem, podalje od Šatora sastanka, i kraljevaše nad Izraelom.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 1, 14, 'Sakupi bojnih kola i konjanika: imao je tisuću četiri stotine kola i dvanaest tisuća konjanika i razmjesti ih po gradovima gdje mu bijahu kola i kod sebe u Jeruzalemu.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 1, 15, 'Salomon učini da srebra i zlata bude u Jeruzalemu izobila kao kamenja, a cedrova mnogo kao dudova u Šefeli.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 1, 16, 'Konji Salomonovi bili su uvezeni iz Musrija i Koe; kraljevski dvorani kupovahu ih u Koi za srebro.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 1, 17, 'Dovozila su se i prodavala jedna bojna kola iz Egipta po šest stotina srebrnih šekela, a konji po sto i pedeset; to bješe isto tako za sve hetitske i aramejske kraljeve koji su ih uvozili preko njih.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 1, 18, 'Salomon naumi sagraditi Dom - jedan Imenu Jahvinu, a drugi sebi za kraljevski dvorac.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 2, 1, 'Odbroji sedamdeset tisuća nosača, osamdeset tisuća kamenolomaca u gori i tri tisuće i šest stotina poslovođa.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 2, 2, 'Tada posla ovu poruku Hiramu, tirskomu kralju: \"Kao što si mome ocu Davidu slao cedrovine da gradi dvor gdje će živjeti, tako učini i meni.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 2, 3, 'Kanim podići Dom Imenu Jahve, svojega Boga, i posvetiti mu ga da se diže pred njim miomirisni kad, da se uvijek postavljaju kruhovi, da se prinose paljenice jutrom i večerom, subotom, na dane mlađaka i na blagdane Jahve, Boga našega; i tako da zauvijek ostane u Izraelu.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 2, 4, 'Dom koji gradim bit će velik, jer je naš Bog najveći među svim bozima.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 2, 5, 'TÓa tko bi imao dovoljno snage da njemu sazda Dom kad ga ni nebesa, ni nebesa nad nebesima ne mogu obuhvatiti? I tko sam ja da mu zidam Dom, osim zato da mu se kad diže pred lice?');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 2, 6, 'Pošalji mi čovjeka vična obradi zlata, srebra, tuča, željeza, grimiza, karmezina i ljubičastog baršuna, i vična umjetnosti rezbarstva: radit će s rukotvorcima kod mene u Judi i u Jeruzalemu, s onima što mi ih ostavi moj otac David.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 2, 7, 'Pošalji mi iz Libanona cedrovine, čempresovine i sandalovine, jer znam da tvoje sluge umiju sjeći libanonska stabla. Moje će sluge raditi s tvojima.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 2, 8, 'Morat će mi pripraviti mnogo drva, jer će kuća što je mislim graditi biti velika i veličanstvena.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 2, 9, 'Drvosječama što će obarati stabla dajem dvadeset tisuća kora pšenice, dvadeset tisuća kora ječma, dvadeset tisuća bata vina i dvadeset tisuća bata ulja za izdržavanje tvojih slugu.\"');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 2, 10, 'Hiram, tirski kralj, odgovori pismom što ga posla Salomonu: \"Zato što voli svoj narod, Jahve te zakraljio nad njim.\"');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 2, 11, 'Dometnu još i ovo: \"Neka je blagoslovljen Jahve, Bog Izraelov, koji je stvorio nebesa i zemlju. On je kralju Davidu dao mudra, pametna i umna sina koji će jedan dom graditi Jahvi, a drugi sebi da iz njega kraljuje.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 2, 12, 'Stoga ti šaljem čovjeka mudra, vješta i razumna, Hurama Abija,');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 2, 13, 'sina jedne Danovke i oca Tirca. Umije obrađivati zlato, srebro, tuč, željezo, kamen, drvo, grimiz, ljubičasti baršun, bÓez i karmezin, umije rezbariti svakovrsne rezbarije i zamisliti svako djelo koje mu se povjeri. On će raditi s tvojim umjetnicima i umjetnicima moga gospodara Davida, tvoga oca.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 2, 14, 'Neka, dakle, sada moj gospodar svojim slugama pošalje pšenice, ječma, ulja i vina kako je obećao.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 2, 15, 'A mi ćemo nasjeći stabala s Libanona koliko ti god treba i dovest ćemo ti ih na splavima morem u Jafu, a ti ih prevezi gore u Jeruzalem.\"');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 2, 16, 'Salomon pobroji sve strance koji se zatekoše u Izraelovoj zemlji poslije popisa što ga bijaše proveo njegov otac David i nađe ih sto pedeset tri tisuće i šest stotina.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 2, 17, 'Od njih odredi sedamdeset tisuća nosača, osamdeset tisuća tesara u planini, tri tisuće i šest stotina ljudi da upravljaju radom naroda.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 3, 1, 'Salomon tada poče graditi Dom Jahvi u Jeruzalemu, na Morijskoj gori, ondje gdje je njegov otac David imao viđenje. To je mjesto koje je pripravio David, gumno Jebusejca Ornana.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 3, 2, 'Salomon otpoče gradnju drugoga mjeseca četvrte godine svojega vladanja.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 3, 3, 'Ovo su temelji koje je Salomon postavio za gradnju Doma Božjega: šezdeset lakata u duljinu - po staroj mjeri lakta - a u širinu dvadeset lakata.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 3, 4, 'Trijem, koji je bio pred Domom, imao je, po širini ovoga potonjega, u dužinu dvadeset lakata, a visok je bio sto i dvadeset lakata. Obložio ga je iznutra čistim zlatom.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 3, 5, 'Veliku je dvoranu obložio čempresovinom, koju je prekrio čistim zlatom i postavio palme i cvjetne vijence.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 3, 6, 'Optočio je potom Dvoranu blistavim draguljima; zlato je bilo zlato parvajimsko.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 3, 7, 'Prekrio je njime Dvoranu: grede, pragove, zidove i vratna krila te izrezao kerubine po zidovima.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 3, 8, 'Potom sazda dvoranu Svetinje nad svetinjama. Bila je, prema hramskoj širini, dvadeset lakata duga i dvadeset lakata široka i obloži je sa šest stotina talenata suhog zlata.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 3, 9, 'Za čavle je dao na mjeru pedeset zlatnih šekela. I gornje je odaje obložio zlatom.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 3, 10, 'U dvorani Svetinje nad svetinjama napravi dva kerubina, liveno djelo. I njih obloži zlatom.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 3, 11, 'Krila kerubina bila su dvadeset lakata duga: jedno krilo od pet lakata dodirivaše hramski zid, a drugo od pet lakata doticaše krilo drugoga kerubina.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 3, 12, 'Tako je i krilo drugoga kerubina, od pet lakata, dodirivalo hramski zid, a drugo mu se krilo, od pet lakata, spajalo s krilom drugoga kerubina.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 3, 13, 'Raširena, krila kerubina imala su dvadeset lakata. Stajali su kerubini uspravno, lic-a okrenutih Dvorani.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 3, 14, 'Napravi zastor od ljubičastog baršuna, od grimiza, karmezina i bÓeza te na njemu izveze kerubine.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 3, 15, 'Pred Dvoranom napravi dva stupa dugačka trideset i pet lakata, a glavice im na vrhu pet lakata.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 3, 16, 'U Debiru on splete vijence te ih postavi navrh stupova i napravi sto mogranja koje postavi među vijence.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 3, 17, 'Postavi stupove pred Hekal, jedan zdesna, drugi slijeva, te nazva Jakin onaj zdesna, a Boaz onaj slijeva.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 4, 1, 'Napravi tučani žrtvenik dugačak dvadeset lakata, širok dvadeset i visok deset.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 4, 2, 'Tada od rastaljene kovine izli more koje je od ruba do ruba mjerilo deset lakata; bilo je okruglo uokolo, pet lakata visoko, a u opsegu, mjereno vrpcom, imalo je trideset lakata.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 4, 3, 'Pod njim bijahu likovi volovski što ga opasivahu uokrug. Po deset ih je bilo na jednom laktu te okruživahu more uokolo; dva je reda bilo tih volova, salivenih s morem.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 4, 4, 'More je počivalo na dvanaest volova; tri su gledala na sjever, tri na zapad, tri na jug, tri na istok: more je stajalo na njima i svi su stražnjim dijelom bili okrenuti unutra.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 4, 5, 'Bilo je debelo pedalj, rub mu kao rub u čaše, kao cvijet, a moglo je primiti tri tisuće bata.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 4, 6, 'Napravi deset umivaonika i postavi ih pet zdesna, pet slijeva da se u njima pere; u njima su prali što je trebalo za paljenice; more je bilo namijenjeno svećenicima da se umivaju u njemu.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 4, 7, 'Napravi deset zlatnih svijećnjaka prema propisu i stavi ih u Hekal, pet s desne strane, pet s lijeve.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 4, 8, 'Onda napravi deset stolova i postavi ih u Hekalu, pet zdesna, a pet slijeva. Napravi stotinu zlatnih kotlića.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 4, 9, 'Onda načini trijem svećenički veliko dvorište s vratima koja prevuče tučem.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 4, 10, 'More stavi s desne strane prema jugoistoku.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 4, 11, 'Huram načini lonce, lopate i kotliće. Dovrši sav posao što ga je obavljao kralju Salomonu za Dom Božji:');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 4, 12, 'dva stupa; dvije glavice što su bile navrh stupova; dva opleta da prekriju dvije glavice što bijahu navrh stupova;');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 4, 13, 'četiri stotine mogranja za oba opleta; dva reda mogranja za svaki oplet da prekriju dvije glavice navrh stupova;');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 4, 14, 'deset podnožja i deset umivaonika na podnožjima;');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 4, 15, 'jedno more i dvanaest volova pod njim;');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 4, 16, 'lonce, lopate, viljuške i sav pribor za njih napravi od tuča Huram Abi kralju Salomonu za Dom Jahvin.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 4, 17, 'Kralj odredi da ih saliju u Jordanskoj ravnici, kod gaza Adame, između Sukota i Serede.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 4, 18, 'Salomon napravi tako mnogo tih predmeta da se nije mogla izmjeriti težina tuča.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 4, 19, 'Onda napravi sve predmete namijenjene Domu Božjemu: zlatni žrtvenik i stolove na kojima bjehu prineseni kruhovi,');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 4, 20, 'zlatne svijećnjake sa svjetiljkama od čistoga zlata što su se, po propisu, trebale paliti pred Debirom;');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 4, 21, 'cvjetove, svjetiljke i usekače od zlata; bilo je to čisto zlato;');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 4, 22, 'nožice, kotliće, mašice i kadionice od čistoga zlata; ulaz u Dom, nutarnja vrata - Svetinje nad svetinjama - i vrata Doma - Hekala - bila su zlatna.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 5, 1, 'Tako bi priveden kraju posao što ga Salomon obavi za Dom Jahvin. Salomon unese sve svete darove oca svoga Davida - srebro, zlato i sve posuđe - i stavi ih u riznicu Božjega Doma.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 5, 2, 'Tada Salomon sazva u Jeruzalem sve Izraelove starješine, knezove plemenske i glavare obiteljske, da se prenese Kovčeg saveza Jahvina iz Davidova grada, to jest sa Siona.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 5, 3, 'Svi se ljudi Izraelovi sabraše pred kraljem na blagdan što je u sedmom mjesecu.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 5, 4, 'Kad se sastadoše sve Izraelove starješine, leviti ponesoše Kovčeg');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 5, 5, 'i Šator sastanka sa svim posvećenim priborom što bješe u Šatoru; svećenici ih i leviti prenesoše.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 5, 6, 'Potom kralj Salomon i sva izraelska zajednica što se sabra k njemu žrtvovaše pred Kovčegom toliko ovaca i goveda da se ne mogahu ni prebrojiti ni procijeniti.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 5, 7, 'Svećenici donesoše Kovčeg saveza Jahvina na njegovo mjesto, u Debir Doma, to jest u Svetinju nad svetinjama, pod krila kerubinÄa.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 5, 8, 'Kerubini su imali raširena krila nad mjestom gdje stajaše Kovčeg i zaklanjahu Kovčeg i njegove motke.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 5, 9, 'Motke su bile tako dugačke da su im se krajevi vidjeli iz Svetišta nasuprot Debiru, ali se nisu vidjele izvana i ondje stoje do dana današnjega.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 5, 10, 'U Kovčegu nije bilo ništa, osim dviju ploča koje metnu Mojsije na Horebu, gdje Jahve sklopi Savez s Izraelcima pošto iziđoše iz Egipta.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 5, 11, 'Svi svećenici izađoše iz Svetišta, jer su se svi nazočni svećenici posvetili bez obzira na redove.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 5, 12, 'Svi levitski pjevači, Asaf, Heman, Jedutun sa sinovima i braćom, stajahu obučeni u bÓez, s cimbalima, harfama i citrama, istočno od žrtvenika, a s njima sto i dvadeset svećenika koji su trubili u trube.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 5, 13, 'I dok su trubili i pjevali složno kao jedan i jednoglasno hvalili i slavili Jahvu, podižući glas uz trube, cimbale i druga glazbala, hvaleći Jahvu \"jer je dobar i jer je vječna njegova ljubav\", oblak ispuni Dom Jahvin.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 5, 14, 'Svećenici ne mogoše od oblaka nastaviti službe: slava Jahvina ispuni Božji dom!');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 6, 1, 'Tada reče Salomon: \"Jahve odluči prebivati u tmastu oblaku,');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 6, 2, 'a ja ti sagradih uzvišen Dom da u njemu prebivaš zauvijek.\"');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 6, 3, 'I, okrenuvši se, kralj blagoslovi sav izraelski zbor, a sav je izraelski zbor stajao.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 6, 4, 'Reče on: \"Neka je blagoslovljen Jahve, Bog Izraelov, koji svojom rukom ispuni obećanje što ga na svoja usta dade ocu mome Davidu, rekavši:');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 6, 5, '\'Od dana kad izvedoh svoj narod iz egipatske zemlje nisam izabrao grada ni iz kojeg Izraelova plemena da se u njemu sagradi Dom gdje bi prebivalo moje Ime, niti sam izabrao ikoga da vlada nad mojim narodom izraelskim.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 6, 6, 'Ali sam izabrao Jeruzalem da u njemu obitava moje Ime i odabrao Davida da zapovijeda mojem narodu izraelskom.\'');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 6, 7, 'Otac mi David naumi podići Dom Imenu Jahve, Boga Izraelova,');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 6, 8, 'ali mu Jahve reče: \'Naumio si podići Dom Imenu mojem, i dobro učini,');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 6, 9, 'ali nećeš ti podići toga Doma, nego tvoj sin koji izađe iz tvoga krila; on će podići Dom Imenu mojem.\'');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 6, 10, 'Jahve ispuni obećanje svoje: naslijedio sam oca Davida i sjeo na prijestolje Izraelovo, kako obeća Jahve, podigao Dom Imenu Jahve, Boga Izraelova,');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 6, 11, 'i namjestio Kovčeg u kojem je Savez što ga Jahve sklopi sa sinovima Izraelovim.\"');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 6, 12, 'Tada Salomon stupi, u nazočnosti svega zbora Izraelova, pred žrtvenik Jahvin i raširi ruke.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 6, 13, 'Salomon je, naime, bio napravio tučano podnožje, dugo pet lakata i široko pet lakata, a visoko tri lakta, i stavio ga nasred predvorja; stavši na nj, kleknuo je pred svim zborom Izraelovim i, raširivši ruke k nebu,');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 6, 14, 'rekao: \"Jahve, Bože Izraelov! Nijedan ti bog nije sličan ni na nebesima ni na zemlji, tebi koji držiš Savez i ljubav svojim slugama što kroče pred tobom sa svim svojim srcem.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 6, 15, 'Sluzi svome Davidu, mojem ocu, ispunio si što si mu obećao. Što si obećao na svoja usta, ispunio si svojom rukom upravo danas.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 6, 16, 'Jahve, Bože Izraelov, sada ispuni svome sluzi, ocu mome Davidu, što si mu obećao kad si rekao: \'Neće ti preda mnom nestati nasljednika koji bi sjedio na izraelskom prijestolju, samo ako tvoji sinovi budu čuvali svoje putove hodeći po mojem zakonu kako si ti hodio preda mnom.\'');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 6, 17, 'Jahve, Bože Izraelov, neka se sada dakle ispuni obećanje koje si dao svome sluzi Davidu!');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 6, 18, 'Ali zar će Bog doista boraviti s ljudima na zemlji? TÓa nebesa ni nebesa nad nebesima ne mogu ga obuhvatiti, a kamoli ovaj Dom što sam ga sagradio!');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 6, 19, 'Pomno počuj molitvu i vapaj svoga sluge, Jahve, Bože moj, te usliši prošnju i molitvu što je tvoj sluga k tebi upućuje!');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 6, 20, 'Neka tvoje oči obdan i obnoć budu otvorene nad ovim Domom, nad ovim mjestom za koje reče da ćeš u nj smjestiti svoje Ime. Usliši molitvu koju će sluga tvoj izmoliti na ovome mjestu.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 6, 21, 'I usliši molitvu sluge svoga i naroda svojega izraelskog koju bude upravljao prema ovome mjestu. Usliši s mjesta gdje prebivaš, s nebesa, usliši i oprosti!');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 6, 22, 'Ako tko zgriješi protiv bližnjega i bude mu naređeno da se zakune i zakletva dođe pred tvoj žrtvenik u ovom Domu,');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 6, 23, 'ti je čuj s neba, postupaj i sudi svojim slugama, osudi krivca okrećući njegova nedjela na njegovu glavu, a nevina oslobodi postupajući s njime po nevinosti njegovoj.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 6, 24, 'Ako narod tvoj poraze neprijatelji jer se ogriješio o tebe, ali se ipak k tebi obrati i proslavi Ime tvoje i u ovom se Domu pomoli i zavapije k tebi,');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 6, 25, 'onda ti čuj to s neba, oprosti grijehe svojem narodu izraelskom i dovedi ga natrag u zemlju koju si dao njima i njihovim očevima.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 6, 26, 'Ako se zatvori nebo i ne padne kiša jer su se ogriješili o tebe, pa ti se pomole na ovom mjestu i proslave Ime tvoje i obrate se od svojega grijeha kad ih ti poniziš,');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 6, 27, 'tada čuj s neba i oprosti grijeh svojim slugama i svojem izraelskom narodu, pokazujući mu valjan put kojim će ići, i pusti kišu na zemlju koju si narodu svojem dao u baštinu.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 6, 28, 'Kad u zemlji zavlada glad, kuga, snijet i rđa, kad navale skakavci i gusjenice, kad neprijatelj ovoga naroda pritisne koja od njegovih vrata ili kad udari kakva druga nevolja ili boleština,');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 6, 29, 'počuj svaku molitvu, svaki vapaj od kojega god čovjeka ili od cijeloga tvoga naroda izraelskog; ako svaki osjeti bol u srcu i raširi ruke k ovom Domu,');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 6, 30, 'usliši im molitvu i vapaj njihov u nebu gdje boraviš i oprosti i daj svakomu po njegovim putovima, jer ti poznaješ srce njegovo; jer ti jedini prozireš srca ljudi');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 6, 31, 'da te se boje idući tvojim putovima dokle god žive na zemlji što je ti dade našim očevima.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 6, 32, 'Pa i tuđinca, koji nije od tvojega naroda izraelskog, nego je stigao iz daleke zemlje radi veličine tvoga Imena i radi tvoje snažne ruke i podignute mišice, ako dođe i pomoli se u ovom Domu,');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 6, 33, 'usliši s neba, gdje prebivaš, usliši sve vapaje njegove da bi svi zemaljski narodi upoznali Ime tvoje i bojali te se kao narod tvoj izraelski i da znaju da je tvoje Ime prizvano nad ovaj Dom koji sam sagradio.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 6, 34, 'Kad narod tvoj krene na neprijatelja putem kojim ga ti uputiš i pomoli se tebi, okrenut gradu što si ga izabrao i prema Domu koji sam podigao tvome Imenu,');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 6, 35, 'usliši mu s neba molitvu i prošnju i učini mu pravdu.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 6, 36, 'Kad ti sagriješe, jer nema čovjeka koji ne griješi, a ti ih, rasrdiv se na njih, predaš neprijateljima da ih zarobe i odvedu kao roblje u daleku ili blizu zemlju,');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 6, 37, 'pa ako se pokaju srcem u zemlji u koju budu dovedeni te se obrate i počnu te moliti za milost u zemlji svojih osvajača govoreći: \'Zgriješili smo\'');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 6, 38, 'i tako se obrate tebi svim srcem i svom dušom u zemlji svoga ropstva u koju budu dovedeni kao roblje, i pomole se okrenuti k zemlji što je ti dade njihovim očevima i prema gradu koji si odabrao i prema Domu što sam ga podigao tvom Imenu,');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 6, 39, 'usliši s neba, gdje prebivaš, njihovu molbu i njihove prošnje, učini im pravdu i oprosti svome narodu što ti je zgriješio.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 6, 40, 'Sada, Bože moj, neka tvoje oči budu otvorene i tvoje uši pažljive na molitve na ovom mjestu!');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 6, 41, 'Pa sada ustani, o Bože Jahve, pođi k svojem počivalištu, ti i Kovčeg tvoje snage; neka se obuku u spasenje tvoji svećenici, o Bože Jahve, i vjerni tvoji neka se raduju u sreći!');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 6, 42, 'Bože Jahve, ne odvrati lica od svog pomazanika, spomeni se milostÄi što ih dade sluzi svome Davidu!\"');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 7, 1, 'Kad Salomon dovrši molitvu, spusti se oganj s neba i spali paljenicu i klanice i slava Jahvina ispuni Dom.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 7, 2, 'Svećenici ne mogoše ući, jer slava Jahvina bješe ispunila Dom Jahvin.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 7, 3, 'Svi sinovi Izraelovi, videći gdje se oganj sa slavom Jahvinom spustio na Dom, padoše ničice k zemlji do kamenog poda; pokloniv se, počeše slaviti Jahvu \"jer je dobar i jer je vječna njegova ljubav\".');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 7, 4, 'Potom kralj i čitav narod stadoše žrtvovati žrtve pred Jahvom.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 7, 5, 'Kralj Salomon prinese za žrtvu dvadeset i dvije tisuće goveda, sto i dvadeset tisuća ovaca; i tako posvetiše Dom Jahvin i kralj i sav narod.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 7, 6, 'Dok su svećenici stajali na dužnostima, leviti su na glazbalima za Jahvine pjesme, što ih učini kralj David, slavili Jahvu \"jer je vječna njegova ljubav\". Time je David preko njihovih ruku hvalio Jahvu. Pred njima su svećenici trubili u trube, dok su Izraelci stajali.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 7, 7, 'Salomon je posvetio i sredinu predvorja koje je pred Jahvinim Domom, jer je ondje prinio paljenice i pretilinu od pričesnica, jer na tučani žrtvenik koji bijaše napravio Salomon nisu mogle stati paljenice ni prinosi ni pretilina.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 7, 8, 'U to je doba Salomon svetkovao blagdan sedam dana i sav Izrael s njime, vrlo velik zbor, od Ulaza u Hamat pa do Egipatskoga potoka.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 7, 9, 'A osmoga su dana svetkovali svečani zbor, jer su posvetu žrtveniku svetkovali sedam dana i blagdan sedam dana.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 7, 10, 'Dvadeset trećega dana sedmoga mjeseca posla ljude k njihovim šatorima i odoše vesela i zadovoljna srca zbog dobra koje je Jahve učinio Davidu i Salomonu i svem narodu izraelskom.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 7, 11, 'Tako je Salomon dovršio Dom Jahvin i kraljevski dvor i izveo sve što god bješe zasnovano da izvrši u Domu Jahvinu i u svojem dvoru.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 7, 12, 'Potom se Jahve ukaza Salomonu noću i reče mu: \"Uslišao sam tvoju molitvu i izabrao to mjesto da mi bude Dom žrtve.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 7, 13, 'Ako zatvorim nebo da ne bude dažda, ili zapovjedim skakavcima da popasu zemlju, ili pustim kugu na svoj narod,');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 7, 14, 'i ponizi se moj narod na koji je prizvano Ime moje i pomoli se i potraži lice moje i okani se zlih putova, ja ću ga tada uslišati s neba i oprostiti mu grijeh i izliječit ću mu zemlju.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 7, 15, 'Moje će oči biti otvorene i moje uši pažljive na molitvu s ovoga mjesta.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 7, 16, 'Sada sam, dakle, izabrao i posvetio ovaj Dom da ovdje bude Ime moje zauvijek i ovdje će sve dane biti moje oči i moje srce.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 7, 17, 'A ti, budeš li išao preda mnom kako ti je išao otac David, vršeći sve što sam ti zapovjedio i držeći se mojih uredaba i zakona,');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 7, 18, 'uzdržat ću tvoje kraljevsko prijestolje kako sam obećao tvome ocu Davidu govoreći: \'Neće ti ponestati nasljednika koji bi vladao u Izraelu.\'');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 7, 19, 'Ali ako me ostavite i napustite uredbe i zapovijedi koje sam vam dao te otiđete i počnete služiti tuđim bogovima i klanjati im se,');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 7, 20, 'istjerat ću Izraelce iz svoje zemlje koju sam im dao i odbacit ću od sebe ovaj Dom koji sam posvetio svojem Imenu i učinit ću od njega priču i sramotu među svim narodima.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 7, 21, 'Tko god prođe mimo ovaj Dom koji bijaše preslavan zaprepastit će se od užasa i pitati: \'Zašto je Jahve tako učinio s ovom zemljom i s ovim Domom?\'');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 7, 22, 'I odgovorit će mu se: \'Ostavili su Jahvu, Boga svojih otaca, koji ih je izveo iz Egipta, i okrenuli se tuđinskim bogovima, i klanjali im se, i služili im, i zato je Jahve pustio na njih sve ovo zlo.\'\"');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 8, 1, 'A kad je prošlo dvadeset godina, za koliko je vremena Salomon podigao Jahvin Dom i svoj dvor,');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 8, 2, 'posagradio je Salomon gradove, koje je dao Salomonu Hiram, i naselio ondje Izraelove sinove.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 8, 3, 'Potom otiđe Salomon na Sopski Hamat i osvoji ga.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 8, 4, 'Sagradi Tadmor u pustinji i svakojaka mjesta za skladišta u Hamatu.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 8, 5, 'Sagradi i Gornji Bet Horon i Donji Bet Horon, tvrde gradove sa zidovima, vratima i prijevornicama;');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 8, 6, 'i Baalat, i sve gradove u kojima je imao skladišta, sve gradove za bojna kola i gradove za konjanike i što je god Salomon zaželio da gradi u Jeruzalemu i na Libanonu i po svoj zemlji svojega kraljevstva.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 8, 7, 'Svim preostalim Hetitima, Amorejcima, Perižanima, Hivijcima i Jebusejcima, koji nisu bili Izraelci,');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 8, 8, 'sinovima njihovim koji ostadoše iza njih u zemlji i koje Izraelci nisu zatrli - Salomon nametnu tlaku do današnjega dana.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 8, 9, 'Sinove Izraelove nije Salomon pretvarao u robove za posao, nego su bili vojnici, zapovjednici njegovih štitonoša i zapovjednici bojnih kola i konjice.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 8, 10, 'Bili su poglavari nad upravnicima, kojih je kralj Salomon imao dvjesta i pedeset, i upravljali su narodom.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 8, 11, 'Salomon preseli i faraonovu kćer iz Davidova grada u kuću koju joj bijaše sagradio, jer je mislio: \"Neće moja žena živjeti u dvoru izraelskoga kralja Davida, jer je svet otkako je u nj došao Kovčeg Jahvin.\"');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 8, 12, 'Tada Salomon poče prinositi paljenice Jahvi na Jahvinu žrtveniku što ga bijaše sagradio pred trijemom,');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 8, 13, 'i to koliko je trebalo iz dana u dan da prinese po Mojsijevoj zapovijedi, u subote, i na mlađake, i na blagdane tri puta u godini, na Blagdan beskvasnih kruhova, i na Blagdan sedmica, i na Blagdan sjenica.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 8, 14, 'Postavio je, po uredbi oca Davida, svećeničke redove po njihovoj službi i levitske po njihovim dužnostima da pjevaju hvale i da služe pred svećenicima, koliko treba iz dana u dan, i vratare po njihovim redovima na svakim vratima, jer je takva bila zapovijed Božjega čovjeka Davida.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 8, 15, 'Nisu odstupili od kraljeve zapovijedi za svećenike i levite ni u čemu, ni za riznice.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 8, 16, 'Tako se svršio sav Salomonov posao od dana kad je bio zasnovan Dom Jahvin pa dokle ga god nije dovršio. Tako bijaše dovršen Dom Jahvin.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 8, 17, 'Tada je Salomon otišao u Esjon-Geber i u Elat na morskoj obali u zemlji edomskoj.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 8, 18, 'A Hiram mu je poslao po slugama lađe i mornare vične moru te su otišli sa Salomonovim slugama u Ofir; uzeše odande četiri stotine i pedeset talenata zlata i donesoše ih kralju Salomonu.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 9, 1, 'Uto kraljica od Sabe ču glas o Salomonu; hoteći iskušati Salomona zagonetkama, dođe u Jeruzalem s mnogobrojnom pratnjom i s devama koje su nosile miomirise, mnogo zlata i dragulja. Došavši k Salomonu, porazgovori se s njim o svemu što joj bijaše na srcu.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 9, 2, 'Salomon joj odgovori na sva pitanja; nije bilo Salomonu sakriveno ništa da joj ne bi umio objasniti.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 9, 3, 'Kad kraljica od Sabe vidje njegovu mudrost, dvor koji bijaše sagradio,');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 9, 4, 'jela na njegovu stolu, odaje njegove i dvorane, otmjenost njegove posluge i njihova odijela, i njegove peharnike i njihova odijela, i njegove paljenice koje je prinosio u Jahvinu domu, zastade joj dah.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 9, 5, 'Tada reče kralju: \"Istina je bila što sam u svojoj zemlji čula o tebi i o tvojoj mudrosti.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 9, 6, 'Ali nisam htjela vjerovati što se pripovijeda dokle god nisam došla i vidjela na svoje oči; i doista, ni pola mi nije bilo rečeno o tvojoj velikoj mudrosti; nadvisio si glas koji sam slušala.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 9, 7, 'Blago tvojim ljudima i tvojim slugama koji stoje pred tobom i slušaju tvoju mudrost!');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 9, 8, 'Neka je blagoslovljen Jahve, tvoj Bog, komu si tako omilio da te postavio na svoje prijestolje da kraljuješ umjesto Jahve, svojega Boga, jer Bog tvoj ljubi Izraela da bi ga održao dovijeka; i zato je postavio tebe za kralja da činiš pravo i pravicu.\"');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 9, 9, 'Dala je tada kralju sto i dvadeset zlatnih talenata i mnogo miomirisa i dragulja. Nikad više nije bilo takvih miomirisa kakve je kraljica od Sabe dala kralju Salomonu.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 9, 10, 'Hiramove sluge, koje su sa Salomonovim slugama donosile zlata iz Ofira, dovezle su također sandalovine i dragulja.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 9, 11, 'Kralj je napravio i citre i harfe za pjevače: nikad se prije nisu vidjele takve stvari u zemlji judejskoj.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 9, 12, 'Kralj Salomon dade kraljici od Sabe što je zaželjela i zatražila, izuzev ono što je sama donijela kralju. Potom ona krenu i sa slugama ode u svoju zemlju.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 9, 13, 'Zlato što je dolazilo Salomonu svake godine bilo je teško šest stotina šezdeset i šest zlatnih talenata,');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 9, 14, 'osim onoga što je dolazilo od trgovaca i putujućih prodavača. I svi su arapski kraljevi i zemaljski upravitelji Salomonu donosili zlato i srebro.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 9, 15, 'Kralj Salomon načini dvjesta štitova od kovanoga zlata; za svaki je štit upotrijebio šest stotina šekela kovanoga zlata;');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 9, 16, 'i načini trista štitića od kovanoga zlata; za svaki je štitić utrošio trista zlatnih šekela. Kralj ih je pohranio u kuću zvanu Libanonska šuma.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 9, 17, 'Kralj je napravio i veliko prijestolje od bjelokosti i obložio ga čistim zlatom.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 9, 18, 'Prijestolje je imalo šest stepenica i zlatno podnožje sastavljeno s prijestoljem, i ručice s obiju strana prijestolja, a kraj ručica stajala dva lava.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 9, 19, 'Dvanaest je lavova stajalo s obiju strana onih šest stepenica. Takvo što nije bilo izrađeno ni u jednom kraljevstvu.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 9, 20, 'Sve posude iz kojih je pio kralj Salomon bijahu zlatne i sve posuđe u kući zvanoj Libanonska šuma bijaše od suhoga zlata; srebro se smatralo bezvrijednim u Salomonovo vrijeme.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 9, 21, 'Kraljeve su lađe išle u Taršiš s Hiramovim slugama; svake treće godine vraćale su se i dolazile taršiške lađe donoseći zlato i srebro, slonovu kost, majmune i paune.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 9, 22, 'Tako je kralj Salomon natkrilio sve zemaljske kraljeve bogatstvom i mudrošću.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 9, 23, 'Svi su zemaljski kraljevi željeli vidjeti Salomona i čuti mudrost koju mu je Bog ulio u srce.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 9, 24, 'Svatko mu je donosio dar, srebrno i zlatno posuđe, haljine, oružje i miomirise, konje i mazge, iz godine u godinu.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 9, 25, 'Salomon je imao četiri tisuće konjskih jasala i bojnih kola i dvanaest tisuća konjanika, koje je rasporedio po gradovima bojnih kola i kod kralja u Jeruzalemu.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 9, 26, 'Vladao je nad svim kraljevima od Rijeke do zemlje filistejske i do egipatske međe.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 9, 27, 'Kralj je učinio da u Jeruzalemu bude srebra kao kamenja, a cedrova kao divljih smokava što rastu u Judejskoj nizini.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 9, 28, 'Salomon je uvozio konje iz Musrija i iz svih zemalja.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 9, 29, 'Ostala djela Salomonova, od prvih do posljednjih, zapisana su u povijesti proroka Natana, u proročkoj knjizi Šilonjanina Ahije i u proročkoj besjedi vidioca Adona o Nebatovu sinu Jeroboamu.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 9, 30, 'Salomon je vladao u Jeruzalemu nad svim Izraelom četrdeset godina.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 9, 31, 'Potom je počinuo kod otaca i sahranili su ga u gradu oca mu Davida, a na njegovo se mjesto zakraljio sin mu Roboam.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 10, 1, 'Tada Roboam ode u Šekem, jer su u Šekem došli svi Izraelci da ga zakralje.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 10, 2, 'Čim to ču Nebatov sin Jeroboam - koji je bio u Egiptu kamo bijaše pobjegao pred kraljem Salomonom - vrati se iz Egipta,');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 10, 3, 'jer bijahu poslali po nj i dozvali ga. Kad dođoše Jeroboam i sav zbor Izraelov, rekoše Roboamu:');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 10, 4, '\"Tvoj nam je otac nametnuo težak jaram, ti nam sada olakšaj tešku službu svoga oca i teški jaram koji metnu na nas, pa ćemo ti služiti.\"');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 10, 5, 'On im odgovori: \"Za tri dana dođite opet k meni.\" I narod ode.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 10, 6, 'Tada se kralj Roboam posavjetova sa starcima koji su služili njegovu ocu Salomonu dok je bio živ i upita ih: \"Što savjetujete da odgovorim ovome narodu?\"');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 10, 7, 'A oni mu odgovoriše: \"Ako udovoljiš tim ljudima, budeš im blagonaklon i odgovoriš im lijepim riječima, oni će ti uvijek biti sluge.\"');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 10, 8, 'Ali on odbaci savjet što mu ga dadoše starci i posavjetova se s mladićima koji su odrasli s njim i bili mu u službi.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 10, 9, 'Upita ih: \"Što savjetujete da odgovorim ovomu narodu koji mi reče: \'Olakšaj jaram što nam ga nametnu tvoj otac!\'\"');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 10, 10, 'Odgovoriše mu mladići koji bijahu s njim odrasli: \"Narodu koji ti je rekao \'Tvoj nam je otac nametnuo jaram, a ti nam ga olakšaj\', odvrati ovako: \'Moj je mali prst deblji od bedara moga oca!');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 10, 11, 'Dakle, moj vam je otac nametnuo težak jaram, a ja ću još otežati vaš jaram; moj vas je otac šibao bičevima, a ja ću vas šibati bičevima sa željeznim štipavcima.\'\"');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 10, 12, 'Trećega dana dođe Jeroboam i sav narod k Roboamu, jer im kralj bijaše naredio: \"Vratite se k meni trećega dana.\"');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 10, 13, 'Kralj im oštro odgovori; odbacivši savjet starijih,');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 10, 14, 'odvrati po savjetu mladih: \"Moj je otac otežao vaš jaram, a ja ću još dometnuti na nj; moj vas je otac šibao bičevima, a ja ću vas šibati bičevima sa željeznim štipavcima.\"');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 10, 15, 'Kralj, dakle, ne htjede poslušati naroda, jer tako upriliči Bog da se ispuni riječ što je preko Šilonjanina Ahije kaza Nabatovu sinu Jeroboamu.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 10, 16, 'Kad Izraelci vidješe gdje se kralj oglušio, odgovori mu narod: \"Kakav dio mi imamo s Davidom? Mi nemamo baštine s Jišajevim sinom! U šatore, Izraele! Sad se, Davide, brini za svoj dom!\" I sav Izrael ode pod svoje šatore.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 10, 17, 'Roboam zavlada samo nad Izraelovim sinovima koji su živjeli po judejskim gradovima.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 10, 18, 'Potom kralj Roboam posla Adorama, nadstojnika za tlaku, ali ga Izraelci kamenovaše i on umrije; a kralj se Roboam brže-bolje pope na kola te pobježe u Jeruzalem.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 10, 19, 'Tako se Izrael odijelio od doma Davidova sve do danas.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 11, 1, 'Došavši u Jeruzalem, skupi sav dom Judin i Benjaminov, sto i osamdeset tisuća vrsnih ratnika, da udare na Izraela i da Roboamu vrate kraljevstvo.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 11, 2, 'Ali dođe Jahvina riječ Božjem čovjeku Šemaji:');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 11, 3, '\"Kaži Salomonovu sinu Roboamu, judejskomu kralju, i svim Izraelcima u Judinu i Benjaminovu plemenu:');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 11, 4, 'Ovako veli Jahve: \'Ne idite se tući s braćom! Neka se svatko vrati svojoj kući, jer je ovo poteklo od mene.\'\" I oni poslušaše riječ Jahvinu, vratiše se i ne udariše na Jeroboama.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 11, 5, 'Roboam, stolujući u Jeruzalemu, poče dizati tvrde gradove po Judeji.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 11, 6, 'Tako je sagradio Betlehem, Etam, Tekou,');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 11, 7, 'Bet Sur, Sokon, Adulam,');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 11, 8, 'Gat, Maresu, Zif,');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 11, 9, 'Adorajim, Lakiš, Azeku,');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 11, 10, 'Soru, Ajalon i Hebron, tvrde gradove u Judinu i Benjaminovu plemenu.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 11, 11, 'Utvrdivši gradove, postavi im zapovjednike i dovuče zalihe hrane, ulja i vina;');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 11, 12, 'u svaki pojedini grad stavi štitova i kopalja i utvrdi ih vrlo jako. Tako je on imao Judino i Benjaminovo pleme.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 11, 13, 'Svećenici i leviti, koji su bili po svem Izraelu, pristupiše k njemu iz svih krajeva.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 11, 14, 'Leviti ostaviše pašnjake i posjed te otiđoše u Judeju i Jeruzalem, jer ih je bio odbacio Jeroboam i njegovi sinovi da ne obavljaju svećeničku službu Jahvi,');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 11, 15, 'a postavio je svećenike za uzvišice, za jarce i za telad koju je napravio.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 11, 16, 'Za njima su iz svih izraelskih plemena dolazili u Jeruzalem da žrtvuju Jahvi, Bogu svojih otaca, oni koji su srcem tražili Jahvu, Boga Izraelova.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 11, 17, 'Tako su utvrdili judejsko kraljevstvo i osokolili Salomonova sina Roboama za tri godine, jer su tri godine živjeli poput Davida i Salomona.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 11, 18, 'Roboam je sebi uzeo za žemu Mahalatu, kćer Davidova sina Jerimota, i Abihajilu, kćer Jišajeva sina Eliaba,');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 11, 19, 'koja mu rodi sinove: Jeuša, Šemarju i Zahama.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 11, 20, 'A poslije nje oženio se Abšalomovom kćerju Maakom, koja mu rodi Abiju, Etaja, Zizu i Šelomita.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 11, 21, 'Roboam je ljubio Abšalomovu kćer Maaku više od svih svojih žena i inoča, iako je uzeo osamnaest žena i šezdeset inoča i rodio dvadeset i osam sinova i šezdeset kćeri.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 11, 22, 'I Roboam postavi Maakina sina Abiju za poglavara i kneza nad njegovom braćom, jer ga je naumio postaviti za kralja.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 11, 23, 'I, mudro radeći, razmjesti sinove po svim judejskim i Benjaminovim krajevima, po svim tvrdim gradovima, davši im hrane izobila i poženivši ih sa mnogo žena.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 12, 1, 'Kad je Roboam utvrdio kraljevstvo i ojačao, napustio je Jahvin zakon i on i sav Izrael s njim.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 12, 2, 'Ali pete godine Roboamova kraljevanja navali egipatski kralj Šišak na Jeruzalem, koji se bijaše iznevjerio Jahvi.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 12, 3, 'Došao je sa tisuću i dvjesta bojnih kola i sa šezdeset tisuća konjanika, a narodu koji je došao s njim iz Egipta - Libijcima, Sukijcima i Etiopljanima - nije bilo broja.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 12, 4, 'Osvojivši tvrde judejske gradove, dopro je do Jeruzalema.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 12, 5, 'Tada dođe prorok Šemaja k Roboamu i judejskim knezovima, koji se bijahu skupili u Jeruzalemu bježeći od Šišaka, i reče im: \"Ovako veli Jahve: \'Vi ste ostavili mene, pa i ja ostavljam vas u ruke Šišaku.\'\"');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 12, 6, 'Tada se poniziše izraelski knezovi i kralj i rekoše: \"Pravedan je Jahve!\"');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 12, 7, 'Kad ih Jahve vidje gdje se poniziše, dođe njegova riječ Šemaji: \"Ponizili su se; neću ih uništiti, nego ću im uskoro dati spasenje te se moja srdžba neće oboriti na Jeruzalem preko Šišaka.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 12, 8, 'Bit će mu sluge, da vide što znači služiti meni, a što zemaljskim kraljevstvima.\"');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 12, 9, 'Tako egipatski kralj Šišak navali na Jeruzalem, opljačka blago iz Doma Jahvina i riznicu kraljeva dvora; sve je uzeo; uze i zlatne štitove što ih bijaše napravio Salomon.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 12, 10, 'Namjesto njih kralj Roboam napravi tučane štitove i povjeri ih zapovjednicima straže koja je čuvala vrata kraljevskoga dvora.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 12, 11, 'Kad je god kralj išao u Dom Jahvin, stražari su ih uzimali, a poslije ih vraćali u stražaru.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 12, 12, 'Kad se, dakle, ponizio, odvratio se od njega Jahvin gnjev te ga nije sasvim uništio, jer i u Judeji bijaše dobra.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 12, 13, 'Potom se kralj Roboam utvrdi u Jeruzalemu i stade kraljevati. Roboamu je bila četrdeset i jedna godina kad se zakraljio, a sedamnaest je godina kraljevao u Jeruzalemu, u gradu koji Jahve izabra između svih izraelskih plemena da ondje postavi Ime svoje. Majka mu se zvala Naama, a bila je Amonka.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 12, 14, 'Činio je zlo, jer nije pregnuo srcem da traži Jahvu.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 12, 15, 'Roboamova prva i posljednja djela - i ratovi koji su se neprestano vodili između Roboama i Jeroboama - zapisani su u povijesti proroka Šemaje i u plemenskom popisu vidioca Adona.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 12, 16, 'Potom Roboam počinu sa svojim ocima i bi sahranjen u Davidovu gradu; na njegovo se mjesto zakraljio sin mu Abija.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 13, 1, 'Osamnaeste godine Jeroboamova kraljevanja zakralji se Abija nad Judejom.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 13, 2, 'Tri je godine kraljevao u Jeruzalemu. Materi mu je bilo ime Mikaja, Urielova kći iz Gabe. Tada izbi rat između Abije i Jeroboama.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 13, 3, 'Abija je izašao u boj s hrabrim ratnicima, sa četiri stotine tisuća izabranih junaka; Jeroboam je svrstao u bojni red protiv njega osam stotina tisuća ljudi, sve biranih junaka.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 13, 4, 'Abija je stao na vrh Semarajimske gore u Efrajimovu gorju i rekao: \"Čujte me, Jeroboame i sav Izraele!');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 13, 5, 'Ne znate li da je Jahve, Bog Izraelov, predao Davidu kraljevstvo nad Izraelom zauvijek, njemu i njegovim sinovima, osoljenim savezom?');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 13, 6, 'Ali se podigao Nebatov sin Jeroboam, sluga Davidova sina Salomona, i pobunio se protiv gospodara.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 13, 7, 'Skupili su se oko njega ljudi praznovi i nevaljalci i stali prkositi Salomonovu sinu Roboamu, koji je bio mlad i strašljiva srca te se nije umio hrabro braniti od njih.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 13, 8, 'Pa sada mislite da se možete oprijeti Jahvinu kraljevstvu što je u ruci Davidovih sinova jer vas je veliko mnoštvo i imate kod sebe zlatnu telad koju vam je napravio Jeroboam da vam budu bogovi.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 13, 9, 'Otjerali ste Jahvine svećenike, Aronove sinove i levite, i postavili sebi svećenike kao drugi zemaljski narodi. Tko je god došao s juncem i sa sedam ovnova, postao je svećenik vašim ništavim bogovima.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 13, 10, 'Nama je Bog Jahve, nismo ga ostavili, a svećenici koji služe Jahvi jesu Aronovi sinovi i leviti u svojem poslu.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 13, 11, 'Pale Jahvi na kad paljenice svakoga jutra i svake večeri s mirisnim kadom, postavljaju kruhove na čist stol i upaljuju svake večeri zlatan svijećnjak sa svijećama; jer mi držimo naredbu Jahve, svojega Boga, a vi ste ga ostavili.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 13, 12, 'Zato je, evo, nama na čelu Bog i njegovi svećenici s glasnim trubama da gromko trube protiv vas. Izraelovi sinovi, ne udarajte na Jahvu, Boga svojih otaca, jer nećete imati sreće!\"');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 13, 13, 'Ali Jeroboam zavede zasjedu da im dođe za leđa; tako su Judejcima bili jedni sprijeda, a zasjeda straga.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 13, 14, 'Kad se Judejci obazreše, a ono, gle, boj im bješe sprijeda i otraga. Tada zavapiše k Jahvi, a svećenici stadoše trubiti u trube.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 13, 15, 'Uto Judejci snažno povikaše, a kad su počeli vikati, Bog razbi Jeroboama i sav Izrael pred Abijom i Judejcima.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 13, 16, 'Izraelovi sinovi pobjegoše pred Judejcima i Bog ih predade njima u ruke.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 13, 17, 'Abija je s narodom učinio velik pokolj među njima te je od Izraela palo pobijenih pet stotina tisuća izabranih ljudi.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 13, 18, 'Tako su sinovi Izraelovi bili poniženi u to vrijeme, a Judini su sinovi ojačali, jer su se oslonili na Jahvu, Boga svojih otaca.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 13, 19, 'Abija je potjerao Jeroboama i osvojio od njega gradove Betel sa selima, Ješanu sa selima i Efron sa selima.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 13, 20, 'Jeroboam se više nije oporavio za Abijina života; Jahve ga je udario tako da je umro.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 13, 21, 'Abija se utvrdio i uzeo sebi četrnaest žena te je rodio dvadeset i dva sina i šesnaest kćeri.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 13, 22, 'A ostali Abijini doživljaji i njegovi pothvati i besjede zapisani su u tumačenju proroka Adona.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 13, 23, 'Potom Abija počinu kraj svojih otaca. Sahraniše ga u Davidovu gradu; na njegovo se mjesto zakralji sin mu Asa. Za njegovih je dana zemlja bila mirna deset godina.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 14, 1, 'Asa je činio što je dobro i pravo u očima Jahve, njegova Boga.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 14, 2, 'Uklonio je tuđinske žrtvenike i uzvišice, polomio stupove i razbio ašere.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 14, 3, 'Naredio je Judejcima da traže Jahvu, Boga svojih otaca, da se drže zakona i zapovijedi.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 14, 4, 'Uklonio je iz svih judejskih gradova uzvišice i sunčane stupove, a kraljevstvo je bilo mirno za njegova vremena.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 14, 5, 'Sagradio je tvrde gradove u Judeji, jer je zemlja bila mirna. Nitko se nije zaratio na nj onih godina, jer mu je Jahve dao mir.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 14, 6, 'Zato je Asa rekao Judejcima: \"Da pogradimo ove gradove i da ih opašemo zidom i kulama, vratima i prijevornicama; još je zemlja pred nama naša, jer smo tražili Jahvu, svoga Boga; tražili smo ga, i on nam je dao mir odasvud uokolo!\" Tako su gradili i bili sretni.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 14, 7, 'Asa je imao vojske trista tisuća ljudi između Judejaca koji su nosili štit i koplje, a od Benjaminova plemena dvjesta i osamdeset tisuća koji su nosili štit i zapinjali luk. Svi su bili hrabri junaci.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 14, 8, 'Izašao je na njih Etiopljanin Zerah sa tisuću tisuća vojnika i tri stotine bojnih kola i došao do Mareše.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 14, 9, 'Asa je izašao preda nj; svrstali su se u bojni red u Sefatskoj dolini kod Mareše.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 14, 10, 'Asa zavapi k Jahvi, Bogu svome: \"O Jahve, tebi je ništa pomoći silnome ili nejakome! Pomozi nam, o Jahve, Bože naš, jer se na te oslanjamo i u tvoje smo ime izišli na ovo mnoštvo! Jahve, ti si Bog naš, ne daj snažnu čovjeku protiv sebe!\"');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 14, 11, 'Jahve razbi Etiopljane pred Asom i pred Judejcima te Etiopljani pobjegoše.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 14, 12, 'Asa ih je s narodom koji bijaše s njim potjerao sve do Gerara. Etiopljani su popadali, tako da nijedan nije ostao živ jer ih je satro Jahve i njegove čete; i one su odnijele vrlo velik plijen.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 14, 13, 'Osvojile su sve gradove oko Gerara jer je Jahvin strah došao na njih; oplijenile su sve te gradove, jer je u njima bilo mnogo plijena.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 14, 14, 'Poharale su i šatore za stoku i zaplijenile mnoštvo sitne stoke i deva; a onda su se vratile u Jeruzalem.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 15, 1, 'Tada duh Božji dođe na Odedova sina Azarju.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 15, 2, 'On je izišao pred Asu i rekao mu: \"Čujte me, Asa i sve Judino i Benjaminovo pleme! Jahve je s vama jer ste vi s njime; i ako ga budete tražili, naći ćete ga; ako li ga ostavite, i on će ostaviti vas.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 15, 3, 'Dugo su Izraelci bili bez pravoga Boga i bez svećenika-učitelja i bez Zakona.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 15, 4, 'Kad su se u nevolji obratili Jahvi, Bogu Izraelovu, i stali ga tražiti, našli su ga.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 15, 5, 'U ona vremena nitko nije mogao na miru ni izlaziti ni dolaziti, jer su veliki nemiri vladali među svim zemaljskim stanovnicima.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 15, 6, 'Udarao je narod na narod, grad na grad, jer ih je Jahve smeo svakojakom nevoljom.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 15, 7, 'Ali vi budite hrabri i neka vam ne klonu ruke, jer ima nagrada za vaša djela.\"');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 15, 8, 'Čuvši te riječi i proročku besjedu proroka Odeda, Asa se ohrabri i ukloni idolske gadove iz cijele Judine i Benjaminove zemlje i iz gradova koje je bio osvojio u Efrajimovoj gori. Obnovio je i Jahvin žrtvenik koji je bio pred Jahvinim trijemom.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 15, 9, 'Onda je skupio sve Judino i Benjaminovo pleme i došljake koji su bili kod njih od Efrajimova, Manašeova i Šimunova plemena, jer ih je mnogo prebjeglo k njemu od Izraelaca kad su vidjeli da je s njim Jahve, njegov Bog.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 15, 10, 'I skupili su se u Jeruzalemu trećega mjeseca petnaeste godine Asina kraljevanja.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 15, 11, 'Onoga su dana prinijeli Jahvi žrtve od plijena koji su dognali, sedam stotina goveda i sedam tisuća sitne stoke.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 15, 12, 'Zavjetovaše se da će tražiti Jahvu, Boga svojih otaca, svim srcem i svom dušom.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 15, 13, 'A tko god ne bi tražio Jahvu, Izraelova Boga, da se pogubi, bio malen ili velik, čovjek ili žena.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 15, 14, 'Zakleli su se Jahvi iza glasa i uz gromki poklik, uz trube i rogove.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 15, 15, 'Svi su se Judejci radovali zbog te zakletve jer su se iz svega srca zakleli i od sve su ga svoje volje tražili i našli ga. Jahve im je dao mir odasvud uokolo.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 15, 16, 'I svoju mater Maaku ukloni kralj Asa s vlasti jer je bila načinila gada Ašeri. Asa je sasjekao njezina gada, satro ga i spalio u potoku Kidronu.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 15, 17, 'Ali uzvišice nisu bile uklonjene iz Izraela. Ipak je Asino srce bilo privrženo Jahvi svega njegova života.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 15, 18, 'Unio je u Dom Božji posvećene darove svoga oca i svoje: srebro i zlato i posuđe.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 15, 19, 'Nije bilo rata sve do trideset i pete godine Asina kraljevanja.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 16, 1, 'Trideset i šeste godine Asina kraljevanja navali izraelski kralj Baša na Judeju i stade utvrđivati Ramu da spriječi svako kretanje judejskom kralju Asi.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 16, 2, 'Asa tada uze srebra i zlata iz riznice Doma Jahvina i kraljevskoga dvora i posla aramejskome kralju Ben-Hadadu, koji je stolovao u Damasku, i poruči mu:');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 16, 3, '\"Neka bude savez između mene i tebe i između moga i tvoga oca; evo, šaljem ti na dar srebra i zlata, hajde, raskini savez s izraelskim kraljem Bašom da bi otišao od mene.\"');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 16, 4, 'Ben-Hadad posluša kralja Asu i posla svoje vojskovođe na izraelske gradove te oni pokoriše Ijon, Dan, Abel Majinu i sve Naftalijeve gradove-skladišta.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 16, 5, 'A kada to Baša dozna, presta utvrđivati Ramu i obustavi posao.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 16, 6, 'Tada kralj Asa sazva sve Judejce i oni odnesoše kamenje i drvo kojima je Baša utvrđivao Ramu, pa time utvrdiše Gebu i Mispu.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 16, 7, 'U to vrijeme dođe vidjelac Hanani k judejskom kralju Asi i reče mu: \"Budući da si se oslonio na aramejskoga kralja, a nisi se oslonio na Jahvu, Boga svoga, vojska aramejskoga kralja izmakla ti je iz ruke.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 16, 8, 'Nisu li Etiopljani i Libijci imali silne čete sa vrlo mnogo bojnih kola i konjanika? Pa kad si se oslonio na Jahvu, predao ti ih je u ruke.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 16, 9, 'Jer Jahve svojim očima gleda po svoj zemlji da bi se ohrabrili oni kojima je srce iskreno prema njemu. Ludo si u tome radio, zato će se od sada dizati ratovi na te.\"');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 16, 10, 'Tada se Asa razgnjevi na vidioca i baci ga u tamnicu, jer se razjario na nj. U to je vrijeme Asa potlačio i neke iz naroda.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 16, 11, 'I eto, Asina djela, od prvoga do posljednjeg, zapisana su u Knjizi o judejskim i izraelskim kraljevima.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 16, 12, 'Razbolio se trideset i devete godine kraljevanja, od nogu, te mu se bolest veoma pogoršala, ali ni u bolesti nije tražio Jahvu nego liječnike.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 16, 13, 'Tako Asa počinu sa svojim ocima i umrije četrdeset i prve godine svoga kraljevanja.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 16, 14, 'Sahranili su ga u grobnici koju bijaše iskopao sebi u Davidovu gradu i položili ga na odar što ga bijaše napunio miomirisima i mastima, zgotovljenima mastilačkom vještinom, i spalili mu ih vrlo mnogo.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 17, 1, 'Onda se na njegovo mjesto zakralji sin mu Jošafat; on pokaza svoju silu protiv Izraela.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 17, 2, 'Razmjestio je vojsku po svim utvrđenim judejskim gradovima i postavio namjesnike po judejskoj zemlji i po Efrajimovim gradovima, koje bijaše zauzeo otac mu Asa.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 17, 3, 'Jahve je bio s Jošafatom jer je hodio pravim putovima svoga oca Davida i nije tražio baala.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 17, 4, 'Tražio je Boga svojih otaca i hodio po njegovim zapovijedima, ne čineći kao Izraelovi sinovi.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 17, 5, 'Zato je Jahve utvrdio kraljevstvo u njegovoj ruci, pa su svi Judejci davali Jošafatu danak, tako da je stekao veliko bogatstvo i slavu.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 17, 6, 'Njegovo se srce hrabrilo na Jahvinim putovima, pa je uklonio još i uzvišice i ašere iz Judeje.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 17, 7, 'Treće godine kraljevanja posla knezove Ben-Hajila, Obadju, Zahariju, Netanela i Miheja da uče po judejskim gradovima.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 17, 8, 'I s njima levite: Šemaju, Netaniju, Zebadju, Asahela, Šemiramota, Jonatana, Adoniju, Tobiju i Tob Adoniju; a s njima svećenike Elišamu i Jorama.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 17, 9, 'Poučavali su po Judeji noseći sa sobom Knjigu Zakona Jahvina i obilazili sve judejske gradove učeći narod.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 17, 10, 'Jahvin je strah spopao sva zemaljska kraljevstva oko Judeje, tako da nisu smjela zaratiti na Jošafata.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 17, 11, 'Sami su mu neki Filistejci donosili darove i novčani danak, a Arapi mu dogonili sitnu stoku: po sedam tisuća i sedam stotina ovnova te sedam tisuća i sedam stotina jaraca.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 17, 12, 'Tako je Jošafat sve više napredovao dok ne postade vrlo velik. Sazidao je u Judeji kule i gradove-skladišta.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 17, 13, 'Imao je mnogo zaliha u judejskim gradovima, a hrabrih junaka u Jeruzalemu.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 17, 14, 'Evo njihova popisa po obiteljima: od Judina plemena tisućnici: vojvoda Adna i s njim trista tisuća hrabrih junaka;');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 17, 15, 'do njega vojvoda Johanan i s njim dvjesta i osamdeset tisuća;');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 17, 16, 'za njim Zikrijev sin Amasja, koji se spremno stavio u Jahvinu službu, a s njim dvjesta tisuća hrabrih junaka.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 17, 17, 'Od Benjaminova plemena: hrabri junak Eliada i s njim dvjesta tisuća ljudi naoružanih lukom i štitom;');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 17, 18, 'za njim Jehozabad i s njim sto i osamdeset tisuća pripravnih za boj.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 17, 19, 'To su oni koji su služili kralju, ne brojeći one što ih je kralj namjestio u tvrdim gradovima po svoj Judeji.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 18, 1, 'Jošafat je stekao veliko bogatstvo i slavu te se sprijateljio s Ahabom.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 18, 2, 'Poslije nekoliko godina došao je k Ahabu u Samariju. Ahab nakla mnogo sitne stoke i goveda njemu i ljudima što su bili s njim i nagovaraše ga da pođe na Ramot Gilead.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 18, 3, 'Izraelski kralj Ahab upita judejskoga kralja Jošafata: \"Hoćeš li poći sa mnom na Ramot Gilead?\" On odgovori: \"Ja sam kao i ti, moj je narod kao i tvoj; s tobom ćemo u rat.\"');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 18, 4, 'Jošafat još reče kralju izraelskom: \"De, posavjetuj se prije s Jahvom!\"');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 18, 5, 'Tada kralj izraelski sakupi proroke, njih četiri stotine, i upita ih: \"Hoćemo li zavojštiti na Ramot Gilead ili da se okanim toga?\" Oni odgovoriše: \"Idi, jer će ga Bog predati kralju u ruke.\"');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 18, 6, 'Ali Jošafat upita: \"Ima li ovdje još koji prorok Jahvin da i njega upitamo?\"');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 18, 7, 'Kralj izraelski odgovori Jošafatu: \"Ima još jedan čovjek preko koga bismo mogli upitati Jahvu, ali ga mrzim jer mi ne proriče dobra nego uvijek samo zlo; to je Mihej, sin Jimlin.\" Jošafat reče: \"Neka kralj ne govori tako!\"');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 18, 8, 'Tada kralj izraelski dozva jednoga dvoranina i reče mu: \"Brže dovedi Jimlina sina Miheja!\"');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 18, 9, 'Izraelski kralj i judejski kralj Jošafat sjedili su svaki na svojem prijestolju, u svečanim haljinama, na gumnu pred Samarijskim vratima, a proroci proricali pred njima.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 18, 10, 'Kenaanin sin Sidkija napravi sebi željezne rogove i reče: \"Ovako veli Jahve: njima ćeš bosti Aramejce dokle ih god ne zatreš.\"');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 18, 11, 'Tako su i svi drugi proroci proricali govoreći: \"Idi na Ramot Gilead, uspjet ćeš: Jahve će ga predati kralju u ruke.\"');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 18, 12, 'Glasnik koji bijaše otišao da zove Miheja reče mu: \"Evo, svi proroci složno proriču dobro kralju. Govori i ti kao jedan od njih i proreci uspjeh!\"');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 18, 13, 'Ali Mihej odvrati: \"Živoga mi Jahve, govorit ću ono što mi Bog kaže!\"');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 18, 14, 'Kad dođe pred kralja, upita ga kralj: \"Miheju, da pođem u rat na Ramot Gilead ili da se okanim toga?\" On odgovori: \"Idite i uspjet ćete, jer će vam se predati u ruke!\"');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 18, 15, 'Na to mu kralj reče: \"Koliko ću te puta zaklinjati da mi kažeš samo istinu u Jahvino ime?\"');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 18, 16, 'Tada Mihej odgovori: \"Sav Izrael vidim rasut po gorama kao stado bez pastira. I Jahve veli: \'Nemaju više gospodara, neka se u miru kući vrate!\'\"');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 18, 17, 'Tada izraelski kralj reče Jošafatu: \"Nisam li ti rekao da mi neće proreći dobro nego zlo?\"');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 18, 18, 'A Mihej reče: \"Zato čujte riječ Jahvinu. Vidio sam Jahvu gdje sjedi na prijestolju, a sva mu vojska nebeska stajaše zdesna i slijeva.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 18, 19, 'Jahve upita: \'Tko će zavesti izraelskoga kralja Ahaba da otiđe i padne u Ramot Gileadu?\' Jedan reče ovo, drugi ono.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 18, 20, 'Tada uđe jedan duh, stade pred Jahvu i reče: \'Ja ću ga zavesti!\' Jahve ga upita: \'Kako?\'');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 18, 21, 'On odvrati: \'Izaći ću i bit ću lažljiv duh u ustima svih njegovih proroka.\' Jahve mu reče: \'Ti ćeš ga zavesti. I uspjet ćeš. Idi i učini tako!\'');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 18, 22, 'Tako je, evo, Jahve stavio lažljiva duha u usta tvojim prorocima; ali ti Jahve navješćuje zlo.\"');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 18, 23, 'Tada pristupi Kenaanin sin Sidkija i udari Miheja po obrazu pitajući: \"Zar je Jahvin duh mene napustio da bi govorio s tobom?\"');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 18, 24, 'Mihej odvrati: \"Vidjet ćeš onoga dana kad budeš bježao iz sobe u sobu da se sakriješ.\"');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 18, 25, 'Tada izraelski kralj naredi: \"Uhvatite Miheja i odvedite ga gradskom zapovjedniku Amonu i kraljeviću Joašu.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 18, 26, 'Recite im: \'Ovako veli kralj: Bacite ovoga u tamnicu i držite ga na suhu kruhu i vodi dok se sretno ne vratim.\'\"');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 18, 27, 'Mihej reče: \"Ako se doista sretno vratiš, onda nije Jahve govorio iz mene!\" i nadoda: \"Čujte, svi puci!\"');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 18, 28, 'Izraelski kralj i judejski kralj Jošafat krenuše na Ramot Gilead.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 18, 29, 'Izraelski kralj reče Jošafatu: \"Ja ću se preobući i onda ući u boj, a ti ostani u svojoj odjeći!\" Preobuče se tada izraelski kralj i oni krenuše u boj.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 18, 30, 'Aramejski kralj naredi zapovjednicima bojnih kola: \"Ne udarajte ni na maloga ni na velikoga nego jedino na izraelskoga kralja!\"');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 18, 31, 'Kad zapovjednici bojnih kola ugledaše Jošafata, rekoše: \"To je izraelski kralj!\" I krenuše na nj da udare. Ali Jošafat povika za pomoć te mu Jahve pomože i odvrati ih od njega.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 18, 32, 'Kad zapovjednici bojnih kola vidješe da to nije izraelski kralj, okrenuše se od njega.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 18, 33, 'Jedan nasumce odape i ustrijeli izraelskoga kralja između nabora na pojasu i oklopa. Kralj reče vozaču: \"Potegni uzdu i izvedi me iz boja jer sam ranjen.\"');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 18, 34, 'Boj je onoga dana bio sve žešći, ali se izraelski kralj držao uspravno na bojnim kolima prema Aramejcima sve do večeri. Umro je o zalasku sunca.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 19, 1, 'Kad se judejski kralj Jošafat sretno vrati kući u Jeruzalem,');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 19, 2, 'iziđe preda nj Hananijev sin vidjelac Jehu i reče kralju Jošafatu: \"Zar da pomažeš bezbožniku i da ljubiš Jahvine mrzitelje? Zato i udara na te srdžba Jahvina.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 19, 3, 'Ipak se našlo nešto dobro u tebe: uklonio si ašere iz zemlje i pregnuo svim srcem da tražiš Jahvu!\"');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 19, 4, 'Od tada je Jošafat živio u Jeruzalemu, opet zalazio među narod od Beer Šebe do Efrajimske gore i obraćao ga Jahvi, Bogu njegovih otaca.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 19, 5, 'Postavi suce u zemlji u svim tvrdim judejskim gradovima, u svakome gradu.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 19, 6, 'I reče im: \"Gledajte što radite, jer ne sudite u ime čovjeka nego u ime Jahve. On je s vama dok sudite.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 19, 7, 'Sada, dakle, neka bude Jahvin strah nad vama; pazite i savjesno radite, jer u Jahve, Boga našega, nema nepravde ni osobne pristranosti, niti on prima mita.\"');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 19, 8, 'Jošafat postavi levite, svećenike i poglavare izraelskih obitelji u Jeruzalemu da izriču Jahvine sudove i da presuđuju u sporovima. Oni su živjeli u Jeruzalemu');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 19, 9, 'i on im dade naputke: \"Radite u Jahvinu strahu vjerno i iskrena srca.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 19, 10, 'Kakav god spor iziđe pred vas od vaše braće što žive u gradovima: bilo da su posrijedi krvna osveta, Zakon, zapovijedi, uredbe ili običaji, valja sve da im rastumačite, kako ne bi sagriješili Jahvi i kako se njegova srdžba ne bi oborila na vas i na vašu braću. Tako radite pa nećete sagriješiti.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 19, 11, 'I evo, svećenički će poglavar Amarja biti nad vama u svim Jahvinim poslovima, a Jišmaelov sin Zebadja, nadstojnik Judina doma, u svim kraljevskim poslovima. Leviti će vam služiti kao pisari. Budite jaki, i na posao! Jahve će biti s onim tko je dobar.\"');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 20, 1, 'Poslije toga Moabovi i Amonovi sinovi, a s njima i neki od Meunjana, zaratiše na Jošafata.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 20, 2, 'Ali Jošafat dobi ovu vijest: \"Dolazi na te veliko mnoštvo s one strane mora, iz Edoma; i eno ga u Haseson Tamaru, to jest u En Gediju.\"');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 20, 3, 'Jošafat se uplaši i stade tražiti Jahvu te oglasi post po svoj Judeji.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 20, 4, 'Skupili se Judejci da traže Jahvu: dolazili iz svih judejskih gradova da ga traže.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 20, 5, 'Tada Jošafat ustade u judejskom zboru u Jeruzalemu, u Domu Jahvinu, pred novim predvorjem');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 20, 6, 'i reče: \"Jahve, Bože otaca naših, ti si Bog na nebu i vladaš nad svim krivobožačkim kraljevstvima. U tvojoj je ruci takva sila i jakost da se nitko ne može održati pred tobom.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 20, 7, 'Ti si, o Bože naš, istjerao stanovnike ove zemlje pred svojim izraelskim narodom i dao je zasvagda potomstvu svoga prijatelja Abrahama;');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 20, 8, 'i nastanili su se u njoj i sagradili u njoj Svetište tvojem Imenu govoreći:');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 20, 9, '\'Kad navali na nas kakvo zlo, osvetni mač ili kuga, ili glad, te kad stanemo pred ovim Domom i pred tobom, jer je tvoje Ime u ovom Domu, i zavapimo k tebi iz svoje nevolje, usliši nas i spasi.\'');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 20, 10, 'Sada, evo, Amonovi i Moabovi sinovi, i oni iz Seirske gore, preko kojih nisi dao Izraelu da prođe kad je dolazio iz zemlje egipatske, nego ih je obišao i nije ih zatro -');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 20, 11, 'sada, dakle, oni nama uzvraćaju zlom, došavši da nas otjeraju s baštine koju si nam ti dao.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 20, 12, 'O Bože naš, zar im nećeš suditi? Jer u nas nema sile prema tome velikom mnoštvu koje dolazi na nas niti mi znamo što da radimo, nego su nam oči uprte u te.\"');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 20, 13, 'Svi su Judejci stajali pred Jahvom, s malom djecom, sa ženama i sinovima.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 20, 14, 'Tada siđe Jahvin duh usred zbora na Jahaziela, sina Zaharije, sina Benaje, sina Jeiela, sina Matanijina - levita od Asafovih sinova.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 20, 15, 'On reče: \"Pozorno slušajte, svi Judejci, Jeruzalemci i ti, kralju Jošafate! Ovako vam govori Jahve: \'Ne bojte se i ne plašite se toga velikog mnoštva, jer ovo nije vaš rat, nego Božji.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 20, 16, 'Sutra siđite na njih; oni će se penjati uz Hasiški uspon, a vi ćete ih sresti nakraj doline prema Jeruelskoj pustinji.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 20, 17, 'Ne treba da se bijete; postavite se, stojte pa gledajte kako će vam pomoći Jahve. Oj Judo i Jeruzaleme, ne bojte se i ne plašite se; sutra iziđite pred njih, i Jahve će biti s vama!\'\"');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 20, 18, 'Tada Jošafat pade ničice na zemlju i svi Judejci i Jeruzalemci padoše pred Jahvom da mu se poklone.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 20, 19, 'Potom leviti od Kehatovih sinova i od Korahovih sinova ustadoše i počeše hvaliti na sav glas Jahvu, Boga Izraelova.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 20, 20, 'Uranivši ujutro, krenuše prema pustinji Tekoi; kad su izlazili, stade Jošafat i reče: \"Čujte me, oj Judejci i Jeruzalemci, pouzdajte se u Jahvu svoga Boga i održat ćete se; pouzdajte se u njegove proroke i budite sretni!\"');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 20, 21, 'Potom se posavjetova s narodom i postavi Jahvine pjevače i hvalitelje koji će u svetom ruhu ići pred naoružanim četama i pjevati: \"Slavite Jahvu jer je vječna ljubav njegova!\"');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 20, 22, 'Kad počeše klicati i pjevati pjesmu pohvalnicu, Jahve podiže zasjedu na Amonce, Moapce i na one iz Seirske gore koji su došli na Judu te biše razbijeni.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 20, 23, 'Jer su Amonovi sinovi i Moapci ustali na one iz Seirske gore da ih zatru i unište; a kad su svršili s onima iz Seira, stadoše udarati jedan na drugoga te se poklaše.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 20, 24, 'Kad Judejci dođoše do stražare prema pustinji i obazreše se na mnoštvo, a ono gle, mrtva tjelesa leže po zemlji; nitko se nije spasio.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 20, 25, 'Tada dođe Jošafat s narodom da pokupi plijen i nađoše ga mnogo: svakoga blaga, odjeće i dragocjenih predmeta; naplijenili su toliko da više nisu mogli nositi; tri su dana pljačkali plijen jer ga je bilo mnogo.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 20, 26, 'Četvrti se dan sakupiše u Dolini blagoslova: ondje su hvalili Jahvu, pa se zato ono mjesto prozvalo Emek Beraka, Dolina blagoslova, do danas.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 20, 27, 'Potom se okrenuše svi Judejci i Jeruzalemci, s Jošafatom na čelu, da se vrate u Jeruzalem u veselju, jer ih je Jahve razveselio nad njihovim neprijateljima.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 20, 28, 'Došli su u Jeruzalem s harfama, citrama i trubama u Dom Jahvin.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 20, 29, 'A strah Božji ušao je u sva zemaljska kraljevstva kad su čula da je Jahve zavojštio na Izraelove neprijatelje.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 20, 30, 'Tako je počinulo Jošafatovo kraljevstvo, jer mu je Bog dao mir odasvud uokolo.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 20, 31, 'Jošafat je kraljevao nad Judejcima. Bilo mu je trideset i pet godina kad se zakraljio; kraljevao je dvadeset i pet godina u Jeruzalemu; mati mu se zvala Azuba, a bila je kći Šilhijeva.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 20, 32, 'Išao je putem oca Ase ne skrećući s njega nego čineći što je pravo u Jahvinim očima.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 20, 33, 'Samo, uzvišice nisu bile uklonjene, jer narod još nije bio upravio svoje srce Bogu otaca.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 20, 34, 'Ostala Jošafatova djela, od prvih do posljednjih, zapisana su u povijesti Hananijeva sina Jehua i uvrštena su u Knjigu o izraelskim kraljevima.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 20, 35, 'Poslije toga udružio se judejski kralj Jošafat s izraelskim kraljem Ahazjom, koji je bezbožno radio.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 20, 36, 'Udružio se s njim zato da naprave lađe i da odu u Taršiš; napravili su lađe u Esjon Geberu.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 20, 37, 'Dodavahuov sin Eliezer iz Mareše prorekao je protiv Jošafata: \"Budući da si se udružio s Ahazjom, Jahve će razoriti tvoja djela.\" Lađe su se razbile i nisu mogle otploviti u Taršiš.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 21, 1, 'Jošafat počinu kraj svojih otaca i bi sahranjen uz njih u Davidovu gradu. Na njegovo se mjesto zakraljio sin mu Joram.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 21, 2, 'Joram je imao šestoricu braće, Jošafatovih sinova: Azarju, Jehiela, Zahariju, Azarju, Mihaela i Šefatju. Svi su oni bili sinovi izraelskog kralja Jošafata.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 21, 3, 'Otac im je dao mnoge darove u srebru, zlatu i dragocjenostima, s utvrđenim gradovima u Judi; kraljevstvo je dao Joramu jer je bio prvenac.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 21, 4, 'Stupivši na očevo prijestolje i utvrdiv se, Joram pobi svu braću mačem, pa i neke izraelske knezove.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 21, 5, 'Joramu su bile trideset i dvije godine kad se zakraljio, a kraljevao je osam godina u Jeruzalemu.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 21, 6, 'Živio je poput izraelskih kraljeva, kao i dom Ahabov, jer mu je kći Ahabova bila žena; radio je što je zlo u Jahvinim očima.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 21, 7, 'Ipak Jahve ne htjede razoriti kuće Davidu zbog Saveza što ga sklopi s njim i zato što mu obeća da će dati svjetiljku njemu i njegovim sinovima zauvijek.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 21, 8, 'U njegovo se vrijeme Edomci odmetnuše ispod judejske vlasti i postaviše sebi kralja.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 21, 9, 'Zato Joram pođe sa svojim vojskovođama i sa svim bojnim kolima. Diže se noću i pobi Edomce koji bijahu opkolili njega i zapovjednike bojnih kola.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 21, 10, 'Ipak su se Edomci oslobodili ispod judejske vlasti sve do danas. U isto se doba odmetnu i Libna da ne bude pod njegovom vlašću, jer je on ostavio Jahvu, Boga svojih otaca.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 21, 11, 'Još je i uzvišice napravio po judejskim gorama, naveo na blud Jeruzalemce i zaveo Judejce.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 21, 12, 'Tada mu od proroka Ilije stiže pismo: \"Ovako veli Jahve, Bog tvoga oca Davida: \'Kako nisi išao putovima oca Jošafata, ni putovima judejskoga kralja Ase,');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 21, 13, 'nego si išao putovima izraelskih kraljeva i naveo na blud Judejce i Jeruzalemce, kao što je učinio dom Ahabov, a uz to si poubijao vlastitu braću, svoju obitelj, koji bjehu bolji od tebe:');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 21, 14, 'evo, Jahve će svaliti veliku nesreću na tvoj narod, na tvoje sinove, tvoje žene, na sve tvoje imanje.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 21, 15, 'Oboljet ćeš od mnogih bolesti: od bolesti u crijevima, tako da će ti crijeva izaći od bolesti koja će trajati dane i dane.\'\"');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 21, 16, 'Jahve podiže na Jorama srdžbu Filistejaca i Arapa koji žive kraj Etiopljana.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 21, 17, 'Oni napadoše Judeju i osvojiše je, porobiše sve blago što se našlo u kraljevu dvoru, pa i njegove sinove i njegove žene, tako da nije ostao nitko, osim najmlađega sina, Joahaza.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 21, 18, 'Poslije svega toga udari ga Jahve neizlječivom crijevnom bolešću.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 21, 19, 'Ona je trajala dane i dane, a kad su se navršile dvije godine, izašla su mu crijeva s bolešću te je umro u strašnim mukama. Narod mu nije priredio mirisna paljenja, kao što je palio njegovim ocima.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 21, 20, 'Bile su mu trideset i dvije godine kad se zakraljio, a osam je godina kraljevao u Jeruzalemu. Preminuo je, a nitko nije požalio za njim; i sahraniše ga u Davidovu gradu, ali ne u kraljevskoj grobnici.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 22, 1, 'Jeruzalemci zakraljiše na njegovo mjesto najmlađeg mu sina, Ahazju, jer sve starije bijaše poubijala četa koja je s Arapima navalila na tabor; tako se zakraljio Ahazja, sin judejskoga kralja Jorama.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 22, 2, 'Bile su mu četrdeset i dvije godine kad se zakraljio. Kraljevao je jednu godinu u Jeruzalemu. Materi mu je bilo ime Atalija, Omrijeva kći.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 22, 3, 'I on je išao putovima doma Ahabova, jer ga mati zlo svjetovaše.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 22, 4, 'Činio je što je zlo u Jahvinim očima, kao dom Ahabov, jer mu baš oni bijahu savjetnici poslije očeve smrti, na njegovu propast.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 22, 5, 'Po njihovu je savjetu pošao s Joramom, sinom izraelskoga kralja Ahaba, u boj na aramejskoga kralja Hazaela u Ramot Gilead. Ali su Aramejci porazili Jorama.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 22, 6, 'On se vratio da se liječi u Jizreelu od rana što mu ih zadadoše u Rami kad se borio s aramejskim kraljem Hazaelom. Joramov sin Ahazja, judejski kralj, sišao je u Jizreel da posjeti Ahabova sina Jorama jer se Joram razbolio.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 22, 7, 'Ali Bog učini da taj posjet Joramu bude na propast Ahazji. Došavši, izišao je s Joramom na Nimšijeva sina Jehua, koga je Jahve pomazao da iskorijeni Ahabovu kuću.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 22, 8, 'Dok je izvršavao osvetu nad Ahabovom kućom, Jehu zateče judejske knezove i sinove Ahazjine braće koji su posluživali Ahazju i pobi ih,');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 22, 9, 'a onda krenu u potragu za Ahazjom. Uhvatili su ga dok se krio u Samariji, doveli ga k Jehuu, koji ga smaknu. Ukopali su ga, jer su rekli: \"Sin je onoga Jošafata koji je tražio Jahvu svim srcem.\" Tako ne ostade nitko od Ahazjine kuće koji bi imao snage da bude kralj.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 22, 10, 'Zato Ahazjina mati Atalija, vidjevši gdje joj sin poginu, ustade i posmica sav kraljevski rod Judina plemena.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 22, 11, 'Ali kraljeva kći Jošeba uze Ahazjina sina Joaša; ukravši ga između kraljevih sinova koje su ubijali, metnu ga s dojiljom u ložnicu. Tako ga je Jošeba, kći kralja Jorama, žena svećenika Jojade, sakrila od Atalije, jer je bila Ahazjina sestra, te nije bio pogubljen.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 22, 12, 'Bio je sakriven s njima u Domu Božjem šest godina, sve dok je zemljom vladala Atalija.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 23, 1, 'Sedme se godine Jojada ojunači i poče tražiti satnike: Jerohamova sina Azarju, Johananova sina Jišmaela, Obedova sina Azarju, Adajina sina Maaseju, Zikrijeva sina Elišafata, i sklopi s njima savez.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 23, 2, 'Počeše obilaziti po Judeji i skupiše levite iz svih judejskih gradova i obiteljske glavare u Izraelu te dođoše u Jeruzalem.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 23, 3, 'Sav zbor sklopi savez s kraljem u Domu Božjem. Jojada im reče: \"Gle, kraljev će sin kraljevati kao što je obećao Jahve za Davidove sinove.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 23, 4, 'Evo što valja da učinite: trećina vas koji subotom ulazite u službu, i svećenici i leviti, neka budu vratari na pragovima;');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 23, 5, 'trećina neka bude u kraljevskom dvoru, trećina na Jesodskim vratima, sav narod u predvorjima Doma Jahvina.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 23, 6, 'Nitko neka ne ulazi u Dom Jahvin, osim svećenika i levita koji poslužuju; oni neka ulaze jer su posvećeni. Sav narod neka se drži Jahvine naredbe.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 23, 7, 'Leviti neka okruže kralja, svaki s oružjem u ruci, i tko god pokuša ući u Dom neka bude pogubljen. Budite uz kralja kamo god pođe ili izađe.\"');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 23, 8, 'Leviti i sav judejski narod učinili su sve onako kako je naredio svećenik Jojada. Svaki je uzeo svoje ljude koji subotom ulaze u službu s onima koji subotom izlaze. Jer svećenik Jojada nije otpustio redova.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 23, 9, 'Svećenik Jojada dade satnicima koplja, štitove i oklope kralja Davida što su bili u Božjemu Domu.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 23, 10, 'Postavio je sav narod, svakoga s kopljem u ruci, od južne do sjeverne strane Doma, prema žrtveniku i prema Domu oko kralja unaokolo.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 23, 11, 'Tada izvedoše kraljeva sina, staviše mu krunu na glavu, dadoše mu Svjedočanstvo i pomazaše ga za kralja. Tada Jojada i njegovi sinovi povikaše: \"Živio kralj!\"');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 23, 12, 'Kad Atalija ču viku naroda koji se skupio i hvalio kralja, dođe k narodu u Jahvin Dom.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 23, 13, 'Pogleda bolje, kad gle, kralj stoji na svojem mjestu na ulazu, a pred kraljem zapovjednici i svirači; sav puk kliče od radosti i trubi u trube, pjevači pjevaju uz glazbala i predvode hvalospjeve. Tad Atalija razdrije haljine i povika: \"Izdaja, izdaja!\"');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 23, 14, 'Svećenik Jojada naredi satnicima i vojnim zapovjednicima: \"Izvedite je kroz redove napolje i tko krene za njom pogubite ga mačem!\" Još je svećenik dodao: \"Nemojte je smaknuti u Jahvinu Domu!\"');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 23, 15, 'Staviše ruke na nju i kad je kroz Konjska vrata stigla do kraljevskoga dvora, ondje je pogubiše.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 23, 16, 'Tada Jojada sklopi savez između Jahve, naroda i kralja da narod bude Jahvin.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 23, 17, 'Potom sav narod otiđe u Baalov hram, razori ga skupa sa žrtvenicima i polomi likove; Baalova svećenika Matana ubiše pred žrtvenicima.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 23, 18, 'Zatim Jojada postavi straže kod Jahvina Doma pod nadzorom svećenika i levita, koje David bijaše porazdijelio za službu u Jahvinu Domu da bi Jahvi prinosili paljenice, kao što je pisano u Mojsijevu Zakonu, s veseljem i s pjesmama, kako uredi David.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 23, 19, 'Postavio je i vratare na vratima Jahvina Doma da ne bi ulazio čovjek nečist od bilo čega.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 23, 20, 'Uzevši satnike, odličnike i uglednike u narodu i sav puk, izveo je kralja iz Jahvina Doma, a onda su ušli kroz gornja vrata u kraljevski dvor i posadili kralja na kraljevsko prijestolje.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 23, 21, 'Sav se puk veselio, a grad se umirio, jer su Ataliju ubili mačem.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 24, 1, 'Joašu je bilo sedam godina kad se zakraljio, a kraljevao je četrdeset godina u Jeruzalemu. Materi mu je bilo ime Sibja iz Beer Šebe.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 24, 2, 'Joaš je činio što je pravo u Jahvinim očima dok je bio živ svećenik Jojada.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 24, 3, 'Jojada ga je oženio dvjema ženama i on je s njima imao sinova i kćeri.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 24, 4, 'Poslije toga nakanio je u srcu obnoviti Jahvin Dom.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 24, 5, 'Skupivši svećenike i levite, reče im: \"Zađite po judejskim gradovima i kupite od svih Izraelaca novaca da se obnovi Dom vašega Boga, od godine do godine, a vi pohitite s tim poslom.\" Ali se levitima nije htjelo.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 24, 6, 'Zato kralj pozva poglavara Jojadu i reče mu: \"Zašto ne tražiš od levita da donose iz Judeje i iz Jeruzalema porez koji je odredio Jahvin sluga Mojsije i Izraelov zbor za Šator svjedočanstva?');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 24, 7, 'Atalija i njeni sinovi bijahu poharali Božji Dom, i sve stvari što su bile posvećene Jahvinu Domu upotrijebili su za baale.\"');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 24, 8, 'Potom kralj zapovjedi da se napravi kovčeg i stavi izvana na vrata Jahvina Doma.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 24, 9, 'Oglasiše po Judi i Jeruzalemu da se donosi Jahvi porez što ga bijaše odredio Božji sluga Mojsije Izraelu u pustinji.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 24, 10, 'Obradovaše se svi knezovi i sav narod i počeše donositi i bacati u kovčeg dok se nije napunio.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 24, 11, 'Leviti bi donosili kovčeg kraljevskom nadgledništvu, i kad bi se vidjelo da ima mnogo novaca, dolazio je kraljev tajnik i povjerenik svećeničkog poglavara te bi ispraznili kovčeg. Onda su ga opet odnosili i stavljali na njegovo mjesto. Tako su činili svaki dan i sabrali mnogo novca.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 24, 12, 'Onda su ga kralj i Jojada davali poslovođama nad poslom oko Jahvina Doma, a oni su za plaću unajmljivali klesare i drvodjelce da se obnovi Jahvin Dom, pa kovače i mjedare da se popravi Jahvin Dom.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 24, 13, 'Poslovođe su poslovale i popravljanje je napredovalo pod njihovom upravom; vratili su Božji Dom u red i obnovili ga.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 24, 14, 'A kad su sve svršili, donijeli su pred kralja i Jojadu novce što su ostali; od toga su napravili posuđe za Jahvin Dom, posuđe za posluživanje, za paljenje, plitice i druge zlatne i srebrne predmete. Paljenice su se prinosile u Jahvinu Domu bez prestanka dok je god živio Jojada.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 24, 15, 'Onda je Jojada, ostarjevši i nasitivši se života, umro u sto i tridesetoj godini.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 24, 16, 'Sahranili su ga u Davidovu gradu kod kraljeva, jer je činio dobro u Izraelu i prema Bogu i njegovu Domu.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 24, 17, 'Poslije Jojadine smrti došli su Judini knezovi i poklonili se kralju. Tada ih kralj poče slušati.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 24, 18, 'Judejci bijahu ostavili Jahvu, Boga otaca, i stali služiti ašerama i likovima; došla je Božja srdžba na Judejce i na Jeruzalem za tu krivicu.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 24, 19, 'Slao im je Bog proroke da ih obrate k Jahvi, oni su ih opominjali, ali oni nisu htjeli slušati.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 24, 20, 'Tada Božji duh napuni Jojadina sina, svećenika Zahariju, koji, stavši poviše naroda, reče: \"Ovako veli Bog: \'Zašto kršite Jahvine zapovijedi? Zašto nećete da budete sretni? Kako ste vi ostavili Jahvu, i on će vas ostaviti.\'\"');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 24, 21, 'Ali su se oni pobunili protiv njega i zasuli ga kamenjem po kraljevoj zapovijedi u predvorju Jahvina Doma.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 24, 22, 'Ni kralj Joaš ne sjeti se ljubavi koju mu učini otac Jojada, nego mu ubi sina; a on je umirući rekao: \"Jahve neka vidi i osveti!\"');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 24, 23, 'Kad je prošla godina dana, diže se na nj aramejska vojska i, navalivši na Judu i Jeruzalem, pobi sve knezove u narodu i posla sav plijen kralju u Damask.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 24, 24, 'Iako je aramejska vojska bila malena po ljudstvu, ipak joj je Jahve predao u ruke vrlo brojnu vojsku, jer ostaviše Jahvu, Boga svojih otaca. Tako su se Aramejci na Joašu osvetili.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 24, 25, 'Kad su otišli od njega, ostaviv ga u teškim bolestima, pobuniše se protiv njega njegovi časnici jer bijaše ubio sina svećenika Jojade, pa i oni njega ubiše na postelji te je poginuo; sahranili su ga u Davidovu gradu, ali ga nisu ukopali u kraljevskoj grobnici.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 24, 26, 'Evo onih što se urotiše protiv njega: Zabad, sin Amonke Šimeate, i Jozabad, sin Moapke Šimrite.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 24, 27, 'A o njegovim sinovima i o velikim proroštvima protiv njega, o obnavljanju Doma Božjega, sve je zapisano u tumačenju Knjige o kraljevima. Na njegovo se mjesto zakraljio sin mu Amasja.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 25, 1, 'Amasji je bilo dvadeset i pet godina kad se zakraljio; kraljevao je dvadeset i devet godina u Jeruzalemu. Mati mu se zvala Joadana i bila je iz Jeruzalema.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 25, 2, 'Činio je što je pravo u Jahvinim očima, ali ne svim srcem.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 25, 3, 'Kad je učvrstio kraljevstvo, pogubio je časnike koji su ubili kralja, njegova oca.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 25, 4, 'Ali im sinova nije pogubio, prema onome što je napisano u knjizi Zakona Mojsijeva, gdje Jahve zapovijeda: \"Neka se očevi ne pogubljuju za sinove, ni sinovi za očeve, nego svatko neka gine za svoj grijeh.\"');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 25, 5, 'Potom Amasja skupi Judejce i svega Judu i Benjamina, razvrsta ih prema obiteljima, tisućnicima i satnicima. Pošto popisa od dvadeset godina naviše, nađe trista tisuća izabranih momaka za vojsku, vičnih koplju i štitu.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 25, 6, 'Među Izraelcima najmi sto tisuća hrabrih junaka za sto srebrnih talenata.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 25, 7, 'Ali k njemu dođe čovjek Božji i reče: \"Kralju, neka ne ide s tobom izraelska vojska, jer Jahve nije s Izraelcima ni s Efrajimovim sinovima,');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 25, 8, 'nego idi ti sam, ponesi se junački u boju; inače će te oboriti Bog pred neprijateljem, jer Bog može pomoći i oboriti.\"');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 25, 9, 'Tada Amasja upita čovjeka Božjeg: \"A što će biti od sto talenata koje sam dao izraelskim četama?\" Božji čovjek odgovori: \"Jahve ima da ti dade više od toga.\"');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 25, 10, 'Tada Amasja odvoji čete koje mu bijahu došle od Efrajima, da se vrate u svoje mjesto. Ali se vojnici razgnjeviše na Judejce i vratiše se u svoje mjesto plamteći od srdžbe.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 25, 11, 'A Amasja, ohrabriv se, povede narod, ode u Slanu dolinu i pobi deset tisuća seirskih sinova.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 25, 12, 'Judini su sinovi zarobili deset tisuća živih, odveli ih na vrh hridi te ih pobacali, tako da se svi razmrskaše.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 25, 13, 'Četa koju je Amasja poslao natrag da ne ide s njima u boj harala je po judejskim gradovima od Samarije pa do Bet Horona i pobila u njima tri tisuće ljudi i naplijenila silan plijen.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 25, 14, 'Poslije toga, kad se Amasja vratio razbivši Edomce, donio je bogove seirskih sinova, postavio ih sebi za bogove i počeo im se klanjati i kaditi im.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 25, 15, 'Tada se Jahve razgnjevi na Amasju i posla k njemu proroka koji ga upita: \"Zašto tražiš bogove toga naroda koji nisu izbavili svoga naroda iz tvoje ruke?\"');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 25, 16, 'Dok je on to govorio, kralj ga upita: \"Jesi li postavljen kralju za savjetnika? Prestani! Zašto da te pogube?\" Tada prorok ušutje, ali nadoda: \"Znam da te Bog odlučio uništiti kad to činiš a ne slušaš mojega savjeta.\"');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 25, 17, 'Tada judejski kralj Amasja smisli i poruči izraelskom kralju Joašu, sinu Jehuova sina Joahaza: \"Dođi da se ogledamo!\"');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 25, 18, 'A izraelski kralj Joaš odvrati judejskom kralju Amasji: \"Libanonski je trn jedanput poslao glasnike k libanonskom cedru i poručio: \'Daj kćer mome sinu za ženu\', ali su divlje zvijeri libanonske prošle i trn izgazile.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 25, 19, 'Potukao si Edomce, pa ti se srce uzobijestilo i tražiš slavu. Radije ostani kod kuće. Zašto izazivaš zlo i hoćeš da padneš i ti i svi Judejci s tobom?\"');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 25, 20, 'Ali Amasja ne posluša, jer tako bijaše odredio Bog, da ih preda u ruke Joašu zato što su pristali uz edomske bogove.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 25, 21, 'Izađe izraelski kralj Joaš te se ogledaše u boju on i judejski kralj Amasja u Bet Šemešu u Judeji.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 25, 22, 'Izraelci poraziše Judejce i oni pobjegoše pod svoj šator.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 25, 23, 'Izraelski kralj Joaš uhvati u Bet Šemešu judejskog kralja Amasju, sina Joaševa, sina Joahazova, i odvede ga u Jeruzalem; onda sruši jeruzalemski zid od Efrajimovih vrata do Ugaonih vrata, u dužini od četiri stotine lakata.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 25, 24, 'Uzevši sve zlato, srebro i posuđe što se nalazilo u Domu Božjem kod Obed Edoma i u riznici kraljevskog dvora, povrh toga i taoce, vrati se u Samariju.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 25, 25, 'Judejski je kralj Amasja, Joašev sin, živio još petnaest godina poslije smrti izraelskoga kralja Joaša, Joahazova sina.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 25, 26, 'Ostala Amasjina djela, od prvih do posljednjih, zapisana su u Knjizi o judejskim i izraelskim kraljevima.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 25, 27, 'Otkako je Amasja ostavio Jahvu, kovala se protiv njega urota u Jeruzalemu. Iako je pobjegao u Lakiš, poslaše za njim u Lakiš ljude koji ga ondje ubiše.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 25, 28, 'Odande su ga prenijeli na konjima i sahranili kraj njegovih otaca u Judinu gradu.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 26, 1, 'Tada sav judejski narod uze Uziju, komu bijaše šesnaest godina, i zakraljiše ga namjesto njegova oca Amasje.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 26, 2, 'On je opet sagradio Elat vrativši ga Judeji, pošto je kralj počinuo kod svojih otaca.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 26, 3, 'Uziji bijaše šesnaest godina kad se zakraljio, a kraljevao je pedeset i dvije godine u Jeruzalemu. Mati mu se zvala Jekolija, a bila je iz Jeruzalema.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 26, 4, 'Činio je što je pravo u Jahvinim očima, sasvim kao i njegov otac Amasja.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 26, 5, 'Tražio je Boga za života Zaharije, koji ga je učio Božjem strahu; dokle je god tražio Jahvu, davao mu je Bog sreću.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 26, 6, 'On je izišao i zavojštio na Filistejce, srušio zid Gata, zid Jabne i zid Ašdoda; sagradio je mjesta po Ašdodu i Filisteji.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 26, 7, 'Bog mu je pomogao protiv Filistejaca i protiv Arapa, koji su živjeli u Gur Baalu, i protiv Meunjana.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 26, 8, 'Amonci su davali danak Uziji, a njegov se glas pronio do Egipta, jer se bijaše vrlo osilio.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 26, 9, 'Uzija je sagradio kule u Jeruzalemu kod Ugaonih vrata, kod Dolinskih vrata i na uglu te ih utvrdio.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 26, 10, 'Sagradio je i u pustinji kule i iskopao mnogo studenaca, jer je imao mnogo stoke i u Šefeli i po Ravnici, ratara i vinogradara u gorama i vrtovima, jer je volio poljodjelstvo.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 26, 11, 'Uzija je imao vojsku vještu boju koja je išla u rat u četama po broju kako ih je izbrojio tajnik Jeiel i nadzornik Maasja pod upravom Hananije, jednoga od kraljevih knezova.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 26, 12, 'Svega je na broj bilo, obiteljskih glavara, hrabrih junaka, dvije tisuće i šest stotina.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 26, 13, 'Pod njihovom je upravom bilo silne vojske trista sedam tisuća i pet stotina boju vičnih ratnika da pomažu kralju protiv neprijatelja.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 26, 14, 'Uzija je pripravio svoj vojsci štitove, koplja, kacige, oklope, lukove i kamenje za praćke.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 26, 15, 'Napravio je u Jeruzalemu vješto smišljene bojne sprave, iznašašće nekoga graditelja, da stoje na kulama i na kruništima, da bacaju strijele i veliko kamenje; pronio mu se glas nadaleko jer je uživao čudesnu pomoć sve dok se nije osilio.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 26, 16, 'Ali kad se osilio, uzobijestilo mu se srce dotle da se pokvario te se iznevjerio Jahvi, svome Bogu, jer je ušao u Jahvin Hekal i počeo prinositi kad na kadionom žrtveniku.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 26, 17, 'Ali je za njim ušao svećenik Azarja i s njim osamdeset Jahvinih svećenika, čestitih ljudi.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 26, 18, 'Oni ustadoše na kralja Uziju govoreći: \"Nije tvoje, Uzijo, da kadiš Jahvi, nego je to dužnost svećenika, Aronovih sinova, koji su posvećeni da kade. Izlazi iz Svetišta! Iznevjerio si se. I ne služi ti na čast pred Bogom Jahvom!\"');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 26, 19, 'Tada se Uzija rasrdi držeći u ruci kadionicu da kadi; kad se rasrdio na svećenike, izbi mu guba na čelu pred svećenicima u Domu Jahvinu kraj kadionog žrtvenika.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 26, 20, 'Kad ga svećenički poglavar Azarja i svi svećenici izbližega pogledaše, a ono, gle, izbila mu guba na čelu; brže ga otjeraše odande, a i on sam pohitje da iziđe jer ga Jahve bijaše udario.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 26, 21, 'Kralj Uzija ostade gubav do smrti i stanovaše u odvojenoj kući, jer bijaše odstranjen od Doma Jahvina; njegov je sin Jotam bio upravitelj kraljevskoga dvora i sudio je puku zemlje.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 26, 22, 'Ostala Uzijina djela, od prvih do posljednjih, opisao je Amosov sin, prorok Izaija.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 26, 23, 'Uzija je počinuo i sahranili su ga kraj njegovih otaca na polju kod kraljevske grobnice, rekavši: \"Gubav je.\" Na njegovo se mjesto zakraljio sin mu Jotam.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 27, 1, 'Jotamu je bilo dvadeset i pet godina kad se zakraljio, a kraljevao je šesnaest godina u Jeruzalemu. Materi mu je bilo ime Jeruša, Sadokova kći.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 27, 2, 'Činio je što je pravo u Jahvinim očima, sasvim kao otac mu Uzija; samo što nije ušao u Jahvin Hekal. Narod je i dalje bio pokvaren.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 27, 3, 'Sagradio je Gornja vrata Doma Jahvina; i na Ofelskom zidu mnogo je gradio.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 27, 4, 'Podigao je i gradove po Judejskoj gori, a u šumama dvorove i kule.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 27, 5, 'Vojevao je s kraljem Amonovih sinova i pobijedio ih. Amonovi su mu sinovi dali one godine sto srebrnih talenata i deset tisuća kora pšenice i deset tisuća kora ječma. Toliko su mu Amonovi sinovi priložili i druge i treće godine.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 27, 6, 'Tako se Jotam utvrdio, jer je uredio svoj život pred Jahvom, svojim Bogom.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 27, 7, 'Ostala su Jotamova djela i svi njegovi ratovi i putovi zapisani u Knjizi o izraelskim i judejskim kraljevima.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 27, 8, 'Bilo mu je dvadeset i pet godina kad se zakraljio. Kraljevao je šesnaest godina u Jeruzalemu.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 27, 9, 'Tada Jotam počinu kod otaca i sahraniše ga u Davidovu gradu. Na njegovo se mjesto zakralji sin mu Ahaz.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 28, 1, 'Ahazu je bilo dvadeset godina kad se zakraljio, a kraljevao je šesnaest godina u Jeruzalemu, ali nije činio što je pravo u Jahvinim očima kao što je činio njegov otac David.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 28, 2, 'Živio je poput izraelskih kraljeva, pa je i likove salio baalima.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 28, 3, 'Sam je prinosio kad u dolini Hinomova sina i proveo vlastite sinove kroz oganj, po gnusnom običaju krivobožačkih naroda što ih je Jahve protjerao pred Izraelovim sinovima.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 28, 4, 'Prinosio je žrtve i kadio po uzvišicama i brežuljcima i pod svakim zelenim drvetom.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 28, 5, 'Zato ga Jahve, njegov Bog, predade u ruke aramejskom kralju te ga on potuče, zarobi mu veliko mnoštvo ljudi i odvede ih u Damask. Još je bio predan u ruke izraelskom kralju koji ga je hametice porazio.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 28, 6, 'Remalijin je sin Pekah pobio među Judejcima sto dvadeset tisuća hrabrih junaka u jedan dan, jer su bili ostavili Jahvu, Boga svojih otaca.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 28, 7, 'A junak od Efrajimova plemena Zikri pogubio je kraljeva sina Maaseju i dvorskoga upravitelja Azrikama i Elkanu, drugoga do kralja.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 28, 8, 'Izraelovi su sinovi zarobili od svoje braće dvjesta tisuća žena, sinova i kćeri, a zadobili su i silan plijen od njih i odnijeli ga u Samariju.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 28, 9, 'Ondje bijaše Jahvin prorok po imenu Oded; izašao on pred vojsku što je išla u Samariju i rekao: \"Gle, Jahve, Bog vaših otaca, razjario se na Judejce i zato ih je predao u vaše ruke te ste ih gnjevno pobili da je do neba doprlo.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 28, 10, 'A sada još mislite podjarmiti Judejce i Jeruzalemce da vam budu robovi i robinje; a ipak, niste li i vi puni krivice prema Jahvi, svome Bogu?');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 28, 11, 'Zato me poslušajte sada i vratite to roblje što ga zarobiste od svoje braće, jer će se izliti na vas Jahvin gnjev.\"');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 28, 12, 'Tada ustadoše neki između glavara Efrajimovih sinova, i to Johananov sin Azarja, Mešilemotov sin Berekja i Šalumov sin Ezekija, Hadlajev sin Amasa, na one što su se vraćali s vojske.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 28, 13, 'Pa im rekoše: \"Nemojte dovoditi ovamo toga roblja, jer, uz krivicu koja je na nama pred Jahvom, vi mislite još dometnuti na naše grijehe i na našu krivicu, kao da nije dosta velika naša krivica i jarosni gnjev na Izraelu.\"');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 28, 14, 'Tada ostaviše ratnici roblje i plijen pred knezovima i svim zborom.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 28, 15, 'Onda su poimence prozvani ljudi ustali, osokolili robove, obukli sve gole u odjeću iz plijena; a kad su ih obukli, obuli, nahranili, napojili i namazali, poveli su na magarcima sve iznemogle i odveli ih u palmov grad Jerihon do njihove braće, a potom se vratili u Samariju.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 28, 16, 'U to je doba kralj Ahaz zamolio asirske kraljeve da mu pomognu.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 28, 17, 'Edomci bijahu opet navalili i porazili Judejce te ih odveli u roblje.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 28, 18, 'Filistejci se raširili po gradovima Judejske Šefele i Negeba i, zauzevši Bet-Šemeš, Ajalon, Gederot i Soko sa selima, Timnu sa selima i Gimzo sa selima, nastanili se ondje.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 28, 19, 'Jahve je počeo ponižavati Judejce zbog judejskoga kralja Ahaza, jer je Ahaz razuzdao Judejce i teško se iznevjerio Jahvi.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 28, 20, 'Došao je na nj asirski kralj Tiglat-Pileser i pritijesnio ga umjesto da ga utvrdi.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 28, 21, 'Ahaz bijaše opljačkao Jahvin Dom, kraljevski dvor i knezove, i sve to dao asirskom kralju, ali mu ništa nije pomoglo.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 28, 22, 'Dok je bio u nevolji, postao je još nevjerniji Jahvi; takav je bio kralj Ahaz.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 28, 23, 'Počeo je žrtvovati damaščanskim bogovima koji su ga porazili, misleći: \"Kad bogovi aramejskih kraljeva njima pomažu, žrtvovat ću im da bi i meni pomagali.\" Ali su oni bili na propast njemu i svem Izraelu.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 28, 24, 'Ahaz je pokupio posuđe iz Božjega Doma, slupao ga, zatvorio vrata Jahvina Doma i podigao žrtvenike po svim uglovima u Jeruzalemu.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 28, 25, 'I u svakom je pojedinom judejskom gradu podigao uzvišice da kadi tuđim bogovima, dražeći Jahvu, Boga otaca.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 28, 26, 'Ostala su njegova djela i svi njegovi putovi, od prvih do posljednjih, zapisani u Knjizi o judejskim i izraelskim kraljevima.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 28, 27, 'Onda je Ahaz počinuo kod otaca. Sahranili su ga u Gradu, u Jeruzalemu, ali ga nisu unijeli u grobnicu judejskih kraljeva. Na njegovo se mjesto zakraljio sin mu Ezekija.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 29, 1, 'Ezekiji je bilo dvadeset i pet godina kad se zakraljio. Kraljevao je dvadeset i devet godina u Jeruzalemu. Materi mu je bilo ime Abija, kći Zaharijina.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 29, 2, 'Činio je što je pravo u očima Jahvinim, sasvim kao i njegov otac David.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 29, 3, 'Prve godine prvoga mjeseca svojega kraljevanja otvorio je vrata Doma Jahvina i popravio ih.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 29, 4, 'Onda je pozvao svećenike i levite i, sabravši ih na istočni trg,');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 29, 5, 'rekao: \"Čujte me, leviti! Sada se posvetite i posvetite Dom Jahve, Boga svojih otaca, i uklonite nečist iz Svetinje.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 29, 6, 'Naši su se oci iznevjerili i radili što je zlo u očima Jahve, našega Boga. Ostavili su ga i odvratili lice od Jahvina Prebivališta, okrenuvši mu leđa.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 29, 7, 'Zatvorili su trijemska vrata i potrnuli svjetiljke; nisu kadili kadom niti su prinosili paljenice u Svetištu Izraelova Boga.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 29, 8, 'Zato se Jahve rasrdio na Judejce i na Jeruzalem te je dopustio da budu zlostavljeni i da budu na užas i ruglo, kako vidite svojim očima.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 29, 9, 'I očevi su nam, eto, pali od mača, a sinovi, kćeri i žene zato su nam u ropstvu.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 29, 10, 'Sad sam, dakle, namislio u svom srcu sklopiti Savez s Jahvom, Izraelovim Bogom, da bi se odvratio od nas njegov jarosni gnjev.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 29, 11, 'Moja djeco, sad se nemojte lijeniti, jer vas je izabrao Jahve da stojite pred njim, da mu služite i da mu budete službenici i da mu kadite.\"');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 29, 12, 'Tada ustadoše leviti: Amasajev sin Mahat i Azarjin sin Joel od Kehatovih sinova; od Merarijevih sinova: Abdijev sin Kiš i Jehalelelov sin Azarja; od Geršonovaca: Zimin sin Joah i Joahov sin Eden;');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 29, 13, 'od Elisafanovih sinova: Šimri i Jeiel; od Asafovih sinova: Zaharija i Matanija;');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 29, 14, 'od Hemanovih sinova: Jehiel i Šimej; od Jedutunovih sinova: Šemaja i Uziel.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 29, 15, 'Oni skupiše braću, posvetiše se i dođoše kako je bio zapovjedio kralj po Jahvinim riječima da očiste Jahvin Dom.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 29, 16, 'Svećenici uđoše u Jahvin Dom da ga očiste. Počeli su svu nečist što su je našli u Jahvinu Hekalu iznositi u predvorje Jahvina Doma; leviti su je primali iznoseći je napolje na potok Kidron.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 29, 17, 'Počeli su posvećivati prvoga dana prvoga mjeseca, a osmoga su dana istoga mjeseca ušli u Jahvin trijem; posvećivali su Jahvin Dom osam dana; šesnaestoga su dana prvoga mjeseca završili.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 29, 18, 'Onda su ušli kralju Ezekiji i rekli: \"Očistili smo sav Jahvin Dom: žrtvenik za paljenice sa svim njegovim priborom, stol za prinesene kruhove sa svim njegovim priborom,');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 29, 19, 'a sve posuđe koje bijaše zabacio kralj Ahaz za svojega kraljevanja i nevjere opet smo obnovili i posvetili; eno ga pred Jahvinim žrtvenikom.\"');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 29, 20, 'Tada kralj Ezekija porani, skupi gradske knezove i ode u Jahvin Dom.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 29, 21, 'Dovedoše sedam mladih junaca, sedam ovnova, sedam jaganjaca, sedam jaraca za okajnicu, za kraljevstvo i za Svetište i za Judu; on zapovjedi Aronovim sinovima svećenicima da ih prinesu za paljenicu na Jahvinu žrtveniku.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 29, 22, 'Zaklavši goveda, svećenici uzeše krv i poškropiše žrtvenik; zaklaše ovnove i krvlju poškropiše žrtvenik, zaklaše jaganjce i krvlju poškropiše žrtvenik.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 29, 23, 'Dovedoše jarce za okajnicu pred kralja i pred zbor te metnuše ruke na njih.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 29, 24, 'Onda ih zaklaše svećenici i prinesoše kao okajnicu njihovu krv na žrtveniku da izvrše obred pomirenja za sav Izrael, jer kralj bijaše zapovjedio da se prinese paljenica i okajnica za sav Izrael.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 29, 25, 'Postavio je u Jahvinu Domu levite s cimbalima, harfama i citrama, kako bijaše zapovjedio David, kraljev vidjelac Gad i prorok Natan, jer je od Jahve dolazila zapovijed po njegovim prorocima.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 29, 26, 'Tako su leviti stajali s Davidovim glazbalima, a svećenici s trubama.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 29, 27, 'Tada Ezekija zapovjedi da prinesu paljenice na žrtveniku. Kad se stala prinositi paljenica, počela je Jahvina pjesma uz trube i uz glazbala izraelskoga kralja Davida.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 29, 28, 'Sav se zbor klanjao, pjevači pjevali, a trubači trubili, i to sve dok se nije svršila paljenica.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 29, 29, 'Kad se svršilo prinošenje paljenice, kralj i svi koji bijahu s njim pobožno padoše na koljena i pokloniše se.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 29, 30, 'Onda su kralj i knezovi zapovjedili levitima da hvale Jahvu riječima Davida i vidioca Asafa; oni su počeli hvaliti s najvećim veseljem i, pavši ničice, poklonili se.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 29, 31, 'Tada Ezekija progovori: \"Sada ste posvetili ruke Jahvi; pristupite i donesite klanice i zahvalnice u Dom Jahvin.\" Sav je zbor donio klanice i zahvalnice. Tko je god bio spremna srca, prinio je paljenice.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 29, 32, 'Paljenica što ih je donio zbor bijaše na broj: sedamdeset goveda, sto ovnova, dvjesta jaganjaca, sve za paljenice Jahvi.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 29, 33, 'Ostalih posvećenih darova bilo je šest stotina goveda i tri tisuće grla sitne stoke.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 29, 34, 'Ali je svećenika bilo premalo, tako da nisu mogli oderati svih paljenica; zato su im pomagala braća leviti, dok se nije svršio posao i dok se nisu posvetili drugi svećenici, jer su leviti bili gorljiviji srcem da se posvete nego svećenici.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 29, 35, 'Bilo je i mnogo paljenica s pretilinom od pričesnica i s ljevanicama na paljenice. Tako se opet obnovila služba u Jahvinu Domu.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 29, 36, 'I Ezekija se veselio, i sav narod s njime, što je Bog spremio narodu, jer se sve to iznenada dogodilo.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 30, 1, 'Potom Ezekija poruči svim Izraelcima i Judejcima pa napisa i pisma Efrajimovu i Manašeovu plemenu da dođu u Jahvin Dom u Jeruzalem da proslave Pashu Jahvi, Izraelovu Bogu.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 30, 2, 'Kralj, vijećajući s knezovima i sa svim zborom u Jeruzalemu, odluči da slave Pashu drugoga mjeseca.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 30, 3, 'Toga nisu mogli učiniti u pravo vrijeme jer nije bilo dosta posvećenih svećenika, i narod se ne bijaše skupio u Jeruzalemu.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 30, 4, 'I to je bilo prÓavo u kraljevim očima i u očima svega zbora,');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 30, 5, 'pa su odredili da se oglasi po svem Izraelu od Beer Šebe pa do Dana da dođu i proslave Pashu Jahvi, Izraelovu Bogu, u Jeruzalemu, jer je premnogi nisu svetkovali kako je propisano.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 30, 6, 'Tako su otišli glasnici s pismima od kralja i njegovih knezova po svem Izraelu i Judi te su govorili po kraljevoj zapovijedi: \"Izraelovi sinovi, obratite se Jahvi, Abrahamovu, Izakovu i Izraelovu Bogu, pa će se i on obratiti k Ostatku koji vam je ostao od ruku asirskih kraljeva.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 30, 7, 'I nemojte biti kao vaši očevi i vaša braća, koji su se iznevjerili Jahvi, Bogu svojih otaca, te ih je predao propasti, kako i sami vidite.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 30, 8, 'Nemojte, dakle, biti tvrdovrati kao vaši očevi: pružite ruku Jahvi i dođite u njegovu Svetinju koju je posvetio zauvijek i služite Jahvi, svome Bogu, pa će odvratiti od vas svoj žestoki gnjev.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 30, 9, 'Ako se obratite Jahvi, vaša će braća i vaši sinovi naći milost u onih koji su ih zarobili pa će se vratiti u ovu zemlju; jer je Jahve, vaš Bog, milostiv i milosrdan i neće odvratiti lica od vas ako se vi obratite njemu.\"');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 30, 10, 'I tako su glasnici krenuli od grada do grada po Efrajimovoj i Manašeovoj zemlji pa do Zebuluna, a ljudi im se podsmijavali i rugali.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 30, 11, 'Ipak su se neki od Ašerova, od Manašeova i od Zebulunova plemena ponizili i došli u Jeruzalem.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 30, 12, 'Na Judejce je pak sišla Božja ruka i prožela ih jednodušnošću da čine što bijaše zapovjedio kralj i knezovi po Jahvinoj riječi.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 30, 13, 'Skupilo se u Jeruzalemu mnogo naroda da slave Blagdan beskvasnih kruhova, drugoga mjeseca; zbor je bio vrlo velik.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 30, 14, 'Tada su ustali i uklonili žrtvenike što su bili u Jeruzalemu, uklonili sve kadionike i bacili ih u potok Kidron.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 30, 15, 'Onda su stali klati Pashu četrnaestoga dana drugoga mjeseca, a svećenici i leviti postidjeli se i, posvetiv se, počeli unositi paljenice u Jahvin Dom.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 30, 16, 'Stali su na svoje mjesto po pravilu, po Zakonu Mojsija, čovjeka Božjeg; svećenici su škropili krvlju primajući je iz ruku levita.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 30, 17, 'Kako ih bijaše mnogo u zboru koji se nisu posvetili, leviti su klali pashalne jaganjce za sve koji nisu bili čisti, da bi ih posvetili Jahvi.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 30, 18, 'Najveći se dio naroda, mnogi od Efrajimova i Manašeova, Jisakarova i Zebulunova plemena, nije očistio te je jeo Pashu nepropisno. Ali se za njih pomolio Ezekija govoreći: \"Blagi Jahve neka očisti od grijeha svakoga');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 30, 19, 'tko je upravio srce da traži Boga Jahvu, Boga svojih otaca, ako i nije čist kako dolikuje Svetištu!\"');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 30, 20, 'Jahve je uslišio Ezekiju i oprostio narodu.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 30, 21, 'Tako su Izraelovi sinovi koji su se zatekli u Jeruzalemu svetkovali Blagdan beskvasnih kruhova sedam dana s velikim veseljem, a leviti i svećenici hvalili Jahvu iz dana u dan uz glazbala za Jahvinu slavu.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 30, 22, 'Ezekija je hrabrio levite koji su pokazivali divnu privrženost Jahvi. Jeli su svečanu žrtvu sedam dana, žrtvujući žrtve pričesnice i slaveći Jahvu, Boga svojih otaca.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 30, 23, 'Potom je sav zbor vijećajući odlučio da svetkuje još sedam dana; svetkovali su još sedam dana s veseljem.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 30, 24, 'Judejski kralj Ezekija darovao je zboru tisuću mladih junaca i sedam tisuća grla sitne stoke; a knezovi darivali zboru tisuću mladih junaca i deset tisuća grla sitne stoke; tada se posvetilo mnogo svećenika.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 30, 25, 'Tako se proveselio sav judejski zbor, i svećenici i leviti, i sav zbor što je bio došao iz Izraela, i došljaci koji bijahu došli iz zemlje izraelske, i stanovnici u Judeji.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 30, 26, 'Bilo je veliko veselje u Jeruzalemu, jer od vremena Davidova sina Salomona, izraelskoga kralja, nije bilo tako u Jeruzalemu.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 30, 27, 'Onda su ustali svećenici i leviti te blagoslovili narod: njihov je glas bio uslišan, a njihova je molitva doprla do Božjega svetog Prebivališta na nebu.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 31, 1, 'Kad se sve to svršilo, svi Izraelovi sinovi koji su se našli ondje zađoše po judejskim gradovima te su razbijali stupove, sjekli ašere i obarali uzvišice i žrtvenike po svem Judinu, Benjaminovu, Efrajimovu i Manašeovu plemenu dokle god nisu završili. Onda se svi Izraelovi sinovi vratiše svaki na svoj posjed, u svoje gradove.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 31, 2, 'Ezekija je opet uredio svećeničke i levitske redove po njihovim redovima, svakoga prema njegovoj službi, svećenike i levite, za paljenice i za pričesnice, da služe, slave i hvale Boga na vratima Jahvina tabora.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 31, 3, 'Odredio je kraljevski doprinos od svoga imanja za paljenice, za paljenice jutarnje i večernje i za paljenice što se prinose subotom, za mlađaka i na blagdane, kako je napisano u Zakonu Jahvinu.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 31, 4, 'Zapovjedio je narodu, jeruzalemskim stanovnicima, da daju dio svećenicima i levitima da se utvrde u Zakonu Jahvinu.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 31, 5, 'Kad se to razglasilo, počeli su Izraelovi sinovi donositi najboljega žita, novog vina, ulja i meda i svakojaka poljskog priroda i donosili su obilne desetine od svega.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 31, 6, 'Izraelovi i Judini sinovi, koji su živjeli u judejskim gradovima, također su donosili desetinu od goveda i sitne stoke i desetinu od svetih stvari posvećenih Jahvi, njihovu Bogu; donosili su i davali sve hrpu na hrpu.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 31, 7, 'Trećega su mjeseca počeli slagati u hrpe, a sedmoga su mjeseca završili.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 31, 8, 'Onda je došao Ezekija s knezovima i, ugledavši hrpe, blagosloviše Jahvu i njegov izraelski narod.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 31, 9, 'Potom se Ezekija propitao kod svećenika i levita za hrpe.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 31, 10, 'Odgovarajući, svećenički poglavar Azarja, od Sadokova doma, reče: \"Otkako su počeli donositi ove prinose u Dom Jahvin, jedemo i siti smo, a mnogo i pretječe, jer je Jahve blagoslovio svoj narod te je preteklo ovo mnoštvo.\"');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 31, 11, 'Tada Ezekija zapovjedi da se urede sobe u Jahvinu Domu; kad su ih spremili,');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 31, 12, 'počeli su onamo unositi prinose, desetine i svetinje; nad tim je bio predstojnik levit Konanija i brat mu Šimej, drugi do njega.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 31, 13, 'A Jehiel, Azazja, Nahat, Asahel, Jerimot, Jozabad, Eliel, Jismakja, Mahat i Benaja biše postavljeni kao nadglednici uz Konaniju i brata mu Šimeja, po nalogu kralja Ezekije i Azarje, predstojnika u Božjem Domu.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 31, 14, 'Kore, sin levita Jimne, vratar Istočnih vrata, bio je nad dragovoljnim Božjim prinosima da bi prinosio Jahvine podizanice i svetinje nad svetinjama.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 31, 15, 'Pod njim su bili Eden, Minjamin, Ješua, Šemaja, Amarja i Šekanija po svećeničkim gradovima da savjesno dijele svojoj braći po njihovim redovima, kako velikome tako i malome -');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 31, 16, 'osim muškaraca starijih od trideset godina popisanih u rodovnicima - svima koji su dolazili u Dom Jahvin na svoj svakidašnji posao da obave obredne dužnosti po svojim redovima.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 31, 17, 'U rodovnike su bili popisani svećenici po obiteljima i leviti od dvadeset godina naviše po svojim službama, po svojim redovima.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 31, 18, 'U rodovnike bijahu popisana sva njihova djeca, njihove žene, njihovi sinovi i njihove kćeri, za svekoliki zbor, jer su se iskreno posvetili svetinjama.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 31, 19, 'Aronovi sinovi, svećenici na poljskim pašnjacima svojih gradova, u svakom pojedinom gradu, bijahu poimence određeni da daju dio svakome muškarcu među svećenicima. Sve su rodovnike sastavili leviti.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 31, 20, 'Ezekija je uradio tako po svoj Judeji čineći što je dobro, pravo i vjerno pred Jahvom, svojim Bogom.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 31, 21, 'U svakom poslu koji je počeo za službu Božjega Doma, i u zakonu i u zapovijedi tražeći Boga, trudio se svim svojim srcem i uspijevao.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 32, 1, 'Poslije tih događaja i dokaza vjernosti dođe asirski kralj Sanherib i, ušavši u Judeju, opkoli tvrde gradove misleći ih osvojiti.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 32, 2, 'Ezekija, vidjevši gdje je došao Sanherib i kako snuje da zavojšti na Jeruzalem,');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 32, 3, 'posavjetova se s knezovima i s junacima da začepi vodene izvore koji bijahu izvan grada. Oni mu podupriješe osnovu.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 32, 4, 'Sabralo se mnogo naroda te su začepili sva vrela i potok koji teče posred zemlje; govorahu: \"Zašto da asirski kraljevi nađu toliko vode kad dođu!\"');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 32, 5, 'Ezekija se osokolio, obnovio sav oboreni zid i podigao kule na njemu; izvana je sagradio drugi zid i utvrdio Milon u Davidovu gradu; napravio je mnogo kopalja i štitova,');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 32, 6, 'zatim postavio vojvode nad narodom i, pozvavši ih k sebi na trg kraj gradskih vrata, ohrabri ih ovim riječima:');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 32, 7, '\"Budite hrabri i junaci; ne bojte se i ne plašite se asirskoga kralja, ni svega mnoštva što je s njim, jer je s nama moćniji nego s njim:');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 32, 8, 's njim je tjelesna mišica, a s nama je Jahve, Bog naš, da nam pomaže i da bije naše bojeve.\" Narod se uzda u riječi judejskoga kralja Ezekije.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 32, 9, 'Poslije toga asirski je kralj Sanherib, dok bijaše kod Lakiša sa svom bojnom silom, poslao sluge u Jeruzalem k judejskome kralju Ezekiji i k svim Judejcima koji bijahu u Jeruzalemu i poručio im:');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 32, 10, '\"Ovako veli asirski kralj Sanherib: \'U što se uzdate stojeći opsjednuti u Jeruzalemu?');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 32, 11, 'Ne zavodi li vas Ezekija da vas preda smrti od gladi i žeđi kad govori: Jahve, Bog naš, izbavit će nas iz ruke asirskoga kralja?');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 32, 12, 'Nije li taj Ezekija uklonio njegove uzvišice i njegove žrtvenike; i zapovjedio Judejcima i Jeruzalemcima govoreći: Pred jednim se žrtvenikom klanjajte i na njemu kadite!');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 32, 13, 'Zar ne znate što sam učinio ja i moji preci od svih zemaljskih naroda? Zar su bogovi zemaljskih naroda mogli izbaviti svoje zemlje iz moje ruke?');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 32, 14, 'Koji je među svim bogovima onih naroda što su ih sasvim uništili moji preci mogao izbaviti narod iz moje ruke, da bi mogao vaš Bog izbaviti vas iz moje ruke?\'');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 32, 15, 'Zato nemojte da vas sada Ezekija vara i da vas tako zavodi i ne vjerujte mu! Jer nijedan bog nikojega naroda ili kraljevstva nije mogao izbaviti svoga naroda iz moje ruke, ni iz ruke mojih predaka, a kamoli će vaš Bog izbaviti vas iz moje ruke!\"');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 32, 16, 'Još su više njegove sluge napadale Boga Jahvu i njegova slugu Ezekiju.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 32, 17, 'Napisao je i pismo ružeći Jahvu, Izraelova Boga: \"Kao što bogovi zemaljskih naroda nisu izbavili svojih naroda iz moje ruke, tako neće ni Ezekijin Bog izbaviti svojega naroda iz moje ruke.\"');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 32, 18, 'I vikahu iza glasa, na judejskom jeziku, jeruzalemskom narodu koji bijaše na zidu da ga uplaše i prepadnu kako bi osvojili grad.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 32, 19, 'Govorili su o jeruzalemskom Bogu kao o bogovima zemaljskih naroda, bogovima koji su djelo čovječjih ruku.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 32, 20, 'Stoga se pomoli kralj Ezekija i prorok Izaija, Amosov sin, i zazvaše nebo u pomoć.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 32, 21, 'Tada Jahve posla anđela koji uništi sve hrabre junake, zapovjednike i vojvode u vojsci asirskoga kralja, tako da se vratio posramljen u svoju zemlju. A kad je ušao u hram svoga boga, sasjekli su ga ondje mačem neki koji su se rodili iz njegova krila.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 32, 22, 'Tako je Jahve spasio Ezekiju i jeruzalemske stanovnike od ruke asirskoga kralja Sanheriba i iz ruku neprijatelja, te im dao mir odasvud uokolo.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 32, 23, 'Mnogi su donosili darove Jahvi u Jeruzalem i dragocjenosti judejskome kralju Ezekiji. Poslije toga Ezekija se uzvisio u očima svih naroda.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 32, 24, 'U to se vrijeme Ezekija razbolio nasmrt, ali se pomolio Jahvi, koji mu je progovorio i učinio čudo.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 32, 25, 'Ali se Ezekija nije odužio dobročinstvu koje mu je iskazano, nego se uzoholio; stoga je došla srdžba na nj, na Judu i na Jeruzalem.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 32, 26, 'Ezekija se ponizio zato što mu se bilo uzoholilo srce, i on i Jeruzalemci, pa tako nije došla na njih Jahvina srdžba za Ezekijina života.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 32, 27, 'Ezekija je stekao vrlo veliko bogatstvo i slavu; napravio je riznice za srebro i zlato, za drago kamenje, za miomirise, za štitove i za svakojake dragocjene posude;');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 32, 28, 'skladište za prirod od žita, od novog vina i ulja, staje za svakojaku stoku, torove za stada.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 32, 29, 'Podigao je i gradove, imao je mnogo blaga, sitne stoke i goveda, jer mu je Bog dao vrlo veliko imanje.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 32, 30, 'Isti je Ezekija začepio gornji izvor Gihonske vode i svrnuo je pravo na zapadnu stranu Davidova grada. Ezekija je bio sretan u svakom poslu.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 32, 31, 'Samo kad su došli poslanici babilonskih knezova, poslani k njemu da se propitaju za čudo koje se dogodilo u zemlji, ostavio ga je Bog da bi ga iskušao i da bi se doznalo sve što mu je u srcu.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 32, 32, 'Ostala Ezekijina djela, njegova pobožnost, zapisani su u proročkom viđenju proroka Izaije, Amosova sina, i u Knjizi o judejskim i izraelskim kraljevima.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 32, 33, 'Ezekija je počinuo kod svojih otaca. Sahranili su ga na usponu kako se ide ka grobovima Davidovih sinova. Po smrti su mu odali počast svi Judejci i Jeruzalemci. Na njegovo se mjesto zakraljio sin mu Manaše.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 33, 1, 'Manašeu je bilo dvanaest godina kad se zakraljio. Pedeset i pet godina kraljevao je u Jeruzalemu.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 33, 2, 'Činio je što je zlo u Jahvinim očima, povodeći se za gnusobama naroda što ih je Jahve protjerao pred sinovima Izraelovim.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 33, 3, 'Obnovio je uzvišice što ih bijaše oborio otac mu Ezekija, podigao je žrtvenike Baalu, načinio ašere i stao se klanjati svoj nebeskoj vojsci i služiti joj.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 33, 4, 'Podigao je žrtvenike i u Domu Jahvinu, za koji bijaše rekao Jahve: \"U Jeruzalemu će prebivati Ime moje zauvijek.\"');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 33, 5, 'Sagradio je žrtvenike svoj nebeskoj vojsci u oba predvorja Doma Jahvina.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 33, 6, 'I sinove je svoje proveo kroz oganj u dolini Hinomova sina. Vračao je, gatao, čarao, stvorio bajače i opsjenare i uopće učinio premnogo zla u Jahvinim očima razjarujući ga.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 33, 7, 'Načinio je idolski lik i posadio ga u Domu Božjem, za koji Bog bijaše rekao Davidu i njegovu sinu Salomonu: \"U ovom Domu i u Jeruzalemu, koji sam izabrao među svim izraelskim plemenima, postavit ću Ime svoje zauvijek.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 33, 8, 'Neću više dati da noga Izraelaca uzmakne iz zemlje koju sam dao u baštinu vašim očevima, samo ako budu držali i provodili u djelo sve što sam im zapovjedio: sav Zakon, uredbe i običaje dane preko Mojsija.\"');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 33, 9, 'Ali je Manaše zaveo Judejce i Jeruzalemce te su radili još gore nego narodi što ih je Jahve iskorijenio pred sinovima Izraelovim.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 33, 10, 'Jahve je opominjao Manašea i njegov narod, ali oni nisu poslušali.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 33, 11, 'Stoga je Jahve doveo na njih vojskovođe asirskoga kralja. Uhvativši Manašea kukama, svezali su ga u dvoje mjedene verige i odveli u Babilon.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 33, 12, 'Kad se našao u nevolji, počeo se moliti za milost Jahvi, svome Bogu, ponizivši se veoma pred Bogom otaca.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 33, 13, 'Molio se i Bog mu se smilovao te usliša njegovu prošnju i vrati ga u Jeruzalem u kraljevstvo. Manaše tada spozna da je Jahve Bog.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 33, 14, 'Poslije toga sagradio je vanjski zid Davidovu gradu zapadno od Gihona, od doline pa do Ribljih vrata, i opasao zidom Ofel, izvevši ga vrlo visoko. Postavio je bojne vojvode u svim tvrdim gradovima u Judi.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 33, 15, 'Osim toga, uklonio je iz Jahvina Doma tuđinske bogove, onaj idolski lik i sve žrtvenike što ih bijaše posagradio na gori Jahvina Doma i u Jeruzalemu i sve ih baci izvan grada.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 33, 16, 'Zatim opet podiže Jahvin žrtvenik i žrtvova na njemu žrtve pričesnice i zahvalnice. Zapovjedi i Judejcima da služe Jahvi, Bogu Izraelovu.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 33, 17, 'Ipak je narod još žrtvovao po uzvišicama, ali samo Jahvi, svojem Bogu.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 33, 18, 'Ostala Manašeova djela i njegova molitva Bogu, riječi koje su mu govorili vidioci u ime Jahve, Izraelova Boga, zapisane su u Povijesti izraelskih kraljeva.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 33, 19, 'Njegova molitva i kako je bio uslišan, svi njegovi grijesi i njegova nevjera te mjesta na kojima je pogradio uzvišice, podigao ašere i idole prije nego što se ponizio - sve je to zapisano u povijesti Hozajevoj.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 33, 20, 'Tada Manaše počinu kraj svojih otaca. Sahranili su ga u dvoru. Na njegovo se mjesto zakraljio sim mu Amon.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 33, 21, 'Dvadeset su i dvije godine bile Amonu kad se zakraljio, a kraljevao je dvije godine u Jeruzalemu.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 33, 22, 'Činio je što je zlo u Jahvinim očima, kao i otac mu Manaše, jer je svim idolima koje bijaše načinio njegov otac Manaše on prinosio žrtve i služio im.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 33, 23, 'Ali se nije ponizio pred Jahvom kako se ponizio otac mu Manaše, nego je još i umnožio svoju krivicu.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 33, 24, 'Tada se protiv njega urotiše njegove sluge i ubiše ga u dvoru.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 33, 25, 'Ali je prosti puk pobio sve one koji se bijahu urotili protiv kralja Amona i na njegovo mjesto zakraljio sina mu Jošiju.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 34, 1, 'Jošiji je bilo osam godina kad se zakraljio. Kraljevao je trideset i jednu godinu u Jeruzalemu.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 34, 2, 'Činio je što je pravo u Jahvinim očima. U svemu je hodio putovima oca Davida, ne skrećući ni desno ni lijevo.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 34, 3, 'Osme godine kraljevanja, dok još bijaše dječak, počeo je tražiti Boga oca Davida, a dvanaeste je godine stao čistiti Judeju i Jeruzalem od uzvišica, ašera, od rezanih i livenih likova.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 34, 4, 'Pred njim su oborili žrtvenike Baalu, polomio je sunčane stupove koji bijahu na njima; izlomio je i satro ašere i rezane i livene likove, prosuo ih po grobovima onih što su im prinosili žrtve.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 34, 5, 'Svećeničke je kosti spalio na njihovim žrtvenicima i tako očistio Judeju i Jeruzalem.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 34, 6, 'Isto je učinio i po gradovima Manašeova, Efrajimova i Šimunova plemena, pa do Naftalijeva, po njihovim opustošenim mjestima unaokolo.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 34, 7, 'Oborio je žrtvenike i ašere, raskovao i satro rezane likove i isjekao sve sunčane stupove po svoj zemlji izraelskoj, a onda se vratio u Jeruzalem.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 34, 8, 'Osamnaeste godine kraljevanja, očistivši zemlju i Dom, posla Asalijahina sina Šafana, gradskoga upravitelja Maaseju, Johazova sina Joaha, tajnika, da poprave Dom Jahve, njegova Boga.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 34, 9, 'Oni su došli k velikom svećeniku Hilkiji i predali mu novce donesene u Božji Dom, koje bijahu sabrali leviti, čuvari hramskog praga, iz ruke Manašeovih i Efrajimovih sinova i od svega Izraelova Ostatka, od svega Judina i Benjaminova plemena, od jeruzalemskih stanovnika.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 34, 10, 'Dali su to na ruku poslovođama, postavljenim nad Domom Jahvinim, a oni su izdavali poslenicima koji su radili u Domu Jahvinu, popravljajući što je bilo trošno i obnavljajući Hram.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 34, 11, 'Dali su drvodjeljama i graditeljima da kupuju tesanac i drvo za grede i da se pobrvnaju kuće koje bijahu porušili judejski kraljevi.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 34, 12, 'Ti su ljudi savjesno obavljali posao; nad njima su bili postavljeni Jahat i Obadja, leviti od Merarijevih sinova, i Zaharija i Mešulam od Kehatovih sinova da upravljaju radom. Svi su leviti bili vični glazbalima.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 34, 13, 'Jedni su bili nad bremenošama i nadstojnicima svih poslenika u svakoj službi, a drugi su od levita bili pisari, nadzornici i vratari.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 34, 14, 'Kad su iznosili novce donesene u Jahvin Dom, našao je svećenik Hilkija Knjigu Zakona Jahvina, danu preko Mojsija.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 34, 15, 'I, progovorivši, Hilkija reče tajniku Šafanu: \"Našao sam Knjigu Zakona u Domu Jahvinu.\" Hilkija dade knjigu Šafanu.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 34, 16, 'Šafan odnese knjigu kralju i izvjesti ga: \"Tvoje sluge rade sve što im se povjerilo.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 34, 17, 'Izasuvši novce što su se našli u Domu Jahvinu, dadoše ih na ruku poslovođama i poslenicima.\"');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 34, 18, 'Tada tajnik Šafan javi kralju: \"Svećenik Hilkija dade mi jednu knjigu.\" I Šafan je poče čitati pred kraljem.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 34, 19, 'Čuvši riječi Zakona, kralj razdrije haljine svoje.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 34, 20, 'I naredi Hilkiji, Šafanovu sinu Ahikamu, Mikinu sinu Abdonu, tajniku Šafanu i kraljevu sluzi Asaji:');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 34, 21, '\"Idite i upitajte Jahvu o meni i Ostatku Izraela i Judeje zbog ove knjige što je nađena, jer je velika Jahvina jarost što se izlila na nas zato što naši očevi nisu čuvali Jahvine riječi, nisu vršili što je pisano u knjizi.\"');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 34, 22, 'Hilkija s kraljevim ljudima ode proročici Huldi, ženi Šaluma, Tokhatova sina, sina Hasre, čuvara odjeće; ona je živjela u Jeruzalemu, u novom gradu. Kad joj to kazaše,');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 34, 23, 'ona im reče: \"Ovako veli Jahve, Bog Izraelov: \'Kažite čovjeku koji vas je poslao k meni:');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 34, 24, 'Ovako veli Jahve: Evo, dovest ću nesreću na ovaj grad i na njegove stanovnike, izvršit ću sve kletve napisane u knjizi što je pročitaše pred judejskim kraljem.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 34, 25, 'Jer su me ostavili i kadili tuđim bogovima da bi me ljutili svim djelima ruku svojih, planut će jarost moja na to mjesto i neće se ugasiti.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 34, 26, 'A judejskome kralju, koji vas je poslao po Jahvin savjet, recite ovo: Ovako govori Jahve, Bog Izraelov: Riječi si čuo.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 34, 27, 'Ali kako ti je omekšalo srce i jer si se ponizio pred Bogom čuvši što sam objavio tome gradu i njegovim stanovnicima, i ponizivši se preda mnom, razdro si haljine i plakao, zato sam te uslišio - riječ je Jahvina!');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 34, 28, 'Evo, sjedinit ću te s ocima tvojim i s mirom ćeš leći u grob da ne vidiš svu nesreću koju ću svaliti na ovo mjesto i njegove stanovnike.\'\" Oni odnesoše taj odgovor kralju.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 34, 29, 'Tada posla kralj da se saberu sve judejske i jeruzalemske starješine.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 34, 30, 'Kralj se potom pope u Dom Jahvin, sa svim Judejcima, Jeruzalemcima, svećenicima, levitima i sa svim narodom, od najvećega do najmanjeg. I pročita im sve riječi Knjige Saveza što je nađena u Domu Jahvinu.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 34, 31, 'Kralj, stojeći na svome mjestu, obnovi pred Jahvom Savez da će slijediti Jahvu, držati se njegovih zapovijedi, pouka i uredaba svim srcem i svom dušom da bi izvršio sve stavke toga Saveza što su napisane u knjizi.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 34, 32, 'I sve koji su se našli u Jeruzalemu i Benjaminovu plemenu pozva da pristupe; i Jeruzalemci prionuše uza Savez Boga, Boga svojih otaca.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 34, 33, 'Tada Jošija ukloni sve gnusobe iz svih izraelskih krajeva i učini te svi koji su se našli u Izraelu počeše služiti Jahvi, svojem Bogu. Za svega njegova života nisu odstupili od Jahve, Boga svojih otaca.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 35, 1, 'Potom je Jošija svetkovao Pashu Jahvi u Jeruzalemu: klalo se pashalno jagnje četrnaestoga dana prvoga mjeseca.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 35, 2, 'Postavio je svećenike na njihove službe, osokolivši ih na službu u Jahvinu Domu.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 35, 3, 'Zatim je rekao levitima koji su poučavali sve Izraelce i bili posvećeni Jahvi: \"Metnite sveti Kovčeg u Dom koji je sagradio Davidov sin Salomon, izraelski kralj; ne smijete ga više nositi na ramenima; sada služite Jahvi, svojem Bogu, i njegovu izraelskom narodu!');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 35, 4, 'I pripravite se po otačkim domovima, po redovima, kako je napisao izraelski kralj David i propisao sin mu Salomon.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 35, 5, 'Stojte u Svetinji po redovima otačkih domova svoje braće, običnoga puka, i po redu levitskoga otačkog doma.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 35, 6, 'I tako koljite pashalno janje te se posvetite i pripravite svoju braću da svetkuju kako je zapovjedio Jahve preko Mojsija.\"');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 35, 7, 'Jošija je darovao običnom puku od sitne stoke jaganjaca i jarića, sve za Pashu, svima koji su se našli ondje, na broj trideset tisuća, i tri tisuće goveda, sve to s kraljeva imanja.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 35, 8, 'Njegovi su knezovi dragovoljno darovali narodu, svećenicima i levitima, i to: Hilkija, Zaharija i Jehiel, predstojnici u Božjem Domu, dali su svećenicima za Pashu dvije tisuće i šest stotina jaganjaca i jarića i tri stotine goveda.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 35, 9, 'A Konanija, Šemaja i Netanel, njegova braća Hašabja, Jehiel i Jozabad, levitski knezovi, darovali su levitima za Pashu pet tisuća grla sitne stoke i pet stotina goveda.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 35, 10, 'A kad je bila uređena služba, stali su svećenici na svoje mjesto i leviti u svojim redovima po kraljevoj zapovijedi.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 35, 11, 'Klali su Pashu, a svećenici su škropili krvlju, dok su leviti odirali kožu.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 35, 12, 'Onda su pripravili paljenice da ih dadu običnom puku po redovima otačkih domova da ih prinese Jahvi, kako je napisano u Mojsijevoj knjizi. Tako su učinili i s govedima.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 35, 13, 'Pekli su Pashu na ognju po običaju, a ostale su posvećene stvari kuhali u loncima, kotlovima i zdjelama i brzo ih raznosili svemu običnom puku.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 35, 14, 'Poslije su pripravljali Pashu sebi i svećenicima, jer su svećenici, Aronovi sinovi, bili zaposleni prinošenjem paljenica i pretiline do noći; zato su leviti pripravljali sebi i svećenicima, Aronovim sinovima.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 35, 15, 'A pjevači, Asafovi sinovi, stajali su na svojem mjestu, kako je bio zapovjedio David, Asaf, Heman i kraljev vidjelac Jedutun. Vratari su stajali na svakim vratima; oni se nisu micali od službe, nego su im njihova braća leviti pripravljala sve.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 35, 16, 'Tako je bila uređena sva Jahvina služba onoga dana da se proslavi Pasha i da se prinesu paljenice na Jahvinu žrtveniku po zapovijedi kralja Jošije.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 35, 17, 'Tako su Izraelovi sinovi, koji su se našli ondje, u to doba sedam dana slavili Pashu i Blagdan beskvasnih kruhova.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 35, 18, 'Pasha kao ova u Izraelu nije se slavila od vremena proroka Samuela niti je ijedan od izraelskih kraljeva slavio Pashu kao što ju je slavio Jošija - sa svećenicima, levitima i sa svim Judejcima i Izraelcima, koliko ih se god našlo, i s Jeruzalemcima.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 35, 19, 'Ta se Pasha svetkovala osamnaeste godine Jošijina kraljevanja.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 35, 20, 'Poslije svega toga, kad je Jošija uredio Dom, došao je egipatski kralj Neko da se bije kod Karkemiša na Eufratu, a Jošija je izišao preda nj.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 35, 21, 'Kralj Neko poslao je Jošiji glasnike i poručio: \"Što ja imam s tobom, judejski kralju? Ne idem ja danas na tebe, nego na dom s kojim sam u ratu, i Bog mi je zapovjedio da se požurim. Okani se Boga koji je sa mnom da te ne upropastim!\"');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 35, 22, 'Ali Jošija nije odvratio lica od njega, nego se ojunačio da se bije s njim; ne poslušavši Nekovih riječi iz Božjih usta, došao je da se bije na Megidskom polju.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 35, 23, 'Strijelci ustrijeliše kralja Jošiju, a on reče slugama: \"Izvedite me jer sam teško ranjen.\"');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 35, 24, 'Sluge ga skinuše s bojnih kola i metnuše u druga kola koja je imao, pa ga odvezoše u Jeruzalem; ondje je umro i bio sahranjen u grobnici otaca. Sva Judeja s Jeruzalemom plakala je za Jošijom.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 35, 25, 'I Jeremija je protužio za Jošijom. I svi pjevači i pjevačice spominju u tužbalicama Jošiju do danas; uveli su ih u običaj u Izraelu, i eno su zapisane u Tužbalicama.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 35, 26, 'Ostala Jošijina djela i njegova pobožnost, vršeni onako kako piše u Jahvinu Zakonu,');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 35, 27, 'svi njegovi pothvati, od prvih do posljednjih, zapisani su u Knjizi o izraelskim i judejskim kraljevima.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 36, 1, 'Tada priprosti puk uze Jošijina sina Joahaza i zakralji ga u Jeruzalemu namjesto njegova oca.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 36, 2, 'Dvadeset i tri godine bile su Joahazu kad se zakraljio. Kraljevao je tri mjeseca u Jeruzalemu.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 36, 3, 'Svrgao ga je egipatski kralj u Jeruzalemu i udario na zemlju danak od sto srebrnih talenata i jedan zlatni talenat.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 36, 4, 'Egipatski kralj postavi za kralja nad Judejom i nad Jeruzalemom njegova brata Elijakima, promijenivši mu ime na Jojakim; njegova je brata Joahaza uzeo Neko i odveo u Egipat.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 36, 5, 'Dvadeset je i pet godina bilo Jojakimu kad se zakraljio. Kraljevao je jedanaest godina u Jeruzalemu; činio je što je zlo u očima Jahve, njegova Boga.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 36, 6, 'Na nj je zaratio babilonski kralj Nabukodonozor i, svezavši ga u dvoje mjedene verige, odveo ga u Babilon.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 36, 7, 'Dio posuđa iz Jahvina Doma odnio je Nabukodonozor u Babilon i metnuo ga u svoj dvorac u Babilonu.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 36, 8, 'Ostala Jojakimova djela i gnusobe koje je činio i što se na njemu našlo, sve je zapisano u Knjizi o izraelskim i judejskim kraljevima. Na njegovo se mjesto zakraljio sin mu Jojakin.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 36, 9, 'Osam je godina bilo Jojakinu kad se zakraljio, a kraljevao je tri mjeseca i deset dana u Jeruzalemu; činio je što je zlo u Jahvinim očima.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 36, 10, 'O godišnjoj je mijeni poslao kralj Nabukodonozor te su ga odveli u Babilon s dragocjenostima iz Jahvina Doma, a nad Judom i nad Jeruzalemom zakraljio je njegova rođaka Sidkiju.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 36, 11, 'Dvadeset je i jedna godina bila Sidkiji kad se zakraljio, a kraljevao je jedanaest godina u Jeruzalemu.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 36, 12, 'Činio je što je zlo u očima Jahve, njegova Boga; nije se ponizio pred prorokom Jeremijom, koji mu je govorio iz Jahvinih usta,');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 36, 13, 'nego se još i pobunio protiv kralja Nabukodonozora, koji ga bijaše zakleo Bogom; ostao je tvrdoglav i uporan u srcu da se ne obrati Jahvi, Bogu Izraelovu.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 36, 14, 'Pa i svi su svećenički poglavari i narod gomilali nevjeru na nevjeru slijedeći gnusna djela krivobožačkih naroda, oskvrnjujući Dom Jahvin, posvećen u Jeruzalemu.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 36, 15, 'Jahve, Bog njihovih otaca, slao je k njima zarana svoje glasnike, slao ih svejednako, jer mu bijaše žao svojega naroda i svojega Prebivališta.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 36, 16, 'Ali su se oni rugali Božjim glasnicima, prezirući njegove riječi i podsmjehujući se njegovim prorocima, dok se nije podigla Jahvina jarost na njegov narod te više nije bilo lijeka.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 36, 17, 'Doveo je na njih kaldejskoga kralja, koji okrenu pod mač njihove mladiće u domu njihova Svetišta, ne štedeći ni mladića ni djevojke, ni starca ni nemoćna.Sve mu je predao u ruke.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 36, 18, 'Sve posuđe Božjega Doma, veliko i malo, blago Jahvina Doma i kraljevo blago, blago njegovih knezova, sve je odnio u Babilon.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 36, 19, 'Spalili su Božji Dom, oborili jeruzalemski zid i sve su njegove dragocjenosti uništili.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 36, 20, 'One što izbjegoše maču odvede Nabukodonozor u Babilon u sužanjstvo. Postali su robovi njemu i njegovim sinovima, dokle nije nastalo perzijsko kraljevstvo.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 36, 21, 'Da bi se ispunila riječ koju Jahve reče na Jeremijina usta: \"Dokle se zemlja ne oduži svojim subotama, počivat će za sve vrijeme u pustoši dok se ne ispuni sedamdeset godina.\"');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 36, 22, 'Ali prve godine perzijskoga kralja Kira, da bi se ispunila riječ Jahvina objavljena na Jeremijina usta, podiže Jahve duh perzijskoga kralja Kira te on oglasi po svemu svojem kraljevstvu usmeno i pismeno:');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 36, 23, '\"Ovako veli perzijski kralj Kir: \'Sva zemaljska kraljevstva dade mi Jahve, Bog nebeski. On mi naloži da mu sagradim Dom u Jeruzalemu, u Judeji. Tko je god među vama od svega njegova naroda, Bog njegov bio s njim, pa neka ide onamo!\'\"');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (15, 1, 1, 'Prve godine perzijskoga kralja Kira, da bi se ispunila riječ Jahvina objavljena na Jeremijina usta, nadahnu Jahve perzijskoga kralja Kira te on objavi po svemu svojem kraljevstvu, usmeno i pismeno:');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (15, 1, 2, '\"Ovako veli perzijski kralj Kir: \'Sva zemaljska kraljevstva dade mi Jahve, Bog nebeski. On mi naloži da mu sagradim Dom u Jeruzalemu, u Judeji.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (15, 1, 3, 'Tko je god među vama od svega njegova naroda, Bog njegov bio s njim! Neka ide u Jeruzalem u Judeji i neka gradi Dom Jahvi, Bogu Izraelovu, Bogu koji stoluje u Jeruzalemu.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (15, 1, 4, 'I gdje god se još zadržao ostatak toga naroda, neka ga stanovništvo mjesta u kojima boravi podupre srebrom i zlatom, imanjem i stokom i dragovoljnim prinosima za Dom Božji u Jeruzalemu.\'\"');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (15, 1, 5, 'Tada ustadoše glavari obitelji Jude i Benjamina, svećenici i leviti, i svi kojima je Bog potaknuo duh i krenuše graditi Dom Jahvin u Jeruzalemu.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (15, 1, 6, 'I svi su im susjedi pomagali: srebrom, zlatom, darovima u naravi, stokom, dragocjenostima mnogim, osim svega što su dragovoljno prilagali.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (15, 1, 7, 'Kralj Kir iznese posuđe Jahvina Doma koje Nabukodonozor bijaše odnio iz Jeruzalema i stavio u hram svoga boga.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (15, 1, 8, 'Kir, kralj perzijski, uruči ga Mitredatu, rizničaru, koji ga izbroji judejskom knezu Šešbasaru.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (15, 1, 9, 'Evo njegova popisa. Zlatnih zdjela: trideset; srebrnih zdjela: tisuću i dvadeset devet;');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (15, 1, 10, 'zlatnih čaša: trideset; srebrnih čaša: četiri stotine i deset; ostalog posuđa: tisuću.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (15, 1, 11, 'Svega zlatnog i srebrnog posuđa: pet tisuća i četiri stotine. Sve je to odnio Šešbasar kada se sužnji vraćahu iz Babilona u Jeruzalem.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (15, 2, 1, 'Ovo su ljudi one pokrajine koji su se vratili iz sužanjstva u Babilonu, kamo ih bijaše odveo babilonski kralj Nabukodonozor. Vratili su se u Jeruzalem i Judeju, svaki u svoj grad.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (15, 2, 2, 'Stigli su oni i s njima Zerubabel, Ješua, Nehemija, Seraja, Reelaja, Nahamani, Mordokaj, Bilšan, Mispar, Bigvaj, Rehum i Baana. Evo popisa ljudi od naroda Izraelova:');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (15, 2, 3, 'sinovi Paroševi: dvije tisuće stotinu sedamdeset i dva;');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (15, 2, 4, 'sinovi Šefatjini: tri stotine sedamdeset i dva;');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (15, 2, 5, 'Arahovi sinovi: sedam stotina sedamdeset i pet;');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (15, 2, 6, 'sinovi Pahat-Moabovi, to jest sinovi Ješuini i Joabovi sinovi: dvije tisuće osam stotina i dvanaest;');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (15, 2, 7, 'Elamovi sinovi: tisuću dvije stotine pedeset i četiri;');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (15, 2, 8, 'sinovi Zatuovi: devet stotina četrdeset i pet;');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (15, 2, 9, 'Zakajevi sinovi: sedam stotina i šezdeset;');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (15, 2, 10, 'Banijevi sinovi: šest stotina četrdeset i dva;');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (15, 2, 11, 'Bebajevi sinovi: šest stotina dvadeset i tri;');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (15, 2, 12, 'sinovi Azgadovi: tisuću dvije stotine dvadeset i dva;');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (15, 2, 13, 'Adonikamovi sinovi: šest stotina šezdeset i šest;');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (15, 2, 14, 'sinovi Bigvajevi: dvije tisuće pedeset i šest;');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (15, 2, 15, 'Adinovi sinovi: četiri stotine pedeset i četiri;');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (15, 2, 16, 'sinovi Aterovi, od Ezekije: devedeset i osam;');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (15, 2, 17, 'Besajevi sinovi: tri stotine dvadeset i tri;');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (15, 2, 18, 'sinovi Jorini: stotinu i dvanaest;');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (15, 2, 19, 'Hašumovi sinovi: dvije stotine dvadeset i tri;');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (15, 2, 20, 'sinovi Gibarovi: devedeset i pet;');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (15, 2, 21, 'ljudi iz Betlehema: stotinu dvadeset i tri;');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (15, 2, 22, 'ljudi iz Netofe: pedeset i šest;');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (15, 2, 23, 'ljudi iz Anatota: stotinu dvadeset i osam;');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (15, 2, 24, 'ljudi iz Bet Azmaveta: četrdeset i dva;');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (15, 2, 25, 'ljudi iz Kirjat Jearima, Kefire i Beerota: sedam stotina četrdeset i tri;');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (15, 2, 26, 'ljudi iz Rame i Gebe: šest stotina dvadeset i jedan;');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (15, 2, 27, 'ljudi iz Mikmasa: stotinu dvadeset i dva;');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (15, 2, 28, 'ljudi iz Betela i Aja: dvije stotine dvadeset i tri;');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (15, 2, 29, 'nebonski sinovi: pedeset i dva;');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (15, 2, 30, 'sinovi Magbiša: stotinu pedeset i šest;');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (15, 2, 31, 'sinovi jednoga drugog Elama: tisuću dvije stotine pedeset i četiri;');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (15, 2, 32, 'Harimovi sinovi: tri stotine i dvadeset;');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (15, 2, 33, 'sinovi Loda, Hadida i Onona: sedam stotina dvadeset i pet;');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (15, 2, 34, 'sinovi Jerihona: tri stotine četrdeset i pet;');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (15, 2, 35, 'sinovi Senajini: tri tisuće šest stotina trideset.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (15, 2, 36, 'Svećenici: Jedajini sinovi, to jest iz kuće Ješuine: devet stotina sedamdeset i tri;');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (15, 2, 37, 'sinovi Imerovi: tisuću pedeset i dva;');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (15, 2, 38, 'Pašhurovi sinovi: tisuću dvije stotine četrdeset i sedam;');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (15, 2, 39, 'sinovi Harimovi: tisuću i sedamnaest.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (15, 2, 40, 'Leviti: sinovi Ješuini i Kadmielovi od Hodavjinovaca: sedamdeset i četiri.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (15, 2, 41, 'Pjevači: sinovi Asafovi: stotinu dvadeset i osam.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (15, 2, 42, 'Vratari: sinovi Šalumovi, sinovi Aterovi, sinovi Talmonovi, sinovi Akubovi, sinovi Hatitini i sinovi Šobajevi: u svemu stotinu trideset i devet.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (15, 2, 43, 'Netinci - sluge hramske: Sihini sinovi, sinovi Hasufini, sinovi Tabaotovi,');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (15, 2, 44, 'Kerosovi sinovi, Siahini sinovi, Fadonovi sinovi,');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (15, 2, 45, 'sinovi Lebanovi, sinovi Hagabini, sinovi Akubovi,');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (15, 2, 46, 'Hagabovi sinovi, Šamlajevi sinovi, Hananovi sinovi,');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (15, 2, 47, 'sinovi Gidelovi, sinovi Gaharovi, sinovi Reajini,');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (15, 2, 48, 'Resinovi sinovi, Nekodini sinovi, Gazamovi sinovi,');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (15, 2, 49, 'sinovi Uzini, sinovi Faseahini, sinovi Besajevi,');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (15, 2, 50, 'Asnanini sinovi, Meunimovi sinovi, Nefusimovi sinovi,');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (15, 2, 51, 'sinovi Bakbukovi, sinovi Hakufini, sinovi Harhurovi,');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (15, 2, 52, 'Baslutovi sinovi, Mehidini sinovi, Haršini sinovi,');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (15, 2, 53, 'sinovi Barkosovi, sinovi Sisrini, sinovi Tamahovi,');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (15, 2, 54, 'Nesiahovi sinovi, Hatifini sinovi.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (15, 2, 55, 'Sinovi slugu Salomonovih: sinovi Sotajevi, sinovi Hasoferetovi, sinovi Farudini,');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (15, 2, 56, 'Jalini sinovi, Darkonovi sinovi, Gidelovi sinovi,');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (15, 2, 57, 'sinovi Šefatjini, sinovi Hatilovi, sinovi Pokeret-Hasebajimovi, sinovi Amijevi.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (15, 2, 58, 'Svega netinaca i sinova slugu Salomonovih: tri stotine dvadeset i dva.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (15, 2, 59, 'Oni koji su pošli iz Tel Melaha, Tel Harše, Keruba, Adana, Imera, a nisu mogli dokazati da li je njihov dom i njihovo sjeme izraelskog podrijetla:');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (15, 2, 60, 'sinovi Dalajini, sinovi Tobijini, sinovi Nekodini - njih šest stotina pedeset i dva.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (15, 2, 61, 'A od svećeničkih sinova: Hobajini sinovi, Hakosovi sinovi, sinovi Barzilaja - onoga koji je uzeo za ženu jednu kćer Barzilaja Gileađanina te se prozvao tim imenom.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (15, 2, 62, 'Oni su tražili svoje rodoslovne popise, ali ih nisu našli. Bili su izlučeni iz svećeništva.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (15, 2, 63, 'I namjesnik im zabrani jesti od svetinja sve dok se ne pojavi svećenik za Urim i Tumim.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (15, 2, 64, 'Sav je zbor brojio četrdeset i dvije tisuće tri stotine i šezdeset duša,');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (15, 2, 65, 'ne računajući njihove sluge i sluškinje, kojih bijaše sedam tisuća tri stotine i sedam. Bijaše i dvije stotine pjevača i pjevačica.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (15, 2, 66, 'Njihovih je konja bilo sedam stotina trideset i šest, njihovih mazga dvije stotine četrdeset i pet,');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (15, 2, 67, 'deva je bilo četiri stotine trideset i pet, a njihovih magaraca ukupno šest tisuća sedam stotina i dvadeset.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (15, 2, 68, 'Stanovit broj obiteljskih glavara kad su stigli u Dom Jahvin, koji je u Jeruzalemu, dragovoljno su priložili darove za Dom Božji da bi se podigao na svome mjestu.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (15, 2, 69, 'Dali su prema svojim mogućnostima u riznicu šezdeset tisuća drahmi zlata, pet tisuća mina srebra i stotinu svećeničkih haljina.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (15, 2, 70, 'Svećenici, leviti i dio naroda nastaniše se u Jeruzalemu; a vratari, pjevači, netinci i svi ostali Izraelci u svojim gradovima.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (15, 3, 1, 'Kad je došao sedmi mjesec - sinovi su Izraelovi bili već u svojim gradovima - sabrao se sav narod kao jedan čovjek u Jeruzalemu.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (15, 3, 2, 'Tada Ješua, sin Josadakov, sa svojom braćom svećenicima, i Zerubabel, sin Šealtielov, sa svojom braćom, počeše graditi žrtvenik Bogu Izraelovu da bi prinosili paljenice, kako je pisano u Zakonu Mojsija, čovjeka Božjeg.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (15, 3, 3, 'I podigoše žrtvenik na starome mjestu - iako su bili u strahu od naroda u zemlji - i prinosili su paljenice Jahvi, paljenice jutarnje i večernje;');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (15, 3, 4, 'i slavili su Blagdan sjenica, kako je pisano: prinosili su svakodnevno broj paljenica propisan za svaki dan.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (15, 3, 5, 'Osim toga prinosili su svakidašnje paljenice, zatim žrtve određene za mlađak i za sve blagdane Jahvine i za sve one koji su htjeli dragovoljno žrtvovati Jahvi.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (15, 3, 6, 'Od prvoga dana u sedmom mjesecu počeli su prinositi Jahvi žrtve paljenice, premda još nisu bili položeni temelji svetišta Jahvina.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (15, 3, 7, 'I dadoše novac kamenarima i drvodjelcima; Sidoncima i Tircima poslaše hranu i piće i ulje da dovezu drva cedrova s Libanona do Jafe po dopuštenju perzijskoga kralja Kira.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (15, 3, 8, 'A druge godine poslije njihova dolaska k Domu Božjemu u Jeruzalemu, drugoga mjeseca kako su Zerubabel, sin Šealtielov, i Ješua, sin Josadakov, s ostalom svojom braćom svećenicima, levitima i sa svim narodom koji se iz ropstva vratio u Jeruzalem počeli graditi, postavili su levite od dvadeset godina naviše da upravljaju poslovima oko Doma Jahvina.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (15, 3, 9, 'Ješua, njegovi sinovi i braća njegova Kadmiel, Binuj i Hodavja bijahu postavljeni da kao jedan upravljaju poslenicima na gradnji Doma Božjega.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (15, 3, 10, 'Kad su zidari bili postavili temelje Svetišta Jahvina, postavili su se svećenici u svečanim odjećama, s trubama, a tako i leviti, sinovi Asafovi, s cimbalima da slave Jahvu prema odredbama Davida, kralja Izraelova.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (15, 3, 11, 'I pjevahu Jahvi hvalu i slavu: \"Jer je dobar, jer je vječna njegova ljubav prema Izraelu.\" I sav je narod klicao hvaleći Jahvu, jer je Dom Jahvin bio postavljen na svoje temelje.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (15, 3, 12, 'Zaista, mnogi svećenici, mnogi leviti i glavari obiteljski i starješine, koji su svojim očima vidjeli temelje prijašnjega Hrama, plakahu iza glasa, a mnogi opet snažno klicahu od radosti.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (15, 3, 13, 'I tako nitko nije mogao razlikovati radosno klicanje od plača u narodu; jer je narod glasno klicao i vika se čula vrlo daleko.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (15, 4, 1, 'Ali kada su čuli Judini i Benjaminovi neprijatelji da povratnici iz sužanjstva grade svetište Jahvi, Bogu Izraelovu,');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (15, 4, 2, 'potražiše Zerubabela, Ješuu i glavare obiteljske i rekoše im: \"Mi želimo s vama graditi, jer, kao i vi, tražimo Boga vašega i njemu prinosimo žrtve od vremena Esar Hadona, asirskoga kralja, koji nas je ovamo doveo.\"');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (15, 4, 3, 'Zerubabel, Ješua i glavari izraelskih obitelji odgovoriše im: \"Nije na vama da s nama gradite Dom našemu Bogu: gradit ćemo mi sami Jahvi, Bogu Izraelovu, kako nam je naredio Kir, kralj perzijski.\"');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (15, 4, 4, 'Tada je narod one zemlje plašio ljude Judeje i smetao im u gradnji.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (15, 4, 5, 'Podmitili su savjetnike da im ometaju naum: tako je bilo za vrijeme perzijskoga kralja Kira sve do perzijskoga kralja Darija. Samarijanske smetnje za Kserksove i Artakserksove vladavine');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (15, 4, 6, 'Za Kserksova kraljevanja, na početku njegove vladavine, sastaviše tužbu protiv stanovnika Judeje i Jeruzalema.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (15, 4, 7, 'I za vremena Artakserksova pisali su Bišlam, Mitredat, Tabel i ostali njihovi drugovi protiv Jeruzalema perzijskom kralju Artakserksu. Podnesak je bio pisan aramejskim pismom i jezikom.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (15, 4, 8, 'Zatim su upravitelj Rehum i tajnik Šimšaj napisali kralju Artakserksu slijedeće pismo protiv Jeruzalema -');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (15, 4, 9, 'upravitelj Rehum, tajnik Šimšaj i ostali drugovi njihovi: perzijski suci, poslanici, činovnici; Arkevajci, Babilonci, Suzanci - to jest Elamci -');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (15, 4, 10, 'i ostali narodi koje je veliki i slavni Asurbanipal bio odveo u sužanjstvo i naselio ih u gradove Samarije i druge krajeve s onu stranu Rijeke.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (15, 4, 11, 'Evo prijepisa pisma koje su mu poslali: \"Kralju Artakserksu, tvoje sluge, ljudi s onu stranu Rijeke. Sada, dakle,');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (15, 4, 12, 'neka zna kralj da su Judejci stigli k nama od tebe; došavši u Jeruzalem, žele ponovo sagraditi odmetnički i opaki grad; podižu zidine, a temelje su već postavili.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (15, 4, 13, 'Neka zna kralj: ako ovaj grad bude sagrađen i zidovi podignuti, neće se više plaćati porez, ni danak, ni carina, i ovaj će grad biti na štetu kraljevske riznice.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (15, 4, 14, 'Budući da jedemo dvorsku sol, ne čini nam se doličnim gledati ovu sramotu nanesenu kralju. Zato, dakle, obavještavamo kralja:');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (15, 4, 15, 'neka se poduzmu istraživanja u ljetopisima tvojih očeva: u tim ćeš ljetopisima naći i utvrditi da je ovaj grad odmetnički grad, nesretan za kraljeve i pokrajine i da su se u njemu od davnine dizale bune. Zato je ovaj grad bio razoren.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (15, 4, 16, 'Obavješćujemo kralja da neće biti više tvoje područje preko Rijeke ako ovaj grad bude ponovo sagrađen i zidovi podignuti!\"');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (15, 4, 17, 'Kralj je poslao ovaj odgovor: \"Rehumu, upravitelju, Šimšaju, tajniku, i ostalim drugovima njihovim koji borave u Samariji i drugdje, s onu stranu Rijeke - mir! Evo,');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (15, 4, 18, 'podnesak koji ste mi poslali bio je preda mnom pričitan u njegovu prijevodu.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (15, 4, 19, 'Po mojoj su naredbi poduzeli istraživanja i utvrdili da se taj grad dizao od davnine protiv kraljeva i da su u njemu bivali ustanci i bune.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (15, 4, 20, 'I moćni su kraljevi kraljevali u Jeruzalemu, koji su gospodarili svime s onu stranu Rijeke: njima se plaćao danak, porez i carina.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (15, 4, 21, 'Zapovjedite, dakle, da se prekine pothvat onih ljudi: taj se grad neće zidati dok ja o tome ne odlučim.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (15, 4, 22, 'Čuvajte se svakog propusta u postupku, da ne bi zlo poraslo na štetu kraljeva.\"');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (15, 4, 23, 'Pošto je prijepis otpisa kralja Artakserksa pročitan pred Rehumom, upraviteljem, Šimšajem, tajnikom, i pred njihovim drugovima, oni brzo odoše u Jeruzalem k Judejcima te im oružanom snagom zabraniše radove.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (15, 4, 24, 'Tako su obustavljeni poslovi oko gradnje Doma Božjega u Jeruzalemu. Bili su prekinuti sve do druge godine kraljevanja Darija, perzijskoga kralja.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (15, 5, 1, 'Tada su proroci Hagaj i Zaharija, sin Adonov, počeli prorokovati Judejcima u Judeji i Jeruzalemu, u ime Boga Izraelova, koji je bio nad njima;');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (15, 5, 2, 'na to ustadoše Zerubabel, sin Šealtielov, i Ješua, sin Josadakov, i počeše zidati Dom Božji u Jeruzalemu: proroci su Božji bili s ljudima i bodrili ih.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (15, 5, 3, 'U to vrijeme dođoše k njima Tatnaj, satrap s onu stranu Rijeke, Šetar Boznaj i drugovi njihovi poslanici i upitaše ih: \"Tko vam je dopustio da gradite ovaj hram i da podižete ove zidove?');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (15, 5, 4, 'Kako se zovu ljudi koji su sagradili ovu zgradu?\"');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (15, 5, 5, 'Ali je oko Božje bdjelo nad starješinama judejskim, te im nisu zabranili da rade dok obavijest nije otišla Dariju i stigao o tom pismeni odgovor.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (15, 5, 6, 'Ovo je prijepis pisma koje su kralju Dariju poslali Tatnaj, satrap s one strane Rijeke, Šetar Boznaj i njihovi drugovi poslanici s one strane Eufrata.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (15, 5, 7, 'Oni su mu uputili izvješće ovog sadržaja: \"Kralju Dariju svaki mir!');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (15, 5, 8, 'Neka znade kralj da smo došli u pokrajinu Judeju k Domu Boga velikoga: grade ga od krupnog kamenja, drvetom oblažu zidove; posao se brižljivo izvodi i napreduje u njihovim rukama.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (15, 5, 9, 'Zapitali smo njihove starješine i rekli smo im: \'Tko vam je dopustio da gradite ovaj hram i da podignete njegove zidove?\'');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (15, 5, 10, 'Pitali smo ih i za njihova imena da bismo ti javili. Tako smo i zapisali imena onih koji zapovijedaju ljudstvu.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (15, 5, 11, 'A oni nam ovako odgovoriše: \'Mi smo sluge Boga neba i zemlje; gradimo Hram koji je bio sagrađen prije mnogo godina i koji je bio sagradio i podigao veliki kralj Izraela.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (15, 5, 12, 'Ali kad su naši oci rasrdili Boga neba, on ih je predao u ruke Nabukodonozora Kaldejca, babilonskog kralja, koji je razorio ovaj Hram i odveo narod u sužanjstvo u Babilon.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (15, 5, 13, 'Ali prve godine Kira, kralja babilonskog, zapovjedio je kralj Kir da se ponovo sazida ovaj Dom Božji.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (15, 5, 14, 'Još i zlatno i srebrno posuđe Doma Božjega, koje Nabukodonozor bijaše odnio iz svetišta u Jeruzalemu i prenio ga u svetište babilonsko, uzeo je kralj Kir iz svetišta u Babilonu i predao čovjeku po imenu Šešbasaru, koga je postavio upraviteljem,');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (15, 5, 15, 'i rekao mu je: \'Uzmi ovo posuđe, pođi i metni ga u svetište jeruzalemsko, i neka se Dom Božji zida na svome starom mjestu.\'');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (15, 5, 16, 'Taj je Šešbasar došao, dakle, i postavio temelje Doma Božjega u Jeruzalemu. I od tada pa do danas gradi se, i još nije dovršen.\'');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (15, 5, 17, 'Sada, dakle, ako kralj želi, neka se istraži u pismohrani kraljevoj u Babilonu je li zaista kralj Kir izdao zapovijed da se sagradi Dom Božji u Jeruzalemu. A kraljeva odluka o tome neka nam se saopći.\"');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (15, 6, 1, 'Tada, po naredbi kralja Darija, uzeše tražiti u Babilonu, u spremištu gdje je bila pismohrana,');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (15, 6, 2, 'i nađoše u Ekbatani, tvrđavi u medijskoj pokrajini, svitak s ovom poveljom: \"Na spomen.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (15, 6, 3, 'Prve godine kraljevanja Kira proglasio je kralj Kir: Dom Božji u Jeruzalemu. Dom neka se sagradi kao mjesto gdje će se prinositi žrtve i gdje će se donositi prinosi za paljenje. Neka bude visok šezdeset lakata i širok šezdeset lakata.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (15, 6, 4, 'Tri reda neka budu od velikog kamenja, a jedan od drveta. Trošak će se podmiriti iz kraljevskog dvora.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (15, 6, 5, 'Povrh toga, posuđe zlatno i srebrno iz Doma Božjeg koje Nabukodonozor bijaše uzeo iz svetišta u Jeruzalemu i prenio u Babilon neka se vrati i bude na svome mjestu u svetištu jeruzalemskom i neka se postavi u Domu Božjem.\"');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (15, 6, 6, '\"Sada, dakle, Tatnaju, satrape s onu stranu Rijeke, Šetar Boznaju i drugovi vaši poslanici s onu stranu Rijeke, udaljite se odatle!');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (15, 6, 7, 'Pustite neka taj Dom Božji grade upravitelji i starješine židovske. Dom Božji treba sagraditi na njegovu prvotnom mjestu.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (15, 6, 8, 'Evo mojih naredaba o vašem držanju prema starješinama judejskim kako bi se ponovo sagradio taj Dom Božji: od kraljevskog blaga - to jest od danka s onu stranu Rijeke - neka se plaća onim ljudima brižljivo, bez prijekida,');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (15, 6, 9, 'i što im bude trebalo za žrtve paljenice Bogu neba: junaca, ovnova i jaganjaca, i pšenice, soli, vina i ulja, neka im se redovito daje svakoga dana, prema uputama svećenika u Jeruzalemu.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (15, 6, 10, 'Neka prinose žrtve na ugodan miris Bogu neba, neka mole za život kralja i njegovih sinova.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (15, 6, 11, 'Naređujem osim toga: tko god prekrši ovu naredbu, neka mu se izvadi greda iz kuće pa neka na njoj bude pogubljen, a kuća da mu zato postane bunište.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (15, 6, 12, 'I Bog, koji je ondje nastanio svoje Ime, neka obori svakog kralja i narod koji bi se drznuo da prekrši moju naredbu i sruši Dom Božji u Jeruzalemu! Ja, Darije, izdao sam ovu zapovijed. Neka se točno vrši!\"');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (15, 6, 13, 'Tada Tatnaj, satrap s onu stranu Rijeke, Šetar Boznaj i njihovi drugovi učiniše onako kako je zapovjedio kralj Darije.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (15, 6, 14, 'A židovske su starješine nastavile uspješno graditi po nadahnuću proroka Hagaja i Zaharije, sina Adonova. Dovršili su gradnju po naredbi Boga Izraelova i po naredbi Kira i Darija i Artakserksa, kralja perzijskoga.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (15, 6, 15, 'Hram je zavšen dvadeset i trećeg dana mjeseca Adara. Bilo je to šeste godine vladavine kralja Darija.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (15, 6, 16, 'Izraelci - svećenici, leviti i ostatak povratnika iz sužanjstva - radosno posvetiše taj Dom Božji.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (15, 6, 17, 'Žrtvovaše za posvećenje Doma Božjega stotinu junaca, dvije stotine ovnova, četiri stotine janjaca i, kao žrtvu za grijehe svega Izraela, dvanaest jaraca - prema broju plemena Izraelovih.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (15, 6, 18, 'Zatim postaviše svećenike po njihovim redovima i levite po njihovim razredima za službu Domu Božjem u Jeruzalemu, kako je propisano u knjizi Mojsijevoj.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (15, 6, 19, 'Povratnici iz sužanjstva slavili su Pashu četrnaestog dana prvoga mjeseca.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (15, 6, 20, 'Svi su se leviti, kao jedan čovjek, očistili: svi su bili čisti; žrtvovali su pashu za sve povratnike iz ropstva, za svoju braću svećenike i za sebe.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (15, 6, 21, 'Blagovali su pashu Izraelci koji su se vratili iz ropstva i svi oni koji su im se, prekinuvši s nečistoćom naroda zemlje, pridružili da traže Jahvu, Boga Izraelova.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (15, 6, 22, 'I svetkovahu radosno Blagdan beskvasnih hljebova sedam dana: jer ih je Jahve ispunio radošću i obratio prema njima srce asirskog kralja da ojača njihove ruke u radovima oko Doma Boga, Boga Izraelova.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (15, 7, 1, 'Poslije tih događaja, za kraljevanja Artakserksa, kralja perzijskoga, Ezra - sin Seraje, sina Azarje, sina Hilkije,');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (15, 7, 2, 'sina Šaluma, sina Sadoka, sina Ahituba,');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (15, 7, 3, 'sina Amarje, sina Azarje, sina Merajota,');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (15, 7, 4, 'sina Zerahje, sina Uzije, sina Bukija,');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (15, 7, 5, 'sina Abišue, sina Pinhasa, sina Eleazara, sina vrhovnog svećenika Arona -');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (15, 7, 6, 'taj Ezra vrati se iz Babilona. Bio je književnik vješt Mojsijevu Zakonu, koji je dao Jahve, Bog Izraelov. Kako je ruka Jahve, Boga njegova, bila nad njim, kralj mu je dao sve što je tražio.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (15, 7, 7, 'Stanovit broj Izraelaca, svećenika, levita, pjevača, vratara i sluga krenuše u Jeruzalem sedme godine kralja Artakserksa.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (15, 7, 8, 'A Ezra je došao u Jeruzalem petoga mjeseca: bilo je to sedme godine kraljeve.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (15, 7, 9, 'Pošao je iz Babilona prvoga dana prvoga mjeseca, a stigao je u Jeruzalem prvoga dana petoga mjeseca: nad njim je bila blaga ruka Boga njegova!');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (15, 7, 10, 'Jer je Ezra nastojao svim srcem proniknuti Zakon Jahvin, vršiti ga i poučavati Izraela u zakonima i običajima.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (15, 7, 11, 'Evo prijepisa isprave koju je kralj Artakserkso dao svećeniku Ezri, književniku vještu naredbama i zakonima što ih je Jahve dao Izraelu:');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (15, 7, 12, '\"Artakserkso, kralj kraljeva, svećeniku Ezri, pisaru Zakona Boga nebeskoga, potpuni mir.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (15, 7, 13, 'Evo mojih zapovijedi: Tko god u mome kraljevstvu od naroda izraelskog, njegovih svećenika ili od njegovih levita želi poći u Jeruzalem, može ići s tobom.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (15, 7, 14, 'Osim toga, šalje te kralj i njegovih sedam savjetnika da pregledaš Judeju i Jeruzalem prema Zakonu Boga tvoga, koji ti je u ruci,');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (15, 7, 15, 'i da odneseš srebro i zlato koje kralj i njegovih sedam savjetnika dragovoljno prinose Bogu Izraelovu, koji prebiva u Jeruzalemu,');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (15, 7, 16, 'i sve srebro i zlato koje skupiš po svoj pokrajini babilonskoj s dragovoljnim prinosima koje narod i svećenici prinesu za Dom svoga Boga u Jeruzalemu.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (15, 7, 17, 'I pobrini se da tim novcem kupiš junaca, ovnova i jaganjaca, a tako i darova i naljeva koji uz to idu: to prinesi na žrtvenik Doma Boga vašega u Jeruzalemu.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (15, 7, 18, 'Sa srebrom i zlatom što preostane učinite ti i tvoja braća kako vam se bude najviše svidjelo, vršeći volju Boga vašega.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (15, 7, 19, 'Posuđe koje si primio za službu Domu Boga tvoga ostavi pred Bogom tvojim, u Jeruzalemu.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (15, 7, 20, 'I što bi još trebalo za Dom Boga tvoga i što bi trebalo nabaviti primit ćeš iz kraljevskih riznica.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (15, 7, 21, 'Ja, kralj Artakserkso, još zapovijedam svim rizničarima s one strane Rijeke: sve što od vas zatraži svećenik Ezra, pisar Zakona Boga nebeskoga, podajte odmah najtočnije,');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (15, 7, 22, 'do stotinu talenata srebra, stotinu kora pšenice, do stotinu bata vina, do stotinu bata ulja, a soli po želji.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (15, 7, 23, 'Sve što naredi Bog nebeski, neka se odmah izvrši u svoj gorljivosti za Dom Boga nebeskog, da gnjev njegov ne dođe na kraljevstvo kraljevo i na djecu njegovu.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (15, 7, 24, 'I još vam javljamo da se ne smije udariti danak, ni porez, ni carina ni na jednoga od svećenika, levita, pjevača, netinaca i drugih službenika toga Doma Božjega.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (15, 7, 25, 'A ti, Ezra, po mudrosti Boga svoga koju imaš u rukama, postavi činovnike i suce koji će suditi svemu narodu s onu stranu Rijeke, to jest svima koji poznaju Zakon Boga tvoga. Tko ne zna, vi ga poučite.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (15, 7, 26, 'Tko ne bude držao Zakona Boga tvojega - koji je i kraljev zakon - neka se oštro osudi: na smrt, na progonstvo, na novčanu globu ili na tamnicu.\"');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (15, 7, 27, '\"Blagoslovljen neka je Jahve, Bog otaca naših, koji je nadahnuo srce kraljevo da proslavi Dom Jahvin u Jeruzalemu');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (15, 7, 28, 'i koji je okrenuo prema meni naklonost kralja, njegovih savjetnika i svih najmoćnijih kraljevskih činovnika. A ja se osmjelih jer ruka Jahve, Boga mojega, bijaše nada mnom i sabrah glavare Izraela da pođu sa mnom.\"');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (15, 8, 1, 'Evo glavara obitelji s rodoslovljem koji su sa mnom pošli iz Babilona za vladavine kralja Artakserksa:');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (15, 8, 2, 'Od Pinhasovih sinova: Geršom; od Itamarovih sinova: Daniel; od Davidovih sinova: Hatuš,');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (15, 8, 3, 'Šekanijini sinovi; od sinova Paroševih: Zaharija i s njim upisanih muškaraca stotinu i pedeset;');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (15, 8, 4, 'od Pahat-Moabovih sinova: Elijoenaj, sin Zerahjin, i s njim dvije stotine muškaraca;');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (15, 8, 5, 'od Zatuovih sinova: Šekanija, sin Jahazielov, i s njim tri stotine muškaraca;');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (15, 8, 6, 'od sinova Adinovih: Ebed, sin Jonatanov, i s njim pedeset muškaraca;');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (15, 8, 7, 'od Elamovih sinova: Izaija, sin Atalijin, i s njim sedamdeset muškaraca;');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (15, 8, 8, 'od Šefatjinih sinova: Zebadja, sin Mihaelov, i s njim osamdeset muškaraca;');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (15, 8, 9, 'od Joabovih sinova: Obadja, sin Jehielov, i s njim dvije stotine i osamnaest muškaraca;');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (15, 8, 10, 'od sinova Banijevih: Šelomit, sin Josifjin, i s njim stotinu i šezdeset muškaraca;');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (15, 8, 11, 'od Bebajevih sinova: Zaharija, sin Bebajev, i s njim dvadeset i osam muškaraca;');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (15, 8, 12, 'od Azgadovih sinova: Johanan, sin Hakatanov, i s njim stotinu i deset muškaraca;');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (15, 8, 13, 'od posljednjih Adonikamovih sinova poimence: Elifelet, Jeiel i Šemaja, i s njima šezdeset muškaraca;');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (15, 8, 14, 'i od sinova Bigvajevih: Utaj, sin Zabudov, i s njim sedamdeset muškaraca.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (15, 8, 15, 'Sabrao sam ih kod rijeke koja teče prema Ahavi. Utaborili smo se za tri dana ondje. Pregledao sam svjetovnjake i svećenike, ali nisam ondje našao ni jednog levita.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (15, 8, 16, 'Tada sam poslao glavare Eliezera, Ariela, Šemaju, Elnatana, Jariba, Elnatana, Natana, Zahariju, Mešulama i učitelje Jojariba i Elnatana');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (15, 8, 17, 'i uputio sam ih Idonu, poglavaru mjesta Kasifje. Stavio sam u njihova usta riječi koje će reći Idonu i njegovoj braći koja su se nalazila u mjestu Kasifji da nam pribave sluge za Dom Boga našega.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (15, 8, 18, 'Milostiva ruka Boga našega bijaše nad nama i oni nam dovedoše razumna čovjeka između sinova Mahlija, sina Levijeva, sina Izraelova: Šerebju s njegovim sinovima i braćom - njih osamnaest.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (15, 8, 19, 'Još Hašabju i s njim njegova brata Izaiju, sina Merarijeva, i njihove sinove: njih dvadeset.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (15, 8, 20, 'A od poslužitelja koje su David i glavari postavili levitima da im služe: dvije stotine i dvadeset poslužitelja. Svi su bili poimence zabilježeni.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (15, 8, 21, 'Ja sam ondje, kraj rijeke Ahave, proglasio post: da bismo se ponizili pred Bogom svojim i od njega izmolili sretan put sebi, svojoj djeci i svemu blagu svojem.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (15, 8, 22, 'Jer bih se stidio moliti od kralja vojske i konjanika da nas štite putem od neprijatelja; izjavili smo, naprotiv, kralju: \"Ruka je Boga našega ispružena da blagoslovi sve one koji ga traže; njegova snaga i gnjev njegov nad onima su koji ga ostavljaju.\"');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (15, 8, 23, 'I tako smo postili i molili Boga svoga na ovu nakanu, i on nas usliša.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (15, 8, 24, 'Izabrao sam dvanaest glavara svećeničkih, Šerebju i Hašabju, i s njima desetoricu njihove braće;');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (15, 8, 25, 'izmjerih im srebro, zlato i posuđe, darove koje su kralj, njegovi savjetnici, velikaši i svi Izraelci darovali za Dom Boga našega.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (15, 8, 26, 'Izmjerih i stavih u njihove ruke šest stotina i pedeset talenata srebra, stotinu srebrnih posuda od po dva talenta, stotinu talenata zlata,');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (15, 8, 27, 'dvadeset zlatnih čaša od tisuću darika i dva vrča od dobre pozlaćene mjedi, skupocjene kao zlato.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (15, 8, 28, 'I rekoh im: \"Vi ste Jahvi posvećeni; ovo je posuđe posvećeno, ovo srebro i zlato dragovoljno je darovano Jahvi, Bogu otaca vaših.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (15, 8, 29, 'Pazite i čuvajte ovo sve dok ne izmjerite pred glavarima svećeničkim i pred levitima i glavarima obitelji Izraelovih u Jeruzalemu, u dvoranama Doma Jahvina.\"');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (15, 8, 30, 'Svećenici i leviti primiše, dakle, izmjereno srebro, zlato i posuđe da ga odnesu u Jeruzalem, u Dom Boga našega.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (15, 8, 31, 'Dvanaestog dana prvoga mjeseca krenusmo od rijeke Ahave da pođemo u Jeruzalem: ruka Boga našega bijaše nad nama; on nas je na putu štitio od napada neprijatelja i od pljačkaša.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (15, 8, 32, 'Stigli smo u Jeruzalem i ondje smo se tri dana odmarali.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (15, 8, 33, 'Četvrtoga dana izmjereno je srebro, zlato i posuđe u Domu Boga našega i predano je u ruke Merimotu, sinu Urijinu, s kojim je bio Eleazar, sin Pinhasov; a pred njima bijahu leviti: Jozabad, sin Ješuin, i Noadja, sin Binujev.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (15, 8, 34, 'Sve je bilo na broju i težini. Zabilježena je tada sveukupna težina. U to vrijeme');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (15, 8, 35, 'oni koji su se vratili iz sužanjstva, povratnici, priniješe žrtvu paljenicu Bogu Izraelovu: dvanaest junaca za sav Izrael, devedeset i šest ovnova, sedamdeset i sedam janjaca, dvanaest jaraca za grijehe - sve to kao paljenicu Jahvi.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (15, 8, 36, 'Zatim predaše kraljeve naredbe kraljevskim satrapima i upraviteljima s one strane Rijeke i oni pomogoše narod i Dom Božji.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (15, 9, 1, 'Pošto je sve to uređeno, dođoše mi glavari govoreći: \"Izraelski narod, svećenici i leviti nisu se odvojili od naroda zemlje, okorjelih u njihovim gnusobama: nisu se odijelili od Kanaanaca, Hetita, Perižana, Jebusejaca, Amonaca, Moabaca, Egipćana i Amorejaca,');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (15, 9, 2, 'nego su za sebe i za sinove svoje uzimali za žene njihove kćeri: sveti rod pomiješao se s narodima zemlje; glavari i savjetnici prvi su počinili tu nevjernost.\"');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (15, 9, 3, 'Na tu vijest razderah svoju odjeću i svoj ogrtač, čupao sam kosu i bradu svoju i sjedoh utučen.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (15, 9, 4, 'Svi koji su strahovali od riječi Božje sakupili se oko mene zbog nevjernosti onih povratnika. A ja sam sveudilj sjedio utučen, sve do večernje žrtve.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (15, 9, 5, 'A o večernjoj žrtvi trgnuh se iz svoga jada i, razderane odjeće i ogrtača, padoh na koljena, raširih ruke prema Jahvi, Bogu svome,');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (15, 9, 6, 'i rekoh: \"Bože moj! Stid me i bojim se podići svoje lice k tebi, Bože moj! Jer su se umnožila zlodjela naša preko glave i grijesi su se naši nagomilali do neba.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (15, 9, 7, 'Od vremena otaca svojih pa do danas u krivnji smo velikoj i zbog zlodjela svojih bijasmo predani u ruke zemaljskih kraljeva: mi, kraljevi naši i svećenici naši - pod mač, u sužanjstvo, u plijen i na sramotu, kao što je to i danas.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (15, 9, 8, 'Ali sada, za kratko vrijeme, učinio nam je Jahve, Bog naš, milost i ostavi nam Ostatak i dade nam utočište u svome svetom mjestu: tako nam je Bog naš prosvijetlio oči i dao nam malo života u robovanju našem.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (15, 9, 9, 'Jer mi smo robovi, ali nas u ropstvu našem nije nikada ostavio Bog naš: nego nam dade te nađosmo milost u perzijskih kraljeva, dade nam snage da podignemo Dom Boga našega i da obnovimo njegove ruševine i pribavi nam utočište u Judeji i Jeruzalemu.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (15, 9, 10, 'Ali sada, što možemo reći, Bože moj, kad smo poslije svega toga odnemarili zapovijedi tvoje');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (15, 9, 11, 'koje si zapovjedio preko svojih slugu proroka ovim riječima: \'Zemlja u koju ulazite da je zaposjednete nečista je zemlja od nečistoće naroda zemlje, od gnusoba njihovih kojima su se napunili od jednoga kraja do drugoga.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (15, 9, 12, 'Stoga ne dajite kćeri svojih za njihove sinove i ne uzimajte njihovih kćeri za svoje sinove, ne želite nikakav njihov mir i sreću njihovu, da biste postali snažni i jeli najbolje plodove zemlje i ostavili je zauvijek u nasljedstvo sinovima svojim.\'');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (15, 9, 13, 'I poslije svega što nas je stiglo zbog zlih djela naših i zbog naše velike krivice, dobro je, o Bože naš, što si naša zlodjela smatrao manjima nego što je zloća njihova i što si nam ostavio ovaj Ostatak!');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (15, 9, 14, 'Zar možemo i dalje kršiti naredbe tvoje i vezivati se s ovim gnusnim narodima? Ne bi li se ti razgnjevio i satro nas da ni Ostatka ni ikoga spašena više ne bi bilo?');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (15, 9, 15, 'Jahve, Bože Izraelov, po pravednosti tvojoj mi ostadosmo Ostatak, kao što smo danas: evo nas pred tobom s grijehom svojim! Zaista ne bismo zbog njega smjeli stajati pred tobom!\"');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (15, 10, 1, 'Dok je Ezra molio i priznavao grijehe, plačući i ležeći pred Domom Božjim, skupilo se oko njega mnoštvo Izraelaca, ljudi, žena i djece: i taj je narod gorko plakao.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (15, 10, 2, 'Tada Šekanija, sin Jehielov, jedan od sinova Elamovih, uzimajući riječ reče Ezri: \"Mi smo izdali Boga svoga ženeći se tuđinkama iz naroda zemlje. Ali još ima nade Izraelu.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (15, 10, 3, 'Obnovimo sada Savez s Bogom svojim: obećajmo da ćemo, prema savjetu moga gospodara i onih koji osjećaju strahopočitanje prema zapovijedi Boga našega, otpustiti svoje žene tuđinke i djecu koju su rodile. Učinimo dakle po Zakonu!');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (15, 10, 4, 'Ustani, jer to je tvoja dužnost, a mi ćemo biti uza te. Budi hrabar i na djelo!\"');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (15, 10, 5, 'Tada ustade Ezra i zakle glavare svećeničke, i levite, i sve Izraelce da će učiniti kako im bijaše rekao. I zakleše se.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (15, 10, 6, 'Ezra se udalji ispred Doma Božjega i uđe u dvoranu Johanana, sina Elijašibova. Ondje provede noć i nije jeo ni kruha niti je pio vode jer tugovaše zbog nevjernosti povratnika.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (15, 10, 7, 'Zatim je objavljeno u Judeji i Jeruzalemu svima povratnicima da se skupe u Jeruzalemu:');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (15, 10, 8, 'a tko ne bude došao u Jeruzalem za tri dana, toga će pozvati glavari i starješine, bit će mu zaplijenjeno imanje i isključit će ga iz zbora povratnika.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (15, 10, 9, 'Svi su se ljudi od Jude i Benjamina sakupili tako za tri dana u Jeruzalemu. Bilo je to devetoga mjeseca, dvadesetoga dana u mjesecu. Sav se narod smjestio na trgu pred Domom Božjim, dršćući zbog svega toga i zbog jake kiše.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (15, 10, 10, 'Tada, ustavši, svećenik Ezra reče im: \"Vi ste se iznevjerili kad ste se oženili tuđinkama. Tako ste povećali grijeh Izraelov!');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (15, 10, 11, 'Ali podajte sada hvalu Jahvi, Bogu otaca svojih, i izvršite volju njegovu te se rastavite od naroda zemlje i od žena tuđinki.\"');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (15, 10, 12, 'Sav je zbor odgovorio snažnim glasom: \"Jest, dužnost nam je učiniti po tvome savjetu!');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (15, 10, 13, 'Ali naroda ima mnogo i dažd nahodi: vani se ne može stajati. Osim toga, nije to posao od dan-dva, jer nas je mnogo koji smo u tome sagriješili.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (15, 10, 14, 'Mogu nas na zajedničkom zboru zastupati naši glavari: svi koji su po našim gradovima oženjeni tuđinkama mogu doći u određeno vrijeme u pratnji starješina i sudaca svakoga grada, sve dok ne budemo odvratili gnjev Boga svojega zbog ovoga.\"');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (15, 10, 15, 'Samo Jonatan, sin Asahelov, i Jahzija, sin Tikvin, bijahu se usprotivili; a podupirahu ih Mešulam i levit Šabetaj.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (15, 10, 16, 'Povratnici učiniše tako: rastaše se. Svećenik Ezra izabra za pomoćnike glavare obitelji, prema njihovim domovima, i svi su bili poimence određeni. Počeli su zasjedati prvoga dana desetoga mjeseca da bi sve ispitali.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (15, 10, 17, 'I prvoga dana prvoga mjeseca završiše sa svima koji se bijahu oženili tuđinkama.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (15, 10, 18, 'Među pripadnicima svećenstva evo koji bijahu oženjeni tuđinkama: između sinova Ješue, sina Josadakova, i među njegovom braćom: Maaseja, Eliezer, Jarib i Gedalija;');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (15, 10, 19, 'oni dadoše svoju ruku da će otpustiti svoje žene i da će za svoj grijeh prinijeti ovna kao naknadnicu.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (15, 10, 20, 'Od sinova Imerovih: Hanani i Zebadja;');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (15, 10, 21, 'od Harimovih sinova: Maaseja, Ilija, Šemaja, Jehiel i Uzija;');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (15, 10, 22, 'od Pašhurovih sinova: Elijoenaj, Maaseja, Jišmael, Netanel, Jozabad i Elasa.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (15, 10, 23, 'Od levita: Jozabad, Šimej, Kelaja - nazvan Kelita - Petahja, Juda i Eliezer.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (15, 10, 24, 'Od pjevača: Elijašib i Zakur. Od vratara: Šalum, Telem i Uri.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (15, 10, 25, 'A između Izraelaca: od sinova Paroševih: Ramja, Jizija, Malkija, Mijamin, Eleazar, Malkija i Benaja;');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (15, 10, 26, 'od sinova Elamovih: Matanija, Zaharija, Jehiel, Abdi, Jeremot i Ilija;');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (15, 10, 27, 'od sinova Zatuovih: Elijoenaj, Elijašib, Matanija, Jeremot, Zabad i Aziza;');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (15, 10, 28, 'od sinova Bebajevih: Johanan, Hananija, Zabaj i Atlaj;');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (15, 10, 29, 'od Banijevih sinova: Mešulam, Maluk, Adaja, Jašub, Šeal i Ramot;');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (15, 10, 30, 'od Pahat-Moabovih sinova: Adna, Kelal, Benaja, Maaseja, Matanija, Besalel, Binuj i Manaše;');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (15, 10, 31, 'od sinova Harimovih: Eliezer, Jišija, Malkija, Šemaja, Šimun,');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (15, 10, 32, 'Benjamin, Maluk, Semarja;');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (15, 10, 33, 'od sinova Hašumovih: Matnaj, Matata, Zabad, Elifelet, Jeremaj, Manaše, Šimej;');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (15, 10, 34, 'od sinova Banijevih: Maadaj, Amram, Joel,');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (15, 10, 35, 'Benaja, Bedja, Kelu,');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (15, 10, 36, 'Vanija, Meremot, Elijašib,');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (15, 10, 37, 'Matanija, Matnaj i Jaasaj;');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (15, 10, 38, 'od sinova Binujevih: Šimej,');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (15, 10, 39, 'Šelemja, Natan i Adaja;');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (15, 10, 40, 'od Zakajevih sinova: Šašaj, Šaraj,');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (15, 10, 41, 'Azareel, Šelemja, Šemarja,');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (15, 10, 42, 'Šalum, Amarja, Josip;');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (15, 10, 43, 'od Nebovih sinova: Jeiel, Matitja, Zabad, Zebina, Jadaj, Joel, Benaja.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (15, 10, 44, 'Svi su ovi bili oženjeni tuđinkama, ali su ih otpustili, žene i djecu.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (16, 1, 1, 'Povijest Nehemije, sina Hakalijina. Mjeseca Kisleva, dvadesete godine, kad sam bio u Susi,');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (16, 1, 2, 'dođe Hanani, jedan od moje braće, s nekim ljudima iz Judeje. Ja ih zapitah o Židovima - o Ostatku što se spasio od sužanjstva i o Jeruzalemu.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (16, 1, 3, 'Oni mi odgovoriše: \"Ostatak, oni koji su nakon sužanjstva ostali u zemlji, u velikoj su nevolji i sramoti. Jeruzalemski je zid sav razoren, a vrata mu ognjem spaljena.\"');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (16, 1, 4, 'Kad sam čuo te vijesti, sjedoh i zaplakah. Tugovao sam više dana, postio i molio se pred Bogom nebeskim.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (16, 1, 5, 'I rekoh: \"O, Jahve, Bože nebeski, veliki i strašni Bože koji čuvaš Savez i naklonost onima koji te ljube i drže zapovijedi tvoje!');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (16, 1, 6, 'Neka uho tvoje bude pažljivo i oči tvoje otvorene da čuješ molitvu sluge svoga. Molim ti se sada, danju i noću, za sinove Izraelove, sluge tvoje, i ispovijedam grijehe sinova Izraelovih koje smo učinili protiv tebe; sagriješili smo i ja i kuća oca mojega!');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (16, 1, 7, 'Veoma smo zlo činili prema tebi, ne držeći naredaba tvojih, zakona i običaja koje si ti naredio po Mojsiju, sluzi svome.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (16, 1, 8, 'Ali se opomeni riječi koje si povjerio Mojsiju, sluzi svome: \'Ako budete nevjerni, ja ću vas rasuti među narode;');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (16, 1, 9, 'ali ako se obratite meni i budete poštovali moje naredbe i držali ih, budu li neki od vas prognani i nakraj neba, ja ću vas sakupiti i odvesti na mjesto koje sam izabrao da ondje prebiva moje Ime.\'');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (16, 1, 10, 'A, eto, oni su tvoje sluge i tvoj narod, koji si izbavio svojom velikom moći i snažnom rukom svojom.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (16, 1, 11, 'Ah, Gospode, neka uho tvoje bude pažljivo na molitvu sluge tvoga, na molitvu slugu tvojih, koji su spremni bojati se tvoga Imena. Smjerno te molim, udijeli danas sreću sluzi svome i učini da nađe milost pred ovim čovjekom.\" A ja bijah tada peharnik kraljev.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (16, 2, 1, 'Mjeseca Nisana, dvadesete godine kraljevanja Artakserksova, stajalo je vino pred kraljem. Uzeh ga i ponudih kralju. Nikada pred njim nisam bio tužan.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (16, 2, 2, 'Tada mi kralj reče: \"Što ti je tužno lice? Nisi li možda bolestan? Nije drugo nego je tuga u tvome srcu!\" Ja se veoma uplaših');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (16, 2, 3, 'i rekoh kralju: \"Neka uvijek živi kralj! Kako mi lice ne bi bilo tužno kad je grad gdje su grobovi mojih otaca razoren, a vrata mu ognjem spaljena?\"');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (16, 2, 4, 'Kralj me upita: \"Što, dakle, želiš?\" Zazvah Boga nebeskoga');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (16, 2, 5, 'i odgovorih kralju: \"Ako je kralju po volji i ako ti je mio sluga tvoj, pusti me da odem u Judeju, u grad grobova mojih otaca, da ga obnovim.\"');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (16, 2, 6, 'Kralj me upita pred kraljicom, koja je sjedila kraj njega: \"Koliko bi trajao tvoj put? Kada ćeš se vratiti?\" Pošto sam utvrdio vrijeme koje je odgovaralo kralju, pusti me da odem.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (16, 2, 7, 'Još rekoh kralju: \"Ako je kralju po volji, mogao bih ponijeti pisma upraviteljima s onu stranu Rijeke da me propuste do Judeje;');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (16, 2, 8, 'i pismo Asafu, nadgledniku kraljeve šume, da mi dadne drva za gradnju vrata na tvrđi Hrama, za gradski bedem i za kuću u kojoj ću se nastaniti.\" I dade mi kralj, jer dobrostiva ruka Boga moga bijaše nada mnom.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (16, 2, 9, 'I dođoh tako k upraviteljima s onu stranu Rijeke i dadoh im kraljeva pisma. A kralj posla sa mnom časnike i konjanike.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (16, 2, 10, 'Kad to ču Sanbalat, Horonac, i sluga Tobija, Amonac, bi im vrlo mrsko što je došao čovjek da se zauzme za dobro Izraelaca.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (16, 2, 11, 'Stigavši u Jeruzalem, ostadoh ondje tri dana.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (16, 2, 12, 'Zatim ustah noću, u pratnji nekoliko ljudi, nikomu ne povjerivši što mi je Bog moj nadahnuo da učinim za Jeruzalem; a nisam imao druge životinje osim kljuseta na kojem sam jahao.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (16, 2, 13, 'Iziđoh, dakle, noću na Dolinska vrata i uputih se Zmajevskom izvoru, a zatim prema Smetlišnim vratima: razgledao sam jeruzalemski zid gdje je bio razoren i vrata koja su bila spaljena.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (16, 2, 14, 'Nastavio sam put prema Izvorskim vratima i Kraljevskom ribnjaku, ali nisam našao prolaza za životinju na kojoj sam jahao.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (16, 2, 15, 'Uspeo sam se zato noću uz Potok, i dalje razgledajući zid, i ponovo sam ušao na Dolinska vrata. Tako sam se vratio,');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (16, 2, 16, 'a da savjetnici nisu primijetili kamo sam otišao i što sam učinio. Sve do sada nisam ništa rekao Židovima: ni svećenicima, ni velikašima, ni savjetnicima, ni drugima nadstojnicima.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (16, 2, 17, 'Tada im rekoh: \"Vidite u kakvoj smo nevolji: Jeruzalem je u ruševinama, a vrata mu spaljena. Hajte, sagradimo jeruzalemski zid da više ne budemo izloženi ruglu.\"');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (16, 2, 18, 'I objasnih im kako je dobrostiva ruka Boga moga bila nada mnom, a saopćih im i riječi koje mi kralj bijaše rekao. \"Ustanimo\", povikaše oni, \"i gradimo!\" I ukrijepiše im se ruke na dobro djelo.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (16, 2, 19, 'Na te vijesti počeše nam se rugati Sanbalat, Horonac, i sluga Tobija, Amonac, i Gešem, Arapin. Prezirno su nam govorili: \"Što radite ovdje? Hoćete li se pobuniti protiv kralja?\"');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (16, 2, 20, 'Ali im ja odgovorih ovim riječima: \"Nebeski će nam Bog dati da uspijemo. Mi, sluge njegove, ustasmo da gradimo. A vi nemate ni dijela, ni prava, ni spomena u Jeruzalemu.\"');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (16, 3, 1, 'Tada usta veliki svećenik Elijašib sa svojom braćom svećenicima te sagradiše Ovčja vrata. Posvetiše ih, postaviše im krila i nastaviše graditi sve do kule Meaha i do Hananelove kule.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (16, 3, 2, 'Kraj njih su gradili Jerihonci, a do njih je gradio Zakur, sin Imrijev.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (16, 3, 3, 'Sinovi Hasnaini gradili su Riblja vrata, stavili dovratke, utvrdili krila, stožere i prijevornice.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (16, 3, 4, 'Kraj njih je popravljao Merimot, sin Urije, sina Hakosova; a do njega je popravljao Mešulam, sin Berekje, sina Mešezabelova; a do njega je popravljao Sadok, sin Baanin.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (16, 3, 5, 'Kraj njih su popravljali Tekoanci, ali su njihovi plemenitaši odbili da prignu šiju na službu svojim gospodarima.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (16, 3, 6, 'Stara vrata popravljali su Jojada, sin Paseahov, i Mešulam, sin Besodjin. Oni su stavili dovratke, učvrstili krila, stožere i prijevornice.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (16, 3, 7, 'A kraj njih obnavljahu Melatja Gibeonjanin, Jadon Meronoćanin i ljudi iz Gibeona i Mispe, podložnici upravitelja s onu stranu Rijeke.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (16, 3, 8, 'A do njih je popravljao Uziel, Harhajin sin, zlatar, a do njega je popravljao Hananija, jedan od pomastara: oni su utvrdili Jeruzalem sve do Širokog zida.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (16, 3, 9, 'Do njih je popravljao Refaja, sin Hurov, glavar polovice jeruzalemskog okruga.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (16, 3, 10, 'A do njega je popravljao Jedaja, sin Harumafov, pred svojom kućom; a do njega je popravljao Hatuš, sin Hašabnejin.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (16, 3, 11, 'Malkija, sin Harimov, i Hašub, sin Pahat-Moabov, popravljali su dio sve do Pećne kule.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (16, 3, 12, 'A do njih je popravljao Šalum, sin Halohešov, glavar polovice okruga, on i njegovi sinovi.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (16, 3, 13, 'Dolinska vrata popravljao je Hanum i stanovnici Zanoaha: sagradili su ih, učvrstili krila, stožere i prijevornice i postavili tisuću lakata zida do Smetlišnih vrata.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (16, 3, 14, 'Smetlišna vrata popravljao je Malkija, sin Rekabov, glavar bethakeremskog okruga, sa svojim sinovima: učvrstili su krila, stožere i prijevornice.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (16, 3, 15, 'Izvorska vrata popravljao je Šalum, sin Kol-Hozeov, glavar nad mispanskim okrugom: sagradio ih je, pokrio ih, utvrdio vratna krila, stožere i prijevornice. On je popravio i zid kod ribnjaka Šiloaha, koji se proteže od Kraljevskog vrta do stepenica što silaze iz Davidova grada.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (16, 3, 16, 'Za njim je popravljao Nehemija, sin Azbukov, glavar nad polovicom betsurskog okruga, sve do nasuprot Davidovim grobnicama i do umjetnog ribnjaka i Vojarne.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (16, 3, 17, 'Za njim su popravljali leviti: Rehum, sin Banijev; a do njega je popravljao Hašabja, glavar nad polovicom keilskog okruga, za svoje područje.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (16, 3, 18, 'Do njih su popravljala njihova braća: Bavaj, sin Henadadov, glavar nad polovicom keilskog kotara;');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (16, 3, 19, 'a do njega Ezer, sin Ješuin, glavar Mispe, popravljao je drugi dio, sučelice usponu prema Oružarnici na uglu.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (16, 3, 20, 'Za njim je popravljao Baruk, sin Zabajev, i popravio je drugi dio, od ugla do kućnih vrata velikog svećenika Elijašiba.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (16, 3, 21, 'Za njim je popravljao Meremot, sin Urije, sina Hakosova, drugi dio: od Elijašibova kućnog ulaza do kraja Elijašibove kuće.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (16, 3, 22, 'Za njima su radili na popravcima svećenici koji su živjeli u Okružju.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (16, 3, 23, 'Za njima su pak popravljali Benjamin i Hašub sučelice svojim kućama. Za njima je popravljao Azarja, sin Ananijina sina Maaseje, nasuprot svojoj kući.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (16, 3, 24, 'Za njima je popravljao Binuj, sin Henadadov, drugi dio - od Azarjine kuće do ugla, do zidnog kruništa.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (16, 3, 25, 'Palal, sin Uzajev, popravljao je nasuprot uglu i kuli koja se uzdiže iznad Gornje kraljevske palače, a nalazi se prema dvorištu Tamnice. Za njim je Pedaja, sin Parošev, popravljao');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (16, 3, 26, 'sve do Vodenih vrata, u smjeru istoka, i sve do pred Uzdignutu kulu.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (16, 3, 27, 'Za njima su popravljali Tekoanci drugi dio nasuprot velikoj Uzdignutoj kuli, sve do Ofelskog zida.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (16, 3, 28, 'Od Konjskih vrata popravljali su svećenici, svaki nasuprot svojoj kući.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (16, 3, 29, 'Za njima je Sadok, sin Imerov, popravljao nasuprot svojoj kući. Za njim je popravljao Šemaja, sin Šekanijin, čuvar Istočnih vrata.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (16, 3, 30, 'Za njim su Hananija, sin Šelemjin, i Hanun, šesti sin Salafov, popravljali drugi dio. Za njima je popravljao Mešulam, sin Berekjin, nasuprot svome stanu.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (16, 3, 31, 'Za njim je Malkija, zlatar, popravljao sve do prebivališta netinaca i trgovaca, nasuprot Nadgledničkim vratima do Gornje dvorane na zidnom kruništu.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (16, 3, 32, 'A zlatari su i trgovci popravljali između Gornje dvorane na zidnom kruništu do Ovčjih vrata.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (16, 3, 33, 'Kad je Sanbalat čuo da gradimo zid, razljutio se. Bio je veoma srdit, ismijavao je Židove');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (16, 3, 34, 'i vikao je pred svojom braćom i samarijanskom vojskom: \"Što poduzimaju ovi jadni Židovi? Kane li možda popraviti, žrtvovati i završiti sve u jedan dan? Zar će iz hrpe praha dozvati u život spaljeno kamenje?\"');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (16, 3, 35, 'Tobija, Amonac, koji je bio uz njega, reče: \"Neka samo grade! Ali popne li se lisica, srušit će im kamene zidove.\"');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (16, 3, 36, 'Čuj, o Bože naš, kako nas preziru! Navrni njihove poruge na njihovu glavu. Predaj ih kao plijen u zemlju ropstva.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (16, 3, 37, 'Ne pokrivaj njihova bezakonja i grijeh njihov neka ne bude izbrisan pred licem tvojim jer su se rugali graditeljima.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (16, 3, 38, 'Tako smo gradili zid, koji je uskoro bio završen do pola visine. Narod je imao oduševljenja za rad.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (16, 4, 1, 'Kad su Sanbalat, Tobija, Arapi, Amonci i Ašdođani čuli da napreduje popravljanje jeruzalemskih zidova - jer su se počele zatvarati pukotine - veoma se ražestiše.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (16, 4, 2, 'Zakleše se svi zajedno da će napasti Jeruzalem i da će nas smesti.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (16, 4, 3, 'Mi smo tada zazvali Boga našega i postavljali smo dnevnu i noćnu stražu da bismo zaštitili grad.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (16, 4, 4, 'A Židovi govorahu: \"Snage su nosačima klonule, a ruševina je mnogo: nećemo nikada stići sagraditi zida!\"');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (16, 4, 5, 'A naši neprijatelji rekoše: \"Uvući ćemo se među njih prije nego što doznaju i opaze nas: tada ćemo ih poubijati i tako osujetiti pothvat!\"');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (16, 4, 6, 'A kad bi došli Židovi koji žive kraj njih, po deset bi nas puta upozoravali: \"Idu protiv vas iz svih mjesta u kojima stanuju!\"');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (16, 4, 7, 'Postavili smo se u nizinama, iza zida i na goletima; rasporedio sam narod po rodovima, s mačevima, kopljima i lukovima.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (16, 4, 8, 'Kad sam vidio kako se boje, ustao sam i objavio velikašima, odličnicima i ostalom narodu ovo: \"Ne bojte se ovih ljudi! Mislite na Gospoda, velikoga i strašnoga, i borite se za svoju braću, za sinove i kćeri svoje, za žene i kuće svoje!\"');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (16, 4, 9, 'Kad su naši neprijatelji čuli da smo obaviješteni i da je Bog osujetio njihovu osnovu, mogli smo se vratiti k zidu, svaki svome poslu.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (16, 4, 10, 'Ali je od toga dana samo polovica mojih momaka obavljala posao, a ostali su držali koplja, štitove, lukove i oklope, a glavari stajali iza doma Judina,');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (16, 4, 11, 'koji je gradio zid. I nosači tereta držali su oružje: jednom je rukom svaki radio svoj posao, a u drugoj mu bilo oružje.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (16, 4, 12, 'Svaki je od graditelja, dok je radio, nosio mač pripasan uz bok. Trubač je stajao kraj mene.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (16, 4, 13, 'Rekao sam velikašima, odličnicima i ostalom narodu: \"Posao je velik i zamašan, a mi se rasuli po zidu, daleko jedni od drugih:');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (16, 4, 14, 'skupite se oko nas na mjesto gdje čujete glas trube, a Bog naš borit će se za nas.\"');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (16, 4, 15, 'Tako smo obavljali posao od rane zore do prvih zvijezda. Polovica je bila naoružana kopljima.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (16, 4, 16, 'U to sam vrijeme još rekao narodu: \"Svaki sa svojim slugom neka noći u Jeruzalemu: po redu ćemo noću stražariti, a danju raditi.\"');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (16, 4, 17, 'Ni ja, ni moja braća, ni moji momci, ni stražari koji su me pratili nismo skidali svojih haljina, svatko je držao pri ruci svoje oružje.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (16, 5, 1, 'Velika se vika digla među ljudima i ženama protiv njihove braće Židova.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (16, 5, 2, 'Jedni su govorili: \"Zalažemo svoje sinove i kćeri da bismo mogli nabaviti pšenice te jesti i živjeti.\"');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (16, 5, 3, 'Drugi su govorili: \"Zalažemo svoja polja, vinograde svoje i kuće svoje da bismo mogli nabaviti pšenice za vrijeme gladi.\"');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (16, 5, 4, 'Drugi su opet govorili: \"Moramo uzaimati novac na polja svoja i vinograde da bismo mogli isplatiti kraljeve namete.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (16, 5, 5, 'Tijelo je naše kao tijelo braće naše, sinovi su naši kao i njihovi, a mi moramo predavati u ropstvo svoje sinove i kćeri; među našim kćerima neke su već robinje! A mi ne možemo ništa jer polja naša i vinograde drže drugi.\"');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (16, 5, 6, 'Razljutio sam se veoma kad sam čuo njihovu viku i te riječi.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (16, 5, 7, 'Pošto sam u sebi promislio, prekorio sam velikaše i odličnike riječima: \"Vi namećete teret svojoj braći!\" I sazvao sam protiv njih velik zbor.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (16, 5, 8, 'I rekao sam: \"Mi smo, koliko smo mogli, otkupili svoju židovsku braću koja bijahu prodana poganima. A sada vi prodajete svoju braću da bismo ih otkupili!\" Svi su šutjeli i nitko nije odgovorio.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (16, 5, 9, 'Nastavio sam: \"Nije dobro to što činite. Ne treba li da hodite u strahu Boga našega da se tako uklonimo ruglu neprijateljskih naroda?');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (16, 5, 10, 'I ja, i moja braća, i moji momci davali smo im novaca i žita. Ali smo im dug oprostili.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (16, 5, 11, 'Vratite im i vi još danas njihova polja, vinograde, maslinike i kuće njihove i oprostite im postotak u novcu, u žitu, u vinu, u ulju, što ste im ga nametnuli.\"');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (16, 5, 12, 'A oni odgovoriše: \"Vratit ćemo; nećemo od njih ništa tražiti. Učinit ćemo kako si rekao.\" Tada pozvah svećenike i naredih neka se zakunu da će učiniti kako su obećali.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (16, 5, 13, 'Zatim istresoh skute svoje odjeće govoreći: \"Neka Bog ovako istrese iz vlastite kuće i imanja svakog čovjeka koji se ne bude držao ovog obećanja! Tako bio istresen i ispražnjen!\" A sav zbor odgovori \"Amen!\" hvaleći Jahvu. I narod je učinio prema ovom dogovoru.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (16, 5, 14, 'I od dana kad mi je kralj naredio da budem upravitelj u zemlji Judinoj, od dvadesete do trideset i druge godine kraljevanja Artakserksa, za dvanaest godina ja i moja braća nismo nikada jeli upraviteljskog kruha.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (16, 5, 15, 'Ali prijašnji upravitelji, moji prethodnici, ugnjetavahu narod: svakoga su dana od njega uzimali četrdeset šekela srebra za kruh; i njihove su sluge ugnjetavale narod. A ja nisam nikada tako činio, zbog straha Božjega.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (16, 5, 16, 'Čak sam se jednako držao posla oko zida i nisam kupio ni jedne njive! Svi su moji momci bili ondje okupljeni na poslu.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (16, 5, 17, 'Za mojim su stolom jeli Židovi i odličnici, njih stotinu i pedeset na broju, osim onih koji su k nama dolazili iz okolnih naroda.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (16, 5, 18, 'Svakoga se dana o mom trošku pripremalo jedno goveče, šest biranih ovaca i peradi; svakih deset dana donosilo se obilje vina za sve. A opet nisam nikada tražio upraviteljskog poreza na kruh, jer je narod već bio teško opterećen.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (16, 5, 19, 'Spomeni se, Bože moj, za moje dobro svega što sam učinio ovome narodu!');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (16, 6, 1, 'Kad su Sanbalat, Tobija, Gešem Arapin i ostali naši neprijatelji dočuli da sam obnovio zid i da nije u njemu ostalo pukotine - do toga vremena nisam zapravo bio namjestio krila na vratima -');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (16, 6, 2, 'poručiše mi Sanbalat i Gešem: \"Dođi da se sastanemo u Kefiri, u Dolini ononskoj.\" Ali su mi oni zlo mislili.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (16, 6, 3, 'Zato sam im poslao glasnike s ovim odgovorom: \"Zauzet sam velikim poslom i ne mogu sići: posao bi zastao kad bih ga ostavio da dođem k vama!\"');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (16, 6, 4, 'Četiri su mi puta slali isti poziv i ja sam im odvraćao isti odgovor.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (16, 6, 5, 'Tada, peti put, s istom nakanom, posla mi Sanbalat svoga slugu s otvorenim pismom.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (16, 6, 6, 'U njemu je pisalo: \"Čuje se u narodima - a Gašmu potvrđuje - da se ti i Židovi spremate na bunu; zato da i gradiš zid i da želiš postati njihovim kraljem, kako vele.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (16, 6, 7, 'I da si postavio proroke da proglase tvoj uspjeh u Jeruzalemu i da kažu: Judeja ima kralja! Sada će ti glasovi stići kralju do ušiju: zato dođi da se posavjetujemo.\"');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (16, 6, 8, 'Ali sam mu ja odgovorio: \"Ništa nije tako kao što tvrdiš; sve je to samo izmišljotina tvoga srca.\"');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (16, 6, 9, 'Jer su nas oni htjeli uplašiti govoreći: \"Klonut će im ruke od posla i neće ga završiti nikada.\" A ja sam, naprotiv, ukrijepio ruke svoje!');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (16, 6, 10, 'Pošao sam Šemaji, sinu Delaje, sina Mehetabelova, koji se bijaše zatvorio u svojoj kući. On mi objavi: \"Nađimo se u Domu Božjemu, usred Hekala, i zatvorimo vrata Hekala jer će doći da te ubiju. Jest, još noćas doći će da te ubiju!\"');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (16, 6, 11, 'A ja odgovorih: \"Zar da bježi čovjek kao što sam ja? Koji čovjek, meni sličan, može ući u Hekal i ostati živ? Ne, ja ne idem.\"');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (16, 6, 12, 'I tada razabrah: nije ga poslao Bog, nego mi je objavio proroštvo, jer su ga Tobija i Sanbalat podmitili,');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (16, 6, 13, 'da bih, uplašen, učinio onako te sagriješio. To bi im poslužilo da me ozloglase i da mi se rugaju!');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (16, 6, 14, 'Sjeti se, Bože moj, Tobije i Sanbalata prema ovim njihovim djelima, a i proročice Noadje i ostalih proroka što me htjedoše uplašiti.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (16, 6, 15, 'Zid je završen dvadeset i petog Elula, za pedeset i dva dana.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (16, 6, 16, 'A kad su čuli svi naši neprijatelji i vidjeli svi pogani oko nas, bilo je to čudo u očima njihovim, jer su shvatili da je Bog naš učinio to djelo.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (16, 6, 17, 'A onih dana mnogi su židovski velikaši često slali svoja pisma Tobiji i mnoga su primali od Tobije.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (16, 6, 18, 'Jer u Judeji bijahu mnogi s njime zakletvom povezani: tÓa bio je u rodu sa Šekanijom, sinom Arahovim, i sinom njegovim Johananom, koji je uzeo za ženu kćer Mešulama, sina Berekjina.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (16, 6, 19, 'I veličali su preda mnom njegova djela, a njemu prenosili moje riječi. Zato je Tobija i slao pisma da me uplaši.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (16, 7, 1, 'A kad je zid bio sagrađen i kad sam namjestio vratna krila, postavljeni su čuvari na vratima i pjevači i leviti.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (16, 7, 2, 'Upravu sam Jeruzalema povjerio Hananiju, svome bratu, i Hananiji, zapovjedniku tvrđave, jer je ovaj bio čovjek povjerenja i bojao se Boga kao malo tko.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (16, 7, 3, 'Rekao sam im: \"Jeruzalemska vrata neka se ne otvaraju dok sunce ne ogrije; a dok ono bude još visoko, neka ih zatvore i prebace prijevornice. Treba postaviti straže uzete između žitelja jeruzalemskih: svakoga na njegovo mjesto, svakoga nasuprot njegovoj kući.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (16, 7, 4, 'Grad je bio prostran i velik, ali je u njemu bilo malo stanovnika jer nije bilo sagrađenih kuća.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (16, 7, 5, 'A Bog me moj nadahnuo te sam skupio velikaše, odličnike i narod da se unesu u rodovnike. Tada sam našao rodovnik onih koji su se prije vratili. U njemu nađoh zapisano:');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (16, 7, 6, 'Evo ljudi iz pokrajine koji su došli iz sužanjstva u koje ih bijaše odveo Nabukodonozor, babilonski kralj. Vratili su se u Jeruzalem i Judeju, svaki u svoj grad.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (16, 7, 7, 'Došli su sa Zerubabelom, Ješuom, Nehemijom, Azarjom, Raamjom, Nahamanijem, Mordokajem, Bilšanom, Misperetom, Bigvajem, Nehumom, Baanom. Broj ljudi naroda Izraelova:');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (16, 7, 8, 'Paroševih sinova: dvije tisuće stotinu sedamdeset i dva;');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (16, 7, 9, 'sinova Šefatjinih: tri stotine sedamdeset i dva;');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (16, 7, 10, 'Arahovih sinova: šest stotina pedeset i dva!');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (16, 7, 11, 'Pahat-Moabovih sinova, to jest Ješuinih i Joabovih sinova: dvije tisuće osam stotina i osamnaest;');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (16, 7, 12, 'sinova Elamovih: tisuću dvjesta pedeset i četiri;');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (16, 7, 13, 'Zatuovih sinova: osam stotina četrdeset i pet;');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (16, 7, 14, 'sinova Zakajevih: sedam stotina i šezdeset;');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (16, 7, 15, 'Binujevih sinova: šest stotina četrdeset i osam;');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (16, 7, 16, 'sinova Bebajevih: šest stotina dvadeset i osam;');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (16, 7, 17, 'Azgadovih sinova: dvije tisuće tri stotine dvadeset i dva;');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (16, 7, 18, 'sinova Adonikamovih: šest stotina šezdeset i sedam;');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (16, 7, 19, 'Bigvajevih sinova: dvije tisuće šezdeset i sedam;');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (16, 7, 20, 'sinova Adinovih: šest stotina pedeset i pet;');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (16, 7, 21, 'Aterovih sinova, to jest od Ezekije: devedeset i osam;');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (16, 7, 22, 'sinova Hašumovih: trista dvadeset i osam;');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (16, 7, 23, 'Besajevih sinova: trista dvadeset i četiri;');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (16, 7, 24, 'sinova Harifovih: stotinu i dvanaest;');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (16, 7, 25, 'Gibeonovih sinova: devedeset i pet;');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (16, 7, 26, 'ljudi iz Betlehema i Netofe: stotinu osamdeset i osam;');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (16, 7, 27, 'ljudi iz Anatota: stotinu dvadeset i osam;');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (16, 7, 28, 'ljudi iz Bet Azmaveta: četrdeset i dva;');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (16, 7, 29, 'ljudi iz Kirjat Jearima, Kefire i Beerota: sedam stotina četrdeset i tri;');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (16, 7, 30, 'ljudi iz Rame i Gabe: šest stotina dvadeset i jedan;');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (16, 7, 31, 'ljudi iz Mikmasa: stotinu dvadeset i dva;');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (16, 7, 32, 'ljudi iz Betela i Aja: stotinu dvadeset i tri;');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (16, 7, 33, 'ljudi iz Neba: pedeset i dva;');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (16, 7, 34, 'sinova drugoga Elama: tisuću dvjesta pedeset i četiri;');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (16, 7, 35, 'Harimovih sinova: trista dvadeset;');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (16, 7, 36, 'ljudi iz Jerihona: trista četrdeset i pet;');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (16, 7, 37, 'ljudi iz Loda, Hadida i Onona: sedam stotina dvadeset i jedan;');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (16, 7, 38, 'sinova Senajinih: tri tisuće devet stotina i trideset.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (16, 7, 39, 'Svećenika: sinova Jedajinih, to jest iz kuće Ješuine: devet stotina sedamdeset i tri;');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (16, 7, 40, 'Imerovih sinova: tisuću pedeset i dva;');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (16, 7, 41, 'sinova Fašhurovih: tisuću dvjesta četrdeset i sedam;');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (16, 7, 42, 'Harimovih sinova: tisuću i sedamnaest.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (16, 7, 43, 'Levita: Ješuinih sinova, to jest Kadmielovih i Hodvinih: sedamdeset i četiri.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (16, 7, 44, 'Pjevača: Asafovih sinova: stotinu četrdeset i osam.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (16, 7, 45, 'Vratara: sinova Šalumovih, sinova Aterovih, sinova Talmonovih, sinova Akubovih, Hatitinih sinova, sinova Šobajevih: stotinu trideset i osam.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (16, 7, 46, 'Netinaca: sinova Sihinih, sinova Hasufinih, sinova Tabaotovih,');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (16, 7, 47, 'sinova Kerosovih, sinova Sijajevih, sinova Fadonovih,');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (16, 7, 48, 'sinova Lebaninih, sinova Hagabinih, sinova Šalmajevih,');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (16, 7, 49, 'sinova Hananovih, sinova Gidelovih, sinova Gaharovih,');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (16, 7, 50, 'sinova Reajinih, sinova Resinovih, sinova Nekodinih,');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (16, 7, 51, 'sinova Gazamovih, sinova Uzinih, sinova Fasealovih,');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (16, 7, 52, 'sinova Besajevih, sinova Merinimovih, sinova Nefišesimovih,');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (16, 7, 53, 'sinova Bakbukovih, sinova Hakufinih, sinova Harhurovih,');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (16, 7, 54, 'sinova Baslitovih, sinova Mehidinih, sinova Haršinih,');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (16, 7, 55, 'sinova Barkošovih, sinova Sisrinih, sinova Tamahovih,');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (16, 7, 56, 'sinova Nasijahovih, sinova Hatifinih.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (16, 7, 57, 'Sinova Salomonovih slugu: sinova Sotajevih, sinova Soferetovih, sinova Feridinih,');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (16, 7, 58, 'sinova Jaalinih, sinova Darkonovih, sinova Gidelovih,');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (16, 7, 59, 'sinova Šefatjinih, sinova Hatilovih, sinova Pokeret-Sebajinih, sinova Amonovih.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (16, 7, 60, 'Svega netinaca i sinova Salomonovih slugu tri stotine devedeset i dva.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (16, 7, 61, 'Slijedeći ljudi koji su došli iz Tel Melaha, Tel Harše, Keruba, Adona i Imera nisu mogli dokazati da su njihove obitelji i njihov rod izraelskog podrijetla:');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (16, 7, 62, 'sinovi Delajini, sinovi Tobijini, sinovi Nekodini: šest stotina četrdeset i dva.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (16, 7, 63, 'A od svećenika: sinovi Hobajini, sinovi Hakosovi, sinovi Barzilaja - onoga koji se oženio jednom od kćeri Barzilaja Gileađanina te uzeo njegovo ime.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (16, 7, 64, 'Ovi su ljudi tražili svoj zapis u rodovnicima, ali ga nisu mogli naći: bili su isključeni iz svećeništva');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (16, 7, 65, 'i namjesnik im zabrani blagovati od svetinja sve dok se ne pojavi svećenik za Urim i Tumin.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (16, 7, 66, 'Ukupno je na zboru bilo četrdeset i dvije tisuće tri stotine i šezdeset osoba,');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (16, 7, 67, 'ne računajući njihove sluge i sluškinje, kojih bijaše sedam tisuća tri stotine trideset i sedam. Bilo je i dvije stotine četrdeset i pet pjevača i pjevačica,');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (16, 7, 68, 'četiri stotine trideset i pet deva i šest tisuća sedam stotina i dvadeset magaraca.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (16, 7, 69, 'Pojedini glavari obitelji dadoše priloge za gradnju. Namjesnik je položio u riznicu tisuću drahmi zlata, pedeset vrčeva, trideset svećeničkih haljina.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (16, 7, 70, 'Neki su od glavara obitelji dali u poslovnu riznicu dvadeset tisuća drahmi zlata i dvije tisuće dvije stotine mina srebra.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (16, 7, 71, 'A darova ostalog puka bilo je do dvadeset tisuća drahmi zlata, dvije tisuće mina srebra i šezdeset i sedam svećeničkih haljina.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (16, 7, 72, 'Svećenici, leviti, vratari, pjevači, netinci i sav Izrael naseliše se svaki u svoj grad. A kada se približio sedmi mjesec, već su sinovi Izraelovi bili u svojim gradovima.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (16, 7, 73, '');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (16, 8, 1, 'Tada se skupi sav narod kao jedan čovjek na trg koji je pred Vodenim vratima. Rekoše književniku Ezri da donese knjigu Mojsijeva zakona što ga je Jahve dao Izraelu.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (16, 8, 2, 'I prvoga dana sedmoga mjeseca svećenik Ezra donese Zakon pred zbor ljudi, žena i sviju koji su bili sposobni da ga razumiju.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (16, 8, 3, 'Na trgu koji je pred Vodenim vratima počeo je čitati knjigu, od ranoga jutra do podneva, pred ljudima, ženama i pred onima koji su bili zreli. Sav je narod pozorno slušao knjigu Zakona.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (16, 8, 4, 'Književnik Ezra stajaše na drvenu besjedištu koje su podigli za tu zgodu. Kraj njega stajahu: s desne strane Matitja, Šema, Anaja, Urija, Hilkija i Maaseja, a s lijeve strane Pedaja, Mišael, Malkija, Hašum, Hašbadana, Zaharija i Mešulam.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (16, 8, 5, 'Ezra je otvorio knjigu naočigled svemu narodu - jer je bio poviše od svega naroda - a kad ju je otvorio, sav narod ustade.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (16, 8, 6, 'Tada Ezra blagoslovi Jahvu, Boga velikoga, a sav narod, podignutih ruku, odgovori: \"Amen! Amen!\" Zatim su kleknuli i poklonili se pred Jahvom, licem do zemlje.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (16, 8, 7, 'A leviti Ješua, Bani, Šerebja, Jamin, Akub, Šabtaj, Hodija, Maaseja, Kelita, Azarja, Jozabad, Hanan i Pelaja objašnjavahu Zakon narodu, a narod stajaše na svome mjestu.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (16, 8, 8, 'I čitahu iz knjige Božjeg zakona po odlomcima i razlagahu smisao da narod može razumjeti što se čita.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (16, 8, 9, 'Potom namjesnik Nehemija, i svećenik i književnik Ezra, i leviti koji poučavahu narod rekoše svemu narodu: \"Ovo je dan posvećen Jahvi, Bogu vašemu! Ne tugujte, ne plačite!\" Jer sav narod plakaše slušajući riječi Zakona.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (16, 8, 10, 'I još im reče Nehemija: \"Pođite i jedite masna jela, i pijte slatko, i pošaljite dio onima koji nemaju ništa pripremljeno, jer ovo je dan posvećen našem Gospodu. Ne žalostite se: radost Jahvina vaša je jakost.\"');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (16, 8, 11, 'I leviti umirivahu sav narod govoreći: \"Umirite se: ovaj je dan svet. Ne tugujte!\"');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (16, 8, 12, 'I ode sav narod da jede i pije, i da šalje obroke, i da slavi veliko slavlje: jer su shvatili riječi koje su im objavljene.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (16, 8, 13, 'Drugog dana skupiše se glavari obitelji svega naroda, svećenici i leviti oko književnika Ezre da prouče riječi Zakona.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (16, 8, 14, 'I nađoše napisano u Zakonu što ga je Jahve naredio preko sluge Mojsija: \"Sinovi Izraelovi neka borave pod sjenicama za svečanosti u sedmom mjesecu.\"');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (16, 8, 15, 'Čim su čuli, proglasiše u svim svojim gradovima i u Jeruzalemu: \"Idite u goru i donesite granja maslinova i granja divlje masline, mirtovih i palmovih grana i granja ostaloga lisnatog drveća da načinimo sjenice, kako je propisano.\"');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (16, 8, 16, 'I ode narod i donese granja i načiniše sjenice, svaki na svom krovu i svojim dvorištima, u predvorjima Doma Božjega, na trgu kod Vodenih vrata i na onom kod Efrajimovih vrata.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (16, 8, 17, 'Sav zbor onih koji su se vratili iz sužanjstva načini sjenice i boravili su u njima - Izraelci nisu toga činili od vremena Jošue, sina Nunova, sve do toga dana. I bila je veoma velika radost.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (16, 8, 18, 'Ezra je čitao knjigu Zakona Božjeg svakog dana, od prvoga do posljednjega. Sedam se dana svetkovao blagdan, a osmoga je dana bio svečani zbor, kako je propisano.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (16, 9, 1, 'Dvadeset i četvrtoga dana toga mjeseca skupiše se Izraelci na post, u pokorničkim vrećama i posuti prašinom.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (16, 9, 2, 'Rod se Izraelov odvojio od svih tuđinaca: pristupili su i ispovijedali svoje grijehe i bezakonja svojih otaca.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (16, 9, 3, 'Stajali su, svatko na svome mjestu, i čitali knjigu Zakona Jahve, Boga svoga, četvrtinu dana; za druge su četvrtine ispovijedali svoje grijehe i klanjali se Jahvi, Bogu svome.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (16, 9, 4, 'A Ješua, Bani, Kadmiel, Šebanija, Buni, Šerebja, Bani i Kenani, popevši se na poviše mjesto za levite, vapili su snažnim glasom Jahvi, Bogu svome.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (16, 9, 5, 'I govorahu leviti Ješua, Kadmiel, Bani, Hašabneja, Šerebja, Hodija, Šebanija i Petahja: \"Ustanite, blagoslivljajte Jahvu, Boga našega! Blagoslovljen da si, Jahve, Bože naš, odvijeka dovijeka! I neka je blagoslovljeno tvoje Ime slavno, iznad svakog blagoslova i hvale uzvišeno.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (16, 9, 6, 'Ti si, Jahve, Jedini! Ti si stvorio nebo, i nebesa nad nebesima, i vojsku njihovu, zemlju i sve što je na njoj, mora i što je u njima. Ti sve to oživljavaš, i vojske se nebeske tebi klanjaju.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (16, 9, 7, 'Ti si, Jahve, Bog, koji si Abrama izabrao, iz Ura kaldejskoga njega izveo i dao mu ime Abraham.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (16, 9, 8, 'Vjerno si srce njegovo pred sobom našao i Savez s njim sklopio da ćeš mu dati zemlju kanaansku, i hetitsku i amorejsku, i perižansku, jebusejsku i girgašansku, njemu i potomstvu njegovu. I svoja si obećanja ispunio, jer si pravedan.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (16, 9, 9, 'Nevolju si otaca naših u Egiptu vidio, i vapaj si njihov čuo kraj Mora crvenoga.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (16, 9, 10, 'Znacima si se i čudesima oborio na faraona i na sve sluge njegove, i na sav narod zemlje njegove; jer znao si kolika je bila protiv njih drskost njihova. Sebi si ime stekao koje do danas traje.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (16, 9, 11, 'More si pred njima razdvojio: prešli su usred mora po suhu. U dubine si utopio progonitelje njihove kao kamen među vode silovite.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (16, 9, 12, 'Stupom oblaka danju si ih vodio, a noću si stupom ognjenim svijetlio im po putu kojim su hodili.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (16, 9, 13, 'Na goru si Sinajsku sišao i s neba im govorio; i dao si im pravedne naredbe, čvrste zakone, zapovijedi izvrsne i uredbe.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (16, 9, 14, 'Ti si im objavio svoju svetu subotu, zapovijedi, naredbe i Zakon si im propisao po glasu sluge svoga Mojsija.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (16, 9, 15, 'S neba si ih hranio kruhom za njihove gladi, za njihovu si žeđ iz stijene vodu izveo. Ti si im zapovjedio da pođu zaposjesti zemlju za koju si se zakleo da ćeš im dati.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (16, 9, 16, 'Ali se oni i oci naši uzjoguniše, vratove ukrutiše i zapovijedi tvojih nisu slušali.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (16, 9, 17, 'Poslušnost su odbili, zaboravili čudesa što si ih za njih učinio; ukrutili su vratove, a u glavu uvrtjeli da u ropstvo se svoje vrate, u Egipat. Ali ti si Bog praštanja, milosrdan i blag, na gnjev si spor, a u milosrdđu velik: i nisi ih ostavio!');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (16, 9, 18, 'Čak su načinili tele saliveno, \'To bog je tvoj\', rekoše, \'koji te izveo iz Egipta!\' I teško su hulili,');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (16, 9, 19, 'a ti u beskrajnom milosrđu nisi ih napuštao u pustinji: stup se oblaka nije pred njima skrivao, danju ih je putem vodio, a stup je plameni noću pred njima svijetlio putem kojim su hodili.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (16, 9, 20, 'Dao si im svoga Duha dobrog da ih naučiš mudrosti, mÓane svoje nisi uskratio njihovim ustima, i u žeđi si im vode pružio.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (16, 9, 21, 'Četrdeset godina krijepio si ih u pustinji: ništa im nije nedostajalo: niti im se odijelo deralo, niti su im noge oticale.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (16, 9, 22, 'I dao si im kraljevstva i narode i razdijelio ih granicama: zaposjeli su zemlju Sihona, kralja hešbonskoga, i zemlju Oga, kralja bašanskoga.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (16, 9, 23, 'I sinove si im umnožio kao zvijezde nebeske, i u zemlju si ih doveo za koju si rekao njihovim ocima da će ući u nju i zaposjesti je.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (16, 9, 24, 'Sinovi su ušli i pokorili zemlju, a ti si pred njima svladao stanovnike zemlje, Kanaance, i predao si u ruke njihove kraljeve i narode zemlje da rade s njima što ih je volja;');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (16, 9, 25, 'osvojili su gradove tvrde i zemlju plodnu i naslijedili kuće pune svakog dobra, isklesane zdence, vinograde, maslinike i mnogo plodnog drveća: jeli su, sitili se i debljali i uživali u velikoj dobroti tvojoj.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (16, 9, 26, 'Ali su se bunili i odvrgli tebe, i Zakon su tvoj bacili za leđa, ubijali su proroke, koji su ih obraćali da se tebi vrate, i grdno su hulili.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (16, 9, 27, 'U ruke si ih tada predao osvajačima, koji su ih tlačili. A u vrijeme muke svoje tebi su vapili i ti si ih s neba uslišio i u velikoj dobroti svojoj slao si im izbavitelje, koji su ih iz ruku tlačitelja njihovih izbavljali.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (16, 9, 28, 'Ali čim bi se smirili, opet su pred tobom zlo činili, a ti si ih puštao u ruke neprijatelja njihovih, koji su ih mučili. I opet su k tebi vapili i ti si ih s neba uslišio: u milosrđu svojem mnogo si ih puta izbavio.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (16, 9, 29, 'Ti si ih opominjao da se vrate tvome Zakonu: ali se oni uzjoguniše, nepokorni tvojim zapovijedima; griješili su protiv naredaba tvojih, a čovjek živi kad ih obdržava. Leđa su izvlačili, šije ukrućivali i nisu slušali.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (16, 9, 30, 'Mnogo si godina bio strpljiv s njima i svojim si ih Duhom opominjao po službi svojih proroka; no nisu slušali. Tada si ih predao u ruke naroda zemaljskih.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (16, 9, 31, 'U velikom milosrđu svojem ti ih nisi uništio, ni ostavio ih nisi, jer si ti Bog milostiv i pun samilosti.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (16, 9, 32, 'A sada, o Bože naš, veliki Bože, jaki i strašni, koji čuvaš Savez i dobrohotnost, neka ne bude pred licem tvojim neznatna sva ova nevolja koja je snašla nas, kraljeve naše i knezove, svećenike i proroke naše, očeve naše i sav narod tvoj od vremena asirskih kraljeva pa do danas.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (16, 9, 33, 'Ti si pravedan u svemu što nas je snašlo, jer si ti pokazao vjernost, a mi zloću svoju.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (16, 9, 34, 'Kraljevi naši i knezovi, svećenici i oci naši nisu vršili Zakona tvoga, nisu osluškivali naredaba tvojih i opomena koje si im davao.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (16, 9, 35, 'Premda su bili u svom kraljevstvu, u velikim dobrima koja si im činio, u prostranoj i plodnoj zemlji koju si im dao, oni ti nisu služili i od svojih zlih djela nisu se odvraćali.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (16, 9, 36, 'Mi smo danas, evo, robovi i u zemlji koju si bio dao ocima našim da uživaju njene plodove i njena dobra, evo u njoj mi robujemo.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (16, 9, 37, 'Njeni obilni prihodi idu kraljevima koje si nam postavio zbog grijeha naših, i gospodare oni po volji svojoj tjelesima našim i stokom našom. Ah, u velikoj smo nevolji!');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (16, 10, 1, 'I zbog svega toga obvezujemo se pismeno na vjernost.\" Na zapečaćenoj ispravi stajala su imena naših knezova, levita i svećenika...');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (16, 10, 2, 'Na zapečaćenoj ispravi su bili: namjesnik Nehemija, sin Hakalijin, i Sidkija,');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (16, 10, 3, 'Seraja, Azarja, Jeremija,');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (16, 10, 4, 'Pašhur, Amarja, Malkija,');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (16, 10, 5, 'Hatuš, Šebanija, Maluk,');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (16, 10, 6, 'Harim, Meremot, Obadja,');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (16, 10, 7, 'Daniel, Gineton, Baruk,');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (16, 10, 8, 'Mešulam, Abija, Mijamin,');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (16, 10, 9, 'Maazja, Bilgaj, Šemaja - to su svećenici.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (16, 10, 10, 'Zatim leviti: Ješua, sin Azanijin, Binuj, od sinova Henadadovih - Kadmiel,');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (16, 10, 11, 'i braća njihova: Šekanija, Hodija, Kelita, Pelaja, Hanan,');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (16, 10, 12, 'Mika, Rehob, Hašabja,');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (16, 10, 13, 'Zakur, Šerebja, Šebanija,');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (16, 10, 14, 'Hodija, Bani, Beninu.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (16, 10, 15, 'Glavari naroda: Paroš, Pahat Moab, Elam, Zatu, Bani,');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (16, 10, 16, 'Buni, Azgad, Bebaj,');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (16, 10, 17, 'Adonija, Bigvaj, Adin,');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (16, 10, 18, 'Ater, Ezekija, Azur,');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (16, 10, 19, 'Hodija, Hašum, Besaj,');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (16, 10, 20, 'Harif, Anatot, Nebaj,');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (16, 10, 21, 'Magpijaš, Mešulam, Hazir,');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (16, 10, 22, 'Mešezabel, Sadok, Jadua,');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (16, 10, 23, 'Pelatja, Hanan, Anaja,');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (16, 10, 24, 'Hošea, Hananija, Hašub,');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (16, 10, 25, 'Haloheš, Pilha, Šobek,');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (16, 10, 26, 'Rehum, Hašabna, Maaseja,');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (16, 10, 27, 'Ahija, Hanan, Anan,');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (16, 10, 28, 'Maluk, Harim, Baana.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (16, 10, 29, '... ali i ostali narod, svećenici, leviti - vratari, pjevači, netinci - i svi koji su se prema Zakonu Božjem odvojili od zemaljskih naroda, a i njihove žene, sinovi i kćeri, svi koji su bili sposobni da razumiju,');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (16, 10, 30, 'priključili su se svojoj braći i glavarima te su se obvezali prisegom i zakletvom da će stupati prema Zakonu Božjem, koji je dan po rukama Mojsija, sluge Božjega, i da će držati i vršiti sve zapovijedi Jahve, Boga našega, njegove naredbe i zakone.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (16, 10, 31, 'I osobito: da nećemo davati svojih kćeri narodima zemaljskim i njihovih kćeri nećemo uzimati svojim sinovima.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (16, 10, 32, 'I ako narodi zemlje donesu na prodaju robu ili kakvo god žito u dan subotnji, mi ništa nećemo od njih kupovati u subotu ni u drugi posvećeni dan. Svake sedme godine ostavljat ćemo zemlju da počine i otpuštati dugove svake ruke.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (16, 10, 33, 'Uzeli smo kao obavezu: da ćemo svake godine davati trećinu šekela za bogoslužje u Domu Boga svojega:');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (16, 10, 34, 'za postavljeni kruh, za trajne prinosnice i za svagdanje paljenice, za žrtve subotnje, mladog mjeseca, blagdanske i za okajnice, da se pomiri Izrael; i za svaku službu u Domu Boga našega.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (16, 10, 35, 'Mi svećenici, leviti i narod bacili smo ždrijeb za prinos drva koja treba da određenog dana svake godine prema svojim obiteljima donosimo u Dom Boga našega za vatru na žrtveniku Jahve, Boga našega, kako je zapisano u Zakonu;');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (16, 10, 36, 'da ćemo svake godine donositi u Dom Jahvin prvine od plodova zemlje i prve plodove svakoga drveta');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (16, 10, 37, 'i prvorođene sinove i prvine svoje stoke, kako je to pisano u Zakonu - prvine od krupne i sitne stoke neka se odnose u Dom Boga našega, jer su određene svećenicima koji služe u Domu Boga našega.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (16, 10, 38, 'Povrh toga prvine svojih naćava, plodova svakog drveta, novoga vina i ulja nosit ćemo svećenicima u sobe Doma Boga našega; a desetinu od svoje zemlje levitima, jer leviti uzimaju desetinu u svim mjestima gdje radimo.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (16, 10, 39, 'Svećenik, sin Aronov, neka prati levite kad skupljaju desetinu. Leviti neka donose desetinu desetine u Dom Boga našega, u sobe riznice,');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (16, 10, 40, 'jer su onamo dužni, Izraelci i leviti donositi prinos od žita, vina i ulja. Ondje se nalaze posude svetišta, svećenici u službi, vratari i pjevači. Nećemo više zanemarivati Doma Boga svojega.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (16, 11, 1, 'Tada se nastaniše knezovi narodni u Jeruzalemu. Ostali je narod bacao ždrijeb da od svakih deset ljudi izađe jedan koji će stanovati u svetom gradu Jeruzalemu, dok će ostalih devet ostati u drugim gradovima.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (16, 11, 2, 'I narod je blagoslovio sve ljude koji su dragovoljno htjeli živjeti u Jeruzalemu.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (16, 11, 3, 'A evo glavara pokrajinskih koji su se nastanili u Jeruzalemu i po gradovima Judeje. Izrael, svećenici, leviti, netinci i sinovi Salomonovih slugu nastanili su se u svojim gradovima, svaki na svome posjedu.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (16, 11, 4, 'U Jeruzalemu se nastaniše sinovi Judini i sinovi Benjaminovi. Od sinova Judinih: Ataja, sin Uzije, sina Zaharijina, sina Amarjina, sina Šefatjina, sina Mahalalelova, od sinova Faresovih;');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (16, 11, 5, 'Maaseja, sin Baruha, sina Kol-Hozea, sina Hazaje, sina Adaje, sina Jojariba, sina Zaharije, sina Šelina.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (16, 11, 6, 'Svega je bilo Faresovih sinova u Jeruzalemu četiri stotine šezdeset i osam ljudi sposobnih za boj.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (16, 11, 7, 'Evo Benjaminovih sinova: Salu, sin Mešulama, sina Joedova, sina Pedajina, sina Kolajina, sina Maasejina, sina Itielova, sina Ješajina,');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (16, 11, 8, 'i braća njegova: sposobnih za boj devet stotina dvadeset i osam.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (16, 11, 9, 'Joel, sin Zikrijev, bio je njihov zapovjednik, i Juda, sin Hasenuin, drugi upravitelj grada.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (16, 11, 10, 'Od svećenika: Jedaja, Jojarib, Jakin,');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (16, 11, 11, 'Seraja, sin Hilkije, sina Mešulama, sina Sadoka, sina Merajota, sina Ahituba, predstojnik Doma Božjega, i');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (16, 11, 12, 'njihova braća koja su vršila službu u Domu: osam stotina dvadeset i dvojica; i Adaja, sin Jerohama, sina Pelalije, sina Amsija, sina Zaharije, sina Pašhura, sina Malkijina,');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (16, 11, 13, 'i njegova braća, glavari obitelji: dvjesta četrdeset i dvojica; i Amasaj, sin Azarela, sina Ahzaja, sina Mešilemota, sina Imerova,');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (16, 11, 14, 'i njihove braće, sposobnih za boj: stotinu dvadeset i osam. Zapovjednik nad njima bio je Zabdiel, sin Hagedolimov.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (16, 11, 15, 'Od levita: Šemaja, sin Hašuba, sina Azrikama, sina Hašabje, sina Bunijeva;');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (16, 11, 16, 'i Šabtaj i Jozabad, od glavara levitskih, za nadzor vanjskih poslova Doma Božjega;');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (16, 11, 17, 'i Matanija, sin Miheja, sina Zabdijeva, sina Asafova, koji je ravnao psalmima, počinjao zahvale i molitve; i Bakbukja, drugi među svojom braćom; i Abda, sin Šamue, sina Galala, sina Jedutunova.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (16, 11, 18, 'Svega je levita bilo u Svetom gradu: dvjesta osamdeset i četiri.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (16, 11, 19, 'A vratari: Akub, Talmon i njihova braća koja su čuvala stražu na vratima: stotinu sedamdeset i dva.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (16, 11, 20, 'A ostali Izraelci, svećenici i leviti, nastaniše se u svim gradovima Judeje, svaki na svojoj baštini i po naseljima u njihovim poljima.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (16, 11, 21, 'Netinci su stanovali u Ofelu; Siha i Gišpa bijahu na čelu netinaca.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (16, 11, 22, 'Predstojnik je levitima u Jeruzalemu bio Uzi, sin Banija, sina Hašabje, sina Matanije, sina Mihejina. On je bio od sinova Asafovih, koji su bili pjevači za službu Doma Božjega.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (16, 11, 23, 'Jer je za njih bila kraljeva zapovijed i uredba za svakodnevnu službu.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (16, 11, 24, 'Petahja, sin Mešezabelov, od sinova Zeraha, sina Judina, bio je kraljev povjerenik za sve poslove s narodom.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (16, 11, 25, 'Od sinova Judinih nastanili su se u Kirjat Haarbi i njezinim zaseocima, u Dibonu i njegovim zaseocima, u Jekabseelu i njegovim naseljima,');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (16, 11, 26, 'u Jesui, u Moladi, u Bet Peletu,');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (16, 11, 27, 'u Hasar Šualu, u Beer Šebi i u njenim zaseocima,');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (16, 11, 28, 'u Siklagu, u Mekoni i njenim zaseocima,');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (16, 11, 29, 'u En Rimonu, u Sori, u Jarmutu,');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (16, 11, 30, 'Zanoahu, Adulamu i njihovim naseljima; u Lakišu i njegovim poljima, u Azeki i njenim zaseocima: tako su se naselili od Beer Šebe sve do Hinomske doline.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (16, 11, 31, 'Benjaminovi sinovi življahu u Gebi, Mikmasu, Aju i Betelu i u njihovim zaseocima,');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (16, 11, 32, 'u Anatotu, Nobu, Ananiji,');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (16, 11, 33, 'Hasoru, Rami, Gitajimu,');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (16, 11, 34, 'Hadidu, Seboimu, u Nebalatu,');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (16, 11, 35, 'Lodu, Ononu i u Dolini rukotvoraca.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (16, 11, 36, 'Skupine levita nalazile su se u Judi i Benjaminu.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (16, 12, 1, 'Ovo su svećenici i leviti koji su došli sa Zerubabelom, sinom Šealtielovim, i Ješuom: Seraja, Jeremija, Ezra,');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (16, 12, 2, 'Amarja, Maluk, Hatuš,');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (16, 12, 3, 'Šekanija, Rehum, Meremot,');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (16, 12, 4, 'Ido, Gineton, Abija,');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (16, 12, 5, 'Mijamin, Maadja, Bilga,');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (16, 12, 6, 'Šemaja, Jojarib, Jedaja,');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (16, 12, 7, 'Salu, Amok, Hilkija i Jedaja. To su bili glavari svećenički i njihova braća za Ješuina vremena.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (16, 12, 8, 'A leviti: Ješua, Binuj, Kadmiel, Šerebja, Juda i Matanija - ovaj potonji i njegova braća ravnali su hvalospjevima.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (16, 12, 9, 'Bakbukja i Uni i braća njihova izmjenjivali su se s njima u službi.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (16, 12, 10, 'Ješua rodi Jojakima; Jojakim rodi Elijašiba, a Elijašib Jojadu;');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (16, 12, 11, 'Jojada rodi Jonatana, a Jonatan rodi Jaduu.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (16, 12, 12, 'U Jojakimovo vrijeme glavari svećeničkih obitelji bijahu: Serajine obitelji Meraja; Jeremijine Hananja;');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (16, 12, 13, 'Ezrine Mešulam; Amarjine Johanan;');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (16, 12, 14, 'Malukove Jonatan; Šebanijine Josip;');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (16, 12, 15, 'Harimove Adna; Meremotove Helkaj;');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (16, 12, 16, 'Idove Zaharija; Ginetonove Mešulam;');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (16, 12, 17, 'Abijine Zikri; Minjaminove...; obitelji Moadjine Piltaj;');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (16, 12, 18, 'Bilgine Šamua; Šemajine Jonatan;');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (16, 12, 19, 'Jojaribove Matenaj; Jedajine Uzi;');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (16, 12, 20, 'Saluove Kelaj; Amokove Eber;');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (16, 12, 21, 'Hilkijine Hašabja; Jedajine Netanel.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (16, 12, 22, 'U vrijeme Elijašiba, Jojade, Johanana i Jadue bili su popisani glavari levitskih obitelji i svećenici sve do kraljevanja Darija Perzijanca.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (16, 12, 23, 'Sinovi Levijevi: glavari obitelji bili su zabilježeni u Knjizi ljetopisa, do vremena Johanana, sina Elijašibova.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (16, 12, 24, 'Glavari levitski bili su: Hašabja, Šerebja, Ješua, Binuj, Kadmiel, a njihova braća, koja su stajala prema njima da pjevaju naizmjenično pohvale i zahvalnice prema uredbama Davida, Božjeg čovjeka,');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (16, 12, 25, 'bijahu: Matanija, Bakbukja i Obadja. A Mešulam, Talmon i Akub, vratari, čuvali su stražu kod skladišta blizu vrata.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (16, 12, 26, 'Ti su živjeli u vrijeme Jojakima, sina Ješue, sina Josadakova, i u vrijeme upravitelja Nehemije i književnika svećenika Ezre.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (16, 12, 27, 'Kad je bila posveta jeruzalemskoga zida, potražili su levite svugdje gdje su stanovali da ih dovedu u Jeruzalem te proslave posvetu radošću, zahvalnicama i pjesmom uz cimbale, harfe i citre.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (16, 12, 28, 'I skupiše se pjevači, sinovi Levijevi, iz kraja oko Jeruzalema, iz netofatskih sela,');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (16, 12, 29, 'iz Bet Hagilgala, iz Gebe i polja Azmaveta: jer su pjevači sebi sagradili sela oko Jeruzalema.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (16, 12, 30, 'Svećenici i leviti očistili su sebe, a zatim su očistili narod, vrata i zid.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (16, 12, 31, 'Tada sam izveo judejske knezove na zid i sastavio dva velika zbora. Prvi je išao desno niza zid, prema Smetlišnim vratima;');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (16, 12, 32, 'za njima su išli Hošaja i polovina judejskih knezova -');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (16, 12, 33, 'Azarja, Ezra i Mešulam,');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (16, 12, 34, 'Juda, Benjamin, Šemaja i Jeremija,');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (16, 12, 35, 'a od svećeničkih sinova s trubljama: Zaharija, sin Jonatana, sina Šemaje, sina Matanije, sina Mikaje, sina Zakura, sina Asafa,');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (16, 12, 36, 's braćom njihovom Šemajom, Azarelom, Milalajem, Gilalajem, Maajem, Netanelom, Judom, Hananijem, s glazbalima Davida, Božjega čovjeka. A Ezra, književnik, išao je pred njima.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (16, 12, 37, 'Kod Izvorskih vrata popeli su se njima nasuprot kraj stepenica Davidova grada, zidnim usponom od Davidove palače sve do Vodenih vrata na istoku.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (16, 12, 38, 'Drugi zbor, a za njim ja i polovica narodnih knezova, išao je nalijevo zidom i Pećkom kulom sve do Tržnog zida,');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (16, 12, 39, 'pa onda iznad Efrajimovih vrata, Starih vrata, Ribljih vrata, Hananelove kule, kule Meaha, sve do Ovčjih vrata. Zaustavili su se kod Zatvorskih vrata.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (16, 12, 40, 'Potom su oba zbora zauzela mjesto u Domu Božjem. Tako i ja i sa mnom polovica odličnika,');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (16, 12, 41, 'svećenici Elijakim, Maaseja, Minjamin, Mikaja, Elijoenaj, Zaharija, Hananija s trubama,');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (16, 12, 42, 'zatim Maaseja, Šemaja, Eleazar, Uzi, Johanan, Malkija, Elam i Ezer. Pjevači su pjevali pod ravnanjem Jizrahjinim.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (16, 12, 43, 'Toga su dana prinesene velike žrtve, ljudi su dali oduška radosti, jer ih je Bog ispunio velikom radošću, veselile se i žene i djeca. I radost Jeruzalema čula se nadaleko.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (16, 12, 44, 'U to su vrijeme postavljeni ljudi da nadziru spremišta prinosa, prvina, desetina i da s polja uz gradove sabiru dijelove koje Zakon dodjeljuje svećenicima i levitima. Jer su se Judejci radovali svećenicima i levitima koji su bili u službi.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (16, 12, 45, 'Oni su vršili službu Bogu svome i službu očišćenja - kao i pjevači i vratari - prema odredbi Davida i njegova sina Salomona.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (16, 12, 46, 'Jer od Davidovih i Asafovih dana, od davnine, postoje pjevački glavari i pjesme pohvalne i zahvalnice Bogu.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (16, 12, 47, 'Zato je sav Izrael u vrijeme Zerubabela i u Nehemijino vrijeme dan za danom davao dijelove određene za pjevače i vratare. Davali su levitima posvećene darove, a leviti su davali sinovima Aronovim.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (16, 13, 1, 'U ono vrijeme čitala se narodu knjiga Mojsijeva i ondje se našlo zapisano da Amonac i Moabac ne smiju nikada ući u zbor Božji,');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (16, 13, 2, 'jer nisu sinovima Izraelovima izašli u susret s kruhom i vodom, nego su čak najmili protiv njih Bileama da ih prokune, ali je naš Bog obratio kletvu u blagoslov.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (16, 13, 3, 'Kad su čuli Zakon, isključili su iz Izraela sve strance.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (16, 13, 4, 'A prije toga svećenik Elijašib, postavljen nad sobama Doma Boga našega, bijaše svom rođaku Tobiji');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (16, 13, 5, 'uredio prostranu sobu gdje su se prije ostavljali prinosi, tamjan, posuđe, desetine žita, vina i ulja, određene za levite, pjevače i vratare, i doprinosi za svećenike.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (16, 13, 6, 'U to vrijeme nisam bio u Jeruzalemu, jer sam trideset i druge godine babilonskog kralja Artakserksa otišao kralju; ali poslije nekog vremena izmolio sam u kralja');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (16, 13, 7, 'da se mogu vratiti u Jeruzalem. Tada doznadoh za zlo djelo što ga učini Elijašib uredivši Tobiji sobu u predvorjima Doma Božjega.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (16, 13, 8, 'To me veoma rasrdilo: izbacih iz sobe sav namještaj Tobijina stana');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (16, 13, 9, 'i naredih da se sobe očiste, zatim unesoh onamo posuđe Doma Božjega, prinose i tamjan.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (16, 13, 10, 'Doznadoh i to da levitima nisu davali njihovih dijelova i da su se i leviti i pjevači, određeni za službu, razbježali svaki u svoje polje.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (16, 13, 11, 'I prekorih odličnike i rekoh: \"Zašto je zapušten Dom Božji?\" Zatim skupih levite i pjevače i vratih ih k njihovim službama.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (16, 13, 12, 'Tada je sva Judeja donosila u spremišta desetinu žita, vina i ulja.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (16, 13, 13, 'Nad spremištima postavio sam svećenika Šelemju, književnika Sadoka i levita Pedaju, a uz njih Hanana, sina Zakura, sina Matanijina. Njih su smatrali pouzdanima; njihova je dužnost bila da dijele svojoj braći.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (16, 13, 14, 'Zato, sjeti se mene, Bože moj: ne prezri mojih pobožnih djela koja učinih za Dom Boga svoga i za službu u njemu.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (16, 13, 15, 'U ono sam vrijeme vidio u Judeji ljude koji gaze u tijescima u dan subotnji; drugi su nosili snopove žita, tovarili na magarce vino, grožđe, smokve i svakojake terete da ih u dan subotnji unesu u Jeruzalem. I prekorih ljude što u taj dan prodaju živež.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (16, 13, 16, 'A Tirci koji su živjeli u Jeruzalemu donosili su onamo ribu i svakovrsnu robu da je prodaju Židovima u subotu.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (16, 13, 17, 'Prekorih judejske velikaše i rekoh im: \"Kakvo to zlo djelo činite i skrnavite dan subotnji?');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (16, 13, 18, 'Nisu li tako činili i vaši oci te je Bog naš doveo svu ovu nesreću na nas i na ovaj grad? A zar vi želite umnažati gnjev protiv Izraela skrnaveći subotu?\"');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (16, 13, 19, 'I zapovjedih još da uoči subote, kad se mrak spusti na jeruzalemska vrata, zatvore njihova krila i rekoh neka se ne otvaraju do iza subote! Postavio sam nekoliko svojih momaka na vrata da se ne unosi nikakav tovar u dan subotnji.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (16, 13, 20, 'Jednom su ili dvaput trgovci i prodavači svakovrsne robe proveli noć izvan Jeruzalema,');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (16, 13, 21, 'ali sam ih upozorio i rekao im: \"Zašto provodite noć pod zidom? Ako to ponovite, dignut ću na vas ruku!\" Od toga vremena nisu više dolazili u subotu.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (16, 13, 22, 'Zapovjedio sam levitima da se očiste i da dođu čuvati vrata, kako bi se svetkovao dan subotnji. I za ovo se spomeni mene, Bože moj, i smiluj mi se po svome velikom milosrđu!');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (16, 13, 23, 'Onih sam dana vidio i Židove koji se bijahu oženili Ašdođankama, Amonkama i Moapkama.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (16, 13, 24, 'Polovica njihovih sinova govorila je ašdodski ili jezikom ovoga ili onoga naroda: više nisu znali govoriti židovski.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (16, 13, 25, 'Korio sam ih i proklinjao, neke sam i tukao, čupao im kose i zaklinjao ih Bogom: \"Ne dajite svojih kćeri njihovim sinovima i ne uzimajte žene od njihovih kćeri za svoje sinove, a ni za sebe!');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (16, 13, 26, 'Nije li u tome sagriješio Salomon, kralj Izraelov? Među mnogim narodima nije bilo kralja njemu ravna. Bio je drag Bogu svome i Gospod ga je postavio kraljem nad svim Izraelom. Ali su i njega tuđinke navele na grijeh!');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (16, 13, 27, 'Treba li slušati kako i vi činite veliko zlo i postajete nevjerni Bogu našemu ženeći se tuđinkama?\"');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (16, 13, 28, 'Jedan od sinova Jojade, sina velikog svećenika Elijašiba, bijaše zet Horonjaninu Sanbalatu. Njega sam otjerao od sebe.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (16, 13, 29, 'Spomeni se, Bože moj, ovih ljudi, jer su oskvrnuli svećeništvo i zavjet svećenički i levitski.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (16, 13, 30, 'Tako sam ih očistio od svega tuđega i opet uspostavio službe svećenika i levita dodijelivši svakome njegov posao.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (16, 13, 31, 'Uredio sam i da se nose drva u određene dane i prvine. Sjeti me se, Bože moj, za moje dobro!');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (17, 1, 1, 'Povijest Tobita, sina Tobielova, sina Ananielova, sina Aduelova, sina Gabaelova, potomka Asielova, iz plemena Naftalijeva -');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (17, 1, 2, 'koji je u vrijeme Šalmanasara, kralja asirskoga, bio odveden u sužanjstvo iz Tisbe, koja se nalazi južno od Kedeša Naftalijeva, u Gornjoj Galileji, nešto poviše Hasora.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (17, 1, 3, 'Ja, Tobit, hodio sam putovima istine i pravde svega svog života. Udijelio sam mnogo milostinje svojoj braći i ljudima koji su došli sa mnom u Ninivu, zemlju Asiraca.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (17, 1, 4, 'Dok sam se, u vrijeme svoje mladosti, još nalazio u domovini, u zemlji Izraelovoj, sve se pleme Naftalija, oca mojega, bilo udaljilo od doma Davidova i od Jeruzalema, izabrana među svim plemenima Izraelovim da bi u njemu prinosili svoje žrtve. Zbog toga je i bio podignut i posvećen Hram, Prebivalište Svevišnjega, za sva vjekovita pokoljenja.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (17, 1, 5, 'Ali su se sva plemena okrenula, pa i pleme oca moga Naftalija, i prinosila su žrtve teletu što ga bijaše načinio Jeroboam, kralj izraelski, u Danu, na brdima galilejskim.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (17, 1, 6, 'Često sam tako, za svetkovinu, sam išao u Jeruzalem, da se poklonim, kako je propisano svemu Izraelu zauvijek, noseći prvine i desetine plodina i vunu prve postrižine.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (17, 1, 7, 'Predavao sam sve to svećenicima, sinovima Aronovim, za žrtvenik; od svih plodova davao sam desetinu sinovima Levijevim, koji vrše službu u Jeruzalemu, i prodavao odgovarajući dio druge desetine te utržak trošio svake godine u Jeruzalemu.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (17, 1, 8, 'Najposlije, poklanjao sam treću desetinu onima kojima je pripadala, kao što mi bijaše naredila Debora, moja baka, budući da sam iza oca ostao siroče.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (17, 1, 9, 'Kad postadoh zreo čovjek oženih se Anom, djevojkom iz svoga plemena, i dobih s njome sina Tobiju.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (17, 1, 10, 'Kad sam kao sužanj došao u Ninivu, sva moja braća, a tako i moji suplemenici, blagovahu jela poganska;');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (17, 1, 11, 'a ja sam otklanjao da ih jedem.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (17, 1, 12, 'Misli sam i srce upravljao Bogu svome,');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (17, 1, 13, 'i zato me Svevišnji nagradi milošću i naklonošću Šalmanasara, komu postadoh upraviteljem dobara.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (17, 1, 14, 'Poslije toga išao sam u Mediju, gdje sam za nj kupovao sve do njegove smrti i ondje pohranih deset srebrenih talenata u Gabaela, Gabrijeva brata, u Ragesu, gradu medijskom.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (17, 1, 15, 'Ali kada Šalmanasar umrije, zakralji se mjesto njega Sanherib, njegov sin. Ceste njegove postadoše opasne i ja više nisam mogao ići u Mediju.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (17, 1, 16, 'U vrijeme Šalmanasarovo dijelio sam obilno milostinju svojoj braći:');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (17, 1, 17, 'hranio sam gladne, odijevao gole, kad bih vidio koga od roda svoga ubijena pa bačena izvan zidina Ninive, brižno bih ga ukopao.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (17, 1, 18, 'Sahranjivao sam potajno one koje je ubio kralj Sanherib, natjeran na povlačenje iz Judeje. Uistinu, ubio ih je mnogo u svome gnjevu: po naređenju kraljevu tražili su mrtva tijela, ali ih ne mogahu naći.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (17, 1, 19, 'Onda jedan iz Ninive ode kralju te me tuži da sam ja onaj koji ih pokopava; a ja se tada utajah. Doznavši da me traže kako bi me pogubili, uplašen se udaljih.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (17, 1, 20, 'Zaplijenili su mi sva dobra i ne osta mi ništa do žene Ane i sina Tobije.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (17, 1, 21, 'Nije prošlo ni pedeset dana kadli kralja ubiše njegova dva sina; poslije toga pobjegoše u planinu Ararat, a zakralji se mjesto njega sin mu Asarhadon. On na čelo državne riznice i čitave uprave postavi Ahikara, sina moga brata Anaela.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (17, 1, 22, 'Ahikar se zauze za me i ja se vratih u Ninivu. Ahikar je Sanheribu, kralju asirskom, bio peharnik, čuvar državnog pečata, upravitelj i rizničar. Asarhadon ga imenova na sve te dužnosti ponovo. A bijaše Ahikar moj bratić.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (17, 2, 1, 'Kad sam se dakle sa svojom ženom Anom i sa sinom Tobijom opet našao na svome, bijaše mi na Pedesetnicu, a to je Blagdan sedmica, priređen lijep objed i ja sjedoh da blagujem.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (17, 2, 2, 'Vidjevši ona mnoga jela, rekoh sinu: \"Idi i dovedi jednoga od naše braće na koga naiđeš a koji se sjeća Gospodina. Eto, čekat ću te!\"');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (17, 2, 3, 'Kad se sin vratio, kaza: \"Oče, jedan od našega roda zadavljen je i bačen na trg.\"');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (17, 2, 4, 'A ja, ništa i ne okusiv, skočih na noge i unesoh onoga mrtvaca u jednu kuću, gdje mogaše ostati sve do zalaza sunca.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (17, 2, 5, 'Potom se vratih, umih se i pojedoh svoj objed u žalosti.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (17, 2, 6, 'Sjetih se Amosova proročanstva: \"Svetkovine vaše u tugu će se pretvoriti, a radosti vaše kuknjavom će postati.\" I zaplakah.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (17, 2, 7, 'Kad je sunce zašlo, odoh, iskopah raku i sahranih mrtvoga.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (17, 2, 8, 'Susjedi mi se rugali i govorili: \"Zar se ne boji da će ga zbog toga ubiti? Jednom se izvukao, a sad opet pokopa mrtvace.\"');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (17, 2, 9, 'Iste noći, poslije onog ukopa, vratih se kući, a kako bijah nečist, legoh kraj zida u vrtu; bilo je toplo pa sam spavao otkrivena lica.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (17, 2, 10, 'Nisam znao da je u zidu bila ptičica. I kako mi oči bijahu otvorene, padoše mi tople ptičje izmetine u oči i od toga dobih bijele mrlje. Išao sam liječnicima, ali mi ne mogoše pomoći. Uzdržavao me Ahikar dok ne ode u Elimaidu.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (17, 2, 11, 'Moja je žena Ana odonda zarađivala ručnim radom: prela je i tkala.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (17, 2, 12, 'Kad bi gospodarima obavila posao, platili bi joj. Sedmoga ožujka dovrši tako jedan rad i posla ga gospodarima. Oni joj sve isplatiše i povrh toga pokloniše jare.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (17, 2, 13, 'Kad ga dovede, jare poče večati. Upitah ženu: \"Odakle ti jare? Da možda nije ukradeno? Vrati ga gospodarima, jer nije dopušteno jesti što je ukradeno.\"');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (17, 2, 14, 'A ona odgovori: \"Dadoše mi ga kao dar povrh plaće.\" Ali ja nisam vjerovao, nego sam joj, naljutivši se na nju, svejednako govorio da ga vrati gospodarima. A ona onda odgovori: \"Gdje su tvoje milostinje i tvoja dobra djela? Eto, vide se na tebi!\"');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (17, 3, 1, 'Ojađen zaplakah i počeh moliti pun tuge:');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (17, 3, 2, '\"Pravedan si, Gospode, sva su tvoja djela i svi tvoji putovi milosrđe i istina: ti si sudac svijeta.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (17, 3, 3, 'Spomeni me se i pogledaj na me: ne kažnjavaj me zbog mojih grijeha ni zbog prijestupa otaca mojih, koji su griješili pred tobom.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (17, 3, 4, 'Uistinu smo prestupili zapovijedi tvoje te si nas prepustio pljački, zatočenju, smrti i porugi među svim narodima među koje si nas razasuo.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (17, 3, 5, 'Pravedni su tvoji sudovi zbog grijeha što ih činih ja i moji oci, jer se nismo držali tvojih zapovijedi, nismo u istini hodili pred tobom.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (17, 3, 6, 'Sad postupaj sa mnom po svojoj volji, odluči se da prihvatiš moj duh, da umrem i postanem zemlja. Jer mi je bolje umrijeti nego živjeti i slušati lažne prijekore i gorčinu u duši kÓupiti. Zapovjedi da budem oslobođen od ove pokore pa da odem u prostore vječne: ne odvrći lica svoga od mene.\"');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (17, 3, 7, 'Istoga dana i Sari, kćeri Raguelovoj, u Ekbatani Medijskoj, dogodi se te je izruži jedna sluškinja njezina oca');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (17, 3, 8, 'zbog toga što je sedam muževa za koje Sara bijaše pošla pakosni zloduh Asmodej ubio prije nego što su ušli k njoj. Reče joj ona sluškinja: \"Jest, ubijaš svoje muževe! Sedam si ih imala, a ne bijaše ti sreće ni s jednim.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (17, 3, 9, 'Zašto nas kažnjavaš? Ako su umrli, poteci za njima! Nikad mi ne vidjele ni tvoga sina ni tvoje kćeri!\"');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (17, 3, 10, 'Kad je Sara to čula, veoma se ražalostila. Plačući je otišla u očevu sobu, u nakani da se objesi. Ali onda, promislivši, reče u sebi: \"Zar da mi oca kude i da mu predbacuju: \'Imao si jedinu, ljubljenu, kćer, pa ti se, na nesreću, i ona objesila.\' Starog bih oca svoga rastužila i gurnula u carstvo mrtvih. Ne, neću se objesiti: bolje mi je moliti Boga da mi udijeli smrt da nikad više ne čujem ovakvih uvreda.\"');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (17, 3, 11, 'I raskrilivši ruke kraj prozora, pomoli se ovako: \"Blagoslovljen, Bože milosrđa, i blagoslovljeno tvoje Ime navijeke! Blagoslivljaju te sva tvoja djela zauvijek.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (17, 3, 12, 'Obraćam, Gospode, lice svoje k tebi i oči upirem u te.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (17, 3, 13, 'Zapovijedi, Gospode, da pođem s ove zemlje i da više nikada ne čujem one uvrede.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (17, 3, 14, 'Ti znaš, Gospode, da sam čista od svakoga grijeha s čovjekom');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (17, 3, 15, 'i da nisam uprljala ime svoje, ni ime oca svojega u zemlji sužanjstva. Jedina sam kći u oca, nema on drugoga djeteta koje bi ga naslijedilo, niti kakva brata blizu, niti rođaka koga bih čekala. Sedam sam muževa već izgubila: tÓa čemu bih još živjela? Ne želiš li mi smrt udijeliti, svrni onda pogled na me i smiluj se da nikad više ne čujem onih uvreda.\"');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (17, 3, 16, 'Obje molitve bijahu uslišane pred Slavom Gospodnjom.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (17, 3, 17, 'I bi poslan Rafael, anđeo Gospodnji, da ih oboje izliječi: da skine bijele mrlje s Tobita i vid mu vrati; a Saru, kćer Raguelovu, da dade za ženu Tobiji, sinu Tobitovu, te da okuje pakosnog zloduha Asmodeja: jer je ona Tobiji bila namijenjena. U isto vrijeme Tobit se vrati u svoju kuću, a Sara, kći Raguelova, siđe iz gornje sobe.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (17, 4, 1, 'Toga dana Tobit se sjeti novca što ga bijaše pohranio kod Gabaela, u Ragesu Medijskom.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (17, 4, 2, 'I reče u sebi: \"Zazivao sam smrt; zašto ne bih radije dozvao Tobiju, svoga sina, da mu kažem to o novcu prije nego umrem?\"');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (17, 4, 3, 'Dozvavši ga, reče mu: \"Sine, kada umrem, pristojno me pokopaj. Poštuj svoju majku, ne ostavljaj je svega svog života, čini sve što će joj biti milo i nemoj je žalostiti.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (17, 4, 4, 'Sjeti se, sine, da se ona suočila s mnogim opasnostima dok si joj bio u krilu. A kad umre, sahrani je pokraj mene u istome grobu.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (17, 4, 5, 'Svakog dana, sine, sjeti se Gospodina Boga našega; nemoj griješiti ili kršiti njegovih zapovijedi. Čini pravedna djela svega svog vijeka i ne kroči putovima nepravde.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (17, 4, 6, 'Jer ako činiš po istini, uspijevat ćeš u djelima svojim, kao svi oni koji čine pravdu.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (17, 4, 7, 'Djeli milostinju od svoga dobra: kad dijeliš milostinju, neka ti ne bude oko stisnuto. Ne okreći lica od siromaha, pa ni Bog neće okrenuti lica od tebe.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (17, 4, 8, 'Od onoga što imaš i prema tome koliko imaš dijeli milostinju: imaš li malo, daj malo, ali ne oklijevaj dati milostinju.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (17, 4, 9, 'Jer dobar polog spremaš sebi za dan potrebe.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (17, 4, 10, 'Udijeljena milostinja oslobađa od smrti i ne dopušta da odeš u mrak.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (17, 4, 11, 'Jer milostinja je mio dar pred licem Svevišnjega.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (17, 4, 12, 'Čuvaj se, sine, svakoga preljuba. I pazi da ti žena bude iz plemena tvojih otaca; ne uzimaj za ženu tuđinku koja ne pripada koljenu tvoga oca, jer mi smo sinovi proročki. Noa, Abraham, Izak, Jakov naši su oci odiskona; sjeti se, sine, da su svi oni uzeli žene među svojom braćom i da su bili blagoslovljeni u svojoj djeci, njihovo potomstvo dobit će zemlju u nasljedstvo.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (17, 4, 13, 'I onda, sine, ljubi svoju braću i nemoj se uzoholiti u srcu pred svojom braćom, ni pred sinovima i kćerima svoga naroda, skanjujući se da odabereš ženu između njih! U oholosti leži mnoga propast i nemir, a od dangube samo je šteta i bijeda, jer je nerad majka gladi.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (17, 4, 14, 'Neka ničija zarada ne prenoći kod tebe, nego je isplati odmah. Budeš li služio Bogu, platit će ti se. Razmišljaj, sine, o svakome svom djelu i lijepo se vladaj.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (17, 4, 15, 'Ne čini nikome što bi tebi samomu bilo mrsko. Ne pij vina do pijanosti; neumjerenost uklanjaj sa svoga puta.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (17, 4, 16, 'Dijeli svoj kruh s gladnima, a svojom odjećom odjeni gologa. Sve što ti je suvišno daj drugima, a kada dijeliš milostinju, neka ti oko ne bude stisnuto.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (17, 4, 17, 'Metni svoj kruh na grob pravednih i ne daj ga grešnicima.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (17, 4, 18, 'Obraćaj se uvijek onome tko je mudar i ne odbacuj korisna savjeta.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (17, 4, 19, 'U svakoj prilici hvali Gospoda Boga i moli ga da ti upravlja putove, da sve tvoje staze i namjere dobro završe. Jer nijedan narod ne posjeduje mudrosti: Bog je onaj koji udjeljuje svako dobro, ponižava kako hoće, sve do dna carstva mrtvih. Sjeti se, sine, mojih pouka: neka ti se nikada iz srca ne izbrišu.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (17, 4, 20, 'A sada ću te, sine, uputiti glede onih deset srebrnih talenata koje sam pohranio u Gabaela, sina Gabrijeva, u Ragesu Medijskom.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (17, 4, 21, 'Ne plaši se, sine, što smo osiromašili. Bit ćeš bogat budeš li se bojao Boga, klonio se svakoga grijeha i vršio ono što je Bogu milo.\"');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (17, 5, 1, 'Tobija odgovori ocu: \"Oče moj, učinit ću sve što si mi naredio.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (17, 5, 2, 'Samo, kako ću preuzeti novac kad ne znam onoga u koga je pohranjen.\"');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (17, 5, 3, 'Onda mu otac dade zadužnicu i reče: \"Potraži čovjeka koji će ići s tobom, a ja ću ga nagraditi. Idi, dakle, i podigni novac.\"');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (17, 5, 4, 'Tobija ode da potraži takva čovjeka i nađe Rafaela. Tobija nije znao da je to anđeo Božji.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (17, 5, 5, 'I upita ga: \"Bi li htio sa mnom u Rages Medijski? Znaš li put onamo?\"');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (17, 5, 6, 'Anđeo mu odvrati: \"Bih. Poći ću s tobom. Znam put, bijah već gost našega brata Gabaela.\"');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (17, 5, 7, 'Tobija mu reče: \"Počekaj da javim ocu.\"');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (17, 5, 8, 'Anđeo mu kaza: \"Idi i ne zadržavaj se.\"');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (17, 5, 9, 'Onda Tobija ode ocu te mu reče: \"Evo, našao sam onoga koji će ići sa mnom.\" A otac će mu: \"Dovedi ga meni da čujem kojemu plemenu pripada i je li pouzdan da ti bude pratilac.\"');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (17, 5, 10, 'Tobija ga zovnu, pa kad on uđe, zagrliše se.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (17, 5, 11, 'Onda ga Tobit upita: \"Brate, kojemu rodu i kojoj obitelji pripadaš? Kaži mi!\"');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (17, 5, 12, 'On mu odgovori: \"Tražiš li rod i obitelj ili nekoga koji će za nagradu pratiti tvoga sina?\" Tobit će mu na to: \"Brate, hoću da znam koji su ti preci i kako se zoveš.\"');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (17, 5, 13, 'A on će: \"Ja sam Azarja, sin Ananije, najstarijeg od tvoje braće.\"');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (17, 5, 14, 'Tobit mu kaza: \"Dobro mi došao! I ne ljuti se na me zato što sam htio doznati za tvoj rod i za tvoje ime. Ti si dakle moj brat iz ugledna i plemenita roda. Poznavao sam dobro i Ananiju i Jatana, sinove velikog Semeja, kad smo išli zajedno u Jeruzalem da se poklonimo i prikažemo prvine i desetine plodina. Oni nisu nikada zašli na stranputicu. Braća su ti ljudi valjani. Pripadaš plemenitu rodu.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (17, 5, 15, 'Ali mi kaži kakvu ću ti nagradu dati: jednu drahmu na dan i sve što je potrebno tebi i mome sinu.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (17, 5, 16, 'I još ću ti dodati nešto povrh plaće kad se vratite živi i zdravi.\"');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (17, 5, 17, 'Dogovoriše se tako. A onda kaza Tobiji: \"Spremi se i sretan vam put obojici!\" Sin spremi sve za put. I reče mu njegov otac: \"Idi s ovim čovjekom, a Bog koji na nebu stoluje udijelio vam sretno putovanje i anđeo njegov pratio vas!\"');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (17, 5, 18, 'Ali Ana, majka Tobijina, zaplaka i ukori Tobita: \"Zašto si dopustio da nam sin ode? Nije li on štap naših ruku kad ulazi i izlazi pred nama?');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (17, 5, 19, 'Ne bilo toga novca, smeće je prema našem sinu.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (17, 5, 20, 'Ta ovo što nas je Bog ostavio u životu - dosta nam je.\"');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (17, 5, 21, 'Tobit joj odgovori: \"Ne govori tako, sestro. Vratit će se on živ i zdrav i tvoje će ga oči opet ugledati.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (17, 5, 22, 'Ta prati ga dobar anđeo i njegovo će putovanje biti sretno, vratit će se živ i zdrav.\"');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (17, 5, 23, 'Onda ona prestade plakati.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (17, 6, 1, 'A sin išao s anđelom i pas za njima. Predvečer stigoše do rijeke Tigrisa i tu provedoše noć.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (17, 6, 2, 'Potom momak siđe u rijeku da se okupa, kad najednom skoči iz vode velika riba i htjede ga proždrijeti.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (17, 6, 3, 'Anđeo mu reče: \"Uhvati ribu.\" Nato se momak dočepa ribe te je izvuče na suho.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (17, 6, 4, 'Onda mu anđeo kaza: \"Raspori ribu, izvadi joj srce, jetru i žuč i dobro ih čuvaj jer su koristan lijek.\"');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (17, 6, 5, 'Momak izvrši što mu je anđeo naredio. I pošto su ribu ispekli, pojedoše je,');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (17, 6, 6, 'a onda nastaviše put dok se ne primakoše Ekbatani.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (17, 6, 7, 'Mladić potom upita anđela: \"Brate Azarja, čemu će služiti riblja jetra, srce i žuč?\"');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (17, 6, 8, 'A on odgovori: \"Srce i jetra služe kad koga muči demon ili zao duh: treba to pred takvim, bio muškarac ili žena, spaliti, i nikad ga zao duh više neće mučiti.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (17, 6, 9, 'A žuč se uzima da se njome premažu oči na kojima su bijele mrlje, tako te bolesnik ozdravi.\"');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (17, 6, 10, 'Kad bijahu blizu Ekbatane,');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (17, 6, 11, 'anđeo reče mladiću: \"Brate, noćas ćemo prenoćiti kod Raguela; on ti je rođak, a ima jedinicu kćer koja se zove Sara.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (17, 6, 12, 'Ja ću gledati da ti je dadu za ženu, jer tebi pripada njezino nasljedstvo: jedini si od njezina roda, djevojka je lijepa i razborita.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (17, 6, 13, 'Sad me poslušaj: govorit ću njenu ocu, i kad se vratimo iz Ragesa, proslavit ćemo svadbu. Jer ja znam da je Raguel, prema Mojsijevu zakonu, ne može dati drugome, a kad bi to uradio, zaslužio bi smrt, jer ti imaš pravo na nasljedstvo pred svakim drugim.\"');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (17, 6, 14, 'Onda mladić kaza anđelu: \"Brate Azarja, čuo sam da je djevojka već bila dana sedmorici ljudi i da su svi nađeni mrtvi u svadbenoj sobi:');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (17, 6, 15, 'jedinac sam u oca; bojim se da ću, odem li k njoj, umrijeti kao i oni prije mene; jer nju ljubi neki demon koji ne čini zla drugima, osim onima koji joj se približe. Bojim se da ne umrem i da za sobom, zbog žalosti, ne povučem u grob svoga oca i svoju majku, a nemaju drugoga sina da ih sahrani.\"');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (17, 6, 16, 'Anđeo mu reče: \"Ne sjećaš se kako ti je otac naredio da uzmeš za ženu samo onu koja pripada tvome rodu? Zato me poslušaj, brate: ona će biti tvoja žena, a ti se ne osvrći na demona, jer će još noćas biti tvoja.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (17, 6, 17, 'Kad budeš ušao u svadbenu sobu, uzet ćeš tamjanova pepela i metnut ćeš na nj malo ribljeg srca i jetre; kad tako okadiš, demon će oćutjeti vonj i pobjeći će i neće se više vratiti.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (17, 6, 18, 'Kad se htjedneš približiti k njoj, bdijte oboje i dozivajte milostivog Boga: on će vas spasiti i smilovati vam se. Ne boj se: ona ti je bila dosuđena oduvijek, ti ćeš je spasiti; ona će poći s tobom i mislim da ćeš s njom imati poroda.\" Kad je Tobija čuo sve to, odmah mu ona omilje i njegova se duša privinu uz njezinu.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (17, 6, 19, '');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (17, 7, 1, 'Onda uđoše u Ekbatanu i pođoše prema kući Raguelovoj. Sara im dođe u susret, pozdravi ih i oni nju pozdraviše, pa ih ona uvede u kuću.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (17, 7, 2, 'Raguel reče Edni, svojoj ženi: \"Kako li je ovaj samo nalik na Tobita, moga rođaka!\"');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (17, 7, 3, 'Raguel ih zapita: \"Odakle ste, braćo?\" Odgovoriše mu: \"Mi pripadamo Naftalijevim sinovima koji su bili prognani u Ninivu.\"');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (17, 7, 4, 'Kaza im on: \"Poznajete li Tobita, brata našega?\" Oni odgovoriše: \"Poznajemo ga.\"');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (17, 7, 5, 'Onda ih upita: \"Je li dobro s njime?\" Oni odgovoriše: \"Živ je i dobro je.\" Tobija nadoda: \"To je moj otac.\"');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (17, 7, 6, 'Nato ga Raguel zagrli, poljubi ga suznih očiju i blagoslovi ga čudeći se: \"Ti si dakle sin onoga plemenitog i dobrog čovjeka.\" Doznavši da je Tobit izgubio vid, ražalosti se i zaplaka.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (17, 7, 7, 'I žena mu Edna i kći Sara zaplakaše i primiše ih spremno.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (17, 7, 8, 'Potom zaklaše ovna i pripremiše jela u izobilju.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (17, 7, 9, 'Tobija kaza Rafaelu: \"Brate Azarja, govori o onome o čemu si mi pripovijedao na putu.\"');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (17, 7, 10, 'Anđeo prozbori o tom s Raguelom, a on će Tobiji: \"Jedi, pij i budi veseo, jer tebi pripada moja kći. Ipak ti moram otkriti istinu:');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (17, 7, 11, 'već bijah svoju kćer dao sedmorici, ali kad joj se približiše, svi noću pomriješe. Ali ti sada budi veseo.\"');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (17, 7, 12, 'Tobija odgovori: \"Neću ništa okusiti dok se ne odlučite i ne izvršite što treba.\" Nato mu Raguel kaza: \"Uzmi je od ovoga časa po pravdi: ti si njezin brat i ona pripada tebi. Milosrdni Bog neka vam udijeli sreću.\"');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (17, 7, 13, 'Zatim pozva Saru, svoju kćer; uzevši je za ruku, dade je kao zaručnicu Tobiji govoreći: \"Evo, uzmi je prema Mojsijevu zakonu i odvedi je k svome ocu.\" I blagoslovi ih.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (17, 7, 14, 'Onda pozva Ednu, ženu svoju. Dohvativši list, napisa ugovor i udari pečat. Potom počeše blagovati.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (17, 7, 15, 'Nakon toga pozva Raguel Ednu, ženu svoju, i reče joj: \"Sestro, pripremi drugu sobu i uvedi je.\"');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (17, 7, 16, 'Ona uradi kako joj je zapovjedio i uvede je. Kći zaplaka.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (17, 7, 17, 'Vidjevši suze svoje kćeri, kaza joj: \"Budi hrabra, kćerko: Gospodar neba i zemlje neka te nagradi milošću za tvoju bol. Budi hrabra, kćerko!\"');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (17, 8, 1, 'Kad su povečerali, uvedoše Tobiju k Sari.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (17, 8, 2, 'On se, ulazeći k njoj, sjeti Rafaelovih riječi: uze tamjanova pepela, metnu na nj riblje srce i jetru i okadi.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (17, 8, 3, 'Tek što demon oćutje vonj, pobježe u Gornji Egipat, a anđeo ga ondje okova.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (17, 8, 4, 'Kako su se zatvorili u sobu, Tobija ustade s postelje i reče: \"Ustaj, sestro, molimo se da nam se Bog smiluje.\"');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (17, 8, 5, 'Onda se Tobija poče moliti: \"Blagoslovljen da si, Bože naših otaca, blagoslovljeno sveto i slavno ime tvoje u sve vijeke! Blagoslivljala te nebesa i sva tvoja stvorenja u sve vijeke!');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (17, 8, 6, 'Ti si stvorio Adama i dao mu pomoćnicu Evu: od njih je proizašao ljudski rod. Ti si rekao: \'Nije dobro da čovjek bude sam; načinimo mu pomoćnicu sličnu njemu.\'');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (17, 8, 7, 'Gospode, ne uzimam zbog pohote ovu svoju sestru nego po istini. Smiluj mi se i učini da s njom doživim starost.\"');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (17, 8, 8, 'I zajedno rekoše: \"Amen, amen.\"');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (17, 8, 9, 'I zaspaše oboje te noći.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (17, 8, 10, 'A Raguel usta i pođe da iskopa raku misleći: \"Ako i on umre.\"');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (17, 8, 11, 'Raguel se vrati u svoju kuću');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (17, 8, 12, 'i kaza Edni, ženi svojoj: \"Pošalji jednu od sluškinja da vidi je li živ. Ako je umro, pokopajmo ga odmah da nitko ne sazna.\"');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (17, 8, 13, 'Sluškinja otvori vrata, uđe i nađe kako oboje spavaju.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (17, 8, 14, 'Izađe i javi im: \"Dobro je, živ je.\"');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (17, 8, 15, 'Nato Raguel zahvali Bogu: \"Blagoslovljen da si, Bože, svakim blagoslovom čistim i svetim. Blagoslivljali te sveti tvoji i sva tvoja stvorenja! Svi anđeli i svi izabranici tvoji blagoslivljali te u sve vijeke!');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (17, 8, 16, 'Blagoslovljen jer si me razveselio i jer se nije dogodilo čega se bojah, nego si nam iskazao svoje bogato milosrđe.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (17, 8, 17, 'Blagoslovljen jer si se smilovao ovoj djeci što su jedina. Izlij na njih svoje milosrđe, Gospode, podari im da zavše život u zdravlju, sa srećom i milosrđem.\"');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (17, 8, 18, 'A zatim zapovjedi kućnoj čeljadi da zatrpaju raku.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (17, 8, 19, 'Tada priredi gozbu koja je trajala četrnaest dana.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (17, 8, 20, 'Prije nego što su izminuli svadbeni dani, Raguel uze zaklinjati Tobiju: \"Ne idi na put dok se ne navrši četrnaest svadbenih dana,');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (17, 8, 21, 'a onda primi polovicu imutka i vrati se živ i zdrav svome ocu. Drugi ćeš dio dobiti poslije moje i ženine mi smrti.\"');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (17, 9, 1, 'Onda Tobija pozva Rafaela i reče mu:');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (17, 9, 2, '\"Brate Azarja, uzmi sa sobom jednog slugu i dvije deve pa idi Gabaelu u Rages koji se nalazi u Mediji: uzmi od njega novac pa dovedi i njega na pir,');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (17, 9, 3, 'jer me Raguel zaklinjao da ne odlazim.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (17, 9, 4, 'Znaš da moj otac broji dane, pa budem li se mnogo zadržavao, bit će zabrinut veoma.\"');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (17, 9, 5, 'Tada Rafael ode. Provede noć u Gabaela i dade mu obveznicu. Gabael izvuče zapečaćene vrećice te mu ih izruči.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (17, 9, 6, 'Brzo se krenuše obojica i dođoše na pir. Tobija blagoslovi svoju ženu.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (17, 10, 1, 'A otac Tobijin brojio svaki dan. I kad je prošlo vrijeme za povratak a sina ne bijaše,');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (17, 10, 2, 'reče Tobit: \"Možda su odbijeni? Ili je možda umro Gabael pa novac nije predan?\"');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (17, 10, 3, 'I rastuži se veoma.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (17, 10, 4, 'Kaza mu žena: \"Dijete je stradalo kad ga tako dugo nema.\"');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (17, 10, 5, 'I poče jadikovati: \"Kako da ne budem zabrinuta, dijete moje, kad sam ti dopustila da odeš, svjetlo očiju mojih!\"');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (17, 10, 6, 'Tobit je stade tješiti: \"Šuti, ne govori: njemu je dobro.\"');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (17, 10, 7, 'Ona mu odgovori: \"Šuti ti i ne zavaravaj me; znam ja, stradalo je dijete moje.\" Svakog je dana izlazila na cestu kojom je sin krenuo na put; danju ne bi ni dodirnula jela, a noću nije prestajala jadikovati za svojim Tobijom. Kad prođe četrnaest dana svadbenih za kojih Raguel zaklinjaše Tobiju da ostane,');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (17, 10, 8, 'Tobija kaza Raguelu: \"Pusti me da idem, jer su već otac moj i majka moja izgubili nadu da će me još ugledati.\"');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (17, 10, 9, 'Tast ga zamoli: \"Ostani kod mene, a ja ću se pobrinuti da pronađem nekoga koji će ocu tvome donijeti vijesti o tebi.\" Ali mu Tobija odvrati: \"Ne, nego me pusti da idem k ocu svome!\"');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (17, 10, 10, 'Raguel onda ustade, preda mu Saru, njegovu ženu, i polovicu imutka, sluge, stoku i novac.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (17, 10, 11, 'Pošto ih je blagoslovio, oprosti se s njima govoreći: \"Djeco, Bog nebeski nek\' vam udijeli sreću još prije nego što umrem.\"');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (17, 10, 12, 'A svojoj kćeri kaza: \"Poštuj svekra i svekrvu: oni su ti sada roditelji. I da čujem samo dobre vijesti o tebi.\" I poljubi je.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (17, 10, 13, 'Onda Edna reče Tobiji: \"Ljubljeni brate moj, nek\' ti Gospodar neba dade sretan povratak, a meni neka udijeli milost da vidim djecu koju ćeš imati s mojom Sarom, da osjetim radost pred Gospodom. Evo, predajem ti kćer svoju na čuvanje: ne žalosti je.\"');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (17, 10, 14, 'Zahvalivši Bogu što mu je udijelio sretan put i poželjevši blagoslov Raguelu i Edni, ženi njegovoj, Tobija krenu.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (17, 11, 1, 'Nastaviše put dok se ne približiše Ninivi.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (17, 11, 2, 'Onda Rafael kaza Tobiji: \"Ne znaš li, brate, u kakvu si stanju ostavio oca svoga?');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (17, 11, 3, 'Potrčimo nas dvojica prije tvoje žene i priredimo kuću:');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (17, 11, 4, 'uzmi u ruku riblju žuč.\" Krenuše, a pas za njima.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (17, 11, 5, 'Dotle je Ana sjedila i gledala na put ne bi li ugledala svoje dijete.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (17, 11, 6, 'Izdaleka ga opazi pa reče Tobitu: \"Evo, vraća se sin tvoj i čovjek koji ga pratio.\"');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (17, 11, 7, 'A Rafael reče Tobiji: \"Znam da će otac tvoj otvoriti oči.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (17, 11, 8, 'Ribljom žuči namaži njegove oči, a on će ih, oćutjevši svrbež, protrljati i tako skinuti s njih bijele mrlje i tebe vidjeti.\"');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (17, 11, 9, 'Dotle se Ana, potrčavši naprijed, baci u zagrljaj sinu svome i reče mu: \"Opet te vidim, sine moj! Od ovoga časa mogu mirno umrijeti!\" Nato oboje zaplakaše.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (17, 11, 10, 'Tobit iziđe na vrata i spotače se, ali sin potrča k njemu');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (17, 11, 11, 'i pridrža ga, razmaza žuč ocu preko očiju i kaza: \"Hrabro, oče moj!\"');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (17, 11, 12, 'Kad ga oči zasvrbješe, protrlja ih, a iz očinjih mu se kutića oljuštiše bijele mrlje.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (17, 11, 13, 'Ugledavši sina, zagrli ga, zaplaka i probesjedi:');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (17, 11, 14, '\"Blagoslovljen da si, Bože, blagoslovljeno tvoje ime uvijeke i blagoslovljeni svi tvoji sveti anđeli! Jer si me udario pa se smilovao na me: evo gledam svoga sina Tobiju!\"');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (17, 11, 15, 'Njegov sin, sav sretan, uđe u kuću te izvijesti oca o velikim događajima što su mu se zbili u Mediji.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (17, 11, 16, 'Tobit, prepun radosti i blagoslivljajući Boga, pođe u susret snahi, prema vratima Ninive. Oni koji su ga vidjeli kako hoda bijahu zadivljeni što je progledao, a Tobit priznavaše pred njima da mu se Bog smilovao.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (17, 11, 17, 'Kada Tobit dođe do Sare, snahe svoje, pozdravi je govoreći joj: \"Dobro došla, kćeri moja! Blagoslovljen Bog koji te doveo k nama! I neka su ti blagoslovljeni i otac i majka!\"');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (17, 11, 18, 'I velika radost obuze svu braću njegovu u Ninivi.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (17, 11, 19, 'A dođoše i Ahikar i njegov nećak Nasbas pa se Tobijina svadba u veselju slavila sedam dana.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (17, 12, 1, 'Potom Tobit pozva Tobiju, sina svoga, i reče mu: \"Sine, pobrini se za plaću čovjeku koji je išao s tobom; a treba mu dati i štogod povrh toga.\"');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (17, 12, 2, 'Sin odgovori: \"Neću štetovati dadem li mu i polovicu onoga što sam donio,');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (17, 12, 3, 'jer me doveo k tebi zdrava, izliječio moju ženu, podigao moj novac, a onda i tebi vratio zdravlje.\"');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (17, 12, 4, 'Starac odgovori: \"To mu s pravom pripada!\"');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (17, 12, 5, 'Onda pozva anđela i kaza mu: \"Uzmi polovicu od svega onoga što ste donijeli.\"');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (17, 12, 6, 'Tada anđeo pozva njih dvojicu u stranu i reče im: \"Blagoslivljajte Boga, hvalite ga i veličajte, hvalite ga pred svim živima zbog onoga što je za vas učinio. Lijepo je hvaliti Boga i uznositi ime njegovo; bogobojazno razglašavati djela njegova.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (17, 12, 7, 'Lijepo je čuvati tajnu kraljevu, ali je slavno otkrivati djela Božja. Činite dobro, i neće vas zlo snaći.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (17, 12, 8, 'Dobra je molitva s postom, s milostinjom i s pravednošću. Bolje je malo s pravednošću nego mnogo s nepravdom. Bolje je dijeliti milostinju nego sabirati u hrpe zlato.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (17, 12, 9, 'Milostinja oslobađa od smrti, ona čisti od svakoga grijeha. Koji dijele milostinju i čine pravednost napunit će se života,');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (17, 12, 10, 'a koji griješe bit će dušmani životu svome.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (17, 12, 11, 'Neću vam sakriti ništa: kazah već da je lijepo čuvati tajnu kraljevu, ali je slavno otkrivanje Božjih djela.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (17, 12, 12, 'I kad ste molili ti i tvoja snaha Sara, ja sam nosio vaše molitve Svetome; kad si ti pokapao mrtve, i ja sam bio uza te;');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (17, 12, 13, 'kad se nisi skanjivao da ustaneš i prekineš svoj ručak da bi pokopao onog mrtvaca, nije mi bilo skriveno da vršiš dobro djelo; i bio sam s tobom.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (17, 12, 14, 'Sada, Bog me poslao da izliječim tebe i tvoju snahu Saru.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (17, 12, 15, 'Ja sam Rafael, jedan od sedmorice svetih anđela koji na nebesima donose molitve svetih i stupaju pred Slavom Svetoga!\"');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (17, 12, 16, 'Njih se dvojica preplašiše i padoše ničice, jer ih zahvati velik strah.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (17, 12, 17, 'Ali im anđeo reče: \"Ne plašite se! Mir s vama! Blagoslivljajte Boga uvijeke!');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (17, 12, 18, 'Ta ja ne dođoh jer se meni svidjelo, nego po zapovijedi Boga našega: zato ga blagoslivljajte uvijeke.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (17, 12, 19, 'Sve sam dane dopuštao da me vide vaše oči, ali nisam ni jeo ni pio: vi ste motrili samo privid.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (17, 12, 20, 'Sada hvalite Boga, a ja se vraćam onome koji me i poslao. Zapišite u knjizi sve što se zbilo.\"');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (17, 12, 21, 'Onda oni ustadoše, ali ga više ne vidješe. Hvalili su velika i čudesna djela Božja i pripovijedali kako im se ukazao anđeo Gospodnji.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (17, 12, 22, '');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (17, 13, 1, 'Tobit potom napisa molitvu u radosti i reče:');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (17, 13, 2, '\"Blagoslovljen Bog, koji živi uvijeke, i njegovo kraljevstvo! Jer on kažnjava i prašta, dovodi u Podzemlje i odande izvodi, i nema toga tko bi izmakao njegovoj ruci.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (17, 13, 3, 'Hvalite ga, sinovi Izraelovi, pred poganima, jer vas je on među njih rasuo.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (17, 13, 4, 'Objavljujte njegovu veličinu uzdižući ga nad sve živo, jer on je naš Gospod i Bog, on je naš otac za sve vjekove.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (17, 13, 5, 'On nas kažnjava zbog naših zlih djela, ali će se opet smilovati na nas i sabrati nas iz svih naroda među koje smo razasuti.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (17, 13, 6, 'Obratite se k njemu svim srcem svojim i svom dušom svojom da činite pred njim istinu, i on će se okrenuti k vama, i neće skrivati lica svoga od vas.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (17, 13, 7, 'Gledajte što učini s vama, na sva ga usta slavite i hvalite, blagoslivljajte Gospoda pravde i uzvisujte kralja vjekova.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (17, 13, 8, 'Ja ga u zemlji progonstva hvalim i očitujem njegovu moć i veličinu grešnom narodu. Obratite se, grešnici, i činite pravdu pred njim. Tko zna hoće li pogled svrnuti na vas i milost vam iskazati!');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (17, 13, 9, 'Boga svoga ja uznosim, i duša moja hvali kralja nebeskoga, i radosno klikće veličini njegovoj:');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (17, 13, 10, 'tako neka kazuju svi i hvale ga u Jeruzalemu! Jeruzaleme, grade sveti! On će te kazniti zbog djela sinova tvojih, ali će se opet smilovati sinovima pravednih.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (17, 13, 11, 'Podaj hvalu Gospodu zanosno i blagoslivljaj kralja vjekova da ti njegov Šator ponovno bude podignut uz veselje;');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (17, 13, 12, 'da bi se u tebi obradovali prognani i da bi u tebi ljubav našli siromasi za sva pokoljenja.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (17, 13, 13, 'Narodi će dolaziti izdaleka k imenu Gospoda Boga donoseći u rukama darove, darove za kralja nebeskoga: pokoljenja upravljat će ti radosne hvale.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (17, 13, 14, 'Prokleti svi oni koji te mrze, blagoslovljeni zauvijek oni koji te ljube.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (17, 13, 15, 'Veseli se i raduj se zbog sinova pravednih, jer će biti sakupljeni i blagoslivljat će Gospoda pravednih. Blaženi oni koji te ljube! Veselit će se zbog tvoga mira!');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (17, 13, 16, 'Blaženi svi koji se rastužiše zbog tvojih nesreća, jer će se radovati kad vide svu tvoju slavu i radovat će se uvijeke. Duša moja neka hvali Boga, kralja velikoga!');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (17, 13, 17, 'Jer će Jeruzalem biti obnovljen safirom i smaragdom, njegove zidine dragim kamenjem, tornjevi i bedemi čistim zlatom, a trgovi popločani berilom, dijamantom i dragim kamenjem iz Ofira.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (17, 13, 18, 'Njegove će ulice kazivati: \'Aleluja!\' i klicat će: \'Blagoslovljen Bog, uzvišen dovijeka.\'\"');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (17, 14, 1, 'Tobit završi pohvalu.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (17, 14, 2, 'Bilo mu je pedeset i osam godina kad je oslijepio, a poslije osam godina opet je progledao. Nastavio je dijeliti milostinju i sveudilj se bojao Gospoda Boga te ga hvalio.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (17, 14, 3, 'Doživio je duboku starost. Na samrti dozva k sebi sina i sinove sina svoga te kaza Tobiji: \"Sinko, uzmi djecu svoju: evo, ostario sam i već sam blizu da se odijelim od života.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (17, 14, 4, 'Preseli se u Mediju, sinko, jer znam da će se sve dogoditi s Ninivom što je o njoj nagovijestio prorok Jona: bit će razrušena, a u Mediji bit će mir za neko vrijeme; naša braća koja se još nalaze u domovini bit će razasuta daleko od lijepe zemlje, Jeruzalem će opustjeti, a Dom Gospodnji koji se nalazi u njemu izgorjet će i bit će pust za neko vrijeme.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (17, 14, 5, 'Ali će se Bog opet smilovati njima i vratit će ih u njihovu zemlju; onda će oni sagraditi hram, ali ne onakav kakav je bio prije, dok se ne ispuni određeno vrijeme. Poslije toga vratit će se iz krajeva progonstva i podići Jeruzalem s velikim počastima. I Dom Božji u njemu bit će sazidan od nadasve vrijedne građe za sva buduća pokoljenja, kao što su kazali za nj proroci:');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (17, 14, 6, 'svi će se narodi uistinu obratiti i bojat će se Gospoda Boga i pokopat će svoje idole; svi će narodi blagoslivljati Gospoda.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (17, 14, 7, 'Onda će narod njegov hvaliti Boga, a Gospod će uzdići narod svoj i bit će radosni svi oni koji ljube Gospoda Boga u istini i pravdi vršeći milosrđe prema braći svojoj.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (17, 14, 8, 'I tako, sine, otiđi iz Ninive, jer će sve biti što je nagovijestio prorok Jona.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (17, 14, 9, 'Ti pak drži zakon i zapovijedi, budi milosrdan i pravedan da ti bude dobro. Časno me pokopaj, a uza me pokopaj majku svoju. Poslije toga ne ostani više ni jednoga dana u Ninivi.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (17, 14, 10, 'Sinko moj, razmotri što Aman učini Ahikaru koji ga je uzgojio: iz svjetla baci ga u tamu i tako zlim plati dobro njegovo. Ali Ahikar bje spašen, a onoga stiže zaslužena kazna: siđe on u tminu. Ahikar dijeljaše milostinju i spasi se od smrtonosne zamke koju mu onaj priredi; u zamku Aman pade i poginu.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (17, 14, 11, 'Dakle, sinovi moji, vidite kakvu snagu ima milostinja i kako pravda spašava.\" To rekavši, izdahnu. Bijaše mu sto pedeset i osam godina. Tobija mu priredi častan ukop.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (17, 14, 12, 'Kad Ana umrije, pokopa je uz oca, pa sa ženom i svojim sinovima krenu u Ekbatanu, k svome tastu Raguelu.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (17, 14, 13, 'Tu doživje časnu starost, časno pokopa svoga tasta i punicu te naslijedi imutak njihov, kao što je naslijedio i očev.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (17, 14, 14, 'Umrije u Ekbatani, u sto dvadeset i sedmoj godini života. Prije nego što je izdahnuo, doznao je za propast Ninive, koju razoriše Nabukodonozor i Asuer. Tako se prije smrti uzradova nad propašću Ninive.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (17, 14, 15, '');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 1, 1, 'Bilo je to dvanaeste godine kraljevanja Nabukodonozora, kralja Asiraca, koji vladaše u velikom gradu Ninivi. U to je vrijeme Arfaksad vladao nad Medijcima u Ekbatani.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 1, 2, 'On sagradi naokolo Ekbatane zidove od tesana i četverouglasta kamena, široka tri lakta i dugačka šest lakata; podigao je bedeme sedamdeset lakata u visinu i pedeset lakata u širinu.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 1, 3, 'Do vrata gradskih podiže kule stotinu lakata visoke, s temeljima koji su bili šezdeset lakata široki.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 1, 4, 'Vrata koja bijaše napravio uzdizahu se sedamdeset lakata u visinu, a široka bijahu četrdeset lakata, kako bi mogla kroz njih izaći golema vojska s povorkom pješaka.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 1, 5, 'U to vrijeme kralj Nabukodonozor vojevaše s kraljem Arfaksadom u velikoj ravnici koja se proteže na području Ragaua.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 1, 6, 'Uza nj se svrstaše svi oni koji su obitavali u planinskim predjelima, svi oni koji su prebivali do obala Eufrata, Tigrisa i Hidaspa, a tako i stanovnici ravnice Arioha, kralja elimskoga: mnogo je dakle bilo ljudstva koje se poredalo u redove naroda keleudskog.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 1, 7, 'Nabukodonozor, kralj Asiraca, uputi poruku svim stanovnicima Perzije, svima onima koji življahu na zapadu, stanovnicima Cilicije, Damaska, Libanona i Antilibanona i svim stanovnicima morske obale,');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 1, 8, 'narodima Karmela, Gileada, Gornje Galileje i prostrane ravnice Ezdrelona,');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 1, 9, 'svima onima koji prebivahu u Samariji i njezinim gradovima, u Transjordaniji sve do Jeruzalema, Batane, Kelusa, Kadeša, Egipatske rijeke, Tafnesa, Ramsesa i po svemu području Gešema,');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 1, 10, 'sve do onkraj Tanisa i Memfisa, najposlije svima stanovnicima Egipta sve do granice Etiopije.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 1, 11, 'Ali stanovnici svake od tih pokrajina narugaše se poruci Nabukodonozora, kralja Asiraca, i ne okupiše se oko njega da bi uza nj vojevali. Nisu ga se bojali, jer on za njih bijaše običan čovjek. Otposlaše praznih ruku glasnike njegove, ne iskazavši im počasti.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 1, 12, 'Tada se Nabukodonozor užasno razbjesni protiv svih tih područja i zakle se svojim prijestoljem i svojim kraljevstvom da će im se osvetiti i mačem opustošiti sve pokrajine Cilicije, Damaska, Sirije, uništiti sve stanovnike koji življahu na području Moaba, plemena Amona, čitave Judeje i sve žitelje Egipta sve do obaju mora.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 1, 13, 'Godine sedamnaeste stade sa svojom vojskom protiv kralja Arfaksada, potuče ga u borbi, rasprši mu svu vojsku, konjaništvo i kola,');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 1, 14, 'zagospodari njegovim gradovima, doprije do Ekbatane, zauze kule, opljačka trgovišta, svede sjaj njegov na sprdnju.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 1, 15, 'Arfaksada uhvati u planinama Ragaua, dade ga izbosti sulicama i tako ga se riješi zauvijek.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 1, 16, 'Vrati se tada u Ninivu sa svom svojom vojskom i s golemim mnoštvom ratnika što im se bijahu pridružili. Tu se u miru i spokojstvu on i njegova vojska predadoše besposlici i uživanju stotinu i dvadeset dana.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 2, 1, 'Godine osamnaeste, prvoga mjeseca, dana dvadeset i drugoga, u kraljevskoj palači Nabukodonozora, kralja asirskoga, smisliše tajnu osnovu o izvršenju osvete nad svakom pokrajinom, kako on već bijaše kazao.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 2, 2, 'Sazva sve svoje pomoćnike i sve svoje dostojanstvenike i saopći im svoju tajnu osnovu i svojim usnama odluči potpuno uništenje onih pokrajina.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 2, 3, 'I bi odlučeno da se unište posvema svi oni koji se ne bijahu pokorili naredbi njegovih usta.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 2, 4, 'Zatim, kako završi vijećanje, Nabukodonozor, kralj Asiraca, dozva k sebi Holoferna, vrhovnog zapovjednika sve vojske, drugoga po redu iza sebe, i kaza mu:');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 2, 5, '\"Ovako govori veliki kralj, gospodar sve zemlje: otići ćeš od mene i povest ćeš sa sobom ljude svjesne svoje snage, otprilike stotinu i dvadeset tisuća pješaka i mnoštvo od dvanaest tisuća konja i konjanika.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 2, 6, 'Poći ćeš protiv sve zemlje na zapadu, jer se ne odazva nalogu mojih usta.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 2, 7, 'Naredit ćeš im da pripreme zemlju i vodu, jer ću u svome bijesu nasrnuti na njih. Prekrit ću svu zemlju nogama svojih vojnika i pustit ću da je temeljito opljačkaju.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 2, 8, 'Njihovi će ranjenici ispuniti doline; svaki potok i rijeka razlit će se nabujavši od njihovih mrtvih tijela.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 2, 9, 'Otjerat ću ih kao prognanike do nakraj svijeta.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 2, 10, 'Ti dakle kreni pa mi zauzmi sve njihovo područje. Ako ti se predaju, ti ćeš mi ih sačuvati za dan njihove kazne.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 2, 11, 'Neka tvoje oko ne zna milosti prema odmetnicima, nego kamo god dođeš, podvrgni ih smrti i pljački u svoj zemlji koja ti je povjerena.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 2, 12, 'Kazah i svojom ću rukom izvesti, kunem se životom i snagom svoga kraljevstva.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 2, 13, 'Ti nemoj prekršiti ni jedne od zapovijedi svoga gospodara, nego izvrši doslovce sve ono što sam ti naredio i nemoj oklijevati da to provedeš.\"');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 2, 14, 'Holoferno ode od svoga gospodara i sakupi sve vrhovne zapovjednike, vojskovođe i časnike vojske asirske,');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 2, 15, 'prebroja ljude koje izabra za bojni raspored kao što je naredio gospodar njegov: stotinu dvadeset tisuća ljudi i dvanaest tisuća strijelaca na konjima');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 2, 16, 'i svrsta ih kako se svrstavaju bojni redovi velika mnoštva.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 2, 17, 'Uze silan broj deva, magaraca i mazgi za prijenos njihove opreme, a tako i velik broj ovaca, volova i koza njima za opskrbu');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 2, 18, 'i za hranu svakog pojedinog vojnika te napokon golemu količinu zlata i srebra iz kraljeva dvora.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 2, 19, 'Krenu sa svom vojskom da bi kao prethodnica Nabukodonozorova prekrio sve lice zemlje na zapadu kolima, konjanicima i izabranim pješacima.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 2, 20, 'Silno, izmiješano mnoštvo, kao skakavci ili kopneni pijesak nebrojeni, iđaše za njim.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 2, 21, 'Krenuše iz Ninive i nakon tri dana hoda stigoše do ravnice Bektileta, pa se utaboriše za Bektiletom, blizu planine koja se nalazi nalijevo od Gornje Cilicije.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 2, 22, 'Holoferno pokrenu svu vojsku, pješake, konjanike i kola, pa se odande uputi prema planinskim predjelima.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 2, 23, 'Razori Fud i Lud, orobi sve Rasisove sinove i sinove Izmaelove koji borave sučelice pustinji, južno od zemlje heleonske.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 2, 24, 'Prijeđe Eufrat, prođe kroz Mezopotamiju, razori sve gradove koji se nalaze na uzvisinama uzduž potoka Abrona, da bi izbio na more.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 2, 25, 'Zauze područje Cilicije, isječe na komade sve one koji mu se opirahu i stiže do međa Jafata na jug, nasuprot Arabiji.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 2, 26, 'Opkoli sve sinove Madijanove, zapali im šatore, ugrabi stada.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 2, 27, 'Za žetve žita siđe u nizinu Damaska, zapali im sve njive, uništi im stada i stoku, opljačka im gradove, opustoši polja i oštricom mača pobi sve mlado.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 2, 28, 'Tada spopade strah i užas sve stanovnike obala Sidona i Tira, žitelje Sura i Okine i sve žitelje Jamnije. I građane koji su živjeli u Azotu i Askalonu zahvati silan strah pred njim.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 3, 1, 'Poslaše mu zbog toga glasnike s miroljubivim prijedlozima i poručiše:');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 3, 2, '\"Evo, mi podanici velikoga kralja Nabukodonozora padamo ničice preda te: učini s nama što ti se prohtije.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 3, 3, 'Evo ti naših kuća, našega kraja, žitnih polja, stada, stoke: svi torovi naših šatora ovise samo o jednom tvome migu; služi se svime kako ti se ushtije i kako ti se svidi.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 3, 4, 'Evo, i naši su gradovi sa svojim stanovnicima robovi tvoji, samo dođi i učini s njima što je dobro u očima tvojim.\"');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 3, 5, 'Ljudi dođoše do Holoferna i saopćiše mu te poruke.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 3, 6, 'On siđe s vojskom prema obali, postavi upravitelje po utvrđenim gradovima te iz tih gradova unovači posebno izabrane ljude kao pomoćnu vojnicu.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 3, 7, 'Građani i sav okoliš dočekaše ga s vijencima, plesovima i bubnjevima.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 3, 8, 'Poruši on sve njihove uzvišice, sravni sa zemljom svete gajeve njihove: bilo mu je najvelikodušnije dopušteno da razruši sva domaća božanstva kako bi svi narodi častili samo Nabukodonozora i svi ga jezici i plemena zazivali kao Boga.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 3, 9, 'Stiže tako nasuprot Ezdrelonu u blizini Dotaina, a to je sučelice velikoj judejskoj ravni. Utabori se između Gebe i Skitopolisa i tu se zadrža cio mjesec dana da sakupi opskrbu za svoju vojsku.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 3, 10, '');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 4, 1, 'Sinovi Izraelovi koji življahu u Judeji dočuše što je Holoferno, vrhovni zapovjednik Nabukodonozora, kralja Asiraca, učinio drugim narodima i kako je opljačkao i razorio hramove njihove;');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 4, 2, 'obuze ih neiskaziv strah od toga čovjeka i počeše strepiti zbog Jeruzalema i zbog Hrama Gospoda, Boga svoga.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 4, 3, 'Bjehu se tek vratili iz sužanjstva, sav narod Judeje bio se sabrao tek nedavno, i predmeti, žrtvenik i Hram bili su posvećeni poslije obeščašćenja.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 4, 4, 'Odaslaše zbog toga glasnike na područje Samarije, u Konu, Betoron, Belmajin, Jerihon, u Hobu, u Esoru i u Salemsku dolinu.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 4, 5, 'Prije svega zaposjedoše sve vrhove najviših brda, opasaše zidovima sela koja su se nalazila ondje i nagomilaše hranu i opremu za vođenje rata, jer polja njihova bijahu istom požeta.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 4, 6, 'Tada Joakim, veliki svećenik, koji se tih dana nalazio u Jeruzalemu, napisa stanovnicima Betulije i Betomestaima, koji je smješten nasuprot Ezdrelonu na ulazu u ravan blizu Dotaina,');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 4, 7, 'i naredi da se zaposjednu brdski prijelazi, jer je preko njih vodio put u Judeju. A bilo je lako spriječiti neprijateljski upad, jer je klanac bio tako uzak da su samo dva čovjeka mogla odjednom proći.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 4, 8, 'Sinovi Izraelovi učiniše kako im je naložio Joakim, veliki svećenik, i starješine narodne koje življahu u Jeruzalemu.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 4, 9, 'Svaki Izraelac žarko podiže glas k Bogu i svi se poniziše pred Bogom:');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 4, 10, 'oni i žene njihove, i djeca, i životinje, i pridošlice, i plaćenici i robovi nošahu kostrijet oko bokova.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 4, 11, 'Svi Izraelci i žene i djeca što življahu u Jeruzalemu padoše ničice pred Hramom, posuše glavu pepelom i prostriješe kostrijet pred Gospoda:');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 4, 12, 'opasaše vrećama i žrtvenik i zazivahu žarko Boga Izraelova u jedan glas, da ne preda njihovu djecu pokolju, njihove žene u ropstvo, njihove gradove i baštinu njihovu rušenju a svetišta njihova obeščašćenju, pogrdi i ruglu pogana.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 4, 13, 'Bog usliša glas njihov i smilova se nad nevoljom njihovom: sav je narod postio mnogo dana u svoj Judeji i u Jeruzalemu pred Svetištem Boga Svevladara.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 4, 14, 'Veliki svećenik Joakim, svećenici koji su stajali pred Gospodom i svi oni koji su mu služili, vezavši kostrijet oko bokova, prinosili su svakidašnje žrtve paljenice, zavjetnice i dragovoljne prinose puka;');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 4, 15, 'posuvši pepelom mitre, podizahu iz sve snage glas Gospodu da bi milostivo pogledao dom Izraelov.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 5, 1, 'Izvijestiše Holoferna, vrhovnog zapovjednika vojske asirske, da su se sinovi Izraelovi spremili za rat, da su zatvorili brdske prijelaze, utvrdili sve vrhove najviših planina te postavili prepreke u predjelima što se nalaze u ravnici.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 5, 2, 'On se rasrdi strahovito, sazva sve glavare moapske, vojskovođe amonske, sve primorske namjesnike');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 5, 3, 'pa im kaza: \"Recite mi, sinovi kanaanski: kakav je to narod koji nastava brdovite predjele? Kakvi su mu gradovi u kojima živi? Kolika je vojska njegova? U čemu je snaga njegova i moć njegova? Tko je kralj koji nad njima vlada i zapovijeda im vojskom?');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 5, 4, 'Zašto je među svima koji žive na zapadu on jedini gnjevno odbio da mi miroljubivo dođe u susret?\"');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 5, 5, 'Odgovori mu Ahior, vođa svih sinova Amonovih: \"Poslušaj, moj gospodaru, riječi iz usta sluge svoga: ja ću te obavijestiti istinito o tome narodu koji, smješten blizu tebe, nastava taj brdovit kraj; neće izaći laž iz usta sluge tvoga.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 5, 6, 'Narod taj potječe od Kaldejaca.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 5, 7, 'Najprije su boravili u Mezopotamiji, jer su otklonili da se drže bogova otaca svojih koji su živjeli u zemlji kaldejskoj.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 5, 8, 'Skrenuše dakle s puta otaca svojih pa počeše štovati Boga nebeskoga, onoga Boga koga bijahu spoznali. I zato, udaljeni od lica svojih bogova, skloniše se u Mezopotamiju i tu se dugo zadržaše.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 5, 9, 'Pa im Bog njihov zapovjedi da ostave to prebivalište i odu u zemlju Kanaan; naseliše se ondje te imađahu u obilju zlata i srebra i mnogo stoke.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 5, 10, 'Spustiše se poslije u Egipat, jer glad bijaše pritisla zemlju kanaansku; ondje su ostali dok se imahu čime hraniti. Porastoše u snažno mnoštvo; rodu njihovu ne bijaše broja.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 5, 11, 'Ali se kralj Egipta diže na njih, naruga im se u pravljenju opeke; ponizi ih i učini robovima.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 5, 12, 'Onda oni zavapiše Bogu svome, a on svu zemlju egipatsku udari ranama bez prebola. Zbog toga ih Egipćani otjeraše od sebe.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 5, 13, 'Bog pred njima isuši Crveno more');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 5, 14, 'i prevede ih preko Sinaja i Kadeš Barne. Oni odbiše od sebe sve nasrtaje stanovnika pustinje,');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 5, 15, 'smjestiše se na području Amorejaca i vlastitom snagom istrijebiše sve Hešbonce. Prijeđoše preko Jordana i dobiše u nasljedstvo sav planinski kraj;');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 5, 16, 'istjeraše Kanaanca, Perižanina, Jebusejca, Sihemca i sve Girgašane i tu obitavahu mnogo vremena.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 5, 17, 'Dok ne sagriješiše protiv Boga svoga, pratilo ih je blagostanje, jer je bio s njima Bog komu je mrska nepravda;');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 5, 18, 'ali kad se udaljiše od puta što im ga on bijaše naznačio, u mnogim ratovima pretrpješe užasna razaranja, zatočiše ih u zemlju koja nije bila njihova. Hram Boga njihova bi razoren do temelja, a gradove im oteše neprijatelji njihovi.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 5, 19, 'Ali sada, kako su se vratili Bogu svome, uspeše se iz raznih krajeva kamo bijahu raspršeni i ponovo zauzeše Jeruzalem, gdje se nalazi Svetište njihovo, i smjestiše se po brdovitim krajevima koji bijahu opustjeli.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 5, 20, 'Zato, gospodaru, pomno izvidimo je li taj narod u čemu zastranio, je li sagriješio Bogu svome, pa ako utvrdimo da jest, onda možemo krenuti na nj i pokoriti ga;');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 5, 21, 'ali ako narod onaj nije kriv ni zbog kakva prijestupa, onda neka gospodar moj odustane od nauma: jer će ih Bog njihov štititi, a mi ćemo biti na ruglo svoj zemlji.\"');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 5, 22, 'Kada Ahior završi tu besjedu, stadoše rogoboriti oni koji su okruživali šator i nalazili se unaokolo, dostojanstvenici Holofernovi, svi stanovnici obalnih krajeva i Moaba: tražili su da ga raskomadaju:');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 5, 23, '\"Ne bojmo se sinova Izraelovih! To je zaista narod koji nema ni moći ni snage za žešću bitku.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 5, 24, 'Krenimo, dakle! Oni će biti samo zalogaj za vojsku tvoju, gospodaru Holoferno!\"');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 6, 1, 'Pošto je utihnula buka onih koji su se skupili na vijećanje, Holoferno, vrhovni zapovjednik asirske vojske, u nazočnosti svega naroda različita podrijetla i sviju sinova moapskih, obrati se Ahioru:');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 6, 2, '\"Tko si ti, Ahiore, ti i plaćenici Efrajimovi, da danas ovako prorokuješ među nama i savjetuješ da odustanemo od borbe protiv roda Izraelova? Bog njihov da bi im bio štit? Ali tko je Bog, osim Nabukodonozora? On će poslati svoju snagu i zbrisati ih s lica zemlje; ni Bog ih njihov neće spasiti.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 6, 3, 'Mi, sluge kraljeve, mi ćemo ih smrviti kao jednog čovjeka. Neće izdržati žestine našega konjaništva.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 6, 4, 'Njime ćemo ih zdrobiti. Brda će se natopiti njihovom krvlju, a ravnice se ispuniti njihovim mrtvim tijelima. Neće se ni održati pred nama, svi će izginuti. Tako govori kralj Nabukodonozor, gospodar sve zemlje. Tako je rekao, a riječi njegove neće ostati neispunjene.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 6, 5, 'A ti, Ahiore, plaćeniče amonski, koji si tako govorio u dan izopačenosti svoje, nećeš više gledati moga lica od današnjeg dana pa sve dok se ne osvetim rodu tih bjegunaca iz Egipta.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 6, 6, 'Tada će gvožđe mojih vojnika i sulica mojih slugu probosti slabine tvoje i ti ćeš pasti među ranjenike Izraela kad se ja okrenem protiv njega.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 6, 7, 'Za sada neka te sluge moje odvedu u brdoviti kraj i ostave u jednome od prilaznih gradova:');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 6, 8, 'nećeš poginuti dok ne budeš zatrt s njima.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 6, 9, 'Ako u srcu svome gajiš nadu da neće biti osvojeni, zašto onda tvoje lice pokazuje toliku utučenost? Rekoh: nijedna od riječi mojih neće ostati neispunjena.\"');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 6, 10, 'Holoferno potom naredi slugama koji bijahu u šatoru njegovu da zgrabe Ahiora, odvedu u Betuliju i predaju u ruke sinova Izraelovih.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 6, 11, 'Njegove ga sluge uhvatiše, odvedoše izvan tabora prema ravnici, iz ravnice provedoše ga prema brdima i dovedoše na izvore koji se nalaze pod Betulijom.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 6, 12, 'Kad su ih ljudi iz grada opazili, dohvatiše oružje, iziđoše iz grada prema vrhu brda, a praćari zauzeše put što se tuda uspinje i počeše bacati kamenice na njih da im spriječe penjanje.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 6, 13, 'Oni se onda skloniše pod brdo, svezaše Ahiora i ostaviše ga na podnožju brda, pa se vratiše svome gospodaru.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 6, 14, 'Sišavši iz svoga grada, sinovi Izraelovi priđoše mu, odvezaše ga i odvedoše u Betuliju i dovedoše pred gradske glavare.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 6, 15, 'Tih dana vršili su tu dužnost Ozija, sin Mihin od plemena Šimunova, pak Kabris, sin Gotonielov, i Harmis, sin Melkielov.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 6, 16, 'Dozvaše gradske starješine, ali dođoše na zbor i svi mladići i žene. Postaviše Ahiora usred svega naroda, a Ozija ga uzme ispitivati što to bijaše s njim.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 6, 17, 'Ahior ih izvijesti o svemu što je rečeno na Holofernovu vijećanju: što je sam kazao vođama Asurovim i što je u nadutosti svojoj Holoferno govorio protiv doma Izraelova.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 6, 18, 'Tada narod pade ničice, iskaza štovanje Bogu svome i zavapi:');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 6, 19, '\"Gospode, Bože nebeski, pogledaj oholost njihovu, budi milostiv poniznosti roda našega i obazri se danas na lica sebi posvećenih!\"');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 6, 20, 'Potom utješiše Ahiora i pohvališe ga.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 6, 21, 'Ozija ga sa zbora odvede u dom svoj i priredi starješinama gozbu. Svu noć dozivahu u pomoć Boga Izraelova.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 7, 1, 'Sutradan zapovjedi Holoferno svoj vojsci svojoj i svim narodima koji mu se bijahu pridružili u savezništvo da krenu na Betuliju, da zaposjednu putove što vode u brda i da zametnu rat protiv sinova Izraelovih.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 7, 2, 'Toga istog dana krenuše svi njihovi ratnici. Vojska se tih bojovnika sastojala od stotinu i sedamdeset tisuća pješaka i dvanaest tisuća konjanika, ne brojeći opremu i golemo mnoštvo ljudi koji su išli pješke među njima.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 7, 3, 'Utaboriše se u dolini nadomak Betuliji, uz izvor; zauzeše prostor u širinu od Dotaina do Belbaima, a u dužinu od Betulije do Kimona, koji se nalazi sučelice Ezdrelonu.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 7, 4, 'Kada sinovi Izraelovi vidješe sve to mnoštvo, u strahu počeše govoriti među sobom: \"Ovi će potamaniti sve na zemlji! Ni najviše planine, ni klanci, ni bregovi neće izdržati pod njihovom težinom.\"');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 7, 5, 'Svaki pograbi oružje; upalivši luči na svojim kulama, ostadoše na straži svu onu noć.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 7, 6, 'Ujutro izvede Holoferno sve konjaništvo pred oči sinova Izraelovih koji su se nalazili u Betuliji;');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 7, 7, 'podvrže budnu nadzoru sve uspone koji su vodili do grada njihova, pretraži sve izvore vode i zauze ih i tu postavi vojničke straže pa se onda vrati k vojsci svojoj.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 7, 8, 'Dođoše k njemu svi poglavari sinova Ezavovih, sve vođe naroda moapskoga i vojskovođe obalnih krajeva te rekoše:');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 7, 9, '\"Neka posluša naš gospodar nekoliko naših riječi da ne bi pretrpio poraz vojske svoje.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 7, 10, 'Taj se narod sinova Izraelovih nije nikada uzdavao u svoja koplja nego u planinske uzvisine po kojima živi, jer nije se lako popeti na vrhove njihovih brda.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 7, 11, 'Zato se nemoj, gospodaru, boriti s njima kako se bori u otvorenoj bitki, pa neće poginuti ni jedan čovjek koji pripada tvome narodu.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 7, 12, 'Ostani u svome taboru čuvajući brižno svakoga svog vojnika. A dotle neka se tvoje sluge domognu vrela koje izvire na obronku.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 7, 13, 'Iz njega doista uzimaju vodu svi stanovnici Betulije. Žeđa će ih skončati i oni će predati grad. Mi ćemo se onda sa svojim četama popeti na obližnje gorske uzvisine pa na njima postaviti stražu da ni jedan čovjek ne izađe iz grada.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 7, 14, 'Glad će umoriti njih i njihove žene i njihovu djecu, pa još prije nego ih sasiječemo mačem, ležat će onemoćali po trgovima boravišta svoga.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 7, 15, 'Tada ćeš im groznom odmazdom platiti što se pobuniše i ne iziđoše ti s mirom u susret.\"');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 7, 16, 'Razlaganje njihovo svidje se Holofernu i svim njegovim vojvodama. Izda on zapovijed da učine kako su ga svjetovali.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 7, 17, 'Krenu dakle odjel sinova Amonovih sa pet tisuća Asiraca pa se utabori u podolju, zauzevši nakapnice i izvore voda sinova Izraelovih.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 7, 18, 'Prema uzvisinama krenuše sinovi Ezavovi i sinovi Amonovi pa stadoše u brdovitu kraju nasuprot Dotainu, odakle poslaše jedan dio prema jugoistoku, sučelice Egrebelu, koji se nalazi blizu Kusa na obali potoka Mohmura. Ostali dio asirske vojske utabori se na ravnici pa prekri sve lice zemlje; šatori i silna oprema protezali im se u gustim nizovima tvoreći golemo mnoštvo.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 7, 19, 'Sinovi Izraelovi podigoše glas Gospodu Bogu svome, jer se obeshrabrio duh njihov zbog toga što bijahu opkoljeni od sviju neprijatelja svojih tako da im ne mogahu izmaći.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 7, 20, 'Trideset se i četiri dana nalazila oko njih asirska sila: pješaci, vojnička kola, konjanici. A onda stanovnicima Betulije nestade vode u sudovima,');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 7, 21, 'a nakapnice im bijahu prazne; ni jedan dan nisu imali dovoljno pitke vode jer im se voda za piće davala na mjeru.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 7, 22, 'Djeca im bijahu iznemogla, žene im i mladići padali u nesvijest od žeđe: ležali su po gradskim trgovima ili u kućama, nisu više imali snage.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 7, 23, 'Tada sav narod, mladići, žene i djeca odoše k Oziji i gradskim upravljačima i povikaše i rekoše pred svim starješinama:');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 7, 24, '\"Neka Bog sudi između vas i nas zbog velike nepravde koju ste počinili na štetu našu jer niste htjeli mirno pregovarati s Asircima.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 7, 25, 'Sad nam nema više pomoći niodakle: Bog nas je predao u njihove ruke da iznemognemo od žeđe i posvemašnje iscrpljenosti.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 7, 26, 'A sada ih pozovite i predajte sav grad pljački Holofernovih ljudi i sve vojske njegove.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 7, 27, 'Jer nam je bolje da postanemo njihov plijen. Bit ćemo, doduše, njihovi robovi, ali ćemo sačuvati živote i nećemo rođenim očima gledati smrt djece svoje niti kako nam žene i djeca ispuštaju dušu.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 7, 28, 'U ime neba i zemlje, u ime Boga i Gospoda otaca naših, koji nas je kaznio zbog grijeha naših i poradi prijestupa otaca naših, zaklinjemo vas da još danas izvršite što smo vam kazali.\"');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 7, 29, 'Usred zbora nasta sveopći plač i svi glasno zavapiše Gospodu Bogu.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 7, 30, 'Ozija im upravi riječ: \"Budite hrabri, braćo, ustrajmo još pet dana, za kojih će Gospod Bog naš izliti na nas milost svoju: zacijelo nas neće napustiti zauvijek.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 7, 31, 'Prođe li tih pet dana bez ikakve pomoći, izvršit ću što tražite.\"');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 7, 32, 'Potom otpusti narod, svakoga u njegovu četvrt. Ljudi odoše na zidove i kule svoga grada, a žene i djecu poslaše njihovim kućama. Ali u gradu bijahu krajnje potišteni.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 8, 1, 'Tih dana sve je to čula Judita, kći Merarija, sina Oksa, sina Oziela, sina Elkija, sina Ananije, sina Gedeona, sina Rafaina, sina Ahitoba, sina Elije, sina Helkije, sina Eliaba, sina Natanaela, sina Salamiela, sina Sarasadaja, sina Izraelova.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 8, 2, 'Njezin muž Manaše, iz istoga plemena i obitelji, bješe umro za žetve ječma.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 8, 3, 'Nadgledavao je one koji su povezivali snopove na njivi kad ga pogodi sunčanica: pade na postelju i umrije u Betuliji, gradu svome; pokopaše ga do njegovih otaca u polju što se nalazi na pola puta između Dotaina i Balamona.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 8, 4, 'Judita odonda življaše kao udovica već tri godine i četiri mjeseca.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 8, 5, 'Načinila je sebi sobu na ravnome kućnom krovu, navukla preko bokova kostrijet i nosila haljine udovičke.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 8, 6, 'Postila je sve dane udovištva svoga, osim uoči subote i za samih subota, uoči mlađaka i za samih mlađaka te za svetkovina i blagdana doma Izraelova.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 8, 7, 'Bila je lijepa i naočita. Njezin muž Manaše bijaše joj ostavio zlata i srebra, slugu i sluškinja, stoke i zemljišta, i tako je živjela.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 8, 8, 'Ne bijaše nikoga koji bi kazao što ružno o njoj, jer je bila jako bogobojazna.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 8, 9, 'Dočula je dakle krute riječi koje puk, zapavši u malodušje zato što je nestalo vode, bijaše upravio gradskom starješini, a doznala je i sve što je Ozija rekao narodu i kako im se zakleo da će do pet dana predati grad Asircima.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 8, 10, 'Posla tada sluškinju koja je vodila njezine poslove da dozove gradske starješine Habrisa i Harmisa.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 8, 11, 'Dođoše oni k njoj, a ona im kaza: \"Poslušajte me, glavari Betulije! Nije baš valjan govor što ste ga održali puku. A umetnuli ste u taj govor i zakletvu između Boga i vas i rekli da ćete predati grad neprijatelju ako vam Gospod u određenom roku ne pomogne.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 8, 12, 'A tko ste vi da danas iskušavate Boga i postavljate se iznad Boga među ljudima?');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 8, 13, 'Ispitujte namisli Boga Svevladara koliko vam drago, pa svejednako nećete razumjeti ništa dovijeka.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 8, 14, 'Ako ne uspijevate istražiti dubine ljudskoga srce niti doznati ono što prolazi ljudskom mišlju, kako ćete dokučiti Boga koji je stvorio sve to? Kako ćete istražiti misao njegovu i shvatiti nakane njegove? Ne, braćo, nemojte ljutiti Gospoda Boga našega!');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 8, 15, 'Jer ako nam i ne htjedne priskočiti u pomoć u ovih pet dana, ipak nas može zaštititi ali i zatrti, i to naočigled neprijatelja naših, u one dane kad mu se svidi.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 8, 16, 'Prema tome, ne tražite odluke Gospoda Boga našega, jer Bog nije čovjek da biste mu mogli prijetiti niti sin čovječji komu biste mogli naređivati.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 8, 17, 'Zbog toga, očekujući spas koji može doći od njega, dozivajmo ga u pomoć, i on će poslušati glas naš, bude li mu to drago.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 8, 18, 'Jer u našim pokoljenjima nije bilo, a nema ni dan-danas u našemu plemenu, obitelji, selu ili gradu onih koji bi štovali boštva načinjena rukama, kao što je bivalo u prijašnja vremena.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 8, 19, 'Zato su očevi naši bili predani maču, bili su pljačkani i doživjeli velike poraze od neprijatelja.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 8, 20, 'Ali mi ne znamo drugoga Boga do njega, pa se stoga nadamo da neće napustiti ni nas ni ikoga od našeg plemena.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 8, 21, 'Jer budemo li osvojeni mi, bit će osvojena i sva Judeja i opljačkano naše Svetište, a on će to obeščašćenje osvetiti našom krvlju.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 8, 22, 'Pokolj braće naše, tjeranje svega naroda u progonstvo i opustošenje baštine naše oborit će na glavu našu među poganima među kojima ćemo se nalaziti kao robovi i biti predmet pogrde i ismjehivanja za naše gospodare,');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 8, 23, 'jer se naše ropstvo neće pretvoriti u naklonost nego će ga Gospod Bog naš pretvoriti u porugu.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 8, 24, 'Stoga, braćo, pokažimo svojoj braći da od nas zavisi život njihov te da Svetište, Hram i žrtvenik počivaju na nama.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 8, 25, 'Zbog svega toga zahvalimo radije Gospodu Bogu našemu što nas iskušava kao što je iskušavao i očeve naše.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 8, 26, 'Sjetite se kako je činio s Abrahamom, kako je iskušavao Izaka, što se dogodilo Jakovu u Mezopotamiji sirijskoj kad je pasao ovce Labana, svoga ujaka.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 8, 27, 'Jer kako je iskušavao njih da bi iskušao njihova srca, tako postupa s nama da se popravimo, a ne da nam se osveti, jer Bog iskušava one koji su mu blizu.\"');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 8, 28, 'Ozija joj odgovori: \"Sve što si izrekla iznosila si iz plemenitog srca i nitko se neće usprotiviti tvojim riječima.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 8, 29, 'Jer tvoja se mudrost ne očitova tek danas: još od početka tvojih dana sav je narod znao za tvoju umnost, za plemenitost srca tvoga!');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 8, 30, 'Ali puk trpi užasno od žeđe, pa nas je prisilio da izvršimo ono što smo obećali i da se zakunemo zakletvom koje nećemo prekršiti.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 8, 31, 'Sada, budući da si ti pobožna žena, moli se za nas, a Gospod će poslati kišu i napuniti naše čatrnje da ne izginemo.\"');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 8, 32, 'Odgovori im Judita: \"Poslušajte me! Izvest ću djelo o kojemu će spomen prelaziti od pokoljenja na pokoljenje među sinovima našeg naroda.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 8, 33, 'Budite noćas na gradskim vratima da mognem izići sa svojom sluškinjom. Prije onog dana u koji ste namislili predati grad neprijateljima Gospod će rukom mojom donijeti spas Izraelu.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 8, 34, 'Ne tražite da vam kažem što sam namjerila. Neću vam odati ništa dok ne bude izvršeno ono što sam odlučila učiniti.\"');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 8, 35, 'Ozija i prvaci rekoše joj: \"Idi u miru! Neka Gospod Bog bude uza te da se uzmogneš osvetiti neprijateljima našim!\"');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 8, 36, 'Izišavši odande, vratiše se na svoja mjesta.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 9, 1, 'Tada Judita pade ničice, posu glavu pepelom i razotkri kostrijet koju je nosila na sebi. I upravo kad su u Jeruzalemu, u Domu Božjem, prinosili večernji tamjan, ona glasno zavapi Gospodu i reče:');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 9, 2, '\"O Gospode, Bože oca moga Šimuna, komu si ruku naoružao mačem da se osveti tuđincima koji bijahu radi sramote odriješili pas jedne djevice, obnažili njezin bok da je okaljaju i obeščastili njezinu utrobu za sramotu. Iako si kazao: \'Ne smije tako biti\', oni su svejedno učinili.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 9, 3, 'I zato si predao pokolju vođe njihove i krvi postelju njihovu, prevarenu i postiđenu njihovom prijevarom. Udario si po robovima i gospodarima; po vladarima na prijestoljima njihovim.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 9, 4, 'Predao si žene njihove plijenu, a kćeri njihove, svu imovinu njihovu odredio da bude razdijeljena među tvoje ljubljene sinove koji su gorjeli od revnosti prema tebi, užasavali se nad obeščašćenjem svoje krvi i zvali te u pomoć. O Bože, moj Bože, poslušaj i mene udovicu.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 9, 5, 'Ti si sazdao i ono što je bilo prije i što će biti poslije. Ti si zamislio i sadašnjost i budućnost i sve se dogodilo što si umom zasnovao.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 9, 6, 'Što si nakanio, došlo je preda te i reklo: \'Evo me!\' Jer svi su tvoji putovi pripremljeni, a tvoje odluke predviđene.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 9, 7, 'Eto, Asirci se uznose svojom vojskom, ponositi su na konje i konjanike svoje, oholi su zbog vrsnoće pješaka svojih, uzdaju se u štit, koplje, luk, praćku i neće da u tebi spoznaju Gospoda koji mrvi ratove.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 9, 8, 'Gospod je tvoje ime. Ti im skrši snagu moći svojom, savij silu gnjevom svojim. Jer su naumili da obeščaste tvoje Svetište, da okaljaju Šator gdje boravi preslavno Ime tvoje, da željezom raznesu uglove žrtvenika tvoga.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 9, 9, 'Vidi njihovu nadutost i upravi gnjev svoj na glave njihove, a moju udovičku ruku ojačaj za naumljeno djelo.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 9, 10, 'Pogodi zamamnošću mojih usana roba s vođom, a vođu s njegovim slugom. Razori drzovitost njihovu rukom jedne žene.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 9, 11, 'Tvoja snaga nije u mnoštvu niti moć tvoja u silnicima, nego si ti Bog poniznih, pomoćnik si malenih, potporanj slabih, utočište napuštenih, spasitelj očajnih.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 9, 12, 'Doista, Bože oca moga, Bože baštine Izraelove, gospodaru neba i zemlje, tvorče voda, kralju svega stvorenja, uslišaj molitvu moju!');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 9, 13, 'Daj mi zamamnu riječ koja ranjava i obara u krvi one koji su strahote smislili protiv tvoga Saveza, svetog Doma, brda Siona i kuće sinova tvojih.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 9, 14, 'Učini da spozna sav narod tvoj i svako pleme da si ti Bog, Bog svake moći i snage, i da osim tebe nema drugoga zaštitnika rodu Izraelovu!\"');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 10, 1, 'Kad je prestala vapiti Bogu Izraelovu i kad je završila svoju molitvu,');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 10, 2, 'ustade gdje bijaše pala ničice, dozva svoju sluškinju i siđe u odaje u kojima je provodila subote i svetkovine svoje.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 10, 3, 'Svuče sa sebe kostrijet, skide udovičke haljine, opra vodom tijelo, namaza se mirisavom mašću, počešlja kosu i stavi prevjes na glavu, odjenu se u svečane haljine u koje se odijevala dok je još živio muž njezin Manaše.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 10, 4, 'Obu sandale, metnu narukvice, ogrlice, prstenje, naušnice i sav nakit: uresi se što je mogla ljepše da bi očarala oči ljudi koji je budu gledali.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 10, 5, 'Sluškinji preda mijeh vina i vrč ulja, napuni dvojače ječmenom kašom, pogačama suhoga voća i čistim hljebovima; sve to složi i stavi na nju.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 10, 6, 'Uputiše se njih dvije prema vratima grada Betulije i tu nađoše Oziju s gradskim starješinama Habrisom i Harmisom.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 10, 7, 'Kad ovi ugledaše Juditu preobražena lica i u onome ruhu, zadiviše se ljepoti njezinoj pa će joj:');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 10, 8, '\"Bog otaca naših udijelio ti milost i dao ti da uspješno izvedeš što si naumila na slavu sinova Izraelovih i uzvišenje Jeruzalema.\"');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 10, 9, 'Judita se pokloni Bogu, a njima reče: \"Zapovjedite da mi otvore gradska vrata. Izići ću i izvesti što ste kazali.\" Oni narediše straži da otvori vrata kako je zatražila.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 10, 10, 'Otvoriše joj, pa Judita iziđe sa sluškinjom. Ljudi su je iz grada pratili pogledom dok se spuštala brdom i dok je poprijeko prelazila podoljem. Onda je više nisu vidjeli.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 10, 11, 'Dok su išle ravno podoljem, sretoše je asirske predstraže.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 10, 12, 'Zaustaviše je i upitaše: \"Kojemu narodu pripadaš? Odakle dolaziš i kamo ideš?\" Ona odgovori: \"Kći sam Hebrejaca i bježim od njih, jer će vam se uskoro predati da vam budu hrana.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 10, 13, 'Zaputila sam se Holofernu, vrhovnom zapovjedniku vaše vojske, da se s njim iskreno porazgovorim. Pokazat ću mu put kojim će morati poći da bi zagospodario svim brdovitim krajem a da ne izgubi ni jednog čovjeka, ni jedne žive duše.\"');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 10, 14, 'Dok su ti ljudi slušali riječi njezine i promatrali je, bijahu zadivljeni njezinom ljepotom. Rekoše joj:');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 10, 15, '\"Spasila si svoj život požurivši se da siđeš k našem gospodaru. Sada idi njegovu šatoru: nas nekolicina pratit ćemo te dok te ne predamo u ruke njegove.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 10, 16, 'Kada se budeš našla pred njim, ne drhti u srcu svome nego mu reci ono što si kazala i on će s tobom postupati dobro.\"');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 10, 17, 'Izabraše između sebe stotinu ljudi. Oni su bili pratnja njoj i sluškinji njezinoj, pa ih dovedoše do Holofernova šatora.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 10, 18, 'U taboru se sve uskomešalo: vijest o Juditinu dolasku pođe od usta do usta po svim šatorima. Dođoše ljudi i poredaše se do nje dok je ona stajala pred Holofernovim šatorom i dok mu se njezin dolazak najavljivao.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 10, 19, 'Divljahu se ljepoti njezinoj i sinovima Izraelovim zbog nje. I govorahu jedan drugome: \"Tko može prezreti narod koji ima takve žene? Zacijelo ne bi valjalo ostaviti u životu i jednog čovjeka toga naroda. Kad bi ga ostavili na miru, bili bi kadri opčiniti sav svijet.\"');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 10, 20, 'Holofernove straže i dvorjanici njegovi iziđoše i uvedoše Juditu u šator.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 10, 21, 'Holoferno je počivao na ležaljci za zastorom od grimiza, zlata, smaragda i dragoga kamenja.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 10, 22, 'Izvijestiše ga o dolasku njezinu i on iziđe na šatorski ulaz: pred njim su nosili srebrne svjetiljke uljanice.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 10, 23, 'Kad se Judita nađe pred njim i njegovim dvorjanicima, svi se zadiviše ljupkosti lica njezina. Ona se pokloni padnuvši ničice. Sluge je Holofernove podigoše.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 11, 1, 'Kaza joj tada Holoferno: \"Budi hrabra, ženo! Ne plaši se u srcu svome! Jer nisam nanio zla nikome od onih koji odlučiše služiti Nabukodonozora, kralja sve zemlje.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 11, 2, 'Pa da me i tvoj narod koji živi u brdovitu kraju nije prezreo, ja ne bih digao koplja na nj. Ali su sami to skrivili.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 11, 3, 'Nego, sada mi reci zašto si pobjegla od njih a došla k nama. Došla si da se spasiš! Hrabro, život će ti biti pošteđen noćas a i poslije.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 11, 4, 'Nitko ti neće nanijeti zla, nego će se postupati s tobom kako se postupa sa slugama moga gospodara i kralja Nabukodonozora.\"');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 11, 5, 'Judita mu odgovori: \"Poslušaj riječi robinje svoje. Neka sluškinji tvojoj bude dopušteno govoriti s tobom: neću noćas govoriti laži svome gospodaru.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 11, 6, 'Budeš li slijedio savjete sluškinje svoje, Bog će ti pomoći sretno izvesti djelo tvoje, a gospodar moj neće biti razočaran sa svojih pothvata.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 11, 7, 'Neka živi Nabukodonozor, kralj sve zemlje, neka živi moć onoga koji te uputio kako bi uzmogao na pravi put izvesti svako živo biće! Pomoću tebe nisu mu doista podvrgnuti samo ljudi nego, zahvaljujući vrijednosti tvojoj, i divlje i domaće životinje i ptice nebeske: sve živi samo za Nabukodonozora i svu kuću njegovu.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 11, 8, 'Dočuli smo već i za razboritost i za oštroumnost tvoju. Svoj je zemlji znano da si u svem kraljevstvu samo ti sposoban, vrstan i pronicav u ratnom umijeću.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 11, 9, 'Doznali smo i za govor što ga je Ahior izgovorio na tvome vijećanju; budući da su ga stanovnici Betulije spasili, on im je kazao sve što je rekao pred tobom.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 11, 10, 'A sada, moćni gospodaru, nemoj potcjenjivati njegovo razlaganje nego ga pohrani u srcu svome jer je istinito: ne može se rod naš progoniti niti ga može dohvatiti mač, osim ako sagriješi Bogu svome.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 11, 11, 'Ali da moj gospodar ne bi ostao razočaran i promašio u svome pothvatu, past će na glavu njihovu smrt: tereti ih grijeh kojim su razgnjevili Boga svoga počinivši bezakonje.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 11, 12, 'Kako im je ponestalo hrane, a i vode imaju sve manje, prohtjelo im se da navale na stoku svoju i odlučiše da jedu što im je Bog zakonima zabranio.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 11, 13, 'Čak su naumili potrošiti prvine žita i desetine vina i ulja, čuvane i namijenjene svećenicima koji u Jeruzalemu služe Boga našega; a ipak su to stvari kojih se nitko od naroda nije smio ni rukom dodirnuti.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 11, 14, 'Otpravili su u Jeruzalem, budući da i tamošnji stanovnici isto rade, glasnike da im donesu potrebno dopuštenje od Vijeća starješina.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 11, 15, 'Čim im stigne dopuštenje te izvrše svoj naum, toga istog dana bit će ti predani na uništenje.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 11, 16, 'Kada sam ja, sluškinja tvoja, doznala sve to, pobjegoh od njih. Bog me poslao da sudjelujem s tobom u pothvatu kojemu će se začuditi sva zemlja kada za nj čuje.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 11, 17, 'Jer sluškinja je tvoja pobožna i štuje Boga nebeskoga i dan i noć, pa sada, kad ostanem uza te, gospodaru, tvoja će sluškinja samo zatražiti da može noću otići prema dolini. Ondje ću moliti Boga, pa će mi kazati kada oni počine grijeh.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 11, 18, 'Zatim ću se vratiti i tebe obavijestiti, i ti ćeš tada izaći sa svom vojskom. Među njima neće biti nikoga da ti se odupre.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 11, 19, 'Odvest ću te kroz Judeju sve do samog Jeruzalema, postavit ću usred njega prijestolje tvoje. Ti ćeš ih tjerati pred sobom kao što se tjera stado koje nema pastira. Ni pas pred tobom neće zalajati. Sve sam to predosjetila, to mi je objavljeno, pa sam poslana da ti odam.\"');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 11, 20, 'Te se riječi svidješe Holofernu i svima njegovim slugama. Zadiviše se mudrosti njezinoj te uzviknuše:');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 11, 21, '\"Od jednoga do drugog kraja svijeta nema ravne njoj ljepotom lika i mudrošću razlaganja.\"');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 11, 22, 'A Holoferno joj reče: \"Dobro je učinio Bog što te poslao pred tvojim narodom da nama pripadne moć, a propast onima koji su prezreli moga gospodara.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 11, 23, 'A ti si plemenita izgledom i lijepo zboriš. Budeš li sve učinila kao što si kazala, tvoj Bog postat će i moj Bog, a ti ćeš provoditi svoje dane u palači kralja Nabukodonozora i bit ćeš slavna na svoj zemlji.\"');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 12, 1, 'Zapovjedi da je odvedu na mjesto gdje je bilo pohranjeno srebrno posuđe i naredi da joj daju od jela njegovih i od vina njegova.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 12, 2, 'Ali Judita odgovori: \"Neću toga jesti da ne bude sablazni, nego neka mi se jelo priređuje od onoga što sam donijela sa sobom.\"');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 12, 3, 'Holoferno je zapita: \"Kad ti ponestane što imaš uza se, odakle ćemo ti davati takva jela kad među nama nema nikoga od tvoga roda?\"');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 12, 4, 'Judita odgovori: \"Života mi tvoga, gospodaru, ropkinja tvoja neće ni utrošiti što je sa sobom donijela, a Gospod će već rukom njezinom izvesti što je odlučio.\"');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 12, 5, 'Onda je sluge Holofernove odvedoše u šator. Spavala je do ponoći. Ustade o jutarnjoj straži.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 12, 6, 'Poruči Holofernu: \"Neka gospodar moj dopusti da sluškinja njegova iziđe radi molitve.\"');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 12, 7, 'Holoferno naredi svojim stražarima da je u tome ne ometaju. Ostala je tako tri dana u taboru. Noću je išla u dolinu Betulije i umivala se na studencu u taboru.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 12, 8, 'Kad bi tako izišla, molila bi Gospoda, Boga Izraelova, da joj korake upravi na slavu sinova naroda njezina.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 12, 9, 'Vrativši se čista, zadržala bi se u šatoru dok joj ne bi navečer priredili jelo.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 12, 10, 'Četvrtoga dana Holoferno priredi gozbu samo za svoje časnike. Ne pozva nikoga od posluge.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 12, 11, 'Reče dvoraninu Bagoi, upravitelju svih svojih dobara: \"Idi i nagovori onu Hebrejku koja je kod tebe da dođe jesti i piti s nama.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 12, 12, 'Bila bi nam prava sramota imati uza se takvu ženu a ne biti s njom; jer ako je ne predobijemo, rugat će nam se.\"');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 12, 13, 'Bagoa izađe od Holoferna, uđe k njoj i reče joj: \"Neka ljepojka ne oklijeva doći k mome gospodaru da bude čašćena u njegovoj nazočnosti, da veselo pije vino s nama i postane ovoga dana kao jedna od asirskih kćeri koje žive u dvoru Nabukodonozorovu.\"');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 12, 14, 'Judita mu odgovori: \"Tko sam ja da se usprotivim svome gospodaru? Učinit ću smjesta sve što je drago oku njegovu. Bit će mi to radost sve do smrti.\"');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 12, 15, 'Ustade, ukrasi se haljinama i svakakvim ženskim uresima. Sluškinja ode prije nje te prostrije po zemlji pred Holoferna ovnujske kože koje je dobila od Bagoe za svakidašnju upotrebu da na njima svakoga dana udobno blaguje.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 12, 16, 'Judita uđe i smjesti se. Holofernu se srce uzbudi, duša mu se uznemiri i spopade ga ognjena žudnja da bude s njom. Od onoga dana kad ju je prvi put vidio, samo je vrebao priliku da je zavede.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 12, 17, 'Kaza joj Holoferno: \"DÓe pij i veseli se s nama!\"');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 12, 18, 'Judita odgovori: \"Hoću, pit ću, gospodaru, jer osjećam da je danas moj život tako velik kako nije bio nikada od moga rođenja.\"');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 12, 19, 'Uzela je, jela je i pila pred njim što joj njezina sluškinja bijaše priredila.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 12, 20, 'Holoferno je uživao u njoj i pio je toliko vina koliko ga nije pio nikad u životu.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 13, 1, 'A uvečer se časnici brzo povukoše. Bagoa zatvori šator izvana, pošto je otpravio od svoga gospodara one koji su se još ondje nalazili. Svi odoše na počinak: bijahu umorni jer se gozba jako oduljila.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 13, 2, 'Juditu ostaviše samu u šatoru. Holoferno pao na postelju jer ga vino bijaše potpuno svladalo.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 13, 3, 'Judita je naredila svojoj sluškinji da je čeka pred ložnicom kao i svakog dana. Rekla je da će izaći na molitvu. Tako je kazala i Bagoi.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 13, 4, 'Svi bijahu otišli od Holoferna, nitko, ni malen ni velik, nije ostao u ložnici. Judita, stojeći kraj Holofernove postelje, reče u srcu svom: \"Gospode, Bože svake sile, svrni u ovome času pogled svoj na djelo ruku mojih da se prodiči Jeruzalem!');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 13, 5, 'Ovo je pravi čas da se pobrineš za svoju baštinu i ostvariš moju zamisao o propasti neprijatelja koji su nasrnuli na nas.\"');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 13, 6, 'Priđe stupu postelje, do Holofernove glave, i skide odande Holofernov mač.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 13, 7, 'Zatim, primaknuvši se postelji, zgrabi kosu Holofernovu i kaza: \"Gospodine Bože Izraelov, ojačaj me danas!\"');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 13, 8, 'I iz sve snage udari dvaput Holoferna po vratu i odrubi mu glavu.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 13, 9, 'Njegov trup potom otkotrlja s ležaja i strže zastor sa stupova. Malo kasnije iziđe i glavu Holofernovu predade sluškinji.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 13, 10, 'Ona je metnu u svoju torbu. Obadvije zatim, po običaju, iziđoše na molitvu. Prešavši tabor, zaokružiše ono podolje, popeše se na uzvisinu Betulije i dođoše pod njezina vrata.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 13, 11, 'Judita se javi još izdaleka straži na vratima: \"Otvorite, otvorite vrata! S nama je Bog naš da izvede junaštvo u Izraelu i jakost protiv neprijatelja kao što je učinio i danas.\"');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 13, 12, 'Kako građani začuše njezin glas, požuriše se do vrata svoga grada i pozvaše starješine gradske.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 13, 13, 'Strčaše se svi, malo i veliko, jer ih je njezin dolazak iznenadio. Otvoriše vrata, primiše ih, zapališe vatru da se vide i okružiše ih.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 13, 14, 'Judita im jakim glasom kaza: \"Hvalite Boga! Hvalite ga! Hvalite Boga koji nije uskratio milosti svoje kući Izraelovoj nego je mojom rukom noćas potukao neprijatelje naše.\"');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 13, 15, 'Izvadivši glavu iz torbe, pokaza im je i reče: \"Evo glave Holoferna, vrhovnog zapovjednika vojske asirske, i evo zastora pod kojim je ležao pijan. Bog ga je pogodio rukom jedne žene!');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 13, 16, 'Neka živi Gospodin koji me zaštitio na putu kojim sam hodila! Jer je moje lice zatravilo Holoferna na propast njegovu, nije zgriješio sa mnom te me tako nije osramotio ni okaljao.\"');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 13, 17, 'Puk, sav izvan sebe, pade ničice da se pokloni Bogu i povika u jedan glas: \"Blagoslovljen da si, Bože naš, koji si danas satro neprijatelje naroda svoga!\"');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 13, 18, 'Ozija joj kaza: \"Blagoslovljena bila, kćeri, od Boga Svevišnjega više od svih drugih žena na zemlji! Blagoslovljen Gospod Bog, stvoritelj neba i zemlje, koji te vodio da odsiječeš glavu vođi neprijatelja naših!');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 13, 19, 'Jer tvoje pouzdanje neće biti izbrisano iz srdaca ljudi nego će se oni dovijeka sjećati Božje moći.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 13, 20, 'Neka Bog učini da to bude na tvoju vječnu diku i neka te nagradi svakim dobrom, jer kad bi ponižen naš rod, nisi štedjela života svoga, nego si spriječila našu propast živeći pravedno pred našim Bogom!\" A sav narod nadoda: \"Amen! Amen!\"');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 14, 1, 'Judita im reče: \"Poslušajte me, braćo! Uzmite ovu glavu i objesite je na krunište naših zidina.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 14, 2, 'Čim zora zarudi te sunce obasja zemlju, neka se svatko maši svog oružja i svi hrabri muževi neka izađu iz grada. Izabrat ćete im vođu kao da tobože hoćete sići u ravnicu, na asirske predstraže. Ali nećete sići.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 14, 3, 'Oni će pograbiti svoje oružje, otići će u tabor i probudit će zapovjednike asirske vojske. Zajedno će otrčati k Holofernovu šatoru, i kad Holoferna ne nađu, spopast će ih užas i pobjeći će ispred vas.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 14, 4, 'Vi i svi koji žive u granicama Izraela, progonite ih i uništite na putu njihova uzmaka.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 14, 5, 'Ali prije nego sve to izvedete, pozovite mi Ahiora Amonca da svojim očima prepozna onoga koji je prezreo kuću Izraelovu a njega poslao k nama u smrt.\"');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 14, 6, 'Pozvaše Ahiora iz Ozijine kuće. Kako dođe i vidje Holofernovu glavu u rukama jednog od članova narodnoga zbora, sruši se na zemlju i onesvijesti.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 14, 7, 'Kada se osvijestio, baci se do nogu Juditi, pokloni joj se i uskliknu: \"Blagoslovljena da si u svakome šatoru Judinu i u svakom narodu! Svatko će drhtati od straha kad čuje tvoje ime!');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 14, 8, 'A sada mi pripovjedi što si sve izvela ovih dana.\" Judita mu usred mnoštva pripovjedi sve što je učinila od onoga dana kad je otišla pa do tada, do toga razgovora s njima.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 14, 9, 'Kad je završila kazivanje, narod počne klicati od radosti: svim gradom odjeknuše radosni povici.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 14, 10, 'Tada Ahior, vidjevši što je sve učinio Bog Izraelov, povjerova čvrsto u Boga te se dade obrezati i tako bi pribrojen narodu Izraelovu.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 14, 11, 'A kad zarudje zora, objesiše Holofernovu glavu na zidine. Svaki pograbi svoje oružje te jurnuše u odredima niz padine.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 14, 12, 'Kada ih Asirci ugledaše, obavijestiše svoje zapovjednike. Ovi pođoše zapovjednicima, tisućnicima i ostalim časnicima svojim.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 14, 13, 'Dođoše do Holofernova šatora pa kazaše upravitelju njegovih dobara: \"DÓe probudi našega gospodara. Oni su se robovi usudili sići i napasti nas da zauvijek budu uništeni.\"');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 14, 14, 'Bagoa uđe i pljesnu rukama pred šatorskim zastorom: mišljaše da Holoferno spava s Juditom.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 14, 15, 'Ali kako se nitko ne odazva, razmaknu zastore, uđe u ložnicu i nađe truplo bačeno na prag: glave nigdje, bijaše odnesena.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 14, 16, 'Kriknu iza glasa te plačući, jecajući i snažno zapomažući rastrga na sebi haljine.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 14, 17, 'Uđe zatim u šator u kojem je boravila Judita i ne nađe je. Onda otrča k narodu i povika:');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 14, 18, '\"Ovi su robovi podmukli: jedna sama Hebrejka osramotila je dom kralja Nabukodonozora. Evo Holoferna na zemlji, ali glave na njemu nema.\"');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 14, 19, 'Kad zapovjednici vojske asirske čuše te riječi, razderaše na sebi haljine, dušu im spopade silan strah, a taborom im se prolomiše oštri krikovi i silna kuknjava.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 15, 1, 'I oni koji su se još nalazili u šatorima, kad su čuli što se dogodilo, skameniše se.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 15, 2, 'Uhvati ih strava i strah te ne bijaše čovjeka koji bi ostao uza svoga bližnjega, nego se svi bezglavo razbježaše po svim brdima i ravnicama.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 15, 3, 'I oni koji se bijahu utaborili u brdovitom kraju oko Betulije nagoše u bijeg. Tada se Izraelci sa svim svojim ratnicima baciše na njih.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 15, 4, 'Ozija posla u Betomastaim, Bebe, Kobe, Kolu i na sve područje Izraela skoroteče s porukom o onome što se dogodilo: neka svi nasrnu na neprijatelje te ih unište.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 15, 5, 'Čim to doznaše, svi sinovi Izraelovi jednodušno udariše na njih te su ih tukli sve do Hobe. Tako učiniše i oni koji su pristigli iz Jeruzalema i sa svih brda, jer je i njima javljeno što se dogodilo u neprijateljskom taboru. Žitelji Gileada i Galileje udariše zatim s boka te su ih žestoko tukli sve dok ne umakoše u Damask i njegove krajeve.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 15, 6, 'Ostali stanovnici Betulije nasrnuše na tabor Asiraca, oboriše ga te nagrabiše bogat plijen.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 15, 7, 'Vrativši se s pokolja, sinovi Izraelovi zagospodariše preostalim. I sela i gradići po brdima i ravnicama domogoše se silna plijena; bijaše ga doista mnogo.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 15, 8, 'Veliki svećenik Joakim i starješine sinova Izraelovih koji su živjeli u Jeruzalemu dođoše da se dive dobročinstvu što ga Gospod učini Izraelu, da vide Juditu i da je pozdrave.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 15, 9, 'Kad uđoše u kuću njezinu, svi je jednodušno blagosloviše govoreći: \"Ti si slava Jeruzalema! Ti si najviši ponos Izraela! Ti si uzvišena dika roda našega!');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 15, 10, 'Rukom svojom sve si to učinila, Izraelu dobra pribavila, Bogu samom time omiljela! Blagoslovljena da si na vječna vremena od Gospoda Svevladara.\" A sav narod reče: \"Amen!\"');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 15, 11, 'Trideset je dana narod pljačkao tabor. Juditi dadoše šator Holofernov, svu srebrninu, naslonjače, posuđe i sav njegov namještaj. Ona uze sve to, natovari svoju mazgu, zatim dade upregnuti svoja kola te ih napuni.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 15, 12, 'Sve su žene Izraelove trčale da je vide, hvalile je i plesove izvodile u čast njezinu. Onda ona uze bršljane u ruke i pokloni ih ženama koje su je pratile.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 15, 13, 'Zatim se ona i njezine pratilice ovjenčaše maslinovim grančicama. Ona je stupala na čelu naroda i predvodila žene u plesu; slijedili su je Izraelci naoružani, okićeni vijencima i s hvalospjevom na usnama.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 15, 14, 'Usred sveg Izraela Judita zapjeva ovu zahvalnicu, a sav je narod glasno prihvatio taj hvalospjev.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 16, 1, 'Judita zapjeva: \"Slavite Boga moga s bubnjevima, Gospodinu pjevajte s cimbalima, psalam i pohvalu izvijajte mu u čast, veličajte i zazivajte Ime njegovo!');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 16, 2, 'Jer Gospod Bog što dokončava ratove, da bi udario tabor svoj usred naroda, izbavi me iz ruke progonitelja mojih.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 16, 3, 'Asur siđe s planina sjevernih, dođe sa silnom vojskom svojom. Mnoštvo njihovo potoke zakrči, konji njihovi bregove prekriše.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 16, 4, 'Kaza da će kraj moj zapaliti, moje mladiće mačem isjeći, o tlo razmrskati moju dojenčad, kao plijen moju djecu uzeti, ugrabiti moje djevice.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 16, 5, 'Gospod Svevladar svlada ih rukom žene jedne!');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 16, 6, 'Nisu im mladići silnika slomili, Titanovi sinovi nisu ga oborili, divovi silni nisu ga napali, nego Judita, kći Merarijeva, ljepotom svoga lica njega uništi!');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 16, 7, 'Ona svuče udovičke haljine, da bi Izraelce ugnjetene podigla, namaza lice mašću mirisnom,');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 16, 8, 'na kose prevjes stavi, lanene halje uze da ga opčini.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 16, 9, 'Sandala njemu oko zatravi, ljepota njena dušu mu zarobi, mač mu kroza šiju prođe.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 16, 10, 'Perzijce njena hrabrost osupnu, a Medijce smionost zaprepasti.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 16, 11, 'Tad viknuše ponizni moji, a oni se prepadoše, nemoćni moji, a oni se prestraviše; podigoše glas, a oni u bijeg nagoše!');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 16, 12, 'Djevojčica sasjekoše ih sinovi, pobiše ih kao sinove odmetnika, u boju Boga moga pogiboše.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 16, 13, 'Bogu svom pjevat ću pjesmu novu. Velik si i slavan, Gospode! U sili divan i nepobjediv!');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 16, 14, 'Sva stvorenja tvoja tebi neka služe, jer ti samo reče, i postadoše; posla duh svoj, i on ih oblikova. I glasu tvome nitko ne odolje.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 16, 15, 'Planine će se iz temelja s vodama potresti, hridi će se pred tobom kao od voska istopiti, ali prema onima koji te se boje ti ćeš i tada milostiv biti.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 16, 16, 'Neznatna ti je svaka žrtva na ugodan miris, još neznatnija pretilina paljenice, ali tko se boji Gospoda - velik je zauvijek.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 16, 17, 'Jao narodima koji ustanu na narod moj! Bog Svevladar kaznit će ih na dan Suda: poslat će oganj i crve u meso njihovo, a oni će u boli jaukati zauvijek.\"');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 16, 18, 'Kada dođoše u Jeruzalem, pokloniše se Bogu, a pošto se narod očisti, prinesoše paljenice, dragovoljne prinose i darove.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 16, 19, 'Judita posveti kao \"herem\" sve Holofernove predmete koje joj puk bijaše predao i svilene tkanine koje bijaše uzela s postelje njegove.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 16, 20, 'Narod se veselio tri mjeseca u Jeruzalemu pred Svetištem i Judita je ostala s njima.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 16, 21, 'A nakon tih dana svaki se vrati na svoju baštinu. Judita se povuče u Betuliju i osta na svom posjedu. I svega vijeka svojega bila je slavna na svoj zemlji.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 16, 22, 'Mnogi su je prosili, ali ona ne upozna ni jednoga čovjeka u sve dane života svojega otkad joj umrije muž Manaše i bi pridružen narodu svome.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 16, 23, 'Starjela je i u domu muža svojega postigla dob od sto i pet godina. Sluškinji svojoj dala je slobodu. Umrije u Betuliji. Pokopaše je u pećini Manašea, muža njezina.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 16, 24, 'Dom Izraelov oplakivaše je sedam dana. Prije smrti razdijelila je svoja dobra rođacima svojim i rođacima muža svojega Manašea.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 16, 25, 'U Juditino vrijeme, a i mnogo poslije smrti njezine, ne bijaše nikoga tko bi zadavao strah sinovima Izraelovim.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 1, 1, 'a Druge godine kraljevanja Ahasvera Velikoga, na prvi dan Nisana, Mordokaj, sin Jaira, sina Šimejeva, sina Kišova, iz Benjaminova plemena, usni san. b Mordokaj je bio Židov koji je živio u gradu Suzi, ugledan čovjek, činovnik na kraljevu dvoru; c bio je jedan od onih zarobljenika što ih je Nabukodonozor, babilonski kralj, protjerao iz Jeruzalema zajedno s Jekonijom, judejskim kraljem. d Ovo je njegov san. Evo: krikovi i buka, grmljavina i potres; pometenost na zemlji. e Zatim: dva golema zmaja, oba spremna za borbu, brekću snažno. f Na to brektanje svaki se narod pripremi za vojnu kako bi se borio protiv naroda pravednih. g Bio je dan mraka i tame, jada i pečali, čemera i velike pometenosti na zemlji. h Sav narod pravednih, smućen od straha pred vlastitim nesrećama, spremi se na propast i zavapi k Bogu. i Od toga njihova vapaja neki malen izvor poraste u golemu rijeku, obilatu vodom. k Ogranu svjetlo i sunce te se poniženi uzvisiše i proždriješe moćne. l Mordokaj, koji je usnio taj san i nazrijevao što Bog kani učiniti, pošto se probudi, zadrža to u srcu trudeći se do noći da svakoj pojedinosti dokuči značenje. m Mordokaj je mirno boravio u kraljevskoj palači s Gabatom i Tarom, dvojicom kraljevih eunuha koja su čuvala dvor. n Slušao je njihove razgovore. I proniknuv jednom njihove osnove, otkri da su se spremali podići ruke na kralja Ahasvera, pa ih prokaza kralju. o A kralj podvrgnu ispitivanju oba eunuha, koji, pošto su priznali, bijahu usmrćeni. p Kralj odredi da se zapišu ti događaji da bi se sačuvao spomen na njih, a opisa ih i Mordokaj. q Kralj zbog toga imenova Mordokaja dostojanstvenikom u kraljevskoj palači i obdari ga poklonima. r Ali Haman Hamdatin, Agađanin, koji bijaše u časti kod kralja, nastojaše da naudi Mordokaju i njegovu narodu zbog dvaju kraljevih eunuha. Bilo je u vrijeme Ahasvera, onoga Ahasvera koji je vladao nad sto dvadeset i sedam pokrajina od Indije do Etiopije.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 1, 2, 'U to vrijeme, dok je kralj Ahasver sjedio na prijestolju svoga kraljevstva u tvrđavi grada Suze,');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 1, 3, 'treće godine svoga kraljevanja, priredi on gozbu za sve svoje knezove i službenike. Našli su se tako pred njim zapovjednici perzijske i medijske vojske, odličnici i pokrajinski upravitelji.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 1, 4, 'Punih sto i osamdeset dana pokazivaše on bogatstvo i slavu kraljevstva svoga i veličanstveni sjaj veličine svoje.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 1, 5, 'Kad je prošlo to vrijeme, priredi kralj u vrtnom trijemu svoje palače sedmodnevnu gozbu za sav narod koji se nalazio u tvrđavi grada Suze, od najvišega pa do najnižega.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 1, 6, 'Zavjese od najfinijeg lana, vune, ljubičasta skrleta bile su pričvršćene vrpcama od beza i crvena grimiza o srebrne prstenove na stupovima od bijela mramora. Na podu od zelenog i bijelog mramora, sedefa i skupocjenog kamenja, nalazile se postelje od srebra i zlata.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 1, 7, 'Za piće su služili zlatni pehari, sve jedan drugačiji od drugoga, a vina je bilo kraljevski obilno, kako i dolikuje kraljevskoj moći.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 1, 8, 'Pilo se po nekom pravilu, ali ne prisilno, jer je kralj bio naredio svim nadzirateljima svoga dvora da sa svakim postupaju prema njegovoj želji.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 1, 9, 'I kraljica Vašti priredi gozbu za žene u kraljevskoj palači kralja Ahasvera.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 1, 10, 'Sedmoga dana, kad srce kraljevo bijaše veselo od vina, naredi Mehumanu, Bizeti, Harboni, Bigti, Abagti, Zetaru i Karkasu, sedmorici eunuha koji su mu služili,');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 1, 11, 'da dovedu preda nj kraljicu Vašti s kraljevskom krunom, da bi pokazao narodu i knezovima ljepotu njezinu. Ona je uistinu bila privlačna.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 1, 12, 'Ali se kraljica Vašti ne htjede odazvati kraljevu pozivu što joj ga prenesoše dvorani. Kralj se tada veoma razbjesni i njegova se srdžba rasplamsa.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 1, 13, 'Onda zapita mudrace koji poznaju vremena. Jer svaki se kraljev posao tako proučavao među onima koji su poznavali zakone i pravo.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 1, 14, 'Najbliži su mu bili Karsena, Šetar, Admata, Taršiš, Mares, Marsena i Memukan, sedam knezova Perzije i Medije. Oni su smjeli gledati kraljevo lice i zauzimali su najistaknutija mjesta u kraljevstvu.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 1, 15, 'Upita ih: \"Što treba prema zakonu poduzeti protiv kraljice Vašti, koja se nije pokorila zapovijedi kralja Ahasvera koju su joj saopćili dvorani?\"');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 1, 16, 'Memukan tada odgovori pred kraljem i knezovima: \"Kraljica je Vašti skrivila ne samo kralju nego i svim poglavarima i svem narodu koji prebiva u svim pokrajinama kralja Ahasvera.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 1, 17, 'Jer će za držanje kraljičino doznati sve žene pa će prezirati svoje muževe govoreći: \'Kralj je Ahasver naredio da dovedu preda nj kraljicu Vašti, ali ona ne htjede doći.\'');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 1, 18, 'I žene će knezova perzijskih i medijskih, pošto doznaju za kraljičino ponašanje, još danas pripovijedati svim poglavarima kraljevim, pa će biti prkosa i prezira u izobilju.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 1, 19, 'Stoga, svidi li se kralju, neka se objavi kraljevska naredba i umetne među zakone Perzije i Medije, tako da se više ne može opozvati, da se Vašti ne smije više pojaviti pred kraljem Ahasverom, a kralj neka preda kraljevsku čast drugoj ženi, boljoj od nje.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 1, 20, 'Kad se ta naredba koju će kralj učiniti pročuje po svem kraljevstvu, koje je zaista veliko, sve će žene iskazivati poštovanje svojim muževima, od najvišega pa do najnižega.\"');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 1, 21, 'Riječ se svidje i kralju i njegovim knezovima. Stoga on učini kako mu je savjetovao Memukan.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 1, 22, 'Uputi pisma u sve kraljevske pokrajine, svakoj pokrajini pismom kojim se ona služila, a svakom narodu njegovim jezikom, da svaki muž bude gospodar u svojoj kući.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 2, 1, 'Poslije tih događaja, kako mu se utiša gnjev, kralj Ahasver sjeti se Vaštije, onoga što je ona učinila i što je bilo odlučeno protiv nje.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 2, 2, 'Rekoše tada momci što služahu kralja: \"Neka se potraže za kralja mlade djevojke, djevice lijepa izgleda.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 2, 3, 'Kralj neka odredi u svim pokrajinama svojega kraljevstva povjerenike da mu sakupe sve djevice pristala izgleda u tvrđavi grada Suze, u haremu, pod upravom Hegeja, kraljeva eunuha, čuvara žena. On će se pobrinuti za njihovu njegu.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 2, 4, 'Ona djevojka koja se najviše svidi očima kraljevim neka kraljuje umjesto Vaštije.\" Bijaše to po volji kralju, i on tako uradi.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 2, 5, 'U tvrđavi grada Suze bio je neki Židov koji se zvao Mordokaj, sin Jaira, sina Šimeja, sina Kišova, iz plemena Benjaminova.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 2, 6, 'On je bio protjeran iz Jeruzalema među prognanicima koje je babilonski kralj Nabukodonozor odveo zajedno s judejskim kraljem Jekonijom.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 2, 7, 'On je odgajao Hadasu, to jest Esteru, kćerku strica svoga, jer ona ne imađaše ni oca ni majke. Djevojka je bila pristala i lijepa izgleda. Poslije smrti njezina oca i njezine majke Mordokaj je uze k sebi kao kćerku.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 2, 8, 'Kako se začu za kraljevu riječ i njegovu naredbu, mnogo se djevojaka sabra u tvrđavi grada Suze pod Hegejevim nadzorom. Tako dovedoše i Esteru u kraljevu palaču, pod nadzor Hegeja, čuvara žena.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 2, 9, 'Djevojka se svidje njegovim očima, steče ona njegovu naklonost i on se pobrinu za njezino uljepšavanje i uzdržavanje. Uz to joj dade sedam najvrednijih ropkinja kraljevskog dvora i premjesti je, skupa s djevojkama, u najudobnije prostorije harema.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 2, 10, 'Estera ne spomenu ni naroda ni obitelji kojoj je pripadala, jer joj Mordokaj bijaše zabranio da to učini.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 2, 11, 'Svakoga je dana Mordokaj šetao pred dvorištem harema da bi doznao kako se Estera osjeća i kako se prema njoj odnose.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 2, 12, 'Svaka je djevojka morala ući kralju kad je na nju, prema uredbi za žene, došao red, to jest nakon dvanaest mjeseci. Jer tada se završavalo razdoblje njihova uljepšavanja: šest mjeseci uljem iz mirne, a šest mjeseci balzamom i ostalim pomastima za žensku njegu.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 2, 13, 'Pa kad bi djevojka ulazila kralju, bilo joj je dopušteno da sa sobom iz harema u kraljevsku palaču ponese sve što bi zatražila.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 2, 14, 'Ona bi ulazila uvečer, a ujutro bi se vraćala u drugi harem, pod nadzorom Šaašgaza, kraljeva eunuha, čuvara priležnica. Više se ne bi vraćala kralju, osim ako bi je posebno zaželio i dozvao je k sebi poimence.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 2, 15, 'Kada dođe red na Esteru, kćerku Abihajla, koji je bio stric Mordokaja koji ju je bio pokćerio, da uđe kralju, ona ne zatraži ništa osim onoga što joj bijaše rekao Hegej, kraljev eunuh, čuvar žena. Ipak je pobuđivala udivljenje svih koji su je gledali.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 2, 16, 'Esteru, dakle, uvedoše kralju Ahasveru, u njegovu kraljevsku palaču, u desetom mjesecu, mjesecu Tebetu, sedme godine njegova vladanja.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 2, 17, 'Kralj zavolje Esteru više od svih drugih žena; više nego sve ostale djevice ona mu omilje i predobi ona njegovu naklonost. I položi on na njezinu glavu kraljevsku krunu, pa mjesto Vaštije ona posta kraljicom.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 2, 18, 'Nakon toga priredi kralj u čast Estere veliku gozbu za svoje knezove i službenike; svim pokrajinama odredi odmor i razda darove kraljevski darežljivo.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 2, 19, 'Kad su drugi put djevojke bile sakupljene, Mordokaj sjeđaše na vratima kraljevim.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 2, 20, 'Estera ne oda ni naroda ni obitelji iz koje je potjecala, kao što joj Mordokaj bijaše naredio. Estera se i dalje držala svih Mordokajevih uputa kao kad se nalazila pod njegovim skrbništvom.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 2, 21, 'U ono vrijeme kad je Mordokaj sjedio na vratima kraljevim, Bigtan i Tereš, dva kraljeva dvoranina, čuvari praga, planuše gnjevom i počeše snovati da podignu ruku na kralja Ahasvera.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 2, 22, 'Za tu njihovu namjeru sazna Mordokaj. On je dojavi kraljici Esteri, a Estera je u Mordokajevo ime saopći kralju.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 2, 23, 'Sve se izvidje i otkri se zavjera, pa obojica budu obješena o stup. To se pred kraljem zapisa u knjizi Ljetopisa.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 3, 1, 'Poslije tih događaja kralj Ahasver promaknu Hamana, Hamdatina sina, Agađanina: uzvisi ga i njegovo prijestolje postavi iznad svih ostalih dostojanstvenika koji su bili s njim.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 3, 2, 'Svi službenici kraljevi koji su se nalazili na kraljevim vratima prigibali bi koljena i padali ničice pred Hamanom, jer je tako zapovjedio kralj. Ali Mordokaj ne bi prignuo koljeno niti bi pao ničice.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 3, 3, 'Službenici kraljevi koji su se nalazili na vratima kraljevim rekoše Mordokaju: \"Zašto prestupaš kraljevu zapovijed?\"');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 3, 4, 'Iako su mu oni to ponavljali svaki dan, on ih ne posluša. Onda oni to dojaviše Hamanu, da vide vrijedi li Mordokajevo opravdanje. Jer im bijaše rekao da je Židov.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 3, 5, 'Kad Haman utvrdi da Mordokaj niti prigiba koljeno niti pada ničice pred njim, jako se razljuti.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 3, 6, 'A kad dozna kojemu narodu pripada, učini mu se premalo podići ruke na samog Mordokaja nego naumi s njim pobiti i sve Židove koji su živjeli u svem kraljevstvu Ahasverovu.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 3, 7, 'U prvom mjesecu, to jest u mjesecu Nisanu, dvanaeste godine Ahasverova kraljevanja u nazočnosti Hamana baciše \"Pur\", to jest ždrijeb, da utvrde dan i mjesec. Ždrijeb pade na trinaesti dan dvanaestoga mjeseca, to jest na mjeseca Adara.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 3, 8, 'I Haman kaza kralju Ahasveru: \"U svim pokrajinama tvoga kraljevstva ima jedan narod razasut među drugim narodima i od njih odvojen. Njegovi su zakoni drugačiji od zakona u svih ostalih naroda. Oni se ne drže kraljevskih odredaba. Kralj ih zato ne smije pustiti na miru.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 3, 9, 'Ako je kralju po volji, neka se raspiše da se oni zatru; a ja ću izbrojiti deset tisuća srebrnih talenata na ruke povjerenika da ih pohrane u kraljevsku riznicu.\"');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 3, 10, 'Nakon toga kralj skinu pečatni prsten s ruke i preda ga Hamanu, sinu Hamdatinu, Agađaninu, neprijatelju Židova,');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 3, 11, 'i kaza mu: \"Neka ti bude novac i narod, pa učini s njim što bude dobro u tvojim očima.\"');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 3, 12, 'Trinaestoga dana prvoga mjeseca bijahu sazvani kraljevi pisari, pa o onome što je naložio Haman sastaviše pisma i upraviše ih kraljevskim namjesnicima, upraviteljima što stajahu na čelu pojedinih pokrajina, knezovima svakoga pojedinog naroda, svakoj pokrajini njezinim pismom i svakom narodu njegovim jezikom. Pisma su napisana u kraljevo ime i na njima je udaren kraljev pečat.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 3, 13, 'Po skorotečama razaslane su svim kraljevim pokrajinama poslanice da se svi Židovi, od dječaka do staraca, djeca i žene unište, pobiju, zatru, a njihova dobra da se zaplijene u jednom jedinom danu, i to trinaestog dana dvanaestog mjeseca, mjeseca Adara. a Ovo je prijepis poslanice: \"Veliki kralj Ahasver upraviteljima sto dvadeset i sedam pokrajina od Indije do Etiopije i njima podložnim mjesnim glavarima ovako piše: b Budući da imam vlast nad mnogim narodima i gospodstvo nad svim svijetom, odlučih, ne zanesen ohološću moći nego u želji da uvijek blago i čovječno vladam, dati podanicima spokojan život i pružiti kraljevstvu blagostanje i slobodu kretanja po njemu te učvrstiti mir za kojim svi ljudi žude. c Pošto sam zapitao savjetnike kako bi se moglo to ostvariti, Haman, koji se među nama izdvaja razboritošću i koji se ističe prokušanom odanošću i ustrajnom vjernošću i zauzima drugo mjesto u kraljevstvu, d prokazao je da se među ostale narode svijeta zavukao jedan neprijateljski narod, svojim zakonima protivan svim pucima, narod koji vječno prezire kraljeve odluke tako te se ne može učvrstiti zajedničko carstvo kojim inače besprijekorno upravljamo. e Ustanovili smo dakle da je samo taj narod neprekidno u sukobu sa svim ljudima, da se ističe načinom života što odstupa od zakona, da zbog neslaganja s našim naumima počinja najgora nedjela tako te se kraljevstvo ne može učvrstiti. f Stoga naređujemo da se, zajedno sa ženama i djecom, neprijateljskim mačevima bez ikakva sažaljenja i milosrđa potpuno iskorijene oni koji vam budu naznačeni u pismima Hamana, upravitelja javnih poslova i našega drugog oca, i to četrnaestoga dana dvanaestoga mjeseca, Adara, tekuće godine. g Tako će se, pošto nekadašnji i današnji neprijatelji u jednom danu budu silovito strovaljeni u Podzemlje, ubuduće za sva vremena naši poslovi moći odvijati postojano i nesmetano.\"');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 3, 14, 'Sadržaj ove naredbe, koja je imala postati zakonom u svakoj pokrajini, bio je objavljen svim narodima da bi bili spremni za taj dan.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 3, 15, 'Skoroteče žurno potekoše s kraljevskom naredbom. Zakon bi objavljen i u tvrđavi Suze, pa dok su kralj i Haman sjedili i častili se, grad je Suza bio uznemiren.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 4, 1, 'Mordokaj doznade za sve što se dogodilo: razdera na sebi haljine, navuče kostrijet, posu se pepelom i prođe posred grada kukajući glasno i gorko.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 4, 2, 'Dođe samo do kraljevih vrata, jer s onom kostrijeti na sebi ne mogaše kroz njih proći.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 4, 3, 'U svakoj je pokrajini, svuda gdje se doznala kraljeva riječ i njegov proglas, među Židovima zavladala žalost: postili su, plakali i jadikovali. Mnogima od njih kostrijet i pepeo posta ležaj.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 4, 4, 'Esterine djevojke i njezini eunusi dođoše da je o tome obavijeste. Kraljica se veoma uznemiri. Posla Mordokaju haljine da bi ih obukao a skinuo sa sebe kostrijet, ali on to odbi.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 4, 5, 'Nato Estera pozva Hataka, jednog od kraljevih eunuha koji joj je bio određen za službu, pa ga posla k Mordokaju da dozna od njega što se dogodilo i zbog čega je takav.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 4, 6, 'Hatak ode do Mordokaja na gradski trg, pred vrata kraljeva.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 4, 7, 'Mordokaj mu pripovjedi što mu se dogodilo i podrobno ga obavijesti o novcu koji je Haman obećao položiti u kraljevu riznicu da bi mogao uništiti Židove.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 4, 8, 'Dade mu i prijepis naredbe o njihovu zatoru, koja je objavljena u Suzi, da je pokaže Esteri te da joj javi i naloži neka ide kralju: neka ga moli za milost i posreduje kod njega za svoj narod. a \"Sjeti se dana siromaštva svoga kad sam te hranio rukom svojom, jer se Haman, drugi čovjek kraljevstva, dogovorio s kraljem da nas usmrti. b Zazivaj Boga, govori kralju za nas i oslobodi nas od smrti.\"');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 4, 9, 'Hatak se vrati i donese Esteri Mordokajevu poruku.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 4, 10, 'Estera odvrati Hataku i naredi mu da saopći Mordokaju:');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 4, 11, '\"Svi službenici kraljevi i narod kraljevih pokrajina znaju kako svakoga onoga, bio on muškarac ili žena, koji nepozvan uđe kralju u unutrašnje predvorje čeka jedan jedini zakon: smrtna kazna, osim ako kralj ne pruži takvome svoje zlatno žezlo i poštedi mu život. A ja već trideset dana nisam bila pozvana kralju.\"');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 4, 12, 'Mordokaju bjehu saopćene Esterine riječi,');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 4, 13, 'pa on poruči Esteri: \"Nemoj misliti da ćeš se zato što se nalaziš u kraljevoj palači spasiti jedina od svih Židova:');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 4, 14, 'jer budeš li u ovoj prilici šutjela, doći će Židovima pomoć i spas s druge strane, a ti ćeš s kućom svoga oca propasti. Tko zna nisi li se baš i popela do kraljevske časti zbog časa kao što je ovaj?\"');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 4, 15, 'Estera i opet poruči Mordokaju:');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 4, 16, '\"Hajde, sakupi sve Židove koji se nalaze u Suzi. Postite za me: tri dana i tri noći ne jedite niti pijte. I ja ću tako postiti sa svojim djevojkama. Tako pripremljena ući ću kralju i unatoč zakonu, pa treba li da poginem, poginut ću.\"');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 4, 17, 'Mordokaj se onda povuče i učini što mu je naredila Estera. a I sjetivši se svih djela koje je Gospod izveo, pomoli se Gospodu i kaza: b \"Gospode, Gospode, kralju koji vladaš nad svime, sve je u tvojoj vlasti i nema toga koji bi se mogao suprotstaviti tvojoj volji da spasiš Izraela! c Ti si stvorio nebo i zemlju i sve što je divljenja vrijedno pod nebom. Gospodar si svega i nema toga koji se može tebi oprijeti, Gospodine! d Tebi je sve poznato; ti znaš, Gospodine: nisam pao ničice pred bahatog Hamana, ali ne iz drskosti, ni iz oholosti, ni iz častoljublja. Ti znaš da bih za spas Izraela bio voljan i tabane njegove cjelivati. e To sam učinio zato da ne metnem čast koja se iskazuje čovjeku iznad one koja se iskazuje Bogu. Neću pasti ničice ni pred kim, nego samo pred tobom, moj Gospodine, i to ne činim iz oholosti. f Sada, Gospodine, Bože, kralju, Bože Abrahamov, poštedi narod svoj, jer gledaju samo kako bi nas istrijebili: žele uništiti ono što je od početka bila tvoja baština. g Nemoj zanemariti posjed svoj koji si oslobodio iz egipatske zemlje! h Poslušaj molitvu moju, budi milostiv nasljedstvu svome i u veselje prometni plač naš, da bismo, ostavši živi, mogli hvalospjevima slaviti ime tvoje i nemoj dopustiti da iščeznu usta onih koji te hvale, o Gospode!\" i I sav je Izrael vapio svom snagom svojom, jer je smrt bila pred očima njihovim. k I kraljica se Estera, obuzeta smrtnom tjeskobom, uteče Gospodinu; pošto svuče sa sebe sjajne haljine, navuče odjeću tjeskobe i žalosti, te umjesto skupocjenim mirisima posu glavu pepelom i prahom. I ponizi veoma tijelo svoje postom, a svako mjesto na kojem se u znak veselja znala ukrašavati posu uvojcima svoje kose, pomoli se Bogu Izraelovu i kaza: l \"Gospodine moj, kralju naš, ti si jedini! Dođi u pomoć meni koja sam sama, kojoj nema druge pomoći do tebe, jer opasnost je moja u ruci mojoj. m Ja sam od svoga djetinjstva slušala u obiteljskom rodu da si ti, Gospode, izabrao Izraela među svim drugim narodima: naše očeve među svim njihovim precima u svoju trajnu baštinu i da si za njih učinio sve što si im obećao. n Ali smo sad sagriješili pred tobom i ti si nas predao u ruke neprijatelja naših jer smo iskazivali počast bogovima njihovim. Pravedan si, Gospodine! o I sad oni, nezadovoljni već gorčinom sužanjstva našega, staviše ruke svoje u ruke kumira svojih da će poništiti odredbu usta tvojih, uništiti baštinu tvoju, začepiti usta onima koji te hvale i utrnuti slavu doma tvoga i žrtvenika tvoga, p a otvoriti usta naroda da hvale njihove isprazne kumire i dive se jednom kralju od mesa. q Nemoj predati, Gospode, žezlo svoje onima koji ne postoje. Neka se ne smiju propasti našoj, nego okreni naum njihov na njihove glave i primjerno kazni onoga koji je počeo bjesniti protiv nas. r Sjeti se, Gospode! Objavi se u vrijeme naših jada i ohrabri me, o kralju bogova i vladaru svakoga gospodstva! s Metni u moja usta primjerenu riječ pred lavom, a njegovo srce zadahni mržnjom na neprijatelja našega; da zatre njega i njegove sumišljenike. t A nas oslobodi rukom svojom i dođi u pomoć meni koja sam sama i nemam nego tebe, o Gospode! u Sve ti je poznato pa znaš da mrzim slavu opakih i da mi je odvratna postelja neobrezanih i svakoga tuđinca. w Znaš tjeskobu moju, jer ja se gnušam nad znamenjem moga visočanstva koje se nalazi na glavi mojoj. U dane kad se s njime pojavim grstim se nad njim kao nad dronjkom mjesečnog pranja i ne nosim ga onih dana koji pripadaju samo meni. x Sluškinja tvoja nije nikada jela sa stola Hamanova, nisam nikada počastila kraljevsku gozbu, niti sam pila vino ljevanica. y I od dana uzdignuća svoga do danas sluškinja tvoja nije se poveselila osim u tebi, Gospode, Bože Abrahamov. z Bože, nadasve moćni, uslišaj glas beznadnih i izbavi nas iz ruku opakih, a oslobodi i mene od moga straha!\"');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 5, 1, 'Trećega dana, pošto presta moliti, svuče molitvene haljine i zaodjenu se slavom svojom. a Tako čarobna zazva Boga Svevida i Spasitelja. Onda uze dvije sluškinje. Na jednu se gotovo nježno naslanjala, a druga ju je slijedila i pridržavala njezinu odjeću. b Blistala je od vrhunske ljepote, lice joj bijaše veselo, kao rastvoreno ljubavi, a srce sapeto od straha. c Kroza sva je vrata ušla pred kralja. On je sjedio na svom kraljevskom prijestolju, zaogrnut svim ukrasom veličanstva svoga, sav u zlatu i dragom kamenju, ulijevao je veliko strahopoštovanje. d Podigavši svoje lice, sjajem ozaren, pogleda krajnje ljutit. Kraljici pozli. Od slabosti problijedje i klonu na glavu sluškinje što je pred njom išla. e Tada Bog sklonu kraljevu dušu na blagost. Zabrinut, kralj skoči sa svoga prijestolja i uze je u naručje dok ne dođe k sebi. Hrabrio ju je utješnim riječima i upitao: f \"Što je, Estero? Ja sam tvoj brat! Ne boj se, nećeš umrijeti - naša je uredba za obične ljude. Priđi!\"');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 5, 2, 'I podigavši zlatno žezlo, postavi ga na vrat Esteri, zagrli je i reče: \"Govori mi!\" a Ona mu reče: \"Spazih te, gospodaru, kao anđela Božjega, pa mi se uznemiri srce od straha pred sjajem tvojim. Jer si, gospodaru, divan i lice ti je puno dražesti.\" b Dok je još govorila, klonu od iznemoglosti. Kralj se uznemiri, a sva ju je posluga njegova hrabrila.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 5, 3, 'Kralj joj reče: \"Što je tebi, kraljice Estero? Što želiš? Bila to i polovica kraljevstva, dobit ćeš je!\"');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 5, 4, 'Estera odgovori: \"Neka kralj, ako mu je drago, dođe s Hamanom na gozbu koju sam danas priredila.\"');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 5, 5, 'Kralj odvrati: \"Obavijestite odmah Hamana da bi se izvršila Esterina želja.\" Kralj dakle dođe s Hamanom na gozbu koju je Estera priredila.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 5, 6, 'Dok su pili vino, kralj kaza Esteri: \"Što god zatražiš, dobit ćeš. Što god zaželiš, bila to i polovica kraljevstva, bit će ti!\"');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 5, 7, 'Estera odgovori: \"Molba mi je i želja,');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 5, 8, 'ako sam našla milost u očima kraljevim i ako se kralju svidi dati mi što molim i učiniti što želim, da kralj ponovo dođe s Hamanom na gozbu koju ću sutra pripremiti za njih i tad ću postupiti po riječi kraljevoj.\"');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 5, 9, 'Toga dana Haman iziđe sretan i zadovoljna srca, ali se rasrdi jako na Mordokaja kad vidje da na vratima kraljevim nije ustao ni maknuo se pred njim.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 5, 10, 'Haman se ipak svlada. Ode kući i posla po svoje prijatelje i po ženu Zarešu.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 5, 11, 'Pripovijedao im je o sjaju svoga bogatstva, o mnoštvu svojih sinova i o svemu onome čime ga je kralj uzveličao i čime ga je uzdignuo nad sve svoje knezove i službenike.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 5, 12, 'Haman još dometnu: \"I kraljica Estera nije uz kralja pozvala nikoga osim mene na gozbu koju je priredila. I sutra sam samo ja uz kralja njezin uzvanik.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 5, 13, 'Ali me sve to ne može učiniti sretnim dokle god gledam Židova Mordokaja kako sjedi na vratima kraljevim.\"');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 5, 14, 'Reče mu Zareša, žena njegova, i svi prijatelji njegovi: \"Podigni vješala visoka pedeset lakata. Sutra ujutro zatraži od kralja neka na njih objese Mordokaja. Poslije toga idi sretan s kraljem na gozbu.\" Savjet se Hamanu učini dobar, pa on naredi da se podignu vješala.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 6, 1, 'Te noći kralj ne mogaše usnuti. Zato naredi da mu donesu i čitaju knjigu znamenitih događaja, Ljetopise.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 6, 2, 'Tu se nađe zapisano kako je Mordokaj prokazao Bigtanu i Tereša, dva dvoranina kraljeva, čuvare praga, koji su se spremali da podignu ruke na kralja Ahasvera.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 6, 3, 'Kralj upita: \"Kakva je čast i kakvo je odlikovanje zapalo Mordokaja za sve to?\" Kraljeve sluge, dvorani koji ga slušahu, odgovoriše: \"Ništa nije učinjeno za nj.\"');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 6, 4, 'Kralj onda zapita: \"Tko je u predvorju?\" A to u vanjsko predvorje kraljevske palače bijaše stigao Haman da traži od kralja neka objese Mordokaja na vješalima koja su već bila podignuta za nj.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 6, 5, 'Službenici kraljevi odgovoriše: \"Eno se u predvorju nalazi Haman.\" \"Neka uđe!\" - naredi kralj.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 6, 6, 'Kako Haman uđe, kralj ga upita: \"Što treba učiniti čovjeku koga kralj hoće da počasti?\" Haman reče u sebi: \"Koga ako ne mene kralj želi počastiti?\"');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 6, 7, 'Zato odgovori kralju: \"Za čovjeka koga kralj želi počastiti');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 6, 8, 'treba donijeti kraljevske haljine koje kralj sam oblači i dovesti konja kojega kralj jaše i položiti mu na glavu kraljevsku krunu.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 6, 9, 'Haljine i konja neka kralj preda jednome od najuglednijih kneževa kraljevih da bi taj obukao onoga koga kralj želi počastiti i na konju ga odveo na gradski trg uzvikujući pred njim: \'Tako biva onome koga kralj hoće da počasti!\'\"');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 6, 10, 'Kralj nato naredi Hamanu: \"Uzmi odmah haljine i konja, kako si rekao, pa učini tako Mordokaju Židovu koji sjedi na kraljevim vratima i ne propusti ništa od onoga što si rekao!\"');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 6, 11, 'Haman uze haljine i konja: obuče u haljine Mordokaja i provede ga na konju po trgu grada vičući pred njim: \"Tako biva onome koga kralj hoće da počasti!\"');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 6, 12, 'Malo zatim Mordokaj se vrati k vratima kraljevim, a Haman, tužan i zastrte glave, ode žurno kući');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 6, 13, 'te ispriča Zareši, ženi svojoj, i svima prijateljima svojim što se dogodilo. Njegovi mu savjetnici i žena Zareša rekoše: \"Ako Mordokaj, pred kojim si počeo posrtati, pripada židovskom rodu, nećeš ga nadjačati, nego će te on zacijelo oboriti.\"');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 6, 14, 'Još su o tom razgovarali, kad eto kraljevih dvorana. Došli su tražiti Hamana da ga žurno odvedu na gozbu koju je priredila Estera.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 7, 1, 'Kralj i Haman dođoše na gozbu kraljici Esteri.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 7, 2, 'I toga drugoga dana, dok se pilo vino, reče kralj Esteri: \"Koja ti je molba, kraljice Estero? Bit će ti udovoljena! Koja je tvoja želja? Ako je i pola kraljevstva, bit će ti!\"');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 7, 3, 'Kraljica Estera odgovori: \"Ako sam, kralju, našla milost u tvojim očima i ako ti je s voljom, neka mi se u ime molbe pokloni život, a u ime želje moj narod!');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 7, 4, 'Jer smo ja i narod moj predani za zator, klanje, uništenje. Da smo predani u roblje, šutjela bih jer nevolja ne bi bila štetna po kralja.\"');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 7, 5, 'Ali kralj Ahasver upade kraljici Esteri u riječ pa je upita: \"Tko je taj? Gdje je taj koji je namislio takvo što učiniti?\" Estera tada odgovori: \"Progonitelj i neprijatelj jest Haman, ovaj zlikovac!\"');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 7, 6, 'Haman se zaprepasti pred kraljem i kraljicom.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 7, 7, 'Kralj, gnjevan, ostavi vino te ode u vrt palače. Haman osta uz kraljicu da je moli za svoj život, jer je uvidio da je njegova nesreća pred kraljem gotova.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 7, 8, 'Kralj se vrati iz vrta u dvoranu gdje se pilo vino. Dotle Haman bijaše pao na počivaljku na kojoj se nalazila Estera. \"Pokušavaš još i nasilje nad kraljicom, i to u mome vlastitom domu?\" - povika kralj. Tek što su te riječi izletjele iz kraljevih usta, pokriše lice Hamanu.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 7, 9, 'Tada kaza Harbona, jedan od dvorana koji su stajali u službi kraljevoj: \"Eno i vješala što ih je Haman pripravio za Mordokaja koji je govorio u korist kraljevu. Nalaze se kraj Hamanove kuće i visoka su pedeset lakata.\" Kralj zapovjedi: \"Objesite ga na njih!\"');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 7, 10, 'Hamana objesiše na vješala koja bijaše pripravio Mordokaju, i kraljeva se srdžba utiša.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 8, 1, 'Onoga istog dana kralj Ahasver preda kraljici Esteri kuću Hamana, progonitelja Židova, a Mordokaj je stupio pred kraljevo lice, jer je Estera objasnila kralju što joj je on.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 8, 2, 'Kralj skinu pečatni prsten, koji je već bio oduzeo Hamanu, i dade ga Mordokaju, a Estera postavi Mordokaja nad Hamanovom kućom.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 8, 3, 'Estera tada ponovo progovori kralju. Baci mu se pred noge; rasplaka se i najvruće ga zamoli da osujeti zlo Hamana Agađanina i naum opaki što ga bijaše zasnovao protiv Židova.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 8, 4, 'Kralj pruži prema Esteri zlatno žezlo. Estera se diže, stade pred kraljem');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 8, 5, 'i reče: \"Ako je kralju po volji, ako sam našla milost pred licem njegovim, ako je kralju pravo te ako sam mila u njegovim očima, neka pismeno opozove sve što napisa Haman, sin Hamdatin, Agađanin, u opakoj nakani da se pobiju Židovi koji se nalaze u svim pokrajinama kraljevstva.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 8, 6, 'TÓa kako bih ja mogla gledati nesreću koja bi pogodila moj narod? Kako bih mogla gledati zator roda svoga?\"');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 8, 7, 'Kralj Ahasver odgovori kraljici Esteri i Mordokaju Židovu: \"Eto, poklonio sam Esteri kuću Hamanovu, a njega sam dao objesiti jer je bio digao svoju ruku na Židove,');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 8, 8, 'a vi u ime kraljevo napišite o Židovima što vam se sviđa i zapečatite kraljevim prstenom. Jer neopoziv je proglas koji je u kraljevo ime napisan te kraljevim pečatom zapečaćen.\"');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 8, 9, 'Tada, dvadeset i trećeg dana trećega mjeseca, to jest mjeseca Sivana, budu sazvani pisari kraljevi i prema svemu što bijaše naredio Mordokaj napisa se Židovima, namjesnicima, upravljačima i knezovima pokrajina od Indije do Etiopije, a bijaše sto dvadeset i sedam pokrajina, svakoj pokrajini njezinim pismom, svakom narodu njegovim jezikom, pa i Židovima njihovim pismom i njihovim jezikom.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 8, 10, 'On napisa pisma u ime kralja Ahasvera i zapečati ih kraljevim prstenom pa ih razasla po skorotečama koji su jahali na konjima, pastusima iz kraljevske ergele.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 8, 11, 'Kralj je dopustio Židovima po svim gradovima da se mogu sastajati, braniti svoj život te uništiti, ubiti i zatrti svaku vojsku narodnu ili pokrajinsku koja bi ih napala, ne štedeći ni djecu ni žene, a slobodno im je oplijeniti njihova dobra;');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 8, 12, 'sve istoga dana u svim pokrajinama kraljevstva Ahasverova: trinaestog dana dvanaestoga mjeseca, to jest mjeseca Adara. a Prijepis toga pisma glasi: b \"Veliki kralj Ahasver namjesnicima u sto dvadeset i sedam pokrajina od Indije do Etiopije, upravljačima pokrajina i svima svojim vjernim podanicima, pozdrav! c Mnogi, koliko su više obasuti častima, poradi velike dobrodušnosti svojih dobročinitelja, toliko se više znaju uzobijestiti zbog toga. Pa ne samo da nastoje nanijeti zlo našim podanicima nego, nesposobni da obuzdaju bahatost, namještaju zamku i samim svojim dobročiniteljima. d Oni ne samo da iskorjenjuju osjećaj harnosti nego, zaneseni nadutošću onih koji ne znaju za dobro, umišljaju da će umaknuti Bogu koji sve vidi i pravdi koja mrzi zlo. e Često i mnogi od onih koji su na vlasti, kad upravu državnih poslova povjere prijateljima, pod njihovim utjecajem postanu sukrivci nevine krvi i zapletu se u nepopravljive nevolje: f smicalice,licemjerje i pokvarenosti izigraju čestitu dobronamjernost upravljača. g To se može vidjeti ne toliko iz starijih povijesti koje su do nas doprle: istražite samo kolike je zločine pred našim očima počinila opakost nedostojnih vladara. h Zato ćemo se ubuduće truditi da svim ljudima damo mirno i spokojno kraljevstvo. i Uvest ćemo promjene, a što nam se na uvid podastre prosuđivat ćemo s najdobrohotnijom susretljivošću. k Tako smo Hamana, sina Hamdatina, Makedonca, koji je doista stran krvi Perzijanaca i jako daleko od naše naklonosti, primili kao gosta, l a on se toliko okoristio dobrohotnošću koju gajimo prema svakom narodu da je bio nazvan našim ocem i bio poštovan od svih jer je zauzimao drugo mjesto, najbliže kraljevskom prijestolju. m Ali ne znajući obuzdati svoju oholost, smisli kako bi nas lišio kraljevstva i života, n tražeći da mnogovrsnim spletkama uništi Mordokaja, našeg spasitelja i trajnog dobročinitelja, i našu neporočnu družicu kraljevstva, Esteru, sa svim njihovim narodom. o Mislio je da će nas tako osamljene zaskočiti i prenijeti vlast Perzijanaca u ruke Makedonaca. p Ali smo mi utvrdili da Židovi koje je taj zlikovac naumio zatrti ne samo da nisu zlotvori nego su, upravljani najpravednijim zakonima, q sinovi Najvišega, Najvećega, živoga Boga koji čuva nama, kao i našim djedovima, carstvo u najboljem redu. r Učinit ćete, dakle, dobro ne budete li se poslužili pismima koja je uputio Haman, Hamdatov sin, jer je on, tvorac toga zločina, već obješen sa svom obitelji pred vratima Suze: Bog, koji vlada nad svime, smjesta mu je dosudio zasluženu kaznu. s Izloživši na svakom mjestu prijepis ove naredbe, pustite da se Židovi služe slobodno svojim zakonima. Pomognite im da uzmognu s uspjehom odbiti od sebe one koji bi ih napali u času nevolje trinaestoga dana dvanaestoga mjeseca, mjeseca Adara, jer je baš to dan t u koji je Bog, gospodar svega, izabranom narodu donio radost mjesto uništenja. u Zato i vi među svojim spomen-blagdanima svetkujte u svoj svečanosti ovaj osobiti dan da bi sada i ubuduće bio vama i Perzijancima dobre volje na spas, a našim neprijateljima spomen na propast. x Svaki grad ili uopće pokrajina koja se ovoga ne bude pridržavala bit će nesmiljeno kopljem i ognjem uništena: postat će ne samo ljudima nepristupačna nego i zvijerima i pticama zauvijek mrska.\"');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 8, 13, 'Prijepis pisma, koje je imalo postati zakonom u svakoj pokrajini, bijaše objavljen među svim narodima, kako bi Židovi toga dana bili spremni osvetiti se svojim neprijateljima.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 8, 14, 'Skoroteče, konjanici na kraljevskim pastusima, krenuše odmah i pojuriše, po kraljevoj zapovijedi. Naredba je bila objavljena i u tvrđavi Suzi.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 8, 15, 'Mordokaj izađe od kralja odjeven u grimiznu i lanenu kraljevsku haljinu, s velikom zlatnom krunom i s ogrtačem od fine tkanine i crvena skrleta. Grad je Suza klicao i veselio se.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 8, 16, 'Bio je to za Židove dan svjetla, veselja, kliktanja i slavlja.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 8, 17, 'U svakoj pokrajini, u svakom gradu i mjestu do kojega je dopro kraljev ukaz i zakon, zavlada među Židovima veselje, radost, gozba i blagdan, i mnogi među pucima zemlje postadoše Židovi jer ih je spopao strah od Židova.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 9, 1, 'Trinaestoga dana dvanaestog mjeseca, mjeseca Adara, kad je morala biti izvršena odredba kraljevog ukaza, istoga dana u koji su se neprijatelji Židova nadali zavladati nad njima dogodi se obrnuto: Židovi zavladaše nad neprijateljima svojim.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 9, 2, 'Židovi se sakupiše po svojim gradovima u svim pokrajinama kralja Ahasvera da udare na one koji su tražili njihovu propast. I nitko se nije usuđivao da im pruži otpor, jer je sve narode spopao strah od Židova.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 9, 3, 'Svi su knezovi pokrajina i namjesnici, upravljači i činovnici kraljevi štitili Židove jer ih je obuzeo strah od Mordokaja.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 9, 4, 'Jer je Mordokaj postao velik na kraljevskom dvoru, i po svim pokrajinama širio se glas da Mordokaj postaje sve moćniji.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 9, 5, 'Židovi, dakle, udariše mačem po svim svojim neprijateljima, sasjekoše ih i zatrše; sa svojim mrziteljima postupiše kako im se htjelo.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 9, 6, 'Samo u tvrđavi Suzi smakoše i zatrše Židovi pet stotina ljudi;');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 9, 7, 'pogubiše Paršandatu, Dalfona, Aspatu,');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 9, 8, 'Poratu, Adaliju, Aridatu,');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 9, 9, 'Parmaštu, Arisaja, Aridaja, Jezatu');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 9, 10, 'i deset sinova Hamana, sina Hamdatina, progonitelja Židova. Ali se ne pojagmiše za plijenom.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 9, 11, 'Toga istog dana, doznavši za broj ubijenih u tvrđavi Suzi,');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 9, 12, 'kralj reče kraljici Esteri: \"U tvrđavi Suzi Židovi su smaknuli i uništili pet stotina ljudi i deset Hamanovih sinova. Što su tek onda izveli u ostalim pokrajinama kraljevim? Koja je sada molba tvoja? Bit će uslišana! Koja je tvoja želja? Bit će ispunjena!\"');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 9, 13, '\"Ako je kralju po volji,\" reče Estera, \"neka se Židovima koji žive u Suzi dopusti još sutra primijeniti isti zakon kao i danas i neka se objesi deset Hamanovih sinova.\"');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 9, 14, 'Kralj naredi da se tako učini: zakon bi u Suzi proglašen i deset Hamanovih sinova obješeno.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 9, 15, 'Tako se Židovi Suze sakupiše i četrnaestoga dana mjeseca Adara pa pobiše u Suzi još tri stotine ljudi. Ali se ni tada ne pojagmiše za plijenom.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 9, 16, 'Ostali Židovi, oni koji su živjeli u kraljevskim pokrajinama, sakupiše se da brane svoje živote i mir od neprijatelja: pobiše sedamdeset i pet tisuća dušmana. Ali se ni tada ne pojagmiše za plijenom. Bio je trinaesti dan mjeseca Adara.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 9, 17, 'Četrnaestoga dana Židovi su mirovali: to bijaše dan gozbe i veselja.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 9, 18, 'Židovi u Suzi koji su se sakupili trinaestoga i četrnaestoga dana mirovahu petnaestoga dana; to je bio dan njihova veselja i gozbi.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 9, 19, 'Zbog toga Židovi pripoljci, oni koji žive po neutvrđenim selima, blagdanski svetkuju četrnaesti dan mjeseca Adara veseleći se i gozbujući i među sobom izmjenjujući darove. a A koji žive u gradovima slave i petnaesti dan Adara u razdraganosti i u veselju, izmjenjujući među sobom darove.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 9, 20, 'Mordokaj opisa te događaje i upravi pisma Židovima svih blizih i dalekih pokrajina kralja Ahasvera.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 9, 21, 'Naložio im je da četrnaesti i petnaesti dan mjeseca Adara svake godine slave');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 9, 22, 'kao dane u kojima su Židovi postigli spokoj od svojih neprijatelja i kao mjesec koji je bio pretvorio u radost njihovu tugu a u blagdan njihovo žalovanje. Neka ih slave gozbom i veseljem, izmjenjujući među sobom darove i dijeleći poklone ubogima.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 9, 23, 'Židovi prihvatiše da drže ono što su već sami od sebe počeli slaviti i o čemu im je pisao Mordokaj:');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 9, 24, '\"Haman, sin Hamdatin, Agađanin, progonitelj svih Židova, kako je bio naumio sve ih uništiti, baci \'Pur\', to jest ždrijeb, za njihovo smaknuće i zator;');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 9, 25, 'ali kad je za njegovu zamisao doznao kralj, on pismeno naredi: \'Neka se na njegovu glavu obori opaki naum što ga bijaše zasnovao protiv Židova i neka bude obješen, on i sinovi njegovi.\'\"');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 9, 26, 'Zbog toga su ti dani nazvani Purim, prema riječi Pur. Zato prema svem sadržaju toga pisma i prema onome što su vidjeli i što im bijaše preneseno');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 9, 27, 'Židovi se neopozivo obvezaše i prihvatiše za se, za svoje potomke i za sve one koji se s njima budu udružili da će svake godine slaviti ta dva dana prema tom propisu i u to vrijeme.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 9, 28, 'Te dane valja slaviti i njih se sjećati od pokoljenja do pokoljenja u svakoj obitelji, pokrajini i gradu; ti dani Purima ne smiju iščeznuti ispred Židova, ni spomen na njih biti izbrisan iz njihova roda.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 9, 29, 'Kraljica Estera, kći Abihailova, i Židov Mordokaj pisali su to što snažnije da tako još jednom potkrijepe pismo o Purimu.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 9, 30, 'Pisma su poslali svim Židovima u sto dvadeset i sedam pokrajina Ahasverova kraljevstva s porukom mira i vjernosti;');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 9, 31, 'da obdržavaju te dane Purima u njihovo određeno vrijeme, kako su to odredili Židov Mordokaj i kraljica Estera, i da drže post i molitve, onako kako su to oni obvezali sebe i svoje potomke.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 9, 32, 'Tako Esterina naredba ozakoni ove propise Purima i to bi zapisano u knjigu.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 10, 1, 'Kralj Ahasver udari danak na zemlju i na otoke morske.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 10, 2, 'Sva djela njegove moći i hrabrosti, a tako i izvještaj o uzdignuću Mordokaja koga je kralj uzvisio, zapisani su u Ljetopisima kraljeva Medije i Perzije:');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 10, 3, 'kako je Židov Mordokaj bio prvi iza kralja Ahasvera, velik u očima Židova, voljen od mnoštva svoje subraće kao pobornik blagostanja svoga naroda i glasnik mira za svoj rod. a Mordokaj uskliknu: \"Božje je to djelo! b Sjećam se, evo, sna koji sam o tom usnio - ništa nije ostalo neispunjeno: c malen izvor koji posta rijeka, svjetlo, sunce i voda u izobilju. Rijeka je Estera kojom se kralj oženio i učinio je kraljicom. d Dva zmaja, to smo ja i Haman. e Narodi, to su svi oni koji su se udružili da bi zatrli ime židovsko. f Moj narod, to je Izrael - oni koji podigoše svoj glas k Bogu i biše spašeni. DÓa, Gospod spasi svoj narod! Gospod nas oslobodi svih onih zala! Bog izvede znakove i čudesa kakvih nema među poganima! g Zato on baca dva ždrijeba: jedan za Božji puk, drugi za sve ostale narode. h I oba ova ždrijeba izađoše u čas, vrijeme i dan koji je dosudio Bog za sve narode. i Sjetio se Bog naroda svoga i dosudio pravdu baštini svojoj. k I bit će im - narodu njegovu Izraelu - ovi dani mjeseca Adara, to jest četrnaesti i petnaesti, dani okupljanja, radosti i veselja pred Bogom za pokoljenja dovijeka.\" l Četvrte godine kraljevanja Ptolemejeva i Kleopatrina, Dositej, koji se kazao kao svećenik i levit, i njegov sin Ptolemej doniješe ovo pismo o Purimu, tvrdeći da je vjerodostojno i da ga je preveo Lizimah, sin Ptolemejev, iz Jeruzalema.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 1, 1, 'Aleksandar Makedonac, sin Filipov - tada već gospodar Grčke - provali iz zemlje Kitima i potuče Darija, kralja perzijskog i medijskog, i zakralji se namjesto njega.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 1, 2, 'Povede mnoge ratove, zauze tvrđave i poubija kraljeve zemlje.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 1, 3, 'Dopro je do nakraj svijeta i poplijenio mnoge narode. Sva zemlja pred njim umuknu, a srce se njegovo uznese i uzoholi.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 1, 4, 'Sakupi silnu vojsku, podloži svojoj vlasti krajeve, narode i vladare da mu plaćaju danak.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 1, 5, 'Konačno pade u postelju i uvidje da mu je umrijeti.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 1, 6, 'Sazva svoje službenike, odličnike koji su s njim rasli od mladosti, i još za života razdijeli im svoje kraljevstvo.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 1, 7, 'Tako, pošto je kraljevao dvanaest godina, Aleksandar umrije.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 1, 8, 'A njegovi časnici preuzeše vlast, svaki na svome području.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 1, 9, 'Svi se oni poslije njegove smrti okruniše, a tako nakon njih i njihovi sinovi. Tako se godine i godine množilo zlo na zemlji.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 1, 10, 'Od njih dođe grešni izdanak Antioh Epifan, sin kralja Antioha, koji bijaše talac u Rimu. On se zakralji godine sto trideset i sedme kraljevstva grčkoga.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 1, 11, 'U one dane nađoše se u Izraelu ljudi opaki koji stadoše uvjeravati mnoge: \"Hajde da sklopimo savez s narodima svojim susjedima, jer otkako se od njih odijelismo, snađoše nas mnoga zla.\"');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 1, 12, 'I mnogima se to svidjelo.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 1, 13, 'Štoviše, požuriše se neki od naroda i odoše kralju, koji im dopusti da se povedu za poganskim običajima.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 1, 14, 'I sagradiše u Jeruzalemu borilište, kako to običavaju pogani,');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 1, 15, 'prepraviše svoje obrezanje i otpadoše od svetog Saveza. Ujarmiše se s poganima i prodaše se da čine zlo.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 1, 16, 'Kad je Antioh učvrstio svoju vlast, poduze da svom kraljevstvu podvrgne Egipat pa da kraljuje dvama kraljevstvima.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 1, 17, 'Provali u Egipat sa silnom vojskom, s bojnim kolima i slonovima, s konjicom i velikim brodovljem.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 1, 18, 'I zametne rat protiv Ptolemeja, kralja egipatskog, koji pred njim uzmače i pobježe. Padoše mnogi nasmrt ranjeni.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 1, 19, 'I tako oni zagospodariše egipatskim utvrđenim gradovima i poplijeniše Egipat.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 1, 20, 'A pošto je potukao Egipat, Antioh se godine sto četrdeset i treće vrati i krene protiv Izraela. Uziđe na Jeruzalem sa silnom vojskom.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 1, 21, 'Drsko prodre u Svetište i zaplijeni zlatni kadioni žrtvenik, svijećnjak sa svim, priborom,');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 1, 22, 'stol za prinošenje hljebova, sudove za žrtve ljevanice, kaleže, zlatne kadionice, zavjese, vijence i sav zlatni ures na pročelju Hrama, koje ogoli.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 1, 23, 'Zaplijenio je sve srebro i zlato, oteo dragocjeno posuđe i opljačkao tajne riznice koje je mogao pronaći.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 1, 24, 'Oplijenivši sve to, vratio se u svoju zemlju, pošto je izvršio pokolj i izgovorio silno bogohulstvo.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 1, 25, 'U Izraelu nasta opća tuga po svim mjestima.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 1, 26, 'Zastenjaše poglavari i starješine, obnemogoše mladići i djevojke - ljepota ženska sva uvenu.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 1, 27, 'Mladoženje udariše u tužaljke; a nevjeste po ložnicama prokukaše.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 1, 28, 'Sva se zemlja tresla od žalosti nad svojim stanovnicima, sav se dom Jakovljev obukao u sramotu.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 1, 29, 'Nakon dvije godine posla kralj u gradove judejske nadglednika poreza, koji dođe u Jeruzalem s jakom vojskom.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 1, 30, 'Najprije im je lukavo govorio o miru, i oni mu povjerovaše. Zatim iznenada navali na grad, potuče ga teškim udarcima i pogubi mnoštvo Izraelaca.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 1, 31, 'Opljačka grad, zapali ga vatrom i sruši mu kuće i zid unaokolo.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 1, 32, 'Žene i djecu učiniše sebi robljem i porazdijeliše među sobom stoku.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 1, 33, 'Zatim su obzidali Davidov grad velikim i jakim zidom, s gordim kulama, i tako im postade utvrdom.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 1, 34, 'Ondje smjestiše opaki ološ, ljude protivne Zakonu, koji se tu osiliše.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 1, 35, 'Nagomilaše tu oružja i hrane i pohraniše plijen koji poplijeniše u Jeruzalemu. I tako se tu stvorilo neprijateljsko gnijezdo.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 1, 36, 'Postade to zasjeda Svetištu, za sve vrijeme opak protivnik Izraelu.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 1, 37, 'Proliše krv nevinu naokolo Svetišta i oskvrnuše sveto mjesto.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 1, 38, 'Zbog njih pobjegoše žitelji jeruzalemski i grad postade naselje stranaca. Jeruzalem postade tuđina porodu svome, i djeca ga njegova napustiše.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 1, 39, 'Svetište njegovo opustje k\'o pustinja, blagdani mu se okrenuše u žalovanje, subote u porugu, a slava njegova u ništavilo.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 1, 40, 'K\'o nekoć slava njegova, namnožila mu se sramota, i sav se ponos njegov okrenu u tugovanje.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 1, 41, 'I napisa kralj proglas svemu svom kraljevstvu da svi moraju postati jedan narod i svaki mora ostaviti svoje običaje.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 1, 42, 'I svi se narodi pokoriše kraljevoj naredbi.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 1, 43, 'I mnogi Izraelci prihvatiše njegovo bogoštovlje i počeše žrtvovati idolima i ne svetkovati subotu.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 1, 44, 'A kralj posla u Jeruzalem, i u ostale judejske gradove, poslanice po glasnicima da se svi imaju povesti za običajima tuđinaca koji su u zemlji,');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 1, 45, 'pa da se u Hramu dokinu paljenice, klanice i ljevanice; da se više ne svetkuju subote i blagdani;');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 1, 46, 'da se onečisti Svetište i sveti narod;');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 1, 47, 'da se podignu oltari, sveti gajevi i idoli pa da im se žrtvuju svinje i nečiste životinje;');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 1, 48, 'da se više ne obrezuju djeca, da se onečiste svakom nečistoćom i gnusobom');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 1, 49, 'i tako zaborave Zakon i izmijene sve običaje.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 1, 50, 'Tko se ne pokori kraljevoj naredbi, osuđen je na smrt.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 1, 51, 'Kralj je svem kraljevstvu napisao proglase takva sadržaja i postavio je nadglednike nad svim narodom da se to provede. Svim je judejskim gradovima, svakomu napose, zapovjedio da prinose žrtve.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 1, 52, 'I pridružiše im se mnogi od naroda, svi oni koji su otpali od Zakona, i zla velika učiniše u zemlji.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 1, 53, 'Takvi primoraše Izraela da se skriva u svakojakim zbježištima.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 1, 54, 'Petnaestoga dana mjeseca Kisleva, godine sto četrdeset i pete, sagradio je kralj na oltaru za žrtve paljenice Grozotu pustoši. I u susjednim judejskim gradovima podigoše žrtvenike.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 1, 55, 'I palili su tamjan na vratima kuća i po trgovima.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 1, 56, 'A u koga nađoše knjige Zakona, razderaše ih i baciše u vatru.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 1, 57, 'Ako bi otkrili da tko čuva svitak knjige Saveza ili da pristaje uza Zakon, po kraljevoj je odluci bio ubijen.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 1, 58, 'Takvo nasilje provodili su mjesec za mjesecom nad Izraelom, nad svakim koga bi po gradovima otkrili.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 1, 59, 'Dvadeset i petoga u mjesecu prinosili su žrtve na žrtveniku podignutu na oltaru za paljenice.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 1, 60, 'Po toj zapovijedi pogubljivali su žene koje su dale obrezati svoju djecu;');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 1, 61, 'objesili bi im o vrat dojenčad i smaknuli ih zajedno sa svim njihovim domom i s onima koji su izvršili obrezanje.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 1, 62, 'Uza sve to, mnogi od Izraela ostadoše postojani i pokazaše se hrabri te nisu jeli od nečistih jela.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 1, 63, 'Radije su išli u smrt nego da se onečiste hranom ili da oskvrnu sveti Savez. I tako su umirali.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 1, 64, 'Uistinu, strašan gnjev bijaše nad Izraelom.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 2, 1, 'U one dane Matatija, sin Ivana Šimunova, svećenik iz koljena Joaribova, ode iz Jeruzalema i udari sjedište u Modinu.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 2, 2, 'A imao je pet sinova: Ivana prozvana Gadi,');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 2, 3, 'Šimuna prozvana Tasi,');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 2, 4, 'Judu prozvana Makabej,');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 2, 5, 'Eleazara prozvana Avaran, Jonatu prozvana Afus.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 2, 6, 'Videći kakva se bogohulstva zbivaju u Judeji i u Jeruzalemu, Matatija');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 2, 7, 'zavapi: \"Jao, zar se zato rodih da gledam zator svog naroda i zator Svetoga grada pa da besposlen sjedim dok nam ga predaju u ruke neprijatelja - Svetište naše u ruke tuđinaca?');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 2, 8, 'Svetište njegovo postade k\'o čovjek bez časti,');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 2, 9, 'posuđe, slava njegova, za plijen opljačkano; nejačad njegova po trgovima poklana, mladići njegovi hrana oštrim mačevima!');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 2, 10, 'Ima li naroda kojemu ne pripade dio našega kraljevstva, koji ne prigrabi sebi plijena našega?!');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 2, 11, 'Sav mu je nakit otet, slobodu zamijeni s ropstvom.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 2, 12, 'Gle, Svetište naše - ljepota i slava naša - opustje, oskvrnuše ga pogani!');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 2, 13, 'Čemu nam život?\"');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 2, 14, 'I razdrije Matatija i njegovi sinovi svoju odjeću, navukoše kostrijet i proplakaše gorko.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 2, 15, 'Uto kraljevi ljudi, poslani da sile na otpad, dođoše u Modin da prinude na žrtvovanje.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 2, 16, 'Mnogi su od Izraela prišli k njima. Ali Matatija i njegovi sinovi ostadoše postojani.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 2, 17, 'Kraljevi ljudi priđu Matatiji i stanu ga nagovarati: \"Ti si čovjek ugledan u ovom gradu, častan i utjecajan; uz tebe su tvoji sinovi i braća.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 2, 18, 'Priđi dakle prvi i izvrši zapovijed kraljevu, kao što to učiniše drugi narodi, ostali Judejci i preostalo stanovništvo Jeruzalema, pa ćeš i ti i tvoji sinovi ući u krug kraljevih prijatelja i bit ćete čašćeni srebrom i zlatom i mnogim darovima.\"');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 2, 19, 'Matatija im jakim glasom odgovori: \"Neka se i svi narodi pod kraljevom vlašću njemu pokore tako te svaki od njih odstupi od bogoštovlja svojih predaka i privoli njegovim naredbama,');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 2, 20, 'ja i moji sinovi i sva braća moja slijedit ćemo Savez otaca svojih.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 2, 21, 'Ne dalo Nebo da ostavimo Zakon i zapovijedi.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 2, 22, 'I zato ne možemo poslušati kraljevih naloga da prestupimo svoje bogoštovlje ni udesno ni ulijevo.\"');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 2, 23, 'Tek što je on to kazao, a Židov neki priđe pred očima sviju da prema kraljevoj zapovijedi žrtvuje na žrtveniku u Modinu.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 2, 24, 'Vidje to Matatija, razgnjevi se i srce mu zadrhta, obuzet pravednim gnjevom, potrči i zakla ga na žrtveniku.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 2, 25, 'U isti čas ubi i kraljeva čovjeka koji je silio na žrtvovanje i obori žrtvenik.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 2, 26, 'Tako provali njegova gorljivost za Zakon kao nekoć Pinhasova protiv Zimrija, sina Šalumova.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 2, 27, 'Matatija tada stade vikati gradom iza glasa: \"Svaki koji gori ljubavlju za Zakon i stoji uza Savez, neka ide za mnom.\"');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 2, 28, 'I pobjegoše u gore on i njegovi sinovi, ostavivši u gradu sve svoje.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 2, 29, 'Mnogi tada kojima je bilo stalo do pravednosti i do pravde pobjegoše u pustinju');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 2, 30, 'sa svojom djecom i ženama i sa svom stokom, jer se zlo oborilo na njih.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 2, 31, 'I bi javljeno kraljevim ljudima i posadi koja bijaše u Jeruzalemu, u Davidovu gradu, da su ljudi koji su prekršili kraljevu zapovijed odbjegli u pustinjska skrovišta.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 2, 32, 'Jaka vojska dade se za njima u potjeru i stiže ih. Svrstaše se protiv njih, spremni da zametnu s njima bitku u dan subotnji.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 2, 33, 'I poručiše im: \"Dosta je! Iziđite, pokorite se kraljevu nalogu da spasite život!\"');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 2, 34, 'Ali im oni odgovoriše: \"Ne izlazimo i nećemo se pokoriti kraljevu nalogu da skvrnemo dan subotnji.\"');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 2, 35, 'Napadoše ih bez oklijevanja.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 2, 36, 'A oni im nisu uzvraćali: ni da bi se kamenom na njih nabacili, a kamoli da se utvrde u svojim skrovištima.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 2, 37, '\"Umrimo svi,\" govorahu, \"u svojoj nedužnosti. Svjedoče nam nebo i zemlja da nas ubijate nepravedno.\"');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 2, 38, 'I zagna se vojska na njih u samu subotu te izginuše svi oni sa svojom djecom i ženama i stokom - oko tisuću duša.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 2, 39, 'Doznaše za to Matatija i njegove pristalice i proplakaše gorko:');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 2, 40, '\"Ako učinimo svi mi tako\", rekoše jedan drugomu, \"kao ova naša braća, i ne pođemo u boj protiv pogana za svoj život i za svoje svetinje, ubrzo će nas istrijebiti sa zemlje.\"');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 2, 41, 'I tako toga dana donesoše odluku: \"Tko god nas napadne u dan subotnji, vojevat ćemo protiv njega da svi ne izginemo kao što izgiboše braća naša u zbjegovima.\"');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 2, 42, 'Pridružila im se i zajednica Hasidejaca, poizbor junaka u Izraelu, sve ljudi odanih Zakonu.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 2, 43, 'I svi drugi koji su bježali od progonstva pridruživali se njima, i tako im je raslo pojačanje.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 2, 44, 'Prikupila se tako cijela vojska te su udarali u svom gnjevu na krivce i u svojoj srdžbi na bezakonike. Ostali se razbježaše - da se spase - po poganskim zemljama.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 2, 45, 'A Matatija i njegove pristalice stanu obilaziti i razvaljivati žrtvenike.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 2, 46, 'Silom su obrezivali neobrezane dječake koje bi našli na području Izraela.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 2, 47, 'Progonili su drske tuđince. I pothvat im je uspijevao.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 2, 48, 'Zaštitili su tako Zakon od ruku pogana i kraljeva i ne dadoše da osili sila grešnička.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 2, 49, 'A kada se Matatijini dani primicahu kraju, reče on svojim sinovima: \"U ovo vrijeme, gle, osilila se drskost i pogrda; nastalo je doba razora i ljutog gnjeva.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 2, 50, 'Djeco moja! Gorljivo se zauzmite za Zakon i život svoj izložite za Savez naših otaca.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 2, 51, 'Spominjite se djela što ih oci naši izvršiše u svoje vrijeme. Steći ćete tako slavu veliku, bit će vam besmrtno ime.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 2, 52, 'Nije li se Abraham vjeran pokazao u kušnji i nije li mu to uzeto u pravednost?');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 2, 53, 'A Josip je u svojoj nevolji očuvao zapovijed i postao gospodar Egipta.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 2, 54, 'Pinhas, otac naš, nosio se gorljivošću i primio je obećanje vječnog svećeništva.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 2, 55, 'Jošua je ispunio nalog i postao sucem Izraela.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 2, 56, 'Kaleb je u zboru bio svjedok istini i zato mu pripade baština u zemlji.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 2, 57, 'Davidu, jer bijaše pobožan, kraljevsko je prijestolje zauvijek dano u baštinu.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 2, 58, 'Ilija, jer bijaše gorljiv borac Zakona, bi uznesen na nebo.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 2, 59, 'Hananija, Azarja i Mišael vjerom se spasiše iz plamena.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 2, 60, 'Daniel zbog svoje nedužnosti bi izbavljen iz lavljih ralja.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 2, 61, 'Razmotrite i vidite iz koljena u koljeno: svi koji se u nj uzdaše ne poklekoše nikada.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 2, 62, 'Ne strašite se prijetnja grešnikovih, jer slava bezbožnikova za gnojište je i za hranu crvima.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 2, 63, 'Danas se visoko diže, sutra ga već naći ne možeš: u prah svoj se vratio, propale mu osnove.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 2, 64, 'Junaci mi, djeco, budite; Zakona se čvrsto držite da se u njem proslavite.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 2, 65, 'Evo vam Šimuna, brata vašega: znam ga, čovjek je razuman; slušajte ga uvijek, on će vam biti otac!');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 2, 66, 'Juda Makabej, poizbor junak od svoje mladosti, bit će vam vojskovođa i zapovijedat će u ratu protiv pogana.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 2, 67, 'Skupite oko sebe sve koji vrše Zakon i osvetite svoj narod.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 2, 68, 'Milo za drago vratite poganima i držite se propisa Zakona.\"');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 2, 69, 'Tada ih Matatija blagoslovi i bi pridružen svojim ocima.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 2, 70, 'Umro je u godini sto četrdeset i šestoj; sahraniše ga u grobnici otaca njegovih u Modinu. Oplakao ga je sav Izrael. Ę(166.-160. prije Krista)');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 3, 1, 'Matatiju je naslijedio sin njegov Juda Makabej.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 3, 2, 'Podupriješe ga sva njegova braća i sve pristalice njegova oca i oduševljeno povedoše rat Izraelov.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 3, 3, 'On proširi nadaleko slavu svoga naroda. Poput diva on se u oklop obukao, bojno oružje sebi pripasao. Mnoge je bojeve zametnuo, oštrim mačem tabor štiteći.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 3, 4, 'Premac lavu svojim djelima, postade k\'o lavić što za plijenom riče.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 3, 5, 'Gonio je otpadnike, trag im njušeći; palio je tlačitelje svoga naroda.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 3, 6, 'Od straha pred njim dah im prestajao, bezakonici pred njim drhtahu. Spasenje se ruci njegovoj posrećilo.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 3, 7, 'Mnogog kralja on je ojadio, a Jakova djelima obradovao. Dok je vijeka blagoslivljat će se uspomena njegova.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 3, 8, 'Obilazio gradovima Jude da istrijebi iz njih bezbožnike, od Izraela srdžbu da odvrati.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 3, 9, 'Do krajeva zemlje ime mu doprlo, oko sebe sabra raspršene.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 3, 10, 'Apolonije sabra pogane i velika vojska krenu iz Samarije da zavojšti na Izraela.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 3, 11, 'Saznao za to Juda, pa ga presrete, potuče ga i ubi. Mnogi nasmrt ranjeni pogiboše, a ostali pobjegoše.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 3, 12, 'Oplijeniše ih, a Juda sebi prisvoji mač Apolonijev i nosio ga je u boju svega svog života.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 3, 13, 'Kad je Seron, sirski vojvoda, čuo da je Juda skupio oko sebe ljude, zbor vjernih, spremnih da svaki čas krenu u rat,');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 3, 14, 'reče: \"Steći ću ime i proslavit ću se u kraljevstvu ako se zaratim s Judom i sa svima njegovima koji preziru kraljevu riječ.\"');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 3, 15, 'I krenu i uzađe s njim snažna vojska bezbožnika da ga potpomognu i da se osvete sinovima Izraelovim.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 3, 16, 'Dok je uzlazio uza strmen Bet Horona, ispriječi mu se Juda sa šakom ljudi.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 3, 17, 'Kad ovi ugledaju vojsku koja je izlazila na njih, rekoše Judi: \"Kako će se oduprijeti nas šačica tome silnom mnoštvu? K tome smo obnemogli, cio dan bez hrane.\"');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 3, 18, 'A Juda im odgovori: \"Lako se može dogoditi da i šačica ljudi ukliješti mnoštvo. A Nebu je svejedno izvojevati spasenje s mnogima ili sa šačicom.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 3, 19, 'Pobjeda u ratu ne zavisi od jačine vojske, jer nam od Neba dolazi jakost.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 3, 20, 'Ovi izlaze na nas u premoći drskosti i bezakonja, da istrijebe nas i naše žene i djecu našu i da nas oplijene,');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 3, 21, 'a mi vojujemo za goli život i za svoje svete uredbe.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 3, 22, 'Zato će ih Gospod pred našim očima satrti, i ništa se ne bojte.\"');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 3, 23, 'Tako reče i obori se iznenada na njih i razbi Serona i svu njegovu vojsku.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 3, 24, 'Naže za njima niz kosinu Bet Horona sve do ravnice. Pade ih kakvih osam stotina ljudi, a ostali pobjegoše u Filisteju.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 3, 25, 'I zavlada strah pred Judom i braćom njegovom i obuze prepast sve okolne narode.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 3, 26, 'Do kralja doprije ime njegovo i po svim se narodima pripovijedalo o Judinim djelima.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 3, 27, 'Kad je sve to čuo kralj Antioh, planu on gnjevom i posla da se skupe sve snage njegova kraljevstva - vojska silna.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 3, 28, 'Otvori svoje riznice i isplati vojsku za godinu dana i naredi da bude spremna za svaku priliku.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 3, 29, 'Uto opazi da presušuje blago u njegovim riznicama i da su mu državni dohoci sve manji zbog razdora i udaraca kojima je izmučio zemlju zatirući zakone koji postojahu odiskona.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 3, 30, 'Poboja se dakle da neće, kako je već bivalo, imati odakle podmiriti troškove i smoći darove što ih je prije dijelio podašnom rukom, premašujući u tom svoje prethodnike.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 3, 31, 'U toj je tjeskobi odluči poći na Perziju da prigrabi danak od zemalja i da tako namakne mnogo novca.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 3, 32, 'Ostavi Liziju, čovjeka ugledna, kraljevskog roda, da vodi državne poslove od Eufrata pa do egipatske granice.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 3, 33, 'I povjeri mu skrbništvo nad svojim sinom Antiohom sve dok se on ne vrati.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 3, 34, 'Preda mu polovicu svoje vojske s bojnim slonovima i dade mu naredbe o svemu što je naumio, osobito o stanovnicima Judeje i Jeruzalema:');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 3, 35, 'da se pošalje na njih vojska, da se satre i istrijebi snaga Izraelova i preostatak Jeruzalema, pa da se izbriše i spomen na to mjesto,');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 3, 36, 'a onda da se na svem onom području nasele tuđinci i njima da se razdijeli njihova zemlja.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 3, 37, 'Tada kralj povede sa sobom ostalu polovicu vojske i krenu iz Antiohije, prijestolnice svoga kraljevstva, godine sto četrdeset i sedme. Prijeđe preko Eufrata i poče se probijati kroz gornje krajeve.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 3, 38, 'Lizija je izabrao Ptolemeja, sina Dorimenova, Nikanora i Gorgiju, muževe junačne, prijatelje kraljeve.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 3, 39, 'S njima posla četrdeset tisuća pješaka i sedam tisuća konjanika da navale na Judeju i da je opustoše po zapovijedi kraljevoj.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 3, 40, 'I pokrenu se sva ta vojska, stiže do Emausa i utabori se ondje u nizini.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 3, 41, 'Kad se o tome pročulo među trgovcima u onomu kraju, uzeše oni mnogo srebra i zlata i okova te dođoše u tabor da Izraelce pokupuju kao roblje. A zavojevačima se pridružila vojska iz Sirije i drugih zemalja.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 3, 42, 'Juda pak i njegova braća vidješe da se množe zla i da su se vojske utaborile na njihovu području, a saznali su i za kraljeve naredbe da im se narod zatre i uništi.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 3, 43, 'Rekoše tada jedni drugima: \"Podignimo narod svoj od propasti i pođimo u rat za narod svoj i za svetinje svoje!\"');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 3, 44, 'I sazvaše sav zbor da se svi spreme za boj i da se pomole i vapiju za milost i milosrđe.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 3, 45, 'Opustje Jeruzalem kao pustinja. Ne bijaše nikog od sve djece njegove da uđe ili da iziđe. Po Svetištu se gazilo, u Tvrđavi se nastaniše stranci, poganima posta svratište. Jakovu je radost iščezla, umuknula mu frula i citara.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 3, 46, 'Izraelci se sastadoše u Masfi, pred Jeruzalemom, jer je nekoć Izrael u Masfi imao molitveno mjesto.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 3, 47, 'Postili su toga dana i obukli se u kostrijet, posuli glavu pepelom i razderali svoje haljine.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 3, 48, 'Razvili su knjigu Zakona da potraže u njoj ono što inače pogani traže od svojih idola.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 3, 49, 'Iznesoše svećeničku odjeću i prvine i desetine i pozvaše nazirejce koji su ispunili razdoblje svoga zavjeta.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 3, 50, 'I zavapiše tada jakim glasom k Nebu: \"Što da sada učinimo sa svim ovim i kamo da ove smjestimo?');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 3, 51, 'Svetište se tvoje gazi i skvrni, svećenstvo je tvoje tužno, poniženo.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 3, 52, 'Pogani se, evo, udružiše protiv nas da nas istrijebe. Ti jedini znadeš što nam spremaju.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 3, 53, 'Kako ćemo im odoljeti ako nam ti ne pritečeš u pomoć?\"');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 3, 54, 'I zatrubiše nato u trublje i povikaše iz sveg glasa.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 3, 55, 'Juda tada postavi narodu starješine: tisućnike, stotnike, pedesetnike i desetnike.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 3, 56, 'Onima pak koji su baš gradili kuću, ili su se tek oženili, ili su sadili vinograd, ili bijahu strašljivice, naredi da se svaki takav, kako i Zakon zapovijeda, vrati kući.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 3, 57, 'I vojska krenu i utabori se južno od Emausa.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 3, 58, 'Juda izda zapovijed: \"Opašite se i budite junaci! Spremni stojte ranom zorom za boj protiv pogana koji se, eto, udružiše da istrijebe nas i naše svetinje.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 3, 59, 'Bolje nam je u boju izginuti nego da gledamo zlo svog naroda i svojih svetinja.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 3, 60, 'Bit će onako kako Nebo hoće.\"');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 4, 1, 'Gorgija povede sa sobom pet tisuća pješaka i tisuću poizbor konjanika; ta je vojska krenula noću');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 4, 2, 'da izvrši prepad na židovski tabor i da ga iznenadi: vodiči joj bijahu stanovnici Tvrđe.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 4, 3, 'Kad je to dočuo Juda, podigao se i on sa svojim junacima da na kraljevu vojsku, koja je bila u Emausu, udari');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 4, 4, 'dok su joj pripadnici još izvan tabora.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 4, 5, 'Gorgija je pak došao noću u Judin tabor i nije našao nikoga, pa je zato stao Židove tražiti po gorama, jer, kako je rekao, \"oni bježe pred nama\".');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 4, 6, 'U cik zore pojavi se Juda u ravnici sa samo tri tisuće ljudi. Ti nisu imali prikladna obrambenog oružja ni mačeva.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 4, 7, 'Vidjeli su poganski tabor, jak i utvrđen: opkoljavali ga konjanici, ljudi vični boju.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 4, 8, 'Juda reče svojim ljudima: \"Ne bojte se toga mnoštva i ne plašite se njihovih napadaja.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 4, 9, 'Sjetite se da su se naši oci spasili na Crvenom moru kad ih je progonio faraon s vojskom.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 4, 10, 'Zavapimo sada k Nebu: ono će nam se možda smilovati, sjetit će se svog Saveza s našim ocima, pa će danas pred nama tu vojsku satrti.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 4, 11, 'Tada će svi narodi spoznati da postoji Netko tko izbavlja i spasava Izraela.\"');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 4, 12, 'Stranci podigoše oči: opazivši kako im Židovi dolaze s protivne strane,');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 4, 13, 'iziđoše iz tabora da prihvate bitku. Judini vojnici zatrubiše u trube i zametnuše boj.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 4, 14, 'Razbijeni, pogani nagnuše u bijeg prema ravnici.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 4, 15, 'Ali svi na zalaznici padoše od mača. Ostale pognaše sve do Gezera i do nizina Idumeje, do Azota i do Jamnije: palo je oko tri tisuće ljudi.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 4, 16, 'Kad se Juda vratio s potjere kojoj bijaše na čelu,');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 4, 17, 'reče narodu: \"Ne lakomite se na plijen jer nam prijeti još jedan rat.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 4, 18, 'Gorgija je sa svojom vojskom tu u gori. Sad se oduprite našim neprijateljima, borite se protiv njih; potom ćete bez brige pokupiti plijen.\"');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 4, 19, 'Juda je još bio u riječi kadli jedan odred proviri s gorskog visa.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 4, 20, 'Vidješe da su njihovi raspršeni i da je tabor izgorio: o tome je još svjedočio dim koji se vidio.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 4, 21, 'Od toga se prizora prestraviše. A kad su još na ravnici opazili Judinu vojsku spremnu za boj,');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 4, 22, 'svi pobjegoše u filistejsku zemlju.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 4, 23, 'Juda se vratio da im oplijeni tabor. Iznijelo se mnogo zlata, srebra, modra i crvena skrletna platna i golemo drugo blago.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 4, 24, 'Na povratku su Židovi hvalili i blagoslivljali Nebo govoreći: \"Ono je dobro i njegova je ljubav vječna!\"');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 4, 25, 'Bijaše to dan velike izraelske pobjede.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 4, 26, 'Oni pak od neprijatelja koji bijahu utekli dođoše k Liziji i javiše mu sve što se dogodilo.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 4, 27, 'Ta ga vijest smete, duh mu klonu, jer se Izraelu nije dogodilo onako kako je on htio niti je bilo onako kako je zapovjedio kralj.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 4, 28, 'Zato je iduće godine Lizija sabrao šezdeset tisuća poizbor pješaka i pet tisuća konjanika da svlada Židove.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 4, 29, 'Došli su u Idumeju i utaborili se u Betsuru. Juda iziđe protiv njih sa deset tisuća ljudi.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 4, 30, 'Kad vidje tu silnu vojsku, pomoli se ovako: \"Blagoslovljen da si, spasitelju Izraela, ti koji si satro juriš diva rukom svoga sluge Davida i koji si filistejsku vojsku predao u ruke Šaulova sina Jonate i njegova štitonoše.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 4, 31, 'Predaj i ovu vojsku u šake Izraela, svog naroda; neka se osramote i pješaci i konjanici.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 4, 32, 'Posij strah u njihovim redovima, uništi uzdanje koje imaju u svoju silu i neka se pokolebaju svojim porazom.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 4, 33, 'Obori ih mačem onih koji te ljube, da te hvale pjesmama svi oni koji ti poznaju Ime!\"');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 4, 34, 'I počeše bitku i u srazu prsa o prsa pade iz Lizijine vojske oko pet tisuća ljudi.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 4, 35, 'Videći kako mu se osula vojska i kako su neustrašivi Judini junaci, koji su bili spremni junački živjeti ili umrijeti, Lizija se vrati u Antiohiju. Ondje unovači najamnike da iznova, s pojačanom vojskom, provali u Judeju.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 4, 36, 'Juda pak i njegova braća rekoše: \"Eto, naši su neprijatelji satrti, hajde da očistimo Svetište i posvetimo ga.\"');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 4, 37, 'Sabra se sva vojska i pope se na goru Sion.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 4, 38, 'Vidjeli su ondje opustjelo sveto mjesto, oskvrnjen oltar, spaljena vrata, u predvorjima naraslo šikarje kao u šumi ili u gorama, a ćelije porušene.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 4, 39, 'Razdrli su na sebi odjeću, zakukali i glavu posuli pepelom.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 4, 40, 'Potom padoše ničice pa na znak truba zavapiše k Nebu.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 4, 41, 'Juda naloži ljudima da tuku one koji su bili u Tvrđi sve dok on Svetište ne očisti.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 4, 42, 'Zatim je izabrao svećenike neokaljane, vjerne Zakonu.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 4, 43, 'Očistiše oni Svetište, a oskvrnjeno kamenje ukloniše na nečisto mjesto.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 4, 44, 'Potom se vijećalo što da se učini od žrtvenika za paljenice, koji je bio oskvrnjen.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 4, 45, 'Dođoše na dobru misao da ga uklone, bojeći se da im ne bude na sramotu, jer su ga pogani oskvrnuli. I oboriše žrtvenik.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 4, 46, 'Kamenje staviše na prikladno mjesto na hramskoj gori, dok ne dođe prorok koji će o njem odlučiti.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 4, 47, 'Nato, prema Zakonu, uzeše neklesano kamenje i podigoše nov žrtvenik, po uzoru na prijašnji.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 4, 48, 'Popravili su Svetište i unutrašnjost Doma i posvetili predvorje.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 4, 49, 'Pošto su načinili novo sveto posuđe, unijeli su u Hram svijećnjak, kadioni žrtvenik i stol.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 4, 50, 'Kadili su tamjan na žrtveniku i zapalili svjetiljke na svijećnjaku koje su rasvijetlile unutrašnjost Hrama.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 4, 51, 'Postavili su hljebove na stol i objesili zastore. Tako dovršiše djelo koje su poduzeli.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 4, 52, 'Dvadeset i petog dana devetog mjeseca, zvanog Kislev, godine sto četrdeset i osme ustadoše u rano jutro');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 4, 53, 'i prinesoše po Zakonu žrtvu na novom žrtveniku za paljenice koji bijahu podigli.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 4, 54, 'Obnovili su posvetu žrtvenika uz pjesme i zvuke citara, harfa i cimbala u ono isto doba i u isti dan u koji su ga pogani oskvrnuli.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 4, 55, 'Sav je narod pao ničice i poklonio se, a zatim upravio hvalu Nebu, onomu koji ih je tako sretno vodio.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 4, 56, 'Osam su dana slavili posvetu žrtvenika i radosno prinosili paljenice i žrtve pričesnice i zahvalnice.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 4, 57, 'Uresili su pročelje Hrama zlatnim vijencima i štitovima, obnovili ulaz i ćelije i postavili im vrata.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 4, 58, 'Nastala je velika radost u narodu i izbrisala se sramota koju su nanijeli pogani.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 4, 59, 'Juda je sa svojom braćom i sa svom izraelskom zajednicom odredio da se, počevši od dvadeset i petog dana mjeseca Kisleva, svake godine u svoje vrijeme osam dana radosno i veselo slavi dan posvete žrtvenika.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 4, 60, 'U to su vrijeme oko gore Siona sagradili visoke zidove s jakim kulama, bojeći se da pogani ne dođu ta mjesta oskvrnuti kao i prije.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 4, 61, 'Juda je ondje smjestio posadu da čuva goru Sion. Utvrdio je Betsur da narod ima tvrđu protiv Idumeje.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 5, 1, 'Kad su okolni narodi čuli da je žrtvenik ponovo sagrađen a Svetište uspostavljeno kao i prije, vrlo se razgnjeviše');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 5, 2, 'i naumiše istrijebiti Jakovljevo pokoljenje što je živjelo među njima; počeli su ubijati i progoniti taj narod.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 5, 3, 'Juda zavojeva na Ezavove sinove u Idumeji, na zemlju Akrabatenu, jer su opsjedali Izraelce. Žestoko ih je porazio, ponizio i dočepao se plijena.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 5, 4, 'Sjetio se i zloće Bajanovih sinova, koji su zasjedama na putovima narodu postavljali zamke i zapreke.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 5, 5, 'Pošto ih je opkolio u kulama, opsjedao ih je i predao ih prokletstvu. Zapalio je i sažgao njihove kule i sve one koji su bili u njima.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 5, 6, 'Zatim krenu na Amonce, u kojih je naišao na jaku vojsku i mnogi narod pod poglavarem Timotejem.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 5, 7, 'Zapodjeo je s njima mnoge bojeve, potukao ih i slomio im silu.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 5, 8, 'Zauze Jazer sa selima njegova područja, a zatim se vrati u Judeju.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 5, 9, 'Pogani u Galaadu udružiše se protiv Izraelaca koji su živjeli u njihovim krajevima da ih istrijebe; a Izraelci pobjegoše u tvrđavu Datemu.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 5, 10, 'Poslali su Judi i njegovoj braći pisma ovako sastavljena: \"Pogani koji nas okružuju udružili se protiv nas da nas unište.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 5, 11, 'Spremaju se da osvoje tvrđavu u koju smo se sklonili. Timotej zapovijeda njihovom vojskom.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 5, 12, 'Dođi sad i izbavi nas iz njihovih ruku, jer mnogo je naših već palo.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 5, 13, 'Pogubili su svu našu braću naseljenu u Tobijinoj zemlji, odveli u ropstvo žene i djecu, imanje im oduzeli i ondje pogubili oko tisuću ljudi.\"');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 5, 14, 'Dok se to pismo još čitalo, dođoše drugi glasnici, iz Galileje, razdrte odjeće, donoseći iste vijesti:');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 5, 15, '\"Udružili se protiv nas iz Ptolemaide i Tira i Sidona sa svim narodima Galileje da nas istrijebe.\"');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 5, 16, 'A kad su Juda i narod to čuli, sazvaše veliku skupštinu da vijećaju što da učine za svoju braću izvrgnutu nevoljama i napadajima neprijatelja.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 5, 17, 'Juda tada reče bratu Šimunu: \"Izaberi sebi ljude pa idi, izbavi svoju braću u Galileji! A ja i brat Jonatan poći ćemo u Galaaditidu.\"');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 5, 18, 'Za obranu Judeje ostavi Zaharijina sina Josipa i Azarju, poglavara naroda, s preostalom vojskom.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 5, 19, 'I zapovjedi im: \"Upravljajte ovim narodom, ali se ne upuštajte u rat protiv poganskih naroda dok se mi ne vratimo.\"');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 5, 20, 'Šimunu su dali tri tisuće ljudi za Galileju, a Judi osam tisuća ljudi za Galaaditidu.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 5, 21, 'Pošto je otišao u Galileju, Šimun je zametnuo mnoge bojeve protiv pogana, porazio ih i natjerao ih u bijeg; gonio ih je do vrata Ptolemaide.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 5, 22, 'Ostavili su na bojištu oko tri tisuće ljudi, od kojih je pokupio plijen.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 5, 23, 'Poveo je sa sobom Židove iz Galileje i Arbate sa ženama i djecom i svim njihovim imanjem te ih odveo u Judeju s velikom radošću.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 5, 24, 'A Juda Makabej i brat mu Jonatan prijeđoše preko Jordana i tri su dana išli pustinjom.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 5, 25, 'Sretoše Nabatejce, koji su ih primili miroljubivo te im pripovjedili sve što se dogodilo njihovoj braći u Galaaditidi:');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 5, 26, 'kako ih je mnogo zatvoreno u Bosori, u Bosoru, u Alemi, Kasfu, Makedu i Karnainu, a to su sve utvrđeni veliki gradovi;');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 5, 27, 'kako ima zatvorenih i u ostalim gradovima Galaaditide i kako je neprijatelj odlučio da sutradan napadne te gradove, osvoji ih i u jednom danu istrijebi sve koji se nalaze u njima.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 5, 28, 'Juda odmah krenu s vojskom kroz pustinju prema Bosori. Zauze grad i spali ga pošto pobi sve muško oštricom mača i pokupi plijen.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 5, 29, 'Odande je krenuo dalje noću i približio se tvrđavi.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 5, 30, 'Kad je svanula zora a oni podigli oči, ugledaše bezbrojno mnoštvo kako namješta ljestve i sprave da zauzmu tvrđavu; već su napadali.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 5, 31, 'Videći da je napadaj počeo i da se urnebesna vika, pomiješana sa zvukom truba, diže iz grada prema nebu,');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 5, 32, 'Juda reče ljudima svoje vojske: \"Borite se danas za svoju braću!\"');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 5, 33, 'Svrsta ih u tri skupine i tako krenuše na neprijateljsku zalaznicu. Trube odjeknuše i zazivi se podigoše.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 5, 34, 'Timotejeva vojska, razabravši da je to Makabej, pobježe pred njim. On ih porazi do nogu: toga dana ostade ih na bojištu oko osam tisuća.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 5, 35, 'Pošto je zatim skrenuo na Alemu, napade je, zauze, pobi sve muško, oplijeni je i spali.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 5, 36, 'Odande se digao da zauzme Kasfo, Maked, Bosor i ostale gradove Galaaditide.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 5, 37, 'Poslije tih događaja Timotej prikupi drugu vojsku i utabori se pred Rafonom s one strane potoka.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 5, 38, 'Juda je poslao svoje da izvide tabor i oni mu javiše: \"Oko ovog poglavara skupili su se svi pogani koji nas okružuju i stvorili su golemu vojsku;');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 5, 39, 'najmili su i Arape kao pomoćne odrede; utaborili su se preko potoka, pripravni da te napadnu.\" Juda krenu da ih presretne.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 5, 40, 'Timotej reče zapovjednicima svoje vojske kad su se Juda i njegove čete približili vodi: \"Ako prvi prijeđe i udari na nas, nećemo mu moći odoljeti jer će imati prednost;');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 5, 41, 'a ako se poboji i utabori s one strane potoka, prijeći ćemo mi, udariti i nadvladati ga.\"');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 5, 42, 'Kad se približio toku vode, Juda postavi uz potok narodne pisare i naloži im: \"Ne dopustite nikomu da razapinje šatora, nego neka idu svi u boj.\"');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 5, 43, 'On prijeđe prvi onamo, a za njim je slijedio sav narod. Potjera pred sobom sve pogane. Oni pobacaše oružje i pobjegoše da se sklone u karnainski hram.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 5, 44, 'Židovi su najprije osvojili grad, zatim spalili hram sa svima koji su bili u njemu. Tako je oboren Karnain i odonda se Judi nije moglo odoljeti.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 5, 45, 'Juda sabra sve Izraelce koji su bili u Galaadu, od najmanjeg do najvećeg, njihove žene i djecu i imanje, i to se golemo mnoštvo uputilo prema judejskoj zemlji.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 5, 46, 'Stigli su u Efron, važan i vrlo jak grad što se nalazio na putu. Kako ga nije bilo moguće zaobići ni desno ni lijevo, nije bilo druge nego kroza nj.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 5, 47, 'Stanovnici su im uskratili prolaz i vrata zagradili kamenjem.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 5, 48, 'Juda im posla poruku sastavljenu ovim miroljubivim riječima: \"Pustite nas da prođemo preko vaše zemlje, da dođemo u svoju; nitko vam neće učiniti nikakve štete, samo ćemo proći.\" Ali im nisu htjeli otvoriti.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 5, 49, 'Tada Juda oglasi po vojsci neka svatko ostane na svojem mjestu.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 5, 50, 'Junaci vojske zauzeše položaje. Juda je cio dan i cijelu noć napadao, i grad mu pade u ruke.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 5, 51, 'Posjekao je sve muško oštricom mača, porušio grad do temelja, oplijenio ga i prošao tim mjestom po tjelesima pobijenih.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 5, 52, 'Židovi su pregazili Jordan na velikoj ravnici nasuprot Betšanu.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 5, 53, 'Juda je cijelim putem pribirao zaostale i bodrio narod sve dok nije stigao u judejsku zemlju.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 5, 54, 'Radosno i veselo uspinjali su se na goru Sion i prinijeli paljenice zato što su se svi u miru vratili i nitko od njih nije stradao.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 5, 55, 'Dok su Juda i Jonatan bili u galaadskoj zemlji a Šimun, njihov brat, u Galileji pred Ptolemaidom,');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 5, 56, 'Josip, Zaharijin sin, i Azarja, zapovjednici vojske, čuli su za njihova sjajna djela i bojeve koje su vodili te rekoše:');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 5, 57, '\"Proslavimo se i mi, pođimo protiv pogana što su oko nas!\"');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 5, 58, 'I tako dadoše naloge četama kojima su zapovijedali i krenuše na Jamniju.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 5, 59, 'Gorgija iziđe iz grada sa svojim ljudima da se s njima pobije.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 5, 60, 'Josip i Azarja biše natjerani u bijeg i gonjeni sve do judejskih međa. Palo je u taj dan među izraelskim narodom oko dvije tisuće ljudi.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 5, 61, 'Bio je to velik poraz za narod: nisu slušali Judu i njegovu braću, nego mišljahu da će se istaknuti hrabrošću.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 5, 62, 'Ali, eto, nisu bili od koljena onih ljudi od kojih je dolazio spas Izraelu.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 5, 63, 'Plemeniti Juda i njegova braća uživali su veliku čast pred svim Izraelom i svim poganima gdje su god čuli za njihova imena.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 5, 64, 'Ljudi se natiskivali oko njih i klicali im.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 5, 65, 'Juda je sa svojom braćom otišao na jug da vojuje protiv Ezavovih sinova. Zauzeo je Hebron i njegova sela, srušio tvrđave, a kule naokolo sve popalio.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 5, 66, 'Digavši tabor, ode da osvoji filistejsku zemlju i prođe Marisu.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 5, 67, 'Toga su dana u boju pali svećenici koji su se htjeli istaći hrabrošću pa se nepromišljeno upustili u boj.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 5, 68, 'Juda se uputio u Azot u filistejskom području i ondje je razrušio žrtvenike, izrezbarene likove njihovih bogova popalio, opljačkao gradove, a onda se vratio u judejsku zemlju.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 6, 1, 'U to vrijeme kralj Antioh prolazio gornjim krajevima. Dočuo je da je perzijski grad Elimaida na glasu s bogatstva, sa srebra i zlata,');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 6, 2, 'da je ondje bogat hram u kojem se nalaze zlatni predmeti vojne opreme, oklopi i oružje što ih je ostavio Filipov sin Aleksandar Makedonski, koji je prvi vladao nad Grcima.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 6, 3, 'Zato je krenuo da pokuša zauzeti grad i opljačkati ga, ali nije uspio jer su građani doznali za njegovu nakanu.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 6, 4, 'Oni mu se opriješe s oružjem u ruci: natjerali su ga u bijeg te se odande morao, jako ojađen, probijati natrag u Babilon.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 6, 5, 'Još dok je bio u Perziji, dođoše i javiše mu kako su poražene čete što su upale u judejsku zemlju.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 6, 6, 'I Lizija je navro sa snažnom vojskom, ali je pred Židovima morao pobjeći, jer su oni pobijeđenim vojskama uzeli opremu i obilan plijen i tako postali još jači.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 6, 7, 'Srušili su i sramotni kip što ga bijaše podigao na žrtveniku u Jeruzalemu, a svoje su sveto mjesto okružili visokim zidovima, kakvi su bili i prije, pa tako i Betsur, jedan od njegovih gradova.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 6, 8, 'Kad je kralj čuo te vijesti, prenerazi se i silno uznemiri; pade na postelju i razbolje se od jada što mu se nije želja ispunila.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 6, 9, 'Ostade tako više dana, ali ga je tuga neprestano presvajala. A kad mu bijaše umrijeti,');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 6, 10, 'dozva sve svoje prijatelje i reče im: \"Nestalo je sna s mojih očiju i srce mi je klonulo od jada.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 6, 11, 'Zato rekoh u svom srcu: \'U koliku li sam tjeskobu zapao i kakav li me to val nesreće zapljusnuo! Mene koji sam u vrijeme svoje moći bio poštovan i ljubljen.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 6, 12, 'Sad mi dolaze na pamet zla koja sam počinio u Jeruzalemu kad sam odande odnio sve zlatno i srebrno posuđe što se u njemu nalazilo i kad sam bez razloga zapovjedio da se stanovnici Jude istrijebe.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 6, 13, 'Sad znam da me zbog toga snašlo ovo zlo i da od velike tuge umirem u tuđoj zemlji!\'\"');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 6, 14, 'Nato dozva Filipa, jednog od svojih prijatelja, i postavi ga nad svim kraljevstvom.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 6, 15, 'I dade mu svoju krunu, plašt i pečatni prsten, i ostavi mu da odgoji njegova sina Antioha, i da ga uputi u vođenje kraljevstva.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 6, 16, 'Tu kralj Antioh umrije godine sto četrdeset i devete.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 6, 17, 'Kad je Lizija doznao da je kralj umro, postavio mu je za nasljednika njegova sina Antioha, koga je odgajao od njegova djetinjstva. Nadjenuo mu je ime Eupator.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 6, 18, 'Ali oni koji su bili u Tvrđi uznemiravahu Izraelce oko Svetišta, neprestano smišljajući kako da im naude i tako pomognu poganima.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 6, 19, 'Juda odluči da ih uništi. Zato sazva sav narod na opsadu.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 6, 20, 'Sabrali su se i opkolili ih godine sto pedesete. Načinili su strelišta i bojne naprave.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 6, 21, 'Ali su neki od opkoljenih probili obruč, a njima se pridružili i neki od bezbožnih Izraelaca.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 6, 22, 'Otišli su kralju i rekli mu: \"Dokle ćeš oklijevati da nam izvršiš pravdu i osvetiš našu braću?');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 6, 23, 'Dobre volje pristali smo da služimo tvome ocu i vladamo se prema njegovim nalozima i držimo se njegovih odredaba.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 6, 24, 'Zato sinovi našeg naroda opsjedaju Tvrđu i zamrziše na nas. I poubijali su sve koji su im dopali šaka i razgrabili su nam baštinu.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 6, 25, 'I nisu samo na nas podigli ruke: podigli su ih i na sve tvoje krajeve.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 6, 26, 'Evo, sad opsjedaju jeruzalemsku Tvrđu: hoće da je zauzmu, a utvrdili su Svetište i Betsur.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 6, 27, 'Ako im se ne ispriječiš, učinit će još i više, a ti ih više nećeš zaustaviti.\"');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 6, 28, 'Na te se riječi kralj razgnjevi. Sabra sve svoje prijatelje, starješine svojih pješaka i zapovjednike konjanika.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 6, 29, 'Došle su mu i najamničke čete drugih kraljevina i od morskih otoka.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 6, 30, 'Broj se njegovih snaga podigao na sto tisuća pješaka i dvadeset tisuća konjanika i trideset i dva slona uvježbana za rat.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 6, 31, 'Došli su preko Idumeje i opsjeli Betsur, dugo ga tukli i čak napravili bojne naprave. Ali su oni iz grada provaljivali, palili naprave i hrabro se borili.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 6, 32, 'Tada se Juda, prekinuvši opsadu Tvrđe, utabori kod Bet Zaharije, nasuprot kraljevskom taboru.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 6, 33, 'Kralj ustade u ranu zoru i požuri se sa svojom vojskom prema Bet Zahariji. Njegove su čete zauzele borbene položaje, a trube zatrubile.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 6, 34, 'Slonovima su davali grožđani i dudov sok da ih potaknu za boj.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 6, 35, 'Životinje su razmjestili među bojne redove. Uza svakog slona poredali su tisuću pješaka opremljenih lančanim oklopima i brončanim šljemovima, a k tomu su svakoj životinji pridijelili i pet stotina odabranih konjanika.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 6, 36, 'Ti su upravljali svim pokretima životinje, pratili je svuda i od nje se nisu udaljivali.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 6, 37, 'Na svakog slona privezali su potpruzima jaku drvenu obrambenu kulu. U svakoj su, uz Indijca, bila četiri snažna ratnika.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 6, 38, 'Ostale je konjanike kralj razmjestio na oba krila vojske da uznemiruju neprijatelje i pokrivaju bojne redove.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 6, 39, 'Kad je sunce obasjalo zlatne i mjedene štitove, zablistale su od njih gore i zasvijetlile poput upaljenih zublja.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 6, 40, 'Jedan se dio kraljevskih četa razvi po gorskim visovima, a drugi po nizinama i svi se pokrenuše u čvrstom i uređenom rasporedu.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 6, 41, 'Uzdrhtaše svi koji su čuli graju toga mnoštva, bahat njegovih stopala i zveket oružja, jer ta je vojska bila vrlo velika i jaka.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 6, 42, 'Juda se sa svojom vojskom upusti u boj. U kraljevskoj vojsci pade šest stotina ljudi.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 6, 43, 'Uto je Eleazar, zvan Auran, opazio jednu životinju opremljenu kraljevskom ormom, višu od ostalih. Pomisli da je u njoj kralj');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 6, 44, 'i žrtvova se da izbavi svoj narod i steče vječno ime.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 6, 45, 'Hrabro potrča prema životinji, posred bojnog reda. Ubijao je desno i lijevo, a neprijatelji se pred njim razdvojili.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 6, 46, 'Uvuče se pod slona, probode ga mačem i ubi. Životinja se strovali na Eleazara i zgnječi ga. Tako on pogibe ondje.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 6, 47, 'Židovi su, videći silnu kraljevsku snagu i žestoku vojsku, pred njom uzmakli.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 6, 48, 'Kraljevska vojska krenu protiv Židova u Jeruzalemu. Kralj je opsjedao Judeju i goru Sion,');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 6, 49, 'a s onima u Betsuru sklopio je mir. Ti su izišli iz grada jer više nisu mogli izdržati opsadu: nisu imali hrane. Bila je, naime, subotnja godina, zemlja počivala.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 6, 50, 'Kralj je zaposjeo Betsur i ondje smjestio posadu.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 6, 51, 'Prilično je dugo opsjedao Svetište. Služio se protiv njega strelištima, bojnim napravama, bacačima plamena, kamenja i strelica, a tako i praćarama.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 6, 52, 'I opsjednuti uzimahu naprave protiv napadača. Borba potraja dugo.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 6, 53, 'Ali u skladištima nestalo hrane. Bila je sedma godina, a, osim toga, Izraelci dovedeni u Judeju iz poganskih krajeva bijahu potrošili i posljednje zalihe.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 6, 54, 'Tako su u Svetištu ostavili malo ljudi jer je zavladala glad. Ostali se raspršili svaki na svoju stranu.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 6, 55, 'Filip, koga je kralj Antioh još za svoga života odabrao da njegova sina Antioha odgaja za prijestolje,');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 6, 56, 'vratio se iz Perzije i Medije s vojskom koja je pratila kralja. Sad je nastojao da zagospoduje državnim poslovima.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 6, 57, 'Na tu vijest Lizija je samo gledao da što prije ode. Rekao je kralju, vojskovođama i ljudima: \"Svaki smo dan slabiji, imamo sve manje hrane, a mjesto koje opsjedamo dobro je utvrđeno. Osim toga, čekaju nas poslovi kraljevstva.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 6, 58, 'Pružimo, dakle, desnicu tim ljudima, sklopimo mir s njima i sa svim njihovim narodom.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 6, 59, 'Dopustimo im da žive po svojim običajima kao i prije, jer su se radi svojih zakona, kad smo ih dokinuli, na nas razgnjevili i sve ovo počinili.\"');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 6, 60, 'Taj je prijedlog kralju i starješinama bio po volji. Po poslanicima ponudio je Židovima mir, a oni ga prihvatiše.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 6, 61, 'Kralj i starješine potkrijepiše sporazum zakletvom, pa su opsjednuti izišli iz Tvrđe.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 6, 62, 'Potom kralj uziđe na goru Sion. Tu vidje kako je mjesto utvrđeno, pogazi svoju zakletvu i zapovjedi da se ono poruši.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 6, 63, 'Nato hitno podiže tabor i vrati se u Antiohiju. Tu nađe Filipa gospodarem grada. Udari na grad i silom ga osvoji.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 7, 1, 'Godine sto pedeset i prve uteče iz Rima Seleukov sin Demetrije, iskrca se sa malo ljudi u nekom primorskom gradu i ondje se zakralji.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 7, 2, 'Kad je ulazio u kraljevski dvor svojih otaca, vojska je uhvatila Antioha i Liziju da ih dovede pred njega.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 7, 3, 'Kad je on to doznao, reče: \"Ne pokazujte mi njihovih lica!\"');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 7, 4, 'Vojska ih pogubi, a Demetrije zasjede na prijestolje svoga kraljevstva.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 7, 5, 'Potom su k njemu došli svi bezakonici i bezbožnici iz Izraela, a predvodio ih Alkim, koji je htio postati velikim svećenikom.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 7, 6, 'Oni su pred kraljem optuživali narod govoreći: \"Juda je sa svojom braćom pobio sve tvoje prijatelje, a nas je izagnao iz zemlje.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 7, 7, 'Zato pošalji čovjeka u koga imaš povjerenje: neka ode onamo i vidi kako je Juda opustošio nas i kraljevsku zemlju, pa neka kazni te ljude i sve njihove pomagače!\"');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 7, 8, 'Vladar je izabrao Bakida, jednog od kraljevih prijatelja, upravitelja Prekorječja, čovjeka ugledna u kraljevstvu i vjerna kralju.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 7, 9, 'Njega posla s bezbožnikom Alkimom, komu je potvrdio svećeništvo, i zapovjedi mu da se osveti Izraelcima.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 7, 10, 'Oni su otišli i s velikom vojskom stigli u judejsku zemlju. Poslali su glasnike Judi i njegovoj braći s miroljubivim riječima, punim himbe.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 7, 11, 'Ali oni nisu vjerovali njihovim riječima, jer vidješe kako su došli s velikom vojskom.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 7, 12, 'A oko Alkima i Bakida okupilo se vijeće zakonoznanaca da pronađe pravedno rješenje.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 7, 13, 'Među Izraelcima prvi su Hasidejci zatražili da se s njima sklopi mir.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 7, 14, 'Govorahu oni: \"S vojskom je došao svećenik od Aronova plemena. Neće nam učiniti ništa nažao.\"');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 7, 15, 'Govorio je s njima miroljubivo, uvjeravao ih i zaklinjao se: \"Nećemo vam učiniti ništa nažao, ni vama ni vašim prijateljima.\"');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 7, 16, 'Oni mu povjerovaše. A on zapovjedi te između njih uhvatiše šezdeset ljudi i pogubiše ih onaj isti dan, prema riječima Pisma:');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 7, 17, '\"Razbacali su tjelesa tvojih svetaca i prolili njihovu krv oko Jeruzalema i ne bijaše nikoga da ih ukopa.\"');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 7, 18, 'Tada strah i trepet obuze sav narod. Rekoše: \"Nema u njih ni istine ni pravde, pogazili su nagodbu i zakletvu koju su položili.\"');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 7, 19, 'Bakid ode iz Jeruzalema i utabori se kod Betzeta. Tu je uhvatio mnoge ljude koji su, s nekima od naroda, uskočili k njemu. Bacio ih je u velik bunar.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 7, 20, 'Zatim je zemlju predao Alkimu i ostavio s njim vojsku da mu pomaže. Bakid se vrati kralju.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 7, 21, 'Alkim se stao boriti za velikosvećeničku čast.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 7, 22, 'Oko njega sabraše se svi koji su smućivali svoj narod. Zavladali su judejskom zemljom i počinili mnogo zla u Izraelu.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 7, 23, 'Kad je Juda vidio da zlodjela Alkima i njegovih pristalica protiv Izraelaca nadmašuju i sama poganska zlodjela,');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 7, 24, 'stade obilaziti svim judejskim krajevima osvećujući se istaknutim prebjezima i braneći im prolaz zemljom.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 7, 25, 'Kad je Alkim spoznao da se Juda sa svojim pristašama osilio i kad je razabrao da im se neće moći oprijeti, vratio se kralju te ih optužio još gore.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 7, 26, 'Tada kralj posla Nikanora, jednog od svojih najistaknutijih vojskovođa, koji bijaše neprijatelj Izraelu; naloži mu kralj da istrijebi taj narod.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 7, 27, 'Došavši u Jeruzalem s mnogobrojnom vojskom, Nikanor poruči Judi i njegovoj braći ove himbeno miroljubive riječi:');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 7, 28, '\"Neka između mene i vas ne bude rata. Posjetit ću vas miroljubivo, sa slabom pratnjom.\"');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 7, 29, 'Stigao je k Judi. Mirno su jedan drugoga pozdravili, ali neprijatelji bijahu spremni da ugrabe Judu.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 7, 30, 'Razabravši da je k njemu došao s podmuklim nakanama, Juda se prepade te ga više ne htjede vidjeti.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 7, 31, 'Nikanor uvidje da su mu otkrili namjeru te zametnu protiv Jude boj kod Kafarsalama.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 7, 32, 'Tu je od Nikanorovih ljudi palo oko pet stotina, a ostali pobjegoše u Davidov grad.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 7, 33, 'Poslije tih događaja Nikanor se pope na goru Sion. Iz svetog mjesta izišli su neki svećenici i narodni starješine da ga mirno pozdrave i pokažu mu paljenicu koja se prinosi za kralja.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 7, 34, 'Ali im se on naruga, ismija ih, onečisti i obasu pogrdama.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 7, 35, 'U napadu gnjeva progovorio je ovako: \"Ako se Juda sa svojom vojskom ovaj put ne preda u moje ruke, spalit ću tu građevinu kad se, nakon pobjede, vratim ovamo.\" Potom je izišao sav razjaren.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 7, 36, 'Svećenici su ušli, stali pred žrtvenik i Svetište i progovorili suznih očiju:');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 7, 37, '\"Ti si izabrao ovaj Dom da se posveti tvom Imenu, da tvome narodu bude kuća molitve i prošnje.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 7, 38, 'Osveti se tom čovjeku i njegovoj vojsci da padnu od mača! Spomeni se njihove hule i ne daj da odahnu!\"');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 7, 39, 'Nikanor je otišao iz Jeruzalema i utaborio se kod Bet Horona. Tu mu se pridružila sirska vojska.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 7, 40, 'Juda se pak utaborio kod Adase, sa tri tisuće ljudi. On se ovako pomolio:');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 7, 41, '\"Kad su te poslanici asirskoga kralja pohulili, izišao je tvoj anđeo i pobio njegovih sto osamdeset i pet tisuća.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 7, 42, 'Tako danas satri pred nama tu vojsku da svi ostali znaju da je bezbožnički govorio protiv tvog Svetišta i sudi mu po njegovoj zloći!\"');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 7, 43, 'Vojske su zapodjele boj trinaestog dana mjeseca Adara. Nikanorova vojska bijaše razbijena, a i on pade u bici.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 7, 44, 'Kad su vojnici vidjeli da im je pao Nikanor, bacili su oružje i razbježali se.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 7, 45, 'Židovi su ih gonili dan hoda, od Adase do okolice Gezera, trubeći za njima bojnim trubama.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 7, 46, 'Iz svih okolnih judejskih sela izlazili su stanovnici i opkoljivali bjegunce. Ti su srtali jedni na druge. Svi su pali od mača, nijedan nije izbjegao.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 7, 47, 'Uzeše plijen od njih. Zatim odsjekoše Nikanoru glavu i desnicu, koju je tako oholo dizao; odnijeli su ih i podigli na vidiku Jeruzalemu.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 7, 48, 'Narod se silno radovao. Taj je dan slavio kao velik blagdan veselja.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 7, 49, 'Odredili su da se taj dan slavi svake godine trinaestog Adara.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 7, 50, 'Tako se judejska zemlja malo smirila.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 8, 1, 'Tada je Juda dočuo za Rimljane: kako su moćni i blagonakloni prema svojim privrženicima, kako sklapaju prijateljstvo s onima koji im se obraćaju i kako su veoma jaki.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 8, 2, 'Pripovijedali su mu o njihovim ratovima i junaštvima kojima su se istaknuli protiv Gala, kako su ih svladali i prisilili na danak,');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 8, 3, 'o svemu što su izveli u Hispaniji da se domognu rudnika srebra i zlata,');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 8, 4, 'kako su razboritošću i ustrajnošću zavladali svim onim područjem, a ono je od njih veoma udaljeno; kako su potukli kraljeve koji su s kraja zemlje dolazili da ih napadaju, nanijeli im velike poraze i kako im neki donose godišnji danak.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 8, 5, 'Napokon su oružjem satrli Filipa i kitijskoga kralja Perzeja, a tako upokorili i druge koji se bijahu digli na njih.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 8, 6, 'Porazili su azijskog kralja Antioha Velikog, koji je na njih pošao u rat sa stotinu dvadeset slonova, s konjanicima, bojnim kolima i mnogobrojnim pješacima.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 8, 7, 'Uhvatili su ga živa, odredili da on i njegovi nasljednici plaćaju težak danak, da dadu taoce i prepuste im');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 8, 8, 'zemlju indijsku, medijsku i lidijsku i neke od svojih najljepših pokrajina, koje onda dadoše kralju Eumenu.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 8, 9, 'Kad su pak neki iz Grčke naumili doći da ih istrijebe,');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 8, 10, 'Rimljani su za to doznali i na njih poslali samo jednog vojskovođu. Udarili su na njih te je palo mnogo žrtava. Odveli su u ropstvo njihove žene i djecu i oplijenili ih. Zavladali su njihovom zemljom, razorili im tvrđave i podjarmili ih sve do danas.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 8, 11, 'A i druga kraljevstva i otoke koji su im se opirali Rimljani su satrli i podložili.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 8, 12, 'Svojim pak prijateljima i onima koji se u njih uzdaju ostali su vjerni. Podložili su kako obližnje tako i udaljene kraljeve, boje ih se svi koji čuju za njihovo ime.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 8, 13, 'Komu žele vlast, njemu je i daju. Svrgavaju pak koga ne žele. Vrlo su ojačali.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 8, 14, 'Unatoč svemu tome nijedan se od njih nije okrunio niti obukao grimizom da bi se tako proslavio.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 8, 15, 'Osnovali su vijeće u kojem svaki dan vijeća trista i dvadeset članova, savjetujući se bez prestanka o svom puku, radi njegova blagostanja.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 8, 16, 'Svake godine povjeravaju jednome čovjeku da vlada i upravlja cijelim carstvom. Svi toga jednog čovjeka slušaju: među njima nema ni zavisti ni ljubomore.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 8, 17, 'Tada Juda izabra Ivanova sina Eupolema, iz Akosove kuće, i Eleazarova sina Jasona i posla ih u Rim da s Rimljanima sklope prijateljstvo i savez');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 8, 18, 'da bi se tako oslobodili jarma. Uvidjeli su da grčko kraljevstvo porobljuje Izraela.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 8, 19, 'Poslije vrlo duga putovanja stigli su u Rim, ušli u senat i ovako progovorili:');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 8, 20, '\"Juda zvan Makabej i njegova braća sa židovskim narodom poslali su nas k vama da s vama sklopimo savez i prijateljstvo i da nas ubrojite u svoje saveznike i prijatelje.\"');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 8, 21, 'Taj se zahtjev senatorima svidio.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 8, 22, 'Evo prijepisa ugovora koji su urezali u brončane ploče i poslali Židovima u Jeruzalem kao ispravu o miru i savezu:');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 8, 23, '\"Neka sreća prati Rimljane i židovski narod na moru i na kopnu zavazda! A mač i neprijatelj bio od njih daleko!');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 8, 24, 'Ako, prije svega, Rimu ili kojemu od njegovih saveznika diljem njegove vladavine zaprijeti rat,');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 8, 25, 'židovski će se narod na njegovoj strani boriti svim srcem, koliko prilike budu zahtijevale.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 8, 26, 'Protivnicima neće davati niti ih opskrbljivati žitom, oružjem, novcem ni lađama. Tako je zaključio Rim. I on će vjerno vršiti svoje obaveze, a da ne prima jamstvo.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 8, 27, 'Isto tako, ako židovski narod bude prvi napadnut, Rimljani će se na njegovoj strani boriti svom dušom, koliko to od njih budu zahtijevale prilike.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 8, 28, 'Napadačima neće se davati ni žita, ni oružja, ni novaca, ni lađa. Tako je zaključio Rim i on će se ovih obaveza držati bez prijevare.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 8, 29, 'Takav su savez Rimljani sklopili sa židovskim narodom.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 8, 30, 'Ako bi pak poslije toga jedni ili drugi htjeli štogod dodati ili oduzeti, mogu to učiniti po svojoj volji, i što god dodaju ili oduzmu to će ih obvezivati.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 8, 31, 'Što se tiče zala koja im je nanio kralj Demetrije, pisali smo mu ovako: \'Zašto pritišćeš jarmom Židove, naše prijatelje i saveznike?');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 8, 32, 'Potuže li se još jednom na tebe, ustat ćemo na obranu njihovih prava i zavojštit ćemo protiv tebe na moru i na kopnu.\'\"');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 9, 1, 'Kad je Demetrije dočuo da je u borbi poginuo Nikanor i njegova vojska, ponovo je poslao Bakida i Alkima u Judeju, na čelu desnoga krila.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 9, 2, 'Oni se uputiše prema Galileji i opsjednuše Mesalot na području Arbele. Pošto su ga zauzeli, pogubili su mnogo stanovnika.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 9, 3, 'Prvoga mjeseca godine sto pedeset i druge utaborili su se pred Jeruzalemom,');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 9, 4, 'a potom su sa dvadeset tisuća pješaka i dvije tisuće konjanika otišli u Beerzet.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 9, 5, 'Juda se sa tri tisuće odabranih ratnika utaborio u Eleasi.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 9, 6, 'Videći velik broj neprijatelja, uplašiše se. Mnogi pobjegoše iz tabora. U njem nije ostalo više od osam stotina ljudi.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 9, 7, 'Juda je vidio da mu se vojska raspala prije bitke. Klonulo mu srce jer više nije imao vremena da je sakupi.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 9, 8, 'Onako zabrinut reče onima koji su preostali: \"Ustanimo! Hajdemo na protivnike! Možda ćemo ih ipak suzbiti.\"');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 9, 9, 'Oni su ga odvraćali riječima: \"Zasad možemo samo spasiti život, tako da se sa svojom braćom vratimo i nastavimo borbu. Sad nas je zaista premalo.\"');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 9, 10, 'Juda odvrati: \"Ne, toga neću nikad učiniti da od njih bježim! Ako nam je došlo vrijeme, poginimo junački za svoju braću i ne ostavljajmo ljage na svojoj slavi!\"');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 9, 11, 'Vojska je krenula iz tabora i stala prema njima. Konjanici se razdijelili na dva odreda, praćari i strijelci stupiše na čelo vojske, a tako i udarne čete, sve sami junaci. Bakid je držao desno krilo,');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 9, 12, 'bojni se red približavo uza zvuk trube sa dva boka.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 9, 13, 'Oni na Judinoj strani i sami zatrubiše, potresla se zemlja od bojnog tutnja. Bitka se zapodjela ujutro i trajala do večera.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 9, 14, 'Juda je opazio da je Bakid s jezgrom svoje vojske nadesno: oko njega se okupili svi srčani ljudi');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 9, 15, 'i razbili su desno krilo i gonili ga do gore Azara.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 9, 16, 'Ali kad su Sirci s lijevoga krila opazili da im je desno krilo provaljeno, nagnuše za Judom i njegovim ljudima i napadoše ih s leđa.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 9, 17, 'Zametnula se ogorčena borba i ranjeni su mnogi s jedne i druge strane.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 9, 18, 'I Juda je pao, a ostali se razbjegli.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 9, 19, 'Jonatan i Šimun podigli su svog brata Judu i pokopali ga u grobu svojih otaca u Modinu.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 9, 20, 'Oplakivao ga je sav Izrael i ljuto tužio za njim, naričući više dana ovako:');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 9, 21, '\"O, kako pade junak, Izraelov spas!\"');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 9, 22, 'Ostala Judina djela, njegovi ratovi, junaštva koja je izvršio i dokazi njegove slave nisu zapisani jer ih bijaše u obilju. Ę(160.-143. prije Krista)');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 9, 23, 'Kad je poginuo Juda, podigli su glave svi bezakonici na svem izraelskom području i ponovo se pojavili svi zlotvori.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 9, 24, 'Kako je u to vrijeme pritisnula veoma velika glad, zemlja je prešla na njihovu stranu.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 9, 25, 'Bakid je namjerno izabirao bezbožne ljude da upravljaju zemljom.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 9, 26, 'Ti su kod Judinih prijatelja vršili premetačine i istrage i dovodili ih Bakidu, koji ih je kažnjavao i izvrgavao ruglu.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 9, 27, 'Tada se u Izraelu razbjesnilo takvo ugnjetavanje kakva nije bilo u sve vrijeme otkad se više nije pojavljivao prorok.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 9, 28, 'Onda se okupiše svi Judini prijatelji i rekoše Jonatanu:');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 9, 29, '\"Otkako je umro tvoj brat Juda, nema više čovjeka slična njemu da se opre našim neprijateljima, Bakidu i mrziteljima našega naroda.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 9, 30, 'Zato te, dakle, danas biramo na njegovo mjesto da nam budeš poglavar i vođa u borbi koju smo poduzeli.\"');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 9, 31, 'Tako je Jonatan prihvatio vodstvo i naslijedio svoga brata Judu.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 9, 32, 'Kad je Bakid za to doznao, samo je gledao da ubije Jonatana.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 9, 33, 'Čim je za to dočuo, Jonatan je sa svojim bratom Šimunom i sa svima onima koji su ih pratili pobjegao u pustinju Tekou i utaborio se kraj vode Asfara.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 9, 34, 'Bakid je to saznao u subotnji dan, pa je i on sa svim svojim vojnicima prešao preko Jordana.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 9, 35, 'Jonatan je poslao svoga brata, kao vođu pratnje, da zamoli prijatelje Nabatejce kako bi kod njih ostavili obilnu opremu.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 9, 36, 'Ali Amrajevi sinovi, oni iz Medabe, iziđoše i uhvatiše Ivana sa svim što je imao i otiđoše s tim plijenom.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 9, 37, 'Poslije tih događaja javili su Jonatanu i njegovu bratu Šimunu da Amrajevi sinovi slave veliku svadbu i da vrlo svečano iz Nadabata vode nevjestu, kćer jednoga od uglednih ljudi u Kanaanu.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 9, 38, 'Tada se oni sjetiše krvavog svršetka svoga brata Ivana. Popeše se i sakriše u gori.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 9, 39, 'Podigoše oči i vidješe gdje se usred nejasna žagora pomalja velika povorka, kako za njom slijedi ženik sa svojim prijateljima i braćom, a prate ih bubnjevima, glazbalima i bogatom opremom.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 9, 40, 'Židovi su nasrnuli na njih iz zasjede i stali ih ubijati. Mnogi su stradali, a ostali utekoše u goru. Odneseno im je sve što su imali.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 9, 41, 'Tako im se svadba okrenula u žalost, a zvuk glazbe u plač.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 9, 42, 'Pošto su ljuto osvetili krv svoga brata, vratiše se na muljevite obale Jordana.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 9, 43, 'Kad je to čuo Bakid, došao je u subotnji dan s mnogom vojskom na obalu Jordana.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 9, 44, 'Tada Jonatan reče svojim ljudima: \"Na noge! Borimo se za svoje živote, jer danas nije kao što je bilo jučer i prekjučer.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 9, 45, 'Eto, rat je pred nama i za nama. Posvuda je voda Jordana, mulj i šikarje: nema uzmaka.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 9, 46, 'Zato sad zavapite k Nebu da izbjegnete sili svojih neprijatelja!\"');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 9, 47, 'Boj se zametnuo. Jonatan je pružio ruku da udari Bakida, ali mu je ovaj izmakao: skočio je unazad.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 9, 48, 'Onda se Jonatan sa svojim ljudima baci u Jordan i prepliva na drugu stranu, ali protivnici nisu za njima prelazili preko Jordana.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 9, 49, 'Taj je dan na Bakidovoj strani palo oko tisuću ljudi.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 9, 50, 'Vrativši se u Jeruzalem, Bakid poče u Judeji graditi tvrde gradove, tvrđavu u Jerihonu, Emausu, Bet Horonu, Betelu, Tamnati, Faratonu, Tefonu, s visokim zidovima, vratima i prijevornicama.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 9, 51, 'U svakoj je ostavio posadu da divlja protiv Izraela.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 9, 52, 'Utvrdio je Betsur, Gezer i Tvrđu. Po njima je razmjestio vojnike i zalihe hrane.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 9, 53, 'Pokupio je za taoce sinove zemaljskih starješina i stavio ih pod stražu u jeruzalemskoj Tvrđi.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 9, 54, 'Godine stotinu pedeset i treće, drugoga mjeseca, zapovjedio je Alkim da sruše zid unutarnjeg dvorišta Svetišta. Tako je uništio djela proroka i počeo razaranje.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 9, 55, 'U to je vrijeme Alkima udarila kap i spriječila njegove pothvate. Usta mu zamuknuše: onako uzet, nije više mogao istisnuti ni riječi niti je mogao svojoj kući davati naloge.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 9, 56, 'I Alkim tako umrije u živim mukama.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 9, 57, 'Kad je Bakid vidio da je Alkim umro, vratio se kralju i judejska je zemlja počinula dvije godine.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 9, 58, 'Svi su se bezakonici savjetovali ovim riječima: \"Gle, Jonatan i njegovi žive mirno i bezbrižno. Hajde da sad dovedemo Bakida neka ih u jednoj noći pohvata sve.\"');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 9, 59, 'Potom su otišli i posavjetovali se s njim.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 9, 60, 'Bakid se podigao s velikom vojskom i tajno pisao svim svojim pristalicama u Judeji da pohvataju Jonatana i njegove ljude. Ali ne mogoše tako, jer su oni doznali za njihovu namjeru.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 9, 61, 'Štoviše, uhvatili su pedesetak ljudi u zemlji, počinitelje te opačine, pa su ih pogubili.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 9, 62, 'Potom se Jonatan i Šimun sa svojim ljudima skloniše u Betbasi u pustinji. Tu su popravili ono što je ondje bilo opustošeno i mjesto utvrdiše.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 9, 63, 'Kad je za to doznao Bakid, skupio je sve svoje ljude i pozvao svoje pristaše u Judeji.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 9, 64, 'Otišao se utaboriti kod Betbasija, opsjedao ga više dana i izradio bojne naprave.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 9, 65, 'Jonatan je u gradu ostavio svoga brata Šimuna, a sam je sa šakom ljudi izišao na obilazak po okolini.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 9, 66, 'Tukao je Odomeru i njegovu braću i Fasironove sinove u njihovu taborištu. Počeli su vojevati i uzlažahu s vojskom.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 9, 67, 'Šimun je sa svojim ljudima provalio iz grada i spalio bojne naprave.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 9, 68, 'Udarivši na Bakida, razbiše ga i teško ga ojadiše, pomrsiše mu namjeru i vojni pohod.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 9, 69, 'Razgnjevi se on protiv odmetnika koji su mu savjetovali da dođe u tu zemlju, pobi mnoge te sa svojim ljudima odluči da se vrati kući.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 9, 70, 'Na tu vijest posla Jonatan k njemu poslanike da s njim uglave mir i povratak zarobljenika.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 9, 71, 'On na to pristade i ostade vjeran svojim obvezama. Zakle mu se da više nikad, dok god živi, neće protiv njega ništa poduzimati.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 9, 72, 'Pošto mu je predao roblje što ga je prije u judejskoj zemlji zarobio, Bakid se vratio u svoju zemlju i više nije dolazio na židovsko područje.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 9, 73, 'Mač je otpočinuo u Izraelu. Jonatan se nastani u Mikmasu, gdje je počeo suditi narodu. Iz Izraela je istrijebio bezbožnike.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 10, 1, 'Godine sto i šezdesete krenu Antiohov sin Aleksandar, nazvan Epifan, da zaposjedne Ptolemaidu. Primili su ga i on poče u njoj vladati.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 10, 2, 'Kad je to doprlo do ušiju kralja Demetrija, skupio je vrlo jaku vojsku i izišao protiv njega u boj.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 10, 3, 'Ujedno je Demetrije poslao Jonatanu vrlo miroljubivo pismo u kojemu mu obećava da će ga uzvisiti u dostojanstvu.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 10, 4, 'Zapravo je u sebi govorio: \"Treba da s tim ljudima žurno sklopimo mir prije nego ga oni s Aleksandrom sklope protiv nas.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 10, 5, 'Jonatan će se sjetiti svih zala što smo ih nanijeli njemu, njegovoj braći i njegovu narodu.\"');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 10, 6, 'Čak ga je ovlastio da diže vojsku, proizvodi oružje i naziva se njegovim saveznikom. Zapovjedio je da mu se iz Tvrđe predaju taoci.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 10, 7, 'Jonatan ode u Jeruzalem i poruku pročita pred svim narodom, a tako i pred onima u Tvrđi.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 10, 8, 'Ti su se zaista zaprepastili kad su čuli da mu je kralj dao pravo da diže vojsku.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 10, 9, 'Ljudi iz Tvrđe predali su Jonatanu taoce, a on ih je vratio njihovim roditeljima.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 10, 10, 'Jonatan se nastanio u Jeruzalemu i počeo ponovo zidati i obnavljati grad.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 10, 11, 'Napose je poslenicima zapovjedio da se ponovo podigne bedem, a gora Sion okruži i utvrdi klesanim kamenjem; oni tako i učiniše.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 10, 12, 'Pobjegli su stranci koji su se nalazili u tvrđavama što ih je sagradio Bakid.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 10, 13, 'Svaki je od njih ostavio svoj položaj i vratio se u svoju zemlju.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 10, 14, 'Jedino su u Betsuru ostali neki od onih koji su pogazili Zakon i zapovijedi: tu im bijaše utočište.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 10, 15, 'Kralj Aleksandar dočuo je za obećanja što ih je Demetrije dao Jonatanu. Kazivali su mu i o ratovima i junaštvima kojima su se istakli on i njegova braća i o mukama koje su morali pretrpjeti.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 10, 16, 'Povikao je: \"Hoćemo li ikad naći takva čovjeka? Učinimo ga, dakle, svojim prijateljem i saveznikom!\"');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 10, 17, 'Napisao mu je i poslao pismo ovako sastavljeno:');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 10, 18, '\"Kralj Aleksandar pozdravlja svog brata Jonatana.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 10, 19, 'Čuli smo o tebi da si hrabar i moćan čovjek i da si dostojan da budeš naš prijatelj.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 10, 20, 'Zato te danas postavljamo vrhovnim svećenikom tvog naroda i dajemo ti naslov kraljeva prijatelja (i ujedno mu posla grimiznu kabanicu i zlatnu krunu), da pristaješ uz nas i s nama sačuvaš prijateljstvo.\"');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 10, 21, 'I Jonatan se odjenu svetom odjećom sedmoga mjeseca godine sto i šezdesete o Blagdanu sjenica. Skupio je zatim vojsku i nabavio mnogo oružja.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 10, 22, 'Kad je Demetrije za to čuo, ožalosti se i reče:');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 10, 23, '\"Zašto smo dopustili da nas preteče Aleksandar i ugrabi prijateljstvo Židova i tako učvrsti svoj položaj?');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 10, 24, 'Pisat ću im i ja uvjerljivo i ponuditi im položaj i bogatstvo, ne bi li mi bili na pomoć.\"');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 10, 25, 'I posla im pismo ovog sadržaja: \"Kralj Demetrije pozdravlja židovski narod.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 10, 26, 'Čuli smo i radujemo se što ste održali svoje ugovore sklopljene s nama i ostali nam vjerni prijatelji i što niste prešli k našim neprijateljima.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 10, 27, 'Ostanite nam vjerni i dalje, a mi ćemo vam dobročinstvima vraćati ono što za nas budete činili.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 10, 28, 'Oprostit ćemo vas mnogih daća i podijelit ćemo vam darove.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 10, 29, 'Već sad vas oslobađam i sve Židove razrješavam dažbina, poreza na sol i krunskog nameta.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 10, 30, 'I trećinu zemaljskih proizvoda i polovicu plodova s drveća što mi pripadaju otpuštam od danas pa ubuduće judejskoj zemlji i trima pokrajinama što su joj pridijeljene u Samariji i Galileji - od današnjeg dana pa zauvijek.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 10, 31, 'Jeruzalem neka je svet i slobodan sa svojim područjem, slobodan od svih desetina i daća.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 10, 32, 'Odričem se posjedovanja jeruzalemske Tvrđe i predajem je vrhovnom svećeniku da u njoj smjesti ljude koje sam izabere da je čuvaju.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 10, 33, 'Otpuštam bez otkupa svaku judejsku osobu odvedenu u zarobljeništvo izvan judejske zemlje gdje se god u mom kraljevstvu nalazila. Hoću da svi budu slobodni od nameta, oni i njihova stoka.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 10, 34, 'Neka svi blagdani, subote, mjeseci mlađaci i zakonski dani, a tako i tri dana prije i tri dana poslije blagdana, neka svi budu za sve Židove u mom kraljevstvu dani oprosta i oslobođenja.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 10, 35, 'Nitko neće imati pravo da i u čemu progoni ili uznemiruje nekoga od vas.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 10, 36, 'Židovi će se upisivati u kraljevsku vojsku do trideset tisuća ljudi, primat će plaću kakva pripada svim kraljevskim vojnicima.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 10, 37, 'Neki će od njih biti porazmješteni po velikim kraljevskim tvrđavama, a drugi će biti u povjerljivim službama kraljevstva. Neka njihovi zapovjednici i starješine proiziđu iz njihovih redova i neka žive po svojim zakonima, kako je kralj odredio za judejsku zemlju.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 10, 38, 'One tri pokrajine što su Judeji pridijeljene od Samarije neka se pripoje Judeji i budu njezine, tako da se nađu pod istim poglavarom, da ne slušaju druge vlasti osim vlasti vrhovnog svećenika.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 10, 39, 'Ptolemaidu s njezinim okružjem dajem na dar Svetištu u Jeruzalemu da se tako podmiruju troškovi Svetišta.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 10, 40, 'Ja osobno davat ću svake godine petnaest tisuća šekela od kraljevskih dohodaka u mjestima za to prikladnim.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 10, 41, 'I sve ostalo što službenici nisu predali kao prijašnjih godina davat će odsad za potrebe Hrama.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 10, 42, 'Osim toga, i onih pet tisuća srebrnih šekela što su ih svake godine ubirali od dohodaka Svetišta neka se otpusti i neka pripadne svećenicima koji vrše službu.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 10, 43, 'Tko god zatraži utočište u jeruzalemskom Hramu i na njegovu području, a kralju duguje poreze ili što drugo, bit će slobodan sa svim svojim imanjem što ga posjeduje u mom kraljevstvu.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 10, 44, 'Za gradnju i obnavljanje Svetišta neka se troškovi isto tako namiruju iz kraljevih dohodaka.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 10, 45, 'Jednako će se iz kraljevskih dohodaka namirivati i troškovi za gradnju jeruzalemskih zidova i okolnih utvrda te za gradnju zidova po judejskim gradovima.\"');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 10, 46, 'Kad su Jonatan i narod čuli za ta obećanja, nisu povjerovali niti ih prihvatili, jer su se sjećali koliko je mnogo zlostavljao Izraela i koliko ga je ugnjetavao.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 10, 47, 'Zato su pristali uz Aleksandra, jer je u njihovim očima on imao miroljubive namjere. Zato su mu bili stalni saveznici.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 10, 48, 'Tada je kralj Aleksandar skupio velike snage i krenuo protiv Demetrija.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 10, 49, 'Pošto su ta dva kralja zametnula borbu, Demetrijeva vojska naže u bijeg, a Aleksandar ju je progonio i nadvladao.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 10, 50, 'Vodio je žestoku borbu do zalaska sunca. Toga je istog dana Demetrije poginuo.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 10, 51, 'Tada je Aleksandar poslao egipatskom kralju Ptolemeju poslanike s ovom porukom:');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 10, 52, '\"Budući da sam se vratio u svoje kraljevstvo, sjeo na prijestolje svojih otaca, preuzeo vlast, razbio Demetrija i zavladao našom zemljom,');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 10, 53, 'budući da sam zametnuo s njime boj pa smo razbili njega i njegovu vojsku i sjeli na njegovo kraljevsko prijestolje,');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 10, 54, 'hajde da se sprijateljimo: daj mi svoju kćer za ženu, bit ću ti zet i dat ću ti, isto kao i njoj, darove tebe dostojne!\"');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 10, 55, 'Kralj Ptolemej odgovorio je ovako: \"Sretna li dana kad si se vratio u zemlju svojih otaca i sjeo na njihovo kraljevsko prijestolje!');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 10, 56, 'Sad ću ti učiniti ono što si pisao, ali mi dođi u susret u Ptolemaidu da se vidimo, i bit ću ti tast, kako si rekao.\"');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 10, 57, 'Ptolemej je otišao sa svojom kćeri Kleopatrom iz Egipta i došao u Ptolemaidu godine sto šezdeset i druge.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 10, 58, 'Kralj Aleksandar došao mu u susret, a on mu dao svoju kćer Kleopatru te je u Ptolemaidi veličanstveno proslavio njezinu udaju, kako pristaje kraljevima.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 10, 59, 'Kralj Aleksandar pisao je Jonatanu da mu dođe u posjete.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 10, 60, 'Dođe on svečano u Ptolemaidu i sastade se sa oba kralja. Obdari mnogim srebrom i zlatom njih i njihove prijatelje. Podijelio je mnogo darova i ugodio im.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 10, 61, 'Tada su se protiv njega urotili pokvarenjaci iz Izraela, izraelski ološ, te ga optužili. Ali ih kralj nije poslušao.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 10, 62, 'Nego kralj zapovjedi da Jonatanu skinu njegovu odjeću i da ga odjenu grimizom, pa tako i učiniše.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 10, 63, 'Kralj ga posadi kraj sebe i zapovjedi svojim dostojanstvenicima: \"Prođite s njim posred grada i objavite da se nitko ničim protiv njega ne smije potužiti i nitko ga ne smije ničim uznemirivati.\"');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 10, 64, 'Kad su tužitelji vidjeli kakva mu se iskazuje čast, kako glasnici pred njim izvikuju, kako se zaogrnuo grimizom, svi pobjegoše.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 10, 65, 'Kralj ga je počastio, upisao ga među svoje prve prijatelje i postavio za vojskovođu i namjesnika.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 10, 66, 'Potom se Jonatan mirno i veselo vratio u Jeruzalem.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 10, 67, 'Godine sto šezdeset i pete došao je s Krete Demetrijev sin Demetrije u zemlju svojih otaca.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 10, 68, 'Kad je za to dočuo kralj Aleksandar, vrlo se ožalostio i vratio u Antiohiju.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 10, 69, 'Demetrije potvrdi Apolonija za namjesnika u Celesiriji, a ovaj sabra veliku vojsku te se utabori kod Jamnije. Velikom svećeniku Jonatanu poruči ovo:');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 10, 70, '\"Ti mi se suprotstavljaš posve sam, tako te sam zbog tebe izvrgnut ruglu i sramoti. Zašto ti vladaš u gorama protiv nas?');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 10, 71, 'Ako li se pouzdaješ u svoju vojsku, siđi k nama u dolinu da se tu ogledamo, jer sa mnom je snaga gradova.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 10, 72, 'Pitaj i doznat ćeš tko sam ja i koji su ostali što mi pomažu. Kažu da nam nećete odoljeti, jer su ti oci u dva maha bili u vlastitoj zemlji natjerani u bijeg.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 10, 73, 'Tako se ni sad nećeš oduprijeti konjaništvu i tolikom pješaštvu u ravnici, gdje nema kamenja ni stijena ni mjesta kamo da pobjegneš.\"');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 10, 74, 'Kad je Jonatan čuo Apolonijevu poruku, sva mu se duša uzbunila. Odabrao je deset tisuća ljudi te izišao iz Jeruzalema. Njegov brat Šimun došao mu je u pomoć.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 10, 75, 'Utaborili se pred Jopom. Građani su mu zatvorili vrata, jer je u Jopi bila Apolonijeva posada. Započeše napadati.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 10, 76, 'Građani se uplašiše i otvoriše vrata, i tako Jonatan zagospodari Jopom.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 10, 77, 'Kad je za to dočuo Apolonije, svrsta za borbu tri tisuće konjanika i mnoštvo pješaka i krenu prema Azotu, kao da će samo proći, ali je odmah zaokrenuo u dolinu jer je imao mnoštvo konjanika u koje se uzdao.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 10, 78, 'Jonatan pohita za njim do Azota i tu se dvije vojske sukobiše.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 10, 79, 'Ali je Apolonije iza njih ostavio skrivenih tisuću konjanika.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 10, 80, 'Jonatan je znao da iza njega ima zasjeda. Konjanici su opkolili njegovu vojsku i na vojnike odapinjali strelice od jutra do mraka.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 10, 81, 'Vojska je dobro izdržala, onako kako je odredio Jonatan, dok su se, naprotiv, konji izmorili.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 10, 82, 'Šimun priskoči sa svojom vojskom i navali na bojni red, jer je konjaništvo već obnemoglo. Neprijatelji su bili slomljeni te su pobjegli.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 10, 83, 'Konjanici se raspršili po ravnici, a bjegunci stigli u Azot i ušli u hram Dagona, svoga idola, da se spase.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 10, 84, 'Ali je Jonatan spalio Azot i gradove oko njega te pokupio plijen i spalio Dagonov hram i sve one koji su se u nj sklonili.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 10, 85, 'Osam je tisuća ljudi palo od mača i bilo spaljeno.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 10, 86, 'Jonatan ode odande i utabori se kod Askalona. Tu su mu građani izišli u susret s velikim slavljem.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 10, 87, 'Poslije toga Jonatan se sa svojima vratio u Jeruzalem s obilnim plijenom.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 10, 88, 'Kad je kralj Aleksandar čuo za te događaje, iskaza još veće počasti Jonatanu.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 10, 89, 'Poslao mu je zlatnu kopču koja se po običaju daje kraljevskim rođacima. Poklonio mu je u posjed Akaron sa svim njegovim područjem.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 11, 1, 'Egipatski je kralj sakupio mnogo vojske kao što je pijeska na morskoj obali, a tako i mnogo brodova, u namjeri da se lukavo dočepa Aleksandrova kraljevstva i pripoji ga svome.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 11, 2, 'Pođe u Siriju s prijateljskim riječima. Građani su mu otvarali vrata gradova, izlazili mu u susret, jer je kralj Aleksandar naložio da ga primaju. Bio mu je tast.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 11, 3, 'Ali čim bi Ptolemej ušao u koji grad, ondje bi odmah smjestio posadu.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 11, 4, 'Kad se približavao Azotu, pokazali su mu spaljen Dagonov hram, opustošeni Azot s okolinom, razbacana mrtva tijela i izgorjele ostake onih koje je Jonatan spalio u ratu. Nagomilali su ih na hrpu na kraljevu putu.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 11, 5, 'Pripovijedali su kralju što je Jonatan učinio, željeli ga oklevetati. Ali je kralj šutio.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 11, 6, 'Jonatan je došao u Jopu i svečano se pridružio kralju. Pozdravili su se i tu prenoćili.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 11, 7, 'Jonatan je kralja ispratio do rijeke koja se zove Eleuter, a zatim se vratio u Jeruzalem.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 11, 8, 'Kralj Ptolemej zavladao je primorskim krajevima do Seleucije na moru. Počeo je snovati pakosne osnove protiv Aleksandra.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 11, 9, 'Poslao je poslanike kralju Demetriju s porukom: \"Hajde da među sobom sklopimo savez. Dat ću ti svoju kćer koju ima Aleksandar i kraljevat ćeš u kraljevstvu svog oca.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 11, 10, 'Žao mi je što sam njemu dao svoju kćer. On mi radi o glavi.\"');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 11, 11, 'Oklevetao ga je jer je poželio njegovo kraljevstvo.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 11, 12, 'Oduzeo mu je svoju kćer i dao je Demetriju. Raskinuo je veze s Aleksandrom, i njihovo neprijateljstvo postade očito.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 11, 13, 'Ptolemej je ušao u Antiohiju i okrunio se krunom Azije; tako se okrunio dvjema krunama: egipatskom i azijskom.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 11, 14, 'Kralj Aleksandar bio je u to vrijeme u Ciliciji, jer su se stanovnici onih krajeva pobunili.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 11, 15, 'Kad je Aleksandar za sve to čuo, pošao je protiv njega u boj. Ptolemej krenu na nj s jakom vojskom i natjera ga u bijeg.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 11, 16, 'Aleksandar pobježe u Arabiju da se ondje skloni, a Ptolemej je slavio slavlje.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 11, 17, 'Arapin Zabdiel odrubi Aleksandru glavu i posla je Ptolemeju.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 11, 18, 'Treći dan potom umro je kralj Ptolemej, a građani su pobili njegove posade po tvrđavama.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 11, 19, 'Kraljem je godine sto šezdeset i sedme postao Demetrije.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 11, 20, 'U to je vrijeme Jonatan sabrao one koji su bili u Judeji da osvoji jeruzalemsku Tvrđu. Napao ju je s mnogo bojnih naprava.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 11, 21, 'Tada su neki mrzitelji svog naroda, ljudi bezakonici, otišli kralju i javili mu kako Jonatan opsjeda Tvrđu.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 11, 22, 'Na tu se vijest kralj razgnjevi. Čim je to čuo, odmah krenu u Ptolemaidu. Odande je pisao Jonatanu da prekine opsadu i što prije dođe u Ptolemaidu na razgovor s njim.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 11, 23, 'Kad je Jonatan primio taj poziv, zapovjedio je da se nastavi opsada. U pratnji izraelskih starješina i svećenika, koje je izabrao, i sam se izvrže opasnosti.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 11, 24, 'Ponijevši srebra i zlata, odjeće i mnogo drugih darova, otišao je kralju u Ptolemaidu. Kralj ga primi milostivo.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 11, 25, 'Neki su ga odmetnici optuživali,');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 11, 26, 'ali je kralj učinio s njime kao što i njegovi prethodnici: odlikova ga pred svim svojim prijateljima.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 11, 27, 'Potvrdio mu je veliko svećeništvo i sve ostale časti što ih je imao otprije i uvrstio ga među svoje prve prijatelje.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 11, 28, 'Jonatan je zamolio kralja da Judeju oslobodi od plaćanja poreza, a ujedno i tri pokrajine Samarije, a za to mu obeća tri stotine talenata.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 11, 29, 'Kralj bijaše s time sporazuman te Jonatanu o svemu tome izda pismo ovog sadržaja:');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 11, 30, '\"Kralj Demetrije pozdravlja brata Jonatana i judejski narod.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 11, 31, 'Prijepis pisma što smo ga o vama pisali svome rođaku Lastenu upućujemo i vama da znate:');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 11, 32, 'kralj Demetrije pozdravlja oca Lastena.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 11, 33, 'Odlučili smo da učinimo dobro judejskom narodu, svojim prijateljima i vjernim saveznicima, zbog njihove blagonaklonosti prema nama.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 11, 34, 'Potvrđujemo im i judejsko područje i tri pokrajine - Aferemu, Lidu i Ramataim - koje su bile oduzete Samariji i pripojene Judeji, sa svime što im pripada. Svima koji prinose žrtve u Jeruzalemu to je u naknadu za poreze što ih je kralj ondje svake godine ubirao na poljski prirod i plodove drveća.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 11, 35, 'Što se tiče naših ostalih prava na desetine i namete, na solarinu i krunski danak što nam pripada, sve im to od danas otpuštamo.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 11, 36, 'Ništa od toga neće biti opozvano odsele pa dovijeka.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 11, 37, 'Zato se sad pobrinite i načinite od ovoga prijepis, pa dajte Jonatanu da se na svetoj Gori stavi na vidljivo mjesto.\"');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 11, 38, 'Kad je kralj Demetrije vidio da mu se zemlja pod njegovom vladom umirila i da mu se više nitko ne opire, otpustio je sve svoje čete, svaku u svoje mjesto, osim onih stranih, koje je unovačio na otocima pogana. Zato su ga zamrzile sve čete njegovih otaca.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 11, 39, 'Tada je Trifon, koji je prije pristajao uz Aleksandra, videći da se sve čete bune protiv Demetrija, otišao k Arapinu Jamlikuu, koji je odgajao Aleksandrova sina Antioha.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 11, 40, 'Usrdno ga je nagovarao da mu preda dječaka, da se sin zakralji umjesto svog oca. Obavijestio ga je o svemu što je učinio Demetrije i kako ga mrze njegove čete. Ondje je ostao mnogo vremena.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 11, 41, 'Međuto je Jonatan zatražio od kralja Demetrija da iz jeruzalemske Tvrđe i ostalih tvrđava povuče posade koje su neprestano ratovale s Izraelcima.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 11, 42, 'Demetrije je poručio Jonatanu: \"Ne samo da ću to za tebe i tvoj narod učiniti negu ću tebe i tvoj narod obasuti častima čim mi se za to pruži prilika.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 11, 43, 'Zasad bi dobro učinio kad bi mi u pomoć poslao ljude, jer su mi se sve moje čete iznevjerile.\"');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 11, 44, 'Jonatan mu je u Antiohiju poslao tri tisuće ljudi vičnih ratu. Kad su stigli kralju, on se njihovu dolasku silno obradova.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 11, 45, 'Gotovo stotinu i dvadeset tisuća građana okupilo se usred grada u namjeri da ubiju kralja.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 11, 46, 'Kralj je utekao u dvor, a građani zaposjeli ulice i počeli napadati.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 11, 47, 'Tada kralj pozva u pomoć Židove. Oni se svi odmah skupiše oko njega, potom se raziđoše po gradu i toga dana pobiše do stotinu tisuća stanovnika.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 11, 48, 'Zapalili su grad i pokupili toga dana mnogo plijena i tako izbaviše kralja.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 11, 49, 'Kad su građani vidjeli da Židovi po miloj volji gospodare gradom, klonuli su srcem i zavapili kralju:');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 11, 50, '\"Pruži nam desnicu, pa neka Židovi prestanu udarati na nas i na grad.\"');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 11, 51, 'Odbacili su oružje te sklopili mir. Židovi su se proslavili pred kraljem i pred svima pripadnicima njegova kraljevstva. Istakli su se u njegovim državama i vratili u Jeruzalem s mnogo plijena.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 11, 52, 'Kralj je Demetrije opet sjeo na svoje kraljevsko prijestolje, i zemlja je pod njegovom upravom bila mirna.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 11, 53, 'Ali je prekršio sva svoja obećanja, zavadio se s Jonatanom, nije više priznavao njegovih usluga nego ga silno žalostio. Okršaj kod Hasora');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 11, 54, 'Poslije toga vratio se Trifon i s njim dječak Antioh, koji se zakraljio i ovjenčao krunom.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 11, 55, 'Tada su se oko njega skupile sve čete kojih se Demetrije riješio. Zaratile su s Demetrijem, natjerale ga u bijeg i porazile.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 11, 56, 'Trifon se dočepao slonova i zavladao Antiohijom.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 11, 57, 'Mladi je Antioh pisao Jonatanu ovo: \"Potvrđujem te za vrhovnog svećenika i postavljam te nad četiri pokrajine i određujem da budeš među kraljevim prijateljima.\"');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 11, 58, 'Ujedno mu je poslao zlatno posuđe i stolni pribor, ovlastio ga da pije iz zlatnih čaša, da se oblači u grimiz i nosi zlatnu kopču.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 11, 59, 'Njegova brata Šimuna postavio je za vojskovođu od Tirskih stepenica do međa egipatskih.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 11, 60, 'Jonatan krenu na obilazak Prekorječja i gradova. Sva sirska vojska prešla je na njegovu stranu da se s njim zajedno bori. Kad je došao u Askalon, građani su ga svečano dočekali.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 11, 61, 'Odande je otišao u Gazu. Gaza je zatvorila vrata, pa ju je uzeo opsjedati, a okolicu paliti i plijeniti.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 11, 62, 'Gažani su stali Jonatana zaklinjati, a on im dade mira, ali je sinove njihovih starješina uzeo za taoce i poslao ih u Jeruzalem. Potom je prošao zemljom do Damaska.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 11, 63, 'Jonatan je čuo da su Demetrijevi zapovjednici došli u Kedeš u Galileji s velikom vojskom da ga maknu s dužnosti.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 11, 64, 'On krenu prema njima, a svoga brata Šimuna ostavi u zemlji.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 11, 65, 'Šimun je opsjedao Betsur, napadao ga mnogo dana i opkoljavao stanovnike.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 11, 66, 'Tada ga zamoliše za mir, a on prihvati. Ali moradoše isprazniti to mjesto, a on zaposjede grad i smjesti u nj posadu.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 11, 67, 'Jonatan se sa svojom vojskom utaborio kod Genezaretskoga jezera, a u ranu su zoru dosegli ravnicu Hasor.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 11, 68, 'Strana vojska pođe ravnicom da ga presretne, pošto mu je u gorama postavila zasjedu. Dok je ta vojska nadirala ravno,');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 11, 69, 'ljudi iz zasjede izbili su iz skrovišta i zametnuli bitku.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 11, 70, 'Svi se Jonatanovi ljudi razbježaše, nijedan od njih nije ostao, osim Matatije, Apsalomova sina, i Jude, Halfijeva sina, zapovjednika njegovih vojnika.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 11, 71, 'Tada Jonatan razdrije odjeću na sebi, glavu posu prašinom i pomoli se.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 11, 72, 'Vrati se u borbu i suzbi neprijatelja i natjera ga u bijeg.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 11, 73, 'Kad su to vidjeli oni koji bijahu pobjegli, vratiše se k njemu te su s njim tjerali neprijatelja do Kedeša, do njegova tabora, pa se tu i oni utaboriše.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 11, 74, 'Taj su dan pale tri tisuće ljudi tuđinske vojske. Jonatan se tada vrati u Jeruzalem.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 12, 1, 'Videći da mu je pogodna prilika, Jonatan izabra ljude i posla ih u Rim da s Rimljanima potvrde i obnove prijateljstvo.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 12, 2, 'Jednaka je pisma poslao i Spartancima i drugima.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 12, 3, 'Tako su oni otišli u Rim, ušli u senat i rekli: \"Veliki svećenik Jonatan i narod židovski poslaše nas da među sobom obnovimo prijateljstvo i savezništvo kakvo je bilo prije.\"');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 12, 4, 'Dali su im pisma za vlasti svake zemlje, s preporukom da ih upute u miru u judejsku zemlju.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 12, 5, 'Evo prijepisa pisma koje je Jonatan pisao Spartancima:');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 12, 6, '\"Veliki svećenik Jonatan, narodno vijeće, svećenici i ostali narod židovski pozdravljaju svoju braću Spartance.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 12, 7, 'Već prije poslao je Arije, koji je vladao među vama, velikom svećeniku Oniji pismo u kojem potvrđuje da ste naša braća, kako to pokazuje priloženi prijepis.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 12, 8, 'Onija je s počastima dočekao čovjeka koji je bio poslan i primio je pismo koje je jasno govorilo o savezništvu i prijateljstvu.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 12, 9, 'Što se nas tiče, iako nam to ne bi bilo potrebno budući da nam za utjehu stoje na raspolaganju Svete knjige,');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 12, 10, 'pokušali smo nekoga poslati da se obnovi bratstvo i prijateljstvo koje nas s vama veže, da se ne otuđimo od vas, jer je proteklo mnogo vremena od vašeg poslanstva.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 12, 11, 'Mi se vas neprestano sjećamo u svako doba i u svakoj prilici, o blagdanima i ostalim svečanim danima, kad prinosimo žrtve i molimo, kako se pristoji i dolikuje sjećati se braće.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 12, 12, 'Radujemo se vašoj slavi.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 12, 13, 'Oko nas su se umnožile nevolje i ratovi i na nas su zavojštili kraljevi naši susjedi.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 12, 14, 'U tim ratovima nismo vam htjeli biti na teret, kao ni ostalim našim saveznicima i prijateljima,');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 12, 15, 'jer nam s Neba dolazi pomoć koja nas jača. Tako smo izbavljeni od svojih neprijatelja, a oni su poniženi.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 12, 16, 'Izabrali smo, dakle, Antiohova sina Numenija i Jasonova sina Antipatra i poslali ih k Rimljanima da s njima obnove prijateljstvo i savez koji nas je ujedinjavao prije.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 12, 17, 'Njima smo naložili da pođu i k vama, da vas pozdrave i uruče vam naša pisma o obnavljanju bratstva.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 12, 18, 'I sad će nam biti drago ako nam na to odgovorite.\"');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 12, 19, 'Ovo je prijepis pisma što su ga oni poslali Oniji:');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 12, 20, '\"Spartanski kralj Arije pozdravlja velikog svećenika Oniju.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 12, 21, 'Našlo se u spisu o Spartancima i Židovima da su braća i da su od Abrahamova roda.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 12, 22, 'Sad, kad to znamo, bit će nam drago ako nam pišete o vašem blagostanju.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 12, 23, 'Mi vam pišemo ovako: vaša stada i vaša dobra naša su, a naša su vaša. Zato smo odredili da vam se u tom smislu donese poruka.\"');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 12, 24, 'Uto je Jonatan dočuo da su se Demetrijevi zapovjednici vratili s jačom vojskom nego prije da udare na nj.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 12, 25, 'Izišao je iz Jeruzalema i krenuo prema njima u zemlju Hamat, jer im nije htio dopustiti da uđu u njegovu zemlju.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 12, 26, 'Poslao je uhode u njihov tabor. Ti su se vratili i javili mu kako se spremaju da noću navale na njih.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 12, 27, 'Kad je zašlo sunce, Jonatan je zapovjedio svojima da bde i oružje drže pod rukom, da svu noć budu spremni na boj. Oko tabora postavio je predstraže.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 12, 28, 'Na vijest da su Jonatan i njegovi spremni na boj, neprijatelji su se uplašili i klonuli srcem te su u svom taboru zapalili vatre.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 12, 29, 'Ali Jonatan i njegovi vojnici nisu do jutra znali za njihov odlazak, jer su vidjeli da gore vatre.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 12, 30, 'Jonatan ih stade goniti, ali ih ne stiže budući da su prešli rijeku Eleuter.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 12, 31, 'Jonatan je odatle krenuo protiv Arapa koji se zovu Zabadejci te ih razbio i oplijenio.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 12, 32, 'Zatim je digao tabor i došao u Damask i prošao svu tu zemlju.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 12, 33, 'A Šimun se zaputio i dopro sve do Askalona i susjednih mjesta. Skrenuo je u Jopu i zauzeo je.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 12, 34, 'Čuo je, naime, da stanovnici kane to mjesto predati Demetrijevim pristašama. U nj je smjestio posadu da ga čuvaju.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 12, 35, 'Kad se Jonatan vratio, sazvao je skupštinu narodnih starješina i s njima odlučio da u Judeji sagradi tvrđave,');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 12, 36, 'da nadogradi jeruzalemske zidove, podigne visoku pregradu između Tvrđe i grada i tako odijeli Tvrđu od grada, osami je da njezini ljudi ne mogu ni kupovati ni prodavati.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 12, 37, 'Sabrali su se da ponovo ozidaju grad. Srušio se dio zida na potoku s istočne strane. Obnovili su četvrt zvanu Kafenata.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 12, 38, 'A Šimun ponovo sagradi Adidu u Šefeli, utvrdi je i namjesti vrata s prijevornicama.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 12, 39, 'Trifon je snovao da zavlada Azijom, ovjenča se krunom i digne ruku na kralja Antioha.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 12, 40, 'Bojeći se da ga Jonatan ne spriječi i da na nj, ako ustreba, ne zavojšti, smišljao je kako bi ga uhvatio i ubio. Krenuo je u Betšan.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 12, 41, 'Jonatan iziđe preda nj sa četrdeset tisuća ljudi izabranih za borbu. Došao je u Betšan.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 12, 42, 'Trifon je vidio kako je došao s velikom vojskom pa se pobojao na nj staviti ruku.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 12, 43, 'I tako ga primi s počastima, preporuči ga svim svojim prijateljima, obdari ga i svojim prijateljima i četama zapovjedi da ga slušaju kao njega samoga.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 12, 44, 'Jonatanu je rekao: \"Zašto si zamarao sav taj narod kad među nama ne prijeti rat?');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 12, 45, 'Pošalji ih, dakle, svojim kućama, izaberi nekoliko ljudi da te prate pa hajde sa mnom u Ptolemaidu. Predat ću ti taj grad kao i ostale tvrđave, ostatak četa i sve službenike, zatim ću se vratiti i otići, jer radi toga sam i došao.\"');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 12, 46, 'Jonatan mu povjerova i učini kako je on rekao. Otpustio je čete da odu u židovsku zemlju.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 12, 47, 'Uza se je ostavio tri tisuće ljudi, od kojih je dvije tisuće odvojio u Galileji, a tisuću ih je pošlo s njim.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 12, 48, 'Kad je Jonatan ušao u Ptolemaidu, njezini stanovnici zatvoriše vrata, uhvatiše ga i posjekoše sve njegove pratioce.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 12, 49, 'Trifon je poslao pješake i konjanike u Galileju i u veliku ravnicu da pobiju sve Jonatanove pristalice.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 12, 50, 'Ti su doznali da je Jonatan uhvaćen i da je poginuo zajedno sa svima svojima. Ohrabrili su jedni druge i pošli stisnutih redova, spremni za boj.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 12, 51, 'Kad su progonitelji vidjeli da im je život ugrožen, vratiše se.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 12, 52, 'Svi su živi i zdravi došli u židovsku zemlju. Oplakivali su Jonatana i njegovu pratnju. Bili su puni straha. Sav je narod tugovao.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 12, 53, 'Svi su pogani oko njih nastojali da ih istrijebe. Govorili su: \"Nemaju ni vođe ni pomoćnika. Vrijeme je da udarimo na njih, pa ćemo im zatrti spomen među ljudima!\" Ę(143.-134. prije Krista)');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 12, 54, '');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 13, 1, 'Šimun je saznao da je Trifon sabrao veliku vojsku da upadne u judejsku zemlju i da je opustoši.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 13, 2, 'Kad je vidio gdje narod strepi od straha, došao je u Jeruzalem i skupio ga.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 13, 3, 'Tješio je narod govoreći: \"Dobro znate što smo ja i moja braća i kuća mog oca učinili za Zakon i za Sveto mjesto. Poznati su vam i ratovi i nevolje koje smo pretrpjeli.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 13, 4, 'Sva su moja braća izginula za Izrael. Ja sam ostao sam.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 13, 5, 'U vrijeme ugnjetavanja nikako ne želim svog života štedjeti. Nisam bolji od svoje braće.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 13, 6, 'Nego radije ću osvetiti svoj narod, Sveto mjesto, vaše žene i vašu djecu, jer su se svi pogani, gonjeni mržnjom, udružili da nas zatru.\"');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 13, 7, 'Čim je narod čuo te riječi, rasplamtio se duh u njemu.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 13, 8, 'Odgovorili su mu jakim glasom: \"Ti si naš vođa namjesto Jude i svoga brata Jonatana!');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 13, 9, 'Preuzmi vodstvo u našem ratu. Što nam god ti zapovjediš, mi ćemo izvršiti.\"');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 13, 10, 'Sabrao je sve ljude sposobne za borbu i žurno dovršio zidove Jeruzalema i unaokolo ga utvrdio.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 13, 11, 'Poslao je u Jopu Apsalomova sina Jonatana i s njim znatnu vojsku. Taj je odande izagnao stanovnike i ondje se nastanio.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 13, 12, 'Trifon se podigao s velikom vojskom iz Ptolemaide da navali na židovsku zemlju. S njime je bio zasužnjeni Jonatan.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 13, 13, 'Šimun se utaborio kod Adide naprama ravnici.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 13, 14, 'Kad je Trifon doznao da je Šimun zamijenio svoga brata Jonatana i da kani s njim zametnuti boj, poslao je poslanike da mu kažu:');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 13, 15, '\"Zbog srebra što ga tvoj brat Jonatan duguje kraljevskoj blagajni za službe što ih je obnašao držimo ga u sužanjstvu.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 13, 16, 'Zato sad pošalji stotinu srebrnih talenata i dva njegova sina kao taoce, da se, kad bude pušten na slobodu, ne odmetne od nas. Onda ćemo ga pustiti.\"');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 13, 17, 'Premda je Šimun znao da mu glasnici lažu, ipak je poslao po srebro i dječake da na sebe ne navuče veliko neprijateljstvo naroda.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 13, 18, 'Jer bi inače rekli da je Jonatan poginuo zato što on nije poslao novce i dječake.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 13, 19, 'Zato je poslao dječake i stotinu talenata, ali ga Trifon prevari i ne posla Jonatana.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 13, 20, 'Poslije toga Trifon je krenuo da osvoji zemlju i opustoši je. Odabrali su zaobilazni put prema Adori. Šimun mu se isprečavao sa svojom vojskom kuda god je on prolazio.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 13, 21, 'A oni koji su bili u Tvrđi poslaše Trifonu poslanike, tražeći da brzo dođe k njima kroz pustinju i opskrbi ih hranom.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 13, 22, 'Tada Trifon odredi da onamo odu svi njegovi konjanici, ali je te noći pao tako obilan snijeg da nisu mogli krenuti. Digao je tabor i otišao u Galaaditidu.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 13, 23, 'Nadomak Baskame ubio je Jonatana, koga tu i pokopaše.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 13, 24, 'Potom se Trifon vratio u svoju zemlju.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 13, 25, 'Šimun je poslao po kosti svoga brata Jonatana i ukopao ga u Modinu, gradu svojih otaca.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 13, 26, 'Za njim je žalio sav Izrael i oplakivao ga mnogo dana.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 13, 27, 'Šimun je na grobnici svog oca i svoje braće podigao nadgrobnik od kamena uglađena straga i sprijeda, a tako visok da se vidio iz daljine.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 13, 28, 'Podigao je sedam piramida, jednu prema drugoj, ocu i majci i četvorici braće.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 13, 29, 'Načinio im je podnožja, okružio ih visokim stupovima, na stupove je na vječni spomen postavio bojnu opremu, a uz bojnu opremu klesane lađe da ih vide svi koji plove morem.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 13, 30, 'Takva je grobnica koju je podigao u Modinu i koja postoji i dan-danas.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 13, 31, 'Trifon je mladoga kralja Antioha pogubio na prijevaru.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 13, 32, 'Zavladao je namjesto njega, ovjenčao se krunom Azije i time navalio mnogo zla na zemlju.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 13, 33, 'A Šimun je ponovo sagradio tvrđave po Judeji, obzidao ih visokim kulama i velikim zidovima, s vratima i prijevornicama, i tvrđave je opskrbio hranom.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 13, 34, 'Potom je Šimun izabrao ljude i poslao ih kralju Demetriju da zemlji isposluju oprost, jer je Trifon znao samo otimati.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 13, 35, 'Kralj Demetrije poslao je odgovor na njihov zahtjev u pismu sastavljenu ovako:');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 13, 36, '\"Kralj Demetrije pozdravlja vrhovnog svećenika Šimuna, prijatelja kraljeva, starješine i judejski narod.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 13, 37, 'Primili smo zlatnu krunu i palmovu grančicu koju ste nam poslali, pa smo pripravni da s vama sklopimo potpuni mir i da pišemo svojim službenicima da vas oproste od poreza.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 13, 38, 'Sve ono što smo s vama uglavili neka ostane na snazi i tvrđave što ste ih sagradili neka su vaše.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 13, 39, 'Opraštamo vam dosadašnje prijestupe i propuste i krunu koju dugujete. A ako se kakav drugi porez ubirao u Jeruzalemu, neka se više ne zahtijeva.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 13, 40, 'Ako su koji od vas kadri da se uvrste u moju tjelesnu stražu, neka se upišu. Neka među nama vlada mir.\"');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 13, 41, 'Godine sto sedamdesete skinut je jaram pogana s Izraela,');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 13, 42, 'i narod je u svojim poveljama i ugovorima počeo pisati: \"Prve godine istaknutog vrhovnog svećenika, židovskog vojskovođe i glavara Šimuna.\"');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 13, 43, 'U te dane opkoli Šimun Gezer da bi ga zaposjeo vojskom. Načinio je kule na kotačima i njima se poslužio protiv grada. Prolomio je jedan od bedema i osvojio ga.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 13, 44, 'Oni s kule uskočili su u mjesto. U gradu nasta velika strka.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 13, 45, 'Građani se sa ženama i djecom popeli na bedeme, trgali na sebi odjeću i Šimunu iza glasa dovikivali da s njima sklopi mir:');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 13, 46, '\"Ne postupaj s nama po našoj zloći nego po svojem milosrđu!\"');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 13, 47, 'Šimun se s njima sporazumio i prestao je na njih udarati, ali ih je istjerao iz grada, očistio kuće u kojima su držali idole, a zatim uđe uz pjesme i hvalospjeve.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 13, 48, 'Uklonio je odande svaku nečistoću, naselio ljude koji vrše Zakon, utvrdio grad pa onda u njemu sebi uredio boravište.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 13, 49, 'Onima koji su bili u jeruzalemskoj Tvrđi nije se dopuštalo da odlaze iz zemlje ili da u nju idu, da kupuju ili prodaju. Ljuto su izgladnjeli. Mnogi su od njih svisnuli od gladi.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 13, 50, 'Zavapili su k Šimunu da s njima sklopi mir, a on tako i učini, ali ih odande istjera i očisti Tvrđu od svake poganštine.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 13, 51, 'Židovi su u nju ušli dvadeset i trećega dana drugoga mjeseca godine sto sedamdeset i prve. Klicali su noseći palmove grane, pjevali himne i hvalospjeve uz citare, harfe i cimbale, jer velik neprijatelj bijaše slomljen i izbačen iz Izraela.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 13, 52, 'Šimun je odredio da se svake godine taj dan svetkuje s veseljem. Utvrdio je hramsku goru kraj Tvrđe te se ondje sa svojima nastanio.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 13, 53, 'Kad je Šimun vidio da mu je sin Ivan odrastao do muževne dobi, postavi ga zapovjednikom svih snaga. Ivan se smjestio u Gezeru.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 14, 1, 'Godine sto sedamdeset i druge skupio je kralj Demetrije svoju vojsku i pošao u Mediju da dobije pomoć za rat protiv Trifona.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 14, 2, 'Kad je perzijski i medijski kralj Arsak čuo da je Demetrije došao na njegovo područje, posla jednog od svojih zapovjednika da ga uhvati živa.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 14, 3, 'Taj je otišao i porazio Demetrijevu vojsku, a njega uhvatio i doveo Arsaku, koji ga zatvori.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 14, 4, 'Zemlja je bila mirna za sve Šimunove vlade. Radio je na dobro svog naroda, i njegovu su vlast voljeli i njegovu slavu za sveg mu života.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 14, 5, 'Uz ostala slavna djela zauze Jopu, od nje učini svoju luku i sebi otvori pristup k morskim otocima.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 14, 6, 'Razmakao je međe svog naroda, zadržao zemlju u ruci');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 14, 7, 'i skupio mnoštvo zarobljenika. Zagospodario je Gezerom, Betsurom i Tvrđom, odande je uklonio poganštinu i nitko se nije našao da mu odoli.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 14, 8, 'Ljudi su mirno obrađivali zemlju, zemlja je davala svoj prirod, a drveće u ravnici plodove.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 14, 9, 'Starci su na trgovima sjedili, svi su razgovarali o blagostanju, mladići su nosili raskošnu odoru i oklop.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 14, 10, 'Gradove je opskrbio živežem, opremio ih utvrdama, slava mu se pronijela do nakraj svijeta.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 14, 11, 'Smirio je zemlju te Izrael doživje veliku radost.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 14, 12, 'Svatko je sjedio pod svojom lozom i smokvom i nitko ga nije uznemirivao.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 14, 13, 'Nestali su svi što su ga u zemlji napadali, i tih su dana kraljevi bili poraženi.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 14, 14, 'Pridizao je ponizne u svom narodu i suzbijao sve bezbožnike i zlikovce. Obdržavao je Zakon,');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 14, 15, 'vratio slavu Svetištu i obogatio ga mnogim posuđem.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 14, 16, 'Kad se u Rimu i do same Sparte saznalo da je Jonatan umro, nastade velika žalost.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 14, 17, 'Ali su čuli da ga je kao vrhovni svećenik naslijedio njegov brat Šimun, da je zavladao zemljom i gradovima u njoj');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 14, 18, 'i zato su mu pisali na brončanim pločicama da s njim obnove prijateljstvo i savezništvo koje su već uglavili s njegovim bratom Judom i Jonatanom.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 14, 19, 'To se pročitalo pred skupštinom u Jeruzalemu.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 14, 20, 'Evo prijepisa pisma što su ga poslali Spartanci: \"Glavari i grad Spartanaca pozdravljaju velikog svećenika Šimuna, starješine, svećenike i sav ostali židovski narod, svoju braću.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 14, 21, 'Poslanici koje ste poslali našem narodu kazivali su nam o vašoj slavi i časti i obradovali smo se njihovu dolasku.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 14, 22, 'Mi smo njihov izvještaj zapisali u narodnom vijeću ovako: židovski poslanici, Antiohov sin Numenije i Jasonov sin Antipater, došli su da s nama obnove prijateljstvo.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 14, 23, 'I narod je odlučio da ljude primi s počastima i da se prijepis njihova izvješća stavi među javne spise, da spartanski narod na to sačuva uspomenu. Osim toga, jedan je prijepis načinjen za vrhovnog svećenika Šimuna.\"');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 14, 24, 'Poslije toga Šimun je poslao Numenija u Rim s velikim zlatnim štitom, teškim tisuću mina, da s Rimljanima utvrdi savez.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 14, 25, 'Kad je narod saznao za te događaje, reče: \"Kako da zahvalimo Šimunu i njegovim sinovima?');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 14, 26, 'Jer on se pokazao čvrst, kao i njegova braća i kuća njegova oca. U bojevima je junački odbio izraelske neprijatelje i izvojštio slobodu.\" I ispisaše brončane pločice, koje su postavili na stupove na gori Sionu.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 14, 27, 'A evo, u prijepisu, što su napisali: \"Osamnaestog dana mjeseca Elula godine sto sedamdeset i druge, a to je treća godina velikog svećenika Šimuna, u Asaramelu,');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 14, 28, 'na velikoj skupštini svećenika, naroda, narodnih knezova i zemaljskih starješina objavilo se slijedeće:');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 14, 29, 'Dok su se česti ratovi vodili u zemlji, Matatijin sin Šimun, potomak Joaribovih sinova, i njegova braća izlagali su se opasnosti i opirali se protivnicima svog naroda da održe svoje Svetište i Zakon i uvelike su proslavili narod.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 14, 30, 'Jonatan je okupio narod i postao veliki svećenik, a zatim se pridružio svom narodu.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 14, 31, 'Neprijatelji Židova naumili su osvojiti njihovu zemlju da opustoše njihovo područje i dignu ruke na Svetište.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 14, 32, 'Tada je ustao Šimun i počeo vojevati za narod. Dao je mnogo svoga blaga, opremao oružjem hrabre ljude svog naroda i davao im plaću.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 14, 33, 'Utvrdio je židovske gradove i Betsur na židovskoj međi, gdje se prije nalazilo neprijateljsko oružje, i ondje je smjestio posadu židovskih ratnika.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 14, 34, 'Utvrdio je i Jopu na moru i Gezer u azotskom kraju, gdje su prije bili neprijatelji. Ondje je naselio Židove i ostavio im sve što im je trebalo za uzdržavanje.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 14, 35, 'Narod je upoznao Šimunovu vjernost i slavu kojom je on nakanio ovjenčati svoj narod. Zbog svih njegovih zasluga, zbog pravde i vjernosti narodu i jer je svime nastojao da podigne narod, postaviše ga za svoga vođu i velikog svećenika.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 14, 36, 'Onih dana on je uspio odstraniti pogane iz zemlje koju su zaposjeli i one iz Davidova grada u Jeruzalemu, gdje su se utvrdili i odakle su provaljivali i onečišćivali okolicu Svetišta i tako teško obeščašćivali njegovu svetost.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 14, 37, 'Smjestio je ondje židovske ratnike i utvrdio Tvrđu da zemlja i grad budu sigurni. Podigao je i jeruzalemske zidove.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 14, 38, 'Zato mu je kralj Demetrije potvrdio vrhovno svećeništvo,');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 14, 39, 'podigao ga u red svojih prijatelja i okružio ga velikim sjajem.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 14, 40, 'Jer je kralj čuo kako Rimljani Židove nazivaju svojim prijateljima, saveznicima i braćom i kako su Šimunove poslanike počastili,');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 14, 41, 'a Židovi i svećenici zaključili neka im Šimun bude vođa i veliki svećenik dovijeka, dok ne ustane vjerodostojan prorok.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 14, 42, 'Neka im bude upravitelj te određuje one koji će se brinuti za dobro Svetišta, za upravu zemljom, za oružje i utvrde.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 14, 43, 'Neka se brine za Svetište. Njega neka svi slušaju, sve isprave u zemlji neka se pišu u njegovo ime, a on da se oblači u grimiz i nosi zlatan nakit.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 14, 44, 'Da se ne usudi nitko, ni od naroda ni od svećenika, da štogod osujećuje ili se protivi onome što je on zapovjedio, niti da mimo njega u zemlji saziva skupštine, niti da se oblači grimizom ili nosi zlatnu kopču.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 14, 45, 'Tko se god o to ogriješi ili štogod od toga osujeti bit će krivac.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 14, 46, 'Sav je narod odobrio da se Šimun ovlasti da radi prema svom nahođenju.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 14, 47, 'Šimun je prihvatio i pristao da bude vrhovni svećenik, vojskovođa i knez Židova i svećenika, da bude na čelu svima.\"');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 14, 48, 'Odredili su da se ta isprava ureže u brončane ploče i da se one izlože u predvorju Svetišta na vidljivu mjestu,');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 14, 49, 'a da se njezini prijepisi pohrane u riznici tako da njima raspolažu Šimun i njegovi sinovi.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 15, 1, 'Antioh, sin kralja Demetrija, posla s morskih otoka svećeniku i židovskom vođi Šimunu i svemu narodu');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 15, 2, 'pismo ovog sadržaja: \"Kralj Antioh pozdravlja velikog svećenika i vođu Šimuna i židovski narod.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 15, 3, 'Budući da su se pokvarenjaci dočepali kraljevstva naših otaca, odlučio sam da ga opet osvojim i uspostavim kako je bilo i prije, i zato sam podigao silne čete i opremio ratno brodovlje');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 15, 4, 'da se iskrcam u zemlji i osvetim onima koji su je upropastili i opustošili mnoge gradove moga kraljevstva.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 15, 5, 'Potvrđujem ti sva oslobođenja od poreza kojih su te oslobodili kraljevi prije mene i svih ostalih prinosa koje su ti otpustili.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 15, 6, 'Dopuštam ti da u svojoj kovnici kuješ novce koji će zakonito optjecati tvojom zemljom.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 15, 7, 'Neka Jeruzalem i Svetište budu slobodni. Neka ti ostane sve oružje koje si proizveo i sve tvrđave koje si podigao i koje zapremaš.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 15, 8, 'Neka ti se oprosti sve što duguješ kraljevskoj riznici i ono što ćeš ubuduće dugovati kralju odsele pa dovijeka.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 15, 9, 'Kad ponovo osvojimo svoje kraljevstvo, obasut ćemo tebe, tvoj narod i Hram takvim častima da će vam slava zablistati po svoj zemlji.\"');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 15, 10, 'Godine sto sedamdeset i četvrte krenu kralj Antioh u zemlju svojih otaca. Oko njega su se okupile sve čete, tako da ih je malo ostalo uz Trifona.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 15, 11, 'Antioh je udario za njim u potjeru. Trifon je pobjegao u Doru na moru,');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 15, 12, 'jer je znao da se na njega svalilo zlo i da su ga čete ostavile.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 15, 13, 'Antioh se utaborio kod Dore sa sto i dvadeset tisuća pješaka i osam tisuća konjanika.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 15, 14, 'Opkolio je grad, pritisnuo ga s kopna i mora, jer se brodovlje približilo s morske strane, tako da nitko nije mogao niti ulaziti niti izlaziti.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 15, 15, 'Uto je Numenije sa svojom pratnjom došao iz Rima s pismima za kraljeve i zemlje. Evo njihova sadržaja:');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 15, 16, '\"Rimski konzul Lucije pozdravlja kralja Ptolemeja.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 15, 17, 'Veliki svećenik Šimun i židovski narod uputili su nam židovske poslanike kao prijatelje i saveznike da obnove nekadašnje prijateljstvo i savezništvo.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 15, 18, 'Donijeli su zlatan štit od tisuću mina.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 15, 19, 'Odlučili smo, dakle, pisati kraljevima i zemljama da im ne čine nikakva zla niti da udaraju na njih, na njihove gradove, na njihovu zemlju i da se ne povezuju s onima koji bi ih napadali.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 15, 20, 'Odlučili smo da od njih primimo štit.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 15, 21, 'Ako su, dakle, kakvi opaki ljudi utekli iz njihove zemlje k vama, predajte ih velikom svećeniku Šimunu da ih kazni po njihovim zakonima!\"');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 15, 22, 'Tako je pisao kralju Demetriju, Atalu, Ariaratu, i Arsaku');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 15, 23, 'i u sve zemlje: Sampsami, Spartancima, u Delos, u Mindos, u Sikion, U Kariju, u Samos, u Pamfiliju, u Likiju, u Halikarnas, u Rodos, u Faselidu, u Kos, u Sidu, u Arad, Gortinu, Knidos, Cipar i Kirenu.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 15, 24, 'Prijepis tih pisama poslali su velikom svećeniku Šimunu.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 15, 25, 'Antioh je taborio pred Dorom, u njezinu predgrađu, pa je neprestano upućivao nove odrede protiv grada i izrađivao bojne naprave. Stisnuo je Trifona tako da se nije moglo niti izlaziti niti ulaziti.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 15, 26, 'Šimun mu je poslao dvije tisuće odabranih ljudi da mu pomažu u boju, a k tomu srebra i zlata i mnogo opreme.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 15, 27, 'On toga ne htjede primiti. Štoviše, poništio je sve što je prije sa Šimunom ugovorio. Posve se izmijenio prema njemu.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 15, 28, 'Poslao je k njemu Atenobija, jednog od svojih prijatelja, da se s njim porazgovori i reče mu: \"Vi držite u svojoj vlasti Jopu, Gezer i jeruzalemsku Tvrđu, gradove moga kraljevstva.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 15, 29, 'Njihova ste područja opustošili, počinili ste mnogo zla u zemlji i zavladali mnogim krajevima u mom kraljevstvu.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 15, 30, 'Zato sad vratite gradove koje ste osvojili, zajedno s porezima onih krajeva kojima ste zavladali izvan židovskih granica.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 15, 31, 'Ako pak nećete, dajte mjesto toga pet stotina srebrnih talenata, a za štete što ste ih počinili i za poreze gradova drugih pet stotina talenata; ako ni toga nećete, poći ćemo protiv vas u rat.\"');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 15, 32, 'Kraljev je prijatelj Atenobije došao u Jeruzalem i vidio Šimunov sjaj i ormar sa zlatnim i srebrnim posuđem i mnogu poslugu. On se zapanjio. Saopćio mu je kraljevu poruku.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 15, 33, 'Šimun mu odgovori ovako: \"Mi nikako nismo oteli tuđu zemlju niti smo zavladali tuđim dobrima, nego je to baština naših otaca: naši su je neprijatelji nepravedno stanovito vrijeme posjedovali.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 15, 34, 'Mi smo pak, koristeći se povoljnim prilikama, ponovo osvojili baštinu svojih predaka.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 15, 35, 'Što se tiče Jope i Gezera, koje ti tražiš, ti su gradovi mnogo mučili narod i pustošili nam zemlju, za njih ćemo dati stotinu talenata.\"');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 15, 36, 'Poslanik mu na to nije odgovorio ni riječi. Vratio se gnjevan kralju i upoznao ga sa Šimunovim odgovorom i veličanstvom, ukratko, sa svim što je vidio, a kralj nato usplamtje gnjevom.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 15, 37, 'Trifon se ukrcao u lađu i pobjegao u Ortosiju.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 15, 38, 'Kralj je Kendebeja postavio za upravitelja primorja i predao mu pješačke i konjaničke čete.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 15, 39, 'Zapovjedio mu je da se utabori pred Judejom i naložio mu da izgradi Kedron, učvrsti mu vrata i zavojšti na narod. Kralj je pošao u potjeru za Trifonom.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 15, 40, 'Kendebej je došao u Jamniju i počeo uznemirivati narod, provaljivati u Judeju, odvoditi narod u roblje i ubijati ga.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 15, 41, 'Ponovo je izgradio Kedron te u nj smjestio konjanike i pješake da provaljuju i obilaze judejskim putovima, kako mu bješe zapovjedio kralj.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 16, 1, 'Ivan uzađe iz Gezera i javi svom ocu Šimunu što radi Kendebej.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 16, 2, 'Šimun tada dozva svoja dva najstarija sina, Judu i Ivana, i reče im: \"Moja braća i ja, i moj očinski dom, vojevali smo protiv Izraelovih neprijatelja od mladosti do današnjeg dana i uspjeli smo više puta izbaviti Izraela.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 16, 3, 'Sad sam ja ostario, a vi ste se po Milosti dohvatili snage: stanite, dakle, na moje mjesto i na mjesto mog brata! Idite i borite se za naš narod, i nebeska pomoć neka bude s vama!\"');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 16, 4, 'Tada izabra u zemlji dvadeset tisuća pješaka i konjanike te odoše na Kendebeja. Prenoćili su u Modinu.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 16, 5, 'Uranivši ujutro, krenuli su u ravnicu, i gle, ide na njih velika vojska, pješaci i konjanici. Među njima bijaše potok.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 16, 6, 'Ivan sa svojim ljudima zauze položaj nasuprot neprijateljima. A kad je vidio da se narod boji prijeći preko potoka, sam prijeđe prvi. Ljudi, videći ga, prijeđoše za njim.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 16, 7, 'Razdijelio je vojsku i konjanike pomiješao među pješake, jer je neprijateljskih konjanika bilo vrlo mnogo.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 16, 8, 'Odjeknuše trube. Kendebej sa svojom vojskom pobježe. Mnogi su poginuli, a oni koji su se spasili pobjegoše put tvrđave.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 16, 9, 'Tada bi ranjen Ivanov brat Juda. Ivan ih je pak gonio dok Kendebej nije stigao do Kedrona, što ga je sam utvrdio.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 16, 10, 'Pobijeđeni su utekli do kula u poljima Azota, a pobjednik ih zapali. Od njih pade oko dvije tisuće ljudi. Ivan se mirno vratio u Judeju.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 16, 11, 'Abubov sin Ptolemej postavljen je upraviteljem u jerihonskoj ravnici. Imao je mnogo srebra i zlata,');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 16, 12, 'jer je bio zet velikog svećenika.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 16, 13, 'Njegovo se srce uzoholilo. Naumio je da zavlada zemljom i stvarao je vjerolomne osnove protiv Šimuna i njegovih sinova.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 16, 14, 'Šimun je obilazio gradove u zemlji nadzirući ih i brinući se za upravu. Tako je došao u Jerihon sa svojim sinovima Matatijom i Judom godine sto sedamdeset i sedme, jedanaestog mjeseca, a to je mjesec Sabat.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 16, 15, 'Abubov ih sin prijevarom namami u tvrđavicu zvanu Dok, koju je on i sagradio. Pripravio im je veliku gozbu, ali je ondje sakrio ljude.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 16, 16, 'Kad se Šimun sa svojim sinovima napio, ustao je Ptolemej sa svojim ljudima, uzeo oružje, navalio na Šimuna u blagovalištu i ubio njega, njegove sinove i neke od njihove posluge.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 16, 17, 'Tako je počinio veliku nevjeru, dobro uzvratio zlom.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 16, 18, 'Ptolemej je o tom pismeno obavijestio kralja da mu pošalje u pomoć čete i preda mu gradove i zemlju.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 16, 19, 'Druge je poslao u Gezer da maknu Ivana te je pismeno naložio zapovjednicima vojske da dođu k njemu da im dade srebra, zlata i darova.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 16, 20, 'Ostale je poslao da zauzmu Jeruzalem i hramsku goru.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 16, 21, 'Ali je netko potrčao naprijed i Ivanu u Gezeru javio da su mu poginuli otac i braća. Dodao je: \"I poslao je nekoga da ubije i tebe.\"');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 16, 22, 'Na tu se vijest Ivan razgnjevi. Uhvatio je ljude koji su došli da ga ubiju te ih je pogubio, jer je znao da ga žele ubiti.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 16, 23, 'Ostala Ivanova djela, njegovi ratovi i junaštva što ih je izvršio, bedemi koje je sagradio i ostali njegovi pothvati,');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 16, 24, 'sve je to zapisano u Ljetopisima njegova vrhovnog svećeništva, od dana kada je poslije svog oca postao velikim svećenikom.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (21, 1, 1, 'Braću Židove u Egiptu pozdravljaju njihova braća Židovi iz Jeruzalema i iz židovske zemlje i žele im nepomućeni mir.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (21, 1, 2, 'Obasuo vas Bog dobročinstvima i spomenuo se svog Saveza s Abrahamom, Izakom i Jakovom, svojim vjernim slugama!');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (21, 1, 3, 'Dao vam svima srce da ga štujete i njegovu volju vršite velikodušno i radosno!');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (21, 1, 4, 'Otvorio vaše srce svom Zakonu i svojim zapovijedima i dao vam mir!');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (21, 1, 5, 'Uslišao vam molitve, pomirio se s vama i ne ostavio vas u vrijeme nevolje!');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (21, 1, 6, 'U ovaj trenutak mi se ovdje za vas molimo.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (21, 1, 7, 'Za kraljevanja Demetrijeva godine sto šezdeset i devete mi smo vam Židovi pisali ovo: \"U nevoljama i jadima koji su zaredali u ovim godinama otkako su Jason i njegove pristalice izdali Svetu zemlju i kraljevstvo,');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (21, 1, 8, 'zapalili Velika vrata i prolili nevinu krv, pomolili smo se Gospodinu i on nas je uslišao. Prinijeli smo žrtvu i najfinije brašno, upalili svjetiljke i postavili hljebove.\"');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (21, 1, 9, 'Sad vam pišemo da biste u mjesecu Kislevu svetkovali Blagdan sjenica. Godine sto osamdeset i osme.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (21, 1, 10, 'Stanovnici Jeruzalema i stanovnici Judeje, starješine i Juda: savjetniku kralja Ptolemeja Aristobulu, od roda pomazanih svećenika, i Židovima u Egiptu pozdrav i dobro zdravlje!');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (21, 1, 11, 'Neka je velika hvala Bogu, koji nas je izbavio iz velikih pogibli kad smo imali vojevati protiv kralja.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (21, 1, 12, 'On je doista odbio one koji su zavojevali na Sveti grad.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (21, 1, 13, 'Kad im je zapovjednik otišao u Perziju, sasjekli su u Nanejinu hramu i njega i njegovu vojsku, koja se smatrala nepobjedivom. Nanejini svećenici poslužili su se varkom.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (21, 1, 14, 'Antioh je onamo došao sa svojim prijateljima pod izlikom da će se oženiti Nanejom, a zapravo da, u ime miraza, prisvoji veliko tamošnje blago.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (21, 1, 15, 'Nanejski su svećenici izložili blago. Čim je Antioh s nekolicinom ušao u hramsko predvorje, svećenici zatvoriše svetište.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (21, 1, 16, 'Otvoriše tajna vrata na stropu, baciše kamenje i ubiše zapovjednika. Sasjekoše ga na komade, a glave baciše onima koji bijahu vani.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (21, 1, 17, 'Neka je za sve to hvaljen naš Bog, koji je bezbožnike predao smrti.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (21, 1, 18, 'Dvadeset i petog Kisleva svetkovat ćemo očišćenje Hrama, pa smo smatrali uputnim da vas o tom obavijestimo, kako biste i vi prikladno svetkovali Blagdan sjenica i vatre koja se pokazala kad je Nehemija, sagradivši Svetište i žrtvenik, prinio žrtve.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (21, 1, 19, 'Kad su, naime, naše oce odvodili u Perziju, tadašnji su pobožni svećenici uzeli žrtvenu vatru i sakrili je u udubinu sličnu presahlu bunaru. Spremili su je tako da nitko za to skrovište ne sazna.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (21, 1, 20, 'Poslije mnogo godina bi Božja volja da perzijski kralj pošalje Nehemiju: ovaj je dao da vatru potraže potomci onih svećenika koji su je sakrili. Ti izvijestiše da nisu našli vatre nego nekakvu muljevitu vodu, a on im zapovjedi da je zahvate i donesu.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (21, 1, 21, 'Pošto je bilo pripravljeno sve za žrtvu, naloži Nehemija svećenicima da tom vodom poškrope drva i što je na njima.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (21, 1, 22, 'Tek što su to učinili, u trenutku zasja sunce, dotad zastrto oblakom, i buknu velika vatra, tako te se svi zadiviše.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (21, 1, 23, 'Dok je žrtva izgarala, svećenici su molili - svećenici i sav narod. Započinjao je Jonatan, a drugi su, zajedno s Nehemijom, nastavljali.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (21, 1, 24, 'Molitva je glasila ovako: \"Gospode, Gospode Bože, stvoritelju svega, strašni, jaki, pravedni, milosrdni, jedini kralju, jedini dobri,');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (21, 1, 25, 'jedini darežljivi, jedini pravedni, svemogući i vječni, koji spasavaš Izraela od svakog zla, koji si naše oce izabrao i posvetio,');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (21, 1, 26, 'primi ovu žrtvu za sav svoj izraelski narod. Čuvaj svoju baštinu i posveti je!');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (21, 1, 27, 'Sakupi one od nas koji su razasuti, izbavi one što robuju među poganima, pogledaj milostivo prezrene i pogrđene, tako da pogani spoznaju da si ti naš Bog!');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (21, 1, 28, 'Kazni one koji nas ugnjetavaju i drsko vrijeđaju!');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (21, 1, 29, 'Usadi svoj narod u svoje Sveto mjesto, kao što je rekao Mojsije!\"');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (21, 1, 30, 'Svećenici pak pjevahu hvalospjeve.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (21, 1, 31, 'Kad je izgorjela žrtva, zapovjedi Nehemija da se preostala voda izlije na veliko kamenje.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (21, 1, 32, 'Kad su to izvršili, liznu plamen, ali ga upi jači sjaj vatre na žrtveniku.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (21, 1, 33, 'Razglasilo se to, i kralju perzijskom bi javljeno da se na mjestu gdje svećenici, odvedeni u sužanjstvo, bijahu sakrili oganj pojavila voda kojom su Nehemija i njegovi ljudi posvetili žrtve.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (21, 1, 34, 'Kralj nato provjeri događaj, dade ograditi to mjesto i uspostaviti svetište.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (21, 1, 35, 'Onima kojima ga je prepustio dao je udio u velikim prihodima koje je odande izvlačio.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (21, 1, 36, 'Nehemija i njegovi ljudi to su mjesto prozvali Neftar, što znači \"očišćenje\", ali se ono općenito zove Neftaj.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (21, 2, 1, 'U spisima se nalazi kako je prorok Jeremija prisilno iseljenima zapovjedio da uzmu vatre, kako je već spomenuto,');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (21, 2, 2, 'i kako je tim prisilno iseljenima prorok preporučio, kad im je davao Zakon, da ne zaborave zapovijedi Gospodnjih i ne zastrane vjerom kad budu gledali ukrašene zlatne i srebrne likove.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (21, 2, 3, 'Takvim i sličnim riječima opominjaše ih da ne odvrgnu Zakon od srca.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (21, 2, 4, 'U tom je spisu pisalo kako je prorok po Božjem nadahnuću sa sobom ponio Šator i Kovčeg saveza, pa se uspeo na goru na koju se bio popeo Mojsije i odakle je motrio Božju baštinu.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (21, 2, 5, 'Stigavši onamo, Jeremija nađe stan u pećini, unese u nj Šator i Kovčeg i kadioni žrtvenik, a ulaz zagradi.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (21, 2, 6, 'Neki od njegovih pratilaca došli su zatim da označe put, ali ga nisu mogli naći.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (21, 2, 7, 'Kad je to saznao Jeremija, prekorio ih je ovako: \"Ovo mjesto bit će nepoznato sve dok Bog ponovo ne sabere svoj narod i ne smiluje mu se.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (21, 2, 8, 'Tada će Gospodin ponovo pokazati sve ove predmete i vidjet će se Gospodinova slava i Oblak, kao što se pojavio za Mojsija i kad je Salomon molio da hram bude veličanstveno posvećen.\"');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (21, 2, 9, 'Tu se također pripovijedalo kako je Salomon, nadaren mudrošću, prinio žrtvu posvete i završetka Hrama.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (21, 2, 10, 'Isto onako kako je Mojsije molio Gospodina i s neba siđe oganj i sažga žrtvu, tako je i Salomon molio te je oganj sišao i sagorio žrtve.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (21, 2, 11, 'Mojsije bijaše rekao: \"Zato što se nije pojela, okajnica je spaljena.\"');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (21, 2, 12, 'Tako je i Salomon svetkovao osam dana.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (21, 2, 13, 'O tome se pripovijeda i u spisima i uspomenama Nehemijinim, i još kako je on, sastavljajući knjižnicu, sakupio knjige o kraljevima, o prorocima i o Davidu, a tako i darovnice kraljeva.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (21, 2, 14, 'Isto je tako Juda sabrao sve knjige, razasute zbog rata koji se vodio protiv nas, i sad su u našim rukama.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (21, 2, 15, 'Ako vam, dakle, trebaju, pošaljite nam glasnike da vam ih donesu.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (21, 2, 16, 'Pišemo vam zato što namjeravamo svetkovati očišćenje Hrama. Bilo bi, dakle, lijepo da i vi te dane svetkujete.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (21, 2, 17, 'Bog je spasio sav svoj narod i svima dao baštinu, kraljevstvo, svećeništvo i Svetište - pa će nam se Bog, kako se nadamo');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (21, 2, 18, 'jer je Zakonom obećao, uskoro smilovati i sabrati nas iz krajeva pod nebom na Sveto mjesto. On nas je izbavio iz velikih zala i očistio mjesto.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (21, 2, 19, 'Povijest Jude Makabeja i njegove braće, očišćenje velikog Hrama, obnovu žrtvenika;');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (21, 2, 20, 'zatim bojeve protiv Antioha Epifana i njegova sina Eupatora;');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (21, 2, 21, 'nadalje, nebeska ukazanja u prilog junaka koji su se velikodušno borili za židovstvo, tako da su, premda malobrojni, oplijenili svu zemlju i barbarske horde natjerali u bijeg;');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (21, 2, 22, 'zatim kako su ponovo osvojili Svetište, slavno u svem svijetu, oslobodili Grad, uspostavili zakone kojima je prijetilo ukinuće, jer im se Gospod smilovao sa svom svojom blagošću;');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (21, 2, 23, 'sve je to Jason Cirenac ocrtao u pet knjiga, a mi ćemo pokušati da zbijemo u jedno djelo.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (21, 2, 24, 'S obzirom na obilje brojeva i na teškoću na koju, zbog opsežnosti građe, nailaze oni koji se upuštaju u povijesna izlaganja,');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (21, 2, 25, 'nastojali smo pružiti duhovnu okrepu onima koji žele čitati, lako štivo onima koji bi te činjenice htjeli upamtiti, a svima bez razlike korist.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (21, 2, 26, 'Nama koji smo se latili mučnog posla skraćivanja ono nije laka zadaća nego rad koji stoji znoja i bdjenja.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (21, 2, 27, 'Ali kao što nije lako onome koji priređuje gozbu i nastoji zadovoljiti druge, i mi ćemo, da zaslužimo zahvalnost mnogih, radosno podnijeti ovaj mučni posao.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (21, 2, 28, 'Prepuštajući povjesničaru brigu da podrobno opisuje svaki događaj, mi ćemo se truditi da dademo pojednostavnjen prikaz.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (21, 2, 29, 'Kao što se graditelj nove kuće mora pobrinuti za čitavu zgradu, a onaj koji je ukrašuje i oslikava voštanim bojama treba da misli što dolazi u obzir za ukrašivanje, tako treba da bude u našem poslu.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (21, 2, 30, 'Udubiti se u stvar, istraživati izvore i zalaziti u pojedinosti - to je dužnost pisca povijesti.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (21, 2, 31, 'A onomu koji sažima treba dopustiti da bude kratak u izlaganju, kloneći se iscrpne povijesti.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (21, 2, 32, 'Počnimo, dakle, izlaganje, kad smo se toliko zadržali na predgovoru; bilo bi glupo razvlačiti predgovor povijesti, a zbijati samu povijest.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (21, 3, 1, 'Dok se u Svetom gradu živjelo u potpunom miru i dok su se ondje najstrože obdržavali zakoni, i to zbog pobožnosti velikog svećenika Onije i njegove mržnje na zlo,');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (21, 3, 2, 'događalo se da su i sami kraljevi poštovali Sveto mjesto i častili Hram najdragocjenijim darovima.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (21, 3, 3, 'Tako je azijski kralj Seleuk iz vlastitih dohodaka namirivao sve troškove koji su bili potrebni za bogoslužne žrtve.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (21, 3, 4, 'Ali neki Šimun iz Bilgina plemena, postavši hramskim predstojnikom, zavadi se s velikim svećenikom zbog gradskoga tržnog nadzora.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (21, 3, 5, 'Kako nije mogao pobijediti Oniju, ode k Apoloniju iz Tarsa, koji je u to vrijeme bio upravitelj u Celesiriji i Feniciji.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (21, 3, 6, 'Priopći mu kako je jeruzalemska riznica krcata neizrecivim blagom, tako da mu se količina ne može ustanoviti, i kako to sve nije potrebno za troškove žrtvovanja te bi se moglo prebaciti u kraljevsko vlasništvo.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (21, 3, 7, 'Prigodom jednog sastanka s kraljem Apolonije ga obavijesti o prokazanom blagu, a kralj izabra Heliodora, svoga državnog upravitelja, i posla ga s nalogom da preuzme spomenuto blago.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (21, 3, 8, 'Heliodor odmah krenu na put, pod izlikom da će izvršiti nadzor nad gradovima Celesirije i Fenicije, a uistinu da izvrši kraljev nalog.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (21, 3, 9, 'Kad je došao u Jeruzalem i kad su ga vrhovni svećenik i grad ljubezno primili, priopći o prijavi i objasni radi čega je došao, pa poče ispitivati je li uistinu tako.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (21, 3, 10, 'Veliki mu svećenik objasni da su to pohrane udovica i siročadi;');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (21, 3, 11, 'a nešto od toga da pripada Hirkanu, Tobijinu sinu, veoma uglednu čovjeku, te da, suprotno od klevetničke izjave opakog Šimuna, ima svega četiri stotine talenata srebra i dvije stotine talenata zlata.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (21, 3, 12, 'Nikako nije dopušteno da se oštete oni koji su se pouzdali u svetost mjesta, u dostojanstvo i nepovredivost Hrama koji je poštovan u svem svijetu.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (21, 3, 13, 'Ali je Heliodor, zbog kraljevih naloga, rekao da se blago svakako mora preuzeti u kraljevsku blagajnu.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (21, 3, 14, 'Na dan koji je za to odredio ušao je da popiše blago. U gradu je nastala povelika uznemirenost.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (21, 3, 15, 'Svećenici su se u svećeničkoj odjeći bacili ničice pred žrtvenik i zavapili prema nebu, Tvorcu zakona o pohrani, moleći ga da sačuva netaknuta dobra onima koji su ih pohranili.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (21, 3, 16, 'Pogled na lice velikog svećenika razdirao je srce: njegov izgled i bljedilo lica odavalo je duševnu tjeskobu.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (21, 3, 17, 'Obuzeo ga strah te je drhtao cijelim tijelom, a to je onima koji su ga gledali kazivalo koliko mu srce pati.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (21, 3, 18, 'Ljudi su hrlili hrpimice iz kuća na skupnu molitvu, jer je Svetom mjestu prijetilo oskvrnuće.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (21, 3, 19, 'Žene, potpasavši kostrijet ispod grudi, grnule na ulice. Štoviše, i djevojke, zatvorene u kućama, istrčale jedne na vrata, druge na zidove, neke se naginjale kroz prozore,');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (21, 3, 20, 'a sve pružale ruke prema nebu, na molitvu.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (21, 3, 21, 'Bilo je žalosno vidjeti posvuda prostrto mnoštvo i tjeskobu velikog svećenika zbog onoga što će doći.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (21, 3, 22, 'Dok su s jedne strane zazivali svemogućeg Gospoda da povjerene pologe potpuno netaknute sačuva vlasnicima,');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (21, 3, 23, 's druge je strane Heliodor izvršivao ono što se odlučilo.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (21, 3, 24, 'Već je on stigao sa svojom pratnjom pred riznicu, kad se ukaza Gospodar duhova i svih vlasti u takvu veličanstvu da je sve koji se usudiše onamo ići udarila Božja sila te su zapali u nemoć i strah.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (21, 3, 25, 'Pred očima im se pojavi konj s prekrasnim sedlom, a na njem strašan jahač: žestoko se propinjući, konj je udarao Heliodora prednjim kopitima. Onaj koji je sjedio na njemu kao da je bio u zlatnu oklopu.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (21, 3, 26, 'U isto vrijeme ukazala mu se dva druga mladića, vrlo snažna, sjajne ljepote, u veličanstvenoj odjeći. Pristupiše Heliodoru, jedan s jedne a drugi s druge strane, i stadoše ga bez daha bičevati tučom udaraca.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (21, 3, 27, 'Heliodor pade na zemlju; obavi ga gusta tama, a oni ga pograbiše i staviše na nosila.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (21, 3, 28, 'I tako su tog čovjeka, koji je čas prije ušao u spomenutu riznicu s mnogobrojnom pratnjom i cijelom tjelesnom stražom, iznijeli bespomoćna, i po tome svi jasno uvidješe Božju silu.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (21, 3, 29, 'Dok je on, udaren Božjom moći, ležao bez riječi i lišen svake nade u spasenje,');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (21, 3, 30, 'Židovi su veličali Gospodina koji je čudesno proslavio svoje Sveto mjesto. A Hram, trenutak prije pun straha i nemira, sada, kad se očitovao Svevladar Gospodin, prelijevao se radošću i veseljem.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (21, 3, 31, 'Neki od Heliodorovih pratilaca brzo su zatražili Oniju da moli Svevišnjega neka podari život onomu što je ležao na izdisaju.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (21, 3, 32, 'Bojeći se da kralj možda ne bi posumnjao da su Židovi napakostili Heliodoru, veliki svećenik prinese žrtvu za spas toga čovjeka.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (21, 3, 33, 'Dok je veliki svećenik prinosio žrtvu pomirnicu, Heliodoru se opet ukazaše oni isti mladići u istoj odjeći. Stadoše preda nj i rekoše mu: \"Budi vrlo zahvalan velikom svećeniku Oniji, jer ti je Gospodin samo po njemu podario život.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (21, 3, 34, 'A ti, koga je Nebo izbičevalo, razglasuj svima veličanstvenu Božju silu!\" To rekavši, iščeznuše.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (21, 3, 35, 'Heliodor prinese žrtvu Gospodinu i učini velike zavjete Onomu koji mu je poklonio život, pa se ljubezno oprosti s Onijom i vrati se kralju sa svojom vojskom.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (21, 3, 36, 'Svjedočio je pred svima o djelima svevišnjeg Boga koja je vidio svojim očima.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (21, 3, 37, 'Kad ga je kralj upitao koji mu se čovjek čini prikladan da se još jednom pošalje u Jeruzalem, Heliodor odgovori:');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (21, 3, 38, '\"Ako imaš kakva neprijatelja ili kakva zavjerenika protiv države, pošalji ga onamo da ti se izbičevan vrati, ako uopće iznese živu glavu, jer uistinu na onome mjestu vlada Božja sila.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (21, 3, 39, 'Onaj koji stoluje na nebu, bdi nad onim mjestom i brani ga, a one koji onamo zlonamjerno pristupaju bije i uništava.\"');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (21, 3, 40, 'To su, eto, događaji s Heliodorom i očuvanjem svete riznice.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (21, 4, 1, 'Spomenuti Šimun, izdajnik blaga i domovine, okleveta Oniju da je rovario protiv Heliodora i upriličio onu nesreću.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (21, 4, 2, 'Dobročinitelja grada, zaštitnika svojih sunarodnjaka, revnitelja za zakone on se usudio nazvati državnim neprijateljem.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (21, 4, 3, 'Mržnja se toliko raspirila da je neki Šimunov pristaša počinio umorstva.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (21, 4, 4, 'Onija je bio svjestan da je takvo suparništvo mučno i da Menestejev sin Apolonije, upravitelj Celesirije i Fenicije, potiče Šimuna na zloću;');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (21, 4, 5, 'zato se uputi kralju, ne da svoje sugrađane tuži, nego radi opće i pojedinačne koristi sveg naroda.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (21, 4, 6, 'Zapravo je dobro vidio da je bez kraljeva posredovanja već nemoguće održavati javni mir i da se Šimun neće okaniti svoje ludosti.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (21, 4, 7, 'Kad je Seleuk preminuo a kraljevstvo preuzeo Antioh nazvan Epifan, Onijin brat Jason gledaše da se dočepa velikog svećeništva.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (21, 4, 8, 'Sastavši se s kraljem, obeća mu tri stotine i šezdeset talenata srebra i još osamdeset talenata na ime drugog dohotka.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (21, 4, 9, 'Osim toga, obećao je da će platiti još stotinu i pedeset talenata ako mu se dopusti da na svoju ruku podigne gimnazij i efebij i da Jeruzalemcima podijeli antiohijsko građanstvo.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (21, 4, 10, 'Kad je kralj pristao, Jason, čim se dočepao vlasti, prevede svoje sunarodnjake grčkome načinu života.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (21, 4, 11, 'Ukide sloboštine koje je kralj iz čovjekoljublja bio podijelio Židovima posredstvom Ivana, oca Eupolemova - to je onaj Eupolem koji će kasnije poći u poslanstvu da s Rimljanima sklopi prijateljstvo i savez. Ukratko, rušio je zakonite građanske ustanove i uvodio nove protuzakonite običaje.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (21, 4, 12, 'Namjerno je dao ispod tvrđave sagraditi borilište, a sam je najbolje efebe vodio pod petazom.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (21, 4, 13, 'Zbog pokvarenosti bezbožnog Jasona, koji nije bio nikakav svećenik, helenizam je tako ojačao a strana moda uzela toliko maha');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (21, 4, 14, 'da svećenici više u službi oko žrtvenika nisu pokazivali nikakve revnosti, nego su se, prezirući Hram i zanemarujući žrtve, na poziv zvečke žurili na Zakonom nedopuštene priredbe u kazalištu.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (21, 4, 15, 'Ne držeći ništa do časti svoje zemlje, vrlo su visoko cijenili helenske počasti.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (21, 4, 16, 'Zato ih je upravo snašla teška nevolja: postadoše im neprijatelji i krvnici baš oni koje su živo nastojali nasljedovati u načinu života i u svemu im biti slični.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (21, 4, 17, 'Božji se zakoni ne krše nekažnjivo, a to će pokazati iduće razdoblje.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (21, 4, 18, 'Kad su se u Tiru, u kraljevoj nazočnosti, održavala petogodišnja natjecanja,');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (21, 4, 19, 'poslao je zločinački Jason kao gledaoce one Jeruzalemce koji su imali antiohijsko građanstvo; sa sobom su nosili trista srebrnih drahma za žrtvu Heraklu. No čak i oni koji su ih nosili smatrali su da ih nije zgodno upotrijebiti za žrtvu nego za nešto drugo.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (21, 4, 20, 'Tako je, dakle, novac koji je pošiljalac odredio za žrtvu Heraklu, odlukom onih koji su ga nosili, potrošen za gradnju brodova sa tri reda vesala.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (21, 4, 21, 'Menestejev sin Apolonije bi poslan u Egipat da pribiva ustoličenju kralja Filometora. Antioh je doznao da kralj ne odobrava njegovih pothvata, pa se stao brinuti za svoju sigurnost. Zato je došao u Jopu, odakle se zaputio u Jeruzalem.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (21, 4, 22, 'Veličanstveno su ga primili Jason i grad i uveli ga uza zublje i klicanje. Poslije isto tako uđe s vojskom u Feniciju.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (21, 4, 23, 'Poslije tri godine Jason posla Menelaja, brata spomenutog Šimuna, da kralju odnese novaca i da ga podsjeti na rješenje nekih hitnih poslova.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (21, 4, 24, 'A Menelaj pristupi kralju s preporukama i, dajući dojam ugledna čovjeka, isposlova sebi velikosvećeničku čast, nudeći tri stotine srebrnih talenata više nego Jason.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (21, 4, 25, 'Primivši, dakle, kraljevske naloge, vrati se a da na njemu nije bilo ničega što bi bilo dostojno velikosvećeništva: donio je sa sobom samo jarost nasilnika i bijes divlje zvijeri.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (21, 4, 26, 'I tako je Jasona, koji je potkopao vlastitog brata, potkopao drugi, pa je morao pobjeći u Amanitidu.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (21, 4, 27, 'Menelaj se, doduše, čvrsto držao vlasti, ali kralju nije nikako plaćao obećanih svota,');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (21, 4, 28, 'iako je to od njega zahtijevao Sostrat, zapovjednik tvrđave, koji je bio ovlašten da utjeruje dohotke. Zato su obojica pozvana kralju.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (21, 4, 29, 'Menelaj je morao prepustiti veliko svećeništvo u nasljedstvo bratu Lizimahu, a Sostrata je zamijenio Krates, zapovjednik Ciprana.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (21, 4, 30, 'Dok se to zbivalo, pobunili se Taršani i Malošani zbog toga što su im gradove darovali u miraz kraljevoj inoči Antiohidi.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (21, 4, 31, 'Kralj je, dakle, brže otišao da ih smiri, a kao zamjenika ostavi Andronika, jednog od velikih dostojanstvenika.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (21, 4, 32, 'Menelaj, računajući da mu se pružila zgodna prilika, prisvoji nešto zlatnog posuđa iz Hrama i darova ga Androniku, a drugo porasproda u Tiru i susjednim gradovima.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (21, 4, 33, 'Kad je Onija o tom primio točne obavijesti, oštro ga prekori, pošto se prije povukao u grad-utočište Dafnu kod Antiohije.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (21, 4, 34, 'Stoga je Menelaj nasamo zamolio Andronika da Oniju ubije. Ovaj dođe k Oniji, prijevarom ga namami pruživši mu desnicu na zakletvu, i Onija, sumnjajući doduše, iziđe iz utočišta, a on ga smjesta ubi, ne mareći za pravdu.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (21, 4, 35, 'Zbog nepravednog umorstva toga čovjeka silno su se ogorčili i ožalostili ne samo Židovi nego i mnogi pripadnici drugih naroda.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (21, 4, 36, 'Kad se kralj vratio iz cilicijskih krajeva, dođe preda nj poslanstvo Židova iz različitih gradova te mu se potuži; njima su se pridružili i Grci, jer su i oni negodovali zbog okrutnog umorstva Onije.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (21, 4, 37, 'Antioh, jako ožalošćen i ganut, zaplaka sjećajući se pokojnikove mudrosti i razboritosti.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (21, 4, 38, 'Planu gnjevom i smjesta s Andronika skinu grimizni plašt, razdera mu odijelo i provede ga čitavim gradom sve do onog mjesta gdje je bezbožno ubio Oniju; tu ubojicu smaknuše. Tako ga je Gospodin kaznio onako kako je zaslužio.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (21, 4, 39, 'Lizimah je s Menelajevim znanjem u gradu počinio mnogo svetogrdnih krađa. Kad se o tom nadaleko proširio glas, puk se diže protiv Lizimaha, ali se već mnogo zlatnine raznijelo.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (21, 4, 40, 'Protiv pobunjenog mnoštva, gnjevom raspaljena, Lizimah naoruža oko tri tisuće ljudi i prvi poče vršiti nasilja, u kojima je četovođa bio neki Auran, čovjek poodmakle dobi i nipošto manje bezumnosti.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (21, 4, 41, 'Kad su ljudi vidjeli da će ih Lizimah napasti, pograbiše jedni kamenje, drugi toljage, a neki zagrabiše pune ruke pepela koji se ondje nalazio, pa svi hrpimice navališe na Lizimahove ljude.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (21, 4, 42, 'Mnoge su ranili, neke ubili, ostale natjerali u bijeg, a samoga oskvrnitelja izmrcvarili kraj riznice.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (21, 4, 43, 'Zbog toga bi podignuta tužba protiv Menelaja.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (21, 4, 44, 'Kad je kralj došao u Tir, tri su čovjeka što ih je poslalo veliko vijeće branila pravednost svoje stvari.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (21, 4, 45, 'Menelaj, videći da će izgubiti, obeća Dorimenovu sinu Ptolemeju mnogo novaca ako za njegovu stvar predobije kralja.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (21, 4, 46, 'Ptolemej odvede kralja pod neki trijem da se tobože ondje rashladi i skloni ga da promijeni odluku.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (21, 4, 47, 'I doista, Menelaja, krivca svega zla, kralj oslobodi od svih optužbi, dok one bijednike koji bi bili proglašeni nevinima da su svoju stvar branili i kod Skita - osudi na smrt.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (21, 4, 48, 'Tako oni koji su govorili u obranu grada, naroda i svetog posuđa smjesta podniješe nepravednu kaznu.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (21, 4, 49, 'Čak su im i Tirani, zgražajući se nad takvom zloćom, priredili svečani ukop.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (21, 4, 50, 'Zbog lakomosti vlastodržaca Menelaj se ipak održi na vlasti; napredujući u pakosti, postade glavni protivnik svojih sugrađana.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (21, 5, 1, 'U to je vrijeme Antioh pripremao drugu vojnu na Egipat.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (21, 5, 2, 'Gotovo četrdeset dana po svem gradu pojavljivali se konjanici koji su u zlatnim odorama projahivali zrakom; zatim naoružane čete raspoređene u kohorte;');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (21, 5, 3, 'pa konjički odredi svrstani u borbene redove, koji su srljali i napadali jedni na druge; na sve strane zamahivanje štitovima, šuma sulica, mačevi izvučeni iz korica, blještav sjaj zlatnih oklopa i svakojake bojne opreme.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (21, 5, 4, 'Svi su molili da ta pojava bude dobar znak.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (21, 5, 5, 'Uto se pronese lažan glas da je Antioh preminuo. Jason tada uze ništa manje nego tisuću ljudi te iznenada napade grad. Pošto su bili istjerani oni koji su branili zidine i grad već bio zauzet, Menelaj uteče u tvrđavu.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (21, 5, 6, 'Jason je stao nemilice klati svoje sugrađane, ne uviđajući da je uspjeh protiv sunarodnjaka najveći neuspjeh, misleći da stječe pobjedničku slavu nad neprijateljima, a ne nad braćom.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (21, 5, 7, 'Nije se domogao vlasti, nego je sramotno završio svoju izdaju i morao opet tražiti utočište u Amanitidi.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (21, 5, 8, 'Tako se završilo njegovo opako djelo. Optužili su ga kod arapskog vladara Arete te je morao bježati od grada do grada; svi su ga gonili, svi mrzili kao otpadnika od Zakona i proklinjali kao krvnika svoje domovine i svojih sugrađana, dok konačno ne zastade u Egiptu.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (21, 5, 9, 'Tako je on koji je mnoge izagnao iz domovine poginuo u tuđini, otišavši Lakedemoncima ne bi li u ime srodništva našao zaštitu.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (21, 5, 10, 'On koji je toliko ljudi bez sahrane bacio na zemlju ostade neoplakan, bez ukopa i bez mjesta u grobu svojih otaca.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (21, 5, 11, 'Kad je kralj doznao što se dogodilo, pomisli da se Judeja odmetnula. Zato se podiže iz Egipta, zvjerski razjaren u duši, i zauze grad oružanom rukom.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (21, 5, 12, 'Vojnicima zapovjedi da nesmiljeno pobiju sve one koje sretnu i da pokolju one koji uteknu u kuće.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (21, 5, 13, 'Ubijali su mlado i staro, zatirali žene i djecu, klali djevojke i nejačad.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (21, 5, 14, 'U cigla tri dana bilo je osamdeset tisuća žrtava, od čega je četrdeset tisuća palo od udaraca, a isto ih je toliko prodano u roblje.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (21, 5, 15, 'Ni time se nije izdovoljio, nego se drznuo ući u Hram najsvetiji na svem svijetu, a vodio ga Menelaj, izdajica zakona i domovine.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (21, 5, 16, 'Tu je svojim nečistim rukama uzimao sveto posuđe, poganim rukama grabio darove što su ih drugi kraljevi davali za napredak, slavu i dostojanstvo tog mjesta.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (21, 5, 17, 'Antioh se uznio u srcu, ne misleći da se Gospod samo na kratko vrijeme ljuti na građane zbog njihovih grijeha i zato ne haje za Sveto mjesto.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (21, 5, 18, 'I da nije bilo tolikog mnoštva grijeha, i njega bi, čim bi ušao, udarci biča odvratili od drskosti, kao što su odvratili i Heliodora, koga bijaše poslao kralj Seleuk da pregleda riznicu.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (21, 5, 19, 'Ali Gospodin nije izabrao narod radi Svetog mjesta, nego mjesto radi naroda.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (21, 5, 20, 'Zato je i samo mjesto, imajući udjela u narodnim nevoljama, kasnije sudjelovalo i u blagostanju; zapušteno zbog srdžbe Svemogućega, bit će opet u svoj svojoj slavi obnovljeno nakon izmirenja s velikim Gospodinom.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (21, 5, 21, 'Antioh, dakle, iz Hrama odnije tisuću i osam stotina talenata pa se požuri u Antiohiju, misleći u svojoj oholosti da zemlju može učiniti plovnom a more prohodnim - toliko mu se uznijelo srce!');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (21, 5, 22, 'Za nadstojnike, pak, koji će zlostavljati narod ostavi u Jeruzalemu Filipa, po narodnosti Frigijca, po ćudi surovijega od onoga koji ga je postavio;');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (21, 5, 23, 'a na gori Gerizimu Andronika; osim njih još i Menelaja, koji je opakije od drugih gospodovao svojim sugrađanima, a bio je osobito neprijateljski raspoložen prema Židovima.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (21, 5, 24, 'Posla i namjesnika Apolonija na čelu vojske od dvadeset i dvije tisuće ljudi, zapovjedivši mu da sve odrasle pokolje, a žene i mladež proda.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (21, 5, 25, 'Kad je taj došao u Jeruzalem, pretvarajući se kao miroljubiv čovjek, pričeka do svetoga subotnjeg dana; tada, iskoristivši židovski počinak, zapovjedi svojim podređenima da izađu pod oružjem.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (21, 5, 26, 'Sve one koji su došli da vide smotru dade poubijati, a potom je, krstareći s naoružanim vojnicima po gradu, pogubio mnoštvo ljudi.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (21, 5, 27, 'Tada se Juda Makabej povuče sa desetak ljudi u pustinju te su u gorama provodili život kao divlje zvijeri, hraneći se samo zelenjem da se čime ne bi onečistili.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (21, 6, 1, 'Nedugo potom posla kralj Atenjanina Geronta da Židove prisiljava da krše zakone otaca i da se više u svom životu ne ravnaju po Božjim zakonima;');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (21, 6, 2, 'pa da oskvrne jeruzalemski Hram i pridijeli ga Olimpskom Zeusu, a onaj na Gerizimu Zeusu Gostoljubivom, kako su to tražili stanovnici tog mjesta.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (21, 6, 3, 'Narodu je bilo teško i nepodnosivo toliko zlo.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (21, 6, 4, 'Pogani ispuniše Hram raspuštenošću i pijankama. Zabavljali su se s djevojčurama i u svetim se predvorjima upuštali sa ženama. Štoviše, u samu su unutrašnjost unosili koješta zabranjeno.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (21, 6, 5, 'Žrtvenik su natovarili nedopuštenim žrtvama koje su zakoni branili.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (21, 6, 6, 'Čak nije bilo dopušteno svetkovati subotu, niti slaviti djedovske svetkovine otaca, niti se uopće itko smio priznavati Židovom.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (21, 6, 7, 'Naprotiv, silom su ih tjerali na mjesečne žrtvene gozbe u spomen kraljeva rođendana, a kad se slavio Dionizov blagdan, morali su ovjenčani bršljanom izići u Dionizovu povorku.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (21, 6, 8, 'Na Ptolemejev poticaj izišla je naredba da se i u susjednim helenskim gradovima jednako postupa sa Židovima, pa da i oni sudjeluju u obrednim gozbama,');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (21, 6, 9, 'a da se ubiju oni koji ne prihvaćaju helenskih običaja. Bilo je očito kakva je nevolja nastala.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (21, 6, 10, 'Tako su bile izvedene pred sud dvije žene koje su obrezale svoju djecu. Objesili su im dojenčad o dojke te su ih javno vodili gradom, a onda strmoglavili sa zidina.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (21, 6, 11, 'Drugi se sastajali u obližnjim spiljama da potajno svetkuju sedmi dan: prokazali su ih Filipu te ih zajedno spališe; iz poštovanja prema tome svetom danu, oni se nisu ni branili.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (21, 6, 12, 'One kojima će ova knjiga dopasti u ruke molim da zbog ovih nevolja ne klonu duhom; neka znaju da su se progonstva zbila ne na propast nego na popravak našeg naroda.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (21, 6, 13, 'Znak je velike milosti kad se grešnici predugo ne puštaju nekažnjeni, nego ih namah stiže kazna.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (21, 6, 14, 'Dok u drugih naroda Gospod strpljivo čeka da ih kazni onda kad prevrše mjeru grijeha, dotle je s nama odlučio drukčije postupiti;');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (21, 6, 15, 'ne čeka da nas kazni istom kad se već ispuni mjera naših grijeha.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (21, 6, 16, 'Zato nam on nikad ne uskraćuje svog milosrđa niti svoj narod ostavlja, iako ga kažnjava nevoljama.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (21, 6, 17, 'Neka je to dovoljno za opomenu. Nakon ovih nekoliko riječi nastavit ćemo kazivanje.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (21, 6, 18, 'Eleazara, jednog od prvaka među pismoznancima, čovjeka već poodmakle dobi ali otmjene vanjštine, nagovorili su, silom mu otvarajući usta, da jede svinjetinu.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (21, 6, 19, 'Ali je on više volio slavnu smrt nego sramotan život, pa sam dragovoljno pristupi mučilištu.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (21, 6, 20, 'Ali prije ispljunu ono što mu je bilo u ustima, kako treba da postupi svaki onaj koji se odlučno čuva onoga što nije dopušteno okusiti ni po cijenu ljubavi prema životu.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (21, 6, 21, 'Oni koji su predsjedavali tome bezbožnom obrednom obroku, kako su odavna poznavali tog čovjeka, uzeše ga nasamo nagovarati da sa sobom donese mesa koje smije uživati i koje je sam pripravio. Neka se samo pretvara da po kraljevoj zapovijedi jede od žrtvenog mesa.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (21, 6, 22, 'Učini li tako, izbavit će se od smrti njihovim čovjekoljubljem, na koje ih obvezuje staro prijateljstvo.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (21, 6, 23, 'Ali on stvori plemenitu odluku, dostojnu svoje dobi i ugleda svoje časne starosti i sijede glave i besprijekorna života sve od djetinjstva, a još većma dostojnu svetih zakona koje je postavio sam Bog: bez oklijevanja izjavi neka ga samo pošalju u Podzemlje.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (21, 6, 24, '\"Ne dolikuje našoj dobi pretvarati se, pa da mnogi mladići pomisle kako je Eleazar sa devedeset godina prešao na tuđinske običaje.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (21, 6, 25, 'Zbog svog pretvaranja da spasim ono malo prolaznog života, mogli bi i sami zastraniti, a ja bih tako na svoju starost navukao ljagu i sramotu.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (21, 6, 26, 'Jer, sve kad bih sada i umakao ljudskoj kazni, ni živ ni mrtav neću izbjeći rukama Svemogućega.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (21, 6, 27, 'A sada, junački se odričući života, pokazat ću se dostojnim svoje starosti');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (21, 6, 28, 'i mladićima ostaviti plemenit primjer kako se za časne i svete zakone valja spremno i velikodušno izložiti smrti.\" Nakon tih riječi odmah pristupi mučilištu.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (21, 6, 29, 'Oni koji su ga vodili, promijeniše dotadašnju naklonost u mržnju: njegove riječi činile im se ludošću.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (21, 6, 30, 'Kad je već pod udarcima umirao, uzdahnu i reče: \"Gospodin, koji posjeduje sveto znanje, dobro zna da sam se mogao izbaviti od smrti, ali da na svom tijelu podnosim teške muke bičevanja jer u duši radosno sve to podnosim u strahopoštovanju prema njemu.\"');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (21, 6, 31, 'I tako je on preminuo i svojom smrću ostavio ne samo mladeži nego i većini naroda primjer hrabrosti i spomenik kreposti.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (21, 7, 1, 'Uhvatiše tako i sedmoricu braće zajedno s njihovom majkom. Kralj naredi da ih biju bičevima i volovskim žilama: htio ih je prisiliti da jedu zabranjeno svinjsko meso.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (21, 7, 2, 'Jedan od njih progovori u njihovo ime: \"Što nas želiš pitati i od nas saznati? Radije ćemo umrijeti nego da prestupimo zakone svojih otaca!\"');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (21, 7, 3, 'Izvan sebe od bijesa, kralj zapovjedi da se užare tave i kotlovi.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (21, 7, 4, 'Kad ih užariše, zapovjedi da se, naočigled ostale braće i majke, odreže jezik onomu koji je u njihovo ime govorio, da mu se s glave oguli koža i odsijeku udovi.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (21, 7, 5, 'Osakativši ga posvema, zapovjedi da ga još živa primaknu vatri i prže na tavi. Dok se para s tave širila nadaleko, drugi se uzajamno poticali s majkom da junački umru.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (21, 7, 6, '\"Gospodin Bog gleda\", govorahu, \"i zaista će nam se smilovati, kao što Mojsije objavljuje pjesmom koja svečano svjedoči: \'I svojim ću se slugama smilovati.\'\"');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (21, 7, 7, 'Kad je prvi tako preminuo, dovedoše drugoga na mučenje. Pošto su mu s glave ogulili kožu s kosom, upitaše ga: \"Hoćeš li jesti svinjetine prije nego ti ud po ud izmučimo tijelo?\"');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (21, 7, 8, 'On odgovori jezikom svojih otaca: \"Neću!\" Zato su i njega podvrgli mučenju kao i prvog.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (21, 7, 9, 'Izdišući reče: \"Ti nam, zlikovče, oduzimaš sadašnji život, ali će nas Kralj svijeta, zato što umiremo za njegove zakone, uskrisiti na život vječni.\"');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (21, 7, 10, 'Poslije njega mučili su trećega. On spremno isplazi jezik kad su zatražili i hrabro pruži ruke.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (21, 7, 11, 'Junački reče: \"Od Neba sam primio ove udove, ali ih zbog njegovih zakona prezirem i nadam se da ću ih od njega natrag dobiti.\"');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (21, 7, 12, 'I sam kralj i njegova pratnja zadiviše se hrabrosti mladića koji je prezirao muke.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (21, 7, 13, 'Kad je taj preminuo, podvrgli su četvrtoga istim mukama.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (21, 7, 14, 'Prije nego što je izdahnuo, reče ovo: \"Blago onom koji umre od ruke ljudi, u čvrstoj nadi koju ima od Boga: da će ga Bog uskrisiti! A ti - za tebe nema uskrsnuća na život!\"');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (21, 7, 15, 'Zatim dovedoše petoga i stadoše ga mučiti.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (21, 7, 16, 'On upilji oči u kralja i reče: \"Iako si smrtan, imaš vlast nad ljudima i radiš što hoćeš. Ali ne misli da je Bog naš narod ostavio!');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (21, 7, 17, 'Samo čekaj, već ćeš vidjeti njegovu veliku moć: mučit će on tebe i tvoje sjeme!\"');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (21, 7, 18, 'Poslije toga doveli su šestoga, koji pred smrt reče: \"Ne zavaravaj se ludo; mi ovo trpimo zbog sebe jer smo sagriješili protiv svog Boga, i odatle nam sva ova strahota.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (21, 7, 19, 'Ali nemoj misliti da ćeš izbjeći kazni ti koji se drsko boriš protiv Boga.\"');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (21, 7, 20, 'Nadasve vrijedna udivljenja i dostojna svijetle uspomene bijaše majka, koja je u jednom jedinom danu gledala smrt svojih sedam sinova: veledušno je to podnijela zato što se ufala u Gospodina.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (21, 7, 21, 'Svakoga od njih poticala je jezikom otaca. Puna plemenitih osjećaja, ona je svoju ženstvenost oživljavala muškom hrabrošću.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (21, 7, 22, 'Govorila im je: \"Ne znam kako ste nastali u mojoj utrobi, jer nisam vam ja darovala ni duh ni život niti vam tkivo složila.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (21, 7, 23, 'Zato će vam Stvoritelj svijeta, koji je sazdao ljudski rod i koji svemu dade početak, milosrdno vratiti i duh i život, jer vi sad ne marite za se iz ljubavi prema njegovim zakonima.\"');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (21, 7, 24, 'Antioh pomisli da ga ona omalovažava; u njezinim je riječima nazrijevao porugu. Kako je najmlađi još živio, on ga poče ne samo riječima poticati nego mu se i zaklinjati i uvjeravati ga da će ga obogatiti i usrećiti, sprijateljit će se s njim i povjerit mu visoke službe ako se odrekne pradjedovskih predaja.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (21, 7, 25, 'Kako mladić za to nije ništa mario, kralj dozove majku i uze je nagovarati neka mladiću savjetuje da sebi spasi život.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (21, 7, 26, 'Poslije duga nagovaranja pristala je da savjetuje sina.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (21, 7, 27, 'Sagnula se k njemu pa je, zavaravajući okrutnog silnika, ovako progovorila jezikom svojih otaca: \"Sinko moj, smiluj se meni koja sam te devet mjeseci nosila u utrobi i dojila te tri godine, zatim te othranila i podigla do sadašnje dobi i odgojila.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (21, 7, 28, 'Molim te, dijete, pogledaj nebo i zemlju i sve što je na njima i znaj da je sve to Bog načinio ni od čega i da je tako nastao i ljudski rod.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (21, 7, 29, 'Ne boj se toga krvnika, nego budi dostojan svoje braće i prihvati smrt, da te s tvojom braćom u vrijeme milosti opet nađem!\"');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (21, 7, 30, 'Tek što je svoje dorekla, mladić reče: \"Što čekate? Ne pokoravam se kraljevoj zapovijedi, nego se pokoravam zapovijedi Zakona što ga našim ocima dade Mojsije.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (21, 7, 31, 'A ti, začetniče svake zloće protiv Hebreja, nipošto nećeš izbjeći ruci Božjoj.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (21, 7, 32, 'Mi trpimo zbog svojih grijeha.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (21, 7, 33, 'Pa ako se živi Gospodin na trenutak na nas i razgnjevio, da nas pokara i pouči, on će se opet i pomiriti sa svojim slugama.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (21, 7, 34, 'A ti, bezbožniče, od svih ljudi najpoganiji, ludo se ne uznosi i ne uljuljavaj se ispraznim nadama dižući ruku protiv sinova Neba,');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (21, 7, 35, 'jer još nisi izbjegao sudu Boga Svevladara, Svevida.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (21, 7, 36, 'Naša braća, pretrpjevši sada muku prolaznu za život neprolazni, pala su za Božji Savez, a ti ćeš već na sudu Božjemu primiti pravednu kaznu za svoju oholost.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (21, 7, 37, 'Ja sa svojom braćom za zakone otaca i tijelo i dušu rado predajem i molim Boga da se našem narodu naskoro smiluje, a tebe mukama i bičevima prinudi da priznaš da je on Bog jedini.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (21, 7, 38, 'Neka se napokon na meni i na mojoj braći zaustavi srdžba Boga Svevladara kojom se s pravom oborio na naš narod.\"');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (21, 7, 39, 'Sav izvan sebe, kralj se na ovoga razbjesnio još i više nego na druge: napose je gorko osjećao tu porugu.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (21, 7, 40, 'Tako je i ovaj preminuo a da se nije okaljao, pun pouzdanja u Gospodina.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (21, 7, 41, 'Posljednja je, poslije svojih sinova, umrla majka.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (21, 7, 42, 'Toliko, evo, o obrednim gozbama i prekomjernim progonstvima.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (21, 8, 1, 'Juda Makabej i njegovi ljudi stali su krišom obilaziti sela te sazivati svoje rođake i prikupljati one koji su ostali vjerni židovstvu. I tako se skupilo kojih šest tisuća ljudi.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (21, 8, 2, 'Molili su Gospodina da pogleda narod od svih potlačen, da se smiluje Hramu koji oskvrnuše bezbožni ljudi;');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (21, 8, 3, 'da se sažali na grad kojemu prijeti propast i opasnost da ga sravne sa zemljom; da usliši krv koja vapi k njemu;');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (21, 8, 4, 'da se spomene zločinačkog pokolja nejačadi; da osveti pogrde svoga Imena.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (21, 8, 5, 'Kad je Makabej stao na čelo svoje vojske, pogani mu nisu mogli odolijevati budući da se Gospodinov gnjev preokrenuo u milosrđe.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (21, 8, 6, 'Vršio je prepade na gradove i sela i spaljivao ih; zauzimao je pogodne položaje i neprijatelja često tjerao u bijeg.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (21, 8, 7, 'Takve je navale najradije vršio pod plaštem noći. Glas o njegovu junaštvu pronosio se na sve strane.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (21, 8, 8, 'Videći da taj čovjek u kratko vrijeme nezaustavno napreduje i sve više uspijeva, Filip zatraži pismeno od Ptolemeja, upravitelja Celesirije i Fenicije, da kraljevoj stvari pritekne u pomoć.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (21, 8, 9, 'Taj izabra Patroklova sina Nikanora, jednoga od svojih prvih prijatelja, i posla ga smjesta, na čelu od najmanje dvadeset tisuća ljudi skupljenih od različitih naroda, da istrijebi sav židovski narod. Pridružio mu je Gorgiju, vojskovođu od zanata, vješta bojnim poslovima.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (21, 8, 10, 'Nikanor je napose namjeravao da prodajom židovskih zarobljenika isplati kraljev danak od dvije tisuće talenata što ih dugovaše Rimljanima.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (21, 8, 11, 'Zato žurno pozva primorske gradove na prodaju židovskog roblja. Obeća ih devedeset za jedan talenat. Nije ni slutio kakva će ga kazna stići od ruke Svemogućega.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (21, 8, 12, 'Uto je Juda doznao za Nikanorov dolazak. Kad je svojim ljudima saopćio da se približava neprijateljska vojska,');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (21, 8, 13, 'pobjegoše kukavice i oni koji se nisu pouzdavali u Božju pravdu.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (21, 8, 14, 'Drugi pak prodaše sve što im je preostalo i zavapiše Gospodinu da ih izbavi od bezbožnoga Nikanora, koji ih je prodao još prije nego što je došlo do boja;');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (21, 8, 15, 'neka ih izbavi, ako i ne zbog njih samih, a ono zbog Saveza s njihovim ocima i zbog toga što se zovu njegovim svetim i veličanstvenim Imenom.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (21, 8, 16, 'Kad je, dakle, Makabej prikupio oko sebe šest tisuća ljudi, stao ih je hrabriti da se ne plaše neprijatelja niti boje mnoštva pogana koji ih nepravedno napadaju nego neka se junački bore.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (21, 8, 17, 'Neka imaju pred očima kako su oni zločinački osramotili Sveto mjesto i kako su zlostavljali i ruglu izvrgli Grad, a pradjedovske običaje uništili.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (21, 8, 18, '\"Oni se uzdaju\", dodao je, \"u oružje i smionost, a mi u Boga Svevladara koji jednim migom oka može oboriti naše napadače i sav svijet.\"');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (21, 8, 19, 'Nabrojio im je slučajeve u kojima se Bog udostojao zaštititi njihove pretke: onaj što se zbio pod Sanheribom kad je poginulo stotinu osamdeset i pet tisuća ljudi,');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (21, 8, 20, 'pa onaj u Babiloniji, u bici protiv Galaćana, gdje se borilo osam tisuća ljudi s pomoću četiri tisuće Makedonaca, i dok su Makedonci došli u škripac, onih samih osam tisuća, zahvaljujući pomoći s Neba, porazilo je stotinu i dvadeset tisuća neprijatelja i zadobilo velik plijen.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (21, 8, 21, 'Kad ih je tim riječima osokolio i pripremio da za svoje zakone i za domovinu i poginu, razdijelio je svoju vojsku na četiri odreda.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (21, 8, 22, 'Na čelo svakom odredu stavio je svoju braću: Šimuna, Josipa i Jonatana, i dao svakomu po tisuću i pet stotina ljudi.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (21, 8, 23, 'Osim toga, naredi Eleazaru da im pročita Svetu knjigu, a onda je, davši im bojni zov: \"S Božjom pomoću!\" stao na čelo prvog odreda i napao Nikanora.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (21, 8, 24, 'Budući da im je Svemogući u boju bio suborac, pobili su preko devet tisuća neprijatelja, izranili i osakatili veći dio Nikanorove vojske i nagnali sve u bijeg.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (21, 8, 25, 'Zaplijenili su i novac onih koji su ih došli kupovati. Pošto su ih podugo tjerali, vratiše se natrag jer nisu imali vremena.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (21, 8, 26, 'Bilo je, naime, uoči subote, pa ih nisu dalje gonili.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (21, 8, 27, 'Pokupiše još neprijateljsko oružje i poskidaše plijen, a onda svetkovahu subotu, obilno hvaleći i slaveći Gospodina koji ih je tog dana izbavio i opet im počeo iskazivati svoju milost.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (21, 8, 28, 'Poslije subote podijelili su dio plijena žrtvama progonstva, pa udovicama i siročadi, a ono što je preostalo podijelili su među sobom i među svojom djecom.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (21, 8, 29, 'Završivši taj posao, okupiše se na zajedničku molitvu i zavapiše milosrdnom Gospodinu da se posve izmiri sa svojim slugama.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (21, 8, 30, 'U kreševu s Timotejevim i Bakidovim vojnicima pobili su ih dvadeset tisuća i osvojili vrlo visoke tvrđave. Velik plijen razdijelili su na dva jednaka dijela - jedan za sebe, drugi za žrtve progonstva, siročad i udovice - a ne zaboraviše ni staraca.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (21, 8, 31, 'Zatim su brižno pokupili neprijateljsko oružje i pohranili ga na prikladnim mjestima. Što je od plijena preostalo, odnijeli su u Jeruzalem.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (21, 8, 32, 'Ubili su vođu Timotejevih četa, čovjeka bezbožna, koji je Židovima nanio mnogo zala.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (21, 8, 33, 'Dok su u domovini slavili pobjedu, spališe one koji su zapalili Sveta vrata, zajedno s Kalistenom, koji bijaše utekao u neku kućicu. Tako je za svoje svetogrđe primio zasluženu plaću.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (21, 8, 34, 'A onaj trostruki zlikovac Nikanor, koji je doveo tri tisuće trgovaca da kupuju Židove,');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (21, 8, 35, 'bio je Božjom pomoću ponižen od onih koje je najviše podcjenjivao: morao je skinuti svoju časničku odoru te je tako, po osamljenim putovima, poput odbjegla roba, stigao u Antiohiju - sretno umaknuvši, dok mu je sva vojska bila poražena.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (21, 8, 36, 'I on, koji je cijenom jeruzalemskih zarobljenika obećao platiti danak Rimljanima, sad je morao razglasiti da Židovi imaju Borca koji se za njih bori i da su Židovi upravo zato neranjivi što slijede zakone koje im je On postavio.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (21, 9, 1, 'U isto se vrijeme Antioh sramotno vraćao iz perzijskih krajeva.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (21, 9, 2, 'Bio je provalio u grad Perzepolis i pokušao opljačkati hram i zaposjesti grad. Ali se pučanstvo podiglo i pograbilo oružje, tako da se Antioh, jer su ga stanovnici te zemlje natjerali u bijeg, morao sramotno povlačiti.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (21, 9, 3, 'Kad je došao do Ekbatane, saznao je što se dogodilo s Nikanorom i s Timotejevima.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (21, 9, 4, 'Sav izvan sebe od jarosti, smišljao je kako da se i za uvredu onih koji su ga natjerali u bijeg iskali na Židovima. Zato je upravljaču kola zapovjedio da njegova bojna kola tjera bez prestanka, sve dok ne stignu. Ali se već nad njim nadvila kazna s Neba, jer je ovako oholo govorio: \"Načinit ću od Jeruzalema, kad onamo dođem, židovsko groblje.\"');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (21, 9, 5, 'Ali Svevid, Gospodin Bog Izraelov, udari ga neizlječivom i nevidljivom bolešću. Čim je izgovorio onu riječ, spopade ga u crijevima nesnosna bol i strašne muke u utrobi.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (21, 9, 6, 'Tako je bilo baš i pravo, jer on je utrobama drugih zadao mnoge i nečuvene muke.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (21, 9, 7, 'On se ipak svoga divljaštva nije okanio, nego nadut od oholosti i rigajući plamen gnjeva na Židove, zapovjedi da se ubrza vožnja. Tada ispade iz kola u trku, koja su odštropotala dalje, a on u nesretnu padu poiščaši sve udove na tijelu.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (21, 9, 8, 'On, koji je u svome nadljudskom razmetanju mislio da je kadar zapovijedati morskim valovima, on koji je umišljao da može mjeriti gorske vrhove, sad se našao zgruhan na tlu, odakle su ga zatim digli na nosila. Tako se svima očitovala na njemu Božja sila,');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (21, 9, 9, 'jer su crvi povrvjeli iz bezbožnikova tijela i sa živog mu tijela, u ljutim bolima, otpadalo meso te je smrad te gnjileži izazivao gađenje u svoj vojsci.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (21, 9, 10, 'Malo prije mišljaše da dohvaća nebeske zvijezde, a sada ga više nitko, zbog nepodnošljiva smrada, nije mogao pratiti.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (21, 9, 11, 'Istom sada, sav skršen bolima, poče popuštati u svojoj velikoj oholosti i pod Božjim bičem stao je dolaziti k pameti, jer su mu se od časa do časa povećavale boli.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (21, 9, 12, 'Kad više ni sam nije mogao podnositi vlastitog smrada, priznade: \"Pravo je pokoravati se Bogu i neka se smrtnik s Bogom ne izjednačuje!\"');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (21, 9, 13, 'Ali taj se zločinac molio Gospodaru u koga više nije bilo smilovanja.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (21, 9, 14, 'Obećavao je da će Sveti grad, kamo se žurio da ga sravni sa zemljom i pretvori u groblje, proglasiti slobodnim;');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (21, 9, 15, 'da će s Atenjanima izjednačiti sve Židove, koje inače nije smatrao dostojnima ni ukopa, nego vrijednima da se s njihovom djecom bace za hranu pticama grabilicama i divljim zvijerima;');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (21, 9, 16, 'da će najljepšim darovima ukrasiti sveti Hram, koji je prije oplijenio, i da će mu mnogostruko vratiti sve sveto posuđe, a troškove žrtvovanja podmirivati od svojih dohodaka;');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (21, 9, 17, 'i napokon da će i sam postati Židov i da će krstariti cijelim svijetom i naviještati Božju svemoć.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (21, 9, 18, 'Ali kako mu boli nisu ništa popuštale, jer se na nj oborio pravedan sud Božji, u beznadnu stanju napisao je Židovima ovo pismo u kojem moli oproštenje. Ono glasi ovako:');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (21, 9, 19, '\"Odličnim građanima Židovima kralj i upravitelj Antioh šalje pozdrav želeći im zdravlje i dobru sreću!');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (21, 9, 20, 'Ako ste dobro vi i vaša djeca, ako vam poslovi idu od ruke, pun nade u Nebo');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (21, 9, 21, 'rado se spominjem vašeg štovanja i vaše blagonaklonosti prema meni. Na povratku iz perzijskih krajeva, pošto sam zapao u nepodnošljivu bolest, smatram potrebnim da se pobrinem za opće dobro.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (21, 9, 22, 'Ne očajavam zbog svog stanja nego se čvrsto nadam da ću se iz bolesti izvući.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (21, 9, 23, 'Ipak, i moj je otac, kad je s vojskom polazio u gornje krajeve, odredio sebi nasljednika,');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (21, 9, 24, 'da se, bude li neočekivanih događaja ili nepovoljnih glasova, državljani ne uzbunjuju, znajući kome je on prepustio upravu poslovima.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (21, 9, 25, 'Osim toga, znam kako obližnji vladaoci i susjedi našeg kraljevstva vrebaju priliku i čekaju da se što dogodi. Zato sam za kralja odredio svoga sina Antioha, koga sam već više puta, polazeći u gornje krajeve, mnogima od vas povjerio i preporučio. I njemu sam, uostalom, napisao priloženo pismo.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (21, 9, 26, 'Zato vas molim i zaklinjem da se sjetite dobročinstava koje sam vam svima pojedinačno učinio te da svoju dosadašnju blagonaklonost prema meni sačuvate i prema mome sinu.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (21, 9, 27, 'Zaista sam uvjeren da će on savjesno slijediti moje nakane i blago i čovjekoljubivo postupati s vama.\"');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (21, 9, 28, 'Tako je taj ubojica i hulitelj, poslije najužasnijih muka, kakve je znao zadavati drugima, najjadnije, u tuđoj zemlji, u pustim planinama završio život.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (21, 9, 29, 'Njegovo je tijelo uzeo sa sobom Filip, njegov prijatelj od djetinjstva, koji se u strahu od njegova sina Antioha uputio u Egipat Ptolemeju Filometoru.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (21, 10, 1, 'Dotle je Makabej sa svojim drugovima, pod vodstvom Gospodinovim, opet zauzeo Hram i Grad.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (21, 10, 2, 'Srušili su žrtvenike što su ih po trgu sagradili tuđinci i uništili su posvećene gajeve.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (21, 10, 3, 'Potom su očistili Hram i podigli drugi žrtvenik; onda su iskresali vatru iz kamena i tom vatrom, nakon prijekida od dvije godine, prinijeli žrtvu; ujedno su obnovili prinos kada, zapalili svjetiljke i izložili prinesene hljebove.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (21, 10, 4, 'Kad su sve to izvršili, pali su ničice i stali moliti Gospodina da više nikada ne dopusti da padnu u takve nevolje, nego, ako kad i sagriješe, neka ih primjerno kazni, ali neka ih ne predaje bogohulnim i divljim narodima.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (21, 10, 5, 'Čišćenje Hrama palo je upravo na isti dan i mjesec u koji su ga pogani i oskvrnuli, na dvadeset i peti dan Kisleva.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (21, 10, 6, 'Svetkovali su to razdragano osam dana, onako kao i Blagdan sjenica, sjećajući se kako su nedavno, na Blagdan sjenica, boravili u planinama i spiljama kao divlje zvijeri.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (21, 10, 7, 'Zato su, noseći bršljanom ovite štapove, zelene grančice i palme, zahvaljivali hvalospjevima Onomu koji je sretno proveo očišćenje svoga Svetog mjesta.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (21, 10, 8, 'Ujedno su javno zaključili i izglasali da sav židovski narod treba da te dane svake godine slavi.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (21, 10, 9, 'Takve su, dakle, bile prilike u vrijeme smrti Antioha, nazvanog Epifana.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (21, 10, 10, 'A sad ćemo izvijestiti o događajima s Antiohom Eupatorom, sinom onoga bezbožnika, sažimajući ukratko ratne nevolje.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (21, 10, 11, 'Kad je taj preuzeo kraljevstvo, postavio je na čelo državnih poslova nekog Liziju, glavnog upravitelja Celesirije i Fenicije.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (21, 10, 12, 'Ptolemej, nazvan Makron, prvi je sa Židovima postupao pravedno, pa je zbog nepravde koja im je bila nanesena nastojao njima upravljati miroljubivo.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (21, 10, 13, 'Zato su ga neki prijatelji optužili Eupatoru, pa je svakom prilikom slušao kako ga nazivaju izdajicom zato što je ostavio Cipar koji mu je povjerio Filometor i što je prešao Antiohu Epifanu. Pa kad više časne vlasti nije mogao časno izvršavati, otrovom je sebi oduzeo život.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (21, 10, 14, 'Kad je potom Gorgija postao upraviteljem tih predjela, skupljao je najamničku vojsku i svakom se prilikom zaraćivao sa Židovima.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (21, 10, 15, 'U isto su vrijeme Idumejci, gospodari tvrđava na dobrim položajima, dodijavali Židovima te su, prihvaćajući izbjeglice iz Jeruzalema, nastojali održati ratno stanje.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (21, 10, 16, 'Makabej i njegovi drugovi, pošto su se okupili na molitvu i Boga molili da im bude saveznik, krenuše protiv tih idumejskih tvrđava.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (21, 10, 17, 'Udarivši snažno, osvojiše te položaje i suzbiše sve one koji su se borili na bedemima. Pobili su sve na koje su naišli, tako da ih je palo ne manje od dvadeset tisuća.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (21, 10, 18, 'Kako je najmanje devet tisuća ljudi pobjeglo u dvije dobro utvrđene kule, a sa sobom su imali sve što je potrebno da se izdrži opsada,');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (21, 10, 19, 'Makabej ostavi Šimuna i Josipa sa Zakejem i njegovima, njih dovoljan broj za opsadu, a sam ode u druga mjesta, gdje je bila veća potreba.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (21, 10, 20, 'Ali Šimunove ljude, pohlepne za novcem, potkupiše neki što su se onamo sklonili, tako te oni, primivši sedamdeset tisuća drahma, pustiše neke da uteknu.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (21, 10, 21, 'Kad su Makabeju javili što se dogodilo, on skupi narodne vođe i optuži krivce da su za novce prodali svoju braću jer su pustili da pobjegnu neprijatelji.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (21, 10, 22, 'Zato ih je dao pogubiti kao izdajice, a onda odmah zauze obje kule.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (21, 10, 23, 'Sretan u oružju, pobi u obadvije tvrđave preko dvadeset tisuća ljudi.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (21, 10, 24, 'Timotej, koga su Židovi prije porazili, skupi mnogo stranih četa, sabra znatan broj azijskih konjanika i krenu na Judeju misleći da će je oružjem osvojiti.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (21, 10, 25, 'Kad se približavao, Makabej i njegovi ljudi stadoše zazivati Boga, posuvši glave prahom i pripasavši oko bokova kostrijet.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (21, 10, 26, 'Padnuvši ničice na podnožju žrtvenika, molili su Boga da im bude milostiv: da bude neprijatelj njihovih neprijatelja, protivnik njihovih protivnika, kako to objašnjava Zakon.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (21, 10, 27, 'Kad su završili molitvu, pograbiše oružje, prilično se odmaknuše od grada i zaustaviše pred neprijateljem.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (21, 10, 28, 'Upravo u cik zore pograbiše se. Jednima je zalog uspjeha i pobjede, osim hrabrosti, bilo uzdanje u Gospodina, a drugi su vodstvo boja stavili samo u junaštvo.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (21, 10, 29, 'Kad se razmahalo kreševo, protivnicima se ukaza s neba pet krasnih ljudi na konjima sa zlatnim uzdama; oni stadoše na čelo Židovima.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (21, 10, 30, 'U isto vrijeme uzeše Makabeja među se da ga štite svojim oružjem i čuvaju neranjena, dok su na protivnike bacali strelice i munje, tako da su ih zabliještili i smeli te se oni raspršiše u najvećem neredu.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (21, 10, 31, 'Bi tada pobijeno dvadeset tisuća i pet stotina pješaka i šest stotina konjanika.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (21, 10, 32, 'Timotej pobježe u vrlo utvrđeno mjesto zvano Gezer, kojim je upravljao Hereja.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (21, 10, 33, 'Makabej i njegovi srčano su ga opsjedali četiri dana.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (21, 10, 34, 'Uzdajući se u čvrstoću mjesta, oni koji bijahu ondje užasno su psovali i sipali bestidnosti.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (21, 10, 35, 'Kad je peti dan počelo svitati, dvadeset mladića iz Makabejeve vojske, poneseno gnjevom zbog onih psovki, jurnu na zid muški hrabro i u divljem žaru pobi svakoga na koga naiđe.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (21, 10, 36, 'Jednako su na opsjednute navalili i drugi s protivne strane. Zažegli su kule i, raspirivši lomače, žive sažgali one bogohulnike. Drugi razbiše vrata, pustiše unutra ostalu vojsku i zaposjedoše grad.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (21, 10, 37, 'Timoteja, koji se sakrio u neku nakapnicu, zaklaše zajedno s njegovim bratom Herejom i Apolofanom.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (21, 10, 38, 'Pošto obaviše posao, počeše himnama i zahvalnicama slaviti Gospodina koji je Izraelu iskazao veliku dobrotu i dao mu pobjedu.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (21, 11, 1, 'Malo zatim kraljev skrbnik i rođak Lizija, koji je bio na čelu državnih poslova, vrlo teško podnoseći posljednje događaje,');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (21, 11, 2, 'skupi kojih osamdeset tisuća pješaka i svekoliko svoje konjaništvo te krenu na Židove, u nakani da Grad učini grčkim naseljem');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (21, 11, 3, 'i da Hram, poput svetišta poganskih naroda, podloži porezu i svake godine prodaje svećeničku čast.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (21, 11, 4, 'Nije nimalo mislio na Božju moć: zanijelo ga mnoštvo njegovih pješaka i tisuće konjanika te osamdeset njegovih slonova.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (21, 11, 5, 'Upade u Judeju i približi se Betsuru, utvrđenu mjestu, udaljenu kojih pet stadija od Jeruzalema, te ga ljuto pritisnu.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (21, 11, 6, 'Kad Makabej i njegovi doznaše da Lizija opsjeda tvrđave, počeše plakati i liti suze, moleći Gospodina da Izraelu pošalje dobroga anđela da ga spasi.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (21, 11, 7, 'Nato Makabej prvi pograbi oružje i potače druge da se zajedno s njim izlože pogibli i pomognu svojoj braći. Puni žara, srnuše zajedno.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (21, 11, 8, 'Dok su se još nalazili blizu Jeruzalema, ukaza im se na čelu konjanik u bijelim haljinama koji je vitlao zlatnim oružjem.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (21, 11, 9, 'Tada se svi zajedno zahvališe milosrdnom Bogu i toliko se ohrabriše da su bili spremni probosti ne samo ljude nego i najdivljije zvijeri i probiti željezne zidove.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (21, 11, 10, 'Kretali su naprijed u bojnom redu sa suborcem koji im je milošću Gospodnjom stigao s neba.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (21, 11, 11, 'Zagnaše se na neprijatelje kao lavovi, oboriše jedanaest tisuća pješaka i tisuću i šest stotina konjanika, a ostale natjeraše u bijeg.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (21, 11, 12, 'Većina se spasila, ali ranjeni i razoružani. Sam se Lizija spasio sramotnim bijegom.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (21, 11, 13, 'Lizija nije bio nerazuman; razmišljao je o porazu koji je pretrpio i uvidio je da su Hebreji nepobjedivi jer im je suborac svesilni Bog.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (21, 11, 14, 'Zato im poruči da pod svim pravednim uvjetima pristanu na mir, a on će kralja sklonuti da im postane prijatelj.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (21, 11, 15, 'Makabej pristade na sve što je Lizija predlagao, jer mu bijaše stalo do općeg dobra. A sam kralj odobri sve što je Makabej preko Lizije za Židove pismeno zatražio.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (21, 11, 16, 'Pismo što ga je Lizija pisao Židovima glasilo je ovako: \"Lizija pozdravlja židovski narod!');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (21, 11, 17, 'Vaši poslanici Ivan i Apsalom predali su mi niže prepisanu ispravu, preporučujući njezin sadržaj.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (21, 11, 18, 'Ja sam nato izvijestio kralja o onom s čime ga je trebalo upoznati, i on je odobrio sve što je bilo prihvatljivo.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (21, 11, 19, 'Ako se, dakle, budete i dalje blagonaklono odnosili prema državnim probicima, ja ću ubuduće nastojati da poradim za vaše dobro.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (21, 11, 20, 'Ujedno sam vašim i svojim izaslanicima naložio da s vama rasprave o pojedinostima.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (21, 11, 21, 'Da ste zdravo! Godine sto četrdeset i osme, dvadeset i četvrtoga Dioskora.\"');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (21, 11, 22, 'Kraljevo je pismo glasilo ovako: \"Kralj Antioh pozdravlja brata Liziju.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (21, 11, 23, 'Naš se otac preselio k bogovima, a mi želimo da nam se u kraljevstvu svatko nesmetano bavi svojim poslovima.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (21, 11, 24, 'Čuli smo da Židovi ne prihvaćaju helenskih običaja moga oca, nego vole svoj poseban način života i traže da im se dopusti da se ravnaju po posebnim zakonima.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (21, 11, 25, 'Želeći, dakle, da i taj narod bude nesmetan, odlučujemo da im se vrati Hram, tako da mogu slobodno živjeti po običajima svojih predaka.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (21, 11, 26, 'Zato će biti dobro da im pošalješ poslanike koji će s njima sklopiti ugovor, pa da se, znajući za našu odluku, raspoloženi i radosni late svojih poslova.\"');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (21, 11, 27, 'Kraljevo pismo židovskom narodu glasilo je ovako: \"Kralj Antioh pozdravlja židovsko starješinstvo i ostale Židove.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (21, 11, 28, 'Nadamo se da ste dobro, kako vam i želimo. I mi smo zdravi.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (21, 11, 29, 'Menelaj nam je saopćio da se želite vratiti svojim domovima.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (21, 11, 30, 'Svima onima koji se kućama vrate do tridesetog Ksantika bit će zajamčena nekažnjivost.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (21, 11, 31, 'Židovi će se služiti svojom posebnom hranom i zakonima kao i prije. Neka se nikome od njih više nikako ne dosađuje zbog pogrešaka učinjenih iz neznanja.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (21, 11, 32, 'Ujedno vam šaljem Menelaja da vas umiri.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (21, 11, 33, 'Da ste zdravo! Godine sto četrdeset i osme, petnaestog Ksantika.\"');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (21, 11, 34, 'A i Rimljani su Židovima poslali pismo, koje glasi ovako: \"Kvint Memije, Tit Manilije i Manije Sergije, rimski poslanici, pozdravljaju židovski narod.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (21, 11, 35, 'Mi pristajemo na ono što vam je dopustio kraljev rođak Lizija.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (21, 11, 36, 'O onome pak što je on smatrao da treba predložiti kralju na potvrdu - odmah dobro razmislite i pošaljite nam smjesta nekoga da bismo to mogli izložiti onako kako odgovara, jer putujemo u Antiohiju.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (21, 11, 37, 'Zato se požurite i pošaljite ljude da i mi doznamo vaše mišljenje.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (21, 11, 38, 'Da ste zdravo! Godine sto četrdeset i osme, petnaestog dana mjeseca Dioskora.\"');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (21, 12, 1, 'Kad su sklopili ugovore, Lizija se vrati kralju, a Židovi se latiše poljskih radova.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (21, 12, 2, 'Ali mjesni upravitelj Timotej i Genejev sin Apolonije, pa i Jeronim i Demofon, kojima se pridružio i Cipranin Nikanor, nisu Židovima dali ni mira ni pokoja.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (21, 12, 3, 'Uto su Jopljani izvršili veliko nedjelo. Pozvali su svoje sugrađane Židove sa ženama i djecom na pripremljene lađe kao da im ništa zlo ne spremaju.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (21, 12, 4, 'Na temelju javnoga gradskog zaključka, Židovi se odazvaše, jer im bijaše stalo do mira, a nisu ni naslućivali ikakvo zlo. Izvedoše ih na morsku pučinu i potopiše najmanje dvije stotine.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (21, 12, 5, 'Čim je Juda doznao za okrutnost izvršenu nad njegovim sunarodnjacima, obavijesti o tome svoje ljude;');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (21, 12, 6, 'zazvavši Boga, pravednog suca, navali na ubojice svoje braće. Noću zapali pristanište i spali lađe te pobi one koji su se onamo sklonili.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (21, 12, 7, 'Budući da je mjesto bilo zatvoreno, otišao je s namjerom da se vrati i istrijebi sve Jopljane.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (21, 12, 8, 'Kad je doznao da i Jamnijci namjeravaju jednako postupiti sa svojim sugrađanima Židovima,');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (21, 12, 9, 'navali noću na njih i zapali im pristanište s lađama, tako da se blijesak vatre vidio sve do Jeruzalema, udaljena dvije stotine i četrdeset stadija.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (21, 12, 10, 'Kad su odande odmakli devet stadija, na pohodu protiv Timoteja, navališe na njih Arapi, njih najmanje pet tisuća pješaka i pet stotina konjanika.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (21, 12, 11, 'Zametnu se žestoka bitka, u kojoj su Judini vojnici s pomoću Božjom pobijedili. Pobijeđeni nomadi zamoliše Judu za mir. Obećali su da će mu dati stoku i u drugome mu biti na korist.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (21, 12, 12, 'Juda, držeći da će mu zaista moći u mnogome biti od pomoći, pristade na mir s njima; dadoše si desnice pa se povukoše pod šatore.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (21, 12, 13, 'Potom navali na grad Kaspin, utvrđen nasipima i okružen bedemima, a naseljen pučanstvom najrazličitijih narodnosti.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (21, 12, 14, 'Njegovi su se građani pouzdavali u čvrste zidove i zalihu hrane, pa su se drsko vladali prema Judinim ljudima, rugali im se, psovali, svašta nepristojno govorili.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (21, 12, 15, 'Judini ljudi zazvaše velikog Gospodara svijeta, koji je bez zidodera i naprava u Jošuino vrijeme oborio Jerihon, i divlje nasrnuše na zid.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (21, 12, 16, 'Zauzevši s Božjom voljom grad, izvršiše neopisiv pokolj, tako da se obližnje jezero, dva stadija široko, činilo kao da je puno krvi koja je u nj tekla.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (21, 12, 17, 'Odmakavši odande sedam stotina i pedeset stadija, dođoše u Harak, k Židovima zvanim Tubijanci.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (21, 12, 18, 'U tim krajevima nisu, doduše, zatekli Timoteja, jer je odande otišao neobavljena posla, ali je na jednom mjestu ostavio snažnu posadu.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (21, 12, 19, 'Tada Makabejevi zapovjednici Dositej i Sosipater krenuše onamo i pobiše ljude koje je Timotej ostavio u tvrđavi, njih više od deset tisuća.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (21, 12, 20, 'Nato je Makabej svoju vojsku rasporedio na kohorte i odredio im zapovjednike, pa navali na Timoteja, koji je oko sebe imao stotinu i dvadeset tisuća pješaka i dvije tisuće pet stotina konjanika.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (21, 12, 21, 'Kad je Timotej doznao da dolazi Juda, najprije otposla ženu, djecu i opremu u mjesto zvano Karnion. To je mjesto bilo neosvojivo i teško pristupačno, jer su onamo vodili sami tijesni klanci.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (21, 12, 22, 'Čim se pojavila prva Judina kohorta, neprijatelja spopade strava. Ulijevala im je strah pojava Onoga koji sve vidi. Udariše u bijeg na sve strane, tako da su se često međusobno ranjavali, probadali se vlastitim mačevima.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (21, 12, 23, 'Juda ih je žestoko gonio i probadao te zlikovce: pobi ih do trideset tisuća.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (21, 12, 24, 'Sam pak Timotej dopade u šake Dositejevim i Sosipatrovim ljudima. Tada ih uze vrlo prepredeno moliti da ga otpuste živa, jer da kod njega ima mnogo njihovih roditelja i braće te bi ih moglo zadesiti kakvo zlo.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (21, 12, 25, 'Kad ih je napokon uvjerio svečanim obavezama da će te ljude vratiti žive i zdrave, pustiše ga - da spase svoju braću.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (21, 12, 26, 'Juda krenu na Karnion i Atargatis i pobi dvadeset i pet tisuća ljudi.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (21, 12, 27, 'Pošto je ove pobijedio i uništio, pošao je s vojskom i na utvrđeni grad Efron, u kojem bijaše Lizanija s četama najrazličitijih narodnosti. Kršni mladići poredani pred zidovima borili se snažno, a unutra bilo je mnogo bojnih naprava i zaliha bacača.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (21, 12, 28, 'Ali zazvavši u pomoć Svemogućega koji svojom moći lomi neprijateljske snage, Židovi osvojiše grad i pobiše u njemu oko dvadeset i pet tisuća stanovnika.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (21, 12, 29, 'Podigavši se odande, uputiše se protiv Scitopolisa, koji je od Jeruzalema udaljen šest stotina stadija.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (21, 12, 30, 'Ali su ondje naseljeni Židovi posvjedočili da su stanovnici Scitopolisa s njima vrlo prijazni te su ih u teškim vremenima susretljivo primali.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (21, 12, 31, 'Juda i njegovi zahvališe im, potičući ih da se i ubuduće pokažu blagonakloni prema njihovu narodu. Stigoše u Jeruzalem nešto prije Blagdana sedmica.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (21, 12, 32, 'Poslije blagdana Pedesetnice udariše na idumejskog vojskovođu Gorgiju.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (21, 12, 33, 'Taj je izišao sa tri tisuće pješaka i četiri stotine konjanika.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (21, 12, 34, 'U boju pade izvjestan broj Židova.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (21, 12, 35, 'Neki Dositej, konjanik iz redova Tubijanaca, čovjek hrabar, uhvati Gorgiju. Držeći ga za plašt, silom ga je vukao da prokletnika zarobi živa; ali na nj naletje neki trački konjanik i odsiječe mu ruku u ramenu. Gorgija pobježe u Marisu.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (21, 12, 36, 'Kako su se Ezdrinovi ljudi od dugog vojevanja izmorili, Juda zamoli Gospodina da im u boju bude pomoćnik i vođa.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (21, 12, 37, 'Potom jezikom otaca zaklikta što mu grlo dade i zapjeva hvalospjeve te nenadano napade Gorgijine ljude i natjera ih u bijeg.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (21, 12, 38, 'Sabravši vojsku, Juda se uputi u grad Odolam. Kako je upravo osvanuo sedmi dan, ondje se prema običaju očistiše i proslaviše subotu.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (21, 12, 39, 'Sutradan su došli Judini ljudi - jer je već bio posljednji čas - da pokupe tjelesa onih što su pali i da ih pokopaju uz njihove rođake u grobovima otaca.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (21, 12, 40, 'Tu su pod odjećom svakoga mrtvaca našli predmete posvećene jamnijskim idolima, što Zakon Židovima zabranjuje. Tako je svima postalo jasno da je to uzrok njihove smrti.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (21, 12, 41, 'Zato su svi stali blagoslivljati Gospodina, pravednog suca koji otkriva ono što je sakriveno.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (21, 12, 42, 'Zatim se pomoliše da bi se počinjeni grijeh sasvim oprostio. Plemeniti Juda opomenu vojnike da se čuvaju čisti od grijeha, jer sad vide što je zbog grijeha zadesilo one koji su pali.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (21, 12, 43, 'Nato je sabrao oko dvije tisuće srebrnih drahmi i poslao u Jeruzalem da se prinese žrtva okajnica za grijeh. Učinio je to vrlo lijepo i plemenito djelo jer je mislio na uskrsnuće.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (21, 12, 44, 'Jer da nije vjerovao da će pali vojnici uskrsnuti, bilo bi suvišno i ludo moliti za mrtve.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (21, 12, 45, 'K tome je imao pred ovima najljepšu nagradu koja čeka one koji usnu pobožno. Svakako, sveta i pobožna misao. Zato je za pokojne prinio žrtvu naknadnicu da im se oproste grijesi.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (21, 12, 46, '');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (21, 13, 1, 'Godine sto četrdeset i devete dočuli su Judini ljudi da Antioh Eupator dolazi s mnoštvom vojske na Judeju');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (21, 13, 2, 'i da je s njime njegov skrbnik Lizija, upravitelj državnih poslova; i da svaki ima grčku vojsku od stotinu i deset tisuća pješaka, pet tisuća i tri stotine konjanika, dvadeset i dva slona i tri stotine bojnih kola, opremljenih srpovima.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (21, 13, 3, 'Njima se pridružio i Menelaj, vrlo prepredeno potičući Antioha, ne zato što bi svojoj domovini želio sreću, nego u nadi da će se održati na vlasti.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (21, 13, 4, 'Ali Kralj kraljeva raspiri Antiohov gnjev na zlikovca, jer je Lizija kralju obrazložio da je Menelaj krivac svemu zlu. Zato Antioh zapovjedi da ga odvedu u Bereju i ondje pogube prema mjesnom običaju.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (21, 13, 5, 'U tom se mjestu nalazi kula visoka pedeset lakata, puna pepela, a na njoj je naprava koja se okreće naokolo i odasvud sunovraćuje u pepeo.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (21, 13, 6, 'Tu se mora popeti krivac svetogrdne pljačke ili kakvih drugih velikih zločina da ga odande strmoglave u smrt.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (21, 13, 7, 'Takva je smrtna kazna zadesila tog nevjernika Menelaja a da ga nisu ni pokopali.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (21, 13, 8, 'I to s pravom; sagriješio je mnogo protiv žrtvenika, kojega je i oganj i pepeo svet, i zato ga je stigla smrt u pepelu.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (21, 13, 9, 'U to se primicao kralj, premećući u glavi najokrutnije nakane kako bi Židovima napakostio još gore nego njegov otac.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (21, 13, 10, 'Kad je Juda za to saznao, odredio je da narod danju i noću zazivlje Gospodina, da i sad kao nekoć pritekne u pomoć onima kojima prijeti pogibao da ih liše Zakona, domovine i svetog Hrama');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (21, 13, 11, 'te da ne dopusti da puk koji je malo odahnuo opet padne pod vlast bogohulnih naroda.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (21, 13, 12, 'Kad su svi zajedno izvršili taj nalog, zaklinjući milosrdnog Gospodina suzama i postovima, prostrti ničice tri dana zaredom, Juda ih ohrabri i pozva da se spreme.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (21, 13, 13, 'Potom je sa starješinama odlučio da ne čekaju, nego da iziđu i s Božjom pomoći riješe stvar prije nego kraljeva vojska upadne u Judeju i zauzme grad.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (21, 13, 14, 'Prepustivši, dakle, pothvat Stvoritelju svijeta, potaknu svoje drugove da se za zakone, Hram, Grad, domovinu i ustanove junački bore na život i smrt, pa se utabori kod Modina.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (21, 13, 15, 'Davši tada svojima bojni zov: \"Božja je pobjeda!\", noću s najboljim poizbor momcima napade kraljev šator; pobi u taboru oko dvije tisuće ljudi, a njegovi ljudi probodoše najvećega slona i njegova upravljača u kućici.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (21, 13, 16, 'Ispuniše sav tabor stravom i metežom pa se pobjedonosno povukoše.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (21, 13, 17, 'Kad je počela svitati zora, sve je bilo gotovo, jer je Gospod pomogao i štitio Judu.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (21, 13, 18, 'Kad je kralj iskusio židovsku hrabrost, pokuša varkama napadati njihove položaje.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (21, 13, 19, 'Približi se snažnoj židovskoj tvrđavi Betsur, ali je bio odbijen, svladan, pobijeđen.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (21, 13, 20, 'Juda je opsjednutima slao što im je bilo potrebno.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (21, 13, 21, 'Ali je neki Rodok iz židovske vojske neprijateljima odao tajne. Pronašli su ga, uhvatili i smaknuli.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (21, 13, 22, 'Kralj je i drugi put poveo pregovore s onima u Betsuru, ponudio im mir, prihvatio uvjete pa se povukao; a zatim napade Judu i njegove ljude, ali bi poražen.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (21, 13, 23, 'Kad je doznao da je Filip, koga je postavio za državnog upravitelja u Antiohiji, podigao bunu, usplahirio se pa stade opet pregovarati sa Židovima; prihvati njihove uvjete i zakletvom se na njih obveza. Poslije izmirenja prinese žrtvu, počasti Hram i nadari Sveto mjesto.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (21, 13, 24, 'Dobro je primio Makabeja i postavio ga za namjesnika od Ptolemaide do zemlje Gerenijaca.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (21, 13, 25, 'Ode u Ptolemaidu, ali se njezini građani nisu slagali s ugovorom; negodovali su zbog nekih stavaka i tražili da se ponište.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (21, 13, 26, 'Tada se na besjedište pope Lizija. Branio je nagodbu kako je najbolje znao; uvjeri stanovnike, umiri ih i pridobi, a onda se vrati u Antiohiju. Tako se završio kraljev vojni pohod i uzmak.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (21, 14, 1, 'Poslije tri godine saznali su Juda i njegovi ljudi da je Seleukov sin Demetrije s jakom vojskom i brodovljem doplovio u luku Tripolis,');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (21, 14, 2, 'zavladao zemljom i pogubio Antioha i njegova skrbnika Liziju.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (21, 14, 3, 'Neki Alkim, koji je prije bio veliki svećenik a poslije se u vrijeme pobune svojevoljno okaljao, videći da se nikako ne može održati i da mu je posve onemogućen pristup k svetom žrtveniku,');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (21, 14, 4, 'pođe godine sto pedeset i prve kralju Demetriju i donese mu zlatnu krunu i palmu, i k tome maslinove grančice koje se običavaju prikazivati u Hramu. Inače tog dana nije učinio ništa više.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (21, 14, 5, 'Ali kad ga je potom Demetrije pozvao u vijeće i upitao kakvo je raspoloženje i koje su nakane Židova, on iskoristi tu priliku za svoje lude namjere i odgovori:');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (21, 14, 6, '\"Židovi koji se zovu Hasideji, a kojima je na čelu Juda Makabej, vode neprestano ratove i dižu bune te ne daju da se kraljevstvo naužije blagostanja.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (21, 14, 7, 'Zato sam ja, lišen pradjedovske časti, to jest velikog svećeništva, došao ovamo,');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (21, 14, 8, 'jer su mi na srcu u prvom redu kraljevska prava, a u drugom naši sugrađani, jer zbog nepromišljenosti spomenutih ljudi sav naš narod trpi nemalu štetu.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (21, 14, 9, 'Kad sve to potanko saznaš, o kralju, po svojoj blagoj čovjekoljubivosti koju gojiš prema svima, udostoj se pobrinuti za dobro naše zemlje i našega naroda, kojemu prijeti pogibao sa svih strana.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (21, 14, 10, 'Jer dok Juda živi, ne može država uživati mira.\"');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (21, 14, 11, 'Čim je to izgovorio, ostali kraljevi prijatelji, neprijateljski raspoloženi prema Judi, još većma uzeše podjarivati Demetrija.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (21, 14, 12, 'On odmah dozva Nikanora, koji je zapovijedao odredom slonova, te ga imenova upraviteljem Judeje i posla ga');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (21, 14, 13, 's nalogom da Judu pogubi a njegove ljude rastjera te da Alkima postavi za velikog svećenika veličanstvenog Svetišta.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (21, 14, 14, 'Oni pogani koji bijahu pred Judom iz Judeje pobjegli pridružiše se hrpimice Nikanoru, jer su mislili da će se nezgode i nesreće Židova okrenuti u njihovu korist.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (21, 14, 15, 'Kad su Židovi čuli za Nikanorov dolazak i za navalu pogana, posuli su se prašinom i stali se moliti Onome koji je dovijeka uspostavio svoj narod i koji se uvijek vidljivim znakovima zauzima za svoju Baštinu.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (21, 14, 16, 'Na nalog svog zapovjednika odmah krenuše odande i sukobiše se s njima kod mjesta Desaua.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (21, 14, 17, 'Judin brat Šimun uhvati se s Nikanorom, ali, iznenađen neočekivanim dolaskom protivničkih četa, pretrpje malen neuspjeh.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (21, 14, 18, 'Ipak se Nikanor bojao da odluči krvlju, jer je čuo o junaštvu Jude i njegovih, o njihovoj neustrašivosti u bojevima za domovinu.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (21, 14, 19, 'Zato je poslao Posidonija, Teodota i Natatiju da Židovima predlože i prihvate mirovne ponude.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (21, 14, 20, 'Ispitavši dublje te prijedloge, zapovjednik ih priopći svojim vojnicima; pokazalo se da su jednodušni i da pristaju na nagodbu.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (21, 14, 21, 'Uglavili su dan kada će se zapovjednici sastati na istom mjestu. Tada su sa svake strane došla po jedna bojna kola te su postavili počasne stolice.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (21, 14, 22, 'Juda je na prikladnim mjestima razmjestio naoružane ljude spremne ako bi neprijatelji iznenada što vjerolomno pokušali. Lijepo su se sporazumjeli.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (21, 14, 23, 'Nikanor se zadržao u Jeruzalemu, ne čineći ništa nepravedno. Štoviše, otpustio je ljude koji se bijahu okupili oko njega.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (21, 14, 24, 'Judu je neprestano imao uza se, jer je u srcu osjećao sklonost prema tom čovjeku.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (21, 14, 25, 'Nagovorio ga da se oženi i da ima djecu. Juda se oženio, živio u blagostanju i nauživao se života.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (21, 14, 26, 'Kad je Alkim vidio njihovu međusobnu sklonost i shvatio da su sklopili ugovor, otišao je Demetriju i rekao mu da Nikanor ima izdajničke namjere, jer je Judu, protivnika njegova kraljevstva, imenovao nasljednikom.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (21, 14, 27, 'Nato se kralj razgnjevi: razjaren klevetama tog nitkova, napisa Nikanoru pismo i poruči mu da zbog nagodbe veoma negoduje; i zapovjedi mu da mu odmah u Antiohiju pošalje Makabeja okovana.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (21, 14, 28, 'Kad je to stiglo Nikanoru, zbunio se, jer mu bijaše teško da pogazi nagodbu s čovjekom koji nije ništa kriv.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (21, 14, 29, 'Ali kako nije bilo moguće usprotiviti se kralju, vrebao je prigodu da taj nalog izvrši lukavštinom.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (21, 14, 30, 'Makabej je ipak zamijetio da se Nikanor hladnije vlada prema njemu i da ga susreće grublje nego što je običavao te nasluti da ta hladnoća nije dobar znak. Zato skupi oko sebe mnogo svojih pristalica i stade izbjegavati Nikanora.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (21, 14, 31, 'A ovaj, videći kako ga je čovjek vješto nadmudrio, pođe u uzvišeni i sveti Hram upravo kad su svećenici prinosili obredne žrtve i zapovjedi da mu predaju tog čovjeka.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (21, 14, 32, 'Kako su mu oni pod zakletvom izjavljivali da ne znaju gdje je čovjek koga traži,');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (21, 14, 33, 'on podiže desnicu prema Hramu i zakle se ovako: \"Ako mi ne predate Judu svezana lancima, sravnit ću to Božje svetište sa zemljom, raskopat ću žrtvenik te ću na istome mjestu podići divan hram Dionizu.\"');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (21, 14, 34, 'Rekavši to, ode. Tada svećenici podigoše ruke prema nebu i zazvaše Onoga koji je uvijek branio naš narod:');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (21, 14, 35, '\"O ti Gospodaru komu ništa ne treba, tebi se svidjelo da se Hram u kojem prebivaš nalazi među nama.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (21, 14, 36, 'Zato sad, sveti Gospodaru svake svetosti, sačuvaj dovijeka neoskvrnjen ovaj Dom koji je nedavno očišćen.\"');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (21, 14, 37, 'Uto Nikanoru optužiše Razisa, jednog od jeruzalemskih starješina, čovjeka koji je ljubio svoje sugrađane i bio na vrlo dobru glasu, pa su ga zbog njegove dobrote nazivali ocem Židova.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (21, 14, 38, 'On je već u prvim vremenima pobune bio okrivljen zbog židovstva te se tijelom i dušom najpostojanije izložio za židovstvo.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (21, 14, 39, 'Stoga je Nikanor, da pokaže svoju otvorenu nesklonost prema Židovima, poslao preko pet stotina vojnika da ga uhvate,');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (21, 14, 40, 'jer nije sumnjao da će nestanak tog čovjeka za Židove značiti težak udarac.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (21, 14, 41, 'Kad je, dakle, rulja već gotovo osvojila kulu i jurišala na ulazna vrata, kad je već bio izdan nalog da se podmetne vatra i vrata zapale, Razis se, opkoljen odasvud, baci na vlastiti mač.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (21, 14, 42, 'Radije je htio časno poginuti nego dopasti u bezbožničke ruke da podnosi uvrede nedostojne njegove plemenitosti.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (21, 14, 43, 'Ali kako se u bojnoj žurbi nije smrtno pogodio, a rulja na vrata prodirala unutra, odvažno otrča na zid te se junački strmoglavi na rulju.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (21, 14, 44, 'Kako su se svi odmah razmakli, pade usred praznine.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (21, 14, 45, 'Još dišući, ponesen gnjevom, ustade sav obliven krvlju i unatoč teškim ranama potrča kroz rulju te stade na strmu pećinu.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (21, 14, 46, 'Već posve bez krvi, istrže sebi utrobu uhvativši je objema rukama te je baci na rulju, moleći Gospodara života i duha da mu je jednom opet vrati. Tako je preminuo.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (21, 15, 1, 'Kad je Nikanor doznao da se Juda i njegovi nalaze u području Samarije, odlučio je da ih bez ikakve opasnosti napadne na dan počinka.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (21, 15, 2, 'Židovi koji su ga prisilno slijedili opomenuše ga: \"Nemoj ih tako divljački i barbarski zatirati, nego poštuj dan što ga je Onaj koji bdi nad svime napose posvetio.\"');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (21, 15, 3, 'Tada ih taj trostruki zlikovac upita postoji li na nebu vladalac koji je zapovjedio da se svetkuje dan subotnji.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (21, 15, 4, 'Kad su mu oni izjavili: \"Postoji živi Gospod, Vladalac na nebu, koji zapovjedi da se svetkuje sedmi dan\",');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (21, 15, 5, 'on odgovori: \"A ja sam vladalac na zemlji i ja zapovijedam da se pograbi oružje i da se izvrše kraljevski poslovi.\" Ipak mu nije uspjelo da izvrši svoju zločinačku odluku.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (21, 15, 6, 'Dok se Nikanor u krajnjoj razmetljivosti nadimao te odlučio da plijenom, otetim Judi i njegovima, podigne zajednički spomenik,');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (21, 15, 7, 'Makabej se opet postojano i nepokolebljivo uzdao da će mu Gospodin priteći u pomoć.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (21, 15, 8, 'Hrabrio je svoje ljude neka se ne plaše navale pogana, nego neka se sjete pomoći što su je od Neba već primili i nadaju se da će im i sada Svemogući udijeliti pobjedu.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (21, 15, 9, 'Osokolivši ih riječima Zakona i Proroka, podsjetivši ih na bojeve što su ih već b§ili, učvrsti ih u hrabrosti.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (21, 15, 10, 'Kad im je tako osmjelio srca, još ih upozori kako pogani okreću vjerom i krše zakletvu.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (21, 15, 11, 'Pošto je tako svakoga od njih naoružao manje pouzdanjem u štitove i koplja a više smjelošću i pobudnim riječima, ispriča im vjerodostojan san, viđenje, a oni mu se svi obradovaše.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (21, 15, 12, 'Evo što je vidio: bivši veliki svećenik Onija, čovjek dobar i čestit, skroman u ophođenju, blage ćudi, otmjen u govoru, od djetinjstva vičan svakoj kreposti, podigao ruke i molio za svu židovsku zajednicu.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (21, 15, 13, 'Zatim se Judi ukazao i čovjek vremešan i častan, čudesna i veličanstvena dostojanstva.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (21, 15, 14, 'Tada Onija progovori: \"Ovo je ljubitelj svoje braće koji se mnogo moli za narod i za sav Sveti grad - Božji prorok Jeremija.\"');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (21, 15, 15, 'Nato Jeremija pruži desnicu i Judi preda zlatan mač. Predajući mu ga, reče:');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (21, 15, 16, '\"Prihvati ovaj sveti mač: Božji je dar, njime ćeš slomiti neprijatelje!\"');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (21, 15, 17, 'Obodreni tim lijepim Judinim riječima, što su mogle nadahnuti junaštvom i mlada srca ispuniti muževnošću, Židovi odlučiše da se i ne utabore, nego da odmah navale i junački, u borbi prsa o prsa, sve riješe, budući da su Grad i svetinje i Hram bili u opasnosti.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (21, 15, 18, 'Nisu se toliko zabrinjavali za žene, djecu, braću i rođake, koliko ih je morio najveći i prvi strah - strah za posvećeni Hram.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (21, 15, 19, 'Ali je i one koji su ostali u gradu obuzimala velika tjeskoba: bili su u strahu zbog bitke na otvorenom polju.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (21, 15, 20, 'Svi su iščekivali ishod bitke: neprijatelj se već bio sabrao i svrstao za boj, slonove su doveli na prikladna mjesta, a konjanike razmjestili na krilima.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (21, 15, 21, 'Makabej vidje to veliko mnoštvo, raznovrsnu opremu i strašnu pojavu slonova. Podiže ruke k nebu i zazva čudotvorca Gospodina, jer je znao da on pobjede ne dijeli prema oružju nego prema tomu koga smatra dostojnim.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (21, 15, 22, 'Zazvao je ovako: \"Ti si, o Gospodaru, za judejskog kralja Ezekije poslao svog anđela, koji pobi sto osamdeset i pet tisuća Sanheribovih ljudi.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (21, 15, 23, 'Zato, o nebeski Vladaru, pošalji i sad ispred nas dobra anđela da sije strah i trepet!');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (21, 15, 24, 'Jakom mišicom svojom udari one koji, huleći, izađoše da napadnu tvoj sveti narod!\" Tako je završio molitvu.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (21, 15, 25, 'Dok su se Nikanorove čete primicale uz jeku truba i bojne pjesme,');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (21, 15, 26, 'Judini se ljudi sukobiše s neprijateljem uz vapaje i molitve.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (21, 15, 27, 'Boreći se rukama a moleći se srcima Bogu, oborili su ne manje od trideset i pet tisuća ljudi, obradovani očevidnom Božjom pomoći.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (21, 15, 28, 'Kad su se poslije boja veselo vraćali, opaziše Nikanora gdje leži u bojnoj opremi.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (21, 15, 29, 'Podiže se vika i nasta metež, a oni uzeše slaviti Svemogućega jezikom svojih otaca.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (21, 15, 30, 'Nato Juda, koji se tijelom i dušom bacio u prve redove za svoje sugrađane i koji je prema svojim sunarodnjacima gajio mladenačku blagonaklonost, zapovjedi da Nikanoru odsijeku glavu i ruku u ramenu i odnesu ih u Jeruzalem.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (21, 15, 31, 'I sam je onamo pošao, sazvao svoje sunarodnjake i svećenike te stao pred žrtvenik. Tada posla po one u Tvrđi:');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (21, 15, 32, 'pokaza im glavu zločinačkog Nikanora i ruku koju taj hulitelj bijaše drzovito podigao protiv svetog Doma Svevladara.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (21, 15, 33, 'Odrezavši jezik bezbožnog Nikanora, naredi da se komad po komad dade pticama i da se pred Hramom objesi njegova luđačka ruka.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (21, 15, 34, 'Svi su tada, upravivši oči nebu, blagoslivljali Gospoda koji se očitovao: \"Blagoslovljen bio Onaj koji je svoje Prebivalište sačuvao neoskvrnjeno!\"');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (21, 15, 35, 'Juda objesi Nikanorovu glavu na Tvrđu, da svima bude na vidiku kao očevidan znak pomoći Gospodnje.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (21, 15, 36, 'Svi jednodušno zaključiše da se taj dan nipošto ne zaboravi, nego da se slavi trinaestog dana dvanaestog mjeseca, koji se aramejskim jezikom zove Adar, uoči dana Mordokajeva.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (21, 15, 37, 'Budući da je s Nikanorom dokončano te su Hebreji od tog vremena zavladali gradom, ja ću ovim završiti svoju povijest.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (21, 15, 38, 'Ako sam je dobro i vješto sastavio, ispunila mi se želja. Ako li slabo i osrednje, učinio sam što sam mogao.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (21, 15, 39, 'Jer kao što je štetno piti samo vino ili samu vodu, dok je vino pomiješano s vodom tečnije i ugodnije, tako se i pravilno raspoređen prikaz sviđa ušima onih koji knjigu slušaju. Time završavam. #THE UNBOUND BIBLE (www.unboundbible.org) #name Ukrainian: NT (P.Kulish, 1871) #filetype Unmapped-BCVS #copyright #abbreviation #language ukr #note #columns orig_book_index orig_chapter orig_verse orig_subverse order_by text');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (22, 1, 1, 'Bijaše nekoć u zemlji Usu čovjek po imenu Job. Bio je to čovjek neporočan i pravedan: bojao se Boga i klonio zla.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (22, 1, 2, 'Rodilo mu se sedam sinova i tri kćeri.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (22, 1, 3, 'Imao je sedam tisuća ovaca, tri tisuće deva, pet stotina jarmova goveda, pet stotina magarica i veoma mnogo služinčadi. Čovjek taj bijaše najugledniji među svim istočnjacima.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (22, 1, 4, 'Sinovi su njegovi običavali naizmjence priređivati gozbe kod jednoga od njih, svaki u svoj dan, te su pozivali svoje tri sestre da jedu i piju s njima.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (22, 1, 5, 'A kad bi se izredali s gozbama, Job bi ih pozvao na očišćenje. Uranio bi izjutra i prinio paljenice za svakog od njih; mislio je: \"Tko zna nisu li mi sinovi griješili i u srcu Boga hulili!\" Tako je Job svagda činio.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (22, 1, 6, 'Jednoga dana dođu sinovi Božji da stanu pred Jahvu, a među njima pristupi i Satan.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (22, 1, 7, 'Jahve tad upita Satana: \"Odakle dolaziš?\" - \"Evo prođoh zemljom i obiđoh je\", odgovori on.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (22, 1, 8, 'Nato će Jahve: \"Nisi li zapazio slugu moga Joba? Njemu na zemlji nema ravna. Čovjek je to neporočan i pravedan, boji se Boga i kloni zla!\"');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (22, 1, 9, 'A Satan odgovori Jahvi: \"Zar se Job uzalud Boga boji?');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (22, 1, 10, 'Zar nisi ogradio njega, kuću mu i sav posjed njegov? Blagoslovio si djelo njegovih ruku, stoka mu se namnožila po zemlji.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (22, 1, 11, 'Ali pruži jednom ruku i dirni mu u dobra: u lice će te prokleti!\"');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (22, 1, 12, '\"Neka ti bude! - reče Jahve Satanu. - Sa svime što ima radi što ti drago; samo ruku svoju na nj ne diži.\" I Satan ode ispred lica Jahvina.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (22, 1, 13, 'Jednoga dana, dok su Jobovi sinovi i kćeri jeli i pili vino u kući najstarijeg brata,');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (22, 1, 14, 'dođe glasnik k Jobu i reče: \"Tvoji su volovi orali a magarice pokraj njih pasle,');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (22, 1, 15, 'kad iznenada Sabejci navališe na njih i oteše ih, pobivši momke oštrim mačem. Jedini ja utekoh da ti ovo javim.\"');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (22, 1, 16, 'Dok je on još to govorio, dođe drugi i reče: \"Oganj Božji udari s neba, spali tvoje ovce i pastire te ih proždrije. Jedini ja utekoh da ti javim.\"');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (22, 1, 17, 'Dok je još govorio, dođe treći i reče: \"Kaldejci navališe sa tri čete na tvoje deve i oteše ih, pobivši momke oštrim mačem. Jedini ja utekoh da ti javim.\"');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (22, 1, 18, 'Dok je ovaj još govorio, dođe četvrti i reče: \"Tvoji su sinovi i kćeri jeli i pili vino u kući najstarijeg brata.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (22, 1, 19, 'I gle, vjetar se silan diže iz pustinje, udari na sva četiri ugla kuće, obori je na djecu te ona zaglaviše. Jedini ja utekoh da ti javim.\"');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (22, 1, 20, 'Tad ustade Job, razdrije haljinu na sebi, obrija glavu pa ničice pade na zemlju, pokloni se');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (22, 1, 21, 'i reče: \"Go iziđoh iz krila majčina, go ću se onamo i vratiti. Jahve dao, Jahve oduzeo! Blagoslovljeno ime Jahvino!\"');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (22, 1, 22, 'Uza sve to, nije sagriješio Job niti je kakvu ludost protiv Boga izustio.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (22, 2, 1, 'Jednoga dana dođu opet sinovi Božji da stanu pred Jahvu, a među njima pristupi i Satan.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (22, 2, 2, 'Jahve tad upita Satana: \"Odakle dolaziš?\" - \"Evo prođoh zemljom i obiđoh je\", odgovori on.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (22, 2, 3, 'Nato će Jahve: \"Nisi li zapazio slugu moga Joba? Njemu na zemlji nema ravna. Čovjek je to neporočan i pravedan: boji se Boga i kloni zla! On je još postojan u neporočnosti, pa si me uzalud izazvao da ga upropastim.\"');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (22, 2, 4, 'A Satan odvrati: \"Koža za kožu! Sve što čovjek ima dat će za život.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (22, 2, 5, 'Ali pruži ruku, dotakni se kosti njegove i mesa: u lice će te prokleti!\"');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (22, 2, 6, '\"Neka ti bude! - reče Jahve Satanu. - U tvojoj je ruci; život mu samo sačuvaj!\"');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (22, 2, 7, 'I Satan ode ispred lica Jahvina. On udari Joba zlim prištem od tabana do tjemena.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (22, 2, 8, 'Job uze crijep da se struže njime i sjede u pepeo.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (22, 2, 9, 'Tada mu njegova žena reče: \"Zar si još postojan u neporočnosti? Prokuni Boga i umri!\"');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (22, 2, 10, 'Job joj odgovori: \"Brbljaš kao luđakinja! Kad od Boga primamo dobro, zar da onda i zlo ne primimo?\" U svemu tome Job nije sagriješio svojim usnama.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (22, 2, 11, 'U to čuše tri Jobova prijatelja za sve nevolje koje ga zadesiše; svaki se zaputi iz svoga kraja - Elifaz iz Temana, Bildad iz Šuaha, Sofar iz Naama - i odlučiše da odu zajedno ožaliti ga i utješiti.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (22, 2, 12, 'A kad su izdaleka upravili oči na njega, nisu ga prepoznali. Tad udariše u plač; svaki razdrije svoju haljinu i prosu prah po glavi.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (22, 2, 13, 'Potom sjedoše kraj njega na zemlju i ostadoše tako sedam dana i sedam noći. Nijedan mu ne progovori ni riječi, jer vidješe da je velika njegova bol.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (22, 3, 1, 'Napokon otvori Job usta i prokle dan svoj;');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (22, 3, 2, 'poče svoju besjedu i reče:');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (22, 3, 3, '\"O, ne bilo dana kad sam se rodio i noći što javi: \'Začeo se dječak!\'');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (22, 3, 4, 'U crnu tminu dan taj nek se prometne! S visina se njega Bog ne spominjao, svjetlost sunčeva ne svijetlila mu više!');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (22, 3, 5, 'Mrak i sjena smrtna o nj se otimali, posvema ga tmina gusta prekrila, pomrčine dnevne stravom ga morile!');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (22, 3, 6, 'O, da bi ga tama svega presvojila, nek\' se ne dodaje danima godine, nek\' ne ulazi u brojenje mjeseci!');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (22, 3, 7, 'A noć ona bila žalosna dovijeka, ne čulo se u njoj radosno klicanje!');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (22, 3, 8, 'Prokleli je oni štono dan proklinju i Levijatana probudit\' su kadri!');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (22, 3, 9, 'Pomrčale zvijezde njezina svanuća, zaludu se ona vidjelu nadala, i zorinih vjeđa ne gledala nigda!');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (22, 3, 10, 'Što mi od utrobe ne zatvori vrata da sakrije muku od mojih očiju!');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (22, 3, 11, 'Što nisam mrtav od krila materina, što ne izdahnuh izlazeć\' iz utrobe?');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (22, 3, 12, 'Čemu su me dva koljena prihvatila i dojke dvije da me nejaka podoje?');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (22, 3, 13, 'U miru bih vječnom počivao sada, spavao bih, pokoj svoj bih uživao');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (22, 3, 14, 's kraljevima i savjetnicima zemlje koji su sebi pogradili grobnice,');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (22, 3, 15, 'ili s knezovima, zlatom bogatima, što su kuće svoje srebrom napunili.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (22, 3, 16, 'Ne bih bio - k\'o nedonošče zakopano, k\'o novorođenče što svjetla ne vidje.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (22, 3, 17, 'Zlikovci se više ne obijeste ondje, iznemogli tamo nalaze počinka.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (22, 3, 18, 'Sužnjeve na miru tamo ostavljaju: ne slušaju više poviku stražara.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (22, 3, 19, 'Malen ondje leži zajedno s velikim, rob je slobodan od gospodara svoga.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (22, 3, 20, 'Čemu darovati svjetlo nesretniku i život ljudima zagorčene duše');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (22, 3, 21, 'koji smrt ištu, a ona ne dolazi, i kao za blagom za njome kopaju?');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (22, 3, 22, 'Grobnom bi se humku oni radovali, klicali od sreće kad bi grob svoj našli.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (22, 3, 23, 'Što će to čovjeku kom je put sakriven, koga je Bog sa svih strana zapriječio?');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (22, 3, 24, 'Zato videć\' hranu, uzdahnuti moram, k\'o voda se moji razlijevaju krici.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (22, 3, 25, 'Obistinjuje se moje strahovanje, snalazi me, evo, čega god se bojah.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (22, 3, 26, 'Pokoja ni mira meni više nema, u mukama mojim nikad mi počinka.\"');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (22, 4, 1, 'Tad prozbori Elifaz Temanac i reče:');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (22, 4, 2, '\"Možeš li podnijeti da ti progovorim? Ali tko se može uzdržat\' od riječi!');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (22, 4, 3, 'Eto, mnoge ljude ti si poučio, okrijepio si iznemogle mišice;');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (22, 4, 4, 'riječju svojom klonule si pridizao, ojačavao si koljena klecava.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (22, 4, 5, 'A kad tebe stiže, klonuo si duhom, na tebe kad pade, čitav si se smeo!');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (22, 4, 6, 'Zar pobožnost tvoja nadu ti ne daje, neporočnost tvoja životu ufanje?');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (22, 4, 7, 'TÓa sjeti se: nevin - propade li kada? Kada su zatrti bili pravednici?');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (22, 4, 8, 'Iz iskustva zborim: nesrećom tko ore i nevolju sije, nju će i požeti.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (22, 4, 9, 'Od daha Božjega oni pogibaju, na gnjevni mu disaj nestaju sa zemlje.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (22, 4, 10, 'Rika lavlja, urlik leopardov krše se k\'o zubi u lavića.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (22, 4, 11, 'Lav ugiba jer mu nesta plijena, rasuli se mladi lavičini.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (22, 4, 12, 'Tajna riječ se meni objavila, šapat njen je uho moje čulo.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (22, 4, 13, 'Noću, kada snovi duh obuzmu i san dubok kad na ljude pada,');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (22, 4, 14, 'strah i trepet mene su svladali, kosti moje žestoko se stresle.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (22, 4, 15, 'Dah mi neki preko lica prođe, digoše se dlake na mom tijelu.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (22, 4, 16, 'Stajao je netko - lica mu ne poznah - ali likom bješe pred očima mojim. Posvuda tišina; uto začuh šapat:');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (22, 4, 17, '\'Zar je smrtnik koji pred Bogom pravedan? Zar je čovjek čist pred svojim Stvoriteljem?');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (22, 4, 18, 'Ni slugama svojim više ne vjeruje, i anđele svoje za grijeh okrivljuje -');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (22, 4, 19, 'kako ne bi onda goste stanova glinenih kojima je temelj u prahu zemaljskom. Gle, kao moljce njih sveudilj satiru:');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (22, 4, 20, 'od jutra do mraka u prah pretvore, nestaju zasvagda - nitko i ne vidi.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (22, 4, 21, 'Iščupan je kolčić njihova šatora, pogibaju skoro, mudrost ne spoznavši.\'');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (22, 5, 1, 'Ded zazivlji! Zar će ti se tko odazvat\'? Kojem li se svecu misliš sad obratit\'?');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (22, 5, 2, 'Doista, budalu njegov bijes ubija, luđaka će sasvim skončat ljubomora.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (22, 5, 3, 'Bezumnika vidjeh kako korijen pušta, al\' prokletstvo skoro na kuću mu pade.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (22, 5, 4, 'Njegovi su sinci daleko od spasa, njih nezaštićene na Vratima tlače.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (22, 5, 5, 'Ljetinu njihovu pojedoše gladni, sam Bog ju je njima oteo iz usta, a žedni hlepe za njihovim dobrima.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (22, 5, 6, 'Ne, opačina ne izbija iz zemlje, nit\' nevolja iz tla može nići sama,');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (22, 5, 7, 'nego čovjek rađa muku i nevolju kao što let orlov teži u visinu.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (22, 5, 8, 'Al\' ja bih se ipak Bogu utekao i pred njime stvar bih svoju razložio.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (22, 5, 9, 'Nedokučiva on djela silna stvori, čudesa koja se izbrojit\' ne mogu.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (22, 5, 10, 'On kišom rosi po svem licu zemljinu i vodu šalje da nam polja natapa.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (22, 5, 11, 'Da bi ponižene visoko digao, da bi ojađene srećom obdario,');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (22, 5, 12, 'redom ruši ono što lukavci smisle, što god započeli, on im izjalovi.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (22, 5, 13, 'On hvata mudre u njihovu lukavstvu, naume spletkara obraća u ništa.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (22, 5, 14, 'Posred bijela dana zapadnu u tamu, pipaju u podne kao usred noći.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (22, 5, 15, 'On iz njinih ralja izbavlja jadnika, iz silničkih ruku diže siromaha.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (22, 5, 16, 'Tako se pokaže nada nevoljniku, i nepravda mora zatvoriti usta.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (22, 5, 17, 'Da, blago čovjeku koga Bog odbaci! Stoga ti ne prezri karanje Svesilnog!');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (22, 5, 18, 'On ranjava, ali i ranu povija, udara i svojom zacjeljuje rukom.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (22, 5, 19, 'Iz šest će nevolja tebe izbaviti, ni u sedmoj zlo te dotaknuti neće.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (22, 5, 20, 'U gladi, od smrti on će te spasiti, a u ratu, oštru će te otet maču.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (22, 5, 21, 'Biču zla jezika uklonit će tebe, ispred otimača bez straha ćeš biti.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (22, 5, 22, 'Suši i studeni ti ćeš se smijati i od divljih zvijeri strahovati nećeš.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (22, 5, 23, 'Sklopit\' ti ćeš savez s kamenjem na njivi, zvjerad divlja s tobom u miru će biti.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (22, 5, 24, 'U šatoru svome mir ćeš uživati, dom svoj kad pohodiš netaknut će stajat.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (22, 5, 25, 'Koljeno ćeš svoje gledat\' gdje se množi i potomstvo gdje ti kao trava raste.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (22, 5, 26, 'U grob ti ćeš leći kada budeš zreo, kao što se žito snosi kad dozori.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (22, 5, 27, 'Sve motrismo ovo: istina je živa! zato sve za dobro svoje ti poslušaj.\"');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (22, 6, 1, 'A Job progovori i reče:');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (22, 6, 2, '\"O, kad bi se jad moj izmjeriti mog\'o, a nevolje moje stavit\' na tezulju!');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (22, 6, 3, 'Teže one jesu od sveg pijeska morskog, i stoga mi riječi zastraniti znaju.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (22, 6, 4, 'Strijele Svesilnoga u mojem su mesu, ljuti otrov njihov ispija mi dušu, Božje se strahote oborile na me.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (22, 6, 5, 'TÓa, kraj svježe trave njače li magarac, muče li goveče kraj punih jasala?');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (22, 6, 6, 'Zar hranu bljutavu jedemo bez soli? Zar kakove slasti ima u bjelancu?');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (22, 6, 7, 'Al\' ono što mi se gadilo dotaći, to mi je sada sva hrana u bolesti.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (22, 6, 8, 'O, da bi se molba moja uslišala, da mi Bog ispuni ono čem se nadam!');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (22, 6, 9, 'O, kada bi me Bog uništiti htio, kada bi mahnuo rukom da me satre!');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (22, 6, 10, 'Za mene bi prava utjeha to bila, klicati bih mog\'o u mukama teškim što se ne protivljah odluci Svetoga.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (22, 6, 11, 'Zar snage imam da mogu čekati? Radi kakve svrhe da ja duže živim?');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (22, 6, 12, 'Zar je snaga moja k\'o snaga kamena, zar je tijelo moje od mjedi liveno?');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (22, 6, 13, 'Na što se u sebi osloniti mogu? Zar mi svaka pomoć nije uskraćena?');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (22, 6, 14, 'Tko odbija milost bližnjemu svojemu, prezreo je strah od Boga Svesilnoga.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (22, 6, 15, 'Kao potok me iznevjeriše braća, kao bujice zimske svoje korito.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (22, 6, 16, 'Od leda mutne vode im se nadimlju, \'bujaju od snijega što se topit\' stao;');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (22, 6, 17, 'al u doba sušno naskoro presahnu, od žege ishlape tada iz korita.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (22, 6, 18, 'Karavane zbog njih skreću sa putova, u pustinju zađu i u njoj se gube.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (22, 6, 19, 'Karavane temske očima ih traže, putnici iz Šebe nadaju se njima.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (22, 6, 20, 'A kad do njih dođu, nađu se u čudu, jer su se u nadi svojoj prevarili.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (22, 6, 21, 'U ovom ste času i vi meni takvi: vidjeste strahotu pa se preplašiste.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (22, 6, 22, 'Rekoh li vam možda: \'Darujte mi štogod, poklonite nešto od svojega blaga;');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (22, 6, 23, 'iz šake dušmanske izbavite mene, oslobodite me silnikova jarma?\'');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (22, 6, 24, 'Vi me poučite, pa ću ušutjeti, u čem je moj prijestup, pokažite meni.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (22, 6, 25, 'O, kako su snažne besjede iskrene! Al\' kamo to vaši smjeraju prijekori?');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (22, 6, 26, 'Mislite li možda prekoriti riječi? TÓa u vjetar ide govor očajnikov!');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (22, 6, 27, 'Nad sirotom kocku zar biste bacali i sa prijateljem trgovali svojim?');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (22, 6, 28, 'U oči me sada dobro pogledajte, paz\'te neću li vam slagati u lice.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (22, 6, 29, 'Povucite riječ! Kakve li nepravde! Povucite riječ, neporočan ja sam!');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (22, 6, 30, 'Zar pakosti ima na usnama mojim? Zar nesreću svaku okusio nisam?');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (22, 7, 1, 'Nije l\' vojska život čovjekov na zemlji? Ne provodi l\' dane poput najamnika?');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (22, 7, 2, 'Kao što trudan rob za hladom žudi, poput nadničara štono plaću čeka,');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (22, 7, 3, 'mjeseci jada tako me zapadoše i noći su mučne meni dosuđene.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (22, 7, 4, 'Liježuć\' mislim svagda: \'Kada ću ustati?\' A dižuć se: \'Kada večer dočekati!\' I tako se kinjim sve dok se ne smrkne.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (22, 7, 5, 'PÓut moju crvi i blato odjenuše, koža na meni puca i raščinja se.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (22, 7, 6, 'Dani moji brže od čunka prođoše, promakoše hitro bez ikakve nade.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (22, 7, 7, 'Spomeni se: život moj je samo lahor i oči mi neće više vidjet\' sreće!');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (22, 7, 8, 'Prijateljsko oko neće me gledati; pogled svoj u mene upro si te sahnem.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (22, 7, 9, 'Kao što se oblak gubi i raspline, tko u Šeol siđe, više ne izlazi.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (22, 7, 10, 'Domu svome natrag ne vraća se nikad, njegovo ga mjesto više ne poznaje.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (22, 7, 11, 'Ustima ja svojim stoga branit\' neću, u tjeskobi duha govorit ću sada, u gorčini duše ja ću zajecati.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (22, 7, 12, 'Zar sam more ili neman morska, pa si stražu nada mnom stavio?');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (22, 7, 13, 'Kažem li: \'Na logu ću se smirit\', ležaj će mi olakšati muke\',');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (22, 7, 14, 'snovima me prestravljuješ tada, prepadaš me viđenjima mučnim.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (22, 7, 15, 'Kamo sreće da mi se zadavit\'! Smrt mi je od patnja mojih draža.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (22, 7, 16, 'Ja ginem i vječno živjet neću; pusti me, tek dah su dani moji!');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (22, 7, 17, 'Što je čovjek da ga toliko ti cijeniš, da je srcu tvojem tako prirastao');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (22, 7, 18, 'i svakoga jutra da njega pohodiš i svakoga trena da ga iskušavaš?');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (22, 7, 19, 'Kada ćeš svoj pogled skinuti sa mene i dati mi barem pljuvačku progutat\'?');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (22, 7, 20, 'Ako sam zgriješio, što učinih tebi, o ti koji pomno nadzireš čovjeka? Zašto si k\'o metu mene ti uzeo, zbog čega sam tebi na teret postao?');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (22, 7, 21, 'Zar prijestupa moga ne možeš podnijeti i ne možeš prijeći preko krivnje moje? Jer, malo će proći i u prah ću leći, ti ćeš me tražiti, al\' me biti neće.\"');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (22, 8, 1, 'Bildan iz Šuaha progovori tad i reče:');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (22, 8, 2, '\"Dokad ćeš jošte govoriti tako, dokle će ti riječ kao vihor biti?');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (22, 8, 3, 'TÓa zar može Bog pravo pogaziti, može li pravdu izvrnut\' Svesilni?');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (22, 8, 4, 'Ako mu djeca tvoja sagriješiše, preda ih zato bezakonju njinu.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (22, 8, 5, 'Al\' ako Boga potražiš iskreno i od Svesilnog milost ti izmoliš;');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (22, 8, 6, 'ako li budeš čist i neporočan, odsad će svagda on nad tobom bdjeti i obnovit će kuću pravedniku.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (22, 8, 7, 'Bit će malena tvoja sreća prošla prema budućoj što te očekuje.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (22, 8, 8, 'No pitaj samo prošle naraštaje, na mudrost pređa njihovih pripazi.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (22, 8, 9, 'Od jučer mi smo i ništa ne znamo, poput sjene su na zemlji nam dani.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (22, 8, 10, 'Oni će te poučit\' i reći ti, iz srca će svog izvući besjede:');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (22, 8, 11, '\'Izvan močvare zar će rogoz nići? Zar će bez vode trstika narasti?');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (22, 8, 12, 'Zeleni se sva, al\' i nekošena usahne prije svake druge trave.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (22, 8, 13, 'To je kob svakog tko Boga zaboravi; tako propada nada bezbožnika:');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (22, 8, 14, 'Nit je tanana njegovo uzdanje, a ufanje mu kuća paukova.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (22, 8, 15, 'Nasloni li se, ona mu se ljulja, prihvati li se, ona mu se ruši.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (22, 8, 16, 'Zeleni se i sav na suncu buja, vrt su mu cio mladice prerasle.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (22, 8, 17, 'Svojim korijenjem krš je isprepleo te život crpe iz živa kamena.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (22, 8, 18, 'A kad ga s mjesta njegova istrgnu, ono ga niječe: \'Nikada te ne vidjeh!\'');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (22, 8, 19, 'I evo gdje na putu sada trune dok drugo bilje već niče iz zemlje.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (22, 8, 20, 'Ne, Bog neće odbacit\' neporočne, niti će rukom poduprijet\' opake.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (22, 8, 21, 'Smijeh će ti opet ispuniti usta, s usana će odjeknuti klicanje.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (22, 8, 22, 'Dušmane će ti odjenut\' sramota i šatora će nestat\' zlikovačkog.\'\"');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (22, 9, 1, 'Job progovori i reče:');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (22, 9, 2, '\"Zaista, dobro ja znadem da je tako: kako da pred Bogom čovjek ima pravo?');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (22, 9, 3, 'Ako bi se tkogod htio prÓeti s njime, odvratio mu ne bi ni jednom od tisuću.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (22, 9, 4, 'Srcem on je mudar, a snagom svesilan, i tko bi se njemu nekažnjeno opro?');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (22, 9, 5, 'On brda premješta, a ona to ne znaju, u jarosti svojoj on ih preokreće.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (22, 9, 6, 'Pokreće on zemlju sa njezina mjesta, iz temelja njene potresa stupove.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (22, 9, 7, 'Kad zaprijeti suncu, ono se ne rađa, on pečatom svojim i zvijezde pečati.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (22, 9, 8, 'Jedini on je nebesa razapeo i pučinom morskom samo on hodao.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (22, 9, 9, 'Stvorio je Medvjede i Oriona, Vlašiće i zvijezđa na južnome nebu.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (22, 9, 10, 'Tvorac on je djela silnih, nepojmljivih čudesa koja se izbrojit\' ne mogu.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (22, 9, 11, 'Ide pored mene, a ja ga ne vidim; evo, on prolazi - ja ga ne opažam.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (22, 9, 12, 'Ugrabi li što, tko će mu to priječit, i tko ga pitat smije: \'Što si učinio?\'');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (22, 9, 13, 'Bog silni srdžbu svoju ne opoziva: pred njim poniču saveznici Rahaba.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (22, 9, 14, 'Pa kako onda da njemu odgovorim, koju riječ da protiv njega izaberem?');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (22, 9, 15, 'I da sam u pravu, odvratio ne bih, u suca svojega milost bih molio.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (22, 9, 16, 'A kad bi se na zov moj i odazvao, vjerovao ne bih da on glas moj sluša.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (22, 9, 17, 'Jer, za dlaku jednu on mene satire, bez razloga moje rane umnožava.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (22, 9, 18, 'Ni časa jednoga predahnut\' mi ne da, nego mene svakom gorčinom napaja!');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (22, 9, 19, 'Ako je na snagu - tÓa on je najjači! Ako je na pravdu - tko će njega na sud?');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (22, 9, 20, 'Da sam i prav, usta bi me osudila, da sam i nevin, zlim bi me proglasila.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (22, 9, 21, 'A jesam li nevin? Ni sam ne znam više, moj je život meni sasvim omrzao!');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (22, 9, 22, 'Jer, to je svejedno; i zato ja kažem: nevina i grešnika on dokončava.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (22, 9, 23, 'I bič smrtni kad bi odjednom ubijo... ali on se ruga nevolji nevinih.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (22, 9, 24, 'U zemlji predanoj u šake zlikovaca, on oči sucima njezinim zastire. Ako on to nije, tko je drugi onda?');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (22, 9, 25, 'Od skoroteče su brži moji dani, bježe daleko, nigdje dobra ne videć.\'');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (22, 9, 26, 'K\'o čamci od rogoza hitro promiču, k\'o orao na plijen kada se zaleti.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (22, 9, 27, 'Kažem li: zaboravit ću jadikovku, razvedrit ću lice i veseo biti,');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (22, 9, 28, 'od mojih me muka groza obuzima, jer znadem da me ti ne držiš nevinim.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (22, 9, 29, 'Ako li sam grešan, tÓa čemu onda da zalud mučim sebe.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (22, 9, 30, 'Kad bih i sniježnicom sebe ja isprao, kad bih i lugom ruke svoje umio,');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (22, 9, 31, 'u veću bi me nečist opet gurnuo, i moje bi me se gnušale haljine!');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (22, 9, 32, 'Nije čovjek k\'o ja da se s njime pravdam i na sud da idem s njim se parničiti.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (22, 9, 33, 'Niti kakva suca ima među nama da ruke svoje stavi na nas dvojicu,');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (22, 9, 34, 'da šibu njegovu od mene odmakne, da užas njegov mene više ne plaši!');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (22, 9, 35, 'Govorit ću ipak bez ikakva straha, jer ja nisam takav u svojim očima!');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (22, 10, 1, 'Kad mi je duši život omrznuo, nek\' mi tužaljka poteče slobodno, zborit ću u gorčini duše svoje.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (22, 10, 2, 'Reću ću Bogu: Nemoj me osudit! Kaži mi zašto se na me obaraš.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (22, 10, 3, 'TÓa što od toga imaš da me tlačiš, da djelo ruku svojih zabacuješ, da pomažeš namjerama opakih?');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (22, 10, 4, 'Jesu li u tebe oči tjelesne? Zar ti vidiš kao što čovjek vidi?');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (22, 10, 5, 'Zar su ti dani k\'o dani smrtnika a kao ljudski vijek tvoje godine?');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (22, 10, 6, 'Zbog čega krivnju moju istražuješ i grijehe moje hoćeš razotkriti,');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (22, 10, 7, 'kad znadeš dobro da sam nedužan, da ruci tvojoj izmaknut ne mogu?');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (22, 10, 8, 'Tvoje me ruke sazdaše, stvoriše, zašto da me sada opet raščiniš!');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (22, 10, 9, 'Sjeti se, k\'o glinu si me sazdao i u prah ćeš me ponovo vratiti.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (22, 10, 10, 'Nisi li mene k\'o mlijeko ulio i učinio da se k\'o sir zgrušam?');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (22, 10, 11, 'Kožom si me i mesom odjenuo, kostima si me spleo i žilama.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (22, 10, 12, 'S milošću si mi život darovao, brižljivo si nad mojim bdio dahom.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (22, 10, 13, 'Al\' u svom srcu ovo si sakrio, znam da je tvoja to bila namjera:');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (22, 10, 14, 'da paziš budno hoću li zgriješiti i da mi grijeh ne prođe nekažnjeno.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (22, 10, 15, 'Ako sam grešan, onda teško meni, ako li sam prav, glavu ne smijem dići - shrvan sramotom, nesrećom napojen!');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (22, 10, 16, 'Ispravim li se, k\'o lav me nagoniš, snagu svoju okušavaš na meni,');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (22, 10, 17, 'optužbe nove na mene podižeš, jarošću većom na mene usplamtiš i sa svježim se četama obaraš.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (22, 10, 18, 'Iz utrobe što si me izvukao? O, što ne umrijeh: vidjeli me ne bi,');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (22, 10, 19, 'bio bih k\'o da me ni bilo nije, iz utrobe u grob bi me stavili.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (22, 10, 20, 'Mog su života dani tako kratki! Pusti me da se još malo veselim');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (22, 10, 21, 'prije nego ću na put bez povratka, u zemlju tame, zemlju sjene smrtne,');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (22, 10, 22, 'u zemlju tmine guste i meteža, gdje je svjetlost slična noći najcrnjoj.\"');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (22, 11, 1, 'Sofar iz Naama progovori tad i reče:');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (22, 11, 2, '\"Zar na riječi mnoge da se ne odvrati? Zar će se brbljavac još i opravdati?');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (22, 11, 3, 'Zar će tvoje trice ušutkati ljude, zar će ruganje ostat\' neizrugano?');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (22, 11, 4, 'Rekao si: \'Nauk moj je neporočan, u očima tvojim čist sam i bez ljage.\'');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (22, 11, 5, 'Ali kada bi Bog htio progovorit\' i otvorit usta da ti odgovori');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (22, 11, 6, 'kada bi ti tajne mudrosti otkrio koje um nijedan ne može doumit\', znao bi da ti za grijehe račun ište.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (22, 11, 7, 'Možeš li dubine Božje proniknuti, dokučiti savršenstvo Svesilnoga?');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (22, 11, 8, 'Od neba je više: što još da učiniš? Od Šeola dublje: što još da mudruješ?');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (22, 11, 9, 'Duže je od zemlje - šire je od mora!');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (22, 11, 10, 'Ako se povuče, ako te pograbi, ako na sud preda, tko će mu braniti?');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (22, 11, 11, 'Jer on u čovjeku prozire prijevaru, vidi opačinu ako i ne gleda.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (22, 11, 12, 'Čovjek se bezuman obraća k pameti i divlji magarac uzdi se pokori.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (22, 11, 13, 'Ako li srce svoje ti uspraviš i ruke svoje pružiš prema njemu,');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (22, 11, 14, 'ako li zloću iz ruku odbaciš i u šatoru svom ne daš zlu stana,');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (22, 11, 15, 'čisto ćeš čelo moći tad podići, čvrst ćeš biti i bojati se nećeš.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (22, 11, 16, 'Svojih se kušnja nećeš sjećat\' više kao ni vode koja je protekla.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (22, 11, 17, 'Jasnije će tvoj život sjat\' no podne, tmina će se obratit\' u svanuće.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (22, 11, 18, 'U uzdanju svom živjet ćeš sigurno i zaštićen počivat ćeš u miru.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (22, 11, 19, 'Kad legneš, nitko te buniti neće; mnogi će tvoju tražiti naklonost.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (22, 11, 20, 'A zlikovcima ugasnut će oči, neće im više biti utočišta: izdahnut\', bit će jedina im nada.\"');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (22, 12, 1, 'Job progovori i reče:');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (22, 12, 2, '\"Uistinu, vi ste cvijet naroda, sa vama će izumrijeti mudrost.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (22, 12, 3, 'Al\' i ja znam k\'o i vi misliti, ni u čemu od vas gori nisam: tko za stvari takve ne bi znao?');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (22, 12, 4, 'Prijateljima sam svojim ja na podsmijeh što zazivam Boga da mi odgovori! Na podsmijeh ja sam - pravednik neporočan!');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (22, 12, 5, 'Prezirat\' je nesretnika - sretni misle, udariti treba onog što posrće!');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (22, 12, 6, 'Dotle su na miru šatori pljačkaša, izazivači Boga žive bezbrižno kao da Boga u šaci svojoj drže!');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (22, 12, 7, 'Ali pitaj zvijeri, i poučit će te; ptice nebeske pitaj, i razjasnit će ti.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (22, 12, 8, 'Gušteri zemlje to će ti protumačit\', ribe u moru ispripovjedit će ti.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (22, 12, 9, 'Od stvorenja sviju, koje ne bi znalo da je sve to Božja ruka učinila?!');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (22, 12, 10, 'U ruci mu leži život svakog bića i dah životvorni svakog ljudskog tijela.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (22, 12, 11, 'Zar uhom mi ne sudimo besjedu k\'o što kušamo nepcem okus jela?');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (22, 12, 12, 'Sjedine mudrost donose čovjeku, a s vijekom dugim umnost mu dolazi.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (22, 12, 13, 'Ali u Njemu mudrost je i snaga, u Njemu savjet je i sva razumnost.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (22, 12, 14, 'Što razgradi, sagradit neće nitko, kog zatvori, nitko ne oslobađa.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (22, 12, 15, 'Ustavi li vodu, suša nastaje; pusti li je, svu zemlju ispremetne.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (22, 12, 16, 'Jer u njemu je snaga i sva mudrost, njegov je prevareni i varalica.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (22, 12, 17, 'On savjetnike lišava razbora, suce pametne udara bezumljem.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (22, 12, 18, 'On otpasuje pojas kraljevima i užetom im vezuje bokove.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (22, 12, 19, 'On bosonoge tjera svećenike i mogućnike sa vlasti obara.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (22, 12, 20, 'On diže riječ iz usta rječitima i starcima pravo rasuđivanje.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (22, 12, 21, 'On sasiplje prezir po plemićima i junacima bedra raspasuje.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (22, 12, 22, 'On dubinama razotkriva tmine i sjenu smrtnu na svjetlo izvodi.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (22, 12, 23, 'On diže narod pa ga uništava, umnoži ga a potom iskorijeni.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (22, 12, 24, 'On zaluđuje vladare naroda te po bespuću lutaju pustinjskom');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (22, 12, 25, 'i pipaju u tmini bez svjetlosti glavinjajući poput pijanaca.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (22, 13, 1, 'Očima svojim sve to ja vidjeh, ušima svojim čuh i razumjeh.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (22, 13, 2, 'Sve što vi znate znadem to i ja, ni u čemu od vas gori nisam.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (22, 13, 3, 'Zato, zborit\' moram sa Svesilnim, pred Bogom svoj razlog izložiti.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (22, 13, 4, 'Jer, kovači laži vi ste pravi, i svi ste vi zaludni liječnici!');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (22, 13, 5, 'Kada biste bar znali šutjeti, mudrost biste svoju pokazali!');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (22, 13, 6, 'Dokaze mi ipak poslušajte, razlog mojih usana počujte.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (22, 13, 7, 'Zar zbog Boga govorite laži, zar zbog njega riječi te prijevarne?');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (22, 13, 8, 'Zar biste pristrano branit\' htjeli Boga, zar biste mu htjeli biti odvjetnici?');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (22, 13, 9, 'Zar bi dobro bilo da vas on ispita? Zar biste ga obmanuli k\'o čovjeka?');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (22, 13, 10, 'Kaznom preteškom on bi vas pokarao poradi potajne vaše pristranosti.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (22, 13, 11, 'Zar vas veličanstvo njegovo ne plaši i zar vas od njega užas ne spopada?');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (22, 13, 12, 'Razlozi su vam od pepela izreke, obrana je vaša obrana od blata.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (22, 13, 13, 'Umuknite sada! Dajte da govorim, pa neka me poslije snađe što mu drago.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (22, 13, 14, 'Zar da meso svoje sam kidam zubima? Da svojom rukom život upropašćujem?');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (22, 13, 15, 'On me ubit\' može: nade druge nemam već da pred njim svoje držanje opravdam.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (22, 13, 16, 'I to je već zalog mojega spasenja, jer bezbožnik preda nj ne može stupiti.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (22, 13, 17, 'Pažljivo mi riječi poslušajte, nek\' vam prodre u uši besjeda.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (22, 13, 18, 'Gle: ja sam pripremio parnicu, jer u svoje sam pravo uvjeren.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (22, 13, 19, 'Tko se sa mnom hoće parničiti? - Umuknut ću potom te izdahnut\'.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (22, 13, 20, 'Dvije mi molbe samo ne uskrati da se od tvog lica ne sakrivam:');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (22, 13, 21, 'digni s mene tešku svoju ruku i užasom svojim ne straši me.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (22, 13, 22, 'Tada me pitaj, a ja ću odgovarat\'; ili ja da pitam, ti da odgovaraš.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (22, 13, 23, 'Koliko počinih prijestupa i grijeha? Prekršaj mi moj pokaži i krivicu.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (22, 13, 24, 'Zašto lice svoje kriješ sad od mene, zašto u meni vidiš neprijatelja?');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (22, 13, 25, 'Zašto strahom mučiš list vjetrom progonjen, zašto se na suhu obaraš slamčicu?');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (22, 13, 26, 'O ti, koji mi gorke pišeš presude i teretiš mene grijesima mladosti,');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (22, 13, 27, 'koji si mi noge u klade sapeo i koji bdiš nad svakim mojim korakom i tragove stopa mojih ispituješ!');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (22, 13, 28, 'Život mi se k\'o trulo drvo raspada, k\'o haljina što je moljci izjedaju!');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (22, 14, 1, 'Čovjek koga je žena rodila kratka je vijeka i pun nevolja.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (22, 14, 2, 'K\'o cvijet je nikao i vene već, poput sjene bježi ne zastajuć\'.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (22, 14, 3, 'Na takva, zar, ti oči otvaraš i preda se na sud ga izvodiš?');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (22, 14, 4, 'Tko će čisto izvuć\' iz nečista? Nitko!');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (22, 14, 5, 'Pa kad su njegovi dani odbrojeni, kad mu broj mjeseci o tebi ovisi, kad mu granicu stavljaš neprijelaznu,');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (22, 14, 6, 'skini s njega pogled da počinut\' može, poput najamnika da svoj dan uživa.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (22, 14, 7, 'TÓa ni drvu nije nada sva propala, posječeno, ono opet prozeleni i mladice nove iz njega izbiju.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (22, 14, 8, 'Ako mu korijen i ostari u zemlji, ako mu se panj i sasuši u prahu,');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (22, 14, 9, 'oćutjevši vodu, ono će propupat\' i pustiti grane kao stablo novo.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (22, 14, 10, 'Al\' kad čovjek umre, ostaje pokošen, kad smrtnik izdahne, gdje li je on tada?');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (22, 14, 11, 'Može sva voda iz mora ispariti i presahnut\' rijeke, isušit posvema\',');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (22, 14, 12, 'al\' čovjek kad legne, ne ustaje više, dok nebesa bude, neće se podići, od sna se svojega probuditi neće.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (22, 14, 13, 'O, kad bi me htio skriti u Šeolu, zakloniti me dok srdžba ti ne mine, dÓati mi rok kad ćeš me se spomenuti,');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (22, 14, 14, '- jer, kad umre čovjek, zar uskrsnut\' može? - čekao bih te sve dane vojske svoje dok ne bi došao da mi smjenu dadeš.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (22, 14, 15, 'Zvao bi me, a ja bih se odazvao: zaželio si se djela svojih ruku.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (22, 14, 16, 'A sad nad svakim mojim vrebaš korakom, nijednog mi grijeha nećeš oprostiti,');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (22, 14, 17, 'u vreći si prijestup moj zapečatio i krivicu moju svu si zapisao.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (22, 14, 18, 'Vaj! K\'o što se jednom uruši planina, k\'o što se hridina s mjesta svog odvali,');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (22, 14, 19, 'k\'o što voda kamen s vremenom istroši, a pljusak bujicom zemlju svu sapere, tako uništavaš nadu u čovjeku.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (22, 14, 20, 'Oborio si ga - on ode za svagda, nagrđena lica, otjeran, odbačen.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (22, 14, 21, 'Djecu mu poštuju - o tom ništa ne zna; ako su prezrena - o tom ne razmišlja.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (22, 14, 22, 'On jedino pati zbog svojega tijela, on jedino tuži zbog svojeg života.\"');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (22, 15, 1, 'Elifaz Temanac progovori tad i reče:');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (22, 15, 2, '\"Zar šupljom naukom odgovara mudrac i vjetrom istočnim trbuh napuhuje?');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (22, 15, 3, 'Zar on sebe brani riječima ispraznim, besjedama koje ničem ne koriste?');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (22, 15, 4, 'Još više ti činiš: ništiš strah od Boga, pred njegovim licem pribranost ukidaš.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (22, 15, 5, 'Tvoje riječi krivicu tvoju odaju, poslužio si se jezikom lukavih,');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (22, 15, 6, 'vlastita te usta osuđuju, ne ja, protiv tebe same ti usne svjedoče.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (22, 15, 7, 'Zar si prvi čovjek koji se rodio? Zar si na svijet prije bregova došao?');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (22, 15, 8, 'Zar si tajne Božje ti prisluškivao i mudrost čitavu za se prisvojio?');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (22, 15, 9, 'Što ti znadeš, a da i mi ne znamo, što ti razumiješ, a da to ne shvaćamo?');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (22, 15, 10, 'Ima među nama i sijedih i starih kojima je više ljeta no tvom ocu.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (22, 15, 11, 'Zar su ti utjehe Božje premalene i blage riječi upućene tebi?');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (22, 15, 12, 'Što te srce tvoje tako slijepo goni i što tako divlje prevrćeš očima');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (22, 15, 13, 'kad proti Bogu jarost svoju okrećeš, a iz usta takve riječi ti izlaze!');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (22, 15, 14, 'Što je čovjek da bi čist mogao biti? Zar je itko rođen od žene pravedan?');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (22, 15, 15, 'Gle, ni u svece se On ne pouzdava, oku njegovu ni nebesa čista nisu,');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (22, 15, 16, 'a kamoli to biće gadno i buntovno, čovjek što k\'o vodu pije opačinu!');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (22, 15, 17, 'Mene sad poslušaj, poučit\' te hoću, što god sam vidjeh, ispričat\' ti želim,');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (22, 15, 18, 'i ono što naučavahu mudraci ne tajeć\' što su primili od pređa');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (22, 15, 19, 'kojima je zemlja ova bila dana kamo tuđin nije nikada stupio.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (22, 15, 20, 'Zlikovac se muči cijelog svoga vijeka, nasilniku već su ljeta odbrojena.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (22, 15, 21, 'Krik strave svagda mu u ušima ječi, dok miruje, na njeg baca se razbojnik.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (22, 15, 22, 'Ne nada se da će izbjeći tminama i znade dobro da je maču namijenjen,');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (22, 15, 23, 'strvinaru da je kao plijen obećan. On znade da mu se dan propasti bliži.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (22, 15, 24, 'Nemir i tjeskoba na njeg navaljuju, k\'o kralj spreman na boj na nj se obaraju.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (22, 15, 25, 'On je protiv Boga podizao ruku, usuđivao se prkosit\' Svesilnom');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (22, 15, 26, 'Ohola je čela na njega srljao, iza štita debela dobro zaklonjen.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (22, 15, 27, 'Lice mu bijaše obloženo salom a bokovi pretilinom otežali.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (22, 15, 28, 'Razrušene je zaposjeo gradove i kućišta nastanio napuštena. Srušit će se ono što za sebe sazda;');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (22, 15, 29, 'cvasti mu neće, već rasuti se blago, sjena mu se neće po zemlji širiti.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (22, 15, 30, 'On se tami više izmaknuti neće, opržit će oganj njegove mladice, u dahu plamenih usta nestat će ga.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (22, 15, 31, 'U taštinu svoju neka se ne uzda, jer će mu ispraznost biti svom nagradom.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (22, 15, 32, 'Prije vremena će svenut\' mu mladice, grane mu se nikad neće zazelenjet\'.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (22, 15, 33, 'Kao loza, grozd će stresat\' svoj nezreo, poput masline pobacit će cvatove.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (22, 15, 34, 'Da, bezbožničko je jalovo koljeno, i vatra proždire šator podmitljivca.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (22, 15, 35, 'Koji zlom zanesu, rađaju nesreću i prijevaru nose u utrobi svojoj.\"');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (22, 16, 1, 'Job progovori i reče:');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (22, 16, 2, '\"Koliko se takvih naslušah besjeda, kako ste mi svi vi mučni tješioci!');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (22, 16, 3, 'Ima li kraja tim riječima ispraznim? Što te goni da mi tako odgovaraš?');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (22, 16, 4, 'I ja bih mogao k\'o vi govoriti da vam je duša na mjestu duše moje; i ja bih vas mog\'o zasuti riječima i nad sudbom vašom tako kimat\' glavom;');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (22, 16, 5, 'i ja bih mogao ustima vas hrabrit\', i ne bih žalio trud svojih usana.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (22, 16, 6, 'Al\' ako govorim, patnja se ne blaži, ako li zašutim, zar će me minuti?');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (22, 16, 7, 'Zlopakost me sada shrvala posvema, čitava se rulja oborila na me.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (22, 16, 8, 'Ustao je proti meni da svjedoči i u lice mi se baca klevetama.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (22, 16, 9, 'Jarošću me svojom razdire i goni, škrgućuć\' zubima obara se na me. Moji protivnici sijeku me očima,');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (22, 16, 10, 'prijeteći, na mene usta razvaljuju, po obrazima me sramotno ćuškaju, u čoporu svi tad navaljuju na me.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (22, 16, 11, 'Da, zloćudnicima Bog me predao, u ruke opakih on me izručio.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (22, 16, 12, 'Mirno življah dok On ne zadrma mnome, za šiju me ščepa da bi me slomio.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (22, 16, 13, 'Uze me za biljeg i strijelama osu, nemilosrdno mi bubrege probode i mojom žuči zemlju žednu natopi.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (22, 16, 14, 'Na tijelu mi ranu do rane otvara, kao bijesan ratnik nasrće na mene.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (22, 16, 15, 'Tijelo sam golo u kostrijet zašio, zario sam čelo svoje u prašinu.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (22, 16, 16, 'Zapalilo mi se sve lice od suza, sjena tamna preko vjeđa mi je pala.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (22, 16, 17, 'A nema nasilja na rukama mojim, molitva je moja bila uvijek čista.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (22, 16, 18, 'O zemljo, krvi moje nemoj sakriti i kriku mom ne daj nigdje da počine.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (22, 16, 19, 'Odsad na nebu imam ja svjedoka, u visini gore moj stoji branitelj.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (22, 16, 20, 'Moja vika moj je odvjetnik kod Boga dok se ispred njega suze moje liju:');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (22, 16, 21, 'o, da me obrani u parbi mojoj s Bogom ko što smrtnik brani svojega bližnjega.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (22, 16, 22, 'No životu mom su odbrojena ljeta, na put bez povratka meni je krenuti.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (22, 17, 1, 'Daha mi nestaje, gasnu moji dani i za mene već se skupljaju grobari.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (22, 17, 2, 'Rugači su evo mene dohvatili, od uvreda oka sklopiti ne mogu.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (22, 17, 3, 'Stoga me zaštiti i budi mi jamcem kad mi nitko u dlan neće da udari.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (22, 17, 4, 'Jer, srca si njina lišio razuma i dopustiti im nećeš da opstanu.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (22, 17, 5, 'K\'o taj što imanje dijeli drugovima, a djeci njegovoj dotle oči gasnu,');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (22, 17, 6, 'narodima svim sam na ruglo postao, onaj kom u lice svatko pljunut\' može.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (22, 17, 7, 'Od tuge vid mi se muti u očima, poput sjene moji udovi postaju.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (22, 17, 8, 'Začudit će se zbog toga pravednici, na bezbožnika će planuti čestiti;');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (22, 17, 9, 'neporočni će na svom ustrajat\' putu, čovjek čistih ruku ojačat će još više.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (22, 17, 10, 'Hajde, svi vi, nećete li opet počet\', tÓa među vama ja mudra ne nalazim!');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (22, 17, 11, 'Minuli su dani, propale zamisli, želje srca moga izjalovile se.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (22, 17, 12, '\'U noći najcrnjoj, dan se približava; blizu je već svjetlo što tminu izgoni.\'');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (22, 17, 13, 'A meni je nada otići u Šeol i prostrijeti sebi ležaj u mrklini.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (22, 17, 14, 'Dovikujem grobu: \'Oče moj rođeni!\' a crve pozdravljam: \'Mati moja, sestro!\'');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (22, 17, 15, 'Ali gdje za mene ima jošte nade? Sreću moju tko će ikada vidjeti?');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (22, 17, 16, 'Hoće li u Šeol ona sa mnom sići da u prahu zajedno otpočinemo?\"');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (22, 18, 1, 'Bildad iz Šuaha progovori tad i reče:');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (22, 18, 2, '\"Kada kaniš obuzdat\' svoje besjede? Opameti se sad da razgovaramo!');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (22, 18, 3, 'Zašto nas držiš za stoku nerazumnu, zar smo životinje u tvojim očima?');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (22, 18, 4, 'O ti, koji se od jarosti razdireš, hoćeš li da zemlja zbog tebe opusti da iz svoga mjesta iskoče pećine?');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (22, 18, 5, 'Al\' ugasit će se svjetlost opakoga, i neće mu sjati plamen na ognjištu.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (22, 18, 6, 'Potamnjet će svjetlo u njegovu šatoru i nad njime će se utrnut\' svjetiljka.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (22, 18, 7, 'Krepki mu koraci postaju sputani, o vlastite on se spotiče namjere.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (22, 18, 8, 'Jer njegove noge vode ga u zamku, i evo ga gdje već korača po mreži.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (22, 18, 9, 'Tanka mu je zamka nogu uhvatila, i evo, užeta čvrsto ga pritežu.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (22, 18, 10, 'Njega vreba omča skrivena na zemlji, njega čeka klopka putem kojim hodi.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (22, 18, 11, 'Odasvuda strahovi ga prepadaju, ustopice sveudilj ga proganjaju.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (22, 18, 12, 'Glad je požderala svu snagu njegovu, nesreća je uvijek o njegovu boku.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (22, 18, 13, 'Boleština kobna kožu mu razjeda, prvenac mu smrti nagriza udove.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (22, 18, 14, 'Njega izvlače iz šatora njegova da bi ga odveli vladaru strahota.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (22, 18, 15, 'U njegovu stanu tuđinac stanuje, po njegovu domu prosipaju sumpor.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (22, 18, 16, 'Odozdo se suši njegovo korijenje, a odozgo grane sve mu redom sahnu.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (22, 18, 17, 'Spomen će se njegov zatrti na zemlji, njegovo se ime s lica zemlje briše.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (22, 18, 18, 'Iz svjetlosti njega u tminu tjeraju, izagnat\' ga hoće iz kruga zemaljskog.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (22, 18, 19, 'U rodu mu nema roda ni poroda, nit\' preživjela na njegovu ognjištu.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (22, 18, 20, 'Sudba je njegova Zapad osupnula, i čitav je Istok obuzela strepnja.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (22, 18, 21, 'Evo, takav usud snalazi zlikovca i dom onog koji ne priznaje Boga.\"');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (22, 19, 1, 'Job progovori i reče:');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (22, 19, 2, '\"TÓa dokle ćete mučit\' dušu moju, dokle ćete me riječima satirat\'?');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (22, 19, 3, 'Već deseti put pogrdiste mene i stid vas nije što me zlostavljate.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (22, 19, 4, 'Pa ako sam zastranio doista, na meni moja zabluda ostaje.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (22, 19, 5, 'Mislite li da ste me nadjačali i krivnju moju da ste dokazali?');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (22, 19, 6, 'Znajte: Bog je to mene pritisnuo i svojom me je on stegnuo mrežom.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (22, 19, 7, 'Vičem: \'Nasilje!\' - nema odgovora; vapijem - ali za me pravde nema.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (22, 19, 8, 'Sa svih strana put mi je zagradio, sve staze moje u tminu zavio.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (22, 19, 9, 'Slavu je moju sa mene skinuo, sa moje glave strgnuo je krunu.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (22, 19, 10, 'Podsijeca me odasvud te nestajem; k\'o drvo, nadu mi je iščupao.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (22, 19, 11, 'Raspalio se gnjev njegov na mene i svojim me drži neprijateljem.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (22, 19, 12, 'U bojnom redu pristižu mu čete, putove proti meni nasipaju, odasvud moj opkoljavaju šator.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (22, 19, 13, 'Od mene su se udaljila braća, otuđili se moji poznanici.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (22, 19, 14, 'Nestade bližnjih mojih i znanaca, gosti doma mog zaboraviše me.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (22, 19, 15, 'Sluškinjama sam svojim kao stranac, neznanac sam u njihovim očima.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (22, 19, 16, 'Slugu zovnem, a on ne odgovara i za milost ga moram zaklinjati.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (22, 19, 17, 'Mojoj je ženi dah moj omrznuo, gadim se djeci vlastite utrobe.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (22, 19, 18, 'I deranima na prezir tek služim, ako se dignem, rugaju se meni.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (22, 19, 19, 'Pouzdanicima sam svojim mrzak, protiv mene su oni koje ljubljah.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (22, 19, 20, 'Kosti mi se za kožu prilijepiše, osta mi jedva koža oko zuba.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (22, 19, 21, 'Smilujte mi se, prijatelji moji, jer Božja me je ruka udarila.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (22, 19, 22, 'Zašto da me k\'o Bog sam progonite, zar se niste moga nasitili mesa?');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (22, 19, 23, 'O, kad bi se riječi moje zapisale i kad bi se u mjed tvrdu urezale;');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (22, 19, 24, 'kad bi se željeznim dlijetom i olovom u spomen vječan u stijenu uklesale!');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (22, 19, 25, 'Ja znadem dobro: moj Izbavitelj živi i posljednji će on nad zemljom ustati.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (22, 19, 26, 'A kad se probudim, k sebi će me dići: iz svoje ću puti tad vidjeti Boga.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (22, 19, 27, 'Njega ja ću kao svojega gledati, i očima mojim neće biti stranac: za njime srce mi čezne u grudima.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (22, 19, 28, 'Kad kažete: \'Kako ćemo ga goniti? Koji ćemo razlog protiv njega naći?\',');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (22, 19, 29, 'mača tad se bojte: grijehu mač je kazna. Saznat ćete tada da imade suda!\"');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (22, 20, 1, 'Sofar iz Naamata progovori tad i reče:');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (22, 20, 2, '\"Misli me tjeraju da ti odgovorim, i zato u meni vri to uzbuđenje');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (22, 20, 3, 'dok slušam ukore koji me sramote, al\' odgovor mudar um će moj već naći.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (22, 20, 4, 'Zar tebi nije od davnine poznato, otkad je čovjek na zemlju stavljen bio,');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (22, 20, 5, 'da je kratka vijeka radost opakoga, da kao tren prođe sreća bezbožnička.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (22, 20, 6, 'Pa ako stasom i do neba naraste, ako mu se glava dotakne oblaka,');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (22, 20, 7, 'poput utvare on zauvijek nestaje; koji ga vidješe kažu: \'Gdje je sad on?\'');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (22, 20, 8, 'Kao san bez traga on se rasplinjuje, nestaje ga kao priviđenja noćnog.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (22, 20, 9, 'Nijedno ga oko više gledat neće, niti će ga mjesto njegovo vidjeti');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (22, 20, 10, 'Njegovu će djecu gonit\' siromasi: rukama će svojim vraćati oteto.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (22, 20, 11, 'Kosti su njegove bujale mladošću; gle, zajedno s njome pokošen je sada.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (22, 20, 12, 'Zlo bijaše slatko njegovim ustima te ga je pod svojim jezikom skrivao;');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (22, 20, 13, 'sladio se pazeć\' da ga ne proguta i pod nepcem svojim zadržavao ga.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (22, 20, 14, 'Ali hrana ta mu trune u utrobi, otrovom zmijskim u crijevima postaje.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (22, 20, 15, 'Blago progutano mora izbljuvati. Bog će ga istjerat\' njemu iz utrobe.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (22, 20, 16, 'Iz zmijine glave otrov je sisao: sada umire od jezika gujina.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (22, 20, 17, 'Potoke ulja on gledat\' više neće, ni vidjet\' gdje rijekom med i mlijeko teku.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (22, 20, 18, 'Vratit će dobitak ne okusivši ga, neće uživat\' u plodu trgovine.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (22, 20, 19, 'Jer je sirotinju gnjeo i tlačio, otimao kuće koje ne sazida,');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (22, 20, 20, 'jer ne bješe kraja požudi njegovoj, njegova ga blaga neće izbaviti.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (22, 20, 21, 'Jer mu proždrljivost ništa ne poštedi, ni sreća njegova dugo trajat neće.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (22, 20, 22, 'Sred izobilja u škripcu će se naći, svom će snagom na nj se oboriti bijeda.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (22, 20, 23, 'I dok hranom bude trbuh svoj punio, Bog će na nj pustiti jarost svoga gnjeva, sasut\' dažd strelica na meso njegovo.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (22, 20, 24, 'Ako i izmakne gvozdenom oružju, luk će mjedeni njega prostrijeliti.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (22, 20, 25, 'Strijelu bi izvuk\'o, al\' mu probi leđa, a šiljak blistavi viri mu iz žuči. Kamo god krenuo, strepnje ga vrebaju,');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (22, 20, 26, 'na njega tmine sve tajom očekuju. Vatra ga ništi, ni od kog zapaljena, i proždire sve pod njegovim šatorom.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (22, 20, 27, 'Gle, nebo krivicu njegovu otkriva i čitava zemlja na njega se diže.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (22, 20, 28, 'Njegovu će kuću raznijeti poplava, otplaviti je u dan Božje jarosti.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (22, 20, 29, 'Takvu sudbinu Bog priprema zlikovcu i takvu baštinu on mu dosuđuje.\"');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (22, 21, 1, 'Job progovori i reče:');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (22, 21, 2, '\"Slušajte, slušajte dobro što ću reći, utjehu mi takvu barem udijelite.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (22, 21, 3, 'Otrpite da riječ jednu ja izrečem, kad završim, tad se rugajte slobodno.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (22, 21, 4, 'Zar protiv čovjeka dižem ja optužbu? Kako da strpljenje onda ne izgubim?');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (22, 21, 5, 'Pogledajte na me: užas će vas spopast\', rukom ćete svoja zakloniti usta;');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (22, 21, 6, 'pomislim li na to, prestravim se i sam i čitavim svojim tad protrnem tijelom.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (22, 21, 7, 'Zašto na životu ostaju zlikovci i, što su stariji, moćniji bivaju?');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (22, 21, 8, 'Potomstvo njihovo s njima napreduje a izdanci im se množe pred očima.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (22, 21, 9, 'Strah nikakav kuće njihove ne mori i šiba ih Božja ostavlja na miru.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (22, 21, 10, 'Njihovi bikovi plode pouzdano, krave im se tele i ne jalove se.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (22, 21, 11, 'K\'o jagnjad djeca im slobodno skakuću, veselo igraju njihovi sinovi.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (22, 21, 12, 'Oni pjevaju uz harfe i bubnjeve i vesele se uz zvukove svirale.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (22, 21, 13, 'Dane svoje završavaju u sreći, u Podzemlje oni silaze spokojno.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (22, 21, 14, 'A govorili su Bogu: \'Ostavi nas, ne želimo znati za tvoje putove!');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (22, 21, 15, 'TÓa tko je Svesilni da njemu služimo i kakva nam korist da ga zazivamo?\'');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (22, 21, 16, 'Zar svoju sreću u ruci ne imahu, makar do Njega ne drže ništa oni?');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (22, 21, 17, 'Zar se luč opakog kada ugasila? Zar se na njega oborila nesreća? Zar mu u gnjevu svom On skroji sudbinu?');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (22, 21, 18, 'Zar je kao slama na vjetru postao, kao pljeva koju vihor svud raznosi?');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (22, 21, 19, 'Hoće l\' ga kaznit\' Bog u njegovoj djeci? Ne, njega nek\' kazni da sam to osjeti!');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (22, 21, 20, 'Vlastitim očima nek\' rasap svoj vidi, neka se napije srdžbe Svesilnoga!');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (22, 21, 21, 'TÓa što poslije smrti on za dom svoj mari kad će se presjeć\' niz njegovih mjeseci?');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (22, 21, 22, 'Ali tko će Boga učiti mudrosti, njega koji sudi najvišim bićima?');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (22, 21, 23, 'Jedan umire u punom blagostanju, bez briga ikakvih, u potpunom miru,');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (22, 21, 24, 'bokova od pretiline otežalih i kostiju sočne moždine prepunih.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (22, 21, 25, 'A drugi umire s gorčinom u duši, nikad nikakve ne okusivši sreće.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (22, 21, 26, 'Obojica leže zajedno u prahu, crvi ih jednako prekrivaju oba.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (22, 21, 27, 'O, znam dobro kakve vaše su namjere, kakve zlosti protiv mene vi snujete.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (22, 21, 28, 'Jer pitate: \'Gdje je kuća plemićeva, šator u kojem stanovahu opaki?\'');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (22, 21, 29, 'Niste li na cesti putnike pitali, zar njihovo svjedočanstvo ne primate:');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (22, 21, 30, '\'Opaki je u dan nesreće pošteđen i u dan Božje jarosti veseo je.\'');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (22, 21, 31, 'Al\' na postupcima tko će mu predbacit\' i tko će mu vratit\' što je počinio?');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (22, 21, 32, 'A kad ga na kraju na groblje odnesu, na grobni mu humak postavljaju stražu.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (22, 21, 33, 'Lake su mu grude zemlje u dolini dok za njime ide čitavo pučanstvo.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (22, 21, 34, 'O, kako su vaše utjehe isprazne! Kakva su prijevara vaši odgovori!\"');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (22, 22, 1, 'Elifaz Temanac progovori tad i reče:');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (22, 22, 2, '\"Zar Bogu koristan može biti čovjek? TÓa tko je mudar, sebi samom koristi.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (22, 22, 3, 'Zar je Svesilnom milost što si pravedan i zar mu je dobit što si neporočan?');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (22, 22, 4, 'Ili te zbog tvoje pobožnosti kara i zato se hoće s tobom parničiti?');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (22, 22, 5, 'Nije l\' to zbog zloće tvoje prevelike i zbog bezakonja kojim broja nema?');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (22, 22, 6, 'Od braće si brao nizašto zaloge i s golih si ljudi svlačio haljine;');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (22, 22, 7, 'ti nisi žednoga vodom napojio, uskraćivao si kruh izgladnjelima;');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (22, 22, 8, 'otimao si od siromaha zemlju da bi na njoj svog nastanio ljubimca;');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (22, 22, 9, 'puštao si praznih ruku udovice i siročadi si satirao ruku.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (22, 22, 10, 'Eto zašto tebe mreže sad sapinju, zašto te strahovi muče iznenadni.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (22, 22, 11, 'Svjetlost ti mrak posta i ništa ne vidiš, vode su duboke tebe potopile.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (22, 22, 12, 'Zar Bog nije u visini nebeskoj i zar zvijezdama tjeme on ne vidi?');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (22, 22, 13, 'Ali ti kažeš: \'Što Bog može znati? Kroz oblak tmasti zar što razabire?');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (22, 22, 14, 'Oblaci pogled njegov zaklanjaju, i rubom kruga on hoda nebeskog.\'');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (22, 22, 15, 'TÓa kaniš li se drevnog držat\' puta kojim su išli ljudi nepravedni?');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (22, 22, 16, 'Prije vremena nestadoše oni, bujica im je temelje raznijela.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (22, 22, 17, 'Zborahu Bogu: \'Nas se ti ostavi! Što nam Svesilni učiniti može?\'');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (22, 22, 18, 'A on im je dom punio dobrima makar do njega ne držahu ništa.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (22, 22, 19, 'Videć\' im propast, klikću pravednici, neporočni se njima izruguju:');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (22, 22, 20, '\'Gle, propadoše protivnici naši, što od njih osta, vatra im proždrije!\"');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (22, 22, 21, 'S Bogom ti se sprijatelji i pomiri, i vraćena će ti opet biti sreća.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (22, 22, 22, 'Ded prihvati Zakon iz njegovih usta, u srce svoje riječ njegovu usadi.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (22, 22, 23, 'Ako se raskajan vratiš Svesilnome i nepravdu iz svog šatora odstraniš,');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (22, 22, 24, 'tad ćeš odbaciti zlato u prašinu i ofirsko blago u šljunak potočni.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (22, 22, 25, 'Svesilni će postat\' tvoje suho zlato, on će biti tvoje gomile srebrene.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (22, 22, 26, 'Da, Svesilni bit će tvoje radovanje, i lice ćeš k Bogu dizati slobodno.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (22, 22, 27, 'Molit ćeš mu se, i uslišat će tebe, ispunit ćeš što si mu zavjetovao.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (22, 22, 28, 'Što god poduzeo, sve će ti uspjeti, i putove će ti obasjavat\' svjetlost.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (22, 22, 29, 'Jer, on ponizuje ponos oholima, dok u pomoć smjernim očima pritječe.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (22, 22, 30, 'Iz nevolje on izbavlja nevinoga; i tebe će spasit\' tvoje čiste ruke.\"');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (22, 23, 1, 'Job progovori i reče:');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (22, 23, 2, '\"Zar mi je i danas tužaljka buntovna? Teška mu ruka iz mene vapaj budi:');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (22, 23, 3, 'o, kada bih znao kako ću ga naći, do njegova kako doprijeti prijestolja,');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (22, 23, 4, 'pred njim parnicu bih svoju razložio, iz mojih bi usta navrli dokazi.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (22, 23, 5, 'Rad bih znati što bi meni odvratio i razumjeti riječ što bi je rekao!');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (22, 23, 6, 'Zar mu treba snage velike za raspru? Ne, dosta bi bilo da me on sasluša.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (22, 23, 7, 'U protivniku bi vidio pravedna, i parnica moja tad bi pobijedila.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (22, 23, 8, 'Na istok krenem li, naći ga ne mogu; pođem li na zapad, ne razabirem ga.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (22, 23, 9, 'Ištem na sjeveru, al\' ga ne opažam; nevidljiv je ako se k jugu okrenem.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (22, 23, 10, 'Pa ipak, on dobro zna put kojim kročim! Neka me kuša: čist k\'o zlato ću izići!');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (22, 23, 11, 'Noga mi se stopa njegovih držala, putem sam njegovim išao ne skrećuć\';');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (22, 23, 12, 'slušao sam nalog njegovih usana, pohranih mu riječi u grudima svojim.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (22, 23, 13, 'Al\' htjedne li štogod, tko će ga odvratit\'? Što zaželi dušom, to će ispuniti.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (22, 23, 14, 'Izvršit će što je dosudio meni, kao i sve drugo što je odlučio!');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (22, 23, 15, 'Zbog toga pred njime sav ustravljen ja sam, i što više mislim, jače strah me hvata.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (22, 23, 16, 'U komade Bog mi je srce smrvio, užasom me svega prožeo Svesilni,');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (22, 23, 17, 'premda nisam ni u tminama propao, ni u mraku što je lice moje zastro.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (22, 24, 1, 'Zašto Svesilni ne promatra vremena, a dane njegove ne vide mu vjernici?');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (22, 24, 2, 'Bezbožnici pomiču granice, otimaju stado i pasu ga.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (22, 24, 3, 'Sirotama odvode magarca, udovi u zalog vola dižu.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (22, 24, 4, 'Siromahe tjeraju sa puta; skrivaju se ubogari zemlje.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (22, 24, 5, 'K\'o magarci divlji u pustinji zarana idu da plijen ugrabe: pustinja im hrani mališane.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (22, 24, 6, 'Po tuđem polju oni pabirče, paljetkuju vinograd opakog.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (22, 24, 7, 'Goli noće, nemaju haljine, ni pokrivača protiv studeni.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (22, 24, 8, 'Oni kisnu na planinskom pljusku; bez skloništa uz hrid se zbijaju.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (22, 24, 9, 'Otkidaju od sise sirotu, ubogom u zalog dijete grabe.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (22, 24, 10, 'Goli hode, nemaju haljina; izgladnjeli, tuđe snoplje nose.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (22, 24, 11, 'Oni mlina za ulje nemaju; ožednjeli, gaze u kacama.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (22, 24, 12, 'Samrtnici hropću iz gradova, ranjenici u pomoć zazivlju. Al\' na sve to Bog se oglušuje.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (22, 24, 13, 'Ima onih koji mrze svjetlost: ne priznaju njezinih putova niti se staza drže njezinih.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (22, 24, 14, 'Za mraka se diže ubojica, kolje ubogog i siromaha. U gluhoj se noći lopov skiće [16a] i u tmini provaljuje kuće.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (22, 24, 15, 'Sumrak žudi oko preljubnika: \'Nitko me vidjet neće\', kaže on i zastire velom svoje lice.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (22, 24, 16, '[16b]Za vidjela oni se skrivaju, oni neće da za svjetlost znaju.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (22, 24, 17, 'Zora im je kao sjena smrtna: kad zarudi, silan strah ih hvata.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (22, 24, 18, 'Prije nego svane, on već hitro bježi kloneći se puta preko vinograda. Njegova su dobra prokleta u zemlji.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (22, 24, 19, 'K\'o što vrućina i žega snijeg upija, tako i Podzemlje proždire grešnike.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (22, 24, 20, 'Zaboravilo ga krilo što ga rodi, ime se njegovo više ne spominje: poput stabla zgromljena je opačina.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (22, 24, 21, 'Ženu nerotkinju on je zlostavljao, udovici nije učinio dobra.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (22, 24, 22, 'Al\' Onaj što snažno hvata nasilnike, ustaje, a njima sva se nada gasi.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (22, 24, 23, 'Dade mu sigurnost, i on se pouzda; okom je njegove nadzirao staze.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (22, 24, 24, 'Dignu se za kratko, a onda nestanu, ruše se i kao svi drugi istrunu, posječeni kao glave klasovima.\"');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (22, 24, 25, 'Nije li tako? Tko će me u laž utjerat\'? Tko moje riječi poništiti može?\"');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (22, 25, 1, 'Bildad iz Šuaha progovori tad i reče:');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (22, 25, 2, '\"Gospodstvo i strah u njegovoj su ruci i on stvara mir u svojim visinama.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (22, 25, 3, 'Zar se njemu čete izbrojiti mogu i svjetlo njegovo nad kim ne izlazi?');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (22, 25, 4, 'Pa kako da čovjek prav bude pred Bogom i od žene rođen kako da čist bude?');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (22, 25, 5, 'Eto, i mjesec pred njime sjaj svoj gubi, njegovim očima zvijezde nisu čiste.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (22, 25, 6, 'Što reći onda o čovjeku, tom crvu, o sinu čovjekovu, crviću jadnom?');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (22, 25, 7, '');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (22, 25, 8, '');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (22, 25, 9, '');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (22, 25, 10, '');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (22, 25, 11, '');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (22, 25, 12, '');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (22, 25, 13, '');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (22, 25, 14, '');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (22, 26, 1, 'Job progovori i reče:');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (22, 26, 2, '\"Kako dobro znadeš pomoći nemoćnom i mišicu iznemoglu poduprijeti!');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (22, 26, 3, 'Kako dobar savjet daješ neukome; baš si preveliku mudrost pokazao.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (22, 26, 4, 'Kome li si ove uputio riječi i koji duh je iz tebe govorio?\"');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (22, 26, 5, 'Pred Bogom mrtvi pod zemljom dolje strepe, vode morske dršću i nemani njine.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (22, 26, 6, 'Pred njegovim okom otkriven zja Šeol i bezdan smrti nema vela na sebi.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (22, 26, 7, 'On povrh praznine Sjever razapinje, on drži zemlju o ništa obješenu.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (22, 26, 8, 'On zatvara vodu u svoje oblake, a oblaci se pod njome ne prodiru.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (22, 26, 9, 'On zastire puno lice mjesečevo razastirući svoj oblak preko njega.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (22, 26, 10, 'On je na vodi označio kružnicu gdje prestaje svjetlost i tmine počinju.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (22, 26, 11, 'Svodu se nebeskom potresu stupovi i premru od straha kada on zaprijeti.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (22, 26, 12, 'Svojom je snagom on ukrotio more i neman Rahaba smrvio mudrošću.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (22, 26, 13, 'Nebesa je svojim razbistrio dahom, a ruka mu je brzu zmiju probola.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (22, 26, 14, 'Sve to samo djelić je djela njegovih, od kojih tek slabu jeku mi čujemo. Ali tko će shvatit\' grom njegove moći?\"');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (22, 27, 1, 'Job nastavi svoju besjedu i reče:');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (22, 27, 2, '\"Živoga mi Boga što mi pravdu krati i Svesilnog koji dušu mi zagorča:');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (22, 27, 3, 'sve dok duha moga bude još u meni, dok mi dah Božji u nosnicama bude,');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (22, 27, 4, 'usne moje neće izustiti zloću niti će laž kakva doći na moj jezik.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (22, 27, 5, 'Daleko od mene da vam dadem pravo, nedužnost svoju do zadnjeg daha branim.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (22, 27, 6, 'Pravde svoje ja se držim, ne puštam je; zbog mojih me dana srce korit\' neće.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (22, 27, 7, 'Neka mi dušmana kob opakog snađe, a mog protivnika udes bezbožnikov!');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (22, 27, 8, 'Čemu se nadati može kad vapije i kada uzdiže k Bogu dušu svoju?');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (22, 27, 9, 'Hoće li čuti Bog njegove krikove kada se na njega obori nevolja?');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (22, 27, 10, 'Zar će se radovat\' on u Svesilnome, zar će Boga svakog časa zazivati?');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (22, 27, 11, 'Ali Božju ruku ja ću vam pokazat\' i neću vam sakrit namjere Svesilnog.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (22, 27, 12, 'Eto, sve ste sami mogli to vidjeti, što se onda u ispraznosti gubite?\"');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (22, 27, 13, '\"Ovu sudbu Bog dosuđuje opakom, ovo baštini silnik od Svemogućeg.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (22, 27, 14, 'Ima li sinova mnogo, mač ih čeka, a porod mu neće imat\' dosta kruha.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (22, 27, 15, 'Smrt će sahranit\' preživjele njegove i udovice ih oplakivat neće.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (22, 27, 16, 'Ako i srebra k\'o praha nagomila, ako i nakupi haljina k\'o blata,');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (22, 27, 17, 'nek\' ih skuplja, odjenut će ih pravednik, ljudi će nedužni podijeliti srebro.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (22, 27, 18, 'Od paučine je kuću sagradio, kolibicu kakvu sebi diže čuvar:');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (22, 27, 19, 'bogat je legao, al\' po posljednji put; kad oči otvori, ničeg više nema.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (22, 27, 20, 'Usred bijela dana strava ga spopada, noću ga oluja zgrabi i odnese.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (22, 27, 21, 'Istočni ga vjetar digne i odvuče, daleko ga baca od njegova mjesta.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (22, 27, 22, 'Bez milosti njime vitla on posvuda, dok mu ovaj kuša umaći iz ruke.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (22, 27, 23, 'Rukama plješću nad njegovom propašću i zvižde na njega kamo god došao.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (22, 27, 24, '');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (22, 28, 1, '\"Da, srebro ima svoja nalazišta, a zlato mjesta gdje se pročišćava.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (22, 28, 2, 'Ruda željezna iz zemlje se vadi, a iz rudače rastaljene bakar.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (22, 28, 3, 'Ljudi tami postavljaju granice i kopaju do najvećih dubina za kamenom u mraku zakopanim.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (22, 28, 4, 'Čeljad iz tuđine rovove dube do kojih ljudska ne dopire noga, visi njišuć\' se, daleko od ljudi.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (22, 28, 5, 'Krilo zemlje iz kojeg kruh nam niče kao od vatre sve je razrovano.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (22, 28, 6, 'Stijene njene safira su skrovišta, prašina zlatna krije se u njima.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (22, 28, 7, 'Tih putova ne znaju grabljivice, jastrebovo ih oko ne opaža.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (22, 28, 8, 'Zvijeri divlje njima nisu kročile niti je kada lav njima prošao.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (22, 28, 9, 'Ali na kamen diže čovjek ruku te iz korijena prevraća planine.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (22, 28, 10, 'U kamenu prokopava prolaze, oko mu sve dragocjeno opaža.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (22, 28, 11, 'Žilama vode on tok zaustavlja; stvari skrivene nosi na vidjelo.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (22, 28, 12, 'Ali otkuda nam Mudrost dolazi? Na kojemu mjestu Razum prebiva?');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (22, 28, 13, 'Čovjek njezina ne poznaje puta, u zemlji živih nisu je otkrili.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (22, 28, 14, 'Bezdan govori: \'U meni je nema!\' a more: \'Ne nalazi se kod mene!\'');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (22, 28, 15, 'Zlatom se čistim kupiti ne može, ni cijenu njenu srebrom odmjeriti;');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (22, 28, 16, 'ne mjeri se ona zlatom ofirskim, ni oniksom skupim pa ni safirom.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (22, 28, 17, 'Sa zlatom, staklom ne poređuje se, nit\' se daje za sud od suha zlata.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (22, 28, 18, 'Čemu spominjat\' prozirac, koralje, bolje je steći Mudrost no biserje.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (22, 28, 19, 'Što je prema njoj topaz etiopski? Ni čistim zlatom ne procjenjuje se.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (22, 28, 20, 'Ali otkuda nam Mudrost dolazi? Na kojemu mjestu Razum prebiva?');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (22, 28, 21, 'Sakrivena je očima svih živih; ona izmiče pticama nebeskim.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (22, 28, 22, 'Propast paklena i Smrt izjavljuju: \'Za slavu njenu mi smo samo čuli.\'');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (22, 28, 23, 'Jedino je Bog put njen proniknuo, on jedini znade gdje se nalazi.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (22, 28, 24, 'Jer pogledom granice zemlje hvata i opaža sve pod svodom nebeskim.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (22, 28, 25, 'Kad htjede vjetru odredit težinu i mjerilom svu vodu izmjeriti,');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (22, 28, 26, 'kad je zakone daždu nametnuo i oblacima gromovnim putove,');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (22, 28, 27, 'tad ju je vidio te izmjerio, učvrstio i do dna ispitao.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (22, 28, 28, 'A potom je rekao čovjeku: Strah Gospodnji - eto što je mudrost; \'Zla se kloni\' - to ti je razumnost.\"');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (22, 29, 1, 'Job nastavi svoju besjedu i reče:');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (22, 29, 2, '\"O, da mi je prošle proživjet\' mjesece, dane one kad je Bog nada mnom bdio,');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (22, 29, 3, 'kad mi je nad glavom njegov sjao žižak a kroz mrak me svjetlo njegovo vodilo,');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (22, 29, 4, 'kao u dane mojih zrelih jeseni kad s mojim stanom Bog prijateljevaše,');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (22, 29, 5, 'kada uz mene još bijaše Svesilni i moji me okruživahu dječaci,');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (22, 29, 6, 'kada mi se noge u mlijeku kupahu, a potokom ulja ključaše mi kamen!');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (22, 29, 7, 'Kada sam na vrata gradska izlazio i svoju stolicu postavljao na trg,');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (22, 29, 8, 'vidjevši me, sklanjali bi se mladići, starci bi ustavši stojeći ostali.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (22, 29, 9, 'Razgovor bi prekidali uglednici i usta bi svoja rukom zatvarali.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (22, 29, 10, 'Glavarima glas bi sasvim utihnuo, za nepce bi im se zalijepio jezik.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (22, 29, 11, 'Tko god me slušao, blaženim me zvao, hvalilo me oko kad bi me vidjelo.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (22, 29, 12, 'Jer, izbavljah bijednog kada je kukao i sirotu ostavljenu bez pomoći.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (22, 29, 13, 'Na meni bješe blagoslov izgubljenih, srcu udovice ja veselje vraćah.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (22, 29, 14, 'Pravdom se ja kao haljinom odjenuh, nepristranost bje mi plaštem i povezom.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (22, 29, 15, 'Bjeh oči slijepcu i bjeh noge bogalju,');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (22, 29, 16, 'otac ubogima, zastupnik strancima.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (22, 29, 17, 'Kršio sam zube čovjeku opaku, plijen sam čupao iz njegovih čeljusti.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (22, 29, 18, 'Govorah: \'U svom ću izdahnuti gnijezdu, k\'o palma, bezbrojne proživjevši dane.\'');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (22, 29, 19, 'Korijenje se moje sve do vode pruža, na granama mojim odmara se rosa.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (22, 29, 20, 'Pomlađivat će se svagda slava moja i luk će mi se obnavljati u ruci.\'');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (22, 29, 21, 'Slušali su željno što ću im kazati i šutjeli da od mene savjet čuju.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (22, 29, 22, 'Na riječi mi ne bi ništa dometali i besjede su mi daždile po njima.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (22, 29, 23, 'Za mnom žudjeli su oni k\'o za kišom, otvarali usta k\'o za pljuskom ljetnim.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (22, 29, 24, 'Osmijeh moj bijaše njima ohrabrenje; pazili su na vedrinu moga lica.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (22, 29, 25, 'Njima ja sam izabirao putove, kao poglavar ja sam ih predvodio, kao kralj među svojim kad je četama kao onaj koji tješi ojađene.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (22, 30, 1, '\"A sada, gle, podruguju se mnome ljudi po ljetima mlađi od mene kojih oce ne bih bio metnuo ni s ovčarskim psima stada svojega.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (22, 30, 2, 'Ta što će mi jakost ruku njihovih kad im muževna ponestane snaga ispijena glađu i oskudicom.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (22, 30, 3, 'Glodali su u pustinji korijenje i čestar opustjelih ruševina.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (22, 30, 4, 'Lobodu su i s grmlja lišće brali, kao kruh jeli korijenje žukino.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (22, 30, 5, 'Od društva ljudskog oni su prognani, za njima viču k\'o za lopovima.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (22, 30, 6, 'Živjeli su po strašnim jarugama, po spiljama i u raspuklinama.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (22, 30, 7, 'Urlik im se iz šikarja dizao; po trnjacima ležahu stisnuti.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (22, 30, 8, 'Sinovi bezvrijednih, soj bezimenih, bičevima su iz zemlje prognani.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (22, 30, 9, 'Rugalicom sam postao takvima i njima sada služim kao priča!');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (22, 30, 10, 'Gnušaju me se i bježe od mene, ne ustežu se pljunut\' mi u lice.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (22, 30, 11, 'I jer On luk mi slomi i satrije me, iz usta svojih izbaciše uzdu.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (22, 30, 12, 'S desne moje strane rulja ustaje, noge moje u bijeg oni tjeraju, put propasti prema meni nasiplju.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (22, 30, 13, 'Stazu mi ruše da bi me satrli, napadaju i ne brani im nitko,');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (22, 30, 14, 'prolomom oni širokim naviru i kotrljaju se poput oluje.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (22, 30, 15, 'Strahote sve se okreću na mene, mojeg ugleda kao vjetra nesta, poput oblaka iščeznu spasenje.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (22, 30, 16, 'Duša se moja rasipa u meni, dani nevolje na me se srušili.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (22, 30, 17, 'Noću probada bolest kosti moje, ne počivaju boli što me glođu.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (22, 30, 18, 'Muka mi je i halju nagrdila i stegla me k\'o ovratnik odjeće.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (22, 30, 19, 'U blato me je oborila dolje, gle, postao sam k\'o prah i pepeo.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (22, 30, 20, 'K Tebi vičem, al\' Ti ne odgovaraš; pred Tobom stojim, al\' Ti i ne mariš.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (22, 30, 21, 'Prema meni postao si okrutan; rukom preteškom na me se obaraš.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (22, 30, 22, 'U vihor me dižeš, nosiš me njime, u vrtlogu me olujnom kovitlaš.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (22, 30, 23, 'Da, znadem da si me smrti predao, saborištu zajedničkom svih živih.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (22, 30, 24, 'Al\' ne pruža li ruku utopljenik, ne viče li kad padne u nevolju?');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (22, 30, 25, 'Ne zaplakah li nad nevoljnicima, ne sažalje mi duša siromaha?');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (22, 30, 26, 'Sreći se nadah, a dođe nesreća; svjetlost čekah, a gle, zavi me tama.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (22, 30, 27, 'Utroba vri u meni bez prestanka, svaki dan nove patnje mi donosi.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (22, 30, 28, 'Smrknut idem, al\' nitko me ne tješi; ustajem u zboru - da bih kriknuo.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (22, 30, 29, 'Sa šakalima sam se zbratimio i nojevima postao sam drugom.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (22, 30, 30, 'Na meni sva je koža pocrnjela, i kosti mi je sažgala ognjica.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (22, 30, 31, 'Tužaljka mi je ugodila harfu, svirala mi glas narikača ima.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (22, 31, 1, 'Sa svojim očima savez sam sklopio da pogledat neću nijednu djevicu.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (22, 31, 2, 'A što mi je Bog odozgo dosudio, kakva mi je baština od Svesilnoga?');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (22, 31, 3, 'TÓa nije li nesreća za opakoga, a nevolja za one koji zlo čine?');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (22, 31, 4, 'Ne proniče li on sve moje putove, ne prebraja li on sve moje korake?');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (22, 31, 5, 'Zar sam ikad u društvu laži hodio, zar mi je noga k prijevari hitjela?');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (22, 31, 6, 'Nek\' me na ispravnoj mjeri Bog izmjeri pa će uvidjeti neporočnost moju!');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (22, 31, 7, 'Ako mi je korak s puta kad zašao, ako mi se srce za okom povelo, ako mi je ljaga ruke okaljala,');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (22, 31, 8, 'neka drugi jede što sam posijao, neka sve moje iskorijene izdanke!');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (22, 31, 9, 'Ako mi zavede srce žena neka, ako za vratima svog bližnjeg kad vrebah,');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (22, 31, 10, 'neka moja žena drugom mlin okreće, neka s drugim svoju podijeli postelju!');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (22, 31, 11, 'Djelo bestidno time bih počinio, zločin kojem pravda treba da presudi,');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (22, 31, 12, 'užego vatru što žeže do Propasti i što bi svu moju sažgala ljetinu.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (22, 31, 13, 'Ako kada prezreh pravo sluge svoga il\' služavke, sa mnom kad su se parbili,');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (22, 31, 14, 'što ću učiniti kada Bog ustane? Što ću odvratit\' kad račun zatraži?');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (22, 31, 15, 'Zar nas oba on ne stvori u utrobi i jednako sazda u krilu majčinu?');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (22, 31, 16, 'Ogluših li se na molbe siromaha ili rasplakah oči udovičine?');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (22, 31, 17, 'Jesam li kada sam svoj jeo zalogaj a da ga nisam sa sirotom dijelio?');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (22, 31, 18, 'TÓa od mladosti k\'o otac sam mu bio, vodio sam ga od krila materina!');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (22, 31, 19, 'Zar sam beskućnika vidio bez odjeće ili siromaha kog bez pokrivača');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (22, 31, 20, 'a da mu bedra ne blagosloviše mene kad se runom mojih ovaca ogrija?');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (22, 31, 21, 'Ako sam ruku na nevina podigao znajuć\' da mi je na vratima branitelj,');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (22, 31, 22, 'nek\' se rame moje od pleća odvali i neka mi ruka od lakta otpadne!');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (22, 31, 23, 'Jer strahote Božje na mene bi pale, njegovu ne bih odolio veličanstvu.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (22, 31, 24, 'Zar sam u zlato pouzdanje stavio i rekao zlatu: \'Sigurnosti moja!\'');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (22, 31, 25, 'Zar sam se veliku blagu radovao, bogatstvima koja su mi stekle ruke?');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (22, 31, 26, 'Zar se, gledajući sunce kako blista i kako mjesec sjajni nebom putuje,');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (22, 31, 27, 'moje srce dalo potajno zavesti da bih rukom njima poljubac poslao?');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (22, 31, 28, 'Grijeh bi to bio što za sudom vapije, jer Boga višnjega bih se odrekao.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (22, 31, 29, 'Zar se obradovah nevolji dušmana i likovah kad ga je zlo zadesilo,');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (22, 31, 30, 'ja koji ne dadoh griješiti jeziku, proklinjući ga i želeći da umre?');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (22, 31, 31, 'Ne govorahu li ljudi mog šatora: \'TÓa koga nije on mesom nasitio\'?');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (22, 31, 32, 'Nikad nije stranac vani noćivao, putniku sam svoja otvarao vrata.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (22, 31, 33, 'Zar sam grijehe svoje ljudima tajio, zar sam u grudima skrivao krivicu');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (22, 31, 34, 'jer sam se plašio govorkanja mnoštva i strahovao od prezira plemenskog te sam mučao ne prelazeć\' svoga praga?');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (22, 31, 35, 'O, kad bi koga bilo da mene sasluša! Posljednju sam svoju riječ ja izrekao: na Svesilnom je sad da mi odgovori! Nek\' mi optužnicu napiše protivnik,');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (22, 31, 36, 'i ja ću je nosit\' na svome ramenu, čelo ću njome k\'o krunom uresit\'.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (22, 31, 37, 'Dat ću mu račun o svojim koracima i poput kneza pred njega ću stupiti.\"');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (22, 31, 38, 'Ako je na me zemlja moja vikala, ako su s njom brazde njezine plakale;');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (22, 31, 39, 'ako sam plodove jeo ne plativši i ako sam joj ojadio ratare,');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (22, 31, 40, '[40a] neka mjesto žita po njoj niče korov, a mjesto ječma nek\' posvud kukolj raste! [40b] Konac riječi Jobovih.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (22, 32, 1, 'Ona tri čovjeka prestadoše Jobu odgovarati, jer je on sebe smatrao nevinim.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (22, 32, 2, 'Nato se rasrdi Elihu, sin Barakeelov, iz Buza, od plemena Ramova: planu gnjevom na Joba zato što je sebe držao pravednim pred Bogom;');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (22, 32, 3, 'a planu gnjevom i na tri njegova prijatelja jer nisu više našli ništa što bi odgovorili te su tako Boga osudili.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (22, 32, 4, 'Dok su oni govorili s Jobom, Elihu je šutio, jer su oni bili stariji od njega.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (22, 32, 5, 'Ali kad vidje da ona tri čovjeka nisu više imala odgovora u ustima, planu od srdžbe.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (22, 32, 6, 'I progovorivši, Elihu, sin Barakeelov, iz Buza, reče: \"Po godinama svojim još mlad sam ja, a u duboku vi ste ušli starost; bojažljivo se zato ja ustezah znanje svoje pokazati pred vama.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (22, 32, 7, 'Mišljah u sebi: \'Govorit će starost, mnoge godine pokazat će mudrost.\'');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (22, 32, 8, 'Uistinu, dah neki u ljudima, duh Svesilnog mudrim čini čovjeka.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (22, 32, 9, 'Dob poodmakla ne daje mudrosti a niti starost pravednosti uči.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (22, 32, 10, 'Zato vas molim, poslušajte mene da vam i ja znanje svoje izložim.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (22, 32, 11, 'S pažnjom sam vaše besjede pratio i razloge sam vaše saslušao dok ste tražili što ćete kazati.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (22, 32, 12, 'Na vama moja sva bijaše pažnja, al\' ne bi nikog da Joba pobije ni da mu od vas tko riječ opovrgne.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (22, 32, 13, 'Nemojte reći: \'Na mudrost smo naišli! Bog će ga pobit jer čovjek ne može.\'');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (22, 32, 14, 'Nije meni on besjedu upravio: odvratit mu neću vašim riječima.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (22, 32, 15, 'Poraženi, otpovrgnut ne mogu, riječi zapeše u grlu njihovu.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (22, 32, 16, 'Čekao sam! Al\', gle, oni ne zbore. Umukoše, ni riječ više da kažu!');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (22, 32, 17, 'Na meni je da progovorim sada, znanje ću svoje i ja izložiti.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (22, 32, 18, 'Riječi mnoge u meni naviru dok iznutra moj duh mene nagoni.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (22, 32, 19, 'Gle, nutrina mi je k\'o mošt zatvoren, k\'o nova će se raspući mješina.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (22, 32, 20, 'Da mi odlane, govorit ću stoga, otvorit ću usne i odvratit\' vama.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (22, 32, 21, 'Nijednoj strani priklonit se neću niti laskat ja namjeravam kome.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (22, 32, 22, 'Laskati ja ne umijem nikako, jer smjesta bi me Tvorac moj smaknuo.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (22, 33, 1, 'Čuj dakle, Jobe, što ću ti kazati, prikloni uho mojim besjedama.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (22, 33, 2, 'Evo, usta sam svoja otvorio, a jezik riječi pod nepcem mi stvara.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (22, 33, 3, 'Iskreno će ti zborit\' srce moje, usne će čistu izreći istinu.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (22, 33, 4, 'TÓa i mene je duh Božji stvorio, dah Svesilnoga oživio mene.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (22, 33, 5, 'Ako uzmogneš, ti me opovrgni; spremi se da se suprotstaviš meni!');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (22, 33, 6, 'Gle, kao i ti, i ja sam pred Bogom, kao i ti, od gline bjeh načinjen;');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (22, 33, 7, 'zato ja strahom tebe motrit\' neću, ruka te moja neće pritisnuti.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (22, 33, 8, 'Dakle, na moje uši rekao si - posve sam jasno tvoje čuo riječi:');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (22, 33, 9, '\'Nedužan sam i bez ikakva grijeha; prav sam i nema krivice na meni.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (22, 33, 10, 'Al\' On izlike protiv mene traži i za svojeg me drži dušmanina.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (22, 33, 11, 'Noge je moje u klade metnuo, nad svakim mojim on pazi korakom.\'');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (22, 33, 12, 'Ovdje, kažem ti, u pravu ti nisi, jer s Bogom čovjek mjerit\' se ne može.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (22, 33, 13, 'Pa zašto s njime zamećeš prepirku što ti na svaku riječ ne odgovara?');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (22, 33, 14, 'Bog zbori nama jednom i dva puta, al\' čovjek na to pažnju ne obraća.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (22, 33, 15, 'U snovima, u viđenjima noćnim, kada san dubok ovlada ljudima i na ležaju dok tvrdo snivaju,');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (22, 33, 16, 'tad on govori na uho čovjeku i utvarama plaši ga jezivim');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (22, 33, 17, 'da ga od djela njegovih odvrati, da u čovjeku obori oholost,');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (22, 33, 18, 'da dušu njegovu spasi od jame i život mu od puta u Podzemlje.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (22, 33, 19, 'Bolešću on ga kara na ležaju kad mu se kosti tresu bez prestanka,');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (22, 33, 20, 'kad se kruh gadi njegovu životu i ponajbolje jelo duši njegovoj;');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (22, 33, 21, 'kada mu tijelo gine naočigled i vide mu se kosti ogoljele,');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (22, 33, 22, 'kad mu se duša približava jami a život njegov boravištu mrtvih.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (22, 33, 23, 'Ako se uza nj nađe tad anđeo, posrednik jedan između tisuću, da čovjeka na dužnost opomene,');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (22, 33, 24, 'pa se sažali nad njim i pomoli: \'Izbavi ga da u jamu ne ide; za život njegov nađoh otkupninu!');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (22, 33, 25, 'Neka mu tijelo procvate mladošću, nek\' se vrati u dane mladenačke!\'');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (22, 33, 26, 'Vapije k Bogu i Bog ga usliša: radosno On ga pogleda u lice; vrati čovjeku pravednost njegovu.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (22, 33, 27, 'Tada čovjek pred ljudima zapjeva: \'Griješio sam i pravo izvrtao, ali mi Bog zlom nije uzvratio.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (22, 33, 28, 'On mi je dušu spasio od jame i život mi se veseli svjetlosti.\'');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (22, 33, 29, 'Gle, sve to Bog je spreman učiniti do dva i do tri puta za čovjeka:');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (22, 33, 30, 'da dušu njegovu spasi od jame i da mu život svjetlošću obasja.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (22, 33, 31, 'Pazi dÓe, Jobe, dobro me poslušaj; šuti, jer nisam sve još izrekao.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (22, 33, 32, 'Ako riječi još imaš, odvrati mi, zbori - rado bih opravdao tebe.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (22, 33, 33, 'Ako li nemaš, poslušaj me samo: pazi, rad bih te poučit\' mudrosti.\"');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (22, 34, 1, 'Elihu nastavi svoju besjedu i reče:');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (22, 34, 2, '\"I vi, mudraci, čujte što ću reći, vi, ljudi umni, poslušajte mene,');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (22, 34, 3, 'jer uši nam prosuđuju besjede isto kao što nepce hranu kuša.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (22, 34, 4, 'Zajedno ispitajmo što je pravo i razmislimo skupa što je dobro.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (22, 34, 5, 'Job je utvrdio: \'Ja sam pravedan, ali Bog meni pravdu uskraćuje.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (22, 34, 6, 'U pravu sam, a lašcem prave mene, nasmrt prostrijeljen, a bez krivnje svoje!\'');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (22, 34, 7, 'Zar gdje čovjeka ima poput Joba koji porugu pije kao vodu,');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (22, 34, 8, 'sa zlikovcima koji skupa hodi i s opakima isti dijeli put?');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (22, 34, 9, 'On tvrdi: \'Kakva korist je čovjeku od tog što Bogu ugoditi želi?\'');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (22, 34, 10, 'Stoga me čujte, vi ljudi pametni! Od Boga zlo je veoma daleko i nepravednost od Svemogućega,');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (22, 34, 11, 'te on čovjeku plaća po djelima, daje svakom po njegovu vladanju.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (22, 34, 12, 'Odista, Bog zla nikada ne čini, niti Svesilni kad izvrće pravo.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (22, 34, 13, 'TÓa tko je njemu povjerio zemlju i vasioni svijet tko je stvorio?');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (22, 34, 14, 'Kad bi on dah svoj u se povukao, kad bi čitav svoj duh k sebi vratio,');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (22, 34, 15, 'sva bića bi odjednom izdahnula i u prah bi se pretvorio čovjek.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (22, 34, 16, 'Ako razuma imaš, slušaj ovo, prikloni uho glasu riječi mojih.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (22, 34, 17, 'Može li vladat\' koji mrzi pravo? Najpravednijeg hoćeš li osudit\'? -');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (22, 34, 18, 'Onog koji kaže kralju: \'Nitkove!\' a odličniku govori: \'Zlikovče!\'');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (22, 34, 19, 'Koji nije spram knezovima pristran i jednak mu je ubog i mogućnik, jer oni su djelo ruku njegovih?');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (22, 34, 20, 'Zaglave za tren, usred gluhe noći: komešaju se narodi, prolaze; ni od čije ruke moćni padaju.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (22, 34, 21, 'Jer, on nadzire pute čovjekove, pazi nad svakim njegovim korakom.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (22, 34, 22, 'Nema toga mraka niti crne tmine gdje bi se mogli zlikovci sakriti.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (22, 34, 23, 'Bog nikome unaprijed ne kaže kada će na sud pred njega stupiti.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (22, 34, 24, 'Bez saslušanja on satire jake i stavlja druge na njihovo mjesto.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (22, 34, 25, 'TÓa odveć dobro poznaje im djela! Sred noći on ih obara i gazi.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (22, 34, 26, 'Ćuškom ih bije zbog zloće njihove na mjestu gdje ih svi vidjeti mogu.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (22, 34, 27, 'Jer prestadoše za njime hoditi, zanemariše putove njegove');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (22, 34, 28, 'goneć uboge da vape do njega i potlačene da k njemu leleču.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (22, 34, 29, 'Al\' miruje li, tko da njega gane? Zastre li lice, tko ga vidjet\' može?');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (22, 34, 30, 'Nad pucima bdi k\'o i nad čovjekom da ne zavlada tko narod zavodi.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (22, 34, 31, 'Kada bezbožnik Bogu svome kaže: \'Zavedoše me, više griješit neću.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (22, 34, 32, 'Ne uviđam li, ti me sad pouči, i ako sam kad nepravdu činio, ubuduće ja činiti je neću!\'');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (22, 34, 33, 'Misliš da Bog mora njega kazniti, dok ti zamisli njegove prezireš? Al\' kada ti odlučuješ, a ne ja, mudrost nam svoju istresi dÓe sada!');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (22, 34, 34, 'Svi ljudi umni sa mnom će se složit\' i svatko razuman koji čuje mene:');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (22, 34, 35, 'Nepromišljeno Job je govorio, u riječima mu neima mudrosti.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (22, 34, 36, 'Stoga, nek\' se Job dokraja iskuša, jer odgovara poput zlikovaca;');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (22, 34, 37, 'a svom grijehu još pobunu domeće, među nama on plješće dlanovima i hule svoje na Boga gomila.\"');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (22, 35, 1, 'Elihu nastavi svoju besjedu i reče:');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (22, 35, 2, '\"Zar ti misliš da pravo svoje braniš, da pravednost pred Bogom dokazuješ,');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (22, 35, 3, 'kada mu kažeš: \'Što ti je to važno, i ako griješim, što ti činim time?\'');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (22, 35, 4, 'Na sve to ja ću odgovorit\' tebi i prijateljima tvojim ujedno.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (22, 35, 5, 'Po nebu se obazri i promatraj! Gledaj oblake: od tebe su viši!');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (22, 35, 6, 'Ako griješiš, što si mu uradio, prijestupom svojim što si mu zadao?');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (22, 35, 7, 'Ako si prav, što si dodao njemu i što iz ruke tvoje on dobiva?');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (22, 35, 8, 'Opakost tvoja tebi slične pogađa i pravda tvoja čovjeku koristi.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (22, 35, 9, 'Ali kad ispod teškog stenju jarma, kad vapiju na nasilje moćnika,');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (22, 35, 10, 'nitko ne kaže: \'Gdje je Bog, moj tvorac, koji noć pjesmom veselom ispunja,');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (22, 35, 11, 'umnijim nas od zvijeri zemskih čini i mudrijima od ptica nebeskih?\'');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (22, 35, 12, 'Tad vapiju, al\' on ne odgovara poradi oholosti zlikovaca.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (22, 35, 13, 'Ali kako je isprazno tvrditi da Bog njihove ne čuje vapaje, da pogled na njih ne svraća Svesilni!');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (22, 35, 14, 'A kamoli tek kada ti govoriš: \'On ne vidi mene, parnica moja pred njime stoji, a ja na nj još čekam.\'');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (22, 35, 15, 'Ili: \'Njegova srdžba ne kažnjava, nimalo on za prijestupe ne mari.\'');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (22, 35, 16, 'Isprazno tada otvara Job usta i besjede gomila nerazumne.\"');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (22, 36, 1, 'Elihu nastavi i reče:');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (22, 36, 2, '\"Strpi se malo, pa ću te poučit\', jer još nisam sve rekao za Boga.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (22, 36, 3, 'Izdaleka ću svoje iznijet\' znanje da Stvoritelja svojega opravdam.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (22, 36, 4, 'Zaista, za laž ne znaju mi riječi, uza te je čovjek znanjem savršen.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (22, 36, 5, 'Gle, Bog je silan, ali ne prezire, silan je snagom razuma svojega.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (22, 36, 6, 'Opakome on živjeti ne daje, nevoljnicima pravicu pribavlja.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (22, 36, 7, 'S pravednika on očiju ne skida, na prijestolje ih diže uz kraljeve da bi dovijeka bili uzvišeni.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (22, 36, 8, 'Ako su negvam\' oni okovani i užetima nevolje sputani,');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (22, 36, 9, 'djela njihova on im napominje, kazuje im grijeh njine oholosti.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (22, 36, 10, 'Tad im otvara uho k opomeni i poziva ih da se zla okane.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (22, 36, 11, 'Poslušaju li te mu se pokore, dani im završavaju u sreći, u užicima godine njihove.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (22, 36, 12, 'Ne slušaju li, od koplja umiru, zaglave, sami ne znajući kako.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (22, 36, 13, 'A srca opaka mržnju njeguju, ne ištu pomoć kad ih on okuje;');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (22, 36, 14, 'u cvatu svoga dječaštva umiru i venu poput hramskih milosnika.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (22, 36, 15, 'Nevoljnog on bijedom njegovom spasava i u nesreći otvara mu oči:');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (22, 36, 16, 'izbavit će te iz ždrijela tjeskobe k prostranstvima bezgraničnim izvesti, k prepunu stolu mesa pretiloga.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (22, 36, 17, 'Ako sudio nisi opakima, ako si pravo krnjio siroti,');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (22, 36, 18, 'nek\' te obilje odsad ne zavede i nek\' te dar prebogat ne iskvari.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (22, 36, 19, 'Nek\' ti je gavan k\'o čovjek bez zlata, a čovjek jake ruke poput slaba.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (22, 36, 20, 'Ne goni one koji su ti tuđi da rodbinu na njino mjesto staviš.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (22, 36, 21, 'Pazi se da u nepravdu ne skreneš, jer zbog nje snađe tebe iskušenje.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (22, 36, 22, 'Gle, uzvišen je Bog u svojoj snazi! Zar učitelja ima poput njega?');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (22, 36, 23, 'Tko je njemu put njegov odredio? Tko će mu reći: \'Radio si krivo\'?');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (22, 36, 24, 'Spomeni se veličati mu djelo što ga pjesmama ljudi opjevaše.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (22, 36, 25, 'S udivljenjem svijet čitav ga promatra, divi se čovjek, pa ma izdaleka.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (22, 36, 26, 'Veći je Bog no što pojmit\' možemo, nedokučiv je broj ljeta njegovih!');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (22, 36, 27, 'U visini on skuplja kapi vode te dažd u paru i maglu pretvara.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (22, 36, 28, 'Pljuskovi tada pljušte iz oblaka, po mnoštvu ljudskom dažde obilato.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (22, 36, 29, 'Tko li će shvatit\' širenje oblaka, tutnjavu strašnu njegovih šatora?');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (22, 36, 30, 'Gle, on nad sobom razastire svjetlost i dno morsko on vodama pokriva.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (22, 36, 31, 'Pomoću njih on podiže narode, u izobilju hranom ih dariva.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (22, 36, 32, 'On munju drži objema rukama i kazuje joj kamo će zgoditi.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (22, 36, 33, 'Glasom gromovnim sebe navješćuje, stiže s gnjevom da zgromi opačinu.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (22, 37, 1, 'Da, od toga i moje srce drhti i s mjesta svoga iskočiti hoće.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (22, 37, 2, 'Čujte, čujte gromor glasa njegova, tutnjavu što mu iz usta izlazi.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (22, 37, 3, 'Gle, munja lijeće preko cijelog neba - i sijevne blijesak s kraja na kraj zemlje -');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (22, 37, 4, 'iza nje silan jedan glas se ori: to On gromori glasom veličajnim. Munje mu lete, nitko ih ne priječi, tek što mu je glas jednom odjeknuo.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (22, 37, 5, 'Da, Bog gromori glasom veličajnim, djela velebna, neshvatljiva stvara.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (22, 37, 6, 'Kad snijegu kaže: \'Zasniježi po zemlji!\' i pljuskovima: \'Zapljuštite silno!\'');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (22, 37, 7, 'svakom čovjeku zapečati ruke da svi njegovo upoznaju djelo.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (22, 37, 8, 'U brlog se tad zvijeri sve uvuku i na svojem se šćućure ležaju.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (22, 37, 9, 'S južne se strane podiže oluja, a studen vjetri sjeverni donose.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (22, 37, 10, 'Već led od daha Božjega nastaje i vodena se kruti površina.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (22, 37, 11, 'I opet vodom puni on oblake, i sijevat\' stanu oblaci munjama;');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (22, 37, 12, 'kruže posvuda po volji njegovoj, što im naloži, to će izvršiti na licu cijelog kruga zemaljskoga.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (22, 37, 13, 'Šalje ih - ili da kazni narode, ili da ih milosrđem obdari.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (22, 37, 14, 'Poslušaj ovo, Jobe, umiri se i promotri djela Božja čudesna.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (22, 37, 15, 'Znaš li kako Bog njima zapovijeda, kako munju iz oblaka svog pušta?');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (22, 37, 16, 'Znaš li o čem vise gore oblaci? Čudesna to su znanja savršenog.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (22, 37, 17, 'Kako ti gore od žege haljine u južnom vjetru kad zemlja obamre?');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (22, 37, 18, 'Zar si nebesa s njim ti razapeo, čvrsta poput ogledala livenog?');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (22, 37, 19, 'DÓe naputi me što da mu kažemo: zbog tmine se ne snalazimo više.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (22, 37, 20, 'Zar ćeš mu reći: \'Hoću govoriti\'? Ili na propast vlastitu pristati?');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (22, 37, 21, 'Tko, dakle, može u svjetlost gledati na nebesima što se sja blistavo kada oblake rastjeraju vjetri?');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (22, 37, 22, 'Sa sjevera k\'o zlato je bljesnulo: veličanstvom strašnim Bog se odjenu!');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (22, 37, 23, 'Da, Svesilnog doseći ne možemo, neizmjeran je u moći i sudu, velik u pravdi, nikog on ne tlači.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (22, 37, 24, 'Zato ljudi svi neka ga se boje! Na mudrost oholu on i ne gleda!\"');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (22, 38, 1, 'Nato Jahve odgovori Jobu iz oluje i reče:');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (22, 38, 2, '\"Tko je taj koji riječima bezumnim zamračuje božanski promisao?');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (22, 38, 3, 'Bokove svoje opaši k\'o junak: ja ću te pitat\', a ti me pouči.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (22, 38, 4, 'Gdje si bio kad zemlju utemeljih? Kazuj, ako ti je znanje sigurno.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (22, 38, 5, 'Znaš li tko joj je mjere odredio i nad njom uže mjerničko napeo?');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (22, 38, 6, 'Na čemu joj počivaju temelji? Tko joj postavi kamen ugaoni');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (22, 38, 7, 'dok su klicale zvijezde jutarnje i Božji uzvikivali dvorjani?');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (22, 38, 8, 'Tko li zatvori more vratnicama kad je navrlo iz krila majčina;');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (22, 38, 9, 'kad ga oblakom k\'o haljom odjenuh i k\'o pelenam\' ovih maglom gustom;');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (22, 38, 10, 'kad sam njegovu odredio među, vrata stavio sa prijevornicama?');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (22, 38, 11, 'Dotle, ne dalje, rekao sam njemu, tu nek\' se lomi ponos tvog valovlja!');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (22, 38, 12, 'Zar si ikad zapovjedio jutru, zar si kazao zori mjesto njeno,');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (22, 38, 13, 'da poduhvati zemlju za rubove i da iz nje sve bezbožnike strese;');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (22, 38, 14, 'da je pretvori u glinu pečatnu i oboji je k\'o kakvu haljinu.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (22, 38, 15, 'Ona uzima svjetlost zlikovcima i pesnicu im lomi uzdignutu.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (22, 38, 16, 'Zar si ti prodro do izvora morskih, po dnu bezdana zar si kad hodio?');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (22, 38, 17, 'Zar su ti vrata smrti pokazali; vidje li dveri kraja mrtvih sjena?');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (22, 38, 18, 'Zar si prostranstvo zemlje uočio? Govori, ako ti je znano sve to.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (22, 38, 19, 'Koji putovi u dom svjetla vode, na kojem mjestu prebivaju tmine,');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (22, 38, 20, 'da ih odvedeš u njine krajeve, da im put k stanu njihovu pokažeš?');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (22, 38, 21, 'Ti znadeš to, tÓa davno ti se rodi, tvojih dana broj veoma je velik!');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (22, 38, 22, 'Zar si stigao do riznica snijega i zar si tuče spremišta vidio');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (22, 38, 23, 'što ih pričuvah za dane nevolje, za vrijeme boja krvava i rata?');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (22, 38, 24, 'Kojim li se putem dijeli munja kada iskre po svoj zemlji prosipa?');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (22, 38, 25, 'Tko li je jaz iskopao povodnju, tko prokrčio pute grmljavini');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (22, 38, 26, 'da bi daždjelo na kraj nenastanjen, na pustinju gdje žive duše nema,');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (22, 38, 27, 'da bi neplodnu napojio pustoš, da bi u stepi trava izniknula?');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (22, 38, 28, 'Ima li kiša svoga roditelja? Tko je taj koji kapi rose rađa?');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (22, 38, 29, 'Iz čijeg li mraz izlazi krila, tko slanu stvara što s nebesa pada?');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (22, 38, 30, 'Kako čvrsnu vode poput kamena i led se hvata površja bezdana?');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (22, 38, 31, 'Možeš li lancem vezati Vlašiće i razdriješiti spone Orionu,');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (22, 38, 32, 'u pravo vrijeme izvesti Danicu, vodit\' Medvjeda s njegovim mladima?');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (22, 38, 33, 'Zar poznaješ ti zakone nebeske pa da njima moć na zemlji dodijeliš?');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (22, 38, 34, 'Zar doviknuti možeš oblacima pa da pljuskovi tebe poslušaju?');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (22, 38, 35, 'Zar na zapovijed tvoju munje lijeću i tebi zar se odazivlju: \'Evo nas\'?');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (22, 38, 36, 'Tko je mudrost darovao ibisu, tko li je pamet ulio u pijetla?');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (22, 38, 37, 'Tko to mudro prebrojava oblake i tko nebeske izlijeva mjehove');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (22, 38, 38, 'dok se zemlja u tijesto ne zgusne i dok se grude njezine ne slijepe?');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (22, 38, 39, 'Zar ćeš ti plijen uloviti lavici ili ćeš glad utažit\' lavićima');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (22, 38, 40, 'na leglu svojem dok gladni čekaju i vrebaju na žrtvu iz zaklona?');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (22, 38, 41, 'Tko hranu gavranovima pribavlja kad Bogu ptići njegovi cijuču i naokolo oblijeću bez hrane?');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (22, 39, 1, 'Znaš li kako se legu divokoze? Vidje li kako se mlade košute?');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (22, 39, 2, 'Izbroji li koliko nose mjeseci, znaš li u koje doba se omlade?');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (22, 39, 3, 'Sagnuvši se, polegu lanad svoju i breme usred pustinje odlažu,');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (22, 39, 4, 'a kad im porod ojača, poraste, ostave ga i ne vraćaju mu se.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (22, 39, 5, 'Tko dade divljem magarcu slobodu i tko to oglav skinu njemu s glave?');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (22, 39, 6, 'U zavičaj mu dadoh ja pustinju i polja slana da ondje živuje.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (22, 39, 7, 'Buci gradova on se podruguje i ne sluša goničevih povika.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (22, 39, 8, 'Luta brdima, svojim pašnjacima, u potrazi za zeleni svakakvom.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (22, 39, 9, 'Možeš li slugom učinit\' bivola, zadržat\' ga noć jednu za jaslama?');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (22, 39, 10, 'Možeš li njega za brazdu prikovat\' da ralo vuče po docima tvojim?');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (22, 39, 11, 'Možeš li se osloniti na njega jer je njegova snaga prevelika i prepustit\' mu težak svoj posao?');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (22, 39, 12, 'Misliš li tebi da će se vratiti i na gumno ti dotjerati žito?');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (22, 39, 13, 'Krilima svojim noj trepće radosno, iako krila oskudnih i perja.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (22, 39, 14, 'On svoja jaja na zemlji ostavlja, povjerava ih pijesku da ih grije,');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (22, 39, 15, 'ne mareć\' što ih zgazit\' može noga ili nekakva divlja zvijer zgnječiti.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (22, 39, 16, 'S nojićima k\'o s tuđima postupa; što mu je trud zaludu, on ne mari.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (22, 39, 17, 'Jer Bog je njega lišio pameti, nije mu dao nikakva razbora.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (22, 39, 18, 'Ali kada na let krila raširi, tada se ruga konju i konjaniku.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (22, 39, 19, 'Zar si ti konja obdario snagom zar si mu ti vrat grivom ukrasio?');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (22, 39, 20, 'Zar ti činiš da skače k\'o skakavac, da u strah svakog nagoni hrzanjem?');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (22, 39, 21, 'Kopitom zemlju veselo raskapa, neustrašivo srlja na oružje.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (22, 39, 22, 'Strahu se ruga, ničeg se ne boji, ni pred mačem uzmaknuti neće.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (22, 39, 23, 'Na sapima mu zvekeće tobolac, koplje sijeva i ubojna sulica.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (22, 39, 24, 'Bijesan i nestrpljiv guta prostore; kad rog zasvira, tko će ga zadržat\':');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (22, 39, 25, 'na svaki zvuk roga on zarže: Ha! Izdaleka on ljuti boj već njuši, viku bojnu i poklič vojskovođa.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (22, 39, 26, 'Zar po promislu tvojem lijeće soko i prema jugu krila svoja širi?');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (22, 39, 27, 'Zar se na nalog tvoj diže orao i vrh timora gnijezdo sebi vije?');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (22, 39, 28, 'Na litici on stanuje i noćÄi, na grebenima vrleti visokih.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (22, 39, 29, 'Odatle na plijen netremice vreba, oči njegove vide nadaleko.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (22, 39, 30, 'Krvlju se hrane njegovi orlići; gdje je ubijenih, tamo je i on.\"');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (22, 40, 1, 'I Jahve se obrati Jobu i reče mu:');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (22, 40, 2, '\"Zar će se s Jakim preti još kudilac? Tužitelj Božji nek\' sam odgovori!\"');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (22, 40, 3, 'A Job odgovori Jahvi i reče:');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (22, 40, 4, '\"Odveć sam malen: što da odgovorim? Rukom ću svoja zatisnuti usta.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (22, 40, 5, 'Riječ rekoh - neću više započeti; rekoh dvije - al\' neću nastaviti.\"');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (22, 40, 6, 'Nato Jahve odgovori Jobu iz oluje i reče:');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (22, 40, 7, '\"Bokove svoje opaši k\'o junak, ja ću te pitat\', a ti me pouči.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (22, 40, 8, 'Zar bi i moj sud pogaziti htio, okrivio me da sebe opravdaš?');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (22, 40, 9, 'Zar ti mišica snagu Božju ima, zar glasom grmjet\' možeš poput njega?');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (22, 40, 10, 'Ogrni se sjajem i veličanstvom, dostojanstvom se odjeni i slavom.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (22, 40, 11, 'Plani dÓe bijesom ognja jarosnoga, pogledom jednim snizi oholnika.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (22, 40, 12, 'Ponositoga pogledaj, slomi ga, na mjestu satri svakoga zlikovca.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (22, 40, 13, 'U zemlju sve njih zajedno zakopaj, u mračnu ih pozatvaraj tamnicu.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (22, 40, 14, 'Tada ću i ja tebi odat\' hvalu što si se svojom desnicom spasio.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (22, 40, 15, 'A sada, dÓe promotri Behemota! Travom se hrani poput govečeta,');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (22, 40, 16, 'u bedrima je, gle, snaga njegova, a krepkost mu u mišićju trbušnom.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (22, 40, 17, 'Poput cedra rep podignut ukruti, sva su mu stegna ispreplele žile.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (22, 40, 18, 'Mjedene cijevi kosti su njegove, zglobovi mu od željeza kvrge.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (22, 40, 19, 'Prvenac on je Božjega stvaranja; mačem ga je naoružao tvorac.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (22, 40, 20, 'Gore mu danak u hrani donose i sve zvijerje što po njima se igra.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (22, 40, 21, 'Pod lotosom on zavaljen počiva, guštik močvarni i glib kriju ga.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (22, 40, 22, 'Sjenu mu pravi lotosovo lišće, pod vrbama on hladuje potočnim.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (22, 40, 23, 'Nabuja li rijeka, on ne strahuje: nimalo njega ne bi zabrinulo da mu u žvale i sav Jordan jurne.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (22, 40, 24, 'Tko bi za oči uhvatio njega i tko bi mu nos sulicom probio?');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (22, 40, 25, 'Zar loviš Levijatana udicom? Zar ćeš mu jezik zažvalit\' užetom?');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (22, 40, 26, 'Zar mu nozdrve trskom probost\' možeš ili mu kukom probiti vilicu?');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (22, 40, 27, 'Hoće li te on preklinjat\' za milost, hoće li s tobom blago govoriti?');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (22, 40, 28, 'I zar će s tobom savez on sklopiti da sveg života tebi sluga bude?');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (22, 40, 29, 'Hoćeš li se s njim k\'o s pticom poigrat\' i vezat\' ga da kćeri razveseliš?');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (22, 40, 30, 'Hoće li se za nj cjenkati ribari, među sobom podijelit\' ga trgovci?');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (22, 40, 31, 'Možeš li kopljem njemu kožu izbost ili glavu mu probiti ostima?');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (22, 40, 32, 'Podigni de ruku svoju na njega: za boj se spremi - bit će ti posljednji!');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (22, 41, 1, 'Zalud je nadu u njega gojiti, na pogled njegov čovjek već pogiba.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (22, 41, 2, 'Junaka nema da njega razdraži, tko će mu se u lice suprotstavit\'?');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (22, 41, 3, 'Tko se sukobi s njim i živ ostade? Pod nebesima tog čovjeka nema!');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (22, 41, 4, 'Prešutjet neću njegove udove, ni silnu snagu, ni ljepotu stasa.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (22, 41, 5, 'Tko mu smije razodjenut\' odjeću, tko li kroz dvostruk prodrijeti mu oklop?');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (22, 41, 6, 'Tko će mu ralje rastvorit\' dvokrilne kad strah vlada oko zubi njegovih?');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (22, 41, 7, 'Hrbat mu je od ljuskavih štitova, zapečaćenih pečatom kamenim.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (22, 41, 8, 'Jedni uz druge tako se sljubiše da među njima dah ne bi prošao.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (22, 41, 9, 'Tako su čvrsto slijepljeni zajedno: priljubljeni, razdvojit\' se ne mogu.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (22, 41, 10, 'Kad kihne, svjetlost iz njega zapršti, poput zorinih vjeđa oči su mu.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (22, 41, 11, 'Zublje plamsaju iz njegovih ralja, iskre ognjene iz njih se prosiplju.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (22, 41, 12, 'Iz nozdrva mu sukljaju dimovi kao iz kotla što kipi na vatri.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (22, 41, 13, 'Dah bi njegov zapalio ugljevlje, jer mu iz ralja plamenovi suču.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (22, 41, 14, 'U šiji leži sva snaga njegova, a ispred njega užas se prostire.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (22, 41, 15, 'Kad se ispravi, zastrepe valovi i prema morskoj uzmiču pučini.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (22, 41, 16, 'Poput pećine srce mu je tvrdo, poput mlinskoga kamena otporno.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (22, 41, 17, 'Pregibi tusta mesa srasli su mu, čvrsti su kao da su saliveni.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (22, 41, 18, 'Zgodi li ga mač, od njeg se odbije, tako i koplje, sulica i strijela.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (22, 41, 19, 'Poput slame je za njega željezo, mjed je k\'o drvo iscrvotočeno.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (22, 41, 20, 'On ne uzmiče od strelice s luka, stijenje iz praćke na nj k\'o pljeva pada.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (22, 41, 21, 'K\'o slamčica je toljaga za njega, koplju se smije kad zazviždi nad njim.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (22, 41, 22, 'Crepovlje oštro ima na trbuhu i blato njime ore k\'o drljačom.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (22, 41, 23, 'Pod njim vrtlog sav k\'o lonac uskipi, uspjeni more k\'o pomast u kotlu.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (22, 41, 24, 'Za sobom svijetlu ostavlja on brazdu, regbi, bijelo runo bezdan prekriva.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (22, 41, 25, 'Ništa slično na zemlji ne postoji i niti je tko tako neustrašiv.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (22, 41, 26, 'I na najviše on s visoka gleda, kralj je svakome, i najponosnijim.\"');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (22, 42, 1, 'A Job ovako odgovori Jahvi:');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (22, 42, 2, '\"Ja znadem, moć je tvoja bezgranična: što god naumiš, to izvesti možeš.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (22, 42, 3, 'Tko je taj koji riječima bezumnim zamračuje božanski promisao? Govorah stoga, ali ne razumjeh, o čudesima meni neshvatljivim.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (22, 42, 4, 'O, poslušaj me, pusti me da zborim: ja ću te pitat\', a ti me pouči.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (22, 42, 5, 'Po čuvenju tek poznavah te dosad, ali sada te oči moje vidješe.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (22, 42, 6, 'Sve riječi svoje zato ja poričem i kajem se u prahu i pepelu.\"');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (22, 42, 7, 'Kada Jahve izgovori Jobu ove riječi, reče on Elifazu Temancu: \"Ti i tvoja dva prijatelja raspalili ste gnjev moj jer niste o meni onako pravo govorili kao moj sluga Job.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (22, 42, 8, 'Zato uzmite sada sedam junaca i sedam ovnova i pođite k mome sluzi Jobu, pa prinesite za sebe paljenicu, a sluga moj Job molit će se za vas. Imat ću obzira prema njemu i neću vam učiniti ništa nažao zato što niste o meni onako pravo govorili kao moj sluga Job.\"');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (22, 42, 9, 'Tada odoše Elifaz iz Temana, Bildad iz Šuaha i Sofar iz Naamata i učiniše kako im je Jahve zapovjedio. I Jahve se obazre na Joba.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (22, 42, 10, 'I Jahve vrati Joba u prijašnje stanje jer se založio za svoje prijatelje, pa mu još udvostruči ono što je posjedovao.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (22, 42, 11, 'Tad se vratiše Jobu sva njegova braća, i sve njegove sestre, i svi prijašnji znanci te su jeli s njim kruh u njegovoj kući, žaleći ga i tješeći zbog svih nevolja što ih Jahve bijaše na nj poslao. Svaki mu darova po jedan srebrnik i po jedan zlatan prsten.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (22, 42, 12, 'Jahve blagoslovi novo Jobovo stanje još više negoli prijašnje. Blago mu je brojilo četrnaest tisuća ovaca, šest tisuća deva, tisuću jarmova volova i tisuću magarica.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (22, 42, 13, 'Imao je sedam sinova i tri kćeri.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (22, 42, 14, 'Prvoj nadjenu ime Jemima, drugoj Kasija, a trećoj Keren-Hapuk.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (22, 42, 15, 'U svem onom kraju ne bijaše žena tako lijepih kao Jobove kćeri. I otac im dade jednaku baštinu kao i njihovoj braći.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (22, 42, 16, 'Poslije toga Job doživje dob od sto četrdeset godina i vidje djecu svoju i djecu svoje djece do četvrtog koljena. Potom umrije Job, star, nauživši se života.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (22, 42, 17, '');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 1, 1, 'Blago čovjeku koji ne slijedi savjeta opakih, ne staje na putu grešničkom i ne sjeda u zbor podrugljivaca,');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 1, 2, 'već uživa u Zakonu Jahvinu, o Zakonu njegovu misli dan i noć.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 1, 3, 'On je k\'o stablo zasađeno pokraj voda tekućica što u svoje vrijeme plod donosi; lišće mu nikad ne vene, sve što radi dobrim urodi.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 1, 4, 'Nisu takvi opaki, ne, nisu takvi! Oni su k\'o pljeva što je vjetar raznosi.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 1, 5, 'Stoga se opaki neće održati na sudu, ni grešnici u zajednici pravednih.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 1, 6, 'Jer Jahve zna put pravednih, a propast će put opakih.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 2, 1, 'Zašto se bune narodi, zašto puci ludosti snuju?');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 2, 2, 'Ustaju kraljevi zemaljski, knezovi se rotÄe protiv Jahve i Pomazanika njegova:');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 2, 3, '\"Skršimo okove njihove i jaram njihov zbacimo!\"');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 2, 4, 'Smije se onaj što na nebu stoluje, Gospod im se podruguje.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 2, 5, 'Tad im veli u svom gnjevu, žestinom ih on zbunjuje:');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 2, 6, '\"TÓa ja kralja svog postavih nad Sionom, svojom svetom gorom.\"');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 2, 7, 'Obznanjujem odluku Jahvinu: Gospodin mi reče: \"Ti si sin moj, danas te rodih.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 2, 8, 'Zatraži samo, i dat ću ti puke u baštinu, i u posjed krajeve zemaljske.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 2, 9, 'Vladat ćeš njima palicom gvozdenÄom i razbit ih kao sud lončarski.\"');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 2, 10, 'Opametite se sada, vi kraljevi, Urazumite se, suci zemaljski.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 2, 11, 'Služite Jahvi sa strahom, s trepetom se pokorite njemu,');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 2, 12, 'da se ne razgnjevi te ne propadnete na putu, kad uskoro plane srdžba njegova. Blago svima koji se njemu utječu!');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 3, 1, 'Psalam. Davidov. Kad je David bježao pred sinom Abšalomom.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 3, 2, 'Jahve, koliko je tlačitelja mojih, koliki se podižu na me!');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 3, 3, 'Mnogi su što o meni zbore: \"Nema mu spasenja u Bogu!\"');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 3, 4, 'Ti si ipak štit moj, Jahve; slavo moja, ti mi glavu podižeš.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 3, 5, 'Iza sveg glasa Jahvi zavapih, i on me usliša sa svete gore svoje.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 3, 6, 'Sad mogu leć\' i usnuti, i onda ustat\' jer me Jahve drži.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 3, 7, 'Ne bojim se tisuća ljudi što me opsjedaju dušmanski.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 3, 8, 'Ustani, o Jahve! Spasi me, o Bože moj! Ti udaraš po obrazu sve neprijatelje moje, opakima zube razbijaš.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 3, 9, 'U Jahve je spasenje: na tvom narodu tvoj je blagoslov!');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 4, 1, 'Zborovođi. Uz žičana glazbala. Psalam. Davidov.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 4, 2, 'Kad zazovem, usliši me, Bože, pravdo moja, ti što me u tjeskobi izbavÄi: smiluj mi se, usliši moju molitvu!');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 4, 3, 'Sinovi čovječji, dokle će vam srca ostati tvrda? Zašto ispraznost ljubite, opsjenu slijedite?');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 4, 4, 'Znajte: Jahve čudesno uzvisuje prijatelja svoga; Gospodin će me uslišiti kad ga zazovem.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 4, 5, 'Promislite u srcima i ne griješite, dršćite na svojim ležajima i zanijemite.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 4, 6, 'Prinesite žrtve pravedne, u Jahvu se uzdajte!');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 4, 7, 'Mnogi govore: \"Tko će nam pokazati sreću?\" Obasjaj nas, Jahve, svjetlom svoga lica!');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 4, 8, 'Više si u srce moje ulio radosti nego kad obilno rode pšenica i vino.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 4, 9, 'Čim legnem, odmah u miru i usnem, jer mi samo ti, o Jahve, daješ miran počinak.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 5, 1, 'Zborovođi. Uz frule. Psalam. Davidov.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 5, 2, 'Čuj, o Jahve, riječi moje, jecaje moje razaberi!');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 5, 3, 'Osvrni se na glas mog prizivanja, o Kralju moj i Bože moj, jer tebe vruće zazivam!');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 5, 4, 'Jahve, zorom glas mi već čuješ, zorom ti već lijem molitve u nadi čekajuć\'.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 5, 5, 'Jer ti nisi Bog kom je nepravda mila: zlobniku nema boravka s tobom,');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 5, 6, 'opaki ne mogu opstati pred tvojim pogledom. Mrziš sve što čine bezakonje');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 5, 7, 'i uništavaš lažljivce. Varalica i krvopija Jahvi se gadi.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 5, 8, 'Po velikoj dobroti tvojoj unići ću u Dom tvoj; past ću ničice pred svetim Domom tvojim, Jahve, prepun poštovanja.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 5, 9, 'U svojoj me pravdi vodi poradi mojih dušmana, svoj put mi poravnaj pred očima.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 5, 10, 'U njihovim ustima iskrenosti nema, srce im je puno zloće; grlo im je grob otvoren, a jezikom laskaju.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 5, 11, 'Kazni ih, o Bože! Nek\' propadnu oni i osnove njine, otjeraj ih zbog mnogih nedjela njihovih; tÓa oni se digoše na tebe.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 5, 12, 'Nek\' se raduju svi što se utječu tebi, neka kliču sve dovijeka! Štiti ih i nek se vesele u tebi koji ljube ime tvoje,');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 5, 13, 'jer pravednika, Jahve, ti blagoslivljaš, dobrotom ga svojom k\'o štitom zaklanjaš.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 6, 1, 'Zborovođi. Uz žičano glazbalo. U oktavi. Psalam. Davidov.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 6, 2, 'Jahve, nemoj me karati u srdžbi svojoj, ne kažnjavaj me u svojoj jarosti!');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 6, 3, 'Smiluj mi se, Jahve, jer sam iznemog\'o, Jahve, ozdravi me jer dršću kosti moje.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 6, 4, 'Duboko mi je duša potresena, a ti, o Jahve - dokle ćeš?');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 6, 5, 'Vrati se, Jahve, dušu mi izbavi, spasi me rad svoje dobrote:');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 6, 6, 'jer među mrtvima tko te se sjeća, u Podzemlju tko ti hvale pjeva?');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 6, 7, 'Iznemogoh od pusta jecanja, u noći postelju plačem zalijevam, suzama ležaj natapam.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 6, 8, 'Od žalosti oko mi gasne i slabi, jer su mnogi neprijatelji moji.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 6, 9, 'Odstupite od mene, svi opaki, jer je Jahve plač moj čuo.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 6, 10, 'Čuo je Jahve molbu moju, Jahve je primio moju molitvu.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 6, 11, 'Neka se postide i užasno zbune svi moji dušmani, i puni srama neka smjesta odstupe.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 7, 1, 'Tužaljka. Davidova. Ispjeva je Jahvi zbog Kuša Benjaminovca.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 7, 2, 'O Jahve, Bože moj, tebi se utječem, od svih progonitelja spasi me, oslobodi,');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 7, 3, 'da mi dušu ne zgrabe kao lav što razdire, a nema tko da izbavi.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 7, 4, 'Jahve, Bože moj, ako to učinih, ako je nepravda na rukama mojim,');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 7, 5, 'ako zlom uzvratih prijatelju, ili oplijenih nepravedna tužitelja:');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 7, 6, 'neka mi dušmanin progoni dušu i zgrabi je, neka mi život u zemlju satre i jetru u prašinu baci.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 7, 7, 'Ustani, Jahve, u svom gnjevu, digni se na bijes tlačitelja mojih. Probudi se! Sud mi sazovi!');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 7, 8, 'Neka te okruži skupština narodna, nad njom sjedni visoko!');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 7, 9, 'O Jahve, dosudi mi pravo po pravosti mojoj i po nevinosti koja je u meni.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 7, 10, 'Dokrajči bezakonje zlotvora, pravedna podigni, pravedni Bože koji proničeš srca i bubrege.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 7, 11, 'Meni je štit Bog koji spasava čestita srca.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 7, 12, 'Bog je pravedan sudac, on povazdan prijeti:');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 7, 13, 'ako se ne obrate, mač će naoštriti, luk će svoj zapet\' i pravo smjerit\'.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 7, 14, 'Spremit će za njih smrtonosno oružje, strijele će svoje užariti.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 7, 15, 'Eto, zlotvor zače nepravdu, otrudnje pakošću i podlost rodi.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 7, 16, 'Iskopa jamu i prodube; sam u jamu svoju pade!');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 7, 17, 'Pakost će njegova pasti njemu na glavu, njemu na tjeme okrenut se nasilje njegovo.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 7, 18, 'A ja ću hvaliti Jahvu zbog pravde njegove i pjevat ću imenu Jahve višnjega.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 8, 1, 'Zborovođi. Po napjevu \"Tijesci\". Psalam. Davidov.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 8, 2, 'Jahve, Gospode naš, divno je ime tvoje po svoj zemlji, veličanstvom nebo natkriljuješ!');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 8, 3, 'U ustima djece i dojenčadi hvalu si spremio protiv neprijatelja, da postidiš mrzitelja, zlotvora.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 8, 4, 'Gledam ti nebesa, djelo prstiju tvojih, mjesec i zvijezde što ih učvrsti -');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 8, 5, 'pa što je čovjek da ga se spominješ, sin čovječji te ga pohodiš?');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 8, 6, 'Ti ga učini malo manjim od Boga, slavom i sjajem njega okruni.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 8, 7, 'Vlast mu dade nad djelima ruku svojih, njemu pod noge sve podloži:');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 8, 8, 'ovce i svakolika goveda, i zvijeri poljske k tome,');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 8, 9, 'ptice nebeske i ribe morske, i što god prolazi stazama morskim.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 8, 10, 'Jahve, Gospode naš, divno je ime tvoje po svoj zemlji!');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 9, 1, 'Zborovođi. Po napjevu \"Umri za sina\". Psalam. Davidov.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 9, 2, '$ALEF Slavim te, Jahve, svim srcem svojim, ispovijedam sva čudesna djela tvoja.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 9, 3, 'Radujem se i kličem tebi, pjevam imenu tvome, Svevišnji!');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 9, 4, '$BET Dušmani moji natrag krenuše, padoše i pred licem tvojim pogiboše.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 9, 5, 'Jer ti se zauze za moje pravo i parbu moju, ti sjede na prijesto - sudac pravedan:');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 9, 6, '$GIMEL ti pokara pogane, pogubi bezbošca, ime im izbrisa dovijeka.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 9, 7, 'Dušmani klonuše, smrvljeni zauvijek, ti im gradove razori - nesta im spomena.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 9, 8, '$HE Ali Jahve dovijeka stoluje, postavi prijesto svoj da sudi:');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 9, 9, 'sam po pravdi sudi krug zemaljski, izreče pucima osudu pravednu.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 9, 10, '$VAU Jahve je tvrđava tlačenom, tvrđava spasa u danima tjeskobe.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 9, 11, 'Nek\' se uzdaju u te koji znaju ime tvoje, jer ne ostavljaš onih što ljube tebe, o Jahve.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 9, 12, '$ZAJIN Pjevajte Jahvi koji prebiva na Sionu, razglašujte među pucima djela njegova,');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 9, 13, 'jer ih se spomenu kao osvetnik krvi i siromaškog jauka ne zaboravi.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 9, 14, '$HET Smiluj mi se, Jahve: pogledaj nevolju u koju me vrgoše neprijatelji moji, od vrata smrti izbavi me');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 9, 15, 'da naviještam sve hvale tvoje na vratima kćeri Sionske, da radostan kličem zbog spasenja tvoga.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 9, 16, '$TET Pogani padoše u jamu koju sami iskopaše, zamka koju potajno staviše uhvati nogu njihovu.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 9, 17, 'Jahve se iskaza i sud održa; grešnik se spleo u djela svoja.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 9, 18, '$JOD Nek\' grešnici odu u Podzemlje, svi pogani što zaboraviše Boga.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 9, 19, '$KAF Jer siromah neće pasti u zaborav zauvijek, ufanje ubogih neće biti zaludu dovijeka.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 9, 20, 'Ustani, Jahve, da se ne osili čovjek, nek\' pogani budu osuđeni pred tobom!');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 9, 21, 'Strah im, o Jahve, utjeraj, nek\' spoznaju pogani da su smrtnici!');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 10, 1, '$LAMED Zašto, Jahve, stojiš daleko, zašto se skrivaš u dane tjeskobe?');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 10, 2, 'Obijesni bezbožnik jadnika goni, u zamke ga hvata koje mu postavi.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 10, 3, 'Bezbožnik se pohlepom hvali, $NUN lakomac psuje i Jahvu prezire.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 10, 4, 'Bezbožnik zbori u obijesti svojoj: \"Ne, istrage nema! TÓa ni Boga nema!\" I u tome sva mu je misao.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 10, 5, 'Puti su mu svagda uspješni, na sudove tvoje on i ne misli, sve protivnike svoje prezire.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 10, 6, 'U srcu veli: \"Neću posrnuti! Ni u kojem koljenu neću biti nesretan.\"');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 10, 7, '$PE Usta mu puna kletve, lukavstva i prijevare, pod jezikom njegovim muka i nesreća.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 10, 8, 'U zasjedi čuči pokraj ograda, potajno ubija nevina, $AJIN očima siromaha vreba.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 10, 9, 'U zaklonu sjedi k\'o lav u pećini, vreba da opljačka jadnika i da ga povuče u mrežu.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 10, 10, 'Pritajen čuči na zemlji, od nasilja mu siromasi padaju.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 10, 11, 'U srcu svome veli: \"ZÓaboravi Gospod, odvrati lice i nikoga ne vidi!\"');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 10, 12, '$KOF Ustani, Gospode Bože, podigni ruku, ne zaboravi siromaha.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 10, 13, 'Zašto da bezbožnik prezire Boga, zašto da kaže u srcu: \"Neće kazniti!\"');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 10, 14, '$REŠ Jer ti vidiš, gledaš jad i nevolju, u ruci je mjeriš. Siromah se tebi predaje, ubogu ti si pomoć!');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 10, 15, '$ŠIN Pakosnu grešniku satri mišicu, kazni mu pakost da je više ne bude!');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 10, 16, 'Jahve je kralj u vijeke vjekova, iz zemlje njegove nestat će pogana.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 10, 17, '$TAU Počuj, o Jahve, čežnju siromašnih, okrijepi im srce, uho prikloni:');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 10, 18, 'da zaštitiš pravo ubogih i tlačenih, da straha više ne zadaje čovjek zemljanÄi.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 11, 1, 'Zborovođi. Psalam. Davidov. Jahvi se utječem! Zašto dakle govorite duši mojoj: \"Odleti u goru kao ptica!');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 11, 2, 'Gle, bezbožnici već luk napeše, za tetivu strijelu zapeše da iz potaje ustrijele pravednika.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 11, 3, 'Kad su temelji uzljuljani, što da učini pravednik?\"');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 11, 4, 'Jahve je u svom svetom Hramu, na nebeskom sjedi prijestolju. Oči njegove motre, vjeđama proniče sinove ljudske.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 11, 5, 'Jahve proniče pravedna i nepravedna, iz dna duše mrzi silnika.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 11, 6, 'Na grešnike će izlit\' žeravu i sumpor, vjetar ognjeni bit će dio njine sudbine.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 11, 7, 'Pravedan je Jahve i pravednost ljubi, čestiti će gledat\' lice njegovo.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 12, 1, 'Zborovođi. U oktavi. Psalam. Davidov.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 12, 2, 'U pomoć, Jahve, jer nestaje pobožnih, vjernosti nema više među ljudima!');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 12, 3, 'Svatko laže svome bližnjemu, govori usnama lažljivim i srcem dvoličnim.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 12, 4, 'Istrijebi, Jahve, sve usne lažljive i jezik hvastavi;');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 12, 5, 'one što zbore: \"Jezik je naša snaga, naše su usne za nas: tko nam što može?\"');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 12, 6, '\"Zbog nevolje tlačenih i jauka ubogih sada ću ustati - govori Jahve - spasenje donijet\' onom tko ga želi.\"');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 12, 7, 'Riječi su Jahvine riječi iskrene, srebro prokušano, od zemlje odvojeno, sedam puta očišćeno.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 12, 8, 'O Jahve, ti ćeš bdjeti nad nama, od naraštaja ovog čuvat\' nas svagda,');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 12, 9, 'pa nek\' se okolo vrzu zlotvori, nek\' se izdižu ljudi najgori.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 13, 1, 'Zborovođi. Psalam. Davidov.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 13, 2, 'TÓa dokle, Jahve, dokle ćeš me zaboravljati? Dokle ćeš skrivati lice od mene?');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 13, 3, 'Dokle ću nositi bol u duši; tugu u srcu obdan i obnoć? Dokle će se dušmanin dizat\' na me?');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 13, 4, 'Pogledaj, usliši, Jahve, Bože moj! Prosvijetli mi oči da ne zaspim nasmrt,');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 13, 5, 'nek\' ne kaže dušmanin: \"Nadjačah njega!\" Nek\' ne kliču protivnici ako posrnem!');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 13, 6, 'Ja se u tvoju dobrotu uzdam, nek\' mi se srce raduje spasenju tvome! Pjevat ću Jahvi koji mi učini dobro, pjevat ću imenu Jahve Svevišnjeg!');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 14, 1, 'Zborovođi. Davidov. Bezumnik reče u srcu: \"Nema Boga.\" Pokvareni rade gadosti; nitko da čini dobro.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 14, 2, 'Jahve s nebesa gleda na sinove ljudske da vidi ima li tko razuman Boga da traži.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 14, 3, 'No, svi skrenuše zajedno, svi se pokvariše: nitko da čini dobro - nikoga nema.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 14, 4, 'Neće li se urazumiti svi što bezakonje čine, koji proždiru narod moj kao da jedu kruha? Ne zazivlju ime Jahvino:');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 14, 5, 'jednom će drhtati od straha, jer je Bog s rodom pravednim.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 14, 6, 'Želite razbiti nakane ubogog: Jahve je utočište njegovo.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 14, 7, 'O neka dođe sa Siona spas Izraelu! Kad Jahve promijeni udes naroda svoga, klicat će Jakov, radovat se Izrael.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 15, 1, 'Psalam. Davidov. Jahve, tko smije prebivati u šatoru tvome, tko li stanovati na svetoj gori tvojoj?');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 15, 2, 'Onaj samo tko živi čestito, koji čini pravicu, i istinu iz srca zbori,');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 15, 3, 'i ne kleveće jezikom; koji bližnjem zla ne nanosi i ne sramoti susjeda svoga;');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 15, 4, 'koji zlikovca prezire, a poštuje one što se Jahve boje;');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 15, 5, 'koji se zaklinje prijatelju, a ne krši prisege, i ne daje novca na lihvu, i ne prima mita protiv nedužna. Tko tako čini, pokolebat\' se neće dovijeka.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 16, 1, 'Miktam. Davidov. Čuvaj me, Bože, jer se tebi utječem.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 16, 2, 'Jahvi rekoh: \"Ti si moj gospodar, nema mi blaženstva bez tebe!\"');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 16, 3, 'Za svetima što su u zemlji sav plamtim od čežnje!');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 16, 4, 'Gomilaju patnje moje koji slijede bogove tuđe. Ja im ljevanica nalijevat\' neću, ime im spominjat\' neću usnama.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 16, 5, 'Jahve mi je baština i kalež: Ti u ruci držiš moju sudbinu.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 16, 6, 'Na divnu zemlju padoše mi konopi, vrlo mi je mila moja baština.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 16, 7, 'Blagoslivljam Jahvu koji me svjetuje te me i noću srce opominje.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 16, 8, 'Jahve mi je svagda pred očima; jer mi je zdesna, neću posrnuti.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 16, 9, 'Stog\' mi se raduje srce i kliče duša, i tijelo mi spokojno počiva.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 16, 10, 'Jer mi nećeš ostavit\' dušu u Podzemlju ni dati da pravednik tvoj truleži ugleda.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 16, 11, 'Pokazat ćeš mi stazu u život, puninu radosti pred licem svojim, sebi zdesna blaženstvo vječno.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 17, 1, 'Molitva. Davidova. Počuj, Jahve pravedni, i vapaj mi poslušaj, usliši molitvu iz usta iskrenih!');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 17, 2, 'Od tebe nek\' mi dođe presuda, tvoje oči vide što je pravo.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 17, 3, 'Istraži mi srce, pohodi noću, ognjem me iskušaj, al\' u meni nećeš nać\' bezakonja. Ne zgriješiše usta moja');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 17, 4, 'kao što griješe ljudi: po riječima usta tvojih čuvah putove Zakona.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 17, 5, 'Korak mi čvrsto prionu za tvoje staze, ne zasta mi noga na putima tvojim.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 17, 6, 'Zazivam te, Bože, ti ćeš me uslišit\': prikloni mi uho i čuj riječi moje.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 17, 7, 'Proslavi na meni dobrotu svoju, ti koji od dušmana izbavljaš one što se utječu desnici tvojoj.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 17, 8, 'Čuvaj me k\'o zjenicu oka, sakrij me u sjenu krila svojih');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 17, 9, 'od zlotvora što na me nasrću. Dušmani me bijesni opkoljuju,');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 17, 10, 'bešćutno srce zatvaraju i ustima zbore naduto,');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 17, 11, 'Koraci njini sad me okružuju, smjeraju da me na zemlju obore;');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 17, 12, 'slični lavu dok se, zinuv, na plijen obara i laviću što vreba u potaji.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 17, 13, 'Ustani, Jahve, presretni ga i obori, od grešnika mi život mačem spasi,');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 17, 14, 'a rukom od ljudi, Gospodine: od ljudi kojih je dio ovaj život, kojima želudac puniš dobrima; kojih su sinovi siti, a djeci daju što im pretekne.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 17, 15, 'A ja ću u pravdi gledati lice tvoje, i jednom kad se probudim, sit ću ga se nagledati.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 18, 1, 'Učitelju zbora. Od Jahvina sluge Davida koji Jahvi ispjeva ovu pjesmu u onaj dan kad ga Jahve oslobodi iz ruku neprijatelja');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 18, 2, 'Ljubim te, Jahve, kreposti moja!');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 18, 3, 'Jahve, hridino moja, utvrdo moja spase moj; Bože moj, pećino moja kojoj se utječem, štite moj, snago spasenja moga, tvrđavo moja!');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 18, 4, 'Zazvat ću Jahvu, hvale predostojna, i od dušmana bit ću izbavljen.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 18, 5, 'Valovi smrti okružiše mene, prestraviše me bujice pogubne.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 18, 6, 'Užad Podzemlja sputiše me, smrtonosne zamke padoše na me:');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 18, 7, 'u nevolji zazvah Jahvu i Bogu svome zavapih. Iz svog Hrama zov mi začu, i vapaj moj mu do ušiju doprije.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 18, 8, 'I zemlja se potrese i uzdrhta, uzdrmaše se temelji gora, pokrenuše se, jer On gnjevom planu.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 18, 9, 'Iz nosnica mu dim se diže, iz usta mu oganj liznu, ugljevlje živo od njega plamsa.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 18, 10, 'On nagnu nebesa i siđe, pod nogama oblaci mu mračni.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 18, 11, 'Na keruba stade i poletje; na krilima vjetra zaplovi.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 18, 12, 'Ogrnu se mrakom kao koprenom, prekri se tamnim vodama i oblacima tmastim,');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 18, 13, 'od blijeska pred licem njegovim užga se ugljevlje plameno.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 18, 14, 'Jahve s neba zagrmje, Svevišnjega glas se ori.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 18, 15, 'Odape strijele i dušmane rasu, izbaci munje i na zemlju ih obori.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 18, 16, 'Morska se dna pokazaše, i temelji svijeta postaše goli od strašne prijetnje Jahvine, od olujna daha gnjeva njegova.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 18, 17, 'On pruži s neba ruku i mene prihvati, iz silnih voda on me izbavi.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 18, 18, 'Od protivnika moćnog mene oslobodi, od dušmana mojih jačih od mene.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 18, 19, 'Navališe na me u dan zlosretni, ali me Jahve zaštiti,');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 18, 20, 'na polje prostrano izvede me, spasi me jer sam mu mio.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 18, 21, 'Po pravednosti mojoj Jahve mi uzvrati, po čistoći ruku mojih on me nagradi,');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 18, 22, 'jer čuvah putove Jahvine, od Boga se svoga ne udaljih.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 18, 23, 'Odredbe njegove sve su mi pred očima, zapovijedi njegove nisam odbacio,');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 18, 24, 'do srži odan njemu sam bio, čuvam se grijeha svakoga.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 18, 25, 'Jahve mi po pravdi mojoj vrati, čistoću ruku mojih vidje.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 18, 26, 'S prijateljem ti si prijatelj, poštenu poštenjem uzvraćaš.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 18, 27, 'S čovjekom čistim ti si čist, a lukavca izigravaš,');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 18, 28, 'jer narodu poniženu spasenje donosiš, a ponižavaš oči ohole.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 18, 29, 'Jahve, ti moju svjetiljku užižeš, Bože, tminu moju obasjavaš:');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 18, 30, 's tobom udaram na čete dušmanske, s Bogom svojim preskačem zidine.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 18, 31, 'Savršeni su puti Gospodnji, i riječ je Božja ognjem kušana. On, samo on, štit je svima koji se k njemu utječu.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 18, 32, 'Jer tko je Bog osim Jahve? Tko li je hridina osim Boga našega?');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 18, 33, 'Taj Bog me snagom opasuje, stere mi put besprijekoran,');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 18, 34, 'noge mi dade brze k\'o u košute i postavi me na visine čvrste,');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 18, 35, 'ruke mi za borbu uvježba i mišice da luk mjedeni napinju.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 18, 36, 'Daješ mi štit svoj koji spasava, tvoja me desnica drži, tvoja me brižljivost uzvisi.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 18, 37, 'Pouzdanje daješ mom koraku, i noge mi više ne posrću.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 18, 38, 'Pognah svoje dušmane i dostigoh, i ne vratih se dok ih ne uništih.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 18, 39, 'Obaram ih, ne mogu se dići, padaju, pod nogama mi leže.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 18, 40, 'Ti me opasa snagom za borbu, a protivnike moje meni podloži.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 18, 41, 'Ti dušmane moje u bijeg natjera, i rasprših one koji su me mrzili.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 18, 42, 'Vapiju u pomoć - nikog da pomogne; vapiju Jahvi - ne odaziva se.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 18, 43, 'Smrvih ih kao prah na vjetru, zgazih ih k\'o blato na putu.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 18, 44, 'Ti me izbavi od bune u mom narodu, postavi me glavarom pogana, puk koji ne poznavah služi mi.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 18, 45, 'Svaki moj šapat pokorno on sluša, sinovi tuđinci meni laskaju;');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 18, 46, 'sinovi tuđinski gube srčanost, izlaze dršćuć\' iz svojih utvrda.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 18, 47, 'Živio Jahve! Blagoslovljena hridina moja! Neka se uzvisi Bog, spasenje moje!');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 18, 48, 'Bog koji mi daje osvetu i narode meni pokorava.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 18, 49, 'Od dušmana me mojih izbavljaš i nad protivnike me moje izdižeš, ti mene od čovjeka silnika spasavaš.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 18, 50, 'Zato te slavim, Jahve, među pucima i psalam pjevam tvome Imenu:');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 18, 51, 'umnožio si pobjede kralju svojemu, pomazaniku svome milost si iskazao, Davidu i potomstvu njegovu navijeke.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 19, 1, 'Zborovođi. Psalam. Davidov.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 19, 2, 'Nebesa slavu Božju kazuju, naviješta svod nebeski djelo ruku njegovih.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 19, 3, 'Dan danu to objavljuje, a noć noći glas predaje.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 19, 4, 'Nije to riječ, a ni govor nije, nije ni glas što se može čuti,');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 19, 5, 'al\' po zemlji razliježe se jeka, riječi sve do nakraj svijeta sežu. Ondje suncu razape šator,');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 19, 6, 'te ono k\'o ženik iz ložnice ide, k\'o div kliče kad prelijeće stazu.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 19, 7, 'Izlazi ono od nebeskog kraja, i put mu se opet s krajem spaja, ne skriva se ništa žaru njegovu.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 19, 8, 'Savršen je Zakon Jahvin - dušu krijepi; pouzdano je Svjedočanstvo Jahvino - neuka uči;');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 19, 9, 'prÓava je naredba Jahvina - srce sladi; čista je zapovijed Jahvina - oči prosvjetljuje;');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 19, 10, 'neokaljan strah Jahvin - ostaje svagda; istiniti sudovi Jahvini - svi jednako pravedni,');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 19, 11, 'dragocjeniji od zlata, od zlata čistoga, slađi od meda, meda samotoka.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 19, 12, 'Sluga tvoj pomno na njih pazi, vrlo brižno on ih čuva.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 19, 13, 'Ali tko propuste svoje da zapazi? Od potajnih grijeha očisti me!');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 19, 14, 'Od oholosti čuvaj slugu svoga da mnome ne zavlada. Tad ću biti neokaljan, čist od grijeha velikoga.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 19, 15, 'Moje ti riječi omiljele i razmišljanje srca moga pred licem tvojim. Jahve, hridi moja, otkupitelju moj!');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 20, 1, 'Zborovođi. Psalam. Davidov.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 20, 2, 'Uslišio te Jahve u dan nevolje, štitilo te ime Boga Jakovljeva!');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 20, 3, 'Poslao ti pomoć iz Svetišta, branio te sa Siona!');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 20, 4, 'Spomenuo se svih ti prinosnica, bila mu mila paljenica tvoja!');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 20, 5, 'Udijelio ti što ti srce želi, ispunio sve namisli tvoje!');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 20, 6, 'Radovali se tvojoj pobjedi, u ime Boga svoga dizali stjegove! Ispunio Jahve svaku molbu tvoju!');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 20, 7, 'Znam evo: Jahve će pobjedu dati svom pomazaniku, uslišit ga iz svetih nebesa snagom pobjedne desnice svoje.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 20, 8, 'Jedni se hvale kolima bojnim, drugi konjima, mi imenom Jahve, Boga našega!');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 20, 9, 'Oni posrću i padaju, mi se držimo i stojimo.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 20, 10, 'Jahve, daruj pobjedu kralju, usliši nas u dan kad te zazovemo!');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 21, 1, 'Zborovođi. Psalam. Davidov.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 21, 2, 'Jahve, zbog tvoje se moći kralj veseli, zbog pomoći tvoje radosno kliče.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 21, 3, 'Ti mu ispuni želju srca, ne odbi molitve usana njegovih.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 21, 4, 'Ti ga predusrete blagoslovima sretnim, na glavu mu krunu stavi od suhoga zlata.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 21, 5, 'Za život te molio, i ti mu dade premnoge dane - za vijeke vjekova.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 21, 6, 'Pomoću tvojom slava je njegova velika, uresio si ga veličanstvom i sjajem.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 21, 7, 'Ti ga učini blagoslovom za vjekove, veseliš ga radošću lica svojega.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 21, 8, 'Doista, kralj se uzda u Jahvu i po dobroti Svevišnjega neće se pokolebati.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 21, 9, 'Tvoja ruka nek\' pronađe sve dušmane tvoje, desnica tvoja neka stigne one koji te mrze!');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 21, 10, 'Nek\' budu kao u peći ognjenoj kad se ukaže lice tvoje! Nek\' ih Jahve gnjevom uništi, neka ih proguta oganj!');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 21, 11, 'Njihovo potomstvo satri sa zemlje i rod im iz sinova ljudskih.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 21, 12, 'Ako li stanu zlo kovati protiv tebe, ako spremaju spletke, neće uspjeti.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 21, 13, 'Ti ćeš ih natjerati u bijeg, svoj luk ćeš usmjeriti na njih.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 21, 14, 'Ustani, Jahve, u sili svojoj! Daj nam da pjesmama slavimo snagu tvoju!');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 22, 1, 'Zborovođi. Po napjevu \"Košuta u zoru\". Psalam. Davidov.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 22, 2, 'Bože moj, Bože moj, zašto si me ostavio? Daleko si od ridanja moga.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 22, 3, 'Bože moj, vičem danju, al\'ne odvraćaš; noću vapijem i nema mi počinka.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 22, 4, 'A ipak, ti u Svetištu prebivaš, Nado Izraelova!');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 22, 5, 'U tebe se očevi naši uzdaše, uzdaše se, i ti ih izbavi;');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 22, 6, 'k tebi su vikali i spasavali se, u tebe se uzdali, i postidjeli se nisu.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 22, 7, 'A ja, crv sam, a ne čovjek, ruglo ljudi i naroda prezir.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 22, 8, 'Koji me vode, podruguju se meni, razvlače usne, mašu glavom:');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 22, 9, '\"U Jahvu se on uzda, neka ga sad izbavi, neka ga spasi ako mu omilje!\"');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 22, 10, 'Iz krila majčina ti si me izveo, mir mi dao na grudima majke.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 22, 11, 'Tebi sam predan iz materine utrobe, od krila majčina ti si Bog moj.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 22, 12, 'Ne udaljuj se od mene, blizu je nevolja, a nikog nema da mi pomogne.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 22, 13, 'Opkoliše me junci mnogobrojni, bašanski bikovi okružiše mene.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 22, 14, 'Ždrijela svoja razvaljuju na me k\'o lav koji plijen kida i riče.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 22, 15, 'Kao voda razlih se, sve mi se kosti rasuše; srce mi posta poput voska, topi se u grudima mojim.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 22, 16, 'Grlo je moje kao crijep suho, i moj se jezik uz nepce slijepi: u prah smrtni bacio si mene.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 22, 17, 'Opkolio me čopor pasa, rulje me zločinačke okružile. Probodoše mi ruke i noge,');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 22, 18, 'sve kosti svoje prebrojiti mogu, a oni me gledaju i zure na me.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 22, 19, 'Haljine moje dijele među sobom i kocku bacaju za odjeću moju.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 22, 20, 'Ali ti, o Jahve, daleko mi ne budi; snago moja, pohiti mi u pomoć!');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 22, 21, 'Dušu moju istrgni maču, iz šapa pasjih život moj.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 22, 22, 'Spasi me iz ralja lavljih i jadnu mi dušu od rogova bivoljih!');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 22, 23, 'A sada, braći ću svojoj naviještat\' ime tvoje, hvalit ću te usred zbora.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 22, 24, '\"Koji se bojite Jahve, hvalite njega! Svi od roda Jakovljeva, slavite njega! Svi potomci Izraelovi, njega se bojte!');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 22, 25, 'Jer nije prezreo ni zaboravio muku jadnika, i nije sakrio lice svoje od njega; kad ga je zazvao, on ga je čuo.\"');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 22, 26, 'Zato ću te hvaliti u zboru veliku, pred vjernicima tvojim izvršit\' zavjete.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 22, 27, 'Siromasi će jesti i nasitit će se, hvalit će Jahvu koji traže njega: nek\' živi srce vaše dovijeka!');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 22, 28, 'Spomenut će se i Jahvi se vratit\' svi krajevi zemlje; pred njim će n§icÄe pasti sve obitelji pogana.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 22, 29, 'Jer Jahvino je kraljevstvo, on je vladar pucima.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 22, 30, 'Njemu će se jedinom klanjati svi koji snivaju u zemlji, pred njim se sagnuti svi koji u prah silaze. I moja će duša za njega živjeti,');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 22, 31, 'njemu će služiti potomstvo moje. O Gospodu će se pripovijedat\'');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 22, 32, 'slijedećem koljenu, o njegovoj pravdi naviještati narodu budućem: \"Ovo učini Jahve!\"');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 23, 1, 'Psalam. Davidov. Jahve je pastir moj: ni u čem ja ne oskudijevam;');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 23, 2, 'na poljanama zelenim on mi daje odmora. Na vrutke me tihane vodi');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 23, 3, 'i krijepi dušu moju. Stazama pravim on me upravlja radi imena svojega.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 23, 4, 'Pa da mi je i dolinom smrti proći, zla se ne bojim, jer si ti sa mnom. Tvoj štap i palica tvoja utjeha su meni.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 23, 5, 'Trpezu preda mnom prostireš na oči dušmanima mojim. Uljem mi glavu mažeš, čaša se moja prelijeva.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 23, 6, 'Dobrota i milost pratit će mene sve dane života moga. U Jahvinu ću domu prebivati kroz dane mnoge.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 24, 1, 'Psalam. Davidov. Jahvina je zemlja i sve na njoj, svijet i svi koji na njemu žive.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 24, 2, 'On ga na morima utemelji i na rijekama učvrsti.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 24, 3, 'Tko će uzići na Goru Jahvinu, tko će stajati na svetom mjestu njegovu?');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 24, 4, 'Onaj u koga su ruke čiste i srce nedužno: duša mu se ne predaje ispraznosti, i ne kune se varavo.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 24, 5, 'On blagoslov prima od Jahve i nagradu od Boga, Spasitelja svoga.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 24, 6, 'Takav je naraštaj onih koji traže njega, koji traže lice Boga Jakovljeva.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 24, 7, '\"Podignite, vrata, nadvratnike svoje, dižite se, dveri vječne, da uniđe Kralj slave!\"');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 24, 8, '\"Tko je taj Kralj slave?\" \"Jahve silan i junačan, Jahve silan u boju!\"');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 24, 9, '\"Podignite, vrata, nadvratnike svoje dižite se, dveri vječne, da uniđe Kralj slave!\"');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 24, 10, '\"Tko je taj Kralj slave?\" \"Jahve nad Vojskama - on je Kralj slave!\"');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 25, 1, 'Davidov. $ALEF K tebi, Jahve, uzdižem dušu svoju,');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 25, 2, '$BET u tebe se uzdam, Bože moj: ne daj da se postidim, da se ne vesele nada mnom dušmani!');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 25, 3, '$GIMEL Koji se u tebe uzdaju, postidjet se neće: postidjet će se koji se lako iznevjere.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 25, 4, '$DALET Pokaži mi, Jahve, svoje putove, nauči me svojim stazama!');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 25, 5, '$HE Istinom me svojom vodi i pouči me, jer ti si Bog, moj Spasitelj: $VAU u tebe se pouzdajem svagda.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 25, 6, '$ZAJIN Spomeni se, Jahve, svoje nježnosti i ljubavi svoje dovijeka.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 25, 7, '$HET Ne spominji se grijeha moje mladosti ni prijestupa, spomeni me se po svojoj ljubavi - radi dobrote svoje, o Jahve!');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 25, 8, '$TET Jahve je sama dobrota i pravednost: grešnike on na put privodi.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 25, 9, '$JOD On ponizne u pravdi vodi i uči malene putu svome.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 25, 10, '$KAF Sve su staze Jahvine istina i ljubav za onog koji čuva Savez njegov i propise.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 25, 11, '$LAMED Jahve, radi svojeg imena grijeh moj mi oprosti, jer je velik.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 25, 12, '$MEM Ima li koga da se boji Jahve? On će ga poučiti kojim će putem krenuti.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 25, 13, '$NUN Duša će mu u sreći počivati, a potomci će njegovi zaposjesti zemlju.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 25, 14, '$SAMEK Prisan je Jahve s onima koji ga se boje i Savez svoj objavljuje njima.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 25, 15, '$AJIN K Jahvi su svagda oči moje upravljene, jer mi nogu izvlači iz zamke.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 25, 16, '$PE Pogledaj na me i smiluj se meni, jer osamljen sam i nevoljan.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 25, 17, '$SADE Odagnaj tjeskobe srca moga, iz bojazni mojih izbavi me!');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 25, 18, 'Vidi nevolju moju i muku i oprosti sve grijehe moje!');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 25, 19, '$REŠ Pogledaj dušmane moje: kako ih je mnogo i kakvom me mržnjom žestokom mrze.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 25, 20, '$ŠIN Čuvaj dušu moju, izbavi me: neću se postidjeti, jer se tebi utekoh.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 25, 21, '$TAU Nedužnost i čestitost nek\' me štite, jer u tebe se uzdam, o Jahve.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 25, 22, 'Izbavi, Bože, Izraela iz sviju tjeskoba njegovih.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 26, 1, 'Davidov. Dosudi mi pravo, Jahve, jer hodih u nedužnosti, i uzdajuć\' se u Jahvu ja se ne pokolebah.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 26, 2, 'Ispitaj me, Jahve, iskušaj me, istraži mi bubrege i srce.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 26, 3, 'Jer tvoja je dobrota pred očima mojim, u istini tvojoj ja hodim.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 26, 4, 'S ljudima opakim ja ne sjedim i ne svraćam podlima.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 26, 5, 'Mrsko mi je društvo zlotvora, i s bezbošcima sjesti ne želim.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 26, 6, 'U nedužnosti ruke svoje perem i obilazim žrtvenik tvoj, Jahve,');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 26, 7, 'da tvoju hvalu javno razglasim i pripovijedam sva divna djela tvoja.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 26, 8, 'O Jahve, ljubim dom u kojem prebivaš i mjesto gdje slava tvoja stoluje.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 26, 9, 'Ne pogubi mi dušu s grešnicima ni život moj s krvolocima;');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 26, 10, 'na rukama je njihovim zločin, a desnica im puna mita.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 26, 11, 'A ja u nedužnosti svojoj hodim: izbavi me, milostiv mi budi.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 26, 12, 'Noga mi stoji na pravu putu: u zborovima blagoslivljat ću Jahvu.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 27, 1, 'Davidov. Jahve mi je svjetlost i spasenje: koga da se bojim? Jahve je štit života moga: pred kime da strepim?');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 27, 2, 'Kad navale na me zlotvori da mi tijelo žderu, protivnici moji i dušmani, oni posrću i padaju.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 27, 3, 'Nek\' se vojska protiv mene utabori, srce se moje ne boji; nek\' i rat plane protiv mene, i tada pun sam pouzdanja.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 27, 4, 'Za jedno molim Jahvu, samo to ja tražim: da živim u Domu Jahvinu sve dane života svoga, da uživam milinu Jahvinu i Dom njegov gledam.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 27, 5, 'U sjenici svojoj on me zaklanja u dan kobni; skriva me u skrovištu Šatora svoga, na hridinu on me uzdiže.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 27, 6, 'I sada izdižem glavu iznad dušmana oko sebe. U njegovu ću Šatoru prinositi žrtve radosne, Jahvi ću pjevat\' i klicati.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 27, 7, 'Slušaj, o Jahve, glas moga vapaja, milostiv mi budi, usliši me!');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 27, 8, 'Moje mi srce govori: \"Traži lice njegovo!\" Da, lice tvoje, o Jahve, ja tražim.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 27, 9, 'Ne skrivaj lica svoga od mene. Ne odbij u gnjevu slugu svoga! Ti, Pomoći moja, nemoj me odbaciti! I ne ostavi me, Bože, Spasitelju moj!');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 27, 10, 'Ako me otac i mati ostave, Jahve će me primiti.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 27, 11, 'Nauči me, Jahve, putu svojemu, ravnom me stazom povedi poradi protivnika mojih.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 27, 12, 'Bijesu dušmana mojih ne predaj me, jer ustadoše na mene svjedoci lažni koji dašću nasiljem.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 27, 13, 'Vjerujem da ću uživati dobra Jahvina u zemlji živih.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 27, 14, 'U Jahvu se uzdaj, ojunači se, čvrsto nek\' bude srce tvoje: u Jahvu se uzdaj!');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 28, 1, 'Davidov. K tebi, o Jahve, vapijem, hridino moja, ne ogluši se na me: da neuslišan ne postanem kao oni koji u grob silaze.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 28, 2, 'Čuj moje zazivanje dok tebi vapijem, dok ruke uzdižem svetomu Hramu tvojem.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 28, 3, 'Ne uzmi me s bezbožnicima i s onima koji čine bezakonje, koji govore slatko s bližnjima a u srcu im je pakost.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 28, 4, 'Daj im po djelima njihovim i po zloći njihovih nedjela! Po djelu ruku njihovih plati im, uzvrati im po njihovoj zasluzi!');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 28, 5, 'Jer ne mare za čine Jahvine ni za djelo ruku njegovih: nek\' ih obori i više ne podigne!');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 28, 6, 'Blagoslovljen Jahve što usliša zazivanje moje! Jahve mi je zaklon, on štit je moj.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 28, 7, 'U njega se srce moje pouzdalo i pomoć mi dođe; zato mi kliče srce i pjesmom njega slavim.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 28, 8, 'Jahve je jakost narodu svome, tvrđava spasa svom pomazaniku.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 28, 9, 'Spasi narod svoj i blagoslovi svoju baštinu, pasi ih i nosi ih dovijeka!');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 29, 1, 'Psalam. Davidov. Prinesite Jahvi, o sinovi Božji, prinesite Jahvi slavu i moć!');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 29, 2, 'Prinesite Jahvi slavu njegova imena, poklonite se Jahvi u svetištu njegovu!');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 29, 3, 'Čuj! Jahve nad vodama, Jahve nad vodama silnim!');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 29, 4, 'Čuj! Jahve u sili, Jahve u veličanstvu!');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 29, 5, 'Čuj! Jahve lomi cedre, Jahve lomi cedre libanske,');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 29, 6, 'i Liban skakuće poput teleta, a Sirion kao mlado bivolče!');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 29, 7, 'Čuj! Jahve sipa munje, Jahve sipa munje ognjene!');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 29, 8, 'Čuj! Jahve potresa pustinjom, Jahve potresa pustinjom kadeškom!');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 29, 9, 'Čuj! Od straha se mladÄe košute, prerano se mladÄe košute šumske. [3b] Čuj! Bog veličanstveni zagrmje, [9a] a u Hramu njegovu svi kliknuše: Slava!');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 29, 10, 'Jahve nad valima stoluje, stoluje Jahve - kralj dovijeka!');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 29, 11, 'Jahve narodu svom daje jakost, Jahve narod svoj mirom blagoslivlje.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 30, 1, 'Psalam. Pjesma za posvećenje Doma. Davidov.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 30, 2, 'Veličam te, Jahve, jer si me izbavio i nisi dao da se raduju nada mnom dušmani.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 30, 3, 'Jahve, Bože moj, zazvah te, i ti si me ozdravio;');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 30, 4, 'Jahve, izveo si mi dušu iz Podzemlja, na rubu groba ti si me oživio.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 30, 5, 'Pjevajte Jahvi, vjernici njegovi, zahvaljujte svetom imenu njegovu!');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 30, 6, 'Jer samo za tren traje srdžba njegova, a čitav život dobrota njegova. Večer donese suze, a jutro klicanje.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 30, 7, 'U svojoj sreći rekoh: \"Neću se pokolebati nikada!\"');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 30, 8, 'Dobrotom si me, o Jahve, na goru nade postavio, ali čim lice sakriješ, sav se uplašim.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 30, 9, 'Tada, Jahve, zavapih k tebi i zazvah milosrđe Boga svojega:');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 30, 10, '\"Kakva je korist od krvi moje, kakva korist da u grob siđem? Zar će te prašina slaviti, zar će naviještati vjernost tvoju?\"');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 30, 11, 'Slušaj, o Jahve, i smiluj se meni; Jahve, budi mi na pomoć!');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 30, 12, 'Okrenuo si moj plač u igranje, skinuo kostrijet s mene i opasao me radošću.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 30, 13, 'Zato ti pjeva duša moja i neće zamuknuti: Jahve, Bože moj, dovijeka ću te hvaliti!');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 31, 1, 'Zborovođi. Psalam. Davidov.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 31, 2, 'Tebi se, Jahve, utječem, o, da se ne postidim nikada: u svojoj me pravdi izbavi!');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 31, 3, 'Prikloni k meni uho svoje, pohiti da me oslobodiš! Budi mi hrid zaštite, tvrđava spasenja.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 31, 4, 'Jer ti si hrid moja, tvđava moja, radi svoga imena vodi me i ravnaj.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 31, 5, 'Izvuci me iz mreže koju mi zapeše, jer ti si moje utočište.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 31, 6, 'U tvoje ruke duh svoj predajem: otkupi me, Jahve, Bože vjerni.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 31, 7, 'Ti mrziš one koji štuju ništavne kumire, a ja se u Jahvu uzdam.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 31, 8, 'Radosno ću klicat\' tvojoj milosti, jer si na moju bijedu pogledao, pomogao u tjeskobi duši mojoj.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 31, 9, 'Nisi me predao u ruke dušmana, noge si mi na prostran put izveo.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 31, 10, 'Smiluj mi se, Jahve, jer sam u tjeskobi, od jada slabi mi oko, duša i tijelo.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 31, 11, 'Život mi se troši u gorčini, ljeta moja u jecanju. U muci mi se iscrpila snaga i kosti su moje klonule.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 31, 12, 'Dušmanima svojim postao sam ruglo, susjedima podsmijeh, a znancima strašilo; koji me vide vani, bježe od mene.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 31, 13, 'Nestalo me k\'o mrtvaca iz sjećanja ljudi, postadoh k\'o razbijena posuda.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 31, 14, 'Čujem šaputanje mnogih, užas odasvud: sastaju se protiv mene i smišljaju kako da mi život oduzmu.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 31, 15, 'A ja se, Jahve, u tebe uzdam; govorim: Ti si Bog moj!');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 31, 16, 'U tvojoj je ruci sudbina moja: istrgni me iz ruke dušmana i onih koji me progone!');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 31, 17, 'Rasvijetli lice nad slugom svojim, po svojoj me dobroti spasi.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 31, 18, 'Jahve, ne bilo me stid što tebe zazvah! Neka se postide zlotvori, nek\' u Podzemlju zamuknu.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 31, 19, 'Nek\' zanijeme usne lažljive koje protiv pravednika govore drsko, oholo i prezirno.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 31, 20, 'O, kako je velika, Jahve, tvoja dobrota, koju čuvaš za one koji te se boje, koju iskazuješ onima što se tebi utječu naočigled sinovima čovječjim.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 31, 21, 'Zaklanjaš ih štitom lica svoga od zavjera ljudskih; u šatoru svom ih skrivaš od jezika svadljivih.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 31, 22, 'Blagoslovljen Jahve jer me obasu čudesnom dobrotom u gradu tvrdom.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 31, 23, 'U tjeskobi svojoj već mišljah: \"Odbačen sam od pogleda tvoga.\" Ali ti si čuo glas mog zaziva dok sam tebi vapio.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 31, 24, 'Ljubite Jahvu, svi sveti njegovi: čuva Jahve svoje vjernike, a po zasluzi vraća onima koji postupaju oholo.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 31, 25, 'Budite hrabri i jaka srca, svi koji se u Jahvu uzdate!');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 32, 1, 'Davidov. Poučna pjesma. Blažen onaj kome je grijeh otpušten, kome je zločin pokriven!');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 32, 2, 'Blago čovjeku kome Jahve ne ubraja krivnju i u čijemu duhu nema prijevare!');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 32, 3, 'Prešutjet\' sam htio, al\' kosti mi klonuše od neprestana jecanja.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 32, 4, 'Danju i noću ruka me tvoja tištala, snaga mi se trošila k\'o za ljetnih žega.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 32, 5, 'Tad grijeh svoj tebi priznah i krivnju svoju više ne skrivah. Rekoh: \"Priznat ću Jahvi prijestup svoj\", i ti si mi krivnju grijeha oprostio.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 32, 6, 'Zato nek\' ti se moli pobožnik svaki u času nevolje. Kad bujice silne navale, njega neće stići.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 32, 7, 'Utočište ti si moje, od tjeskobe ti ćeš me sačuvat\', odjenut\' me radošću spasenja.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 32, 8, 'Učit ću te, put ti kazat\' kojim ti je ići, svjetovat ću te, oko će moje bdjeti nad tobom.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 32, 9, 'Ne budite kao konj ili mazga bez razuma: divljinu im krotiš vođicama i uzdom, inače im se ne primiči!');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 32, 10, 'Bezbožnika taru mnoge nevolje, a tko se uzda u Jahvu, njega okružuje milost.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 32, 11, 'Radujte se Jahvi i kličite, pravedni, kličite svi koji ste srca čestita!');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 33, 1, 'Pravednici, Jahvi kličite! Hvaliti ga pristoji se čestitima.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 33, 2, 'Slavite Jahvu na harfi, na liri od deset žica veličajte njega!');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 33, 3, 'Pjesmu novu zapjevajte njemu i glazbala skladna popratite poklicima.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 33, 4, 'Jer prÓava je riječ Jahvina i vjernost su sva djela njegova.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 33, 5, 'On ljubi pravdu i pravo: puna je zemlja dobrote Jahvine.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 33, 6, 'Jahvinom su riječju nebesa sazdana i dahom usta njegovih sva vojska njihova.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 33, 7, 'Vodu morsku on sabire kao u mješinu i bezdane stavlja u spremišta.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 33, 8, 'Zemlja sva neka pred Jahvom strepi, neka ga se boje svi stanovnici svijeta!');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 33, 9, 'Jer on reče - i sve postade, naredi - i sve se stvori.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 33, 10, 'Jahve razbija nakane pucima, mrsi namjere narodima.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 33, 11, 'Naum Jahvin dovijeka ostaje i misli srca njegova od koljena do koljena.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 33, 12, 'Blago narodu kojemu je Jahve Bog, Narodu koji on odabra sebi za baštinu!');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 33, 13, 'Gospodin motri s nebesa i gleda sve sinove čovječje.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 33, 14, 'Iz svoga prebivališta motri sve stanovnike zemaljske:');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 33, 15, 'on je svima srca stvorio i pazi na sva djela njihova.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 33, 16, 'Ne spasava kralja vojska mnogobrojna, ne spasava velika sila junaka.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 33, 17, 'Isprazno se od konja nadati spasenju, jačina njegova ne izbavlja.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 33, 18, 'Oko je Jahvino nad onima koji ga se boje, nad onima koji se uzdaju u milost njegovu:');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 33, 19, 'da im od smrti život spasi, da ih hrani u danima gladi.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 33, 20, 'Naša se duša Jahvi nada, on je pomoć i zaštita naša.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 33, 21, 'Srce nam se u njemu raduje, u njegovo sveto ime mi se uzdamo.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 33, 22, 'Neka dobrota tvoja, o Jahve, bude nad nama, kao što se mi u tebe uzdamo!');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 34, 1, 'Davidov. Kada se David pravio ludim pred Abimelekom, a on');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 34, 2, '$ALEF Blagoslivljat ću Jahvu u svako doba, njegova će mi hvala biti svagda na ustima!');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 34, 3, '$BET Nek\' se Jahvom duša moja hvali: nek\' čuju ponizni i nek\' se raduju!');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 34, 4, '$GIMEL Veličajte sa mnom Jahvu, uzvisujmo ime njegovo zajedno!');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 34, 5, '$DALETTražio sam Jahvu, i on me usliša, izbavi me od straha svakoga.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 34, 6, '$HE U njega gledajte i razveselite se, da se ne postide lica vaša.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 34, 7, '$ZAJIN Eto, jadnik vapi, a Jahve ga čuje, izbavlja ga iz svih tjeskoba.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 34, 8, '$HET Anđeo Jahvin tabor podiže oko njegovih štovalaca da ih spasi.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 34, 9, '$TET Kušajte i vidite kako dobar je Jahve: blago čovjeku koji se njemu utječe!');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 34, 10, '$JOD Bojte se Jahve, vi sveti njegovi: ne trpe oskudice koji ga se boje.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 34, 11, '$KAF Osiromašiše mogućnici i gladuju, a koji traže Jahvu ne trpe oskudice.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 34, 12, '$LAMED Dođite, djeco, i poslušajte me, učit ću vas strahu Gospodnjem.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 34, 13, '$MEM O čovječe, ljubiš li život? Želiš li dane mnoge uživati dobra?');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 34, 14, '$NUN Jezik svoj oda zla suspreži i usne od riječi prijevarnih!');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 34, 15, '$SAMEK Zla se kloni, a čini dobro, traži mir i za njim idi!');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 34, 16, '$PE Oči Jahvine gledaju pravedne, uši mu slušaju vapaje njihove.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 34, 17, '$AJIN Lice se Jahvino okreće protiv zločinaca da im spomen zatre na zemlji.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 34, 18, '$SADE Pravednici zazivaju, i Jahve ih čuje, izbavlja ih iz svih tjeskoba.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 34, 19, '$KOF Blizu je Jahve onima koji su skršena srca, a klonule duše spasava.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 34, 20, '$REŠ Mnoge nevolje ima pravednik, ali ga Jahve od svih izbavlja.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 34, 21, '$ŠIN On čuva sve kosti njegove: ni jedna mu se neće slomiti.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 34, 22, '$TAU Opakost bezbošca ubija, platit će koji mrze pravednika.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 34, 23, 'Jahve izbavlja duše slugu svojih, i neće platiti tko god se njemu utječe.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 35, 1, 'Davidov. Optuži, Jahve, tužitelje moje i napadni one koji mene napadaju!');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 35, 2, 'Stavi oklop, uzmi štit svoj i ustani meni u pomoć!');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 35, 3, 'Zavitlaj kopljem i presretni progonitelje moje, reci mojoj duši: \"Ja sam tvoje spasenje.\"');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 35, 4, 'Nek\' se smetu i postide koji život moj traže, nek\' uzmaknu i nek\' se posrame koji mi propast snuju!');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 35, 5, 'Nek\' budu k\'o pljeva na vjetru kad ih Anđeo Jahvin potjera!');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 35, 6, 'Mračni i skliski bili im putovi kad ih Anđeo Jahvin bude gonio!');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 35, 7, 'Bez razloga napeše mi mrežu, bez razloga grob duši mojoj iskopaše.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 35, 8, 'Propast će ih stići iznenada, u mrežu koju napeše sami će se uhvatiti, past će u jamu što je iskopaše!');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 35, 9, 'A moja će duše klicati u Jahvi, radovat će se u spasenju njegovu.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 35, 10, 'Sve će kosti moje govoriti: Tko je, Jahve, poput tebe koji ubogog spasavaš od silnika, jadnika i siromaha od pljačkaša?');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 35, 11, 'Ustadoše svjedoci opaki: pitaju me za ono što ne znam.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 35, 12, 'Vraćaju mi zlo za dobro, duša moja zapada u osamu.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 35, 13, 'U bolesti njihovoj nosio sam kostrijet, dušu svoju postom morio, i molitva mi se u krilo vraćala.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 35, 14, 'Kao za prijateljem, za bratom - obilažah tužan; od žalosti se pogurih kao onaj što za majkom žali.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 35, 15, 'A sada kad posrnuh ja, oni se raduju, skupiše se protiv mene da udare iznenada, i bez prestanka oni me razdiru.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 35, 16, 'Ruglom na ruglo iskušavaju me i zubima škripaju na mene.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 35, 17, 'O Jahve, dokle ćeš gledati? Istrgni mi dušu nasrtajima njihovim, otmi lavovima jedino dobro moje!');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 35, 18, 'Zahvalit ću ti u velikom zboru, slavit ću te među pukom brojnim.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 35, 19, 'Nek\' se ne raduju nada mnom dušmani nepravedni, nek\' ne namiguju očima oni koji me nizašto mrze!');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 35, 20, 'Jer oni ne misle o miru, već spletke snuju protiv mirnih u zemlji.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 35, 21, 'Razvaljuju svoja usta na me i govore: \"Ha, ha, vidjesmo očima svojim!\"');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 35, 22, 'Ti sve vidiš, o Jahve! Nemoj šutjeti! Gospode, od mene se ne udaljuj!');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 35, 23, 'Preni se, ustani da me obraniš, Bože moj, Gospode, vodi parnicu moju!');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 35, 24, 'Po svojoj me pravdi sudi, Jahve, Bože moj, nek\' se ne raduju nada mnom!');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 35, 25, 'Nek\' ne misle u srcu: \"Ispunila nam se želja!\" Nek\' ne reknu: \"Progutali smo ga!\"');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 35, 26, 'Nek\' se postide i posrame svi zajedno koji se nesreći mojoj raduju! Nek\' se odjenu stidom i sramotom oni koji se podižu na me!');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 35, 27, 'Nek\' radosno kliču kojima je pravo moje na srcu i nek\' svagda govore: \"Velik je Jahve! Milo mu je spasenje sluge njegova!\"');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 35, 28, 'A moj će jezik kazivati pravdu tvoju i hvalu tebi navijeke.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 36, 1, 'Zborovođi. Od sluge Jahvina Davida.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 36, 2, 'Grešan je naum u srcu zlotvora, straha Božjega nema on pred očima.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 36, 3, 'Sam sebi on laska suviše, grijeha svog ne vidi i ne mrzi.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 36, 4, 'Riječi usta njegovih prijevara su i zlodjelo, za razumnost i dobro on više ne mari.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 36, 5, 'Bezakonje smišlja na postelji svojoj, na opaku ostaje putu, od zla ne odustaje.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 36, 6, 'Do neba je, Jahve, dobrota tvoja, do oblaka vjernost tvoja.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 36, 7, 'Pravednost je tvoja k\'o Božji vrhunci, a sudovi tvoji k\'o duboko more: ljude i stoku ti, Jahve, spasavaš.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 36, 8, 'Kako li je dragocjena, Bože, dobrota tvoja, pod sjenu krila tvojih ljudi se sklanjaju;');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 36, 9, 'site se pretilinom Doma tvojega, potocima svojih slasti ti ih napajaš.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 36, 10, 'U tebi je izvor životni, tvojom svjetlošću mi svjetlost vidimo.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 36, 11, 'Zakrili dobrotom sve koji te štuju i pravednošću svojom sve koji su srca čestita.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 36, 12, 'Neka me ne zgazi noga ohola, i ruka grešnika neka me ne goni.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 36, 13, 'Gle, padoše koji čine bezakonje: oboreni su da više ne ustanu.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 37, 1, 'Davidov. $ALEF Nemoj se žestiti na opake, zavidjet nemoj pakosnicima:');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 37, 2, 'kao trava brzo se osuše, k\'o mlada zelen brzo uvenu.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 37, 3, '$BET U Jahvu se uzdaj i čini dobro, da smiješ stanovati u zemlji i živjeti u miru.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 37, 4, 'Sva radost tvoja neka bude Jahve: on će ispuniti želje tvoga srca!');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 37, 5, '$GIMEL Prepusti Jahvi putove svoje, u njega se uzdaj i on će sve voditi.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 37, 6, 'Pravda će tvoja zasjati k\'o svjetlost i tvoje pravo k\'o sunce podnevno.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 37, 7, '$DALET Smiri se pred Jahvom i njemu se nadaj, ne žesti se na onog koji ima sreće, na čovjeka koji spletke kuje.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 37, 8, '$HE Stišaj svoj gnjev i ostavi se srdžbe, ne žesti se da zlo ne učiniš.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 37, 9, 'Jer će biti satrti zlikovci, a koji se u Jahvu uzdaju, baštinit će zemlju.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 37, 10, '$VAU Još malo i nestat će bezbožnika: mjesto ćeš njegovo tražiti, a njega više nema.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 37, 11, 'Zemlju će posjedovati krotki, obilje mira oni će uživat\'.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 37, 12, '$ZAJIN Bezbožnik smišlja zlo pravedniku i zubima škrguće na njega.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 37, 13, 'A Gospod se njemu smije jer vidi da dan njegov dolazi.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 37, 14, '$HET Mač potežu bezbošci i zapinju lukove da obore jadnika i siromaha, da pokolju one koji hode pravim putem.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 37, 15, 'Mačem će vlastito srce probiti, slomit će se njihovi lukovi.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 37, 16, '$TET Bolje je i malo u pravednika no golemo blago u zlotvora:');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 37, 17, 'jer će se ruke zlotvora slomiti, a Jahve je oslon pravedniku.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 37, 18, '$JOD Jahve se brine za život čestitih, dovijeka će trajati baština njihova.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 37, 19, 'Neće se postidjeti u vrijeme nevolje, bit će siti u danima gladi.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 37, 20, '$KAF A bezbožnici će propasti, dušmani Jahvini povenut će k\'o ures livada, poput dima se rasplinuti.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 37, 21, '$LAMED Bezbožnik zaima, ali ne vraća, pravednik se sažaljeva i daje.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 37, 22, 'Oni koje Jahve blagoslovi baštinit će zemlju, a koje prokune bit će zatrti.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 37, 23, '$MEM Jahve vodi i učvršćuje korake čovjeku i mio mu je put njegov.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 37, 24, 'Ako i posrne, ne pada jer ga Jahve drži za ruku.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 37, 25, '$NUN Mlad bijah i ostarjeh, al\' ne vidjeh pravednika napuštena ili da mu djeca kruha prose.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 37, 26, 'Uvijek je milosrdan i u zajam daje, na njegovu je potomstvu blagoslov.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 37, 27, '$SAMEK Zla se kloni i čini dobro, i ostat ćeš dovijeka.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 37, 28, 'Jer Jahve ljubi pravdu i pobožnika svojih ne ostavlja. $AJIN Zauvijek će biti zatrti zlikovci, istrijebit će se potomstvo bezbožnika.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 37, 29, 'Zemlju će posjedovati pravednici i živjet će na njoj dovijeka.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 37, 30, '$PE Pravednikova usta mudrost kazuju, a jezik njegov govori pravo.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 37, 31, 'Zakon mu je Božji u srcu, ne kolebaju se koraci njegovi.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 37, 32, '$SADE Bezbožnik vreba pravednoga i smišlja da ga usmrti.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 37, 33, 'Jahve ga neće ostaviti u njegovoj vlasti i neće dopustiti da ga na sudu osude.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 37, 34, '$KOF U Jahvu se uzdaj i drži se puta njegova: on će te uzvisit\' i baštinit ćeš zemlju; radostan ćeš gledati propast bezbožnih.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 37, 35, '$REŠ Vidjeh obijesna zlotvora gdje se k\'o cedar krošnjat širi.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 37, 36, 'Prođoh, i gle - nema ga više; potražih ga i ne nađoh.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 37, 37, '$ŠIN Promatraj čestita i gledaj neporočna: mirotvorac ima potomstvo.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 37, 38, 'A grešnici bit će svi iskorijenjeni, istrijebit će se zlikovačko sjeme.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 37, 39, '$TAU Od Jahve dolazi spas pravednicima, on im je zaklon u vrijeme nevolje.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 37, 40, 'Jahve im pomaže, on ih izbavlja: on će ih izbaviti od zlotvora i spasiti, jer u njemu traže okrilje.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 38, 1, 'Psalam. Davidov. Za spomen.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 38, 2, 'Jahve, u srdžbi svojoj nemoj ne karati, i nemoj me kazniti u svojemu gnjevu.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 38, 3, 'Strijele se tvoje u me zabodoše, ruka me tvoja teško pritisnu:');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 38, 4, 'na tijelu mi ništa zdravo nema zbog gnjeva tvog, od grijeha mojih mira mi nema kostima.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 38, 5, 'Zloće moje glavu su mi nadišle, kao preteško breme tište me.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 38, 6, 'Rane moje zaudaraju i gnjiju zbog bezumnosti moje.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 38, 7, 'Pogurih se sav i zgrčih, povazdan lutam žalostan.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 38, 8, 'Moji bokovi puni su ognjice, na tijelu mi ništa zdravo nema.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 38, 9, 'Iscrpljen sam i satrven posve, stenjem od jecanja srca svojega.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 38, 10, 'O Gospode, sve su mi želje pred tobom, i vapaji moji nisu ti skriveni.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 38, 11, 'Srce mi udara silno, snaga me ostavlja i svjetlost vida očinjeg gasi se.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 38, 12, 'Prijatelji i drugovi od rana mojih uzmakoše, i moji najbliži stoje daleko.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 38, 13, 'Namještaju mi zamke oni koji mi život vrebaju, koji mi žele nesreću, propašću mi prijete i uvijek smišljaju prijevare.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 38, 14, 'A ja sam kao gluh i ništa ne čujem i, kao nijem, usta ne otvaram.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 38, 15, 'Postadoh k\'o čovjek koji ne čuje i koji u ustima nema odgovora.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 38, 16, 'Jer u tebe se, o Jahve, uzdam, ti ćeš me uslišati, Jahve, Bože moj!');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 38, 17, 'Rekoh: \"Nek\' se ne raduju nada mnom; kad mi noga posrne, nek\' se ne uzdižu nada mnom!\"');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 38, 18, 'Jer umalo ne propadoh, i moja je bol svagda preda mnom.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 38, 19, 'Bezakonje svoje ja priznajem i pun sam žalosti zbog grijeha svojega.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 38, 20, 'A koji su bez razloga protiv mene, moćni su, i mnogi su koji me mrze nepravedno.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 38, 21, 'Za dobro zlom mi uzvraćaju, protive mi se što tražim dobro.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 38, 22, 'O Jahve, ne ostavljaj me! Bože moj, ne udaljuj se od mene!');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 38, 23, 'Požuri se meni u pomoć, Gospode, spase moj!');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 39, 1, 'Zborovođi. Jedutunu. Psalam. Davidov.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 39, 2, 'Odlučio sam: \"Čuvat ću put svoj da ne zgriješim jezikom; usta ću svoja zauzdati dokle god preda mnom bude bezbožnik.\"');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 39, 3, 'Zamukoh, zanijemjeh, glasa ne puštah, ali uzalud - bol mi postade gorča.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 39, 4, 'U meni srce je gorjelo, na samu pomisao buknuo bi oganj; tad progovorih svojim jezikom:');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 39, 5, '\"Objavi mi, Jahve, moj svršetak i kolika je mjera mojih dana, da znam kako sam ništavan.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 39, 6, 'Evo, pedljem si mi dane izmjerio, život moj je kao ništa pred tobom: tek dašak je svaki čovjek.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 39, 7, 'Poput sjene čovjek prolazi tek dašak je sve bogatstvo njegovo: zgrće, a ne zna tko će ga pokupiti.\"');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 39, 8, 'A sada, čemu da se nadam, Gospode? Sva je nada moja u tebi!');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 39, 9, 'Izbavi me svih mojih bezakonja, ne daj da ruglo budem luđaku!');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 39, 10, 'Šutim i usta ne otvaram, jer tako si ti učinio.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 39, 11, 'Bič svoj otkloni od mene, jer izdišem pod težinom ruke tvoje.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 39, 12, 'Ti kaznama popravljaš čovjeka i sve mu najdraže kao moljac rastačeš: tek dašak je svaki čovjek.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 39, 13, 'Čuj, o Jahve, molitvu moju, vapaje mi poslušaj, na suze se moje ne ogluši! Jer u tebe ja sam došljak, pridošlica kao svi oci moji.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 39, 14, 'Odvrati pogled od mene, da odahnem prije nego odem i više ne budem!');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 40, 1, 'Zborovođi. Psalam. Davidov.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 40, 2, 'Uzdah se u Jahvu uzdanjem silnim, i on se k meni prignu i usliša vapaj moj.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 40, 3, 'Izvuče me iz jame propasti, iz blata kalnoga; noge mi stavi na hridinu, korake moje ukrijepi.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 40, 4, 'U usta mi stavi pjesmu novu, slavopoj Bogu našemu. Vidjet će mnogi i strah će ih obuzeti: uzdanje će svoje staviti u Jahvu.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 40, 5, 'Blago čovjeku koji se u Jahvu uzda, koji ne ide za štovateljima lažnih bogova, za onima koji se predaju prijevari.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 40, 6, 'Čudesa mnoga tvoriš, o Jahve, Bože moj, i namisli čudesne - ravna ti nema! Kazivat\' ih i objavljivati želim, al\' odveć ih je da bi se nabrojit\' mogli.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 40, 7, 'Nisu ti mile ni žrtve ni prinosi, nego si mi uši otvorio: paljenice ni okajnice ne tražiš.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 40, 8, 'Tada rekoh: \"Evo dolazim! U svitku knjige piše za mene:');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 40, 9, 'Milje mi je, Bože moj, vršit volju tvoju, Zakon tvoj duboko u srcu ja nosim.\"');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 40, 10, 'Tvoju ću pravdu naviještat\' u velikom zboru, i usta svojih zatvoriti neću, o Jahve, sve ti je znano.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 40, 11, 'Tvoju pravdu neću kriti u srcu, kazivat ću vjernost tvoju i tvoj spas. Tajit neću dobrote tvoje, ni tvoje vjernosti velikoj skupštini.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 40, 12, 'A ti, o Jahve, milosrđa mi svog ne krati, dobrota tvoja i vjernost neka me svagda čuvaju.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 40, 13, 'Jer me okružiše nesreće nebrojene, krivice me moje sustigoše da gledat\' ne mogu: više ih je no vlasi na glavi, i srce mi je stoga klonulo.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 40, 14, 'Bilo ti milo, o Jahve, da me izbaviš; Gospodine, u pomoć mi pohitaj!');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 40, 15, 'Neka se postide i smetu svi koji mi o glavi rade. Nek\' uzmaknu i neka se posrame koji se nesreći mojoj raduju!');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 40, 16, 'Neka se skamene u sramoti svojoj koji zlurado na me grohoću!');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 40, 17, 'Neka kliču i nek\' se vesele u tebi svi koji te traže! Neka govore svagda: \"Velik je Jahve!\" svi koji spasenje tvoje ljube.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 40, 18, 'Bijedan sam ja i nevoljan, al\' Jahve se brine za me. Ti si pomoć moja i moj spasitelj; o Bože moj, ne kasni!');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 41, 1, 'Zborovođi. Psalam. Davidov.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 41, 2, 'Blago onome koji misli na uboga i slaba: u dan nevolje Jahve će ga spasiti!');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 41, 3, 'Jahve će ga štititi i živa sačuvati, sreću mu dati na zemlji i neće ga predati na volju dušmanima.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 41, 4, 'Jahve će ga ukrijepiti na postelji boli, bolest mu okrenuti u snagu.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 41, 5, 'Zavapih: \"Jahve, smiluj mi se, iscijeli mi dušu jer tebi sagriješih!\"');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 41, 6, 'Neprijatelji zlo govore o meni: \"Kad će umrijeti i kad će mu nestati imena?\"');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 41, 7, 'I dođe li tko da me posjeti, himbeno govori, u srcu pakosti skuplja i vani opada.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 41, 8, 'Mrzitelji moji svi složno šapuću o meni; zlo mi dosuđuju:');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 41, 9, '\"Pogubna se pošast na nj oborila.\" Ili: \"Tko jednom leže, više ne ustaje.\"');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 41, 10, 'Pa i prijatelj moj u koga se uzdah, koji blagovaše kruh moj, petu na me podiže.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 41, 11, 'A ti, Jahve, smiluj se meni i podigni me da im mogu uzvratiti.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 41, 12, 'Po tome ću znati da sam mio tebi: što se dušmanin moj neće veseliti nada mnom.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 41, 13, 'A mene ćeš zdrava uzdržati i pred svoje me lice staviti dovijeka.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 41, 14, 'Blagoslovljen Jahve, Bog Izraelov, od vijeka do vijeka! Tako neka bude! Amen!');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 42, 1, 'Zborovođi. Poučna pjesma. Sinova Korahovih.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 42, 2, 'Kao što košuta žudi za izvor-vodom, tako duša moja čezne, Bože, za tobom.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 42, 3, 'Žedna mi je duša Boga, Boga živoga: o, kada ću doći i lice Božje gledati?');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 42, 4, 'Suze su kruh moj danju i noću, dok me svednevice pitaju: \"Gdje ti je Bog tvoj?\"');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 42, 5, 'Duša moja gine kada se spomenem kako koračah u mnoštvu predvodeć\' ih k Domu Božjem uz radosno klicanje i hvalopojke u povorci svečanoj.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 42, 6, 'Što si mi, dušo, klonula i što jecaš u meni? U Boga se uzdaj, jer opet ću ga slaviti, spasenje svoje, Boga svog!');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 42, 7, 'Tuguje duša u meni, stoga se tebe spominjem iz zemlje Jordana i Hermona, s brda Misara.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 42, 8, 'Bezdan doziva bezdan bukom slapova tvojih: sve vode tvoje i vali preko mene prijeđoše.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 42, 9, 'Nek\' mi danju Jahve naklonost udijeli, a noću pjesmom ću hvalit\' Boga života svog.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 42, 10, 'Reći ću Bogu: \"Hridino moja, zašto me zaboravljaš? Zašto obilazim žalostan, pritisnut dušmanima?\"');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 42, 11, 'Kosti mi se lome od poruge neprijatelja dok me svednevice pitaju: \"Gdje ti je Bog tvoj?\"');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 42, 12, 'Što si mi, dušo, klonula i što jecaš u meni? U Boga se uzdaj, jer opet ću ga slaviti, spasenje svoje, Boga svog!');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 43, 1, 'Dosudi mi pravo, Bože, i povedi parbu moju protiv čeljadi bezbožne, izbavi me od čovjeka zlobna i opaka!');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 43, 2, 'Jer ti si, Bože, zaklon moj: zašto me odbacuješ? Zašto obilazim žalostan, pritisnut dušmanima?');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 43, 3, 'Pošlji svjetlost svoju i vjernost: nek\' me vode, nek\' me dovedu na tvoju svetu goru, u šatore tvoje!');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 43, 4, 'I pristupit ću Božjem žrtveniku, Bogu, radosti svojoj. Harfom ću slaviti tebe, Bože, o Bože moj!');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 43, 5, 'Što si mi, dušo, klonula i što jecaš u meni? U Boga se uzdaj, jer opet ću ga slaviti, spasenje svoje, Boga svog!');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 44, 1, 'Zborovođi. Sinova Korahovih. Poučna pjesma.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 44, 2, 'Bože, ušima svojim slušasmo, očevi nam pripovijedahu naši, o djelu koje si izveo u danima njihovim - u danima davnim.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 44, 3, 'Rukom si svojom izagnao pogane, a njih posadio, iskorijenio narode, a njih raširio.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 44, 4, 'Mačem svojim oni zemlju ne zauzeše niti im mišica njihova donese pobjedu, već desnica tvoja i tvoja mišica i lice tvoje milosno jer si ih ljubio.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 44, 5, 'Ti, o moj Kralju i Bože moj, ti si dao pobjede Jakovu.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 44, 6, 'Po tebi dušmane svoje odbismo, u tvome imenu zgazismo one koji se na nas digoše.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 44, 7, 'U svoj se luk nisam pouzdavao, nit\' me mač moj spasavao.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 44, 8, 'Nego ti, ti si nas spasio od dušmana, ti si postidio one koji nas mrze.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 44, 9, 'Dičili smo se Bogom u svako doba i tvoje ime slavili svagda.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 44, 10, 'A sad si nas odbacio i posramio nas i više ne izlaziš, Bože, sa četama našim.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 44, 11, 'Pustio si da pred dušmanima uzmaknemo, i opljačkaše nas mrzitelji naši.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 44, 12, 'Dao si nas k\'o ovce na klanje i rasuo nas među neznabošce.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 44, 13, 'U bescjenje si puk svoj prodao i obogatio se nisi prodajom.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 44, 14, 'Učinio si nas ruglom susjedima našim, na podsmijeh i igračku onima oko nas.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 44, 15, 'Na porugu smo neznabošcima, narodi kimaju glavom nad nama.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 44, 16, 'Svagda mi je sramota moja pred očima i stid mi lice pokriva');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 44, 17, 'zbog pogrdne graje podrugljivaca, zbog osvetljiva dušmanina.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 44, 18, 'Sve nas to snađe iako te nismo zaboravili niti povrijedili Saveza tvoga,');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 44, 19, 'niti nam se srce odmetnulo od tebe, niti nam je noga s tvoje skrenula staze,');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 44, 20, 'kad si nas smrvio u boravištu šakalskom i smrtnim nas zavio mrakom.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 44, 21, 'Da smo i zaboravili ime Boga našega, da smo ruke k tuđem bogu podigli:');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 44, 22, 'zar Bog toga ne bi saznao? TÓa on poznaje tajne srdaca!');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 44, 23, 'Ali zbog tebe ubijaju nas dan za danom, i mi smo im k\'o ovce za klanje.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 44, 24, 'Preni se! Što spavaš, Gospode? Probudi se! Ne odbacuj nas dovijeka!');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 44, 25, 'Zašto lice svoje sakrivaš, zaboravljaš bijedu i nevolju našu?');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 44, 26, 'Jer duša nam se u prah raspala, trbuh nam se uza zemlju prilijepio.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 44, 27, 'Ustani, u pomoć nam priteci, izbavi nas radi ljubavi svoje!');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 45, 1, 'Zborovođi. Po napjevu \"Ljiljani\". Sinova Korahovih. Poučna pjesma. Svadbena pjesma.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 45, 2, 'Iz srca mi naviru riječi divne: pjesmu svoju ja kralju pjevam, jezik mi je k\'o pisaljka hitra pisara.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 45, 3, 'Lijep si, najljepši od ljudskih sinova, po usnama ti se milina prosula, stoga te Bog blagoslovio dovijeka.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 45, 4, 'Pripaši mač uz bedra, junače, ogrni se sjajem i veličanstvom!');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 45, 5, 'Zajaši i kreni za istinu, za vjernost i pravdu, zapni luk i desnicu svoju proslavi!');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 45, 6, 'Oštre su strelice tvoje, narodi padaju pred tobom i kraljeve dušmane ostavlja hrabrost.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 45, 7, 'Prijestolje je tvoje, Bože, u vijeke vjekova, i pravedno žezlo - žezlo je tvog kraljevstva!');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 45, 8, 'Ti ljubiš pravednost, a mrziš bezakonje, stoga Jahve, Bog tvoj, tebe pomaza uljem radosti kao nikog od tvojih drugova.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 45, 9, 'Smirnom, alojem i kasijom mirišu ti haljine, iz dvorova bjelokosnih harfe te vesele.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 45, 10, 'Kraljevske ti kćeri idu u susret, zdesna ti je kraljica u zlatu ofirskom.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 45, 11, '\"Slušaj, kćeri, pogledaj, prisluhni: zaboravi svoj narod i dom oca svog!');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 45, 12, 'Zaželi li kralj ljepotu tvoju, smjerno se pokloni njemu jer je on gospodar tvoj.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 45, 13, 'Narod tirski dolazi s darovima, naklonost tvoju traže prvaci naroda.\"');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 45, 14, 'Sva lijepa korača kći kraljeva u haljinama zlatom vezenim.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 45, 15, 'U haljini od veza šarena kralju je dovode, pratnja su joj djevice, druge njezine.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 45, 16, 'S veseljem ih vode i s klicanjem u kraljeve dvore ulaze.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 45, 17, 'Oce tvoje naslijedit će tvoji sinovi, postavit ćeš ih knezovima na svoj zemlji.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 45, 18, 'Iz koljena u koljeno naviještat će ime tvoje, hvalit će te narodi u vijeke vjekova.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 46, 1, 'Zborovođi. Sinova Korahovih. Po napjevu \"Djevice\". Pjesma.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 46, 2, 'Bog nam je zaklon i utvrda, pomoćnik spreman u nevolji.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 46, 3, 'Stoga, ne bojmo se kad se ljulja zemlja, kad se bregovi ruše u more.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 46, 4, 'Nek\' buče i bjesne valovi morski, nek\' bregovi dršću od žestine njihove: s nama je Jahve nad Vojskama, naša je utvrda Bog Jakovljev!');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 46, 5, 'Rijeka i rukavci njezini vesele Grad Božji, presveti šator Višnjega.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 46, 6, 'Bog je sred njega, poljuljat se neće, od rane zore Bog mu pomaže.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 46, 7, 'Ma bješnjeli puci, rušila se carstva, kad glas njegov zagrmi, zemlja se rastopi:');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 46, 8, 's nama je Jahve nad Vojskama, naša je utvrda Bog Jakovljev!');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 46, 9, 'Dođite, gledajte djela Jahvina, strahote koje on na zemlji učini.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 46, 10, 'Do nakraj zemlje on ratove prekida, lukove krši i lomi koplja, štitove ognjem sažiže.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 46, 11, 'Prestanite i znajte da sam ja Bog, uzvišen nad pucima, nad svom zemljom uzvišen!');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 46, 12, 'S nama je Jahve nad Vojskama, naša je utvrda Bog Jakovljev!');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 47, 1, 'Zborovođi. Sinova Korahovih. Psalam.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 47, 2, 'Narodi svi, plješćite rukama, kličite Bogu glasom radosnim.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 47, 3, 'Jer Jahve je to - svevišnji, strašan, kralj velik nad zemljom svom.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 47, 4, 'Narode je nama podložio, pogane stavio pod noge naše,');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 47, 5, 'baštinu nam odabrao - ponos Jakova, svoga ljubimca.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 47, 6, 'Uzlazi Bog uz klicanje, Jahve uza zvuke trublje.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 47, 7, 'Pjevajte Bogu, pjevajte, pjevajte kralju našemu, pjevajte!');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 47, 8, 'Jer on je kralj nad zemljom svom, pjevajte Bogu, pjevači vrsni!');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 47, 9, 'Bog kraljuje nad narodima, stoluje Bog na svetom prijestolju.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 47, 10, 'Prvaci se pribiru poganski k narodu Boga Abrahamova. Božji su svi vlastodršci zemlje, nad svima on je uzvišen.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 48, 1, 'Pjesma. Psalam. Sinova Korahovih.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 48, 2, 'Velik je Jahve, hvale predostojan u gradu Boga našega.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 48, 3, 'Sveto brdo njegovo, brijeg veličanstven, radost je zemlji svoj. Gora Sion, na krajnjem sjeveru, grad je Kralja velikog.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 48, 4, 'Bog u kulama njegovim jakom se pokaza utvrdom.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 48, 5, 'Jer gle, složiše se kraljevi, navališe zajedno.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 48, 6, 'Čim vidješe, zapanjiše se i zbunjeni u bijeg nagnuše.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 48, 7, 'Ondje ih trepet obuze kao muka porodilje,');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 48, 8, 'kao kad vjetar istočni razbija brodove taršiške.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 48, 9, 'Što smo čuli, sada vidimo: grad Jahve nad Vojskama, grad Boga našega - Bog ga utvrdi dovijeka.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 48, 10, 'Spominjemo se, Bože, tvoje dobrote usred Hrama tvojega.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 48, 11, 'Kao ime tvoje, Bože, tako i slava tvoja do nakraj zemlje doseže. Puna je pravde desnica tvoja; neka se raduje brdo sionsko!');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 48, 12, 'Neka kliču gradovi Judini zbog tvojih sudova!');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 48, 13, 'Obiđite Sion i prođite njime, prebrojite kule njegove!');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 48, 14, 'Pogledajte dobro bedeme njegove, promotrite mu potanko dvorove: da biste kazivali budućem koljenu:');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 48, 15, '\"Takav je Bog, Bog naš zasvagda i dovijeka! On neka nas vodi!\"');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 49, 1, 'Zborovođi. Sinova Korahovih. Psalam.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 49, 2, 'Poslušajte ovo, svi narodi, čujte, svi stanovnici zemlje,');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 49, 3, 'vi, djeco puka, i vi, odličnici, bogati i siromašni zajedno!');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 49, 4, 'Moja će usta zboriti mudrost, i moje srce misli razumne.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 49, 5, 'K poučnoj izreci priklonit ću uho, uz harfu ću izložit\' svoju zagonetku.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 49, 6, 'Što da se bojim u danima nesreće kad me opkoli zloba izdajica');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 49, 7, 'koji se u blago svoje uzdaju i silnim se hvale bogatstvom?');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 49, 8, 'TÓa nitko sebe ne može otkupit\' ni za se dati Bogu otkupninu:');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 49, 9, 'životu je cijena previsoka, i nikada je neće platiti');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 49, 10, 'tko želi živjeti dovijeka i ne vidjeti jamu grobnu.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 49, 11, 'Jer, i mudri umiru, pogiba i luđak i bezumnik: bogatstvo svoje ostavlja drugima.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 49, 12, 'Grobovi im kuće zasvagda, stanovi njihovi od koljena do koljena, sve ako se zemlje nazivale imenima njihovim.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 49, 13, 'Čovjek koji nerazumno živi sličan je stoci koja ugiba.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 49, 14, 'Takav je put onih koji se ludo uzdaju, to je konac onih koji uživaju u sreći:');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 49, 15, 'Poput stada redaju se u Podzemlju, smrt im je pastir, a dobri njima vladaju. Njihova će lika brzo nestati, Podzemlje će im biti postojbina.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 49, 16, 'A moju će dušu Bog ugrabiti Podzemlju iz pandža i milostivo me primiti.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 49, 17, 'Ne boj se ako se tko obogati i ako se poveća blago doma njegova:');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 49, 18, 'kad umre, ništa neće ponijeti sa sobom, i blago njegovo neće s njime sići.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 49, 19, 'Ako se u životu držao sretnim - \"Govorit će se da ti je dobro bilo!\" -');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 49, 20, 'i on će doći u skup otaca svojih, gdje svjetlosti više vidjeti neće.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 49, 21, 'Čovjek koji nerazumno živi sličan je stoci koja ugiba.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 50, 1, 'Psalam. Asafov. Bog nad bogovima, Jahve, govori i zove zemlju od izlaza sunčeva do zalaza.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 50, 2, 'Sa Siona predivnog Bog zablista:');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 50, 3, 'Bog naš dolazi i ne šuti. Pred njim ide oganj što proždire, oko njega silna bjesni oluja.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 50, 4, 'On zove nebesa odozgo i zemlju da sudi narodu svojemu:');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 50, 5, '\"Saberite mi sve pobožnike koji žrtvom Savez sa mnom sklopiše!\"');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 50, 6, 'Nebesa objavljuju pravednost njegovu: on je Bog sudac!');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 50, 7, '\"Slušaj, narode moj, ja ću govoriti, o Izraele, svjedočit ću protiv tebe: ja, Bog - Bog tvoj!');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 50, 8, 'Ne korim te zbog žrtava tvojih - paljenice su tvoje svagda preda mnom.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 50, 9, 'Neću od doma tvog\' uzet junca, ni jaraca iz tvojih torova:');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 50, 10, 'tÓa moje su sve životinje šumske, tisuće zvjeradi u gorama mojim.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 50, 11, 'Znam sve ptice nebeske, moje je sve što se miče u poljima.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 50, 12, 'Kad bih ogladnio, ne bih ti rekao, jer moja je zemlja i sve što je ispunja.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 50, 13, 'Zar da ja jedem meso bikova ili da pijem krv jaraca?');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 50, 14, 'Prinesi Bogu žrtvu zahvalnu, ispuni Višnjemu zavjete svoje!');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 50, 15, 'I zazovi me u dan tjeskobe: oslobodit ću te, a ti ćeš me slaviti.\"');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 50, 16, 'A grešniku Bog progovara: \"Što tumačiš naredbe moje, što mećeš u usta Savez moj?');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 50, 17, 'Ti, komu stega ne prija, te riječi moje iza leđa bacaš?');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 50, 18, 'Kad tata vidiš, s njime se bratimiš i družiš se s preljubnicima.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 50, 19, 'Svoja si usta predao pakosti, a jezik ti plete prijevare.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 50, 20, 'U društvu na brata govoriš i kaljaš sina matere svoje.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 50, 21, 'Sve si to činio, a ja da šutim? Zar misliš da sam ja tebi sličan? Pokarat ću te i stavit ću ti sve to pred oči.\"');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 50, 22, 'Shvatite ovo svi vi koji Boga zaboraviste, da vas ne pograbim i nitko vas spasiti neće.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 50, 23, 'Pravo me štuje onaj koji prinosi žrtvu zahvalnu: i onomu koji hodi stazama pravim - njemu ću pokazati spasenje svoje.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 50, 24, '');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 51, 1, 'Zborovođi. Psalam. Davidov. Kad je k Davidu došao prorok Natan poslije njegova grijeha');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 51, 2, 'Smiluj mi se, Bože, po milosrđu svome, po velikom smilovanju izbriši moje bezakonje!');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 51, 3, 'Operi me svega od moje krivice, od grijeha me mojeg očisti!');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 51, 4, 'Bezakonje svoje priznajem, grijeh je moj svagda preda mnom.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 51, 5, 'Tebi, samom tebi ja sam zgriješio i učinio što je zlo pred tobom: pravedan ćeš biti kad progovoriš, bez prijekora kada presudiš.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 51, 6, 'Evo, grešan sam već rođen, u grijehu me zače majka moja.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 51, 7, 'Evo, ti ljubiš srce iskreno, u dubini duše učiš me mudrosti.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 51, 8, 'Poškropi me izopom da se očistim, operi me, i bit ću bjelji od snijega!');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 51, 9, 'Objavi mi radost i veselje, nek\' se obraduju kosti satrvene!');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 51, 10, 'Odvrati lice od grijeha mojih, izbriši svu moju krivicu!');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 51, 11, 'Čisto srce stvori mi, Bože, i duh postojan obnovi u meni!');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 51, 12, 'Ne odbaci me od lica svojega i svoga svetog duha ne uzmi od mene!');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 51, 13, 'Vrati mi radost svoga spasenja i učvrsti me duhom spremnim!');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 51, 14, 'Učit ću bezakonike tvojim stazama, i grešnici tebi će se obraćati.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 51, 15, 'Oslobodi me od krvi prolivene, Bože, Bože spasitelju moj! Nek\' mi jezik kliče pravednosti tvojoj!');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 51, 16, 'Otvori, Gospodine, usne moje, i usta će moja naviještati hvalu tvoju.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 51, 17, 'Žrtve ti se ne mile, kad bih dao paljenicu, ti je ne bi primio.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 51, 18, 'Žrtva Bogu duh je raskajan, srce raskajano, ponizno, Bože, nećeš prezreti.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 51, 19, 'U svojoj dobroti milostiv budi Sionu i opet sagradi jeruzalemske zidine!');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 51, 20, 'Tada će ti biti mile žrtve pravedne i tad će se prinosit\' teoci na žrtveniku tvojemu.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 51, 21, '');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 52, 1, 'Zborovođi. Poučna pjesma. Davidova. Kad je Edomac Doeg Šaulu javio: \"David je ušao u kuću Abimelekovu.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 52, 2, 'Što se to hvališ pakošću, silniče nesmiljeni?');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 52, 3, 'Neprestano snuješ o propasti, jezik ti je britva nabrušena, spletkaru!');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 52, 4, 'Zlo voliš više nego dobro, i laž više nego pravednost!');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 52, 5, 'Mili su ti pogubni govori, lažljivi jeziče!');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 52, 6, 'Bog će te zato satrti, zauvijek te ukloniti; iščupat će te iz tvog šatora, iskorijeniti iz zemlje živih.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 52, 7, 'Pravednici će gledati s užasom i njemu se smijati:');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 52, 8, '\"Gle čovjeka koji ne uze Boga za svoju zaštitu, već se uzdao u veliko bogatstvo i osilio u svojim zločinima!\"');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 52, 9, 'A ja, k\'o zelena maslina u Domu Božjem, uzdam se u Božju dobrotu dovijeka.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 52, 10, 'Hvalit ću te svagda što si to učinio i slavit ću tvoje ime, jer je dobrostivo, pred licem tvojih pobožnika.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 52, 11, '');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 53, 1, 'Zborovođi. Prema napjevu \"Bolest\". Poučna pjesma. Davidova.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 53, 2, 'Bezumnik reče u srcu: \"Nema Boga!\" Pokvareni rade gadosti; nitko da čini dobro.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 53, 3, 'Bog s nebesa gleda na sinove ljudske da vidi ima li tko razuman Boga da traži.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 53, 4, 'No svi skrenuše zajedno, svi se pokvariše: nitko da čini dobro - nikoga nema.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 53, 5, 'Neće li se urazumiti svi što čine bezakonje, koji proždiru narod moj kao da jedu kruh? Boga oni ne zazivlju:');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 53, 6, 'od straha će drhtat\' gdje straha i nema jer Bog će rasuti kosti onih koji tebe opsjedaju, bit će posramljeni jer će ih Bog odbaciti.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 53, 7, 'O, neka dođe sa Siona spas Izraelu! Kad Bog promijeni udes naroda svoga, klicat će Jakov, radovat\' se Izrael.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 54, 1, 'Zborovođi. Uza žičana glazbala. Poučna pjesma. Davidova. Kad su Zifijci došli k Šaulu govoreći: \"David se kod nas');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 54, 2, 'Spasi me, Bože, svojim imenom i jakošću svojom izbori mi pravdu!');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 54, 3, 'Poslušaj, Bože, moju molitvu i usliši riječi usta mojih!');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 54, 4, 'Oholice ustadoše na me i moj život traže silnici: na Boga se ne osvrću.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 54, 5, 'Evo, Bog mi pomaže, Gospodin krijepi život moj.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 54, 6, 'Okreni nesreću na dušmane moje, zatri ih u vjernosti svojoj.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 54, 7, 'Od srca rado ću ti žrtvovati, slavit ću ti ime, Jahve, jer je dobrostivo,');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 54, 8, 'jer ti me izbavi iz svake nevolje, i oko moje vidje postiđene moje dušmane.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 54, 9, '');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 55, 1, 'Zborovođi. Uza žičana glazbala. Poučna pjesma. Davidova.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 55, 2, 'Počuj mi, Bože, molitvu, ne krij se molbi mojoj:');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 55, 3, 'obazri se na me i usliši me! Mučim se u svojoj tjeskobi,');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 55, 4, 'zbuni me vika dušmanska i tlačenje grešničko. Navališe na me nesrećom, bijesno me progone.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 55, 5, 'Srce mi je ustreptalo i strah me samrtni spopade.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 55, 6, 'Užas me i trepet hvata, groza me obuze.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 55, 7, 'Zavapih: \"O, da su mi krila golubinja, odletio bih da otpočinem!');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 55, 8, 'Daleko, daleko bih letio, u pustinji se nastanio;');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 55, 9, 'brzo bih si potražio sklonište od bijesne oluje i vihora.\"');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 55, 10, 'Smeti ih, Gospode, podvoji im jezike, jer nasilje i svađu vidim u gradu;');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 55, 11, 'danju i noću zidinama kruže; bezakonja su i nevolje u njemu.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 55, 12, 'Usred njega zasjede, s ulica mu nepravda i podlost ne odlaze.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 55, 13, 'Da me pogrdio dušmanin, bio bih podnio; da se digao na me koji me mrzi, pred njim bih se sakrio.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 55, 14, 'Ali ti, ti si to bio, meni jednak, prijatelj moj, moj pouzdanik');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 55, 15, 's kojim sam slatko drugovao i složno hodismo u Domu Božjemu.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 55, 16, 'Smrt neka ih zaskoči, živi nek\' siđu u Podzemlje jer im je pakost u stanu i srcu.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 55, 17, 'A ja ću Boga prizvati, i Jahve će me spasiti.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 55, 18, 'Večerom, jutrom i o podne tužan ću jecati, i on će čuti vapaj moj.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 55, 19, 'Dat će mi mira od onih koji me progone: jer mnogi su protiv mene.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 55, 20, 'Bog će čuti i njih poniziti, Onaj koji kraljuje odvijeka, jer se ne popravljaju, Boga se ne boje.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 55, 21, 'Podižu ruke na prijatelje, savez svoj oskvrnjuju.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 55, 22, 'Usta su im glađa od maslaca, a srce ratoborno; riječi blaže od ulja, a oni - isukani mačevi.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 55, 23, 'Povjeri Jahvi svu svoju brigu, i on će te pokrijepiti: neće dati da ikada posrne pravednik.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 55, 24, 'A njih ti, o Bože, strmoglavi u jamu grobnu! Krvoloci i varalice ni polovicu dana neće doživjeti! A ja se u tebe uzdam!');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 56, 1, 'Zborovođi. Prema napjevu \"Golubica nijema u daljini\". Davidov. Miktam. Kad su ga u Gatu uhitili Filistejci.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 56, 2, 'Smiluj mi se, moj Bože, jer me dušmanin hoće zgaziti, napadač me moj neprestano tlači.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 56, 3, 'Dušmani moji nasrću na me povazdan, mnogo ih je koji se na me obaraju. Svevišnji,');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 56, 4, 'kad me strah spopadne, u te ću se uzdati.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 56, 5, 'Božje obećanje slavim, u Boga ja se uzdam i neću se bojati: što mi može učiniti smrtnik?');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 56, 6, 'Od jutra do večeri obružuju me, svi naumi njihovi meni su na zlo.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 56, 7, 'Sastaju se i vrebaju, paze mi na korake, o glavi mi rade.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 56, 8, 'Plati im prema bezakonju, u gnjevu, o Bože, obori pogane!');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 56, 9, 'Ti izbroji dane mog progonstva, sabrao si suze moje u mijehu svom. Nije li sve zapisano u knjizi tvojoj?');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 56, 10, 'Moji će dušmani uzmaknuti čim te zazovem. Ovo sigurno znam: Bog je za mene!');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 56, 11, 'Božje obećanje slavim,');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 56, 12, 'u Jahvu se uzdam i neću se bojati: što mi može učiniti čovjek?');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 56, 13, 'Vežu me zavjeti koje učinih tebi, o Bože: prinijet ću ti žrtve zahvalne');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 56, 14, 'jer si mi dušu od smrti spasio. Ti si očuvao noge moje od pada, da pred Bogom hodim u svjetlosti živih.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 57, 1, 'Zborovođi. Po napjevu \"Ne pogubi!\" Davidov. Miktam. Kad je ispred Šaula pobjegao u pećinu.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 57, 2, 'Smiluj mi se, Bože, o smiluj se meni jer mi se duša utječe tebi! U sjenu tvojih krila zaklanjam se dok pogibao ne mine.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 57, 3, 'Vapijem Bogu višnjemu, Bogu koji mi čini dobro.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 57, 4, 'Nek\' pošalje s nebesa i spasi me, nek\' postidi one što me progone: neka Bog pošalje dobrotu svoju i vjernost!');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 57, 5, 'Ležim usred lavova koji proždiru ljudske sinove. Zubi su im koplja i strijele, a jezik im mač je naoštren.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 57, 6, 'Uzvisi se, Bože, nad nebesa, slava tvoja nek\' je nad svom zemljom!');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 57, 7, 'Mrežu namjestiše stopama mojim, stisnuše dušu moju; iskopaše preda mnom jamu: sami nek\' u nju padnu!');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 57, 8, 'Postojano je srce moje, Bože, postojano je srce moje; pjevat ću i svirati.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 57, 9, 'Probudi se, dušo moja! Probudi se, harfo i citaro! Probudit ću zoru jutarnju.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 57, 10, 'Hvalit ću te, Gospode, među narodima, među pucima pjevat ću tebi:');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 57, 11, 'jer do neba je dobrota tvoja, do oblaka vjernost tvoja.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 57, 12, 'Uzvisi se, Bože, nad nebesa, slava tvoja nek\' je nad svom zemljom!');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 58, 1, 'Zborovođi. Po napjevu \"Ne pogubi!\" Davidov. Miktam.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 58, 2, 'Zar doista krojite pravdu, vi moćni, zar sudite pravo, sinovi ljudski?');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 58, 3, 'Ne, već bezakonje smišljeno činite, po zemlji vam ruke dijele nepravde.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 58, 4, 'Na krivu su putu bezbošci od krila majčina, na krivu su putu lašci od utrobe.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 58, 5, 'U njima je otrov kao u zmije, kao u ljutice što uši začepljuje');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 58, 6, 'da glas čarobnjakov ne čuje ni glas bajača vješta bajanju.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 58, 7, 'O Bože, polomi im zube u ustima; razbij, o Jahve, čeljusti lavićima!');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 58, 8, 'K\'o vode što hitro otječu neka se razliju, k\'o zgažena trava neka se osuše.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 58, 9, 'Nek\' budu k\'o puž koji se pužuć\' rastoči, k\'o pometnut plot nek\' sunca ne vide.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 58, 10, 'Prije nego vam kotlovi trnje osjete, dok je zeleno, neka ga vihor odnese.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 58, 11, 'Radostan će biti pravednik kad ugleda odmazdu, noge će prati u krvi zlotvora.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 58, 12, 'I reći će ljudi: \"Pravednik plod svoj ima! Još ima Boga da sudi na zemlji!\"');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 59, 1, 'Zborovođi. Po napjevu \"Ne pogubi!\" Davidov. Miktam. Kad je Šaul opkolio kuću da ubije Davida.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 59, 2, 'Izbavi me od dušmana, Bože moj, zaštiti me od mojih protivnika!');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 59, 3, 'Izbavi me od bezakonika, od krvoloka spasi me!');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 59, 4, 'Jer evo: dušu moju vrebaju, na me ustadoše silnici. Nema na meni krivnje, o Jahve, ni grijeha:');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 59, 5, 'bez moje krivnje na me nasrću. Probudi se! Dođi mi u pomoć i pogledaj,');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 59, 6, 'Jahve, Bože nad Vojskama, Bože Izraelov! Preni se, kazni sve pogane, podlacima nemoj se smilovati!');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 59, 7, 'Uvečer se vraćaju, reže poput pasa i trče po gradu.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 59, 8, 'Gle, kako bljuju ustima; kletve su im na usnama i govore: \"Tko nas čuje?\"');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 59, 9, 'No, ti im se smiješ, o Jahve, i rugaš se poganima svima.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 59, 10, 'Jakosti moja, gledat ću na te, jer ti si, Bože, zaštita moja, Bog moj, milosrđe moje.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 59, 11, 'Bog neka mi pohiti u susret, nek\' me razveseli nad dušmanima mojim!');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 59, 12, 'Pobij ih, Bože, da mi narod ne zavode, zbuni i obori ih jakošću svojom, štite naš, Gospodine.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 59, 13, 'Grijeh je svaka riječ usta njihovih: nek se uhvate u svoju oholost, u kletve i laži što ih govore!');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 59, 14, 'Istrijebi ih u gnjevu, istrijebi da nestanu, nek\' se zna da Bog vlada u Jakovu i do nakraj zemlje!');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 59, 15, 'Uvečer se vraćaju, reže poput pasa i trče po gradu.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 59, 16, 'Nek\' lutaju okolo tražeći hranu; i kad se nasite, neka zavijaju.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 59, 17, 'A ja ću opjevati silu tvoju i klicat ću jutrom milosrđu tvome, jer mi ti postade utočište i sklonište u dan nevolje.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 59, 18, 'Jakosti moja, tebi ću pjevati, jer ti si, Bože, zaštita moja, Bog moj, milosrđe moje.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 60, 1, 'Zborovođi. Po napjevu \"Ljiljan svjedočanstva\". Miktam. Davidov. Kad je David izišao protiv Aram Naharajima i protiv Aram Sobe i kad je Joab na povratku potukao dvanaest tisuća Edomaca');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 60, 2, 'Bože, ti nas ÓodbÄaci i bojne nam redove prÓobi, razjari se, a sad nas opet vrati!');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 60, 3, 'Potrese zemlju, rasječe je, zatvori joj usjeline jer se poljuljala.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 60, 4, 'Zlu si kob na svoj narod navalio, napio nas vinom omamnim.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 60, 5, 'Al\' si i stijeg dao vjernicima svojim da umaknu luku dušmanskom.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 60, 6, 'Da ti se ljubimci izbave, desnicom pomozi, usliši nas!');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 60, 7, 'Bog reče u svom Svetištu: \"Šekem ću razdijelit\' kličući, dolinu Sukot izmjeriti.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 60, 8, 'Moj je Gilead, moj Manaše, Efrajim mi kaciga, Judeja žezlo moje!');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 60, 9, 'Moab je sud iz kojeg se umivam, na Edom ću baciti obuću, nad Filistejcem slavit\' pobjedu!\"');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 60, 10, 'Tko će me dovesti do utvrđena grada, tko će me dovesti do Edoma?');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 60, 11, 'Zar nećeš ti, o Bože, što nas odbaci? Zar više nećeš, Bože, s četama našim?');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 60, 12, 'Pomozi nam protiv dušmana, jer ljudska je pomoć ništavna!');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 60, 13, 'S pomoću Božjom hrabro ćemo se boriti, a on će zgaziti naše dušmane.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 60, 14, '');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 61, 1, 'Zborovođi. Uza žičana glazbala. Davidov.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 61, 2, 'O Bože, vapaj mi poslušaj, budi pomnjiv na molitvu moju!');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 61, 3, 'S kraja zemlje vapijem k tebi jer mi srce klonu. Dignut ćeš me na liticu i pokoj mi dati,');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 61, 4, 'jer ti si moje sklonište, utvrda čvrsta protiv dušmana.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 61, 5, 'O, da mi je stanovati uvijek u tvom šatoru, da se sklanjat\' mogu pod okrilje tvoje!');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 61, 6, 'Jer ti, Bože, usliši molbe moje, dade mi baštinu onih što ime ti štuju.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 61, 7, 'Kraljevim danima pridometni danÄa, kroz koljena mnoga nek\' mu ljeta traju,');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 61, 8, 'nek\' pred Bogom uvijek vlada; dobrotu i vjernost pošalji da ga čuvaju!');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 61, 9, 'Ovako ću pjevat svagda tvom imenu, dan za danom vršit\' zavjete svoje.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 62, 1, 'Zborovođi. Po Jedutunu. Psalam. Davidov.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 62, 2, 'Samo je u Bogu mir, dušo moja, samo je u njemu spasenje.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 62, 3, 'Samo on je moja hrid i spasenje, utvrda moja: neću se pokolebati.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 62, 4, 'Dokle ćete na bijednika nasrtati, obarat\' ga svi zajedno, k\'o zid ruševan il\' ogradu nagnutu?');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 62, 5, 'Urotiše se da me s visa mog obore, u laži uživaju; ustima blagoslivlju, a u srcu proklinju.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 62, 6, 'Samo je u Bogu mir, dušo moja, samo je u njemu nada moja.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 62, 7, 'Samo on je moja hrid i spasenje, utvrda moja: neću se pokolebati.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 62, 8, 'U Boga je spasenje moje i slava; Bog mi je hridina silna, utočište.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 62, 9, 'U nj se, narode, uzdaj u svako doba; pred njim srca izlijevajte: Bog je naše utočište!');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 62, 10, 'Sinovi su ljudski samo dašak, laž su djeca čovječja: svi da stanu na tezulju, od daha bi lakši bili.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 62, 11, 'U grabež se ne uzdajte nit\' se otetim tašto hvalite; umnoži l\' se blago, nek\' vam srce za nj ne prione.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 62, 12, 'Bog rekao jedno, a ja dvoje čuo:');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 62, 13, '\"U Boga je snaga! U tebe je, Gospode, dobrota! Ti uzvraćaš svakom po djelima.\"');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 63, 1, 'Psalam. Davidov. Dok David bijaše u Judejskoj pustinji.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 63, 2, 'O Bože, ti si Bog moj: gorljivo tebe tražim; tebe žeđa duša moja, tebe želi tijelo moje, kao zemlja suha, žedna, bezvodna.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 63, 3, 'U Svetištu sam tebe motrio gledajuć\' ti moć i slavu.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 63, 4, 'Ljubav je tvoja bolja od života, moje će te usne slavit\'.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 63, 5, 'Tako ću te slavit\' za života, u tvoje ću ime ruke dizati.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 63, 6, 'Duša će mi biti kao sala i mrsa sita, hvalit ću te kliktavim ustima.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 63, 7, 'Na postelji se tebe spominjem, u bdjenjima noćnim mislim na tebe.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 63, 8, 'Ti postade meni pomoć, kličem u sjeni krila tvojih.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 63, 9, 'Duša se moja k tebi privija, desnica me tvoja drži.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 63, 10, 'Oni što dušu u propast guraju neka siđu u dubinu zemlje,');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 63, 11, 'nek\' vlasti mača predani budu, nek\' postanu plijen šakalima.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 63, 12, 'A kralj će se radovat\' u Bogu, slavit će se tko se kune njime, jer će lašcima biti začepljena usta.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 64, 1, 'Zborovođi. Psalam. Davidov.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 64, 2, 'Poslušaj, Bože, moje žalbe glas; od strašna dušmanina život mi čuvaj!');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 64, 3, 'Štiti me od mnoštva opakih, sakrij od bjesnila zlotvora');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 64, 4, 'koji bruse jezike k\'o mačeve, otrovne riječi izbacuju kao strijele,');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 64, 5, 'da iz potaje rane nedužna, da ga rane iznenada ne bojeć\' se ničega.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 64, 6, 'Spremni su na djelo pakosno, snuju kako će kradom zamke staviti i govore: \"Tko će nas vidjeti?\"');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 64, 7, 'Snuju zlodjela, smišljene osnove kriju: pamet i srce čovječje bezdan su duboki.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 64, 8, 'No Bog ih ranjava strijelom, odjednom ih rane prekriju.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 64, 9, 'Vlastiti jezik propast im donosi, kimaju glavom oni što ih vide:');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 64, 10, 'svi se boje, Božje djelo slave i misle o onom što on učini.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 64, 11, 'Pravednik se raduje u Jahvi, njemu se utječe, i kliču svim srcem čestiti.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 65, 1, 'Zborovođi. Psalam. Davidov. Pjesma.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 65, 2, 'Bože, tebi dolikuje hvalospjev sa Sionu, tebi se ispunja zavjet -');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 65, 3, 'ti molitve uslišuješ. Svaka pÓut dolazi k tebi');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 65, 4, 'pod teretom grijeha. Naši nas prijestupi taru, ti ih pomiruješ.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 65, 5, 'Blažen kog izabra i k sebi uze: on boravi u dvorima tvojim. Daj da se nasitimo dobrima Doma tvoga i svetošću tvoga Hrama.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 65, 6, 'Čudesno nas uslišuješ u pravednosti svojoj, o Bože, spasenje naše, nado svih krajeva svijeta i mora dalekih.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 65, 7, 'Učvršćuješ bregove jakošću svojom silom opasÄan.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 65, 8, 'Krotiš huku mora, huku valova i buku naroda.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 65, 9, 'Oni što žive nakraj svijeta boje se znamenja tvojih; dveri jutra i večeri radošću napunjaš.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 65, 10, 'Ti pÓohodÄi zemlju i ti je nÓatopÄi, ÓobogatÄi nju veoma. Božja se rijeka vodom napuni, ti pripravi ljudima žito. Ovako pripremi zemlju:');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 65, 11, 'brazde joj natopi, grude joj poravna; kišom je omekša, usjeve joj blagoslovi.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 65, 12, 'Ti okruni godinu dobrotom svojom, plodnost niče za stopama tvojim.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 65, 13, 'Pustinjski pašnjaci kaplju od obilja, brežuljci se pašu radošću.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 65, 14, 'Njive se kite stadima, doline se pokrivaju žitom: svagdje klicanje, pjesma.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 66, 1, 'Zborovođi. Pjesma. Psalam.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 66, 2, 'Kliči Bogu, zemljo sva, opjevaj slavu imena njegova, podaj mu hvalu dostojnu.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 66, 3, 'Recite Bogu: \"Kako su potresna djela tvoja! Zbog velike sile tvoje dušmani ti laskaju.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 66, 4, 'Sva zemlja nek\' ti se klanja i nek\' ti pjeva, neka pjeva tvom imenu!\"');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 66, 5, 'Dođite i gledajte djela Božja: čuda učini među sinovima ljudskim.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 66, 6, 'On pretvori more u zemlju suhu te rijeku pregaziše. Stog\' se njemu radujmo!');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 66, 7, 'Dovijeka vlada jakošću svojom, oči mu paze na narode da se ne izdignu ljudi buntovni.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 66, 8, 'Blagoslivljajte, narodi, Boga našega, razglašujte hvalu njegovu!');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 66, 9, 'Našoj je duši darovao život i ne dade da nam posrne noga.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 66, 10, 'Iskušavao si nas teško, Bože, iskušavao ognjem kao srebro.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 66, 11, 'Pustio si da u zamku padnemo, stisnuo lancima bokove naše.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 66, 12, 'Pustio si da nam zajašu za vrat: prošli smo kroz oganj i vodu, onda si pustio da odahnemo.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 66, 13, 'S paljenicama ću u Dom tvoj ući, zavjete ispuniti pred tobom');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 66, 14, 'što ih obećaše usne moje, što ih usta moja u tjeskobi obrekoše.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 66, 15, 'Prinijet ću ti paljenice s kadom ovnova, žrtvovati volove i jarad.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 66, 16, 'Dođite, počujte, koji se Boga bojite, pripovjedit ću što učini duši mojoj!');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 66, 17, 'Na svoja sam usta njega zvao, jezikom ga hvalio.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 66, 18, 'Da sam u srcu na zlo mislio, ne bi uslišio Gospod.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 66, 19, 'No Bog me uslišio: obazro se na glas molitve moje.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 66, 20, 'Blagoslovljen Bog koji mi molitvu ne odbi, naklonosti ne odvrati od mene!');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 67, 1, 'Zborovođi. Uza žičana glazbala. Psalam. Pjesma.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 67, 2, 'Smilovao nam se Bog i blagoslovio nas, obasjao nas licem svojim,');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 67, 3, 'da bi sva zemlja upoznala putove tvoje, svi puci tvoje spasenje!');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 67, 4, 'Neka te slave narodi, Bože, svi narodi neka te slave!');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 67, 5, 'Nek\' se vesele i kliču narodi, jer sudiš pucima pravedno i narode vodiš na zemlji.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 67, 6, 'Neka te slave narodi, Bože, svi narodi neka te slave!');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 67, 7, 'Zemlja plodom urodila! Bog nas blagoslovio, Bog naš!');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 67, 8, 'Bog nas blagoslovio! Neka ga štuju svi krajevi svjetski!');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 68, 1, 'Zborovođi. Davidov. Psalam. Pjesma.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 68, 2, 'Bog nek\' ustane! Razbježali se dušmani njegovi! Svi mrzitelji njegovi pobjegli pred njim!');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 68, 3, 'Kao što dim iščezava, i njih neka nestane! Kako se vosak topi na ognju, nek\' nestane grešnika pred licem Božjim!');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 68, 4, 'Pravedni neka se raduju, neka klikću pred Bogom, neka kliču od radosti.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 68, 5, 'Pjevajte Bogu, slavite mu ime! Poravnajte put onome koji ide pustinjom - kojemu je ime Jahve - i kličite pred njim!');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 68, 6, 'Otac sirota, branitelj udovica, Bog je u svom svetom šatoru.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 68, 7, 'Napuštene okućit će Jahve, sužnjima pružit\' sretnu slobodu: buntovnici samo ostaše u sažganoj pustinji.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 68, 8, 'Kad si stupao, Bože, pred narodom svojim, dok si prolazio pustinjom,');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 68, 9, 'tresla se zemlja, nebo se rosilo pred Bogom, Sinaj drhtao pred Bogom, Bogom Izraela.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 68, 10, 'Blagoslovljen dažd pustio si, Bože, na baštinu svoju, okrijepio je umornu.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 68, 11, 'Stado se tvoje nastani u njoj, u dobroti, Bože, ti je spremi siromahu.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 68, 12, 'Jahve riječ zadaje, veliko je mnoštvo radosnih vjesnika:');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 68, 13, 'kraljevi vojska bježe te bježe, domaćice plijen dijele.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 68, 14, 'Dok vi počivaste među stadima, krila golubice zablistaše srebrom, a njeno perje žućkastim zlatom:');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 68, 15, 'ondje Svemogući razbijaše kraljeve, a ona poput snijega zablista na Salmonu.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 68, 16, 'Božanska je gora gora bašanska vrletna.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 68, 17, 'Zašto vi, gore vrletne, zavidno gledate na goru gdje se svidje Bogu prebivati? Jahve će na njoj boraviti svagda!');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 68, 18, 'Božja su kola bezbrojna, tisuću tisuća: Jahve sa Sinaja u Svetište dolazi!');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 68, 19, 'Na visinu uzađe vodeći sužnje, na dar si ljude primio, pa i one što ne žele prebivati kod Boga.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 68, 20, 'Blagoslovljen Jahve dan za danom, nosi nas Bog, naš Spasitelj.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 68, 21, 'Bog naš jest Bog koji spasava, Jahve od smrti izbavlja.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 68, 22, 'Zaista, Bog će satrti glave dušmana svojih, kuštravo tjeme onog što hodi u grijesima.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 68, 23, 'Reče Gospodin: \"Iz Bašana ću ih dovesti, dovest ću ih iz dubine mora,');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 68, 24, 'da okupaš nogu u krvi, da jezici tvojih pasa imadnu dio od dušmana.\"');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 68, 25, 'Ulazak ti, Bože, gledaju, ulazak moga Boga i Kralja u Svetište:');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 68, 26, 'sprijeda pjevači, za njima svirači, u sredini djevojke s bubnjićima.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 68, 27, '\"U svečanim zborovima slavite Boga, slavite Jahvu, sinovi Izraelovi!\"');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 68, 28, 'Predvodi ih najmlađi, Benjamin, koji ide pred njima, ondje su knezovi Judini sa četama svojim, knezovi Zebulunovi i knezovi Naftalijevi.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 68, 29, 'Pokaži, Bože, silu svoju, silu kojom se, Bože, boriš za nas');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 68, 30, 'iz Hrama svojega u Jeruzalemu! Nek\' ti kraljevi darove donose!');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 68, 31, 'Ukroti neman u trsci, stado bikova s teladi naroda! Neka se prostru pred tobom sa srebrnim žezlima: rasprši narode koji se ratu vesele!');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 68, 32, 'Nek\' dođu velikani iz Egipta, Etiopija nek\' pruži ruke Bogu!');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 68, 33, 'Sva kraljevstva svijeta, pjevajte Bogu, slavite Jahvu,');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 68, 34, 'koji se vozi po nebu, po nebu iskonskom! Čuj, glasom grmi, glasom svojim silnim:');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 68, 35, '\"Priznajte silu Božju!\" Nad Izraelom veličanstvo njegovo, u oblacima sila njegova!');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 68, 36, 'Strašan je Bog iz svojega Svetišta. Bog Izraelov daje moć i silu narodu svojemu. Blagoslovljen Bog!');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 69, 1, 'Zborovođi. Po napjevu \"Ljiljani\". Davidov.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 69, 2, 'Spasi me, Bože: vode mi dođoše do grla!');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 69, 3, 'U duboko blato zapadoh i nemam kamo nogu staviti; u duboku tonem vodu, pokrivaju me valovi.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 69, 4, 'Iznemogoh od vikanja, grlo mi je promuklo, oči mi klonuše Boga mog čekajuć\'.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 69, 5, 'Brojniji su od vlasi na glavi mojoj oni koji me mrze nizašto. Tvrđi su od kostiju mojih oni što mi se nepravedno protive: zar mogu vratiti što nisam oteo?');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 69, 6, 'Bože, ti znadeš bezumnost moju, moji ti grijesi nisu sakriti.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 69, 7, 'Nek\' se ne postide zbog mene koji se u te uzdaju, Gospode, Jahve nad Vojskama! Neka se ne posrame zbog mene koji traže tebe, Bože Izraelov!');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 69, 8, 'Jer zbog tebe podnesoh pogrdu, i stid mi pokri lice.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 69, 9, 'Tuđinac postadoh braći i stranac djeci majke svoje.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 69, 10, 'Jer me izjela revnost za Dom tvoj i poruge onih koji se rugaju tebi padoše na me.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 69, 11, 'Dušu sam postom mučio, okrenulo mi se u ruglo.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 69, 12, 'Uzeh kostrijet za haljinu, i postah im igračka.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 69, 13, 'Koji sjede na vratima protiv mene govore, vinopije mi rugalice poju.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 69, 14, 'No tebi se molim, Jahve, u vrijeme milosti, Bože; po velikoj dobroti svojoj ti me usliši po svojoj vjernoj pomoći!');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 69, 15, 'Izvuci me iz blata da ne potonem, od onih koji me mrze izbavi me - iz voda dubokih.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 69, 16, 'Nek\' me ne pokriju valovi, nek\' me ne proguta dubina, nek\' bezdan ne zatvori usta nada mnom!');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 69, 17, 'Usliši me, Jahve, jer je dobrostiva milost tvoja, po velikom milosrđu pogledaj na me!');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 69, 18, 'Ne sakrivaj lica pred slugom svojim; jer sam u stisci, usliši me brzo!');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 69, 19, 'Približi se duši mojoj i spasi je; zbog dušmana mojih oslobodi me!');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 69, 20, 'Ti mi znadeš porugu, stid i sramotu, pred tvojim su očima svi koji me muče.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 69, 21, 'Ruganje mi slomilo srce i klonuh; čekao sam da se tko sažali nada mnom, ali ga ne bi; i da me tko utješi, ali ga ne nađoh.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 69, 22, 'U jelo mi žuči umiješaše, u mojoj me žeđi octom napojiše.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 69, 23, 'Nek\' im stol bude zamka, a žrtvene gozbe stupica!');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 69, 24, 'Nek\' im potamne oči da ne vide, nek\' im bokovi zasvagda oslabe!');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 69, 25, 'Izlij na njih ljutinu, žar tvoga gnjeva nek\' ih zahvati!');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 69, 26, 'Njihova kuća nek\' opusti, u njihovu šatoru nek\' nitko ne stanuje!');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 69, 27, 'Jer su progonili koga ti pokara, bol povećaše onomu koga ti rani.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 69, 28, 'Na njihovu krivnju krivnju još dodaj, ne opravdali se pred tobom!');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 69, 29, 'Nek\' budu izbrisani iz knjige živih, među pravednike neka se ne broje!');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 69, 30, 'A ja sam jadnik i bolnik - nek\' me štiti tvoja pomoć, o Bože!');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 69, 31, 'Božje ću ime hvaliti popijevkom, hvalit ću ga zahvalnicom.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 69, 32, 'Bit će to milije Jahvi no bik žrtveni, milije nego junac s papcima i rozima.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 69, 33, 'Gledajte, ubogi, i radujte se, nek\' vam oživi srce, svima koji Boga tražite.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 69, 34, 'Jer siromahe Jahve čuje, on ne prezire sužanja svojih.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 69, 35, 'Neka ga hvale nebesa i zemlja, mora i sve što se u njima miče.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 69, 36, 'Jer Bog će spasiti Sion - on će sagradit\' gradove Judine - tu će oni stanovat\', imati baštinu.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 69, 37, 'Baštinit će ga potomci slugu njegovih; prebivat će u njemu oni što ljube ime Božje.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 70, 1, 'Zborovođi. Davidov. Za spomen.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 70, 2, 'O Bože, spasi me, Jahve, u pomoć mi pohitaj!');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 70, 3, 'Nek\' se postide i smetu svi koji mi o glavi rade! Nek\' odstupe i nek\' se posrame koji se nesreći mojoj raduju!');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 70, 4, 'Nek\' uzmaknu u sramoti svojoj koji zlurado na me grohoću!');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 70, 5, 'Neka kliču i nek\' se vesele u tebi svi koji tebe traže! Neka govore svagda: \"Velik je Bog!\" svi koji spasenje tvoje ljube!');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 70, 6, 'A bijedan sam ja i nevoljan, o Bože, u pomoć mi pohitaj! Ti si pomoć moja i spasitelj; Jahve, ne kasni!');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 71, 1, 'Tebi si, Jahve, utječem, ne daj da se ikada postidim!');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 71, 2, 'U pravdi me svojoj spasi i izbavi, prikloni uho k meni i spasi me!');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 71, 3, 'Budi mi hrid utočišta i čvrsta utvrda spasenja: jer ti si stijena i utvrda moja.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 71, 4, 'Bože moj, istrgni me iz ruke zlotvora, iz šake silnika i tlačitelja:');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 71, 5, 'jer ti si, o Gospode, ufanje moje, Jahve, uzdanje od moje mladosti!');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 71, 6, 'Na te se oslanjam od utrobe; ti si mi zaštitnik od majčina krila: u te se svagda uzdam.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 71, 7, 'Mnogima postadoh čudo, jer ti si mi bio silna pomoć.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 71, 8, 'Usta mi bijahu puna tvoje hvale, slaviše te svaki dan!');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 71, 9, 'Ne zabaci me u starosti: kad mi malakšu sile, ne zapusti me!');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 71, 10, 'Jer govore o meni moji dušmani, i koji me vrebaju složno se svjetuju:');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 71, 11, '\"Bog ga je napustio; progonite ga i uhvatite jer nema tko da ga spasi!\"');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 71, 12, 'O Bože, ne stoj daleko od mene, Bože moj, pohitaj mi u pomoć!');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 71, 13, 'Neka se postide i propadnu koji traže moj život; nek\' se sramotom i stidom pokriju koji mi žele nesreću!');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 71, 14, 'A ja ću se uvijek uzdati, iz dana u dan hvaleć\' te sve više.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 71, 15, 'Ustima ću naviještati pravednost tvoju, povazdan pomoć tvoju: jer im ne znam broja.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 71, 16, 'Kazivat ću silu Jahvinu, Gospode, slavit ću samo tvoju pravednost.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 71, 17, 'Bože, ti mi bijaše učitelj od mladosti moje, i sve do sada naviještam čudesa tvoja.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 71, 18, 'Ni u starosti, kad posijedim, Bože, ne zapusti me, da kazujem mišicu tvoju naraštaju novom i svima budućima silu tvoju,');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 71, 19, 'i pravednost tvoju, Bože, koja seže do neba, kojom učini velika djela. Bože, tko je kao ti!');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 71, 20, 'Trpljenja mnoga i velika bacio si na me: ali ti ćeš me opet oživiti i opet me podići iz dubine zemlje.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 71, 21, 'Povećaj dostojanstvo moje i opet me utješi:');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 71, 22, 'A ja ću uz harfu slaviti tvoju vjernost, o Bože, svirat ću ti u citaru, Sveče Izraelov!');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 71, 23, 'Moje će usne klicati pjevajuć\' tebi i moja duša koju si spasio.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 71, 24, 'I moj će jezik svagda slaviti pravdu tvoju, jer su postiđeni i posramljeni oni što traže moju nesreću.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 72, 1, 'Salomonov. Bože, sud svoj daj kralju i svoju pravdu sinu kraljevu.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 72, 2, 'Nek\' puku tvojem sudi pravedno, siromasima po pravici!');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 72, 3, 'Nek\' bregovi narodu urode mirom, a brežuljci pravdom.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 72, 4, 'Sudit će pravo ubogim pučanima, djeci siromaha donijet će spasenje, a tlačitelja on će smrviti.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 72, 5, 'I živjet će dugo kao sunce i kao mjesec u sva pokoljenja.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 72, 6, 'Sići će kao rosa na travu, kao kiša što natapa zemlju!');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 72, 7, 'U danima njegovim cvjetat će pravda i mir velik - sve dok bude mjeseca.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 72, 8, 'I vladat će od mora do mora i od Rijeke do granica svijeta.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 72, 9, 'Dušmani će njegovi preda nj kleknuti i protivnici lizati prašinu.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 72, 10, 'Kraljevi Taršiša i otoka nosit će dare, vladari od Arabije i Sabe danak donositi.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 72, 11, 'Klanjat će mu se svi vladari, svi će mu narodi služiti.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 72, 12, 'On će spasiti siromaha koji uzdiše, nevoljnika koji pomoćnika nema;');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 72, 13, 'smilovat će se ubogu i siromahu i spasit će život nevoljniku:');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 72, 14, 'oslobodit će ih nepravde i nasilja, jer je dragocjena u njegovim očima krv njihova.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 72, 15, 'Stog\' neka živi! Neka ga daruju zlatom iz Arabije, nek\' mole za njega svagda i neka ga blagoslivljaju!');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 72, 16, 'Nek\' bude izobila žita u zemlji, po vrhuncima klasje neka šušti k\'o Libanon! I cvjetali stanovnici gradova kao trava na livadi.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 72, 17, 'Bilo ime njegovo blagoslovljeno dovijeka! Dok je sunca, živjelo mu ime! Njim se blagoslivljala sva plemena zemlje, svi narodi nazivali blaženima!');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 72, 18, 'Blagoslovljen Jahve, Bog Izraelov, koji jedini tvori čudesa!');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 72, 19, 'I blagoslovljeno slavno mu ime dovijeka! Sva se zemlja napunila slave njegove! Tako neka bude. Amen!');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 72, 20, 'Time se završavaju molitve Jišajeva sina Davida.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 73, 1, 'Psalam. Asafov Kako je dobar Bog čestitima, Bog onima koji su čista srca!');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 73, 2, 'A meni umalo noge ne posrnuše, zamalo koraci ne okliznuše,');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 73, 3, 'jer zločincima zavidjeh motreći sreću grešnika.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 73, 4, 'Nikakvu patnju ne snose, pretilo je tijelo njihovo.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 73, 5, 'Ne žive u mukama smrtnika, ljudske ih nevolje ne biju.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 73, 6, 'Stoga je oholost ogrlica vratu njihovu, a nasilje haljina koja ih pokriva.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 73, 7, 'Iz pretila srca izlazi opakost njihova, srca im se prelijevaju ispraznim tlapnjama.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 73, 8, 'Podsmjehuju se i zlobno govore, nasiljem prijete odozgo.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 73, 9, 'Ustima na nebo nasrću, a jezik se njihov obara na zemlju.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 73, 10, 'Zato moj narod za njima leti i srče obilne vode');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 73, 11, 'pa veli: \"Kako da dozna Bog? Spoznaje li Svevišnji?\"');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 73, 12, 'Eto, takvi su grešnici: uvijek spokojni, bogatstvo zgrću.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 73, 13, 'Jesam li, dakle, samo ja uzalud čuvao srce čisto i u nedužnosti prao ruke');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 73, 14, 'kad sam primao udarce svaki dan i kaznu jutro za jutrom?');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 73, 15, 'Da sam kazao: \"Govorit ću kao i oni\", izdao bih rod sinova tvojih.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 73, 16, 'Promišljah tada da bih spoznao: al\' mi se učini mučno u očima mojim');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 73, 17, 'sve dok ne nađoh ulaz u Božje svetinje pa prozreh kakav im je svršetak.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 73, 18, 'Zaista, na klizavu stazu ti ih postavljaš, u propast ih obaraš.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 73, 19, 'Kako učas propadoše, nestaše, užas ih izjede!');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 73, 20, 'Kao što čovjek prezire san kad se probudi, tako ćeš, Gospode, prezreti lik im kada ustaneš.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 73, 21, 'Kad mi duša bijaše ojađena, a bubrezi probodeni,');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 73, 22, 'bezumnik bijah bez razbora, k\'o živinče pred tobom.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 73, 23, 'Al\' ću odsad uvijek biti s tobom, jer ti prihvati desnicu moju:');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 73, 24, 'vodit ćeš me po naumu svojem da me zatim uzmeš u slavu svoju.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 73, 25, 'Koga ja imam u nebu osim tebe? Kad sam s tobom, ne veselim se zemlji.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 73, 26, 'Malaksalo mi tijelo i srce: okrilje srca moga, i baštino moja, o Bože, dovijeka!');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 73, 27, 'Doista, propast će oni koji se udaljuju od tebe, istrebljuješ svakog tko ti se iznevjeri.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 73, 28, 'A meni je milina biti u Božjoj blizini, imati sklonište svoje u Jahvi. Pripovijedat ću sva tvoja djela na vratima Kćeri sionske.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 74, 1, 'Poučna pjesma. Asafova. Zašto si, Bože, posve zabacio, zašto kiptiš gnjevom na ovce paše svoje?');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 74, 2, 'Sjeti se zajednice koju si davno stekao, plÓemena koje namače kao svoju baštinu i brda Siona gdje si Šator svoj udario!');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 74, 3, 'Korakni k ruševinama vječnim - sve je u Svetištu razorio neprijatelj.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 74, 4, 'Protivnici tvoji vikahu posred skupštine tvoje, znakove svoje postaviše k\'o pobjedne znakove.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 74, 5, 'Bijahu kao oni koji mašu sjekirom po guštari,');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 74, 6, 'sjekirom i maljem vrata mu razbijali.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 74, 7, 'Ognju predadoše Svetište tvoje, do zemlje oskvrnuše Prebivalište tvoga imena.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 74, 8, 'Rekoše u srcu: \"Istrijebimo ih zajedno; spalite sva svetišta Božja na zemlji!\"');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 74, 9, 'Ne vidimo znakova svojih, proroka više nema, i nitko među nama ne zna dokle...');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 74, 10, 'Dokle će se još, o Bože, dušmanin rugati? Hoće li protivnik dovijeka prezirati ime tvoje?');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 74, 11, 'Zašto povlačiš ruku, zašto u krilu sakrivaš desnicu svoju?');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 74, 12, 'No Bog je moj kralj od davnine, on koji posred zemlje spasava!');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 74, 13, 'Ti svojom silom rasječe more, smrska glave nakazama u vodi.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 74, 14, 'Ti si Levijatanu glave zdrobio, dao ga za hranu nemanima morskim.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 74, 15, 'Ti si dao da provre izvor i bujica, ti si presušio rijeke nepresušne.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 74, 16, 'Tvoj je dan i noć je tvoja, ti učvrsti mjesec i sunce;');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 74, 17, 'ti sazda sve granice zemlji, ti stvori ljeto i zimu.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 74, 18, 'Spomeni se ovoga: dušmanin ti se rugaše, Jahve, i bezumni narod pogrdi ime tvoje.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 74, 19, 'Ne predaj jastrebu život grlice svoje, i život svojih siromaha ne zaboravi zauvijek!');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 74, 20, 'Pogledaj na Savez svoj, jer svi su zakuci zemlje puni tmina i nasilja.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 74, 21, 'Ne daj da jadnik otiđe postiđen: neka siromah i ubog hvale ime tvoje!');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 74, 22, 'Ustani, Bože, zauzmi se za svoju parnicu, spomeni se pogrde koju ti bezumnik svaki dan nanosi.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 74, 23, 'Ne zaboravi vike neprijatelja svojih: buka buntovnika još se diže k tebi!');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 75, 1, 'Zborovođi. Po napjevu \"Ne razori!\" Psalam. Asafov. Pjesma.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 75, 2, 'Slavimo te, Bože, slavimo i zazivamo ime tvoje, pripovijedamo čudesa tvoja.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 75, 3, '\"Kad odredim vrijeme, sudit ću po pravu.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 75, 4, 'Pa neka se strese zemlja sa stanovnicima svojim, ja sam učvrstio stupove njezine.\"');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 75, 5, 'Drznike opominjem: \"Ne budite drski!\" bezbožnike: \"Ne budite tako rogati!\"');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 75, 6, 'Ne dižite roga svog protiv Neba, nemojte govoriti drsko na Boga!');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 75, 7, 'Jer niti sa istoka niti sa zapada, niti iz pustinje niti sa bregova...');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 75, 8, 'Bog je koji sudi: ovoga snizuje, onog uzvisuje!');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 75, 9, 'Jer je u Jahvinoj ruci pehar pun vina pjenušava, začinjena mirisnim travama; iz njega on napaja, do taloga će ga iskapiti i ispiti svi zlotvori svijeta.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 75, 10, 'A ja ću klicati dovijeka, pjevat ću Bogu Jakovljevu.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 75, 11, 'Rogove ću polomiti bezbožniku, a pravednik će podići glavu.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 76, 1, 'Zborovođi. Uza žičana glazbala. Psalam. Asafov. Pjesma.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 76, 2, 'Na glasu je Bog u Judeji, u Izraelu veliko je ime njegovo!');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 76, 3, 'U Šalemu je Šator njegov, na Sionu boravište.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 76, 4, 'Tu polomi strijele lukovima, štitove, mačeve, sve oružje.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 76, 5, 'Blistav si od svjetla, veličanstveniji od bregova drevnih.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 76, 6, 'Opljačkani su oni koji bijahu jaki srcem, i san svoj snivaju - klonuše ruke svim hrabrima.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 76, 7, 'Od prijetnje tvoje, Bože Jakovljev, skameniše se kola i konji.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 76, 8, 'Strašan si ti, i tko da opstane kraj žestine gnjeva tvojega.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 76, 9, 'S neba reče presudu - od straha zemlja zadrhta i zanijemje');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 76, 10, 'kad se diže Bog da sudi, da spasi uboge na zemlji.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 76, 11, 'Jer će te i bijes Edoma slaviti, i preživjeli iz Hamata štovat će te.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 76, 12, 'Zavjetujte i izvršite zavjete Jahvi, Bogu svojemu, svi oko njega neka donose darove Strašnome');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 76, 13, 'koji obuzdava oholost knezova, koji je strašan kraljevima zemlje.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 77, 1, 'Zborovođi. Po Jedutunu. Asafov. Psalam.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 77, 2, 'Glasom svojim Bogu vapijem, glas mi se Bogu diže i on me čuje.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 77, 3, 'U dan nevolje tražim Gospodina, noću mi se ruka neumorno pruža k njemu, ne može se utješit\' duša moja.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 77, 4, 'Spominjem se Boga i uzdišem; kad razmišljam, daha mi nestane.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 77, 5, 'Vjeđe moje držiš, potresen sam, ne mogu govoriti.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 77, 6, 'Mislim na drevne dane i sjećam se davnih godina;');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 77, 7, 'razmišljam noću u srcu, mislim, i duh moj ispituje:');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 77, 8, '\"Hoće li Gospodin odbaciti zauvijek i hoće li ikad još biti milostiv?');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 77, 9, 'Je li njegova dobrota minula zauvijek, njegovo obećanje propalo za sva pokoljenja?');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 77, 10, 'Zar Bog je zaboravio da se smiluje, ili je gnjevan zatvorio smilovanje svoje?\"');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 77, 11, 'I govorim: \"Ovo je bol moja: promijenila se desnica Višnjega.\"');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 77, 12, 'Spominjem se djela Jahvinih, sjećam se tvojih pradavnih čudesa.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 77, 13, 'Promatram sva djela tvoja, razmatram ono što si učinio.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 77, 14, 'Svet je tvoj put, o Bože: koji je bog tako velik kao Bog naš?');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 77, 15, 'Ti si Bog koji čudesa stvaraš, na pucima si pokazao silu svoju.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 77, 16, 'Mišicom si izbavio narod svoj, sinove Jakovljeve i Josipove.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 77, 17, 'Vode te ugledaše, Bože, ugledaše te vode i ustuknuše, bezdani se uzburkaše.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 77, 18, 'Oblaci prosuše vode, oblaci zatutnjiše gromom i tvoje strijele poletješe.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 77, 19, 'Grmljavina tvoja u vihoru zaori, munje rasvijetliše krug zemaljski, zemlja se zatrese i zadrhta.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 77, 20, 'Kroz more put se otvori tebi i tvoja staza kroz vode goleme, a tragova tvojih nitko ne vidje.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 77, 21, 'Ti si svoj narod vodio kao stado rukama Mojsija i Arona.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 78, 1, 'Poučna pjesma. Asafova. Poslušaj, narode moj, moju nauku, prikloni uho riječima usta mojih!');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 78, 2, 'Otvorit ću svoja usta na pouku, iznijet ću tajne iz vremena davnih.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 78, 3, 'Ono što čusmo i saznasmo, što nam kazivahu oci,');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 78, 4, 'nećemo kriti djeci njihovoj, predat ćemo budućem koljenu: slavu Jahvinu i silu njegovu i djela čudesna što ih učini.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 78, 5, 'Svjedočanstvo podiže on u Jakovu, Zakon postavi u Izraelu, da ono što naredi ocima našim oni djeci svojoj objave,');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 78, 6, 'da sazna budući naraštaj, i sinovi koji će se roditi da djeci svojoj kazuju');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 78, 7, 'da u Boga ufanje svoje stave i ne zaborave djela Božjih, već da vrše zapovijedi njegove,');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 78, 8, 'kako ne bi bili, kao oci njihovi, naraštaj buntovan, prkosan - naraštaj srcem nestalan i duhom Bogu nevjeran.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 78, 9, 'Sinovi Efrajimovi, ratnici s lukom, u dan bitke okrenuše leđa.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 78, 10, 'Saveza s Bogom ne održaše i ne htjedoše hoditi po Zakonu njegovu.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 78, 11, 'Zaboraviše na djela njegova, na čudesa koja im pokaza.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 78, 12, 'Pred njihovim ocima činio je znakove u Egiptu, u Soanskom polju.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 78, 13, 'On more razdijeli i njih prevede, vode kao nasip uzdiže.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 78, 14, 'Danju ih vodio oblakom, a svu noć ognjem blistavim.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 78, 15, 'U pustinji hrid prolomi i napoji ih obilno kao iz bezdana.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 78, 16, 'Iz stijene izbi potoke te izvede vode k\'o velike rijeke.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 78, 17, 'A oni jednako griješiše, prkosiše Višnjem u pustinji.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 78, 18, 'Boga su kušali u srcima svojim ištuć\' jela svojoj pohlepnosti.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 78, 19, 'Prigovarali su Bogu i pitali: \"Može li Gospod stol u pustinji prostrti?');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 78, 20, 'Eno, udari u hrid, i voda poteče i provreše potoci: a može li dati i kruha, i mesa pružiti svome narodu?\"');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 78, 21, 'Kad to začu Jahve, gnjevom usplamtje: oganj se raspali protiv Jakova, srdžba se razjari protiv Izraela,');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 78, 22, 'jer ne vjerovaše Bogu niti se u njegovu pomoć uzdaše.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 78, 23, 'Pa ozgo naredi oblaku i otvori brane nebeske,');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 78, 24, 'k\'o kišu prosu na njih mÓanu da jedu i nahrani ih kruhom nebeskim.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 78, 25, 'Čovjek blagovaše kruh Jakih; on im dade hrane do sitosti.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 78, 26, 'Probudi na nebu vjetar istočni i svojom silom južnjak dovede.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 78, 27, 'Prosu na njih mesa k\'o prašine i ptice krilatice k\'o pijeska morskoga.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 78, 28, 'Padoše usred njihova tabora i oko šatora njihovih.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 78, 29, 'Jeli su i nasitili se, želju njihovu on im ispuni.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 78, 30, 'Još nisu svoju utažili pohlepu i jelo im još bješe u ustima,');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 78, 31, 'kad se srdžba Božja na njih raspali: pokosi smrću prvake njihove i mladiće pobi Izraelove.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 78, 32, 'Uza sve to griješiše dalje i ne vjerovaše u čudesna djela njegova.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 78, 33, 'I skonča im dane jednim dahom i njihova ljeta naglim svršetkom.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 78, 34, 'Kad ih ubijaše, tražiše ga i opet pitahu za Boga;');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 78, 35, 'spominjahu se da je Bog hridina njihova i Svevišnji njihov otkupitelj.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 78, 36, 'Ali ga opet ustima svojim varahu i jezikom svojim lagahu njemu.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 78, 37, 'Njihovo srce s njime ne bijaše, nit\' bijahu vjerni Savezu njegovu.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 78, 38, 'A on im milosrdno grijeh praštao i nije ih posmicao; često je gnjev svoj susprezao da ne plane svom jarošću.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 78, 39, 'Spominjao se da su pÓut i dah koji odlazi i ne vraća se više.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 78, 40, 'Koliko mu prkosiše u pustinji i žalostiše ga u samotnom kraju!');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 78, 41, 'Sve nanovo iskušavahu Boga i vrijeđahu Sveca Izraelova');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 78, 42, 'ne spominjuć\' se ruke njegove ni dana kad ih od dušmana izbavi,');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 78, 43, 'ni znakova njegovih u Egiptu, ni čudesnih djela u polju Soanskom.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 78, 44, 'U krv im pretvori rijeke i potoke, da ne piju.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 78, 45, 'Posla na njih obade da ih žderu i žabe da ih more.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 78, 46, 'I predade skakavcu žetvu njihovu, i plod muke njihove žderaču.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 78, 47, 'Vinograde im tučom udari, a mrazom smokvike njihove.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 78, 48, 'I predade grÓadu njihova goveda i munjama stada njihova.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 78, 49, 'Obori na njih svu žestinu gnjeva svog, jarost, bijes i nevolju: posla na njih anđele nesreće.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 78, 50, 'I put gnjevu svojem otvori: ne poštedje im život od smrti, životinje im izruči pošasti.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 78, 51, 'Pobi u Egiptu sve prvorođeno, prvence u šatorju Hamovu.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 78, 52, 'I povede narod svoj kao ovce i vođaše ih kao stado kroz pustinju.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 78, 53, 'Pouzdano ih je vodio te se nisu bojali, a more je prekrilo dušmane njihove.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 78, 54, 'U Svetu zemlju svoju on ih odvede, na bregove što mu ih osvoji desnica.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 78, 55, 'Pred njima istjera pogane, konopom im podijeli baštinu, pod šatorjem njihovim naseli plemena izraelska.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 78, 56, 'A oni iskušavali i gnjevili Boga Višnjega i nisu držali zapovijedi njegovih.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 78, 57, 'Otpadoše, iznevjeriše se k\'o oci njihovi, k\'o luk nepouzdan oni zatajiše.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 78, 58, 'Na gnjev ga nagnaše svojim uzvišicama, na ljubomor navedoše kumirima svojim.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 78, 59, 'Bog vidje i gnjevom planu, odbaci posve Izraela.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 78, 60, 'I napusti boravište svoje u Šilu, Šator u kojem prebivaše s ljudima.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 78, 61, 'Preda u ropstvo snagu svoju i svoju diku u ruke dušmanske.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 78, 62, 'Narod svoj prepusti maču, raspali se na svoju baštinu.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 78, 63, 'Mladiće njihove oganj proguta, ne udaše se djevice njihove.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 78, 64, 'Svećenici njihovi padoše od mača, ne zaplakaše Óudove njihove.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 78, 65, 'Tad se k\'o oda sna trgnu Gospodin, k\'o ratnik vinom savladan.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 78, 66, 'Udari otraga dušmane svoje, sramotu im vječitu zadade.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 78, 67, 'On odbaci šator Josipov i Efrajimovo pleme ne odabra,');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 78, 68, 'već odabra pleme Judino i goru Sion koja mu omilje.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 78, 69, 'Sagradi Svetište k\'o nebo visoko, k\'o zemlju utemelji ga dovijeka.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 78, 70, 'Izabra Davida, slugu svojega, uze ga od torova ovčjih;');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 78, 71, 'odvede ga od ovaca dojilica da pase Jakova, narod njegov, Izraela, baštinu njegovu.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 78, 72, 'I pasao ih je srcem čestitim i brižljivim rukama vodio.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 79, 1, 'Psalam. Asafov. Bože, pogani, evo, provališe u baštinu tvoju, tvoj sveti Hram oskvrnuše, pretvoriše Jeruzalem u ruševine.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 79, 2, 'Trupla tvojih slugu dadoše za hranu pticama nebeskim, meso tvojih pobožnika zvijerima zemaljskim.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 79, 3, 'Krv im k\'o vodu prolijevahu oko Jeruzalema i ne bijaše nikoga da ih pokopa.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 79, 4, 'Postadosmo sramota susjedima svojim, podsmijeh i ruglo svima oko nas.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 79, 5, 'Dokle još, Jahve? Zar ćeš se svagda srditi? Zar će ljubomora tvoja poput ognja gorjeti?');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 79, 6, 'Izlij gnjev na pogane koji te ne priznaju i na kraljevstva što ne zazivlju ime tvoje!');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 79, 7, 'Jer izjedoše Jakova i opustošiše boravište njegovo.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 79, 8, 'Ne spominji se, protiv nas, grijeha otaca; neka nas pretekne smilovanje tvoje jer smo jadni i nevoljni.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 79, 9, 'Pomozi nam, Bože, pomoći naša, zbog slave imena svojega, oslobodi nas i otpusti nam grijehe zbog imena svoga!');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 79, 10, 'Zašto da pogani govore: \"TÓa gdje je njihov Bog?\" Nek\' se na poganima pokaže, pred očima našim, kako osvećuješ prolivenu krv slugu svojih!');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 79, 11, 'Nek\' do tebe dopru uzdasi sužanja, snagom svoje mišice poštedi predane smrti!');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 79, 12, 'A našim susjedima vrati sedmerostruko u krilo pogrdu koju naniješe tebi, o Jahve!');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 79, 13, 'A mi, tvoj puk i ovce paše tvoje, slavit ćemo te dovijeka, kazivat ćemo od koljena do koljena hvalu tvoju!');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 80, 1, 'Zborovođi. Po napjevu \"Ljiljan svjedočanstva\". Asafov. Psalam.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 80, 2, 'Pastiru Izraelov, počuj, ti što vodiš Josipa k\'o stado ovaca! Ti što sjediš nad kerubima, zablistaj');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 80, 3, 'pred Efrajimom, Benjaminom, Manašeom: probudi silu svoju, priteci nam u pomoć!');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 80, 4, 'Bože, obnovi nas, razvedri lice svoje i spasi nas!');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 80, 5, 'Jahve, Bože nad Vojskama, dokle ćeš plamtjeti, premda se moli narod tvoj?');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 80, 6, 'Dokle ćeš nas hraniti kruhom suza i obilno pojiti suzama?');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 80, 7, 'Dokle će se oko nas svađat\' susjedi i rugat\' nam se naši dušmani?');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 80, 8, 'Bože nad Vojskama, obnovi nas, razvedri lice svoje i spasi nas!');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 80, 9, 'Ti prenese čokot iz Egipta, pogane istjera, a njega zasadi.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 80, 10, 'Ti mu tlo pripravi, i on pusti korijenje i napuni zemlju.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 80, 11, 'Sjena mu prekri bregove, lozje mu k\'o Božji cedrovi.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 80, 12, 'Mladice svoje ispruži do mora i svoje ogranke do Rijeke.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 80, 13, 'Zašto si mu srušio ogradu da ga beru svi što putem prolaze,');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 80, 14, 'da ga pustoši vepar iz šume, da ga pasu poljske zvijeri?');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 80, 15, 'Vrati se, Bože nad Vojskama, pogledaj s neba i vidi, obiđi ovaj vinograd:');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 80, 16, 'zakrili što zasadi desnica tvoja, sina kog za se odgoji!');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 80, 17, 'Oni koji ga spališe i posjekoše nek\' izginu od prijetnje lica tvojega!');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 80, 18, 'Tvoja ruka nek\' bude nad čovjekom desnice tvoje, nad sinom čovječjim kog za se odgoji!');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 80, 19, 'Nećemo se više odmetnuti od tebe; poživi nas, a mi ćemo zazivati ime tvoje.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 80, 20, 'Jahve, Bože nad Vojskama, obnovi nas, razvedri lice svoje i spasi nas!');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 81, 1, 'Zborovođi. Po napjevu \"Tijesci\". Asafov.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 81, 2, 'Kliknite Bogu, našoj jakosti, kličite Bogu Jakovljevu!');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 81, 3, 'Nek\' zazvuče žice, nek\' se čuje bubanj, svirajte u milozvučnu harfu s citarom!');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 81, 4, 'Zatrubite u rog za mlađaka, za uštapa, na svetkovinu našu!');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 81, 5, 'Jer to je propis Izraelu, zapovijed Boga Jakovljeva.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 81, 6, 'Takav je zakon dao Josipu kad je izlazio iz zemlje Egipta.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 81, 7, 'Šapat tajnovit čuh: \"Oslobodih od tereta rame njegovo, ruke su mu slobodne od košare.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 81, 8, 'U tjeskobi si zavapio i ja te izbavih; iz gromovna oblaka odgovorih tebi, iskušah te kod voda meripskih.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 81, 9, 'Slušaj, puče moj, i ja ću te opomenuti: o, da me poslušaš, Izraele!');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 81, 10, 'Nek\' ne bude u tebe drugog boga i ne klanjaj se bogu tuđem!');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 81, 11, 'Ja sam Jahve, Bog tvoj koji te izvedoh iz Egipta: otvori svoja usta da ih napunim!\"');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 81, 12, '\"Ali moj narod ne slušaše glasa moga, Izrael me ne posluša.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 81, 13, 'Zato ga pustih okorjelom srcu njegovu: neka hodi kako mu se hoće!');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 81, 14, 'O, kad bi me narod moj slušao, kad bi Izrael putovima mojim hodio,');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 81, 15, 'brzo bih pokorio dušmane njegove, ruku bih svoju okrenuo na protivnike njegove.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 81, 16, 'Oni što ga sada mrze dodvarali bi mu se i njihov bi udes bio zapečaćen zauvijek.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 81, 17, 'A svoj narod hranio bih pšenicom najboljom i sitio ga medom iz pećine.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 82, 1, 'Psalam. Asafov. Bog ustaje u skupštini \"bogova\", usred \"bogova\" sud održava.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 82, 2, '\"Dokle ćete sudit\' krivo, ić\' na ruku bezbožnima?');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 82, 3, 'Štitite slaba i sirotu, vratite pravicu jadniku i siromahu!');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 82, 4, 'Izbavite potlačenog i ubogog: istrgnite ga iz ruku bezbožnih!\"');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 82, 5, 'Ne shvaćaju nit\' razumiju, po mraku hodaju: poljuljani su svi temelji zemlje.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 82, 6, 'Rekoh doduše: \"Vi ste bogovi i svi ste sinovi Višnjega!');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 82, 7, 'Ali ćete k\'o svi ljudi umrijeti, past ćete kao svatko od velikih!\"');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 82, 8, 'Ustani, Bože, i sudi zemlju, jer si s pravom gospodar svih naroda.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 83, 1, 'Pjesma. Psalam. Asafov.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 83, 2, 'Ne šuti, Jahve, ne budi nijem i nemoj mirovati, Bože!');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 83, 3, 'Jer evo: dušmani tvoji buče, i mrzitelji tvoji glave podižu.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 83, 4, 'Protiv naroda se tvoga rote i svjetuju se protiv štićenika tvojih.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 83, 5, 'Govore: \"Dođite, zatrimo ih da ne budu narod, nek\' se ime Izrael više ne spominje!\"');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 83, 6, 'Zaista, jednodušno se svjetuju i protiv tebe savez sklopiše:');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 83, 7, 'šatori edomski i Jišmaelci, Moapci i Hagrijci,');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 83, 8, 'Gebal i Amon i Amalek, Filisteja sa stanovnicima Tira.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 83, 9, 'I Asirci se s njima udružiše, pružiše ruke potomcima Lotovim.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 83, 10, 'Učini njima k\'o Midjancima, k\'o Siseri i Jabinu na potoku Kišonu:');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 83, 11, 'koji padoše blizu En-Dora i postaše gnojivo njivi.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 83, 12, 'K\'o Oreb i Zeb neka budu knezovi njihovi, kao Zebah i Salmuna nek\' budu sve vođe njihove');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 83, 13, 'koji jednodušno vikahu: \"Osvojimo krajeve Božje!\"');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 83, 14, 'Daj, o Bože, da budu kao kovitlac, kao pljeva koju nosi vjetar.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 83, 15, 'Kao što oganj proždire šumu, kao što plamen sažiže bregove,');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 83, 16, 'tako ih goni olujom svojom, prestravi ih svojom žestinom!');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 83, 17, 'Pokrij im lice sramotom, da traže tvoje ime, Jahve!');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 83, 18, 'Neka se stide i plaše navijek, neka se posrame i neka izginu!');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 83, 19, 'Nek\' znaju: ti si komu je ime Jahve, jedini Višnji nada svom zemljom.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 84, 1, 'Zborovođi. Po napjevu \"Tijesci\". Sinova Korahovih.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 84, 2, 'Kako su mili stanovi tvoji, Jahve nad Vojskama!');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 84, 3, 'Duša mi gine i čezne za dvorima Jahvinim. Srce moje i moje tijelo kliču Bogu živomu.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 84, 4, 'I vrabac sebi log nalazi, i lastavica gnjezdašce gdje će položiti mlade svoje:');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 84, 5, 'a ja žrtvenike tvoje, Jahve nad Vojskama, Kralju moj i Bože moj! Blaženi koji prebivaju u Domu tvome slaveć\' te bez prestanka!');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 84, 6, 'Blažen komu je pomoć u tebi dok se sprema na svete putove!');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 84, 7, 'Prolaze li suhom dolinom, u izvor je vode promeću i prva je kiša u blagoslov odijeva.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 84, 8, 'Snaga im raste od časa do časa: dok ne ugledaju Boga na Sionu.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 84, 9, 'Jahve, Bože nad Vojskama, čuj molitvu moju, poslušaj, Bože Jakovljev!');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 84, 10, 'Pogledaj, štite naš, Bože, pogledaj lice pomazanika svoga!');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 84, 11, 'Zaista, jedan je dan u dvorima tvojim bolji od tisuću drugih. Volim biti na pragu Doma Boga svoga nego boraviti u šatorima grešnika.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 84, 12, 'Jahve, Bog, sunce je i štit: on daje milost i slavu. Ne uskraćuje Jahve dobara onima koji idu u nedužnosti.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 84, 13, 'Jahve nad Vojskama, blago onom tko se u te uzda.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 85, 1, 'Zborovođi. Sinova Korahovih. Psalam.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 85, 2, 'Zavolje opet, Jahve, zemlju svoju, na dobro okrenu udes Jakovljev.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 85, 3, 'Otpusti krivnju narodu svome, pokri sve grijehe njegove.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 85, 4, 'Suspregnu svu ljutinu svoju, odusta od žestine gnjeva svoga.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 85, 5, 'Obnovi nas, Bože, Spasitelju naš, i odbaci zlovolju prema nama!');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 85, 6, 'Zar ćeš se dovijeka gnjeviti na nas, prenositi srdžbu svoju od koljena na koljeno?');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 85, 7, 'Zar nas nećeš opet oživiti da se narod tvoj raduje u tebi?');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 85, 8, 'Pokaži nam, Jahve, milosrđe svoje i daj nam svoje spasenje.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 85, 9, 'Da poslušam što mi to Jahve govori: Jahve obećava mir narodu svomu, vjernima svojim, onima koji mu se svim srcem vrate.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 85, 10, 'Zaista, blizu je njegovo spasenje onima koji ga se boje, i slava će njegova živjeti u zemlji našoj.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 85, 11, 'Ljubav će se i Vjernost sastati, Pravda i Mir zagrliti.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 85, 12, 'Vjernost će nicat\' iz zemlje, Pravda će gledat\' s nebesa.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 85, 13, 'Jahve će dati blagoslov i sreću, i zemlja naša urod svoj.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 85, 14, 'Pravda će stupati pred njim, a Mir tragom stopa njegovih.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 86, 1, 'Molitva. Davidova. Prigni uho svoje, Jahve, i usliši me jer sam bijedan i ubog.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 86, 2, 'Čuvaj dušu moju jer sam posvećen tebi; spasi slugu svoga koji se uzda u te! Ti si moj Bog;');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 86, 3, 'o Gospode, smiluj mi se jer povazdan vapijem k tebi.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 86, 4, 'Razveseli dušu sluge svoga jer k tebi, Jahve, dušu uzdižem.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 86, 5, 'Jer ti si, Gospode, dobar i rado praštaš, pun si ljubavi prema svima koji te zazivaju.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 86, 6, 'Slušaj, Jahve, molitvu moju i pazi na glas vapaja mog.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 86, 7, 'U dan tjeskobe vapijem k tebi jer ćeš me uslišati.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 86, 8, 'Nema ti ravna među bozima, Gospode, nema djela kakvo je tvoje.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 86, 9, 'Svi narodi što ih stvori doći će i klanjat\' se tebi, o Jahve, i slavit će ime tvoje.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 86, 10, 'Jer ti si velik i činiš čudesa: ti si jedini Bog.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 86, 11, 'Uči me, Jahve, svojemu putu da hodim vjeran tebi, usmjeri srce moje da se boji imena tvojega!');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 86, 12, 'Hvalit ću te, Gospode, Bože moj, svim srcem svojim, slavit ću ime tvoje dovijeka,');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 86, 13, 'jer tvoje ljubavi prema meni ima izobila, istrgao si moju dušu iz dubine Podzemlja.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 86, 14, 'O Bože, oholice se digoše na me, mnoštvo silnika život mi vreba i nemaju tebe pred očima.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 86, 15, 'No ti si, Gospode Bože, milosrdan i blag, spor na srdžbu - sama ljubav i vjernost.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 86, 16, 'Pogledaj na me i smiluj se meni; daj svome sluzi snage svoje i spasi sina sluškinje svoje!');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 86, 17, 'Daj mi milostivo znak naklonosti svoje, da vide moji mrzitelji i da se postide, jer si mi ti, o Jahve, pomogao, ti me utješio.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 87, 1, 'Sinova Korahovih. Psalam. Pjesma. Zdanje svoje na svetim gorama');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 87, 2, 'ljubi Jahve; draža su mu vrata sionska nego svi šatori Jakovljevi.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 87, 3, 'Divote se govore o tebi, grade Božji!');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 87, 4, '\"Rahab i Babilon brojit ću k onima što me štuju; Filisteja i Tir i narod etiopski - i oni su rođeni ondje.\"');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 87, 5, 'O Sionu se govori: \"Ovaj i onaj u njemu je rođen! Svevišnji ga utemelji!\"');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 87, 6, 'Gospodin će zapisati u knjigu naroda: \"Ovi su rođeni ondje.\"');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 87, 7, 'I pjevat će igrajući kolo: \"Svi su izvori moji u tebi!\"');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 88, 1, 'Pjesma. Psalam. Sinova Korahovih. Zborovođi. Po napjevu \"Bolest\". Za pjevanje. Poučna pjesma. Ezrahijca Hemana.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 88, 2, 'Jahve, Bože moj, vapijem danju, a noću naričem pred tobom.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 88, 3, 'Neka dopre do tebe molitva moja, prigni uho k vapaju mome.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 88, 4, 'Jer mi je duša zasićena patnjama, moj se život bliži Podzemlju.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 88, 5, 'Broje me k onima što u grob silaze, postadoh sličan nemoćniku.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 88, 6, 'Među mrtvima moj je ležaj, poput ubijenih što leže u grobu kojih se više ne spominješ, od kojih si ustegao ruku.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 88, 7, 'Smjestio si me u jamu duboku, u tmine, u bezdan.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 88, 8, 'Teško me pritišće ljutnja tvoja i svim me valima svojim prekrivaš.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 88, 9, 'Udaljio si od mene znance moje, Óučini da im gnusan budem: zatvoren sam, ne mogu izaći.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 88, 10, 'Od nevolje oči mi gasnu: vapijem tebi, Jahve, iz dana u dan, za tobom ruke pružam.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 88, 11, 'Zar na mrtvima činiš čudesa? Zar će sjene ustati i hvaliti tebe?');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 88, 12, 'Zar se u grobu pripovijeda o tvojoj dobroti? O vjernosti tvojoj u Propasti?');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 88, 13, 'Zar se u tmini objavljuju čudesa tvoja i tvoja pravda u Zaboravu?');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 88, 14, 'Ipak ja vapijem tebi, Jahve, prije jutra molitvom te pretječem.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 88, 15, 'Zašto, Jahve, odbacuješ dušu moju? Zašto sakrivaš lice od mene?');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 88, 16, 'Bijedan sam i umirem već od dječaštva, klonuh noseći tvoje strahote.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 88, 17, 'Preko mene prijeđoše vihori tvojega gnjeva, strahote me tvoje shrvaše,');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 88, 18, 'okružuju me kao voda sveudilj, optječu me svi zajedno.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 88, 19, 'Udaljio si od mene prijatelja i druga: mrak mi je znanac jedini.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 89, 1, 'Poučna pjesma. Ezrahijca Etana.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 89, 2, 'O ljubavi Jahvinoj pjevat ću dovijeka, kroza sva koljena vjernost ću tvoju naviještati.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 89, 3, 'Ti reče: \"Zavijeke je sazdana ljubav moja!\" U nebu utemelji vjernost svoju:');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 89, 4, '\"Savez sklopih s izabranikom svojim, zakleh se Davidu, sluzi svome:');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 89, 5, 'tvoje potomstvo održat ću dovijeka, za sva koljena sazdat ću prijestolje tvoje.\"');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 89, 6, 'Nebesa veličaju čudesa tvoja, Jahve, i tvoju vjernost u zboru svetih.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 89, 7, 'TÓa tko je u oblacima ravan Jahvi, tko li je Jahvi sličan među sinovima Božjim?');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 89, 8, 'Bog je strahovit u zboru svetih, velik i strašan svima oko sebe.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 89, 9, 'Jahve, Bože nad Vojskama, tko je kao ti? Silan si, Jahve, i vjernost te okružuje.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 89, 10, 'Ti zapovijedaš bučnome moru, obuzdavaš silu valova njegovih;');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 89, 11, 'ti sasječe Rahaba i zgazi, snažnom mišicom rasu dušmane svoje.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 89, 12, 'Tvoja su nebesa i tvoja je zemlja, zemljin krug ti si sazdao i sve što je na njemu;');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 89, 13, 'sjever i jug ti si stvorio, Tabor i Hermon kliču imenu tvojemu.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 89, 14, 'Tvoja je mišica snažna, ruka čvrsta, desnica dignuta.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 89, 15, 'Pravda i Pravednost temelj su prijestolja tvoga, Ljubav i Istina koračaju pred tobom.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 89, 16, 'Blago narodu vičnu svetom klicanju, on hodi u sjaju lica tvojega, Jahve,');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 89, 17, 'u tvom se imenu raduje svagda i tvojom se pravdom ponosi.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 89, 18, 'Jer ti si ures moći njegove, po tvojoj milosti raste snaga naša.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 89, 19, 'Jer Jahve je štit naš, Svetac Izraelov kralj je naš.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 89, 20, 'Nekoć si u viđenju govorio pobožnima svojim: \"Junaku stavih krunu na glavu, izabranika iz naroda izdigoh;');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 89, 21, 'nađoh Davida, slugu svoga, svetim ga svojim uljem pomazah,');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 89, 22, 'da ruka moja svagda ostane s njime i moja mišica da ga krijepi.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 89, 23, 'Neće ga nadmudriti dušmanin, niti oboriti sin bezakonja.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 89, 24, 'Razbit ću pred njim protivnike njegove, pogubit ću mrzitelje njegove.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 89, 25, 'Vjernost moja i dobrota bit će s njime i u mome imenu rast će mu snaga.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 89, 26, 'Pružit ću njegovu ruku nad more, do Rijeke desnicu njegovu.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 89, 27, 'On će me zvati: \'Oče moj! Bože moj i hridi spasa mojega.\'');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 89, 28, 'A ja ću ga prvorođencem učiniti, najvišim među kraljevima svijeta.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 89, 29, 'Njemu ću sačuvati dovijeka naklonost svoju i Savez svoj vjeran.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 89, 30, 'Njegovo ću potomstvo učiniti vječnim i prijestolje mu kao dan nebeski.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 89, 31, 'Ako li mu sinovi Zakon moj ostave i ne budu hodili po naredbama mojim,');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 89, 32, 'ako li prestupe odredbe moje i ne budu čuvali zapovijedi mojih;');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 89, 33, 'šibom ću kazniti nedjelo njihovo, udarcima ljutim krivicu njihovu,');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 89, 34, 'ali mu naklonosti svoje oduzeti neću niti ću prekršiti vjernosti svoje.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 89, 35, 'Neću povrijediti Saveza svojega i neću poreći obećanja svoga.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 89, 36, 'Jednom se zakleh svetošću svojom: Davida prevariti neću:');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 89, 37, 'potomstvo će njegovo ostati dovijeka, prijestolje njegovo preda mnom kao sunce,');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 89, 38, 'ostat će dovijeka kao mjesec, vjerni svjedok na nebu.\"');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 89, 39, 'A sada ti ga odbi i odbaci, silno se razgnjevi na pomazanika svoga.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 89, 40, 'Prezre Savez sa slugom svojim i krunu njegovu do zemlje ponizi.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 89, 41, 'Razvali sve zidine njegove, njegove utvrde u ruševine baci.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 89, 42, 'Pljačkaju ga svi što naiđu, na ruglo je susjedima svojim.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 89, 43, 'Podiže desnicu dušmana njegovih i obradova protivnike njegove.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 89, 44, 'Otupi oštricu mača njegova, u boju mu ne pomože.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 89, 45, 'Njegovu sjaju kraj učini, njegovo prijestolje na zemlju obori.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 89, 46, 'Skratio si dane mladosti njegove, sramotom ga pokrio.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 89, 47, 'TÓa dokle ćeš, Jahve? Zar ćeš se uvijek skrivati? Hoće li gnjev tvoj k\'o oganj gorjeti?');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 89, 48, 'Sjeti se kako je kratak život moj, kako si ljude prolazne stvorio!');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 89, 49, 'Tko živ smrti vidjeti neće? Tko će od ruke Podzemlja dušu sačuvati?');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 89, 50, 'Gdje li je, Jahve, tvoja dobrota iskonska kojom se Davidu zakle na vjernost svoju?');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 89, 51, 'Sjeti se, Jahve, sramote slugu svojih: u srcu nosim svu mržnju pogana');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 89, 52, 's kojom nasrću dušmani tvoji, Jahve, s kojom nasrću na korake pomazanika tvoga.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 89, 53, 'Blagoslovljen Jahve dovijeka! Tako neka bude. Amen!');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 90, 1, 'Molitva. Mojsija, sluge Božjega. Jahve, ti nam bijaše okrilje od koljena do koljena.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 90, 2, 'Prije nego se rodiše bregovi, prije nego postade kopno i krug zemaljski, od vijeka do vijeka, Bože, ti jesi!');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 90, 3, 'Smrtnike u prah vraćaš i veliš: \"Vratite se, sinovi ljudski!\"');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 90, 4, 'Jer je tisuću godina u očima tvojim k\'o jučerašnji dan koji je minuo i kao straža noćna.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 90, 5, 'Razgoniš ih k\'o jutarnji san, kao trava su što se zeleni:');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 90, 6, 'jutrom cvate i sva se zeleni, a uvečer - već se suši i vene.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 90, 7, 'Zaista, izjeda nas tvoja srdžba i zbunjuje ljutina tvoja.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 90, 8, 'Naše si grijehe stavio pred svoje oči, naše potajne grijehe na svjetlost lica svojega.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 90, 9, 'Jer svi naši dani prođoše u gnjevu tvojemu, kao uzdah dovršismo godine svoje.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 90, 10, 'Zbroj naše dobi sedamdeset je godina, ako smo snažni, i osamdeset; a većina od njih muka je i ništavost: jer prolaze brzo i mi letimo odavle.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 90, 11, 'Tko će mjeriti žestinu gnjeva tvojega, tko proniknuti srdžbu tvoju?');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 90, 12, 'Nauči nas dane naše brojiti, da steknemo mudro srce.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 90, 13, 'Vrati se k nama, Jahve! TÓa dokle ćeš? Milostiv budi slugama svojim!');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 90, 14, 'Jutrom nas nasiti smilovanjem svojim, da kličemo i da se veselimo u sve dane!');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 90, 15, 'Obraduj nas za dane kad si nas šibao, za ljeta kad smo stradali!');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 90, 16, 'Neka se na slugama tvojim pokaže djelo tvoje i tvoja slava na djeci njihovoj!');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 90, 17, 'Dobrota Jahve, Boga našega, nek\' bude nad nama daj da nam uspije djelo naših ruku, djelo ruku naših nek\' uspije.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 91, 1, 'Ti što prebivaš pod zaštitom Višnjega, što počivaš u sjeni Svemogućega,');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 91, 2, 'reci Jahvi: \"Zaklone moj! Utvrdo moja! Bože moj u koga se uzdam!\"');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 91, 3, 'Jer on će te osloboditi od zamke ptičarske, od kuge pogubne.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 91, 4, 'Svojim će te krilima zaštititi i pod njegova ćeš se krila skloniti: Vjernost je njegova štit i obrana!');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 91, 5, 'Nećeš se bojati strašila noćnoga ni strelice što leti danju,');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 91, 6, 'ni kuge što se šulja kroz tmine, ni pošasti što hara o podne.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 91, 7, 'Pa nek\' padaju tisuće kraj tebe, deseci tisuća s desne tvoje, tebi se neće primaći!');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 91, 8, 'Tek što okom pogledaš, već ćeš vidjeti plaću grešnika.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 91, 9, 'Jer Jahve je zaklon tvoj, Višnjega odabra sebi za okrilje.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 91, 10, 'Neće te snaći nesreća, nevolja se neće prikučiti šatoru tvojemu.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 91, 11, 'Jer anđelima svojim zapovjedi da te čuvaju na svim putima tvojim.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 91, 12, 'Na rukama će te nositi da se ne spotakneš o kamen.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 91, 13, 'Nogom ćeš gaziti lava i ljuticu, zgazit ćeš lavića i zmiju.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 91, 14, 'Izbavit ću ga jer me ljubi, zakrilit ga jer poznaje ime moje.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 91, 15, 'Zazvat će me, a ja ću ga uslišiti, s njim ću biti u nevolji, spasit ću ga i proslaviti.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 91, 16, 'Nasitit ću ga danima mnogim, pokazat\' mu spasenje svoje.\"');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 92, 1, 'Psalam. Pjesma. Za dan subotnji.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 92, 2, 'Dobro je slaviti Jahvu, pjevati imenu tvome, Svevišnji;');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 92, 3, 'naviještati jutrom ljubav tvoju i noću vjernost tvoju,');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 92, 4, 'uz harfu od deset žica i liru, s pjesmom uz citaru.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 92, 5, 'Obradovao si me djelima svojim, o Jahve, kličem zbog djela ruku tvojih.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 92, 6, 'Kako su silna djela tvoja, o Jahve, i duboki naumi tvoji!');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 92, 7, 'Bezuman čovjek ne spoznaje, luđak ne shvaća.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 92, 8, 'Sve ako bi bezbošci nicali k\'o trava i cvali svi što zlo čine, određeni su za vječnu propast;');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 92, 9, 'a ti, Jahve, dovijeka uzvišen ostaješ.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 92, 10, 'Doista, dušmani tvoji, o Jahve, tvoji će dušmani propasti; raspršit će se svi što čine zlo.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 92, 11, 'Rog si mi digao k\'o u bivola, pomazao me uljem prečistim;');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 92, 12, 'i oko mi s visoka gleda dušmane i uho mirno sluša o onima što na me ustaju.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 92, 13, 'K\'o palma cvate pravednik i raste k\'o cedar libanonski.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 92, 14, 'Zasađeni u Domu Jahvinu, cvatu u dvorima Boga našega.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 92, 15, 'Rod donose i u starosti, sočni i puni svježine:');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 92, 16, 'da navijeste kako je pravedan Jahve, Hrid moja, onaj na kome nema nepravde.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 93, 1, 'Jahve kraljuje, u sjaj zaodjeven, Jahve zaodjeven moći i opasan. Čvrsto stoji krug zemaljski, neće se poljuljati.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 93, 2, 'Čvrsto je prijestolje tvoje odiskona, ti si od vječnosti!');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 93, 3, 'Rijeke podižu, Jahve, rijeke podižu glase svoje, rijeke podižu svoj bučni huk.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 93, 4, 'Jači od glasova voda golemih, silniji od bijesnoga mora: silan je Jahve u visinama.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 93, 5, 'Tvoja su obećanja vjere predostojna, svetost je ures Doma tvojega, Jahve, u sve dane!');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 94, 1, 'Bože osvetniče, Jahve, Bože osvetniče, pokaži se.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 94, 2, 'Ustani ti što sudiš zemlju, po zasluzi plati oholima!');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 94, 3, 'Dokle će bezbošci, Jahve, dokle će se bezbošci hvastati?');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 94, 4, 'Dokle će brbljati, drsko govoriti, dokle će se bezakonici hvastati?');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 94, 5, 'Tlače narod tvoj, Jahve, i baštinu tvoju pritišću;');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 94, 6, 'kolju udovicu i pridošlicu, sirotama život oduzimlju');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 94, 7, 'i govore: \"Jahve ne vidi! Ne opaža Bog Jakovljev!\"');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 94, 8, 'Shvatite, lude u narodu: bezumni, kad ćete se urazumiti?');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 94, 9, 'Onaj što uho zasadi da ne čuje? Koji stvori oko da ne vidi?');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 94, 10, 'Onaj što odgaja narode da ne kazni - Onaj što ljude uči mudrosti?');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 94, 11, 'Jahve poznaje namisli ljudske: one su isprazne.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 94, 12, 'Blago onom koga ti poučavaš, Jahve, i učiš Zakonu svojemu:');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 94, 13, 'da mu mir udijeliš od nesretnih dana, dok se grob kopa zlikovcu.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 94, 14, 'Jer neće Jahve odbaciti naroda svojega i svoje baštine neće napustiti;');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 94, 15, 'jer će se pravo dosuditi pravednosti i za njom će ići svi čestiti srcem.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 94, 16, 'Tko će ustati za me protiv zlotvora? Tko će se zauzeti za me protiv zločinaca?');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 94, 17, 'Da mi Jahve ne pomaže, brzo bih sišao u mjesto tišine.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 94, 18, 'Čim pomislim: \"Noga mi posrće\", dobrota me tvoja, o Jahve, podupire.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 94, 19, 'Kad se skupe tjeskobe u srcu mome, tvoje mi utjehe dušu vesele.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 94, 20, 'Zar je bezbožno sudište u savezu s tobom kad nevolje stvara pod izlikom zakona?');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 94, 21, 'Nek\' samo pritišću dušu pravednog, nek\' osuđuju krv nedužnu:');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 94, 22, 'Jahve mi je utvrda, Bog - hrid utočišta moga.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 94, 23, 'Platit će im bezakonje njihovo, njihovom će ih zloćom istrijebiti, istrijebit će ih Jahve, Bog naš.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 95, 1, 'Dođite, kličimo Jahvi, uzvikujmo Hridi, Spasitelju svome!');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 95, 2, 'Pred lice mu stupimo s hvalama, kličimo mu u pjesmama!');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 95, 3, 'Jer velik je Jahve, Bog naš, Kralj veliki nad svim bogovima.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 95, 4, 'U njegovoj su ruci zemaljske dubine, njegovi su vrhunci planina.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 95, 5, 'Njegovo je more, on ga je stvorio, i kopno koje načiniše ruke njegove.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 95, 6, 'Dođite, prignimo koljena i padnimo nice, poklonimo se Jahvi koji nas stvori!');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 95, 7, 'Jer on je Bog naš, a mi narod paše njegove, ovce što on ih čuva. O, da danas glas mu poslušate:');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 95, 8, '\"Ne budite srca tvrda kao u Meribi, kao u dan Mase u pustinji');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 95, 9, 'gdje me iskušavahu očevi vaši premda vidješe djela moja.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 95, 10, 'Četrdeset ljeta jadio me naraštaj onaj, pa rekoh: \'Narod su nestalna srca i ne promiču moje putove.\'');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 95, 11, 'Stog se zakleh u svom gnjevu: \'Nikad neće ući u moj pokoj!\'\"');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 96, 1, 'Pjevajte Jahvi pjesmu novu! Pjevaj Jahvi, sva zemljo!');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 96, 2, 'Pjevajte Jahvi, hvalite ime njegovo! Navješćujte iz dana u dan spasenje njegovo,');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 96, 3, 'kazujte poganima njegovu slavu, svim narodima čudesa njegova.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 96, 4, 'Velik je Jahve, hvale predostojan, strašniji od svih bogova!');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 96, 5, 'Ništavni su svi bozi naroda. Jahve stvori nebesa!');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 96, 6, 'Slava je i veličanstvo pred njim, sila i sjaj u Svetištu njegovu.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 96, 7, 'Dajte Jahvi, narodna plemena, dajte Jahvi slavu i silu!');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 96, 8, 'Dajte Jahvi slavu imena njegova! Prinosite žrtvu i uđite u dvorove njegove,');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 96, 9, 'poklonite se Jahvi u sjaju svetosti njegove. Strepi pred njim, zemljo sva!');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 96, 10, 'Nek\' se govori među poganima: \"Jahve kraljuje!\" Svijet on učvrsti da se ne pomakne, narodima pravedno upravlja.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 96, 11, 'Raduj se, nebo, i kliči, zemljo! Neka huči more i što je u njemu!');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 96, 12, 'Nek\' se raduje polje i što je na njemu, neka klikće šumsko drveće');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 96, 13, 'pred Jahvom, jer dolazi, jer dolazi suditi zemlji. Sudit će svijetu u pravdi i narodima u istini svojoj.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 97, 1, 'Jahve kraljuje: neka kliče zemlja, nek\' se vesele otoci mnogi!');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 97, 2, 'Oblak i tama ovijaju njega, pravda i pravo temelji su prijestolja njegova.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 97, 3, 'Oganj ide pred njim i sažiže okolo dušmane njegove.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 97, 4, 'Munje mu svijet osvjetljuju; zemlja to vidi i strepi.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 97, 5, 'Brda se tope pred Jahvom k\'o vosak, pred vladarom zemlje sve.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 97, 6, 'Nebesa navješćuju pravednost njegovu, svi narodi gledaju mu slavu.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 97, 7, 'Nek\' se postide svi što likove štuju i koji se hvale kumirima. Poklonite mu se, svi bozi!');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 97, 8, 'Sion radostan sluša, gradovi Judini kliču zbog tvojih sudova, o Jahve!');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 97, 9, 'Jer ti si, o Jahve, Svevišnji - nad svom zemljom, visoko, visoko nad bozima svima.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 97, 10, 'Jahve ljubi one koji mrze na zlo, on čuva duše pobožnika svojih, izbavlja ih iz ruku opakih.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 97, 11, 'Svjetlost sviće pravedniku i radost čestitima u srcu.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 97, 12, 'Radujte se, pravednici, u Jahvi, slavite sveto ime njegovo!');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 98, 1, 'Psalam. Pjevajte Jahvi pjesmu novu, jer učini djela čudesna. Pobjedu mu pribavi desnica njegova i sveta mišica njegova.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 98, 2, 'Jahve obznani spasenje svoje, pred poganima pravednost objavi.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 98, 3, 'Spomenu se dobrote i vjernosti prema domu Izraelovu. Svi krajevi svijeta vidješe spasenje Boga našega.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 98, 4, 'Sva zemljo, poklikni Jahvi, raduj se, kliči i pjevaj!');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 98, 5, 'Zapjevajte Jahvi uz citaru, uz citaru i uza zvuke harfe;');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 98, 6, 'uz trublje i zvuke rogova: kličite Jahvi kralju!');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 98, 7, 'Neka huči more i što je u njemu, krug zemaljski i stanovnici njegovi!');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 98, 8, 'Rijeke nek\' plješću rukama, zajedno s njima neka se brda raduju!');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 98, 9, 'Jer Jahve dolazi, dolazi suditi zemlji. Vladat će krugom zemaljskim po pravdi i pucima po pravici.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 99, 1, 'Jahve kraljuje - nek\' zadršću narodi; sjedi nad kerubima - zemlja nek\' se potrese!');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 99, 2, 'Velik je Jahve na Sionu, uzvišen nada sve narode.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 99, 3, 'Nek\' slave ime tvoje veliko i strašno: ono je sveto!');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 99, 4, 'Ti kralj si moćan koji ljubiš što je pravo, pravednost ti si utvrdio, pravo i pravednost vršiš u Jakovu.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 99, 5, 'Uzvisujte Jahvu, Boga našega, padnite pred podnožje njegovo: ono je sveto.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 99, 6, 'Mojsije i Aron među svećenicima njegovim i Samuel među onima koji zazivaju ime njegovo: zazivahu Jahvu, i on ih usliša.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 99, 7, 'Iz stupa od oblaka govoraše njima: slušahu zapovijedi njegove i odredbe što ih dade.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 99, 8, 'Jahve, Bože naš, ti si ih uslišivao; Bože, milostiv si bio njima premda si kažnjavao grijehe njihove.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 99, 9, 'Uzvisujte Jahvu, Boga našega, padnite pred svetu goru njegovu: jer svet je Jahve, Bog naš.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 100, 1, 'Psalam. Zahvalnica. Kliči Jahvi, zemljo sva!');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 100, 2, 'Služite Jahvi u veselju! Pred lice mu dođite s radosnim klicanjem!');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 100, 3, 'Znajte da je Jahve Bog: on nas stvori, i mi smo njegovi, njegov smo narod i ovce paše njegove.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 100, 4, 'Uđite s hvalama na vrata njegova, u dvore njegove s pjesmama; hvalite ga, ime mu slavite!');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 100, 5, 'Jer dobar je Jahve, dovijeka je ljubav njegova, od koljena do koljena vjernost njegova.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 101, 1, 'Davidov. Psalam. Da zapjevam o dobroti i pravdi, tebi, Jahve, da zasviram!');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 101, 2, 'Razmatrat ću put savršenstva: kad li ćeš k meni doći? Hodit ću u nedužnosti srca u domu svojemu.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 101, 3, 'Neću stavljati pred oči svoje ništa opako. Mrzim čovjeka koji čini zlo: on neće biti uza me.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 101, 4, 'Opako će srce biti daleko od mene; o zlu neću da znadem.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 101, 5, 'Tko kleveće bližnjeg u potaji, toga ću pogubiti. Čovjeka oholih očiju i srca naduta ja ne podnosim.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 101, 6, 'Pogled upravljam k vjernima na zemlji da sa mnom stanuju. Tko hodi putem nedužnim taj će mi služiti.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 101, 7, 'Neće prebivati u kući mojoj tko spletke snuje. Tko govori laži, neće opstati pred mojim očima.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 101, 8, 'Svaki ću dan istrebljivati sve zlikovce u zemlji; iskorijenit ću iz grada Jahvina sve koji čine bezakonje.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 101, 9, '');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 102, 1, 'Molitva nevoljnika koji je klonuo pa svoju tugu izlijeva');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 102, 2, 'Jahve, usliši molitvu moju, i vapaj moj k tebi da dođe!');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 102, 3, 'Nemoj sakrivati lice od mene u dan moje nevolje! Prigni k meni uho svoje: kad te prizovem, brzo me usliši!');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 102, 4, 'Jer moji dani nestaju poput dima, a moje kosti gore kao oganj.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 102, 5, 'Srce mi se suši kao pokošena trava i kruh svoj zaboravljam jesti.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 102, 6, 'Od snažnih jecaja mojih kosti mi uz kožu prionuše.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 102, 7, 'Sličan sam čaplji u pustinji, postah k\'o ćuk na pustoj razvalini.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 102, 8, 'Ne nalazim sna i uzdišem k\'o samotan vrabac na krovu.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 102, 9, 'Svagda me grde dušmani moji; mnome se proklinju što bjesne na me.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 102, 10, 'Pepeo jedem poput kruha, a piće svoje miješam sa suzama');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 102, 11, 'zbog tvoje ljutine i gnjeva, jer si me digao i bacio.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 102, 12, 'Moji su dani k\'o oduljena sjena, a ja se, gle, sušim poput trave.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 102, 13, 'A ti, o Jahve, ostaješ dovijeka i tvoje ime kroza sva koljena.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 102, 14, 'Ustani, smiluj se Sionu: vrijeme je da mu se smiluješ - sada je čas!');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 102, 15, 'Jer milo je slugama tvojim kamenje njegovo, žale ruševine njegove.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 102, 16, 'Tad će se pogani bojati, Jahve, imena tvojega i svi kraljevi zemlje slave tvoje');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 102, 17, 'kad Jahve opet sazda Sion, kad se pokaže u slavi svojoj,');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 102, 18, 'kad se osvrne na prošnju ubogih i ne prezre molitve njihove.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 102, 19, 'Nek\' se zapiše ovo za budući naraštaj, puk što nastane neka hvali Jahvu.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 102, 20, 'Jer Jahve gleda sa svog uzvišenog svetišta, s nebesa na zemlju gleda');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 102, 21, 'da čuje jauke sužnjeva, da izbavi smrti predane,');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 102, 22, 'da se na Sionu navijesti ime Jahvino i njegova hvala u Jeruzalemu');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 102, 23, 'kad se narodi skupe i kraljevstva da služe Jahvi.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 102, 24, 'Putem je istrošio sile moje, skratio mi dane.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 102, 25, 'Rekoh: \"Bože moj, nemoj me uzeti u sredini dana mojih! Kroza sva koljena traju godine tvoje.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 102, 26, 'U početku utemelji zemlju, i nebo je djelo ruku tvojih.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 102, 27, 'Propast će, ti ćeš ostati, sve će ostarjeti kao odjeća. Mijenjaš ih poput haljine i nestaju:');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 102, 28, 'ti si uvijek isti - godinama tvojim nema kraja.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 102, 29, 'Djeca će tvojih slugu živjeti u miru i potomstvo će njihovo trajati pred tobom.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 103, 1, 'Davidov. Blagoslivljaj Jahvu, dušo moja, i sve što je u meni, sveto ime njegovo!');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 103, 2, 'Blagoslivljaj Jahvu, dušo moja, i ne zaboravi dobročinstva njegova:');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 103, 3, 'on ti otpušta sve grijehe tvoje, on iscjeljuje sve slabosti tvoje;');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 103, 4, 'on ti od propasti čuva život, kruni te dobrotom i ljubavlju;');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 103, 5, 'život ti ispunja dobrima, k\'o orlu ti se mladost obnavlja.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 103, 6, 'Jahve čini pravedna djela i potlačenima vraća pravicu,');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 103, 7, 'Mojsiju objavi putove svoje, sinovima Izraelovim djela svoja.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 103, 8, 'Milosrdan i milostiv je Jahve, spor na srdžbu i vrlo dobrostiv.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 103, 9, 'Jarostan nije za vječna vremena niti dovijeka plamti srdžba njegova.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 103, 10, 'Ne postupa s nama po grijesima našim niti nam plaća po našim krivnjama.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 103, 11, 'Jer kako je nebo visoko nad zemljom, dobrota je njegova s onima koji ga se boje.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 103, 12, 'Kako je istok daleko od zapada, tako udaljuje od nas bezakonja naša.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 103, 13, 'Kako se otac smiluje dječici, tako se Jahve smiluje onima što ga se boje.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 103, 14, 'Jer dobro zna kako smo sazdani, spominje se da smo prašina.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 103, 15, 'Dani su čovjekovi kao sijeno, cvate k\'o cvijetak na njivi;');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 103, 16, 'jedva ga dotakne vjetar, i već ga nema, ne pamti ga više ni mjesto njegovo.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 103, 17, 'Al\' ljubav Jahvina vječna je nad onima što ga se boje i njegova pravda nad sinovima sinova,');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 103, 18, 'nad onima što njegov Savez čuvaju i pamte mu zapovijedi da ih izvrše.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 103, 19, 'Jahve u nebu postavi prijestolje svoje, i kraljevska vlast svemir mu obuhvaća.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 103, 20, 'Blagoslivljajte Jahvu, svi anđeli njegovi, vi jaki u sili, što izvršujete naredbe njegove, poslušni riječi njegovoj!');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 103, 21, 'Blagoslivljajte Jahvu, sve vojske njegove, sluge njegove koje činite volju njegovu!');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 103, 22, 'Blagoslivljajte Jahvu, sva djela njegova, na svakome mjestu vlasti njegove: blagoslivljaj Jahvu, dušo moja!');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 104, 1, 'Blagoslivljaj Jahvu, dušo moja, Jahve, Bože moj, silno si velik! Odjeven veličanstvom i ljepotom,');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 104, 2, 'svjetlošću ogrnut kao plaštem! Nebo si razapeo kao šator,');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 104, 3, 'na vodama sagradio dvorove svoje. Od oblaka praviš kola svoja, na krilima vjetrova putuješ.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 104, 4, 'Vjetrove uzimaš za glasnike, a žarki oganj za slugu svojega.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 104, 5, 'Zemlju si stavio na stupove njene: neće se poljuljati u vijeke vjekova,');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 104, 6, 'pokrio si je vodama bezdanim k\'o haljinom, iznad bregova stajahu vode;');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 104, 7, 'na tvoju se prijetnju povukoše, od tvoje grmljavine zadrhtaše.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 104, 8, 'Bregovi se digoše, doline spustiše na mjesto koje si im odredio.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 104, 9, 'Odredio si granicu koju ne smiju prijeći, da opet ne pokriju zemlju.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 104, 10, 'Izvore svraćaš u potoke što žubore među brdima.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 104, 11, 'Oni poje sve živine poljske, divlji magarci žeđ gase u njima.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 104, 12, 'Uz njih se gnijezde ptice nebeske i pjevaju među granama.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 104, 13, 'Ti natapaš bregove iz dvorova svojih, zemlja se nasićuje plodom tvojih ruku.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 104, 14, 'Ti daješ te niče trava za stoku i bilje na korist čovjeku da izvede kruh iz zemlje');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 104, 15, 'i vino što razvedruje srce čovječje; da uljem lice osvježi i da kruh okrijepi srce čovjeku.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 104, 16, 'Stabla se Jahvina napajaju hranom, cedri libanonski koje on zasadi.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 104, 17, 'Ondje se ptice gnijezde, u čempresu dom je rodin.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 104, 18, 'Visoki bregovi daju kozorogu a pećine jazavcu sklonište.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 104, 19, 'Ti si stvorio mjesec da označuje vremena i sunce znade kada ima zaći.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 104, 20, 'Kad razastreš tmine i noć se spusti, tad se šuljaju u njoj životinje šumske.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 104, 21, 'Lavići riču za plijenom i od Boga hranu traže.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 104, 22, 'Kad sunce ograne, nestaju i liježu na ležaje.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 104, 23, 'Tad čovjek izlazi na dnevni posao i na rad do večeri.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 104, 24, 'Kako su brojna tvoja djela, o Jahve! Sve si to mudro učinio: puna je zemlja stvorenja tvojih.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 104, 25, 'Eno mora, velika i široka, u njemu vrve gmazovi bez broja, životinje male i velike.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 104, 26, 'Onud prolaze nemani, Levijatan kojeg stvori da se igra u njemu.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 104, 27, 'I sva ova bića željno čekaju da ih nahraniš na vrijeme.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 104, 28, 'Daješ li im, tada sabiru: otvaraš li ruku, nasite se dobrima.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 104, 29, 'Sakriješ li lice svoje, tad se rastuže; ako dah im oduzmeš, ugibaju i opet se u prah vraćaju.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 104, 30, 'Pošalješ li dah svoj, opet nastaju, i tako obnavljaš lice zemlje.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 104, 31, 'Neka dovijeka traje slava Jahvina: nek\' se raduje Jahve u djelima svojim!');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 104, 32, 'On pogleda zemlju i ona se potrese, dotakne bregove, oni se zadime.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 104, 33, 'Pjevat ću Jahvi dokle god živim, svirat ću Bogu svome dokle god me bude.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 104, 34, 'Bilo mu milo pjevanje moje! Ja ću se radovati u Jahvi.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 104, 35, 'Nek\' zločinci sa zemlje nestanu i bezbožnika nek\' više ne bude! Blagoslivljaj Jahvu, dušo moja! Aleluja!');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 105, 1, 'Hvalite Jahvu, prizivajte mu ime, navješćujte među narodima djela njegova!');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 105, 2, 'Pjevajte mu, svirajte mu, pripovijedajte sva njegova čudesa!');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 105, 3, 'Dičite se svetim imenom njegovim, neka se raduje srce onih što traže Jahvu!');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 105, 4, 'Tražite Jahvu i njegovu snagu, tražite svagda njegovo lice!');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 105, 5, 'Sjetite se čudesa koja učini, njegovih čuda i sudova usta njegovih!');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 105, 6, 'Abrahamov rod sluga je njegov, sinovi Jakovljevi njegovi izabranici!');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 105, 7, 'On je Jahve, Bog naš; po svoj su zemlji njegovi sudovi!');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 105, 8, 'On se uvijek sjeća svojega Saveza, riječi koju dade tisući naraštaja:');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 105, 9, 'Saveza koji sklopi s Abrahamom i zakletve svoje Izaku.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 105, 10, 'Ustanovi je kao zakon Jakovu, Izraelu vječni Savez,');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 105, 11, 'govoreći: \"Tebi ću dati kanaansku zemlju kao dio u baštinu vašu.\"');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 105, 12, 'Kad ih još bješe malo na broju, vrlo malo, i kad bjehu pridošlice u njoj,');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 105, 13, 'išli su od naroda do naroda, iz jednoga kraljevstva k drugom narodu,');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 105, 14, 'ali ne dopusti nikom da ih tlači, kažnjavaše zbog njih kraljeve:');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 105, 15, '\"Ne dirajte u moje pomazanike, ne nanosite zla mojim prorocima!\"');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 105, 16, 'I on pozva glad na zemlju, sve zalihe uništi krušne.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 105, 17, 'Pred njima čovjeka posla: Josip u ropstvo bijaše prodan.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 105, 18, 'Sputaše uzama noge njegove, u gvožđe mu vrat staviše,');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 105, 19, 'dok se ne ispuni proroštvo njegovo, Jahvina ga riječ potvrdi.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 105, 20, 'Kralj naredi da ga driješe, narÄodÄa poglavar oslobodi njega.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 105, 21, 'Za domaćina ga stavi kući svojoj, za nadstojnika sveg imanja svoga,');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 105, 22, 'da velikaše njegove po volji uči i starce njegove mudrosti da vodi.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 105, 23, 'Tad Izrael u Egipat uđe, Jakov došljak bješe u Kamovoj zemlji.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 105, 24, 'Narod svoj umnoži veoma, učini ga jačim od dušmana.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 105, 25, 'Okrenu im srce da zamrze narod njegov, da slugama njegovim opaki budu.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 105, 26, 'Mojsija posla, slugu svoga, Arona, kog odabra.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 105, 27, 'Činjahu među njima znake njegove i čudesa u Kamovoj zemlji.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 105, 28, 'Posla tmine, i smrknu se, al\' prkosiše oni riječima njegovim.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 105, 29, 'U krv im vode prometnu i pobi ribe njihove.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 105, 30, 'Zemljom im žabe provrvješe, prodriješe i u dvore kraljevske.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 105, 31, 'Reče, i muha roj doletje i komarci u sve kraje njine.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 105, 32, 'Mjesto kiše grÓad im dade, ognjene munje po njihovoj zemlji.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 105, 33, 'Udari im lozu i smokve, polomi stabla u krajima njinim.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 105, 34, 'Reče, i skakavci dođoše i bezbrojne gusjenice s njima.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 105, 35, 'U zemlji im proždriješe svu bilinu, proždriješe rod njihovih njiva.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 105, 36, 'Pobi sve prvorođene u njihovoj zemlji, sve prvine snage njihove.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 105, 37, 'Izvede ih sa srebrom i zlatom; u plemenima njinim bolesnih ne bješe.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 105, 38, 'Odlasku njihovu Egipat se obradova, jer ga od njih strah spopade.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 105, 39, 'Rasprostro je oblak kao pokrov i oganj da se obnoć sja.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 105, 40, 'Zamoliše, i dovede prepelice, nebeskim ih kruhom tad nahrani.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 105, 41, 'Hrid rascijepi, i provri voda, pustinjom poteče kao rijeka.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 105, 42, 'Tad se sjeti svete riječi svoje što je zada sluzi svome Abrahamu.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 105, 43, 'Puk svoj s klicanjem izvede i s veseljem izabrane svoje.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 105, 44, 'I dade im zemlje poganske, trud naroda baštiniše,');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 105, 45, 'da čuvaju naredbe njegove i zakone da mu paze. Aleluja!');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 106, 1, 'Aleluja! Hvalite Jahvu jer je dobar, jer je vječna ljubav njegova!');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 106, 2, 'Tko će izreć\' djela moći Jahvine, tko li mu iskazat\' sve pohvale?');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 106, 3, 'Blaženi što drže naredbe njegove i čine pravo u svako doba!');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 106, 4, 'Sjeti me se, Jahve, po dobroti prema svome puku, pohodi me spasenjem svojim');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 106, 5, 'da uživam sreću izabranih tvojih, da se radujem radosti naroda tvoga, da tvojom se baštinom ponosim.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 106, 6, 'Zgriješismo kao oci naši, činismo bezakonje, bezbožno radismo.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 106, 7, 'Oci naši u Egiptu, nehajni za čudesa tvoja, ne spominjahu se velike ljubavi tvoje, već na Svevišnjeg digoše se na Crvenom moru.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 106, 8, 'Al\' on ih izbavi rad\' imena svoga da pokaže silu svoju.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 106, 9, 'Zapovjedi Crvenome moru, i presahnu ono, provede ih izmed valÄa kao kroz pustinju.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 106, 10, 'Iz ruku mrzitelja njih izbavi, oslobodi iz ruku dušmana.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 106, 11, 'I prekriše vode neprijatelje njine, ne ostade nijednoga od njih.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 106, 12, 'Vjerovahu riječima njegovim i hvale mu pjevahu.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 106, 13, 'Zaboraviše brzo djela njegova, ne uzdaše se u volju njegovu.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 106, 14, 'Pohlepi se daše u pustinji, iskušavahu Boga u samoći.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 106, 15, 'I dade im što iskahu, al\' u duše njine on groznicu posla.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 106, 16, 'Zavidješe tada Mojsiju u taboru, Aronu, kog posveti Jahve.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 106, 17, 'Otvori se zemlja, Datana proždrije, Abiramovo pokri mnoštvo.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 106, 18, 'Oganj pade na sve mnoštvo njino i zlotvore plamen sažga.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 106, 19, 'Načiniše tele na Horebu, klanjahu se liku od zlata slivenu.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 106, 20, 'Zamijeniše Slavu svoju likom bika što proždire travu.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 106, 21, 'Zaboraviše Boga, koji ih izbavi u Egiptu znamenja čineći');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 106, 22, 'i čudesa u Kamovoj zemlji i strahote na Crvenome moru.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 106, 23, 'Već namisli da ih satre, al\' Mojsije, izabranik njegov, zauze se za njih da srdžbu mu odvrati, te ih ne uništi.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 106, 24, 'Prezreše oni zemlju željkovanu ne vjerujuć\' njegovoj riječi.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 106, 25, 'Mrmljahu pod šatorima svojim, ne poslušaše glasa Jahvina.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 106, 26, 'Zakle se tada podignutom rukom: sve će ih pokosit\' u pustinji,');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 106, 27, 'potomstvo njino međ\' narode razbacat\', njih razasut\' po zemljama.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 106, 28, 'Posvetiše se Baal Peoru i jedoše žrtve bogova mrtvih.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 106, 29, 'Razjariše ga nedjelima svojim, i on na njih pošast baci.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 106, 30, 'Al\' se Pinhas diže, sud izvrši i pošasti nesta tada.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 106, 31, 'U zasluge to mu uđe u sva pokoljenja dovijeka.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 106, 32, 'Razjariše ga opet kraj voda meripskih, i Mojsija zlo pogodi zbog njih,');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 106, 33, 'jer mu duh već ogorčiše, nesmotrenu riječ izusti.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 106, 34, 'I ne istrijebiše naroda za koje im Jahve bješe naredio.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 106, 35, 'S poganima miješahu se, naučiše djela njina.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 106, 36, 'Štovahu likove njihove, koji im postaše zamka.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 106, 37, 'Žrtvovahu sinove svoje i svoje kćeri zlodusima.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 106, 38, 'Prolijevahu krv nevinu, krv sinova i kćeri svojih, koje žrtvovahu likovima kanaanskim. Zemlja bješe krvlju okaljana,');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 106, 39, 'djelima se svojim uprljaše, učiniše preljub svojim nedjelima.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 106, 40, 'Na svoj narod Jahve srdžbom planu, zgadi mu se njegova baština.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 106, 41, 'Predade ih u ruke pogana te vladahu njima mrzitelji njini.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 106, 42, 'Mučili ih neprijatelji i tlačili rukom svojom.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 106, 43, 'Prečesto ih izbavljaše, al\' ga razjariše naumima svojim: pokošeni bjehu za bezakonja svoja.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 106, 44, 'On pogleda opet na nevolju njinu kad njihove molitve začu');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 106, 45, 'i sjeti se svog Saveza s njima, sažali se na njih u velikom milosrđu svome.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 106, 46, 'Učini da nađu milost u onih što ih bjehu zarobili.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 106, 47, 'Spasi nas, Jahve, Bože naš, i saberi nas od bezbožnih naroda da slavimo tvoje sveto ime, da se tvojom slavom ponosimo.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 106, 48, 'Blagoslovljen Jahve, Bog Izraelov, od vijeka dovijeka! I sav narod neka kaže: \"Amen! Aleluja!\"');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 107, 1, 'Hvalite Jahvu jer je dobar, jer je dovijeka ljubav njegova!');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 107, 2, 'Tako nek\' reknu svi otkupljenici koje Jahve otkupi iz ruke dušmanske');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 107, 3, 'i koje skupi iz svih zemalja, s istoka i sa zapada, sa sjevera i s juga.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 107, 4, 'Lutahu pustinjom, u samoći pustoj, puta ne nalazeć\' do naseljena grada.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 107, 5, 'Gladni su bili, žeđu izmoreni, duša je klonula u njima.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 107, 6, 'Tada zavapiše Jahvi u svojoj tjeskobi, i on ih istrže iz svih nevolja.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 107, 7, 'Pravim ih putem pÓovede da stignu ka gradu naseljenu.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 107, 8, 'Neka hvale Jahvu za dobrotu njegovu, za čudesa njegova sinovima ljudskim!');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 107, 9, 'Jer gladnu dušu on nasiti, dušu izgladnjelu on napuni dobrima.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 107, 10, 'U mraku sjeđahu i u tmini, sputani bijedom i gvožđima,');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 107, 11, 'jer su prkosili besjedama Božjim i prezreli naum Svevišnjega.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 107, 12, 'Srce im stoga skrši patnjama: posrtahu, a ne bješe nikog da im pomogne.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 107, 13, 'Tada zavapiše Jahvi u svojoj tjeskobi i on ih istrže iz svih nevolja.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 107, 14, 'Izvede ih iz tmina i mraka, raskide okove njihove.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 107, 15, 'Neka hvale Jahvu za dobrotu njegovu, za čudesa njegova sinovima ljudskim!');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 107, 16, 'Jer razbi vrata mjedena i gvozdene polomi zasune.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 107, 17, 'Zbog svojih bezakonja bolovahu oni, ispaštajuć\' svoje opačine:');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 107, 18, 'svako se jelo gadilo duši njihovoj, do vrata smrti oni dođoše.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 107, 19, 'Tada zavapiše Jahvi u svojoj tjeskobi i on ih istrže iz svih nevolja.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 107, 20, 'Riječ svoju posla da ih ozdravi i život im spasi od jame grobne.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 107, 21, 'Neka hvale Jahvu za dobrotu njegovu, za čudesa njegova sinovima ljudskim!');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 107, 22, 'Nek\' prinose žrtve zahvalnice i kličući nek\' djela njegova kazuju!');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 107, 23, 'Oni koji lađama zaploviše morem da po vodama silnim trguju:');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 107, 24, 'oni vidješe djela Jahvina, čudesa njegova na pučini.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 107, 25, 'On reče i olujni se vjetar uzvitla što u visinu diže valove mora.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 107, 26, 'Do neba se dizahu, u bezdan se spuštahu, u nevolji duša im ginula.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 107, 27, 'Teturahu i posrtahu kao pijani, sva ih je mudrost izdala.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 107, 28, 'Tada zavapiše Jahvi u svojoj tjeskobi i on ih istrže iz svih nevolja.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 107, 29, 'Smiri oluju u tih povjetarac, valovi morski umukoše.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 107, 30, 'Obradovaše se tišini, u željenu luku on ih povede.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 107, 31, 'Neka hvale Jahvu za dobrotu njegovu, za čudesa njegova sinovima ljudskim!');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 107, 32, 'Neka ga uzvisuju u narodnom zboru, neka ga hvale u vijeću staraca!');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 107, 33, 'On pretvori rijeke u pustinju, a izvore vodene u žednu zemlju;');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 107, 34, 'plodonosnu zemlju u slanu pustaru zbog zloće žitelja njezinih.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 107, 35, 'On obrati pustinju u jezero, a zemlju suhu u vodene izvore');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 107, 36, 'i naseli ondje izgladnjele te podigoše grad gdje će živjeti.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 107, 37, 'Zasijaše njive, posadiše vinograde što im doniješe obilnu ljetinu.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 107, 38, 'I on ih blagoslovi te se namnožiše silno i stada im se ne smanjiše.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 107, 39, 'Prorijeđeni bjehu i prezreni pod teretom patnja i nevolja.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 107, 40, 'Onaj što izlijeva prezir na knezove pusti ih da po bespuću pustom lutaju.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 107, 41, 'Iz nevolje pÓodiže ubogog i obitelji k\'o stada ÓumnožÄi.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 107, 42, 'Videć\' to, čestiti neka se raduju, a zloća neka sebi usta začepi!');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 107, 43, 'Tko je mudar nek\' o svemu tom razmišlja i nek\' uvidi dobrotu Jahvinu!');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 108, 1, 'Pjesma. Psalam. Davidov.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 108, 2, 'Moje je srce sigurno, Bože, sigurno je srce moje: pjevat ću i svirati.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 108, 3, 'Probudi se, dušo moja! Probudi se, harfo i citaro! Probudit ću zoru jutarnju.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 108, 4, 'Hvalit ću te, Jahve, među narodima, među pucima tebi ću pjevati,');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 108, 5, 'jer do neba je dobrota tvoja, do oblaka tvoja vjernost.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 108, 6, 'Uzvisi se, Bože, nad nebesa, slava tvoja nek\' je nad svom zemljom!');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 108, 7, 'Da ti se ljubimci izbave, desnicom pomozi, usliši nas!');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 108, 8, 'Bog reče u svom Svetištu: \"Šekem ću razdijelit\' kličući, dolinu ću Sukot izmjeriti.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 108, 9, 'Moj je Gilead, moj Manaše, Efrajim mi kaciga, Judeja žezlo moje!');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 108, 10, 'Moab je sud iz kojeg se umivam, na Edom ću baciti obuću, nad Filistejcem slaviti pobjedu!\"');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 108, 11, 'Tko će me dovesti do utvrđena grada, tko će me dovesti do Edoma?');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 108, 12, 'Zar nećeš ti, o Bože, što nas odbaci? Zar nećeš više, Bože, sa četama našim?');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 108, 13, 'Pomozi nam protiv dušmana, jer je ljudska pomoć ništavna!');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 108, 14, 'S Božjom pomoću hrabro ćemo se boriti, Bog će zgaziti naše dušmane.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 109, 1, 'Zborovođi. Psalam. Davidov. Bože, diko moja, nemoj šutjeti!');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 109, 2, 'Usta bezbožna i prijevarna na me se otvaraju, govore mi jezikom lažljivim,');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 109, 3, 'riječima me mržnje okružuju, bezrazložno me napadaju.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 109, 4, 'Za moju me ljubav oni optužuju, a ja se samo molim.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 109, 5, 'Uzvraćaju mi zlo za dobro, mržnju za ljubav moju.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 109, 6, '\"Digni protiv njega bezbožnika i tužitelj nek\' mu stane zdesna!');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 109, 7, 'Kad mu se bude sudilo, nek\' bude osuđen, i molitva mu se za grijeh uzela!');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 109, 8, 'Dani njegovi nek\' budu malobrojni, njegovu službu nek\' dobije drugi!');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 109, 9, 'Djeca njegova nek\' postanu siročad, a njegova žena udovica!');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 109, 10, 'Nek\' mu djeca budu skitnice, prosjaci, nek\' budu bačena iz opustjelih domova!');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 109, 11, 'Nek\' mu lihvar prigrabi sav posjed, tuđinci nek\' razgrabe plod muke njegove!');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 109, 12, 'Nitko ne imao prema njemu samilosti, nitko se ne smilovao siročadi njegovoj!');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 109, 13, 'Neka mu se zatre potomstvo, u drugome koljenu neka se utrne ime njegovo!');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 109, 14, 'Spominjao se Jahve grijeha njegovih, i grijeh njegove majke nek\' se ne izbriše:');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 109, 15, 'nek budu svagda Jahvi pred očima! Neka se sa zemlje izbriše spomen njihov!\"');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 109, 16, 'Jer se ne spomenu da čini milosrđe, već proganjaše bijedna i uboga i u smrt gonjaše čovjeka srca shrvana.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 109, 17, 'Prokletstvo je ljubio, pa neka ga stigne; blagoslova ne htjede, daleko nek\' je od njega!');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 109, 18, 'Prokletstvom nek\' se odjene kao haljinom, neka kao voda uđe u njega i kao ulje u kosti njegove.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 109, 19, 'Bilo mu haljinom kojom se pokriva, pojas kojim se svagda paše!');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 109, 20, 'Tako nek\' plati Jahve tužiteljima mojim koji zlo govore protiv duše moje!');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 109, 21, 'A ti, Jahve, Gospode, rad imena svog zauzmi se za me, spasi me jer je dobrostiva ljubav tvoja!');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 109, 22, 'Jer bijedan sam i ubog, i srce je moje ranjeno u meni.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 109, 23, 'K\'o sjena što se naginje ja nestajem, progone me kao skakavca.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 109, 24, 'Od posta mi koljena klecaju i tijelo moje omrša.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 109, 25, 'Ruglom sam njima postao, kimaju glavom kad me vide.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 109, 26, 'Pomozi mi, Jahve, Bože moj, po doborti me svojoj spasi!');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 109, 27, 'Nek\' upoznaju da je ovo ruka tvoja i da si ti ovo učinio, Jahve!');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 109, 28, 'Oni nek\' proklinju, ti blagoslivljaj; nek\' se postide koji se na me podižu, a sluga tvoj nek\' se raduje!');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 109, 29, 'Stidom nek\' se odjenu tužitelji moji i sramotom svojom nek\' se k\'o plaštem pokriju!');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 109, 30, 'Slavit ću Jahvu iz svega grla i hvalit\' ga u veliku mnoštvu');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 109, 31, 'jer stoji s desne siromahu da mu dušu spasi od sudaca.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 110, 1, 'Psalam. Davidov. Riječ Jahvina Gospodinu mojemu: \"Sjedi mi zdesna dok ne položim dušmane za podnožje tvojim nogama!');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 110, 2, 'Žezlo tvoje moći protegnut će Jahve sa Siona: vladaj posred svojih neprijatelja!');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 110, 3, 'Spreman je tvoj narod u svetim odorama za dan tvog junaštva: kao rosa iz krila zorina uza te su mladi ratnici.\"');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 110, 4, 'Zakleo se Jahve i neće se pokajati: \"Dovijeka ti si svećenik po redu Melkisedekovu!\"');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 110, 5, 'Gospodin ti je zdesna, on će oboriti kraljeve u dan gnjeva svojega.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 110, 6, 'On će sudit\' narodima: bit će trupla na gomile, po svoj zemlji raskoljenih glava.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 110, 7, 'Na putu će se napit\' iz potoka, visoko će dignuti glavu.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 111, 1, 'Aleluja! $ALEF Hvalit ću Jahvu svim srcem svojim $BET u zboru pravednika, u zajednici njihovoj.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 111, 2, '$GIMEL Silna su djela Jahvina, $DALET nek\' razmišljaju o njima svi koji ih ljube.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 111, 3, '$HE Sjajno je i veličanstveno djelo njegovo, $VAU i pravda njegova ostaje dovijeka.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 111, 4, '$ZAJIN Čudesima svojim spomen postavi, $HET blag je Jahve i milosrdan.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 111, 5, '$TET Hranu dade štovateljima svojim, $JOD dovijeka se sjeća svoga Saveza.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 111, 6, '$KAF Silna djela svoja objavi svom narodu, $LAMED u posjed im dade zemlju pogana.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 111, 7, '$MEM Djela ruku njegovih vjernost su i pravednost, $NUN stalne su sve naredbe njegove,');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 111, 8, '$SAMEK utvrđene za sva vremena, dovijeka, $AJIN sazdane na istini i na pravdi.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 111, 9, '$PE On posla spasenje svom narodu, $SADE Savez svoj postavi zauvijek: $KOF sveto je i časno ime njegovo!');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 111, 10, '$REŠ Početak mudrosti strah Gospodnji! $ŠIN Mudro čine koji ga poštuju. $TAU Slava njegova ostaje dovijeka!');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 112, 1, 'Aleluja! $ALEF Blago čovjeku koji se boji Jahve $BET i koji uživa u naredbama njegovim:');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 112, 2, '$GIMEL moćno će mu biti na zemlji potomstvo, $DALET na pravednu će pokoljenju počivati blagoslov.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 112, 3, '$HE Blagostanje i bogatstvo bit će u domu njegovu, $VAU njegova pravednost ostaje dovijeka.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 112, 4, '$ZAJIN Čestitima sviće k\'o svjetlost u tami: $HET blag, milosrdan i pravedan Jahve.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 112, 5, '$TET Dobro je čovjeku koji je milostiv i daje u zajam, $JOD koji poslove svoje obavlja pravedno.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 112, 6, '$KAF Dovijeka neće on posrnuti: $LAMED u vječnome će spomenu biti pravednik.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 112, 7, '$MEM Žalosne se vijesti neće bojati, $NUN mirno je njegovo srce uzdajuć\' se u Jahvu.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 112, 8, '$SAMEK Hrabro mu je srce, ničeg se ne boji, $AJIN neprijatelje svoje prezire.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 112, 9, '$PE On prosipa, daje sirotinji: $SADE pravednost njegova ostaje dovijeka, $KOF njegovo će se čelo slavno uzdići.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 112, 10, '$REŠ Ljutito će to gledati bezbožnik, $ŠIN škrgutat će zubima i venuti, $TAU propast će želja opakih.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 113, 1, 'Aleluja! Hvalite, sluge Jahvine, hvalite ime Jahvino!');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 113, 2, 'Blagoslovljeno ime Jahvino sada i dovijeka!');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 113, 3, 'Od istoka sunca do zalaska hvaljeno bilo ime Jahvino!');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 113, 4, 'Uzvišen je Jahve nad sve narode, slava njegova nebesa nadvisuje.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 113, 5, 'Tko je kao Jahve, Bog naš, koji u visinama stoluje');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 113, 6, 'i gleda odozgo nebo i zemlju?');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 113, 7, 'Podiže iz prašine uboga, iz gliba vadi siromaha');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 113, 8, 'da ga posadi s prvacima, s prvacima svoga naroda.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 113, 9, 'Nerotkinji daje da u domu stanuje kao radosna majka djece brojne.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 114, 1, 'Aleluja! Kad izađe Izrael iz Egipta i kuća Jakovljeva iz naroda barbarskog,');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 114, 2, 'Judeja mu posta svetište, a Izrael kraljevstvo njegovo.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 114, 3, 'Vidje more i uzmače, a Jordan ustuknu.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 114, 4, 'Bregovi skakahu poput ovnova i brežuljci poput jaganjaca.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 114, 5, 'Što ti je, more, da uzmičeš? Jordane, zašto natrag okrećeš?');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 114, 6, 'Bregovi, zašto skačete poput ovnova i vi, brežuljci, poput jaganjaca?');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 114, 7, 'Dršći, zemljo, pred licem Gospodnjim, pred licem Boga Jakovljeva.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 114, 8, 'On hrid pretvara u slap vodeni i stijenu u izvor vode.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 115, 1, 'Ne nama, o Jahve, ne nama, već svom imenu slavu daj zbog ljubavi i vjernosti svoje.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 115, 2, 'Zašto da govore pogani: \"TÓa gdje je Bog njihov?\"');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 115, 3, 'Naš je Bog na nebesima, sve što mu se svidi to učini.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 115, 4, 'Idoli su njihovi srebro i zlato, ljudskih su ruku djelo.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 115, 5, 'Usta imaju, a ne govore, oči imaju, a ne vide.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 115, 6, 'Uši imaju, a ne čuju, nosnice, a ne mirišu.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 115, 7, 'Ruke imaju, a ne hvataju, noge imaju, a ne hodaju; glas im iz grla ne izlazi.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 115, 8, 'Takvi su i oni koji ih napraviše i svi koji se u njih uzdaju.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 115, 9, 'Dome Izraelov, u Jahvu se uzdaj! - On je štit i pomoćnik njihov.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 115, 10, 'Dome Aronov, u Jahvu se uzdaj! - On je štit i pomoćnik njihov.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 115, 11, 'Štovatelji Jahvini, u Jahvu se uzdajte! - On je štit i pomoćnik njihov.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 115, 12, 'Jahve će se nas spomenut\' i on će nas blagoslovit\': blagoslovit će dom Izraelov, blagoslovit će dom Aronov,');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 115, 13, 'blagoslovit će one koji se Jahve boje - i male i velike.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 115, 14, 'Umnožio vas Jahve, vas i vaše sinove!');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 115, 15, 'Blagoslovio vas Jahve koji stvori nebo i zemlju!');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 115, 16, 'Nebo je nebo Jahvino, a zemlju dade sinovima čovječjim.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 115, 17, 'Ne, Jahvu mrtvi ne hvale, nitko od onih što siđu u Podzemlje.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 115, 18, 'Mi živi, mi Jahvu slavimo sada i dovijeka. Aleluja.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 116, 1, 'Ljubim Jahvu jer čuje vapaj molitve moje:');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 116, 2, 'uho svoje prignu k meni u dan u koji ga zazvah.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 116, 3, 'Užeta smrti sapeše me, stegoše me zamke Podzemlja, snašla me muka i tjeskoba.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 116, 4, 'Tada zazvah ime Jahvino: \"O Jahve, spasi život moj!\"');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 116, 5, 'Dobrostiv je Jahve i pravedan, pun sućuti je Bog naš.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 116, 6, 'Jahve čuva bezazlene: u nevolji bijah, on me izbavi.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 116, 7, 'Vrati se, dušo moja, u svoj pokoj, jer Jahve je dobrotvor tvoj.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 116, 8, 'On mi život od smrti izbavi, oči moje od suza, noge od pada.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 116, 9, 'Hodit ću pred licem Jahvinim u zemlji živih.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 116, 10, 'Ja vjerujem i kada kažem: \"Nesretan sam veoma.\"');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 116, 11, 'U smetenosti svojoj rekoh: \"Svaki je čovjek lažac!\"');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 116, 12, 'Što da uzvratim Jahvi za sve što mi je učinio?');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 116, 13, 'Uzet ću čašu spasenja i zazvat ću ime Jahvino.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 116, 14, 'Izvršit ću Jahvi zavjete svoje pred svim pukom njegovim.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 116, 15, 'Dragocjena je u očima Jahvinim smrt pobožnika njegovih.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 116, 16, 'Jahve, tvoj sam sluga, tvoj sluga, sin sluškinje tvoje: ti si razriješio okove moje.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 116, 17, 'Tebi ću prinijeti žrtve zahvalne, zazvat ću ime Jahvino.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 116, 18, 'Izvršit ću Jahvi zavjete svoje pred svim pukom njegovim,');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 116, 19, 'u predvorjima Doma Jahvina, posred tebe, Jeruzaleme!');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 117, 1, 'Aleluja! Hvalite Jahvu, svi puci, slavite ga, svi narodi!');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 117, 2, 'Silna je prema nama ljubav njegova, i vjernost Jahvina ostaje dovijeka!');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 118, 1, 'Aleluja! Zahvaljujte Jahvi jer je dobar, jer je vječna ljubav njegova!');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 118, 2, 'Neka rekne dom Izraelov: \"Vječna je ljubav njegova!\"');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 118, 3, 'Neka rekne dom Aronov: \"Vječna je ljubav njegova!\"');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 118, 4, 'Svi koji se Jahve boje neka reknu: \"Vječna je ljubav njegova!\"');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 118, 5, 'Iz tjeskobe Jahvu ja zazvah: on me usliša i oslobodi.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 118, 6, 'Jahve je sa mnom i ja ne strahujem: što mi tko može?');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 118, 7, 'Jahve je sa mnom, pomoć moja, i zbunjene gledam dušmane.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 118, 8, 'Bolje se Jahvi uteći nego se uzdat\' u čovjeka.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 118, 9, 'Bolje se Jahvi uteći nego se uzdat\' u mogućnike.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 118, 10, 'Pogani me okružiše: imenom ih Jahvinim uništih.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 118, 11, 'Opkoliše me odasvud: imenom ih Jahvinim uništih.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 118, 12, 'Opkoliše me poput pčela, ubod im žeže kao trnje zapaljeno: imenom ih Jahvinim uništih.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 118, 13, 'Gurahu me, gurahu, da me obore, ali mi Jahve pomože.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 118, 14, 'Jahve je moja snaga i pjesma, on mi je spasitelj.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 118, 15, 'Čuj! Radost i spasenje odzvanja šatorima pravednika: Jahvina se proslavi desnica,');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 118, 16, 'Jahvina me uzdigne desnica, Jahvina se proslavi desnica!');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 118, 17, 'Ne, umrijeti neću nego živjeti i kazivat ću djela Jahvina.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 118, 18, 'Kaznom teškom kaznio me Jahve, ali me smrti ne preda.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 118, 19, 'Otvorite mi širom vrata pravde: ući ću, Jahvi zahvalit\'!');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 118, 20, '\"Ovo su vrata Jahvina, na njih ulaze pravedni!\"');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 118, 21, 'Zahvalit ću ti što si me uslišio i moj postao spasitelj.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 118, 22, 'Kamen što ga odbaciše graditelji postade kamen zaglavni.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 118, 23, 'Jahvino je to djelo: kakvo čudo u očima našim!');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 118, 24, 'Ovo je dan što ga učini Jahve: kličimo i radujmo se njemu!');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 118, 25, 'O Jahve, spasenje nam daj! Jahve, sreću nam daj!');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 118, 26, 'Blagoslovljen koji dolazi u imenu Jahvinu! Blagoslivljamo vas iz Doma Jahvina!');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 118, 27, 'Obasjao nas Bog Jahve! Složite povorku s grančicama u ruci sve do rogova žrtvenika.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 118, 28, 'Ti si Bog moj - tebi zahvaljujem: Bože moj, tebe ja uzvisujem.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 118, 29, 'Zahvaljujte Jahvi jer je dobar, jer je vječna ljubav njegova!');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 119, 1, '$ALEF Blaženi oni kojih je put neokaljan, koji hode po Zakonu Jahvinu!');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 119, 2, 'Blaženi oni koji čuvaju propise njegove, čitavim srcem njega traže;');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 119, 3, 'koji ne čine bezakonje, već hode putovima njegovim.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 119, 4, 'Naredbe si svoje dao da se brižno čuvaju.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 119, 5, 'O, kad bi čvrsti bili putovi moji da tvoja čuvam pravila!');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 119, 6, 'Neću se postidjeti tada kad budem pazio na zapovijedi tvoje.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 119, 7, 'Slavit ću te u čestitosti srca kad naučim sudove pravde tvoje.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 119, 8, 'Tvoja ću pravila čuvati: ne zapusti me nikada!');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 119, 9, '$BET Kako će mladić čistim sačuvati put svoj? Čuvajući riječi tvoje.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 119, 10, 'Svim srcem svojim tebe tražim; ne daj da zastranim od zapovijedi tvojih.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 119, 11, 'U srce pohranih riječ tvoju da protiv tebe ne sagriješim.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 119, 12, 'Blagoslovljen si, o Jahve, nauči me svojim pravilima.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 119, 13, 'Usnama svojim navješćujem sudove usta tvojih.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 119, 14, 'Putu se propisa tvojih radujem više no svemu bogatstvu.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 119, 15, 'Razmišljat ću o naredbama tvojim i putove ću tvoje razmatrat\'.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 119, 16, 'Uživat ću u pravilima tvojim, riječi tvojih neću zaboravit\'.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 119, 17, '$GIMEL Milostiv budi meni, sluzi svojem, da živim i tvoje riječi čuvam.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 119, 18, 'Otvori oči moje da gledam divote tvoga Zakona!');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 119, 19, 'Ja sam došljak na zemlji, zapovijedi svoje nemoj od mene skrivati!');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 119, 20, 'Duša mi gine u svako doba žudeći za tvojim odlukama.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 119, 21, 'Oholima ti si zaprijetio: prokleti koji odstupaju od zapovijedi tvojih.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 119, 22, 'Uzmi s mene rug i sramotu, jer tvoje ja čuvam propise.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 119, 23, 'Pa nek\' se sastaju knezovi i proti meni govore, tvoj sluga razmišlja o pravilima tvojim.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 119, 24, 'Jer tvoja su svjedočanstva uživanje moje, tvoja su pravila moji savjetnici.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 119, 25, '$DALET Moja duša leži u prašini: po riječi svojoj vrati mi život.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 119, 26, 'Kazivao sam ti svoje putove i ti si me čuo: pravilima me svojim nauči.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 119, 27, 'Pokaži mi put odredaba svojih i o čudesima ću tvojim razmišljat\'.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 119, 28, 'Suze roni duša moja od žalosti: po riječi svojoj ti me podigni!');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 119, 29, 'Daleko me drži od puta zablude i Zakonom me svojim obdari!');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 119, 30, 'Put istine ja sam odabrao, pred oči sam stavio odluke tvoje.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 119, 31, 'Uz propise tvoje ja čvrsto prianjam, o Jahve, nemoj me postidjeti!');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 119, 32, 'Ja kročim putem zapovijedi tvojih jer si mi prosvijetlio srce.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 119, 33, '$HE Pokaži mi, Jahve, stazu pravila svojih i ja ću je čuvati do kraja.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 119, 34, 'Pouči me da se tvoga držim Zakona i čuvat ću ga svim srcem.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 119, 35, 'Uputi me stazom svojih zapovijedi, jer ja u njoj uživam.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 119, 36, 'Prikloni mi srce propisima svojim, a ne k pohlepi!');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 119, 37, 'Odvrati moje oči da ne vide ništavost, život mi čuvaj na putu svojemu!');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 119, 38, 'Ispuni svom sluzi obećanje koje si onima dao što te se boje.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 119, 39, 'Ukloni sramotu od koje strahujem, jer divni su tvoji sudovi.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 119, 40, 'Evo, čeznem za naredbama tvojim: pravdom me svojom poživi.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 119, 41, '$VAU Nek\' milost tvoja, o Jahve, dođe na mene i spasenje tvoje po tvom obećanju.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 119, 42, 'Odgovorit ću onima koji me ruže, jer se uzdam u riječ tvoju.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 119, 43, 'Od mojih usta ne oduzmi riječ istine, jer se uzdam u sudove tvoje.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 119, 44, 'Tvoj ću Zakon čuvati uvijek i dovijeka.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 119, 45, 'Hodit ću putem prostranim, jer naredbe tvoje istražujem.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 119, 46, 'Pred kraljevima o tvojim ću propisima govorit\' i zbunit\' se neću.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 119, 47, 'U zapovijedima tvojim moja je naslada jer ih ljubim.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 119, 48, 'Prema zapovijedima tvojim ja podižem ruke i o tvojim odredbama razmišljam.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 119, 49, '$ZAJIN Spomeni se svoje riječi sluzi svojem kojom si mi dao nadu.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 119, 50, 'U nevolji sva mi je utjeha što mi život čuva riječ tvoja.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 119, 51, 'Oholice me napadaju žestoko, ali ja od tvog Zakona ne odstupam.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 119, 52, 'Sjećam se, o Jahve, davnih sudova tvojih i to me tješi.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 119, 53, 'Bijes me hvata zbog grešnika koji tvoj Zakon napuštaju.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 119, 54, 'Tvoje su mi naredbe pjesma u zemlji kojom putujem.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 119, 55, 'Noću se spominjem, Jahve, imena tvojega i tvoj čuvam Zakon.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 119, 56, 'Evo što je želja moja: čuvati tvoje odredbe.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 119, 57, '$HET Dio je moj, o Jahve - rekoh - da tvoje čuvam riječi.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 119, 58, 'Svim srcem lice tvoje ganuti hoću: smiluj mi se po svom obećanju.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 119, 59, 'Promislio sam putove svoje i k tvojem sam svjedočanstvu upravio noge.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 119, 60, 'Hitam i ne oklijevam da zapovijedi tvoje čuvam.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 119, 61, 'Opletoše me užeta grešnika, ali tvoga Zakona ja ne zaboravljam.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 119, 62, 'U ponoći ustajem da te slavim zbog pravednih tvojih odluka.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 119, 63, 'Prijatelj sam svima koji te se boje i koji tvoje čuvaju naredbe.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 119, 64, 'Dobrote tvoje, Jahve, puna je zemlja; nauči me odredbama svojim.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 119, 65, '$TET Učinio si dobro svom sluzi, Jahve, po riječi svojoj.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 119, 66, 'Nauči me razumu i znanju, jer u zapovijedi tvoje vjerujem.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 119, 67, 'Prije nego bjeh ponižen, lutao sam, ali sada tvoju čuvam riječ.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 119, 68, 'Ti si tako dobar i dobrostiv: nauči me pravilima svojim.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 119, 69, 'Oholi na me prijevare smišljaju, ali se ja svim srcem držim naredaba tvojih.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 119, 70, 'Srce im je poput sala bešćutno, a ja uživam u tvom Zakonu.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 119, 71, 'Dobro mi je što sam ponižen da bih tvoja naučio pravila.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 119, 72, 'Draži mi je zakon usta tvojih no tisuće zlatnika i srebrnika.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 119, 73, '$JOD Tvoje me ruke stvoriše i oblikovaše; prosvijetli me da naučim zapovijedi tvoje.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 119, 74, 'Štovatelji tvoji videć\' me vesele se, jer se u riječ tvoju ja pouzdah.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 119, 75, 'Znadem, o Jahve, da su ti sudovi pravedni i da si me s pravom ponizio.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 119, 76, 'Tvoja ljubav nek\' mi bude tješiteljicom po obećanju koje si dao sluzi svom.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 119, 77, 'Nek\' dođe na me milosrđe tvoje da poživim, jer Zakon tvoj moja je naslada.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 119, 78, 'Nek\' se smetu oholi, jer me tlače nizašto, a ja ću o naredbama tvojim razmišljat\'.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 119, 79, 'Nek\' mi se priklone štovatelji tvoji i koji znaju tvoje zapovijedi.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 119, 80, 'Nek\' mi srce savršeno bude u tvojim pravilima da ne budem postiđen.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 119, 81, '$KAF Duša moja gine za tvojim spasenjem riječ tvoju željno čekam.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 119, 82, 'Oči mi čeznu za tvojom besjedom: kad ćeš mi donijeti utjehu?');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 119, 83, 'Kao mijeh u dimu postadoh, ali pravila tvojih ne zaboravih.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 119, 84, 'Koliko dana ima sluga tvoj? Kad ćeš suditi progonitelje moje?');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 119, 85, 'Oholnici mi jame iskopaše: oni ne rade po Zakonu tvojemu.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 119, 86, 'Sve zapovijedi tvoje istina su sama: nekriva me gone, pomozi mi.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 119, 87, 'Umalo me smrviše u zemlji, ali naredaba tvojih ja ne ostavljam.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 119, 88, 'Po svojoj me milosti poživi i čuvat ću svjedočanstvo tvojih usta.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 119, 89, '$LAMED Dovijeka, o Jahve, riječ tvoja ostaje, stalna poput nebesa.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 119, 90, 'od koljena do koljena tvoja je vjernost; učvrstio si zemlju i ona stoji.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 119, 91, 'Po tvojim zakonima stoje zauvijek jer sve tebi služi.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 119, 92, 'Da nije tvoj Zakon uživanje moje, propao bih u nevolji svojoj.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 119, 93, 'Naredaba tvojih neću zaboravit\' dovijeka, jer po njima ti me oživljavaš.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 119, 94, 'Tvoj sam, Gospodine: spasi me, jer tvoje ja ištem naredbe.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 119, 95, 'Bezbožni vrebaju da me upropaste, ali ja na tvoje pazim propise.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 119, 96, 'Svakom savršenstvu vidim granicu, a zapovijed tvoja nema granica.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 119, 97, '$MEM O, kako ljubim Zakon tvoj, po cio dan o njemu razmišljam.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 119, 98, 'Tvoja me zapovijed mudrijim učini od dušmana mojih jer ona je sa mnom vječito.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 119, 99, 'Umniji sam od svih svojih učitelja jer razmišljam o svjedočanstvima tvojim.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 119, 100, 'Razumniji sam i od staraca jer tvoje čuvam naredbe.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 119, 101, 'Zla puta klone mi se noge da riječ tvoju sačuvam.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 119, 102, 'Od tvojih sudova ne odstupam, jer ti si me poučio.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 119, 103, 'Kako su slatke nepcu mom riječi tvoje, od meda su slađe ustima mojim.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 119, 104, 'Po tvojim naredbama postajem razuman, stoga mrzim sve putove lažne.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 119, 105, '$NUN Tvoja riječ nozi je mojoj svjetiljka i svjetlo mojoj stazi.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 119, 106, 'Kunem se i čvrsto odlučujem, i riječ ću održati: pravedne ću tvoje slijedit\' odluke.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 119, 107, 'U nevolji sam velikoj, Jahve, po riječi me svojoj poživi.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 119, 108, 'Prinose usta mojih primi, Jahve, uči me sudovima svojim.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 119, 109, 'Život mi je u pogibelji neprestanoj, ali tvog Zakona ja ne zaboravljam.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 119, 110, 'Grešnici mi postaviše zamku, ali ne skrećem od tvojih naredaba.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 119, 111, 'Svjedočanstva tvoja vječna su mi baština, ona su radost mome srcu.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 119, 112, 'Prignuh srce da vrši naredbe tvoje uvijek i do kraja.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 119, 113, '$SAMEK Ja mrzim one koji su dvostruka srca, a ljubim Zakon tvoj.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 119, 114, 'Ti si moj štit i moj zaklon, u tvoju se riječ ja uzdam.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 119, 115, 'Odstupite od mene, zlikovci: držat ću zapovijedi Boga svoga.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 119, 116, 'Podrži me po svom obećanju i živjet ću; nemoj da se u svojoj nadi postidim.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 119, 117, 'Pomozi mi i spasit ću se, na tvoja ću pravila svagda paziti.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 119, 118, 'Ti prezireš one koji odstupaju od pravila tvojih jer je lažna misao njihova.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 119, 119, 'K\'o hrđu zlotvore zemlje uklanjaš, zato ljubim tvoje propise.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 119, 120, 'Moje tijelo dršće od straha pred tobom, sudova tvojih ja se bojim.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 119, 121, '$AJIN Činim što je pravo i pravedno, ne predaj me tlačiteljima mojim.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 119, 122, 'Založi se za slugu svojega da me ne satru oholice!');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 119, 123, 'Moje oči ginu od čežnje za spasenjem tvojim, za tvojom riječi pravednom.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 119, 124, 'Učini sluzi svom po svojoj dobroti i nauči me pravilima svojim.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 119, 125, 'Ja sam sluga tvoj: prosvijetli me da upoznam tvoje propise.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 119, 126, 'Čas je, o Jahve, da se javiš: oskvrnuše Zakon tvoj.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 119, 127, 'Stoga ljubim zapovijedi tvoje više no zlato, zlato žeženo.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 119, 128, 'Zato hodim po odredbama tvojim, mrski su mi svi lažni putovi.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 119, 129, '$PE Divna su tvoja svjedočanstva, stoga ih čuva duša moja.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 119, 130, 'Objava riječi tvojih prosvjetljuje, bezazlene urazumljuje.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 119, 131, 'Otvaram usta svoja zadahtan u žudnji jer čeznem za zapovijedima tvojim.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 119, 132, 'Obrati se k meni i milostiv mi budi kao onima koji ljube ime tvoje.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 119, 133, 'Korake mi upravljaj po svom obećanju da nikakva opačina ne ovlada mnome.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 119, 134, 'Izbavi me od nasilja ljudskog, i naredbe tvoje ja ću čuvati.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 119, 135, 'Licem svojim obasjaj slugu svog i nauči me pravilima svojim!');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 119, 136, 'Potoci suza potekoše mi iz očiju jer se Zakon tvoj ne čuva.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 119, 137, '$SADE Pravedan si, Jahve, i pravi su sudovi tvoji.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 119, 138, 'Dao si Zakon pravedan i vjeran veoma.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 119, 139, 'Revnost me moja izjeda jer moji tlačitelji zaboravljaju riječi tvoje.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 119, 140, 'Tvoje su riječi prokušane veoma, zato ih tvoj sluga ljubi.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 119, 141, 'Malen sam i prezren, ali naredaba tvojih ne zaboravljam.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 119, 142, 'Pravda je tvoja pravda vječita i Zakon tvoj sama istina.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 119, 143, 'Tjeskoba me i nevolja snađe, al\' tvoje su zapovijedi uživanje moje.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 119, 144, 'Vječna je pravda tvojeg svjedočanstva, prosvijetli me i živjet ću.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 119, 145, '$KOF Iz svega srca vapijem, Jahve, usliši me: tvoja ću pravila čuvati.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 119, 146, 'K tebi vapijem, spasi me, tvojeg ću se držat\' svjedočanstva.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 119, 147, 'Pretječem zoru i molim za pomoć, u tvoje se riječi uzdam.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 119, 148, 'Oči moje straže noćne pretječu da razmišljam o besjedi tvojoj.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 119, 149, 'Po svojoj dobroti, Jahve, glas mi poslušaj, i po svojoj odluci poživi me.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 119, 150, 'Primiču se koji me podlo progone, daleko su oni od Zakona tvojega.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 119, 151, 'A ti si blizu, Jahve, i vjerne su sve zapovijedi tvoje.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 119, 152, 'Odavno znam za tvoje propise da si ih sazdao zasvagda.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 119, 153, '$REŠ Pogledaj na nevolju moju, izbavi me, jer Zakona tvog ne zaboravih.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 119, 154, 'Parnicu moju brani, po svom obećanju poživi me!');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 119, 155, 'Daleko je spasenje od grešnika jer za pravila tvoja ne mare.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 119, 156, 'Veliko je, o Jahve, tvoje smilovanje: po odlukama svojim poživi me.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 119, 157, 'Mnogi me progone i tlače, od tvojih svjedočanstava ja ne odstupam.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 119, 158, 'Otpadnike vidjeh i zgadiše mi se jer tvojih riječi ne čuvaju.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 119, 159, 'Gle, naredbe tvoje ljubim, o Jahve: po dobroti svojoj poživi me.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 119, 160, 'Srž je riječi tvoje istina, vječan je sud pravde tvoje.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 119, 161, '$ŠIN Mogućnici me progone nizašto, al\' samo pred tvojim riječima srce mi dršće.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 119, 162, 'Radujem se besjedama tvojim kao onaj koji se domogao velika plijena.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 119, 163, 'Mrzim na laž, grsti mi se ona, a ljubim tvoj Zakon.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 119, 164, 'Sedam puta na dan tebe hvalim zbog pravednih sudova tvojih.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 119, 165, 'Koji tvoj Zakon ljube, velik mir uživaju, ni o što se oni ne spotiču.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 119, 166, 'Pomoć tvoju čekam, o Jahve, tvoje zapovijedi izvršavam.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 119, 167, 'Moja duša čuva propise tvoje i ljubi ih veoma.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 119, 168, 'Čuvam tvoje naredbe i svjedočanstvo tvoje, jer svi su putovi moji pred tobom.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 119, 169, '$TAU Vapaj moj, Jahve, nek\' do tebe dopre, po svojoj me riječi prosvijetli.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 119, 170, 'Nek\' molitva moja dođe pred lice tvoje, po svojoj me riječi izbavi.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 119, 171, 'Usne moje nek\' zapjevaju pohvalnu pjesmu jer si me naučio pravilima svojim.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 119, 172, 'Nek\' mi pjeva jezik o riječi tvojoj, jer zapovijedi su tvoje sve pravedne.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 119, 173, 'Nek\' mi ruka tvoja na pomoć bude jer odabrah tvoje naredbe.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 119, 174, 'Jahve, za tvojim spasenjem čeznem, uživam u tvom Zakonu.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 119, 175, 'Nek\' živi duša moja i neka te hvali, a tvoji sudovi nek\' mi na pomoć budu!');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 119, 176, 'K\'o ovca izgubljena ja zalutah: o, potraži slugu svojega jer zapovijedi tvoje ja ne zaboravih.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 120, 1, 'Hodočasnička pjesma Kad bijah u nevolji, Jahvi zavapih i on me usliša.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 120, 2, 'Jahve, izbavi dušu moju od usana prijevarnih, od zlobna jezika!');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 120, 3, 'Kojim zlom da te prokunem, zlobni jeziče?');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 120, 4, 'Strelicama oštrim iz ratničke ruke i ugljevljem žarkim.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 120, 5, 'Jao meni što mi je boraviti u Mešeku i stanovati u šatorima kedarskim!');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 120, 6, 'Predugo mi duša mora živjeti s mrziteljima mira.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 120, 7, 'Kada o miru govorim, oni sile na rat.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 121, 1, 'Hodočasnička pjesma. K brdima oči svoje uzdižem: odakle će mi doći pomoć?');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 121, 2, 'Pomoć je moja od Jahve koji stvori nebo i zemlju.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 121, 3, 'Tvojoj nozi on posrnuti ne da i neće zadrijemati on, čuvar tvoj.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 121, 4, 'Ne, ne drijema i ne spava on, čuvar Izraelov.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 121, 5, 'Jahve je čuvar tvoj, Jahve je zasjen tvoj s desne tvoje!');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 121, 6, 'Neće ti sunce nauditi danju ni mjesec noću.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 121, 7, 'Čuvao te Jahve od zla svakoga, čuvao dušu tvoju!');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 121, 8, 'Čuvao Jahve tvoj izlazak i povratak odsada dovijeka.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 122, 1, 'Hodočasnička pjesma. Davidova. Obradovah se kad mi rekoše: \"Hajdemo u Dom Jahvin!\"');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 122, 2, 'Eto, noge nam već stoje na vratima tvojim, Jeruzaleme.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 122, 3, 'Jeruzaleme, grade čvrsto sazdani i kao u jedno saliveni!');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 122, 4, 'Onamo uzlaze plemena, plemena Jahvina, po Zakonu Izraelovu, da slave ime Jahvino.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 122, 5, 'Ondje stoje sudačke stolice, stolice doma Davidova.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 122, 6, 'Molite za mir Jeruzalemov! Blago onima koji tebe ljube!');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 122, 7, 'Neka bude mir u zidinama tvojim i pokoj u tvojim palačama!');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 122, 8, 'Radi braće i prijatelja svojih klicat ću: \"Mir tebi!\"');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 122, 9, 'Radi Doma Jahve, Boga našega, za sreću tvoju ja ću moliti.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 123, 1, 'Hodočasnička pjesma. Oči svoje uzdižem k tebi koji u nebesima prebivaš.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 123, 2, 'Evo, kao što su uprte oči slugu u ruke gospodara i oči sluškinje u ruke gospodarice tako su oči naše uprte u Jahvu, Boga našega, dok nam se ne smiluje.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 123, 3, 'Smiluj nam se, Jahve, smiluj se nama jer se do grla nasitismo prezira.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 123, 4, 'Presita nam je duša podsmijeha obijesnih, poruga oholih.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 124, 1, 'Hodočasnička pjesma. Davidova. Da nije Jahve za nas bio - neka slobodno rekne Izrael -');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 124, 2, 'da nije Jahve za nas bio: kad se ljudi digoše proti nama,');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 124, 3, 'žive bi nas progutali. Kad je uskipio bijes njihov na nas,');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 124, 4, 'voda bi nas podavila; bujica bi nas odnijela,');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 124, 5, 'vode pobješnjele sve nas potopile.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 124, 6, 'Blagoslovljen Jahve koji nas ne dade za plijen zubima njihovim!');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 124, 7, 'Duša je naša poput ptice umakla iz zamke lovaca: raskinula se zamka, a mi umakosmo!');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 124, 8, 'Pomoć je naša u imenu Jahve koji stvori nebo i zemlju.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 125, 1, 'Hodočasnička pjesma. Tko se uzda u Jahvu, on je kao brdo Sion: ne pomiče se, ostaje dovijeka.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 125, 2, 'Bregovi okružuju Jeruzalem: Jahve okružuje narod svoj odsada i dovijeka.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 125, 3, 'I neće vladati žezlo bezbožničko nad udesom pravednih, da ne bi pravedni ruke za bezakonjem pružili.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 125, 4, 'Učini, Jahve, dobro dobrima i čestitima u srcu.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 125, 5, 'A koji na krive skreću putove nek\' ih istrijebi Jahve sa zločincima! Mir nad Izraelom!');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 126, 1, 'Hodočasnička pjesma. Kad Jahve vraćaše sužnjeve sionske, bilo nam je k\'o da snivamo.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 126, 2, 'Usta nam bjehu puna smijeha, a jezik klicanja. Među poganima tad se govorilo: \"Velika im djela Jahve učini!\"');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 126, 3, 'Velika nam djela učini Jahve: opet smo radosni!');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 126, 4, 'Vrati, o Jahve, sužnjeve naše k\'o potoke negepske!');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 126, 5, 'Oni koji siju u suzama, žanju u pjesmi.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 126, 6, 'Išli su plačući noseći sjeme sjetveno: vraćat će se s pjesmom, noseći snoplje svoje.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 127, 1, 'Hodočasnička pjesma. Salomonova. Ako Jahve kuću ne gradi, uzalud se muče graditelji. Ako Jahve grad ne čuva, uzalud stražar bdi.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 127, 2, 'Uzalud vam je ustat prije zore i dugo u noć sjediti, vi što jedete kruh muke: miljenicima svojim u snu on daje.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 127, 3, 'Evo: sinovi su Jahvin dar, plod utrobe njegova je nagrada.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 127, 4, 'Strelica u ruci ratnika - to su sinovi mladosti.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 127, 5, 'Blago čovjeku koji njima napuni tobolac, neće se postidjeti kad se prÓeo bude s dušmanom na vratima.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 128, 1, 'Hodočasnička pjesma. Blago svakome koji se Jahve boji, koji njegovim hodi stazama!');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 128, 2, 'Plod ruku svojih ti ćeš uživati, blago tebi, dobro će ti biti.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 128, 3, 'Žena će ti biti kao plodna loza u odajama tvoje kuće; sinovi tvoji k\'o mladice masline oko stola tvojega.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 128, 4, 'Eto, tako će biti blagoslovljen čovjek koji se Jahve boji!');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 128, 5, 'Blagoslovio te Jahve sa Siona, uživao sreću Jeruzalema sve dane života svog!');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 128, 6, 'Vidio djecu svojih sinova, mir nad Izraelom!');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 129, 1, 'Hodočasnička pjesma. \"Mnogo su me od mladosti tlačili\" - neka rekne sad Izrael!');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 129, 2, '\"Mnogo su me od mladosti tlačili, ali me ne svladaše.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 129, 3, 'Po leđima su mojim orači orali, duge brazde povlačili.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 129, 4, 'Al\' Jahve pravedni isiječe užeta zlikovcima!\"');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 129, 5, 'Nek\' se postide i uzmaknu svi koji mrze Sion!');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 129, 6, 'Nek\' budu k\'o trava na krovu što povene prije nego je počupaju.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 129, 7, 'Žetelac njome ne napuni ruku ni naručje onaj koji veže snopove.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 129, 8, 'A prolaznici nek\' ne reknu: \"Blagoslov Jahvin nad vama! Blagoslivljamo vas imenom Jahvinim!\"');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 130, 1, 'Hodočasnička pjesma. Iz dubine, Jahve, vapijem tebi:');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 130, 2, 'Gospodine, čuj glas moj! Neka pazi uho tvoje na glas moga vapaja!');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 130, 3, 'Ako se, Jahve, grijeha budeš spominjao, Gospodine, tko će opstati?');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 130, 4, 'Al\' u tebe je praštanje, da bi te se bojali.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 130, 5, 'U Jahvu ja se uzdam, duša se moja u njegovu uzda riječ.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 130, 6, 'Duša moja čeka Gospodina više no zoru straža noćna; više no zoru straža noćna');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 130, 7, 'nek\' Izrael čeka Jahvu. Jer je u Jahve milosrđe i obilno je u njega otkupljenje;');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 130, 8, 'on će otkupiti Izraela od svih grijeha njegovih.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 131, 1, 'Hodočasnička pjesma. Davidova. O Jahve, ne gordi se moje srce niti se oči uznose. Ne idem za stvarima velikim ni za čudima što su iznad mene.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 131, 2, 'Ne, ja sam se smirio i upokojio dušu svoju; kao dojenče na grudima majke, kao dojenče duša je moja u meni.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 131, 3, 'U Jahvu se, Izraele, uzdaj odsada dovijeka.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 132, 1, 'Hodočasnička pjesma.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 132, 2, 'Spomeni se, o Jahve, Davida i sve revnosti njegove: kako se Jahvi zakleo, zavjetovao Snazi Jakovljevoj:');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 132, 3, '\"Neću ući u šator doma svog nit\' uzaći na ležaj svoje postelje,');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 132, 4, 'neću pustit\' snu na oči nit\' počinka dati vjeđama,');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 132, 5, 'dok Jahvi mjesto ne nađem, boravište Snazi Jakovljevoj.\"');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 132, 6, 'Eto, čusmo za nj u Efrati, nađosmo ga u Poljima jaarskim.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 132, 7, 'Uđimo u stan njegov, pred noge mu padnimo!');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 132, 8, '\"Ustani, o Jahve, pođi k svom počivalištu, ti i Kovčeg sile tvoje!');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 132, 9, 'Svećenici tvoji nek\' se obuku u pravednost, pobožnici tvoji nek\' radosno kliču!');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 132, 10, 'Poradi Davida, sluge svojega, ne odvrati lica od svog pomazanika!\"');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 132, 11, 'Jahve se zakle Davidu zakletvom tvrdom od koje neće odustati: \"Potomka tvoje utrobe posadit ću na prijestolje tvoje.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 132, 12, 'Budu li ti sinovi Savez moj čuvali i naredbe kojima ih učim, i sinovi će njini dovijeka sjedit\' na tvom prijestolju.\"');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 132, 13, 'Jer Jahve odabra Sion, njega zaželje sebi za sjedište.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 132, 14, '\"Ovo mi je počivalište vječno, boravit ću ovdje jer tako poželjeh.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 132, 15, 'Žitak ću njegov blagosloviti, siromahe nahraniti kruhom.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 132, 16, 'Svećenike njegove u spas ću odjenuti, sveti će njegovi kliktati radosno.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 132, 17, 'Učinit ću da ondje za Davida rog izraste, pripravit ću svjetiljku za svog pomazanika.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 132, 18, 'U sram ću mu obući dušmane, a na njemu će blistat\' vijenac moj.\"');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 133, 1, 'Hodočasnička pjesma. Davidova. Gle, kako je dobro i kako je milo kao braća zajedno živjeti:');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 133, 2, 'kao na glavi ulje dragocjeno što slazi na bradu, bradu Aronovu, što slazi na skute haljina njegovih;');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 133, 3, 'kao rosa s Hermona što slazi na brdo Sion. Ondje Jahve daje svoj blagoslov i život dovijeka.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 134, 1, 'Hodočasnička pjesma. Sad, blagoslivljajte Jahvu, sve sluge Jahvine što stojite u Domu Jahvinu, u noćnim satima!');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 134, 2, 'Dižite svoje ruke prema Svetištu i Jahvu blagoslivljajte!');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 134, 3, '\"Blagoslovio te sa Siona Jahve koji stvori nebo i zemlju!\"');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 135, 1, 'Aleluja! Hvalite ime Jahvino, hvalite, sluge Jahvine');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 135, 2, 'koji u Domu Jahvinu stojite u predvorjima Doma Boga našega!');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 135, 3, 'Hvalite Jahvu jer dobar je Jahve, pjevajte imenu njegovu jer je ljupko!');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 135, 4, 'Jer Jahve sebi odabra Jakova, Izraela za dragu svojinu.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 135, 5, 'Znadem da je velik Jahve, da je nad bozima svim gospodar.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 135, 6, 'Što god se Jahvi svidi, to čini na nebu i na zemlji, na moru i u bezdanima.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 135, 7, 'Oblake diže s kraja zemlje; stvara kiši munje, vjetar izvodi iz skrovišta njegovih.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 135, 8, 'On Egiptu pobi prvorođence, ljude i stoku podjednako.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 135, 9, 'On učini znamenja i čudesa usred tebe, Egipte, protiv Faraona i svih slugu njegovih.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 135, 10, 'On pobi narode mnoge i pogubi kraljeve moćne:');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 135, 11, 'Sihona, kralja amorejskog, i Oga, kralja bašanskog, i sva kraljevstva kanaanska.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 135, 12, 'I dade njihovu zemlju u baštinu, u baštinu Izraelu, narodu svom.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 135, 13, 'Ime tvoje, o Jahve, ostaje dovijeka i spomen na te, o Jahve, od koljena do koljena.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 135, 14, 'Jer Jahve štiti narod svoj, slugama svojim on je milostiv.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 135, 15, 'Kumiri poganski, srebro i zlato, ljudskih su ruku djelo:');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 135, 16, 'usta imaju, a ne govore; oči imaju, a ne vide;');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 135, 17, 'uši imaju, a ne čuju; i nema daha u ustima njihovim.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 135, 18, 'Takvi su i oni koji ih napraviše i svi koji se u njih uzdaju.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 135, 19, 'Dome Izraelov, Jahvu blagoslivljaj! Dome Aronov, Jahvu blagoslivljaj!');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 135, 20, 'Dome Levijev, Jahvu blagoslivljaj! Štovatelji Jahvini, Jahvu blagoslivljajte!');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 135, 21, 'Blagoslovljen sa Siona Jahve koji prebiva u Jeruzalemu!');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 136, 1, 'Aleluja! Hvalite Jahvu jer je dobar: vječna je ljubav njegova!');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 136, 2, 'Hvalite Boga nad bogovima: vječna je ljubav njegova!');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 136, 3, 'Hvalite Gospodara nad gospodarima: vječna je ljubav njegova!');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 136, 4, 'Jedini on učini čuda velika: vječna je ljubav njegova!');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 136, 5, 'Mudro sazda on nebesa: vječna je ljubav njegova!');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 136, 6, 'On utvrdi zemlju nad vodama: vječna je ljubav njegova!');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 136, 7, 'On načini svjetlila velika: vječna je ljubav njegova!');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 136, 8, 'Sunce da vlada danom: vječna je ljubav njegova!');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 136, 9, 'Mjesec i zvijezde da vladaju noću: vječna je ljubav njegova!');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 136, 10, 'On pobi prvorođence Egiptu: vječna je ljubav njegova!');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 136, 11, 'Izvede Izraela iz njega: vječna je ljubav njegova!');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 136, 12, 'Mišicom jakom, rukom ispruženom: vječna je ljubav njegova!');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 136, 13, 'On Crveno more razdvoji: vječna je ljubav njegova!');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 136, 14, 'Provede Izraela posred voda: vječna je ljubav njegova!');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 136, 15, 'I vrgnu Faraona i vojsku mu u Crveno more: vječna je ljubav njegova!');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 136, 16, 'On narod svoj vođaše pustinjom: vječna je ljubav njegova!');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 136, 17, 'On udari kraljeve velike: vječna je ljubav njegova!');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 136, 18, 'I pogubi kraljeve moćne: vječna je ljubav njegova!');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 136, 19, 'Sihona, kralja amorejskog: vječna je ljubav njegova!');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 136, 20, 'Oga, kralja bašanskog: vječna je ljubav njegova!');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 136, 21, 'I njihovu zemlju dade u baštinu: vječna je ljubav njegova!');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 136, 22, 'U baštinu Izraelu, sluzi svome: vječna je ljubav njegova!');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 136, 23, 'On se spomenu nas u poniženju našem: vječna je ljubav njegova!');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 136, 24, 'Od dušmana nas naših oslobodi: vječna je ljubav njegova!');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 136, 25, 'On daje hrane svakom tijelu: vječna je ljubav njegova!');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 136, 26, 'Hvalite Boga nebeskog: vječna je ljubav njegova!');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 137, 1, 'Na obali rijeka babilonskih sjeđasmo i plakasmo spominjući se Siona;');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 137, 2, 'o vrbe naokolo harfe svoje bijasmo povješali.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 137, 3, 'I tada naši tamničari zaiskaše od nas da pjevamo, porobljivači naši zaiskaše da se veselimo: \"Pjevajte nam pjesmu sionsku!\"');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 137, 4, 'Kako da pjesmu Jahvinu pjevamo u zemlji tuđinskoj!');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 137, 5, 'Nek\' se osuši desnica moja, Jeruzaleme, ako tebe zaboravim!');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 137, 6, 'Nek\' mi se jezik za nepce prilijepi ako spomen tvoj smetnem ja ikada, ako ne stavim Jeruzalem vrh svake radosti svoje!');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 137, 7, 'Ne zaboravi, Jahve, sinovima Edoma kako su u dan kobni Jeruzalemov vikali oni: \"Rušite! Srušite ga do temelja!\"');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 137, 8, 'Kćeri babilonska, pustošiteljice, blažen koji ti vrati milo za drago za sva zla što si nam ih nanijela!');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 137, 9, 'Blažen koji zgrabi i smrska o stijenu tvoju dojenčad!');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 138, 1, 'Davidov. Zahvaljujem ti, Jahve, iz svega srca jer si čuo riječi mojih usta. Pred licem anđela pjevam tebi,');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 138, 2, 'bacam se nice prema svetom Hramu tvojemu. Zahvaljujem imenu tvojem za tvoju dobrotu i vjernost, jer si nada sve uzveličao obećanje svoje.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 138, 3, 'Kad sam te zazvao, uslišio si me, dušu si moju pokrijepio.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 138, 4, 'Nek\' ti zahvaljuju, Jahve, svi kraljevi zemlje kad čuju riječi usta tvojih,');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 138, 5, 'nek\' pjevaju putove Jahvine: \"Zaista, velika je slava Jahvina!\"');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 138, 6, 'Zaista, uzvišen je Jahve, ali gleda na ponizna, a oholicu izdaleka poznaje.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 138, 7, 'Kroz nevolje kad budem kročio, život mi čuvaj, pruži ruku proti gnjevu mojih dušmana; nek\' me tvoja spasi desnica!');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 138, 8, 'Jahve, što ja počeh, ti dovrši! Jahve, vječna je ljubav tvoja: djelo ruku svojih ne zapusti!');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 139, 1, 'Zborovođi. Davidov. Jahve, proničeš me svega i poznaješ,');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 139, 2, 'ti znaš kada sjednem i kada ustanem, izdaleka ti već misli moje poznaješ.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 139, 3, 'Hodam li ili ležim, sve ti vidiš, znani su ti svi moji putovi.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 139, 4, 'Riječ mi još nije na jezik došla, a ti, Jahve, sve već znadeš.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 139, 5, 'S leđa i s lica ti me obuhvaćaš, na mene si ruku svoju stavio.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 139, 6, 'Znanje to odveć mi je čudesno, previsoko da bih ga dokučio.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 139, 7, 'Kamo da idem od duha tvojega i kamo da od tvog lica pobjegnem?');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 139, 8, 'Ako se na nebo popnem, ondje si, ako u Podzemlje legnem, i ondje si.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 139, 9, 'Uzmem li krila zorina pa se naselim moru na kraj');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 139, 10, 'i ondje bi me ruka tvoja vodila, desnica bi me tvoja držala.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 139, 11, 'Reknem li: \"Nek\' me barem tmine zakriju i nek\' me noć umjesto svjetla okruži!\" -');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 139, 12, 'ni tmina tebi neće biti tamna: noć sjaji kao dan i tama kao svjetlost.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 139, 13, 'Jer ti si moje stvorio bubrege, satkao me u krilu majčinu.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 139, 14, 'Hvala ti što sam stvoren tako čudesno, što su djela tvoja predivna. Dušu moju do dna si poznavao,');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 139, 15, 'kosti moje ne bjehu ti sakrite dok nastajah u tajnosti, otkan u dubini zemlje.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 139, 16, 'Oči tvoje već tada gledahu djela moja, sve već bješe zapisano u knjizi tvojoj: dani su mi određeni dok još ne bješe ni jednoga.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 139, 17, 'Kako su mi, Bože, naumi tvoji nedokučivi, kako li je neprocjenjiv zbroj njihov.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 139, 18, 'Da ih brojim? Više ih je nego pijeska! Dođem li im do kraja, ti mi preostaješ!');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 139, 19, 'De, istrijebi, Bože, zlotvora, krvoloci nek\' odstupe od mene!');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 139, 20, 'Jer podmuklo se bune protiv tebe, uzalud se dižu tvoji dušmani.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 139, 21, 'Jahve, zar da ne mrzim tvoje mrzitelje? Zar da mi se ne gade protivnici tvoji?');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 139, 22, 'Mržnjom dubokom ja ih mrzim i držim ih svojim neprijateljima.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 139, 23, 'Pronikni me svega, Bože, srce mi upoznaj, iskušaj me i upoznaj misli moje:');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 139, 24, 'pogledaj, ne idem li putem pogubnim i povedi me putem vječnim!');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 140, 1, 'Zborovođi. Psalam. Davidov.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 140, 2, 'Izbavi me, Jahve, od čovjeka zlobna, zaštiti me od čovjeka nasilna:');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 140, 3, 'od onih koji pakosti u srcu smišljaju i čitav dan začinju kavge.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 140, 4, 'Kao zmije bruse jezike svoje, pod usnama im je otrov ljutičin.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 140, 5, 'Spasi me, Jahve, od ruku zlotvora, čuvaj me od čovjeka nasilna koji hoće da mi noga posrne.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 140, 6, 'Oholice mi potajno nastavljaju zamku, užetima mrežu pletu, kraj puta klopke mi stavljaju.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 140, 7, 'Zavapih Jahvi: \"Ti si Bog moj! Poslušaj, o Jahve, krik mojih molitava!');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 140, 8, 'Jahve, Gospode moj, spasitelju silni moj, u dan boja zakloni mi glavu!\"');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 140, 9, 'Ne daj da se ispune želje zlotvora, ne daj da svoje on izvrši namjere!');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 140, 10, 'Nek\' glavu ne podignu oni koji me opkoliše, nek\' na njih padne zloba njihovih usana!');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 140, 11, 'Nek\' daždi po njima ugljevlje ognjeno, nek\' se strovale u jamu da više ne ustanu!');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 140, 12, 'Opadač se neće održat\' na zemlji, silnika će odjednom zgrabiti nesreća.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 140, 13, 'Znam da će Jahve dati pravo ubogu i pravicu siromasima.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 140, 14, 'Zaista, pravedni će tvoje ime slaviti, pred tvojim će licem boraviti čestiti.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 141, 1, 'Psalam. Davidov. Prizivljem te, Jahve, k meni pohitaj! Slušaj glas moj kojim tebi vapijem!');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 141, 2, 'Nek\' mi se uzdigne molitva kao kad pred lice tvoje, podizanje mojih ruku nek\' bude k\'o prinos večernji!');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 141, 3, 'Na usta mi, Jahve, stražu postavi i stražare na vrata usana mojih!');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 141, 4, 'Ne daj da mi se srce zlu prikloni, da bezbožno počinim djela opaka; i u društvu zlotvora da ne blagujem poslastica njihovih!');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 141, 5, 'Nek\' me samo udari pravednik, ljubav je što me kara, al\' ulje grešničko neće mi glavu pomazat\'; zloći njihovoj oprijet ću se uvijek svojom molitvom.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 141, 6, 'Kad strovale niz hridinu suce njihove, razumjet će kako blage bjehu riječi moje.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 141, 7, 'Kao kad orač ore i para zemlju, tako će im se na rubu Podzemlja kosti rasuti.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 141, 8, 'U te su, Jahve, uprte oči moje, k tebi se utječem, ne daj da mi duša propadne!');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 141, 9, 'Čuvaj me od stupice koju postaviše meni, od zamki zločinaca!');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 141, 10, 'Nek\' u vlastite zamke upadnu zlotvori, a ja neka im umaknem!');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 142, 1, 'Poučna pjesma. Davidova. Kad bijaše u spilji. Molitva.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 142, 2, 'Iz svega glasa vapijem Jahvi, iz svega glasa Jahvu zaklinjem.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 142, 3, 'Pred njim svoju izlijevam tužaljku, tjeskobu svoju pred njim razastirem.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 142, 4, 'Ako duh moj i klone u meni, ti put moj poznaješ. Na putu kojim prolazim potajnu mi zamku staviše.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 142, 5, 'Obazrem li se nadesno i pogledam: nitko ne zna za mene. Nemam kamo pobjeći, nitko za život moj ne mari.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 142, 6, 'K tebi, Jahve, vapijem; govorim: ti si mi utočište, ti si dio moj u zemlji živih.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 142, 7, 'Poslušaj moje vapaje jer sam veoma nevoljan. Izbavi me od gonitelja mojih jer od mene oni su moćniji.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 142, 8, 'Izvedi iz tamnice dušu moju da zahvaljujem imenu tvojemu. Oko mene će se okupiti pravednici zbog dobra što si ga iskazao meni.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 143, 1, 'Psalam. Davidov. Jahve, slušaj moju molitvu, u vjernosti svojoj prikloni uho mojim vapajima, u pravednosti me svojoj usliši!');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 143, 2, 'Ne idi na sud sa slugom svojim, jer nitko živ nije pravedan pred tobom!');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 143, 3, 'Dušmanin mi dušu progoni, o zemlju pritisnu život moj; u tmine me baci da stanujem kao oni koji su davno umrli.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 143, 4, 'Duh moj već zamire u meni, srce mi trne u grudima.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 143, 5, 'Spominjem se dana minulih, mislim o svim djelima tvojim, o djelima ruku tvojih razmišljam.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 143, 6, 'Ruke svoje za tobom pružam, duša moja k\'o suha zemlja za tobom žeđa.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 143, 7, 'Usliši me brzo, o Jahve, dah moj već je na izmaku! Lica svojeg preda mnom ne skrivaj, da ne postanem kao oni koji u grob silaze!');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 143, 8, 'Objavi mi jutrom dobrotu svoju jer se uzdam u tebe. Put mi kaži kojim ću krenuti jer k tebi dušu uzdižem.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 143, 9, 'Izbavi me, Jahve, od mojih dušmana, tebi ja se utječem.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 143, 10, 'Nauči me da vršim volju tvoju jer ti si Bog moj. Duh tvoj dobri nek\' me po ravnu putu vodi!');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 143, 11, 'Zbog imena svog, Jahve, poživi me, zbog svoje pravednosti dušu mi izvedi iz tjeskobe!');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 143, 12, 'Po svojoj dobroti satri moje dušmane, uništi sve moje tlačitelje, jer ja sam sluga tvoj!');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 144, 1, 'Davidov. Blagoslovljen Jahve, hridina moja: ruke mi uči boju a prste ratu.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 144, 2, 'On je ljubav moja i tvrđava moja, zaštita moja, izbavitelj moj, štit moj za koji se sklanjam; on mi narode stavlja pod noge!');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 144, 3, 'Što je čovjek, o Jahve, da ga poznaješ, što li čedo ljudsko da ga se spominješ?');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 144, 4, 'Poput daška je čovjek, dani njegovi kao sjena nestaju.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 144, 5, 'Jahve, nagni svoja nebesa i siđi, takni bregove: i zadimit će se!');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 144, 6, 'Sijevni munjom i rasprši dušmane, odapni strijele i rasprši ih!');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 144, 7, 'Ruku pruži iz visina, istrgni me i spasi iz voda beskrajnih, iz šaka sinova tuđinskih:');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 144, 8, 'laži govore usta njihova, a desnica krivo priseže.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 144, 9, 'Pjevat ću ti, Bože, pjesmu novu, na harfi od deset žica svirat ću.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 144, 10, 'Ti daješ pobjedu kraljevima, koji si spasio Davida, slugu svojega. Od pogubna mača');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 144, 11, 'spasi mene, oslobodi me iz ruke tuđinske; laži govore usta njihova, a desnica krivo priseže.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 144, 12, 'Daj da nam sinovi budu kao biljke što rastu od mladosti svoje; a kćeri naše kao stupovi ugaoni, krasne poput hramskog stupovlja;');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 144, 13, 'da nam žitnice budu pune svakog obilja, s plodovima svakojakim u izobilju;');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 144, 14, 'ovce naše plodile se na tisuće, plodile se beskrajno na našim poljima; stoka naša neka bude tovna! U zidinama nam ne bilo proboja ni ropstva ni plača na ulicama našim!');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 144, 15, 'Blago narodu kojem je tako, blago narodu kojem je Jahve Bog!');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 145, 1, 'Hvalospjev. Davidov. $ALEF Slavit ću te, o Bože, kralju moj, ime ću tvoje blagoslivljat\' uvijek i dovijeka.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 145, 2, '$BET Svaki ću dan tebe slaviti, ime ću tvoje hvaliti uvijek i dovijeka. $GIMEL');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 145, 3, 'Velik je Jahve i svake hvale dostojan, nedokučiva je veličina njegova! $DALET');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 145, 4, 'Naraštaj naraštaju kazuje djela tvoja i silu tvoju naviješta.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 145, 5, '$HE Govore o blistavoj slavi tvoga veličanstva i čudesa tvoja objavljuju.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 145, 6, '$VAU Kazuju strahovitu silu djela tvojih, veličinu tvoju pripovijedaju.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 145, 7, '$ZAJIN Razglašuju spomen velike dobrote tvoje i pravednosti tvojoj kliču.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 145, 8, '$HET Milostiv je Jahve i milosrdan, spor na srdžbu, bogat dobrotom.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 145, 9, '$TET Gospodin je dobar svima, milosrdan svim djelima svojim.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 145, 10, '$JOD Nek\' te slave, Jahve, sva djela tvoja i tvoji sveti nek\' te blagoslivlju!');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 145, 11, '$KAF Neka kazuju slavu tvoga kraljevstva, neka o sili tvojoj govore');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 145, 12, '$LAMED da objave ljudskoj djeci silu tvoju i slavu divnoga kraljevstva tvoga.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 145, 13, '$MEM Kraljevstvo tvoje kraljevstvo je vječno, tvoja vladavina za sva pokoljenja. $NUN Vjeran je Jahve u svim riječima svojim i svet u svim svojim djelima.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 145, 14, '$SAMEK Jahve podupire sve koji posrću i pognute on uspravlja.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 145, 15, '$AJIN Oči sviju u tebe su uprte, ti im hranu daješ u pravo vrijeme.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 145, 16, '$PE Ti otvaraš ruku svoju, do mile volje sitiš sve živo.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 145, 17, '$SADE Pravedan si, Jahve, na svim putovima svojim i svet u svim svojim djelima.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 145, 18, '$KOF Blizu je Jahve svima koji ga prizivlju, svima koji ga zazivaju iskreno.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 145, 19, '$REŠ On ispunja želje štovatelja svojih, sluša njihove vapaje i spasava ih.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 145, 20, '$ŠIN Jahve štiti one koji njega ljube, a zlotvore sve će zatrti.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 145, 21, '$TAU Nek\' usta moja kazuju hvalu Jahvinu i svako tijelo nek\' slavi sveto ime njegovo - uvijek i dovijeka.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 146, 1, 'Aleluja! Hvali, dušo moja, Jahvu!');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 146, 2, 'Hvalit ću Jahvu sveg života svojeg. Dok me bude, Bogu svom ću pjevati.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 146, 3, 'Ne uzdajte se u knezove, u čovjeka od kog nema spasenja!');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 146, 4, 'Iziđe li duh iz njega, u zemlju svoju on se vraća i propadaju sve misli njegove.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 146, 5, 'Blago onom kome je pomoćnik Bog Jakovljev, kome je ufanje u Jahvi, Bogu njegovu,');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 146, 6, 'koji stvori nebo i zemlju, more i sve što je u njima; koji ostaje vjeran dovijeka,');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 146, 7, 'potlačenima vraća pravicu, a gladnima kruh daje. Jahve oslobađa sužnje,');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 146, 8, 'Jahve slijepcima oči otvara. Jahve uspravlja prignute, Jahve ljubi pravedne.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 146, 9, 'Jahve štiti tuđince, sirote i udovice podupire, a grešnicima mrsi putove.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 146, 10, 'Jahve će kraljevati dovijeka, tvoj Bog, Sione, od koljena do koljena. Aleluja!');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 147, 1, 'Aleluja! Hvalite Jahvu jer je dobar, pjevajte Bogu našem jer je sladak; svake hvale on je dostojan!');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 147, 2, 'Jahve gradi Jeruzalem, sabire raspršene Izraelce.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 147, 3, 'On liječi one koji su srca skršena i povija rane njihove.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 147, 4, 'On određuje broj zvijezda, svaku njezinim imenom naziva.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 147, 5, 'Velik je naš Gospodin i svesilan, nema mjere mudrosti njegovoj.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 147, 6, 'Jahve pridiže ponizne, zlotvore do zemlje snizuje.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 147, 7, 'Pjevajte Jahvi pjesmu zahvalnu, svirajte na citari Bogu našem!');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 147, 8, 'Oblacima on prekriva nebesa i zemlji kišu sprema; daje da po bregovima raste trava i bilje na službu čovjeku.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 147, 9, 'On stoci hranu daje i mladim gavranima kada grakću.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 147, 10, 'Za konjsku snagu on ne mari nit\' mu se mile bedra čovječja.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 147, 11, 'Mili su Jahvi oni koji se njega boje, koji se uzdaju u dobrotu njegovu.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 147, 12, 'Slavi Jahvu, Jeruzaleme, hvali Boga svoga, Sione!');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 147, 13, 'On učvrsti zasune vrata tvojih, blagoslovi u tebi tvoje sinove.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 147, 14, 'On dade mir granicama tvojim, pšenicom te hrani najboljom.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 147, 15, 'Besjedu svoju šalje na zemlju, brzo trči riječ njegova.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 147, 16, 'Kao vunu snijeg razbacuje, prosipa mraz poput pepela.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 147, 17, 'On sipa grÓad kao zalogaje, voda mrzne od njegove studeni.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 147, 18, 'Riječ svoju pošalje i vode se tope; dunu vjetrom i vode otječu.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 147, 19, 'Riječ svoju on objavi Jakovu, odluke svoje i zakone Izraelu.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 147, 20, 'Ne učini tako nijednom narodu: nijednom naredbe svoje ne objavi! Aleluja!');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 148, 1, 'Aleluja! Hvalite Jahvu s nebesa, hvalite ga u visinama!');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 148, 2, 'Hvalite ga, svi anđeli njegovi, hvalite ga, sve vojske njegove!');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 148, 3, 'Hvalite ga, sunce i mjeseče, hvalite ga, sve zvijezde svjetlosne!');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 148, 4, 'Hvalite ga, nebesa nebeska, i vode nad svodom nebeskim!');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 148, 5, 'Neka hvale ime Jahvino jer on zapovjedi i postadoše.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 148, 6, 'Postavi ih zauvijek i dovijeka po zakonu koji neće proći.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 148, 7, 'Hvalite Jahvu sa zemlje, nemani morske i svi bezdani!');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 148, 8, 'Ognju i grÓade, sniježe i maglo, olujni vjetre, što riječ njegovu izvršavaš!');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 148, 9, 'Gore i svi brežuljci, plodonosna stabla i svi cedrovi!');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 148, 10, 'Zvijeri i sve životinje, gmizavci i ptice krilate!');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 148, 11, 'Zemaljski kraljevi i svi narodi, knezovi i suci zemaljski!');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 148, 12, 'Mladići i djevojke, starci s djecom zajedno:');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 148, 13, 'nek\' svi hvale ime Jahvino, jer jedino je njegovo ime uzvišeno! Njegovo veličanstvo zemlju i nebo nadvisuje,');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 148, 14, 'on podiže snagu svom narodu, on proslavlja svete svoje, sinove Izraelove - narod njemu blizak. Aleluja!');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 149, 1, 'Aleluja! Pjevajte Jahvi pjesmu novu i u zboru svetih hvalu njegovu!');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 149, 2, 'Nek\' se raduje Izrael Stvoritelju svojem! Kralju svom neka klikću sinovi Siona!');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 149, 3, 'Neka u kolu hvale ime njegovo, bubnjem i citarom neka ga slave!');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 149, 4, 'Jer Jahve ljubi narod svoj, spasenjem ovjenčava ponizne!');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 149, 5, 'Neka se sveti raduju u slavi, neka kliču s ležaja svojih!');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 149, 6, 'Nek\' im pohvale Božje budu na ustima, mačevi dvosjekli u rukama');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 149, 7, 'da nad pucima izvrše odmazdu i kaznu nad narodima;');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 149, 8, 'da im kraljeve bace u lance, a odličnike u okove gvozdene;');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 149, 9, 'da na njima izvrše sud davno napisan - nek\' bude na čast svim svetima njegovim! Aleluja!');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 150, 1, 'Aleluja!');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 150, 2, 'Hvalite Boga u Svetištu njegovu, slavite ga u veličanstvu svoda nebeskog!');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 150, 3, 'Hvalite ga zbog silnih djela njegovih, slavite ga zbog beskrajne veličine njegove!');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 150, 4, 'Hvalite ga zvucima roga, slavite ga harfom i citarom!');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 150, 5, 'Hvalite ga igrom i bubnjem, slavite ga glazbalima zvonkim i frulom! Hvalite ga cimbalima zvučnim, slavite ga cimbalima gromkim!');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 150, 6, 'Sve što god diše Jahvu neka slavi! Aleluja!');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 1, 1, 'Mudre izreke Salomona, sina Davidova, kralja izraelskog:');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 1, 2, 'da se spozna mudrost i pouka, da se shvate razumne riječi;');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 1, 3, 'da se primi umna pouka, pravda i pravica i nepristranost;');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 1, 4, 'da se dade pamet neiskusnima, mladiću znanje i umijeće;');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 1, 5, 'kad mudar čuje, da umnoži znanje, a razuman steče mudrije misli;');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 1, 6, 'da razumije izreke i prispodobe, riječi mudraca i njihove zagonetke.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 1, 7, 'Strah je Gospodnji početak spoznaje, ali ludi preziru mudrost i pouku.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 1, 8, 'Poslušaj, sine moj, pouku oca svoga i ne odbacuj naputka svoje majke!');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 1, 9, 'Jer će ti biti ljupki vijenac na glavi i ogrlica oko tvoga vrata.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 1, 10, 'Sine moj, ako te grešnici mame, ne pristaj;');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 1, 11, 'ako bi rekli: \"Hodi s nama, da vrebamo krv, čekamo u zasjedi nevina ni za što;');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 1, 12, 'da ih progutamo žive kao carstvo smrti i cijele kao one koji silaze u grob;');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 1, 13, 'naplijenit ćemo svakojaka blaga, napuniti svoje kuće plijenom;');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 1, 14, 'bacat ćeš s nama svoj ždrijeb, svi ćemo zajedno imati jednu kesu.\"');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 1, 15, 'Sine moj, ne idi s njima na put, makni nogu od njihove staze.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 1, 16, 'Jer na zlo trče svojim nogama i hite prolijevati krv.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 1, 17, 'Jer uzalud je razapinjati mrežu pred očima svima pticama.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 1, 18, 'A oni vrebaju vlastitu krv, postavljaju zasjedu svojemu životu.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 1, 19, 'Takva je sudba svih lakomih na ružan dobitak: on ih života stane.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 1, 20, 'Mudrost glasno uzvikuje na ulici, na trgovima diže svoj glas;');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 1, 21, 'propovijeda po bučnim uglovima, na otvorenim gradskim vratima govori svoje riječi:');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 1, 22, '\"Dokle ćete, vi glupi, ljubiti glupost i dokle će podsmjevačima biti milo podsmijevanje, i dokle će bezumnici mrziti znanje?');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 1, 23, 'Poslušajte moju opomenu! Gle, svoj duh pred vas izlijevam, hoću vas poučiti svojim riječima.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 1, 24, 'Koliko sam vas zvala, a vi ste odbijali; pružala sam ruku, ali je nitko ne opazi.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 1, 25, 'Nego ste odbacili svaki moj savjet i niste poslušali moje opomene;');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 1, 26, 'zato ću se i ja smijati vašoj propasti, rugat ću se kad vas obuzme tjeskoba:');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 1, 27, 'kad navali na vas strah kao nevrijeme i zgrabi vas propast kao vihor, kad navali na vas nevolja i muka.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 1, 28, 'Tada će me zvati, ali se ja neću odazvati; tražit će me, ali me neće naći.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 1, 29, 'Jer su mrzili spoznaju i nisu izabrali Gospodnjeg straha');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 1, 30, 'niti su poslušali moj savjet, nego su prezreli svaku moju opomenu.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 1, 31, 'Zato će jesti plod svojeg vladanja i nasititi se vlastitih savjeta.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 1, 32, 'Jer glupe će ubiti njihovo odbijanje, a nemar će upropastiti bezumne.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 1, 33, 'A tko sluša mene, bezbrižan ostaje i spokojno živi bez straha od zla.\"');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 2, 1, 'Sine moj, ako primiš moje riječi i pohraniš u sebi moje zapovijedi,');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 2, 2, 'i uhom svojim osluhneš mudrost i obratiš svoje srce razboru;');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 2, 3, 'jest, ako prizoveš razum i zavapiš za razborom;');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 2, 4, 'ako ga potražiš kao srebro i tragaš za njim kao za skrivenim blagom -');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 2, 5, 'tada ćeš shvatiti strah Gospodnji i naći ćeš Božje znanje.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 2, 6, 'Jer Jahve daje mudrost, iz njegovih usta dolazi znanje i razboritost.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 2, 7, 'On pravednicima pruža svoju pomoć, štit je onih koji hode u bezazlenosti.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 2, 8, 'Jer on štiti staze pravde i čuva pute svojih pobožnika.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 2, 9, 'Tada ćeš shvatiti pravdu, pravicu, pravednost i sve staze dobra,');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 2, 10, 'jer će mudrost ući u tvoje srce i spoznaja će obradovati tvoju dušu.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 2, 11, 'Oprez će paziti na te i razboritost će te čuvati:');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 2, 12, 'da te izbavi od zla puta, od varava čovjeka,');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 2, 13, 'od onih koji ostavljaju staze poštenja te idu mračnim putovima;');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 2, 14, 'koji se vesele čineći zlo i likuju u opačinama zloće;');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 2, 15, 'kojih su staze krive i koji su opaki na svojim putovima;');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 2, 16, 'da te izbavi od preljubnice i od tuđinke koja laska riječima;');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 2, 17, 'koja ostavlja prijatelja svoje mladosti i zaboravlja zavjet svoga Boga');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 2, 18, 'jer joj kuća tone u smrt i njezini putovi vode mrtvima.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 2, 19, 'Tko god zalazi k njoj ne vraća se nikad i ne nalazi više putove života.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 2, 20, 'Zato idi putem čestitih i drži se staza pravedničkih!');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 2, 21, 'Jer samo će pravedni nastavati zemlju i bezazleni će ostati na njoj.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 2, 22, 'A opake će zbrisati sa zemlje i bogohulnike iščupati iz nje.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 3, 1, 'Sine moj, ne zaboravljaj moje pouke, i tvoje srce neka čuva moje zapovijedi,');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 3, 2, 'jer će ti produljiti dane i životne godine i podariti spokojstvo.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 3, 3, 'Neka te ne ostavljaju dobrota i vjernost, objesi ih sebi oko vrata, upiši ih na ploču srca svoga.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 3, 4, 'Tako ćeš steći ugled i uspjeti pred Božjim i ljudskim očima.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 3, 5, 'Uzdaj se u Jahvu svim srcem i ne oslanjaj se na vlastiti razbor.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 3, 6, 'Misli na nj na svim svojim putovima i on će ispraviti tvoje staze.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 3, 7, 'Ne umišljaj da si mudar: boj se Jahve i kloni se zla.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 3, 8, 'To će biti lijek tvome tijelu i okrepa tvojim kostima.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 3, 9, 'Časti Jahvu svojim blagom i prvinama svega svojeg prirasta.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 3, 10, 'I tvoje će žitnice biti prepune i tvoje će se kace prelijevati novim vinom.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 3, 11, 'Sine moj, ne odbacuj Jahvine opomene i nemoj da ti omrzne njegov ukor.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 3, 12, 'Jer koga Jahve ljubi onoga i kori, kao otac sina koga voli.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 3, 13, 'Blago čovjeku koji je stekao mudrost i čovjeku koji je zadobio razboritost.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 3, 14, 'Jer bolje je steći nju nego steći srebro, i veći je dobitak ona i od zlata.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 3, 15, 'Skupocjenija je od bisera, i što je god tvojih dragocjenosti, s njome se porediti ne mogu;');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 3, 16, 'dug joj je život u desnoj ruci, a u lijevoj bogatstvo i čast.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 3, 17, 'Njezini su putovi putovi miline i sve su njene staze pune spokoja.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 3, 18, 'Životno je drvo onima koji se nje drže i sretan je onaj tko je zadrži.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 3, 19, 'Jahve je mudrošću utemeljio zemlju i umom utvrdio nebesa;');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 3, 20, 'njegovim su se znanjem otvorili bezdani i oblaci osuli rosom.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 3, 21, 'Sine moj, ne gubi to iz očiju, sačuvaj razbor i oprez.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 3, 22, 'I bit će život tvojoj duši i ures vratu tvome.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 3, 23, 'Bez straha ćeš tada kročiti svojim putem i noga ti se neće spoticati.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 3, 24, 'Kad legneš, nećeš se plašiti, i kad zaspiš, slatko ćeš snivati.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 3, 25, 'Ne boj se nenadne strahote ni nagle propasti kad stigne bezbožnike.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 3, 26, 'Jer će ti Jahve biti uzdanje i čuvat će nogu tvoju od zamke.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 3, 27, 'Ne uskrati dobročinstva potrebitim kad god to možeš učiniti.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 3, 28, 'Ne reci svome bližnjemu: \"Idi i dođi opet, sjutra ću ti dati\", kad možeš već sada.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 3, 29, 'Ne kuj zla svome bližnjemu dok on bez straha kod tebe boravi.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 3, 30, 'Ne pravdaj se ni s kim bez razloga ako ti nije učinio nikakva zla.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 3, 31, 'Nemoj zavidjeti nasilniku niti slijediti njegove pute,');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 3, 32, 'jer su Jahvi mrski pokvarenjaci, a prisan je s pravednima.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 3, 33, 'Jahvino je prokletstvo na domu bezbožnika, a blagoslov u stanu pravednika.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 3, 34, 'S podsmjevačima on se podsmijeva, a poniznima dariva milost.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 3, 35, 'Mudri će baštiniti čast, a bezumnici snositi sramotu.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 4, 1, 'Slušajte, djeco, pouku očevu i pazite kako biste spoznali mudrost,');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 4, 2, 'jer dobar vam nauk dajem: ne prezrite moga naputka.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 4, 3, 'I ja sam bio sin u svoga oca i nježan jedinac u svoje matere;');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 4, 4, 'i mene je on učio i govorio mi: \"Zadrži moje riječi u svojem srcu, poštuj moje zapovijedi i živjet ćeš.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 4, 5, 'Steci mudrost, steci razbor, ne smeći ih s uma i ne odstupi od riječi mojih usta.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 4, 6, 'Ne ostavljaj je i čuvat će te; ljubi je i obranit će te.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 4, 7, 'Početak je mudrosti: steci sebi mudrost i svim svojim imanjem steci razboritost.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 4, 8, 'Veličaj je i uzvisit će te; donijet će ti čast kad je prigrliš.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 4, 9, 'Stavit će ti ljupki vijenac na glavu, i obdarit će te krasnom krunom.\"');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 4, 10, 'Poslušaj, sine moj, primi moje riječi i umnožit će se godine tvojeg života.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 4, 11, 'Poučih te putu mudrosti, navratih te na prave staze;');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 4, 12, 'neće ti se zapletati koraci kad staneš hoditi; potrčiš li, nećeš posrnuti.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 4, 13, 'Čvrsto se drži pouke, ne puštaj je, čuvaj je, jer ona ti je život.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 4, 14, 'Ne idi stazom opakih i ne stupaj putem zlikovaca.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 4, 15, 'Ostavi ga, ne hodi njime; kloni ga se i zaobiđi ga.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 4, 16, 'Jer oni ne spavaju ako ne učine zla, i san im ne dolazi ako koga ne obore.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 4, 17, 'Jer jedu kruh opačine i piju vino nasilja.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 4, 18, 'A pravednička je staza kao svjetlost svanuća, koja je sve jasnija do potpunog dana.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 4, 19, 'A put je opakih kao mrkli mrak: ne znaju o što će se spotaknuti.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 4, 20, 'Sine moj, pazi na moje riječi, prigni uho svoje mojim besjedama.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 4, 21, 'Ne gubi ih nikad iz očiju, pohrani ih usred srca svoga.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 4, 22, 'Jer su život onima koji ih nalaze i ozdravljenje svemu tijelu njihovu.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 4, 23, 'A svrh svega, čuvaj svoje srce, jer iz njega izvire život.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 4, 24, 'Drži daleko od sebe lažna usta i udalji od sebe usne prijevarne.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 4, 25, 'Nek\' tvoje oči gledaju u lice i neka ti je pogled uvijek prav.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 4, 26, 'Pazi na stazu kojom kročiš i neka ti svi putovi budu pouzdani.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 4, 27, 'Ne skreći ni desno ni lijevo, drži svoj korak daleko oda zla.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 5, 1, 'Sine moj, čuj moju mudrost, prigni uho mojoj razboritosti');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 5, 2, 'da sačuvaš oprez, da ti usne zadrže znanje.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 5, 3, 'Jer s usana žene preljubnice kaplje med i nepce joj je glađe od ulja,');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 5, 4, 'ali je ona naposljetku gorka kao pelin, oštra kao dvosjekli mač.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 5, 5, 'Njene noge silaze k smrti, a koraci vode u Podzemlje.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 5, 6, 'Ona ne pazi na put života, ne mari što su joj staze kolebljive.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 5, 7, 'Zato me sada poslušaj, sine, i ne odstupaj od riječi mojih usta.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 5, 8, 'Neka je put tvoj daleko od nje i ne približuj se vratima njezine kuće,');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 5, 9, 'da drugima ne bi dao svoju slavu i okrutnima svoje godine;');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 5, 10, 'da se ne bi tuđinci nasitili tvoga dobra i da tvoja zaslužba ne ode u tuđu kuću;');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 5, 11, 'da ne ridaš na koncu kad ti nestane tijela i puti');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 5, 12, 'i da ne kažeš: \"Oh, kako sam mrzio pouku i kako mi je srce preziralo ukor!');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 5, 13, 'I ne slušah glasa svojih učitelja, niti priklonih uho onima što me poučavahu.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 5, 14, 'I umalo ne zapadoh u svako zlo, usred zbora i zajednice!\"');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 5, 15, 'Pij vodu iz svoje nakapnice i onu što teče iz tvoga studenca.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 5, 16, 'Moraju li se tvoji izvori razlijevati i tvoji potoci teći ulicama?');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 5, 17, 'Nego neka oni budu samo tvoji, a ne i tuđinaca koji su uza te.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 5, 18, 'Neka je blagoslovljen izvor tvoj i raduj se sa ženom svoje mladosti:');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 5, 19, 'neka ti je kao mila košuta i ljupka gazela, neka te grudi njene opajaju u svako doba, njezina ljubav zatravljuje bez prestanka!');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 5, 20, 'TÓa zašto bi se, sine moj, zanosio preljubnicom i grlio tuđinki njedra?');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 5, 21, 'Jer pred Jahvinim su očima čovjekovi putovi i on motri sve njegove staze.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 5, 22, 'Opakoga će uhvatiti njegova zloća i sapet će ga užad njegovih grijeha.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 5, 23, 'Umrijet će jer nema pouke, propast će zbog svoje goleme gluposti.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 6, 1, 'Sine moj, kad jamčiš bližnjemu svojem i daš svoju ruku drugome,');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 6, 2, 'vezao si se vlastitim usnama, uhvatio se riječima svojih usta;');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 6, 3, 'učini onda ovo, sine moj: oslobodi se! Jer si dopao u ruke bližnjemu svojemu; idi, baci se preda nj i salijeći bližnjega svoga.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 6, 4, 'Ne daj sna svojim očima ni drijema svojim vjeđama;');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 6, 5, 'otmi se kao gazela iz mreže i kao ptica iz ruku ptičaru.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 6, 6, 'Idi k mravu, lijenčino, promatraj njegove pute i budi mudar:');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 6, 7, 'on nema vođe, nadzornika, ni nadstojnika,');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 6, 8, 'ljeti se sebi brine za hranu i prikuplja jelo u doba žetve.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 6, 9, 'A ti, dokle ćeš, lijenčino, spavati? Kad ćeš se dići oda sna svoga?');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 6, 10, 'Još malo odspavaj, još malo odrijemaj, još malo podvij ruke za počinak');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 6, 11, 'i doći će tvoje siromaštvo kao skitač i tvoja oskudica kao oružanik.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 6, 12, 'Nevaljalac i opak čovjek hodi s lažljivim ustima;');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 6, 13, 'namiguje očima, lupka nogama, pokazuje prstima;');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 6, 14, 'prijevare su mu u srcu, snuje zlo u svako doba, zameće svađe.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 6, 15, 'Zato će mu iznenada doći propast, i učas će se slomiti i neće mu biti lijeka.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 6, 16, 'Šest je stvari koje Gospod mrzi, a sedam ih je gnusoba njegovu biću:');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 6, 17, 'ohole oči, lažljiv jezik, ruke koje prolijevaju krv nevinu,');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 6, 18, 'srce koje smišlja grešne misli, noge koje hitaju na zlo,');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 6, 19, 'lažan svjedok koji širi laži, i čovjek koji zameće svađe među braćom.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 6, 20, 'Sine moj, čuvaj zapovijedi oca svoga i ne odbacuj nauka matere svoje.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 6, 21, 'Priveži ih sebi na srce zauvijek, ovij ih oko svoga grla;');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 6, 22, 'da te vode kada hodiš, da te čuvaju kada spavaš i da te razgovaraju kad se probudiš.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 6, 23, 'Jer je zapovijed svjetiljka, pouka je svjetlost, opomene stege put su života;');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 6, 24, 'da te čuvaju od zle žene, od laskava jezika tuđinke.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 6, 25, 'Ne poželi u svom srcu njezine ljepote i ne daj da te osvoji trepavicama svojim,');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 6, 26, 'jer bludnici dostaje i komad kruha, dok preljubnica lovi dragocjeni život.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 6, 27, 'Može li tko nositi oganj u njedrima a da mu se odjeća ne upali?');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 6, 28, 'Može li tko hoditi po živom ugljevlju a svojih nogu da ne ožeže?');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 6, 29, 'Tako biva onomu tko ide k ženi svoga bližnjega: neće ostati bez kazne tko god se nje dotakne.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 6, 30, 'Ne sramote li lupeža sve ako je krao da gladan utoli glad:');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 6, 31, 'uhvaćen, on sedmerostruko vraća i plaća svim imanjem kuće svoje.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 6, 32, 'Nerazuman je, dakle, tko se upušta s preljubnicom; dušu svoju gubi koji tako čini.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 6, 33, 'Bruke i sramote dopada i rug mu se nikad ne briše.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 6, 34, 'Jer bijesna je ljubomornost u muža: on ne zna za milost u osvetni dan;');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 6, 35, 'ne pristaje ni na kakav otkup i ne prima ma kolike mu darove dao.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 7, 1, 'Čuvaj, sine, riječi moje i pohrani moje zapovijedi kod sebe.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 7, 2, 'Čuvaj moje zapovijedi, i bit ćeš živ, i nauk moj kao zjenicu oka svoga.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 7, 3, 'Priveži ih sebi na prste, upiši ih na ploči srca svoga;');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 7, 4, 'reci mudrosti: \"Moja si sestra\" i razboritost nazovi \"sestričnom\",');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 7, 5, 'da te čuva od žene preljubnice, od tuđinke koja laskavo govori.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 7, 6, 'Kad bijah jednom na prozoru svoje kuće i gledah van kroz rešetku,');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 7, 7, 'vidjeh među lakovjernima, opazih među momcima nerazumna mladića:');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 7, 8, 'prolazio je ulicom kraj njezina ugla i koracao putem k njezinoj kući');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 7, 9, 'u sumraku između dana i večeri kad se hvata noćna tmina;');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 7, 10, 'i gle, susrete ga žena, bludno odjevena i s prijevarom u srcu.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 7, 11, 'Jogunasta bijaše i razuzdana, noge joj se nisu mogle u kući zadržati;');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 7, 12, 'bila je čas na ulici, čas na trgovima i vrebala kod svakog ugla;');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 7, 13, 'i uhvati ga i poljubi i reče mu bezobrazna lica:');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 7, 14, '\"Bila sam dužna žrtvu pričesnicu, i danas izvrših svoj zavjet;');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 7, 15, 'zato sam ti izašla u susret, da te tražim, i nađoh te.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 7, 16, 'Svoju sam postelju nastrla sagovima, vezenim pokrivačima misirskim;');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 7, 17, 'svoj sam krevet namirisala smirnom, alojem i cimetom.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 7, 18, 'Hajde da se opijamo nasladom do jutra i da se radujemo užicima ljubavi.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 7, 19, 'Jer muža mi nema kod kuće: otišao je na dalek put;');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 7, 20, 'uzeo je sa sobom novčani tobolac; a vratit će se kući tek o uštapu.\"');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 7, 21, 'Tako ga zavede svojim vičnim nagovorom, odvuče ga svojim glatkim usnama.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 7, 22, 'I ludo on pođe za njom, kao što vol ide na klaonicu i kao što jelen zapleten u mrežu čeka');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 7, 23, 'dok mu strijela ne probije jetra, i kao ptica što ulijeće u zamku, i ne znajući da će ga to života stajati.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 7, 24, 'Zato me, sine moj, poslušaj i čuj riječi mojih usta.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 7, 25, 'Nek\' ti srce ne zastranjuje na njezine putove i ne lutaj po njezinim stazama.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 7, 26, 'Jer je mnoge smrtno ranila i oborila, i mnogo je onih što ih je pobila.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 7, 27, 'U Podzemlje vode putovi kroz njenu kuću, dolje u odaje smrti.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 8, 1, 'Ne propovijeda li mudrost i ne diže li razboritost svoj glas?');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 8, 2, 'Navrh brda, uza cestu, na raskršćima stoji,');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 8, 3, 'kod izlaza iz grada, kraj ulaznih vrata, ona glasno viče:');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 8, 4, '\"Vama, o ljudi, propovijedam i upravljam svoj glas sinovima ljudskim.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 8, 5, 'Shvatite mudrost, vi neiskusni, a vi nerazumni, urazumite srce.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 8, 6, 'Slušajte, jer ću zboriti o važnim stvarima, i moje će usne otkriti što je pravo.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 8, 7, 'Jer moje nepce zbori istinu i zloća je mojim usnama mrska.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 8, 8, 'Sve su riječi mojih usta pravične, u njima nema ništa ni krivo ni prijetvorno.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 8, 9, 'Sve su one jasne razboritomu i pravedne onomu tko je stekao spoznaju.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 8, 10, 'Primajte radije moju pouku no srebro i znanje požudnije od zlata.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 8, 11, 'Jer mudrost je vrednija od biserja i nikakve se dragocjenosti ne mogu porediti s njom.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 8, 12, 'Ja, mudrost, boravim s razboritošću i posjedujem znanje umna djelovanja.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 8, 13, 'Strah Gospodnji mržnja je na zlo. Oholost, samodostatnost, put zloće i usta puna laži - to ja mrzim.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 8, 14, 'Moji su savjet i razboritost, ja sam razbor i moja je jakost.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 8, 15, 'Po meni kraljevi kraljuju i velikaši dijele pravdu.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 8, 16, 'Po meni knezuju knezovi i odličnici i svi suci zemaljski.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 8, 17, 'Ja ljubim one koji ljube mene i nalaze me koji me traže.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 8, 18, 'U mene je bogatstvo i slava, postojano dobro i pravednost.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 8, 19, 'Moj je plod bolji od čista i žežena zlata i moj je prihod bolji od čistoga srebra.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 8, 20, 'Ja kročim putem pravde, sred pravičnih staza,');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 8, 21, 'da dadem dobra onima koji me ljube i napunim njihove riznice.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 8, 22, 'Jahve me stvori kao počelo svoga djela, kao najraniji od svojih čina, u pradoba;');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 8, 23, 'oblikovana sam još od vječnosti, odiskona, prije nastanka zemlje.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 8, 24, 'Rodih se kad još nije bilo pradubina, dok nije bilo izvora obilnih voda.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 8, 25, 'Rodih se prije nego su utemeljene gore, prije brežuljaka.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 8, 26, 'Kad još ne bijaše načinio zemlje, ni poljana, ni početka zemaljskom prahu;');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 8, 27, 'kad je stvarao nebesa, bila sam nazočna, kad je povlačio krug na licu bezdana.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 8, 28, 'Kad je u visini utvrđivao oblake i kad je odredio snagu izvoru pradubina;');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 8, 29, 'kad je postavljao moru njegove granice da mu se vode ne preliju preko obala, kad je polagao temelje zemlji,');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 8, 30, 'bila sam kraj njega, kao graditeljica, bila u radosti, iz dana u dan, igrajući pred njim sve vrijeme:');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 8, 31, 'igrala sam po tlu njegove zemlje, i moja su radost djeca čovjekova.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 8, 32, 'Tako, djeco, poslušajte me, blago onima koji čuvaju moje putove.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 8, 33, 'Poslušajte pouku - da stečete mudrost i nemojte je odbaciti.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 8, 34, 'Blago čovjeku koji me sluša i bdi na mojim vratima svaki dan i koji čuva dovratnike moje.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 8, 35, 'Jer tko nalazi mene, nalazi život i stječe milost od Jahve.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 8, 36, 'A ako se ogriješi o mene, udi svojoj duši: svi koji mene mrze ljube smrt.\"');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 9, 1, 'Mudrost je sazidala sebi kuću, i otesala sedam stupova.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 9, 2, 'Poklala je svoje klanice, pomiješala svoje vino i postavila svoj stol.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 9, 3, 'Poslala je svoje djevojke da objave svrh gradskih visina:');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 9, 4, '\"Tko je neiskusan, neka se svrati ovamo!\" A nerazumnima govori:');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 9, 5, '\"Hodite, jedite od mojega kruha i pijte vina koje sam pomiješala.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 9, 6, 'Ostavite ludost, da biste živjeli, i hodite putem razboritosti.\"');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 9, 7, 'Tko poučava podrugljivca, prima pogrdu, i tko prekorava opakoga, prima ljagu.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 9, 8, 'Ne kori podsmjevača, da te ne zamrzi; kori mudra, da te zavoli.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 9, 9, 'Pouči mudroga, i bit će još mudriji; uputi pravednoga, i uvećat će se njegovo znanje.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 9, 10, 'Gospodnji strah početak je mudrosti, a razboritost je spoznaja Presvetog.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 9, 11, '\"Po meni ti se umnožavaju dani i množe ti se godine života.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 9, 12, 'Ako si mudar, sebi si mudar; budeš li podsmjevač, sam ćeš snositi.\"');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 9, 13, 'Gospođa ludost puna je strasti, prosta je i ne zna ništa.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 9, 14, 'I sjedi na vratima svoje kuće na stolici, u gradskim visinama,');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 9, 15, 'te poziva one koji prolaze putem, koji ravno idu svojim stazama:');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 9, 16, '\"Tko je neiskusan, neka se svrati ovamo!\" I nerazumnomu govori:');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 9, 17, '\"Kradena je voda slatka i ugodno je potajno jesti kruh.\"');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 9, 18, 'A on ne zna da su Sjene ondje, da uzvanici njezini počivaju u Podzemlju.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 10, 1, 'Mudar sin veseli oca, a lud je sin žalost majci svojoj.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 10, 2, 'Ne koristi krivo stečeno blago, dok pravednost izbavlja od smrti.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 10, 3, 'Ne dopušta Jahve da gladuje duša pravednika, ali odbija pohlepu opakih.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 10, 4, 'Lijena ruka osiromašuje čovjeka, a marljiva ga obogaćuje.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 10, 5, 'Tko sabira ljeti, razuman je sin, a tko hrče o žetvi, navlači sramotu.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 10, 6, 'Blagoslovi su nad glavom pravedniku, a usta opakih kriju nasilje.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 10, 7, 'Pravednikov je spomen blagoslovljen, a opakom se ime proklinje.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 10, 8, 'Tko je mudra srca, prima zapovijedi, dok brbljava luda propada.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 10, 9, 'Tko nedužno živi, hodi bez straha, a tko ide krivim putovima, poznat će se.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 10, 10, 'Tko žmirka okom, zadaje tugu, a tko ludo zbori, propada.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 10, 11, 'Pravednikova su usta izvor života, a opakomu usta kriju nasilje.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 10, 12, 'Mržnja izaziva svađu, a ljubav pokriva sve pogreške.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 10, 13, 'Na usnama razumnoga nalazi se mudrost, a batina je za leđa nerazumna čovjeka.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 10, 14, 'Mudri kriju znanje, a luđakova su usta blizu propasti.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 10, 15, 'Blago je bogatomu tvrdi grad, a ubogima je propast njihovo siromaštvo.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 10, 16, 'Pravednik prirađuje za život, a opaki prirađuje za grijeh.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 10, 17, 'Tko se naputka drži, na putu je života, a zabluđuje tko se na ukor ne osvrće.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 10, 18, 'Lažljive usne kriju mržnju, a tko klevetu širi, bezuman je!');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 10, 19, 'Obilje riječi ne biva bez grijeha, a tko zauzdava svoj jezik, razuman je.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 10, 20, 'Pravednikov je jezik odabrano srebro, a razum opakoga malo vrijedi.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 10, 21, 'Pravednikove su usne hrana mnogima, a luđaci umiru s ludosti svoje.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 10, 22, 'Gospodnji blagoslov obogaćuje i ne prati ga nikakva muka.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 10, 23, 'Bezumniku je radost učiniti sramotno djelo, a razumnu čovjeku biti mudar.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 10, 24, 'Čega se opaki boji, ono će ga stići, a pravednička se želja ispunjava.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 10, 25, 'Kad oluja prohuja, opakoga nestane, a pravednik ima temelj vječni.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 10, 26, 'Kakav je ocat zubima i dim očima, takav je ljenivac onima koji ga šalju.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 10, 27, 'Strah Gospodnji umnaža dane, a opakima se prekraćuju godine.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 10, 28, 'Pravedničko je ufanje puno radosti, a opakima je nada uprazno.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 10, 29, 'Gospodnji je put okrilje bezazlenu, a propast onima koji čine zlo.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 10, 30, 'Pravednik se neće nikad pokolebati, a opakih će nestati s lica zemlje.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 10, 31, 'Pravednikova usta rađaju mudrošću, a opak jezik čupa se s korijenom.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 10, 32, 'Pravednikove usne znaju što je milo, dok usta opakih poznaju zloću.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 11, 1, 'Lažna je mjera mrska Jahvi, a puna mjera mila mu je.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 11, 2, 'S ohološću dolazi sramota, a u smjernih je mudrost.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 11, 3, 'Pravednike vodi nevinost njihova, a bezbožnike upropašćuje njihova opačina.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 11, 4, 'Ne pomaže bogatstvo u dan Božje srdžbe, a pravednost izbavlja od smrti.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 11, 5, 'Nedužnomu pravda njegova put utire, a zao propada od svoje zloće.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 11, 6, 'Poštene izbavlja pravda njihova, a bezbožnici se hvataju u svoju lakomost.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 11, 7, 'Kad zao čovjek umre, nada propada i ufanje u imetak ruši se.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 11, 8, 'Pravednik se od tjeskobe izbavlja, a opaki dolazi na mjesto njegovo.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 11, 9, 'Bezbožnik ustima ubija svoga bližnjega, a pravednici se izbavljaju znanjem.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 11, 10, 'Sa sreće pravedničke grad se raduje i klikuje zbog propasti opakoga.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 11, 11, 'Blagoslovom pravednika grad se diže, a ustima opakih razara se.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 11, 12, 'Nerazumnik prezire svoga bližnjega, dok čovjek uman šuti.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 11, 13, 'Tko s klevetom hodi, otkriva tajnu, a čovjek pouzdana duha čuva se.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 11, 14, 'Gdje vodstva nema, narod propada, jer spasenje je u mnogim savjetnicima.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 11, 15, 'Veoma zlo prolazi tko jamči za drugoga, a bez straha je tko mrzi na jamstvo.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 11, 16, 'Ljupka žena stječe slavu, a krepki muževi bogatstvo.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 11, 17, 'Dobrostiv čovjek sam sebi dobro čini, a okrutnik muči vlastito tijelo.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 11, 18, 'Opak čovjek pribavlja isprazan dobitak, a tko sije pravdu, ima sigurnu nagradu.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 11, 19, 'Tko je čvrst u pravednosti, ide u život, a tko za zlom trči, na smrt mu je.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 11, 20, 'Mrski su Jahvi srcem opaki, a mili su mu životom savršeni.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 11, 21, 'Zaista, zao čovjek neće proći bez kazne, a rod će se pravednički izbaviti.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 11, 22, 'Zlatan je kolut na rilu svinjskom: žena lijepa, a bez razuma.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 11, 23, 'Pravednička je želja samo na sreću, a nada je opakih prolazna.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 11, 24, 'Tko dijeli obilato, sve više ima, a tko škrtari, sve je siromašniji.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 11, 25, 'Podašna duša nalazi okrepu, i tko napaja druge, sam će se napojiti.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 11, 26, 'Tko ne da žita, kune ga narod, a blagoslov je nad glavom onoga koji ga prodaje.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 11, 27, 'Tko traži dobro, nalazi milost, a tko za zlom ide, ono će ga snaći.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 11, 28, 'Tko se uzda u bogatstvo, propada, a pravednici uspijevaju kao zeleno lišće.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 11, 29, 'Tko vlastitu kuću zapusti, vjetar žanje, a luđak je sluga mudromu.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 11, 30, 'Plod je pravednikov drvo života, i mudrac je tko predobiva žive duše.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 11, 31, 'Ako se pravedniku plaća na zemlji, još će se više opakomu i grešniku.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 12, 1, 'Tko ljubi pouku, ljubi znanje, a tko mrzi ukor, lud je.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 12, 2, 'Dobar dobiva milost od Jahve, a podmukao osudu.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 12, 3, 'Zloćom se čovjek ne utvrđuje, a korijen se pravedniku ne pomiče.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 12, 4, 'Kreposna je žena vijenac mužu svojemu, a sramotna mu je kao gnjilež u kostima.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 12, 5, 'Pravedničke su misli pravične, spletke opakih prijevarne.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 12, 6, 'Riječi opakih pogubne su zamke, a pravedne izbavljaju usta njihova.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 12, 7, 'Opaki se ruše i nema ih više, a kuća pravednika ostaje.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 12, 8, 'Čovjek se hvali po oštrini svoga razuma, a prezire se tko je opak srcem.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 12, 9, 'Bolje je biti malen i imati samo jednog slugu nego se hvastati a nemati ni kruha.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 12, 10, 'Pravednik pazi i na život svog živinčeta, dok je opakomu srce okrutno.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 12, 11, 'Tko obrađuje svoju zemlju, sit je kruha, a tko trči za ništavilom, nerazuman je.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 12, 12, 'Čežnja je opakoga mreža od zala, a korijen pravednika daje ploda.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 12, 13, 'Opakomu je zamka grijeh njegovih usana, a pravednik se izbavlja od tjeskobe.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 12, 14, 'Od ploda svojih usta nasitit će se svatko obilno, a ono što je rukama učinio vratit će mu se.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 12, 15, 'Luđaku se čini pravim njegov put, a mudar čovjek sluša savjete.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 12, 16, 'Luđak odmah odaje svoj bijes, a pametan pokriva sramotu.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 12, 17, 'Tko govori istinu, otkriva što je pravo, a lažljiv svjedok prijevaru.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 12, 18, 'Nesmotren govori kao da mačem probada, a jezik je mudrih iscjeljenje.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 12, 19, 'Istinita usta traju dovijeka, a lažljiv jezik samo za čas.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 12, 20, 'Prijevara je u srcu onih koji snuju zlo, a veselje u onih koji dijele miroljubive savjete.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 12, 21, 'Pravednika ne stiže nikakva nevolja, a opaki u zlu grcaju.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 12, 22, 'Mrske su Jahvi usne lažljive, a mili su mu koji zbore istinu.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 12, 23, 'Promišljen čovjek prikriva svoje znanje, a srce bezumničko razglašuje svoju ludost.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 12, 24, 'Marljiva ruka vlada, a nemar vodi u podložnost.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 12, 25, 'Briga u srcu pritiskuje čovjeka, a blaga riječ veseli ga.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 12, 26, 'Pravednik vodi svojeg prijatelja, a opake zavodi njihov put.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 12, 27, 'Nemaran ne ulovi svoje lovine, a marljivost je čovjeku blago dragocjeno.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 12, 28, 'Na stazi pravice stoji život i na njezinu putu nema smrti.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 13, 1, 'Mudar sin sluša naputak očev, a podsmjevač ne sluša ukora.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 13, 2, 'Od ploda usta svojih uživa čovjek sreću, a srce je nevjernika puno nasilja.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 13, 3, 'Tko čuva usta svoja, čuva život svoj, a tko nesmotreno zbori, o glavu mu je.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 13, 4, 'Uzaludna je žudnja lijenčine, a ispunit će se želja marljivih.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 13, 5, 'Pravednik mrzi na lažljivu riječ, a opaki goji mržnju i sramotu.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 13, 6, 'Pravda čuva pobožna, a opake grijeh obara.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 13, 7, 'Netko se gradi bogatim, a ništa nema, netko se gradi siromašnim, a ima veliko bogatstvo.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 13, 8, 'Otkup života bogatstvo je čovjeku; a siromah ne sluša opomene.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 13, 9, 'Svjetlost pravednička blistavo sja, a svjetiljka opakih gasi se.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 13, 10, 'Oholost rađa samo svađu, a mudrost je u onih koji primaju savjet.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 13, 11, 'Naglo stečeno bogatstvo iščezava, a tko sabire pomalo, biva bogat.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 13, 12, 'Predugo očekivanje ubija srce, a ispunjena želja drvo je života.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 13, 13, 'Tko riječ prezire, taj propada, a tko poštiva zapovijedi, plaću dobiva.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 13, 14, 'Pouka mudračeva izvor je životni, ona izbavlja od zamke smrti.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 13, 15, 'Uvid u dobro pribavlja milost, a put bezbožnika hrapav je.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 13, 16, 'Svatko pametan djeluje promišljeno, a bezumnik se hvališe svojom ludošću.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 13, 17, 'Zao glasnik zapada u zlo, a vjeran poslanik donosi spasenje.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 13, 18, 'Siromaštvo i sramota onomu tko odbija pouku, a tko ukor prima, doći će do časti.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 13, 19, 'Slatka je duši ispunjena želja, a bezumnicima je mrsko kloniti se oda zla.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 13, 20, 'Druži se s mudrima, i postat ćeš mudar, a tko se drži bezumnika, postaje opak.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 13, 21, 'Grešnika progoni zlo, a dobro je nagrada pravednima.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 13, 22, 'Valjan čovjek ostavlja baštinu unucima, a bogatstvo se grešnikovo čuva pravedniku.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 13, 23, 'Izobilje je hrane na krčevini siromaškoj, a ima i tko propada s nepravde.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 13, 24, 'Tko štedi šibu, mrzi na sina svog, a tko ga ljubi, na vrijeme ga opominje.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 13, 25, 'Pravednik ima jela do sitosti, a trbuh opakih poznaje oskudicu.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 14, 1, 'Ženska mudrost sagradi kuću, a ludost je rukama razgrađuje.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 14, 2, 'Tko živi s poštenjem, boji se Jahve, a tko ide stranputicom, prezire ga.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 14, 3, 'U luđakovim je ustima šiba za oholost njegovu, a mudre štite vlastite usne.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 14, 4, 'Gdje nema volova, prazne su jasle, a obilna je žetva od snage bikove.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 14, 5, 'Istinit svjedok ne laže, a krivi svjedok širi laž.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 14, 6, 'Podsmjevač traži mudrost i ne nalazi je, a razumni lako dolazi do znanja.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 14, 7, 'Idi od čovjeka bezumna jer nećeš upoznati usne što zbore znanje.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 14, 8, 'Mudrost je pametna čovjeka u tom što pazi na svoj put, a bezumnička ludost prijevara je.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 14, 9, 'Luđacima je grijeh šala, a milost je Božja s poštenima.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 14, 10, 'Srce poznaje svoj jad, i veselje njegovo ne može dijeliti nitko drugi.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 14, 11, 'Dom opakih propast će, a šator će pravednika procvasti.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 14, 12, 'Neki se put učini čovjeku prav, a na koncu vodi k smrti.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 14, 13, 'I u smijehu srce osjeća bol, a poslije veselja dolazi tuga.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 14, 14, 'Otpadnik se siti svojim prestupcima, a dobar čovjek svojim radom.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 14, 15, 'Glupan vjeruje svakoj riječi, a pametan pazi na korak svoj.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 14, 16, 'Mudar se boji i oda zla se uklanja, a bezuman se raspaljuje i bez straha je.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 14, 17, 'Nagao čovjek čini ludosti, a razborit ih podnosi.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 14, 18, 'Glupaci baštine ludost, a mudre ovjenčava znanje.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 14, 19, 'Zli padaju ničice pred dobrima i opaki pred vratima pravednikovim.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 14, 20, 'I svom prijatelju mrzak je siromah, a bogataš ima mnogo ljubitelja.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 14, 21, 'Griješi tko prezire bližnjega svoga, a blago onomu tko je milostiv ubogima.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 14, 22, 'Koji snuju zlo, ne hode li stranputicom, a zar nisu dobrota i vjernost s onima koji snuju dobro?');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 14, 23, 'U svakom trudu ima probitka, a pusto brbljanje samo je na siromaštvo.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 14, 24, 'Mudrima je vijenac bogatstvo njihovo, a bezumnima kruna - njihova ludost.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 14, 25, 'Istinit svjedok izbavlja duše, a tko laži širi, taj je varalica.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 14, 26, 'U strahu je Gospodnjem veliko pouzdanje i njegovim je sinovima utočište.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 14, 27, 'Strah Gospodnji izvor je života: on izbavlja od zamke smrti.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 14, 28, 'Mnoštvo je naroda ponos kralju, a bez puka knez propada.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 14, 29, 'Tko se teško srdi, velike je razboritosti, a nabusit duhom pokazuje ludost.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 14, 30, 'Mirno je srce život tijelu, a ljubomor je gnjilež u kostima.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 14, 31, 'Tko tlači siromaha huli na stvoritelja, a časti ga tko je milostiv ubogomu.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 14, 32, 'Opaki propada zbog vlastite pakosti, a pravednik i u samoj smrti nalazi utočište.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 14, 33, 'U razumnu srcu mudrost počiva, a što je u bezumnome, to se i pokaže.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 14, 34, 'Pravednost uzvisuje narod, a grijeh je sramota pucima.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 14, 35, 'Kralju je mio razborit sluga, a na sramotna se srdi.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 15, 1, 'Blag odgovor ublažava jarost, a riječ osorna uvećava srdžbu.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 15, 2, 'Jezik mudrih ljudi proslavlja znanje, a usta bezumnih prosipaju ludost.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 15, 3, 'Oči su Jahvine na svakome mjestu i budno motre i zle i dobre.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 15, 4, 'Blaga je besjeda drvo života, a pakosna je rana duhu.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 15, 5, 'Luđak prezire pouku oca svog, a tko ukor prima, pametno čini.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 15, 6, 'U pravednikovoj je kući mnogo blaga, a opaki zarađuje propast svoju.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 15, 7, 'Usne mudrih siju znanje, a srce je bezumnika nepostojano.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 15, 8, 'Žrtva opakog mrska je Jahvi, a mila mu je molitva pravednika.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 15, 9, 'Put opakih Jahvi je mrzak, a mio mu je onaj koji ide za pravicom.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 15, 10, 'Oštra kazna čeka onog tko ostavlja pravi put, a umrijet će tko mrzi ukor.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 15, 11, 'I Šeol i Abadon stoje pred Jahvom, a nekmoli srca sinova ljudskih.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 15, 12, 'Podsmjevač ne ljubi onog tko ga kori: on se ne druži s mudrima.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 15, 13, 'Veselo srce razvedrava lice, a bol u srcu tjeskoba je duhu.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 15, 14, 'Razumno srce traži znanje, a bezumnička se usta bave ludošću.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 15, 15, 'Svi su dani bijednikovi zli, a komu je srce sretno, na gozbi je bez prestanka.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 15, 16, 'Bolje je malo sa strahom Gospodnjim nego veliko blago i s njime nemir.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 15, 17, 'Bolji je obrok povrća gdje je ljubav nego od utovljena vola gdje je mržnja.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 15, 18, 'Gnjevljiv čovjek zameće svađu, a ustrpljiv utišava raspru.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 15, 19, 'Put je ljenivčev kao glogov trnjak, a utrta je staza pravednika.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 15, 20, 'Mudar sin veseli oca, a bezumnik prezire majku svoju.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 15, 21, 'Ludost je veselje nerazumnomu, a razuman čovjek pravo hodi.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 15, 22, 'Ne uspijevaju nakane kad nema vijećanja, a ostvaruju se gdje je mnogo savjetnika.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 15, 23, 'Čovjek se veseli odgovoru usta svojih, i riječ u pravo vrijeme - kako je ljupka!');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 15, 24, 'Razumnu čovjeku put života ide gore, da izmakne carstvu smrti koje je dolje.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 15, 25, 'Jahve ruši kuću oholima, a postavlja među udovici.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 15, 26, 'Mrske su Jahvi zle misli, a dobrostive riječi mile su mu.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 15, 27, 'Tko se grabežu oda, razara svoj dom, a tko mrzi mito, živjet će.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 15, 28, 'Pravednikovo srce smišlja odgovor, a opakomu usta govore zlobom.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 15, 29, 'Daleko je Jahve od opakih, a uslišava molitvu pravednih.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 15, 30, 'Bistar pogled razveseli srce i radosna vijest oživi kosti.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 15, 31, 'Uho koje posluša spasonosan ukor prebiva među mudracima.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 15, 32, 'Tko odbaci pouku, prezire vlastitu dušu, a tko posluša ukor, stječe razboritost.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 15, 33, 'Strah je Gospodnji škola mudrosti, jer pred slavom ide poniznost.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 16, 1, 'Čovjek snuje u srcu, a od Jahve je što će jezik odgovoriti.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 16, 2, 'Čovjeku se svi njegovi putovi čine čisti, a Jahve ispituje duhove.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 16, 3, 'Prepusti Jahvi svoja djela, i tvoje će se namisli ostvariti.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 16, 4, 'Jahve je sve stvorio u svoju svrhu, pa i opakoga za dan zli.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 16, 5, 'Mrzak je Jahvi svatko ohola duha: takav zaista ne ostaje bez kazne.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 16, 6, 'Ljubavlju se i vjernošću pomiruje krivnja, i strahom se Gospodnjim uklanja zlo.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 16, 7, 'Kad su Jahvi mili putovi čovječji, i neprijatelje njegove miri s njim.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 16, 8, 'Bolje je malo s pravednošću nego veliki dohoci s nepravdom.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 16, 9, 'Srce čovječje smišlja svoj put, ali Jahve upravlja korake njegove.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 16, 10, 'Proročanstvo je na usnama kraljevim: u osudi se njegova usta neće ogriješiti.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 16, 11, 'Mjere i tezulje pripadaju Jahvi; njegovo su djelo i svi utezi.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 16, 12, 'Mrsko je kraljevima počiniti opačinu, jer se pravdom utvrđuje prijestolje.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 16, 13, 'Mile su kraljevima usne pravedne i oni ljube onog koji govori pravo.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 16, 14, 'Jarost je kraljeva vjesnik smrti ali je mudar čovjek ublaži.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 16, 15, 'U kraljevu je vedru licu život, i njegova je milost kao oblak s kišom proljetnom.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 16, 16, 'Probitačnije je steći mudrost nego zlato, i stjecati razbor dragocjenije je nego srebro.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 16, 17, 'Životni je put pravednih: kloniti se zla, i tko pazi na svoj put, čuva život svoj.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 16, 18, 'Pred slomom ide oholost i pred padom uznositost.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 16, 19, 'Bolje je biti krotak s poniznima nego dijeliti plijen s oholima.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 16, 20, 'Tko pazi na riječ, nalazi sreću, i tko se uzda u Jahvu, blago njemu.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 16, 21, 'Mudar srcem naziva se razumnim i prijazne usne uvećavaju znanje.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 16, 22, 'Izvor je životni razum onima koji ga imaju, a ludima je kazna njihova ludost.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 16, 23, 'Mudračev duh urazumljuje usta njegova, na usnama mu znanje umnožava.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 16, 24, 'Saće meda riječi su ljupke, slatke duši i lijek kostima.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 16, 25, 'Neki se put čini čovjeku prav, a na kraju vodi k smrti.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 16, 26, 'Radnikova glad radi za nj; jer ga tjeraju usta njegova.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 16, 27, 'Bezočnik pripravlja samo zlo i na usnama mu je oganj plameni.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 16, 28, 'Himben čovjek zameće svađu i klevetnik razdor među prijatelje.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 16, 29, 'Nasilnik zavodi bližnjega svoga i navodi ga na rđav put.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 16, 30, 'Tko očima namiguje, himbu smišlja, a tko usne stišće, već je smislio pakost.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 16, 31, 'Sijede su kose prekrasna kruna, nalaze se na putu pravednosti.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 16, 32, 'Tko se teško srdi, bolji je od junaka, i tko nad sobom vlada, bolji je od osvojitelja grada.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 16, 33, 'U krilo plašta baca se kocka, ali je od Jahve svaka odluka.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 17, 1, 'Bolji je zalogaj suha kruha s mirom nego sa svađom kuća puna žrtvene pečenke.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 17, 2, 'Razuman sluga vlada nad sinom sramotnim i s braćom će dijeliti baštinu.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 17, 3, 'Taljika je za srebro i peć za zlato, a srca iskušava Jahve sam.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 17, 4, 'Zločinac rado sluša usne prijevarne, i lažac spremno prisluškuje pogubnu jeziku.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 17, 5, 'Tko se ruga siromahu, podruguje se Stvoritelju njegovu, i tko se veseli nesreći, ne ostaje bez kazne.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 17, 6, 'Unuci su vijenac starcima, a sinovima ures oci njihovi.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 17, 7, 'Ne dolikuje budali uzvišena besjeda, a još manje odličniku usne lažljive.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 17, 8, 'Dar je čarobni kamen u očima onoga koji ga daje: kamo se god okrene, uspijeva.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 17, 9, 'Tko prikriva prijestup, traži ljubav, a tko glasinu širi, razgoni prijatelje.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 17, 10, 'Razumna se ukor jače doima nego bezumna stotina udaraca.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 17, 11, 'Opak čovjek ide samo za zlom, ali se okrutan glasnik šalje na nj.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 17, 12, 'Bolje je nabasati na medvjedicu kojoj ugrabiše mlade nego na bezumnika u njegovoj ludosti.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 17, 13, 'Tko dobro zlom uzvraća neće ukloniti nesreću od doma svojeg.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 17, 14, 'Zametnuti svađu isto je kao pustiti poplavu: stoga prije nego svađa izbije, udalji se!');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 17, 15, 'Tko opravdava krivoga i tko osuđuje pravoga, obojica su mrski Jahvi.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 17, 16, 'Čemu novac u ruci bezumnomu? Da njime mudrost kupi, kad nema razbora!');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 17, 17, 'Prijatelj ljubi u svako vrijeme, a u nevolji i bratom postaje.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 17, 18, 'Nerazuman čovjek daje ruku i jamči pred svojim bližnjim.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 17, 19, 'Grijeh ljubi tko ljubi svađu, i tko visoko diže svoja vrata, traži propast.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 17, 20, 'Opak srcem ne nalazi sreće, i komu je jezik zao, zapada u nesreću.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 17, 21, 'Tko rodi bezumna, na tugu mu je; a nije veseo ni otac budale.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 17, 22, 'Veselo je srce izvrstan lijek, a neveseo duh suši kosti.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 17, 23, 'Opaki prima dar iz njedara da bi iskrivio putove pravici.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 17, 24, 'Razuman ima mudrost pred sobom, a bezumniku su oči na kraj zemlje.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 17, 25, 'Briga je ocu bezuman sin i žalost roditeljki svojoj.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 17, 26, 'Ne valja kažnjavati pravednika, a nije pravo ni tući odličnike.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 17, 27, 'Tko usteže svoje riječi, razumije mudrost, i razuman je čovjek mirna duha.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 17, 28, 'I luđak se smatra mudrim kada šuti i razumnim kad susteže svoje usne.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 18, 1, 'Vlastitoj požudi popušta onaj tko zastranjuje, i svađa se usprkos svakom razboru.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 18, 2, 'Bezumnomu nije mio razum; stalo mu je dati srcu oduška.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 18, 3, 'Kad dolazi opačina, dolazi i prezir i bruka sa sramotom.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 18, 4, 'Duboke su vode riječi iz usta nečijih, izvor mudrosti bujica što se razlijeva.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 18, 5, 'Ne valja se obazirati na opaku osobu, da se pravedniku nanese nepravda na sudu.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 18, 6, 'Bezumnikove se usne upuštaju u svađu i njegova usta izazivlju udarce.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 18, 7, 'Bezumnomu su propast vlastita usta i usne su mu zamka životu.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 18, 8, 'Klevetnikove su riječi kao poslastice: spuštaju se u dno utrobe.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 18, 9, 'Tko je nemaran u svom poslu, brat je onomu koji rasipa.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 18, 10, 'Tvrda je kula ime Jahvino: njemu se pravednik utječe i nalazi utočišta.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 18, 11, 'Bogatstvo je bogatašu njegova tvrđava i kao visok zid u mašti njegovoj.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 18, 12, 'Pred slomom se oholi srce čovječje, a pred slavom ide poniznost.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 18, 13, 'Tko odgovara prije nego što sasluša, na ludost mu je i sramotu.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 18, 14, 'Kad je čovjek bolestan, njegov ga duh podiže, a ubijen duh tko će podići?');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 18, 15, 'Razumno srce stječe znanje i uho mudrih traži znanje.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 18, 16, 'Dar čovjeku otvara put i vodi ga pred velikaše.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 18, 17, 'Prvi je pravedan u svojoj parnici, a kad dođe njegov protivnik, opovrgne ga.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 18, 18, 'Ždrijeb poravna svađe, pa i među moćnicima odlučuje.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 18, 19, 'Uvrijeđen brat jači je od tvrda grada i svađe su kao prijevornice na tvrđavi.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 18, 20, 'Svatko siti trbuh plodom usta svojih, nasićuje se rodom usana svojih.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 18, 21, 'Smrt i život u vlasti su jeziku, a tko ga miluje, jede od ploda njegova.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 18, 22, 'Tko je našao ženu, našao je sreću i stekao milost od Jahve.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 18, 23, 'Ponizno moleći govori siromah, a grubo odgovara bogataš.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 18, 24, 'Ima prijatelja koji vode u propast, a ima i prijatelja privrženijih od brata.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 19, 1, 'Bolji je siromah koji živi u nedužnosti nego čovjek opakih usana i k tomu bezuman.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 19, 2, 'Revnost bez razboritosti nije dobra, i tko brzo hoda, spotiče se.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 19, 3, 'Ludost čovjeku kvari život, a srce mu se ljuti na Jahvu!');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 19, 4, 'Bogatstvo pribavlja mnoge prijatelje, a siromaha i njegov prijatelj ostavlja.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 19, 5, 'Lažljiv svjekok ne ostaje bez kazne, i tko širi laži, neće uteći.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 19, 6, 'Mnogi laskaju licu odličnikovu i svatko je prijatelj čovjeku darežljivu.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 19, 7, 'Na siromaha mrze sva braća njegova, još više se udaljuju od njega prijatelji njegovi: on hlepi za dobrim riječima, ali ih ne nalazi!');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 19, 8, 'Tko stječe razboritost, ljubi sebe, a tko čuva razum, nalazi sreću.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 19, 9, 'Lažljiv svjedok ne ostaje bez kazne, i tko širi laži, propada.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 19, 10, 'Ne dolikuje bezumnomu živjeti raskošno, a još manje sluzi vlast nad knezovima.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 19, 11, 'Um čovjeka usteže od srdžbe, a čast mu je oprostiti krivicu.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 19, 12, 'Kraljev je gnjev kao rika lavlja, a njegova milost kao rosa bilju.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 19, 13, 'Nesreća je ocu svojemu bezuman sin, i neprestano prokišnjavanje svađe su ženine.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 19, 14, 'Kuća se i bogatstvo baštine od otaca, a od Jahve je žena razumna.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 19, 15, 'Lijenost navlači čovjeku dubok san i nemarna duša gladuje.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 19, 16, 'Tko se drži zapovijedi, čuva život svoj, a tko ne pazi putove svoje, umire.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 19, 17, 'Jahvi pozaima tko je siromahu milostiv, i on će mu platiti dobročinstvo.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 19, 18, 'Kažnjavaj sina svoga dok ima nade, ali ne idi za tim da ga ubiješ.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 19, 19, 'Tko je jarostan, plaća globu, i kad ga štediš, samo uvećavaš njegov gnjev.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 19, 20, 'Slušaj savjet i primaj pouku, kako bi naposljetku postao mudar.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 19, 21, 'Mnogo je namisli u srcu čovječjem, ali što Jahve naumi, to i bude.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 19, 22, 'Dražest je čovjekova u dobroti njegovoj, i bolji je siromah od lažljivca.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 19, 23, 'Strah Gospodnji daje život, i tko se njime ispuni, zlo ga ne pohodi.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 19, 24, 'Lijenčina umače ruku u zdjelu, ali je ustima svojim ne prinosi.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 19, 25, 'Udari podsmjehivača, i lud se opameti; ukori razumnog, i shvatit će znanje.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 19, 26, 'Sin je sramotan i pokvaren tko zlostavlja oca i odgoni majku.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 19, 27, 'Prestani, sine moj, slušati naputke koji odvode od riječi spoznaje!');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 19, 28, 'Nevaljao se svjedok podruguje pravdi i usta opakih gutaju nepravdu.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 19, 29, 'Pripravljene su kazne podsmjevačima i udarci za leđa bezumnika.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 20, 1, 'Vino je podsmjevač, žestoko piće bukač, i tko se njima odaje neće steći mudrosti.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 20, 2, 'Kraljev je gnjev kao rika lavlja: tko ga izaziva, griješi protiv sebe samog.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 20, 3, 'Čast je čovjeku ustegnuti se od raspre, a tko je bezuman počinje svađu.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 20, 4, 'Lijenčina u jesen ne ore: u doba žetve on traži, i ništa nema.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 20, 5, 'Savjet je u srcu čovječjem voda duboka i razuman će je čovjek iscrpsti.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 20, 6, 'Mnogi se naziva dobrim čovjekom, ali tko će naći vjerna čovjeka?');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 20, 7, 'Pravednik hodi u bezazlenosti svojoj: blago sinovima njegovim poslije njega!');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 20, 8, 'Kralj koji sjedi na stolici sudačkoj istražuje svako zlo svojim očima.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 20, 9, 'Tko može reći: \"Očistih srce svoje, oprah se od grijeha svoga?\"');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 20, 10, 'Dvojaki utezi i dvojaka mjera mrski su Jahvi podjednako.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 20, 11, 'I dijete se poznaje po onome što čini, je li čisto i pravedno djelo njegovo.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 20, 12, 'I uho koje čuje i oko koje vidi, oboje je Jahve načinio.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 20, 13, 'Ne ljubi sna, da ne osiromašiš; otvori oči svoje i nasitit ćeš se kruha.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 20, 14, '\"Loše, loše\", govori kupac, a kad ode, hvali se dobrom kupovinom.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 20, 15, 'Ima zlata i mnogih bisera, ali su mudre usne najdragocjeniji nakit.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 20, 16, 'Uzmi haljinu onomu tko je jamčio za drugoga; oplijeni njega umjesto tuđinca.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 20, 17, 'Sladak je čovjeku kruh prijevare, ali mu se usta poslije napune pijeskom.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 20, 18, 'Naumi se provode savjetom: zato dobro razmisli pa vodi boj!');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 20, 19, 'Tko okolo kleveće, otkriva tajne: zato se ne miješaj s onim komu su usne uvijek otvorene.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 20, 20, 'Tko kune oca svoga i majku svoju svjetiljka mu se gasi usred tmine.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 20, 21, 'Od početka brzo stečeno imanje na koncu nije blagoslovljeno.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 20, 22, 'Nemoj govoriti: \"Osvetit ću se za zlo\"; čekaj Jahvu, i on će te spasiti.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 20, 23, 'Mrski su Jahvi dvojaki utezi, i kriva mjera ne valja.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 20, 24, 'Od Jahve su koraci čovječji, i kako da čovjek razumije svoj put?');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 20, 25, 'Zamka je čovjeku nesmotreno reći: \"Ovo je sveto\", a poslije promišljati što je zavjetovao.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 20, 26, 'Mudar kralj umije izlučiti opake i stavlja ih pod točkove.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 20, 27, 'Svjetiljka je Gospodnja duh čovječji: ona istražuje sve do dna utrobe.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 20, 28, 'Dobrota i vjernost čuvaju kralja, jer dobrotom utvrđuje prijestol svoj.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 20, 29, 'Ljepota je mladićima njihova snaga, a starcima je ures sijeda kosa.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 20, 30, 'Krvave masnice očiste zlo i udarci pročiste odaje utrobe.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 21, 1, 'Kraljevo je srce u ruci Jahve kao voda tekućica; vodi ga kuda god hoće.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 21, 2, 'Svaki je put čovjeku pravedan u vlastitim očima, a Jahve ispituje srca.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 21, 3, 'Da se vrši pravda i čini pravo, draže je Jahvi nego žrtva.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 21, 4, 'Ponosite oči i oholo srce i svjetiljka opakih - to je grijeh.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 21, 5, 'Namisli marljivoga samo su na korist, a nagloga samo na siromaštvo.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 21, 6, 'Blago stečeno jezikom lažljivim nestalna je ispraznost onih koji traže smrt.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 21, 7, 'Opake će odnijeti nasilje njihovo jer ne žele činiti pravice.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 21, 8, 'Zapleten je put zločinca, a pravo je djelo čista čovjeka.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 21, 9, 'Bolje je živjeti pod rubom krova nego u zajedničkoj kući sa ženom svadljivom.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 21, 10, 'Duša opakoga želi zlo: u njega nema samilosti ni za bližnjega.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 21, 11, 'Kad se podsmjevač kazni, neiskusan postaje mudar, a mudri iz pouke crpe znanje.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 21, 12, 'Na kuću opakoga pazi Svepravedni i opake strovaljuje u nesreću.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 21, 13, 'Tko zatvori uho svoje pred vikom siromaha, i sam će vikati, ali ga neće nitko uslišati.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 21, 14, 'Potajan dar utišava srdžbu, a poklon ispod ruke i žestoku jarost.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 21, 15, 'Sud pravičan radost je pravedniku a užas zločincima.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 21, 16, 'Čovjek koji skreće s puta razbora počivat će u zboru mrtvačkom.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 21, 17, 'Tko ljubi veselje, postaje siromah, i tko ljubi vino i mirisno ulje, ne obogati se.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 21, 18, 'Opak čovjek otkup je za pravednika, i bezbožnik stupa na mjesto pravednog.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 21, 19, 'Bolje je živjeti u pustinji nego sa ženom svadljivom i gnjevljivom.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 21, 20, 'Krasno je blago i ulje u stanu mudroga, a bezuman ih čovjek rasipa.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 21, 21, 'Tko teži za pravdom i dobrohotnošću, nalazi život i čast.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 21, 22, 'Mudrac nadvladava i grad pun ratnika i krši silu u koju su se uzdali.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 21, 23, 'Tko čuva usta i jezik svoj, čuva sebe od nevolje.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 21, 24, 'Drzovitom i oholici ime je \"podsmjevač\"; on sve radi s prekomjernom drskošću.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 21, 25, 'Lijenčinu ubija želja njegova jer mu ruke bježe od posla.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 21, 26, 'Opak po cio dan živo želi, a pravednik daje i ne škrtari.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 21, 27, 'Mrska je žrtva opakih, osobito kad se požudno prinosi.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 21, 28, 'Lažljiv svjedok propada, a čovjek koji sluša, opet će govoriti.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 21, 29, 'Opaki pokazuju drsko lice, a poštenjak učvršćuje put svoj.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 21, 30, 'Nema mudrosti i nema razuma i nema savjeta protiv Jahve.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 21, 31, 'Konj se oprema za dan boja, ali Jahve daje pobjedu.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 22, 1, 'Dobro je ime bolje od velika bogatstva, i bolja je naklonost od srebra i zlata.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 22, 2, 'Bogataš se i siromah sreću: obojicu ih Jahve stvori.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 22, 3, 'Pametan čovjek vidi zlo i skrije se, a glupaci idu bezbrižno i trpe kaznu.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 22, 4, 'Nagrada je poniznosti strah Gospodnji, bogatstvo, čast i život.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 22, 5, 'Trnje i zamke su na putu varalici: tko čuva život svoj, daleko je od oboga.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 22, 6, 'Upućuj dijete prema njegovu putu, pa kad i ostari, neće odstupiti od njega.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 22, 7, 'Bogataš vlada nad siromasima, a dužnik je sluga vjerovniku.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 22, 8, 'Tko sije nepravdu, žanje nesreću, i šiba njegova gnjeva udarit će njega samog.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 22, 9, 'Milostivo se oko blagoslivlje, jer daje od svog kruha siromahu.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 22, 10, 'Otjeraj podsmjevača i prestat će svađe i nestat će nesloga i pogrda.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 22, 11, 'Jahve ljubi čisto srce, i tko je ljubeznih usana, kralj mu je prijatelj.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 22, 12, 'Pogled Jahvin čuva znanje, Jahve pomućuje riječi bezbožnika.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 22, 13, 'Lijenčina veli: \"Lav je vani, nasred trga poginuo bih.\"');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 22, 14, 'Duboka jama usta su preljubnice, i na koga se Jahve srdi, pada onamo.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 22, 15, 'Ludost prianja uza srce djetinje: šiba pouke otklanja je od njega.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 22, 16, 'Tko tlači siromaha, taj mu koristi; tko daje bogatašu, samo mu šteti.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 22, 17, 'Riječi mudraca: Prigni uho svoje i čuj riječi moje i upravi svoje srce mojem znanju,');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 22, 18, 'jer milina je ako ih čuvaš u nutrini svojoj, i kad ti budu sve spremne na usnama tvojim.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 22, 19, 'Da bi uzdanje tvoje bilo u Jahvi, upućujem danas i tebe.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 22, 20, 'Napisah ti trideset što savjeta što pouka');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 22, 21, 'da te poučim riječima istine, da uzmogneš pouzdanim riječima odgovoriti onomu tko te zapita.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 22, 22, 'Nemoj pljačkati siromaha zato što je siromah i ne gazi ubogoga na sudu.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 22, 23, 'Jer će Jahve parbiti parbu njihovu i otet će život onima koji ga njima otimlju.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 22, 24, 'Ne druži se sa srditim i ne idi s čovjekom jedljivim');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 22, 25, 'da se ne bi privikao na staze njegove i namjestio zamku duši svojoj.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 22, 26, 'Ne budi među onima koji daju ruku, koji jamče za dugove:');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 22, 27, 'ako nemaš čime nadoknaditi, zašto da ti oduzmu i postelju ispod tebe?');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 22, 28, 'Ne pomiči prastare međe koju su postavili oci tvoji.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 22, 29, 'Jesi li vidio čovjeka vična poslu svom: takav ima pristup kraljevima i ne služi prostacima.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 23, 1, 'Kad sjedneš blagovati s moćnikom. dobro pazi što je pred tobom;');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 23, 2, 'stavljaš nož sebi pod grlo ako si proždrljivac;');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 23, 3, 'ne poželi slastica njegovih jer su jelo prijevarno.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 23, 4, 'Ne trudi se stjecati bogatstvo; okani se takve misli;');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 23, 5, 'usmjeriš li oči prema njemu, njega već nema jer načini sebi krila kao orao i odleti u nebo.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 23, 6, 'Ne jedi jela zavidnikova, ne čezni za slasticama njegovim,');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 23, 7, 'jer on je onakav kako u sebi misli: \"Jedi i pij\", veli ti, ali mu srce nije s tobom.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 23, 8, 'Zalogaj koji si pojeo izbljuvat ćeš, uzalud ćeš prosut\' svoje ljupke riječi.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 23, 9, 'Pred bezumnikom nemoj govoriti jer prezire tvoje umne riječi.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 23, 10, 'Ne pomiči prastare međe i ne prodiri u polje siročadi,');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 23, 11, 'jer je moćan njihov osvetnik: branit će njihovo pravo protiv tebe.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 23, 12, 'Obrati pouci srce svoje i uho svoje riječima mudrim.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 23, 13, 'Ne uskraćuj djetetu opomene, jer, udariš li ga šibom, neće umrijeti:');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 23, 14, 'biješ ga šibom, ali mu dušu iz Podzemlja izbavljaš.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 23, 15, 'Sine moj, kad ti je mudro srce, i ja se od srca veselim;');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 23, 16, 'i kliče sva nutrina moja kad ti usne govore što je pravo.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 23, 17, 'Neka ti srce ne zavidi grešnicima, nego neka ti uvijek bude u strahu Gospodnjem,');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 23, 18, 'jer imat ćeš budućnost i tvoja nada neće propasti.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 23, 19, 'Slušaj, sine moj, i mudar budi i ravnim putem vodi srce svoje.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 23, 20, 'Ne druži se s vinopijama ni sa žderačima mesa,');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 23, 21, 'jer pijanica i izjelica osiromaše i pospanac se oblači u krpe.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 23, 22, 'Slušaj svoga oca, svoga roditelja, i ne prezri majku kad ostari.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 23, 23, 'Pribavi istinu i ne prodaji je, steci mudrost, pouku i razbor.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 23, 24, 'Radovat će se otac pravednikov, i roditelj će se mudroga veseliti.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 23, 25, 'Neka se veseli otac tvoj i majka tvoja, i neka se raduje roditeljka tvoja.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 23, 26, 'Daj mi, sine moj, srce svoje, i neka oči tvoje raduju putovi moji.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 23, 27, 'Jer bludnica je jama duboka i tuđinka tijesan zdenac.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 23, 28, 'Ona i vreba u zasjedi kao lupež i uvećava broj bezbožnika među ljudima.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 23, 29, 'Komu: ah? komu: jao? komu: svađe? komu: uzdasi? komu: rane nizašto? komu: zamućene oči?');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 23, 30, 'Onima što kasno sjede kod vina, koji su došli kušati vino začinjeno.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 23, 31, 'Ne gledaj na vino kad rujno iskri, kad se u čaši svjetlucavo prelijeva: pije se tako glatko,');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 23, 32, 'a na kraju ujeda kao zmija i žaca kao guja ljutica.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 23, 33, 'Oči će ti gledati tlapnje i srce govoriti ludosti.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 23, 34, 'I bit će ti kao da ležiš na pučini morskoj ili kao da ležiš navrh jarbola.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 23, 35, '\"Izbiše me, ali me ne zabolje; istukoše me, ali ne osjetih; kad se otrijeznim, još ću tražiti.\"');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 24, 1, 'Ne zavidi opakim ljudima niti želi da budeš s njima.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 24, 2, 'Jer im srce smišlja nasilje i usne govore o nedjelu.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 24, 3, 'Mudrošću se zida kuća i razborom utvrđuje,');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 24, 4, 'i po znanju se pune klijeti svakim blagom dragocjenim i ljupkim.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 24, 5, 'Bolji je mudar od jakoga i čovjek razuman od silne ljudine.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 24, 6, 'Jer s promišljanjem se ide u boj i pobjeda je u mnoštvu savjetnika.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 24, 7, 'Previsoka je bezumnomu mudrost: zato na sudu ne otvara usta svojih!');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 24, 8, 'Tko smišlja zlo zove se učitelj podmukli.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 24, 9, 'Ludost samo grijeh snuje, i podrugljivac je mrzak ljudima.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 24, 10, 'Kloneš li u dan bijede, bijedna je tvoja snaga.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 24, 11, 'Izbavi one koje vode u smrt; i spasavaj one koji posrćući idu na stratište.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 24, 12, 'Ako kažeš: \"Nismo za to znali\", ne razumije li onaj koji ispituje srca? I ne znade li onaj koji ti čuva dušu? I ne plaća li on svakomu po njegovim djelima?');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 24, 13, 'Jedi med, sine moj, jer je dobar, i saće je slatko nepcu tvome.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 24, 14, 'Takva je, znaj, i mudrost tvojoj duši: ako je nađeš, našao si budućnost i nada tvoja neće propasti.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 24, 15, 'Ne postavljaj, opaki, zasjede stanu pravednikovu, ne čini nasilja boravištu njegovu;');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 24, 16, 'jer padne li pravednik i sedam puta, on ustaje, a opaki propadaju u nesreći.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 24, 17, 'Ne veseli se kad padne neprijatelj tvoj i ne kliči srcem kada on posrće,');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 24, 18, 'da ne bi vidio Jahve i za zlo uzeo i obratio srdžbu svoju od njega.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 24, 19, 'Nemoj se srditi zbog zločinaca, nemoj zavidjeti opakima,');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 24, 20, 'jer zao čovjek nema budućnosti, svjetiljka opakih gasi se.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 24, 21, 'Boj se Jahve, sine moj, i kralja: i ne buni se ni protiv jednoga ni protiv drugoga.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 24, 22, 'Jer iznenada provaljuje nesreća njihova i tko zna kad će doći propast njihova.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 24, 23, 'I ovo je od mudraca: Ne valja biti pristran na sudu.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 24, 24, 'Tko opakomu veli: \"Pravedan si\", proklinju ga narodi i kunu puci;');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 24, 25, 'a oni koji ga ukore nalaze zadovoljstvo, i na njih dolazi blagoslov sreće.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 24, 26, 'U usta ljubi tko odgovara pošteno.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 24, 27, 'Svrši svoj posao vani i uredi svoje polje, potom i kuću svoju zidaj.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 24, 28, 'Ne svjedoči lažno na bližnjega svoga: zar ćeš varati usnama svojim?');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 24, 29, 'Ne reci: \"Kako je on meni učinio, tako ću i ja njemu; platit ću tom čovjeku po djelu njegovu!\"');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 24, 30, 'Prolazio sam mimo polje nekog lijenčine i mimo vinograd nekog luđaka,');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 24, 31, 'i gle, sve bijaše zaraslo u koprive, i sve pokrio čkalj, i kamena ograda porušena.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 24, 32, 'Vidjeh to i pohranih u srcu, promotrih i uzeh pouku:');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 24, 33, '\"Još malo odspavaj, još malo odrijemaj, još malo podvij ruke za počinak,');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 24, 34, 'i doći će tvoje siromaštvo kao skitač i oskudica kao oružanik!\"');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 25, 1, 'I ovo su mudre izreke Salomonove; sabrali ih ljudi Ezekije, kralja judejskog.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 25, 2, 'Slava je Božja sakrivati stvar, a slava kraljevska istraživati je.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 25, 3, 'Neistražljivo je nebo u visinu, zemlja u dubinu i srce kraljevsko.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 25, 4, 'Ukloni trosku od srebra, i uspjet će posao zlataru.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 25, 5, 'Ukloni opakoga ispred kralja, i utvrdit će se pravicom prijestol njegov.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 25, 6, 'Ne veličaj se pred kraljem i ne sjedaj na mjesto velikaško,');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 25, 7, 'jer je bolje da ti se kaže: \"Popni se gore\" nego da te ponize pred odličnikom.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 25, 8, 'Što su ti oči vidjele ne iznosi prebrzo na raspru; jer što ćeš učiniti na koncu kad te opovrgne bližnji tvoj?');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 25, 9, 'Kad si u parbi s bližnjim svojim, ne otkrivaj tuđe tajne,');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 25, 10, 'da te ne izgrdi tko čuje i da ti se kleveta ne vrati.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 25, 11, 'Riječi kazane u pravo vrijeme zlatne su jabuke u srebrnim posudama.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 25, 12, 'Mudrac koji kori uhu je poslušnu zlatan prsten i ogrlica od tanka zlata.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 25, 13, 'Vjeran je glasnik onomu tko ga šalje kao ledena studen u doba žetve: on krijepi dušu svoga gospodara.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 25, 14, 'Tko se diči lažljivim darom, on je kao oblak i vjetar bez kiše.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 25, 15, 'Strpljivošću se ublažava sudac, mek jezik i kosti lomi.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 25, 16, 'Kad naiđeš na med, jedi umjereno, kako se ne bi prejeo i pojedeno izbljuvao.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 25, 17, 'Rijetko zalazi u kuću bližnjega svoga, da te se ne zasiti i ne zamrzi na te.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 25, 18, 'Čovjek koji svjedoči lažno na bližnjega svoga on je kao bojni malj i mač i oštra strijela.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 25, 19, 'Uzdanje u bezbožnika na dan nevolje - krnjav je zub i noga klecava.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 25, 20, 'Kao onaj koji skida haljinu u zimski dan ili ocat lije na ranu, takav je onaj tko pjeva pjesmu turobnu srcu.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 25, 21, 'Ako je gladan neprijatelj tvoj, nahrani ga kruhom, i ako je žedan, napoji ga vodom.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 25, 22, 'Jer mu zgrćeš ugljevlje na glavu i Jahve će ti platiti.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 25, 23, 'Sjeverni vjetar donosi dažd, a himben jezik srdito lice.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 25, 24, 'Bolje je stanovati pod rubom krova nego u zajedničkoj kući sa ženom svadljivom.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 25, 25, 'Kao studena voda žednu grlu, takva je dobra vijest iz zemlje daleke.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 25, 26, 'Kao zatrpan izvor i vrelo zamućeno, takav je pravednik koji kleca pred opakim.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 25, 27, 'Jesti mnogo meda nije dobro niti tražiti pretjerane časti.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 25, 28, 'Grad razvaljen i bez zidova - takav je čovjek koji nema vlasti nad sobom.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 26, 1, 'Kao snijeg ljeti ili kiša o žetvi, tako pristaju počasti bezumnomu.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 26, 2, 'Kao vrabac kad prhne i lastavica kad odleti, tako se i bezrazložna kletva ne ispunja.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 26, 3, 'Bič konju, uzda magarcu, a šiba leđima bezumnika.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 26, 4, 'Ne odgovaraj bezumniku po njegovoj ludosti, da mu i sam ne postaneš jednak.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 26, 5, 'Odgovori bezumniku po ludosti njegovoj, da se ne bi učinio sam sebi mudar.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 26, 6, 'Odsijeca noge sebi i gorčinu pije tko po bezumnom poruke šalje.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 26, 7, 'Klecava bedra u hromoga - mudra je izreka u ustima bezumničkim.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 26, 8, 'Kamen za praćku vezuje tko bezumnom iskazuje čast.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 26, 9, 'Trnovita grana u ruci pijanice: mudra izreka u ustima bezumnika.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 26, 10, 'Strijelac koji ranjava sve prolaznike: takav je onaj tko unajmljuje bezumnika.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 26, 11, 'Bezumnik se vraća svojoj ludosti kao što se pas vraća na svoju bljuvotinu.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 26, 12, 'Vidiš li čovjeka koji se sam sebi mudrim čini? Znaj, i od bezumnika ima više nade nego od njega!');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 26, 13, 'Lijenčina veli: \"Zvijer je na putu, i lav je na ulicama.\"');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 26, 14, 'Kao što se vrata okreću na stožerima svojim, tako i lijenčina na postelji svojoj.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 26, 15, 'Lijenčina umače ruku u zdjelu, ali je ne može prinijeti ustima.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 26, 16, 'Lijenčina se čini sebi mudrijim od sedmorice koji umno odgovaraju.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 26, 17, 'Psa za uši hvata tko se, u prolazu, umiješa u raspru koja ga se ne tiče.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 26, 18, 'Kao bjesomučnik koji baca zublje, strelice i sije smrt,');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 26, 19, 'takav je čovjek koji vara bližnjega svoga i veli: \"Samo se našalih.\"');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 26, 20, 'Kad nestane drva, oganj se gasi, i kad više nema klevetnika, prestaje svađa.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 26, 21, 'Ugljen je za žeravnicu i drvo za oganj, a svadljivac da raspaljuje svađu.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 26, 22, 'Klevetnikove su riječi kao slastice: spuštaju se u dno utrobe.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 26, 23, 'Srebrna gleđa preko zemljana suđa: laskave usne i opako srce.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 26, 24, 'Mrzitelj hini usnama svojim, a u sebi nosi prijevaru;');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 26, 25, 'ne vjeruj mu kad ljupkim glasom govori, jer u srcu mu je sedam grdila;');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 26, 26, 'ako himbom skriva mržnju, njegova će se opačina otkriti na zboru.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 26, 27, 'Tko jamu kopa, sam u nju pada, i tko kamen valja, na njega se prevaljuje.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 26, 28, 'Lažljiv jezik mrzi svoje žrtve, laskava usta propast spremaju.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 27, 1, 'Ne hvali se danom sutrašnjim jer ne znaš što danas može donijeti.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 27, 2, 'Neka te hvali drugi, a ne tvoja usta, tuđinac, a ne tvoje usne.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 27, 3, 'Težak je kamen i pijesak je težak, ali je od obojega teži bezumnikov bijes.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 27, 4, 'Jarost je okrutna i srdžba žestoka a tko će odoljeti ljubomoru?');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 27, 5, 'Bolji je javni ukor nego lažna ljubav.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 27, 6, 'Čestiti su udarci prijateljevi, a lažni poljupci neprijateljevi.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 27, 7, 'Sito grlo prezire i med samotok, a gladnu je i sve gorko - slatko.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 27, 8, 'Kao ptica daleko od gnijezda svog, takav je čovjek daleko od svojeg zavičaja.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 27, 9, 'Kao što ulje i kad vesele srce, tako i slatkoća prijateljstva tješi dušu.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 27, 10, 'Ne ostavljaj prijatelja svoga ni prijatelja očeva i ne dolazi u kuću bratovu kad si u nesreći; bolji je susjed blizu nego brat daleko.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 27, 11, 'Budi mudar, sine moj, i obraduj mi srce da mogu odgovoriti onome koji me grdi.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 27, 12, 'Pametan čovjek opazi zlo i skrije se, a glupaci idu bezbrižno i trpe kaznu.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 27, 13, 'Uzmi haljinu onomu tko je jamčio za drugoga i oplijeni ga mjesto tuđinca.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 27, 14, 'Tko pozdravlja svoga prijatelja naglas, a rano ujutro, prima mu se blagoslov za kletvu.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 27, 15, 'Streha što prokišnjava za žestoke kiše i svadljiva žena - jedno su te isto.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 27, 16, 'Tko nju zaustavlja, zaustavlja vjetar i desnicom hvata ulje.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 27, 17, 'Željezo se željezom oštri i čovjek oštri jedan drugoga.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 27, 18, 'Tko čuva smokvu, jede od njena ploda, i tko čuva svoga gospodara, poštiva se.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 27, 19, 'Kao što se u vodi različito odražava lice od lica, tako i u srcu čovjek od čovjeka.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 27, 20, 'Carstvo Smrti i Propast ne mogu se zasititi, tako ni oči čovječje.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 27, 21, 'Taljika je za srebro i peć za zlato, a čovjek se poznaje po ustima koja ga hvale.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 27, 22, 'Da bezumnika stučeš tučkom u stupi, ne bi ga ostavila ludost njegova.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 27, 23, 'Brižno pazi na stoku svoju i srcem se brini o stadima,');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 27, 24, 'jer blago ne traje dovijeka; i baštini li se kruna od koljena do koljena?');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 27, 25, 'Kad trava nikne i zelen se pokaže i bilje se kupi planinsko,');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 27, 26, 'tad su ti janjci za odijelo i jarci za kupovinu polja;');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 27, 27, 'tad imaš izobilje kozjega mlijeka sebi za jelo, i za hranu kući svojoj i za prehranu sluškinjama svojim.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 28, 1, 'Opaki bježe i kad ih nitko ne progoni, a pravednici su neustrašivi kao mladi lav.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 28, 2, 'Kad se u zemlji griješi, mnogi su joj knezovi, a s čovjekom razumnim i umnim uprava je postojana.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 28, 3, 'Čovjek opak koji tlači ubogoga - kiša je razorna poslije koje kruha nema.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 28, 4, 'Koji zapuštaju Zakon, veličaju opake, a koji se drže Zakona, protive im se.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 28, 5, 'Zli ljudi ne razumiju pravice, a koji traže Jahvu, razumiju sve.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 28, 6, 'Bolji je siromah koji živi bezazleno nego bogataš koji kroči krivim putem.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 28, 7, 'Tko se drži Zakona, razuman je sin, a tko se druži s izbjeglicama, sramoti oca svoga.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 28, 8, 'Tko umnožava bogatstvo svoje lihvom i pridom, skuplja ga onomu tko je milostiv ubogima.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 28, 9, 'Tko uklanja uho svoje da ne sluša Zakona, i molitva je njegova mrska.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 28, 10, 'Tko zavodi poštene na put zao, past će u jamu svoju, a pošteni će baštiniti sreću.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 28, 11, 'Bogat se čovjek čini sebi mudrim, ali će ga razuman siromah raskrinkati.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 28, 12, 'Velika je slava kad se raduju pravednici, a kad se dižu opaki, ljudi se kriju.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 28, 13, 'Tko skriva svoje grijehe, nema sreće, a tko ih ispovijeda i odriče ih se, milost nalazi.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 28, 14, 'Blago čovjeku uvijek bojaznu, jer čovjek okorjela srca zapada u nesreću.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 28, 15, 'Lav koji riče i gladan medvjed: takav je opak vladalac siromašnu narodu.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 28, 16, 'Nerazuman knez čini mnoga nasilja, a koji mrzi lakomost, dugo živi.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 28, 17, 'Onaj koga tišti krvna krivica, do groba bježi: ne zaustavljajte ga.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 28, 18, 'Spasava se tko živi pravedno, tko se koleba između dva puta, propada na jednom od njih.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 28, 19, 'Tko obrađuje svoju zemlju, nasitit će se kruha, a tko trči za tlapnjama, nasitit će se siromaštva.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 28, 20, 'Čestit čovjek stječe blagoslov, a tko hrli za bogatstvom, ne ostaje bez kazne.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 28, 21, 'Ne valja biti pristran na sudu, jer i za zalogaj kruha čovjek čini zlo.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 28, 22, 'Pohlepnik hrli za bogatstvom, a ne zna da će ga stići oskudica.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 28, 23, 'Tko kori čovjeka, nalazi poslije veću milost nego onaj koji laska jezikom.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 28, 24, 'Tko pljačka oca svoga i majku svoju i veli: \"Nije grijeh\", drug je razbojniku.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 28, 25, 'Lakomac zameće svađu, a tko se uzda u Jahvu, uspjet će.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 28, 26, 'Bezuman je tko se uzda u svoje srce, a spasava se tko živi mudro.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 28, 27, 'Tko daje siromahu, ne trpi oskudicu; a tko odvraća oči svoje, bit će proklet.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 28, 28, 'Kad se dižu opaki, ljudi se kriju, a kad propadaju, tad se množe pravednici.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 29, 1, 'Čovjek koji, po opomeni, ostaje tvrdoglav, u tren će se slomiti, i neće mu biti spasa.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 29, 2, 'Narod se veseli kad se množe pravednici, a puk uzdiše kad zavlada opaki.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 29, 3, 'Čovjek koji ljubi mudrost, veseli oca svoga, a koji se druži s bludnicama, rasipa imetak.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 29, 4, 'Kralj pravicom održava državu, a ruši je čovjek koji nameće daće.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 29, 5, 'Čovjek koji laska bližnjemu svome razapinje mrežu stopama njegovim.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 29, 6, 'U grijehu je zamka zlu čovjeku, a pravednik likuje i veseli se.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 29, 7, 'Pravednik razumije pravo malenih, a opaki ne shvaća spoznaju.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 29, 8, 'Podsmjevači uzbunjuju grad, a mudri stišavaju srdžbu.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 29, 9, 'Kad se mudrac parbi s bezumnikom, il\' se srdio, il\' se smijao, svejednako mira nema.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 29, 10, 'Krvopije mrze poštenoga, a pravednici mu se za život brinu.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 29, 11, 'Bezumnik izlijeva sav svoj gnjev, a mudrac susteže svoju srdžbu.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 29, 12, 'Ako vladalac posluša riječ lažljivu, sve mu sluge postaju opake.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 29, 13, 'Siromah se i gulikoža susreću: Jahve obojici prosvjetljuje oči.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 29, 14, 'Kralj koji sudi siromasima po istini ima prijesto čvrst dovijeka.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 29, 15, 'Šiba i ukor podaruju mudrost, a razuzdan mladić sramoti majku svoju.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 29, 16, 'Kad se množe opaki, množi se i grijeh, ali pravednici promatraju propast njihovu.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 29, 17, 'Ukori sina svoga, i zadovoljit će te i dati radost duši tvojoj.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 29, 18, 'Kad objave nema, narod se razuzda, a blago onome tko se drži Zakona!');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 29, 19, 'Samim se riječima sluga ne popravlja, jer se ne pokorava iako umom shvaća.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 29, 20, 'Jesi li vidio čovjeka brza na riječima? I bezumnik ima više nade nego on.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 29, 21, 'Tko mazi slugu svoga od djetinjstva bit će mu poslije neposlušan.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 29, 22, 'Gnjevljiv čovjek zameće svađu, a naprasit čovjek počini mnoge grijehe.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 29, 23, 'Oholost ponizuje čovjeka, a ponizan duhom postiže časti.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 29, 24, 'Tko s lupežom plijen dijeli, mrzi sebe samog: čuje proklinjanje i ništa ne otkriva.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 29, 25, 'Strah čovjeku postavlja zamku, a tko se uzda u Jahvu, nalazi okrilje.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 29, 26, 'Mnogi traže milost vladaočevu, ali Jahve dijeli pravdu svakome.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 29, 27, 'Nepravednik je mrzak pravednicima, a pravednik je mrzak opakima.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 30, 1, 'Riječi Agura, sina Jakeova, iz Mase; proročanstvo njegovo za Itiela, za Itiela i Ukala.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 30, 2, 'Da, preglup sam da bih bio čovjek i nemam razbora čovječjeg.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 30, 3, 'Ne stekoh mudrosti i ne poznajem znanosti svetih!');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 30, 4, 'Tko uzađe na nebo i siđe? Tko uhvati vjetar u šake svoje? Tko sabra vode u plašt svoj? Tko postavi krajeve zemaljske? Kako se zove i kako mu se zove sin? Znaš li?');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 30, 5, 'Svaka je Božja riječ prokušana, štit onima koji se u nj uzdaju.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 30, 6, 'Ne dodaji ništa njegovim riječima, da te ne prekori i ne smatra lažljivim.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 30, 7, 'Za dvoje te molim, ne uskrati mi, dok ne umrem:');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 30, 8, 'udalji od mene licemjernu i lažnu riječ; ne daj mi siromaštva ni bogatstva: hrani me kruhom mojim dostatnim;');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 30, 9, 'inače bih, presitivši se, zatajio tebe i rekao: \"Tko je Jahve?\" Ili bih, osiromašivši, krao i oskvrnio ime Boga svojega.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 30, 10, 'Ne klevetaj sluge gospodaru njegovu, jer bi te mogao kleti i ti morao okajati.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 30, 11, 'Ima izrod koji kune oca svoga i ne blagoslivlje majke svoje!');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 30, 12, 'Izrod koji za se misli da je čist, a od kala svojeg nije opran!');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 30, 13, 'Izrod uznositih očiju koji visoko diže svoje trepavice!');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 30, 14, 'Izrod komu su zubi mačevi i očnjaci noževi da proždiru nesretnike na zemlji i siromahe među ljudima!');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 30, 15, 'Pijavica ima dvije kćeri: \"Daj! Daj!\" Postoje tri stvari nezasitne i četiri koje ne kažu: \"Dosta!\"');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 30, 16, 'Carstvo smrti, jalova utroba, zemlja nikad gasna vode i vatra koja nikad ne kaže: \"Dosta!\"');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 30, 17, 'Oko koje se ruga ocu i odriče posluh majci iskljuvat će potočni gavrani i izjesti mladi orlovi.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 30, 18, 'Troje mi je nedokučivo, a četvrto ne razumijem:');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 30, 19, 'put orlov po nebu, put zmijin po stijeni, put lađin posred mora i put muškarčev djevojci.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 30, 20, 'Takav je put preljubnice: najede se, obriše usta i veli: \"Nisam sagriješila.\"');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 30, 21, 'Od troga se zemlja ljulja, a četvrtoga ne može podnijeti:');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 30, 22, 'od roba kad postane kralj i kad se prostak kruha nasiti,');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 30, 23, 'od puštenice kad se uda i sluškinje kad istisne svoju gospodaricu.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 30, 24, 'Četvero je maleno na zemlji, ali mudrije od mudraca:');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 30, 25, 'mravi, nejaki stvorovi, koji sebi ljeti spremaju hranu;');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 30, 26, 'jazavci, stvorovi bez moći, što u stijeni grade sebi stan;');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 30, 27, 'skakavci, koji nemaju kralja, a svi idu u poretku;');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 30, 28, 'gušter, što se rukama hvata, a prodire u kraljevske palače.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 30, 29, 'Troje ima lijep korak, a četvero lijepo hodi:');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 30, 30, 'lav, junak među zvijerima, koji ni pred kim ne uzmiče;');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 30, 31, 'pijetao što se odvažno šeće među kokošima; jarac koji vodi stado; i kralj sa svojom vojskom.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 30, 32, 'Ako si ludovao oholeći se ili to svjesno činio, stavi ruku na usta.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 30, 33, 'Kad se mlijeko metÄe, izlazi maslac; kad se nos pritisne, poteče krv; kad se srdžba potisne, dobiva se spor.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 31, 1, 'Riječ Lemuela, kralja Mase, kojima ga je učila majka njegova.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 31, 2, 'Ne, sine moj! Ne, sine srca mog! Ne, sine zavjeta mojih!');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 31, 3, 'Ne daj snage svoje ženama ni putova svojih zatiračima kraljeva.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 31, 4, 'Nije za kraljeve, Lemuele, ne pristaje kraljevima vino piti, ni glavarima piće opojno,');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 31, 5, 'da u piću ne zaborave zakona i prevrnu pravo nevoljnicima.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 31, 6, 'Dajte žestoko piće onomu koji će propasti i vino čovjeku komu je gorčina u duši:');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 31, 7, 'on će piti i zaboraviti svoju bijedu i neće se više sjećati svoje nevolje.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 31, 8, 'Otvaraj usta svoja za nijemoga i za pravo sviju nesretnika što propadaju.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 31, 9, 'Otvaraj usta svoja, sudi pravedno i pribavi pravo siromahu i nevoljniku.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 31, 10, 'Tko će naći ženu vrsnu? Više vrijedi ona nego biserje.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 31, 11, 'Muževljevo se srce uzda u nju i blagom neće oskudijevati.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 31, 12, 'Ona mu čini dobro, a ne zlo, u sve dane vijeka svojeg.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 31, 13, 'Pribavlja vunu i lan i vješto radi rukama marnim.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 31, 14, 'Ona je kao lađa trgovačka: izdaleka donosi kruh svoj.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 31, 15, 'Još za noći ona ustaje, hrani svoje ukućane i određuje posao sluškinjama svojim.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 31, 16, 'Opazi li polje, kupi ga; plodom svojih ruku sadi vinograd.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 31, 17, 'Opasuje snagom bedra svoja i živo miče rukama.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 31, 18, 'Vidi kako joj posao napreduje: noću joj se ne gasi svjetiljka.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 31, 19, 'Rukama se maša preslice i prstima drži vreteno.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 31, 20, 'Siromahu dlan svoj otvara, ruke pruža nevoljnicima.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 31, 21, 'Ne boji se snijega za svoje ukućane, jer sva čeljad ima po dvoje haljine.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 31, 22, 'Sama sebi šije pokrivače, odijeva se lanom i purpurom.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 31, 23, 'Muž joj je slavan na Vratima, gdje sjedi sa starješinama zemaljskim.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 31, 24, 'Platno tka i prodaje ga i pojase daje trgovcu.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 31, 25, 'Odjevena je snagom i dostojanstvom, pa se smije danu budućem.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 31, 26, 'Svoja usta mudro otvara i pobožan joj je nauk na jeziku.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 31, 27, 'Na vladanje pazi ukućana i ne jede kruha besposlice.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 31, 28, 'Sinovi njezini podižu se i sretnom je nazivaju, i muž njezin hvali je:');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 31, 29, '\"Mnoge su žene bile vrsne, ali ti ih sve nadmašuješ.\"');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 31, 30, 'Lažna je ljupkost, tašta je ljepota: žena sa strahom Gospodnjim zaslužuje hvalu.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 31, 31, 'Plod joj dajte ruku njezinih i neka je na Vratima hvale djela njezina!');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (25, 1, 1, 'Misli Propovjednika, Davidova sina, kralja u Jeruzalemu.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (25, 1, 2, 'Ispraznost nad ispraznošću, veli Propovjednik, ispraznost nad ispraznošću, sve je ispraznost!');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (25, 1, 3, 'Kakva je korist čovjeku od svega truda njegova kojim se trudi pod suncem?');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (25, 1, 4, 'Jedan naraštaj odlazi, drugi dolazi, a zemlja uvijek ostaje.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (25, 1, 5, 'Sunce izlazi, sunce zalazi i onda hiti svojem mjestu odakle izlazi.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (25, 1, 6, 'Vjetar puše na jug i okreće se na sjever, kovitla sad ovamo sad onamo i vraća se u novom vrtlogu.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (25, 1, 7, 'Sve rijeke teku u more i more se ne prepunja; odakle teku rijeke, onamo se vraćaju da ponovo počnu svoj tok.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (25, 1, 8, 'Sve je mučno. Nitko ne može reći da se oči nisu do sita nagledale i uši dovoljno naslušale.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (25, 1, 9, 'Što je bilo, opet će biti, i što se činilo, opet će se činiti, i nema ništa novo pod suncem.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (25, 1, 10, 'Ima li išta o čemu bi se moglo reći: \"Gle, ovo je novo!\" Sve je već davno prije nas postojalo.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (25, 1, 11, 'Samo, od prošlosti ne ostade ni spomena, kao što ni u budućnosti neće biti sjećanja na ono što će poslije doći.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (25, 1, 12, 'Ja, Propovjednik, bijah kralj nad Izraelom u Jeruzalemu.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (25, 1, 13, 'I trudih se da mudrošću istražim i dokučim sve što biva pod nebom; o, kako mučnu zadaću zadade Bog sinovima ljudskim.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (25, 1, 14, 'Vidjeh sve što se čini pod suncem: kakve li ispraznosti i puste tlapnje!');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (25, 1, 15, 'Što je krivo, ne može se ispraviti; čega nema, izbrojiti se ne može.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (25, 1, 16, 'Rekoh onda sam sebi: \"Gle, stekao sam veću mudrost nego bilo tko od mojih prethodnika u Jeruzalemu. Duh moj sabrao je golemu mudrost i znanje.\"');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (25, 1, 17, 'Mudrost pomnjivo proučih, a tako i glupost i ludost, ali sam spoznao da je to pusta tlapnja.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (25, 1, 18, 'Mnogo mudrosti - mnogo jada; što više znanja, to više boli.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (25, 2, 1, 'Tad rekoh u srcu svom: \"Daj da okušam užitak i vidim što naslada pruža\" - ali gle: i to je ispraznost!');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (25, 2, 2, 'O smijehu rekoh: \"Ludost je\"; o užitku: \"Čemu valja?\"');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (25, 2, 3, 'Odlučih tijelo krijepiti vinom, a srce posvetiti mudrosti; poželjeh prigrliti i ludost, kako bih spoznao usrećava li ljude ono što pod nebesima čine za izbrojenih dana svojega života.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (25, 2, 4, 'Učinih velika djela: sazidah sebi palače, zasadih vinograde;');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (25, 2, 5, 'uredih perivoje i voćnjake, nasadih u njima voćke svakojake.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (25, 2, 6, 'Načinih jezera da plodna sadišta natapam.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (25, 2, 7, 'Nakupovah robova i robinja, imadoh i sluge domaće, a tako i stada krupne i sitne stoke više no itko prije mene u Jeruzalemu.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (25, 2, 8, 'Nagomilah srebro i zlato i blago kraljeva i pokrajina, nabavih pjevače i pjevačice i svakoga raskošja ljudskog, sve škrinju na škrinji.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (25, 2, 9, 'I postadoh tako velik, veći no bilo tko prije mene u Jeruzalemu; a nije me ni mudrost moja ostavila.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (25, 2, 10, 'I što god su mi oči poželjele, nisam im uskratio, niti branih srcu svojemu kakva veselja, već se srce moje veselilo svakom trudu mojem, i takva bi nagrada svakom mojem naporu.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (25, 2, 11, 'A onda razmotrih sva svoja djela, sve napore što uložih da do njih dođem - i gle, sve je to opet ispraznost i pusta tlapnja! I ništa nema valjano pod suncem.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (25, 2, 12, 'Okrenuh zatim misao svoju mudrosti, gluposti i ludosti. Što, na priliku, čini kraljev nasljednik? Ono što je već učinjeno.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (25, 2, 13, 'I spoznadoh da je bolja mudrost od ludosti, kao što je svjetlost bolja od tame.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (25, 2, 14, 'Mudracu su oči u glavi, a bezumnik luta u tami. Ali također znam da obojicu stiže ista kob.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (25, 2, 15, 'Zato rekoh u sebi: \"Kakva je sudbina luđaku, takva je i meni. Čemu onda žudjeti za mudrošću?\" I rekoh u srcu: \"I to je ispraznost!\"');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (25, 2, 16, 'Jer trajna spomena nema ni mudru ni bezumniku: obojicu će poslije nekog vremena prekriti zaborav! I, jao, mudrac mora umrijeti kao i bezumnik.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (25, 2, 17, 'Omrznuh život, jer mi se učini mučnim sve što se zbiva pod suncem: sve je ispraznost i pusta tlapnja.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (25, 2, 18, 'Zamrzih sve za što sam se pod suncem trudio i što sad ostavljam svome nasljedniku.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (25, 2, 19, 'Tko zna hoće li on biti mudar ili lud? Pa ipak on će biti gospodar sve moje muke u koju uložih sav svoj napor i mudrost pod suncem. I to je ispraznost.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (25, 2, 20, 'I stao sam srcem očajavati zbog velikog napora kojim sam se trudio pod suncem.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (25, 2, 21, 'Jer čovjek se trudi mudro i umješno i uspješno, pa sve to mora ostaviti u baštinu drugomu koji se oko toga nije uopće trudio. I to je ispraznost i velika nevolja.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (25, 2, 22, 'Jer što on dobiva za sav svoj napor i trud koji je pod suncem podnio?');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (25, 2, 23, 'Jer svi su njegovi dani doista mukotrpni, poslovi mu puni brige; čak ni noću ne miruje srce njegovo. I to je ispraznost.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (25, 2, 24, 'Nema čovjeku druge sreće već jesti i piti i biti zadovoljan svojim poslom. I to je, vidim, dar Božje ruke.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (25, 2, 25, 'Jer tko bi mogao jesti, tko li nezadovoljan biti, osim po njemu.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (25, 2, 26, 'Mudrost, spoznaju, radost on daruje onom tko mu je po volji, a grešniku nameće zadaću da sabira i skuplja za onoga tko je po volji Bogu. I to je ispraznost i pusta tlapnja.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (25, 3, 1, 'Sve ima svoje doba i svaki posao pod nebom svoje vrijeme.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (25, 3, 2, 'Vrijeme rađanja i vrijeme umiranja; vrijeme sađenja i vrijeme čupanja posađenog.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (25, 3, 3, 'Vrijeme ubijanja i vrijeme liječenja; vrijeme rušenja i vrijeme građenja.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (25, 3, 4, 'Vrijeme plača i vrijeme smijeha; vrijeme tugovanja i vrijeme plesanja.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (25, 3, 5, 'Vrijeme bacanja kamenja i vrijeme sabiranja kamenja; vrijeme grljenja i vrijeme kad se ostavlja grljenje.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (25, 3, 6, 'Vrijeme traženja i vrijeme gubljenja; vrijeme čuvanja i vrijeme odbacivanja.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (25, 3, 7, 'Vrijeme deranja i vrijeme š§ijenja; vrijeme šutnje i vrijeme govorenja.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (25, 3, 8, 'Vrijeme ljubljenja i vrijeme mržnje; vrijeme rata i vrijeme mira.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (25, 3, 9, 'Koja je posleniku korist od njegovih napora?');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (25, 3, 10, 'Razmišljam o mučnoj zadaći što je Bog zadade sinovima ljudskim.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (25, 3, 11, 'Sve što on čini prikladno je u svoje vrijeme; ali iako je dopustio čovjeku uvid u vjekove, čovjek ne može dokučiti djela koja Boga čini od početka do kraja.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (25, 3, 12, 'Znam da nije druge sreće čovjeku osim da se veseli i čini dobro za svojega života.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (25, 3, 13, 'I kad čovjek jede i pije i uživa u svojem radu, i to je Božji dar.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (25, 3, 14, 'I znam da sve što Bog čini, čini za stalno. Tome se ništa dodati ne može niti mu se može oduzeti; a Bog čini tako da ga se boje.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (25, 3, 15, 'Što biva, već bijaše, i što će biti, već je bilo; a Bog obnavlja što je prohujalo.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (25, 3, 16, 'Još vidim kako pod suncem umjesto pravice vlada nepravda i umjesto pravednika zločinac.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (25, 3, 17, 'Zato rekoh u sebi: \"Bog će suditi i pravedniku i zločincu, jer ovdje ima vrijeme za svaku namjeru i čin.\"');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (25, 3, 18, 'Još rekoh u sebi: \"Ljudi se ponašaju tako da Bog može pokazati kakvi su uistinu, da su jedni drugima poput zvijeri.\"');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (25, 3, 19, 'Jer zaista, kob ljudi i zvijeri jedna je te ista. Kako ginu oni, tako ginu i one; i dišu jednakim dahom, i čovjek ničim ne nadmašuje zvijer, jer sve je ispraznost.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (25, 3, 20, 'I jedni i drugi odlaze na isto mjesto; svi su postali od praha i u prah se vraćaju.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (25, 3, 21, 'Tko zna da li dah ljudski uzlazi gore, a dah zvijeri silazi dolje k zemlji?');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (25, 3, 22, 'Uviđam da čovjeku druge sreće nema osim radosti u svome djelu, jer to je ljudska sudbina. A tko će ga dovesti do toga da dozna što će biti poslije njega?');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (25, 4, 1, 'Opet stadoh promatrati sva nasilja koja se čine pod suncem, i gle, suze potlačenih, i nikog nema da ih utre; i nasilje iz tlačiteljske ruke, a zaštitnika niotkuda.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (25, 4, 2, 'Zato sretnima smatram mrtve koji su već pomrli; sretniji su od živih što još žive.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (25, 4, 3, 'A od obojih je sretniji onaj koji još nije postao, koji nije vidio zlih djela što se čine pod suncem.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (25, 4, 4, 'Nadalje iskusih da svaki napor i svaki uspjeh pribavlja čovjeku zavist njegova bližnjeg. I to je ispraznost i pusta tlapnja.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (25, 4, 5, 'Bezumnik prekriži ruke i izjeda sebe.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (25, 4, 6, 'Bolja je puna šaka u miru nego obje pregršti mučna rada i puste tlapnje.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (25, 4, 7, 'I još jednu opazih ispraznost pod suncem:');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (25, 4, 8, 'Čovjek potpun samac - bez sina, bez brata, i opet nema kraja njegovu trudu; oči mu se ne mogu nasititi blaga; a ne misli: za koga se mučim i uskraćujem dobro sebi? I to je ispraznost i zla briga.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (25, 4, 9, 'Bolje je dvojici nego jednome, jer imaju bolju plaću za svoj trud.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (25, 4, 10, 'Padne li jedan, drugi će ga podići; a teško jednomu! Ako padne, nema nikoga da ga podigne.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (25, 4, 11, 'Pa ako se i spava udvoje, toplije je; a kako će se samac zagrijati?');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (25, 4, 12, 'I ako tko udari na jednoga, dvojica će mu se oprijeti; i trostruko se uže ne kida brzo.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (25, 4, 13, 'Bolji je mladić siromašan a mudar nego kralj star a lud, koji više ne zna za savjet.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (25, 4, 14, 'Jer mladić može izići iz tamnice i postati kraljem, iako se rodio kao prosjak u svom kraljevstvu.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (25, 4, 15, 'Opazih kako svi koji žive i hode pod suncem pristaju uz mladića, uz nastupnika koji ga naslijedi.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (25, 4, 16, 'On stupa na čelo bezbrojnih podanika i kasniji se naraštaji ne mogahu zbog njega radovati. I to je zacijelo ispraznost i pusta tlapnja.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (25, 4, 17, 'Kad odlaziš u Božji dom, pazi na korake svoje. Priđi da mogneš čuti - žrtva je valjanija nego prinos luđaka, jer oni i ne znaju da čine zlo.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (25, 5, 1, 'Ne nagli ustima svojim i ne žuri se s riječima pred Bogom, jer je Bog na nebu, a ti si na zemlji; zato štedi svoje riječi.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (25, 5, 2, 'San dolazi od mnogih briga, a lud govor od mnoštva riječi.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (25, 5, 3, 'Kad zavjetuješ štogod Bogu, odmah to izvrši, jer njemu nisu mili bezumnici. Zato ispuni svaki svoj zavjet.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (25, 5, 4, 'Bolje je ne zavjetovati, nego zavjetovati a ne izvršiti zavjeta.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (25, 5, 5, 'Ne daj ustima svojim da te navode na grijeh i ne reci kasnije pred anđelom da je bilo nehotice. Zašto pružati Bogu priliku da se srdi na riječ tvoju i uništi djelo tvojih ruku?');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (25, 5, 6, 'Koliko sanja, toliko i ispraznosti; mnogo riječi - isprazna tlapnja. Zato boj se Boga.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (25, 5, 7, 'Ako vidiš gdje tlače siromaha i gaze pravo i pravicu u zemlji, ne čudi se tomu, jer nad visokim straži viši, a nad njim najviši.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (25, 5, 8, 'Korist zemlje je nada sve; i kralj ovisi o zemljištu.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (25, 5, 9, 'Tko novce ljubi, nikad ih dosta nema; tko bogatstvo ljubi, nikad mu dosta probitka. I to je ispraznost.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (25, 5, 10, 'Gdje je mnogo bogatstva, mnogo je i gotovana, pa kakva je korist od toga gospodaru, osim što ga očima gleda?');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (25, 5, 11, 'Sladak je dan radiši, jeo malo ili mnogo, dok bogatstvo ne da bogatašu zaspati.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (25, 5, 12, 'I vidjeh teško zlo pod suncem: skupljeno blago što je na propast svojemu vlasniku.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (25, 5, 13, 'Jer zlom nezgodom propadne takvo bogatstvo te sinu što mu se rodi ne ostane ništa.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (25, 5, 14, 'Gol je izašao iz utrobe majke svoje i tako će gol i otići kakav je i došao; ništa nema od svega svojeg truda da ponese.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (25, 5, 15, 'I to je teško zlo što tako odlazi kako je i došao; pa kakva mu je korist što se u vjetar mučio.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (25, 5, 16, 'Sve svoje dane živi u tami, nevolji, brizi, bolesti i srdžbi.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (25, 5, 17, 'Ovo, stoga, zaključujem: prava je sreća čovjeku jesti i piti i biti zadovoljan sa svim svojim trudom kojim se muči pod suncem za kratka vijeka koji mu je dao Bog, jer takva mu je sudbina dosuđena.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (25, 5, 18, 'Pa ako je čovjeku Bog dao bogatstvo i imanje da ih uživa i bude zadovoljan svojim djelom - i to je dar od Boga.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (25, 5, 19, 'Jer tada barem ne misli mnogo na dane svog života, kad mu Bog daje da mu se srce veseli.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (25, 6, 1, 'I vidjeh: ima još jedno zlo pod suncem i teško tišti ljude.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (25, 6, 2, 'Nekomu Bog udijeli bogatstvo i blago i počasti te ima sve što mu duša poželi, ali mu ne udijeli da to i uživa, nego uživa tuđinac. To je ispraznost i grdna nevolja.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (25, 6, 3, 'I velim: bolje je nedonošče od onoga koji bi rodio stotinu djece i živio mnogo godina, a sam se ne bi naužio dobra niti bi imao pogreba;');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (25, 6, 4, 'jer je nedonošče uzalud došlo i u tamu otišlo i ime mu je tamom pokriveno;');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (25, 6, 5, 'sunca čak ne vidje niti spozna - a spokojnije je od onoga.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (25, 6, 6, 'Pa kad bi takav živio i dvije tisuće godina, a svojeg dobra ne bi uživao, zar ne odlaze obojica jednako na isto mjesto?');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (25, 6, 7, 'Čovjek se trudi samo da bi jeo, a želudac njegov nikad da se nasiti.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (25, 6, 8, 'Jer po čemu je mudrac bolji od luđaka i što reći o siromahu koji se umije držati pred ljudima?');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (25, 6, 9, 'Bolje je očima vidjeti nego duhom lutati. I to je ispraznost i pusta tlapnja.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (25, 6, 10, 'Što je već bilo, ime ima; i zna se što je čovjek; i on se ne može parbiti s jačim od sebe.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (25, 6, 11, 'Što više riječi, to veća ispraznost svega, i koja je od toga korist čovjeku?');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (25, 6, 12, 'Tko zna što je dobro čovjeku u životu njegovu, za ono malo dana koje tako isprazno živi, koji mu prolaze kao sjena? Tko će kazati čovjeku što će biti poslije njega pod suncem?');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (25, 7, 1, 'Bolji je dobar glas nego skupocjeno ulje, i smrtni dan nego dan rođenja.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (25, 7, 2, 'Bolje je ići u kuću gdje je žalost nego u kuću gdje je gozba, jer ondje je kraj svakoga čovjeka, i tko je živ, nek\' primi k srcu!');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (25, 7, 3, 'Bolji je jad nego smijeh, jer pod žalosnim licem srce je radosno.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (25, 7, 4, 'Srce je mudrih ljudi u kući žalosti, a srce bezumnih u kući veselja.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (25, 7, 5, 'Bolje je poslušati ukor mudra čovjeka negoli slušati hvalospjev luđaka.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (25, 7, 6, 'Jer kao prasak trnja ispod kotla, takav je smijeh luđaka, i to je ispraznost.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (25, 7, 7, 'Jer smijeh od mudraca čini luđaka i veselje kvari srce.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (25, 7, 8, 'Bolji je svršetak stvari nego njezin početak i bolja je strpljivost od oholosti.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (25, 7, 9, 'Ne nagli u srdžbu, jer srdžba počiva u srcu luđaka.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (25, 7, 10, 'Ne pitaj zašto su negdašnja vremena bila bolja od ovih, jer to nije mudro pitanje.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (25, 7, 11, 'Mudrost je dragocjena baština i probitak onima na koje sunce sja.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (25, 7, 12, 'Jer kao što je novac zaštita, tako je i mudrost; a prednost je mudrosti u tome što izbavlja onoga tko je ima.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (25, 7, 13, 'Pogledaj djela Božja; tko može ispraviti što je on iskrivio?');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (25, 7, 14, 'U sretan dan uživaj sreću, a u zao dan razmišljaj: Bog je stvorio jedno kao i drugo - da čovjek ne otkrije ništa od svoje budućnosti.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (25, 7, 15, 'Svašta vidjeh u svojemu ništavnom životu: pravednik propada unatoč svojoj pravednosti, a bezbožnik i dalje živi unatoč svojoj bezbožnosti.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (25, 7, 16, 'Ne budi prepravedan i ne budi premudar; zašto da se uništavaš?');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (25, 7, 17, 'Ne budi preopak i ne budi lud; zašto bi umro prije vremena?');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (25, 7, 18, 'Dobro je da držiš jedno, ali ni drugo ne puštaj iz ruke, jer tko se boji Boga, izbavlja se od svega.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (25, 7, 19, 'Mudrost mudraca veću moć daje gradu nego deset mogućnika.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (25, 7, 20, 'Na zemlji nema pravednika koji, čineći dobro, ne bi nikad sagriješio.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (25, 7, 21, 'I još jedno: nemoj se obazirati na govorkanje; čut ćeš možda da te sluga tvoj proklinjao;');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (25, 7, 22, 'a zna tvoje srce kako si i ti često druge proklinjao.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (25, 7, 23, 'Sve sam to mudrošću iskušao. Mislio sam da sam mudar, ali mi je mudrost bila nedokučiva.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (25, 7, 24, 'Ono što jest, daleko je i duboko, tako duboko - tko da i pronađe?');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (25, 7, 25, 'I još jednom pokušah istražiti i shvatiti mudrost i smisao, da spoznam opačinu kao ludost, a ludost kao bezumlje.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (25, 7, 26, 'Otkrih da ima nešto gorče od smrti - žena, ona je zamka, srce joj je mreža, a ruke okovi; tko je Bogu drag, izmiče joj, a grešnik je njezin sužanj.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (25, 7, 27, 'Eto, to sam sve u svemu otkrio, veli Propovjednik.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (25, 7, 28, 'I još sam tražio, ali bez uspjeha. Nađoh čovjeka - jednog od tisuću, a žene ne nađoh među svima nijedne.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (25, 7, 29, 'Otkrih ovo: Bog stvori čovjeka jednostavnim, a on snuje nebrojene spletke.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (25, 8, 1, 'Tko je kao mudrac? Tko još umije tumačiti stvari? Mudrost čovjeku razvedruje lice i mijenja njegov namršteni lik.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (25, 8, 2, 'Zato velim: slušaj kraljevu zapovijed zbog Božje zakletve.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (25, 8, 3, 'Ne nagli da je prekršiš: ne budi tvrdoglav kad razlog nije dobar, jer on čini kako mu odgovara.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (25, 8, 4, 'Jer kraljeva je riječ najjača, i tko ga smije pitati: \"Što činiš?\"');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (25, 8, 5, 'Tko se drži zapovijedi, ne poznaje nevolju, i mudrac zna za vrijeme i sud.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (25, 8, 6, 'Jer postoji vrijeme i sud za sve, i čovjeka veoma tereti nedjelo njegovo');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (25, 8, 7, 'jer on ne zna što će biti; a tko mu može kazati kad će što biti?');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (25, 8, 8, 'Vjetar nitko ne može svladati, niti gospodariti nad danom smrtnim, niti ima odgode u ratu; niti opačina izbavlja onoga koji je čini.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (25, 8, 9, 'Sve ovo vidjeh pazeći na sve što se čini pod suncem, kad čovjek vlada nad čovjekom na njegovu nesreću.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (25, 8, 10, 'Dalje vidjeh kako opake nose na groblje, i ljudi iz svetog mjesta izlaze da ih slave zbog toga što su tako činili. I to je ispraznost.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (25, 8, 11, 'Kad nema brze osude za zlo djelo, ljudsko je srce sklono činiti zlo.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (25, 8, 12, 'I grešnik koji čini zlo i sto puta, dugo živi. Ja ipak znam da će biti sretni oni koji se boje Boga jer ga se boje.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (25, 8, 13, 'Ali opak čovjek neće biti sretan i neće produljivati svoje dane ni kao sjena jer se ne boji Boga.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (25, 8, 14, 'Ali je na zemlji ispraznost te pravednike stiže sudbina opakih, a opake sudbina pravednika. Velim: i to je ispraznost.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (25, 8, 15, 'Zato slavim veselje, jer nema čovjeku sreće pod suncem nego u jelu, pilu i nasladi. I to neka ga prati u njegovoj muci za života koji mu Bog dade pod suncem.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (25, 8, 16, 'Poslije svih napora da dokučim mudrost, pokušah spoznati što se radi na zemlji. Uistinu, čovjek ne nalazi spokojstva ni danju ni noću.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (25, 8, 17, 'Promatram cjelokupno djelo Božje: i odista - nitko ne može dokučiti ono što se zbiva pod suncem. Jer ma koliko se čovjek trudio da otkrije, nikad ne može otkriti. Pa ni mudrac to ne može otkriti, iako misli da zna.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (25, 9, 1, 'Razmišljah o svemu tome i shvatih kako su i pravednici i mudraci, sa djelima svojim, u Božjoj ruci; i čovjek ne razumije ni ljubavi ni mržnje, i njemu su obje ispraznost.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (25, 9, 2, 'Svima je ista kob, pravednomu kao i opakom, čistomu i nečistomu, onomu koji žrtvuje kao i onomu koji ne žrtvuje; jednako dobru kao i grešniku, onomu koji se zaklinje kao i onomu koji se boji zakletve.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (25, 9, 3, 'Najgore je od svega što biva pod suncem ovo: ista je kob svima, ljudsko je srce puno zla, ludost je u srcima ljudi dok žive, a potom se pridružuju mrtvima.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (25, 9, 4, 'Jer onaj tko je među živima, ima nade: i živ pas više vrijedi nego mrtav lav.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (25, 9, 5, 'Živi barem znaju da će umrijeti, a mrtvi ne znaju ništa niti imaju više nagrade, jer se zaboravlja i spomen na njih.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (25, 9, 6, 'Davno je nestalo i njihove ljubavi, i mržnje, i zavisti, i više nemaju udjela ni u čem što biva pod suncem.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (25, 9, 7, 'Zato s radošću jedi svoj kruh i vesela srca pij svoje vino, jer se Bogu već prije svidjelo tvoje djelo.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (25, 9, 8, 'U svako doba nosi haljine bijele i ulja nek\' ne ponestane na tvojoj glavi.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (25, 9, 9, 'Uživaj život sa ženom koju ljubiš u sve dane svojega ispraznog vijeka koji ti Bog daje pod suncem, jer to je tvoj udio u životu i u trudu kojim se trudiš pod suncem.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (25, 9, 10, 'I što god nakaniš učiniti, učini dok možeš, jer nema ni djela, ni umovanja, ni spoznaje, ni mudrosti u Podzemlju u koje ideš.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (25, 9, 11, 'Osim toga, vidjeh pod suncem: ne dobivaju trku hitri, ni boj hrabri; nema kruha za mudraca, ni bogatstva za razumne, ni milosti za učene, jer vrijeme i kob sve ih dostiže.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (25, 9, 12, 'Čovjek ne zna svoga časa: kao ribe ulovljene u podmukloj mreži, i kao ptice u zamku uhvaćene, tako se hvataju sinovi ljudski u vrijeme nevolje koja ih iznenada spopada.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (25, 9, 13, 'Još vidjeh pod suncem i ovu \"mudrost\" koja mi se učini velikom:');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (25, 9, 14, 'Bi jedan malen grad i u njem malo ljudi, a na nj udari velik kralj, opkoli ga i podiže oko njega velike opsadne tornjeve.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (25, 9, 15, 'Ali se u njemu nađe čovjek siromah mudar koji spasi grad svojom mudrošću, a poslije se nitko nije sjećao toga čovjeka.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (25, 9, 16, 'Ipak ja velim: bolja je mudrost nego jakost, ali se ne cijeni mudrost siromaha i ne slušaju njegove riječi.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (25, 9, 17, 'Blage se riječi mudraca bolje čuju nego vika zapovjednika nad luđacima.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (25, 9, 18, 'Mudrost više vrijedi nego bojno oružje, ali jedan jedini grešnik pokvari mnogo dobra.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (25, 10, 1, 'Uginula muha usmrdi mirisno ulje, a i malo ludosti jače je od mudrosti i časti.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (25, 10, 2, 'Mudrac kroči pravim putem, a luđak krivim.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (25, 10, 3, 'Dovoljno je da luđak pođe putem: kako razbora nema, svakomu pokazuje da je lud.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (25, 10, 4, 'Ako se na te digne vladaočev gnjev, ne ostavljaj svoga mjesta, jer blagost sprečava velike grijehe.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (25, 10, 5, 'Ima zlo što ga vidjeh pod suncem kao prestupak koji dolazi od vladaoca:');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (25, 10, 6, 'ludost se podiže na najviša mjesta, a veliki zauzimaju niske položaje.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (25, 10, 7, 'Vidjeh sluge na konjima, a knezove gdje idu pješice kao sluge.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (25, 10, 8, 'Tko jamu kopa, u nju pada; i tko ruši zid, ujeda ga zmija.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (25, 10, 9, 'Tko lomi kamenje, ono ga ranjava; tko cijepa drva, može nastradati.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (25, 10, 10, 'Kad zatupi željezo i oštrica mu nije nabrušena, tada treba više snage; a nagrada mudrosti je uspjeh.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (25, 10, 11, 'Ako zmija ujede prije čaranja, ništa onda opčaratelj ne koristi.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (25, 10, 12, 'Pune su miline riječi iz usta mudraca, a bezumnika upropašćuju njegove usne.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (25, 10, 13, 'On počinje svoje besjede ludošću i svršava ih potpunim bezumljem.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (25, 10, 14, 'Luđak previše govori: čovjek ne poznaje budućnost, i tko mu može kazati što će poslije njega biti?');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (25, 10, 15, 'Luđake mori njihov trud; tko ne zna puta, ne može u grad.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (25, 10, 16, 'Jao tebi, zemljo, kad ti je kralj premlad i knezovi se već ujutro goste.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (25, 10, 17, 'Blago tebi, zemljo, kad ti je kralj plemenit i knezovi ti u svoje vrijeme blaguju da se okrijepe, a ne da se opiju.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (25, 10, 18, 'S lijenosti se ugiblju grede, zbog nebrige prokišnjava kuća.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (25, 10, 19, 'Ali su gozbe radi zabave i vino uveseljava život, a novci pribavljaju sve.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (25, 10, 20, 'Ni u svojoj misli ne kuni kralja, ni u svojoj ložnici ne kuni bogataša, jer će ptice odnijeti glas i kleveta lako okrilati.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (25, 11, 1, 'Baci kruh svoj na vodu i naći ćeš ga poslije mnogo vremena.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (25, 11, 2, 'Podijeli sedmorici ili osmorici, jer ne znaš kakvo će zlo zadesiti zemlju.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (25, 11, 3, 'Kad se oblaci napune kišom, prosiplju je na zemlju, a padne li drvo na jug ili na sjever, svejedno: gdje padne, ondje i ostaje.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (25, 11, 4, 'Tko pazi na vjetar, ne sije, i tko gleda na oblake, ne žanje.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (25, 11, 5, 'Kao što ne znaš koji je put vjetru ni kako postaju kosti u utrobi trudne žene, tako ne znaš ni djela Boga koji sve tvori.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (25, 11, 6, 'Ujutro sij svoje sjeme, a navečer nek\' ti ruka ne počiva. Jer ne znaš da li će biti bolje ovo ili ono, ili će oboje biti jednako dobro.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (25, 11, 7, 'Ljupka je svjetlost i ugodno je očima vidjeti sunce.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (25, 11, 8, 'Ali ako čovjek živi i mnogo godina, neka se uvijek veseli, a neka se sjeti da će tamnih dana biti mnogo. Ispraznost je sve što će doći.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (25, 11, 9, 'Zato se raduj, mladiću, za svoje mladosti, i veseli se u danima svoga mladenaštva; idi putovima svoga srca i slijedi želje svojih očiju; ali znaj da će ti za sve to suditi Bog.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (25, 11, 10, 'Ukloni dakle jad iz svoga srca i udalji bol od svojega tijela. Ali je isprazna i mladost i doba tamnih kosa.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (25, 12, 1, 'I sjećaj se svoga Stvoritelja u danima svoje mladosti prije nego dođu zli dani i prispiju godine kad ćeš reći: \"Ne mile mi se.\"');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (25, 12, 2, 'Prije nego potamni sunce i svjetlost, mjesec i zvijezde, i vrate se oblaci iza kiše.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (25, 12, 3, 'U dan kad zadrhte čuvari kuće i pognu se junaci, i dosađuju se mlinarice jer ih je premalo, i potamne oni koji gledaju kroz prozore;');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (25, 12, 4, 'kad se zatvore ulična vrata, oslabi šum mlina, kad utihne pjev ptice i zamru zvuci pjesme.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (25, 12, 5, 'Kad je put uzbrdo muka i svaki izlazak prijetnja; a badem je u cvatu, i skakavac ne skače više, i koprov plot puca, jer čovjek ide u svoj vječni dom! A narikače već se kreću ulicama.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (25, 12, 6, 'Prije nego se prekine srebrna vrpca i zlatna se svjetiljka razbije i razlupa se vrč na izvoru i slomi točak na bunaru;');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (25, 12, 7, 'i vrati se prah u zemlju kao što je iz nje i došao, a duh se vrati Bogu koji ga je dao.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (25, 12, 8, 'Ispraznost nad ispraznostima, veli Propovjednik, sve je ispraznost.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (25, 12, 9, 'A osim toga što je sam Propovjednik bio mudar, on je i narod učio mudrosti te je odmjerio, ispitao i sastavio mnogo mudrih izreka.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (25, 12, 10, 'Ujedno se Propovjednik trudio pronaći prikladne riječi i izravno izraziti istinu.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (25, 12, 11, 'Besjede su mudrih ljudi kao ostani i kao pobodeni kolci: pastir se njima služi na dobro svojega stada.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (25, 12, 12, 'I na kraju, sine moj, znaj da je neizmjerno mnogo truda potrebno da se napiše knjiga i da mnogo učenje umara tijelo.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (25, 12, 13, 'Čujmo svemu završnu riječ: \"Boj se Boga, izvršuj njegove zapovijedi, jer - to je sav čovjek.\"');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (25, 12, 14, 'Jer sva će skrivena djela, bila dobra ili zla, Bog izvesti na sud.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 1, 1, 'Salomonova Pjesma nad pjesmama');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 1, 2, 'Poljubi me poljupcem usta svojih, ljubav je tvoja slađa od vina.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 1, 3, 'Miris najboljih mirodija, ulje razlito ime je tvoje, zato te ljube djevojke.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 1, 4, 'Povuci me za sobom, bježimo! Kralj me uveo u odaje svoje. Igrat ćemo se i radovati zbog tebe, slavit ćemo ljubav tvoju više nego vino. Pravo je da te ljube.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 1, 5, 'Crna sam ali lijepa, kćeri jeruzalemske, kao šatori kedarski, kao zavjese Salomonove.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 1, 6, 'Ne gledajte što sam garava, to me sunce opalilo. Sinovi majke moje rasrdili se na mene, postavili me da čuvam vinograde; a svog vinograda, koji je u meni, nisam čuvala.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 1, 7, 'Reci mi, ti koga ljubi duša moja, gdje paseš, gdje se u podne odmaraš, da ne lutam, tražeći te, oko stada tvojih drugova.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 1, 8, 'Ako ne znaš, o najljepša među ženama, izađi i slijedi tragove stada i pasi kozliće svoje oko pastirskih koliba.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 1, 9, 'Usporedio bih te s konjima pod kolima faraonovim, o prijateljice moja.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 1, 10, 'Lijepi su obrazi tvoji među naušnicama, vrat tvoj pod ogrlicama.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 1, 11, 'Učinit ćemo za tebe zlatne naušnice s privjescima srebrnim.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 1, 12, '- Dok se kralj odmara na svojim dušecima, (tada) nard moj miriše.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 1, 13, 'Dragi mi je moj stručak smirne što mi među grudima počiva.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 1, 14, 'Dragi mi je moj grozd ciprov u vinogradima engedskim.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 1, 15, '- Gle, kako si lijepa, prijateljice moja, gle, kako si lijepa, imaš oči kao golubica.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 1, 16, '- Gle, kako si lijep, dragi moj, gle, kako si mio. Zelenilo je postelja naša.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 1, 17, '- Grede kuća naših cedri su, a natkrovlje čempresi.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 2, 1, '- Ja sam cvijet šaronski, ljiljan u dolu.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 2, 2, '- Što je ljiljan među trnjem, to je prijateljica moja među djevojkama.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 2, 3, '- Što je jabuka među šumskim stablima, to je dragi moj među mladićima; bila sam željna hlada njezina i sjedoh, plodovi njeni slatki su grlu mome.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 2, 4, 'Uveo me u odaje vina i pokrio me zastavom ljubavi.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 2, 5, 'Okrijepite me kolačima, osvježite jabukama, jer sam bolna od ljubavi.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 2, 6, 'Njegova mi je lijeva ruka pod glavom, a desnom me grli.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 2, 7, '- Kćeri jeruzalemske, zaklinjem vas srnama i košutama poljskim, ne budite, ne budite ljubav moju dok sama ne bude htjela!');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 2, 8, 'Glas dragoga moga! Evo ga, dolazi, prelijeće brda, preskakuje brežuljke.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 2, 9, 'Dragi je moj kao srna, on je kao jelenče. Evo ga za našim zidom, gleda kroz prozore, zaviruje kroz rešetke.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 2, 10, 'Dragi moj podiže glas i govori mi: \"Ustani, dragano moja, ljepoto moja, i dođi,');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 2, 11, 'jer evo, zima je već minula, kiša je prošla i nestala.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 2, 12, 'Cvijeće se po zemlji ukazuje, vrijeme pjevanja dođe i glas se grličin čuje u našem kraju.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 2, 13, 'Smokva je izbacila prve plodove, vinograd, u cvatu, miriše. Ustani, dragano moja, ljepoto moja i dođi.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 2, 14, 'Golubice moja, u spiljama kamenim, u skrovištima vrletnim, daj da ti vidim lice i da ti čujem glas, jer glas je tvoj ugodan i lice je tvoje krasno.\"');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 2, 15, 'Pohvatajte lisice, male lisice što oštećuju vinograde, naše vinograde u cvatu.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 2, 16, 'Dragi moj pripada meni, a ja njemu, on pase među ljiljanima.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 2, 17, 'Prije nego dan izdahne i sjene se spuste, vrati se, dragi moj: budi lagan kao srna, kao lane na gori Beteru.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 3, 1, 'Po ležaju svome, u noćima, tražila sam onoga koga ljubi duša moja, tražila sam ga, ali ga nisam našla.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 3, 2, 'Ustat ću dakle i optrčati grad, po ulicama i trgovima tražit ću onoga koga ljubi duša moja: tražila sam ga, ali ga nisam našla.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 3, 3, 'Sretoše me čuvari koji grad obilaze: \"Vidjeste li onoga koga ljubi duša moja?\"');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 3, 4, 'Tek što pođoh od njih, nađoh onoga koga ljubi duša moja. Uhvatila sam ga i neću ga pustiti, dok ga ne uvedem u kuću majke svoje, u ložnicu roditeljke svoje.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 3, 5, 'Zaklinjem vas, kćeri jeruzalemske, srnama i košutama poljskim, ne budite, ne budite ljubav moju dok sama ne bude htjela!');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 3, 6, 'Što se to diže iz pustinje kao stup dima iz kada smirne i tamjana i svih prašaka mirodijskih?');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 3, 7, 'Gle, to je nosiljka Salomonova, oko nje šezdeset kršnih momaka između najkršnijih u Izraelu.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 3, 8, 'Svi su vični mačevima, za rat su izvježbani, svakome je sablja o boku zbog opasnosti noćnih.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 3, 9, 'Sebi je prijestolje načinio kralj Salomon od drveta libanskoga.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 3, 10, 'Stupove je napravio od srebra, naslon od zlata, sjedište od grimiza, unutra je sve ukrašeno ljubavlju kćeri jeruzalemskih.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 3, 11, 'Izađite, kćeri sionske, i vidite kralja Salomona pod dijademom kojim ga mati ovjenčala na dan svadbe njegove, na dan radosti njegova srca.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 4, 1, 'Kako si lijepa, prijateljice moja, kako si lijepa! Imaš oči kao golubica (kad gledaš) ispod koprene. Kosa ti je kao stado koza što izađoše na brdo Gilead.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 4, 2, 'Zubi su ti kao stado ovaca ostriženih kad s kupanja dolaze: idu dvije i dvije kao blizanke i nijedna nije osamljena.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 4, 3, 'Usne su tvoje kao trake od grimiza i riječi su tvoje dražesne, kao kriške mogranja tvoji su obrazi pod koprenom tvojom.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 4, 4, 'Vrat ti je kao kula Davidova, za obranu sagrađena: tisuću štitova visi na njoj, sve oklopi junački.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 4, 5, 'Tvoje su dvije dojke kao dva laneta, blizanca košutina, što pasu među ljiljanima.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 4, 6, 'Prije nego dan izdahne i sjene se spuste, poći ću na brdo smirne, na brežuljak tamjana.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 4, 7, 'Sva si lijepa, prijateljice moja, i nema mane na tebi.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 4, 8, 'Pođi sa mnom s Libana, nevjesto, pođi sa mnom s Libana. Siđi s vrha Amane, s vrha Senira i Hermona, iz lavljih spilja, s planina leopardskih.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 4, 9, 'Srce si mi ranila, sestro moja, nevjesto, srce si mi ranila jednim pogledom svojim, jednim samim biserom kolajne svoje.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 4, 10, 'Kako je slatka ljubav tvoja, sestro moja, nevjesto! Slađa je ljubav tvoja od vina, a miris ulja tvojih ugodniji od svih mirisa.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 4, 11, 'S usana tvojih, nevjesto, saće kapa, pod jezikom ti je med i mlijeko, a miris je haljina tvojih kao miris libanski.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 4, 12, 'Ti si vrt zatvoren, sestro moja, nevjesto, vrt zatvoren i zdenac zapečaćen.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 4, 13, 'Mladice su tvoje vrt mogranja pun biranih plodova:');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 4, 14, 'nard i šafran, mirisna trska i cimet, sa svim stabljikama tamjanovim, smirna i aloj s najboljim mirisima.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 4, 15, 'Zdenac je u mom vrtu, izvor žive vode koja teče s Libana.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 4, 16, 'Ustani, sjevernjače, duni, južni vjetre, duni nad vrtom mojim, neka poteku njegovi mirisi. Neka dragi moj dođe u vrt svoj, neka jede najbolje plodove u njemu.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 4, 17, '');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 5, 1, 'Došao sam u vrt svoj, o sestro moja, nevjesto, berem smirnu svoju i balzam svoj, jedem med svoj i saće svoje, pijem vino svoje i mlijeko svoje. Jedite, prijatelji, pijte i opijte se, mili moji!');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 5, 2, 'Ja spavam, ali srce moje bdi. Odjednom glas! Dragi moj mi pokuca: \"Otvori mi, sestro moja, prijateljice moja, golubice moja, savršena moja, glava mi je puna rose a kosa noćnih kapi.\"');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 5, 3, '\"Svukla sam odjeću svoju, kako da je odjenem? Noge sam oprala, kako da ih okaljam?\"');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 5, 4, 'Dragi moj promoli ruku kroz otvor, a sva mi utroba uzdrhta.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 5, 5, 'Ustadoh da otvorim dragome svome, a iz ruke mi prokapa smirna i poteče niz prste na ručku zavora.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 5, 6, 'Otvorih dragome svome, ali on se već bijaše udaljio i nestao. Ostala sam bez daha kad je otišao. Tražila sam ga, ali ga nisam našla, zvala sam, ali nije se odazvao.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 5, 7, 'Sretoše me čuvari koji grad obilaze, tukli su me, ranili i plašt mi uzeli čuvari zidina.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 5, 8, 'Zaklinjem vas, kćeri jeruzalemske, ako nađete dragoga moga, što ćete mu reći? Da sam bolna od ljubavi.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 5, 9, 'Što je tvoj dragi bolji od drugih, o najljepša među ženama, što je tvoj dragi bolji od drugih te nas toliko zaklinješ?');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 5, 10, 'Dragi je moj bijel i rumen, ističe se među tisućama.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 5, 11, 'Glava je njegova kao zlato, zlato čisto, uvojci kao palmove mladice, crne poput gavrana.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 5, 12, 'Oči su njegove kao golubi nad vodom potočnom; zubi mu kao mlijekom umiveni, u okvir poredani.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 5, 13, 'Obrazi su njegovi kao lijehe mirisnog bilja, kao cvijeće ugodno, usne su mu ljiljani iz kojih smirna teče.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 5, 14, 'Ruke su mu zlatno prstenje puno dragulja, prsa su njegova kao čista bjelokost pokrita safirima.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 5, 15, 'Noge su mu stupovi od mramora na zlatnom podnožju. Stas mu je kao Liban, vitak poput cedra.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 5, 16, 'Govor mu je sladak i sav je od ljupkosti. Takav je dragi moj, takav je prijatelj moj, o kćeri jeruzalemske.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 6, 1, 'Kamo je otišao dragi tvoj, o najljepša među ženama? Kuda je zamakao dragi tvoj, da ga tražimo s tobom?');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 6, 2, 'Dragi je moj sišao u svoj vrt k lijehama mirisnog bilja da pase po vrtovima i da bere ljiljane.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 6, 3, 'Ja pripadam dragome svome, dragi moj pripada meni, on pase među ljiljanima.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 6, 4, 'Lijepa si, prijateljice moja, kao Tirsa, krasna si kao Jeruzalem, strašna kao vojska pod zastavama.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 6, 5, 'Odvrati oči svoje od mene jer me zbunjuju. Kosa je tvoja kao stado koza koje silaze s Gileada.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 6, 6, 'Zubi su ti kao stado ovaca ostriženih kada s kupanja dolaze: idu dvije i dvije kao blizanke i nijedna nije osamljena.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 6, 7, 'Kao kriške mogranja tvoji su obrazi pod koprenom tvojom.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 6, 8, 'Ima šezdeset kraljica, osamdeset inoča, a djevojaka ni broja se ne zna.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 6, 9, 'Ali je samo jedna golubica moja, savršena moja, jedina u majke, izabrana u roditeljke svoje. Vidjele su je djevojke i nazvale je blaženom, a kraljice i inoče hvale su joj izrekle.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 6, 10, 'Tko je ova koja dolazi kao što zora sviće, lijepa kao mjesec, sjajna kao sunce, strašna kao vojska pod zastavama?');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 6, 11, 'Siđoh kroz nasade oraha da vidim mladice u dolinama, da pogledam pupaju li vinogradi, cvatu li mogranji.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 6, 12, 'Ne znam kako, tek želja moja pope me na kola naroda mog kneževskog.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 7, 1, 'Vrati se, Sulamko, vrati se, vrati se da te gledamo! Što ćete vidjeti na Sulamki koja pleše u dva zbora?');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 7, 2, 'Kako su krasni koraci tvoji u sandalama, kćeri kneževska! Pregibi su bokova tvojih kao grivne stvorene rukom umjetnika.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 7, 3, 'Pupak ti je kao okrugla čaša koja nikad nije bez pića. Trbuh ti je kao stog pšenice ograđen ljiljanima.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 7, 4, 'Dvije su dojke tvoje dva laneta, blizanca košutina.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 7, 5, 'Vrat je tvoj kao kula bjelokosna. Oči su tvoje kao ribnjaci u Hešbonu kod vrata batrabimskih. Nos ti je kao kula libanska što gleda prema Damasku.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 7, 6, 'Glava je tvoja kao brdo Karmel, a kosa na glavi kao purpur i kralj se zapleo u njene pletenice.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 7, 7, 'Kako si lijepa i kako si ljupka, o najdraža, među milinama!');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 7, 8, 'Stas je tvoj kao palma, grudi su tvoje grozdovi.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 7, 9, 'Rekoh: popet ću se na palmu da dohvatim vrške njezine, a grudi će tvoje biti kao grozdovi na lozi, miris daha tvoga kao jabuke.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 7, 10, 'Usta su tvoja kao najbolje vino. Koje odlazi ravno dragome mome kao što teče na usnama usnulih.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 7, 11, 'Ja pripadam dragome svome i on je željan mene.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 7, 12, 'Dođi, dragi moj, ići ćemo u polja, noćivat ćemo u selima.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 7, 13, 'Jutrom ćemo ići u vinograde da vidimo pupa li loza, zameće li se grožđe, jesu li procvali mogranji. Tamo ću ti dati ljubav svoju.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 7, 14, 'Mandragore šire miris, u našim kućama ima svakog voća, novoga i starog, za te sam ga čuvala, o najdraži moj!');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 8, 1, 'O, da si mi brat, da si sisao prsa majke moje, našla bih te vani, poljubila bih te i nitko me zato ne bi prezirao.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 8, 2, 'Povela bih te i uvela u kuću majke svoje koja me odgojila, pojila bih te najboljim vinom i sokom od mogranja.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 8, 3, 'Njegova mi je lijeva ruka pod glavom, a desnom me grli.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 8, 4, 'Zaklinjem vas, kćeri jeruzalemske, ne budite, ne budite ljubav mojuš dok sama ne bude htjela!');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 8, 5, 'Tko je ta što dolazi iz pustinje, naslonjena na dragoga svoga? Probudio sam te pod jabukom gdje te mati rodila, gdje te na svijet dala roditeljka tvoja.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 8, 6, 'Stavi me kao znak na srce, kao pečat na ruku svoju, jer ljubav je jaka kao smrt, a ljubomora tvrda kao grob. Žar je njezin žar vatre i plamena Jahvina.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 8, 7, 'Mnoge vode ne mogu ugasiti ljubav niti je rijeke potopiti. Da netko daje za ljubav sve što u kući ima, taj bi navukao prezir na sebe.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 8, 8, 'Imamo malu sestru koja još nema grudi, što ćemo činiti sa svojom sestrom kad bude riječ o njoj?');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 8, 9, 'Ako bude poput zida, sagradit ćemo na njemu krunište od srebra; ako bude poput vrata, utvrdit ćemo ih cedrovim daskama.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 8, 10, 'Ja sam zid i grudi su moje kule: tako postadoh u očima njegovim kao ona što nađe smirenje.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 8, 11, 'Salomon ima vinograd u Baal Hamonu, dao ga je čuvarima i svaki mora donijeti za urod tisuću srebrnjaka.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 8, 12, 'Moj vinograd je preda mnom: tebi, Salomone, tisuća, a dvjesta onima što čuvaju plodove.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 8, 13, 'O ti, koja boraviš u vrtovima, drugovi slušaju glas tvoj, daj da ga i ja čujem!');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 8, 14, 'Pohitaj, mili moj, budi kao srna i kao jelenče na gorama mirisnim!');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (27, 1, 1, 'Ljubite pravednost, vi suci zemaljski, pravednim mislima mislite o Gospodinu i tražite ga u jednostavnosti srca.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (27, 1, 2, 'Jer njega nalaze koji ga ne iskušavaju i otkriva se onima koji mu ne uskraćuju svoju vjeru.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (27, 1, 3, 'A podmukle misli otuđuju od Boga i iskušavana Svemoć posramljuje bezumnike.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (27, 1, 4, 'Jer mudrost ne ulazi u dušu opaku i ne nastanjuje se u tijelu grijehu podložnu.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (27, 1, 5, 'Jer sveti duh pouke bježi od prijevare i uklanja se od misli bezumnih i uzmiče kad se nepravda pojavi.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (27, 1, 6, 'Jer mudrost je duh čovjekoljubiv, ali hulniku neće oprostiti njegovih riječi, jer Bog proniče bubrege njegove, istinski mu srce nadzire i sluša njegove riječi.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (27, 1, 7, 'Doista duh Gospodnji ispunja svemir, i on, koji drži sve, zna i sve što se govori.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (27, 1, 8, 'Zato ne ostaje skriven tko nepravedno govori niti će ga mimoići osvetnička pravda.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (27, 1, 9, 'Jer se namisli bezbožnikove točno ispituju i glas riječi njegovih ide sve do Gospoda da se kazne bezakonja njegova.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (27, 1, 10, 'Jer postoji uho ljubomorno koje čuje sve i ne izmiče mu ni glasak najtišeg gunđanja.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (27, 1, 11, 'Čuvajte se isprazna gunđanja i čuvajte jezik od opakih riječi, jer i najtajnija riječ nije bez učinka, a lažljiva usta ubijaju dušu.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (27, 1, 12, 'Ne trčite za smrću stranputicama života svojeg i ne navlačite na se propast djelima ruku svojih.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (27, 1, 13, 'Jer Bog nije stvorio smrt niti se raduje propasti živih.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (27, 1, 14, 'Već je sve stvorio da sve opstane, i spasonosni su stvorovi svijeta, i u njima nema smrtonosna otrova. I Podzemlje ne vlada zemljom,');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (27, 1, 15, 'jer pravednost je besmrtna.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (27, 1, 16, 'Ali bezbožnici dozivaju smrt i rukama i riječju i za njom ginu smatrajući je prijateljem i s njome ugovor sklapaju, dostojni da joj pripadaju.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (27, 2, 1, 'Jer oni krivo misle i ovako mudruju: \"Kratkovijek je i tužan život naš i nema lijeka kad čovjeku dođe kraj i još nije poznat tko bi se iz Podzemlja izbavio.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (27, 2, 2, 'Mi smo djeca pukog slučaja i kasnije ćemo biti kao da nikad nismo ni bili, jer samo je dim ono čime dišu naše nosnice, a misao je tek iskra od kucaja našega srca.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (27, 2, 3, 'Kad se ona utrne, pretvorit će se tijelo u pepeo, a duh će se rasplinuti kao lagan zrak.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (27, 2, 4, 'Ime će nam se s vremenom zaboraviti i nitko se neće sjećati djela naših; i život će nam proći kao pramenje oblaka i nestat će ga kao magle što je gone zrake sunčane i pritiskuje žega njihova.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (27, 2, 5, 'Jer život naš kao sjena odmiče, iz naše smrti nema povratka, zapečaćeno je i nitko se ne vraća.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (27, 2, 6, 'Zato hodite ovamo! Uživajmo dobra sadašnja, koristimo se stvorovima sa žarom mladosti.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (27, 2, 7, 'Nauživajmo se odabranih vina i mirisa i neka nas ne mimoiđe ni jedan cvijet proljetni,');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (27, 2, 8, 'okrunimo se ružama prije no što uvenu.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (27, 2, 9, 'Neka svaki od nas sudjeluje u pijanki našoj, ostavimo svuda znake našeg veseljenja: to je naš dio i to je naša baština.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (27, 2, 10, 'Potlačimo ubogoga pravednika, ne štedimo udovice, ne poštujmo starca ni sjedina od mnogih godina.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (27, 2, 11, 'Nek\' naša snaga bude zakon pravde, jer ono što je slabo nije ni za što.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (27, 2, 12, 'Postavimo zasjedu pravedniku jer nam smeta i protivi se našem ponašanju, predbacuje nam prijestupe protiv Zakona i spočitava kako izdadosmo odgoj svoj.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (27, 2, 13, 'On se hvasta posjedom spoznaje o Bogu i naziva se sinom Gospodnjim.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (27, 2, 14, 'On je ukor utjelovljeni našim mislima, sama njegova pojava tišti našu dušu.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (27, 2, 15, 'Život njegov nije kao u ostalih i njegovo je ponašanje nastrano.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (27, 2, 16, 'Smatra nas patvorinom i uklanja se od putova naših kao od nečisti. On svršetak pravednika proglašava sretnim i hvali se da mu je Bog otac.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (27, 2, 17, 'Pogledajmo jesu li istinite riječi njegove, istražimo kakav će biti njegov svršetak.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (27, 2, 18, 'Jer ako je pravednik Božji sin, On će se za nj zauzeti i izbavit će ga iz ruku neprijateljskih.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (27, 2, 19, 'Zato ga iskušajmo porugom i mukom da istražimo blagost njegovu i da prosudimo strpljivost njegovu.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (27, 2, 20, 'Osudimo ga na smrt sramotnu, jer će mu, kako veli, doći izbavljenje.\"');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (27, 2, 21, 'Tako oni misle, ali se varaju, jer ih zloća njihova zasljepljuje.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (27, 2, 22, 'Oni ne znaju tajna Božjih, ne očekuju nagradu za svetost, ne vjeruju u naknadu čistim dušama.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (27, 2, 23, 'Jer je Bog stvorio čovjeka za neraspadljivost i učinio ga na sliku svoje besmrtnosti.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (27, 2, 24, 'A đavlovom je zavišću došla smrt u svijet i nju će iskusiti oni koji njemu pripadaju.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (27, 3, 1, 'A duše su pravednika u ruci Božjoj i njih se ne dotiče muka nikakva.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (27, 3, 2, 'Očima se bezbožničkim čini da oni umiru i njihov odlazak s ovog svijeta kao nesreća;');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (27, 3, 3, 'i to što nas napuštaju kao propast, ali oni su u miru.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (27, 3, 4, 'Ako su, u očima ljudskim, bili kažnjeni, nada im je puna besmrtnosti.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (27, 3, 5, 'Za malo muke zadobili su dobra velika jer Bog ih je stavio na kušnju i našao da su ga dostojni.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (27, 3, 6, 'Iskušao ih je kao zlato u taljiku i primio ih kao žrtvu paljenicu.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (27, 3, 7, 'Zato će se u vrijeme posjeta njegova zasjati te će vrcati kao iskre u strnjici.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (27, 3, 8, 'Sudit će pucima i vladati narodima i Gospodin će kraljevat nad njima uvijeke.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (27, 3, 9, 'Koji se u nj ufaju spoznat će istinu, i koji su vjerni bit će u ljubavi s njim, jer izabranici njegovi stječu milost i milosrđe.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (27, 3, 10, 'A bezbožnici će zbog svojih misli biti primjereno kažnjeni jer su prezreli pravednike i otpali od Gospodina.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (27, 3, 11, 'Teško onima koji preziru mudrost i stegu! Isprazna je nada njihova, napori uzaludni i poslovi bez probitka.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (27, 3, 12, 'Žene su im bezumne, djeca opaka i proklet njihov rod!');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (27, 3, 13, 'Blago nerotkinji, ali bez ljage, kojoj ložnica ne poznaje grijeha; plodnost će se njezina pokazati na istrazi duša.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (27, 3, 14, 'Blago i uškopljeniku koji ne počini zločina niti smišlja zla protiv Gospoda; jer će za vjernost dobiti milost izabranu i baštinu najljupkiju u Domu Gospodnjem.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (27, 3, 15, 'Jer plemenit trud donosi plod pun slave i neraspadljiv je korijen razbora.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (27, 3, 16, 'A djeca preljubnička neće doći do savršenstva i rod nezakonite ložnice propada.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (27, 3, 17, 'Pa ako i žive dugo, nisu ni za što i na koncu im je starost nečasna.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (27, 3, 18, 'Umru li opet rano, nade nemaju niti utjehe na sudnji dan:');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (27, 3, 19, 'jer okrutna je kob grešna roda.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (27, 4, 1, 'Bolje i ne imati djece a posjedovati krepost, jer je spomen njezin besmrtan, i Bog i ljudi je cijene.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (27, 4, 2, 'Kad je nazočna, oponašaju je, kad je odsutna, priželjkuju je; okrunjena vječno slavlje slavi, jer je pobijedila u borbama bez ljage.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (27, 4, 3, 'A mnogobrojno potomstvo bezbožnika nije ni za što; izdanci se nečisti duboko ne korijene i nemaju čvrsta temelja.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (27, 4, 4, 'Jer ako se načas i razgranaju, slabo ukorijenjeni, na vjetru se zaljuljaju, iščupa ih sila vihora,');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (27, 4, 5, 'i grane što tek su izbile polomi i plod im je beskoristan, nezreo za jelo i nije ni za što.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (27, 4, 6, 'Jer djeca rođena iz nezakonita spavanja svjedoče na sudu o zlu roditelja.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (27, 4, 7, 'A pravednik, ako i umre prijevremeno, naći će mir.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (27, 4, 8, 'Jer duljina dana ne čini starost časnom niti se ona mjeri brojem godina.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (27, 4, 9, 'Već razboritost - to su sjedine ljudske, i krepostan život - zrela starost.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (27, 4, 10, 'I jer je ugađao Bogu, On ga je zavolio, i jer je živio među grešnicima, On ga je uzeo k sebi.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (27, 4, 11, 'Uzdignut je da zloća ne bi izopačila njegov razbor ili da mu himba ne zavede duše.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (27, 4, 12, 'Jer blještavilo opačine zasjenjuje dobro i vihor požude izopačuje dobru dušu.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (27, 4, 13, 'Stekavši savršenstvo u malo vremena, dugo je živio;');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (27, 4, 14, 'i jer mu je duša bila draga Gospodu, On ga je hitro izbavio od zloće oko njega. Svjetina sve to vidi, ali ne shvaća; njima i ne pada na um');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (27, 4, 15, 'da milost i milosrđe pripadaju izabranicima Gospodnjim i zaštita njegovim svetima.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (27, 4, 16, 'A pravednik koji umire osuđuje žive bezbožnike i prijevremeno dokončana mladost produženu starost opakih.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (27, 4, 17, 'Svjetina vidi kraj mudračev, ali ne shvaća što je Gospod s njim naumio ili zašto ga je uzeo u zaštitu.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (27, 4, 18, 'Oni gledaju i preziru, ali će se i njima Gospod podsmijevati.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (27, 4, 19, 'Ubrzo će oni biti trupla prezrena i ruglo među mrtvima dovijeka, jer će ih Gospod strmoglaviti bez glasa, otrgnut će ih od temelja njihova, sasvim ih opustošiti; na mukama će oni biti i spomen će im propasti.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (27, 4, 20, 'Puni straha doći će na obračun grijeha, i bezakonja njihova u lice će ih optuživati.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (27, 5, 1, 'A pravednik će se vedro sučeliti s onima koji ga tlačiše i koji prezirahu patnje njegove.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (27, 5, 2, 'Kad ga ugledaju, uzdrhtat će od silna straha, zapanjeni njegovim iznenadnim spasenjem.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (27, 5, 3, 'Govorit će među sobom, puni kajanja, i uzdišući u tjeskobi svoje duše:');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (27, 5, 4, '\"To je onaj komu smo se nekoć podsmijevali i koji nam je bio za porugu. Mi, budale, smatrasmo njegov život ludošću i svršetak njegov nečasnim.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (27, 5, 5, 'Kako li se ubrojio među sinove Božje i dobio udio svoj među svecima?');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (27, 5, 6, 'Mi, odista, zalutasmo s puta istine i svjetlost pravde nije nam svijetlila niti nam je sunce ogranulo.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (27, 5, 7, 'Bazali smo stazama propasti i prohodili bespuća pustinje, ali puta Gospodnjega nismo spoznali.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (27, 5, 8, 'Što nam je koristila oholost? Što nam je vrijedilo bogatstvo i hvastanje?');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (27, 5, 9, 'Sve je prošlo kao sjena i kao kratkotrajan glas.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (27, 5, 10, 'I kao lađa koja siječe uzburkano more i traga joj nema kuda prođe niti brazde hrptici njezinoj u valovima;');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (27, 5, 11, 'ili kao ptica što zrakom proleti i ne ostavi traga prolazu svojem: šiba lagani uzduh udarcima svojih pera i rasijeca ga uza snažan fijuk i prodire zamasima svojih krila, a poslije nema više nikakva traga njezinu letu;');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (27, 5, 12, 'ili kao strijela odapeta na svoj cilj: probijeni se zrak odmah sklapa i ne raspoznaje se staza njezina -');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (27, 5, 13, 'tako i mi: jedva što smo na svijet došli, a već nestadosmo, ni traga kreposti pokazati ne mogosmo: u zloći se svojoj sasvim istrošismo.\"');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (27, 5, 14, 'I doista, nada je bezbožnikova kao pljeva što je vjetar raznosi i kao sitna pjena što je vihor razgoni; ona nestaje kao dim na vjetru i prolazi kao spomen na jednodnevna gosta.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (27, 5, 15, 'A pravednici žive dovijeka, i u Gospodu je nagrada njihova i briga za njih u Svevišnjeg.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (27, 5, 16, 'Zato će iz ruku Gospodnjih primiti kraljevsku krunu slave i vijenac ljepote; svojom će ih desnicom Gospod zakriliti i svojom ih mišicom zaštititi.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (27, 5, 17, 'Latit će se svog žara ljubomornog kao oružja i naoružat će sve stvorenje da kazni svoje neprijatelje;');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (27, 5, 18, 'kao oklop obući će pravednost, a kao šljem stavit će sud bez himbe;');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (27, 5, 19, 'uzet će nepobjedivu svetost kao štit,');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (27, 5, 20, 'a kao mač naoštrit će žestok gnjev i sav će svemir poći s njim u boj protiv bezumnika.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (27, 5, 21, 'Tad će poletjet\' dobro naperene strijele: munje iz oblaka padat će na cilj kao iz nategnuta luka;');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (27, 5, 22, 'iz bojne sprave izlijetat će zrna grÓada srdžbom nabijena. Na njih će voda morska bjesnjeti, i rijeke će ih potapati bez milosti.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (27, 5, 23, 'Dah Svemoći zapuhat će protiv njih, izvijat će ih poput vihora. I tako će svu zemlju opustošiti bezakonje i opačina će prevrnuti prijestolja vladalačka.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (27, 6, 1, 'Čujte, dakle, kraljevi, i urazumite se! Poučite se, vladari zemalja dalekih!');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (27, 6, 2, 'Poslušajte, vi koji upravljate mnoštvima i koji se hvastate silom svojih naroda!');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (27, 6, 3, 'Gospod je onaj koji vam je moć podario, i vladavina je od Svevišnjeg, koji će ispitivati djela vaša i vaše nakane istražiti.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (27, 6, 4, 'Iako ste upravljači njegova kraljevstva, ne vladaste pravedno, niti se držaste zakona, niti služiste nakani Božjoj.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (27, 6, 5, 'Gospod će vas napasti brzo i užasno, jer za velikaše je nemilosrdna kazna;');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (27, 6, 6, 'maleni su oproštenja dostojni, a moćnici će biti moćno kažnjeni.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (27, 6, 7, 'Jer Gospod Svevladar ne uzmiče ni pred kim niti se plaši kakve veličine: tÓa on je stvorio i mala i velika i jednako se brine za sve,');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (27, 6, 8, 'a istraga oštra očekuje moćnike.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (27, 6, 9, 'Vama su dakle, vladari upravljene riječi moje da se naučite mudrosti i ne griješite.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (27, 6, 10, 'Jer oni koji sveto čuvaju svetinje sami se posvećuju, i koji su u tom poučeni nalaze obranu.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (27, 6, 11, 'Žudite stoga za riječima mojim, čeznite za njima: one će vas poučiti.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (27, 6, 12, 'Mudrost je sjajna i ona ne tamni: lako je vide koji je ljube i nalaze je oni koji je traže.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (27, 6, 13, 'Ona pretječe sve koji je žude i prva im se pokazuje.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (27, 6, 14, 'Tko zorom rani njoj taj se ne muči: nalazi je gdje sjedi kraj vrata njegovih.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (27, 6, 15, 'Jer je i sama misao na nju mudrost savršena, a tko radi nje bdi, brzo je bezbrižan.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (27, 6, 16, 'Ona hodi naokolo i traži sebi dostojne; i pojavljuje im se dobrohotno na stazama i u susret im dolazi u svakoj misli.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (27, 6, 17, 'Jer njezin početak najistinskiji želja je za poukom, u težnji za poukom ljubav je prema njoj;');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (27, 6, 18, 'voljeti je znači držati njene zakone, a posluh njezinim zakonima pouzdana je besmrtnost,');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (27, 6, 19, 'a besmrtnost vodi u blizinu Božju;');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (27, 6, 20, 'tako žudnja za mudrošću dovodi do kraljevstva.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (27, 6, 21, 'Ako se, vi vladari nad pucima, radujete prijestoljima i žezlima, tad mudrost štujte da dovijeka kraljujete.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (27, 6, 22, 'A sad ću vam priopćiti što je mudrost i kako je postala. Neću vam skriti tajne, nego ću je pratiti od početka i na vidjelo iznijeti znanje njezino, i neću istinu mimoići.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (27, 6, 23, 'Neću poći ni s pogubnom Zavišću: ona ništa zajedničko nema s Mudrošću.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (27, 6, 24, 'Mnoštvo je mudraca svijetu spasenje i kralj uman blagostanje narodu.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (27, 6, 25, 'Zato crpite nauku iz riječi mojih i bit će vam na probitak.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (27, 7, 1, 'I ja sam smrtnik, kao i svi ostali, i potomak prvog bića od zemlje načinjena i oblikovan kao tijelo u utrobi majčinoj,');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (27, 7, 2, 'u deset mjeseci, stisnut u krvi, iz sjemena muževljeva i slasti družice u spavanju.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (27, 7, 3, 'I ja sam, došavši na svijet, udahnuo zajednički zrak i pao na zemlju koja nas sve nosi, i plač mi je bio prvi glas kao i svima ostalima.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (27, 7, 4, 'U pelenama bijah odgajan i u brigama,');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (27, 7, 5, 'jer nijedan kralj nije drukčije postao niti na svijet došao.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (27, 7, 6, 'Jer za sve postoji jedan ulazak u život, a tako i jedan izlazak.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (27, 7, 7, 'Zato se pomolih i razbor dobih; zavapih i primih duh mudrosti.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (27, 7, 8, 'Zavoljeh je više nego žezla i prijestolja i ništa ne cijenih bogatstvo u usporedbi s njom.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (27, 7, 9, 'Nisam je htio uspoređivati ni sa draguljima, jer je sve zlato pred njom kao malo pijeska, a srebro je prema njoj kao blato.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (27, 7, 10, 'Ljubio sam je više od zdravlja i ljepote i zavolio više od svjetlosti, jer njezin sjaj bez prestanka svijetli.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (27, 7, 11, 'A s njome su mi došla sva dobra i od ruku njezinih blago nebrojeno.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (27, 7, 12, 'I svemu sam se tome radovao, jer mudrost sve donosi; još nisam znao da je ona roditeljka svega toga.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (27, 7, 13, 'I ono što naučih bez primisli, to bez zavisti predajem, bogatstva njezina ne skrivam.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (27, 7, 14, 'Ona je neiscrpljiva riznica ljudima, i koji se njome služe postaju prijatelji Božji, preporučeni darovima njezina nauka.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (27, 7, 15, 'Zato neka mi dade Bog govoriti kako me svjetova i misliti misli dostojne darova njegovih, jer on je vođa mudrosti i upravlja mudracima.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (27, 7, 16, 'U njegovoj smo ruci mi i riječi naše, sa svim našim razborom i umijećem.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (27, 7, 17, 'On mi je podario istinsku znanost o svemu što jest, naučio me sustavu svijeta i svojstvima prapočela;');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (27, 7, 18, 'početku, svršetku i sredini vremena, izmjeni suncovrata i slijedu godišnjih doba,');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (27, 7, 19, 'tijeku godina i položaju zvijezda;');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (27, 7, 20, 'naravi životinja i nagonima divljih zvijeri, moći duhova i mislima ljudskim, različnosti biljaka i ljekovitosti korijenja.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (27, 7, 21, 'I spoznadoh sve što god je tajno i javno, jer me poučavaše mudrost, umjetnica u svemu.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (27, 7, 22, 'Jer u nje je duh razborit, svet, jedinstven, mnogostran, tanan, okretan, pronicav, neoskvrnjen, jasan, nepristran, dobrohotan, oštar,');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (27, 7, 23, 'nezaprečiv, dobrotvoran, čovjekoljubiv, postojan, pouzdan, bezbrižan, svemoćan, svenadzoran, što prodire kroza sve duše, mudre, čiste i najtanje.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (27, 7, 24, 'Jer je mudrost gibljivija od svakog gibanja, ona proniče i prožima sve svojom čistoćom.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (27, 7, 25, 'Jer je ona dah sile Božje i čist odvir slave Svemogućeg; zato je ništa nećisto ne može oskvrnuti.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (27, 7, 26, 'Ona je odsjev vječne svjetlosti i zrcalo čisto djela Božjeg, i slika dobrote njegove.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (27, 7, 27, 'Jedna je, a može sve, i, ostajući u sebi, sve obnavlja. Ona prelazi od naraštaja do naraštaja u duše svete i čini od njih Božje prijatelje i proroke.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (27, 7, 28, 'Jer Bog ne ljubi nikoga osim onoga tko se druži s mudrošću.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (27, 7, 29, 'Ona je od sunca sjajnija i nad sve zviježđe uzvišena; uspoređena sa svjetlošću, ona je nadmašuje:');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (27, 7, 30, 'jer svjetlost ustupa mjesto noći, dok zloća nema moći protiv mudrosti.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (27, 8, 1, 'Njena se snaga prostire s jednoga kraja svijeta na drugi i blagotvorno upravlja svemirom.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (27, 8, 2, 'Nju zavoljeh i za njom čeznuh od svoje mladosti; i nastojah da mi bude zaručnica i zaljubih se u ljepotu njezinu.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (27, 8, 3, 'Njezina životna prisnost s Bogom podaruje sjaj njezinu plemenitom podrijetlu jer je ljubi gospodar svemira.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (27, 8, 4, 'Ona je povjerenica znanja Božjeg, izbiračica djela njegovih.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (27, 8, 5, 'Ako je bogatstvo blago poželjno u ovom životu, što je onda bogatije od mudrosti koja sve stvara?');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (27, 8, 6, 'Ako opet razum stvara, tko je na svijetu od nje veći umjetnik?');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (27, 8, 7, 'Ako li pak tko ljubi pravednost, pa, kreposti su plodovi njezinih napora: ona poučava umjerenosti i razboritosti, pravednosti i hrabrosti, od kojih u životu nema ništa korisnije ljudima.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (27, 8, 8, 'Ako li tko čezne za većim znanjem, ona poznaje prošlost i proriče budućnost, vična je izrekama i umije odgonetati zagonetke. Ona znade unaprijed znake i čudesa i slijed razdoblja i vremena.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (27, 8, 9, 'Zato odlučih dovesti je kao družicu životnu, znajući da će mi biti savjetnica u sreći i tješiteljica u brigama i tuzi.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (27, 8, 10, 'Po njoj ću steći slavu u mnoštvu narodnom, još kao mladić čast pred starcima.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (27, 8, 11, 'Na sudu će se vidjeti kako sam oštrouman i divit će mi se velikaši kad stanem pred njih.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (27, 8, 12, 'Čekat će me kad budem šutio i slušat će me kad prozborim; ako se odulji govor moj, držat će ruku na svojim ustima.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (27, 8, 13, 'Po njoj ću zadobiti besmrtnost i ostavit ću vječni spomen rodu budućem.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (27, 8, 14, 'Vladat ću pucima i narodi će mi biti podložni.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (27, 8, 15, 'Pobojat će se strašni silnici kad čuju za me, s narodom ću svojim biti dobrostiv i hrabar u ratu.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (27, 8, 16, 'Kada se vratim kući, tad ću počinuti kraj nje, jer u drugovanju s njome nema gorčine i nema bola u zajedništvu s njom, već samo užitak i radost.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (27, 8, 17, 'Kad sam tako sve u sebi razmislio i srcem svojim razabrao da je besmrtnost u srodstvu s mudrošću');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (27, 8, 18, 'i da je u ljubavi njezinoj radost čista i u djelima ruku njezinih blago neiscrpno, i razboritost u izmjeni misli s njome i slava u zajedništvu riječi njezinih, stao sam tad okolo hoditi i nastojati kako bih je zadobio.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (27, 8, 19, 'Ja bijah mladić sretne naravi i imao sam dobru dušu,');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (27, 8, 20, 'ili bolje: jer bijah dobar, ušao sam u tijelo bez ljage.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (27, 8, 21, 'A znajući da neću mudrost zadobiti ako ne da Bog - a razboritost je već bila znati čiji je ona dar - pristupih Gospodu i pomolih se i svim srcem svojim rekoh:');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (27, 9, 1, 'Bože otaca naših i Gospode milosrđa, ti koji si riječju svojom stvorio svemir');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (27, 9, 2, 'i koji si sazdao čovjeka mudrošću svojom da vlada nad stvorovima tvojim');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (27, 9, 3, 'i da svijetom upravlja u svetosti i pravednosti i da sud sudi dušom pravičnom:');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (27, 9, 4, 'daj mi mudrost, prisjednicu svoga prijestolja i ne odbaci me između djece svoje.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (27, 9, 5, 'Jer sam sluga tvoj, sin sluškinje tvoje, čovjek slab i malovjek, nesposoban shvatiti pravdu i zakone.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (27, 9, 6, 'Jer ako bi tko od sinova ljudskih bio i savršen, ali bez mudrosti koja od tebe dolazi, opet ne bi ničemu vrijedio.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (27, 9, 7, 'Ti si me izabrao za kralja svome narodu i za suca sinovima i kćerima svojim.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (27, 9, 8, 'Odredio si mi da sagradim Hram na Svetoj gori tvojoj i žrtvenik u gradu boravišta tvojeg, u liku svetoga Šatora koji si odiskona bio spremio.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (27, 9, 9, 'S tobom je mudrost koja zna djela tvoja, koja je bila nazočna kad si stvarao svijet; ona zna što je milo tvojim očima i što je pravo po tvojim zapovijedima.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (27, 9, 10, 'Pošlji je s nebesa svetih i otpravi je od svoga slavnog prijestolja, da uza me bude i potrudi se sa mnom i da spoznam što je tebi milo.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (27, 9, 11, 'Jer ona sve zna i razumije, ona će me razborito voditi u pothvatima mojim i štititi svojom moći.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (27, 9, 12, 'Tad će ti djela moja biti ugodna, i ja ću pravedno upravljati pukom tvojim i bit ću dostojan prijestolja oca svoga.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (27, 9, 13, 'Jer tko može spoznati Božju namisao i tko će se domisliti što hoće Gospod?');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (27, 9, 14, 'Plašljive su misli smrtnika i nestalne su naše namisli.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (27, 9, 15, 'Jer propadljivo tijelo tlači dušu i ovaj zemljani šator pritiskuje um bremenit mislima.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (27, 9, 16, 'Mi jedva nagađamo što je na zemlji i s mukom spoznajemo i ono što je u našim rukama: a što je na nebu, tko će istražiti?');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (27, 9, 17, 'Tko bi doznao tvoju volju da ti nisi dao mudrosti i da s visine nisi poslao Duha svoga svetoga.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (27, 9, 18, 'Samo tako su se poravnale staze ljudima na zemlji i samo su tako naučili ljudi što je tebi milo i spasili se tvojom mudrošću.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (27, 9, 19, '');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (27, 10, 1, 'Ona je štitila prvooblikovanog oca svijeta, koji je stvoren sam, istrgla ga iz grijeha njegova');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (27, 10, 2, 'i dala mu jakost da vlada svemirom.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (27, 10, 3, 'A kad se u jarosti svojoj grešnik odmetnu od nje, poginu u mržnji svojoj bratoubilačkoj.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (27, 10, 4, 'I kad je zemlju zbog njega potop stigao, opet ju je mudrost spasila brodeći s pravednikom na krhkom drvetu.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (27, 10, 5, 'I kada se, složni u opačini svojoj, narodi bijahu pomutili, ona je našla pravednika i sačuvala ga Bogu nezazorna i uzdržala jačim od ljubavi prema djetetu.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (27, 10, 6, 'Kad su bezbožnici izgibali, ona je izbavila pravednika koji je bježao od ognja što je s neba pao na pet gradova.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (27, 10, 7, 'O opačini njihovoj još svjedoči pustoš puna dima i bilje kojemu plod nikad ne sazrijeva i stup od soli što stoji kao spomenik duši nevjernoj.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (27, 10, 8, 'I jer nisu slijedili puta mudrosti, izgubili su spoznaju o dobru i još ostavili svijetu spomenik svoje ludosti da se ne mogahu sakriti zlodjela njihova.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (27, 10, 9, 'A mudrost je vjernike svoje spasila od nevolje.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (27, 10, 10, 'Kad je pravednik bježao ispred jarosti bratove, ona ga je vodila pravim stazama; pokazala mu Božje kraljevstvo i podarila mu znanje o svetinjama; uspjehom okrunila napore njegove i umnožila plodove truda njegova.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (27, 10, 11, 'Kad su ga pritijesnili lakomci, pomogla ga je i obdarila bogatstvom,');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (27, 10, 12, 'sačuvala ga od neprijatelja i zaštitila ga od zasjeda, darovala mu pobjedu u žestokom boju da spozna kako je bogobojaznost od svega jača.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (27, 10, 13, 'Ona nije ostavila prodanog pravednika, nego ga je čuvala od grijeha.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (27, 10, 14, 'S njime je u tamnicu sišla te ga ni u okovima nije zapustila dok mu nije donijela žezlo kraljevsko i vlast nad onima koji ga tlačiše i nagnala u laž one koji ga kaljahu, a njemu dala slavu vječnu.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (27, 10, 15, 'Ona je spasila sveti puk i rod besprijekorni od vlasti naroda mučiteljskog.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (27, 10, 16, 'Ušla je u dušu sluge Gospodnjeg, i on se strašnim kraljevima opro čudesima i znacima.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (27, 10, 17, 'Ona je dala plaću svetima za njihove trude i vodila ih putem čudesnim, danju im bila zaklon od žege i noću zvjezdani sjaj.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (27, 10, 18, 'Provela ih preko Mora crvenog, provela ih je preko vode velike,');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (27, 10, 19, 'a neprijatelje njihove valovima potopila i onda ih izbacila iz dubina bezdana.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (27, 10, 20, 'Zato su pravednici oplijenili bezbožnike i pjesmom proslavili tvoje sveto ime, Gospode, jednodušno opjevali tvoju ruku zaštitnicu.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (27, 10, 21, 'Jer je mudrost otvorila usta nijemima i obdarila djecu nejaku jezikom rječitim.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (27, 11, 1, 'Ona im je pothvate k uspjehu vodila po ruci proroka svetog');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (27, 11, 2, 'kad su prohodili pustoš nenastanjenu i dizali šatore po bespućima.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (27, 11, 3, 'Opirahu se dušmanima i branjahu se od neprijatelja;');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (27, 11, 4, 'a kad su ožednjeli i tebe prizvali, napojiše se vode iz strme pećine i zagasiše žeđ iz tvrda kamena.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (27, 11, 5, 'I tako je ono čime su bili kažnjeni neprijatelji njihovi postalo njima dobročinstvo kada bijahu u nevolji. [7a] Njima si, zbog njihove zapovijedi o čedomorstvu,');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (27, 11, 6, 'umjesto vječnog izvora vode tekućice, dao rijeku zamućenu krvlju i blatom,');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (27, 11, 7, '[7b] a svojima si, unatoč svakoj nadi, dao izobilje vode,');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (27, 11, 8, 'pokazavši im u žeđi koja tada vladaše kakvom si kaznom kaznio neprijatelje njihove.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (27, 11, 9, 'Jer su iz kušnje kojom si ih milostivo ukorio lako razabrali kakvim se mukama namučiše bezbožnici kojima si u jarosti sudio.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (27, 11, 10, 'Jer si njih iskušao, opominjući blago kao otac, dok si one kao strahoviti kralj ispitao i osudio.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (27, 11, 11, 'Jednako su se mučili nazočni i nenazočni,');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (27, 11, 12, 'i dvostruka ih žalost obuzimaše i uzdisahu u sjećanju na prošlost.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (27, 11, 13, 'Kad čuše kako se ono što njima bijaše kazna obratilo Izraelcima u dobročinstvo, osjetiše ruku Gospodnju;');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (27, 11, 14, 'i kad sve bi gotovo, divljahu se onomu koga su nekoć izložili i s porugom ga odbili, jer njihova žeđ bijaše sasvim različita od žeđi pravednika.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (27, 11, 15, 'Da ih kazniš za njihove nepravedne i bezumne misli, što ih zavedoše da štuju nerazumne gmazove i bijedne životinje, poslao si na njih, za kaznu, mnoštvo životinja nerazumnih');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (27, 11, 16, 'da bi spoznali kako se svatko kažnjava onim čime i sagriješi.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (27, 11, 17, 'Tvoja svemoguća ruka - koja je sazdala svijet od tvari bezoblične - mogla je poslati na njih mnoštvo medvjeda ili ljutih lavova,');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (27, 11, 18, 'ili novostvorene, još nepoznate, divlje zvijeri pune gnjeva kojima iz nozdrva plamen liže, ili rigaju pare smrdljive, ili siplju strašne iskre iz očiju -');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (27, 11, 19, 'zvijeri kadre smožditi ih ne samo strašnim ujedom nego ih uništiti samom strahovitom pojavom.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (27, 11, 20, 'Ali i bez svega toga mogli su pasti od jednog jedinog daha, gonjeni tvojom pravdom, otpuhani tvojom silinom. Ali ti si sve uredio po broju, utegu i mjeri.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (27, 11, 21, 'I jer ti je uvijek u vlasti tvoja silna snaga, tko se može oprijeti tvojoj jakoj mišici?');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (27, 11, 22, 'Sav je svijet pred tobom kao zrnce praha na tezulji i kao kaplja jutarnje rose što se spušta na zemlju.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (27, 11, 23, 'A ti si milostiv svemu jer možeš sve i kroz prste gledaš na grijehe ljudima da bi se pokajali.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (27, 11, 24, 'Jer ti ljubiš sva bića i ne mrziš ni jedno koje si stvorio. Jer da si štogod mrzio, ne bi ga ni stvorio.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (27, 11, 25, 'A kako bi išta moglo opstojati ako ti ne bi htio? Ili se održati ako ga ti nisi u život dozvao?');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (27, 11, 26, 'Ali ti štediš, jer sve je tvoje, Gospodaru, ljubitelju života,');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (27, 12, 1, 'i tvoj je besmrtni duh u svemu.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (27, 12, 2, 'Blago kažnjavaš prestupnike, koriš ih i opominješ za grijehe njihove da se ostave zloće i da se ufaju u tebe, Gospode!');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (27, 12, 3, 'Zamrzio si drevne stanovnike svoje Svete zemlje');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (27, 12, 4, 'jer su činili zlodjela grozna u vradžbinama i obredima bezbožnim;');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (27, 12, 5, 'okrutne ubojice djece, žderače utrobe na gozbama mesa ljudskog, posvećenike s krvava pira,');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (27, 12, 6, 'roditelje ubojice bića bespomoćnih, odlučio si uništiti rukama otaca naših,');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (27, 12, 7, 'da najdraža ti od sviju zemalja primi dostojno naselje djece Božje.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (27, 12, 8, 'Ipak si i njih poštedio kao ljude, jer si im pred vojskom svojom poslao ose kao preteče da ih malo-pomalo istrijebe.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (27, 12, 9, 'Premda si ih mogao, kao bezbožnike, predati u boju rukama pravednika ili strašnim zvijerima ili ih strogom riječju najedanput zatrti,');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (27, 12, 10, 'sudeći im malo-pomalo, davao si mjesta pokajanju, premda si dobro znao da je to opak rod kojem je zloća prirođena i da im se ćud nikad neće izmijeniti,');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (27, 12, 11, 'jer je to pleme odiskona bilo prokleto. A što si ostavio nekažnjene njihove grijehe, nije bilo od straha ni pred kim.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (27, 12, 12, 'Jer tko bi tebi smio kazati: \"Što si učinio?\" I tko se smije oprijeti sudu tvojemu? Ili te optužiti što si uništio narode koje si stvorio? Ili tko će ustati protiv tebe kao branitelj nepravednih ljudi?');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (27, 12, 13, 'Jer, osim tebe, nema Boga koji se brine za sve da bi mu morao dokazati kako ne sudiš krivo.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (27, 12, 14, 'A nijedan kralj ni vladar ne smije ustati protiv tebe u korist onih koje si kaznio.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (27, 12, 15, 'I jer si pravedan, upravljaš svime pravedno, i nedostojno je moći tvoje kazniti onoga koji kazne ne zaslužuje.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (27, 12, 16, 'Jer moć je tvoja načelo pravice tvoje i jer svime vladaš, možeš i sve poštedjeti.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (27, 12, 17, 'Jakost svoju pokazuješ samo onda kad ljudi ne vjeruju u puninu tvoje moći i kažnjavaš drskost onih koji je spoznaše.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (27, 12, 18, 'Ti, silni gospodaru, sudiš blago i upravljaš nama s velikom pažnjom, jer kad god hoćeš, moć ti je pri ruci.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (27, 12, 19, 'A takvim si djelima narod svoj poučio da pravednik ima biti čovječan; podario si sinovima svojim dobru nadu, jer daješ pokajanje za grijehe.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (27, 12, 20, 'Jer kad si s tolikim obzirom i blagošću kaznio neprijatelje djece svoje i smrtne krivce - dajući im vremena i prigode da se zloće svoje okane -');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (27, 12, 21, 'kako li si brižno sudio sinove svoje, čijim si ocima dao divna obećanja i prisegama i savezima!');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (27, 12, 22, 'Dok nas, dakle, koriš, dotle šibaš naše neprijatelje deset tisuća puta strože, da bismo se sjetili dobrote tvoje kada sami sudimo i da očekujemo milosrđe tvoje kada nam bude suđeno.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (27, 12, 23, 'Zato si one koji su živjeli bezbrižnim i bezumnim životom namučio njihovim vlastitim gnusobama.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (27, 12, 24, 'Jer su odviše zabasali na krivim putovima i stali kao bogove štovati najgore i najprezrenije od životinja, zabludjeli kao djeca bez razbora.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (27, 12, 25, 'Zato si im kao djeci bez razbora poslao kaznu rugla.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (27, 12, 26, 'A jer ih nije poučila kazna porugljiva, ubrzo iskusiše kaznu dostojnu Boga.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (27, 12, 27, 'Jer kad vidješe da su im za kaznu te životinje koje štovahu kao bogove, rasrdiše se na njih zbog patnja koje im prouzrokovaše i spoznaše pravoga Boga, o kom prije nisu htjeli ništa čuti. Zato ih je i stigla najviša osuda.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (27, 13, 1, 'Po naravi su glupi svi ljudi koji ne upoznaše Boga, oni koji iz vidljivih ljepota ne mogu spoznati onoga koji jest - nisu kadri prepoznati umjetnika po djelima njegovim;');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (27, 13, 2, 'nego smatraju bogovima koji svijetom vladaju oganj ili vjetar ili hitri zrak, zvjezdan krug ili silnu vodu ili svjetlila nebeska.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (27, 13, 3, 'Jer ako su ih, opčinjeni njihovom ljepotom, uzeli smatrati bogovima, morali su spoznati koliko ih tek nadmašuje njihov gospodar jer ih je stvorio sam Tvorac ljepote.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (27, 13, 4, 'Ako ih je i zadivila njihova sila i snaga, morali su iz toga zaključiti koliko je tek silniji njihov stvoritelj.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (27, 13, 5, 'Jer prema veličini i ljepoti stvorova možemo, po sličnosti, razmišljati o njihovu Tvorcu.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (27, 13, 6, 'Ali ovi ipak zaslužuju malen prijekor, jer možda samo lutaju tražeći Boga i želeći ga naći;');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (27, 13, 7, 'živeći među djelima njegovim, nastoje ih shvatiti, a zavodi ih samo naličje stvari jer vide toliko ljepote.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (27, 13, 8, 'Pa ipak, oprostiti im ne treba:');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (27, 13, 9, 'jer ako su bili kadri steći toliko spoznaje da mogu svemir istraživati, koliko su lakše mogli otkriti Gospodara svega toga!');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (27, 13, 10, 'Ali nesretnici su oni - i u mrtve se predmete ufaju - koji bogovima nazivaju djela ruku čovječjih: zlato i srebro, umjetno obrađeno, životinjske likove, bezvrijedni kamen isklesan drevnom rukom.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (27, 13, 11, 'Posiječe drvodjelja prikladno drvo, brižljivo mu oguli koru i s divnim umijećem načini predmet koristan za svagdašnju upotrebu.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (27, 13, 12, 'A triješće što preostane upotrijebi da spremi jelo kojim se siti.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (27, 13, 13, 'Ostane mu komad koji nije ni za što, drvo krivo i kvrgavo: uzme ga i u dokolici marljivo izrezuje, oblikuje ga umijećem nehotičnim, dade mu lik čovječji;');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (27, 13, 14, 'ili izdjelja od njega kakvu bezvrijednu životinju, crljenkom je oboji, crvenilom naliči, premaže joj svaku pjegu.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (27, 13, 15, 'Konačno joj načini prikladnu kućicu, metne na zid i prikuje željeznim čavlom.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (27, 13, 16, 'Pobrine se tako za nju da ne padne, dobro znajući kako sebi sama pomoći ne može: jer je lik kojem treba tuđe pomoći.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (27, 13, 17, 'I poslije svega toga on se ne stidi tu neživu stvar nagovarati i njoj se moliti za imetak, za ženidbu i djecu, i za zdravlje svoje zaziva nemoć,');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (27, 13, 18, 'za život preklinje smrt, i utječe se za pomoć samoj nemoći, za putovanje onomu koji ne može ni nogom maknuti;');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (27, 13, 19, 'i za svoje dobitke i pothvate, za uspjeh u svojem poslu, on traži snage u onoga komu su ruke najnemoćnije.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (27, 14, 1, 'Drugi se opet spremi da zaplovi, nakan da prebrodi bijesne valove, i prizivlje u pomoć drvo koje je slabije od drvene lađe što ga nosi.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (27, 14, 2, 'Jer je nju izmislila težnja za dobitkom i sagradila je mudrost graditeljska.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (27, 14, 3, 'Ali njome upravlja tvoja providnost, Oče, koji si dao i na moru put i u valovima stazu pouzdanu:');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (27, 14, 4, 'pokazuješ tako da možeš iz svake pogibelji izbaviti, da bi se nevješt smio ukrcati.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (27, 14, 5, 'Jer ti nećeš da neplodna budu djela tvoje mudrosti, zato ljudi povjeravaju svoj život i drvlju najneznatnijem te prelaze splavom burne valove i dolaze u luku spasa.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (27, 14, 6, 'Pa i nekoć, kad su izgibali oholi divovi, sklonila se nada ovog svijeta u splav kojom je upravljala ruka tvoja i svijetu ostavila sjeme za nova pokoljenja.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (27, 14, 7, 'Blagoslovljeno je drvo po kojem pravda dolazi,');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (27, 14, 8, 'a prokleta krivobožačka rukotvorina i onaj koji je načini; on jer je napravi, a ona jer se, iako prolazna, bogom nazva.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (27, 14, 9, 'Tako Bogu su mrski i bezbožnik i bezbožnost njegova,');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (27, 14, 10, 'izrađevina i izrađivač bit će jednako kažnjeni.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (27, 14, 11, 'Zato će osuda pasti na kumire neznabožačke, jer su postali gnusoba među stvorenjima Božjim i sablazan ljudskim dušama i zamka bezumničkim nogama.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (27, 14, 12, 'Pronalazak kumira bio je početak bluda i njihovo je otkriće izopačilo život.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (27, 14, 13, 'Nije ih bilo u početku niti će ih biti dovijeka.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (27, 14, 14, 'Jer su došli na svijet po ispraznosti čovječjoj i zato im je određen konac brz.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (27, 14, 15, 'Neki otac, satrt prijevremenom žalošću, načini lik svojeg djeteta koje je tako brzo ugrabljeno: i dojučerašnjeg mrtvaca sad već kao boga štuje i odredi svojim podanicima tajne obrede i žrtve.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (27, 14, 16, 'U tijeku vremena ukorijeni se taj bezbožni običaj i počeše ga kao zakon čuvati,');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (27, 14, 17, 'i po zapovijedi vladara uvelo se štovanje likova. A onih koje ljudi nisu mogli u osobi njihovoj štovati, jer su predaleko od njih prebivali, približavahu sebi njihovo daleko obličje, načinivši od čašćenog kralja vidljiv lik da mu nenazočnu revno laskaju kao da je nazočan.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (27, 14, 18, 'A i častoljublje umjetnika navodilo je na sve jače štovanje i one koji kralja nisu poznali.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (27, 14, 19, 'Jer umjetnik, koji se možda htio dodvoriti vladaru, trudio se svim svojim umijećem da obličje bude što ljepše,');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (27, 14, 20, 'te je svjetina, ponesena ljepotom djela, počela pridavati božanske počasti onomu koga je nedavno slavila kao čovjeka.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (27, 14, 21, 'I to postade zamka životu: robujući nesreći ili nasilju vladarskom, ljudi su neizrecivo ime Božje prenijeli na kamenje i na drvlje.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (27, 14, 22, 'I ne bijaše im dosta što su zastranili u spoznaji Boga, nego su, živeći u velikoj borbi zbog neznanja, tako veliko zlo još mirom nazivali.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (27, 14, 23, 'Jer, ili djecu žrtvuju ili vrše tajne obrede ili priređuju bijesne gozbe s čudnim običajima.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (27, 14, 24, 'Ne čuvaju više čistoće ni tijela ni ženidbe, jedan drugoga ili iz zasjede ubijaju ili jedan drugomu preljubom jade zadaju.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (27, 14, 25, 'Svuda zbrka: krv, ubojstvo, krađa, prijevara, pokvarenost, nevjernost, buna, kriva prisega,');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (27, 14, 26, 'uznemirivanje čestitih, zaboravljanje dobročinstva, oskrvnjenje duša, zločini protiv naravi, nered u braku, preljub, nećudorednost.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (27, 14, 27, 'Jer je krivoboštvo početak, uzrok i kraj svakog zla.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (27, 14, 28, 'Ili bjesne na svojim zabavama, ili izriču lažna proroštva, ili žive nepravedno, ili bez oklijevanja krivo prisežu.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (27, 14, 29, 'Jer se uzdaju u mrtve idole, ne boje se da će okajavati lažne prisege.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (27, 14, 30, 'Ali će ih za oboje stići kazna: što su služeći idolima iskrivili pojam o Bogu i što se krivo i podlo zaklinjahu prezirući sve što je sveto.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (27, 14, 31, 'Jer se prijestupima bezbožničkim uvijek osvećuje - ne moć prizivanih idola, nego pravda koja stiže grešnike.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (27, 15, 1, 'A ti si, Bože naš, blag i istinit, spor na gnjev i svime milostivo upravljaš.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (27, 15, 2, 'Ako i sagriješismo, tvoji smo! Priznajemo tvoju vlast i nećemo griješiti kad znamo da smo tvoji.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (27, 15, 3, 'Jer tebe znati - savršena je pravednost, i poznavati snagu tvoju korijen je besmrtnosti.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (27, 15, 4, 'Nas nije zaveo nikakav izum opaka ljudskog umijeća ni jalovo djelo slikarsko, likovi našarani ličilima');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (27, 15, 5, 'koji u budalama potiču žudnju te žude za neživim obličjem mrtva lika.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (27, 15, 6, 'Ljubitelji su zla i dostojni takvih nada oni koji ih čine ili žele ili štuju.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (27, 15, 7, 'Muči se lončar i gnječi zemlju mekanu: pravi posuđe kojim se služimo. Od istoga blata pravi posude koje služe u plemenite svrhe i one koje služe suprotnom: kakva će kojoj namjena biti - određuje lončar.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (27, 15, 8, 'I možda - o napora na zlo data! - od iste gline pravi ništavnog boga, on koji je nedavno od zemlje sazdan i koji će se ubrzo zemlji vratit\' od koje je uzet, kad se od njega duša zatraži.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (27, 15, 9, 'Ne mari on što će brzo umrijeti ni što mu je život kratkovjek, nego se natječe sa zlatarima i srebrnarima i nasljeduje mjedare, ponosan što pravi krivotvorine.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (27, 15, 10, 'Srce mu je kao pepeo, i nada mu od zemlje bjednija, i život od gline nevredniji,');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (27, 15, 11, 'jer nije poznao Stvoritelja svoga koji mu je udahnuo dušu djelatnu i nadahnuo ga dahom životnim.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (27, 15, 12, 'Nego misli da je žiće naše igra i život naš sajam pun probitka. \"Treba, veli, izbijati korist iz svega, čak iz zla.\"');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (27, 15, 13, 'Jer bolje no itko drugi zna takav da griješi kad od iste tvari zemljane pravi lomne posude i kumire.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (27, 15, 14, 'Ali su od svih najluđi i jadniji od duše čeda nejakog, oni neprijatelji tvog naroda koji ga nekoć tlačiše.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (27, 15, 15, 'Jer oni obožavahu sve poganske kumire koji ne mogu ni očima gledati, ni nosom disati, ni ušima slušati, ni prstima pipati, ni nogama hoditi.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (27, 15, 16, 'Jer ih čovjek načini, sazda ih onaj komu je dah u zajam dan. Nijedan čovjek ne može načiniti boga sebi slična;');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (27, 15, 17, 'i jer je smrtan, mrtvo djelo gradi bezbožničkim rukama. On je dragocjeniji od svojih svetinja, jer je živ, a one nisu.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (27, 15, 18, 'A čak štuju i najgadnije životinje, što su, po gluposti svojoj, gore od ostalih.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (27, 15, 19, 'Na njima nikakve ljepote da bi privlačile kao druge životinje: umakle su i Božjoj hvali i njegovu blagoslovu.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (27, 16, 1, 'Zato bijahu primjereno kažnjeni sličnim životinjama i mučeni mnoštvom kukaca.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (27, 16, 2, 'A narod si svoj, mjesto takvom kaznom, obasuo dobročinstvom; i da zadovoljiš njegovu žudnju žarku, pripravio si jelo izvanredno: slasne prepelice.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (27, 16, 3, 'I tako Egipćanima, premda željnima hrane, kad vidješe odvratne stvorove poslane protiv njih, zataji i naravna želja za jelom; a narodu si svojem poslije kratke oskudice poklonio jelo čudesno.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (27, 16, 4, 'Na tlačitelje morade doći neuklonjiva oskudica, dok je tvojima trebalo samo pokazati kako su teško mučeni neprijatelji njihovi.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (27, 16, 5, 'I kad je na njih navalio životinjski bijes te pogibahu od ujeda zmija vijugavih, srdžba tvoja još ne bješe došla do kraja.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (27, 16, 6, 'Da se opamete, bijahu samo uplašeni na kratak čas, jer su dobili spasonosni znak da se sjete zapovijedi tvoga Zakona.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (27, 16, 7, 'Jer tko god je u nj pogledao, ozdravio je, ali ne po onom u što je pogledao, već zbog tebe, Spasitelju sviju!');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (27, 16, 8, 'Ujedno si time dokazao našim dušmanima da si ti izbavitelj od zla svakoga.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (27, 16, 9, 'Umirahu od ujeda skakavaca i muha i ne bijaše lijeka životu njihovu, jer su zaslužili da budu tako kažnjeni.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (27, 16, 10, 'A sinovima tvojim nisu naudili ni zubi zmija otrovnica, jer im je milost tvoja u pomoć pritekla te ih iscijelila.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (27, 16, 11, 'Podbadao si ih samo i odmah ozdravljao da se sjete proroštava tvojih, da ne zapadnu u zaboravnost duboku i ostanu bez tvojeg dobročinstva.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (27, 16, 12, 'Jer njih nije liječila ni trava ni melem nego tvoja riječ, o Gospode, koja liječi sve.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (27, 16, 13, 'Ti imaš vlast nad životom i smrću, ti dovodiš do vrata Podzemlja i opet izvodiš.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (27, 16, 14, 'Čovjek može svojom zloćom ubiti, ali kad duh izađe, ne može ga vratiti niti izbaviti dušu oduzetu.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (27, 16, 15, 'Ruci se tvojoj ne može uteći.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (27, 16, 16, 'Mišica je tvoja silna kaznila bezbožnike koji te ne htjedoše priznati; gonio ih nečuven dažd i tuča, i pljusak neumoljiv, i oganj ih proždirao.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (27, 16, 17, 'A najčudnije: u vodi koja gasi sve rasla je ognju sve žešća moć, jer se svemir borio za pravednike.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (27, 16, 18, 'Čas bi se plamen ublažio da ne spali životinje poslane na bezbožnike, nego da ovi vide i spoznaju kako ih goni sud Božji;');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (27, 16, 19, 'čas bi opet buknuo u samoj vodi od ognja snažnije da uništi plodove zemlje opake.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (27, 16, 20, 'A narod si svoj hranio hranom anđeoskom, slao mu s neba gotov kruh koji je imao u sebi svaku slast i ugađao svakom ukusu.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (27, 16, 21, 'Pokazao si svojim darom slatku nježnost prema djeci, jer je dar ugađao svakom teku i mijenjao se u što je tko htio.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (27, 16, 22, 'Snijeg i led odolijevahu ognju ne topeći se, da bi se znalo kako je neprijateljske plodove uništio oganj koji je plamtio u tuči i bljeskao u daždu,');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (27, 16, 23, 'dok je opet oganj zaboravio snagu svoju da bi se nahranili pravednici.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (27, 16, 24, 'Jer sve stvorenje služi tebi, svojem Stvoritelju, napinje snagu svoju za kaznu opakima, a popušta za dobro onima koji se u te uzdaju:');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (27, 16, 25, 'zato se i tada u sve preobražavalo da posluži tvojoj darežljivosti svehraniteljskoj, prema želji potrebitih,');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (27, 16, 26, 'da bi sinovi tvoji, koje ljubiš, Gospode, naučili kako čovjeka na hrane različiti plodovi, nego riječ tvoja uzdržava sve koji u te vjeruju;');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (27, 16, 27, 'jer ono što nije mogao oganj uništiti rastopilo se pod toplinom jedne zrake sunčane,');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (27, 16, 28, 'da bi se znalo kako treba sunce preteći i tebi zahvaliti, prije svjetla zorina preda te stupiti.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (27, 16, 29, 'Jer se nada nezahvalnika rastapa kao zimski mraz i razlijeva se kao voda nekorisna.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (27, 17, 1, 'Veliki su i nedokučivi sudovi tvoji, zato lutaju duše nepoučljive.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (27, 17, 2, 'Dok su mislili bezbožnici da imaju u vlasti sveti narod tvoj, postadoše sužnji tmine u okovima duge noći, zatvoreni pod svojim krovovima, prognanici vječne providnosti.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (27, 17, 3, 'Mišljahu da će im se tajni grijesi skriti, pokriveni tamnim velom zaborava, a rasuše se u užasnu strahu, zaplašeni utvarama.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (27, 17, 4, 'Ni skrovište u koje se povukoše nije ih sačuvalo od straha, nego se oko njih razlijegao grozan jek, ukazivahu im se kobne utvare, mračnih lica.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (27, 17, 5, 'I nikakva im sila ognjena nije mogla svjetla pružiti, niti su sjajne plamene zvijezde mogle osvijetliti tu strašnu noć.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (27, 17, 6, 'Jedino im se ukazivaše neka lomača, sama od sebe upaljena, puna užasa; i kad bi ta prikaza iščezla, oni je, izvan sebe od straha, držahu strašnijom nego što bijaše.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (27, 17, 7, 'Nemoćna bijahu njihova umijeća čarobnjačka i njihovo hvastanje razborom bijaše izvrgnuto ruglu.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (27, 17, 8, 'Jer oni koji prije obećavahu kako će istjerati strah i tjeskobu iz bolne duše, sami se razbolješe od straha smiješnoga.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (27, 17, 9, 'Kad ih i nije ništa strahovito plašilo, bješe im na užas gmizanje životinja i šištanje zmija.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (27, 17, 10, 'Ginuli su od straha, ne usuđujući se pogledati ni u zrak kojem se ne može umaknuti.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (27, 17, 11, 'Jer zloća je strašljivaca: vlastitim se svjedočanstvom osuđuje i uvijek zlo uvećava kad je stane savjest tištiti.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (27, 17, 12, 'Jer strah i nije drugo nego izdaja pomagala što ih razum daje:');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (27, 17, 13, 'što se manje čovjek u sebi na njih oslanja, to mu teže pada što ne zna uzrok svojoj patnji.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (27, 17, 14, 'I tako oni, one noći zaista nemoćne izišle iz dubina Podzemlja nemoćnog, usnuli istim snom,');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (27, 17, 15, 'bijahu progonjeni strašnim sablastima ili su smalaksali obamrle duše, jer ih napade iznenadan i neočekivan strah.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (27, 17, 16, 'I tako svaki, pavši gdje se našao, osta zatočen u tamnici bez prijevornica:');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (27, 17, 17, 'i orač i pastir i radnik koji se samotan muči zaskočeni zapadoše u neminovnu nevolju, svi bijahu okovani jednim lancem tame.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (27, 17, 18, 'I šumni vjetar, i milopojni ptičji glas među lisnim granama, i odmjeren huk vode što silovito protječe; i divlja buka pećina što se ruše,');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (27, 17, 19, 'i nevidljiva trka životinja što skaču, i urlik ljutih divljih zvijeri, i jeka što se odbija od gorskih dolova - sve ih ispunjaše užasom.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (27, 17, 20, 'A sav svijet blistao od sjajne svjetlosti i prepuštao se nesmetano svojim djelima.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (27, 17, 21, 'Jedino se nad njima raskrilila teška noć, slika mraka koji će ih primiti; ali teži od same tame bijahu oni - teret sami sebi.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (27, 18, 1, 'A svetima tvojim svijetlila je svjetlost najveća, i Egipćani, slušajući njihov glas a ne videći im obličja, nazivahu ih blaženima jer nisu nevolju trpjeli;');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (27, 18, 2, 'i zahvaljivahu im što se ne osvećuju za nanesene nepravde i moljahu ih da im oproste neprijateljstvo.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (27, 18, 3, 'A Izraelcima si dao ognjen stup da im bude vođom na stazama neznanim, blago sunce na njihovu časnom putovanju.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (27, 18, 4, 'Zaslužili su Egipćani da svjetlost izgube i da ih tama zasužnji, jer u zatvoru držahu djecu tvoju po kojoj se svijetu imala podariti nepropadljiva svjetlost Zakona.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (27, 18, 5, 'I jer odlučiše pogubiti djecu svetaca, a jedno se od izložene djece spasilo, ti im za kaznu oduze mnoštvo djece i sve ih pogubi u silnoj vodi.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (27, 18, 6, 'A noć ona bijaše unaprijed najavljena ocima našim da bi jasno znali kakvim su prisegama povjerovali, i da budu dobre volje.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (27, 18, 7, 'Tako je tvoj narod očekivao spas pravednika i propast neprijatelja.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (27, 18, 8, 'Jer čime si kaznio naše protivnike, time si proslavio nas, pozvavši nas k sebi.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (27, 18, 9, 'Tada su pobožna djeca pravednika žrtve tajno prinijela i složno postavila zakon božanstven da sveti tvoji jednako snose i dobra i pogibelji. I tad su zapjevali svete pjesme otaca.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (27, 18, 10, 'A u odjek im dođoše neskladni povici neprijatelja, tužan jauk za djecom oplakivanom.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (27, 18, 11, 'Jednaka kazna stiže i roba i gospodara, isto je trpio i pučanin i kralj.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (27, 18, 12, 'A svi su zajedno imali nebrojene mrtvace pogođene istom smrću. I živih bijaše premalo da pokapaju mrtve, jer im za tren poginu najodličniji porod.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (27, 18, 13, 'I oni koji, zbog svojih čarolija, ni u što nisu vjerovali, kad im izginuše prvenci njihovi, moradoše priznati da je narod izraelski - sin Božji.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (27, 18, 14, 'Dok je mirna tišina svime vladala i noć brzim tijekom stigla do sredine puta svog,');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (27, 18, 15, 'jurnula je tvoja svemoguća riječ s nebesa, s kraljevskih prijestolja, kao žestok ratnik u sredinu zemlje, propasti predane. Kao oštar mač nosila je tvoju neopozivu zapovijed.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (27, 18, 16, 'Zaustavi se i sve ispuni smrću: doticala se neba, stajala na zemlji.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (27, 18, 17, 'Tada Egipćane iznenada uplašiše prikaze jezivih snova, napade ih neočekivan strah.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (27, 18, 18, 'Padahu polumrtvi, jedan ovdje, drugi ondje, kazujući zašto umiru.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (27, 18, 19, 'Jer su im sni, što ih smutiše, to unaprijed najavili, da ne bi poginuli ne znajući uzroka s kojeg ih je stiglo zlo.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (27, 18, 20, 'Ali se napast smrtna dotakla i pravednika i mnoštvo ih je u pustinji pomrlo. Ali srdžba nije dugo trajala.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (27, 18, 21, 'Jer se brzo za njih zauzeo čovjek besprijekoran: naoružan oružjem službe svoje - molitvom i pomirbenim kadom - opro se srdžbi i dokrajčio nevolju, pokazavši da je sluga tvoj.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (27, 18, 22, 'On gnjevu nije odolio ni snagom tjelesnom ni silom oružja nego je riječju svojom pokorio zatornika spomenuv otačke prisege i zavjete.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (27, 18, 23, 'Mrtvi već ležahu jedan preko drugoga, a on stade sred njih i jarost suzbi, presiječe joj put ka živima.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (27, 18, 24, 'Na njegovoj dugoj halji bijaše čitav svemir i u četiri reda dragulja slavna imena otaca, a na vijencu oko glave tvoje veličanstvo.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (27, 18, 25, 'Pred tim uzmaknu zatornik, predade se: samo je malo okušao srdžbu tvoju - i bijaše mu dosta.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (27, 19, 1, 'A grešnike je sasvim pritisnuo gnjev nemilostiv, jer je Gospodin znao što će oni:');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (27, 19, 2, 'najprije će dopustiti Izraelcima da odu i brzo ih ispratiti, a zatim će se predomisliti i poći za njima u potjeru.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (27, 19, 3, 'Još im teška žalost bijaše na srcu dok naricahu nad grobovima svojih mrtvaca, kad im pade na um nova luda misao te stadoše kao bjegunce progoniti one koje su prije molili da odu.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (27, 19, 4, 'A zaslužena ih je sudbina nagnala da zaborave prošle jade i da svojim mukama dodaju još jednu:');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (27, 19, 5, 'dok će narod tvoj prijeći put čudesan, oni će naći smrt nečuvenu.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (27, 19, 6, 'Da se sačuvaju djeca tvoja neozlijeđena, sve stvoreno preinači opet narav svoju služeći tvojim zapovijedima.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (27, 19, 7, 'Oblak se pojavi i sjenom zakri tabor, a kopno izroni gdje prije bijaše voda; put slobodan nasta od Crvenoga mora i polje travnato od strašnih valova.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (27, 19, 8, 'Preko njega prijeđe narod sav, štićen tvojom desnicom, zadivljen silnim čudesima.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (27, 19, 9, 'Bijahu kao konji kada pasu, i kao jaganjci skakahu slaveći tebe, Gospode, izbavitelja svoga.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (27, 19, 10, 'Još se sjećahu događaja u tuđini, kako je mjesto životinja zemlja komarce rađala i kako je mjesto riba rijeka izbacila mnoštvo žaba.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (27, 19, 11, 'Poslije vidješe i nov nastanak ptica, kada su, potaknuti žudnjom, zatražili jela raskošna:');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (27, 19, 12, 'izašle iz mora prepelice da im želji udovolje.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (27, 19, 13, 'A grešnike stigla kazna, prethodili joj snažni gromovi. Stigla ih pravedna plaća za zla djela, jer su divljom mržnjom mrzili tuđince.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (27, 19, 14, 'Jer dok oni odbijahu neznance, ovi goste i dobrotvore pretvoriše u robove.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (27, 19, 15, 'Oni se prema strancima poniješe odmah neprijateljski, i plaća ih čeka za to.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (27, 19, 16, 'Ovi, naprotiv, primiše svečano Izraelce, a onda ih, već ravne sebi, udariše teškom tlakom.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (27, 19, 17, 'I njih udari sljepoća kao i one pred vratima pravednikovim; opkoli ih tama duboka, i svaki je tražio svoja vrata.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (27, 19, 18, 'Tako se počela međusobno izmjenjuju, kao što se skladno izmjenjuju glasovi na harfi, ostajući uvijek kod zvuka svojeg; a to se može jasno razabrati kad se razmotre događaji.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (27, 19, 19, 'Jer se kopnene životinje u vodene mijenjahu, a one što plivaju, na kopno prelažahu.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (27, 19, 20, 'Oganj je u vodi silu svoju pojačao, a voda zaboravila snagu što gasi.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (27, 19, 21, 'Plamenovi ognjeni nisu pržili meso životinja propadljivih kada su posred njih hodile niti se u njima topila hrana nebeska, laka i topljiva poput inja.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (27, 19, 22, 'U svemu si, Gospode, uzvisio i proslavio narod svoj i nisi ga prezreo, već si mu bio na pomoći svagda i svagdje.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (28, 1, 1, 'Svaka je mudrost od Gospoda i s njime je dovijeka.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (28, 1, 2, 'Tko će izbrojiti pijesak morski i kaplje kišne i dane vječnosti?');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (28, 1, 3, 'Tko će istražiti nebesku visinu, zemaljsku širinu i dubinu bezdana?');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (28, 1, 4, 'Mudrost je stvorena prije svega ostalog, i misaon razbor vječan je.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (28, 1, 5, '#');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (28, 1, 6, 'Komu se otkrio korijen mudrosti i tko znade njezine namisli?');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (28, 1, 7, '#');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (28, 1, 8, 'Samo je jedan mudar i uistinu strašan kad sjedi na prijestolju svojem - Gospod.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (28, 1, 9, 'On ju je stvorio, gledao i izbrojio, izlio je na sva svoja djela,');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (28, 1, 10, 'na svako tijelo prema veličini njegovoj i obdario njome one koji ga ljube.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (28, 1, 11, 'Strah je Gospodnji slava i hvala, veselje i vijenac radosti.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (28, 1, 12, 'Strah Gospodnji sladi srce, daje radost, veselje i dug život.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (28, 1, 13, 'Tko se boji Gospoda, sretan je na svršetku i blagoslovljen u dan svoje smrti.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (28, 1, 14, 'Strah Gospodnji početak je mudrosti, s vjernima je ona stvorena u utrobi majčinoj.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (28, 1, 15, 'Svila je gnijezdo s temeljem vječnim među ljudima i bit će vjerna porodu njihovu.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (28, 1, 16, 'Strah je Gospodnji punina mudrosti, ona ih opija svojim plodovima.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (28, 1, 17, 'Dom im napunja milinama i klijeti svojim urodom.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (28, 1, 18, 'Strah Gospodnji vijenac je mudrosti koji cvate mirom i zdravljem.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (28, 1, 19, 'Gospod je nju gledao i izbrojio i izlio spoznaju i razbor, uzvisio slavu onih koji je posjeduju.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (28, 1, 20, 'Strah Gospodnji korijen je mudrosti, a izdanci su dug život.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (28, 1, 21, '#');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (28, 1, 22, 'Strast opakoga ne može opravdati, jer mu teret strasti donosi pad.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (28, 1, 23, 'Strpljiv čovjek podnosi do u pravi čas, a na kraju uživa radost.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (28, 1, 24, 'On krije svoje riječi do pravog trena, i usta mnogih govore o njegovu razboru.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (28, 1, 25, 'U riznicama mudrosti zagonetke su spoznaje, ali je grešniku mrska pobožnost.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (28, 1, 26, 'Želiš li mudrost, vrši zapovijedi, i Gospod će ti je dati.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (28, 1, 27, 'Jer strah je Gospodnji mudrost i pouka, i Gospodu je draga vjernost i krotkost.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (28, 1, 28, 'Ne opiri se strahu Gospodnjem i ne pristupaj Gospodu dvolična srca.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (28, 1, 29, 'Ne budi licemjer pred ljudima i pazi na usne svoje.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (28, 1, 30, 'Ne uznosi se, da ne padneš i da se ne osramotiš, jer Gospod će otkriti tvoje tajne i poniziti te pred svim zborom, jer nisi dosegao straha Gospodnjeg i jer ti je srce puno prijevare.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (28, 2, 1, 'Sine moj, ako želiš služiti Gospodu, pripravi dušu svoju na kušnju.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (28, 2, 2, 'Učvrsti svoje srce i budi jak i ne nagli kad napast dođe.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (28, 2, 3, 'Prioni uz Boga i ne odmeći se, da bi bio slavljen na svoj posljednji dan.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (28, 2, 4, 'Primi sve što te stigne i budi strpljiv u nestalnosti svoje bijede.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (28, 2, 5, 'Jer kao što se u vatri kuša zlato, tako i odabranici u peći poniženja.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (28, 2, 6, 'Vjeruj u Gospoda, i on će ti pomoći, kroči pravom stazom i uzdaj se u njega.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (28, 2, 7, 'Vi što se bojite Gospoda, očekujte njegovu milost i ne skrećite s pravoga puta, da ne propadnete.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (28, 2, 8, 'Vi što se bojite Gospoda, uzdajte se u nj i plaća vam neće propasti.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (28, 2, 9, 'Vi što se bojite Gospoda, nadajte se dobru, vječnoj radosti i milosti.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (28, 2, 10, 'Pogledajte prošla pokoljenja i vidite: je li se ikad postidio tko se uzdao u Gospoda? Je li ikad ostavljen tko ga se ustrajno bojao? Je li ikad prezren koji ga je u pomoć zvao?');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (28, 2, 11, 'TÓa Gospod je sućutan i milostiv, on oprašta grijehe i izbavlja u danima nevolje.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (28, 2, 12, 'Jao strašljivim srcima i lijenim rukama i grešniku koji hodi dvjema stazama.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (28, 2, 13, 'Jao mlaku srcu koje ne vjeruje, jer takvo neće naći zaštite.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (28, 2, 14, 'Jao vama koji ste izgubili izdržljivost: što ćete raditi kad vas Gospod pohodi?');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (28, 2, 15, 'Koji se boje Gospoda slušaju njegove riječi, i koji ga ljube drže se putova njegovih.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (28, 2, 16, 'Koji se boje Gospoda čine što je njemu po volji, i koji ga ljube uživaju u njegovu Zakonu.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (28, 2, 17, 'Koji se boje Gospoda pripravljaju se srcem svojim i pred njim se ponizuju.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (28, 2, 18, 'Predajmo se u ruke Gospodnje, a ne u ruke ljudske: jer kakvo je u Gospoda veličanstvo, takva je i njegova milost.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (28, 3, 1, 'Djeco, slušajte mene, oca svoga, i radite tako da se spasite.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (28, 3, 2, 'Jer Gospod slavi oca u djeci njegovoj i učvršćuje pravo majke nad sinovima njezinim.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (28, 3, 3, 'Tko štuje oca okajava grijehe svoje,');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (28, 3, 4, 'i tko časti majku svoju sabire blago.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (28, 3, 5, 'Tko štuje oca radovat će se sa svoje djece i bit će uslišen u dan molitve svoje.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (28, 3, 6, 'Tko časti oca svojeg, dugo živi; tko čini radost majci svojoj sluša Gospoda.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (28, 3, 7, 'On služi roditeljima svojim kao svojim gospodarima.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (28, 3, 8, 'Sine moj, riječju i djelom štuj oca svoga da te od njega stigne blagoslov.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (28, 3, 9, 'Jer blagoslov očev učvršćuje kuću djeci, a majčina kletva temelje im ruši.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (28, 3, 10, 'Ne traži časti u sramoti oca svojeg, jer ti očeva sramota nije na čast.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (28, 3, 11, 'Jer čovjeku dolazi čast od počasti oca njegova, a prezrena majka sramota je djeci.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (28, 3, 12, 'Sine moj, pomozi oca svoga u starosti i ne žalosti ga za života njegova.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (28, 3, 13, 'Ako mu i razum klone, budi blag s njime i ne grdi ga ti, koji si u punoj snazi.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (28, 3, 14, 'Jer, ne zaboravlja se milost prema ocu, već se uračunava u oprost grijeha.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (28, 3, 15, 'U danima tvoje nevolje Gospod će te se sjetiti: kao što se led topi na suncu, tako će se iskopnjeti tvoji grijesi.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (28, 3, 16, 'Od hulitelja nije bolji tko prezire oca, i Gospod proklinje onoga tko vrijeđa majku.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (28, 3, 17, 'Sine moj, budi krotak u poslu svojem, i bit ćeš voljeniji nego onaj koji darove dijeli.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (28, 3, 18, 'Što si veći to se većma ponizi da nađeš milost u Gospoda.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (28, 3, 19, 'Jer veliko je milosrđe Božje i poniznima otkriva tajnu svoju.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (28, 3, 20, 'Iako je velika moć Gospoda, on prima počast poniznih.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (28, 3, 21, 'Ne idi za onim što ti je previsoko i ne istražuj ono što je iznad tvojih snaga.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (28, 3, 22, 'Trsi se duhom svojim oko onoga što ti je dano i ne bavi se pojavama otajstvenim.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (28, 3, 23, 'Ne trudi se oko onog što je iznad tvoje snage, jer i ono čemu su te učili već je pregolemo za um ljudski.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (28, 3, 24, 'Mnoge već zavede njihova umišljenost, i opaka uobraženost iskrivi im misli.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (28, 3, 25, '#');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (28, 3, 26, 'Tvrdokorno srce u zlu završava, i tko pogibelj ljubi, u njoj i propada.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (28, 3, 27, 'Tvrdokorno srce oteščalo je od nevolja, i grešnik gomila grijeh na grijeh.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (28, 3, 28, 'Nema lijeka bolesti oholnika, jer se opačina u njem ukorijenila.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (28, 3, 29, 'Srce razborita čovjeka razmišlja o izrekama, i pažljivo uho san je mudracu.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (28, 3, 30, 'Kao što voda gasi uzbuktali oganj, tako i milosrđe čisti od grijeha.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (28, 3, 31, 'Tko dobročinstva uzvraća misli na budućnost, i u času svojeg pada naći će potporu.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (28, 4, 1, 'Sine moj, ne uskraćuj milodara siromahu i ne daj da dugo iščekuju oči ubogoga.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (28, 4, 2, 'Ne žalosti dušu gladnu i ne draži čovjeka u oskudici njegovoj.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (28, 4, 3, 'Ne razdražuj srca ogorčena i ne pusti uboga da čeka na dan tvoj.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (28, 4, 4, 'Ne odbij molbe nevoljnika i ne odvraćaj lice svoje od siromaha.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (28, 4, 5, 'Ne odvrati pogleda svoga od potrebita i ne daj nikomu prilike da te kune.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (28, 4, 6, 'Jer prokune li te tko u tjeskobi duše svoje, Tvorac će njegov uslišiti mu vapaj.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (28, 4, 7, 'Nastoj omiljeti društvu i prigni glavu pred vladarem.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (28, 4, 8, 'Saslušaj siromaha i uljudno mu odzdravi;');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (28, 4, 9, 'izbavi potlačena od njegova tlačitelja i ne budi podao u svojoj presudi.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (28, 4, 10, 'Budi kao otac sirotama i kao muž budi na pomoć udovicama. I bit ćeš kao sin Svevišnjemu, koji će te ljubiti više nego tvoja majka.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (28, 4, 11, 'Mudrost odgaja sinove svoje i brine se za one koji je traže.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (28, 4, 12, 'Tko ljubi nju, ljubi život, i koji je rano traže ispunit će se srećom.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (28, 4, 13, 'Tko je posjeduje baštinit će čast, i kamo god krene, Gospod ga blagoslivlja.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (28, 4, 14, 'Služe Svetomu koji njoj služe, i Gospod ljubi one koji ljube nju.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (28, 4, 15, 'Tko nju posluša sudi pravedno, i tko se nje drži on je na pouzdanu.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (28, 4, 16, 'Ako se u nju ufa, onda je i baštini, i ona ostaje u posjedu njegovih potomaka.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (28, 4, 17, 'Jer iako u početku vodi putem krivudavim, nagoni ga na tjeskobu i drhtavicu, muči ga stegom svojom dok se ne mogne u nj pouzdati, iskušava ga zapovijedima svojim,');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (28, 4, 18, 'a na kraju će ga privesti pravom putu i otkriti mu svoje tajne.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (28, 4, 19, 'Ako odluta, ona ga ostavlja i predaje njegovoj propasti.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (28, 4, 20, 'Sine moj, pazi na prilike i čuvaj se zla, i ne stidi se samoga sebe.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (28, 4, 21, 'Jer ima stid što vodi grijehu, kao i stid koji je čast i milost.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (28, 4, 22, 'Ne budi pristran protiv sebe samoga i ne stidi se na svoju propast.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (28, 4, 23, 'Ne susteži svoje riječi u pravo vrijeme i ne skrivaj svoje mudrosti.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (28, 4, 24, 'Jer se u govoru očituje mudrost i po riječima otkriva naobrazba.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (28, 4, 25, 'Ne protivi se istini, radije se crveni zbog svojeg neznanja.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (28, 4, 26, 'Ne stidi se priznati svoje grijehe i ne opiri se struji rijeke.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (28, 4, 27, 'Ne ponizuj se pred budalom i ne budi pristran pred mogućnicima.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (28, 4, 28, 'Do smrti se bori za istinu, i Gospod će se boriti za te.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (28, 4, 29, 'Ne budi silovit na jeziku a lijen i mlitav na djelu.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (28, 4, 30, 'Ne budi kao lav u svojoj kući, a strašljivac prema svojim slugama.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (28, 4, 31, 'Nek\' ti ne bude ruka ispružena za primanje, a stisnuta u vrijeme vraćanja.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (28, 5, 1, 'Ne oslanjaj se na svoje bogatstvo i ne reci: \"Ja imam dosta.\"');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (28, 5, 2, 'Ne idi za svojom željom i svojom snagom, slijedeći strasti svoga srca.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (28, 5, 3, 'Ne reci: \"Tko mi što može?\" jer će te Gospod kazniti.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (28, 5, 4, 'Ne reci: \"Griješio sam, pa što!\" jer Gospod umije čekati.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (28, 5, 5, 'Ne uzdaj se toliko u oproštenje da gomilaš grijeh na grijeh.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (28, 5, 6, 'Ne reci: \"Veliko je milosrđe njegovo, oprostit će mi moje mnoge grijehe!\" jer je s njime milosrđe i gnjev te na grešnike pada srdžba njegova.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (28, 5, 7, 'Ne oklijevaj vratiti se njemu, i ne odgađaj iz dana u dan; jer će iznenada njegov gnjev planuti, i u čas osvetni ti ćeš propasti.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (28, 5, 8, 'Ne uzdaj se u blago krivo stečeno, ono ti ništa neće koristiti u dan nesreće.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (28, 5, 9, 'Ne povijaj se sa svakim vjetrom i ne idi po svakoj stazi (tako čini grešnik licemjerni).');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (28, 5, 10, 'Budi postojan u nazorima svojim i neka je jedna tvoja riječ.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (28, 5, 11, 'Budi brz i pripravan saslušati, a spor odgovarati.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (28, 5, 12, 'Ako znaš, odgovori svojem bližnjemu; ako ne znaš, stavi ruku na usta.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (28, 5, 13, 'I slava i sramota dolaze od riječi, i jezik je čovjekov propast njegova.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (28, 5, 14, 'Ne budi klevetnik i jezikom svojim ne postavljaj zamke, jer kao što lupeža čeka sramota, tako podlaca očekuje teška osuda.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (28, 5, 15, 'Ne budi opak ni u malu ni u veliku i ne budi neprijatelj umjesto prijatelj.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (28, 5, 16, '');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (28, 5, 17, '');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (28, 6, 1, 'Jer zao glas donosi zazor i sramotu, kako to biva grešniku licemjernom.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (28, 6, 2, 'Ne predaj se u ruke svojoj strasti, da ti ona dušu ne rastrga kao razbješnjeli bik;');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (28, 6, 3, 'da ti ne obrsti lišće i da ti ne propadnu plodovi i ne ostaneš poput sasušena drveta.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (28, 6, 4, 'Jer strastvena duša propast je onome čija je i čini od njega ruglo pred njegovim neprijateljima.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (28, 6, 5, 'Umilna riječ umnožava prijatelje, i jezik uljudan izaziva prijazne odgovore.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (28, 6, 6, 'Neka su ti mnogi poznanici, ali pouzdanik samo jedan od tisuću.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (28, 6, 7, 'Ako želiš imati prijatelja, steci ga kušanjem i nemoj se prebrzo u nj pouzdati.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (28, 6, 8, 'Jer netko je prijatelj samo kad to njemu odgovara i taj ne ostaje vjeran u dan nevolje.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (28, 6, 9, 'A neki će se prijatelj prometnuti u neprijatelja i tvoju sramotu iznijeti na vidjelo.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (28, 6, 10, 'Gdjekoji je opet prijatelj za stolom, ali ga nema u času nevolje.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (28, 6, 11, 'Dok si sretan, on će ti biti kao ti sam sebi: s ukućanima tvojim povjerljiv će biti;');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (28, 6, 12, 'a stigne li te zlo, okrenut će se protiv tebe i bježat će od tvog pogleda.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (28, 6, 13, 'Odvoji se od svojih neprijatelja i čuvaj se svojih prijatelja.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (28, 6, 14, 'Vjeran prijatelj pouzdana je zaštita; i tko ga je stekao našao je blago.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (28, 6, 15, 'Pravom prijatelju nema cijene niti se može izmjeriti njegova vrijednost.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (28, 6, 16, 'Pravi je prijatelj balzam života, nalazi ga onaj tko se Gospoda boji.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (28, 6, 17, 'Tko se Gospoda boji, nalazi prave prijatelje, jer kakav čovjek, takav mu i prijatelj.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (28, 6, 18, 'Sine, uči od mladosti svoje, prigrli pouku, pa ćeš do svojih sjedina nalaziti mudrost.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (28, 6, 19, 'Prilazi joj kao orač i sijač i očekuj obilnu ljetinu, jer malo ćeš se oko nje truditi i brzo ćeš jesti od ploda njezina.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (28, 6, 20, 'Veoma je opora nepokornima, i nerazborit ne ustraje u njoj.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (28, 6, 21, 'Ona ga tišti kao težak kamen i on ne oklijeva da je odbaci.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (28, 6, 22, 'Jer stega je vjerna svojem imenu, ona mnogima nije dostupna.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (28, 6, 23, 'Poslušaj, sine, primi moj naputak i ne odbaci savjeta mog.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (28, 6, 24, 'Stavi svoje noge u njezine okove i vrat svoj u njezin jaram.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (28, 6, 25, 'Podmetni svoja leđa pod njezin teret, i neka ti ne smetaju njezine uzde.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (28, 6, 26, 'Svom dušom svojom pristupi k njoj i svom snagom svojom slijedi putove njezine.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (28, 6, 27, 'Ispituj i istražuj je, i ona će ti se objaviti; i kad je jednom uhvatiš, ne puštaj je.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (28, 6, 28, 'Jer ćeš naposljetku u njoj naći mir, i ona će ti se pretvoriti u radost.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (28, 6, 29, 'Njezini okovi bit će moćna zaštita i njezin jaram halja časti.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (28, 6, 30, 'Njezin jaram bit će zlatni ures, njezine uzde grimizne vrpce.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (28, 6, 31, 'Nosit ćeš je kao svečanu odoru i vezat ćeš je kao krasni vijenac.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (28, 6, 32, 'Ako si voljan, sine, možeš postati mudar; i ako se potrudiš, steći ćeš razboritost.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (28, 6, 33, 'Ako si pripravan slušati, naučit ćeš; ako poslušaš, bit ćeš mudar.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (28, 6, 34, 'Nek\' ti je mjesto u staračkom zboru; i vidiš li mudraca, drži se uz njega.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (28, 6, 35, 'Rado slušaj svaku riječ koja dolazi od Boga i neka ti ne promaknu oštroumne izreke.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (28, 6, 36, 'Vidiš li razborita čovjeka, rano ga posjeti i neka tvoja stopala istaru njegov prag.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (28, 6, 37, 'Razmišljaj o zapovijedima Gospodnjim i neprestano se drži njegovih naredaba, i Gospod će osnažiti tvoje srce i steći ćeš mudrost koju želiš.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (28, 7, 1, 'Ne čini zla, pa te zlo neće stići.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (28, 7, 2, 'Kloni se nepravde, i ona će biti daleko od tebe.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (28, 7, 3, 'Ne sij, sine moj, u brazde nepravde, da ih ne požanješ sedmerostruko.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (28, 7, 4, 'Ne traži od Gospoda najviše mjesto, niti od kralja počasno sjedalo.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (28, 7, 5, 'Ne razmeći se vrlinom pred Gospodom niti mudrošću pred kraljem.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (28, 7, 6, 'Ne traži da budeš sudac ako nemaš snage iskorijeniti nepravdu, da ne bi popustio pred mogućnikom i postavio stupicu pravednosti svojoj.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (28, 7, 7, 'Ne griješi prema javnom zboru, da ne izgubiš ugled u zajednici.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (28, 7, 8, 'Nemoj dvaput griješiti, jer već zbog prvog grijeha nećeš umaći kazni.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (28, 7, 9, 'Ne reci: \"Pogledat će Bog na mnoge moje darove i primit će Svevišnji Bog kad mu ih prinesem.\"');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (28, 7, 10, 'Ne budi malodušan u molitvi svojoj i ne zanemari dati milodar.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (28, 7, 11, 'Ne preziri čovjeka turobna srca, jer onaj tko ponizuje može i uzvisiti.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (28, 7, 12, 'Ne pleti prijevare bratu svojem, niti prijatelju takvo što čini.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (28, 7, 13, 'Kloni se svake laži, jer od nje dobra nikakva.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (28, 7, 14, 'Ne govori predugo na zboru staraca i ne ponavljaj riječi u molitvi svojoj.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (28, 7, 15, 'Ne prezri tegobna rada ni ratarskog posla što ga je Svevišnji dao.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (28, 7, 16, 'Ne ubrajaj se među grešnike, sjeti se da srdžba ne kasni!');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (28, 7, 17, 'Ponizi duboko dušu svoju, jer su vatra i crvi kazna bezbožniku.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (28, 7, 18, 'Ne mijenjaj prijatelja za novac ni brata za ofirsko zlato.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (28, 7, 19, 'Ne odbacuj razumne i dobre žene, jer njezina je ljupkost dragocjenija od zlata.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (28, 7, 20, 'Ne zlostavljaj roba koji pošteno radi ni sluge koji ti vjerno služi.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (28, 7, 21, 'Ljubi razumna roba kao sebe samog i ne uskrati mu slobode.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (28, 7, 22, 'Imaš li živinče, pazi ga; ako ti je od koristi, sačuvaj ga.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (28, 7, 23, 'Imaš li djece, pouči ih i povij im vrat za mladosti.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (28, 7, 24, 'Imaš li kćeri, čuvaj im tijelo i ne pokazuj im odveć prijazno lice.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (28, 7, 25, 'Udaj kćer, i obavio si krupan posao, ali je daj čovjeku razumnu.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (28, 7, 26, 'Imaš li ženu po srcu svojem, ne otpuštaj je; ako li je ne voliš, ne uzdaj se u nju.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (28, 7, 27, 'Svim srcem poštuj oca svoga i ne zaboravi majčinih bolova.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (28, 7, 28, 'Sjeti se da im svoj život duguješ: kako da im uzvratiš sve što učiniše za te?');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (28, 7, 29, 'Svom dušom svojom boj se Gospoda i štuj njegove svećenike.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (28, 7, 30, 'Svom snagom svojom ljubi Stvoritelja svoga i ne ostavljaj slugu njegovih.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (28, 7, 31, 'Boj se Boga i štuj svećenika, daj mu dio kako ti je naloženo: prvine, naknadnice i prinos plećaka, posvetnice i prvence svetinja.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (28, 7, 32, 'I siromahu pruži ruku, da bude savršen tvoj blagoslov.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (28, 7, 33, 'Budi darežljiv svakomu živom stvoru, pa ni mrtvomu ne uskrati milosti.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (28, 7, 34, 'Ne uklanjaj se od onih koji plaču, već s tužnim tuguj.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (28, 7, 35, 'Ne zaboravi posjetiti bolesnika, jer će te za to ljubiti.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (28, 7, 36, 'U svim svojim djelima misli na svoj konac, pa nećeš nikada griješiti.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (28, 8, 1, 'Ne bori se s velikašem, da mu ne padneš u šake.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (28, 8, 2, 'Ne pravdaj se s bogatašem, da se ne pokaže težim od tebe. Jer zlato je već mnoge uništilo i zavelo srce kraljevima.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (28, 8, 3, 'Ne prepiri se s čovjekom hitra jezika i ne meći mu drva na vatru.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (28, 8, 4, 'Ne šali se s neodgojenim čovjekom, da ti ne bi uvrijedio predaka.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (28, 8, 5, 'Ne sramoti čovjeka koji se obratio od grijeha; sjeti se da smo svi krivci.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (28, 8, 6, 'Ne prezri starca čovjeka, jer će i od nas neki ostarjeti.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (28, 8, 7, 'Ne likuj nad preminulim; sjeti se da svi umiremo.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (28, 8, 8, 'Ne odbacuj razgovora mudrih, nego razmišljaj o njihovim izrekama, jer ćeš tako steći nauk i umijeće za službu velikašima.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (28, 8, 9, 'Ne podcjenjuj govora staraca, jer oni su učili od svojih roditelja, a od njih ćeš se ti naučiti razboru i u pravo vrijeme odgovarati.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (28, 8, 10, 'Ne raspiruj ugljevlja grešnikova, da se ne ožežeš njegovim plamenom.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (28, 8, 11, 'Ne dopusti da te rugač razgnjevi i postavi ti zamku tvojim vlastitim riječima.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (28, 8, 12, 'Ne uzajmljuj čovjeku moćnijem od sebe; ako si uzajmio, kao da si izgubio.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (28, 8, 13, 'Ne jamči preko svojih mogućnosti; ako si jamčio, misli kako ćeš platiti.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (28, 8, 14, 'Ne parbi se sa sucem, jer će mu dosuditi po volji.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (28, 8, 15, 'Ne idi na put s pustolovom, da ti se on ne natovari: jer on će činiti po svojoj volji, i njegova će ludost obojicu upropastiti.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (28, 8, 16, 'S čovjekom gnjevnim ne zameći svađe i ne putuj s njim po pustinji, jer njemu nije ništa proliti krv, i na mjestu gdje nema pomoći ubit će te.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (28, 8, 17, 'Luđaka ne pitaj za savjet, jer ne može sačuvati tajne.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (28, 8, 18, 'Ne pokazuj tajne pred tuđinom, jer ne znaš što će se izleći.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (28, 8, 19, 'Ne otkrivaj svoga srca svakom čovjeku i ne očekuj dobra od svakoga.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (28, 9, 1, 'Ne budi ljubomoran na svoju ljubljenu ženu i ne uči je pakosti na svoju štetu.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (28, 9, 2, 'Ne prepuštaj se posve ženi, da ona potpuno ne zavlada tobom.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (28, 9, 3, 'Ne približuj se bludnici, da ne padneš u zamke njezine.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (28, 9, 4, 'Ne druži se s pjevačicom, da te ne smete umijećem svojim.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (28, 9, 5, 'Ne upiri pogled u djevicu, da ne bi bio kažnjen zajedno s njom.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (28, 9, 6, 'Ne daj bludnici svoje duše, da ne izgubiš imetak svoj.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (28, 9, 7, 'Ne obziri se po gradskim ulicama i ne skitaj se pustim zakucima.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (28, 9, 8, 'Odvrati pogled svoj od ljupke žene i ne gledaj tuđu ljepotu. Mnoge već zavede ženina ljepota, koja želju raspaljuje kao vatru.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (28, 9, 9, 'Ne sjedaj nikad s udatom ženom i zajedno s njom ne pij vina, da ti srce ne podlegne njezinim dražima i da u strasti svojoj ne srneš u propast.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (28, 9, 10, 'Ne odbacuj starog prijatelja, jer mu novi neće biti jednak. Nov prijatelj, vino novo; kad ostari, piješ ga s užitkom.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (28, 9, 11, 'Ne zavidi grešniku na uspjehu, jer ne znaš kakav će mu kraj biti.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (28, 9, 12, 'Ne naslađuj se onim čime i bezbožnici; sjeti se da im sreća neće trajati do Podzemlja.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (28, 9, 13, 'Drži se daleko od čovjeka koji je kadar ubiti, i neće te progoniti strah od smrti. Ako mu se približiš, dobro se pazi da te ne liši života. Znaj da među zamkama hodiš i kročiš po kruništu zidina gradskih.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (28, 9, 14, 'Koliko možeš, druži se sa svojim bližnjim i savjetuj se s mudracima.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (28, 9, 15, 'Za razgovor traži razborite ljude, i tvoje riječi nek\' su po Zakonu Svevišnjeg.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (28, 9, 16, 'Jedi kruh svoj s pravednicima i u strahu Gospodnjem neka je tvoj ponos.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (28, 9, 17, 'Djelo vještih ruku zaslužuje hvalu, a knez naroda mora biti vičan govoru.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (28, 9, 18, 'Užas je gradu čovjek jezičav, a brbljavac je omražen.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (28, 10, 1, 'Mudar vladar odgaja svoj narod u stezi, i uredna je vlada razborita čovjeka.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (28, 10, 2, 'Kakav je vladar, takvi su i činovnici; i kakav je gradski upravitelj, takvi mu i građani.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (28, 10, 3, 'Neobuzdan kralj upropašćuje svoj narod, a svoj napredak duguje grad razboritosti vladara.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (28, 10, 4, 'Vlast nad zemljom u rukama je Gospodnjim: Gospod joj u pravo vrijeme postavlja pravog čovjeka.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (28, 10, 5, 'Uspjeh je čovjekov u Božjoj ruci, i zakonodavcu Bog daruje čast.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (28, 10, 6, 'Ne budi kivan na svoga bližnjeg ni zbog kakve nepravde i ne čini ništa nepravedno.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (28, 10, 7, 'Mrska je oholost i Gospodu i čovjeku, a nepravda je odvratna obojici.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (28, 10, 8, 'Vlast prelazi od jednog naroda drugomu zbog nepravde, nasilja i novca.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (28, 10, 9, 'Što se toliko oholi prah i pepeo - kad već za života ima crvljiva crijeva?');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (28, 10, 10, 'Duga bolest srdi liječnika; tko je danas kralj, sutra umire.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (28, 10, 11, 'Kad čovjek umre, baštini gnjilež, grabežljive zvijeri i crve.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (28, 10, 12, 'Oholost počinje kad čovjek otpadne od Gospoda i srcem se odmetne od svoga Stvoritelja.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (28, 10, 13, 'I jer je početak oholosti grijeh, tko se njoj oda, širi gnusobu. Gospod ih zbog toga kažnjava čudesnim kaznama i potpuno uništava.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (28, 10, 14, 'Gospod je srušio prijestolja silnika i potlačene posadio na mjesto njihovo.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (28, 10, 15, 'Gospod je iskorijenio oholice i posadio ponizne na mjesto njihovo.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (28, 10, 16, 'Gospod je porazio zemlje poganske i razorio ih do samog temelja.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (28, 10, 17, 'Neke je od njih odveo i uništio i zbrisao njihov spomen s lica zemlje.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (28, 10, 18, 'Oholost nije stvorena za čovjeka, ni srdžba bijesna za rod ženin.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (28, 10, 19, 'Koji je rod dostojan časti? Ljudski rod. Koji je rod dostojan časti? Onaj koji se boji Gospoda. Koji rod prezir zaslužuje? Ljudski rod. Koji rod prezir zaslužuje? Onaj koji krši Zakon.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (28, 10, 20, 'Među braćom je glavar dostojan časti; koji se Gospoda boje, u časti su pred njim.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (28, 10, 21, '#');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (28, 10, 22, 'Nek\' se bogat, plemenit i siromah ponose strahom Gospodnjim.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (28, 10, 23, 'Ne valja prezirati razborita siromaha niti častiti grešnika.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (28, 10, 24, 'Poglavar, vladar i moćnik dostojni su časti, ali nema većeg od onog koji se boji Gospoda.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (28, 10, 25, 'Mudru robu služe slobodnjaci, i razborit se čovjek ne tuži.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (28, 10, 26, 'Odviše ne mudruj radeći svoj posao i ne hvastaj se kad si u stisci.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (28, 10, 27, 'Bolji je koji radi i živi u izobilju nego tko se hvasta a nema od čega živjeti.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (28, 10, 28, 'Sine, poniznošću časti samog sebe i cijeni sebe svojom pravom cijenom.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (28, 10, 29, 'Tko će opravdati onoga tko sam sebi nepravdu nanosi i častiti onoga koji samog sebe prezire?');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (28, 10, 30, 'Siromaha časte zbog njegova razuma i bogataša zbog njegova bogatstva.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (28, 10, 31, 'Koga časte u siromaštvu njegovu, koliko više u bogatstvu! Koga preziru u bogatstvu, koliko još više u siromaštvu!');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (28, 11, 1, 'Mudrost uzvisuje glavu siromahu i posađuje ga među knezove.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (28, 11, 2, 'Ne hvali čovjeka po obličju njegovu i ne preziri nikoga zbog njegova izgleda.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (28, 11, 3, 'Malena je pčela među stvorovima krilatim, ali ona daje slast najslađu.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (28, 11, 4, 'Ne uznosi se zbog odjeće koju nosiš niti se uznosi zbog svojih počasti; jer čudesna su djela Gospodnja, iako su skrivena ljudima.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (28, 11, 5, 'Često su kraljevi sjedili na tlima, a neznanac je stekao krunu.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (28, 11, 6, 'I često su moćnici bili jako poniženi i odličnici potpali pod tuđu vlast.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (28, 11, 7, 'Ne optužuj prije nego što istražiš, prvo promisli, pa onda ukori.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (28, 11, 8, 'Ne odgovaraj prije nego si čuo i ne miješaj se usred govora.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (28, 11, 9, 'Ne prepiri se o onome što te se ne tiče i ne miješaj se u svađu grešnika.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (28, 11, 10, 'Sine moj, ne preuzimaj previše poslova; ako ih umnožiš, nećeš proći bez kazne; ma koliko se žurio, nećeš stići, niti ćeš trkom uteći.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (28, 11, 11, 'Čovjek se trudi, muči i hiti, da bi još više zaostao.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (28, 11, 12, 'Postoji slab čovjek koji moli pomoć, bez snage i pun nevolje, ali ga Gospod milostivo gleda i podiže iz njegove bijede.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (28, 11, 13, 'Uzdiže glavu njegovu i mnogi mu se dive.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (28, 11, 14, 'Dobro i zlo, život i smrt, siromaštvo i bogatstvo - sve dolazi od Gospoda.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (28, 11, 15, '#');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (28, 11, 16, '#');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (28, 11, 17, 'Dar Gospodnji ostaje u pobožnika, i naklonost će ih Gospodnja dovijeka pratiti.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (28, 11, 18, 'Ima ih koji se obogate pomnjom i škrtošću, i evo što im je plaća:');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (28, 11, 19, 'dođe dan kad kažu: \"Nađoh mir, i sad ću uživati svoja dobra\", ali ne znaju koliko će trajati: morat će dobra svoja ostaviti drugom i umrijeti.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (28, 11, 20, 'Ustraj u dužnosti svojoj, i neka ti je mila, i u svojem radu ostari.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (28, 11, 21, 'Ne čudi se djelima grešnikovim; uzdaj se u Gospoda i ustraj u svom poslu, jer tako je lako Gospodu iznenada i začas obogatiti siromaha.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (28, 11, 22, 'Blagoslov je Gospodnji plaća pobožniku: brzo se rastvara cvijet blagoslova.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (28, 11, 23, 'Ne reci: \"Što mi još treba? I kakav me probitak čeka?\"');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (28, 11, 24, 'Ne reci: \"Imam svega dosta, kakvo me odsad zlo može zadesiti?\"');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (28, 11, 25, 'U vrijeme dobra zlo se zaboravlja, i u vrijeme nesreće ne pamti se sreća.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (28, 11, 26, 'Jer Gospodu je lako u dan smrtni platiti čovjeku prema činima njegovim.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (28, 11, 27, 'U vrijeme nevolje naslade se zaboravljaju, u posljednjem času otkrivaju se djela čovjekova.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (28, 11, 28, 'Prije smrti ne zovi nikoga sretnim, jer se tek na svom koncu spoznaje čovjek.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (28, 11, 29, 'Ne uvodi svakoga čovjeka u kuću svoju, jer mnogovrsne su u spletkara zamke.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (28, 11, 30, 'Srce je oholičino jarebica-mamljivica u krletki, i kao uhoda vreba on tvoju propast.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (28, 11, 31, 'Klevetnik izvrće dobro u zlo i baca ljagu na samu krepost.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (28, 11, 32, 'Od jedne iskre nastaje ognjište puno žara, a grešnik vreba da prolije krv.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (28, 11, 33, 'Čuvaj se opakoga, jer on zlo snuje, da ti ne nanese vječnu sramotu.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (28, 11, 34, 'Uvedi tuđinca u kuću, i on će donijeti nevolju i otuđiti te od tvojih.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (28, 12, 1, 'Kad činiš dobro, pazi komu činiš, i tvoja dobročinstva neće biti uzalud.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (28, 12, 2, 'Čini dobro pobožnu, i on će ti uzvratiti, a ako ne on, onda Svevišnji.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (28, 12, 3, 'Nikakvo dobro ne dolazi čovjeku u zlu ustrajnu, i koji odbija da dijeli milodare.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (28, 12, 4, 'Podaj pobožniku i ne pomaži grešniku.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (28, 12, 5, 'Učini dobro poniznu i ne daj ništa bezbožnu. Uskrati mu kruh, ne daj mu ga, da ga to ne učini jačim od tebe; jer će ti platiti dvostrukom opačinom za sve dobro što si mu učinio.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (28, 12, 6, 'Jer Svevišnji prezire grešnike i osvetit će se bezbožnicima.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (28, 12, 7, 'Daruj dobromu, a uskrati pomoć grešniku.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (28, 12, 8, 'Prijatelj se ne poznaje u sreći, a neprijatelj se ne može sakriti u nesreći.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (28, 12, 9, 'Kad je čovjek sretan, i neprijatelj mu je prijatelj, a kad je nesretan, i prijatelj ga se kloni.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (28, 12, 10, 'Nikad ne vjeruj neprijatelju, jer zloća je njegova kao kovina što rđa.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (28, 12, 11, 'Pa i ako ide ponizno i pogureno, jako se pazi i ne vjeruj mu. Budi prema njemu kao onaj koji uglačava zrcalo, i vidjet ćeš da rđa njegova nije posve iščezla.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (28, 12, 12, 'Ne meći ga kraj sebe, da te ne istisne i zauzme tvoje mjesto. Ne posađuj ga zdesna sebi: on će nastojati da ti preotme sjedište, i na kraju ćeš shvatiti moje riječi i pokajat\' se zbog moje opomene.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (28, 12, 13, 'Tko će žaliti zmijara koga je zmija ujela i one koji se približuju divljim zvijerima?');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (28, 12, 14, 'Tako i onoga tko se druži s grešnikom i sudionik je u njegovim grijesima.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (28, 12, 15, 'Dok ti čvrsto stojiš, on se ne otkriva, ali kad jednom posrneš, on će navaliti.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (28, 12, 16, 'Usnama je svojim sladak neprijatelj, ali u srcu smišlja da te u jamu baci. U očima neprijatelju mogu biti suze, a kad mu se pruži prilika, ni krv ga neće zadovoljiti.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (28, 12, 17, 'Ako li te gdje stigne zlo, on je tu već prije tebe, i kao da pomaže, podmeće ti nogu.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (28, 12, 18, 'On će mahati glavom i pljeskati rukama, mnogo će mrmljati i razvlačiti lice.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (28, 13, 1, 'Tko smolu dira, ulijepi se, i tko se druži s oholicom, postaje kao i on.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (28, 13, 2, 'Ne diži ono što ti je preteško i ne druži se s jačim i bogatijim od sebe. Zašto staviti zajedno zemljani lonac s bakrenim? Kad ga ovaj udari, onaj se razbije.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (28, 13, 3, 'Bogataš počini zlo i još se razmeće; siromahu se čini zlo, a on još za milost moli.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (28, 13, 4, 'Ako si mu na korist, on će te iskoristiti; a kad iznemogneš, ostavlja te.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (28, 13, 5, 'Dok imaš štogod, živjet će s tobom i oplijeniti te bez ikakve grižnje savjesti.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (28, 13, 6, 'Ako mu trebaš, on ti laska; smiješi ti se i daje ti nadu. Govori ti lijepo i pita: \"Što ti treba?\" I postidjet će te svojim svečanim objedima,');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (28, 13, 7, 'dok te ne oplijeni dva i tri puta i na kraju te ismije. Kad te poslije vidi, prezire te i maše glavom nad tobom.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (28, 13, 8, 'Čuvaj se da te ne zavedu, da te ne ponizi ludost tvoja.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (28, 13, 9, 'Pozove li te velikaš, suzdrži se, i on će te još upornije pozivati.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (28, 13, 10, 'Ne nameći se, da ne budeš odbačen, a ne udaljuj se, da ne budeš zaboravljen.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (28, 13, 11, 'Ne postupaj s njim kao s jednakim i ne vjeruj njegovoj rječitosti, jer te kuša riječima svojim i, kao u šali, on te procjenjuje.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (28, 13, 12, 'Nemilosrdan je čovjek preslobodan u riječima, taj te neće poštedjeti ni udaraca ni okova.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (28, 13, 13, 'Čuvaj se i budi pozoran, jer hodiš sa svojom propašću.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (28, 13, 14, '#');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (28, 13, 15, 'Svako živo biće ljubi svoju vrstu i svaki čovjek svojega bližnjeg.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (28, 13, 16, 'Svaki stvor drži se svoga roda, i čovjek se drži sebi sličnih.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (28, 13, 17, 'Zar se družiti mogu vuk i janje? Tako i grešnik s pobožnikom.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (28, 13, 18, 'Može li biti mira između hijene i psa? I mira između bogataša i siromaha?');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (28, 13, 19, 'Divlji su magarci plijen lavovima pustinjskim, a siromasi bogatašima.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (28, 13, 20, 'Odvratna je poniznost oholici i ogavan je bogatašu siromah.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (28, 13, 21, 'Kad bogataš posrne, podupru ga prijatelji, a kad siromah posrne, prijatelji ga odbacuju.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (28, 13, 22, 'Kad se bogataš spotakne, mnoge ga ruke dočekuju; ako i gluposti govori, čestitaju mu. Spotakne li se siromah, odmah ga ukore, pa ako govori i razborito, ipak mu nema mjesta.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (28, 13, 23, 'Kad govori bogataš, svi šute, i uzdižu zatim njegov govor do oblaka; govori li siromah, tad se pitaju: \"Tko je ovaj?\" i ako posrne, još ga gurnu.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (28, 13, 24, 'Dobro je bogatstvo, ako je bez grijeha, a zlo je siromaštvo, kažu bezbožnici.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (28, 13, 25, 'Srce mijenja lik čovjeku, bilo na dobro bilo na zlo.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (28, 13, 26, 'Vedro je lice znak vesela srca; a mučan je posao smišljati izreke.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (28, 14, 1, 'Blago čovjeku koji nije zgriješio riječima i koga ne muči grižnja zbog grijeha.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (28, 14, 2, 'Blago čovjeku koga ne optužuje vlastita savjest i koji se nije odrekao nade.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (28, 14, 3, 'Tvrdici ne priliči bogatstvo, i čemu veliko blago pohlepniku?');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (28, 14, 4, 'Tko uskraćuje sebi sabire drugomu, i tuđinci će se naslađivati dobrima njegovim.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (28, 14, 5, 'Tko je tvrd prema sebi, komu će biti dobar? Takav ne uživa ni u vlastitom dobru.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (28, 14, 6, 'Nema okrutnijeg od onoga tko muči samog sebe: to mu je plaća za vlastitu zloću.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (28, 14, 7, 'Pa ako i čini dobro, čini nenamjerno i na koncu otkriva svoju zloću.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (28, 14, 8, 'Zavidljivac je opak: on odvraća pogled i prezire tuđi život.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (28, 14, 9, 'Premalen je oku lakomu vlastiti dio, pohlepa isušuje dušu.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (28, 14, 10, 'Tvrdičino oko hlepi za kruhom i glad je za njegovim stolom.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (28, 14, 11, 'Sine moj, imaš li štogod, priušti sebi i prinesi Gospodu dostojne žrtve.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (28, 14, 12, 'Ne zaboravi da smrt neće oklijevati i da ti nije objavljen ugovor Podzemlja.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (28, 14, 13, 'Prije nego umreš, čini dobro prijatelju, i pruži, daj mu koliko možeš.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (28, 14, 14, 'Ne uskraćuj sebi sadašnje sreće i ne daj da ti izmakne dio dopuštena užitka.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (28, 14, 15, 'Nećeš li ostaviti blago svoje drugomu i neće li zaslužba tvoja biti ždrijebom razdijeljena?');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (28, 14, 16, 'Podari i primi i okusi užitka, jer se u Podzemlju radost ne traži.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (28, 14, 17, 'Sve se živo troši kao i odjeća, i vječna je uredba: valja umrijeti.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (28, 14, 18, 'Kao lišće što raste na bujnu drvetu te jedno opada a drugo niče, tako i naraštaji od krvi i mesa: jedni umiru, a drugi se rađaju.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (28, 14, 19, 'I svako prolazno djelo propada, a zajedno s njim i njegov tvorac.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (28, 14, 20, 'Blago čovjeku koji razmišlja o mudrosti i umuje razborito,');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (28, 14, 21, 'koji u srcu svojem proučava njezine putove i posvećuje se u njezine tajne.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (28, 14, 22, 'On je progoni kao lovac i vreba je kraj staze njezine;');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (28, 14, 23, 'on viri kroz prozor njezin i prisluškuje na vratima njezinim;');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (28, 14, 24, 'postavlja se blizu kuće njezine i udara klin svoj u njezin zid;');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (28, 14, 25, 'podiže svoj šator kraj nje i nastanjuje se u sretnu počivalištu;');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (28, 14, 26, 'on stavlja djecu svoju pod njezinu zaštitu i boravi pod granjem njezinim;');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (28, 14, 27, 'on nalazi okrilje od žege pod sjenom njezinom i prebiva u divoti njezinoj.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (28, 15, 1, 'Tako čini tko se boji Gospoda; i tko se drži zakona steći će mudrost.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (28, 15, 2, 'Ona mu dolazi u susret kao majka i dočekuje ga kao nevjesta djevica.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (28, 15, 3, 'Ona ga hrani kruhom razboritosti i poji ga vodom mudrosti.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (28, 15, 4, 'On se oslanja na nju i ne posrće; uzda se u nju i ne sramoti se.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (28, 15, 5, 'Ona ga uzvisuje nad bližnjega njegova i sred zbora usta mu otvara.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (28, 15, 6, 'On nalazi veselje i vijenac radosti i baštini ime vječno.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (28, 15, 7, 'Nerazumnici je nikad ne dobivaju niti je grešnici očima gledaju.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (28, 15, 8, 'Ona je daleko od oholice i lažljivcima ne dolazi na um.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (28, 15, 9, 'Ne priliči hvalospjev ustima grešnikovim jer mu ga Gospod nije dao.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (28, 15, 10, 'Iz usta mudračevih nek\' odjekuje hvalospjev, i tada sam Gospod njime upravlja.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (28, 15, 11, 'Ne reci: \"Od Boga je grijeh moj\", jer što on mrzi, nikad ne čini.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (28, 15, 12, 'I ne reci: \"On me zavede\", jer njemu grešnici ne trebaju.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (28, 15, 13, 'Gospod mrzi svaku gnusobu, a mrzi je i svaki onaj tko se njega boji.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (28, 15, 14, 'On je sam u početku stvorio čovjeka i prepustio ga slobodnoj volji njegovoj.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (28, 15, 15, 'Ako hoćeš, možeš držati zapovijedi, u tvojoj je moći da budeš vjeran.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (28, 15, 16, 'On je preda te stavio vatru i vodu: za čim hoćeš pruži ruku svoju.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (28, 15, 17, 'Pred čovjekom je i život i smrt: što on više voli to će mu se dati.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (28, 15, 18, 'Jer velika je mudrost u Gospoda, on je svemoćan i vidi sve.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (28, 15, 19, 'Oči Gospodnje počivaju na onima koji ga se boje, Gospod zna svako djelo čovječje.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (28, 15, 20, 'Nije nikad zapovjedio nikomu da bude bezbožnik niti dao dopuštenje za grijeh.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (28, 16, 1, 'Ne želi mnoštva nevrijedne djece i ne raduj se bezbožnim sinovima.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (28, 16, 2, 'Ma koliko ih bilo, ne veseli se njima ako nema u njih straha Gospodnjeg.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (28, 16, 3, 'Ne računaj na njihov dug život i ne pouzdaj se u njihovu sudbinu, jer više vrijedi jedan nego tisuću i umrijeti bez djece bolje je nego imati potomke bezbožnike.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (28, 16, 4, 'Jer jedan razborit čovjek napuči grad, a rod zlikovaca razori ga.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (28, 16, 5, 'Mnogo je sličnoga vidjelo oko moje, a još više slušalo uho moje.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (28, 16, 6, 'U zboru grešničkom zapalio se oganj i u puku buntovnom raspalio se gnjev.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (28, 16, 7, 'Bog nije oprostio divovima u staro doba kad se pobuniše pouzdavši se u svoju moć.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (28, 16, 8, 'Nije poštedio sugrađana Lotovih: njih se gnušao zbog oholosti njihove.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (28, 16, 9, 'Nije poštedio ni puka prokletoga: oni bijahu iskorijenjeni zbog grijeha svojih.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (28, 16, 10, 'Ni šest stotina tisuća pješaka, koji propadoše zbog tvrdoće srca svojeg.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (28, 16, 11, 'Pa kad bi postojao i samo jedan tvrdoglavac, bilo bi čudo ako bi ostao bez kazne, jer i milosrđe i gnjev pripadaju Gospodu, koji može u svojoj moći oprostiti i srdžbu iskaliti.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (28, 16, 12, 'Kao što mu je milosrđe veliko, tako mu je velika i strogost; on ljudima sudi po djelima njihovim.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (28, 16, 13, 'Bez kazne mu ne može uteći grešnik s plijenom, niti je uzalud strpljivost pobožnika.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (28, 16, 14, 'Širok je put njegove milosti, ali svatko dobiva prema djelima svojim.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (28, 16, 15, '#');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (28, 16, 16, '#');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (28, 16, 17, 'Ne reci: \"Sakrit ću se od Boga; tko će misliti na mene gore u visini? Među tolikim mnoštvom neće me prepoznati; što sam ja u neizmjernom stvaranju?\"');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (28, 16, 18, 'Gle: nebo i nebesa nad nebesima, bezdan i zemlja, zadrhte kad ih Gospod pohodi.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (28, 16, 19, 'Gorski vrhunci i temelji zemaljski istodobno se tresu kad na njih pogleda.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (28, 16, 20, 'Ali na sve to tko će misliti? I tko da shvati putove njegove?');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (28, 16, 21, 'Ima i oluja koje nitko ne vidi, skrivena je većina njegovih djela.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (28, 16, 22, '\"Pravedna djela tko će objaviti? I tko ih očekuje? Jer ugovor je daleko.\"');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (28, 16, 23, 'Tako misli čovjek kratke pameti, bez razbora, omamljen svojim tlapnjama.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (28, 16, 24, 'Slušaj, sine moj, i steći ćeš spoznaju; upravi svoje srce riječima mojim.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (28, 16, 25, 'Odmjereno ću ti objasniti stegu i pomno izložiti znanje.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (28, 16, 26, 'Bog u početku stvori djela svoja i dodijeli nakon stvaranja svakomu mjesto.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (28, 16, 27, 'Uredio je djela svoja za sva vremena, od njihovih početaka do njihove daleke budućnosti: niti gladuju, niti se trude, niti ikad napuštaju svoje dužnosti.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (28, 16, 28, 'Nijedno od njih svoga bližnjega ne tlači i nikad ne krši njegove zapovijedi.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (28, 16, 29, 'A poslije Gospod pogleda na zemlju i napuni je svojim dobrima.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (28, 16, 30, 'Pokri joj površje svakojakim životinjama i sve se opet vraća njoj.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (28, 17, 1, 'Gospod stvori čovjeka od zemlje i opet ga u nju vraća.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (28, 17, 2, 'Dao je ljudima točan broj dana i određeno vrijeme, dade im i vlast nad svime što je na zemlji.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (28, 17, 3, 'Odjenu ih snagom kakva je njegova i stvori ih na sliku svoju.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (28, 17, 4, 'Svakom je stvoru udahnuo strah od čovjeka, da bi on gospodario zvijerima i pticama.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (28, 17, 5, '#');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (28, 17, 6, 'Oblikovao im jezik, oči, uši, i srce im dade da razmišljaju.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (28, 17, 7, 'Napuni ih znanjem i razumijevanjem i otkri im dobro i zlo.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (28, 17, 8, 'Oči je svoje stavio u srca njihova da im pokaže veličanstvo djela svojih.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (28, 17, 9, '#');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (28, 17, 10, 'Oni će slaviti njegovo sveto ime, pričajući o veličanstvu djela njegovih.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (28, 17, 11, 'Još im umnoži znanje i obdari ih zakonom života.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (28, 17, 12, 'Učini s njima Savez vječni i pouči ih sudovima svojim.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (28, 17, 13, 'Oči su njihove gledale slavu veličanstvenu i uho slušalo slavni njegov glas.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (28, 17, 14, '\"Čuvajte se svakoga zla\", reče im i odredi im dužnosti prema bližnjemu.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (28, 17, 15, 'Njihovi su putovi uvijek pred njim, ne mogu se sakriti pred očima njegovim.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (28, 17, 16, '#');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (28, 17, 17, 'Svakomu narodu postavi vladara, ali je Izrael baština Gospodnja.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (28, 17, 18, '#');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (28, 17, 19, 'Sva su djela njihova pred njim kao sunce, i oči njegove svagda paze na putove njihove.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (28, 17, 20, 'Ne mogu se pred njim sakriti nepravde njihove, pred Gospodom su svi grijesi njihovi.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (28, 17, 21, '#');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (28, 17, 22, 'Milostinja čovjekova njemu je kao pečat, i na dobročinstvo pazi kao na zjenicu oka.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (28, 17, 23, 'Jednoga će se dana dići i platiti im, svakomu će plaća pasti na vlastitu glavu.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (28, 17, 24, 'Samo pokajnicima dopušta povratak i tješi one koji su izgubili nadu.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (28, 17, 25, 'Obrati se Gospodu i okani se grijeha, moli se pred licem njegovim i prestani ga vrijeđati.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (28, 17, 26, 'Vrati se Višnjem i okani se nepravde i jako zamrzi na gnusan čin.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (28, 17, 27, 'Jer tko će hvaliti Svevišnjeg u Podzemlju mjesto živih koji ga mogu slaviti?');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (28, 17, 28, 'Hvala mrtvih mrtva je - kao da ih nema, samo živ i zdrav hvali Gospodina.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (28, 17, 29, 'O kako je veliko milosrđe u Gospoda, praštanje onima koji mu se obraćaju!');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (28, 17, 30, 'Ljudi ne mogu sve, jer sin čovjekov nije besmrtan.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (28, 17, 31, 'Što je svjetlije od sunca? Pa i ono pomrkne. Tijelo i krv mogu hraniti samo zloću.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (28, 17, 32, 'Gospod nadzire sile na visokim nebesima, a svi su ljudi samo prah i pepeo.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (28, 18, 1, 'Onaj koji živi uvijek stvorio je svemir.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (28, 18, 2, 'Jedini je Gospod pravedan!');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (28, 18, 3, '#');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (28, 18, 4, 'Komu on dade moć da iskaže djela njegova i tko će iscrpsti čudesa njegova?');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (28, 18, 5, 'Tko može izmjeriti moć veličanstva njegova i tko ispričati dokaze milosti njegovih?');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (28, 18, 6, 'Niti im se može štogod oduzeti niti dodati, niti se mogu iscrpsti čudesa Gospodnja.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (28, 18, 7, 'Kad čovjek završi, tek je započeo, i kad prestane, zbunjen je kao i uvijek.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (28, 18, 8, 'Što je čovjek? Ili čemu služi? Što je njegovo dobro, a što njegovo zlo?');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (28, 18, 9, 'Trajnost života njegova? Sto godina vrlo je dugo.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (28, 18, 10, 'A prema vječnosti te su godine kao kap morske vode ili zrno pijeska.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (28, 18, 11, 'Zbog toga je Gospod strpljiv s ljudima i obasipa ih svojim milosrđem.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (28, 18, 12, 'On vidi i zna kako je bijedan njihov kraj i zato je umnožio praštanje svoje.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (28, 18, 13, 'Sućut je čovjekova za bližnjega njegova, a sućut je Gospodnja za sve živo: Gospod ih kori, odgaja i poučava te vraća kao pastir stado svoje.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (28, 18, 14, 'On je milostiv onima koji se stege drže i koji su revni u naredbama njegovim.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (28, 18, 15, 'Sine, dobročinstva ne popraćuj ukorom niti darove ujedljivim riječima.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (28, 18, 16, 'Ne ublažava li rosa žegu? Tako je i riječ dragocjenija od milodara.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (28, 18, 17, 'I mislim, nije li riječ bolja od dara? A oboje se nalazi u čovjeka puna milosti.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (28, 18, 18, 'Luđak ne daje ništa i grdi, a zavidnikov dar peče oči.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (28, 18, 19, 'Promisli prije nego prozboriš, traži lijeka prije bolesti.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (28, 18, 20, 'Prosudi samog sebe prije nego sudiš, pa ćeš naći oprosta u čas Božjeg pohoda.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (28, 18, 21, 'Ponizi se prije nego se razboliš, i kad si pogriješio, pokaj se.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (28, 18, 22, 'Ne oklijevaj ispuniti zavjet na vrijeme i ne čekaj smrt da bi postupio pravedno.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (28, 18, 23, 'Pripravi se prije svoga zavjeta i ne budi kao čovjek koji iskušava Gospodina.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (28, 18, 24, 'Misli na srdžbu posljednjih dana i na čas osvetni kad Bog odvrati lice svoje.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (28, 18, 25, 'Misli na glad u vrijeme obilja i na siromaštvo i oskudnost u dane bogatstva.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (28, 18, 26, 'Vrijeme se mijenja od jutra do večeri i sve brzo prolazi pred Gospodinom.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (28, 18, 27, 'Mudrac je oprezan u svemu i u grešnim se danima čuva prijestupa.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (28, 18, 28, 'Svaki koji je razuman prepoznaje mudrost i poštovat će onoga tko je steče.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (28, 18, 29, 'Koji shvaćaju mudre besjede sami postaju mudri i obasipaju kišom prikladnih izreka.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (28, 18, 30, 'Ne idi za svojim strastima, kroti svoje požude.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (28, 18, 31, 'Ako zadovoljiš svoju dušu požudom, načinit ćeš od sebe ruglo neprijateljima.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (28, 18, 32, 'Ne upuštaj se u raskošan život, ne miješaj se u takvo društvo.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (28, 18, 33, 'Nemoj da osiromašiš gosteći se pozajmljenim novcem kad ništa nemaš u tobolcu svojem.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (28, 19, 1, 'Radnik pijanica nikad se neće obogatiti, i tko prezire male stvari, brzo osiromaši.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (28, 19, 2, 'Vino i žene izopače razborite ljude, i tko se druži s bludnicama izgubi svaki stid.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (28, 19, 3, 'Bit će plijenom ličinkama i crvima i drznik će izgubiti život svoj.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (28, 19, 4, 'Tko se brzo povjerava lakomislen je, a tko griješi sam sebi naudi.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (28, 19, 5, 'Tko uživa u zlu bit će kažnjen.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (28, 19, 6, 'A tko mrzi brbljanje uklanja od sebe zloću.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (28, 19, 7, 'Ne raznosi ono što ti je povjereno i nitko ti neće nauditi.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (28, 19, 8, 'Ne povjeravaj ni neprijatelju ni prijatelju; ako ti nije grijeh, ne otkrivaj!');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (28, 19, 9, 'Jer čuje li tko, čuvat će se tebe i u svoje vrijeme osjetit ćeš njegov prezir.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (28, 19, 10, 'Ako si čuo štogod, budi kao grob. Ne boj se! Neće te raskinuti.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (28, 19, 11, 'Kad nešto čuje, luđaka spopadaju trudovi kao porodilju u porodu.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (28, 19, 12, 'Kao strijela zabodena u bedro, takva je riječ u nutrini luđakovoj.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (28, 19, 13, 'Ispitaj svoga prijatelja: možda nije ništa učinio, pa ako je štogod učinio, da ne učini više.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (28, 19, 14, 'Ispitaj svojega susjeda: možda nije ništa rekao, ili ako je rekao, neće ponovo reći.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (28, 19, 15, 'Ispitaj svojega prijatelja, jer česta je kleveta i ne vjeruj svemu što čuješ.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (28, 19, 16, 'Čovjeku se štogod omakne, ali bez zle namjere, i tko nije sagriješio jezikom svojim?');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (28, 19, 17, 'Ispitaj susjeda svojeg prije nego što zaprijetiš i poslušaj zakon Svevišnjeg.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (28, 19, 18, '#');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (28, 19, 19, '#');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (28, 19, 20, 'Sva je mudrost u strahu Gospodnjem, i u svoj je mudrosti poštivanje Zakona.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (28, 19, 21, '#');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (28, 19, 22, 'Ali mudrost nije u spoznaji zloće, i razbora nema u savjetu grešnika.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (28, 19, 23, 'Postoji umješnost koja je gnusna, i luđak je komu mudrosti nedostaje.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (28, 19, 24, 'Bolje je biti razborom siromašan ali bogobojazan nego biti bogat razborom a kršiti Zakon.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (28, 19, 25, 'Postoji lukava umješnost u službi nepravde: poslužit će se i prijevarom u svoju korist.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (28, 19, 26, 'Postoji čovjek koji hodi pognut i tužan, ali je iznutra pun podmuklosti.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (28, 19, 27, 'Takav obara lice i pričinja se gluh, ali će te podmuklo napasti.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (28, 19, 28, 'Ako i propusti grijeh zbog nemoći, čim se pruži prilika, učinit će zlo.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (28, 19, 29, 'Čovjek se poznaje po liku svojem, umnik se prepoznaje po licu.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (28, 19, 30, 'Odijelo čovjekovo govori što on čini, a korak njegov otkriva kakav je.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (28, 20, 1, 'Ima prijekor koji nije zgodan, i ima tko prešuti, i taj je razuman.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (28, 20, 2, 'Ali bolje je koriti nego se gnjeviti,');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (28, 20, 3, 'i tko priznaje uklanja se poniženju.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (28, 20, 4, 'Kao uškopljenik koji hoće razdjevičiti djevicu, takav je onaj tko hoće pravdu provesti nasiljem.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (28, 20, 5, 'Ima tko šuti, pa se smatra mudrim, a drugoga mrze zbog brbljanja.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (28, 20, 6, 'Ima tko šuti jer ne zna odgovoriti; drugi šuti jer čeka pravi čas.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (28, 20, 7, 'Mudar čovjek šuti do zgodnog časa, a luđak i brbljavac propuštaju zgodu.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (28, 20, 8, 'Tko odviše govori postaje odvratan, a tko je odviše slobodan postaje mrzak.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (28, 20, 9, 'Netko u nesreći nalazi sreću, a gdjekoji dobitak postaje gubitak.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (28, 20, 10, 'Ima dar koji ti ništa ne koristi i dar koji se dvostruko isplaćuje.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (28, 20, 11, 'Ima slave koja vodi poniženju, a ima ljudi koji iz poniženja podignu glavu.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (28, 20, 12, 'Netko kupi mnogo za malo novaca, a ipak plati sedmerostruko.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (28, 20, 13, 'Mudrac stekne naklonost svojim riječima, dok luđaci prosipaju laske uzalud.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (28, 20, 14, 'Bezumnikov dar ništa ti ne koristi, jer njegove oči traže sedmerostruk uzvrat;');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (28, 20, 15, 'on malo daje, a mnogo predbacuje, i kazuje na sva usta kao razglasitelj; danas daje u zajam, a sutra traži natrag: mrzak je takav čovjek.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (28, 20, 16, 'Luđak veli: \"Nemam prijatelja i ne primam zahvalnosti za svoja dobročinstva.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (28, 20, 17, 'Zlobna su jezika svi koji jedu moj kruh.\" Koliko puta i koliki izruguju takvoga!');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (28, 20, 18, 'Bolje je pokliznuti se na cesti nego na jeziku: tako opakima propast iznenada dolazi.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (28, 20, 19, 'Čovjek neugodan - neumjesna je priča razvučena na ustima neodgojenih.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (28, 20, 20, 'Mudra izreka ne vrijedi u ustima luda čovjeka, jer je ne kazuje u pravo vrijeme.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (28, 20, 21, 'Gdjekoga siromaštvo čuva od grijeha: njegova spokoja ne remeti grižnja savjesti.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (28, 20, 22, 'Mnogi sebi uništi život zbog lažna stida i upropasti se zbog luđakova mnijenja.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (28, 20, 23, 'Netko zbog stida obeća štogod prijatelju i učini ga bez potrebe neprijateljem.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (28, 20, 24, 'Gnusna je ljaga na čovjeku laž i uvijek je u ustima ljudi neukih.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (28, 20, 25, 'Bolji je i tat nego onaj tko uvijek laže, a oba će baštiniti propast.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (28, 20, 26, 'Laganje je sramotan običaj, i sramota lažljivčeva ostaje vječno s njim.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (28, 20, 27, 'Mudar čovjek stječe ugled, i umnik je mio velikašima.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (28, 20, 28, 'Tko obrađuje zemlju žanje obilnu žetvu, i tko znade ugoditi velikašima prašta mu se nepravda.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (28, 20, 29, 'Darovi i pokloni zasljepljuju oči mudracima i kao brnjica na ustima zaustavljaju ukore.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (28, 20, 30, 'Skrivena mudrost i neotkriveno blago, kakva korist od toga oboga?');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (28, 20, 31, 'Bolji je čovjek koji krije ludost svoju nego čovjek koji krije svoju mudrost.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (28, 20, 32, '');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (28, 21, 1, 'Sine moj, ako si griješio, nemoj više; a za prijašnje grijehe moli oproštenje.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (28, 21, 2, 'Bježi od grijeha kao od zmije, jer ako se primakneš, ujest će te. Kao u lava zubi su njegovi: ljudima život oduzimaju.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (28, 21, 3, 'Svako je bezakonje kao dvosjekli mač koji nanosi rane neizlječive.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (28, 21, 4, 'Okrutnost i nasilje pustoše dvorce, a tako se ruše i kuće oholica.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (28, 21, 5, 'Molitva iz usta siromaha ide pravo u uši Božje i presuda će brzo stići.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (28, 21, 6, 'Tko mrzi ukor ide stopama grešničkim, a tko se boji Gospoda obratit će se u srcu svojem.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (28, 21, 7, 'Jezičavac se poznaje nadaleko, ali uman čovjek predviđa njegov pad.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (28, 21, 8, 'Tko sebi gradi kuću tuđim blagom, kao da skuplja kamenje za vlastiti grob.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (28, 21, 9, 'Zbor je bezakonički kao hrpa kučina: završit će u ognju plamenom.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (28, 21, 10, 'Put je grešnički dobro popločen, ali se zavšava u ponoru Podzemlja.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (28, 21, 11, 'Tko čuva Zakon, gospodar je svojim strastima, i savršenstvo straha Gospodnjeg mudrost je.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (28, 21, 12, 'Ne stječe pouku tko nije nadaren, ali gdjekad nadarenost umnaža gorčinu čovjekovu.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (28, 21, 13, 'Spoznaja mudračeva prelijeva se kao poplava, a savjet mu je kao vrelo živo.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (28, 21, 14, 'Srce je bezumnikovo kao vrč razbijen koji ne drži nikakve spoznaje.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (28, 21, 15, 'Kad uman čovjek čuje mudru riječ, pohvali je i drugu doda; a čuje li je bezumnik, ruga joj se i baca je iza svojih leđa.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (28, 21, 16, 'Pripovijedanje je bezumnikovo kao teret na putu, a milina je slušati razborita čovjeka.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (28, 21, 17, 'Riječ se razumna čovjeka traži u zboru i o riječima se njegovim razmišlja u srcu.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (28, 21, 18, 'Kao kuća u ruševinama, takva je mudrost luđaka, i znanje je nerazumnog kao besmislica.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (28, 21, 19, 'Stega je bezumniku kao negve na nogama i kao okovi na njegovoj desnici.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (28, 21, 20, 'Luđak se smije punim grlom, a uman se čovjek tiho osmjehne.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (28, 21, 21, 'Stega je razumnu čovjeku kao ures zlatni i kao narukvica njegovoj desnici.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (28, 21, 22, 'Bezumnikova noga žuri se u kuću, a iskusan čovjek stidljivo prilazi.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (28, 21, 23, 'Bezumnik kroz vrata viri u kuću, a odgojen čovjek čeka vani.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (28, 21, 24, 'Znak je lošeg odgoja prisluškivati na vratima, i razborit se čovjek toga srami.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (28, 21, 25, 'Usne brbljavaca ponavljaju tuđe riječi, a riječi mudrih pomno su odmjerene.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (28, 21, 26, 'Luđacima je srce u ustima, a mudracima su usta u srcu.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (28, 21, 27, 'Kad bezbožnik proklinje neprijatelja, onda proklinje samog sebe.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (28, 21, 28, 'Klevetnik kalja samog sebe i mrzak je u susjedstvu.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (28, 22, 1, 'Lijenčina je sličan uprljanu kamenu: svatko zviždi zbog gnusobe njegove.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (28, 22, 2, 'Lijenčina je sličan hrpi balege: tko ga dirne otresa ruku.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (28, 22, 3, 'Sramota je ocu loše odgojen sin, a ako je kći, na štetu mu je.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (28, 22, 4, 'Razumna kći blago je mužu svojem, a besramnica je na tugu svojem roditelju.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (28, 22, 5, 'Bestidna kći sramoti i oca i muža, pa je obojica preziru.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (28, 22, 6, 'Neprikladan je prigovor kao gozba na dan žalosti, ali šiba i ukor uvijek su mudrost.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (28, 22, 7, '#');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (28, 22, 8, '#');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (28, 22, 9, 'Tko poučava luđaka pokušava zalijepiti krhotine i budi spavača iz sna dubokog.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (28, 22, 10, 'Objašnjavati luđaku isto je kao i bunovnu čovjeku, jer će na koncu zapitati: \"Što je?\"');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (28, 22, 11, 'Za mrtvim plači, jer mu se ugasila svjetlost; i za luđakom plači, jer mu se ugasio razum. Manje za mrtvim plači, jer je počinuo, a luđakov je život gori od smrti.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (28, 22, 12, 'Žalost za mrtvim traje sedam dana, a za luđakom i bezbožnikom sve dane života njihova.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (28, 22, 13, 'Ne govori mnogo s bezumnikom i ne druži se s nerazumnikom: čuvaj ga se, da ti ne dosadi i da se ne ukaljaš dodirom njegovim. Kloni ga se, da nađeš mir i da ti ne dojadi ludost njegova.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (28, 22, 14, 'Što je teže od olova? I kako se zove ako ne: luđak?');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (28, 22, 15, 'Lakše je nositi i pijesak i sol i komad željeza nego snositi čovjeka nerazumna.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (28, 22, 16, 'Kao što se greda uglavljena u zdanje ne remeti potresom, tako se ni srce utvrđeno zrelim promišljanjem ne plaši u času pogibelji.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (28, 22, 17, 'Srce učvršćeno umnim razmišljanjem jest kao ures od žbuke na uglačanu zidu.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (28, 22, 18, 'Kao što kamenčići na visoku zidu ne mogu odoljeti vjetru, tako ni srce zaplašeno luđačkim tlapnjama ne odolijeva nikakvu strahu.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (28, 22, 19, 'Tko oko udari suze izazove, a tko srce dirne izaziva osjećaje.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (28, 22, 20, 'Tko se baca kamenom na ptice rastjera ih, a tko prijatelja grdi raskida prijateljstvo.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (28, 22, 21, 'Ako trgneš i mač na prijatelja, ne gubi nade jer on se može vratiti.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (28, 22, 22, 'I ako otvoriš usta protiv prijatelja, ne boj se jer moguća je pomirba. Samo u slučaju pogrde, oholosti, otkrivanja tajne i udaraca iz potaje odbjegne svaki prijatelj.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (28, 22, 23, 'Budi vjeran bližnjemu svojem kad je siromašan, tako da mu budeš i u kasnijoj sreći dionik; ostaj mu vjeran u vrijeme nevolje, da s njime zajedno dijeliš baštinu.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (28, 22, 24, 'Prije vatre diže se iz peći vatra i dim, tako i prije krvoprolića izbija svađa.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (28, 22, 25, 'Ne stidim se uzeti u zaštitu prijatelja i pred njim se ne krijem.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (28, 22, 26, 'Ako li me od njega zadesi zlo, svatko koji čuje čuvat će se od njega.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (28, 22, 27, 'Oj, tko će postaviti stražu ustima mojim i na usne moje pečat razboritosti, da nikad zbog njih u zlo ne zapadnem, da me jezik moj ne uništi?');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (28, 23, 1, 'Gospodine, Oče i vladaru života moga, ne prepusti me ćudi njihovoj, ne dopusti da propadnem zbog njih.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (28, 23, 2, 'Tko će biti bič mislima mojim i stega mudrosti srcu mojem, nemilosrdan prestupcima mojim i nepopustljiv grijesima mojim,');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (28, 23, 3, 'da ne uzobiluju pogreške moje i ne namnože se moji grijesi; da ne padnem naočigled protivnika svojih i da neprijatelj moj ne likuje nada mnom?');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (28, 23, 4, 'Gospode, Oče i Bože života moga, ne daj mi oči ohole,');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (28, 23, 5, 'odvrati požudu od mene,');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (28, 23, 6, 'ne daj da podlegnem nasladi i pohoti, ne prepusti me besramnim željama.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (28, 23, 7, 'Čujte, djeco, pouku za usta: tko se nje drži neće zalutati.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (28, 23, 8, 'Grešnik pada u zamku zbog vlastitih usana, o njih se spotiče i svadljivac i oholica.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (28, 23, 9, 'Ne privikavaj usta svoja na prisege i ne navikavaj se izgovarati ime Svetoga.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (28, 23, 10, 'Jer kao što rob pod neprestanim nadzorom ne ostaje bez modrica, tako i tko uvijek priseže i zaziva ime Božje neće izmaći grijehu.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (28, 23, 11, 'Čovjek koji mnogo priseže pun je zloće i bič ne odstupa od kuće njegove. Ako pogriješi, grijeh mu njegov ostaje; a ako se na to ne obazire, griješi dvostruko. Ako se prisegne krivo, neće mu se oprostiti i kuća će mu biti puna nevolje.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (28, 23, 12, 'Postoji govor koji zaslužuje smrt, i ne bilo ga u baštini Jakovljevoj! Sve to nek\' je daleko od ljudi pobožnih, da se ne valjaju u grijesima.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (28, 23, 13, 'Ne privikavaj usta gnusnoj neuljudnosti jer se u njoj nalazi riječ grijeha.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (28, 23, 14, 'Kad si među velikašima, sjeti se oca i majke svoje, da se ne zaboraviš pred njima, i da se ne ponašaš kao luđak i ne zažališ što si se rodio i ne prokuneš i dan svojeg rođenja.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (28, 23, 15, 'Tko se naviknuo na sramotne riječi neće se popraviti svega vijeka svoga.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (28, 23, 16, 'Dvije vrste ljudi umnažaju grijehe, a treća navlači na se srdžbu:');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (28, 23, 17, 'žarka strast što kao oganj žeže ne stišava se dok se ne ugasi; čovjek pohotan na vlastito tijelo: on ne prestaje dok ga vatra ne sažeže. Bludniku je svaka hrana slatka i on se ne smiruje sve do smrti.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (28, 23, 18, 'Čovjek koji čini preljub na postelji svojoj i govori u sebi: \"Tko me vidi? Tama je oko mene i zidovi me kriju, nitko me ne vidi, čemu se bojati? Grijeha se mojih neće sjetiti Svevišnji!\" -');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (28, 23, 19, 'takav se boji samo ljudskih očiju, a ne shvaća kako su oči Gospodnje deset tisuća puta od sunca svjetlije i paze na sve putove ljudske i motre i najskrivenije zakutke.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (28, 23, 20, 'Njemu je sve to poznato bilo prije nego je stvoreno, a tako i sada kada je sve dovršeno.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (28, 23, 21, 'Takva će čovjeka na ulicama grada stići kazna, uhvatit će ga gdje i ne sluti.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (28, 23, 22, 'Tako je i ženi koja je nevjerna mužu svojemu i rađa mu baštinika s tuđincem.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (28, 23, 23, 'Jer je, prvo, prezrela Zakon Svevišnjega, i drugo: ogriješila se o muža svog, i treće: preljubom se ukaljala i začela djecu s tuđim mužem.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (28, 23, 24, 'Takva će biti izvedena pred zbor narodni i djecu će joj pregledati.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (28, 23, 25, 'Djeca joj ne će pustiti korijenja niti će joj grane ploda donijeti.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (28, 23, 26, 'Ostavit će proklet spomen o sebi, i njezina se sramota neće nikad izbrisati.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (28, 23, 27, 'I priznat će svi oni koji ostanu iza nje da nema ništa bolje od straha Gospodnjeg, nema ništa slađe no vršiti zapovijedi Gospodnje.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (28, 23, 28, '');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (28, 24, 1, 'Mudrost se sama slavi i sred puka svog se hvali.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (28, 24, 2, 'Usta svoja otvara u zboru Svevišnjeg i pred njegovom se moći proslavlja:');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (28, 24, 3, '\"Izađoh iz usta Svevišnjeg i pokrih zemlju kao magla.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (28, 24, 4, 'Na visinama nebeskim razapeh šator svoj i prijestol moj bi stup od oblaka.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (28, 24, 5, 'Obiđoh sama krug nebeski i prošetah se dubinama bezdana.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (28, 24, 6, 'U vlasti su mojoj valovi morski, i sva zemlja, i svi narodi i puci.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (28, 24, 7, 'Među svima njima tražila sam počinka i na čijoj baštini da se nastanim.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (28, 24, 8, 'Tada mi zapovjedi Stvoritelj sviju stvari i koji me stvori, odredi mjesto za šator moj i reče: \'Nastani se u Jakovu i uđi u baštinu Izraelu.\'');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (28, 24, 9, 'Prije vjekova, odiskona, on me stvorio i neću prestati dovijeka.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (28, 24, 10, 'Pred njim sam služila u Svetom šatoru i potom se nastanila na Sionu.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (28, 24, 11, 'Dao mi je tako spokoj u milome gradu i vlast mi je u Jeruzalemu.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (28, 24, 12, 'Tako se ukorijenih u slavnom narodu, na dijelu Gospodnjem, u baštini njegovoj.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (28, 24, 13, 'Uzrastoh kao cedar na Libanu i kao čempres na gori Hermonu.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (28, 24, 14, 'Uzrastoh kao palma u Engadu i kao ružičnjaci u Jerihonu. Kao divna maslina u dolini, uzrastoh kao makljen nad vodama.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (28, 24, 15, 'Rasuh miomiris svoj kao cimet i drvo bagremovo i zamirisah mirisom kao smirna izabrana, kao galban, oniks i stakte i kao vonj tamjanov u Šatoru.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (28, 24, 16, 'Raširih grane svoje kao terebinta, i grane su moje divne i ljupke.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (28, 24, 17, 'Propupah kao trs mladicama ljupkim, i cvjetovi su moji porod slave i bogatstva.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (28, 24, 18, '#');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (28, 24, 19, 'Dođite k meni svi koji me žudite i nasitite se plodovima mojim.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (28, 24, 20, 'Jer je spomen na mene slađi od meda i baština moja od mednoga saća.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (28, 24, 21, 'Koji me jedu još više su me gladni, i koji me piju još više za mnom žeđaju.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (28, 24, 22, 'Tko mene sluša taj se ne stidi, i tko sa mnom radi taj ne griješi.\"');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (28, 24, 23, 'Sve je ovo Knjiga saveza Boga Svevišnjeg, Zakon koji nam je Mojsije odredio kao baštinu zajednicama Jakovljevim.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (28, 24, 24, '#');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (28, 24, 25, 'On je mudrosti pun kao vode Fišona i kao Tigris u dane proljetne;');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (28, 24, 26, 'on buja razborom kao Eufrat i kao Jordan u vrijeme žetveno:');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (28, 24, 27, 'obiluje stegom kao Nil vodom i kao Gihon u vrijeme berbe.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (28, 24, 28, 'Prvi ga čovjek nije do dna spoznao niti će ga posljednji istražiti.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (28, 24, 29, 'Jer su misli njegove šire od mora i namisli dublje od bezdana.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (28, 24, 30, 'A ja sam kao jarak prekopan od rijeke i kao vodotok doveden u perivoj.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (28, 24, 31, 'I rekoh: \"Natopit ću vrt svoj i navodnit ću cvijetnjake svoje\". I gle, od jarka mojeg rijeka postade, a od rijeke more mi nasta.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (28, 24, 32, 'Učinit ću da kao zora zasja nauk moj, i svjetlost ću njegovu razaslati nadaleko.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (28, 24, 33, 'Izlit ću nauku poput proroštva, ostaviti je pokoljenjima budućim.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (28, 24, 34, 'Vidite: ne trudih se samo za sebe nego za sve koji je traže.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (28, 25, 1, 'Troje mi je drago, a milo je i Gospodu i ljudima: sloga među braćom, prijateljstvo među susjedima, muž i žena koji se vole.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (28, 25, 2, 'A tri vrste ljudi mrzi duša moja i veoma mi je oduran život njihov: ohol siromah i lažljiv bogataš i razbludan starac koji nema razbora.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (28, 25, 3, 'Ako za mladosti nisi ništa sabirao, kako ćeš išta naći u starosti?');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (28, 25, 4, 'Kako lijepo pristaje sijedoj kosi zdrava rasudba i starcima savjet znalački!');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (28, 25, 5, 'O, kako je lijepa mudrost u staraca i promišljen savjet odličnika!');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (28, 25, 6, 'Veliko je iskustvo kruna starcima, i strah je Gospodnji istinska slava njihova.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (28, 25, 7, 'Devetero smatra srce moje blaženim, a deseto mi je sad na jeziku: čovjek koji se djeci svojoj raduje i koji doživi pad neprijatelja svojih.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (28, 25, 8, 'Blago mužu koji živi sa ženom razumnom i koji ne ore s volom i magarcem, i koji nije pogriješio jezikom svojim, i koji ne služi od sebe nevrednijemu.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (28, 25, 9, 'Blago onomu koji je stekao razboritost i koji pripovijeda ušima pozornim.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (28, 25, 10, 'A kako je velik onaj koji je našao mudrost, ali nitko ne nadmašuje onoga koji se boji Gospoda.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (28, 25, 11, 'Strah je Gospodnji iznad svega; i tko ga ima, s kime se može usporediti?');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (28, 25, 12, '#');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (28, 25, 13, 'Svaka rana, samo ne rana srca! I svaka opačina, samo ne opačina ženina!');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (28, 25, 14, 'Svaka nesreća, samo ne nesreća od mrzitelja! I svaka osveta, samo ne osveta neprijateljska!');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (28, 25, 15, 'Nema otrova nad otrovom zmijskim niti mržnje od mržnje neprijateljske.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (28, 25, 16, 'Volim više živjeti s lavom i sa zmajem nego živjeti sa ženom opakom.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (28, 25, 17, 'Pakost ženi nagrđuje lik i mrači joj lice kao u medvjeda.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (28, 25, 18, 'Kad među susjedima sjedi joj muž, on i nehotice gorko uzdiše.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (28, 25, 19, 'Malena je svaka zloća prema zloći ženskoj: neka je snađe kob grešnička!');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (28, 25, 20, 'Kakav je pješčani brijeg nogama staračkim, takva je jezičava žena mirnu mužu.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (28, 25, 21, 'Ne daj se zavesti ljepotom ženskom i ne žudi za ženom.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (28, 25, 22, 'Velik je jad, sramota i ruglo kad žena uzdržava muža svog.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (28, 25, 23, 'Srce poniženo, lice pomračeno i rana u srcu - to je žena opaka. Ruke lomne i klecava koljena, takva je žena koja ne usrećuje muža svoga.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (28, 25, 24, 'Od žene je grijeh počeo i zbog nje svi umiremo.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (28, 25, 25, 'Ne daj vodi pukotine niti zloj ženi slobode jezika.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (28, 25, 26, 'Ako ne čini kao što joj pokažeš, otpusti je od sebe.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (28, 26, 1, 'Blago mužu žene čestite jer je dvostruk broj dana njegovih.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (28, 26, 2, 'Čestita žena radost je mužu svojem, on će godine svojeg života proživjeti u miru.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (28, 26, 3, 'Izvrsna žena odabran je dio, dar onomu koji se boji Gospodina.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (28, 26, 4, 'Bio bogat ili siromah, srce mu je veselo i lice vedro u svako doba.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (28, 26, 5, 'Troga se plaši srce moje a od četvrtog užasava: od klevete u gradu, od zbora svjetine i od lažne optužbe, jer je sve to gore od smrti;');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (28, 26, 6, 'ali je tuga i jad žena ljubomorna na ženu i bič jezika koji sve jednako udara.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (28, 26, 7, 'Nepodesan je jaram žena opaka, i svladati nju isto je kao uhvatiti štipavca.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (28, 26, 8, 'Žena pijana zaziva srdžbu golemu, jer sramota je njezina neizbrisiva.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (28, 26, 9, 'Ženina je bludnost u njezinu drsku pogledu i poznaje se po njezinim trepavicama.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (28, 26, 10, 'Pod oštrim nadzorom drži kćer drzovitu, da ne zlorabi prvu priliku.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (28, 26, 11, 'Budno pazi na oko bestidno, da se ne začudiš kad se o tebe ogriješi.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (28, 26, 12, 'Kao žedan putnik, ona otvara usta i pije svaku vodu na koju naiđe i spušta se pred svakim kolcem i svakoj strijeli otvara tulac.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (28, 26, 13, 'Mila je žena radost mužu svom, i znanje mu njezino kosti ojačava.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (28, 26, 14, 'Dar je Gospodnji žena šutljiva, i nema cijene duši dobro odgojenoj.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (28, 26, 15, 'A milina je na milinu žena stidljiva, i nema cijene dostojne duše uzdržljive.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (28, 26, 16, 'Kao što sunce blista na planinama Gospodnjim, tako i ljepota vrsne žene u urednosti kuće njezine.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (28, 26, 17, 'Kao svijeća što svijetli na svetom svijećnjaku, tako je krasno lice na skladnu tijelu.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (28, 26, 18, 'Kao stupovi zlatni na podnožju srebrnu, tako su lijepe noge na čvrstim petama.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (28, 26, 19, '#');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (28, 26, 20, '#');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (28, 26, 21, '#');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (28, 26, 22, '#');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (28, 26, 23, '#');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (28, 26, 24, '#');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (28, 26, 25, '#');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (28, 26, 26, '#');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (28, 26, 27, '#');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (28, 26, 28, 'Dvoje rastužuje srce moje, a zbog trećeg gnjev me hvata: kad ratnik stÓarÄi u bijedi, kad se preziru ljudi umni, kad se netko od pravednosti vraća grijehu - za takvog je Gospod mač spremio.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (28, 26, 29, 'Trgovac teško odolijeva napasti, i prodavač nije bez grijeha.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (28, 27, 1, 'Radi probitka mnogi griješe, i tko traži bogatstvo biva nemilosrdan.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (28, 27, 2, 'Kolac se zabija između dva kamena, a grijeh se utiskuje između kupnje i prodaje.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (28, 27, 3, 'Tko se čvrsto ne drži straha Gospodnjeg kuća će mu brzo propasti.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (28, 27, 4, 'Kad se sito trese, mekinje ostaju: tako i nedostaci čovjekovi izbijaju u govoru njegovu.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (28, 27, 5, 'Lončareve posude peć iskušava, a čovjeka njegov govor.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (28, 27, 6, 'Obradu voćke očituje njezin plod: tako i riječi čovjekove otkrivaju njegove osjećaje.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (28, 27, 7, 'Nikoga ne hvali prije no što progovori, jer govor je kušnja ljudi.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (28, 27, 8, 'Ako težiš pravdi, naći ćeš je i obući ćeš je kao svečanu odoru.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (28, 27, 9, 'Ptice se jate sa sebi sličnima, i pravica se svraća onima koji je vrše.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (28, 27, 10, 'Lav vreba svoju lovinu, tako i grijeh one koji čine nepravdu.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (28, 27, 11, 'Govor je pobožna čovjeka uvijek pun mudrosti, a luđak se mijenja poput mjeseca.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (28, 27, 12, 'Kad si među bezumnicima, pazi na vrijeme, a s ljudima mudrim boravi bez straha.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (28, 27, 13, 'Sablažnjiv je govor luđački i smijeh je njihov grešna razuzdanost.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (28, 27, 14, 'Govor s mnogim zakletvama podiže čovjeku vlasi, i kad se takvi svađaju, začepiti je uši.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (28, 27, 15, 'Svađa oholih ljudi završava se krvlju, i mučno se slušaju grdnje njihove.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (28, 27, 16, 'Tko otkriva tajne gubi povjerenje i neće više naći prijatelja po srcu svojem.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (28, 27, 17, 'Ljubi prijatelja i budi mu vjeran, ali ako si izdao njegove tajne, ne idi više za njim.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (28, 27, 18, 'Jer kao što čovjek uništava svojeg neprijatelja, tako si ti uništio prijateljstvo svojega bližnjeg.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (28, 27, 19, 'Ili kao što si ispustio pticu iz šake, tako si ispustio prijatelja svoga i nećeš ga uhvatiti više.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (28, 27, 20, 'Ne trči za njim jer je daleko odmakao i utekao poput gazele iz zamke.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (28, 27, 21, 'Jer se rana može povezati i pogrda oprostiti, ali za onoga tko je izdao tajnu nema nade.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (28, 27, 22, 'Tko žmirka očima kuje zlo, i nitko ga od toga ne može odvratiti.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (28, 27, 23, 'Pred tobom je medenih usta i divi se tvojim riječima, ali iza tvojih leđa mijenja svoj jezik i u sablazan izvrće tvoje riječi.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (28, 27, 24, 'Mnogo što mrzim, ali ništa kao takva čovjeka, a i Gospod ga mrzi.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (28, 27, 25, 'Tko baca kamen uvis, na glavu mu pada; podmukao udarac protuudarcem rađa.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (28, 27, 26, 'Tko jamu kopa, u nju pada, i tko zamku namješta, u nju se hvata.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (28, 27, 27, 'Tko čini zlo, zlo mu se vraća, iako on ne zna odakle dolazi.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (28, 27, 28, 'Ruglo i sramota oholici, i osveta na nj vreba kao lav.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (28, 27, 29, 'U zamku se hvataju koji se raduju padu pobožnika, i bol će ih izjesti prije smrti njihove.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (28, 27, 30, 'Mržnja i srdžba jednako su gnusne, i grešan ih čovjek obje u sebi nosi.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (28, 28, 1, 'Tko se osvećuje, njemu se Gospod osvećuje i dobro pazi na grijehe njegove.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (28, 28, 2, 'Oprosti nepravdu svojemu bližnjemu, pa kad budeš molio, grijesi će se tvoji oprostiti.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (28, 28, 3, 'Ako čovjek goji mržnju na drugoga, kako može od Gospoda tražiti ozdravljenje?');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (28, 28, 4, 'Kad s čovjekom sličnim sebi nema milosrđa, kako može moliti se za svoje grijehe?');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (28, 28, 5, 'On, koji je samo od mesa, goji osvetljivost, pa tko će mu oprostiti grijehe?');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (28, 28, 6, 'Misli na konac svoj i prestani s mržnjom; sjeti se raspadanja i smrti, i vrši zapovijedi.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (28, 28, 7, 'Misli na zapovijedi i ne mrzi na bližnjega i na Zavjet Svevišnjega, pa oprosti krivicu.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (28, 28, 8, 'Kloni se svađe, pa ćeš manje griješiti; strastven čovjek raspaljuje svađu.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (28, 28, 9, 'Grešnik sije razdor među prijateljima i među mirne ljude baca klevetu.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (28, 28, 10, 'Oganj se raspaljuje prema gorivu kojim se hrani, a svađa se širi prema silini svojoj; gnjev čovjekov ovisi o snazi njegovoj i jarost mu raste prema bogatstvu njegovu.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (28, 28, 11, 'Nagla svađa raspaljuje vatru, nagla prepirka vodi u krvoproliće.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (28, 28, 12, 'Pušeš li u iskru, ona se rasplamsa, pljuneš li na nju, ona se ugasi: oboje izlazi iz usta tvojih.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (28, 28, 13, 'Proklet bio došaptavač i klevetnik, jer uništiše mnoge koji su živjeli u miru.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (28, 28, 14, 'Treći je jezik potresao mnoge i prognao ih od naroda do naroda; razorio je tvrde gradove i porušio kuće kneževske.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (28, 28, 15, 'Treći je jezik izagnao žene čestite i lišio ih plodova trudbe njihove.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (28, 28, 16, 'Tko ga sluša taj nema počinka niti će imati boravišta mirna.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (28, 28, 17, 'Udarac bičem ostavlja masnicu, udarac jezikom lomi kosti.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (28, 28, 18, 'Mnogi su pali od mača, ali ne toliki kao od jezika.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (28, 28, 19, 'Blago čovjeku koji se od njega zaštitio i nije iskusio srdžbu njegovu, koji nije nosio jarma njegova niti je bio svezan lancima njegovim.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (28, 28, 20, 'Jer jaram je njegov jaram gvozdeni i lanci su njegovi lanci mjedeni.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (28, 28, 21, 'Strašna je smrt koju donosi, i bolje je Podzemlje od nje.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (28, 28, 22, 'Ali nema vlasti nad pobožnicima, njih ne prži plamen njegov.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (28, 28, 23, 'Njegove su žrtve oni koji ostavljaju Gospoda, u njima on plamti i ne gasi se, on će nasrnuti na njih kao lav i raznijeti ih kao pantera.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (28, 28, 24, 'Gle, trnjem ogradi svoj posjed, zaključaj dobro svoje srebro i zlato:');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (28, 28, 25, 'tako i riječima svojim načini mjerila i utege i ustima svojim vrata s prijevornicom.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (28, 28, 26, 'Pazi da ne posrneš zbog jezika svojeg i ne postaneš plijenom onomu koji te vreba.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (28, 29, 1, 'Milosrđe čini tko uzajmljuje svojem bližnjemu; i tko mu pomaže vrši zapovijedi.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (28, 29, 2, 'Uzajmljuj bližnjemu kad je u potrebi i opet vraćaj bližnjemu u pravo vrijeme.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (28, 29, 3, 'Čvrsto drži svoju riječ i budi mu vjeran, pa ćeš u svako vrijeme dobiti što ti treba.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (28, 29, 4, 'Mnogi smatraju zajam dobitkom i zadaju jad onima koji su im pomogli.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (28, 29, 5, 'Dok ne dobije, ruku mu ljubi i ponizno zbori o bogatstvu bližnjega, ali na dan naplate on odgađa rok, udara u jadikovke i krivnju baca na zla vremena.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (28, 29, 6, 'Mogne li, vrati jedva polovicu, a i to valja smatrati dobitkom. Ne plati li, valja oteti od njegova - i eto neprijatelja bez potrebe: vraća on kletvama i svađama, umjesto čašću uzvraća prezirom.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (28, 29, 7, 'Mnogi se stoga, ne zbog zloće, ustežu davati zajam: boje se da ne budu nezasluženo opljačkani.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (28, 29, 8, 'Ali sa siromahom budi velikodušan i ne pusti ga da čeka na tvoj milodar.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (28, 29, 9, 'Zbog Božje zapovijedi pomozi siromahu; ako je potrebit, ne pusti ga praznih ruku.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (28, 29, 10, 'Radije izgubi novce na brata ili prijatelja nego da ti propadaju hrđajući pod kamenom.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (28, 29, 11, 'Uloži blago svoje po zapovijedima Svevišnjega, i bit će ti probitačnije nego samo zlato.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (28, 29, 12, 'Uloži milostinju u svoje riznice, i ona će te izbaviti od svake nevolje:');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (28, 29, 13, 'bolje će se boriti za te pred neprijateljem negoli čvrsti štit i teško koplje.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (28, 29, 14, 'Dobar čovjek jamči za bližnjega svoga, a tko je izgubio osjećaj stida, ostavlja ga na cjedilu.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (28, 29, 15, 'Ne zaboravljaj jamcu uslugu njegovu, jer je dušu svoju dao za tebe.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (28, 29, 16, 'Grešnik se ne brine za dobra jamčeva, i nezahvalnik zaboravlja svojeg izbavitelja.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (28, 29, 17, 'Jamčenje je upropastilo mnoge sretne ljude i razbacalo ih kao morske valove.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (28, 29, 18, 'Istjeralo je iz doma ljude bogate, koji onda lutaju među tuđim pucima.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (28, 29, 19, 'Grešnik koji se upušta u jamčenje radi laka dobitka - potpada pod sud.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (28, 29, 20, 'Pomozi bližnjemu koliko god možeš, ali pazi da se i sam ne upropastiš.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (28, 29, 21, 'Prve su životne potrebe voda, kruh, odijelo i kuća, da se sram pokrije.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (28, 29, 22, 'Bolje je živjeti siromaški pod krovom od dasaka nego se gostiti gospodski u tuđoj kući.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (28, 29, 23, 'Budi zadovoljan imao malo ili mnogo, pa nećeš slušati ukore ukućana.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (28, 29, 24, 'Težak je život ići od kuće do kuće, i gdje god se zaustaviš, ne smiješ usta otvoriti;');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (28, 29, 25, 'tuđinac si i poznaj okus poniženja, a osobito zvuk gorkih riječi:');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (28, 29, 26, '\"Hajde, tuđinče, postavi stol, i ako imaš što, daj mi jesti.\"');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (28, 29, 27, '\"Odlazi, tuđinče, ustupi mjesto časnijemu, dolazi mi brat i treba mi kuća.\"');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (28, 29, 28, 'Teško je umnu čovjeku kad mu predbace gostoprimstvo i pogrde ga kao vjerovnika.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (28, 30, 1, 'Tko ljubi sina svog, često ga bije šibom, da se na koncu u njemu obraduje.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (28, 30, 2, 'Tko valjano odgaja svog sina, imat će od njega koristi i ponosit će se njime među znancima svojim.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (28, 30, 3, 'Tko pouči sina svoga, čini zavidnim neprijatelja svoga i raduje se pred prijateljima svojim.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (28, 30, 4, 'Pa i umre li otac, kao da i nije umro, jer ostavlja sina sebi slična.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (28, 30, 5, 'Za svojeg se života radovao gledajući ga i na samrti se svojoj ne žalosti.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (28, 30, 6, 'Jer za neprijatelje ostavlja osvetnika, a prijateljima sina koji će im znati milost uzvraćati.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (28, 30, 7, 'Tko miluje sina svoga, zavijat će mu rane i na svaki će mu se njegov jauk potresati srce.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (28, 30, 8, 'Neukroćen konj postaje ćudljiv, a zapušten sin postaje tvrdoglav.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (28, 30, 9, 'Razmazi dijete svoje, pa će te zaprepastiti; igraj se s njim, pa će te u tugu zaviti.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (28, 30, 10, 'Ne smij se njim ako ne želiš plakati s njim i na koncu škrgutati zubima.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (28, 30, 11, 'Ne daj mu slobode u mladosti i ne praštaj mu pogrešaka njegovih.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (28, 30, 12, 'Savij mu šiju dok je mlad i nagnječi mu rebra dok je malen, da ti ne bude buntovan i neposlušan i ne ožalosti te duboko.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (28, 30, 13, 'Odgoji sina svojega i dotjeruj ga, da ti ne bi trpio zbog njegove drskosti.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (28, 30, 14, 'Bolji je siromah tijelom zdrav i čio nego bogataš bolesna tijela.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (28, 30, 15, 'Više valja zdravlje i snaga nego sve zlato svijeta i krepko tijelo više od golema posjeda.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (28, 30, 16, 'Nema blaga nad zdravljem tjelesnim niti sreće nad sretnim srcem.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (28, 30, 17, 'Bolja je smrt nego gorak život i počinak vječni nego trajna bolest.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (28, 30, 18, 'Dobre su jestvine pred ustima zatvorenim kao jelo žrtveno na grob položeno.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (28, 30, 19, 'Čemu žrtve idolu, kad ne može ni jesti niti pomirisati? Tako i onaj koga Gospod progoni:');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (28, 30, 20, 'samo gleda i uzdiše, kao uškopljenik koji grli djevicu i uzdiše.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (28, 30, 21, 'Ne prepuštaj se žalosti i ne kinji se mračnim mislima.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (28, 30, 22, 'Veselje srca život je čovjeku, i radost mu produljuje dane životne.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (28, 30, 23, 'Prevari svoje brige i utješi srce svoje, otjeraj od sebe žalost: jer je žalost pogubila mnoge, od nje nema koristi nikomu.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (28, 30, 24, 'Zavist i srdžba skraćuju dane, i briga donosi starost prije vremena.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (28, 30, 25, 'Izdašnu srcu jelo je u slast: i koristi mu ono što pojede.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (28, 31, 1, 'Briga za bogatstvo izjeda tijelo, i skrb za njim odgoni san.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (28, 31, 2, 'Dnevne se brige u san uvlače, i teška bolest ne da spavati.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (28, 31, 3, 'Bogataš se muči da skupi imetak, a kad se odmara, uživa u raskoši;');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (28, 31, 4, 'siromah se muči, jer nema od čega živjeti, a kad se odmara, zapada u bijedu.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (28, 31, 5, 'Tko ljubi zlato - ne ostaje bez grijeha, i tko za novcem trči - zbog njega će zalutati.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (28, 31, 6, 'Mnogi postadoše žrtve zlata, propast im bijaše neminovna.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (28, 31, 7, 'Jer ono je zamka onima koji mu žrtvuju, i svaki se nerazumni lako u nju hvata.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (28, 31, 8, 'Blago bogatašu koji se našao bez krivnje i koji nije trčao za zlatom!');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (28, 31, 9, 'Tko je taj, da mu čestitamo, jer je izvršio čudesna djela u svom narodu?');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (28, 31, 10, 'Tko je tu kušnju prošao i savršen ostao, neka mu je na čast! Tko je mogao zgriješiti, a nije zgriješio, i zlo učiniti, a nije učinio?');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (28, 31, 11, 'Njegova će dobra biti trajna, i zajednica će slaviti dobrotu njegovu.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (28, 31, 12, 'Ako si sjeo za obilan stol, ne otvaraj nad njim ždrijela svoga i ne reci: \"Ima dosta na njemu!\"');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (28, 31, 13, 'Sjeti se: oko pohlepno veliko je zlo. Je li stvoreno išta gore od takva oka? Zato ono suze roni za sve što vidi.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (28, 31, 14, 'Kamo drugi gleda, ti ne pružaj ruke, da se s njim ne sukobiš u zdjeli.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (28, 31, 15, 'Prosudi potrebe susjedove po svojima i budi obazriv u svemu.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (28, 31, 16, 'Pristojno jedi što ti je ponuđeno i ne budi pohlepan da te ne omrznu.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (28, 31, 17, 'Zbog pristojnosti prestani prvi i ne budi nezasitan, da ne sablazniš.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (28, 31, 18, 'Ako i u veliku društvu sjediš, ne pružaj ruke prije ostalih.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (28, 31, 19, 'Malo je dosta čovjeku dobro odgojenu i on se ne muči na postelji svojoj.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (28, 31, 20, 'Umjeren obrok - dobar san, i čovjek rano ustaje, pun svježine. A besanicu, bljuvanje i srdobolju mora pretrpjeti proždrljivac.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (28, 31, 21, 'Ako si morao previše pojesti, ustani i izbljuj, i bit će ti lakše.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (28, 31, 22, 'Slušaj, sine moj, i ne preziri me, na kraju ćeš shvatiti moje riječi. U svim djelima svojim budi umjeren i neće te snaći nikakva bolest.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (28, 31, 23, 'Dobra ugosnika hvale usne i trajno je svjedočanstvo darežljivosti njegove.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (28, 31, 24, 'Na loša se ugosnika javno mrmlja i uporan je glas o škrtosti njegovoj.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (28, 31, 25, 'U vinu se nemoj junačiti, jer je mnoge oborilo vino.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (28, 31, 26, 'Kao što se u peći kuša ocjel, tako i u vinu srca svadljivih hvalisavaca.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (28, 31, 27, 'Vino je život čovjeku ako ga pije umjereno. Kakav je život bez vina, kad je stvoreno za veselje ljudima!');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (28, 31, 28, 'Radost srcu i veselje duši, takvo je vino koje se pije u pravo vrijeme i u pravoj količini.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (28, 31, 29, 'Gorčina duše spopada čovjeka koji je vina previše popio, u strasti i u gnjevu.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (28, 31, 30, 'Pijanstvo u bezumnika izaziva srdžbu na vlastitu propast, umanjuje mu snagu i umnožava rane.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (28, 31, 31, 'Na gozbi ne izazivaj susjeda i ne rugaj mu se ako je veseo: ne reci mu ružne riječi i ne kinji ga tražeći da vrati dug.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (28, 32, 1, 'Ako su te postavili ravnateljem stola, nemoj se uznositi. Budi među njima kao jedan od njih, pobrini se za njih i tada sjedni.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (28, 32, 2, 'Kad obaviš sve svoje dužnosti, sjedni da se proveseliš zajedno s njima i primiš vijenac za svoju uglađenost.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (28, 32, 3, 'Govori, starče, jer ti dolikuje, ali odmjereno, i ne prekidaj glazbu.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (28, 32, 4, 'Gdje se sluša pjesma, ne drži besjede i ne budi mudar u nevrijeme.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (28, 32, 5, 'Kao pečatnik od dragog kamena na zlatnu uresu, takva je skladna glazba na gozbi.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (28, 32, 6, 'Kao zlatom okovan pečatnik sa smaragdom, takav je zvuk pjesme uz odabrano vino.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (28, 32, 7, 'Govori, mladiću, ako ti je potrebno, ali tek pošto te dvaput zamole.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (28, 32, 8, 'Govori sažeto i mnogo reci u malo riječi: ostavi dojam čovjeka koji zna, ali ne želi govoriti.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (28, 32, 9, 'Kad si s odličnicima, ne izjednačuj se s njima i ne ćeretaj mnogo dok drugi zbori.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (28, 32, 10, 'Munja prethodi gromu, a ljupkost ide ispred skromna čovjeka.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (28, 32, 11, 'Na vrijeme ustani, ne budi posljednji; požuri se kući, ne oklijevaj.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (28, 32, 12, 'Ondje se zabavljaj i čini što ti na um padne, ali ne griješi govorom bestidnim.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (28, 32, 13, 'A za sve Stvoritelja svoga slavi, koji te obasu svojim dobrima.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (28, 32, 14, 'Tko se Boga boji prima pouku; oni koji ga traže - naklonost njegovu stječu.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (28, 32, 15, 'Tko traži Zakon - njime se ispunja, a licemjer se o nj spotiče.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (28, 32, 16, 'Koji se boje Gospoda dolaze do pravice, i njihova dobra djela sjaju kao svjetlost.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (28, 32, 17, 'Grešnik odbija opomenu i po volji svojoj nalazi ispriku.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (28, 32, 18, 'Razborit čovjek ne prezire savjet, a oholi bezbožnik ne poznaje straha.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (28, 32, 19, 'Bez promišljanja ne čini ništa, pa se poslije nećeš kajati.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (28, 32, 20, 'Ne idi po opasnim putovima, da se ne spotakneš o kamenje.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (28, 32, 21, 'Ne vjeruj suviše ravnu putu i čuvaj se svoje vlastite djece.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (28, 32, 22, 'U svim djelima svojim čuvaj sebe, jer tko to čini drži se zapovijedi.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (28, 32, 23, 'Tko se pouzdava u Zakon pokorava se zapovijedima; i tko se uzda u Gospoda neće pretrpjeti štete.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (28, 32, 24, '');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (28, 33, 1, 'Tko se boji Gospoda zlo ga ne snalazi i uvijek se iz kušnje izbavlja.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (28, 33, 2, 'Nije mudar tko mrzi Zakon, a tko je u njemu licemjer, ljulja se kao lađa u oluji.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (28, 33, 3, 'Razborit se čovjek pouzdava u Zakon, on u Zakon vjeruje kao u proroštvo.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (28, 33, 4, 'Pripravi svoj govor, i tad će te slušati; priberi znanje svoje i tad odgovori.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (28, 33, 5, 'Osjećaji su luđakovi kao kolski točak, a misao mu je kao osovina što se okreće.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (28, 33, 6, 'Ujedljiv je prijatelj kao uspaljen konj: tko god ga zajaše on zarže.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (28, 33, 7, 'Zašto je dan od dana uzvišeniji, kad im svima kroz godinu svjetlost od sunca dolazi?');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (28, 33, 8, 'Zato što su u misli Gospodnjoj razdijeljeni, Gospod je razlučio doba i blagdane.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (28, 33, 9, 'Neke je uzvisio i posvetio, a druge uvrstio u dane obične.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (28, 33, 10, 'I svi su ljudi od blata, i Adam je od zemlje stvoren.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (28, 33, 11, 'Ali ih Gospod u svojoj velikoj mudrosti razdijeli i dade im različite sudbine.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (28, 33, 12, 'Neke je blagoslovio i uzvisio, druge posvetio i sebi približio; neke je opet prokleo i ponizio i oborio ih s mjesta njihova.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (28, 33, 13, 'Kao što je glina u rukama lončara koji je oblikuje po svojoj volji, tako su i ljudi u rukama Tvorca svoga koji im daje prema svom sudu.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (28, 33, 14, 'Nasuprot zlu stoji dobro, nasuprot smrti stoji život: tako nasuprot pobožniku stoji grešnik.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (28, 33, 15, 'I gledaj tako sva djela Svevišnjega, sva su po dvoje, jedno prema drugome.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (28, 33, 16, 'Ja se posljednji prenuh kao onaj koji pabirči iza berača;');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (28, 33, 17, 'ali stigoh s Božjim blagoslovom i napunih tijesak svoj kao pravi berač.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (28, 33, 18, 'Gledajte kako se nisam trudio samo za se nego za sve one koji traže pouku.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (28, 33, 19, 'Oj, čujte me, glavari naroda, upravitelji općine, poslušajte!');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (28, 33, 20, 'Ni sinu ni ženi, ni bratu ni prijatelju ne daj vlasti nad sobom za života svoga. Ne daj svoga blaga drugomu, da se ne pokaješ i ne zatražiš natrag.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (28, 33, 21, 'Dok si živ i dok je daha u tebi, ne daj nikomu vlasti nad sobom:');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (28, 33, 22, 'jer je bolje da se djeca tebi mole nego da ti moliš u sinova svojih.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (28, 33, 23, 'U svim djelima svojim budi gospodar i ne daj da ti se okalja čast.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (28, 33, 24, 'Kad ti se završe dani života, u času smrti, razdijeli svoju baštinu.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (28, 33, 25, 'Magarcu krma, batina i teret, a robu kruh, stega i rad.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (28, 33, 26, 'Daj sluzi raditi, pa ćeš naći počinka; pustiš li mu slobodne ruke, tražit će slobodu.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (28, 33, 27, 'Jaram i uzde savijaju šiju, a zla slugu klade i mučila.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (28, 33, 28, 'Šalji ga na rad, da se ne ulijeni, jer lijenost poučava zloćama mnogim.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (28, 33, 29, 'Zaposli ga kako mu pripada, i ako ne sluša, stavi ga u okove.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (28, 33, 30, 'Ali ne prelazi mjere ni prema kome i ne čini ništa nepravedno.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (28, 33, 31, 'Imaš li roba, neka ti bude kao ti sam, jer si ga krvlju stekao!');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (28, 33, 32, 'Imaš li roba, postupaj s njim kao s bratom, jer ti je potreban kao ti sam sebi.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (28, 33, 33, 'Ako ga zlostavljaš pa ti odbjegne, na kojem ćeš ga putu tražiti?');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (28, 34, 1, 'Za bezumnika su prazne nade i tlapnje, i od snova luđaci okrilate.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (28, 34, 2, 'Kao hvatač sjene ili gonič vjetra, takav je onaj koji vjeruje snovima.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (28, 34, 3, 'Slični su san i zrcalo: u jednome i drugome samo je prividnost.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (28, 34, 4, 'Što se može nečistoćom očistiti? Kako će biti istina od laži?');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (28, 34, 5, 'Gatanje, proricanje i sni - sve ispraznosti, sve kao tlapnje porodilje.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (28, 34, 6, 'Ako ih Svevišnji ne šalje kao glasnike svoje, ne posvećuj im ni jedne misli.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (28, 34, 7, 'Jer mnoge su sni zaludili i propali su uzdajući se u njih.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (28, 34, 8, 'Zakon treba ispunjavati bez prijevara, i mudrost je savršena tek u iskrenosti.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (28, 34, 9, 'Tko je mnogo putovao - mnogo zna, i tko je mnogo iskusio - umno zbori.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (28, 34, 10, 'Tko nije ništa iskusio - malo znade; a tko je putovao, u svemu se snalazi.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (28, 34, 11, 'Mnogo vidjeh na putovanjima svojim i više shvatih nego što mogu iskazati.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (28, 34, 12, 'Često bijah i u smrtnoj pogibelji, ali sam se spasio,');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (28, 34, 13, 'jer živjet će duh bogobojaznih: oni se uzdaju u onoga koji ih može izbaviti.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (28, 34, 14, 'Tko se boji Gospoda, ne boji se ničega i ne straši se, jer je Gospod nada njegova.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (28, 34, 15, 'Blago duši onoga koji se boji Gospoda! U koga li se uzdao? I tko mu je potpora?');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (28, 34, 16, 'Gospod ne odvraća očiju s onih koji ga ljube, on im je moćna zaštita i snažna potpora, štitnik od vjetra pustinjskog i sjena u jari podnevnoj, obrana od posrtaja i oslon protiv pada.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (28, 34, 17, 'On je radost srcu i svjetlost očima, on je zdravlje, život i blagoslov.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (28, 34, 18, 'Žrtva od blaga krivo stečena porugljiv je dar i ne primaju se pokloni opakih.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (28, 34, 19, 'Svevišnjemu se ne mile darovi bezbožnički: gomilom žrtava oni neće iskupiti svoje grijehe.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (28, 34, 20, 'Pred očima očevim kolje sina tko prinosi žrtvu od imetka siromaha.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (28, 34, 21, 'Oskudna hrana život je siromaha, i tko je otima - pravi je krvnik;');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (28, 34, 22, 'ubija bližnjega tko mu otima hranu i prolijeva krv tko radniku uskraćuje plaću.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (28, 34, 23, 'Ako jedan gradi, a drugi razgrađuje, što im ostaje, osim trudbe?');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (28, 34, 24, 'Ako jedan moli, a drugi kune, čiji će glas uslišati Gospodar?');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (28, 34, 25, 'Tko se taknuo mrtvaca, pa se oprao i opet ga dirnuo, što mu koristi pranje njegovo?');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (28, 34, 26, 'Tako je i s čovjekom koji posti za grijehe svoje pa ih opet čini: tko će mu uslišati molitvu i zar mu koristi što se ponizio?');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (28, 34, 27, '');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (28, 34, 28, '');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (28, 34, 29, '');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (28, 34, 30, '');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (28, 34, 31, '');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (28, 35, 1, 'Tko se drži Zakona umnožava svoje žrtve. Tko vrši zapovijedi prinosi žrtve pričesnice.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (28, 35, 2, 'Tko pokazuje razboritost prinosi brašneni cvijet. Tko daje milostinju prinosi žrtvu zahvalnicu.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (28, 35, 3, 'Milo je Gospodu kad tko odstupa oda zla i okajnicu prinosi tko odstupa od nepravde.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (28, 35, 4, 'Ne pokazuj se pred Gospodom praznih ruku, jer to sve biva prema zapovijedi.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (28, 35, 5, 'Žrtva pravednikova ukrašava žrtvenik i miomiris njezin dolazi pred Svevišnjeg.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (28, 35, 6, 'Ugodna je žrtva pobožna čovjeka i njezin se spomen ne zaboravlja.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (28, 35, 7, 'Darežljivim srcem časti Gospoda i ne škrtari prvinama što ih prinosiš.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (28, 35, 8, 'Za svakoga prinosa neka ti lice sja od veselja i s radošću posvećuj desetinu.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (28, 35, 9, 'Daj Svevišnjemu kao što i on tebi dade, darežljivo i koliko možeš.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (28, 35, 10, 'Jer sve Gospod plaća i vratit će sedmerostruko.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (28, 35, 11, 'Ne podmićuj ga, jer on ne prima mita. I ne uzdaj se u žrtvu nepravednu,');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (28, 35, 12, 'jer je Gospod sudac i ne gleda tko je tko.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (28, 35, 13, 'Nije pristran na štetu siromahovu i sluša molitvu potlačenoga.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (28, 35, 14, 'Ne prezire jauk siročeta ni udovice kad izlijeva svoj bol.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (28, 35, 15, 'Ne teku li udovici suze niz lice i ne optužuje li jaukom onoga koji ih uzrokuje?');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (28, 35, 16, 'Tko Boga služi svim srcem svojim bit će uslišan, jer njegove se molbe dižu do oblaka.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (28, 35, 17, 'Molitva poniznog prodire kroz oblake i on nema mira dok ona ne dođe do Boga');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (28, 35, 18, 'i ne popušta dok ga Svevišnji ne pogleda, pravedno ne presudi i pravdu ne uspostavi.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (28, 35, 19, 'I Gospod neće oklijevati niti će odgađati');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (28, 35, 20, 'dok ne satre bedra nasilnicima i ne osveti se narodima,');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (28, 35, 21, 'ne iskorijeni mnoštvo oholica i ne slomi žezlo opakima;');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (28, 35, 22, 'dok ne plati svakome po djelu njegovu i ne prosudi čine ljudske prema namisli njihovoj;');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (28, 35, 23, 'dok ne svrši parbu puka svojega i ne obraduje ga milošću svojom.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (28, 35, 24, 'Dobra je milost u doba nevolje kao oblak kišonosan u vrijeme sušno!');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (28, 35, 25, '');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (28, 35, 26, '');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (28, 36, 1, 'Smiluj nam se, Gospodaru, Bože svega svijeta, i pogledaj na nas i prožmi strahom svojim sve narode!');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (28, 36, 2, 'Podigni ruku protiv naroda tuđinskih da spoznaju tvoju moć.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (28, 36, 3, 'Kako si se u očima njihovim pokazao nama svetim, tako se sada u očima našim pokaži velik prema njima.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (28, 36, 4, 'Da poznaju kao što znamo i mi da nema Boga osim tebe, Gospode.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (28, 36, 5, 'Obnovi znake i ponovi čudesa, proslavi ruku i desnicu svoju.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (28, 36, 6, 'Probudi gnjev i srdžbu izlij, obori protivnika, uništi neprijatelja.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (28, 36, 7, 'Požuri vrijeme, sjeti se prisege, i neka se slave tvoja silna djela.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (28, 36, 8, 'Neka žestok oganj proždre preživjele i neka propadnu tlačitelji puka tvojeg.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (28, 36, 9, 'Satri glavu poglavarima tuđinskim koji se hvale: \"Nikoga nema osim nas.\"');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (28, 36, 10, 'Okupi sva plemena Jakovljeva, vrati im baštinu kao na početku.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (28, 36, 11, 'Smiluj se, Gospode, narodu koji se zove imenom tvojim, Izraelu, kojega si učinio prvencem svojim.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (28, 36, 12, 'Smiluj se svetom gradu svojem, Jeruzalemu, prebivalištu svome.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (28, 36, 13, 'Ispuni Sion pjesmom u svoju hvalu i Svetište svoje slavom svojom.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (28, 36, 14, 'Podari svjedočanstvo svojim prvim stvorovima, ispuni proročanstva objavljena u tvoje ime.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (28, 36, 15, 'Nagradi one koji se u te uzdaju, da se proroci tvoji pokažu istiniti.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (28, 36, 16, 'Uslišaj, Gospode, molitvu slugu svojih prema blagoslovu Aronovu nad pukom tvojim.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (28, 36, 17, 'I da spoznaju svi na zemlji da si ti Gospod, vječni Bog.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (28, 36, 18, 'Svako jelo želudac prima, ali je jedno slađe od drugoga.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (28, 36, 19, 'Nepce raspoznaje okus divljači, tako i razborito srce lažljive riječi.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (28, 36, 20, 'Prijevarno srce boli zadaje, ali iskusan čovjek zna kako se uzvraća.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (28, 36, 21, 'Žena prima svakog muža, premda je jedna djevojka od druge bolja.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (28, 36, 22, 'Ženska ljepota raduje oči, i to je najjača od svih ljudskih želja.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (28, 36, 23, 'Ako su dobrota i nježnost na njezinim usnama, muž joj nije kao ostali ljudi.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (28, 36, 24, 'Tko ima ženu posjeduje blago: ona mu je pomoć i stup potporni.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (28, 36, 25, 'Gdje nema ograde, pokradu imanje. Tko nema žene tužan je lutalac.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (28, 36, 26, 'Tko će vjerovati razbojniku koji leti od grada do grada?');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (28, 36, 27, 'Tako i čovjeku koji nema gnijezda, već počiva gdje ga zatekne noć.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (28, 36, 28, '');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (28, 36, 29, '');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (28, 36, 30, '');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (28, 36, 31, '');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (28, 37, 1, 'Svaki prijatelj veli: \"I ja sam ti prijatelj.\" Ali su mnogi samo po imenu prijatelji.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (28, 37, 2, 'Nije li sama smrtna žalost kad se drug ili prijatelj pretvori u neprijatelja?');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (28, 37, 3, 'O, sklonosti opaka, zašto si stvorena? Da prekriješ zemlju prijevarom?');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (28, 37, 4, 'U sreći se lažni drug raduje s prijateljem, a u času nesreće okreće se protiv njega.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (28, 37, 5, 'A pravi drug dijeli nevolju s prijateljem i kad do boja dođe, štita se laća.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (28, 37, 6, 'Ne zaboravljaj prijatelja vjerna u boju i ne zaboravi ga kad se obogatiš.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (28, 37, 7, 'Svaki savjetnik dijeli savjete, ali mnogi svjetuju sebi u prilog.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (28, 37, 8, 'Čuvaj se od onoga koji nudi savjet: ispitaj prije što on sam želi - jer on daje savjet na svoju korist - da on ne baci oko na tebe');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (28, 37, 9, 'pa ti veli: \"Dobar je tvoj put\", a potom iz prikrajka promatra nesreću tvoju.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (28, 37, 10, 'Ne svjetuj se s čovjekom koji te krivo gleda i ne otkrivaj zavidniku namjere svoje.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (28, 37, 11, 'Ne svjetuj se sa ženom o njezinoj suparnici, niti s kukavicom o ratu, niti s trgovcem o trgovini, niti s kupcem o prodaji, niti sa zavidnikom o zahvalnosti, niti sa samoživcem o milosrđu, niti s lijenčinom o bilo kakvu poslu, niti s prolaznim najamnikom o svršetku posla, niti s lijenim slugom o veliku radu: ne oslanjaj se na njih ni za kakav savjet.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (28, 37, 12, 'Nego se uvijek obrati na pobožnika o kome znadeš da vrši zapovijedi, koji je s tobom jedne duše i koji će nad tobom plakati kada posrneš.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (28, 37, 13, 'I na savjet srca svoga pazi, jer nemaš nikog vjernijeg od njega.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (28, 37, 14, 'Jer srce često pretkazuje čovjeku pouzdanije nego sedam stražara s vidikovca visokog.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (28, 37, 15, 'Ali se kraj svega toga moli Svevišnjem da te vodi stazom istine.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (28, 37, 16, 'Razbor je početak svakog posla, promišljanje prethodi poduzimanju.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (28, 37, 17, 'Korijen misli u srcu je, iz njega izrastaju četiri grane:');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (28, 37, 18, 'dobro i zlo, život i smrt, a jezik im je uvijek gospodar.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (28, 37, 19, 'Postoji čovjek kadar poučiti druge, a sebi je samom beskoristan.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (28, 37, 20, 'Drugi je opet spretan govornik, ali omražen, i takav će umrijeti od gladi:');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (28, 37, 21, 'jer nije stekao naklonosti Gospodnje i lišen je svake mudrosti.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (28, 37, 22, 'Postoji i mudrac sam sebi mudar, i plodovi su mu razbora na ustima pouzdani.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (28, 37, 23, 'Mudrac poučava svoj vlastiti puk, i plodovi su njegova razbora pouzdani.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (28, 37, 24, 'Mudar je čovjek pun blagoslova, i svi koji ga vide zovu ga sretnim.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (28, 37, 25, 'Malen je broj dana života čovječjeg, i nebrojeni su dani naroda izraelskog.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (28, 37, 26, 'Mudrac stječe povjerenje naroda svog i ime mu živi životom vječnim.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (28, 37, 27, 'Sine moj, dok si živ, kušaj narav svoju, vidi što joj šteti i to joj uskrati.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (28, 37, 28, 'Jer nije svima sve probitačno niti je svakomu sve po volji.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (28, 37, 29, 'Ne budi nezasitan u slasticama i ne budi lakom za jestvinom.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (28, 37, 30, 'Jer prekomjerno jelo donosi bolest i proždrljivost izaziva proljev.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (28, 37, 31, 'Mnogi pomriješe od neumjerenosti, a tko se čuva produžuje svoj život.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (28, 38, 1, 'Časti liječnika čašću koja mu pripada zbog njegove službe, jer je i njega Gospod stvorio.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (28, 38, 2, 'Liječenje od Svevišnjeg dolazi, kao što se dar od kralja dobiva.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (28, 38, 3, 'Znanje uzdiže glavu liječniku i moćnici ga poštuju.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (28, 38, 4, 'Gospod od zemlje pravi lijekove i razborit ih čovjek ne odbacuje.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (28, 38, 5, 'Nije li po drvetu voda postala slatka, pokazujuć\' tako svoju moć?');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (28, 38, 6, 'Ljudima je dao znanost da uzmognu slaviti snagu djela njegovih.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (28, 38, 7, 'Njima se liječi i bol ublažuje, od njih ljekarnik lijekove priprema.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (28, 38, 8, 'Tako nema kraja djelima njegovim i po njemu se blagostanje širi svijetom.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (28, 38, 9, 'Sine moj, u bolesti ne budi potišten, već se Bogu moli jer on zdravlje daje.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (28, 38, 10, 'Bježi od nepravde i ne budi pristran, i od svih grijeha očisti srce.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (28, 38, 11, 'Prinesi žrtvu blagomirisnu i spomen-žrtvu i pretio dar prema imanju svojem.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (28, 38, 12, 'Ali i liječniku mjesta daj, i njega je Gospod stvorio: nek\' nije daleko od tebe, jer i on je potreban.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (28, 38, 13, 'Katkad je spas u ruci njihovoj,');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (28, 38, 14, 'jer se i oni Bogu utječu da im poda milost izlječenja i lijek za spas života.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (28, 38, 15, 'Tko griješi pred Stvoriteljem svojim nek padne u ruke liječničke.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (28, 38, 16, 'Sine moj, roni suze nad mrtvim, tužaljkom prokukaj kao patnik skrhan: ukopaj mu tijelo prema običaju i ne uskrati počasti grobu njegovu.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (28, 38, 17, 'Gorko plači i žarko ridaj i pokaži žalost koju zaslužuje: jedan ili dva dana, da izbjegneš govorkanje, a potom se utješi od žalosti svoje.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (28, 38, 18, 'Jer od tuge dolazi prijeka smrt, i žalost slabi snagu životnu.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (28, 38, 19, 'Neka žalost prođe s pogrebom, jer je život u žalosti nepodnošljiv.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (28, 38, 20, 'Ne prepuštaj srce svoje žalosti: odagnaj je i misli na svoj svršetak.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (28, 38, 21, 'I ne zaboravi: povratka nema; njemu ne koristiš, a sebi udiš.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (28, 38, 22, 'Misli na njegovu kob koja je i tvoja: jučer meni, danas tebi.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (28, 38, 23, 'Kad mrtvac počine, nek\' počine i spomen njegov i utješi se kad izađe njegov duh.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (28, 38, 24, 'U dokolici je mudrost zakonoznanca, i tko je od poslova slobodan postaje mudar.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (28, 38, 25, 'Kako će omudriti onaj tko upravlja plugom i komu je sva slava u šiljku ostana, tko tjera volove i bavi se radom oko njih i koji govori samo o teladi:');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (28, 38, 26, 'um je njegov obuzet brazdama koje slijedi, a bdijenja mu prolaze u tovu junadi.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (28, 38, 27, 'Tako i svi radnici i rukotvorci koji rade i dan i noć: oni koji rezbare pečatnjake i trude se neprestano oko novih šara svesrdno teže za što većom sličnošću uzoru i bde noću da usavrše svoje djelo.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (28, 38, 28, 'Tako i kovač koji sjedi pokraj nakovnja i promatra sirovo željezo: dah ognja peče mu kožu, a on se oko vrela ognjišta napreže; zvuk čekića zaglušuje uho njegovo, oči upire u uzorak pred sobom; srcem misli na svršetak posla svog i noću bdi da ga usavrši.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (28, 38, 29, 'Tako i lončar koji sjedi kod posla svog i okreće točak nogama: uvijek je u brizi za djelo svoje i sve su mu kretnje odbrojane.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (28, 38, 30, 'Rukom daje oblik glini, a nogama je gnječi; srcem misli na laštenja i bdi noću da peć očisti.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (28, 38, 31, 'Svi se oni u ruke uzdaju, i svaki je vičan svome poslu.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (28, 38, 32, 'Bez njih se nijedan grad ne može sagraditi, a nema ni naselja ni putovanja.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (28, 38, 33, 'Ali njih ne pitaju u vijeću narodnom i ne ističu se u općini. Ne sjede na stolici sudačkoj i ne shvaćaju Zakona zavjetnoga.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (28, 38, 34, 'Ne ističu se naobrazbom ni zdravom rasudbom i nema ih među tvorcima mudrih izreka. Ali oni održavaju stvoreni svijet i molitva im je na djelo usmjerena.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (28, 39, 1, 'Ali je drukčije s onim koji posvećuje dušu svoju i razmišljanje svoje Zakonu Svevišnjega, istražuje mudrost drevnu i bavi se proroštvima.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (28, 39, 2, 'On pamti govore glasovitih muževa i prodire u tančine mudrih izreka;');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (28, 39, 3, 'istražuje skriveni smisao poslovica i bavi se tajnama prispodoba.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (28, 39, 4, 'On služi među velikašima i viđa se u prisutnosti vladara, putuje po zemljama drugih naroda, iskušava dobro i zlo među ljudima.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (28, 39, 5, 'U zoru srce svoje uzdiže Gospodu, Stvoritelju svome, moli se pred Svevišnjim: na molitvu otvara usta i moli milost za grijehe svoje.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (28, 39, 6, 'Ako to veliki Gospod hoće, napunja ga duhom razbora i on daždi riječima mudrosti i molitvom slavi Gospoda.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (28, 39, 7, 'Gospod upravlja savjetom i spoznajom njegovom, a on razmišlja o otajstvima Gospodnjim.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (28, 39, 8, 'On izlaže pouku koju je primio i hvali se Zakonom Saveza Gospodnjeg.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (28, 39, 9, 'Mnogi hvale umnost njegovu, nikad neće u zaborav pasti niti će mu spomen ikad propasti, nego će mu ime živjeti od pokoljenja do pokoljenja.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (28, 39, 10, 'Narodi će proglasiti mudrost njegovu i hvalom će ga slaviti zajednica.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (28, 39, 11, 'Ako dugo živi, ime mu nadvisuje tisuće ostalih, a ako umre, i to će dostajati.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (28, 39, 12, 'Još jednom želim iznijeti misli svoje jer sam njima ispunjen kao mjesec pun.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (28, 39, 13, 'Slušajte me, djeco pobožna, i cvjetajte kao ruža što niče na obali toka vodenog.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (28, 39, 14, 'Mirišite kao miris tamjanov, cvatite kao ljiljanov cvijet, širite miris i pjesmu pjevajte, slavite Gospoda za sva djela njegova.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (28, 39, 15, 'Dajte slavu imenu njegovu, hvalite ga i slavite pjesmama i harfom i ovako mu u pohvalu recite:');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (28, 39, 16, 'Kako su veličanstvena sva djela Gospodnja! I sve se naredbe njegove pravovremeno izvršuju. Ne smije se pitati: \"Što je ovo? Zašto to?\" jer sve će dobro doći u svoje vrijeme.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (28, 39, 17, 'Na riječ njegovu voda se kao nasip zaustavlja, i na besjedu usta njegovih nastaje spremište voda.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (28, 39, 18, 'Kad on zapovjedi štogod, volja mu se ispunja i nitko ne može umanjiti njegovo spasenje.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (28, 39, 19, 'Pred njim su djela svakog stvora i ništa nije skriveno očima njegovim.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (28, 39, 20, 'Njegov se pogled pruža od vječnosti do vječnosti i ništa nema čudesno pred očima njegovim.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (28, 39, 21, 'Ne smije se reći: \"Što je ovo? I zašto to?\" jer sve što je stvoreno svrhu ima.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (28, 39, 22, 'Kao što se blagoslov njegov prelijeva poput rijeke i natapa zemlju kao poplava,');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (28, 39, 23, 'tako je srdžba njegova baština narodima, kao kad je vode pretvorio u sol.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (28, 39, 24, 'Kao što su njegovi putovi ravni pobožnicima, tako su neprohodni opakima.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (28, 39, 25, 'Kao što je od početka stvoreno dobro za dobre, tako i zlo za opake.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (28, 39, 26, 'Najvažnije su potrebe ljudima za život voda i vatra, željezo i sol, brašno pšenično, mlijeko i med, sok grožđa, ulje i odijelo:');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (28, 39, 27, 'sve je to dobro dobrima, a pretvara se u zlo zlima.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (28, 39, 28, 'Ima vjetrova za kaznu stvorenih, sazda ih kao bičeve bijesa svoga; oni će u vrijeme svršetka snagu razviti i umiriti gnjev svoga Stvoritelja.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (28, 39, 29, 'Vatra i tuča, glad i kuga - sve je to za kaznu stvoreno.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (28, 39, 30, 'Očnjaci u zvijeri, štipavci i guje, i osvetni mač na propast bezbožnicima');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (28, 39, 31, 'vesele se zapovijedi njegovoj i pripravno čekaju na zemlji: i kad vrijeme dođe, ne opiru se riječi njegovoj.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (28, 39, 32, 'Stoga bijah od početka osvjedočen pa razmislih i zapisan u knjigu:');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (28, 39, 33, '\"Sva su djela Gospodnja dobra, svakoj potrebi Gospod u pravo vrijeme udovoljava.\"');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (28, 39, 34, 'Ne smije se reći: \"Ovo je gore nego ono\", jer sve je dobro u pravi čas.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (28, 39, 35, 'A sad iz puna srca i usta zapjevajte i blagoslovite ime Gospodnje!');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (28, 40, 1, 'Nevoljna je sudbina dodijeljena svima ljudima, težak jaram sinovima ljudskim od dana kad izađu iz utrobe majčine do dana kad se vrate majci svega živog.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (28, 40, 2, 'Predmet misli njihove, strah srca njihova - tjeskobno je iščekivanje dana smrtnoga.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (28, 40, 3, 'Od onoga koji sjedi na prijestolju slavnom do onoga koji sjedi u prahu i pepelu;');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (28, 40, 4, 'od onoga koji nosi krunu i grimiz do onoga koji nosi prtenu odjeću -');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (28, 40, 5, 'sve je gnjev, zavist, nevolja i nemir, strah od smrti, svađe i borba. I kad počiva na svojoj postelji, san mu noćni samo izmjenjuje brige:');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (28, 40, 6, 'tek što je legao, a ono u snu kao na svjetlosti danjoj opsjedaju ga strahotni prizori, kao bjegunca što je iz boja utekao.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (28, 40, 7, 'I kad se probudi u času izbavljenja, čudi se svojem ispraznomu strahu.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (28, 40, 8, 'Jer stvorovima svima, od ljudi do životinja, a sedmerostruko grešnicima - prijeti');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (28, 40, 9, 'smrt i krv, i boj i mač, nesreće, glad, patnja, kuga.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (28, 40, 10, 'Sve je to stvoreno za grešnike, i zbog njih je do potopa došlo.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (28, 40, 11, 'Sve što je iz zemlje u zemlju se vraća i što je iz vode došlo u more odlazi.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (28, 40, 12, 'Svako mito i nepravda propadaju, a poštenje traje dovijeka.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (28, 40, 13, 'Blago nepravedničko nestaje kao bujica i kao trijesak groma za nevremena.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (28, 40, 14, 'Kad otvori svoje ruke, on se raduje, tako i grešnici srljaju u svoju propast.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (28, 40, 15, 'Izdanak bezbožnički ne tjera mladice, jer nečisto korijenje nalazi samo tvrdo stijenje.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (28, 40, 16, 'Trska što raste na svakoj vodi i obali kosi se prije svake druge trave.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (28, 40, 17, 'A milost je kao perivoj blagoslova i milosrđe traje dovijeka.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (28, 40, 18, 'Nezavisan čovjek i radnik imaju ugodan život, ali od obojice bolji ima onaj tko pronađe blago.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (28, 40, 19, 'Djeca i sazidan grad proslavljuju ime, ali je nad obojim otkriće mudrosti. Stoka i vinogradi donose glasovitost, ali više od oboga uzorna žena.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (28, 40, 20, 'Vino i glazba vesele srce, ali još više ljubav prema mudrosti.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (28, 40, 21, 'Frula i harfa zaslađuju pjesmu, ali je nad obojim skladan glas.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (28, 40, 22, 'Ljepota i ljupkost vesele oči, ali još više zelenilo polja.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (28, 40, 23, 'Prijatelj ili drug - sretnu se u pravi čas, ali su nad obojicom žena i muž.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (28, 40, 24, 'Braća i pomoćnici u nevolji dobro dođu, ali od obojih bolje izbavlja milostinja.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (28, 40, 25, 'Zlato i srebro učvršćuju korak, ali je od obadvoga bolji dobar savjet.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (28, 40, 26, 'Bogatstvo i moć osnažuju srce, ali od obadvoga bolje strah Gospodnji. Sa strahom Gospodnjim čovjek sve ima i s njime mu ne treba nikakva pomoćnika.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (28, 40, 27, 'Strah je Gospodnji kao perivoj blagoslova: on čovjeka štiti više od svake slave.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (28, 40, 28, 'Sine moj, ne živi od prosjačenja; bolje je umrijeti nego prosjačiti.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (28, 40, 29, 'Čovjek koji neprestano gleda na tuđi stol ne živi životom života dostojnim. On kalja svoje grlo jelima tuđinskim, a obrazovan i odgojen čovjek toga se kloni.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (28, 40, 30, 'Slatko je prosjačenje usnama bestidnika, ali ga u utrobi pali kao vatra.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (28, 41, 1, 'O smrti, kako je gorka pomisao na te čovjeku koji živi sretno i usred dobara svojih, čovjeku koji živi spokojno i u svemu napreduje i još ima snage uživati raskoš!');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (28, 41, 2, 'O smrti, odluka je tvoja dobrodošla čovjeku ubogu i bez snage, istrošenu starcu, izmorenu brigama, nevjeričnu i na kraju strpljivosti.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (28, 41, 3, 'Ne boj se zakona smrti, sjeti se onih prije tebe i onih što će poslije doći.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (28, 41, 4, 'To je presuda Gospodnja svemu živom - i čemu se opirati volji Svevišnjega? Živio ti deset, stotinu ili tisuću godina, u Podzemlju ti neće predbacivati dužinu života.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (28, 41, 5, 'Opake su hulje sinovi grešnika i oni koji zalaze u nastambe bezbožničke.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (28, 41, 6, 'Baština djece grešničke na propast je osuđena, potomstvo njihovo predmet je vječna ukora.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (28, 41, 7, 'Bezbožna oca proklinju vlastita djeca, jer su zbog njega u sramoti.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (28, 41, 8, 'Teško vama, bezbožnici, koji zapostavljate Zakon Boga Svevišnjega.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (28, 41, 9, 'Ako ste se rodili, za prokletstvo se rodiste, a kad umrete, prokletstvo ćete baštiniti.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (28, 41, 10, 'Sve što je od zemlje u zemlju se vraća, tako i bezbožnici iz prokletstva u propast.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (28, 41, 11, 'Ljudi žale za svojim mrtvima, ali će opako ime grešnika nestati.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (28, 41, 12, 'Brini se za ime, jer ti ono ostaje dulje nego tisuće velikih zlatnih zaloga.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (28, 41, 13, 'Sretan život traje stanovit broj dana, ali časno ime ostaje zauvijek.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (28, 41, 14, 'Držite, djeco, pouke moje u miru. Skrivena mudrost i blago nevidljivo, kakva je korist od oboga?');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (28, 41, 15, 'Bolji je čovjek koji krije ludost svoju negoli koji krije mudrost svoju.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (28, 41, 16, 'Stidite se prema onome što vam govorim, jer nije dobro svakom stidu podlijegati niti svi jednako cijene sve.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (28, 41, 17, 'Pred ocem i majkom stidi se bludnosti i lÓaži pred poglavarom i moćnikom,');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (28, 41, 18, 'zločina pred sucem i knezom, bezakonja pred općinom i narodom,');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (28, 41, 19, 'nepravde pred drugom i prijateljem, krađe pred susjedstvom u kojem živiš.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (28, 41, 20, 'Pred istinom Božjom i zavjetom stidi se naslanjati lakte na stol,');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (28, 41, 21, 'prezirno primati i darivati i ne odgovarati onima koji te pozdravljaju;');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (28, 41, 22, 'stidi se piljiti u tuđu ženu i okrenuti leđa rođaku,');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (28, 41, 23, 'prisvojiti tuđi dio ili dar, udvarati se udatoj ženi,');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (28, 41, 24, 'biti prisan sa sluškinjom njezinom: ne prilazi njezinoj postelji!');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (28, 41, 25, 'Stidi se riječi pogrde pred prijateljima svojim i nemoj kuditi nakon darivanja,');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (28, 41, 26, 'ponavljati i širiti glasine i izdavati tajne.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (28, 41, 27, 'Tad ćeš biti istinski stidljiv i naći ćeš milost u očima sviju ljudi.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (28, 42, 1, 'Ali se ovoga nemoj stidjeti, ovoga ne krši zbog ljudskog obzira:');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (28, 42, 2, 'Zakona i Saveza Svevišnjega, presude koja daje pravdu i bezbožniku,');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (28, 42, 3, 'čista računa s drugom i suputnikom, diobe svoje baštine prijateljima,');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (28, 42, 4, 'točnosti u mjerilima i utezima, malena ili velika probitka,');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (28, 42, 5, 'dobitka u trgovačkim poslovima, stroge stege prema svojoj djeci i da do krvi išibaš opakoga slugu.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (28, 42, 6, 'Kad je žena radoznala, dobar je pečat; a gdje je mnogo ruku, zaključavaj.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (28, 42, 7, 'Kad što daješ, pazi na broj i težinu, i svaki izdatak i primitak zabilježi.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (28, 42, 8, 'Ne stidi se ukoriti glupana ili luđaka ili ishlapjela starca koji raspravlja s mladićima. Tako ćeš pokazati kako si uistinu obrazovan, i svi će ti odobravati.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (28, 42, 9, 'Kći je ocu potajna mora, briga za nju spavati mu ne da: u mladosti, strah da se neće udati, a kad se uda, da je muž ne zamrzi;');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (28, 42, 10, 'dok je djevica, da je tko ne zavede i da ne zatrudni u kući očevoj, a u kući muževljoj da se ne razbludi, i kad je već žena, da ne bude nerotkinja.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (28, 42, 11, 'Ako ti je kći neposlušna, dobro je pazi da ne načini od tebe ruglo neprijateljima tvojim, priču gradsku i predmet svačijeg klevetanja i da te ne obeščasti u očima sviju.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (28, 42, 12, 'Ne zaustavljaj pogleda ni pred čijom ljepotom i ne sjedaj sa ženama.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (28, 42, 13, 'Jer iz odijela izlazi moljac, a od žena ženska zloća.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (28, 42, 14, 'Bolja je zloća muška nego dobrota ženska; od žene potječe sramota i ruglo.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (28, 42, 15, 'Sad ću podsjetiti na djela Božja, i što sam vidio, to ću ispričati. Riječima Gospod stvori djela svoja, i sve se stvoreno pokorava volji njegovoj.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (28, 42, 16, 'Sunce sjajno sve obasjava, i slave je Gospodnje puno djelo njegovo.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (28, 42, 17, 'Gospod nije dao anđelima moć da govore o svim čudesima koja je Gospod, gospodar svega, čvrsto sazdao kako bi svemir opstao u slavi njegovoj.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (28, 42, 18, 'Izmjerio je dubinu bezdana i srca ljudskog i prozreo sve tajne njihove. Jer Svevišnji ima svoju spoznaju koja postoji i promotrio je znake vremena.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (28, 42, 19, 'On objavljuje prošlost i budućnost i otkriva stvari skrivene.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (28, 42, 20, 'Ni jedna mu misao promaći ne može, ni jedna se riječ ne može njemu skriti.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (28, 42, 21, 'On je uredio čudesna djela svoje mudrosti, jer je jedini od vječnosti do vječnosti. Niti mu se što može dodati niti oduzeti i njemu savjet ničiji ne treba.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (28, 42, 22, 'Kako li su divna sva djela njegova, kao sjajna iskra njihov je prizor.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (28, 42, 23, 'Sve to živi i traje dovijeka, i u svakoj prilici sve je poslušno.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (28, 42, 24, 'Sve je dvostruko, jedno prema drugome, i ništa nije stvorio nepotpuno.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (28, 42, 25, 'Jedno drugo izvrsnošću nadmašuje, i tko se može nasititi njegove krasote?');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (28, 43, 1, 'Ponos visina, blistavi svod, takva su nebesa u slavnom prizoru.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (28, 43, 2, 'Kad se sunce pomalja, izlazeći objavljuje: \"Divno je i čudesno djelo Svevišnjeg!\"');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (28, 43, 3, 'Kad je o podne, žari krug zemaljski, i tko bi izdržao žegu njegovu?');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (28, 43, 4, 'U peć treba puhati da se dobije toplina, a sunce sažiže planine tri puta snažnije; riga pare plamene i zrakama svojim zasljepljuje oči.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (28, 43, 5, 'Velik je Gospod koji ga načini i čije riječi požuruju njegov hod.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (28, 43, 6, 'I mjesec tako, uvijek točan, označuje vrijeme i vječni je znak.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (28, 43, 7, 'Mjesec označuje blagdane, to svjetlilo koje se smanjuje kad postane puno.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (28, 43, 8, 'Od njega mjesec dobiva svoje ime. On čudesno raste u mijenama svojim, stijeg vojske nebeske što blista na svodu nebesa.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (28, 43, 9, 'Sjaj je zvijezda ljepota neba, blistav ures visinama Gospodnjim.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (28, 43, 10, 'Po zapovijedi Svetoga, kako on odredi, one miruju i ne zamaraju se nikad od straže svoje.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (28, 43, 11, 'Pogledaj dugu i slavi Stvoritelja njezina, jer je tako veličanstvena u sjaju svojem.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (28, 43, 12, 'Preko nebesa prebacuje dični luk što ga razape ruka Svevišnjeg.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (28, 43, 13, 'Po zapovijedi njegovoj pada snijeg i munje požuruje svojom naredbom.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (28, 43, 14, 'Tako se otvaraju i riznice njegove iz kojih izlijeću oblaci kao ptice.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (28, 43, 15, 'Silom svojom drži oblake i mrvi ih u tuču.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (28, 43, 16, '[16a] Kad se on pojavi, gore se tresu,');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (28, 43, 17, '[17a] i kad grom njegov zagrmi, zemlja se uvija od bola. [16b]Po zapovijedi njegovoj puše južnjak, [17b] vijavica sjeverna i vihor olujni.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (28, 43, 18, 'Kao ptice prši njegov snijeg i pada kao jato skakavaca. Oko se divi ljepoti njegove bjeline i duh se zanosi praminjanjem njegovim.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (28, 43, 19, 'Inje pada kao sol na zemlju, i kad se dobro smrzne, kostriješi se kao bodlje.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (28, 43, 20, 'Kad zapuše hladni sjever, tad se led uhvati na vodi, spusti se na svaku mirnu vodu, koja se onda njime kao oklopom odjene.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (28, 43, 21, 'On guta gore i sažiže pustinju i kao oganj proždire bilje.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (28, 43, 22, 'Ali oblaci ubrzo sve liječe i poslije žege osvježava rosa.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (28, 43, 23, 'Namišlju je svojom ukrotio bezdan i po njemu razastro otoke.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (28, 43, 24, 'Pomorci pričaju o pogibeljima morskim i divimo se onomu što od njih čujemo:');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (28, 43, 25, 'jer i tu su neobična i prečudesna djela njegova, zvijeri svakojake i nemani morske.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (28, 43, 26, 'Njegovom pomoću sve se svršava dobro i sve se uređuje prema riječi njegovoj.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (28, 43, 27, 'Ma koliko da dodamo, ne bismo završili; jednom riječju: \"On je sve!\"');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (28, 43, 28, 'Odakle smoći dovoljno snage da ga slavimo, jer on je velik, iznad svih je djela svojih.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (28, 43, 29, 'Strašan je Gospod i veoma velik, i čudesna je moć njegova.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (28, 43, 30, 'Veličajte Gospoda u hvalama svojim koliko god možete, a on će vas uvijek nadmašivati; napregnite svu svoju snagu kad ga veličate, ne popuštajte, pa ipak nikad do kraja nećete doći.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (28, 43, 31, 'Jer tko ga je ikad vidio pa da opriča? I tko ga može proslaviti onako kako on zaslužuje?');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (28, 43, 32, 'Mnogo je otajstava većih nego su ova, jer smo vidjeli samo neka od djela njegovih!');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (28, 43, 33, 'Sve je stvorio Gospod, koji je mudrost dao pobožnima.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (28, 43, 34, '');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (28, 43, 35, '');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (28, 44, 1, 'Opjevajmo slavne muževe, pretke naše po njihovim pokoljenjima.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (28, 44, 2, 'Mnogo je slave podijelio Višnji i pokazao svoje veličanstvo od iskonskih dana.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (28, 44, 3, 'Jedni vladahu kraljevstvima svojim i bijahu poznati po svojoj snazi; drugi bijahu mudri savjetnici i izricahu riječi proročanske.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (28, 44, 4, 'Savjetom svojim upravljahu ljudima, razumijevanjem narodne mudrosti, i mudrim napucima svojeg nauka.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (28, 44, 5, 'Neki skladahu napjeve i pisahu pjesme;');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (28, 44, 6, 'drugi bijahu bogati i moćni živeći mirno u domovima svojim.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (28, 44, 7, 'Svi se oni proslaviše u svom vremenu i bijahu slava svojeg doba.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (28, 44, 8, 'Neki od njih ostaviše ime za sobom te se o njima još hvale pjevaju.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (28, 44, 9, 'A drugima opet nema spomena, iščezoše kao da nikad nisu niti postojali; sada su kao da ih nikad nije bilo, tako i djeca njihova za njima.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (28, 44, 10, 'Ali ovi bijahu ljudi pobožni čija se dobra djela ne zaboravljaju;');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (28, 44, 11, 'u potomcima njihovim ostade bogata baština što je oni namriješe.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (28, 44, 12, 'Djeca im se vjerno drže zavjeta, i potomstvo njihovo, zbog njih;');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (28, 44, 13, 'dovijeka njihova loza ostaje i ne briše se dika njihova;');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (28, 44, 14, 'u miru počivaju tijela njihova i ime živi za sva pokoljenja;');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (28, 44, 15, 'mudrost njihovu objavljuju puci i slavu njihovu naviješta općina.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (28, 44, 16, 'Henok se svidio Gospodu i bi prenesen, uzor obraćenja za sva pokoljenja.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (28, 44, 17, 'Noa bijaše savršen pravednik i u vrijeme gnjeva postade obnovitelj; po njemu je spašen ostatak na zemlji u doba Potopa.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (28, 44, 18, 'Vječni je Savez utemeljen s njim da više neće od potopa izginuti sve živo.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (28, 44, 19, 'Abraham, otac slavni mnoštva naroda, nitko mu u slavi nikad nije bio ravan;');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (28, 44, 20, 'on je čuvao zapovijed Svevišnjega i sklopio Savez s njim; on je taj Savez učvrstio svojim tijelom i u dan kušnje vjeran ostao.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (28, 44, 21, 'Zato mu je Gospod zakletvom obećao da će blagosloviti narode u potomstvu njegovu, da će ga umnožiti kao prah zemaljski i potomstvo mu uzvisiti kao zvijezde. I dati im zemlju u baštinu, od mora do mora, od Rijeke do krajeva zemaljskih.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (28, 44, 22, 'I Izaku je tako, zbog oca njegova Abrahama, zajamčio');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (28, 44, 23, 'blagoslov svih ljudi i utemeljio je Savez na glavi Jakovljevoj. I utvrdio ga u svojim blagoslovima i dao mu zemlju u baštinu: podijelio je na dijelove i razdijelio među dvanaest plemena.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (28, 45, 1, 'Od njega je potekao čovjek čestit koji je našao milost pred svima, drag Bogu i ljudima, Mojsije, blagoslovljena spomena!');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (28, 45, 2, 'Podijelio mu slavu kao i svetima i učinio ga moćnim, na užas neprijateljima.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (28, 45, 3, 'Na njegovu je riječ znamenja zaustavio i ukrijepio ga pred licem kraljeva; dao mu zapovijedi za narod njegov i otkrio mu nešto od svoje slave.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (28, 45, 4, 'Zbog njegove vjernosti i poniznosti posveti ga, izabra ga jedinog između sviju ljudi;');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (28, 45, 5, 'dopusti mu da čuje glas njegov i uvede ga u tamu; dade mu zapovijedi licem u lice, Zakon života i spoznaje, da Jakova uči Savezu i Izraela naredbama njegovim.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (28, 45, 6, 'Potom uzvisi Arona, sveca poput Mojsija, brata njegova, iz plemena Levijeva.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (28, 45, 7, 'Vječni Savez sklopi s njim i dade mu svećeništvo naroda. Usreći ga odjećom ukrasnom, obuče ga u odoru slave.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (28, 45, 8, 'Odjenu ga dičnim savršenstvom i opremi bogatom odjećom: gaćama, haljom i oplećkom.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (28, 45, 9, 'Obloži ga mogranjem i brojnim zvončićima zlatnim uokolo, da zveckaju pri koračanju njegovu, da im se u Svetištu čuje zvon na opomenu sinovima naroda njegova.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (28, 45, 10, 'I svetu odjeću od zlata, grimiznu, svu izvezenu; oplećak sudački, Urim i Tumim, od upletena purpura, djelo vješta rukotvorca;');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (28, 45, 11, 'drago kamenje, urezano kao pečatnjaci u zlatnu okovu, djelo draguljara, kao opomenu s natpisom urezanim, prema broju plemena Izraelovih.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (28, 45, 12, 'I krunu zlatnu na kapi, ukrašenu pečatom posvete, ures vrhunski, djelo veličanstveno, ukrase, očima u nasladu.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (28, 45, 13, 'Nitko nikad sličnih nije vidio, i nikada ih nije tuđinac oblačio, nego samo sinovi njegovi i odvjeci njegovi zauvijek.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (28, 45, 14, 'Njegove žrtve potpuno se spaljuju, trajno, dvaput svakog dana.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (28, 45, 15, 'Njemu Mojsije dade svećeničku vlast i svetim ga uljem pomaza, i to mu bijaše vječni Savez i potomstvu njegovu sve dok nebesa traju, da mu služi i bude svećenikom i da blagoslivlja narod u ime Gospodnje.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (28, 45, 16, 'Izabra ga između svih živih da mu prinosi žrtvu i tamjan, da mu pali miris ugodni za spomen i da očišća sinove Izraelove.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (28, 45, 17, 'Još mu svoje zapovijedi dade i povjeri mu odredbe Zakona da pouči Jakova naredbama njegovim, da prosvijetli Izraela njegovim Zakonom.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (28, 45, 18, 'Ali se na njega razgnjeviše neprijatelji i pozavidješe mu u pustinji, ljudi Datanovi i Abiramovi, Korah i njegovi u mržnji i gnjevu.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (28, 45, 19, 'I vidje Gospod i rasrdi se i uništi ih žarom svoje srdžbe. Posla na njih čudesa i sažeže ih plamenim ognjem.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (28, 45, 20, 'I umnoži tako slavu Aronu i dade mu baštinu njegovu, odredi mu pretilinu prvina, prije svega kruha u izobilju.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (28, 45, 21, 'Tako se oni hrane žrtvama Gospodnjim, koje Gospod pokloni njemu i potomstvu njegovu.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (28, 45, 22, 'Samo u zemlji on baštine nema, nema svog dijela među narodom, jer Gospod je njegov dio i baština.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (28, 45, 23, 'I Pinhas, sin Eleazarov, treći je po slavi zbog revnosti svoje u strahu Gospodnjem. Jer kad se narod pobunio, postojan je bio i plemenito smiona srca, i tako je stekao oproštenje Izraelu.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (28, 45, 24, 'Zato bi Savez mira zapečaćen s njim, da bude poglavar Svetišta i naroda svoga te njemu i potomstvu njegovu pripadne dostojanstvo velikog svećeništva za sva vremena.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (28, 45, 25, 'Učinio je Savez i s Davidom, sinom Jišaja, iz plemena Judina, ali baština kraljevska od oca samo jednom sinu ostaje, dok baština Aronova ostaje svemu potomstvu njegovu.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (28, 45, 26, 'Zato neka vam sada Gospod mudrost u srce posadi da narodu njegovu pravedno sudite, da vrline predačke nikad ne nestanu i da slava njihova prijeđe na potomke njihove.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (28, 46, 1, 'Junak u boju bijaše Jošua, sin Nunov, nasljednik Mojsijev u službi proročkoj, koji valjano zasluži svoje ime i bi veliki izbavitelj izabranog naroda, osvetivši se drskim neprijateljima i uspostavivši Izraela na baštini njegovoj.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (28, 46, 2, 'Kako li krasan bijaše kad bi digao ruku i mačem zamahnuo protiv gradova!');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (28, 46, 3, 'Tko je ikad imao njegovu odlučnost? On je vodio bojeve Gospodnje.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (28, 46, 4, 'Nije li po njemu sunce zastalo i od jednog dana postala dva?');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (28, 46, 5, 'Jer je prizvao Boga Svevišnjega u nevolji kada ga odasvud pritijesniše neprijatelji, i usliša ga veliki Gospod i pusti krupnu i snažnu tuču.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (28, 46, 6, 'Bacio se na narod dušmanski i protivnike pobio na Strmini: da bi poznali puci snagu njegova oružja i spoznali da je Gospod protivnik njihov.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (28, 46, 7, 'I jer je vjerno išao za Svemogućim i u dane Mojsijeve ljubav dokazao - on i Kaleb, sin Jefuneov, koji se opriješe kad se zbor pobunio, odvrativši narod od grijeha i utišavši glasove pobune.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (28, 46, 8, 'Zato je i sačuvao samo ovu dvojicu, od šest stotina tisuća pješaka, da ih uvede u baštinu njihovu, u zemlju kojom teče med i mlijeko.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (28, 46, 9, 'Još je Kalebu dao snagu, koja s njime do starosti ostade, te se mogao verati po visinama zemaljskim, koje su baština potomcima njegovim,');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (28, 46, 10, 'neka bi spoznao sav Izrael da je dobro ići vjerno za Gospodom.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (28, 46, 11, 'I suci, svaki po svom imenu, koji uvijek bijahu srca vjerna i koji se ne odmetnuše od Boga - da je blagoslovljen spomen njihov.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (28, 46, 12, 'Neka im kosti procvatu u grobu i neka se imena tih slavnih ljudi pomlade u sinovima njihovim.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (28, 46, 13, 'Samuel bijaše miljenik svojemu Gospodu, prorok Gospodnji, on utemelji kraljevstvo i pomaza vladare nad svojim narodom.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (28, 46, 14, 'Po Zakonu Gospodnjem upravljaše općinom, i Gospod je pohodio Jakova.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (28, 46, 15, 'Zbog vjernosti njegove priznavahu ga prorokom, u govorima se pokazivaše pouzdan vidjelac.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (28, 46, 16, 'I on prizva Boga u nevolji kada ga odasvud pritisnuše dušmani prinoseći mliječno janješce.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (28, 46, 17, 'Tada zagrmje Gospod s neba i u strašnoj lomljavi začu glas njegov;');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (28, 46, 18, 'porazio je vođe dušmanske i satro knezove filistejske.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (28, 46, 19, 'I kad je polazio na počinak vječni, posvjedočio je pred Gospodom i pomazanikom njegovim: \"Ni od koga nikad ne uzeh ništa, čak ni potplate obične.\" I nitko ga nije optužio.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (28, 46, 20, 'A kad je usnuo, proreče još jednom i objavi kralju njegov kraj. I ispod zemlje podignu svoj glas proročki da izbriše opačinu s naroda.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (28, 47, 1, 'Poslije njega ustade Natan da prorokuje u vrijeme Davidovo.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (28, 47, 2, 'Kao što se pretilina odlučuje od pričesnice, tako bi David odabran od sinova Izraelovih.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (28, 47, 3, 'Igraše se s lavom kao s jarićima i s medvjedima kao s janjcima;');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (28, 47, 4, 'zar nije još kao dječak ubio diva i skinuo sramotu s naroda kad je iz praćke bacio kamen i slomio oholost Golijata?');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (28, 47, 5, 'Jer i on prizva Boga Svevišnjega, koji mu je dao snagu desnici, da obori junaka vješta bojevima i podigne jakost narodu svome.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (28, 47, 6, 'Zato mu je dana slava od deset tisuća, i slavljahu ga dok blagoslivljaše Gospoda, i ponudiše mu krunu slavnu,');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (28, 47, 7, 'jer on svuda porazi neprijatelje i uništi protivnike Filistejce i slomi silu njihovu do današnjega dana.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (28, 47, 8, 'U svakome svom djelu slavio je Svetog Svevišnjeg riječima hvale; pjevao je svim srcem svojim i ljubio Tvorca svoga.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (28, 47, 9, 'Pred žrtvenik je postavio glazbala da zvucima njihovim zasladi pjesmu.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (28, 47, 10, 'Blagdanima je sjajnost dodao i savršeno uresio svetkovine, proslavljao sveto ime Gospodnje, i Svetište je odzvanjalo već od zore.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (28, 47, 11, 'Zato mu Gospod grijehe oprosti i podiže dovijeka silu njegovu i dade mu Savez kraljevski, slavni prijestol u Izraelu.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (28, 47, 12, 'Mudar ga je sin naslijedio, koji se, zbog njega, nadaleko proširio.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (28, 47, 13, 'Salomon kraljevaše u vrijeme mirno, i Bog mu dade mir odasvuda, da je uzmogao sazdati Dom imenu njegovu i podići vječno Svetište.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (28, 47, 14, 'Kako li si mudar bio za svoje mladosti i prepun spoznaje poput rijeke!');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (28, 47, 15, 'Prekrio si zemlju umom svojim i ispunio je tajanstvenim izrekama.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (28, 47, 16, 'Ime ti se pročulo do dalekih otoka i stekao si ljubav svojim mirom.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (28, 47, 17, 'Začudio si svijet pjesmama svojim, pričama, poslovicama i odgovorima.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (28, 47, 18, 'U ime Gospodina Boga, koji se Bogom Izraela zove, nakupio si zlata kao kositra i namnožio srebra kao olova.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (28, 47, 19, 'A slabine si svoje potom priklonio ženama i postao rob svoga tijela.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (28, 47, 20, 'Ljagom si okaljao slavu svoju i oskvrnuo svoj rod, navukao si gnjev na porod svoj, i nevolju svojim potomcima.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (28, 47, 21, 'Kraljevstvo se nadvoje rascijepilo: i od Efrajima izađe pobunjena vlast.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (28, 47, 22, 'Ipak Bog nije odbacio milosti svoje, niti je pogazio riječi svoje: izabranika svoga nije lišio potomstva te nije istrijebio roda onom koji ga je ljubio, već je dao Ostatak Jakovu i domu Davidovu korijen od njega.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (28, 47, 23, 'I počinuo je Salomon kraj otaca svojih, ostavivši jednog od svojih kao nasljednika, najglupljeg od čitava naroda, čovjeka bez razbora: Roboama, koji je savjetom svojim narod pobunio.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (28, 47, 24, 'A zatim dođe Jeroboam, sin Nabatov, koji navede na grijeh Izraela i uputi Efrajima na put zloće. Od tada se njihovi grijesi toliko namnožiše te ih otjeraše iz zemlje njihove.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (28, 47, 25, 'Jer okušavahu svaku vrstu opačine, sve dok ih osveta ne snađe.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (28, 48, 1, 'I usta prorok Ilije kao oganj, riječ mu plamtjela kao buktinja.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (28, 48, 2, 'On je na njih donio glad i revnošću je svojom umanjio njihov broj.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (28, 48, 3, 'Po riječi je Božjoj nebo zatvorio i tri puta oganj s neba sveo.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (28, 48, 4, 'Kako li si strašan bio, Ilija, u čudesima svojim! I može li se itko dičiti koliko ti?');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (28, 48, 5, 'Podigao si mrtva od smrti iz Podzemlja po riječi Svevišnjeg.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (28, 48, 6, 'Bacio si u propast kraljeve i vukao odličnike s odra njihova.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (28, 48, 7, 'Na Sinaju si čuo ukore i sud osvetni na Horebu.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (28, 48, 8, 'Pomazao si kraljeve osvetničke i proroka sebi za nasljednika.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (28, 48, 9, 'Podignut si bio u vihoru ognja, u kolima s plamenim konjima.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (28, 48, 10, 'Određen si u prijetnjama budućim da umiriš srdžbu Božju prije no što ona provali, da obratiš srca otačka sinovima i da obnoviš plemena Jakovljeva.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (28, 48, 11, 'Blago onomu koji će te vidjeti i onima koji su usnuli u ljubavi, jer i mi ćemo posjedovati život.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (28, 48, 12, 'Kad je vihor zastro Iliju, napuni se duhom njegovim Elizej: za života ga nijedan vladar ne mogaše pobijediti i nitko ga ne mogaše podjarmiti.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (28, 48, 13, 'Ništa mu ne bijaše teško, i iz groba mu je tijelo prorokovalo.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (28, 48, 14, 'Za života je čudesa činio, a u smrti svojoj djela divotna.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (28, 48, 15, 'Ali se kraj svega toga narod nije pokajao niti se ostavio grijeha svojih, dok ne bi izagnan iz domaje i rasijan po svim zemljama svijeta;');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (28, 48, 16, 'samo je nešto ljudi ostalo, s vladarom iz kuće Davidove. Neki su od njih pravo činili pred Gospodom, a drugi opet gomilahu grijeh na grijeh.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (28, 48, 17, 'Ezekija utvrdi grad svoj i dovede vodu sred njega, željezom prokopa pećine i sagradi spremišta vodena.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (28, 48, 18, 'Za vijeka se njegova diže Sanherib i posla Rabsaka, koji diže ruku na Sion i u oholosti svojoj huljaše.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (28, 48, 19, 'Tada su im drhtala srca i ruke i podnosili su muke kao žene u trudovima;');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (28, 48, 20, 'ali prizvaše milostivog Boga i podigoše ruke svoje prema njemu. I Sveti je s neba brzo uslišio njihov glas i spasio ih rukom Izaijinom,');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (28, 48, 21, 'razbio je logor asirski, i njegov ih anđeo sve pobi.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (28, 48, 22, 'Jer je Ezekija činio što je Gospodu milo i držao se putova Davida, oca svojeg, kako mu je zapovjedio prorok Izaija, velik i pouzdan u viđenju svojem.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (28, 48, 23, 'U dane se njegove sunce povratilo, on je kralju produžio život.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (28, 48, 24, 'U silini duha vidio je stvari posljednje i tješio je žalobne na Sionu.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (28, 48, 25, 'Objavio je budućnost sve do kraja vremena i najavio tajne stvari prije nego se dogodiše.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (28, 49, 1, 'Spomen na Jošiju je kao smjesa mirisa, pripravljena umijećem mirisarskim; svačijim je ustima kao med sladak i kao glazba na vinskoj gozbi.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (28, 49, 2, 'Pravim je putem kročio da obrati narod i zatro je gnusnu bezbožnost.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (28, 49, 3, 'Srce je svoje upravio prema Gospodu i u bezbožno je vrijeme osnažio pobožnost.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (28, 49, 4, 'Osim Davida, Ezekije i Jošije, svi ostali gomilahu opačinu na opačinu. Jer napustiše Zakon Svevišnjega, nestalo je kraljeva judejskih.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (28, 49, 5, 'Snagu svoju dadoše drugima i slavu svoju tuđinskom narodu.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (28, 49, 6, 'Spališe sveti izabrani Grad i opustošiše ceste njegove,');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (28, 49, 7, 'po riječi Jeremijinoj, jer ga zlostavljahu, iako bijaše prorok posvećen u utrobi materinoj, da istrijebi i obara, zatire, ali i da sagradi i utvrđuje.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (28, 49, 8, 'Ezekiel je vidio prizor slave koji mu je Bog pokazao na kolima kerubinskim.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (28, 49, 9, 'Jer se sjetio neprijatelja pred likom nevremena, na korist onih koji se drže putova pravednih.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (28, 49, 10, 'A što se tiče dvanaest proroka, procvale im kosti iz rake njihove, jer su utješili Jakova i izbavili ga vjerom i nadom.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (28, 49, 11, 'Kako proslaviti Zerubabela? On bijaše kao pečatnjak na desnici.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (28, 49, 12, 'A takav bi i Jošua, sin Josedekov: oni u svoje vrijeme sagradiše Dom i podigoše Gospodu sveti Hram, određen za vječnu slavu.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (28, 49, 13, 'Velik je i spomen na Nehemiju, koji je podigao naše zidove razvaljene, postavio vrata i prijevornice i obnovio naše domove.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (28, 49, 14, 'Malo ih je bilo stvorenih na zemlji kao Henok, on je bio uznesen sa zemlje.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (28, 49, 15, 'A je li se ipak rodio čovjek kao Josip? Vođa braći svojoj, potpora narodu svojem. Kosti su mu posjećene.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (28, 49, 16, 'Još i Šem i Šet bijahu slavljeni među ljudima, ali je Adam iznad svih živih stvorova.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (28, 50, 1, 'Šimun, Sin Onijin, veliki svećenik, za svoga je života popravio Dom, u svoje je vrijeme učvrstio Hram.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (28, 50, 2, 'Položio temelje dvostruke visine i visoka kruništa oko Svetišta.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (28, 50, 3, 'U njegovo je vrijeme vodeno spremište iskopano, jezero poput mora golemo.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (28, 50, 4, 'U brizi da narod izbavi od propasti, utvrdio je grad protiv opsade.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (28, 50, 5, 'Kako li krasan bješe, okružen gomilom ljudi, kad bi izašao iza zastora Doma?');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (28, 50, 6, 'Kao zvijezda Danica među oblacima i kao mjesec pun;');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (28, 50, 7, 'kao sunce koje obasjava Hram Svevišnjega i kao sjajna duga na blistavim oblacima;');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (28, 50, 8, 'kao ruža u proljetne dane i kao ljiljan kraj izvora; kao grana tamjanova za žara ljetnoga');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (28, 50, 9, 'i kao plamen i kad u kadionici; kao vrč od kovana zlata, optočen mnogovrsnim dragim kamenjem;');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (28, 50, 10, 'kao maslina puna plodova i kao čempres što se diže u oblake.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (28, 50, 11, 'Kad bi na se metnuo krasnu odjeću i obukao se u divne haljine, i kad bi se uspinjao na sveti žrtvenik i ispunio trijem Svetišta svojim veličanstvom;');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (28, 50, 12, 'kad je primao žrtvene dijelove iz ruku svećenika, a sam stajao kod ognjišta oltarskog okružen vijencem braće svoje kao mladi cedar libanonski: okruživahu ga kao grane palmove');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (28, 50, 13, 'svi sinovi Aronovi u slavi svojoj, sa prinosima Gospodnjim na rukama, pred svim zborom Izraelovim.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (28, 50, 14, 'Dok je on vršio službu kod oltara, prinosili su po redu prinose Svevišnjem, Svevladaru;');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (28, 50, 15, 'pružio bi ruku svoju za posudom i prolio soka od grožđa, izlivši ga na podnožje oltarsko za ugodni miris Svevišnjem Kralju svega.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (28, 50, 16, 'Klicali bi tad sinovi Aronovi i trubili u trublje od tučene kovine i ječali jekom silnom u spomen pred Svevišnjim.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (28, 50, 17, 'I tada bi sav narod odjednom pao na zemlju ničice da se pokloni Gospodu, Svevladaru, Bogu Svevišnjem.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (28, 50, 18, 'A pjevači bi zapjevali pjesme hvalbenice: sladak bijaše zvuk mnoštva tih glasova,');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (28, 50, 19, 'dok se narod utjecao Bogu Svevišnjem moleći se pred Milosrdnim dok se ne bi svršila služba Gospodnja i obred priveo kraju.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (28, 50, 20, 'Potom bi sišao i podigao ruke svoje nad svim zborom sinova Izraelovih da blagoslov Gospodnji svojim usnama izusti i prodiči se njegovim imenom.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (28, 50, 21, 'I još jednom svi bi pali ničice da prime blagoslov Svevišnjeg.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (28, 50, 22, 'A sada blagoslovite Boga svemira, koji čini čudesa svagdje, koji uzdiže naše dane od utrobe majčine i čini s nama po milosti svojoj.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (28, 50, 23, 'On neka nam dadne radosno srce i podari mir našem vremenu, u Izraelu, na vijeke vijekova.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (28, 50, 24, 'Neka milost njegova bude trajno s nama i neka nas u naše vrijeme izbavi.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (28, 50, 25, 'Na dva se naroda gnuša moja duša, a treći i nije narod:');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (28, 50, 26, 'na žitelje Seirske gore i na Filistejce i na ludi puk koji živi u Šekemu.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (28, 50, 27, 'Pouku u mudrosti i znanosti zapisao je u knjigu ovu Isus, sin Sirahov, Eleazar, iz Jeruzalema, koji je kao kišu izlio mudrost svojeg srca.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (28, 50, 28, 'Blago čovjeku koji o ovome razmišlja i primajući to k srcu postaje mudar.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (28, 50, 29, 'Bude li postupao prema tome, u svemu će biti moćan, jer je svjetlost Gospodnja njegov put.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (28, 51, 1, 'Slavit ću te, Gospodaru, Kralju, i hvalit ću te, Bože, Spasitelju moj. Zahvaljujem imenu tvojem,');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (28, 51, 2, 'jer ti si bio zaštitnik i pomoćnik moj i spasio si tijelo moje od propasti, od zamke prijevarna jezika, od usana što laži kuju i pred onima što su okolo mene bio si zaštitnik i pomoćnik moj.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (28, 51, 3, 'Po velikom milosrđu i imenu svom izbavio si me od ujeda onih koji bi me proždrli, iz ruku onih koji mi o glavi rade, od mnogih kušnja koje pretrpjeh,');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (28, 51, 4, 'od gušenja u vatri koja me okružila, iz središta ognja koji nisam potpalio,');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (28, 51, 5, 'iz duboke utrobe Podzemlja, od nečista jezika i lažljive riječi,');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (28, 51, 6, 'od potvore nepravedna jezika pred kraljem. Duša moja bijaše blizu smrti i život moj na pragu Podzemlja.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (28, 51, 7, 'Okruživahu me sa svih strana i nije bilo nikoga da mi pomogne; pogledom sam pomoć ljudi tražio, ali uzalud.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (28, 51, 8, 'Tad se sjetih milosrđa tvojeg, o Gospode, i djela tvojih još odiskona, kako izbavljaš one koji te strpljivo čekaju i spasavaš ih iz ruku neprijateljskih.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (28, 51, 9, 'Tad podigoh sa zemlje glas svoj i zamolih spas od smrti,');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (28, 51, 10, 'zazvah Gospodina, oca mojega Gospodina: \"Ne ostavi me u dan nevoljni, u vrijeme moje nemoći protiv oholih. - Slavit ću ime tvoje bez prestanka i zahvalnu ti hvalu pjevati.\"');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (28, 51, 11, 'I bi molba moja uslišana, izbavio si me od propasti, spasio me od vremena zloće.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (28, 51, 12, 'I stoga ću te hvaliti i slaviti i blagoslivljati ime Gospodnje.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (28, 51, 13, 'Kad još bijah mladić, prije svojih putovanja molio sam otvoreno za mudrost u molitvama.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (28, 51, 14, 'Pred vratima Svetišta za nju sam molio i do posljednjeg ću dana tragati za njom.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (28, 51, 15, 'Od njena cvata pa do sazrela grozda radovalo joj se srce moje. Noga je moja kročila pravim putem i tražio sam mudrost od svoje mladosti.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (28, 51, 16, 'Prignuvši malo uho, naučih je i stekoh mnogu pouku.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (28, 51, 17, 'Po njoj uznapredovah i slavu ću dati onomu koji me podari mudrošću.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (28, 51, 18, 'Jer odlučih u djelo je provesti, žarko za dobrom tragah i neću se stidjeti.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (28, 51, 19, 'Duša se moja za nju borila, pomno sam se držao Zakona. Pružao sam ruke prema nebu i oplakivao što je ne poznam.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (28, 51, 20, 'Usmjerih svoju dušu prema njoj i nađoh je u čistoći. Od početka joj posvetih svoje srce, i neću nikad biti napušten.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (28, 51, 21, 'I utroba mi uzdrhta od čežnje za njom, i stoga stekoh valjano blago.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (28, 51, 22, 'Za plaću mi je Gospod jezik podario: njime ću ga slaviti.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (28, 51, 23, 'Priđite k meni, vi nepoučeni, u mojoj školi sjedite.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (28, 51, 24, 'Zašto da u tom oskudijevate, i da vam duše toliko žeđaju?');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (28, 51, 25, 'Otvorih svoja usta i rekoh: \"Kupujte je bez novaca,');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (28, 51, 26, 'podmetnite vrat svoj pod njen jaram i neka vam duše prihvate pouku. Tko je traži - blizu mu je, i čovjek odan nalazi je.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (28, 51, 27, 'Pogledajte očima svojim: kako sam se malo trudio, a mnogo spokoja stekao.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (28, 51, 28, 'Kupujte pouku velikom svotom novca, njome ćete steći mnogo zlata.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (28, 51, 29, 'Nek\' se duša vaša raduje u milosrđu Gospodnjem, i nikad se ne stidite hvaliti ga.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (28, 51, 30, 'Učinite djelo svoje prije određena vremena: u svoje vrijeme dat će vam on vašu plaću.\" Mudrost Isusa, sina Sirahova.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (29, 1, 1, 'Viđenje Izaije, sina Amosova, koje je imao o Judeji i Jeruzalemu u dane Uzije, Jotama, Ahaza i Ezekije, kraljeva judejskih.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (29, 1, 2, 'Čujte, nebesa, poslušaj, zemljo, jer Jahve govori: \"Sinove sam ti odgojio, podigao, al\' se oni od mene odvrgoše.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (29, 1, 3, 'Vo poznaje svog vlasnika, a magarac jasle gospodareve - Izrael ne poznaje, narod moj ne razumije.\"');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (29, 1, 4, 'Jao, grešna li naroda, puka u zlu ogrezla, roda zlikovačkog, pokvarenih sinova! Jahvu ostaviše, prezreše Sveca Izraelova, njemu su okrenuli leđa.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (29, 1, 5, 'TÓa gdje da vas još udarim, odmetnici tvrdokorni? Sva je glava bolna, srce iznemoglo;');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (29, 1, 6, 'od pete do glave nidje zdrava mjesta, već ozljede, modrice, otvorene rane, ni očišćene, ni povijene, ni uljem ublažene.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (29, 1, 7, 'Zemlja vam opustje, gradove oganj popali, njive vam na oči haraju tuđinci - pustoš k\'o kad propade Sodoma.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (29, 1, 8, 'Kći sionska ostade kao koliba u vinogradu, kao pojata u polju krastavaca, kao grad opsjednut.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (29, 1, 9, 'Da nam Jahve nad Vojskama ne ostavi Ostatak, bili bismo k\'o Sodoma, Gomori slični.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (29, 1, 10, 'Čujte riječ Jahvinu, glavari sodomski, poslušaj zakon Boga našega, narode gomorski!');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (29, 1, 11, '\"Što će mi mnoštvo žrtava vaših?\" - govori Jahve. - \"Sit sam ovnujskih paljenica i pretiline gojne teladi. I krv mi se ogadi bikova, janjaca i jaradi.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (29, 1, 12, 'Kad mi lice vidjet\' dolazite, tko od vas ište da gazite mojim predvorjima?');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (29, 1, 13, 'Prestanite mi nositi ništavne prinose, kad mi omrznu. Mlađaka, subote i sazive - ne podnosim zborovanja i opačine.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (29, 1, 14, 'Mlađake i svetkovine vaše iz sve duše mrzim - teški su mi, podnijet\' ih ne mogu!');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (29, 1, 15, 'Kad na molitvu ruke širite, je od vas oči odvraćam. Molitve samo množite, ja vas ne slušam. Ruke su vam u krvi ogrezle,');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (29, 1, 16, 'operite se, očistite. Uklonite mi s očiju djela opaka, prestanite zlo činiti!');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (29, 1, 17, 'Učite se dobrim djelima: pravdi težite, ugnjetenom pritecite u pomoć, siroti pomozite do pravde, za udovu se zauzmite.\"');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (29, 1, 18, '\"Hajde, dakle, da se pravdamo,\" govori Jahve. \"Budu l\' vam grijesi kao grimiz, pobijeljet će poput snijega; kao purpur budu li crveni, postat će kao vuna.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (29, 1, 19, 'Htjednete l\' me poslušati, uživat ćete plodove zemaljske.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (29, 1, 20, 'U buntovništvu ako ustrajete, proždrijet će vas mač.\" Tako usta Jahvina govorahu.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (29, 1, 21, 'Kako li posta bludnicom tvrđa vjerna? Bješe puna pravičnosti, pravda u njoj stolovala, a sad - ubojice.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (29, 1, 22, 'Srebro ti se u trosku obratilo, vino ti se razvodnjelo.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (29, 1, 23, 'Knezovi se tvoji odmetnuli, s tatima se pobratili. Svi za mitom hlepe, za darovima lete. Siroti pravdu uskraćuju, udovička parnica ne stiže k njima.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (29, 1, 24, 'Stog ovako govori Jahve, Gospod nad Vojskama, Junak Izraelov: \"Ah, kad se iskalim na protivnicima i osvetim dušmanima!');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (29, 1, 25, 'Kada na te ruku pružim, da lužinom tvoju trosku očistim, da iz tebe uklonim olovo!');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (29, 1, 26, 'Da ti opet postavim suce kao negda, savjetnike kao u početku, pa da te zovu Gradom pravednim, Tvrđom vjernosti.\"');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (29, 1, 27, 'Sud pravedni otkupit će Sion, a pravda obraćenike njegove.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (29, 1, 28, 'Otpadnici i grešnici skršit će se zajedno, a oni što Jahvu napuštaju poginut će.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (29, 1, 29, 'Da, stidjet ćete se zbog hrastova što ih sad obožavate i crvenjet ćete zbog gajeva u kojima sad uživate.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (29, 1, 30, 'Jer, bit ćete poput hrasta osušena lišća i poput gaja u kojem vode nema.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (29, 1, 31, 'Junak će biti kučina, a iskra djelo njegovo, zajedno će izgorjeti, a nikoga da ugasi.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (29, 2, 1, 'Viđenje Izaije, sina Amosova, o Judeji i Jeruzalemu:');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (29, 2, 2, 'Dogodit će se na kraju dana: Gora Doma Jahvina bit će postavljena vrh svih gora, uzvišena iznad svih bregova. K njoj će se stjecati svi narodi,');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (29, 2, 3, 'nagrnut će mnoga plemena i reći: \"Hajde, uziđimo na Goru Jahvinu, pođimo u Dom Boga Jakovljeva! On će nas naučiti svojim putovima, hodit ćemo stazama njegovim. Jer će iz Siona Zakon doći, iz Jeruzalema riječ Jahvina.\"');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (29, 2, 4, 'On će biti sudac narodima, mnogim će sudit\' plemenima, koji će mačeve prekovati u plugove, a koplja u srpove. Neće više narod dizat\' mača protiv naroda nit\' se više učit\' ratovanju.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (29, 2, 5, 'Hajde, dome Jakovljev, u Jahvinoj hodimo svjetlosti!');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (29, 2, 6, 'Da, ti si svoj odbacio narod, dom Jakovljev, jer je pun vračeva s istoka i gatara kao Filistejci, bratime se s tuđincima.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (29, 2, 7, 'Zemlja mu je puna srebra i zlata i blagu mu kraja nema; zemlja mu je puna konja, kolima mu broja nema.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (29, 2, 8, 'Zemlja mu je prepuna kumira i oni se klanjaju pred djelom ruku svojih, pred onim što njihovi načiniše prsti.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (29, 2, 9, 'Smrtnik će se poviti, čovjek sniziti; ne praštaj im.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (29, 2, 10, 'Uđi među pećine, skrij se u prašinu, pred užasom Jahvinim, pred sjajem veličanstva njegova, kad ustane da potrese zemlju.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (29, 2, 11, 'Ohol pogled bit će skršen i bahatost ljudska ponižena. Jahve će se uzvisiti, on jedini - u dan onaj.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (29, 2, 12, 'Da, bit će to dan Jahve nad Vojskama, protiv svih oholih i bahatih, protiv sviju što se uzvisiše, da ih obori;');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (29, 2, 13, 'protiv svih cedrova libanonskih i svih hrastova bašanskih;');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (29, 2, 14, 'protiv svih gora uznositih i svih bregova uzdignutih;');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (29, 2, 15, 'protiv svake visoke tvrđe i svih tvrdih zidina;');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (29, 2, 16, 'protiv sveg brodovlja taršiškog i svih brodova raskošnih.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (29, 2, 17, 'Oholost ljudska skršit će se i bahatost ljudska poniziti. Jahve će se uzvisiti, on jedini - u dan onaj,');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (29, 2, 18, 'i kumiri će netragom nestati.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (29, 2, 19, 'Uđite u rupe među pećinama i u spilje zemaljske pred užasom Jahvinim, pred sjajem veličanstva njegova, kad ustane da potrese zemlju.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (29, 2, 20, 'U dan onaj: bacit će svaki svoje srebro i zlatne kumire koje sebi načini da im se klanja,');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (29, 2, 21, 'kad uteče u šupljine pećina i u raspukline stijena pred užasom Jahvinim, pred sjajem veličanstva njegova, kad ustane da potrese zemlju.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (29, 2, 22, 'Čuvajte se, dakle, čovjeka koji ima samo jedan dah u nosnicama: jer što vrijedi?');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (29, 3, 1, 'Gle, Gospod, Jahve nad Vojskama, oduzima Jeruzalemu i Judeji svaku potporu, pomoć u kruhu i pomoć u vodi,');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (29, 3, 2, 'junaka i ratnika, suca i proroka, vrača i starješinu, pedesetnika i odličnika,');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (29, 3, 3, 'savjetnika i mudra gatara i onoga što se bavi čaranjem.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (29, 3, 4, '\"A za glavare postavljam im djecu, dajem deranima da njima vladaju.\"');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (29, 3, 5, 'Ljudi se glože jedan s drugim i svaki s bližnjim svojim; dijete nasrće na starca, prostak na odličnika');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (29, 3, 6, 'te svatko brata hvata u očinskoj kući: \"Ti imaš plašt, budi nam glavarom, uzmi u ruke ovo rasulo!\"');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (29, 3, 7, 'A on će se, u dan onaj, braniti: \"Neću da budem vidar, nema u mene ni kruha ni plašta: ne stavljajte me narodu za glavara.\"');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (29, 3, 8, 'Jeruzalem se ruši i pada Judeja, jer im se jezik i djela Jahvi protive te prkose pogledu Slave njegove.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (29, 3, 9, 'Lice njihovo protiv njih svjedoči, razmeću se grijehom poput Sodome i ne kriju ga, jao njima, sami sebi propast spremaju.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (29, 3, 10, 'Kažite: \"Blago pravedniku, hranit će se plodom djela svojih!');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (29, 3, 11, 'Jao opakome, zlo će mu biti, na nj će pasti djela ruku njegovih.\"');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (29, 3, 12, 'Deran tlači narod moj i žene njime vladaju. O narode moj, vladaoci te tvoji zavode i raskapaju put kojim hodiš.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (29, 3, 13, 'Ustade Jahve da se popravda s narodom svojim,');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (29, 3, 14, 'Jahve dolazi na sud sa starješinama i glavarima svog naroda: \"Vinograd ste moj opustošili, u vašim je kućama što oteste siromahu.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (29, 3, 15, 'S kojim pravom narod moj tlačite i gazite lice siromaha?\" - riječ je Jahve, Gospoda nad Vojskama.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (29, 3, 16, 'I reče Jahve: \"Što se to ohole kćeri sionske te ispružena vrata hode, okolo okom namiguju, koracima sitnim koracaju, grivnama na nozi zveckaju?');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (29, 3, 17, 'Oćelavit će Gospod tjeme kćeri sionskih, obnažit će Jahve golotinju njihovu.\"');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (29, 3, 18, 'U onaj će dan Gospod strgnuti sve čime se ona ponosi: ukosnice i mjesečiće,');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (29, 3, 19, 'naušnice, narukvice i koprene,');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (29, 3, 20, 'poveze, lančiće, pojaseve, bočice s miomirisima i privjese,');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (29, 3, 21, 'prstenje i nosne prstenove,');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (29, 3, 22, 'skupocjene haljine i plašteve, prijevjese i torbice,');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (29, 3, 23, 'zrcala i košuljice, povezače i rupce.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (29, 3, 24, 'Mjesto miomirisa, smrad; mjesto pojasa, konopac; mjesto kovrča, tjeme obrijano; mjesto gizdave halje, kostrijet; mjesto ljepote, žig.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (29, 3, 25, 'Muževi tvoji od mača će pasti, junaci tvoji u kreševu.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (29, 3, 26, 'Vrata će tvoja kukat\' i tugovati, na zemlji ćeš sjedit\' napuštena.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (29, 4, 1, 'I sedam će se žena jagmiti za jednoga čovjeka - u dan onaj: \"Svoj ćemo kruh jesti,\" reći će, \"i u halje se svoje oblačiti, daj nam samo da tvoje nosimo ime, skini sa nas svu sramotu našu.\"');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (29, 4, 2, 'U onaj će dan izdanak Jahvin biti na diku i na slavu, a plod zemlje na ponos i ures spašenima u Izraelu.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (29, 4, 3, 'Koji ostanu na Sionu i prežive u Jeruzalemu, zvat će se \"sveti\" i bit će upisani da u Jeruzalemu žive.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (29, 4, 4, 'Kad Gospod spere ljagu kćeri sionskih i obriše s Jeruzalema krv prolivenu dahom suda i dahom što spaljuje,');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (29, 4, 5, 'sazdat će Jahve nad svom Gorom sionskom i nad svima što ondje budu zborovali oblak s dimom danju, a noću sjaj ognja žarkoga. Jer, vrh svega Slava će biti zaklon');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (29, 4, 6, 'i sjenica da zasjenjuje danju od pripeke, štit i utočište od pljuska i oluje.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (29, 5, 1, 'Zapjevat ću svojemu dragome, pjesmu svog ljubljenog njegovu vinogradu. Moj je dragi imao vinograd na brežuljku rodnome.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (29, 5, 2, 'Okopa ga, iskrči kamenje, posadi ga lozom plemenitom. Posred njega kulu on podiže i u nj tijesak metnu. Nadaše se da će uroditi grožđem, a on izrodi vinjagu.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (29, 5, 3, 'Sad, žitelji jeruzalemski i ljudi Judejci, presudite izmeđ\' mene i vinograda mojega.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (29, 5, 4, 'Što još mogoh učiniti za svoj vinograd a da nisam učinio? Nadah se da će uroditi grožđem, zašto vinjagu izrodi?');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (29, 5, 5, 'No sad ću vam reći što ću učiniti od svog vinograda: plot ću mu soriti da ga opustoše, zidinu razvaliti da ga izgaze.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (29, 5, 6, 'U pustoš ću ga obratiti, ni obrezana ni okopana, nek\' u drač i trnje sav zaraste; zabranit ću oblacima da dažde nad njime.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (29, 5, 7, 'Vinograd Jahve nad Vojskama dom je Izraelov; izabrani nasad njegov ljudi Judejci. Nadao se pravdi, a eto nepravde, nadao se pravičnosti, a eto vapaja.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (29, 5, 8, 'Jao vama koji kuću kući primičete i polje s poljem sastavljate, dok sve mjesto ne zauzmete te postanete jedini u zemlji.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (29, 5, 9, 'Na uši moje reče Jahve nad Vojskama: \"Doista, mnoge će kuće opustjeti, velike i lijepe, bit će bez žitelja.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (29, 5, 10, 'Deset rali vinograda dat će samo bačvicu, mjera sjemena dat će samo mjericu.\"');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (29, 5, 11, 'Jao onima što već jutrom na uranku žestokim se pićem zalijevaju i kasno noću sjede vinom raspaljeni.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (29, 5, 12, 'Na gozbama im harfe i citare, bubnjevi i frule uz vino, a za djelo Jahvino ne mare, ne gledaju djelo ruku njegovih.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (29, 5, 13, 'Stoga će u ropstvo narod moj odvesti, jer nema razumnosti, odličnici njegovi od gladi će umirati, puk njegov od žeđi će gorjeti.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (29, 5, 14, 'Da, Podzemlje će razvaliti ždrijelo, razjapit će ralje neizmjerne da se u njih strmoglave odličnici mu i mnoštvo sa svom grajom i veseljem!');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (29, 5, 15, 'Smrtnik će nikom poniknuti, ponizit\' se čovjek, oborit će se pogled silnih.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (29, 5, 16, 'Jahve nad Vojskama uzvisit će se sudom, i Bog će sveti otkrit\' svetost svoju.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (29, 5, 17, 'Jaganjci će pasti kao na pašnjacima, a jarci će brstiti po ruševinama bogataškim.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (29, 5, 18, 'Jao onima koji na se krivnju vuku volovskom užadi i grijeh kolskim konopcem -');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (29, 5, 19, 'onima što govore: \"Neka pohiti, neka poteče s djelom svojim da bismo ga vidjeli, neka se približi i završi naum Sveca Izraelova da bismo znali!\"');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (29, 5, 20, 'Jao onima koji zlo dobrom nazivaju, a dobro zlom, koji od tame svjetlost prave, a od svjetlosti tamu, koji gorko slatkim čine, a slatko gorkim!');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (29, 5, 21, 'Jao onima koji su mudri u svojim očima i pametni sami pred sobom!');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (29, 5, 22, 'Jao onima koji su jaki u vinu i junaci u miješanju jakih pića;');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (29, 5, 23, 'onima koji za mito brane krivca, a pravedniku uskraćuju pravdu!');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (29, 5, 24, 'Zato, kao što plameni jezici proždiru slamu i kao što nestaje suha trava u plamenu, tako će korijen njihov istrunuti, poput praha razletjet\' se pupoljak njihov, jer odbaciše Zakon Jahve nad Vojskama i prezreše riječ Sveca Izraelova.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (29, 5, 25, 'Zato se raspali gnjev Jahvin protiv njegova naroda, i on diže ruku na nj i udari ga te se potresoše gore: trupla njihova leže k\'o smeće po ulicama, ali gnjev se njegov još ne smiri, ruka mu je sveđer podignuta.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (29, 5, 26, 'On podiže stijeg ratni narodu dalekom, zazviždi mu na kraj zemlje, i gle: brzo, spremno hita.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (29, 5, 27, 'U njemu nema trudna ni sustala, ni dremljiva niti snena, oko boka pojas ne otpasuje, na obući ne driješi remena.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (29, 5, 28, 'Strijele su mu dobro zašiljene, lukovi mu svi zapeti, kremen su kopita konja njegovih, vihor su točkovi bojnih mu kola.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (29, 5, 29, 'Rika mu je k\'o u lava i riče k\'o lavovi mladi, reži, grabi plijen i odnosi, a nikoga da mu ga istrgne.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (29, 5, 30, 'U dan onaj režat će na njega k\'o što more buči. Pogledaš li zemlju - sve tmina, tjeskoba, svjetlost proguta tmina oblačna.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (29, 6, 1, 'One godine kad umrije kralj Uzija, vidjeh Gospoda gdje sjedi na prijestolju visoku i uzvišenu. Skuti njegova plašta ispunjahu Svetište.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (29, 6, 2, 'Iznad njega stajahu serafi; svaki je imao po šest krila: dva krila da zakloni lice, dva da zakrije noge, a dvama je krilima letio.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (29, 6, 3, 'I klicahu jedan drugome: \"Svet! Svet! Svet Jahve nad Vojskama! Puna je sva zemlja Slave njegove!\"');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (29, 6, 4, 'Od gromka glasa onih koji klicahu stresoše se dovraci na pragovima, a Dom se napuni dimom.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (29, 6, 5, 'Rekoh: \"Jao meni, propadoh, jer čovjek sam nečistih usana, u narodu nečistih usana prebivam, a oči mi vidješe Kralja, Jahvu nad Vojskama!\"');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (29, 6, 6, 'Jedan od serafa doletje k meni: u ruci mu žerava koju uze kliještima sa žrtvenika;');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (29, 6, 7, 'dotače se njome mojih usta i reče: \"Evo, usne je tvoje dotaklo, krivica ti je skinuta i grijeh oprošten.\"');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (29, 6, 8, 'Tad čuh glas Gospodnji: \"Koga da pošaljem? I tko će nam poći?\" Ja rekoh: \"Evo me, mene pošalji!\"');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (29, 6, 9, 'On odgovori: \"Idi i reci tom narodu: \'Slušajte dobro, al\' nećete razumjeti, gledajte dobro, al\' nećete spoznati.\'');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (29, 6, 10, 'Otežaj salom srce tom narodu, ogluši mu uši, zaslijepi oči, da očima ne vidi, da ušima ne čuje i srcem da ne razumije kako bi se obratio i ozdravio.\"');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (29, 6, 11, 'Ja rekoh: \"Dokle, o Gospode?\" On mi odgovori: \"Dok gradovi ne opuste i ne ostanu bez žitelja, dok kuće ne budu bez ikoga živa, i zemlja ne postane pustoš,');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (29, 6, 12, 'dok Jahve daleko ne protjera ljude. Haranje veliko pogodit će zemlju,');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (29, 6, 13, 'i ostane li u njoj još desetina, i ona će biti zatrta poput duba kad ga do panja posijeku. Panj će njihov biti sveto sjeme.\"');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (29, 7, 1, 'U dane judejskoga kralja Ahaza, sina Jotamova, sina Uzijina, aramski kralj Rason i izraelski kralj Pekah, sin Remalijin, zavojštiše na Jeruzalem, ali ga ne mogoše zauzeti.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (29, 7, 2, 'Tada dojaviše domu Davidovu: \"Aramci se utaborili u Efrajimu.\" Na tu vijest uzdrhta srce kraljevo i srce svega naroda, kao što u šumi drveće ustrepti od vjetra.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (29, 7, 3, 'I Jahve reče Izaiji: \"Iziđi pred Ahaza, ti i sin tvoj Šear Jašub, do nakraj vodovoda gornjeg ribnjaka na putu u Valjarevo polje.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (29, 7, 4, 'Reci mu: \'Pazi, smiri se, ne boj se, i nek\' ti ne premire srce od ovih dvaju ugaraka zadimljenih, od raspaljenog bijesa Rasona aramskog i sina Remalijina,');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (29, 7, 5, 'jer Aram, Efrajim i sin Remalijin smisliše tvoju propast.\'');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (29, 7, 6, 'Pođimo, rekoše, na Judeju, uplašimo je i osvojimo da u njoj zakraljimo sina Tabelova.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (29, 7, 7, 'Ovako govori Jahve Gospod: \'To se neće zbiti: toga biti neće!');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (29, 7, 8, '[8a] Damask je glava Aramcima, a Damasku je glava Rason;');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (29, 7, 9, 'Samarija je glava Efrajimcima, a Samariji glava je Remalija. [8b]Još šezdeset i pet godina, i Efrajim, razoren, neće više biti narod. [9b] Ako se na me ne oslonite, održat\' se nećete!\"');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (29, 7, 10, 'Jahve opet progovori Ahazu i reče mu:');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (29, 7, 11, '\"Zaišti od Jahve, Boga svoga, jedan znak za sebe iz dubine Podzemlja ili gore iz visina.\"');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (29, 7, 12, 'Ali Ahaz odgovori: \"Ne, neću iskati i neću iskušavati Jahvu.\"');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (29, 7, 13, 'Tada reče Izaija: \"Čujte, dome Davidov. Zar vam je malo dodijavati ljudima, pa i Bogu mom dodijavate!');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (29, 7, 14, 'Zato, sam će vam Gospodin dati znak: Evo, začet će djevica i roditi sina i nadjenut će mu ime Emanuel!');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (29, 7, 15, 'Vrhnjem i medom on će se hraniti dok ne nauči odbacivat\' zlo i birati dobro.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (29, 7, 16, 'Jer prije nego dječak nauči odbacivat\' zlo i birati dobro, opustjet će zemlja, zbog koje strepiš, od dvaju kraljeva.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (29, 7, 17, 'Protiv tebe i protiv tvog naroda i protiv kuće oca tvojega dovest će Jahve dane kakvih ne bijaše otkad se Efrajim odvoji od Jude - kralja asirskoga.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (29, 7, 18, 'U dan onaj zazviždat će Jahve muhama na ušću egipatskih rijeka i pčelama u zemlji asirskoj');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (29, 7, 19, 'da dođu i popadaju po strmim dolovima, po rasjelinama stijena, po svim trnjacima i svim pojilištima.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (29, 7, 20, 'U dan onaj Gospod će obrijati britvom najmljenom s onu stranu Eufrata - kraljem asirskim - kosu s glave, dlake s nogu i bradu s obraza.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (29, 7, 21, 'U dan onaj svatko će hraniti po kravu i dvije ovce');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (29, 7, 22, 'i od obilja mlijeka koje će mu dati hranit će se vrhnjem; vrhnjem i medom hranit će se koji god u zemlji preostanu.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (29, 7, 23, 'U dan onaj gdje god bijaše tisuću čokota, vrijednih tisuću srebrnika, izrast će drač i trnje.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (29, 7, 24, 'Onamo će polaziti sa strijelom i lukom, jer sva će zemlja u drač i trnje zarasti.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (29, 7, 25, 'A po svim gorama gdje se motikom kopalo nitko više neće ići, strašeći se trnja i drača: onuda će goveda pasti i gaziti ovce.\"');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (29, 8, 1, 'Reče Jahve: \"Uzmi veliku ploču i napiši na njoj ljudskim pismom: Maher Šalal Haš Baz - Brz grabež - hitar plijen.\"');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (29, 8, 2, 'Potom uzeh vjerne svjedoke, svećenika Uriju i Zahariju, sina Berekjina.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (29, 8, 3, 'Približih se proročici te ona zače i rodi sina. Jahve mi reče: \"Nazovi ga Maher Šalal Haš Baz,');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (29, 8, 4, 'jer prije no što dijete počne tepati \'tata\' i \'mama\', nosit će se pred kralja asirskog sve bogatstvo Damaska i plijen Samarije.\"');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (29, 8, 5, 'I opet mi reče Jahve:');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (29, 8, 6, '\"Jer narod ovaj odbacuje mirne tekućice Šiloaha, a dršće pred Rasonom i pred sinom Remalijinim,');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (29, 8, 7, 'navest će Gospod na vas vodu Eufrata, silnu i veliku - kralja asirskog i svu slavu njegovu - i ona će izići iz rukava svoga, preliti se preko svih obala;');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (29, 8, 8, 'provalit će u Judeju, razlit\' se i poplaviti je, popeti se do grla njezina; i krila će svoja raširiti preko cijele tvoje zemlje, o Emanuele.\"');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (29, 8, 9, 'Udružite se samo, narodi, al\' bit ćete smrvljeni! Poslušajte, vi kraljevi daleki, pašite se, bit ćete smrvljeni, pašite se, bit ćete smrvljeni!');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (29, 8, 10, 'Kujte naum - bit će uništen, dogovarajte se samo, bit će uzalud, jer s nama je Bog!');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (29, 8, 11, 'Jer, ovako mi reče Jahve, kad me rukom uhvatio i opomenuo da ne idem putem kojim narod ovaj ide:');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (29, 8, 12, '\"Ne zovite urotom sve što narod ovaj urotom zove; ne bojte se čega se on boji i nemajte straha.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (29, 8, 13, 'Jahve nad Vojskama - on jedini nek\' vam svet bude; jedino se njega bojte, strah od njega nek\' vas prožme.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (29, 8, 14, 'On će vam biti zamka i kamen spoticanja i stijena posrtanja za obje kuće Izraelove, zamka i mreža svim Jeruzalemcima.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (29, 8, 15, 'Mnogi će od njih posrnuti, pasti, razbiti se, zaplesti se, uhvatiti.\"');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (29, 8, 16, 'Pohrani ovo svjedočanstvo, zapečati ovu objavu među učenicima svojim:');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (29, 8, 17, 'Čekat ću Jahvu koji je lice svoje sakrio od doma Jakovljeva - u njega ja se uzdam.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (29, 8, 18, 'Evo, ja i djeca koju mi Jahve dade Izraelu smo znak i znamenje od Jahve nad Vojskama što prebiva na Gori sionskoj.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (29, 8, 19, 'Reknu li vam: \"Duhove pitajte i vrače koji šapću i mrmljaju\" - dakako, narod mora pitati svoje \"bogove\" i za žive u mrtvih se raspitivati! -');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (29, 8, 20, 'Uza Zakon! Uza svjedočanstvo! Tko ne rekne tako, zoru neće dočekati.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (29, 8, 21, 'Lutat će zemljom potlačen i gladan, izgladnjela bijes će ga spopasti, proklinjat će svoga kralja i svog Boga. Okrene l\' se k nebu,');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (29, 8, 22, 'pogleda l\' po zemlji, gle, svuda samo mrak i strava, svuda tmina tjeskobna. Ali će se tama raspršiti,');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (29, 8, 23, 'jer više neće biti mraka gdje je sad tjeskoba.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (29, 8, 24, 'U prvo vrijeme on obescijeni zemlju Zebulunovu i zemlju Naftalijevu, al\' u vrijeme posljednje on će proslaviti Put uz more, s one strane Jordana - Galileju pogansku.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (29, 9, 1, 'Narod koji je u tmini hodio svjetlost vidje veliku; one što mrklu zemlju obitavahu svjetlost jarka obasja.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (29, 9, 2, 'Ti si radost umnožio, uvećao veselje, i oni se pred tobom raduju kao što se ljudi raduju žetvi, k\'o što kliču kad se dijeli plijen.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (29, 9, 3, 'Teški jaram njegov, prečku što mu pleća pritiskaše, šibu njegova goniča slomi kao u dan midjanski.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (29, 9, 4, 'Da, sva bojna obuća, svaki plašt krvlju natopljen izgorjet će i bit će ognju hrana.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (29, 9, 5, 'Jer, dijete nam se rodilo, sina dobismo; na plećima mu je vlast. Ime mu je: Savjetnik divni, Bog silni, Otac vječni, Knez mironosni.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (29, 9, 6, 'Nadaleko vlast će mu se sterat\' i miru neće biti kraja nad prijestoljem Davidovim, nad kraljevstvom njegovim: učvrstit će ga i utvrdit u pravu i pravednosti. Od sada i dovijeka učinit će to privržena ljubav Jahve nad Vojskama.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (29, 9, 7, 'Gospod posla riječ protiv Jakova i ona pade na Izraela.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (29, 9, 8, 'Sazna je sav narod njegov, Efrajim i stanovnici Samarije koji govorahu naduta i ohola srca:');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (29, 9, 9, '\"Opeke nam popadaše, gradit ćemo od tesanika; sasjekoše nam divlje smokve, cedre ćemo posaditi.\"');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (29, 9, 10, 'Al\' Jahve podiže na brdo Sion njegove protivnike i podbada neprijatelje njegove:');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (29, 9, 11, 'Aram s istoka, Filistejce sa zapada, da svim ustima proždiru Izraela. Na sve to gnjev se njegov neće smiriti, ruka će mu ostat\' ispružena.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (29, 9, 12, 'Ali se narod nije obratio onom koji ga je b§io, ne tražiše Jahvu nad Vojskama.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (29, 9, 13, 'Zato Jahve odsiječe Izraelu glavu i rep, palmu i rogoz u jednom danu.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (29, 9, 14, 'Starješina i odličnik - to je glava; prorok, učitelj laži - to je rep.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (29, 9, 15, 'Oni što vode narod taj - zavode ga, a koji se vodit\' daju - propali su.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (29, 9, 16, 'Stog\' mu Gospod neće poštedjet\' mladića, sirotama njegovim i udovicama smilovat\' se neće. Sav je taj narod bezbožan i zao, na sva usta bezumno govori. Na sve to gnjev se njegov neće smiriti, ruka će mu ostat\' ispružena.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (29, 9, 17, 'Da, bezbožnost se k\'o oganj razmahala, drač i trnje proždire, pa upali šumsku guštaru, stupovi se dima podižu.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (29, 9, 18, 'Plamti zemlja od gnjeva Jahvina, narod ognju hrana postaje. Nitko ni brata svog ne štedi, [19b] svatko jede meso svog susjeda.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (29, 9, 19, '[19a] Proždire zdesna, i opet je gladan; guta slijeva, i opet sit nije:');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (29, 9, 20, 'Manaše Efrajima, Efrajim Manašea, obojica zajedno Judu. Na sve to gnjev se njegov neće smiriti, ruka će mu ostat\' ispružena.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (29, 9, 21, '');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (29, 10, 1, 'Jao onima koji izdaju odredbe nepravedne, koji ispisuju propise tlačiteljske;');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (29, 10, 2, 'koji uskraćuju pravdu ubogima i otimlju pravo sirotinji mog naroda, da oplijene udovice, da opljačkaju sirote!');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (29, 10, 3, 'Što ćete činiti u dan kazne kad izdaleka propast dođe? Kom ćete se za pomoć uteći, gdje ostaviti blago svoje');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (29, 10, 4, 'da se ne morate među roblje pognuti, pasti među poklanima? Na sve to gnjev se njegov neće smiriti, ruka će mu ostat\' ispružena.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (29, 10, 5, 'Jao Asiru, šibi gnjeva mojega, prutu kojim srdžba moja zamahuje!');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (29, 10, 6, 'Na puk ga poslah nevjeran, na narod što me razjari, da ga oplijeni i opljačka, da ga izgazi k\'o blato na ulici.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (29, 10, 7, 'Ali on nije tako mislio i u srcu nije tako sudio, već u srcu zasnova zator, istrebljenje mnogih naroda.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (29, 10, 8, 'Govoraše: \"Nisu li svi knezovi moji kraljevi?');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (29, 10, 9, 'Nije li Kalno kao Karkemiš? Nije li Hamat kao Arpad, Samarija kao Damask?');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (29, 10, 10, 'Kao što mi ruka dosegnu kraljevstva kumira, bogatija kipovima od Jeruzalema i Samarije,');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (29, 10, 11, 'kao što učinih sa Samarijom i kumirima njenim, neću li učiniti s Jeruzalemom i s likovima njegovim?\"');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (29, 10, 12, 'I kad dovrši Gospod sve djelo svoje na gori Sionu i u Jeruzalemu, kaznit će plod ohola srca kralja asirskog i drskost njegovih ponositih očiju.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (29, 10, 13, 'Jer reče: \"Učinih snagom svoje ruke i mudrošću svojom, jer sam uman; uklonih međe narodima i blaga njihova opljačkah, kao junak oborih one što sjede na prijestoljima.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (29, 10, 14, 'Ruka moja kao gnijezda zgrabi bogatstva naroda. Kao što se kÓupe ostavljena jaja, zemlju svu sam pokupio i nikog ne bi krilima da zalepeće, kljun otvori, zapijuče.\"');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (29, 10, 15, 'Zar se hvali sjekira povrh onog koji njome siječe? Hoće li se oholit\' pila povrh onog koji njome pili? K\'o da šiba maše onim koji je podiže, il\' štap diže onog koji drvo nije;');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (29, 10, 16, 'Jahve nad Vojskama poslat će stoga gojaznima njegovim skončanje, slavu će mu ognjem potpaliti, kao što se vatra potpiruje.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (29, 10, 17, 'Svjetlost Izraelova bit će poput ognja, Svetac njegov kao plamen koji će zapalit\' i proždrijeti drač njegov i trnje njegovo u jednome danu.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (29, 10, 18, 'I krasotu njegovih šuma i voćnjaka uništit će od srčike do kore, ona će biti k\'o bolesnik što se trne;');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (29, 10, 19, 'ostatak stabala šumskih bit će lako izbrojiti - dijete će ih lako popisati.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (29, 10, 20, 'U onaj dan: Ostatak Izraelov i preživjeli iz kuće Jakovljeve neće se više oslanjati na onoga koji ih bije, već će se iskreno oslanjati na Jahvu, Sveca Izraelova.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (29, 10, 21, 'Ostatak će se vratiti, ostatak Jakovljev Bogu jakome.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (29, 10, 22, 'Zaista, o Izraele, sve da naroda tvojega ima kao pijeska u moru, samo će se Ostatak njegov vratiti. Određeno je uništenje, pravda se prelila,');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (29, 10, 23, 'Jahve, Gospod nad Vojskama, poharat će, kako odredi, svu zemlju.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (29, 10, 24, 'Zato ovako govori Jahve nad Vojskama: \"O narode moj što prebivaš na Sionu, ne boj se Asira kad te šibom tuče, kad štap diže na tebe.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (29, 10, 25, 'Jer, još malo, vrlo malo, i gnjev moj će prestati, moja će ih jarost uništiti.\"');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (29, 10, 26, 'Na nj će Jahve nad Vojskama bičem zamahnuti, kao kad udari Midjan na stijeni Orebu, i štap će dići nad more k\'o na putu egipatskom.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (29, 10, 27, 'U onaj dan: s leđa će ti breme pasti i jaram njegov s vrata će ti nestat\'.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (29, 10, 28, 'Ide on od Rimona, dolazi na Ajat, prelazi Migron, u Mikmasu breme odlaže.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (29, 10, 29, 'Prelaze klance, u Gebi im je noćište; Rama dršće, Gibea Šaulova bježi.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (29, 10, 30, 'Viči iza glasa, Bat Galime! Slušaj ga, Lajšo! Odgovori mu, Anatote!');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (29, 10, 31, 'Madmena pobježe, utekoše stanovnici gebimski.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (29, 10, 32, 'Još danas zaustavit će se u Nobu, rukom prijeti gori Kćeri sionske, Brijegu jeruzalemskom.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (29, 10, 33, 'Gle, Jahve, Gospod nad Vojskama, kreše grane silom strahovitom: najviši su vršci posječeni, ponajviši sniženi.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (29, 10, 34, 'Pod sjekirom pada šumska guštara, sa slavom svojom pada Libanon.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (29, 11, 1, 'Isklijat će mladica iz panja Jišajeva, izdanak će izbit\' iz njegova korijena.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (29, 11, 2, 'Na njemu će duh Jahvin počivat\', duh mudrosti i umnosti, duh savjeta i jakosti, duh znanja i straha Gospodnjeg.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (29, 11, 3, 'Prodahnut će ga strah Gospodnji: neće suditi po viđenju, presuđivati po čuvenju,');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (29, 11, 4, 'već po pravdi će sudit\' ubogima i sud prav izricat\' bijednima na zemlji. Šibom riječi svoje ošinut će silnika, a dahom iz usta ubit\' bezbožnika.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (29, 11, 5, 'On će pravdom opasati bedra, a vjernošću bokove.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (29, 11, 6, 'Vuk će prebivati s jagnjetom, ris ležati s kozlićem, tele i lavić zajedno će pasti, a djetešce njih će vodit\'.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (29, 11, 7, 'Krava i medvjedica zajedno će pasti, a mladunčad njihova skupa će ležati, lav će jesti slamu k\'o govedo.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (29, 11, 8, 'Nad rupom gujinom igrat će se dojenče, sisanče će ruku zavlačiti u leglo zmijinje.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (29, 11, 9, 'Zlo se više neće činiti, neće se pustošiti na svoj svetoj gori mojoj: zemlja će se ispuniti spoznajom Jahvinom kao što se vodom pune mora.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (29, 11, 10, 'U dan onaj: Jišajev izdanak, dignut kao stijeg narodima, puci će željno tražiti. I prebivalište njegovo bit će slavno.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (29, 11, 11, 'U dan onaj: Jahve će drugi put ruku pružiti da otkupi Ostatak svoga naroda, one što ostanu iz Asira i iz Egipta, iz Patrosa, Kuša i Elama, iz Šineara, Hamata i s morskih otoka.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (29, 11, 12, 'Podignut će stijeg narodima, sabrat će Izraelu prognanike i skupiti Judi raspršene sa sva četiri kraja zemlje.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (29, 11, 13, 'Ljubomor će nestat\' Efrajimov, bit će istrijebljeni dušmani Judini; Efrajim neće više zavidjeti Judi, a Juda neće biti neprijatelj Efrajimu.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (29, 11, 14, 'Filistejcima na zapadu za vrat će sjesti, zajedno će plijeniti sinove Istoka; ruku će svoju pružit\' na Edom i Moab, bit će im pokorni sinovi Amonovi.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (29, 11, 15, 'Jahve će isušit\' zaljev mora egipatskog, zamahnut će rukom protiv Eufrata; snagom daha razbit će ga na sedam potoka da se u obući može prelaziti:');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (29, 11, 16, 'i bit će cesta Ostatku njegova naroda, koji preživio bude iz Asira, kao što bijaše Izraelcima kad iziđoše iz zemlje egipatske.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (29, 12, 1, 'Reći ćeš u dan onaj: Hvalim te, Jahve, razgnjevi se ti na mene, ali se odvratio gnjev tvoj i ti me utješi!');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (29, 12, 2, 'Evo, Bog je spasenje moje, uzdam se, ne bojim se više, jer je Jahve snaga moja i pjesma, on je moje spasenje.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (29, 12, 3, 'I s radošću ćete crpsti vodu iz izvora spasenja.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (29, 12, 4, 'Reći ćete u dan onaj: Hvalite Jahvu prizivajte ime njegovo! Objavite narodima djela njegova, razglašujte uzvišenost imena njegova!');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (29, 12, 5, 'Pjevajte Jahvi, jer stvori divote, neka je to znano po svoj zemlji!');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (29, 12, 6, 'Kličite i radujte se, stanovnici Siona, jer je velik među vama Svetac Izraelov!');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (29, 13, 1, 'Proroštvo o Babilonu koje vidje Izaija, sin Amosov.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (29, 13, 2, 'Na goletnu brdu dignite zastavu, vičite im iz sveg grla. Mašite rukom neka dođu na vrata kneževska.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (29, 13, 3, 'Zapovijed dadoh svetim svojim ratnicima, gnjevu svom pozvah svoje junake koji slave veličanstvo moje.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (29, 13, 4, 'Čuj! Žagor na gorama kao od silna naroda. Čuj! Buka kraljevstava, sakupljenih naroda. To Jahve nad Vojskama za boj vojsku pregleda.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (29, 13, 5, 'Iz daleka kraja, s granica neba dolaze oni - Jahve i oruđa gnjeva njegova - da svu zemlju poharaju.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (29, 13, 6, 'Kukajte, jer je blizu Jahvin dan, k\'o pohara dolazi od Svemoćnog.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (29, 13, 7, 'I sve ruke stog\' malakšu... Svako ljudsko srce klone,');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (29, 13, 8, 'strava ih je obrvala, trudovi boli već ih spopadaju i grče se k\'o rodilja. U prepasti jedan drugog motre, lica su im poput plamena.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (29, 13, 9, 'Dolazi nesmiljeni Jahvin dan - gnjev i jarost - da u pustoš zemlju prometne, da istrijebi iz nje grešnike.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (29, 13, 10, 'Jer nebeske zvijezde a ni Štapci neće više sjati svjetlošću, pomrčat će sunce ishodeći i mjesec neće više svijetliti.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (29, 13, 11, 'Kaznit ću svijet za zloću, bezbožnike za bezakonje, dokrajčit ću ponos oholih, poniziti nadutost silnika.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (29, 13, 12, 'Rjeđi će biti čovjek neg\' žeženo zlato, rjeđi samrtnik od zlata ofirskog.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (29, 13, 13, 'Nebesa ću potresti, maknut će se zemlja s mjesta od srdžbe Jahve nad Vojskama u dan kad se izlije gnjev njegov.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (29, 13, 14, 'I tada, kao gazela preplašena, kao ovce koje nitko ne prikuplja, svatko će se vratit\' svom narodu, svatko će u zemlju svoju pobjeći.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (29, 13, 15, 'Koga stignu, probost će ga: koga uhvate, mačem će sasjeći;');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (29, 13, 16, 'pred očima smrskat će im dojenčad, opljačkati kuće, silovati žene.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (29, 13, 17, 'Gle, podižem na njih Medijce što ne cijene srebra i preziru zlato.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (29, 13, 18, 'Svi će mladići biti pokošeni, sve djevojke zatrte. Na plod utrobe neće se smilovati, nad djecom im se oko neće sažaliti.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (29, 13, 19, 'Babilon, ures kraljevstava, ures i ponos kaldejski, bit će k\'o Sodoma i Gomora kad ih Bog zatrije.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (29, 13, 20, 'Nikad se više neće naseliti, od koljena do koljena ostat će nenapučen. Arapin ondje neće dizati šatora, nit\' će pastiri ondje počivati.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (29, 13, 21, 'Počivat će ondje zvijeri pustinjske, sove će im napuniti kuće, nojevi će ondje stanovati, jarci plesati.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (29, 13, 22, 'Hijene će zavijati iz njegovih palača, a čaglji iz raskošnih dvorova... Vrijeme se njegovo bliži, dani mu se neće produžiti.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (29, 14, 1, 'Da, smilovat će se Jahve Jakovu i opet izabrati Izraela, dati mu da počine u svojoj zemlji. Pridružit će im se došljak i priključiti se domu Jakovljevu.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (29, 14, 2, 'Sami će narodi po njih doći i odvesti ih u njihov kraj, a njih će Dom Izraelov baštiniti u Jahvinoj zemlji kao sluge i sluškinje. I zarobit će one koji njih bijahu zarobili i gospodovat će nad svojim tlačiteljima.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (29, 14, 3, 'U dan kad ti Jahve dade da počineš od svojih stradanja, nemira i teškog robovanja kojima te pritisnuše,');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (29, 14, 4, 'zapjevat ćeš ovu rugalicu kralju babilonskom: Kako nestade silnika? Kako nestade tlačenja?');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (29, 14, 5, 'Jahve slomi štap zlikovački i žezlo vladarsko');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (29, 14, 6, 'što je bijesno b§ilo narode udarcima bez kraja i konca, što je gnjevno vladalo narodima progoneć\' ih nemilice.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (29, 14, 7, 'Počiva, miruje sva zemlja kličući od radosti.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (29, 14, 8, 'Nad tobom se raduju čempresi i cedri libanonski: \"Otkako si pao, ne dolaze nas više sjeći!\"');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (29, 14, 9, 'Zbog tebe se uzbudi Podzemlje da te dočeka kada dođeš. U tvoju čast ono budi sjene, sve zemaljske mogućnike, ono diže s prijestolja sve kraljeve naroda.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (29, 14, 10, 'Svi ti oni progovaraju: \"I ti si skršen k\'o i mi, nama si sličan postao.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (29, 14, 11, 'Oholost se tvoja sruši u Podzemlje i buka tvojih harfa; pod tobom je ležaj od truleži, a crvi tvoj su pokrivač.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (29, 14, 12, 'Kako pade sa nebesa, Svjetlonošo, sine Zorin? Kako li si oboren na zemlju, ti, vladaru naroda?');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (29, 14, 13, 'U svom si srcu govorio: \'Uspet ću se na nebesa, povrh zvijezda Božjih prijesto ću sebi dići. Na zbornoj ću stolovati gori na krajnom sjeveru.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (29, 14, 14, 'Uzaći ću u visine oblačne, bit ću jednak Višnjemu.\'');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (29, 14, 15, 'A sruši se u Podzemlje, u dubine provalije!\"');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (29, 14, 16, 'Koji te vide, motre te i o tebi razmišljaju: \"Je li to čovjek koji je zemljom tresao i drmao kraljevstvima,');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (29, 14, 17, 'koji je u pustinju svijet obraćao i sa zemljom sravnjivao gradove, koji sužnjeva svojih nikad nije kući otpuštao?\"');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (29, 14, 18, 'Kraljevi naroda svi u časti počivaju, svaki u svojoj grobnici.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (29, 14, 19, 'A ti si iz groba izbačen kao smeće odvratno, pokriven poklanima, mačem probodenima, koji su na ploče grobne pobacani k\'o strvina zgažena!');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (29, 14, 20, 'Nećeš se združiti s njima u grobu, jer si zemlju svoju uništio i narod svoj poklao. I nikad se više neće spominjati pleme zlikovačko.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (29, 14, 21, 'Spremite pokolj djeci za bezakonje otaca njihovih, da se više ne dignu da osvajaju zemlju i da ne pokriju lice svijeta!');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (29, 14, 22, 'Ustat ću na njih - riječ je Jahve nad Vojskama - i zatrt ću Babilonu ime i ostatak, rod i porod - riječ je Jahvina.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (29, 14, 23, 'Dat ću ga u posjed ježevima i močvarama. Pomest ću ga metlom zatornom - riječ je Jahve nad Vojskama.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (29, 14, 24, 'Zakleo se Jahve nad Vojskama: \"Što zamislih, zbit će se, što naumih, izvršit će se!');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (29, 14, 25, 'Skršit ću Asur u svojoj zemlji, zgazit ću ga na svojim gorama. Jaram njegov s njih će spasti, spast će im s pleća breme njegovo.\"');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (29, 14, 26, 'Takva je odluka stvorena protiv čitave zemlje; takva je ruka pružena protiv svih naroda!');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (29, 14, 27, 'A kad Jahve nad Vojskama odluči, tko da se usprotivi? Kada ruku ispruži, tko da je odvrati?');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (29, 14, 28, 'One godine kad je umro kralj Ahaz, bi objavljeno ovo proroštvo:');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (29, 14, 29, 'Ne raduj se, sva Filistejo, što se slomi štap koji te udarao, jer će iz korijena zmijinjeg izaći ljutica što će izleći zmaja krilatoga.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (29, 14, 30, 'Ubogi će pasti na mojim pašnjacima i u pouzdanju počivati siromasi; glađu ću pomoriti rod tvoj i pobiti što od tebe ostane.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (29, 14, 31, 'Kukajte, vrata! Zapomaži, grade! Strepi, sva Filistejo! Jer sa sjevera dim dolazi i čete njegove ne napušta nitko!');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (29, 14, 32, 'Što će se tad odgovoriti glasnicima naroda? \"Jahve zasnova Sion, i u njem su zaštićeni siromasi njegova naroda.\"');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (29, 15, 1, 'Proroštvo o Moabu. Obnoć opustošen, šaptom pade Ar Moab! Obnoć opustošen, šaptom pade Kir Moab!');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (29, 15, 2, 'Uspinju se u hram dibonski, na uzvišice da plaču; nad Nebom i nad Medebom Moab nariče! Sve su glave ostrižene, a sve brade obrijane;');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (29, 15, 3, 'na ulicama oblače vreće, na njegovim krovovima leleču! Na njegovim trgovima svi nariču i suze prolijevaju.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (29, 15, 4, 'Jauču Hešbon i Eleala, do Jahasa jauk se čuje. Zato dršću bokovi Moabu, strepi duša njegova;');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (29, 15, 5, 'srce Moabovo jeca, bjegunci mu idu do Soara. Da, uz brdo Luhit uspinju se plačući; putem horonajimskim razliježe se jauk nad propašću.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (29, 15, 6, 'Da! Vode nimrimske postadoše pustinja: trava usahla, bilja nestalo, zelenila više nema.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (29, 15, 7, 'Zato stečevinu koju stekoše i ono što prištedješe nose preko Potoka vrba.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (29, 15, 8, 'Da! Jauk se razliježe po kraju moapskom: kukanje mu do Eglajima, kukanje mu do Beer Elima.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (29, 15, 9, 'Da! Vode dimonske krvi su pune, i još jednu nesreću dodajem Dimonu: jednog lava na moapske bjegunce i na preživjele u zemlji.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (29, 16, 1, 'Šaljite jaganjce vladaru zemlje, od Stijene prema pustinji do gore Kćeri sionske.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (29, 16, 2, 'Kao razbjegle ptice, kao raspršeno gnijezdo bit će kćeri moapske na arnonskim gazovima.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (29, 16, 3, 'Daj nam savjet, stvori odluku! Sred podneva sjenu svoju kao noć razastri. Sakrij izagnane, ne izdaj bjegunca.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (29, 16, 4, 'Daj da kod tebe borave prognanici moapski, budi im okriljem pred pustošnikom. Kad se skonča tlačitelj, kad nestane pustošnika, kad ugnjetač iščezne iz zemlje,');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (29, 16, 5, 'učvrstit će se prijesto u blagosti i na njemu će vjerno stolovati, u šatoru Davidovu, sudac koji pravo ište i pravdu čini.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (29, 16, 6, 'Čuli smo za nadutost Moaba, nadutost preveliku, za ponos, oholost i uznositost; isprazno je njegovo hvastanje.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (29, 16, 7, 'Zato kuka Moab, nad Moabom svi jauču, za kolačima grožđanim iz Kir Heresa jauču posve slomljeni.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (29, 16, 8, 'Jer uvenuše nasadi hešbonski, trsje sibmansko, i lišće su mu pomlatili gospodari naroda. Sezaše do Jazera, zamicaše u pustinju; izdanci mu dosezahu sve do mora.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (29, 16, 9, 'Zato plačem za trsjem sibmanskim kao što plače Jazer, suzama te ja zalijevam, Hešbone i Elealo! Nad plodovima tvojim, nad jematvom, krik se začu;');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (29, 16, 10, 'nestade iz voćnjaka veselja i radosti. U vinogradima ne pocikuje se, ne kliče se od radosti; ne mastÄi se vino u kaci, zamuknu podvikivanje.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (29, 16, 11, 'Zato utroba moja za Moabom poput harfe dršće, a grudi mi za Kir Herešom.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (29, 16, 12, 'Zaludu se pokazuje Moab, umara se na uzvišicama dolazeći u svetište da se moli: ništa postići neće.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (29, 16, 13, 'Ovo je riječ koju nekoć reče Jahve protiv Moaba.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (29, 16, 14, 'A sada govori Jahve ovako: \"Za tri godine, godine najamničke, slava će Moabova, sa svim velikim mnoštvom njegovim, potamnjeti, a što od nje ostane, bit će maleno, slabo i nemoćno.\"');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (29, 17, 1, 'Proroštvo o Damasku. Gle, prestat će Damask biti gradom i postat će hrpom ruševina;');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (29, 17, 2, 'njegovi gradići, dovijek napušteni, bit će pašnjak stadima; ležat će u njima i nitko ih neće tjerati.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (29, 17, 3, 'Izgubit će Efrajim utvrde, a Damask kraljevstvo; ostatku Arama zbit će se što i slavi sinova Izraelovih - riječ je Jahve nad Vojskama.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (29, 17, 4, 'U onaj dan smanjit će se slava Jakovljeva, spast će salo tijela njegova.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (29, 17, 5, 'Bit će k\'o kad žetelac žito hvata, a ruka mu žanje klasje, kao kad se pabirče klasovi u refajimskoj dolini -');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (29, 17, 6, 'ostat će samo pabirci; ili kao kad se otresa maslina: dvije-tri uljike sasvim na vrhu, četiri ili pet na granama drveta - riječ je Jahve, Boga Izraelova.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (29, 17, 7, 'U onaj dan čovjek će pogledati na svog Stvoritelja i upraviti oči k Svecu Izraelovu.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (29, 17, 8, 'Neće više gledati žrtvenika, djela svojih ruku, neće više gledati onoga što njegovi prsti stvoriše: ašere i sunčane stupove.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (29, 17, 9, 'U onaj će dan gradovi tvoji biti napušteni, kao što bjehu napušteni hivijski i amorejski kad ih ostaviše pred Izraelcima, i opustjet će,');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (29, 17, 10, 'jer si zaboravio Boga svog spasenja i nisi se spomenuo Stijene svoje snage. Stog\' i sadiš ljupke biljke i strane presađuješ mladice;');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (29, 17, 11, 'u dan kad ih posadiš, one izrastu, a ujutro procvatu tvoje sadnice, al\' propada žetva u dan nevolje, u dan boli neizlječive.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (29, 17, 12, 'Jao, buka naroda mnogobrojnih; buče kao što buči more; šum naroda koji šume k\'o što šumore silne vode.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (29, 17, 13, 'Šume narodi kao što silne vode šumore, al\' kad On im zaprijeti, bježe daleko, po gorama razvijani kao pljeva na vjetru, k\'o prašina u vihoru.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (29, 17, 14, 'Navečer eto straha; prije svanuća više ga nema: to je sudba onih koji nas plijene i kob onih što nas pljačkaju.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (29, 18, 1, 'Jao zemlji krilatih kukaca s one strane rijeka kuških,');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (29, 18, 2, 'tebi koja šalješ morem glasnike i vodom u čamcima rogoznim. Idite, brze skoroteče, k narodu stasitu, tamnoputu, k narodu kog se boje odvajkada, narodu žilavu, zavojevaču, čija je zemlja rijekama izbrazdana.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (29, 18, 3, 'Svi stanovnici kruga zemaljskoga, i vi, žitelji zemlje, kad se zastava na brdu digne, gledajte; kad rog zatrubi, slušajte.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (29, 18, 4, 'Jer ovako mi govori Jahve: \"Mirno ću gledati s mjesta svojega, k\'o prozirna žega podnevna, k\'o rosan oblak za vrućine žetvene.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (29, 18, 5, 'Prije berbe, kad loza ocvate i cvijet u grozdove dozri, nožima će posjeći mladice, povezati, ukloniti grane.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (29, 18, 6, 'Svi će biti ostavljeni grabljivicama gorskim i zvijerima zemaljskim. Grabljivice će na njima ljetovati, zvijeri zemaljske zimovati.\"');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (29, 18, 7, 'U ono će vrijeme narod stasit i tamnoputan, narod kojega se boje odvajkada, narod žilav i zavojevački, čija je zemlja izbrazdana rijekama, donositi darove Jahvi nad Vojskama, k mjestu imena Jahve nad Vojskama - na goru Sion.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (29, 19, 1, 'Proroštvo o Egiptu. Gle, Jahve sjedi na brzu oblaku, u Egipat dolazi. Dršću pred njim idoli egipatski, u njedrima premire srce Egipćana.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (29, 19, 2, 'Podbost ću Egipćane protiv Egipćana, i brat će se s bratom svojim boriti, drug s drugom, grad s gradom, a kraljevstvo s kraljevstvom.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (29, 19, 3, 'Egiptu se pamet muti, ja sprečavam njegove naume; oni traže idole i vrače, opsjenare i gatare.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (29, 19, 4, 'Egipćane ja predajem u ruke gospodaru okrutnu, kralj silovit njima će vladati - riječ je Jahve nad Vojskama.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (29, 19, 5, 'Nestat će vode iz mora, presahnut će i presušiti Rijeka,');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (29, 19, 6, 'zaudarat će prokopi, spast će rukavci Rijeke egipatske i presušiti. Uvenut će trska i sita,');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (29, 19, 7, 'sva zelen pokraj Nila; usahnut će na Nilu svi usjevi, propast će, raspršit\' se, iščeznuti.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (29, 19, 8, 'Tužit će ribari, kukat će svi što u Nil udicu bacaju; jadikovat će oni što u vodi mrežu razapinju.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (29, 19, 9, 'Postidjet će se lanari, grebenari i tkači bijela tkanja.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (29, 19, 10, 'Snuždit će se tkalci, rastužiti radnici.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (29, 19, 11, 'Pravi su luđaci knezovi soanski, mudri savjetnici faraonovi glupo svjetuju; kako se usuđujete reći faraonu: \"Učenik sam mudraca, učenik drevnih kraljeva?\"');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (29, 19, 12, 'TÓa gdje su tvoji mudraci? Nek\' ti dojave i obznane što je Jahve nad Vojskama nakanio s Egiptom.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (29, 19, 13, 'Ludi su knezovi taniški, prevareni knezovi memfiški, oni zavode Egipat, glavare njegovih plemena.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (29, 19, 14, 'U njih je ulio Jahve duh vrtoglavi te zavode Egipat u svakom mu činu da tetura k\'o pijanac kada bljuje.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (29, 19, 15, 'U Egiptu više ne može uspjeti ništa od onog što čine glava i rep, palma i sita.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (29, 19, 16, 'U onaj će dan Egipćani postati kao žene, drhtat će i strepiti od zamaha ruke Jahve nad Vojskama kojom će zamahnuti na njih.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (29, 19, 17, 'Zemlja će Judina biti na užas Egiptu; kad god je se sjeti, strah će ga obuzeti zbog onoga što je Jahve nad Vojskama protiv njega naumio.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (29, 19, 18, 'U onaj će se dan u zemlji egipatskoj pet gradova što govore kanaanskim jezikom zakleti Jahvi nad Vojskama; jedan će se od njih zvati Ir Hahres.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (29, 19, 19, 'U onaj će dan biti žrtvenik Jahvin usred zemlje egipatske i stup posvećen Jahvi blizu granice njegove.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (29, 19, 20, 'To će Jahvi nad Vojskama biti znak i svjedočanstvo u egipatskoj zemlji. Kad zazovu Jahvu protiv tlačitelja, on će im poslati spasitelja i vođu da ih izbavi.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (29, 19, 21, 'I objavit će se Jahve Egipćanima, i u onaj će dan Egipćani spoznati Jahvu; služit će mu žrtvama i prinosima, zavjetovat će se i izvršavati zavjete.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (29, 19, 22, 'Jahve će teško udariti Egipćane, ali će ih iscijeliti; obratit će se oni Jahvi i on će ih uslišiti i iscijeliti.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (29, 19, 23, 'U onaj će dan ići cesta od Egipta do Asirije. Asirci će dolaziti u Egipat, a Egipćani u Asiriju. Egipat i Asirija služit će Jahvi.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (29, 19, 24, 'U onaj će dan Izrael, treći s Egiptom i Asirijom, biti blagoslovljen usred zemlje.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (29, 19, 25, 'Jahve nad Vojskama blagoslovit će ga: \"Nek\' je blagoslovljen\", reći će, \"moj narod egipatski, djelo mojih ruku Asirija i baština moja Izrael.\"');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (29, 20, 1, 'U godini kad je vrhovni vojskovođa, koga bijaše poslao Sargon, kralj asirski, došao u Ašdod, napao ga i zauzeo,');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (29, 20, 2, 'u to vrijeme reče Jahve po Izaiji, sinu Amosovu: \"Hajde, skini kostrijet s bokova i obuću izuj s nogu.\" On to učini te iđaše gol i bos.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (29, 20, 3, 'Tada reče Jahve: \"Kao što je sluga moj Izaija tri godine išao gol i bos kao znak i znamenje Egiptu i Kušu,');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (29, 20, 4, 'tako će kralj asirski odvesti sužnje iz Egipta i izgnanike iz Kuša, mlade i stare, gole i bose, otkrivenih zadnjica, sramote Egipta.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (29, 20, 5, 'Zbunit će se tad i posramiti zbog Kuša, svoje uzdanice, i Egipta, svojega ponosa.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (29, 20, 6, 'I reći će u onaj dan stanovnici ovog primorja: \'Eto, to je uzdanica naša kojoj se utjecasmo da nam pomogne i spasi nas od kralja asirskoga. A kako da se mi spasimo?\'\"');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (29, 21, 1, 'Proroštvo primorskoj pustinji. Kao što vihori, hujeći nad Negebom, dolaze iz pustinje, kraja strahotna');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (29, 21, 2, '- otkri mi se u strašnom viđenju - tako pljačkaš pljačka, pustošnik pustoši. \"Navali, Elame, opsjedni, Medijo! Dokrajčit ću sve jauke.\"');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (29, 21, 3, 'Zato bedra moja probadaju grčevi; bolovi me spopadaju k\'o trudovi porodilju; od smućenosti ogluših, od straha obnevidjeh.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (29, 21, 4, 'Srce mi dršće, groza me obuze, sumrak za kojim čeznuh postade mi užas.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (29, 21, 5, 'Postavljaju stol, prostiru stolnjak, jede se i pije... Ustajte, knezovi, mažite štit!');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (29, 21, 6, 'Jer Gospod mi ovako reče: \"Idi, postavi stražara! Što vidi, nek\' javi.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (29, 21, 7, 'Vidi li konjanike, jahače udvojene, jahače na magarcima, jahače na devama, neka dobro pazi s pažnjom napetom!\"');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (29, 21, 8, 'A stražar viknu: \"Povazdan, Gospodaru, stojim na stražarnici, čitavu noć na straži prostojim.\"');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (29, 21, 9, 'I gle, dolaze konjanici, jahači udvojeni. Oni mi viknuše, oni rekoše: \"Pade, pade Babilon! Svi kipovi njegovih bogova o zemlju se razbiše.\"');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (29, 21, 10, 'Omlaćeno žito, čedo gumna moga, što čuh od Jahve nad Vojskama, Boga Izraelova, objavih vam!');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (29, 21, 11, 'Proroštvo o Edomu. Viču mi iz Seira: \"Stražaru, koje je doba noći? Stražaru, koje je doba noći?\"');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (29, 21, 12, 'Stražar odgovori: \"Dolazi jutro, a zatim opet noć. Hoćete li pitati, pitajte, vratite se, dođite!\"');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (29, 21, 13, 'Proroštvo o Arapima. U šikarama pustinjskim počivate, dedanske karavane.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (29, 21, 14, 'Vodu iznesite pred žedne, stanovnici zemlje temske, iziđite s kruhom pred bjegunca.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (29, 21, 15, 'Pred mačevima bježe oni, pred mačem trgnutim, pred lukom zapetim, pred bojem žestokim.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (29, 21, 16, 'Da, ovako mi reče Gospod: \"Još jedna godina, godina nadničarska, i nestat će sve slave Kedrove.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (29, 21, 17, 'A od mnogobrojnih strijelaca među hrabrim sinovima Kedrovim malo će ih ostati.\" Tako je govorio Jahve, Bog Izraelov.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (29, 22, 1, 'Proroštvo o Dolini viđenja: Što ti je da uzlaziš sav na krovove,');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (29, 22, 2, 'grade pun vreve, grade bučni, grade razigrani? Pobijeni tvoji ne padoše od mača, nit\' u boju poginuše mrtvi tvoji;');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (29, 22, 3, 'glavari svi ti zajedno pobjegoše, u ropstvo padoše luka ne napevši. Zasužnjeni su svi tvoji knezovi, zalud umakoše daleko.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (29, 22, 4, 'Zato velim: \"Ostavite me, zaplakat ću gorko; nemojte me tješiti zbog uništenja naroda moga.\"');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (29, 22, 5, 'Jer ovo je dan pometnje i rasula od Jahve, Gospoda nad Vojskama. U Dolini viđenja zid se ruši, vapaj za pomoć diže se u goru.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (29, 22, 6, 'Elam tobolac uzima, Aram konja jaše, a Kir štit otkriva.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (29, 22, 7, 'Krasne doline tvoje pune su bojnih kola, konjanici stižu pred vrata.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (29, 22, 8, 'Tako pada Judi zaštita. U onaj dan svrnuo si pogled na oružje u Šumskoj kući.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (29, 22, 9, 'Vidjeste da u gradu Davidovu ima mnogo pukotina. Sabraste vodu iz Donjega ribnjaka.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (29, 22, 10, 'Prebrojiste kuće jeruzalemske, porušiste kuće da zid učvrstite.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (29, 22, 11, 'Između dva zida načiniste spremište za vodu iz starog ribnjaka. Ali se ne obazreste na Tvorca, nit\' vidjeste onog što davno sve smisli.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (29, 22, 12, 'Gospod, Jahve nad Vojskama, pozivaše vas u dan onaj da plačete i tugujete, da obrijete glave i pripašete kostrijet.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (29, 22, 13, 'A gle: radost i veselje, ubijaju goveda i kolju ovce; jedu meso i piju vino: \"Jedimo i pijmo, jer sutra nam je mrijeti.\"');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (29, 22, 14, 'Ali Jahve nad Vojskama objavi mi: \"Dok ne umrete, grijeh taj neće vam se oprostiti\", reče Jahve, Gospod nad Vojskama.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (29, 22, 15, 'Ovako govori Jahve, Gospod nad Vojskama: \"Hajde, idi k onom dvorjaninu, k Šibni, nadstojniku dvora,');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (29, 22, 16, 'koji kleše sebi grob na uzvisini i u stijeni sebi prebivalište usijeca: \'Što tu posjeduješ i koga tu imaš da sebi klešeš grobnicu?\'');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (29, 22, 17, 'Gle, Jahve će te baciti daleko udarcem jednim jedinim, snažno će te uhvatiti,');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (29, 22, 18, 'smotat će te u klupko, kao loptu te baciti po zemlji širokoj! Ondje ti ćeš umrijeti, s kolima što ti bijahu na slavu, ti, sramoto dvoru svoga gospodara!\"');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (29, 22, 19, 'Lišit ću te tvoje službe, otjerat te sa tvog mjesta;');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (29, 22, 20, 'i pozvat ću svoga slugu Elijakima, sina Hilkijina.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (29, 22, 21, 'Obući ću mu tvoju haljinu, tvojim ću ga pojasom opasat\', tvoju ću mu vlast predati u ruke te će biti otac žiteljima jeruzalemskim i kući Judinoj.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (29, 22, 22, 'Metnut ću mu na pleća ključ od kuće Davidove: kad otvori, nitko neće zatvoriti, kad zatvori, nitko neće otvoriti.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (29, 22, 23, 'Kao klin zabit ću ga na tvrdu mjestu; i postat će prijesto slave domu oca svojega.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (29, 22, 24, 'O njega će se vješati sva slava njegova doma očinskog, izdanci i potomstvo, sve malo posuđe, od zdjelica do ćupova.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (29, 22, 25, 'U onaj dan - riječ je Jahve nad Vojskama - izvući će se klin zabijen na tvrdu mjestu, slomit će se i pasti. I sav teret što je visio na njemu razbit će se, jer je Jahve govorio.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (29, 23, 1, 'Proroštvo o Tiru. Kukajte, lađe taršiške, jer vaša je tvrđa razorena! Javljeno im je dok se iz kitimske vraćahu zemlje.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (29, 23, 2, 'Umuknite, stanovnici primorja, trgovci sidonski, kojih su glasnici brodili morem po vodi velikoj.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (29, 23, 3, 'Sjetva Nila, žetva Rijeke, bijaše njegovo bogatstvo. On bijaše sajmište narodima.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (29, 23, 4, 'Stidi se, Sidone, jer more govori: \"Ne hvataju me trudovi niti rađam, ne odgajam momaka nit\' podižem djevojaka.\"');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (29, 23, 5, 'Uzdrhtat će Egipćani kad o Tiru vijest čuju.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (29, 23, 6, 'Otplovite u Taršiš, kukajte, stanovnici primorja.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (29, 23, 7, 'Je li to vaš grad veseli što postoji od davnih davnina i noge ga daleko nosile da se ondje naseli?');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (29, 23, 8, 'Tko li je to odlučio protiv Tira okrunjenog, kojeg trgovci bijahu knezovi a prekupci odličnici zemlje?');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (29, 23, 9, 'Jahve nad Vojskama odluči tako da osramoti ponosnu slavu, da ponizi sve odličnike zemlje.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (29, 23, 10, 'Obrađuj zemlju, kćeri taršiška, tvoje luke više nema!');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (29, 23, 11, 'Ruku svoju Gospod diže na more i kraljevstvima zadrma. Zapovjedi Jahve da se razore tvrđave kanaanske.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (29, 23, 12, 'Rekao je: \"Nećeš više klikovati, okaljana djevice, kćeri sidonska!\" Ustani i idi u Kitim; ni ondje nećeš imati mira.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (29, 23, 13, 'Evo zemlje kitimske... podižu se kule opsadne, razaraju utvrde, sve je ruševina.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (29, 23, 14, 'Kukajte, brodovi taršiški, razorena je vaša tvrđava!');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (29, 23, 15, 'Dogodit će se, u onaj dan, da će Tir biti zaboravljen sedamdeset godina, kao dani jednoga kralja. A poslije sedamdeset godina Tiru će biti kao bludnici iz pjesme:');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (29, 23, 16, '\"Uzmi citaru i skići se gradom, bludnice zaboravljena! Sviraj lijepo, pjevaj mnogo, da te se spomenu!\"');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (29, 23, 17, 'Poslije sedamdeset godina pohodit će Jahve Tir. I grad će opet dobivati svoju plaću bludničku. Podavat će se bludu sa svim kraljevstvima svijeta na licu zemlje.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (29, 23, 18, 'Ali će njegova dobit i plaća biti posvećena Jahvi; neće se zgrtati ni čuvati, nego će njegova dobit biti za one koji prebivaju pred Jahvom da imaju hrane do sita i doličnu odjeću.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (29, 24, 1, 'Gle, Jahve razvaljuje zemlju, razara je, nakazi joj lice, raspršuje stanovnike njene.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (29, 24, 2, 'Svećenik će biti k\'o i narod, gospodar k\'o i sluga, gospodarica k\'o i sluškinja, prodavač k\'o i kupac, zajmodavac k\'o i zajmoprimac, vjerovnik k\'o i dužnik.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (29, 24, 3, 'Opustošena će biti zemlja, opljačkana sasvim, jer je Jahve odlučio.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (29, 24, 4, 'Zemlja tuži, vene, svijet gine, gasne, nebo sa zemljom propada.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (29, 24, 5, 'Oskvrnjena je zemlja pod žiteljima svojim, jer prestupiše Zakon, pogaziše odredbu, Savez vječni razvrgoše.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (29, 24, 6, 'Zato prokletstvo proždire zemlju, okajavaju stanovnici njeni. Zato su sažgani žitelji zemljini i malo je ljudi preostalo.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (29, 24, 7, 'Vino tuguje, loza vene, uzdišu svi što bijahu srca vesela.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (29, 24, 8, 'Prestalo je veselje uz bubnje, zamrla je graja razigrana; umukla je glazba citara.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (29, 24, 9, 'Ne pije se više vino uz pjesmu, ogrknu piće silovito.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (29, 24, 10, 'Razoren je grad ništavila, zatvoren ulaz svim kućama.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (29, 24, 11, 'Jauk po ulicama zbog vina, nesta svakog veselja, radost je iz zemlje prognana.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (29, 24, 12, 'Tek pustoš ostade u gradu, u trijeske smrskana su vrata.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (29, 24, 13, 'Jer tako se zbiva na zemlji, među narodima, kao kad se oberu masline il\' paljetkuje grožđe nakon berbe.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (29, 24, 14, 'Oni glas podižu, kliču od radosti; uznose s mora veličajnost Jahvinu.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (29, 24, 15, 'I na istoku ime Jahve slave oni, na otocima mora ime Jahve, Boga Izraelova.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (29, 24, 16, 'S kraja zemlje čujemo pjesme: \"Slava Pravedniku!\" Ali ja kažem: \"Propadoh! Propadoh! Jao meni! Vjerolomci se iznevjeriše, nevjerom se, vjerolomci, iznevjeriše.\"');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (29, 24, 17, 'Strava, jama, zamka tebi, žitelju zemlje:');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (29, 24, 18, 'tko pred glasom strave uteče u jamu će upasti; tko se iz jame izvuče zamka će ga uhvatit\'. Da, otvorit će se ustave u visini i zatresti zemlji temelji.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (29, 24, 19, 'Zemlja će se grozno razbiti, zemlja će se strašno raspući, zemlja će se silno uzdrmati,');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (29, 24, 20, 'zemlja će zateturati poput pijanca, zanjihat se poput kolibe; toliko će joj otežati bezakonje njeno da će pasti i neće više ustati.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (29, 24, 21, 'I dogodit će se u onaj dan: Jahve će kazniti u visini Vojsku nebesku, a na zemlji sve kraljeve zemaljske;');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (29, 24, 22, 'bit će sakupljeni i zasužnjeni u jami, zatvoreni u tamnicu i nakon mnogih dana kažnjeni.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (29, 24, 23, 'Pocrvenjet će mjesec, postidjet se sunce, jer će kraljevati Jahve nad Vojskama na gori Sionu i u Jeruzalemu i Slava će mu sjati pred starješinama.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (29, 25, 1, 'Jahve, ti si Bog moj, uznosim te, tvoje ime slavim, jer si proveo čudesan naum, smišljen od davnine, istinit i vjeran,');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (29, 25, 2, 'jer grad si pretvorio u hrpu kamenja, a mjesto utvrđeno u ruševine. Tvrđa neprijateljska više nije grad, dovijeka se više obnoviti neće.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (29, 25, 3, 'Zato te slavi narod snažan, grad moćnih plemena tebe se boji;');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (29, 25, 4, 'jer ti si utočište nevoljnom, utočište ubogom u nevolji; ti si skrovište od pljuska i od žege zaklon, jer ćud je silnička kao pljusak zimski;');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (29, 25, 5, 'kao žega nad zemljom sušnom ti gušiš graju neprijatelja; kao žega sjenom oblaka prekinu se silniku pjesma pobjednička.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (29, 25, 6, 'I Jahve nad Vojskama spremit će svim narodima na ovoj gori gozbu od pretiline, gozbu od izvrsna vina, od pretiline sočne, od vina staložena.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (29, 25, 7, 'Na ovoj gori on će raskinuti zastor što zastiraše sve narode, pokrivač koji sva plemena pokrivaše');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (29, 25, 8, 'i uništit će smrt zasvagda. I suzu će sa svakog lica Jahve, Gospod, otrti - sramotu će svog naroda na svoj zemlji skinuti: tako Jahve reče.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (29, 25, 9, 'I reći će se u onaj dan: \"Gle, ovo je Bog naš, u njega se uzdasmo, on nas je spasio; ovo je Jahve u koga se uzdasmo! Kličimo i veselimo se spasenju njegovu,');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (29, 25, 10, 'jer ruka Jahvina na ovoj gori počiva!\" Moab je izgažen na svome mjestu kao što se gazi slama na buništu;');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (29, 25, 11, 'ondje on razmahuje rukama kao što ih razmahuje plivač kada pliva. Ali Jahve obara njegovu ponositost i propinjanja ruku njegovih.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (29, 25, 12, 'Visoku tvrđu tvojih zidina on razvaljuje, na zemlju baca, u prah ruši.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (29, 26, 1, 'U onaj dan pjevat ću ovu pjesmu u zemlji Judinoj: \"Tvrd grad mi imamo: za obranu nam On podiže zidove i predziđa.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (29, 26, 2, 'Otvorite vrata! Nek\' uđe narod pravedni koji čuva vjernost,');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (29, 26, 3, 'čiji je značaj čvrst, koji čuva mir jer se u te uzda.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (29, 26, 4, 'Uzdajte se u Jahvu dovijeka, jer Jahve je Stijena vječna;');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (29, 26, 5, 'on obara one koji obitavahu visoko, razvaljuje tvrđu visoku, ruši u prah, sravnjuje sa zemljom,');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (29, 26, 6, 'te je gaze noge, noge ubogih i koraci nevoljnih.\"');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (29, 26, 7, 'Put je pravednikov prav, ti ravniš stazu pravednom.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (29, 26, 8, 'Da, na stazi tvojih sudova željno te, Jahve, čekamo; ime tvoje i spomen tvoj duša nam žudi.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (29, 26, 9, 'Dušom svojom žudim tebe noću i duhom svojim u sebi te tražim. Jer kad se na zemlji pojave tvoji sudovi, uče se pravdi stanovnici kruga zemaljskoga.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (29, 26, 10, 'Ako se pomiluje opaki, on se ne uči pravednosti. U zemlji pravednosti on čini bezakonje i ne obazire se na veličanstvo Jahvino.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (29, 26, 11, 'Jahve, ruka je tvoja podignuta, a oni je ne vide. Nek\' vide i postide se, nek\' ih proguta revnost za narod, nek\' ih proždre oganj pripravljen dušmanima tvojim.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (29, 26, 12, 'Jahve, ti mir nama daješ, jer ti si tvorac svih djela naših.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (29, 26, 13, 'Jahve, Bože naš, gospodarili su nama osim tebe drugi gospodari, ali tebe jedinog, ime tvoje, častimo.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (29, 26, 14, 'Mrtvi neće oživjeti, sjene neće uskrsnuti, jer ti si ih kaznio i uništio i zatro svaki spomen na njih!');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (29, 26, 15, 'Umnožio si narod, Jahve, umnožio si narod, proslavio se, proširio sve granice zemlje!');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (29, 26, 16, 'Jahve, tražili su te u nevolji; izlijevali tihu molitvu, kad ih je stigla tvoja kazna.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (29, 26, 17, 'Kao što se trudna žena pred porođajem grči i viče u bolovima, takvi smo, Jahve, pred tobom.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (29, 26, 18, 'Zatrudnjeli smo, u mukama smo kao da rađamo, nismo donijeli duha spasenja zemlji nit\' se rodiše stanovnici svijeta.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (29, 26, 19, 'Tvoji će mrtvi oživjeti, uskrsnut će tijela. Probudite se i kličite, stanovnici praha! Jer rosa je tvoja - rosa svjetlosti, i zemlja će sjene na svijet dati.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (29, 26, 20, 'Hajde, narode moj, uđi u sobe i vrata za sobom zatvori. Sakrij se časkom dok jarost ne prođe.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (29, 26, 21, 'Jer, gle, izići će Jahve iz svog prebivališta da stanovnike zemljine kazni što se o njeg\' ogriješiše. Izbacit će zemlja svu krv što je na njoj prolivena i neće više kriti onih koji su na njoj poklani.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (29, 27, 1, 'U onaj dan kaznit će Jahve mačem ljutim, velikim i jakim Levijatana, zmiju hitru, Levijatana, zmiju vijugavu, i ubit će zmaja morskoga.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (29, 27, 2, 'U onaj dan pjevajte mu, vinogradu vinorodnom:');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (29, 27, 3, 'Ja, Jahve, njega čuvam, svaki čas ga zalijevam, i da ga tko ne ošteti, danju i noću stražim.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (29, 27, 4, 'Nema gnjeva u meni! Nek\' se trnje i drač samo pojavi, protiv njega ustat ću u boj, svega ću ga sažgati!');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (29, 27, 5, 'Ili u moje nek\' dođe okrilje, neka sklopi mir sa mnom, mir neka sklopi sa mnom!');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (29, 27, 6, 'Dolaze dani kad će se ukorijeniti Jakov, razgranit\' se i procvasti Izrael, i sav svijet plodovima napuniti.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (29, 27, 7, 'Je li ga udario kako udari one koji njega udarahu? Je li ga ubio kako ubi one koji njega ubiše?');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (29, 27, 8, 'Za kaznu ga potjera, izagna, odnese ga silnim dahom svojim u dan istočnjaka.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (29, 27, 9, 'Tako će se okajati bezakonje Jakovljevo; a ovo je sve plod oproštenja grijeha njegova. Neka se smrve svi kamenovi žrtvenika kao što se u prah drobi krečno kamenje! Nek\' se više ne dižu ašere i sunčani stupovi!');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (29, 27, 10, 'Jer opustje tvrdi grad, naselje je poharano, napušteno kao pustinja. Telad ondje pase - leži ondje, grmlje brsti.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (29, 27, 11, 'Kad mu se osuše grane, lome ih, dolaze žene i oganj pale. Jer to je narod nerazuman, zato ga neće žaliti Stvoritelj, Tvorac mu se neće smilovati.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (29, 27, 12, 'Jahve će u dan onaj klasje vrijeći od Eufrata do Potoka egipatskog, i bit ćete pobrani jedan po jedan, djeco Izraelova.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (29, 27, 13, 'U onaj dan zatrubit će velika trublja, i doći će izgubljeni u zemlji asirskoj, i koji bijahu izgnani u zemlju egipatsku, i poklonit će se Jahvi na Svetoj gori, u Jeruzalemu.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (29, 28, 1, 'Teško gizdavu vijencu pijanica Efrajimovih, uvelu cvijetu blistava mu nakita - onima što uvrh plodnog dola leže vinom opijeni!');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (29, 28, 2, 'Evo, od Gospoda jaki i moćni, kao pljusak s tučom, kao vihor razorni, prolom oblaka i povodanj, i svom ih snagom na zemlju baca.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (29, 28, 3, 'Bit će izgažen nogama gizdav vijenac pijanica Efrajimovih');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (29, 28, 4, 'i uveo cvijet blistava mu nakita uvrh plodnih dolina; bit će kao rana smokva prije ljeta: čim je tko spazi, odmah je ubere.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (29, 28, 5, 'U onaj dan Jahve nad Vojskama postat će kruna slave i sjajan vijenac Ostatku svoga naroda -');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (29, 28, 6, 'duh pravde onome koji sjedi na stolici sudačkoj i srčanost onome koji odbija napad na vrata.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (29, 28, 7, 'Oni posrću od vina, teturaju od žestoka pića: svećenici i proroci od žestoka pića posrću; omami ih vino; teturaju od žestoka pića, posrću u viđenjima, ljuljaju se sudeći.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (29, 28, 8, 'Svi su stolovi puni gnusnih bljuvotina, nigdje čista mjesta nema!');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (29, 28, 9, '\"Koga on to uči mudrosti, koga on upućuje u objavu? Zar djecu odviknutu od mlijeka odbijenu od prsiju?');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (29, 28, 10, 'Sav la-sav, sav la-sav, kav la-kav, kav la-kav, zeer šam, zeer šam.\"');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (29, 28, 11, 'Da, mucavim usnama i na stranom jeziku govorit će se ovom narodu.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (29, 28, 12, 'On im reče: \"Evo počinka, dajte umornom da otpočine! Evo odmora!\" Ali ne htjedoše poslušati.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (29, 28, 13, 'Zato će im Jahve ovako govoriti: \"Sav la-sav, sav la-sav, kav la-kav, kav la-kav, zeer šam, zeer šam\", da hodeći padnu nauznak, da se razbiju, zapletu i uhvate.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (29, 28, 14, 'Stoga čujte riječ Jahvinu, vi podsmjevači, vi što vladate narodom ovim koji je u Jeruzalemu.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (29, 28, 15, 'Vi velite: \"Sklopismo savez sa smrću i s Podzemljem učinismo sporazum. Kad prođe bič razorni, ne, neće nas dohvatiti, jer od laži načinismo sebi sklonište i od obmane skrovište.\"');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (29, 28, 16, 'Stog ovako govori Jahve Gospod: \"Evo, postavljam na Sion kamen odabrani, dragocjen kamen ugaoni, temeljac. Onaj koji u nj vjeruje neće propasti.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (29, 28, 17, 'I uzet ću pravo za mjeru, a pravdu za tezulju.\" I tuča će vam zastrti sklonište od laži, a voda otplaviti skrovište;');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (29, 28, 18, 'propast će savez vaš sa smrću, vaš sporazum s Podzemljem održat\' se neće. Kada bič razorni prođe, satrt će vas;');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (29, 28, 19, 'kad god prođe, dohvatit će vas; prolazit će svako jutro, danju i noću. Samo će vas strah uputit u objavu.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (29, 28, 20, 'Prekratka će bit\' postelja da se čovjek pruži, preuzak pokrivač da se umota.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (29, 28, 21, 'Da, kao na gori Perasimu, Jahve će ustati, kao u Dolini gibeonskoj, on će se razjariti, da izvrši djelo svoje, djelo čudnovato, da ispuni naum svoj, naum tajnoviti.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (29, 28, 22, 'Podsmijevanja se okanite, da vas jače okovi ne stegnu; jer čuh da je od Gospoda, Jahve nad Vojskama, zemlji ovoj dosuđeno uništenje.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (29, 28, 23, 'Poslušajte i čujte glas moj, prisluhnite pomno moju besjedu.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (29, 28, 24, 'Ore li orač svakog dana, brazdi, brana njivu svoju?');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (29, 28, 25, 'A kad joj poravna površinu, ne sije li grahor, ne sipa li kumin? Pšenicu gdje treba, proso i ječam, i napokon raž po rubovima?');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (29, 28, 26, 'Bog ga njegov upućuje, on ga uči djelu pravom.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (29, 28, 27, 'Ne mlati se grahor cijepom, nećeš točkom po kuminu, već se grahor štapom mlati, a kumin se prutom lupa.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (29, 28, 28, 'A da li se žito tare? Ne, nećeš ga dovijeka mlatiti: po njem ćeš pognat kolski točak i konje, ali ga zdrobiti nećeš.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (29, 28, 29, 'I to dolazi od Jahve nad Vojskama, savjetom divnog, mudrošću velikog.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (29, 29, 1, 'Teško Arielu! Arielu, gradu što ga opkoli David! Nek\' se niže godina na godinu, nek\' se izredaju blagdani,');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (29, 29, 2, 'pa ću pritisnuti Ariel i nastat će jauk i lelek. Za mene ćeš biti Ariel,');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (29, 29, 3, 'opkolit ću te kao David, rovovima okružiti, suprot tebi nasipe ću dići.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (29, 29, 4, 'Oboren govorit ćeš sa zemlje, iz praha mucat\' riječju prigušenom, glas će ti se iz zemlje dizat\' kao pokojnikov, iz praha ćeš šaptati besjedu.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (29, 29, 5, 'Kao sitna prašina bit će mnoštvo tvojih dušmana, kao pljeva razvijana - rulja silnika: i odjednom, u tren oka:');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (29, 29, 6, 'pohodit će te Jahve nad Vojskama grmljavinom, tutnjem, bukom velikom, vihorom, olujom i plamenim ognjem što proždire.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (29, 29, 7, 'Bit će k\'o san, utvara noćna: mnoštvo svih naroda što vojuje s Arielom i svih onih koji zavojštiše na nj i na utvrde njegove i koji ga odasvud pritijesniše.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (29, 29, 8, 'Bit će kao kad gladan sanja da jede, a probudi se prazna želuca; i kao kad žedan sanja da pije, pa se, iznemogao, suha grla probudi. Tako će se dogoditi mnoštvu naroda koji vojuju protiv Gore sionske.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (29, 29, 9, 'Stanite, skamenite se od čuda, oslijepite i obnevidite! Pijani su, ali ne od vina, posrću, ali ne od silna pića.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (29, 29, 10, 'Jahve je izlio na vas duh obamrlosti, zatvorio je oči vaše - proroke, zastro glave vaše - vidioce.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (29, 29, 11, 'Zato će vam svako viđenje biti kao riječi u zapečaćenoj knjizi: dade li se kome tko zna čitati govoreći: \"De, čitaj to!\" - on će odgovoriti: \"Ne mogu jer je zapečaćena.\"');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (29, 29, 12, 'A dade li se kome tko ne zna čitati govoreći: \"Čitaj to!\" - on će odvratiti: \"Ne znam čitati.\"');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (29, 29, 13, 'Jahve reče: \"Jer mi narod ovaj samo ustima pristupa i samo me usnama časti, a srce mu je daleko od mene i njegovo štovanje naučena ljudska uredba,');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (29, 29, 14, 'zato ću, evo, i dalje čudno postupati s ovim narodom - čudno i prečudno: i propast će mudrost njegovih mudraca, pomračit se umnost njegovih umnika.\"');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (29, 29, 15, 'Teško onima koji se od Jahve kriju da bi svoje sakrili namjere i koji u mraku djeluju i zbore: \"Tko nas vidi i tko nas pozna?\"');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (29, 29, 16, 'Kolike li naopakosti vaše! Cijeni li se glina kao lončar, pa da djelo rekne svome tvorcu: \"NIje me on načinio\"? Ili lonac da rekne lončaru: \"On ne razumije ništa\"?');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (29, 29, 17, 'Neće li se naskoro Libanon u voćnjak pretvoriti, a voćnjak izroditi u šumu?');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (29, 29, 18, 'I čut će u onaj dan gluhi riječi knjige; oslobođene mraka i tmine, oči će slijepih vidjeti.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (29, 29, 19, 'A siromasi će se opet radovati u Jahvi, najbjedniji će klicat\' Svecu Izraelovu,');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (29, 29, 20, 'jer neće više biti silnika, nestat će podsmjevača, istrijebit će se svi koji zlo snuju:');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (29, 29, 21, 'oni koji riječju druge okrivljuju, oni koji na vratima sucu postavljaju zamku i nizašto obaraju pravednika.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (29, 29, 22, 'Zato ovako govori Jahve, Bog kuće Jakovljeve, koji otkupi Abrahama: \"Neće se odsad više stidjeti Jakov i više mu neće lice blijedjeti,');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (29, 29, 23, 'jer kad vidi usred sebe djelo mojih ruku, svetit će ime moje.\" Svetit će Sveca Jakovljeva, bojat će se Boga Izraelova.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (29, 29, 24, 'Zabludjeli duhom urazumit će se, a oni što mrmljaju primit će pouku.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (29, 30, 1, 'Teško sinovima odmetničkim! - riječ je Jahvina. Oni provode osnove koje nisu moje, sklapaju saveze koji nisu po mom duhu i grijeh na grijeh gomilaju.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (29, 30, 2, 'Zaputiše se u Egipat, ne pitajući usta moja, da se uteku faraonovu zaklonu i da se zaštite u sjeni Egipta.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (29, 30, 3, 'Zaklon faraonov bit će na sramotu, i na ruglo zaštita u sjeni Egipta.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (29, 30, 4, 'Eno mu knezova već u Soanu, podanici stigoše u Hanes:');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (29, 30, 5, 'svi će se oni razočarati u narodu beskorisnom, neće im biti na pomoć ni na korist, već na sramotu i porugu.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (29, 30, 6, 'Proroštvo o negepskim životinjama. Kroza zemlju nevolje i bijede, lavice i lava koji riču, ljutice i zmaja krilatog, nose oni blago na leđima magaraca i bogatstvo na grbi deva, nose ga narodu beskorisnom.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (29, 30, 7, 'Jer prazna je i ništavna pomoć Egipta, zato ga i zovemo: Rahab - danguba.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (29, 30, 8, 'Ded napiši na ploču i zapiši u knjigu da vremenima budućim svjedočanstvo ostane.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (29, 30, 9, 'Ovo je narod odmetnički, sinovi lažljivi, sinovi koji neće da slušaju Zakon Jahvin.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (29, 30, 10, 'Vidovitima oni govore: \"Okanite se viđenja!\" a vidiocima: \"Ne prorokujte istinu! Govorite nam što je ugodno, opsjene nam prorokujte!');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (29, 30, 11, 'Skrenite s puta, zastranite sa staze, uklonite nam s očiju Sveca Izraelova!\"');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (29, 30, 12, 'Stog\' ovako zbori Svetac Izraelov: \"Jer riječ ovu odbacujete, a uzdate se u opačinu i prijevaru i na njih se oslanjate,');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (29, 30, 13, 'grijeh će vam taj biti poput pukotine, visoko na zidu izbočene, koja prijeti rušenjem.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (29, 30, 14, 'Da se sruši k\'o što se glinen sud razbije, slupan nemilice, te mu se među krhotinama ne nađe ni rbine, žerave da uzmeš s ognjišta il\' zagrabiš vode iz studenca.\"');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (29, 30, 15, 'Jer ovako govori Jahve Gospod, Svetac Izraelov: \"Mir i obraćenje - spas vam je, u smirenu uzdanju snaga je vaša. Ali vi ne htjedoste.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (29, 30, 16, 'Rekoste: \'Ne! Pobjeći ćemo na konjima!\' - i zato, bježat ćete! \'Na brzim ćemo konjima jahati!\' - i zato, bit će brži vaši neprijatelji!\"');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (29, 30, 17, 'Pobjeći će vas tisuća kad jedan zaprijeti, zaprijete li petorica, u bijeg ćete nagnut\' dok vas ne preostane k\'o kopljača na vrhu gore il\' na brijegu zastava.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (29, 30, 18, 'Al\' Jahve čeka čas da vam se smiluje, i stog izglÄedÄa da vam milost iskaže, jer Jahve je Bog pravedan - blago svima koji njega čekaju.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (29, 30, 19, 'Da, puče sionski koji živiš u Jeruzalemu, više ne plači! Čim začuje vapaj tvoj, odmah će ti se smilovati; čim te čuje, uslišit će te.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (29, 30, 20, 'Hranit će vas Gospod kruhom tjeskobe, pojiti vodom nevolje, al\' se više neće kriti tvoj Učitelj - oči će ti gledati Učitelja tvoga.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (29, 30, 21, 'I uši će tvoje čuti riječ gdje iza tebe govori: \"To je put, njime idite\", bilo da vam je krenuti nadesno ili nalijevo.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (29, 30, 22, 'Smatrat ćeš nečistima svoje srebrne kumire i pozlatu svojih kipova; odbacit ćeš ih kao nečist i reći im: \"Napolje!\"');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (29, 30, 23, 'A on će dati kišu tvojem sjemenu što ga posiješ u zemlju, i kruh kojim zemlja urodi bit će obilat i hranjiv. Stoka će tvoja pasti u onaj dan po prostranim pašnjacima.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (29, 30, 24, 'Volovi i magarci što obrađuju zemlju jest će osoljenu krmu, ovijanu lopatom i vijačom.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (29, 30, 25, 'I na svakoj gori i na svakome povišenom brijegu bit će potoka i rječica - u dan silnoga pokolja kad se kule budu rušile.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (29, 30, 26, 'Tada će svjetlost mjesečeva biti kao svjetlost sunčana, a svjetlost će sunčana postati sedam puta jača, kao svjetlost sedam dana - u dan kad Jahve iscijeli prijelom svojemu narodu, izliječi rane svojih udaraca.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (29, 30, 27, 'Gle, ime Jahve izdaleka dolazi, gnjev njegov gori, dim je neizdrživ. Usne su mu pune jarosti, jezik mu oganj što proždire.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (29, 30, 28, 'Dah mu je kao potok nabujali što do grla seže. On dolazi da prosije narode rešetom zatornim, da stavi uzde zavodljive u čeljusti naroda.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (29, 30, 29, 'Tad će vam pjesma biti kao u noćima blagdanskim, kad su srca vesela kao u onoga koji uza zvuke frule hodočasti na Goru Jahvinu, k Stijeni Izraelovoj.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (29, 30, 30, 'Jahve će zagrmjet glasom veličajnim i pokazat ruku svoju što udara u jarosnu gnjevu, sred ognja zatornog, iz olujna pljuska i krupÄe kamene.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (29, 30, 31, 'Od glasa Jahvina prepast će se Asur, šibom ošinut.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (29, 30, 32, 'I kad god ga udari šiba kaznena, kojom će ga Jahve išibati, nek\' se oglase bubnjevi i citare - u sav jek boja on s njima ratuje!');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (29, 30, 33, 'Odavna je pripravljen Tofet za Moleka - lomača visoka, široka, mnogo ognja, mnogo drvlja. Dah gnjeva Jahvina, kao potok sumporni, njega će spaliti.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (29, 31, 1, 'Teško onima što slaze u Egipat po pomoć i nadu u konje polažu te se uzdaju u mnoga kola i u mnoštvo konjanika, ne gledajuć\' s uzdanjem u Sveca Izraelova i od Jahve savjeta ne tražeć\'.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (29, 31, 2, 'Al\' i on je mudar i navalit će zlo, i neće poreć\' svojih prijetnja; on će ustat\' na dom zlikovački i na pomoć zločinačku.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (29, 31, 3, 'Egipćanin je čovjek, a ne Bog; konji su mu meso, a ne duh; kada Jahve rukom mahne, posrnut će pomagač i past će onaj komu pomaže - svi će zajedno propasti.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (29, 31, 4, 'Da, ovako mi reče Jahve: Kao što lav ili lavić nad plijenom reži, pa i kad se strči na njega mnoštvo pastira, on se ne prepada vike njihove, nit\' za njihovu graju mari - tako će Jahve nad Vojskama sići da vojuje za goru Sion, za visinu njezinu.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (29, 31, 5, 'Kao ptice što lepršaju krilima, Jahve nad Vojskama zaklanjat će Jeruzalem, zaklanjat\' ga, izbaviti, poštedjet\' ga i spasiti.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (29, 31, 6, 'Vratite se onome od kog otpadoste tako duboko, sinovi Izraelovi.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (29, 31, 7, 'Da, u onaj će dan svatko prezreti svoje kumire srebrne i zlatne što ih rukama sebi za grijeh načiniste.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (29, 31, 8, 'Asur neće pasti od mača ljudskoga: proždrijet će ga mač, ali ne čovječji. Od mača će bježat\', al\' će mu satnici pod tlaku pasti.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (29, 31, 9, 'Užasnut, ostavit će svoju hridinu, prestravljeni, knezovi od svoje će bježat\' zastave - riječ je Jahve, čiji je oganj na Sionu i čija je peć u Jeruzalemu.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (29, 32, 1, 'Evo po pravdi kralj kraljuje, po pravici vladaju knezovi:');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (29, 32, 2, 'svaki je kao zavjetrina, utočište od nevremena, kao u sušnoj zemlji potoci, kao sjena u žednoj pustari.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (29, 32, 3, 'Oči vidovitih neće više biti slijepe, uši onih što čuju slušat će pozorno;');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (29, 32, 4, 'srce nerazumnih shvaćat će mudrost, mucavci će govorit\' okretno i razgovijetno;');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (29, 32, 5, 'pokvarenjaka neće više zvati plemenitim, varalicu neće više držat\' odličnikom.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (29, 32, 6, 'Jer, pokvarenjak govori ludosti i srce mu bezakonje snuje, da počini zlodjela, da o Jahvi oholo govori; da gladnoga ostavi prazna želuca, da žednome napitak uskrati.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (29, 32, 7, 'U varalice pakosno je oružje; on spletke samo kuje, da lažima upropasti uboge, pa i kad nevoljnik pravo dokazuje.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (29, 32, 8, 'U plemenita nakane su plemenite i plemenito on djeluje.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (29, 32, 9, 'Ustajte, žene nehajne, slušajte moj glas; kćeri lakoumne, čujte mi besjedu.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (29, 32, 10, 'Za godinu i nekoliko dana drhtat ćete, lakoumnice, jer jematve neće biti, plodovi se neće brati.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (29, 32, 11, 'Dršćite, nehajnice, strepite, lakoumnice, svucite se, obnažite, oko bedara kostrijet opašite!');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (29, 32, 12, 'Bijte se u prsa zbog ljupkih polja, plodnih vinograda;');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (29, 32, 13, 'zbog njiva naroda mojega što rađaju trnjem i dračem; zbog svih kuća veselih, grada razigranog.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (29, 32, 14, 'Jer, napuštena bit će palača, opustjet će bučni grad; Ofel i kula postat će brlog dovijeka - bit će radost divljim magarcima, paša stadima,');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (29, 32, 15, 'dok se na nas ne izlije duh iz visina. Tad će pustinja postat\' voćnjak, a voćnjak se u šumu pretvorit\'.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (29, 32, 16, 'U pustinji će se nastaniti pravo, i pravda će prebivati u voćnjaku.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (29, 32, 17, 'Mir će biti djelo pravde, a plod pravednosti - trajan pokoj i uzdanje.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (29, 32, 18, 'Narod će moj prebivati u nastambama pouzdanim, u bezbrižnim počivalištima.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (29, 32, 19, 'A šuma će biti oborena, grad će biti snižen.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (29, 32, 20, 'Blago vama: sijat ćete kraj svih voda, puštajući vola i magarca da slobodno idu!');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (29, 33, 1, 'Teško tebi koji nepustošen pustošiš, koji pljačkaš nepljačkan, kad prestaneš, tebe će opustošiti, opljačkat\' te kad prestaneš pljačkati.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (29, 33, 2, 'Jahve, smiluj nam se, u te se uzdamo! Budi mišica naša svako jutro, naš spas u doba nevolje.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (29, 33, 3, 'Od silna tutnja pobjegoše narodi, ti ustade, raspršiše se puci');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (29, 33, 4, 'i plijen se skuplja kao što se kupe šaške, na nj će navaliti kao jato skakavaca.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (29, 33, 5, 'Uzvišen je Jahve jer u visini stoluje, on puni Sion pravom i pravednošću.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (29, 33, 6, 'Pouzdan je tvoj vijek: mudrost i znanje spasonosno su blago - a strah Gospodnji njegovo bogatstvo.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (29, 33, 7, 'Gle, stanovništvo Arielovo kuka po ulicama, glasnici mironosni plaču gorko.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (29, 33, 8, 'Opustješe ceste, s putova nesta putnika; raskidaju se savezi, preziru se svjedoci, ni prema kome nema obzira.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (29, 33, 9, 'Gine zemlja u žalosti, u stidu vene Libanon. Šaron je kao stepa, Bašan i Karmel ogolješe.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (29, 33, 10, '\"Sada ću ustati\", veli Jahve, \"sada ću se dići, sada uzvisiti.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (29, 33, 11, 'Začeste sijeno, rodit ćete slamu; dah moj proždrijet će vas kao oganj.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (29, 33, 12, 'Narodi će biti sažgani u vapno, kao posječeno trnje što gori u vatri.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (29, 33, 13, 'Čujte, vi koji ste daleko, što sam učinio, a vi koji ste blizu poznajte mi snagu!\"');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (29, 33, 14, 'Na Sionu strepe grešnici, trepet spopada bezbožnika: \"Tko će od nas opstati pred ognjem zatornim, tko će od nas opstati pred žarom vječnim?\"');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (29, 33, 15, 'Onaj koji hodi u pravdi i pravo govori, koji prezire dobit od prinude, koji otresa ruku da ne primi mito, koji zatiskuje uši da ne čuje o krvoproliću, koji zatvara oči da ne vidi zlo:');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (29, 33, 16, 'on će prebivati u visinama, tvrđe na stijenama bit će mu utočište, imat će dosta kruha i vode će mu svagda dotjecati.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (29, 33, 17, 'Oči će ti gledati kralja u njegovoj ljepoti, promatrat će zemlju nepreglednu.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (29, 33, 18, 'Srce će ti u strahu misliti: Gdje li je onaj što je brojio, gdje li onaj što je mjerio, gdje li onaj što je prebrajao mladiće?');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (29, 33, 19, 'Nećeš više vidjeti divljega naroda, naroda nerazumljiva i neshvatljiva govora, jezika strana što ga nitko ne razumije.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (29, 33, 20, 'Pogledaj na Sion, grad blagdana naših: oči će ti Jeruzalem vidjeti, prebivalište zaštićeno, šator što se ne prenosi, kojem se kolčići nikad ne vade, nit\' mu se ijedno uže otkida.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (29, 33, 21, 'Ondje nam je Jahve silni, umjesto rijeka i širokih rukavaca: neće onud proći nijedna lađa s veslima niti će koji bojni brod projedriti.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (29, 33, 22, 'Jer Jahve je sudac naš, Jahve naš vojvoda, Jahve je kralj naš - on će nas spasiti.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (29, 33, 23, 'Užad ti je popustila, ne može držati jarbola ni razviti stijega, pa se dijeli golemo blago oteto - kljasti će se naplijeniti plijena!');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (29, 33, 24, 'I nijedan građanin neće reći: \"Bolestan sam!\" Narodu što živi ondje krivnja će se oprostiti.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (29, 34, 1, 'Pristupite, puci, da čujete, pomno slušajte, narodi; čuj, zemljo, i sve što te ispunja, kruže zemaljski i sve što raste po tebi!');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (29, 34, 2, 'Jer razgnjevi se Jahve na sve narode, razjari se na svu vojsku njihovu. Izruči ih uništenju, pokolju ih predade.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (29, 34, 3, 'Leže njihovi pobijeni, smrad se diže od trupla mnogih, krv gorama proteče,');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (29, 34, 4, 'raspade se sva vojska nebeska. Nebesa se sviše kao knjiga i pada sva njihova vojska k\'o što lozov list otpada, k\'o što se trusi lišće smokovo.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (29, 34, 5, 'Jer na nebu je opijeni mač moj: gle, na Edom on se obara da kazni narod što ga prokleh.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (29, 34, 6, 'Mač Jahvin krvlju je opijen, omašćen pretilinom, krvlju janjećom i jarećom, pretilinom bubrega ovnujskih. Jer Jahvi se u Bosri žrtva prinosi, veliko klanje u zemlji edomskoj.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (29, 34, 7, 'S njima će biti poklani bivoli i junad s bikovima. Zemlja će se njihovom napojiti krvlju, i prašina njihova omastit\' pretilinom,');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (29, 34, 8, 'jer Jahvi je ovo dan odmazde, godina naplate da Sion osveti.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (29, 34, 9, 'Potoci se njegovi obrću u smolu, prašina njegova u sumpor, i zemlja će mu postat smola goreća.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (29, 34, 10, 'Ni noću ni danju ugasit\' se neće, dim će joj se dizati dovijeka, iz koljena u koljeno pusta će ostati, za vjekove vjekova nitko neće prolaziti njome.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (29, 34, 11, 'Zaposjest će je jež i čaplja, sova i gavran prebivat će u njoj. Rastegnut će nad njom uže pustoši i visak praznine.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (29, 34, 12, 'Ondje će se nastaniti jarci, neće biti više plemića njezinih, ondje se više neće proglašavat\' kraljevi, svi će joj knezovi biti uništeni.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (29, 34, 13, 'Nići će trnje u njenim dvorcima, u tvrđavama kopriva i stričak, ona će biti jazbina čagljima, ležaj nojevima.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (29, 34, 14, 'Ondje će se sretat divlje mačke s hijenama, jarci će dozivati jedan drugoga; ondje će se odmarati Lilit našav počivalište.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (29, 34, 15, 'Ondje će se gnijezditi guja, odlagati jaja, ležat\' na njima, u sjeni ih tvojoj izleći; onamo će slijetati jastrebovi jedan za drugim.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (29, 34, 16, 'Istražujte u knjizi Jahvinoj i čitajte, nijedno od tog ne izosta, jer usta njegova tako narediše i duh njegov njih sakupi.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (29, 34, 17, 'Jer on im je ždrijeb bacio i ruka im njegova užetom zemlju odmjeri: dovijeka će je oni posjedovati, od koljena do koljena nju će obitavati.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (29, 35, 1, 'Nek\' se uzraduje pustinja, zemlja sasušena, neka kliče stepa, nek\' ljiljan procvjeta.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (29, 35, 2, 'Nek\' bujno cvatom cvate, da, neka od veselja kliče i nek\' se raduje. Dana joj je slava Libanona, divota Karmela i Šarona; oni će vidjeti slavu Jahvinu, divotu Boga našega.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (29, 35, 3, 'Ukrijepite ruke klonule, učvrstite koljena klecava!');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (29, 35, 4, 'Recite preplašenim srcima: \"Budite jaki, ne bojte se! Evo Boga vašega, odmazda dolazi, Božja naplata, on sam hita da nas spasi!\"');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (29, 35, 5, 'Sljepačke će oči progledati, uši će se gluhih otvoriti,');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (29, 35, 6, 'tad će hromi skakati k\'o jelen, njemakov će jezik klicati. Jer će u pustinji provreti voda, i u stepi potoci,');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (29, 35, 7, 'sažgana će zemlja postat\' jezero, a tlo žedno - izvori. U brlozima gdje ležahu čaglji izrast će rogoz i trska.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (29, 35, 8, 'Bit će ondje čista cesta, a zvat će se Sveti put: nitko nečist njime neće proći, bezumnici njime neće lutati.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (29, 35, 9, 'Ondje neće više biti lÓava, nit\' će onud zvijer prolaziti, već će hodit\' samo otkupljeni,');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (29, 35, 10, 'vraćati se otkupljenici Jahvini. Doći će u Sion kličuć\' od radosti, s veseljem vječnim na čelima; pratit će ih radost i veselje, pobjeći će bol i jauci.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (29, 36, 1, 'Četrnaeste godine Ezekijina kraljevanja asirski kralj Sanherib napade sve utvrđene judejske gradove i osvoji ih.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (29, 36, 2, 'Tada pošalje asirski kralj iz Lakiša u Jeruzalem kralju Ezekiji velikoga peharnika s jakom vojskom. On stade kod vodovoda Gornjeg ribnjaka, na putu u Valjarevo polje.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (29, 36, 3, 'K njemu iziđe upravitelj dvora Elijakim, sin Hilkijin, pisar Šebna i savjetnik Joah, sin Asafov.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (29, 36, 4, 'Veliki im peharnik reče: \"Kažite Ezekiji: Ovako govori veliki kralj, kralj asirski: \'Kakvo je to uzdanje u koje se uzdaš?');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (29, 36, 5, 'Misliš li da su prazne riječi već i savjet i snaga za rat? U koga se uzdaš da si se pobunio protiv mene?');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (29, 36, 6, 'Eto, oslanjaš se na Egipat, na slomljenu trsku koja prodire i probada dlan onomu tko se na nju nasloni. Takav je faraon, kralj egipatski, svima koji se uzdaju u njega.\'');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (29, 36, 7, 'Možda ćete mi odgovoriti: \'Uzdamo se u Jahvu, Boga svojega.\' Ali nije li njemu Ezekija uklonio uzvišice i žrtvenike i zapovjedio Judejcima i Jeruzalemu: \'Samo se pred ovim žrtvenikom klanjajte!\'');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (29, 36, 8, 'Hajde, okladi se s mojim gospodarom, kraljem asirskim: dat ću ti dvije tisuće konja ako mogneš naći jahače za njih.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (29, 36, 9, 'Kako ćeš onda odoljeti jednome jedinom od najmanjih slugu moga gospodara? Ali ti se uzdaš u Egipat da će ti dati kola i konjanike!');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (29, 36, 10, 'Naposljetku, zar sam ja mimo volju Jahvinu krenuo protiv ove zemlje da je razorim? Sam mi je Jahve rekao: \'Idi na tu zemlju i razori je!\'\"');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (29, 36, 11, 'Elijakim, Šebna i Joah rekoše velikom peharniku: \"Molimo te, govori svojim slugama aramejski, jer mi razumijemo; ne govori s nama judejski da čuje narod koji je na zidinama.\"');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (29, 36, 12, 'Ali im veliki peharnik odgovori: \"Zar me moj gospodar poslao da ovo kažem tvojem gospodaru i tebi, a ne upravo onim ljudima koji sjede na zidinama, osuđeni da s vama jedu svoju nečist i piju svoju mokraću?\"');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (29, 36, 13, 'Tada se veliki peharnik uspravi i u sav glas povika na judejskom ove riječi: \"Čujte riječ velikoga kralja, kralja asirskoga!');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (29, 36, 14, 'Ovako veli kralj: \'Neka vas Ezekija ne zavarava, jer vas ne može izbaviti iz moje ruke.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (29, 36, 15, 'Neka vas Ezekija ne hrabri pouzdanjem u Jahvu govoreći: Jahve će nas sigurno izbaviti: ovaj grad neće pasti u ruke kralju asirskom.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (29, 36, 16, 'Ne slušajte Ezekije, jer ovako veli asirski kralj: Sklopite mir sa mnom, predajte mi se, pa neka svaki od vas jede plodove iz svoga vinograda i sa svoje smokve i neka pije vode iz svojega studenca');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (29, 36, 17, 'dok ne dođem i ne odvedem vas u zemlju kao što je vaša, u zemlju pšenice i mošta, u zemlju kruha i vinograda.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (29, 36, 18, 'Ne dajte da vas Ezekija zaludi govoreći vam: Jahve će vas izbaviti. Jesu li bogovi drugih naroda izbavili svoje zemlje iz ruku asirskoga kralja?');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (29, 36, 19, 'Gdje su bogovi hamatski i arpadski, gdje su bogovi sefarvajimski, gdje su bogovi samarijski da izbave Samariju iz moje ruke?');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (29, 36, 20, 'Koji su među svim bogovima tih zemalja izbavili svoju zemlju iz moje ruke, da bi Jahve izbavio Jeruzalem iz ruke moje?\'\"');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (29, 36, 21, 'Šutjeli su i ni riječi mu nisu odgovorili, jer kralj bijaše zapovjedio: \"Ne odgovarajte mu!\"');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (29, 36, 22, 'Upravitelj dvora Elijakim, sin Hilkijin, pisar Šebna i savjetnik Joah, sin Asafov, dođoše k Ezekiji, razdrijevši haljine, i saopćiše mu riječi velikoga peharnika.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (29, 37, 1, 'Čuvši to, kralj Ezekija razdrije svoje haljine, obuče kostrijet i ode u Dom Jahvin.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (29, 37, 2, 'Zatim posla Elijakima, upravitelja dvora, kraljevskog pisara Šebnu i svećeničke starješine, odjevene u kostrijet, k proroku Izaiji, sinu Amosovu.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (29, 37, 3, 'Oni mu rekoše: \"Ovako veli Ezekija: \'Ovo je dan nevolje, kazne i rugla: prispješe djeca do porođaja, a nema snage da se rode.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (29, 37, 4, 'Možda je Jahve, Bog tvoj, čuo riječi velikog peharnika koga je kralj asirski, gospodar njegov, poslao da se izruguje Bogu živome, i možda će Jahve, Bog tvoj, kazniti riječi koje je čuo! Pomoli se pobožno za Ostatak koji je još preostao!\'\"');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (29, 37, 5, 'Kad su sluge kralja Ezekije stigle k Izaiji,');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (29, 37, 6, 'on im reče: \"Kažite svome gospodaru: \'Ovako veli Jahve: Ne boj se riječi koje si čuo kada su na me hulile sluge kralja asirskoga.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (29, 37, 7, 'Udahnut ću u njega duh, i kad čuje jednu vijest, vratit će se u svoju zemlju. I učinit ću da u svojoj zemlji pogine od mača.\'\"');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (29, 37, 8, 'Veliki peharnik vrati se i nađe asirskoga kralja gdje opsjeda Libnu, jer bijaše čuo da je kralj otišao iz Lakiša.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (29, 37, 9, 'Dočuo je, naime, da je Tirhaka, etiopski kralj, zavojštio na njega. Tada Sanherib ponovo uputi poslanike da kažu Ezekiji:');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (29, 37, 10, '\"Ovako recite judejskom kralju Ezekiji: \'Neka te ne vara tvoj Bog, u koga se uzdaš, govoreći ti: Jeruzalem neće pasti u ruke asirskog kralja.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (29, 37, 11, 'Ti znaš što su kraljevi asirski učinili svim zemljama izručivši ih prokletstvu! A ti, ti li ćeš se spasiti?');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (29, 37, 12, 'Jesu li bogovi spasili narode koje su uništili moji oci: Gozance, Harance, Resefce i Edence, u Tel Basaru?');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (29, 37, 13, 'Gdje je kralj hamatski, kralj arpadski, kralj Sefarvajima, Hene i Ive?\'\"');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (29, 37, 14, 'Ezekija primi pismo iz ruke poslanikove i pročita ga. Zatim uđe u Dom Jahvin i razvi ga ondje pred Jahvom.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (29, 37, 15, 'I pomoli se Ezekija Jahvi ovako:');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (29, 37, 16, '\"Jahve nad Vojskama, Bože Izraelov, koji stoluješ nad kerubima, ti si Bog jedini nad svim kraljevstvima na zemlji, ti si stvorio nebo i zemlju.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (29, 37, 17, 'Prikloni uho, Jahve, i počuj! Otvori oči, Jahve, i vidi! Sanheribove čujder riječi koje poruči da izruga Boga živoga.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (29, 37, 18, 'Istina je, o Jahve, asirski su kraljevi zatrli sve narode i zemlje njihove;');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (29, 37, 19, 'pobacali im u oganj bogove, jer ne bijahu bogovi to, već djela ruku ljudskih, od drva i kamena; zato ih i uništiše.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (29, 37, 20, 'Ali sada, Jahve, Bože naš, izbavi nas iz ruke njegove, da spoznaju sva kraljevstva zemlje da si ti, Jahve, Bog jedini!\"');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (29, 37, 21, 'Tad Izaija, sin Amosov, poruči Ezekiji: \"Ovako veli Jahve, Bog Izraelov: \'Uslišah molitvu koju mi uputi zbog Sanheriba, kralja asirskoga.\'');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (29, 37, 22, 'Evo riječi što je Jahve objavi protiv njega: Prezire te, ruga ti se, djevica, Kći sionska; za tobom maše glavom kći jeruzalemska.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (29, 37, 23, 'Koga si grdio, hulio? Na koga si glasno vikao, ohol pogled dizao? Na Sveca Izraelova!');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (29, 37, 24, 'Po slugama si svojim vrijeđao Gospoda. Govorio si: s mnoštvom kola ja popeh se na vrh gorÄa, na najviše vrhunce Libanona. Posjekoh mu ja cedre najviše i čemprese ponajljepše. Dosegoh mu vrh najviši, i vrt njegov šumoviti.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (29, 37, 25, 'Kopao sam i pio sam vode tuđe; stopalima tad isuših sve rijeke egipatske.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (29, 37, 26, 'Čuješ li dobro? Odavna to sam snovao, odiskona smišljao, sada to ostvarujem: na tebi je da prometneš gradove tvrde u razvaline;');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (29, 37, 27, 'stanovnici njini, nemoćni, prepadnuti i smeteni, bjehu kao trava u polju kao mlado zelenilo, kao trava vrh krovova opaljena vjetrom istočnim.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (29, 37, 28, 'Znam kad se dižeš i kad sjedaš, kad izlaziš i kad se vraćaš.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (29, 37, 29, 'Jer bjesnio si na me i jer obijest tvoja do ušiju mi dođe, prsten ću ti provući kroz nozdrve, uzde stavit\' u žvale, vratit ću te putem kojim si došao!');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (29, 37, 30, 'A znak nek\' ti bude ovo: ove će se godine jesti što se samo okrÄunÄi, dogodine što samo uzraste, a treće godine sijte i žanjite, sadite vinograde, jedite im rod.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (29, 37, 31, 'Preživjeli iz kuće Judine, žilje će pustit\' u dubinu, plodom rodit\' u visinu.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (29, 37, 32, 'Jer će iz Jeruzalema izaći Ostatak. Sačuvani s gore Siona. Sve će to učinit\' ljubomora Jahve nad Vojskama.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (29, 37, 33, 'Zato ovo govori Jahve o kralju asirskom: U ovaj grad on ući neće, ovamo strijele svoje neće izmetati, k njemu neće ni štit okrenuti, niti oko njega nasipe kopati.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (29, 37, 34, 'Vratit će se putem kojim je i došao, u grad ovaj neće ući - riječ je Jahvina.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (29, 37, 35, 'Grad ću ovaj štitit, zakriliti ga, sebe radi i rad sluge svoga Davida.\"');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (29, 37, 36, 'Tad iziđe Anđeo Jahvin i pobi u asirskom taboru sto osamdeset i pet tisuća ljudi. Ujutru, kad je valjalo ustati, gle, bijahu ondje sve sami mrtvaci.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (29, 37, 37, 'Sanherib podiže tabor i ode. Vratio se u Ninivu.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (29, 37, 38, 'Jednoga dana, dok se klanjao u hramu svoga boga Nimroka, njegovi ga sinovi Adramelek i Sareser ubiše mačem i pobjegoše u zemlju araratsku. Na njegovo se mjesto zakralji sin mu Asar-Hadon.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (29, 38, 1, 'U ono se vrijeme Ezekija razbolje nasmrt. Prorok Izaija, sin Amosov, dođe mu i reče: \"Ovako veli Jahve: \'Uredi kuću svoju, jer ćeš umrijeti, nećeš ozdraviti.\'\"');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (29, 38, 2, 'Ezekija se okrenu zidu i ovako se pomoli Jahvi:');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (29, 38, 3, '\"Ah, Jahve, sjeti se da sam pred tobom hodio vjerno i poštena srca i učinio što je dobro u tvojim očima.\" I Ezekija briznu u gorak plač.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (29, 38, 4, 'Tada dođe riječ Jahvina Izaiji:');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (29, 38, 5, '\"Idi i reci Ezekiji: Ovako kaže Jahve, Bog oca tvoga Davida: \'Uslišao sam tvoju molitvu, vidio tvoje suze. Izliječit ću te; za tri dana uzići ćeš u Dom Jahvin. Dodat ću tvome vijeku petnaest godina.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (29, 38, 6, 'Izbavit ću tebe i ovaj grad iz ruku asirskoga kralja. Jest, zakrilit ću ovaj grad!\'\"');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (29, 38, 7, 'Izaija odgovori: \"Evo ti znaka od Jahve da će učiniti što je rekao:');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (29, 38, 8, 'sjenu koja je sišla po stupnjevima Ahazova sunčanika vratit ću za deset stupnjeva natrag.\" I vrati se sunce deset stupnjeva natrag po stupnjevima po kojima bijaše već sišlo.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (29, 38, 9, 'Pjesan Ezekije, kralja judejskoga, kada se razbolio pa ozdravio od svoje bolesti:');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (29, 38, 10, '\"Govorio sam: U podne dana svojih ja moram otići. Na vratima Podzemlja mjesto mi je dano za ostatak mojih ljeta.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (29, 38, 11, 'Govorio sam: Vidjet više neću Jahve na zemlji živih, vidjet više neću nikoga od stanovnika ovog svijeta.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (29, 38, 12, 'Stan je moj razvrgnut, bačen daleko, kao šator pastirski; poput tkalca moj si život namotao da bi me otkinuo od osnove. Od jutra do noći skončat ćeš me,');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (29, 38, 13, 'vičem sve do jutra; kao što lav mrska kosti moje, od jutra do noći skončat ćeš me.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (29, 38, 14, 'Poput laste ja pijučem, zapomažem kao golubica, uzgor mi se okreću oči, zauzmi se, jamči za me.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (29, 38, 15, 'Kako ću mu govoriti i što ću mu reći? TÓa on je koji djeluje. Slavit ću te sva ljeta svoja, premda s gorčinom u duši.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (29, 38, 16, 'Gospodine, za tebe živjet će srce moje i živjet će moj duh. Ti ćeš me izliječiti i vratiti mi život,');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (29, 38, 17, 'bolest će mi se pretvorit\' u zdravlje. Ti si spasio dušu moju od jame uništenja, za leđa si bacio sve moje grijehe.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (29, 38, 18, 'Jer Podzemlje ne slavi te, ne hvali te Smrt; oni koji padnu u rupu u tvoju se vjernost više ne uzdaju.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (29, 38, 19, 'Živi, živi, jedino on te slavi kao ja danas. Otac naučava sinovima tvoju vjernost.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (29, 38, 20, 'U pomoć mi, Jahve priteci, i mi ćemo pjevati uz harfe sve dane svojega života pred Hramom Jahvinim.\"');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (29, 38, 21, 'Izaija naloži: \"Donesite oblog od smokava, privijte mu ga na čir i on će ozdraviti.\"');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (29, 38, 22, 'Ezekija upita: \"Po kojem ću znaku prepoznati da ću uzići u Dom Jahvin?\"');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (29, 39, 1, 'U to vrijeme posla babilonski kralj Merodak Baladan, sin Baladanov, pisma s darom Ezekiji, jer bijaše čuo da se razbolio i ozdravio.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (29, 39, 2, 'Ezekija se obradova tome i pokaza poslanicima svoju riznicu - srebro, zlato, miomirise i mirisavo ulje - svoju oružanu i sve što je bilo u skladištima. Nije bilo ničega u njegovu dvoru i u svemu njegovu gospodarstvu što im Ezekija nije pokazao.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (29, 39, 3, 'Tada prorok Izaija dođe kralju Ezekiji i upita ga: \"Što su rekli ti ljudi i odakle su došli k tebi?\" Ezekija odgovori: \"Došli su iz daleke zemlje, iz Babilona.\"');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (29, 39, 4, 'Izaija upita dalje: \"Što su vidjeli u tvojem dvoru?\" Ezekija odgovori: \"Vidjeli su sve što je u mojem dvoru; nema u mojim skladištima ničega što im nisam pokazao.\"');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (29, 39, 5, 'Tad Izaija reče Ezekiji: \"Čuj riječ Jahve nad Vojskama:');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (29, 39, 6, '\'Evo dolaze dani kada će sve što je u tvojem dvoru, sve što su tvoji oci nakupili do danas, biti odneseno u Babilon. Ništa neće ostati,\' kaže Jahve.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (29, 39, 7, '\'A od sinova koji poteku od tebe, koji ti se rode, neke će uzeti da budu uškopljeni dvorani babilonskoga kralja.\'\"');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (29, 39, 8, 'Ezekija odgovori Izaiji: \"Povoljna je riječ koju ti je Jahve objavio.\" A mislio je: \"Bit će barem mira i sigurnosti za moga života.\"');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (29, 40, 1, '\"Tješite, tješite moj narod, govori Bog vaš.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (29, 40, 2, 'Govorite srcu Jeruzalema, vičite mu da mu se ropstvo okonča, da mu je krivnja okajana, jer iz Jahvine ruke primi dvostruko za sve grijehe svoje.\"');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (29, 40, 3, 'Glas viče: \"Pripravite Jahvi put kroz pustinju. Poravnajte u stepi stazu Bogu našemu.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (29, 40, 4, 'Nek\' se povisi svaka dolina, nek\' se spusti svaka gora i brežuljak. Što je neravno, nek\' se poravna, strmine nek\' postanu ravni.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (29, 40, 5, 'Otkrit će se tada Slava Jahvina i svako će je tijelo vidjeti, jer Jahvina su usta govorila.\"');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (29, 40, 6, 'Glas nalaže: \"Viči!\" Odgovorih: \"Što da vičem?\" - \"Svako je tijelo k\'o trava, k\'o cvijet poljski sva mu dražest.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (29, 40, 7, 'Sahne trava, vene cvijet, kad dah Jahvin preko njih prođe. Doista, narod je trava.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (29, 40, 8, 'Sahne trava, vene cvijet, ali riječ Boga našeg ostaje dovijeka.\"');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (29, 40, 9, 'Na visoku se uspni goru, glasniče radosne vijesti, Sione! Podigni snažno svoj glas, glasniče radosne vijesti, Jeruzaleme! Podigni ga, ne boj se, reci judejskim gradovima: \"Evo Boga vašega!\"');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (29, 40, 10, 'Gle, Gospod Jahve dolazi u moći, mišicom svojom vlada! Evo s njim naplata njegova, a ispred njega njegova nagrada.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (29, 40, 11, 'Kao pastir pase stado svoje, u ruke uzima jaganjce, nosi ih u svome naručju i brižljivo njeguje dojilice.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (29, 40, 12, 'Tko je šakom izmjerio more i nebesa premjerio pedljem? Tko je mjericom izmjerio zemlju i planine na mjerila, a tezuljom bregove?');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (29, 40, 13, 'Tko je pokrenuo duh Jahvin, koji ga je uputio savjetnik?');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (29, 40, 14, 'S kim se on posvjetova, tko je njemu mudrost ulio, naučio ga putovima pravde? Tko li ga je naučio znanju, pokazao mu put k umnosti?');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (29, 40, 15, 'Gle, narodi su kao kap iz vjedra, vrijede kao prah na tezulji. Otoci, gle, lebde poput truna!');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (29, 40, 16, 'Libanon je malen za lomaču, a zvijeri njegovih nema dosta za paljenicu.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (29, 40, 17, 'Svi narodi k\'o ništa su pred njim, ništavilo su njemu i praznina.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (29, 40, 18, 'S kime ćete prispodobit\' Boga? I s kakvim ga likom usporedit\'?');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (29, 40, 19, 'Ljevač lijeva idol, zlatar ga pozlaćuje i lijeva od srebra lančiće.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (29, 40, 20, 'Siromah za prinos bira drvo koje ne trune; i vješta traži umjetnika. da mu načini kip nepomičan.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (29, 40, 21, 'Zar ne znate? Zar niste čuli? Nije li vam odiskona otkriveno? Zar niste shvatili tko zasnova zemlju?');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (29, 40, 22, 'On stoluje vrh kruga zemaljskoga kom su stanovnici poput skakavaca. Kao zastor nebesa je razastro, kao šator za stan razapeo.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (29, 40, 23, 'On obraća u ništa knezove, uništava suce zemaljske.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (29, 40, 24, 'Tek što su zasađeni, tek što su posijani, tek što im stabljika u zemlju korijen pruži, on puhne na njih i oni posahnu, vihor ih k\'o pljevu raznese.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (29, 40, 25, '\"S kime ćete mene prispodobit\', tko mi je ravan?\" - kaže Svetac.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (29, 40, 26, 'Podignite oči i gledajte: tko je to stvorio? Onaj koji na broj izvodi vojsku njihovu i koji ih sve zove po imenu.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (29, 40, 27, 'Zašto kažeš, Jakove, i ti, Izraele, govoriš: \"Moj put sakriven je Jahvi, Bogu mom izmiče moja pravica?\"');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (29, 40, 28, 'Zar ne znaš? Zar nisi čuo? Jahve je Bog vječni, krajeva zemaljskih stvoritelj. On se ne umara, ne sustaje, i um je njegov neizmjerljiv.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (29, 40, 29, 'Umornome snagu vraća, jača nemoćnoga.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (29, 40, 30, 'Mladići se more i malakšu, iznemogli, momci posrću.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (29, 40, 31, 'Al\' onima što se u Jahvu uzdaju snaga se obnavlja, krila im rastu kao orlovima, trče i ne sustaju, hode i ne more se.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (29, 41, 1, 'Umuknite preda mnom, otoci, nek\' novu snagu narodi priberu. Nek\' se primaknu i progovore; zajedno pristupimo k sudu.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (29, 41, 2, '\"Tko je podigao s Istoka onog kog ukorak prati Pobjeda? Tko mu izručuje narode i kraljeve podlaže? Prah su pod mačem njegovim, k\'o pljevu ih njegov luk raspršuje.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (29, 41, 3, 'Goni ih, napreduje pouzdano, noge mu se ceste ne dotiču.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (29, 41, 4, 'Tko je to učinio i izvršio? Onaj koji odiskona zove naraštaje, ja, Jahve, koji sam prvi i bit ću ovaj isti s posljednjima!\"');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (29, 41, 5, 'Otoci gledaju i strah ih obuzima, dršću krajevi zemaljski, oni se bliže i već su tu.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (29, 41, 6, 'Svatko pomaže svome drugu i bratu svom zbori: \"Hrabro!\"');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (29, 41, 7, 'Ljevač bodri zlatara, onaj koji gladi čekićem bodri onog koji kuje na nakovnju. On govori o spajanju: \"Dobro je\", i čavlima kip učvršćuje da se ne pomiče.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (29, 41, 8, 'Ti, Izraele, slugo moja, Jakove, kog sam izabrao, potomče Abrahama, mojega ljubimca!');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (29, 41, 9, 'Ti koga uzeh s krajeva zemlje i pozvah s rubova njenih, ti kome rekoh: \"Ti si sluga moj, izabrao sam te i nisam te odbacio.\"');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (29, 41, 10, 'Ne boj se jer ja sam s tobom; ne obaziri se plaho jer ja sam Bog tvoj. Ja te krijepim i pomažem ti, podupirem te pobjedničkom desnicom.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (29, 41, 11, 'Gle, postidjet će se i smesti svi koji su na tebe bjesnjeli, bit će uništeni i propast će oni što se s tobom parbiše!');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (29, 41, 12, 'Tražit ćeš svoje protivnike, ali ih nećeš naći. Bit će uništeni, svedeni na ništa oni koji protiv tebe vojuju.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (29, 41, 13, 'Jer ja, Jahve, Bog tvoj, krijepim desnicu tvoju i kažem ti: \"Ne boj se, ja ti pomažem.\"');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (29, 41, 14, 'Ne boj se, Jakove, crviću, Izraele, ličinko, ja sam pomoć tvoja - riječ je Jahvina - Svetac Izraelov tvoj je otkupitelj.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (29, 41, 15, 'Gle, činim te mlatilom oštrim, novim, dvostrukih zubaca; mlatit ćeš i satirati brda, u prah ćeš pretvoriti bregove.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (29, 41, 16, 'Vijat ćeš ih, vjetar će ih odnijeti, vihor će ih raspršiti. A ti ćeš kliktati u Jahvi, dičit ćeš se Svecem Izraelovim.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (29, 41, 17, 'Ubogi i bijedni vodu traže, a nje nema! Jezik im se osuši od žeđi. Ja, Jahve, njih ću uslišiti, ja, Bog Izraelov, ostavit\' ih neću.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (29, 41, 18, 'U goleti bregova otvorit ću rijeke i posred dolova izvore. Pustinju ću pretvoriti u močvaru, a u vrela sušnu zemlju.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (29, 41, 19, 'Posadit ću u pustinji cedar, bagrem, mirtu i maslinu. Stepu ću pošumiti čempresom, brijestom i šimširom zajedno.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (29, 41, 20, 'Nek\' svi vide i nek\' znaju, nek\' promisle i nek\' shvate: ruka Jahvina to učini, Svetac Izraelov stvori sve.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (29, 41, 21, '\"Iznesite svoj spor, kaže Jahve, predočite dokaze, kaže kralj Jakovljev.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (29, 41, 22, 'Nek\' pristupe i nek\' nam objave ono što će se zbiti. TÓa što su nam otkrili o onom što bijaše, što se ispunilo, da o tom mislimo? Il\' objavite što će biti, da doznamo ono što dolazi.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (29, 41, 23, 'Otkrijte nam što će se poslije zbiti, i poznat ćemo da ste bogovi. Učinite nešto, dobro ili zlo, da se začudimo i prepadnemo zajedno.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (29, 41, 24, 'Ali vi niste ništa i djela su vam ništavna, gnusan je koji vas izabere.\"');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (29, 41, 25, 'Podigoh ga sa sjevera da dođe, zazvah ga po imenu s istoka. Kao blato gazio je namjesnike, kao što po glini lončar gazi.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (29, 41, 26, 'Tko je to odiskona objavio da bismo znali, unaprijed prorekao da bismo rekli: istina je? Ali nikog nema tko bi objavio, niti koga da bi navijestio, niti koga da čuje riječi vaše.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (29, 41, 27, 'Ja prvi rekoh Sionu: \"Gle, evo ih\"; prvi Jeruzalemu poslah glasnika vijesti radosne.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (29, 41, 28, 'Gledao sam, ali ne bješe nikoga, ni jednoga od njih da savjet dade, da ih pitam i da odgovore.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (29, 41, 29, 'Svi zajedno ništa su, ništavna su djela njihova, vjetar i ispraznost njihovi kipovi.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (29, 42, 1, 'Evo Sluge mojega koga podupirem, mog izabranika, miljenika duše moje. Na njega sam svoga duha izlio da donosi pravo narodima.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (29, 42, 2, 'On ne viče, on ne diže glasa, niti se čuti može po ulicama.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (29, 42, 3, 'On ne lomi napuknutu trsku niti gasi stijenj što tinja. Vjerno on donosi pravdu,');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (29, 42, 4, 'ne sustaje i ne malakše dok na zemlji ne uspostavi pravo. Otoci žude za njegovim naukom.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (29, 42, 5, 'Ovako govori Jahve, Bog, koji stvori i razastrije nebesa, koji rasprostrije zemlju i njeno raslinje, koji dade dah narodima na njoj i dah bićima što njome hode.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (29, 42, 6, 'Ja, Jahve, u pravdi te pozvah, čvrsto te za ruku uzeh; oblikovah te i postavih te za Savez narodu i svjetlost pucima,');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (29, 42, 7, 'da otvoriš oči slijepima, da izvedeš sužnje iz zatvora, iz tamnice one što žive u tami.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (29, 42, 8, 'Ja, Jahve mi je ime, svoje slave drugom ne dam, niti časti svoje kipovima.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (29, 42, 9, 'Što prije prorekoh, evo, zbi se, i nove događaje ja naviještam, i prije negoli se pokažu, vama ih objavljujem.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (29, 42, 10, 'Pjevajte Jahvi pjesmu novu, i s kraja zemlje hvalu njegovu, neka ga slavi more sa svim što je u njem, otoci i njihovi žitelji!');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (29, 42, 11, 'Nek\' digne glas pustinja i njeni gradovi, nek\' odjeknu naselja gdje žive Kedarci! Nek\' podvikuju stanovnici Stijene, neka kliču s gorskih vrhova!');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (29, 42, 12, 'Nek\' daju čast Jahvi i hvalu mu naviještaju po otocima!');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (29, 42, 13, 'Kao junak izlazi Jahve, kao ratnik žar svoj podjaruje. Uz bojni poklik i viku ratnu ide junački na svog neprijatelja.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (29, 42, 14, '\"Šutjeh dugo, gluh se činjah, svladavah se; sad vičem kao žena kada rađa, dašćem i uzdišem.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (29, 42, 15, 'Isušit ću brda i bregove, sparušiti svu zelen po njima, rijeke ću u stepe pretvoriti i močvare isušiti.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (29, 42, 16, 'Vodit ću slijepce po cestama, uputit\' ih putovima. Pred njima ću tamu u svjetlost obratit\', a neravno tlo u ravno. To ću učiniti i neću propustiti.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (29, 42, 17, 'Uzmaknut će u golemu stidu koji se uzdaju u kipove, koji ljevenim likovima govore: \'Vi ste naši bogovi.\'\"');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (29, 42, 18, 'Čujte, gluhi! Progledajte, slijepi, da vidite!');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (29, 42, 19, 'Tko je slijep ako ne moj sluga, tko je gluh kao glasnik koga šaljem? Tko je slijep kao prijatelj, tko je gluh kao sluga Jahvin?');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (29, 42, 20, 'Mnogo si vidio, ali nisi mario, uši ti bjehu otvorene, ali nisi čuo!');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (29, 42, 21, 'Jahvi se svidjelo zbog njegove pravednosti da uzveliča i proslavi Zakon svoj.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (29, 42, 22, 'A narod je ovaj opljačkan i oplijenjen, mladići mu stavljeni u klade, vrgnuti u zatvore. Plijene ih, a nikoga da ih izbavi; robe ih, a nitko da kaže: \"Vrati!\"');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (29, 42, 23, 'Tko od vas mari za to? Tko pazi i sluša unapredak?');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (29, 42, 24, 'Tko je pljačkašu izručio Jakova i otimačima Izraela? Nije li Jahve, protiv koga smo griješili, čijim putima ne htjedosmo hoditi, čiji Zakon nismo slušali?');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (29, 42, 25, 'Zato izli na Izraela žarki gnjev svoj i strahote ratne: plamen ga okruži odasvud, al\' on ni to nije shvatio; sažeže ga, al\' on ni to k srcu ne uze.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (29, 43, 1, 'Sada ovako govori Jahve, koji te stvorio, Jakove, koji te sazdao, Izraele: \"Ne boj se, jer ja sam te otkupio; imenom sam te zazvao: ti si moj!');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (29, 43, 2, 'Kad preko vode prelaziš, s tobom sam; ili preko rijeke, neće te preplaviti. Pođeš li kroz vatru, nećeš izgorjeti, plamen te opaliti neće.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (29, 43, 3, 'Jer ja sam Jahve, Bog tvoj, Svetac Izraelov, tvoj spasitelj. Za otkupninu tvoju dajem Egipat, mjesto tebe dajem Kuš i Šebu.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (29, 43, 4, 'Jer dragocjen si u mojim očima, vrijedan si i ja te ljubim. Stog i dajem ljude za tebe i narode za život tvoj.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (29, 43, 5, 'Ne boj se jer ja sam s tobom. S istoka ću ti dovest\' potomstvo i sabrat ću te sa zapada.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (29, 43, 6, 'Reći ću sjeveru: \'Daj mi ga!\' a jugu \'Ne zadržavaj ga!\' Sinove mi dovedi izdaleka i kćeri moje s kraja zemlje,');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (29, 43, 7, 'sve koji se mojim zovu imenom i koje sam na svoju slavu stvorio, koje sam sazdao i načinio.\"');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (29, 43, 8, 'Izvedi narod slijep, premda oči ima, i gluh, premda uši ima.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (29, 43, 9, 'Neka se saberu sva plemena i neka se skupe narodi. Tko je od njih to prorekao i davno navijestio? Nek\' dovedu svjedoke da se opravdaju, neka se čuje da se može reći: \"Istina je!\"');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (29, 43, 10, 'Jer vi ste mi svjedoci, riječ je Jahvina, i moje sluge koje sam izabrao, da biste znali i vjerovali i uvidjeli da sam to ja. Prije mene nijedan bog nije bio načinjen i neće poslije mene biti.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (29, 43, 11, 'Ja, ja sam Jahve, osim mene nema spasitelja.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (29, 43, 12, 'Ja sam prorekao, spasio i navijestio, i nema među vama tuđinca! Vi ste mi svjedoci, riječ je Jahvina, a ja sam Bog');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (29, 43, 13, 'od vječnosti - ja jesam! I nitko iz ruke moje ne izbavlja; što učinim, tko izmijeniti može?');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (29, 43, 14, 'Ovako govori Jahve, otkupitelj vaš, Svetac Izraelov: \"Radi vas poslah protiv Babilona, oborit ću prijevornice zatvorima i Kaldejci će udarit u kukanje.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (29, 43, 15, 'Ja sam Jahve, Svetac vaš, stvoritelj Izraelov, kralj vaš!\"');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (29, 43, 16, 'Ovako govori Jahve, koji put po moru načini i stazu po vodama silnim;');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (29, 43, 17, 'koji izvede bojna kola i konje, vojsku i junake, i oni padoše da više ne ustanu, zgasnuše, kao stijenj se utrnuše.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (29, 43, 18, 'Ne spominjite se onog što se zbilo, nit\' mislite na ono što je prošlo.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (29, 43, 19, 'Evo, činim nešto novo; već nastaje. Zar ne opažate? Da, put ću napraviti u pustinji, a staze u pustoši.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (29, 43, 20, 'Slavit će me divlje zvijeri, čaglji i nojevi, jer vodu ću stvorit\' u pustinji, rijeke u stepi, da napojim svoj narod, izabranika svoga.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (29, 43, 21, 'I narod koji sam sebi sazdao moju će kazivati hvalu!');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (29, 43, 22, 'Ali me ti, Jakove, nisi zazvao, niti si se zamorio oko mene, Izraele!');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (29, 43, 23, 'Nisi mi prinosio ovce za paljenicu, nisi me častio žrtvama. A ja te silio nisam na prinose, nisam ti dodijavao ištući kada.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (29, 43, 24, 'Nisi mi kupovao za novac trsku, nisi me sitio salom svojih žrtava; nego si me grijesima svojim mučio, bezakonjem svojim dosađivao mi.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (29, 43, 25, 'A ja, ja radi sebe opačine tvoje brišem i grijeha se tvojih ne spominjem.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (29, 43, 26, 'Podsjeti me, zajedno se sporimo, govori ti da se opravdaš.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (29, 43, 27, 'Prvi je otac tvoj sagriješio, posrednici tvoji od mene se odmetnuli,');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (29, 43, 28, 'knezovi su tvoji oskvrnuli Svetište. Tad izručih Jakova prokletstvu, i poruzi Izraela.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (29, 44, 1, 'Sad čuj, Jakove, slugo moj, Izraele, kog sam izabrao.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (29, 44, 2, 'Ovako kaže Jahve, koji te stvorio, koji te od utrobe sazdao i pomaže ti: \"Ne boj se, Jakove, slugo moja, Ješurune, kog sam izabrao.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (29, 44, 3, 'Jer na žednu ću zemlju vodu izliti i po tlu sušnome potoke. Izlit ću duh svoj na tvoje potomstvo i blagoslov na tvoja pokoljenja.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (29, 44, 4, 'Rast će kao trava pokraj izvora, kao vrbe uz vode tekućice.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (29, 44, 5, 'Jedan će reći: \'Ja sam Jahvin\', drugi će se zvati imenom Jakovljevim. Treći će sebi na ruci napisati: \'Jahvin\' i nazvat će se imenom Izraelovim.\"');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (29, 44, 6, 'Ovako govori kralj Izraelov i otkupitelj njegov, Jahve nad Vojskama: \"Ja sam prvi i ja sam posljednji: osim mene Boga nema.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (29, 44, 7, 'Tko je kao ja? Nek\' ustane i govori, nek\' navijesti i nek\' mi razloži! Tko je od vječnosti otkrio što se zbilo? Nek\' nam navijesti što će još doći!');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (29, 44, 8, 'Ne plašite se, ne bojte se: nisam li vam to odavna navijestio i otkrio? Vi ste mi svjedoci: ima li Boga osim mene? Ima li Stijene? Ja ne znam!\"');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (29, 44, 9, 'Tko god pravi kipove, ništavan je, i dragocjenosti njegove ne koriste ničemu. Svjedoci njihovi ništa ne vide i ništa ne znaju, da im budu na sramotu.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (29, 44, 10, 'Tko pravi boga i lijeva kip da od toga korist ne očekuje?');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (29, 44, 11, 'Gle, svi će štovatelji likova biti osramoćeni, izrađivači njihovi više od bilo koga. Nek\' se saberu svi i pojave: prepast će se i postidjeti odjednom.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (29, 44, 12, 'Kovač ga izrađuje na živu ugljevlju, čekićem ga oblikuje, snažnom ga rukom obrađuje. Gladan je i iznemogao; ne pije vode, iscrpljuje se.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (29, 44, 13, 'Drvodjelja uzima mjeru, pisaljkom lik ocrta, ostruže ga dlijetom, šestarom ga zaokruži i izdjelja ga po uzoru na lik ljudski, kao lijepo ljudsko obličje, da stoji u hramu.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (29, 44, 14, 'Bijaše sebi nasjekao cedre, uzeo čempres ili hrast koje je za se njegovao među šumskim drvećem; ili je posadio bor koji raste od kiše.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (29, 44, 15, 'Čovjeku su dobra za vatru; uzima ih da se ogrije; pali ih da ispeče kruh. Ali od njih djelja i boga pred kojim pada ničice, pravi kip i klanja mu se.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (29, 44, 16, 'Polovinom od toga naloži, dakle, oganj, peče meso na žeravi, jede pečenku i siti se: grije se i govori: \"Ah, grijem se i uživam uz vatru.\"');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (29, 44, 17, 'Ali od onoga što preostane pravi sebi boga, svog kumira, pada pred njim ničice i klanja mu se i moli: \"Spasi me, jer si ti moj bog.\"');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (29, 44, 18, 'Ne znaju oni i ne razumiju: zaslijepljene su im oči pa ne vide, i srce pa ne shvaćaju.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (29, 44, 19, 'Takav ne razmišlja, nema u njega znanja ni razbora da sebi kaže: \"Polovinom od ovoga naložio sam oganj, na žeravici ispekao kruh, ispržio meso koje sam pojeo, pa zar ću od ostatka načiniti gnusobu? Zar ću se komadu drveta klanjati?\"');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (29, 44, 20, 'On voli pepeo, zavodi ga prevareno srce. Neće spasti svog života i nikad neće reći: \"Nije li varka ovo u mojoj desnici?\"');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (29, 44, 21, 'Sjeti se toga, Jakove, i ti, Izraele, jer si sluga moj! Ja sam te stvorio i sluga si mi, Izraele, neću te zaboraviti!');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (29, 44, 22, 'Kao maglu rastjerao sam tvoje opačine i grijehe tvoje poput oblaka. Meni se obrati jer ja sam te otkupio.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (29, 44, 23, 'Kličite, nebesa, jer je Jahve učinio! Orite se, dubine zemljine! Odjekujte radošću, planine, i vi, šume, sa svim svojim drvećem! Jer Jahve je otkupio Jakova, proslavio se u Izraelu!');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (29, 44, 24, 'Ovako govori Jahve, otkupitelj tvoj i tvorac tvoj od utrobe: \"Ja sam Jahve koji sam sve stvorio, koji sam nebesa sam razapeo i učvrstio zemlju bez pomoći ičije.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (29, 44, 25, 'Ja osujećujem znamenja vrača, i čarobnjake u luđake promećem; silim mudrace da ustuknu i mudrost im obraćam u bezumlje,');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (29, 44, 26, 'ali potvrđujem riječ sluge svojega, ispunjam naum svojih glasnika. Ja govorim Jeruzalemu: \'Naseli se!\' I gradovima judejskim: \'Sagradite se!\' Iz razvalina ja ih podižem.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (29, 44, 27, 'Ja govorim moru: \'Presahni! Presušujem ti rijeke.\'');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (29, 44, 28, 'Ja govorim Kiru: \'Pastiru moj!\' I on će sve želje moje ispuniti govoreći Jeruzalemu: \'Sagradi se!\' i Hramu: \'Utemelji se!\'\"');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (29, 45, 1, 'Ovako govori Jahve o Kiru, pomazaniku svome: \"Primih ga za desnicu da pred njim oborim narode i raspašem bokove kraljevima, da rastvorim pred njim vratnice, da mu nijedna vrata ne budu zatvorena.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (29, 45, 2, 'Ja ću hoditi pred tobom da poravnam uzvisine, da razbijem mjedene vratnice, da slomim željezne prijevornice.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (29, 45, 3, 'Dajem ti tajna blaga i skrivena bogatstva, da bi spoznao da sam ja Jahve koji te zovem po imenu, Bog Izraelov.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (29, 45, 4, 'Radi sluge svog Jakova i Izraela, svog izabranika, po imenu ja te pozvah, imenovah te premda me znao nisi.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (29, 45, 5, 'Ja sam Jahve i nema drugoga; osim mene Boga nema. Iako me ne poznaš, naoružah te:');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (29, 45, 6, 'nek\' se znade od istoka do zapada da izvan mene sve je ništavilo.\" Ja sam Jahve i nema drugoga;');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (29, 45, 7, 'ja tvorim svjetlost i stvaram tamu. Ja stvaram sreću i dovodim nesreću, ja, Jahve, činim sve to.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (29, 45, 8, 'Rosite, nebesa, odozgo, i oblaci, daždite pravednošću. Neka se rastvori zemlja da procvjeta spasenje, da proklija izbavljenje! Ja, Jahve, stvaram sve.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (29, 45, 9, 'Jao onome tko raspravlja s tvorcem svojim, a sud je među glinenim sudovima! Kaže li glina lončaru: \"Što radiš?\" ili djelo njegovo: \"Kljast si!\"');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (29, 45, 10, 'Jao onom koji kaže ocu: \"Što si rodio?\" Ili ženi: \"Što si na svijet dala?\"');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (29, 45, 11, 'Ovako govori Jahve, Svetac Izraelov, njegov tvorac: \"Zar je vaše da me o mojoj djeci pitate i da mi nad djelom ruku mojih zapovijedate?');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (29, 45, 12, 'Ja sam načinio zemlju i čovjeka na njoj stvorio; svojim sam rukama razapeo nebesa i zapovijedam svim vojskama njihovim.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (29, 45, 13, 'Ja sam ga podigao da pobijedi i poravnao sam mu sve putove. On će obnoviti moj Grad i sužnje moje vratiti bez otkupnine i naknade.\" Tako kaže Jahve nad Vojskama.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (29, 45, 14, 'Ovako govori Jahve: \"Ratari Egipta i trgovci Kuša, i Sebejci, ljudi rasta visoka, prijeći će tebi i tvoji će biti; za tobom će ići okovani, tebi će se klanjati i molit će ti se: \'Jedino je kod tebe Bog, nema drugoga; ništavni su bogovi.\'\"');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (29, 45, 15, 'Doista ti si Bog skriveni, Bog Izraelov, Spasitelj.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (29, 45, 16, 'Postidjet će se i poniknut će svi zajedno, otići će u ruglu oni koji prave kipove.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (29, 45, 17, 'A Jahve će vječnim spasenjem spasit\' Izraela. Nećete se postidjeti i nećete poniknuti dovijeka.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (29, 45, 18, 'Da, ovako govori Jahve, nebesa Stvoritelj - on je Bog - koji je oblikovao i sazdao zemlju, koji ju je učvrstio i nije je stvorio pustu, već ju je uobličio za obitavanje: \"Ja sam Jahve i nema drugoga.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (29, 45, 19, 'Nisam govorio u tajnosti, u zakutku mračne zemlje. Nisam rekao potomstvu Jakovljevu: \'Tražite me u pustoši.\' Ja, Jahve, govorim pravo i naviještam čestito.\"');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (29, 45, 20, '\"Saberite se i dođite, pristupite zajedno, svi preživjeli od naroda! Neznalice puke oni su što nose kip izrađen od drveta i mole boga koji ih spasit\' ne može.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (29, 45, 21, 'Objavite, iznesite svoje dokaze, svjetujte se zajedno: tko je to od davnine navijestio i od tada prorekao? Nisam li ja, Jahve? Nema drugoga boga do mene; Boga pravednog i Spasitelja osim mene nema.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (29, 45, 22, 'Obratite se k meni da se spasite, svi krajevi zemlje, jer ja sam Bog i nema drugoga!');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (29, 45, 23, 'Sobom se samim kunem, iz mojih usta izlazi istina, riječ neopoziva, da će se preda mnom prignuti svako koljeno, mnome će se svaki jezik zaklinjati');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (29, 45, 24, 'govoreći: \'Jedino je u Jahvi pobjeda i snaga!\'\" K njemu će doći, postiđeni, svi što na nj su bjesnjeli.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (29, 45, 25, 'U Jahvi će pobijediti i proslavit se sve potomstvo Izraelovo!');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (29, 46, 1, 'Pade Bel! Sruši se Nebo! Prte svoje kipove na životinje i stoku, nose ih kao breme, teret što zamara.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (29, 46, 2, 'Padaju, ruše se svi zajedno, ne mogu spasiti one što ih nose, nego i sami u ropstvo odlaze.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (29, 46, 3, '\"Slušajte me, kućo Jakovljeva, i svi koji ostadoste od kuće Izraelove! Ja sam vas ponio tek što se rodiste, i nosio vas od krila materina.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (29, 46, 4, 'Do starosti vaše ja ću ostat\' isti, do vaših sjedina podupirat ću vas. To sam činio; nosit ću vas i dalje, pomagati vas, izbavljati.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (29, 46, 5, 'S kime biste me usporedili i izjednačili, s kime prispodobili: komu da sam sličan?');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (29, 46, 6, 'Vade zlato iz kese i tezuljom mjere srebro, pa naimlju zlatara da od njeg boga načini te pred njim padaju ničice i klanjaju se.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (29, 46, 7, 'Dižu ga na rame i nose ga, onda ga stavljaju na njegovo mjesto; on stoji i ne miče se s njega. Prizivaju li ga, on ne odgovara i nikog ne spasava od nevolje njegove.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (29, 46, 8, 'Sjetite se toga i budite ljudi, uzmite to k srcu, otpadnici,');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (29, 46, 9, 'sjetite se prošlosti pradavne: ja sam Bog i nema drugoga; Bog, nitko mi sličan nije!');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (29, 46, 10, 'Onaj sam koji od početka svršetak otkriva i unaprijed javlja što još se nije zbilo! Ja kažem: Odluka će se moja ispuniti, izvršit ću sve što mi je po volji.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (29, 46, 11, 'S istoka zovem grabljivicu, iz daleke zemlje zovem čovjeka svog nauma. Rekao sam - ispunit ću, naumio sam - izvršit ću.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (29, 46, 12, 'Slušajte me, vi koji gubite srčanost i koji ste daleko od pobjede.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (29, 46, 13, 'Primičem svoju pobjedu, nije više daleko, spasenje moje zakasniti neće. Na Sion ću spas staviti, u Izraela svoju slavu.\"');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (29, 47, 1, 'Spusti se, sjedni u prašinu, djevice, kćeri babilonska! Sjedni na zemlju, bez prijestolja, kćeri kaldejska! Jer, neće te više zvati nježnom i tankoćutnom.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (29, 47, 2, 'Uzmi mlin i melji brašno! Skini prijevjes, podigni skut, razgali bedra, prijeđi preko rijeke!');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (29, 47, 3, 'Nek\' se golotinja tvoja otkrije, nek\' se sramota tvoja pokaže! Ja ću se osvetiti, odvraćat\' me nitko neće.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (29, 47, 4, 'Otkupitelj naš, ime mu je Jahve nad Vojskama, Svetac Izraelov, kaže:');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (29, 47, 5, '\"Sjedi šutke, u mrak se povuci, kćeri kaldejska. Jer, neće te više zvati vladaricom kraljevstava.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (29, 47, 6, 'Razgnjevih se na svoj narod, oskvrnuh svoju baštinu. Tebi ih u ruke izručih, a ti im ne iskaza milosti. Na starce si stavljala jaram svoj preteški.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (29, 47, 7, 'Govorila si: \'Dovijeka gospodaricom ću ostati.\' Nikad nisi to k srcu uzela ni pomislila kako će se završiti.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (29, 47, 8, 'A sad poslušaj, razvratnice, koja sjediš bezbrižno i u srcu svom govoriš: \'Ja, i nitko drugi! Nikad neću obudovjeti, neću djece izgubiti!\'');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (29, 47, 9, 'Stići će te oboje, za tren, u isti dan! Izgubit ćeš djecu, obudovjet ćeš! Punom će te mjerom snaći oboje, pokraj svega tvojeg vračanja i množine tvojih zaklinjanja!');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (29, 47, 10, 'U zloću si se svoju uzdala, govorila si: \'Nitko me ne vidi!\' Mudrost tvoja i znanje zavedoše te. U svom si srcu govorila: \'Ja i nitko drugi!\'');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (29, 47, 11, 'Zlo će te snaći - nećeš ga presresti; oborit će se na te nesreća - nećeš je odvratiti; doći će na te propast iznenada - nećeš je predvidjeti.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (29, 47, 12, 'Ustraj, dakle, u svojim zaklinjanjima i u tolikim svojim čaranjima, oko kojih si se trudila od mladosti. Možda će ti biti od koristi? Možda ćeš s njima strah utjerati?');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (29, 47, 13, 'Izmoriše te mnogi tvoji savjetnici! Nek\' ustanu samo da te spase oni koji premjeravaju nebesa, koji promatraju zvijezde i koji svakog mjeseca proriču ono što će te snaći.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (29, 47, 14, 'Gle, oni će biti poput pljeve, oganj će ih sažeći. Ni sami sebe neće izbaviti iz zagrljaja plamenoga. Neće ostat\' ni žerave da se tko ogrije, ni ognjišta da uza nj posjedne!');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (29, 47, 15, 'Takvi će ti biti vrači tvoji, oko kojih si se trudila od mladosti! Poći će svaki svojim putem, i nikog neće biti da te spasi.\"');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (29, 48, 1, 'Čujte ovo, kućo Jakovljeva, vi koji se zovete imenom Izraelovim i koji ste izišli iz voda Judinih! Vi koji se Jahvinim imenom kunete i slavite Boga Izraelova, ali ne u istini i pravdi.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (29, 48, 2, 'Jer vi se nazivate po Svetome gradu i oslanjate se na Boga Izraelova, Jahve nad Vojskama njemu je ime.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (29, 48, 3, 'Dogođaje prošle odavna sam navijestio, iz mojih su izišli usta i ja sam ih objavio, učinih brzo, i zbi se.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (29, 48, 4, 'Jer znao sam da si tvrdokoran, da ti je šija žila gvozdena i čelo da ti je mjedeno.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (29, 48, 5, 'Zato sam ti već onda navijestio, javio ti prije nego što se zbilo, da ne bi rekao: \"Moj kip učini to, rezani moj lik i ljeveni kip zapovjediše tako!\"');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (29, 48, 6, 'Čuo si i vidio sve to; zar ne priznaješ? A sada navijestit ću ti nešto novo, otajno, što još ne znaš;');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (29, 48, 7, 'ovog je trena stvoreno, a ne odavna, o tome dosad nisi ništa čuo, da ne bi rekao: \"Znao sam.\"');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (29, 48, 8, 'Nisi o tome čuo ni znao, niti se uho tvoje prije otvorilo, jer znadoh da ćeš se iznevjeriti i da te od utrobe majčine zovu otpadnikom.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (29, 48, 9, 'Radi imena svoga odgađah svoj gnjev, radi časti svoje susprezah se da te ne uništim.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (29, 48, 10, 'Gle, pročistio sam te poput srebra, iskušao te u talioniku nevolje.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (29, 48, 11, 'Sebe radi činih tako, sebe radi! TÓa zar da se ime moje obeščasti? Slave svoje drugome ne dam!');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (29, 48, 12, 'Čuj me, Jakove, Izraele, koga sam pozvao: Ja jesam, ja sam prvi, ja sam i posljednji.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (29, 48, 13, 'Ruka moja zemlju utemelji, desnica mi razape nebesa. Pozovem ih samo, i odmah dolaze.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (29, 48, 14, 'Saberite se svi i čujte: tko je od njih to prorekao? \"Onaj koga Jahve ljubi ispunit će volju moju nad Babilonom i nad potomstvom kaldejskim.\"');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (29, 48, 15, 'Ja rekoh i pozvah ga, vodih ga i pomogoh u naumu.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (29, 48, 16, 'Pristupite k meni i počujte ovo: \"Od početka nisam vam govorio tajno, i kad se zbivalo, bijah ondje.\" - \"A sada me Gospod Jahve šalje s duhom svojim.\"');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (29, 48, 17, 'Ovako govori Jahve, otkupitelj tvoj, Svetac Izraelov: \"Ja, Jahve, Bog tvoj, tvojem dobru te učim, vodim te putem kojim ti je ići.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (29, 48, 18, 'O, da si pazio na zapovijedi moje, kao rijeka sreća bi tvoja bila, a pravda tvoja kao morski valovi!');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (29, 48, 19, 'Potomstva bi tvojeg bilo kao pijeska, a poroda utrobe tvoje kao njegovih zrnaca! Nikad ti se ime ne bi zatrlo niti izbrisalo preda mnom!\"');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (29, 48, 20, 'Izađite iz Babilona, bježite iz Kaldeje! Glasno kličući, kazujte, objavljujte, do nakraj zemlje razglasite! Govorite: \"Jahve je otkupio slugu svoga Jakova!');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (29, 48, 21, 'Nisu žeđali dok ih je kroz pustinju vodio; iz stijene je za njih vodu izbio, rascijepio je pećinu i potekla je voda.\"');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (29, 48, 22, '\"Nema mira opakima,\" kaže Jahve.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (29, 49, 1, 'Čujte me, otoci, slušajte pomno, narodi daleki! Jahve me pozvao od krila materina, od utrobe majke moje spomenuo se moga imena.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (29, 49, 2, 'Od usta mojih britak mač je načinio, sakrio me u sjeni ruke svoje, od mene je oštru načinio strijelu, sakrio me u svome tobolcu.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (29, 49, 3, 'Rekao mi: \"Ti si Sluga moj, Izraele, u kom ću se proslaviti!\"');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (29, 49, 4, 'A ja rekoh: \"Zaludu sam se mučio, nizašto naprezao snagu.\" Ipak, kod Jahve je moje pravo, kod mog Boga nagrada je moja. A sad govori Jahve, koji me od utrobe Slugom svojim načini, da mu vratim natrag Jakova, da se sabere Izrael.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (29, 49, 5, 'Proslavih se u očima Jahvinim, Bog moj bijaše mi snaga.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (29, 49, 6, 'I reče mi: \"Premalo je da mi budeš Sluga, da podigneš plemena Jakovljeva i vratiš Ostatak Izraelov, nego ću te postaviti za svjetlost narodima, da spas moj do nakraj zemlje doneseš.\"');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (29, 49, 7, 'Ovako govori Jahve, otkupitelj Izraelov, Svetac njegov, onome kog preziru i odbacuju narodi, sluzi silničkome: \"Kad vide, dići će se kraljevi, bacit će se ničice knezovi, zbog Jahve, koji je vjernost svoju pokazao, Sveca Izraelova, koji te izabrao.\"');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (29, 49, 8, 'Ovako govori Jahve: \"U vrijeme milosti ja ću te uslišiti, u dan spasa ja ću ti pomoći. Sazdao sam te i postavio za Savez narodu, da zemlju podignem, da nanovo razdijelim baštinu opustošenu,');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (29, 49, 9, 'da kažeš zasužnjenima: \'Iziđite!\' a onima koji su u tami: \'Dođite na svjetlo!\' Oni će pasti uzduž svih putova, i paša će im biti po svim goletima.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (29, 49, 10, 'Neće više gladovat\' i žeđati, neće ih mučiti žega ni sunce, jer vodit će ih onaj koji im se smiluje, dovest će ih k izvorima vode.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (29, 49, 11, 'Sve gore svoje obratit će u putove, i ceste će se moje povisiti.\"');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (29, 49, 12, 'Gle, jedni dolaze izdaleka, drugi sa sjevera i sa zapada, a neki iz zemlje sinimske.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (29, 49, 13, 'Kličite, nebesa, veseli se, zemljo, podvikujte, planine, od veselja; jer Jahve tješi narod svoj, on je milosrdan nevoljnima.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (29, 49, 14, 'Sion reče: \"Jahve me ostavi, Gospod me zaboravi.\"');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (29, 49, 15, '\"Može li žena zaboravit\' svoje dojenče, ne imat\' sućuti za čedo utrobe svoje? Pa kad bi koja i zaboravila, tebe ja zaboraviti neću.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (29, 49, 16, 'Gle, u dlanove sam te svoje urezao, zidovi tvoji svagda su mi pred očima.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (29, 49, 17, 'Obnovitelji tvoji hitaju, rušioci tvoji i pustošitelji odlaze od tebe.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (29, 49, 18, 'Obazri se oko sebe i pogledaj: sabiru se svi i dolaze k tebi. Života mi moga\" - riječ je Jahvina - \"svima ćeš se njima zaodjenuti k\'o nakitom, i njima ćeš se k\'o nevjesta ukrasiti!');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (29, 49, 19, 'Jest, tvoje ruševine, tvoje razvaline i tvoja zemlja poharana pretijesna će biti žiteljima tvojim kad se udalje oni što te zatirahu.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (29, 49, 20, 'Opet će na tvoje uši reći sinovi kojih si bila lišena: \'Pretijesno mi je mjesto ovo, makni se da se mogu smjestiti.\'');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (29, 49, 21, 'I ti ćeš se u srcu svom zapitati: \'Tko mi rodi sve ove? Bijah bez djece, neplodna, prognana i odbačena, pa tko ih podiže? Bijah, eto, sama ostala, a oni gdje su bili?\'\"');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (29, 49, 22, 'Ovako govori Gospod Jahve: \"Evo, dajem rukom znak narodima i zastavu svoju dižem plemenima. Vratit će ti u naručju sinove, nosit će ti kćeri na plećima.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (29, 49, 23, 'Kraljevi će biti tvoji skrbnici, a kneginje im tvoje dojkinje. Klanjat će ti se licem do zemlje i prah će lizat s tvojih nogu. I znat ćeš da sam ja Jahve: koji se u me uzdaju, neće se posramiti.\"');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (29, 49, 24, 'Može li se otet plijen junaku? Može li sužanj pobjeć pobjedniku?');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (29, 49, 25, 'Da, ovako govori Jahve: \"Bit će oduzet sužanj junaku, pobjeći će plijen pobjedniku! S onima koji se s tobom spore ja ću se sporiti, tvoju djecu ja ću izbaviti;');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (29, 49, 26, 'tlačiteljima ću tvojim dati njihovo meso za jelo i svojom krvlju opit će se kao moštom. I znat će svako tijelo da sam ja Jahve, Spasitelj tvoj, i da je tvoj okupitelj Silni Jakovljev.\"');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (29, 50, 1, 'Ovako govori Jahve: \"Gdje je otpusno pismo vaše matere kojim sam je otpustio? Ili tko je od mojih vjerovnika taj komu sam vas prodao? Zbog bezakonja ste svojih prodani, zbog nevjere je mati vaša otpuštena.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (29, 50, 2, 'Zašto ne nađoh nikoga kad sam došao? Zašto se ne odazva nitko kad sam zazvao? Zar mi je ruka prekratka da izbavi, ili u meni snage nema da oslobodim? Gle, prijetnjom svojom isušujem more, u pustinje rijeke pretvaram; njihove se ribe raspadaju jer vode nema i od žeđi ugibaju.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (29, 50, 3, 'Nebesa oblačim u tminu i kostrijet im dajem za pokrivač!\"');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (29, 50, 4, 'Gospod Jahve dade mi jezik vješt da znam riječju krijepiti umorne. Svako jutro on mi uho budi da ga slušam kao učenici.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (29, 50, 5, 'Gospod Jahve uši mi otvori: ne protivih se niti uzmicah.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (29, 50, 6, 'Leđa podmetnuh onima što me udarahu, a obraze onima što mi bradu čupahu, i lica svojeg ne zaklonih od uvreda ni od pljuvanja.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (29, 50, 7, 'Gospod mi Jahve pomaže, zato se neću smesti. Zato učinih svoj obraz k\'o kremen i znam da se neću postidjeti.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (29, 50, 8, 'Blizu je onaj koji mi pravo daje. Tko će se pravdati sa mnom? Iziđimo zajedno! Tko je protivnik moj u parnici? Nek\' mi se približi!');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (29, 50, 9, 'Gle, Gospod mi Jahve pomaže, tko će me osuditi? Svi će se oni k\'o haljina izlizati, moljac će ih razjesti.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (29, 50, 10, '\"Tko god se od vas Jahve boji, nek\' posluša glas Sluge njegova! Tko u tmini hodi, bez tračka svjetlosti, nek\' se uzda u ime Jahvino, nek\' se na Boga svog osloni.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (29, 50, 11, 'Ali svi vi oganj palite, raspirujete žeravicu. Idite u plamenove ognja svojega i u žeravu koju raspiriste. Tako će vam moja učiniti ruka: ležat ćete u mukama.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (29, 51, 1, 'Čujte me, vi koji za pravdom težite, koji Jahvu tražite; pogledajte stijenu iz koje ste isječeni i jamu duboku iz koje ste izvađeni.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (29, 51, 2, 'Pogledajte oca svoga Abrahama i Saru koja vas porodi! Jest, sam bijaše kad sam ga pozvao, al\' sam ga blagoslovio i umnožio.\"');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (29, 51, 3, 'Jest, Jahvi se sažalio Sion, sažalile mu se njegove razvaline. Pustaru će njegovu učiniti poput Edena, a stepu poput Vrta Jahvina. Klicanje i radost njim će odjekivat\', i zahvalnice i glas hvalospjeva.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (29, 51, 4, '\"Pomno me slušaj, puče moj, počujte me, narodi! Jer od mene Zakon dolazi i moje pravo za svjetlo narodima.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (29, 51, 5, 'Brzo će stići pravda moja, moje će spasenje doći kao svjetlost. Moja će mišica suditi narodima. Mene očekuju otoci i u moju se mišicu uzdaju.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (29, 51, 6, 'K nebu oči podignite, na zemlju dolje pogledajte. K\'o dim će se rasplinut\' nebesa, zemlja će se k\'o haljina istrošit\', kao komarci nestat će joj žitelji. Ali će spasenje moje trajati dovijeka, i pravdi mojoj neće biti kraja.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (29, 51, 7, 'Poslušajte me, vi koji poznajete pravo, narode kojima je moj Zakon u srcu. Ne bojte se poruge ljudske, ne plašite se uvreda!');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (29, 51, 8, 'Jer moljac će ih razjesti kao haljinu, crv će ih rastočiti kao vunu. Ali će pravda moja trajati dovijeka i spas moj od koljena do koljena.\"');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (29, 51, 9, 'Probudi se! Probudi se! Opaši se snagom, mišice Jahvina! Probudi se, kao u dane davne, za drevnih naraštaja. Nisi li ti rasjekla Rahaba i probola Zmaja?');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (29, 51, 10, 'Nisi li ti isušila more, vodu velikog bezdana, i od dubine morske put načinila da njime prolaze otkupljeni?');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (29, 51, 11, 'Vratit će se oni što ih je oslobodio Jahve i s radosnim kricima doći će na Sion. Vječna će sreća biti nad glavama, pratit će ih klicanje i radost, nestat će tuge i jecaja.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (29, 51, 12, 'Ja, ja sam tješitelj vaš. Tko si ti da se bojiš smrtna čovjeka i sina čovječjeg, koji je kao trava?');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (29, 51, 13, 'Zaboravio si Jahvu, svoga Stvoritelja, koji razastrije nebesa i koji zemlju utemelji; sveudilj strepiš, svaki dan, od tlačiteljeve jarosti. Kao da je pregnuo da te uništi. Ali gdje je sad jarost tlačiteljeva?');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (29, 51, 14, 'Doskora će biti slobodan sužanj, neće umrijeti u jami, niti će mu kruha nedostajati.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (29, 51, 15, 'Jer, ja sam Jahve, Bog tvoj, koji burkam more da mu valovi buče, ime mi je Jahve nad Vojskama.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (29, 51, 16, 'Svoje sam ti riječi stavio u usta, u sjenu svoje ruke sakrio sam te kad sam razastro nebesa, utemeljio zemlju i rekao Sionu: \"Ti si narod moj!\"');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (29, 51, 17, 'Probudi se, probudi se, ustani, Jeruzaleme! Ti koji si pio iz ruke Jahvine čašu gnjeva njegova. Ispio si pehar opojni, do dna ga iskapio.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (29, 51, 18, 'Od svih sinova koje je rodio ne bješe nikog da ga vodi; od svih sinova koje je podigao ne bješe nikog da ga pridrži.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (29, 51, 19, 'Ovo te dvoje pogodilo - tko da te požali? - pohara i rasap, glad i mač - tko da te utješi?');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (29, 51, 20, 'Sinovi ti leže obamrli po uglovima svih ulica, kao antilopa u mreži, puni gnjeva Jahvina, prijetnje Boga tvojega.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (29, 51, 21, 'Zato čuj ovo, bijedniče, pijan, ali ne od vina.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (29, 51, 22, 'Ovako govori Jahve, Gospod tvoj, tvoj Bog, branitelj tvoga naroda: \"Iz ruke ti, evo, uzimam čašu opojnu, pehar gnjeva svojega: nećeš ga više piti.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (29, 51, 23, 'Stavit ću je u ruke tvojim tlačiteljima, onima koji su ti govorili: \'Prigni se da prijeđemo!\' I ti si im leđa kao tlo podmetao, kao put za prolaznike.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (29, 52, 1, 'Probudi se! Probudi se! Odjeni se snagom, Sione! Odjeni se najsjajnijim haljinama, Jeruzaleme, grade sveti, jer više neće k tebi ulaziti neobrezani i nečisti.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (29, 52, 2, 'Otresi prah sa sebe, ustani, izgnani Jeruzaleme! Skini okov sa svog vrata, izgnana kćeri sionska.\"');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (29, 52, 3, 'Jest, ovako govori Jahve: \"Bili ste prodani nizašto i bit ćete otkupljeni bez novaca.\"');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (29, 52, 4, 'Jest, ovako govori Gospod Jahve: \"Moj je narod sišao nekoć u Egipat da se ondje nastani kao stranac, potom ga Asirci nizašto potlačiše.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (29, 52, 5, 'Ali sada, čemu sam ja ovdje - riječ je Jahvina - kad je moj narod bio bez razloga porobljen, a gospodari njegovi likuju - riječ je Jahvina - i bez prestanka se danomice ime moje huli.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (29, 52, 6, 'Zato će narod moj poznati moje ime i shvatit će u onaj dan da sam ja koji govorim: \'Evo me!\'\"');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (29, 52, 7, 'Kako su ljupke po gorama noge glasonoše radosti koji oglašava mir, nosi sreću, i spasenje naviješta govoreć Sionu: \"Bog tvoj kraljuje!\"');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (29, 52, 8, 'Čuj, stražari ti glas podižu, zajedno svi kliču od radosti, jer na svoje oči vide gdje se na Sion vraća Jahve.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (29, 52, 9, 'Radujte se, kličite, razvaline jeruzalemske, jer je Jahve utješio narod svoj i otkupio Jeruzalem.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (29, 52, 10, 'Ogolio je Jahve svetu svoju mišicu pred očima svih naroda, da svi krajevi zemaljski vide spasenje Boga našega.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (29, 52, 11, 'Odlazite, odlazite, iziđite odatle, ne dotičite ništa nečisto! Iziđite iz njegove sredine! Očistite se, vi koji nosite posude Jahvine!');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (29, 52, 12, 'Jer nećete izići u hitnji, niti ćete ići bježeći, jer će vam prethodnica biti Jahve, a zalaznica Bog Izraelov!');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (29, 52, 13, 'Gle, uspjet će Sluga moj, podignut će se, uzvisit\' i proslaviti!');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (29, 52, 14, 'Kao što se mnogi užasnuše vidjevši ga - tako mu je lice bilo neljudski iznakaženo te obličjem više nije naličio na čovjeka -');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (29, 52, 15, 'tako će on mnoge zadiviti narode i kraljevi će pred njim usta stisnuti videć\' ono o čemu im nitko nije govorio, shvaćajuć\' ono o čemu nikad čuli nisu:');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (29, 53, 1, '\"Tko da povjeruje u ono što nam je objavljeno, kome se otkri ruka Jahvina?\"');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (29, 53, 2, 'Izrastao je pred njim poput izdanka, poput korijena iz zemlje sasušene. Ne bijaše na njem ljepote ni sjaja da bismo se u nj zagledali, ni ljupkosti da bi nam se svidio.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (29, 53, 3, 'Prezren bješe, odbačen od ljudi, čovjek boli, vičan patnjama, od kog svatko lice otklanja, prezren bješe, odvrgnut.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (29, 53, 4, 'A on je naše bolesti ponio, naše je boli na se uzeo, dok smo mi držali da ga Bog bije i ponižava.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (29, 53, 5, 'Za naše grijehe probodoše njega, za opačine naše njega satriješe. Na njega pade kazna - radi našeg mira, njegove nas rane iscijeliše.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (29, 53, 6, 'Poput ovaca svi smo lutali i svaki svojim putem je hodio. A Jahve je svalio na nj bezakonje nas sviju.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (29, 53, 7, 'Zlostavljahu ga, a on puštaše, i nije otvorio usta svojih. K\'o jagnje na klanje odvedoše ga; k\'o ovca, nijema pred onima što je strižu, nije otvorio usta svojih.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (29, 53, 8, 'Silom ga se i sudom riješiše; tko se brine za njegovu sudbinu? Da, iz zemlje živih ukloniše njega, za grijehe naroda njegova nasmrt ga izbiše.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (29, 53, 9, 'Ukop mu odrediše među zločincima, a grob njegov bi s bogatima, premda nije počinio nepravde nit\' su mu usta laži izustila.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (29, 53, 10, 'Al\' se Jahvi svidje da ga pritisne bolima. Žrtvuje li život svoj za naknadnicu, vidjet će potomstvo, produžit\' sebi dane i Jahvina će se volja po njemu ispuniti.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (29, 53, 11, 'Zbog patnje duše svoje vidjet će svjetlost i nasititi se spoznajom njezinom. Sluga moj pravedni opravdat će mnoge i krivicu njihovu na sebe uzeti.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (29, 53, 12, 'Zato ću mu mnoštvo dati u baštinu i s mogućnicima plijen će dijeliti, jer sam se ponudio na smrt i među zlikovce bio ubrojen, da grijehe mnogih ponese na sebi i da se zauzme za zločince.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (29, 54, 1, 'Kliči, nerotkinjo, koja nisi rađala; podvikuj od radosti, ti što ne znaš za trudove! Jer osamljena više djece ima negoli udata, kaže Jahve.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (29, 54, 2, 'Raširi prostor svog šatora, razastri, ne štedi platna svog prebivališta, produži mu užeta, kolčiće učvrsti!');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (29, 54, 3, 'Jer proširit ćeš se desno i lijevo. Tvoje će potomstvo zavladat\' narodima i napučit će opustjele gradove.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (29, 54, 4, 'Ne boj se, nećeš se postidjeti; na srami se, nećeš se crvenjeti. Zaboravit ćeš sramotu svoje mladosti i više se nećeš spominjati rugla udovištva svoga.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (29, 54, 5, 'Jer suprug ti je tvoj Stvoritelj, ime mu je Jahve nad Vojskama; tvoj je Otkupitelj Svetac Izraelov, Bog zemlje svekolike on se zove.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (29, 54, 6, 'Jest, k\'o ženu ostavljenu, u duši ucviljenu, Jahve te pozvao. Zar se smije otpustiti žena svoje mladosti, pita Bog tvoj.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (29, 54, 7, '\"Za kratak trenutak ostavih tebe, al\' u sućuti velikoj opet ću te prigrliti.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (29, 54, 8, 'U provali srdžbe sakrih načas od tebe lice svoje, al\' u ljubavi vječnoj smilovah se tebi,\" govori Jahve, tvoj Otkupitelj.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (29, 54, 9, '\"Bit će mi k\'o za Noinih dana, kad se zakleh da vode Noine neće više preplaviti zemlju; tako se zaklinjem da se više neću na tebe srditi nit\' ću ti prijetiti.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (29, 54, 10, 'Nek\' se pokrenu planine i potresu brijezi, al\' se ljubav moja neće odmać\' od tebe, nit\' će se pokolebati moj Savez mira,\" kaže Jahve koji ti se smilovao.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (29, 54, 11, '\"O nevoljnice, vihorom vitlana, neutješna, gle, postavit ću na smaragd tvoje kamenje i na safir tvoje temelje.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (29, 54, 12, 'Od rubina dići ću ti kruništa, vrata tvoja od prozirca, ograde ti od dragulja.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (29, 54, 13, 'Svi će ti sinovi Jahvini biti učenici, i velika će biti sreća djece tvoje.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (29, 54, 14, 'Na pravdi ćeš biti zasnovana. Odbaci tjeskobu, nemaš se čega bojati, odbaci strah jer ti se neće primaći.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (29, 54, 15, 'Ako li te napadnu, neće doći od mene; tko se na te digne, zbog tebe će pasti.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (29, 54, 16, 'Gle, ja sam stvorio kovača koji raspaljuje žeravu i vadi iz nje oružje da ga kuje. Ali stvorih i zatornika da uništava.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (29, 54, 17, 'Neće uspjeti oružje protiv tebe skovano. Dokazat ćeš da je zao svaki jezik što na te udari na sudu. To je baština slugu Jahvinih, to im je pobjeda od mene\" - riječ je Jahvina.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (29, 55, 1, '\"O svi vi koji ste žedni, dođite na vodu; ako novaca i nemate, dođite. Bez novaca i bez naplate kupite vina i mlijeka!');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (29, 55, 2, 'Zašto da trošite novac na ono što kruh nije i nadnicu svoju na ono što ne siti? Mene poslušajte, i dobro ćete jesti i sočna ćete uživati jela.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (29, 55, 3, 'Priklonite uho i k meni dođite, poslušajte, i duša će vam živjeti. Sklopit ću s vama Savez vječan, Savez milosti Davidu obećanih.\"');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (29, 55, 4, 'Evo, učinih te svjedokom pucima, knezom i zapovjednikom narodima.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (29, 55, 5, 'Evo, pozvat ćeš narod koji ne poznaješ, i narod koji te ne zna dohrlit će k tebi radi Jahve, Boga tvojega, i Sveca Izraelova, jer on te proslavio.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (29, 55, 6, 'Tražite Jahvu dok se može naći, zovite ga dok je blizu!');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (29, 55, 7, 'Nek\' bezbožnik put svoj ostavi, a zlikovac naume svoje. Nek\' se vrati Gospodu, koji će mu se smilovati, k Bogu našem jer je velikodušan u praštanju.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (29, 55, 8, '\"Jer misli vaše nisu moje misli i puti moji nisu vaši puti,\" riječ je Jahvina.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (29, 55, 9, '\"Visoko je iznad zemlje nebo, tako su puti moji iznad vaših putova, i misli moje iznad vaših misli.\"');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (29, 55, 10, '\"Kao što daždi i sniježi s neba bez prestanka dok se zemlja ne natopi, oplodi i ozeleni da bi dala sjeme sijaču i kruha za jelo,');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (29, 55, 11, 'tako se riječ koja iz mojih usta izlazi ne vraća k meni bez ploda, nego čini ono što sam htio i obistinjuje ono zbog čega je poslah.\"');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (29, 55, 12, 'Da, s radošću ćete otići i u miru ćete biti vođeni. Gore će i brda klicati od radosti pred vama i sva će stabla u polju pljeskati.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (29, 55, 13, 'Umjesto trnja rast će čempresi, umjesto koprive mirta će nicati. I bit će to Jahvi na slavu, kao znak vječan, neprolazan.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (29, 56, 1, 'Ovako govori Jahve: \"Držite se prava i činite pravdu, jer će uskoro doći moj spas i objaviti se moja pravednost.\"');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (29, 56, 2, 'Blago čovjeku koji čini tako i sinu čovječjem što se toga pridržava: koji poštuje subotu da je ne oskvrni i koji ruke svoje čuva od svakoga zla djela.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (29, 56, 3, 'Neka sin tuđinčev koji je prionuo uz Jahvu ne govori: \"Jamačno će me Jahve odvojiti od svojega naroda.\" Neka uškopljenik ne govori: \"Ja sam, evo, tek suho drvo.\"');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (29, 56, 4, 'Jer ovako govori Jahve: \"S uškopljenicima koji obdržavaju subotu, koji izabiru što je meni drago i ostanu postojani u Savezu mome -');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (29, 56, 5, 'podići ću u kući svojoj i među svojim zidovima spomenik i ime, bolje nego sinovima i kćerima, dat ću im vječno ime koje neće biti iskorijenjeno.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (29, 56, 6, 'A sinove tuđinske koji pristadoše uz Jahvu da mu služe i da ljube ime Jahvino i da mu budu službenici, koji poštuju subotu i ne oskvrnjuju je i postojani su u Savezu mome,');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (29, 56, 7, 'njih ću dovesti na svoju svetu goru i razveseliti u svojem Domu molitve. Njihove žrtve paljenice i klanice bit će ugodne na mojem žrtveniku, jer će se Dom moj zvati Dom molitve za sve narode.\"');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (29, 56, 8, 'Riječ je Gospoda Jahve koji sabire raspršene Izraelce: \"Sabrat ću ih još povrh onih koji su već sabrani.\"');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (29, 56, 9, 'Sve zvijeri poljske, dođite jesti, i sve vi, zvijeri šumske!');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (29, 56, 10, 'Svi su mu stražari slijepi, i ništa ne shvaćaju. Svi su oni psi nijemi, ne mogu lajati. Sanjaju i drijemlju, najmilije im spavati.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (29, 56, 11, 'Psi su to proždrljivi, nezasitni; pastiri su to bez razbora: svaki svojim putem okreće, svaki za dobitkom svojim.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (29, 56, 12, '\"Dođite, donijet ću vina; napit ćemo se pića žestoka, i sutra će biti kao danas, izobilje veliko, preveliko!\"');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (29, 57, 1, 'Pravednik gine, i nitko ne mari. Uklanjaju ljude pobožne, i nitko ne shvaća. Da, zbog zla uklonjen je pravednik');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (29, 57, 2, 'da bi ušao u mir. Tko god je pravim putem hodio počiva na svom ležaju.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (29, 57, 3, 'Pristupite sad, sinovi vračarini, leglo preljubničko i bludničko!');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (29, 57, 4, 'S kim se podrugujete, na koga razvaljujete usta i komu jezik plazite? Niste li vi porod grešan i leglo lažljivo?');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (29, 57, 5, 'Vi koji se raspaljujete među hrašćem, pod svakim zelenim drvetom, žrtvujući djecu u dolinama i u rasjelinama stijena!');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (29, 57, 6, 'Dio je tvoj među oblucima potočnim, oni, oni su baština tvoja. Njima izlijevaš ljevanicu, njima prinosiš darove! Zar da se time ja utješim?');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (29, 57, 7, 'Na gori visokoj, uzdignutoj, svoj si ležaj postavila i popela se onamo da prinosiš žrtvu klanicu.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (29, 57, 8, 'Za vrata i dovratke metnula si spomen svoj; daleko od mene svoj ležaj raskrivaš, penješ se na nj i širiš ga. Pogađala si se s onima s kojima si voljela lijegati, sve si više bludničila s njima gledajuć\' im mušku snagu.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (29, 57, 9, 'S uljem za Molekom trčiš, s pomastima mnogim, nadaleko posla glasnike svoje, strovali ih u Podzemlje.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (29, 57, 10, 'Iscrpljena si od tolikih lutanja, al\' nisi rekla: \"Beznadno je!\" Snagu si svoju nanovo našla te nisi sustala.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (29, 57, 11, 'Koga si se uplašila i pobojala da si se iznevjerila, da se više nisi mene spominjala, niti si me k srcu uzimala? Šutio sam, zatvarao oči, zato me se nisi bojala.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (29, 57, 12, 'Ali ću objavit\' o tvojoj pravdi i djela ti tvoja neće koristiti.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (29, 57, 13, 'Kad uzmeš vikati, nek\' te izbave kipovi koje si skupila, sve će ih vjetar raznijeti, vihor će ih otpuhnuti. A tko se u me uzda, baštinit će zemlju i zaposjest će svetu goru moju.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (29, 57, 14, 'Govorit će se: Naspite, naspite, poravnajte put! Uklonite zapreke s puta mog naroda!');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (29, 57, 15, 'Jer ovako govori Višnji i Uzvišeni, koji vječno stoluje i ime mu je Sveti: \"U prebivalištu visokom i svetom stolujem, ali ja sam i s potlačenim i poniženim, da oživim duh smjernih, da oživim srca skrušenih.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (29, 57, 16, 'Jer neću se prepirati dovijeka ni vječno se ljutiti: preda mnom bi podlegao duh i duše što sam ih stvorio.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (29, 57, 17, 'Zbog grijeha lakomosti njegove razgnjevih se, udarih ga i sakrih se rasrđen. Ali on okrenu za srcem svojim');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (29, 57, 18, 'i vidjeh putove njegove. Izliječit ću ga, voditi i utješit\' one što s njime tuguju -');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (29, 57, 19, 'stavit ću hvalu na usne njihove. Mir, mir onom tko je daleko i tko je blizu,\" govori Jahve, \"ja ću te izliječiti.\"');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (29, 57, 20, 'Al\' opaki su poput mora uzburkanog koje se ne može smiriti, valovi mu mulj i blato izmeću.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (29, 57, 21, '\"Nema mira grešnicima!\" govori Bog moj.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (29, 58, 1, 'Viči iz sveg grla, ne suspeži se! Glas svoj poput roga podigni. Objavi mom narodu njegove zločine, domu Jakovljevu grijehe njegove.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (29, 58, 2, 'Dan za danom oni mene traže i žele znati moje putove, kao narod koji vrši pravdu i ne zaboravlja pravo Boga svoga. Od mene ištu pravedne sudove i žude da im se Bog približi:');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (29, 58, 3, '\"Zašto postimo ako ti ne vidiš, zašto se trapimo ako ti ne znaš?\" Gle, u dan kad postite poslove nalazite i na posao gonite radnike svoje.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (29, 58, 4, 'Gle, vi postite da se prepirete i svađate i da pesnicom bijete siromahe. Ne postite više kao danas, i čut će vam se glas u visini!');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (29, 58, 5, 'Zar je meni takav post po volji u dan kad se čovjek trapi? Spuštati kao rogoz glavu k zemlji, sterati poda se kostrijet i pepeo, hoćeš li to zvati postom i danom ugodnim Jahvi?');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (29, 58, 6, 'Ovo je post koji mi je po volji, riječ je Jahve Gospoda: Kidati okove nepravedne, razvezivat\' spone jarmene, puštati na slobodu potlačene, slomiti sve jarmove;');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (29, 58, 7, 'podijeliti kruh svoj s gladnima, uvesti pod krov svoj beskućnike, odjenuti onog koga vidiš gola i ne kriti se od onog tko je tvoje krvi.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (29, 58, 8, 'Tad će sinut\' poput zore tvoja svjetlost, i zdravlje će tvoje brzo procvasti. Pred tobom će ići tvoja pravda, a Slava Jahvina bit će ti zalaznicom.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (29, 58, 9, 'Vikneš li, Jahve će ti odgovorit, kad zavapiš, reći će: \"Evo me!\" Ukloniš li iz svoje sredine jaram, ispružen prst i besjedu bezbožnu,');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (29, 58, 10, 'dadeš li kruha gladnome, nasitiš li potlačenog, tvoja će svjetlost zasjati u tmini i tama će tvoja kao podne postati,');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (29, 58, 11, 'Jahve će te vodit\' bez prestanka, sitit će te u sušnim krajevima. On će krijepit\' kosti tvoje i bit ćeš kao vrt zaljeven, kao studenac kojem voda nikad ne presuši.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (29, 58, 12, 'I ti ćeš gradit\' na starim razvalinama, dići ćeš temelje budućih koljena. Zvat će te popravljačem pukotina i obnoviteljem cesta do naselja.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (29, 58, 13, 'Zadržiš li nogu da ne pogaziš subotu i u sveti dan ne obavljaš poslove; nazoveš li subotu milinom a časnim dan Jahvi posvećen; častiš li ga odustajuć\' od puta, bavljenja poslom i pregovaranja -');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (29, 58, 14, 'tad ćeš u Jahvi svoju milinu naći, i ja ću te provesti po zemaljskim visovima, dat ću ti da uživaš u baštini oca tvog Jakova, jer Jahvina su usta govorila.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (29, 59, 1, 'Ne, nije ruka Jahvina prekratka da spasi, niti mu je uho otvrdlo da ne bi čuo,');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (29, 59, 2, 'nego su opačine vaše jaz otvorile između vas i Boga vašega. Vaši su grijesi lice njegovo zastrli, i on vas više ne sluša.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (29, 59, 3, 'Jer ruke su vaše u krvi ogrezle, a vaši prsti u zločinima. Usne vam izgovaraju laž, a jezik podlost mrmlja.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (29, 59, 4, 'Nitko s pravom tužbu ne podiže, niti koga sude po istini. U ništavilo se uzdaju, laž kazuju, začinju zloću, a rađaju bezakonje.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (29, 59, 5, 'Legu jaja gujina, tkaju mrežu paukovu; pojede li tko njihovo jaje, umire, razbije li ga, iz njega ljutica izlazi.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (29, 59, 6, 'Njihovim tkanjem nemoguće se odjenuti, ne možeš se pokriti njihovom rukotvorinom. Rukotvorine su njihove djela zločinačka, rukama svojim čine nasilje.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (29, 59, 7, 'Noge njihove u zlo hitaju i brze su da krv nevinu proliju. Misli su im misli zločinačke, pustoš i propast na njinim su putima.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (29, 59, 8, 'Put mira oni ne poznaju, na stazama njihovim nema pravice. Iskrivili su svoje putove, tko njima kreće mira ne poznaje.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (29, 59, 9, 'Stog\' se pravo od nas udaljilo, zato pravda ne dopire do nas. Nadasmo se svjetlosti, a ono tama; i vidjelu, a ono u tmini hodimo.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (29, 59, 10, 'Pipamo kao slijepci duž zida, tapkamo kao bez očiju. Spotičemo se u podne k\'o u sumraku, sasvim zdravi, kao da smo mrtvi.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (29, 59, 11, 'Svi mumljamo kao medvjedi i gučemo tužno kao golubovi. Očekivasmo Sud, a njega nema, i spasenje - od nas je daleko.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (29, 59, 12, 'Jer mnogo je naših opačina pred tobom i grijesi naši protiv nas svjedoče. Doista, prijestupi su naši pred nama, mi znademo svoju krivicu;');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (29, 59, 13, 'pobunili smo se i zanijekali Jahvu, odmetnuli se od Boga svojega, govorili podlo, odmetnički, mrmljali u srcu riječi lažljive.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (29, 59, 14, 'Tako je potisnuto pravo, i pravda mora stajati daleko. Jer na trgu posrnu istina i poštenju nema više pristupa.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (29, 59, 15, 'Vjernosti je ponestalo, a tko izbjegava zlo, bude opljačkan. Jahve vidje, i ne bi mu milo što nema pravice.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (29, 59, 16, 'Vidje da nema čovjeka, začudi se što nema posrednika. Tad mu pomože njegova mišica i njegova ga pravda poduprije.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (29, 59, 17, 'Pravednost je obukao k\'o oklop, stavio na glavu kacigu spasenja. Osvetom se odjenuo k\'o haljom, ogrnu se revnošću kao plaštem.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (29, 59, 18, 'Vratit će svakome po njegovim djelima: gnjev svojim protivnicima, odmazdu dušmanima.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (29, 59, 19, 'Sa zapada vidjet će ime Jahvino i Slavu njegovu s istoka sunčanog. Jer doći će kao uska rijeka koju goni dah Jahvin.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (29, 59, 20, 'Ali doći će Otkupitelj Sionu, i onima od sinova Jakovljevih koji se obrate od svog otpadništva, riječ je Jahvina.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (29, 59, 21, '\"A ovo je moj Savez s njima,\" govori Jahve. \"Duh moj koji je na tebi i riječi moje koje stavih u tvoja usta neće izići iz usta tvojih ni usta tvojega potomstva, ni iz usta potomstva tvojih potomaka, od sada pa dovijeka,\" veli Jahve.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (29, 60, 1, 'Ustani, zasini, jer svjetlost tvoja dolazi, nad tobom blista Slava Jahvina.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (29, 60, 2, 'A zemlju, evo, tmina pokriva, i mrklina narode! A tebe obasjava Jahve, i Slava se njegova javlja nad tobom.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (29, 60, 3, 'K tvojoj svjetlosti koračaju narodi, i kraljevi k istoku tvoga sjaja.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (29, 60, 4, 'Podigni oči, obazri se: svi se sabiru, k tebi dolaze. Sinovi tvoji dolaze izdaleka, kćeri ti nose u naručju.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (29, 60, 5, 'Gledat ćeš tad i sjati radošću, igrat će srce i širit\' se, jer k tebi će poteći bogatstvo mora, blago naroda k tebi će pritjecati.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (29, 60, 6, 'Mnoštvo deva prekrit će te, jednogrbe deve iz Midjana i Efe. Svi će iz Šebe doći donoseći zlato i tamjan i hvale Jahvi pjevajući.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (29, 60, 7, 'Sva stada kedarska u tebi će se sabrati, ovnovi nebajotski bit će ti na službu. Penjat će se k\'o ugodna žrtva na moj žrtvenik, proslavit ću Dom Slave svoje!');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (29, 60, 8, 'Tko su oni što lebde poput oblaka, k\'o golubovi prema golubinjacima svojim?');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (29, 60, 9, 'Da, to se zbog mene sabiru brodovi, lađe su taršiške pred njima da izdaleka dovezu tvoje sinove, a s njima srebro njihovo i zlato, zbog imena Jahve, Boga tvojega, zbog Sveca Izraelova koji te proslavi.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (29, 60, 10, 'Zidine će tvoje obnoviti stranci i kraljevi njihovi služit će ti. U svojoj srdžbi ja sam te udario, al\' u svojoj naklonosti opet ti se smilovah.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (29, 60, 11, 'Vrata će tvoja biti otvorena svagda, ni danju ni noću neće se zatvarati, da propuste k tebi bogatstva naroda s kraljevima koji ih vode.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (29, 60, 12, 'Jer propast će narod i kraljevstvo koje ti ne bude htjelo služiti, i ti će se narodi sasvim zatrti.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (29, 60, 13, 'K tebi će doći slava Libanona, čempresi, jele i brijestovi skupa, da ukrase prostor mojega Svetišta, podnožje će moje proslaviti!');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (29, 60, 14, 'K tebi će, sagnuti, dolaziti sinovi tvojih tlačitelja, pred noge ti padat\' koji te prezirahu. Nazivat će te Gradom Jahvinim, Sionom Sveca Izraelova.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (29, 60, 15, 'Zato što si bio ostavljen, omražen, izbjegavan, učinit ću te vječnim ponosom, radošću od koljena do koljena.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (29, 60, 16, 'Ti ćeš sisati mlijeko naroda, sisat ćeš grudi kraljeva. I znat ćeš da sam ja, Jahve, Spasitelj tvoj, Silni Jakovljev, tvoj Otkupitelj.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (29, 60, 17, 'Mjesto mjedi, donijet ću zlato; mjesto željeza, donijet ću srebro; mjesto drva, mjed; mjesto kamena, željezo. Za glavara tvoga postavit ću Mir, Pravdu za vladara.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (29, 60, 18, 'Više se neće slušat\' o nasilju u tvojoj zemlji ni o pustošenju i razaranju na tvojem području. Zidine ćeš svoje nazivati Spasom, Slavom svoja vrata.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (29, 60, 19, 'Neće ti više sunce biti svjetlost danju nit\' će ti svijetlit\' mjesečina, nego će Jahve biti tvoje vječno svjetlo i tvoj će Bog biti tvoj sjaj.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (29, 60, 20, 'Sunce tvoje neće više zalaziti nit\' će ti mjesec pomrčati, jer će Jahve biti tvoje vječno svjetlo, i okončat će se dani tvoje žalosti.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (29, 60, 21, 'Svi u tvom narodu bit će pravednici i posjedovat će zemlju dovijeka, mog nasada izdanci, mojih ruku djelo, da bih se u njima proslavio.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (29, 60, 22, 'Od najmanjega postat će tisuća, od neznatnoga moćan narod. Ja, Jahve, govorio sam; u pravo ću vrijeme izvršiti.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (29, 61, 1, 'Duh Jahve Gospoda na meni je, jer me Jahve pomaza, posla me da radosnu vijest donesem ubogima, da iscijelim srca slomljena; da zarobljenima navijestim slobodu i oslobođenje sužnjevima;');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (29, 61, 2, 'da navijestim godinu milosti Jahvine i dan odmazde Boga našega; da razveselim ožalošćene na Sionu');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (29, 61, 3, 'i da im dadem vijenac mjesto pepela, ulje radosti mjesto ruha žalosti, pjesmu zahvalnicu mjesto duha očajna. I zvat će ih Hrastovima pravde, Nasadom Jahvinim - na slavu njegovu.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (29, 61, 4, 'Oni će nanovo dići drevne razvaline, sazdati opet mjesta poharana, ruševine prošlih pokoljenja.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (29, 61, 5, 'Tuđinci će doći da vam stada pasu, stranci će vam biti ratari i vinogradari.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (29, 61, 6, 'A vas će zvati \"Svećenici Jahvini\", nazivat će vas \"Službenici Boga našega\". Uživat ćete bogatstva naroda, blagom se njihovim dičiti.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (29, 61, 7, 'Dvostruka bijaše njihova sramota - rug i prezir bijahu im baština - zato će u zemlji svojoj baštinit\' dvostruko, njihova će biti radost vječita.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (29, 61, 8, 'Jer ja, Jahve, ljubim pravdu, a mrzim grabež nepravedni. Vjerno ću ih nagraditi i sklopiti s njima Savez vječni.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (29, 61, 9, 'Slavno će im biti sjeme među pucima i potomstvo među narodima. Tko god ih vidi, prepoznat će da su sjeme što ga Jahve blagoslovi.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (29, 61, 10, 'Radošću silnom u Jahvi se radujem, duša moja kliče u Bogu mojemu, jer me odjenu haljinom spasenja, zaogrnu plaštem pravednosti, kao ženik kad sebi vijenac stavi il\' nevjesta kad se uresi nakitom.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (29, 61, 11, 'Kao što zemlja tjera svoje klice, kao što u vrtu niče sjemenje, učinit će Gospod da iznikne pravda i hvala pred svim narodima.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (29, 62, 1, 'Sionu za ljubav neću šutjeti, Jeruzalema radi neću mirovati dok pravda njegova ne zasine k\'o svjetlost, dok njegovo spasenje ne plane k\'o zublja.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (29, 62, 2, 'I puci će vidjet\' tvoju pravednost, i tvoju slavu svi kraljevi; prozvat će te novim imenom što će ga odrediti usta Jahvina.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (29, 62, 3, 'U Jahvinoj ćeš ruci biti kruna divna i kraljevski vijenac na dlanu Boga svog.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (29, 62, 4, 'Neće te više zvati Ostavljenom ni zemlju tvoju Opustošenom, nego će te zvati Moja milina, a zemlju tvoju Udata, jer ti si milje Jahvino i zemlja će tvoja imat\' supruga.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (29, 62, 5, 'Kao što se mladić ženi djevicom, tvoj će se graditelj tobom oženiti; i kao što se ženik raduje nevjesti, tvoj će se Bog tebi radovati.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (29, 62, 6, 'Na zidine tvoje, Jeruzaleme, stražare sam postavio: ni danju ni noću ne smiju zašutjeti. O, vi koji podsjećate Jahvu, vama nema počinka!');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (29, 62, 7, 'I ne dajte mu mira dok ne obnovi Jeruzalem, dok ga opet slavom na zemlji ne učini.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (29, 62, 8, 'Zakle se Gospod desnicom i mišicom svojom snažnom: \"Neću više dati žita tvoga za hranu neprijateljima. Neće više tuđinci piti tvoga vina o kojem si teško radio.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (29, 62, 9, 'Neka ga jedu oni koji su ga želi i neka hvale Jahvu, neka ga piju oni što su ga trgali u predvorju mojega Svetišta!\"');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (29, 62, 10, 'Prođite, prođite kroz vrata, poravnajte put narodu! Nasipajte, nasipajte cestu, uklonite s nje kamenje. Podignite stijeg narodima!');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (29, 62, 11, 'Evo, Jahve oglasuje do nakraj zemlje: \"Recite kćeri sionskoj: Evo, dolazi tvoj spasitelj. Evo, s njim naplata njegova i njegova nagrada ispred njega!');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (29, 62, 12, 'Oni će se zvati \'Sveti narod\', \'Otkupljenici Jahvini\'. A tebe će zvati \'Traženi\' - \'Grad neostavljeni\'.\"');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (29, 63, 1, 'Tko je taj što dolazi iz Edoma, iz Bosre, u haljinama crvenim? Tko je taj što veličanstveno odjenut pun snage korača? - Ja sam to koji naučavam pravdu, velik kad spasavam!');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (29, 63, 2, '- Zašto je crvena tvoja haljina i odijelo kao u onog koji gazi u kaci?');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (29, 63, 3, '- U kaci sam sam gazio, od narodÄa nikog ne bijaše. U gnjevu ih svom izgazih i zgnječih u svojoj jarosti. Krv mi njihova poprska haljine, iskaljah svu odjeću svoju.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (29, 63, 4, 'Jer dan osvete bijaše mi u srcu, došla je godina mojeg otkupljenja.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (29, 63, 5, 'Ogledah se, al\' ne bješe pomoćnika! Začudih se, al\' ne bješe potpore. Tada mi je moja mišica pomogla i moja me srdžba poduprla.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (29, 63, 6, 'U gnjevu svom satrijeh narode, u bijesu sve ih izgazih i zemlju polih krvlju njihovom!');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (29, 63, 7, 'Slavit ću ljubav Jahvinu, slavna djela njegova - za sve što nam Jahve učini, za veliku dobrotu domu Izraelovu što nam je iskaza u svojoj samilosti, u obilju svoje ljubavi.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (29, 63, 8, 'Reče: \"Dosta, oni su narod moj, sinovi koji se neće iznevjeriti!\" I on im posta Spasiteljem u svim njihovim tjeskobama.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (29, 63, 9, 'Nije slao poslanika ni anđela nego ih je sam spasio. U svojoj ljubavi i samilosti sam ih je otkupio, podigao ih i nosio u sve dane od davnine.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (29, 63, 10, 'Ali se oni odmetnuše, ožalostiše sveti Duh njegov. Zato im je postao neprijatelj i sam je na njih zavojštio.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (29, 63, 11, 'Spomenuše se tad davnih dana i sluge njegova Mojsija: \"Gdje li je onaj koji izvuče iz vode pastira stada svojega? Gdje je onaj koji udahnu u njega Duh svoj sveti?');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (29, 63, 12, 'Koji je Mojsijevu desnicu vodio veličanstveno svojom mišicom, koji vodu pred njima razdvoji i steče sebi ime vječno;');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (29, 63, 13, 'koji ih provede dnom bezdana kao konja po pustinji i nisu se spoticali?');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (29, 63, 14, 'Poput stoke što silazi u dolinu, Duh Jahvin vodio ih počivalištu. Tako si ti vodio narod svoj i slavno ime sebi stekao.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (29, 63, 15, 'Pogledaj s nebesa i vidi iz prebivališta svoga svetog i slavnog. Gdje li je ljubomora tvoja i snaga? Zar se susteglo ganuće tvog srca i samilost tvoja prema meni? Ah, sućuti nam svoje ne ustegni,');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (29, 63, 16, 'jer Otac si naš! Abraham nas ne poznaje i ne spominje nas se Izrael; Jahve, ti si naš Otac, Otkupitelj naš - ime ti je oduvijek.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (29, 63, 17, 'Zašto, o Jahve, zašto nas puštaš da lutamo daleko od tvojih putova, zašto si dao da nam srce otvrdne da se tebe više ne bojimo? Vrati se, radi slugu svojih i radi plemenÄa što su tvoja baština!');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (29, 63, 18, 'Zašto bezbožnici gaze tvoje Svetište, a neprijatelji naši blate tvoju svetinju?');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (29, 63, 19, 'Odavna postadosmo kao oni kojima više ne vladaš i koji tvoje ime više ne nose. O, da razdreš nebesa i siđeš, da ime svoje objaviš neprijateljima: pred licem tvojim tresla bi se brda, pred tobom bi drhtali narodi,');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (29, 64, 1, 'kao kad oganj suho granje zapali i vatra vodu zakuha!');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (29, 64, 2, 'Čineć\' djela strahotna, neočekivana, silazio si i brda su se tresla pred tobom!');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (29, 64, 3, 'Odvijeka se čulo nije, uho nijedno nije slušalo, oko nijedno nije vidjelo, da bi koji bog, osim tebe, takvo što činio onima koji se uzdaju u njega.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (29, 64, 4, 'Pomažeš onima što pravdu čine radosno i tebe se spominju na putima tvojim; razgnjevismo te, griješismo, od tebe se odmetnusmo.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (29, 64, 5, 'Tako svi postasmo nečisti, a sva pravda naša k\'o haljine okaljane. Svi mi k\'o lišće otpadosmo i opačine naše k\'o vjetar nas odnose.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (29, 64, 6, 'Nikog nema da tvoje ime prizove, da se probudi i osloni o tebe. Jer lice si svoje od nas sakrio i predao nas u ruke zločinima našim.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (29, 64, 7, 'Pa ipak, naš si otac, o Jahve: mi smo glina, a ti si naš lončar - svi smo mi djelo ruku tvojih.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (29, 64, 8, 'Ne srdi se, Jahve, odveć žestoko, ne spominji se bez prestanka naše krivice. De pogledaj - tÓa svi smo mi narod tvoj!');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (29, 64, 9, 'Opustješe sveti gradovi tvoji, Sion pustinja posta, i pustoš Jeruzalem.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (29, 64, 10, 'Dom, svetinja naša i ponos naš, u kom te oci naši slavljahu, ognjem izgori i sve su nam dragocjenosti opljačkane.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (29, 64, 11, 'Zar ćeš se na sve to, Jahve, sustezati, zar ćeš šutjet\' i ponižavati nas odveć žestoko?');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (29, 65, 1, 'Potražiše me koji ne pitahu za me, nađoše me koji me ne tražahu; rekoh: \"Evo me! Evo me!\" narodu koji ne prizivaše ime moje.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (29, 65, 2, 'Svagda sam pružao ruku narodu odmetničkom, koji hodi putem zlim, za mislima svojim,');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (29, 65, 3, 'narodu koji me bez prestanka u lice srdi: žrtvuju po vrtovima, kad prinose na opekama,');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (29, 65, 4, 'na grobovima stanuju i noće na skrovitim mjestima, jedu svinjetinu, meću u zdjele jela nečista.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (29, 65, 5, 'I još govore: \"Ukloni se! Ne prilazi mi da te ne posvetim.\" Oni su mi dim u nosu, oganj što gori povazdan.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (29, 65, 6, 'Evo, sve je napisano preda mnom: neću ušutjet\' dok im ne platim, dok im ne platim u njedra,');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (29, 65, 7, 'za bezakonja vaša i vaših otaca, sva zajedno - govori Jahve. Koji su prinosili kad na gorama i pogrđivali me na brežuljcima - izmjerit ću im u krilo plaću za djela prijašnja.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (29, 65, 8, 'Ovako govori Jahve: \"Kao što o soku u grozdu vele: \'Ne uništavajte ga, u njemu je blagoslov!\' tako ću učiniti i ja radi slugu svojih, neću sve uništiti.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (29, 65, 9, 'Izvest ću iz Jakova potomstvo, a iz Jude baštinika gora svojih; baštinit će ih odabranici moji, i moje će se sluge ondje naseliti.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (29, 65, 10, 'Šaron će postati pašnjak ovcama, a nizina akorska počivalište govedima - narodu mojem koji mene traži.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (29, 65, 11, 'A vi koji ste Jahvu ostavili, koji ste zaboravili Svetu goru moju, koji pripremate stol Gadu, koji Meniju naljev lijevate,');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (29, 65, 12, 'za mač sam vas odredio - past ćete ničice da vas kolju. Jer zvao sam vas, a vi se niste odazvali, govorio sam, a vi niste slušali, nego ste činili što je zlo u očima mojim, izabirali ste što mi nije po volji.\"');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (29, 65, 13, 'Stog ovako Jahve Gospod govori: \"Evo, sluge će moje jesti, a vi ćete gladovati. Evo, sluge će moje piti, a vi ćete žeđati. Evo, sluge će se moje veseliti, a vi ćete se stidjeti.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (29, 65, 14, 'Evo, sluge će se moje radovati od sreće u srcu, a vi ćete vikati od boli u srcu i kukati duše slomljene!');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (29, 65, 15, 'Ime ćete svoje ostaviti za kletvu mojim izabranicima: \'Tako te ubio Jahve!\' A sluge svoje on će zvati drugim imenom.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (29, 65, 16, 'Tko se u zemlji bude blagoslivljao, nek\' se blagoslivlje Bogom vjernim. I tko se u zemlji bude kleo, nek\' se kune Bogom vjernim. Jer prijašnje će nevolje biti zaboravljene, od očiju mojih bit će sakrivene.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (29, 65, 17, 'Jer, evo, ja stvaram nova nebesa i novu zemlju. Prijašnje se više neće spominjati niti će vam na um dolaziti.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (29, 65, 18, 'Veselite se i dovijeka kličite zbog onoga što ja stvaram; jer, evo, od Jeruzalema stvaram klicanje, od naroda njegova radost.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (29, 65, 19, 'I klicat ću nad Jeruzalemom, radovat\' se nad svojim narodom. U njemu više neće čuti ni plača ni vapaja.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (29, 65, 20, 'U njemu više neće biti novorođenčeta koje živi malo dana ni starca koji ne bi godina svojih navršio: najmlađi će umrijet\' kao stogodišnjak, a tko ne doživi stotinu godina prokletim će se smatrati.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (29, 65, 21, 'Gradit će kuće i stanovat\' u njima, saditi vinograde i uživati rod njihov.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (29, 65, 22, 'Neće se više graditi da drugi stanuju ni saditi da drugi uživa: vijek naroda moga bit će k\'o vijek drveta, izabranici moji dugo će uživati plodove ruku svojih.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (29, 65, 23, 'Neće se zalud mučiti i neće rađati za smrt preranu, jer će oni s potomcima svojim biti rod blagoslovljenika Jahvinih.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (29, 65, 24, 'Prije nego me zazovu, ja ću im se odazvat\'; još će govoriti, a ja ću ih već uslišiti.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (29, 65, 25, 'Vuk i jagnje zajedno će pasti, lav će jesti slamu k\'o govedo; al\' će se zmija prahom hraniti. Nitko neće činiti zla ni štete na svoj Svetoj gori mojoj\" - govori Jahve.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (29, 66, 1, 'Ovako govori Jahve: \"Nebesa su moje prijestolje, a zemlja podnožje nogama! Kakvu kuću da mi sagradite i gdje da bude mjesto mog prebivališta?');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (29, 66, 2, 'TÓa sve je moja ruka načinila i sve je moje\" - riječ je Jahvina. \"Ali na koga svoj pogled svraćam? Na siromaha i čovjeka duha ponizna koji od moje riječi dršće.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (29, 66, 3, 'Ima ih koji kolju bika, ali i ljude ubijaju; žrtvuju ovcu, ali i psu vrat lome. Netko prinosi žrtvu, ali i krv svinjsku; prinose kad, ali časte i kipove. Kao što oni izabraše svoje putove i duši im se mile gnusobe njihove,');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (29, 66, 4, 'tako ću i ja izabrati za njih nevolje nesmiljene, pustit ću na njih ono čega se plaše. Jer zvao sam, a nitko se ne odazva, govorio sam, a nitko ne posluša, nego su činili što je zlo u očima mojim, izabrali ono što mi nije po volji.\"');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (29, 66, 5, 'Poslušajte riječ Jahvinu, vi koji od njegove riječi dršćete. \"Govore braća vaša koja na vas mrze i odbacuju vas radi moga imena: \'Neka se proslavi Jahve, pa da radost vašu vidimo.\' Ali oni će biti postiđeni.\"');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (29, 66, 6, 'Čuj! Buka iz grada, glas iz Hrama! Glas je to Jahve koji uzvraća svojim neprijateljima.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (29, 66, 7, 'Prije neg\' bolove oćutje, eto je rodila. Prije neg\' trudove osjeti, porodi dječaka.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (29, 66, 8, 'Tko je takvo što čuo, tko je takvo što vidio? Može li se zemlja u jednom danu napučiti? Može li se narod odjednom roditi? A tek što je osjetila trudove, Sionka rodi sinove!');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (29, 66, 9, '\"Zar bih ja otvorio krilo materino a da ono ne rodi?\" - govori Jahve. \"Zar bih ja, koji dajem rađanje, zatvorio maternicu?\" - kaže Bog tvoj.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (29, 66, 10, 'Veselite se s Jeruzalemom, kličite zbog njega svi koji ga ljubite! Radujte se, radujte s njime svi koji ste nad njim tugovali!');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (29, 66, 11, 'Nadojite se i nasitite na dojkama utjehe njegove da se nasišete i nasladite na grudima krepčine njegove.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (29, 66, 12, 'Jer ovako govori Jahve: \"Evo, mir ću na njih kao rijeku svratiti i kao potok nabujali bogatstvo naroda. Dojenčad ću njegovu na rukama nositi i milovati na koljenima.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (29, 66, 13, 'Kao što mati tješi sina, tako ću i ja vas utješiti - utješit ćete se u Jeruzalemu.\"');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (29, 66, 14, 'Kad to vidite, srce će vam se radovati i procvast će vam kosti k\'o mlada trava. Očitovat će se ruka Jahvina na njegovim slugama i gnjev nad neprijateljima njegovim.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (29, 66, 15, 'Jer, evo, dolazi Jahve s ognjem - bojna su mu kola poput vihora - da u jarosti gnjev svoj iskali i prijetnje svoje u ognju žarkome.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (29, 66, 16, 'Da, sudit će Jahve ognjem i mačem svakom smrtniku: pobijenih Jahvinih mnoštvo će biti.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (29, 66, 17, 'Oni koji se posvećuju i čiste u vrtovima iza onog jednog u sredini, koji jedu svinjetinu, nečisto i miševe - svi će zajedno izginuti, riječ je Jahvina.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (29, 66, 18, 'Ja dobro poznajem njihova djela i namjere njihove. \"Dolazim da saberem sve puke i jezike, i oni će doći i vidjeti moju Slavu!');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (29, 66, 19, 'Postavit ću im znak i poslat ću preživjele od njih k narodima u Taršiš, Put, Lud, Mošek, Roš, Tubal i Javan - k dalekim otocima koji nisu čuli glasa o meni ni vidjeli moje Slave - i oni će naviještati Slavu moju narodima.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (29, 66, 20, 'I dovest će svu vašu braću između svih naroda kao prinos Jahvi - na konjima, na bojnim kolima, nosilima, na mazgama i jednogrbim devama - na Svetu goru svoju u Jeruzalemu\" - govori Jahve - \"kao što sinovi Izraelovi prinose prinos u čistim posudama u Domu Jahvinu.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (29, 66, 21, 'I uzet ću sebi između njih svećenike, levite\" - govori Jahve.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (29, 66, 22, '\"Jer, kao što će nova nebesa i zemlja nova, koju ću stvoriti, trajati preda mnom\" - riječ je Jahvina - \"tako će vam ime i potomstvo trajati.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (29, 66, 23, 'Od mlađaka do mlađaka, od subote do subote, dolazit će svi ljudi da se poklone pred licem mojim\" - govori Jahve.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (29, 66, 24, 'Izlazeći, gledat ću trupla ljudi koji se od mene odmetnuše: crv njihov neće umrijeti i njihov se oganj neće ugasiti - bit će na gadost svim ljudima.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (30, 1, 1, 'Riječi Jeremije, sina Hilkijina, svećenika iz Anatota, u zemlji Benjaminovoj.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (30, 1, 2, 'Njemu dođe riječ Jahvina, u dane Jošije, sina Amonova, kralja Judina, trinaeste godine vladanja njegova:');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (30, 1, 3, 'zatim u dane Jojakima, sina Jošijina, kralja Judina, do svršetka jedanaeste godine Sidkije, sina Jošijina, kralja Judeje sve do Jeruzalema, u petom mjesecu izgnanstva.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (30, 1, 4, 'Dođe mi riječ Jahvina:');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (30, 1, 5, '\"Prije nego što te oblikovah u majčinoj utrobi, ja te znadoh; prije nego što iz krila majčina izađe, ja te posvetih, za proroka svim narodima postavih te.\"');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (30, 1, 6, 'A ja rekoh: \"Ah, Gospode Jahve, gle, ja ne umijem govoriti: dijete sam.\"');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (30, 1, 7, 'A Jahve mi odvrati: \"Ne govori: \'Dijete sam!\' Već idi k onima kojima te šaljem i reci sve ono što ću ti narediti.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (30, 1, 8, 'Ne boj ih se: jer ja sam s tobom da te izbavim,\" riječ je Jahvina.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (30, 1, 9, 'I tada Jahve pruži ruku, dotače se usta mojih i reče: \"Evo, u usta tvoja stavljam riječi svoje.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (30, 1, 10, 'Gle: postavljam te danas nad narode i kraljevstva, da istrebljuješ i rušiš, da zatireš i ništiš, da gradiš i sadiš.\"');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (30, 1, 11, 'I dođe mi riječ Jahvina: \"Što vidiš, Jeremija?\" A ja ću: \"Vidim granu bademovu.\"');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (30, 1, 12, 'Tada mi Jahve reče: \"Dobro vidiš, jer ja bdim nad riječima svojim da ih ispunim!\"');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (30, 1, 13, 'I dođe mi riječ Jahvina: \"Što vidiš?\" A ja ću: \"Vidim uzavrio lonac, a otvor mu gleda na sjever.\"');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (30, 1, 14, 'I Jahve mi reče: \"Sa sjevera buknut će zlo protiv svih stanovnika ove zemlje.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (30, 1, 15, 'Jer evo, ja ću sazvati sva sjeverna kraljevstva\" - riječ je Jahvina. \"I ona će doći: svako će od njih staviti svoje prijestolje pred ulaz vrata Jeruzalema, protiv svih zidina njegovih, i protiv svih gradova judejskih.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (30, 1, 16, 'I sudit ću im za sve opačine njihove; zato što me ostaviše, zato što kadiše drugim bogovima i klanjahu se djelima ruku svojih.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (30, 1, 17, 'Ti bedra svoja sad opaši, ustaj, pa ćeš im govoriti sve što ću tebi zapovjediti. Ne dršći pred njima, da ne bih morao učiniti da uzdršćeš pred njima.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (30, 1, 18, 'Danas te, evo, postavljam kao grad utvrđeni, kao stup željezni, k\'o zidinu brončanu protiv sve zemlje: protiv kraljeva i knezova judejskih, svećenika i naroda ove zemlje.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (30, 1, 19, 'I borit će se s tobom, al\' te neće nadvladati, jer ja sam s tobom da te izbavim,\" riječ je Jahvina.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (30, 2, 1, 'I dođe mi riječ Jahvina:');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (30, 2, 2, '\"Idi i viči u uši Jeruzalemu: Ovako govori Jahve: Spominjem se mladosti tvoje privržene, ljubavi tvoje vjereničke: ti pođe za mnom u pustinju, po zemlji gdje se ne sije.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (30, 2, 3, 'Izrael bijaše Jahvi svetinja, prvina plodova njegovih; tko god od njih jeđaše, bijaše kažnjen; zlo ga snađe\" - riječ je Jahvina.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (30, 2, 4, '\"Čujte riječ Jahvinu, dome Jakovljev, i svi rodovi doma Izraelova.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (30, 2, 5, 'Ovako govori Jahve: \'Kakvu nepravdu nađoše oci vaši na meni te se udaljiše od mene? Za ispraznošću pođoše, te sami isprazni postadoše.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (30, 2, 6, 'Ne pitahu: Gdje je Jahve koji nas izvede iz zemlje egipatske te nas vođaše kroz pustinju, po zemlji pustoj, jedva prohodnoj, po zemlji suhoj i mračnoj, po zemlji kojom nitko ne prolazi, nit\' se tko nastanjuje?\'');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (30, 2, 7, 'U zemlju vinograda i maslinika ja vas dovedoh, da se hranite plodom i dobrotom njezinom. Ali tek što uđoste, zemlju moju oskvrnuste i baštinu moju u gnusobu pretvoriste.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (30, 2, 8, 'Svećenici ne govorahu: \'Gdje je Jahve?\' Tumači Zakona mene ne upoznaše, pastiri otpadoše od mene, a proroci prorokovahu u ime Baalovo i iđahu za onima što im pomoći ne mogoše.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (30, 2, 9, 'Zato ću još parnicu voditi s vama - riječ je Jahvina - i parbit ću se sa sinovima sinova vaših.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (30, 2, 10, 'Pođite, dakle, na otoke kitimske, da vidite, ili u Kedar pošljite izvidnice te dobro promislite i provjerite je li se igda što slično zbilo.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (30, 2, 11, 'Je li koji narod mijenjao bogove - oni čak i nisu bogovi! A narod moj Slavu svoju zamijeni za one što ne pomažu!');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (30, 2, 12, 'Zapanjite se nad tim, nebesa, zgranite se i zaprepastite,\" riječ je Jahvina.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (30, 2, 13, '\"Jer dva zla narod moj učini: ostavi mene, Izvor vode žive, te iskopa sebi kladence, kladence ispucane što vode držati ne mogu.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (30, 2, 14, 'Je li Izrael rob il\' sluga u kući rođen? Zašto plijenom posta?');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (30, 2, 15, 'Lavovi su na nj rikali, podizali glas svoj. U pustoš pretvoriše zemlju njegovu, gradove popališe, nema im žitelja.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (30, 2, 16, 'Čak i oni iz Memfisa i Tafnisa brijahu ti tjeme.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (30, 2, 17, 'Nisi li to sam sebi učinio otpavši od Jahve, Boga svojega?');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (30, 2, 18, 'A sad, zašto krećeš u Egipat da piješ vode iz Nila? Zašto krećeš u Asiriju da piješ vode iz Rijeke?');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (30, 2, 19, 'Opačina te tvoja kažnjava, otpadništvo te tvoje osuđuje. Shvati i vidi kako je teško i gorko što ostavi Jahvu, Boga svojega, što više nema straha mog u tebi\" - riječ je Gospoda Jahve nad Vojskama.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (30, 2, 20, '\"Da, odavna ti slomi jaram svoj, raskide veze što te vezahu i reče: \'Neću da robujem.\' Pa ipak, na svakom povišem humu, pod svakim drvetom zelenim lijegao si k\'o bludnica.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (30, 2, 21, 'A ja te zasadih kao lozu izabranu, k\'o sadnicu plemenitu. Kako li mi se samo prometnu u jalov izrod, u lozu divlju!');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (30, 2, 22, 'Da se i lužinom opereš, napravljenom od mnogo pepela, ostat će mrlja bezakonja tvoga preda mnom\" - riječ je Jahve Gospoda.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (30, 2, 23, '\"Kako samo možeš reći: \'Nisam se uprljala, za baalima nisam trčala.\' Pogledaj tragove svoje u Dolini, upoznaj što si učinila. Deva brza što krstari stazama svojim,');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (30, 2, 24, 'magarica divlja navikla na pustinju, u pohoti svojoj požudno dašće, tko da je ukroti u vrijeme gonjenja? Tko god je traži, neće se umoriti, naći će je u mjesecu njezinu.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (30, 2, 25, 'Čuvaj se da ti noga ne obosi, grlo se ne osuši. A ti kažeš: \'Ne, uzalud je! Jer volim strance, i za njima ću ići.\'');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (30, 2, 26, 'Kao što se lupež zastidi kad ga uhvate, tako će se zastidjeti sinovi - dom Izraelov, oni, kraljevi, knezovi, svećenici i proroci njihovi');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (30, 2, 27, 'koji govore drvetu: \'Ti si otac moj!\' a kamenu: \'Ti si me rodio!\' jer mi leđa okreću, a ne lice, ali u nevolji svojoj zapomažu: \'Ustani, spasi nas!\'');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (30, 2, 28, 'Gdje su bogovi što ih ti sam načini? Nek\' ustanu ako te mogu spasiti u nevolji tvojoj! Jer imaš, o Judejo, bogova koliko i gradova! Koliko Jeruzalem ima ulica, toliko Baal ima žrtvenika.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (30, 2, 29, 'Zašto hoćete da se sa mnom parbite? Svi se od mene odmetnuste\" - riječ je Jahvina.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (30, 2, 30, '\"Zaludu sam udarao sinove vaše: vi iz toga ne uzeste pouke: mačevi vaši rastrgaše vaše proroke kao lav zatornik.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (30, 2, 31, 'Kakva li ste roda? Čujte riječ Jahvinu: Zar bijah pustinja Izraelu, il\' zemlja mračna? Zašto moj narod govori: \'Slobodu hoćemo, nećemo više k tebi!\'');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (30, 2, 32, 'Zaboravlja li djevica svoj nakit il\' nevjesta pojas svoj? A narod moj mene zaboravi, bezbroj je tomu već dana.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (30, 2, 33, 'O, kako li dobro znaš svoj put kad tragaš za ljubavlju! Zato si i na zlo putove svoje navikla.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (30, 2, 34, 'Čak su i ruke tvoje omašćene krvlju siromaha nevinih: nisi ih zatekla kako provaljuju vrata tvoja. Da, za sve njih ti ćeš odgovarati.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (30, 2, 35, 'A govoriš: \'Nevina sam, gnjev se njegov odvratio od mene.\' Evo me da ti sudim jer govoriš: \'Nisam zgriješila.\'');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (30, 2, 36, 'Kako si jadna u zabludjelosti svojoj! I Egipćani će te posramiti kao što te posramiše Asirci.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (30, 2, 37, 'I odavde ćeš morati otići s rukama nad glavom svojom, jer Jahve odbaci one u koje se uzdaš; ti nećeš biti sretna s njima.\"');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (30, 3, 1, '\"Ako muž otpusti ženu svoju i ona ide od njega te se uda za drugoga, ima li još pravo da se vrati njemu? Nije li ta žena sasvim oskvrnuta? A ti si bludničila s mnogim milosnicima, pa da se meni vratiš?\" - riječ je Jahvina.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (30, 3, 2, 'Podigni oči na goleti i pogledaj: gdje te to nisu oskvrnuli? Na putovima si ih dočekivala kao Arapin u pustinji. Ti si oskvrnula zemlju bludom i opačinom svojom,');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (30, 3, 3, 'zato i kiše prestadoše i kasni daždevi ne padoše. Čelo ti je kao u bludnice: ni zacrvenjela se nisi.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (30, 3, 4, 'Ne dovikuješ li mi sada: \'Oče moj, ti si prijatelj mladosti moje!');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (30, 3, 5, 'Hoće li zauvijek plamtjeti, vječno tinjati gnjev tvoj?\' Tako govoriš, a činiš i dalje zla koliko god možeš.\"');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (30, 3, 6, 'Jahve mi reče u dane kralja Jošije: \"Vidje li što učini odmetnica Izrael? Ona odlazi na svaku visoku goru i pod svako zeleno stablo i ondje se podaje bludu.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (30, 3, 7, 'A ja mišljah: \'Poslije svega što učini vratit će se k meni.\' Ali se ona ne vraća. I to vidje sestra njena, nevjernica Judeja.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (30, 3, 8, 'A vidje i kako otpustih odmetnicu Izraela zbog svih preljuba i dadoh joj knjigu otpusnu. Ali sestra joj, nevjernica Judeja, nimalo se ne poboja, pa i ona okrenu u blud.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (30, 3, 9, 'I svojim lakoumnim bludom obeščasti zemlju; činila je preljub s kamenjem i drvljem.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (30, 3, 10, 'I nakon svega toga nije se vratila k meni nevjernica sestra njezina, Judeja, svim srcem svojim, već samo prijetvorno\" - riječ je Jahvina.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (30, 3, 11, 'I reče mi Jahve: \"Odmetnica Izrael pravednija je od Judeje nevjernice.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (30, 3, 12, 'Idi i viči prema Sjeveru ove riječi. Reci: Vrati se, odmetnice, Izraele, riječ je Jahvina. Ne gnjevi se više lice moje na vas, jer sam milostiv - riječ je Jahvina - neću se gnjeviti dovijeka.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (30, 3, 13, 'Samo priznaj svoju krivnju da si se odvrgla od Jahve, Boga svojega, i odlutala k tuđincima, pod svako drvo zeleno i nisi slušala glasa mojega - riječ je Jahvina.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (30, 3, 14, 'Vratite se, sinovi odmetnici - riječ je Jahvina - jer ja sam vaš Gospodar. Uzet ću vas, po jednoga iz svakoga grada, po dvojicu od svakoga roda, da vas odvedem na Sion.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (30, 3, 15, 'I dat ću vam pastire po srcu svojemu koji će vas pasti razumno i mudro.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (30, 3, 16, 'A kad se u one dane namnožite i narodite u zemlji - riječ je Jahvina - više se neće govoriti: \'Kovčeg Jahvina Saveza\' i nitko neće na nj misliti, nitko ga se neće sjećati ni za njim čeznuti, niti ga ponovo graditi.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (30, 3, 17, 'U to će se vrijeme Jeruzalem zvati \'Prijestolje Gospodnje\'; i svi će se narodi u njemu sabrati u ime Jahvino, i nijedan se više neće tvrdoglavo povoditi za pokvarenim srcem svojim.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (30, 3, 18, 'U one dane slagat će se dom Judin s domom Izraelovim; i zajedno će krenuti iz Zemlje sjeverne u zemlju koju ocima vašim dadoh u baštinu.\"');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (30, 3, 19, 'A ja rekoh: \"Kako da te ubrojim među sinove i dam ti zemlju slasti, baštinu, najljepši biser među narodima! Pomislih: Ti ćeš me zvati \'Oče moj!\' i nećeš se više odvratiti od mene.\"');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (30, 3, 20, '\"Ali kao što se žena iznevjeri mužu svome, tako se i vi iznevjeriste meni, dome Izraelov\" - riječ je Jahvina.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (30, 3, 21, 'Čuj! Po goletima plač se čuje, zapomaganje djece Izraelove, jer skrenuše s puta svojega. Jahvu, Boga svoga, zaboraviše.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (30, 3, 22, '- Vratite se, sinovi, što se odvratiste, izliječit ću odmetništva vaša! - Evo nas, dolazimo k tebi, jer ti si Jahve, Bog naš!');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (30, 3, 23, 'Doista, prijevarni su visovi, graja po brdima. Odista, u Jahvi, Bogu našemu, spasenje je Izraelovo!');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (30, 3, 24, 'Baal je proždro trud naših otaca još od mladosti naše: ovce njihove i goveda, nihove kćeri i sinove.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (30, 3, 25, 'Lezimo u sramotu svoju, nek\' nas pokrije ruglo naše! Jer Jahvi, Bogu svome, sagriješismo mi i oci naši, od mladosti svoje do dana današnjeg, i ne slušamo glasa Jahve, Boga svojega.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (30, 4, 1, '\"Ako se, Izraele, želiš vratiti - riječ je Jahvina - k meni se vrati; ukloniš li grozote svoje, više ne moraš bježati od mene.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (30, 4, 2, 'Ako se zakuneš: \'Živoga mi Jahve!\' istinito, pravo i pravedno, narodi će se blagoslivljati u tebi i tobom se dičiti.\"');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (30, 4, 3, 'Jer ovako govori Jahve Judejcima i Jeruzalemcima: \"Prokrčite sebi prljuše, ne sijte po trnjacima.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (30, 4, 4, 'Obrežite se Jahvi, skinite obrezak sa srca svojega, Judejci i Jeruzalemci, jer će bijes moj buknuti kao vatra i gorjet će, a nikog da ugasi, zbog zlodjela i opačina što ih počiniste.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (30, 4, 5, 'Objavite u Judeji, razglasite u Jeruzalemu! Trubite u rog širom zemlje, vičite punim glasom i recite: \'Svi na okup! Zavucimo se u gradove svoje utvrđene!\'');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (30, 4, 6, 'Dižite znak prema Sionu! Bježite! Nemojte zastajati! Jer dovodim nesreću sa Sjevera, veliku propast.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (30, 4, 7, 'Lav se podiže iz čestara svoga, zatornik naroda izađe iz svog mjesta, krenu da zemlju tvoju opustoši: gradove će tvoje razoriti, nestat će im žitelja.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (30, 4, 8, 'Zato se u kostrijet ogrnite, kukajte, naričite, jer rasplamtjela jarost Jahvina nas nije mimoišla.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (30, 4, 9, 'U dan onaj - riječ je Jahvina - klonut će srce kralju i knezovima. Svećenici će se zapanjiti, proroci umuknuti.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (30, 4, 10, 'I reći će: \'Ah, Jahve, Gospodine, zaista nas teško prevari kad reče: \'Uživat ćete mir\' a sad nam je mač pod grlom.\'');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (30, 4, 11, 'U to će se vrijeme reći narodu ovom i Jeruzalemu: Vruć vjetar s pustinjskih sipina puše prema kćeri naroda moga; ali ne da hladi i da pročisti!');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (30, 4, 12, 'Doći će mi vjetar pun prijetnje, i ja ću im tada izreći sud!');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (30, 4, 13, 'Gle: diže se k\'o oblačine, kola mu slična vihoru, konji brži od orlova. Jao nama! Propadosmo!');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (30, 4, 14, 'Operi opačinu sa srca svoga, Jeruzaleme, da bi se spasio. Dokle će se u grudima tvojim misli zločinačke gnijezditi?');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (30, 4, 15, 'Jer glas naviješta od Dana, s gore Efrajimove najavljuje nesreću.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (30, 4, 16, 'Opomenite, razglasite po Judeji, obznanite Jeruzalemu: neprijatelji dolaze iz daleke zemlje i poklike izvikuju protiv gradova judejskih;');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (30, 4, 17, 'poput čuvara poljskih okružuju Jeruzalem, jer se odmetnu od mene\" - riječ je Jahvina.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (30, 4, 18, 'Put tvoj i djela tvoja to ti učiniše. To je tvoja nesreća! Kako je gorka, kako li pogađa u srce!');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (30, 4, 19, 'Utrobo moja! Utrobo moja, bolujem, srce mi se razdire! Dršće mi duša! Ne mogu šutjeti, jer čujem glas roga, poklike bojne.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (30, 4, 20, 'Javljaju slom za slomom, sva je zemlja poharana, moji su šatori iznenada opustošeni, u tren oka sva skloništa moja uništena.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (30, 4, 21, 'Dokle ću gledati bojne znakove, slušati pozive roga?');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (30, 4, 22, 'Da, bezuman je moj narod, ne poznaju me, djeca su oni nerazumna, ništa ne shvaćaju, mudri su tek za zlodjela, al\' činiti dobro ne umiju.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (30, 4, 23, 'Gledam zemlju: pusta je, evo, i prazna, nebesa: svjetlost im iščezla.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (30, 4, 24, 'Gledam brda: gle, tresu se, a svi se humci uzdrmali.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (30, 4, 25, 'Gledam: evo čovjeka nema, ptice nebeske sve su odletjele.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (30, 4, 26, 'Gledam: plodno polje, evo, opustje, sve gradove razori Jahve žestinom gnjeva svoga.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (30, 4, 27, 'Da, ovako govori Jahve: \"Sva će zemlja biti poharana, ja ću joj zadati posljednji udarac.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (30, 4, 28, 'Na to će se zemlja u crno zaviti, a nebesa, gore, potamnjeti. Jer rekoh, i neću se raskajati, odlučih i neću odustati.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (30, 4, 29, 'Pred vikom \'Konjanici i strijelci!\' sva se zemlja u bijeg dade: bježe u šipražje, penju se na hridi: svi su gradovi napušteni: nigdje više žive duše.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (30, 4, 30, 'A ti, opustošena, što ćeš učiniti? Da se i grimizom zaodjeneš, nakitom zlatnim ukrasiš i oči ličilom izraniš, uzalud se uljepšavaš! Ljubavnici tvoji tebe preziru: traže glavu tvoju.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (30, 4, 31, 'Da, jauk kao u bolesnice čujem, vrisak kao u one što prvi put rađa; čuj, to kći sionska jeca i pruža ruke: \'Jao meni! Duša mi zamire pod udarcima ubojica!\'');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (30, 5, 1, 'Prođite ulicama jeruzalemskim, pogledajte dobro i raspitajte se, tražite po njegovim trgovima, pa ako nađete ijednoga čovjeka koji čini pravo i traži istinu, oprostit ću ovom gradu\" - riječ je Jahvina.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (30, 5, 2, 'Pa kad i govore: \"Živoga mi Jahve!\" doista se krivo zaklinju.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (30, 5, 3, 'Jahve, nisu li oči tvoje upravljene k istini? Biješ ih, ali njih ne boli; zatireš ih, al\' oni odbijaju pouku tvoju. Čelo im je tvrđe od litice, odbijaju da se obrate.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (30, 5, 4, 'Rekoh: \"Samo siromasi tako ludo postupaju, jer ne znaju puta Jahvina ni pravo Boga svojega.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (30, 5, 5, 'Poći ću, dakle, velikima i njima ću govoriti, jer oni poznaju put Jahvin i pravo Boga svojega.\" Ali oni svi složno razbiše jaram i sve veze pokidaše.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (30, 5, 6, 'I zato ih šumski lav napada, vuk pustinjski razdire, leopardi vrebaju gradove njihove, tko god iziđe iz njih bit će rastrgan. Jer su grijesi njihovi mnogobrojni, mnogostruki otpadi njihovi.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (30, 5, 7, '\"Zašto da ti oprostim? Sinovi me tvoji napustiše, zaklinju se lažnim bogovima. Ja ih nasitih, oni preljub učiniše, u bludničinu kuću nagrnuše.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (30, 5, 8, 'Oni su k\'o ugojeni, sileni konji: ržu za ženom bližnjega svoga.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (30, 5, 9, 'Pa da to ne kaznim - riječ je Jahvina - narodu takvu da se ne osvetim?');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (30, 5, 10, 'Popnite se na zidove! Razarajte! Uništite, ali ne posvema! Iščupajte sve čokote jer nisu Jahvini.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (30, 5, 11, 'Da, podlo me izdadoše dom Izraelov i dom Judin\" - riječ je Jahvina.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (30, 5, 12, 'Zanijekaše Jahvu, rekoše: \"Nema ga! Zlo nas neće snaći, nećemo iskusiti ni gladi ni mača!');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (30, 5, 13, '[13a] A proroci su poput vjetra, govornika nema među njima!\"');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (30, 5, 14, 'Zato ovako govori Jahve, Bog nad Vojskama: \"Zato što su tako govorili, [13b] evo što će im se zbiti: U oganj ću pretvoriti svoje riječi u tvojim ustima, a narod ovaj u drvo da ga oganj proždre.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (30, 5, 15, 'Evo, dovest ću na vas narod izdaleka, dome Izraelov - riječ je Jahvina. Narod nepobjediv, narod drevan, narod kojega jezik nećeš znati, ni razumjeti što govori.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (30, 5, 16, 'Tobolac mu je razjapljen grob. Svi su oni po izboru junaci.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (30, 5, 17, 'On će proždrijet\' tvoju žetvu, tvoj kruh, sinove i kćeri tvoje, ovce i goveda tvoja, grožđe i smokve tvoje, razorit će ti gradove tvrde u koje se sada uzdaš.\"');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (30, 5, 18, '\"Ali ni tada - riječ je Jahvina - neću te posve uništiti.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (30, 5, 19, 'A kad budu pitali: \'Zašto nam Jahve, Bog naš, učini sve ovo?\' ti ćeš im odgovoriti: \'Jer ste mene ostavili da biste služili tuđim bogovima u svojoj zemlji, služit ćete tuđincu u zemlji koja nije vaša!\'\"');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (30, 5, 20, '\"Objavite ovo domu Jakovljevu i obznanite po Judeji:');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (30, 5, 21, 'Čujte, dakle, ovo, narode ludi i nerazumni: oči imaju, a ne vide, uši imaju, a ne čuju!');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (30, 5, 22, 'Zar se mene nećete bojati - riječ je Jahvina - zar nećete drhtati preda mnom koji sam stavio pijesak moru za granicu, za vječnu među koje nikad neće prijeći: ono se biba, al\' je nemoćno, valovi mu huče, ali prijeći neće.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (30, 5, 23, 'No, u naroda ovog srce je prkosno, nepokorno; oni se udaljiše - to je snaga njihova!');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (30, 5, 24, 'Ne rekoše u srcu svome: \'Bojmo se Jahve, Boga svojega, koji nam u pravi čas šalje dažd rani i kišu kasnu i koji nam čuva tjedne određene za žetvu.\'');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (30, 5, 25, 'Vaša bezakonja narušiše ovo, vaši vam grijesi uništiše blagostanje.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (30, 5, 26, 'Da, u mome narodu ima zlikovaca: kao ptičari vrebaju iz zasjede, postavljaju zamke, hvataju ljude.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (30, 5, 27, 'Kao što je krletka puna ptica, tako su njihove kuće pune grabeža; postadoše tako veliki i bogati,');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (30, 5, 28, 'tusti i ugojeni. Da, prevršila se mjera zla, ne brane prava, prava sirote ne sreću, ne mare za pravo sirotinje.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (30, 5, 29, 'Pa da to ne kaznim - riječ je Jahvina - narodu takvu da se ne osvetim?');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (30, 5, 30, 'Strahote i grozote zbivaju se u ovoj zemlji:');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (30, 5, 31, 'proroci laž proriču, a svećenici poučavaju na svoju ruku. A mojem narodu to omilje! Al\' što ćete raditi na kraju?');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (30, 6, 1, 'Bježite, sinovi Benjaminovi, isred Jeruzalema! U Tekoi zatrubite u rog, na Bet Hakeremu podignite bojni stijeg! Jer sa Sjevera se nadvija nesreća, propast velika.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (30, 6, 2, 'Može li se Kći sionska usporedit\' s nježnom tratinom?');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (30, 6, 3, 'K njoj dolaze pastiri sa stadima. Svud oko nje razapeše šatore, svaki pase na dijelu svome.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (30, 6, 4, 'S njome zametnite sveti boj! Na noge! Navalimo usred dana! Jao nama, jer se dan naginje k zapadu, a večernje sjene duljaju!');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (30, 6, 5, 'Na noge! Navalimo usred noći, razrušimo dvore njene!\"');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (30, 6, 6, 'Jer ovako zbori Jahve nad Vojskama: \"Oborite stabla njena, podignite nasip oko Jeruzalema, to je grad laži, u njemu je sve samo tlačenje.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (30, 6, 7, 'Kao što iz studenca izvire voda, tako iz njega opačina izvire. U njemu se čuje samo nasilje i pustošenje, preda mnom su svagda bolesti i rane.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (30, 6, 8, 'Popravi se, Jeruzaleme, da mi se duša od tebe ne odvrati, da te ne pretvorim u pustoš, u zemlju nenastanjenu.\"');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (30, 6, 9, 'Ovako govori Jahve nad Vojskama: \"Paljetkuj, paljetkuj kao lozu Ostatak Izraelov! Poput berača pruži ruke među čokote!\"');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (30, 6, 10, 'Komu treba da govorim, koga da opomenem da me saslušaju? Gle, uho im je neobrezano stog ne mogu čuti. Gle, riječ Jahvina postade im porugom, nije im mila.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (30, 6, 11, 'Prepun sam gnjeva Jahvina, ne mogu više izdržati! - Izlij ga, dakle, po djeci na ulici i na skupove mladića. Sve će ih obuzeti: muža i ženu, starca i čovjeka zrele dobi.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (30, 6, 12, 'Njihove će kuće pripasti drugima, a tako i polja i žene im. \"Da, ispružit ću ruku svoju - govori Jahve - na stanovnike ove zemlje,');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (30, 6, 13, 'jer od najmanjega do najvećeg svi gramze za plijenom, od proroka do svećenika svi su varalice.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (30, 6, 14, 'I olako liječe ranu naroda moga, vičući: \'Mir! Mir!\' Ali mira nema.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (30, 6, 15, 'Nek\' se postide što gnusobu počiniše, no oni više ne znaju što je stid, ne umiju se više crvenjeti. I zato će popadati s onima što padaju, srušit će se kad stanem kažnjavati\" - govori Jahve.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (30, 6, 16, 'Ovako govori Jahve: \"Stanite na negdašnje putove, raspitajte se za iskonske staze: Koji put vodi k dobru? Njime pođite i naći ćete spokoj dušama svojim! Al\' oni rekoše: \'Ne idemo!\'');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (30, 6, 17, 'I postavih im stražare: \'Pazite na glas roga!\' Al\' oni rekoše: \'Nećemo paziti!\'');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (30, 6, 18, 'Zato čujte, narodi, i vi pastiri stada njihovih!');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (30, 6, 19, 'Čuj, zemljo! Gle, dovodim zlo na ovaj narod, plod njihove pobune, jer oni ne slušahu riječi moje, Zakon moj odbaciše.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (30, 6, 20, 'Što će mi tamjan koji dolazi iz Šebe i trska mirisna iz zemlje daleke? Vaše mi paljenice nisu drage, nisu mi po volji klanice vaše.\"');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (30, 6, 21, 'Zato ovako govori Jahve: \"Evo postavljam narodu ovome prepreke o koje će se spotaći, oci i djeca zajedno, poginut će susjed zajedno s prijateljem.\"');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (30, 6, 22, 'Ovako govori Jahve: \"Evo dolazi narod iz zemlje sjeverne, puk velik diže se s krajeva zemlje:');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (30, 6, 23, 'u ruci im luk i koplje, okrutni su, nemilosrdni; graja im buči kao more, jašu na konjima, kao jedan za boj spremni protiv tebe, Kćeri sionska.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (30, 6, 24, 'Kad saznasmo novost, ruke nam klonuše, strava nas obuze, bol kao porodilju.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (30, 6, 25, 'Ne izlazite u polja, ne idite na putove, jer mačevi dušmanski prijete, užas sve uokolo.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (30, 6, 26, 'Kćeri mog naroda, kostrijet pripaši, pospi se pepelom, nariči k\'o za jedincem tužaljku pregorku. Jer će doći nenadano na nas pustošnik.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (30, 6, 27, 'Postavih te za ispitivača naroda mojeg da spoznaš i ispitaš putove njegove.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (30, 6, 28, 'Svi su oni odmetnici najgori, okolo kleveću i mjed i željezo, svi su pokvareni.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (30, 6, 29, 'Mijeh sopće da bi vatra proždrla olovo, zalud se ljevač trudi da ga rastopi: šljaka se ne da izlučiti.\"');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (30, 6, 30, '\"Srebro odbačeno\", tako ih zovu, jer ih Jahve odbaci!');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (30, 7, 1, 'Ovo je riječ što dođe Jeremiji od Gospodina:');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (30, 7, 2, '\"Stani pred vrata Doma Jahvina, objavi ondje ovu riječ. Reci: Čujte riječ Jahvinu, svi Judejci koji ulazite na ova vrata da se poklonite Jahvi.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (30, 7, 3, 'Ovako govori Jahve nad Vojskama, Bog Izraelov: \'Popravite svoje putove i djela svoja, pa ću boraviti s vama na ovome mjestu.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (30, 7, 4, 'Ne uzdajte se u lažne riječi: \'Svetište Jahvino! Svetište Jahvino! Svetište Jahvino!\'');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (30, 7, 5, 'Ali ako zaista popravite svoje putove i djela svoja i ako zaista budete činili što je pravo, svatko prema bližnjemu svome,');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (30, 7, 6, 'ako ne budete tlačili stranca, sirote i udovice i ne budete prolijevali krvi nedužne na ovome mjestu, ako ne budete trčali za tuđim bogovima na svoju nesreću -');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (30, 7, 7, 'boravit ću s vama na ovome mjestu, u zemlji koju sam dao vašim ocima zauvijek.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (30, 7, 8, 'Ali se vi uzdate u lažne i beskorisne riječi!');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (30, 7, 9, 'Zar da kradete, ubijate, činite preljub, krivo se zaklinjete, palite tamjan Baalu i trčite za tuđim bogovima kojih ne poznajete,');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (30, 7, 10, 'a onda da dolazite i stojite preda mnom u Domu ovome koji nosi moje ime i govorite: \'Spašeni smo!\' i da nakon toga opet činite nedjela i opačine?');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (30, 7, 11, 'Zar je Dom ovaj, koji se zove mojim imenom, u vašim očima pećina razbojnička? Ali ja dobro vidim\" - riječ je Jahvina.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (30, 7, 12, '\"Pođite, dakle, na moje mjesto koje je u Šilu, gdje nekoć nastanih ime svoje, i pogledajte što od njega učinih zbog opačina naroda svoga izraelskoga.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (30, 7, 13, 'Kako činite sva ona ista nedjela - riječ je Jahvina - i premda vas neumorno opominjem, vi ne slušate, a kad vas zovem, vi se ne odazivate:');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (30, 7, 14, 'od ovoga Doma što se zove mojim imenom, u koje se vi uzdate, i od ovoga mjesta što ga dadoh vama i ocima vašim učinit ću isto što sam učinio i od Šila.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (30, 7, 15, 'Odbacit ću vas od lica svojega kao što odbacih svu braću vašu, sve potomstvo Efrajimovo.\"');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (30, 7, 16, '\"A ti ne moli milosti za narod ovaj, ne diži glasa za njih i ne moli, ne navaljuj na me jer te neću uslišiti.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (30, 7, 17, 'Ne vidiš li što čine po gradovima judejskim i po ulicama jeruzalemskim?');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (30, 7, 18, 'Djeca kupe drva, oci pale vatru, žene mijese tijesto da ispeku kolače \'kraljici neba\' i lijevaju ljevanice tuđim bogovima da me pogrde.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (30, 7, 19, 'Zar mene tim pogrđuju - riječ je Jahvina - a ne sebe na svoju sramotu?\"');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (30, 7, 20, 'I stoga ovako govori Jahve Gospod: \"Evo, gnjev svoj i jarost svoju izlit ću na ovo mjesto, na ljude i na stoku, na poljsko drveće i na plodove zemlje, rasplamtjet će se i neće se ugasiti.\"');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (30, 7, 21, 'Ovako govori Jahve nad Vojskama, Bog Izraelov: \"Paljenicama dometnite još i klanice, i jedite meso.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (30, 7, 22, 'Ja ništa ne rekoh ocima vašim o paljenicama i klanicama, niti im što o tom zapovjedih kad ih izvedoh iz zemlje egipatske.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (30, 7, 23, 'Ovo im ja zapovjedih: \'Slušajte glas moj, pa ću ja biti vaš Bog, a vi ćete biti moj narod. Idite putem kojim vam zapovjedih, da vam dobro bude.\'');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (30, 7, 24, 'A oni ne poslušaše, uho svoje ne prignuše, već pođoše po savjetu i okorjelosti zloga srca svojega; okrenuše mi leđa, a ne lice.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (30, 7, 25, 'Od dana kad oci vaši iziđoše iz zemlje egipatske pa do dana današnjeg slao sam vam tolike sluge svoje, proroke, iz dana u dan, neumorno.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (30, 7, 26, 'Ali me oni nisu slušali, uho svoje nisu prignuli, nego otvrdnuše, gori od otaca svojih.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (30, 7, 27, 'Možeš im sve to reći, ali te neće poslušati; zovi ih, neće ti se odazvati.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (30, 7, 28, 'Zato im reci: \'Ovo je narod koji ne sluša glasa Jahve, Boga svojega, i ne prima opomenÄe. Nestade istine, nestade je iz usta njihovih.\'\"');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (30, 7, 29, 'Ostriži svoju dugu kosu, baci je. Po goletima protuži tužaljkom, jer Jahve odbaci i odvrgnu rod na koji se razgnjevio.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (30, 7, 30, '\"Da, sinovi Judini čine što je zlo u očima mojim\" - riječ je Jahvina. \"Postaviše grozote u Dom koji se mojim zove imenom, da ga oskvrnu;');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (30, 7, 31, 'podigoše uzvišice tofetske u Dolini Ben Hinomu i spaljuju vatrom svoje sinove i kćeri - što im ja nikad ne zapovjedih niti mi to ikada na um pade.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (30, 7, 32, 'Stoga evo dolaze dani - riječ je Jahvina - kad se više neće reći Tofet ni Dolina Ben Hinom, nego Dolina klanja. U Tofetu će se pokapati mrtvi, jer drugdje neće biti mjesta.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (30, 7, 33, 'A mrtva tijela ovoga naroda bit će hrana pticama nebeskim i zvjeradi zemaljskoj, i nitko se neće naći da ih poplaši i otjera.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (30, 7, 34, 'Uklonit ću iz gradova judejskih i s ulica jeruzalemskih radost i veselje: jer će se zemlja ta pretvoriti u pustinju.\"');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (30, 8, 1, '\"U ono vrijeme - riječ je Jahvina - povadit će iz grobova kosti kraljeva judejskih, kosti knezova njezinih, kosti svećenika, kosti proroka i kosti žitelja jeruzalemskih.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (30, 8, 2, 'I razasut će ih prema suncu, prema mjesecu i prema svoj vojsci nebeskoj, koje ljubljahu, kojima služahu, koje slijeđahu, koje za savjet pitahu i kojima se klanjahu. I neće ih pokupiti i sahraniti; ostat će kao gnoj po zemlji.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (30, 8, 3, 'Tada će svima onima što preostanu od tih zlih plemena, po svim mjestima kuda ih rasprših, smrt biti milija od života\" - riječ je Jahve nad Vojskama.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (30, 8, 4, '\"Reci im: Ovako govori Jahve: \'Padne li tko, neće li opet ustati, zaluta li, neće li se opet vratiti?');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (30, 8, 5, 'Zašto onda taj narod luta uporno i neprekidno? Čvrsto se drže laži, neće da se obrate.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (30, 8, 6, 'Pazio sam i osluškivao: Ne govore kako valja. Nitko se ne kaje zbog pakosti svoje, i ne govori \'Što učinih?\' Svatko je skrenuo trku svoju kao konj kad u boj nagne.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (30, 8, 7, 'Čak i roda pod nebom zna svoje vrijeme, grlica, lastavica i ždral drže se vremena kad se moraju vratiti. A moj narod ne poznaje suda Jahvina.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (30, 8, 8, 'Kako možete tvrditi: \'Mi smo mudri, u nas je Zakon Jahvin!\' Zaista, u laž ga je pretvorila lažljiva pisaljka pisara!');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (30, 8, 9, 'Mudraci će biti osramoćeni, prestravljeni i uhvaćeni u zamku. Gle, oni prezreše riječ Jahvinu! A njihova mudrost - što im koristi?');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (30, 8, 10, 'Zato ću žene njihove dati strancima, a vaša polja osvajačima. Jer od najmanjeg do najvećega svi gramze za plijenom, od proroka do svećenika svi su varalice.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (30, 8, 11, 'I olako liječe ranu naroda mojega vičući: \'Mir! Mir!\' Ali mira nema.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (30, 8, 12, 'Neka se postide što gnusobu počiniše, no oni više ne znaju što je stid, ne umiju se više crvenjeti. Zato će popadati s onima što padaju, srušit će se kad stanem kažnjavati\" - govori Jahve.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (30, 8, 13, '\"Htjedoh u berbu k njima - riječ je Jahvina - a ono ni grozda na trsu, ni smokve na smokvi; čak je i lišće uvelo. Zato ih predah onima što prolaze kraj njih.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (30, 8, 14, '\'Zašto još čekamo? Na okup! Zavucimo se u tvrde gradove da ondje izginemo, jer nas Jahve, Bog naš, zatire, napaja nas vodom otrovanom, jer zgriješismo protiv Jahve.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (30, 8, 15, 'Nadasmo se miru, ali dobra nema, čekasmo vrijeme ozdravljenja, al\' evo užasa!');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (30, 8, 16, 'Iz Dana dopire njištanje konja njegovih, od rzanja njegovih pastuha dršće zemlja sva. Dolaze da proždru zemlju i što je napunja, grad i žitelje u njemu.\'');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (30, 8, 17, 'I gle, puštam na vas otrovnice protiv kojih nema čarolija; ujedat će vas - riječ je Jahvina -');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (30, 8, 18, 'lijeka biti neće.\" Bol me spopada, srce mi iznemoglo.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (30, 8, 19, 'Evo zapomažu kćeri naroda moga iz zemlje daleke: \"Zar Jahve nije više na Sionu? Kralj njegov? Zašto me razjariše svojim kipovima, ništavilima tuđinskim?');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (30, 8, 20, 'Žetva prođe, minu ljeto, a mi nismo spašeni!\"');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (30, 8, 21, 'Satrven sam što je kći naroda mojega satrvena, žalostan sam, stravom obuzet.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (30, 8, 22, 'Zar u Gileadu nema balzama? Nema li ondje liječnika? TÓa zašto ne dolazi ozdravljenje kćeri naroda mojega?');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (30, 8, 23, 'O, tko bi glavu moju pretvorio u vrelo, a oči moje u vrutak suza, danju i noću da plačem nad poginulima kćeri svoje, naroda svojega!');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (30, 9, 1, '\"Da imam u pustinji obitavalište, ostavio bih narod svoj i daleko od njih otišao. Jer svi su oni preljubnici, rulja izdajnička.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (30, 9, 2, 'Kao luk napinju jezik, laž, a ne istina, prevladava na zemlji. Iz zla u zlo srljaju, mene ne poznaju\" - riječ je Jahvina!');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (30, 9, 3, '\"Nek se svatko čuva prijatelja, a brat bratu neka ne vjeruje, jer brat svaki nasljeduje Jakova, a svaki prijatelj raznosi klevete.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (30, 9, 4, 'Jedan drugoga varaju, istine ne govore, privikoše jezik da govori laži; izopačeni, ne mogu se više');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (30, 9, 5, 'vratiti. Nasilje na nasilje! Prijevara za prijevarom! Neće da spoznaju mene\" - riječ je Jahvina.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (30, 9, 6, 'Stog ovako govori Jahve nad Vojskama: \"Evo, pretopit ću ih i ispitati, tÓa kako da i postupaju prema kćeri naroda moga?');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (30, 9, 7, 'Jezik im je strijela ubojita, na ustima riječ prijevarna. \'Mir s tobom\', pozdravljaju bližnjega, ali mu u srcu zamku spremaju.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (30, 9, 8, 'Pa da ih zbog toga ne kaznim - riječ je Jahvina - narodu takvu da se ne osvetim?\"');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (30, 9, 9, '\"Zaplačite, tugujte nad brdima, nad ispašama pustinjskim naričite! Jer izgorješe, nitko ne prolazi, glas stada više se ne čuje. Od ptice nebeske do stoke sve pobježe, svega nestade.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (30, 9, 10, 'Od Jeruzalema učinit ću gomilu kamenja, brlog čagaljski, gradove judejske pretvorit ću u pustoš gdje nitko ne stanuje.\"');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (30, 9, 11, 'Tko je mudar da bi to razumio, kome su usta Jahvina govorila da objavi zašto zemlja izgorje kao pustinja i nitko njome više ne prolazi?');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (30, 9, 12, 'I reče Jahve: \"Jer ostaviše Zakon moj koji im dadoh i jer ne slušahu glasa mojega, niti ga slijeđahu,');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (30, 9, 13, 'nego slijeđahu okorjelo srce svoje i baale kojima ih oci njihovi naučiše,');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (30, 9, 14, 'ovako govori Jahve nad Vojskama, Bog Izraelov: Evo, nahranit ću narod ovaj pelinom i napojiti ga vodom zatrovanom.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (30, 9, 15, 'I raspršit ću ih među narode kojih ne poznavahu oni ni oci njihovi. A za njima ću poslati mač da ih zatre.\" Ovako govori Jahve nad Vojskama:');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (30, 9, 16, '\"Pazite! Pozovite narikače! Neka dođu! Pošaljite po najvještije! Neka dođu!');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (30, 9, 17, 'Neka pohite da zapjevaju tužbalicu nad nama! Da suze poteku iz očiju naših, da voda poteče s trepavica naših!');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (30, 9, 18, 'Sa Siona dopire tužbalica: \'O, kako smo upropašteni, osramoćeni veoma! Jer moramo zemlju ostaviti i stanove svoje napustiti.\'\"');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (30, 9, 19, 'I zato, o žene, čujte riječ Jahvinu, i neka uho vaše primi riječ iz usta njegovih. Učite kćeri svoje jadati, jedna drugu naricati:');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (30, 9, 20, '\"Smrt se ušulja kroz prozore naše, uđe u dvore naše, djecu pokosi nasred ulice, mladiće nasred trgova.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (30, 9, 21, 'I mrtva tjelesa leže kao gnoj po oranicama, kao snoplje za žeteocem, a nikoga da ih skupi.\"');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (30, 9, 22, 'Ovako govori Jahve: \"Mudri neka se ne hvale mudrošću, ni junak neka se ne hvali hrabrošću, ni bogati neka se ne hvali bogatstvom.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (30, 9, 23, 'A tko se hvaliti hoće, neka se hvali time što ima mudrost da mene spozna. Jer ja sam Jahve koji tvori dobrotu, pravo i pravdu na zemlji, jer to mi je milo\" - riječ je Jahvina.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (30, 9, 24, '\"Evo, bliže se dani\" - riječ je Jahvina - \"kaznit ću sve koji su obrezani na tijelu:');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (30, 9, 25, 'Egipat, Judeju, Edom, sinove Amonove i Moab i sve one što briju zaliske i prebivaju u pustinji. Jer svi su ti narodi neobrezani i sav dom Izraelov neobrezana je srca!\"');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (30, 10, 1, 'Slušajte riječ koju vam govori Jahve, dome Izraelov.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (30, 10, 2, 'Ovako govori Jahve: \"Ne privikavajte se putu bezbožnom i ne dršćite pred znacima nebeskim, jer pred njima dršću samo bezbošci.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (30, 10, 3, 'Jer su strašila tih naroda puka ništavnost, samo drvo posječeno u šumi, djelo ruku tesarovih,');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (30, 10, 4, 'ukrašeno srebrom i zlatom, pričvršćeno čavlima i čekićima da se ne klima.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (30, 10, 5, 'Nalik su na ptičja strašila u vrtu: ne znaju govoriti. Treba ih nositi, jer ne umiju hodati. Njih se ne bojte, jer ne mogu zla činiti, ali ni dobra učiniti ne mogu.\"');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (30, 10, 6, 'Nitko nije kao ti, Jahve, ti si velik i silno je ime tvoje.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (30, 10, 7, 'Tko da se tebe ne boji, kralju naroda? Zaista, tebi to pripada, jer među svim mudracima naroda i u svim njihovim kraljevstvima tebi nema ravna!');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (30, 10, 8, 'Čime vatru lože, to ih zaluđuje! Zakon im isprazan - obično drvo,');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (30, 10, 9, 'tankolisto srebro dovezeno iz Taršiša, zlato iz Ofira, rad kipara i rukotvorina zlatara, sva djela umješna, ogrnuta ljubičastim i crvenim grimizom.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (30, 10, 10, 'A Jahve je pravi Bog. Živi je on Bog i Kralj vječni. Od njegova gnjeva zemlja se trese. Narodi ne mogu podnijeti jarosti njegove.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (30, 10, 11, 'Evo što ćete o kipovima reći: \"Bogovi koji nisu stvorili neba ni zemlje moraju nestati s lica zemlje i ispod neba.\"');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (30, 10, 12, 'On stvori zemlju snagom svojom, mudrošću svojom uspostavi krug zemaljski i umom svojim razape nebesa.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (30, 10, 13, 'Kad mu glas zaori, huče vode na nebesima, oblake diže s kraja zemlje; stvara kiši munje, vjetar izvodi iz skrovišta njegovih.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (30, 10, 14, 'Svakom čovjeku pamet stane, svaki se zlatar zastidi svoga kipa, jer svi su mu kipovi samo varka, nema u njima duha!');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (30, 10, 15, 'Isprazni su oni, smiješne tvorevine, propast će u dan kazne.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (30, 10, 16, '\'Jakovljev dio\' nije kao oni: jer je on sve stvorio, Izrael pleme je baštine njegove, Jahve nad Vojskama ime je njegovo.\"');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (30, 10, 17, 'Skupi prnje svoje sa zemlje, ti koja stanuješ u utvrdi!');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (30, 10, 18, 'Jer ovako govori Gospod: \"Gle, ovaj put daleko ću odbaciti stanovnike ove zemlje, pritijesniti ih da me nađu.\"');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (30, 10, 19, '\"Jao meni zbog ozljede moje, rana je moja neiscjeljiva.\" A ja rekoh: \"Ipak, bolest je moja, nosit ću je!');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (30, 10, 20, 'Šator je moj obÄaljen, sva užeta pokidana. Djeca me ostaviše: nema ih. Nema ga tko bi opet razapeo šator moj i podigao krila šatorska.\"');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (30, 10, 21, 'Da, pastiri pamet izgubiše: ne tražiše Jahve. Zato ih sreća ne prati i sva se stada raspršiše.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (30, 10, 22, 'Čujte vijest! Primiče se, evo, buka strašna iz zemlje sjeverne, da gradove judejske pretvori u pustinju, u brlog čagalja.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (30, 10, 23, 'Znam, Jahve, da put čovjeka nije u njegovoj vlasti, da čovjek koji hodi ne može upravljati korake svoje!');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (30, 10, 24, 'Kazni me, Jahve, ali po pravici, ne u gnjevu, da nas ne zatreš.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (30, 10, 25, 'Izlij gnjev na narode koji te ne priznaju i na plemena koja ne zazivlju imena tvoga! Jer oni su proždrli Jakova, izjeli ga, opustošili naselje njegovo.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (30, 11, 1, 'Riječ koju je Jahve uputio Jeremiji:');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (30, 11, 2, '\"Govori Judejcima i Jeruzalemcima.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (30, 11, 3, 'Reci im: Ovako veli Jahve, Bog Izraelov: \'Proklet bio čovjek koji ne posluša riječi Saveza ovoga,');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (30, 11, 4, 'riječi koje sam zapovjedio ocima vašim kad sam ih izveo iz zemlje egipatske, iz one peći ražarene, govoreći: Poslušajte glas moj i činite sve što vam zapovjedim: tada ćete biti narod moj, a ja vaš Bog,');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (30, 11, 5, 'da bih ispunio zakletvu kojom sam se zakleo ocima vašim da ću im dati zemlju u kojoj teče mlijeko i med - kao što je danas.\'\" A ja odgovorih i rekoh: \"Tako je, Jahve.\"');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (30, 11, 6, 'I dalje mi reče Jahve: \"Objavi riječi ove po gradovima judejskim i po ulicama jeruzalemskim: \'Poslušajte riječi Saveza ovoga, te ih izvršavajte.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (30, 11, 7, 'Jer sam ozbiljno opominjao očeve vaše kad sam ih izvodio iz zemlje egipatske i do danas ih neumorno opominjem: Poslušajte glas moj!');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (30, 11, 8, 'Ali oni ne slušahu i ne prignuše uha svojega, nego se povedoše za okorjelošću zloga srca svoga. Zato dopustih da se na njima ispune sve riječi Saveza ovoga za koji im zapovjedih da ga se pridržavaju, ali ga se oni ne pridržavahu.\'\"');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (30, 11, 9, 'I reče mi Jahve: \"Zavjera je među Judejcima i Jeruzalemcima.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (30, 11, 10, 'Vratiše se bezakonjima svojih otaca koji se oglušiše na moje riječi, pa trčahu za tuđim bogovima da im služe. Dom Izraelov i dom Judin prekršiše Savez moj koji sam sklopio s ocima njihovim.\"');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (30, 11, 11, 'Zato ovako govori Jahve: \"Evo, dovest ću na njih zlo kojemu neće umaći; vapit će k meni, ali ih ja neću slušati.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (30, 11, 12, 'Onda neka gradovi judejski i žitelji jeruzalemski vapiju k bogovima kojima kade, ali im oni neće pomoći u vrijeme nevolje!');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (30, 11, 13, 'Jer imaš, o Judejo, bogova koliko i gradova! I koliko ima ulica u Jeruzalemu, toliko žrtvenika podigoste da kadite Baalu.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (30, 11, 14, 'Ti, dakle, ne moli milosti za taj narod, ne diži glasa za njih i ne moli, jer ih neću uslišiti kad me zazovu u nevolji svojoj.\"');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (30, 11, 15, 'Što li će draga moja u Domu mome? Kuje zle osnove. Hoće li pretilina i meso posvećeno ukloniti zlo od tebe? Mogu li te stoga proglasiti čistom?');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (30, 11, 16, '\"Zelena maslina lijepa uzrasta\", tako te Jahve nazva. A sada uz prasak veliki plamenom sažiže njeno lišće; spaljene su grane njene.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (30, 11, 17, 'Jahve nad Vojskama, koji te bijaše posadio, nesreću ti namijeni zbog zločina što ga učini dom Izraelov i dom Judin kadeći Baalu da bi mene razgnjevili.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (30, 11, 18, 'Jahve mi objavi te znam! Tada mi ti, Jahve, razotkri njihove spletke.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (30, 11, 19, 'A ja bijah kao jagnje krotko što ga vode na klanje i ne slutih da protiv mene snuju pakosne naume. \"Uništimo drvo još snažno, iskorijenimo ga iz zemlje živih, da mu se ime nikad više ne spominje!\"');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (30, 11, 20, 'Ali ti, Jahve nad Vojskama, koji pravedno sudiš, koji ispituješ srca i bubrege, daj da vidim kako se njima osvećuješ, jer tebi povjerih parnicu svoju.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (30, 11, 21, 'Zato Jahve nad Vojskama govori protiv ljudi u Anatotu koji mi rade o glavi i govore: \"Ne prorokuj više u ime Jahvino, da ne pogineš od ruke naše!\"');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (30, 11, 22, 'Ovako govori Jahve nad Vojskama: \"Evo, ja ću ih kazniti. Njihovi će mladići od mača poginuti, sinovi i kćeri pomrijet će od gladi.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (30, 11, 23, 'Ni ostatka neće ostati kad donesem nesreću ljudima u Anatotu u godini kazne njihove.\"');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (30, 12, 1, 'Prepravedan si, Jahve, da bih se mogao s tobom parbiti. Samo bih jedno s tobom raspravio: Zašto je put zlikovaca uspješan? Zašto podmuklice uživaju mir?');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (30, 12, 2, 'Ti si ih posadio, i oni se ukorijeniše, rastu i plod donose. Al\' si bliz samo ustima njihovim, a daleko im od srca.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (30, 12, 3, 'No ti, Jahve, mene poznaješ i vidiš; ispitao si srce moje, ono je s tobom. Odvedi ih kao jagnjad na klanje, sačuvaj ih za dan pokolja.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (30, 12, 4, 'Dokle će zemlja tugovati, dokle će trava na svem polju sahnuti? Zbog opačine njezinih stanovnika ugiba stoka i ptice! Jer govore: Bog ne vidi naših putova.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (30, 12, 5, 'Ako s pješacima trčeći sustaješ, kako ćeš se s konjima utrkivati? Kad ni u mirnoj zemlji nemaš uzdanja, kako ćeš onda kroz guštare jordanske?');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (30, 12, 6, 'Jer su i braća tvoja i obitelj tvoja licemjerni prema tebi! I oni te iza leđa ocrnjuju na sva usta. Ne vjeruj im kad ti zbore umilno.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (30, 12, 7, 'Ostavih dom svoj, napustih baštinu svoju; miljenicu srca svoga dadoh u ruke dušmana njenih.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (30, 12, 8, 'Baština moja postade za me kao lav u šumi. Zarikao je na me, zato ga zamrzih.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (30, 12, 9, 'Zar je baština moja šarena ptica oko koje odasvud druge slijeću? Hajde, skupite se, sve divlje zvijeri, dođite žderati.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (30, 12, 10, 'Mnogi pastiri opustošiše moj vinograd, zgaziše nasljedstvo moje; dragu mi baštinu pretvoriše u golu pustinju,');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (30, 12, 11, 'pretvoriše u pustoš, žalosna je pustoš preda mnom. Sva je zemlja pusta jer nikog u srce ne dira.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (30, 12, 12, 'Preko svih goleti pustinjskih nagrnuše pustošnici. Jer u Jahve je mač što proždire: s jednog kraja zemlje do drugog nema mira nijednome tijelu.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (30, 12, 13, 'Sijahu pšenicu, a požeše trnje: iscrpli se bez koristi. Stide se uroda svoga sve zbog jarosti Jahvine.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (30, 12, 14, 'Ovako govori Jahve: \"Sve zle susjede svoje, koji su dirnuli u baštinu što sam je dao narodu svome Izraelu, ja ću iščupati iz zemlje njihove. Ali dom Judin iščupat ću isred njih.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (30, 12, 15, 'A kad ih iščupam, ponovo ću im se smilovati i povesti natrag, svakoga na baštinu i zemlju njegovu.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (30, 12, 16, 'Pa ako doista nauče putove naroda mojega i stanu se zaklinjati imenom mojim - \'Živoga mi Jahve\' - kao što su učili moj narod da se zaklinje Baalom, tada će se opet nastaniti usred naroda moga.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (30, 12, 17, 'Ako pak ne poslušaju, onda ću takav narod potpuno iščupati i zatrti\" - riječ je Jahvina.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (30, 13, 1, 'Ovako mi govori Jahve: \"Idi i kupi sebi lanen pojas i opaši bokove. Ali ga u vodu ne umači.\"');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (30, 13, 2, 'I kupih pojas po riječi Jahvinoj i opasah bokove.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (30, 13, 3, 'I dođe mi drugi put riječ Jahvina:');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (30, 13, 4, '\"Uzmi pojas što si ga kupio i njime se opasao, digni se, idi do rijeke Eufrata i sakrij ga ondje u pukotinu pećine.\"');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (30, 13, 5, 'I odoh i sakrih ga kraj Eufrata, kako mi Jahve zapovjedi. Poslije mnogo dana reče mi Jahve:');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (30, 13, 6, '\"Ustaj, idi na Eufrat pa izvuci odande pojas za koji ti zapovjedih da ga ondje sakriješ.\"');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (30, 13, 7, 'Odoh na Eufrat, izvukoh i uzeh pojas s mjesta gdje ga bijah sakrio, i gle: pojas istrunuo, ne bijaše više nizašto.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (30, 13, 8, 'Tada mi dođe riječ Jahvina:');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (30, 13, 9, '\"Ovako govori Jahve: Tako ću uništiti silnu oholost Judeje i Jeruzalema.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (30, 13, 10, 'Narod taj opaki koji ne sluša mojih riječi, nego slijedi okorjelo srce svoje i trči za drugim bogovima da im služi i da im se klanja, postat će kao tvoj pojas koji nije više nizašto.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (30, 13, 11, 'Jer kao što pojas prianja uz bedra čovjekova, tako sam htio da sav dom Izraelov i sav dom Judin prianja uza me - riječ je Jahvina - da budu moj narod, moj dobar glas, moj ponos, moja slava i čast. Ali nisu poslušali!\"');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (30, 13, 12, 'Reci tom narodu: \"Svaki se vrč puni vinom.\" A oni će ti prigovoriti: \"Zar možda ne znamo da se svaki vrč puni vinom?\"');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (30, 13, 13, 'Reci im tada: \"Ovako govori Jahve: evo, napunit ću pijanošću sve stanovnike ove zemlje, kraljeve što sjede na prijestolju Davidovu, i svećenike, i proroke, i sve Jeruzalemce.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (30, 13, 14, 'I porazbijat ću ih jednog o drugoga, očeve zajedno sa sinovima - riječ je Jahvina. Uništit ću ih bez samilosti, bez milosrđa i bez smilovanja.\"');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (30, 13, 15, 'Poslušajte, dobro čujte, okanite se oholosti: Jahve sad govori!');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (30, 13, 16, 'Dajte slavu Jahvi, Bogu svojemu, prije nego što se smrkne, prije nego što se noge vaše spotaknu po planinama mračnim. Vi se nadate svjetlosti, a on će je u mrak pretvoriti, prometnuti u crnu tamu!');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (30, 13, 17, 'Ako ovo ne poslušate, potajno će mi duša plakati zbog oholosti vaše, suze će roniti, oko će mi suze prolijevati, jer Jahvino stado u izgnanstvo odlazi.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (30, 13, 18, 'Reci kralju i kraljici-majci: \"Sjednite duboko dolje, jer vijenac slave pade s vaših glava.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (30, 13, 19, 'Gradovi Negeba zatvoreni su, i nikoga nema da ih otvori. Sva je Judeja izgnana, sasvim izgnana!\"');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (30, 13, 20, 'Podigni oči, Jeruzaleme, i pogledaj one što nadiru sa Sjevera. Gdje je stado tebi povjereno, slavne ovce tvoje?');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (30, 13, 21, 'Što ćeš reći kada ti se nametnu kao gospodari tvoji oni koje si sam naučio da te kao ljubavnici vode. Neće li te bolovi spopasti kao porodilju?');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (30, 13, 22, 'Možda ćeš se tad upitati: \"Zašto me to snašlo?\" Zbog mnoštva bezakonja tvojih otkriše ti skute, nasilje nad tobom učiniše.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (30, 13, 23, 'Može li Etiopljanin promijeniti kožu svoju? Ili leopard krzno svoje? \"A vi, možete li činiti dobro, navikli da zlo činite?');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (30, 13, 24, 'Zato ću vas raspršiti k\'o pljevu koju raznosi pustinjski vjetar.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (30, 13, 25, 'To je sudba tvoja i dio tebi odmjeren - riječ je Jahvina - jer si mene zaboravio i u laž se uzdao.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (30, 13, 26, 'Sam ću ti halju do lica podići da se tvoja golotinja vidi.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (30, 13, 27, 'Sve preljube tvoje, tvoje vriskanje i bestidno tvoje bludničenje, na humcima, u poljima, vidio sam tvoje grozote. Jao tebi, Jeruzaleme! Još se ne očisti i dokle će to još trajati...?\"');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (30, 14, 1, 'Riječ Jahvina Jeremiji o velikoj suši:');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (30, 14, 2, 'Judeja je tugom obrvana i ginu njeni gradovi, sumorno leže na zemlji, krik Jeruzalema do neba se vije.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (30, 14, 3, 'Odličnici šalju sluge po vodu: dolaze do studenaca, ali vode ne nalaze, vraćaju se praznih vrčeva, postiđeni, posramljeni, pokriše glavu svoju.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (30, 14, 4, 'Zemlja je sva ispucala jer kiše nema. Ratari se postidješe, pokriše glave.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (30, 14, 5, 'Pa i košuta u polju ostavlja mlado jer trave nema.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (30, 14, 6, 'Divlji magarci, stojeć\' na goletima, dašću kao čagalj, oči im malaksale jer nema zelenila.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (30, 14, 7, 'Bezakonja naša protiv nas svjedoče, smiluj se, o Jahve, rad\' imena svoga! Jer otpadosmo od tebe, tebi sagriješismo,');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (30, 14, 8, 'o nado Izraelova, spasitelju njegov u danima nevolje! Zašto si kao stranac u ovoj zemlji, kao putnik što se uvrati da prenoći?');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (30, 14, 9, 'Zašto si kao prestravljen čovjek, kao junak koji ne može pomoći? TÓa ti si među nama, o Jahve, mi se tvojim zovemo imenom - nemoj nas ostaviti!');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (30, 14, 10, 'Ovako govori Jahve o narodu ovome: Jest, oni vole tumarati i ne štede svojih nogu, i zato ih Jahve ne voli. I sada se spominje bezakonja njihova i kažnjava grijehe njihove.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (30, 14, 11, 'I reče mi Jahve: \"Ne traži milosti za ovaj narod.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (30, 14, 12, 'Ako će i postiti, neću uslišiti njihovih vapaja. Ako će i prinijeti paljenicu i prinos, neće mi omiljeti. Jer mačem, glađu i kugom ja ću ih zatrti.\"');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (30, 14, 13, 'Tada rekoh: \"Ah, Jahve Gospode! Eno, proroci im govore: \'Nećete vidjeti mača, niti će vam biti gladi, nego ću vam dati postojan mir na ovome mjestu.\'\"');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (30, 14, 14, 'A Jahve mi reče: \"Laž prorokuju ti proroci u moje ime; niti ih poslah niti im nalog kakav dadoh - ja im i nisam govorio. Oni vam prorokuju lažna viđenja, isprazna gatanja i snove srca svoga.\"');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (30, 14, 15, 'Zato ovako govori Jahve: \"Proroci ti što u moje ime prorokuju, a ja ih nisam poslao, te govore da neće biti ni mača ni gladi u zemlji ovoj, sami će od mača i gladi poginuti.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (30, 14, 16, 'A narod ovaj kojemu prorokuju ležat će po ulicama jeruzalemskim, pokošen mačem i glađu, i neće biti čovjeka da ga pokopa - njih, žene njihove, sinove i kćeri njihove. Tako ću na njih izliti zloću njihovu.\"');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (30, 14, 17, 'A ti im reci ovako: Nek\' oči moje suze rone danju i noću, i neka ne prestanu, jer je strašno slomljena djevica, kći naroda moga, ranom neobično ljutom.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (30, 14, 18, 'Pođem li u polje, evo mačem pobijenih! Vratim li se u grad, evo od gladi iznemoglih! Čak i proroci i svećenici lutaju po zemlji i ništa ne znaju.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (30, 14, 19, 'TÓa zar si Judeju sasvim odbacio? Zar ti duši omrznu Sion? Zašto nas tako biješ te nam više nema lijeka? Nadasmo se miru, ali dobra nema, čekasmo vrijeme ozdravljenja, al\' evo užasa!');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (30, 14, 20, 'O Jahve, bezbožnost svoju priznajemo, bezakonje otaca svojih; doista, tebi sagriješismo!');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (30, 14, 21, 'Ne odbaci nas, rad\' imena svoga, ne sramoti prijesto Slave svoje, spomeni se i nemoj razvrći Saveza svog s nama!');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (30, 14, 22, 'Zar ispraznost bezbožnika dažda daje? Ili zar nebesa sama kiše? Zar ne daješ ti to, Jahve, Bože naš? Zato se u te uzdamo, jer ti sve to činiš.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (30, 15, 1, 'I reče mi Jahve: \"Kad bi i Mojsije i Samuel stali pred lice moje, ne bi mi se duša obratila narodu tome. Otjeraj ih ispred lice mojega, neka idu od mene!');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (30, 15, 2, 'Ako te upitaju: \'Kamo da idemo?\' odgovori im: \'Ovako govori Jahve: Tko je za smrt, u smrt! Tko je za mač, pod mač! Tko je za glad, u glad! Tko je za izgnanstvo, u izgnanstvo!\'');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (30, 15, 3, 'Poslat ću na njih četiri nevolje - riječ je Jahvina: mač da ih ubija, pse da ih rastrgaju, ptice nebeske i zvjerad da ih žderu i zatiru.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (30, 15, 4, 'I učinit ću ih užasom svim kraljevstvima zemaljskim, i to zbog Manašea, sina Ezekijina, kralja judejskoga - za sva zla što ih počini u Jeruzalemu.\"');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (30, 15, 5, '\"Tko da se smiluje tebi, Jeruzaleme, tko da te požali? Tko li će se svratit\' da te zapita kako ti je?');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (30, 15, 6, 'Ti me odbaci - riječ je Jahvina - i leđa mi okrenu. I zato na te digoh ruku zatornicu. Dojadi mi da ti uvijek praštam!');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (30, 15, 7, 'Zato ću ih izvijati vijačom na vratima zemlje ove. Narod svoj ću lišit\' djece i istrijebit\' ga, jer se ne obraćaju sa svojih putova.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (30, 15, 8, 'Bit će u njih više udovica negoli pijeska morskoga. Na majke mladih ratnika dovest ću zatornika, usred podneva, i pustit ću na njih iznenada užas i strahotu.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (30, 15, 9, 'Onesvijestila se roditeljka sedmero djece, dušu ispustila. Sunce joj zađe još za dana: postiđena, osramoćena je. A što od njih ostane, pod mač ću vrći pred njihovim dušmanima\" - riječ je Jahvina.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (30, 15, 10, 'Jao meni, majko, što si me rodila, da svađam se i prepirem sa svom zemljom. Nikom ne uzajmih, ni od koga zajma ne uzeh, a ipak svi me proklinju.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (30, 15, 11, 'Uistinu, o Jahve, nisam li ti služio za njihovo dobro, nisam li tražio milost u tebe za neprijatelja svoga, u doba nevolje, u danima tjeskobe njegove? Ti to dobro znaš!');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (30, 15, 12, 'Može l\' se željezo slomiti, željezo sa Sjevera i mjed?');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (30, 15, 13, 'Tvoje bogatstvo i blago tvoje pljački ću predati. Tako ćeš platiti za sva bezakonja svoja po svoj zemlji.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (30, 15, 14, 'Učinit ću te robljem neprijatelja u zemlji koju ne poznaješ, jer gnjev moj planu ognjem koji će vas sažgati, koji će protiv vas buknuti.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (30, 15, 15, 'Jahve, spomeni me se i pohodi me i kazni progonitelje moje. Ne daj da propadnem zbog sporosti srdžbe tvoje! Spomeni se da tebe radi podnosim sramotu.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (30, 15, 16, 'Kad mi dođoše riječi tvoje, ja sam ih gutao: riječi tvoje ushitiše i obradovaše srce moje. Jer sam se tvojim zvao imenom, o Jahve, Bože nad Vojskama.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (30, 15, 17, 'Nikad sjedio nisam u društvu veseljaka da se razveselim. Pod težinom ruke tvoje samotan živim, jer ti me jarošću prože.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (30, 15, 18, 'Zašto je bol moja bez prebola? Zašto je rana moja neiscjeljiva i nikako da zaraste? Ah! Hoćeš li meni biti kao potok nestalan, vodama nepouzdan?');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (30, 15, 19, 'Zato ovako govori Jahve: \"Ako se vratiš, pustit ću te da mi opet služiš; ako odvojiš dragocjeno od bezvrijedna, bit ćeš usta moja. Oni će se okrenuti k tebi, al\' ti se zato ne smiješ okrenuti k njima!');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (30, 15, 20, 'Učinit ću od tebe za ovaj narod zid od mjedi, neosvojiv. Borit će se protiv tebe, al\' te neće nadvladati, jer ja sam s tobom, da te spasim i izbavim\" - riječ je Jahvina.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (30, 15, 21, '\"Izbavit ću te iz ruku zlikovaca i otkupiti te iz ruku silnika.\"');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (30, 16, 1, 'I dođe mi riječ Jahvina i reče:');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (30, 16, 2, '\"Ne uzimaj sebi žene; i nemaj ni sinova ni kćeri na ovome mjestu.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (30, 16, 3, 'Jer ovako govori Jahve o kćerima i sinovima koji će se roditi na ovome mjestu i o majkama koje će ih rađati i o očevima koji će ih imati u ovoj zemlji:');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (30, 16, 4, 'Oni će umrijeti smrću prebolnom, nitko ih neće oplakivati, niti će ih sahraniti. Pretvorit će se u gnoj za oranice, izginut će od mača i gladi, a njihova će trupla biti hrana pticama nebeskim i zvijerima zemaljskim.\"');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (30, 16, 5, 'Da, ovako govori Jahve: \"Ne smiješ ući u kuću žalosti, ne idi naricati niti ih sažaljevati. Jer ja sam tom narodu uskratio mir svoj - riječ je Jahvina - ljubav i samilost.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (30, 16, 6, 'Pomrijet će veliko i malo u ovoj zemlji i nitko ih neće pokopati. Nitko neće naricati nad njima, niti će zbog njih praviti ureza, niti kose šišati.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (30, 16, 7, 'Za onog u žalosti neće kruh lomiti, da ga utješe zbog pokojnika, nitiće mu tko pružiti pehar utjehe zbog smrti njegova oca ili majke njegove.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (30, 16, 8, 'Ne ulazi u kuću slavlja da s njima sjediš i gostiš se.\"');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (30, 16, 9, 'Jer ovako govori Jahve nad Vojskama, Bog Izraelov: \"Evo, učinit ću da s ovog mjesta i pred vašim očima i u ovim danima iščeznu poklici radosti i veselja i glasovi zaručnika i zaručnice.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (30, 16, 10, 'A kad objaviš tom narodu sve ove riječi, pa te upitaju: \'Zašto nam Jahve zaprijeti svom ovom golemom nesrećom; u čemu je zločinstvo naše i u čemu su grijesi naši što ih počinismo protiv Jahve, Boga našega?\' -');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (30, 16, 11, 'onda im odgovori: \'U tom što me ostaviše oci vaši - riječ je Jahvina - i trčaše za tuđim bogovima da im služe i da im se klanjaju, a mene ostaviše i Zakona se moga ne držaše.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (30, 16, 12, 'A vi još gore učiniste nego oci vaši, jer evo, svaki se povodi za okorjelošću zloga srca svoga, a mene ne sluša.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (30, 16, 13, 'Zato ću vas istjerati iz ove zemlje u zemlju koja vam je neznana, kao što bijaše i ocima vašim. Ondje ćete služiti tuđim bogovima danju i noću: jer neću vam se više smilovati!\'\"');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (30, 16, 14, '\"Zato, evo, dolaze dani - riječ je Jahvina - kad se više neće govoriti: \'Živoga mi Jahve koji sinove Izraelove izvede iz Egipta\',');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (30, 16, 15, 'nego: \'Živoga mi Jahve koji sinove Izraelove izvede iz zemlje sjeverne i iz svih zemalja kamo ih bijaše prognao.\' Vratit ću ih u zemlju njihovu koju dadoh ocima njihovim.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (30, 16, 16, 'Evo, poslat ću mnoga ribara - riječ je Jahvina - koji će ih uloviti. A zatim ću dovesti mnoge lovce koji će ih goniti sa svih gora, i sa svih brežuljaka, i iz svih pećinskih rasjeklina.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (30, 16, 17, 'Jer moje oči prate sve njihove putove: neće mi izmaći, niti se bezakonje njihovo može sakriti od očiju mojih.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (30, 16, 18, 'Dvostruko ću naplatiti njihovo bezakonje i grijehe njihove, jer su truplima svojih grozota oskvrnuli moju zemlju i moju baštinu ispunili gnusobama.\"');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (30, 16, 19, 'Jahve, snago moja i moja utvrdo, utočište moje u danima nevolje! K tebi će doći narodi s krajeva zemlje. I govorit će: Samu nam laž oci namriješe, Ništavost i Nemoć.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (30, 16, 20, 'TÓa stvara li čovjek sam sebi bogove, to nikako nisu bogovi.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (30, 16, 21, 'Učinit ću, evo, da osjete, da ovaj put zaista oćute moju ruku i snagu moju, i znat će da mi je ime Jahve.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (30, 17, 1, 'Judin grijeh upisan je željeznom pisaljkom, urezan dijamantnim vrškom u pločicu njihova srca i u rogove njihovih žrtvenika,');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (30, 17, 2, 'kao spomen sinovima njihovim na žrtvenike njihove i ašere njihove oko zelenog drveća na visokim brežuljcima,');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (30, 17, 3, 'na brdima i usred polja. Tvoje bogatstvo i sve blago tvoje pljački ću predati. Tako ćeš platiti za grijeh svoj po svoj zemlji.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (30, 17, 4, 'Morat ćeš pustiti baštinu koju sam tebi poklonio. Učinit ću te robljem neprijatelja u zemlji koju ne poznaješ. Jer gnjev moj planu ognjem koji će vječno gorjeti.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (30, 17, 5, 'Ovako govori Jahve: \"Proklet čovjek koji se uzdaje u čovjeka, i slabo tijelo smatra svojom mišicom, i čije se srce od Jahve odvraća.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (30, 17, 6, 'Jer on je kao drač u pustinji: ne osjeća kad je sreća na domaku, tavori dane u usahloj pustinji, u zemlji slanoj, nenastanjenoj.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (30, 17, 7, 'Blagoslovljen čovjek koji se uzdaje u Jahvu i kome je Jahve uzdanje.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (30, 17, 8, 'Nalik je na stablo zasađeno uz vodu što korijenje pušta k potoku: ne mora se ničeg bojati kad dođe žega, na njemu uvijek zelenilo ostaje. U sušnoj godini brigu ne brine, ne prestaje donositi plod.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (30, 17, 9, 'Podmuklije od svega je srce. Jedva popravljivo, tko da ga pronikne?');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (30, 17, 10, 'Ja, Jahve, istražujem srca i ispitujem bubrege, da bih dao svakom po njegovu vladanju, prema plodu ruku njegovih.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (30, 17, 11, 'Prepelica što leži na jajima a ne leže jest onaj što nepravdom stječe bogatstvo: usred dana svojih ostavit\' ga mora i na kraju ostaje lÓuda.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (30, 17, 12, 'Slavan prijestol dignut od davnina, to je naše sveto mjesto.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (30, 17, 13, 'O Jahve, nado Izraela, svi koji te ostave postidjet će se, koji se odmetnu od tebe bit će u prah upisani, jer ostaviše Izvor žive vode.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (30, 17, 14, 'Iscijeli me, Jahve, i bit ću zdrav, spasi me, i bit ću spašen, jer ti si pjesma moja.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (30, 17, 15, 'Evo ih što mi govore: Gdje je riječ Jahvina? Neka se ispuni!');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (30, 17, 16, 'Ta ja se nisam vrzao oko tebe za njihovu nesreću niti sam želio kobni Dan! - ti to znaš, sve što je izlazilo iz usta mojih pred tobom je.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (30, 17, 17, 'Ne budi mi na užas, ti, utočište moje, u Dan nesretni.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (30, 17, 18, 'Progonitelji moji nek\' se postide, ne ja, njih smeti, ne mene. Na njih dovedi Dan nesretni, zatri ih dvogubim zatorom!');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (30, 17, 19, 'Ovako mi reče Jahve: \"Idi i stani na vrata Sinova naroda na koja ulaze i izlaze kraljevi judejski i na sva vrata jeruzalemska.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (30, 17, 20, 'Reci im: Čujte riječ Jahvinu, vi, kraljevi judejski i svi Judejci i Jeruzalemci koji prolazite kroz ova vrata.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (30, 17, 21, 'Ovako govori Jahve: \'Čuvajte se ako vam je život mio i ne nosite tereta u dan subotnji, i ne unosite ga na vrata jeruzalemska.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (30, 17, 22, 'I ne nosite bremena iz kuće u dan subotnji, i nikakva posla ne radite, nego svetkujte dan subotnji, kao što sam zapovjedio vašim ocima.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (30, 17, 23, 'Oni me ne poslušaše i ne prikloniše uha svojega, nego tvrdovrato ne poslušaše i ne prihvatiše nauka.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (30, 17, 24, 'A vi, ako me poslušate - riječ je Jahvina - i ako ne budete nosili bremena na vrata ovoga grada, nego budete svetkovali dan subotnji, ne radeći nikakva posla,');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (30, 17, 25, 'tada će na vrata ovoga grada ulaziti kraljevi koji sjede na prijestolju Davidovu, koji se voze kolima i jašu na konjima, oni i njihovi časnici, Judejci i Jeruzalemci, i ovaj će grad ostati dovijeka.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (30, 17, 26, 'I dolazit će iz gradova judejskih, iz okolice Jeruzalema, iz zemlje Benjaminove i iz Šefele, iz Gorja i iz Negeba, da prinesu paljenice, klanice, prinosnice i kad i da prinesu žrtvu zahvalnicu u Domu Jahvinu.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (30, 17, 27, 'Ali ako me ne poslušate te ne budete svetkovali dan subotnji, i ako budete nosili bremena ulazeći na vrata jeruzalemska u dan subotnji, tada ću potpaliti oganj na vratima njegovim: i plamen će proždrijeti dvore jeruzalemske, i neće se ugasiti.\'\"');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (30, 18, 1, 'Ovo je riječ koju Jahve uputi Jeremiji:');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (30, 18, 2, '\"Ustani i siđi u kuću lončarovu - ondje ću ti objaviti svoje riječi.\"');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (30, 18, 3, 'Siđoh, dakle, u kuću lončarovu, upravo je radio na lončarskom kolu.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (30, 18, 4, 'I kako bi se koji sud što bi ga načinio od ilovače u ruci lončarovoj pokvario, on bi opet od nje pravio drugi - već kako se lončaru svidjelo da napravi.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (30, 18, 5, 'I dođe mi riječ Jahvina:');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (30, 18, 6, '\"Ne mogu li i ja s vama činiti kao ovaj lončar, dome Izraelov? - riječ je Jahvina. Evo, kao ilovača u ruci lončarovoj, i vi ste u mojoj ruci, dome Izraelov.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (30, 18, 7, 'Objavim li jednom kojem narodu ili kojem kraljevstvu da ću ga iskorijeniti, uništiti i razoriti,');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (30, 18, 8, 'i taj se narod, protiv kojeg sam govorio, obrati od opačina i zloća, tada ću se ja pokajati za zlo koje mu bijah namijenio.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (30, 18, 9, 'Objavim li kojem narodu, ili kojem kraljevstvu, da ću ga izgraditi i posaditi,');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (30, 18, 10, 'a on stane činiti što je zlo u mojim očima, ne slušajući glasa mojega, pokajat ću se za dobro koje sam im obećao.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (30, 18, 11, 'Zato sada reci Judejcima i Jeruzalemcima: \'Ovako govori Jahve: Evo, spremam vam zlo i snujem protiv vas osnove. Vratite se, dakle, svaki sa svoga zlog puta i popravite svoje putove i svoja djela.\'');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (30, 18, 12, 'Ali oni vele: \'Uzalud! Mi ćemo radije provoditi svoje osnove i činiti svaki po okorjelosti zlog srca svojega.\'\"');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (30, 18, 13, 'Ovako govori Jahve: \"Propitajte se po narodima: je li itko takvo što čuo? Toliku grozotu učini djevica Izraelova.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (30, 18, 14, 'Nestaje li s gorske vrleti snijeg libanonski? Mogu li presušiti vode daleke što studene teku?');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (30, 18, 15, 'A narod moj mene zaboravi! Kad prinose ništavnosti, posrnuše na putovima svojim, na stazama drevnim, i hode stazama i putem neprohodnim.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (30, 18, 16, 'I tako su zemlju u pustoš obratili, na vječnu porugu, da se nad njom zgraža svaki prolaznik glavom mašući.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (30, 18, 17, 'Razvitlat ću ih pred neprijateljem, kao istočnjak; leđa, a ne lice, ja ću im pokazati u dan njine propasti.\"');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (30, 18, 18, 'I rekoše: \"Hajdemo da se urotimo protiv Jeremije, jer svećeniku ne može nestati Zakona, ni mudrome savjeta, ni proroku besjede. Hajde, udarimo ga njegovim jezikom i pazimo budno na svaku riječ njegovu.\"');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (30, 18, 19, 'Poslušaj me, o Jahve, i čuj što govore moji protivnici.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (30, 18, 20, 'TÓa zar se dobro uzvraća zlim? A oni mi jamu kopaju! Sjeti se kako stajah pred licem tvojim da u tebe milost tražim za njih, da odvratim od njih jarost tvoju.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (30, 18, 21, 'Zato im djecu izruči gladi, maču ih predaj! Neka im žene ostanu jalove i udovice, neka im kuga pobije muževe, a mladići neka od mača u boju poginu.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (30, 18, 22, 'Neka se prolomi vapaj iz kuća njihovih kad iznenada na njih dovedeš čete pljačkaša. Jer oni iskopaše jamu da me uhvate, nogama mojim u potaji zamke namjestiše.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (30, 18, 23, 'Ti, o Jahve, znadeš sav njihov naum ubilački protiv mene. Ne oprosti im bezakonja njihova, ne izbriši im grijeha pred sobom. Neka padnu pred licem tvojim, obračunaj s njima u dan gnjeva svoga!');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (30, 19, 1, 'Ovako mi reče Jahve: \"Idi i kupi vrč glineni. Povedi sa sobom nekoliko starješina narodnih i svećeničkih.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (30, 19, 2, 'Pođi u Dolinu Ben Hinom, na ulazu Vrata lončarskih. Ondje proglasi riječi koje ću ti kazati.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (30, 19, 3, 'Reci im: Čujte riječ Jahvinu, kraljevi judejski i stanovnici jeruzalemski. Ovako govori Jahve nad Vojskama, Bog Izraelov: \'Evo dovodim nesreću na ovo mjesto te će svima koji to čuju u ušima zazujati.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (30, 19, 4, 'Zato što su me ostavili i otuđili ovo mjesto prinoseći kad tuđim bogovima kojih ne poznavahu oci njihovi ni kraljevi judejski; i zato što su mjesto ovo natopili krvlju nevinih;');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (30, 19, 5, 'i zato što pogradiše uzvišice Baalove da mu spaljuju sinove kao žrtve, a to im ja nikada ne naredih niti zapovjedih, niti mi je takvo što na um palo.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (30, 19, 6, 'Stoga, evo, dolaze dani - riječ je Jahvina - kad se ovo mjesto neće više zvati Tofet ni Dolina Ben Hinom nego Dolina klanja.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (30, 19, 7, 'Izjalovit ću na ovom mjestu naum Judeje i Jeruzalema i učiniti da svi poginu od neprijateljskog mača, od ruku onih što im rade o glavi. A trupla ću njihova dati za hranu pticama nebeskim i zvijerima poljskim.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (30, 19, 8, 'A grad ću ovaj učiniti ruglom i užasom: svaki koji prođe mimo nj zgrozit će se i zviždati zbog svih nesreća njegovih.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (30, 19, 9, 'I dat ću im da jedu meso sinova i kćeri svojih. Da, svaki će jesti meso bližnjega svoga zbog preteške nevolje kojom će ih pritisnuti njihovi neprijatelji što im rade o glavi.\'');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (30, 19, 10, 'Razbij vrč pred očima svojih pratilaca');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (30, 19, 11, 'i reci im: Ovako govori Jahve nad Vojskama: \'Tako ću razbiti ovaj narod i ovaj grad, kao što se razbija sud lončarski, te se više ne da popraviti. U Tofetu će se ukapati, jer inače neće biti mjesta za ukapanje.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (30, 19, 12, 'Tako ću postupiti s ovim mjestom - riječ je Jahvina - i sa stanovnicima njegovim. I učinit ću grad ovaj sličnim Tofetu.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (30, 19, 13, 'I sve kuće jeruzalemske i kuće kraljeva judejskih bit će onečišćene kao mjesto Tofet: sve kuće kojima se na krovovima kad prinosi svoj vojsci nebeskoj i lijevaju ljevanice tuđim bogovima.\'\"');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (30, 19, 14, 'Kad se Jeremija vratio iz Tofeta, kamo ga Jahve bijaše poslao da prorokuje, stade u predvorju Doma Jahvina te uze govoriti svemu narodu:');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (30, 19, 15, '\"Ovako govori Jahve nad Vojskama, Bog Izraelov: \'Evo, dovest ću na ovaj grad i na sve njegove gradiće sve zlo kojim sam im prijetio, jer ukrutiše vratove svoje ne slušajući riječi mojih.\'\"');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (30, 20, 1, 'A svećenik Pašhur, sin Imerov, vrhovni nadzornik Doma Jahvina, ču kako Jeremija prorokuje te riječi.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (30, 20, 2, 'I Pašhur dade Jeremiju batinati i baci ga u klade što se nalaze kod gornjih vrata Benjaminovih, a u Domu su Jahvinu.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (30, 20, 3, 'A kad sutradan Pašhur pusti Jeremiju iz klada, reče mu Jeremija: \"Jahve te više ne zove Pašhur već \'Užas odasvud\'.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (30, 20, 4, 'Jer ovako govori Jahve: \'Evo, predajem te užasu, tebe i sve prijatelje tvoje, i poginut će od mača neprijatelja svojih, svojim ćeš očima vidjeti. I svu Judeju dat ću u ruke kralju babilonskom. On će ih odvesti u izgnanstvo u Babilon i mačem pobiti.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (30, 20, 5, 'I sve bogatstvo ovoga grada, sav njegov trudom stečeni imetak i sve dragocjenosti te sve blago kraljeva judejskih predat ću u ruke neprijateljima. Oni će sve opljačkati, ugrabiti i u Babilon odnijeti.\'');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (30, 20, 6, 'A ti ćeš se, Pašhure, sa svim svojim ukućanima seliti u Babilon. Da, u Babilon ćeš doći i ondje umrijeti i biti pokopan, ti i svi tvoji prijatelji kojima si laži prorokovao.\"');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (30, 20, 7, 'Ti me zavede, o Jahve, i dadoh se zavesti, nadjačao si me i svladao me. A sada sam svima na podsmijeh iz dana u dan, svatko me ismijava.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (30, 20, 8, 'Jer kad god progovorim, moram vikati, naviještati moram: \"Nasilje! Propast!\" Doista, riječ mi Jahvina postade na ruglo i podsmijeh povazdan.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (30, 20, 9, 'I rekoh u sebi: neću više na nj misliti niti ću govoriti u njegovo ime. Al\' tad mi u srcu bi kao rasplamtjeli oganj, zapretan u kostima mojim: uzalud se trudih da izdržim, ne mogoh više.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (30, 20, 10, 'Čuh klevete mnogih: \"Užas odasvud! Prijavite! Mi ćemo ga prijaviti.\" Svi koji mi bijahu prijatelji čekahu moj pad. \"Možda ga zavedemo, pa ćemo njim ovladati i njemu se osvetiti!\"');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (30, 20, 11, 'Sa mnom je Jahve kao snažan junak! Zato će progonitelji moji posrnuti i neće nadvladati, postidjet će se veoma zbog poraza, zbog nezaboravne vječne sramote.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (30, 20, 12, 'O Jahve nad Vojskama, koji proničeš pravednika i vidiš mu bubrege i srce, daj da vidim kako im se osvećuješ, jer tebi povjerih parnicu svoju.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (30, 20, 13, 'Pjevajte Jahvi, hvalite Jahvu, jer on izbavi dušu sirote iz ruku zlikovaca.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (30, 20, 14, 'Proklet bio dan kad se rodih, dan kad me rodi majka moja ne bio blagoslovljen!');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (30, 20, 15, 'Proklet bio čovjek koji ocu mom dojavi: \"Rodio ti se sin, muškić!\" i time mi oca obradova.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (30, 20, 16, 'Tom čovjeku bilo kao gradovima što ih Jahve nemilice razvali; već u cik zore čuo zapomaganje i poklike bojne u podne,');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (30, 20, 17, 'jer me ne pogubi u majčinoj utrobi da bi majka bila moj grob, da bi joj utroba dovijeka ostala trudna!');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (30, 20, 18, 'O, zašto izađoh iz majčina krila? Da vidim jad i nevolju i u sramoti da dokončam dane!');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (30, 21, 1, 'Riječ koju Jahve uputi Jeremiji kad kralj Sidkija posla k njemu Pašhura, sina Malkijina, i svećenika Sefaniju, sina Maasejina, s porukom:');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (30, 21, 2, '\"Hajde, upitaj Jahvu za nas, jer je Nabukodonozor, kralj babilonski, zavojštio na nas; možda će Jahve opet učiniti s nama čudo, pa će se neprijatelj povući pred nama.\"');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (30, 21, 3, 'Jeremija im reče: \"Ovako recite Sidkiji:');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (30, 21, 4, 'Ovako govori Jahve, Bog Izraelov: \'Povući ću oružje koje je u vašim rukama, kojim se borite protiv kralja babilonskoga i Kaldejaca što vas napadaju izvan zidina, i skupiti ga usred ovoga grada.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (30, 21, 5, 'I sam ću se boriti protiv vas ispruženom rukom i snažnom mišicom, u srdžbi i gnjevu i velikoj jarosti.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (30, 21, 6, 'I strašnom kugom udarit ću stanovnike ovoga grada, ljude i životinje, i pomrijet će.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (30, 21, 7, 'Poslije toga ću - riječ je Jahvina - Sidkiju, kralja judejskoga, i njegove sluge i narod, i sve one koji preostadoše u tom gradu nakon pošasti, mača i gladi, predati u ruke Nabukodonozora, kralja babilonskoga, u ruke njihovih neprijatelja i u ruke onih koji im rade o glavi; on će ih sasjeći oštricom mača bez samilosti, bez milosrđa i bez smilovanja.\'');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (30, 21, 8, 'A ovom narodu reci: \'Ovako govori Jahve: Evo stavljam pred vas put života i put smrti.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (30, 21, 9, 'Tko ostane u ovom gradu, poginut će od mača, gladi i kuge. A tko izađe, te se preda Kaldejcima koji vas opsjedaju, spasit će život - život će mu ostati kao plijen.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (30, 21, 10, 'Jer, okrenuh lice svoje ovomu gradu na zlo, a ne na dobro - riječ je Jahvina - i bit će izručen u ruke kralja babilonskoga, i on će ga vatrom spaliti.\'\"');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (30, 21, 11, 'Kraljevskom domu Judeje. Čujte riječ Jahvinu,');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (30, 21, 12, 'dome Davidov! Ovako govori Jahve: \"Svako jutro sudite pravedno, izbavite potlačene iz ruku tlačitelja, ili će moj gnjev planut\' poput vatre, raspalit\' se neugasivo zbog vaših opačina.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (30, 21, 13, 'Evo me protiv tebe koji stanuješ na Pećini dolinskoj - riječ je Jahvina - protiv vas koji kažete: \'Tko može na nas navaliti, tko u naše nastambe prodrijeti?\'');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (30, 21, 14, 'Al\' ja ću vam platiti prema plodu djela vaših - riječ je Jahvina. - Oganj ću podmetnuti šumi njegovoj i proždrijet će sve oko nje!\"');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (30, 22, 1, 'Ovako govori Jahve: \"Siđi u palaču kralja judejskoga i objavi ondje ovu riječ.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (30, 22, 2, 'Reci: Slušaj riječ Jahvinu, kralju judejski, koji sjediš na prijestolju Davidovu, ti i tvoje sluge i tvoj narod koji ulaze na ova vrata.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (30, 22, 3, 'Ovako govori Jahve: \'Činite pravo i pravicu, izbavite potlačene iz ruku tlačitelja! Ne činite krivo strancu, siroti, udovici, ne tlačite ih i ne prolijevajte krvi nedužne na ovome mjestu.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (30, 22, 4, 'Jer budete li se istinski vladali po riječi ovoj, na vrata ovog dvora ulazit će kraljevi što sjede na prijestolju Davidovu, voze se na kolima i jašu na konjima - oni, njihove sluge i njihov narod.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (30, 22, 5, 'Ako pak ne poslušate ovih riječi, zaklinjem se sobom - riječ je Jahvina - da ću taj dvor pretvoriti u ruševinu!\'\"');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (30, 22, 6, 'Jer ovako govori Jahve o dvoru kralja judejskoga: \"Ti si za me Gilead, vrh libanonski. Ali, uistinu, pretvorit ću te u pustinju, u grad nenastanjen.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (30, 22, 7, 'Spremit ću protiv tebe zatirače, svakoga s oružjem njegovim, nek\' posijeku izabrane ti cedrove i u vatru ih pobacaju.\"');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (30, 22, 8, 'Mnoštvo će naroda prolaziti mimo taj grad i pitat će jedan drugoga: \"Zašto je Jahve tako postupio s ovim velikim gradom?\"');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (30, 22, 9, 'Odgovorit će im: \"Jer su ostavili Savez Jahve, Boga svoga, klanjali se drugim bogovima i služili im.\"');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (30, 22, 10, 'Ne oplakujte mrtvoga, ne jadikujte za njim. Radije plačite za onim koji odlazi, jer se nikad više neće vratiti ni rodne grude vidjeti.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (30, 22, 11, 'Jer ovako govori Jahve o Šalumu, sinu Jošijinu, kralju judejskomu, koji kraljevaše mjesto oca svoga i morade otići iz ovoga mjesta: \"Nikad se više neće vratiti,');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (30, 22, 12, 'nego će umrijeti u mjestu kamo ga izagnaše, a ovu zemlju nikad više neće vidjeti.\"');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (30, 22, 13, 'Jao onom koji kuću gradi nepravedno i gornje odaje diže bez prava; koji bližnjega tjera na tlaku i plaću mu ne isplaćuje;');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (30, 22, 14, 'koji kaže: \"Sagradit ću sebi kuću prostranu i prozračne gornje odaje!\" koji probija prozore, oblaže ih cedrovinom crveno obojenom.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (30, 22, 15, 'Jesi li zato kralj što se cedrom razmećeš? Nije li ti i otac jeo i pio, ali je činio pravo i pravicu i zato mu bješe dobro.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (30, 22, 16, 'Branio je pravo siromaha i jadnika, i zato mu bješe dobro. Zar ne znači to mene poznavati? - riječ je Jahvina.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (30, 22, 17, 'Ali tvoje oči i srce idu samo za dobitkom, da krv nevinu prolijevaš, da nasilje činiš i krivdu.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (30, 22, 18, 'Zato ovako govori Jahve o Jojakimu, sinu Jošijinu, kralju judejskom: \"Za njim neće naricati: \'Jao, brate moj! Jao, sestro moja!\' Za njim neće naricati: \'Jao, gospodaru! Jao, veličanstvo!\'');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (30, 22, 19, 'Pokopat će ga k\'o magarca, izvući ga i baciti izvan vrata Jeruzalema.\"');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (30, 22, 20, '\"Popni se na Libanon i viči, po Bašanu nek\' se ori glas, s Abarima buči, jer svi su tvoji prijatelji slomljeni!');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (30, 22, 21, 'Lijepo sam te svjetovao u danima mirnim, al\' ti mi reče: \'Neću slušati!\' Tako se vladaš od mladosti: ne slušaš glasa mojega.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (30, 22, 22, 'Sve će tvoje pastire vjetar popasti, a ljubavnici će tvoji u izgnanstvo. Tada ćeš se stidjet\' i sramiti zbog sve pakosti svoje.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (30, 22, 23, 'Ti što prebivaš na Libanonu, ti što se gnijezdiš po cedrovima, kako li ćeš stenjati kad bolovi te spopadnu, trudovi porodilje.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (30, 22, 24, 'Života mi moga - riječ je Jahvina - kad bi Konija, sin Jojakimov, kralj judejski, bio pečatnjak na mojoj desnici, ja bih ga strgao s prsta.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (30, 22, 25, 'Dat ću te u ruke onima koji ti rade o glavi, u ruke onima pred kojima dršćeš, u ruke Nabukodonozora, kralja babilonskog, i u ruke Kaldejaca.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (30, 22, 26, 'I bacit ću tebe i majku koja te rodila u drugu zemlju gdje se niste rodili; tamo ćete umrijeti.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (30, 22, 27, 'Ali u zemlju u koju čeznu da se vrate neće se vratiti!\"');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (30, 22, 28, 'TÓa zar je taj čovjek Konija sud prezren, razbijen? Il\' posuda što nikom se ne sviđa? Zašto bjehu protjerani on i potomstvo, prognani u zemlju koja im je posve neznana?');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (30, 22, 29, 'Zemljo, zemljo, zemljo, poslušaj riječ Jahvinu.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (30, 22, 30, 'Ovako govori Jahve: \"Upišite za ovoga čovjeka: \'Bez djece. Život mu se nije posrećio. Nitko od potomstva njegova neće sjesti na prijesto Davidov ni vladati Judejom.\'\"');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (30, 23, 1, '\"Jao pastirima koji upropašćuju i raspršuju ovce paše moje\" - riječ je Jahvina.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (30, 23, 2, 'Stoga ovako govori Jahve, Bog Izraelov, protiv pastira koji pasu narod moj: \"Vi ste raspršili ovce moje, rastjerali ih, niste se brinuli za njih. Zato ću se ja sada pobrinuti za vas zbog zlodjela vaših - riječ je Jahvina.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (30, 23, 3, 'I sam ću skupiti ostatak svojih ovaca iz svih zemalja kamo sam ih raspršio i vratiti ih na ispaše njihove: bit će plodne i množit će se.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (30, 23, 4, 'I podići ću im pastire da ih pasu te se ničega više neće bojati ni plašiti, niti će se gubiti\" - riječ je Jahvina.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (30, 23, 5, '\"Evo dolaze dani - riječ je Jahvina - podići ću Davidu izdanak pravedni. On će vladati kao kralj i biti mudar i činit će pravo i pravicu u zemlji.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (30, 23, 6, 'U njegove će dane Judeja biti spašena i Izrael će živjeti spokojno. I evo imena kojim će ga nazivati: \'Jahve, Pravda naša.\'');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (30, 23, 7, 'Zato, evo, dolaze dani - riječ je Jahvina - kad se više neće govoriti: \'Živoga mi Jahve koji sinove Izraelove izvede iz zemlje egipatske\',');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (30, 23, 8, 'nego: \'Živoga mi Jahve koji potomstvo doma Izraelova izvede i dovede iz zemlje sjeverne i iz svih zemalja kamo ih bijaše prognao, tako da obitavaju u zemlji svojoj.\'\"');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (30, 23, 9, 'Prorocima. Srce je u meni skrhano, dršću mi kosti, sličan sam pijancu, čovjeku kojim vino ovlada, pred licem Jahvinim i njegovim svetim riječima:');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (30, 23, 10, '\"Jer zemlja je puna preljubnika; zbog tih se ljudi zemlja u crno zavila, a ispaše u pustinji sagorješe. Njihova je trka zloba, a moć im je nepravda.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (30, 23, 11, 'Da, i prorok i svećenik zlikovci su, čak i u Domu svome nađoh im pakost\" - riječ je Jahvina.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (30, 23, 12, 'Stog\' će im se puti prometnuti u tlo klizavo: u mraku će posrtati i padati. Jer ja ću na njih svaliti nesreću u godine kazne njihove\" - riječ je Jahvina.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (30, 23, 13, '\"I u proroka Samarije vidjeh mnoge ludosti: prorokuju u Baalovo ime i zavode narod moj izraelski.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (30, 23, 14, 'Ali u proroka jeruzalemskih vidjeh strahote: preljub, prijevarne putove, jačaju ruke zločincima, te se nitko od zločina svojih ne obraća. Svi su mi oni kao Sodoma, a žitelji kao Gomora!\"');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (30, 23, 15, 'I zato Jahve nad Vojskama ovako govori o prorocima: \"Evo, nahranit ću ih pelinom i napojiti vodom zatrovanom, jer od proroka jeruzalemskih potječe pokvara u svoj zemlji.\"');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (30, 23, 16, 'Ovako govori Jahve nad Vojskama: \"Ne slušajte riječi proroka: oni vas obmanjuju, objavljuju viđenja srca svoga, a ne što dolazi iz usta Jahvinih;');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (30, 23, 17, 'govore onima što preziru riječ Jahvinu: \'Bit će s vama mir!\' a onima što slijede glas svog srca okorjelog: \'Nikakvo vas zlo neće snaći!\'\"');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (30, 23, 18, 'TÓa tko bijaše na vijećanju Jahvinu, tko je vidio, tko slušao riječ njegovu? Tko ju je shvatio te je može objaviti?');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (30, 23, 19, 'Gle, nevrijeme Jahvino: jarost provaljuje, razmahuje se vihor silan i svaljuje na glave bezbožničke.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (30, 23, 20, 'Jahvin se gnjev neće stišati, dok on ne izvrši i ne ispuni naume srca svojega. U dane posljednje jasno ćete to razumjeti.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (30, 23, 21, '\"Ne poslah ti proroka, a ipak trče! Ne govorih im, a ipak prorokuju!');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (30, 23, 22, 'Jest, da bijahu na mom vijećanju, moje bi riječi narodu mom obznanili, i kušali ih svrnuti sa zla puta njihova i od zlodjela njihovih!');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (30, 23, 23, 'TÓa, zar sam ja Bog samo iz blizine - riječ je Jahvina - zar iz daljine nisam više Bog?');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (30, 23, 24, 'Može li se tko skriti u skrovištima da ga ja ne vidim? - riječ je Jahvina. Ne ispunjam li ja nebo i zemlju? - riječ je Jahvina.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (30, 23, 25, 'Čuo sam što govore proroci koji prorokuju laži u ime moje i tvrde: \'Usnio sam! Usnio sam!\'');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (30, 23, 26, 'Dokle će među prorocima biti onih koji prorokuju laž i objavljuju prijevaru srca svojega?');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (30, 23, 27, 'Misle da će svojim snima što ih jedan drugom pripovijedaju postići da narod moj zaboravi ime moje, kao što već oci njihovi zaboraviše ime moje uz Baala!');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (30, 23, 28, 'Prorok koji je usnio san neka samo pripovijeda svoj san, a u koga je riječ moja, neka po istini objavljuje riječ moju!\" \"Što je zajedničko slami i žitu? - riječ je Jahvina.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (30, 23, 29, 'Nije li riječ moja poput vatre - riječ je Jahvina - i nije li slična malju što razbija pećinu?');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (30, 23, 30, 'Evo me stoga protiv proroka - riječ je Jahvina - koji jedan drugome kradu moje riječi.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (30, 23, 31, 'Evo me protiv proroka - riječ je Jahvina - koji mlate jezikom i proroštva kuju.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (30, 23, 32, 'Evo me protiv proroka - riječ je Jahvina - koji prorokuju izmišljene snove i pripovijedajući ih zavode narod moj izmišljotinama svojim i lažima. A ja ih nisam poslao, niti sam im što zapovjedio, niti su narodu ovome od kakve koristi - riječ je Jahvina.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (30, 23, 33, 'A ako te ovaj narod, ili prorok, ili svećenik, zapita: \'Što je breme Jahvino?\' odgovori im: \'Vi ste breme Jahvino i ja vas odbacujem\' - riječ je Jahvina.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (30, 23, 34, 'A reče li koji prorok ili svećenik, ili tko iz naroda: \'Breme Jahvino\', kaznit ću toga čovjeka i dom njegov.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (30, 23, 35, 'Ovako morate govoriti svaki svome bližnjemu i svaki svome bratu: \'Što je Jahve odgovorio?\' ili \'Što je Jahve rekao?\'');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (30, 23, 36, 'Ali \'Breme Jahvino\' da više niste spomenuli, jer je breme svakome riječ njegova.\" Jer vi iskrivljujete riječi Boga živoga, Jahve nad Vojskama, našega Boga!');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (30, 23, 37, 'Ovako reci proroku: \"Što ti je Jahve odgovorio?\" ili \"Što je Jahve rekao?\"');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (30, 23, 38, 'Ali ako kažete \"Breme Jahvino\", ovako govori Jahve: \"Zato što se služite riječju \'Breme Jahvino\', premda sam vam poručio da je ne izgovarate,');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (30, 23, 39, 'ja ću visoko podići i odbaciti od lica svojega vas i vaš grad što ga dadoh vama i ocima vašim!');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (30, 23, 40, 'I svalit ću na vas vječnu sramotu i vječnu porugu koja se neće zaboraviti.\"');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (30, 24, 1, 'Jahve mi pokaza, i gle: dvije kotarice smokava stajahu pred Domom Jahvinim, pošto Nabukodonozor, kralj babilonski, odvede iz Jeruzalema i izagna u Babilon Jekoniju, sina Jojakimova, kralja judejskoga, zajedno s knezovima judejskim, kovačima i bravarima.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (30, 24, 2, 'U jednoj kotarici bijahu izvrsne smokve, kakve već jesu rane smokve; a u drugoj bijahu pokvarene smokve, tako rđave da se ne mogahu jesti.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (30, 24, 3, 'I Jahve me upita: \"Jeremija, što vidiš?\" A ja odgovorih: \"Smokve! Dobre su vrlo dobre, a loše su vrlo loše - tako loše da nisu za jelo.\"');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (30, 24, 4, 'I dođe mi riječ Jahvina:');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (30, 24, 5, 'Ovako govori Jahve, Bog Izraelov: \"Kao na ove dobre smokve, tako ću milostivo pogledati na sužnje judejske koje sam s ovoga mjesta prognao u zemlju kaldejsku.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (30, 24, 6, 'I milostivo ću svrnuti oči na njih i vratiti ih u ovu zemlju. Ponovo ću ih podići i neću ih više uništiti; opet ću ih posaditi i neću ih više iščupati.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (30, 24, 7, 'I dat ću im srce da me poznaju da sam ja Jahve, da budu narod moj, a ja Bog njihov, jer će se oni svim srcem svojim opet k meni obratiti.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (30, 24, 8, 'Ali kao s lošim smokvama koje su tako loše da nisu za jelo - da, riječ je Jahvina - tako ću postupiti i sa Sidkijom, kraljem judejskim, s njegovim knezovima i sa svim Jeruzalemcima što preostadoše u ovoj zemlji i s onima što se u Egiptu nastaniše.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (30, 24, 9, 'Učinit ću da budu na užas svim kraljevstvima zemaljskim, na sramotu i porugu, na ruglo i kletvu posvuda kamo ih protjeram.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (30, 24, 10, 'I poslat ću na njih mač, glad i kugu dok se ne istrijebe sa zemlje koju dadoh njima i ocima njihovim.\"');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (30, 25, 1, 'Riječ upućena Jeremiji o svem narodu judejskom, četvrte godine Jojakima, sina kralja judejskog - to je prve godine Nabukodonozora, kralja babilonskog.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (30, 25, 2, 'Prorok');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (30, 25, 3, 'Od trinaeste godine Jošije, sina Amonova, kralja judejskoga, sve do dana današnjeg, ove dvadeset i tri godine, dolazila mi je riječ Jahvina i ja sam vam jednako govorio, ali me niste slušali.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (30, 25, 4, 'I Jahve je svejednako slao k vama sve sluge svoje, proroke, ali vi niste slušali i niste prignuli uši svoje da čujete.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (30, 25, 5, 'I govorahu vam: \"Vratite se svaki sa zla puta svojega i od zlih djela svojih i ostanite u zemlji koju Jahve dade vama i ocima vašim za sva vremena;');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (30, 25, 6, 'i ne idite za tuđim bogovima da im služite i da im se klanjate; i ne gnjevite me djelima ruku svojih, pa vam neću ništa nažao učiniti.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (30, 25, 7, 'Ali me niste poslušali - riječ je Jahvina - nego me razgnjeviste djelima ruku svojih, na svoju nesreću!\"');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (30, 25, 8, 'Zato ovako govori Jahve nad Vojskama: \"Jer niste poslušali mojih riječi,');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (30, 25, 9, 'evo, ja ću poslati i podignuti sve narode sa sjevera - riječ je Jahvina - i slugu svoga Nabukodonozora, kralja babilonskoga, i dovest ću ih na ovu zemlju i na njene stanovnike i na sve okolne narode; izručit ću ih kletom uništenju i učinit ću ih užasom i ruglom, vječnim razvalinama.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (30, 25, 10, 'I ugušit ću među njima svaki glas radosti i veselja, klicanje zaručnika i zaručnice i klopot žrvnja i svjetlost svjetiljke.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (30, 25, 11, 'Sva će se zemlja pretvoriti u pustoš i pustinju i svi će narodi služiti kralju babilonskom sedamdeset godina.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (30, 25, 12, 'Ali kad se navrši sedamdeset godina, kaznit ću kralja babilonskog i narod onaj - riječ je Jahvina - za bezakonje njihovo i zemlju kaldejsku i pretvorit ću ih u vječne razvaline.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (30, 25, 13, 'Dovest ću na tu zemlju sve što sam protiv nje rekao - sve je to napisano u ovoj knjizi, što prorokova Jeremija za sve narode.\"');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (30, 25, 14, '\"I oni će služiti mnogim narodima i velikim kraljevima i platit ću im po njihovim činima i po djelima ruku njihovih.\"');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (30, 25, 15, 'Ovako mi reče Jahve, Bog Izraelov: \"Uzmi ovaj pehar vina iz moje ruke i napoji njime sve narode kojima ću te poslati.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (30, 25, 16, 'Neka piju dok ne zateturaju i dok se ne izbezume zbog mača što ću ga među njih poslati.\"');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (30, 25, 17, 'I uzeh pehar iz ruke Jahvine i napojih njime sve narode kojima me Jahve bijaše poslao:');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (30, 25, 18, 'Jeruzalem i gradove judejske s njihovim kraljevima i knezovima, neka budu razvalina, pustoš, ruglo i prokletstvo, kao što su i danas;');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (30, 25, 19, 'faraona, kralja egipatskoga, s njegovim slugama i knezovima i narodom njegovim');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (30, 25, 20, 'i svu onu mješavinu naroda: sve kraljeve zemlje Usa, sve kraljeve zemlje filistejske, Aškelon, Gazu, Ekron i ono što ostade od Ašdoda;');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (30, 25, 21, 'Edom, Moab i sinove Amonove;');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (30, 25, 22, 'sve kraljeve Tira, sve kraljeve Sidona, kraljeve otoka onkraj mora;');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (30, 25, 23, 'Dedan, Temu, Buz i sve one ostriženih zalizaka,');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (30, 25, 24, 'sve kraljeve Arabije, sve kraljeve mješavine naroda koji obitavaju u pustinji;');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (30, 25, 25, 'sve kraljeve Zimrija, sve kraljeve Elama i sve kraljeve Medije;');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (30, 25, 26, 'sve kraljeve Sjevera, blize i daleke, jednog za drugim, i sva kraljevstva na licu zemlje. A kralj Šešak pit će poslije njih.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (30, 25, 27, 'I reci im: \"Ovako govori Jahve nad Vojskama, Bog Izraelov: \'Pijte! Opijte se! Bljujte! Padnite da se više ne dignete od mača koji ću pustiti među vas.\'');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (30, 25, 28, 'Ako ne bi htjeli uzeti pehar iz tvoje ruke da piju, reci im: \'Ovako govori Jahve nad Vojskama: Morate piti!');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (30, 25, 29, 'Jer, evo, ja sam počeo kažnjavati grad koji se zove mojim imenom. A vi zar da prođete bez kazne? Ne, nećete ostati nekažnjeni, jer ću sam dozvati mač da udari na sve stanovnike zemlje\' - riječ je Jahve nad Vojskama.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (30, 25, 30, 'Ti im, dakle, prorokuj sve riječi ove i reci im: \'Jahve reče sa visine, iz svetoga stana grmi glasom, riče iza glasa protiv pašnjaka svoga, podvikuje kao oni što grožđe gaze. Do svih stanovnika zemlje');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (30, 25, 31, 'dopire bojni klik - do nakraj svijeta - jer Jahve se parbi s narodima, izlazi na sud sa svakim tijelom, bezbožnike će maču izručiti - riječ je Jahvina.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (30, 25, 32, 'Ovako govori Jahve nad Vojskama: Evo, nesreća već zahvaća narod za narodom; nevrijeme strašno već se prolama s krajeva zemlje.\'\"');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (30, 25, 33, 'U onaj dan bit će pobijenih Jahvinih s jednoga kraja svijeta do drugoga. Za njima nitko neće naricati, niti će ih tko pokupiti i sahraniti; ostat će kao gnoj po zemlji.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (30, 25, 34, 'Kukajte, pastiri, i vičite, valjajte se po prašini, vodiči stada, jer vam se ispuniše dani za klanje, popadat ćete ko ovnovi izabrani.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (30, 25, 35, 'Više nema utočišta pastirima, niti spasa vodičima stada.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (30, 25, 36, 'Čuj, kako vapiju pastiri, kako kukaju vodiči stada, jer Jahve pustoši pašnjak njihov,');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (30, 25, 37, 'mirna su pasišta poharana od jarosna gnjeva Jahvina.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (30, 25, 38, 'Lav ostavlja guštaru jer će zemlja njihova opustjeti od mača pustošničkog, od jarosnog gnjeva Jahvina.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (30, 26, 1, 'U početku kraljevanja Jojakima, sina Jošijina, kralja Judina, dođe mi riječ Jahvina.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (30, 26, 2, 'Ovako govori Jahve: \"Stani u predvorju Doma Jahvina i svim gradovima judejskim koji dolaze da se poklone u Domu Jahvinu naviještaj sve riječi koje sam ti zapovjedio da im kažeš. I ne izostavi ni jedne jedine.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (30, 26, 3, 'Možda će poslušati i vratiti se svaki sa zla puta svoga, pa ću se pokajati za zlo koje naumih učiniti zbog zlodjela njihovih.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (30, 26, 4, 'Reci im: \'Ovako govori Jahve: Ako me ne poslušate da hodite po Zakonu što ga stavih pred vas,');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (30, 26, 5, 'slušajući riječi slugu mojih proroka koje vam neumorno šaljem, premda ih do sada niste slušali,');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (30, 26, 6, 'postupit ću s ovim Domom kao sa Šilom i učinit ću da ovaj grad bude prokletstvo za sve narode na zemlji.\'\"');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (30, 26, 7, 'I svećenici i proroci i sav narod slušahu Jeremiju kako naviješta te riječi u Domu Jahvinu.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (30, 26, 8, 'A kad Jeremija izreče sve ono što mu je Gospod zapovjedio da naviješta svemu narodu, zgrabiše ga svećenici i proroci govoreći: \"Platit ćeš glavom!');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (30, 26, 9, 'Zašto si u ime Jahvino prorokovao: \'Postupit ću s ovim Domom kao sa Šilom i ovaj će grad biti opustošen te nitko više u njemu neće stanovati?\'\" I sav se narod skupi na Jeremiju u Domu Jahvinu.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (30, 26, 10, 'Čuvši to, starješine judejske dođoše iz kraljevskog dvora u Dom Jahvin i sjedoše pred Nova vrata Doma Jahvina.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (30, 26, 11, 'Tada svećenici i proroci rekoše starješinama i svemu narodu: \"Ovaj je čovjek zaslužio smrt jer je prorokovao protiv ovoga grada, kao što ste čuli na svoje uši.\"');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (30, 26, 12, 'Tada Jeremija reče starješinama i svemu narodu: \"Jahve me posla da prorokujem protiv ovoga Doma i ovoga grada sve ono što ste čuli.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (30, 26, 13, 'Popravite, dakle, putove svoje i djela svoja i slušajte glas Jahve, Boga svoga: i pokajat će se za zlo kojim vam se zaprijetio.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (30, 26, 14, 'Ja sam, evo, u vašim rukama. Učinite sa mnom što vam se čini dobro i pravo.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (30, 26, 15, 'Ali dobro znajte: ako me pogubite, krv nedužnu navalit ćete na sebe, na ovaj grad i na njegove stanovnike. Jer, zaista, Jahve me posla k vama da u vaše uši govorim sve ove riječi.\"');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (30, 26, 16, 'Tada rekoše starješine i sav narod svećenicima i prorocima: \"Ovaj čovjek nipošto ne zaslužuje smrt, jer nam je govorio u ime Jahve, Boga našega.\"');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (30, 26, 17, 'Nato ustadoše i neki od najuglednijih u zemlji te rekoše svemu mnoštvu naroda što se ondje okupilo:');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (30, 26, 18, '\"Mihej Morešećanin prorokovaše u dane Ezekije, kralja judejskog, i govoraše svemu narodu judejskom: \'Ovako govori Jahve nad Vojskama: Sion će biti polje preorano, Jeruzalem ruševina, a Goru Doma ovog šuma će prekriti.\'');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (30, 26, 19, 'Je li ga zato pogubio Ezekija, kralj judejski, i sva Judeja? Nisu li se pobojali Jahve i nastojali da Jahvu umilostive, te se Jahve pokaja za zlo kojim im se bijaše zaprijetio? A mi, zar da na duše svoje navalimo tako velik zločin?\"');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (30, 26, 20, 'Bijaše ondje još neki koji prorokovaše u ime Jahvino, Urija, sin Šemajin, rodom iz Kirjat Jearima. I on prorokovaše protiv ovoga grada i zemlje ove kao i Jeremija.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (30, 26, 21, 'A kad je kralj Jojakim sa svim ratnicima i zapovjednicima čuo te riječi, tražio je da ga smakne. Čuvši to, Urija se prestraši i pobježe u Egipat.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (30, 26, 22, 'Ali kralj Jojakim posla u Egipat Elnatana, sina Akborova, s nekoliko ljudi;');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (30, 26, 23, 'dovedoše oni Uriju iz Egipta i odvedoše ga kralju Jojakimu, koji ga mačem pogubi, a truplo njegovo baci na groblje prostoga puka.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (30, 26, 24, 'Ali Ahikam, sin Šafanov, zaštiti Jeremiju te ga ne predaše u ruke narodu da ga pogube.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (30, 27, 1, 'U početku kraljevanja Sidkije, sina Jošije, kralja judejskoga, uputi Jahve Jeremiji ovu riječ.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (30, 27, 2, 'Ovako mi reče Jahve: \"Načini sebi užad i jaram i stavi ga sebi na vrat.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (30, 27, 3, 'Zatim poruči kralju edomskom, kralju moapskom, kralju amonskom, kralju tirskom i kralju sidonskom, po njihovim izaslanicima koji su došli u Jeruzalem kralju judejskom Sidkiji.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (30, 27, 4, 'Naredi im da poruče svojim gospodarima: \'Ovako govori Jahve nad Vojskama, Bog Izraelov! Ovako poručite svojim gospodarima:');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (30, 27, 5, 'Ja sam snagom svojom svesilnom i rukom ispruženom stvorio zemlju, ljude i životinje na zemlji. I ja to dajem kome hoću.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (30, 27, 6, 'Sada, dakle, sve te zemlje dajem u ruke Nabukodonozoru, kralju babilonskom, sluzi svojemu; dajem mu i poljsko zvijerje da mu služi.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (30, 27, 7, 'I svi će narodi služiti njemu i njegovu sinu, i sinu njegova sina, dok i njegovoj zemlji ne kucne čas te i njega ne upokore moćni narodi i veliki kraljevi.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (30, 27, 8, 'Ako koji narod, ili kraljevstvo, ne htjedne služiti Nabukodonozora, kralja babilonskoga, ne hoteć\' se upregnuti u jaram kralja babilonskog, taj ću narod kazniti mačem, glađu i kugom - riječ je Jahvina - dok ga sasvim ne zatrem rukom njegovom.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (30, 27, 9, 'Ne slušajte, dakle, svojih proroka, gatalaca, sanjara, zvjezdara svojih i čarobnjaka koji vam govore: \'Ne, vi nećete služiti kralju babilonskom!\'');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (30, 27, 10, 'Jer vam oni laž prorokuju samo da vas udalje iz vaše zemlje, da vas otjeram pa da propadnete.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (30, 27, 11, 'Ali narod koji se upregne u jaram kralja babilonskoga da mu služi ostavit ću na miru u zemlji njegovoj - riječ je Jahvina - da je obrađuje i u njoj živi.\'\"');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (30, 27, 12, 'Sve sam to rekao Sidkiji, kralju judejskom, govoreći: \"Upregnite se u jaram kralja babilonskoga i pokorite se njemu i narodu njegovu da ostanete živi.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (30, 27, 13, 'Zašto da poginete, ti i narod tvoj, od mača, gladi i kuge, kao što se Jahve zaprijetio narodu koji se ne podvrgne kralju babilonskom?');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (30, 27, 14, 'Ne slušajte, dakle, riječi onih proroka koji vam govore: \'Vi nećete služiti kralju babilonskom.\' Oni vam laž prorokuju.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (30, 27, 15, '\'Jer nisam ih ja poslao da vam prorokuju - riječ je Jahvina - nego vam oni laž prorokuju u moje ime, da vas otjeram iz vaše zemlje, pa da propadnete - vi i proroci koji vam prorokuju.\'\"');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (30, 27, 16, 'I svećenicima i svemu ovom narodu rekao sam: \"Ovako govori Jahve: \'Ne slušajte riječi svojih proroka koji vam ovako prorokuju: Evo, posuđe Doma Jahvina bit će uskoro vraćeno iz Babilona.\' Oni vam laži prorokuju.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (30, 27, 17, 'Ne slušajte ih! Pokorite se kralju babilonskom da ostanete živi! Zašto da ovaj grad postane ruševina?');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (30, 27, 18, 'Ako su oni zaista proroci, te ako je u njima riječ Jahvina, neka mole Jahvu nad Vojskama da i posuđe što još ostade u Domu Jahvinu i u dvoru kraljeva judejskih i u Jeruzalemu ne dospije u Babilon!');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (30, 27, 19, 'Jer ovako govori Jahve o stupovima, moru, podnožjima i o preostalom posuđu što još ostade u ovome gradu -');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (30, 27, 20, 'što još Nabukodonozor, kralj babilonski, ne uze sa sobom onda kad odvede u izgnanstvo iz Jeruzalema u Babilon Jekoniju, sina Jojakimova, kralja judejskoga, i sve odličnike judejske i jeruzalemske.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (30, 27, 21, 'Da, ovako govori Jahve nad Vojskama, Bog Izraelov, o posuđu koje preostade u Domu Jahvinu, u dvoru kralja judejskog, i u Jeruzalemu:');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (30, 27, 22, '\'U Babilon će ih odnijeti i ondje će ostati sve do dana kad ja odem po njih - riječ je Jahvina. I ja ću sve to donijeti i postaviti na ovo mjesto!\'\"');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (30, 28, 1, 'Iste godine, u početku kraljevanja Sidkije, kralja judejskoga, četvrte godine, petog mjeseca, Hananija, sin Azurov, prorok rodom iz Gibeona, reče mi u Domu Jahvinu pred svim svećenicima i svim narodom:');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (30, 28, 2, '\"Ovako govori Jahve nad Vojskama, Bog Izraelov: \'Skršit ću jaram kralja babilonskoga.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (30, 28, 3, 'Do dvije godine vratit ću na ovo mjesto sve posuđe Doma Jahvina koje je Nabukodonozor, kralj babilonski, odavde uzeo i odnio u Babilon.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (30, 28, 4, 'A tako i Jekoniju, sina Jojakimova, kralja judejskoga, i sve izgnanike judejske, koji dospješe u Babilon, također ću vratiti na ovo mjesto - riječ je Jahvina - jer ću skršiti jaram kralja babilonskoga.\'\"');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (30, 28, 5, 'Tada prorok Jeremija odgovori proroku Hananiji pred svećenicima i pred svim narodom koji bijahu u Domu Jahvinu.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (30, 28, 6, 'Reče prorok Jeremija: \"Amen! Učinio Jahve tako! Ispunio Jahve riječi koje si prorokovao i vratio ovamo sve posuđe iz Doma Jahvina i sve izgnanike iz Babilona.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (30, 28, 7, 'Ali čujder i ovu riječ koju ću kazati na tvoje uši i na uši svega naroda.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (30, 28, 8, 'Proroci koji su bili prije mene i tebe, odiskona prorokovahu mnogim moćnim zemljama i velikim kraljevstvima rat, glad, kugu.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (30, 28, 9, 'Ali o proroku koji proriče mir možeš istom kad se ispuni njegova proročka riječ znati da ga je zaista Jahve poslao.\"');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (30, 28, 10, 'Tada prorok Hananija skide jaram s vrata proroka Jeremije i skrši ga.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (30, 28, 11, 'I reče Hananija pred svim narodom: \"Ovako govori Jahve: \'Evo, ovako ću - za dvije godine - skršiti jaram Nabukodonozora, kralja babilonskoga, s vrata svih naroda!\'\" Tada prorok Jeremija ode svojim putem.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (30, 28, 12, 'A kad prorok Hananija skrši jaram s vrata proroka Jeremije, dođe riječ Jahvina Jeremiji:');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (30, 28, 13, '\"Idi i ovako reci Hananiji: \'Ovako govori Jahve: Ti si skršio drveni jaram, ali ću ja mjesto njega načiniti željezni.\'');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (30, 28, 14, 'Jer ovako govori Jahve nad Vojskama, Bog Izraelov: \'Željezni ću jaram staviti oko vrata svih ovih naroda da ih podvrgnem Nabukodonozoru, kralju babilonskom, i služit će mu, jer ja sam njemu podložio čak i poljsku zvjerad!\'\"');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (30, 28, 15, 'I prorok Jeremija reče proroku Hananiji: \"Čuj me dobro, Hananija! Tebe nije poslao Jahve, a ti si u narodu pobudio varave nade.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (30, 28, 16, 'Zato ovako govori Jahve: \'Gle, brišem te s lica zemlje! Umrijet ćeš još ove godine, jer si propovijedao pobunu protiv Jahve!\'\"');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (30, 28, 17, 'I umrije prorok Hananija te godine u sedmom mjesecu.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (30, 29, 1, 'Evo, ovo su riječi poslanice koju prorok Jeremija iz Jeruzalema posla Ostatku izgnanstva - starješinama, svećenicima i prorocima i svemu preostalom narodu što ga Nabukodonozor iz Jeruzalema bijaše odveo u Babilon,');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (30, 29, 2, 'pošto kralj Jekonija i kraljica-majka, dvorjanici, odličnici judejski i jeruzalemski, kovači i bravari ostaviše Jeruzalem.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (30, 29, 3, 'Poslanica je poslana po Elasi, sinu Šafanovu, i Gemarji, sinu Hilkijinu, koje Sidkija, kralj judejski, posla u Babilon Nabukodonozoru, kralju babilonskom. Evo sadržaja:');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (30, 29, 4, '\"Ovako govori Jahve nad Vojskama, kralj Izraelov: \'Svima izgnanicima koje odvedoh iz Jeruzalema u Babilon!');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (30, 29, 5, 'Gradite kuće i nastanite se, sadite vrtove i uživajte urod njihov!');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (30, 29, 6, 'Ženite se i rađajte sinove i kćeri! Ženite svoje sinove i udajite svoje kćeri da i oni rađaju sinove i kćeri! Množite se da se ne smanjite!');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (30, 29, 7, 'Ištite mir zemlji u koju vas izagnah, molite se za nju Jahvi, jer na njezinu miru počiva i vaš mir!\'');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (30, 29, 8, 'Ovako govori Jahve nad Vojskama, Bog Izraelov: \'Ne dajte da vas obmanjuju vaši proroci koji su među vama, vaši gataoci! Ne povodite se za snovima koje oni sanjaju!');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (30, 29, 9, 'Jer oni vam laž prorokuju u moje ime, a ja ih nisam poslao\' - riječ je Jahvina.\"');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (30, 29, 10, 'Jer ovako govori Jahve: \'Istom kad se Babilonu ispuni onih sedamdeset godina, ja ću vas pohoditi te vam ispuniti dobro obećanje da ću vas vratiti na ovo mjesto.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (30, 29, 11, 'Jer ja znam svoje naume koje s vama namjeravam - riječ je Jahvina - naume mira, a ne nesreće: da vam dadnem budućnost i nadu.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (30, 29, 12, 'Tada ćete me zazivati, dolaziti k meni, moliti mi se i ja ću vas uslišati.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (30, 29, 13, 'Tražit ćete me i naći me jer ćete me tražiti svim srcem svojim.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (30, 29, 14, 'I pustit ću da me nađete - riječ je Jahvina. Izmijenit ću udes vaš i sabrati vas iz svih naroda i sa svih mjesta kamo vas odagnah - riječ je Jahvina. I vratit ću vas na mjesto odakle vas u izagnanstvo odvedoh.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (30, 29, 15, 'Istina, vi velite: \'Jahve nam podiže proroke u Babilonu.\'');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (30, 29, 16, 'Ovako govori Jahve kralju koji sjedi na prijestolju Davidovu, i svemu narodu koji živi u ovome gradu - braći vašoj što ne moradoše s vama u izgnanstvo.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (30, 29, 17, 'Ovako govori Jahve nad Vojskama: \"Evo šaljem na njih mač, glad i kugu; učinit ću da budu kao pokvarene smokve, tako loše da nisu za jelo.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (30, 29, 18, 'I gonit ću ih mačem, glađu i kugom i učinit ću ih užasom svim kraljevstvima zemaljskim, prokletstvom, strahotom, ruglom i sramotom svim narodima kamo ih otjeram.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (30, 29, 19, 'Jer ne poslušaše riječi mojih - riječ je Jahvina - premda sam im svejednako slao sluge svoje proroke, ali ih oni ne poslušaše - riječ je Jahvina.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (30, 29, 20, 'Ali vi, izgnanici, koje poslah iz Jeruzalema u Babilon, poslušajte svi riječ Jahvinu!\"');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (30, 29, 21, 'Ovako govori Jahve nad Vojskama, kralj Izraelov, o Ahabu, sinu Kolajinu, i o Sidkiji, sinu Maasejinu, koji vam laž prorokuje u moje ime: \"Evo, predajem ih u ruke Nabukodonozora, kralja babilonskoga, da ih pogubi vama na oči.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (30, 29, 22, 'I njima će se kao kletvom proklinjati svi izgnanici koji su u Babilonu: \'Neka Jahve učini s tobom kao sa Sidkijom i Ahabom koje kralj babilonski ispeče na vatri');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (30, 29, 23, 'jer u Izraelu počiniše sramotu čineći preljub sa ženama svojih bližnjih i govoreći u moje ime lažne riječi koje im ja nisam zapovjedio. Ja to znam, i svjedok sam tome\' - riječ je Jahvina!\"');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (30, 29, 24, '-');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (30, 29, 25, 'A Šemaji ćeš Nehelamcu poručiti: \"Ovako govori Jahve nad Vojskama, Bog Izraelov: Ti si u svoje ime poslao pisma svemu narodu koji je u Jeruzalemu, i svećeniku Sefaniji, sinu Maasejinu, i svim ostalim svećenicima:');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (30, 29, 26, '\'Jahve te postavi svećenikom namjesto svećenika Jojade da paziš u Domu Jahvinu na svakog luđaka koji se gradi prorokom i da ga baciš u klade, sa željezom oko vrata.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (30, 29, 27, 'Zašto, dakle, nisi spriječio Jeremiju iz Anatota, koji se među vama gradi prorokom?');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (30, 29, 28, 'TÓa on nam je poslao poruku u Babilon: Dugo će još trajati: Gradite kuće i nastanite se! Sadite vrtove i uživajte urod njihov!\'\"');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (30, 29, 29, 'Svećenik Sefanija pročita pismo proroku Jeremiji.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (30, 29, 30, 'Tada dođe riječ Jahvina Jeremiji:');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (30, 29, 31, '\"Pošalji svim izgnanicima ovu vijest: \'Ovako govori Jahve o Šemaji Nehelamcu: Jer vam Šemaja prorokuje te vam budi varave nade, premda ga ja nisam poslao,');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (30, 29, 32, 'ovako govori Jahve: Kaznit ću Šemaju Nehelamca, njega i potomstvo njegovo: nitko mu neće preostati usred ovoga naroda da doživi sreću koju spremam narodu svojemu - riječ je Jahvina - jer je propovijedao pobunu protiv Jahve.\'\"');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (30, 30, 1, 'Riječ koju Jahve upravi Jeremiji:');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (30, 30, 2, 'Ovako govori Jahve, Bog Izraelov: \"Upiši u knjigu sve ove riječi koje ti govorim.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (30, 30, 3, 'Jer evo dolaze dani - riječ je Jahvina - i promijenit ću udes naroda svoga Izraela i Judeje\" - govori Jahve - \"i vratit ću ih u zemlju koju u baštinu dadoh ocima njihovim.\"');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (30, 30, 4, 'Evo riječi što ih Jahve reče o Izraelu i o Judeji:');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (30, 30, 5, 'Ovako govori Jahve: \"Čujem krik užasa: strava je to, a ne mir.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (30, 30, 6, 'Hajde, propitajte se i pogledajte: je li ikad muškarac rodio? A svi se muškarci za bedra hvataju kao porodilje! Zašto su sva lica izobličena i problijedjela?');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (30, 30, 7, 'Jao, jer velik je dan ovaj, slična mu nÓe bÄi! Vrijeme je nevolje za Jakova, al\' će se izbaviti iz nje.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (30, 30, 8, 'Onoga dana - riječ je Jahve nad Vojskama - slomit ću jaram na njihovu vratu i lance ću njihove raskinuti. Više neće služiti tuđinu,');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (30, 30, 9, 'već će služiti Jahvi, Bogu svojemu, i Davidu, kralju svome, koga ću im podići.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (30, 30, 10, 'Ne boj se, Jakove, slugo moja - riječ je Jahvina - ne plaši se, Izraele! Jer evo, spasit ću te izdaleka i potomstvo tvoje iz zemlje izgnanstva. Jakov će se opet smiriti, spokojno će živjeti i nitko ga neće plašiti - riječ je Jahvina -');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (30, 30, 11, 'jer ja sam s tobom da te izbavim. Zatrt ću narode među koje te prognah, a tebe neću sasvim uništiti; al\' ću te kazniti po pravici, ne smijem te pustit\' nekažnjena.\"');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (30, 30, 12, 'Uistinu, ovako govori Jahve: \"Neiscjeljiva je rana tvoja, neprebolan polom tvoj.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (30, 30, 13, 'Nema lijeka rani tvojoj i nikako da zaraste.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (30, 30, 14, 'Zaboraviše te svi ljubavnici, više za te i ne pitaju! Jer po tebi ja udarih k\'o što udara neprijatelj, kaznom krutom za bezakonje i za mnoge grijehe tvoje.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (30, 30, 15, 'Zašto kukaš zbog rane svoje? Zar je neizlječiva tvoja bol? Zbog mnoštva bezakonja i grijeha silnih tvojih to ti učinih.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (30, 30, 16, 'Al\' i oni što te žderu bit će prožderani, u ropstvo će svi dušmani tvoji; pljačkaši tvoji bit će opljačkani, i koji te plijeniše bit će oplijenjeni.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (30, 30, 17, '[17b] Zvahu te \'Protjeranom\' i \'Sionkom za koju nitko ne pita\'. [17a] Al\' ja ću te iscijeliti, rane ti zaliječiti\" - riječ je Jahvina.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (30, 30, 18, 'Ovako govori Jahve: \"Evo, izmijenit ću udes šatora Jakovljevih, smilovat ću se na stanove njegove: na razvalinama njegovim bit će opet grad sazidan, i dvori će stajati na starome mjestu.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (30, 30, 19, 'Iz njih će se čuti hvalospjev, i glasovi radosni. Umnožit ću ih i više im se neće smanjiti broj, ugled ću im dati i više ih neće prezirati.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (30, 30, 20, 'Sinovi njihovi bit će mi kao nekoć, zajednica njina preda mnom će čvrsto stajati, a kaznit ću sve njihove ugnjetače.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (30, 30, 21, 'Glavar njihov iz njih će niknuti, vladar njihov isred njih će izaći. Pustit ću ga k sebi da mi se približi - jer tko da se usudi sam preda me!\" - riječ je Jahvina.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (30, 30, 22, '\"I vi ćete biti moj narod, a ja vaš Bog.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (30, 30, 23, 'Gle, nevrijeme Jahvino, jarost provaljuje, razmahuje se vihor silan, i svaljuje na glave bezbožničke.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (30, 30, 24, 'Jahvin se gnjev neće stišati dok on ne izvrši i ne ispuni naume srca svojega. U dane posljednje jasno ćete to razumjeti.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (30, 31, 1, '\"U ono vrijeme - riječ je Jahvina - bit ću Bog svim plemenima Izraelovim i oni će biti narod moj.\"');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (30, 31, 2, 'Ovako govori Jahve: \"Nađe milost u pustinji narod koji uteče maču: Izrael ide u svoje prebivalište.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (30, 31, 3, 'Iz daljine mu se Jahve ukaza: Ljubavlju vječnom ljubim te, zato ti sačuvah milost.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (30, 31, 4, 'Opet ću te sazdati, i bit ćeš sazdana, djevice Izraelova. Opet ćeš se resit\' bubnjićima, u veselo kolo hvatati.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (30, 31, 5, 'Opet ćeš saditi vinograde na brdima Samarije: koji nasade posade, oni će i trgati.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (30, 31, 6, 'Jer dolazi dan te će stražari vikati na brdu efrajimskom: \'Na noge! Na Sion se popnimo, k Jahvi, Bogu svojemu!\'\"');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (30, 31, 7, 'Jer ovako govori Jahve: \"Kličite od radosti Jakovu, pozdravite burno prvaka naroda! Neka se ori vaš glas! Objavite slavopojkom: Jahve spasi narod svoj, Ostatak Izraelov!');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (30, 31, 8, 'Evo, ja ih vodim iz zemlje sjeverne, skupljam ih s krajeva zemlje: s njima su slijepi i hromi, trudnice i rodilje: vraća se velika zajednica.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (30, 31, 9, 'Evo, u suzama pođoše, utješene sad ih vraćam! Vodit ću ih kraj potočnih voda, putem ravnim kojim neće posrnuti, jer ja sam otac Izraelu, Efrajim je moj prvenac.\"');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (30, 31, 10, 'Čujte, o narodi, riječ Jahvinu, objavite je širom dalekih otoka: \"Onaj što rasprši Izraela, opet ga sabire i čuva ga k\'o pastir stado svoje!\"');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (30, 31, 11, 'Jer Jahve oslobodi Jakova, izbavi ga iz ruku jačeg od njega.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (30, 31, 12, 'I oni će, radosno kličući, na vis sionski da se naužiju dobara Jahvinih: žita, ulja, mladog vina, jagnjadi i teladi, duša će im biti kao vrt navodnjen, nikad više neće ginuti.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (30, 31, 13, 'Djevojke će se veselit\' u kolu, mlado i staro zajedno, jer ću im tugu u radost pretvoriti, utješit ću ih i razveselit\' nakon žalosti.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (30, 31, 14, 'Pretilinom ću im okrijepiti svećenstvo i narod svoj nasititi dobrima\" - riječ je Jahvina.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (30, 31, 15, 'Ovako govori Jahve: \"Čuj! U Rami se kukanje čuje i gorak plač: Rahela oplakuje sinove svoje, i neće da se utješi za djecom, jer njih više nema.\"');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (30, 31, 16, 'Ovako govori Jahve: \"Prestani kukati, otari suze u očima! Patnje će tvoje biti nagrađene: oni će se vratiti iz zemlje neprijateljske.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (30, 31, 17, 'Ima nade za tvoje potomstvo - riječ je Jahvina - sinovi tvoji vratit će se u svoj kraj.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (30, 31, 18, 'Dobro čujem Efrajimov jecaj: \'Ti me pokara, i ja se popravih kao june još neukroćeno. Obrati me, da se obratim, jer ti si, Jahve, Bog moj.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (30, 31, 19, 'Odvratih se od tebe, ali se pokajah, uvijek, i sad se u slabine tučem. Stidim se i crvenim, jer nosim sramotu mladosti svoje!\'\"');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (30, 31, 20, '\"Zar mi je Efrajim sin toliko drag, dijete najmilije? Jer koliko god mu prijetim, bez prestanka živo na njega mislim i srce mi dršće za njega od nježne samilosti\" - riječ je Jahvina.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (30, 31, 21, '\"Postavi putokaze, podigni stupove! Sjeti se ceste, puta kojim si prošla. I vrati se, djevice Izraelova, vrati se u gradove svoje!');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (30, 31, 22, 'Dokle ćeš još oklijevati, kćeri odmetnice? Jer Jahve stvori nešto novo na zemlji: Žena će okružiti Muža.\"');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (30, 31, 23, 'Ovako govori Jahve nad Vojskama, Bog Izraelov: \"U zemlji Judinoj, kad promijenim njezinu sudbinu, u njezinim će se gradovima ovako govoriti: \'Blagoslovio te Jahve, prebivalište Pravednosti, Goro sveta!\'\"');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (30, 31, 24, '\"I u njoj će se opet nastaniti Judeja sa svim svojim gradovima, ratari i oni što idu za stadima,');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (30, 31, 25, 'jer ja ću okrijepiti dušu iscrpljenu, obilno nahraniti dušu klonulu.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (30, 31, 26, 'Kao ono: \'Čim se probudih, pogledah: sladak li bijaše sanak moj!\'\"');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (30, 31, 27, '\"Evo dolaze dani - riječ je Jahvina - kad ću u domu Izraelovu i u domu Judinu posijati sjeme čovječje i sjeme životinjsko.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (30, 31, 28, 'I kao što sam nekoć bdio da ih iščupam, razvalim, istrijebim, zatrem i nesreću na njih svalim, tako ću sada brižno bdjeti da ih podignem i posadim.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (30, 31, 29, 'U one dane neće se više govoriti: \'Oci jedoše kiselo grožđe, a sinovima zubi trnu.\'');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (30, 31, 30, 'Nego će svatko umrijeti zbog vlastite krivice. I onomu koji bude jeo kiselo grožđe zubi će trnuti.\"');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (30, 31, 31, '\"Evo dolaze dani - riječ je Jahvina - kad ću s domom Izraelovim i s domom Judinim sklopiti Novi savez.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (30, 31, 32, 'Ne Savez kakav sam sklopio s ocima njihovim u dan kad ih uzeh za ruku da ih izvedem iz zemlje egipatske, Savez što ga oni razvrgoše premda sam ja gospodar njihov - riječ je Jahvina.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (30, 31, 33, 'Nego, ovo je Savez što ću ga sklopiti s domom Izraelovim poslije onih dana - riječ je Jahvina: Zakon ću svoj staviti u dušu njihovu i upisati ga u njihovo srce. I bit ću Bog njihov, a oni narod moj.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (30, 31, 34, 'I neće više učiti drug druga ni brat brata govoreći: \'Spoznajte Jahvu!\' nego će me svi poznavati, i malo i veliko - riječ je Jahvina - jer ću oprostiti bezakonje njihovo i grijeha se njihovih neću više spominjati.\"');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (30, 31, 35, 'Ovako govori Jahve, koji daje da sunce sjaje danju, a mjesec i zvijezde da svijetle noću, koji burka more da mu valovi buče - ime mu je Jahve nad Vojskama:');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (30, 31, 36, '\"Ako se ikad ti zakoni poremete preda mnom - riječ je Jahvina - onda će i potomstvo Izraelovo prestati da bude narod pred licem mojim zauvijek!');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (30, 31, 37, 'Ako se mogu izmjeriti nebesa gore, i dolje istražiti temelji zemlje, onda ću i ja odbaciti potomstvo Izraelovo zbog svega što počiniše\" - riječ je Jahvina.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (30, 31, 38, '\"Evo dolaze dani - riječ je Jahvina - kada će grad Jahvin biti opet sazidan, od Kule Hananelove do Vrata ugaonih.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (30, 31, 39, 'I još će se dalje protegnuti mjerničko uže, pravo do brežuljka Gareba, a onda okrenuti prema Goi.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (30, 31, 40, 'I sva dolina trupla i pepela, i sva polja do potoka Kidrona, do ugla Konjskih vrata na istoku, bit će svetinja Jahvina. I neće više biti razaranja ni prokletstva.\"');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (30, 32, 1, 'Riječ koju Jahve uputi Jeremiji desete godine Sidkije, kralja judejskoga, to jest osamnaeste godine Nabukodonozorove.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (30, 32, 2, 'U to vrijeme vojska kralja babilonskoga opsjedaše Jeruzalem, a prorok Jeremija bijaše zatvoren u tamničkom dvorištu u dvoru judejskoga kralja.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (30, 32, 3, 'Sidkija, kralj judejski, bijaše ga ondje zatvorio, prigovoriv mu: \"Zašto si prorokovao: \'Ovako govori Jahve: Gle, grad ću ovaj predati u ruke kralju babilonskom da ga osvoji;');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (30, 32, 4, 'a Sidkija, kralj judejski, neće umaći sili kaldejskoj, nego će biti predan u ruke kralja babilonskoga - usta u usta s njim će govoriti, oči u oči njega vidjeti.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (30, 32, 5, 'Sidkiju će odvesti u Babilon i ondje će ostati dok ga ne pohodim - riječ je Jahvina! I ako se budete borili protiv Kaldejaca, nećete uspjeti!\'\"');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (30, 32, 6, 'Tada reče Jeremija: \"Dođe mi riječ Jahvina:');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (30, 32, 7, '\'Uskoro će doći k tebi Hanamel, sin tvoga strica Šaluma, da ti kaže: Kupi njivu moju u Anatotu; ti imaš rodbinsko pravo da je kupiš!\'');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (30, 32, 8, 'Kako je Jahve navijestio, k meni dođe moj stričević Hanamel u tamničko dvorište i reče mi: \'De kupi moju njivu u Anatotu, jer ti imaš pravo na posjed i rodbinsko pravo da je kupiš! Kupi je!\' I tada spoznah da to bijaše riječ Jahvina.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (30, 32, 9, 'Kupih, dakle, tu njivu od stričevića Hanamela iz Anatota te mu izmjerih u novcu sedamnaest šekela srebra.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (30, 32, 10, 'Napišem ugovor, udarim pečat, pozovem svjedoke i izmjerim novac na tezulji.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (30, 32, 11, 'Zatim uzmem kupovni ugovor, zapečaćen prema propisu i uredbama,');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (30, 32, 12, 'predam kupovni ugovor Baruhu, sinu Mahsejeva sina Nerije. Nazočni su bili: moj stričević Hanamel, svjedoci što su potpisali kupovni ugovor i svi Judejci koji su se našli u tamničkom dvorištu.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (30, 32, 13, 'Tada pred njima zapovjedim Baruhu:');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (30, 32, 14, '\'Ovako govori Jahve nad Vojskama, Bog Izraelov: Uzmi ove isprave, ovaj kupovni ugovor, zapečaćeni i otvoreni, i stavi ih u glinenu posudu da se zadugo sačuvaju.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (30, 32, 15, 'Jer ovako govori Jahve nad Vojskama, Bog Izraelov: Još će se u ovoj zemlji kupovati i kuće, i njive, i vinogradi!\'\"');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (30, 32, 16, 'Pošto kupovni ugovor predadoh Nerijinu sinu Baruhu, pomolih se Jahvi:');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (30, 32, 17, '\"O, Jahve, Gospode! Ti stvori nebo i zemlju snagom velikom, rukom uzdignutom! Ništa tebi nije nemoguće!');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (30, 32, 18, 'Tisućama iskazuješ milost, a krivnju otaca osvećuješ na djeci, potomcima njihovim. Bože veliki i moćni, kome je ime Jahve nad Vojskama!');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (30, 32, 19, 'Velik si u svojim naumima, silan u svojim djelima! Oči tvoje bde nad svim putovima ljudskim da naplatiš svakome prema putu njegovu i prema plodu djela njegovih!');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (30, 32, 20, 'Ti koji si činio znamenja i čudesa u zemlji egipatskoj i u Izraelu, i među svim ljudima sve do danas,');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (30, 32, 21, 'ti si izveo svoj narod izraelski iz zemlje egipatske znamenjima i čudesima, rukom moćnom i mišicom podignutom, strahotama velikim.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (30, 32, 22, 'Zatim im dade svu ovu zemlju koju si zakletvom obećao ocima njihovim, zemlju u kojoj teče med i mlijeko.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (30, 32, 23, 'I oni je zaposjedoše; ali nisu slušali glasa tvojega niti su hodili putem Zakona tvojega. Ništa ne učiniše od onog što im ti naredi; zato si dozvao na njih sve ove nevolje.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (30, 32, 24, 'Gle, nasipi se već primakoše gradu, i bit će osvojen, i grad će pasti u ruke Kaldejcima koji na nj navaljuju mačem, glađu i kugom. Čime si prijetio, evo dolazi. I sam vidiš.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (30, 32, 25, 'A ti mi, Jahve Gospode moj, reče: \'Kupi novcem njivu i pozovi svjedoke\', a grad je već predan u ruke Kaldejcima!\"');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (30, 32, 26, 'Tada mi dođe riječ Jahvina:');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (30, 32, 27, '\"Gle, ja sam Jahve, Bog svakoga tijela! Meni ništa nije nemoguće!');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (30, 32, 28, 'Zato - veli Jahve - grad ovaj predajem u ruke Kaldejaca i u ruke kralja babilonskoga, koji će ga zauzeti.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (30, 32, 29, 'Ući će u nj Kaldejci koji se bore protiv ovoga grada, ognjem će ga uništiti i spaliti ga zajedno s kućama kojima su na krovovima Baalu palili tamjan i lijevali ljevanice tuđim bogovima, mene gnjeveći.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (30, 32, 30, 'Jer sinovi Izraelovi i sinovi Judini od mladosti čine samo zlo pred mojim očima. Doista, sinovi Izraelovi bez prestanka me gnjeve djelima ruku svojih - riječ je Jahvina.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (30, 32, 31, 'Grad ovaj, doista, samo mi je na gnjev i srdžbu otkako je sagrađen pa do dana današnjega te ga moram ukloniti ispred lica svojega');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (30, 32, 32, 'zbog svega bezakonja što ga sinovi Izraelovi i sinovi Judini počiniše, gnjeveći me - oni i kraljevi njihovi, knezovi i svećenici i proroci, Judejci i Jeruzalemci.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (30, 32, 33, 'Okretahu mi leđa, a ne lice svoje, iako se neumorno trudih da ih poučim, ali me ne slušaše niti nauk moj primiše.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (30, 32, 34, 'Postaviše grozote u Dom koji se mojim zove imenom da ga oskvrnu.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (30, 32, 35, 'Baalu podigoše uzvišice u Dolini Ben Hinomu, i sinove i kćeri svoje Moleku kroz oganj provodiše - što im ja nikad ne zapovjedih; ni na um mi ne pade da bi činili takve gadosti niti da bih Judu pustio u takav grijeh.\"');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (30, 32, 36, 'Ipak, ovako govori Jahve, Bog Izraelov, o tom gradu za koji vi velite da će od mača, gladi i kuge pasti u ruke kralju babilonskom:');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (30, 32, 37, '\"Evo, ja ću ih sabrati iz svih zemalja u koje ih prognah - u gnjevu i jarosti svojoj - i vratit ću ih na ovo mjesto da ovdje spokojno žive.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (30, 32, 38, 'I oni će biti narod moj, a ja, ja ću biti Bog njihov.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (30, 32, 39, 'I dat ću im srce jedno i put jedan, da bi me se bojali u sve dane, na sreću svoju i djece svoje.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (30, 32, 40, 'I sklopit ću s njima Savez vječan, nikad se više neću odvratiti od njih i uvijek ću im činiti dobro; usadit ću im u srce svoj strah, da se nikad više ne odmetnu od mene.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (30, 32, 41, 'I radovat ću se čineći im dobro; i čvrsto ću ih zasaditi u ovoj zemlji, svim srcem svojim, svom dušom svojom.\"');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (30, 32, 42, 'Jer ovako govori Jahve: \"Kao što sam na ovaj narod doveo svu ovu strašnu nesreću, tako ću na njih dovesti svu sreću koju im obrekoh.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (30, 32, 43, 'Da, opet će se kupovati njive u ovoj zemlji o kojoj vi velite: \'Ova je pustinja, bez čovjeka i živinčeta, predana na milost i nemilost Kaldejcima!\'');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (30, 32, 44, 'Njive će se za novac kupovati, pisat će se i pečatiti kupovni ugovori, pozivat će se svjedoci u zemlji Benjaminovoj i u okolici Jeruzalema. U gradovima Judinim i u gradovima Gorja, Šefele, Negeba, jer ću promijeniti udes njihov\" - riječ je Jahvina.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (30, 33, 1, 'Dok je Jeremija bio još zatvoren u tamničkom dvorištu, i drugi mu put dođe riječ Jahvina:');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (30, 33, 2, '\"Ovako govori Jahve, koji stvori zemlju, oblikova je i učvrsti - ime mu je Jahve!');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (30, 33, 3, 'Zazovi me, i odazvat ću ti se i objavit ću ti velike i nedokučive tajne o kojima ništa ne znaš.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (30, 33, 4, 'Jer ovako govori Jahve, Bog Izraelov, o kućama ovoga grada i o dvorima kraljeva judejskih, porušenim zbog nasipa i mača,');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (30, 33, 5, 'i o onima što zameću borbu s Kaldejcima da napune svoje kuće tjelesima ljudi koje pobih u srdžbi i jarosti svojoj, i odvratih lice svoje od ovoga grada zbog njihove opakosti.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (30, 33, 6, 'Evo, ja ću zaliječiti njihovu ranu, ja ću ih iscijeliti i ozdraviti i pružiti im obilje istinskoga mira.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (30, 33, 7, 'Promijenit ću udes zemlje Judine i Jeruzalema i podići ću ih da budu kao nekoć.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (30, 33, 8, 'Očistit ću ih od svakoga grijeha kojim sagriješiše protiv mene i oprostit ću im sve krivice koje mi skriviše odmetnuv se od mene.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (30, 33, 9, 'I Jeruzalem će mi biti na radost, na hvalu i čast pred svim narodima svijeta: kad čuju za sve dobro kojim ću ih nadijeliti, divit će se i čuditi svoj onoj sreći i miru što ću im ja dati.\"');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (30, 33, 10, 'Ovako govori Jahve: \"Na ovome mjestu o kojemu vi velite: \'To je pustinja bez čovjeka i bez živinčeta\' - u gradovima judejskim i po opustošenim ulicama jeruzalemskim opet će se oriti');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (30, 33, 11, 'poklici radosti, poklici zaručnika i zaručnice, poklici onih koji će u Domu Jahvinu prinositi žrtve zahvalnice pjevajući: \'Hvalite Jahvu nad Vojskama, jer je dobar Jahve - vječna je ljubav njegova!\' Jer ja ću obnoviti zemlju da bude kao nekoć\" - riječ je Jahvina.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (30, 33, 12, 'Ovako govori Jahve nad Vojskama: \"Na ovome mjestu koje je sada pusto, bez čovjeka i bez živinčeta, i u svim gradovima opet će biti pašnjaci za pastire što odmaraju stada svoja.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (30, 33, 13, 'U gradovima Gorja, i u gradovima Šefele, i u gradovima Negeba, u kraju Benjaminovu, u okolici Jeruzalema i u gradovima Judinim opet će prolaziti ovce ispod ruke pastira koji će ih brojiti\" - riječ je Jahvina.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (30, 33, 14, '\"Evo, dolaze dani - riječ je Jahvina - kad ću ispuniti dobro obećanje što ga dadoh domu Izraelovu i domu Judinu:');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (30, 33, 15, 'U one dane i u vrijeme ono podići ću Davidu izdanak pravedni; on će zemljom vladati po pravu i pravici.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (30, 33, 16, 'U one dane Judeja će biti spašena, Jeruzalem će živjeti spokojno. A grad će se zvati: \'Jahve, Pravda naša.\'');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (30, 33, 17, 'Jer ovako govori Jahve: \"Nikada Davidu neće nestati potomka koji će sjediti na prijestolju doma Izraelova.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (30, 33, 18, 'I nikada neće levitima i svećenicima nestati potomaka koji će služiti preda mnom i prinositi paljenice, kaditi prinosnice i prikazivati klanice u sve dane.\"');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (30, 33, 19, 'I dođe riječ Jahvina Jeremiji:');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (30, 33, 20, 'Ovako govori Jahve: \"Ako možete razvrći savez moj s danom i savez moj s noći, tako da ni dana ni noći više ne bude u pravo vrijeme,');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (30, 33, 21, 'moći će se raskinuti i Savez moj sa slugom mojim Davidom te više neće imati sina koji bi kraljevao na prijestolju njegovu i s levitima i svećenicima koji mi služe.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (30, 33, 22, 'Kao što se vojska nebeska ne može izbrojiti ni izmjeriti pijesak morski, tako ću umnožiti potomstvo sluge svojega Davida i levite i svećenike koji mi služe.\"');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (30, 33, 23, 'I dođe riječ Jahvina Jeremiji:');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (30, 33, 24, '\"Nisi li opazio što ovi ljudi govore: \'Jahve je odbacio obadva plemena koja je bio sebi izabrao?\' I s prezirom poriču narod moj kao da mi više nije narod.\"');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (30, 33, 25, 'Ovako govori Jahve: \"Da ne sklopih saveza svojega s danom i noći i da ne postavih zakone nebu i zemlji,');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (30, 33, 26, 'mogao bih odbaciti potomstvo Jakova i Davida, sluge svojega, da više ne uzimam potomka njihova za vladara nad potomstvom Abrahamovim, Izakovim i Jakovljevim, kad promijenim udes njihov i kad im se smilujem.\"');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (30, 34, 1, 'Riječ koju Jahve uputi Jeremiji kad Nabukodonozor, kralj babilonski, i sva njegova vojska, i sva kraljevstva pod njegovom vlašću, i svi narodi navališe na Jeruzalem i na sve gradove njegove.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (30, 34, 2, 'Ovako govori Jahve, Bog Izraelov: \"Idi i govori sa Sidkijom, kraljem judejskim, i reci mu: Ovako govori Jahve: \'Evo, predajem ovaj grad u ruke kralja babilonskoga da ga on ognjem spali.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (30, 34, 3, 'Ni ti nećeš ruci njegovoj umaći. Da, bit ćeš uhvaćen i predat će te u njegove ruke; oči u oči gledat ćeš kralja babilonskoga, usta u usta on će s tobom govoriti i bit ćeš odveden u Babilon.\'');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (30, 34, 4, 'Ali čuj riječ Jahvinu, Sidkija, kralju judejski! Ovo ti poručuje Jahve: \'Nećeš od mača poginuti,');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (30, 34, 5, 'umrijet ćeš u miru! I kao što su tvoje očeve i kraljeve tvoje prethodnike okadili, i tebe će okaditi i naricat će za tobom: \'Jao Gospodaru!\' Ja ti to govorim\' - riječ je Jahvina.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (30, 34, 6, 'I prorok Jeremija poruči sve ove riječi Sidkiji, kralju judejskom u Jeruzalemu,');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (30, 34, 7, 'dok je vojska kralja babilonskoga navaljivala na Jeruzalem i na preostale gradove Judine - na Lakiš i Azeku, jer još samo oni preostadoše od judejskih utvrđenih gradova.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (30, 34, 8, 'Riječ koju Jahve uputi Jeremiji, pošto je kralj Sidkija sa svekolikim narodom jeruzalemskim sklopio savez da im proglasi slobodu,');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (30, 34, 9, 'da svaki pusti na slobodu svoga roba Hebreja i svoju robinju Hebrejku te da više ni u koga ne bude Hebrej, brat njegov, kao rob.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (30, 34, 10, 'I svi odličnici i sav narod koji uđoše u ovaj savez pristadoše te svaki pusti na slobodu roba svoga i svoju ropkinju da im više ne robuju. Pristadoše, dakle, i pustiše ih.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (30, 34, 11, 'A potom se okrenuše i uzeše opet svoje robove i ropkinje koje bijahu oslobodili pa ih prisiliše da im opet robuju.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (30, 34, 12, 'Tada Jahve uputi riječ Jeremiji govoreći:');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (30, 34, 13, 'Ovako govori Jahve, Bog Izraelov: \"Ja sam sklopio Savez s ocima vašim u dan kada ih izvedoh iz Egipta, iz zemlje ropstva, govoreći:');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (30, 34, 14, '\'Nakon sedam godina neka svaki od vas pusti na slobodu brata svoga Hebreja koji mu se prodao i šest godina kao rob služio.\' Ali me vaši oci ne poslušaše i ne htjedoše me čuti.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (30, 34, 15, 'A vi se bijaste obratili i učinili što je pravo u očima mojim, proglasivši slobodu za svakoga bližnjega svoga i preda mnom ste sklopili savez u Domu koji se zove mojim imenom.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (30, 34, 16, 'A zatim se okrenuste i oskvrnuste ime moje, jer je svaki od vas opet uveo svoga roba i ropkinju koje ste već bili oslobodili, i ponovo ste ih prisilili da vam robuju.\"');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (30, 34, 17, 'Zato ovako govori Jahve: \"Vi me ne poslušaste da proglasite slobodu subratu svojemu i bližnjemu. I zato, evo, i ja proglašavam protiv vas slobodu - riječ je Jahvina - maču, kugi i gladi, i učinit ću vas strašilom svim kraljevstvima zemlje.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (30, 34, 18, 'A s ljudima koji razvrgoše Savez moj i ne ispuniše saveza obećana pred mojim licem postupit ću kao s teletom što ga nadvoje rasjekoše te između tih pola prođoše.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (30, 34, 19, 'Knezove Judeje i Jeruzalema, dvorjane, svećenike i sav narod zemlje što prođoše između pola telećih');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (30, 34, 20, 'predat ću u ruke dušmana koji im rade o glavi, a njihova trupla bit će hrana pticama nebeskim i zvijerima zemaljskim.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (30, 34, 21, 'Sidkiju, kralja judejskoga, i njegove knezove predat ću u ruke dušmana koji im rade o glavi i u ruke vojske kralja babilonskoga, koja se od vas bila povukla.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (30, 34, 22, 'Evo, ja ću im zapovjediti - riječ je Jahvina - i vratit ću ih na ovaj grad, i navalit će na nj, osvojiti ga i ognjem spaliti. A gradove judejske obratit ću u pustinju nenastanjenu.\"');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (30, 35, 1, 'Jahve uputi riječ Jeremiji u dane Jojakima, sina Jošijina, kralja judejskoga:');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (30, 35, 2, '\"Idi u zajednicu Rekabovaca, govori s njima i dovedi ih u Dom Jahvin, u jednu od dvorana, i daj im vina.\"');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (30, 35, 3, 'Tada dovedoh Jaazaniju, sina Habasinijina sina Jeremije, njegovu braću i sve sinove njegove i sav dom Rekabovaca');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (30, 35, 4, 'i dovedoh ih u Dom Jahvin, u dvoranu čovjeka Božjega Ben Johanana, sina Jigdalijina, koja je kraj dvorane kneževske, a nad dvoranom vratara Maaseje, sina Šalumova.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (30, 35, 5, 'Zatim stavih pred sinove doma Rekabova krčage pune vina i čaše te im rekoh: \"Pijte vina!\"');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (30, 35, 6, 'Ali oni odgovoriše: \"Ne pijemo vina, jer nam je otac naš Jonadab, sin Rekabov, zapovjedio: \'Ne smijete nikada piti vina, ni vi ni sinovi vaši.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (30, 35, 7, 'Niti smijete graditi kućÄa, niti sijati sjemena ni saditi vinogradÄa, niti ih posjedovati, nego provodite sav život pod šatorima, da dugo živite u zemlji gdje kao stranci boravite.\'');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (30, 35, 8, 'I mi poslušasmo glas oca Jonadaba, sina Rekabova, u svem što nam je zapovjedio: da nikad vina ne pijemo, ni mi ni žene naše, niti sinovi naši, ni kćeri naše,');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (30, 35, 9, 'da ne gradimo kuća, ni da posjedujemo vinograda ni polja zasijanih,');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (30, 35, 10, 'da stanujemo pod šatorima i držimo se poslušno svega što nam zapovjedi naš otac Jonadab.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (30, 35, 11, 'Samo kada je Nabukodonozor, kralj babilonski, krenuo protiv ove zemlje, rekosmo: \'Hajdemo, pođimo u Jeruzalem da izbjegnemo vojsku kaldejsku i vojsku aramejsku!\' I tako sada živimo u Jeruzalemu.\"');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (30, 35, 12, 'Tada dođe riječ Jahvina Jeremiji:');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (30, 35, 13, 'Ovako govori Jahve nad Vojskama, kralj Izraelov: \"Idi i objavi Judejcima i Jeruzalemcima: \'Zar nećete primiti nauka moga i poslušati riječi moje?\' - riječ je Jahvina. -');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (30, 35, 14, '\'Ispunjuju se riječi Jonadaba, sina Rekabova, koji je sinovima svojim zabranio da piju vina, i do dana današnjega nitko ga nije pio, jer oni slušaju riječ svoga oca. A ja sam vam jednako govorio, ali me niste slušali.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (30, 35, 15, 'I slao sam bez prestanka k vama sluge svoje, proroke, da vam propovijedaju: \'Vratite se svaki sa svoga opakog puta, popravite djela svoja i ne trčite za tuđim bogovima da im služite, pa ćete ostati u zemlji koju dadoh vama i ocima vašim\'; ali ne prikloniste uha svojega i ne poslušaste me.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (30, 35, 16, 'Sinovi Jonadaba, sina Rekabova, držahu se zapovijedi koju im dade otac njihov. Ali mene ovaj narod ne sluša.\'');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (30, 35, 17, 'Zato govori Jahve nad Vojskama, Bog Izraelov: \'Evo, navući ću na sve Jeruzalemce sve one nevolje kojima sam im zaprijetio, jer sam im govorio, a oni me ne slušahu, dozivao ih, ali se oni ne odazivahu.\'\"');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (30, 35, 18, 'Zajednici Rekabovaca Jeremija reče: \"Ovako govori Jahve nad Vojskama, Bog Izraelov: \'Jer ste slušali zapovijedi svoga oca Jonadaba i držali se svih naredaba i činili sve što vam je on zapovjedio,');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (30, 35, 19, 'zato - ovako govori Jahve nad Vojskama, kralj Izraelov - Jonadabu, sinu Rekabovu, nikad neće ponestati potomka koji će stajati pred licem mojim u sve dane.\'\"');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (30, 36, 1, 'Četvrte godine Jojakima, sina Jošijina, kralja judejskoga, uputi Jahve Jeremiji ovu riječ:');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (30, 36, 2, '\"Uzmi svitak i zapiši na nj sve riječi koje ti kazah o Jeruzalemu, Judeji i svim narodima, od dana kad ti počeh govoriti, od dana Jošijinih do dana današnjega.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (30, 36, 3, 'Možda će čuti dom Judin o svim nesrećama što sam ih naumio oboriti na njih te će se vratiti svaki sa svoga zlog puta, a ja ću im oprostiti krivicu i grijeh njihov.\"');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (30, 36, 4, 'Tada Jeremija dozva Baruha, sina Nerijina, i Baruh napisa na svitak, po kazivanju Jeremijinu, sve riječi koje mu Jahve bijaše objavio.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (30, 36, 5, 'Tada Jeremija naredi Baruhu: \"Meni nije slobodno te ne mogu poći u Dom Jahvin.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (30, 36, 6, 'Idi ti te na dan posta u Domu Jahvinu čitaj narodu riječi Jahvine iz svitka što si ga po mojem kazivanju napisao. Pročitaj ih i svim Judejcima koji su došli iz svojih gradova.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (30, 36, 7, 'Možda će se vapaji njihovi vinuti k Jahvi i možda će se obratiti svatko sa zloga puta svojega; jer je velik bijes i srdžba kojima Jahve prijeti ovom narodu.\"');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (30, 36, 8, 'I Baruh, sin Nerijin, učini sve kako mu prorok Jeremija bijaše zapovjedio da pročita riječi Jahvine u Domu Jahvinu.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (30, 36, 9, 'U petoj godini Jojakima, sina Jošijina, kralja judejskoga, mjeseca devetoga, pozvaše na post pred Jahvu sav narod jeruzalemski i sav narod što mogaše stići iz gradova judejskih u Jeruzalem.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (30, 36, 10, 'Baruh svemu narodu pročita riječi Jeremije iz svitka u Domu Jahvinu, u dvorani Gemarje, sina pisara Šafana, u gornjem predvorju pred Novim vratima Jahvina Doma.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (30, 36, 11, 'A kad Mikaj, sin Šafanova sina Gemarje, ču iz knjige sve Jahvine riječi,');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (30, 36, 12, 'siđe u kraljevski dvor u sobu pisarovu, gdje upravo sjeđahu svi dostojanstvenici: pisar Elišama, Delaja, sin Šemajin, Elnatan, sin Akborov, Gemarja, sin Šafanov, Sidkija, sin Hananijin, i svi drugi dostojanstvenici.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (30, 36, 13, 'Mikaj im kaza sve riječi što ih bijaše čuo kad ih je Baruh narodu čitao iz knjige.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (30, 36, 14, 'Tada dostojanstvenici poslaše Jehudija, sina Netanijina, i Šelemju, sina Kušijeva, Baruhu da mu kažu: \"Uzmi u ruke svitak iz kojega si čitao narodu i dođi!\" Tada Baruh, sin Nerijin, uze svitak u ruke i dođe k njima.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (30, 36, 15, 'Oni mi rekoše: \"Hajde, sjedi i pročitaj nam!\" I Baruh im pročita.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (30, 36, 16, 'Kad čuše sve one riječi, uplašeno se pogledaše i rekoše Baruhu: \"Moramo sve to kazati kralju.\"');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (30, 36, 17, 'I upitaše Baruha: \"Hajde, objasni nam kako ti napisa sve te riječi.\"');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (30, 36, 18, 'Baruh će njima: \"Jeremija mi je sve te riječi u pero kazivao, a ja sam ih crnilom u knjigu zapisao.\"');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (30, 36, 19, 'Tada dostojanstvenici rekoše Baruhu: \"Idi i sakrijte se, ti i Jeremija; nitko da ne zna gdje ste.\"');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (30, 36, 20, 'I, pohranivši svitak u dvorani pisara Elišame, pođoše kralju u dvorsko predvorje i sve mu ispripovjediše.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (30, 36, 21, 'Kralj posla Jehudija da donese svitak: on ga donese iz sobe pisara Elišame i pročita ga kralju i dostojanstvenicima koji stajahu oko njega.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (30, 36, 22, 'Kralj je sjedio u zimskim odajama - bijaše to u devetom mjesecu - a pred njim stajaše ražarena žeravnica.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (30, 36, 23, 'I kako bi Jehudi pročitao tri-četiri stupca, kralj bi ih rezao pisarskim perorezom i bacao u vatru na žeravnice sve dok cio svitak ne bi uništen u vatri žeravnice.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (30, 36, 24, 'Ni kralj ni njegove sluge ne prestrašiše se niti razderaše haljina kad čuše te riječi,');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (30, 36, 25, 'pa ipak Elnatan, Delaja i Gemarja moljahu kralja da ne spali svitak, ali on ih ne posluša.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (30, 36, 26, 'Tada kralj zapovjedi kraljeviću Jerahmeelu i Seraji, sinu Azrielovu, i Šelemji, sinu Abdeelovu, da uhvate pisara Baruha i proroka Jeremiju. Ali ih Jahve bijaše sakrio.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (30, 36, 27, 'Pošto je dakle kralj spalio svitak s riječima što ih Baruh bijaše zapisao po Jeremijinu kazivanju, dođe riječ Jahvina Jeremiji:');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (30, 36, 28, '\"Uzmi drugi svitak i upiši u nj sve one riječi što bijahu na prvom svitku koji je Jojakim, kralj judejski, spalio.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (30, 36, 29, 'A protiv Jojakima, kralja judejskoga, ovako reci: Ovako govori Jahve: Spalio si svitak govoreći: \'Zašto si u njemu napisao da će doći kralj babilonski koji će opustošiti zemlju ovu i istrijebiti i ljude i stoku?\'');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (30, 36, 30, 'Zato ovako govori Jahve protiv Jojakima, kralja judejskoga: \'On neće imati potomka da sjedne na prijestolje Davidovo, a njegovo mrtvo tijelo bit će bačeno na pripeku danju i noćni mraz.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (30, 36, 31, 'Kaznit ću njega, i potomstvo njegovo, i sluge njegove zbog njihova bezakonja, i svalit ću na Jeruzalemce i na Judejce sve zlo kojim sam im prijetio, a nisu me slušali.\"');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (30, 36, 32, 'Tada Jeremija uze drugi svitak, dade ga pisaru Baruhu, sinu Nerijinu, i on po kazivanju Jeremijinu upisa sve riječi knjige koju je Jojakim, kralj judejski, na žeravnici spalio. I k njima je dopisano još mnogo onakvih riječi.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (30, 37, 1, 'Nakon Konije, sina Jojakimova, zakralji se Sidkija, sin Jošijin. Nabukodonozor, kralj babilonski, postavi ga za kralja u zemlji judejskoj.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (30, 37, 2, 'Ali ni on ni sluge njegove ni narod zemlje ne slušahu riječi što ih je Jahve govorio na usta proroka Jeremije.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (30, 37, 3, 'Kralj Sidkija posla Jehukala, sina Šelemjina, i svećenika Sefaniju, sina Maasejina, k proroku Jeremiji s porukom: \"Daj, pomoli se za nas Jahvi, Bogu našemu!\"');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (30, 37, 4, 'Jeremija u ono vrijeme još zalažaše među narod i još ga ne bijahu bacili u tamnicu.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (30, 37, 5, 'A vojska je faraonova nadirala iz Egipta: čuvši to, Kaldejci, koji opsjedahu Jeruzalem, udaljiše se od grada.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (30, 37, 6, 'Tada se javi riječ Jahvina proroku Jeremiji:');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (30, 37, 7, 'Ovako govori Jahve, Bog Izraelov: \"Kralju judejskomu, koji vas posla k meni da me pitate, ovako recite: \'Evo, vojska faraonova, koja vam priteče u pomoć, vratit će se u svoju zemlju Egipat.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (30, 37, 8, 'Kaldejci će opet napasti ovaj grad, osvojiti ga i spaliti.\'');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (30, 37, 9, 'Ovako govori Jahve: \'Ne zanosite se mišlju: \'Kaldejci će otići od nas\', jer oni neće otići!');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (30, 37, 10, 'Pa i da razbijete svu vojsku kaldejsku koja se bori s vama, tako da bi od nje ostali samo ranjenici, oni bi, svaki iz svoga šatora, opet poustajali da požarom unište ovaj grad.\'\"');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (30, 37, 11, 'Kad je vojska kaldejska zbog vojske faraonove morala prekinuti opsadu Jeruzalema,');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (30, 37, 12, 'i Jeremija htjede otići iz Jeruzalema da ode u zemlju Benjaminovu te ondje od rođaka dobije dio.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (30, 37, 13, 'Ali kad stiže do Benjaminovih vrata, ondje bijaše zapovjednik straže Jirijaj, sin Hananijina sina Šelemje. On zaustavi proroka Jeremiju povikavši: \"Ti hoćeš prebjeći Kaldejcima!\" Jeremija odgovori:');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (30, 37, 14, '\"Nije istina, ne želim prebjeći Kaldejcima!\" Ali i ne slušajući Jeremiju, Jirijaj ga uhvati i odvede dostojanstvenicima.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (30, 37, 15, 'Dostojanstvenici se razljutiše na Jeremiju te ga istukoše i zatvoriše u kuću pisara Jonatana, koju bijahu pretvorili u tamnicu.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (30, 37, 16, 'Tako Jeremija dospje u nadsvođen podrum. Ondje Jeremija ostade mnogo vremena.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (30, 37, 17, 'Tada kralj Sidkija posla po njega. I nasamo, u dvoru, kralj ga upita: \"Ima li riječi od Jahve?\" A na to će Jeremija: \"Dakako!\" I dometne: \"Bit ćeš predan u ruke kralja babilonskoga!\"');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (30, 37, 18, 'Onda Jeremija kaza kralju Sidkiji: \"Što skrivih tebi, tvojim slugama i ovom narodu te me baciste u tamnicu?');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (30, 37, 19, 'Gdje su sada vaši proroci koji vam prorekoše: \'Kralj babilonski neće udariti na vas ni na ovu zemlju?\'');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (30, 37, 20, 'A sada, hajde, čuj mene, gospodaru moj i kralju, usliši molbu moju! Nemoj da me opet vrgnu u kuću pisara Jonatana, da ondje ne umrem!\"');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (30, 37, 21, 'Tada kralj Sidkija naredi i Jeremiju odvedoše u tamničko dvorište te mu davahu svaki dan pogaču kruha iz Pekarske ulice, sve dok nije ponestalo kruha u gradu. I tako Jeremija ostade u tamničkom dvorištu.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (30, 38, 1, 'Šefatja, sin Matanov, i Gedalija, sin Pašhurov, i Jukal, sin Šelemjin, i Pašhur, sin Malkijin, čuše tada za riječi što ih Jeremija kaza svemu narodu:');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (30, 38, 2, '\"Ovako govori Jahve: \'Tko ostane u ovome gradu, poginut će od mača, gladi i kuge. A tko izađe pred Kaldejce, spasit će život - život će mu ostati kao plijen, ostat će živ.\'');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (30, 38, 3, 'Jer ovako govori Jahve: \'Ovaj će grad odista pasti u ruke vojsci kralja babilonskoga i ona će ga zauzeti!\'\"');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (30, 38, 4, 'Tada dostojanstvenici rekoše kralju: \"Ovoga čovjeka valja ubiti: on zaista obeshrabruje ratnike koji su još ostali u gradu i sav narod kad takve riječi pred njima govori. Pa taj čovjek ne traži dobrobit ovoga naroda, nego njegovu propast.\"');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (30, 38, 5, 'A kralj Sidkija odgovori: \"Eto, on je u vašim rukama, jer kralj ionako više nema nikakve vlasti nad vama.\"');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (30, 38, 6, 'Tada pograbiše Jeremiju i baciše ga u čatrnju kraljevića Malkije, što je bila u tamničkom dvorištu, i oni ga spustiše na užetima. Ali u čatrnji ne bijaše vode, već samo glib, tako da Jeremija propade u glib.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (30, 38, 7, 'Ali Kušit Ebed-Melek, dvorjanin koji bijaše u kraljevskom dvoru, doču da su Jeremiju bacili u čatrnju dok je kralj upravo sjedio kod Benjaminovih vrata.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (30, 38, 8, 'Tada Ebed-Melek izađe iz kraljevskog dvora te ovako reče kralju:');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (30, 38, 9, '\"Gospodaru, kralju moj, zlo čine ovi ljudi kad tako postupaju s prorokom Jeremijom: bacili su ga u čatrnju, gdje će od gladi umrijeti, jer nema kruha u gradu.\"');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (30, 38, 10, 'Nato kralj zapovjedi Kušitu Ebed-Meleku: \"Povedi trojicu ljudi te izvuci proroka Jeremiju iz čatrnje dok nije umro.\"');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (30, 38, 11, 'I Ebed-Melek povede ljude, uđe u kraljevski dvor, pod riznicu: uze ondje nešto iznošenih i poderanih dronjaka te ih na užetu spusti Jeremiji u čatrnju.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (30, 38, 12, 'Kušit Ebed-Melek reče Jeremiji: \"Podmetni iznošene i poderane dronjke pod pazuha i pod užad.\" Jeremija učini tako.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (30, 38, 13, 'Tada na užetima izvukoše Jeremiju iz čatrnje. Otada Jeremija ostade u tamničkom dvorištu.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (30, 38, 14, 'Kralj Sidkija posla po proroka Jeremiju te ga pozva da dođe k njemu na treći ulaz što vodi u Dom Jahvin. Kralj reče Jeremiji: \"Htio bih te nešto upitati, nemoj mi ni riječi zatajiti!\"');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (30, 38, 15, 'Jeremija odgovori Sidkiji: \"Ako ti kažem, nećeš li me pogubiti? Ako te pak posvjetujem, nećeš me poslušati!\"');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (30, 38, 16, 'Tada se kralj Sidkija u tajnosti zakle Jeremiji ovim riječima: \"Živoga mi Jahve, koji nam daje ovaj život, neću te pogubiti i neću te predati onima što ti rade o glavi.\"');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (30, 38, 17, 'Jeremija, dakle, reče Sidkiji: \"Ovako govori Jahve, Bog nad Vojskama, Bog Izraelov: \'Ako izađeš pred vojskovođe kralja babilonskoga, spasit ćeš glavu i ovaj grad neće biti uništen požarom; živjet ćete ti i tvoj dom.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (30, 38, 18, 'Ako pak ne izađeš pred vojskovođe kralja babilonskoga, ovaj će grad pasti u ruke Kaldejaca i oni će ga spaliti, a ti se nećeš spasiti iz ruku njihovih.\'\"');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (30, 38, 19, 'A kralj Sidkija odgovori Jeremiji: \"Bojim se Judejaca koji su prebjegli Kaldejcima: mogli bi mene predati njima da mi se izruguju.\"');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (30, 38, 20, 'Jeremija odvrati: \"Oni to neće učiniti. Poslušaj glas Jahvin prema kojem sam ti govorio, bit će ti dobro i spasit ćeš život svoj.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (30, 38, 21, 'Ali ako ne htjedneš iz grada, evo riječi koju mi Jahve objavi:');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (30, 38, 22, '\'Gle, sve žene koje su još ostale u dvoru kralja judejskoga bit će odvedene k vojskovođama kralja babilonskoga i govorit će: Zaveli te, svladali te vjerni prijatelji tvoji! Kad ti noge u kal propadaju, oni te napuštaju!\'');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (30, 38, 23, 'Da, sve će žene tvoje i djecu tvoju odvesti Kaldejcima, a ni ti sam nećeš umaći rukama njihovim: dospjet ćeš u ruke kralju babilonskom, a grad će ovaj biti spaljen.\"');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (30, 38, 24, 'Sidkija reče Jeremiji: \"Nitko živ ne smije o tome što saznati, inače ćeš umrijeti.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (30, 38, 25, 'Ako, dakle, dostojanstvenici doznaju da sam s tobom razgovarao te dođu k tebi i kažu: \'TÓa očituj nam što kralj kaza tebi, a ti njemu; ne krij ništa pred nama, inače ćemo te ubiti\',');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (30, 38, 26, 'odgovori im: \'Molio sam kralja da me više ne vrati u kuću Jonatanovu, da ondje ne umrem!\'\"');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (30, 38, 27, 'I doista, dođoše dostojanstvenici k Jeremiji te ga ispitivahu. Ali im on odgovori upravo onako kako mu kralj bijaše naredio. Tada ga se okaniše, jer se ništa nije pročulo o onom razgovoru.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (30, 38, 28, 'Jeremiju, dakle, ostaviše u tamničkom dvorištu sve do dana kad neprijatelj zauze Jeruzalem. Kad Jeruzalem zauzeše, on bijaše ondje.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (30, 39, 1, 'Devete godine kralja Sidkije, kralja judejskoga, desetoga mjeseca, Nabukodonozor, kralj babilonski, krenu sa svom vojskom na Jeruzalem te ga opsjede.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (30, 39, 2, 'Jedanaeste godine kralja Sidkije, četvrtoga mjeseca, dana devetoga u mjesecu, provališe u grad.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (30, 39, 3, 'Uđoše sve vojskovođe kralja babilonskoga te se smjestiše kod Srednjih vrata: Nergal Sar-Eser, knez Sin-Magira, vrhovni zapovjednik, Nebušasban, visoki dostojanstvenik, i sve druge vojskovođe kralja babilonskoga.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (30, 39, 4, 'Kad ih vidješe Sidkija, kralj judejski, i svi ratnici njegovi, dadoše se u bijeg na vrata između dva zida, noću iziđoše iz grada prema Kraljevu vrtu i krenuše k dolini Arabi.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (30, 39, 5, 'Ali ih čete kaldejske gonjahu i sustigoše Sidkiju u Poljanama jerihonskim. Uhvatiše ga, odvedoše u Riblu, u zemlju hamatsku, pred Nabukodonozora, kralja babilonskoga, koji mu izreče sud.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (30, 39, 6, 'I kralj babilonski dade u Ribli pred očima kralja Sidkije zaklati djecu njegovu. A dade kralj babilonski pogubiti i sve odličnike judejske.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (30, 39, 7, 'Sidkiji iskopa oči, stavi ga u okove da ga odvede u Babilon.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (30, 39, 8, 'Kaldejci zapališe kraljev dvor i kuće naroda i porušiše bedeme jeruzalemske.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (30, 39, 9, 'Ostatak pučanstva koje još ostade u gradu, izbjeglice što su mu se predale i sav ostali narod, izagna u Babilon Nebuzaradan, zapovjednik tjelesne straže.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (30, 39, 10, 'A od siromašnoga puka koji nije ništa posjedovao, Nebuzaradan, zapovjednik tjelesne straže, ostavi neke u zemlji judejskoj i porazdijeli im vinograde i polja.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (30, 39, 11, 'O Jeremiji Nabukodonozor, kralj babilonski, zapovjedi Nebuzaradanu, zapovjedniku tjelesne straže:');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (30, 39, 12, '\"Uzmi ga i oko tvoje neka bdi nad njim. Ne čini mu nikakva zla, nego postupaj s njime kako on bude želio.\"');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (30, 39, 13, 'Tada Nebuzaradan, zapovjednik tjelesne straže, Nebušazdan, visoki dostojanstvenik, Nergal Sar-Eser, vrhovni zapovjednik, i sve vojskovođe kralja babilonskoga');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (30, 39, 14, 'poslaše ljude da izvedu Jeremiju iz tamničkoga dvorišta i pustiše ga na slobodu. I tako on osta među narodom.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (30, 39, 15, 'Dok je Jeremija bio zatvoren u tamničkom dvorištu, dođe mu riječ Jahvina:');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (30, 39, 16, '\"Idi i reci Kušitu Ebed-Meleku: Ovako govori Jahve nad Vojskama, Bog Izraelov: \'Evo, učinit ću da se ispune moje riječi protiv ovoga grada, na nesreću, ne na spas njegov. I kad se u onaj dan na tvoje oči obistine,');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (30, 39, 17, 'ja ću te u onaj dan spasiti - riječ je Jahvina - i nećeš biti predan u ruke ljudima pred kojima dršćeš,');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (30, 39, 18, 'jer ja ću te pouzdano spasiti te nećeš od mača poginuti, nego ćeš dobiti život kao plijen, jer si se u me pouzdao\' - riječ je Jahvina.\"');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (30, 40, 1, 'Ovo je riječ koju Jahve uputi Jeremiji pošto ga Nebuzaradan, zapovjednik tjelesne straže, bijaše pustio iz Rame. Odvojio ga je kad je već, u lance okovan, bio među svim jeruzalemskim i judejskim izgnanicima koje vođahu u Babilon.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (30, 40, 2, 'Odvojivši ga, dakle, zapovjednik tjelesne straže reče mu: \"Jahve, Bog tvoj, zaprijetio je nesrećom ovome mjestu.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (30, 40, 3, 'Izvršio je i učinio kako bijaše zaprijetio, jer ste griješili protiv Jahve i niste slušali glasa njegova. Zato vas je i snašlo ovo zlo.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (30, 40, 4, 'Evo, sada driješim okove s ruku tvojih. Ako ti je po volji da ideš sa mnom u Babilon, pođi sa mnom i oko će moje bdjeti nad tobom. Ako ti nije volja ići sa mnom u Babilon, ti ostani. Gle, sva je zemlja pred tobom: možeš ići kamo ti oko želi i gdje će ti biti dobro.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (30, 40, 5, 'Ako, dakle, hoćeš ostati, možeš poći Gedaliji, sinu Šafanova sina Ahikama, koga je kralj babilonski postavio nad gradovima judejskim, i ostati kod njega usred naroda, ili pak možeš ići kamo ti drago.\" Zatim mu zapovjednik tjelesne straže dade hrane i k tomu dar te ga otpusti.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (30, 40, 6, 'Tada se Jeremija otputi u Mispu, Gedaliji, sinu Ahikamovu, te osta kod njega među narodom koji je ostao u zemlji.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (30, 40, 7, 'Svi vojni zapovjednici i njihovi ljudi uokolo saznaše da je kralj babilonski postavio zemlji za namjesnika Ahikamova sina Gedaliju te mu povjerio muževe, žene i djecu i siromahe koji još ne bijahu odvedeni u babilonsko sužanjstvo.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (30, 40, 8, 'I dođoše pred Gedaliju u Mispu: Netanijin sin Jišmael, Kareahov sin Johanan; Tanhumetov sin Seraja, Zatim sinovi Efaja Netofljanina, Makatijev sin Jaazanija - oni i njihovi ljudi.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (30, 40, 9, 'Gedalija, sin Šafanova sina Ahikama, zakle se njima i njihovim ljudima i reče: \"Ne bojte se služiti Kaldejcima, ostanite u zemlji, budite odani babilonskom kralju i bit će vam dobro.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (30, 40, 10, 'A ja ću, evo, ostati u Mispi na službu Kaldejcima koji dolaze k nama. Vi pak potrgajte grožđe, poberite voće i masline, pohranite u sudove i ostanite u gradovima što ih zaposjedoste.\"');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (30, 40, 11, 'I svi Judejci što se zatekoše u Moabu, kod sinova Amonovih, i u Edomu, po svim zemljama, saznadoše da je kralj babilonski ostavio ostatak u Judeji i da je postavio nad njim Gedaliju, sina Šafanova sina Ahikama.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (30, 40, 12, 'I onda se vratiše svi Judejci iz svih mjesta kamo ih bijahu raspršili, vratiše se u zemlju judejsku Gedaliji u Mispu te nabraše veoma mnogo grožđa i drugoga voća.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (30, 40, 13, 'A Johanan, sin Kareahov, i svi vojni zapovjednici pođoše Gedaliji u Mispu');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (30, 40, 14, 'te mu rekoše: \"A znaš li ti da je amonski kralj Baalis poslao Jišmaela, sina Netanijina, da te ubije?\" Ali im Gedalija, sin Ahikamov, ne povjerova.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (30, 40, 15, 'Tada reče Johanan, sin Kareahov, potajno Gedaliji u Mispi: \"Idem da ubijem Jišmaela, sina Netanijina, tako da nitko neće doznati. Zašto da on tebe ubije i da se opet rasprše svi Judejci što se oko tebe skupiše? I zašto da propadne ostatak Judejaca?\"');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (30, 40, 16, 'Ali Gedalija, sin Ahikamov, uzvrati Johananu, sinu Kareahovu: \"Nemoj toga raditi! Jer je laž što govoriš o Jišmaelu.\"');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (30, 41, 1, 'Ali u sedmom mjesecu dođe Jišmael, sin Elišamina sina Netanije, roda kraljevskoga, sa deset ljudi i potraži Gedaliju, sina Ahikamova, u Mispi. I dok su se ondje, u Mispi, zajedno gostili,');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (30, 41, 2, 'diže se Jišmael, sin Netanijin, sa svojom desetoricom i mačem smakoše Gedaliju, sina Ahikamova. I tako ubi čovjeka koga kralj babilonski bijaše postavio nad zemljom.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (30, 41, 3, 'A i sve Judejce koji bijahu s njim u Mispi, i Kaldejce, vojnike što se tu nađoše - Jišmael dade pogubiti.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (30, 41, 4, 'Sutradan, pošto Gedalija bi ubijen, dok još nitko nije znao što se zbilo,');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (30, 41, 5, 'dođoše ljudi iz Šekema, Šila i Samarije, njih osamdeset, obrijane brade, poderanih haljina i s urezima po tijelu, noseći u rukama prinose i tamjan da ih prinesu u Domu Jahvinu.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (30, 41, 6, 'Jišmael, sin Netanijin, iziđe im iz Mispe u susret, dok su oni, plačući, išli svojim putem. Kad ih stiže, reče im: \"Dođite Gedaliji, sinu Ahikamovu!\"');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (30, 41, 7, 'A kad stigoše usred grada, Jišmael, sin Netanijin, i njegovi ljudi poklaše ih i baciše u čatrnju.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (30, 41, 8, 'A među njima bijaše deset ljudi koji rekoše Jišmaelu: \"Nemoj nas ubiti, jer imamo u poljima zakopanih zaliha pšenice, ječma, ulja i meda.\" On tada odusta i ne ubi ih s braćom njihovom.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (30, 41, 9, 'A čatrnja u koju je Jišmael pobacao sva tjelesa pobijenih ljudi, velika čatrnja, bijaše ona ista koju je kralj Asa načinio protiv Baše, kralja izraelskoga. I sad ju je Jišmael, sin Netanijin, napunio pobijenim ljudima.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (30, 41, 10, 'Tada Jišmael odvede ostatak naroda iz Mispe, zajedno s kćerima kraljevim koje je Nebuzaradan, zapovjednik tjelesne straže, povjerio Gedaliji, sinu Ahikamovu: u cik zore krenu Jišmael, sin Netanijin, i zaputi se da prijeđe u zemlju Amonovih sinova.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (30, 41, 11, 'Ali kad Johanan, sin Kareahov, i svi vojni zapovjednici koji bijahu s njim saznadoše za sva zlodjela što ih Jišmael, sin Netanijin, bijaše počinio,');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (30, 41, 12, 'uzeše sve svoje vojnike te krenuše u boj na Jišmaela, sina Netanijina. Nađoše ga uz veliku vodu u Gibeonu.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (30, 41, 13, 'Čim oni ljudi što bijahu kod Jišmaela ugledaše Johanana, sina Kareahova, i sve vojne zapovjednike koji bijahu s njime, obradovaše se,');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (30, 41, 14, 'i sav narod što ga je Jišmael odveo iz Mispe okrenu se i potrča Johananu, sinu Kareahovu.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (30, 41, 15, 'Ali Jišmael, sin Netanijin, sa osam ljudi, pobježe od Johanana i ode k sinovima Amonovim.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (30, 41, 16, 'Tada Johanan, sin Kareahov, i svi vojni zapovjednici koji bijahu s njim uzeše sav preostali narod što ga Jišmael, sin Netanijin, pošto ubi Gedaliju, sina Ahikamova, bijaše doveo iz Mispe: muškarce, žene i djecu i dvorjane koje dovede iz Gibeona.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (30, 41, 17, 'Krenuše, a kod Svratišta Kimhama, koje je kraj Betlehema, oni se odmarahu da bi mogli nastaviti put i stići u Egipat,');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (30, 41, 18, 'što dalje od Kaldejaca, kojih se bojahu: jer je Jišmael, sin Netanijin, ubio Gedaliju, sina Ahikamova, koga kralj babilonski bijaše postavio za namjesnika u zemlji.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (30, 42, 1, 'Nato svi vojni zapovjednici, osobito Johanan, sin Kareahov, i Azarja, sin Hošajin, i sav narod, malo i veliko, pristupiše');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (30, 42, 2, 'i rekoše proroku Jeremiji: \"Pomno počuj molbu našu! Zagovaraj nas pred Jahvom, Bogom svojim, za sav ovaj ostatak, jer nas, kako i sam vidiš, ostade još samo malo od velikoga broja koliko nas je nekoć bilo.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (30, 42, 3, 'Neka nam Jahve, Bog tvoj, objavi kuda da krenemo i što valja da činimo.\"');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (30, 42, 4, 'Prorok im Jeremija odgovori: \"Pristajem. Pomolit ću se, kao što rekoste, Jahvi, Bogu vašemu, i javit ću vam sve što on odgovori, ni riječi vam neću zatajiti.\"');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (30, 42, 5, 'Oni pak rekoše Jeremiji: \"Neka Jahve bude istinit i vjerodostojan svjedok protiv nas ako ne postupimo sasvim po riječima koje će nam Jahve, Bog tvoj, po tebi objaviti.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (30, 42, 6, 'Bio povoljan ili nepovoljan glas Jahve, Boga našega, komu te šaljemo, mi ćemo ga slušati da nam dobro bude što poslušasmo glas Jahve, Boga svojega.\"');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (30, 42, 7, 'Poslije deset dana dođe riječ Jahvina Jeremiji.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (30, 42, 8, 'Tada on pozva Johanana, sina Kareahova, sve vojne zapovjednike koji bijahu s njim i sav narod, malo i veliko,');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (30, 42, 9, 'te im reče: \"Ovako govori Jahve, Bog Izraelov, kojemu ste me poslali da izlijem preda nj molbu vašu:');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (30, 42, 10, '\'Ako budete mirno živjeli u zemlji ovoj, podići ću vas i neću vas više razoriti; posadit ću vas, a ne iskorijeniti. Jer se kajem za zlo koje sam vam nanio.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (30, 42, 11, 'Ne bojte se kralja babilonskoga od koga strahujete. Ne bojte ga se - riječ je Jahvina - jer ja sam s vama da vas spasim i izbavim iz ruku njegovih.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (30, 42, 12, 'I ja ću vam pribaviti milost da vam se smiluje i pusti vas da u zemlji svojoj živite.\'');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (30, 42, 13, 'Ako pak kažete: \'Nećemo ostati u ovoj zemlji\', ne pokoravajući se glasu Jahve, Boga svoga,');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (30, 42, 14, 'ako kažete: \'Ne, u Egipat idemo, rata više da ne vidimo, glasa bojnog roga više da ne čujemo, da ne moramo biti više gladni kruha; da, onamo idemo\',');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (30, 42, 15, 'onda čujte riječ Jahvinu, vi koji ste Ostatak Judeje: Ovako govori Jahve nad Vojskama, Bog Izraelov: \'Ako ste odlučili krenuti u Egipat da ondje živite,');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (30, 42, 16, 'mač kojega se plašite u zemlji će vas egipatskoj dostići; glad od koje strahujete, u Egiptu će vam biti za petama: i ondje ćete umrijeti!');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (30, 42, 17, 'I svi oni koji odluče da odu u Egipat i da se ondje nasele, poginut će od mača, gladi i kuge: nitko živ neće umaći nesreći koju ću na njih svaliti.\'');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (30, 42, 18, 'Jer ovako govori Jahve nad Vojskama, Bog Izraelov: \'Kao što se srdžba moja i bijes moj oboriše na Jeruzalemce, tako će se gnjev moj izliti i na vas ako pođete u Egipat: postat ćete prokletstvo, užas, kletva i poruga, a ovoga mjesta nikad više nećete ugledati.\'');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (30, 42, 19, 'Vama, koji ste Ostatak Judeje, Jahve poručuje da ne idete u Egipat. Dobro znajte da sam danas bio svjedok protiv vas.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (30, 42, 20, 'Jer sami sebe obmanjujete. TÓa vi ste me poslali k Jahvi, Bogu svome rekavši: \'Zagovaraj nas pred Jahvom, Bogom našim, i saopći nam sve što ti on objavi, i mi ćemo to učiniti.\'');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (30, 42, 21, 'A danas sam vam objavio, ali vi ne slušate više glasa Jahve, Boga svojega, koji me k vama posla.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (30, 42, 22, 'Znajte, dakle, dobro: od mača, gladi i kuge poginut ćete na mjestu kamo hoćete da odete da se ondje naselite.\"');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (30, 43, 1, 'Kad je Jeremija svemu narodu kazao sve riječi Jahve, Boga njihova, sve one riječi radi kojih ga je Jahve, Bog njihov, k njima poslao,');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (30, 43, 2, 'Azarja, sin Hošajin, i Johanan, sin Kareahov, i svi oni drski ljudi odgovoriše Jeremiji: \"Laži nam govoriš. Nije te poslao Jahve da nam govoriš: \'Ne idite u Egipat da se ondje nastanite\',');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (30, 43, 3, 'nego Baruh, sin Nerijin, podgovori te da nas predaš u ruke Kaldejcima koji će nas pogubiti ili odvesti u sužanjstvo babilonsko!\"');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (30, 43, 4, 'I Johanan, sin Kareahov, i svi zapovjednici i sav narod ne poslušaše glasa Jahvina da ostanu u zemlji judejskoj.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (30, 43, 5, 'Nego Johanan, sin Kareahov, i vojni zapovjednici povedoše sav ostatak Judin, one što se vratiše iz zemalja kamo bijahu izagnani, da se nastane u zemlji judejskoj:');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (30, 43, 6, 'muževe, žene i djecu i sve kraljevske kćeri i sve ljude koje je Nebuzaradan, zapovjednik tjelesne straže, ostavio kod Gedalije, sina Šafanova sina Ahikama, pa i proroka Jeremiju, i Baruha, sina Nerijina,');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (30, 43, 7, 'te se oni iseliše u Egipat, jer ne slušahu glasa Jahvina. I tako dođoše u Tafnis.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (30, 43, 8, 'U Tafnisu dođe riječ Jahvina Jeremiji:');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (30, 43, 9, '\"Uzmi u ruke velikoga kamenja i ugradi ga, pred svim Judejcima, meljtom u pločnik što je pred ulazom u faraonov dvor.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (30, 43, 10, 'I reci im: Ovako govori Jahve nad Vojskama, kralj Izraelov: \'Evo šaljem po slugu svojega Nabukodonozora, kralja babilonskoga. On će postaviti prijestolje na ovo kamenje što sam ga ugradio i nad njim će razapeti svoju nebnicu.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (30, 43, 11, 'Da, doći će i udarit će na zemlju egipatsku: Tko je za smrt, u smrt! Tko za izgnanstvo, u izgnanstvo! Tko za mač, pod mač!');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (30, 43, 12, 'On će vatrom sažeći hramove bogova egipatskih, spalit će i izagnati bogove, očistit će zemlju egipatsku kao što pastir svoj plašt otrijebi od buha. I onda će, nesmetan, odavde otići.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (30, 43, 13, 'Porazbijat će spomenike hrama Sunca koji je u Heliopolu, a hramove bogova egipatskih ognjem će spaliti.\'\"');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (30, 44, 1, 'Riječ koja se javi Jeremiji za sve Judejce što življahu u zemlji egipatskoj, što življahu u Migdolu, u Tafnisu, u Memfisu i u zemlji Patrosu.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (30, 44, 2, 'Ovako govori Jahve nad Vojskama, Bog Izraelov: \"I sami vidjeste svu nesreću koju sam svalio na Jeruzalem i na sve gradove judejske: evo danas su to gomile ruševina, a u njima nitko više ne živi,');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (30, 44, 3, 'zbog nedjela njihovih što ih učiniše da bi mene vrijeđali, polazeći drugim bogovima kojih nisu poznavali ni oni, ni vi, ni oci vaši, da im kade i da im služe.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (30, 44, 4, 'A ja sam vam jednako slao svoje sluge proroke da vam kažu: \'Ne činite tih gnusoba koje su mi ogavne!\'');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (30, 44, 5, 'Ali me oni nisu slušali, niti su uho svoje priklonili da se okane zloće svoje i prestanu kaditi tuđim bogovima.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (30, 44, 6, 'Zato se izli gnjev moj i srdžba moja i rasplamtje se u gradovima judejskim i po ulicama jeruzalemskim, te se pretvoriše u pustoš i razvaline, kao što su danas.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (30, 44, 7, 'Zašto sami svaljujete na se tako golemu nesreću\" - govori Jahve, Bog nad Vojskama, Bog Izraelov - \"te sami do korijena istrebljujete iz Judeje sve muško i žensko, djecu i dojenčad, te vam ni ostatka ostati neće,');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (30, 44, 8, 'jer me vrijeđate djelima ruku svojih, kadeći tuđim bogovima u zemlji egipatskoj, u koju ste došli prebivati, a bit ćete iskorijenjeni i postat ćete kletva i ruglo među svim narodima na zemlji?');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (30, 44, 9, 'Jeste li zaboravili bezakonja otaca svojih, bezakonja kraljeva judejskih, bezakonja knezova svojih i žena njihovih i bezakonja svoja, bezakonja žena svojih, počinjena u zemlji judejskoj i po ulicama jeruzalemskim?');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (30, 44, 10, 'Do dana današnjega nisu se pokajali, nisu se bojali, nisu živjeli po Zakonu mojemu ni po odredbama mojim, koje dadoh vama i ocima vašim.\"');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (30, 44, 11, 'Zato ovako govori Jahve nad Vojskama, Bog Izraelov: \"Evo, okrećem svoje lice vama, na nesreću vašu, da zatrem svu zemlju judejsku.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (30, 44, 12, 'Odnijet ću ostatak Judeje koji je odlučio da ide u zemlju egipatsku da se ondje stani; svi će izginuti u zemlji egipatskoj, past će od mača, od gladi će pogibati, poginut će svi, malo i veliko, pomrijet će od mača i gladi, i bit će prokletstvo, užas, kletva i poruga.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (30, 44, 13, 'Kaznit ću sve koji budu u zemlji egipatskoj, kao što sam kaznio Jeruzalem: mačem, glađu i kugom.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (30, 44, 14, 'A od ostatka Judeje koji je došao da se stani u Egiptu, nitko neće uteći ni preživjeti da bi se mogao vratiti u zemlju judejsku za kojom im duše čeznu, da se u nju vrate i ondje nastane. Jer se nitko neće vratiti, osim izbjeglica.\"');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (30, 44, 15, 'I tada svi muškarci koji su znali da im žene kade tuđim bogovima, i sve nazočne žene, u velikom mnoštvu, i sav narod što življaše u zemlji egipatskoj i u Patrosu odgovoriše Jeremiji:');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (30, 44, 16, '\"Riječi koje si u ime Jahvino nama objavio mi ne slušamo;');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (30, 44, 17, 'naprotiv, i dalje ćemo se držati zadane riječi: kadit ćemo nebeskoj kraljici i lijevati ljevanice, kao što smo i mi i oci naši, naši kraljevi i knezovi činili u gradovima judejskim i po ulicama jeruzalemskim: tada imadosmo kruha izobila, bijasmo sretni i ne trpjesmo nikakvih nesreća.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (30, 44, 18, 'Ali otkako prestadosmo kaditi nebeskoj kraljici i lijevati joj ljevanice, u svemu smo oskudijevali i od mača i gladi pogibali.\"');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (30, 44, 19, 'A žene rekoše: \"Kad kadimo kraljici nebeskoj i lijevamo joj ljevanice, zar joj bez znanja svojih muževa pečemo kolače u obliku lika njezina i lijevamo ljevanice?\"');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (30, 44, 20, 'Tada Jeremija svemu narodu, muškarcima i ženama, i svim ljudima koji su mu tako govorili reče:');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (30, 44, 21, '\"Nije li se Jahve spomenuo i nije li ga u srce dirnuo tamjan što ste ga palili po ulicama jeruzalemskim, vi i oci vaši, vaši kraljevi, knezovi i puk zemaljski?');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (30, 44, 22, 'Jahve više nije mogao podnositi zlodjela vaših i gnusoba koje počiniste, i zato se zemlja vaša pretvorila u pustoš i ruševine, u prokletstvo, bez stanovnika, kao što je i danas.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (30, 44, 23, 'Zbog toga što ste, prinoseći tamjan, zgriješili Jahvi, što Jahvina glasa ne slušaste i Jahvina se Zakona i njegovih se naredaba i svjedočanstava ne držaste, snađe vas ova nevolja, kakva je danas.\"');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (30, 44, 24, 'Zatim reče Jeremija svemu narodu, osobito ženama: \"Čujte riječ Jahvinu, svi Judejci koji ste u zemlji egipatskoj:');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (30, 44, 25, 'Ovako govori Jahve nad Vojskama, Bog Izraelov: \'Vi žene, ono što vaša usta obećaju, to vaše ruke moraju i izvršiti. Rekoste: \'Mi ćemo se tvrdo držati zavjeta što ih učinismo: kaditi kraljici nebeskoj i lijevati joj ljevanice.\' Držite se samo svojih zavjeta i lijevajte revno ljevanice!');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (30, 44, 26, 'Ali čujte zato riječ Jahvinu, svi vi Judejci nastanjeni u zemlji egipatskoj! Evo, zaklinjem se velikim imenom svojim,\' govori Jahve. \'U svoj zemlji egipatskoj nijedna usta judejska neće više izustiti mojega imena; nitko neće reći: \'Živoga mi Jahve!\'');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (30, 44, 27, 'Evo, bdim nad njima, na nesreću, a ne na dobro njihovo: svi ljudi judejski što su u zemlji egipatskoj poginut će od mača i gladi do potpunog istrebljenja.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (30, 44, 28, 'I bit će malo onih koji će izbjeći maču i vratiti se iz egipatske zemlje u zemlju judejsku. Onda će sav ostatak judejski, svi koji dođoše u zemlju egipatsku da ondje žive, spoznati čija riječ vrijedi, moja ili njihova.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (30, 44, 29, 'A ovo neka vam bude znamenje - riječ je Jahvina - da ću vas kazniti na ovome mjestu, da biste znali da će se vama na nesreću ispuniti prijetnje moje protiv vas.\'');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (30, 44, 30, 'Ovako govori Jahve: \'Gle, predat ću faraona Hofru, kralja egipatskoga, u ruke njegovim neprijateljima i u ruke onih koji mu rade o glavi, baš kao što sam Sidkiju, kralja Judejskoga, predao u ruke Nabukodonozora, kralja babilonskoga, neprijatelja njegova, koji mu je radio o glavi.\'\"');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (30, 45, 1, 'Riječ koju uputi Jeremija proroku Baruhu, sinu Nerijinu, dok je on te riječi iz usta Jeremijinih pisao u knjigu, četvrte godine Jojakima, sina Jošijina, kralja judejskoga:');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (30, 45, 2, 'Ovako govori Jahve, Bog Izraelov, za tebe, Baruše:');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (30, 45, 3, '\"Jer si rekao: \'Jao meni jer mi Jahve dodaje nevolju na nevolju. Sustadoh uzdišući i ne mogu naći mira!\'');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (30, 45, 4, 'Ovako govori Jahve: \'Evo, što sam sagradio, porušit ću, što sam zasadio, iščupat ću - po svoj zemlji!');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (30, 45, 5, 'A ti tražiš za se čudesa! Ne traži toga! Jer, gle, svalit ću zlo na sve živo - riječ je Jahvina. A tebi ću kao plijen pokloniti život tvoj na svim mjestima kamo dođeš.\'\"');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (30, 46, 1, 'Riječ koju Jahve uputi proroku Jeremiji protiv naroda.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (30, 46, 2, 'Još o Egiptu. Protiv vojske faraona Neka, kralja egipatskoga, što bijaše kod rijeke Eufrata, u Karkemišu, i kralj Nabukodonozor ga potuče, četvrte godine Jojakima, sina Jošijina, kralja judejskoga.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (30, 46, 3, 'Pripremite štitove i oklope! Naprijed, u boj!');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (30, 46, 4, 'Upregnite konje! Na kola, vozači! Postavite se pod kacigama! Naperite koplja! Navucite oklope!');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (30, 46, 5, 'Što vidim? Zaprepašteni, uzmiču? Junaci njihovi, poraženi, u bijeg udariše glavom bez obzira! Užas odasvud - riječ je Jahvina.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (30, 46, 6, 'Ni najbrži ne umače, ni najhrabriji ne uteče! Na sjeveru, na obali Eufrata, posrću i padaju.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (30, 46, 7, 'Tko se to diže poput Nila, čije vode šume, k\'o brzaci nabujaše?');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (30, 46, 8, 'To Egipat se diže poput Nila, k\'o brzaci vode mu nabujaše. I govori: dići ću se, poplaviti zemlju, opustošiti gradove i pučanstvo!');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (30, 46, 9, 'Konji, naprijed! Poletite, kola bojna! Navalite, ratnici! Kušiti, Putijci, štitom zaštićeni, i Ludijci, što lukom strijeljate!');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (30, 46, 10, 'Ovo je dan Jahve nad Vojskama - dan osvete da se dušmanima svojim osveti: mač će se nažderati, nasititi, glad utoliti krvlju njihovom! Jer Gospod, Jahve nad Vojskama, ima žrtveno klanje u sjevernoj zemlji uz obalu Eufrata.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (30, 46, 11, 'Popni se na Gilead, balzama potraži, djevice, kćeri egipatska! Uzalud lijekovi mnogi: nema tebi ozdravljenja!');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (30, 46, 12, 'Narodi čuše za tvoju sramotu, vapaji tvoji napuniše zemlju. Jer se junak o junaka spotiče i obojica padaju.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (30, 46, 13, 'Riječ koju Jahve uputi proroku Jeremiji kad Nabukodonozor, kralj babilonski, dođe da udari na zemlju egipatsku.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (30, 46, 14, 'Navijestite Egiptu, objavite u Migdolu, obznanite u Memfisu: \"Svrstaj se! Spremi se! Jer mač već ždere sve oko tebe!');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (30, 46, 15, 'Što? Zar Apis pobježe? Tvoj se Bik ne odrva?\" Da, Jahve ga obori!');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (30, 46, 16, 'On učini te mnogi posrnuše, popadaše jedan na drugoga. I gle, govore: \"Na noge! Vratimo se svom narodu, rodnoj grudi svojoj, pred mačem koljačkim!\"');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (30, 46, 17, 'Faraonu, kralju egipatskom, ime nadjenite: \"Graja što pravi čas promaši.\"');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (30, 46, 18, '\"Tako, života mi moga\" - govori Kralj, komu je ime Jahve nad Vojskama - \"ono će doći kao Tabor posred gora, kao Karmel iznad mora.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (30, 46, 19, 'Spremi izgnanički zavežljaj, udomljena kćeri egipatska, jer Memfis će biti u pustoš pretvoren, poharan i nenastanjen.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (30, 46, 20, 'Egipat bijaše lijepa junica, ali ide, ide na nju obad sa Sjevera.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (30, 46, 21, 'A i plaćenici egipatski što k\'o gojna telad usred nje življahu, i oni se okrenuše, u bijeg udariše, ne mogu se odhrvati jer ih stiže Dan propasti, dođe vrijeme da se kazne.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (30, 46, 22, 'Slušaj! K\'o da zmija sikće, sa svom silom dolaze, sjekirama na nju navaljuju, baš k\'o drvosječe.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (30, 46, 23, 'Posjeći će šumu - riječ je Jahvina - iako je neprohodna. Više ih je nego skakavaca, broja njima nema.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (30, 46, 24, 'Osramoćena je zemlja egipatska, predana je narodu Sjevera.\"');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (30, 46, 25, 'Govori Jahve nad Vojskama, kralj Izraelov: \"Evo, kaznit ću Amona Tebskoga, faraona i Egipat, i sve njegove bogove, kraljeve, faraona i sve koji se u nj uzdaju.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (30, 46, 26, 'Predat ću ih u ruke onima što im rade o glavi, u ruke Nabukodonozora, kralja babilonskoga, i u ruke slugu njegovih. A poslije će Egipat biti opet naseljen, kao u stara vremena\" - riječ je Jahvina.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (30, 46, 27, '\"Ne boj se, Jakove, slugo moja, ne plaši se, Izraele! Jer, evo, spasit ću te izdaleka i potomstvo tvoje iz zemlje izgnanstva. Jakov će se opet smiriti, spokojno će živjet\' i nitko ga neće plašiti.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (30, 46, 28, 'Ne boj se, Jakove, slugo moja - riječ je Jahvina - jer ja sam s tobom. Zatrt ću narode među koje te prognah, a tebe neću sasvim uništiti: ali ću te kaznit\' po pravici, ne smijem te pustit\' nekažnjena.\"');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (30, 47, 1, 'Riječ koju Jahve uputi proroku Jeremiji o Filistejcima prije nego što faraon osvoji Gazu.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (30, 47, 2, 'Ovako reče Jahve: \"Evo, vode se dižu sa Sjevera i kao nabujali brzaci poplavljuju zemlju i sve što je na njoj, gradove i sve njihovo pučanstvo. I ljudi vapiju, i kukaju svi žitelji zemlje,');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (30, 47, 3, 'uz tutanj kopita njegove ždrebadi, uza štropot kola i tresku točkova. Oci više ne mare za djecu svoju jer su im ruke klonule');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (30, 47, 4, 'zbog dana što osvanu da Filistejce istrijebi, da zatre Tiru i Sidonu sve do posljednjeg pomagača. Jer Jahve istrebljuje Filistejce, i sav ostatak otočja kaftorskog.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (30, 47, 5, 'Gazi će biti obrijana glava, razoren Aškelon. A ti, Ašdode, ostače Anakovaca, dokle će te tuga razdirati?');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (30, 47, 6, 'Jao, maču Jahvin, kad li ćeš se smiriti? Vrati se u korice, stani i počini!\"');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (30, 47, 7, 'Ali kako da se smiri, kad Jahvina ruka njime zapovijeda: na Aškelon i na morski žal on ga isuka.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (30, 48, 1, 'O Moabu. Ovako govori Jahve nad Vojskama, Bog Izraelov: \"Jao brdu Nebu jer je opustošeno, postiđen je Kirjatajim i osvojen, tvrđa posramljena, razorena,');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (30, 48, 2, 'nema više dike moapske. U Hešbonu mu propast skovaše: \'Hajde da ga istrijebimo iz naroda!\' A ti, Madmene, bit ćeš razoren, mač već ide za tobom!');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (30, 48, 3, 'Slušaj! Jauci se čuju iz Horonajima: \'Pohara, propast strašna!\'');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (30, 48, 4, '\'Moab je smlavljen!\' čuje se vrištanje mališa njegovih.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (30, 48, 5, 'Da, uz brdo Luhit uspinju se plačući. Da, niz obronke Horonajima razliježe se jauk nad propašću.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (30, 48, 6, '\'Bježite, spasavajte život, ugledajte se u pustinjsku magarad!\'');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (30, 48, 7, 'Jer si se pouzdao u svoje utvrde, bit ćeš i ti osvojen. Kemoš odlazi u izgnanstvo sa svećenicima i knezovima svojim.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (30, 48, 8, 'Pustošnik će doći u svaki grad, nijedan mu neće izmaći: Dolina će biti poharana, Visoravan opustošena,\" govori Jahve!');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (30, 48, 9, 'Stavite Moabu nadgrobni kamen, jer je do temelja srušen; njegovi su gradovi pustare, u njima nitko ne obitava.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (30, 48, 10, 'Proklet bio tko nemarno obavlja poslove Jahvine! Proklet bio tko krvlju mač svoj ne omasti!');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (30, 48, 11, 'Od mladosti svoje mir uživaše Moab, ležaše na droždini svojoj, nikad ga nisu pretakali iz bačve u bačvu, nikad u izgnanstvo išao nije: zato mu okus ostade svjež, miris nepromijenjen.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (30, 48, 12, '\"Ali, evo, dolaze dani\" - govori Jahve - \"i ja ću mu poslati tlačitelje koji će ga pretakati, isprazniti njegove bačve i sudove njegove porazbijati.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (30, 48, 13, 'I tada će se Moab postidjeti zbog Kemoša, kao što se dom Izraelov postidio zbog Betela u koji se uzdao.\"');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (30, 48, 14, 'Kako možete reći: \"Mi smo junaci, hrabri ratnici.\"');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (30, 48, 15, 'Pustošnik Moabov navaljuje na nj; cvijet mladosti njegove u klanice silazi, riječ je Kraljeva, Jahve nad Vojskama njemu je ime.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (30, 48, 16, 'Bliži se propast Moabova, nesreća njegova hiti.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (30, 48, 17, 'Žalite ga, svi susjedi njegovi, i svi koji znate ime njegovo. Recite: \"Kako li se slomi čvrsta palica, žezlo veličanstveno!\"');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (30, 48, 18, 'Siđi sa slave svoje, sjedni u blato, žitelju, kćeri dibonska! Jer pustošnik Moaba navali na te, poruši sve utvrde tvoje.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (30, 48, 19, 'Stani na cestu i promatraj, o žitelju Aroera! Pitaj bjegunce i preživjele, pitaj ih: \"Što se to dogodi?\"');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (30, 48, 20, '\"Moab se stidi jer je slomljen. Plačite, jecajte! Objavite na Arnonu da je Moab poharan.\"');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (30, 48, 21, 'Sud stiže nad Visoravan i nad Holon, Jahsu i Mefaot,');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (30, 48, 22, 'nad Dibon, Nebo, Bet Diblatajim,');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (30, 48, 23, 'Kirjatajim, Bet Gamul, Bet Meon,');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (30, 48, 24, 'Kerijot, Bosru i nad sve gradove zemlje moapske, daleke i blize.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (30, 48, 25, '\"Moabu je rog odbijen, ruka mu je slomljena.\"');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (30, 48, 26, '\"Opijte ga jer se htjede uzvisiti nad Jahvu: neka se Moab sada valja u bljuvotini svojoj te i on neka bude na podsmijeh.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (30, 48, 27, 'Nije li tebi bio Izrael na podsmijeh? Jesu li ga možda zatekli u krađi te mašeš glavom kad god o njemu govoriš?\"');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (30, 48, 28, '\"Ostavite gradove, živite u pećinama, stanovnici Moaba! Budite kao golubovi što se gnijezde na litici onkraj razjapljena bezdana!\"');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (30, 48, 29, 'Čuli smo za nadutost Moaba, nadutost preveliku, ponos njegov, hvastanje, uznositost, za oholost srca njegova!');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (30, 48, 30, '\"Poznajem ja obijest njegovu - riječ je Jahvina - laž njegovih riječi, laž djela njegovih!');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (30, 48, 31, 'Zato moram jaukati nad Moabom, plakati nad svim Moapcima, jecati zbog ljudi Kir Heresa.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (30, 48, 32, 'Više nego nad Jazerom, plakat ću nad tobom, o lozje sibmansko, kojem se mladice pružahu preko mora, sezahu sve do Jazera. Na tvoje berbe i žetve pade sada pustošnik.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (30, 48, 33, 'Iščeznu radost i veselje iz voćnjaka i zemlje moapske. Nesta vina u kacama, mastioci više grožđa ne maste, veseli zvuci više nisu veseli.\"');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (30, 48, 34, 'Urlanje Hešbona i Elalea čuje se sve do Jahasa. Viču od Soara do Horonajima i Eglat Šelišije, jer se i vode nimrimske pretvoriše u pustaru.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (30, 48, 35, '\"U Moabu ću učiniti - riječ je Jahvina - da se ne uzlazi na uzvišice i kadi bogovima njegovim.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (30, 48, 36, 'Stoga mi srce poput frule dršće za Moabom, srce moje poput frule dršće za ljudima Kir Heresa: jer propade stečevina koju stekoše!');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (30, 48, 37, 'Sve su glave obrijane i brade podrezane; po svim rukama urezi, oko bokova kostrijet.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (30, 48, 38, 'Na svim krovovima Moaba i na njegovim trgovima samo zapomaganje, jer smrskah Moab kao krčag koji se nikomu ne mili\" - riječ je Jahvina.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (30, 48, 39, 'Kako li je smrskan! Kako li sramotno Moab udari u bijeg! Moab postade ruglo i strašilo svim susjedima.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (30, 48, 40, 'Jer ovako govori Jahve: \"Gle, poput orla lebdi, nad Moabom širi krila.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (30, 48, 41, 'Gradovi su zauzeti, osvojene tvrđave. Srce moapskih junaka bit će toga dana kao srce žene u trudovima.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (30, 48, 42, 'Izbrisan je Moab iz naroda jer se uzvisi nad Jahvu.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (30, 48, 43, 'Strava, jama i zamka tebi, žitelju Moaba! - riječ je Jahvina.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (30, 48, 44, 'Tko stravi umakne, u jamu će pasti; tko se iz jame izvuče, u zemlju će pasti. Da, to ću svaliti na Moab u danima kazne njegove\" - riječ je Jahvina.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (30, 48, 45, '\"U sjeni se hešbonskoj ustavljaju iscrpljeni bjegunci. Al\' vatra izlazi iz Hešbona, plamen liže iz dvora sihonskog i proždire sljepoočnice Moabu i tjeme sinova nemirničkih.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (30, 48, 46, 'Jao tebi, Moabe! Umišljen si, narode Kemošev! Jer sinove tvoje u izgnanstvo odvedoše, kćeri tvoje u progonstvo.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (30, 48, 47, 'Ali ću promijeniti udes Moabov u budućnosti\" - riječ je Jahvina. Dovde suđenje Moabu.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (30, 49, 1, 'O sinovima Amonovim. Ovako govori Jahve: \"Izrael nema sinova, nema nasljednika? Zašto je Milkom baštinio Gad i narod se njegov nastanio u njegovim gradovima?');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (30, 49, 2, 'Zato, evo, dolaze dani - riječ je Jahvina - i učinit ću da se zaore ratni krikovi u Rabi sinova Amonovih, i ona će biti humak poharani, i naseobine njene ognjem popaljene. Tada će Izrael opljačkati svoje pljačkaše\" - govori Jahve.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (30, 49, 3, '\"Plači, Hešbone, jer Ar je opustošen, zapomažite kćeri rapske. Opašite kostrijet, tužbalice povedite, obilazite s urezima. Jer Milkom mora u izgnanstvo sa svećenicima i knezovima.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (30, 49, 4, 'Što se dičiš dolinom svojom, kćeri odmetnice, koja se uzdaš u bogatstvo svoje i govoriš: \'Tko se usuđuje ustati protiv mene?\'');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (30, 49, 5, 'Evo, svaljujem na te stravu odasvud uokolo: bit ćete raspršeni, svak\' na svoju stranu, i nitko bjegunce neće skupiti.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (30, 49, 6, 'Ali uto ću opet promijeniti udes sinova Amonovih\" - riječ je Jahvina.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (30, 49, 7, 'O Edomu. Ovako govori Jahve nad Vojskama: \"Zar nema više mudrosti u Temanu, zar u razumnih nesta svj§eta, zar se izvjetrila mudrost njihova?');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (30, 49, 8, 'Bježite, gubite se i duboko se sakrijte, stanovnici Dedana, jer Ezavu propast nosim, vrijeme kazne njegove.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (30, 49, 9, 'Dođu li trgači k tebi, ni pabirka neće ostaviti; dođu li kradljivci noćni, opljačkat će sve što žele.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (30, 49, 10, 'Jer ja sam onaj što će Ezava pretražiti i skrovišta mu otkriti da se ne mogne sakriti. Pleme je njegovo opustošeno: nema ga više! Nitko ne kaže:');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (30, 49, 11, '\'Ostavi siročad svoju, ja ću je prehraniti i neka se udovice tvoje u me pouzdaju!\'\"');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (30, 49, 12, 'Jer ovako govori Jahve: \"Gle, oni koji odista ne bi morali piti čašu moraju je iskapiti, i zar upravo ti da ostaneš nekažnjen? Ne, ti nećeš ostati nekažnjen, morat ćeš čašu ispiti!');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (30, 49, 13, 'Jer samim se sobom zakleh - riječ je Jahvina: Bosra će postati ruglo i sramota, pustinja i prokletstvo; a svi njezini gradovi bit će vječne razvaline.\"');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (30, 49, 14, 'Jahve mi vijest uputi, glasnik bi poslan k narodima: \"Skupite se! Krenite na nj, krenite! Ustajte! U boj!');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (30, 49, 15, 'Jer, gle, učinit ću te malim među narodima, prezrenim među ljudima.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (30, 49, 16, 'Strah te tvoj zaveo, uznositost srca tvoga, ti koji živiš u pećinama kamenim i držiš se visova planinskih te viješ gnijezdo na timoru, k\'o orlovi, odande ću te strovaliti\" - riječ je Jahvina.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (30, 49, 17, '\"Edom će postati pustoš; tko god njime prođe, zaprepastit će se i zviždati zbog svih rana njegovih.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (30, 49, 18, 'Razorit će ga kao Sodomu i Gomoru i susjede njihove\" - govori Jahve. Čovjek ondje neće stanovati, sin čovječji neće u njem boraviti.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (30, 49, 19, '\"Gle, kao lav on izlazi iz guštare jordanske na pašnjake vječno zelene. Ali ću ga učas otjerati i smjestiti ondje svog izabranika. Jer tko je meni ravan? I tko će mene na račun pozvati? I koji će mi pastir odoljeti?\"');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (30, 49, 20, 'Zato čujte što je Jahve naumio učiniti Edomu, čujte što je nakanio protiv stanovnika Temana: i najsitniju jagnjad on će odvući, i sam njihov pašnjak zgrozit će se nad njima.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (30, 49, 21, 'Od lomljave pada njina zemlja će se potresti, razlijegat će se vapaj do Crvenog mora!');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (30, 49, 22, 'Gle, poput orla on se diže i lebdi, nad Bosrom širi krila. U dan onaj srce će junaka edomskih biti kao srce žene u trudovima.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (30, 49, 23, 'O Damasku. Smeteni su Hamat i Arpad jer zlu vijest čuše. Srce im se steže od užasa i smirit se ne može.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (30, 49, 24, 'Obeshrabren je Damask, u bijeg udario, strah ga spopao, tjeskoba i bolovi obuzeli ga kao porodilju.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (30, 49, 25, 'Kako? Napušten je slavni grad, grad radosti moje!');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (30, 49, 26, 'Zato će mladići njegovi popadati po trgovima, svi će ratnici poginuti u onaj dan - riječ je Jahve nad Vojskama.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (30, 49, 27, '\"Potpalit ću vatrom zidine Damaska: plamen će proždrijeti dvor Ben-Hadadov.\"');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (30, 49, 28, 'O Kedaru i kraljevstvima hasorskim koje je potukao Nabukodonozor, kralj babilonski. Ovako govori Jahve: \"Ustajte, na Kedar navalite, uništite sinove Istoka!');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (30, 49, 29, 'Nek\' im se oduzmu šatori i stada, šatorska krila i sva im oprema! Neka im se deve odvedu, i nek\' viču na njih: \'Strava odasvud!\'');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (30, 49, 30, 'Bježite glavom bez obzira, duboko se skrijte, žitelji Hasora - riječ je Jahvina. Jer Nabukodonozor, kralj babilonski, snuje naum protiv vas, navalu smišlja:');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (30, 49, 31, '\'Ustajte, udarite na mirni narod što živi bez straha - riječ je Jahvina - što nema vrata ni zasuna, što u osami prebiva!');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (30, 49, 32, 'Deve njihove bit će plijen, mnoštvo ovaca otimačina!\' I raspršit ću ih na sve strane, one ljude obrijanih zalizaka, i dovest ću odasvud na njih nesreću - riječ je Jahvina.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (30, 49, 33, 'Hasor će postati brlog čagaljski i pustinja vječna. Čovjek ondje neće prebivati, neće se ondje nastaniti sin čovječji.\"');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (30, 49, 34, 'Riječ koju Jahve uputi proroku Jeremiji o Elamu, u početku kraljevanja Sidkije, kralja judejskoga.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (30, 49, 35, 'Ovako govori Jahve nad Vojskama: \"Lomim, evo, luk Elamov, srž snage njegove.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (30, 49, 36, 'Četiri ću vjetra dognati na Elam sa četiri kraja neba i raspršit Elamce u sva četiri vjetra, i neće biti naroda kamo neće stići bjegunci elamski.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (30, 49, 37, 'Utjerat ću Elamcima strah u kosti pred njihovim dušmanima. Pustit ću na njih nesreću, oganj gnjeva svojega. Poslat ću mač za njima dok ne budu sasvim uništeni.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (30, 49, 38, 'I postavit ću u Elamu prijesto svoj i zatrt ću ondje kralja i sve knezove\" - riječ je Jahvina.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (30, 49, 39, 'Ali ću okrenut\' udes Elama\" - riječ je Jahvina.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (30, 50, 1, 'Riječ koju Jahve reče protiv Babilona, protiv zemlje kaldejske:');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (30, 50, 2, '\"Objavite narodima! Razglasite, ne tajite, recite: Zauzet je Babilon! Bel je postiđen: Marduk razbijen! Posramljeni su kipovi njegovi, razmrskani njegovi likovi.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (30, 50, 3, 'Jer sa sjevera na nj se diže narod koji će mu zemlju prometnuti u pustinju; nitko više neće u njoj živjeti, i ljudi i stoka pobjeći će i otići.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (30, 50, 4, 'U one dane i u vrijeme ono - riječ je Jahvina - vratit će se sinovi Izraelovi, ići će plačuć\' i tražeći Jahvu, Boga svojega.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (30, 50, 5, 'Pitat će za put na Sion, onamo će pogled upravljati: \'Hodite, prionimo uz Jahvu Savezom vječnim, nezaboravnim!\'');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (30, 50, 6, 'K\'o izgubljene ovce bijaše narod moj, pastiri ih zavedoše te zalutaše po brdima: moradoše s brda na brežuljke, zaboraviše gdje su im torovi.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (30, 50, 7, 'Tko ih nađe, proždire ih, neprijatelji njini zborahu: \'Nismo mi krivi, jer zgriješiše Jahvi, pašnjaku pravde, Jahvi, nadi otaca svojih!\'');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (30, 50, 8, 'Bježite iz Babilona! Izađite iz zemlje kaldejske! Budite poput ovnova pred stadom.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (30, 50, 9, 'Jer evo ću dići i dovesti na Babilon mnoštvo velikih naroda; u zemlji sjevernoj svrstat će se protiv njega - odanle će biti osvojen. Strijele su im k\'o u sretna junaka, prazne se ne vraćaju.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (30, 50, 10, 'Kaldeja će biti oplijenjena, do mile volje nju će pljačkati\" - riječ je Jahvina.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (30, 50, 11, '\"Da! Radujte se samo i klikujte, vi pljačkaši moje baštine! Poskakujte k\'o june na paši! Ržite kao ždrebad!');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (30, 50, 12, 'Mati vaša teško se osramoti, postidi se roditeljka vaša. Evo, posljednja je među narodima: pustinja, zemlja prljuša.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (30, 50, 13, 'Zbog gnjeva Jahvina bit će bez življa, sva će opustjeti. Tko god prođe mimo Babilon, zgrozit će se i zviždat će nad njegovim ranama.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (30, 50, 14, 'Svrstajte se protiv Babilona, opkolite ga. Strijelci, strijeljajte na nj, ne žalite strelica - Jahvi je zgriješio.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (30, 50, 15, 'Sa svih strana nek\' zaore poklici bojni. On se predaje! Stupovi mu padaju, bedemi se ruše: to Jahvina je osveta! Osvetite se Babilonu, vratite mu milo za drago!');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (30, 50, 16, 'Istrijebite Babilonu i sijača i žeteoca što srpom zamahuje u dane žetvene! Pred mačem silničkim nek\' svak\' se vrati svome narodu, neka bježi zemlji svojoj.\"');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (30, 50, 17, 'Izrael bijaše stado razagnano, lavovi ga raspršiše. Prvi ga kralj asirski proždrije, a onda mu Nabukodonozor, kralj babilonski, kosti polomi.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (30, 50, 18, 'Zato ovako govori Jahve nad Vojskama, Bog Izraelov: \"Evo, kaznit ću kralja babilonskoga i zemlju njegovu, kao što kaznih kralja asirskoga.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (30, 50, 19, 'I vratit ću Izraela pašnjaku njegovu da pase po Karmelu, Bašanu, brdima efrajimskim i u Gileadu, da se sit najede.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (30, 50, 20, 'U one dane, u vrijeme ono - riječ je Jahvina - tražit će grijeh Izraelov, ali ga više neće biti; tražit će opačine judejske, ali ih neće naći. Jer oprostih svima koje sačuvah.\"');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (30, 50, 21, '\"Na zemlju meratajimsku! Kreni na nju i na stanovnike Pekoda, zatri ih do temelja, uništi iza njih sve - riječ je Jahvina - izvrši sve kako ti zapovjedih!\"');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (30, 50, 22, 'Ratna se vika čuje u zemlji, poraz strašan.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (30, 50, 23, 'O, kako li je skršen, razbijen malj cijele zemlje! Kako li Babilon posta strašilo narodima!');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (30, 50, 24, 'Zamku ti metnuh, Babilone, ti se uhvati i ne vidje. Zatečen si i uhvaćen, jer se s Jahvom zarati!');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (30, 50, 25, 'Jahve otvori svoju oružnicu, izvuče oružje gnjeva svojega, jer ima posla za Jahvu nad Vojskama u zemlji kaldejskoj.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (30, 50, 26, 'Udarite na nju sa svih strana, otvorite žitnice njene, slažite je kao snoplje, zatrite Babilon kletim uništenjem, da od njega ne ostane ništa.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (30, 50, 27, 'Pokoljite svu junad njegovu, u klaonicu neka siđu! Jao njima, došao je njihov dan, vrijeme kazne njihove!');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (30, 50, 28, 'Čujder glasa onih što pobjegoše, što utekoše iz zemlje babilonske da jave na Sionu osvetu Jahve, Boga našega, osvetu Hrama njegova!');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (30, 50, 29, 'Sazovite na Babilon strijelce, sve što zapinju lukove, opkolite ga sa svih strana: nitko da ne uteče! Platite mu po zasluzi, vratite mu milo za drago, jer bi se oholio na Jahvu, Sveca Izraelova.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (30, 50, 30, 'Zato će mu svi mladići popadati po trgovima i svi će mu ratnici u onaj dan izginuti - riječ je Jahvina.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (30, 50, 31, '\"Evo me na te, Oholice!\" - riječ je Gospoda Jahve nad Vojskama - \"došao je dan tvoj, vrijeme pohoda na te.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (30, 50, 32, 'Oholica će posrnuti, pasti, i nitko ga neće podići. Oganj ću podmetnuti gradovima njegovim i proždrijet će sve uokolo.\"');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (30, 50, 33, 'Ovako govori Jahve nad Vojskama: \"Potlačeni su sinovi Izraelovi, zajedno sa sinovima Judinim. Oni što ih zarobiše, drže ih čvrsto i neće da ih puste.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (30, 50, 34, 'Ali, moćan je njihov Otkupitelj, ime mu Jahve nad Vojskama. On će obraniti parnicu njihovu - zemlji mir donijeti i smesti pučanstvo Babilona.\"');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (30, 50, 35, 'Mač na Kaldejce - riječ je Jahvina - na pučanstvo Babilona, na knezove i mudrace njegove!');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (30, 50, 36, 'Mač na brbljavce njegove, neka polude! Mač na njegove ratnike, neka se prestrave!');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (30, 50, 37, 'Mač na njegove konje i bojna kola i na svu gomilu posred njega: nek postanu kao žene! Mač na njihove riznice; nek ih opljačkaju!');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (30, 50, 38, 'Mač na vode njihove, neka presahnu! Jer to je zemlja idola, zaludiše ih kipovi, strašila njihova.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (30, 50, 39, 'Zato će se ondje nastaniti risovi s čagljima, i nojevi će ondje obitavat. Dovijeka će ostat\' mjesto bez življa, nitko ondje neće živjeti od koljena do koljena.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (30, 50, 40, 'Razorit će ga kao što Bog razori Sodomu i Gomoru i susjede njihove - riječ je Jahvina. Čovjek ondje neće stanovati, sin čovječji neće u njem\' boraviti.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (30, 50, 41, 'Evo dolazi narod sa Sjevera, puk velik i mnogi kraljevi, i dižu se s krajeva zemlje.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (30, 50, 42, 'U ruci im luk i koplje, okrutni su, nemilosrdni. Graja im buči poput mora, jašu na konjima, kao jedan za boj spremni protiv tebe, kćeri babilonska.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (30, 50, 43, 'Kralj babilonski ču vijest o njima: i ruke mu klonuše, muka ga spopade, bolovi ga obuzeše kao porodilju.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (30, 50, 44, '\"Gle, kao lav on izlazi iz guštare jordanske na pašnjake vječno zelene. Al\' ja ću ga učas otjerati i smjestiti ondje svog izabranika. Jer, tko je meni ravan? I tko će mene na račun pozvati? I koji će mi pastir odoljeti?\"');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (30, 50, 45, 'Zato, čujte što je Jahve naumio da učini Babilonu, čujte što je nakanio protiv zemlje kaldejske: i najsitniju jagnjad on će odvući; i sam njihov pašnjak zgrozit će se nad njima.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (30, 50, 46, 'Na glas da je pao Babilon zemlja će se potresti: razlijegat će se vapaj među narodima.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (30, 51, 1, 'Ovako govori Jahve: \"Gle, ja podižem protiv Babilona i protiv pučanstva kaldejskog vjetar zatornički.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (30, 51, 2, 'Poslat ću na Babilon vijače da ga viju i prorešetaju zemlju njegovu. Kad ga sa svih strana opkole u kobni dan,');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (30, 51, 3, 'nek\' strijelac luka ne odlaže, nek\' ne skida oklopa! Ne štedite mladića njihovih, svu mu vojsku kleto uništite!');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (30, 51, 4, 'Pobijeni će padati po zemlji kaldejskoj, probodeni po ulicama njegovim.\"');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (30, 51, 5, 'Ne, Izrael - Judeja - nije udovica Boga svojega, Jahve nad Vojskama, iako je zemlja njihova puna krivice protiv Sveca Izraelova.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (30, 51, 6, 'Bježite iz Babilona, nek\' svak\' spasi život svoj, da ne izginete s njegova bezakonja, jer ovo je vrijeme Jahvine odmazde, svakom plaća po zasluzi!');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (30, 51, 7, 'Babilon bijaše pehar zlatni u ruci Jahvinoj, pehar koji opi svijet cijeli. Vinom tim se puci opiše, i zato se puci obezumiše.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (30, 51, 8, 'Iznenada pade Babilon, razmrskan: zakukajte nad njim! Potražite balzama rani njegovoj: možda će ozdravit\'!');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (30, 51, 9, 'Liječili smo Babilon, al\' se ne izliječi. Pustimo ga, vratimo se svaki u svoj kraj! Jer do neba dopire njegova osuda i diže se pod oblake.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (30, 51, 10, 'Jahve je iznio pravdu našu! Hajde da Sionu objavimo djelo Jahve, Boga našega.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (30, 51, 11, 'Naoštrite strelice, napunite tobolce! Jahve potače duh kraljeva medijskih jer naumi zatrti Babilon, Jahvina je to osveta, osveta za Hram njegov.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (30, 51, 12, 'Razvijte stijeg, zidine babilonske! Pojačajte straže! Postavite stražare! Razmjestite zasjede! Jer Jahve što naumi to sad izvodi, kako je rekao protiv Babilona.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (30, 51, 13, 'O, ti što prebivaš na velikim vodama i bogat blagom svakojakim! Sad ti svršetak dođe, kraj tvojoj lakomosti.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (30, 51, 14, 'Životom svojim zakle se Jahve nad Vojskama: \"Napunit ću te ljudstvom kao skakavcima, zaorit će protiv tebe vika bojna.\"');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (30, 51, 15, 'On snagom svojom stvori zemlju, mudrošću svojom uspostavi krug zemaljski i umom svojim razape nebesa.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (30, 51, 16, 'Kad mu glas zaori, huče vode na nebesima, oblake diže s kraja zemlje: stvara kiši munje, vjetar izvodi iz skrovišta njegovih.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (30, 51, 17, 'Svakom čovjeku pamet stane, svaki se zlatar zastidi svoga kipa, jer svi su mu kipovi samo varka, nema u njima duha.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (30, 51, 18, 'Isprazni su oni, smiješne tvorevine, propast će u dan kazne.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (30, 51, 19, '\'Jakovljev dio\' nije kao oni: jer on je sve stvorio, Izrael pleme je baštine njegove. Jahve nad Vojskama ime je njegovo.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (30, 51, 20, 'Ti si mi bio malj, oružje ratno. Pomlatih tobom narode, razmrskah tobom kraljevstva.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (30, 51, 21, 'Pomlatih tobom konja i konjanika, pomlatih tobom bojna kola i vozača.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (30, 51, 22, 'Pomlatih tobom čovjeka i ženu, pomlatih tobom starca i dijete. Pomlatih tobom mladića i djevojku, pomlatih tobom pastira i stado.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (30, 51, 23, 'Pomlatih tobom ratara i zapregu njegovu, pomlatih tobom namjesnike i upravljače.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (30, 51, 24, 'Ali na vaše oči sada plaća Babilonu i svim Kaldejcima za sve zlo koje učiniše Sionu - riječ je Jahvina.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (30, 51, 25, '\"Evo me na te, Goro zatornice - riječ je Jahvina - zatornice svega svijeta! Zamahnut ću rukom protiv tebe, svalit ću te s litice, pretvorit ću te u goru spaljenu.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (30, 51, 26, 'Iz tebe više neće klesati kamen ugaoni ni kamen temeljac, bit ćeš vječna pustinja\" - riječ je Jahvina.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (30, 51, 27, 'Podignite stijeg u zemlji, zatrubite u rog među narodima! Pripremite na nj narode, sazovite na nj kraljevstva - Ararat, Mini, Aškenaz! Postavite protiv njega pozivnike, nek\' nasrnu konji k\'o dlakavi skakavci!');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (30, 51, 28, 'Spremite na nj narode, kraljeve medijske, vojvode i namjesnike njihove i svu zemlju kojom vladaju.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (30, 51, 29, 'Zemlja će se tresti, drhtati, kad se stanu uspinjati k Babilonu svi naumi Jahvini da pretvori zemlju babilonsku u pustinju nenastanjenu.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (30, 51, 30, 'Nebojše babilonske odustaše od borbe, u utvrdama posjedaše, nesta sile njihove: postadoše kao žene. Spaljeni su domovi njihovi, polomljeni zasuni na vratima.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (30, 51, 31, 'Teklič tekliča prestiže, glasnik juri za glasnikom, da jave kralju babilonskom da mu je grad sa svih strana zauzet,');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (30, 51, 32, 'prijelazi zaposjednuti, tvrđave ognjem popaljene, a ratnici prestrašeni.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (30, 51, 33, 'Jer ovako govori Jahve, Bog Izraelov: \"Kći je babilonska kao gumno u vrijeme kad se po njem gazi; još malo, i doći će joj vrijeme žetve.\"');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (30, 51, 34, 'Izjeo me, satro babilonski kralj, odgurnuo me kao prazan pladanj, k\'o zmaj me on progutao, napunio trbušinu, iz mog me istjerao Edena.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (30, 51, 35, '\"Nasilje i patnje moje na Babilon!\" govore stanovnici Siona. \"Krv moja na Kaldejce!\" govori Jeruzalem.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (30, 51, 36, 'Zato ovako govori Jahve: \"Gle, ja ću braniti parnicu tvoju i krvavo te osvetiti. Sasušit ću more njegovo i presahnut ću izvore njegove.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (30, 51, 37, 'Babilon će biti hrpa ruševina, brlog čagljima, užas i ruglo, kraj nenastanjen.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (30, 51, 38, 'Svi zajedno riču k\'o lavovi, zavijaju kao lavići.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (30, 51, 39, 'Kad se ugriju, priredit će im pijanku, napojiti ih da se provesele, da zaspe vječnim snom, da se više ne probude - riječ je Jahvina.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (30, 51, 40, 'Odvest ću ih k\'o janjce na klanje, kao jarce i ovnove.\"');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (30, 51, 41, '\"Kako li je zauzet, kako osvojen taj ponos zemlje sve? Kako li Babilon posta strašilo narodima?');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (30, 51, 42, 'Uzdiglo se more protiv Babilona, prekrilo ga valovlje njegovo.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (30, 51, 43, 'Gradovi mu pustoš postali, zemlja suha, pustara: čovjek u njoj ne stanuje, niti njom prolazi sin čovječji.\"');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (30, 51, 44, '\"Kaznit ću Bela babilonskog, iz ralja mu otet što je progutao. Neće više k njemu hrliti narodi, srušit će se babilonske zidine.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (30, 51, 45, 'Izađi iz njega, narode moj! Nek\' svaki spasi život svoj od jarosnoga gnjeva Jahvina!');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (30, 51, 46, 'Neka vam srce ne klone! Ne bojte se glasÄa što se zemljom šire, jedne godine ovakvi, druge onakvi, i što u zemlji vlada nasilje, te silnik za silnikom ustaje.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (30, 51, 47, 'Jer evo dolaze dani kada ću kazniti kipove babilonske, i sva će mu se zemlja postidjeti, i svi će mu pobijeni ležat\' posred grada.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (30, 51, 48, 'Tada će nad Babilonom klicati nebo i zemlja i sve što je na njima, jer će sa sjevera navaliti na grad, zatornici njegovi - riječ je Jahvina!');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (30, 51, 49, 'I Babilon mora pasti za pobijene Izraelce, kao što su za Babilon padali pobijeni po svem svijetu.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (30, 51, 50, 'Vi što umakoste maču, idite, ne ostajte ovdje. Spominjite se Jahve u zemlji dalekoj, i neka vam Jeruzalem bude na srcu:');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (30, 51, 51, '\'Stidjeli smo se slušajuć\' sramotu, rumenilo nam prekrilo lice kad ono tuđinci nahrupiše u Svetište Doma Jahvina.\'');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (30, 51, 52, 'Zato, evo, dolaze dani - riječ je Jahvina - kad ću kazniti kipove njegove i po svoj će mu zemlji stenjat\' ranjenici.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (30, 51, 53, 'Da se Babilon popne do neba, da se utvrdi na visu nedostupnu, na moju će zapovijed na nj navalit\' pustošnici\" - riječ je Jahvina.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (30, 51, 54, 'Čujte vapaj iz Babilona, i strašan poraz iz zemlje kaldejske!');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (30, 51, 55, 'Jer sam Jahve pustoši Babilon, on stišava strašnu buku njegovu: bučili su vali njegovi k\'o vode velike, razlijegala se huka njihova.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (30, 51, 56, 'Jest, pustošnik dođe na Babilon, uhvaćeni su ratnici njegovi, lukovi im polomljeni. Zaista, Jahve je Bog osvetnik koji plaća po zasluzi!');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (30, 51, 57, '\"Opojit ću mu knezove i mudrace, vojvode, namjesnike i ratnike: da zaspe vječnim snom pa se više ne probude\" - govori Kralj, ime mu je Jahve nad Vojskama.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (30, 51, 58, 'Ovako govori Jahve nad Vojskama: \"Široke zidine babilonske bit će do temelja razvaljene, a visoka trava njegova bit će ognjem spaljena. Narodi se zalud trudili, puci se za oganj mučili!\"');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (30, 51, 59, 'Evo zapovijedi što je prorok Jeremija dade Seraji, sinu Mahsejina sina Nerije, kad je Seraja krenuo u Babilon sa Sidkijom, kraljem judejskim, četvrte godine njegova vladanja. Seraja bijaše veliki komornik.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (30, 51, 60, 'Jeremija je u jednu knjigu bio zapisao svu nesreću koja je morala doći na Babilon - sva ona proroštva napisana protiv Babilona.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (30, 51, 61, 'Jeremija reče Seraji: \"Kad dođeš u Babilon, išti prigodu da obznaniš sve ove riječi.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (30, 51, 62, 'I reci: \'Jahve, ti sam reče da ćeš zatrti ovo mjesto te u njemu ničega više neće biti, ni čovjeka ni živinčeta, nego će postati vječna pustinja.\'');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (30, 51, 63, 'Kad pročitaš ovu knjigu, zaveži je za kamen i baci uEufrat.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (30, 51, 64, 'I reci: \'Ovako će potonuti Babilon i neće se više podići iz nesreće koju ću na nj svaliti.\'\" To su riječi Jeremijine.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (30, 52, 1, 'Sidkiji je bila dvadeset i jedna godina kad se zakraljio, a kraljevao je jedanaest godina u Jeruzalemu. Materi mu bijaše ime Hamitala, kćerka Jeremije, i bila je iz Libne.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (30, 52, 2, 'Činio je što je zlo u očima Jahvinim, sve kao što je činio Jojakin.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (30, 52, 3, 'To je zadesilo Jeruzalem zbog gnjeva Jahvina; Jahve ih napokon i odbaci ispred lica svoga. Sidkija se pobunio protiv babilonskog kralja.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (30, 52, 4, 'Devete godine njegova kraljevanja, desetoga dana desetoga mjeseca, krenu sam babilonski kralj Nabukodonozor sa svom svojom vojskom na Jeruzalem. Utabori se pred gradom i opasa ga opkopom.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (30, 52, 5, 'Grad osta opkoljen sve do jedanaeste godine Sidkijina kraljevanja.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (30, 52, 6, 'Devetoga dana četvrtoga mjeseca, kad je u gradu zavladala takva glad da priprosti puk nije imao ni kruha,');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (30, 52, 7, 'neprijatelj provali u grad. Tada kralj i svi ratnici pobjegoše noću kroz vrata između dva zida nad Kraljevskim vrtom - Kaldejci bijahu opkolili grad - i krenuše putem prema Arabi.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (30, 52, 8, 'Kaldejske čete nagnuše za njim u potjeru i sustigoše Sidkiju na Jerihonskim poljanama, a sva se njegova vojska razbježala.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (30, 52, 9, 'I Kaldejci uhvatiše kralja i odvedoše ga u Riblu, u zemlji hamatskoj, pred kralja babilonskog, koji mu izreče presudu.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (30, 52, 10, 'Pokla Sidkijine sinove pred njegovim očima, pobi u Ribli sve Judine knezove;');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (30, 52, 11, 'Sidkiji iskopa oči i okova ga verigama i odvede u Babilon, gdje ga je držao u tamnici sve do smrti njegove.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (30, 52, 12, 'Desetoga dana petoga mjeseca - devetnaeste godine kraljevanja Nabukodonozora, kralja babilonskog - uđe u Jeruzalem Nebuzaradan, zapovjednik tjelesne straže.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (30, 52, 13, 'On zapali Dom Jahvin, kraljevski dvor i sve kuće u Jeruzalemu, osobito kuće uglednika;');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (30, 52, 14, 'kaldejske čete, pod zapovjednikom tjelesne straže, razoriše zidine oko Jeruzalema.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (30, 52, 15, 'Nebuzaradan, zapovjednik tjelesne straže, odvede u sužanjstvo ostatak naroda koji bijaše ostao u gradu, a tako i prebjege babilonskom kralju i ostalu svjetinu.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (30, 52, 16, 'Neke od malih ljudi Nebuzaradan ostavi u zemlji kao vinogradare i ratare.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (30, 52, 17, 'Kaldejci razbiše tučane stupove u Domu Jahvinu, podnožja i mjedeno more u Domu Jahvinu, i tuč odniješe u Babilon.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (30, 52, 18, 'Uzeše i lonce, lopate, noževe, posudice i uopće sav tučani pribor koji se upotrebljavao za bogoslužja.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (30, 52, 19, 'Zapovjednik uze i umivaonice, kadionice, škropionice, lonce, svijećnjake, zdjele, žrtvene pehare, uopće sve što bijaše od zlata i srebra,');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (30, 52, 20, 'dva stupa, jedno more i dvanaest tučanih volova pod morem, podnožja što je kralj Salomon dao izraditi za Dom Jahvin. Nije moguće procijeniti koliko je tuča bilo u svim tim predmetima.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (30, 52, 21, 'Prvi stup bijaše visok osamnaest lakata - obuhvatiti ga je mogao konop od dvanaest lakata - bijaše četiri prsta debeo, a šupalj.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (30, 52, 22, 'Imao je glavicu od tuča, visoku pet lakata; i obvijaše je oplet i mogranji, a sve od tuča. Takav je bio i drugi stup.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (30, 52, 23, 'A devedeset i šest šipaka slobodno je visjelo. Sve u svemu bijaše oko sto šipaka u tom opletu.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (30, 52, 24, 'Zapovjednik je straže odveo svećeničkog poglavara Seraju, drugog svećenika, Sefaniju, i tri čuvara praga.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (30, 52, 25, 'Iz grada je odveo jednog dvorjanina, vojničkog zapovjednika, sedam ljudi iz kraljeve pratnje koji se zatekoše u gradu, pisara zapovjednika vojske koji je novačio puk te šezdeset pučana koji se također zatekoše u gradu.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (30, 52, 26, 'Zapovjednik tjelesne straže Nebuzaradan odvede ih pred kralja babilonskog u Riblu.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (30, 52, 27, 'I kralj babilonski zapovjedi da ih pogube u Ribli, u zemlji hamatskoj. Tako su judejski narod odveli s njegove rodne grude.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (30, 52, 28, 'Evo broja ljudstva što ga Nabukodonozor odvede u sužanjstvo: sedme godine tri tisuće i dvadeset tri Judejca;');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (30, 52, 29, 'osamnaeste godine Nabukodonozorove osamsto trideset i dvije osobe iz Jeruzalema;');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (30, 52, 30, 'dvadeset i treće godine Nabukodonozorove, Nebuzaradan, zapovjednik tjelesne straže, odvede sedam stotina četrdeset i pet Judejaca. U svemu: četiri tisuće i šest stotona osoba.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (30, 52, 31, 'A trideset i sedme godine otkako je zasužnjen judejski kralj Jojakin, dvadeset i petoga dana dvanaestoga mjeseca, babilonski kralj Evil Merodak u prvoj godini svoje vladavine pomilova judejskoga kralja Jojakina i pusti ga iz tamnice.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (30, 52, 32, 'Ljubezno je s njim razgovarao i stolicu mu postavio više nego drugim kraljevima koji bijahu s njim u Babilonu.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (30, 52, 33, 'Jojakin je odložio svoje tamničke haljine i jeo s kraljem za istim stolom svega svoga vijeka.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (30, 52, 34, 'Do kraja njegova života, sve do smrti, babilonski mu je kralj trajno, iz dana u dan, davao uzdržavanje.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (31, 1, 1, 'Kako osamljena sjedi prijestolnica, nekoć naroda puna; postade kao udovica, nekoć velika među narodima. Vladarica nad pokrajinama, na tlaku sad ide.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (31, 1, 2, 'Noći provodi gorko plačući, suzama pokriva obraze. Nikog nema da je utješi, od svih koji su je ljubili. Svi je prijatelji iznevjeriše i postaše joj neprijatelji.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (31, 1, 3, 'Izagnan je Juda, u nevolji je i u progonstvu teškom. Sad živi među poganima, ne nalazi počinka. Svi ga gonitelji sustižu u tjesnacima.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (31, 1, 4, 'Putovi sionski tuguju jer nitko ne dolazi na svetkovine. Sva su vrata razvaljena, svećenici uzdišu, ucviljene su djevice njegove, a on je pun gorčine.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (31, 1, 5, 'Tlačitelji njegovi sada gospodare, neprijatelji likuju: Jahve ga ucvili zbog grijeha njegovih premnogih. Djeca mu otišla u izgnanstvo pred tlačiteljem.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (31, 1, 6, 'Povukla se od Kćeri sionske sva slava njezina. Knezovi joj postadoše k\'o ovnovi koji paše ne nalaze; nemoćni vrludaju ispred goniča.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (31, 1, 7, 'Jeruzalem se spominje danÄa bijede i lutanja, kad mu narod dušmanu u ruke pade a nitko mu pomoći ne pruži. Tlačitelji ga gledahu smijući se njegovoj propasti.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (31, 1, 8, 'Teško sagriješi Jeruzalem, postade kao nečistoća ženina. Svi što ga štovahu, sada ga preziru: jer vidješe golotinju njegovu. On samo plače i natrag se okreće.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (31, 1, 9, 'Skuti su mu uprljani, nije ni sanjao što ga čeka. Duboko je pao, a nikog da ga tješi. \"Pogledaj, Jahve, moju nevolju: jer neprijatelj likuje.\"');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (31, 1, 10, 'Neprijatelj poseže rukom za svim dragocjenostima njegovim. Gledao je gdje pogani provaljuju u njegovo Svetište, oni kojima si zabranio i pristup u svoj zbor.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (31, 1, 11, 'Sav narod njegov jeca, tražeći kruha; svi daju dragulje za hranu da bi ponovo živnuli. Evo, Jahve, pogledaj kako sam prezren.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (31, 1, 12, 'Svi vi što putem prolazite, pogledajte i vidite ima li boli kakva je bol kojom sam ja pogođen, kojom me Jahve udari u dan žestokog gnjeva svoga!');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (31, 1, 13, 'S visine pusti oganj, utjera ga u kosti moje. Pred noge mrežu mi razape i tako me nauznak obori; ucvili me, ožalosti za sva vremena.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (31, 1, 14, 'Natovario me mojim grijesima, rukom ih svojom pritegnuo; na vrat mi ih navalio, snagu mi oduzeo. Predao me Gospod u ruke njihove, ne mogu se uspraviti.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (31, 1, 15, 'Sve junake iz moje sredine Gospod odbaci: digao je zbor protiv mene da uništi uzdanicu moju. U tijesku izgazi Gospod mene, djevicu, kćerku Judinu.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (31, 1, 16, 'Zato moram plakati, oči mi suze liju, jer daleko je od mene moj tješitelj da mi duh povrati. Sinovi su moji poraženi, odveć silan bijaše neprijatelj.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (31, 1, 17, 'Sion pruža ruke: nema mu tješitelja. Jahve je protiv Jakova sa svih strana pozvao tlačitelje; i tako Jeruzalem postade među njima strašilo.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (31, 1, 18, 'Jahve, on je pravedan; jer riječi se njegovoj protivih. Oh, čujte, narodi svi, gledajte moju bol: djevice moje, moji mladići, svi odoše u izgnanstvo!');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (31, 1, 19, 'Pozvah sve ljubavnike svoje, ali me oni prevariše. Moji svećenici i starješine pogiboše u gradu tražeći hrane da bi ponovo živnuli.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (31, 1, 20, 'Pogledaj, Jahve, u kakvoj sam tjeskobi, moja utroba strepi, srce mi se u grudima grči jer bijah opako prkosan! Vani mač pokosi moje sinove, a unutra - smrt.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (31, 1, 21, 'Čuj kako stenjem: nema mi tješitelja! Svi neprijatelji čuju za moju nesreću i likuju što si to učinio! Daj da dođe dan što si ga objavio, da njima bude kao meni.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (31, 1, 22, 'Neka se pokaže sva njina zloća pred licem tvojim, a onda postupaj s njima kao što si sa mnom postupio za sve grijehe moje! Jer samo uzdišem, a srce moje tuguje.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (31, 2, 1, 'Kako mrakom zastrije Gospod u svom gnjevu Kćer sionsku. S neba na zemlju baci slavu Izraelovu! I ne sjeti se podnožja svoga u dan gnjeva svojega!');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (31, 2, 2, 'Bez milosti Gospod satrije sve stanove Jakovljeve, u svom gnjevu razori tvrđave kćeri Judine; sa zemljom je sravnio i prokleo kraljevstvo i njegove knezove.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (31, 2, 3, 'U rasplamtjelom gnjevu svojem razbi svu snagu Izraelovu, povuče svoju desnicu pred neprijateljem; u Jakovu raspiri plamen ognjeni koji sve uokolo proždire.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (31, 2, 4, 'Nategao je luk k\'o neprijatelj, kao dušman ispružio desnicu, ubijajući sve što mu drago bijaše. Na šator Kćeri sionske sasu k\'o oganj gnjev svoj jarosni.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (31, 2, 5, 'K\'o neprijatelj Gospod bijaše: razorio je Izraela, razorio sve dvore njegove, porušio njegove utvrde, umnožio kćeri Judinoj uzdisaje i jecaje.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (31, 2, 6, 'Kao vrtu razvali mu sjenicu, razori mjesto sastanka. Baci Jahve u zaborav svetkovine i subote na Sionu; u gnjevu svojem prezre kralja i svećenika.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (31, 2, 7, 'Svoj oltar je Gospod odbacio, zgadilo mu se Svetište njegovo. U ruke neprijatelja je predao bedeme svoje i dvorove. Bučili su u Domu Jahvinu, kao u dan blagdanji.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (31, 2, 8, 'Jahve naumi razvaliti zidove Kćeri sionske. Nape uže mjerničko, ne ustegnu ruku od rušenja. Predziđe, zidine zavi u tugu: oronuše zajedno.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (31, 2, 9, 'Vrata njina utonuše u zemlju, on im je razbio zasune; kralj i knezovi su među pucima, Zakona nema! Ni u prorokÄa više se ne nalaze viđenja Jahvina.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (31, 2, 10, 'Starješine Kćeri sionske na zemlji sjede i šute, posiplju glavu prašinom, kostrijet pripasuju. K zemlji glave obaraju djevice jeruzalemske.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (31, 2, 11, 'Iščilješe mi oči od suza, utroba moja ustreptala, jetra mi se na zemlju prosula zbog sloma kćeri naroda mojega, jer djeca i dojenčad umiru po trgovima Grada.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (31, 2, 12, 'Govore majkama svojim: \"Gdje je žito i vino?\" dok obamiru kao ranjeni po trgovima Grada, dok ispuštaju dušu svoju na grudima matera svojih.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (31, 2, 13, 'S čime da te prispodobim? Na koga si nalik, Kćeri jeruzalemska? S kime da te usporedim, kako utješim, djevice, Kćeri sionska? Jer kao more tvoja je nesreća neizmjerna. Tko će te iscijeliti?');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (31, 2, 14, 'Viđenja tvojih proroka bijahu varka i laž, oni nisu objavili krivnju tvoju da te od izgnanstva odvrate. Varali su te utvarama lažnim i zamamnim.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (31, 2, 15, 'Nad tobom plješću rukama svi koji putem prolaze, zvižde i vrte glavom zbog Kćeri jeruzalemske: \"Je li to grad na glasu ljepotom, radost svemu svijetu?\"');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (31, 2, 16, 'Na tebe otvaraju usta svi neprijatelji tvoji, zvižde, škrguću zubima i govore: \"Proždrijesmo je! To je dan za kojim čeznusmo, doživjesmo, vidjesmo!\"');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (31, 2, 17, 'Jahve izvrši naum svoj, održa svoju riječ koju naredi u davnim danima: nemilice te razorio. Neprijatelj likuje zbog tebe, tvoj protivnik rog svoj podiže.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (31, 2, 18, 'U sav glas viči Gospodu, jecaj, Kćeri sionska! Neka k\'o potok teku tvoje suze danju i noću. Ne daj počinka sebi, neka se zjenica oka tvoga ne odmori.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (31, 2, 19, 'Ustani, viči noću za svake promjene straže. K\'o vodu izlij srce pred licem Gospodnjim, k njemu podiži ruke i traži milost za svoju nejačad koja od glada obamire po uglovima ulica.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (31, 2, 20, 'Pogledaj, Jahve, i vidi kome si to učinio. Zar žene da jedu porod svoj, djecu što njišu u naručju? Zar moradoše biti poklani u Svetištu Gospodnjem svećenici i proroci?');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (31, 2, 21, 'U uličnoj prašini leže djeca i starci; moje djevice i moji mladići od mača padoše. Ti ih pomori u dan gnjeva svojega, ti ih pokla nemilice.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (31, 2, 22, 'Ti si, kao na dan svečani, sa svih strana sazvao užase moje. U dan gnjeva Jahvina nitko nije preživio, nitko se nije spasio. One koje sam odnjihala i odgojila neprijatelj moj sve je istrijebio.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (31, 3, 1, 'Ja sam čovjek što upozna bijedu pod šibom gnjeva njegova.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (31, 3, 2, 'Mene je odveo i natjerao da hodam u tmini i bez svjetlosti.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (31, 3, 3, 'I upravo mene bije i udara bez prestanka njegova ruka.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (31, 3, 4, 'Iscijedio je moje meso, kožu moju, polomio kosti moje.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (31, 3, 5, 'Načinio mi jaram, glavu obrubio tegobama.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (31, 3, 6, 'Pustio me da živim u tminama kao mrtvaci vječiti.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (31, 3, 7, 'Zazidao me, i ja ne mogu izaći, otežao je moje okove.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (31, 3, 8, 'Kada sam vikao i zapomagao, molitvu je moju odbijao.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (31, 3, 9, 'Zazidao mi ceste tesanim kamenom, zakrčio je putove moje.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (31, 3, 10, 'Meni on bijaše medvjed koji vreba, lav u zasjedi.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (31, 3, 11, 'U bespuća me vodio, razdirao, ostavljao me da umirem.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (31, 3, 12, 'Napinjao je luk svoj i gađao me kao metu za svoje strelice.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (31, 3, 13, 'U slabine mi sasuo strelice, sinove svoga tobolca.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (31, 3, 14, 'Postao sam smiješan svome narodu, rugalica svakidašnja.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (31, 3, 15, 'Gorčinom me hranio, pelinom me napajao.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (31, 3, 16, 'Puštao me da zube kršim kamen grizući, zakapao me u pepeo.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (31, 3, 17, 'Duši je mojoj oduzet mir i više ne znam što je sreća!');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (31, 3, 18, 'Rekoh: Dotrajao je život moj i nada koja mi od Jahve dolazi.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (31, 3, 19, 'Spomeni se bijede moje i stradanja, pelina i otrova!');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (31, 3, 20, 'Bez prestanka na to misli i sahne duša u meni.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (31, 3, 21, 'To nosim u srcu i gojim nadu u sebi.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (31, 3, 22, 'Dobrota Jahvina nije nestala, milosrđe njegovo nije presušilo.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (31, 3, 23, 'Oni se obnavljaju svako jutro: tvoja je vjernost velika!');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (31, 3, 24, '\"Jahve je dio moj\", veli mi duša, \"i zato se u nj pouzdajem.\"');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (31, 3, 25, 'Dobar je Jahve onom koji se u nj pouzdaje, duši koja ga traži.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (31, 3, 26, 'Dobro je u miru čekati spasenje Jahvino!');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (31, 3, 27, 'Dobro je čovjeku da nosi jaram za svoje mladosti.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (31, 3, 28, 'Neka sjedi u samoći i šuti, jer mu On to nametnu;');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (31, 3, 29, 'neka usne priljubi uz prašinu, možda još ima nade!');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (31, 3, 30, 'Neka pruži obraz onome koji ga bije, neka se zasiti porugom.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (31, 3, 31, 'Jer Gospod ne odbacuje nikoga zauvijek:');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (31, 3, 32, 'jer ako i rastuži, on se smiluje po svojoj velikoj ljubavi.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (31, 3, 33, 'Jer samo nerado on ponižava i rascvili sinove čovjeka.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (31, 3, 34, 'Kad se gaze nogama svi zemaljski sužnjevi,');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (31, 3, 35, 'kad se izvrće pravica čovjeku pred licem Svevišnjeg,');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (31, 3, 36, 'kad se krivica nanosi čovjeku u parnici, zar Gospod ne vidi?');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (31, 3, 37, 'Tko je rekao nešto i zbilo se? Nije li Gospod to zapovjedio?');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (31, 3, 38, 'Ne dolazi li iz usta Svevišnjega i dobro i zlo?');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (31, 3, 39, 'Na što se tuže živi ljudi? Svatko na svoj grijeh.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (31, 3, 40, 'Ispitajmo, pretražimo pute svoje i vratimo se Jahvi.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (31, 3, 41, 'Dignimo svoje srce i ruke svoje k Bogu koji je na nebesima.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (31, 3, 42, 'Da, mi smo se odmetali, bili nepokorni, a ti, ti nisi praštao!');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (31, 3, 43, 'Obastrt gnjevom svojim, gonio si nas, ubijao i nisi štedio.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (31, 3, 44, 'Oblakom si se obastro da molitva ne prodre do tebe.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (31, 3, 45, 'Načinio si od nas smeće i odmet među narodima.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (31, 3, 46, 'Razjapili usta na nas svi neprijatelji naši.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (31, 3, 47, 'Užas i jama bila nam sudbina, propast i zator!');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (31, 3, 48, 'Potoci suza teku iz očiju mojih zbog propasti Kćeri naroda mojega.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (31, 3, 49, 'Moje oči liju suze bez prestanka, jer prestanka nema');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (31, 3, 50, 'dok ne pogleda i ne vidi Jahve s nebesa.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (31, 3, 51, 'Moje mi oko bol zadaje zbog kćeri svih mojega grada.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (31, 3, 52, 'Uporno me k\'o pticu progone svi što me mrze, a bez razloga.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (31, 3, 53, 'U jamu baciše moj život i zatrpaše je kamenjem.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (31, 3, 54, 'Voda mi dođe preko glave, rekoh sam sebi: \"Pogiboh!\"');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (31, 3, 55, 'I tada zazvah ime tvoje, Jahve, iz najdublje jame.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (31, 3, 56, 'Ti oču moj glas: \"Ne začepljuj uši svoje na vapaje moje.\"');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (31, 3, 57, 'Bliz meni bijaše u dan vapaja mog, govoraše: \"Ne boj se!\"');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (31, 3, 58, 'Ti si, Gospode, izborio pravdu za dušu moju, ti si život moj izbavio.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (31, 3, 59, 'Ti, Jahve, vidje kako me tlače, dosudi mi pravdu.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (31, 3, 60, 'Ti vidje svu osvetu njinu, sve podvale protiv mene.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (31, 3, 61, 'Čuo si, Jahve, podrugivanje njihovo, sve podvale protiv mene.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (31, 3, 62, 'Usne protivnika mojih i misli njine protiv mene su cio dan.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (31, 3, 63, 'Kad sjede, kad ustaju, pogledaj samo: ja sam im pjesma-rugalica.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (31, 3, 64, 'Vrati im, Jahve, milo za drago, po djelu ruku njihovih.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (31, 3, 65, 'Učini da srca im otvrdnu, udari ih prokletstvom svojim.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (31, 3, 66, 'Goni ih gnjevno i sve ih istrijebi pod nebesima svojim, Jahve!');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (31, 4, 1, 'Jao, potamnje zlato, to suho zlato! Sveto se kamenje prosu na uglovima svih ulica.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (31, 4, 2, 'Sinovi sionski, nekoć cijenjeni kao najčišće zlato, ah, sada ih cijene kao sudove glinske, kao djelo ruku lončarevih!');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (31, 4, 3, 'Čak i šakali pružaju dojke i doje mladunčad, ali kćeri naroda moga postaše okrutne kao nojevi u pustinji.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (31, 4, 4, 'Jezik dojenčeta za nepce se lijepi od žeđi. Djeca vape za kruhom, a nikog da im ga pruži.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (31, 4, 5, 'Oni što se nekoć sladiše biranim jelima ginu po ulicama; nekoć nošeni u grimizu, sada se valjaju po buništu.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (31, 4, 6, 'Veći bijaše zločin Kćeri naroda moga od grijeha Sodome, što u tren oka bi razorena, a ničija se ruka ne diže na nju.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (31, 4, 7, 'Njeni mladići bijahu nekoć čišći od snijega, bjelji od mlijeka, od koralja rumenija bijahu im tijela, lice glatko k\'o safir.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (31, 4, 8, 'Sad im je obraz crnji od čađe, ne prepoznaju se više na ulici. Koža im se lijepi za kosti, suha kao drvo.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (31, 4, 9, 'Kako su sretni oni što ih mač probode, sretniji od onih koje pomori glad; koji padaju, iscrpljeni, jer im nedostaju plodovi zemljini.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (31, 4, 10, 'Žene, tako nježne, kuhaše djecu svoju, njima se hraniše za propasti Kćeri naroda moga.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (31, 4, 11, 'Jahve je utolio svoj bijes, izlio jarosnu srdžbu svoju, na Sionu raspirio požar što sažiže i same temelje njegove.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (31, 4, 12, 'Nisu vjerovali kraljevi zemaljski ni svekoliko stanovništvo zemlje da će ugnjetač i neprijatelj ući na vrata jeruzalemska -');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (31, 4, 13, 'zbog grijeha svojih prorokÄa, zbog bezakonja svećenikÄa koji usred grada prolijevahu krv pravednikÄa!');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (31, 4, 14, 'K\'o slijepi teturahu ulicama, omašteni krvlju, te nitko nije smio da se takne odjeće njihove.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (31, 4, 15, '\"Natrag, nečisti!\" - viču im. \"Natrag! Ne dirajte!\" I tada pobjegoše poganima, al\' ne smjedoše ondje ostati.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (31, 4, 16, 'Raspršilo ih lice Jahvino, on ih više nije gledao. Ne poštuju više svećenikÄa, ne sažaljuju staraca.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (31, 4, 17, 'Već nam oči iščilješe iščekujući pomoć, ali uzalud; s kula naših zureć\' u daljinu očekivasmo narod koji nas ne može spasiti.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (31, 4, 18, 'Vrebaju nam na korake da ne hodamo po trgovima svojim. Bliži nam se kraj, navršili nam se dani, naš konac dolazi.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (31, 4, 19, 'Naši gonitelji bijahu brži od orlova na nebu; u planini nas ganjahu, u pustinji dočekivahu u zasjedi.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (31, 4, 20, 'Naš životni dah, Jahvin pomazanik, pade u njihove jame - on za koga govorasmo: \"U sjeni njegovoj živjet ćemo među narodima.\"');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (31, 4, 21, 'Raduj se i veseli se, Kćeri edomska, ti koja živiš u zemlji Usu: doći će i do tebe čaša, opit ćeš se i razgoliti.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (31, 4, 22, 'Tvoj grijeh je iskupljen, Kćeri sionska, neće te više u izgnanstvo voditi. Kaznit će opačinu tvoju, Kćeri edomska, razotkriti grijehe tvoje.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (31, 5, 1, 'Spomeni se, Jahve, što nas je snašlo, pogledaj, vidi sramotu našu!');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (31, 5, 2, 'Baština naša pade u ruke strancima, domovi naši pripadoše tuđincima.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (31, 5, 3, 'Siročad smo: oca nemamo, majke su nam kao udovice.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (31, 5, 4, 'Vodu što pijemo plaćamo novcem, i za drvo valja nam platiti.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (31, 5, 5, 'Jaram nam je o vratu, gone nas, iscrpljeni smo, ne daju nam predahnuti.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (31, 5, 6, 'Pružamo ruke k Egiptu i Asiriji da se kruha nasitimo.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (31, 5, 7, 'Oci naši zgriješiše i više ih nema, a mi nosimo krivice njihove.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (31, 5, 8, 'Robovi nama zapovijedaju, a nitko da nas izbavi iz ruku njihovih.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (31, 5, 9, 'Kruh svoj donosimo izlažući život maču u pustinji.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (31, 5, 10, 'Koža nam gori kao peć užarena, ognjicom od plamena gladi.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (31, 5, 11, 'Oskvrnuli su žene na Sionu i djevice u gradovima judejskim.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (31, 5, 12, 'Svojim su rukama vješali knezove, ni lica staračka nisu poštivali.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (31, 5, 13, 'Mladići su nosili žrvnjeve, djeca padala pod bremenom drva.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (31, 5, 14, 'Starci su ostavili vrata, mladići više ne sviraju na lirama.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (31, 5, 15, 'Radosti nesta iz naših srdaca, naš ples se pretvori u tugovanje.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (31, 5, 16, 'Pao je vijenac s naše glave, jao nama što zgriješismo!');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (31, 5, 17, 'Evo zašto nam srce boluje, evo zašto nam oči se zastiru:');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (31, 5, 18, 'zato što Gora sionska opustje i po njoj se šuljaju šakali.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (31, 5, 19, 'Ali ti, Jahve, ostaješ zauvijek, tvoj je prijesto od koljena do koljena.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (31, 5, 20, 'Zašto da nas zaboraviš zauvijek, da nas ostaviš za mnoge dane?');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (31, 5, 21, 'Vrati nas k sebi, Jahve, obratit ćemo se, obnovi dane naše kao što nekoć bijahu.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (31, 5, 22, 'Il\' nas hoćeš sasvim zabaciti i na nas se beskrajno srditi?');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (32, 1, 1, 'Ovo su riječi knjige koju u Babilonu napisa Baruh, sin Nerije, sina Maaseje, sina Sidkije, sina Hasadije, sina Hilkije,');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (32, 1, 2, 'pete godine, sedmoga dana u mjesecu, u vrijeme kada su Kaldejci osvojili Jeruzalem i spalili ga.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (32, 1, 3, 'Baruh pročita riječi ove knjige pred Jekonijom, sinom Jojakimovim, kraljem Judinim, i pred čitavim narodom koji bijaše došao na čitanje knjige;');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (32, 1, 4, 'pred mogućnicima i kraljevim sinovima, pred starješinama, ukratko, pred svim narodom, malim i velikim, pred svima koji su živjeli u Babilonu, na obalama rijeke Suda.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (32, 1, 5, 'Čuvši, plakali su, postili i molili se pred Gospodom.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (32, 1, 6, 'Sabraše i novca, koliko tko mogaše,');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (32, 1, 7, 'i poslaše ga u Jeruzalem svećeniku Jojakimu, sinu Hilkije, Šalumova sina, i ostalim svećenicima i svemu narodu koji se s njim nalazio u Jeruzalemu.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (32, 1, 8, 'Desetoga dana mjeseca Sivana Baruh je spasio posuđe kuće Gospodnje što bijaše ugrabljeno iz Hrama da bi ga odnio natrag u zemlju Judinu - srebrno posuđe što ga je načinio Sidkija, sin Jošijin, kralj Judin,');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (32, 1, 9, 'kad je Nabukodonozor, kralj babilonski, odveo iz Jeruzalema i u Babilon doveo Jekoniju s knezovima, ključarima, mogućnicima i svim narodom.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (32, 1, 10, 'I napisaše: Evo, šaljemo vam novac da njime kupite žrtve paljenice i tamjan; pripravite žrtve i prinesite ih za grijehe na žrtveniku Gospoda, Boga našega.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (32, 1, 11, 'I molite se za život Nabukodonozora, kralja babilonskog, i za život sina njegova Baltazara da im dani na zemlji budu kao dani neba;');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (32, 1, 12, 'neka nam Gospod dade snage i prosvijetli oči naše da bismo živjeli u sjeni Nabukodonozora, kralja babilonskog, i u sjeni njegova sina Baltazara, da bismo ih dugo služili te našli milost pred njima.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (32, 1, 13, 'Molite se i za nas Gospodu, Bogu našem, jer smo ga uvrijedili i do danas se gnjev i srdžba Gospodnja nije odvratila od nas.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (32, 1, 14, 'Čitajte, dakle, knjigu koju vam šaljemo i obznanite je u kući Gospodnjoj, na blagdan i u dane Zborovanja.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (32, 1, 15, 'Recite tada: Pravedan je Gospod, Bog naš! Ali nama treba da se danas zacrvene od stida obrazi - nama Judejcima i žiteljima jeruzalemskim,');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (32, 1, 16, 'našim kraljevima i knezovima, našim svećenicima i prorocima i našim ocima,');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (32, 1, 17, 'jer smo griješili pred Gospodom, bili mu nepokorni');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (32, 1, 18, 'i nismo slušali glasa Gospoda, Boga svojega, da hodimo po zapovjedima koje Gospod bijaše stavio pred nas.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (32, 1, 19, 'Od dana kada je oce naše izveo iz Egipta pa do dana današnjega nepokorni smo bili Gospodu, Bogu svojem, i nismo marili da čujemo njegov glas.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (32, 1, 20, 'Tada navališe na nas nevolje i prokletstva kojima se Gospod zaprijetio sluzi svome Mojsiju u dan kada je izveo oce naše iz Egipta da bi nam dao zemlju kojom teče med i mlijeko. I tako je to do danas.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (32, 1, 21, 'Nismo bili poslušali glas Gospoda, Boga svojega, ni riječi njegovih preko proroka koje nam je on slao;');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (32, 1, 22, 'svaki je od nas hodio po nagnuću svoga opakog srca, služeći drugim bogovima i čineći što nije po volji Gospodu, Bogu našem.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (32, 2, 1, 'Zato je Gospod izvršio prijetnju koju je naviještao protiv nas, protiv naših sudaca koji su sudili Izraelu, protiv naših kraljeva i knezova, protiv naroda Izraelova i Judina:');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (32, 2, 2, 'pod čitavim nebom nije se još dogodilo ništa slično onome što se dogodilo u Jeruzalemu, prema onome što bijaše zapisano u Mojsijevu Zakonu -');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (32, 2, 3, 'da se jelo meso sina i kćeri.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (32, 2, 4, 'Predao ih je vlasti svih kraljevstava oko nas, na porugu i prokletstvo među svim okolnim narodima kamo ih je raspršio Gospod.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (32, 2, 5, 'Bijahu podjarmljeni umjesto da budu gospodari, jer - sagriješismo Gospodu, Bogu svojemu, ne poslušavši glasa njegova.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (32, 2, 6, 'Da, pravedan je Gospod, Bog naš! Ali nama - nama treba da se danas zacrvene od stida obrazi, nama i ocima našim.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (32, 2, 7, 'Oborila se na nas sva zla kojima nam Gospod bijaše zaprijetio.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (32, 2, 8, 'Mi pak nismo umolili lice Gospodnje odvrativši se od misli svojih opakih srdaca.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (32, 2, 9, 'Gospod tada uze bdjeti nad nevoljama koje je navalio na nas; jer pravedan je Gospod u svim djelima koja nam je naložio,');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (32, 2, 10, 'ali mi nismo slušali njegova glasa niti smo hodili po zapovijedima koje je Gospod pred nas stavio.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (32, 2, 11, 'A sada, Gospode, Bože Izraelov, koji si snažnom rukom izveo narod svoj iz Egipta znamenjima i čudesima, velikom snagom i ispruženom desnicom, proslavivši tako ime svoje do dana današnjega:');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (32, 2, 12, 'mi smo sagriješili, bezbožni smo bili i nepravedni pred svim tvojim zapovijedima, Gospode, Bože naš!');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (32, 2, 13, 'Neka se odvrati gnjev tvoj od nas, jer smo samo malen ostatak među narodima kamo si nas raspršio.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (32, 2, 14, 'Usliši, Gospode, molitvu našu i vapaj: izbavi nas poradi sebe i udijeli nam milost svoju, pred licem onih koji su nas u sužanjstvo odveli,');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (32, 2, 15, 'da sva zemlja zna da si ti Gospod, Bog naš, jer Izrael i njegov rod nosi tvoje ime.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (32, 2, 16, 'Obazri se, Gospode, iz svetoga svoga prebivališta i svrni misao na nas, prikloni uho i poslušaj,');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (32, 2, 17, 'otvori oči i pogledaj: tÓa mrtvi u podzemnom svijetu - kojima je iz utrobe oduzet dah - ne, oni više ne kazuju slave i pravednosti Gospodnje;');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (32, 2, 18, 'samo duša ojađena, koja hodi pognuto i iznemoglo, ugaslih očiju, duša pregladnjela, Gospode, iskazuje tvoju slavu i pravednost!');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (32, 2, 19, 'O Gospode, Bože naš! Ne upravljamo svoje prošnje tvome licu zbog zasluga svojih otaca i svojih kraljeva;');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (32, 2, 20, 'nego jer si ti poslao na nas gnjev svoj i srdžbu svoju, kako si bio navijestio po prorocima, slugama svojim, ovim riječima:');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (32, 2, 21, '\"Ovako govori Gospod: Prignite šiju i služite kralju babilonskom, da ostanete u zemlji koju sam dao ocima vašim.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (32, 2, 22, 'Ne poslušate li nalog Gospodnji da služite kralju babilonskom,');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (32, 2, 23, 'učinit ću da iz gradova judejskih i s trgova jeruzalemskih nestane pjesme radosti i pjesme veselja, pjesme zaručnika i pjesme zaručnice, i sva će zemlja postati pustoš bez stanovnika.\"');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (32, 2, 24, 'Ali mi nismo poslušali glasa tvog da služimo kralju babilonskom, i ti si tada izvršio prijetnje koje si navijestio po prorocima, slugama svojim, da će kosti kraljeva naših i kosti naših otaca biti izbačene iz svog počivališta.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (32, 2, 25, 'I doista, one bjehu izbačene na žegu dana i studen noći. I umiralo se u strašnim mukama od kuge, gladi i mača.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (32, 2, 26, 'A od kuće koja nosi Ime tvoje učinio si ono što je ona danas, zbog zloće kuće Izraelove i kuće Judine.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (32, 2, 27, 'Pa ipak, Gospode, Bože naš, postupio si s nama po svoj svojoj dobroti i prevelikoj blagosti,');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (32, 2, 28, 'kako si obećao po sluzi svome Mojsiju onoga dana kada si mu zapovjedio da napiše Zakon tvoj za sinove Izraela ovim riječima:');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (32, 2, 29, '\"Ako ne poslušate glasa mog, ovo veliko i bezbrojno mnoštvo zacijelo će se smanjiti među narodima kamo ću ih raspršiti;');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (32, 2, 30, 'a znam, taj narod tvrde šije neće poslušati. Ali u zemlji svog sužanjstva oni će se opametiti');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (32, 2, 31, 'i spoznati da sam ja Gospod, Bog njihov. I dat ću im srce i uši da čuju.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (32, 2, 32, 'Oni će me hvaliti u zemlji svog izgnanstva i spominjat će se moga imena; obratit će se, i smekšat će im se tvrda šija,');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (32, 2, 33, 'i odvratit će se od opakih svojih djela, jer sjetit će se sudbine otaca svojih kad su griješili Gospodu.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (32, 2, 34, 'Tada ću ih dovesti natrag u zemlju koju sam obećao zaklevši se njihovim ocima Abrahamu, Izaku i Jakovu, da gospodare njome. I umnožit ću ih, i oni se više neće smanjivati.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (32, 2, 35, 'I uspostavit ću s njima vječni Savez: ja ću biti njihov Bog, a oni će biti moj narod. I neću više izgoniti svog naroda Izraela iz zemlje koju sam im dao.\"');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (32, 3, 1, 'Svevladaru Gospode, Bože Izraelov, tebi viče duša tjeskobna, duh uznemiren:');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (32, 3, 2, 'Čuj, Gospode, i smiluj se jer smo sagriješili pred tobom.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (32, 3, 3, 'Ti vladaš vječito, a mi propadamo bez prestanka.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (32, 3, 4, 'Gospode svemogući, Bože Izraelov, čuj dakle molitvu samrtnika Izraelovih, sinova onih koji su protiv tebe sagriješili, koji nisu slušali glasa Gospoda, Boga svojega, pa zato navališe na nas nevolje.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (32, 3, 5, 'Ne spominji se opačina naših otaca, već se spomeni u ovo vrijeme ruke svoje i Imena svoga.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (32, 3, 6, 'Da, ti si Gospod, Bog naš, i mi te hoćemo slaviti, Gospode.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (32, 3, 7, 'TÓa zato si nam u srce usadio strah svoj da bismo zazvali Ime tvoje i da bismo te proslavili u izgnanstvu uklonivši iz srca svu zloću naših otaca, koji su sagriješili pred tobom.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (32, 3, 8, 'Evo nas još danas u ovom izgnanstvu kamo si nas raspršio na užas, prokletstvo i pokaranje zbog svih opačina naših.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (32, 3, 9, 'Čuj, Izraele, životne propise, prisluhni da naučiš mudrost.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (32, 3, 10, 'Zašto, o Izraele, zašto si u zemlji neprijatelja i zašto stariš u tuđini,');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (32, 3, 11, 'onečišćujuć\' se mrtvacima, ubrojen među one koji su u Podzemlju?');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (32, 3, 12, 'Zato što si Vrelo Mudrosti ostavio!');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (32, 3, 13, 'Da si Božjim hodio putem, zauvijek bi prebivao u miru.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (32, 3, 14, 'Nauči stoga gdje je mudrost, gdje snaga, gdje li razboritost, pa da ujedno spoznaš u čemu je dugovječnost i život i gdje je svjetlost očinja i mir.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (32, 3, 15, 'Ali tko je otkrio prebivalište Mudrosti, tko li prodro u njene riznice?');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (32, 3, 16, 'Gdje su vladari narodÄa, gdje gospodari zvijeri zemaljskih,');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (32, 3, 17, 'gdje oni koji se igrahu pticÄa nebeskih i oni koji zgrtahu srebro i zlato - u što se ljudi uzdaju - te ne bijaše kraja zgrtanju njihovu?');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (32, 3, 18, 'I gdje su oni koji s tolikim trudom srebro kovahu da im djela nitko natkriliti ne može?');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (32, 3, 19, 'Iščezli su, otišli u Podzemlje! Na njihovo mjesto dođoše drugi.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (32, 3, 20, 'Mlađi ugledaše svjetlo dana, nastaniše zemlju, no puta Mudrosti ni oni ne otkriše;');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (32, 3, 21, 'staza njenih ni oni ne razumješe, ne doumiše joj se - sinovi njeni daleko ostadoše od puta njezina.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (32, 3, 22, 'Nije se čulo o njoj u Kanaanu niti se vidjela u Temanu;');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (32, 3, 23, 'ni sinovi Hagarini što zemsku umnost ištu, ni trgovci iz Midjana i Teme, ni pjesnici priča, ni istraživači umnosti ne spoznaše puta Mudrosti, ne dovinuše se staza njezinih.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (32, 3, 24, 'Kako je veliko, o Izraele, kako je veliko Božje prebivalište i kako je prostrano mjesto posjeda njegova?');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (32, 3, 25, 'Veliko i bezgranično, visoko - neizmjerno!');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (32, 3, 26, 'Ondje se rodiše divovi, čuveni od davnine, rastom golemi, vješti u boju;');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (32, 3, 27, 'ali njih ne izabra Bog niti im povjeri put spoznanja;');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (32, 3, 28, 'izginuše jer ne imaše mudrosti, izginuše sa svoje ludosti.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (32, 3, 29, 'Tko se na nebo pope, pa da je dohvati - na oblake, pa da je skine?');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (32, 3, 30, 'Tko prebrodi more da bi je otkrio pa da je kupi za najčistije zlato?');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (32, 3, 31, 'Nitko ne zna njezina puta i nitko njezine staze ne shvaća.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (32, 3, 32, 'Sveznajući - samo je on poznaje, svojim je umom proniče: on koji je za sva vremena sazdao zemlju i svu je životinjama naselio;');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (32, 3, 33, 'on koji pošalje svjetlost, i ona, gle, pođe; natrag je zovne, i dršćuć\' ona ga posluša.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (32, 3, 34, 'Zvijezde mu veselo sjaju na svojim postajama;');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (32, 3, 35, 'zovne li ih, one mu odgovore: \"Evo nas!\" - i radosno sjaju svom Stvoritelju.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (32, 3, 36, 'On je naš Bog: nitko se drugi s njim usporedit\' ne može.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (32, 3, 37, 'On je pronikao sav put spoznaje i predao je sluzi svom Jakovu - Izraelu, svome ljubimcu.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (32, 3, 38, 'Potom se ona na zemlji pojavila, među ljudima udomila.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (32, 4, 1, 'Ona je knjiga Božjih zapovijedi, Zakon koji će trajati dovijeka: tko ga se držao bude, taj će živjeti; tko ga napusti, taj će umrijeti.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (32, 4, 2, 'Vrati se, Jakove, i prihvati je, hodi k sjaju, k njenoj svjetlosti:');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (32, 4, 3, 'ne ustupaj slavu svoju drugomu, ni dostojanstvo svoje narodu tuđemu.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (32, 4, 4, 'Blago nama, Izraele, jer nam je otkriveno što je Bogu po volji!');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (32, 4, 5, 'Ohrabri se, narode moj, spomene Izraelov!');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (32, 4, 6, 'Bili ste prodani narodima, ali ne na uništenje. Boga ste razgnjevili, stoga biste izručeni neprijateljima;');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (32, 4, 7, 'Stvoritelja svog ste izazvali žrtvujući zlodusima, a ne Bogu.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (32, 4, 8, 'Zaboravili ste Boga vječnog, svoga hranioca! Ožalostili ste i Jeruzalem - majku koja vas je othranila.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (32, 4, 9, 'Kada je vidjela gdje se na vas obara gnjev od Boga, stade naricati: \"Slušajte, susjede sionske: u tugu veliku zavi me Gospod.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (32, 4, 10, 'Vidjeh gdje mi u sužanjstvo izruči Vječni sinove i kćeri.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (32, 4, 11, 'S radošću sam ih hranila, s tugom i plačem gledam gdje odlaze.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (32, 4, 12, 'Nitko nek\' se nada mnom ne raduje što obudovjeh i ostadoh sama. Zbog grijeha djece svoje opustjeh, jer se okrenuše od Božjeg Zakona.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (32, 4, 13, 'Nisu marili za njegove zapovijedi niti išli putovima njegovih propisa, niti stupali stazom stege u njegovoj pravednosti.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (32, 4, 14, 'Dođite, susjede sionske! Gledajte gdje mi u sužanjstvo predaje Vječni sinove i kćeri!');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (32, 4, 15, 'Doveo je na njih narod iz daljine, narod drzak, tuđega jezika, bez poštovanja prema starcu, bez smilovanja prema djetetu;');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (32, 4, 16, 'odvedoše udovi ljubimce, ostaviše je samu, bez kćeri.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (32, 4, 17, 'Kako bih vam mogla ja pomoći?');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (32, 4, 18, 'Samo onaj koji dovede na vas ove nevolje izbavit\' vas može iz ruku neprijatelja.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (32, 4, 19, 'Idite, djeco, otiđite svojim putem! Ja ostajem napuštena, samotna;');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (32, 4, 20, 'skinuh haljinu mira, odjenuh se u kostrijet svojih vapaja: sve dane svoje zazivat ću Vječnoga.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (32, 4, 21, 'Ohrabrite se, djeco, zavapite Bogu: on će vas izbaviti iz nasilja, iz ruku neprijatelja.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (32, 4, 22, 'Jer u Vječnog se uzdam, on će vas spasiti; od Svetoga očekujem radost: uskoro na vas će se smilovati, Vječni, Spasitelj vaš.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (32, 4, 23, 'S tugom i plačem vidjeh vas gdje odlazite, ali Bog će vas meni vratiti s radošću i klicanjem za sva vremena.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (32, 4, 24, 'Kao što susjede sionske vidješe gdje vas zasužnjuju, tako će naskoro vidjeti gdje će vas izbaviti Bog, koji će doći u velikoj slavi i sjaju Vječnoga.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (32, 4, 25, 'Djeco moja, podnesite pokaranje što se obori na vas od Boga. Neprijatelj te progonio, al\' uskoro vidjet ćeš njegovu propast, na njegovu ćeš šiju staviti nogu.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (32, 4, 26, 'Moja su nježna djeca hodila grubim putovima, otjerana kao stado što ga ote neprijatelj.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (32, 4, 27, 'Ohrabrite se, djeco, zavapite Bogu: Onaj koji vas stavi na kušnju, on će vas se spomenuti.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (32, 4, 28, 'Ako vam je misao, zastranivši, bila daleko od Boga, vratite se i tražite ga revnošću deseterostrukom.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (32, 4, 29, 'Jer onaj koji je na vas nesreću doveo, vašim će spasenjem vratiti vam vječnu radost.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (32, 4, 30, 'Ohrabri se, Jeruzaleme, utješit će te onaj koji ti dade ime.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (32, 4, 31, 'Jao onima koji te zlostavljaju, koji se vesele tvojoj propasti!');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (32, 4, 32, 'Jao gradovima kojima su tvoja djeca robovala, teško onom koji ti odvede sinove!');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (32, 4, 33, 'Jer kao što je uživao u tvojemu padu i tvojoj se propasti radovao, tako će tugovati nad svojim opustošenjem.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (32, 4, 34, 'Neće se veseliti mnogome pučanstvu, obijest će mu se preobratit\' u tugovanje,');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (32, 4, 35, 'od Vječnoga na nj će doći oganj za mnogo dana, i za dugo vrijeme bit će stan zlodusima.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (32, 4, 36, 'Obazri se na istok, Jeruzaleme, vidi radost što ti dolazi od Boga.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (32, 4, 37, 'Evo, vraćaju ti se sinovi koje si vidio gdje odlaze, sabiru se u tebi od istoka do zapada na zapovijed Svetoga i kliču u slavu Božju.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (32, 5, 1, 'Skini, Jeruzaleme, haljinu tugovanja i nesreće, odjeni se zauvijek ljepotom slave Božje,');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (32, 5, 2, 'ogrni se plaštem Božje pravednosti, stavi na glavu vijenac slave Vječnoga;');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (32, 5, 3, 'jer Bog hoće pokazati sjaj tvoj svemu pod nebom');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (32, 5, 4, 'i zasvagda ti hoće dati ime: \'Mir pravednosti\' i \'Slava bogoljubnosti\'.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (32, 5, 5, 'Ustani, Jeruzaleme, stani na visoko i obazri se na istok: Pogledaj! Djeca se tvoja sabiru, od istoka do zapada, na zapovijed Svetoga, radujuć\' se što ih se spomenuo Bog.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (32, 5, 6, 'Otišli su od tebe pješice, vodio ih neprijatelj, a gle, Bog ih tebi vraća nošene u slavlju, kao djecu kraljevsku.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (32, 5, 7, 'I naredi Bog: neka se snize sve visoke gore i vječne klisure; nek\' se doline ispune i poravna zemlja da Izrael čvrsto kroči u sjaju slave Božje.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (32, 5, 8, 'A šume i sva stabla mirisna činit će sjenu Izraelu po Božjoj zapovijedi;');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (32, 5, 9, 'jer Bog će voditi Izraela u radosti, u svjetlu njegove slave, prateć\' ga milosrđem svojim i pravednošću.\"');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (32, 6, 1, 'Prijepis poslanice koju je poslao Jeremija sužnjima koje je kralj Babilonaca uskoro imao odvesti u Babilon da im saopći preporuke što mu ih je povjerio Bog. Zbog grijeha što ste ih pred Bogom počinili, Nabukodonozor, kralj Babilonaca, odvest će vas kao sužnje u Babilon.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (32, 6, 2, 'Kada stignete u Babilon, ostat ćete ondje mnogo godina i za dugo vrijeme, do sedmog naraštaja, a potom ću vas odande u miru izvesti.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (32, 6, 3, 'A u Babilonu vidjet ćete bogove - srebrne, zlatne i drvene - koji se nose na leđima i koji neznabošcima strah zadaju.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (32, 6, 4, 'Čuvajte se! Ne povodite se za tuđim narodima i nemojte da vas pred tim bogovima strah obuzme');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (32, 6, 5, 'kad opazite pred njima i za njima mnoštvo koje im se klanja. Recite u srcu: \"Tebi se, Gospode, jedinomu treba klanjati.\"');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (32, 6, 6, 'Jer s vama je moj anđeo - njemu ste životom svojim odgovorni.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (32, 6, 7, 'Jezik im je izgladio umjetnik, drugi su ih obložili zlatom i srebrom: obmana su i govoriti ne mogu.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (32, 6, 8, 'Kao za gizdavu djevojku, uzimaju zlato i prave krune za glave svojih bogova.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (32, 6, 9, 'A dogodi se te svećenici potkradaju sa svojih bogova zlato i srebro i troše ga za sebe; daruju ga čak i bludnicama u bludilištima. Ukrašuju ih haljinama kao ljude -');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (32, 6, 10, 'te bogove, srebrne, zlatne i drvene, no oni se od hrđe i crvotoči obraniti ne mogu');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (32, 6, 11, 'usprkos grimizu kojim ih odijevaju. Potrebno im je čistiti lica od hramske prašine koja napada na njih.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (32, 6, 12, 'Jedan drži žezlo kao poglavar pokrajine, ali nikog tko bi ga uvrijedio ne može pogubiti;');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (32, 6, 13, 'drugi u desnici drži mač i sjekiru, ali se ne može obraniti ni od rata ni od razbojnika.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (32, 6, 14, 'Po tom jasno slijedi: to bogovi nisu - njih se, dakle, ne bojte!');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (32, 6, 15, 'Kao što posuda kojom se čovjek služi postaje beskorisnom kada se razbije, tako je i s njihovim bogovima koji su postavljeni u hramovima.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (32, 6, 16, 'Oči su im pune prašine što je dižu noge onih koji ulaze.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (32, 6, 17, 'I kao što su na sve strane zatvorena vrata onome koji se ogriješio o kralja te ima biti pogubljen, tako svećenici utvrđuju hramove ovih bogova vratima, bravama i zasunima, bojeći se da ih razbojnici ne opljačkaju.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (32, 6, 18, 'Užižu im svjetiljke u mnogo većem broju negoli sebi samima, ali nijedne od njih bogovi ne mogu vidjeti.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (32, 6, 19, 'Nalik su na grede hrama: srce im iznutra, kažu, crvi rastaču - crvi koji gmižu iz zemlje te rastaču njih i njihove haljine.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (32, 6, 20, 'Oni i ne osjećaju da im je lice pocrnjelo od dima što se diže u hramu.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (32, 6, 21, 'Na njihova tijela i glave dolijeću šišmiši, lastavice i druge ptice; a ima i mačaka.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (32, 6, 22, 'Po tim ćete znacima prepoznati da to bogovi nisu - njih se, dakle, ne bojte!');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (32, 6, 23, 'Ne očiste li im naslagu sa zlata kojim su obloženi za ukras, sami ga neće osvjetlati. Nisu ni osjećali dok su ih salijevali.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (32, 6, 24, 'Kupovali su ih za najvišu cijenu, a nema u njima životnoga daha.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (32, 6, 25, 'Bez nogu su, pa ih na ramenima nose i tad pokazuju svoje ruglo ljudima; stide ih se i oni koji im služe,');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (32, 6, 26, 'jer padne li koji bog na zemlju, oni ga moraju podići; usprave li ih, oni se sami od sebe neće pomaći; ako se nagnu, ne mogu se uspraviti.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (32, 6, 27, 'Kao mrtvacima darove im prinose. Svećenici im njihovi tada odnose žrtve da izvuku korist prodajući ih. Isto tako i njihove žene prigrabe po dio, ne dijeleći ništa siromasima i nemoćnima. Njihovih se žrtava dotiču žene u čišćenju, a i porodilje.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (32, 6, 28, 'Po tom dobro znate: to bogovi nisu - ništa ih se ne bojte!');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (32, 6, 29, 'TÓa kako biste ih mogli zvati bogovima? Tima srebrnim, zlatnim i drvenim bogovima žrtve prinose žene.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (32, 6, 30, 'U njihovim hramovima svećenici sjede poderanih haljina, obrijane glave i brade, ne pokrivajući glave;');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (32, 6, 31, 'tule i viču pred svojim bogovima, kao na mrtvačkim gozbama.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (32, 6, 32, 'Svećenici im skidaju haljine te njima odijevaju svoje žene i djecu.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (32, 6, 33, 'Učine li im kakvo dobro ili zlo, oni to ne mogu uzvratiti;');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (32, 6, 34, 'niti mogu koga učiniti kraljem ili ga svrgnuti; niti mogu dati bogatstvo ili novac. Učini li im tko zavjet pa ga ne održi, oni ga ne mogu prisiliti da za to odgovara.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (32, 6, 35, 'Oni ne mogu čovjeka spasiti od smrti niti slabijeg osloboditi od jačeg;');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (32, 6, 36, 'ne mogu slijepcu vratiti vid niti izbaviti čovjeka iz nevolje;');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (32, 6, 37, 'ne mogu se smilovati udovici niti učiniti dobro siroti.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (32, 6, 38, 'Nalik su na kamenje iz planine, ti bogovi obloženi zlatom i srebrom. Oni koji ih štuju stidjet će se!');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (32, 6, 39, 'Kako se, dakle, mogu smatrati ili nazivati bogovima!');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (32, 6, 40, 'I sami ih Kaldejci obeščašćuju; jer videći nijema čovjeka koji ne može govoriti, oni ga dovode Belu i traže da čovjek progovori, kao da bi ga bog mogao čuti;');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (32, 6, 41, 'i nesposobni su promisliti o tome i ostaviti te bogove, toliko su lišeni razbora!');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (32, 6, 42, 'Žene opasane užetom sjede na putovima i pale kad od maslinovih ljusaka;');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (32, 6, 43, 'kada koju od njih snubi prolaznik da mu se poda, ona se ruga svojoj susjedi što je nisu zapazili kao nju i što joj uže nije prekinuto.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (32, 6, 44, 'Sve što se događa u blizini tih bogova prijevara je; kako ih, dakle, mogu smatrati ili nazivati bogovima!');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (32, 6, 45, 'Načiniše ih drvodjelje i zlatari, i nisu drugo doli tvorevina njihova.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (32, 6, 46, 'Njihovi izrađivači ne žive dugo; kako bi njihove rukotvorine bile bogovi?');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (32, 6, 47, 'Jer svojim će potomcima ostaviti samo obmanu i sramotu.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (32, 6, 48, 'Ako ljude pogodi rat ili nevolja, svećenici se među sobom savjetuju gdje da se s njima sakriju;');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (32, 6, 49, 'kako ne uvidjeti da to nisu bogovi kad ni sami sebe ne mogu izbaviti od rata i od nevolja?');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (32, 6, 50, 'Po svemu tomu znat će se: ti drveni idoli, obloženi zlatom ili srebrom, samo su prijevara! Svima, narodima i kraljevima, bit će jasno: nisu to bogovi, nego su djela ruku ljudskih: nikakva Božjeg udjela u njima nema!');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (32, 6, 51, 'Kome, dakle, neće biti jasno: to bogovi nisu?');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (32, 6, 52, 'TÓa ne mogu oni postaviti kralja u nekoj zemlji niti dati kišu ljudima;');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (32, 6, 53, 'ne mogu presuditi u svojim poslovima niti izbaviti potlačenog; nemoćni su oni poput vrana između neba i zemlje.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (32, 6, 54, 'Neka padne vatra na hram tih drvenih bogova obloženih zlatom ili srebrom, njihovi će svećenici pobjeći i spasiti se, dok će oni ondje izgorjeti kao grede.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (32, 6, 55, 'Oni se ne mogu opirati ni kralju ni neprijatelju.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (32, 6, 56, 'Kako onda pomisliti ili povjerovati da su to bogovi?');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (32, 6, 57, 'Ti drveni bogovi obloženi srebrom i zlatom ne mogu se obraniti ni od kradljivaca ni od razbojnika: kako su ovi jači od njih, opljačkat će im zlato i srebro i otići s haljinama u koje su odjeveni; oni su nesposobni sebi samima pomoći.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (32, 6, 58, 'Zato je bolje biti kralj koji dokazuje svoju hrabrost, ili u kući korisna posuda kojom se vlasnik služi nego lažni bogovi; bolja su i vrata u kući koja čuvaju ono što je u njoj nego lažni bogovi; i drveni stup u kakvoj palači bolji je nego lažni bogovi.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (32, 6, 59, 'Sunce, mjesec i zvijezde, dok sjaju da izvrše službu, poslušni su.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (32, 6, 60, 'Milina je vidjeti i munju kada sijevne. A vjetar donosi dah svoj zemlji,');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (32, 6, 61, 'i oblaci, kada im Gospod zapovjedi da oblete svu zemlju, odmah izvrše nalog Božji. Vatra, poslana odozgo da sažeže gore i šume, izvršava što joj je naloženo.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (32, 6, 62, 'Sa svim ovim ti se bogovi ni ljepotom ni snagom usporediti ne mogu.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (32, 6, 63, 'Zato se ne može misliti ni reći da su to bogovi, jer nisu sposobni kazniti niti učiniti dobra ljudima.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (32, 6, 64, 'Kada, dakle, znate da to bogovi nisu, njih se ne bojte!');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (32, 6, 65, 'Oni ne mogu ni prokleti ni blagosloviti kraljeva;');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (32, 6, 66, 'niti mogu narodima pokazati znamenja na nebu; oni ne sjaju kao sunce niti svijetle kao mjesec.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (32, 6, 67, 'Zvijeri su od njih bolje; pobjeći one mogu u skrovište i sebi pomoći.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (32, 6, 68, 'Nikako nam, dakle, nije jasno da su to bogovi; stoga ih se ne bojte!');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (32, 6, 69, 'Kao ptičje strašilo u nečuvanu polju lubenica, takvi su njihovi drveni bogovi obloženi zlatom i srebrom.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (32, 6, 70, 'Jednako su slični glogovu grmu u vrtu na koji sjeda svaka ptica ili mrtvacu bačenu u mrak - ti drveni bogovi obloženi zlatom i srebrom.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (32, 6, 71, 'Po grimizu i crvenilu što na njima trune prepoznat ćete da to nisu bogovi. Napokon i sami budu izjedeni te postanu na sramotu zemlji.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (32, 6, 72, 'Koliko je bolji pravednik koji nema kumirÄa; sramota je daleko od njega!');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (33, 1, 1, 'Godine tridesete, četvrtoga mjeseca, petoga dana, kad bijah među izgnanicima na rijeci Kebaru, otvoriše se nebesa i ja ugledah božanska viđenja.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (33, 1, 2, 'Petoga dana istoga mjeseca - godine pete otkako odvedoše u izgnanstvo kralja Jojakima -');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (33, 1, 3, 'riječ Jahvina dođe Ezekielu, sinu Buzijevu, svećeniku u zemlji kaldejskoj, na rijeci Kebaru. Spusti se na me ruka Jahvina.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (33, 1, 4, 'Pogledah, kad ono sa sjevera udario silan vihor, velik oblak, bukteći oganj obavijen sjajem; usred njega, usred ognja, nešto nalik na sjajnu kovinu.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (33, 1, 5, 'Usred toga nešto kao četiri bića, obličjem slična čovjeku;');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (33, 1, 6, 'svako od njih sa četiri obraza, u svakoga četiri krila.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (33, 1, 7, 'Noge im ravne, a stopala kao u teleta; sijevahu poput glatke mjedi.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (33, 1, 8, 'Ispod krila imahu na sve četiri strane ruke čovječje. I svako od njih četvero imaše svoj obraz i svoja krila.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (33, 1, 9, 'Krila im se spajahu jedno s drugim. Idući, ne okretahu se: svako se naprijed kretaše.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (33, 1, 10, 'I u sva četiri bijaše lice čovječje; u sva četiri zdesna lice lavlje; u sva četiri slijeva lice volujsko; i lice orlovsko u sva četiri.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (33, 1, 11, 'Krila im bijahu gore raskriljena. Svako imaše dva krila što se spajahu i dva krila kojim tijelo pokrivahu.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (33, 1, 12, 'I svako iđaše samo naprijed. A iđahu onamo kamo ih je duh gonio. I ne okretahu se idući.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (33, 1, 13, 'A posred tih bića vidjelo se kao neko užareno ugljevlje, kao goruće zublje koje se među njima kretahu; iz ognja sijevaše i munje bljeskahu.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (33, 1, 14, 'Bića trčahu i opet se vraćahu poput munje.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (33, 1, 15, 'Dok ja promatrah, gle: na zemlji uza svako od četiri bića po jedan točak.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (33, 1, 16, 'Točkovi bijahu slični krizolitu, sva četiri istoga oblika; oblikom i napravom bijahu kao da je jedan točak u drugome.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (33, 1, 17, 'U kretanju mogli su ići u sva četiri smjera a nisu se morali okretati.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (33, 1, 18, 'Naplatnice im bijahu visoke, a kad bolje promotrih, gle, na sve strane pune očiju.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (33, 1, 19, 'Kad bi bića krenula, krenuli bi s njima i točkovi; kad bi se bića sa tla podigla, i točkovi se podizahu.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (33, 1, 20, 'Kuda ih je duh gonio, onuda se kretahu, a zajedno se s njima i točkovi podizali, jer duh bića bijaše u točkovima.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (33, 1, 21, 'Pa kad su bića krenula, i točkovi bi krenuli, a kad bi se ona zaustavila, ustavljali se i točkovi; kad se ona sa tla dizahu, i točkovi se s njima podizahu, jer duh bića bijaše u točkovima.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (33, 1, 22, 'Nad glavama bića bijaše nešto kao svod nebeski, nalik na sjajan prozirac, uzdignut nad njihovim glavama.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (33, 1, 23, 'A pod svodom raskriljena krila, jedno prema drugome: svakome po dva krila pokrivahu tijelo.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (33, 1, 24, 'Čuh lepet njihovih krila kao huk velikih voda, kao glas Svesilnog, kao silan vihor, kao graju u taboru. Kad bi se bića zaustavila, spustila bi krila.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (33, 1, 25, 'Sa svoda nad njihovim glavama čula se grmljavina.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (33, 1, 26, 'Ispod svoda nad njihovim glavama bijaše nešto kao kamen safir, poput prijestolja: na tom kao prijestolju, gore na njemu, kao neki čovjek.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (33, 1, 27, 'I vidjeh kao sjajnu kovinu, iznutra i uokolo kao oganj; od njegovih bokova naviše i od njegovih bokova naniže nešto poput ognja i blijeska na sve strane.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (33, 1, 28, 'Taj blijesak na sve strane bijaše poput duge što se za kišnih dana javlja u oblaku. To bijaše nešto kao slava Jahvina. Vidjeh, padoh ničice i čuh glas koji mi govoraše.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (33, 2, 1, 'I reče mi: \"Sine čovječji, na noge se, da s tobom govorim!\"');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (33, 2, 2, 'OI uđe u me duh, kako mi progovori, te me podiže na noge i ja čuh glas onoga koji mi govoraše.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (33, 2, 3, 'I reče mi: \"Sine čovječji, šaljem te k sinovima Izraelovim, k narodu odmetničkom što se odvrže od mene. Oni i oci njihovi griješili su protiv mene sve do dana današnjega.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (33, 2, 4, 'Šaljem te k sinovima tvrdokorna pogleda i okorjela srca. Reci im: Ovako govori Jahve Gospod!');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (33, 2, 5, 'I poslušali oni ili ne poslušali - rod su odmetnički - neka znaju da je prorok među vama.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (33, 2, 6, 'A ti, sine čovječji, ne boj ih se i ne plaši se riječi njihovih: \'Trnje te okružuje i sjediš među samim skorpijama.\' Ne plaši se riječi njihovih i ne boj se nimalo njihova pogleda jer oni su rod odmetnički.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (33, 2, 7, 'Govori im moje riječi, poslušali oni ili ne poslušali, jer rod su odmetnički.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (33, 2, 8, 'A ti, sine čovječji, poslušaj što ću ti sada reći: Ne budi odmetnik kao što su oni rod odmetnički! Otvori usta i progutaj što ću ti sada dati!\"');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (33, 2, 9, 'I pogledah, a to ruka k meni ispružena i u njoj, gle, svitak knjige.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (33, 2, 10, 'I razvi se knjiga preda mnom: bijaše ispisana izvana i iznutra, a u njoj napisano: \"Naricanje! Jecanje! Jauk!\"');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (33, 3, 1, 'I reče mi: \"Sine čovječji, progutaj što je pred tobom! Pojedi taj svitak, te idi i propovijedaj domu Izraelovu!\"');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (33, 3, 2, 'Otvorih usta, a on mi dade da progutam svitak');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (33, 3, 3, 'i reče: \"Sine čovječji, nahrani trbuh i nasiti utrobu svitkom što ti ga dajem!\" I pojedoh ga, i bijaše mi u ustima sladak kao med.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (33, 3, 4, 'Reče mi: \"Sine čovječji, idi domu Izraelovu i prenesi mu moju poruku.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (33, 3, 5, 'Ne šaljem te k narodu nepoznata jezika i nerazumljiva govora, već te šaljem domu Izraelovu.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (33, 3, 6, 'Ne šaljem te k mnogim narodima nepoznata jezika i nerazumljiva govora koje ti ne bi mogao razumjeti. A kad bih te k njima i poslao, oni bi te poslušali.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (33, 3, 7, 'A dom te Izraelov neće poslušati, jer ni mene ne sluša, jer dom je Izraelov tvrde glave i okorjela srca.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (33, 3, 8, 'Evo, zato ću sada otvrdnuti tvoje lice kao što je i njihovo i glavu ću tvoju učiniti tvrdoglavom kao što je njihova.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (33, 3, 9, 'I ne boj ih se i ne plaši, jer oni su rod odmetnički!\"');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (33, 3, 10, 'Reče mi: \"Sine čovječji, sve riječi što ću ti reći uzmi k srcu i poslušaj ih svojim ušima.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (33, 3, 11, 'I hajde izgnanicima, sinovima svojega naroda, i reci im: Ovako govori Jahve Gospod! - poslušali ili ne poslušali!\"');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (33, 3, 12, 'Uto me duh podiže i ja za sobom čuh silnu tutnjavu. Slava se Jahvina podigla sa svojega mjesta.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (33, 3, 13, 'Čuh lepet krila onih bića - udarahu jedno o drugo - i snažnu škripu točkova što se s njima kretahu i zaglušnu jeku jakoga glasa.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (33, 3, 14, 'Tada me duh prihvati i ponese. I ja iđah ogorčen i gnjevna srca, a ruka me Jahvina čvrsto pritisla.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (33, 3, 15, 'Tako stigoh u Tel Abib, k izgnanicima koji življahu na rijeci Kebaru - onamo gdje se bijahu nastanili - te ostadoh među njima sedam dana kao omamljen.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (33, 3, 16, 'Poslije sedam dana dođe mi opet riječ Jahvina:');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (33, 3, 17, '\"Sine čovječji, postavljam te za čuvara doma Izraelova. I ti ćeš riječi iz mojih usta slušati i opominjat ćeš ih u moje ime.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (33, 3, 18, 'Kad bezbožniku reknem: \'Umrijet ćeš\', a ti ga ne opomeneš i ne odvratiš od zla puta njegova kako bi mu život spasio, on će umrijeti sa svojega bezakonja, ali ću ja od tebe tražiti račun za krv njegovu.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (33, 3, 19, 'A kad opomeneš bezbožnika, a on se ne odvrati od bezakonja i od zla puta svojega, on će umrijeti zbog svoje krivice, a ti ćeš spasiti svoj život.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (33, 3, 20, 'Isto tako, odvrati li se pravednik od svoje pravednosti i stane činiti nepravdu, postavit ću mu zamku i umrijet će jer ga ti ne opomenu zbog njegova grijeha; umrijet će, i njegova se pravedna djela više neće spominjati, ali ću od tebe tražiti račun za krv njegovu.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (33, 3, 21, 'Ako li ti pravednika opomeneš da ne griješi, i on zaista prestane griješiti, živjet će jer je prihvatio opomenu, a i ti ćeš spasiti život svoj.\"');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (33, 3, 22, 'Ondje me opet zahvati ruka Jahvina i on mi reče: \"Ustani i siđi u dolinu da ondje s tobom govorim!\"');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (33, 3, 23, 'Ustadoh tada i siđoh u dolinu, i gle: Slava Jahvina stajaše ondje, slična Slavi koju vidjeh na rijeci Kebaru te padoh ničice.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (33, 3, 24, 'Jahvin duh uđe u me, osovi me na noge i reče: \"Idi i zatvori se u domu svojemu!');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (33, 3, 25, 'Na te ću, evo, sine čovječji, staviti užad i svezati te i više nećeš izlaziti.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (33, 3, 26, 'I jezik ću ti zalijepiti za nepce te ćeš onijemjeti i nećeš ih više karati, jer su rod odmetnički.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (33, 3, 27, 'A kad ti ja progovorim, otvorit ću ti usta i ti ćeš im reći: Ovako govori Jahve Gospod! I tko hoće slušati, neka sluša, a tko neće, neka ne sluša, jer su rod odmetnički.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (33, 4, 1, 'A ti, sine čovječji, uzmi opeku, postavi je preda se i nacrtaj na njoj grad Jeruzalem.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (33, 4, 2, 'Oko njega postavi opsadu, sagradi prema njemu utvrdu, podigni nasip, iskopaj oko njega opkop, razvrstaj vojsku i porazmjesti zidodere uokolo.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (33, 4, 3, 'Zatim uzmi gvozdenu ploču i postavi je kao gvozden bedem između sebe i grada te k njemu okreni lice, i bit će opsjednut. Pritisni ga! To je znak domu Izraelovu!');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (33, 4, 4, 'Zatim lezi na svoju lijevu stranu i stavi na se grijeh doma Izraelova: koliko dana budeš tako ležao, toliko ćeš dana nositi njihov grijeh.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (33, 4, 5, 'Dajem ti po dan za godine grijeha njihovih: sto i devedeset dana nosit ćeš grijeh doma Izraelova.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (33, 4, 6, 'A kad to završiš, četrdeset ćeš dana ležati na desnoj strani da nosiš grijeh doma Judina; dajem ti po dan za svaku godinu.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (33, 4, 7, 'Tad okreni lice prema opsjedanom Jeruzalemu, pruži golu desnicu i prorokuj protiv njega.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (33, 4, 8, 'A ja ću te užetima vezati da se ne možeš okretati s jedne strane na drugu dok ne navršiš dane svoje opsade.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (33, 4, 9, 'Uzmi pšenice, ječma, boba, leće, prosa i raži, stavi to u jednu posudu i pripravi od toga sebi kruh. Jest ćeš ga onoliko dana koliko budeš ležao na svojoj strani: sto i devedeset dana.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (33, 4, 10, 'Jelo što ćeš ga jesti bit će izmjereno; dvadeset šekela na dan; a jest ćeš ga u određeno vrijeme.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (33, 4, 11, 'I vodu ćeš piti na mjeru: šestinu hina. Pit ćeš je u određeno vrijeme.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (33, 4, 12, 'A jest ćeš pogaču od ječma što ćeš je pred njima ispeći na ljudskim izmetinama.\"');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (33, 4, 13, 'I reče: \"Tako će sinovi Izraelovi jesti svoj nečisti kruh među narodima među koje ću ih izagnati.\"');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (33, 4, 14, 'Ja mu odgovorih: \"Jao, Jahve Gospode, gle, moja duša nije okaljana, jer se od djetinjstva još ne okusih ničega uginulog ni rastrganog niti u moja usta ikad uđe meso nečisto.\"');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (33, 4, 15, 'A on će: \"Gle, dajem ti kravlju balegu umjesto ljudskih izmetina da na njoj ispečeš kruh!\"');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (33, 4, 16, 'Još mi reče: \"Sine čovječji, uništit ću u Jeruzalemu posljednju pričuvu kruha, i jest će kruh na mjeru i s tjeskobom, i pit će vodu na mjeru i sa zebnjom.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (33, 4, 17, 'Neka im nestane kruha i vode, neka usahnu zbog bezakonja svojega i jedan za drugim neka poginu!');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (33, 5, 1, 'A ti, sine čovječji, uzmi mač naoštren, uzmi ga kao britvu brijačku i obrij glavu i bradu. Zatim uzmi mjerice i porazdijeli.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (33, 5, 2, 'Trećinu spali posred grada ognjem kad se navrše dani tvoje opsade; trećinu uzmi i sasijeci mačem oko grada; trećinu baci u vjetar - i svoj ću mač trgnuti na njih.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (33, 5, 3, 'Uzmi malo i zaveži u skute haljine.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (33, 5, 4, 'Od toga opet nešto uzmi, baci u vatru i spali: odatle će se razgorjeti vatra svemu domu Izraelovu!\"');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (33, 5, 5, 'Ovako govori Jahve Gospod: \"Ovo je Jeruzalem! Postavih ga u središte naroda, okružih ga zemljama!');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (33, 5, 6, 'Ali se on odupro mojim naredbama većma nego pogani, zakonima mojim većma nego zemlje koje ga okružuju.\"');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (33, 5, 7, 'Stoga ovako govori Jahve Gospod: \"Buntovniji ste od naroda koji vas okružuju, ne hodite po mojim zakonima i ne vršite ni mojih naredaba ni naredaba okolnih naroda.\"');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (33, 5, 8, 'Zato ovako govori Jahve Gospod: \"Evo i mene protiv tebe! Izvršit ću sud svoj nad tobom na oči svih naroda.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (33, 5, 9, 'Zbog tvojih gadosti učinit ću s tobom što još ne učinih nikada nit ću ikad učiniti:');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (33, 5, 10, 'posred tebe očevi će jesti sinove, a sinovi očeve; izvršit ću sud svoj nad tobom i sav ostatak tvoj predati svim vjetrovima!');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (33, 5, 11, 'Života mi moga! - riječ je Jahve Gospoda - svakojakim grozotama i gadostima ti uistinu oskvrnu moje Svetište. I ja ću sada brijati i oko se moje neće sažaliti i neću se smilovati:');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (33, 5, 12, 'trećina će tvojih žitelja posred tebe od kuge skončati i od gladi umrijeti; trećina će oko tebe od mača pasti; trećinu ću predati vjetrovima - i mač ću svoj trgnuti na njih!');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (33, 5, 13, 'Tako ću iskaliti gnjev svoj i smirit će se jarost moja kad im se osvetim. I kad iskalim jarost svoju nad njima, spoznat će da sam to ja, Jahve, u ljubomori svojoj bio rekao.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (33, 5, 14, 'Opustošit ću te, izvrgnut ću te ruglu naroda koji te okružuju, na oči svim prolaznicima.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (33, 5, 15, 'Da, bit ćeš na ruglo i sramotu, opomena i užas okolnim narodima kad izvršim protiv tebe sve svoje sudove kažnjavajući gnjevno, jarosno. Ja, Jahve, rekoh!');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (33, 5, 16, 'I kad na vas pustim ljute strijele gladi što zatiru, koje ću pustiti na vas da vas uništim i glađu zatrem - uništit ću vam i posljednju pričuvu kruha.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (33, 5, 17, 'A povrh gladi pustit ću na vas i divlje zvijeri koje će ti djecu rastrgati; kuga će te i krv preplaviti: pod mač ću te svoj okrenuti. Ja, Jahve, rekoh!\"');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (33, 6, 1, 'Tada mi dođe riječ Jahvina i reče:');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (33, 6, 2, '\"Sine čovječji, okreni lice prema gorama Izraelovim i prorokuj protiv njih.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (33, 6, 3, 'Reci: \'Gore Izraelove, čujte riječ Jahve Gospoda! Ovako govori Jahve Gospod: Gore i brežuljci, jaruge i doline, evo, spustit ću mač na vas i oborit ću uzvišice vaše!');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (33, 6, 4, 'Opustjet će žrtvenici vaši i porušit će se stupovi vaši, a vaše poginule pred kumire ću vam baciti.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (33, 6, 5, 'Pobacat ću trupla sinova Izraelovih pred kumire njihove i rasijat ću kosti vaše oko žrtvenika vaših!');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (33, 6, 6, 'Gdje god boravili, gradovi će vaši biti opustošeni, uzvišice poharane, žrtvenici će vam opustjeti i biti uništeni, kumiri će vaši biti oboreni i nestat će ih, stupovi će vaši biti smrvljeni, sva će djela vaša propasti.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (33, 6, 7, 'Među vas će padati poginuli, i znat ćete da sam ja Jahve!');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (33, 6, 8, 'Ali ću ipak poštedjeti neke od vas: ti će među narodima uteći maču kad se raspršite po zemljama.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (33, 6, 9, 'Tada će se preživjeli među vama spomenuti mene među narodima kamo budu odvedeni u izgnanstvo, kad im slomim srce preljubničko što se odmetnulo od mene i kad im iskopam preljubničke oči što pođoše za kumirima njihovim. I tada će sami sebi omrznuti zbog nedjela što ih počiniše gadostima svojim.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (33, 6, 10, 'I spoznat će da sam ja Jahve: nisam im zaludu govorio da ću ih udariti svim tim zlom.\'\"');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (33, 6, 11, 'Ovako govori Jahve Gospod: \"Pljesni rukama i lupni nogama, te reci: Jao! zbog svih gadnih nedjela dom će Izraelov pasti od mača, gladi i kuge!');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (33, 6, 12, 'Tko bude daleko, od kuge će umrijeti; tko bude blizu, od mača će pasti, i tko bude opkoljen, od gladi će izdahnuti! Tako ću gnjev iskaliti na njima');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (33, 6, 13, 'i spoznat će da sam ja Jahve kad im poginuli budu ležali među kumirima oko žrtvenika na svakome povišem brežuljku, nad svim vrhovima planinskim, pod svakim stablom zelenim, pod svakim hrastom granatim, gdje se god prinosio ugodan miris kumirima njihovim.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (33, 6, 14, 'Ruku ću podići na njih i svu ću im zemlju pretvoriti u pustoš, od pustinje do Rible, posvuda gdje borave! I spoznat će da sam ja Jahve!\"');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (33, 7, 1, 'Opet mi dođe riječ Jahvina i reče:');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (33, 7, 2, '\"Ti, sine čovječji, reci: Ovako govori Jahve Gospod zemlji Izraelovoj: \'Primiče se kraj: bliži se konac zemlji na sve četiri strane svijeta!');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (33, 7, 3, 'Sada je i tebi kraj: gnjev ću svoj na te izliti, sudit ću ti prema putovima tvojim i na te ću oboriti sve gadosti tvoje!');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (33, 7, 4, 'I moje te oči neće požaliti, neću ti se smilovati, nego ću te nagraditi prema putovima tvojim, tvoje će gadosti u tebi ostati. I znat ćete da sam ja Jahve.\'\"');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (33, 7, 5, 'Ovako govori Jahve: \"Jedna nesreća, evo, dolazi!');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (33, 7, 6, 'Kraj dolazi, dolazi ti kraj, evo, dolazi!');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (33, 7, 7, 'Kolo ti udesa dolazi, stanovniče zemlje! Dolazi tvoj čas, bliži se dan: strava je, a ne radost u gorama.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (33, 7, 8, 'Eto, uskoro ću na te izliti gnjev i iskalit ću na tebi srdžbu svoju! Sudit ću ti prema putovima tvojim i oborit ću na te sve gadosti tvoje.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (33, 7, 9, 'I moje te oči neće požaliti, neću ti se smilovati, nego ću ti platiti prema putovima tvojim i tvoje će gadosti u tebi ostati! I spoznat ćete da sam ja Jahve koji bije.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (33, 7, 10, 'Evo, evo dolazi, kolo ti udesa dolazi, prut već cvjeta i oholost pupa,');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (33, 7, 11, 'a nasilje se podiže kao žezlo bezbožnosti! I nitko neće ostati od njih, nitko od njihova mnoštva. Ništa od njihove buke, nema u njima vrijednosti.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (33, 7, 12, 'Ide vrijeme, bliži se dan! Tko kupuje, neka se ne raduje, a tko prodaje, neka ne tuguje, jer se gnjev izlijeva na sve bogatstvo njegovo.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (33, 7, 13, 'Jer tko proda, neće više dobiti što je prodao, i nitko neće bezakonjem ojačati život!');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (33, 7, 14, 'Trube trublje i sve je spremno, ali nitko ne kreće u boj, jer gnjev se moj izlijeva na sve bučno mnoštvo.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (33, 7, 15, 'Vani - mač, a unutra - kuga i glad! I tko je u polju, od mača će poginuti, a tko u gradu, glad će ga i kuga uništiti.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (33, 7, 16, 'Koji uteku, sklonit će se u gore kao dolinski golubovi, a ja ću ih sve istrijebiti, svakoga zbog bezakonja njegova,');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (33, 7, 17, 'i sve će ruke klonuti, a koljena će svima malaksati.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (33, 7, 18, 'U kostrijet će se odjenuti, trepet će ih obuzeti, sva će lica sramota pokriti, sve će im glave oćelavjeti!');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (33, 7, 19, 'Srebro svoje pobacat će na ulice, a zlato će smatrati izmetom: u dan srdžbe Jahvine ni srebro ni zlato neće ih izbaviti, duše im neće moći nasititi ni trbuha napuniti, jer se o to spotakoše na grijeh.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (33, 7, 20, 'Uzoholiše se zbog divnoga nakita svojega; od njega napraviše kumire - grozote i gadosti svoje: zato im ga pretvorih u izmet.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (33, 7, 21, 'Dat ću ga u ruke tuđincima da oplijene, razgrabe i oskvrnu.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (33, 7, 22, 'Odvratit ću od njih lice svoje: i neka se samo oskvrnjuje moja dragocjenost, neka u nju uđu provalnici i neka je oskvrnu!');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (33, 7, 23, 'Spremaj lance, jer je zemlja puna krvi i zločina koji zaslužuju smrt i grad prepun nasilja!');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (33, 7, 24, 'Zato ću dovesti najgore narode da baštine njihove domove. Slomit ću oholost nasilnika, i svetišta njihova bit će oskvrnjena.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (33, 7, 25, 'Dolazi tjeskoba! Tražit će mir, a mira biti neće!');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (33, 7, 26, 'Dolazit će nevolja za nevoljom, jedna zla vijest za drugom! I tražit će se viđenje u proroka; u svećenika neće više biti Zakona ni u starješina savjeta!');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (33, 7, 27, 'Kralj će protužiti, a kneza će spopasti užas i ruke će puku zadrhtati, jer ću ih nagraditi prema putovima njihovim i sudit ću im prema sudovima njihovim. I znat će da sam ja Jahve.\"');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (33, 8, 1, 'Godine šeste, šestoga mjeseca, petoga dana, dok sjeđah u svojoj kući, a preda mnom starješine judejske, spusti se na me ruka Jahvina.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (33, 8, 2, 'Pogledah, i gle: tu kao neki čovjek; od njegovih kao bokova naniže oganj, a od njegovih kao bokova naviše bljeskanje, nešto poput usijane kovine.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (33, 8, 3, 'Ispruži nešto nalik na ruku i uhvati me za kosu na glavi. Uto me duh podiže između zemlje i neba i ponese me u božanskome viđenju u Jeruzalem, na ulaz unutrašnjih vrata, što su okrenuta prema sjeveru gdje stoji kumir, ljubomora koja izaziva ljubomoru.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (33, 8, 4, 'I gle, ondje bijaše Slava Boga Izraelova, kao što je vidjeh u dolini.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (33, 8, 5, 'I reče mi: \"Sine čovječji, podigni oči prema sjeveru!\" I podigoh oči prema sjeveru. I gle, kumir, ljubomora, bijaše i na sjeveru, kraj vrata žrtvenika, na strani prema ulazu.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (33, 8, 6, 'I reče mi: \"Sine čovječji, vidiš li što oni ovdje čine? Velike su to gnusobe što ih dom Izraelov ovdje čini, samo da me udalji iz mojega Svetišta. A vidjet ćeš i gorih gnusoba!\"');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (33, 8, 7, 'I povede me do vrata predvorja. Pogledah, i gle: u zidu pukotina.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (33, 8, 8, 'I reče mi: \"Sine čovječji, probij taj zid!\" Probih zid, a ono - ulaz!');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (33, 8, 9, 'I reče mi: \"Uđi i pogledaj strahovite gadosti što se ovdje čine!\"');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (33, 8, 10, 'Uđoh i pogledah. I gle, svakojake slike gmazova i gnusnih životinja - sve kumiri doma Izraelova, našarani na zidu, svuda uokolo.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (33, 8, 11, 'A pred tim kumirima sedamdesetorica ljudi od starješina doma Izraelova, i među njima i Šafanov sin Jaazanija. I svakome od njih u ruci kadionica iz koje se podiže oblak kada miomirisnoga.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (33, 8, 12, 'I reče mi: \"Sine čovječji, vidiš li što u toj tami rade starješine doma Izraelova, svatko u svojoj oslikanoj komori? I još govore: Jahve nas ne vidi jer je Jahve napustio zemlju!\"');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (33, 8, 13, 'I reče mi još: \"A vidjet ćeš i gorih gnusoba što se ovdje čine!\"');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (33, 8, 14, 'I povede me do vrata Doma Jahvina što su okrenuta prema sjeveru. I gle, ondje sjeđahu žene i oplakivahu Tamuza.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (33, 8, 15, 'I reče mi: \"Vidiš li, sine čovječji? A vidjet ćeš i gorih gnusoba od ovih!\"');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (33, 8, 16, 'I povede me u unutrašnje predvorje Doma Jahvina. Ondje, na ulazu u Hekal Jahvin, između trijema i žrtvenika, bijaše oko dvadeset i pet ljudi, okrenutih leđima Hekalu Jahvinu, a licem prema istoku, i ondje se prema istoku klanjahu suncu.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (33, 8, 17, 'I reče mi: \"Vidiš li to, sine čovječji? Malo li je domu Judinu svih ovih gnusoba što ih ovdje čine, nego mi još zemlju pune i nasiljem, i ponovo me izazivaju i granama pred nosom mašu?');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (33, 8, 18, 'Zato ću i ja sada postupiti s njima jarosno i oči se moje više neće sažaliti i neću im se smilovati. I kad stanu iza glasa vikati na moje uši, neću ih uslišiti.\"');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (33, 9, 1, 'Tada zagrmje na moje uši i reče: \"Kazne grada! Priđite svaka sa svojim zatornim oružjem u ruci!\"');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (33, 9, 2, 'I gle, dođoše šestorica ljudi s gornjih vrata, što su okrenuta k sjeveru, svaki sa svojim zatornim oružjem u ruci. Među njima bijaše i jedan odjeven u lan, s pisarskim priborom za pojasom. Uđoše oni i stadoše uz tučani žrtvenik.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (33, 9, 3, 'A Slava Boga Izraelova vinu se s kerubina, nad kojima lebdijaše, prema pragu Doma. I pozva čovjeka odjevena u lan, koji imaše za pojasom pisarski pribor,');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (33, 9, 4, 'te mu reče: \"Prođi gradom Jeruzalemom i znakom \'tau\' obilježi čela sviju koji tuguju i plaču zbog gnusoba što se u njemu čine!\"');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (33, 9, 5, 'A drugima reče na moje uši: \"Pođite za njim gradom i ubijajte bez milosrđa. Oči vaše neka se ne sažale i nemajte smilovanja.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (33, 9, 6, 'Pobijte starce, mladiće, djevojke, djecu i žene; istrijebite ih sve do posljednjega. Ali na kome bude znak \'tau\', njega ne dirajte. Počnite od mojega Svetišta!\" I oni počeše od starješina koji stajahu pred Domom.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (33, 9, 7, 'I reče im: \"Oskvrnite Dom moj i napunite mu predvorje truplima! Krenite!\" I oni iziđoše te zaredaše ubijati gradom.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (33, 9, 8, 'Dok su oni klali, ja ostadoh, bacih se ničice i zavapih: \"Jao, Jahve Gospode! Zar ćeš zaista uništiti sve što preostade od Izraela da iskališ svoj gnjev nad Jeruzalemom?\"');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (33, 9, 9, 'Reče mi: \"Veoma je veliko bezakonje doma Izraelova i doma Judina; zemlja je puna krvi, a grad krcat zločina. Govore: \'Jahve je ostavio zemlju! Ne vidi Jahve!\'');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (33, 9, 10, 'I zato se moje oči neće sažaliti i neću im se smilovati: djela ću im njihova oboriti na glavu!\"');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (33, 9, 11, 'I gle, čovjek odjeven u lan, koji imaše za pojasom pisarski pribor, javi vijesti: \"Učinih kako si mi zapovjedio!\"');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (33, 10, 1, 'Pogledah, i gle: na svodu nad glavama kreubinÄa pojavi se nešto kao kamen safir, kao nekakvo prijestolje.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (33, 10, 2, 'I prozbori čovjeku odjevenom u lan: \"Uđi među točkove pod kerubinima, uzmi pune pregršti žeravice između kerubina i prospi je nad gradom!\" - I on na moje oči uđe među kerubine.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (33, 10, 3, 'A kerubini stajahu s desne strane Doma kad čovjek uđe među njih. I oblak ispuni sve unutrašnje predvorje,');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (33, 10, 4, 'a Slava Jahvina vinu se s kerubinÄa prema pragu Doma. Dom se ispuni oblakom, a predvorje napuni svjetlost Slave Jahvine.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (33, 10, 5, 'Huka kerubinskih krila razliježe se do vanjskoga predvorja, kao kad zagrmi glas Svevišnjega.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (33, 10, 6, 'A kad on zapovjedi čovjeku odjevenom u lan: \"Uzmi ognja između točkova što su pod kerubinima\", čovjek uđe i stade kraj točkova.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (33, 10, 7, 'Jedan kerubin pruži ruku prema ognju što bijaše među kerubinima, uze ga i stavi u ruke čovjeku odjevenom u lan. On ga primi i iziđe.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (33, 10, 8, 'A ispod kerubinskih krila ukaza se nešto kao ruka čovječja.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (33, 10, 9, 'Pogledah, i gle: uz kerubine četiri točka, po jedan uza svakoga. A točkovi bijahu nalik na kamen krizolit;');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (33, 10, 10, 'sva četiri istog oblika i kao da je jedan točak u drugome.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (33, 10, 11, 'U kretanju mogahu ići u sva četiri smjera, sve bez zakretanja. Kamo bi se glava usmjerila, onamo bi krenuli, a da se, krećući se, nisu morali okretati.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (33, 10, 12, 'Cijelo tijelo u kerubinÄa - leđa, ruke, krila i sva četiri točka njihova - sve im bijaše posvud naokolo puno očiju.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (33, 10, 13, 'A točkovi, koliko sam čuo, zvahu se \"Kovitlac\".');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (33, 10, 14, 'Svaki imaše po četiri lica: lice prvoga kerubinsko, lice drugoga čovječje, a u trećega lice lavlje, u četvrtoga orlovsko.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (33, 10, 15, 'Tada se kerubini podigoše u visine. Bijahu to ista bića što ih vidjeh na rijeci Kebaru.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (33, 10, 16, 'Kad bi kerubini krenuli, krenuli bi i točkovi uz njih, kad bi kerubini krilima mahnuli da se od zemlje podignu, točkovi se ne bi od njih odmicali.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (33, 10, 17, 'Kad bi se zaustavili, i točkovi bi stali; a kad bi se sa zemlje podigli, i točkovi se podizahu, jer duh bića bijaše u njima.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (33, 10, 18, 'Uto se Slava Jahvina vinu s praga Doma i stade nad kerubinima.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (33, 10, 19, 'Tada kerubini raširiše krila i podigoše se sa zemlje pred mojim očima. A kad oni krenuše, i točkovi za njima krenuše. I zaustaviše se nad istočnim vratima Doma Jahvina, a Slava Boga Izraelova bijaše nad njima.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (33, 10, 20, 'Bijahu to ista bića što ih vidjeh pred Bogom Izraelovim na rijeci Kebaru. I tako spoznah da ono bijahu kerubini.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (33, 10, 21, 'U svakoga po četiri lica i po četiri krila, a pod krilima nešto kao ruka čovječja.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (33, 10, 22, 'Lica im ista kao ona što ih vidjeh na rijeci Kebaru. I svako se naprijed kretaše.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (33, 11, 1, 'Tada se duh podiže i ponese me do istočnih vrata Doma Jahvina, što su okrenuta k istoku. I gle: na ulazu vrata dvadeset i pet ljudi, među kojima vidjeh i Jaazaniju, sina Azurova, i Pelatju, sina Benajina, knezove narodne.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (33, 11, 2, 'I reče mi: \"Sine čovječji, evo ljudi koji smišljaju opačine i koji u ovom gradu daju zle savjete:');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (33, 11, 3, '\'Nije li čas da gradimo domove? Ovaj je grad kotao, a mi smo meso.\'');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (33, 11, 4, 'Zato prorokuj protiv njih, prorokuj, sine čovječji!\"');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (33, 11, 5, 'I duh Jahvin siđe nada me i kaza mi: \"Reci: Ovako veli Jahve Gospod: \'Ne govoriš li tako, dome Izraelov? Ali ja poznajem misli vašega srca!');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (33, 11, 6, 'Množite ubojstva u ovome gradu i njegove ulice punite truplima.\'');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (33, 11, 7, 'Zato ovako govori Jahve Gospod: \'Oni koje vi probodoste i razbacaste po gradu - oni su meso, a grad je kotao. Zato ću vas ja izvesti sada iz njega.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (33, 11, 8, 'Od mača strahujete, i mač ću na vas dovesti - riječ je Jahve Gospoda!');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (33, 11, 9, 'Izvest ću vas iz grada i predati vas u ruke tuđincima, i sud ću svoj izvršiti nad vama:');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (33, 11, 10, 'od mača ćete pasti! Na međi Izraelovoj sudit ću vam, i tada ćete znati da sam ja Jahve!');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (33, 11, 11, 'A ovaj grad više vam neće biti kotao i vi nećete biti meso njegovo. Na međi Izraelovoj sudit ću vam,');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (33, 11, 12, 'i tada ćete znati da sam ja Jahve po čijim uredbama ne živjeste i čijih zakona ne izvršavaste, nego živjeste po zakonima okolnih naroda!\'\"');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (33, 11, 13, 'Dok ja tako prorokovah, umrije Pelatja, sin Benajin. I ja padoh ničice te zavapih iz svega glasa: \"Jao, Jahve Gospode, zar ćeš doista uništiti sav Ostatak doma Izraelova?\"');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (33, 11, 14, 'I dođe mi riječ Jahvina:');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (33, 11, 15, '\"Sine čovječji, tvojoj braći, i tvojim rođacima, i svem domu Izraelovu Jeruzalemci govore: \'Daleko ste od Jahve! Nama je ova zemlja dana u posjed!\'');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (33, 11, 16, 'Zato im reci: Ovako govori Jahve Gospod: \'Ako ih i odagnah među daleke narode, ako ih i rasprših po zemljama, ja ću im sam uskoro biti Svetište u zemljama u kojima se nalaze.\'');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (33, 11, 17, 'Stoga im reci: Ovako govori Jahve Gospod: \'Sabrat ću vas iz narodÄa, vratit ću vas iz zemalja u kojima ste bili raspršeni i dat ću vam opet zemlju Izraelovu!');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (33, 11, 18, 'I kad se u nju vrate, istrijebit će iz nje sve grozote i gadosti.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (33, 11, 19, 'I ja ću im dati novo srce i nov ću duh udahnuti u njih: iščupat ću iz njih njihovo kameno srce i stavit ću u njih srce od mesa,');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (33, 11, 20, 'da hode po mojim naredbama i da čuvaju i vrše sve moje zakone. I bit će oni moj narod, a ja Bog njihov!');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (33, 11, 21, 'A onima kojima srce hodi za grozotama i gadostima oborit ću na glavu njihov put\' - riječ je Jahve Gospoda.\"');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (33, 11, 22, 'Kerubini podigoše krila i točkovi se digoše za njima, a Slava Boga Izraelova lebdijaše nad njima.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (33, 11, 23, 'Slava se Jahvina vinu iz grada i zaustavi se na gori, istočno od grada.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (33, 11, 24, 'A mene duh podiže i ponese duhom Božjim k izgnanicima u zemlju kaldejsku. I iščeznu viđenje koje gledah.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (33, 11, 25, 'I pripovjedih izgnanicima sve što mi Jahve bijaše objavio.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (33, 12, 1, 'Opet mi dođe riječ Jahvina:');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (33, 12, 2, '\"Sine čovječji! Ti boraviš u rodu odmetničkom koji ima oči, a ne vidi, uši ima, a ne čuje, jer su rod odmetnički.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (33, 12, 3, 'Zato, sine čovječji, spremi izgnanički zavežljaj i njima na oči obdan se seli: seli se iz svojega mjesta u drugo, ne bi li uvidjeli da su rod odmetnički.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (33, 12, 4, 'Obdan, njima na oči, iznesi zavežljaj, zavežljaj izgnanički, a iziđi obnoć na njihove oči kao što se odlazi u izgnanstvo.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (33, 12, 5, 'Njima na oči prokopaj zid i kroza nj izađi.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (33, 12, 6, 'I njima na oči vrgni zavežljaj na ramena i po mrkloj noći iziđi. Pokrij lice da ne vidiš zemlju, jer te postavih kao znamenje domu Izraelovu!\"');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (33, 12, 7, 'Učinih kako mi bijaše zapovjeđeno: obdan iznesoh zavežljaj, zavežljaj izgnanički, a obnoć prokopah zid rukama i njima na oči po mrkloj noći vrgoh zavežljaj na ramena.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (33, 12, 8, 'Ujutro mi dođe riječ Jahvina:');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (33, 12, 9, '\"Sine čovječji, zapita li te dom Izraelov, dom odmetnički: \'Što to radiš?\'');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (33, 12, 10, 'ti mu reci: \'Ovako govori Jahve Gospod! Ovo je proroštvo knezu jeruzalemskom i svemu domu Izraelovu koji je u Jeruzalemu.\'');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (33, 12, 11, 'Reci: \'Ja sam vam znamenje! Kako ja uradih, tako će biti njima: svi ćete se morati seliti u izgnanstvo!');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (33, 12, 12, 'Knez njihov morat će vrći zavežljaj na ramena i po mrkloj noći izaći. Prokopat će zid da izađe kroza nj i lice će pokriti rukama da očima ne vidi zemlje.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (33, 12, 13, 'Ja ću mu razapeti mrežu, i uhvatit će se u moju zamku, i odvest ću ga u Babilon, u zemlju kaldejsku. Ali je on neće ugledati i ondje će život ostaviti.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (33, 12, 14, 'A sve one oko njega, pomagače i čete, raspršit ću u sve vjetrove i svoj mač ću trgnuti na njih.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (33, 12, 15, 'A kad ih raspršim među narode i rasijem po zemljama, znat će da sam ja Jahve.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (33, 12, 16, 'Ipak, ostavit ću nekolicinu koji će umaći maču, gladi i kugi, da među narodima kamo prispiju pripovijedaju svoje gadosti; neka se zna da sam ja Jahve.\'\"');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (33, 12, 17, 'I dođe mi riječ Jahvina:');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (33, 12, 18, '\"Sine čovječji, jedi kruha zabrinuto i pij vode sa zebnjom i sa strepnjom!');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (33, 12, 19, 'I reci puku zemlje: \'Ovako govori Jahve Gospod Jeruzalemcima u zemlji Izraelovoj: Zabrinuto će jesti kruha i sa strepnjom piti vode, jer će im zemlja opustjeti i ostat će bez igdje ičega s bezakonja žitelja svojih.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (33, 12, 20, 'I svi gradovi, sada napučeni, bit će poharani, a sva zemlja opustošena. I znat će da sam ja Jahve!\'\"');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (33, 12, 21, 'I dođe mi riječ Jahvina:');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (33, 12, 22, '\"Sine čovječji, kakve su vam to priče o zemlji Izraelovoj? Govori se: \'Gle, prolaze dani, a od proroštva ništa!\'');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (33, 12, 23, 'Zato im reci: Ovako govori Jahve Gospod: \'Dokončat ću te priče i neće se više ponavljati u Izraelu.\' Reci im: \'Bliže se već dani i sva će se proroštva moja ispuniti!');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (33, 12, 24, 'Jer neće više biti u domu Izraelovu varavih viđenja, ni lažnih proroštava kojima ljude bijahu zavodili.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (33, 12, 25, 'Jer što ja, Jahve Gospod, govorim, to će i biti, i riječ se neće odgoditi! Da! Još za vaših dana, rode odmetnički, riječ ću izgovoriti i izvršiti.\' Tako govori Jahve Gospod!\"');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (33, 12, 26, 'I dođe mi riječ Jahvina:');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (33, 12, 27, '\"Sine čovječji! Evo što se govori u domu Izraelovu: \'Viđenje što ga ovaj ugleda za dane je daleke! Prorokuje za daleka vremena!\'');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (33, 12, 28, 'Zato im reci: Ovako govori Jahve Gospod: \'Nijedna riječ moja neće se više odgoditi! Što rekoh, rečeno je, i sve će se ispuniti!\' - riječ je Jahve Gospoda.\"');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (33, 13, 1, 'I opet mi dođe riječ Jahvina:');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (33, 13, 2, '\"Sine čovječji! Prorokuj protiv onih koji se grade prorocima u Izraelu!');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (33, 13, 3, 'Reci tim prorocima koji prorokuju po svojoj glavi: \'Čujte riječ Jahvinu! Ovako govori Jahve Gospod: Jao prorocima bezumnim koji duh svoj slijede a ništa ne vide!');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (33, 13, 4, 'Ti su tvoji proroci, Izraele, kao lisice usred ruševina.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (33, 13, 5, 'Vi se ne popeste na proboje i ne zidaste zida oko doma Izraelova da se održi u boju u dan Jahvin.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (33, 13, 6, 'Viđenja su njihova isprazna, i lažna su njihova proricanja. Govore \'Riječ Jahvina!\' - a Jahve ih nije poslao. I još očekuju da će im se riječi ispuniti.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (33, 13, 7, 'Zar ne vidite da su vam viđenja isprazna i da su vam lažna proricanja kad govorite \'Riječ Jahvina!\' - a ja nisam govorio.\'');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (33, 13, 8, 'Stoga ovako govori Jahve Gospod: \'Zato što govorite isprazno i laž vidite, evo me protiv vas\' - riječ je Jahve Gospoda!');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (33, 13, 9, 'Evo, ruka moja bit će protiv proroka koji vide isprazno i laž proriču: neće više biti u zboru mojega naroda, neće biti upisani u knjigu doma Izraelova, nikad više neće stupiti na tlo Izraelovo! I znat će da sam ja Jahve Gospod!');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (33, 13, 10, 'Jer narod moj obmanjuju govoreći \'Mir\' kad mira nema. I dok jedni hoće da se zid utvrdi, oni hoće da se samo ožbuka.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (33, 13, 11, 'Reci onima koji hoće da se samo ožbuka: \'Past će!\' Udarit će silan pljusak, oborit ću na nj grÓad kao kamenje, bjesnjet će olujni vihori.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (33, 13, 12, 'Evo, zid će pasti! Neće li vas tada pitati: \'Gdje vam je sada žbuka kojom ste ga ožbukali?\'');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (33, 13, 13, 'Zato ovako govori Jahve Gospod: \'U svojoj jarosti razbjesnit ću olujne vihore, u srdžbi ću svojoj udariti silnim pljuskom da ga zatrem, u gnjevu ću na nj oboriti grÓad kao kamenje.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (33, 13, 14, 'Obalit ću zid što ga vi žbukom ožbukaste, na zemlju ću ga oboriti da mu se razgole temelji. Past će zid, i vi ćete pod njim izginuti! Tada ćete znati da sam ja Jahve!');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (33, 13, 15, 'Tako ću iskaliti gnjev nad zidom i nad onima koji ga žbukom ožbukaše. A vama ću reći: Nema više zida! Nema onih koji ga žbukom ožbukaše.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (33, 13, 16, 'Nema izraelskih proroka koji Jeruzalemu proricahu i koji mu mir vidješe kad mira ne bijaše.\' Tako govori Jahve Gospod.\"');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (33, 13, 17, '\"Sine čovječji, okreni lice protiv kćeri svojega naroda koje prorokuju po svojoj glavi! Prorokuj protiv njih:');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (33, 13, 18, 'Ovako govori Jahve Gospod: \'Jao onima koje vezu poveze za svačije ruke i koje prave prijevjese za glave svake veličine da ulove duše! Mislite li uloviti sve duše mojega naroda a svoje duše sačuvati žive?');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (33, 13, 19, 'Obeščašćujete me pred mojim narodom za šaku ječma, za zalogaj kruha, ubijajući duše koje ne bi trebale da umru, a spasavajući one koje ne bi trebale da žive; i obmanjujete tako narod moj koji rado sluša vaše laži.\'');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (33, 13, 20, 'Zato ovako govori Jahve Gospod: \'Evo me protiv vaših poveza kojima lovite duše kao ptice! Rastrgat ću sve to na vašim rukama i oslobodit ću duše koje time hvatate kao ptice!');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (33, 13, 21, 'Poderat ću vaše prijevjese i oslobodit ću svoj narod da ne bude više plijen vaših ruku. I znat ćete da sam ja Jahve!');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (33, 13, 22, 'Jer vi lažju ražalostiste srce pravednika, koje ja ražalostiti ne htjedoh, a okrijepiste ruke bezbožnika da se ne obrati od zla puta bezbožničkog pa da život spasi.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (33, 13, 23, 'Zato nećete više vidjeti isprazno niti ćete laž proricati: ja ću osloboditi narod svoj iz vaših ruku. I znat ćete da sam ja Jahve!\'\"');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (33, 14, 1, 'Uto k meni dođoše neki od starješina Izraelovih i sjedoše preda me.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (33, 14, 2, 'I dođe mi riječ Jahvina:');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (33, 14, 3, '\"Sine čovječji! Ti ljudi nose kumire u srcu i upiru oči u ono što ih na grijeh potiče. Pa zar da trpim da u mene traže savjeta?');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (33, 14, 4, 'Zato im reci: Ovako govori Jahve Gospod: \'Tko god iz doma Izraelova nosi u srcu kumire i upire oči u ono što ga na grijeh potiče, a dolazi k proroku, ja, Jahve, odgovorit ću mu prema mnoštvu njegovih kumira,');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (33, 14, 5, 'da uhvatim za srce dom Izraelov koji se zbog idola svojih odmetnu od mene.\'');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (33, 14, 6, 'Zato reci domu Izraelovu: Ovako govori Jahve Gospod: \'Obratite se, odvratite se od kumira svojih! Odvratite lice od gnusoba svojih!');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (33, 14, 7, 'Jer tko se god iz doma Izraelova i od došljaka koji se nastaniše u Izraelu odmetne od mene i u srcu nosi kumire i upire oči u ono što ga potiče na grijeh, pa unatoč tome dođe k proroku da preko njega u mene traži savjeta, njemu ću ja, Jahve, sam odgovoriti;');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (33, 14, 8, 'okrenut ću se protiv njega i učinit ću od njega poslovičan primjer: iskorijenit ću ga iz svojega naroda! I znat ćete da sam ja Jahve.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (33, 14, 9, 'Ako li se prorok dadne zavesti i progovori, bilo bi to kao da sam ja, Jahve, zaveo toga proroka: ruku ću podići na njega i iskorijenit ću ga iz svojega naroda izraelskoga.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (33, 14, 10, 'Obojica će podjednako snositi grijeh svoj: grijeh prorokov jednak je grijehu onoga koji je u njega tražio savjeta.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (33, 14, 11, 'I tako se dom Izraelov više neće odmetati od mene i neće se više kaljati svojim opačinama: on će biti narod moj, a ja ću biti njegov Bog\' - riječ je Jahve Gospoda.\"');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (33, 14, 12, 'I dođe mi riječ Jahvina:');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (33, 14, 13, '\"Sine čovječji, zgriješi li koja zemlja protiv mene nevjerom i ja podignem ruku na nju te joj uništim i posljednju pričuvu kruha i pustim na nju glad da zatrem u njoj sve ljude i stoku;');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (33, 14, 14, 'preostanu li u njoj samo tri čovjeka - Noa, Daniel i Job - ti će se svojom pravednošću spasiti - riječ je Jahve Gospoda.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (33, 14, 15, 'Također, ako na tu zemlju pustim divlje zvijeri da joj djecu unište a nju pretvore u pustinju, kojom se zbog zvijeri više nitko neće usuditi proći;');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (33, 14, 16, 'preostanu li u njoj samo ta tri čovjeka, života mi moga - riječ je Jahve Gospoda - oni neće spasiti ni sinova ni kćeri nego samo sebe, a zemlja će njihova postati prava pustinja.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (33, 14, 17, 'Ili, ako ja trgnem mač na tu zemlju govoreći: \'Maču, prođi ovom zemljom!\' da istrijebim u njoj sve ljude i stoku,');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (33, 14, 18, 'a u njoj se nađu samo ona tri čovjeka, života mi moga - riječ je Jahve Gospoda - oni neće spasiti ni sinova ni kćeri nego samo sebe.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (33, 14, 19, 'Ili, ako ja pošaljem na tu zemlju kugu te izlijem na nju gnjev i pokolj da zatrem u njoj sve ljude i stoku,');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (33, 14, 20, 'a u njoj preostanu samo ona tri čovjeka, Noa, Daniel i Job, života mi moga - riječ je Jahve Gospoda - oni neće spasiti ni sinova ni kćeri nego samo sebe svojom pravednošću.\"');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (33, 14, 21, 'Ovako govori Jahve Gospod: \"Ipak, ako na Jeruzalem pustim sva svoja četiri ljuta biča - mač, glad, divlju zvjerad i kugu - da zatrem u njemu sve ljude i stoku,');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (33, 14, 22, 'u njemu će ipak preživjeti Ostatak koji će spasiti sinove i kćeri. I evo, oni će doći k vama da vidite njihovo vladanje i njihova djela i da se utješite, jer ćete upoznati: što god poduzeh protiv Jeruzalema, ne učinih bez razloga.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (33, 14, 23, 'Da, kad vidite njihovo vladanje i njihova djela, utješit ćete se, jer ćete upoznati da ne učinih bez razloga što god poduzeh protiv Jeruzalema - riječ je Jahve Gospoda.\"');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (33, 15, 1, 'I dođe mi riječ Jahvina:');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (33, 15, 2, '\"Sine čovječji! U čemu je trs loze bolji od drugih šumskih drveta?');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (33, 15, 3, 'Služi li da se od njega štogod načini? Djelja li se od njega klin da se o njega što objesi?');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (33, 15, 4, 'Gle, baca se u oganj da izgori: kad mu oganj sažeže oba kraja i sredinu spali, može li još čemu poslužiti?');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (33, 15, 5, 'Eto, ni onda kad bijaše čitav ništa se od njega ne mogaše načiniti. Pa kako će, dakle, čemu poslužiti kad ga plamen sažga?\"');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (33, 15, 6, 'Zato ovako govori Jahve Gospod: \"Kao što sam trs loze, među drugim drvetima, bacio u oganj da izgori, tako ću postupati i s Jeruzalemcima!');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (33, 15, 7, 'Upravit ću lice svoje na njih, i kada se iz jednog ognja izbave, drugi će ih proždrijeti. I spoznat ćete da sam ja Jahve kad lice svoje upravim na njih');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (33, 15, 8, 'i svu im zemlju opustošim jer mi bijahu nevjerni! - riječ je Jahve Gospoda.\"');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (33, 16, 1, 'I dođe mi riječ Jahvina:');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (33, 16, 2, 'Sine čovječji! Pokaži Jeruzalemu sve gadosti njegove!');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (33, 16, 3, 'Reci: Ovako Jahve Gospod govori Jeruzalemu, nevjernici: \'Podrijetlom i rodom iz zemlje si kanaanske, otac ti Amorejac, mati Hetitkinja.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (33, 16, 4, 'Kad si svijet ugledala, na dan rođenja tvojega pupka ti ne odrezaše niti te vodom opraše da te očiste; solju te ne osoliše niti te povojima poviše.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (33, 16, 5, 'Nijedno se oko na te ne sažali niti se tko smilova da ti to učini, nego te na dan rođenja tvojega gadnu baciše napolje.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (33, 16, 6, 'A ja prođoh kraj tebe i vidjeh gdje se koprcaš u krvi. I rekoh ti dok si još u krvi bila: \'Živi!\' U krvi ti tvojoj rekoh: \'Živi!');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (33, 16, 7, 'Razrasti se kao izdanak u polju!\' I umnožih te, i ti se razraste i velika postade, i dođe vrijeme da sazreš. Dojke ti se raspupale, kosa ti narasla, ali si još gola i naga bila.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (33, 16, 8, 'Prođoh kraj tebe i u te se zagledah: i gle, dob tvoja - dob je ljubavi! Raširih na te skute svoje i pokrih ti golotinju. Prisegoh ti i sklopih Savez s tobom - riječ je Jahve Gospoda - i ti moja postade.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (33, 16, 9, 'Okupah te u vodi, krv saprah s tebe i uljem te pomazah.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (33, 16, 10, 'Obukoh te u šarene haljine, na noge ti obuh sandale od fine kože; opasah te bezom i pokrih te prijevjesom svilenim.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (33, 16, 11, 'Uresih te nakitima: na ruke ti stavih narukvice, oko vrata ogrlice;');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (33, 16, 12, 'prstenom ti nos uresih, uši naušnicama, a glavu ti ovjenčah vijencem najljepšim.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (33, 16, 13, 'I tako se sva u srebru i zlatu pojavi, u haljini od beza, svilom izvezenoj. Za hranu ti dadoh najfinije brašno, med i ulje. Bila si tako lijepa, prelijepa, za kraljicu podobna!');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (33, 16, 14, 'Glas o ljepoti tvojoj puče među narodima, jer ti bijaše tako lijepa u nakitu mojem što ga djenuh na tebe - riječ je Jahve Gospoda.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (33, 16, 15, 'Ali te ljepota tvoja zanijela, zbog glasa se svojega bludu podade: blud si svoj nudila obilno svakom prolazniku, njegova si bila.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (33, 16, 16, 'Od haljina si svojih šarene uzvišice pravila i na njima se bludu odavala...');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (33, 16, 17, 'I nakite uze zlatne i srebrne, kojima te ja bijah uresio, i od njih načini sebi muške likove da s njima bludničiš.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (33, 16, 18, 'Uze šarene, vezene haljine da njima odjeneš kumire svoje i njima si prinosila moje ulje i moj kad.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (33, 16, 19, 'A hranu što ti je dadoh - najfinije brašno, med i ulje kojima te hranjah - pred njih si stavljala na ugodan miris. Da, tako to bijaše - riječ je Jahve Gospoda!');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (33, 16, 20, 'Sinove si svoje i kćeri uzimala koje meni porodi i njima ih za hranu klala. Malo ti bijaše tvoga bludničenja,');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (33, 16, 21, 'pa si čak i djecu moju davala da se njima na čast kroz oganj provedu!');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (33, 16, 22, 'U svim tim gnusobama i bludu svojemu ne spomenu se dana mladosti svoje, kad si se gola i naga u krvi svojoj koprcala.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (33, 16, 23, 'I povrh svega zla - Jao! Jao! riječ je Jahve Gospoda -');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (33, 16, 24, 'sagradi sebi humke, posvud diže uzvišice.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (33, 16, 25, 'Na svim raskršćima podiže uzvišice i na njima blatiš svoju ljepotu, nudiš se svakom prolazniku množeć\' svoje bludničenje.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (33, 16, 26, 'Bludu se podade sa sinovima Egipta, snažna tijela, bludničenje si množila da me razjariš.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (33, 16, 27, 'Zato, evo, ruku digoh na te, smanjivši ti obrok hrane i predavši te bijesu tvojih mrziteljica, kćeri filistejskih, koje se stide sramotnoga tvojeg vladanja.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (33, 16, 28, 'Tjerala si blud i sa sinovima Asira i nisi se zasitila; i s njima si blud tjerala, ali se nisi zasitila.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (33, 16, 29, 'Umnožila si bludničenje svoje i sa zemljom kanaanskom, sa zemljom kaldejskom, ali se ni onda nisi zasitila.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (33, 16, 30, 'O, kako li slabo bijaše tvoje srce - riječ je Jahve Gospoda - kad činjaše ono što rade bludnice najrazvratnije.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (33, 16, 31, 'Na svim raskrsnicama humak sebi podiže, posvuda sagradi sebi uzvišice. Ali ne kao druge bludnice, jer si prezirala plaću bludničku,');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (33, 16, 32, 'nego kao preljubnica: mjesto muža, strance si primala.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (33, 16, 33, 'Svima se bludnicama plaća, a ti si sama ljubavnike svoje plaćala i još si ih u bludnosti svojoj darovima mamila da ti dođu odasvuda.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (33, 16, 34, 'Ti bijaše bludnica kakvih nema: nitko za tobom nije trčao da s tobom blud provodi, nego si sama davala plaću bludničku, a nisu je tebi plaćali. Toliko si bila opaka!');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (33, 16, 35, 'Stoga, razvratnice, čuj riječ Jahvinu:');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (33, 16, 36, 'Ovako govori Jahve Gospod: Jer si svlačila svoju sramotu i u bludu golotinju otkrivala pred svima svojim ljubavnicima i gnusnim kumirima, i zbog krvi svojih sinova što si ih njima prinosila,');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (33, 16, 37, 'evo, skupit ću sve tvoje ljubavnike s kojima si se naslađivala, sve koje si voljela i koje si mrzila, skupit ću ih odasvud protiv tebe i razotkriti im tvoju golotinju, neka vide sramotu tvoju.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (33, 16, 38, 'Sudit ću ti kao što se sudi preljubnicama i krvnicama i predati te bijesu njihovu.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (33, 16, 39, 'Predat ću te u ruke njihove da poruše tvoje humke, da razore uzvišice tvoje. I zderat će sa tebe haljine, oteti nakit i ostaviti te golu, sasvim nagu.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (33, 16, 40, 'A zatim će na te dovesti svjetinu da te kamenuje i da te sasiječe mačevima.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (33, 16, 41, 'Kuće će ti ognjem spaliti i naočigled svim ženama izvršiti pravdu nad tobom. Tako ću dokrajčiti tvoje bludničenje, nećeš više davati plaću bludničku.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (33, 16, 42, 'Iskalit ću gnjev svoj nad tobom i povući ću svoju ljubomoru od tebe. Smirit ću se i neću se više gnjeviti.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (33, 16, 43, 'I jer se ne spomenu svoje mladosti, već me svim tim izazivaše, oborit ću ti na glavu sve postupke tvoje - riječ je Jahve Gospoda: nećeš više dodavati bestidnosti na sve svoje gadosti!');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (33, 16, 44, 'I sastavljač poslovica narugat će ti se poslovicom: \'Kakva mati, takva kći.\'');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (33, 16, 45, 'Prava si kći svoje matere, koja ostavi muža i djecu; sestra si sestara svojih, koje ostaviše muževe svoje i djecu: Hetitkinja vam mati bijaše, otac Amorejac:');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (33, 16, 46, 'Samarija, sestra tvoja starija, sa svojim kćerima tebi slijeva stoji; Sodoma, tvoja mlađa sestra, sa kćerima svojim zdesna ti stoji.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (33, 16, 47, 'A ti ne samo da si njihovim putem hodila i činila njihove gadosti - to bi tebi bilo premalo - već bijaše od njih pokvarenija na svojim putovima.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (33, 16, 48, 'Života mi mojega - riječ je Jahve Gospoda - tvoja sestra Sodoma sa svojim kćerima ne učini što si ti počinila zajedno sa kćerima svojim.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (33, 16, 49, 'Evo opačina sestre tvoje Sodome: gizdavo, u izobilju kruha i bezbrižno življaše ona i kćeri njezine, a sirotinju i bijednike ne pomagahu.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (33, 16, 50, 'Uzoholiše se i gadosti pred očima mojim činjahu, i zato ih zatrijeh, kao što vidje!');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (33, 16, 51, 'A sestra ti Samarija ne počini ni polovicu grijeha tvojih, i tako ti počini više gadosti nego one obje zajedno, opravdavši sestre svoje svojim gadostima.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (33, 16, 52, 'Zato snosi sad sramotu grijeha kojima si sestre svoje opravdala; zbog grijeha kojima se više od njih nagrdi, one izađoše pravednije. Postidi se, dakle, i snosi sramotu svoju kojom sestre opravda.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (33, 16, 53, 'A ja ću okrenuti udes njihov, udes Sodome i kćeri njenih, udes Samarije i kćeri njenih; i tvoj ću udes okrenuti među njima,');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (33, 16, 54, 'da snosiš sramotu svoju i da se postidiš za sve što si počinila, njima na utjehu.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (33, 16, 55, 'Sestra tvoja Sodoma i kćeri njene vratit će se u stanje prijašnje; sestra tvoja Samarija i kćeri njene vratit će se u stanje prijašnje; ali i ti i kćeri tvoje vratit ćete se u stanje prijašnje.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (33, 16, 56, 'Zar se nije spominjala sestra tvoja Sodoma dok ti bijaše ponosita,');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (33, 16, 57, 'prije negoli se golotinja tvoja otkrila? Budi sada za ruglo kćerima edomskim, susjedama njenim i kćerima filistejskim koje ti se sa svih strana rugaju.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (33, 16, 58, 'Snosi, dakle, svoju sramotu i svoje gadosti - riječ je Jahve Gospoda!\'');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (33, 16, 59, 'Jer ovako govori Jahve Gospod: \'Postupit ću s tobom onako kako ti učini kad pogazi zakletvu i raskinu Savez.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (33, 16, 60, 'Ali ću se ja ipak spomenuti svojega Saveza s tobom što ga sklopih u dane mladosti tvoje i uspostavit ću s tobom Savez vječan.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (33, 16, 61, 'I ti ćeš se opomenuti svojih putova i postidjet ćeš se kad primiš svoje sestre, stariju i mlađu, koje ću ti dati za kćeri, ali ne snagom tvog Saveza.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (33, 16, 62, 'Sklopit ću s tobom savez svoj i znat ćeš da sam ja Jahve,');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (33, 16, 63, 'da se opomeneš i da se postidiš i da od sramote više ne otvoriš usta kad ti oprostim sve što učini! To je riječ Jahve Gospoda.\'\"');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (33, 17, 1, 'Dođe mi riječ Jahvina:');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (33, 17, 2, '\"Sine čovječji, smisli zagonetku i iznesi prispodobu domu Izraelovu! Reci:');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (33, 17, 3, '\'Ovako govori Jahve Gospod: Velik orao, velikih krila, duga perja, gusta, šarena paperja, doletje na Libanon i zgrabi cedrov vrh;');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (33, 17, 4, 'odlomi mu najvišu grančicu, odnese je u zemlju trgovaca i spusti je u grad prodavača.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (33, 17, 5, 'Onda uze izdanak iz zemlje, u plodnu ga njivu posadi, kraj obilnih voda stavi, kao vrbu usadi.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (33, 17, 6, 'Izdanak proklija, bujan izbi čokot, onizak izraste, mladice mu k orlu segnuše, a pod njim mu žilje bješe; u bujan se razvi čokot, potjera izdanke, mladice razgrana.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (33, 17, 7, 'Bijaše i drugi orao, velik i velikih krila, gusta perja. I gle, čokot k njemu žilje pruži, k njemu upravi grančice svoje da ga natapa bolje od tla u koje bi zasađen.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (33, 17, 8, 'Na plodnoj njivi, kraj obilnih voda, bješe zasađen: mogao je tjerat\' mladice, uroditi rodom, k\'o veličanstveni trs izrasti.\'');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (33, 17, 9, 'Reci: \'Ovako govori Jahve Gospod: Hoće l\' uspijevati? Neće l\' mu orao sve žilje izguliti? Neće l\' mu sve plodove potrgati? Neće l\' mu sve mladice, čim izbiju, sasušiti? Da, i bez snažne mišice, i bez mnoštva naroda, iščupat će ga iz korijena!');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (33, 17, 10, 'Gle, zasađen je! Hoće l\' uspijevati? Čim ga takne istočnjak, neće l\' sav usahnuti? Da, na lijehama iz kojih niče uvenut će.\'\"');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (33, 17, 11, 'Dođe mi riječ Jahvina:');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (33, 17, 12, '\"Reci domu odmetničkome: \'Zar ne znate što ovo znači?\' Reci im: \'Eto, dođe kralj babilonski u Jeruzalem, zarobi mu kralja i sve knezove, odvede ih k sebi u Babilon.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (33, 17, 13, 'Odvede i izdanak iz kraljevskoga koljena, sklopi s njima savez i zakletvom se obveza, pošto odvede sve mogućnike iz zemlje,');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (33, 17, 14, 'da će kraljevstvo ostati neznatno i da se neće dizati, nego će čuvati i držati savez s njime.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (33, 17, 15, 'Ali se on od njega odmetnu; poslanike uputi u Egipat, tražeći od njega konje i jaku vojsku. Hoće li uspjeti? Može li umaći onaj tko tako radi? Raskinu savez, pa da umakne?');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (33, 17, 16, 'Života mi moga, riječ je Jahve Gospoda: jer prezre zakletvu kralja koji ga na prijestolje posadi i razvrže savez s njime, u njegovoj će zemlji umrijeti, usred Babilona!');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (33, 17, 17, 'Svojom silnom vojskom i mnoštvom naroda faraon mu neće pomoći u boju kad onaj digne nasipe i sagradi kule opsadne da mu zatre mnogo ljudstvo.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (33, 17, 18, 'Prezreo je zakletvu, razvrgao savez. Da, iako ruku bijaše dao, sve to učini! Ne, neće umaći!\'');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (33, 17, 19, 'Stoga ovako govori Jahve Gospod: \'Života mi moga, zakletvu što je prezre i savez što ga razvrže oborit ću na glavu njegovu!');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (33, 17, 20, 'Mrežu ću nad njim razapeti i uhvatit će se u moju zamku, pa ću ga odvesti u Babilon i ondje mu suditi zbog nevjere kojom mi se iznevjeri.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (33, 17, 21, 'Cvijet vojske njegove od mača će pasti, a ostatak se raspršiti u sve vjetrove. I spoznat ćete da ja, Jahve, tako rekoh.\'');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (33, 17, 22, 'Ovako govori Jahve Gospod: \'S vrha cedra velikoga, s vrška mladih grana njegovih, odlomit ću grančicu i posadit\' je na gori visokoj, najvišoj.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (33, 17, 23, 'Na najvišoj gori izraelskoj nju ću zasaditi: razgranat će se ona, plodom uroditi.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (33, 17, 24, 'I sve će poljsko drveće znati da ja sam Jahve koji visoko drvo ponizujem, a nisko uzvisujem; zeleno drvo sušim, a drvu suhu dajem da rodi. Ja, Jahve, rekoh i učinit ću!\'\"');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (33, 18, 1, 'Dođe mi riječ Jahvina:');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (33, 18, 2, '\"Što vam je te o Izraelu ponavljate poslovicu: \'Oci jedoše kiselo grožđe, sinovima trnu zubi!\'');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (33, 18, 3, 'Života mi moga, riječ je Jahve Gospoda: nitko od vas neće više u Izraelu ponavljati tu poslovicu;');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (33, 18, 4, 'jer, svi su životi moji, kako život očev tako i život sinovlji. I evo, onaj koji zgriješi, taj će umrijeti.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (33, 18, 5, 'Tko je pravedan i poštuje zakon i pravdu');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (33, 18, 6, 'i ne blaguje po gorama i očiju ne podiže kumirima doma Izraelova, ne oskvrnjuje žene bližnjega svoga i ne prilazi ženi dok je nečista;');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (33, 18, 7, 'nikomu ne nanosi nasilja, vraća što je u zalog primio i ništa ne otima; kruh svoj dijeli s gladnim, gologa odijeva,');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (33, 18, 8, 'ne posuđuje uz dobit i ne uzima pridavka, ruku usteže od nedjela, po istini presuđuje,');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (33, 18, 9, 'po mojim naredbama hodi i čuva moje zakone, postupajući po istini - taj je zaista pravedan i taj će živjeti, riječ je Jahve Gospoda.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (33, 18, 10, 'Ali, porodi li on sina nasilnika, koji krv prolijeva ili bratu takvo što učini,');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (33, 18, 11, 'a ne radi kao njegov roditelj, nego blaguje po gorama, oskvrnjuje ženu bližnjega;');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (33, 18, 12, 'ubogu i bijednu nanosi nasilje, otima, ne vraća što je u zalog primio, oči podiže kumirima čineći gadosti;');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (33, 18, 13, 'posuđuje uz dobit i uzima pridavak - ne, takav sin neće živjeti! Učinio je te gadosti i umrijet će, a krv će njegova na njega pasti.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (33, 18, 14, 'A porodi li on sina koji uvidi sve grijehe što ih njegov otac počini, uvidi ih i tako više ne učini;');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (33, 18, 15, 'ne blaguje po gorama, očiju ne podiže kumirima doma Izraelova, ne oskvrnjuje žene bližnjega;');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (33, 18, 16, 'nikomu ne nanosi nasilja, ne prisvaja zaloga, ništa ne otima, kruh svoj dijeli s gladnim, gologa odijeva;');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (33, 18, 17, 'ruku usteže od nedjela, ne uzima dobiti ni pridavka, vrši moje zakone i hodi po mojim naredbama - ne, taj neće umrijeti zbog grijeha očeva, on će živjeti.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (33, 18, 18, 'A njegov otac, koji je nemilice tlačio i pljačkao bližnjega, čineći u narodu što ne valja, zbog svojega će grijeha umrijeti.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (33, 18, 19, 'Ali vi kažete: \'Zašto da sin ne snosi očev grijeh?\' Zato što sin vrši zakon i pravdu, čuva i vrši sve moje naredbe, živjet će.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (33, 18, 20, 'Onaj koji zgriješi, taj će i umrijeti. Sin neće snositi grijeha očeva, ni otac grijeha sinovljega. Na pravedniku će biti pravda njegova, a na bezbožniku bezbožnost njegova.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (33, 18, 21, 'Ako se bezbožnik odvrati od svih grijeha što ih počini, i bude čuvao sve moje naredbe i vršio zakon i pravdu, živjet će i neće umrijeti.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (33, 18, 22, 'Sva njegova nedjela što ih počini bit će zaboravljena: zbog pravednosti što je čini, živjet će.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (33, 18, 23, 'Jer, zar je meni do toga da umre bezbožnik - riječ je Jahve Gospoda - a ne da se odvrati od svojih zlih putova i da živi?');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (33, 18, 24, 'Ako li se pravednik odvrati od svoje pravednosti i stane činiti nepravdu i sve gadosti koje radi bezbožnik - hoće li živjeti? Sva pravedna djela koja bijaše činio zaboravit će se, a zbog svoje nevjere kojom se iznevjerio i zbog grijeha što ih počini, umrijet će.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (33, 18, 25, 'A vi velite: \'Put Jahvin nije pravedan!\' Čuj, dome Izraelov: Moj put da nije pravedan? Nisu li vaši putovi nepravedni?');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (33, 18, 26, 'Ako li se pravednik odvrati od svoje pravednosti i stane činiti nepravdu, pa zbog toga umre, umrijet će zbog nepravde što je počini.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (33, 18, 27, 'A ako se bezbožnik odvrati od svoje bezbožnosti što je bijaše činio, pa stane vršiti moj zakon i pravdu, živjet će i neće umrijeti.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (33, 18, 28, 'Jer je uvidio i odvratio se od svojih nedjela što ih bijaše počinio, živjet će i neće umrijeti.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (33, 18, 29, 'Ali dom Izraelov kaže: \'Put Gospodnji nije pravedan!\' Putovi moji da nisu pravedni, dome Izraelov? Nisu li vaši putovi nepravedni?');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (33, 18, 30, 'Dome Izraelov, ja ću suditi svakome po njegovim putovima - riječ je Jahve Gospoda. Obratite se, dakle, i povratite od svih svojih nedjela, i grijeh vam vaš neće biti na propast!');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (33, 18, 31, 'Odbacite od sebe sva nedjela koja ste činili i načinite sebi novo srce i nov duh! Zašto da umirete, dome Izraelov?');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (33, 18, 32, 'Ja ne želim smrti nikoga koji umre - riječ je Jahve Gospoda. Obratite se, dakle, i živite!');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (33, 19, 1, 'A ti, sine čovječji, protuži tužaljkom za knezovima izraelskim.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (33, 19, 2, 'Reci: Što bijaše tvoja mati? Lavica među lavovima, ležala je među lavićima, hraneći mladunčad svoju.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (33, 19, 3, 'I othrani jedno mlado, koje lavom posta. Naučiv se plijen derati, stade ljude proždirati!');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (33, 19, 4, 'Narodi se protiv njega udružiše, lav upade u jamu njihovu, na lancu ga odvedoše u zemlju egipatsku.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (33, 19, 5, 'A kad mati vidje da uzalud čeka i da joj nada propade, uze drugo mlado i od njega lava učini.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (33, 19, 6, 'Živeć\' tako među lavovima, i on lavom posta. Naučiv se plijen derati, stade ljude proždirati,');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (33, 19, 7, 'utvrde im rušiti, pustošiti gradove. Uzdrhta zemlja i sve na njoj od silne rike njegove.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (33, 19, 8, 'Ali se ljudi iz okolnih mjesta protiv njega podigoše i zamke mu postaviše; i lav se uhvati u jamu njihovu.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (33, 19, 9, 'Okovana u kavez ga zatvoriše, odvedoše kralju babilonskom, ondje ga u kulu zatočiše, da mu se više ne čuje rika po gorama izraelskim.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (33, 19, 10, 'Mati tvoja bješe kao loza pokraj vode zasađena, rodna i granata od obilja vode!');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (33, 19, 11, 'Imala je jaku granu za palicu vladalačku: uzdiže se nad krošnju, naočita visinom, mnoštvom grančica.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (33, 19, 12, 'Al\' u gnjevu bješe iščupana i na zemlju bačena. Istočnjak joj rod sasuši: polomi se i uvenu jaka grana njezina i vatra je svu proguta.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (33, 19, 13, 'U pustinju bje presađena, u zemlju suhu, bezvodnu.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (33, 19, 14, 'Al\' liznu oganj iz pruta njezina i spali joj grane i plodove! I nema više na njoj grane jake za palicu vladalačku.\" To je, evo tužaljka, i ostat će tužaljka.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (33, 20, 1, 'Godine sedme, petoga mjeseca, desetoga dana, dođoše k meni neke od starješina izraelskih da se s Jahvom svjetuju. Posjedaše preda me.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (33, 20, 2, 'I dođe mi riječ Jahvina: \"Sine čovječji! Govori starješinama Izraelovim!');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (33, 20, 3, 'Reci im: Ovako govori Jahve Gospod: \'Došli ste me pitati za savjet? Života mi moga, nećete me pitati!\' - riječ je Jahve Gospoda.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (33, 20, 4, 'Hoćeš li im suditi, hoćeš li suditi, sine čovječji? Pokaži im gadosti otaca njihovih.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (33, 20, 5, 'Reci im: Ovako govori Jahve Gospod: \'Onoga dana kad izabrah Izraela i ruku stavih na potomstvo doma Jakovljeva te im se objavih u zemlji egipatskoj, zakleh im se: Ja sam Jahve, Bog vaš!');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (33, 20, 6, 'Toga im se dana rukom podignutom zakleh da ću ih izvesti iz zemlje egipatske u zemlju koju za njih izabrah, u zemlju kojom teče med i mlijeko, od svih zemalja najljepšu.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (33, 20, 7, 'I rekoh im: Odbacite od sebe sve gadosti što vam oči privlače i ne kaljajte se kumirima egipatskim jer - ja sam Jahve, Bog vaš!\'');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (33, 20, 8, 'Ali se oni odvrgoše od mene i ne htjedoše me poslušati: nijedan ne odbaci gadosti koje mu oči zaniješe i ne okani se kumira egipatskih. Tad odlučih izliti gnjev svoj na njih i iskaliti srdžbu na njima u zemlji egipatskoj.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (33, 20, 9, 'Ali radi imena svojega - da se ne kalja na oči naroda među kojima obitavahu i pred kojima im bijah objavio da ću ih izvesti -');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (33, 20, 10, 'izvedoh ih iz zemlje egipatske i odvedoh ih u pustinju;');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (33, 20, 11, 'i dadoh im svoje uredbe i objavih svoje zakone, koje svatko mora vršiti da bi živio;');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (33, 20, 12, 'dadoh im i svoje subote, kao znak između sebe i njih, neka znaju da sam ja Jahve koji ih posvećujem.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (33, 20, 13, 'Ali se i u pustinji dom Izraelov odmetnu od mene: nisu hodili po mojim uredbama; odbaciše moje zakone, koje svatko mora vršiti da bi živio; subote moje oskvrnjivahu. I zato odlučih u pustinji gnjev svoj na njih izliti da ih zatrem.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (33, 20, 14, 'Ali ni toga ne učinih radi svojeg imena, da se ono ne kalja pred narodima kojima ih naočigled izvedoh.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (33, 20, 15, 'Ali im se zakleh u pustinji da ih neću uvesti u zemlju koju sam im bio dao, u zemlju kojom teče med i mlijeko, od svih zemalja najljepšu,');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (33, 20, 16, 'jer odbaciše moje zakone, i ne hodiše po mojim uredbama, i subote moje oskvrnjivahu, a srce im iđaše za njihovim kumirima.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (33, 20, 17, 'Oči se moje ipak sažališe da ih ne zatrem. I tako ih u pustinji ne uništih,');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (33, 20, 18, 'nego rekoh sinovima njihovim u pustinji: \'Ne hodite po uredbama svojih otaca, ne čuvajte zakona njihovih i ne kaljajte se kumirima njihovim!');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (33, 20, 19, 'Ja sam Jahve, Bog vaš! Po uredbama mojim hodite, čuvajte i vršite moje zakone');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (33, 20, 20, 'i svetkujte moje subote, neka one budu znak između mene i vas, kako bi se znalo da sam ja Jahve, Bog vaš!\'');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (33, 20, 21, 'Ali se i sinovi odmetnuše od mene: po mojim uredbama nisu hodili i nisu čuvali ni vršili mojih zakona, koje svatko mora vršiti da bi živio, a subote su moje oskvrnjivali. I zato odlučih gnjev svoj izliti i iskaliti srdžbu svoju na njima u pustinji.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (33, 20, 22, 'Ali opet ruku svoju sustegoh radi svojeg imena, da se ono ne kalja pred narodima kojima ih naočigled izvedoh.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (33, 20, 23, 'No zakleh se u pustinji da ću ih raspršiti među narode i rasijati po zemljama,');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (33, 20, 24, 'jer nisu vršili mojih zakona i jer prezreše moje uredbe i jer subote moje oskvrnjivahu i oči upirahu u kumire svojih otaca.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (33, 20, 25, 'I zato im dadoh uredbe koje ne bijahu dobre, zakone koji usmrćuju:');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (33, 20, 26, 'da se oskvrnjuju svojim prinosima, provodeći kroz oganj svoju prvorođenčad. Htjedoh tako da ih zastrašim, neka znaju da sam ja Jahve.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (33, 20, 27, 'Sine čovječji, reci domu Izraelovu: \'Ovako govori Jahve Gospod! I ovim me oci vaši još uvrijediše: nevjerom mi se iznevjeriše!');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (33, 20, 28, 'Kad ih uvedoh u zemlju koju im se zakleh dati, gdje god bi ugledali povišen brežuljak ili stablo krošnjato, prinosili bi žrtve, donosili izazovne prinose, metali mirise ugodne, nalijevali ljevanice.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (33, 20, 29, 'Upitah ih: što li znači ta uzvišica na koju se penjete?\' I tako osta ime \'bama\', uzvišica, do dana današnjega.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (33, 20, 30, 'Zato reci domu Izraelovu: \'Ovako govori Jahve Gospod: Ne kaljate li se i vi kao oci vaši, ne provodite li i vi blud s gadostima njihovim?');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (33, 20, 31, 'Kaljate se prinoseći im darove, provodeći kroz oganj svoje sinove u čast svim kumirima svojim sve do dana današnjega. I da me onda za savjet pitaš, dome Izraelov! Života mi moga - riječ je Jahve Gospoda - nećete me za savjet pitati!');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (33, 20, 32, 'I neće se zbiti o čemu sanjate kad govorite: \'Bit ćemo kao drugi narodi, kao narodi ostalih zemalja što služe drveću i kamenju.\'');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (33, 20, 33, 'Života mi moga - riječ je Jahve Gospoda - vladat ću vama rukom krepkom i mišicom uzdignutom, u svoj žestini svoje jarosti.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (33, 20, 34, 'Izvest ću vas iz naroda, skupiti vas iz svih zemalja u koje bijaste raspršeni rukom krepkom i mišicom uzdignutom, u svem plamu jarosti moje!');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (33, 20, 35, 'Odvest ću vas u pustinju naroda i ondje vam licem u lice suditi!');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (33, 20, 36, 'Kao što sudih ocima vašim u pustinji zemlje egipatske, i vama ću suditi - riječ je Jahve Gospoda!');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (33, 20, 37, 'Provest ću vas ispod štapa svojega, podvrći vas brojenju:');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (33, 20, 38, 'razlučit ću između vas sve koji se pobuniše i odvrgoše od mene: izvest ću ih iz zemlje u kojoj kao došljaci borave, ali - u zemlju Izraelovu nikad ući neće! I znat ćete da sam ja Jahve!\'');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (33, 20, 39, '\'A vi, dome Izraelov\' - ovako govori Jahve Gospod - \'samo idite i dalje služite svaki svom kumiru! Jednom ćete, kunem vas se, poslušati i nećete više kaljati moje sveto ime svojim prinosima i kumirima:');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (33, 20, 40, 'na Svetoj gori mojoj, na visokoj gori Izraelovoj - riječ je Jahve Gospoda - služit će mi sav dom Izraelov, u svojoj zemlji. Ondje će mi oni omiljeti i ondje ću iskati vaše podizanice i prinose vaših prvina sa svim svetinjama.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (33, 20, 41, 'Omiljet ćete mi kao miris ugodan kad vas izvedem iz narodÄa i skupim iz zemalja u kojima bjeste rasijani. I na vama ću očitovati svetost svoju naočigled svih naroda.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (33, 20, 42, 'Tada ćete znati da sam ja Jahve, kada vas dovedem u zemlju Izraelovu, u zemlju koju se zakleh dati očevima vašim.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (33, 20, 43, 'Ondje ćete se spomenuti svih svojih putova i nedjela kojima se okaljaste: sami ćete sebi omrznuti zbog nedjela što ih počiniste.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (33, 20, 44, 'I tada ćete spoznati da sam ja Jahve kad, radi imena svojega, ne postupim s vama po zloći vaših putova ni po vašim pokvarenim djelima, dome Izraelov! Tako govori Jahve Gospod!\'\"');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (33, 21, 1, 'I dođe mi riječ Jahvina:');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (33, 21, 2, '\"Sine čovječji, okreni lice k jugu i prospi besjedu prema jugu te prorokuj protiv šume u kraju negepskom.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (33, 21, 3, 'Reci šumi negepskoj: \'Poslušaj riječ Jahvinu! Ovako govori Jahve Gospod: Evo, zapalit ću usred tebe oganj i on će proždrijeti u tebi svako drvo, zeleno i suho! Razgorjeli se oganj neće utrnuti dok sve ne izgori od sjevera do juga.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (33, 21, 4, 'I svi će vidjeti da sam ja, Jahve, zapalio taj oganj i neće se ugasiti.\'\"');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (33, 21, 5, 'Rekoh na to: \"Jao, Jahve Gospode, tÓa oni će za mene reći: \'Evo opet pričalice s pričama!\'\"');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (33, 21, 6, 'I dođe mi riječ Jahvina:');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (33, 21, 7, '\"Sine čovječji, okreni lice prema Jeruzalemu i prospi besjedu protiv njegova Svetišta i prorokuj protiv zemlje Izraelove.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (33, 21, 8, 'Reci zemlji Izraelovoj: \'Ovako govori Jahve Gospod: Evo me na te! Trgnut ću mač iz korica, istrijebit ću iz tebe sve - i pravedna i bezbožna!');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (33, 21, 9, 'Da iz tebe istrijebim pravedna i bezbožna, trgnut ću evo mač iz korica na svako tijelo, od sjevera do juga.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (33, 21, 10, 'I svako će tijelo spoznati da sam ja, Jahve, isukao mač svoj iz korica i da ga više neću u njih vratiti!');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (33, 21, 11, 'A ti, sine čovječji, kukaj kao da su ti sva rebra polomljena, kukaj gorko, njima na oči!');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (33, 21, 12, 'Ako li te zapitaju: \'Što toliko kukaš?\' reci im: \'Zbog vijesti koja stiže, od koje će sva srca zamrijeti i sve ruke klonuti, svaki duh biti utučen i svako koljeno klecati. Evo, dolazi, već je tu!\' Tako govori Jahve Gospod.\"');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (33, 21, 13, 'I dođe mi riječ Jahvina:');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (33, 21, 14, '\"Sine čovječji, prorokuj! Ovako govori Jahve Gospod. Reci: \'Mač! Mač! Naoštren i osvjetlan!');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (33, 21, 15, 'Za klanje naoštren, osvjetlan da sijeva.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (33, 21, 16, 'Osvjetlan da ga ruka prihvati, mač naoštren, osvjetlan da se stavi u ruke ubojici.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (33, 21, 17, 'A ti, sine čovječji, plači, nariči! Jer, evo, mač je već na narod moj isukan, mač na izraelske knezove: svi su oni s mojim narodom maču izručeni! Udri se stoga u slabine!\'');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (33, 21, 18, 'Dođe kušnja, i odbačenoga žezla više biti neće - riječ je Jahve Gospoda.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (33, 21, 19, 'A ti, sine čovječji, prorokuj i rukama plješći. Neka se udvostruči, neka se utrostruči taj mač pokolja, mač pokolja golema što ih odasvud okružuje.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (33, 21, 20, 'Da zadršću srca, da bude žrtava nebrojenih, na svaka sam vrata postavio mač, pripravljen da k\'o munja sijeva, za pokolje naoštren.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (33, 21, 21, 'Natrag! Desno! Naprijed! Lijevo!');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (33, 21, 22, 'I ja ću pljeskati rukama, iskaliti gnjev svoj na njima! Ja, Jahve, rekoh!\"');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (33, 21, 23, 'I dođe mi riječ Jahvina:');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (33, 21, 24, '\"Sine čovječji, zacrtaj dva puta kuda da pođe mač kralja babilonskoga. Neka oba puta izlaze iz iste zemlje! Na raskršću puta ka gradu stavi putokaz.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (33, 21, 25, 'Zacrtaj maču put da dođe u Rabat Bene Amon i u Judeju, u utvrđeni Jeruzalem.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (33, 21, 26, 'Jer kralj babilonski stoji na početku puta, na raspuću dvaju putova, i pita znamenja - miješa strijele, ispituje terafime i motri jetru.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (33, 21, 27, 'Znamenja mu u desnici kažu: na Jeruzalem; da ondje namjesti zidodere, da naredi pokolj, da podigne zidodere protiv vrata, da naspe nasip i sagradi opsadne kule.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (33, 21, 28, 'Ali će se njima učiniti da je znamenje lažno, jer mu se zakleše na vjernost. Ali će ih on tada podsjetiti na njihovo vjerolomstvo u koje se uloviše.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (33, 21, 29, 'Zato, ovako govori Jahve Gospod: \'Jer bez prestanka podsjećate na svoja bezakonja otkrivajući opačine i pokazujući grijehe u svim svojim djelima - da, jer bez prestanka na njih podsjećate, u njih ćete se uloviti.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (33, 21, 30, 'A tebi, nečasni i bezbožnički kneže izraelski, tebi dođe dan i čas posljednjega zločina.\'');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (33, 21, 31, 'Ovako govori Jahve Gospod: \'Skini mitru s glave i odloži kraljevski vijenac! Jer sve se mijenja: tko bi dolje, bit će uzvišen, a tko bi gore, bit će ponižen.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (33, 21, 32, 'Ruševine, ruševine, ruševine ću postaviti kakvih nije bilo, dok ne dođe onaj koji ima suditi, jer ja ću mu predati sud.\'');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (33, 21, 33, 'Sine čovječji, prorokuj: Ovako govori Jahve Gospod sinovima Amonovim o njihovoj sramoti. Reci: \'Mač! Mač za pokolj isukan i naoštren da siječe, da kao munja sijeva,');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (33, 21, 34, 'a tebi dotle isprazno viđaju, laž proriču - da se stavi pod vrat zlikovcima zloglasnim, kojima, eto, dođe dan i čas posljednjega zločina!');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (33, 21, 35, 'Ali vrati mač u korice! U mjestu gdje si nastao i u zemlji gdje si se rodio ja ću ti suditi.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (33, 21, 36, 'Ondje ću na te gnjev svoj izliti i raspiriti protiv tebe plamen srdžbe svoje i predati te u ruke okrutnim ljudima, vještim zatornicima.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (33, 21, 37, 'I bit ćeš hrana ognju, a krv će tvoja zemljom protjecati. I nitko te živ više neće spominjati! Jer ja, Jahve, tako rekoh.\'\"');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (33, 22, 1, 'I dođe mi riječ Jahvina:');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (33, 22, 2, '\"Sine čovječji, hoćeš li suditi, hoćeš li suditi gradu krvničkom? Pokaži mu sve gnusobe njegove!');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (33, 22, 3, 'Reci: \'Ovako govori Jahve Gospod: Grade što u sebi krv toliku prolijevaš i što svuda sebi kumire praviš da se okaljaš, kucnu čas tvoj:');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (33, 22, 4, 'krvlju što je proli ti sagriješi i kumirima koje napravi ti se okalja, skrativši tako dane svoje i ubrzavši svoje godine. I zato ću te sada učiniti sramotom među narodima, ruglom po svim zemljama.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (33, 22, 5, 'I koji su ti blizu i koji su ti daleko, podrugivat će se tebi: \'O sramotno ime, grade pokvareni!\'');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (33, 22, 6, 'Eto, knezovi izraelski - svaki na svoju ruku - u tebi krv prolijevaju.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (33, 22, 7, 'I u tebi se više ne poštuje ni otac ni majka, došljake tlače, siročad i udovice u tebi zlostavljaju!');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (33, 22, 8, 'Svetinje moje prezireš, subote oskvrnjuješ.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (33, 22, 9, 'U tebi su klevetnici zbog kojih se krv prolijeva; u tebi se po gorama blaguje, posred tebe čine sramote.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (33, 22, 10, 'U tebi se raskriva sramota očeva, u tebi siluju žene dok su nečiste.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (33, 22, 11, 'Jedan čini gadost sa ženom susjeda svoga, drugi djelom sramotnim oskvrnjuje snahu svoju, a treći u tebi siluje sestru, kćerku oca svoga.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (33, 22, 12, 'Ima ih koji i mito primaju da krv proliju. Uzimaš ujam i pridatak, od bližnjega silom otimaš, a mene zaboravljaš - riječ je Jahve Gospoda.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (33, 22, 13, 'Zato, evo, ja rukama plješćem nad plijenom što ga ti napljačka i nad krvlju što se lije u tebi.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (33, 22, 14, 'Jer, hoće li srce tvoje izdržati i hoće li ruke tvoje odoljeti u dane kad ja na te ustanem? Ja, Jahve, rekoh i učinit ću!');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (33, 22, 15, 'Zato ću te raspršiti među narode, rasijat\' te po zemljama, da uklonim iz tebe svu nečistoću!');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (33, 22, 16, 'I bit ćeš opet moja baština naočigled naroda. I znat ćeš da sam ja Jahve!\'\"');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (33, 22, 17, 'Dođe mi riječ Jahvina:');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (33, 22, 18, '\"Sine čovječji, dom Izraelov troska mi postade: bakar, srebro, kositar, željezo i olovo u peći - svi su oni troska!');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (33, 22, 19, 'Stoga ovako govori Jahve Gospod: \'Jer mi troska postadoste, skupit ću vas, evo, u Jeruzalemu.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (33, 22, 20, 'Kao što se skuplja srebro, bakar, željezo, olovo i kositar u peći te se okolo oganj potpiri da se sve rastali, tako ću i ja vas skupiti u svojem gnjevu i u svojoj jarosti, složiti vas i rastaliti.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (33, 22, 21, 'Jest, skupit ću vas i potpiriti oko vas oganj svoje jarosti da se usred grada rastalite.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (33, 22, 22, 'Kao što se srebro u peći topi, tako ćete se i vi u njemu rastopiti. I znat ćete da ja, Jahve, gnjev svoj na vas izlijevam!\'\"');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (33, 22, 23, 'Dođe mi riječ Jahvina:');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (33, 22, 24, '\"Sine čovječji, reci još: \'Ti si zemlja još neočišćena, koju još ne opra kiša dana jarosnoga!');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (33, 22, 25, 'Knezovi njezini, poput lavova što riču i plijen razdiru, ljude proždiru, otimlju im blago i dragocjenosti, množeći udovice usred nje.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (33, 22, 26, 'Svećenici njezini ne poštuju mog Zakona i oskvrnjuju moje svetinje, ne razlikujući sveto od nesvetoga, ne učeći se lučiti nečisto od čistoga. Zanemarili su subote moje, bez časti sam u njihovoj sredini.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (33, 22, 27, 'Starješine njezine, poput vukova što plijen razdiru i krv prolijevaju, upropašćuju ljude, lakomi na dobitak.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (33, 22, 28, 'A proroci njezini sve to premazuju bjelilom i prekrivaju ispraznim viđenjima i lažnim proricanjima zboreći: \'Ovako govori Jahve Gospod!\' - a Jahve to ne reče.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (33, 22, 29, 'Imućnici pak čine svakojaka nasilja i otimačine, siromaha i bijednika ugnjetavaju, a došljaka bespravno tlače.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (33, 22, 30, 'Tražio sam među njima nekoga da podigne zidine i stane na proboje preda me u obranu zemlje, da je ne zatrem, i ne nađoh nikoga.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (33, 22, 31, 'I zato izlih na njih gnjev svoj pa ih zatrijeh ognjem svoje jarosti; putove im njihove na glavu oborih\' - riječ je Jahve Gospoda.\"');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (33, 23, 1, 'Dođe mi riječ Jahvina:');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (33, 23, 2, '\"Sine čovječji, bile dvije žene, kćeri jedne matere.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (33, 23, 3, 'I odaše se bludu u Egiptu, blud činiše u mladosti: ondje su im grudi stiskali, djevojačke dojke gnječili.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (33, 23, 4, 'Starijoj bijaše ime Ohola, a sestri joj Oholiba. Obje moje postadoše i rodiše mi sinove i kćeri. Evo im imenÄa: Samarija je Ohola, Jeruzalem Oholiba.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (33, 23, 5, 'Ohola, iako meni pripadaše, bludu se odala; uspalila se za ljubavnicima, za Asircima, susjedima svojim,');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (33, 23, 6, 'u modri baršun odjevenima, sve samim vojvodama i namjesnicima, pristalim momcima, vještim konjanicima.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (33, 23, 7, 'I oda se bludu s njima, sve poizbor sinovima asirskim; i usplamtjev za njima, okalja se svim njihovim kumirima.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (33, 23, 8, 'A ne okani se ni bluda s Egipćanima, koji s njome ležahu od njezine mladosti, koji su joj djevojačke dojke gnječili i na nju blud svoj izlijevali.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (33, 23, 9, 'I zato je predah u ruke njenim ljubavnicima, u ruke Asircima za kojima se uspalila.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (33, 23, 10, 'I oni je razgoliše, zarobiše joj sinove i kćeri, a nju samu mačem pogubiše. I postade tako primjer svim ženama kako na njoj bi sud izvršen.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (33, 23, 11, 'Vidje to sestra joj Oholiba, ali se još gore uspali i gori blud činjaše.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (33, 23, 12, 'Za sinovima se asirskim uspaljivala, sve samim vojvodama i namjesnicima, svojim susjedima, raskošno odjevenim, vještim konjanicima, poizbor momcima.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (33, 23, 13, 'I vidjeh kako se okaljala: obje su istim putem pošle.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (33, 23, 14, 'Ali se ova još gore bludu odala: kad bi ugledala muškarca na zidu naslikana, likove Kaldejaca crvenilom nacrtane,');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (33, 23, 15, 'bedara pasom opasanih, sa spuštenim povezima na glavama - sve junake, prave Babilonce, rodom iz zemlje kaldejske -');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (33, 23, 16, 'tek što bi ugledala priliku njihovu, sva bi se za njima uspalila te im slala poslanike u zemlju kaldejsku.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (33, 23, 17, 'Sinovi babilonski k njoj bi dohrlili na ljubavnu postelju da je bludom kaljaju. A kad bi se s njima okaljala, zgadili bi joj se.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (33, 23, 18, 'Ali se razglasilo njezino bludništvo, otkrila se njena golotinja, i duša se moja od nje odvratila, kao što se bješe odvratila od sestre njene.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (33, 23, 19, 'Jer ona se još gorem bludu predala, opominjući se dana svoje mladosti kad se u Egiptu bludu odavala,');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (33, 23, 20, 'uspaljujući se za razvratnicima kojima muška snaga bijaše kao u magaraca, a izljev kao u pastuha.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (33, 23, 21, 'Tako se opet vrati sramoti svoje mladosti, kad su joj u Egiptu grudi pritiskivali, djevičanske dojke gnječili.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (33, 23, 22, 'Zato, Oholibo, ovako govori Jahve Gospod: \'Gle, dignut ću na te tvoje ljubavnike, koji ti se duši ogadiše, i dovest ću ih odasvud na tebe:');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (33, 23, 23, 'Babilonce, sve Kaldejce, Pekođane, Šoance i Koance, a s njima sve sinove asirske - sve poizbor momke, vojvode i namjesnike, na glasu junake, vješte konjanike.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (33, 23, 24, 'I doći će na te sa sjevera sila bojnih kola i točkova s mnoštvom naroda i svrstat\' se odasvud protiv tebe sa štitovima, štitićima i oklopima. Njima ću te na sud predati, i svojim će ti sudom suditi.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (33, 23, 25, 'Oborit ću na te svu svoju ljubomoru, neka s tobom jarosno postupe: nos i uši neka ti odsijeku, a ostatak tvoj da od mača padne; sinove i kćeri da ti odvedu, a ostatak tvoj da oganj proguta.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (33, 23, 26, 'I zderat će s tebe tvoje haljine i oteti sve tvoje nakite.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (33, 23, 27, 'Tako ću okončati svu tvoju sramotu i bludničenje, sve tamo od Egipta: nećeš više k njima oči dizati i nećeš se više spominjati Egipta!\'');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (33, 23, 28, 'Jer, ovako govori Jahve Gospod: \'Evo me! Predat ću te u ruke onima koji ti omrznuše, koji ti se duši ogadiše.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (33, 23, 29, 'Neka iskale na tebi svoju mržnju, neka ti svu muku preotmu, a tebe nek\' ostave golu i nagu! Neka se obnaži sva golotinja tvoje bludnosti i besramnosti, tvojeg bludničenja.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (33, 23, 30, 'Sve će te to stići zbog tvojeg bludničenja s narodima i jer si se okaljala njihovim kumirima.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (33, 23, 31, 'Putem si sestre svoje hodila: dat ću ti u ruku čašu njezinu:');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (33, 23, 32, 'Ovako govori Jahve Gospod: Čašu sestre svoje ispit ćeš, čašu široku, duboku, i bit ćeš na podsmijeh i ruglo - mnogo u nju stane! -');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (33, 23, 33, 'napunit ćeš se pijanstva i žalosti! Čaša je to pustošenja, užasa - čaša sestre tvoje Samarije.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (33, 23, 34, 'Pit ćeš je, do dna iskapiti, zatim u komade razbiti, grudi svoje izraniti. Jer, ja tako rekoh\' - riječ je Jahve Gospoda!');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (33, 23, 35, 'Stoga ovako govori Jahve Gospod: \'Jer ti mene zaboravi i leđa mi okrenu, snosi sada svu svoju sramotu i bestidnost!\'\"');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (33, 23, 36, 'I još mi reče Jahve: \"Sine čovječji, hoćeš li suditi Oholi i Oholibi, pokazati im njihove gadosti?');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (33, 23, 37, 'Preljub počiniše, ruke su im okrvavljene, s kumirima svojim preljub učiniše, djecu koju mi porodiše provedoše kroz oganj da ih proguta.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (33, 23, 38, 'Još mi i ovo učiniše: onoga dana obeščastiše moje Svetište i subote moje oskvrnuše.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (33, 23, 39, 'Jer istoga dana kad djecu svoju kumirima klaše, u Svetište moje dođoše da ga obeščaste. Eto, tako uradiše usred Doma mojega.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (33, 23, 40, 'Slale su čak po muškarce izdaleka, i oni bi im pohrlili čim bi glasnici k njima stigli. A ti se za njih kupala, oči svoje mazala i nakitom se kitila.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (33, 23, 41, 'A potom bi sjedala na raskošnu postelju pred kojom stol prostrt bijaše na koji si stavljala moj tamjan i moje ulje.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (33, 23, 42, 'Tu se čulo pocikivanje bezbrižnog društva zbog velikog mnoštva dovedena sa svih strana pustinje; stavljali su ženama na ruke narukvice i na glavu vijence prekrasne.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (33, 23, 43, 'I rekoh: \'Sa ženom ogrezlom u preljubu još blud tjeraju, i sama se ona još bludu odaje!\'');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (33, 23, 44, 'Prilaze joj kao kakvoj bludnici! Da, prilazili su k Oholi i Oholibi, pokvarenicama.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (33, 23, 45, 'Zato će im pravednici suditi kao što se sudi preljubnicama i onima koji krv prolijevaju, jer - one su preljubnice, ruke su im okrvavljene.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (33, 23, 46, 'Jer ovako govori Jahve Gospod: \'Neka se protiv njih zbor sazove da ih izvrgnem zlostavljanju i pljački.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (33, 23, 47, 'Zbor neka ih kamenuje i mačevima raskomada; sinove i kćeri neka im pokolje, a domove ognjem spali.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (33, 23, 48, 'Tako ću iz zemlje istrijebiti sramotu, da se druge žene opomenu i ne čine djela vaših sramotnih.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (33, 23, 49, 'A na vas ću oboriti svu vašu bestidnost, ispaštat ćete grijehe idolopoklonstva. I znat ćete da sam ja Jahve Gospod.\'\"');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (33, 24, 1, 'Godine devete, devetoga mjeseca, desetoga dana, dođe mi riječ Jahvina:');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (33, 24, 2, '\"Sine čovječji, zapiši ovaj dan: upravo danas kralj babilonski zaposjede Jeruzalem.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (33, 24, 3, 'Pripovijedaj domu odmetničkom prispodobu. Reci im: Ovako govori Jahve Gospod: \'Pristavi lonac, pristavi i nalij vode u nj!');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (33, 24, 4, 'Baci u nj komade, sve najbolje komade mesa, but i pleće! Napuni ga ponajboljim kostima!');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (33, 24, 5, 'Uzmi najbolje od stada. Pod loncem vatru naloži. Neka dobro uzavri, neka se u njemu skuhaju i kosti.\'');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (33, 24, 6, 'Jer ovako govori Jahve Gospod: \'Jao gradu krvničkom, zahrđalu loncu s kojega se hrđa ne skida! A zatim komad po komad iz njega izvadi, ali za nj ne bacaj kÓockÄe!');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (33, 24, 7, 'Jer krv je njegova u njemu - na golu je kamenu ostavi, po zemlji je ne razlij gdje bi je prašina mogla prekriti!');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (33, 24, 8, 'Da se gnjev moj raspali, da mu odmazdim, ostavih krv njegovu na kamenu golom, da se ne pokrije.\'');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (33, 24, 9, 'Stoga ovako govori Jahve Gospod: \'Jao gradu krvničkome, jer ću veliku lomaču naložiti!');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (33, 24, 10, 'Skupi drva, vatru potpali, skuhaj meso, primiješaj začina, nek\' izgore i kosti!');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (33, 24, 11, 'A zatim ga prazna na žeravicu pristavi da mjed mu se usija i nečistoća njegova sva se rastopi, da se uništi hrđa na njemu!');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (33, 24, 12, 'Grdne li muke! Ali se velika hrđa ne dade s njega skinuti: i vatri odolje.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (33, 24, 13, 'Sramotan je grijeh tvoj: htjedoh te očistiti, ali se ti ne htjede od grijeha očistiti; i zbog toga se više nećeš očistiti dok nad tobom ne iskalim gnjev svoj!');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (33, 24, 14, 'Ja, Jahve, rekoh! I riječ ću ispuniti; neću popustiti: I neću se smilovati niti ću se pokajati! Sudit ću te po putovima tvojim i po djelima tvojim! - riječ je Jahve Gospoda.\"');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (33, 24, 15, 'I dođe mi riječ Jahvina:');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (33, 24, 16, '\"Sine čovječji, evo, nenadanom smrću oduzet ću ti radost očinju! Ne tuguj, ne plači i ne roni suza!');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (33, 24, 17, 'Jecaj tiho, ali ne žali kao što se za mrtvima žali! I povij oko glave povez, a na noge obuj sandale. Ne prekrivaj brade i ne jedi žalobničke pogače.\"');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (33, 24, 18, 'Ujutro tako prorokovah narodu, a uveče mi žena umrije te sutradan uradih kao što mi bijaše zapovjeđeno.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (33, 24, 19, 'Narod me na to zapita: \"Nećeš li nam reći što znači za nas to što ti radiš?\"');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (33, 24, 20, 'Ja im odgovorih: \"Dođe mi riječ Jahvina:');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (33, 24, 21, '\"Reci domu Izraelovu: Ovako govori Jahve Gospod: Evo, oskvrnut ću svoje Svetište, vaš ponos snažni, radost vam očinju i čežnju duše vaše! I sinovi i kćeri koje ostaviste, od mača će pasti!');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (33, 24, 22, 'Tada ćete uraditi kao što i ja uradih: nećete prekrivati brade i nećete jesti žalobničke pogače!');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (33, 24, 23, 'Povit ćete povez oko glave i obuti na noge sandale! I nećete više tugovati ni plakati, nego ćete čiljeti zbog svojih nedjela i jecati jedan za drugim!');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (33, 24, 24, 'A Ezekiel će vam biti primjer: učinit ćete sve što je i on činio. Kad se to zbude, spoznat ćete da sam ja Jahve!\'');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (33, 24, 25, 'A ti, sine čovječji, doista u dan kad im oduzmem snagu, dičnu radost njihovu, radost im očinju, slast duše njihove, sinove i kćeri njihove -');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (33, 24, 26, 'u taj će dan k tebi stići bjegunac da ti to dojavi!');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (33, 24, 27, 'U taj će se dan tvoja usta otvoriti, i ti ćeš tom bjeguncu progovoriti; nećeš više biti nijem. I tako ćeš im biti znak. I oni će spoznati da sam ja Jahve!\"');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (33, 25, 1, 'I dođe mi riječ Jahvina:');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (33, 25, 2, '\"Sine čovječji, okreni lice k sinovima Amonovim te prorokuj protiv njih!');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (33, 25, 3, 'Reci sinovima Amonovim: \'Poslušajte riječ Jahve Gospoda! Ovako govori Jahve Gospod: Zato što vi klicaste \'ha, ha!\' nad mojim Svetištem kad ono bijaše oskvrnuto, i nad zemljom Izraelovom kad ona bijaše opustošena, i nad domom Judinim kad odlažaše u izgnanstvo,');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (33, 25, 4, 'predat ću vas, evo, u posjed sinovima Istoka da usred vas razapnu svoje šatore, udare svoja prebivališta. Oni neka jedu tvoje plodove i piju mlijeko tvoje!');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (33, 25, 5, 'Od Rabe ću pašnjake za deve načiniti, a u zemlji Amonovih sinova torove ću za ovce podići. I znat ćete da sam ja Jahve!\'');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (33, 25, 6, 'Jer ovako govori Jahve Gospod: \'Zato što si pljeskao rukama i udarao nogama i svom se dušom radovao nad zemljom Izraelovom,');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (33, 25, 7, 'ja ću, evo, ruku na te podići i kao plijen te predati narodima! Istrijebit ću te iz narodÄa, iskorijeniti iz zemalja! Zatrijet ću te! I znat ćeš da sam ja Jahve!');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (33, 25, 8, 'Ovako govori Jahve Gospod: \'Zato što Moab i Seir govorahu: \'Gle, dom je Judin poput svih naroda\',');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (33, 25, 9, 'otkrit ću, evo, obronke moapske, da s kraja na kraj ostane bez gradova što bijahu ukras zemlje: Bet Haješimot, Baal Meon i Kirjatajim.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (33, 25, 10, 'Dat ću ih u posjed sinovima Istoka, neprijateljima Amonaca, da se sinovi Amonovi među narodima više ne spominju!');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (33, 25, 11, 'Tako ću izvršiti sud nad Moabom. I znat će da sam ja Jahve!\'');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (33, 25, 12, 'Ovako govori Jahve Gospod: \'Zato što se Edom osveti domu Judinu i tom se osvetom teško ogriješi,');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (33, 25, 13, 'ovako govori Jahve Gospod: Podići ću ruku na Edom, istrijebit ću iz njega ljude i životinje! Pretvorit ću ga u pustinju: od Temana do Dedana svi će od mača izginuti.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (33, 25, 14, 'Tako ću se osvetiti Edomu rukom svojega naroda izraelskog. Oni će postupiti s Edomom prema mojem gnjevu i mojoj srdžbi. I spoznat će moju osvetu!\' - riječ je Jahve Gospoda.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (33, 25, 15, 'Ovako govori Jahve Gospod: \'Zato što Filistejci izvršiše odmazdu, krvavo se osvećujući s mržnjom u srcu, razarajući sve zbog svojeg neprijateljstva,');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (33, 25, 16, 'ovako govori Jahve Gospod: Evo, podižem ruku na Filistejce, istrijebit ću Kerećane, uništit ću sve što preostane na morskoj obali!');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (33, 25, 17, 'Tako ću im se strašno osvetiti kaznama jarosnim. I kad im se osvetim, znat će da sam ja Jahve.\'\"');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (33, 26, 1, 'Godine jedanaeste, prvoga dana u mjesecu, dođe mi riječ Jahvina:');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (33, 26, 2, '\"Sine čovječji, jer Tir nad Jeruzalemom klicaše: \'Ha, ha! Razbiše se ta vrata narÄodÄa, i k meni se okrenuše; obogatit ću se: on je opustošen\' -');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (33, 26, 3, 'stoga ovako govori Jahve Gospod: \'Evo me protiv tebe, Tire, dići ću na te silne narode, kao što more valove diže!');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (33, 26, 4, 'Porušit će zidine tirske i razoriti sve kule njegove. A ja ću mu i prašinu pomesti, načinit\' od njega pećinu golu!');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (33, 26, 5, 'Bit će sušilište mreža. Jer ja rekoh! - riječ je Jahve Gospoda. I narodima plijen će postati.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (33, 26, 6, 'A sve kćeri njegove od mača će pasti u polju! Znat će da sam ja Jahve!\'');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (33, 26, 7, 'Jer ovako govori Jahve Gospod: \'Gle, dovest ću na Tir sa sjevera Nabukodonozora, kralja babilonskoga, kralja nad kraljevima, s konjima i bojnim kolima, s konjanicima, četama i mnoštvom naroda!');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (33, 26, 8, 'Kćeri će tvoje u polju mačem posjeći! Protiv tebe dići će kule opsadne, nasuti protiv tebe nasipe i podić\' protiv tebe štitove.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (33, 26, 9, 'Na zidove će tvoje upraviti zidodere i tvoje će kule kukama oborit\'!');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (33, 26, 10, 'Od nebrojenih konja njegovih svega će te prašina prekriti, a od štropota konjanika i točkova i bojnih kola njihovih zadrhtat će zidine tvoje, kad bude prolazio kroz vrata tvoja, k\'o što se prolazi kroz grad osvojen.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (33, 26, 11, 'Kopitima svojih konja zgazit će ti sve ulice; narod tvoj mačem će pobiti i srušiti stupovlje tvoje.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (33, 26, 12, 'Poplijenit će bogatstvo tvoje, tvoje će razgrabiti blago! Razorit će tvoje zidine i kuće tvoje divne srušiti! Kamenje, drvo, prašinu tvoju u more će pobacati!');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (33, 26, 13, 'A ja ću prekinuti jeku tvojih pjesama, i zvuk se tvojih harfa više neće čuti!');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (33, 26, 14, 'Pretvorit ću te u pećinu golu, postat ćeš sušilište mrežÄa. Više se nikad nećeš podići, jer ja, Jahve, rekoh!\' - to riječ je Jahve Gospoda.\"');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (33, 26, 15, 'Ovako Jahve Gospod govori Tiru: \"A neće li od trijeska pada tvojega i jecanja tvojih ranjenika, kad nastane u tebi pokolj nemili, zadrhtati svi otoci?');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (33, 26, 16, 'I neće li tada svi morski knezovi sići s prijestolja svojih, odbaciti svoje plašteve, i skinuti vezene haljine, u strah se zaodjeti, na zemlju posjedati, dršćući bez prestanka, užasnuti tvojim udesom?');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (33, 26, 17, 'A zatim će nad tobom zakukati i reći ti: \'Kamo li propade? Kamo li s mora nestade, grade proslavljeni, što bijaše tako moćan na moru, ti i žitelji tvoji, koji strah zadavahu zemlji svoj?');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (33, 26, 18, 'Sada na dan pada tvojega otoci će zadrhtati, otoci u moru prestravit će se zbog propasti tvoje!\'');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (33, 26, 19, 'Jer ovako govori Jahve Gospod: \'Kad te pretvorim u pusti grad, kakvi su gradovi u kojima više nitko ne boravi, i kada na tebe dovedem bezdane da te velike vode prekriju,');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (33, 26, 20, 'spustit ću te s onima koji su sišli u grob, k narodu pradavnom, i smjestit ću te u najdublje zemljine predjele, u vječnu samoću, s onima što u grob siđoše, da se više ne vratiš u zemlju živih.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (33, 26, 21, 'Pretvorit ću te u užas i više te neće biti. Tražit će te, ali te više nikad neće naći!\' - riječ je Jahve Gospoda.\"');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (33, 27, 1, 'I dođe mi riječ Jahvina:');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (33, 27, 2, '\"A ti sine čovječji, udari u tužaljku nad Tirom');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (33, 27, 3, 'i reci Tiru što leži na ulazu u more i trguje s narodima bezbrojnih otoka: \'Ovako govori Jahve Gospod: Tire što govoraše: Ja sam lađa prekrasna, izvanredne ljepote.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (33, 27, 4, 'Tvoje međe sežu u more duboko, graditelji tvoji besprimjerno te lijepa načiniše.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (33, 27, 5, 'Od senirskih čempresa oplate ti sagradiše, cedar libanonski uzeše, jarbole ti podigoše;');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (33, 27, 6, 'od bašanskih hrastova istesaše ti vesla, od bjelokosti i šimšira s kitijimskog otočja palubu ti načiniše!');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (33, 27, 7, 'Od vezena lana egipatskog bijahu ti jedra da ti budu zastava! A grimiz i skrlet s eliških otoka staviše ti za krovišta.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (33, 27, 8, 'Žitelji Sidona i Arvada bjehu ti veslači, a mudraci tvoji, Tire, bijahu ti kormilari!');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (33, 27, 9, 'Starješine gebalske i vještaci popravljahu kvarove tvoje. Sve morske lađe i mornari bijahu tvoji i s tobom trgovahu!');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (33, 27, 10, 'Perzijanci, Ludijci i Putijci u tvojoj vojsci bijahu ratnici, u tebi vješahu štitove i kacige; oni ti sjaj davahu.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (33, 27, 11, 'Sinovi arvadski s vojnicima na bedemima tvojim uokrug čuvahu ti kule. O zidove ti uokolo štitove vješahu da uzveličaju jedinstvenu ljepotu tvoju!');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (33, 27, 12, 'Zbog bogatstva tvoga golemog čak i Taršiš s tobom trgovaše, plaćajući srebrom i gvožđem, olovom i kositrom trg tvoj.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (33, 27, 13, 'Javan i Tubal i Mešek s tobom trgovahu: davahu ljude i suđe mjedeno za trg tvoj.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (33, 27, 14, 'Oni iz Bet Togarme davahu konje, trkaće konjiće i mazge.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (33, 27, 15, 'I sinovi Dedanovi s tobom trgovahu. Mnogi ti otoci bijahu podložni: plaćahu ti daću u bjelokosti i ebanovini.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (33, 27, 16, 'Zbog obilja robe tvoje Edom s tobom trgovaše. Davahu ti za trg dragulje, purpur i vezivo, koralje, rubine i bez;');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (33, 27, 17, 'i Judeja i zemlja Izraelova trgovahu s tobom: minitskim žitom, voskom, medom, uljem i balzamom trg tvoj plaćahu!');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (33, 27, 18, 'Zbog obilja trga tvojeg, silnoga ti blaga, i Damask s tobom trgovaše za helbonsko vino i saharsku vunu.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (33, 27, 19, 'I Dan i Javan iz Uzala za trg tvoj prekaljeno gvožđe mijenjahu, cimet i slatku trsku.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (33, 27, 20, 'Dedan s tobom trgovaše prostirkama jahačkim.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (33, 27, 21, 'Arapi i kedarski knezovi mijenjahu se s tobom, trg ti plaćajući jaganjcima, jarcima i ovnovima.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (33, 27, 22, 'Trgovci iz Šebe i Rame trgovahu s tobom, za trg ti davahu najbolje dragulje i zlato.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (33, 27, 23, 'Haran, Kane i Eden, trgovci Šebe, Asirije i Kišmada trgovahu s tobom. Mijenjahu za trg tvoj');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (33, 27, 24, 'skupocjene halje, purpurne i vezene plašteve, sagove šarene i užad čvrsto pletenu.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (33, 27, 25, 'Taršiške su lađe nakrcane prevozile robu tvoju! Bješe tako puna i teška veoma.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (33, 27, 26, 'Na pučinu morsku, na mnoga te mora izvedoše veslači. Istočni te vjetar razbi na pučini morskoj!');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (33, 27, 27, 'Tvoje blago i trg ti, rukodjela tvoja, lađari tvoji i krmilari, popravljači pukotina, mjenjači trga tvojeg, svi ratnici na tebi i sve mnoštvo posred tebe potonut će na dno morsko na dan tvoga brodoloma!');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (33, 27, 28, 'Na vapaj ti krmilara obale će zadrhtati.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (33, 27, 29, 'I sići će s lađa svojih svi veslači, svi lađari i svi krmilari i ostat će na kopnu.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (33, 27, 30, 'Za tobom će glasno naricati i kukati gorko. Pepelom će posut glave, i valjat se u prašini;');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (33, 27, 31, 'zbog tebe će glave obrijati, kostrijet će pripasati, ojađene duše za tobom naricati, i kukati gorko.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (33, 27, 32, 'U žalosti će ti tužbalicu zapjevati, nad tobom će protužiti: \'Koji grad k\'o Tir ponosan bješe posred mora?\'');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (33, 27, 33, 'Jer kad bi on blago iskrcao, mnoge bi narode njima nasitio! Obiljem bogatstva i trga mnoge bi kraljeve zemaljske usrećio.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (33, 27, 34, 'A sada te, evo, valovi smrskaše, potonu u dubine morske! Blago tvoje i sva posada potonuše s tobom.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (33, 27, 35, 'Svi žitelji otočki zbog tebe se prestraviše. Kraljevi se njini naježiše, glave pokunjiše.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (33, 27, 36, 'Trgovci narodÄa zviždahu za tobom, jer ti strašilo posta i nestade zauvijek!\'\"');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (33, 28, 1, 'I dođe mi riječ Jahvina:');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (33, 28, 2, '\"Sine čovječji, kaži knezu tirskome: \'Ovako govori Jahve Gospod: Tvoje se srce uzoholi, ti reče: \'Ja sam bog! Na božjem prijestolju sjedim u srcu morskom.\' Iako čovjek, a ne Bog, ti srce svoje izjednači s Božjim.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (33, 28, 3, 'Bješe, eto, od Daniela mudriji, nijedna ti tajna ne bje skrivena!');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (33, 28, 4, 'Mudrošću svojom i razborom nateče bogatstva, riznicu napuni srebrom i zlatom!');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (33, 28, 5, 'Mudar li bijaše trgovac, bogatstvo svoje namnoži! Al\' ti se s bogatstva srce uzoholi.\'');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (33, 28, 6, 'Stog ovako govori Jahve Gospod: \'Jer svoje srce s Božjim izjednači,');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (33, 28, 7, 'dovest ću, evo, na te tuđince najnasilnije među narodima. Isukat će mačeve na mudrost ti divnu, i ljepotu će ti okaljati,');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (33, 28, 8, 'bacit će te u jamu da umreš nasilnijom smrću od onih što umiru na pučini morskoj!');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (33, 28, 9, 'Hoćeš li tada pred krvnikom reći: \'Ja sam bog\'? Čovjek si, a ne bog, u ruci svojih ubojica.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (33, 28, 10, 'Umrijet ćeš smrću neobrezanih od ruke tuđinske! Jer ja, Jahve, rekoh to\' - riječ je Jahve Gospoda.\"');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (33, 28, 11, 'I dođe mi riječ Jahvina:');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (33, 28, 12, '\"Sine čovječji, zakukaj tužaljku nad tirskim kraljem. Reci mu: \'Ovako govori Jahve Gospod: Gle, ti bješe uzor savršenstva, pun mudrosti i čudesno lijep!');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (33, 28, 13, 'U Edenu, vrtu Božjem, ti življaše, resio te dragulj svaki, sard, topaz i dijamant, krizolit, oniks i jaspis, safir, smaragd i zlato. Načinjeni bjehu bubnjevi i frule, na dan ti rođenja bjehu pripravljeni.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (33, 28, 14, 'Postavih te kao raskriljena keruba zaštitnika: bio si na svetoj gori Božjoj, hodio si posred ognjena kamenja.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (33, 28, 15, 'Savršen bješe na putima svojim od dana svojega rođenja dok ti se u srcu ne zače opačina.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (33, 28, 16, 'Obilno trgujući, napuni se nasiljem i sagriješi. Zato te zbacih s gore Božje, istrgoh te, kerube zaštitniče, isred ognjenoga kamenja.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (33, 28, 17, 'Srce ti se uzoholi zbog ljepote tvoje, mudrost svoju odnemari zbog svojega blaga! Na zemlju te bacih i predah te zemaljskim kraljevima da te prezirno gledaju.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (33, 28, 18, 'Mnoštvom svog bezakonja, nepoštenim trgovanjem oskvrnu svoja svetišta! Pustih oganj posred tebe da te proždre. Pretvorih te na zemlji u pepeo na oči onih što te motre.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (33, 28, 19, 'Svi koji te poznaju među narodima zgroziše se nad tobom! Jer ti strašilo posta, nestade zauvijek.\'\"');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (33, 28, 20, 'I dođe mi riječ Jahvina:');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (33, 28, 21, '\"Sine čovječji, okreni lice k Sidonu, prorokuj protiv njega.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (33, 28, 22, 'Reci: \'Ovako govori Jahve Gospod: Evo me protiv tebe, Sidone, proslavit ću se usred tebe! I znat će se da sam ja Jahve kada nad njim sud izvršim i svetost svoju pokažem u njemu.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (33, 28, 23, 'I poslat ću na nj kugu i krv po ulicama njegovim; i mrtvi će posred njega padati od mača, koji ti odasvud prijeti, i znat će se tada da sam ja Jahve.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (33, 28, 24, 'I više neće biti domu Izraelovu trna što ranjava nit\' žaoke što razdire među svima uokolo koji ga preziru! I znat će se da sam ja Jahve!\'\"');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (33, 28, 25, 'Ovako govori Jahve Gospod: \"A kad skupim sav dom Izraelov između naroda po kojima su razasuti, očitovat ću u njima svoju svetost pred očima narodÄa. I nastanit će se u svojoj zemlji što je dadoh sluzi svome Jakovu.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (33, 28, 26, 'I u njoj će živjeti u miru, gradit će domove i saditi vinograde. Živjet će u pouzdanju dok budem izvršivao svoj sud nad svima koji ih naokolo prezirahu. I znat će da sam ja Jahve, Bog njihov.\"');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (33, 29, 1, 'Godine desete, desetoga mjeseca, dvanaestoga dana, dođe mi riječ Jahvina:');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (33, 29, 2, '\"Sine čovječji, okreni lice faraonu, kralju egipatskom, i prorokuj protiv njega i protiv sveg Egipta.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (33, 29, 3, 'Govori i reci: \'Ovako govori Jahve Gospod: Evo me protiv tebe, faraone, kralju egipatski, golemi krokodile što ležiš usred rijeka svojih. Ti reče: \'Rijeke su moje, sebi sam ih načinio.\'');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (33, 29, 4, 'I zato ću ti kuke zarit\' u gubicu i sve ribe rijeka tvojih zalijepiti na krljušti tvoje. Izvući ću te isred rijeka tvojih sa svim ribama rijeka tvojih zalijepljenim na tvoje krljušti.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (33, 29, 5, 'Bacit ću u pustinju tebe i sve ribe iz rijeka tvojih. Na tlo ćeš poljsko pasti, nitko te neće podić\' ni sahraniti, zvijerima zemaljskim i nebeskim pticama dat ću te za hranu!');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (33, 29, 6, 'I znat će svi stanovnici Egipta da sam ja Jahve. Jer ti bješe trska za oslonac domu Izraelovu!');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (33, 29, 7, 'Kad te u ruku uhvatiše, ti se slomi i rane im otvori; a kad se na te osloniše, ti prepuče i bedra im sva izrani.\'');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (33, 29, 8, 'Stog ovako govori Jahve Gospod: \'Gle, dovest ću mač svoj na te, istrijebit ću iz tebe i ljude i stoku!');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (33, 29, 9, 'Sva će zemlja egipatska pustoš biti i razvalina, i oni će znati da sam ja Jahve!\' Jer ti reče: \'Rijeka je moja, sebi je načinih.\'');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (33, 29, 10, '\'Zato evo me na te i na rijeke tvoje da pretvorim zemlju egipatsku u pustinju i pustoš od Migdola do Sevana i do granice etiopske!');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (33, 29, 11, 'Neće njome više prolaziti noga ljudska ni noga životinjska, ostat će nenaseljena četrdeset godina.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (33, 29, 12, 'Od zemlje ću egipatske načiniti pustoš sred zemalja opustošenih, a gradovi njezini bit će četrdeset godina ruševine među razvaljenim gradovima. I raspršit ću Egipćane među narode i rasijat ću ih po zemljama.\'');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (33, 29, 13, 'Jer, ovako govori Jahve Gospod: \'Kad mine četrdeset godina, sakupit ću opet sve Egipćane između naroda kamo bijahu raspršeni.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (33, 29, 14, 'Vratit ću izgnanike egipatske, vratit ću ih opet u zemlju Patros, domovinu njihovu, da osnuju ondje slabo kraljevstvo.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (33, 29, 15, 'Ono će biti najmanje od svih kraljevstava, da se više nikad ne digne nad druge narode. Smanjit ću ga da više nikad ne podjarmi drugih naroda');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (33, 29, 16, 'i da više ne bude uzdanje domu Izraelovu. Nek\' mu u pamet doziva grijehe koje bijaše počinio okrećući se za njima. I oni će spoznati da sam ja Jahve.\'\"');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (33, 29, 17, 'Godine dvadeset i sedme, prvoga dana prvoga mjeseca, dođe mi riječ Jahvina:');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (33, 29, 18, '\"Sine čovječji, kralj babilonski Nabukodonozor krenu s vojskom na velik pohod protiv grada Tira. I svaka glava ogolje i svako se rame odadrije. Ali ni on ni vojska mu ne imahu nikakve dobiti od toga što krenuše na Tir.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (33, 29, 19, 'Stoga ovako govori Jahve Gospod: \'Gle, predat ću Nabukodonozoru, kralju babilonskome, zemlju egipatsku. Odnijet će joj blago, nagrabiti plijena i opljačkati je. To će biti plaća vojsci njegovoj.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (33, 29, 20, 'Za trud što na Tir krenu dat ću mu svu zemlju egipatsku, jer za me bijaše radio\' - riječ je Jahve Gospoda.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (33, 29, 21, '\'U onaj ću dan učiniti da izraste rog domu Izraelovu, a tebi ću usta otvoriti među njima. I znat će da sam ja Jahve.\'\"');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (33, 30, 1, 'I dođe mi riječ Jahvina:');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (33, 30, 2, '\"Sine čovječji, prorokuj i reci: \'Ovako govori Jahve Gospod: Kukajte: \'Jao dana!\'');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (33, 30, 3, 'Jer se bliži dan, bliži se dan Jahvin! Dan oblačan, vrijeme narodima određeno.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (33, 30, 4, 'I mač će ući u Egipat, a strah će ophrvati Etiopiju kad mrtvi stanu padati po Egiptu i kad se razgrabi njegovo blago te kad mu temelje sve sruše.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (33, 30, 5, 'Kuš, Put i Lud, sva Arabija i Libija, i sinovi zemlje Krete s njima od mača će izginuti\'!');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (33, 30, 6, 'Ovako govori Jahve Gospod: \'Past će koji podupiru Egipat i srozat će se ponos njegove moći. Od Migdola do Sevana sve će u njemu od mača pasti - riječ je Jahve Gospoda.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (33, 30, 7, 'On će biti pustoš među opustošenim zemljama, a njegovi gradovi ruševine među razrušenim gradovima.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (33, 30, 8, 'I znat će da sam ja Jahve kad zapalim svoj oganj u Egiptu i zatrem sve pomagače njegove.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (33, 30, 9, 'U onaj će dan glasnici od mene na lađama isploviti da zastraše bezbrižnu Etiopiju. I strah će je ophrvati u dan egipatski. Jer, evo, bliži se!\'');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (33, 30, 10, 'Ovako govori Jahve Gospod: \'Uništit ću mnoštvo egipatsko rukom Nabukodonozora, kralja babilonskoga!');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (33, 30, 11, 'On i njegov narod s njime - najokrutniji među narodima - bit će dovedeni da zemlju zatru. I oni će isukati mač na Egipat i svu će mu zemlju truplima ispuniti.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (33, 30, 12, 'A ja ću isušiti rijeke i zemlju predati u ruke silnicima, opustošit ću zemlju i što je u njoj - rukom tuđinaca. Ja, Jahve, rekoh!\'');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (33, 30, 13, 'Ovako govori Jahve Gospod: \'Razorit ću kumire i ništavila istrijebiti iz Memfisa, i neće više biti knezova u egipatskoj zemlji, a strah ću posijati u zemlji egipatskoj.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (33, 30, 14, 'Opustošit ću Patros, zapaliti Soan, izvršiti sud na Tebi.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (33, 30, 15, 'Iskalit ću gnjev nad Sinom, tvrđom egipatskom, istrijebit ću mnoštvo u Tebi.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (33, 30, 16, 'Zapalit ću oganj pod Egiptom: Sin će uzdrhtati od strave, Teba će biti osvojena, a Memfis u tjeskobi dan za danom.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (33, 30, 17, 'Mladići Heliopola i Pi-Beseta od mača će pasti. A oni će biti odvedeni u ropstvo!');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (33, 30, 18, 'Nad Tafnisom pomrčat će dan kad ondje slomim jaram egipatski i kad se dokonča ponos moći u njemu! Nad njim će se nadviti oblak, i njegove će kćeri biti odvedene u ropstvo!');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (33, 30, 19, 'Tako ću izvršiti sud nad Egiptom, i znat će da sam ja Jahve.\'\"');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (33, 30, 20, 'Godine jedanaeste, prvoga mjeseca, sedmoga dana dođe mi riječ Jahvina:');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (33, 30, 21, '\"Sine čovječji, gle, slomih mišicu faraonu, kralju egipatskom! I evo, nisu je ni povili: nisu metnuli lijekove niti su je povojima obavili da je okrijepe kako bi se opet mogla prihvatiti mača.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (33, 30, 22, 'Stoga ovako govori Jahve Gospod: \'Evo me protiv faraona, kralja egipatskoga, da mu slomim obje ruke, i zdravu i slomljenu, i da mu mač izbijem iz ruke!');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (33, 30, 23, 'Razagnat ću Egipćane među narode i rasijati ih po zemljama!');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (33, 30, 24, 'Ojačat ću ruke kralju babilonskom i mač ću svoj staviti u njegovu ruku; a faraonu ću slomiti ruke te će stenjati pred neprijateljem kao ranjenik.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (33, 30, 25, 'Da, ojačat ću ruke kralju babilonskom, a ruke će faraonove klonuti. I znat će se da sam ja Jahve kad metnem mač svoj u ruke kralju babilonskom i on ga zavitla nad zemljom egipatskom.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (33, 30, 26, 'Raspršit ću Egipćane među narode i rasijati ih po zemljama. I znat će da sam ja Jahve.\'\"');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (33, 31, 1, 'Jedanaeste godine, trećega mjeseca, prvoga dana, dođe mi riječ Jahvina:');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (33, 31, 2, '\"Sine čovječji, kaži faraonu, kralju egipatskom, i mnoštvu njegovu: \'Na koga naličiš veličinom svojom?');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (33, 31, 3, 'Usporedit ću te, evo, s cedrom libanonskim, lijepih grana, gusta lišća i debla visoka: vrh mu do oblaka seže.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (33, 31, 4, 'Voda ga othrani i uzvisi bezdan; rijekama mu svojim nasad oblijevaše, rukave svoje slaše k svem drveću poljskom.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (33, 31, 5, 'I zato rastom on nadvisi sve poljsko drveće. Grane mu se namnožiše, hvoje mu se razgranaše od obilne vode što mu dotjecaše;');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (33, 31, 6, 'ptice mu nebeske na granama gnijezda savijahu. Ispod hvoja njegovih legoše se divlje zvijeri. A u hladu njegovu svi veliki narodi sjeđahu.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (33, 31, 7, 'Lijep on bijaše veličinom i širinom svojih grana; do dubokih voda žilje mu sezaše!');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (33, 31, 8, 'Ne bijahu mu ravni ni cedrovi u vrtu Božjem, ni čempresi se ne mogahu usporediti s granama njegovim, a platane ni kao hvoje njegove ne bijahu! Nijedno stablo u vrtu Božjem ne bješe mu po ljepoti ravno.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (33, 31, 9, 'Ukrasih ga mnoštvom grana, i zaviđaše mu sve edensko drveće u vrtu Božjem.\'');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (33, 31, 10, 'Stoga ovako govori Jahve Gospod: \'Jer se s rasta uzoholio što mu vrh do oblaka sezaše i srce mu visina zanese,');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (33, 31, 11, 'predadoh ga u ruke najmoćnijemu od svih naroda da učini s njime po zloći njegovoj, i odbacih ga.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (33, 31, 12, 'Tuđinci, najokrutniji od naroda, posjekoše ga i oboriše, grane mu padahu po gorama i svim dolinama, hvoje mu se po svim uvalama polomiše, svi se narodi zemlje od njegova hlada udaljiše, ostaviše ga!');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (33, 31, 13, 'Na njegovo oboreno stablo sve ptice nebeske sletješe! Među njegovim se granama sve divlje zvijeri nastaniše!');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (33, 31, 14, 'Da se rastom svojim nijedno stablo pokraj vode više ne uzvisi i da vrh svoj među oblake ne uzdigne! I da se nijedno stablo koje pije vode u visinu svoju ne uzdaje! Jer su svi predani smrti, bačeni u podzemne krajeve, posred sinova ljudskih, s onima što slaze u jamu!\'');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (33, 31, 15, 'Ovako govori Jahve Gospod: \'U dan kad on siđe u Podzemlje, u znak žalosti, zatvorih nad njim ponor i zaustavih rijeke njegove. I velike vode presahnuše te sav Libanon zbog njega u tugu zaogrnuh i sve se poljsko drveće zbog njega osuši!');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (33, 31, 16, 'Gromotom pada njegova potresoh narode kad ga strmoglavih u Podzemlje s onima što u jamu siđoše! I u podzemnom se kraju utješi sve drveće edensko, najizabranije i najljepše u Libanonu, sve što je vodu ispijalo.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (33, 31, 17, 'I ono, mišica njegova, i oni među narodima koji u hladu njegovu sjeđahu, siđoše s njim u Podzemlje, k onima što mačem bijahu probodeni.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (33, 31, 18, 'Na koga, dakle, među drvećem edenskim, naličiš svojom moći, slavom i veličinom? A sad si s njima oboren u podzemni kraj i s neobrezanima ležiš među onima što mačem bijahu probodeni. To je faraon i sve njegovo mnoštvo\' - riječ je Jahve Gospoda.\"');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (33, 32, 1, 'Godine dvanaeste, dvanaestoga mjeseca, prvoga dana, dođe mi riječ Jahvina:');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (33, 32, 2, '\"Sine čovječji, zaplači nad faraonom, kraljem egipatskim, i kaži mu: \'Laviću naroda, propao si! Ti bješe kao krokodil u vodi, bučio si u rijekama svojim, nogama si vodu mutio, valove joj podizao!\'');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (33, 32, 3, 'Ovako govori Jahve Gospod: \'Gle, razapet ću mrežu nad tobom sa skupom mnogih naroda: oni će te u mojoj mreži izvući.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (33, 32, 4, 'Ostavit će te na zemlji, tresnuti tobom o tlo. Sve ptice nebeske na te ću pustiti i zvijeri zemaljske tobom ću nahraniti!');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (33, 32, 5, 'Meso ću ti razbacat\' po gorama, doline ću prekriti strvinom tvojom.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (33, 32, 6, 'Istekom iz tebe zemlju ću napojiti, krvlju tvojom po gorama, i korita riječna njome napuniti.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (33, 32, 7, 'A kada te utrnem, nebesa ću potamniti i zvijezde na njima ugasiti! Oblakom ću sunce zastrijeti, i mjesec svjetlošću neće svijetliti.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (33, 32, 8, 'Sva ću svjetlila na nebu zbog tebe utrnuti i mrak ću nad zemljom razastrijeti!\' - riječ je Jahve Gospoda.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (33, 32, 9, '\'Ucvilit ću srca mnogih naroda kad izgnanike tvoje odvedem u zemlje tebi nepoznate.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (33, 32, 10, 'Narode će mnoge strava uhvatiti, a njihovi će se kraljevi nad tobom užasnuti njima naočigled. I na dan pada tvojega svatko će za svoj život neprestano strepiti.\'');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (33, 32, 11, 'Jer ovako govori Jahve Gospod: \'Mač kralja babilonskoga na te će se spustiti.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (33, 32, 12, 'Tvoje ću mnoštvo pobiti mačevima junaka, najljući od svih naroda opustošit će ponos Egipta i sve mnoštvo njegovo zatrijeti.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (33, 32, 13, 'Svu ću stoku njegovu uništiti pokraj voda obilnih. Ljudska ih noga više neće gaziti niti će ih životinjski papak mutiti.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (33, 32, 14, 'Onda ću im vode opet stišati i učinit ću da im rijeke kao ulje teku!\' - riječ je Jahve Gospoda.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (33, 32, 15, '\'Kad zemlju egipatsku opustošim, kad bude opljačkano što je na njoj, kad udarim sve žitelje njezine, znat će da sam ja Jahve.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (33, 32, 16, 'Tužaljka je to koja će se naricati. Naricat će je kćeri naroda. Naricat će je nad Egiptom i nad svim njegovim mnoštvom\' - riječ je Jahve Gospoda.\"');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (33, 32, 17, 'Godine dvanaeste, prvoga mjeseca, petnaestoga dana, dođe mi riječ Jahvina:');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (33, 32, 18, '\"Sine čovječji, nariči za egipatskim mnoštvom, gurni ga, njega i kćeri naroda slavnih, u podzemni kraj, k onima što siđoše u jamu.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (33, 32, 19, 'Od koga si bolji? Siđi i počini s neobrezanima.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (33, 32, 20, 'Oni će pasti među one što ih mač pokosi. Ležaj će dobiti sa svim mnoštvom.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (33, 32, 21, 'Najhrabriji junaci govorit će mu iz srca Podzemlja: \'Ti i pomoćnici tvoji siđite i počinite s neobrezanima, mačem pokošenima!\'');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (33, 32, 22, 'Ondje je i Asirac i sva njegova gomila oko groba njegova - svi pobijeni, mačem pokošeni.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (33, 32, 23, 'Grobovi im leže na dnu jame i sva mu je gomila oko grobova njegova - svi, nekoć užas u zemlji živih, sada pobijeni, mačem pokošeni.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (33, 32, 24, 'Ondje Elam i sve mnoštvo njegovo oko groba njegova - svi pobijeni, mačem pokošeni, neobrezani u podzemni kraj mrtvih siđoše: nekoć užas u zemlji živih, snose sad sramotu svoju s onima što u jamu siđoše.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (33, 32, 25, 'Usred pobijenih ležaj smjestiše njemu i mnoštvu oko groba njegova - sve neobrezani, mačem probodeni: nekoć užas u zemlji živih, snose sad sramotu svoju s onima što u jamu siđoše, među pobijene položeni.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (33, 32, 26, 'Ondje je Mešek i Tubal i sve mnoštvo njegovo, s grobovima oko groba njegova - svi neobrezani, mačem probodeni, nekoć užas u zemlji živih.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (33, 32, 27, 'Ne leže s junacima davno palima, u Podzemlje siđoše s oružjem, s mačem pod glavom i sa štitom na kostima, jer bijahu užas junacima u zemlji živih.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (33, 32, 28, 'I ti ćeš ležati usred neobrezanih, mačem pokošenih.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (33, 32, 29, 'Ondje je Edom i svi njegovi kraljevi i knezovi: unatoč svojemu junaštvu, i oni leže zajedno s onima što su mačem pokošeni, s neobrezanima, s onima koji u jamu siđoše.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (33, 32, 30, 'Ondje su knezovi sjevera i svi Sidonci, i oni siđoše među probodene. Unatoč užasu svojega junaštva, leže neobrezani, s mačem probodenima, snoseći svoju sramotu s onima što u jamu siđoše.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (33, 32, 31, 'Vidjet će ih faraon i utješit će se zbog svog mnoštva - faraon i sva vojska njegova mačem pokošena, riječ je Jahve Gospoda!');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (33, 32, 32, 'Jer je zadavao strah u zemlji živih, faraon i sve mnoštvo njegovo leže s neobrezanima, s mačem pokošenima - riječ je Jahve Gospoda.\"');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (33, 33, 1, 'Dođe mi riječ Jahvina:');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (33, 33, 2, '\"Sine čovječji, govori sinovima naroda svojega! Reci: \'Ako ja na neku zemlju dovedem mač, a narod te zemlje uzme jednoga između sebe i postavi ga za stražara,');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (33, 33, 3, 'a on - videći da mač dolazi na zemlju - zatrubi u rog i opomene sav narod:');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (33, 33, 4, 'ako se tada onaj koji čuje glas roga ne da opomenuti te mač dođe i pogubi ga - krv njegova past će na glavu njegovu:');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (33, 33, 5, 'jer, čuo je glas roga, ali se ne dade opomenuti - krv njegova past će na njega. Da se dao opomenuti, spasio bi život.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (33, 33, 6, 'A opet, ako stražar - videći da mač dolazi na zemlju - ne zatrubi u rog i ne opomene narod te mač dođe i pogubi koga od njih: taj je, doduše, poginuo zbog svoga grijeha, ali ću ja krv njegovu tražiti iz stražarove ruke.\'');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (33, 33, 7, 'I tebe sam, sine čovječji, postavio za stražara domu Izraelovu: kad čuješ riječ iz mojih usta, opomeni ih u moje ime.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (33, 33, 8, 'Reknem li bezbožniku: \'Bezbožniče, umrijet ćeš!\' - a ti ne progovoriš i ne opomeneš bezbožnika da se vrati od svojega zloga puta, bezbožnik će umrijeti zbog svojega grijeha, ali krv njegovu tražit ću iz tvoje ruke.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (33, 33, 9, 'Ali ako bezbožnika opomeneš da se vrati od svojega zloga puta, a on se ne vrati sa svojega puta: on će umrijeti zbog svojega grijeha, a ti si spasio život svoj.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (33, 33, 10, 'Sine čovječji, reci domu Izraelovu: Vi govorite: \'Prijestupi i grijesi naši pritišću nas i zbog njih propadamo! I da još živimo?\'');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (33, 33, 11, 'Odgovori im: \'Života mi moga - riječ je Jahve Gospoda - nije meni do smrti bezbožnikove, nego da se odvrati od zloga puta svojega i da živi! Obratite se, dakle, obratite od zloga puta svojega! Zašto da umrete, dome Izraelov!\'');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (33, 33, 12, 'Sine čovječji, reci sinovima naroda svoga: \'Pravednika neće izbaviti pravednost njegova u dan kad sagriješi niti će bezbožnik stradati zbog svoje bezbožnosti u dan kad se od nje odvrati, kao što ni pravednik neće moći ostati na životu u dan kad sagriješi.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (33, 33, 13, 'Reknem li ja prevedniku: \'Živjet ćeš!\' a on se pouzda u svoju pravednost i stane činiti nepravdu, zaboravit ću svu njegovu pravednost, i on će umrijeti zbog nepravde što je počini!');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (33, 33, 14, 'A reknem li bezbožniku: \'Umrijet ćeš!\' a on se odvrati od grijeha svojega i stane raditi po zakonu i pravdi,');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (33, 33, 15, 'vrati zalog, plati oteto i stane živjeti po zakonima života, ne čineći bezakonja - živjet će, neće umrijeti!');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (33, 33, 16, 'I svi grijesi njegovi što ih bijaše počinio bit će mu zaboravljeni. Radi po zakonu i pravdi, živjet će!\'');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (33, 33, 17, 'Ali sinovi naroda tvoga govore: \'Jahvin put nije pravedan!\' Njihov put nije pravedan!');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (33, 33, 18, 'Ako se pravednik odvrati od svoje pravednosti i stane činiti nepravdu, on će stoga umrijeti.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (33, 33, 19, 'A ako se bezbožnik odvrati od svoje bezbožnosti i stane raditi po zakonu i pravdi, on će zbog toga živjeti.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (33, 33, 20, 'A vi velite: \'Jahvin put nije pravedan!\' Svakome ću od vas suditi prema putovima njegovim, dome Izraelov!\"');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (33, 33, 21, 'Godine dvanaeste, desetoga mjeseca, petoga dana našeg izgnanstva, dođe k meni bjegunac iz Jeruzalema i reče: \"Pade grad!\"');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (33, 33, 22, 'Ruka se Jahvina spustila na me uveče, prije dolaska toga bjegunca, i otvorila mi usta prije negoli on dođe k meni ujutro! Otvoriše mi se, dakle, usta i ja više ne bijah nijem.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (33, 33, 23, 'I dođe mi riječ Jahvina:');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (33, 33, 24, '\"Sine čovječji, oni koji žive u ovim ruševinama zemlje Izraelove govore: \'Jedan bijaše Abraham i baštini ovu zemlju, a nas je mnogo - nama je zemlja dana u posjed!\'');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (33, 33, 25, 'Stoga im reci: \'Ovako govori Jahve Gospod: Vi blagujete po gorama, oči podižete kumirima svojim, krv prolijevate - i još da posjedujete ovu zemlju?');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (33, 33, 26, 'Na svoj se mač oslanjate, činite gadosti, oskvrnjujete ženu bližnjega - i još da posjedujete ovu zemlju?\'');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (33, 33, 27, 'Ovo im reci: \'Ovako govori Jahve Gospod: Života mi moga, oni koji su u ruševinama od mača će pasti; one koji su u polju dat ću zvijerima da ih proždru; a koji su u utvrdama i po pećinama od kuge će poginuti!');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (33, 33, 28, 'Tako ću zemlju ovu razoriti i opustošiti i nestat će zauvijek drskoga njezina ponosa. Opustjet će gore Izraelove i nitko više neće njima prolaziti.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (33, 33, 29, 'I znat će da sam ja Jahve kad zemlju njihovu razorim i opustošim zbog svih gadosti što ih počiniše.\'');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (33, 33, 30, 'A o tebi, sine čovječji, sinovi naroda tvoga kazuju uza zidove i na kućnim vratima i govore jedan drugom: \'Hajde da čujemo kakva je to riječ došla od Jahve!\'');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (33, 33, 31, 'I hrle k tebi kao na zbor narodni; i narod moj sjeda preda te i sluša tvoje riječi, ali ih ne izvršuje: naslađuju se njima u ustima, a srce im ide za nepravednim dobitkom.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (33, 33, 32, 'I gle, ti si za njih kao slatka pjesma uz glazbu otpjevana glasom umilnim: riječi ti slušaju, ali ih ne izvršuju.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (33, 33, 33, 'Ali kad sve ovo dođe - gle, već dolazi - znat će da prorok bijaše među njima!\"');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (33, 34, 1, 'I dođe mi riječ Jahvina:');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (33, 34, 2, '\"Sine čovječji, prorokuj protiv Izraelovih pastira, prorokuj im i reci: \'Ovako govori Jahve Gospod: Jao pastirima Izraelovim koji napasaju sami sebe! Ne moraju li pastiri napasati stado?');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (33, 34, 3, 'Mlijekom se hranite, vunom odijevate, ovnove tovne koljete, a stada ne pasete.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (33, 34, 4, 'Nemoćnih ne krijepite, bolesnih ne liječite, ranjenih ne povijate, zalutalih natrag ne dovodite, izgubljenih ne tražite, nego nasilno i okrutno njima gospodarite.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (33, 34, 5, 'I tako se ovce raspršiše nemajuć\' pastira, i raspršene postadoše plijen zvijerima.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (33, 34, 6, 'Ovce lutaju po svim gorama i visokim bregovima; po svoj su zemlji raspršene ovce moje i nitko za njih ne pita, nikoga nema da ih traži.\'');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (33, 34, 7, 'Zato, pastiri, čujte riječ Jahvinu:');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (33, 34, 8, '\'Tako mi života, riječ je Jahve Gospoda: zato što ovce moje postadoše plijen i hrana zvijerima, nemajuć\' pastira, dok pastiri moji ovaca mojih ne traže nego sami sebe pasu, a ne pasu stada mojega -');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (33, 34, 9, 'zato, pastiri, čujte riječ Jahvinu:');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (33, 34, 10, 'Ovako govori Jahve Gospod: \'Evo me na pastire! Ovce svoje tražit ću iz ruku njihovih i neću im dati da mi više stado pasu ni da sami sebe pasu: istrgnut ću ovce iz usta njihovih, neće im više biti hrana.\'');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (33, 34, 11, 'Jer ovako govori Jahve Gospod: \'Evo me, sam ću potražiti ovce svoje i sam ću ih pasti!');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (33, 34, 12, 'Kao što se pastir brine za ovce svoje kad se nađe uza stado raspršeno, i ja ću se pobrinuti za svoje ovce i skupit\' ih iz svih mjesta u koje se raspršiše u dan oblaka i mraka.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (33, 34, 13, 'Izvest ću ih iz naroda, skupit ću ih iz zemalja i dovesti ih u zemlju njihovu da ih pasem na gorama izraelskim, po svim dolinama i travnjacima.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (33, 34, 14, 'Past ću ih na izvrsnim pašama, ovčinjaci će im biti na visokim gorama izraelskim; ondje će počivati u dobrim ovčinjacima i past će na sočnim pašama, po gorama izraelskim.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (33, 34, 15, 'Sam ću pasti ovce svoje i sam ću im dati počinka - riječ je Jahve Gospoda.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (33, 34, 16, 'Potražit ću izgubljenu, dovesti natrag zalutalu, povit ću ranjenu i okrijepiti nemoćnu, bdjeti nad pretilom i jakom - past ću ih pravedno.\'');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (33, 34, 17, 'A vama, ovce moje, ovako govori Jahve Gospod: \'Evo me da sudim između ovce i ovce, između ovnova i jaraca!');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (33, 34, 18, 'Zar vam je malo pasti na dobroj paši te ostatak paše nogama gazite? Malo vam je piti bistru vodu te ostatak nogama mutite?');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (33, 34, 19, 'A moje ovce moraju pasti što vi nogama izgaziste, piti što vi nogama zamutiste.\'');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (33, 34, 20, 'Stoga ovako govori Jahve Gospod: \'Evo me da sudim između ovce pretile i mršave!');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (33, 34, 21, 'Jer bokovima i plećima, bodući rogovima, slabe ovce guraste dok ih ne izguraste.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (33, 34, 22, 'Ja ću izbaviti ovce svoje da više ne budu plijenom i sudit ću između ovce i ovce.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (33, 34, 23, 'Postavit ću im jednoga pastira koji će ih pasti, slugu svoga Davida: on će ih sam pasti i bit će im pastir,');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (33, 34, 24, 'a ja, Jahve, bit ću njihov Bog, i moj sluga David bit će im knez. Ja, Jahve, rekoh!');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (33, 34, 25, 'I sklopit ću s njima Savez mira i uklonit ću iz zemlje sve divlje zvijeri, i živjet će mirno u pustinji i spavati po šumama.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (33, 34, 26, 'Njih i sve oko brda svojega učinit ću blagoslovom i dat ću im na vrijeme kišu, i bit će to kiša blagoslova.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (33, 34, 27, 'I drveće će poljsko donositi plodove, a zemlja će dati rod svoj. I oni će mirno živjeti u svojoj zemlji i znat će da sam ja Jahve kad slomim palice jarma njihova i kad ih izbavim iz ruku onih što ih podjarmiše.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (33, 34, 28, 'I neće više biti plijenom narodima, i zvijeri ih više neće žderati, nego će mirno živjeti i nitko ih neće plašiti.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (33, 34, 29, 'I učinit ću da im probuja slavni nasad, i glad ih više neće zatirati, u zemlji više neće podnositi rug narodÄa.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (33, 34, 30, 'I znat će da sam ja, Jahve, Bog njihov, s njima i da su oni, dom Izraelov, narod moj - riječ je Jahve Gospoda.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (33, 34, 31, 'Vi, ovce moje, vi ste stado paše moje, a ja sam Bog vaš\' - riječ je Jahve Gospoda.\"');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (33, 35, 1, 'I dođe mi riječ Jahvina:');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (33, 35, 2, '\"Sine čovječji, okreni lice k Seirskoj gori i prorokuj protiv nje!');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (33, 35, 3, 'Reci joj: \'Ovako govori Jahve Gospod: Evo me na te, Goro seirska! Ruku ću podići na te i pretvoriti te u pustoš i pustinju.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (33, 35, 4, 'Gradove ću tvoje razvaliti i postat ćeš pustinjom. I znat ćeš da sam ja Jahve!');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (33, 35, 5, 'Vječnu si mržnju gojila i maču predavala sinove Izraelove kad bi ih nesreća pogodila i kad bi im kucnuo čas posljednjega grijeha.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (33, 35, 6, 'Zato, života mi moga - riječ je Jahve Gospoda - krvi ću te predati i krv će te progoniti: od krvi nisi prezala, krv će te progoniti!');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (33, 35, 7, 'Od Gore seirske učinit ću pustoš i pustinju, istrijebit ću iz nje polaznika i povratnika.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (33, 35, 8, 'Gore njezine napunit ću truplima: po tvojim brežuljcima, po tvojim dolinama i po tvojim uvalama padat će mačem pokošeni.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (33, 35, 9, 'Učinit ću od tebe vječnu pustinju, gradovi se tvoji neće napučiti. I znat ćete da sam ja Jahve!\'');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (33, 35, 10, 'Ti reče: \'Ova dva naroda i ove dvije zemlje bit će moji; mi ćemo ih zaposjesti, ako i jest Jahve bio ondje!\'');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (33, 35, 11, '\'Zato, života mi moga - riječ je Jahve Gospoda - postupit ću s tobom prema gnjevu i ljubomori s kojom ti postupi u svojoj mržnji s njima! Upoznat ćeš me po tome kako ću ti suditi!');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (33, 35, 12, 'I znat ćeš da sam ja, Jahve, čuo sve tvoje hule što ih izreče na gore Izraelove govoreći: \'Opustješe, nama su dane za hranu!\'');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (33, 35, 13, 'Razmetali ste se, protiv mene govorili i gomilali protiv mene riječi; čuo sam ja!\'');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (33, 35, 14, 'Ovako govori Jahve Gospod: \'Na radost sve zemlje, od tebe ću učiniti pustoš.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (33, 35, 15, 'Kako si se ti radovala što opustje baština doma Izraelova, tako ću učiniti s tobom: opustjet ćeš, Goro seirska, a s tobom i sav Edom! I znat će se da sam ja Jahve!\"');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (33, 36, 1, 'Sine čovječji, prorokuj gorama Izraelovim i reci: \"O gore Izraelove, čujte riječ Jahvinu:');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (33, 36, 2, 'Ovako govori Jahve Gospod: Neprijatelji vaši govore o vama: \'Ha! Ha! Visine vječne postat će naš posjed!\'');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (33, 36, 3, 'I zato prorokuj i reci: \'Ovako govori Jahve Gospod: Sa svih vas strana pustoše i plijene da budete posjed ostalim narodima i na jezike dođoste svjetini klevetničkoj.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (33, 36, 4, 'Zato, gore Izraelove, čujte riječ Jahvinu! Ovako govori Jahve Gospod gorama i brežuljcima, uvalama i dolinama, opustošenim razvalinama i napuštenim gradovima koji postadoše plijen i ruglo ostalim narodima uokolo -');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (33, 36, 5, 'ovako, dakle, govori Jahve Gospod: Zaista sam govorio o ognju ljubomore svoje protiv ostalih naroda, protiv sveg Edoma, koji s radošću u srcu i s mržnjom u duši sebi prisvoji u posjed zemlju moju da je oplijeni i opljačka.\'');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (33, 36, 6, 'Zato prorokuj o zemlji Izraelovoj! Reci gorama i brežuljcima, uvalama i dolinama: \'Ovako govori Jahve Gospod! Evo, govorim u ljubomori i jarosti jer moradoste podnositi rug naroda.\'');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (33, 36, 7, 'Zato ovako govori Jahve Gospod: \'Evo, dižem ruku i kunem se: narodi koji su oko vas snosit će sami svoju sramotu!');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (33, 36, 8, 'A vi, gore Izraelove, razgranajte se i donesite rod narodu koji će skoro doći.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (33, 36, 9, 'Jer, evo me k vama! K vama se okrenuh, i gajit ću vas i zasijati!');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (33, 36, 10, 'Razmnožit ću ljude po vama - sav dom Izraelov - gradove vam napučiti, razvaline vaše opet podići!');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (33, 36, 11, 'Razmnožit ću po vama ljude i stoku, oni će se namnožiti i naploditi - te ću vas napučiti kao nekoć i obasuti vas dobrima više nego prije! I znat ćete da sam ja Jahve!');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (33, 36, 12, 'Dovest ću k vama ljude, narod svoj, Izraela, i zaposjest će te i bit ćeš im baština i nećeš im više djecu otimati.\'\"');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (33, 36, 13, 'Ovako govori Jahve Gospod: \"A što se o tebi govori: \'Ti si zemlja koja ljude proždire i svojem narodu djecu otima\' -');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (33, 36, 14, 'ti više nećeš ljude proždirati ni narodu svome djece otimati - riječ je Jahve Gospoda.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (33, 36, 15, 'Ne dam da više slušaš rug pogana, ne dam da više budeš na sramotu narodima: nećeš više narodu svojem djece otimati\" - riječ je Jahve Gospoda.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (33, 36, 16, 'Dođe mi riječ Jahvina:');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (33, 36, 17, '\"Sine čovječji, kad dom Izraelov još življaše u svojoj zemlji, oskvrnu je svojim nedjelima i svojim putovima. Putovi njihovi bijahu preda mnom kao nečistoća žene nečiste.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (33, 36, 18, 'I zato na njih izlih gnjev svoj zbog krvi što je proliše i zbog kumira kojima je oskvrnuše.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (33, 36, 19, 'Rasprših ih među narode i rasijah po zemljama. Sudio sam im prema putovima i nedjelima njihovim.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (33, 36, 20, 'Ali u narodima među koje dođoše, među svim narodima u koje dospješe, oskvrnjivahu moje sveto ime, jer o njima se govorilo: \'To je Jahvin narod, a morade otići iz zemlje Jahvine!\'');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (33, 36, 21, 'I meni se sažali moje sveto ime što ga dom Izraelov obeščasti u narodima među koje dođe.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (33, 36, 22, 'Reci zato domu Izraelovu: \'Ovako govori Jahve Gospod: Što činim, ne činim radi vas, dome Izraelov, nego radi svetoga imena svojega, koje vi oskvrnuste među narodima u koje dođoste.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (33, 36, 23, 'Ja ću posvetiti ime svoje veliko koje vi oskvrnuste posred narodÄa u koje dođoste! I znat će narodi da sam ja Jahve - riječ je Jahve Gospoda - kad na vama, njima naočigled, pokažem svetost svoju.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (33, 36, 24, 'Tada ću vas sabrati iz svih naroda i skupiti iz svih zemalja, natrag vas dovesti u vašu zemlju.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (33, 36, 25, 'Poškropit ću vas vodom čistom da se očistite. Očistit ću vas od svih vaših nečistoća i od svih kumira vaših.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (33, 36, 26, 'Dat ću vam novo srce, nov duh udahnut ću u vas! Izvadit ću iz tijela vašega srce kameno i dat ću vam srce od mesa.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (33, 36, 27, 'Duh svoj udahnut ću u vas da hodite po mojim zakonima i da čuvate i vršite moje naredbe.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (33, 36, 28, 'I nastanit ćete se u zemlji koju dadoh vašim ocima, i bit ćete moj narod, a ja ću biti vaš Bog.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (33, 36, 29, 'Izbavit ću vas od svih vaših nečistoća i dozvat ću žito i umnožiti ga, i nikad vas više neću izvrći gladi.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (33, 36, 30, 'Umnožit ću plod drveća i rod njiva da ne podnosite više zbog gladi sramotu među narodima.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (33, 36, 31, 'I tada ćete se spomenuti zlih putova i nedjela svojih, i sami ćete sebe omrznuti zbog bezakonja i gadosti svojih.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (33, 36, 32, 'A što činim, znajte dobro, ne činim radi vas - riječ je Jahve Gospoda! Postidite se i posramite zbog putova svojih, dome Izraelov!\'');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (33, 36, 33, 'Ovako govori Jahve Gospod: \'A kad vas očistim od svih bezakonja vaših, napučit ću opet vaše gradove i sagraditi razvaline;');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (33, 36, 34, 'opustjela zemlja, nekoć pustinja naočigled svakom prolazniku, bit će opet obrađena.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (33, 36, 35, 'Tada će se reći: \'Evo zemlje što bijaše pusta, a postade kao vrt edenski! Gle gradova što bijahu pusti, same razvaline i ruševine, a sada su utvrđeni i napučeni!\'');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (33, 36, 36, 'I narodi oko vas koji preostanu znat će da ja, Jahve, razvaljeno opet gradim, i što bi opustošeno, opet sadim. Ja, Jahve, rekoh i učinit ću!\'');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (33, 36, 37, 'Ovako govori Jahve Gospod: Još će ovo moliti dom Izraelov: da im ljudstvo namnožim kao stada.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (33, 36, 38, 'Kao svetim stadima, kao stadima blagdanskih dana u Jeruzalemu, gradovi, nekoć razvaline, napučit će se ljudstvom. I znat će da sam ja Jahve.\"');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (33, 37, 1, 'I spusti se na me ruka Jahvina i Jahve me u svojem duhu izvede i postavi usred doline pune kostiju.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (33, 37, 2, 'Provede me kroz njih, svuda oko njih, i gle, bijaše ih u dolini veoma mnogo i bijahu sasvim suhe!');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (33, 37, 3, 'Reče mi: \"Sine čovječji, mogu li ove kosti oživjeti?\" Ja odgovorih: \"Jahve Gospode, to samo ti znaš!\"');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (33, 37, 4, 'Tad mi reče: \"Prorokuj ovim kostima i reci im: \'O suhe kosti, čujte riječ Jahvinu!\'');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (33, 37, 5, 'Ovako govori Jahve Gospod ovim kostima: \'Evo, duh ću svoj udahnuti u vas i oživjet ćete!');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (33, 37, 6, 'Žilama ću vas ispreplesti, mesom obložiti, kožom vas obaviti i duh svoj udahnuti u vas i oživjet ćete - i znat ćete da sam ja Jahve!\'\"');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (33, 37, 7, 'I ja stadoh prorokovati kao što mi bješe zapovjeđeno. I dok sam prorokovao, nastade šuškanje i pomicanje i kosti se stadoše pribirati.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (33, 37, 8, 'Pogledah, i gle, po njima narasle žile i meso; kožom se presvukoše, ali duha još ne bijaše u njima.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (33, 37, 9, 'I reče mi: \"Prorokuj duhu, sine čovječji, prorokuj i reci: \'Ovako govori Jahve Gospod: Od sva četiri vjetra dođi, duše, i dahni u ova trupla da ožive!\'\"');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (33, 37, 10, 'I stadoh prorokovati kao što mi zapovjedi, i duh uđe u njih i oživješe i stadoše na noge - vojska vrlo, vrlo velika.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (33, 37, 11, 'Reče mi: \"Sine čovječji, te kosti - to je sav dom Izraelov. Evo, oni vele: \'Usahnuše nam kosti i propade nam nada, pogibosmo!\'');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (33, 37, 12, 'Zato prorokuj i reci im. \'Ovako govori Jahve Gospod: Ja ću otvoriti vaše grobove, izvesti vas iz vaših grobova, narode moj, i odvesti vas u zemlju Izraelovu!');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (33, 37, 13, 'I znat ćete da sam ja Jahve kad otvorim grobove vaše i kad vas izvedem iz vaših grobova, moj narode!');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (33, 37, 14, 'I duh svoj udahnut ću u vas da oživite, i dovest ću vas u vašu zemlju, i znat ćete da ja, Jahve govorim i činim\' - riječ je Jahve Gospoda.\"');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (33, 37, 15, 'I dođe mi riječ Jahvina:');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (33, 37, 16, '\"Sine čovječji, uzmi drvo i napiši na njemu: \'Juda i sinovi Izraelovi, njegovi saveznici!\' Onda uzmi drugo drvo i napiši na njemu: \'Josip - drvo Efrajimovo - i sav dom Izraelov, njegov saveznik.\'');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (33, 37, 17, 'I sastavi ih u jedno drvo da budu kao jedno u tvojoj ruci!');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (33, 37, 18, 'A kad te sinovi tvojega naroda zapitaju: \'Hoćeš li nam objasniti što to znači?\' -');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (33, 37, 19, 'reci im: \'Ovako govori Jahve Gospod: Evo, uzet ću drvo Josipovo, što je u ruci Efrajimovoj, drvo Josipovo i Izraelovih plemena, njegovih saveznika, i sastavit ću ga s drvetom Judinim te ću od njih načiniti jedno; oba će biti jedno u mojoj ruci.\'');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (33, 37, 20, 'Oba drveta na koja to napišeš neka ti budu u ruci, njima naočigled.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (33, 37, 21, 'I reci im: \'Ovako govori Jahve Gospod: Evo, skupit ću sinove Izraelove iz naroda u koje dođoše, skupit ću ih odasvud i odvesti ih u zemlju njihovu.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (33, 37, 22, 'I načinit ću od njih jedan narod u zemlji, u gorama Izraelovim, i bit će im svima jedan kralj, i oni više neće biti dva naroda i neće više biti razdijeljeni na dva kraljevstva.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (33, 37, 23, 'I neće se više kaljati svojim kumirima, ni svojim grozotama, ni opačinama. Izbavit ću ih od svih njihovih nevjera kojima zgriješiše i očistit ću ih, i oni će biti moj narod, a ja njihov Bog.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (33, 37, 24, 'I sluga moj David bit će im kralj i svima će im biti jedan pastir. Živjet će po mojim zakonima, čuvajući i vršeći moje naredbe.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (33, 37, 25, 'Boravit će u zemlji koju dadoh sluzi svome Jakovu, u kojoj življahu oci vaši: u njoj će stanovati oni i njihovi sinovi, i sinovi sinova njihovih dovijeka. I moj sluga David bit će im knez dovijeka.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (33, 37, 26, 'Sklopit ću s njima savez mira; bit će to Savez vječan s njima. Utvrdit ću ih i razmnožiti i postavit ću Svetište svoje zauvijek među njih.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (33, 37, 27, 'Moj će Šator biti među njima i ja ću biti Bog njihov, a oni narod moj!');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (33, 37, 28, 'I kad Svetište moje bude zauvijek među njima, znat će svi narodi da sam ja Jahve, koji posvećujem Izraela.\'\"');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (33, 38, 1, 'I dođe mi riječ Jahvina:');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (33, 38, 2, '\"Sine čovječji, okreni lice ka Gogu, u zemlji Magogu, velikom knezu Mešeka i Tubala, prorokuj protiv njega.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (33, 38, 3, 'Reci: \'Ovako govori Jahve Gospod: Evo me na te, Gože, veliki kneže Mešeka i Tubala!');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (33, 38, 4, 'Namamit ću te i metnut ću ti žvale u čeljusti, izvest ću tebe i svu tvoju vojsku - konje i konjanike, silno mnoštvo u potpunoj opremi - sve u oklopima i sa štitovima, sve vične maču.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (33, 38, 5, 'S njima je i Perzija, Etiopija i Put - svi sa štitovima i pod kacigama;');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (33, 38, 6, 'zatim Gomer i sve čete njegove, Bet Togarma s krajnjega sjevera i sve čete njezine - silan narod s tobom!');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (33, 38, 7, 'Dobro se spremi ti i sve mnoštvo što se oko tebe skupilo i stani mu na čelo!');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (33, 38, 8, 'Poslije mnogo dana dobit ćeš zapovijed; poslije mnogo godina navalit ćeš na zemlju, izbavljenu od mača i skupljenu iz mojih naroda, na gore Izraelove, nekoć zadugo puste: otkako ih izvedoh iz naroda, svi spokojno žive.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (33, 38, 9, 'Dići ćeš se, doći kao nevrijeme, kao oblak što prekrije zemlju, ti i tvoje čete, a s vama sila naroda!\'');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (33, 38, 10, 'Ovako govori Jahve Gospod: \'U onaj će ti se dan misli rojiti u srcu i skovat ćeš zao naum.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (33, 38, 11, 'Reći ćeš: \'Hajde da se dignem na zemlju nebranjenu, da navalim na miran narod koji spokojno živi bez zidina i bez prijevornica i bez vrata:');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (33, 38, 12, 'pa da se plijena naplijenim i pljačke napljačkam - da ruku stavim na razvaline opet napučene i na narod iz narÄodÄa sakupljen, koji se bavi stadima i imanjem i živi u središtu zemlje.\'');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (33, 38, 13, 'Šeba, Dedan i trgovci taršiški i svi njihovi lavići pitat će te: \'Zar zato dolaziš plijeniti? I zar si radi pljačke toliku gomilu skupio da odneseš srebro i zlato, da otmeš stoku i imanje i da se plijena velikoga naplijeniš?\'');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (33, 38, 14, 'Zato prorokuj, sine čovječji, i reci Gogu: \'Ovako govori Jahve Gospod: U onaj dan kad narod moj izraelski bude spokojno živio, ti ćeš se podići!');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (33, 38, 15, 'Doći ćeš iz svoga sjedišta, s krajnjega sjevera, ti i s tobom mnogo naroda, sve samih konjanika, silno mnoštvo, golema vojska.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (33, 38, 16, 'Navalit ćeš na Izraela, narod moj, kao oblak kad pokrije zemlju. U posljednje dane dovest ću te na svoju zemlju da me narodi upoznaju, kad na tebi, Gože, njima naočigled, pokažem svetost svoju.\'');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (33, 38, 17, 'Ovako govori Jahve Gospod: \'Nisi li ti onaj o kome sam govorio, u davne dane, preko slugu svojih, proroka Izraelovih, koji u ono vrijeme prorokovaše da ću te na njih dovesti?');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (33, 38, 18, 'U onaj dan kad Gog navali na zemlju Izraelovu - riječ je Jahve Gospoda - gnjev će mi iz nosa planuti.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (33, 38, 19, 'U ljubomori svojoj i u ognju jarosti svoje odlučih: U onaj dan bit će silan potres u zemlji Izraelovoj.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (33, 38, 20, 'I trest će se poda mnom ribe morske i ptice nebeske, poljske zvijeri i gmazovi što gmižu po zemlji i svi ljudi što žive na njoj. Planine će se razvaliti, vrleti popadati i sve se zidine porušiti!');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (33, 38, 21, 'I po svim svojim gorama pozvat ću na njega mač - riječ je Jahve Gospoda - s mačem će se brat na brata dići!');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (33, 38, 22, 'Sudit ću mu kugom i krvlju. I spustit ću silan pljusak, i kamenje tÓuče, oganj i sumpor na nj, na njegove čete i na mnogi narod koji bude s njime.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (33, 38, 23, 'I uzveličat ću se, posvetiti i objaviti pred svim narodima, i znat će da sam ja Jahve.\'');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (33, 39, 1, 'Sine čovječji, prorokuj protiv Goga i reci: \'Ovako govori Jahve Gospod: Evo me na te, Gože, veliki kneže Mešeka i Tubala!');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (33, 39, 2, 'Namamit ću te i povesti, podići te s krajnjega sjevera i dovesti na gore Izraelove.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (33, 39, 3, 'Izbit ću ti luk iz lijeve ruke i prosuti strijele iz tvoje desnice.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (33, 39, 4, 'Na gorama ćeš Izraelovim pasti, ti i sve tvoje čete i narodi koji budu s tobom: pticama grabljivicama, svemu krilatom, i zvijerima dadoh te za hranu.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (33, 39, 5, 'Na otvorenom ćeš polju pasti, jer ja tako rekoh - riječ je Jahve Gospoda.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (33, 39, 6, 'Poslat ću oganj na Magog i na sve koji spokojno žive na otocima - i znat će da sam ja Jahve.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (33, 39, 7, 'A svoje sveto ime objavit ću posred naroda svoga izraelskoga i neću dati da se više oskvrnjuje moje sveto ime! I znat će svi narodi da sam ja, Jahve, Svetac Izraelov.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (33, 39, 8, 'Evo dolazi i biva - riječ je Jahve Gospoda! To je dan o kojem sam govorio!');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (33, 39, 9, 'Izići će stanovnici izraelskih gradova, naložiti vatru i spaliti oružje, štitove, štitiće, lukove i strelice, koplja i sulice - ložit će njima vatru sedam godina.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (33, 39, 10, 'Neće nositi drva iz polja ni sjeći u šumama, nego će vatru oružjem ložiti. I oplijenit će one koji su njih plijenili, opljačkati one koji su njih pljačkali - riječ je Jahve Gospoda.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (33, 39, 11, 'U onaj ću dan dati Gogu za grob glasovito mjesto u Izraelu: dolinu Abarim, istočno od Mora, koja zatvara put prolaznicima; ondje će pokopati Goga i sve njegovo mnoštvo. I dolina će se prozvati Hamon-Gog.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (33, 39, 12, 'I ukopavat će ih dom Izraelov, sedam mjeseci, da očisti svu zemlju;');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (33, 39, 13, 'pokapat će ih sav narod zemlje. I bit će im slavan dan u koji se proslavim, riječ je Jahve Gospoda.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (33, 39, 14, 'Izabrat će ljude da neprestano prolaze zemljom pa da s prolaznicima pokapaju one koji preostaše po zemlji, da je tako očiste.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (33, 39, 15, 'I kad koji, prolazeći zemljom, vidi ljudske kosti, podignut će kraj njih nadgrobnik dok ih grobari ne ukopaju u dolini Hamon-Gog.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (33, 39, 16, 'Hamona je ime i gradu. I tako će očistiti zemlju.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (33, 39, 17, 'Sine čovječji, ovako govori Jahve Gospod: Reci pticama, svemu krilatom i svemu zvijerju: skupite se i dođite! Saberite se odasvud na žrtvu moju koju koljem za vas, na veliku gozbu po izraelskim gorama, da se najedete mesa i napijete krvi.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (33, 39, 18, 'Najedite se mesa od junaka i napijte se krvi zemaljskih knezova, ovnova, janjaca, jaraca, junaca, ugojene stoke bašanske!');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (33, 39, 19, 'Najedite se do sita pretiline i napijte se krvi mojih klanica koje sam vam naklao.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (33, 39, 20, 'Nasitite se za mojim stolom konja i konjanika, junaka i ratnika!\' - riječ je Jahve Gospoda.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (33, 39, 21, '\'Tako ću se proslaviti među narodima, i svi će narodi vidjeti sud koji ću izvršiti i ruku što ću je na njih podići.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (33, 39, 22, 'Znat će dom Izraelov da sam ja, Jahve, Bog njihov - od toga dana zauvijek.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (33, 39, 23, 'I znat će narodi da dom Izraelov bijaše odveden u ropstvo zbog svojih nedjela: iznevjerio mi se, pa sakrih lice svoje od njih i predadoh ih njihovim neprijateljima u ruke da od mača poginu.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (33, 39, 24, 'Postupih s njima po nečistoći njihovoj i nedjelima te sakrih lice svoje od njih.\'');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (33, 39, 25, 'Stoga ovako govori Jahve Gospod: \'Sad ću vratiti roblje Jakovljevo i pomilovati sav dom Izraelov - ljubomoran na ime svoje sveto,');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (33, 39, 26, 'oprostit ću im svu sramotu i nevjeru kojom mi se iznevjeriše dok još spokojno življahu u zemlji i nikoga ne bijaše da ih straši.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (33, 39, 27, 'A kad ih dovedem iz naroda i skupim iz zemalja dušmanskih i na njima, naočigled mnogih naroda, svetost svoju pokažem,');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (33, 39, 28, 'znat će da sam ja Jahve, Bog njihov, koji ih u izgnanstvo među narode odvedoh i koji ih opet skupljam u njihovu zemlju, ne ostavivši ondje nijednoga od njih.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (33, 39, 29, 'I nikada više neću kriti lica od njih, jer ću duh svoj izliti na dom Izraelov\' - riječ je Jahve Gospoda.\"');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (33, 40, 1, 'Godine dvadeset i pete za našega izgnanstva, početkom godine, prvoga mjeseca, desetoga dana, a četrnaest godina otkako pade Grad, upravo onoga dana spusti se na me ruka Jahvina.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (33, 40, 2, 'I odvede me u božanskom viđenju u zemlju Izraelovu te me postavi na veoma visoku goru: Na njoj, s južne strane, bijaše nešto kao sazidan grad.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (33, 40, 3, 'Povede me onamo, i gle: čovjek, sjajan kao mjed, stajaše na vratima, s lanenim užetom i mjeračkom trskom u ruci.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (33, 40, 4, 'I taj mi čovjek reče: \"Sine čovječji, gledaj svojim očima i slušaj svojim ušima, popamti sve što ću ti pokazati, jer si doveden ovamo da ti pokažem. Objavi domu Izraelovu sve što ovdje vidiš.\"');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (33, 40, 5, 'I gle, zdanje sve uokolo opasano zidom. Čovjek držaše u ruci mjeračku trsku od šest lakata, a svaki lakat bijaše za jedan dlan duži od običnoga lakta. On izmjeri zdanje. Širina: jedna trska, visina: jedna trska.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (33, 40, 6, 'Zatim pođe k vratima što bijahu okrenuta k istoku. Uspe se uza stepenice i izmjeri prag vrata. Širina: jedna trska.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (33, 40, 7, 'A svaka klijet jednu trsku dugačka i jednu trsku široka. Između klijeti: pet lakata. Prag vrata sa strane njihova trijema, iznutra, jedna trska.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (33, 40, 8, 'Izmjeri trijem vrata iznutra: bijaše osam lakata širok,');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (33, 40, 9, 'a njegovi polustupovi dva lakta. Trijem vrata bijaše s nutarnje strane.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (33, 40, 10, 'Na svakoj strani istočnih vrata bijahu po tri klijeti. I sve tri bijahu iste mjere. Tako i polustupovi: s obje strane bijahu iste mjere.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (33, 40, 11, 'Zatim izmjeri vrata: bijahu deset lakata široka i trinaest lakata visoka.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (33, 40, 12, 'Pred klijetima bijaše s jedne i s druge strane ograda od jednog lakta. Svaka klijet: šest lakata s jedne i šest lakata s druge strane.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (33, 40, 13, 'A zatim izmjeri vrata od stražnje strane jedne klijeti do stražnje strane nasuprotne klijeti, u širinu: bijaše dvadeset i pet lakata; otvor pred otvorom.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (33, 40, 14, 'Izmjeri i trijem: dvadeset lakata. Predvorje bijaše sve uokolo trijema vrata.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (33, 40, 15, 'Od ulaznog pročelja vrata do nasuprotne strane njihova trijema bijaše pedeset lakata.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (33, 40, 16, 'Na klijetima i njihovim dovracima, s unutrašnje strane sve uokolo, a tako i u trijemu, bijahu prozori s rešetkama. Takvi su prozori bili iznutra, sve naokolo, a na polustupovima palme.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (33, 40, 17, 'Zatim me povede u vanjsko predvorje Doma. I gle, sve oko predvorja prostorije i pločnik. Trideset prostorija na pločniku.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (33, 40, 18, 'Pločnik bijaše sa svake strane vrata i odgovaraše razini vrata. To je donji pločnik.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (33, 40, 19, 'On izmjeri širinu predvorja od donjih vrata do unutrašnjega predvorja, s vanjske strane: sto lakata na istok i na sjever.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (33, 40, 20, 'Sjevernim vratima vanjskoga predvorja izmjeri širinu i dužinu.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (33, 40, 21, 'I ta su imala po tri klijeti sa svake strane, a stupovi im i trijemovi istih mjera kao u prvih vrata: pedeset lakata u dužinu i dvadeset i pet lakata u širinu.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (33, 40, 22, 'Prozori im, trijemovi i palme bijahu iste mjere kao na istočnim vratima, a na prilazu im sedam stepenica; trijem im bijaše s unutrašnje strane.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (33, 40, 23, 'Unutrašnje predvorje imaše vrata što bijahu nasuprot sjevernim vratima; kao i istočna. On izmjeri: između jednih i drugih vrata bijaše sto lakata.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (33, 40, 24, 'Zatim me povede na jug, i gle: i ondje vrata. Izmjeri ondje klijeti, polustupove i trijemove: bijahu iste mjere.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (33, 40, 25, 'Ona, kao i njihovi trijemovi, imahu sve uokolo prozore što bijahu kao i oni prvi. Dužina je i tu iznosila pedeset lakata, a širina dvadeset i pet.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (33, 40, 26, 'K vratima je vodilo sedam stuba; trijem im je bio s unutrašnje strane, a na stupovima imahu po jednu palmu sa svake strane.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (33, 40, 27, 'Unutrašnje predvorje imaše jedna vrata i s južne strane. On izmjeri: od tih vrata do južnih vrata - sto lakata.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (33, 40, 28, 'Zatim me na južna vrata uvede u unutrašnje predvorje. I izmjeri južna vrata: bijahu istih mjera.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (33, 40, 29, 'Klijeti, stupovi i trijemovi bijahu istih mjera. Vrata i njihov trijem imahu svud unaokolo prozore. Pedeset lakata bijaše tu u dužinu, dvadeset i pet lakata u širinu.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (33, 40, 30, 'A sve uokolo trijemovi: dvadeset i pet lakata dugi, a pet lakata široki.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (33, 40, 31, 'Trijemovi su se pružili prema vanjskom predvorju. Na polustupovima njihovim palme, a stubište im je imalo osam stuba.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (33, 40, 32, 'Zatim me povede k istočnim vratima unutrašnjega predvorja. I izmjeri vrata: bijahu istih mjera.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (33, 40, 33, 'Klijeti im, polustupovi i trijemovi bijahu također istih mjera. Vrata i njihov trijem imahu svud naokolo prozore. U dužinu bješe pedeset lakata, u širinu dvadeset i pet.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (33, 40, 34, 'Trijem im se pružao prema vanjskom predvorju. Na njihovim polustupovima s ove i s one strane bijahu palme. Stubište im imaše osam stuba.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (33, 40, 35, 'Zatim me povede k sjevernim vratima. I izmjeri ih: bijahu istih mjera.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (33, 40, 36, 'Klijeti im, polustupovi i trijemovi bijahu također istih mjera. Vrata i njihov trijem imahu svud uokolo prozore. Pedeset je lakata tu bilo u dužinu, a dvadeset i pet u širinu.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (33, 40, 37, 'Trijem je sezao do vanjskoga predvorja. Na polustupovima s ove i one strane bijahu palme. Stubište imaše osam stuba.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (33, 40, 38, 'Uz trijemove vrata bijaše prostor s posebnim ulazom. Ondje su se ispirale žrtve paljenice.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (33, 40, 39, 'U trijemu vrata s jedne i s druge strane bijahu po dva stola za klanje paljenicÄa, okajnicÄa i naknadnicÄa.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (33, 40, 40, 'I s vanjske strane onomu tko ulazi na ulaz sjevernih vrata bijahu dva stola; i s druge strane, prema trijemu vrata, dva stola.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (33, 40, 41, 'Četiri stola, dakle, s jedne, a četiri stola s druge strane vrata: u svemu osam stolova, na kojima se klahu žrtve.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (33, 40, 42, 'Osim toga, četiri stola za paljenice, od klesanoga kamena. Bili su po lakat i pol široki i lakat visoki. Na njima je stajao pribor za klanje žrtava paljenica i klanica.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (33, 40, 43, 'Stolovi bijahu sve uokolo obrubljeni žljebićima od jednoga dlana, zavrnutima unutra. Na stolove se stavljalo žrtveno meso.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (33, 40, 44, 'Zatim me povede u unutrašnje predvorje. U unutrašnjem predvorju bijahu dvije prostorije: jedna bijaše sa strane sjevernih vrata, okrenuta prema jugu, a druga sa strane južnih vrata, okrenuta prema sjeveru.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (33, 40, 45, 'I on mi reče: \"Ta prostorija što je okrenuta na jug određena je za svećenike koji obavljaju službu u Domu.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (33, 40, 46, 'A prostorija što je okrenuta na sjever jest za svećenike koji obavljaju službu na žrtveniku. To su sinovi Sadokovi, oni između sinova Levijevih koji smiju prići k Jahvi da mu služe!\"');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (33, 40, 47, 'On izmjeri predvorje. Dužina: sto lakata, širina: sto lakata; bijaše četverouglasto. Pred Domom stajaše žrtvenik.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (33, 40, 48, 'A zatim me povede k trijemu. Izmjeri polustupove trijema: bijaše pet lakata na jednoj i pet lakata na drugoj strani. Vrata bijahu široka tri lakta s jedne i tri lakta s druge strane.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (33, 40, 49, 'Trijem bijaše dugačak dvadeset lakata, a širok dvanaest lakata. Deset je stepenica vodilo onamo. Na dovratnicima s jedne i s druge strane stajaše po jedan stup.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (33, 41, 1, 'Zatim me povede u Hekal. Izmjeri mu polustupove: bijahu široki šest lakata s jedne i šest lakata s druge strane.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (33, 41, 2, 'Vrata bijahu široka deset lakata: sa svake strane po jedno krilo od pet lakata. A zatim izmjeri Hekal: bijaše dugačak četrdeset, a širok dvadeset lakata.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (33, 41, 3, 'Onda uđe i izmjeri polustupove vrata: dva lakta; zatim vrata: šest lakata; pa širinu vrata: sedam lakata.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (33, 41, 4, 'Izmjeri zatim unutrašnji prostor: dužina dvadeset lakata, širina ispred Hekala dvadeset lakata. I reče mi: \"To je Svetinja nad svetinjama.\"');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (33, 41, 5, 'Potom izmjeri zid Doma: šest lakata. Pobočne prostorije bijahu široke četiri lakta, sve oko Doma.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (33, 41, 6, 'Pobočne prostorije bijahu jedna nad drugom, bijaše ih trideset na tri bÓoja. U hramskom zidu bijahu, sve uokolo, zasjeci da prihvate pobočne prostorije. Tako one ne bijahu ugrađene u hramski zid.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (33, 41, 7, 'Širina se prostorija povećavala od boja do boja, jer su one sve uokolo, na bojeve, okruživale Dom, a Dom je, kako se uzlazilo, ostavljao sve širi prostor. S najdonjeg se boja uzlazilo na najgornji kroza srednji.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (33, 41, 8, 'Onda vidjeh sve oko Doma neku uzvisinu. Osnove pobočnih prostorija: cijela trska, šest lakata.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (33, 41, 9, 'Debljina vanjskoga zida pobočnih klijeti: pet lakata. Prolaz između pobočnih prostorija Doma');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (33, 41, 10, 'i klijeti bijaše, sve uokolo Doma, dvadeset lakata širok.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (33, 41, 11, 'Iz pobočne prostorije izlažahu na prolaz jedna vrata prema sjeveru i jedna prema jugu. Prolaz bijaše širok pet lakata svud uokolo.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (33, 41, 12, 'Zdanje što zatvaraše ograđeni prostor sa zapada bijaše široko sedamdeset lakata, a zid te građevine posvud uokolo bijaše debeo pet lakata i dugačak devedeset lakata.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (33, 41, 13, 'On izmjeri Dom: bijaše dugačak stotinu lakata. Ograđeni prostor, zdanje mu i zidovi, stotinu lakata dužine.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (33, 41, 14, 'Širina pročelja Doma s ograđenim prostorom prema istoku: sto lakata.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (33, 41, 15, 'On izmjeri dužinu zdanja duž ograđenog prostora što bijaše straga i hodnike s jedne i s druge strane: stotinu lakata. Unutrašnjost Hekala, trijemovi predvorja,');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (33, 41, 16, 'pragovi, prozori s rešetkama i hodnici na sve tri strane uokolo, nasuprot pragovima, bijahu sve uokolo drvetom obloženi od zemlje do prozora. Prozori su bili zastrti.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (33, 41, 17, 'Od ulaza sve do unutrašnjosti Doma, a tako i izvana te po svem zidu uokolo, iznutra i izvana,');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (33, 41, 18, 'bijahu likovi kerubina i palma. Po jedna palma između dva kerubina, a svaki kerubin imaše dva lica:');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (33, 41, 19, 'prema palmi s jedne strane lice čovječje, a prema palmi s druge strane lice lavlje. Tako bijaše po svemu Domu sve uokolo:');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (33, 41, 20, 'od zemlje do ponad vrata bijahu izdjeljani kerubini i palme, a tako i po zidu Hekala.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (33, 41, 21, 'Dovratnici Hekala bijahu četverouglasti.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (33, 41, 22, 'Pred Svetištem nešto kao žrtvenik od drveta: tri lakta visok, dva lakta dugačak i dva lakta širok. Uglovi mu, podnožje i stranice bijahu od drveta. I čovjek mi reče: \"Evo stola koji je pred licem Jahvinim!\"');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (33, 41, 23, 'I Hekal i Svetište imahu po dvoja vrata,');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (33, 41, 24, 'a svaka vrata po dva krila što se obrtahu: dva krila u jednih i dva krila u drugih vrata.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (33, 41, 25, 'A na vratima Hekala bijahu izdjeljani kerubini i palme, kao što bijahu izdjeljani i po zidovima. Izvana pred trijemom bijaše drvena nadstrešnica.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (33, 41, 26, 'Prozori s rešetkama i palme bijahu s jedne i s druge strane na trijemu, u pobočnim prostorijama Doma i na nadstrešnici.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (33, 42, 1, 'A zatim me povede na sjever, u vanjsko predvorje, i dovede me do prostorija nasuprot ograđenom prostoru, nasuprot zdanju prema sjeveru.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (33, 42, 2, 'Pročelje im sa sjeverne strane bijaše dugo sto lakata, a široko pedeset lakata.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (33, 42, 3, 'Nasuprot vratima unutrašnjeg predvorja i nasuprot pločniku vanjskoga predvorja bijahu hodnici jedan prema drugome na tri boja.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (33, 42, 4, 'Pred prostorijama bijaše prolaz prema unutrašnjosti - deset lakata širok i sto lakata dugačak. Vrata im bijahu okrenuta na sjever.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (33, 42, 5, 'Gornje prostorije, jer im prostor oduzimahu hodnici, bijahu manje od donjih i srednjih.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (33, 42, 6, 'Jer bijahu na tri boja, ali ne imahu stupova kao u predvorju. Zato gornje prostorije bijahu uže od donjih i srednjih.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (33, 42, 7, 'Vanjski zid, duž klijeti, prema vanjskom predvorju, ispred klijeti, bijaše dugačak pedeset lakata.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (33, 42, 8, 'Jer dužina klijetima vanjskoga predvorja bijaše pedeset lakata, a onima pred Hekalom sto lakata.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (33, 42, 9, 'U tih prostorija bijaše ulaz s istoka onomu tko im prilazi iz vanjskog predvorja.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (33, 42, 10, 'Po širini zida predvorja prema istoku, pred ograđenim prostorom i pred samim zdanjem, bijaše još prostorijÄa.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (33, 42, 11, 'Pred njima bijaše prolaz kao ispred klijeti smještenih prema sjeveru: jednake dužine i jednake širine; i svi im izlazi, raspored i vrata bijahu jednaki.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (33, 42, 12, 'Bili su kao ulazi u klijeti što bijahu prema jugu: ulaz na početku svakog prolaza, nasuprot zidu zdanja, prema istoku onomu tko bi u njih ulazio.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (33, 42, 13, 'I reče mi: \"Sjeverne i južne prostorije ispred ograđenog prostora jesu prostorije Svetišta: ondje svećenici koji prilaze Jahvi blaguju najveće svetinje. Oni će ovdje odlagati najveće svetinje, prinose, okajnice i naknadnice, jer je to mjesto sveto.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (33, 42, 14, 'A kad svećenici budu ulazili, neće izlaziti iz Svetišta u vanjsko predvorje, nego će tu ostavljati odjeću u kojoj bijahu službu služili, jer je sveta, i oblačiti drugu odjeću da bi se mogli približiti mjestu određenu za narod.\"');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (33, 42, 15, 'Izmjerivši unutrašnjost Doma, izvede me na istočna vrata i izmjeri sve uokolo.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (33, 42, 16, 'Mjeračkom trskom izmjeri istočnu stranu: bijaše pet stotina trska, mjeračkih trska,');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (33, 42, 17, 'a zatim se okrenu i izmjeri sjevernu stranu: bijaše pet stotina trska, mjeračkih trska.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (33, 42, 18, 'Tada se okrenu na južnu stranu i izmjeri: pet stotina trska, mjeračkih trska.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (33, 42, 19, 'Potom se okrenu na zapadnu stranu i izmjeri: pet stotina trska, mjeračkih trska.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (33, 42, 20, 'On izmjeri zid na sve četiri strane uokolo: bijaše pet stotina trska dugačak i pet stotina širok. Odvajao je sveto mjesto od nesvetoga.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (33, 43, 1, 'Zatim me povede k vratima što gledaju na istok.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (33, 43, 2, 'I gle, Slava Boga Izraelova dolazi od istoka; šum joj kao šum velikih voda: i zemlja se sjala od slave njegove.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (33, 43, 3, 'To viđenje koje gledah bijaše kao viđenje što ga vidjeh kad dođoh da uništim grad i kao viđenje koje vidjeh na rijeci Kebaru. Padoh ničice.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (33, 43, 4, 'A Slava Jahvina uđe u Dom na vrata koja gledaju na istok.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (33, 43, 5, 'Tada me duh podiže i odvede u unutrašnje predvorje. I gle: Dom bijaše pun Slave Jahvine.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (33, 43, 6, 'I čuh glas koji mi iz Doma govori, a kraj mene netko stajaše.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (33, 43, 7, 'I reče mi: \"Sine čovječji, ovo je mjesto mojega prijestolja, ovo je mjesto stopa mojih nogu: ovdje ću, posred sinova Izraelovih, prebivati zauvijek. Izraelov dom neće više oskvrnjivati moje sveto ime - ni oni ni njihovi kraljevi - svojim bludništvom i truplima svojih kraljeva:');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (33, 43, 8, 'stavili su svoj prag do moga, svoje dovratnike do mojih, tako da je bio samo zid između mene i njih, i oskvrnjivali su moje sveto ime gnusobama koje počiniše. I zato ih zatrijeh u svojem gnjevu.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (33, 43, 9, 'Sada će oni ukloniti daleko od mene svoje bludništvo i trupla svojih kraljeva, a ja ću zauvijek prebivati posred njih.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (33, 43, 10, 'Sine čovječji, pokaži domu Izraelovu ovaj Dom da se posrame sa svojih bezakonja. Neka mu izmjere razmjere.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (33, 43, 11, 'Ako se posrame zbog svega što učiniše, opiši im Dom i njegove razmjere, njegove izlaze i ulaze, sve njegovo obličje, sve propise i sve zakone; upoznaj ih i nacrtaj im da vide i da čuvaju i provedu sve njegovo obličje i sve propise o njemu.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (33, 43, 12, 'A ovo je zakon za Dom: navrh gore, sav prostor uokolo, bit će najsvetija svetinja.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (33, 43, 13, 'Ovo su mjere žrtvenika, na laktove - a lakat je ovdje jedan lakat i pedalj: podnožje žrtvenika lakat dugo, lakat široko; obrub kojim je obrubljen uokolo - jedan pedalj. Visina žrtvenika:');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (33, 43, 14, 'od podnožja na zemlji do donjega pojasa žrtvenika - dva lakta, a u širinu jedan lakat; od manjeg pojasa do većega četiri lakta, a u širinu jedan lakat.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (33, 43, 15, 'A samo žrtvište: četiri lakta visoko. A sa žrtvišta dižu se uvis četiri roga.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (33, 43, 16, 'Žrtvište: dvanaest lakata dugo, dvanaest lakata široko, četvorina, na sve četiri strane.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (33, 43, 17, 'A pojas: četrnaest lakata dug i četrnaest lakata širok, na četiri strane; njegov rub uokolo pol lakta, a podnožje oko njega uokolo jedan lakat; stepenice mu gledaju na istok.\"');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (33, 43, 18, 'I reče mi: \"Sine čovječji, ovako govori Jahve Gospod: \'Ovo su propisi žrtveni po kojima se u svoje vrijeme mora podići žrtvenik da se na njemu prinose paljenice i da se po njemu škropi krvlju.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (33, 43, 19, 'Svećenicima levitima, potomcima Sadokovim, koji pristupaju k meni da mi služe - riječ je Jahve Gospoda - dat ćeš june za žrtvu okajnicu.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (33, 43, 20, 'Uzet ćeš njegove krvi i njome pomazati četiri roga žrtvišta i četiri ugla pojasa i obrub sve uokolo da okajnicom pomiriš žrtvenik.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (33, 43, 21, 'Zatim uzmi june i spali ga na odijeljenom mjestu Doma, izvan Svetišta.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (33, 43, 22, 'Sutradan prinesi jarca bez mane kao okajnicu, neka se njime okaje žrtvenik kao što je okajan junetom.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (33, 43, 23, 'A kad ga okaješ, prinesi junca bez mane i ovna bez mane iz stada:');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (33, 43, 24, 'prikaži ih pred Jahvom, a svećenici neka ih pospu solju i neka ih prinesu kao paljenicu Jahvi.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (33, 43, 25, 'Sedam dana svaki dan prinesi jednog jarca za grijeh; i neka se prinese june i ovan iz stada, oba bez mane.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (33, 43, 26, 'Sedam dana neka se pomiruje žrtvenik i neka se čisti i posvećuje.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (33, 43, 27, 'Pošto se navrše ti dani, od osmoga dana unapredak neka svećenici žrtvuju na žrtveniku vaše paljenice i pričesnice; i omiljet ćete mi\' - riječ je Jahve Gospoda.\"');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (33, 44, 1, 'Potom me odvede natrag k izvanjskim vratima Svetišta, koja gledaju na istok: bijahu zatvorena.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (33, 44, 2, 'I reče mi Jahve: \"Ova će vrata biti zatvorena; neka se ne otvaraju i nitko neka ne ulazi na njih, jer ja, Jahve, Bog Izraelov, kroz njih prođoh - zato neka budu zatvorena.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (33, 44, 3, 'Samo knez, jer je knez, smije sjesti tu i blagovati pred Jahvom; tada neka uđe kroz trijem vrata i istim putem neka izađe.\"');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (33, 44, 4, 'Zatim me odvede k sjevernim vratima pred Dom. Pogledah, i gle: Slava Jahvina bijaše napunila Dom Jahvin. Padoh ničice.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (33, 44, 5, 'Jahve mi reče: \"Sine čovječji, pomno pripazi, dobro gledaj i pažljivo poslušaj što ću ti reći o svim uredbama Doma Jahvina i o svim njegovim zakonima. Dobro pazi tko smije ući u Dom i tko je iz Svetišta odijeljen.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (33, 44, 6, 'Reci rodu odmetničkom, domu Izraelovu: \'Ovako govori Jahve Gospod: Previše je već vaših gnusoba, dome Izraelov!');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (33, 44, 7, 'Uvodili ste tuđince, neobrezana srca i neobrezana tijela, te su ušli u moje Svetište i oskvrnuli moj Dom dok ste vi prinosili moj kruh i pretilinu i krv; i tako ste raskinuli moj Savez svim tim gnusobama.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (33, 44, 8, 'Niste sami čuvali moje svetinje, nego ste njih namjestili namjesto sebe kao čuvare u mojem Svetištu.\'');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (33, 44, 9, 'Ovako govori Jahve Gospod: \'Nijedan tuđinac, neobrezana srca i neobrezana tijela, da više ne ulazi u moje Svetište - nijedan tuđinac koji živi među sinovima Izraelovim.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (33, 44, 10, 'A leviti koji su se udaljili od mene, kad je ono Izrael odlutao od mene za svojim kumirima, snosit će svoje bezakonje.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (33, 44, 11, 'Služit će u Svetištu samo kao stražari na vratima Doma i kao posluga Domu: klat će narodu paljenice i druge žrtve i bit će mu na službu.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (33, 44, 12, 'Služili su im pred njihovim kumirima i tako naveli Dom Izraelov na bezakonje. Zato podigoh ruku na njih - riječ je Jahve Gospoda - da snose svoje bezakonje.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (33, 44, 13, 'Više neće pristupati k meni da mi služe kao svećenici i neće više prilaziti mojim najsvetijim svetinjama, nego će snositi svoju sramotu i gnusobe koje počiniše.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (33, 44, 14, 'Postavit ću ih da u Domu rade svaki posao i sve što treba u njemu svršiti.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (33, 44, 15, 'Svećenici leviti, potomci Sadokovi, koji su mi vjerno služili u mojem Svetištu kad su ono sinovi Izraelovi odlutali od mene - oni smiju pristupati k meni da mi služe: služit će preda mnom prinoseći mi pretilinu i krv - riječ je Jahve Gospoda.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (33, 44, 16, 'Oni smiju ulaziti u moje Svetište i pristupati k mojem stolu da mi služe i da vrše službu.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (33, 44, 17, 'Kad budu ulazili na vrata unutrašnjega predvorja, neka obuku lanene haljine: neka ne bude na njima ništa vuneno kad služe na vratima unutrašnjega predvorja i Doma.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (33, 44, 18, 'Na glavama neka nose lanene kape, oko bokova gaće lanene: neka se ne pašu ničim od čega bi se znojili.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (33, 44, 19, 'Kad izlaze u vanjsko predvorje k narodu, neka svuku haljine u kojima su služili i neka ih ostave u prostorijama Svetišta, a neka obuku druge haljine, da ne posvete puk svojim haljinama.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (33, 44, 20, 'I neka ne briju glave, a ni bujne kose neka ne puštaju, nego neka strigu kosu.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (33, 44, 21, 'I nijedan svećenik, kad mu je poći u unutrašnje predvorje, neka ne pije vina.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (33, 44, 22, 'Neka se ne žene udovicom ili puštenicom nego samo djevojkom iz roda Izraelova ili udovicom svećenikovom.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (33, 44, 23, 'Neka mi narod uče razlikovati sveto od nesvetoga, lučiti nečisto od čistoga.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (33, 44, 24, 'U parnicama oni neka budu suci: neka sude po mojim zakonima; i neka čuvaju zakone i uredbe o svim mojim blagdanima i neka svetkuju moje subote.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (33, 44, 25, 'K mrtvacu neka ne prilaze da se ne okaljaju; samo za ocem i za majkom, za sinom i kćerju, za bratom i sestrom još neudatom smiju se okaljati.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (33, 44, 26, 'Pošto se nakon toga koji očisti, neka mu se broji sedam dana:');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (33, 44, 27, 'a onda kad uđe u Svetište, u unutrašnje predvorje da služi u Svetištu, neka prinese žrtvu okajnicu - riječ je Jahve Gospoda.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (33, 44, 28, 'Njima ne pripada nikakva baština - ja sam njihova baština; i zato im ne dajte nikakva posjeda u Izraelu - ja sam posjed njihov.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (33, 44, 29, 'Hranit će se od žrtava prinosnica, okajnica i naknadnica, i sve zavjetovano u Izraelu njima pripada.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (33, 44, 30, 'Najbolje od svih vaših prvina i od svih vaših prinosa koje ćete prinositi pripada svećenicima; njima ćete davati i najbolje brašno, da blagoslov počiva na vašim domovima.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (33, 44, 31, 'Svećenici ne smiju jesti mesa od uginulih i razderanih životinja - bilo od ptica ili stoke.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (33, 45, 1, 'Kad budete zemlju ždrijebom dijelili u baštinu, prinesite kao prinos pridržan Jahvi jedan sveti dio zemlje, dugačak dvadeset i pet tisuća lakata, širok deset tisuća; to neka bude sveto područje uzduž i poprijeko.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (33, 45, 2, 'Od toga neka bude za Svetište četvorina od pet stotina lakata i čistina od deset lakata uokolo.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (33, 45, 3, 'Od toga područja izmjeri u dužinu dvadeset i pet tisuća lakata, a u širinu deset tisuća: tu neka bude Svetište - Svetinja nad svetinjama.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (33, 45, 4, 'Taj sveti dio zemlje pripada svećenicima koji služe u Svetištu i koji pristupaju k Jahvi da mu služe: tu neka im bude mjesto za kuće; i to neka je sveto mjesto koje pripada Svetištu.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (33, 45, 5, 'Dvadeset i pet tisuća u dužinu i deset tisuća u širinu neka bude levitima koji služe Domu: neka ondje sagrade gradove u kojima će stanovati.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (33, 45, 6, 'Za posjed gradu dodijelite pet tisuća lakata u širinu i dvadeset i pet tisuća lakata u dužinu usporedo sa svetim područjem: to će pripadati svemu domu Izraelovu.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (33, 45, 7, 'Knezu pripada dio s obje strane svetoga područja i gradskoga posjeda - duž svetoga područja i duž gradskoga posjeda - od zapadne strane prema zapadu i od istočne strane prema istoku, a dužina neka bude jednaka svakom tom dijelu, od zapadne do istočne granice.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (33, 45, 8, 'To neka bude njegova zemlja, posjed u Izraelu, da knezovi više ne tlače narod moj i da zemlju dadu domu Izraelovu po plemenima.\'');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (33, 45, 9, 'Ovako govori Jahve Gospod: \'Dosta je, knezovi Izraelovi! Okanite se nasilja i pljačke i vršite zakon i pravdu; izbavite narod moj od svojih tražbina - riječ je Jahve Gospoda.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (33, 45, 10, 'Mjerite pravom mjerom: pravom efom i pravim batom.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (33, 45, 11, 'Efa i bat neka jednako hvataju: bat neka iznosi desetinu homera i efa desetinu homera - neka im mjera bude prema homeru.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (33, 45, 12, 'Šekel neka bude dvadeset gera; mina neka vam bude dvadeset šekela, dvadeset i pet šekela i petnaest šekela.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (33, 45, 13, 'Ovo je prinos koji ćete prinositi: šestinu efe od svakoga homera pšenice i šestinu efe od svakoga homera ječma.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (33, 45, 14, 'A za ulje ova je uredba: desetina bata od svakoga kora - deset bata jedan je kor.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (33, 45, 15, 'Od svakoga stada od dvije stotine ovaca sa sočnih izraelskih pašnjaka po jednu ovcu za žrtvu prinosnicu, paljenicu i pričesnicu - vama za pomirenje - riječ je Jahve Gospoda.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (33, 45, 16, 'Sav narod zemlje duguje ovaj prinos knezu Izraelovu.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (33, 45, 17, 'A knez je dužan davati žrtve paljenice, prinosnice i ljevanice za svetkovine i za mlađake, za subote i blagdane doma Izraelova: on neka se postara za okajnicu, za pomirnicu, prinosnicu, paljenicu i pričesnicu za pomirenje doma Izraelova.\'');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (33, 45, 18, 'Ovako govori Jahve Gospod: \'Prvoga mjeseca, prvoga dana u mjesecu, uzmi june bez mane i okaj njime Svetište.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (33, 45, 19, 'Svećenik neka uzme krvi te žrtve okajnice i neka njome pomaže dovratnike Doma i sva četiri ugla pojasa žrtveničkoga i dovratnike vrata unutrašnjega predvorja.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (33, 45, 20, 'Tako neka učini i sedmoga dana istoga mjeseca za svakoga koji je sagriješio iz slabosti i neznanja. Tako ćete dovršiti pomirenje Doma.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (33, 45, 21, 'Prvoga mjeseca, četrnaestoga dana u mjesecu, svetkujte Pashu, sedmodnevni blagdan, kad se blaguju beskvasni hljebovi.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (33, 45, 22, 'Toga dana neka knez za se i za sav puk zemlje prinese june za okajnicu.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (33, 45, 23, 'Sedam dana blagdana neka prinosi za paljenicu Jahvi sedam junčića i sedam ovnova bez mane - svaki dan tih sedam dana - i svaki dan jarca kao okajnicu.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (33, 45, 24, 'A kao prinosnicu neka prinese efu po svakom juncu i efu po ovnu i hin ulja na svaku efu.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (33, 45, 25, 'Sedmoga mjeseca, petnaestoga dana u mjesecu, neka o blagdanu isto toliko prinosi sedam dana: isto toliko okajnica, paljenica, prinosnica i ulja.\'');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (33, 46, 1, 'Ovako govori Jahve Gospod: \'Vrata unutrašnjega predvorja, koja gledaju na istok, neka budu zatvorena šest radnih dana, a neka se otvaraju u dan subotnji; i u dan mlađaka neka se otvaraju.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (33, 46, 2, 'Knez neka ulazi kroz njihov trijem i neka stane kod dovratnika; svećenici će tada prinijeti njegovu paljenicu i pričesnicu, a on će se pokloniti na pragu vrata i izaći. Neka se vrata ne zatvaraju do večeri.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (33, 46, 3, 'Na ulazu istih vrata subotom i na mlađake klanjat će se Jahvi puk zemlje.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (33, 46, 4, 'Paljenica koju će knez subotom prinositi Jahvi neka bude: šest jaganjaca bez mane, ovan bez mane.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (33, 46, 5, 'A prinosnica neka bude efa po ovnu, a po jaganjcu koliko i kako tko može i hin ulja po efi.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (33, 46, 6, 'Na dan mlađaka neka se prinese june bez mane, šest jaganjaca i ovan bez mane.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (33, 46, 7, 'A za prinosnicu neka se prinese efa po junetu, efa po ovnu, a po jaganjcu koliko tko može i hin ulja po efi.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (33, 46, 8, 'Kad knez bude ulazio, neka ulazi kroz trijem vrata i istim putem neka izlazi.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (33, 46, 9, 'A kad puk zemlje o blagdanima dolazi pred Jahvu, onaj koji na sjeverna vrata uđe da se pokloni neka izađe na južna, a tko uđe na južna neka izađe na sjeverna: neka se ne vraća na vrata na koja je ušao, nego neka izađe na suprotna.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (33, 46, 10, 'I knez neka bude s njima: kad oni ulaze, neka i on uđe i neka izađe kad oni izlaze.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (33, 46, 11, 'O blagdanima i svetkovinama neka se kao prinosnica prinese efa po juncu i efa po ovnu, a po jaganjcu koliko tko može i hin ulja po efi.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (33, 46, 12, 'Kad knez želi prinijeti dobrovoljnu paljenicu ili dobrovoljnu pričesnicu Jahvi, neka mu se otvore vrata koja gledaju na istok, pa neka prinese paljenicu i svoju pričesnicu kao na dan subotnji; potom neka iziđe, a kad iziđe, neka se zatvore vrata.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (33, 46, 13, 'Svaki dan prinijet ćeš Jahvi za paljenicu janje od godine, bez mane; prinijet ćeš ga svako jutro.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (33, 46, 14, 'A kao prinosnicu na nj prinesi svako jutro šestinu efe i trećinu hina ulja da se poškropi najfinije brašno; to neka bude svagdašnji prinos Jahvi po vječnoj uredbi.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (33, 46, 15, 'Treba dakle prinijeti jagnje, prinosnicu i ulje svako jutro kao svagdašnju žrtvu paljenicu.\'');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (33, 46, 16, 'Ovako govori Jahve Gospod: \'Dadne li knez dar komu svom sinu od svoje baštine, taj će dar pripasti njima u posjed kao baština.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (33, 46, 17, 'Ako li od svoje baštine dade dar komu svom sluzi, tome će to pripadati do otpusne godine, a potom neka se vrati knezu; baština pripada samo kneževim sinovima.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (33, 46, 18, 'Knez ne smije prisvojiti ništa od baštine naroda, pljačkajući narodni posjed. Sinovima svojim neka dade baštinu od svojega posjeda, da se ne raspe narod potjeran sa svojega posjeda.\'\"');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (33, 46, 19, 'Zatim me odvede kroz ulaz kraj vrata, u svećeničke prostorije Svetišta što gledaju na sjever. I gle: ondje, u dnu, prema zapadu, jedan prostor!');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (33, 46, 20, 'I reče mi: \"Ovo je mjesto gdje će svećenici kuhati žrtve naknadnice i okajnice i žrtvu pomirnicu, gdje će peći prinosnice da ih ne iznose u vanjsko predvorje te ne posvete naroda.\"');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (33, 46, 21, 'Potom me izvede u vanjsko predvorje i provede kraj četiri ugla predvorja, i gle, u svakom uglu predvorja bijaše malo predvorje.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (33, 46, 22, 'Ta mala predvorja u četiri ugla predvorja bijahu četrdeset lakata dugačka, trideset široka - sva četiri istih razmjera;');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (33, 46, 23, 'sva četiri zidom opasana, a pod zidom sve uokolo bijahu sagrađena ognjišta.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (33, 46, 24, 'I reče mi: \"To su kuhinje gdje će sluge Doma kuhati puku žrtve.\"');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (33, 47, 1, 'Zatim me odvede natrag k vratima Doma. I gle: voda izvirala ispod praga Doma, prema istoku - jer pročelje Doma bijaše prema istoku - i voda otjecaše ispod desne strane Doma, južno od žrtvenika.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (33, 47, 2, 'Zatim me izvede na sjeverna vrata i provede me uokolo vanjskim putem k vanjskim vratima koja gledaju na istok. I gle, voda izvirala s desne strane.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (33, 47, 3, 'Čovjek pođe prema istoku s užetom u ruci, izmjeri tisuću lakata i prevede me preko vode, a voda mi sezaše do gležanja.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (33, 47, 4, 'Ondje opet izmjeri tisuću lakata i provede me preko vode, a voda bijaše do koljena. I opet izmjeri tisuću lakata i prevede me preko vode što bijaše do bokova.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (33, 47, 5, 'Opet izmjeri tisuću lakata, ali ondje bijaše potok koji ne mogoh prijeći jer je voda nabujala te je trebalo plivati: bijaše to potok koji se ne može prijeći.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (33, 47, 6, 'I upita me: \"Vidiš li, sine čovječji?\" I odvede me natrag, na obalu potoka.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (33, 47, 7, 'I kad se vratih, gle, na obali s obje strane mnoga stabla.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (33, 47, 8, 'I reče mi: \"Ova voda teče u istočni kraj, spušta se u Arabu i teče u more; a kad se u more izlije, vode mu ozdrave.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (33, 47, 9, 'I kuda god potok protječe, sve živo što se miče oživi; i bit će vrlo mnogo riba, jer kamo god dođe ova voda, sve ozdravi i oživi - kuda god protječe ovaj potok.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (33, 47, 10, 'I ribari će ribariti duž mora: od En Gedija do En Eglajima sušit će se mreže; i bit će vrlo mnogo svakovrsnih riba kao u Velikom moru.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (33, 47, 11, 'A močvare onoga mora i njegove bare neće ozdraviti: bit će za sol.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (33, 47, 12, 'Duž potoka na obje strane rast će svakovrsne voćke: lišće im neće otpadati i s njih neće nestajati ploda; svakog će mjeseca roditi novim plodom jer im voda dotječe iz Svetišta. Plod će njihov biti za jelo, a lišće za lijek\'.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (33, 47, 13, 'Ovako govori Jahve Gospod: \'Ovo su granice u kojima ćete podijeliti zemlju u baštinu među dvanaest plemena Izraelovih - Josipu dva dijela.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (33, 47, 14, 'Svakom će od vas pripasti podjednako od zemlje koju se zakleh dati vašim ocima, a vama će pripasti u baštinu.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (33, 47, 15, 'Ovo su, dakle, granice zemlje: na sjeveru, od Velikoga mora put Hetlona do Ulaza u Hamat: Sedad,');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (33, 47, 16, 'Berota, Sibrajim, između kraja damaščanskog i hamatskoga, i Haser Enon, prema granici hauranskoj.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (33, 47, 17, 'Granica će se, dakle, protezati od mora do Haser Enona, kojemu je na sjeveru kraj damaščanski i hamatski - sjeverna strana.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (33, 47, 18, 'Istočna strana: između Haurana i Damaska, između Gileada i zemlje izraelske, pa Jordanom kao granicom prema istočnomu moru do Tamara - istočna strana.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (33, 47, 19, 'Južna strana: prema jugu od Tamara do Meripskih voda i Kadeša pa potokom prema Velikomu moru - južna strana, prema jugu.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (33, 47, 20, 'A zapadna strana: granica je Veliko more pa do nadomak Ulaza u Hamat - zapadna strana.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (33, 47, 21, 'Tu zemlju razdijelite među sobom po plemenima Izraelovim.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (33, 47, 22, 'Razdijelit ćete je ždrijebom u baštinu između sebe i između došljaka koji žive među vama i koji među vama djecu narodiše: i njih ćete smatrati domorocima među Izraelovim sinovima, da i oni dobiju ždrijebom baštinu među Izraelovim sinovima.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (33, 47, 23, 'Svakome tom došljaku dodijelite baštinu u plemenu u kojem živi - riječ je Jahve Gospoda.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (33, 48, 1, 'A ovo su imena plemenÄa: od krajnjega sjevera put Hetlona prema Ulazu u Hamat i Haser Enon, od damaščanskoga kraja na sjeveru duž Hamata, od istoka do zapada - dio Danov.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (33, 48, 2, 'Uz područje Danovo, od istoka do zapada - dio Ašerov.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (33, 48, 3, 'Uz područje Ašerovo, od istoka do zapada - dio Naftalijev.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (33, 48, 4, 'Uz područje Naftalijevo, od istoka do zapada - dio Manašeov.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (33, 48, 5, 'Uz područje Manašeovo, od istoka do zapada - dio Efrajimov.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (33, 48, 6, 'Uz područje Efrajimovo, od istoka do zapada - dio Rubenov.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (33, 48, 7, 'Uz područje Rubenovo, od istoka do zapada - dio Judin.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (33, 48, 8, 'Uz područje Judino, od istoka do zapada neka bude pridržano područje koje ćete Jahvi prinijeti: dvadeset i pet tisuća lakata u širinu, a u dužinu kao svaki drugi dio, od istoka do zapada. U sredini neka bude Svetište.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (33, 48, 9, 'To pridržano područje koje ćete Jahvi prinijeti neka bude dugačko dvadeset i pet tisuća lakata, široko deset tisuća.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (33, 48, 10, 'To sveto, prineseno područje za svećenike neka bude na sjeveru dvadeset i pet tisuća lakata; prema zapadu široko deset tisuća, prema istoku široko deset tisuća; prema jugu dugačko dvadeset i pet tisuća. U sredini neka bude Jahvino Svetište.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (33, 48, 11, 'A posvećenim svećenicima, potomcima Sadokovim, koji su mi vjerno služili i nisu, kao leviti, zastranili kad su ono zastranili sinovi Izraelovi:');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (33, 48, 12, 'njima će pripasti dio od toga najsvetijeg područja zemlje, uz područje levitsko.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (33, 48, 13, 'A levitima, baš kao i području svećeničkom: dvadeset i pet tisuća lakata u dužinu i deset tisuća lakata u širinu - ukupno dvadeset i pet tisuća lakata u dužinu, deset tisuća u širinu.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (33, 48, 14, 'Od toga se ništa ne smije prodati ni zamijeniti; ne smije se ni na koga prenijeti ta prvina zemlje, jer je Jahvi posvećena.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (33, 48, 15, 'Pet tisuća lakata u širinu, što ostane od onih dvadeset i pet tisuća, neka bude opće područje: za grad, za naselje i za čistinu. Grad neka bude u sredini.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (33, 48, 16, 'Evo mjerÄa: sa sjevera četiri tisuće i pet stotina lakata; s juga četiri tisuće i pet stotina; s istoka četiri tisuće i pet stotina; sa zapada četiri tisuće i pet stotina.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (33, 48, 17, 'A čistina oko grada: dvije stotine i pedeset lakata prema sjeveru, dvije stotine i pedeset prema jugu, dvije stotine i pedeset prema istoku, dvije stotine i pedeset prema zapadu.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (33, 48, 18, 'Što ostane u dužinu, duž svetoga područja - deset tisuća lakata prema istoku i deset tisuća prema zapadu, duž svetoga područja - to neka bude za uzdržavanje onih koji služe gradu.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (33, 48, 19, 'Ti koji služe gradu uzimat će se iz svih plemena Izraelovih.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (33, 48, 20, 'Sve, dakle, pridržano područje - dvadeset i pet tisuća lakata sa dvadeset i pet tisuća, u četverokut - prinijet ćete Jahvi: i sveto područje i posjed gradski.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (33, 48, 21, 'Knezu pripada što preostane: s obje strane svetoga područja i posjeda gradskoga - prema istoku dvadeset i pet tisuća lakata, prema istočnoj strani, i prema zapadu dvadeset i pet tisuća lakata, prema zapadnoj strani, usporedo s drugim područjima - sve je to kneževo. A u sredini je sveto područje i Svetište Doma.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (33, 48, 22, 'Od levitskoga posjeda i od posjeda gradskoga - koje je usred kneževa - i između Judina i Benjaminova područja: kneževo je.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (33, 48, 23, 'Ostala plemena: od istoka do zapada - dio Benjaminov.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (33, 48, 24, 'Uz područje Benjaminovo, od istoka do zapada - dio Šimunov.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (33, 48, 25, 'uz područje Šimunovo, od istoka do zapada - dio Jisakarov.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (33, 48, 26, 'Uz područje Jisakarovo, od istoka do zapada - dio Zebulunov.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (33, 48, 27, 'Uz područje Zebulunovo, od istoka do zapada - dio Gadov.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (33, 48, 28, 'Uz područje Gadovo, na južnoj strani, prema jugu, ide granica od Tamara do Meripskih voda i Kadeša, pa potokom prema Velikome moru.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (33, 48, 29, 'To je zemlja koju ćete ždrijebom razdijeliti u baštinu plemenima Izraelovim, to su njihovi dijelovi - riječ je Jahve Gospoda.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (33, 48, 30, '[30a] A ovo su gradska vrata');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (33, 48, 31, '[31a] koja će se zvati po Izraelovim plemenima. [30b] Na sjevernoj strani - četiri tisuće i pet stotina lakata u dužinu - [31b] troja vrata: Vrata Rubenova, Vrata Judina, Vrata Levijeva.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (33, 48, 32, 'Na istočnoj strani - četiri tisuće i pet stotina lakata u dužinu - troja vrata: Vrata Josipova, Vrata Benjaminova, Vrata Danova.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (33, 48, 33, 'Na južnoj strani - četiri tisuće i pet stotina lakata u dužinu - troja vrata: Vrata Šimunova, Vrata Jisakarova, Vrata Zebulunova.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (33, 48, 34, 'Sa zapadne strane - četiri tisuće i pet stotina lakata u dužinu - troja vrata: Vrata Gadova, Vrata Ašerova, Vrata Naftalijeva.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (33, 48, 35, 'Sve uokolo: osamnaest tisuća lakata. A ime će gradu unapredak biti: \'Jahve je ovdje.\'\"');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (34, 1, 1, 'Treće godine kraljevanja Jojakima, kralja Judeje, dođe Nabukodonozor, kralj Babilona, na Jeruzalem te ga opsjede.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (34, 1, 2, 'Gospodin mu dade u ruke Jojakima, kralja judejskog, i dio predmeta iz Doma Božjega; on ih dopremi u zemlju Šinear i pohrani predmete u riznici svojih bogova.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (34, 1, 3, 'Kralj naredi Ašfenazu, starješini svojih dvorjanika, da dovede od Izraelaca nekoliko dječaka kraljevskoga ili velikaškog roda:');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (34, 1, 4, 'neka budu bez nedostatka, lijepi, vrsni u svakoj mudrosti, dobro poučeni i bistri, prikladni da stoje na kraljevu dvoru; Ašfenaz neka ih nauči pismu i jeziku Kaldejaca.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (34, 1, 5, 'Kralj im odredi dnevni obrok od kraljevskih jela i od vina sa svoga stola. Neka se odgajaju tri godine, a poslije toga imali bi stajati pred kraljem.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (34, 1, 6, 'Među njima bijahu Judejci: Daniel, Hananija, Mišael i Azarja.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (34, 1, 7, 'Dvorjanički starješina nadjene im imena: Daniel će se zvati Baltazar, Hananija Šadrak, Mišael Mešak, Azarja Abed Nego.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (34, 1, 8, 'Daniel je u srcu odlučio da se neće okaljati kraljevim jelima i vinom s njegova stola, pa zamoli dvorjaničkog starješinu da ga poštedi te se ne okalja.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (34, 1, 9, 'Bog dade Danielu te nađe dobrohotnost i smilovanje u dvorjaničkog starješine.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (34, 1, 10, 'Starješina reče Danielu: \"Bojim se svoga gospodara kralja; on vam je odredio jelo i pilo, pa ako vidi da su vam lica mršavija nego u drugih dječaka vaše dobi, ja ću zbog vas biti kriv pred kraljem.\"');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (34, 1, 11, 'Tada reče Daniel čuvaru koga bijaše dvorjanički starješina odredio Danielu, Hananiji, Mišaelu i Azarji:');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (34, 1, 12, '\"Molim te, pokušaj sa svojim slugama deset dana: neka nam se daje povrće za jelo i voda za pilo.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (34, 1, 13, 'Vidjet ćeš onda kakvi ćemo biti mi a kakvi dječaci koji jedu od kraljevih jela, pa učini sa svojim slugama po onome što budeš vidio.\"');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (34, 1, 14, 'On pristade i stavi ih na kušnju deset dana.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (34, 1, 15, 'A nakon deset dana oni bijahu ljepši i ugojeniji nego svi dječaci koji jeđahu od kraljevih jela.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (34, 1, 16, 'Od tada čuvar dokinu njihova jela i obrok vina što su imali piti te im davaše povrća.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (34, 1, 17, 'Ovoj četvorici dječaka dade Bog znanje i razumijevanje svih knjiga i mudrosti. Daniel razumijevaše viđenja i sne.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (34, 1, 18, 'Pošto se navršilo vrijeme određeno od kralja da mu ih dovedu, dvorjanički starješina uvede ih pred Nabukodonozora.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (34, 1, 19, 'Kralj razgovaraše s njima i među svima ne nađe se nijedan kao Daniel, Hananija, Mišael i Azarja. I tako oni ostadoše pred kraljem.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (34, 1, 20, 'I u svemu mudrom i umnom o čemu ih ispitivaše kralj nađe da su deset puta vrsniji od svih čarobnika i gatalaca što ih bijaše u svem njegovu kraljevstvu.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (34, 1, 21, 'Daniel ostade ondje do prve godine kralja Kira.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (34, 2, 1, 'Druge godine Nabukodonozorova kraljevanja usni Nabukodonozor sanje: njegov se duh zbog toga uznemiri, a san ga ostavi.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (34, 2, 2, 'Kralj naredi da se pozovu čarobnici i gataoci, zaklinjači i zvjezdari da protumače kralju njegove sanje.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (34, 2, 3, 'Dođoše dakle te stadoše pred kralja. Kralj im reče: \"Usnih jednu sanju i moj se duh uznemiri od želje da razumijem sanju.\"');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (34, 2, 4, 'Kaldejci odgovoriše kralju (aramejski): \"O kralju, živ bio dovijeka! Pripovjedi svoju sanju slugama svojim, a mi ćemo ti otkriti njezino značenje.\"');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (34, 2, 5, 'Kralj odgovori i reče zvjezdarima: \"Moja je odluka neopoziva: ako mi ne kažete što sam snio i što san znači, bit ćete rastrgani u komade, a vaše će kuće postati smetišta.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (34, 2, 6, 'No ako mi otkrijete moju sanju i njezino značenje, dobit ćete od mene darove i poklone i velike časti. Otkrijte mi dakle što sam snio i što san znači.\"');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (34, 2, 7, 'Oni opet odgovoriše: \"Neka kralj rekne svoju sanju slugama svojim, a mi ćemo mu otkriti njezino značenje.\"');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (34, 2, 8, 'A kralj: \"Dobro ja znam da želite dobiti na vremenu jer znate da je moja odluka neopoziva.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (34, 2, 9, 'Ako mi ne kažete što sam snio, znači da me namjeravate obmanjivati varavim riječima i izmišljotinama dok nekako ne prođe vrijeme. Stoga, recite mi moj san, pa ću znati da li mi možete kazati i njegovo značenje!\"');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (34, 2, 10, 'Zvjezdari odgovoriše pred kraljem: \"Nema na svijetu čovjeka koji bi takvo što mogao otkriti kralju. I stoga nijedan kralj, ma kako velik i moćan, takvo što ne traži od čarobnika, gataoca ili zvjezdara.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (34, 2, 11, 'Što tražiš, kralju, teško je, i nema ga tko bi to mogao otkriti kralju osim bogova, koji ne borave među smrtnicima.\"');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (34, 2, 12, 'Tada se kralj silno razgnjevi i razbjesni te naredi da se pogube svi mudraci babilonski.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (34, 2, 13, 'Pošto je objavljena naredba da se ubiju mudraci, potražiše i Daniela i njegove drugove da ih pogube.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (34, 2, 14, 'No Daniel se mudrim i umnim riječima obrati na Arjoka, zapovjednika kraljevskih straža, koji bijaše izišao da pogubi mudrace babilonske.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (34, 2, 15, 'On reče Arjoku, zapovjedniku kraljevu: \"Zašto je kralj izdao tako strogu naredbu?\" Arjok pripovjedi Danielu,');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (34, 2, 16, 'a Daniel otiđe kralju i zamoli da mu dade vremena te će kralju otkriti što san znači.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (34, 2, 17, 'Daniel uđe u svoju kuću te sve kaza Hananiji, Mišaelu i Azarji, svojim drugovima,');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (34, 2, 18, 'da mole milosrđe u Boga Nebeskoga radi te tajne, da Daniel i njegovi drugovi ne poginu s drugim mudracima babilonskim.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (34, 2, 19, 'I objavi se tajna Danielu u noćnom viđenju. A Daniel blagoslovi Boga Nebeskoga.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (34, 2, 20, 'Daniel prihvati riječ i reče: \"Bilo ime Božje blagoslovljeno odvijeka dovijeka, njegova je mudrost i sila.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (34, 2, 21, 'On mijenja doba i vremena, ruši i postavlja kraljeve, daje mudrost mudrima a znanje pronicavima.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (34, 2, 22, 'On otkriva dubine i tajne, zna što je u tminama i svjetlost prebiva u njega.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (34, 2, 23, 'Tebe, o Bože otaca mojih, slavim i hvalim što si mi dao mudrost i jakost! Evo, objavio si mi ono što smo te molili, objavio si nam što kralj traži.\"');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (34, 2, 24, 'Daniel ode k Arjoku, kome bijaše kralj naredio da smakne mudrace babilonske. Uđe i reče mu: \"Ne ubijaj mudraca babilonskih! Odvedi me kralju, pa ću mu otkriti što san znači.\"');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (34, 2, 25, 'Arjok žurno odvede Daniela kralju i reče: \"Našao sam među izgnanicima judejskim čovjeka koji će kralju kazati što san znači.\"');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (34, 2, 26, 'Kralj reče Danielu (koji se zvaše Baltazar): \"Jesi li kadar kazati mi san koji sam usnio i što znači?\"');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (34, 2, 27, 'Daniel odgovori pred kraljem: \"Tajnu koju istražuje kralj ne mogahu kralju otkriti mudraci, čarobnici, gataoci i zaklinjači;');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (34, 2, 28, 'ali ima na nebu Bog koji objavljuje tajne i on je saopćio kralju Nabukodonozoru ono što će biti na svršetku dana. Evo tvoje sanje i onoga što ti se prividjelo na postelji:');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (34, 2, 29, 'O kralju, na tvojoj ti postelji dođoše misli o tome što će se dogoditi kasnije, a Otkrivatelj tajna saopćio ti je ono što će biti.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (34, 2, 30, 'Iako nemam mudrosti više nego ostali smrtnici, ta mi je tajna objavljena samo zato da njezino značenje saopćim kralju i da upoznaš misli svoga srca.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (34, 2, 31, 'Ti si, o kralju, imao viđenje: gle, kip, golem kip, vrlo blistav, stajaše pred tobom, strašan za oči.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (34, 2, 32, 'Tome kipu glava bijaše od čistog zlata, prsa i ruke od srebra, trbuh i bedra od mjedi,');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (34, 2, 33, 'gnjati od željeza, a stopala dijelom od željeza, dijelom od gline.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (34, 2, 34, 'Ti si promatrao: iznenada se odvali kamen a da ga ne dodirnu ruka, pa udari u kip, u stopala od željeza i gline te ih razbi.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (34, 2, 35, 'Tada se smrvi najednom željezo i glina, mjed, srebro i zlato, i sve postade kao pljeva na gumnu ljeti i vjetar sve odnese bez traga. A kamen koji bijaše u kip udario postade veliko brdo te napuni svu zemlju.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (34, 2, 36, 'To bijaše sanja; a njezino ćemo značenje reći pred kraljem.\"');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (34, 2, 37, '\"Ti, o kralju, kralju kraljeva, komu Bog Nebeski dade kraljevstvo, silu moć i slavu -');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (34, 2, 38, 'i u čije je ruke stavio, gdje god se našli, sinove ljudske, životinje poljske, ptice nebeske i postavio te gospodarom nad svim time - ti si glava od zlata.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (34, 2, 39, 'Poslije tebe ustat će drugo kraljevstvo, slabije od tvoga, pa treće, od mjedi, koje će gospodariti svom zemljom.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (34, 2, 40, 'A četvrto kraljevstvo bit će tvrdo poput željeza, poput željeza koje sve satire i mrvi; kao željezo koje razbija, skršit će i razbit sva ona kraljevstva.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (34, 2, 41, 'Stopala koja si vidio, dijelom glina a dijelom željezo, jesu podijeljeno kraljevstvo; imat će nešto od čvrstoće željeza prema onome što si vidio željezo izmiješano s glinom.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (34, 2, 42, 'Prsti stopala, dijelom željezo a dijelom glina: kraljevstvo će biti dijelom čvrsto a dijelom krhko.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (34, 2, 43, 'A što si vidio željezo izmiješano s glinom: oni će se miješati ljudskim sjemenom, ali se neće držati zajedno, kao što se ni željezo ne da pomiješati s glinom.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (34, 2, 44, 'U vrijeme ovih kraljeva Bog Nebeski podići će kraljevstvo koje neće nikada propasti i neće prijeći na neki drugi narod. Ono će razbiti i uništiti sva ona kraljevstva, a samo će stajati dovijeka -');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (34, 2, 45, 'kao što si vidio da se kamen s brijega odvalio a da ga ne dodirnu ruka te smrvio željezo, mjed, glinu, srebro i zlato. Veliki je Bog saopćio kralju što se ima dogoditi. Sanja je istinita, a tumačenje joj pouzdano.\"');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (34, 2, 46, 'Nato kralj Nabukodonozor pade ničice i pokloni se pred Danielom. Naredi da mu prinesu dar i kad.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (34, 2, 47, 'I reče kralj Danielu: \"Zaista, vaš je bog Bog nad bogovima i gospodar nad kraljevima, Otkrivatelj tajna, kad si mogao otkriti ovu tajnu.\"');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (34, 2, 48, 'Kralj uzvisi Daniela i dariva ga mnogim blistavim darovima. Postavi ga upraviteljem sve pokrajine babilonske i starješinom svih mudraca babilonskih.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (34, 2, 49, 'Daniel zamoli kralja da odredi za upravitelje pokrajine babilonske Šadraka, Mešaka i Abed Nega, a Daniel ostade na kraljevu dvoru.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (34, 3, 1, 'Kralj Nabukodonozor odredi da se načini zlatni kip, visok šezdeset lakata i širok šest, i da ga postave u ravnici Duri, u pokrajini babilonskoj.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (34, 3, 2, 'Kralj Nabukodonozor pozva satrape, namjesnike, upravitelje, savjetnike, rizničare, suce i zakonoznance i sve namjesnike pokrajina da dođu na posvetu kipa što ga podiže kralj Nabukodonozor.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (34, 3, 3, 'Tada se sakupiše satrapi, namjesnici, upravitelji, savjetnici, rizničari, suci i zakonoznanci i svi namjesnici pokrajinske vlasti na posvetu kipa što ga podiže kralj Nabukodonozor. I stadoše pred kip što podiže Nabukodonozor.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (34, 3, 4, 'Glasnik proglasi: \"O narodi, plemena i jezici, evo što vam se naređuje:');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (34, 3, 5, 'u času kad začujete zvuke roga, frule, citre, sambuke, psaltira, gajda i svakovrsnih drugih glazbala, bacite se na tlo i poklonite se zlatnome kipu što ga podiže kralj Nabukodonozor!');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (34, 3, 6, 'Tko se ne baci na tlo i ne pokloni, bit će smjesta bačen u peć užarenu.\"');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (34, 3, 7, 'Zato, čim začuše zvuk roga, frule, citre, sambuke, psaltira, gajda i svakovrsnih drugih glazbala, baciše se na tlo svi narodi, plemena i jezici klanjajući se zlatnome kipu što ga podiže kralj Nabukodonozor.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (34, 3, 8, 'Uto dođoše neki Kaldejci i optužiše Judejce.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (34, 3, 9, 'Rekoše kralju Nabukodonozoru: \"O kralju, živ bio dovijeka!');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (34, 3, 10, 'Ti si, kralju, naredio svakom čovjeku koji začuje zvuke roga, frule, citre, sambuke, psaltira, gajda i svakovrsnih drugih glazbala da se baci na tlo i da se pokloni zlatnome kipu;');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (34, 3, 11, 'a tko se ne baci na tlo i ne pokloni, da bude bačen u peć užarenu.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (34, 3, 12, 'A evo, ovdje su Judejci koje si postavio za upravitelje pokrajine babilonske: Šadrak, Mešak i Abed Nego. Ti ljudi ne mare za te, o kralju; oni ne štuju tvojih bogova i nisu se poklonili zlatnome kipu što si ga podigao.\"');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (34, 3, 13, 'Nabukodonozor, bijesan i gnjevan, pozva Šadraka, Mešaka i Abed Nega. Odmah ih dovedoše pred kralja.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (34, 3, 14, 'A Nabukodonozor im reče: \"Je li istina, Šadrače, Mešače i Abed Nego, da vi ne štujete mojih bogova i da se ne klanjate zlatnome kipu što ga podigoh?');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (34, 3, 15, 'Jeste li voljni, čim začujete zvuk roga, frule, citre, sambuke, psaltira, gajda i svakovrsnih drugih glazbala, baciti se na tlo i pokloniti se kipu što ga načinih? Ako li mu se ne poklonite, bit ćete smjesta bačeni u peć užarenu; i koji je taj bog koji bi vas izbavio iz ruke moje?\"');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (34, 3, 16, 'Šadrak, Mešak i Abed Nego odgovoriše kralju Nabukodonozoru: \"Ne treba da ti odgovorimo na to.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (34, 3, 17, 'Bog naš, kome služimo, može nas izbaviti iz užarene peći i od ruke tvoje, kralju; on će nas i izbaviti.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (34, 3, 18, 'No ako toga i ne učini, znaj, o kralju: mi nećemo služiti tvojemu bogu niti ćemo se pokloniti kipu što si ga podigao.\"');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (34, 3, 19, 'Na te riječi kralj Nabukodonozor uskipje bijesom, a lice mu se iznakazi na Šadraka, Mešaka i Abed Nega.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (34, 3, 20, 'On naredi da se peć ugrije sedam puta jače no inače i jakim ljudima iz svoje vojske zapovjedi da svežu Šadraka, Mešaka i Abed Nega i bace u peć punu žarkoga ognja.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (34, 3, 21, 'Svezaše ih, dakle, i u plaštevima, obući i kapama baciše u zažarenu peć.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (34, 3, 22, 'Kako kraljeva zapovijed bijaše žurna a peć preko mjere užarena, plamen ubi ljude koji su bacali Šadraka, Mešaka i Abed Nega.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (34, 3, 23, 'A tri čovjeka - Šadrak, Mešak i Abed Nego - padoše svezani u zažarenu peć.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (34, 3, 24, 'I hodahu posred plamena hvaleći Boga, slaveći Gospoda.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (34, 3, 25, 'Stavši Azarja otvori usta i pomoli se usred ognja ovako:');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (34, 3, 26, '\"Blagoslovljen i hvaljen budi, Gospode, Bože otaca naših, i neka ime tvoje bude slavljeno dovijeka!');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (34, 3, 27, 'Pravedan si u svemu što učini nama, sva su tvoja djela istinita, svi tvoji putovi pravi, svi tvoji sudovi istina.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (34, 3, 28, 'Po pravdi si presudio u svemu što si poslao na nas i na sveti grad otaca naših, Jeruzalem: zbog naših si grijeha ovako postupio s nama, u istini i pravednosti.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (34, 3, 29, 'Zgriješili smo i počinili bezakonje odmetnuvši se od tebe, sagriješili teško; ne slušasmo naredbe tvoje.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (34, 3, 30, 'Nismo ih čuvali i nismo vršili što nam bijaše naređeno za naše dobro.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (34, 3, 31, 'Sve što si poslao na nas, sve što si nam učinio, pravedno si učinio.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (34, 3, 32, 'Kad si nas predao u ruke bezakonika, dušmana naših, najgorih odmetnika, i kralju nepravednom, najgorem na zemlji,');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (34, 3, 33, 'te danas ne smijemo otvoriti usta: sramota i ruglo pokrivaju one koji ti služe i tebi se klanjaju.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (34, 3, 34, 'O, ne zapusti nas zauvijek, zbog imena svoga, i ne razvrgni Saveza svoga,');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (34, 3, 35, 'ne uskrati nam svoje milosrđe zbog Abrahama, miljenika svoga; zbog Izaka, sluge svojega; zbog Izraela, sveca svojega,');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (34, 3, 36, 'kojima si obećao umnožit\' potomstvo kao zvijezde nebeske i kao pijesak na obali morskoj.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (34, 3, 37, 'Gospode, postadosmo najmanji među narodima, prezreni po svoj zemlji poradi grijeha svojih.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (34, 3, 38, 'Nemamo sada vojvode, proroka, kneza, paljenice, klanice, prinosa, kada, ni mjesta gdje da prinesemo prvence tebi');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (34, 3, 39, 'Üi da nađemo milosrđe. No primi nas slomljene duše, duha ponizna!');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (34, 3, 40, 'Kao paljenice ovnova i bikova, kao tisuće pretilih janjaca - takva nek\' bude žrtva naša pred tobom danas da nas pomiri s tobom - jer se neće postidjeti oni koji se u te uzdaju.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (34, 3, 41, 'Odsada ćemo svim srcem slijediti tebe, tebe se bojati i tražiti lice tvoje.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (34, 3, 42, 'Ne postidi nas, već postupaj s nama po blagosti svojoj, po velikoj ljubavi svojoj!');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (34, 3, 43, 'Izbavi nas, kao nekoć, čudesima svojim, proslavi ime svoje, Gospode!');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (34, 3, 44, 'Neka se postide oni koji zlo čine slugama tvojim: neka se postide svoga nasilja i neka im sila skršena bude!');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (34, 3, 45, 'Nek\' znaju da si ti jedini Bog i Gospod, slavan po svoj zemlji!\" Anđeo Gospodnji u užarenoj peći');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (34, 3, 46, 'Kraljeve sluge koje ih bijahu bacile u peć neprestano poticahu oganj zemnim uljem, smolom, kučinama i vinjagom,');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (34, 3, 47, 'tako te plamen lizaše četrdeset i devet lakata iznad peći.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (34, 3, 48, 'Buknuvši, spali Kaldejce koji se nađoše oko peći.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (34, 3, 49, 'No Anđeo Gospodnji siđe u peć k Azarji i njegovim drugovima; izagna plamen ognja iz peći');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (34, 3, 50, 'te usred peći puhaše kao rosni lahor, a oganj ih ne dodirnu niti im zadade bol ili kakvu neugodnost. Pjesma triju mladića');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (34, 3, 51, 'Tada sva trojica zapjevaše u peći jednim glasom, slaveći i blagoslivljajući Boga:');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (34, 3, 52, '\"Blagoslovljen budi, Gospodine, Bože otaca naših, hvaljen i uzvisivan dovijeka! Blagoslovljeno, slavno i sveto ime tvoje, hvaljeno i uzvisivano dovijeka!');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (34, 3, 53, 'Blagoslovljen budi u Domu svete slave svoje, hvaljen i slavljen dovijeka!');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (34, 3, 54, 'Blagoslovljen budi na prijestolju kraljevstva svoga, hvaljen i uzvisivan dovijeka!');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (34, 3, 55, 'Blagoslovljen, ti što istražuješ bezdane i sjediš nad kerubima, hvaljen i uzvisivan dovijeka!');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (34, 3, 56, 'Blagoslovljen budi na svodu nebeskom, hvaljen i slavljen dovijeka!');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (34, 3, 57, 'Sva djela Gospodnja, blagoslivljajte Gospoda: hvalite i uzvisujte ga dovijeka!');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (34, 3, 58, 'Anđeli Gospodnji, blagoslivljajte Gospoda: hvalite i uzvisujte ga dovijeka!');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (34, 3, 59, 'Nebesa, blagoslivljajte Gospoda: hvalite i uzvisujte ga dovijeka!');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (34, 3, 60, 'Sve vode nad nebesima, blagoslivljajte Gospoda: hvalite i uzvisujte ga dovijeka!');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (34, 3, 61, 'Sve sile Gospodnje, blagoslivljajte Gospoda: hvalite i uzvisujte ga dovijeka!');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (34, 3, 62, 'Sunce i mjeseče, blagoslivljajte Gospoda: hvalite i uzvisujte ga dovijeka!');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (34, 3, 63, 'Zvijezde nebeske, blagoslivljajte Gospoda: hvalite i uzvisujte ga dovijeka!');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (34, 3, 64, 'Sve kiše i rose, blagoslivljajte Gospoda: hvalite i uzvisujte ga dovijeka!');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (34, 3, 65, 'Svi vjetrovi, blagoslivljajte Gospoda: hvalite i uzvisujte ga dovijeka!');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (34, 3, 66, 'Ognju i žare, blagoslivljajte Gospoda: hvalite i uzvisujte ga dovijeka!');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (34, 3, 67, 'Studeni i vrućino, blagoslivljajte Gospoda: hvalite i uzvisujte ga dovijeka!');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (34, 3, 68, 'Rose i mrazovi, blagoslivljajte Gospoda: hvalite i uzvisujte ga dovijeka!');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (34, 3, 69, 'Lede i studeni, blagoslivljajte Gospoda: hvalite i uzvisujte ga dovijeka!');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (34, 3, 70, 'Tuče i snijezi, blagoslivljajte Gospoda: hvalite i uzvisujte ga dovijeka!');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (34, 3, 71, 'Noći i dani, blagoslivljajte Gospoda: hvalite i uzvisujte ga dovijeka!');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (34, 3, 72, 'Svjetlo i tmino, blagoslivljajte Gospoda: hvalite i uzvisujte ga dovijeka!');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (34, 3, 73, 'Munje i oblaci, blagoslivljajte Gospoda: hvalite i uzvisujte ga dovijeka!');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (34, 3, 74, 'Zemlja neka blagoslivlje Gospoda: neka ga hvali i uzvisuje dovijeka!');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (34, 3, 75, 'Bregovi i brežuljci, blagoslivljajte Gospoda: hvalite i uzvisujte ga dovijeka!');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (34, 3, 76, 'Sve raslinstvo na zemlji, blagoslivljaj Gospoda: hvalite i uzvisujte ga dovijeka!');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (34, 3, 77, 'Izvori, blagoslivljajte Gospoda: hvalite i uzvisujte ga dovijeka!');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (34, 3, 78, 'Mora i rijeke, blagoslivljajte Gospoda: hvalite i uzvisujte ga dovijeka!');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (34, 3, 79, 'Kitovi i sve što se miče u vodama, blagoslivljajte Gospoda: hvalite i uzvisujte ga dovijeka!');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (34, 3, 80, 'Ptice nebeske, blagoslivljajte Gospoda: hvalite i uzvisujte ga dovijeka!');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (34, 3, 81, 'Sve divlje i pitome životinje, blagoslivljajte Gospoda: hvalite i uzvisujte ga dovijeka!');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (34, 3, 82, 'Sinovi ljudski, blagoslivljajte Gospoda: hvalite i uzvisujte ga dovijeka!');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (34, 3, 83, 'Izraele, blagoslivljaj Gospoda: hvali i uzvisuj ga dovijeka!');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (34, 3, 84, 'Svećenici Gospodnji, blagoslivljajte Gospoda: hvalite i uzvisujte ga dovijeka!');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (34, 3, 85, 'Sluge Gospodnje, blagoslivljajte Gospoda: hvalite i uzvisujte ga dovijeka!');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (34, 3, 86, 'Dusi i duše pravednih, blagoslivljajte Gospoda: hvalite i uzvisujte ga dovijeka!');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (34, 3, 87, 'Sveti i ponizni srcem, blagoslivljajte Gospoda: hvalite i uzvisujte ga dovijeka!');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (34, 3, 88, 'Hananijo, Azarjo, Mišaele, blagoslivljajte Gospoda: hvalite i uzvisujte ga dovijeka! Jer on nas je spasio od Podzemlja, on nas je istrgao iz ruke smrti, on nas je izbavio iz peći užarene, on nas je izbavio iz plamena.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (34, 3, 89, 'Slavite Gospoda jer je dobar, jer je vječna ljubav njegova!');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (34, 3, 90, 'Svi štovatelji Gospodnji, blagoslivljajte Boga nad bogovima, hvalite i zahvaljujte, jer vječna je ljubav njegova!\"]');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (34, 3, 91, 'Tada se kralj Nabukodonozor zaprepasti i brzo ustade. Zapita svoje savjetnike: \"Nismo li bacili ova tri čovjeka svezana u oganj?\" Oni odgovoriše: \"Jesmo, kralju!\"');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (34, 3, 92, 'On reče: \"Ali ja vidim četiri čovjeka, odriješeni šeću po vatri i ništa im se zlo ne događa; četvrti je sličan sinu Božjemu.\"');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (34, 3, 93, 'Nabukodonozor priđe vratima užarene peći i viknu: \"Šadrače, Mešače i Abed Nego, sluge Boga Višnjega, iziđite i dođite ovamo!\" Tada iziđoše iz ognja Šadrak, Mešak i Abed Nego.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (34, 3, 94, 'Sakupiše se satrapi, starješine, upravitelji i kraljevi savjetnici da vide te ljude: oganj ne bijaše naudio njihovu tijelu, kosa im na glavi neopaljena, plaštevi im neoštećeni, nikakav se zadah ognja ne bijaše uhvatio njih.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (34, 3, 95, 'Nabukodonozor viknu: \"Blagoslovljen bio Bog Šadrakov, Mešakov i Abed Negov, koji je poslao svog anđela i izbavio svoje sluge, one koji se uzdahu u njega te se ne pokoriše kraljevoj naredbi, već radije predadoše svoje tijelo ognju negoli da štuju ili se klanjaju drugome osim svome Bogu!');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (34, 3, 96, 'Naređujem dakle: O narodi, plemena i jezici, svatko između vas tko bi pogrdio Boga Šadrakova, Mešakova i Abed Negova neka bude raskomadan, a njegova kuća pretvorena u smetlište, jer nema boga koji bi mogao izbaviti kao ovaj.\"');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (34, 3, 97, 'Tada kralj uzvisi Šadraka, Mešaka i Abed Nega na visoke položaje u pokrajini babilonskoj.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (34, 3, 98, 'Nabukodonozor, kralj, svim plemenima, narodima i jezicima po svoj zemlji: Obilovali mirom!');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (34, 3, 99, 'Svidjelo mi se obznaniti vam znakove i čudesa što ih na meni učini Bog Svevišnji. Znakovi njegovi kako su veliki! Čudesa njegova kako silna! Kraljevstvo njegovo - kraljevstvo vječno! Vlast njegova za sva pokoljenja!');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (34, 3, 100, '');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (34, 4, 1, 'Ja, Nabukodonozor, življah mirno u svojoj kući i sretno u svojoj palači,');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (34, 4, 2, 'kad vidjeh sanju koja me uplašila. Utvare i viđenja što su mi se na mom ležaju vrzla po glavi uznemiriše me.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (34, 4, 3, 'I naredih: neka mi pozovu sve mudrace babilonske da mi kažu što sanja znači.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (34, 4, 4, 'Dođoše gataoci, čarobnici, zvjezdari i tumači znakova: ja im rekoh svoju sanju, a oni mi ne znadoše reći njezino značenje.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (34, 4, 5, 'Tada dođe preda me Daniel, koji je nazvan Baltazar prema imenu moga boga, i u komu prebiva duh Boga Svetoga. Ja mu pripovjedih svoju sanju:');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (34, 4, 6, '\"Baltazare, starješino gatalaca, znam da u tebi prebiva duh Boga Svetoga i da ti nijedna tajna nije preteška: evo sanje što je imah: daj mi njezino značenje.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (34, 4, 7, 'Evo viđenja što mi se na postelji vrzlo po glavi: Pogledam, kad evo jedno stablo usred zemlje vrlo veliko.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (34, 4, 8, 'Stablo poraste, postade snažno, visina mu doseže nebo, vidjelo se s krajeva zemlje.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (34, 4, 9, 'Krošnja mu bijaše lijepa, plodovi obilni; na njemu je bilo hrane za sve, u njegovoj sjeni počivaše zvijerje poljsko, na njegovim se granama gnijezdile ptice nebeske i svako se tijelo hranilo od njega.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (34, 4, 10, 'Ja promatrah viđenja što su mi se na mojoj postelji vrzla po glavi kad, evo, Stražar, Svetac, silazi s neba,');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (34, 4, 11, 'silnim glasom viče: \'Posijecite stablo, okrešite mu grane, počupajte mu lišće, pobacajte plodove! Neka se životinje razbjegnu ispod njega i ptice s grana njegovih!');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (34, 4, 12, 'U zemlji ostavite panj i korijenje u gvozdenim i mjedenim okovima, u travi poljskoj! Neka ga pere rosa nebeska, i travu zemaljsku neka dijeli sa zvijerjem poljskim!');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (34, 4, 13, 'Neka mu se promijeni srce čovječje, srce životinjsko nek\' mu se dade! Sedam vremena neka prođe nad njim!');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (34, 4, 14, 'Tako su presudili Stražari, tako su odlučili Sveci, da sve živo upozna kako Svevišnji ima vlast nad kraljevstvom ljudskim: on ga daje kome hoće i postavlja nad njim najnižega od ljudi!\'');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (34, 4, 15, 'Ovo je sanja što je vidjeh ja, kralj Nabukodonozor. A ti, Baltazare, reci mi njezino značenje, jer mi nijedan od mudraca moga kraljevstva to ne može reći; ti možeš, jer u tebi je duh Boga Svetoga.\"');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (34, 4, 16, 'Tada se Daniel, nazvan Baltazar, načas smete i prestraši u svojim mislima. Kralj reče: \"Baltazare, ne daj se zbuniti ovom sanjom i njezinim značenjem!\" Baltazar odgovori: \"Gospodaru moj, ova sanja neka bude tvojim dušmanima i njezino značenje tvojim mrziteljima!');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (34, 4, 17, 'Stablo koje si vidio, veliko i snažno, koje seže sve do neba i vidi se po svoj zemlji,');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (34, 4, 18, 'krošnje lijepe i plodova obilnih na kojem bijaše hrane za sve i pod kojim počiva zvijerje poljsko, a na njegovim se granama gnijezde ptice nebeske:');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (34, 4, 19, 'to si ti, o kralju, koji si velik i moćan, veličina ti se povećala i dosegla do neba, a tvoja vlast do krajeva zemlje.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (34, 4, 20, 'A što je vidio kralj kako Stražar, Svetac, silazi s neba te govori: \'Posijecite stablo, raskomadajte ga, no njegov panj i korijenje ostavite u zemlji, u gvozdenim i mjedenim okovima, u travi poljskoj, neka ga pere rosa nebeska i dio neka mu bude sa zvijerjem poljskim dok ne prođe sedam vremena nad njim\' -');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (34, 4, 21, 'ovo je značenje, o kralju, odluka Svevišnjega što će se ispuniti na mom gospodaru kralju:');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (34, 4, 22, 'Izagnat će te iz društva ljudi i sa životinjama ćeš poljskim boraviti; hranit ćeš se travom kao goveda, tebe će prati rosa nebeska; sedam će vremena proći nad tobom dok ne upoznaš da Svevišnji ima vlast nad kraljevstvom ljudskim i da ga daje kome on hoće.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (34, 4, 23, 'A što se reklo \'Ostavite panj i korijenje stabla\' - tvoje će se kraljevstvo obnoviti čim spoznaš da Nebesa imaju svu vlast.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (34, 4, 24, 'Zato, kralju, neka ti bude mio moj savjet: iskupi svoje grijehe pravednim djelima i svoja bezakonja milosrđem prema siromasima, da bi ti potrajala sreća.\"');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (34, 4, 25, 'Sve se to dogodi kralju Nabukodonozoru.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (34, 4, 26, 'Dvanaest mjeseci kasnije, šetajući babilonskim kraljevskim dvorom,');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (34, 4, 27, 'kralj govoraše: \"Nije li to taj veliki Babilon što ga ja sagradih da mi bude kraljevskom prijestolnicom - snagom svoje moći, na slavu svoga veličanstva?\"');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (34, 4, 28, 'Još bijahu te riječi u ustima njegovim kad s neba dođe glas: \"Tebi se objavljuje, kralju Nabukodonozore! Kraljevstvo ti se oduzelo;');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (34, 4, 29, 'bit ćeš izagnan iz društva ljudi, sa životinjama ćeš poljskim boraviti; hranit ćeš se travom kao goveda, i sedam će vremena proći nad tobom dok ne spoznaš da Svevišnji ima vlast nad kraljevstvom ljudskim, i da ga on daje kome hoće.\"');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (34, 4, 30, 'I smjesta se riječ izvrši na Nabukodonozoru: bi izagnan iz društva ljudi, jeđaše travu kao goveda, prala ga rosa nebeska; vlasi mu narastoše poput orlova perja, a njegovi nokti kao ptičje pandže.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (34, 4, 31, '\"Pošto se navršiše određeni dani, ja, Nabukodonozor, podigoh oči prema nebu, razum mi se vrati, tada blagoslovih Svevišnjega hvaleći i uzvisujući onoga koji živi dovijeka: njegovo je kraljevstvo - kraljevstvo vječno, njegova je vlast za sva pokoljenja.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (34, 4, 32, 'Stanovnici zemlje - upravo kao da ih i nema: po svojoj volji postupa on s vojskom nebeskom i sa žiteljima zemaljskim. Nitko ne može zaustaviti njegovu ruku ili mu kazati: \'Što to radiš?\'');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (34, 4, 33, 'U isti čas razum mi se vrati, i na slavu moje kraljevske časti vrati mi se veličanstvo i sjaj; moji me savjetnici i velikaši potražiše, bih uspostavljen u kraljevsku čast i moja veličina još poraste.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (34, 4, 34, 'Sada ja, Nabukodonozor, hvalim, uzvisujem i slavim Kralja nebeskoga, čija su sva djela istina, svi putovi pravda i koji može poniziti one koji hode u oholosti.\"');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (34, 5, 1, 'Kralj Baltazar priredi veliku gozbu tisući svojih velikaša; s njima je pio vino.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (34, 5, 2, 'Opijen vinom, Baltazar naredi da se donese zlatno i srebrno suđe koje njegov otac Nabukodonozor bijaše oteo iz jeruzalemskog Svetišta, pa da iz njega pije kralj, njegovi velikaši, njegove žene i suložnice.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (34, 5, 3, 'Donesoše dakle zlatno i srebrno suđe oteto iz Božjega doma u Jeruzalemu i stadoše piti iz njega kralj i njegovi velikaši, njegove žene i suložnice.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (34, 5, 4, 'Pili su vino i slavili svoje bogove od zlata i srebra, mjedi i željeza, drva i kamena.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (34, 5, 5, 'Iznenada se pojaviše prsti čovječje ruke koji stadoše pisati, nasuprot velikom svijećnjaku, po okrečenu zidu kraljevskog dvora, i kralj vidje dlan ruke koja pisaše.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (34, 5, 6, 'Kralj problijedje, misli ga uznemiriše, zglobovi njegovih kukova popustiše i koljena mu stadoše udarati jedno o drugo.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (34, 5, 7, 'Glasno dozva čarobnike, zvjezdare i gataoce. I reče kralj mudracima babilonskim: \"Tko pročita ovo pismo i otkrije mi njegov smisao, bit će obučen u grimiz, oko vrata nosit će zlatan lanac i bit će treći u kraljevstvu.\"');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (34, 5, 8, 'Pristupe svi mudraci kraljevi, ali ne mogoše pročitati pismo niti mu otkriti značenje.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (34, 5, 9, 'Kralj se Baltazar zbog toga silno uplaši, problijedje, a njegovi velikaši ostadoše zbunjeni.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (34, 5, 10, 'Kraljica, čuvši riječi kralja i velikaša, uđe u gozbenu dvoranu i reče: \"Kralju, živ bio dovijeka! Neka se tvoje misli ne uznemiruju i tvoje lice neka ne blijedi!');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (34, 5, 11, 'Ima u tvome kraljevstvu čovjek u kome prebiva duh Boga Svetoga. Još za vremena tvoga oca nađe se u njemu svjetlo, razum i mudrost slična mudrosti bogova. I zato ga kralj Nabukodonozor, otac tvoj, imenova starješinom čarobnika, gatalaca, zvjezdara i mudraca.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (34, 5, 12, 'Budući da se u tom Danielu - koga kralj bijaše nazvao Baltazarom - našao duh izvanredan, znanje, bistrina, vještina da tumači sanje, da rješava zagonetke i da razrješuje teškoće, pozovi stoga Daniela i on će ti kazati značenje.\"');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (34, 5, 13, 'Dovedoše Daniela pred kralja, a kralj ga upita: \"Jesi li ti Daniel, jedan od izgnanika judejskih koje dovede iz Judeje kralj moj otac?');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (34, 5, 14, 'Čujem da duh Božji prebiva na tebi i da je u tebi svjetlo, razum i mudrost izvanredna.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (34, 5, 15, 'Dovedoše mi mudrace i čarobnike da pročitaju ovo pismo i da mi reknu njegovo značenje, ali oni nisu kadri otkriti mi njegov smisao.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (34, 5, 16, 'A čujem da si ti kadar dati tumačenja i da razrješuješ teškoće. Ako si dakle kadar pročitati ovo pismo i reći mi njegovo značenje, bit ćeš odjeven u grimiz i nosit ćeš zlatan lanac oko vrata i bit ćeš treći u kraljevstvu.\"');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (34, 5, 17, 'Daniel prihvati riječ i odgovori kralju: \"Tvoji darovi neka ti ostanu, i svoje poklone daj drugima! A ja ću pročitati ovo pismo kralju i kazat ću mu njegovo značenje.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (34, 5, 18, 'O kralju, Bog je Svevišnji dao kraljevstvo, veličinu, veličanstvo i slavu Nabukodonozoru, ocu tvome.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (34, 5, 19, 'Zbog veličine koju mu bijaše dao drhtahu od straha pred njim narodi, plemena i jezici: on ubijaše po svojoj volji, ostavljaše na životu koga je htio, uzdizaše koga je htio, ponizivaše koga je htio.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (34, 5, 20, 'No kad mu se srce uzdiglo i duh uzobijestio do drskosti, tada bi oboren sa svoga kraljevskog prijestolja i slava mu bijaše oduzeta.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (34, 5, 21, 'Bi izagnan iz ljudskog društva i srce mu posta slično životinjskom: prebivaše s divljim magarcima; poput goveda jeđaše travu; nebeska je rosa prala njegovo tijelo, dok ne spozna da Svevišnji Bog ima vlast nad kraljevstvom ljudskim i stavlja mu na čelo onoga koga on hoće.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (34, 5, 22, 'No ti, Baltazare, sine njegov, nisi ponizio srce svoje, iako si znao sve ovo:');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (34, 5, 23, 'ti si se podigao protiv Gospoda Nebeskoga, dao si da ti donesu suđe iz njegova Doma i pili ste vino iz njega ti, tvoji velikaši, tvoje žene i tvoje suložnice, hvaleći bogove od zlata i srebra, od mjedi i željeza, od drva i kamena, koji ne vide, ne čuju niti razumiju, a nisi dao slavu Bogu koji u svojoj ruci drži dah tvoj i sve tvoje putove.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (34, 5, 24, 'I zato on posla ovu ruku koja napisa ovo pismo.\"');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (34, 5, 25, '\"A evo što je napisano: Mene, Mene, Tekel, Parsin.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (34, 5, 26, 'A te riječi znače: Mene: izmjerio je Bog tvoje kraljevstvo i učinio mu kraj;');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (34, 5, 27, 'Tekel: bio si vagnut na tezulji i nađen si prelagan;');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (34, 5, 28, 'Parsin: razdijeljeno je tvoje kraljevstvo i predano Medijcima i Perzijancima.\"');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (34, 5, 29, 'Tada Baltazar naredi da Daniela obuku u grimiz, da mu oko vrata objese zlatan lanac i da ga proglase trećim u kraljevstvu.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (34, 5, 30, 'Iste te noći kaldejski kralj Baltazar bi ubijen.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (34, 6, 1, 'A Darije Medijac preuze kraljevstvo, star već šezdeset i dvije godine.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (34, 6, 2, 'Svidjelo se Dariju da postavi nad svojim kraljevstvom stotinu i dvadeset satrapa da budu nad svim kraljevstvom.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (34, 6, 3, 'Njima na čelo stavi tri pročelnika - Daniel bijaše jedan od njih - kojima će satrapi polagati račun da se ne bi dosađivalo kralju.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (34, 6, 4, 'Daniel se toliko isticaše svojim izvanrednim duhom iznad pročelnika i satrapa te kralj mišljaše da ga postavi nad svim kraljevstvom.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (34, 6, 5, 'Tada pročelnici i satrapi stadoše tražiti povod, štogod oko državne uprave, zbog čega bi mogli optužiti Daniela; ali ne mogoše na njemu naći ništa takvo, ništa zbog čega bi ga prekorili, jer bijaše vjeran, na njemu ni nemara ni ogrešenja.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (34, 6, 6, 'Ti ljudi rekoše tada: \"Nećemo naći nikakva povoda protiv Daniela, osim da nađemo nešto protiv njega u zakonu njegova Boga.\"');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (34, 6, 7, 'Tada pročelnici i satrapi navališe na kralja te mu rekoše: \"O kralju Darije, živ bio dovijeka!');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (34, 6, 8, 'Svi pročelnici kraljevstva, predstojnici i satrapi, savjetnici i namjesnici složiše se u tome da bi trebalo da kralj izda naredbu i zabranu: svaki onaj koji bi u roku od trideset dana upravio molbu bilo na kojega boga ili čovjeka, osim na tebe, o kralju, bit će bačen u lavsku jamu.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (34, 6, 9, 'O kralju, potvrdi tu zabranu i potpiši naredbu da bude neopoziva prema nepromjenljivom medijsko-perzijskom zakonu!\"');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (34, 6, 10, 'Nato kralj Darije potpisa pismo i zabranu.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (34, 6, 11, 'Saznavši Daniel da je spis potpisan, otiđe u svoju kuću. Prozori gornje sobe bijahu otvoreni prema Jeruzalemu. Tu je on tri puta na dan padao na koljena blagoslivljajući, moleći i hvaleći Boga, kako je uvijek činio.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (34, 6, 12, 'Oni ljudi nahrupiše i nađoše Daniela gdje moli i zaziva svoga Boga.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (34, 6, 13, 'Tada odoše i pred kraljem se pozvaše na kraljevsku zabranu: \"Zar ti nisi potpisao zabranu prema kojoj će svaki onaj koji bi u vremenu od trideset dana upravio molbu na nekoga boga ili čovjeka, osim na tebe, o kralju, biti bačen u lavsku jamu?\" Kralj odgovori: \"Tako je odlučeno po nepromjenljivom medijsko-perzijskom zakonu.\"');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (34, 6, 14, 'Tada rekoše kralju: \"Daniel, onaj od izgnanika judejskih, ne mari za tebe, o kralju, ni za tvoju zabranu koju si potpisao: tri puta na dan obavlja svoju molitvu.\"');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (34, 6, 15, 'Čuvši te riječi, kralj se vrlo ražalosti i odluči spasiti Daniela. Sve do sunčeva zalaza nastojaše da ga spasi.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (34, 6, 16, 'Ali oni ljudi navališe na kralja govoreći: \"Znaj, o kralju, da prema medijsko-perzijskom zakonu nijedna kraljevska zabrana ili odluka ne može biti opozvana!\"');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (34, 6, 17, 'Tada kralj naredi da dovedu Daniela i da ga bace u lavsku jamu. Kralj reče Danielu: \"Bog tvoj, kome tako postojano služiš, neka te izbavi.\"');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (34, 6, 18, 'Donesoše kamen i staviše ga jami na otvor. Kralj ga zapečati prstenom svojim i prstenom svojih velikaša, da se ništa ne mijenja za Daniela.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (34, 6, 19, 'Kralj se vrati u svoj dvor i provede noć ne okusivši jela i ne dopustivši da mu dovedu suložnice. Nije mogao usnuti.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (34, 6, 20, 'Kralj ustade u ranu zoru, kad se danilo, i pođe brzo k lavskoj jami.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (34, 6, 21, 'Kad se primače blizu, viknu žalosnim glasom Danielu: \"Daniele, slugo Boga živoga, je li te Bog, kome postojano služiš, mogao izbaviti od lavova?\"');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (34, 6, 22, 'Daniel odgovori: \"O kralju, živ bio dovijeka!');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (34, 6, 23, 'Moj je Bog poslao svog Anđela; zatvorio je ralje lavovima te mi ne naudiše, jer sam nedužan pred njim. Pa i pred tobom, o kralju, ja sam bez krivice.\"');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (34, 6, 24, 'Kralj se vrlo obradova i naredi da Daniela izvade iz jame. Izvadiše Daniela iz jame neozlijeđena, jer se bijaše uzdao u svoga Boga.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (34, 6, 25, 'Kralj zapovjedi da dovedu one ljude koji bijahu optužili Daniela i da ih bace u lavsku jamu - njih, njihove žene i njihovu djecu: i prije nego dodirnuše tlo, lavovi ih zgrabiše i smrviše im kosti.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (34, 6, 26, 'Nato kralj Darije napisa svim plemenima, narodima i jezicima što stanuju po svoj zemlji: \"Obilovali mirom!');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (34, 6, 27, 'Evo naredbe koju donosim: u svemu mojem kraljevstvu neka se ljudi boje i neka dršću pred Bogom Danielovim: On je Bog živi, on ostaje dovijeka! Njegovo kraljevstvo neće propasti, njegovoj vlasti nema kraja!');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (34, 6, 28, 'On izbavlja i spasava, čini znake i čudesa na nebesima i na zemlji! On je spasio Daniela iz šapa lavljih!\"');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (34, 6, 29, 'Daniel bijaše sretan za vladanja Darija i za vladanja Kira Perzijanca.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (34, 7, 1, 'Prve godine Baltazara, kralja babilonskoga, usni Daniel san: utvare mu se na postelji vrzle glavom. Sažeto zapisa što je usnio.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (34, 7, 2, 'Kazivaše ovako: Noću u viđenju pogledah, kad eno: četiri vjetra nebeska uzbibaše veliko more.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (34, 7, 3, 'Četiri goleme nemani iziđoše iz mora, svaka drukčija. Prva bijaše kao lav, a krila joj orlovska.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (34, 7, 4, 'Dok je promatrah, krila joj se iščupaše, diže se ona sa zemlje i uspravi na noge kao čovjek, i bijaše joj dano srce čovječje.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (34, 7, 5, 'Kad eno druga neman: gle, sasvim drukčija: kao medvjed, s jedne strane uspravljena, tri joj rebra u raljama, među zubima. I bijaše joj rečeno: \"Ustani, nažderi se mesa!\"');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (34, 7, 6, 'Gledah dalje, i evo: treća neman kao leopard, na leđima joj četiri ptičja krila: imaše četiri glave, i dana joj je moć.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (34, 7, 7, 'Zatim, u noćnim viđenjima, pogledah, kad eno: četvrta neman, strahovita, užasna, izvanredno snažna: imaše velike gvozdene zube; ona žderaše, mrvljaše, a što preostade, gazila je nogama. Razlikovala se od prijašnjih nemani i imaše deset rogova.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (34, 7, 8, 'Promatrah joj rogove, i gle: među njima poraste jedan mali rog; i pred tim se rogom iščupaše tri prijašnja roga. I gle, na tome rogu oči kao oči čovječje i usta koja govorahu velike hule.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (34, 7, 9, 'Gledao sam: Prijestolja bjehu postavljena i Pradavni sjede. Odijelo mu bijelo poput snijega; vlasi na glavi kao čista vuna. Njegovo prijestolje kao plamenovi ognjeni i točkovi kao žarki oganj.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (34, 7, 10, 'Rijeka ognjena tekla, izvirala ispred njega. Tisuću tisuća služahu njemu, mirijade stajahu pred njim. Sud sjede, knjige se otvoriše.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (34, 7, 11, 'Ja gledah tada, zbog buke velikih hula što ih govoraše rog, i dok gledah, neman bi ubijena, njezino tijelo raskomadano i predano ognju.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (34, 7, 12, 'Ostalim nemanima vlast bi oduzeta, ali im duljina života bi na jedno vrijeme i rok.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (34, 7, 13, 'Gledah u noćnim viđenjima i gle, na oblacima nebeskim dolazi kao Sin čovječji. On se približi Pradavnome i dovedu ga k njemu.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (34, 7, 14, 'Njemu bi predana vlast, čast i kraljevstvo, da mu služe svi narodi, plemena i jezici. Vlast njegova vlast je vječna i nikada neće proći, kraljevstvo njegovo neće propasti.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (34, 7, 15, 'Meni, Danielu, smete se zbog toga sav duh, viđenja mi se vrzoše glavom, svega me prestraviše.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (34, 7, 16, 'Pristupih jednome od onih koji stajahu ondje i zamolih ga da mi rekne istinu o svemu tome. On mi odgovori i kaza mi značenje:');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (34, 7, 17, '\"One četiri goleme nemani jesu četiri kralja koji će se dići na zemlji.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (34, 7, 18, 'Ali će od njih kraljevstvo preuzeti Sveci Svevišnjega i oni će ga posjedovati za vijeke vjekova.\"');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (34, 7, 19, 'Zaželjeh tada saznati istinu o četvrtoj nemani, onoj koja se razlikovaše od svih drugih, bila izvanredno strašna, imala gvozdene zube i mjedene pandže i koja je žderala i mrvila i nogama gazila što preostajaše;');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (34, 7, 20, 'i o deset rogova što bijahu na njezinoj glavi, i o drugom rogu koji poraste dok tri prva otpadoše - o rogu koji imaše oči i usta što govorahu velike hule i koji bijaše veći nego drugi rogovi.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (34, 7, 21, 'I gledao sam kako ovaj rog ratuje protiv Svetaca te ih nadvladava,');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (34, 7, 22, 'dok ne dođe Pradavni, koji dosudi pravdu Svecima Svevišnjega, i dok ne dođe vrijeme kad Sveci zaposjedoše kraljevstvo.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (34, 7, 23, 'On reče: \"Četvrta neman bit će četvrto kraljevstvo na zemlji, različito od svih kraljevstava. Progutat će svu zemlju, zgazit\' je i smrviti.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (34, 7, 24, 'A deset rogova: Od ovoga kraljevstva nastat će deset kraljeva, a iza njih će se podići jedan drugi različit od onih prvih - i oborit će tri kralja.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (34, 7, 25, 'On će huliti na Svevišnjega, zatirati Svece Svevišnjega; pomišljat će da promijeni blagdane i Zakon, i Sveci će biti predani u njegove ruke na jedno vrijeme i dva vremena i polovinu vremena.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (34, 7, 26, 'Tada će sjesti Sud, vlast mu oduzeti, razoriti, sasvim uništiti.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (34, 7, 27, 'A kraljevstvo, vlast i veličanstvo pod svim nebesima dat će se puku Svetaca Svevišnjega. Kraljevstvo njegovo kraljevstvo je vječno, i sve vlasti služit će mu i pokoravati se njemu.\"');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (34, 7, 28, 'Ovdje se završava izvještaj. Ja, Daniel, bijah vrlo potresen u svojim mislima i lice mi problijedje, ali sve ovo sačuvah u srcu svojemu.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (34, 8, 1, 'Treće godine kralja Baltazara ukaza se meni, Danielu, viđenje poslije onoga koje mi se ukazalo prije.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (34, 8, 2, 'Gledah viđenje, i dok gledah, nađoh se u Šušanu, čvrstu gradu u pokrajini Elamu; i u viđenju se vidjeh na rijeci Ulaju.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (34, 8, 3, 'Podigoh oči, i gle: ovan stajaše kraj rijeke. Imaše dva roga: oba roga visoka, no jedan viši nego drugi, a onaj viši narastao poslije.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (34, 8, 4, 'Gledah kako ovan bode na zapad, na sjever i jug. Nijedna mu se životinja ne mogaše oprijeti, ništa mu ne mogaše izbjeći. Činio je što je htio, osilio se.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (34, 8, 5, 'Dok sam promatrao, gle: jarac dolazi sa zapada povrh sve zemlje, ne dodirujući tla; jarac imaše silan rog među očima.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (34, 8, 6, 'Približi se dvorogom ovnu kojega bijah vidio gdje stoji kraj rijeke i potrča na njega u svoj žestini svoje snage.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (34, 8, 7, 'Vidjeh kako se približi ovnu: bijesno udari na ovna i slomi mu oba roga, a ovan nije imao snage da mu se opre; obori ga jarac na zemlju i stade ga nogama gaziti; nikoga ne bijaše da spasi ovna.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (34, 8, 8, 'Jarac osili veoma, ali kad osili, veliki se rog slomi, a na njegovu mjestu izrastoše četiri velika roga prema četiri vjetra nebeska.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (34, 8, 9, 'Iz jednoga od njih izbi malen rog, ali taj silno poraste prema jugu i istoku, prema Divoti.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (34, 8, 10, 'On poraste sve do Nebeske vojske, obori na zemlju neke iz Vojske i od zvijezda pa ih zgazi nogama.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (34, 8, 11, 'Poraste sve do Zapovjednika Vojske, oduze mu svagdašnju žrtvu i razori mu njegovo Sveto mjesto.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (34, 8, 12, 'Vojska se digla na žrtvu svagdašnju zbog opačine, na zemlju oborila istinu i uspje u svemu što činjaše.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (34, 8, 13, 'Tada čuh gdje jedan Svetac govori, a drugi Svetac upita onoga koji govoraše: \"Dokle će trajati ovo viđenje o svagdašnjoj žrtvi i o opačini što pustoši i gazi Svetište i Vojsku?\"');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (34, 8, 14, 'Odgovori: \"Još dvije tisuće i tri stotine večeri i jutara; tada će Svetište biti očišćeno.\"');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (34, 8, 15, 'Kad sam ja, Daniel, gledajući ovo viđenje, tražio da ga razumijem, gle, preda me stade kao neki čovjek.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (34, 8, 16, 'Začuh glas čovječji gdje viče preko Ulaja: \"Gabriele, objasni mu to viđenje!\"');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (34, 8, 17, 'On pođe onamo gdje stajah i kad mi se približi, strah me obuze i padoh na lice. On mi reče: \"Sine čovječji, razumij: jer ovo je viđenje za vrijeme posljednje.\"');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (34, 8, 18, 'On još govoraše, a ja se onesvijestih, padoh na zemlju. On me dotače i uspravi na mom mjestu.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (34, 8, 19, 'I reče: \"Evo, kazat ću ti što će doći na kraju gnjeva, najavljeni svršetak.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (34, 8, 20, 'Ovan što si ga vidio - njegova dva roga - to su kraljevi Medije i Perzije.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (34, 8, 21, 'Rutavi jarac jest kralj Grčke; veliki rog među njegovim očima jest prvi kralj;');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (34, 8, 22, 'slomljeni rog i četiri roga što izbiše na njegovu mjestu, to su četiri kraljevstva što će izići iz njegova naroda, ali neće imati njegovu moć.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (34, 8, 23, 'I potkraj njihova kraljevanja, kad bezakonici navrše mjeru, ustat će kralj, drzak i lukav.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (34, 8, 24, 'Njegova će moć porasti, ali ne svojom snagom; nesmiljeno će pustošiti, uspijevat će u svojim pothvatima, zatirat\' junake i narod Svetaca.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (34, 8, 25, 'Zbog njegove lukavosti prijevara će uspijevati u njegovoj ruci. On će se uznijeti u svome srcu, iz čista mira upropastit će mnoge. Suprotstavit će se Knezu nad knezovima, ali će - ne rukom - biti skršen.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (34, 8, 26, 'Viđenje o večerima i jutrima o kojem je bilo govora istinito je; no ti ga zapečati, jer je za daleke dane.\"');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (34, 8, 27, 'Tada ja, Daniel, obnemogoh i bijah bolestan više dana. Zatim ustadoh da vršim kraljevske poslove. Bijah smeten zbog viđenja, no nitko to nije dokučio.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (34, 9, 1, 'Prve godine Darija, sina Artakserksova, iz roda Medijaca, koji vladaše kraljevstvom kaldejskim,');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (34, 9, 2, 'prve dakle godine njegova kraljevanja, ja, Daniel, istraživah u Pismima broj godina koje se - prema riječi koju Jahve uputi proroku Jeremiji - imaju ispuniti nad ruševinama Jeruzalema: sedamdeset godina.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (34, 9, 3, 'Ja obratih svoje lice prema Gospodinu Bogu nastojeći moliti se i zaklinjati u postu, kostrijeti i pepelu.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (34, 9, 4, 'Ja se moljah Jahvi, Bogu svome, priznavajući: \"Ah, Gospodine moj, Bože veliki i strahoviti, koji čuvaš Savez i naklonost onima koji tebe ljube i čuvaju zapovijedi tvoje!');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (34, 9, 5, 'Mi sagriješismo, mi bezakonje počinismo, zlo učinismo, odmetnusmo se i udaljismo od zapovijedi i naredaba tvojih.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (34, 9, 6, 'Nismo slušali sluge tvoje, proroke koji govorahu u tvoje ime našim kraljevima, našim knezovima, našim očevima, svemu puku zemlje.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (34, 9, 7, 'U tebe je, Gospodine, pravednost, a u nas stid na obrazu, kao u ovaj dan, u nas Judejaca, Jeruzalemaca, svega Izraela, blizu i daleko, u svim zemljama kuda si ih rastjerao zbog nevjernosti kojom ti se iznevjeriše.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (34, 9, 8, 'Jahve, stid na obraz nama, našim kraljevima, našim knezovima, našim očevima, jer sagriješismo protiv tebe!');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (34, 9, 9, 'U Gospoda je Boga našega smilovanje i oproštenje jer smo se odmetnuli od njega');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (34, 9, 10, 'i nismo slušali glas Jahve, Boga našega, da slijedimo njegove zakone što nam ih dade po svojim slugama, prorocima.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (34, 9, 11, 'Sav je Izrael prestupio Zakon tvoj, odmetnuo se ne slušajući tvoj glas. Zato se na nas izlila kletva i prokletstvo, kako je zapisano u Zakonu Mojsija, sluge Božjega - jer sagriješismo protiv Njega.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (34, 9, 12, 'Izvršio je prijetnje kojima je zaprijetio nama i sucima koji su nam sudili: svalio je na nas tešku nesreću te se ne dogodi pod nebom što se dogodi u Jeruzalemu.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (34, 9, 13, 'Sva ova nesreća, kao što je zapisano u Zakonu Mojsijevu, došla je na nas, a mi nismo umilostivili lice Jahve, Boga svojega: nismo se obratili od svojih bezakonja pa da prionemo uz istinu tvoju.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (34, 9, 14, 'Jahve je bdio nad nesrećom, on je dovede na nas. Jer je pravedan Jahve, Bog naš, u svim djelima koja učini, a mi nismo slušali glas njegov.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (34, 9, 15, 'A sada, Gospode, Bože naš, koji si moćnom svojom rukom izveo narod svoj iz zemlje egipatske - i time sebi stekao ime koje traje do danas: mi sagriješismo, mi zlo učinismo.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (34, 9, 16, 'Gospode, po svoj pravednosti svojoj odvrati svoj gnjev i svoju jarost od Jeruzalema, grada svojega, Svete gore svoje, jer zbog naših grijeha i zlodjela naših otaca Jeruzalem i tvoj narod ruglo su svima koji nas okružuju.\"');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (34, 9, 17, '\"A sada poslušaj, o Bože naš, molitvu sluge svoga i usrdne molbe njegove. Neka tvoje lice zasja nad svetištem tvojim opustošenim - zbog tebe, Gospode!');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (34, 9, 18, 'Prikloni uho svoje, Bože moj, i slušaj! Otvori oči te pogledaj našu pustoš i grad koji se tvojim zove imenom! Jer mi te ne molimo zbog svoje pravednosti, već zbog velikih smilovanja tvojih.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (34, 9, 19, 'Gospode, čuj! Gospode, oprosti! Gospode, poslušaj i čini! Ne oklijevaj - zbog sebe, Bože moj, jer se tvojim imenom zove grad tvoj i narod tvoj!\"');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (34, 9, 20, 'Ja sam još govorio, moleći se i priznavajući grijehe svoje i grijehe svog naroda Izraela i usrdno zaklinjući Jahvu, svoga Boga, za Svetu goru Boga svoga.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (34, 9, 21, 'Dok sam dakle ja još govorio moleći se, onaj čovjek Gabriel, koga vidjeh na početku viđenja, doletje u brzu letu, dotače me se u vrijeme večernjeg prinosa');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (34, 9, 22, 'i pouči me: \"Daniele, evo me: dođoh da te poučim.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (34, 9, 23, 'Od početka tvoje molitve izišla je riječ, i ja dođoh da ti je navijestim. Ti si miljenik. Pazi dobro na riječ, razumij viđenje.\"');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (34, 9, 24, '\"Sedamdeset je sedmica određeno tvom narodu i tvom svetom gradu da se dokrajči opačina, da se stavi pečat grijehu, da se zadovolji za bezakonje, da se uvede vječna pravednost, da se stavi pečat viđenju i prorocima, da se pomaže Sveti nad svetima.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (34, 9, 25, 'Znaj i razumij: Od časa kad izađe riječ \'Neka se vrate i neka opet sagrade Jeruzalem\' pa do Kneza Pomazanika: sedam sedmica, a onda šezdeset i dvije sedmice, i bit će opet sagrađeni trg i opkop, i to u teško vrijeme.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (34, 9, 26, 'A poslije šezdeset i dvije sedmice bit će Pomazanik pogubljen, ali ne za sebe. Narod jednog kneza koji će doći razorit će Grad i Svetište: svršetak im je u propasti, a do svršetka rat i određena pustošenja.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (34, 9, 27, 'I sklopit će savez s mnogima za jednu sedmicu: a u polovici sedmice prestat će žrtva i prinos: na vrhu Hrama bit će grozota pustoši sve do svršetka, dok se određeno pustošenje ne obori na pustošnika.\"');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (34, 10, 1, 'Treće godine Kira, kralja perzijskoga, Danielu, prozvanome Baltazar, bi objavljena riječ - riječ istinita: velik rat. On je nastojao razumjeti riječ, i razumijevanje bi mu dano u viđenju.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (34, 10, 2, 'U te dane ja, Daniel, žalovao sam tri sedmice:');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (34, 10, 3, 'nisam jeo tečnih jela; meso ni vino nije ulazilo u moja usta i nisam se mazao uljem dok ne prođoše te tri sedmice.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (34, 10, 4, 'Dvadeset i četvrtoga dana prvog mjeseca bijah na obali velike rijeke Tigrisa;');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (34, 10, 5, 'podigoh oči da vidim, i gle: Čovjek odjeven u lanene haljine, oko pasa mu pojas od zlata ofirskoga,');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (34, 10, 6, 'tijelo mu poput krizolita, lice kao munja, oči kao baklje ognjene, ruke i noge poput mjedi uglađene, zvuk riječi njegovih kao žamor mnoštva.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (34, 10, 7, 'Jedini ja, Daniel, gledah ovo viđenje, ljudi koji bijahu sa mnom ne vidješe ga, ali ih spopade silan strah te pobjegoše da se sakriju.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (34, 10, 8, 'Ostadoh sam gledajući to veliko viđenje; onemoćah, lice mi problijedje, iznakazi se, snaga me ostavi.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (34, 10, 9, 'Začuh glas njegovih riječi, i kad razabrah glas, onesvijestih se i padoh licem na zemlju.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (34, 10, 10, 'I gle: ruka me dotače i pomože mi da se uprem na koljena i na dlanove.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (34, 10, 11, 'On mi reče: \"Daniele, miljeniče, pripazi na riječi koje ću ti kazati! Ustani, jer ja sam evo k tebi poslan.\" To reče, a ja ustadoh dršćući.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (34, 10, 12, 'I kaza mi: \"Ne boj se, Daniele, jer od prvoga dana kad si odlučio da se poniziš pred svojim Bogom da bi razumio, tvoje su riječi uslišane i ja sam došao zbog tvojih riječi.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (34, 10, 13, 'Knez kraljevstva perzijskoga protivio mi se dvadeset i jedan dan, ali Mihael, jedan od prvih Knezova, dođe mi u pomoć. Ostavih ga nasuprot Knezu perzijskome,');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (34, 10, 14, 'a ja dođoh da ti kažem što će zadesiti tvoj narod na svršetku dana. Jer još će jedno viđenje biti za one dane.\"');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (34, 10, 15, 'Pošto mi to reče, ja oborih pogled na zemlju, bez riječi.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (34, 10, 16, 'I gle: onaj, sličan sinu čovječjem dotače se mojih usana. Otvorih usta da govorim te rekoh onome koji stajaše preda mnom: \"Gospodaru moj, zbog ovog viđenja obuzeše me tjeskobe i onemoćah.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (34, 10, 17, 'I kako će sluga Gospodina svoga govoriti s Gospodinom kad posve onemoćah i dah me ostavi?\"');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (34, 10, 18, 'Tada me se opet dotače onaj što bijaše kao čovjek te me okrijepi.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (34, 10, 19, 'On reče: \"Ne boj se, miljeniče! Mir tebi! Budi jak! Ohrabri se!\" I dok mi to govoraše, ja se ohrabrih pa rekoh: \"Govori, Gospodine, jer si me ohrabrio!\"');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (34, 10, 20, 'Tada će on: \"Znaš li zašto sam došao k tebi? Sad ću se vratiti da se borim protiv Kneza Perzije; a čim svršim, doći će Knez Grčke.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (34, 10, 21, 'Ali ću ti prije otkriti što je zapisano u Knjizi istine. Nema nikoga tko bi se sa mnom protiv njih borio, osim Mihaela, Kneza vašega,');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (34, 11, 1, 'moje potpore i moga okrilja.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (34, 11, 2, 'A sada ću ti otkriti istinu. Evo: još će tri kralja ustati za Perziju: četvrti će biti bogatiji od svih ostalih, pa kad se zbog svoga bogatstva osili, sve će podići protiv kraljevstva grčkoga.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (34, 11, 3, 'Ustat će junački kralj, vladat će silnom moću i činiti što ga bude volja.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (34, 11, 4, 'A čim se ustane, njegovo će se kraljevstvo raspasti i bit će razdijeljeno na četiri vjetra nebeska, ali ne među njegove potomke; i neće više biti tako moćno kao za njegove vladavine, jer će njegovo kraljevstvo biti razoreno i predano drugima, a ne njima.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (34, 11, 5, 'Kralj će Juga postati moćan; jedan će od njegovih zapovjednika biti moćniji od njega i zavladat će većom moću nego što je njegova.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (34, 11, 6, 'Nekoliko godina kasnije oni će se udružiti, a kći kralja Juga doći će kralju Sjevera da sklope ugovor. Ali ona tim neće sačuvati snagu svoje mišice i njezino se potomstvo neće održati: bit će predana ona, i njezina pratnja, i njezino dijete, i njezin pomagač u tim vremenima.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (34, 11, 7, 'No jedan će se izdanak njezina korijena podići na njezino mjesto, navalit će na vojsku, prodrijet će u tvrđavu kralja Sjevera, postupati s njima po miloj volji i pobijediti ih.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (34, 11, 8, 'Pa i njihove bogove, njihove kipove i njihovo dragocjeno suđe, srebrno i zlatno, odnijet će kao plijen u Egipat. Nekoliko godina bit će jači od kralja Sjevera,');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (34, 11, 9, 'koji će onda prodrijeti u kraljevstvo kralja Juga, odakle će se vratiti u svoju zemlju.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (34, 11, 10, 'Ali će se onda njegovi sinovi naoružati, skupit će silnu vojsku, odlučno će navaliti i poput poplave proći, zatim će se opet zametnuti rat sve do njegove utvrde.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (34, 11, 11, 'Tada će se kralj Juga razgnjeviti i zavojštiti na kralja Sjevera; podići će silnu vojsku i nadvladati vojsku njegovu.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (34, 11, 12, 'Mnoštvo će biti uništeno, a on će se zbog toga uzoholiti; pobit će desetke tisuća, ali se neće održati:');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (34, 11, 13, 'kralj će Sjevera opet dići vojsku veću nego prije, i poslije nekoliko godina navalit će s velikom, dobro opremljenom vojskom.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (34, 11, 14, 'U to vrijeme mnogi će se podići protiv kralja Juga; ustat će i nasilnici iz tvog naroda da se ispuni viđenje, ali će propasti.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (34, 11, 15, 'Doći će kralj Sjevera: podići će nasipe da zauzme jedan utvrđeni grad. Mišice Juga neće odoljeti, pa ni izabrane čete neće imati snage da se odupru.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (34, 11, 16, 'Onaj će navaliti protiv njega i učinit će s njime kako mu se prohtije - nitko mu se neće oprijeti: zaustavit će se u Divoti, uništenje je u njegovim rukama.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (34, 11, 17, 'Čvrsto odlučivši da se pošto-poto domogne svega njegova kraljevstva, sklopit će s njim ugovor dajući mu jednu kćer za ženu da ga upropasti, ali mu neće uspjeti, neće se to zbiti.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (34, 11, 18, 'Zatim će se okrenuti prema otocima i mnoge će osvojiti, ali će jedan zapovjednik dokrajčiti tu sramotu, sramotu mu sramotom vratiti.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (34, 11, 19, 'Brže će nagnuti prema utvrdama svoje zemlje, ali će posrnuti, pasti, više ga neće biti.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (34, 11, 20, 'Na njegovo će mjesto doći jedan koji će u diku kraljevstva poslati poreznika, ali će u kratko vrijeme poginuti bez gnjeva i boja.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (34, 11, 21, 'Na njegovo će se mjesto uzdići nitkov kome ne pripada kraljevska čast. Ali on će iznenada doći i spletkama se domoći kraljevstva.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (34, 11, 22, 'Pred njim će biti preplavljene i skršene navalne snage i sam knez Saveza.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (34, 11, 23, 'Unatoč sporazumu s njime, izdajnički će navaliti i svladati ga s malo ljudi.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (34, 11, 24, 'Iznenada će upasti u bogate pokrajine i postupat će kako nisu postupali njegovi očevi ni očevi njegovih otaca, rasipajući među svoje plijen, pljačku i bogatstvo, smišljat će osnove protiv tvrdih gradova, ali samo za neko vrijeme.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (34, 11, 25, 'Pokrenut će, s velikom vojskom, svoju snagu i hrabrost protiv kralja Juga. Kralj Juga krenut će u rat s mnogom i moćnom vojskom, ali neće izdržati, jer će se protiv njega skovati spletke.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (34, 11, 26, 'I oni koji jeđahu za njegovim stolom skršit će ga: njegova će vojska biti uništena i mnogi će posječeni popadati.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (34, 11, 27, 'Oba će kralja smišljati zlo; sjedeći za istim stolom, govorit će laži jedan drugome: ali neće uspjeti, jer je svršetak odložen do određenog vremena.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (34, 11, 28, 'Vratit će se on u svoju zemlju s velikim blagom; srcem protiv svetoga Saveza, učinit će svoje i vratiti se u svoju zemlju.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (34, 11, 29, 'U određeno vrijeme opet će krenuti protiv Juga, ali sada neće biti kao prvi put.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (34, 11, 30, 'Kitimski će brodovi navaliti na njega, i on će se uplašiti. Vratit će se, bjesnjeti protiv svetoga Saveza i opet će se sporazumjeti s onima koji napustiše sveti Savez.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (34, 11, 31, 'Čete će njegove doći i oskvrnuti svetište-tvrđu, dokinut\' svagdašnju žrtvu i ondje postaviti grozotu pustoši.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (34, 11, 32, 'Svojim će spletkama navesti na otpad one koji se ogrešuju o Savez, ali ljudi koji ljube Boga ostat će postojani i vršit će svoje.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (34, 11, 33, 'Umnici u narodu poučavat će mnoštvo, ali će ih jedno vrijeme zatirati mačem i ognjem, izgnanstvom i pljačkanjem.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (34, 11, 34, 'Dok ih budu zatirali, samo će im nekolicina pomagati, a mnogi će im se pridružiti prijevarno.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (34, 11, 35, 'Od umnika neki će pasti, da se prokušaju, probrani, čisti do vremena svršetka, jer još nije došlo određeno vrijeme.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (34, 11, 36, 'Kralj će raditi što god mu se prohtije, uznoseći i uzdižući sebe iznad svih bogova: protiv Boga nad bogovima govorit će hule i uspijevat će dok se gnjev ne navrši - jer ono što je određeno, to će se ispuniti.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (34, 11, 37, 'Neće mariti za bogove svojih otaca ni za Miljenika ženÄa niti za kojega drugog boga: samog će sebe izdizati iznad sviju.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (34, 11, 38, 'Mjesto njih častit će boga tvrđava, boga koga nisu poznavali njegovi očevi, častiti ga zlatom i srebrom, dragim kamenjem i drugim dragocjenostima.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (34, 11, 39, 'Navalit će na tvrđave gradova pomoću stranog boga: one koji njega priznaju obasut će počastima i dat će im vlast nad mnoštvom i dijelit će im zemlju za nagradu.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (34, 11, 40, 'U vrijeme svršetka kralj će se Juga zaratiti s njime; kralj će Sjevera navaliti na nj svojim kolima, svojim konjanicima i svojim mnogim brodovima. Provalit će u zemlje i proći njima poput poplave.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (34, 11, 41, 'Prodrijet će u Divotu i mnogi će pasti. Njegovim će rukama izmaći Edom i Moab i glavnina sinova Amonovih.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (34, 11, 42, 'Pružit će svoju ruku za zemljama: Egipat mu neće izmaći.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (34, 11, 43, 'On će se domoći zlatnog i srebrnog blaga i svih dragocjenosti Egipta. Pratit će ga Libijci i Etiopljani.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (34, 11, 44, 'Ali će ga uznemiriti vijesti s istoka i sa sjevera te će poći vrlo gnjevan da uništi i zatre mnoštvo.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (34, 11, 45, 'Postavit će svoje dvorske šatore između mora i Svete gore Divote. Ali će i njemu doći kraj, i nitko mu neće pomoći.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (34, 12, 1, 'U ono će vrijeme ustati Mihael, veliki knez koji štiti sinove tvog naroda. Bit će to vrijeme tjeskobe kakve ne bijaše otkako je ljudi pa do toga vremena. U ono vrijeme tvoj će se narod spasiti - svi koji se nađu zapisani u Knjizi.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (34, 12, 2, 'Tada će se probuditi mnogi koji snivaju u prahu zemljinu; jedni za vječni život, drugi za sramotu, za vječnu gadost.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (34, 12, 3, 'Umnici će blistati kao sjajni nebeski svod, i koji su mnoge učili pravednosti, kao zvijezde navijeke, u svu vječnost.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (34, 12, 4, 'A ti, Daniele, drži u tajnosti ove riječi i zapečati ovu knjigu do vremena svršetka! Mnogi će tumarati, i bezakonja će rasti.\"');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (34, 12, 5, 'Ja, Daniel, pogledah, kad eno: druga dvojica stajahu jedan s jedne, drugi s druge strane rijeke.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (34, 12, 6, 'Jedan upita čovjeka odjevena u lanene haljine koji stajaše iznad voda rijeke: \"Kada će doći kraj tim čudesima?\"');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (34, 12, 7, 'Začuh čovjeka odjevena u lanene haljine, koji stajaše iznad voda rijeke; on podiže k nebu desnicu i ljevicu, kunući se Vječno živim. \"Nakon jednog vremena, dva vremena i pola vremena - kada dođe kraj rasulu snage svetoga naroda - sve će se to svršiti.\"');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (34, 12, 8, 'Ja slušah, ali ne razumjeh, pa upitah: \"Gospodaru, kako će to svršiti?\"');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (34, 12, 9, 'On reče: \"Idi, Daniele, ove su riječi tajne i zapečaćene do vremena svršetka.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (34, 12, 10, 'Mnogi će se očistiti, ubijeliti i prokušati; a bezbožnici će i dalje biti bezbožni; bezbožnici se neće urazumjeti, a umnici će razumjeti.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (34, 12, 11, 'Od časa kad bude dokinuta svagdašnja žrtva i postavljena grozota pustoši: tisuću dvjesta i devedeset dana.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (34, 12, 12, 'Blago onomu koji dočeka i dosegne tisuću trista trideset i pet dana!');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (34, 12, 13, 'A ti idi i otpočini; ustat ćeš da primiš svoju baštinu na kraju dana.\"');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (34, 13, 1, 'U Babilonu življaše neki čovjek po imenu Jojakim.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (34, 13, 2, 'On se oženi Suzanom, kćerju Hilkijinom, veoma lijepom i bogobojaznom.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (34, 13, 3, 'Njezini roditelji bijahu pravednici i odgojiše svoju kćer po Zakonu Mojsijevu.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (34, 13, 4, 'Jojakim bijaše vrlo bogat: uz kuću imaše vrt. Judejci se skupljahu kod njega jer bijaše poštovaniji od svih.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (34, 13, 5, 'One godine izabraše za suce dva starca iz naroda. O takvima reče Gospod: \"Bezakonje izađe iz Babilona po starješinama, sucima koji su se smatrali upravljačima naroda.\"');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (34, 13, 6, 'Ovi posjećivahu kuću Jojakimovu, i svi koji imahu kakvu parnicu obraćahu se njima.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (34, 13, 7, 'Kad bi se narod, oko podneva, razišao, Suzana bi dolazila šetati u vrt svog muža.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (34, 13, 8, 'Ona je dva starca svaki dan promatrahu gdje ulazi i šeta, pa je poželješe.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (34, 13, 9, 'Izgubiše od toga razum, odvratiše svoje oči od Neba i zaboraviše njegove pravedne sudove.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (34, 13, 10, 'Obojica njome ranjena, skrivahu jedan od drugoga svoju muku,');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (34, 13, 11, 'jer su se stidjeli priznati svoju pohotu za njom,');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (34, 13, 12, 'ali su živo nastojali da je svaki dan vide.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (34, 13, 13, 'Jednom se rastadoše rekavši: \"Hajdemo kući, doba je ručku.\" I svaki ode na svoju stranu,');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (34, 13, 14, 'ali se vratiše i nađoše na istom mjestu. Ispitujući se za povod, priznaše pohotu za njom, i tada ugovoriše priliku kad bi mogli zateći Suzanu samu.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (34, 13, 15, 'I dok su tako vrebali zgodan dan, uđe ona jednom, kao i minulih dana, samo sa dvije djevojke: htjede se okupati u vrtu, jer bijaše vruće.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (34, 13, 16, 'Ondje ne bijaše nikoga: osim ona dva starca, koji je, skriveni, vrebahu.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (34, 13, 17, 'Ona reče djevojkama: \"Donesite mi ulja i pomasti pa zaključajte vrtna vrata da se okupam!\"');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (34, 13, 18, 'One učine kako im zapovjedi: zaključaše vrtna vrata te iziđoše na pokrajna vrata da donesu što im je zapovjedila; ništa nisu znale o starcima, jer bijahu skriveni.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (34, 13, 19, 'Čim djevojke izađoše, oni ustadoše i pritrčaše k njoj.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (34, 13, 20, '\"Evo, rekoše, vrtna su vrata zaključana, nitko nas ne vidi. Mi te se poželjesmo, podaj nam se i budi naša!');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (34, 13, 21, 'Ako li nećeš, mi ćemo protiv tebe svjedočiti da je neki mladić bio s tobom i da si zbog toga udaljila od sebe svoje djevojke.\"');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (34, 13, 22, 'Suzana zastenja: \"Odasvud sam pritisnuta: učinim li to, smrt me čeka; ne učinim li, neću vam ruci umaći.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (34, 13, 23, 'Milije mi je da nedužna padnem u vaše ruke nego da sagriješim pred Gospodom.\"');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (34, 13, 24, 'I povika iza glasa. Okrenuše vikati i oba starca na nju,');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (34, 13, 25, 'a jedan potrča i otvori vrtna vrata.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (34, 13, 26, 'Kad ukućani čuše krikove u vrtu, dotrčaše na pokrajnja vrata da vide što se dogodilo.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (34, 13, 27, 'Pošto starci ispripovjediše svoju pripovijest, postidješe se sluge veoma, jer se o Suzani takvo što nikad ne ču.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (34, 13, 28, 'Sutradan se narod sabra kod Jojakima, njezina muža. Dođoše onamo starci, puni bezbožne namjere da Suzanu usmrte.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (34, 13, 29, 'Rekoše skupljenu narodu: \"Pošaljite po Suzanu, kćer Hilkijinu, ženu Jojakimovu!\" Poslaše po nju.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (34, 13, 30, 'Ona dođe sa svojim roditeljima, djecom i svim rođacima.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (34, 13, 31, 'A Suzana bijaše veoma ljupka i ljepolika.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (34, 13, 32, 'Kako bijaše pod koprenom, oni bezakonici narediše da skine koprenu da bi se nasitili njezine ljepote.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (34, 13, 33, 'Svi njezini plakahu, a tako i svi koji je gledahu.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (34, 13, 34, 'Oba starca ustadoše usred naroda i staviše joj ruke na glavu.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (34, 13, 35, 'Ona plačući, srca zaufana u Gospoda, pogleda prema nebu.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (34, 13, 36, 'Starci rekoše: \"Dok mi šetasmo sami po vrtu, uđe ona sa dvije djevojke, zaključa vrtna vrata i otpusti djevojke.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (34, 13, 37, 'Priđe k njoj mladić koji bijaše skriven i leže s njom.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (34, 13, 38, 'Mi bijasmo u kutu vrta; videći to bezakonje, potrčasmo k njima.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (34, 13, 39, 'Vidjesmo ih zajedno, ali ne mogosmo uhvatiti mladića jer bijaše jači od nas pa otvori vrata i pobježe.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (34, 13, 40, 'Ali ovu uhvatismo i zapitasmo tko ono bijaše.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (34, 13, 41, 'Ne htjede nam kazati. Za to svjedočimo.\" Povjerova im zbor - tÓa oni bijahu starješine narodne, suci, i osudiše je na smrt.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (34, 13, 42, 'Suzana povika iza glasa: \"Bože vječni, ti koji poznaješ tajne, koji znaš sve prije negoli se zbude,');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (34, 13, 43, 'ti znadeš da su lažno svjedočili protiv mene. I evo umrijet\' mi je, a da ne učinih ništa od onoga što je njihova pakost izmislila protiv mene.\"');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (34, 13, 44, 'Gospod usliši njezin vapaj.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (34, 13, 45, 'Dok su je vodili u smrt, probudi Bog sveti duh mladog momčića Daniela.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (34, 13, 46, 'On povika iza glasa: \"Ja sam čist od krvi njezine!\"');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (34, 13, 47, 'Sav se narod okrenu prema njemu i zapita: \"Što si to kazao?\"');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (34, 13, 48, 'Stade posred njih i reče: \"Tako li ste ludi, sinovi Izraelovi? Bez istrage i bez uvida u istinu osudiste kćer Izraelovu?');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (34, 13, 49, 'Vratite se u sudnicu, jer lažno ovi svjedočiše protiv nje.\"');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (34, 13, 50, 'Sav se narod brzo vrati, a starješine mu rekoše: \"Dođi, sjedni među nas i reci nam, jer tebi Bog dade starješinstvo!\"');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (34, 13, 51, 'Tada im reče Daniel: \"Rastavite daleko jednoga od drugoga, i ja ću ih ispitati.\"');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (34, 13, 52, 'Rastaviše ih, pa Daniel dozva jednoga od njih i reče mu: \"Stari zlikovče, sada dođoše na te grijesi koje nekoć učini,');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (34, 13, 53, 'donoseći nepravedne presude, osuđujući nedužne i oslobađajući krivce, dok Gospod govori: \'Nedužna i pravedna da nisi ubio.\'');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (34, 13, 54, 'Sada, dakle, ako si ovu doista vidio, reci nam: pod kojim si ih drvetom vidio zajedno?\" On odgovori: \"Pod jednom trišljom.\"');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (34, 13, 55, 'Daniel reče: \"Zaista, slagao si na svoju glavu. Evo, Anđeo je Božji već dobio od Boga zapovijed da te rasiječe po sredini.\"');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (34, 13, 56, 'I otpusti ovoga, a dade dovesti drugoga te mu reče: \"Sjeme Kanaanovo, a ne Judino, ljepota te zaludila, strast ti srce okrenula!');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (34, 13, 57, 'Ovako ste radili sa kćerima Izraelovim, a one su vam se od straha podavale. Ali se kći Judina ne podloži vašem bezakonju.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (34, 13, 58, 'Reci mi dakle pod kojim si ih drvetom zatekao zajedno!\" On odgovori: \"Pod jasikom.\"');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (34, 13, 59, 'Daniel mu reče: \"Pravo si i ti lagao na svoju glavu. Anđeo Božji čeka s mačem u ruci da te rasiječe po sredini te vas obojicu zatre.\"');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (34, 13, 60, 'Tada sav zbor stade iza glasa vikati i blagoslivljati Boga koji spasava one što se u nj uzdaju.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (34, 13, 61, 'I okrenuše se protiv one dvojice staraca kojima je Daniel iz njihovih usta dokazao lažno svjedočenje.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (34, 13, 62, 'I učiniše njima kako u svojoj pakosti oni smisliše bližnjemu: pogubiše ih prema zakonu Mojsijevu. Tako onoga dana bi spašena jedna nedužna krv.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (34, 13, 63, 'Hilkija i njegova žena dadoše hvalu Bogu za svoju kćer Suzanu, a tako i Jojakim, muž njezin, i svi njezini rođaci, što se na njoj ne nađe ništa sramotno.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (34, 13, 64, 'I od onoga dana Daniel postade velik u očima naroda.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (34, 14, 1, 'Kralj Astijag bi pridružen svojim ocima, a naslijedi ga Kir Perzijanac.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (34, 14, 2, 'Daniel življaše kod kralja, koji ga poštivaše više nego bilo kojega od svojih prijatelja.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (34, 14, 3, 'A imali su u Babilonu kumira imenom Bela i prinosili mu svaki dan po dvanaest artaba najboljeg brašna, četrdeset ovaca i šest metreta vina.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (34, 14, 4, 'I kralj ga je štovao i svaki dan išao da mu se klanja. A Daniel se klanjaše svome Bogu.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (34, 14, 5, 'Stoga mu reče kralj: \"Zašto se ti ne klanjaš Belu?\" On odgovori: \"Jer ne štujem rukotvorenih kumira, nego Boga živoga, koji stvori nebo i zemlju i koji gospodari svakim tijelom!\"');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (34, 14, 6, 'Tada će kralj: \"Ti dakle misliš da Bel nije živi bog? Zar ne vidiš što sve pojede i popije svaki dan?\"');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (34, 14, 7, 'I reče Daniel smiješeći se: \"Ne varaj se, kralju; iznutra je od gline, izvana od mjedi; nikada taj još nije ni jeo ni pio.\"');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (34, 14, 8, 'Kralj, bijesan, dozva Belove svećenike te im reče: \"Ako mi ne reknete tko jede ovu hranu, umrijet ćete; no ako dokažete da to Bel jede, umrijet će Daniel što pogrdi Bela.\"');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (34, 14, 9, 'I reče Daniel kralju: \"Neka bude po tvojoj riječi!\" A svećenika Belovih bijaše sedamdeset, ne brojeći žene i djecu.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (34, 14, 10, 'Kralj tako uđe s Danielom u hram Belov.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (34, 14, 11, 'Svećenici mu Belovi rekoše: \"Mi ćemo izići, a ti, o kralju, naredi da se postave jela i donese miješano vino: zatim zaključaj vrata i zapečati ih svojim prstenom; ako ujutro dođeš i ne nađeš da je Bel sve pojeo, neka umremo - mi ili Daniel, naš klevetnik.\"');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (34, 14, 12, 'Nisu se bojali, jer bijahu načinili pod stolom tajni ulaz kojim bi svaki dan dolazili i trošili jelo.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (34, 14, 13, 'Ali kad oni izađoše i kralj dade postaviti jela Belu,');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (34, 14, 14, 'Daniel naredi svojim slugama da donesu pepela i njime pospu sav hram pred očima kraljevim. Tada iziđoše, zaključaše vrata, zapečatiše ih kraljevim prstenom te otiđoše.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (34, 14, 15, 'Svećenici, po običaju, dođoše noću sa ženama i djecom: sve izjedoše i popiše.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (34, 14, 16, 'Kralj sutradan urani, a tako i Daniel.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (34, 14, 17, 'I kralj ga zapita: \"Daniele, jesu li pečati nepovrijeđeni?\" - \"Nepovrijeđeni su, kralju\", odgovori Daniel.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (34, 14, 18, 'Čim se otvoriše vrata, kralj pogleda na stol i povika iza glasa: \"Velik li si, Bele, i nema nikakve prijevare u tebe!\"');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (34, 14, 19, 'Daniel se nasmija; zadrža kralja da ne uđe, pa mu reče: \"Pogledaj pod, istraži čije su ovo stope!\"');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (34, 14, 20, '\"Vidim stope muškaraca, žena i djece\" reče kralj.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (34, 14, 21, 'I bijesan, dade uhvatiti svećenike, žene i djecu njihovu. Tada mu pokazaše tajna vrata na koja su ulazili i trošili ono što bijaše na stolu.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (34, 14, 22, 'Kralj ih dade pogubiti, a Bela predade Danielu, koji razori njega i njegov hram.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (34, 14, 23, 'A bijaše i velik zmaj koga štovahu Babilonci.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (34, 14, 24, 'Kralj reče Danielu: \"Hoćeš reći da je mjeden? Gle! Živi, jede, pije: nećeš valjda kazati da ovo nije živi bog. Pokloni mu se!\"');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (34, 14, 25, 'Daniel odgovori: \"Ja se klanjam Gospodu Bogu svome; on je Bog živi. A ti, kralju, daj mi vlast, i ja ću ubiti ovu zmiju bez mača i bez toljage.\"');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (34, 14, 26, 'I reče kralj: \"Dajem ti!\"');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (34, 14, 27, 'Tada Daniel uze smole, masti i dlaka, sve to ispeče, načini od toga kuglice te ih baci zmaju u ždrijelo. Zmaj proguta i rasprsnu se. A Daniel reče: \"Gledajte čemu se klanjate!\"');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (34, 14, 28, 'Kad to čuše Babilonci, silno se razbjesnješe i pobuniše se protiv kralja. Rekoše: \"Kralj postade Židov: Bela sruši, zmaja ubi, svećenike pokla.\"');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (34, 14, 29, 'Navališe dakle kralju i rekoše: \"Predaj nam Daniela, inače ćemo ubiti tebe i tvoj dom!\"');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (34, 14, 30, 'I vidje kralj da žestoko navaljuju; prisiljen, preda im Daniela.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (34, 14, 31, 'Oni ga baciše u lavlju jamu: i ostade ondje šest dana.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (34, 14, 32, 'U jami bijaše sedam lavova kojima davahu svaki dan po dva trupla i dvije ovce: tada im ne dadoše ništa da bi proždrli Daniela.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (34, 14, 33, 'A prorok Habakuk bijaše u Judeji: upravo bijaše skuhao kašu i nadrobio kruha u posudu te pošao da odnese žeteocima u polje.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (34, 14, 34, 'I Anđeo Gospodnji reče Habakuku: \"Odnesi ručak koji imaš u Babilon, Danielu u lavljoj jami!\"');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (34, 14, 35, 'Habakuk odgovori: \"Gospodine, Babilon ne vidjeh i za jamu ne znam!\"');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (34, 14, 36, 'Anđeo ga Gospodnji uhvati za vrh glave i noseći za kiku spusti ga u Babilonu povrh jame hitrinom svoga duha.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (34, 14, 37, 'I povika Habakuk: \"Daniele, Daniele, uzmi ručak što ti ga šalje Bog!\"');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (34, 14, 38, 'A Daniel reče: \"Spomenuo si se mene, Bože, i nisi zapustio one koji tebe ljube.\"');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (34, 14, 39, 'I ustade Daniel i blagova, a Anđeo Gospodnji odmah vrati Habakuka u njegovu zemlju.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (34, 14, 40, 'Sedmoga dana dođe kralj da oplače Daniela; priđe jami, pogleda, kad ono: Daniel sjedi.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (34, 14, 41, 'Tada kralj povika iza glasa: \"Velik si, Gospode Bože Danielov, i nema drugoga Boga osim tebe!\"');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (34, 14, 42, 'I zapovjedi da Daniela izvade iz jame i da onamo bace one koji su njega htjeli upropastiti: lavovi ih učas požderaše pred njegovim očima.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (34, 14, 43, '');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (35, 1, 1, 'Riječ Jahvina koja dođe Hošei, sinu Beerijevu, u dane Uzije, Jotama, Ahaza i Ezekije, kraljeva judejskih, u dane Jeroboama, sina Joaševa, kralja izraelskog.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (35, 1, 2, 'Početak riječi Jahvinih Hošei. Jahve reče Hošei: \"Idi, oženi se bludnicom i izrodi djecu bludničku, jer se zemlja bludu odala, odmetnuvši se od Jahve!\"');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (35, 1, 3, 'I on ode, uze Gomeru, kćer Diblajimovu, koja zače i rodi mu sina.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (35, 1, 4, 'Jahve mu reče: \"Nadjeni mu ime Jizreel, jer još samo malo i kaznit ću pokolje jizreelske na domu Jehuovu i dokončat ću kraljevstvo doma Izraelova.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (35, 1, 5, 'I u taj dan slomit ću luk Izraelov u Dolini jizreelskoj.\"');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (35, 1, 6, 'I ona opet zače i rodi kćer. I reče mu Jahve: \"Nadjeni joj ime Nemila, jer mi odsad neće biti mila kuća Izraelova, od nje ću se povući;');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (35, 1, 7, 'a omiljet će mi kuća Judina, spasit ću je Jahvom, Bogom njihovim, a neću je spasiti lukom, mačem ni kopljem, ni konjima ni konjanicima.\"');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (35, 1, 8, 'Kad odoji Nemilu, zače opet i rodi sina.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (35, 1, 9, 'I reče Jahve: \"Nadjeni mu ime Ne-narod-moj, jer više niste narod moj i ja vama nisam više Onaj koji jest.\"');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (35, 2, 1, '\"A djece Izraelove bit će brojem k\'o pijeska u moru što se izmjerit\' ne može ni izbrojit\'. Umjesto da im govore: \'Vi niste moj narod,\' zvat će ih: \'Sinovi Boga živoga.\'');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (35, 2, 2, 'Ujedinit će se sinovi Judini i sinovi Izraelovi, postavit će sebi jednoga glavara i otići će iz zemlje; jer velik će biti dan jizreelski.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (35, 2, 3, 'Recite braći svojoj: \'Narode moj,\' sestrama svojim: \'Mila.\'');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (35, 2, 4, 'Podignite tužbu, podignite, protiv majke svoje, jer ona mi nije više žena, a ja joj muž više nisam. Nek\' odbaci od sebe bludničenja i preljube izmeđ\' svojih dojki,');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (35, 2, 5, 'da je golu ne svučem te učinim da bude k\'o na dan rođenja; da je ne obratim u pustinju, da je u zemlju suhu ne obratim i žeđu ne umorim.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (35, 2, 6, 'Ja joj djece neću milovati, jer djeca su to bludnička.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (35, 2, 7, 'Da, bludu se odala mati njihova, sramotila se ona koja ih zače. Da, rekla je: \'Trčat ću za svojim milosnicima, za njima koji mi daju kruh moj i vodu, vunu moju i lan, ulje i piće moje.\'');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (35, 2, 8, 'Stoga ću put joj trnjem zagraditi, zidom opkoliti, da ne nađe više svojih staza.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (35, 2, 9, 'I trčat će za milosnicima, ali ih stići neće, tražit će ih, al\' ih neće pronaći. Tada će reći: \'Idem se vratiti prvome mužu, jer sretnija bijah prije nego sada.\'');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (35, 2, 10, 'I ona nije razumjela da joj ja davah i žito i mošt i ulje, da je ja obasipah srebrom i zlatom od kojega načiniše baale.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (35, 2, 11, 'Stoga ću uzeti natrag svoje žito u svoje vrijeme i svoj mošt u pravi čas; oduzet ću svoju vunu i svoj lan kojima je imala pokriti golotinju svoju;');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (35, 2, 12, 'sad ću joj otkriti sramotu na oči njenih milosnika, i nitko je iz moje neće izbaviti ruke.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (35, 2, 13, 'Učinit ću kraj svim njenim veseljima, svetkovinama, mlađacima, subotama i svim blagdanima njezinim.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (35, 2, 14, 'Opustošit ću joj čokote i smokve za koje je govorila: \'To je plaća što mi je dadoše moji milosnici.\' Obratit ću ih u šikarje, i životinje će ih poljske obrstiti.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (35, 2, 15, 'Kaznit ću je za dane Baalove kojima je kad palila, kitila se grivnom i kolajnom i trčala za svojim milosnicima; a mene je zaboravljala - riječ je Jahvina.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (35, 2, 16, 'Stoga ću je, evo, primamiti, odvesti je u pustinju i njenu progovorit\' srcu.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (35, 2, 17, 'I vratit ću joj ondje njene vinograde, i od Doline ću akorske učiniti vrata nade. Ondje će mi odgovarat\' ona kao u dane svoje mladosti, kao u vrijeme kada je izišla iz Egipta.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (35, 2, 18, 'U onaj dan - riječ je Jahvina - ti ćeš me zvati: \'Mužu moj\', a nećeš me više zvati: \'Moj Baale.\'');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (35, 2, 19, 'Uklonit ću joj iz usta imena baalska i neće im više ime spominjati.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (35, 2, 20, 'U onaj dan, učinit ću za njih savez sa životinjama u polju, sa pticama nebeskim i gmazovima zemskim; luk, mač i boj istrijebit ću iz zemlje da mirno u njoj počiva.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (35, 2, 21, 'Zaručit ću te sebi dovijeka; zaručit ću te u pravdi i u pravu, u nježnosti i u ljubavi;');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (35, 2, 22, 'zaručit ću te sebi u vjernosti i ti ćeš spoznati Jahvu.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (35, 2, 23, 'U onaj dan - riječ je Jahvina - odazvat ću se nebesima, a ona će se zemlji odazvati;');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (35, 2, 24, 'zemlja će se odazvati žitu, moštu i ulju, a oni će se odazvati Jizreelu.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (35, 2, 25, 'I posijat ću ga u zemlji, zamilovat ću Nemilu, Ne-narodu mom reći ću: \'Ti si narod moj!\' a on će reći: \'Bože moj!\'\"');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (35, 3, 1, 'Potom mi Jahve reče: \"Idi opet, ljubi ženu koja drugog ljubi i čini preljub, kao što Jahve ljubi djecu Izraelovu dok se oni k drugim bogovima okreću i žude za kolačima od grožđa.\"');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (35, 3, 2, 'Ja je tad kupih za petnaest srebrnika, za homer i letek ječma,');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (35, 3, 3, 'i rekoh joj: \"Za mnogo dana ostat ćeš mi povučena, nećeš se odavati bludu ni podavati nikojem čovjeku, a ni ja neću k tebi prilaziti.\"');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (35, 3, 4, 'Jer mnogo će dana sinovi Izraelovi ostati bez kralja i bez kneza, bez žrtve i bez stupa, bez oplećka i bez kumira.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (35, 3, 5, 'Poslije toga, sinovi će se Izraelovi vratiti; tražit će Jahvu, Boga svoga, i Davida, svoga kralja; sa strahom će pristupiti k Jahvi i k njegovim dobrima, na kraju dana.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (35, 4, 1, 'Čujte riječ Jahvinu, sinovi Izraelovi, jer Jahve se parbi sa stanovnicima zemlje.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (35, 4, 2, 'Nema više vjernosti, nema ljubavi, nema znanja Božjega u zemlji, već proklinjanje i laž, ubijanje i krađa, preljub i nasilje, jedna krv drugu stiže.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (35, 4, 3, 'Stoga tuguje zemlja i ginu svi stanovnici s poljskim zvijerima i pticama nebeskim te ugibaju i ribe u moru.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (35, 4, 4, 'Ipak neka se nitko ne parbi, neka nitko ne kori! Ali s tobom se moram parbiti, svećeniče.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (35, 4, 5, 'Danju ti posrćeš, a noću s tobom posrće i prorok; pogubit ću mater tvoju.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (35, 4, 6, 'Moj narod gine: nema znanja; jer si ti znanje odbacio, i ja odbacujem tebe iz svećenstva svoga; jer si Zakon svoga Boga zaboravio, i ja ću tvoje zaboraviti sinove.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (35, 4, 7, 'Što ih je više bivalo, više su protiv mene griješili, Slavu su svoju Sramotom zamijenili.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (35, 4, 8, 'Grijesima mog naroda oni se hrane, duša im hlepi za bezakonjem njegovim.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (35, 4, 9, 'I sa svećenikom bit će k\'o i s narodom; kaznit ću ga za njegove putove i naplatit ću mu za njegova djela.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (35, 4, 10, 'Jest će, ali se nasititi neće; bludničit će, ali se neće množiti, jer oni su prestali štovati Jahvu -');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (35, 4, 11, 'blud, mošt i vino zarobiše im srce.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (35, 4, 12, 'Narod moj savjet traži od drva, palica mu njegova daje odgovore: jer duh razvratni njih zavodi te se od Boga svoga bludu odaju.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (35, 4, 13, 'Oni žrtvuju na gorskim vrhuncima i na bregovima pale kad, pod hrastom, jablanom i dubom; jer je tako lagodno pod njihovom sjenom. I zato, odaju li se vaše kćeri bludu, čine li preljub vaše nevjeste,');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (35, 4, 14, 'neću vam kazniti kćeri što bludniče niti nevjeste vaše što preljub čine; jer oni sami idu nasamo s bludnicama i žrtvuju s milosnicama hramskim. Tako, bez razuma narod u propast srlja!');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (35, 4, 15, 'Ako li se ti bludu odaješ, Izraele, neka bar Juda ne griješi! I ne idite u Gilgal, ne penjite se u Bet Aven, ne kunite se \"živoga mi Jahve.\"');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (35, 4, 16, 'Jer poput junice tvrdoglave Izrael tvrdoglav postade, pa kako da ga Jahve sad pase k\'o janje na prostranoj livadi?');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (35, 4, 17, 'Efrajim se udružio s kumirima: pusti ga!');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (35, 4, 18, 'A kad završe pijanku, bluda se prihvaćaju, Sramotu vole više nego Slavu svoju.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (35, 4, 19, 'Vihor će ih svojim krilima stegnuti i njihovi će ih osramotit\' žrtvenici.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (35, 5, 1, 'Poslušajte ovo, svećenici, pazi, dome Izraelov, dome kraljev, de posluhni, jer vaš je sud! Vi ste bili zamka u Mispi i mreža napeta na Taboru.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (35, 5, 2, 'Jamu su duboko iskopali prestupnici, ali ću ih sve kazniti.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (35, 5, 3, 'Poznajem ja Efrajima, Izrael mi nije sakriven: da, Efrajime, bludu si se odao, okaljao si se, Izraele.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (35, 5, 4, 'Ne daju im djela njihova da se Bogu svome vrate, jer je duh bluda među njima; oni Jahve ne poznaju.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (35, 5, 5, 'Ponos Izraelov svjedoči protiv njega; svojom krivnjom posrnu Efrajim, posrnut će i Juda s njim.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (35, 5, 6, 'Ići će s ovcama i govedima Jahvu tražiti ali ga naći neće - povukao se od njih!');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (35, 5, 7, 'Jahvu su iznevjerili: rodili su kopilad; vjetar će žarki proždrijeti polja njihova.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (35, 5, 8, 'Zasvirajte u rog u Gibeji, u trublju u Rami, uzbunite Bet Aven: za petama su ti, Benjamine!');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (35, 5, 9, 'Opustošit će Efrajima u dan kazne: među plemenima Izraelovim objavljujem ono što je sasvim pouzdano.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (35, 5, 10, 'Knezovi judejski postadoše poput onih što razmiču međe; na njih ću k\'o vodu gnjev svoj izliti.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (35, 5, 11, 'Efrajim je tlačitelj, on pravdu gazi jer mu se svidjelo ići za ništavilom.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (35, 5, 12, 'A ja ću biti poput moljca Efrajimu, kao gnjilež kući Judinoj.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (35, 5, 13, 'Tad je Efrajim svoju bolest vidio, a Juda ranu svoju; i pođe Efrajim u Asiriju, obrati se Juda velikome kralju; al\' on vas neće iscijeliti niti vam ranu vašu zaliječiti.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (35, 5, 14, 'Jer k\'o lav ću biti Efrajimu, kao lavić domu Judinu; ja, ja ću razderati i otići, odnijet ću i nitko neće spasiti.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (35, 5, 15, 'Poći ću, vratit ću se na svoje mjesto, dok krivnju ne priznaju i lice moje ne potraže; kad u nevolji budu, iskat će me.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (35, 6, 1, '\"Hajde, vratimo se Jahvi! On je razderao, on će nas iscijeliti: on je udario, on će nam poviti rane;');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (35, 6, 2, 'poslije dva dana oživit će nas, trećeg će nas dana podignuti i mi ćemo živjeti pred njim.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (35, 6, 3, 'Težimo da upoznamo Jahvu: k\'o zora pouzdan mu dolazak. On će nam doći poput dažda jesenskog, poput kiše proljetne što natapa zemlju.\"');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (35, 6, 4, 'Što za tebe mogu učiniti, Efrajime? Što za tebe mogu učiniti, Judo? K\'o oblak jutarnji ljubav je vaša, k\'o rana rosa koje nestaje.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (35, 6, 5, 'Zato sam ih preko proroka sjekao i ubijao riječima usta svojih; al\' sud će tvoj izaći k\'o svjetlost.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (35, 6, 6, 'Jer ljubav mi je mila, ne žrtve, poznavanje Boga, ne paljenice.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (35, 6, 7, 'Al\' oni su kod Adama prekršili Savez i ondje mene iznevjerili.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (35, 6, 8, 'Gilead je grad zlikovački, pun krvavih tragova.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (35, 6, 9, 'Družba je svećenička kao zasjeda razbojnička: ubijaju na šekemskom putu; odista, sramotu počinjaju!');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (35, 6, 10, 'Strahotu vidjeh u domu Izraelovu; Efrajim se ondje bludu odaje i skvrni se Izrael.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (35, 6, 11, 'I tebi sam, Judo, žetvu odredio kad okrenem udes naroda svoga.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (35, 7, 1, 'Kad hoću Izraela liječiti, otkriva se bezakonje Efrajimovo i zloća Samarije; prijevarom se bave oni: tat u kuću provaljuje, a vani napadaju razbojnici.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (35, 7, 2, 'I u srcu svome oni ne kažu da ja pamtim svu zlopakost njihovu! Ali djela su ih njihova sad opkolila, pred licem mojim ona stoje.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (35, 7, 3, 'Svojom zloćom razveseljuju kralja, a knezove podlošću svojom.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (35, 7, 4, 'Svi su oni preljubnici, kao peć su ražarena koju pekar više ne potpaljuje kad zamijesi tijesto pa dok ne ukisne.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (35, 7, 5, 'U dan kralja našega knezovi obolješe od žestine vina, a on ruku pruža pijanima.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (35, 7, 6, 'U zavjeri srce im se žari poput peći; svu noć njihova jarost drijema, ujutru se razgara k\'o plam ognjeni;');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (35, 7, 7, 'poput peći svi se raspalili te proždiru svoje suce. Padoše svi njihovi kraljevi, a nijedan od njih zazvao me nije.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (35, 7, 8, 'Efrajim se miješa s narodima, Efrajim je pogača što je ne prevrnuše.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (35, 7, 9, 'Tuđinci proždiru snagu njegovu, a on toga i ne zna! Sjedine mu pobijeliše glavu, a on toga i ne zna!');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (35, 7, 10, 'Naprasitost Izraelova protiv njih samih svjedoči; i oni se ne vraćaju Jahvi, Bogu svome, i uza sve to oni ga ne traže!');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (35, 7, 11, 'Efrajim je kao golubica plaha i bez razuma; oni pozivaju Egipat, idu u Asiriju.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (35, 7, 12, 'Kamo god otišli, na njih ću razapeti svoju mrežu, oborit ću ih kao ptice nebeske, za njihovu ih kazniti zloću.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (35, 7, 13, 'Teško njima jer od mene odbjegoše! Propast na njih jer se pobuniše protiv mene! Otkupit\' ih hoću, a oni protiv mene lažu.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (35, 7, 14, 'Oni me ne prizivlju iz srca kada kukaju na svojim ležajima; razdiru svoje lice zbog žita i mošta, ali protiv mene se bune.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (35, 7, 15, 'Dok sam im ja mišicu krijepio, oni su zlosti smišljali protiv mene!');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (35, 7, 16, 'Okreću se prema ništavostima, oni su poput varljiva luka. Poradi razbješnjela jezika knezovi će im od mača pasti, bit će im to na ruglo u zemlji egipatskoj!');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (35, 8, 1, 'Trublju na usta, poput stražara na Domu Jahvinu; jer oni moj Savez prestupiše, otpadoše od moga Zakona.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (35, 8, 2, 'Meni viču: \"Poznajemo te, Bože Izraelov.\"');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (35, 8, 3, 'Ali je Izrael odbacio dobro, dušman će ga progoniti.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (35, 8, 4, 'Kraljeve su postavljali bez mene, knezove birali bez znanja moga. Od srebra svog i zlata načiniše sebi kumire da budu uništeni.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (35, 8, 5, 'Odbacih tvoje tele, Samarijo, na njih se gnjev moj rasplamtio. Dokle će ostati nečisti sinovi Izraelovi?');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (35, 8, 6, 'Umjetnik ga je neki načinio, i ono Bog nije. Prometnut će se u komadiće tele samarijsko.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (35, 8, 7, 'Posijali su vjetar, i požet će oluju; žito im neće proklijati, neće brašna dati; ako ga i dade proždrijet će ga tuđinci.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (35, 8, 8, 'Progutan je Izrael, evo ga među narodima poput nevrijedne posude;');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (35, 8, 9, 'jer otiđoše k Asircu, divljem magarcu što sam živi! Efrajim obdaruje milosnike.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (35, 8, 10, 'Neka ih samo obdaruje, među narode ću ih sada razasuti: i doskora će uzdrhtati pod teretom kralja knezova.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (35, 8, 11, 'Žrtvenike je umnožio Efrajim, za grijeh su mu oni poslužili.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (35, 8, 12, 'Da mu i tisuću zakona svojih napišem, oni ih smatraju tuđima.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (35, 8, 13, 'Nek\' žrtvuju klanice što mi ih prinose, nek\' samo jedu meso! Jahvi se ne mile. Odsad će se spominjati bezakonja njihova i njihove će kazniti grijehe: u Egipat će se oni vratiti.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (35, 8, 14, 'Izrael je zaboravio tvorca svoga i sebi dvorove sagradio; Juda je namnožio gradove tvrde. Oganj ću pustiti na gradove njegove; vatra će mu dvorove progutati.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (35, 9, 1, 'Ne raduj se, Izraele, ne kliči k\'o drugi narodi; bludu se oda, jer, ostavivši Boga svoga, zavolio si plaću bludničku po svim gumnima žitnim.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (35, 9, 2, 'Ni gumno ni kaca neće ih hraniti, i mlado će ih vino prevariti.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (35, 9, 3, 'Neće više živjeti u zemlji Jahvinoj, Efrajim će se vratiti u Egipat i nečista će jela jesti u Asuru.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (35, 9, 4, 'Neće više Jahvi lijevati vina, nit\' će mu prinositi žrtve svoje; kruh će im biti kao kruh žalosti, i nečist će biti tko ga bude jeo; jer njihov je kruh samo za njih, neće ući u Dom Jahvin.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (35, 9, 5, 'Što ćete činiti na dan blagdanski, na dan svetkovine Jahvine?');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (35, 9, 6, 'Jer, evo gdje odoše pred pustošenjem; prihvatit će ih Egipat, sahraniti Memfis, srebrna im blaga kopriva će baštiniti, šatore će njihove obrasti trnje.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (35, 9, 7, 'Dođoše dani kazne! Dođoše dani odmazde! Nek\' znade Izrael! Lud je prorok, nadahnuti bunca! Zbog velikog bezakonja tvoga i silnog buntovništva.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (35, 9, 8, 'Efrajim uhodi šator prorokov, stavljaju mu zamke po svim putovima, odmazda je u kući Boga njegova.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (35, 9, 9, 'U duboku su pali pokvarenost kao u dane Gibeje; spomenut će se Jahve bezakonja njihova i grijehe će njihove kazniti.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (35, 9, 10, 'Kao grožđe u pustinji nađoh ja Izraela, kao rani plod na smokvi vidjeh oce vaše; oni dođoše u Baal Peor, posvetiše se sramoti i postadoše grozote kao ljubimci njihovi.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (35, 9, 11, 'Odletje poput ptice slava Efrajimova: od rođenja, od utrobe, od začeća.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (35, 9, 12, 'Ako i podignu svoje sinove, oduzet ću ih prije dobi muževne, da, teško njima kada ih ostavim!');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (35, 9, 13, 'Efrajim je k\'o da gledam Tir na njivi posađen, al\' će Efrajim djecu svoju voditi na klanje.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (35, 9, 14, 'Daj im, o Jahve! A što da im dadeš? Daj im krilo jalovo, dojke usahle.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (35, 9, 15, 'U Gilgalu sva je njihova zloća, ondje sam ih zamrzio. Zbog njihovih djela opakih iz kuće svoje ću ih izagnati, voljeti ih više neću, svi su im knezovi odmetnici.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (35, 9, 16, 'Pogođen je Efrajim, korijen mu je usahnuo; roda neće imati. Ako im se i rodi djece, ubit ću im mili plod utrobe.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (35, 9, 17, 'Odbacit će ih Bog moj jer ga nisu poslušali; i potucat će se među narodima.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (35, 10, 1, 'Bujna je loza bio Izrael, rod bogat ona je nosila. I što mu je više rodilo plodova, to je više umnažao žrtvenike; što mu je bogatija zemlja bila, to je kićenije dizao stupove.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (35, 10, 2, 'Srce je njihovo prijevarno, okajat će to oni! Porušit će im On žrtvenike, polomiti stupove njihove.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (35, 10, 3, 'Kazat će tada: \"Mi kralja nemamo jer se Jahve bojali nismo. TÓa čemu bi nam bio kralj?\"');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (35, 10, 4, 'Riječi prosiplju, lažno se kunu, sklapaju saveze; a pravo cvate k\'o otrovno bilje u brazdama polja.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (35, 10, 5, 'Za tele betavensko strepe stanovnici Samarije; da, zbog njega tuguje narod njegov, svećenici njegovi kukaju nad njim, nad slavom njegovom jer je od njega prognana.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (35, 10, 6, 'A njega samog odvući će u Asiriju na dar velikome kralju. Efrajima stid će spopasti, crvenjet će se Izrael zbog svoje odluke.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (35, 10, 7, 'Uništena je Samarija. Njen kralj tek trunak je vodi na površju.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (35, 10, 8, 'Bit će razorene sramne uzvišice, grijeh Izraelov; trnje će i čičak rasti po žrtvenicima njihovim. Tad će govoriti brdima: \"Pokrijte nas!\" i bregovima: \"Padnite na nas!\"');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (35, 10, 9, 'Većma no u dane gibejske griješio si, Izraele! A da se i ondje zaustaviše, ne bi li ih zatekao rat kao bezakonike gibejske?');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (35, 10, 10, 'Kako mi se svidi, kaznit ću ih: sabrat će se protiv njih narodi da ih za dvostruko kazne bezakonje.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (35, 10, 11, 'Efrajim je junica dobro naučena koja rado vrše; šiju ću joj lijepu ujarmiti, upregnut ću Efrajima. Juda će orati, Jakov branat\'.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (35, 10, 12, 'Sijte pravednost, požet ćete ljubav; krčite zemlje nove: vrijeme je da Jahvu tražite dok ne dođe i podaždi vam pravdom.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (35, 10, 13, 'Orali ste bezbožnost, želi bezakonje, jeli plod prijevare. Pouzdao si se u kola svoja i u mnoštvo svojih ratnika,');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (35, 10, 14, 'zato će se vika bojna razlijegati tvojim gradovima i sve će ti tvrđe biti razorene k\'o što Šalman razori Bet Arbel u dan ratni, kada mater smrskaše na sinovima.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (35, 10, 15, 'Evo što vam Betel učini jer ste u zlu ogrezli: u zoru će zavijek nestati kralja Izraelova!');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (35, 11, 1, 'Dok Izrael bijaše dijete, ja ga ljubljah, iz Egipta dozvah sina svoga.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (35, 11, 2, 'Al\' što sam ih više zvao, sve su dalje od mene odlazili; baalima su žrtvovali, kadili kumirima.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (35, 11, 3, 'A ja sam Efrajima hodati učio, držeći ga za ruke njegove; al\' oni ne spoznaše da sam se za njih brinuo.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (35, 11, 4, 'Užima za ljude privlačio sam ih, konopcima ljubavi; bijah im k\'o onaj koji u čeljustima njihovim žvale opušta; nad njega se saginjah i davah mu jesti.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (35, 11, 5, 'U zemlju egipatsku on će se vratiti, Asirac će mu kraljem biti, jer se ne htjede vratiti k meni.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (35, 11, 6, 'Mač će bješnjeti njegovim gradovima, uništiti prijevornice njegove, proždirat će zbog spletaka njegovih.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (35, 11, 7, 'Narod je moj sklon otpadu; i premda ga k Višnjem dozivlju, nitko da ga podigne.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (35, 11, 8, 'Kako da te dadem, Efrajime, kako da te predam, Izraele! Kako da te dadem kao Admu, da učinim s tobom kao Sebojimu? Srce mi je uznemireno, uzavrela mi sva utroba:');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (35, 11, 9, 'neću više gnjevu dati maha, neću opet zatirati Efrajima, jer ja sam Bog, a ne čovjek: Svetac posred tebe - neću više gnjevan dolaziti!');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (35, 11, 10, 'Za Jahvom će ići on, k\'o lav on će rikati; a kad zarikao bude, sinovi će mu veselo dohrliti sa zapada;');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (35, 11, 11, 'k\'o ptice će dohrliti iz Egipta, k\'o golubica iz zemlje asirske, i naselit ću ih po kućama njihovim - riječ je Jahvina.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (35, 12, 1, 'Opkolio me lažju Efrajim i prijevarom Izraelov dom. A i Juda još je nestalan Bogu, Svecu vjernome.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (35, 12, 2, 'Efrajim pase vjetar, za vjetrom istočnim trči cio dan, sve više je laži njegovih i nasilja. Savez sklapaju s Asirijom, ulje nose u Egipat.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (35, 12, 3, 'S Izraelom ima Jahve parnicu, kaznit će Jakova prema postupcima, vratit će mu po djelima njegovim.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (35, 12, 4, 'Već u krilu materinu brata je potisnuo, u snazi muževnoj s Bogom se borio.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (35, 12, 5, 'S Anđelom se borio i nadvladao ga, plakao je i zaklinjao ga. Našao ga je u Betelu i ondje mu je govorio.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (35, 12, 6, 'Da, Jahve, Bog nad Vojskama, Jahve je ime njegovo.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (35, 12, 7, 'Ti se dakle Bogu svojem vrati, čuvaj ljubav i pravednost i u Boga se svoga uzdaj svagda!');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (35, 12, 8, 'U ruci je Kanaanu kriva tezulja, on voli zakidati.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (35, 12, 9, 'I reče Efrajim: \"Samo sam se obogatio, blago sam nagomilao.\" Ali ništa mu od sveg dobitka neće ostati, jer se ogriješio bezakonjima.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (35, 12, 10, 'Ja sam Jahve, Bog tvoj, sve od zemlje egipatske, još ću ti dati da stanuješ pod šatorima kao u dane Sastanka;');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (35, 12, 11, 'govorit ću prorocima, umnožit ću viđenja i po prorocima prispodobom učiti.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (35, 12, 12, 'Gilead je puko bezakonje, ispraznost sama; u Gilgali žrtvuju bikove; zato će im oltari biti k\'o hrpe kamenja u brazdama poljskim.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (35, 12, 13, 'Jakov pobježe u kraj aramski, za ženu služaše Izrael, za ženu jednu stada čuvaše.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (35, 12, 14, 'Al\' po Proroku izvede Jahve Izraela iz Egipta, i po Proroku on ga je čuvao.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (35, 12, 15, 'Pregorko ga Efrajim uvrijedi: stoga će krv njegovu na nj svaliti, platit će mu Gospod njegov za pogrde.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (35, 13, 1, 'Kad je Efrajim govorio, strah je zadavao, jer bijaše on prvak u Izraelu, al\' ogriješi se Baalom i poginu.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (35, 13, 2, 'I sad još griješe oni od srebra praveć\' sebi kipove, kumire po svojoj mašti; svi su oni djelo rukotvorca! Tima - vele - žrtvujte, ljudi neka cjelivaju teoce!');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (35, 13, 3, 'Zato, bit će oni kao oblak jutarnji, kao rosa koje brzo nestaje, kao pljeva raznesena s gumna, kao dim što kroz otvor izlazi.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (35, 13, 4, 'A ja sam Jahve, Bog tvoj sve od zemlje egipatske: drugog Boga osim mene ne ljubi! Osim mene nema spasitelja.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (35, 13, 5, 'Ja te ljubljah u pustinji, u zemlji suhoj.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (35, 13, 6, 'Ja ih pasoh, i siti bijahu; nasićenima srce se uzoholi; i tako me zaboraviše.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (35, 13, 7, 'Stoga ću im biti kao lav, kao leopard što na putu vreba;');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (35, 13, 8, 'kao medvjedica kojoj ugrabiše mlade, ja ću se na njih baciti, rastrgat\' im grudi do srca; k\'o lav ću proždrijeti meso njihovo, zvijeri će ih poljske rastrgati.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (35, 13, 9, 'Uništit ću te, Izraele, i tko će ti pomoći?');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (35, 13, 10, 'TÓa gdje ti je kralj da te spasi, gdje tvoji knezovi da te brane - oni za koje si govorio: \"Daj mi kralja i knezove!\"');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (35, 13, 11, 'U gnjevu svom kralja ti dadoh i u srdžbi ti ga uzimam.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (35, 13, 12, 'Dobro se čuva bezakonje Efrajimovo, grijeh je njegov dobro pohranjen.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (35, 13, 13, 'Dođoše na nj trudovi porodiljski, ali on je ludo čedo, ne izlazi na vrijeme iz utrobe materine!');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (35, 13, 14, 'Ja ću ih izbaviti od vlasti Podzemlja, od smrti ću ih spasiti! Gdje je tvoja kuga, o smrti, gdje pomor tvoj, Podzemlje! Samilost se sakri od mojih očiju!');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (35, 13, 15, 'Tako je rodan među braćom Efrajim, ali će doći vjetar istočni, vjetar Jahvin iz pustinje: isušit će mu izvore, presahnuti studence, opljačkat mu riznicu, blago odnijeti.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (35, 14, 1, 'Ispaštat će Samarija jer se protiv Boga svoga pobunila. Od mača past će oni, djecu će njihovu smrskati, žene trudne rasporiti.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (35, 14, 2, 'Vrati se, Izraele, Jahvi Bogu svome, jer zbog svojeg si bezakonja posrnuo.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (35, 14, 3, 'Uzmite sa sobom riječi i Jahvi se vratite. Recite mu: \"Skini sa nas bezakonje i dobrohotno primi da ti prinesemo plod svojih usana.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (35, 14, 4, 'Asirac nas neće izbavljati i nećemo konje više jahati niti ćemo djelu ruku svojih govoriti: \'Bože naš!\' - jer u tebe sirota milost nalazi.\"');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (35, 14, 5, 'Iscijelit ću ih od njihova otpada, od svega ću ih srca ljubiti; jer gnjev se moj odvratio od njih.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (35, 14, 6, 'Bit ću kao rosa Izraelu; kao ljiljan on će cvasti, pustit će korijen poput jablana,');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (35, 14, 7, 'nadaleko pružat će izdanke. Ljepota će mu biti kao u masline, miris poput libanonskog.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (35, 14, 8, 'Opet će u mojoj sjeni boraviti, uzgajat će svoju pšenicu, vinograde gajit\' što će steći ime vina helbonskog.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (35, 14, 9, 'Efrajime, što ti imaš još s kumirima? Ja sam ga uslišao i pogledao. Ja sam poput zelena čempresa: po meni si rodan plodovima.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (35, 14, 10, 'Tko je mudar neka shvati ovo, i čovjek razuman neka spozna! Jer pravi su putovi Jahvini: pravednici hode po njima, grešnici na njima posrću.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (36, 1, 1, 'Riječ Jahvina koja dođe Joelu, sinu Petuelovu.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (36, 1, 2, 'Čujte ovo, starci, počujte, svi žitelji zemlje! Je li ovakvo što ikad bilo u vaše dane il\' u dane vaših otaca?');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (36, 1, 3, 'Recite ovo svojim sinovima, vaši sinovi svojim sinovima, a njihovi sinovi potonjem koljenu.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (36, 1, 4, 'Što ostavi šaška, proždrije skakavac, što ostavi skakavac, proždrije gusjenica, što ostavi gusjenica, proždrije ljupilac.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (36, 1, 5, 'Probudite se, pijanice, i plačite! Sve vinopije, tužite za novim vinom: iz usta vam je oteto.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (36, 1, 6, 'Jer prekri moju zemlju narod moćan i bezbrojan; zubi su mu kao zubi lavlji, očnjaci mu kao u lavice.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (36, 1, 7, 'Opustoši mi lozu vinovu i polomi smokve moje; oguli ih i razbaca, grane su im pobijeljele.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (36, 1, 8, 'Plačite k\'o djevica odjevena u kostrijet za zaručnikom svojim.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (36, 1, 9, 'Nestade prinosnice i ljevanice iz Doma Jahvina. Tuže svećenici, sluge Jahvine.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (36, 1, 10, 'Opustošeno polje, zemlja poharana. Poharano žito, vino propade, presahnu ulje.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (36, 1, 11, 'Tugujte, težaci, kukajte, vinogradari, za pšenicom i za ječmom, jer propade žetva poljska.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (36, 1, 12, 'Loza usahnu, uvenu smokva, mogranj, palma i jabuka: svako se drvo poljsko sasuši. Da, nestade radosti između sinova ljudskih.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (36, 1, 13, 'Svećenici, opašite kostrijet i tužite! Službenici žrtvenika, naričite! Dođite, prenoćite u kostrijeti, službenici Boga mojeg! Jer iz Doma Boga našeg nesta prinosnice i ljevanice!');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (36, 1, 14, 'Naredite sveti post, proglasite zbor svečani; starješine, saberite sve stanovnike zemlje u kuću Jahve, Boga svojeg. Zavapijte Jahvi:');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (36, 1, 15, '\"Jao dana!\" Jer Jahvin dan je blizu i dolazi k\'o pohara od Svevišnjeg.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (36, 1, 16, 'Ne iščeznu li hrana pred našim očima? Nije li nestalo radosti i sreće iz Doma Boga našega?');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (36, 1, 17, 'Istrunu zrnje pod grudama; puste su žitnice, porušene spreme jer žita nesta.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (36, 1, 18, 'Kako li stoka uzdiše! Krda goveda podivljala lutaju jer im nema paše. Čak i stada ovaca kaznu podnose.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (36, 1, 19, 'Tebi, Jahve, vapijem: oganj popali pašnjake pustinjske, plamen sažga sva stabla poljska.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (36, 1, 20, 'Čak i zvijeri čeznu za tobom, jer presušiše potoci, oganj popali pašnjake pustinjske.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (36, 2, 1, 'Trubite u trubu na Sionu! Dižite uzbunu na svetoj mi gori! Neka svi stanovnici zemlje dršću, jer dolazi Jahvin dan. Da, on je blizu.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (36, 2, 2, 'Dan pun mraka i tmine, dan oblačan i crn. K\'o zora po gorama se prostire narod jak i mnogobrojan, kakva ne bje nikad prije, niti će ga igda biti do vremena najdaljih.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (36, 2, 3, 'Pred njim oganj proždire, za njim plamen guta. Zemlja je k\'o vrt rajski pred njim, a za njim pustinja tužna. Ništa mu ne umiče.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (36, 2, 4, 'Nalik su na konje, jure poput konjanika.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (36, 2, 5, 'Buče kao bojna kola, po gorskim vrhuncima skaču, pucketaju k\'o plamen ognjeni kad strnjiku proždire, kao vojska jaka u bojnome redu.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (36, 2, 6, 'Pred njima narodi dršću i svako lice problijedi.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (36, 2, 7, 'Skaču k\'o junaci, k\'o ratnici se na zidove penju. Svaki ide pravo naprijed, ne odstupa od svog puta.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (36, 2, 8, 'Ne tiskaju jedan drugog, već svak\' ide svojom stazom. Padaju od strijela ne kidajuć\' redova.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (36, 2, 9, 'Na grad navaljuju, na zidine skaču, penju se na kuće i kroz okna ulaze poput lupeža.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (36, 2, 10, 'Pred njima se zemlja trese, nebo podrhtava, sunce, mjesec mrčaju, zvijezdama se trne sjaj.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (36, 2, 11, 'I Jahve glas svoj šalje pred vojsku svoju. I odista, tabor mu je silno velik, zapovijedi njegove moćan izvršitelj. Da, velik je Jahvin dan i vrlo strašan. Tko će ga podnijeti?');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (36, 2, 12, '\"Al\' i sada - riječ je Jahvina - vratite se k meni svim srcem svojim posteć\', plačuć\' i kukajuć\'.\"');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (36, 2, 13, 'Razderite srca, a ne halje svoje! Vratite se Jahvi, Bogu svome, jer on je nježnost sama i milosrđe, spor na ljutnju, a bogat dobrotom, on se nad zlom ražali.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (36, 2, 14, 'Tko zna neće li se opet ražaliti, neće li blagoslov ostaviti za sobom! Prinose i ljevanice Jahvi, Bogu našemu!');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (36, 2, 15, 'Trubite u trubu na Sionu! Sveti post naredite, oglasite zbor svečani,');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (36, 2, 16, 'narod saberite, posvetite zbor. Saberite starce, sakupite djecu, čak i nejač na prsima. Neka ženik iziđe iz svadbene sobe a nevjesta iz odaje.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (36, 2, 17, 'Između trijema i žrtvenika neka tuže svećenici, sluge Jahvine. Neka mole: \"Smiluj se, Jahve, svojem narodu! Ne prepusti baštine svoje sramoti, poruzi naroda. Zašto da se kaže među narodima: Gdje im je Bog?\"');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (36, 2, 18, 'Tad Jahve, ljubomoran na zemlju svoju, smilova se svom narodu.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (36, 2, 19, 'Odgovori Jahve svojem narodu: \"Šaljem vam, evo, žita, vina i ulja da se njime nasitite. Nikad više neću pustiti da budete na sramotu narodima.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (36, 2, 20, 'Protjerat ću Sjevernjaka od vas daleko, odagnat ga u zemlju suhu i pustu, prethodnicu u Istočno more, zalaznicu u Zapadno more. Dići će se njegov smrad, dizat će se trulež njegova.\" (Jer učini stvari velike.)');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (36, 2, 21, 'O zemljo, ne boj se! Budi sretna, raduj se, jer Jahve učini djela velika.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (36, 2, 22, 'Zvijeri poljske, ne bojte se; pašnjaci u pustinji opet se zelene, voćke daju rod, smokva i loza nose izobila.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (36, 2, 23, 'Sinovi sionski, radujte se, u Jahvi se veselite, svojem Bogu; jer vam daje kišu jesensku u pravoj mjeri, izli na vas kišu, jesensku i proljetnu kišu kao nekoć.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (36, 2, 24, 'Gumna će biti puna žita, kace će se prelijevati od vina i ulja.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (36, 2, 25, '\"Nadoknadit ću vam godine koje izjedoše skakavac, gusjenica, ljupilac i šaška, silna vojska moja što je poslah na vas.\"');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (36, 2, 26, 'Jest ćete izobila, jest ćete do sita, slavit ćete ime Jahve, svojeg Boga, koji je s vama čudesno postupao. (\"Moj se narod neće postidjeti nikad više.\")');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (36, 2, 27, '\"Znat ćete da sam posred Izraela, da sam ja Jahve, vaš Bog, i nitko više. Moj se narod neće postidjeti nikad više.\"');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (36, 3, 1, '\"Poslije ovoga izlit ću Duha svoga na svako tijelo, i proricat će vaši sinovi i kćeri, vaši će starci sanjati sne, a vaši mladići gledati viđenja.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (36, 3, 2, 'Čak ću i na sluge i sluškinje izliti Duha svojeg u dane one.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (36, 3, 3, 'Pokazat ću znamenja na nebu i zemlji, krv i oganj i stupove dima.\"');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (36, 3, 4, 'Sunce će se prometnut\' u tminu a mjesec u krv, prije nego svane Jahvin dan, velik i strašan.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (36, 3, 5, 'Svi što prizivaju ime Jahvino spašeni će biti, jer će na brdu Sionu i u Jeruzalemu biti spasenje, kao što Jahve reče, a među preživjelima oni koje Jahve pozove.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (36, 4, 1, '\"Jer, gle, u one dane i u ono vrijeme, kad okrenem udes Judeji i Jeruzalemu,');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (36, 4, 2, 'sakupit ću sve narode i povesti ih u dolinu Jošafat. Ondje ću im suditi zbog Izraela, naroda mog i moje baštine, koju rastjeraše među narode i razdijeliše moju zemlju među se.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (36, 4, 3, 'Baciše ždrijeb za moj narod; davali su dječake za bludnice, djevojke prodavali za vino i pili.\"');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (36, 4, 4, '\"I vi, Tire i Sidone, što hoćete od mene? I vi, filistejski kraljevi? Želite li mi se osvetiti? Ako se budete svetili meni, osveta će brzo na vaše glave.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (36, 4, 5, 'Na vas što mi oteste srebro i zlato, što odnesoste bogate mi riznice u svoje hramove,');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (36, 4, 6, 'na vas koji prodavaste Grcima sinove Jude i Jeruzalema da biste ih otjerali od domovine njihove.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (36, 4, 7, 'Gle, ja ih kanim dići s mjesta gdje god ih prodaste, i učinit ću da vam zločin vaš padne na glave.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (36, 4, 8, 'Prodat ću vaše sinove i kćeri sinovima Judinim, a oni će ih prodat\' Sabejcima, daleku narodu. Jer Jahve reče!\"');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (36, 4, 9, 'Razglasite ovo među narodima! Posvetite se za rat! Dižite junake! Naprijed, navalite, svi ratnici!');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (36, 4, 10, 'Prekujte raonike u mačeve, kosire u koplja, nek\' slabić kaže: \"Junak sam!\"');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (36, 4, 11, 'Pohitajte i dođite, svi okolni narodi, i ondje se saberite! (Jahve, onamo pošalji svoje junake!)');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (36, 4, 12, '\"Budite se, narodi, stupajte u Dolinu Jošafat, jer ću ondje sjesti da sudim svim okolnim narodima.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (36, 4, 13, 'Hvatajte se srpa: ljetina je zrela. Ustanite, siđite: tijesak je pun, prelijevaju se kace, jer je velika zloća njihova.\"');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (36, 4, 14, 'Mnoštvo, mnoštvo u Dolini Odluke! Da, blizu je dan Jahvin u Dolini Odluke!');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (36, 4, 15, 'Sunce i mjesec pomrčaše, zvijezde potamnješe.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (36, 4, 16, 'Jahve grmi sa Siona, glas diže iz Jeruzalema; nebo se i zemlja tresu. Ali je Jahve utočište svome narodu i zaštita sinovima Izraela.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (36, 4, 17, '\"Znat ćete tada da sam ja Jahve vaš Bog što stoluje na Sionu, svetoj gori svojoj. Jeruzalem će biti svetište, tuđinac više neće kroza nj proći.\"');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (36, 4, 18, 'Kad dođe taj dan, kapat će gore moštom, iz bregova će brizgati mlijeko, kroza sva korita riječna u Judeji voda će proteći. Vrelo će šiknuti iz kuće Jahvine da natopi Dolinu sitimsku.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (36, 4, 19, 'Egipat će opustjeti, Edom će postati beživotna pustinja zbog nasilja učinjena sinovima Judinim, jer proliše krv nevinu u njihovoj zemlji.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (36, 4, 20, 'Judeja će dovijek biti naseljena i Jeruzalem u sva koljena.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (36, 4, 21, '\"Osvetit ću krv njihovu za koju se nisam još osvetio.\" Jahve će dići Dom svoj na Sionu.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (37, 1, 1, 'Riječi Amosa, pastira iz Tekoe. Njegova viđenja o Izraelu u doba judejskoga kralja Uzije i Jeroboama, sina Joaša, izraelskoga kralja, dvije godine prije potresa.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (37, 1, 2, 'Veli on: \"Jahve grmi sa Siona, iz Jeruzalema glas mu se ori; stočarski pašnjaci tuže i suši se vrh Karmela.\"');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (37, 1, 3, 'Ovako govori Jahve: \"Za tri zločina Damaska, za četiri zločina, odluka je neopoziva: jer su vrhli Gilead cijepom željeznim,');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (37, 1, 4, 'pustit ću oganj na dom Hazaelov da sažeže Ben-Hadadove dvorce;');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (37, 1, 5, 'polomit ću zasune Damaska, istrijebiti živalj Bikat Avena i žezlonošu iz Bet Edena; narod će aramski u ropstvo u Kir,\" veli Jahve Gospod.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (37, 1, 6, 'Ovako govori Jahve: \"Za tri zločina Gaze, za četiri zločina, odluka je neopoziva: jer odvedoše sve u izgnanstvo i Edomu predadoše,');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (37, 1, 7, 'pustit ću oganj na zidine Gaze da dvorce joj sažeže.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (37, 1, 8, 'Istrijebit ću žitelje ašdodske i žezlonošu iz Aškelona. Pružit ću ruku na Ekron da ostatak filistejski pogine,\" veli Jahve Gospod.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (37, 1, 9, 'Ovako govori Jahve: \"Za tri zločina Tira, za četiri zločina, odluka je neopoziva: jer predade sve izgnanike Edomu i nisu se sjetili bratskog saveza,');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (37, 1, 10, 'pustit ću oganj na zidove Tira da sažeže njihove dvorce.\"');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (37, 1, 11, 'Ovako govori Jahve: \"Za tri zločina Edoma, za četiri zločina, odluka je neopoziva: jer gonjaše brata mačem prigušujuć\' samilost svoju, jer gnjev svoj potpirivaše jednako, jer poticaše bijes svoj,');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (37, 1, 12, 'pustit ću oganj na Teman da sažeže dvorce u Bosri.\"');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (37, 1, 13, 'Ovako govori Jahve: \"Za tri zločina Amonovih sinova, za četiri zločina, odluka je neopoziva: jer parahu trudnice gileadske da rašire granice svoje,');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (37, 1, 14, 'potpalit ću oganj na zidinama Rabe da dvorce joj sažeže, s bojnom grajom u dan rata, s burama u dan vihora,');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (37, 1, 15, 'a kralj će im otić\' u izgnanstvo, on i knezovi njegovi s njime,\" veli Jahve Gospod.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (37, 2, 1, 'Ovako govori Jahve: \"Za tri zločina Moaba, za četiri zločina, odluka je neopoziva: jer kosti edomskoga kralja spališe u vapno,');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (37, 2, 2, 'pustit ću oganj na Moab da dvorce kerijotske sažeže, a Moab će umrijet u metežu, s bojnom grajom i sa zvukom trube;');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (37, 2, 3, 'oborit ću suca u njemu i poklati sve knezove s njime,\" veli Jahve Gospod.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (37, 2, 4, 'Ovako govori Jahve: \"Za tri zločina Judina, za četiri zločina, odluka je neopoziva: jer odbaciše Zakon Jahvin i njegovih se odredaba ne držahu; zavedoše ih lažni bozi za kojima iđahu očevi njihovi,');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (37, 2, 5, 'pustit ću oganj na Judu, da sažeže dvorce jeruzalemske.\"');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (37, 2, 6, 'Ovako govori Jahve: \"Za tri zločina Izraela, za četiri zločina, odluka je neopoziva: jer prodavahu pravednika za srebro i nevoljnika za sandale;');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (37, 2, 7, 'jer gaze po glavi siromahu i sirotinju na zlo vode; sin i otac k istoj djevojci idu da oskvrnu moje sveto ime;');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (37, 2, 8, 'i na haljinama u zalog uzetima leže kraj svakoga žrtvenika; i piju vino oglobljenih u Domu Boga svojega.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (37, 2, 9, 'Ja pred njima istrijebih Amorejce visoke k\'o cedar, jake poput hrašća, ja uništih i plod na njima i korijen pod njima.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (37, 2, 10, 'Ja vas izvedoh iz zemlje egipatske i četrdeset vas godina vodih po pustinji da zaposjednete zemlju amorejsku.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (37, 2, 11, 'Ja podigoh proroke izmeđ\' vaših sinova i nazirejce među vašim mladićima. Nije li tako, sinovi Izraelovi? - riječ je Jahvina.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (37, 2, 12, 'Al\' vi nagnaste nazirejce da vino piju, a prorocima zapovjediste: \'Ne prorokujte!\'');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (37, 2, 13, 'Gle, ja vas prignječujem o tlo pod vama, k\'o što vršalice gnječe klasje;');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (37, 2, 14, 'neće biti bijega brzu, jaka neće učvrstiti snaga, junak se neće spasiti,');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (37, 2, 15, 'strijelac se neće održati, hitri trkač pobjeć\' neće, nit\' će jahač umaći,');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (37, 2, 16, 'najsrčaniji će ratnici bježat\' nagi onog dana\" - riječ je Jahvina.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (37, 3, 1, 'Počujte, sinovi Izraelovi, ovu riječ koju Jahve zbori protiv vas, protiv svakoga roda što ga izvedoh iz zemlje egipatske:');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (37, 3, 2, '\"Među svim plemenima zemaljskim samo vas poznah, zato ću vas kazniti za sve grijehe vaše.\"');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (37, 3, 3, 'Idu li dvojica zajedno da se ne dogovore?');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (37, 3, 4, 'Riče li lav u šumi ako plijena nema? Reži li lavić u brlogu ako ništa ne ulovi?');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (37, 3, 5, 'Pada l\' ptica na zemlju ako na njoj zamke nema? Diže li se mreža sa zemlje ako se ništa ne uhvati?');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (37, 3, 6, 'Trubi li truba po gradu da se narod ne uzbuni? Hoće li kob pogoditi grad ako je Jahve ne pošalje?');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (37, 3, 7, 'Ništa ne čini Jahve Gospod a da osnove svoje ne otkrije slugama svojim prorocima.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (37, 3, 8, 'Lav riče: tko da se ne prestravi? Gospod Jahve govori: tko da ne prorokuje?');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (37, 3, 9, 'Proglasite ovo po dvorcima asirskim i po dvorcima u zemlji egipatskoj; recite: \"Skupite se na planini Samarije, pogledajte velik nered u njoj i tlačenje posred nje.\"');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (37, 3, 10, 'Jer ne znaju činiti pravo - riječ je Jahvina - u dvorcima gomilaju nasilje i tlačenje.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (37, 3, 11, 'Stog ovako govori Jahve Gospod: \"Neprijatelj će opkoliti zemlju, utvrde će tvoje razvaliti, tvoje dvorce oplijeniti.\"');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (37, 3, 12, 'Ovako govori Jahve: \"Kao kad pastir istrgne dvije golijeni ili komadić uha iz lavljih ralja, tako će se istrgnuti sinovi Izraelovi koji sjede u Samariji na rubu počivaljke i na divanima.\"');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (37, 3, 13, 'Čujte i posvjedočite protiv doma Jakovljeva - riječ je Jahve Gospoda, Boga nad Vojskama:');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (37, 3, 14, '\"Onoga dana kad kaznim Izraela za zločine, kaznit ću i žrtvenike betelske; žrtvenički će se rozi odlomiti i na tlo popadati.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (37, 3, 15, 'Razorit ću zimsku kuću i ljetnu kuću, propast će kuće bjelokosne. Mnogih će kuća nestati\" - riječ je Jahvina.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (37, 4, 1, 'Počujte ovu riječ, krave bašanske, što boravite na samarijskoj gori, tlačite potrebite, ugnjetavate siromahe, govorite muževima: \"Donesi da pijemo!\"');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (37, 4, 2, 'Zakle se Jahve Gospod svetošću svojom: \"Dolaze vam, evo, dani kad će vas izvlačiti kukama, a posljednju od vas ostima.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (37, 4, 3, 'Kroz pukotine ćete izlaziti, ne obziruć\' se nikamo, i biti bačene prema Hermonu\" - riječ je Jahvina.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (37, 4, 4, '\"Idite samo u Betel i griješite, u Gilgal i množite grijehe svoje! Prinosite svakog jutra žrtve, i desetine svaki treći dan.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (37, 4, 5, 'Palite tijesto uskislo na žrtvu zahvalnicu, oglasite žrtve dragovoljne, razglasite ih, jer to volite, sinovi Izraelovi\" - riječ je Jahve Gospoda.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (37, 4, 6, '\"Zato dadoh da vam zubi čisti ostanu u svim gradovima vašim, ostavih vas bez kruha u svim selima vašim; pa ipak se ne obratiste k meni\" - riječ je Jahvina.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (37, 4, 7, '\"Uskratih vam i kišu tri mjeseca prije žetve; pustih da kiši na jedan grad, al\' ne i na drugi; jedno bi se polje nakvasilo, a drugo bi se - na koje ne pustih kiše - sasušilo.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (37, 4, 8, 'Dva-tri grada lutahu tako u treći da piju vode, ali se ne mogoše napiti, pa ipak se ne obratiste k meni\" - riječ je Jahvina.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (37, 4, 9, '\"Udarah vas snijeću i medljikom, sasuših vam vrtove i vinograde, proždriješe vam skakavci smokve i masline, pa ipak se ne obratiste k meni\" - riječ je Jahvina.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (37, 4, 10, '\"Poslah na vas kugu poput kuge egipatske; mladiće vaše poklah mačem, a konji vam bjehu k\'o plijen odvedeni; napunih vam nosnice smradom iz tabora vašega, pa ipak se ne obratiste k meni\" - riječ je Jahvina.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (37, 4, 11, '\"Obarah vas k\'o što Bog obori Sodomu i Gomoru, bijaste k\'o glavnja iz ognja istrgnuta, pa ipak se ne obratiste k meni\" - riječ je Jahvina.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (37, 4, 12, '\"Stog ću, Izraele, ovako s tobom postupiti, i jer ću tako s tobom postupiti, pripravi se, Izraele, da susretneš Boga svoga!\"');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (37, 4, 13, 'Jer, gle, on sazda planine i stvori vjetar, otkriva čovjeku misao svoju, on tvori zoru i mrak, i penje se na vrh visova zemaljskih, Jahve, Bog nad Vojskama, njegovo je ime.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (37, 5, 1, 'Počujte ovu riječ što je iznosim protiv vas, naricaljku, dome Izraelov:');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (37, 5, 2, 'Pade i više neće ustati djevica izraelska. Na tlu svojem ona leži, nikog da je digne.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (37, 5, 3, 'Jer ovako govori Jahve Gospod domu Izraelovu: u gradu iz kojeg izlažaše tisuća, ostat će stotina, iz kojeg izlažaše stotina, ostat će ih deset.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (37, 5, 4, 'Jer ovako govori Jahve domu Izraelovu: \"Tražite i živjet ćete.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (37, 5, 5, 'Ne tražite Betela, ne idite u Gilgal, ne putujte u Beer Šebu, jer će Gilgal bit odveden u izgnanstvo, a Betel će se prometnuti u ništa.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (37, 5, 6, 'Tražite Jahvu i živjet ćete, il\' će ko\' oganj zahvatiti kuću Josipovu i sažeć\' je, a u Betelu nikog da plamen ugasi.\"');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (37, 5, 7, 'Jao onima koji pravdu pretvaraju u pelin, u prah bacaju poštenje!');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (37, 5, 8, 'On napravi Vlašiće i Štapce, on obrće mrak u zoru, a dan u najglušu noć. On saziva morske vode i valja ih preko lica zemlje. Jahve mu je ime.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (37, 5, 9, 'Nenadano šalje pustoš na tvrđavu i utvrdi propast nosi.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (37, 5, 10, 'Mrze čovjeka što na vratima pravdu dijeli i grde onog što zbori pošteno.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (37, 5, 11, 'Stoga, jer gazite siromaha, dižući od njega porez u žitu - u kućama što ih sazdaste od tesanika nikad živjet\' nećete; iz ljupkih vinograda što ih posadiste nikad nećete piti vina.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (37, 5, 12, 'Jer znam mnoge vaše zločine, i vaše grijehe pregoleme: tlačite pravednika i primate mito, odbijajuć\' siromaha na gradskim vratima.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (37, 5, 13, 'Mudrac šuti u ovo vrijeme, jer vremena su tako zla.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (37, 5, 14, 'Tražite dobro, a ne zlo, da biste živjeli, i da Jahve, Bog nad Vojskama, odista s vama bude kao što velite da jest.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (37, 5, 15, 'Mrzite zlo, ljubite dobro, držite pravicu na gradskim vratima, pa će se možda Jahve, Bog nad Vojskama, smilovat\' ostatku Josipovu.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (37, 5, 16, 'Stog ovako govori Jahve, Bog nad Vojskama, Gospod: \"Na svakom će trgu biti kuknjava, po svim će ulicama zapomagati: \'Jao! Jao!\' Težake će sazvat\' da jauču, narikače da nariču,');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (37, 5, 17, 'bit će jauk u svakom vinogradu, jer ću proći posred tebe\" - veli Jahve.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (37, 5, 18, '\"Jao vama što žudite za danom Jahvinim! Što će vam biti dan Jahvin? Tama, a ne svjetlost.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (37, 5, 19, 'Bit će vam k\'o onom što uteče lavljim raljama, a sretne ga medvjed; koji uđe u kuću i stavi ruku na zid, a ujede ga zmija.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (37, 5, 20, 'Neće li dan Jahvin biti tama, a ne svjetlost? Mrklina, a ne sunčan sjaj?');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (37, 5, 21, 'Mrzim i prezirem vaše blagdane i nisu mi mile vaše svečanosti.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (37, 5, 22, 'Paljenice kad mi prinosite, prinosnice mi vaše nisu mile, na pričesnice se od ugojenih telaca vaših i ne osvrćem.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (37, 5, 23, 'Uklonite od mene dreku svojih pjesama, neću da slušam zvuke vaših harfa.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (37, 5, 24, 'Pravda nek\' poteče kao voda i pravica k\'o bujica silna.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (37, 5, 25, 'Prinosiste li mi žrtve i prinos u pustinji četrdeset godina, dome Izraelov?');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (37, 5, 26, 'Nosit ćete Sikuta, svoga kralja, i Kevana, boga svoga, likove što ih sebi napraviste,');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (37, 5, 27, 'dok vas budem odvodio onkraj Damaska,\" govori Jahve - Bog nad Vojskama njemu je ime.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (37, 6, 1, 'Jao bezbrižnima na Sionu i spokojnima na samarijskoj gori, nazvanima \"prvina naroda\", kojima se obraća dom Izraelov.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (37, 6, 2, 'Krenite u Kalnu i vidite, idite odande u Veliki Hamat, siđite u Gat filistejski. Jeste li bolji od tih kraljevstava? Je li im područje veće od vašega?');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (37, 6, 3, 'Mislite: daleko je kobni dan, a primičete vlast nasilja.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (37, 6, 4, 'Ležeći na bjelokosnim posteljama, na počivaljkama izvaljeni, jedu janjad iz stada i telad iz staje;');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (37, 6, 5, 'deru se uza zvuk harfe, izumljuju glazbala k\'o David,');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (37, 6, 6, 'piju vino iz vrčeva i mažu se najfinijim uljem, al\' za slom Josipov ne mare.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (37, 6, 7, 'Stog će prvi sad biti prognani; umuknut će veselje raskošnika.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (37, 6, 8, 'Zakle se Gospod Jahve samim sobom - riječ je Jahve, Boga nad Vojskama: \"Gnušam se oholosti Jakovljeve i mrzim dvorce njegove, predat ću grad i sve u njemu.\"');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (37, 6, 9, 'Ako i deset ljudi ostane u jednoj kući, umrijet će.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (37, 6, 10, 'Rođak će i spaljivač prionuti da iznesu kosti iz kuće; ako bi tko upitao onog u kutu kuće: \"Je li još tko ostao s tobom?\" on će odvratiti: \"Ne! Pst! Jahvino se ime ne smije spomenuti.\"');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (37, 6, 11, 'Jer, gle, Jahve zapovjedi, i velika se kuća ruši u komade, mala se kuća ori u komadiće.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (37, 6, 12, 'Jure li konji po litici, ore li se more volovima, da vi pretvarate pravdu u otrov a plod pravednosti u pelin?');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (37, 6, 13, 'Vi se radujete Lo Dabaru kad velite: \"Nismo li svojom snagom zauzeli Karnajim?\"');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (37, 6, 14, '\"Ha, evo, dome Izraelov, dižem na te - riječ je Jahve, Boga nad Vojskama - narod što će vas tlačiti od Ulaza hamatskoga do Pustinjskog potoka.\"');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (37, 7, 1, 'Evo što mi pokaza Jahve Gospod: gle, sazda skakavce kad otava poče nicati, otava nakon kraljevske kosidbe.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (37, 7, 2, 'Kad izjedoše sav zemaljski usjev, rekoh: \"Jahve Gospode, oprosti, molim te! Kako će Jakov preživjeti onako malen?\"');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (37, 7, 3, 'I Jahve se stoga pokaja: \"Neće biti\", reče Jahve.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (37, 7, 4, 'Evo što mi pokaza Jahve Gospod: Gle, Jahve Gospod pozva oganj da kažnjava; već proždrije veliki Bezdan i uprav poče gutati polje.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (37, 7, 5, 'A ja ću: \"Stani, Jahve Gospode, molim te! Kako će Jakov preživjeti onako malen?\"');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (37, 7, 6, 'I Jahve se stog pokaja: \"Ni ovoga neće biti\", reče Jahve Gospod.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (37, 7, 7, 'Evo što mi Jahve Gospod pokaza: gle, čovjek stoji na zidu, u ruci mu visak.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (37, 7, 8, '\"Što vidiš, Amose?\" - upita me Jahve. \"Visak\", rekoh. Tada Gospod reče: \"Evo, izmjerit ću viskom svoj narod izraelski; neću ga više štedjeti.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (37, 7, 9, 'Razorit će se uzvišice Izakove, opustjeti svetišta izraelska, i s mačem ću ustati na kuću Jeroboamovu.\"');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (37, 7, 10, 'Amasja, svećenik betelski, poruči izraelskom kralju Jeroboamu: \"Amos se urotio protiv tebe usred doma Izraelova; zemlja ne može više podnijeti njegovih riječi.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (37, 7, 11, 'Jer ovako on govori: \'Jeroboam će poginuti od mača, a Izrael će iz svoje zemlje u izgnanstvo.\'\"');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (37, 7, 12, 'Amasja reče Amosu: \"Odlazi, vidioče! Bježi u zemlju Judinu, ondje jedi kruh i ondje prorokuj!');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (37, 7, 13, 'Ali u Betelu da više nisi prorokovao, jer ovo je kraljevsko svetište, kraljevski hram.\"');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (37, 7, 14, '\"Nisam bio prorok ni proročki sin\" - odgovori Amos Amasji - \"bio sam stočar i gajio sam divlje smokve:');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (37, 7, 15, 'ali me Jahve uze od stada i Jahve mi reče: \'Idi, prorokuj mojemu narodu Izraelu.\'');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (37, 7, 16, 'Sada čuj riječ Jahvinu. Ti veliš: \'Ne prorokuj protiv Izraela, ne proriči protiv doma Izakova.\'');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (37, 7, 17, 'Zato ovako govori Jahve: \'Tvoja će žena bludničit\' po gradu, sinovi tvoji i kćeri od mača će pasti, tvoja će se zemlja užetom razdijeliti, a ti ćeš umrijeti na nečistu tlu, i Izrael će otići u izgnanstvo iz svoje zemlje.\'\"');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (37, 8, 1, 'Evo što mi pokaza Jahve Gospod: gle, kotarica zrela ploda:');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (37, 8, 2, '\"Što vidiš, Amose?\" - upita me. \"Kotaricu zrela ploda\", rekoh. Tada mi Jahve reče: \"Moj narod izraelski dozreo je za propast; neću ga više štedjeti.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (37, 8, 3, 'I hramske će pjevačice jaukati toga dana - riječ je Jahve Gospoda - bit će mnoštvo trupla, svuda će se bacati.\"');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (37, 8, 4, 'Slušajte ovo, vi što gazite potrebnika i satirete uboge u zemlji!');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (37, 8, 5, 'Kažete: \"Kad li će mlađak proći, da prodamo žito, i subota, da tržimo pšenicu. Smanjujuć\' efu, povećavajući šekel, da varamo krivim mjerama:');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (37, 8, 6, 'da kupimo siromaha za novac, potrebita za sandale, i da prodajemo otražak od žita.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (37, 8, 7, 'Zakle se Jahve Ponosom Jakovljevim: \"Dovijeka neću zaboraviti nijednoga vašeg djela.\"');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (37, 8, 8, 'Neće l\' se od toga zemlja potresti, protužiti svi njeni stanovnici, neće li se sva podići kao Nil, spustiti kao Rijeka egipatska?');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (37, 8, 9, '\"Toga ću dana - riječ je Jahve Gospoda - učiniti da sunce zapadne u podne, i pomračit ću zemlju u po bijela dana.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (37, 8, 10, 'Okrenut ću svetkovine vaše u kuknjavu i sve vaše pjevanje u tužaljku; obući ću u kostrijet svako bedro, oćelavit ću svaku glavu. Bit će kao kad se tuži za jedincem, i što ostane, bit će kao dan gorčine.\"');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (37, 8, 11, '\"Evo, dani dolaze - riječ je Jahve Gospoda - kad ću poslati glad na zemlju, ne glad kruha ni žeđ vode, već slušanja riječi Jahvine.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (37, 8, 12, 'Tumarat će od mora do mora, od sjevera do istoka potucati se ištući riječ Jahvinu, ali je neće naći.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (37, 8, 13, 'U onaj će dan obamirati od žeđi lijepe djevojke i mladići.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (37, 8, 14, 'Koji se kunu Grijehom samarijskim i zaklinju se: \'Tako živ bio bog tvoj, Dane!\' i: \'Tako živ bio Ljubimac tvoj, Beer Šebo!\' oni će pasti i nikad ustati neće.\"');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (37, 9, 1, 'Vidjeh Gospoda gdje stoji kraj žrtvenika i govori: \"Udari u glavice stupova, neka se pragovi zatresu! Svima ću satrti glave, što ostane, pod mač ću udariti. Nijedan neće uteći, nitko se neće spasiti.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (37, 9, 2, 'Zariju li se i u Podzemlje, iščupat će ih ruka moja. Popnu li se i na nebo, odande ću ih skinuti.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (37, 9, 3, 'Ako se sakriju i navrh Karmela, naći ću ih i pohvatati. Ako se od mog pogleda na dno morsko skriju, zapovjedit ću Zmaju da ih proždre.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (37, 9, 4, 'Ako i u izgnanstvo odu pred neprijateljem, naredit ću maču da ih sasiječe; upravit ću oči na njih, ali na nesreću, ne na dobro.\"');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (37, 9, 5, 'Jahve, Gospod nad Vojskama... on dodirne zemlju i ona se potrese, svi joj stanovnici protuže; diže se sva poput Nila i spušta k\'o Rijeka egipatska.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (37, 9, 6, 'On sazda sebi prijesto na nebesima, i svod svoj na zemlji osnova; on poziva morske vode i lijeva ih zemlji preko lica - Jahve mu je ime.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (37, 9, 7, '\"Sinovi Izraelovi, niste li za me kao i Kušani\" - riječ je Jahvina. \"Ne izvedoh li ja Izraela iz zemlje egipatske, kao Filistejce iz Kaftora i Aramejce iz Kira?\"');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (37, 9, 8, 'Gle, oči Jahve Gospoda uprte su na grešno kraljevstvo, izbrisat će ga s lica zemlje. \"Ipak neću sasvim zatrti dom Jakovljev\" - riječ je Jahvina.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (37, 9, 9, '\"Jer, gle, zapovijed ću dati i rastresti dom Izraelov među sve narode, k\'o što se trese žito u rešetu, da ni zrnce na zemlju ne padne.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (37, 9, 10, 'Svi grešnici naroda moga od mača će pasti, svi koji kažu: \'Nije blizu i neće nas stići nesreća.\'\"');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (37, 9, 11, '\"U dan ću onaj podići raspalu kolibu Davidovu, zatvorit\' joj pukotine, popraviti mjesta ruševna, opet je sazidati k\'o u stara vremena,');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (37, 9, 12, 'da osvoje ostatak Edoma i svih naroda nad kojima je zazvano ime moje\" - riječ je Jahve Gospoda, tvorca svega toga.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (37, 9, 13, '\"Evo dolaze dani - riječ je Jahvina - kada će orač stizat\' žeteoca, mastilac grožđa sijača, kad će planine procuriti mladim vinom i svi se bregovi prelijevati njime.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (37, 9, 14, 'Okrenut ću sudbinu naroda moga Izraela: obnovit će gradove srušene i živjeti u njima, saditi vinograde i vino im piti, zasaditi vrtove i jesti njihov rod.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (37, 9, 15, 'Posadit ću ih u zemlju njihovu i nikad se više neće iščupati iz zemlje koju im dadoh\" - veli Jahve, Bog tvoj.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (38, 1, 1, 'Viđenje Obadijino. Ovako govori Jahve Gospod Edomu! Čuli smo vijest od Jahve, glasnik bi poslan k narodima: \"Ustajte! Na nj u boj krenimo!\"');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (38, 1, 2, '\"Jer gle, učinit ću te najmanjim među narodima, prezrenim veoma.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (38, 1, 3, 'Uznositost srca tvoga zavela te, tebe što živiš u pećinama kamenim, u visoku stanu svojemu, i u srcu svome zboriš: \'Tko li će me na zemlju skinuti?\'');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (38, 1, 4, 'Da se vineš k\'o orao, gnijezdo sviješ među zvijezdama, i odande skinut ću te\" - riječ je Jahvina.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (38, 1, 5, '\"Dođu li k tebi lupeži il\' kradljivci noćni, kako li ćeš biti oplijenjen! Neće li te okrasti po miloj volji? Dođu li trgači k tebi, zar će i pabirka ostaviti?');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (38, 1, 6, 'Kako li Edom bješe pretresen, skrivena mu skrovišta pretražena!');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (38, 1, 7, 'Do granica te potjeraše, svi te saveznici tvoji prevariše, nadvladaše te tvoji prijatelji! Oni što kruh tvoj jedu zamku ti staviše: \'Sasvim je bez uma!\'');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (38, 1, 8, 'Neću li u dan onaj - riječ je Jahvina - uništit\' mudraca u Edomu i razum iz gore Ezavljeve?');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (38, 1, 9, 'Ratnike tvoje, Temane, užas će spopasti, i posljednji će biti istrijebljen na gori Ezavljevoj.\" \"Za pokolj');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (38, 1, 10, 'i nasilje nad bratom svojim Jakovom sram će te pokriti i nestat ćeš zasvagda.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (38, 1, 11, 'U dan onaj kad stajaše postrance, dok mu tuđinci blago odvodiše, dok stranci ulažahu na vrata njegova i ždrijeb bacahu za Jeruzalem, ti bijaše kao jedan od njih.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (38, 1, 12, 'Ne naslađuj se bratu u dan nesreće njegove! Ne likuj nad sinovima judejskim u dan propasti njine! Ne razvaljuj usta u dan tjeskobni!');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (38, 1, 13, 'Ne provaljuj na vrata naroda moga u dan nesreće njegove! Ne naslađuj se njegovom propašću u dan nesreće njegove! Ne pružaj ruke na imanje njegovo u dan nesreće njegove!');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (38, 1, 14, 'Ne stoj na raskršćima da pobiješ njegove bjegunce! Ne izdaji preživjelih njegovih u dan tjeskobni!\"');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (38, 1, 15, 'Jer blizu je Jahvin dan svima narodima! Dat će ti se milo za drago, tvoja će djela na tvoju glavu pasti.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (38, 1, 16, '\"Jest, kako vi piste na svetoj mi gori, pit će svi narodi bez oduška, pit će i iskapiti - i bit će k\'o da ih nigda bilo nije.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (38, 1, 17, 'Al\' na gori Sionu bit će spasenici - postat će sveta - i dom će Jakovljev baštiniti svoju baštinu.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (38, 1, 18, 'Dom će Jakovljev biti oganj, dom Josipov plamen, dom Ezavljev strnjika. Potpalit će ga i proždrijeti, i od doma Ezavljeva nitko neće ostati\" - riječ je Jahvina.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (38, 1, 19, 'Žitelji negepski baštinit će goru Ezavljevu, žitelji Šefele zemlju filistejsku; baštinit će kraj Efrajimov i kraj samarijski, a Benjamin će baštiniti Gilead.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (38, 1, 20, 'A izgnana nekoć vojska sinova Izraelovih baštinit će Kanaan sve do Sarfate; izgnanici jeruzalemski što su u Sefaradu baštinit će gradove negepske.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (38, 1, 21, 'Izbavitelji će uzaći na goru Sion da sude gori Ezavljevoj. I tada će nastat\' kraljevstvo Jahvino.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (39, 1, 1, 'Riječ Jahvina dođe Joni, sinu Amitajevu:');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (39, 1, 2, '\"Ustani,\" reče mu, \"idi u Ninivu, grad veliki, i propovijedaj u njemu, jer se zloća njihova popela do mene.\"');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (39, 1, 3, 'A Jona ustade da pobjegne u Taršiš, daleko od Jahve. Siđe u Jafu i nađe lađu što je plovila u Taršiš. Plati vozarinu i ukrca se da otplovi s njima u Taršiš, daleko od Jahve.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (39, 1, 4, 'Ali Jahve podiže na moru silan vjetar i nastade nevrijeme veliko na moru te mišljahu da će se lađa razbiti.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (39, 1, 5, 'Uplašiše se mornari; svaki zazva svoga boga, i da bi je olakšali, stadoše iz lađe bacati tovar što bijaše u njoj. Jona pak bijaše sišao na dno lađe, legao i zaspao tvrdim snom.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (39, 1, 6, 'Zapovjednik lađe pristupi mu i reče: \"Što spavaš kao zaklan? Ustaj i prizivlji Boga svojega! Možda će nas se sjetiti Bog taj da ne poginemo.\"');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (39, 1, 7, 'Potom rekoše jedni drugima: \"Hajde da bacimo ždrijeb da vidimo od koga nam dođe ovo zlo.\" Baciše ždrijeb i pade ždrijeb na Jonu.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (39, 1, 8, 'Oni mu onda rekoše: \"Kaži nam: zbog koga nas ovo zlo snađe, kojim se poslom baviš, odakle dolaziš, iz koje si zemlje i od kojega naroda?\"');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (39, 1, 9, 'On im odgovori: \"Ja sam Hebrej, i štujem Jahvu, Boga nebeskoga, koji stvori more i zemlju.\"');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (39, 1, 10, 'Ljudi se uplašiše veoma i rekoše mu: \"Što si to učinio!\" Jer bijahu doznali da on bježi od Jahve - sam im je to pripovjedio.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (39, 1, 11, 'Oni ga zapitaše: \"Što da učinimo s tobom da nam se more smiri?\" Jer se more sve bješnje dizalo.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (39, 1, 12, 'On im odgovori: \"Uzmite me i bacite u more, pa će vam se more smiriti, jer znam da se zbog mene diglo na vas ovo veliko nevrijeme.\"');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (39, 1, 13, 'Ljudi uzeše veslati ne bi li se primakli kopnu, jer se more sve bješnje dizalo protiv njih.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (39, 1, 14, 'Tad zazvaše Jahvu i rekoše: \"Ah, Jahve, ne daj da poginemo zbog života ovoga čovjeka i ne svali na nas krv nevinu, jer ti si Jahve: činiš kako ti je milo.\"');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (39, 1, 15, 'I uzevši Jonu, baciše ga u more - i more presta bjesnjeti.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (39, 1, 16, 'Tada velik strah Jahvin obuze ljude te prinesoše žrtvu Jahvi i učiniše zavjete.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (39, 2, 1, 'Jahve zapovjedi velikoj ribi da proguta Jonu. Tri dana i tri noći ostade Jona u ribljoj utrobi.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (39, 2, 2, 'Iz utrobe riblje stade Jona moliti Jahvu, Boga svojega.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (39, 2, 3, 'On reče: \"Iz nevolje svoje zavapih Jahvi, i on me usliša; iz utrobe Podzemlja zazvah, i ti si mi čuo glas.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (39, 2, 4, 'Ti me baci moru u dubine, i voda me opteče. Sve poplave tvoje i valovi oboriše se na me.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (39, 2, 5, 'Pomislih: odbačen sam ispred očiju tvojih. Al\' ipak oči upirem svetom Hramu tvojem.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (39, 2, 6, 'Vode me do grla okružiše, bezdan me opkoli. Trave mi glavu omotaše,');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (39, 2, 7, 'siđoh do korijena planina. Nada mnom se zatvoriše zauvijek zasuni zemljini. Al\' ti iz jame izvadi život moj, o Jahve, Bože moj.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (39, 2, 8, 'Samo što ne izdahnuh kad se spomenuh Jahve, i molitva se moja k tebi vinula, prema svetom Hramu tvojemu.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (39, 2, 9, 'Oni koji štuju isprazna ništavila milost svoju ostavljaju.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (39, 2, 10, 'A ja ću ti s pjesmom zahvalnicom žrtvu prinijeti. Što se zavjetovah, ispunit ću. Spasenje je od Gospoda.\"');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (39, 2, 11, 'Tada Jahve zapovjedi ribi i ona izbljuva Jonu na obalu.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (39, 3, 1, 'Riječ Jahvina dođe Joni drugi put:');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (39, 3, 2, '\"Ustani,\" reče mu, \"idi u Ninivu, grad veliki, propovijedaj u njemu što ću ti reći.\"');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (39, 3, 3, 'Jona ustade i ode u Ninivu, kako mu Jahve zapovjedi. Niniva bijaše grad velik do Boga - tri dana hoda.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (39, 3, 4, 'Jona prođe gradom dan hoda, propovijedajući: \"Još četrdeset dana i Niniva će biti razorena.\"');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (39, 3, 5, 'Ninivljani povjerovaše Bogu; oglasiše post i obukoše se u kostrijet, svi od najvećega do najmanjega.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (39, 3, 6, 'Glas doprije do kralja ninivskoga: on ustade s prijestolja, skide plašt sa sebe, odjenu se u kostrijet i sjede u pepeo.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (39, 3, 7, 'Tada se po odredbi kralja i njegovih velikaša oglasi i objavi u Ninivi: \"Ljudi i stoka, goveda i ovce da ne okuse ništa, ni da pasu, ni da vodu piju.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (39, 3, 8, 'Nego i ljudi i stoka da se pokriju kostrijeću, da glasno Boga zazivlju i da se obrati svatko sa svojega zlog puta i nepravde koju je činio.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (39, 3, 9, 'Tko zna, možda će se povratiti Bog, smilovati se i odustati od ljutoga svog gnjeva da ne izginemo?\"');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (39, 3, 10, 'Bog vidje što su činili: da se obratiše od svojega zlog puta. I sažali se Bog zbog nesreće kojom im bijaše zaprijetio i ne učini.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (39, 4, 1, 'Joni bi veoma krivo i rasrdi se.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (39, 4, 2, 'I ovako se pomoli Jahvi: \"Ah, Jahve, nisam li ja to slutio dok još u svojoj zemlji bijah? Zato sam htio prije pobjeći u Taršiš; jer znao sam da si ti Bog milostiv i milosrdan, spor na gnjev i bogat milosrđem i da se nad nesrećom brzo sažališ.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (39, 4, 3, 'Sada, Jahve, uzmi moj život, jer mi je bolje umrijeti nego živjeti.\"');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (39, 4, 4, 'Jahve odgovori: \"Srdiš li se ti s pravom?\"');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (39, 4, 5, 'Jona iziđe iz grada i sjede s istoka gradu; načini ondje kolibu i sjede pod njom u hlad da vidi što će biti od grada.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (39, 4, 6, 'A Jahve Bog učini da izraste bršljan nad Jonom i pruži sjenu njegovoj glavi te da ga izliječi od zlovolje. Jona se bršljanu veoma obradova.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (39, 4, 7, 'Ali sutradan, u osvit zore, Bog zapovjedi crvu da podgrize bršljan, i on usahnu.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (39, 4, 8, 'Kad je ogranulo sunce, posla Bog vruć istočni vjetar; sunce je palilo glavu Joninu te je sasvim klonuo. Poželje umrijeti i reče: \"Bolje mi je umrijeti nego živjeti.\"');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (39, 4, 9, 'Bog upita Jonu: \"Srdiš li se s pravom zbog bršljana?\" On odgovori: \"Da, s pravom sam ljut nasmrt.\"');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (39, 4, 10, 'Jahve mu reče: \"Tebi je žao bršljana oko kojega se nisi trudio, nego je u jednu noć nikao i u jednu noć usahnuo.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (39, 4, 11, 'A meni da ne bude žao Ninive, grada velikoga, u kojem ima više od sto i dvadeset tisuća ljudi koji ne znaju razlikovati desno i lijevo, a uz to i mnogo životinja!\"');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 1, 1, 'Riječ Jahvina, upućena Miheju Morešećaninu u vrijeme Jotama, Ahaza i Ezekije, kraljeva judejskih. Njegova viđenja o Samariji i o Jeruzalemu.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 1, 2, 'Čujte, narodi, vi svi! Slušaj, zemljo, i sve što te ispunja! Gospod Jahve protiv vas će svjedočiti - Gospod iz svetoga Hrama svojega!');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 1, 3, 'Jer evo: Jahve izlazi iz svetoga mjesta svojega, silazi i hodi po visovima zemaljskim.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 1, 4, 'Gore se rastapaju pod njegovim koracima i doline rasijedaju kao vosak pred ognjem, kao voda što se razlijeva niz obronak.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 1, 5, 'Sve je to za zločinstvo Jakovljevo i za grijehe doma Izraelova. Koje je zločinstvo Jakovljevo? Nije li Samarija? Što su uzvišice Judine? Nije li Jeruzalem?');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 1, 6, '\"Učinit ću od Samarije kamenu gomilu u polju, ledinu za vinograd. Zavaljat ću kamenje njezino u dolinu, otkrit ću joj temelje.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 1, 7, 'Razbit će se svi njeni kipovi, sva će joj se plaća bludnička ognjem spaliti, raskomadat ću sve njene idole, jer su od bludničke plaće nakupljeni, i opet će postati plaćom bludničkom.\"');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 1, 8, '\"Zato ću zakukati i zaridati, ići ću gol i bos, zavijat ću kao šakali, urlikat ću kao nojevi.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 1, 9, 'Jer njenoj rani nema lijeka, sve do Jude dopire, dotiče Vrata moga naroda, sve do Jeruzalema!');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 1, 10, 'Ne objavljujte toga u Gatu, u Akonu nemojte plakati! U Bet Leafri valjajte se u prašini!');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 1, 11, 'Odlazi sramotno, stanovnice šafirska! Iz svoga grada nije izašla stanovnica saananska! Bet Haesel iščupan je iz temelja, iz svojih čvrstih osnova.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 1, 12, 'Kako se može nadati sreći stanovnica marotska? Jer nesreća silazi od Jahve sve do vrata jeruzalemskih.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 1, 13, 'Upregni brze konje u bojna kola, stanovnice lakiška! To je bio početak grijeha Kćeri sionske, jer su se u tebi našla zločinstva Izraelova.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 1, 14, 'Zato ćeš dati otpusnicu Morešet Gatu, domovi će akzipski razočarati kraljeve izraelske.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 1, 15, 'Još ću ti dovesti osvajača, stanovnice mareška, stići će do Adulama slava Izraelova.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 1, 16, 'Čupaj kosu i ostriži se za milom djecom svojom! Postani ćelava kao orao lešinar, jer su izgnana daleko od tebe.\"');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 2, 1, 'Teško onima koji smišljaju nedjelo i snuju zlo na posteljama svojim! Kad svane dan, oni ga izvrše, jer je sila u njihovoj ruci.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 2, 2, 'Zažele li polja, otimaju ih, i kuće, uzimaju ih; čine nasilje čovjeku i kući njegovoj, vlasniku i posjedu njegovu.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 2, 3, 'Zato ovako govori Jahve: \"Evo tome rodu smišljam zlo iz kojega nećete izvući vratova, niti ćete hoditi ponosito, jer će biti zlo vrijeme.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 2, 4, 'U onaj će vam se dan složiti rugalica, zapjevati tužaljka i reći: \'Propalo je! Posve smo opustošeni, baština je naroda moga otuđena i nitko da mu je vrati, naša polja podijeljena su odmetniku.\'');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 2, 5, 'Zato neće biti nikoga tko bi bacio kocku za dio tvoj u zboru Jahvinu.\"');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 2, 6, '\"Ne balite!\" - bale oni - \"Tako se ne bali! Sramota na nas neće pasti!');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 2, 7, 'Zar će biti proklet dom Jakovljev? Zar je Jahve izgubio strpljivost? Zar on tako postupa? Nisu li riječi njegove ugodne Izraelu, narodu njegovu?\"');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 2, 8, 'Vi se sami dižete kao neprijatelji narodu mojemu. Čovjeku nezazornu vi otimate kabanicu, onome koji bez straha putuje ratne strahote dosuđujete.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 2, 9, 'Vi izgonite žene moga naroda iz njihovih milih domova; djeci njihovoj zauvijek oduzimate slavu koju sam im dao:');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 2, 10, '\"Ustanite, idite! Ovo nije počivalište! Zbog nečistoće teško vas uže svezalo.\"');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 2, 11, 'Kad bi mogao biti nadahnut čovjek koji izmišlja ovu opsjenu: \"Prorokujem ti vino i piće\", on bi bio prorok narodu ovome.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 2, 12, 'Svega ću te sabrati, Jakove, sakupit ću Ostatak Izraelov! Smjestit ću ih zajedno kao ovce u toru, kao stado na paši - neće se bojati nikoga.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 2, 13, 'Pred njima stupa rušilac: oni će se porušiti i ući, kroz vrata će proći i izaći; pred njima će ići njihov kralj, Jahve će biti na čelu.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 3, 1, 'Potom rekoh: \"Čujte sada, glavari kuće Jakovljeve, suci doma Izraelova! Nije li na vama da znate što je pravo? Ali vi mrzite dobro, a ljubite zlo!');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 3, 2, 'Vi ljudima derete kožu s tijela i meso s kosti njihovih.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 3, 3, 'Oni proždiru tijelo moga naroda i deru mu kožu, lome kosti. Oni ih komadaju kao u loncu, kao meso u punom kotlu!');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 3, 4, 'Zato, oni će Jahvu zazivati, a on im neće odgovoriti. Sakrit će, u ono vrijeme, lice od njih zbog zločina koje su počinili.\"');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 3, 5, 'Ovako govori Jahve protiv prorokÄa koji moj narod zavode: \"Ako imaju zalogaj u zubima, proglašuju: \'Mir!\' Ali protiv onoga koji im ništa ne stavlja u usta naviještaju sveti rat.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 3, 6, 'Zato ćete imati noć mjesto vaših viđenja i tminu mjesto proricanja. Zaći će sunce tim prorocima i dan će za njih pomrčati.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 3, 7, 'Tada će se posramiti vidovnjaci i zblaniti vračari. Svi će oni pokriti gubice, jer odgovora Božjeg neće biti.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 3, 8, 'Ali ja sam pun snage i duha Jahvina, pun pravde i jakosti da objavim Jakovu opačinu njegovu, Izraelu njegov grijeh.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 3, 9, 'Čujte dakle ovo, glavari kuće Jakovljeve, suci doma Izraelova, vi kojima se pravda gadi te izvrćete sve što je ispravno!');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 3, 10, 'Vi koji gradite Sion u krvi i Jeruzalem u zločinu!');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 3, 11, 'Glavari njegovi sude prema mitu, svećenici njegovi poučavaju radi zarade, proroci njegovi bale za novac. A na Jahvu se oni pozivaju i govore: \'Nije li Jahve u našoj sredini? Neće na nas zlo navaliti.\'');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 3, 12, 'Poradi vas i vaše krivnje Sion će biti polje preorano, Jeruzalem ruševina, a Goru Doma prekrit će šuma.\"');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 4, 1, 'Dogodit će se na kraju danÄa: Gora Doma Jahvina bit će postavljena vrh svih gora, uzvišena iznad svih bregova.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 4, 2, 'K njoj će se stjecat svi narodi, nagrnut će mnoga plemena i reći: \"Hajde, uziđimo na goru Jahvinu, u Dom Boga Jakovljeva! On će nas naučit\' svojim putovima, i hodit ćemo stazama njegovim. Jer će sa Siona Zakon izaći, riječ Jahvina iz Jeruzalema.\"');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 4, 3, 'On će upravljati mnogim pučanstvima i bit će sudac moćnim narodima. Svoje će mačeve prekovati u ralice, a svoja koplja u radne srpove. Narod na narod neće mača dizati niti će se više za rat vježbati.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 4, 4, 'Svaki će mirno živjeti pod lozom vinovom, pod smokvom svojom, i nitko ga neće plašiti. To rekoše usta Jahve nad Vojskama.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 4, 5, 'Jer svi narodi idu, svaki u ime boga svojega, a mi, mi idemo u imenu Jahve, Boga našega, uvijek i dovijeka.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 4, 6, '\"U onaj dan - riječ je Jahvina - sabrat ću hrome, okupiti raspršene i sve kojima sam zlo učinio.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 4, 7, 'Od hromih ću Ostatak učiniti, moćan narod od onih što su izgnani.\" Tada će Jahve nad njima kraljevati na gori Sionu od sada i dovijeka.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 4, 8, 'I ti Kulo stadÄa, Ofele Kćeri sionske, opet će se tebi vratiti prijašnja vlast, kraljevstvo Kćeri jeruzalemske.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 4, 9, 'Zašto sada kukaš kuknjavom? Nema li kralja u tebi? Zar su savjetnici tvoji propali da te obuzimlju bolovi kao porodilju?');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 4, 10, 'Savijaj se od boli i kriči, Kćeri sionska, kao žena koja porađa, jer ćeš sada iz grada izići i stanovati na polju. Do Babilona ti ćeš otići, ondje ćeš se osloboditi, ondje će te Jahve otkupiti iz šaka tvojih dušmana.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 4, 11, 'A sada se mnogi narodi protivu tebe sabraše. Oni govore: \"Neka se obeščasti, neka se naše oči nasite Siona!\"');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 4, 12, 'Ali zamisli Jahvine oni ne znaju i ne razumiju namjere njegove: kao snoplje na gumnu on ih je sabrao.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 4, 13, 'Ustani! Ovrši žito, Kćeri sionska, jer ti pravim gvozden rog i mjedena kopita. I satrt ćeš mnoge narode; zavjetovat ćeš Jahvi blago njihovo i bogatstvo njihovo Gospodaru sve zemlje.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 4, 14, 'Utvrdi se sada, Tvrđavo! Opkoljeni smo i opsjednuti, palicom po licu udaraju Suca Izraelova.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 5, 1, 'A ti, Betleheme Efrato, najmanji među kneževstvima Judinim, iz tebe će mi izaći onaj koji će vladati Izraelom; njegov je iskon od davnina, od vječnih vremena.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 5, 2, 'Zato će ih Jahve ostaviti dok ne rodi ona koja ima roditi. Tada će se Ostatak njegove braće vratiti djeci Izraelovoj.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 5, 3, 'On će se uspraviti, na pašu izvodit\' svoje stado silom Jahvinom, veličanstvom imena Boga svojega. Oni će u miru živjeti, jer će on rasprostrijeti svoju vlast sve do krajeva zemaljskih.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 5, 4, 'On - on je mir! Ako Asirci provale u našu zemlju, ako stupe u naše dvore, podići ćemo na njih sedam pastira, osam narodnih knezova.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 5, 5, 'Zemlju asirsku oni će mačem opasti, zemlju Nimrodovu sabljama. I on će nas osloboditi od Asiraca ako provale u našu zemlju, ako stupe na naše tlo.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 5, 6, 'Tada će Ostatak Jakovljev, među brojnim narodima, biti kao rosa koja od Jahve dolazi, kao kapljice kiše na travi koja ne čeka na čovjeka niti iščekuje sina čovječjeg.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 5, 7, 'Tada će Ostatak Jakovljev, među brojnim narodima, biti kao lav među šumskim zvijerima, kao lavić među ovčjim stadima: svaki put kad prolazi, on gazi nogama, razdire, i nitko da od njega izbavi.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 5, 8, 'Tvoja ruka neka se podigne na protivnike, svi tvoji neprijatelji bit će zatrti!');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 5, 9, '\"U onaj dan - riječ je Jahvina - potamanit ću sve tvoje konje, uništiti tvoja bojna kola;');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 5, 10, 'razorit ću po tvojoj zemlji svako naselje, porušiti sve tvoje tvrde gradove.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 5, 11, 'Zatrt ću iz tvoje ruke bajanje, vračara više nećeš imati;');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 5, 12, 'i zatrt ću u tebi sve kipove i stupove kamene. I ti se više nećeš klanjati pred djelom ruku svojih.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 5, 13, 'Iskorijenit ću ašere iz tebe i razorit ću tvoje gradove.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 5, 14, 'U gnjevu, u bijesu, izvršit ću osvetu na narodima koji nisu slušali.\"');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 6, 1, 'Čujte, dakle, riječ koju govori Jahve: \"Ustani! Povedi parnicu pred gorama, i neka bregovi čuju tvoj glas!\"');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 6, 2, 'Slušajte, gore, parnicu Jahvinu, čujte, temelji zemaljski, jer Jahve se parbi s narodom svojim, on se parniči s Izraelom:');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 6, 3, '\"Narode moj, što sam ti učinio? Čime sam te zamorio? Odgovori mi.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 6, 4, 'Ja sam tebe izveo iz zemlje egipatske, izbavio te iz kuće ropstva; poslao sam pred tobom Mojsija, Arona i Mirjamu.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 6, 5, 'Narode moj, sjeti se sada: Što je bio naumio Balak, kralj moapski? Što je njemu odgovorio Bileam, sin Beorov?...od Šitima do Gilgala, da poznaš pravedna djela Jahvina.\"');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 6, 6, '\"S čime ću doći pred Jahvu, hoću li pasti ničice pred Bogom Svevišnjim? Hoću li doći preda nj sa žrtvom paljenicom, s teocima od jedne godine?');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 6, 7, 'Hoće li mu biti mile tisuće ovnova, tisuće tisuća potokÄa ulja? Treba li prinijeti sina prvorođenog zbog svoga zločina, plod svoje utrobe zbog grijeha koji sam počinio?\"');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 6, 8, '\"Objavljeno ti je, čovječe, što je dobro, što Jahve traži od tebe: samo činiti pravicu, milosrđe ljubiti i smjerno sa svojim Bogom hoditi.\"');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 6, 9, 'Jahvin glas viče gradu: \"Slušajte, vi plemenjaci i sabore gradski!');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 6, 10, 'Zar mogu podnositi krivo stečeno blago i patvorenu efu prokletu?');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 6, 11, 'Mogu li opravdati onoga koji se služi mjerom krivom, vrećom krivotvorenih utega?');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 6, 12, 'Bogataši vaši puni su okrutnosti, stanovnici vaši laž govore, varljiv je jezik u njihovim ustima!');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 6, 13, 'Zato sam te i ja počeo udarati, tamaniti zbog grijeha tvojih.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 6, 14, 'Jest ćeš, a nećeš se nasititi, gladan ćeš ostati; stavljat ćeš na stranu, a ništa nećeš sačuvati; ako što i sačuvaš, ja ću maču predati.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 6, 15, 'Sijat ćeš, ali nećeš žeti; tijestit ćeš maslinu, a ulja neće biti; gazit ćeš mošt, a vina nećeš piti.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 6, 16, 'Držiš se zakona Omrijevih i svih djela doma Ahabova, živiš po osnovama njihovim: učinit ću od tebe pustinju, od žitelja tvojih porugu, da nosite sramotu mnogih naroda.\"');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 7, 1, 'Teško meni! Postao sam kao žetelac ljeti, kao trgač poslije jematve: nema bobice grožđa da je pozobljem, nema smokve ranke za kojom žudim!');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 7, 2, 'Vjernici su iščezli iz zemlje: nijednog pravednika među ljudima! Svi vrebaju za krvoprolićem, svaki svome bratu mrežu postavlja.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 7, 3, 'Njihove ruke za zlo su sposobne: glavar traži dar, sudac sudi prema poklonu, velikaš po svome hiru odlučuje.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 7, 4, 'I najbolji među njima je kao trn, najpravedniji kao drača živica. Iskušenje njihovo danas sa Sjevera dolazi, dolazi ura strave njihove.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 7, 5, 'Ne pouzdavajte se u bližnjega, ne vjerujte u prijatelja; pred onom koja s tobom dijeli postelju pazi da usta ne otvoriš.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 7, 6, 'Jer sin svoga oca zlostavlja, kćerka na majku ustaje, snaha na svoju svekrvu, svakome je dušmanin njegov ukućanin.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 7, 7, 'A ja, prema Jahvi ja sam zagledan, čekam na Boga koji spasava, Bog moj mene će uslišati.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 7, 8, 'Ne raduj se mome zlu, dušmanko moja, ako sam pao, ustat ću; ako boravim u tminama, Jahve je svjetlost moja.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 7, 9, 'Moram podnositi srdžbu Jahvinu, jer sam protiv njega sagriješio, sve dok on ne prosudi spor moj i izrekne pravdu; izvest će me na svjetlost, gledat ću pravednost njegovu.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 7, 10, 'Kada ga moja dušmanka ugleda, od stida će se pokriti ona koja mi je govorila: \"Gdje je on, Jahve, tvoj Bog?\" Moje će se oči naslađivati kad je ugledam: ona će biti zgažena kao blato na putu.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 7, 11, 'Dolazi dan kad će se sazidati tvoji bedemi! Toga dana nadaleko će se prostirati tvoje granice!');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 7, 12, 'Toga dana dolazit će k tebi od zemlje asirske do Egipta, od Tira do Rijeke, od mora do mora, od gore do gore.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 7, 13, 'Zemlja će postat\' pustinja zbog stanovnika svojih, zbog djela njihovih.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 7, 14, 'Pasi svoj narod svojom palicom, stado svoje baštine, koje osamljeno živi u šikarju, usred plodnih voćnjaka. Neka pase u Bašanu i Gileadu, kao u davne dane!');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 7, 15, 'Kao u dane kad si izašao iz Egipta, pokaži nam čudesa!');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 7, 16, 'Narodi će ih vidjeti i bit će posramljeni uza svu silu svoju; stavit će ruku na usta i uši će im oglušiti.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 7, 17, 'Lizat će prašinu kao zmija, kao gmazovi koji gmižu po zemlji. Izići će dršćući iz svojih jazbina, prestravljeni i ustrašeni pred tobom.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 7, 18, 'Tko je Bog kao ti koji prašta krivnju, koji grijeh oprašta i prelazi preko prekršaja Ostatka baštine svoje, koji ne ustraje dovijeka u svome gnjevu, nego uživa u pomilovanju?');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 7, 19, 'Još jednom, imaj milosti za nas! Satri naše opačine, baci na dno mora sve grijehe naše!');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 7, 20, 'Udijeli Jakovu vjernost svoju, dobrotu svoju Abrahamu, kako si se zakleo ocima našim od dana iskonskih.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 1, 1, 'Proročanstvo nad Ninivom. Knjiga viđenja Nahuma Elkošanina.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 1, 2, 'Jahve je Bog ljubomoran i osvetnik! Jahve se osvećuje, gospodar srdžbe! Jahve se osvećuje svojim protivnicima, ustrajan u gnjevu na neprijatelje.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 1, 3, 'Jahve je spor u gnjevu, ali silan u moći. Ne, Jahve neće pustiti krivca nekažnjena. U vihoru i oluji put je njegov, oblaci su prašina koju podižu njegovi koraci.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 1, 4, 'Prijeti moru i isušuje ga, presušuje sve rijeke....Bašan i Karmel uvenuli su, povenuli su pupoljci Libana!');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 1, 5, 'Pred njim se gore potresaju, bregovi se ljuljaju, zemlja se pod njim provaljuje, krug zemaljski i sve što na njem stanuje.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 1, 6, 'Tko može izdržati pred bijesom njegovim? Tko će odoljeti pred gnjevnom srdžbom njegovom? Jarost se njegova kao vatra izlijeva i litice se pred njim kidaju.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 1, 7, 'Jahve je dobar onima koji se u njeg\' uzdaju, on je okrilje u dan nevolje, poznaje one koji se njemu utječu');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 1, 8, 'kada potopne vode poplave. Uništit će one koji se protiv njega podižu, progonit će svoje dušmane u najmrkliji mrak.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 1, 9, 'Što vi snujete protiv Jahve? On uništava do kraja; nevolja se neće dva puta podići.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 1, 10, 'Kao trnovita šikara i kao pijanci na pijanki, k\'o suha slama bit će potpuno smlavljeni.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 1, 11, 'Iz tebe je potekao onaj koji snuje zlo protiv Jahve, savjetnik Belijala.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 1, 12, 'Jahve ovako govori: \"Neka su spremni, neka mnogobrojni, bit će pokošeni, uništeni. Ako sam te ponizio, neću te odsada ponižavati.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 1, 13, 'A sada, razbit ću jaram koji te steže, raskidat ću tvoje okove.\"');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 1, 14, 'Protiv tebe Jahve naređuje: \"Neće više biti roda tvoga imena, iz hrama tvojih bogova istrijebit ću likove rezane i livene, a od tvog groba ruglo ću učiniti.\"');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 2, 1, 'Gledajte, preko gora hrli glasnik, on naviješta: \"Spasenje!\" Svetkuj svoje blagdane, Judo, ispuni svoje zavjete, jer Belijal više neće prolaziti po tebi, on je sasvim zatrt.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 2, 2, 'Protiv tebe dolazi rušitelj. Postavi stražu na bedeme, gledaj na put, opaši bedra, saberi sve svoje snage.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 2, 3, 'Da, Jahve će obnoviti vinograd Jakovljev i vinograd Izraelov. Pljačkaši ih opljačkali, mladice im potrli.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 2, 4, 'Štitovi njegovih junaka crvene se, njegovi su ratnici u grimizu; ognjem blista čelik na njihovim bojnim kolima kad krenu u boj; konji im se propinju.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 2, 5, 'Po ulicama bjesne bojna kola, lete preko trgova; na pogled su baklje goruće; kao munje, samo sijevaju.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 2, 6, 'Pozivaju se borci odabrani, bacaju se u rovove, hrle brzo na bedeme, već je zaklon postavljen.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 2, 7, 'Vrata koja gledaju na Rijeku otvaraju se, strava je u palači.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 2, 8, 'Podižu, u izgnanstvo odvode Gospodaricu, robinjice njene cvile, tuguju kao golubice, u prsa se udaraju.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 2, 9, 'Niniva je nabujalo jezero, oni bježe pred vodom njezinom. \"Zaustavite se, stanite!\" Ali se nitko ne okreće.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 2, 10, '\"Grabite srebro! Grabite zlato!\" Blagu kraja nema, obilje dragocjenosti!');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 2, 11, 'Pljačkanje, haranje, razaranje! Srce zamire, koljena klecaju, u bedrima drhtavica, svima su lica poblijedjela.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 2, 12, 'Gdje je skrovište lavovima i log lavićima? Kad je lav izlazio, lavica je ostajala i lavovi mališani; plašio ih nitko nije.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 2, 13, 'Lav je grabio za svoje laviće, davio je za svoje lavice; svoje spilje punio je plijenom, svoja skrovišta lovinom.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 2, 14, '\"Evo me! Tebi!\" - riječ je Jahve nad Vojskama. \"Pretvorit ću u dim tvoja bojna kola, mač će poklati tvoje laviće. Istrijebit ću sa zemlje tvoja pljačkanja, i neće se više čuti povik tvojih glasnika.\"');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 3, 1, 'Teško gradu krvničkom, pun je laži, prepun grabeža, s pljačkanjem on ne prestaje!');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 3, 2, 'Slušajte! Pucaju bičem! Slušajte! Štropot točkova! Konji upropanj, kola poskakuju.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 3, 3, 'Konjanici u stremenu, mačevi sjaju, koplja sijevaju... gomile ranjenih, snopovi mrtvih, trupla unedogled, svuda se o truplo spotiče!');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 3, 4, 'Eto plaće za razvrat bludnice, ljupke ljubaznice, vješte čarobnice koja je zavodila narode svojim razvratom i plemena svojim čaranjima.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 3, 5, '\"Evo me! Tebi!\" - riječ je Jahve nad Vojskama. \"Na tvoje lice podignut ću skute tvoje haljine, tvoju golotinju pokazat ću narodima, tvoju sramotu kraljevstvima.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 3, 6, 'Bacit ću na tebe smeće, osramotit ću te, izložiti na stup sramote.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 3, 7, 'Svaki koji te vidi, bježat će od tebe. Reći će: \'Niniva! Kakva razvalina!\' Tko je može požaliti? Gdje joj naći tješitelje?\"');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 3, 8, 'Jesi li tvrđa od Tebe Amonove koja sjedi na rukavima Rijeke? Njezino predziđe bilo je more, njezini bedemi bile su vode.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 3, 9, 'Njezina snaga bila je Etiopija, Egipat; nije imala granica. Narodi Puta i Libije bili su joj pomoćnici.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 3, 10, 'A i ona je otišla u progonstvo, morala je ići u sužanjstvo; njezina nejaka djeca bila su razmrskana po svim raskršćima; za ugledne ljude njezine bacali su ždrijeb, svi njezini velikani okovani su lancima.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 3, 11, 'Tako ćeš i ti biti slomljena, bit ćeš svladana; tako ćeš i ti morati tražiti utočište pred dušmaninom.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 3, 12, 'Tvoje utvrde sve su kao smokvino stablo s urodom mladih smokava; kad se potrese stablo, smokve padaju u usta svakome koji ih želi jesti.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 3, 13, 'Gledaj svoj narod: sve je žensko u domu tvome; vrata tvoje zemlje širom se otvaraju neprijatelju; oganj je sažgao tvoje prijevornice.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 3, 14, 'Nacrpi vode za opsadu, utvrdi svoje bedeme, gnječi blato, gazi ilovaču, uzmi kalup za opeku.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 3, 15, 'A ipak će te oganj sažeći i mač potamaniti. Namnoži se kao kukci, namnoži se kao skakavci;');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 3, 16, '[16a] umnoži svoje trgovce da ih bude više nego zvijezda na nebu,');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 3, 17, '[17a] tvoje posade neka bude kao skakavaca, a tvojih pisara kao kobilica. Borave po zidovima kad je hladan dan. Sunce grane: [16b] kukci razvijaju krilašca i lete, [17b] i odlaze tko zna kamo.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 3, 18, 'Jao! Kako su zaspali tvoji pastiri, kralju asirski? Tvoji izabrani vojnici drijemaju, narod se tvoj raspršio po gorama, nitko ga više ne može sakupiti.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 3, 19, 'Tvojoj rani nema lijeka! Neizlječiva je tvoja ozljeda. Svi koji to saznaju plješću tvojoj razvalini. Tko nije bez sanka i prestanka osjećao na sebi tvoju okrutnost?');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 1, 1, 'Proroštvo koje vidje prorok Habakuk.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 1, 2, 'Dokle ću, Jahve, zapomagati, a da ti ne čuješ? Vikati k tebi \"Nasilje!\" a da ti ne spasiš?');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 1, 3, 'Zašto mi nepravdu iznosiš pred oči, zašto gledaš ugnjetavanje? Pljačka je i nasilje preda mnom. Raspra je, razmirica bjesni!');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 1, 4, 'Zakon je izgubio snagu, a pravda se ni načas ne pomalja. Da, zlikovac progoni pravednika, pravo je stoga izopačeno.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 1, 5, 'Obazrite se na narode, pogledajte, čudite se, zapanjite! Jer u vaše dane činim djelo u koje ne biste vjerovali da vam ga tko ispriča.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 1, 6, 'Da! Evo dižem Kaldejce, narod divlji i naprasit što nadire širom zemlje da obitavališta otme tuđa.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 1, 7, 'On je strašan i jezovit, od njega samog izlazi njegovo pravo i njegov ponos.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 1, 8, 'Konji su mu brži od leoparda, hitriji od vukova uvečer; jahači mu poskakuju, stižu izdaleka, ustremljeni k\'o orlovi da plijen proždru.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 1, 9, 'Svi će doći rad\' grabeža, lica im žegu k\'o istočni vjetar, grabe roblje kao pijesak!');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 1, 10, 'Taj se narod kraljevima ruga, podsmjehuje knezovima, poigrava se svim utvrdama, nasipa zemlju i zauzima ih.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 1, 11, 'Tad se k\'o vjetar okrenu i ode, zlikovac komu je snaga bog postala.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 1, 12, 'Nisi li od davnih vremena, Jahve, Bože moj, Sveče moj? Ti koji ne umireš! Ti si, Jahve podigao ovaj narod radi pravde, postavio ga, Stijeno, da kažnjava.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 1, 13, 'Prečiste su tvoje oči da bi zloću gledale. Ti ne možeš motriti tlačenja. Zašto gledaš vjerolomce, šutiš kad zlikovac ništi pravednijeg od sebe?');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 1, 14, 'Postupaš s ljudima k\'o s morskim ribama, k\'o s gmazovima što nemaju gospodara!');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 1, 15, 'On ih sve lovi na udicu, izvlači ih mrežom, pređom ih skuplja i tako se raduje i likuje.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 1, 16, 'Stog žrtvuje mreži svojoj, pali tamjan svojoj pređi jer mu pribavljaju zalogaj slastan, hranu pretilu.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 1, 17, 'Valja li, dakle, da neprestano poteže mač i kolje narod nemilice?');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 2, 1, 'Stat ću na stražu svoju, postavit se na bedem, paziti što će mi reći, kako odgovorit na moje tužbe.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 2, 2, 'Tada Jahve odgovori i reče: \"Zapiši viđenje, ureži ga na pločice, da ga čitač lako čita.\"');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 2, 3, 'Jer ovo je viđenje samo za svoje vrijeme: ispunjenju teži, ne vara; ako stiže polako, čekaj, jer odista će doći i neće zakasniti!');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 2, 4, 'Gle: propada onaj čija duša nije pravedna, a pravednik živi od svoje vjere.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 2, 5, 'Bogatstvo je odista podmuklo! Ohol je i ne može počinuti tko ždrijelo razvaljuje k\'o Podzemlje, tko je kao smrt nezasitan, tko sabire za se sve narode, tko kupi za se sva plemena!');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 2, 6, 'Zar mu se neće svi podrugivati, rugalicu i zagonetku spjevat\' protiv njega? Reći će: Jao onom tko množi što nije njegovo (a dokle će?) i opterećuje se zalogama!');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 2, 7, 'Neće li naglo ustat\' vjerovnici tvoji, neće li se probuditi ljuti tvoji tlačitelji? Tada ćeš im plijen biti!');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 2, 8, 'Jer si opljačkao mnoge narode, sav ostatak naroda opljačkat će tebe, jer si prolio krv ljudsku, poharao zemlju, grad i sve mu žitelje.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 2, 9, 'Jao onom tko otimačinu zgrće nepravednu kući svojoj, da visoko svije gnijezdo svoje i otkloni ruku zla!');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 2, 10, 'Nanese sramotu kući svojoj: zatirući mnoga plemena, griješiš protiv sebe.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 2, 11, 'Jer iz samih zidova kamen kriči, a krovna mu greda odgovara.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 2, 12, 'Jao onom tko grad diže krvlju i tvrđavu zasnuje na nepravdi!');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 2, 13, 'Nije li to, gle, od Jahve nad Vojskama da se narodi za oganj trude, puci nizašto muče?');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 2, 14, 'Jer će se zemlja napuniti znanja o slavi Jahvinoj kao što vode prekrivaju more.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 2, 15, 'Jao onom tko bližnjeg navodi na piće, ulijeva otrov dok on pije da bi promatrao njegovu nagost!');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 2, 16, 'Ti si pijan od sramote, ne od slave! Pij samo i pokazuj kapicu. Dolazi ti pehar iz desnice Jahvine i sramota na slavu tvoju!');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 2, 17, 'Nasilje nad Libanonom tebe će prestraviti, pokolj zvijeri, jer si ljudsku krv prolio, poharao zemlju, grad i njegove žitelje.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 2, 18, 'Čemu koristi tesan lik da ga umjetnik teše? Čemu lijevan lik, lažno proroštvo, da se tvorac njegov u nj pouzdaje oblikujuć\' nijeme kipove?');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 2, 19, 'Jao onom tko komadu drva kaže: \"Probudi se!\" Kamenu nijemom: \"Preni se!\" On da prorokuje? Optočen može biti i zlatom i srebrom, ali nikakva daha životnog nema u njemu.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 2, 20, 'Ali je Jahve u svojem svetom Hramu: nek\' zemlja sva zašuti pred njime!');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 3, 1, 'Molitva. Od proroka Habakuka. Na način tužbalice.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 3, 2, 'Jahve, čuo sam za slavu tvoju, Jahve, tvoje mi djelo ulijeva jezu! Ponovi ga u naše vrijeme! Otkrij ga u naše vrijeme! U gnjevu se svojem smilovanja sjeti!');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 3, 3, 'Bog stiže iz Temana, a Svetac s planine Parana! Veličanstvo njegovo zastire nebesa, zemlja mu je puna slave.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 3, 4, 'Sjaj mu je k\'o svjetlost, zrake sijevaju iz njegovih ruku, ondje mu se krije sila.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 3, 5, 'Kuga pred njim ide, groznica ga sustopice prati.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 3, 6, 'On stane, i zemlja se trese, on pogleda, i dršću narodi. Tad se raspadoše vječne planine, bregovi stari propadoše, njegove su staze od vječnosti.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 3, 7, 'Prestrašene vidjeh kušanske šatore, čadore što dršću u zemlji midjanskoj.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 3, 8, 'Jahve, planu li tvoj gnjev na rijeke ili jarost tvoja na more te jezdiš na svojim konjima, na pobjedničkim bojnim kolima?');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 3, 9, 'Otkrivaš svoj luk i otrovnim ga strijelama sitiš. Bujicama rasijecaš tlo,');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 3, 10, 'planine dršću kad te vide, navaljuje oblaka prolom, bezdan diže svoj glas.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 3, 11, 'Sunce uvis diže ruke, mjesec u obitavalištu svojem popostaje, pred blijeskom tvojih strijela, pred blistavim sjajem koplja tvoga.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 3, 12, 'Jarosno po zemlji koračaš, srdito gaziš narode.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 3, 13, 'Iziđe da spasiš narod svoj, da spasiš svog pomazanika; sori vrh kuće bezbožnikove, ogoli joj temelje do stijene.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 3, 14, 'Kopljima si izbo vođu ratnika njegovih, koji navališe da nas s radošću satru, kao da će potajice proždrijet\' ubogoga.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 3, 15, 'Gaziš po moru s konjima svojim, po pučini silnih voda!');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 3, 16, 'Čuo sam! Sva se moja utroba trese, podrhtavaju mi usne na taj zvuk, trulež prodire u kosti moje, noge klecaju poda mnom. Počinut ću kada dan tjeskobni svane narodu što nas sad napada.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 3, 17, 'Jer smokvino drvo neće više cvasti niti će na lozi biti ploda, maslina će uskratiti rod, polja neće donijeti hrane, ovaca će nestati iz tora, u oborima neće biti ni goveda.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 3, 18, 'Ali ja ću se radovati u Jahvi i kliktat ću u Bogu, svojem Spasitelju.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 3, 19, 'Jahve, moj Gospod, moja je snaga, on mi daje noge poput košutinih i vodi me na visine. Zborovođi. Na žičanim glazbalima.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 1, 1, 'Riječ Jahvina upućena Sefaniji, sinu Kušija, sina Gedalijina, sina Amarjina, sina Ezekijina, u vrijeme Jošije, sina Amonova, kralja judejskoga.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 1, 2, '\"Da, sve ću zbrisati s lica zemlje\" - riječ je Jahvina!');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 1, 3, '\"Izbrisat ću ljude i zvijeri, ptice nebeske i ribe morske, učinit ću da padnu bezbožnici, istrijebit ću ljude s lica zemlje\" - riječ je Jahvina!');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 1, 4, '\"Podignut ću ruku na Judu i na sve stanovnike Jeruzalema i istrijebit ću iz ovoga mjesta ostatak Baalov, ime služitelja idolskih sa svećenicima njegovim;');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 1, 5, 'one koji se klanjaju na krovovima vojsci nebeskoj, one koji se klanjaju pred Jahvom a zaklinju se Milkomom;');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 1, 6, 'one koji su se odmetnuli od Jahve, koji ne traže Jahvu i nimalo za nj ne mare.\"');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 1, 7, 'Tišina pred Jahvom Gospodom, jer je dan Jahvin blizu! Da, Jahve je prigotovio žrtvu, posvetio je svoje uzvanike.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 1, 8, '\"U dan žrtve Jahvine, kaznit ću knezove, sinove kraljeve, i sve koji se oblače na način tuđinski.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 1, 9, 'Kaznit ću u taj dan sve koji preko praga poskakuju, koji Dom Gospodara svojega pune nasiljem i prijevarom.\"');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 1, 10, '\"U onaj dan\" - riječ je Jahvina - \"vapaj će se podići od Ribljih vrata, urlici iz novog dijela grada, silna lomljavina sa brežuljaka.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 1, 11, 'Kukajte, stanovnici makteški, jer je satrt sav narod kanaanski, zbrisani su svi mjerači srebra.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 1, 12, 'I u to vrijeme pretražit ću Jeruzalem sa zubljama i pohodit ću kaznom ljude koji miruju na svojoj vinskoj droždini i u svom srcu govore: \'Jahve ne može učiniti ni dobro ni zlo.\'\"');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 1, 13, 'Blago njihovo bit će prepušteno pljački, njihove kuće pustošenju. Oni su gradili kuće - neće u njima stanovati; sadili su vinograde - iz njih vina neće piti.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 1, 14, 'Blizu je dan Jahvin, veliki! Blizu je i žurno dolazi! Gorak je glas dana Jahvina: tada će i junak zajaukati.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 1, 15, 'Dan gnjeva, onaj dan! Dan tjeskobe i nevolje! Dan užasa i pustošenja! Dan pomrčine i naoblake! Dan tmina i magluština!');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 1, 16, 'Dan trubljavine i bojne vike na gradove utvrđene i na visoka kruništa.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 1, 17, '\"Prepustit ću ljude nevoljama i vrludat će kao slijepci (jer su protiv Jahve sagriješili), krv će se njihova prosuti kao prašina, njihova trupla bit će bačena kao smeće.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 1, 18, 'Ni njihovo srebro ni njihovo zlato neće ih spasiti.\" U dan gnjeva Jahvina oganj njegove revnosti svu će zemlju sažeći. Jer on će uništiti, zatrti sve stanovnike zemlje.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 2, 1, 'Saberite se, skupite, narode bestidni');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 2, 2, 'prije nego budete izgnani kao pljeva koja se u dan rasprši, prije nego stigne na vas plamen i gnjev Jahvin, prije nego stigne na vas dan gnjeva Jahvina.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 2, 3, 'Tražite Jahvu, svi skromni na zemlji, svi koji izvršavate odredbe njegove! Tražite pravdu, tražite poniznost: vi ćete možda biti zaštićeni u dan gnjeva Jahvina.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 2, 4, 'Da, Gaza će postati pustinja, Aškelon pustoš. Ašdod u puklo podne bit će izgnan, Ekron iz temelja iščupan.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 2, 5, 'Teško stanovnicima obale morske, narodu kretskome! Evo riječi Jahvine protivu vas: \"Ja ću te poniziti, zemljo Filistejaca, uništit ću te, istrijebit ću sve tvoje stanovnike!');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 2, 6, 'I postat ćeš ispaša, pasište pastirsko i ograda za stado.\"');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 2, 7, 'I taj kraj pripast će u dio Ostatku doma Judina; tu će oni izvoditi blago na pašu; uvečer se odmarati u kućama aškelonskim, jer će ih pohoditi Jahve, Bog njihov, i on će promijeniti sudbinu njihovu.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 2, 8, 'Čuo sam uvredu Moabovu i podrugivanja sinova Amonovih kad su vrijeđali moj narod i ponosili se zemljištem svojim.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 2, 9, '\"Zato, života mi moga!\" - riječ je Jahve nad Vojskama, Boga Izraelova: \"Moab će postati kao Sodoma i sinovi Amonovi kao Gomora: polje obraslo koprivom, hrpa soli pustoš dovijeka. Ostatak moga naroda oplijenit će ih, preostatak moga naroda zaposjest će ih.\"');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 2, 10, 'To će biti cijena za njihovu oholost jer su se uznosili i rugali narodu Jahve nad Vojskama.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 2, 11, 'Za njih će Jahve biti strašan: kad uništi sve bogove zemaljske, pred njim će se pokloniti - svaki na svojoj zemlji - svi otoci naroda.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 2, 12, 'I vi, Etiopljani: \"Vi ćete biti probijeni mojim mačem.\"');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 2, 13, 'Zatim će svoju ruku dići protiv Sjevera i razrušit će zemlju asirsku, od Ninive će pustoš učiniti, suhu pustoš kao pustinja.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 2, 14, 'Usred nje će stado ležati, zvijeri svakojake; čaplje i pelikani počivat će noću na glavicama stupova, sova će hukati na prozoru, gavran graktati na pragu.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 2, 15, 'To li je veseli grad koji je stolovao u miru, koji je u svom srcu govorio: \"Ja, i jedino ja!\" Gledaj! Postade razvalina, brlog zvjerinji! Svi koji pokraj njega prolaze zvižde i mašu rukama.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 3, 1, 'Teško nepokornom, okaljanom, nasilničkom gradu!');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 3, 2, 'On nikada nije čuo poziva, nikada nije prihvatio pouku; Jahvi on se nikada nije povjerio; svome Bogu nije se nikada približio.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 3, 3, 'Njegovi su knezovi usred njega - lavovi koji riču; njegovi su suci - vuci večernji koji do jutra nisu kosti glodali;');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 3, 4, 'proroci su njegovi - razmetljivci, puki lažljivci, svećenici njegovi skvrne Svetište, krše Zakon.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 3, 5, 'Usred njega, Jahve je pravedan - on ne čini nepravde; svako jutro iznosi svoju pravicu, u praskozorje ne izostaje; ali bezbožnik srama ne poznaje.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 3, 6, '\"Uništio sam narode, razorena su kruništa kula njihovih, poharao sam njihove ulice: nema više prolaznika! Razoreni su njihovi gradovi: nema ljudi, nema stanovnika!');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 3, 7, 'Govorio sam: \'Ti ćeš se mene ipak bojati, prigrlit ćeš pouku; u njihovim očima ne mogu nestati toliki moji pohodi.\' Ali ne! - oni su žurno pokvarili sva djela svoja.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 3, 8, 'Zato mene čekajte - riječ je Jahvina - do dana kad ustanem kao tužilac; jer ja sam odredio da se sakupe narodi, da se saberu kraljevstva, da na vas gnjev svoj izlijem, svu gorčinu svoje srdžbe: u vatri moje ljubomore bit će sva zemlja sažgana.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 3, 9, 'Dat ću narodima čiste usne, da svi mogu zazivati ime Jahvino i služiti mu jednodušno.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 3, 10, 'S druge obale rijeka etiopskih prinosit će mi žrtvene darove moji štovaoci.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 3, 11, 'U onaj dan nećeš se sramiti svih svojih nedjela koja si protiv mene počinio, jer ću ukloniti iz tebe tvoje ohole hvalisavce; i nećeš se više šepiriti na Svetoj gori mojoj,');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 3, 12, 'jer ću pustiti da u tebi opstane samo skroman i čedan narod, i u imenu Jahvinu tražit će okrilje');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 3, 13, 'Ostatak Izraelov. Oni neće više činiti nepravdu, neće više govoriti laži; u njihovim ustima neće se više naći jezik prijevarni. Moći će pasti i odmarati se, i nitko im neće smetati.\"');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 3, 14, 'Klikći od radosti, Kćeri sionska, viči od veselja, Izraele! Veseli se i raduj se iz sveg srca, Kćeri jeruzalemska!');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 3, 15, 'Jahve te riješio tvoje osude, neprijatelje tvoje uklonio! Jahve, kralj Izraelov, u sredini je tvojoj! Ne boj se više zla!');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 3, 16, 'U onaj dan reći će se Jeruzalemu: \"Ne boj se, Sione! Neka ti ne klonu ruke!');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 3, 17, 'Jahve, Bog tvoj, u sredini je tvojoj, silni spasitelj! On će se radovati tebi pun veselja, obnovit će ti svoju ljubav, kliktat će nad tobom radosno');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 3, 18, 'kao u dan svečani. Odvratio sam od tebe nevolju da na sebi više ne nosiš sramotu.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 3, 19, 'Evo svladavam sve tvoje tlačitelje. U ono vrijeme izbavit ću sve hrome, sabrat ću prognane, pribavit im hvalu i diku po svoj zemlji gdje ih sramota bijaše dopala.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 3, 20, 'U ono vrijeme ja ću vas dovesti, u ono vrijeme ja ću vas sabrati! Tada ću vam dati hvalu i diku među narodima zemlje, kad okrenem vašu sudbinu pred vašim očima\" - govori Jahve.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 1, 1, 'Druge godine kralja Darija, šestoga mjeseca, prvoga dana u mjesecu, dođe riječ Jahvina preko proroka Hagaja Zerubabelu, sinu Šealtielovu, namjesniku judejskom, i Jošui, sinu Josadakovu, velikom svećeniku:');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 1, 2, '\"Ovako govori Jahve nad Vojskama. Narod ovaj govori: \'Nije još došlo vrijeme da se opet sazda Dom Jahvin!\'');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 1, 3, 'Zato je došla riječ Jahvina preko proroka Hagaja:');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 1, 4, 'A vama je vrijeme da stanujete u pokrivenim kućama, dok je ovaj Dom razvaljen.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 1, 5, 'I zato, ovako sada govori Jahve nad Vojskama: Razmotrite svoje putove!');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 1, 6, 'Sijete mnogo, malo dovozite; jedete, a niste siti; pijete, a napojit\' se ne možete; odijevate se, a nije vam toplo. Poslenik zarađuje plaću, a stavlja je u prodrt tobolac!\"');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 1, 7, 'Ovako govori Jahve nad Vojskama: \"Razmotrite svoje putove!');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 1, 8, 'Idite na goru, dovezite drva i podignite opet Dom; bit će mi to milo i proslavit ću se\" - govori Jahve.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 1, 9, '\"Nadaste se obilju, a gle, malo je; što dovezete kući, ja otpuhnem. A zašto?\" - riječ je Jahve nad Vojskama. \"Zato što je Dom moj razvaljen, dok se svaki od vas brine za dom svoj.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 1, 10, 'Stog\' je nebo uskratilo rosu, a zemlja uskratila usjeve.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 1, 11, 'Ja dozvah sušu na zemlju i gore, na žito i vino, na ulje i na sve što zemlja rađa, na ljude i stoku i na svaki trudno stečen plod.\"');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 1, 12, 'A Zerubabel, sin Šealtielov, i Jošua, sin Josadakov, veliki svećenik, i sav ostali narod poslušaše glas Jahve, Boga svojega, i riječi proroka Hagaja u onome radi čega ga Jahve njima posla: i narod se poboja Jahve.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 1, 13, 'Tada Hagaj, glasnik Jahvin, po Jahvinu nalogu ovako reče narodu: \"Ja sam s vama\" - riječ je Jahvina. -');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 1, 14, 'Jahve probudi duh Zerubabelu, sinu Šealtielovu, namjesniku judejskom, i duh Jošui, sinu Josadakovu, velikom svećeniku, i duh svemu ostalom narodu te oni dođoše i prionuše na posao u Domu Jahve nad Vojskama, Boga svojega.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 1, 15, 'Bijaše to dvadeset i četvrtoga dana šestog mjeseca.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 2, 1, 'Druge godine kralja Darija, sedmoga mjeseca, dvadeset i prvoga dana u mjesecu, dođe riječ Jahvina preko proroka Hagaja:');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 2, 2, '\"Reci ovako Zerubabelu, sinu Šealtielovu, namjesniku judejskom, i Jošui, sinu Josadakovu, velikom svećeniku, i ostalom narodu:');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 2, 3, '\'Ima li još koga među vama koji vidje ovaj Dom u njegovoj staroj slavi? A kakva ga sada vi vidite? Prema onome, nije li to k\'o ništa u vašim očima?');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 2, 4, 'Budi, dakle, junak, Zerubabele - riječ je Jahvina - budi junak, Jošua, sine Josadakov, veliki svećeniče! Budi junak, narode sve zemlje - riječ je Jahvina. Na posao! Jer, ja sam s vama! - riječ je Jahve nad Vojskama!');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 2, 5, 'Po obećanju što ga vama dadoh kad izađoste iz Egipta, duh moj posred vas ostaje. Ne bojte se!\'');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 2, 6, 'Jer ovako govori Jahve nad Vojskama: \'Zamalo, i ja ću potresti nebesa i zemlju, i more i kopno.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 2, 7, 'Potrest ću sve narode da dođe blago svih naroda, i slavom ću napunit ovaj Dom\' - kaže Jahve nad Vojskama.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 2, 8, '\'Moje je zlato, moje je srebro\' - riječ je Jahve nad Vojskama.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 2, 9, '\'Slava ovoga drugog Doma bit će veća nego prvoga\' - riječ je Jahve nad Vojskama. \'I na ovom ću mjestu dati mir\' - riječ je Jahve nad Vojskama.\"');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 2, 10, 'Dvadeset i četvrtoga dana devetoga mjeseca, druge godine kralja Darija, dođe riječ Jahvina preko proroka Hagaja:');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 2, 11, 'Ovako govori Jahve nad Vojskama. \"Pitaj svećenike što kaže Zakon i reci:');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 2, 12, '\'Kad bi tko u skutu svoje haljine nosio posvećeno meso, ili bi se skutom dotakao kruha, jela, vina, ulja ili kakve god hrane, bi li to postalo sveto?\'\" Svećenici odgovoriše: \"Ne!\"');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 2, 13, 'Hagaj dalje upita: \"Kad bi netko koji se onečistio dodirnuvši mrtvaca dotakao nešto od onoga, bi li to postalo nečisto?\" Svećenici odgovoriše: \"Bilo bi nečisto.\"');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 2, 14, 'Onda Hagaj ovako reče: \"Takav je i ovaj puk, takav je ovaj narod preda mnom - riječ je Jahvina - takvo je svako djelo ruku njihovih, i sve što ovdje prinose: sve je nečisto!\"');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 2, 15, '\"A sada, promislite u srcu, od današnjega dana unapredak: Prije negoli se poče stavljati kamen na kamen u Jahvinu Svetištu,');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 2, 16, 'kakvi ono bijaste? Dolažaste hrpi od dvadeset mjerica, a bješe ih samo deset! Dolažaste kaci da zahvatite pedeset mjerica, a bješe ih samo dvadeset!');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 2, 17, 'Udarao sam snijeću, medljikom i grÓadom svako djelo vaših ruku, ali nikoga nema k meni\" - riječ je Jahvina.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 2, 18, '\"Stoga dobro pripazite od današnjeg dana unapredak - od dvadeset i četvrtoga dana devetoga mjeseca, kad se stao graditi Hram Jahvin, pripazite dobro');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 2, 19, 'ima li još žita u žitnici? Ni vinova loza ni smokva, ni mogranj ni maslina nisu rađali! Al\' od ovog dana ja ću blagosloviti.\"');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 2, 20, 'Dvadeset i četvrtoga dana istoga mjeseca dođe riječ Jahvina Hagaju drugi put:');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 2, 21, '\"Reci ovako Zerubabelu, namjesniku judejskom: \'Ja ću potresti nebesa i zemlju!');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 2, 22, 'Oborit ću prijestolja kraljevstvima i uništit ću moć kraljevima naroda. Prevrnut ću bojna kola i one na njima, konji i konjanici njihovi bit će oboreni, past će od mača brata svojega.\'\"');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 2, 23, '\"Toga dana\" - riječ je Jahve nad Vojskama - \"uzet ću te, Zerubabele, sine Šealtielov, slugo moja\" - riječ je Jahvina - \"i stavit ću te kao pečatnjak, jer tebe izabrah\" - riječ je Jahve nad Vojskama.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (45, 1, 1, 'Osmoga mjeseca druge godine Darijeve dođe riječ Jahvina proroku Zahariji, sinu Berekjinu, sinu Idonovu.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (45, 1, 2, '\"Jahve se teško razgnjevio na oce vaše!');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (45, 1, 3, 'Zatim im reci: \'Ovako govori Jahve nad Vojskama: Vratite se meni, i ja ću se vratiti vama\' - riječ je Jahve nad Vojskama.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (45, 1, 4, '\'Ne budite poput svojih otaca koje su pozivali negdašnji proroci.\' Ovako govori Jahve nad Vojskama: \'Vratite se sa zlih putova svojih i od zlih djela. Ali oni nisu slušali ni pazili na mene\' - govori Jahve.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (45, 1, 5, 'Gdje su sad oci vaši? Zar će dovijeka živjeti proroci?');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (45, 1, 6, 'Ali moje riječi i odredbe, koje sam naložio slugama svojim prorocima, nisu li stigle vaše oce? Oni se obratiše i priznaše: \'Jahve nad Vojskama učinio je s nama kako bijaše namislio učiniti prema našim putovima i našim djelima.\'\"');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (45, 1, 7, 'Dvadeset i četvrtog dana, jedanaestoga mjeseca, a to je mjesec Šebat, druge godine Darijeve, dođe riječ Jahvina proroku Zahariji, sinu Berekjinu, sinu Idonovu.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (45, 1, 8, 'Imao sam noću viđenje. Gle, na riđanu čovjek jaše među mirtama koje imaju duboko korijenje, a iza njega konji riđi, smeđi i bijeli.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (45, 1, 9, 'Upitah: \"Koji su ovi, gospodaru?\" Anđeo koji je sa mnom govorio reče mi: \"Ja ću ti pokazati koji su.\"');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (45, 1, 10, 'Čovjek koji stajaše među mirtama odgovori: \"Ovo su oni koje je poslao Jahve da obilaze zemlju.\"');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (45, 1, 11, 'Oni se obratiše anđelu Jahvinu, koji stajaše među mirtama, i kazaše: \"Obišli smo zemlju, i gle: sva zemlja počiva i miruje.\"');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (45, 1, 12, 'Tada progovori anđeo Jahvin i reče: \"Jahve nad Vojskama, kada ćeš se već jednom smilovati Jeruzalemu i gradovima judejskim na koje se već sedamdeset godina ljuto srdiš?\"');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (45, 1, 13, 'A Jahve anđelu koji je govorio sa mnom odgovori utješnim riječima.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (45, 1, 14, 'I anđeo koji je govorio sa mnom reče mi: \"Objavi ovo: \'Ovako govori Jahve nad Vojskama: Ljubavlju ljubomornom gorim za Jeruzalem i za Sion,');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (45, 1, 15, 'a velikim gnjevom plamtim na ohole narode, jer kad se ono malo rasrdih, oni prijeđoše mjeru.\'');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (45, 1, 16, 'Zato ovako govori Jahve: \'Vraćam se Jeruzalemu s milosrđem; opet će u njemu sagraditi Dom moj\' - riječ je Jahve nad Vojskama - \'i opet će se u Jeruzalemu protezati uže mjeračko.\'');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (45, 1, 17, 'I ovo poruči: \'Ovako govori Jahve nad Vojskama: Moji će se gradovi opet prelijevati obiljem, i Jahve će utješiti Sion, izabrati Jeruzalem.\'\"');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (45, 2, 1, 'Podigoh oči i vidjeh. I gle: četiri roga.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (45, 2, 2, 'Upitah anđela koji je govorio sa mnom: \"Što je ovo?\" On mi odgovori: \"To su rogovi koji su raznijeli Judu, Izraela i Jeruzalem.\"');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (45, 2, 3, 'Onda mi Jahve pokaza četiri kovača.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (45, 2, 4, 'A ja upitah: \"Što su došli ovi raditi?\" On mi odgovori: \"Ono su rogovi koji su raznijeli Judu te se nitko više ne usuđuje dići glavu; a ovi su došli da ih zastraše i da slome rogove narodima koji podizahu rog na zemlju Judinu kako bi je raznijeli.\"');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (45, 2, 5, 'Podigoh oči i vidjeh. I gle: čovjek, a u ruci mu mjeračko uže.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (45, 2, 6, 'Upitah ga: \"Kamo ideš?\" Odgovori mi: \"Da izmjerim Jeruzalem i da vidim koliko je širok a koliko dug.\"');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (45, 2, 7, 'I gle, anđeo koji je govorio sa mnom stajaše nepomično, a drugi mu iziđe u susret');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (45, 2, 8, 'i reče mu: \"Trči, reci onome mladiću ovako: Jeruzalem će biti kao otvoren grad radi mnoštva ljudi i stoke koji će biti u njemu.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (45, 2, 9, 'A ja ću mu - riječ je Jahvina - biti ognjen zid unaokolo i Slava njegova sred njega.\"');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (45, 2, 10, '\"Hej! Hej! Bježite iz zemlje sjeverne\" - riječ je Jahvina - \"jer u sva četiri vjetra nebeska razasuo sam vas\" - riječ je Jahvina!');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (45, 2, 11, '\"Hej, Sione, koji živiš kod kćeri babilonske, spasi se!\"');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (45, 2, 12, 'Ovako govori Jahve nad Vojskama, čija me Slava izaslala k narodima koji su vas opljačkali: \"Tko vas dira, dira mi zjenicu oka.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (45, 2, 13, 'Gle, ruku dižem na njih da plijenom budu svojim robovima.\" Znat ćete tako da me posla Jahve nad Vojskama!');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (45, 2, 14, '\"Kliči i raduj se, kćeri sionska, jer evo, dolazim usred tebe prebivat\' - riječ je Jahvina.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (45, 2, 15, 'U onaj dan mnogi će narodi uz Jahvu prionuti i bit će narod moj, a ja ću prebivati usred tebe.\" Znat ćeš tako da me tebi posla Jahve nad Vojskama.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (45, 2, 16, 'I Judeja će biti baština Jahvina, njegov dio u Svetoj zemlji, i on će opet izabrati Jeruzalem.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (45, 2, 17, 'Tiho, ljudi svi, pred Jahvom, jer, evo, on ustaje iz svetoga Prebivališta svojega!');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (45, 3, 1, 'Potom mi pokaza Jošuu, velikog svećenika, koji stajaše pred anđelom Jahvinim, i Satana, koji mu stajaše zdesna da ga tuži.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (45, 3, 2, 'Anđeo Jahvin reče Satanu: \"Suzbio te Jahve, Satane! Suzbio te Jahve koji izabra Jeruzalem! Nije li on glavnja iz ognja izvučena?\"');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (45, 3, 3, 'A Jošua bijaše obučen u prljave haljine dok stajaše pred anđelom Jahvinim.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (45, 3, 4, 'Anđeo se obrati onima koji pred njim stajahu i reče im: \"Skinite s njega te prljave haljine!\" I reče mu: \"Evo, skidam s tebe tvoju krivicu i odijevam te u dragocjenu haljinu!\"');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (45, 3, 5, 'I nastavi: \"Stavite mu čist povez oko glave!\" Oni mu staviše čist povez oko glave i odjenuše ga u dragocjene haljine u nazočnosti anđelovoj.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (45, 3, 6, 'I anđeo Jahvin upozori Jošuu:');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (45, 3, 7, '\"Ovako govori Jahve nad Vojskama: \'Ako budeš mojim putovima hodio i mojih se pridržavao naredaba, ti ćeš biti upravitelj u Domu mojemu, čuvat ćeš moja predvorja i dat ću ti pristup među one koji ondje stoje.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (45, 3, 8, 'Poslušaj, dakle, Jošua, veliki svećeniče, ti i drugovi tvoji koji su oko tebe, jer vi ste ljudi znamenja! Evo, ja ću dovesti Izdanak, Slugu svojega, i uklonit ću opačinu ove zemlje u jedan dan.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (45, 3, 9, 'Jer evo kamena koji stavljam pred Jošuu: na tom je kamenu sedam očiju i u nj ću urezati natpis\' - riječ je Jahve nad Vojskama.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (45, 3, 10, '\'U dan onaj\' - riječ je Jahve nad Vojskama - \'pozivat ćete jedan drugoga pod lozu i pod smokvu.\'\"');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (45, 4, 1, 'Anđeo koji je govorio sa mnom vrati se tad i probudi me kao čovjeka koji se oda sna budi.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (45, 4, 2, '\"Što vidiš?\" - upita. Ja odgovorih: \"Vidim, evo, svijećnjak, sav od zlata, s posudom za ulje vrh njega; i sedam je žižaka na svijećnjaku, sa sedam lijevaka za sedam žižaka što su na njemu.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (45, 4, 3, 'Dvije su masline kraj njega, jedna njemu zdesna, druga slijeva.\"');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (45, 4, 4, 'Obratih se anđelu koji je govorio sa mnom i upitah ga: \"Što je to, gospodaru?\"');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (45, 4, 5, 'Anđeo koji je govorio sa mnom odgovori mi: \"Zar ne znaš što je to?\" Ja rekoh: \"Ne, gospodaru.\"');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (45, 4, 6, '[6a] On mi tad odgovori ovako: [6b]Evo riječi Jahvine Zerubabelu: \"Ne silom niti snagom, već duhom mojim!\" - riječ je Jahve nad Vojskama.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (45, 4, 7, 'Što si ti, goro velika? Pred Zreubabelom postaješ ravnica! On će izvući krunišni kamen uz poklike: \"Hvala! Hvala za njega!\"');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (45, 4, 8, 'Dođe mi potom riječ Jahvina:');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (45, 4, 9, 'Zerubabelove su ruke ovaj Dom utemeljile, njegove će ga ruke završiti. I vi ćete znati da me k vama poslao Jahve nad Vojskama.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (45, 4, 10, '[10a] Jer, tko je prezreo dan skromnih početaka? Radovat će se kad vide olovni visak u ruci Zerubabelovoj. [10b] \"Ovih sedam oči su Jahvine što strijeljaju po svoj zemlji.\"');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (45, 4, 11, 'Tad progovorih i zapitah ga: \"Što su one dvije masline desno i lijevo od svijećnjaka?\"');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (45, 4, 12, 'Progovorih opet i upitah ga: \"Što su one dvije maslinove grančice koje kroz dvije zlatne cijevi dolijevaju ulje?\"');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (45, 4, 13, 'On mi odgovori: \"Zar ne znaš što je to?\" Odvratih: \"Ne, gospodaru!\"');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (45, 4, 14, 'On reče: \"To su dva Pomazanika koji stoje pred Gospodarem sve zemlje.\"');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (45, 4, 15, '');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (45, 4, 16, '');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (45, 5, 1, 'Podigoh opet oči i vidjeh: leti svitak knjige.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (45, 5, 2, 'Anđeo me upita: \"Što vidiš?\" Odgovorih: \"Vidim svitak knjige gdje leti: dužina joj je dvadeset lakata, a širina deset.\"');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (45, 5, 3, 'On mi tad reče: \"To je prokletstvo koje će zahvatiti svu zemlju; odsad, svaki koji krade bit će po njem izgnan odavde i svaki koji krivo priseže bit će po njem odavde protjeran.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (45, 5, 4, 'Ja ću ga izvesti - riječ je Jahve nad Vojskama - da uđe u kuću lupežu i u kuću onome koji se krivo kune mojim imenom te da boravi usred njegove kuće i uništi je skupa s njenim drvljem i kamenjem.\"');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (45, 5, 5, 'Anđeo koji je govorio sa mnom iziđe i reče mi: \"Podigni oči i pogledaj što se to pojavljuje.\"');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (45, 5, 6, 'Ja ga upitah: \"Što je to?\" On reče: \"To se pojavljuje efa.\" I nastavi: \"To je opća pokvarenost na zemlji.\"');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (45, 5, 7, 'I gle, podiže se olovan poklopac i jedna žena sjedi usred efe.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (45, 5, 8, 'On reče: \"To je zloća.\" I gurnu je u efu i baci joj na otvor olovni poklopac.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (45, 5, 9, 'Podigavši oči, vidjeh: dvije žene izlaze s vjetrom u krilima, a krila im bijahu kao krila rode; one podigoše efu između zemlje i neba.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (45, 5, 10, 'Upitah tad anđela koji je govorio sa mnom: \"Kamo odnose efu?\"');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (45, 5, 11, 'On mi odgovori: \"Da joj sagrade hram u zemlji šinearskoj i da joj pripreme postolje na koje će je postaviti.\"');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (45, 6, 1, 'I podigoh oči i vidjeh: gle, četvera bojna kola izlaze između dviju gora; a gore bijahu od mjedi.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (45, 6, 2, 'U prvim kolima bijahu riđi konji; u drugim kolima crni konji;');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (45, 6, 3, 'u trećim kolima bijeli konji, a u četvrtim kolima konji šareni.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (45, 6, 4, 'Obratih se anđelu koji je govorio sa mnom i upitah ga: \"Što je to, gospodaru?\"');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (45, 6, 5, 'Anđeo mi odgovori ovako: \"Ti kreću u četiri vjetra nebeska pošto su stajali pred Gospodarem sve zemlje.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (45, 6, 6, 'Riđani kreću u zemlju istočnu; vranci u zemlju sjevernu; bijelci kreću u zemlju zapadnu, a šarci kreću u zemlju južnu.\"');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (45, 6, 7, 'Krepko oni stupaju, nestrpljivi da obiđu zemlju. On im reče: \"Idite, obiđite zemlju!\" I oni krenuše obilaziti zemljom.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (45, 6, 8, 'On me zovnu i reče mi: \"Vidi, oni koji su krenuli u sjevernu zemlju umirit će gnjev moj u zemlji sjevernoj.\"');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (45, 6, 9, 'I dođe mi riječ Jahvina:');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (45, 6, 10, '\"Uzmi prinose od izgnanika - od Heldaja, Tobije i Jedaje - i pođi danas i uđi u dom Jošije, sina Sefanijina, koji je došao iz Babilona.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (45, 6, 11, 'Uzmi srebra i zlata, načini krunu i stavi na glavu Jošui, sinu Josadakovu, velikom svećeniku.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (45, 6, 12, 'I reci mu: \'Ovako govori Jahve nad Vojskama: Evo čovjeka komu je ime Izdanak; ispod njega će proklijati i on će sazdati Svetište Jahvino.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (45, 6, 13, 'On će sazdati Svetište Jahvino i proslaviti se. On će sjediti i vladati na prijestolju. A do njega će na prijestolju biti svećenik. Sklad savršen bit će među njima.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (45, 6, 14, 'A kruna neka ostane u Jahvinu Svetištu za spomen Heldaju, Tobiji, Jedaji i Jošiji, sinu Sefanijinu.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (45, 6, 15, 'I oni koji su daleko doći će i sazdat će Svetište Jahvino. Znat ćete tako da me Jahve nad Vojskama k vama poslao.\' To će se zbiti ako zaista poslušate glas Jahve, Boga svojega.\"');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (45, 7, 1, 'Četvrte godine kralja Darija, četvrtoga dana devetoga mjeseca, Kisleva, dođe riječ Jahvina Zahariji.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (45, 7, 2, 'Betel je naime poslao Sar-Esera i Regem-Meleka s njihovim ljudima da mole lice Jahvino');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (45, 7, 3, 'i da pitaju svećenike u Domu Jahve nad Vojskama i proroke: \"Hoćemo li plakati petoga mjeseca i postiti, kao što činimo već tolike godine?\"');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (45, 7, 4, 'Tada mi dođe riječ Jahve nad Vojskama: \"Reci svemu puku zemlje i svećenicima:');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (45, 7, 5, '\'Kad postite i naričete petoga i sedmoga mjeseca već sedamdeset godina, zar meni postite?');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (45, 7, 6, 'A kad jedete i pijete, zar sebi ne jedete i pijete?');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (45, 7, 7, 'Nisu li to propisi koje je Jahve objavio preko negdašnjih proroka kada Jeruzalem bijaše naseljen i miran kao i gradovi oko njega i kada bijaše napučen Negeb i Šefela?\'\"');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (45, 7, 8, 'Riječ Jahvina dođe Zahariji:');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (45, 7, 9, '\"Ovako govori Jahve nad Vojskama: \'Sudite istinito i budite dobrostivi i milosrdni jedni drugima.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (45, 7, 10, 'Ne tlačite udovu ni sirotu, ni došljaka ni uboga, i ne snujte u srcu pakosti jedan prema drugom.\'');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (45, 7, 11, 'Ali oni ne htjedoše poslušati, već prkosno okrenuše leđa; zatisnuše uši da ne bi čuli;');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (45, 7, 12, 'otvrdnuše srcem kao kremen, da ne bi čuli Zakon i riječi koje im je slao Jahve nad Vojskama, svojim duhom, preko drevnih proroka. I Jahve nad Vojskama silno se tad razgnjevi.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (45, 7, 13, 'I zato, kao što je on zvao a oni ga ne slušaše, tako su sad oni zvali a ja ih nisam slušao - riječ je Jahve nad Vojskama.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (45, 7, 14, 'I razmeo sam ih među sve narode kojih ne poznavahu, a zemlja iza njih bi opustošena, te nitko nije njome prolazio niti se vraćao. Tako su zemlju blagostanja obratili u pustoš!\"');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (45, 8, 1, 'I dođe mi riječ Jahvina:');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (45, 8, 2, '\"Ovako govori Jahve nad Vojskama: \'Ljubavlju ljubomornom za Sion izgaram i gnjevom velikim plamtim za nj! Vraćam se u Sion, prebivati hoću sred Jeruzalema.\'');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (45, 8, 3, 'Ovako govori Jahve nad Vojskama: \'Jeruzalem će se zvati Gradom vjernosti i Gorom Jahve nad Vojskama, Gorom svetosti.\'');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (45, 8, 4, 'Ovako govori Jahve nad Vojskama: \'Starci i starice opet će posjedati po trgovima jeruzalemskim, svatko sa štapom u ruci zbog starosti prevelike.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (45, 8, 5, 'A gradski će se trgovi ispuniti dječacima i djevojčicama koji će se igrati na njegovim trgovima.\'');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (45, 8, 6, 'Ovako govori Jahve nad Vojskama: \'Ako to bude čudo u očima Ostatka u dane one, zar će to biti čudo i u mojim očima\' - riječ je Jahve nad Vojskama.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (45, 8, 7, 'Ovako govori Jahve nad Vojskama: \'Evo spasit ću svoj narod iz zemlje istočne i iz zemlje sunčanog zapada.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (45, 8, 8, 'Ja ću ih dovesti da se nastane usred Jeruzalema. I bit će mi narod a ja ću im biti Bog u vjernosti i pravdi.\'');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (45, 8, 9, 'Ovako Govori Jahve nad Vojskama: \'Neka ojačaju ruke vama koji ovih dana slušate riječi ove iz usta proroka koji prorokuje od dana kada bjehu položeni temelji Domu Jahve nad Vojskama da bi se opet sagradilo Svetište.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (45, 8, 10, 'Jer, prije ovih dana ne bijaše nadnice za čovjeka niti nadnice za živinče; niti bijaše mira od neprijatelja onome koji je izlazio ni onome koji je dolazio; puštao sam ljude jedne protiv drugih.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (45, 8, 11, 'Ali sada, neću biti prema Ostatku ovog naroda kao minulih dana - riječ je Jahve nad Vojskama -');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (45, 8, 12, 'nego ću posijati mir: loza će roditi grožđem, zemlja će davati usjeve, a nebo će davati rosu svoju. Sve ću to dati Ostatku ovoga naroda.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (45, 8, 13, 'I kao što bijaste prokletstvo među narodima, dome Judin i dome Izraelov, tako ću vas spasiti da budete blagoslovom! Ne bojte se, nek\' vam jake budu ruke!\'');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (45, 8, 14, 'Jer ovako govori Jahve nad Vojskama: \'Kao što bijah namislio unesrećiti vas kada su me razgnjevili oci vaši - govori Jahve nad Vojskama - i nisam se pokajao,');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (45, 8, 15, 'tako, promijenivši naum, u ove dane mislim usrećiti Jeruzalem i dom Judin. Ne bojte se!');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (45, 8, 16, 'A ovo vam je činiti: Govorite istinu jedan drugom; sudite istinito i miroljubivo na vratima gradskim!');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (45, 8, 17, 'Ne snujte jedan drugome zlo u srcu; ne ljubite lažnu kletvu. Jer sve to ja mrzim\' - riječ je Jahvina!\"');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (45, 8, 18, 'Dođe mi riječ Jahve nad Vojskama:');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (45, 8, 19, '\"Ovako govori Jahve nad Vojskama: Post četvrtoga, post petoga, post sedmoga i post desetoga mjeseca postat će za Dom Jahvin radost, veselje i veseli blagdani. Ali ljubite istinu i mir!\"');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (45, 8, 20, '\"Ovako govori Jahve nad Vojskama: Još će dolaziti narodi i stanovnici mnogih gradova.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (45, 8, 21, 'Stanovnici jednoga grada ići će u drugi govoreći: \'Hajde da idemo moliti lice Jahvino i tražiti Jahvu nad Vojskama!\' Ići ću i ja!');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (45, 8, 22, 'I doći će mnogi puk i moćni će narodi tražiti Jahvu nad Vojskama u Jeruzalemu i moliti lice Jahvino.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (45, 8, 23, 'Ovako govori Jahve nad Vojskama! U one će dane deset ljudi od naroda svih jezika hvatati jednog Židova za skut govoreći: \'Idemo s vama, jer čusmo da je s vama Bog.\'\"');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (45, 9, 1, 'Proroštvo. Riječ Jahvina. Jahve prolazi zemljom Hadraka, Damask mu je počivalište; jer Jahvini su gradovi Arama i sva plemena Izraela.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (45, 9, 2, 'Hamat također, koji s njim graniči,');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (45, 9, 3, 'i Tir i Sidon, tako mudar. Tir podiže tvrde bedeme, zgrnu srebra kao prašine i zlata kao blata s ulica.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (45, 9, 4, 'Al\' evo, Gospod će ga osvojiti, survati u more moć njegovu, a njega će progutati oganj.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (45, 9, 5, 'Vidjet će to Aškelon i prestrašiti se, a Gaza sva će uzdrhtati, i Ekron, jer ga nada prevari: nestat će kralja iz Gaze, Aškelon će pust ostati,');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (45, 9, 6, 'u Ašdodu stanovat će kopilad! Zatrt ću ponos Filistejaca,');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (45, 9, 7, 'uklonit ću im krv iz usta i gnusobu iz zuba. I oni će pripasti Bogu našem i bit će kao jedna obitelj u Judeji, a Ekron će biti kao Jebusejac.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (45, 9, 8, 'Uz Dom svoj utaborit ću se kao straža, protiv onih koji odlaze i dolaze; tlačitelj neće više ovud prolaziti, jer njegovu sam uvidio bijedu.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (45, 9, 9, 'Klikni iz sveg grla, Kćeri sionska! Viči od radosti, Kćeri jeruzalemska! Tvoj kralj se evo tebi vraća: pravičan je i pobjedonosan, ponizan jaše na magarcu, na magaretu, mladetu magaričinu.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (45, 9, 10, 'On će istrijebit\' kola iz Efrajima i konje iz Jeruzalema; on će istrijebit\' luk ubojni. On će navijestit\' mir narodima; vlast će mu se proširit\' od mora do mora i od Rijeke do rubova zemlje.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (45, 9, 11, 'A i tebi, zbog krvi tvoga Saveza, vratit ću sužnje tvoje iz jama bezvodnih.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (45, 9, 12, 'Vratite se u Tvrđavu, izgnanici puni nade, još danas - ja navješćujem - dvostruko ću ti uzvratiti.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (45, 9, 13, 'Jer, Judu sam kao luk napeo, a Efrajimom luk naoružao: tvoje ću, o Sione, zavitlat\' sinove - protiv sinova tvojih, o Javane - i učinit ću te kao mač junaka.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (45, 9, 14, 'Nad njima tad će se pojaviti Jahve i kao munja letjet će mu strijela. Jahve Gospod u rog će zatrubit\', hodit će na južnim vihorima.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (45, 9, 15, 'Jahve nad Vojskama zakrilit će ih i oni će gaziti nogama kamenje praćaka, pit će krv kao da je vino, napojit\' se kao škropilo, kao uglovi na žrtveniku.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (45, 9, 16, 'Jahve Bog njihov spasit će ih u dan onaj; kao stado on će pasti narod svoj; kao drago kamenje krune oni će blistat\' u zemlji njegovoj.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (45, 9, 17, 'Ah, kako li će sretan, kako lijep biti! Od žita će rasti mladići, a od slatkog vina djevice.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (45, 10, 1, 'Tražite od Jahve dažda u vrijeme proljetno! Jahve stvara munje i daje kišu; čovjeku kruh daje, a stoci travu.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (45, 10, 2, 'Lažno bajaju kumiri, prijevaru vide gatari, obmanu govore snovi, varljivu utjehu daju, zato kao stado blude ljudi, lutaju jer nemaju pastira.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (45, 10, 3, 'Moj je gnjev planuo na pastire, i ja ću kaznom pohodit jarce. Da, Jahve nad Vojskama pohodit će stado svoje, dom Judin. I učinit će da budu k\'o gizdav konj u boju:');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (45, 10, 4, 'od njega će poteći kamen zaglavni, klin šatorski, od njega ubojit luk, od njega sve vođe.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (45, 10, 5, 'Bit će zajedno kao junaci što u boju gaze kao po blatu uličnom; vojevat će, jer Jahve je s njima, i osramotit će one koji konje jašu.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (45, 10, 6, '\"Ojačat ću dom Judin, spasiti dom Josipov. Opet ću ih naseliti, žao mi ih, i bit će kao da ih nisam odbacio, jer ja sam Jahve, Bog njihov - uslišat ću ih.\"');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (45, 10, 7, 'Efrajimci bit će kao junaci i radostit će im se srce kao od vina: vidjet će sinove svoje i veseliti se, u Jahvi će klicati srce njihovo.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (45, 10, 8, '\"Zazviždat ću im i sabrati ih, jer ja sam ih izbavio, bit će opet brojni kao što bjehu.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (45, 10, 9, 'Rasijao sam ih među narode, ali će se oni u zemljama dalekim spomenuti mene, poučit će svoje sinove, i oni će se vratiti.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (45, 10, 10, 'Vratit ću ih iz zemlje egipatske, sabrat ću ih iz Asirije i dovest ih u zemlju gileadsku i na Libanon, i neće biti dosta mjesta za njih.\"');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (45, 10, 11, 'Prijeći će more egipatsko, jer on će udariti valove morske, sve dubine Nila presahnut će. Bit će oboren ponos Asirije, oduzeto žezlo Egiptu.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (45, 10, 12, 'U Jahvi će biti snaga njihova, njegovim će se oni proslavit imenom - riječ je Jahvina.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (45, 11, 1, 'Otvori vrata, Libanone, nek\' ti oganj sažeže cedrove!');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (45, 11, 2, 'Kukaj, čempresu, jer pade cedar, jer su mogućnici upropašteni! Kukajte, hrastovi bašanski, jer posječena je šuma najgušća.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (45, 11, 3, 'Čuj jauk pastira, opustošen je sjaj njihov! Čuj riku lavića, opustošen je ponos jordanski!');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (45, 11, 4, 'Ovako mi reče Jahve:');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (45, 11, 5, '\"Pasi ovce klanice! Kupci ih njihovi kolju nekažnjeno, a koji ih prodaju, govore: \'Blagoslovljen bio Jahve, obogatio sam se!\' i pastiri ih njihovi ne štede.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (45, 11, 6, 'Ni ja više neću štedjeti žitelja zemlje - riječ je Jahve nad Vojskama - nego: predajem, evo, svakoga u ruke njegova bližnjega i u ruke kralja njegova; i oni će pustošiti zemlju, a ja neću izbavljati iz ruku njihovih.\"');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (45, 11, 7, 'Stadoh pasti ovce klanice za trgovce ovcama te uzeh dva štapa: jedan nazvah Naklonost, drugi Sveza. Tako sam pasao stado.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (45, 11, 8, 'I u jednom mjesecu odbacih tri pastira. Ali mi i ovce dojadiše, omrznuh im.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (45, 11, 9, 'Tad rekoh: \"Neću vas više pasti! Koja mora uginuti, nek\' ugine! Koja mora nestati, nek\' nestane! A koje ostanu, neka jedna drugoj meso prožderu!\"');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (45, 11, 10, 'Tad uzeh svoj štap Naklonost i slomih ga da raskinem Savez svoj što ga bijah sklopio sa svim narodima.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (45, 11, 11, 'I on se raskinu onog dana, i trgovci ovcama koji su to gledali doznaše da je to bila riječ Jahvina.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (45, 11, 12, 'Rekoh im tad: \"Ako vam je to dobro, dajte mi plaću; ako nije, nemojte.\" Oni mi odmjeriše plaću: trideset srebrnika.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (45, 11, 13, 'A Jahve mi reče: \"Baci u riznicu tu lijepu cijenu kojom su me procijenili!\" Ja uzeh trideset srebrnika i bacih u riznicu u Domu Jahvinu.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (45, 11, 14, 'Onda slomih i svoj drugi štap, Svezu - da raskinem bratstvo između Jude i Izraela.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (45, 11, 15, 'I reče mi Jahve: \"Uzmi još opremu bezumna pastira,');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (45, 11, 16, 'jer, evo, podići ću jednoga bezumnog pastira u ovoj zemlji: za izgubljene on se neće brinuti, zalutale neće tražiti, ranjene neće vidati, iscrpljene neće nositi, nego će jesti meso od pretilih i papke im otkidati.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (45, 11, 17, 'Teško pastiru opakom koji stado ostavlja! Neka mu mač stigne ruku i desno oko! Nek\' mu desnica sasvim usahne, oko desno sasvim potamni!\"');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (45, 12, 1, 'Proroštvo. Besjeda Jahvina o Izraelu. Govori Jahve koji razape nebesa, utemelji zemlju i stvori dah čovjeku u grudima:');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (45, 12, 2, '\"Evo, učinit ću Jeruzalem čašom opojnom svim narodima uokolo - za opsade Jeruzalema.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (45, 12, 3, 'U onaj dan učinit ću Jeruzalem teškim kamenom svim narodima: svi koji ga budu dizali teško će se izraniti, a skupit će se na nj svi narodi zemlje.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (45, 12, 4, 'U onaj dan - riječ je Jahvina - udarit ću sve konje strahom, a njine jahače mahnitošću. Ali nad domom Judinim otvorit ću oči, a sljepilom ću udariti sve konje narodÄa.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (45, 12, 5, 'Tada će u srcu reći plemena Judina: \'Snaga je Jeruzalemaca u Jahvi nad Vojskama, Bogu njihovu!\'');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (45, 12, 6, 'U onaj dan učinit ću da plemena Judina budu kao žeravnica užarena na drvlju, kao baklja upaljena na snoplju: i proždirat će zdesna i slijeva sve narode uokolo. A Jeruzalem će i dalje stajati na svome mjestu.\"');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (45, 12, 7, 'Jahve će najprije spasiti Judine šatore da se ponos doma Davidova i ponos Jeruzalemaca ne izdigne iznad Jude.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (45, 12, 8, 'U onaj dan Jahve će zakriliti Jeruzalemce: najsustaliji među njima bit će u onaj dan kao David, a dom Davidov bit će kao božanstvo, kao Anđeo Jahvin pred njima.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (45, 12, 9, '\"U onaj dan pregnut ću da uništim sve narode koji dođu na Jeruzalem.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (45, 12, 10, 'A na dom Davidov i na Jeruzalemce izlit ću duh milosni i molitveni. I gledat će na onoga koga su proboli; naricat će nad njim kao nad jedincem, gorko ga oplakivati kao prvenca.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (45, 12, 11, 'U onaj dan plač velik će nastati u Jeruzalemu, poput plača hadad-rimonskog u ravnici megidonskoj.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (45, 12, 12, 'I plakat će zemlja, svaka porodica napose, i žene njihove napose; porodica doma Davidova napose, i žene njihove napose; porodica doma Natanova napose, i žene njihove napose;');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (45, 12, 13, 'porodica doma Levijeva napose, i žene njihove napose; porodica Šimejeva napose, i žene njihove napose;');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (45, 12, 14, 'i sve ostale porodice, svaka porodica za sebe, i žene njihove napose.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (45, 13, 1, 'U onaj dan otvorit će se izvor domu Davidovu i Jeruzalemcima da se operu od grijeha i nečistoće.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (45, 13, 2, 'U onaj dan - riječ je Jahve nad Vojskama - iskorijenit ću iz zemlje imena kumirÄa da se više ne spominju; uklonit ću iz zemlje i proroke i duh nečistoće.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (45, 13, 3, 'Ako netko još bude prorokovao, otac i mati koji su ga rodili reći će mu: \'Nećeš više živjeti, jer laž govoriš u ime Jahvino!\' Otac i mati koji su ga rodili probost će ga kada bude prorokovao.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (45, 13, 4, 'U onaj dan svaki će se prorok stidjeti svoga viđenja; neće se više ogrtati plaštem od kostrijeti da bi lagali,');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (45, 13, 5, 'nego će govoriti: \'Nisam ja prorok; ja sam ratar, zemlja je moje dobro od mladosti!\'');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (45, 13, 6, 'Ako li ga tko upita: \'Kakve su ti to rane po tijelu?\' on će odgovoriti: \'Izranjen sam kod prijateljÄa.\'');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (45, 13, 7, 'Probudi se, maču, protiv mog pastira, protiv čovjeka, moga srodnika - riječ je Jahve nad Vojskama. Udari pastira, i ovce će se razbjeći! Okrenut ću ruku protiv slabića,');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (45, 13, 8, 'i u svoj će zemlji - riječ je Jahvina - dvije trećine biti istrijebljene, a trećina ostavljena.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (45, 13, 9, 'Tu ću trećinu kroz oganj provesti, pročistit ću ih kao što se pročišćuje srebro, iskušat\' ih kao što se srebro iskušava. I on će zazivati ime moje, a ja ću mu se odazvati; i reći ću: \'Moj je to narod!\' a on će reći: \'Jahve je Bog moj!\'\"');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (45, 14, 1, 'Gle, dolazi dan Jahvin kada će se podijeliti plijen usred tebe.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (45, 14, 2, 'I sabrat ću sve narode u Jeruzalem u borbu. I zaposjest će grad, opljačkati kuće i silovati žene. Polovina će grada otići u izgnanstvo, ali Ostatak neće biti istrijebljen iz grada.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (45, 14, 3, 'Tada će Jahve izaći i boriti se protiv tih naroda kako on zna ratovati u dan ratni.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (45, 14, 4, 'Noge će mu, u dan onaj, stajati na Gori maslinskoj koja je nasuprot Jeruzalemu na istoku. I raskolit će se Gora maslinska po srijedi, između istoka i zapada, u golemu dolinu: jedna će se polovina pomaknuti na sjever, druga na jug.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (45, 14, 5, 'Dolina Gore moje bit će ispunjena od Goe pa do Jasola i bit će zakrčena kao što je bila zakrčena poslije potresa u dane Uzije, kralja judejskog. Tada će doći Jahve, Bog tvoj, i svi sveci s njim.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (45, 14, 6, 'U dan onaj neće više biti ni studeni ni leda.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (45, 14, 7, 'Bit će to dan čudesan - znade ga Jahve - ni dan ni noć; i u vrijeme večeribit će svjetlo.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (45, 14, 8, 'U onaj dan žive će vode poteći iz Jeruzalema, pola k moru istočnom, pola kmoru zapadnom. Bit će tako ljeti i zimi.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (45, 14, 9, 'I Jahve će biti kralj nad svom zemljom.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (45, 14, 10, 'Sva će se zemlja pretvoriti u ravnicu, od Gebe do Rimona negepskog. A Jeruzalem će se uzvisiti na svom mjestu; i bit će nastanjen - od Vrata Benjaminovih do Prvih vrata, to jest do Vrata ugaonih, i od Kule Hananeelove do Kraljeva tijeska.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (45, 14, 11, 'Opet će se stanovati u njemu, i više neće biti prokletstva; Jeruzalem će živjeti u miru.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (45, 14, 12, 'A evo kojom će ranom Jahve udariti sve narode koji budu zavojštili na Jeruzalem: meso će im se raspadati dok budu na nogama; oči će im trunuti u dupljama, jezik gnjiti u ustima.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (45, 14, 13, 'U dan onaj nastat će među njima silan metež od Jahve: jedan će drugoga za ruku hvatati, i ruka će se jednoga dizati na drugoga.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (45, 14, 14, 'I Juda će se boriti u Jeruzalemu. Tu će se sakupiti bogatstva svih okolnih naroda: zlato, srebro, odjeća u velikoj množini.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (45, 14, 15, 'A slična će rana pasti na konje, mazge, deve i magarce, i na svu stoku koja se nađe u tome taboru.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (45, 14, 16, 'Tko preživi od svih naroda koji dođu na Jeruzalem, uzlazit će godimice da se pokloni pred Kraljem, Jahvom nad Vojskama, i da slave Blagdan sjenica.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (45, 14, 17, 'Ako koje pleme zemlje ne uzađe u Jeruzalem da se pokloni pred Kraljem, Jahvom nad Vojskama, neće biti kiše za njega.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (45, 14, 18, 'Ako li pleme egipatsko ne uzađe i ne dođe, stići će ga isti udarac kojim će Jahve udariti narode koji ne bi uzašli svetkovati Blagdan sjenica.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (45, 14, 19, 'Takva će biti kazna Egiptu i svim narodima koji ne budu uzašli da svetkuju Blagdan sjenica.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (45, 14, 20, 'U onaj dan stajat će na konjskim praporcima \'Jahvi posvećen\'; a u Domu Jahvinu bit će lonci kao žrtvene čaše pred žrtvenikom;');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (45, 14, 21, 'i svaki će lonac u Jeruzalemu i u Judeji biti posvećen Jahvi nad Vojskama - svi koji budu htjeli žrtvovati uzimat će ih i kuhati u njima. I u dan onaj neće više biti trgovaca u Domu Jahve nad Vojskama.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (46, 1, 1, 'Proroštvo. Riječ Gospodnja Izraelu po Malahiji.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (46, 1, 2, 'Ljubio sam vas - govori Jahve, a vi pitate: \"Po čemu si nas ljubio?\" Ne bijaše li Ezav brat Jakovljev? - riječ je Jahvina -');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (46, 1, 3, 'ali Jakova sam zavolio, a Ezav mi omrznu: gradove mu u pustoš pretvorih, a baštinu njegovu dadoh pustinjskim šakalima.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (46, 1, 4, 'Jer, rekne li Edom: Bili smo smrvljeni, ali ćemo opet podići ruševine!\" ovako kaže Jahve nad Vojskama: Neka grade oni, a ja ću razgraditi! Zvat će ih zemljom bezbožničkom i narodom na koji se Jahve srdi dovijeka!');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (46, 1, 5, 'Vaše će oči vidjeti, i reći ćete: \"Velik je Jahve preko granica zemlje izraelske.\"');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (46, 1, 6, 'Sin časti oca, a sluga gospodara. Ali, ako sam ja otac, gdje je čast moja? Ako sam gospodar, gdje je strah od mene? To govori Jahve nad Vojskama vama, svećenici, koji moje ime prezirete, a pitate: \"Čime smo prezreli ime tvoje?\"');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (46, 1, 7, 'Oskvrnjen kruh na mome prinosite žrtveniku i još pitate: \"Čime te oskvrnismo?\" Time što kažete \"Stol je Jahvin stvar nevažna!\"');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (46, 1, 8, 'A kada za žrtvu slijepu stoku prinosite, zar to nije zlo? I kad prinosite hromo i bolesno, zar to nije zlo? Donesi takvo što svome namjesniku, hoće li biti zadovoljan i dobro te primiti? - govori Jahve nad Vojskama.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (46, 1, 9, 'Sada umilostivite lice Božje da nam se smiluje. To donose ruke vaše, hoće li vas dobro primiti? - govori Jahve nad Vojskama.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (46, 1, 10, 'O kada bi tko od vas zatvorio vrata da mi zaludu ne palite ognja na žrtveniku! Niste mi mili - govori Jahve nad Vojskama - i ne primam žrtve iz ruke vaše.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (46, 1, 11, 'Jer od istoka do zapada veliko je ime moje među narodima, i na svakom mjestu prinosi se kad i žrtva čista Imenu mojemu, jer veliko je Ime moje među narodima - govori Jahve nad Vojskama.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (46, 1, 12, 'Ali vi ga skvrnite kada govorite: \"Stol je Gospodnji okaljan i hrana na njemu ni za što nije!\"');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (46, 1, 13, 'Kažete još: \"Gle, šteta truda!\" i prezirete ga - govori Jahve nad Vojskama. Kada dovodite stoku otetu, hromu i bolesnu, te je prinosite kao dar žrtveni, zar da to iz vaše ruke milostivo primim? - govori Jahve nad Vojskama.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (46, 1, 14, 'Proklet bio varalica koji u stadu ima ovna što mi ga je zavjetovao, a žrtvuje mi ovcu jalovicu. Jer ja sam velik kralj - govori Jahve nad Vojskama - i strašno je Ime moje među narodima.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (46, 2, 1, 'A sad vas opominjem, svećenici!');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (46, 2, 2, 'Ako ne budete poslušali, ako ne budete k srcu uzeli da proslavite Ime moje - govori Jahve nad Vojskama - kletvu ću na vas svaliti i proklet ću vaš blagoslov. I već ga prokleh jer to niste k srcu uzeli.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (46, 2, 3, 'I slomit ću vam ruku, bacit ću vam u lice izmetine, izmetine vaših svetkovina, i s njima ću vas splaviti.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (46, 2, 4, 'Po tom ćete znati: to je bila moja opomena da ostane Savez moj s Levijem - govori Jahve nad Vojskama.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (46, 2, 5, 'A moj Savez s njim, to bijaše život i mir - ja sam mu ih dao: bijaše to strah - i on me se bojao, Imena se moga plašio.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (46, 2, 6, 'Zakon istine bijaše u njegovim ustima i pakost mu ne kaljaše usana; u miru i pravičnosti hodio je sa mnom i mnoge je od grijeha odvratio.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (46, 2, 7, 'Da, usne svećenikove treba da čuvaju znanje, a iz njegovih usta treba tražiti Zakon: ta on je glasnik Jahve nad Vojskama.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (46, 2, 8, 'Ali vi ste s puta zašli, učinili ste da se mnogi o Zakon spotiču, raskinuli ste Savez Levijev - govori Jahve nad Vojskama.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (46, 2, 9, 'Zato učinih da vas preziru i ponizuju svi narodi jer se putova mojih vi držali niste, nego ste bili pristrani primjenjujuć Zakon.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (46, 2, 10, 'Nemamo li svi jednog Oca? Nije li nas jedan Bog stvorio? Zašto smo onda jedan drugome nevjerni te skvrnimo Savez svojih otaca?');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (46, 2, 11, 'Iznevjerio se Juda: učinili su sramotu u Izraelu i Jeruzalemu, jer Juda je oskvrnuo Svetinju, Jahvi dragu, i ženi se kćerju tuđega božanstva.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (46, 2, 12, 'Svakog tko tako učini, ma tko bio on, nek iskorijeni Jahve iz šatora Jakovljevih i izmeđ onih koji prinose žrtvu Jahvi nad Vojskama!');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (46, 2, 13, 'I ovo još vi činite: zalijevate suzama Jahvin žrtvenik tužeći i ridajući, jer on više neće da se žr tvi prikloni, iz ruke mu vaše ona nije ugodna.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (46, 2, 14, 'I vi pitate: \"Zašto?\" Zato što je Jahve bio svjedok između tebe i žene mladosti tvoje kojoj si nevjeran premda ti drugarica bijaše i žena tvoga saveza.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (46, 2, 15, 'Nije li On načinio jedno jedino biće dahom životnim obdareno? A što to jedino biće traži? Božanski naraštaj! Poštuj dakle život svoj i ne budi nevjeran ženi svoje mladosti.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (46, 2, 16, 'Jer ja mrzim otpuštanje žena - govori Jahve, Bog Izraelov - i onog koji nevjerom haljine svoje kalja - govori Jahve nad Vojskama! Poštujte dakle život svoj, ne budite nevjerni!');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (46, 2, 17, 'Dosađujete Jahvi svojim riječima, a pitate: \"U čemu mu dosađujemo?\" Time što govorite: \"Svi koji zlo čine dobro su viđeni u očima Jahvinim i takvi su mu mili!\" ili: \"Gdje je Bog pravde?\"');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (46, 3, 1, 'Evo šaljem glasnika da put preda mnom pripravi. I doći će iznenada u Hram svoj Gospod koga vi tražite i anđeo Saveza koga žudite. Evo ga, dolazi već - govori Jahve nad Vojskama.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (46, 3, 2, 'Ali tko će podnijeti dan njegova dolaska i tko će opstati kad se on pojavi? Jer on je kao oganj ljevačev i kao lužina bjeliočeva.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (46, 3, 3, 'I zasjest će kao onaj što topi srebro i pročišćava. Očistit će sinove Levijeve i pročistit će ih kao zlato i srebro, da prinose Jahvi žrtvu u pravednosti.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (46, 3, 4, 'Tad će biti draga Jahvi žrtva Judina i jeruzalemska kao u drevne dane i kao prvih godina.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (46, 3, 5, 'Doći ću k vama na sud i bit ću spreman svjedok protiv vračeva i preljubnika, protiv onih koji se lažno kunu, protiv onih koji zakidaju plaću radniku, udovici i siroti, protiv onih koji gaze pravo stranaca i mene se ne boje - govori Jahve nad Vojskama.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (46, 3, 6, 'Jer ja, Jahve, ne mijenjam se, a vi se, sinovi Jakovljevi, mijenjate bez prestanka!');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (46, 3, 7, 'Od vremena svojih otaca odstupate od mojih uredaba i ne čuvate ih. Vratite se meni, a ja ću se vratiti vama - govori Jahve nad Vojskama. Pitate: \"Kako da se vratimo?\"');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (46, 3, 8, 'Smije li čovjek prikraćivati Boga? A vi mene prikraćujete. I pitate: \"U čemu te prikratismo?\" U desetini i u prinosu.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (46, 3, 9, 'Udareni ste prokletstvom jer me prikraćujete vi, sav narod!');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (46, 3, 10, 'Donesite čitavu desetinu u riznicu da u mojoj kući bude hrane. Tada me iskušajte - govori Jahve nad Vojskama - neću li vam otvoriti ustave nebeske i neću li izliti na vas punom mjerom blagoslov,');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (46, 3, 11, 'neću li zbog vas zaprijetit skakavcu da vam više ne kvari usjeva i da vam ne bude nerodna loza u polju - govori Jahve nad Vojskama.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (46, 3, 12, 'Svi će vas narodi tad držati sretnima, jer ćete biti zemlja blaženstva - govori Jahve nad Vojskama.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (46, 3, 13, 'Teške su besjede vaše protiv mene - govori Jahve.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (46, 3, 14, 'Vi ipak pitate: \"Što smo između sebe govorili protiv tebe?\" Govorili ste: \"Zaludu je Bogu služiti i kakva je korist što njegove čuvamo propise i žalosni hodimo pred Jahvom nad Vojskama.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (46, 3, 15, 'Odsad ćemo sretnim zvati oholice: napreduju oni koji zlo čine, i premda Boga iskušavaju, izvuku se!\"');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (46, 3, 16, 'Ali kad se razgovaraju oni koji se Boga boje, Jahve pazi, sluša ih, i to se pred njim piše u knjigu spomenicu u korist onih koji se boje Jahve i štuju Ime njegovo.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (46, 3, 17, 'Moji će biti, moja stečevina - govori Jahve nad Vojskama. U Dan koji spremam bit ću im milostiv kao što je milostiv otac sinu koji mu služi.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (46, 3, 18, 'I tada ćete opet razlikovati pravednika od grešnika, onoga koji služi Bogu od onoga koji mu ne služi.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (46, 3, 19, 'Jer evo dan dolazi poput peći užaren; oholi i zlikovci bit će kao strnjika: dan koji se bliži spalit će ih - govori Jahve nad Vojskama - da im neće ostati ni korijena ni grančice.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (46, 3, 20, 'A vama koji se Imena moga bojite sunce pravde će ogranuti sa zdravljem u zrakama, i vi ćete izlaziti poskakujući kao telad na pašu.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (46, 3, 21, 'I gazit ćete bezbožnike kao prah pod nogama u dan koji spremam\" - govori Jahve nad Vojskama.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (46, 3, 22, '\"Spomenite se Zakona Mojsija, sluge moga, kome sam na Horebu propisao zakone i uredbe za sav Izrael.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (46, 3, 23, 'Evo, poslat ću vam proroka Iliju prije nego dođe Dan Jahvin, dan velik i strašan.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (46, 3, 24, 'On će obratiti srce otaca k sinovima, a srce sinova k ocima, da ne dođem i ne udarim prokletstvom zemlju.\"');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (47, 1, 1, 'Rodoslovlje Isusa Krista, sina Davidova, sina Abrahamova.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (47, 1, 2, 'Abrahamu se rodi Izak. Izaku se rodi Jakov. Jakovu se rodi Juda i njegova braća.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (47, 1, 3, 'Judi Tamara rodi Peresa i Zeraha. Peresu se rodi Hesron. Hesronu se rodi Ram.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (47, 1, 4, 'Ramu se rodi Aminadab. Aminadabu se rodi Nahšon. Nahšonu se rodi Salma.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (47, 1, 5, 'Salmi Rahaba rodi Boaza. Boazu Ruta rodi Obeda. Obedu se rodi Jišaj.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (47, 1, 6, 'Jišaju se rodi David kralj. Davidu bivša žena Urijina rodi Salomona.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (47, 1, 7, 'Salomonu se rodi Roboam. Roboamu se rodi Abija. Abiji se rodi Asa.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (47, 1, 8, 'Asi se rodi Jozafat. Jozafatu se rodi Joram. Joramu se rodi Ahazja.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (47, 1, 9, 'Ahazji se rodi Jotam. Jotamu se rodi Ahaz. Ahazu se rodi Ezekija.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (47, 1, 10, 'Ezekiji se rodi Manaše. Manašeu se rodi Amon. Amonu se rodi Jošija.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (47, 1, 11, 'Jošiji se rodi Jehonija i njegova braća u vrijeme progonstva u Babilon.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (47, 1, 12, 'Poslije progonstva u Babilon Jehoniji se rodi Šealtiel. Šealtielu se rodi Zerubabel.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (47, 1, 13, 'Zerubabelu se rodi Abiud. Abiudu se rodi Elijakim. Elijakimu se rodi Azor.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (47, 1, 14, 'Azoru se rodi Sadok. Sadoku se rodi Akim. Akimu se rodi Elijud.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (47, 1, 15, 'Elijudu se rodi Eleazar. Eleazaru se rodi Matan. Matanu se rodi Jakov.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (47, 1, 16, 'Jakovu se rodi Josip, muž Marije, od koje se rodio Isus koji se zove Krist.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (47, 1, 17, 'U svemu dakle: od Abrahama do Davida četrnaest naraštaja; od Davida do progonstva u Babilon četrnaest naraštaja; poslije progonstva u Babilon do Krista četrnaest naraštaja.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (47, 1, 18, 'A rođenje Isusa Krista zbilo se ovako. Njegova majka Marija, zaručena s Josipom, prije nego se sastadoše, nađe se trudna po Duhu Svetom.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (47, 1, 19, 'A Josip, muž njezin, pravedan, ne htjede je izvrgnuti sramoti, nego naumi da je potajice napusti.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (47, 1, 20, 'Dok je on to snovao, gle, anđeo mu se Gospodnji ukaza u snu i reče: \"Josipe, sine Davidov, ne boj se uzeti k sebi Mariju, ženu svoju. Što je u njoj začeto, doista je od Duha Svetoga.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (47, 1, 21, 'Rodit će sina, a ti ćeš mu nadjenuti ime Isus jer će on spasiti narod svoj od grijeha njegovih.\"');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (47, 1, 22, 'Sve se to dogodilo da se ispuni što Gospodin reče po proroku:');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (47, 1, 23, 'Evo, Djevica će začeti i roditi sina i nadjenut će mu se ime Emanuel - što znači: S nama Bog!');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (47, 1, 24, 'Kad se Josip probudi oda sna, učini kako mu naredi anđeo Gospodnji: uze k sebi svoju ženu.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (47, 1, 25, 'I ne upozna je dok ne rodi sina. I nadjenu mu ime Isus.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (47, 2, 1, 'Kad se Isus rodio u Betlehemu judejskome u dane Heroda kralja, gle, mudraci se s Istoka pojaviše u Jeruzalemu');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (47, 2, 2, 'raspitujući se: \"Gdje je taj novorođeni kralj židovski? Vidjesmo gdje izlazi zvijezda njegova pa mu se dođosmo pokloniti.\"');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (47, 2, 3, 'Kada to doču kralj Herod, uznemiri se on i sav Jeruzalem s njime.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (47, 2, 4, 'Sazva sve glavare svećeničke i pismoznance narodne pa ih ispitivaše gdje se Krist ima roditi.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (47, 2, 5, 'Oni mu odgovoriše: \"U Betlehemu judejskome jer ovako piše prorok:');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (47, 2, 6, 'A ti, Betleheme, zemljo Judina! Nipošto nisi najmanji među kneževstvima Judinim jer iz tebe će izaći vladalac koji će pasti narod moj - Izraela!');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (47, 2, 7, 'Tada Herod potajno dozva mudrace i razazna od njih vrijeme kad se pojavila zvijezda.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (47, 2, 8, 'Zatim ih posla u Betlehem: \"Pođite, reče, i pomno se raspitajte za dijete. Kad ga nađete, javite mi da i ja pođem te mu se poklonim.\"');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (47, 2, 9, 'Oni saslušavši kralja, pođoše. I gle, zvijezda kojoj vidješe izlazak iđaše pred njima sve dok ne stiže i zaustavi se povrh mjesta gdje bijaše dijete.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (47, 2, 10, 'Kad ugledaše zvijezdu, obradovaše se radošću veoma velikom.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (47, 2, 11, 'Uđu u kuću, ugledaju dijete s Marijom, majkom njegovom, padnu ničice i poklone mu se. Otvore zatim svoje blago i prinesu mu darove: zlato, tamjan i smirnu.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (47, 2, 12, 'Upućeni zatim u snu da se ne vraćaju Herodu, otiđoše drugim putem u svoju zemlju.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (47, 2, 13, 'A pošto oni otiđoše, gle, anđeo se Gospodnji u snu javi Josipu: \"Ustani, reče, uzmi dijete i majku njegovu te bježi u Egipat i ostani ondje dok ti ne reknem jer će Herod tražiti dijete da ga pogubi.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (47, 2, 14, 'On ustane, uzme noću dijete i majku njegovu te krene u Egipat.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (47, 2, 15, 'I osta ondje do Herodova skončanja - da se ispuni što Gospodin reče po proroku: Iz Egipta dozvah Sina svoga.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (47, 2, 16, 'Vidjevši da su ga mudraci izigrali, Herod se silno rasrdi i posla poubijati sve dječake u Betlehemu i po svoj okolici, od dvije godine naniže - prema vremenu što ga razazna od mudraca.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (47, 2, 17, 'Tada se ispuni što je rečeno po proroku Jeremiji:');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (47, 2, 18, 'U Rami se glas čuje, kuknjava i plač gorak: Rahela oplakuje sinove svoje i neće da se utješi jer više ih nema.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (47, 2, 19, 'Nakon Herodova skončanja, gle, anđeo se Gospodnji javi u snu Josipu u Egiptu:');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (47, 2, 20, '\"Ustani, reče, uzmi dijete i njegovu majku te pođi u zemlju izraelsku jer su umrli oni koji su djetetu o glavi radili.\"');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (47, 2, 21, 'On ustane, uzme dijete i njegovu majku te uđe u zemlju izraelsku.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (47, 2, 22, 'Ali saznavši da Arhelaj vlada Judejom namjesto svoga oca Heroda, bojao se poći onamo pa, upućen u snu, ode u kraj galilejski.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (47, 2, 23, 'Dođe i nastani se u gradu zvanu Nazaret - da se ispuni što je rečeno po prorocima: Zvat će se Nazarećanin.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (47, 3, 1, 'U one dane pojavi se Ivan Krstitelj propovijedajući u Judejskoj pustinji:');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (47, 3, 2, '\"Obratite se jer približilo se kraljevstvo nebesko!\"');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (47, 3, 3, 'Ovo je uistinu onaj o kom proreče Izaija prorok: Glas viče u pustinji: Pripravite put Gospodinu, poravnite mu staze!');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (47, 3, 4, 'Ivan je imao odjeću od devine dlake i kožnat pojas oko bokova; hranom mu bijahu skakavci i divlji med.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (47, 3, 5, 'Grnuo k njemu Jeruzalem, sva Judeja i sva okolica jordanska.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (47, 3, 6, 'Primali su od njega krštenje u rijeci Jordanu ispovijedajući svoje grijehe.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (47, 3, 7, 'Kad ugleda mnoge farizeje i saduceje gdje mu dolaze na krštenje, reče im: \"Leglo gujinje! Tko li vas je samo upozorio da bježite od skore srdžbe?');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (47, 3, 8, 'Donosite dakle plod dostojan obraćenja.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (47, 3, 9, 'I ne usudite se govoriti u sebi: \'Imamo oca Abrahama!\' Jer, kažem vam, Bog iz ovoga kamenja može podići djecu Abrahamovu.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (47, 3, 10, 'Već je sjekira položena na korijen stablima. Svako dakle stablo koje ne donosi dobroga roda, siječe se i u oganj baca.\"');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (47, 3, 11, '\"Ja vas, istina, krstim vodom na obraćenje, ali onaj koji za mnom dolazi jači je od mene. Ja nisam dostojan obuće mu nositi. On će vas krstiti Duhom Svetim i ognjem.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (47, 3, 12, 'U ruci mu vijača, pročistit će svoje gumno i skupiti žito u svoju žitnicu, a pljevu spaliti ognjem neugasivim.\"');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (47, 3, 13, 'Tada dođe Isus iz Galileje na Jordan Ivanu da ga on krsti.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (47, 3, 14, 'Ivan ga odvraćaše: \"Ti mene treba da krstiš, a ti da k meni dolaziš?\"');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (47, 3, 15, 'Ali mu Isus odgovori: \"Pusti sada! Ta dolikuje nam da tako ispunimo svu pravednost!\" Tada mu popusti.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (47, 3, 16, 'Odmah nakon krštenja izađe Isus iz vode. I gle! Otvoriše se nebesa i ugleda Duha Božjega gdje silazi kao golub i spušta se na nj.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (47, 3, 17, 'I eto glasa s neba: \"Ovo je Sin moj, Ljubljeni! U njemu mi sva milina!\"');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (47, 4, 1, 'Duh tada odvede Isusa u pustinju da ga đavao iskuša.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (47, 4, 2, 'I propostivši četrdeset dana i četrdeset noći, napokon ogladnje.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (47, 4, 3, 'Tada mu pristupi napasnik i reče: \"Ako si Sin Božji, reci da ovo kamenje postane kruhom.\"');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (47, 4, 4, 'A on odgovori: \"Pisano je: Ne živi čovjek samo o kruhu, nego o svakoj riječi što izlazi iz Božjih usta.\"');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (47, 4, 5, 'Ðavao ga tada povede u Sveti grad, postavi ga na vrh Hrama');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (47, 4, 6, 'i reče mu: \"Ako si Sin Božji, baci se dolje! Ta pisano je: Anđelima će svojim zapovjediti za tebe i na rukama će te nositi da se gdje nogom ne spotakneš o kamen.\"');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (47, 4, 7, 'Isus mu kaza: \"Pisano je također: Ne iskušavaj Gospodina, Boga svojega!\"');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (47, 4, 8, 'Ðavao ga onda povede na goru vrlo visoku i pokaza mu sva kraljevstva svijeta i slavu njihovu');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (47, 4, 9, 'pa mu reče: \"Sve ću ti to dati ako mi se ničice pokloniš.\"');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (47, 4, 10, 'Tada mu reče Isus: \"Odlazi, Sotono! Ta pisano je: Gospodinu, Bogu svom se klanjaj i njemu jedinom služi!\"');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (47, 4, 11, 'Tada ga pusti đavao. I gle, anđeli pristupili i služili mu.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (47, 4, 12, 'A čuvši da je Ivan predan, povuče se u Galileju.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (47, 4, 13, 'Ostavi Nazaret te ode i nastani se u Kafarnaumu, uz more, na području Zebulunovu i Naftalijevu');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (47, 4, 14, 'da se ispuni što je rečeno po proroku Izaiji:');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (47, 4, 15, 'Zemlja Zebulunova i zemlja Naftalijeva, Put uz more, s one strane Jordana, Galileja poganska -');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (47, 4, 16, 'narod što je sjedio u tmini svjetlost vidje veliku; onima što mrkli kraj smrti obitavahu svjetlost jarka osvanu.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (47, 4, 17, 'Otada je Isus počeo propovijedati: \"Obratite se jer približilo se kraljevstvo nebesko!\"');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (47, 4, 18, 'Prolazeći uz Galilejsko more, ugleda dva brata, Šimuna zvanog Petar i brata mu Andriju, gdje bacaju mrežu u more; bijahu ribari.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (47, 4, 19, 'I kaže im: \"Hajdete za mnom, učinit ću vas ribarima ljudi!\"');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (47, 4, 20, 'Oni brzo ostave mreže i pođu za njim.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (47, 4, 21, 'Pošavši odande, ugleda druga dva brata, Jakova Zebedejeva i brata mu Ivana: u lađi su sa Zebedejem, ocem svojim, krpali mreže. Pozva i njih.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (47, 4, 22, 'Oni brzo ostave lađu i oca te pođu za njim.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (47, 4, 23, 'I obilazio je Isus svom Galilejom naučavajući po njihovim sinagogama, propovijedajući Evanđelje o Kraljevstvu i liječeći svaku bolest i svaku nemoć u narodu.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (47, 4, 24, 'I glas se o njemu pronese svom Sirijom. I donosili su mu sve koji bolovahu od najrazličitijih bolesti i patnja - opsjednute, mjesečare, uzete - i on ih ozdravljaše.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (47, 4, 25, 'Za njim je pohrlio silan svijet iz Galileje, Dekapola, Jeruzalema, Judeje i Transjordanije.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (47, 5, 1, 'Ugledavši mnoštvo, uziđe na goru. I kad sjede, pristupe mu učenici.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (47, 5, 2, 'On progovori i stane ih naučavati:');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (47, 5, 3, '\"Blago siromasima duhom: njihovo je kraljevstvo nebesko!');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (47, 5, 4, 'Blago ožalošćenima: oni će se utješiti!');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (47, 5, 5, 'Blago krotkima: oni će baštiniti zemlju!');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (47, 5, 6, 'Blago gladnima i žednima pravednosti: oni će se nasititi!');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (47, 5, 7, 'Blago milosrdnima: oni će zadobiti milosrđe!');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (47, 5, 8, 'Blago čistima srcem: oni će Boga gledati!');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (47, 5, 9, 'Blago mirotvorcima: oni će se sinovima Božjim zvati!');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (47, 5, 10, 'Blago progonjenima zbog pravednosti: njihovo je kraljevstvo nebesko!\"');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (47, 5, 11, '\"Blago vama kad vas - zbog mene - pogrde i prognaju i sve zlo slažu protiv vas!');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (47, 5, 12, 'Radujte se i kličite: velika je plaća vaša na nebesima! Ta progonili su tako proroke prije vas!\"');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (47, 5, 13, '\"Vi ste sol zemlje. Ali ako sol obljutavi, čime će se ona osoliti? Nije više ni za što, nego da se baci van i da ljudi po njoj gaze.\"');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (47, 5, 14, '\"Vi ste svjetlost svijeta. Ne može se sakriti grad što leži na gori.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (47, 5, 15, 'Niti se užiže svjetiljka da se stavi pod posudu, nego na svijećnjak da svijetli svima u kući.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (47, 5, 16, 'Tako neka svijetli vaša svjetlost pred ljudima da vide vaša dobra djela i slave Oca vašega koji je na nebesima.\"');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (47, 5, 17, '\"Ne mislite da sam došao ukinuti Zakon ili Proroke. Nisam došao ukinuti, nego ispuniti.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (47, 5, 18, 'Zaista, kažem vam, dok ne prođe nebo i zemlja, ne, ni jedno slovce, ni jedan potezić iz Zakona neće proći, dok se sve ne zbude.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (47, 5, 19, 'Tko dakle ukine jednu od tih, pa i najmanjih zapovijedi i tako nauči ljude, najmanji će biti u kraljevstvu nebeskom. A tko ih bude vršio i druge učio, taj će biti velik u kraljevstvu nebeskom.\"');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (47, 5, 20, '\"Uistinu kažem vam: ne bude li pravednost vaša veća od pravednosti pismoznanaca i farizeja, ne, nećete ući u kraljevstvo nebesko.\"');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (47, 5, 21, '\"Čuli ste da je rečeno starima: Ne ubij! Tko ubije, bit će podvrgnut sudu.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (47, 5, 22, 'A ja vam kažem: Svaki koji se srdi na brata svoga, bit će podvrgnut sudu. A tko bratu rekne \'Glupane!\', bit će podvrgnut Vijeću. A tko reče: \'Luđače!\', bit će podvrgnut ognju paklenomu.\"');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (47, 5, 23, '\"Ako dakle prinosiš dar na žrtvenik pa se ondje sjetiš da tvoj brat ima nešto protiv tebe,');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (47, 5, 24, 'ostavi dar ondje pred žrtvenikom, idi i najprije se izmiri s bratom, a onda dođi i prinesi dar.\"');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (47, 5, 25, '\"Nagodi se brzo s protivnikom dok si još s njim na putu, da te protivnik ne preda sucu, a sudac tamničaru, pa da te ne bace u tamnicu.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (47, 5, 26, 'Zaita, kažem ti, nećeš izići odande dok ne isplatiš do posljednjeg novčića.\"');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (47, 5, 27, '\"Čuli ste da je rečeno: Ne čini preljuba!');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (47, 5, 28, 'A ja vam kažem: Tko god s požudom pogleda ženu, već je s njome učinio preljub u srcu.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (47, 5, 29, 'Ako te desno oko sablažnjava, iskopaj ga i baci od sebe. Ta bolje je da ti propadne jedan od udova, nego da ti cijelo tijelo bude bačeno u pakao.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (47, 5, 30, 'Ako te desnica tvoja sablažnjava, odsijeci je i baci od sebe. Ta bolje je da ti propadne jedan od udova, nego da ti cijelo tijelo ode u pakao.\"');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (47, 5, 31, '\"Rečeno je također: Tko otpusti svoju ženu, neka joj dade otpusnicu.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (47, 5, 32, 'A ja vam kažem: Tko god otpusti svoju ženu - osim zbog bludništva - navodi je na preljub i tko se god otpuštenom oženi, čini preljub.\"');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (47, 5, 33, '\"Čuli ste još da je rečeno starima: Ne zaklinji se krivo, nego izvrši Gospodinu svoje zakletve.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (47, 5, 34, 'A ja vam kažem: Ne kunite se nikako! Ni nebom jer je prijestolje Božje.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (47, 5, 35, 'Ni zemljom jer je podnožje njegovim nogama. Ni Jeruzalemom jer grad je Kralja velikoga!');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (47, 5, 36, 'Ni svojom se glavom ne zaklinji jer ni jedne vlasi ne možeš učiniti bijelom ili crnom.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (47, 5, 37, 'Vaša riječ neka bude: \'Da, da, - ne, ne!\' Što je više od toga, od Zloga je.\"');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (47, 5, 38, '\"Čuli ste da je rečeno: Oko za oko, zub za zub!');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (47, 5, 39, 'A ja vam kažem: Ne opirite se Zlomu! Naprotiv, pljusne li te tko po desnom obrazu, okreni mu i drugi.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (47, 5, 40, 'Onomu tko bi se htio s tobom parničiti da bi se domogao tvoje donje haljine prepusti i gornju.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (47, 5, 41, 'Ako te tko prisili jednu milju, pođi s njim dvije.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (47, 5, 42, 'Tko od tebe što zaište, podaj mu! I ne okreni se od onoga koji hoće da mu pozajmiš.\"');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (47, 5, 43, '\"Čuli ste da je rečeno: Ljubi svoga bližnjega, a mrzi neprijatelja.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (47, 5, 44, 'A ja vam kažem: Ljubite neprijatelje, molite za one koji vas progone');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (47, 5, 45, 'da budete sinovi svoga oca koji je na nebesima, jer on daje da sunce njegovo izlazi nad zlima i dobrima i da kiša pada pravednicima i nepravednicima.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (47, 5, 46, 'Jer ako ljubite one koji vas ljube, kakva li vam plaća? Zar to isto ne čine i carinici?');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (47, 5, 47, 'I ako pozdravljate samo braću, što osobito činite? Zar to isto ne čine i pogani?\"');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (47, 5, 48, '\"Budite dakle savršeni kao što je savršen Otac vaš nebeski!\"');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (47, 6, 1, '\"Pazite da svoje pravednosti ne činite pred ljudima da vas oni vide. Inače, nema vam plaće u vašeg Oca koji je na nebesima.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (47, 6, 2, 'Kada dakle dijeliš milostinju, ne trubi pred sobom, kako to u sinagogama i na ulicama čine licemjeri da bi ih ljudi hvalili. Zaista, kažem vam, primili su svoju plaću.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (47, 6, 3, 'Ti naprotiv, kada daješ milostinju - neka ti ne zna ljevica što čini desnica,');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (47, 6, 4, 'da tvoja milostinja bude u skrovitosti. I Otac tvoj, koji vidi u skrovitosti, uzvratit će ti!\"');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (47, 6, 5, '\"Tako i kad molite, ne budite kao licemjeri. Vole moliti stojeći u sinagogama i na raskršćima ulica da se pokažu ljudima. Zaista, kažem vam, primili su svoju plaću.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (47, 6, 6, 'Ti naprotiv, kad moliš, uđi u svoju sobu, zatvori vrata i pomoli se svomu Ocu, koji je u skrovitosti. I Otac tvoj, koji vidi u skrovitosti, uzvratit će ti.\"');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (47, 6, 7, '\"Kad molite, ne blebećite kao pogani. Misle da će s mnoštva riječi biti uslišani.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (47, 6, 8, 'Ne nalikujte na njih. Ta zna vaš Otac što vam treba i prije negoli ga zaištete.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (47, 6, 9, 'Vi, dakle, ovako molite: \'Oče naš, koji jesi na nebesima! Sveti se ime tvoje!');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (47, 6, 10, 'Dođi kraljevstvo tvoje! Budi volja tvoja kako na nebu tako i na zemlji!');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (47, 6, 11, 'Kruh naš svagdanji daj nam danas!');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (47, 6, 12, 'I opusti nam duge naše kako i mi otpustismo dužnicima svojim!');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (47, 6, 13, 'I ne uvedi nas u napast, nego izbavi nas od Zloga!\'\"');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (47, 6, 14, '\"Doista, ako vi otpustite ljudima njihove prijestupke, otpustit će i vama Otac vaš nebeski.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (47, 6, 15, 'Ako li vi ne otpustite ljudima, ni Otac vaš neće otpustiti vaših prijestupaka.\"');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (47, 6, 16, '\"I kad postite, ne budite smrknuti kao licemjeri. Izobličuju lica da pokažu ljudima kako poste. Zaista, kažem vam, primili su svoju plaću.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (47, 6, 17, 'Ti naprotiv, kad postiš, pomaži glavu i umij lice');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (47, 6, 18, 'da ne zapaze ljudi kako postiš, nego Otac tvoj, koji je u skrovitosti. I Otac tvoj, koji vidi u skrovitosti, uzvratit će ti.\"');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (47, 6, 19, '\"Ne zgrćite sebi blago na zemlji, gdje ga moljac i rđa nagrizaju i gdje ga kradljivci potkapaju i kradu.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (47, 6, 20, 'Zgrćite sebi blago na nebu, gdje ga ni moljac ni rđa ne nagrizaju i gdje kradljivci ne potkapaju niti kradu.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (47, 6, 21, 'Doista, gdje ti je blago, ondje će ti biti i srce.\"');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (47, 6, 22, '\"Oko je tijelu svjetiljka. Ako ti je dakle oko bistro, sve će tijelo tvoje biti svijetlo.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (47, 6, 23, 'Ako ti je pak oko nevaljalo, sve će tijelo tvoje biti tamno. Ako je dakle svjetlost koja je u tebi - tamna, kolika će istom tama biti?\"');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (47, 6, 24, '\"Nitko ne može služiti dvojici gospodara. Ili će jednoga mrziti, a drugoga ljubiti; ili će uz jednoga prianjati, a drugoga prezirati. Ne možete služiti Bogu i bogatstvu.\"');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (47, 6, 25, '\"Zato vam kažem: Ne budite zabrinuti za život svoj: što ćete jesti, što ćete piti; ni za tijelo svoje: u što ćete se obući. Zar život nije vredniji od jela i tijelo od odijela?\"');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (47, 6, 26, '\"Pogledajte ptice nebeske! Ne siju, ne žanju niti sabiru u žitnice, pa ipak ih hrani vaš nebeski Otac. Zar niste vi vredniji od njih?');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (47, 6, 27, 'A tko od vas zabrinutošću može svome stasu dodati jedan lakat?');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (47, 6, 28, 'I za odijelo što ste zabrinuti? Promotrite poljske ljiljane, kako rastu! Ne muče se niti predu.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (47, 6, 29, 'A kažem vam: ni Salomon se u svoj svojoj slavi ne zaodjenu kao jedan od njih.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (47, 6, 30, 'Pa ako travu poljsku, koja danas jest a sutra se u peć baca, Bog tako odijeva, neće li još više vas, malovjerni?\"');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (47, 6, 31, '\"Nemojte dakle zabrinuto govoriti: \'Što ćemo jesti?\' ili: \'Što ćemo piti?\' ili: \'U što ćemo se obući?\'');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (47, 6, 32, 'Ta sve to pogani ištu. Zna Otac vaš nebeski da vam je sve to potrebno.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (47, 6, 33, 'Tražite stoga najprije Kraljevstvo i pravednost njegovu, a sve će vam se ostalo dodati.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (47, 6, 34, 'Ne budite dakle zabrinuti za sutra. Sutra će se samo brinuti za se. Dosta je svakom danu zla njegova.\"');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (47, 7, 1, '\"Ne sudite da ne budete suđeni!');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (47, 7, 2, 'Jer sudom kojim sudite bit ćete suđeni. I mjerom kojom mjerite mjerit će vam se.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (47, 7, 3, 'Što gledaš trun u oku brata svojega, a brvna u oku svome ne opažaš?');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (47, 7, 4, 'Ili kako možeš reći bratu svomu: \'De da ti izvadim trun iz oka\', a eto brvna u oku tvom?');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (47, 7, 5, 'Licemjere, izvadi najprije brvno iz oka svoga pa ćeš onda dobro vidjeti izvaditi trun iz oka bratova!\"');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (47, 7, 6, '\"Ne dajte svetinje psima! Niti svoga biserja bacajte pred svinje da ga ne pogaze nogama pa se okrenu i rastrgaju vas.\"');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (47, 7, 7, '\"Ištite i dat će vam se! Tražite i naći ćete! Kucajte i otvorit će vam se!');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (47, 7, 8, 'Doista, tko god ište, prima; i tko traži, nalazi; i onomu koji kuca otvorit će se.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (47, 7, 9, 'Ta ima li koga među vama da bi svojemu sinu, ako ga zaište kruha, kamen dao?');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (47, 7, 10, 'Ili ako ribu zaište, zar će mu zmiju dati?');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (47, 7, 11, 'Ako dakle vi, iako zli, znate dobrim darima darivati djecu svoju, koliko li će više Otac vaš, koji je na nebesima, dobrima obdariti one koji ga zaištu!\"');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (47, 7, 12, '\"Sve, dakle, što želite da ljudi vama čine, činite i vi njima. To je, doista, Zakon i Proroci.\"');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (47, 7, 13, '\"Uđite na uska vrata! Jer široka su vrata i prostran put koji vodi u propast i mnogo ih je koji njime idu.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (47, 7, 14, 'O kako su uska vrata i tijesan put koji vodi u Život i malo ih je koji ga nalaze!\"');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (47, 7, 15, '\"Čuvajte se lažnih proroka koji dolaze k vama u ovčjem odijelu, a iznutra su vuci grabežljivi.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (47, 7, 16, 'Po njihovim ćete ih plodovima prepoznati. Bere li se s trnja grožđe ili s bodljike smokve?');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (47, 7, 17, 'Tako svako dobro stablo rađa dobrim plodovima, a nevaljalo stablo rađa plodovima zlim.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (47, 7, 18, 'Ne može dobro stablo donijeti zlih plodova niti nevaljalo stablo dobrih plodova.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (47, 7, 19, 'Svako stablo koje ne rađa dobrim plodom siječe se i u oganj baca.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (47, 7, 20, 'Dakle: po plodovima ćete ih njihovim prepoznati.\"');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (47, 7, 21, '\"Neće u kraljevstvo nebesko ući svaki koji mi govori: \'Gospodine, Gospodine!\', nego onaj koji vrši volju Oca mojega, koji je na nebesima.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (47, 7, 22, 'Mnogi će me u onaj dan pitati: \'Gospodine, Gospodine! Nismo li mi u tvoje ime prorokovali, u tvoje ime đavle izgonili, u tvoje ime mnoga čudesa činili?\'');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (47, 7, 23, 'Tada ću im kazati: \'Nikad vas nisam poznavao! Nosite se od mene, vi bezakonici!\'\"');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (47, 7, 24, '\"Stoga, tko god sluša ove moje riječi i izvršava ih, bit će kao mudar čovjek koji sagradi kuću na stijeni.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (47, 7, 25, 'Zapljušti kiša, navale bujice, duhnu vjetrovi i sruče se na tu kuću, ali ona ne pada. Jer - utemeljena je na stijeni.\"');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (47, 7, 26, '\"Naprotiv, tko god sluša ove moje riječi, a ne vrši ih, bit će kao lud čovjek koji sagradi kuću na pijesku.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (47, 7, 27, 'Zapljušti kiša, navale bujice, duhnu vjetrovi i sruče se na tu kuću i ona se sruši. I bijaše to ruševina velika.\"');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (47, 7, 28, 'Kad Isus završi ove svoje besjede, mnoštvo osta zaneseno njegovim naukom.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (47, 7, 29, 'Ta učio ih kao onaj koji ima vlast, a ne kao njihovi pismoznanci.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (47, 8, 1, 'Kad je Isus sišao s gore, pohrli za njim silan svijet.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (47, 8, 2, 'I gle, pristupi neki gubavac, pokloni mu se do zemlje i reče: \"Gospodine, ako hoćeš, možeš me očistiti.\"');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (47, 8, 3, 'Isus pruži ruku i dotakne ga se govoreći: \"Hoću, očisti se!\" I odmah se očisti od gube.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (47, 8, 4, 'Kaže mu Isus: \"Pazi, nikomu ne kazuj, nego idi, pokaži se svećeniku i prinesi dar što ga propisa Mojsije, njima za svjedočanstvo.\"');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (47, 8, 5, 'Kad uđe u Kafarnaum, pristupi mu satnik pa ga zamoli:');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (47, 8, 6, '\"Gospodine, sluga mi leži kod kuće uzet, u strašnim mukama.\"');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (47, 8, 7, 'Kaže mu: \"Ja ću doći izliječiti ga.\"');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (47, 8, 8, 'Odgovori satnik: \"Gospodine, nisam dostojan da uđeš pod krov moj, nego samo reci riječ i izliječen će biti sluga moj.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (47, 8, 9, 'Ta i ja, premda sam čovjek pod vlašću, imam pod sobom vojnike pa reknem jednomu: \'Idi!\' - i ode, drugomu: \'Dođi!\' - i dođe, a sluzi svomu: \'Učini to\' - i učini.\"');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (47, 8, 10, 'Čuvši to, zadivi se Isus i reče onima koji su išli za njim: \"Zaista, kažem vam, ni u koga u Izraelu ne nađoh tolike vjere.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (47, 8, 11, 'A kažem vam: Mnogi će s istoka i zapada doći i sjesti za stol s Abrahamom, Izakom i Jakovom u kraljevstvu nebeskom,');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (47, 8, 12, 'a sinovi će kraljevstva biti izbačeni van u tamu. Ondje će biti plač i škrgut zubi.\"');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (47, 8, 13, 'I reče Isus satniku: \"Idi, neka ti bude kako si vjerovao!\" I ozdravi sluga u taj čas.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (47, 8, 14, 'Ušavši u kuću Petrovu, Isus ugleda njegovu punicu koja ležaše u ognjici.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (47, 8, 15, 'Dotače joj se ruke i pusti je ognjica. Ona ustade i posluživaše mu.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (47, 8, 16, 'A uvečer mu doniješe mnoge opsjednute. On izagna duhove riječju i sve bolesnike ozdravi -');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (47, 8, 17, 'da se ispuni što je rečeno po Izaiji proroku: On slabosti naše uze i boli ponese.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (47, 8, 18, 'Kad Isus vidje mnoštvo oko sebe, zapovjedi da se prijeđe prijeko.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (47, 8, 19, 'I pristupi jedan pismoznanac te mu reče: \"Učitelju, za tobom ću kamo god ti pošao.\"');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (47, 8, 20, 'Kaže mu Isus: \"Lisice imaju jazbine i ptice nebeske gnijezda, a Sin Čovječji nema gdje bi glavu naslonio.\"');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (47, 8, 21, 'Drugi mu od učenika reče: \"Gospodine, dopusti mi da prije odem i pokopam svoga oca.\"');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (47, 8, 22, 'Isus mu kaže: \"Hajde za mnom i pusti neka mrtvi pokapaju svoje mrtve.\"');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (47, 8, 23, 'Kad uđe u lađu, pođoše za njim njegovi učenici.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (47, 8, 24, 'I gle, žestok vihor nasta na moru tako da lađu prekrivahu valovi. A on je spavao.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (47, 8, 25, 'Oni pristupiše i probudiše ga govoreći: \"Gospodine, spasi, pogibosmo!\"');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (47, 8, 26, 'Kaže im: \"Što ste plašljivi, malovjerni?\" Tada ustade i zaprijeti vjetrovima i moru te nasta velika utiha.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (47, 8, 27, 'A ljudi su u čudu pitali: \"Tko je taj da mu se i vjetrovi i more pokoravaju?\"');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (47, 8, 28, 'I kada dođe prijeko, u gadarski kraj, eto mu u susret dvaju opsjednutih: izlazili su iz grobnica, silno goropadni, te nitko nije mogao proći onim putem.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (47, 8, 29, 'I gle, povikaše: \"Što ti imaš s nama, Sine Božji? Došao si ovamo prije vremena mučiti nas?\"');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (47, 8, 30, 'A podalje od njih paslo je veliko krdo svinja.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (47, 8, 31, 'Zlodusi ga zaklinjahu: \"Ako nas istjeraš, pošalji nas u ovo krdo svinja.\"');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (47, 8, 32, 'On im reče: \"Idite!\" Oni iziđoše i uđoše u svinje. I gle, sve krdo jurnu niz obronak u more i podavi se u vodama.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (47, 8, 33, 'A svinjari pobjegoše, odoše u grad te razglasiše sve, napose o opsjednutima.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (47, 8, 34, 'I gle, sav grad iziđe u susret Isusu. Kad ga ugledaše, zamole ga da ode iz njihova kraja.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (47, 9, 1, 'I ušavši u lađu, preplovi i dođe u svoj grad.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (47, 9, 2, 'Kad gle, doniješe mu uzetoga koji je ležao na nosiljci. Vidjevši njihovu vjeru, reče Isus uzetomu: \"Hrabro, sinko, otpuštaju ti se grijesi!\"');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (47, 9, 3, 'A gle, neki od pismoznanaca rekoše u sebi: \"Ovaj huli!\"');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (47, 9, 4, 'Prozrevši njihove misli, Isus reče: \"Zašto snujete zlo u srcima?');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (47, 9, 5, 'Ta što je lakše reći: \'Otpuštaju ti se grijesi\' ili reći: \'Ustani i hodi\'?');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (47, 9, 6, 'Ali da znate: vlastan je Sin Čovječji na zemlji otpuštati grijehe!\" Tada reče uzetomu: \"Ustani, uzmi nosiljku i pođi kući!\"');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (47, 9, 7, 'I on usta te ode kući.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (47, 9, 8, 'Kad mnoštvo to vidje, zaprepasti se i poda slavu Bogu koji takvu vlast dade ljudima.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (47, 9, 9, 'Odlazeći odande, ugleda Isus čovjeka zvanog Matej gdje sjedi u carinarnici. I kaže mu: \"Pođi za mnom!\" On usta i pođe za njim.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (47, 9, 10, 'Dok je Isus bio u kući za stolom, gle, mnogi carinici i grešnici dođoše za stol s njime i njegovim učenicima.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (47, 9, 11, 'Vidjevši to, farizeji stanu govoriti: \"Zašto vaš učitelj jede s carinicima i grešnicima?\"');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (47, 9, 12, 'A on, čuvši to, reče: \"Ne treba zdravima liječnika, nego bolesnima.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (47, 9, 13, 'Hajdete i proučite što znači: Milosrđe mi je milo, a ne žrtva. Ta ne dođoh zvati pravednike, nego grešnike.\"');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (47, 9, 14, 'Tada pristupe k njemu Ivanovi učenici govoreći: \"Zašto mi i farizeji postimo, a učenici tvoji ne poste?\"');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (47, 9, 15, 'Nato im Isus reče: \"Mogu li svatovi tugovati dok je s njima zaručnik? Doći će već dani kad će im se ugrabiti zaručnik, i tada će postiti!\"');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (47, 9, 16, '\"A nitko ne stavlja krpe od sirova sukna na staro odijelo, jer zakrpa vuče s odijela pa nastane još veća rupa.\"');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (47, 9, 17, '\"I ne ulijeva se novo vino u stare mješine. Inače se mješine proderu, vino prolije, a mješine propadnu. Nego, novo se vino ulijeva u nove mješine pa se oboje sačuva.\"');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (47, 9, 18, 'Dok im on to govoraše, gle, pristupi neki glavar, pokloni mu se do zemlje i reče: \"Kći mi, evo, umrije, ali dođi, stavi ruku na nju, i oživjet će.\"');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (47, 9, 19, 'Isus usta te s učenicima pođe za njim.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (47, 9, 20, 'I gle, neka žena koja bolovaše dvanaest godina od krvarenja priđe odostraga i dotaknu se skuta njegove haljine.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (47, 9, 21, 'Mislila je: \"Dotaknem li se samo njegove haljine, spasit ću se.\"');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (47, 9, 22, 'A Isus se okrenu i vidjevši je reče: \"Hrabro, kćeri, vjera te tvoja spasila.\" I žena bi spašena od toga časa.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (47, 9, 23, 'I uđe Isus u kuću glavarovu. Ugleda svirače i bučno mnoštvo pa');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (47, 9, 24, 'reče: \"Odstupite! Djevojka nije umrla, nego spava.\" Oni mu se podsmjehivahu.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (47, 9, 25, 'A kad je svijet bio izbačen, uđe on, primi djevojku za ruku i ona bi uskrišena.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (47, 9, 26, 'I razglasi se to po svem onom kraju.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (47, 9, 27, 'Kad je Isus odlazio odande, pođu za njim dva slijepca vičući: \"Smiluj nam se, Sine Davidov!\"');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (47, 9, 28, 'A kad uđe u kuću, pristupe mu slijepci. Isus im kaže: \"Vjerujete li da mogu to učiniti?\" Kažu mu: \"Da, Gospodine!\"');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (47, 9, 29, 'Tada se dotače njihovih očiju govoreći: \"Neka vam bude po vašoj vjeri.\"');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (47, 9, 30, 'I otvoriše im se oči. A Isus im poprijeti: \"Pazite da nitko ne dozna!\"');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (47, 9, 31, 'Ali oni, izišavši, razniješe glas o njemu po svem onom kraju.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (47, 9, 32, 'Tek što oni iziđoše, gle, doniješe mu njemaka opsjednuta.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (47, 9, 33, 'Pošto izagna đavla, progovori njemak. Mnoštvo se čudom čudilo i govorilo: \"Nikada se takvo što ne vidje u Izraelu!\"');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (47, 9, 34, 'A farizeji govorahu: \"Po poglavici đavolskome izgoni đavle.\"');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (47, 9, 35, 'I obilazio je Isus sve gradove i sela učeći po njihovim sinagogama, propovijedajući Evanđelje o Kraljevstvu i liječeći svaku bolest i svaku nemoć.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (47, 9, 36, 'Vidjevši mnoštvo, sažali mu se nad njim jer bijahu izmučeni i ophrvani kao ovce bez pastira.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (47, 9, 37, 'Tada reče svojim učenicima: \"Žetve je mnogo, a radnika malo.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (47, 9, 38, 'Molite dakle gospodara žetve da pošalje radnike u žetvu svoju.\"');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (47, 10, 1, 'Dozva dvanaestoricu svojih učenika i dade im vlast nad nečistim dusima: da ih izgone i da liječe svaku bolest i svaku nemoć.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (47, 10, 2, 'A ovo su imena dvanaestorice apostola: prvi Šimun, zvani Petar, i Andrija, brat njegov; i Jakov, sin Zebedejev, i Ivan brat njegov;');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (47, 10, 3, 'Filip i Bartolomej; Toma i Matej carinik; Jakov Alfejev i Tadej;');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (47, 10, 4, 'Šimun Kananaj i Juda Iškariotski, koji ga izda.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (47, 10, 5, 'Tu dvanaestoricu posla Isus uputivši ih: \"K poganima ne idite i ni u koji samarijski grad ne ulazite!');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (47, 10, 6, 'Pođite radije k izgubljenim ovcama doma Izraelova!');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (47, 10, 7, 'Putom propovijedajte: \'Približilo se kraljevstvo nebesko!\'');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (47, 10, 8, 'Bolesne liječite, mrtve uskrisujte, gubave čistite, zloduhe izgonite! Besplatno primiste, besplatno dajte!');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (47, 10, 9, 'Ne stječite zlata, ni srebra, ni mjedi sebi u pojase,');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (47, 10, 10, 'ni putne torbe, ni dviju haljina, ni obuće, ni štapa. Ta vrijedan je radnik hrane svoje.\"');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (47, 10, 11, '\"U koji god grad ili selo uđete, razvidite tko je u njemu dostojan: ondje ostanite sve dok ne odete.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (47, 10, 12, 'Ulazeći u kuću, zaželite joj mir.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (47, 10, 13, 'Bude li kuća dostojna, neka mir vaš siđe na nju. Ne bude li dostojna, neka se mir vaš k vama vrati.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (47, 10, 14, 'Gdje vas ne prime i ne poslušaju riječi vaših, iziđite iz kuće ili grada toga i prašinu otresite sa svojih nogu.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (47, 10, 15, 'Zaista, kažem vam, lakše će biti zemlji sodomskoj i gomorskoj na Dan sudnji negoli gradu tomu.\"');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (47, 10, 16, '\"Evo, ja vas šaljem kao ovce među vukove. Budite dakle mudri kao zmije, a bezazleni kao golubovi!');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (47, 10, 17, 'Čuvajte se ljudi, jer će vas predavati vijećima i po svojim će vas sinagogama bičevati.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (47, 10, 18, 'Pred upravitelje i kraljeve vodit će vas poradi mene, za svjedočanstvo njima i poganima.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (47, 10, 19, 'Kad vas predadu, ne budite zabrinuti kako ili što ćete govoriti. Dat će vam se u onaj čas što ćete govoriti.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (47, 10, 20, 'Ta ne govorite to vi, nego Duh Oca vašega govori u vama!\"');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (47, 10, 21, '\"Brat će brata predavati na smrt i otac dijete. Djeca će ustajati na roditelje i ubijati ih.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (47, 10, 22, 'Svi će vas zamrziti zbog imena moga. Ali tko ustraje do svršetka, bit će spašen.\"');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (47, 10, 23, '\"Kad vas stanu progoniti u jednom gradu, bježite u drugi. Zaista, kažem vam, nećete obići gradova izraelskih prije nego što dođe Sin Čovječji.\"');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (47, 10, 24, '\"Nije učenik nad učiteljem niti sluga nad gospodarom svojim.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (47, 10, 25, 'Dosta je da učenik bude kao njegov učitelj i sluga kao njegov gospodar. Ako su domaćina Beelzebulom nazvali, koliko će više njegove ukućane?\"');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (47, 10, 26, '\"Ne bojte ih se dakle. Ta ništa nije skriveno što se neće otkriti ni tajno što se neće doznati.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (47, 10, 27, 'Što vam govorim u tami, recite na svjetlu; i što na uho čujete, propovijedajte na krovovima.\"');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (47, 10, 28, '\"Ne bojte se onih koji ubijaju tijelo, ali duše ne mogu ubiti. Bojte se više onoga koji može i dušu i tijelo pogubiti u paklu.\"');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (47, 10, 29, '\"Ne prodaju li se dva vrapca za novčić? Pa ipak ni jedan od njih ne pada na zemlju bez Oca vašega.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (47, 10, 30, 'A vama su i vlasi na glavi sve izbrojene.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (47, 10, 31, 'Ne bojte se dakle! Vredniji ste nego mnogo vrabaca.\"');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (47, 10, 32, '\"Tko god se, dakle, prizna mojim pred ljudima, priznat ću se i ja njegovim pred Ocem, koji je na nebesima.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (47, 10, 33, 'A tko se odreče mene pred ljudima, odreći ću se i ja njega pred svojim Ocem, koji je na nebesima.\"');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (47, 10, 34, '\"Ne mislite da sam došao mir donijeti na zemlju. Ne, nisam došao donijeti mir, nego mač.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (47, 10, 35, 'Ta došao sam rastaviti čovjeka od oca njegova i kćer od majke njezine i snahu od svekrve njezine;');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (47, 10, 36, 'i neprijatelji će čovjeku biti ukućani njegovi.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (47, 10, 37, '\"Tko ljubi oca ili majku više nego mene, nije mene dostojan. Tko ljubi sina ili kćer više nego mene, nije mene dostojan.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (47, 10, 38, 'Tko ne uzme svoga križa i ne pođe za mnom, nije mene dostojan.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (47, 10, 39, 'Tko nađe život svoj, izgubit će ga, a tko izgubi svoj život poradi mene, naći će ga.\"');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (47, 10, 40, '\"Tko vas prima, mene prima; a tko prima mene, prima onoga koji je mene poslao.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (47, 10, 41, 'Tko prima proroka jer je prorok, primit će plaću proročku; tko prima pravednika jer je pravednik, primit će plaću pravedničku.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (47, 10, 42, 'Tko napoji jednoga od ovih najmanjih samo čašom hladne vode zato što je moj učenik, zaista, kažem vam, neće mu propasti plaća.\"');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (47, 11, 1, 'Pošto Isus završi upućivati dvanaestoricu učenika, ode odande naučavati i propovijedati po njihovim gradovima.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (47, 11, 2, 'A kad Ivan u tamnici doču za djela Kristova, posla svoje učenike');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (47, 11, 3, 'da ga upitaju: \"Jesi li ti Onaj koji ima doći ili drugoga da čekamo?\"');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (47, 11, 4, 'Isus im odgovori: \"Pođite i javite Ivanu što ste čuli i vidjeli:');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (47, 11, 5, 'Slijepi progledaju, hromi hode, gubavi se čiste, gluhi čuju, mrtvi ustaju, siromasima se navješćuje Evanđelje.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (47, 11, 6, 'I blago onom tko se ne sablazni o mene.\"');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (47, 11, 7, 'Kad oni odoše, poče Isus govoriti mnoštvu o Ivanu: \"Što ste izišli u pustinju gledati? Trsku koju vjetar ljulja?');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (47, 11, 8, 'Ili što ste izišli vidjeti? Čovjeka u mekušasto odjevena? Eno, oni što se mekušasto nose po kraljevskim su dvorima.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (47, 11, 9, 'Ili što ste izišli? Vidjeti proroka? Da, kažem vam, i više nego proroka.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (47, 11, 10, 'On je onaj o kome je pisano: Evo, ja šaljem glasnika svoga pred licem tvojim da pripravi put pred tobom.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (47, 11, 11, 'Zaista, kažem vam, između rođenih od žene ne usta veći od Ivana Krstitelja. A ipak, i najmanji u kraljevstvu nebeskom veći je od njega!');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (47, 11, 12, 'A od dana Ivana Krstitelja do sada kraljevstvo nebesko silom se probija i siloviti ga grabe.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (47, 11, 13, 'Uistinu, svi proroci i Zakon prorokovahu do Ivana.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (47, 11, 14, 'Zapravo ako hoćete: on je Ilija koji ima doći.\"');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (47, 11, 15, '\"Tko ima uši, neka čuje.\"');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (47, 11, 16, '\"A komu da prispodobim ovaj naraštaj? Nalik je djeci što sjede na trgovima pa jedni drugima dovikuju:');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (47, 11, 17, '\'Zasvirasmo vam i ne zaigraste, zakukasmo i ne zaplakaste.\'\"');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (47, 11, 18, '\"Doista, dođe Ivan. Nije jeo ni pio, a govori se: \'Ðavla ima.\'');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (47, 11, 19, 'Dođe Sin Čovječji koji jede i pije, a govori se: \'Gle, izjelice i vinopije, prijatelja carinika i grešnika!\' Ali opravda se Mudrost djelima svojim.\"');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (47, 11, 20, 'Tada stane prekoravati gradove u kojima se dogodilo najviše njegovih čudesa, a oni se ne obratiše:');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (47, 11, 21, '\"Jao tebi, Korozaine! Jao tebi, Betsaido! Da su se u Tiru i Sidonu zbila čudesa koja su se dogodila u vama, odavna bi se već oni u kostrijeti i pepelu bili obratili.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (47, 11, 22, 'Ali kažem vam: Tiru i Sidonu bit će na Dan sudnji lakše negoli vama.\"');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (47, 11, 23, '\"I ti, Kafarnaume! Zar ćeš se do neba uzvisiti? Do u Podzemlje ćeš se strovaliti! Doista, da su se u Sodomi zbila čudesa koja su se dogodila u tebi, ostala bi ona do danas.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (47, 11, 24, 'Ali kažem vam: Zemlji će sodomskoj biti na Dan sudnji lakše nego tebi.\"');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (47, 11, 25, 'U ono vrijeme reče Isus: \"Slavim te, Oče, Gospodaru neba i zemlje, što si ovo sakrio od mudrih i umnih, a objavio malenima.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (47, 11, 26, 'Da, Oče, tako se tebi svidjelo.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (47, 11, 27, 'Sve je meni predao Otac moj i nitko ne pozna Sina doli Otac niti tko pozna Oca doli Sin i onaj kome Sin hoće objaviti.\"');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (47, 11, 28, '\"Dođite k meni svi koji ste izmoreni i opterećeni i ja ću vas odmoriti.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (47, 11, 29, 'Uzmite jaram moj na sebe, učite se od mene jer sam krotka i ponizna srca i naći ćete spokoj dušama svojim.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (47, 11, 30, 'Uistinu, jaram je moj sladak i breme moje lako.\"');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (47, 12, 1, 'U ono vrijeme prolazio je Isus subotom kroz usjeve. Učenici su njegovi ogladnjeli te počeli trgati klasje i jesti.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (47, 12, 2, 'Vidjevši to, farizeji mu rekoše: \"Gle, učenici tvoji čine što nije dopušteno činiti subotom.\"');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (47, 12, 3, 'On im reče: \"Niste li čitali što učini David kad ogladnje on i njegovi pratioci?');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (47, 12, 4, 'Kako uđe u Dom Božji te pojedoše prinesene kruhove, a to ne bijaše slobodno jesti ni njemu ni njegovim pratiocima, nego samo svećenicima?');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (47, 12, 5, 'Ili zar niste čitali u Zakonu da subotom svećenici u Hramu krše subotu, a bez krivnje su?');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (47, 12, 6, 'A velim vam: veće od Hrama jest ovdje!');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (47, 12, 7, 'I kad biste razumjeli što ono znači: Milosrđe mi je milo, a ne žrtva, ne biste osudili ove nekrive.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (47, 12, 8, 'Ta Sin Čovječji gospodar je subote!\"');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (47, 12, 9, 'Otišavši odande, dođe u njihovu sinagogu,');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (47, 12, 10, 'kad gle čovjeka s usahlom rukom. A oni upitaše Isusa da bi ga mogli optužiti: \"Je li dopušteno subotom liječiti?\"');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (47, 12, 11, 'On im reče: \"Tko to od vas jedinu ovcu koju ima ne bi subotom prihvatio i izvadio kad bi mu upala u jamu?');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (47, 12, 12, 'A koliko je čovjek vredniji od ovce! Tako, slobodno je subotom činiti dobro!\"');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (47, 12, 13, 'Tada reče čovjeku: \"Ispruži ruku!\" On je ispruži, i - ruka mu zdrava kao i druga!');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (47, 12, 14, 'A farizeji iziđoše i održaše vijećanje protiv njega, kako da ga pogube.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (47, 12, 15, 'Kad Isus to dozna, ukloni se odande. Za njim je išlo mnoštvo. On ih sve ozdravi');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (47, 12, 16, 'i poprijeti im da ga ne prokazuju -');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (47, 12, 17, 'da se ispuni što je rečeno po Izaiji proroku:');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (47, 12, 18, 'Evo Sluge mojega, koga sebi izabrah: mog ljubimca, miljenika duše moje! Stavit ću Duha svoga na njega: naviještat će pravo narodima;');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (47, 12, 19, 'preti se neće, neće bučiti, glas mu se neće čuti po trgovima;');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (47, 12, 20, 'trske stučene prelomiti neće, stijenja što tek tinja neće ugasiti - sve dok do pobjede ne izvede pravo.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (47, 12, 21, 'Ime njegovo nada je narodima!');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (47, 12, 22, 'Tada mu donesoše opsjednuta, slijepa i nijema. I ozdravi ga te njemak progovori i progleda.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (47, 12, 23, 'I sve ono mnoštvo zapanjeno govoraše: \"Da ovo nije Sin Davidov?\"');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (47, 12, 24, 'A farizeji čuvši to rekoše: \"Ne može ovaj izgoniti đavle osim po Beelzebulu, poglavici đavolskom.\"');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (47, 12, 25, 'A on, znajući njihove misli, reče im: \"Svako kraljevstvo u sebi razdijeljeno opustjet će i svaki grad ili kuća u sebi razdijeljena neće opstati.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (47, 12, 26, 'Ako Sotona Sotonu izgoni, u sebi je razdijeljen. Kako će dakle opstati kraljevstvo njegovo?');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (47, 12, 27, 'I ako ja po Beelzebulu izgonim đavle, po kome ih sinovi vaši izgone? Zato će vam oni biti suci.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (47, 12, 28, 'Ali ako ja po Duhu Božjem izgonim đavle, zbilja je došlo k vama kraljevstvo Božje.\"');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (47, 12, 29, '\"Ili kako bi tko mogao ući u kuću jakoga i oplijeniti mu pokućstvo ako prije ne sveže jakoga? Tada će mu kuću oplijeniti.\"');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (47, 12, 30, '\"Tko nije sa mnom, protiv mene je, i tko ne sabire sa mnom, rasipa.\"');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (47, 12, 31, '\"Zato kažem vam: svaki će se grijeh i bogohulstvo oprostiti ljudima, ali rekne li tko bogohulstvo protiv Duha, neće se oprostiti.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (47, 12, 32, 'I rekne li tko riječ protiv Sina Čovječjega, oprostit će mu se. Ali tko rekne protiv Duha Svetoga, neće mu se oprostiti ni na ovom svijetu ni u budućem.\"');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (47, 12, 33, '\"Ili uzmite: dobro stablo i plod mu je dobar. Ili uzmite: trulo stablo i plod mu je truo. Ta po plodu se stablo poznaje.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (47, 12, 34, 'Leglo gujinje! Kako možete govoriti dobro kad ste opaki. Ta iz obilja srca usta govore!');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (47, 12, 35, 'Dobar čovjek iz riznice dobre vadi dobro, a zao čovjek iz riznice zle vadi zlo.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (47, 12, 36, 'A kažem vam: za svaku bezrazložnu riječ koju ljudi reknu dat će račun na Dan sudnji.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (47, 12, 37, 'Doista, tvoje će te riječi opravdati i tvoje će te riječi osuditi.\"');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (47, 12, 38, 'Jednom zapodjenuše s njime razgovor neki pismoznanci i farizeji: \"Učitelju, htjeli bismo od tebe vidjeti znak.\"');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (47, 12, 39, 'A on im odgovori: \"Naraštaj opak i preljubnički znak traži, ali mu se znak neće dati doli znak Jone proroka.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (47, 12, 40, 'Doista, kao što Jona bijaše u utrobi kitovoj tri dana i tri noći, tako će i Sin Čovječji biti u srcu zemlje tri dana i tri noći.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (47, 12, 41, 'Ninivljani će ustati na Sudu zajedno s ovim naraštajem i osuditi ga jer se oni na propovijed Joninu obratiše, a evo, ovdje je i više od Jone!');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (47, 12, 42, 'Kraljica će Juga ustati na Sudu zajedno s ovim naraštajem i osuditi ga jer je s krajeva zemlje došla čuti mudrost Salomonovu, a evo, ovdje je i više od Salomona!\"');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (47, 12, 43, '\"A kad nečisti duh iziđe iz čovjeka, luta bezvodnim mjestima tražeći spokoja, ali ne nalazi!');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (47, 12, 44, 'Tada rekne: \'Vratit ću se u kuću odakle iziđoh.\' I došavši, nađe je praznu, pometenu i uređenu.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (47, 12, 45, 'Tada ode i uzme sa sobom sedam drugih duhova, gorih od sebe, te uđu i nastane se ondje. Na kraju bude s onim čovjekom gore nego na početku. Tako će biti i s ovim opakim naraštajem.\"');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (47, 12, 46, 'Dok on još govoraše mnoštvu, eto majke i braće njegove. Stajahu vani tražeći da s njime govore.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (47, 12, 47, 'Reče mu netko: \"Evo majke tvoje i braće tvoje, vani stoje i traže da s tobom govore.\"');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (47, 12, 48, 'Tomu koji mu to javi on odgovori: \"Tko je majka moja, tko li braća moja?\"');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (47, 12, 49, 'I pruži ruku prema učenicima: \"Evo, reče, majke moje i braće moje!');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (47, 12, 50, 'Doista, tko god vrši volju Oca mojega, koji je na nebesima, taj mi je brat i sestra i majka.\"');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (47, 13, 1, 'Onoga dana Isus iziđe iz kuće i sjede uz more.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (47, 13, 2, 'I nagrnu k njemu silan svijet te je morao ući u lađu: sjede, a sve ono mnoštvo stajaše na obali.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (47, 13, 3, 'I zborio im je mnogo u prispodobama: \"Gle, iziđe sijač sijati.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (47, 13, 4, 'I dok je sijao, nešto zrnja pade uz put, dođoše ptice i pozobaše ga.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (47, 13, 5, 'Nešto opet pade na kamenito tlo, gdje nemaše dosta zemlje, i odmah izniknu jer nemaše duboke zemlje.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (47, 13, 6, 'A kad sunce ogranu, izgorje i jer nemaše korijena, osuši se.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (47, 13, 7, 'Nešto opet pade u trnje, trnje uzraste i uguši ga.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (47, 13, 8, 'Nešto napokon pade na dobru zemlju i davaše plod: jedno stostruk, drugo šezdesetostruk, treće tridesetostruk.\"');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (47, 13, 9, '\"Tko ima uši, neka čuje!\"');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (47, 13, 10, 'I pristupe učenici pa ga zapitaju: \"Zašto im zboriš u prispodobama?\"');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (47, 13, 11, 'On im odgovori: \"Zato što je vama dano znati otajstva kraljevstva nebeskoga, a njima nije dano.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (47, 13, 12, 'Doista, onomu tko ima dat će se i obilovat će, a onomu tko nema oduzet će se i ono što ima.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (47, 13, 13, 'U prispodobama im zborim zato što gledajući ne vide i slušajući ne čuju i ne razumiju.\"');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (47, 13, 14, '\"Tako se ispunja na njima proroštvo Izaijino koje govori: Slušat ćete, slušati - i nećete razumjeti; gledat ćete, gledati - i nećete vidjeti!');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (47, 13, 15, 'Jer usalilo se srce naroda ovoga: uši začepiše, oči zatvoriše da očima ne vide, ušima ne čuju, srcem ne razumiju te se ne obrate pa ih izliječim.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (47, 13, 16, 'A blago vašim očima što vide, i ušima što slušaju.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (47, 13, 17, 'Zaista, kažem vam, mnogi su proroci i pravednici željeli vidjeti što vi gledate, ali nisu vidjeli; i čuti što vi slušate, ali nisu čuli.\"');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (47, 13, 18, '\"Vi, dakle, poslušajte prispodobu o sijaču.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (47, 13, 19, 'Svakomu koji sluša Riječ o Kraljevstvu, a ne razumije, dolazi Zli te otima što mu je u srcu posijano. To je onaj uz put zasijan.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (47, 13, 20, 'A zasijani na tlo kamenito - to je onaj koji čuje Riječ i odmah je s radošću prima,');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (47, 13, 21, 'ali nema u sebi korijena, nego je nestalan: kad zbog Riječi nastane nevolja ili progonstvo, odmah se pokoleba.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (47, 13, 22, 'Zasijani u trnje - to je onaj koji sluša Riječ, ali briga vremenita i zavodljivost bogatstva uguše Riječ, te ona ostane bez ploda.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (47, 13, 23, 'Zasijani na dobru zemlju - to je onaj koji Riječ sluša i razumije, pa onda, dakako, urodi i daje: jedan stostruko, jedan šezdesetostruko, a jedan tridesetostruko.\"');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (47, 13, 24, 'Drugu im prispodobu iznese: \"Kraljevstvo je nebesko kao kad čovjek posije dobro sjeme na svojoj njivi.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (47, 13, 25, 'Dok su njegovi ljudi spavali, dođe njegov neprijatelj, posije posred žita kukolj i ode.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (47, 13, 26, 'Kad usjev uzraste i isklasa, tada se pokaza i kukolj.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (47, 13, 27, 'Sluge pristupe domaćinu pa mu reknu: \'Gospodaru, nisi li ti dobro sjeme posijao na svojoj njivi? Odakle onda kukolj?\'');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (47, 13, 28, 'On im odgovori: \'Neprijatelj čovjek to učini.\' Nato mu sluge kažu: \'Hoćeš li, dakle, da odemo pa da ga pokupimo?\'');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (47, 13, 29, 'A on reče: \'Ne! Da ne biste sabirući kukolj iščupali zajedno s njim i pšenicu.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (47, 13, 30, 'Pustite nek oboje raste do žetve. U vrijeme žetve reći ću žeteocima: Pokupite najprije kukolj i svežite ga u snopove da se spali, a žito skupite u moju žitnicu.\'\"');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (47, 13, 31, 'I drugu im prispodobu iznese: \"Kraljevstvo je nebesko kao kad čovjek uze gorušičino zrno i posija ga na svojoj njivi.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (47, 13, 32, 'Ono je doduše najmanje od svega sjemenja, ali kad uzraste, veće je od svega povrća. Razvije se u stablo te dolaze ptice nebeske i gnijezde mu se po granama.\"');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (47, 13, 33, 'I drugu im kaza prispodobu: \"Kraljevstvo je nebesko kao kad žena uze kvasac i zamijesi ga u tri mjere brašna dok sve ne uskisne.\"');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (47, 13, 34, 'Sve je to Isus mnoštvu zborio u prispodobama. I ništa im nije zborio bez prispodoba -');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (47, 13, 35, 'da se ispuni što je rečeno po proroku: Otvorit ću u prispodobama usta svoja, iznijet ću što je sakriveno od postanka svijeta.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (47, 13, 36, 'Tada otpusti mnoštvo i uđe u kuću. Pristupe mu učenici govoreći: \"Razjasni nam prispodobu o kukolju na njivi.\"');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (47, 13, 37, 'On odgovori: \"Sijač dobroga sjemena jest Sin Čovječji.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (47, 13, 38, 'Njiva je svijet. Dobro sjeme sinovi su Kraljevstva, a kukolj sinovi Zloga.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (47, 13, 39, 'Neprijatelj koji ga posija jest đavao. Žetva je svršetak svijeta, a žeteoci anđeli.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (47, 13, 40, 'Kao što se kukolj sabire i ognjem sažiže, tako će biti na svršetku svijeta.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (47, 13, 41, 'Sin će Čovječji poslati svoje anđele da pokupe iz njegova kraljevstva sve zavodnike i bezakonike');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (47, 13, 42, 'i bace ih u peć ognjenu, gdje će biti plač i škrgut zubi.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (47, 13, 43, 'Tada će pravednici zasjati poput sunca u kraljevstvu Oca svojega.\" \"Tko ima uši, neka čuje!\"');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (47, 13, 44, '\"Kraljevstvo je nebesko kao kad je blago skriveno na njivi: čovjek ga pronađe, sakrije, sav radostan ode, proda sve što ima i kupi tu njivu.\"');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (47, 13, 45, '\"Nadalje, kraljevstvo je nebesko kao kad trgovac traga za lijepim biserjem:');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (47, 13, 46, 'pronađe jedan dragocjeni biser, ode, rasproda sve što ima i kupi ga.\"');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (47, 13, 47, '\"Nadalje, kraljevstvo je nebesko kao kad mreža bačena u more zahvati svakovrsne ribe.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (47, 13, 48, 'Kad se napuni, izvuku je na obalu, sjednu i skupe dobre u posude, a loše izbace.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (47, 13, 49, 'Tako će biti na svršetku svijeta. Izići će anđeli, odijeliti zle od pravednih');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (47, 13, 50, 'i baciti ih u peć ognjenu, gdje će biti plač i škrgut zubi.\"');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (47, 13, 51, '\"Jeste li sve ovo razumjeli?\" Odgovore mu: \"Jesmo.\"');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (47, 13, 52, 'A on će im: \"Stoga svaki pismoznanac upućen u kraljevstvo nebesko sličan je čovjeku domaćinu koji iz svoje riznice iznosi novo i staro.\"');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (47, 13, 53, 'Kad Isus završi sve ove prispodobe, ode odande.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (47, 13, 54, 'I dođe u svoj zavičaj. Naučavaše ih u njihovoj sinagogi te zapanjeni govorahu: \"Odakle ovomu ta mudrost i te čudesne sile?');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (47, 13, 55, 'Nije li ovo drvodjeljin sin? Nije li mu majka Marija, a braća Jakov, i Josip, i Šimun, i Juda?');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (47, 13, 56, 'I sestre mu nisu li sve među nama? Odakle mu sve to?\"');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (47, 13, 57, 'I sablažnjavahu se o njega. A Isus im reče: \"Nije prorok bez časti doli u svom zavičaju i u svom domu.\"');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (47, 13, 58, 'I ne učini ondje mnogo čudesa zbog njihove nevjere.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (47, 14, 1, 'U ono vrijeme doču Herod tetrarh za Isusa');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (47, 14, 2, 'pa reče svojim slugama: \"To je Ivan Krstitelj! On uskrsnu od mrtvih i zato čudesne sile djeluju u njemu.\"');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (47, 14, 3, 'Herod doista bijaše uhitio Ivana te ga svezana bacio u tamnicu zbog Herodijade, žene brata svoga Filipa.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (47, 14, 4, 'Jer Ivan mu govoraše: \"Ne smiješ je imati!\"');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (47, 14, 5, 'Htjede ga ubiti, ali se bojao naroda jer su ga smatrali prorokom.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (47, 14, 6, 'Na Herodov rođendan zaplesa kći Herodijadina pred svima i svidje se Herodu.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (47, 14, 7, 'Zato se zakle dati joj što god zaište.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (47, 14, 8, 'A ona nagovorena od matere: \"Daj mi, reče, ovdje na pladnju glavu Ivana Krstitelja.\"');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (47, 14, 9, 'Ražalosti se kralj, ali zbog zakletve i sustolnika zapovjedi da se dade.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (47, 14, 10, 'Posla odrubiti glavu Ivanu u tamnici.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (47, 14, 11, 'I doniješe glavu njegovu na pladnju, dadoše djevojci, a ona je odnije materi.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (47, 14, 12, 'A učenici njegovi dođu, uzmu njegovo tijelo i pokopaju ga pa odu i jave Isusu.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (47, 14, 13, 'Kad je Isus to čuo, povuče se odande lađom na samotno mjesto, u osamu. Dočuo to narod pa pohrli pješice za njim iz gradova.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (47, 14, 14, 'Kad on iziđe, vidje silan svijet, sažali mu se nad njim te izliječi njegove bolesnike.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (47, 14, 15, 'Uvečer mu pristupe učenici pa mu reknu: \"Pust je ovo kraj i već je kasno. Otpusti dakle svijet: neka odu po selima kupiti hrane.\"');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (47, 14, 16, 'A Isus im reče: \"Ne treba da idu, dajte im vi jesti.\"');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (47, 14, 17, 'Oni mu kažu: \"Nemamo ovdje ništa osim pet kruhova i dvije ribe.\"');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (47, 14, 18, 'A on će im: \"Donesite mi ih ovamo.\"');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (47, 14, 19, 'I zapovjedi da mnoštvo posjeda po travi. On uze pet kruhova i dvije ribe, pogleda na nebo, izreče blagoslov pa razlomi i dade kruhove učenicima, a učenici mnoštvu.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (47, 14, 20, 'I jeli su svi i nasitili se. Od preteklih ulomaka nakupiše dvanaest punih košara.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (47, 14, 21, 'A blagovalo je oko pet tisuća muškaraca, osim žena i djece.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (47, 14, 22, 'I odmah prisili učenike da uđu u lađu i da se prebace prijeko dok on otpusti mnoštvo.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (47, 14, 23, 'A pošto otpusti mnoštvo, uziđe na goru, nasamo, da se pomoli. Uvečer bijaše ondje sam.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (47, 14, 24, 'Lađa se već mnogo stadija bila ostisla od kraja, šibana valovima. Bijaše protivan vjetar.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (47, 14, 25, 'O četvrtoj noćnoj straži dođe on k njima hodeći po moru.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (47, 14, 26, 'A učenici ugledavši ga kako hodi po moru, prestrašeni rekoše: \"Utvara!\" I od straha kriknuše.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (47, 14, 27, 'Isus im odmah progovori: \"Hrabro samo! Ja sam! Ne bojte se!\"');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (47, 14, 28, 'Petar prihvati i reče: \"Gospodine, ako si ti, zapovjedi mi da dođem k tebi po vodi!\"');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (47, 14, 29, 'A on mu reče: \"Dođi!\" I Petar siđe s lađe te, hodeći po vodi, pođe k Isusu.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (47, 14, 30, 'Ali kad spazi vjetar, poplaši se, počne tonuti te krikne: \"Gospodine, spasi me!\"');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (47, 14, 31, 'Isus odmah pruži ruku, dohvati ga i kaže mu: \"Malovjerni, zašto si posumnjao?\"');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (47, 14, 32, 'Kad uđoše u lađu, utihnu vjetar.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (47, 14, 33, 'A oni na lađi poklone mu se ničice govoreći: \"Uistinu, ti si Sin Božji!\"');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (47, 14, 34, 'Pošto preploviše, dođu na kraj, u Genezaret.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (47, 14, 35, 'I ljudi ga onoga kraja prepoznaju pa razglase po svoj onoj okolici. I donošahu mu sve bolesnike');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (47, 14, 36, 'te ga moljahu da se samo dotaknu skuta njegove haljine. I koji bi se dotakli, ozdravili bi.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (47, 15, 1, 'Tada pristupe Isusu farizeji i pismoznanci iz Jeruzalema govoreći:');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (47, 15, 2, '\"Zašto tvoji učenici prestupaju predaju starih? Ne umivaju ruku prije jela!\"');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (47, 15, 3, 'On im odgovori: \"A zašto vi prestupate zapovijed Božju radi svoje predaje?');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (47, 15, 4, 'Ta reče Bog: Poštuj oca i majku! I: Tko prokune oca ili majku, smrću neka se kazni!');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (47, 15, 5, 'A vi velite: \'Rekne li tko ocu ili majci: Pomoć koja te od mene ide neka bude sveti dar,');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (47, 15, 6, 'ne treba da poštuje oca svoga ni majku svoju.\' Tako dokinuste riječ Božju radi svoje predaje.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (47, 15, 7, 'Licemjeri, dobro prorokova o vama Izaija:');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (47, 15, 8, 'Narod me ovaj usnama časti, a srce mu je daleko od mene.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (47, 15, 9, 'Uzalud me štuju naučavajući nauke - uredbe ljudske.\"');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (47, 15, 10, 'Tada dozove mnoštvo i reče: \"Slušajte i razumijte!');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (47, 15, 11, 'Ne onečišćuje čovjeka što ulazi u usta, nego što iz usta izlazi - to čovjeka onečišćuje.\"');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (47, 15, 12, 'Tada pristupe k njemu učenici i kažu mu: \"Znaš li da su se farizeji sablaznili kad su čuli tu riječ?\"');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (47, 15, 13, 'On im odgovori: \"Svaki nasad koji ne posadi Otac moj nebeski iskorijenit će se.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (47, 15, 14, 'Pustite ih! Slijepi su, vođe slijepaca! A ako slijepac slijepca vodi, obojica će u jamu pasti.\"');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (47, 15, 15, 'Petar prihvati i reče mu: \"Protumači nam tu prispodobu!\"');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (47, 15, 16, 'A on reče: \"I vi još uvijek ne razumijete?');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (47, 15, 17, 'Ne shvaćate li: sve što ulazi na usta, ide u trbuh te se izbacuje u zahod.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (47, 15, 18, 'Naprotiv, što iz usta izlazi, iz srca izvire i to onečišćuje čovjeka.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (47, 15, 19, 'Ta iz srca izviru opake namisli, ubojstva, preljubi, bludništva, krađe, lažna svjedočanstva, psovke.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (47, 15, 20, 'To onečišćuje čovjeka; a jesti neopranih ruku ne onečišćuje čovjeka.\"');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (47, 15, 21, 'Isus zatim ode odande i povuče se u krajeve tirske i sidonske.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (47, 15, 22, 'I gle: žena neka, Kanaanka iz onih krajeva, iziđe vičući: \"Smiluj mi se, Gospodine, Sine Davidov! Kći mi je teško opsjednuta!\"');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (47, 15, 23, 'Ali on joj ne uzvrati ni riječi. Pristupe mu na to učenici te ga moljahu: \"Udovolji joj jer viče za nama.\"');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (47, 15, 24, 'On odgovori: \"Poslan sam samo k izgubljenim ovcama doma Izraelova.\"');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (47, 15, 25, 'Ali ona priđe, pokloni mu se ničice i kaže: \"Gospodine, pomozi mi!\"');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (47, 15, 26, 'On odgovori: \"Ne priliči uzeti kruh djeci i baciti ga psićima.\"');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (47, 15, 27, 'A ona će: \"Da, Gospodine! Ali psići jedu od mrvica što padaju sa stola njihovih gospodara!\"');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (47, 15, 28, 'Tada joj Isus reče: \"O ženo! Velika je vjera tvoja! Neka ti bude kako želiš.\" I ozdravi joj kći toga časa.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (47, 15, 29, 'Otišavši odande, dođe Isus do Galilejskog mora, uziđe na goru i sjede ondje.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (47, 15, 30, 'Tada nagrnu k njemu silan svijet s hromima, kljastima, slijepima, nijemima i mnogima drugima. Polože mu ih do nogu, a on ih izliječi.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (47, 15, 31, 'Gledajući kako su nijemi progovorili, kljasti ozdravili, hromi prohodali, slijepi progledali, divilo se mnoštvo i slavilo Boga Izraelova.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (47, 15, 32, 'A Isus dozva svoje učenike pa im reče: \"Žao mi je naroda jer su već tri dana uza me, a nemaju što jesti. Otpraviti ih gladne neću da ne klonu putem.\"');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (47, 15, 33, 'Kažu mu učenici: \"Odakle nam u pustinji toliko kruha da nahranimo toliko mnoštvo?\"');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (47, 15, 34, 'A Isus im reče: \"Koliko kruhova imate?\" Oni će: \"Sedam, i malo riba.\"');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (47, 15, 35, 'Nato zapovjedi mnoštvu da posjeda po zemlji,');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (47, 15, 36, 'uze sedam kruhova i ribe, zahvali, razlomi i davaše učenicima, a učenici mnoštvu.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (47, 15, 37, 'I jeli su i nasitili se. A od preteklih ulomaka nakupiše sedam punih košara.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (47, 15, 38, 'A blagovalo je četiri tisuće muškaraca, osim žena i djece.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (47, 15, 39, 'Tada otpusti mnoštvo, uđe u lađu i ode u kraj magadanski.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (47, 16, 1, 'Pristupe k njemu farizeji i saduceji. Iskušavajući ga, zatraže da im pokaže kakav znak s neba.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (47, 16, 2, 'On im odgovori: \"Uvečer govorite: \'Bit će vedro, nebo se žari.\'');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (47, 16, 3, 'A ujutro: \'Danas će nevrijeme, nebo se tamno zacrvenjelo.\' Lice neba znadete rasuditi, a znakove vremena ne znate.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (47, 16, 4, 'Naraštaj opak i preljubnički znak traži, ali mu se znak neće dati doli znak Jonin.\" Tada ih ostavi i ode.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (47, 16, 5, 'Učenici dođoše prijeko, a zaboraviše ponijeti kruha.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (47, 16, 6, 'A Isus im reče: \"Pazite, čuvajte se kvasca farizejskog i saducejskog!\"');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (47, 16, 7, 'Oni zamišljeni među sobom govorahu: \"Kruha ne ponijesmo.\"');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (47, 16, 8, 'Zamijetio to Isus pa reče: \"Što ste zamišljeni, malovjerni, da kruha nemate?');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (47, 16, 9, 'Zar još ne shvaćate, ne sjećate li se onih pet kruhova na pet tisuća i koliko košara nakupiste?');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (47, 16, 10, 'I onih sedam kruhova na četiri tisuće i koliko košara nakupiste?');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (47, 16, 11, 'Kako onda ne shvaćate da vam to ne rekoh o kruhu? Nego, čuvajte se kvasca farizejskog i saducejskog.\"');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (47, 16, 12, 'Tada razumješe kako im ne reče da se čuvaju kvasca krušnoga, nego nauka farizejskog i saducejskoga.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (47, 16, 13, 'Kad Isus dođe u krajeve Cezareje Filipove, upita učenike: \"Što govore ljudi, tko je Sin Čovječji?\"');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (47, 16, 14, 'Oni rekoše: \"Jedni da je Ivan Krstitelj; drugi da je Ilija; treći opet da je Jeremija ili koji od proroka.\"');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (47, 16, 15, 'Kaže im: \"A vi, što vi kažete, tko sam ja?\"');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (47, 16, 16, 'Šimun Petar prihvati i reče: \"Ti si Krist-Pomazanik, Sin Boga živoga.\"');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (47, 16, 17, 'Nato Isus reče njemu: \"Blago tebi, Šimune, sine Jonin, jer ti to ne objavi tijelo i krv, nego Otac moj, koji je na nebesima.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (47, 16, 18, 'A ja tebi kažem: Ti si Petar-Stijena i na toj stijeni sagradit ću Crkvu svoju i vrata paklena neće je nadvladati.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (47, 16, 19, 'Tebi ću dati ključeve kraljevstva nebeskoga, pa što god svežeš na zemlji, bit će svezano na nebesima; a što god odriješiš na zemlji, bit će odriješeno na nebesima.\"');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (47, 16, 20, 'Tada zaprijeti učenicima neka nikomu ne reknu da je on Krist.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (47, 16, 21, 'Otada poče Isus upućivati učenike kako treba da pođe u Jeruzalem, da mnogo pretrpi od starješina, glavara svećeničkih i pismoznanaca, da bude ubijen i treći dan da uskrsne.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (47, 16, 22, 'Petar ga uze na stranu i poče odvraćati: \"Bože sačuvaj, Gospodine! Ne, to se tebi ne smije dogoditi!\"');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (47, 16, 23, 'Isus se okrene i reče Petru: \"Nosi se od mene, sotono! Sablazan si mi jer ti nije na pameti što je Božje, nego što je ljudsko!\"');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (47, 16, 24, 'Tada Isus reče svojim učenicima: \"Hoće li tko za mnom, neka se odrekne samoga sebe, neka uzme svoj križ i neka ide za mnom.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (47, 16, 25, 'Tko hoće život svoj spasiti, izgubit će ga, a tko izgubi život svoj poradi mena, naći će ga.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (47, 16, 26, 'Ta što će koristiti čovjeku ako sav svijet stekne, a životu svojemu naudi? Ili što će čovjek dati u zamjenu za život svoj?');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (47, 16, 27, 'Doći će, doista, Sin Čovječji u slavi Oca svoga s anđelima svojim i tada će naplatiti svakomu po djelima njegovim.\"');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (47, 16, 28, '\"Zaista, kažem vam, neki od ovdje nazočnih neće okusiti smrti dok ne vide Sina Čovječjega gdje dolazi sa svojim kraljevstvom.\"');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (47, 17, 1, 'Nakon šest dana uze Isus sa sobom Petra, Jakova i Ivana, brata njegova, te ih povede na goru visoku, u osamu,');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (47, 17, 2, 'i preobrazi se pred njima. I zasja mu lice kao sunce, a haljine mu postadoše bijele kao svjetlost.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (47, 17, 3, 'I gle: ukazaše im se Mojsije i Ilija te razgovarahu s njime.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (47, 17, 4, 'A Petar prihvati i reče Isusu: \"Gospodine, dobro nam je ovdje biti. Ako hoćeš, načinit ću ovdje tri sjenice, tebi jednu, Mojsiju jednu i Iliji jednu.\"');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (47, 17, 5, 'Dok je on još govorio, gle, svijetao ih oblak zasjeni, a glas iz oblaka govoraše: \"Ovo je Sin moj, Ljubljeni! U njemu mi sva milina! Slušajte ga!\"');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (47, 17, 6, 'Čuvši glas, učenici padoše licem na zemlju i silno se prestrašiše.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (47, 17, 7, 'Pristupi k njima Isus, dotakne ih i reče: \"Ustanite, ne bojte se!\"');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (47, 17, 8, 'Podigoše oči, ali ne vidješe nikoga doli Isusa sama.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (47, 17, 9, 'Dok su silazili s gore, zapovjedi im Isus: \"Nikomu ne kazujte viđenje dok Sin Čovječji od mrtvih ne uskrsne.\"');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (47, 17, 10, 'Upitaše ga učenici: \"Što dakle pismoznanci govore da prije treba da dođe Ilija?\"');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (47, 17, 11, 'On im odgovori: \"Ilija će doduše doći i sve obnoviti.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (47, 17, 12, 'No velim vam: Ilija je već došao, ali ga ne upoznaše, već učiniše s njim što im se prohtjelo. Tako je i Sinu Čovječjemu trpjeti od njih.\"');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (47, 17, 13, 'Tada razumješe učenici da im to reče o Ivanu Krstitelju.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (47, 17, 14, 'Kada dođoše k mnoštvu, pristupi mu čovjek, padne pred njim na koljena');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (47, 17, 15, 'i reče: \"Gospodine, smiluj se sinu mojemu jer je mjesečar i zlo mu je. Često doista pada u oganj i često u vodu.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (47, 17, 16, 'Dovedoh ga tvojim učenicima i ne mogoše ga izliječiti.\"');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (47, 17, 17, 'A Isus odgovori: \"O rode nevjerni i opaki! Dokle mi je biti s vama! Dokle li vas podnositi! Dovedite mi ga ovamo!\"');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (47, 17, 18, 'I zaprijeti Isus zloduhu te on iziđe iz njega. I ozdravi dječak toga časa.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (47, 17, 19, 'Tada učenici pristupiše nasamo k Isusu i rekoše: \"Zašto ga mi ne mogosmo izagnati?\"');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (47, 17, 20, 'Kaže im: \"Zbog vaše malovjernosti. Zaista, kažem vam, ako imadnete vjere koliko je zrno gorušičino te reknete ovoj gori: \'Premjesti se odavde onamo!\', premjestit će se i ništa vam neće biti nemoguće.\"');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (47, 17, 21, '#');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (47, 17, 22, 'A kad su se skupili u Galileji, reče im Isus: \"Sin Čovječji ima biti predan ljudima u ruke');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (47, 17, 23, 'i ubit će ga, ali on će treći dan uskrsnuti.\" I ožalostiše se silno.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (47, 17, 24, 'Kad stigoše u Kafarnaum, pristupe Petru oni što ubiru dvodrahme pa mu rekoše: \"Učitelj vaš ne plaća dvodrahme?\"');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (47, 17, 25, '\"Plaća\", odgovori. A kad on uđe u kuću, pretekne ga Isus: \"Što ti se čini, Šimune? Kraljevi zemaljski od koga ubiru carinu ili porez? Od svojih sinova ili od tuđih?\"');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (47, 17, 26, 'Kad on odgovori: \"Od tuđih!\", reče mu Isus: \"Sinovi su, dakle, oslobođeni.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (47, 17, 27, 'Ali da ih ne sablaznimo, pođi k moru, baci udicu i prvu ribu koja naiđe uzmi, otvori joj usta i naći ćeš stater. Uzmi ga pa im ga podaj za me i za se.\"');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (47, 18, 1, 'U onaj čas pristupe učenici Isusu pa ga zapitaju: \"Tko je, dakle, najveći u kraljevstvu nebeskom?\"');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (47, 18, 2, 'On dozove dijete, postavi ga posred njih');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (47, 18, 3, 'i reče: \"Zaista, kažem vam, ako se ne obratite i ne postanete kao djeca, nećete ući u kraljevstvo nebesko.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (47, 18, 4, 'Tko god se dakle ponizi kao ovo dijete, taj je najveći u kraljevstvu nebeskom.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (47, 18, 5, 'I tko primi jedno ovakvo dijete u moje ime, mene prima.\"');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (47, 18, 6, '\"Onomu, naprotiv, tko bi sablaznio jednoga od ovih najmanjih što vjeruju u mene bilo bi bolje da mu se o vrat objesi mlinski kamen pa da potone u dubinu morsku.\"');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (47, 18, 7, '\"Jao svijetu od sablazni! Neizbježivo dolaze sablazni, ali jao čovjeku po kom dolazi sablazan.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (47, 18, 8, 'Pa ako te ruka ili noga sablažnjava, odsijeci je i baci od sebe. Bolje ti je ući u život kljastu ili hromu, nego s obje ruke ili s obje noge biti bačen u oganj vječni.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (47, 18, 9, 'I ako te oko sablažnjava, izvadi ga i baci od sebe. Bolje ti je jednooku u život ući, nego s oba oka biti bačen u pakao ognjeni.\"');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (47, 18, 10, '\"Pazite da ne prezrete ni jednoga od ovih najmanjih jer, kažem vam, anđeli njihovi na nebu uvijek gledaju lice Oca mojega, koji je na nebesima.\"');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (47, 18, 11, '#');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (47, 18, 12, '\"Što vam se čini? Ako neki čovjek imadne sto ovaca i jedna od njih zaluta, neće li on ostaviti onih devedeset i devet u gorama i poći u potragu za zalutalom?');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (47, 18, 13, 'Posreći li mu se te je nađe, zaista, kažem vam, raduje se zbog nje više nego zbog onih devedeset i devet koje nisu zalutale.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (47, 18, 14, 'Tako ni Otac vaš, koji je na nebesima, neće da propadne ni jedan od ovih malenih.\"');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (47, 18, 15, '\"Pogriješi li tvoj brat, idi i pokaraj ga nasamo.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (47, 18, 16, 'Ako te posluša, stekao si brata. Ne posluša li te, uzmi sa sobom još jednoga ili dvojicu, neka na iskazu dvojice ili trojice svjedoka počiva svaka tvrdnja.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (47, 18, 17, 'Ako ni njih ne posluša, reci Crkvi. Ako pak ni Crkve ne posluša, neka ti bude kao poganin i carinik.\"');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (47, 18, 18, '\"Zaista, kažem vam, što god svežete na zemlji, bit će svezano na nebu; i što god odriješite na zemlji, bit će odriješeno na nebu.\"');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (47, 18, 19, '\"Nadalje, kažem vam, ako dvojica od vas na zemlji jednodušno zaištu što mu drago, dat će im Otac moj, koji je na nebesima.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (47, 18, 20, 'Jer gdje su dvojica ili trojica sabrana u moje ime, tu sam i ja među njima.\"');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (47, 18, 21, 'Tada pristupi k njemu Petar i reče: \"Gospodine, koliko puta da oprostim bratu svomu ako se ogriješi o mene? Do sedam puta?\"');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (47, 18, 22, 'Kaže mu Isus: \"Ne kažem ti do sedam puta, nego do sedamdeset puta sedam.\"');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (47, 18, 23, '\"Stoga je kraljevstvo nebesko kao kad kralj odluči urediti račune sa slugama.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (47, 18, 24, 'Kad započe obračunavati, dovedoše mu jednoga koji mu dugovaše deset tisuća talenata.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (47, 18, 25, 'Kako nije imao odakle vratiti, zapovjedi gospodar da se proda on, žena mu i djeca i sve što ima te se podmiri dug.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (47, 18, 26, 'Nato sluga padne ničice preda nj govoreći: \'Strpljenja imaj sa mnom, i sve ću ti vratiti.\'');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (47, 18, 27, 'Gospodar se smilova tomu sluzi, otpusti ga i dug mu oprosti.\"');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (47, 18, 28, '\"A kad taj isti sluga izađe, naiđe na jednoga svoga druga koji mu dugovaše sto denara. Uhvati ga i stane ga daviti govoreći: \'Vrati što si dužan!\'');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (47, 18, 29, 'Drug padne preda nj i stane ga zaklinjati: \'Strpljenja imaj sa mnom i vratit ću ti.\'');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (47, 18, 30, 'Ali on ne htjede, nego ode i baci ga u tamnicu dok mu ne vrati duga.\"');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (47, 18, 31, '\"Kad njegovi drugovi vidješe što se dogodilo, silno ražalošćeni odoše i sve to dojaviše gospodaru.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (47, 18, 32, 'Tada ga gospodar dozva i reče mu: \'Slugo opaki, sav sam ti onaj dug oprostio jer si me zamolio.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (47, 18, 33, 'Nije li trebalo da se i ti smiluješ svome drugu, kao što sam se i ja tebi smilovao?\'');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (47, 18, 34, 'I gospodar ga, rasrđen, preda mučiteljima dok mu ne vrati svega duga.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (47, 18, 35, 'Tako će i Otac moj nebeski učiniti s vama ako svatko od srca ne oprosti svomu bratu.\"');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (47, 19, 1, 'Kad Isus završi ove besjede, ode iz Galileje i dođe u judejski kraj s onu stranu Jordana.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (47, 19, 2, 'Za njim je išao silan svijet. Ondje ih izliječi.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (47, 19, 3, 'Pristupe mu tada farizeji pa, da ga iskušaju, kažu: \"Je li dopušteno otpustiti ženu s kojega god razloga?\"');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (47, 19, 4, 'On odgovori: \"Zar niste čitali: Stvoritelj od početka muško i žensko stvori ih');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (47, 19, 5, 'i reče: Stoga će čovjek ostaviti oca i majku da prione uza svoju ženu; i dvoje njih bit će jedno tijelo?');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (47, 19, 6, 'Tako više nisu dvoje, nego jedno tijelo. Što, dakle, Bog združi, čovjek neka ne rastavlja.\"');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (47, 19, 7, 'Kažu mu: \"Zašto onda Mojsije zapovjedi dati otpusno pismo i - otpustiti?\"');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (47, 19, 8, 'Odgovori im: \"Zbog tvrdoće srca vašega dopusti vam Mojsije otpustiti žene, ali od početka ne bijaše tako.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (47, 19, 9, 'A ja vam kažem: Tko otpusti svoju ženu - osim zbog bludništva - pa se oženi drugom, čini preljub.\"');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (47, 19, 10, 'Kažu mu učenici: \"Ako je tako između muža i žene, bolje je ne ženiti se.\"');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (47, 19, 11, 'A on im reče: \"Ne shvaćaju toga svi, nego samo oni kojima je dano.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (47, 19, 12, 'Doista, ima za ženidbu nesposobnih koji se takvi iz utrobe materine rodiše. Ima nesposobnih koje ljudi onesposobiše. A ima nesposobnih koji sami sebe onesposobiše poradi kraljevstva nebeskoga. Tko može shvatiti, neka shvati.\"');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (47, 19, 13, 'Tada mu doniješe dječicu da na njih stavi ruke i pomoli se. A učenici im branili.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (47, 19, 14, 'Nato će im Isus: \"Pustite dječicu i ne priječite im k meni jer takvih je kraljevstvo nebesko!\"');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (47, 19, 15, 'I položi ruke na njih pa krene odande.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (47, 19, 16, 'I gle, pristupi mu netko i reče: \"Učitelju, koje mi je dobro činiti da imam život vječni?\"');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (47, 19, 17, 'A on mu reče: \"Što me pitaš o dobrome? Jedan je samo dobar! Ali ako hoćeš u život ući, čuvaj zapovijedi.\"');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (47, 19, 18, 'Upita ga: \"Koje?\" A Isus reče: Ne ubij! Ne čini preljuba! Ne ukradi! Ne svjedoči lažno!');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (47, 19, 19, 'Poštuj oca i majku! I ljubi svoga bližnjega kao sebe samoga!\"');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (47, 19, 20, 'Kaže mu mladić: \"Sve sam to čuvao. Što mi još nedostaje?\"');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (47, 19, 21, 'Reče mu Isus: \"Hoćeš li biti savršen, idi, prodaj što imaš i podaj siromasima pa ćeš imati blago na nebu. A onda dođi i idi za mnom.\"');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (47, 19, 22, 'Na tu riječ ode mladić žalostan jer imaše velik imetak.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (47, 19, 23, 'A Isus reče svojim učenicima: \"Zaista, kažem vas, teško će bogataš u kraljevstvo nebesko.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (47, 19, 24, 'Ponovno vam velim: Lakše je devi kroz uši iglene nego bogatašu u kraljevstvo Božje.\"');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (47, 19, 25, 'Čuvši to, učenici se silno snebivahu govoreći: \"Tko se onda može spasiti?\"');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (47, 19, 26, 'A Isus upre u njih pogled pa im reče: \"Ljudima je to nemoguće, ali Bogu je sve moguće.\"');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (47, 19, 27, 'Tada Petar prihvati pa upita: \"Evo, mi sve ostavismo i pođosmo za tobom. Što ćemo za to dobiti?\"');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (47, 19, 28, 'Reče im Isus: \"Zaista, kažem vam, vi koji pođoste za mnom, o preporodu, kad Sin Čovječji sjedne na prijestolje svoje slave, i vi ćete sjediti na dvanaest prijestolja i suditi dvanaest plemena Izraelovih.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (47, 19, 29, 'I tko god ostavi kuće, ili braću, ili sestre, ili oca, ili majku, ili ženu, ili djecu, ili polja poradi imena mojega, stostruko će primiti i život vječni baštiniti.\"');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (47, 19, 30, '\"A mnogi prvi bit će posljednji, i posljednji prvi.\"');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (47, 20, 1, '\"Kraljevstvo je nebesko kao kad domaćin rano ujutro izađe najmiti radnike u svoj vinograd.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (47, 20, 2, 'Pogodi se s radnicima po denar na dan i pošalje ih u svoj vinograd.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (47, 20, 3, 'Izađe i o trećoj uri i vidje druge gdje stoje na trgu besposleni');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (47, 20, 4, 'pa i njima reče: \'Idite i vi u moj vinograd pa što bude pravo, dat ću vam.\'');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (47, 20, 5, 'I oni odoše. Izađe opet o šestoj i devetoj uri te učini isto tako.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (47, 20, 6, 'A kad izađe o jedanaestoj uri, nađe druge gdje stoje i reče im: \'Zašto ovdje stojite vazdan besposleni?\'');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (47, 20, 7, 'Kažu mu: \'Jer nas nitko ne najmi.\' Reče im: \'Idite i vi u vinograd.\'\"');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (47, 20, 8, '\"Uvečer kaže gospodar vinograda svojemu upravitelju: \'Pozovi radnike i podaj im plaću počevši od posljednjih pa sve do prvih.\'');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (47, 20, 9, 'Dođu tako oni od jedanaeste ure i prime po denar.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (47, 20, 10, 'Pa kada dođu oni prvi, pomisle da će primiti više, ali i oni prime po denar.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (47, 20, 11, 'A kad primiše, počeše mrmljati protiv domaćina:');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (47, 20, 12, '\'Ovi posljednji jednu su uru radili i izjednačio si ih s nama, koji smo podnosili svu tegobu dana i žegu.\'\"');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (47, 20, 13, '\"Nato on odgovori jednomu od njih: \'Prijatelju, ne činim ti krivo. Nisi li se pogodio sa mnom po denar?');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (47, 20, 14, 'Uzmi svoje pa idi. A ja hoću i ovomu posljednjemu dati kao i tebi.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (47, 20, 15, 'Nije li mi slobodno činiti sa svojim što hoću? Ili zar je oko tvoje zlo što sam ja dobar?\'\"');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (47, 20, 16, '\"Tako će posljednji biti prvi, a prvi posljednji.\"');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (47, 20, 17, 'Dok je Isus uzlazio u Jeruzalem, uze dvanaestoricu nasamo te im putem reče:');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (47, 20, 18, '\"Evo, uzlazimo u Jeruzalem i Sin Čovječji bit će predan glavarima svećeničkim i pismoznancima. Osudit će ga na smrt');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (47, 20, 19, 'i predati poganima da ga izrugaju, izbičuju i razapnu, ali on će treći dan uskrsnuti.\"');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (47, 20, 20, 'Tada mu pristupi mati sinova Zebedejevih zajedno sa sinovima, pade ničice da od njega nešto zaište.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (47, 20, 21, 'A on će joj: \"Što želiš?\" Kaže mu: \"Reci da ova moja dva sina u tvome kraljevstvu sjednu uza te, jedan tebi zdesna, drugi slijeva.\"');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (47, 20, 22, 'Isus odgovori: \"Ne znate što ištete. Možete li piti čašu koju ću ja piti?\" Kažu mu: \"Možemo!\"');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (47, 20, 23, 'A on im reče: \"Čašu ćete moju doduše piti, ali sjesti meni zdesna ili slijeva - to nisam ja vlastan dati, to je onih kojima je pripravio moj Otac.\"');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (47, 20, 24, 'Kada su to čula ostala desetorica, razgnjeve se na dva brata.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (47, 20, 25, 'Zato ih Isus dozva i reče: \"Znate da vladari gospoduju svojim narodima i velikaši njihovi drže ih pod vlašću.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (47, 20, 26, 'Neće tako biti među vama! Naprotiv, tko hoće da među vama bude najveći, neka vam bude poslužitelj.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (47, 20, 27, 'I tko god hoće da među vama bude prvi, neka vam bude sluga.\"');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (47, 20, 28, '\"Tako i Sin Čovječji nije došao da bude služen, nego da služi i život svoj dade kao otkupninu za mnoge.\"');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (47, 20, 29, 'Kad su izlazili iz Jerihona, pođe za njim silan svijet.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (47, 20, 30, 'I gle, dva slijepca sjeđahu kraj puta. Čuvši da Isus prolazi, povikaše: \"Gospodine, smiluj nam se, Sine Davidov!\"');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (47, 20, 31, 'Mnoštvo ih ušutkivalo, ali oni još jače viknuše: \"Gospodine, smiluj nam se, Sine Davidov!\"');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (47, 20, 32, 'Isus se zaustavi, dozove ih i reče: \"Što hoćete da vam učinim?\"');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (47, 20, 33, 'Kažu mu: \"Gospodine, da nam se otvore oči.\"');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (47, 20, 34, 'Isus se ganut dotače njihovim očiju i oni odmah progledaše. I pođoše za njim.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (47, 21, 1, 'Kad se približiše Jeruzalemu te dođoše u Betfagu, na Maslinskoj gori, posla Isus dvojicu učenika');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (47, 21, 2, 'govoreći: \"Pođite u selo pred vama i odmah ćete naći privezanu magaricu i uz nju magare. Odriješite ih i dovedite k meni.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (47, 21, 3, 'Ako vam tko što rekne, recite: \'Gospodinu trebaju\', i odmah će ih pustiti.\"');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (47, 21, 4, 'To se dogodi da se ispuni što je rečeno po proroku:');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (47, 21, 5, 'Recite kćeri Sionskoj: Evo kralj ti tvoj dolazi, krotak, jašuć na magarcu, na magaretu, mladetu magaričinu.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (47, 21, 6, 'Učenici odu i učine kako im naredi Isus.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (47, 21, 7, 'Dovedu magaricu i magare te stave na njih haljine i Isus uzjaha na njih.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (47, 21, 8, 'Silan svijet prostrije svoje haljine po putu, a drugi rezahu grane sa stabala i sterahu ih po putu.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (47, 21, 9, 'Mnoštvo pak pred njim i za njim klicaše: \"Hosana Sinu Davidovu! Blagoslovljen Onaj koji dolazi u ime Gospodnje! Hosana u visinama!\"');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (47, 21, 10, 'Kad uđe u Jeruzalem, uskomešao se sav grad i govorio: \"Tko je ovaj?\"');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (47, 21, 11, 'A mnoštvo odgovaraše: \"To je Prorok, Isus iz Nazareta galilejskoga.\"');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (47, 21, 12, 'Isus uđe u Hram i izagna sve koji su prodavali i kupovali u Hramu. Mjenjačima isprevrta stolove i prodavačima golubova klupe.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (47, 21, 13, 'Kaže im: \"Pisamo je: Dom će se moj zvati Dom molitve, a vi od njega činite pećinu razbojničku.\"');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (47, 21, 14, 'U Hramu mu priđoše slijepi i hromi i on ih ozdravi.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (47, 21, 15, 'A kad glavari svećenički i pismoznanci vidješe čudesa koja učini i djecu što viču Hramom: \"Hosana Sinu Davidovu!\", gnjevni');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (47, 21, 16, 'mu rekoše: \"Čuješ li što ovi govore?\" Kaže im Isus: \"Da! A niste li čitali: Iz usta djece i dojenčadi sebi si pripravio hvalu?\"');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (47, 21, 17, 'On ih ostavi, pođe iz grada u Betaniju te ondje prenoći.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (47, 21, 18, 'Ujutro se vraćao u grad i ogladnje.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (47, 21, 19, 'Ugleda smokvu kraj puta i priđe k njoj, ali ne nađe na njoj ništa osim lišća pa joj kaže: \"Ne bilo više ploda s tebe dovijeka!\" I smokva umah usahnu.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (47, 21, 20, 'Vidjevši to, učenici se začude: \"Kako umah smokva usahnu!\"');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (47, 21, 21, 'Isus im odvrati: \"Zaista, kažem vam, ako budete imali vjeru i ne posumnjate, činit ćete ne samo ovo sa smokvom, nego - reknete li i ovoj gori: \'Digni se i baci u more!\', bit će tako.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (47, 21, 22, 'I sve što zaištete u molitvi vjerujući, primit ćete.\"');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (47, 21, 23, 'I uđe u Hram. Dok je naučavao, pristupiše mu glavari svećenički i starješine narodne te ga upitaše: \"Kojom vlašću to činiš? Tko ti dade tu vlast?\"');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (47, 21, 24, 'Isus im odgovori: \"I ja ću vas jedno upitati. Ako mi na to odgovorite, ja ću vama kazati kojom vlašću ovo činim.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (47, 21, 25, 'Krst Ivanov odakle li bijaše? Od Neba ili od ljudi?\" A oni umovahu među sobom: \"Reknemo li \'Od Neba\', odvratit će nam: \'Zašto mu, dakle, ne povjerovaste?\'');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (47, 21, 26, 'A reknemo li \'Od ljudi\', strah nas je mnoštva. Ta svi Ivana smatraju prorokom.\"');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (47, 21, 27, 'Zato odgovore Isusu: \"Ne znamo.\" I on njima reče: \"Ni ja vama neću kazati kojom vlašću ovo činim.\"');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (47, 21, 28, '\"A što vam se čini? Čovjek neki imao dva sina. Priđe prvomu i reče: \'Sinko, hajde danas na posao u vinograd!\'');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (47, 21, 29, 'On odgovori: \'Neću!\' No poslije se predomisli i ode.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (47, 21, 30, 'Priđe i drugomu pa mu reče isto tako. A on odgovori: \'Evo me, gospodaru!\' i ne ode.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (47, 21, 31, 'Koji od te dvojice izvrši volju očevu?\" Kažu: \"Onaj prvi.\" Nato će im Isus: \"Zaista, kažem vam, carinici i bludnice pretekoše vas u kraljevstvo Božje!');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (47, 21, 32, 'Doista, Ivan dođe k vama putom pravednosti i vi mu ne povjerovaste, a carinici mu i bludnice povjerovaše. Vi pak, makar to vidjeste, ni kasnije se ne predomisliste da mu povjerujete.\"');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (47, 21, 33, '\"Drugu prispodobu čujte! Bijaše neki domaćin koji posadi vinograd, ogradi ga ogradom, iskopa u njemu tijesak i podiže kulu pa ga iznajmi vinogradarima i otputova.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (47, 21, 34, 'Kad se približilo vrijeme plodova, posla svoje sluge vinogradarima da uzmu njegov urod.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (47, 21, 35, 'A vinogradari pograbe njegove sluge pa jednoga istukoše, drugog ubiše, a trećega kamenovaše.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (47, 21, 36, 'I opet posla druge sluge, više njih nego prije, ali oni i s njima postupiše jednako.\"');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (47, 21, 37, '\"Naposljetku posla k njima sina svoga misleći: \'Poštovat će mog sina.\'');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (47, 21, 38, 'Ali kad vinogradari ugledaju sina, rekoše među sobom: \'Ovo je baštinik! Hajde da ga ubijemo i imat ćemo baštinu njegovu!\'');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (47, 21, 39, 'I pograbe ga, izbace iz vinograda i ubiju.\"');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (47, 21, 40, '\"Kada dakle dođe gospodar vinograda, što će učiniti s tim vinogradarima?\"');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (47, 21, 41, 'Kažu mu: \"Opake će nemilo pogubiti, a vinograd iznajmiti drugim vinogradarima što će mu davati urod u svoje vrijeme.\"');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (47, 21, 42, 'Kaže im Isus: \"Zar nikada niste čitali u Pismima: Kamen što ga odbaciše graditelji postade kamen zaglavni. Gospodnje je to djelo - kakvo čudo u očima našim!');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (47, 21, 43, 'Zato će se - kažem vam - oduzeti od vas kraljevstvo Božje i dat će se narodu koji donosi njegove plodove! (');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (47, 21, 44, 'I tko padne na taj kamen, smrskat će se, a na koga on padne, satrt će ga.)\"');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (47, 21, 45, 'Kad su glavari svećenički i farizeji čuli te njegove prispodobe, razumjeli su da govori o njima.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (47, 21, 46, 'I tražili su da ga uhvate, ali se pobojaše mnoštva jer ga je smatralo prorokom.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (47, 22, 1, 'Isus im ponovno prozbori u prispodobama:');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (47, 22, 2, '\"Kraljevstvo je nebesko kao kad neki kralj pripravi svadbu sinu svomu.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (47, 22, 3, 'Posla sluge da pozovu uzvanike na svadbu. No oni ne htjedoše doći.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (47, 22, 4, 'Opet posla druge sluge govoreći: \'Recite uzvanicima: Evo, objed sam ugotovio. Junci su moji i tovljenici poklani i sve pripravljeno. Dođite na svadbu!\'\"');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (47, 22, 5, '\"Ali oni ne mareći odoše - jedan na svoju njivu, drugi za svojom trgovinom.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (47, 22, 6, 'Ostali uhvate njegove sluge, zlostave ih i ubiju.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (47, 22, 7, 'Nato se kralj razgnjevi, posla svoju vojsku i pogubi one ubojice, a grad im spali.\"');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (47, 22, 8, '\"Tada kaže slugama: \'Svadba je, evo, pripravljena ali uzvanici ne bijahu dostojni.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (47, 22, 9, 'Pođite stoga na raskršća i koga god nađete, pozovite na svadbu!\'\"');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (47, 22, 10, '\"Sluge iziđoše na putove i sabraše sve koje nađoše - i zle i dobre. I svadbena se dvorana napuni gostiju.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (47, 22, 11, 'Kad kralj uđe pogledati goste, spazi ondje čovjeka koji ne bijaše odjeven u svadbeno ruho.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (47, 22, 12, 'Kaže mu: \'Prijatelju, kako si ovamo ušao bez svadbenoga ruha?\' A on zanijemi.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (47, 22, 13, 'Tada kralj reče poslužiteljima: \'Svežite mu ruke i noge i bacite ga van u tamu, gdje će biti plač i škrgut zubi.\'');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (47, 22, 14, 'Doista, mnogo je zvanih, malo izabranih.\"');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (47, 22, 15, 'Tada farizeji odoše i održaše vijeće kako da Isusa uhvate u riječi.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (47, 22, 16, 'Pošalju k njemu svoje učenike s herodovcima da ga upitaju: \"Učitelju! Znamo da si istinit te po istini putu Božjem učiš i ne mariš tko je tko jer nisi pristran.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (47, 22, 17, 'Reci nam, dakle, što ti se čini: je li dopušteno dati porez caru ili nije?\"');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (47, 22, 18, 'Znajući njihovu opakost, reče Isus: \"Zašto me iskušavate, licemjeri?');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (47, 22, 19, 'Pokažite mi porezni novac!\" Pružiše mu denar.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (47, 22, 20, 'On ih upita: \"Čija je ovo slika i natpis?\"');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (47, 22, 21, 'Odgovore: \"Carev.\" Kaže im: \"Podajte dakle caru carevo, a Bogu Božje.\"');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (47, 22, 22, 'Čuvši to, zadive se pa ga ostave i odu.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (47, 22, 23, 'Toga dana pristupiše k njemu saduceji, koji vele da nema uskrsnuća, i upitaše ga:');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (47, 22, 24, '\"Učitelju, Mojsije reče: Umre li tko bez djece, neka se njegov brat oženi njegovom ženom te podigne porod bratu svomu.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (47, 22, 25, 'Bijaše tako u nas sedmero braće. Prvi se oženi i umrije bez poroda ostavivši ženu svom bratu.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (47, 22, 26, 'Tako i drugi i treći, sve do sedmoga.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (47, 22, 27, 'A nakon svih umrije i žena.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (47, 22, 28, 'Kojemu će dakle od te sedmorice biti žena o uskrsnuću? Jer sva su je sedmorica imala.\"');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (47, 22, 29, 'Odgovori im Isus: \"U zabludi ste jer ne razumijete Pisama ni sile Božje.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (47, 22, 30, 'Ta u uskrsnuću niti se žene niti udavaju, nego su kao anđeli na nebu.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (47, 22, 31, 'A što se tiče uskrsnuća mrtvih, zar niste čitali što vam reče Bog:');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (47, 22, 32, 'Ja sam Bog Abrahamov, Bog Izakov i Bog Jakovljev? Nije on Bog mrtvih, nego živih!\"');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (47, 22, 33, 'Čuvši to, mnoštvo osta zaneseno njegovim naukom.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (47, 22, 34, 'A kad su farizeji čuli kako ušutka saduceje, okupiše se,');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (47, 22, 35, 'a jedan od njih, zakonoznanac, da ga iskuša, upita:');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (47, 22, 36, '\"Učitelju, koja ja zapovijed najveća u Zakonu?\"');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (47, 22, 37, 'A on mu reče: \"Ljubi Gospodina Boga svojega svim srcem svojim, i svom dušom svojom, i svim umom svojim.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (47, 22, 38, 'To je najveća i prva zapovijed.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (47, 22, 39, 'Druga, ovoj slična: Ljubi svoga bližnjega kao sebe samoga.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (47, 22, 40, 'O tim dvjema zapovijedima visi sav Zakon i Proroci.\"');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (47, 22, 41, 'Kad se farizeji skupiše, upita ih Isus:');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (47, 22, 42, '\"Što mislite o Kristu? Čiji je on sin?\" Kažu mu: \"Davidov.\"');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (47, 22, 43, 'A on će njima: \"Kako ga onda David u Duhu naziva Gospodinom, kad veli:');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (47, 22, 44, 'Reče Gospod Gospodinu mojemu: \'Sjedi mi zdesna dok ne položim neprijatelje tvoje za podnožje nogama tvojim?\'');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (47, 22, 45, 'Ako ga dakle David naziva Gospodinom, kako mu je sin?\"');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (47, 22, 46, 'I nitko mu nije mogao odgovoriti ni riječi, niti se od toga dana tko usudio upitati ga bilo što.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (47, 23, 1, 'Tada Isus prozbori mnoštvu i svojim učenicima:');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (47, 23, 2, '\"Na Mojsijevu stolicu zasjedoše pismoznanci i farizeji.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (47, 23, 3, 'Činite dakle i obdržavajte sve što vam kažu, ali se nemojte ravnati po njihovim djelima jer govore, a ne čine.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (47, 23, 4, 'Vežu i ljudima na pleća tovare teška bremena, a sami ni da bi ih prstom makli.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (47, 23, 5, 'Sva svoja djela čine zato da ih ljudi vide. Doista, proširuju zapise svoje i produljuju rese.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (47, 23, 6, 'Vole pročelja na gozbama, prva sjedala u sinagogama,');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (47, 23, 7, 'pozdrave na trgovima i da ih ljudi zovu \'Rabbi\'.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (47, 23, 8, 'Vi pak ne dajte se zvati \'Rabbi\', jer jedan je učitelj vaš, a svi ste vi braća.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (47, 23, 9, 'Ni ocem ne zovite nikoga na zemlji jer jedan je Otac vaš - onaj na nebesima.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (47, 23, 10, 'I ne dajte da vas vođama zovu, jer jedan je vaš vođa - Krist.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (47, 23, 11, 'Najveći među vama neka vam bude poslužitelj.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (47, 23, 12, 'Tko se god uzvisuje, bit će ponižen, a tko se ponizuje, bit će uzvišen.\"');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (47, 23, 13, '\"Jao vama, pismoznanci i farizeji! Licemjeri! Zaključavate kraljevstvo nebesko pred ljudima; sami ne ulazite, a ne date ući ni onima koji bi htjeli.\"');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (47, 23, 14, '#');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (47, 23, 15, '\"Jao vama, pismoznanci i farizeji! Licemjeri! Obilazite morem i kopnom da pridobijete jednog sljedbenika. A kad ga pridobijete, promećete ga u sina paklenoga dvaput goreg od sebe.\"');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (47, 23, 16, '\"Jao vama! Slijepe vođe! Govorite: \'Zakune li se tko Hramom, nije ništa. Ali ako se zakune hramskim zlatom, veže ga zakletva.\'');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (47, 23, 17, 'Budale i slijepci! Ta što je veće: zlato ili Hram što posvećuje zlato?');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (47, 23, 18, 'Nadalje: \'Zakune li se tko žrtvenikom, nije ništa. Ali ako se zakune darom što je na njemu, veže ga zakletva.\'');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (47, 23, 19, 'Slijepci! Ta što je veće: dar ili žrtvenik što dar posvećuje?');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (47, 23, 20, 'Tko se dakle zakune žrtvenikom, kune se njime i svime što je na njemu.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (47, 23, 21, 'I tko se zakune Hramom, kune se njime i Onim koji u njemu prebiva.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (47, 23, 22, 'I tko se zakune nebom, kune se prijestoljem Božjim i Onim koji na njemu sjedi.\"');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (47, 23, 23, '\"Jao vama, pismoznanci i farizeji! Licemjeri! Namirujete desetinu od metvice i kopra i kima, a propuštate najvažnije u Zakonu: pravednost, milosrđe, vjernost. Ovo je trebalo činiti, a ono ne propuštati.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (47, 23, 24, 'Slijepe vođe! Cijedite komarca, a gutate devu!\"');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (47, 23, 25, '\"Jao vama, pismoznanci i farizeji! Licemjeri! Čistite čašu i zdjelu izvana, a iznutra su pune grabeža i pohlepe.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (47, 23, 26, 'Farizeju slijepi! Očisti najprije nutrinu čaše da joj i vanjština bude čista.\"');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (47, 23, 27, 'Jao vama pismoznanci i farizeji! Licemjeri! Nalik ste na obijeljene grobove. Izvana izgledaju lijepi, a iznutra su puni mrtvačkih kostiju i svakojake nečistoće.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (47, 23, 28, 'Tako i vi izvana ljudima izgledate pravedni, a iznutra ste puni licemjerja i bezakonja.\"');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (47, 23, 29, '\"Jao vama, pismoznanci i farizeji! Licemjeri! Gradite grobnice prorocima i kitite spomenike pravednicima');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (47, 23, 30, 'te govorite: \'Da smo mi živjeli u dane otaca svojih, ne bismo bili njihovi sudionici u prolijevanju krvi proročke.\'');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (47, 23, 31, 'Tako sami protiv sebe svjedočite da ste sinovi ubojica proroka.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (47, 23, 32, 'Dopunite samo mjeru otaca svojih!\"');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (47, 23, 33, '\"Zmije! Leglo gujinje! Kako ćete uteći osudi paklenoj?');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (47, 23, 34, 'Zato evo ja šaljem vama proroke i mudrace i pismoznance. Jedne ćete od njih ubiti i raspeti, druge bičevati po svojim sinagogama i progoniti od grada do grada');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (47, 23, 35, 'da tako na vas dođe sva pravedna krv, prolivena na zemlji od krvi Abela pravednoga pa do krvi Zaharije, sina Barahijina, kojega ubiste između Hrama i žrtvenika.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (47, 23, 36, 'Zaista, kažem vam, sve će to doći na ovaj naraštaj!\"');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (47, 23, 37, '\"Jeruzaleme, Jeruzaleme, koji ubijaš proroke i kamenuješ one što su tebi poslani! Koliko li puta htjedoh okupiti djecu tvoju kao što kvočka okuplja piliće pod krila, i ne htjedoste.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (47, 23, 38, 'Evo, napuštena vam kuća.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (47, 23, 39, 'Doista, kažem vam, odsada me nećete vidjeti dok ne reknete: Blagoslovljen Onaj koji dolazi u ime Gospodnje!\"');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (47, 24, 1, 'Isus iziđe iz Hrama. Putom mu pristupiše učenici pokazujući mu hramsko zdanje.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (47, 24, 2, 'A on im reče: \"Ne vidite li sve ovo? Zaista, kažem vam, ne, neće se ovdje ostaviti ni kamen na kamenu nerazvaljen.\"');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (47, 24, 3, 'Dok je zatim na Maslinskoj gori sjedio, pristupiše k njemu učenici nasamo govoreći: \"Reci nam kada će to biti i koji će biti znak tvojega Dolaska i svršetka svijeta?\"');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (47, 24, 4, 'Isus im odgovori: \"Pazite da vas tko ne zavede!');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (47, 24, 5, 'Mnogi će doista doći u moje ime i govoriti: \'Ja sam Krist!\' I mnoge će zavesti.\"');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (47, 24, 6, '\"A čut ćete za ratove i za glasove o ratovima. Pazite, ne uznemirujte se. Doista treba da se to dogodi, ali to još nije svršetak.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (47, 24, 7, 'Narod će ustati protiv naroda i kraljevstvo protiv kraljevstva; bit će gladi i potresa po raznim mjestima.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (47, 24, 8, 'Ali sve je to samo početak trudova.\"');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (47, 24, 9, '\"Tada će vas predavati na muke i ubijati vas. I svi će vas narodi zamrziti zbog imena moga.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (47, 24, 10, 'Mnogi će se tada sablazniti, izdavat će jedni druge i mrziti se među sobom.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (47, 24, 11, 'Ustat će mnogi lažni proroci i mnoge zavesti.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (47, 24, 12, 'Razmahat će se bezakonje i ohladnjeti ljubav mnogih.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (47, 24, 13, 'Ali tko ustraje do svršetka, bit će spašen.\"');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (47, 24, 14, '\"I propovijedat će se ovo evanđelje Kraljevstva po svem svijetu za svjedočanstvo svim narodima. Tada će doći svršetak.\"');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (47, 24, 15, '\"Kada dakle vidite da grozota pustoši, po proroštvu Daniela proroka, stoluje na svetome mjestu - tko čita, neka razumije:');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (47, 24, 16, 'koji se tada zateknu u Judeji, neka bježe u gore;');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (47, 24, 17, 'tko bude na krovu, neka ne silazi uzeti što iz kuće;');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (47, 24, 18, 'i tko bude u polju, neka se ne okreće natrag da uzme haljinu!\"');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (47, 24, 19, '\"A jao trudnicama i dojiljama u one dane!\"');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (47, 24, 20, '\"I molite da bijeg vaš ne bude zimi ili subotom');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (47, 24, 21, 'jer tada će biti velika tjeskoba kakve ne bijaše od početka svijeta sve do sada, a neće je ni biti.\"');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (47, 24, 22, '\"I kad se ne bi skratili dani oni, nitko se ne bi spasio. No poradi izabranih skratit će se dani oni.\"');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (47, 24, 23, '\"Ako vam tada tko rekne: \'Gle, evo Krista!\' ili: \'Eno ga!\' - ne povjerujte!');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (47, 24, 24, 'Ustat će, doista, lažni kristi i lažni proroci i iznijeti znamenja velika i čudesa da, bude li moguće, zavedu i izabrane.\"');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (47, 24, 25, '\"Eto, prorekao sam vam.\"');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (47, 24, 26, '\"Reknu li vam dakle: \'Evo, u pustinji je!\', ne izlazite; \'Evo ga u ložnicama!\', ne vjerujte.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (47, 24, 27, 'Jer kao što munja izlazi od istoka i bljesne do zapada, tako će biti i s dolaskom Sina Čovječjega.\"');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (47, 24, 28, '\"Gdje bude strvine, ondje će se skupljati orlovi.\"');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (47, 24, 29, '\"A odmah nakon nevolje onih dana sunce će pomrčati i mjesec neće više svijetljeti i zvijezde će s neba padati i sile će se nebeske poljuljati.\"');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (47, 24, 30, '\"I tada će se pojaviti znak Sina Čovječjega na nebu. I tada će proplakati sva plemena zemlje. I ugledat će Sina Čovječjega gdje dolazi na oblacima nebeskim s velikom moći i slavom.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (47, 24, 31, 'I razaslat će anđele svoje s trubljom velikom i sabrat će mu izabranike s četiri vjetra, s jednoga kraja neba do drugoga.\"');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (47, 24, 32, '\"A od smokve se naučite prispodobi! Kad joj grana već omekša i lišće potjera, znate: blizu je ljeto.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (47, 24, 33, 'Tako i vi kad sve to ugledate, znajte: blizu je, na vratima!\"');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (47, 24, 34, '\"Zaista, kažem vam, ne, neće uminuti naraštaj ovaj dok se sve to ne zbude.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (47, 24, 35, 'Nebo će i zemlja uminuti, ali riječi moje ne, neće uminuti.\"');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (47, 24, 36, '\"A o onom danu i času nitko ne zna, pa ni anđeli nebeski, ni Sin, nego samo Otac.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (47, 24, 37, 'Kao u dane Noine, tako će biti i Dolazak Sina Čovječjega.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (47, 24, 38, 'Kao što su u dane one - prije potopa - jeli i pili, ženili se i udavali do dana kad Noa uđe u korablju');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (47, 24, 39, 'i ništa nisu ni slutili dok ne dođe potop i sve odnije - tako će biti i Dolazak Sina Čovječjega.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (47, 24, 40, 'Dvojica će tada biti u polju: jedan će se uzeti, drugi ostaviti.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (47, 24, 41, 'Dvije će mljeti u mlinu: jedna će se uzeti, druga ostaviti.\"');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (47, 24, 42, '\"Bdijte dakle jer ne znate u koji dan Gospodin vaš dolazi.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (47, 24, 43, 'A ovo znajte: kad bi domaćin znao o kojoj straži kradljivac dolazi, bdio bi i ne bi dopustio potkopati kuće.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (47, 24, 44, 'Zato i vi budite pripravni jer u čas kad i ne mislite Sin Čovječji dolazi.\"');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (47, 24, 45, '\"Tko li je onaj vjerni i razumni sluga što ga gospodar postavi nad svojim ukućanima da im izda hranu u pravo vrijeme?');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (47, 24, 46, 'Blago onome sluzi kojega gospodar kada dođe nađe da tako radi!');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (47, 24, 47, 'Zaista, kažem vam, postavit će ga nad svim imanjem svojim.\"');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (47, 24, 48, '\"No rekne li taj zli sluga u srcu: \'Okasnit će gospodar moj\'');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (47, 24, 49, 'pa stane tući sudrugove, jesti i piti s pijanicama,');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (47, 24, 50, 'doći će gospodar toga sluge u dan u koji mu se ne nada i u čas u koji i ne sluti;');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (47, 24, 51, 'rasjeći će ga i dodijeliti mu udes među licemjerima. Ondje će biti plač i škrgut zubi.\"');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (47, 25, 1, '\"Tada će kraljevstvo nebesko biti kao kad deset djevica uzeše svoje svjetiljke i iziđoše u susret zaručniku.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (47, 25, 2, 'Pet ih bijaše ludih, a pet mudrih.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (47, 25, 3, 'Lude uzeše svjetiljke, ali ne uzeše sa sobom ulja.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (47, 25, 4, 'Mudre pak zajedno sa svjetiljkama uzeše u posudama ulja.\"');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (47, 25, 5, '\"Budući da je zaručnik okasnio, sve one zadrijemaše i pozaspaše.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (47, 25, 6, 'O ponoći nasta vika: \'Evo zaručnika! Iziđite mu u susret!\'');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (47, 25, 7, 'Tada ustadoše sve one djevice i urediše svoje svjetiljke.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (47, 25, 8, 'Lude tada rekoše mudrima: \'Dajte nam od svoga ulja, gase nam se svjetiljke!\'');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (47, 25, 9, 'Mudre im odgovore: \'Nipošto! Ne bi doteklo nama i vama. Pođite radije k prodavačima i kupite!\'\"');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (47, 25, 10, '\"Dok one odoše kupiti, dođe zaručnik: koje bijahu pripravne, uđoše s njim na svadbu i zatvore se vrata.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (47, 25, 11, 'Poslije dođu i ostale djevice pa stanu dozivati: \'Gospodine! Gospodine! Otvori nam!\'');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (47, 25, 12, 'A on im odgovori: \'Zaista kažem vam, ne poznam vas!\'');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (47, 25, 13, 'Bdijte dakle jer ne znate dana ni časa!\"');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (47, 25, 14, '\"Doista, kao kad ono čovjek, polazeći na put, dozva sluge i dade im svoj imetak.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (47, 25, 15, 'Jednomu dade pet talenata, drugomu dva, a trećemu jedan - svakomu po njegovoj sposobnosti.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (47, 25, 16, 'I otputova. Onaj koji je primio pet talenata odmah ode, upotrijebi ih i stekne drugih pet.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (47, 25, 17, 'Isto tako i onaj sa dva stekne druga dva.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (47, 25, 18, 'Onaj naprotiv koji je primio jedan ode, otkopa zemlju i sakri novac gospodarov.\"');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (47, 25, 19, '\"Nakon dugo vremena dođe gospodar tih slugu i zatraži od njih račun.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (47, 25, 20, 'Pristupi mu onaj što je primio pet talenata i donese drugih pet govoreći: \'Gospodaru! Pet si mi talenata predao. Evo, drugih sam pet talenata stekao!\'');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (47, 25, 21, 'Reče mu gospodar: \'Valjaš, slugo dobri i vjerni! U malome si bio vjeran, nad mnogim ću te postaviti! Uđi u radost gospodara svoga!\'\"');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (47, 25, 22, '\"Pristupi i onaj sa dva talenta te reče: \'Gospodaru! Dva si mi talenta predao. Evo, druga sam dva talenta stekao!\'');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (47, 25, 23, 'Reče mu gospodar: \'Valjaš, slugo dobri i vjerni! U malome si bio vjeran, nad mnogim ću te postaviti! Uđi u radost gospodara svoga.\'\"');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (47, 25, 24, '\"A pristupi i onaj koji je primio jedan talenat te reče: \'Gospodaru! Znadoh te: čovjek si strog, žanješ gdje nisi sijao i kupiš gdje nisi vijao.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (47, 25, 25, 'Pobojah se stoga, odoh i sakrih talenat tvoj u zemlju. Evo ti tvoje!\'');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (47, 25, 26, 'A gospodar mu reče: \'Slugo zli i lijeni! Znao si da žanjem gdje nisam sijao i kupim gdje nisam vijao!');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (47, 25, 27, 'Trebalo je dakle da uložiš moj novac kod novčara i ja bih po povratku izvadio svoje s dobitkom.\'\"');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (47, 25, 28, '\"\'Uzmite stoga od njega talenat i podajte onomu koji ih ima deset.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (47, 25, 29, 'Doista, onomu koji ima još će se dati, neka ima u izobilju, a od onoga koji nema oduzet će se i ono što ima.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (47, 25, 30, 'A beskorisnoga slugu izbacite van u tamu. Ondje će biti plač i škrgut zubi.\'\"');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (47, 25, 31, '\"Kad Sin Čovječji dođe u slavi i svi anđeli njegovi s njime, sjest će na prijestolje slave svoje.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (47, 25, 32, 'I sabrat će se pred njim svi narodi, a on će ih jedne od drugih razlučiti kao što pastir razlučuje ovce od jaraca.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (47, 25, 33, 'Postavit će ovce sebi zdesna, a jarce slijeva.\"');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (47, 25, 34, '\"Tada će kralj reći onima sebi zdesna: \'Dođite, blagoslovljeni Oca mojega! Primite u baštinu Kraljevstvo pripravljeno za vas od postanka svijeta!');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (47, 25, 35, 'Jer ogladnjeh i dadoste mi jesti; ožednjeh i napojiste me; stranac bijah i primiste me;');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (47, 25, 36, 'gol i zaogrnuste me; oboljeh i pohodiste me; u tamnici bijah i dođoste k meni.\'\"');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (47, 25, 37, '\"Tada će mu pravednici odgovoriti: \'Gospodine, kada te to vidjesmo gladna i nahranismo te; ili žedna i napojismo te?');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (47, 25, 38, 'Kada te vidjesmo kao stranca i primismo; ili gola i zaogrnusmo te?');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (47, 25, 39, 'Kada te vidjesmo bolesna ili u tamnici i dođosmo k tebi?\'');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (47, 25, 40, 'A kralj će im odgovoriti: \'Zaista, kažem vam, što god učiniste jednomu od ove moje najmanje braće, meni učiniste!\'\"');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (47, 25, 41, '\"Zatim će reći i onima slijeva: \'Odlazite od mene, prokleti, u oganj vječni, pripravljen đavlu i anđelima njegovim!');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (47, 25, 42, 'Jer ogladnjeh i ne dadoste mi jesti; ožednjeh i ne dadoste mi piti;');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (47, 25, 43, 'stranac bijah i ne primiste me; gol i ne zaogrnuste me; bolestan i u tamnici i ne pohodiste me!\'\"');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (47, 25, 44, '\"Tada će mu i oni odgovoriti: \'Gospodine, a kada te to vidjesmo gladna, ili žedna, ili stranca, ili gola, ili bolesna, ili u tamnici, i ne poslužismo te?\'');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (47, 25, 45, 'Tada će im on odgovoriti: \'Zaista, kažem vam, što god ne učiniste jednomu od ovih najmanjih, ni meni ne učiniste.\'\"');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (47, 25, 46, '\"I otići će ovi u muku vječnu, a pravednici u život vječni.\"');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (47, 26, 1, 'I kad Isus završi sve te besjede, reče svojim učenicima:');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (47, 26, 2, '\"Znate da je za dva dana Pasha, i Sin Čovječji predaje se da se razapne.\"');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (47, 26, 3, 'Uto se sabraše glavari svećenički i starješine narodne u dvoru velikoga svećenika imenom Kajfe');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (47, 26, 4, 'i zaključiše Isusa na prijevaru uhvatiti i ubiti.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (47, 26, 5, 'Jer se govorilo: \"Nikako ne o Blagdanu da ne nastane pobuna u narodu.\"');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (47, 26, 6, 'Kad je Isus bio u Betaniji, u kući Šimuna Gubavca,');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (47, 26, 7, 'pristupi mu neka žena s alabastrenom posudicom skupocjene pomasti i polije ga po glavi, dok je on bio za stolom.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (47, 26, 8, 'Vidjevši to, učenici negodovahu: \"Čemu ta rasipnost?');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (47, 26, 9, 'Moglo se to skupo prodati i dati siromasima.\"');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (47, 26, 10, 'Zapazio to Isus pa im reče: \"Što dodijavate ženi? Dobro djelo učini prema meni.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (47, 26, 11, 'Ta siromaha svagda imate uza se, a mene nemate svagda.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (47, 26, 12, 'Izlila je tu pomast na moje tijelo - za ukop mi to učini.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (47, 26, 13, 'Zaista, kažem vam, gdje se god bude propovijedalo ovo evanđelje, po svem svijetu, navješćivat će se i ovo što ona učini - njoj na spomen.\"');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (47, 26, 14, 'Tada jedan od dvanaestorice, zvan Juda Iškariotski, pođe glavarima svećeničkim');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (47, 26, 15, 'i reče: \"Što ćete mi dati i ja ću vam ga predati.\" A oni mu odmjeriše trideset srebrnjaka.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (47, 26, 16, 'Otada je tražio priliku da ga preda.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (47, 26, 17, 'Prvoga dana Beskvasnih kruhova pristupiše učenici Isusu i upitaše: \"Gdje hoćeš da ti pripravimo te blaguješ pashu?\"');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (47, 26, 18, 'On reče: \"Idite u grad tomu i tomu i recite mu: \'Učitelj veli: Vrijeme je moje blizu, kod tebe slavim pashu sa svojim učenicima.\'\"');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (47, 26, 19, 'I učine učenici kako im naredi Isus i priprave pashu.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (47, 26, 20, 'Uvečer bijaše Isus za stolom s dvanaestoricom.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (47, 26, 21, 'I dok su blagovali, reče: \"Zaista, kažem vam, jedan će me od vas izdati.\"');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (47, 26, 22, 'Silno ožalošćeni, stanu mu jedan za drugim govoriti: \"Da nisam ja, Gospodine?\"');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (47, 26, 23, 'On odgovori: \"Onaj koji umoči sa mnom ruku u zdjelu, taj će me izdati.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (47, 26, 24, 'Sin Čovječji, istina, odlazi kako je o njemu pisano, ali jao čovjeku onomu koji predaje Sina Čovječjega. Tomu bi čovjeku bolje bilo da se ni rodio nije.\"');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (47, 26, 25, 'A Juda, izdajnik, prihvati i reče: \"Da nisam ja, učitelju?\" Reče mu: \"Ti kaza.\"');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (47, 26, 26, 'I dok su blagovali, uze Isus kruh, izreče blagoslov pa razlomi, dade svojim učenicima i reče: \"Uzmite i jedite! Ovo je tijelo moje!\"');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (47, 26, 27, 'I uze čašu, zahvali i dade im govoreći: \"Pijte iz nje svi!');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (47, 26, 28, 'Ovo je krv moja, krv Saveza koja se za mnoge prolijeva na otpuštenje grijeha.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (47, 26, 29, 'A kažem vam: ne, neću od sada piti od ovog roda trsova do onoga dana kad ću ga - novoga - s vama piti u kraljevstvu Oca svojega.\"');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (47, 26, 30, 'Otpjevavši hvalospjeve, zaputiše se prema Maslinskoj gori.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (47, 26, 31, 'Tada im reče Isus: \"Svi ćete se vi još ove noći sablazniti o mene. Ta pisano je: Udarit će pastira i stado će se razbjeći.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (47, 26, 32, 'Ali kad uskrsnem, ići ću pred vama u Galileju.\'');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (47, 26, 33, 'Nato će mu Petar: \"Ako se i svi sablazne o tebe, ja se nikada neću!\"');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (47, 26, 34, 'Reče mu Isus: \"Zaista, kažem ti, još ove noći, prije negoli se pijetao oglasi, triput ćeš me zatajiti!\"');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (47, 26, 35, 'Kaže mu Petar: \"Bude li trebalo i umrijeti s tobom, ne, neću te zatajiti.\" Tako rekoše i svi učenici.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (47, 26, 36, 'Tada dođe Isus s njima u predio zvan Getsemani i kaže učenicima: \"Sjednite ovdje dok ja odem onamo pomoliti se.\"');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (47, 26, 37, 'I povede sa sobom Petra i oba sina Zebedejeva. Spopade ga žalost i tjeskoba.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (47, 26, 38, 'Tada im reče: \"Duša mi je nasmrt žalosna. Ostanite ovdje i bdijte sa mnom!\"');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (47, 26, 39, 'I ode malo dalje, pade ničice moleći: \"Oče moj! Ako je moguće, neka me mimoiđe ova čaša. Ali ne kako ja hoću, nego kako hoćeš ti.\"');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (47, 26, 40, 'I dođe učenicima i nađe ih pozaspale pa reče Petru: \"Tako, zar niste mogli jedan sat probdjeti sa mnom?');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (47, 26, 41, 'Bdijte i molite da ne padnete u napast! Duh je, istina, voljan, no tijelo je slabo.\"');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (47, 26, 42, 'Opet, po drugi put, ode i pomoli se: \"Oče moj! Ako nije moguće da me čaša mine da je ne pijem, budi volja tvoja!\"');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (47, 26, 43, 'I ponovno dođe i nađe ih pozaspale, oči im se sklapale.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (47, 26, 44, 'Opet ih ostavi, pođe i pomoli se po treći put ponavljajući iste riječi.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (47, 26, 45, 'Tada dođe učenicima i reče im: \"Samo spavajte i počivajte! Evo, približio se čas! Sin Čovječji predaje se u ruke grešničke!');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (47, 26, 46, 'Ustanite, hajdemo! Evo, približio se moj izdajica.\"');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (47, 26, 47, 'Dok je on još govorio, gle, dođe Juda, jedan od dvanaestorice, i s njime silna svjetina s mačevima i toljagama poslana od glavara svećeničkih i starješina narodnih.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (47, 26, 48, 'A izdajica im dao znak: \"Koga poljubim, taj je, njega uhvatite!\"');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (47, 26, 49, 'I odmah pristupi Isusu i reče: \"Zdravo, Učitelju!\" I poljubi ga.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (47, 26, 50, 'A Isus mu reče: \"Prijatelju, zašto ti ovdje!\" Tada pristupe, podignu ruke na Isusa i uhvate ga.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (47, 26, 51, 'I gle, jedan od onih koji bijahu s Isusom maši se rukom, trgnu mač, udari slugu velikoga svećenika i odsiječe mu uho.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (47, 26, 52, 'Kaže mu tada Isus: \"Vrati mač na njegovo mjesto jer svi koji se mača laćaju od mača i ginu.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (47, 26, 53, 'Ili zar misliš da ja ne mogu zamoliti Oca svojega i eto umah uza me više od dvanaest legija anđela?');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (47, 26, 54, 'No kako bi se onda ispunila Pisma da tako mora biti?\"');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (47, 26, 55, 'U taj čas reče Isus svjetini: \"Kao na razbojnika iziđoste s mačevima i toljagama da me uhvatite? Danomice sjeđah u Hramu naučavajući i ne uhvatiste me.\"');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (47, 26, 56, 'A sve se to dogodilo da se ispune Pisma proročka. Tada ga svi učenici ostave i pobjegnu.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (47, 26, 57, 'Nato uhvatiše Isusa i odvedoše ga velikomu svećeniku Kajfi, kod kojega se sabraše pismoznanci i starješine.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (47, 26, 58, 'A Petar je išao za njim izdaleka do dvora velikog svećenika; i ušavši unutra, sjedne sa stražarima da vidi svršetak.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (47, 26, 59, 'A glavari svećenički i cijelo Vijeće tražili su kakvo lažno svjedočanstvo protiv Isusa da bi ga mogli pogubiti.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (47, 26, 60, 'Ali ne nađoše premda pristupiše mnogi lažni svjedoci. Napokon pristupe dvojica');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (47, 26, 61, 'i reknu: \"Ovaj reče: \'Mogu razvaliti Hram Božji i za tri ga dana sagraditi.\'\"');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (47, 26, 62, 'Usta nato veliki svećenik i reče mu: \"Zar ništa ne odgovaraš? Što to ovi protiv tebe svjedoče?\"');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (47, 26, 63, 'Isus je šutio. Reče mu veliki svećenik: \"Zaklinjem te Bogom živim: Kaži nam jesi li ti Krist, Sin Božji?\"');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (47, 26, 64, 'Reče mu Isus: \"Ti kaza! Štoviše, kažem vam: Odsada ćete gledati Sina Čovječjega gdje sjedi zdesna Sile i dolazi na oblacima nebeskim.\"');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (47, 26, 65, 'Nato veliki svećenik razdrije haljine govoreći: \"Pohulio je! Što nam još trebaju svjedoci! Evo, sada ste čuli hulu!');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (47, 26, 66, 'Što vam se čini?\" Oni odgovoriše: \"Smrt zaslužuje!\"');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (47, 26, 67, 'Tada su mu pljuvali u lice i udarali ga, a drugi ga pljuskali');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (47, 26, 68, 'govoreći: \"Proreci nam, Kriste, tko te udario?\"');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (47, 26, 69, 'A Petar je sjedio vani u dvorištu. I pristupi mu jedna sluškinja govoreći: \"I ti bijaše s Isusom Galilejcem.\"');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (47, 26, 70, 'On pred svima zanijeka: \"Ne znam što govoriš.\"');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (47, 26, 71, 'Kad iziđe u predvorje, spazi ga druga i kaže nazočnima: \"Ovaj bijaše s Isusom Nazarećaninom.\"');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (47, 26, 72, 'On opet zanijeka sa zakletvom: \"Ne znam toga čovjeka.\"');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (47, 26, 73, 'Malo zatim nazočni pristupiše Petru i rekoše: \"Doista, i ti si od njih! Ta govor te tvoj izdaje!\"');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (47, 26, 74, 'On se tada stane zaklinjati i preklinjati: \"Ne znam toga čovjeka.\" I odmah se oglasi pijetao.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (47, 26, 75, 'I spomenu se Petar riječi koju mu Isus reče: \"Prije nego se pijetao oglasi, triput ćeš me zatajiti.\" I iziđe te gorko zaplaka.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (47, 27, 1, 'A kad objutri, svi su glavari svećenički i starješine narodne održali vijećanje protiv Isusa da ga pogube.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (47, 27, 2, 'I svezana ga odveli i predali upravitelju Pilatu.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (47, 27, 3, 'Kada Juda, njegov izdajica, vidje da je Isus osuđen, pokaja se i vrati trideset srebrnjaka glavarima svećeničkim i starješinama');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (47, 27, 4, 'govoreći: \"Sagriješih predavši krv nedužnu!\" Odgovoriše: \"Što se to nas tiče? To je tvoja stvar!\"');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (47, 27, 5, 'I bacivši srebrnjake u Hram, ode te se objesi.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (47, 27, 6, 'Glavari svećenički uzeše srebrnjake i rekoše:');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (47, 27, 7, '\"Nije dopušteno staviti ih u hramsku riznicu jer su krvarina.\" Posavjetuju se i kupe za njih lončarovu njivu za ukop stranaca.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (47, 27, 8, 'Stoga se ona njiva zove \"Krvava njiva\" sve do danas.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (47, 27, 9, 'Tada se ispuni što je rečeno po proroku Jeremiji: Uzeše trideset srebrnjaka - cijenu Neprocjenjivoga kojega procijeniše sinovi Izraelovi -');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (47, 27, 10, 'i dadoše ih za njivu lončarovu kako mi naredi Gospodin.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (47, 27, 11, 'Dovedoše dakle Isusa pred upravitelja. Upita ga upravitelj: \"Ti li si kralj židovski?\" On odgovori: \"Ti kažeš.\"');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (47, 27, 12, 'I dok su ga glavari svećenički i starješine narodne optuživale, ništa nije odgovarao.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (47, 27, 13, 'Tada mu reče Pilat: \"Ne čuješ li što sve protiv tebe svjedoče?\"');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (47, 27, 14, 'I ne odgovori mu ni na jednu riječ te se upravitelj silno čudio.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (47, 27, 15, 'A o Blagdanu upravitelj je običavao svjetini pustiti jednoga uznika, koga bi već htjeli.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (47, 27, 16, 'Tada upravo bijaše u njih poznati uznik zvani Baraba.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (47, 27, 17, 'Kad se dakle sabraše, reče im Pilat: \"Koga hoćete da vam pustim: Barabu ili Isusa koji se zove Krist?\"');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (47, 27, 18, 'Znao je doista da ga predadoše iz zavisti.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (47, 27, 19, 'Dok je sjedio na sudačkoj stolici, poruči nu njegova žena: \"Mani se ti onoga pravednika jer sam danas u snu mnogo pretrpjela zbog njega.\"');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (47, 27, 20, 'Međutim, glavari svećenički i starješine nagovore svjetinu da zaište Barabu, a Isus da se pogubi.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (47, 27, 21, 'Upita ih dakle upravitelj: \"Kojega od ove dvojice hoćete da vam pustim?\" A oni rekoše: \"Barabu!\"');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (47, 27, 22, 'Kaže im Pilat: \"Što dakle da učinim s Isusom koji se zove Krist?\" Oni će: \"Neka se razapne.\"');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (47, 27, 23, 'A on upita: \"A što je zla učinio?\" Vikahu još jače: \"Neka se razapne!\"');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (47, 27, 24, 'Kad Pilat vidje da ništa ne koristi, nego da biva sve veći metež, uzme vodu i opere ruke pred svjetinom govoreći: \"Nevin sam od krvi ove! Vi se pazite!\"');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (47, 27, 25, 'Sav narod nato odvrati: \"Krv njegova na nas i na djecu našu!\"');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (47, 27, 26, 'Tada im pusti Barabu, a Isusa, izbičevana, preda da se razapne.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (47, 27, 27, 'Onda vojnici upraviteljevi uvedoše Isusa u dvor upraviteljev i skupiše oko njega cijelu četu.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (47, 27, 28, 'Svukoše ga pa zaogrnuše skrletnim plaštem.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (47, 27, 29, 'Spletoše zatim vijenac od trnja i staviše mu na glavu, a tako i trsku u desnicu. Prigibajući pred njim koljena, izrugivahu ga: \"Zdravo, kralju židovski!\"');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (47, 27, 30, 'Onda pljujući po njemu, uzimahu trsku i udarahu ga njome po glavi.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (47, 27, 31, 'Pošto ga izrugaše, svukoše mu plašt, obukoše mu njegove haljine pa ga odvedoše da ga razapnu.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (47, 27, 32, 'Izlazeći nađu nekoga čovjeka Cirenca, imenom Šimuna, i prisile ga da mu ponese križ.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (47, 27, 33, 'I dođoše na mjesto zvano Golgota, to jest Lubanjsko mjesto,');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (47, 27, 34, 'dadoše mu piti vino sa žuči pomiješano. I kad okusi, ne htjede piti.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (47, 27, 35, 'A pošto ga razapeše, razdijeliše među se haljine njegove bacivši kocku.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (47, 27, 36, 'I sjedeći ondje, čuvahu ga.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (47, 27, 37, 'I staviše mu ponad glave krivicu napisanu: \"Ovo je Isus, kralj židovski.\"');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (47, 27, 38, 'Tada razapeše s njime dva razbojnika, jednoga zdesna, drugoga slijeva.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (47, 27, 39, 'A prolaznici su ga pogrđivali mašući glavama:');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (47, 27, 40, '\"Ti koji razvaljuješ Hram i za tri ga dana sagradiš, spasi sam sebe! Ako si Sin Božji, siđi s križa!\"');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (47, 27, 41, 'Slično i glavari svećenički s pismoznancima i starješinama, rugajući se, govorahu:');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (47, 27, 42, '\"Druge je spasio, sebe ne može spasiti! Kralj je Izraelov! Neka sada siđe s križa pa ćemo povjerovati u nj!');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (47, 27, 43, 'Uzdao se u Boga! Neka ga sad izbavi ako mu omilje! Ta govorio je: \'Sin sam Božji!\'\"');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (47, 27, 44, 'Tako ga vrijeđahu i s njim raspeti razbojnici.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (47, 27, 45, 'Od šeste ure nasta tama po svoj zemlji - do ure devete.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (47, 27, 46, 'O devetoj uri povika Isus iza glasa: \"Eli, Eli, lema sabahtani?\" To će reći: \"Bože moj, Bože moj, zašto si me ostavio?\"');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (47, 27, 47, 'A neki od nazočnih, čuvši to, govorahu: \"Ovaj zove Iliju.\"');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (47, 27, 48, 'I odmah pritrča jedan od njih, uze spužvu, natopi je octom, natakne je na trsku i pruži mu piti.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (47, 27, 49, 'A ostali rekoše: \"Pusti da vidimo hoće li doći Ilija da ga spasi.\"');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (47, 27, 50, 'A Isus opet povika iz glasa i ispusti duh.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (47, 27, 51, 'I gle, zavjesa se hramska razdrije odozgor dodolje, nadvoje; zemlja se potrese, pećine se raspukoše,');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (47, 27, 52, 'grobovi otvoriše i tjelesa mnogih svetih preminulih uskrsnuše');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (47, 27, 53, 'te iziđoše iz grobova nakon njegova uskrsnuća, uđoše u sveti grad i pokazaše se mnogima.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (47, 27, 54, 'A satnik i oni koji su s njime čuvali Isusa vidješe potres i što se zbiva, silno se prestrašiše i rekoše: \"Uistinu, Sin Božji bijaše ovaj.\"');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (47, 27, 55, 'A bijahu ondje i izdaleka promatrahu mnoge žene što su iz Galileje išle za Isusom poslužujući mu;');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (47, 27, 56, 'među njima Marija Magdalena i Marija, Jakovljeva i Josipova majka, i majka sinova Zebedejevih.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (47, 27, 57, 'Uvečer dođe neki bogat čovjek iz Arimateje, imenom Josip, koji i sam bijaše učenik Isusov.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (47, 27, 58, 'On pristupi Pilatu i zaiska tijelo Isusovo. Tada Pilat zapovjedi da mu se dadne.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (47, 27, 59, 'Josip uze tijelo, povi ga u čisto platno');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (47, 27, 60, 'i položi u svoj novi grob koji bijaše isklesao u stijeni. Dokotrlja velik kamen na grobna vrata i otiđe.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (47, 27, 61, 'A bijahu ondje Marija Magdalena i druga Marija: sjedile su nasuprot grobu.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (47, 27, 62, 'Sutradan, to jest dan nakon Priprave, sabraše se glavari svećenički i farizeji kod Pilata');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (47, 27, 63, 'te mu rekoše: \"Gospodaru, sjetismo se da onaj varalica još za života kaza: \'Nakon tri dana uskrsnut ću.\'');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (47, 27, 64, 'Zapovjedi dakle da se grob osigura sve do trećega dana da ne bi možda došli njegovi učenici, ukrali ga pa rekli narodu: \'Uskrsnuo je od mrtvih!\' I bit će posljednja prijevara gora od prve.\"');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (47, 27, 65, 'Reče im Pilat: \"Imate stražu! Idite i osigurajte kako znate!\"');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (47, 27, 66, 'Nato oni odu i osiguraju grob: zapečate kamen i postave stražu.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (47, 28, 1, 'Po suboti, u osvit prvoga dana u tjednu, dođe Marija Magdalena i druga Marija pogledati grob.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (47, 28, 2, 'I gle, nastade žestok potres jer anđeo Gospodnji siđe s neba, pristupi, otkotrlja kamen i sjede na nj.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (47, 28, 3, 'Lice mu bijaše kao munja, a odjeća bijela kao snijeg.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (47, 28, 4, 'Od straha pred njim zadrhtaše stražari i obamriješe.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (47, 28, 5, 'A anđeo progovori ženama: \"Vi se ne bojte! Ta znam: Isusa Raspetoga tražite!');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (47, 28, 6, 'Nije ovdje! Uskrsnu kako reče. Hajde, vidite mjesto gdje je ležao');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (47, 28, 7, 'pa pođite žurno i javite njegovim učenicima da uskrsnu od mrtvih. I evo, ide pred vama u Galileju. Ondje ćete ga vidjeti. Evo, rekoh vam.\"');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (47, 28, 8, 'One otiđoše žurno s groba te sa strahom i velikom radošću otrčaše javiti njegovim učenicima.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (47, 28, 9, 'Kad eto im Isusa u susret! Reče im: \"Zdravo!\" One polete k njemu, obujme mu noge i ničice mu se poklone.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (47, 28, 10, 'Tada im Isus reče: \"Ne bojte se! Idite, javite mojoj braći da pođu u Galileju! Ondje će me vidjeti!\"');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (47, 28, 11, 'Dok su one odlazile, gle, neki od straže dođoše u grad i javiše glavarima svećeničkim sve što se dogodilo.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (47, 28, 12, 'Oni se sabraše sa starješinama na vijećanje, uzeše mnogo novaca i dadoše vojnicima');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (47, 28, 13, 'govoreći: \"Recite: \'Noću dok smo mi spavali, dođoše njegovi učenici i ukradoše ga.\'');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (47, 28, 14, 'Ako to dočuje upravitelj, mi ćemo ga uvjeriti i sve učiniti da vi budete bez brige.\"');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (47, 28, 15, 'Oni uzeše novac i učiniše kako bijahu poučeni. I razglasilo se to među Židovima - sve do danas.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (47, 28, 16, 'Jedanaestorica pođoše u Galileju na goru kamo im je naredio Isus.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (47, 28, 17, 'Kad ga ugledaše, padoše ničice preda nj. A neki posumnjaše.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (47, 28, 18, 'Isus im pristupi i prozbori: \"Dana mi je sva vlast na nebu i na zemlji!');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (47, 28, 19, 'Pođite dakle i učinite mojim učenicima sve narode krsteći ih u ime Oca i Sina i Duha Svetoga');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (47, 28, 20, 'i učeći ih čuvati sve što sam vam zapovjedio!\" \"I evo, ja sam s vama u sve dane - do svršetka svijeta.\"');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (48, 1, 1, 'Početak Evanđelja Isusa Krista Sina Božjega.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (48, 1, 2, 'Pisano je u Izaiji proroku: Evo šaljem glasnika svoga pred licem tvojim da ti pripravi put.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (48, 1, 3, 'Glas viče u pustinji: Pripravite put Gospodinu, poravnite mu staze!');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (48, 1, 4, 'Tako se pojavi Ivan: krstio je u pustinji i propovijedao krst obraćenja na otpuštenje grijeha.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (48, 1, 5, 'Grnula k njemu sva judejska zemlja i svi Jeruzalemci: primali su od njega krštenje u rijeci Jordanu ispovijedajući svoje grijehe.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (48, 1, 6, 'Ivan bijaše odjeven u devinu dlaku, s kožnatim pojasom oko bokova; hranio se skakavcima i divljim medom.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (48, 1, 7, 'I propovijedao je: \"Nakon mene dolazi jači od mene. Ja nisam dostojan sagnuti se i odriješiti mu remenje na obući.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (48, 1, 8, 'Ja vas krstim vodom, a on će vas krstiti Duhom Svetim.\"');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (48, 1, 9, 'Onih dana dođe Isus iz Nazareta galilejskoga i primi u Jordanu krštenje od Ivana.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (48, 1, 10, 'I odmah, čim izađe iz vode, ugleda otvorena nebesa i Duha poput goluba gdje silazi na nj,');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (48, 1, 11, 'a glas se zaori s nebesa: Ti si Sin moj, Ljubljeni! U tebi mi sva milina!');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (48, 1, 12, 'I odmah ga Duh nagna u pustinju.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (48, 1, 13, 'I bijaše u pustinji četrdeset dana, gdje ga je iskušavao Sotona; bijaše sa zvijerima, a anđeli mu služahu.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (48, 1, 14, 'A pošto Ivan bijaše predan, otiđe Isus u Galileju. Propovijedao je evanđelje Božje:');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (48, 1, 15, '\"Ispunilo se vrijeme, približilo se kraljevstvo Božje! Obratite se i vjerujte evanđelju!\"');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (48, 1, 16, 'I prolazeći uz Galilejsko more, ugleda Šimuna i Andriju, brata Šimunova, gdje ribare na moru; bijahu ribari.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (48, 1, 17, 'I reče im Isus: \"Hajdete za mnom i učinit ću vas ribarima ljudi!\"');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (48, 1, 18, 'Oni odmah ostaviše mreže i pođoše za njim.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (48, 1, 19, 'Pošavši malo naprijed, ugleda Jakova Zebedejeva i njegova brata Ivana: u lađi su krpali mreže.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (48, 1, 20, 'Odmah pozva i njih. Oni ostave oca Zebedeja u lađi s nadničarima i otiđu za njim.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (48, 1, 21, 'I stignu u Kafarnaum. Odmah u subotu uđe on u sinagogu i poče naučavati.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (48, 1, 22, 'Bijahu zaneseni njegovim naukom. Ta učio ih je kao onaj koji ima vlast, a ne kao pismoznanci.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (48, 1, 23, 'A u njihovoj se sinagogi upravo zatekao čovjek opsjednut nečistim duhom. On povika:');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (48, 1, 24, '\"Što ti imaš s nama, Isuse Nazarećanine? Došao si da nas uništiš? Znam tko si: Svetac Božji!\"');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (48, 1, 25, 'Isus mu zaprijeti: \"Umukni i iziđi iz njega!\"');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (48, 1, 26, 'Nato nečisti duh potrese njime pa povika iz svega glasa i iziđe iz njega.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (48, 1, 27, 'Svi se zaprepastiše te se zapitkivahu: \"Što li je ovo? Nova li i snažna nauka! Pa i samim nečistim dusima zapovijeda, i pokoravaju mu se.\"');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (48, 1, 28, 'I pročulo se odmah o njemu posvuda, po svoj okolici galilejskoj.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (48, 1, 29, 'I odmah pošto iziđoše iz sinagoge, uđe s Jakovom i Ivanom u kuću Šimunovu i Andrijinu.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (48, 1, 30, 'A punica Šimunova ležala u ognjici. I odmah mu kažu za nju.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (48, 1, 31, 'On pristupi, prihvati je za ruku i podiže. I pusti je ognjica. I posluživaše im.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (48, 1, 32, 'Uvečer, kad sunce zađe, donošahu preda nj sve bolesne i opsjednute.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (48, 1, 33, 'I sav je grad nagrnuo k vratima.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (48, 1, 34, 'I on ozdravi bolesnike - a bijahu mnogi i razne im bolesti - i zloduhe mnoge izagna. I ne dopusti zlodusima govoriti jer su ga znali.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (48, 1, 35, 'Rano ujutro, još za mraka, ustane, iziđe i povuče se na samotno mjesto i ondje se moljaše.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (48, 1, 36, 'Potražiše ga Šimun i njegovi drugovi.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (48, 1, 37, 'Kad ga nađoše, rekoše mu: \"Svi te traže.\"');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (48, 1, 38, 'Kaže im: \"Hajdemo drugamo, u obližnja mjesta, da i ondje propovijedam! Ta zato sam došao.\"');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (48, 1, 39, 'I prođe svom Galilejom: propovijedao je u njihovim sinagogama i zloduhe izgonio.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (48, 1, 40, 'I dođe k njemu neki gubavac, klekne i zamoli: \"Ako hoćeš, možeš me očistiti!\"');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (48, 1, 41, 'Isus ganut pruži ruku, dotače ga se pa će mu: \"Hoću, budi čist!\"');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (48, 1, 42, 'I odmah nesta s njega gube i očisti se.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (48, 1, 43, 'Isus se otrese na nj i odmah ga otpravi');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (48, 1, 44, 'riječima: \"Pazi, nikomu ništa ne kazuj, nego idi, pokaži se svećeniku i prinesi za svoje očišćenje što propisa Mojsije, njima za svjedočanstvo.\"');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (48, 1, 45, 'Ali čim iziđe, stane on uvelike pripovijedati i razglašavati događaj tako da Isus više nije mogao javno ući u grad, nego se zadržavao vani na samotnim mjestima. I dolažahu k njemu odasvud.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (48, 2, 1, 'I pošto nakon nekoliko dana opet uđe u Kafarnaum, pročulo se da je u kući.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (48, 2, 2, 'I skupiše se mnogi te više nije bilo mjesta ni pred vratima. On im navješćivaše Riječ.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (48, 2, 3, 'I dođu noseći k njemu uzetoga. Nosila ga četvorica.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (48, 2, 4, 'Budući da ga zbog mnoštva nisu mogli unijeti k njemu, otkriju krov nad mjestom gdje bijaše Isus. Načinivši otvor, spuste postelju na kojoj je uzeti ležao.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (48, 2, 5, 'Vidjevši njihovu vjeru, kaže Isus uzetome: \"Sinko! Otpuštaju ti se grijesi.\"');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (48, 2, 6, 'Sjedjeli su ondje neki pismoznanci koji počeše mudrovati u sebi:');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (48, 2, 7, '\"Što to ovaj govori? Huli! Ta tko može grijehe otpuštati doli Bog jedini?\"');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (48, 2, 8, 'Isus duhom odmah proniknu da tako mudruju u sebi, pa će im: \"Što to mudrujete u sebi?');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (48, 2, 9, 'Ta što je lakše? Reći uzetomu: \'Otpuštaju ti se grijesi\' ili reći: \'Ustani, uzmi svoju postelju i hodi?\'');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (48, 2, 10, 'Ali da znate: vlastan je Sin Čovječji na zemlji otpuštati grijehe!\" I reče uzetomu:');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (48, 2, 11, '\"Tebi zapovijedam, ustani, uzmi postelju i pođi kući!\"');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (48, 2, 12, 'I on usta, uze odmah postelju i iziđe na očigled svima. Svi su zaneseni slavili Boga govoreći: \"Takvo što nikad još ne vidjesmo!\"');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (48, 2, 13, 'Isus ponovno iziđe k moru. Sve je ono mnoštvo grnulo k njemu i on ih poučavaše.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (48, 2, 14, 'Prolazeći ugleda Levija Alfejeva gdje sjedi u carinarnici. I kaže mu: \"Pođi za mnom!\" On usta i pođe za njim.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (48, 2, 15, 'Kada zatim Isus bijaše za stolom u njegovoj kući, nađoše se za stolom s njime i njegovim učenicima i mnogi carinici i grešnici. Bilo ih je uistinu mnogo. A slijedili su ga');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (48, 2, 16, 'i pismoznanci farizejske sljedbe pa vidjevši da jede s grešnicima i carinicima rekoše njegovim učenicima: \"Zašto jede s carinicima i grešnicima?\"');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (48, 2, 17, 'Čuvši to, Isus im reče: \"Ne treba zdravima liječnika, nego bolesnima! Ne dođoh zvati pravednike, nego grešnike.\"');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (48, 2, 18, 'Ivanovi su učenici i farizeji postili. I dođu neki i kažu mu: \"Zašto učenici Ivanovi i učenici farizejski poste, a tvoji učenici ne poste?\"');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (48, 2, 19, 'Nato im Isus reče: \"Mogu li svatovi postiti dok je zaručnik s njima? Dokle god imaju zaručnika sa sobom, ne mogu postiti.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (48, 2, 20, 'Doći će već dani kad će im se ugrabiti zaručnik i tada će postiti u onaj dan!\"');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (48, 2, 21, '\"Nitko ne prišiva krpe od sirova sukna na staro odijelo. Inače nova zakrpa vuče sa starog odijela pa nastane još veća rupa.\"');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (48, 2, 22, '\"I nitko ne ulijeva novo vino u stare mješine. Inače će vino poderati mješine pa propade i vino i mješine. Nego - novo vino u nove mješine!\"');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (48, 2, 23, 'Jedne je subote prolazio kroz usjeve. Njegovi učenici počeše putem trgati klasje. A farizeji mu rekoše:');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (48, 2, 24, '\"Gle! Zašto čine što subotom nije dopušteno?\"');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (48, 2, 25, 'Isus im odgovori: \"Zar nikad niste čitali što učini David kad ogladnje te se nađe u potrebi on i njegovi pratioci?');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (48, 2, 26, 'Kako za velikog svećenika Ebjatara uđe u Dom Božji i pojede prinesene kruhove kojih ne smije jesti nitko osim svećenika; a on dade i svojim pratiocima?\"');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (48, 2, 27, 'I govoraše im: \"Subota je stvorena radi čovjeka, a ne čovjek radi subote.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (48, 2, 28, 'Tako, Sin Čovječji gospodar je subote!\"');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (48, 3, 1, 'Uđe ponovno u sinagogu. Bio je ondje čovjek usahle ruke.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (48, 3, 2, 'A oni vrebahu hoće li ga Isus u subotu izliječiti, da ga optuže.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (48, 3, 3, 'On kaže čovjeku usahle ruke: \"Stani na sredinu!\"');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (48, 3, 4, 'A njima će: \"Je li subotom dopušteno činiti dobro ili činiti zlo, život spasiti ili pogubiti?\" No oni su šutjeli.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (48, 3, 5, 'A on, ražalošćen okorjelošću srca njihova, srdito ih ošinu pogledom pa reče tom čovjeku: \"Ispruži ruku!\" On ispruži - i ruka mu zdrava!');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (48, 3, 6, 'Farizeji iziđu i dadnu se odmah s herodovcima na vijećanje protiv njega kako da ga pogube.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (48, 3, 7, 'Isus se s učenicima povuče k moru. Za njim je išao silan svijet iz Galileje. I iz Judeje,');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (48, 3, 8, 'iz Jeruzalema, iz Idumeje, iz Transjordanije i iz okolice Tira i Sidona - silno je mnoštvo čulo što čini i nagrnulo k njemu.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (48, 3, 9, 'Stoga reče učenicima neka mu se zbog mnoštva pripravi lađica da ga ne bi zgnjeli.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (48, 3, 10, 'Jer mnoge je ozdravio pa su se svi koji bijahu pogođeni kakvim zlom bacali na nj da bi ga se dotakli.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (48, 3, 11, 'A nečisti duhovi, čim bi ga spazili, padali bi preda nj i vikali: \"Ti si Sin Božji!\"');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (48, 3, 12, 'A on im se oštro prijetio da ga ne prokazuju.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (48, 3, 13, 'Uziđe na goru i pozove koje sam htjede. I dođoše k njemu.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (48, 3, 14, 'I ustanovi dvanaestoricu da budu s njime i da ih šalje propovijedati');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (48, 3, 15, 's vlašću da izgone đavle.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (48, 3, 16, 'Ustanovi dakle dvanaestoricu: Šimuna, kojemu nadjenu ime Petar,');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (48, 3, 17, 'i Jakova Zebedejeva i Ivana, brata Jakovljeva, kojima nadjenu ime Boanerges, to jest Sinovi groma,');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (48, 3, 18, 'i Andriju i Filipa i Bartolomeja i Mateja i Tomu i Jakova Alfejeva i Tadeja i Šimuna Kananajca');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (48, 3, 19, 'i Judu Iškariotskoga, koji ga izda.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (48, 3, 20, 'I dođe Isus u kuću. Opet se skupi toliko mnoštvo da nisu mogli ni jesti.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (48, 3, 21, 'Čuvši to, dođoše njegovi da ga obuzdaju jer se govorilo: \"Izvan sebe je!\"');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (48, 3, 22, 'I pismoznanci što siđoše iz Jeruzalema govorahu: \"Beelzebula ima, po poglavici đavolskom izgoni đavle.\"');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (48, 3, 23, 'A on ih dozva pa im u prispodobama govoraše: \"Kako može Sotona Sotonu izgoniti?');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (48, 3, 24, 'Ako se kraljevstvo u sebi razdijeli, ono ne može opstati.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (48, 3, 25, 'Ili: ako se kuća u sebi razdijeli, ona ne može opstati.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (48, 3, 26, 'Ako je dakle Sotona sam na sebe ustao i razdijelio se, ne može opstati, nego mu je kraj.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (48, 3, 27, 'Nitko, dakako, ne može u kuću jakoga ući i oplijeniti mu pokućstvo ako prije jakoga ne sveže. Tada će mu kuću oplijeniti!\"');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (48, 3, 28, 'Doista, kažem vam, sve će se oprostiti sinovima ljudskima, koliki god bili grijesi i hule kojima pohule.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (48, 3, 29, 'No pohuli li tko na Duha Svetoga, nema oproštenja dovijeka; krivac je grijeha vječnoga.\"');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (48, 3, 30, 'Jer govorahu: \"Duha nečistoga ima.\"');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (48, 3, 31, 'I dođu majka njegova i braća njegova. Ostanu vani, a k njemu pošalju neka ga pozovu.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (48, 3, 32, 'Oko njega je sjedjelo mnoštvo. I reknu mu: \"Eno vani majke tvoje i braće tvoje, traže te!\"');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (48, 3, 33, 'On im odgovori: \"Tko je majka moja i braća moja?\"');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (48, 3, 34, 'I okruži pogledom po onima što su sjedjeli oko njega u krugu i kaže: \"Evo majke moje, evo braće moje!');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (48, 3, 35, 'Tko god vrši volju Božju, on mi je brat i sestra i majka.\"');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (48, 4, 1, 'I poče opet poučavati uz more. I zgrnu se k njemu silan svijet te on uđe u lađu i sjede na moru, a sve ono mnoštvo bijaše uz more, na kopnu.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (48, 4, 2, 'Poučavao ih je u prispodobama mnogočemu. Govorio im u pouci:');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (48, 4, 3, '\"Poslušajte! Gle, iziđe sijač sijati.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (48, 4, 4, 'I dok je sijao, poneko zrno pade uz put, dođoše ptice i pozobaše ga.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (48, 4, 5, 'Neko opet pade na kamenito tlo gdje nemaše dosta zemlje. Odmah izniknu jer nemaše duboke zemlje.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (48, 4, 6, 'Ali kad ogranu sunce, izgorje; i jer nemaše korijenja, osuši se.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (48, 4, 7, 'Neko opet pade u trnje i trnje uzraste i uguši ga te ploda ne donese.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (48, 4, 8, 'Neko napokon pade u dobru zemlju i dade plod, razraste se i razmnoži, te donese: jedno tridesetostruko, jedno šezdesetostruko, jedno stostruko.\"');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (48, 4, 9, 'I doda: \"Tko ima uši da čuje, neka čuje!\"');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (48, 4, 10, 'Kad bijaše nasamo, oni oko njega zajedno s dvanaestoricom pitahu ga o prispodobama.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (48, 4, 11, 'I govoraše im: \"Vama je dano otajstvo kraljevstva Božjega, a onima vani sve biva u prispodobama:');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (48, 4, 12, 'da gledaju, gledaju - i ne vide, slušaju, slušaju - i ne razumiju, da se ne obrate pa da im se otpusti.\"');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (48, 4, 13, 'I kaže im: \"Zar ne znate tu prispodobu? Kako ćete onda razumjeti prispodobe uopće?');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (48, 4, 14, 'Sijač sije Riječ.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (48, 4, 15, 'Oni uz put, gdje je Riječ posijana, jesu oni kojima, netom čuju, odmah dolazi Sotona i odnosi Riječ u njih posijanu.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (48, 4, 16, 'Zasijani na tlo kamenito jesu oni koji kad čuju Riječ, odmah je s radošću prime,');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (48, 4, 17, 'ali nemaju u sebi korijena, nego su nestalni: kad nastane nevolja ili progonstvo zbog Riječi, odmah se sablazne.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (48, 4, 18, 'A drugi su oni u trnje zasijani. To su oni koji poslušaju Riječ,');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (48, 4, 19, 'ali nadošle brige vremenite, zavodljivost bogatstva i ostale požude uguše Riječ te ona ostane bez ploda.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (48, 4, 20, 'A zasijani na dobru zemlju jesu oni koji čuju i prime Riječ te urode: tridesetostruko, šezdesetostruko, stostruko.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (48, 4, 21, 'I govoraše im: \"Unosi li se svjetiljka da se pod posudu stavi ili pod postelju? Zar ne da se stavi na svijećnjak?');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (48, 4, 22, 'Ta ništa nije zastrto, osim zato da se očituje; i ništa skriveno, osim zato da dođe na vidjelo!');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (48, 4, 23, 'Ima li tko uši da čuje, neka čuje.\"');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (48, 4, 24, 'I govoraše im: \"Pazite što slušate. Mjerom kojom mjerite mjerit će vam se. I nadodat će vam se.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (48, 4, 25, 'Doista, onomu tko ima dat će se, a onomu tko nema oduzet će se i ono što ima.\"');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (48, 4, 26, 'I govoraše im: \"Kraljevstvo je Božje kao kad čovjek baci sjeme u zemlju.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (48, 4, 27, 'Spavao on ili bdio, noću i danju sjeme klija i raste - sam ne zna kako;');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (48, 4, 28, 'zemlja sama od sebe donosi plod: najprije stabljiku, onda klas i napokon puno zrnja na klasu.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (48, 4, 29, 'A čim plod dopusti, brže se on laća srpa jer eto žetve.\"');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (48, 4, 30, 'I govoraše: \"Kako da prispodobimo kraljevstvo nebesko ili u kojoj da ga prispodobi iznesemo?');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (48, 4, 31, 'Kao kad se gorušičino zrno posije u zemlju. Manje od svega sjemenja na zemlji,');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (48, 4, 32, 'jednoć posijano, naraste i postane veće od svega povrća pa potjera velike grane te se pod sjenom njegovom gnijezde ptice nebeske.\"');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (48, 4, 33, 'Mnogim takvim prispodobama navješćivaše im Riječ, kako već mogahu slušati.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (48, 4, 34, 'Bez prispodobe im ne govoraše, a nasamo bi svojim učenicima sve razjašnjavao.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (48, 4, 35, 'Uvečer istoga dana kaže im: \"Prijeđimo prijeko!\"');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (48, 4, 36, 'Oni otpuste mnoštvo i povezu Isusa kako već bijaše u lađi. A pratile su ga i druge lađe.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (48, 4, 37, 'Najednom nasta žestoka oluja, na lađu navale valovi te su je već gotovo napunili.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (48, 4, 38, 'A on na krmi spavaše na uzglavku. Probude ga i kažu mu: \"Učitelju! Zar ne mariš što ginemo?\"');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (48, 4, 39, 'On se probudi, zaprijeti vjetru i reče moru: \"Utihni! Umukni!\" I smiri se vjetar i nasta velika utiha.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (48, 4, 40, 'Tada im reče: \"Što ste bojažljivi? Kako nemate vjere?\"');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (48, 4, 41, 'Oni se silno prestrašiše pa se zapitkivahu: \"Tko li je ovaj da mu se i vjetar i more pokoravaju?\"');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (48, 5, 1, 'Stigoše na onu stranu mora, u kraj gerazenski.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (48, 5, 2, 'Čim iziđe iz lađe, odmah mu iz grobnica pohiti u susret neki čovjek s nečistim duhom.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (48, 5, 3, 'Obitavalište je imao u grobnicama. I nitko ga više nije mogao svezati ni lancima');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (48, 5, 4, 'jer je već često bio i okovima i lancima svezan, ali je raskinuo okove i iskidao lance i nitko ga nije mogao ukrotiti.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (48, 5, 5, 'Po cijele bi noći i dane u grobnicama i po brdima vikao i bio se kamenjem.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (48, 5, 6, 'Kad izdaleka opazi Isusa, dotrči i pokloni mu se,');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (48, 5, 7, 'a onda u sav glas povika: \"Što ti imaš sa mnom, Isuse, Sine Boga Svevišnjega? Zaklinjem te Bogom, ne muči me!\"');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (48, 5, 8, 'Jer Isus mu bijaše rekao: \"Iziđi, duše nečisti, iz ovoga čovjeka!\"');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (48, 5, 9, 'Isus ga nato upita: \"Kako ti je ime?\" Kaže mu: \"Legija mi je ime! Ima nas mnogo!\"');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (48, 5, 10, 'I uporno zaklinjaše Isusa da ih ne istjera iz onoga kraja.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (48, 5, 11, 'A ondje je pod brdom paslo veliko krdo svinja.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (48, 5, 12, 'Zaklinjahu ga dakle: \"Pošalji nas u ove svinje da u njih uđemo!\"');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (48, 5, 13, 'I on im dopusti. Tada iziđoše nečisti duhovi i uđoše u svinje. I krdo od oko dvije tisuće jurnu niz obronak u more i podavi se u moru.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (48, 5, 14, 'Svinjari pobjegoše i razglasiše gradom i selima. A ljudi pođoše vidjeti što se dogodilo.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (48, 5, 15, 'Dođu Isusu. Ugledaju opsjednutoga: sjedio je obučen i zdrave pameti - on koji ih je imao legiju. I prestraše se.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (48, 5, 16, 'A očevici im razlagahu kako je to bilo s opsjednutim i ono o svinjama.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (48, 5, 17, 'Tada ga stanu moliti da ode iz njihova kraja.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (48, 5, 18, 'Kad je ulazio u lađu, onaj što bijaše opsjednut molio ga da bude uza nj.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (48, 5, 19, 'No on mu ne dopusti, nego mu reče: \"Pođi kući k svojima pa im javi što ti je učinio Gospodin, kako ti se smilovao.\"');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (48, 5, 20, 'On ode i poče razglašavati po Dekapolu što mu učini Isus. I svi su se divili.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (48, 5, 21, 'Kad se Isus lađom ponovno prebacio prijeko, zgrnu se k njemu silan svijet.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (48, 5, 22, 'Stajao je uz more. I dođe, gle, jedan od nadstojnika sinagoge, imenom Jair. Ugledavši ga, padne mu pred noge');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (48, 5, 23, 'pa ga usrdno moljaše: \"Kćerkica mi je na umoru! Dođi, stavi ruke na nju da ozdravi i ostane u životu!\"');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (48, 5, 24, 'I pođe s njima. A za njim je išao silan svijet i pritiskao ga.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (48, 5, 25, 'A neka je žena dvanaest godina bolovala od krvarenja,');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (48, 5, 26, 'mnogo pretrpjela od pustih liječnika, razdala sve svoje i ništa nije koristilo; štoviše, bivalo joj je sve gore.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (48, 5, 27, 'Čuvši za Isusa, priđe mu među mnoštvom odostraga i dotaknu se njegove haljine.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (48, 5, 28, 'Mislila je: \"Dotaknem li se samo njegovih haljina, bit ću spašena.\"');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (48, 5, 29, 'I odmah prestane njezino krvarenje te osjeti u tijelu da je ozdravila od zla.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (48, 5, 30, 'Isus odmah u sebi osjeti da je iz njega izišla sila pa se okrenu usred mnoštva i reče: \"Tko se to dotaknu mojih haljina?\"');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (48, 5, 31, 'A učenici mu rekoše: \"Ta vidiš kako te mnoštvo odasvud pritišće i još pitaš: \'Tko me se to dotaknu?\'\"');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (48, 5, 32, 'A on zaokruži pogledom da vidi onu koja to učini.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (48, 5, 33, 'Žena, sva u strahu i trepetu, svjesna onoga što joj se dogodilo, pristupi i baci se preda nj pa mu kaza sve po istini.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (48, 5, 34, 'On joj reče: \"Kćeri, vjera te tvoja spasila! Pođi u miru i budi zdrava od svojega zla!\"');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (48, 5, 35, 'Dok je Isus još govorio, eto nadstojnikovih s porukom. \"Kći ti je umrla. Čemu dalje mučiti učitelja?\"');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (48, 5, 36, 'Isus je čuo taj razgovor, pa će nadstojniku: \"Ne boj se! Samo vjeruj!\"');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (48, 5, 37, 'I ne dopusti da ga itko drugi prati osim Petra i Jakova i Ivana, brata Jakovljeva.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (48, 5, 38, 'I dođu u kuću nadstojnikovu. Ugleda buku i one koji plakahu i naricahu u sav glas.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (48, 5, 39, 'Uđe i kaže im: \"Što bučite i plačete? Dijete nije umrlo, nego spava.\"');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (48, 5, 40, 'A oni mu se podsmjehivahu. No on ih sve izbaci, uzme sa sobom djetetova oca i majku i svoje pratioce pa uđe onamo gdje bijaše dijete.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (48, 5, 41, 'Primi dijete za ruku govoreći: \"Talita, kum!\" što znači: \"Djevojko! Zapovijedam ti, ustani!\"');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (48, 5, 42, 'I djevojka odmah usta i poče hodati. Bijaše joj dvanaest godina. I u tren ostadoše zapanjeni, u čudu veliku.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (48, 5, 43, 'On im dobro poprijeti neka toga nitko ne dozna; i reče da djevojci dadnu jesti.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (48, 6, 1, 'I otišavši odande, dođe u svoj zavičaj. A doprate ga učenici.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (48, 6, 2, 'I kada dođe subota, poče učiti u sinagogi. I mnogi što su ga slušali preneraženi govorahu: \"Odakle to ovome? Kakva li mu je mudrost dana? I kakva se to silna djela događaju po njegovim rukama?');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (48, 6, 3, 'Nije li ovo drvodjelja, sin Marijin, i brat Jakovljev, i Josipov, i Judin, i Šimunov? I nisu li mu sestre ovdje među nama?\" I sablažnjavahu se o njega.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (48, 6, 4, 'A Isus im govoraše: \"Nije prorok bez časti doli u svom zavičaju i među rodbinom i u svom domu.\"');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (48, 6, 5, 'I ne mogaše ondje učiniti ni jedno čudo, osim što ozdravi nekoliko nemoćnika stavivši ruke na njih.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (48, 6, 6, 'I čudio se njihovoj nevjeri. Obilazio je selima uokolo i naučavao.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (48, 6, 7, 'Dozva dvanaestoricu te ih poče slati dva po dva dajući im vlast nad nečistim dusima.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (48, 6, 8, 'I zapovjedi im da na put ne nose ništa osim štapa: ni kruha, ni torbe, ni novaca o pojasu,');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (48, 6, 9, 'nego da nose samo sandale i da ne oblače dviju haljina.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (48, 6, 10, 'I govoraše im: \"Kad uđete gdje u kuću, u njoj ostanite dok ne odete odande.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (48, 6, 11, 'Ako vas gdje ne prime te vas ne poslušaju, iziđite odande i otresite prah ispod svojih nogu njima za svjedočanstvo.\"');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (48, 6, 12, 'Otišavši, propovijedali su obraćenje,');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (48, 6, 13, 'izgonili mnoge zloduhe i mnoge su nemoćnike mazali uljem i oni su ozdravljali.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (48, 6, 14, 'Dočuo to i kralj Herod jer se razglasilo Isusovo ime te se govorilo: \"Ivan Krstitelj uskrsnuo od mrtvih i zato čudesne sile djeluju u njemu.\"');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (48, 6, 15, 'A drugi govorahu: \"Ilija je!\" Treći opet: \"Prorok, kao jedan od proroka.\"');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (48, 6, 16, 'Herod pak na to govoraše: \"Uskrsnu Ivan kojemu ja odrubih glavu.\"');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (48, 6, 17, 'Herod doista bijaše dao uhititi Ivana i svezati ga u tamnici zbog Herodijade, žene brata svoga Filipa, kojom se bio oženio.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (48, 6, 18, 'Budući da je Ivan govorio Herodu: \"Ne smiješ imati žene brata svojega!\",');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (48, 6, 19, 'Herodijada ga mrzila i htjela ga ubiti, ali nije mogla');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (48, 6, 20, 'jer se Herod bojao Ivana; znao je da je on čovjek pravedan i svet pa ga je štitio. I kad god bi ga slušao, uvelike bi se zbunio, a rado ga je slušao.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (48, 6, 21, 'I dođe zgodan dan kad Herod o svom rođendanu priredi gozbu svojim velikašima, časnicima i prvacima galilejskim.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (48, 6, 22, 'Uđe kći Herodijadina i zaplesa. Svidje se Herodu i sustolnicima. Kralj reče djevojci: \"Zaišti od mene što god hoćeš i dat ću ti!\"');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (48, 6, 23, 'I zakle joj se: \"Što god zaišteš od mene, dat ću ti, pa bilo to i pol mojega kraljevstva.\"');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (48, 6, 24, 'Ona iziđe pa će svojoj materi: \"Što da zaištem?\" A ona će: \"Glavu Ivana Krstitelja!\"');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (48, 6, 25, 'I odmah žurno uđe kralju te zaište: \"Hoću da mi odmah dadeš na pladnju glavu Ivana Krstitelja!\"');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (48, 6, 26, 'Ožalosti se kralj, ali zbog zakletve i sustolnika na htjede je odbiti.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (48, 6, 27, 'Kralj odmah posla krvnika i naredi da donese glavu Ivanovu. On ode, odrubi mu glavu u tamnici,');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (48, 6, 28, 'donese je na pladnju i dade je djevojci, a djevojka materi.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (48, 6, 29, 'Kad za to dočuše Ivanovi učenici, dođu, uzmu njegovo tijelo i polože ga u grob.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (48, 6, 30, 'Uto se apostoli skupe oko Isusa i izvijeste ga o svemu što su činili i naučavali.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (48, 6, 31, 'I reče im: \"Hajdete i vi u osamu na samotno mjesto, i otpočinite malo.\" Jer mnogo je svijeta dolazilo i odlazilo pa nisu imali kada ni jesti.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (48, 6, 32, 'Otploviše dakle lađom na samotno mjesto, u osamu.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (48, 6, 33, 'No kad su odlazili, mnogi ih vidješe i prepoznaše te se pješice iz svih gradova strčaše onamo i pretekoše ih.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (48, 6, 34, 'Kad iziđe, vidje silan svijet i sažali mu se jer bijahu kao ovce bez pastira pa ih stane poučavati u mnogočemu.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (48, 6, 35, 'A u kasni već sat pristupe mu učenici pa mu reknu: \"Pust je ovo kraj i već je kasno.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (48, 6, 36, 'Otpusti ih da odu po okolnim zaseocima i selima i kupe sebi što za jelo.\"');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (48, 6, 37, 'No on im odgovori: \"Podajte im vi jesti.\" Kažu mu: \"Da pođemo i kupimo za dvjesta denara kruha pa da im damo jesti?\"');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (48, 6, 38, 'A on će im: \"Koliko kruhova imate? Idite i vidite!\" Pošto izvidješe, kažu: \"Pet, i dvije ribe.\"');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (48, 6, 39, 'I zapovjedi im da sve, u skupinama, posjedaju po zelenoj travi.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (48, 6, 40, 'I pružiše se po sto i po pedeset na svaku lijehu.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (48, 6, 41, 'On uze pet kruhova i dvije ribe, pogleda na nebo, izreče blagoslov pa razlomi kruhove i davaše učenicima da posluže ljude. Tako i dvije ribe razdijeli svima.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (48, 6, 42, 'I jeli su svi i nasitili se.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (48, 6, 43, 'I od ulomaka nakupiše dvanaest punih košara, a i od riba.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (48, 6, 44, 'A jelo je pet tisuća muškaraca.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (48, 6, 45, 'On odmah prisili učenike da uđu u lađu i da se prebace prijeko, prema Betsaidi, dok on otpusti mnoštvo.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (48, 6, 46, 'I pošto se rasta s ljudima, otiđe u goru da se pomoli.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (48, 6, 47, 'Uvečer pak lađa bijaše posred mora, a on sam na kraju.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (48, 6, 48, 'Vidjevši kako se muče veslajući, jer im bijaše protivan vjetar, oko četvrte noćne straže dođe k njima hodeći po moru. I htjede ih mimoići.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (48, 6, 49, 'A oni, vidjevši kako hodi po moru, pomisliše da je utvara pa kriknuše.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (48, 6, 50, 'Jer svi su ga vidjeli i prestrašili se. A on im odmah progovori: \"Hrabro samo! Ja sam! Ne bojte se!\"');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (48, 6, 51, 'I uziđe k njima u lađu, a vjetar utihnu. I veoma se, prekomjerno, snebivahu;');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (48, 6, 52, 'još ne shvatiše ono o kruhovima, nego im srce bijaše stvrdnuto.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (48, 6, 53, 'Pošto doploviše na kraj, dođu u Genezaret i pristanu.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (48, 6, 54, 'Kad iziđu iz lađe, ljudi ga odmah prepoznaju');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (48, 6, 55, 'pa oblete sav onaj kraj. I počnu donositi na nosilima bolesnike onamo gdje bi čuli da se on nalazi.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (48, 6, 56, 'I kamo bi god ulazio - u sela, u gradove, u zaseoke - po trgovima bi stavljali bolesnike i molili ga da se dotaknu makar skuta njegove haljine. I koji bi ga se god dotakli, ozdravljali bi.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (48, 7, 1, 'Skupe se oko njega farizeji i neki od pismoznanaca koji dođoše iz Jeruzalema.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (48, 7, 2, 'I opaze da neki njegovi učenici jedu kruh nečistih, to jest neopranih ruku.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (48, 7, 3, 'A farizeji i svi Židovi ne jedu ako prije temeljito ne operu ruke; drže se predaje starih.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (48, 7, 4, 'Niti s trga što jedu ako prije ne operu. Mnogo toga još ima što zbog predaje drže: pranje čaša, vrčeva i lonaca.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (48, 7, 5, 'Zato farizeji i pismoznanci upitaju Isusa: \"Zašto tvoji učenici ne postupaju po predaji starih, nego nečistih ruku blaguju?\"');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (48, 7, 6, 'A on im reče: \"Dobro prorokova Izaija o vama, licemjeri, kad napisa: Ovaj me narod usnama časti, a srce mu je daleko od mene.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (48, 7, 7, 'Uzalud me štuju naučavajući nauke - uredbe ljudske.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (48, 7, 8, 'Napustili ste zapovijed Božju, a držite se predaje ljudske.\"');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (48, 7, 9, 'Još im govoraše: \"Lijepo! Dokidate Božju zapovijed da biste sačuvali svoju predaju.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (48, 7, 10, 'Mojsije doista reče: Poštuj oca svoga i majku svoju. I: Tko prokune oca ili majku, smrću neka se kazni.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (48, 7, 11, 'A vi velite: \'Rekne li tko ocu ili majci: Pomoć koja te od mene ide neka bude \'korban\', to jest sveti dar\',');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (48, 7, 12, 'takvome više ne dopuštate ništa učiniti za oca ili majku.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (48, 7, 13, 'Tako dokidate riječ Božju svojom predajom, koju sami sebi predadoste. I još štošta tomu slično činite.\"');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (48, 7, 14, 'Tada ponovno dozove mnoštvo i stane govoriti: \"Poslušajte me svi i razumijte!');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (48, 7, 15, 'Ništa što izvana ulazi u čovjeka ne može ga onečistiti, nego što iz čovjeka izlazi - to ga onečišćuje.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (48, 7, 16, 'Tko ima uši da čuje, neka čuje!\"');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (48, 7, 17, 'I kad od mnoštva uđe u kuću, upitaše ga učenici za prispodobu.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (48, 7, 18, 'I reče im: \"Tako? Ni vi ne razumijete? Ne shvaćate li da čovjeka ne može onečistiti što u nj ulazi');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (48, 7, 19, 'jer mu ne ulazi u srce, nego u utrobu te izlazi u zahod?\" Tako on očisti sva jela.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (48, 7, 20, 'Još dometnu: \"Što iz čovjeka izlazi, te onečišćuje čovjeka.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (48, 7, 21, 'Ta iznutra, iz srca čovječjega, izlaze zle namisli, bludništva, krađe, ubojstva,');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (48, 7, 22, 'preljubi, lakomstva, opakosti, prijevara, razuzdanost, zlo oko, psovka, uznositost, bezumlje.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (48, 7, 23, 'Sva ta zla iznutra izlaze i onečišćuju čovjeka.\"');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (48, 7, 24, 'Odande otiđe u kraj tirski. I uđe u neku kuću. Htio je da nitko ne sazna, ali se nije mogao sakriti,');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (48, 7, 25, 'nego odmah doču žena koje kćerkica imaše duha nečistoga. Ona dođe i pade mu pred noge.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (48, 7, 26, 'A žena bijaše Grkinja, Sirofeničanka rodom. I moljaše ga da joj iz kćeri istjera zloduha.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (48, 7, 27, 'A on joj govoraše: \"Pusti da se prije nasite djeca! Ne priliči uzeti kruh djeci i baciti ga psićima.\"');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (48, 7, 28, 'A ona će mu: \"Da, Gospodine! Ali i psići ispod stola jedu od mrvica dječjih.\"');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (48, 7, 29, 'Reče joj: \"Zbog te riječi idi, izišao je iz tvoje kćeri zloduh.\"');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (48, 7, 30, 'I ode kući te nađe dijete gdje leži na postelji, a zloduh je bio izišao.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (48, 7, 31, 'Zatim se ponovno vrati iz krajeva tirskih pa preko Sidona dođe Galilejskom moru, u krajeve dekapolske.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (48, 7, 32, 'Donesu mu nekoga gluhog mucavca pa ga zamole da stavi na nj ruku.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (48, 7, 33, 'On ga uzme nasamo od mnoštva, utisne svoje prste u njegove uši, zatim pljune i dotakne se njegova jezika.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (48, 7, 34, 'Upravi pogled u nebo, uzdahne i kaže mu: \"Effata!\" - to će reći: \"Otvori se!\"');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (48, 7, 35, 'I odmah mu se otvoriše uši i razdriješi spona jezika te stade govoriti razgovijetno.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (48, 7, 36, 'A Isus im zabrani da nikome ne kazuju. No što im je on više branio, oni su to više razglašavali');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (48, 7, 37, 'i preko svake mjere zadivljeni govorili: \"Dobro je sve učinio! Gluhima daje čuti, nijemima govoriti!\"');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (48, 8, 1, 'Onih se dana opet skupio silan svijet. Budući da nisu imali što jesti, dozva Isus učenike pa im reče:');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (48, 8, 2, '\"Žao mi je naroda jer su već tri dana uza me i nemaju što jesti.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (48, 8, 3, 'Ako ih otpravim gladne njihovim kućama, klonut će putom. A neki su od njih došli iz daleka.\"');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (48, 8, 4, 'Učenici mu odgovore: \"Otkuda bi ih tko ovdje u pustinji mogao nahraniti kruhom?\"');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (48, 8, 5, 'On ih zapita: \"Koliko kruhova imate?\" Oni odgovore: \"Sedam.\"');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (48, 8, 6, 'Nato zapovjedi mnoštvu da posjeda po zemlji. I uze sedam kruhova, zahvali, razlomi i davaše svojim učenicima da posluže. I poslužiše mnoštvu.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (48, 8, 7, 'A imali su i malo ribica. Blagoslovi i njih te reče da i to posluže.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (48, 8, 8, 'I jeli su i nasitili se. A od preteklih ulomaka odniješe sedam košara.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (48, 8, 9, 'Bilo ih je oko četiri tisuće. Tada ih otpusti,');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (48, 8, 10, 'a sam sa svojim učenicima odmah uđe u lađu i ode u kraj dalmanutski.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (48, 8, 11, 'Tada istupiše farizeji i počeše raspravljati s njime. Iskušavajući ga, zatraže od njega znak s neba.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (48, 8, 12, 'On uzdahnu iz sve duše i reče: \"Zašto ovaj naraštaj traži znak? Zaista, kažem vam, ovome se naraštaju neće dati znak.\"');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (48, 8, 13, 'Tada ih ostavi, ponovno uđe u lađu pa otiđe prijeko.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (48, 8, 14, 'A zaboraviše ponijeti kruha; imali su samo jedan kruh sa sobom na lađi.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (48, 8, 15, 'Nato ih Isus opomenu: \"Pazite, čuvajte se kvasca farizejskog i kvasca Herodova!\"');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (48, 8, 16, 'Oni, zamišljeni, među sobom govorahu: \"Kruha nemamo.\"');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (48, 8, 17, 'Zamijetio to Isus pa im reče: \"Zašto ste zamišljeni što kruha nemate? Zar još ne shvaćate i ne razumijete? Zar vam je srce stvrdnuto?');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (48, 8, 18, 'Oči imate, a ne vidite; uši imate, a ne čujete? Zar se ne sjećate?');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (48, 8, 19, 'Kad sam ono razlomio pet kruhova na pet tisuća, koliko punih košara ulomaka odnijeste?\" Kažu mu: \"Dvanaest.\"');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (48, 8, 20, '\"A kada razlomih sedam na četiri tisuće, koliko punih košara ulomaka odnijeste?\" Odgovore: \"Sedam.\"');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (48, 8, 21, 'A on će njima: \"I još ne razumijete?\"');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (48, 8, 22, 'Dođu u Betsaidu, dovedu mu slijepca pa ga zamole da ga se dotakne.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (48, 8, 23, 'On uhvati slijepca za ruku, izvede ga iz sela, pljunu mu u oči, stavi na nj ruke i zapita ga: \"Vidiš li što?\"');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (48, 8, 24, 'Slijepac upilji pogled i reče: \"Opažam ljude; vidim nešto kao drveće... hodaju.\"');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (48, 8, 25, 'Tada mu Isus opet stavi ruke na oči i slijepac progleda i ozdravi te je mogao sve jasno na daleko vidjeti.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (48, 8, 26, 'Tada ga posla kući i reče mu: \"Ne ulazi u selo.\"');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (48, 8, 27, 'I krenu Isus i njegovi učenici u sela Cezareje Filipove. Putem on upita učenike: \"Što govore ljudi, tko sam ja?\"');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (48, 8, 28, 'Oni mu rekoše: \"Da si Ivan Krstitelj, drugi da si Ilija, treći opet da si neki od proroka.\"');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (48, 8, 29, 'On njih upita: \"A vi, što vi kažete, tko sam ja?\" Petar prihvati i reče: \"Ti si Pomazanik - Krist!\"');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (48, 8, 30, 'I zaprijeti im da nikomu ne kazuju o njemu.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (48, 8, 31, 'I poče ih poučavati kako Sin Čovječji treba da mnogo pretrpi, da ga starješine, glavari svećenički i pismoznanci odbace, da bude ubijen i nakon tri dana da ustane.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (48, 8, 32, 'Otvoreno im to govoraše. Petar ga uze u stranu i poče odvraćati.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (48, 8, 33, 'A on se okrenu, pogleda svoje učenike pa zaprijeti Petru: \"Nosi se od mene, sotono, jer ti nije na pameti što je Božje, nego što je ljudsko!\"');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (48, 8, 34, 'Tada dozva narod i učenike pa im reče: \"Hoće li tko za mnom, neka se odrekne samoga sebe, neka uzme svoj križ i neka ide za mnom.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (48, 8, 35, 'Tko hoće život svoj spasiti, izgubit će ga; a tko izgubi život svoj poradi mene i evanđelja, spasit će ga.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (48, 8, 36, 'Ta što koristi čovjeku steći sav svijet, a životu svojemu nauditi?');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (48, 8, 37, 'Ta što da čovjek dadne u zamjenu za život svoj?');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (48, 8, 38, 'Doista, tko se zastidi mene i mojih riječi u ovom preljubničkom i grešničkom naraštaju - njega će se stidjeti i Sin Čovječji kada dođe u slavi Oca svoga zajedno sa svetim anđelima.\"');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (48, 9, 1, 'Još im govoraše: \"Zaista, kažem vam, neki od ovdje nazočnih neće okusiti smrti dok ne vide da je kraljevstvo Božje došlo u sili.\"');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (48, 9, 2, 'Nakon šest dana uze Isus sa sobom Petra, Jakova i Ivana i povede ih na goru visoku, u osamu, same, i preobrazi se pred njima.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (48, 9, 3, 'I haljine mu postadoše sjajne, bijele veoma - nijedan ih bjelilac na zemlji ne bi mogao tako izbijeliti.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (48, 9, 4, 'I ukaza im se Ilija s Mojsijem te razgovarahu s Isusom.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (48, 9, 5, 'A Petar prihvati i reče Isusu: \"Učitelju, dobro nam je ovdje biti! Načinimo tri sjenice: tebi jednu, Mojsiju jednu i Iliji jednu.\"');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (48, 9, 6, 'Doista nije znao što da kaže jer bijahu prestrašeni.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (48, 9, 7, 'I pojavi se oblak i zasjeni ih, a iz oblaka se začu glas: \"Ovo je Sin moj, Ljubljeni! Slušajte ga!\"');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (48, 9, 8, 'I odjednom, obazrevši se uokolo, nikoga uza se ne vidješe doli Isusa sama.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (48, 9, 9, 'Dok su silazili s gore, naloži im da nikomu ne pripovijedaju što su vidjeli dok Sin Čovječji od mrtvih ne ustane.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (48, 9, 10, 'Oni održaše tu riječ, ali se među sobom pitahu što znači to njegovo \"od mrtvih ustati\"');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (48, 9, 11, 'pa ga upitaju: \"Zašto pismoznanci govore da prije treba da dođe Ilija?\"');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (48, 9, 12, 'A on im reče: \"Ilija će, doduše, prije doći i sve obnoviti. Pa kako ipak piše o Sinu Čovječjem da će mnogo pretrpjeti i biti prezren?');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (48, 9, 13, 'Ali, velim vam: Ilija je već došao i oni učiniše s njim što im se prohtjelo, kao što piše o njemu.\"');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (48, 9, 14, 'Kada dođoše k učenicima, ugledaše oko njih silan svijet i pismoznance kako raspravljaju s njima.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (48, 9, 15, 'Čim ga sve ono mnoštvo ugleda, iznenađeno brže pohrli pozdraviti ga.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (48, 9, 16, 'A on ih upita: \"Što to raspravljaste s njima?\"');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (48, 9, 17, 'Odvrati netko iz mnoštva: \"Učitelju, dovedoh k tebi svoga sina koji ima nijemoga duha.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (48, 9, 18, 'Gdje ga god zgrabi, obara ga, a on pjeni, škripi zubima i koči se. Rekoh tvojim učenicima da ga izagnaju, ali ne mogoše.\"');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (48, 9, 19, 'On im odvrati: \"O rode nevjerni! Dokle mi je biti s vama? Dokle li vas podnositi? Dovedite ga k meni!\"');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (48, 9, 20, 'I dovedoše ga k njemu. Čim zloduh ugleda Isusa, potrese dječakom i on se, oboren na zemlju, stane valjati i pjeniti.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (48, 9, 21, 'Isus upita njegova oca: \"Koliko je vremena kako mu se to događa?\" On reče: \"Od djetinjstva!');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (48, 9, 22, 'A često ga znade baciti i u vatru i u vodu da ga upropasti. Nego, ako što možeš, pomozi nam, imaj samilosti s nama!\"');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (48, 9, 23, 'Nato mu Isus reče: \"Što? Ako možeš? Sve je moguće onomu koji vjeruje!\"');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (48, 9, 24, 'Dječakov otac brže povika: \"Vjerujem! Pomozi mojoj nevjeri!\"');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (48, 9, 25, 'Vidjevši da svijet odasvud grne, Isus zaprijeti nečistomu duhu: \"Nijemi i gluhi duše, ja ti zapovijedam, iziđi iz njega i da nisi više u nj ušao!\"');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (48, 9, 26, 'Zloduh nato zaviče, žestoko strese dječaka te iziđe, a on osta kao mrtav te su mnogi govorili da je umro.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (48, 9, 27, 'No Isus ga dohvati za ruku, podiže ga i on ustade.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (48, 9, 28, 'Kad Isus uđe u kuću, upitaše ga učenici nasamo: \"Kako to da ga mi ne mogosmo izagnati?\"');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (48, 9, 29, 'Odgovori im: \"Ovaj se rod ničim drugim ne može izagnati osim molitvom i postom.\"');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (48, 9, 30, 'Otišavši odande, prolažahu kroz Galileju. On ne htjede da to itko sazna.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (48, 9, 31, 'Jer poučavaše svoje učenike. Govoraše im: \"Sin Čovječji predaje se u ruke ljudima. Ubit će ga, ali će on, ubijen, nakon tri dana ustati.\"');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (48, 9, 32, 'No oni ne razumješe te besjede, a bojahu ga se pitati.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (48, 9, 33, 'I dođoše u Kafarnaum. I već u kući upita ih: \"Što ste putem raspravljali?\"');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (48, 9, 34, 'A oni umukoše jer putem među sobom razgovarahu o tome tko je najveći.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (48, 9, 35, 'On sjede i dozove dvanaestoricu te im reče: \"Ako tko želi biti prvi, neka bude od svih posljednji i svima poslužitelj!\"');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (48, 9, 36, 'I uzme dijete, postavi ga posred njih, zagrli ga i reče im:');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (48, 9, 37, '\"Tko god jedno ovakvo dijete primi u moje ime, mene prima. A tko mene prima, ne prima mene, nego onoga koji mene posla.\"');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (48, 9, 38, 'Reče mu Ivan: \"Učitelju, vidjesmo jednoga kako u tvoje ime izgoni zloduhe. Mi smo mu branili jer ne ide s nama.\"');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (48, 9, 39, 'A Isus reče: \"Ne branite mu! Jer nitko ne može učiniti nešto silno u moje ime pa me ubrzo zatim pogrditi.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (48, 9, 40, 'Tko nije protiv nas, za nas je.\"');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (48, 9, 41, '\"Uistinu, tko vas napoji čašom vode u ime toga što ste Kristovi, zaista, kažem vam, neće mu propasti plaća.\"');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (48, 9, 42, '\"Onomu naprotiv tko bi sablaznio jednoga od ovih najmanjih što vjeruju, daleko bi bolje bilo da s mlinskim kamenom o vratu bude bačen u more.\"');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (48, 9, 43, '\"Pa ako te ruka sablažnjava, odsijeci je. Bolje ti je sakatu ući u život, nego s obje ruke otići u pakao, u oganj neugasivi.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (48, 9, 44, '#');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (48, 9, 45, 'I ako te noga sablažnjava, odsijeci je. Bolje ti je hromu ući u život, nego s obje noge bit bačen u pakao.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (48, 9, 46, '#');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (48, 9, 47, 'I ako te oko sablažnjava, iskopaj ga. Bolje ti je jednooku ući u kraljevstvo Božje, nego s oba oka biti bačen u pakao,');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (48, 9, 48, 'gdje crv njihov ne gine niti se oganj gasi.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (48, 9, 49, 'Uistinu, ognjem će svaki od njih biti posoljen.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (48, 9, 50, 'Dobra je sol. Ali ako sol postane neslana, čime ćete nju začiniti? Imajte sol u sebi, a mir među sobom!\"');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (48, 10, 1, 'Krenuvši odande, dođe u judejski kraj i na onu stranu Jordana. I opet mnoštvo nagrnu k njemu, a on ih po svojem običaju ponovno poučavaše.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (48, 10, 2, 'A pristupe farizeji pa, da ga iskušaju, upitaše: \"Je li mužu dopušteno otpustiti ženu?\"');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (48, 10, 3, 'On im odgovori: \"Što vam zapovjedi Mojsije?\"');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (48, 10, 4, 'Oni rekoše: \"Mojsije je dopustio napisati otpusno pismo i - otpustiti.\"');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (48, 10, 5, 'A Isus će im: \"Zbog okorjelosti srca vašega napisa vam on tu zapovijed.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (48, 10, 6, 'Od početka stvorenja muško i žensko stvori ih.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (48, 10, 7, 'Stoga će čovjek ostaviti oca i majku da prione uza svoju ženu;');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (48, 10, 8, 'i dvoje njih bit će jedno tijelo. Tako više nisu dvoje, nego jedno tijelo.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (48, 10, 9, 'Što dakle Bog združi, čovjek neka ne rastavlja!\"');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (48, 10, 10, 'U kući su ga učenici ponovno o tome ispitivali.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (48, 10, 11, 'I reče im: \"Tko otpusti svoju ženu pa se oženi drugom, čini prema prvoj preljub.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (48, 10, 12, 'I ako žena napusti svoga muža pa se uda za drugoga, čini preljub.\"');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (48, 10, 13, 'Donosili mu dječicu da ih se dotakne, a učenici im branili.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (48, 10, 14, 'Opazivši to, Isus se ozlovolji i reče im: \"Pustite dječicu neka dolaze k meni; ne priječite im jer takvih je kraljevstvo Božje!');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (48, 10, 15, 'Zaista, kažem vam, tko ne primi kraljevstva Božjega kao dijete, ne, u nj neće ući.\"');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (48, 10, 16, 'Nato ih zagrli pa ih blagoslivljaše polažući na njih ruke.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (48, 10, 17, 'I dok je izlazio na put, dotrči netko, klekne preda nj pa ga upita: \"Učitelju dobri, što mi je činiti da baštinim život vječni?\"');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (48, 10, 18, 'Isus mu reče: \"Što me zoveš dobrim? Nitko nije dobar doli Bog jedini!');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (48, 10, 19, 'Zapovijedi znadeš: Ne ubij! Ne čini preljuba! Ne ukradi! Ne svjedoči lažno! Ne otmi! Poštuj oca svoga i majku!\"');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (48, 10, 20, 'On mu odgovori: \"Učitelju, sve sam to čuvao od svoje mladosti.\"');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (48, 10, 21, 'Isus ga nato pogleda, zavoli ga i rekne mu: \"Jedno ti nedostaje! Idi i što imaš, prodaj i podaj siromasima pa ćeš imati blago na nebu. A onda dođi i idi za mnom.\"');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (48, 10, 22, 'On se na tu riječ smrkne i ode žalostan jer imaše velik imetak.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (48, 10, 23, 'Isus zaokruži pogledom pa će svojim učenicima: \"Kako li će teško imućnici u kraljevstvo Božje!\"');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (48, 10, 24, 'Učenici ostadoše zapanjeni tim njegovim riječima. Zato im Isus ponovi: \"Djeco, kako je teško u kraljevstvo Božje!');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (48, 10, 25, 'Lakše je devi kroz ušice iglene nego bogatašu u kraljevstvo Božje.\"');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (48, 10, 26, 'Oni se još većma snebivahu te će jedan drugome: \"Pa tko se onda može spasiti?\"');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (48, 10, 27, 'Isus upre u njih pogled i reče: \"Ljudima je nemoguće, ali ne Bogu! Ta Bogu je sve moguće!\"');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (48, 10, 28, 'Petar mu poče govoriti: \"Evo, mi sve ostavismo i pođosmo za tobom.\"');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (48, 10, 29, 'Reče Isus: \"Zaista, kažem vam, nema ga tko ostavi kuću, ili braću, ili sestre, ili majku, ili oca, ili djecu, ili polja poradi mene i poradi evanđelja,');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (48, 10, 30, 'a da ne bi sada, u ovom vremenu, s progonstvima primio stostruko kuća, i braće, i sestara, i majki, i djece, i polja - i u budućem vijeku život vječni.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (48, 10, 31, 'A mnogi prvi bit će posljednji i posljednji prvi.\"');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (48, 10, 32, 'Putovali su tako uzlazeći u Jeruzalem. Isus je išao pred njima te bijahu zaprepašteni, a oni koji su išli za njima, prestrašeni. Tada Isus opet uze dvanaestoricu i poče im kazivati što će ga zadesiti:');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (48, 10, 33, '\"Evo, uzlazimo u Jeruzalem i Sin Čovječji bit će predan glavarima svećeničkim i pismoznancima. Osudit će ga na smrt, predati poganima,');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (48, 10, 34, 'izrugati i popljuvati. Izbičevat će ga, ubit će ga, ali on će nakon tri dana ustati.\"');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (48, 10, 35, 'I pristupe mu Jakov i Ivan, sinovi Zebedejevi, govoreći mu: \"Učitelju, htjeli bismo da nam učiniš što te zaištemo.\"');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (48, 10, 36, 'A on će im: \"Što hoćete da vam učinim?\"');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (48, 10, 37, 'Oni mu rekoše: \"Daj nam da ti u slavi tvojoj sjednemo jedan zdesna, a drugi slijeva.\"');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (48, 10, 38, 'A Isus im reče: \"Ne znate što ištete. Možete li piti čašu koju ja pijem, ili krstiti se krstom kojim se ja krstim?\"');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (48, 10, 39, 'Oni mu rekoše: \"Možemo.\" A Isus će im: \"Čašu koju ja pijem pit ćete i krstom kojim se ja krstim bit ćete kršteni,');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (48, 10, 40, 'ali sjesti meni zdesna ili slijeva nisam ja vlastan dati - to je onih kojima je pripravljeno.\"');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (48, 10, 41, 'Kad su to čula ostala desetorica, počeše se gnjeviti na Jakova i Ivana.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (48, 10, 42, 'Zato ih Isus dozva i reče im: \"Znate da oni koji se smatraju vladarima gospoduju svojim narodima i velikaši njihovi drže ih pod vlašću.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (48, 10, 43, 'Nije tako među vama! Naprotiv, tko hoće da među vama bude najveći, neka vam bude poslužitelj!');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (48, 10, 44, 'I tko hoće da među vama bude prvi, neka bude svima sluga.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (48, 10, 45, 'Jer ni Sin Čovječji nije došao da bude služen, nego da služi i život svoj dade kao otkupninu za mnoge.\"');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (48, 10, 46, 'Dođu tako u Jerihon. Kad je Isus s učenicima i sa silnim mnoštvom izlazio iz Jerihona, kraj puta je sjedio slijepi prosjak Bartimej, sin Timejev.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (48, 10, 47, 'Kad je čuo da je to Isus Nazarećanin, stane vikati: \"Sine Davidov, Isuse, smiluj mi se!\"');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (48, 10, 48, 'Mnogi ga ušutkivahu, ali on još jače vikaše: \"Sine Davidov, smiluj mi se!\"');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (48, 10, 49, 'Isus se zaustavi i reče: \"Pozovite ga!\" I pozovu slijepca sokoleći ga: \"Ustani! Zove te!\"');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (48, 10, 50, 'On baci sa sebe ogrtač, skoči i dođe Isusu.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (48, 10, 51, 'Isus ga upita: \"Što hoćeš da ti učinim?\" Slijepac mu reče: \"Učitelju moj, da progledam.\"');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (48, 10, 52, 'Isus će mu: \"Idi, vjera te tvoja spasila!\" I on odmah progleda i uputi se za njim.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (48, 11, 1, 'Kad se približe Jeruzalemu, Betfagi i Betaniji, do Maslinske gore, pošalje dva učenika');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (48, 11, 2, 'i kaže im: \"Hajdete u selo pred vama. Čim u nj uđete, naći ćete privezano magare koje još nitko nije zajahao. Odriješite ga i vodite.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (48, 11, 3, 'Ako vam tko reče: \'Što to radite?\' recite: \'Gospodinu treba\', i odmah će ga ipak ovamo pustiti.\"');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (48, 11, 4, 'Otiđoše i nađoše magare privezano uz vrata vani na cesti i odriješe ga.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (48, 11, 5, 'A neki od nazočnih upitaše: \"Što radite? Što driješite magare?\"');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (48, 11, 6, 'Oni im odvrate kako im reče Isus. I pustiše ih.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (48, 11, 7, 'I dovedu magare Isusu, prebace preko njega svoje haljine i on zajaha na nj.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (48, 11, 8, 'Mnogi prostriješe svoje haljine po putu, a drugi narezaše zelenih grana po poljima.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (48, 11, 9, 'I oni pred njim i oni za njim klicahu: \"Hosana! Blagoslovljen Onaj koji dolazi u ime Gospodnje!');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (48, 11, 10, 'Blagoslovljeno kraljevstvo oca našega Davida koji dolazi! Hosana u visinama!\"');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (48, 11, 11, 'I uđe u Jeruzalem, u Hram. I sve uokolo razgleda, pa kako već bijaše kasno, pođe s dvanaestoricom u Betaniju.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (48, 11, 12, 'Sutradan su izlazili iz Betanije, a on ogladnje.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (48, 11, 13, 'Ugleda izdaleka lisnatu smokvu i priđe ne bi li na njoj što našao. Ali došavši bliže, ne nađe ništa osim lišća jer ne bijaše vrijeme smokvama.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (48, 11, 14, 'Tada reče smokvi: \"Nitko nikada više ne jeo s tebe!\" Čuli su to njegovi učenici.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (48, 11, 15, 'Stignu tako u Jeruzalem. On uđe u Hram i stane izgoniti one koji su prodavali i kupovali u Hramu. Mjenjačima isprevrta stolove i prodavačima golubova klupe.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (48, 11, 16, 'I ne dopusti da itko išta pronese kroz Hram.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (48, 11, 17, 'Učio ih je i govorio: \"Nije li pisano: Dom će se moj zvati Dom molitve za sve narode? A vi od njega načinili pećinu razbojničku!\"');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (48, 11, 18, 'Kada su za to dočuli glavari svećenički i pismoznanci, tražili su kako da ga pogube. Uistinu, bojahu ga se jer je sav narod bio očaran njegovim naukom.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (48, 11, 19, 'A kad se uvečerilo, izlazili su iz grada.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (48, 11, 20, 'Kad su ujutro prolazili mimo one smokve, opaze da je usahla do korijena.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (48, 11, 21, 'Petar se prisjeti pa će Isusu: \"Učitelju, pogledaj! Smokva koju si prokleo usahnu.\"');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (48, 11, 22, 'Isus im odvrati: \"Imajte vjeru Božju.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (48, 11, 23, 'Zaista, kažem vam, rekne li tko ovoj gori: \'Digni se i baci u more!\' i u srcu svome ne posumnja, nego vjeruje da će se dogoditi to što kaže - doista, bit će mu!');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (48, 11, 24, 'Stoga vam kažem: Sve što god zamolite i zaištete, vjerujte da ste postigli i bit će vam!');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (48, 11, 25, 'No kad ustanete na molitvu, otpustite ako što imate protiv koga da i vama Otac vaš, koji je na nebesima, otpusti vaše prijestupke.\"');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (48, 11, 26, '#');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (48, 11, 27, 'I dođu opet u Jeruzalem. Dok je obilazio Hramom, dođu k njemu glavari svećenički, pismoznanci i starješine.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (48, 11, 28, 'I govorahu mu: \"Kojom vlašću to činiš? Ili tko ti dade tu vlast da to činiš?\"');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (48, 11, 29, 'A Isus im reče: \"Jedno ću vas upitati. Odgovorite mi, pa ću vam kazati kojom vlašću ovo činim.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (48, 11, 30, 'Krst Ivanov bijaše li od Neba ili od ljudi? Odgovorite mi!\"');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (48, 11, 31, 'A oni umovahu među sobom: \"Reknemo li \'od Neba\', odvratit će \'Zašto mu dakle ne povjerovaste?\'');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (48, 11, 32, 'Nego, da reknemo \'od ljudi!\'\" - Bojahu se mnoštva. Ta svi Ivana smatrahu doista prorokom.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (48, 11, 33, 'I odgovore Isusu: \"Ne znamo.\" A Isus će im: \"Ni ja vama neću kazati kojom vlašću ovo činim.\"');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (48, 12, 1, 'I uze im zboriti u prispodobama: Čovjek vinograd posadi, ogradom ogradi, iskopa tijesak i kulu podiže pa ga iznajmi vinogradarima i otputova.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (48, 12, 2, 'I u svoje vrijeme posla vinogradarima slugu da od njih uzme dio uroda vinogradarskoga.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (48, 12, 3, 'A oni ga pograbiše, istukoše i otposlaše praznih ruku.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (48, 12, 4, 'I opet posla k njima drugog slugu: i njemu razbiše glavu i izružiše ga.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (48, 12, 5, 'Trećega također posla: njega ubiše. Tako i mnoge druge: jedne istukoše, druge pobiše.\"');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (48, 12, 6, '\"Još jednoga imaše, sina ljubljenoga. Njega naposljetku posla k njima misleći: \'Poštovat će sina moga.\'');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (48, 12, 7, 'Ali ti vinogradari među sobom rekoše: \'Ovo je baštinik! Hajde da ga ubijemo i baština će biti naša.\'');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (48, 12, 8, 'I pograbe ga, ubiju i izbace iz vinograda.\"');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (48, 12, 9, '\"Što li će učiniti gospodar vinograda? Doći će i pobiti te vinogradare i dati vinograd drugima.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (48, 12, 10, 'Niste li čitali ovo Pismo: Kamen što ga odbaciše graditelji, postade kamen zaglavni.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (48, 12, 11, 'Gospodnje je to djelo - kakvo čudo u očima našim!\"');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (48, 12, 12, 'I tražili su da ga uhvate, ali se pobojaše mnoštva. Razumješe da je protiv njih izrekao prispodobu pa ga ostave i odu.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (48, 12, 13, 'I pošalju k njemu neke od farizeja i herodovaca da ga uhvate u riječi.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (48, 12, 14, 'Oni dođu i kažu mu: \"Učitelju, znamo da si istinit i ne mariš tko je tko jer nisi pristran, nego po istini učiš putu Božjemu. Je li dopušteno dati porez caru ili nije? Da damo ili da ne damo?\"');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (48, 12, 15, 'A on im reče prozirući njihovo licemjerje: \"Što me iskušavate? Donesite mi denar da vidim!\"');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (48, 12, 16, 'Oni doniješe. I reče im: \"Čija je ovo slika i natpis?\" A oni će mu: \"Carev.\"');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (48, 12, 17, 'A Isus im reče: \"Caru podajte carevo, a Bogu Božje!\" I divili su mu se.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (48, 12, 18, 'Dođu k njemu saduceji, koji vele da nema uskrsnuća, i upitaju ga:');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (48, 12, 19, '\"Učitelju, Mojsije nam napisa: Umre li čiji brat i ostavi ženu, a ne ostavi djeteta, neka njegov brat uzme tu ženu te podigne porod bratu svomu.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (48, 12, 20, 'Sedmero braće bijaše. Prvi uze ženu i umrije ne ostavivši poroda.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (48, 12, 21, 'I drugi je uze te umrije ne ostavivši poroda. I treći jednako tako.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (48, 12, 22, 'I sedmorica ne ostaviše poroda. Najposlije i žena umrije.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (48, 12, 23, 'Komu će biti žena o uskrsnuću, kad uskrsnu? Jer sedmorica su je imala za ženu.\"');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (48, 12, 24, 'Reče im Isus: \"Niste li u zabludi zbog toga što ne razumijete Pisama ni sile Božje?');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (48, 12, 25, 'Ta kad od mrtvih ustaju, niti se žene niti udavaju, nego su kao anđeli na nebesima.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (48, 12, 26, 'A što se tiče mrtvih, da ustaju, niste li čitali u knjizi Mojsijevoj ono o grmu, kako Mojsiju reče Bog: Ja sam Bog Abrahamov i Bog Izakov i Bog Jakovljev?');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (48, 12, 27, 'Nije on Bog mrtvih, nego živih. Uvelike se varate.\"');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (48, 12, 28, 'Tada pristupi jedan od pismoznanaca koji je slušao njihovu raspravu. Vidjevši da im je dobro odgovorio, upita ga: \"Koja je zapovijed prva od sviju?\"');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (48, 12, 29, 'Isus odgovori: \"Prva je: Slušaj, Izraele! Gospodin Bog naš Gospodin je jedini.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (48, 12, 30, 'Zato ljubi Gospodina Boga svojega iz svega srca svojega, i iz sve duše svoje, i iz svega uma svoga, i iz sve snage svoje!\"');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (48, 12, 31, '\"Druga je: Ljubi svoga bližnjega kao sebe samoga. Nema druge zapovijedi veće od tih.\"');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (48, 12, 32, 'Nato će mu pismoznanac: \"Dobro, učitelju! Po istini si kazao: On je jedini, nema drugoga osim njega.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (48, 12, 33, 'Njega ljubiti iz svega srca, iz svega razuma i iz sve snage i ljubiti bližnjega kao sebe samoga - više je nego sve paljenice i žrtve.\"');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (48, 12, 34, 'Kad Isus vidje kako je pametno odgovorio, reče mu: \"Nisi daleko od kraljevstva Božjega!\" I nitko se više nije usuđivao pitati ga.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (48, 12, 35, 'A naučavajući u Hramu, uze Isus govoriti: \"Kako pismoznanci kažu da je Krist sin Davidov?');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (48, 12, 36, 'A sam David reče u Duhu Svetome: Reče Gospod Gospodinu mojemu: \'Sjedni mi zdesna dok ne položim neprijatelje tvoje za podnožje nogama tvojim!\'');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (48, 12, 37, 'Sam ga David zove Gospodinom. Kako mu je onda sin?\" Silan ga je svijet s užitkom slušao.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (48, 12, 38, 'A on im u pouci svojoj govoraše: \"Čuvajte se pismoznanaca, koji rado idu u dugim haljinama, vole pozdrave na trgovima,');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (48, 12, 39, 'prva sjedala u sinagogama i pročelja na gozbama;');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (48, 12, 40, 'proždiru kuće udovičke, još pod izlikom dugih molitava. Stići će ih to oštrija osuda!\"');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (48, 12, 41, 'Potom sjede nasuprot riznici te promatraše kako narod baca sitniš u riznicu. Mnogi bogataši bacahu mnogo.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (48, 12, 42, 'Dođe i neka siromašna udovica i baci dva novčića, to jest jedan kvadrant.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (48, 12, 43, 'Tada dozove svoje učenike i reče im: \"Doista, kažem vam, ova je sirota udovica ubacila više od svih koji ubacuju u riznicu.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (48, 12, 44, 'Svi su oni zapravo ubacili od svoga suviška, a ona je od svoje sirotinje ubacila sve što je imala, sav svoj žitak.\"');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (48, 13, 1, 'Kad je izlazio iz Hrama, rekne mu jedan od njegovih učenika: \"Učitelju, gledaj! Kakva li kamenja, kakvih li zdanja!\"');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (48, 13, 2, 'Isus mu odvrati: \"Vidiš li ta veličanstvena zdanja? Ne, neće se ostaviti ni kamen na kamenu nerazvaljen.\"');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (48, 13, 3, 'Dok je zatim na Maslinskoj gori sjedio sučelice Hramu, upitaju ga nasamo Petar, Jakov, Ivan i Andrija:');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (48, 13, 4, '\"Reci nam kada će to biti i na koji se znak sve to ima svršiti?\"');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (48, 13, 5, 'Tada im Isus poče govoriti: \"Pazite da vas tko ne zavede.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (48, 13, 6, 'Mnogi će doći u moje ime i govoriti: Ja sam! I mnoge će zavesti.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (48, 13, 7, 'Kada pak čujete za ratove i za glasove o ratovima, ne uznemirujte se. Treba da se to dogodi, ali to još nije svršetak.\"');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (48, 13, 8, '\"Narod će ustati protiv naroda, kraljevstvo protiv kraljevstva. Bit će potresa po raznim mjestima, bit će gladi. To je početak trudova.\"');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (48, 13, 9, '\"Vi pak pazite sami na sebe. Predavat će vas vijećima i tući vas u sinagogama, pred upraviteljima i kraljevima stajat ćete zbog mene, njima za svjedočanstvo.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (48, 13, 10, 'A treba da se najprije svim narodima propovijeda evanđelje.\"');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (48, 13, 11, '\"Kad vas budu vodili na izručenje, ne brinite se unaprijed što ćete govoriti, nego govorite što vam bude dano u onaj čas. Ta niste vi koji govorite, nego Duh Sveti.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (48, 13, 12, 'Predavat će na smrt brat brata i otac sina. Djeca će ustajati na roditelje i ubijati ih.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (48, 13, 13, 'Svi će vas zamrziti zbog imena moga. Ali tko ustraje do svršetka, bit će spašen.\"');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (48, 13, 14, '\"I kad vidite da grozota pustoši stoluje gdje joj nije mjesto - tko čita, neka razumije - koji se tada zateknu u Judeji, neka bježe u gore!');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (48, 13, 15, 'Tko bude na krovu, neka ne silazi i ne ulazi u kuću da iz nje što uzme.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (48, 13, 16, 'I tko bude u polju, neka se ne okreće natrag da uzme ogrtač!\"');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (48, 13, 17, '\"Jao trudnicama i dojiljama u one dane!');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (48, 13, 18, 'A molite da to ne bude zimi');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (48, 13, 19, 'jer će onih dana biti tjeskoba kakve ne bi od početka stvorenja, koje stvori Bog, sve do sada, a neće je ni biti.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (48, 13, 20, 'I kad Gospodin ne bi skratio dane one, nitko se ne bi spasio. No poradi izabranih, koje on sebi izabra, skratio je on te dane.\"');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (48, 13, 21, 'Ako vam tada tko rekne: \'Evo Krista ovdje! Eno ondje!\' - ne vjerujte.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (48, 13, 22, 'Ustat će doista lažni kristi i lažni proroci i tvorit će znamenja i čudesa da, bude li moguće, zavedu izabrane.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (48, 13, 23, 'Vi dakle budite na oprezu! Evo, prorekao sam vam sve!\"');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (48, 13, 24, 'Nego, u one dane, nakon one nevolje, sunce će pomrčati i mjesec neće više svijetljeti');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (48, 13, 25, 'a zvijezde će s neba padati i sile će se nebeske poljuljati.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (48, 13, 26, 'Tada će ugledati Sina Čovječjega gdje dolazi na oblacima s velikom moći i slavom.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (48, 13, 27, 'I razaslat će anđele i sabrati svoje izabranike s četiri vjetra, s kraja zemlje do na kraj neba.\"');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (48, 13, 28, 'A od smokve se naučite prispodobi! Kad joj grana već omekša i lišće potjera, znate: ljeto je blizu.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (48, 13, 29, 'Tako i vi kad vidite da se to zbiva, znajte: blizu je, na vratima!');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (48, 13, 30, 'Zaista, kažem vam, ne, neće uminuti naraštaj ovaj dok se sve to ne zbude.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (48, 13, 31, 'Nebo će i zemlja uminuti, ali riječi moje ne, neće uminuti.\"');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (48, 13, 32, '\"A o onom danu i času nitko ne zna, pa ni anđeli na nebu, ni Sin, nego samo Otac.\"');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (48, 13, 33, '\"Pazite! Bdijte jer ne znate kada je čas.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (48, 13, 34, 'Kao kad ono čovjek neki polazeći na put ostavi svoju kuću, upravu povjeri slugama, svakomu svoj posao, a vrataru zapovjedi da bdije.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (48, 13, 35, 'Bdijte, dakle, jer ne znate kad će se domaćin vratiti - da li uvečer ili o ponoći, da li za prvih pijetlova ili ujutro -');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (48, 13, 36, 'da vas ne bi našao pozaspale ako iznenada dođe.\"');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (48, 13, 37, '\"Što vama kažem, svima kažem: Bdijte!\"');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (48, 14, 1, 'Za dva dana bijaše Pasha i Beskvasni kruhovi. Glavari svećenički i pismoznanci tražili su kako da ga na prijevaru uhvate i ubiju.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (48, 14, 2, 'Jer se govorilo: \"Nikako ne na Blagdan da ne nastane pobuna naroda.\"');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (48, 14, 3, 'I kad je u Betaniji, u kući Šimuna Gubavca, bio za stolom, dođe neka žena s alabastrenom posudicom prave skupocjene nardove pomasti. Razbi posudicu i poli ga po glavi.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (48, 14, 4, 'A neki negodovahu te će jedan drugomu: \"Čemu to rasipanje pomasti?');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (48, 14, 5, 'Mogla se pomast prodati za više od tristo denara i dati siromasima.\" I otresahu se na nju.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (48, 14, 6, 'A Isus reče: \"Pustite je, što joj dodijavate? Dobro djelo učini na meni.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (48, 14, 7, 'Ta siromaha svagda imate uza se i kad god hoćete možete im dobro činiti, a mene nemate svagda.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (48, 14, 8, 'Učinila je što je mogla: unaprijed mi pomaza tijelo za ukop.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (48, 14, 9, 'Zaista, kažem vam, gdje se god bude propovijedalo evanđelje, po svem svijetu, navješćivat će se i ovo što ona učini - njoj na spomen.\"');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (48, 14, 10, 'A Juda Iškariotski, jedan od dvanaestorice, ode glavarima svećeničkim da im ga preda.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (48, 14, 11, 'Kad su oni to čuli, obradovali su se i obećali mu dati novca. I tražio je zgodu da ga preda.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (48, 14, 12, 'Prvoga dana Beskvasnih kruhova, kad se žrtvovala pasha, upitaju učenici Isusa: \"Gdje hoćeš blagovati pashu, da odemo i pripravimo?\"');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (48, 14, 13, 'On pošalje dvojicu učenika i rekne im: \"Idite u grad i namjerit ćete se na čovjeka koji nosi krčag vode. Pođite za njim');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (48, 14, 14, 'pa gdje on uđe, recite domaćinu: \'Učitelj pita: Gdje mi je svratište u kojem bih blagovao pashu sa svojim učenicima?\'');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (48, 14, 15, 'I on će vam pokazati na katu veliko blagovalište, prostrto i spremljeno. Ondje nam pripravite.\"');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (48, 14, 16, 'Učenici odu, dođu u grad i nađu kako im on reče te priprave pashu.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (48, 14, 17, 'A uvečer dođe on s dvanaestoricom.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (48, 14, 18, 'I dok bijahu za stolom te blagovahu, reče Isus: \"Zaista, kažem vam, jedan će me od vas izdati - koji sa mnom blaguje.\"');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (48, 14, 19, 'Ožalošćeni, stanu mu govoriti jedan za drugim: \"Da nisam ja?\"');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (48, 14, 20, 'A on im reče: \"Jedan od dvanaestorice koji umače sa mnom u zdjelicu.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (48, 14, 21, 'Sin Čovječji, istina, odlazi kako je o njemu pisano, ali jao čovjeku onomu koji ga predaje. Tomu bi čovjeku bolje bilo da se ni rodio nije!\"');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (48, 14, 22, 'I dok su blagovali, on uze kruh, izreče blagoslov pa razlomi, dade im i reče: \"Uzmite, ovo je tijelo moje.\"');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (48, 14, 23, 'I uze čašu, zahvali i dade im. I svi su iz nje pili.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (48, 14, 24, 'A on im reče: \"Ovo je krv moja, krv Saveza, koja se za mnoge prolijeva.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (48, 14, 25, 'Zaista, kažem vam, ne, neću više piti od ovoga roda trsova do onoga dana kad ću ga - novoga - piti u kraljevstvu Božjem.\"');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (48, 14, 26, 'Otpjevavši hvalospjeve, zaputiše se prema Maslinskoj gori.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (48, 14, 27, 'I reče im Isus: \"Svi ćete se sablazniti. Ta pisano je: Udarit ću pastira i ovce će se razbjeći.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (48, 14, 28, 'Ali kad uskrsnem, ići ću pred vama u Galileju.\"');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (48, 14, 29, 'Nato će mu Petar: \"Ako se i svi sablazne, ja neću!\"');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (48, 14, 30, 'A Isus mu reče: \"Zaista, kažem ti, baš ti, danas, ove noći, prije nego se pijetao dvaput oglasi, triput ćeš me zatajiti.\"');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (48, 14, 31, 'Ali on je upornije uvjeravao: \"Bude li trebalo i umrijeti s tobom - ne, neću te zatajiti.\" A tako su svi govorili.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (48, 14, 32, 'I dođu u predio imenom Getsemani. I kaže Isus svojim učenicima: \"Sjednite ovdje dok se ne pomolim.\"');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (48, 14, 33, 'I povede sa sobom Petra, Jakova i Ivana. Spopade ga užas i tjeskoba');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (48, 14, 34, 'pa im reče: \"Duša mi je nasmrt žalosna! Ostanite ovdje i bdijte!\"');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (48, 14, 35, 'Ode malo dalje i rušeći se na zemlju molio je da ga, ako je moguće, mimoiđe ovaj čas.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (48, 14, 36, 'Govoraše: \"Abba! Oče! Tebi je sve moguće! Otkloni čašu ovu od mene! Ali ne što ja hoću, nego što hoćeš ti!\"');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (48, 14, 37, 'I dođe, nađe ih pozaspale pa reče Petru: \"Šimune, spavaš? Jedan sat nisi mogao probdjeti?');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (48, 14, 38, 'Bdijte i molite da ne padnete u napast. Duh je, istina, voljan, no tijelo je slabo.\"');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (48, 14, 39, 'Opet ode i pomoli se istim riječima.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (48, 14, 40, 'Ponovno dođe i nađe ih pozaspale. Oči im se sklapale i nisu znali što da mu odgovore.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (48, 14, 41, 'Dođe i treći put i reče im: \"Samo spavajte i počivajte! Gotovo je! Dođe čas! Evo, predaje se Sin Čovječji u ruke grešničke!');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (48, 14, 42, 'Ustanite, hajdemo! Evo, izdajica se moj približio!\"');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (48, 14, 43, 'Uto, dok je on još govorio, stiže Juda, jedan od dvanaestorice, i s njime svjetina s mačevima i toljagama, poslana od glavara svećeničkih, pismoznanaca i starješina.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (48, 14, 44, 'A izdajica im njegov dade znak: \"Koga poljubim, taj je! Uhvatite ga i oprezno odvedite!\"');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (48, 14, 45, 'I kako dođe, odmah pristupi k njemu i reče: \"Učitelju!\" I poljubi ga.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (48, 14, 46, 'Oni podignu na nj ruke i uhvate ga.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (48, 14, 47, 'A jedan od nazočnih trgnu mač, udari slugu velikoga svećenika i odsiječe mu uho.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (48, 14, 48, 'Isus im prozbori: \"Kao na razbojnika iziđoste s mačevima i toljagama da me uhvatite.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (48, 14, 49, 'Danomice bijah vam u Hramu, naučavah i ne uhvatiste me. No neka se ispune Pisma!\"');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (48, 14, 50, 'I svi ga ostave i pobjegnu.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (48, 14, 51, 'A jedan je mladić išao za njim, ogrnut samo plahtom. I njega htjedoše uhvatiti,');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (48, 14, 52, 'no on ostavi plahtu i gol pobježe.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (48, 14, 53, 'Zatim odvedoše Isusa velikom svećeniku. I skupe se svi glavari svećenički, starješine i pismoznanci.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (48, 14, 54, 'Petar je izdaleka išao za njim do u dvor velikog svećenika. Tu je sjedio sa stražarima i grijao se uz vatru.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (48, 14, 55, 'A glavari svećenički i cijelo Vijeće, da bi mogli pogubiti Isusa, tražili su protiv njega kakvo svjedočanstvo, ali nikako da ga nađu.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (48, 14, 56, 'Mnogi su doduše lažno svjedočili protiv njega, ali im se svjedočanstva ne slagahu.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (48, 14, 57, 'Ustali su neki i lažno svjedočili protiv njega:');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (48, 14, 58, '\"Mi smo ga čuli govoriti: \'Ja ću razvaliti ovaj rukotvoreni Hram i za tri dana sagraditi drugi, nerukotvoreni!\'\"');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (48, 14, 59, 'Ali ni u tom im svjedočanstvo ne bijaše složno.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (48, 14, 60, 'Usta nato veliki svećenik na sredinu i upita Isusa: \"Zar ništa ne odgovaraš? Što to ovi svjedoče protiv tebe?');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (48, 14, 61, 'A on je šutio i ništa mu nije odgovarao. Veliki ga svećenik ponovo upita: \"Ti li si Krist, Sin Blagoslovljenoga?\"');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (48, 14, 62, 'A Isus mu reče: \"Ja jesam! I gledat ćete Sina Čovječjega gdje sjedi zdesna Sile i dolazi s oblacima nebeskim.\"');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (48, 14, 63, 'Nato veliki svećenik razdrije haljine i reče: \"Što nam još trebaju svjedoci?');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (48, 14, 64, 'Čuli ste hulu. Što vam se čini?\" Oni svi presudiše da zaslužuje smrt.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (48, 14, 65, 'I neki stanu pljuvati po njemu, zastirati mu lice i udarati ga govoreći: \"Proreci!\" I sluge ga stadoše pljuskati.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (48, 14, 66, 'I dok je Petar bio dolje u dvoru, dođe jedna sluškinja velikoga svećenika;');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (48, 14, 67, 'ugledavši Petra gdje se grije, upre u nj pogled i reče: \"I ti bijaše s Nazarećaninom, Isusom.\"');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (48, 14, 68, 'On zanijeka: \"Niti znam niti razumijem što govoriš.\" I iziđe van u predvorje, a pijetao se oglasi.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (48, 14, 69, 'Sluškinja ga ugleda i poče opet govoriti nazočnima: \"Ovaj je od njih!\"');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (48, 14, 70, 'On opet nijekaše. Domalo nazočni opet stanu govoriti Petru: \"Doista, i ti si od njih! Ta Galilejac si!\"');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (48, 14, 71, 'On se tada stane kleti i preklinjati: \"Ne znam čovjeka o kom govorite!\"');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (48, 14, 72, 'I odmah se po drugi put oglasi pijetao. I spomenu se Petar one besjede, kako mu ono Isus reče: \"Prije nego se pijetao dvaput oglasi, triput ćeš me zatajiti.\" I briznu u plač.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (48, 15, 1, 'Odmah izjutra glavari svećenički zajedno sa starješinama i pismoznancima - cijelo Vijeće - upriličili su vijećanje pa Isusa svezali, odveli i predali Pilatu.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (48, 15, 2, 'I upita ga Pilat: \"Ti li si kralj židovski?\" On mu odgovori: \"Ti kažeš.\"');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (48, 15, 3, 'I glavari ga svećenički teško optuživahu.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (48, 15, 4, 'Pilat ga opet upita: \"Ništa ne odgovaraš? Gle, koliko te optužuju.\"');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (48, 15, 5, 'A Isus ništa više ne odgovori te se Pilat čudio.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (48, 15, 6, 'O Blagdanu bi im pustio uznika koga bi zaiskali.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (48, 15, 7, 'A zajedno s pobunjenicima koji u pobuni počiniše umorstvo bijaše u okove bačen čovjek zvani Baraba.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (48, 15, 8, 'I uziđe svjetina te poče od Pilata iskati ono što im običavaše činiti.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (48, 15, 9, 'A on im odgovori: \"Hoćete li da vam pustim kralja židovskoga?\"');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (48, 15, 10, 'Znao je doista da ga glavari svećenički bijahu predali iz zavisti.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (48, 15, 11, 'Ali glavari svećenički podjare svjetinu da traži neka im radije pusti Barabu.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (48, 15, 12, 'Pilat ih opet upita: \"Što dakle da učinim s ovim kojega zovete kraljem židovskim?\"');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (48, 15, 13, 'A oni opet povikaše: \"Raspni ga!\"');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (48, 15, 14, 'Reče im Pilat: \"Ta što je zla učinio?\" Povikaše još jače: \"Raspni ga!\"');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (48, 15, 15, 'Hoteći ugoditi svjetini, Pilat im pusti Barabu, a Isusa izbičeva i preda da se razapne.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (48, 15, 16, 'Vojnici ga odvedu u unutarnjost dvora, to jest u pretorij, pa sazovu cijelu četu');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (48, 15, 17, 'i zaogrnu ga grimizom; spletu trnov vijenac i stave mu na glavu');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (48, 15, 18, 'te ga stanu pozdravljati: \"Zdravo, kralju židovski!\"');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (48, 15, 19, 'I udarahu ga trskom po glavi, pljuvahu po njemu i klanjahu mu se prigibajući koljena.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (48, 15, 20, 'A pošto ga izrugaše, svukoše mu grimiz i obukoše mu njegove haljine. I izvedu ga da ga razapnu.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (48, 15, 21, 'I prisile nekog prolaznika koji je dolazio s polja, Šimuna Cirenca, oca Aleksandrova i Rufova, da mu ponese križ.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (48, 15, 22, 'I dovuku ga na mjesto Golgotu, što znači Lubanjsko mjesto.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (48, 15, 23, 'I nuđahu mu piti namirisana vina, ali on ne uze.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (48, 15, 24, 'Kad ga razapeše, razdijele među se haljine njegove bacivši za njih kocku - što će tko uzeti.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (48, 15, 25, 'A bijaše treća ura kad ga razapeše.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (48, 15, 26, 'Bijaše napisan i natpis o njegovoj krivici: \"Kralj židovski.\"');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (48, 15, 27, 'A zajedno s njime razapnu i dva razbojnika, jednoga njemu zdesna, drugoga slijeva.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (48, 15, 28, '#');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (48, 15, 29, 'Prolaznici su ga pogrđivali mašući glavama: \"Ej, ti, koji razvaljuješ Hram i sagradiš ga za tri dana,');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (48, 15, 30, 'spasi sam sebe, siđi s križa!\"');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (48, 15, 31, 'Slično i glavari svećenički s pismoznancima rugajući se govorahu jedni drugima: \"Druge je spasio, sebe ne može spasiti!');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (48, 15, 32, 'Krist, kralj Izraelov! Neka sad siđe s križa da vidimo i povjerujemo!\" Vrijeđahu ga i oni koji bijahu s njim raspeti.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (48, 15, 33, 'A o šestoj uri tama nasta po svoj zemlji - sve do ure devete.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (48, 15, 34, 'O devetoj uri povika Isus iza glasa: \"Eloi, Eloi lama sabahtani?\" To znači: \"Bože moj, Bože moj, zašto si me ostavio?\"');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (48, 15, 35, 'Neki od nazočnih čuvši to govorahu: \"Gle, Iliju zove.\"');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (48, 15, 36, 'A jedan otrča, natopi spužvu octom, natakne na trsku i pruži mu piti govoreći: \"Pustite da vidimo hoće li doći Ilija da ga skine.\"');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (48, 15, 37, 'A Isus zavapi jakim glasom i izdahnu.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (48, 15, 38, 'I zavjesa se hramska razdrije nadvoje, odozgor dodolje.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (48, 15, 39, 'A kad satnik koji stajaše njemu nasuprot vidje da tako izdahnu, reče: \"Zaista, ovaj čovjek bijaše Sin Božji!\"');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (48, 15, 40, 'Izdaleka promatrahu i neke žene: među njima Marija Magdalena i Marija, majka Jakova Mlađega i Josipa, i Saloma -');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (48, 15, 41, 'te su ga pratile kad bijaše u Galileji i posluživale mu - i mnoge druge koje uziđoše s njim u Jeruzalem.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (48, 15, 42, 'A uvečer, budući da je bila Priprava, to jest predvečerje subote,');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (48, 15, 43, 'dođe Josip iz Arimateje, ugledan vijećnik, koji također isčekivaše kraljevstvo Božje: odvaži se, uđe k Pilatu i zaiska tijelo Isusovo.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (48, 15, 44, 'Pilat se začudi da je već umro pa dozva satnika i upita ga je li odavna umro.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (48, 15, 45, 'Kad sazna od satnika, darova Josipu tijelo.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (48, 15, 46, 'Josip kupi platno, skine tijelo i zavije ga u platno te položi u grob, koji bijaše izduben iz stijene. I dokotrlja kamen na grobna vrata.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (48, 15, 47, 'A Marija Magdalena i Marija Josipova promatrahu kamo ga polažu.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (48, 16, 1, 'Kad prođe subota, Marija Magdalena i Marija Jakovljeva i Saloma kupiše miomirisa da odu pomazati Isusa.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (48, 16, 2, 'I prvoga dana u tjednu, veoma rano, o izlasku sunčevu, dođu na grob.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (48, 16, 3, 'I razgovarahu među sobom: \"Tko će nam otkotrljati kamen s vrata grobnih?\"');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (48, 16, 4, 'Pogledaju, a ono kamen otkotrljan. Bijaše doista veoma velik.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (48, 16, 5, 'I ušavši u grob, ugledaju mladića zaogrnuta bijelom haljinom gdje sjedi zdesna. I preplaše se.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (48, 16, 6, 'A on će im: \"Ne plašite se! Isusa tražite, Nazarećanina, Raspetoga? Uskrsnu! Nije ovdje! Evo mjesta kamo ga položiše.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (48, 16, 7, 'Nego idite, recite njegovim učenicima i Petru: Ide pred vama u Galileju! Ondje ćete ga vidjeti, kamo vam reče!\"');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (48, 16, 8, 'One iziđu i stanu bježati od groba: spopade ih strah i trepet. I nikomu ništa ne rekoše jer se bojahu.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (48, 16, 9, 'Uskrsnuvši dakle rano prvog dana u tjednu, ukaza se najprije Mariji Magdaleni iz koje bijaše istjerao sedam zloduha.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (48, 16, 10, 'Ona ode i dojavi njegovima, tužnima i zaplakanima.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (48, 16, 11, 'Kad su oni čuli da je živ i da ga je ona vidjela, ne povjerovaše.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (48, 16, 12, 'Nakon toga ukazao se u drugome obličju dvojici od njih na putu dok su išli u selo.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (48, 16, 13, 'I oni odu i dojave drugima. Ni njima ne povjerovaše.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (48, 16, 14, 'Napokon se ukaza jedanaestorici dok bijahu za stolom. Prekori njihovu nevjeru i okorjelost srca što ne povjerovaše onima koji ga vidješe uskrsla od mrtvih.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (48, 16, 15, 'I reče im: \"Pođite po svem svijetu, propovijedajte evanđelje svemu stvorenju.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (48, 16, 16, 'Tko uzvjeruje i pokrsti se, spasit će se, a tko ne uzvjeruje, osudit će se.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (48, 16, 17, 'A ovi će znakovi pratiti one koji uzvjeruju: u ime će moje izganjati zloduhe, novim će jezicima zboriti,');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (48, 16, 18, 'zmije uzimati; i popiju li što smrtonosno, ne, neće im nauditi; na nemoćnike će ruke polagati, i bit će im dobro.\"');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (48, 16, 19, 'I Gospodin Isus, pošto im to reče, bude uzet na nebo i sjede zdesna Bogu.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (48, 16, 20, 'Oni pak odoše i propovijedahu posvuda, a Gospodin surađivaše i utvrđivaše Riječ popratnim znakovima.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (49, 1, 1, 'Kad već mnogi poduzeše sastaviti izvješće o događajima koji se ispuniše među nama -');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (49, 1, 2, 'kako nam to predadoše oni koji od početka bijahu očevici i sluge Riječi -');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (49, 1, 3, 'pošto sam sve, od početka, pomno ispitao, naumih i ja tebi, vrli Teofile, sve po redu napisati');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (49, 1, 4, 'da se tako osvjedočiš o pouzdanosti svega u čemu si poučen.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (49, 1, 5, 'U dane Heroda, kralja judejskoga, bijaše neki svećenik imenom Zaharija iz razreda Abijina. Žena mu bijaše od kćeri Aronovih, a ime joj Elizabeta.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (49, 1, 6, 'Oboje bijahu pravedni pred Bogom: živjeli su besprijekorno po svim zapovijedima i odredbama Gospodnjim.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (49, 1, 7, 'No nisu imali djeteta jer Elizabeta bijaše nerotkinja, a oboje već poodmakle dobi.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (49, 1, 8, 'Dok je Zaharija jednom po redu svoga razreda obavljao svećeničku službu pred Bogom,');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (49, 1, 9, 'ždrijebom ga zapade po bogoslužnom običaju da uđe u Svetište Gospodnje i prinese kad.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (49, 1, 10, 'Za vrijeme kađenice sve je ono mnoštvo naroda vani molilo.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (49, 1, 11, 'A njemu se ukaza anđeo Gospodnji. Stajao je s desne strane kadionoga žrtvenika.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (49, 1, 12, 'Ugledavši ga, Zaharija se prepade i strah ga spopade.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (49, 1, 13, 'No anđeo mu reče: \"Ne boj se, Zaharija! Uslišana ti je molitva: žena će ti Elizabeta roditi sina. Nadjenut ćeš mu ime Ivan.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (49, 1, 14, 'Bit će ti radost i veselje i rođenje će njegovo mnoge obradovati.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (49, 1, 15, 'Bit će doista velik pred Gospodinom. Ni vina ni drugoga opojnog pića neće piti. Duha Svetoga bit će pun već od majčine utrobe.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (49, 1, 16, 'Mnoge će sinove Izraelove obratiti Gospodinu, Bogu njihovu.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (49, 1, 17, 'Ići će pred njim u duhu i sili Ilijinoj da obrati srce otaca k sinovima i nepokorne k razumnosti pravednih te spremi Gospodinu narod pripravan.\"');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (49, 1, 18, 'Nato Zaharija reče anđelu: \"Po čemu ću ja to razaznati. Ta star sam i žena mi poodmakle dobi.\"');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (49, 1, 19, 'Anđeo mu odgovori: \"Ja sam Gabriel koji stojim pred Bogom. Poslan sam da govorim s tobom i da ti donesem ovu radosnu poruku.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (49, 1, 20, 'I evo, budući da nisi povjerovao mojim riječima, koje će se ispuniti u svoje vrijeme, zanijemjet ćeš i nećeš moći govoriti do dana dok se to ne zbude.\"');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (49, 1, 21, 'Narod je iščekivao Zahariju i čudio se što se toliko zadržao u Svetištu.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (49, 1, 22, 'Kad je napokon izašao, nije im mogao ništa reći pa zaključiše da je u Svetištu imao viđenje. Nastojao im se doduše izraziti znakovima, ali osta nijem.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (49, 1, 23, 'Kad se navršiše dani njegove službe, otiđe kući.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (49, 1, 24, 'Nakon tih dana zatrudnje Elizabeta, njegova žena. Krila se pet mjeseci govoreći:');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (49, 1, 25, '\"Evo, to mi je učinio Gospodin u dane kad mu se svidje skinuti s mene sramotu među ljudima.\"');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (49, 1, 26, 'U šestome mjesecu posla Bog anđela Gabriela u galilejski grad imenom Nazaret');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (49, 1, 27, 'k djevici zaručenoj s mužem koji se zvao Josip iz doma Davidova; a djevica se zvala Marija.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (49, 1, 28, 'Anđeo uđe k njoj i reče: \"Zdravo, milosti puna! Gospodin s tobom!\"');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (49, 1, 29, 'Na tu se riječ ona smete i stade razmišljati kakav bi to bio pozdrav.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (49, 1, 30, 'No anđeo joj reče: \"Ne boj se, Marijo! Ta našla si milost u Boga.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (49, 1, 31, 'Evo, začet ćeš i roditi sina i nadjenut ćeš mu ime Isus.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (49, 1, 32, 'On će biti velik i zvat će se Sin Svevišnjega. Njemu će Gospodin Bog dati prijestolje Davida, oca njegova,');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (49, 1, 33, 'i kraljevat će nad domom Jakovljevim uvijeke i njegovu kraljevstvu neće biti kraja.\"');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (49, 1, 34, 'Nato će Marija anđelu: \"Kako će to biti kad ja muža ne poznajem?\"');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (49, 1, 35, 'Anđeo joj odgovori: \"Duh Sveti sići će na te i sila će te Svevišnjega osjeniti. Zato će to čedo i biti sveto, Sin Božji.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (49, 1, 36, 'A evo tvoje rođakinje Elizabete: i ona u starosti svojoj zače sina. I njoj, nerotkinjom prozvanoj, ovo je već šesti mjesec.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (49, 1, 37, 'Ta Bogu ništa nije nemoguće!\"');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (49, 1, 38, 'Nato Marija reče: \"Evo službenice Gospodnje, neka mi bude po tvojoj riječi!\" I anđeo otiđe od nje.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (49, 1, 39, 'Tih dana usta Marija i pohiti u Gorje, u grad Judin.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (49, 1, 40, 'Uđe u Zaharijinu kuću i pozdravi Elizabetu.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (49, 1, 41, 'Čim Elizabeta začu Marijin pozdrav, zaigra joj čedo u utrobi. I napuni se Elizabeta Duha Svetoga');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (49, 1, 42, 'i povika iz svega glasa: \"Blagoslovljena ti među ženama i blagoslovljen plod utrobe tvoje!');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (49, 1, 43, 'Ta otkuda meni da mi dođe majka Gospodina mojega?');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (49, 1, 44, 'Gledaj samo! Tek što mi do ušiju doprije glas pozdrava tvojega, zaigra mi od radosti čedo u utrobi.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (49, 1, 45, 'Blažena ti što povjerova da će se ispuniti što ti je rečeno od Gospodina!\"');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (49, 1, 46, 'Tada Marija reče: \"Veliča duša moja Gospodina,');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (49, 1, 47, 'klikće duh moj u Bogu, mome Spasitelju,');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (49, 1, 48, 'što pogleda na neznatnost službenice svoje: odsad će me, evo, svi naraštaji zvati blaženom.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (49, 1, 49, 'Jer velika mi djela učini Svesilni, sveto je ime njegovo!');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (49, 1, 50, 'Od koljena do koljena dobrota je njegova nad onima što se njega boje.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (49, 1, 51, 'Iskaza snagu mišice svoje, rasprši oholice umišljene.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (49, 1, 52, 'Silne zbaci s prijestolja, a uzvisi neznatne.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (49, 1, 53, 'Gladne napuni dobrima, a bogate otpusti prazne.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (49, 1, 54, 'Prihvati Izraela, slugu svoga, kako obeća ocima našim:');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (49, 1, 55, 'spomenuti se dobrote svoje prema Abrahamu i potomstvu njegovu dovijeka.\"');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (49, 1, 56, 'Marija osta s Elizabetom oko tri mjeseca, a onda se vrati kući.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (49, 1, 57, 'Elizabeti se međutim navršilo vrijeme da rodi. I porodi sina.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (49, 1, 58, 'Kad su njezini susjedi i rođaci čuli da joj Gospodin obilno iskaza dobrotu, radovahu se s njome.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (49, 1, 59, 'Osmoga se dana okupe da obrežu dječaka. Htjedoše ga prozvati imenom njegova oca - Zaharija,');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (49, 1, 60, 'no mati se njegova usprotivi: \"Nipošto, nego zvat će se Ivan!\"');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (49, 1, 61, 'Rekoše joj na to: \"Ta nikoga nema od tvoje rodbine koji bi se tako zvao.\"');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (49, 1, 62, 'Tada znakovima upitaju oca kojim ga imenom želi prozvati.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (49, 1, 63, 'On zaiska pločicu i napisa \"Ivan mu je ime!\" Svi se začude,');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (49, 1, 64, 'a njemu se umah otvoriše usta i jezik te progovori blagoslivljajući Boga.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (49, 1, 65, 'Strah obuze sve njihove susjede, a po svem su se Gorju judejskom razglašavali svi ti događaji.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (49, 1, 66, 'I koji su god čuli, razmišljahu o tome pitajući se: \"Što li će biti od ovoga djeteta?\" Uistinu, ruka Gospodnja bijaše s njime.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (49, 1, 67, 'A Zaharija, otac njegov, napuni se Duha Svetoga i stade prorokovati:');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (49, 1, 68, '\"Blagoslovljen Gospodin Bog Izraelov, što pohodi i otkupi narod svoj!');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (49, 1, 69, 'Podiže nam snagu spasenja u domu Davida, sluge svojega,');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (49, 1, 70, 'kao što obeća na usta svetih proroka svojih odvijeka:');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (49, 1, 71, 'spasiti nas od neprijatelja naših i od ruke sviju koji nas mrze;');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (49, 1, 72, 'iskazati dobrotu ocima našim i sjetiti se svetog Saveza svojega,');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (49, 1, 73, 'zakletve kojom se zakle Abrahamu, ocu našemu: da će nam dati');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (49, 1, 74, 'te mu, izbavljeni iz ruku neprijatelja, služimo bez straha');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (49, 1, 75, 'u svetosti i pravednosti pred njim u sve dane svoje.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (49, 1, 76, 'A ti, dijete, prorok ćeš se Svevišnjega zvati jer ćeš ići pred Gospodinom da mu pripraviš putove,');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (49, 1, 77, 'da pružiš spoznaju spasenja narodu njegovu po otpuštenju grijeha njihovih,');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (49, 1, 78, 'darom premilosrdnog srca Boga našega po kojem će nas pohoditi Mlado sunce s visine');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (49, 1, 79, 'da obasja one što sjede u tmini i sjeni smrtnoj, da upravi noge naše na put mira.\"');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (49, 1, 80, 'Dječak je međutim rastao i duhom jačao. Boravio je u pustinji sve do dana svoga javnog nastupa pred Izraelom.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (49, 2, 1, 'U one dane izađe naredba cara Augusta da se provede popis svega svijeta.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (49, 2, 2, 'Bijaše to prvi popis izvršen za Kvirinijeva upravljanja Sirijom.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (49, 2, 3, 'Svi su išli na popis, svaki u svoj grad.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (49, 2, 4, 'Tako i Josip, budući da je bio iz doma i loze Davidove, uziđe iz Galileje, iz grada Nazareta, u Judeju - u grad Davidov, koji se zove Betlehem -');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (49, 2, 5, 'da se podvrgne popisu zajedno sa svojom zaručnicom Marijom koja bijaše trudna.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (49, 2, 6, 'I dok se bili ondje, navršilo joj se vrijeme da rodi.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (49, 2, 7, 'I porodi sina svoga, prvorođenca, povi ga i položi u jasle jer za njih nije bilo mjesta u svratištu.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (49, 2, 8, 'A u tom kraju bijahu pastiri: pod vedrim su nebom čuvali noćnu stražu kod svojih stada.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (49, 2, 9, 'Anđeo im Gospodnji pristupi i slava ih Gospodnja obasja! Silno se prestrašiše.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (49, 2, 10, 'No anđeo im reče: \"Ne bojte se! Evo javljam vam blagovijest, veliku radost za sav narod!');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (49, 2, 11, 'Danas vam se u gradu Davidovu rodio Spasitelj - Krist, Gospodin.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (49, 2, 12, 'I evo vam znaka: naći ćete novorođenče povijeno gdje leži u jaslama.\"');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (49, 2, 13, 'I odjednom se anđelu pridruži silna nebeska vojska hvaleći Boga i govoreći:');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (49, 2, 14, '\"Slava na visinama Bogu, a na zemlji mir ljudima, miljenicima njegovim!\"');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (49, 2, 15, 'Čim anđeli otiđoše od njih na nebo, pastiri stanu poticati jedni druge: \"Hajdemo dakle do Betlehema. Pogledajmo što se to dogodilo, događaj koji nam obznani Gospodin.\"');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (49, 2, 16, 'I pohite te pronađu Mariju, Josipa i novorođenče gdje leži u jaslama.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (49, 2, 17, 'Pošto sve pogledaše, ispripovijediše što im bijaše rečeno o tom djetetu.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (49, 2, 18, 'A svi koji su to čuli divili se tome što su im pripovijedali pastiri.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (49, 2, 19, 'Marija u sebi pohranjivaše sve te događaje i prebiraše ih u svome srcu.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (49, 2, 20, 'Pastiri se zatim vratiše slaveći i hvaleći Boga za sve što su čuli i vidjeli kako im je bilo rečeno.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (49, 2, 21, 'Kad se navršilo osam dana da bude obrezan, nadjenuše mu ime Isus, kako ga je bio prozvao anđeo prije njegova začeća.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (49, 2, 22, 'Kad se zatim po Mojsijevu Zakonu navršiše dani njihova čišćenja, poniješe ga u Jeruzalem da ga prikažu Gospodinu -');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (49, 2, 23, 'kao što piše u Zakonu Gospodnjem: Svako muško prvorođenče neka se posveti Gospodinu! -');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (49, 2, 24, 'i da prinesu žrtvu kako je rečeno u Zakonu Gospodnjem: dvije grlice ili dva golubića.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (49, 2, 25, 'Živio tada u Jeruzalemu čovjek po imenu Šimun. Taj čovjek, pravedan i bogobojazan, iščekivaše Utjehu Izraelovu i Duh Sveti bijaše na njemu.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (49, 2, 26, 'Objavio mu Duh Sveti da neće vidjeti smrti dok ne vidi Pomazanika Gospodnjega.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (49, 2, 27, 'Ponukan od Duha, dođe u Hram. I kad roditelji uniješe dijete Isusa da obave što o njemu propisuje Zakon,');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (49, 2, 28, 'primi ga on u naručje, blagoslovi Boga i reče:');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (49, 2, 29, '\"Sad otpuštaš slugu svojega, Gospodaru, po riječi svojoj, u miru!');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (49, 2, 30, 'Ta vidješe oči moje spasenje tvoje,');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (49, 2, 31, 'koje si pripravio pred licem svih naroda:');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (49, 2, 32, 'svjetlost na prosvjetljenje naroda, slavu puka svoga izraelskoga.\"');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (49, 2, 33, 'Otac njegov i majka divili se što se to o njemu govori.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (49, 2, 34, 'Šimun ih blagoslovi i reče Mariji, majci njegovoj: \"Ovaj je evo postavljen na propast i uzdignuće mnogima u Izraelu i za znak osporavan -');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (49, 2, 35, 'a i tebi će samoj mač probosti dušu - da se razotkriju namisli mnogih srdaca!\"');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (49, 2, 36, 'A bijaše neka proročica Ana, kći Penuelova, iz plemena Ašerova, žena veoma odmakla u godinama. Nakon djevojaštva živjela je s mužem sedam godina,');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (49, 2, 37, 'a sama kao udovica do osamdeset i četvrte. Nije napuštala Hrama, nego je postovima i molitvama danju i noću služila Bogu.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (49, 2, 38, 'Upravo u taj čas nadođe. Hvalila je Boga i svima koji iščekivahu otkupljenje Jeruzalema pripovijedala o djetetu.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (49, 2, 39, 'Kad obaviše sve po Zakonu Gospodnjem, vratiše se u Galileju, u svoj grad Nazaret.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (49, 2, 40, 'A dijete je raslo, jačalo i napunjalo se mudrosti i milost je Božja bila na njemu.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (49, 2, 41, 'Njegovi su roditelji svake godine o blagdanu Pashe išli u Jeruzalem.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (49, 2, 42, 'Kad mu bijaše dvanaest godina, uziđoše po običaju blagdanskom.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (49, 2, 43, 'Kad su minuli ti dani, vraćahu se oni, a dječak Isus osta u Jeruzalemu, a da nisu znali njegovi roditelji.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (49, 2, 44, 'Uvjereni da je među suputnicima, odoše dan hoda, a onda ga stanu tražiti među rodbinom i znancima.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (49, 2, 45, 'I kad ga ne nađu, vrate se u Jeruzalem tražeći ga.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (49, 2, 46, 'Nakon tri dana nađoše ga u Hramu gdje sjedi posred učitelja, sluša ih i pita.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (49, 2, 47, 'Svi koji ga slušahu bijahu zaneseni razumnošću i odgovorima njegovim.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (49, 2, 48, 'Kad ga ugledaše, zapanjiše se, a majka mu njegova reče: \"Sinko, zašto si nam to učinio? Gle, otac tvoj i ja žalosni smo te tražili.\"');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (49, 2, 49, 'A on im reče: \"Zašto ste me tražili? Niste li znali da mi je biti u onome što je Oca mojega?\"');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (49, 2, 50, 'Oni ne razumješe riječi koju im reče.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (49, 2, 51, 'I siđe s njima, dođe u Nazaret i bijaše im poslušan. A majka je njegova brižno čuvala sve ove uspomene u svom srcu.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (49, 2, 52, 'A Isus napredovaše u mudrosti, dobi i milosti kod Boga i ljudi.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (49, 3, 1, 'Petnaeste godine vladanja cara Tiberija, dok je upravitelj Judeje bio Poncije Pilat, tetrarh Galileje Herod, a njegov brat Filip tetrarh Itureje i zemlje trahonitidske, i Lizanije tetrarh Abilene,');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (49, 3, 2, 'za velikog svećenika Ane i Kajfe, dođe riječ Božja Ivanu, sinu Zaharijinu, u pustinji.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (49, 3, 3, 'On obiđe svu okolicu jordansku propovijedajući obraćeničko krštenje na otpuštenje grijeha');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (49, 3, 4, 'kao što je pisano u Knjizi besjeda Izaije proroka: Glas viče u pustinji: Pripravite put Gospodinu, poravnite mu staze!');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (49, 3, 5, 'Svaka dolina neka se ispuni, svaka gora i brežuljak neka se slegne! Što je krivudavo, neka se izravna, a hrapavi putovi neka se izglade!');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (49, 3, 6, 'I svako će tijelo vidjeti spasenje Božje.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (49, 3, 7, 'Govoraše dakle mnoštvu koje je dolazilo da se krsti: \"Leglo gujinje! Tko vas samo upozori da bježite od skore srdžbe?');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (49, 3, 8, 'Donosite dakle plodove dostojne obraćenja. I nemojte početi u sebi govoriti: \'Imamo oca Abrahama!\' Jer, kažem vam: Bog iz ovog kamenja može podići djecu Abrahamovu.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (49, 3, 9, 'Već je sjekira položena na korijen stablima: svako dakle stablo koje ne donosi dobra roda siječe se i u oganj baca.\"');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (49, 3, 10, 'Pitalo ga mnoštvo: \"Što nam je dakle činiti?\"');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (49, 3, 11, 'On im odgovaraše: \"Tko ima dvije haljine, neka podijeli s onim koji nema. U koga ima hrane, neka učini isto tako.\"');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (49, 3, 12, 'Dođoše krstiti se i carinici pa ga pitahu: \"Učitelju, što nam je činiti?\"');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (49, 3, 13, 'Reče im: \"Ne utjerujte više nego što vam je određeno.\"');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (49, 3, 14, 'Pitahu ga i vojnici: \"A nama, što je nama činiti?\" I reče im: \"Nikome ne činite nasilja, nikoga krivo ne prijavljujte i budite zadovoljni svojom plaćom.\"');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (49, 3, 15, 'Narod bijaše u iščekivanju i svi se u srcu pitahu o Ivanu nije li on možda Krist.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (49, 3, 16, 'Zato im Ivan svima reče: \"Ja vas, istina, vodom krstim. Ali dolazi jači od mene. Ja nisam dostojan odriješiti mu remenje na obući. On će vas krstiti Duhom Svetim i ognjem.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (49, 3, 17, 'U ruci mu vijača da pročisti gumno svoje i sabere žito u žitnicu svoju, a pljevu će spaliti ognjem neugasivim.\"');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (49, 3, 18, 'I mnogim je drugim pobudama Ivan narodu navješćivao evanđelje.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (49, 3, 19, 'A Heroda je tetrarha Ivan prekorio zbog Herodijade, žene njegova brata i zbog svih njegovih zlodjela.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (49, 3, 20, 'Svemu tome nadoda Herod još i ovo: zatvori Ivana u tamnicu.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (49, 3, 21, 'Kad se krstio sav narod, krstio se i Isus. I dok se molio, rastvori se nebo,');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (49, 3, 22, 'siđe na nj Duh Sveti u tjelesnom obličju, poput goluba, a glas se s neba zaori: \"Ti si Sin moj, Ljubljeni! U tebi mi sva milina!\"');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (49, 3, 23, 'Kad je Isus nastupio, bilo mu je oko trideset godina. Bijaše - kako se smatralo - sin Josipov, Elijev,');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (49, 3, 24, 'Matatov, Levijev, Malkijev, Janajev, Josipov.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (49, 3, 25, 'Matatijin, Amosov, Naumov, Heslijev, Nagajev,');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (49, 3, 26, 'Mahatov, Matatijin, Šimijev, Josehov, Jodin,');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (49, 3, 27, 'Johananov, Resin, Zerubabelov, Šealtielov, Nerijev,');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (49, 3, 28, 'Malkijev, Adijev, Kosamov, Elmadamov, Erov,');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (49, 3, 29, 'Jošuin, Eliezerov, Jorimov, Matatov, Levijev,');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (49, 3, 30, 'Šimunov, Judin, Josipov, Jonamov, Elijakimov,');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (49, 3, 31, 'Melejin, Menin, Matatin, Natanov, Davidov,');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (49, 3, 32, 'Jišajev, Obedov, Boazov, Salin, Nahšonov,');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (49, 3, 33, 'Aminadabov, Adminov, Arnijev, Hesronov, Peresov, Judin,');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (49, 3, 34, 'Jakovljev, Izakov, Abrahamov, Terahov, Nahorov,');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (49, 3, 35, 'Serugov, Reuov, Pelegov, Eberov, Šelahov,');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (49, 3, 36, 'Kenanov, Arpakšadov, Šemov, Noin, Lamekov,');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (49, 3, 37, 'Metušalahov, Henokov, Jeredov, Mahalalelov, Kenanov,');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (49, 3, 38, 'Enošev, Šetov, Adamov, Božji.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (49, 4, 1, 'Isus se, pun Duha Svetoga, vratio s Jordana i Duh ga četrdeset dana vodio pustinjom,');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (49, 4, 2, 'gdje ga je iskušavao đavao. Tih dana nije ništa jeo, te kad oni istekoše, ogladnje.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (49, 4, 3, 'A đavao mu reče: \"Ako si Sin Božji, reci ovom kamenu da postane kruhom.\"');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (49, 4, 4, 'Isus mu odgovori: \"Pisano je: Ne živi čovjek samo o kruhu.\"');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (49, 4, 5, 'I povede ga đavao na visoko, pokaza mu odjednom sva kraljevstva zemlje');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (49, 4, 6, 'i reče mu: \"Tebi ću dati svu ovu vlast i slavu njihovu jer meni je dana i komu hoću, dajem je.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (49, 4, 7, 'Ako se dakle pokloniš preda mnom, sve je tvoje.\"');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (49, 4, 8, 'Isus mu odgovori: \"Pisano je: Klanjaj se Gospodinu, Bogu svomu, i njemu jedinomu služi!\"');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (49, 4, 9, 'Povede ga u Jeruzalem i postavi na vrh Hrama i reče mu: \"Ako si Sin Božji, baci se odavde dolje!');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (49, 4, 10, 'Ta pisamo je: Anđelima će svojim zapovjediti za tebe da te čuvaju.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (49, 4, 11, 'I: Na rukama će te nositi da se gdje nogom ne spotakneš o kamen.\"');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (49, 4, 12, 'Odgovori mu Isus: \"Rečeno je: Ne iskušavaj Gospodina, Boga svojega!\"');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (49, 4, 13, 'Pošto iscrpi sve kušnje, đavao se udalji od njega do druge prilike.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (49, 4, 14, 'A Isus se u snazi Duha vrati u Galileju te glas o njemu puče po svoj okolici.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (49, 4, 15, 'I slavljen od sviju, naučavaše po njihovim sinagogama.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (49, 4, 16, 'I dođe u Nazaret, gdje bijaše othranjen. I uđe po svom običaju na dan subotni u sinagogu te ustane čitati.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (49, 4, 17, 'Pruže mu Knjigu proroka Izaije. On razvije knjigu i nađe mjesto gdje stoji napisano:');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (49, 4, 18, 'Duh Gospodnji na meni je jer me pomaza! On me posla blagovjesnikom biti siromasima, proglasiti sužnjima oslobođenje, vid slijepima, na slobodu pustiti potlačene,');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (49, 4, 19, 'proglasiti godinu milosti Gospodnje.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (49, 4, 20, 'Tada savi knjigu, vrati je poslužitelju i sjede. Oči sviju u sinagogi bijahu uprte u njega.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (49, 4, 21, 'On im progovori: \"Danas se ispunilo ovo Pismo što vam još odzvanja u ušima.\"');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (49, 4, 22, 'I svi su mu povlađivali i divili se milini riječi koje su tekle iz njegovih usta. Govorahu: \"Nije li ovo sin Josipov?\"');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (49, 4, 23, 'A on im reče: \"Zacijelo ćete mi reći onu prispodobu: Liječniče, izliječi sam sebe! Što smo čuli da se dogodilo u Kafarnaumu, učini i ovdje, u svom zavičaju.\"');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (49, 4, 24, 'I nastavi: \"Zaista, kažem vam, nijedan prorok nije dobro došao u svom zavičaju.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (49, 4, 25, 'Uistinu, kažem vam, mnogo bijaše udovica u Izraelu u dane Ilijine kad se na tri godine i šest mjeseci zatvorilo nebo pa zavladala velika glad po svoj zemlji.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (49, 4, 26, 'I ni k jednoj od njih nije bio poslan Ilija doli k ženi udovici u Sarfati sidonskoj.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (49, 4, 27, 'I mnogo bijaše gubavaca u Izraelu za proroka Elizeja. I nijedan se od njih ne očisti doli Naaman Sirac.\"');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (49, 4, 28, 'Čuvši to, svi se u sinagogi napune gnjevom,');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (49, 4, 29, 'ustanu, izbace ga iz grada i odvedu na rub brijega na kojem je sagrađen njihov grad da ga strmoglave.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (49, 4, 30, 'No on prođe između njih i ode.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (49, 4, 31, 'I siđe u Kafarnaum, grad galilejski. I poučavaše ih subotom');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (49, 4, 32, 'te bijahu zaneseni njegovim naukom jer silna bijaše riječ njegova.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (49, 4, 33, 'A zatekao se u sinagogi čovjek s duhom nečistoga đavla. On povika u sav glas:');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (49, 4, 34, '\"Hej, što ti imaš s nama, Isuse Nazarećanine? Došao si da nas uništiš! Znam ja tko si ti: Svetac Božji.\"');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (49, 4, 35, 'Isus mu zaprijeti: \"Umukni i iziđi iz njega!\" Nato đavao čovjeka obori u sredinu te iziđe iz njega ne naudiv mu ništa.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (49, 4, 36, 'I nasta opće zaprepaštenje te se među sobom razgovarahu: \"Kakve li riječi! S vlašću i snagom zapovijeda nečistim dusima te izlaze!\"');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (49, 4, 37, 'I glas se o njemu širio po svim okolnim mjestima.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (49, 4, 38, 'Ustavši iz sinagoge, uđe u kuću Šimunovu. A Šimunovu je punicu mučila velika ognjica. I zamole ga za nju.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (49, 4, 39, 'On se nadvi nad nju, zaprijeti ognjici i ona je pusti. I odmah ustade i posluživaše im.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (49, 4, 40, 'O zalazu sunca svi koji su imali bolesnike od raznih bolesti dovedoše ih k njemu. A on bi na svakoga od njih stavljao ruke i ozdravljao ih.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (49, 4, 41, 'A iz mnogih su izlazili i zlodusi vičući: \"Ti si Sin Božji!\" On im se prijetio i nije im dao govoriti jer su znali da je on Krist.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (49, 4, 42, 'Kad osvanu dan, iziđe i pođe na samotno mjesto. I mnoštvo ga tražilo. Dođoše k njemu i zadržavahu ga da ne ode od njih.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (49, 4, 43, 'A on im reče: \"I drugim gradovima treba da navješćujem evanđelje o kraljevstvu Božjem. Jer za to sam poslan.\"');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (49, 4, 44, 'I naučavaše po sinagogama judejskim.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (49, 5, 1, 'Dok se jednom oko njega gurao narod da čuje riječ Božju, stajaše on pokraj Genezaretskog jezera.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (49, 5, 2, 'Spazi dvije lađe gdje stoje uz obalu; ribari bili izašli iz njih i ispirali mreže.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (49, 5, 3, 'Uđe u jednu od tih lađa; bila je Šimunova pa zamoli Šimuna da malo otisne od kraja. Sjedne te iz lađe poučavaše mnoštvo.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (49, 5, 4, 'Kada dovrši pouku, reče Šimunu: \"Izvezi na pučinu i bacite mreže za lov.\"');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (49, 5, 5, 'Odgovori Šimun: \"Učitelju, svu smo se noć trudili i ništa ne ulovismo, ali na tvoju riječ bacit ću mreže.\"');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (49, 5, 6, 'Učiniše tako te uhvatiše veoma mnogo riba; mreže im se gotovo razdirale.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (49, 5, 7, 'Mahnuše drugovima na drugoj lađi da im dođu pomoći. Oni dođoše i napuniše obje lađe, umalo im ne potonuše.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (49, 5, 8, 'Vidjevši to, Šimun Petar pade do nogu Isusovih govoreći: \"Idi od mene! Grešan sam čovjek, Gospodine!\"');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (49, 5, 9, 'Zbog lovine riba što ih uloviše bijaše se zapanjio on i svi koji bijahu s njime,');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (49, 5, 10, 'a tako i Jakov i Ivan, Zebedejevi sinovi, drugovi Šimunovi. Isus reče Šimunu: \"Ne boj se! Odsada ćeš loviti ljude!\"');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (49, 5, 11, 'Oni izvukoše lađe na kopno, ostaviše sve i pođoše za njim.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (49, 5, 12, 'I dok bijaše u jednom gradu, gle čovjeka puna gube! Ugledavši Isusa, padne ničice i zamoli ga: \"Gospodine, ako hoćeš, možeš me očistiti.\"');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (49, 5, 13, 'Isus pruži ruku i dotakne ga se govoreći: \"Hoću, očisti se!\" I odmah nesta gube s njega.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (49, 5, 14, 'I zapovjedi mu: \"Nikome ni riječi, nego otiđi, pokaži se svećeniku i prinesi za svoje očišćenje kako propisa Mojsije, njima za svjedočanstvo.\"');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (49, 5, 15, 'Glas se o njemu sve više širio i silan svijet grnuo k njemu da ga sluša i da ozdravi od svojih bolesti.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (49, 5, 16, 'A on se sklanjao na samotna mjesta da moli.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (49, 5, 17, 'I jednog je dana on naučavao. A sjeđahu ondje farizeji i učitelji Zakona koji bijahu došli iz svih galilejskih i judejskih sela i Jeruzalema. A sila ga je Gospodnja nukala da liječi.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (49, 5, 18, 'I gle, ljudi doniješe na nosiljci čovjeka koji bijaše uzet. Tražili su da ga unesu i stave preda nj.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (49, 5, 19, 'Budući da zbog mnoštva nisu našli kuda bi ga unijeli, popnu se na krov te ga između crepova s nosiljkom spuste u sredinu pred Isusa.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (49, 5, 20, 'Vidjevši njihovu vjeru reče on: \"Čovječe, otpušteni su ti grijesi!\"');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (49, 5, 21, 'Pismoznanci i farizeji počeše mudrovati: \"Tko je ovaj što huli? Tko može grijehe otpuštati doli Bog jedini?\"');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (49, 5, 22, 'Proniknuvši njihovo mudrovanje, upita ih Isus: \"Što mudrujete u sebi?');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (49, 5, 23, 'Što je lakše? Reći: \'Otpušteni su ti grijesi\' ili reći: \'Ustani i hodi?\'');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (49, 5, 24, 'Ali da znate: Vlastan je Sin Čovječji na zemlji otpuštati grijehe!\" I reče uzetomu: \"Tebi zapovijedam: ustani, uzmi nosiljku i idi kući!\"');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (49, 5, 25, 'I on odmah usta pred njima, uze na čemu ležaše i ode kući slaveći Boga.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (49, 5, 26, 'A sve obuze zanos te su slavili Boga i puni straha govorili: \"Danas vidjesmo nešto neviđeno!\"');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (49, 5, 27, 'Nakon toga iziđe i ugleda carinika imenom Levija gdje sjedi u carinarnici. I reče mu: \"Pođi za mnom!\"');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (49, 5, 28, 'On sve ostavi, usta i pođe za njim.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (49, 5, 29, 'I Levi mu u svojoj kući priredi veliku gozbu. A s njime bijaše za stolom veliko mnoštvo carinika i drugih.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (49, 5, 30, 'Farizeji i pismoznanci njihovi negodovahu i govorahu njegovim učenicima: \"Zašto s carinicima i grešnicima jedete i pijete?\"');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (49, 5, 31, 'Isus im odgovori: \"Ne treba zdravima liječnika, nego bolesnima.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (49, 5, 32, 'Nisam došao zvati pravedne, nego grešnike na obraćenje.\"');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (49, 5, 33, 'A oni mu rekoše: \"Učenici Ivanovi, a tako i farizejski, počesto poste i obavljaju molitve, tvoji pak jedu i piju.\"');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (49, 5, 34, 'Reče im Isus: \"Ne možete svatove prisiliti da poste dok je zaručnik s njima.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (49, 5, 35, 'Doći će već dani: kad im se ugrabi zaručnik, tada će postiti, u one dane!\"');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (49, 5, 36, 'A kazivao im je i prispodobu: \"Nitko neće otparati krpe s novog odijela da je stavi na staro odijelo. Inače će i novo rasparati, a starom neće pristajati krpa s novoga.\"');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (49, 5, 37, '\"I nitko ne ulijeva novo vino u stare mješine. Inače će novo vino proderati mješine pa će se i ono proliti i mješine će propasti.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (49, 5, 38, 'Nego, novo vino neka se ulijeva u nove mješine!\"');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (49, 5, 39, '\"I nitko pijuć staro, ne zaželi novoga. Ta veli se: \'Valja staro!\'\"');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (49, 6, 1, 'Jedne je subote prolazio kroz usjeve. Učenici su njegovi trgali klasje, trli ga rukama i jeli.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (49, 6, 2, 'A neki farizeji rekoše: \"Zašto činite što subotom nije dopušteno?\"');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (49, 6, 3, 'Odgovori im Isus: \"Zar niste čitali što učini David kad ogladnje on i njegovi pratioci?');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (49, 6, 4, 'Kako uđe u Dom Božji, uze, pojede i svojim pratiocima dade prinesene kruhove kojih ne smije jesti nitko, nego samo svećenici?\"');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (49, 6, 5, 'I govoraše im: \"Sin Čovječji gospodar je subote!\"');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (49, 6, 6, 'Druge subote uđe u sinagogu i stane naučavati. Bio je ondje čovjek kome desnica bijaše usahla.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (49, 6, 7, 'Pismoznanci i farizeji vrebahu na nj da li subotom liječi kako bi našli u čemu da ga optuže.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (49, 6, 8, 'A on je znao njihove namjere pa reče čovjeku s usahlom rukom: \"Ustani i stani na sredinu!\" On usta i stade.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (49, 6, 9, 'A Isus im reče: \"Pitam ja vas: je li subotom dopušteno činiti dobro ili činiti zlo? Život spasiti ili upropastiti?\"');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (49, 6, 10, 'Sve ih ošinu pogledom pa reče čovjeku: \"Ispruži ruku!\" On učini tako - i ruka mu zdrava.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (49, 6, 11, 'A oni se, izbezumljeni, počnu dogovarati što da poduzmu protiv Isusa.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (49, 6, 12, 'Onih dana iziđe na goru da se pomoli. I provede noć moleći se Bogu.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (49, 6, 13, 'Kad se razdanilo, dozva k sebi učenike te između njih izabra dvanaestoricu, koje prozva apostolima:');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (49, 6, 14, 'Šimuna, koga prozva Petrom, i Andriju, brata njegova, i Jakova, i Ivana, i Filipa, i Bartolomeja,');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (49, 6, 15, 'i Mateja, i Tomu, i Jakova Alfejeva, i Šimuna zvanoga Revnitelj,');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (49, 6, 16, 'i Judu Jakovljeva, i Judu Iškariotskoga, koji posta izdajica.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (49, 6, 17, 'Isus siđe s njima i zaustavi se na ravnu. I silno mnoštvo njegovih učenika i silno mnoštvo naroda iz cijele Judeje i Jeruzalema, iz primorja tirskog i sidonskog');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (49, 6, 18, 'nagrnuše da ga slušaju i da ozdrave od svojih bolesti. I ozdravljali su oni koje su mučili nečisti dusi.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (49, 6, 19, 'Sve je to mnoštvo tražilo da ga se dotakne jer je snaga izlazila iz njega i sve ozdravljala.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (49, 6, 20, 'On podigne oči prema učenicima i govoraše: \"Blago vama, siromasi: vaše je kraljevstvo Božje!');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (49, 6, 21, 'Blago vama koji sada gladujete: vi ćete se nasititi! Blago vama koji sada plačete: vi ćete se smijati!');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (49, 6, 22, 'Blago vama kad vas zamrze ljudi i kad vas izopće i pogrde te izbace ime vaše kao zločinačko zbog Sina Čovječjega!');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (49, 6, 23, 'Radujte se u dan onaj i poskakujte: evo, plaća vaša velika je na nebu. Ta jednako su činili prorocima oci njihovi!\"');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (49, 6, 24, '\"Ali jao vama, bogataši: imate svoju utjehu!');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (49, 6, 25, 'Jao vama koji ste sada siti: gladovat ćete! Jao vama koji se sada smijete: jadikovat ćete i plakati!');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (49, 6, 26, 'Jao vama kad vas svi budu hvalili! Ta tako su činili lažnim prorocima oci njihovi.\"');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (49, 6, 27, '\"Nego, velim vama koji slušate: Ljubite svoje neprijatelje, dobro činite svojim mrziteljima,');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (49, 6, 28, 'blagoslivljajte one koji vas proklinju, molite za one koji vas zlostavljaju.\"');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (49, 6, 29, '\"Onomu tko te udari po jednom obrazu pruži i drugi, i onomu tko ti otima gornju haljinu ne krati ni donje.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (49, 6, 30, 'Svakomu tko od tebe ište daji, a od onoga tko tvoje otima ne potražuj.\"');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (49, 6, 31, '\"I kako želite da ljudi vama čine, tako činite i vi njima.\"');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (49, 6, 32, '\"Ako ljubite one koji vas ljube, kakvo li vam uzdarje? Ta i grešnici ljube ljubitelje svoje.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (49, 6, 33, 'Jednako tako, ako dobro činite svojim dobročiniteljima, kakvo li vam uzdarje? I grešnici to isto čine.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (49, 6, 34, 'Ako pozajmljujete samo onima od kojih se nadate dobiti, kakvo li vam uzdarje? I grešnici grešnicima pozajmljuju da im se jednako vrati.\"');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (49, 6, 35, '\"Nego, ljubite neprijatelje svoje. Činite dobro i pozajmljujte ne nadajuć se odatle ničemu. I bit će vam plaća velika, i bit ćete sinovi Svevišnjega jer je on dobrostiv i prema nezahvalnicima i prema opakima.\"');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (49, 6, 36, '\"Budite milosrdni kao što je Otac vaš milosrdan.\"');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (49, 6, 37, '\"Ne sudite i nećete biti suđeni. Ne osuđujte i nećete biti osuđeni. Praštajte i oprostit će vam se.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (49, 6, 38, 'Dajite i dat će vam se: mjera dobra, nabijena, natresena, preobilna dat će se u krilo vaše jer mjerom kojom mjerite vama će se zauzvrat mjeriti.\"');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (49, 6, 39, 'A kaza im i prispodobu: \"Može li slijepac slijepca voditi? Neće li obojica u jamu upasti?');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (49, 6, 40, 'Nije učenik nad učiteljem. Pa i tko je posve doučen, bit će samo kao njegov učitelj.\"');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (49, 6, 41, '\"Što gledaš trun u oku brata svojega, a brvna u oku svome ne opažaš?');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (49, 6, 42, 'Kako možeš kazati bratu svomu: \'Brate, de da izvadim trun koji ti je u oku\', a sam u svom oku brvna ne vidiš? Licemjere! Izvadi najprije brvno iz oka svoga pa ćeš onda dobro vidjeti izvaditi trun što je u oku bratovu.\"');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (49, 6, 43, '\"Nema dobra stabla koje bi rađalo nevaljalim plodom niti stabla nevaljala koje bi rađalo dobrim plodom.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (49, 6, 44, 'Ta svako se stablo po svom plodu poznaje. S trnja se ne beru smokve niti se s gloga grožđe trga.\"');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (49, 6, 45, '\"Dobar čovjek iz dobra blaga srca svojega iznosi dobro, a zao iz zla iznosi zlo. Ta iz obilja srca usta mu govore.\"');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (49, 6, 46, '\"Što me zovete \'Gospodine, Gospodine!\', a ne činite što zapovijedam?');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (49, 6, 47, 'Tko god dolazi k meni te sluša moje riječi i vrši ih, pokazat ću vam kome je sličan:');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (49, 6, 48, 'sličan je čovjeku koji gradi kuću pa iskopa u dubinu i postavi temelj na kamen. A kad bude poplava, nahrupi bujica na tu kuću, ali je ne može uzdrmati jer je dobro sagrađena.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (49, 6, 49, 'A koji čuje i ne izvrši, sličan je čovjeku koji sagradi kuću na tlu bez temelja; nahrupi na nju bujica i umah se sruši te bude od te kuće razvalina velika.\"');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (49, 7, 1, 'Pošto dovrši sve te svoje besjede narodu, uđe u Kafarnaum.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (49, 7, 2, 'Nekomu satniku bijaše bolestan sluga, samo što ne izdahnu, a bijaše mu veoma drag.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (49, 7, 3, 'Kad je satnik čuo za Isusa, posla k njemu starješine židovske moleći ga da dođe i ozdravi mu slugu.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (49, 7, 4, 'Kad oni dođoše Isusu, usrdno ga moljahu: \"Dostojan je da mu to učiniš');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (49, 7, 5, 'jer voli naš narod, i sinagogu nam je sagradio.\"');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (49, 7, 6, 'Isus se uputi s njima. I kad bijaše već kući nadomak, posla satnik prijatelje s porukom: \"Gospodine, ne muči se. Nisam dostojan da uđeš pod krov moj.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (49, 7, 7, 'Zato se i ne smatrah dostojnim doći k tebi. Nego - reci riječ da ozdravi sluga moj.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (49, 7, 8, 'Ta i ja, premda sam vlasti podređen, imam pod sobom vojnike pa reknem jednomu: \'Idi\' - i ode, drugomu: \'Dođi\' - i dođe, a sluzi svomu: \'Učini to\' - i učini.\"');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (49, 7, 9, 'Čuvši to, zadivi mu se Isus pa se okrenu mnoštvu koje je išlo za njim i reče: \"Kažem vam, ni u Izraelu na nađoh tolike vjere.\"');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (49, 7, 10, 'Kad se oni koji su bili poslani vratiše kući, nađoše slugu zdrava.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (49, 7, 11, 'Nakon toga uputi se Isus u grad zvani Nain. Pratili ga njegovi učenici i silan svijet.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (49, 7, 12, 'Kad se približi gradskim vratima, gle, upravo su iznosili mrtvaca, sina jedinca u majke, majke udovice. Pratilo ju mnogo naroda iz grada.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (49, 7, 13, 'Kad je Gospodin ugleda, sažali mu se nad njom i reče joj: \"Ne plači!\"');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (49, 7, 14, 'Pristupi zatim, dotače se nosila; nosioci stadoše, a on reče: \"Mladiću, kažem ti, ustani!\"');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (49, 7, 15, 'I mrtvac se podiže i progovori, a on ga dade njegovoj majci.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (49, 7, 16, 'Sve obuze strah te slavljahu Boga govoreći: \"Prorok velik usta među nama! Pohodi Bog narod svoj!\"');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (49, 7, 17, 'I proširi se taj glas o njemu po svoj Judeji i po svoj okolici.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (49, 7, 18, 'Sve to dojaviše Ivanu njegovi učenici. On dozva dvojicu svojih učenika');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (49, 7, 19, 'i posla ih Gospodinu da ga pitaju: \"Jesi li ti Onaj koji ima doći ili drugoga da čekamo?\"');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (49, 7, 20, 'Došavši k njemu, rekoše ti ljudi: \"Ivan Krstitelj posla nas k tebi da pitamo: \'Jesi li ti Onaj koji ima doći ili drugoga da čekamo?\'\"');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (49, 7, 21, 'Upravo u taj čas Isus je ozdravio mnoge od bolesti, muka i zlih duhova i mnoge je slijepe podario vidom.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (49, 7, 22, 'Tada im odgovori: \"Pođite i javite Ivanu što ste vidjeli i čuli: Slijepi progledaju, hromi hode, gubavi se čiste, gluhi čuju, mrtvi ustaju, siromasima se navješćuje evanđelje.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (49, 7, 23, 'I blago onom tko se ne sablazni o mene.\"');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (49, 7, 24, 'Kad Ivanovi glasnici odoše, poče Isus govoriti mnoštvu o Ivanu: \"Što ste izašli u pustinju gledati? Trsku koju vjetar ljulja?');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (49, 7, 25, 'Ili što ste izašli vidjeti: Čovjeka u mekušaste haljine odjevena? Eno, oni u sjajnoj odjeći i raskošju po kraljevskim su dvorima.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (49, 7, 26, 'Ili što ste izašli vidjeti? Proroka? Uistinu, kažem vam, i više nego proroka!');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (49, 7, 27, 'On je onaj o kome je pisano: Evo, šaljem glasnika svoga pred licem tvojim da pripravi put pred tobom.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (49, 7, 28, 'Kažem vam: među rođenima od žene nitko nije veći od Ivana. A ipak, i najmanji u kraljevstvu Božjem veći je od njega.\"');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (49, 7, 29, 'Sav narod koji ga je slušao, pa i carinici, uvidješe pravednost Božju: pokrstiše se Ivanovim krstom.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (49, 7, 30, 'Naprotiv, farizeji i zakonoznanci ometoše što je Bog s njima naumio jer ne htjedoše da ih Ivan krsti.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (49, 7, 31, '\"S kime dakle da prispodobim ljude ovog naraštaja? Komu su nalik?');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (49, 7, 32, 'Nalik su djeci što sjede na trgu pa jedni drugima po poslovici dovikuju: \'Zasvirasmo vam i ne zaigraste! Zakukasmo i ne zaplakaste!\'');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (49, 7, 33, 'Doista, došao je Ivan Krstitelj. Nije kruha jeo ni vina pio, a velite: \'Ðavla ima!\'');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (49, 7, 34, 'Došao je Sin Čovječji koji jede i pije, a govorite: \'Evo izjelice i vinopije, prijatelja carinika i grešnika!\'');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (49, 7, 35, 'Ali opravda se Mudrost pred svom djecom svojom.\"');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (49, 7, 36, 'Neki farizej pozva Isusa da bi blagovao s njime. On uđe u kuću farizejevu i priđe stolu.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (49, 7, 37, 'Kad eto neke žene koja bijaše grešnica u gradu. Dozna da je Isus za stolom u farizejevoj kući pa ponese alabastrenu posudicu pomasti');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (49, 7, 38, 'i stade odostrag kod njegovih nogu. Sva zaplakana poče mu suzama kvasiti noge: kosom ih glave svoje otirala, cjelivala i mazala pomašću.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (49, 7, 39, 'Kad to vidje farizej koji ga pozva, pomisli: \"Kad bi ovaj bio Prorok, znao bi tko i kakva je to žena koja ga se dotiče: da je grešnica.\"');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (49, 7, 40, 'A Isus, da mu odgovori, reče: \"Šimune, imam ti nešto reći.\" A on će: \"Učitelju, reci!\" A on:');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (49, 7, 41, '\"Neki vjerovnik imao dva dužnika. Jedan mu dugovaše pet stotina denara, drugi pedeset.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (49, 7, 42, 'Budući da nisu imali odakle vratiti, otpusti obojici. Koji će ga dakle od njih više ljubiti?\"');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (49, 7, 43, 'Šimun odgovori: \"Predmnijevam, onaj kojemu je više otpustio.\" Reče mu Isus: \"Pravo si prosudio.\"');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (49, 7, 44, 'I okrenut ženi reče Šimunu: \"Vidiš li ovu ženu? Uđoh ti u kuću, nisi mi vodom noge polio, a ona mi suzama noge oblila i kosom ih svojom otrla.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (49, 7, 45, 'Poljupca mi nisi dao, a ona, otkako uđe, ne presta mi noge cjelivati.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (49, 7, 46, 'Uljem mi glave nisi pomazao, a ona mi pomašću noge pomaza.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (49, 7, 47, 'Stoga, kažem ti, oprošteni su joj grijesi mnogi jer ljubljaše mnogo. Komu se malo oprašta, malo ljubi.\"');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (49, 7, 48, 'A ženi reče: \"Oprošteni su ti grijesi.\"');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (49, 7, 49, 'Sustolnici počeli nato među sobom govoriti: \"Tko je ovaj da i grijehe oprašta?\"');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (49, 7, 50, 'A on reče ženi: \"Vjera te tvoja spasila! Idi u miru!\"');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (49, 8, 1, 'Zatim zareda obilaziti gradom i selom propovijedajući i navješćujući evanđelje o kraljevstvu Božjemu. Bila su s njim dvanaestorica');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (49, 8, 2, 'i neke žene koje bijahu izliječene od zlih duhova i bolesti: Marija zvana Magdalena, iz koje bijaše izagnao sedam đavola;');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (49, 8, 3, 'zatim Ivana, žena Herodova upravitelja Huze; Suzana i mnoge druge. One su im posluživale od svojih dobara.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (49, 8, 4, 'Kad se skupio silan svijet te iz svakoga grada nagrnuše k njemu, prozbori u prispodobi:');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (49, 8, 5, '\"Iziđe sijač sijati sjeme. Dok je sijao, jedno pade uz put, bi pogaženo i ptice ga nebeske pozobaše.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (49, 8, 6, 'Drugo pade na kamen i, tek što je izniklo, osuši se jer ne imaše vlage.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (49, 8, 7, 'Drugo opet pade među trnje i trnje ga preraste i uguši.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (49, 8, 8, 'Drugo napokon pade u dobru zemlju, nikne i urodi stostrukim plodom.\" Rekavši to, povika: \"Tko ima uši da čuje, neka čuje!\"');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (49, 8, 9, 'Upitaše ga učenici kakva bi to bila prispodoba.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (49, 8, 10, 'A on im reče: \"Vama je dano znati otajstva kraljevstva Božjega, a ostalima u prispodobama - da gledajući ne vide i slušajući ne razumiju.\"');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (49, 8, 11, '\"A ovo je prispodoba: Sjeme je Riječ Božja.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (49, 8, 12, 'Oni uz put slušatelji su. Zatim dolazi đavao i odnosi Riječ iz srca njihova da ne bi povjerovali i spasili se.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (49, 8, 13, 'A na kamenu - to su oni koji kad čuju, s radošću prime Riječ, ali korijena nemaju: ti neko vrijeme vjeruju, a u vrijeme kušnje otpadnu.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (49, 8, 14, 'A što pade u trnje - to su oni koji poslušaju, ali poneseni brigama, bogatstvom i nasladama života, uguše se i ne dorode roda.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (49, 8, 15, 'Ono pak u dobroj zemlji - to su oni koji u plemenitu i dobru srcu slušaju Riječ, zadrže je i donose rod u ustrajnosti.\"');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (49, 8, 16, '\"Nitko ne užiže svjetiljke da je pokrije posudom ili stavi pod postelju, nego je stavlja na svijećnjak da oni koji ulaze vide svjetlost.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (49, 8, 17, 'Ta ništa nije tajno što se neće očitovati; ništa skriveno što se neće saznati i na vidjelo doći.\"');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (49, 8, 18, '\"Pazite dakle kako slušate. Doista, onomu tko ima dat će se, a onomu tko nema oduzet će se i ono što misli da ima.\"');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (49, 8, 19, 'A majka i braća njegova htjedoše k njemu, ali ne mogoše do njega zbog mnoštva.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (49, 8, 20, 'Javiše mu: \"Majka tvoja i braća tvoja stoje vani i žele te vidjeti.\"');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (49, 8, 21, 'A on im odgovori: \"Majka moja, braća moja - ovi su koji riječ Božju slušaju i vrše.\"');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (49, 8, 22, 'Jednoga dana uđe u lađu on i učenici njegovi. I reče im: \"Prijeđimo na onu stranu jezera.\" I otisnuše se.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (49, 8, 23, 'Dok su plovili, on zaspa. I spusti se oluja na jezero. Voda stane nadirati te bijahu u pogibli.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (49, 8, 24, 'Oni pristupiše i probudiše ga govoreći: \"Učitelju, učitelju, propadosmo!\" On se probudi, zaprijeti vjetru i valovlju; i oni se smire te nasta utiha.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (49, 8, 25, 'A on će im: \"Gdje vam je vjera?\" A oni se prestrašeni u čudu zapitkivahu: \"Tko li je ovaj da i vjetrovima zapovijeda i vodi, i pokoravaju mu se?\"');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (49, 8, 26, 'Doploviše u gergezenski kraj koji je nasuprot Galileji.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (49, 8, 27, 'Čim iziđe na kopno, eto mu iz grada u susret nekog čovjeka koji imaše zloduhe. Već dugo vremena nije se uopće odijevao niti stanovao u kući, nego po grobnicama.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (49, 8, 28, 'Kad opazi Isusa, zastenja, pade ničice preda nj i u sav glas povika: \"Što ti imaš sa mnom, Isuse, Sine Boga Svevišnjega? Molim te, ne muči me!\"');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (49, 8, 29, 'Jer bijaše zapovjedio nečistom duhu da iziđe iz toga čovjeka. Da, dugo ga je već vremena držao u vlasti i makar su ga lancima vezali i u verigama čuvali, on bi raskidao spone i zloduh bi ga odagnao u pustinju.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (49, 8, 30, 'Isus ga nato upita: \"Kako ti je ime?\" On reče: \"Legija\", jer u nj uđoše mnogi zlodusi.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (49, 8, 31, 'I zaklinjahu ga da im ne naredi vratiti se u Bezdan.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (49, 8, 32, 'A ondje u gori paslo je poveliko krdo svinja. Zaklinjahu ga dakle da im dopusti ući u njih. I on im dopusti.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (49, 8, 33, 'Tada zlodusi iziđoše iz čovjeka i uđoše u svinje. Krdo jurnu niz obronak u jezero i podavi se.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (49, 8, 34, 'Vidjevši što se dogodilo, svinjari pobjegoše i razglasiše gradom i selima.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (49, 8, 35, 'A ljudi iziđoše vidjeti što se dogodilo. Dođoše Isusu i nađoše čovjeka iz kojega bijahu izašli zlodusi gdje do nogu Isusovih sjedi, obučen i zdrave pameti. I prestraše se.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (49, 8, 36, 'A očevici im ispripovijediše kako je opsjednuti ozdravio.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (49, 8, 37, 'I zamoli ga sve ono mnoštvo iz okolice gergezenske da ode od njih jer ih strah velik spopade. On uđe u lađu i vrati se.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (49, 8, 38, 'A moljaše ga čovjek iz koga iziđoše zlodusi da može ostati s njim, ali ga on otpusti govoreći:');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (49, 8, 39, '\"Vrati se kući i pripovijedaj što ti učini Bog.\" On ode razglašujući po svem gradu što mu učini Isus.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (49, 8, 40, 'Na povratku Isusa dočeka mnoštvo jer su ga svi željno iščekivali.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (49, 8, 41, 'I gle, dođe čovjek, ime mu Jair, koji bijaše predstojnik sinagoge. Baci se Isusu pred noge i stane ga moliti da dođe u njegovu kuću.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (49, 8, 42, 'Imaše kćer jedinicu, otprilike od dvanaest godina, koja umiraše. Dok je onamo išao, mnoštvo ga guralo odasvud.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (49, 8, 43, 'A neka žena koja je već dvanaest godina bolovala od krvarenja, sve svoje imanje potrošila na liječnike i nitko je nije mogao izliječiti,');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (49, 8, 44, 'priđe odostrag i dotaknu se skuta njegove haljine i umah joj se zaustavi krvarenje.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (49, 8, 45, 'I reče Isus: \"Tko me se to dotaknu?\" Svi se branili, a Petar će: \"Učitelju, mnoštvo te gura i pritišće.\"');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (49, 8, 46, 'A Isus: \"Netko me se dotaknuo. Osjetio sam kako snaga izlazi iz mene.\"');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (49, 8, 47, 'A žena, vidjevši da se ne može kriti, sva u strahu pristupi i baci se preda nj te pred svim narodom ispripovjedi zašto ga se dotakla i kako je umah ozdravila.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (49, 8, 48, 'A on joj reče: \"Kćeri, vjera te tvoja spasila. Idi u miru!\"');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (49, 8, 49, 'Dok je on još govorio, eto jednog od nadstojnikovih s porukom: \"Umrla ti kći, ne muči više Učitelja.\"');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (49, 8, 50, 'Čuo to Isus pa mu reče: \"Ne boj se! Samo vjeruj i ona će se spasiti!\"');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (49, 8, 51, 'Uđe u kuću, ali nikomu ne dopusti da s njim uđe osim Petra, Ivana, Jakova i djetetova oca i majke.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (49, 8, 52, 'A svi plakahu i žalovahu za njom. A on im reče: \"Ne plačite! Nije umrla, nego spava!\"');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (49, 8, 53, 'No oni mu se podsmjehivahu znajući da je umrla.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (49, 8, 54, 'On je uhvati za ruku i povika: \"Dijete, ustani!\"');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (49, 8, 55, 'I povrati joj se duh i umah ustade, a on naredi da joj dadu jesti.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (49, 8, 56, 'Njezini se roditelji začudiše, a on zapovjedi da nikome ne reknu što se dogodilo.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (49, 9, 1, 'Sazva dvanaestoricu i dade im moć i vlast nad svim zlodusima i da liječe bolesti.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (49, 9, 2, 'I posla ih propovijedati kraljevstvo Božje i liječiti bolesnike.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (49, 9, 3, 'I reče im: \"Ništa ne uzimajte na put: ni štapa, ni torbe, ni kruha, ni srebra! I da niste imali više od dvije haljine!');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (49, 9, 4, 'U koju god kuću uđete, ondje ostanite pa odande dalje pođite.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (49, 9, 5, 'Gdje vas ne prime, iziđite iz toga grada i stresite prašinu s nogu za svjedočanstvo protiv njih.\"');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (49, 9, 6, 'Oni krenuše: obilazili su po selima, navješćivali evanđelje i liječili posvuda.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (49, 9, 7, 'Dočuo Herod tetrarh sve što se događa te se nađe u nedoumici jer su neki govorili: \"Ivan uskrsnu od mrtvih\";');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (49, 9, 8, 'drugi: \"Pojavio se Ilija\"; treći opet: \"Ustao je neki od drevnih proroka.\"');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (49, 9, 9, 'A Herod reče: \"Ivanu ja odrubih glavu. Tko je onda ovaj o kom toliko čujem?\" I tražio je priliku da ga vidi.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (49, 9, 10, 'Apostoli se vrate i ispripovjede što su učinili. Isus ih povede sa sobom i povuče se nasamo u grad zvani Betsaida.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (49, 9, 11, 'Saznalo to mnoštvo po pođe za njim. On ih primi te im govoraše o kraljevstvu Božjem i ozdravljaše sve koji su trebali ozdravljenja.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (49, 9, 12, 'Dan bijaše na izmaku. Pristupe dakle dvanaestorica pa mu reknu: \"Otpusti svijet, neka pođu po okolnim selima i zaseocima da se sklone i nađu jela jer smo ovdje u pustu kraju.\"');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (49, 9, 13, 'A on im reče: \"Podajte im vi jesti!\" Oni rekoše: \"Nemamo više od pet kruhova i dvije ribe, osim da odemo kupiti hrane za sav ovaj narod.\"');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (49, 9, 14, 'A bijaše oko pet tisuća muškaraca. Nato će on svojim učenicima: \"Posjedajte ih po skupinama, otprilike po pedeset.\"');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (49, 9, 15, 'I učine tako: sve ih posjedaju.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (49, 9, 16, 'A on uze pet kruhova i dvije ribe, pogleda na nebo, blagoslovi ih i razlomi pa davaše učenicima da posluže mnoštvo.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (49, 9, 17, 'Jeli su i svi se nasitili. I od preteklih ulomaka nakupilo se dvanaest košara.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (49, 9, 18, 'Dok je jednom u osami molio, bijahu s njim samo njegovi učenici. On ih upita: \"Što govori svijet, tko sam ja?\"');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (49, 9, 19, 'Oni odgovoriše: \"Da si Ivan Krstitelj, drugi: da si Ilija, treći opet: da neki od drevnih proroka usta.\"');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (49, 9, 20, 'A on im reče: \"A vi, što vi kažete, tko sam ja?\" Petar prihvati i reče: \"Krist - Pomazanik Božji!\"');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (49, 9, 21, 'A on im zaprijeti da toga nikomu ne kazuju.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (49, 9, 22, 'Reče: \"Treba da Sin Čovječji mnogo pretrpi, da ga starješine, glavari svećenički i pismoznanci odbace, da bude ubijen i treći dan da uskrsne.\"');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (49, 9, 23, 'A govoraše svima: \"Hoće li tko za mnom, neka se odrekne samoga sebe, neka danomice uzima križ svoj i neka ide za mnom.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (49, 9, 24, 'Tko hoće život svoj spasiti, izgubit će ga; a tko izgubi život svoj poradi mene, taj će ga spasiti.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (49, 9, 25, 'Ta što koristi čovjeku ako sav svijet zadobije, a sebe samoga izgubi ili sebi naudi?\"');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (49, 9, 26, '\"Doista, tko se zastidi mene i mojih riječi, toga će se i Sin Čovječji stidjeti kada dođe u slavi svojoj i Očevoj i svetih anđela.\"');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (49, 9, 27, '\"A kažem vam uistinu: neki od nazočnih neće okusiti smrti dok ne vide kraljevstva Božjega.\"');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (49, 9, 28, 'Jedno osam dana nakon tih besjeda povede Isus sa sobom Petra, Ivana i Jakova te uziđe na goru da se pomoli.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (49, 9, 29, 'I dok se molio, izgled mu se lica izmijeni, a odjeća sjajem zablista.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (49, 9, 30, 'I gle, dva čovjeka razgovarahu s njime. Bijahu to Mojsije i Ilija.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (49, 9, 31, 'Ukazali se u slavi i razgovarali s njime o njegovu Izlasku, što se doskora imao ispuniti u Jeruzalemu.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (49, 9, 32, 'No Petra i njegove drugove bijaše svladao san. Kad se probudiše, ugledaše njegovu slavu i dva čovjeka koji stajahu uza nj.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (49, 9, 33, 'I dok su oni odlazili od njega, reče Petar Isusu: \"Učitelju, dobro nam je ovdje biti. Načinimo tri sjenice: jednu tebi, jednu Mojsiju, jednu Iliji.\" Nije znao što govori.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (49, 9, 34, 'Dok je on to govorio, pojavi se oblak i zasjeni ih. Ušavši u oblak, oni se prestrašiše.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (49, 9, 35, 'A glas se začu iz oblaka: \"Ovo je Sin moj, Izabranik! Njega slušajte!\"');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (49, 9, 36, 'I upravo kad se začu glas, osta Isus sam. Oni su šutjeli i nikomu onih dana nisu kazivali što su vidjeli.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (49, 9, 37, 'A kad su sutradan sišli s gore, pohiti mu u susret silan svijet.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (49, 9, 38, 'I gle, čovjek neki iz mnoštva povika: \"Učitelju, molim te pogledaj mi sina: jedinac mi je,');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (49, 9, 39, 'a gle, duh ga spopada te on odmah udari u kriku; trza njime i on se pjeni te jedva da od njega odstupi dok ga nije posve satro.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (49, 9, 40, 'Molio sam tvoje učenike da ga izagnaju, ali ne mogoše.\"');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (49, 9, 41, 'Isus odvrati: \"O rode nevjerni i opaki, dokle mi je biti s vama i podnositi vas? Dovedi ovamo svoga sina!\"');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (49, 9, 42, 'I dok je prilazio, obori ga zloduh i potrese. A Isus zaprijeti nečistom duhu te izliječi dječaka i preda ga njegovu ocu.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (49, 9, 43, 'Svi se zapanjiše zbog veličanstva Božjega. Dok su se svi divili svemu što je činio, reče on učenicima:');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (49, 9, 44, '\"Uzmite k srcu ove riječi: Sin Čovječji doista ima biti predan ljudima u ruke.\"');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (49, 9, 45, 'Ali oni nerazumješe te besjede, bijaše im skrivena te ne shvatiše, a bojahu se upitati ga o tome.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (49, 9, 46, 'U njima se porodi misao tko bi od njih bio najveći.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (49, 9, 47, 'Znajući tu misao njihova srca, uzme Isus dijete, postavi ga uza se');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (49, 9, 48, 'i reče im: \"Tko god primi ovo dijete u moje ime, mene prima. A tko mene prima, prima onoga koji me je poslao. Doista, tko je najmanji među vama svima, taj je velik!\"');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (49, 9, 49, 'Prihvati Ivan i reče: \"Učitelju, vidjesmo jednoga koji u tvoje ime izgoni zloduhe. Mi smo mu branili, jer ne ide za nama.\"');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (49, 9, 50, 'Reče mu Isus: \"Ne branite! Ta tko nije protiv vas, za vas je!\"');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (49, 9, 51, 'Kad su se navršili dani da bude uznesen, krenu Isus sa svom odlučnošću prema Jeruzalemu.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (49, 9, 52, 'I posla glasnike pred sobom. Oni odoše i uđoše u neko samarijansko selo da mu priprave mjesto.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (49, 9, 53, 'No ondje ga ne primiše jer je bio na putu u Jeruzalem.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (49, 9, 54, 'Kada to vidješe učenici Jakov i Ivan, rekoše: \"Gospodine, hoćeš li da kažemo neka oganj siđe s neba i uništi ih?\"');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (49, 9, 55, 'No on se okrenu i prekori ih.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (49, 9, 56, 'I odoše u drugo selo.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (49, 9, 57, 'Dok su išli putom, reče mu netko: \"Za tobom ću kamo god ti pošao.\"');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (49, 9, 58, 'Reče mu Isus: \"Lisice imaju jazbine, ptice nebeske gnijezda, a Sin Čovječji nema gdje bi glavu naslonio.\"');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (49, 9, 59, 'Drugomu nekom reče: \"Pođi za mnom!\" A on će mu: \"Dopusti mi da prije odem i pokopam oca.\"');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (49, 9, 60, 'Reče mu: \"Pusti neka mrtvi pokapaju svoje mrtve, a ti idi i navješćuj kraljevstvo Božje.\"');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (49, 9, 61, 'I neki drugi reče: \"Za tobom ću, Gospodine, ali dopusti mi da se prije oprostim sa svojim ukućanima.\"');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (49, 9, 62, 'Reče mu Isus: \"Nitko tko stavi ruku na plug pa se obazire natrag, nije prikladan za kraljevstvo Božje.\"');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (49, 10, 1, 'Nakon toga odredi Gospodin drugih sedamdesetdvojicu učenika i posla ih po dva pred sobom u svaki grad i u svako mjesto kamo je kanio doći.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (49, 10, 2, 'Govorio im je: \"Žetva je velika, ali radnika malo. Molite dakle gospodara žetve da radnike pošalje u žetvu svoju.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (49, 10, 3, 'Idite! Evo, šaljem vas kao janjce među vukove.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (49, 10, 4, 'Ne nosite sa sobom ni kese, ni torbe, ni obuće. I nikoga putem ne pozdravljajte.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (49, 10, 5, 'U koju god kuću uđete, najprije recite: \'Mir kući ovoj!\'');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (49, 10, 6, 'Bude li tko ondje prijatelj mira, počinut će na njemu mir vaš. Ako li ne, vratit će se na vas.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (49, 10, 7, 'U toj kući ostanite, jedite i pijte što se kod njih nađe. Ta vrijedan je radnik plaće svoje. Ne prelazite iz kuće u kuću.\"');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (49, 10, 8, '\"Kad u koji grad uđete pa vas prime, jedite što vam se ponudi');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (49, 10, 9, 'i liječite bolesnike koji su u njemu. I kazujte im: \'Približilo vam se kraljevstvo Božje!\'');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (49, 10, 10, 'A kad u neki grad uđete pa vas ne prime, iziđite na njegove ulice i recite:');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (49, 10, 11, '\'I prašinu vašega grada, koja nam se nogu uhvatila, stresamo vam sa sebe! Ipak znajte ovo: Približilo se kraljevstvo Božje!\'');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (49, 10, 12, 'Kažem vam: Sodomcima će u onaj dan biti lakše negoli tomu gradu.\"');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (49, 10, 13, '\"Jao tebi, Korozaine! Jao tebi, Betsaido! Da su se u Tiru i Sidonu zbila čudesa koja su se dogodila u vama, odavna bi već, sjedeć u kostrijeti i pepelu, činili pokoru.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (49, 10, 14, 'Ali Tiru i Sidonu bit će na Sudu lakše negoli vama.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (49, 10, 15, 'I ti Kafarnaume! Zar ćeš se do neba uzvisiti? Do u Podzemlje ćeš se strovaliti.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (49, 10, 16, 'Tko vas sluša, mene sluša; tko vas prezire, mene prezire. A tko mene prezire, prezire onoga koji mene posla.\"');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (49, 10, 17, 'Vratiše se zatim sedamdesetdvojica radosni govoreći: \"Gospodine, i zlodusi nam se pokoravaju na tvoje ime!\"');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (49, 10, 18, 'A on im reče: \"Promatrah Sotonu kako poput munje s neba pade.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (49, 10, 19, 'Evo, dao sam vam vlast da gazite po zmijama i štipavcima i po svoj sili neprijateljevoj i ništa vam neće naškoditi.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (49, 10, 20, 'Ali ne radujte se što vam se duhovi pokoravaju, nego radujte se što su vam imena zapisana na nebesima.\"');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (49, 10, 21, 'U taj isti čas uskliknu Isus u Duhu Svetom: \"Slavim te, Oče, Gospodaru neba i zemlje, što si ovo sakrio od mudrih i umnih, a objavio malenima. Da, Oče! Tako se tebi svidjelo.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (49, 10, 22, 'Sve mi preda Otac moj i nitko ne zna tko je Sin - doli Otac; niti tko je Otac - doli Sin i onaj kome Sin hoće da objavi.\"');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (49, 10, 23, 'Tada se okrene učenicima pa im nasamo reče: \"Blago očima koje gledaju što vi gledate!');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (49, 10, 24, 'Kažem vam: mnogi su proroci i kraljevi htjeli vidjeti što vi gledate, ali nisu vidjeli; i čuti što vi slušate, ali nisu čuli!\"');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (49, 10, 25, 'I gle, neki zakonoznanac usta i, da ga iskuša, upita: \"Učitelju, što mi je činiti da život vječni baštinim?\"');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (49, 10, 26, 'A on mu reče: \"U Zakonu što piše? Kako čitaš?\"');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (49, 10, 27, 'Odgovori mu onaj: Ljubi Gospodina Boga svojega iz svega srca svoga, i svom dušom svojom, i svom snagom svojom, i svim umom svojim; i svoga bližnjega kao sebe samoga!\"');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (49, 10, 28, 'Reče mu na to Isus: \"Pravo si odgovorio. To čini i živjet ćeš.\"');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (49, 10, 29, 'Ali hoteći se opravdati, reče on Isusu: \"A tko je moj bližnji?\"');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (49, 10, 30, 'Isus prihvati i reče: \"Čovjek neki silazio iz Jeruzalema u Jerihon. Upao među razbojnike koji ga svukoše i izraniše pa odoše ostavivši ga polumrtva.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (49, 10, 31, 'Slučajno je onim putem silazio neki svećenik, vidje ga i zaobiđe.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (49, 10, 32, 'A tako i levit: prolazeći onuda, vidje ga i zaobiđe.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (49, 10, 33, 'Neki Samarijanac putujući dođe do njega, vidje ga, sažali se');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (49, 10, 34, 'pa mu pristupi i povije rane zalivši ih uljem i vinom. Zatim ga posadi na svoje živinče, odvede ga u gostinjac i pobrinu se za nj.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (49, 10, 35, 'Sutradan izvadi dva denara, dade ih gostioničaru i reče: \'Pobrini se za njega. Ako što više potrošiš, isplatit ću ti kad se budem vraćao.\'\"');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (49, 10, 36, '\"Što ti se čini, koji je od ove trojice bio bližnji onomu koji je upao među razbojnike?\"');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (49, 10, 37, 'On odgovori: \"Onaj koji mu iskaza milosrđe.\" Nato mu reče Isus: \"Idi pa i ti čini tako!\"');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (49, 10, 38, 'Dok su oni tako putovali, uđe on u jedno selo. Žena neka, imenom Marta, primi ga u kuću.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (49, 10, 39, 'Imala je sestru koja se zvala Marija. Ona sjede do nogu Gospodinovih i slušaše riječ njegovu.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (49, 10, 40, 'A Marta bijaše sva zauzeta posluživanjem pa pristupi i reče: \"Gospodine, zar ne mariš što me sestra samu ostavila posluživati? Reci joj dakle da mi pomogne.\"');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (49, 10, 41, 'Odgovori joj Gospodin: \"Marta, Marta! Brineš se i uznemiruješ za mnogo,');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (49, 10, 42, 'a jedno je potrebno. Marija je uistinu izabrala bolji dio, koji joj se neće oduzeti.\"');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (49, 11, 1, 'Jednom je Isus na nekome mjestu molio. Čim presta, reče mu jedan od učenika: \"Gospodine, nauči nas moliti kao što je i Ivan naučio svoje učenike.\"');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (49, 11, 2, 'On im reče: \"Kad molite, govorite: \'Oče! Sveti se ime tvoje! Dođi kraljevstvo tvoje!');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (49, 11, 3, 'Kruh naš svagdanji daji nam svaki dan!');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (49, 11, 4, 'I otpusti nam grijehe naše: ta i mi otpuštamo svakom dužniku svojem! I ne uvedi nas u napast!\'\"');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (49, 11, 5, 'I reče im: \"Tko to od vas ima ovakva prijatelja? Pođe k njemu o ponoći i rekne mu: \'Prijatelju, posudi mi tri kruha.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (49, 11, 6, 'Prijatelj mi se s puta svratio te nemam što staviti preda nj!\'');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (49, 11, 7, 'A onaj mu iznutra odgovori: \'Ne dosađuj mi! Vrata su već zatvorena, a dječica sa mnom u postelji. Ne mogu ustati da ti dadnem...\'');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (49, 11, 8, 'Kažem vam: ako i ne ustane da mu dadne zato što mu je prijatelj, ustat će i dati mu što god treba zbog njegove bezočnosti.\"');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (49, 11, 9, '\"I ja vama kažem: Ištite i dat će vam se! Tražite i naći ćete! Kucajte i otvorit će vam se!');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (49, 11, 10, 'Doista, tko god ište, prima; i tko traži, nalazi; i onomu tko kuca, otvorit će se.\"');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (49, 11, 11, '\"A koji je to otac među vama: kad ga sin zaište ribu, zar će mu mjesto ribe zmiju dati?');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (49, 11, 12, 'Ili kad zaište jaje, zar će mu dati štipavca?');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (49, 11, 13, 'Ako dakle vi, iako zli, znate dobrim darima darivati djecu svoju, koliko li će više Otac s neba obdariti Duhom Svetim one koji ga zaištu!\"');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (49, 11, 14, 'I istjerivaše đavla koji bijaše nijem. Kad iziđe đavao, progovori njemak. I mnoštvo se divilo.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (49, 11, 15, 'A neki od njih rekoše: \"Po Beelzebulu, poglavici đavolskom, izgoni đavle!\"');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (49, 11, 16, 'A drugi su iskušavajući ga, tražili od njega kakav znak s neba.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (49, 11, 17, 'Ali on, znajući njihove misli, reče im: \"Svako kraljevstvo u sebi razdijeljeno opustjet će i kuća će na kuću pasti.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (49, 11, 18, 'Ako je dakle Sotona u sebi razdijeljen, kako će opstati kraljevstvo njegovo? Jer vi kažete da ja po Beelzebulu izgonim đavle.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (49, 11, 19, 'Ako dakle ja po Beelzebulu izgonim đavle, po kome ih vaši sinovi izgone? Zato će vam oni biti suci.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (49, 11, 20, 'Ali ako ja prstom Božjim izgonim đavle, zbilja je došlo k vama kraljevstvo Božje.\"');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (49, 11, 21, '\"Dokle god jaki i naoružani čuva svoj stan, u miru je sav njegov posjed.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (49, 11, 22, 'Ali ako dođe jači od njega, svlada ga i otme mu sve njegovo oružje u koje se uzdao, a plijen razdijeli.\"');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (49, 11, 23, '\"Tko nije sa mnom, protiv mene je. I tko sa mnom ne sabire, rasipa.\"');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (49, 11, 24, '\"Kad nečisti duh iziđe iz čovjeka, luta bezvodnim mjestima tražeći spokoja. Kad ga ne nađe, rekne: \'Vratit ću se u kuću odakle iziđoh.\'');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (49, 11, 25, 'Došavši, nađe je pometenu i uređenu.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (49, 11, 26, 'Tada ode i uzme sa sobom sedam drugih duhova, gorih od sebe, te uđu i nastane se ondje. Na kraju bude onomu čovjeku gore nego na početku.\"');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (49, 11, 27, 'Dok je on to govorio, povika neka žena iz mnoštva: \"Blažena utroba koja te nosila i prsi koje si sisao!\"');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (49, 11, 28, 'On odgovori: \"Još blaženiji oni koji slušaju riječ Božju i čuvaju je!\"');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (49, 11, 29, 'Kad je nagrnulo mnoštvo, poče im Isus govoriti: \"Naraštaj ovaj naraštaj je opak. Znak traži, ali mu se znak neće dati doli znak Jonin.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (49, 11, 30, 'Doista, kao što je Jona bio znak Ninivljanima, tako će biti i Sin Čovječji ovomu naraštaju.\"');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (49, 11, 31, '\"Kraljica će Juga ustati na Sudu s ljudima ovog naraštaja i osuditi ih jer je s krajeva zemlje došla čuti mudrost Salomonovu, a evo ovdje i više od Salomona!');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (49, 11, 32, 'Ninivljani će ustati na Sudu s ovim naraštajem i osuditi ga jer se obratiše na propovijed Joninu, a evo ovdje i više od Jone!\"');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (49, 11, 33, '\"Nitko ne užiže svjetiljku da je stavi u zakutak ili pod posudu, nego na svijećnjak da oni koji ulaze vide svjetlost.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (49, 11, 34, 'Oko je svjetiljka tvomu tijelu. Kad ti je oko bistro, sve ti je tijelo svijetlo. A kad je ono nevaljalo, i tijelo ti je tamno.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (49, 11, 35, 'Pazi dakle da svjetlost koja je u tebi ne bude tamna.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (49, 11, 36, 'Ako ti dakle sve tijelo bude svijetlo, bez djelića tame, bit će posve svijetlo, kao kad te svjetiljka svojim sjajem rasvjetljuje.\"');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (49, 11, 37, 'Dok je on govorio, pozva ga neki farizej k sebi na objed. On uđe i priđe k stolu.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (49, 11, 38, 'Vidjevši to, farizej se začudi što se Isus prije objeda ne opra.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (49, 11, 39, 'A Gospodin mu reče: \"Da, vi farizeji čistite vanjštinu čaše u zdjele, a nutrina vam je puna grabeža i pakosti.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (49, 11, 40, 'Bezumnici! Nije li onaj koji načini vanjštinu načinio i nutrinu.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (49, 11, 41, 'Nego, dajte za milostinju ono iznutra i gle - sve vam je čisto.\"');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (49, 11, 42, '\"Ali jao vama, farizeji! Namirujete desetinu od metvice i rutvice i svake vrste povrća, a ne marite za pravednost i ljubav Božju. Ovo je trebalo činiti, a ono ne zanemariti.\"');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (49, 11, 43, '\"Jao vama farizeji! Volite prvo sjedalo u sinagogama i pozdrave na trgovima.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (49, 11, 44, 'Jao vama! Vi ste kao nezamjetljivi grobovi po kojima ljudi ne znajući hode.\"');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (49, 11, 45, 'Nato će neki zakonoznanac: \"Učitelju, tako govoreći i nas vrijeđaš.\"');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (49, 11, 46, 'A on reče: \"Jao i vama, zakonoznanci! Tovarite na ljude terete nepodnosive, a sami ni da ih se jednim prstom dotaknete.\"');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (49, 11, 47, '\"Jao vama! Podižete spomenike prorocima, a vaši ih oci ubiše.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (49, 11, 48, 'Zato ste svjedoci i sumišljenici djela svojih otaca: oni ih ubiše, a vi spomenike podižete!');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (49, 11, 49, 'Zbog toga i kaza Mudrost Božja: \'Poslat ću k njima proroke i apostole. Neke će poubijati i prognati -');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (49, 11, 50, 'da se od ovog naraštaja zatraži krv svih proroka prolivena od postanka svijeta,');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (49, 11, 51, 'od krvi Abelove do krvi Zaharije, koji je pogubljen između žrtvenika i svetišta.\' Da, kažem vam, tražit će se od ovoga naraštaja!\"');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (49, 11, 52, '\"Jao vama, zakonoznanci! Uzeste ključ znanja: sami ne uđoste, a spriječiste one koji htjedoše ući.\"');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (49, 11, 53, 'Kad Isus izađe odande, stadoše pismoznanci i farizeji žestoko na nj navaljivati i postavljati mu mnoga pitanja');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (49, 11, 54, 'vrebajući na nj, ne bi li štogod ulovili iz njegovih usta.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (49, 12, 1, 'Kad se uto skupilo mnoštvo, tisuće i tisuće, te su jedni druge gazili, poče Isus govoriti najprije svojim učenicima: \"Čuvajte se kvasca farizejskoga, to jest licemjerja.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (49, 12, 2, 'Ništa nije skriveno što se neće otkriti ni tajno što se neće saznati.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (49, 12, 3, 'Naprotiv, sve što u tami rekoste, na svjetlu će se čuti; i što ste po skrovištima u uho šaptali, propovijedat će se po krovovima.\"');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (49, 12, 4, '\"A kažem vama, prijateljima svojim: ne bojte se onih koji ubijaju tijelo, a nakon toga nemaju više što učiniti.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (49, 12, 5, 'Pokazat ću vam koga vam se bojati: onoga se bojte koji pošto ubije, ima moć baciti u pakao. Da, velim vam, njega se bojte!');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (49, 12, 6, 'Ne prodaje li se pet vrapčića za dva novčića? Pa ipak ni jednoga od njih Bog ne zaboravlja.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (49, 12, 7, 'A vama su i vlasi na glavi sve izbrojene. Ne bojte se! Vredniji ste nego mnogo vrabaca!\"');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (49, 12, 8, '\"A kažem vam: tko se god prizna mojim pred ljudima, i Sin Čovječji priznat će se njegovim pred anđelima Božjim.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (49, 12, 9, 'A tko mene zaniječe pred ljudima, bit će zanijekan pred anđelima Božjim.\"');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (49, 12, 10, '\"I tko god rekne riječ na Sina Čovječjega, oprostit će mu se. Ali tko pohuli protiv Duha Svetoga, neće mu se oprostiti.\"');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (49, 12, 11, '\"Nadalje, kad vas budu dovodili pred sinagoge i poglavarstva i vlasti, ne budite zabrinuti kako ćete se ili čime braniti, što li reći!');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (49, 12, 12, 'Ta Duh Sveti poučit će vas u taj čas što valja reći.\"');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (49, 12, 13, 'Tada mu netko iz mnoštva reče: \"Učitelju, reci mome bratu da podijeli sa mnom baštinu.\"');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (49, 12, 14, 'Nato mu on reče: \"Čovječe, tko me postavio sucem ili djeliocem nad vama?\"');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (49, 12, 15, 'I dometnu im: \"Klonite se i čuvajte svake pohlepe: koliko god netko obilovao, život mu nije u onom što posjeduje.\"');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (49, 12, 16, 'Kaza im i prispodobu: \"Nekomu bogatu čovjeku obilno urodi zemlja');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (49, 12, 17, 'pa u sebi razmišljaše: \'Što da učinim? Nemam gdje skupiti svoju ljetinu.\'');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (49, 12, 18, 'I reče: \'Evo što ću učiniti! Srušit ću svoje žitnice i podignuti veće pa ću ondje zgrnuti sve žito i dobra svoja.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (49, 12, 19, 'Tada ću reći duši svojoj: dušo, evo imaš u zalihi mnogo dobara za godine mnoge. Počivaj, jedi, pij, uživaj!\'');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (49, 12, 20, 'Ali Bog mu reče: \'Bezumniče! Već noćas duša će se tvoja zaiskati od tebe! A što si pripravio, čije će biti?\'');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (49, 12, 21, 'Tako biva s onim koji sebi zgrće blago, a ne bogati se u Bogu.\"');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (49, 12, 22, 'Zatim reče svojim učenicima: \"Zato vam kažem: ne budite zabrinuti za život: što ćete jesti; ni za tijelo: u što ćete se obući.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (49, 12, 23, 'Ta život je vredniji od jela i tijelo od odijela.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (49, 12, 24, 'Promotrite gavrane! Ne siju niti žanju, nemaju spremišta ni žitnice, pa ipak ih Bog hrani. Koliko li ste vi vredniji od ptica!');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (49, 12, 25, 'A tko od vas zabrinutošću može svojemu stasu dodati lakat?');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (49, 12, 26, 'Ako dakle ni ono najmanje ne možete, što ste onda za ostalo zabrinuti?');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (49, 12, 27, 'Promotrite ljiljane, kako niti predu niti tkaju, a kažem vam: ni Salomon se u svoj svojoj slavi ne zaodjenu kao jedan od njih.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (49, 12, 28, 'Pa ako travu koja je danas u polju, a sutra se u peć baca Bog tako odijeva, koliko li će više vas, malovjerni!\"');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (49, 12, 29, '\"Zato i vi: ne tražite što ćete jesti, što piti. Ne uznemirujte se!');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (49, 12, 30, 'Ta sve to traže pogani ovoga svijeta. Otac vaš zna da vam je sve to potrebno.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (49, 12, 31, 'Nego, tražite kraljevstvo njegovo, a to će vam se nadodati!\"');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (49, 12, 32, '\"Ne boj se, stado malo: svidjelo se Ocu vašemu dati vam Kraljevstvo.\"');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (49, 12, 33, '\"Prodajte što god imate i dajte za milostinju! Načinite sebi kese koje ne stare, blago nepropadljivo na nebesima, kamo se kradljivac ne približava i gdje moljac ne rastače.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (49, 12, 34, 'Doista, gdje vam je blago, ondje će vam i srce biti.\"');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (49, 12, 35, '\"Neka vam bokovi budu opasani i svjetiljke upaljene,');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (49, 12, 36, 'a vi slični ljudima što čekaju gospodara kad se vraća sa svadbe da mu odmah otvore čim stigne i pokuca.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (49, 12, 37, 'Blago onim slugama koje gospodar, kada dođe, nađe budne! Zaista, kažem vam, pripasat će se, posaditi ih za stol pa će pristupiti i posluživati ih.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (49, 12, 38, 'Pa dođe li o drugoj ili o trećoj straži i nađe ih tako, blago njima!\"');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (49, 12, 39, '\"A ovo znajte: kad bi domaćin znao u koji čas kradljivac dolazi, ne bi dao prokopati kuće.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (49, 12, 40, 'I vi budite pripravni jer u čas kad i ne mislite Sin Čovječji dolazi.\"');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (49, 12, 41, 'Nato će Petar: \"Gospodine, govoriš li tu prispodobu samo za nas ili i za sve?\"');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (49, 12, 42, 'Reče Gospodin: \"Tko li je onaj vjerni i razumni upravitelj što će ga gospodar postaviti nad svojom poslugom da im u pravo vrijeme daje obrok?');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (49, 12, 43, 'Blago onome sluzi kojega gospodar kada dođe, nađe da tako radi.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (49, 12, 44, 'Uistinu, kažem vam, postavit će ga nad svim imanjem svojim.\"');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (49, 12, 45, '\"No rekne li taj sluga u srcu: \'Okasnit će gospodar moj\' pa stane tući sluge i sluškinje, jesti, piti i opijati se,');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (49, 12, 46, 'doći će gospodar toga sluge u dan u koji mu se ne nada i u čas u koji i ne sluti; rasjeći će ga i dodijeliti mu udes među nevjernicima.\"');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (49, 12, 47, '\"I onaj sluga što je znao volju gospodara svoga, a nije bio spreman ili nije učinio po volji njegovoj, dobit će mnogo udaraca.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (49, 12, 48, 'A onaj koji nije znao, ali je učinio što zaslužuje udarce, dobit će malo udaraca. Kome je god mnogo dano, od njega će se mnogo iskati. Kome je mnogo povjereno, više će se od njega iskati.\"');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (49, 12, 49, '\"Oganj dođoh baciti na zemlju pa što hoću ako je već planuo!');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (49, 12, 50, 'Ali krstom mi se krstiti i kakve li muke za me dok se to ne izvrši!\"');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (49, 12, 51, '\"Mislite li da sam došao mir dati na zemlji? Nipošto, kažem vam, nego razdjeljenje.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (49, 12, 52, 'Ta bit će odsada petorica u jednoj kući razdijeljena: razdijelit će se trojica protiv dvojice i dvojica protiv trojice -');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (49, 12, 53, 'otac protiv sina i sin protiv oca, mati protiv kćeri i kći protiv matere, svekrva protiv snahe i snaha protiv svekrve.\"');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (49, 12, 54, 'Zatim je govorio mnoštvu: \"Kad opazite da se oblak diže na zapadu, odmah kažete: \'Kiša će!\' I bude tako.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (49, 12, 55, 'Kad zapuše južnjak, kažete: \'Bit će vrućine!\' I bude.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (49, 12, 56, 'Licemjeri! Lice zemlje i neba umijete rasuditi, kako onda ovo vrijeme ne rasuđujete?\"');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (49, 12, 57, '\"Zašto sami od sebe ne sudite što je pravo?');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (49, 12, 58, 'Kad s protivnikom ideš glavaru, na putu sve uloži da ga se oslobodiš pa te ne odvuče k sucu. Sudac će te predati izvršitelju, a izvršitelj baciti u tamnicu.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (49, 12, 59, 'Kažem ti: nećeš izići odande dok ne isplatiš do posljednjega novčića.\"');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (49, 13, 1, 'Upravo u taj čas dođoše neki te mu javiše što se dogodilo s Galilejcima kojih je krv Pilat pomiješao s krvlju njihovih žrtava.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (49, 13, 2, 'Isus im odgovori: \"Mislite li da ti Galilejci, jer tako postradaše, bijahu grešniji od drugih Galilejaca?');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (49, 13, 3, 'Nipošto, kažem vam, nego ako se ne obratite, svi ćete slično propasti!');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (49, 13, 4, 'Ili onih osamnaest na koje se srušila kula u Siloamu i ubila ih, zar mislite da su oni bili veći dužnici od svih Jeruzalemaca?');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (49, 13, 5, 'Nipošto, kažem vam, nego ako se ne obratite, svi ćete tako propasti.\"');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (49, 13, 6, 'Nato im pripovjedi ovu prispodobu: \"Imao netko smokvu zasađenu u svom vinogradu. Dođe tražeć ploda na njoj i ne nađe');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (49, 13, 7, 'pa reče vinogradaru: \'Evo, već tri godine dolazim i tražim ploda na ovoj smokvi i ne nalazim. Posijeci je. Zašto da iscrpljuje zemlju?\'');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (49, 13, 8, 'A on mu odgovori: \'Gospodaru, ostavi je još ove godine dok je ne okopam i ne pognojim.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (49, 13, 9, 'Možda će ubuduće ipak uroditi. Ako li ne, posjeći ćeš je.\'\"');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (49, 13, 10, 'Jedne je subote naučavao u nekoj sinagogi.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (49, 13, 11, 'Kad eto žene koja je osamnaest godina imala duha bolesti. Bila je zgrbljena i nikako se nije mogla uspraviti.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (49, 13, 12, 'Kad je Isus opazi, dozva je i reče joj: \"Ženo, oslobođena si svoje bolesti!\"');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (49, 13, 13, 'I položi na nju ruke, a ona se umah uspravi i poče slaviti Boga.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (49, 13, 14, 'Nadstojnik sinagoge - ozlovoljen što je Isus u subotu izliječio - govoraše mnoštvu: \"Šest je dana u koje treba raditi! U te dakle dane dolazite i liječite se, a ne u dan subotni!\"');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (49, 13, 15, 'Odgovori mu Gospodin: \"Licemjeri! Ne driješi li svaki od vas u subotu svoga vola ili magarca od jasala da ga vodi na vodu?');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (49, 13, 16, 'Nije li dakle i ovu kćer Abrahamovu, koju Sotona sveza evo osamnaest je već godina, trebalo odriješiti od tih spona u dan subotni?\"');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (49, 13, 17, 'Na te njegove riječi postidješe se svi protivnici njegovi, a sav se narod radovaše zbog svega čime se on proslavio.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (49, 13, 18, 'Govoraše dakle: \"Čemu je slično kraljevstvo Božje? Čemu da ga prispodobim?');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (49, 13, 19, 'Ono je kao kad čovjek uze gorušičino zrno i baci ga u svoj vrt. Uzraste i razvi se u stablo te mu se ptice nebeske gnijezde po granama.\"');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (49, 13, 20, 'I opet im reče: \"Čemu da prispodobim kraljevstvo Božje?');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (49, 13, 21, 'Ono je kao kad žena uze kvasac i zamijesi ga u tri mjere brašna dok sve ne uskisne.\"');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (49, 13, 22, 'Putujući tako u Jeruzalem, prolazio je i naučavao gradovima i selima.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (49, 13, 23, 'Reče mu tada netko: \"Gospodine, je li malo onih koji se spasavaju?\" A on im reče:');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (49, 13, 24, '\"Borite se da uđete na uska vrata jer mnogi će, velim vam, tražiti da uđu, ali neće moći.\"');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (49, 13, 25, '\"Kada gospodar kuće ustane i zaključa vrata, a vi stojeći vani počnete kucati na vrata: \'Gospodine, otvori nam!\', on će vam odgovoriti: \'Ne znam vas odakle ste!\'');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (49, 13, 26, 'Tada ćete početi govoriti: \'Pa mi smo s tobom jeli i pili, po našim si trgovima naučavao!\'');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (49, 13, 27, 'A on će vam reći: \'Kažem vam: ne znam odakle ste. Odstupite od mene, svi zlotvori!\'\"');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (49, 13, 28, '\"Ondje će biti plač i škrgut zubi kad ugledate Abrahama i Izaka i Jakova i sve proroke u kraljevstvu Božjem, a sebe vani, izbačene.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (49, 13, 29, 'I doći će s istoka i zapada, sa sjevera i juga i sjesti za stol u kraljevstvu Božjem.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (49, 13, 30, 'Evo, ima posljednjih koji će biti prvi, ima i prvih koji će biti posljednji.\"');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (49, 13, 31, 'U taj čas pristupe neki farizeji i reknu mu: \"Otiđi, otputuj odavde jer te Herod hoće ubiti.\"');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (49, 13, 32, 'A on će njima: \"Idite i kažite toj lisici: \'Evo, izgonim đavle i liječim danas i sutra, a treći dan dovršujem.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (49, 13, 33, 'Ali danas, sutra i prekosutra moram nastaviti put jer ne priliči da prorok pogine izvan Jeruzalema.\'\"');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (49, 13, 34, '\"Jeruzaleme, Jeruzaleme, koji ubijaš proroke i kamenuješ one što su tebi poslani! Koliko li puta htjedoh skupiti djecu tvoju kao kvočka piliće pod krila i ne htjedoste!');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (49, 13, 35, 'Evo, napuštena vam kuća. A kažem vam, nećete me vidjeti dok ne dođe čas te reknete: \"Blagoslovljen Onaj koji dolazi u ime Gospodnje!\"');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (49, 14, 1, 'Jedne subote dođe on u kuću nekoga prvaka farizejskog na objed. A oni ga vrebahu.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (49, 14, 2, 'Kad evo: pred njim neki čovjek koji je imao vodenu bolest.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (49, 14, 3, 'Nato Isus upita zakonoznance i farizeje: \"Je li dopušteno subotom liječiti ili nije?\"');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (49, 14, 4, 'A oni mukom ponikoše. On ga dotaknu, izliječi i otpusti.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (49, 14, 5, 'A njima reče: \"Ako komu od vas sin ili vol padne u bunar, neće li ga brže bolje izvući i u dan subotni?\"');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (49, 14, 6, 'I ne mogoše mu na to odgovoriti.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (49, 14, 7, 'Promatrajući kako uzvanici biraju prva mjesta, kaza im prispodobu:');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (49, 14, 8, '\"Kada te tko pozove na svadbu, ne sjedaj na prvo mjesto da ne bi možda bio pozvan koji časniji od tebe,');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (49, 14, 9, 'te ne dođe onaj koji je pozvao tebe i njega i ne rekne ti: \'Ustupi mjesto ovome.\' Tada ćeš, postiđen, morati zauzeti posljednje mjesto.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (49, 14, 10, 'Nego kad budeš pozvan, idi i sjedni na posljednje mjesto pa, kada dođe onaj koji te pozvao, da ti rekne: \'Prijatelju, pomakni se naviše!\' Bit će ti to tada na čast pred svim sustolnicima,');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (49, 14, 11, 'jer - svaki koji se uzvisuje, bit će ponižen, a koji se ponizuje, bit će uzvišen.\"');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (49, 14, 12, 'A i onome koji ga pozva, kaza: \"Kad priređuješ objed ili večeru, ne pozivaj svojih prijatelja, ni braće, ni rodbine, ni bogatih susjeda, da ne bi možda i oni tebe pozvali i tako ti uzvratili.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (49, 14, 13, 'Nego kad priređuješ gozbu, pozovi siromahe, sakate, hrome, slijepe.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (49, 14, 14, 'Blago tebi jer oni ti nemaju čime uzvratiti. Uzvratit će ti se doista o uskrsnuću pravednih.\"');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (49, 14, 15, 'Kad je to čuo jedan od sustolnika, reče mu: \"Blago onome koji bude blagovao u kraljevstvu Božjem!\"');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (49, 14, 16, 'A on mu reče: \"Čovjek neki priredi veliku večeru i pozva mnoge.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (49, 14, 17, 'I posla slugu u vrijeme večere da rekne uzvanicima: \'Dođite! Već je pripravljeno!\'');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (49, 14, 18, 'A oni se odreda počeli ispričavati. Prvi mu reče: \'Njivu sam kupio i valja mi poći pogledati je. Molim te, ispričaj me.\'');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (49, 14, 19, 'Drugi reče: \'Kupio sam pet jarmova volova pa idem okušati ih. Molim te, ispričaj me.\'');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (49, 14, 20, 'Treći reče: \'Oženio sam se i zato ne mogu doći.\'\"');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (49, 14, 21, '\"Sluga se vrati i javi to domaćinu. Tada domaćin, gnjevan, reče sluzi: \'Iziđi brzo na trgove gradske i ulice pa dovedi ovamo prosjake, sakate, slijepe i hrome.\'');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (49, 14, 22, 'I sluga reče: \'Gospodaru, učinjeno je što si naredio i još ima mjesta.\'');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (49, 14, 23, 'Reče gospodar sluzi: \'Iziđi na putove i među ograde i prisili neka uđu da mi se napuni kuća.\'');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (49, 14, 24, 'A kažem vam: nijedan od onih pozvanih neće okusiti moje večere.\"');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (49, 14, 25, 'S njim je zajedno putovalo silno mnoštvo. On se okrene i reče im:');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (49, 14, 26, '\"Dođe li tko k meni, a ne mrzi svog oca i majku, ženu i djecu, braću i sestre, pa i sam svoj život, ne može biti moj učenik!');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (49, 14, 27, 'I tko ne nosi svoga križa i ne ide za mnom, ne može biti moj učenik!\"');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (49, 14, 28, '\"Tko od vas, nakan graditi kulu, neće prije sjesti i proračunati troškove ima li čime dovršiti:');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (49, 14, 29, 'da ga ne bi - pošto već postavi temelj, a ne mogne dovršiti - počeli ismjehivati svi koji to vide:');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (49, 14, 30, '\'Ovaj čovjek poče graditi, a ne može dovršiti!\'');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (49, 14, 31, 'Ili koji kralj kad polazi da se zarati s drugim kraljem, neće prije sjesti i promisliti da li s deset tisuća može presresti onoga koji na nj dolazi s dvadeset tisuća?');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (49, 14, 32, 'Ako ne može, dok je onaj još daleko, poslat će poslanstvo da zaište mir.\"');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (49, 14, 33, '\"Tako dakle nijedan od vas koji se ne odrekne svega što posjeduje, ne može biti moj učenik.\"');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (49, 14, 34, '\"Dobra je sol. Ali ako i sol obljutavi, čime će se ona začiniti?');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (49, 14, 35, 'Nije prikladna ni za zemlju ni za gnojište. Van se baca. Tko ima uši da čuje, neka čuje!\"');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (49, 15, 1, 'Okupljahu se oko njega svi carinici i grešnici da ga slušaju.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (49, 15, 2, 'Stoga farizeji i pismoznanci mrmljahu: \"Ovaj prima grešnike, i blaguje s njima.\"');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (49, 15, 3, 'Nato im Isus kaza ovu prispodobu:');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (49, 15, 4, '\"Tko to od vas, ako ima sto ovaca pa izgubi jednu od njih, ne ostavi onih devedeset i devet u pustinji te pođe za izgubljenom dok je ne nađe?');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (49, 15, 5, 'A kad je nađe, stavi je na ramena sav radostan');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (49, 15, 6, 'pa došavši kući, sazove prijatelje i susjede i rekne im: \'Radujte se sa mnom! Nađoh ovcu svoju izgubljenu.\'');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (49, 15, 7, 'Kažem vam, tako će na nebu biti veća radost zbog jednog obraćena grešnika nego li zbog devedeset i devet pravednika kojima ne treba obraćenja.\"');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (49, 15, 8, '\"Ili koja to žena, ima li deset drahma pa izgubi jednu drahmu, ne zapali svjetiljku, pomete kuću i brižljivo pretraži dok je ne nađe?');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (49, 15, 9, 'A kad je nađe, pozove prijateljice i susjede pa će im: \'Radujte se sa mnom! Nađoh drahmu što je bijah izgubila.\'');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (49, 15, 10, 'Tako, kažem vam, biva radost pred anđelima Božjim zbog jednog obraćena grešnika.\"');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (49, 15, 11, 'I nastavi: \"Čovjek neki imao dva sina.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (49, 15, 12, 'Mlađi reče ocu: \'Oče, daj mi dio dobara koji mi pripada.\' I razdijeli im imanje.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (49, 15, 13, 'Nakon nekoliko dana mlađi sin pokupi sve, otputova u daleku zemlju i ondje potrati svoja dobra živeći razvratno.\"');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (49, 15, 14, '\"Kad sve potroši, nasta ljuta glad u onoj zemlji te on poče oskudijevati.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (49, 15, 15, 'Ode i pribi se kod jednoga žitelja u onoj zemlji. On ga posla na svoja polja pasti svinje.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (49, 15, 16, 'Želio se nasititi rogačima što su ih jele svinje, ali mu ih nitko nije davao.\"');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (49, 15, 17, '\"Došavši k sebi, reče: \'Koliki najamnici oca moga imaju kruha napretek, a ja ovdje umirem od gladi!');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (49, 15, 18, 'Ustat ću, poći svomu ocu i reći mu: \'Oče, sagriješih protiv Neba i pred tobom!');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (49, 15, 19, 'Nisam više dostojan zvati se sinom tvojim. Primi me kao jednog od svojih najamnika.\'\"');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (49, 15, 20, '\"Usta i pođe svom ocu. Dok je još bio daleko, njegov ga otac ugleda, ganu se, potrča, pade mu oko vrata i izljubi ga.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (49, 15, 21, 'A sin će mu: \'Oče! Sagriješih protiv Neba i pred tobom! Nisam više dostojan zvati se sinom tvojim.\'');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (49, 15, 22, 'A otac reče slugama: \'Brzo iznesite haljinu najljepšu i obucite ga! Stavite mu prsten na ruku i obuću na noge!');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (49, 15, 23, 'Tele ugojeno dovedite i zakoljite, pa da se pogostimo i proveselimo');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (49, 15, 24, 'jer sin mi ovaj bijaše mrtav i oživje, izgubljen bijaše i nađe se!\' I stadoše se veseliti.\"');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (49, 15, 25, '\"A stariji mu sin bijaše u polju. Kad se na povratku približio kući, začu svirku i igru');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (49, 15, 26, 'pa dozva jednoga slugu da se raspita što je to.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (49, 15, 27, 'A ovaj će mu: \'Došao tvoj brat pa otac tvoj zakla tele ugojeno što sina zdrava dočeka.\'');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (49, 15, 28, 'A on se rasrdi i ne htjede ući. Otac tada iziđe i stane ga nagovarati.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (49, 15, 29, 'A on će ocu: \'Evo toliko ti godina služim i nikada ne prestupih tvoju zapovijed, a nikad mi ni jareta nisi dao da se s prijateljima proveselim.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (49, 15, 30, 'A kada dođe ovaj sin tvoj koji s bludnicama proždrije tvoje imanje, ti mu zakla ugojeno tele.\'');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (49, 15, 31, 'Nato će mu otac: \'Sinko, ti si uvijek sa mnom i sve moje - tvoje je.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (49, 15, 32, 'No trebalo se veseliti i radovati jer ovaj brat tvoj bijaše mrtav i oživje, izgubljen i nađe se!\'\"');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (49, 16, 1, 'Govoraše i svojim učenicima: \"Bijaše neki bogat čovjek koji je imao upravitelja.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (49, 16, 2, 'Ovaj je bio optužen pred njim kao da mu rasipa imanje. On ga pozva pa mu reče: \'Što to čujem o tebi? Položi račun o svom upravljanju jer više ne možeš biti upravitelj!\'');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (49, 16, 3, 'Nato upravitelj reče u sebi: \'Što da učinim kad mi gospodar moj oduzima upravu? Kopati? Nemam snage. Prositi? Stidim se.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (49, 16, 4, 'Znam što ću da me prime u svoje kuće kad budem maknut s uprave.\'\"');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (49, 16, 5, '\"I pozva dužnike svoga gospodara, jednog po jednog. Upita prvoga: \'Koliko duguješ gospodaru mojemu?\' On reče: \'Sto bata ulja.\'');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (49, 16, 6, 'A on će mu: \'Uzmi svoju zadužnicu, sjedni brzo, napiši pedeset.\'');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (49, 16, 7, 'Zatim reče drugomu: \'A ti, koliko ti duguješ?\' On odgovori: \'Sto kora pšenice.\' Kaže mu: \'Uzmi svoju zadužnicu i napiši osamdeset.\'\"');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (49, 16, 8, '\"I pohvali gospodar nepoštenog upravitelja što snalažljivo postupi jer sinovi su ovoga svijeta snalažljiviji prema svojima od sinova svjetlosti.\"');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (49, 16, 9, '\"I ja vama kažem: napravite sebi prijatelje od nepoštena bogatstva pa kad ga nestane da vas prime u vječne šatore.\"');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (49, 16, 10, '\"Tko je vjeran u najmanjem, i u najvećem je vjeran; a tko je u najmanjem nepošten, i u najvećem je nepošten.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (49, 16, 11, 'Ako dakle ne bijaste vjerni u nepoštenom bogatstvu, tko li će vam istinsko povjeriti?');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (49, 16, 12, 'I ako u tuđem ne bijaste vjerni, tko li će vam vaše dati?\"');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (49, 16, 13, '\"Nijedan sluga ne može služiti dvojici gospodara. Ili će jednoga mrziti, a drugoga ljubiti; ili će uz jednoga prianjati, a drugoga prezirati. Ne možete služiti Bogu i bogatstvu.\"');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (49, 16, 14, 'Sve su to slušali farizeji, srebroljupci, i rugali mu se.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (49, 16, 15, 'On im reče: \"Vi se pravite pravedni pred ljudima, ali zna Bog srca vaša. Jer što je ljudima uzvišeno, odvratnost je pred Bogom.\"');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (49, 16, 16, '\"Zakon i Proroci do Ivana su, a otada se navješćuje kraljevstvo Božje i svatko se u nj silom probija.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (49, 16, 17, 'Lakše će nebo i zemlja proći, negoli propasti i jedan potezić Zakona.\"');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (49, 16, 18, '\"Tko god otpusti svoju ženu pa se oženi drugom, čini preljub. I tko se god oženi otpuštenom, čini preljub.\"');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (49, 16, 19, '\"Bijaše neki bogataš. Odijevao se u grimiz i tanani lan i danomice se sjajno gostio.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (49, 16, 20, 'A neki siromah, imenom Lazar, ležao je sav u čirevima pred njegovim vratima');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (49, 16, 21, 'i priželjkivao nasititi se onim što je padalo s bogataševa stola. Čak su i psi dolazili i lizali mu čireve.\"');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (49, 16, 22, '\"Kad umrije siromah, odnesoše ga anđeli u krilo Abrahamovo. Umrije i bogataš te bude pokopan.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (49, 16, 23, 'Tada u teškim mukama u paklu, podiže svoje oči te izdaleka ugleda Abrahama i u krilu mu Lazara');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (49, 16, 24, 'pa zavapi: \'Oče Abrahame, smiluj mi se i pošalji Lazara da umoči vršak svoga prsta u vodu i rashladi mi jezik jer se strašno mučim u ovom plamenu.\'');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (49, 16, 25, 'Reče nato Abraham: \'Sinko! Sjeti se da si za života primio dobra svoja, a tako i Lazar zla. Sada se on ovdje tješi, a ti se mučiš.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (49, 16, 26, 'K tome između nas i vas zjapi provalija golema te koji bi i htjeli prijeći odavde k vama, ne mogu, a ni odatle k nama prijelaza nema.\'\"');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (49, 16, 27, '\"Nato će bogataš: \'Molim te onda, oče, pošalji Lazara u kuću oca moga.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (49, 16, 28, 'Imam petero braće pa neka im posvjedoči da i oni ne dođu u ovo mjesto muka.\'');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (49, 16, 29, 'Kaže Abraham: \'Imaju Mojsija i Proroke! Njih neka poslušaju!\'');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (49, 16, 30, 'A on će: \'O ne, oče Abrahame! Nego dođe li tko od mrtvih k njima, obratit će se.\'');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (49, 16, 31, 'Reče mu: \'Ako ne slušaju Mojsija i Proroka, neće povjerovati sve da i od mrtvih tko ustane.\'\"');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (49, 17, 1, 'I reče svojim učenicima: \"Nije moguće da ne dođu sablazni, no jao onome po kom dolaze;');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (49, 17, 2, 'je li s mlinskim kamenom o vratu strovaljen u more, korisnije mu je, nego da sablazni jednoga od ovih malenih.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (49, 17, 3, 'Čuvajte se!\" \"Pogriješi li tvoj brat, prekori ga; ako se obrati, oprosti mu.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (49, 17, 4, 'Pa ako se sedam puta na dan ogriješi o tebe i sedam se puta obrati tebi govoreći: \'Žao mi je!\', oprosti mu.\"');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (49, 17, 5, 'Apostoli zamole Gospodina: \"Umnoži nam vjeru!\"');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (49, 17, 6, 'Gospodin im odvrati: \"Da imate vjere koliko je zrno gorušičino, rekli biste ovom dudu: \'Iščupaj se s korijenom i presadi se u more!\' I on bi vas poslušao.\"');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (49, 17, 7, '\"Tko će to od vas reći sluzi svomu, oraču ili pastiru, koji se vrati s polja: \'Dođi brzo i sjedni za stol?\'');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (49, 17, 8, 'Neće li mu naprotiv reći: \'Pripravi što ću večerati pa se pripaši i poslužuj mi dok jedem i pijem; potom ćeš ti jesti i piti?\'');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (49, 17, 9, 'Zar duguje zahvalnost sluzi jer je izvršio što mu je naređeno?');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (49, 17, 10, 'Tako i vi: kad izvršite sve što vam je naređeno, recite: \'Sluge smo beskorisne! Učinismo što smo bili dužni učiniti!\'\"');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (49, 17, 11, 'Dok je tako putovao u Jeruzalem, prolazio je između Samarije i Galileje.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (49, 17, 12, 'Kad je ulazio u neko selo, eto mu u susret deset gubavaca. Zaustave se podaleko');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (49, 17, 13, 'i zavape: \"Isuse, Učitelju, smiluj nam se!\"');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (49, 17, 14, 'Kad ih Isus ugleda, reče im: \"Idite, pokažite se svećenicima!\" I dok su išli, očistiše se.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (49, 17, 15, 'Jedan od njih vidjevši da je ozdravio, vrati se slaveći Boga u sav glas.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (49, 17, 16, 'Baci se ničice k Isusovim nogama zahvaljujući mu. A to bijaše neki Samarijanac.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (49, 17, 17, 'Nato Isus primijeti: \"Zar se ne očistiše desetorica?');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (49, 17, 18, 'A gdje su ona devetorica? Ne nađe li se nijedan koji bi se vratio i podao slavu Bogu, osim ovoga tuđinca?\"');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (49, 17, 19, 'A njemu reče: \"Ustani! Idi! Tvoja te vjera spasila!\"');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (49, 17, 20, 'Upitaju ga farizeji: \"Kad će doći kraljevstvo Božje?\" Odgovori im: \"Kraljevstvo Božje ne dolazi primjetljivo.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (49, 17, 21, 'Niti će se moći kazati: \'Evo ga ovdje!\' ili: \'Eno ga ondje!\' Ta evo - kraljevstvo je Božje među vama!\"');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (49, 17, 22, 'Zatim reče učenicima: \"Doći će dani kad ćete zaželjeti vidjeti i jedan dan Sina Čovječjega, ali ga nećete vidjeti.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (49, 17, 23, 'Govorit će vam: \'Eno ga ondje, evo ovdje!\' Ne odlazite i ne pomamite se!');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (49, 17, 24, 'Jer kao što munja sijevne na jednom kraju obzorja i odbljesne na drugom, tako će biti i sa Sinom Čovječjim u Dan njegov.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (49, 17, 25, 'No prije treba da on mnogo pretrpi i da ga ovaj naraštaj odbaci.\"');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (49, 17, 26, '\"I kao što bijaše u dane Noine, tako će biti i u dane Sina Čovječjega:');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (49, 17, 27, 'jeli su, pili, ženili se i udavali do dana kad Noa uđe u korablju. I dođe potop i sve uništi.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (49, 17, 28, 'Slično kao što bijaše u dane Lotove: jeli su, pili, kupovali, prodavali, sadili, gradili.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (49, 17, 29, 'A onog dana kad Lot iziđe iz Sodome, zapljušti s neba oganj i sumpor i sve uništi.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (49, 17, 30, 'Tako će isto biti u dan kad se Sin Čovječji objavi.\"');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (49, 17, 31, '\"U onaj dan tko bude na krovu, a stvari mu u kući, neka ne siđe da ih uzme.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (49, 17, 32, 'I tko bude u polju, neka se ne okreće natrag. Sjetite se žene Lotove!');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (49, 17, 33, 'Tko god bude nastojao život svoj sačuvati, izgubit će ga; a tko ga izgubi, živa će ga sačuvati.\"');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (49, 17, 34, '\"Kažem vam, one će noći biti dvojica u jednoj postelji: jedan će se uzeti, drugi ostaviti.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (49, 17, 35, 'Dvije će mljeti zajedno: jedna će se uzeti, druga ostaviti.\"');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (49, 17, 36, '#');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (49, 17, 37, 'Upitaše ga na to: \"Gdje to, Gospodine?\" A on im reče: \"Gdje bude trupla, ondje će se okupljati i orlovi.\"');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (49, 18, 1, 'Kaza im i prispodobu kako valja svagda moliti i nikada ne sustati:');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (49, 18, 2, '\"U nekom gradu bio sudac. Boga se nije bojao, za ljude nije mario.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (49, 18, 3, 'U tom gradu bijaše i neka udovica. Dolazila k njemu i molila: \'Obrani me od mog tužitelja!\'');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (49, 18, 4, 'No on ne htjede zadugo. Napokon reče u sebi: \'Iako se Boga ne bojim nit za ljude marim, ipak,');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (49, 18, 5, 'jer mi udovica ova dodijava, obranit ću je da vječno ne dolazi mučiti me.\'\"');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (49, 18, 6, 'Nato reče Gospodin: \"Čujte što govori nepravedni sudac!');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (49, 18, 7, 'Neće li onda Bog obraniti svoje izabrane koji dan i noć vape k njemu sve ako i odgađa stvar njihovu?');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (49, 18, 8, 'Kažem vam, ustat će žurno na njihovu obranu. Ali kad Sin Čovječji dođe, hoće li naći vjere na zemlji?\"');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (49, 18, 9, 'Nekima pak koji se pouzdavahu u sebe da su pravednici, a druge potcjenjivahu, reče zatim ovu prispodobu:');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (49, 18, 10, '\"Dva čovjeka uziđoše u Hram pomoliti se: jedan farizej, drugi carinik.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (49, 18, 11, 'Farizej se uspravan ovako u sebi molio: \'Bože, hvala ti što nisam kao ostali ljudi: grabežljivci, nepravednici, preljubnici ili - kao ovaj carinik.\'');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (49, 18, 12, 'Postim dvaput u tjednu, dajem desetinu od svega što steknem.\'');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (49, 18, 13, 'A carinik, stojeći izdaleka, ne usudi se ni očiju podignuti k nebu, nego se udaraše u prsa govoreći: \'Bože milostiv budi meni grešniku!\'');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (49, 18, 14, 'Kažem vam: ovaj siđe opravdan kući svojoj, a ne onaj! Svaki koji se uzvisuje, bit će ponižen; a koji se ponizuje, bit će uzvišen.\"');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (49, 18, 15, 'A donosili mu i dojenčad da ih se dotakne. Vidjevši to, učenici im branili.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (49, 18, 16, 'A Isus ih dozva i reče: \"Pustite dječicu neka dolaze k meni i ne priječite im jer takvih je kraljevstvo Božje.\"');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (49, 18, 17, '\"Zaista, kažem vam, tko ne primi kraljevstva Božjega kao dijete, ne, u nj neće ući.\"');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (49, 18, 18, 'I upita ga neki uglednik: \"Učitelju dobri, što mi je činiti da baštinim život vječni?\"');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (49, 18, 19, 'Reče mu Isus: \"Što me zoveš dobrim? Nitko nije dobar, doli Bog jedini.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (49, 18, 20, 'Zapovijedi znaš: Ne čini preljuba! Ne ubij! Ne ukradi! Ne svjedoči lažno! Poštuj oca svoga i majku!\"');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (49, 18, 21, 'A onaj će: \"Sve sam to čuvao od mladosti.\"');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (49, 18, 22, 'Čuvši to, Isus mu reče: \"Još ti jedno preostaje: sve što imaš prodaj i razdaj siromasima pa ćeš imati blago na nebu. A onda dođi i idi za mnom.\"');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (49, 18, 23, 'Kad je on to čuo, ražalosti se jer bijaše silno bogat.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (49, 18, 24, 'Vidjevši ga, reče Isus: \"Kako li je teško imućnicima u kraljevstvo Božje!');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (49, 18, 25, 'Lakše je devi kroz uši iglene nego bogatašu u kraljevstvo Božje.\"');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (49, 18, 26, 'Koji su to čuli, rekoše: \"Pa tko se onda može spasiti?\"');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (49, 18, 27, 'A on će: \"Što je nemoguće ljudima, moguće je Bogu.\"');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (49, 18, 28, 'Nato reče Petar: \"Evo, mi ostavismo svoje i pođosmo za tobom.\"');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (49, 18, 29, 'Isus će im: \"Zaista, kažem vam, nema ga tko bi ostavio kuću, ili ženu, ili braću, ili roditelje, ili djecu poradi kraljevstva Božjega,');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (49, 18, 30, 'a da ne bi primio mnogostruko već u ovom vremenu, i u budućem vijeku život vječni.\"');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (49, 18, 31, 'I uzevši sa sobom dvanaestoricu, reče im: \"Evo uzlazimo u Jeruzalem i na Sinu Čovječjem ispunit će se sve što su napisali proroci:');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (49, 18, 32, 'doista, bit će predan poganima, izrugan, zlostavljan i popljuvan;');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (49, 18, 33, 'i pošto ga izbičuju, ubit će ga, ali on će treći dan ustati.\"');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (49, 18, 34, 'No oni ništa od toga ne razumješe. Te im riječi bijahu skrivene i ne shvaćahu što bijaše rečeno.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (49, 18, 35, 'A kad se približavao Jerihonu, neki slijepac sjedio kraj puta i prosio.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (49, 18, 36, 'Čuvši gdje mnoštvo prolazi, raspitivao se što je to.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (49, 18, 37, 'Rekoše mu: \"Isus Nazarećanin prolazi.\"');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (49, 18, 38, 'Tada povika: \"Isuse, Sine Davidov, smiluj mi se!\"');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (49, 18, 39, 'Oni ga sprijeda ušutkivali, ali on je još jače vikao: \"Sine Davidov, smiluj mi se!\"');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (49, 18, 40, 'Isus se zaustavi i zapovjedi da ga dovedu k njemu. Kad se on približi, upita ga:');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (49, 18, 41, '\"Što hoćeš da ti učinim?\" A on će: \"Gospodine, da progledam.\"');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (49, 18, 42, 'Isus će mu: \"Progledaj! Vjera te tvoja spasila.\"');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (49, 18, 43, 'I umah progleda i uputi se za njim slaveći Boga. I sav narod koji to vidje dade hvalu Bogu.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (49, 19, 1, 'I uđe u Jerihon. Dok je njime prolazio,');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (49, 19, 2, 'eto čovjeka imenom Zakej. Bijaše on nadcarinik, i to bogat.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (49, 19, 3, 'Želio je vidjeti tko je to Isus, ali ne mogaše od mnoštva jer je bio niska stasa.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (49, 19, 4, 'Potrča naprijed, pope se na smokvu da ga vidi jer je onuda imao proći.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (49, 19, 5, 'Kad Isus dođe na to mjesto, pogleda gore i reče mu: \"Zakeju, žurno siđi! Danas mi je proboraviti u tvojoj kući.\"');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (49, 19, 6, 'On žurno siđe i primi ga sav radostan.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (49, 19, 7, 'A svi koji to vidješe stadoše mrmljati: \"Čovjeku se grešniku svratio!\"');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (49, 19, 8, 'A Zakej usta i reče Gospodinu: \"Evo, Gospodine, polovicu svog imanja dajem siromasima! I ako sam koga u čemu prevario, vraćam četverostruko.\"');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (49, 19, 9, 'Reče mu na to Isus: \"Danas je došlo spasenje ovoj kući jer i on je sin Abrahamov!');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (49, 19, 10, 'Ta Sin Čovječji dođe potražiti i spasiti izgubljeno!\"');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (49, 19, 11, 'Kako su oni to slušali, dometnu on prispodobu - zato što bijaše nadomak Jeruzalemu i oni mislili da će se umah pojaviti kraljevstvo Božje.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (49, 19, 12, 'Reče dakle: \"Neki je ugledan čovjek imao otputovati u daleku zemlju da primi svoje kraljevstvo pa da se vrati.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (49, 19, 13, 'Dozva svojih deset slugu, dade im deset mna i reče: \'Trgujte dok ne dođem.\'');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (49, 19, 14, 'A njegovi ga građani mrzili te poslaše za njim poslanstvo s porukom: \'Nećemo da se ovaj zakralji nad nama.\'\"');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (49, 19, 15, '\"Kad je on primio kraljevstvo i vratio se, naredi da mu dozovu one sluge kojima je predao novac da sazna što su zaradili.\"');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (49, 19, 16, '\"Pristupi prvi i reče: \'Gospodaru, tvoja mna donije deset mna.\'');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (49, 19, 17, 'Reče mu: \'Valjaš, slugo dobri! U najmanjem si bio vjeran, vladaj nad deset gradova!\'');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (49, 19, 18, 'Dođe i drugi govoreći: \'Mna je tvoja, gospodaru, donijela pet mna.\'');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (49, 19, 19, 'I tomu reče: \'I ti budi nad pet gradova!\'\"');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (49, 19, 20, '\"Treći, opet dođe govoreći: \'Gospodaru, evo ti tvoje mne. Držao sam je pohranjenu u rupcu.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (49, 19, 21, 'Bojao sam te se jer si čovjek strog: uzimaš što nisi pohranio, žanješ što nisi posijao.\'\"');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (49, 19, 22, '\"Kaže mu: \'Iz tvojih te usta sudim, zli slugo! Znao si da sam čovjek strog, da uzimam što nisam pohranio i žanjem što nisam posijao?');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (49, 19, 23, 'Zašto onda nisi uložio moj novac u novčarnicu? Ja bih ga po povratku podigao s dobitkom.\'');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (49, 19, 24, 'Nato reče nazočnima: \'Uzmite od njega mnu i dajte onomu koji ih ima deset.\'');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (49, 19, 25, 'Rekoše mu: \'Gospodaru, ta već ima deset mna!\'');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (49, 19, 26, 'Kažem vam: svakomu koji ima još će se dati, a od onoga koji nema oduzet će se i ono što ima.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (49, 19, 27, 'A moje neprijatelje - one koji me ne htjedoše za kralja - dovedite ovamo i smaknite ih pred mojim očima!\'\"');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (49, 19, 28, 'Rekavši to, nastavi put uzlazeći u Jeruzalem.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (49, 19, 29, 'Kad se približi Betfagi i Betaniji, uz goru koja se zove Maslinska, posla dvojicu učenika');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (49, 19, 30, 'govoreći: \"Hajdete u selo pred vama. Čim uđete u nj, naći ćete privezano magare koje još nitko nije zajahao. Odriješite ga i dovedite.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (49, 19, 31, 'Upita li vas tko: \'Zašto driješite?\', ovako recite: \'Gospodinu treba.\'\"');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (49, 19, 32, 'Oni koji bijahu poslani otiđoše i nađoše kako im bijaše rekao.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (49, 19, 33, 'I dok su driješili magare, rekoše im gospodari: \"Što driješite magare?\"');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (49, 19, 34, 'Oni odgovore: \"Gospodinu treba.\"');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (49, 19, 35, 'I dovedoše ga Isusu i staviše svoje haljine na magare te posjednuše Isusa.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (49, 19, 36, 'I kuda bi on prolazio, prostirali bi po putu svoje haljine.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (49, 19, 37, 'A kad se već bio približio obronku Maslinske gore, sve ono mnoštvo učenika, puno radosti, poče iza glasa hvaliti Boga za sva silna djela što ih vidješe:');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (49, 19, 38, '\"Blagoslovljen Kralj, Onaj koji dolazi u ime Gospodnje! Na nebu mir! Slava na visinama!\"');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (49, 19, 39, 'Nato mu neki farizeji iz mnoštva rekoše: \"Učitelju, prekori svoje učenike.\"');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (49, 19, 40, 'On odgovori: \"Kažem vam, ako ovi ušute, kamenje će vikati!\"');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (49, 19, 41, 'Kad se približi i ugleda grad, zaplaka nad njim');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (49, 19, 42, 'govoreći: \"O kad bi i ti u ovaj dan spoznao što je za tvoj mir!');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (49, 19, 43, 'Ali sada je sakriveno tvojim očima. Doći će dani na tebe kad će te neprijatelji tvoji opkoliti opkopom, okružit će te i pritijesniti odasvud.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (49, 19, 44, 'Smrskat će o zemlju tebe i djecu tvoju u tebi. I neće ostaviti u tebi ni kamena na kamenu zbog toga što nisi upoznao časa svoga pohođenja.\"');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (49, 19, 45, 'Ušavši u Hram, stane izgoniti prodavače.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (49, 19, 46, 'Kaže im: \"Pisano je: Dom moj bit će Dom molitve, a vi od njega načiniste pećinu razbojničku!\"');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (49, 19, 47, 'I danomice naučavaše u Hramu. A glavari su svećenički i pismoznanci tražili kako da ga pogube, a tako i prvaci narodni,');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (49, 19, 48, 'ali nikako naći što da učine jer je sav narod visio o njegovoj riječi.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (49, 20, 1, 'Jednog dana dok je naučavao narod u Hramu i naviještao evanđelje, ispriječe se glavari svećenički i pismoznanci sa starješinama');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (49, 20, 2, 'pa mu dobace: \"Reci nam kojom vlašću to činiš ili tko ti dade tu vlast?\"');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (49, 20, 3, 'On odgovori: \"Upitat ću i ja vas. Recite mi:');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (49, 20, 4, 'krst Ivanov bijaše li od Neba ili od ljudi?\"');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (49, 20, 5, 'A oni smišljahu među sobom: \"Reknemo li \'od Neba\', odvratit će \'Zašto mu ne povjerovaste?\'');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (49, 20, 6, 'A reknemo li \'od ljudi\', sav će nas narod kamenovati. Ta uvjeren je da je Ivan prorok.\"');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (49, 20, 7, 'I odgovore da ne znaju odakle.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (49, 20, 8, 'I Isus reče njima: \"Ni ja vama neću kazati kojom vlašću ovo činim.\"');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (49, 20, 9, 'Zatim uze narodu kazivati ovu prispodobu: \"Čovjek posadi vinograd, iznajmi ga vinogradarima i otputova na dulje vrijeme.\"');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (49, 20, 10, '\"Kada dođe doba, posla slugu vinogradarima da mu dadnu od uroda vinogradskoga. No vinogradari ga istukoše i otposlaše praznih ruku.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (49, 20, 11, 'Nato on posla drugoga slugu. Ali oni i toga istukoše, izružiše i otposlaše praznih ruku.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (49, 20, 12, 'Posla i trećega. A oni i njega izraniše i izbaciše.\"');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (49, 20, 13, '\"Nato reče gospodar vinograda: \'Što da učinim? Poslat ću im sina svoga ljubljenoga. Njega će valjda poštovati.\'');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (49, 20, 14, 'Ali kada ga vinogradari ugledaju, stanu među sobom umovati: \'Ovo je baštinik. Ubijmo ga da baština bude naša.\'');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (49, 20, 15, 'Izbaciše ga iz vinograda i ubiše.\" \"Što će dakle učiniti s njima gospodar vinograda?');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (49, 20, 16, 'Doći će i pogubiti te vinogradare i dati vinograd drugima.\" Koji ga slušahu rekoše: \"Bože sačuvaj!\"');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (49, 20, 17, 'A on ih ošinu pogledom i reče: \"A što ono piše: Kamen što ga odbaciše graditelji postade kamen zaglavni?');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (49, 20, 18, 'Tko god padne na taj kamen, smrskat će se, a na koga on padne, satrt će ga.\"');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (49, 20, 19, 'Pismoznanci i glavari svećenički gledahu da istog časa stave ruke na nj, ali se pobojaše naroda. Dobro razumješe da o njima kaza tu prispodobu.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (49, 20, 20, 'Vrebajući na nj, poslaše uhode koji su se pravili pravednicima da ga uhvate u riječi pa da ga predaju oblasti i vlasti upraviteljevoj.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (49, 20, 21, 'Upitaše ga dakle: \"Učitelju, znamo da pravo zboriš i naučavaš te nisi pristran, nego po istini učiš putu Božjem.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (49, 20, 22, 'Je li nam dopušteno dati porez caru ili nije?\"');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (49, 20, 23, 'Proničući njihovu lukavost, reče im:');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (49, 20, 24, '\"Pokažite mi denar.\" \"Čiju ima sliku i natpis?\"');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (49, 20, 25, 'A oni će: \"Carevu.\" On im reče: \"Stoga dajte caru carevo, a Bogu Božje.\"');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (49, 20, 26, 'I ne mogoše ga uhvatiti u riječi pred narodom, nego umuknuše zadivljeni njegovim odgovorom.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (49, 20, 27, 'Pristupe mu neki od saduceja, koji niječu uskrsnuće. Upitaše ga:');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (49, 20, 28, '\"Učitelju! Mojsije nam napisa: Umre li bez djece čiji brat koji imaše ženu, neka njegov brat uzme tu ženu te podigne porod bratu svomu.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (49, 20, 29, 'Bijaše tako sedmero braće. Prvi se oženi i umrije bez djece.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (49, 20, 30, 'Drugi uze njegovu ženu,');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (49, 20, 31, 'onda treći; i tako redom sva sedmorica pomriješe ne ostavivši djece.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (49, 20, 32, 'Naposljetku umrije i žena.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (49, 20, 33, 'Kojemu će dakle od njih ta žena pripasti o uskrsnuću? Jer sedmorica su je imala za ženu.\"');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (49, 20, 34, 'Reče im Isus: \"Djeca se ovog svijeta žene i udaju.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (49, 20, 35, 'No oni koji se nađoše dostojni onog svijeta i uskrsnuća od mrtvih niti se žene niti udaju.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (49, 20, 36, 'Zaista, ni umrijeti više ne mogu: anđelima su jednaki i sinovi su Božji jer su sinovi uskrsnuća.\"');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (49, 20, 37, '\"A da mrtvi ustaju, naznači i Mojsije kad u odlomku o grmu Gospodina zove Bogom Abrahamovim, Bogom Izakovim i Bogom Jakovljevim.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (49, 20, 38, 'A nije on Bog mrtvih, nego živih. Ta svi njemu žive!\"');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (49, 20, 39, 'Neki pismoznanci primijete: \"Učitelju! Dobro si rekao!\"');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (49, 20, 40, 'I nisu se više usuđivali upitati ga bilo što.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (49, 20, 41, 'A on im reče: \"Kako kažu da je Krist sin Davidov?');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (49, 20, 42, 'Ta sam David veli u Knjizi psalama: Reče Gospod Gospodinu mojemu: \'Sjedi mi zdesna');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (49, 20, 43, 'dok ne položim neprijatelje tvoje za podnožje nogama tvojim!\'');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (49, 20, 44, 'David ga dakle naziva Gospodinom. Kako mu je onda sin?\"');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (49, 20, 45, 'I pred svim narodom reče svojim učenicima:');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (49, 20, 46, '\"Čuvajte se pismoznanaca, koji rado hodaju u dugim haljinama, vole pozdrave na trgovima, prva sjedala u sinagogama i pročelja na gozbama,');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (49, 20, 47, 'proždiru kuće udovičke, još pod izlikom dugih molitava. Stići će ih to oštrija osuda.\"');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (49, 21, 1, 'Pogleda i vidje kako bogataši bacaju u riznicu svoje darove.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (49, 21, 2, 'A ugleda i neku ubogu udovicu kako baca onamo dva novčića.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (49, 21, 3, 'I reče: \"Uistinu, kažem vam: ova je sirota udovica ubacila više od sviju.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (49, 21, 4, 'Svi su oni zapravo među darove ubacili od svog suviška, a ona je od svoje sirotinje ubacila sav žitak što ga imaše.\"');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (49, 21, 5, 'I dok su neki razgovarali o Hramu, kako ga resi divno kamenje i zavjetni darovi, reče:');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (49, 21, 6, '\"Doći će dani u kojima se od ovoga što motrite neće ostaviti ni kamen na kamenu nerazvaljen.\"');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (49, 21, 7, 'Upitaše ga: \"Učitelju, a kada će to biti? I na koji se znak to ima dogoditi?\"');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (49, 21, 8, 'A on reče: \"Pazite, ne dajte se zavesti. Mnogi će doista doći u moje ime i govoriti: \'Ja sam\' i: \'Vrijeme se približilo!\' Ne idite za njima.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (49, 21, 9, 'A kad čujete za ratove i pobune, ne prestrašite se. Doista treba da se to prije dogodi, ali to još nije odmah svršetak.\"');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (49, 21, 10, 'Tada im kaza: \"Narod će ustati protiv naroda i kraljevstvo protiv kraljevstva.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (49, 21, 11, 'I bit će velikih potresa i po raznim mjestima gladi i pošasti; bit će strahota i velikih znakova s neba.\"');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (49, 21, 12, '\"No prije svega toga podignut će na vas ruke i progoniti vas, predavati vas u sinagoge i tamnice. Vući će vas pred kraljeve i upravitelje zbog imena mojega.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (49, 21, 13, 'Zadesit će vas to radi svjedočenja.\"');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (49, 21, 14, '\"Stoga uzmite k srcu: nemojte unaprijed smišljati obranu!');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (49, 21, 15, 'Ta ja ću vam dati usta i mudrost kojoj se neće moći suprotstaviti niti oduprijeti nijedan vaš protivnik.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (49, 21, 16, 'A predavat će vas čak i vaši roditelji i braća, rođaci i prijatelji. Neke će od vas i ubiti.\"');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (49, 21, 17, '\"Svi će vas zamrziti zbog imena mojega.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (49, 21, 18, 'Ali ni vlas vam s glave neće propasti.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (49, 21, 19, 'Svojom ćete se postojanošću spasiti.\"');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (49, 21, 20, '\"Kad ugledate da vojska opkoljuje Jeruzalem, tada znajte: približilo se njegovo opustošenje.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (49, 21, 21, 'Koji se tada zateknu u Judeji, neka bježe u gore; a koji u Gradu, neka ga napuste; koji pak po poljima, neka se u nj ne vraćaju');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (49, 21, 22, 'jer to su dani odmazde, da se ispuni sve što je pisano.\"');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (49, 21, 23, '\"Jao trudnicama i dojiljama u one dane jer bit će jad velik na zemlji i gnjev nad ovim narodom.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (49, 21, 24, 'Padat će od oštrice mača, odvodit će ih kao roblje po svim narodima. I Jeruzalem će gaziti pogani sve dok se ne navrše vremena pogana.\"');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (49, 21, 25, '\"I bit će znaci na suncu, mjesecu i zvijezdama, a na zemlji bezizlazna tjeskoba naroda zbog huke mora i valovlja.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (49, 21, 26, 'Izdisat će ljudi od straha i iščekivanja onoga što prijeti svijetu. Doista, sile će se nebeske poljuljati.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (49, 21, 27, 'Tada će ugledati Sina Čovječjega gdje dolazi u oblaku s velikom moći i slavom.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (49, 21, 28, 'Kad se sve to stane zbivati, uspravite se i podignite glave jer se približuje vaše otkupljenje.\"');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (49, 21, 29, 'I reče im prispodobu: \"Pogledajte smokvu i sva stabla.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (49, 21, 30, 'Kad već propupaju, i sami vidite i znate: blizu je već ljeto.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (49, 21, 31, 'Tako i vi kad vidite da se to zbiva, znajte: blizu je kraljevstvo Božje.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (49, 21, 32, 'Zaista, kažem vam, ne, neće uminuti naraštaj ovaj dok se sve ne zbude.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (49, 21, 33, 'Nebo će i zemlja uminuti, ali moje riječi ne, neće uminuti.\"');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (49, 21, 34, '\"Pazite na se da vam srca ne otežaju u proždrljivosti, pijanstvu i u životnim brigama te vas iznenada ne zatekne onaj Dan');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (49, 21, 35, 'jer će kao zamka nadoći na sve žitelje po svoj zemlji.\"');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (49, 21, 36, '\"Stoga budni budite i u svako doba molite da uzmognete umaći svemu tomu što se ima zbiti i stati pred Sina Čovječjega.\"');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (49, 21, 37, 'Danju je učio u Hramu, a noću bi izlazio i noćio na gori zvanoj Maslinska.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (49, 21, 38, 'A sav bi narod rano hrlio k njemu u Hram da ga sluša.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (49, 22, 1, 'Bližio se Blagdan beskvasnih kruhova zvan Pasha.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (49, 22, 2, 'Glavari svećenički i pismoznanci tražili su kako da Isusa smaknu jer se bojahu naroda.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (49, 22, 3, 'A Sotona uđe u Judu zvanog Iškariotski koji bijaše iz broja dvanaestorice.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (49, 22, 4, 'On ode i ugovori s glavarima svećeničkim i zapovjednicima kako da im ga preda.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (49, 22, 5, 'Oni se povesele i ugovore da će mu dati novca.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (49, 22, 6, 'On pristade. Otada je tražio priliku da im ga preda mimo naroda.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (49, 22, 7, 'Kada dođe Dan beskvasnih kruhova, u koji je trebalo žrtvovati pashu,');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (49, 22, 8, 'posla Isus Petra i Ivana i reče: \"Hajdete, pripravite nam da blagujemo pashu.\"');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (49, 22, 9, 'Rekoše mu: \"Gdje hoćeš da pripravimo?\"');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (49, 22, 10, 'On im reče: \"Evo, čim uđete u grad, namjerit ćete se na čovjeka koji nosi krčag vode. Pođite za njim u kuću u koju uniđe');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (49, 22, 11, 'i recite domaćinu te kuće: \'Učitelj veli: Gdje je svratište u kojem bih blagovao pashu sa svojim učenicima?\'');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (49, 22, 12, 'I on će vam pokazati na katu veliko blagovalište prostrto: ondje pripravite.\"');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (49, 22, 13, 'Oni odu, nađu kako im je rekao i priprave pashu.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (49, 22, 14, 'Kada dođe čas, sjede Isus za stol i apostoli s njim.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (49, 22, 15, 'I reče im: \"Svom sam dušom čeznuo ovu pashu blagovati s vama prije svoje muke.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (49, 22, 16, 'Jer kažem vam, neću je više blagovati dok se ona ne završi u kraljevstvu Božjem.\"');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (49, 22, 17, 'I uze čašu, zahvali i reče: \"Uzmite je i razdijelite među sobom.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (49, 22, 18, 'Jer kažem vam, ne, neću više piti od roda trsova dok kraljevstvo Božje ne dođe.\"');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (49, 22, 19, 'I uze kruh, zahvali, razlomi i dade im govoreći: \"Ovo je tijelo moje koje se za vas predaje. Ovo činite meni na spomen.\"');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (49, 22, 20, 'Tako i čašu, pošto večeraše, govoreći: \"Ova čaša novi je Savez u mojoj krvi koja se za vas prolijeva.\"');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (49, 22, 21, '\"A evo, ruka mog izdajice sa mnom je na stolu.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (49, 22, 22, 'Sin Čovječji, istina, ide kako je određeno, ali jao čovjeku onomu koji ga predaje.\"');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (49, 22, 23, 'I oni se počeše ispitivati tko bi od njih mogao takvo što učiniti.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (49, 22, 24, 'Uto nasta među njima prepirka tko bi od njih bio najveći.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (49, 22, 25, 'A on im reče: \"Kraljevi gospoduju svojim narodima i vlastodršci nazivaju sebe dobrotvorima.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (49, 22, 26, 'Vi nemojte tako! Naprotiv, najveći među vama neka bude kao najmlađi; i predstojnik kao poslužitelj.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (49, 22, 27, 'Ta tko je veći? Koji je za stolom ili koji poslužuje? Zar ne onaj koji je za stolom? A ja sam posred vas kao onaj koji poslužuje.\"');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (49, 22, 28, '\"Da, vi ste sa mnom ustrajali u mojim kušnjama.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (49, 22, 29, 'Ja vam stoga u baštinu predajem kraljevstvo što ga je meni predao moj Otac:');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (49, 22, 30, 'da jedete i pijete za mojim stolom u kraljevstvu mojemu i sjedite na prijestoljima sudeći dvanaest plemena Izraelovih.\"');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (49, 22, 31, '\"Šimune, Šimune, evo Sotona zaiska da vas prorešeta kao pšenicu.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (49, 22, 32, 'Ali ja sam molio za tebe da ne malakše tvoja vjera. Pa kad k sebi dođeš, učvrsti svoju braću.\"');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (49, 22, 33, 'Petar mu reče: \"Gospodine, s tobom sam spreman i u tamnicu i u smrt.\"');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (49, 22, 34, 'A Isus će mu: \"Kažem ti, Petre, neće se danas oglasiti pijetao dok triput ne zatajiš da me poznaš.\"');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (49, 22, 35, 'I reče: \"Kad sam vas poslao bez kese i bez torbe i bez sandala, je li vam što nedostajalo?\" Oni odgovore: \"Ništa.\"');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (49, 22, 36, 'Nato će im: \"No sada tko ima kesu, neka je uzme! Isto tako i torbu! A koji nema, neka proda svoju haljinu i neka kupi sebi mač');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (49, 22, 37, 'jer kažem vam, ono što je napisano treba se ispuniti na meni: Među zlikovce bi ubrojen. Uistinu, sve što se odnosi na mene ispunja se.\"');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (49, 22, 38, 'Oni mu rekoše: \"Gospodine, evo ovdje dva mača!\" Reče im: \"Dosta je!\"');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (49, 22, 39, 'Tada iziđe te se po običaju zaputi na Maslinsku goru. Za njim pođoše i njegovi učenici.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (49, 22, 40, 'Kada dođe onamo, reče im: \"Molite da ne padnete u napast!\"');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (49, 22, 41, 'I otrgnu se od njih koliko bi se kamenom dobacilo, pade na koljena pa se molio:');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (49, 22, 42, '\"Oče! Ako hoćeš, otkloni ovu čašu od mene. Ali ne moja volja, nego tvoja neka bude!\"');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (49, 22, 43, 'A ukaza mu se anđeo s neba koji ga ohrabri. A kad je bio u smrtnoj muci, usrdnije se molio.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (49, 22, 44, 'I bijaše znoj njegov kao kaplje krvi koje su padale na zemlju.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (49, 22, 45, 'Usta od molitve, dođe učenicima i nađe ih snene od žalosti');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (49, 22, 46, 'pa im reče: \"Što spavate? Ustanite! Molite da ne padnete u napast!\"');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (49, 22, 47, 'Dok je on još govorio, eto svjetine, a pred njom jedan od dvanaestorice, zvani Juda. On se približi Isusu da ga poljubi.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (49, 22, 48, 'Isus mu reče: \"Juda, poljupcem Sina Čovječjeg predaješ?\"');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (49, 22, 49, 'A oni oko njega, vidjevši što se zbiva, rekoše: \"Gospodine, da udarimo mačem?\"');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (49, 22, 50, 'I jedan od njih udari slugu velikoga svećenika i odsiječe mu desno uho.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (49, 22, 51, 'Isus odgovori: \"Pustite! Dosta!\" Onda se dotače uha i zacijeli ga.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (49, 22, 52, 'Nato Isus reče onima koji se digoše na nj, glavarima svećeničkim, zapovjednicima hramskim i starješinama: \"Kao na razbojnika iziđoste s mačevima i toljagama!');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (49, 22, 53, 'Danomice bijah s vama u Hramu i ne digoste ruke na me. No ovo je vaš čas i vlast Tmina.\"');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (49, 22, 54, 'Uhvatiše ga dakle, odvedoše i uvedoše u dom velikoga svećenika. Petar je išao za njim izdaleka.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (49, 22, 55, 'A posred dvorišta naložiše vatru i posjedaše uokolo. Među njih sjedne Petar.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (49, 22, 56, 'Ugleda ga neka sluškinja gdje sjedi kraj vatre, oštro ga pogleda i reče: \"I ovaj bijaše s njim!\"');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (49, 22, 57, 'A on zanijeka: \"Ne znam ga, ženo!\"');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (49, 22, 58, 'Malo zatim opazi ga netko drugi i reče: \"I ti si od njih!\" A Petar reče: \"Čovječe, nisam!\"');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (49, 22, 59, 'I nakon otprilike jedne ure drugi neki navaljivaše: \"Doista, i ovaj bijaše s njim! Ta Galilejac je!\"');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (49, 22, 60, 'A Petar će: \"Čovječe, ne znam što govoriš!\" I umah, dok je on još govorio, oglasi se pijetao.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (49, 22, 61, 'Gospodin se obazre i upre pogled u Petra, a Petar se spomenu riječi Gospodinove, kako mu ono reče: \"Prije nego se danas pijetao oglasi, zatajit ćeš me tri puta.\"');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (49, 22, 62, 'I iziđe te gorko zaplaka.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (49, 22, 63, 'A ljudi koji su Isusa čuvali udarajući ga poigravali se njime');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (49, 22, 64, 'i zastirući mu lice, zapitkivali ga: \"Proreci tko te udario!\"');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (49, 22, 65, 'I mnogim se drugim pogrdama nabacivali na nj.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (49, 22, 66, 'A kad se razdanilo, sabra se starješinstvo narodno, glavari svećenički i pismoznanci te ga dovedoše pred svoje Vijeće');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (49, 22, 67, 'i rekoše: \"Ako si ti Krist, reci nam!\" A on će im: \"Ako vam reknem, nećete vjerovati;');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (49, 22, 68, 'ako vas zapitam, nećete odgovoriti.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (49, 22, 69, 'No od sada će Sin Čovječji sjedjeti zdesna Sile Božje.\"');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (49, 22, 70, 'Nato svi rekoše: \"Ti si, dakle, Sin Božji!\" On im reče: \"Vi velite! Ja jesam!\"');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (49, 22, 71, 'Nato će oni: \"Što nam još svjedočanstvo treba? Ta sami smo čuli iz njegovih usta!\"');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (49, 23, 1, 'I ustade sva ona svjetina. Odvedoše ga Pilatu');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (49, 23, 2, 'i stadoše ga optuživati: \"Ovoga nađosmo kako zavodi naš narod i brani davati caru porez te za sebe tvrdi da je Krist, kralj.\"');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (49, 23, 3, 'Pilat ga upita: \"Ti li si kralj židovski?\" On mu odgovori: \"Ti kažeš!\"');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (49, 23, 4, 'Tada Pilat reče glavarima svećeničkim i svjetini: \"Nikakve krivnje ne nalazim na ovom čovjeku!\"');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (49, 23, 5, 'No oni navaljivahu: \"Buni narod naučavajući po svoj Judeji, počevši od Galileje pa dovde!\"');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (49, 23, 6, 'Čuvši to, Pilat propita da li je taj čovjek Galilejac.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (49, 23, 7, 'Saznavši da je iz oblasti Herodove, posla ga Herodu, koji i sam bijaše onih dana u Jeruzalemu.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (49, 23, 8, 'A kad Herod ugleda Isusa, veoma se obradova jer ga je već odavna želo vidjeti zbog onoga što je o njemu slušao te se nadao od njega vidjeti koje čudo.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (49, 23, 9, 'Postavljao mu je mnoga pitanja, ali mu Isus uopće nije odgovarao.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (49, 23, 10, 'A stajahu ondje i glavari svećenički i pismoznanci optužujući ga žestoko.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (49, 23, 11, 'Herod ga zajedno sa svojom vojskom prezre i ismija: obuče ga u bijelu haljinu i posla natrag Pilatu.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (49, 23, 12, 'Onoga se dana Herod i Pilat sprijateljiše, jer prije bijahu neprijatelji.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (49, 23, 13, 'A Pilat dade sazvati glavare svećeničke, vijećnike i narod');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (49, 23, 14, 'te im reče: \"Doveli ste mi ovoga čovjeka kao da buni narod. Ja ga evo ispitah pred vama pa ne nađoh na njemu ni jedne krivice za koju ga optužujete.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (49, 23, 15, 'A ni Herod jer ga posla natrag nama. Evo, on nije počinio ništa čime bi zaslužio smrt.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (49, 23, 16, 'Kaznit ću ga dakle i pustiti.\"');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (49, 23, 17, '#');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (49, 23, 18, 'I povikaše svi uglas: \"Smakni ovoga, a pusti nam Barabu!\"');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (49, 23, 19, 'A taj bijaše bačen u tamnicu zbog neke pobune u gradu i ubojstva.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (49, 23, 20, 'Pilat im stoga ponovno progovori hoteći osloboditi Isusa.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (49, 23, 21, 'Ali oni vikahu: \"Raspni, raspni ga!\"');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (49, 23, 22, 'On im treći put reče: \"Ta što je on zla učinio? Ne nađoh na njemu smrtne krivice. Kaznit ću ga dakle i pustiti.\"');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (49, 23, 23, 'Ali oni navaljivahu iza glasa ištući da se razapne. I vika im bivala sve jača.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (49, 23, 24, 'Pilat presudi da im bude što ištu.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (49, 23, 25, 'Pusti onoga koji zbog pobune i ubojstva bijaše bačen u tamnicu, koga su iskali, a Isusa preda njima na volju.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (49, 23, 26, 'Kad ga odvedoše, uhvatiše nekog Šimuna Cirenca koji je dolazio s polja i stave na nj križ da ga nosi za Isusom.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (49, 23, 27, 'Za njim je išlo silno mnoštvo svijeta, napose žena, koje su plakale i naricale za njim.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (49, 23, 28, 'Isus se okrenu prema njima pa im reče: \"Kćeri Jeruzalemske, ne plačite nada mnom, nego plačite nad sobom i nad djecom svojom.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (49, 23, 29, 'Jer evo idu dani kad će se govoriti: \'Blago nerotkinjama, utrobama koje ne rodiše i sisama koje ne dojiše.\'');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (49, 23, 30, 'Tad će početi govoriti gorama: \'Padnite na nas!\' i bregovima: \'Pokrijte nas!\'');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (49, 23, 31, 'Jer ako se tako postupa sa zelenim stablom, što li će biti sa suhim?\"');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (49, 23, 32, 'A vodili su i drugu dvojicu, zločince, da ih s njime pogube.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (49, 23, 33, 'I kada dođoše na mjesto zvano Lubanja, ondje razapeše njega i te zločince, jednoga zdesna, drugoga slijeva.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (49, 23, 34, 'A Isus je govorio: \"Oče, oprosti im, ne znaju što čine!\" I razdijeliše među se haljine njegove bacivši kocke.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (49, 23, 35, 'Stajao je ondje narod i promatrao. A podrugivali se i glavari govoreći: \"Druge je spasio, neka spasi sam sebe ako je on Krist Božji, Izabranik!\"');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (49, 23, 36, 'Izrugivali ga i vojnici, prilazili mu i nudili ga octom');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (49, 23, 37, 'govoreći: \"Ako si ti kralj židovski, spasi sam sebe!\"');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (49, 23, 38, 'A bijaše i natpis ponad njega: \"Ovo je kralj židovski.\"');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (49, 23, 39, 'Jedan ga je od obješenih zločinaca pogrđivao: \"Nisi li ti Krist? Spasi sebe i nas!\"');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (49, 23, 40, 'A drugi ovoga prekoravaše: \"Zar se ne bojiš Boga ni ti, koji si pod istom osudom?');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (49, 23, 41, 'Ali mi po pravdi jer primamo što smo djelima zaslužili, a on - on ništa opako ne učini.\"');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (49, 23, 42, 'Onda reče: \"Isuse, sjeti me se kada dođeš u kraljevstvo svoje.\"');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (49, 23, 43, 'A on će mu: \"Zaista ti kažem: danas ćeš biti sa mnom u raju!\"');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (49, 23, 44, 'Bijaše već oko šeste ure kad nasta tama po svoj zemlji - sve do ure devete,');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (49, 23, 45, 'jer sunce pomrča, a hramska se zavjesa razdrije po sredini.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (49, 23, 46, 'I povika Isus iza glasa: \"Oče, u ruke tvoje predajem duh svoj!\" To rekavši, izdahnu.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (49, 23, 47, 'Kad satnik vidje što se zbiva, stane slaviti Boga: \"Zbilja, čovjek ovaj bijaše pravednik!\"');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (49, 23, 48, 'I kad je sav svijet koji se zgrnuo na taj prizor vidio što se zbiva, vraćao se bijući se u prsa.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (49, 23, 49, 'Stajahu podalje i gledahu to svi znanci njegovi i žene koje su za njim išle iz Galileje.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (49, 23, 50, 'I dođe čovjek imenom Josip, vijećnik, čovjek čestit i pravedan;');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (49, 23, 51, 'on ne privoli njihovoj odluci i postupku. Bijaše iz Arimateje, grada judejskoga i iščekivaše kraljevstvo Božje.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (49, 23, 52, 'Taj dakle pristupi Pilatu i zaiska tijelo Isusovo.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (49, 23, 53, 'Zatim ga skinu, povi u platno i položi u grob isklesan u koji još ne bijaše nitko položen.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (49, 23, 54, 'Bijaše dan Priprave; subota je svitala.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (49, 23, 55, 'A pratile to žene koje su s Isusom došle iz Galileje: motrile grob i kako je položeno tijelo njegovo.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (49, 23, 56, 'Zatim se vrate i priprave miomirise i pomasti. U subotu mirovahu po propisu.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (49, 24, 1, 'Prvoga dana u tjednu, veoma rano, dođoše one na grob s miomirisima što ih pripraviše.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (49, 24, 2, 'Kamen nađoše otkotrljan od groba.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (49, 24, 3, 'Uđoše, ali ne nađoše tijela Gospodina Isusa.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (49, 24, 4, 'I dok su stajale zbunjene nad tim, gle, dva čovjeka u blistavoj odjeći stadoše do njih.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (49, 24, 5, 'Zastrašene obore lica k zemlji, a oni će im: \"Što tražite Živoga među mrtvima?');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (49, 24, 6, 'Nije ovdje, nego uskrsnu! Sjetite se kako vam je govorio dok je još bio u Galileji:');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (49, 24, 7, '\'Treba da Sin Čovječji bude predan u ruke grešnika, i raspet, i treći dan da ustane.\'\"');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (49, 24, 8, 'I sjetiše se one riječi njegovih,');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (49, 24, 9, 'vratiše se s groba te javiše sve to jedanaestorici i svima drugima.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (49, 24, 10, 'A bile su to: Marija Magdalena, Ivana i Marija Jakovljeva. I ostale zajedno s njima govorahu to apostolima,');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (49, 24, 11, 'ali njima se te riječi pričiniše kao tlapnja, te im ne vjerovahu.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (49, 24, 12, 'A Petar usta i potrča na grob. Sagnuvši se, opazi samo povoje. I vrati se kući čudeći se tome što se zbilo.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (49, 24, 13, 'I gle, dvojica su od njih toga istog dana putovala u selo koje se zove Emaus, udaljeno od Jeruzalema šezdeset stadija.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (49, 24, 14, 'Razgovarahu međusobno o svemu što se dogodilo.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (49, 24, 15, 'I dok su tako razgovarali i raspravljali, približi im se Isus i pođe s njima.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (49, 24, 16, 'Ali prepoznati ga - bijaše uskraćeno njihovim očima.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (49, 24, 17, 'On ih upita: \"Što to putem pretresate među sobom?\" Oni se snuždeni zaustave');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (49, 24, 18, 'te mu jedan od njih, imenom Kleofa, odgovori: \"Zar si ti jedini stranac u Jeruzalemu te ne znaš što se u njemu dogodilo ovih dana?\"');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (49, 24, 19, 'A on će: \"Što to?\" Odgovore mu: \"Pa ono s Isusom Nazarećaninom, koji bijaše prorok - silan na djelu i na riječi pred Bogom i svim narodom:');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (49, 24, 20, 'kako su ga glavari svećenički i vijećnici naši predali da bude osuđen na smrt te ga razapeli.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (49, 24, 21, 'A mi se nadasmo da je on onaj koji ima otkupiti Izraela. Ali osim svega toga ovo je već treći dan što se to dogodilo.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (49, 24, 22, 'A zbuniše nas i žene neke od naših: u praskozorje bijahu na grobu,');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (49, 24, 23, 'ali nisu našle njegova tijela pa dođoše te rekoše da su im se ukazali anđeli koji su rekli da je on živ.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (49, 24, 24, 'Odoše nato i neki naši na grob i nađoše kako žene rekoše, ali njega ne vidješe.\"');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (49, 24, 25, 'A on će im: \"O bezumni i srca spora da vjerujete što god su proroci navijestili!');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (49, 24, 26, 'Nije li trebalo da Krist sve to pretrpi te uđe u svoju slavu?\"');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (49, 24, 27, 'Počevši tada od Mojsija i svih proroka, protumači im što u svim Pismima ima o njemu.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (49, 24, 28, 'Uto se približe selu kamo su išli, a on kao da htjede dalje.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (49, 24, 29, 'No oni navaljivahu: \"Ostani s nama jer zamalo će večer i dan je na izmaku!\" I uniđe da ostane s njima.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (49, 24, 30, 'Dok bijaše s njima za stolom, uze kruh, izreče blagoslov, razlomi te im davaše.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (49, 24, 31, 'Uto im se otvore oči te ga prepoznaše, a on im iščeznu s očiju.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (49, 24, 32, 'Tada rekoše jedan drugome: \"Nije li gorjelo srce u nama dok nam je putem govorio, dok nam je otkrivao Pisma?\"');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (49, 24, 33, 'U isti se čas digoše i vratiše u Jeruzalem. Nađoše okupljenu jedanaestoricu i one koji bijahu s njima.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (49, 24, 34, 'Oni im rekoše: \"Doista uskrsnu Gospodin i ukaza se Šimunu!\"');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (49, 24, 35, 'Nato oni pripovjede ono s puta i kako ga prepoznaše u lomljenju kruha.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (49, 24, 36, 'Dok su oni o tom razgovarali, stane Isus posred njih i reče im: \"Mir vama!\"');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (49, 24, 37, 'Oni, zbunjeni i prestrašeni, pomisliše da vide duha.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (49, 24, 38, 'Reče im Isus: \"Zašto se prepadoste? Zašto vam sumnje obuzimaju srce?');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (49, 24, 39, 'Pogledajte ruke moje i noge! Ta ja sam! Opipajte me i vidite jer duh tijela ni kostiju nema kao što vidite da ja imam.\"');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (49, 24, 40, 'Rekavši to, pokaza im ruke i noge.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (49, 24, 41, 'I dok oni od radosti još nisu vjerovali, nego se čudom čudili, on im reče: \"Imate li ovdje što za jelo?\"');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (49, 24, 42, 'Oni mu pruže komad pečene ribe.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (49, 24, 43, 'On uzme i pred njima pojede.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (49, 24, 44, 'Nato im reče: \"To je ono što sam vam govorio dok sam još bio s vama: treba da se ispuni sve što je u Mojsijevu Zakonu, u Prorocima i Psalmima o meni napisano.\"');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (49, 24, 45, 'Tada im otvori pamet da razumiju Pisma');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (49, 24, 46, 'te im reče: \"Ovako je pisano: \'Krist će trpjeti i treći dan ustati od mrtvih,');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (49, 24, 47, 'i u njegovo će se ime propovijedati obraćenje i otpuštenje grijeha po svim narodima počevši od Jeruzalema.\'');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (49, 24, 48, 'Vi ste tomu svjedoci.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (49, 24, 49, 'I evo, ja šaljem na vas Obećanje Oca svojega. Ostanite zato u gradu dok se ne obučete u Silu odozgor.\"');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (49, 24, 50, 'Zatim ih izvede do Betanije, podiže ruke pa ih blagoslovi.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (49, 24, 51, 'I dok ih blagoslivljaše, rasta se od njih i uznesen bi na nebo.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (49, 24, 52, 'Oni mu se ničice poklone pa se s velikom radosti vrate u Jeruzalem');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (49, 24, 53, 'te sve vrijeme u Hramu blagoslivljahu Boga.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (50, 1, 1, 'U početku bijaše Riječ i Riječ bijaše u Boga i Riječ bijaše Bog.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (50, 1, 2, 'Ona bijaše u početku u Boga.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (50, 1, 3, 'Sve postade po njoj i bez nje ne postade ništa. Svemu što postade');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (50, 1, 4, 'u njoj bijaše život i život bijaše ljudima svjetlo;');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (50, 1, 5, 'i svjetlo u tami svijetli i tama ga ne obuze.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (50, 1, 6, 'Bi čovjek poslan od Boga, ime mu Ivan.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (50, 1, 7, 'On dođe kao svjedok da posvjedoči za Svjetlo da svi vjeruju po njemu.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (50, 1, 8, 'Ne bijaše on Svjetlo, nego - da posvjedoči za Svjetlo.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (50, 1, 9, 'Svjetlo istinsko koje prosvjetljuje svakog čovjeka dođe na svijet;');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (50, 1, 10, 'bijaše na svijetu i svijet po njemu posta i svijet ga ne upozna.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (50, 1, 11, 'K svojima dođe i njegovi ga ne primiše.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (50, 1, 12, 'A onima koji ga primiše podade moć da postanu djeca Božja: onima koji vjeruju u njegovo ime,');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (50, 1, 13, 'koji su rođeni ne od krvi, ni od volje tjelesne, ni od volje muževlje, nego - od Boga.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (50, 1, 14, 'I Riječ tijelom postade i nastani se među nama i vidjesmo slavu njegovu - slavu koju ima kao Jedinorođenac od Oca - pun milosti i istine.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (50, 1, 15, 'Ivan svjedoči za njega. Viče: \"To je onaj o kojem rekoh: koji za mnom dolazi, preda mnom je jer bijaše prije mene!\"');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (50, 1, 16, 'Doista, od punine njegove svi mi primismo, i to milost na milost.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (50, 1, 17, 'Uistinu, Zakon bijaše dan po Mojsiju, a milost i istina nasta po Isusu Kristu.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (50, 1, 18, 'Boga nitko nikada ne vidje: Jedinorođenac - Bog - koji je u krilu Očevu, on ga obznani.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (50, 1, 19, 'A evo svjedočanstva Ivanova. Kad su Židovi iz Jeruzalema poslali k njemu svećenike i levite da ga upitaju: \"Tko si ti?\",');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (50, 1, 20, 'on prizna; ne zanijeka, nego prizna: \"Ja nisam Krist.\"');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (50, 1, 21, 'Upitaše ga nato: \"Što dakle? Jesi li Ilija?\" Odgovori: \"Nisam.\" \"Jesi li Prorok?\" Odgovori: \"Ne.\"');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (50, 1, 22, 'Tada mu rekoše: \"Pa tko si da dadnemo odgovor onima koji su nas poslali? Što kažeš sam o sebi?\"');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (50, 1, 23, 'On odgovori: \"Ja sam glas koji viče u pustinji: Poravnite put Gospodnji! - kako reče prorok Izaija.\"');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (50, 1, 24, 'A neki izaslanici bijahu farizeji.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (50, 1, 25, 'Oni prihvatiše riječ i upitaše ga: \"Zašto onda krstiš kad nisi Krist, ni Ilija, ni Prorok?\"');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (50, 1, 26, 'Ivan im odgovori: \"Ja krstim vodom. Među vama stoji koga vi ne poznate -');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (50, 1, 27, 'onaj koji za mnom dolazi, komu ja nisam dostojan odriješiti remenje na obući.\"');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (50, 1, 28, 'To se dogodilo u Betaniji s onu stranu Jordana, gdje je Ivan krstio.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (50, 1, 29, 'Sutradan Ivan ugleda Isusa gdje dolazi k njemu pa reče: \"Evo Jaganjca Božjega koji odnosi grijeh svijeta!\"');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (50, 1, 30, 'To je onaj o kojem rekoh: Za mnom dolazi čovjek koji je preda mnom jer bijaše prije mene!\"');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (50, 1, 31, '\"Ja ga nisam poznavao, ali baš zato dođoh i krstim vodom da se on očituje Izraelu.\"');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (50, 1, 32, 'I posvjedoči Ivan: \"Promatrao sam Duha gdje s neba silazi kao golub i ostaje na njemu.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (50, 1, 33, 'Njega ja nisam poznavao, ali onaj koji me posla vodom krstiti reče mi: \'Na koga vidiš da Duh silazi i ostaje na njemu, to je onaj koji krsti Duhom Svetim.\'');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (50, 1, 34, 'I ja sam to vidio i svjedočim: on je Sin Božji.\"');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (50, 1, 35, 'Sutradan opet stajaše Ivan s dvojicom svojih učenika.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (50, 1, 36, 'Ugleda Isusa koji je onuda prolazio i reče: \"Evo Jaganjca Božjega!\"');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (50, 1, 37, 'Te njegove riječi čula ona dva njegova učenika pa pođoše za Isusom.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (50, 1, 38, 'Isus se obazre i vidjevši da idu za njim, upita ih: \"Što tražite?\" Oni mu rekoše: \"Rabbi\" - što znači: \"Učitelju - gdje stanuješ?\"');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (50, 1, 39, 'Reče im: \"Dođite i vidjet ćete.\" Pođoše dakle i vidješe gdje stanuje i ostadoše kod njega onaj dan. Bila je otprilike deseta ura.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (50, 1, 40, 'Jedan od one dvojice, koji su čuvši Ivana pošli za Isusom, bijaše Andrija, brat Šimuna Petra.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (50, 1, 41, 'On najprije nađe svoga brata Šimuna te će mu: \"Našli smo Mesiju!\" - što znači \"Krist - Pomazanik\".');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (50, 1, 42, 'Dovede ga Isusu, a Isus ga pogleda i reče: \"Ti si Šimun, sin Ivanov! Zvat ćeš se Kefa!\" - što znači \"Petar - Stijena\".');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (50, 1, 43, 'Sutradan naumi Isus poći u Galileju. Nađe Filipa i reče mu: \"Pođi za mnom!\"');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (50, 1, 44, 'Filip je bio iz Betsaide, iz grada Andrijina i Petrova.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (50, 1, 45, 'Filip nađe Natanaela i javi mu: \"Našli smo onoga o kome je pisao Mojsije u Zakonu i Proroci: Isusa, sina Josipova, iz Nazareta.\"');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (50, 1, 46, 'Reče mu Natanael: \"Iz Nazareta da može biti što dobro?\" Kaže mu Filip: \"Dođi i vidi.\"');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (50, 1, 47, 'Kad Isus ugleda gdje Natanael dolazi k njemu, reče za njega: \"Evo istinitog Izraelca u kojem nema prijevare!\"');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (50, 1, 48, 'Kaže mu Natanael: \"Odakle me poznaješ?\" Odgovori mu Isus: \"Vidjeh te prije negoli te Filip pozva, dok si bio pod smokvom.\"');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (50, 1, 49, 'Nato će mu Natanael: \"Učitelju, ti si Sin Božji! Ti kralj si Izraelov!\"');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (50, 1, 50, 'Odgovori mu Isus: \"Stoga što ti rekoh: \'Vidjeh te pod smokvom\', vjeruješ. I više ćeš od toga vidjeti!\"');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (50, 1, 51, 'I nadoda: \"Zaista, zaista, kažem vam: gledat ćete otvoreno nebo i anđele Božje gdje uzlaze i silaze nad Sina Čovječjega.\"');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (50, 2, 1, 'Trećeg dana bijaše svadba u Kani Galilejskoj. Bila ondje Isusova majka.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (50, 2, 2, 'Na svadbu bijaše pozvan i Isus i njegovi učenici.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (50, 2, 3, 'Kad ponesta vina, Isusu će njegova majka: \"Vina nemaju.\"');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (50, 2, 4, 'Kaže joj Isus: \"Ženo, što ja imam s tobom? Još nije došao moj čas!\"');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (50, 2, 5, 'Nato će njegova mati poslužiteljima: \"Što god vam rekne, učinite!\"');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (50, 2, 6, 'A bijaše ondje Židovima za čišćenje šest kamenih posuda od po dvije do tri mjere.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (50, 2, 7, 'Kaže Isus poslužiteljima: \"Napunite posude vodom!\" I napune ih do vrha.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (50, 2, 8, 'Tada im reče: \"Zagrabite sada i nosite ravnatelju stola.\" Oni odnesu.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (50, 2, 9, 'Kad okusi vodu što posta vinom, a nije znao odakle je - znale su sluge koje zagrabiše vodu - ravnatelj stola pozove zaručnika');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (50, 2, 10, 'i kaže mu: \"Svaki čovjek stavlja na stol najprije dobro vino, a kad se ponapiju, gore. Ti si čuvao dobro vino sve do sada.\"');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (50, 2, 11, 'Tako, u Kani Galilejskoj, učini Isus prvo znamenje i objavi svoju slavu te povjerovaše u njega njegovi učenici.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (50, 2, 12, 'Nakon toga siđe sa svojom majkom, s braćom i sa svojim učenicima u Kafarnaum. Ondje ostadoše nekoliko dana.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (50, 2, 13, 'Blizu bijaše židovska Pasha. Stoga Isus uziđe u Jeruzalem.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (50, 2, 14, 'U Hramu nađe prodavače volova, ovaca i golubova i mjenjače gdje sjede.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (50, 2, 15, 'I načini bič od užeta te ih sve istjera iz Hrama zajedno s ovcama i volovima. Mjenjačima rasu novac i stolove isprevrta,');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (50, 2, 16, 'a prodavačima golubova reče: \"Nosite to odavde i ne činite od kuće Oca mojega kuću trgovačku.\"');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (50, 2, 17, 'Prisjetiše se njegovi učenici da je pisano: Izjeda me revnost za Dom tvoj.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (50, 2, 18, 'Nato se umiješaju Židovi i upitaju ga: \"Koje nam znamenje možeš pokazati da to smiješ činiti?\"');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (50, 2, 19, 'Odgovori im Isus: \"Razvalite ovaj hram i ja ću ga u tri dana podići.\"');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (50, 2, 20, 'Rekoše mu nato Židovi: \"Četrdeset i šest godina gradio se ovaj Hram, a ti da ćeš ga u tri dana podići?\"');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (50, 2, 21, 'No on je govorio o hramu svoga tijela.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (50, 2, 22, 'Pošto uskrsnu od mrtvih, prisjetiše se njegovi učenici da je to htio reći te povjerovaše Pismu i besjedi koju Isus reče.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (50, 2, 23, 'Dok je boravio u Jeruzalemu o blagdanu Pashe, mnogi povjerovaše u njegovo ime promatrajući znamenja koja je činio.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (50, 2, 24, 'No sam se Isus njima nije povjeravao jer ih je sve dobro poznavao');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (50, 2, 25, 'i nije trebalo da mu tko daje svjedočanstvo o čovjeku: ta sam je dobro znao što je u čovjeku.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (50, 3, 1, 'Bijaše među farizejima čovjek imenom Nikodem, ugledan Židov.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (50, 3, 2, 'On dođe Isusu obnoć i reče mu: \"Rabbi, znamo da si od Boga došao kao učitelj jer nitko ne može činiti znamenja kakva ti činiš ako Bog nije s njime.\"');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (50, 3, 3, 'Odgovori mu Isus: \"Zaista, zaista, kažem ti: tko se ne rodi nanovo, odozgor, ne može vidjeti kraljevstva Božjega!\"');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (50, 3, 4, 'Kaže mu Nikodem: \"Kako se čovjek može roditi kad je star? Zar može po drugi put ući u utrobu majke svoje i roditi se?\"');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (50, 3, 5, 'Odgovori Isus: \"Zaista, zaista, kažem ti: ako se tko ne rodi iz vode i Duha, ne može ući u kraljevstvo Božje.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (50, 3, 6, 'Što je od tijela rođeno, tijelo je; i što je od Duha rođeno, duh je.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (50, 3, 7, 'Ne čudi se što ti rekoh: \'Treba da se rodite nanovo, odozgor.\'');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (50, 3, 8, 'Vjetar puše gdje hoće; čuješ mu šum, a ne znaš odakle dolazi i kamo ide. Tako je sa svakim koji je rođen od Duha.\"');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (50, 3, 9, 'Upita ga Nikodem: \"Kako se to može zbiti?\"');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (50, 3, 10, 'Odgovori mu Isus: \"Ti si učitelj u Izraelu pa to da ne razumiješ?');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (50, 3, 11, 'Zaista, zaista, kažem ti: govorimo što znamo, svjedočimo za ono što vidjesmo, ali svjedočanstva našega ne primate.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (50, 3, 12, 'Ako vam rekoh zemaljsko pa ne vjerujete, kako ćete vjerovati kad vam budem govorio nebesko?');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (50, 3, 13, 'Nitko nije uzašao na nebo doli onaj koji siđe s neba, Sin Čovječji.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (50, 3, 14, 'I kao što je Mojsije podigao zmiju u pustinji tako ima biti podignut Sin Čovječji');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (50, 3, 15, 'da svaki koji vjeruje u njemu ima život vječni.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (50, 3, 16, 'Uistinu, Bog je tako ljubio svijet te je dao svoga Sina Jedinorođenca da nijedan koji u njega vjeruje ne propadne, nego da ima život vječni.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (50, 3, 17, 'Ta Bog nije poslao Sina na svijet da sudi svijetu, nego da se svijet spasi po njemu.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (50, 3, 18, 'Tko vjeruje u njega, ne osuđuje se; a tko ne vjeruje, već je osuđen što nije vjerovao u ime jedinorođenoga Sina Božjega.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (50, 3, 19, 'A ovo je taj sud: Svjetlost je došla na svijet, ali ljudi su više ljubili tamu nego svjetlost jer djela im bijahu zla.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (50, 3, 20, 'Uistinu, tko god čini zlo, mrzi svjetlost i ne dolazi k svjetlosti da se ne razotkriju djela njegova;');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (50, 3, 21, 'a tko čini istinu, dolazi k svjetlosti nek bude bjelodano da su djela njegova u Bogu učinjena.\"');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (50, 3, 22, 'Poslije toga ode Isus sa svojim učenicima u Judejsku zemlju. Tu je boravio s njima i krstio.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (50, 3, 23, 'A krstio je i Ivan, u Enonu blizu Salima, jer ondje bijaše mnogo vode. Ljudi su dolazili i krstili se.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (50, 3, 24, 'Jer Ivan još nije bio bačen u tamnicu.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (50, 3, 25, 'Između Ivanovih učenika i nekog Židova nastade tako prepirka o čišćenju.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (50, 3, 26, 'Dođoše Ivanu i rekoše mu: \"Učitelju, onaj koji s tobom bijaše s onu stranu Jordana i za kojega si ti svjedočio - on eno krsti i svi hrle k njemu.\"');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (50, 3, 27, 'Ivan odgovori: \"Nitko ne može sebi uzeti ništa ako mu nije dano s neba.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (50, 3, 28, 'Vi ste mi sami svjedoci da sam rekao: \'Nisam ja Krist, nego poslan sam pred njim.\'');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (50, 3, 29, 'Tko ima zaručnicu, zaručnik je. A prijatelj zaručnikov, koji stoji uza nj i sluša ga, klikće od radosti na glas zaručnikov. Ta se moja radost upravo ispunila.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (50, 3, 30, 'On treba da raste, a ja da se umanjujem.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (50, 3, 31, 'Tko odozgor dolazi, on je iznad sviju; tko je sa zemlje, zemaljski je i zemaljski govori. Tko dolazi s neba, on je iznad sviju:');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (50, 3, 32, 'što je vidio i čuo - za to svjedoči, a svjedočanstva njegova nitko ne prima.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (50, 3, 33, 'Tko primi njegovo svjedočanstvo, potvrđuje da je Bog istinit.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (50, 3, 34, 'Uistinu, onaj koga Bog posla Božje riječi govori jer Bog Duha ne daje na mjeru.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (50, 3, 35, 'Otac ljubi Sina i sve je predao u ruku njegovu.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (50, 3, 36, 'Tko vjeruje u Sina, ima vječni život; a tko neće da vjeruje u Sina, neće vidjeti života; gnjev Božji ostaje na njemu.\"');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (50, 4, 1, 'Kad Gospodin dozna da su farizeji dočuli kako on, Isus, okuplja i krsti više učenika nego Ivan -');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (50, 4, 2, 'iako zapravo nije krstio sam Isus, nego njegovi učenici -');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (50, 4, 3, 'ode iz Judeje i ponovno se vrati u Galileju.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (50, 4, 4, 'Morao je proći kroza Samariju.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (50, 4, 5, 'Dođe dakle u samarijski grad koji se zove Sihar, blizu imanja što ga Jakov dade svojemu sinu Josipu.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (50, 4, 6, 'Ondje bijaše zdenac Jakovljev. Isus je umoran od puta sjedio na zdencu. Bila je otprilike šesta ura.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (50, 4, 7, 'Dođe neka žena Samarijanka zahvatiti vode. Kaže joj Isus: \"Daj mi piti!\"');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (50, 4, 8, 'Njegovi učenici bijahu otišli u grad kupiti hrane.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (50, 4, 9, 'Kaže mu na to Samarijanka: \"Kako ti, Židov, išteš piti od mene, Samarijanke?\" Jer Židovi se ne druže sa Samarijancima.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (50, 4, 10, 'Isus joj odgovori: \"Kad bi znala dar Božji i tko je onaj koji ti veli: \'Daj mi piti\', ti bi u njega zaiskala i on bi ti dao vode žive.\"');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (50, 4, 11, 'Odvrati mu žena: \"Gospodine, ta nemaš ni čime bi zahvatio, a zdenac je dubok. Otkuda ti dakle voda živa?');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (50, 4, 12, 'Zar si ti možda veći od oca našeg Jakova koji nam dade ovaj zdenac i sam je iz njega pio, a i sinovi njegovi i stada njegova?\"');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (50, 4, 13, 'Odgovori joj Isus: \"Tko god pije ove vode, opet će ožednjeti.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (50, 4, 14, 'A tko bude pio vode koju ću mu ja dati, ne, neće ožednjeti nikada: voda koju ću mu ja dati postat će u njemu izvorom vode koja struji u život vječni.\"');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (50, 4, 15, 'Kaže mu žena: \"Gospodine, daj mi te vode da ne žeđam i da ne moram dolaziti ovamo zahvaćati.\"');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (50, 4, 16, 'Nato joj on reče: \"Idi i zovi svoga muža pa se vrati ovamo.\"');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (50, 4, 17, 'Odgovori mu žena: \"Nemam muža.\" Kaže joj Isus: \"Dobro si rekla: \'Nemam muža!\'');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (50, 4, 18, 'Pet si doista muževa imala, a ni ovaj koga sada imaš nije ti muž. To si po istini rekla.\"');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (50, 4, 19, 'Kaže mu žena: \"Gospodine, vidim da si prorok.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (50, 4, 20, 'Naši su se očevi klanjali na ovome brdu, a vi kažete da je u Jeruzalemu mjesto gdje se treba klanjati.\"');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (50, 4, 21, 'A Isus joj reče: \"Vjeruj mi, ženo, dolazi čas kad se nećete klanjati Ocu ni na ovoj gori ni u Jeruzalemu.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (50, 4, 22, 'Vi se klanjate onome što ne poznate, a mi se klanjamo onome što poznamo jer spasenje dolazi od Židova.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (50, 4, 23, 'Ali dolazi čas - sada je! - kad će se istinski klanjatelji klanjati Ocu u duhu i istini jer takve upravo klanjatelje traži Otac.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (50, 4, 24, 'Bog je duh i koji se njemu klanjaju, u duhu i istini treba da se klanjaju.\"');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (50, 4, 25, 'Kaže mu žena: \"Znam da ima doći Mesija zvani Krist - Pomazanik. Kad on dođe, objavit će nam sve.\"');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (50, 4, 26, 'Kaže joj Isus: \"Ja sam, ja koji s tobom govorim!\"');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (50, 4, 27, 'Uto dođu njegovi učenici pa se začude što razgovara sa ženom. Nitko ga ipak ne zapita: \"Što tražiš?\" ili: \"Što razgovaraš s njom?\"');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (50, 4, 28, 'Žena ostavi svoj krčag pa ode u grad i reče ljudima:');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (50, 4, 29, '\"Dođite da vidite čovjeka koji mi je kazao sve što sam počinila. Da to nije Krist?\"');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (50, 4, 30, 'Oni iziđu iz grada te se upute k njemu.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (50, 4, 31, 'Učenici ga dotle nudili: \"Učitelju, jedi!\"');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (50, 4, 32, 'A on im reče: \"Hraniti mi se valja jelom koje vi ne poznajete.\"');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (50, 4, 33, 'Učenici se nato zapitkivahu: \"Da mu nije tko donio jesti?\"');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (50, 4, 34, 'Kaže im Isus: \"Jelo je moje vršiti volju onoga koji me posla i dovršiti djelo njegovo.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (50, 4, 35, 'Ne govorite li vi: \'Još četiri mjeseca i evo žetve?\' Gle, kažem vam, podignite oči svoje i pogledajte polja: već se bjelasaju za žetvu.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (50, 4, 36, 'Žetelac već prima plaću, sabire plod za vječni život da se sijač i žetelac zajedno raduju.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (50, 4, 37, 'Tu se obistinjuje izreka: \'Jedan sije, drugi žanje.\'');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (50, 4, 38, 'Ja vas poslah žeti ono oko čega se niste trudili; drugi su se trudili, a vi ste ušli u trud njihov.\"');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (50, 4, 39, 'Mnogi Samarijanci iz onoga grada povjerovaše u njega zbog riječi žene koja je svjedočila: \"Kazao mi je sve što sam počinila.\"');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (50, 4, 40, 'Kad su dakle Samarijanci došli k njemu, moljahu ga da ostane u njih. I ostade ondje dva dana.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (50, 4, 41, 'Tada ih je još mnogo više povjerovalo zbog njegove riječi');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (50, 4, 42, 'pa govorahu ženi: \"Sada više ne vjerujemo zbog tvoga kazivanja; ta sami smo čuli i znamo: ovo je uistinu Spasitelj svijeta.\"');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (50, 4, 43, 'Nakon dva dana ode odande u Galileju.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (50, 4, 44, 'Sam je Isus doduše izjavio da prorok nema časti u svom zavičaju.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (50, 4, 45, 'Kad je dakle stigao u Galileju, Galilejci ga lijepo primiše jer bijahu vidjeli što je sve učinio u Jeruzalemu za blagdana. Jer su i oni bili uzišli na blagdan.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (50, 4, 46, 'Dođe dakle ponovno u Kanu Galilejsku, gdje bijaše pretvorio vodu u vino. Ondje bijaše neki kraljevski službenik koji je imao bolesna sina u Kafarnaumu.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (50, 4, 47, 'Kad je čuo da je Isus došao iz Judeje u Galileju, ode k njemu pa ga moljaše da siđe i ozdravi mu sina jer već samo što nije umro.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (50, 4, 48, 'Nato mu Isus reče: \"Ako ne vidite znamenja i čudesa, ne vjerujete!\"');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (50, 4, 49, 'Kaže mu kraljevski službenik: \"Gospodine, siđi dok mi ne umre dijete.\"');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (50, 4, 50, 'Kaže mu Isus: \"Idi, sin tvoj živi!\" Povjerova čovjek riječi koju mu reče Isus i ode.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (50, 4, 51, 'Dok je on još silazio, pohite mu u susret sluge s viješću da mu sin živi.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (50, 4, 52, 'Upita ih dakle za uru kad mu je krenulo nabolje. Rekoše mu: \"Jučer oko sedme ure pustila ga ognjica.\"');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (50, 4, 53, 'Tada razabra otac da je to bilo upravo onog časa kad mu Isus reče: \"Sin tvoj živi.\" I povjerova on i sav dom njegov.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (50, 4, 54, 'Bijaše to drugo znamenje što ga učini Isus po povratku iz Judeje u Galileju.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (50, 5, 1, 'Nakon toga bijaše židovski blagdan pa Isus uziđe u Jeruzalem.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (50, 5, 2, 'U Jeruzalemu se kod Ovčjih vrata nalazi kupalište koje se hebrejski zove Bethzatha, a ima pet trijemova.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (50, 5, 3, 'U njima je ležalo mnoštvo bolesnika - slijepih, hromih, uzetih:čekali su da izbije voda..');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (50, 5, 4, 'Anđeo bi Gospodnji, naime, silazio od vremena do vremena u ribnjak i pokrenuo vodu: tko bi prvi ušao pošto je voda izbila, ozdravio bi makar bolovao od bilo kakve bolesti.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (50, 5, 5, 'Bijaše ondje neki čovjek koji je trpio od svoje bolesti trideset i osam godina.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (50, 5, 6, 'Kad ga Isus opazi gdje leži i kada dozna da je već dugo u tome stanju, kaže mu: \"Želiš li ozdraviti?\"');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (50, 5, 7, 'Odgovori mu bolesnik: \"Gospodine, nikoga nemam tko bi me uronio u kupalište kad se voda uzbiba. Dok ja stignem, drugi već prije mene siđe.\"');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (50, 5, 8, 'Kaže mu Isus: \"Ustani, uzmi svoju postelju i hodi!\"');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (50, 5, 9, 'Čovjek odmah ozdravi, uzme svoju postelju i prohoda. Toga dana bijaše subota.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (50, 5, 10, 'Židovi su stoga govorili ozdravljenomu: \"Subota je! Ne smiješ nositi postelju svoju!\"');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (50, 5, 11, 'On im odvrati: \"Onaj koji me ozdravi reče mi: \'Uzmi svoju postelju i hodi!\'\"');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (50, 5, 12, 'Upitaše ga dakle: \"Tko je taj čovjek koji ti je rekao: \'Uzmi i hodi?\'\"');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (50, 5, 13, 'No ozdravljenik nije znao tko je taj jer je Isus nestao u mnoštvu što se ondje nalazilo.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (50, 5, 14, 'Nakon toga nađe ga Isus u Hramu i reče mu: \"Eto, ozdravio si! Više ne griješi da te što gore ne snađe!\"');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (50, 5, 15, 'Čovjek ode i javi Židovima da je Isus onaj koji ga je ozdravio.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (50, 5, 16, 'Zbog toga su Židovi počeli Isusa napadati što to radi subotom.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (50, 5, 17, 'Isus im odgovori: \"Otac moj sve do sada radi pa i ja radim.\"');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (50, 5, 18, 'Zbog toga su Židovi još više gledali da ga ubiju jer je ne samo kršio subotu nego i Boga nazivao Ocem svojim izjednačujući sebe s Bogom.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (50, 5, 19, 'Isus nato odvrati: \"Zaista, zaista, kažem vam: Sin ne može sam od sebe činiti ništa, doli što vidi da čini Otac; što on čini, to jednako i Sin čini.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (50, 5, 20, 'Jer Otac Ljubi Sina i pokazuje mu sve što sam čini. Pokazat će mu i veća djela od ovih te ćete se čudom čuditi.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (50, 5, 21, 'Uistinu, kao što Otac uskrisuje mrtve i oživljava tako i Sin oživljava koje hoće.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (50, 5, 22, 'Otac doista ne sudi nikomu: sav je sud predao Sinu');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (50, 5, 23, 'da svi časte Sina kao što časte Oca. Tko ne časti Sina, ne časti ni Oca koji ga posla.\"');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (50, 5, 24, '\"Zaista, zaista, kažem vam: tko sluša moju riječ i vjeruje onomu koji me posla, ima život vječni i ne dolazi na sud, nego je prešao iz smrti u život.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (50, 5, 25, 'Zaista, zaista, kažem vam: dolazi čas - sada je! - kad će mrtvi čuti glas Sina Božjega i koji čuju, živjet će.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (50, 5, 26, 'Doista, kao što Otac ima život u sebi tako je i Sinu dao da ima život u sebi;');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (50, 5, 27, 'i ovlasti ga da sudi jer je Sin Čovječji.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (50, 5, 28, 'Ne čudite se tome jer dolazi čas kad će svi koji su u grobovima, čuti njegov glas.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (50, 5, 29, 'I izići će: koji su dobro činili - na uskrsnuće života, a koji su radili zlo - na uskrsnuće osude.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (50, 5, 30, 'Ja sam od sebe ne mogu učiniti ništa: kako čujem, sudim, i sud je moj pravedan jer ne tražim svoje volje, nego volju onoga koji me posla.\"');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (50, 5, 31, '\"Ako ja svjedočim sam za sebe, svjedočanstvo moje nije istinito.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (50, 5, 32, 'Drugi svjedoči za mene i znam: istinito je svjedočanstvo kojim on svjedoči za mene.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (50, 5, 33, 'Vi ste poslali k Ivanu i on je posvjedočio za istinu.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (50, 5, 34, 'Ja ne primam svjedočanstva od čovjeka, već govorim to da se vi spasite.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (50, 5, 35, 'On bijaše svjetiljka što gori i svijetli, a vi se htjedoste samo za čas naslađivati njegovom svjetlosti.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (50, 5, 36, 'Ali ja imam svjedočanstvo veće od Ivanova: djela koja mi je dao izvršiti Otac, upravo ta djela koja činim, svjedoče za mene - da me poslao Otac.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (50, 5, 37, 'Pa i Otac koji me posla sam je svjedočio za mene. Niti ste glasa njegova ikada čuli niti ste lica njegova ikada vidjeli,');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (50, 5, 38, 'a ni riječ njegova ne prebiva u vama jer ne vjerujete onomu kojega on posla.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (50, 5, 39, 'Vi istražujete Pisma jer mislite po njima imati život vječni. I ona svjedoče za mene,');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (50, 5, 40, 'a vi ipak nećete da dođete k meni da život imate.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (50, 5, 41, 'Slave od ljudi ne tražim,');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (50, 5, 42, 'ali vas dobro upoznah: ljubavi Božje nemate u sebi.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (50, 5, 43, 'Ja sam došao u ime Oca svoga i vi me ne primate. Dođe li tko drugi u svoje ime, njega ćete primiti.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (50, 5, 44, 'Ta kako biste vi vjerovali kad tražite slavu jedni od drugih, a slave od Boga jedinoga ne tražite!');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (50, 5, 45, 'Ne mislite da ću vas ja tužiti Ocu. Vaš je tužitelj Mojsije u koga se uzdate.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (50, 5, 46, 'Uistinu, kad biste vjerovali Mojsiju, i meni biste vjerovali: ta o meni je on pisao.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (50, 5, 47, 'Ali ako njegovim pismima ne vjerujete, kako da mojim riječima vjerujete?\"');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (50, 6, 1, 'Nakon toga ode Isus na drugu stranu Galilejskog, Tiberijadskog mora.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (50, 6, 2, 'Slijedilo ga silno mnoštvo jer su gledali znamenja što ih je činio na bolesnicima.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (50, 6, 3, 'A Isus uziđe na goru i ondje sjeđaše sa svojim učenicima.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (50, 6, 4, 'Bijaše blizu Pasha, židovski blagdan.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (50, 6, 5, 'Isus podigne oči i ugleda kako silan svijet dolazi k njemu pa upita Filipa: \"Gdje da kupimo kruha da ovi blaguju?\"');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (50, 6, 6, 'To reče kušajući ga; jer znao je što će učiniti.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (50, 6, 7, 'Odgovori mu Filip: \"Za dvjesta denara kruha ne bi bilo dosta da svaki nešto malo dobije.\"');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (50, 6, 8, 'Kaže mu jedan od njegovih učenika, Andrija, brat Šimuna Petra:');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (50, 6, 9, '\"Ovdje je dječak koji ima pet ječmenih kruhova i dvije ribice! Ali što je to za tolike?\"');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (50, 6, 10, 'Reče Isus: \"Neka ljudi posjedaju!\" A bilo je mnogo trave na tome mjestu. Posjedaše dakle muškarci, njih oko pet tisuća.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (50, 6, 11, 'Isus uze kruhove, izreče zahvalnicu pa razdijeli onima koji su posjedali. A tako i od ribica - koliko su god htjeli.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (50, 6, 12, 'A kad se nasitiše, reče svojim učenicima: \"Skupite preostale ulomke da ništa ne propadne!\"');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (50, 6, 13, 'Skupili su dakle i napunili dvanaest košara ulomaka što od pet ječmenih kruhova pretekoše onima koji su blagovali.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (50, 6, 14, 'Kad su ljudi vidjeli znamenje što ga Isus učini, rekoše: \"Ovo je uistinu Prorok koji ima doći na svijet!\"');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (50, 6, 15, 'Kad Isus spozna da kane doći, pograbiti ga i zakraljiti, povuče se ponovno u goru, posve sam.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (50, 6, 16, 'Kad nasta večer, siđoše njegovi učenici k moru,');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (50, 6, 17, 'uđoše u lađicu i krenuše na onu stranu mora, u Kafarnaum. Već se i smrklo, a Isusa još nikako k njima.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (50, 6, 18, 'More se uzburkalo od silnog vjetra što je zapuhao.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (50, 6, 19, 'Pošto su dakle isplovili oko dvadeset i pet do trideset stadija, ugledaju Isusa gdje ide po moru i približava se lađici. Prestraše se,');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (50, 6, 20, 'a on će njima: \"Ja sam! Ne bojte se!\"');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (50, 6, 21, 'Htjedoše ga uzeti u lađicu, kadli se lađica odmah nađe na obali kamo su se zaputili.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (50, 6, 22, 'Sutradan mnoštvo, koje osta s onu stranu mora, zapazi da ondje bijaše samo jedna lađica i da Isus nije bio ušao zajedno sa svojim učenicima u lađicu, nego da oni odoše sami.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (50, 6, 23, 'Iz Tiberijade pak stigoše druge lađice blizu onog mjesta gdje jedoše kruh pošto je Gospodin izrekao zahvalnicu.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (50, 6, 24, 'Kada dakle mnoštvo vidje da ondje nema Isusa ni njegovih učenika, uđu u lađice i odu u Kafarnaum tražeći Isusa.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (50, 6, 25, 'Kad ga nađoše s onu stranu mora, rekoše mu: \"Učitelju, kad si ovamo došao?\"');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (50, 6, 26, 'Isus im odgovori: \"Zaista, zaista, kažem vam: tražite me, ali ne stoga što vidjeste znamenja, nego stoga što ste jeli od onih kruhova i nasitili se.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (50, 6, 27, 'Radite, ali ne za hranu propadljivu, nego za hranu koja ostaje za život vječni: nju će vam dati Sin Čovječji jer njega Otac - Bog - opečati.\"');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (50, 6, 28, 'Rekoše mu dakle: \"Što nam je činiti da bismo radili djela Božja?\"');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (50, 6, 29, 'Odgovori im Isus: \"Djelo je Božje da vjerujete u onoga kojega je on poslao.\"');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (50, 6, 30, 'Rekoše mu onda: \"Kakvo ti znamenje činiš da vidimo pa da ti vjerujemo? Koje je tvoje djelo?');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (50, 6, 31, 'Očevi naši blagovaše manu u pustinji, kao što je pisano: Nahrani ih kruhom nebeskim.\"');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (50, 6, 32, 'Reče im Isus: \"Zaista, zaista, kažem vam: nije vam Mojsije dao kruh s neba, nego Otac moj daje vam kruh s neba, kruh istinski;');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (50, 6, 33, 'jer kruh je Božji Onaj koji silazi s neba i daje život svijetu.\"');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (50, 6, 34, 'Rekoše mu nato: \"Gospodine, daj nam uvijek toga kruha.\"');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (50, 6, 35, 'Reče im Isus: \"Ja sam kruh života. Tko dolazi k meni, neće ogladnjeti; tko vjeruje u mene, neće ožednjeti nikada.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (50, 6, 36, 'No rekoh vam: vidjeli ste me, a opet ne vjerujete.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (50, 6, 37, 'Svi koje mi daje Otac doći će k meni, i onoga tko dođe k meni neću izbaciti;');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (50, 6, 38, 'jer siđoh s neba ne da vršim svoju volju, nego volju onoga koji me posla.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (50, 6, 39, 'A ovo je volja onoga koji me posla: da nikoga od onih koje mi je dao ne izgubim, nego da ih uskrisim u posljednji dan.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (50, 6, 40, 'Da, to je volja Oca mojega da tko god vidi Sina i vjeruje u njega, ima život vječni i ja da ga uskrisim u posljednji dan.\"');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (50, 6, 41, 'Židovi nato mrmljahu protiv njega što je rekao: \"Ja sam kruh koji je sišao s neba.\"');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (50, 6, 42, 'Govorahu: \"Nije li to Isus, sin Josipov? Ne poznajemo li mu oca i majku? Kako sada govori: \'Sišao sam s neba?\'\"');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (50, 6, 43, 'Isus im odvrati: \"Ne mrmljajte među sobom!');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (50, 6, 44, 'Nitko ne može doći k meni ako ga ne povuče Otac koji me posla; i ja ću ga uskrisiti u posljednji dan.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (50, 6, 45, 'Pisano je u Prorocima: Svi će biti učenici Božji. Tko god čuje od Oca i pouči se, dolazi k meni.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (50, 6, 46, 'Ne da bi tko vidio Oca, doli onaj koji je kod Boga; on je vidio Oca.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (50, 6, 47, 'Zaista, zaista, kažem vam: tko vjeruje, ima život vječni.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (50, 6, 48, 'Ja sam kruh života.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (50, 6, 49, 'Očevi vaši jedoše u pustinji manu i pomriješe.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (50, 6, 50, 'Ovo je kruh koji silazi s neba: da tko od njega jede, ne umre.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (50, 6, 51, 'Ja sam kruh živi koji je s neba sišao. Tko bude jeo od ovoga kruha, živjet će uvijeke. Kruh koji ću ja dati tijelo je moje - za život svijeta.\"');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (50, 6, 52, 'Židovi se nato među sobom prepirahu: \"Kako nam ovaj može dati tijelo svoje za jelo?\"');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (50, 6, 53, 'Reče im stoga Isus: \"Zaista, zaista, kažem vam: ako ne jedete tijela Sina Čovječjega i ne pijete krvi njegove, nemate života u sebi!');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (50, 6, 54, 'Tko blaguje tijelo moje i pije krv moju, ima život vječni; i ja ću ga uskrisiti u posljednji dan.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (50, 6, 55, 'Tijelo je moje jelo istinsko, krv je moja piće istinsko.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (50, 6, 56, 'Tko jede moje tijelo i pije moju krv, u meni ostaje i ja u njemu.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (50, 6, 57, 'Kao što je mene poslao živi Otac i ja živim po Ocu, tako i onaj koji mene blaguje živjet će po meni.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (50, 6, 58, 'Ovo je kruh koji je s neba sišao, ne kao onaj koji jedoše očevi i pomriješe. Tko jede ovaj kruh, živjet će uvijeke.\"');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (50, 6, 59, 'To reče Isus naučavajući u sinagogi u Kafarnaumu.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (50, 6, 60, 'Mnogi od njegovih učenika čuvši to rekoše: \"Tvrda je to besjeda! Tko je može slušati?\"');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (50, 6, 61, 'A Isus znajući sam od sebe da njegovi učenici zbog toga mrmljaju, reče im: \"Zar vas to sablažnjava?');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (50, 6, 62, 'A što ako vidite Sina Čovječjega kako uzlazi onamo gdje je prije bio?\"');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (50, 6, 63, '\"Duh je onaj koji oživljuje, tijelo ne koristi ništa. Riječi koje sam vam govorio duh su i život su.\"');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (50, 6, 64, '\"A ipak, ima ih među vama koji ne vjeruju.\" Jer znao je Isus od početka koji su oni što ne vjeruju i tko je onaj koji će ga izdati.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (50, 6, 65, 'I doda: \"Zato sam vam i rekao da nitko ne može doći k meni ako mu nije dano od Oca.\"');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (50, 6, 66, 'Otada mnogi učenici odstupiše, više nisu išli s njime.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (50, 6, 67, 'Reče stoga Isus dvanaestorici: \"Da možda i vi ne kanite otići?\"');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (50, 6, 68, 'Odgovori mu Šimun Petar: \"Gospodine, kome da idemo? Ti imaš riječi života vječnoga!');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (50, 6, 69, 'I mi vjerujemo i znamo: ti si Svetac Božji.\"');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (50, 6, 70, 'Odgovori im Isus: \"Nisam li ja vas dvanaestoricu izabrao? A ipak, jedan je od vas đavao.\"');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (50, 6, 71, 'Govoraše to o Judi, sinu Šimuna Iškariotskoga, jednom od dvanaestorice, jer on ga je imao izdati.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (50, 7, 1, 'Nakon toga Isus je obilazio po Galileji; nije htio u Judeju jer su Židovi tražili da ga ubiju.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (50, 7, 2, 'Bijaše blizu židovski Blagdan sjenica.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (50, 7, 3, 'Rekoše mu stoga njegova braća: \"Otiđi odavle i pođi u Judeju da i tvoji učenici vide djela što činiš.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (50, 7, 4, 'Ta tko želi biti javno poznat, ne čini ništa u tajnosti. Ako već činiš sve to, očituj se svijetu.\"');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (50, 7, 5, 'Jer ni braća njegova nisu vjerovala u njega.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (50, 7, 6, 'Reče im nato Isus: \"Moje vrijeme još nije došlo, a za vas je vrijeme svagda pogodno.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (50, 7, 7, 'Vas svijet ne može mrziti, ali mene mrzi jer ja svjedočim protiv njega: da su mu djela opaka.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (50, 7, 8, 'Vi samo uziđite na blagdan. Ja još ne uzlazim na ovaj blagdan jer moje se vrijeme još nije ispunilo.\"');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (50, 7, 9, 'To im reče i ostade u Galileji.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (50, 7, 10, 'Ali pošto njegova braća uziđoše na blagdan, uziđe i on, ne javno, nego potajno.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (50, 7, 11, 'A Židovi su ga tražili o blagdanu pitajući: \"Gdje je onaj?\"');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (50, 7, 12, 'I među mnoštvom o njemu se mnogo šaptalo. Jedni govorahu: \"Dobar je!\" Drugi pak: \"Ne, nego zavodi narod.\"');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (50, 7, 13, 'Ipak nitko nije otvoreno govorio o njemu zbog straha od Židova.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (50, 7, 14, 'Usred blagdana uziđe Isus u Hram i stade naučavati.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (50, 7, 15, 'Židovi se u čudu pitahu: \"Kako ovaj znade Pisma, a nije učio?\"');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (50, 7, 16, 'Nato im Isus odvrati: \"Moj nauk nije moj, nego onoga koji me posla.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (50, 7, 17, 'Ako tko hoće vršiti volju njegovu, prepoznat će da li je taj nauk od Boga ili ja sam od sebe govorim.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (50, 7, 18, 'Tko sam od sebe govori, svoju slavu traži, a tko traži slavu onoga koji ga posla, taj je istinit i nema u njemu nepravednosti.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (50, 7, 19, 'Nije li vam Mojsije dao Zakon? Pa ipak nitko od vas ne vrši Zakona.\" \"Zašto tražite da me ubijete?\"');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (50, 7, 20, 'Odgovori mnoštvo: \"Zloduha imaš! Tko traži da te ubije?\"');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (50, 7, 21, 'Uzvrati im Isus: \"Jedno djelo učinih i svi se čudite.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (50, 7, 22, 'Mojsije vam dade obrezanje - ne, ono i nije od Mojsija, nego od otaca - i vi u subotu obrezujete čovjeka.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (50, 7, 23, 'Ako čovjek može primiti obrezanje u subotu da se ne prekrši Mojsijev zakon, zašto se ljutite na mene što sam svega čovjeka ozdravio u subotu?');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (50, 7, 24, 'Ne sudite po vanjštini, nego sudite sudom pravednim!\"');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (50, 7, 25, 'Rekoše tada neki Jeruzalemci: \"Nije li to onaj koga traže da ga ubiju?');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (50, 7, 26, 'A evo, posve otvoreno govori i ništa mu ne kažu. Da nisu možda i glavari doista upoznali da je on Krist?');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (50, 7, 27, 'Ali za njega znamo odakle je, a kad Krist dođe, nitko neće znati odakle je!\"');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (50, 7, 28, 'Nato Isus, koji je učio u Hramu, povika: \"Da! Poznajete me i znate odakle sam! A ipak ja nisam došao sam od sebe: postoji jedan istiniti koji me posla. Njega vi ne znate.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (50, 7, 29, 'Ja ga znadem jer sam od njega i on me poslao.\"');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (50, 7, 30, 'Židovi su otad vrebali da ga uhvate. Ipak nitko ne stavi na nj ruke jer još nije bio došao njegov čas.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (50, 7, 31, 'A mnogi iz mnoštva povjerovaše u nj te govorahu: \"Zar će Krist, kada dođe, činiti više znamenja nego što ih ovaj učini?\"');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (50, 7, 32, 'Dočuli farizeji da se to u mnoštvu o njemu šapće. Stoga glavari svećenički i farizeji poslaše stražare da ga uhvate.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (50, 7, 33, 'Tada Isus reče: \"Još sam malo vremena s vama i odlazim onomu koji me posla.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (50, 7, 34, 'Tražit ćete me i nećete me naći; gdje sam ja, vi ne možete doći.\"');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (50, 7, 35, 'Rekoše nato Židovi među sobom: \"Kamo to ovaj kani da ga mi nećemo naći? Da ne kani poći raseljenima među Grcima i naučavati Grke?');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (50, 7, 36, 'Što li znači besjeda koju reče: \'Tražit ćete me i nećete me naći; gdje sam ja, vi ne možete doći\'?\"');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (50, 7, 37, 'U posljednji, veliki dan blagdana Isus stade i povika: \"Ako je tko žedan, neka dođe k meni! Neka pije');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (50, 7, 38, 'koji vjeruje u mene! Kao što reče Pismo: \'Rijeke će žive vode poteći iz njegove utrobe!\'\"');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (50, 7, 39, 'To reče o Duhu kojega su imali primiti oni što vjeruju u njega. Tada doista ne bijaše još došao Duh jer Isus nije bio proslavljen.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (50, 7, 40, 'Kad su neki iz naroda čuli te riječi, govorahu: \"Ovo je uistinu Prorok.\"');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (50, 7, 41, 'Drugi govorahu: \"Ovo je Krist.\" A bilo ih je i koji su pitali: \"Pa zar Krist dolazi iz Galileje?');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (50, 7, 42, 'Ne kaže li Pismo da Krist dolazi iz potomstva Davidova, i to iz Betlehema, mjesta gdje bijaše David?\"');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (50, 7, 43, 'Tako je u narodu nastala podvojenost zbog njega.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (50, 7, 44, 'Neki ga čak htjedoše uhvatiti, ali nitko ne stavi na nj ruke.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (50, 7, 45, 'Dođoše dakle stražari glavarima svećeničkim i farizejima, a ovi im rekoše: \"Zašto ga ne dovedoste?\"');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (50, 7, 46, 'Stražari odgovore: \"Nikada nitko nije ovako govorio.\"');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (50, 7, 47, 'Nato će im farizeji: \"Zar ste se i vi dali zavesti?');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (50, 7, 48, 'Je li itko od glavara ili farizeja povjerovao u njega?');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (50, 7, 49, 'Ali ta svjetina koja ne pozna Zakona - to je prokleto!\"');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (50, 7, 50, 'Kaže im Nikodem - onaj koji ono prije dođe k Isusu, a bijaše jedan od njih:');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (50, 7, 51, '\"Zar naš Zakon sudi čovjeku ako ga prije ne sasluša i ne dozna što čini?\"');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (50, 7, 52, 'Odgovoriše mu: \"Da nisi i ti iz Galileje? Istraži pa ćeš vidjeti da iz Galileje ne ustaje prorok.\"');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (50, 7, 53, 'I otiđoše svaki svojoj kući.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (50, 8, 1, 'A Isus se uputi na Maslinsku goru.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (50, 8, 2, 'U zoru eto ga opet u Hramu. Sav je narod hrlio k njemu. On sjede i stade poučavati.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (50, 8, 3, 'Uto mu pismoznanci i farizeji dovedu neku ženu zatečenu u preljubu. Postave je u sredinu');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (50, 8, 4, 'i kažu mu: \"Učitelju! Ova je žena zatečena u samom preljubu.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (50, 8, 5, 'U Zakonu nam je Mojsije naredio takve kamenovati. Što ti na to kažeš?\"');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (50, 8, 6, 'To govorahu samo da ga iskušaju pa da ga mogu optužiti. Isus se sagne pa stane prstom pisati po tlu.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (50, 8, 7, 'A kako su oni dalje navaljivali, on se uspravi i reče im: \"Tko je od vas bez grijeha, neka prvi na nju baci kamen.\"');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (50, 8, 8, 'I ponovno se sagnuvši, nastavi pisati po zemlji.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (50, 8, 9, 'A kad oni to čuše, stadoše odlaziti jedan za drugim, počevši od starijih. Osta Isus sam - i žena koja stajaše u sredini.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (50, 8, 10, 'Isus se uspravi i reče joj: \"Ženo, gdje su oni? Zar te nitko ne osudi?\"');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (50, 8, 11, 'Ona reče: \"Nitko, Gospodine.\" Reče joj Isus: \"Ni ja te ne osuđujem. Idi i odsada više nemoj griješiti.\"');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (50, 8, 12, 'Isus im zatim ponovno progovori: \"Ja sam svjetlost svijeta; tko ide za mnom, neće hoditi u tami, nego će imati svjetlost života.\"');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (50, 8, 13, 'Farizeji mu nato rekoše: \"Ti svjedočiš sam za sebe: svjedočanstvo tvoje nije istinito!\"');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (50, 8, 14, 'Odgovori im Isus: \"Ako ja i svjedočim sam za sebe, svjedočanstvo je moje istinito jer znam odakle dođoh i kamo idem. A vi ne znate ni odakle dolazim ni kamo idem.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (50, 8, 15, 'Vi sudite po tijelu; ja ne sudim nikoga;');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (50, 8, 16, 'no ako i sudim, sud je moj istinit jer nisam sam, nego - ja i onaj koji me posla, Otac.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (50, 8, 17, 'Ta i u vašem zakonu piše da je svjedočanstvo dvojice istinito.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (50, 8, 18, 'Ja svjedočim za sebe, a svjedoči za mene i onaj koji me posla, Otac.\"');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (50, 8, 19, 'Nato ga upitaju: \"Gdje je tvoj Otac?\" Odgovori Isus: \"Niti mene poznajete niti Oca mojega. Kad biste poznavali mene, i Oca biste moga poznavali.\"');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (50, 8, 20, 'Te riječi rekao je Isus u riznici dok je naučavao u Hramu. I nitko ga ne uhvati jer još ne bijaše došao njegov čas.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (50, 8, 21, 'Reče im ponovno Isus: \"Ja odlazim, a vi ćete me tražiti i u svojem ćete grijehu umrijeti. Kamo ja odlazim, vi ne možete doći.\"');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (50, 8, 22, 'Židovi se nato stanu pitati: \"Da se možda ne kani ubiti kad govori: \'Kamo ja odlazim, vi ne možete doći\'?\"');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (50, 8, 23, 'A Isus nastavi: \"Vi ste odozdol, ja sam odozgor. Vi ste od ovoga svijeta, a ja nisam od ovoga svijeta.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (50, 8, 24, 'Stoga vam i rekoh: \'Umrijet ćete u grijesima svojim.\' Uistinu, ako ne povjerujete da Ja jesam, umrijet ćete u grijesima svojim.\"');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (50, 8, 25, 'Nato mu oni rekoše: \"A tko si ti?\" Odvrati Isus:');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (50, 8, 26, '\"Ta što da vam s početka opet zborim? Mnogo toga imam o vama zboriti i suditi; no onaj koji me posla istinit je, i što sam čuo od njega, to ja zborim svijetu.\"');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (50, 8, 27, 'Ne shvatiše da im govori o Ocu.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (50, 8, 28, 'Isus im nato reče: \"Kad uzdignete Sina Čovječjega, tada ćete upoznati da Ja jesam i da sam od sebe ne činim ništa, nego da onako zborim kako me naučio Otac.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (50, 8, 29, 'Onaj koji me posla sa mnom je i ne ostavi me sama jer ja uvijek činim što je njemu milo.\"');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (50, 8, 30, 'Na te njegove riječi mnogi povjerovaše u njega.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (50, 8, 31, 'Tada Isus progovori Židovima koji mu povjerovaše: \"Ako ostanete u mojoj riječi, uistinu, moji ste učenici;');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (50, 8, 32, 'upoznat ćete istinu i istina će vas osloboditi.\"');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (50, 8, 33, 'Odgovore mu: \"Potomstvo smo Abrahamovo i nikome nikada nismo robovali. Kako to ti govoriš: \'Postat ćete slobodni?\'\"');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (50, 8, 34, 'Odgovori im Isus: \"Zaista, zaista, kažem vam: tko god čini grijeh, rob je grijeha.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (50, 8, 35, 'Rob ne ostaje u kući zauvijek, a sin ostaje zauvijek.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (50, 8, 36, 'Ako vas dakle Sin oslobodi, zbilja ćete biti slobodni.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (50, 8, 37, 'Znam: potomstvo ste Abrahamovo, a ipak tražite da me ubijete jer moja riječ nema mjesta u vama.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (50, 8, 38, 'Ja govorim što vidjeh kod Oca, a vi činite što čuste od svog oca.\"');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (50, 8, 39, 'Odgovoriše mu: \"Naš je otac Abraham\". Kaže im Isus: \"Da ste djeca Abrahamova, djela biste Abrahamova činili.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (50, 8, 40, 'A eto, tražite da ubijete mene, mene koji sam vam govorio istinu što sam je od Boga čuo. Takvo što Abraham nije učinio!');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (50, 8, 41, 'Vi činite djela oca svojega.\" Rekoše mu: \"Mi se nismo rodili iz preljuba, jedan nam je Otac - Bog.\"');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (50, 8, 42, 'Reče im Isus: \"Kad bi Bog bio vaš Otac, ljubili biste mene jer sam ja od Boga izišao i došao; nisam sam od sebe došao, nego on me posla.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (50, 8, 43, 'Zašto moje besjede ne razumijete? Zato što niste kadri slušati moju riječ.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (50, 8, 44, 'Vama je otac đavao i hoće vam se vršiti prohtjeve oca svoga. On bijaše čovjekoubojica od početka i ne stajaše u istini jer nema istine u njemu: kad govori laž, od svojega govori jer je lažac i otac laži.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (50, 8, 45, 'A meni, jer istinu govorim, meni ne vjerujete.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (50, 8, 46, 'Tko će mi od vas dokazati grijeh? Ako istinu govorim, zašto mi ne vjerujete?');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (50, 8, 47, 'Tko je od Boga, riječi Božje sluša; vi zato ne slušate jer niste od Boga.\"');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (50, 8, 48, 'Odgovoriše mu Židovi: \"Ne kažemo li pravo da si ti Samarijanac i da imaš zloduha?\"');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (50, 8, 49, 'Odgovori Isus: \"Ja nemam zloduha, nego častim svoga Oca, a vi me obeščašćujete.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (50, 8, 50, 'No ja ne tražim svoje slave; ima tko traži i sudi.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (50, 8, 51, 'Zaista, zaista, kažem vam: ako tko očuva moju riječ, neće vidjeti smrti dovijeka.\"');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (50, 8, 52, 'Rekoše mu Židovi: \"Sada vidimo da imaš zloduha. Abraham umrije, tako i proroci, a ti kažeš: \'Ako tko čuva moju riječ, neće okusiti smrti dovijeka.\'');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (50, 8, 53, 'Zar si ti veći od oca našega Abrahama, koji je umro? Pa i proroci pomriješe. Kime se to praviš?\"');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (50, 8, 54, 'Odgovori Isus: \"Ako ja sam sebe slavim, slava moja nije ništa. Ima koji me slavi - Otac moj, a vi velite da je on vaš Bog,');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (50, 8, 55, 'no ne poznajete ga, a ja ga znam. Ako vam reknem da ga ne znam, bit ću lažac jednak vama. No znam ga i riječ njegovu čuvam.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (50, 8, 56, 'Abraham, otac vaš, usklikta što će vidjeti moj Dan. I vidje i obradova se.\"');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (50, 8, 57, 'Rekoše mu nato Židovi: \"Ni pedeset ti još godina nije, a vidio si Abrahama?\"');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (50, 8, 58, 'Reče im Isus: \"Zaista, zaista, kažem vam: prije negoli Abraham posta, Ja jesam!\"');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (50, 8, 59, 'Nato pograbiše kamenje da bace na nj. No Isus se sakri te iziđe iz Hrama.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (50, 9, 1, 'Prolazeći ugleda čovjeka slijepa od rođenja.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (50, 9, 2, 'Zapitaše ga njegovi učenici: \"Učitelju, tko li sagriješi, on ili njegovi roditelji te se slijep rodio?\"');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (50, 9, 3, 'Odgovori Isus: \"Niti sagriješi on niti njegovi roditelji, nego je to zato da se na njemu očituju djela Božja.\"');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (50, 9, 4, '\"Dok je dan, treba da radimo djela onoga koji me posla. Dolazi noć, kad nitko ne može raditi.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (50, 9, 5, 'Dok sam na svijetu, svjetlost sam svijeta.\"');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (50, 9, 6, 'To rekavši, pljune na zemlju i od pljuvačke načini kal pa mu kalom premaza oči.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (50, 9, 7, 'I reče mu: \"Idi, operi se u kupalištu Siloamu!\" - što znači \"Poslanik.\" Onaj ode, umije se pa se vrati gledajući.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (50, 9, 8, 'Susjedi i oni koji su ga prije viđali kao prosjaka govorili su: \"Nije li to onaj koji je sjedio i prosio?\"');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (50, 9, 9, 'Jedni su govorili: \"On je.\" Drugi opet: \"Nije, nego mu je sličan.\" On je sam tvrdio: \"Da, ja sam!\"');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (50, 9, 10, 'Nato ga upitaše: \"Kako su ti se otvorile oči?\"');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (50, 9, 11, 'On odgovori: \"Čovjek koji se zove Isus načini kal, premaza mi oči i reče mi: \'Idi u Siloam i operi se.\' Odoh dakle, oprah se i progledah.\"');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (50, 9, 12, 'Rekoše mu: \"Gdje je on?\" Odgovori: \"Ne znam.\"');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (50, 9, 13, 'Tada odvedoše toga bivšeg slijepca farizejima.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (50, 9, 14, 'A toga dana kad Isus načini kal i otvori njegove oči, bijaše subota.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (50, 9, 15, 'Farizeji ga počeše iznova ispitivati kako je progledao. On im reče: \"Stavio mi kal na oči i ja se oprah - i evo vidim.\"');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (50, 9, 16, 'Nato neki između farizeja rekoše: \"Nije taj čovjek od Boga: ne pazi na subotu.\" Drugi su pak govorili: \"A kako bi jedan grešnik mogao činiti takva znamenja?\" I nastade među njima podvojenost.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (50, 9, 17, 'Zatim ponovno upitaju slijepca: \"A što ti kažeš o njemu? Otvorio ti je oči!\" On odgovori: \"Prorok je!\"');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (50, 9, 18, 'Židovi ipak ne vjerovahu da on bijaše slijep i da je progledao dok ne dozvaše roditelje toga koji je progledao');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (50, 9, 19, 'i upitaše ih: \"Je li ovo vaš sin za kojega tvrdite da se slijep rodio? Kako sada vidi?\"');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (50, 9, 20, 'Njegovi roditelji odvrate: \"Znamo da je ovo naš sin i da se slijep rodio.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (50, 9, 21, 'A kako sada vidi, to mi ne znamo; i tko mu je otvorio oči, ne znamo. Njega pitajte! Punoljetan je: neka sam o sebi govori!\"');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (50, 9, 22, 'Rekoše tako njegovi roditelji jer su se bojali Židova. Židovi se doista već bijahu dogovorili da se iz sinagoge ima izopćiti svaki koji njega prizna Kristom.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (50, 9, 23, 'Zbog toga rekoše njegovi roditelji: \"Punoljetan je, njega pitajte!\"');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (50, 9, 24, 'Pozvaše stoga po drugi put čovjeka koji bijaše slijep i rekoše mu: \"Podaj slavu Bogu! Mi znamo da je taj čovjek grešnik!\"');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (50, 9, 25, 'Nato im on odgovori: \"Je li grešnik, ja ne znam. Jedno znam: slijep sam bio, a sada vidim.\"');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (50, 9, 26, 'Rekoše mu opet: \"Što ti učini? Kako ti otvori oči?\"');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (50, 9, 27, 'Odgovori im: \"Već vam rekoh i ne poslušaste me. Što opet hoćete čuti? Da ne kanite i vi postati njegovim učenicima?\"');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (50, 9, 28, 'Nato ga oni izgrdiše i rekoše: \"Ti si njegov učenik, a mi smo učenici Mojsijevi.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (50, 9, 29, 'Mi znamo da je Mojsiju govorio Bog, a za ovoga ne znamo ni odakle je.\"');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (50, 9, 30, 'Odgovori im čovjek: \"Pa to i jest čudnovato da vi ne znate odakle je, a meni je otvorio oči.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (50, 9, 31, 'Znamo da Bog grešnike ne uslišava; nego je li tko bogobojazan i vrši li njegovu volju, toga uslišava.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (50, 9, 32, 'Odvijeka se nije čulo da bi tko otvorio oči slijepcu od rođenja.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (50, 9, 33, 'Kad ovaj ne bi bio od Boga, ne bi mogao činiti ništa\".');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (50, 9, 34, 'Odgovore mu: \"Sav si se u grijesima rodio, i ti nas da učiš?\" i izbaciše ga.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (50, 9, 35, 'Dočuo Isus da su onoga izbacili pa ga nađe i reče mu: \"Ti vjeruješ u Sina Čovječjega?\"');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (50, 9, 36, 'On odgovori: \"A tko je taj, Gospodine, da vjerujem u njega?\"');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (50, 9, 37, 'Reče mu Isus: \"Vidio si ga! To je onaj koji govori s tobom!\"');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (50, 9, 38, 'A on reče: \"Vjerujem, Gospodine!\" I baci se ničice preda nj.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (50, 9, 39, 'Tada Isus reče: \"Radi suda dođoh na ovaj svijet: da progledaju koji ne vide, a koji vide, da oslijepe!\"');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (50, 9, 40, 'Čuli to neki od farizeja koji su bili s njime pa ga upitaju: \"Zar smo i mi slijepi?\"');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (50, 9, 41, 'Isus im odgovori: \"Da ste slijepi, ne biste imali grijeha. No vi govorite: \'Vidimo\' pa grijeh vaš ostaje.\"');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (50, 10, 1, '\"Zaista, zaista, kažem vam: tko god u ovčinjak ne ulazi na vrata, nego negdje drugdje preskače, kradljivac je i razbojnik.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (50, 10, 2, 'A tko na vrata ulazi, pastir je ovaca.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (50, 10, 3, 'Tome vratar otvara i ovce slušaju njegov glas. On ovce svoje zove imenom pa ih izvodi.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (50, 10, 4, 'A kad sve svoje izvede, pred njima ide i ovce idu za njim jer poznaju njegov glas.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (50, 10, 5, 'Za tuđincem, dakako, ne idu, već bježe od njega jer tuđinčeva glasa ne poznaju.\"');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (50, 10, 6, 'Isus im kaza tu poredbu, ali oni ne razumješe što im htjede time kazati.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (50, 10, 7, 'Stoga im Isus ponovno reče: \"Zaista, zaista, kažem vam: ja sam vrata ovcama.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (50, 10, 8, 'Svi koji dođoše prije mene, kradljivci su i razbojnici; ali ih ovce ne poslušaše.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (50, 10, 9, 'Ja sam vrata. Kroza me tko uđe, spasit će se: i ulazit će i izlaziti i pašu nalaziti.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (50, 10, 10, 'Kradljivac dolazi samo da ukrade, zakolje i pogubi. Ja dođoh da život imaju, u izobilju da ga imaju.\"');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (50, 10, 11, '\"Ja sam pastir dobri. Pastir dobri život svoj polaže za ovce.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (50, 10, 12, 'Najamnik - koji nije pastir i nije vlasnik ovaca - kad vidi vuka gdje dolazi, ostavlja ovce i bježi, a vuk ih grabi i razgoni:');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (50, 10, 13, 'najamnik je i nije mu do ovaca.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (50, 10, 14, 'Ja sam pastir dobri i poznajem svoje i mene poznaju moje,');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (50, 10, 15, 'kao što mene poznaje Otac i ja poznajem Oca i život svoj polažem za ovce.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (50, 10, 16, 'Imam i drugih ovaca, koje nisu iz ovog ovčinjaka. I njih treba da dovedem i glas će moj čuti i bit će jedno stado, jedan pastir.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (50, 10, 17, 'Zbog toga me i ljubi Otac što polažem život svoj da ga opet uzmem.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (50, 10, 18, 'Nitko mi ga ne oduzima, nego ja ga sam od sebe polažem. Vlast imam položiti ga, vlast imam opet uzeti ga. Tu zapovijed primih od Oca svoga.\"');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (50, 10, 19, 'Među Židovima ponovno nasta podvojenost zbog tih riječi.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (50, 10, 20, 'Mnogi su od njih govorili: \"Zloduha ima pa mahnita! Što ga slušate?\"');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (50, 10, 21, 'Drugi su govorili: \"Nisu to riječi opsjednuta. Zar zloduh može slijepima oči otvoriti?\"');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (50, 10, 22, 'Svetkovao se tada u Jeruzalemu Blagdan posvećenja. Bila je zima.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (50, 10, 23, 'Isus je obilazio Hramom po trijemu Salomonovu.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (50, 10, 24, 'Okružili ga Židovi i govorili mu: \"Dokle ćeš nam dušu držati u neizvjesnosti? Ako si ti Krist, reci nam otvoreno!\"');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (50, 10, 25, 'Isus im odgovori: \"Rekoh vam pa ne vjerujete. Djela što ih ja činim u ime Oca svoga - ona svjedoče za mene.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (50, 10, 26, 'Ali vi ne vjerujete jer niste od mojih ovaca.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (50, 10, 27, 'Ovce moje slušaju glas moj; ja ih poznajem i one idu za mnom.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (50, 10, 28, 'Ja im dajem život vječni te neće propasti nikada i nitko ih neće ugrabiti iz moje ruke.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (50, 10, 29, 'Otac moj, koji mi ih dade, veći je od svih i nitko ih ne može ugrabiti iz ruke Očeve.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (50, 10, 30, 'Ja i Otac jedno smo.\"');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (50, 10, 31, 'Židovi ponovno pograbiše kamenje da ga kamenuju.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (50, 10, 32, 'Isus im odgovori: \"Mnoga vam dobra djela Očeva pokazah. Za koje me od tih djela kamenujete?\"');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (50, 10, 33, 'Odgovoriše mu Židovi: \"Zbog dobra te djela ne kamenujemo, nego zbog hule: što ti - čovjek - sebe Bogom praviš.\"');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (50, 10, 34, 'Odgovori im Isus: \"Nije li pisano u vašem Zakonu: Ja rekoh: bogovi ste!');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (50, 10, 35, 'Ako bogovima nazva one kojima je riječ Božja upravljena - a Pismo se ne može dokinuti -');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (50, 10, 36, 'kako onda vi onome kog Otac posveti i posla na svijet možete reći: \'Huliš!\' - zbog toga što rekoh: \'Sin sam Božji!\'');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (50, 10, 37, 'Ako ne činim djela Oca svoga, nemojte mi vjerovati.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (50, 10, 38, 'Ali ako činim, sve ako meni i ne vjerujete, djelima vjerujte pa uvidite i upoznajte da je Otac u meni i ja u Ocu.\"');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (50, 10, 39, 'Nato ga ponovno nastojahu uhvatiti, ali im on izmaknu iz ruku.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (50, 10, 40, 'I ode ponovno na onu stranu Jordana - na mjesto gdje je prije Ivan krstio. I osta ondje.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (50, 10, 41, 'A mnogi dođoše k njemu i rekoše mu: \"Ivan doduše ne učini nijednog znamenja, ali se sve obistinilo što je rekao o ovome.\"');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (50, 10, 42, 'Mnogi ondje povjerovaše u njega.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (50, 11, 1, 'Bijaše neki bolesnik, Lazar iz Betanije, iz sela Marije i sestre joj Marte.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (50, 11, 2, 'Marija bijaše ono pomazala Gospodina pomašću i otrla mu noge svojom kosom. Njezin dakle brat Lazar bijaše bolestan.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (50, 11, 3, 'Sestre stoga poručiše Isusu: \"Gospodine, evo onaj koga ljubiš, bolestan je.\"');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (50, 11, 4, 'Čuvši to, Isus reče: \"Ta bolest nije na smrt, nego na slavu Božju, da se po njoj proslavi Sin Božji.\"');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (50, 11, 5, 'A Isus ljubljaše Martu i njezinu sestru i Lazara.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (50, 11, 6, 'Ipak, kad je čuo za njegovu bolest, ostade još dva dana u onome mjestu gdje se nalazio.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (50, 11, 7, 'Istom nakon toga reče učenicima: \"Pođimo opet u Judeju!\"');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (50, 11, 8, 'Kažu mu učenici: \"Učitelju, Židovi su sad tražili da te kamenuju, pa da opet ideš onamo?\"');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (50, 11, 9, 'Odgovori Isus: \"Nema li dan dvanaest sati? Hodi li tko danju, ne spotiče se jer vidi svjetlost ovoga svijeta.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (50, 11, 10, 'Hodi li tko noću, spotiče se jer nema svjetlosti u njemu.\"');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (50, 11, 11, 'To reče, a onda im dometnu: \"Lazar, prijatelj naš, spava, no idem probuditi ga.\"');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (50, 11, 12, 'Rekoše mu nato učenici: \"Gospodine, ako spava, ozdravit će.\"');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (50, 11, 13, 'No Isus to reče o njegovoj smrti, a oni pomisliše da govori o spavanju, o snu.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (50, 11, 14, 'Tada im Isus reče posve otvoreno: \"Lazar je umro.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (50, 11, 15, 'Ja se radujem što ne bijah ondje, i to poradi vas - da uzvjerujete. Nego pođimo k njemu!\"');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (50, 11, 16, 'Nato Toma zvani Blizanac reče suučenicima: \"Hajdemo i mi da umremo s njime!\"');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (50, 11, 17, 'Kad je dakle Isus stigao, nađe da je onaj već četiri dana u grobu.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (50, 11, 18, 'Betanija bijaše blizu Jeruzalema otprilike petnaest stadija.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (50, 11, 19, 'A mnogo Židova bijaše došlo tješiti Martu i Mariju zbog brata njihova.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (50, 11, 20, 'Kad Marta doču da Isus dolazi, pođe mu u susret dok je Marija ostala u kući.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (50, 11, 21, 'Marta reče Isusu: \"Gospodine, da si bio ovdje, brat moj ne bi umro.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (50, 11, 22, 'Ali i sada znam: što god zaišteš od Boga, dat će ti.\"');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (50, 11, 23, 'Kaza joj Isus: \"Uskrsnut će brat tvoj!\"');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (50, 11, 24, 'A Marta mu odgovori: \"Znam da će uskrsnuti o uskrsnuću, u posljednji dan.\"');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (50, 11, 25, 'Reče joj Isus: \"Ja sam uskrsnuće i život: tko u mene vjeruje, ako i umre, živjet će.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (50, 11, 26, 'I tko god živi i vjeruje u mene, neće umrijeti nikada. Vjeruješ li ovo?\"');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (50, 11, 27, 'Odgovori mu: \"Da, Gospodine! Ja vjerujem da si ti Krist, Sin Božji, Onaj koji dolazi na svijet!\"');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (50, 11, 28, 'Rekavši to ode, zovnu svoju sestru Mariju i reče joj krišom: \"Učitelj je ovdje i zove te.\"');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (50, 11, 29, 'A ona, čim doču, brzo ustane i pođe k njemu.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (50, 11, 30, 'Isus još ne bijaše ušao u selo, nego je dotada bio na mjestu gdje ga je Marta susrela.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (50, 11, 31, 'Kad Židovi, koji su s Marijom bili u kući i tješili je, vidješe kako je brzo ustala i izišla, pođoše za njom; mišljahu da ide na grob plakati.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (50, 11, 32, 'A kad Marija dođe onamo gdje bijaše Isus i kad ga ugleda, baci mu se k nogama govoreći: \"Gospodine, da si bio ovjde, brat moj ne bi umro.\"');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (50, 11, 33, 'Kad Isus vidje kako plače ona i Židovi koji je dopratiše, potresen u duhu i uzbuđen');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (50, 11, 34, 'upita: \"Kamo ste ga položili?\" Odgovoriše mu: \"Gospodine, dođi i pogledaj!\"');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (50, 11, 35, 'I zaplaka Isus.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (50, 11, 36, 'Nato su Židovi govorili: \"Gle, kako ga je ljubio!\"');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (50, 11, 37, 'A neki između njih rekoše: \"Zar on, koji je slijepcu otvorio oči, nije mogao učiniti da ovaj ne umre?\"');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (50, 11, 38, 'Isus onda, ponovno potresen, pođe grobu. Bila je to pećina, a na nju navaljen kamen.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (50, 11, 39, 'Isus zapovjedi: \"Odvalite kamen!\" Kaže mu pokojnikova sestra Marta: \"Gospodine, već zaudara. Ta četvrti je dan.\"');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (50, 11, 40, 'Kaže joj Isus: \"Nisam li ti rekao: budeš li vjerovala, vidjet ćeš slavu Božju?\"');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (50, 11, 41, 'Odvališe dakle kamen. A Isus podiže oči i reče: \"Oče, hvala ti što si me uslišao.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (50, 11, 42, 'Ja sam znao da me svagda uslišavaš; no rekoh to zbog nazočnog mnoštva: da vjeruju da si me ti poslao.\"');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (50, 11, 43, 'Rekavši to povika iza glasa: \"Lazare, izlazi!\"');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (50, 11, 44, 'I mrtvac iziđe, noge mu i ruke bile povezane povojima, a lice omotano ručnikom. Nato Isus reče: \"Odriješite ga i pustite neka ide!\"');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (50, 11, 45, 'Tada mnogi Židovi koji bijahu došli k Mariji, kad vidješe što Isus učini, povjerovaše u nj.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (50, 11, 46, 'A neki od njih odu farizejima i pripovjede im što Isus učini.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (50, 11, 47, 'Stoga glavari svećenički i farizeji sazvaše Vijeće. Govorili su: \"Što da radimo? Ovaj čovjek čini mnoga znamenja.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (50, 11, 48, 'Ako ga pustimo tako, svi će povjerovati u nj pa će doći Rimljani i oduzeti nam ovo mjesto i narod!\"');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (50, 11, 49, 'A jedan od njih - Kajfa, veliki svećenik one godine - reče im: \"Vi ništa ne znate.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (50, 11, 50, 'I ne mislite kako je za vas bolje da jedan čovjek umre za narod, nego da sav narod propadne!\"');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (50, 11, 51, 'To ne reče sam od sebe, nego kao veliki svećenik one godine prorokova da Isus ima umrijeti za narod;');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (50, 11, 52, 'ali ne samo za narod nego i zato da raspršene sinove Božje skupi u jedno.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (50, 11, 53, 'Toga dana dakle odluče da ga ubiju.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (50, 11, 54, 'Zbog toga se Isus više nije javno kretao među Židovima, nego je odatle otišao u kraj blizu pustinje, u grad koji se zove Efrajim. Tu se zadržavao s učenicima.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (50, 11, 55, 'Bijaše blizu židovska Pasha i mnogi iz toga kraja uziđoše prije Pashe u Jeruzalem da se očiste.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (50, 11, 56, 'Iskahu dakle Isusa te se stojeći u Hramu zapitkivahu: \"Što vam se čini? Zar on ne kani doći na Blagdan?\"');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (50, 11, 57, 'A glavari svećenički i farizeji izdadoše naredbu: ako tko sazna gdje je, neka dojavi da ga uhvate.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (50, 12, 1, 'Šest dana prije Pashe dođe Isus u Betaniju gdje bijaše Lazar koga je Isus uskrisio od mrtvih.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (50, 12, 2, 'Ondje mu prirediše večeru. Marta posluživaše, a Lazar bijaše jedan od njegovih sustolnika.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (50, 12, 3, 'Tada Marija uzme libru prave dragocjene nardove pomasti, pomaže Isusu noge i otare ih svojom kosom. I sva se kuća napuni mirisom pomasti.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (50, 12, 4, 'Nato reče Juda Iškariotski, jedan od njegovih učenika, onaj koji ga je imao izdati:');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (50, 12, 5, '\"Zašto se ta pomast nije prodala za trista denara i razdala siromasima?\"');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (50, 12, 6, 'To ne reče zbog toga što mu bijaše stalo do siromaha, nego što bijaše kradljivac: kako je imao kesu, kradom je uzimao što se u nju stavljalo.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (50, 12, 7, 'Nato Isus odvrati: \"Pusti je! Neka to izvrši za dan mog ukopa!');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (50, 12, 8, 'Jer siromahe imate uvijek uza se, a mene nemate uvijek.\"');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (50, 12, 9, 'Silno mnoštvo Židova dozna da je Isus ondje pa se okupi, ne samo zbog Isusa, već i zato da vide Lazara kojega on bijaše uskrisio od mrtvih.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (50, 12, 10, 'A glavari svećenički odlučiše i Lazara ubiti');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (50, 12, 11, 'jer su zbog njega mnogi Židovi odlazili i vjerovali u Isusa.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (50, 12, 12, 'Kad je sutradan silan svijet koji dođe na Blagdan čuo da Isus dolazi u Jeruzalem,');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (50, 12, 13, 'uze palmove grančice i iziđe mu u susret. Vikahu: \"Hosana! Blagoslovljen Onaj koji dolazi u ime Gospodnje! Kralj Izraelov.\"');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (50, 12, 14, 'A Isus nađe magarčića i sjede na nj kao što je pisano:');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (50, 12, 15, 'Ne boj se, kćeri Sionska! Evo, kralj tvoj dolazi jašuć na mladetu magaričinu!');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (50, 12, 16, 'To učenici njegovi isprva ne razumješe. Ali pošto je Isus bio proslavljen, prisjetiše se da je to bilo o njemu napisano i da mu baš to učiniše.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (50, 12, 17, 'Mnoštvo koje bijaše s njime kad Lazara pozva iz groba i uskrisi od mrtvih pronosilo je svjedočanstvo o tome.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (50, 12, 18, 'Stoga mu je i izišao u susret silan svijet: pročulo se da je on učinio to znamenje.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (50, 12, 19, 'Farizeji nato rekoše među sobom: \"Vidite da ništa ne postižete. Eno, svijet ode za njim!\"');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (50, 12, 20, 'A među onima koji su se došli klanjati na Blagdan bijahu i neki Grci.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (50, 12, 21, 'Oni pristupe Filipu iz Betsaide galilejske pa ga zamole: \"Gospodine, htjeli bismo vidjeti Isusa.\"');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (50, 12, 22, 'Filip ode i kaže to Andriji pa Andrija i Filip odu i kažu Isusu.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (50, 12, 23, 'Isus im odgovori: \"Došao je čas da se proslavi Sin Čovječji.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (50, 12, 24, 'Zaista, zaista, kažem vam: ako pšenično zrno, pavši na zemlju, ne umre, ostaje samo; ako li umre, donosi obilat rod.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (50, 12, 25, 'Tko ljubi svoj život, izgubit će ga. A tko mrzi svoj život na ovome svijetu, sačuvat će ga za život vječni.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (50, 12, 26, 'Ako mi tko hoće služiti, neka ide za mnom. I gdje sam ja, ondje će biti i moj služitelj. Ako mi tko hoće služiti, počastit će ga moj Otac.\"');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (50, 12, 27, '\"Duša mi je sada potresena i što da kažem? Oče, izbavi me iz ovoga časa? No, zato dođoh u ovaj čas!');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (50, 12, 28, 'Oče, proslavi ime svoje!\" Uto dođe glas s neba: \"Proslavio sam i opet ću proslaviti!\"');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (50, 12, 29, 'Mnoštvo koje je ondje stajalo i slušalo govoraše: \"Zagrmjelo je!\" Drugi govorahu: \"Anđeo mu je zborio.\"');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (50, 12, 30, 'Isus na to reče: \"Ovaj glas nije bio poradi mene, nego poradi vas.\"');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (50, 12, 31, '\"Sada je sud ovomu svijetu, sada će knez ovoga svijeta biti izbačen.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (50, 12, 32, 'A ja kad budem uzdignut sa zemlje, sve ću privući k sebi.\"');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (50, 12, 33, 'To reče da označi kakvom će smrću umrijeti.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (50, 12, 34, 'Nato mu mnoštvo odgovori: \"Mi smo iz Zakona čuli da Krist ostaje zauvijek. Kako onda ti govoriš da Sin Čovječji treba da bude uzdignut? Tko je taj Sin Čovječji?\"');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (50, 12, 35, 'Isus im nato reče: \"Još je malo vremena svjetlost među vama. Hodite dok imate svjetlost da vas ne obuzme tama. Tko hodi u tami, ne zna kamo ide.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (50, 12, 36, 'Dok imate svjetlost, vjerujte u svjetlost da budete sinovi svjetlosti!\" To Isus doreče, a onda ode i sakri se od njih.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (50, 12, 37, 'Iako je Isus pred njima učinio tolika znamenja, oni ne povjerovaše u njega,');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (50, 12, 38, 'da se ispuni riječ koju kaza prorok Izaija: Gospodine! Tko povjerova našoj poruci? Kome li se otkri ruka Gospodnja?');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (50, 12, 39, 'Stoga i ne mogahu vjerovati, jer Izaija dalje kaže:');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (50, 12, 40, 'Zaslijepi im oči, stvrdnu srca; da očima ne vide, srcem ne razumiju te se ne obrate pa ih ozdravim.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (50, 12, 41, 'Reče to Izaija jer je vidio slavu njegovu te o njemu zborio.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (50, 12, 42, 'Ipak, mnogi su i od glavara vjerovali u njega, ali zbog farizeja nisu to priznavali: da ne budu izopćeni iz sinagoge.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (50, 12, 43, 'Jer više im je bilo do slave ljudske, nego do slave Božje.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (50, 12, 44, 'A Isus povika: \"Tko u mene vjeruje, ne vjeruje u mene, nego u onoga koji me posla;');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (50, 12, 45, 'i tko vidi mene, vidi onoga koji me posla.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (50, 12, 46, 'Ja - Svjetlost - dođoh na svijet da nijedan koji u mene vjeruje u tami ne ostane.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (50, 12, 47, 'I sluša li tko moje riječi, a ne čuva ih, ja ga ne sudim. Ja nisam došao suditi svijetu, nego svijet spasiti.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (50, 12, 48, 'Tko mene odbacuje i riječi mojih ne prima, ima svoga suca: riječ koju sam zborio - ona će mu suditi u posljednji dan.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (50, 12, 49, 'Jer nisam ja zborio sam od sebe, nego onaj koji me posla - Otac - on mi dade zapovijed što da kažem, što da zborim.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (50, 12, 50, 'I znam: zapovijed njegova jest život vječni. Što ja dakle zborim, tako zborim kako mi je rekao Otac.\"');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (50, 13, 1, 'Bijaše pred blagdan Pashe. Isus je znao da je došao njegov čas da prijeđe s ovoga svijeta Ocu, budući da je ljubio svoje, one u svijetu, do kraja ih je ljubio.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (50, 13, 2, 'I za večerom je đavao već bio ubacio u srce Judi Šimuna Iškariotskoga da ga izda.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (50, 13, 3, 'A Isus je znao da mu je Otac sve predao u ruke i da je od Boga izišao te da k Bogu ide pa');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (50, 13, 4, 'usta od večere, odloži haljine, uze ubrus i opasa se.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (50, 13, 5, 'Nalije zatim vodu u praonik i počne učenicima prati noge i otirati ih ubrusom kojim je bio opasan.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (50, 13, 6, 'Dođe tako do Šimuna Petra. A on će mu: \"Gospodine! Zar ti da meni pereš noge?\"');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (50, 13, 7, 'Odgovori mu Isus: \"Što ja činim, ti sada ne znaš, ali shvatit ćeš poslije.\"');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (50, 13, 8, 'Reče mu Petar: \"Nećeš mi prati nogu nikada!\" Isus mu odvrati: \"Ako te ne operem, nećeš imati dijela sa mnom.\"');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (50, 13, 9, 'Nato će mu Šimun Petar: \"Gospodine, onda ne samo noge, nego i ruke i glavu!\"');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (50, 13, 10, 'Kaže mu Isus: \"Tko je okupan, ne treba drugo da opere nego noge - i sav je čist! I vi ste čisti, ali ne svi!\"');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (50, 13, 11, 'Jer znao je tko će ga izdati. Stoga je i rekao: \"Niste svi čisti.\"');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (50, 13, 12, 'Kad im dakle opra noge, uze svoje haljine, opet sjede i reče im: \"Razumijete li što sam vam učinio?');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (50, 13, 13, 'Vi me zovete Učiteljem i Gospodinom. Pravo velite jer to i jesam!');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (50, 13, 14, 'Ako dakle ja - Gospodin i Učitelj - vama oprah noge, treba da i vi jedni drugima perete noge.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (50, 13, 15, 'Primjer sam vam dao da i vi činite kao što ja vama učinih.\"');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (50, 13, 16, 'Zaista, zaista, kažem vam: nije sluga veći od gospodara niti poslanik od onoga koji ga posla.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (50, 13, 17, 'Ako to znate, blago vama budete li tako i činili!\"');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (50, 13, 18, '\"Ne govorim o svima vama! Ja znam koje izabrah! Ali - neka se ispuni Pismo: Koji blaguje kruh moj, petu na me podiže.\"');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (50, 13, 19, '\"Već vam sada kažem, prije negoli se dogodi, da kad se dogodi vjerujete da Ja jesam.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (50, 13, 20, 'Zaista, zaista, kažem vam: Tko primi onoga kojega ja šaljem, mene prima. A tko mene primi, prima onoga koji je mene poslao.\"');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (50, 13, 21, 'Rekavši to, potresen u duhu Isus posvjedoči: \"Zaista, zaista, kažem vam: jedan će me od vas izdati!\"');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (50, 13, 22, 'Učenici se zgledahu među sobom u nedoumici o kome to govori.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (50, 13, 23, 'A jedan od njegovih učenika - onaj kojega je Isus ljubio - bijaše za stolom Isusu do krila.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (50, 13, 24, 'Šimun Petar dade mu znak i reče: \"Pitaj tko je taj o kome govori.\"');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (50, 13, 25, 'Ovaj se privine Isusu uz prsa i upita: \"Gospodine, tko je taj?\"');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (50, 13, 26, 'Isus odgovori: \"Onaj je kome ja dadnem umočen zalogaj.\"');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (50, 13, 27, 'Tada umoči zalogaj, uze ga i dade Judi Šimuna Iškariotskoga. Nakon zalogaja uđe u nj Sotona. Nato mu Isus reče: \"Što činiš, učini brzo!\"');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (50, 13, 28, 'Nijedan od sustolnika nije razumio zašto mu je to rekao.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (50, 13, 29, 'Budući da je Juda imao kesu, neki su mislili da mu je Isus rekao: \"Kupi što nam treba za blagdan!\" - ili neka poda nešto siromasima.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (50, 13, 30, 'On dakle uzme zalogaj i odmah iziđe. A bijaše noć.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (50, 13, 31, 'Pošto Juda iziđe, reče Isus: \"Sada je proslavljen Sin Čovječji i Bog se proslavio u njemu!');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (50, 13, 32, 'Ako se Bog proslavio u njemu, i njega će Bog proslaviti u sebi, i uskoro će ga proslaviti!');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (50, 13, 33, 'Dječice, još sam malo s vama. Tražit ćete me, ali kao što rekoh Židovima, kažem sada i vama: kamo ja odlazim, vi ne možete doći.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (50, 13, 34, 'Zapovijed vam novu dajem: ljubite jedni druge; kao što sam ja ljubio vas tako i vi ljubite jedni druge.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (50, 13, 35, 'Po ovom će svi znati da ste moji učenici: ako budete imali ljubavi jedni za druge.\"');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (50, 13, 36, 'Kaže mu Šimun Petar: \"Gospodine, kamo to odlaziš?\" Isus mu odgovori: \"Kamo ja odlazim, ti zasad ne možeš poći za mnom. No poći ćeš poslije.\"');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (50, 13, 37, 'Nato će mu Petar: \"Gospodine, a zašto sada ne bih mogao poći za tobom? Život ću svoj položiti za tebe!\"');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (50, 13, 38, 'Odgovori Isus: \"Život ćeš svoj položiti za mene? Zaista, zaista, kažem ti: Pijetao neće zapjevati dok me triput ne zatajiš.\"');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (50, 14, 1, '\"Neka se ne uznemiruje srce vaše! Vjerujte u Boga i u mene vjerujte!');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (50, 14, 2, 'U domu Oca mojega ima mnogo stanova. Da nema, zar bih vam rekao: \'Idem pripraviti vam mjesto\'?');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (50, 14, 3, 'Kad odem i pripravim vam mjesto, ponovno ću doći i uzeti vas k sebi da i vi budete gdje sam ja.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (50, 14, 4, 'A kamo ja odlazim, znate put.\"');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (50, 14, 5, 'Reče mu Toma: \"Gospodine, ne znamo kamo odlaziš. Kako onda možemo put znati?\"');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (50, 14, 6, 'Odgovori mu Isus: \"Ja sam Put i Istina i Život: nitko ne dolazi Ocu osim po meni.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (50, 14, 7, 'Da ste upoznali mene, i Oca biste moga upoznali. Od sada ga i poznajete i vidjeli ste ga.\"');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (50, 14, 8, 'Kaže mu Filip: \"Gospodine, pokaži nam Oca i dosta nam je!\"');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (50, 14, 9, 'Nato će mu Isus: \"Filipe, toliko sam vremena s vama i još me ne poznaš?\" \"Tko je vidio mene, vidio je i Oca. Kako ti onda kažeš: \'Pokaži nam Oca\'?');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (50, 14, 10, 'Ne vjeruješ li da sam ja u Ocu i Otac u meni? Riječi koje vam govorim, od sebe ne govorim: Otac koji prebiva u meni čini djela svoja.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (50, 14, 11, 'Vjerujte mi: ja sam u Ocu i Otac u meni. Ako ne inače, zbog samih djela vjerujte.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (50, 14, 12, 'Zaista, zaista, kažem vam: Tko vjeruje u mene, činit će djela koja ja činim; da veća će od njih činiti jer ja odlazim Ocu.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (50, 14, 13, 'I što god zaištete u moje ime, učinit ću, da se proslavi Otac u Sinu.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (50, 14, 14, 'Ako me što zaištete u moje ime, učinit ću.\"');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (50, 14, 15, '\"Ako me ljubite, zapovijedi ćete moje čuvati.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (50, 14, 16, 'I ja ću moliti Oca i on će vam dati drugoga Branitelja da bude s vama zauvijek:');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (50, 14, 17, 'Duha Istine, kojega svijet ne može primiti jer ga ne vidi i ne poznaje. Vi ga poznajete jer kod vas ostaje i u vama je.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (50, 14, 18, 'Neću vas ostaviti kao siročad; doći ću k vama.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (50, 14, 19, 'Još malo i svijet me više neće vidjeti, no vi ćete me vidjeti jer ja živim i vi ćete živjeti.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (50, 14, 20, 'U onaj ćete dan spoznati da sam ja u Ocu svom i vi u meni i ja u vama.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (50, 14, 21, 'Tko ima moje zapovijedi i čuva ih, taj me ljubi; a tko mene ljubi, njega će ljubiti Otac moj, i ja ću ljubiti njega i njemu se očitovati.\"');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (50, 14, 22, 'Kaže mu Juda, ne Iškariotski: \"Gospodine, kako to da ćeš se očitovati nama, a ne svijetu?\"');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (50, 14, 23, 'Odgovori mu Isus: \"Ako me tko ljubi, čuvat će moju riječ pa će i Otac moj ljubiti njega i k njemu ćemo doći i kod njega se nastaniti.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (50, 14, 24, 'Tko mene ne ljubi, riječi mojih ne čuva. A riječ koju slušate nije moja, nego Oca koji me posla.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (50, 14, 25, 'To sam vam govorio dok sam boravio s vama.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (50, 14, 26, 'Branitelj - Duh Sveti, koga će Otac poslati u moje ime, poučavat će vas o svemu i dozivati vam u pamet sve što vam ja rekoh.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (50, 14, 27, 'Mir vam ostavljam, mir vam svoj dajem. Dajem vam ga, ali ne kao što svijet daje. Neka se ne uznemiruje vaše srce i neka se ne straši.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (50, 14, 28, 'Čuli ste, rekoh vam: \'Odlazim i vraćam se k vama.\' Kad biste me ljubili, radovali biste se što idem Ocu jer Otac je veći od mene.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (50, 14, 29, 'Kazao sam vam to sada, prije negoli se dogodi, da vjerujete kad se dogodi.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (50, 14, 30, 'Neću više s vama mnogo govoriti jer dolazi knez svijeta. Protiv mene ne može on ništa.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (50, 14, 31, 'Ali neka svijet upozna da ja ljubim Oca i da tako činim kako mi je zapovjedio Otac. Ustanite, pođimo odavde!\"');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (50, 15, 1, '\"Ja sam istinski trs, a Otac moj - vinogradar.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (50, 15, 2, 'Svaku lozu na meni koja ne donosi roda on siječe, a svaku koja rod donosi čisti da više roda donese.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (50, 15, 3, 'Vi ste već očišćeni po riječi koju sam vam zborio.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (50, 15, 4, 'Ostanite u meni i ja u vama. Kao što loza ne može donijeti roda sama od sebe, ako ne ostane na trsu, tako ni vi ako ne ostanete u meni.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (50, 15, 5, 'Ja sam trs, vi loze. Tko ostaje u meni i ja u njemu, taj donosi mnogo roda. Uistinu, bez mene ne možete učiniti ništa.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (50, 15, 6, 'Ako tko ne ostane u meni, izbace ga kao lozu i usahne. Takve onda skupe i bace u oganj te gore.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (50, 15, 7, 'Ako ostanete u meni i riječi moje ako ostanu u vama, što god hoćete, ištite i bit će vam.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (50, 15, 8, 'Ovim se proslavlja Otac moj: da donosite mnogo roda i da budete moji učenici.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (50, 15, 9, 'Kao što je Otac ljubio mene tako sam i ja ljubio vas; ostanite u mojoj ljubavi.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (50, 15, 10, 'Budete li čuvali moje zapovijedi, ostat ćete u mojoj ljubavi; kao što sam i ja čuvao zapovijedi Oca svoga te ostajem u ljubavi njegovoj.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (50, 15, 11, 'To sam vam govorio da moja radost bude u vama i da vaša radost bude potpuna.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (50, 15, 12, 'Ovo je moja zapovijed: ljubite jedni druge kao što sam ja vas ljubio!');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (50, 15, 13, 'Veće ljubavi nitko nema od ove: da tko život svoj položi za svoje prijatelje.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (50, 15, 14, 'Vi ste prijatelji moji ako činite što vam zapovijedam.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (50, 15, 15, 'Više vas ne zovem slugama jer sluga ne zna što radi njegov gospodar; vas sam nazvao prijateljima jer vam priopćih sve što sam čuo od Oca svoga.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (50, 15, 16, 'Ne izabraste vi mene, nego ja izabrah vas i postavih vas da idete i rod donosite i rod vaš da ostane te vam Otac dadne što ga god zaištete u moje ime.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (50, 15, 17, 'Ovo vam zapovijedam: da ljubite jedni druge.\"');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (50, 15, 18, '\"Ako vas svijet mrzi, znajte da je mene mrzio prije nego vas.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (50, 15, 19, 'Kad biste bili od svijeta, svijet bi svoje ljubio; no budući da niste od svijeta, nego sam vas ja izabrao iz svijeta, zbog toga vas svijet mrzi.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (50, 15, 20, 'Sjećajte se riječi koju vam rekoh: \'Nije sluga veći od svoga gospodara.\' Ako su mene progonili, i vas će progoniti; ako su moju riječ čuvali, da vašu će čuvati.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (50, 15, 21, 'A sve će to poduzimati protiv vas poradi imena moga jer ne znaju onoga koji mene posla.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (50, 15, 22, 'Da nisam došao i da im nisam govorio, ne bi imali grijeha; no sada nemaju izgovora za svoj grijeh.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (50, 15, 23, 'Tko mene mrzi, mrzi i Oca mojega.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (50, 15, 24, 'Da nisam učinio među njima djela kojih nitko drugi ne čini, ne bi imali grijeha; a sada vidješe pa ipak zamrziše i mene i Oca mojega.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (50, 15, 25, 'No neka se ispuni riječ napisana u njihovu Zakonu: Mrze me nizašto.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (50, 15, 26, 'A kada dođe Branitelj koga ću vam poslati od Oca - Duh Istine koji od Oca izlazi - on će svjedočiti za mene.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (50, 15, 27, 'I vi ćete svjedočiti jer ste od početka sa mnom.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (50, 16, 1, 'To sam vam govorio da se ne sablaznite.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (50, 16, 2, 'Izopćavat će vas iz sinagoga. Štoviše, dolazi čas kad će svaki koji vas ubije misliti da služi Bogu.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (50, 16, 3, 'A to će činiti jer ne upoznaše ni Oca ni mene.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (50, 16, 4, 'Govorio sam vam ovo da se, kada dođe vrijeme, sjetite da sam vam rekao.\" \"S početka vam ne rekoh ovo jer bijah s vama.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (50, 16, 5, 'A sada odlazim k onome koji me posla i nitko me od vas ne pita: \'Kamo ideš?\'');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (50, 16, 6, 'Naprotiv, žalošću se ispunilo vaše srce što vam ovo kazah.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (50, 16, 7, 'No kažem vam istinu: bolje je za vas da ja odem: jer ako ne odem, Branitelj neće doći k vama; ako pak odem, poslat ću ga k vama.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (50, 16, 8, 'A kad on dođe, pokazat će svijetu što je grijeh, što li pravednost, a što osuda:');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (50, 16, 9, 'grijeh je što ne vjeruju u mene;');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (50, 16, 10, 'pravednost - što odlazim k Ocu i više me ne vidite;');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (50, 16, 11, 'a osuda - što je knez ovoga svijeta osuđen.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (50, 16, 12, 'Još vam mnogo imam kazati, ali sada ne možete nositi.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (50, 16, 13, 'No kada dođe on - Duh Istine - upućivat će vas u svu istinu; jer neće govoriti sam od sebe, nego će govoriti što čuje i navješćivat će vam ono što dolazi.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (50, 16, 14, 'On će mene proslavljati jer će od mojega uzimati i navješćivati vama.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (50, 16, 15, 'Sve što ima Otac, moje je. Zbog toga vam rekoh: od mojega uzima i - navješćivat će vama.\"');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (50, 16, 16, '\"Malo, i više me nećete vidjeti; i opet malo, pa ćete me vidjeti.\"');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (50, 16, 17, 'Nato se neki od učenika zapitkivahu: \"Što je to što nam kaže: \'Malo, i nećete me vidjeti, i opet malo, pa ćete me vidjeti\' i \'Odlazim Ocu\'?\"');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (50, 16, 18, 'Govorahu dakle: \"Što je to što kaže \'Malo\'? Ne znamo što govori.\"');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (50, 16, 19, 'Isus spozna da su ga htjeli pitati pa im reče: \"Pitate se među sobom o tome što kazah: \'Malo, i nećete me vidjeti; i opet malo, pa ćete me vidjeti\'?');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (50, 16, 20, 'Zaista, zaista, kažem vam: vi ćete plakati i jaukati, a svijet će se veseliti. Vi ćete se žalostiti, ali žalost će se vaša okrenuti u radost.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (50, 16, 21, 'Žena kad rađa, žalosna je jer je došao njezin čas; ali kad rodi djetešce, ne spominje se više muke od radosti što se čovjek rodio na svijet.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (50, 16, 22, 'Tako dakle i vi: sad ste u žalosti, no ja ću vas opet vidjeti; i srce će vam se radovati i radosti vaše nitko vam oteti neće.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (50, 16, 23, 'U onaj me dan nećete ništa više pitati. Zaista, zaista, kažem vam: što god zaištete u Oca, dat će vam u moje ime.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (50, 16, 24, 'Dosad niste iskali ništa u moje ime. Ištite i primit ćete da radost vaša bude potpuna!\"');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (50, 16, 25, '\"To sam vam govorio u poredbama. Dolazi čas kad vam više neću govoriti u poredbama, nego ću vam otvoreno navješćivati Oca.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (50, 16, 26, 'U onaj dan iskat ćete u moje ime i ne velim vam da ću ja moliti Oca za vas.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (50, 16, 27, 'Ta sam vas Otac ljubi jer vi ste mene ljubili i vjerovali da sam ja od Boga izišao.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (50, 16, 28, 'Izišao sam od Oca i došao na svijet. Opet ostavljam svijet i odlazim Ocu.\"');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (50, 16, 29, 'Kažu mu učenici: \"Evo, sad otvoreno zboriš i nikakvon se poredbom ne služiš.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (50, 16, 30, 'Sada znamo da sve znaš i ne treba da te tko pita. Stoga vjerujemo da si izišao od Boga.\"');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (50, 16, 31, 'Odgovori im Isus: \"Sada vjerujete?');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (50, 16, 32, 'Evo dolazi čas i već je došao: raspršit ćete se svaki na svoju stranu i mene ostaviti sama. No ja nisam sam jer Otac je sa mnom.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (50, 16, 33, 'To vam rekoh da u meni mir imate. U svijetu imate muku, ali hrabri budite - ja sam pobijedio svijet!\"');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (50, 17, 1, 'To Isus doreče, a onda podiže oči k nebu i progovori: \"Oče, došao je čas: proslavi Sina svoga da Sin proslavi tebe');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (50, 17, 2, 'i da vlašću koju si mu dao nad svakim tijelom dade život vječni svima koje si mu dao.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (50, 17, 3, 'A ovo je život vječni: da upoznaju tebe, jedinoga istinskog Boga, i koga si poslao - Isusa Krista.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (50, 17, 4, 'Ja tebe proslavih na zemlji dovršivši djelo koje si mi dao izvršiti.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (50, 17, 5, 'A sada ti, Oče, proslavi mene kod sebe onom slavom koju imadoh kod tebe prije negoli je svijeta bilo.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (50, 17, 6, 'Objavio sam ime tvoje ljudima koje si mi dao od svijeta. Tvoji bijahu, a ti ih meni dade i riječ su tvoju sačuvali.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (50, 17, 7, 'Sad upoznaše da je od tebe sve što si mi dao');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (50, 17, 8, 'jer riječi koje si mi dao njima predadoh i oni ih primiše i uistinu spoznaše da sam od tebe izišao te povjerovaše da si me ti poslao.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (50, 17, 9, 'Ja za njih molim; ne molim za svijet, nego za one koje si mi dao jer su tvoji.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (50, 17, 10, 'I sve moje tvoje je, i tvoje moje, i ja se proslavih u njima.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (50, 17, 11, 'Ja više nisam u svijetu, no oni su u svijetu, a ja idem k tebi. Oče sveti, sačuvaj ih u svom imenu koje si mi dao: da budu jedno kao i mi.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (50, 17, 12, 'Dok sam ja bio s njima, ja sam ih čuvao u tvom imenu, njih koje si mi dao; i štitio ih, te nijedan od njih ne propade osim sina propasti, da se Pismo ispuni.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (50, 17, 13, 'A sada k tebi idem i ovo govorim u svijetu da imaju puninu moje radosti u sebi.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (50, 17, 14, 'Ja sam im predao tvoju riječ, a svijet ih zamrzi jer nisu od svijeta kao što ni ja nisam od svijeta.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (50, 17, 15, 'Ne molim te da ih uzmeš sa svijeta, nego da ih očuvaš od Zloga.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (50, 17, 16, 'Oni nisu od svijeta kao što ni ja nisam od svijeta.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (50, 17, 17, 'Posveti ih u istini: tvoja je riječ istina.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (50, 17, 18, 'Kao što ti mene posla u svijet tako i ja poslah njih u svijet.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (50, 17, 19, 'I za njih posvećujem samog sebe da i oni budu posvećeni u istini.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (50, 17, 20, 'Ne molim samo za ove nego i za one koji će na njihovu riječ vjerovati u mene:');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (50, 17, 21, 'da svi budu jedno kao što ti, Oče, u meni i ja u tebi, neka i oni u nama budu da svijet uzvjeruje da si me ti poslao.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (50, 17, 22, 'I slavu koju si ti dao meni ja dadoh njima: da budu jedno kao što smo mi jedno -');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (50, 17, 23, 'ja u njima i ti u meni, da tako budu savršeno jedno da svijet upozna da si me ti poslao i ljubio njih kao što si mene ljubio.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (50, 17, 24, 'Oče, hoću da i oni koje si mi dao budu gdje sam ja, da i oni budu sa mnom: da gledaju moju slavu, slavu koju si mi dao jer si me ljubio prije postanka svijeta.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (50, 17, 25, 'Oče pravedni, svijet te nije upoznao, ja te upoznah; a i ovi upoznaše da si me ti poslao.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (50, 17, 26, 'I njima sam očitovao tvoje ime, i još ću očitovati, da ljubav kojom si ti mene ljubio bude u njima - i ja u njima.\"');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (50, 18, 1, 'To rekavši, zaputi se Isus sa svojim učenicima na drugu stranu potoka Cedrona. Ondje bijaše vrt u koji uđe Isus i njegovi učenici.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (50, 18, 2, 'A poznavaše to mjesto i Juda, njegov izdajica, jer se Isus tu često sastajao sa svojim učenicima.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (50, 18, 3, 'Juda onda uze četu i od svećeničkih glavara i farizeja sluge te dođe onamo sa zubljama, svjetiljkama i oružjem.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (50, 18, 4, 'Znajući sve što će s njim biti, istupi Isus naprijed te ih upita: \"Koga tražite?\"');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (50, 18, 5, 'Odgovore mu: \"Isusa Nazarećanina.\" Reče im Isus: \"Ja sam!\" A stajaše s njima i Juda, njegov izdajica.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (50, 18, 6, 'Kad im dakle reče: \"Ja sam!\" - oni ustuknuše i popadaše na zemlju.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (50, 18, 7, 'Ponovno ih tada upita: \"Koga tražite?\" Oni odgovore: \"Isusa Nazarećanina.\"');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (50, 18, 8, 'Isus odvrati: \"Rekoh vam da sam ja. Ako dakle mene tražite, pustite ove da odu\" -');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (50, 18, 9, 'da se ispuni riječ koju reče: \"Ne izgubih ni jednoga od onih koje si mi dao.\"');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (50, 18, 10, 'A Šimun Petar isuče mač koji je imao uza se pa udari slugu velikoga svećenika i odsiječe mu desno uho. Sluga se zvao Malho.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (50, 18, 11, 'Nato Isus reče Petru: \"Djeni mač u korice! Čašu koju mi dade Otac zar da ne pijem?\"');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (50, 18, 12, 'Tada četa, zapovjednik i židovski sluge uhvatiše Isusa te ga svezaše.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (50, 18, 13, 'Odvedoše ga najprije Ani jer on bijaše tast Kajfe, velikoga svećenika one godine.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (50, 18, 14, 'Kajfa pak ono svjetova Židove: \"Bolje da jedan čovjek umre za narod.\"');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (50, 18, 15, 'Za Isusom su išli Šimun Petar i drugi učenik. Taj učenik bijaše poznat s velikim svećenikom pa s Isusom uđe u dvorište velikoga svećenika.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (50, 18, 16, 'Petar osta vani kod vrata. Tada taj drugi učenik, znanac velikoga svećenika, iziđe i reče vratarici te uvede Petra.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (50, 18, 17, 'Nato će sluškinja, vratarica, Petru: \"Da nisi i ti od učenika toga čovjeka?\" On odvrati: \"Nisam!\"');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (50, 18, 18, 'A stajahu ondje sluge i stražari, raspirivahu žeravicu jer bijaše studeno i grijahu se. S njima je stajao i Petar i grijao se.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (50, 18, 19, 'Veliki svećenik zapita Isusa o njegovim učenicima i o njegovu nauku.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (50, 18, 20, 'Odgovori mu Isus: \"Ja sam javno govorio svijetu. Uvijek sam naučavao u sinagogi i u Hramu gdje se skupljaju svi Židovi. Ništa nisam u tajnosti govorio.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (50, 18, 21, 'Zašto mene pitaš? Pitaj one koji su slušali što sam im govorio. Oni eto znaju što sam govorio.\"');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (50, 18, 22, 'Na te njegove riječi jedan od nazočnih slugu pljusne Isusa govoreći: \"Tako li odgovaraš velikom svećeniku?\"');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (50, 18, 23, 'Odgovori mu Isus: \"Ako sam krivo rekao, dokaži da je krivo! Ako li pravo, zašto me udaraš?\"');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (50, 18, 24, 'Ana ga zatim posla svezana Kajfi, velikom svećeniku.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (50, 18, 25, 'Šimun Petar stajao je ondje i grijao se. Rekoše mu: \"Da nisi i ti od njegovih učenika?\" On zanijeka: \"Nisam!\"');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (50, 18, 26, 'Nato će jedan od slugu velikog svećenika, rođak onoga komu je Petar bio odsjekao uho: \"Nisam li te ja vidio u vrtu s njime?\"');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (50, 18, 27, 'I Petar opet zanijeka, a pijetao odmah zapjeva.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (50, 18, 28, 'Nato odvedoše Isusa od Kajfe u dvor upraviteljev. Bilo je rano jutro. I oni ne uđoše da se ne okaljaju, već da mognu blagovati pashu.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (50, 18, 29, 'Pilat tada iziđe pred njih i upita: \"Kakvu tužbu iznosite protiv ovoga čovjeka?\"');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (50, 18, 30, 'Odgovore mu: \"Kad on ne bi bio zločinac, ne bismo ga predali tebi.\"');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (50, 18, 31, 'Reče im nato Pilat: \"Uzmite ga vi i sudite mu po svom zakonu.\" Odgovoriše mu Židovi: \"Nama nije dopušteno nikoga pogubiti\" -');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (50, 18, 32, 'da se ispuni riječ Isusova kojom je označio kakvom mu je smrću umrijeti.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (50, 18, 33, 'Nato Pilat uđe opet u dvor, pozove Isusa i upita ga: \"Ti li si židovski kralj?\"');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (50, 18, 34, 'Isus odgovori: \"Govoriš li ti to sam od sebe ili ti to drugi rekoše o meni?\"');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (50, 18, 35, 'Pilat odvrati: \"Zar sam ja Židov? Tvoj narod i glavari svećenički predadoše te meni. Što si učinio?\"');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (50, 18, 36, 'Odgovori Isus: \"Kraljevstvo moje nije od ovoga svijeta. Kad bi moje kraljevstvo bilo od ovoga svijeta, moje bi se sluge borile da ne budem predan Židovima. Ali kraljevstvo moje nije odavde.\"');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (50, 18, 37, 'Nato mu reče Pilat: \"Ti si dakle kralj?\" Isus odgovori: \"Ti kažeš: ja sam kralj. Ja sam se zato rodio i došao na svijet da svjedočim za istinu. Tko je god od istine, sluša moj glas.\"');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (50, 18, 38, 'Reče mu Pilat: \"Što je istina?\"');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (50, 18, 39, 'Rekavši to, opet iziđe pred Židove i reče im: \"Ja ne nalazim na njemu nikakve krivice. A u vas je običaj da vam o Pashi nekoga pustim. Hoćete li dakle da vam pustim kralja židovskoga?\"');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (50, 18, 40, 'Povikaše nato opet: \"Ne toga, nego Barabu!\" A Baraba bijaše razbojnik.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (50, 19, 1, 'Tada Pilat uze i izbičeva Isusa.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (50, 19, 2, 'A vojnici spletoše vijenac od trnja i staviše mu ga na glavu; i zaogrnuše ga grimiznim plaštem.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (50, 19, 3, 'I prilazili su mu i govorili: \"Zdravo kralju židovski!\" I pljuskali su ga.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (50, 19, 4, 'A Pilat ponovno iziđe i reče im: \"Evo vam ga izvodim da znate: ne nalazim na njemu nikakve krivice.\"');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (50, 19, 5, 'Iziđe tada Isus s trnovim vijencem, u grimiznom plaštu. A Pilat im kaže: \"Evo čovjeka!\"');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (50, 19, 6, 'I kad ga ugledaše glavari svećenički i sluge, povikaše: \"Raspni, raspni!\" Kaže im Pilat: \"Uzmite ga vi i raspnite jer ja ne nalazim na njemu krivice.\"');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (50, 19, 7, 'Odgovoriše mu Židovi: \"Mi imamo Zakon i po Zakonu on mora umrijeti jer se pravio Sinom Božjim.\"');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (50, 19, 8, 'Kad je Pilat čuo te riječi, još se više prestraši');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (50, 19, 9, 'pa ponovno uđe u dvor i kaže Isusu: \"Odakle si ti?\" No Isus mu ne dade odgovora.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (50, 19, 10, 'Tada mu Pilat reče: \"Zar meni ne odgovaraš? Ne znaš li da imam vlast da te pustim i da imam vlast da te razapnem?\"');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (50, 19, 11, 'Odgovori mu Isus: \"Ne bi imao nada mnom nikakve vlasti da ti nije dano odozgor. Zbog toga ima veći grijeh onaj koji me predao tebi.\"');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (50, 19, 12, 'Od tada ga je Pilat nastojao pustiti. No Židovi vikahu: \"Ako ovoga pustiš, nisi prijatelj caru. Tko se god pravi kraljem, protivi se caru.\"');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (50, 19, 13, 'Čuvši te riječi, Pilat izvede Isusa i posadi na sudačku stolicu na mjestu koje se zove Litostrotos - Pločnik, hebrejski Gabata -');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (50, 19, 14, 'a bijaše upravo priprava za Pashu, oko šeste ure - i kaže Židovima: \"Evo kralja vašega!\"');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (50, 19, 15, 'Oni na to povikaše: \"Ukloni! Ukloni! Raspni ga!\" Kaže im Pilat: \"Zar kralja vašega da razapnem?\" Odgovoriše glavari svećenički: \"Mi nemamo kralja osim cara!\"');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (50, 19, 16, 'Tada im ga preda da se razapne. Uzeše dakle Isusa.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (50, 19, 17, 'I noseći svoj križ, iziđe on na mjesto zvano Lubanjsko, hebrejski Golgota.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (50, 19, 18, 'Ondje ga razapeše, a s njim i drugu dvojicu, s jedne i druge strane, a Isusa u sredini.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (50, 19, 19, 'A napisa Pilat i natpis te ga postavi na križ. Bilo je napisano: \"Isus Nazarećanin, kralj židovski.\"');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (50, 19, 20, 'Taj su natpis čitali mnogi Židovi jer mjesto gdje je Isus bio raspet bijaše blizu grada, a bilo je napisano hebrejski, latinski i grčki.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (50, 19, 21, 'Nato glavari svećenički rekoše Pilatu: \"Nemoj pisati: \'Kralj židovski\', nego da je on rekao: \'Kralj sam židovski.\'\"');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (50, 19, 22, 'Pilat odgovori: \"Što napisah, napisah!\"');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (50, 19, 23, 'Vojnici pak, pošto razapeše Isusa, uzeše njegove haljine i razdijeliše ih na četiri dijela - svakom vojniku po dio. A uzeše i donju haljinu, koja bijaše nešivena, otkana u komadu odozgor dodolje.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (50, 19, 24, 'Rekoše zato među sobom: \"Ne derimo je, nego bacimo za nju kocku pa komu dopane\" - da se ispuni Pismo koje veli: Razdijeliše među se haljine moje, za odjeću moju baciše kocku. I vojnici učiniše tako.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (50, 19, 25, 'Uz križ su Isusov stajale majka njegova, zatim sestra njegove majke, Marija Kleofina, i Marija Magdalena.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (50, 19, 26, 'Kad Isus vidje majku i kraj nje učenika kojega je ljubio, reče majci: \"Ženo! Evo ti sina!\" Zatim reče učeniku: \"Evo ti majke!\"');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (50, 19, 27, 'I od toga časa uze je učenik k sebi.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (50, 19, 28, 'Nakon toga, kako je Isus znao da je sve dovršeno, da bi se ispunilo Pismo, reče: \"Žedan sam.\"');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (50, 19, 29, 'A ondje je stajala posuda puna octa. I natakoše na izopovu trsku spužvu natopljenu octom pa je primakoše njegovim ustima.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (50, 19, 30, 'Čim Isus uze ocat, reče: \"Dovršeno je!\" I prignuvši glavu, preda duh.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (50, 19, 31, 'Kako bijaše Priprava, da ne bi tijela ostala na križu subotom, jer velik je dan bio one subote, Židovi zamoliše Pilata da se raspetima prebiju golijeni i da se skinu.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (50, 19, 32, 'Dođoše dakle vojnici i prebiše golijeni prvomu i drugomu koji su s Isusom bili raspeti.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (50, 19, 33, 'Kada dođoše do Isusa i vidješe da je već umro, ne prebiše mu golijeni,');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (50, 19, 34, 'nego mu jedan od vojnika kopljem probode bok i odmah poteče krv i voda.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (50, 19, 35, 'Onaj koji je vidio svjedoči i istinito je svjedočanstvo njegovo. On zna da govori istinu da i vi vjerujete');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (50, 19, 36, 'jer se to dogodilo da se ispuni Pismo: Nijedna mu se kost neće slomiti.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (50, 19, 37, 'I drugo opet Pismo veli: Gledat će onoga koga su proboli.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (50, 19, 38, 'Nakon toga Josip iz Arimateje, koji je - kriomice, u strahu od Židova - bio učenik Isusov, zamoli Pilata da smije skinuti tijelo Isusovo. I dopusti mu Pilat. Josip dakle ode i skine Isusovo tijelo.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (50, 19, 39, 'A dođe i Nikodem - koji je ono prije bio došao Isusu noću - i donese sa sobom oko sto libara smjese smirne i aloja.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (50, 19, 40, 'Uzmu dakle tijelo Isusovo i poviju ga u povoje s miomirisima, kako je u Židova običaj za ukop.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (50, 19, 41, 'A na mjestu gdje je Isus bio raspet bijaše vrt i u vrtu nov grob u koji još nitko ne bijaše položen.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (50, 19, 42, 'Ondje dakle zbog židovske Priprave, jer grob bijaše blizu, polože Isusa.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (50, 20, 1, 'Prvog dana u tjednu rano ujutro, još za mraka, dođe Marija Magdalena na grob i opazi da je kamen s groba dignut.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (50, 20, 2, 'Otrči stoga i dođe k Šimunu Petru i drugom učeniku, kojega je Isus ljubio, pa im reče: \"Uzeše Gospodina iz groba i ne znamo gdje ga staviše.\"');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (50, 20, 3, 'Uputiše se onda Petar i onaj drugi učenik i dođoše na grob.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (50, 20, 4, 'Trčahu obojica zajedno, ali onaj drugi učenik prestignu Petra i stiže prvi na grob.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (50, 20, 5, 'Sagne se i opazi povoje gdje leže, ali ne uđe.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (50, 20, 6, 'Uto dođe i Šimun Petar koji je išao za njim i uđe u grob. Ugleda povoje gdje leže');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (50, 20, 7, 'i ubrus koji bijaše na glavi Isusovoj, ali nije bio uz povoje, nego napose svijen na jednome mjestu.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (50, 20, 8, 'Tada uđe i onaj drugi učenik koji prvi stiže na grob i vidje i povjerova.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (50, 20, 9, 'Jer oni još ne upoznaše Pisma da Isus treba da ustane od mrtvih.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (50, 20, 10, 'Potom se učenici vratiše kući.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (50, 20, 11, 'A Marija je stajala vani kod groba i plakala.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (50, 20, 12, 'Zaplakana zaviri u grob i ugleda dva anđela u bjelini kako sjede na mjestu gdje je ležalo tijelo Isusovo - jedan kod glave, drugi kod nogu.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (50, 20, 13, 'Kažu joj oni: \"Ženo, što plačeš?\" Odgovori im: \"Uzeše Gospodina mojega i ne znam gdje ga staviše.\"');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (50, 20, 14, 'Rekavši to, obazre se i ugleda Isusa gdje stoji, ali nije znala da je to Isus.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (50, 20, 15, 'Kaže joj Isus: \"Ženo, što plačeš? Koga tražiš?\" Misleći da je to vrtlar, reče mu ona: \"Gospodine, ako si ga ti odnio, reci mi gdje si ga stavio i ja ću ga uzeti.\"');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (50, 20, 16, 'Kaže joj Isus: \"Marijo!\" Ona se okrene te će mu hebrejski: \"Rabbuni!\" - što znači: \"Učitelju!\"');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (50, 20, 17, 'Kaže joj Isus: \"Ne zadržavaj se sa mnom jer još ne uziđoh Ocu, nego idi mojoj braći i javi im: Uzlazim Ocu svomu i Ocu vašemu, Bogu svomu i Bogu vašemu.\"');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (50, 20, 18, 'Ode dakle Marija Magdalena i navijesti učenicima: \"Vidjela sam Gospodina i on mi je to rekao.\"');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (50, 20, 19, 'I uvečer toga istog dana, prvog u tjednu, dok su učenici u strahu od Židova bili zatvorili vrata, dođe Isus, stane u sredinu i reče im: \"Mir vama!\"');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (50, 20, 20, 'To rekavši, pokaza im svoje ruke i bok. I obradovaše se učenici vidjevši Gospodina.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (50, 20, 21, 'Isus im stoga ponovno reče: \"Mir vama! Kao što mene posla Otac i ja šaljem vas.\"');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (50, 20, 22, 'To rekavši, dahne u njih i kaže im: \"Primite Duha Svetoga.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (50, 20, 23, 'Kojima otpustite grijehe, otpuštaju im se; kojima zadržite, zadržani su im.\"');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (50, 20, 24, 'Ali Toma zvani Blizanac, jedan od dvanaestorice, ne bijaše s njima kad dođe Isus.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (50, 20, 25, 'Govorili su mu dakle drugi učenici: \"Vidjeli smo Gospodina!\" On im odvrati: \"Ako ne vidim na njegovim rukama biljeg čavala i ne stavim svoj prst u mjesto čavala, ako ne stavim svoju ruku u njegov bok, neću vjerovati.\"');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (50, 20, 26, 'I nakon osam dana bijahu njegovi učenici opet unutra, a s njima i Toma. Vrata bijahu zatvorena, a Isus dođe, stade u sredinu i reče: \"Mir vama!\"');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (50, 20, 27, 'Zatim će Tomi: \"Prinesi prst ovamo i pogledaj mi ruke! Prinesi ruku i stavi je u moj bok i ne budi nevjeran nego vjeran.\"');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (50, 20, 28, 'Odgovori mu Toma: \"Gospodin moj i Bog moj!\"');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (50, 20, 29, 'Reče mu Isus: \"Budući da si me vidio, povjerovao si. Blaženi koji ne vidješe, a vjeruju!\"');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (50, 20, 30, 'Isus je pred svojim učenicima učinio i mnoga druga znamenja koja nisu zapisana u ovoj knjizi.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (50, 20, 31, 'A ova su zapisana da vjerujete: Isus je Krist, Sin Božji, i da vjerujući imate život u imenu njegovu.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (50, 21, 1, 'Poslije toga očitova se Isus ponovno učenicima na Tiberijadskome moru. Očitova se ovako:');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (50, 21, 2, 'Bijahu zajedno Šimun Petar, Toma zvani Blizanac, Natanael iz Kane Galilejske, zatim Zebedejevi i još druga dva njegova učenika.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (50, 21, 3, 'Kaže im Šimun Petar: \"Idem ribariti.\" Rekoše: \"Idemo i mi s tobom.\" Izađoše i uđoše u lađu, ali te noći ne uloviše ništa.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (50, 21, 4, 'Kad je već svanulo, stade Isus na kraju, ali učenici nisu znali da je to Isus.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (50, 21, 5, 'Kaže im Isus: \"Dječice, imate li što za prismok?\" Odgovoriše mu: \"Nemamo.\"');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (50, 21, 6, 'A on im reče: \"Bacite mrežu na desnu stranu lađe i naći ćete.\" Baciše oni i više je ne mogoše izvući od mnoštva ribe.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (50, 21, 7, 'Tada onaj učenik kojega je Isus ljubio kaže Petru: \"Gospodin je!\" Kad je Šimun Petar čuo da je to Gospodin, pripaše si gornju haljinu, jer bijaše gol, te se baci u more.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (50, 21, 8, 'Ostali učenici dođoše s lađicom vukući mrežu s ribom jer ne bijahu daleko od kraja, samo kojih dvjesta lakata.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (50, 21, 9, 'Kad iziđu na kraj, ugledaju pripravljenu žeravicu i na njoj pristavljenu ribu i kruh.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (50, 21, 10, 'Kaže im Isus: \"Donesite riba što ih sada uloviste.\"');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (50, 21, 11, 'Nato se Šimun Petar popne i izvuče na kraj mrežu punu velikih riba, sto pedeset i tri. I premda ih je bilo toliko, mreža se ne raskinu.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (50, 21, 12, 'Kaže im Isus: \"Hajde, doručkujte!\" I nitko se od učenika ne usudi upitati ga: \"Tko si ti?\" Znali su da je Gospodin.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (50, 21, 13, 'Isus pristupi, uzme kruh i dade im, a tako i ribu.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (50, 21, 14, 'To se već treći put očitova Isus učenicima pošto uskrsnu od mrtvih.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (50, 21, 15, 'Nakon doručka upita Isus Šimuna Petra: \"Šimune Ivanov, ljubiš li me više nego ovi?\" Odgovori mu: \"Da, Gospodine, ti znaš da te volim.\"');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (50, 21, 16, 'Kaže mu: \"Pasi jaganjce moje!\" Upita ga po drugi put: \"Šimune Ivanov, ljubiš li me?\" Odgovori mu: \"Da, Gospodine, ti znaš da te volim!\" Kaže mu: \"Pasi ovce moje!\"');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (50, 21, 17, 'Upita ga treći put: \"Šimune Ivanov, voliš li me?\" Ražalosti se Petar što ga upita treći put: \"Voliš li me?\" pa mu odgovori: \"Gospodine, ti sve znaš! Tebi je poznato da te volim.\" Kaže mu Isus: \"Pasi ovce moje!\"');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (50, 21, 18, '\"Zaista, zaista kažem ti: Dok si bio mlađi, sam si se opasivao i hodio kamo si htio; ali kad ostariš, raširit ćeš ruke i drugi će te opasivati i voditi kamo nećeš.\"');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (50, 21, 19, 'A to mu reče nagovješćujući kakvom će smrću proslaviti Boga. Rekavši to doda: \"Idi za mnom!\"');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (50, 21, 20, 'Petar se okrene i opazi da ga slijedi onaj učenik kojega je Isus ljubio i koji se za večere bijaše privio Isusu uz prsa i upitao ga: \"Gospodine, tko će te to izdati?\"');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (50, 21, 21, 'Vidjevši ga, Petar kaže Isusu: \"Gospodine, a što s ovim?\"');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (50, 21, 22, 'Odgovori mu Isus: \"Ako hoću da on ostane dok ne dođem, što je tebi do toga? Ti idi za mnom!\"');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (50, 21, 23, 'Stoga se pronese među braćom glas da onaj učenik neće umrijeti. No Isus mu nije rekao: \"Neće umrijeti\", nego: \"Ako hoću da on ostane dok ne dođem, što je tebi do toga?\"');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (50, 21, 24, 'Taj učenik za ovo svjedoči i ovo napisa. I znamo da je istinito svjedočanstvo njegovo.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (50, 21, 25, 'A ima još mnogo toga što učini Isus i kad bi se sve redom popisalo, sav svijet, mislim, ne bi obuhvatio knjiga koje bi se napisale.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (51, 1, 1, 'Prvu sam knjigu, Teofile, sastavio o svemu što je Isus činio i učio');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (51, 1, 2, 'do dana kad je uznesen pošto je dao upute apostolima koje je izabrao po Duhu Svetome.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (51, 1, 3, 'Njima je poslije svoje muke mnogim dokazima pokazao da je živ, četrdeset im se dana ukazivao i govorio o kraljevstvu Božjem.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (51, 1, 4, 'I dok je jednom s njima blagovao, zapovjedi im da ne napuštaju Jeruzalema, nego neka čekaju Obećanje Očevo \"koje čuste od mene:');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (51, 1, 5, 'Ivan je krstio vodom, a vi ćete naskoro nakon ovih dana biti kršteni Duhom Svetim.\"');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (51, 1, 6, 'Nato ga sabrani upitaše: \"Gospodine, hoćeš li u ovo vrijeme Izraelu opet uspostaviti kraljevstvo?\"');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (51, 1, 7, 'On im odgovori: \"Nije vaše znati vremena i zgode koje je Otac podredio svojoj vlasti.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (51, 1, 8, 'Nego primit ćete snagu Duha Svetoga koji će sići na vas i bit ćete mi svjedoci u Jeruzalemu, po svoj Judeji i Samariji i sve do kraja zemlje.\"');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (51, 1, 9, 'Kada to reče, bi uzdignut njima naočigled i oblak ga ote njihovim očima.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (51, 1, 10, 'I dok su netremice gledali kako on odlazi na nebo, gle, dva čovjeka stadoše kraj njih u bijeloj odjeći');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (51, 1, 11, 'i rekoše im: \"Galilejci, što stojite i gledate u nebo? Ovaj Isus koji je od vas uznesen na nebo isto će tako doći kao što ste vidjeli da odlazi na nebo.\"');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (51, 1, 12, 'Onda se vratiše u Jeruzalem s brda zvanoga Maslinsko, koje je blizu Jeruzalema, udaljeno jedan subotni hod.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (51, 1, 13, 'I pošto uđu u grad, uspnu se u gornju sobu gdje su boravili: Petar i Ivan i Jakov i Andrija, Filip i Toma, Bartolomej i Matej, Jakov Alfejev i Šimun Revnitelj i Juda Jakovljev -');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (51, 1, 14, 'svi oni bijahu jednodušno postojani u molitvi sa ženama, i Marijom, majkom Isusovom, i braćom njegovom.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (51, 1, 15, 'U one dane ustade Petar među braćom - a bijaše sakupljenog naroda oko sto i dvadeset duša - i reče:');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (51, 1, 16, '\"Braćo! Trebalo je da se ispuni Pismo što ga na usta Davidova proreče Duh Sveti o Judi koji bijaše vođa onih što uhvatiše Isusa.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (51, 1, 17, 'A Juda se ubrajao među nas i imao udio u ovoj službi.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (51, 1, 18, 'On, eto, steče predio cijenom nepravednosti pa se stropošta, raspuče po sredini i razli mu se sva utroba.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (51, 1, 19, 'I svim je Jeruzalemcima znano da se onaj predio njihovim jezikom zove Akeldama, to jest Predio smrti.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (51, 1, 20, 'Pisano je doista u Knjizi psalama: Njegova kuća nek opusti, nek ne bude stanovnika u njoj! Njegovo nadgledništvo nek dobije drugi!');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (51, 1, 21, 'Jedan dakle od ovih ljudi što bijahu s nama za sve vrijeme što je među nama živio Gospodin Isus -');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (51, 1, 22, 'počevši od krštenja Ivanova pa sve do dana kad bi uzet od nas - treba da bude svjedokom njegova uskrsnuća.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (51, 1, 23, 'I postaviše dvojicu: Josipa koji se zvao Barsaba a prozvao se Just, i Matiju.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (51, 1, 24, 'Onda se pomoliše: \"Ti, Gospodine, poznavaoče svih srdaca, pokaži koga si od ove dvojice izabrao');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (51, 1, 25, 'da primi mjesto ove apostolske službe kojoj se iznevjeri Juda da ode na svoje mjesto.\"');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (51, 1, 26, 'Onda baciše kocke i kocka pade na Matiju; tako bi pribrojen jedanaestorici apostola.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (51, 2, 1, 'Kad je napokon došao dan Pedesetnice, svi su bili zajedno na istome mjestu.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (51, 2, 2, 'I eto iznenada šuma s neba, kao kad se digne silan vjetar. Ispuni svu kuću u kojoj su bili.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (51, 2, 3, 'I pokažu im se kao neki ognjeni razdijeljeni jezici te siđe po jedan na svakoga od njih.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (51, 2, 4, 'Svi se napuniše Duha Svetoga i počeše govoriti drugim jezicima, kako im već Duh davaše zboriti.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (51, 2, 5, 'A u Jeruzalemu su boravili Židovi, ljudi pobožni iz svakog naroda pod nebom.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (51, 2, 6, 'Pa kad nasta ona huka, strča se mnoštvo i smetÄe jer ih je svatko čuo govoriti svojim jezikom.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (51, 2, 7, 'Svi su bili izvan sebe i divili se govoreći: \"Gle! Nisu li svi ovi što govore Galilejci?');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (51, 2, 8, 'Pa kako to da ih svatko od nas čuje na svojem materinskom jeziku?');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (51, 2, 9, 'Parti, Međani, Elamljani, žitelji Mezopotamije, Judeje i Kapadocije, Ponta i Azije,');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (51, 2, 10, 'Frigije i Pamfilije, Egipta i krajeva libijskih oko Cirene, pridošlice Rimljani,');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (51, 2, 11, 'Židovi i sljedbenici, Krećani i Arapi - svi ih mi čujemo gdje našim jezicima razglašuju veličanstvena djela Božja.\"');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (51, 2, 12, 'Svi su izvan sebe zbunjeno jedan drugog pitali: \"Što bi to moglo biti?\"');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (51, 2, 13, 'Drugi su pak, podrugujući se, govorili: \"Slatkog su se vina ponapili!\"');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (51, 2, 14, 'A Petar zajedno s jedanaestoricom ustade, podiže glas i prozbori: \"Židovi i svi što boravite u Jeruzalemu, ovo znajte i riječi mi poslušajte:');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (51, 2, 15, 'Nisu ovi pijani, kako vi mislite - ta istom je treća ura dana -');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (51, 2, 16, 'nego to je ono što je rečeno po proroku Joelu:');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (51, 2, 17, '\"U posljednje dane, govori Bog: Izlit ću Duha svoga na svako tijelo i proricat će vaši sinovi i kćeri, vaši će mladići gledati viđenja, a starci vaši sne sanjati.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (51, 2, 18, 'Čak ću i na sluge i sluškinje svoje izliti Duha svojeg u dane one i proricat će.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (51, 2, 19, 'Pokazat ću čudesa na nebu gore i znamenja na zemlji dolje, krv i oganj i stupove dima.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (51, 2, 20, 'Sunce će se prometnut u tminu, a mjesec u krv prije nego svane Dan Gospodnji velik i slavan.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (51, 2, 21, 'I tko god prizove ime Gospodnje bit će spašen.\"');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (51, 2, 22, '\"Izraelci, čujte ove riječi: Isusa Nazarećanina, čovjeka kojega Bog pred vama potvrdi silnim djelima, čudesima i znamenjima koja, kao što znate, po njemu učini među vama -');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (51, 2, 23, 'njega, predana po odlučenu naumu i promislu Božjem, po rukama bezakonika razapeste i pogubiste.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (51, 2, 24, 'Ali Bog ga uskrisi oslobodivši ga grozote smrti jer ne bijaše moguće da ona njime ovlada.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (51, 2, 25, 'David doista za nj kaže: Gospodin mi je svagda pred očima jer mi je zdesna da ne posrnem.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (51, 2, 26, 'Stog mi se raduje srce i kliče jezik, pa i tijelo mi spokojno počiva.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (51, 2, 27, 'Jer mi nećeš ostaviti dušu u Podzemlju ni dati da pravednik tvoj truleži ugleda.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (51, 2, 28, 'Pokazat ćeš mi stazu života, ispuniti me radošću lica svoga.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (51, 2, 29, 'Braćo, dopustite da vam otvoreno kažem: praotac je David umro, pokopan je i eno mu među nama groba sve do današnjeg dana.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (51, 2, 30, 'Ali kako je bio prorok i znao da mu se zakletvom zakle Bog plod utrobe njegove posaditi na prijestolje njegovo,');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (51, 2, 31, 'unaprijed je vidio i navijestio uskrsnuće Kristovo: Nije ostavljen u Podzemlju niti mu tijelo truleži ugleda.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (51, 2, 32, 'Toga Isusa uskrisi Bog! Svi smo mi tomu svjedoci.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (51, 2, 33, 'Desnicom dakle Božjom uzvišen, primio je od Oca Obećanje, Duha Svetoga, i izlio ga kako i sami gledate i slušate.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (51, 2, 34, 'Ta David nije bio uznesen na nebesa, a veli: Reče Gospodin Gospodinu mojemu: \'Sjedi mi zdesna\'');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (51, 2, 35, 'dok ne položim neprijatelje tvoje za podnožje nogama tvojim!');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (51, 2, 36, 'Pouzdano dakle neka znade sav dom Izraelov da je toga Isusa kojega vi razapeste Bog učinio i Gospodinom i Kristom.\"');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (51, 2, 37, 'Kad su to čuli, duboko potreseni rekoše Petru i drugim apostolima: \"Što nam je činiti, braćo?\"');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (51, 2, 38, 'Petar će im: \"Obratite se i svatko od vas neka se krsti u ime Isusa Krista da vam se oproste grijesi i primit ćete dar, Duha Svetoga.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (51, 2, 39, 'Ta za vas je ovo obećanje i za djecu vašu i za sve one izdaleka, koje pozove Gospodin Bog naš.\"');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (51, 2, 40, 'I mnogim je drugim riječima još svjedočio i hrabrio ih: \"Spasite se od naraštaja ovog opakog!\"');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (51, 2, 41, 'I oni prigrliše riječ njegovu i krstiše se te im se u onaj dan pridruži oko tri tisuće duša.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (51, 2, 42, 'Bijahu postojani u nauku apostolskom, u zajedništvu, lomljenju kruha i molitvama.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (51, 2, 43, 'Strahopoštovanje obuzimaše svaku dušu: apostoli su činili mnoga čudesa i znamenja.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (51, 2, 44, 'Svi koji prigrliše vjeru bijahu združeni i sve im bijaše zajedničko.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (51, 2, 45, 'Sva bi imanja i dobra prodali porazdijelili svima kako bi tko trebao.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (51, 2, 46, 'Svaki bi dan jednodušno i postojano hrlili u Hram, u kućama bi lomili kruh te u radosti i prostodušnosti srca zajednički uzimali hranu');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (51, 2, 47, 'hvaleći Boga i uživajući naklonost svega naroda. Gospodin je pak danomice zajednici pridruživao spasenike.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (51, 3, 1, 'Petar i Ivan uzlazili su u Hram na devetu molitvenu uru.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (51, 3, 2, 'Upravo su donosili nekog čovjeka, hroma od majčine utrobe; njega bi svaki dan postavljali kod hramskih vrata, zvanih Divna, da prosi milostinju od onih koji ulaze u Hram.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (51, 3, 3, 'On ugleda Petra i Ivana upravo kad zakoračiše u Hram te zamoli milostinju.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (51, 3, 4, 'Petar ga zajedno s Ivanom prodorno pogleda i reče: \"Pogledaj u nas!\"');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (51, 3, 5, 'Dok ih je molećivo motrio očekujući od njih nešto dobiti,');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (51, 3, 6, 'reče mu Petar: \"Srebra i zlata nema u mene, ali što imam - to ti dajem: u ime Isusa Krista Nazarećanina hodaj!\"');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (51, 3, 7, 'I uhvativši ga za desnu ruku, pridiže ga: umah mu omoćaše noge i gležnjevi');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (51, 3, 8, 'pa skoči, uspravi se, stane hodati te uđe s njima u Hram hodajući, poskakujući i hvaleći Boga.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (51, 3, 9, 'Sav ga narod vidje kako hoda i hvali Boga.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (51, 3, 10, 'Razabraše da je to on - onaj koji je na Divnim vratima Hrama prosio milostinju - i ostadoše zapanjeni i izvan sebe zbog onoga što se s njim dogodilo.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (51, 3, 11, 'Kako se pak on držao Petra i Ivana, sav se narod zapanjen strča k njima u trijem zvani Salomonov.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (51, 3, 12, 'Kada to vidje Petar, obrati se narodu: \"Izraelci, što se ovomu čudite? Ili što nas gledate kao da smo svojom snagom ili pobožnošću postigli da ovaj prohoda?');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (51, 3, 13, 'Bog Abrahamov, Izakov i Jakovljev, Bog otaca naših, proslavi slugu svoga, Isusa kojega vi predadoste i kojega se odrekoste pred Pilatom kad već bijaše odlučio pustiti ga.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (51, 3, 14, 'Vi se odrekoste Sveca i Pravednika, a izmoliste da vam se daruje ubojica.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (51, 3, 15, 'Začetnika života ubiste. Ali Bog ga uskrisi od mrtvih, čemu smo mi svjedoci.\"');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (51, 3, 16, '\"I po vjeri u njegovo ime, to je ime dalo snagu ovomu kojega gledate i poznate: vjera u Njega vratila je ovomu potpuno zdravlje naočigled vas sviju.\"');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (51, 3, 17, '\"I sada, braćo, znam da ste ono uradili iz neznanja kao i glavari vaši.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (51, 3, 18, 'Ali Bog tako ispuni što unaprijed navijesti po ustima svih proroka: da će njegov Pomazanik trpjeti.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (51, 3, 19, 'Pokajte se dakle i obratite da se izbrišu grijesi vaši');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (51, 3, 20, 'pa od Gospodina dođu vremena rashlade te on pošalje vama unaprijed namijenjenog Pomazanika, Isusa.\"');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (51, 3, 21, 'Njega treba da nebo pridrži do vremena uspostave svega što obeća Bog na usta svetih proroka svojih odvijeka.\"');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (51, 3, 22, '\"Mojsije tako reče: Proroka poput mene od vaše braće podignut će vam Gospodin, Bog vaš. Njega slušajte u svemu što vam god reče.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (51, 3, 23, 'I svaka duša koja ne posluša toga proroka, neka se iskorijeni iz naroda.\"');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (51, 3, 24, '\"I svi Proroci koji su - od Samuela dalje - govorili, također su navijestili ove dane.\"');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (51, 3, 25, '\"Vi ste sinovi proroka i Saveza koji sklopi Bog s ocima vašim govoreći Abrahamu: Potomstvom će se tvojim blagoslivljati sva plemena zemlje.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (51, 3, 26, 'Vama najprije podiže Bog Slugu svoga i posla ga blagoslivljati vas da se svatko obrati od opačina svojih.\"');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (51, 4, 1, 'Dok su oni još govorili narodu, priđu im svećenici, hramski zapovjednik i saduceji,');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (51, 4, 2, 'ozlovoljeni što uče narod i navješćuju - u Isusu - uskrsnuće od mrtvih;');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (51, 4, 3, 'pograbe ih i bace u tamnicu do sutra jer već bijaše večer.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (51, 4, 4, 'Ipak mnogi od onih koji su čuli Riječ, povjerovaše te broj vjernika poraste nekako do pet tisuća.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (51, 4, 5, 'Sutradan se sastadoše u Jeruzalemu glavari, starješine i pismoznanci -');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (51, 4, 6, 'i veliki svećenik Ana, i Kajfa, i Ivan, i Aleksandar, i svi od roda velikosvećeničkoga.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (51, 4, 7, 'Izvedoše apostole preda se pa ih stadoše ispitivati: \"Kojom snagom ili po kojem imenu vi to učiniste?\"');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (51, 4, 8, 'Onda Petar pun Duha Svetoga reče: \"Glavari narodni i starješine!');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (51, 4, 9, 'Zar mi danas odgovaramo zbog dobra djela učinjena bolesnu čovjeku? Po kome je ovaj spašen?');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (51, 4, 10, 'Neka bude znano svima vama i svemu narodu Izraelovu: po imenu Isusa Krista Nazarećanina, kojega ste vi raspeli, a kojega Bog uskrisi od mrtvih! Po njemu ovaj stoji pred vama zdrav!');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (51, 4, 11, 'On je onaj kamen koji vi graditelji odbaciste, ali koji postade kamen zaglavni.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (51, 4, 12, 'I nema ni u kome drugom spasenja. Nema uistinu pod nebom drugoga imena dana ljudima po kojemu se možemo spasiti.\"');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (51, 4, 13, 'Kad vidješe neustrašivost Petrovu i Ivanovu, a znajući da su to ljudi nepismeni i neuki, bijahu u čudu; znali su ih, da bijahu s Isusom, ali');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (51, 4, 14, 'videći gdje s njima stoji izliječeni čovjek, nisu mogli ništa protusloviti.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (51, 4, 15, 'Stoga zapovjediše da izađu iz vijećnice pa stadoše raspravljati:');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (51, 4, 16, '\"Što ćemo s tim ljudima? Ta učinili su očit znak, poznat svim Jeruzalemcima, ne možemo ga nijekati;');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (51, 4, 17, 'ali da se još više ne razglasi u narod, zaprijetimo im da nikomu živom o tom Imenu više ne govore.\"');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (51, 4, 18, 'Pozvaše ih i zapovjediše im da podnipošto ne zbore niti naučavaju u ime Isusovo.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (51, 4, 19, 'Ali im Petar i Ivan odgovoriše: \"Sudite je li pred Bogom pravo slušati radije vas nego Boga.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (51, 4, 20, 'Mi doista ne možemo ne govoriti što vidjesmo i čusmo.\"');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (51, 4, 21, 'Ali oni ne našavši kako da ih kazne, opet im zaprijete pa ih otpuste poradi naroda jer su svi slavili Boga zbog onoga što se dogodilo.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (51, 4, 22, 'Jer čovjeku na kom se dogodi čudo ozdravljenja bijaše više od četrdeset godina.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (51, 4, 23, 'Otpušteni, odoše svojima i javiše što im rekoše veliki svećenici i starješine.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (51, 4, 24, 'Kad su oni to čuli, jednodušno podigoše glas k Bogu i rekoše: \"Gospodine, ti si stvorio nebo i zemlju i more i sve što je u njima!');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (51, 4, 25, 'Ti si na usta oca našega, sluge svoga Davida, po Duhu Svetom rekao: Zašto se bune narodi, zašto puci ludosti snuju?');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (51, 4, 26, 'Ustaju kraljevi zemaljski, Knezovi se rotÄe protiv Gospodina i protiv Pomazanika njegova.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (51, 4, 27, 'RotÄe se, uistinu, u ovome gradu na svetog Slugu tvoga Isusa, kog pomaza, rotÄe se Herod i Poncije Pilat zajedno s narodima i pucima izraelskim');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (51, 4, 28, 'da učine što tvoja ruka i tvoja volja predodredi da se zbude.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (51, 4, 29, 'I evo sada, Gospodine, promotri prijetnje njihove i daj slugama svojim sa svom smjelošću navješćivati riječ tvoju!');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (51, 4, 30, 'Pruži ruku svoju da bude ozdravljenja, znamenja i čudesa po imenu svetoga Sluge tvoga Isusa.\"');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (51, 4, 31, 'I pošto se pomoliše, potrese se mjesto gdje bijahu sabrani, i svi se napuniše Duha Svetoga te stanu navješćivati riječ Božju smjelo.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (51, 4, 32, 'U mnoštva onih što prigrliše vjeru bijaše jedno srce i jedna duša. I nijedan od njih nije svojim zvao ništa od onoga što je imao, nego im sve bijaše zajedničko.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (51, 4, 33, 'Apostoli pak velikom silom davahu svjedočanstvo o uskrsnuću Gospodina Isusa i svi uživahu veliku naklonost.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (51, 4, 34, 'Doista, nitko među njima nije oskudijevao jer koji bi god posjedovali zemljišta ili kuće, prodavali bi ih i utržak donosili');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (51, 4, 35, 'i stavljali pred noge apostolima. A dijelilo se svakomu koliko je trebao.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (51, 4, 36, 'A Josip, od apostola prozvan Barnaba, što znači Sin utjehe, levit, rodom Cipranin,');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (51, 4, 37, 'posjedovaše jednu njivu; proda je pa donese novac i postavi pred noge apostolima.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (51, 5, 1, 'Neki pak čovjek po imenu Ananija, zajedno sa svojom ženom Safirom proda imanje');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (51, 5, 2, 'pa u dogovoru sa ženom odvoji nešto od utrška, a samo jedan dio donese i postavi pred noge apostolima.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (51, 5, 3, 'Petar mu reče: \"Ananija, zašto ti Sotona ispuni srce te si slagao Duhu Svetomu i odvojio od utrška imanja?');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (51, 5, 4, 'Da je ostalo neprodano, ne bi li tvoje ostalo; i jednoć prodano, nije li u tvojoj vlasti? Zašto si se na takvo što odlučio? Nisi slagao ljudima, nego Bogu!\"');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (51, 5, 5, 'Kako Ananija ču te riječi, sruši se i izdahnu. I silan strah spopade sve koji su to čuli.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (51, 5, 6, 'Nato ustanu mladići, poviju ga, iznesu i pokopaju.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (51, 5, 7, 'Nakon otprilike tri sata uđe njegova žena ne znajući što se dogodilo.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (51, 5, 8, 'Petar joj reče: \"Reci mi, jeste li za toliko dali imanje?\" Ona odgovori: \"Da, za toliko.\"');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (51, 5, 9, 'A Petar će joj: \"Što vam bi da se složiste iskušati Duha Gospodnjega? Eto na vratima nogu onih koji ti pokopaše muža! I tebe će iznijeti!\"');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (51, 5, 10, 'Ona se umah sruši do njegovih nogu i izdahnu. Oni mladići uđu, nađu je mrtvu, iznesu je i pokopaju uz muža.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (51, 5, 11, 'I silan strah spopade cijelu Crkvu i sve koji su to čuli.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (51, 5, 12, 'Po rukama se apostolskim događala mnoga znamenja i čudesa u narodu. Svi su se jednodušno okupljali u Trijemu Salomonovu.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (51, 5, 13, 'Nitko se drugi nije usuđivao pridružiti im se, ali ih je narod veličao.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (51, 5, 14, 'I sve se više povećavalo mnoštvo muževa i žena što vjerovahu Gospodinu');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (51, 5, 15, 'tako da su na trgove iznosili bolesnike i postavljali ih na ležaljkama i posteljama ne bi li, kad Petar bude prolazio, bar sjena njegova osjenila kojega od njih.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (51, 5, 16, 'A slijegalo bi se i mnoštvo iz gradova oko Jeruzalema: donosili bi bolesnike i opsjednute od nečistih duhova, i svi bi ozdravljali.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (51, 5, 17, 'Onda se podiže veliki svećenik i sve njegove pristaše - sljedba saducejska.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (51, 5, 18, 'Puni zavisti, pohvataju apostole i strpaju ih u javnu tamnicu.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (51, 5, 19, 'Ali anđeo Gospodnji noću otvori vrata tamnice, izvede ih i reče:');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (51, 5, 20, '\"Pođite i postojano u Hramu navješćujte narodu sve riječi Života ovoga.\"');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (51, 5, 21, 'Poslušni, u praskozorje su ušli u Hram te naučavali. Uto stiže veliki svećenik i njegove pristaše, sazovu Vijeće i sve starješinstvo sinova Izraelovih pa pošalju u zatvor da ih dovedu.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (51, 5, 22, 'Kad stražari stigoše onamo, ne nađoše ih u tamnici pa se vrate i jave:');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (51, 5, 23, '\"Zatvor smo našli sa svom pomnjom zatvoren i čuvare na straži pred vratima, ali kad smo otvorili, nikoga unutra ne nađosmo.\"');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (51, 5, 24, 'Kad su hramski zapovjednik i veliki svećenici čuli te riječi, u nedoumici su se pitali što bi to moglo biti.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (51, 5, 25, 'Nato netko pristigne i dojavi im: \"Eno, ljudi koje baciste u tamnicu, u Hramu stoje i uče narod.\"');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (51, 5, 26, 'Tada zapovjednik sa stražarima ode te ih dovede - ne na silu jer se bojahu da ih narod ne kamenuje.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (51, 5, 27, 'Dovedoše ih i privedoše pred Vijeće. Veliki ih svećenik zapita:');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (51, 5, 28, '\"Nismo li vam strogo zabranili učiti u to Ime? A vi ste eto napunili Jeruzalem svojim naukom i hoćete na nas navući krv toga čovjeka.\"');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (51, 5, 29, 'Petar i apostoli odvrate: \"Treba se većma pokoravati Bogu negoli ljudima!');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (51, 5, 30, 'Bog otaca naših uskrisi Isusa kojega vi smakoste objesivši ga na drvo.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (51, 5, 31, 'Njega Bog desnicom svojom uzvisi za Začetnika i Spasitelja da obraćenjem podari Izraela i oproštenjem grijeha.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (51, 5, 32, 'I mi smo svjedoci tih događaja i Duh Sveti kojega dade Bog onima što mu se pokoravaju.\"');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (51, 5, 33, 'Nato se oni razgnjeviše i htjedoše ih ubiti.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (51, 5, 34, 'Ali ustade u Vijeću neki farizej imenom Gamaliel, zakonoznanac, kojega je poštovao sav narod. On zapovjedi da ljude načas izvedu');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (51, 5, 35, 'pa će vijećnicima: \"Izraelci, dobro promislite što ćete s tim ljudima.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (51, 5, 36, 'Ta prije nekog vremena podiže se Teuda tvrdeći da je netko, i uza nj prista oko četiri stotine ljudi. Bi smaknut i sve mu se pristaše razbjegoše i netragom ih nesta.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (51, 5, 37, 'Nakon toga se u dane popisa podiže Juda Galilejac i odvuče narod za sobom. I on propade i sve mu se pristaše raspršiše.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (51, 5, 38, 'I sad evo kanite se, velim vam, tih ljudi i otpustite ih. Jer ako je taj naum ili to djelo od ljudi, propast će;');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (51, 5, 39, 'ako li je pak od Boga, nećete ga moći uništiti - da se i s Bogom u ratu ne nađete.\" Poslušaju ga');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (51, 5, 40, 'pa dozovu apostole, išibaju ih, zapovjede im da ne govore u ime Isusovo pa ih otpuste.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (51, 5, 41, 'Oni pak odu ispred Vijeća radosni što bijahu dostojni podnijeti pogrde za Ime.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (51, 5, 42, 'I svaki su dan u Hramu i po kućama neprestance učili i navješćivali Krista, Isusa.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (51, 6, 1, 'U one dane, kako se broj učenika množio, Židovi grčkog jezika stadoše mrmljati protiv domaćih Židova što se u svagdanjem služenju zanemaruju njihove udovice.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (51, 6, 2, 'Dvanaestorica nato sazvaše mnoštvo učenika i rekoše: \"Nije pravo da mi napustimo riječ Božju da bismo služili kod stolova.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (51, 6, 3, 'De pronađite, braćo, između sebe sedam muževa na dobru glasu, punih Duha i mudrosti. Njih ćemo postaviti nad ovom službom,');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (51, 6, 4, 'a mi ćemo se posvetiti molitvi i posluživanju Riječi.\"');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (51, 6, 5, 'Prijedlog se svidje svemu mnoštvu pa izabraše Stjepana, muža puna vjere i Duha Svetoga, zatim Filipa, Prohora, Nikanora, Timona, Parmenu te antiohijskog pridošlicu Nikolu.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (51, 6, 6, 'Njih postave pred apostole, a oni pomolivši se, polože na njih ruke.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (51, 6, 7, 'I riječ je Božja rasla, uvelike se množio broj učenika u Jeruzalemu i veliko je mnoštvo svećenika prihvaćalo vjeru.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (51, 6, 8, 'Stjepan je pun milosti i snage činio velika čudesa i znamenja u narodu.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (51, 6, 9, 'Nato se digoše neki iz takozvane sinagoge Slobodnjaka, Cirenaca, Aleksandrinaca te onih iz Cilicije i Azije pa počeše raspravljati sa Stjepanom,');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (51, 6, 10, 'ali nisu mogli odoljeti mudrosti i Duhu kojim je govorio.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (51, 6, 11, 'Onda podmetnuše neke ljude koji rekoše: \"Čuli smo ga govoriti pogrdne riječi protiv Mojsija i Boga.\"');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (51, 6, 12, 'Podjare i narod, starješine i pismoznance pa priđu, zgrabe ga i odvuku u Vijeće.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (51, 6, 13, 'Ondje namjestiše lažne svjedoke koji rekoše: \"Ovaj čovjek neprestance govori protiv svetog Mjesta i Zakona.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (51, 6, 14, 'Čuli smo ga doista govoriti: \'Isus Nazarećanin razvalit će ovo Mjesto i izmijeniti običaje koje nam predade Mojsije\'.\"');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (51, 6, 15, 'A svi koji su sjedili u Vijeću upriješe pogled u Stjepana te opaziše - lice mu kao u anđela.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (51, 7, 1, 'Veliki svećenik upita: \"Je li to tako?\"');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (51, 7, 2, 'Stjepan odgovori: \"Braćo i oci, čujte! Bog slave ukaza se ocu našemu Abrahamu dok bijaše u Mezopotamiji, prije negoli se nastani u Haranu,');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (51, 7, 3, 'i reče mu: Iziđi iz zemlje svoje, iz zavičaja svoga, hajde u zemlju koju ću ti pokazati.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (51, 7, 4, 'On nato iziđe iz zemlje kaldejske i nastani se u Haranu. Odande ga nakon smrti oca njegova Bog preseli u ovu zemlju u kojoj vi sada boravite.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (51, 7, 5, 'U njoj mu ne dade ni stope baštine, nego obeća dati je u posjed njemu i potomstvu njegovu nakon njega, premda još nije imao djeteta.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (51, 7, 6, 'Bog isto tako reče da će potomci njegovi biti pridošlice u zemlji tuđoj, da će ih porobljavati i tlačiti četiri stotine godina.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (51, 7, 7, 'Ali narod kojemu budu robovali ja ću suditi, reče Bog. A nakon toga izići će i iskazati mi štovanje na ovome mjestu.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (51, 7, 8, 'Dade mu i Savez obrezanja. Tako rodi Izaka i obreza ga osmi dan, Izak Jakova, Jakov dvanaest rodozačetnika.\"');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (51, 7, 9, '\"Rodozačetnici pak, iz zavisti, Josipa predadoše u Egipat. Ali Bog bijaše s njim');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (51, 7, 10, 'te ga izbavljaše iz svih nevolja, podari ga naklonošću i mudrošću pred faraonom, kraljem egipatskim koji ga postavi za upravitelja nad Egiptom i nad cijelim dvorom svojim.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (51, 7, 11, 'Onda u cijeloj zemlji egipatskoj i kanaanskoj nasta glad i nevolja velika: oci naši ne mogahu naći hrane.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (51, 7, 12, 'Kad Jakov doču da u Egiptu ima žita, posla onamo najprije oce naše.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (51, 7, 13, 'Drugi se put Josip očitova braći svojoj pa faraon dozna za podrijetlo Josipovo.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (51, 7, 14, 'Josip tada posla po Jakova, oca svoga, i svu rodbinu, sedamdeset i pet duša.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (51, 7, 15, 'Jakov tako siđe u Egipat. I umrije on i oci naši.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (51, 7, 16, 'Preneseni su u Sihem i položeni u grob koji je Abraham za srebro kupio od sinova Hamorovih u Sihemu.\"');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (51, 7, 17, '\"Kako se bližilo vrijeme obećanja koje Bog obreče Abrahamu, rastao je u Egiptu narod i množio se');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (51, 7, 18, 'dok ondje ne zavlada drugi kralj koji nije poznavao Josipa.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (51, 7, 19, 'Lukav prema rodu našemu, tlačio je on oce naše da bi djecu svoju izlagali da ne ostanu na životu.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (51, 7, 20, 'U taj se čas rodi Mojsije. Bijaše božanski lijep. Tri je mjeseca hranjen u kući očinskoj,');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (51, 7, 21, 'a onda, kad je bio izložen, prigrli ga kći faraonova i othrani sebi za sina.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (51, 7, 22, 'Tako Mojsije, odgojen u svoj mudrosti egipatskoj, bijaše silan na riječima i djelima.\"');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (51, 7, 23, '\"Kad mu bijaše četrdeset godina, ponuka ga srce da pohodi braću svoju, sinove Izraelove.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (51, 7, 24, 'I kad vidje kako je jednomu nanesena nepravda, suprotstavi se i osveti zlostavljenoga ubivši Egipćanina.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (51, 7, 25, 'Mislio je da će braća njegova shvatiti kako će im Bog po njegovoj ruci pružiti spasenje, ali oni ne shvatiše.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (51, 7, 26, 'Sutradan se pojavi pred onima koji su se tukli te ih stade nagovarati da se izmire: \'Ljudi, braća ste! Zašto zlostavljate jedan drugoga?\'');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (51, 7, 27, 'Ali ga onaj što je zlostavljao svoga bližnjega odbi riječima: Tko te postavi glavarom i sucem nad nama?');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (51, 7, 28, 'Kaniš li ubiti i mene kao što si jučer ubio onog Egipćanina?');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (51, 7, 29, 'Na te riječi pobježe Mojsije i skloni se u zemlju midjansku, gdje mu se rodiše dva sina.\"');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (51, 7, 30, '\"Nakon četrdeset godina ukaza mu se Anđeo u pustinji brda Sinaja u rasplamtjeloj vatri jednoga grma.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (51, 7, 31, 'Opazivši to, zadivi se Mojsije viđenju. Dok je prilazio da bolje promotri, eto glasa Gospodnjega:');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (51, 7, 32, 'Ja sam Bog Otaca tvojih, Bog Abrahamov, Izakov i Jakovljev. Sav preplašen, Mojsije se ne usudi pogledati.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (51, 7, 33, 'A Gospodin će mu: Izuj obuću s nogu! Jer mjesto na kojem stojiš, sveto je tlo.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (51, 7, 34, 'Vidio sam, vidio nevolju naroda svoga u Egiptu i uzdisaj mu čuo pa siđoh izbaviti ga. I sad hajde! Šaljem te u Egipat!\"');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (51, 7, 35, '\"Toga Mojsija - kojega su se odrekli rekavši: Tko te postavi glavarom i sucem? - toga im Bog kao glavara i otkupitelja posla po Anđelu koji mu se ukaza u grmu.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (51, 7, 36, 'On ih izvede učinivši čudesa i znamenja u zemlji egipatskoj, u Crvenome moru i u pustinji kroz četrdeset godina.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (51, 7, 37, 'To je onaj Mojsije koji reče sinovima Izraelovim: Proroka poput mene od vaše braće podići će vam Bog.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (51, 7, 38, 'To je onaj koji za skupa u pustinji bijaše između Anđela što mu govoraše na brdu Sinaju i otaca naših; onaj koji je primio riječi životne da ih nama preda.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (51, 7, 39, 'Njemu se ne htjedoše pokoriti oci naši, nego ga odbiše i u srcima se svojima vratiše u Egipat');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (51, 7, 40, 'rekavši Aronu: \'Napravi nam bogove koji će ići pred nama! Ta ne znamo što se dogodi s tim Mojsijem koji nas izvede iz zemlje egipatske.\'');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (51, 7, 41, 'Tele načiniše u dane one, prinesoše žrtvu tom kumiru i veseljahu se djelima ruku svojih.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (51, 7, 42, 'Bog se pak odvrati i prepusti ih da časte vojsku nebesku, kao što piše u Knjizi proročkoj: Prinosiste li mi žrtve i prinose četrdeset godina u pustinji, dome Izraelov?');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (51, 7, 43, 'Poprimiste šator Molohov i zvijezdu boga Refana - likove koje napraviste da biste im se klanjali. Odvest ću vas stoga u progonstvo onkraj Babilona!\"');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (51, 7, 44, '\"Oci naši imahu u pustinji Šator svjedočanstva kako odredi Onaj koji reče Mojsiju da se on načini po praliku koji je vidio.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (51, 7, 45, 'Taj su Šator preuzeli oci naši i pod Jošuom ga unijeli u posjed s kojega Bog pred licem njihovim rastjera narode. Tako bijaše sve do dana Davida,');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (51, 7, 46, 'koji je našao milost pred Bogom te molio da nađe boravište Bogu Jakovljevu.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (51, 7, 47, 'Istom Salomon izgradi mu Dom.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (51, 7, 48, 'Ali Svevišnji u rukotvorinama ne prebiva, kao što veli prorok:');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (51, 7, 49, 'Nebesa su moje prijestolje, a zemlja podnožje nogama. Kakav dom da mi sagradite, govori Gospodin, i gdje da bude mjesto mog počinka?');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (51, 7, 50, 'Nije li ruka moja načinila sve to?');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (51, 7, 51, 'Tvrdovrati i neobrezanih srdaca i ušiju, vi se uvijek opirete Duhu Svetomu: kako oci vaši tako i vi!');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (51, 7, 52, 'Kojega od proroka nisu progonili oci vaši? I pobiše one koji su unaprijed navijestili dolazak Pravednika čiji ste vi sada izdajice i ubojice,');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (51, 7, 53, 'vi koji po anđeoskim uredbama primiste Zakon, ali ga se niste držali.\"');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (51, 7, 54, 'Kad su to čuli, uskipješe u srcima i počeše škripati zubima na njega.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (51, 7, 55, 'Ali on, pun Duha Svetoga, uprije pogled u nebo i ugleda slavu Božju i Isusa gdje stoji zdesna Bogu');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (51, 7, 56, 'pa reče: \"Evo vidim nebesa otvorena i Sina Čovječjega gdje stoji zdesna Bogu.\"');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (51, 7, 57, 'Vičući iza glasa, oni zatisnuše uši i navališe jednodušno na njega.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (51, 7, 58, 'Izbaciše ga iz grada pa ga kamenovahu. Svjedoci odložiše haljine do nogu mladića koji se zvao Savao.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (51, 7, 59, 'I dok su ga kamenovali, Stjepan je zazivao: \"Gospodine Isuse, primi duh moj!\"');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (51, 7, 60, 'Onda se baci na koljena i povika iza glasa: \"Gospodine, ne uzmi im ovo za grijeh!\" Kada to reče, usnu.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (51, 8, 1, 'Savao je pristao da se Stjepan smakne. U onaj dan navali velik progon na Crkvu u Jeruzalemu. Svi se osim apostola raspršiše po krajevima judejskim i samarijskim.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (51, 8, 2, 'Bogobojazni su ljudi pokopali Stjepana i održali veliko žalovanje za njim.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (51, 8, 3, 'Savao je pak pustošio Crkvu: ulazio je u kuće, odvlačio muževe i žene i predavao ih u tamnicu.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (51, 8, 4, 'Oni dakle što su se raspršili obilazili su navješćujući Riječ.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (51, 8, 5, 'Filip tako siđe u grad samarijski i stade im propovijedati Krista.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (51, 8, 6, 'Mnoštvo je jednodušno prihvaćalo što je Filip govorio slušajući ga i gledajući znamenja koja je činio.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (51, 8, 7, 'Doista, iz mnogih su opsjednutih izlazili nečisti duhovi vičući iza glasa, a ozdravljali su i mnogi uzeti i hromi.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (51, 8, 8, 'Nasta tako velika radost u onome gradu.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (51, 8, 9, 'Čovjek se neki, imenom Šimun, u gradu već duže bavio čarobnjaštvom i opčaravao narod tvrdeći da je neki veliki.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (51, 8, 10, 'Priklanjalo mu se sve, malo i veliko, te govorilo: \"Ovaj je Snaga Božja, zvana Velika.\"');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (51, 8, 11, 'A priklanjahu mu se jer ih je duže vremena opčaravao svojim vradžbinama.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (51, 8, 12, 'Ali kad povjerovaše Filipu koji navješćivaše evanđelje o kraljevstvu Božjemu i o imenu Isusa Krista, krštavahu se - muževi i žene.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (51, 8, 13, 'Povjerova i Šimun te se krsti i osta uz Filipa: bio je zanesen promatrajući znamenja i čudesa koja su se događala.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (51, 8, 14, 'Kad su apostoli u Jeruzalemu čuli da je Samarija prigrlila riječ Božju, poslaše k njima Petra i Ivana.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (51, 8, 15, 'Oni siđoše i pomoliše se za njih da bi primili Duha Svetoga.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (51, 8, 16, 'Jer još ni na koga od njih ne bijaše sišao; bijahu samo kršteni u ime Gospodina Isusa.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (51, 8, 17, 'Tada polagahu ruke na njih i oni primahu Duha Svetoga.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (51, 8, 18, 'Kad Šimun vidje da se polaganjem ruku apostolskih daje Duh, ponudi apostolima novaca');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (51, 8, 19, 'govoreći: \"Dajte i meni tu moć da svatko na koga položim ruke primi Duha Svetoga.\"');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (51, 8, 20, 'Petar mu odvrati: \"Novac tvoj zajedno s tobom propao kad si mislio dar Božji novcima steći!');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (51, 8, 21, 'Nema tebi ovdje dijela ni udjela jer tvoje srce nije pravo pred Bogom!');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (51, 8, 22, 'Obrati se od te opakosti svoje i moli Gospodina ne bi li ti se kako oprostila namisao srca tvoga.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (51, 8, 23, 'Ta gledam te: žučju si gorak i nepravdom okovan.\"');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (51, 8, 24, 'Šimun odgovori: \"Molite i vi za me Gospodina da me ne snađe ništa od toga što rekoste!\"');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (51, 8, 25, 'Oni pak pošto posvjedočiše i dorekoše riječ Gospodnju, vratiše se u Jeruzalem navješćujući evanđelje mnogim selima samarijskim.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (51, 8, 26, 'Anđeo se Gospodnji obrati Filipu: \"Ustani i pođi na jug putom što iz Jeruzalema silazi u Gazu; on je pust.\"');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (51, 8, 27, 'On usta i pođe. Odjednom eto nekog Etiopljanina, dvoranina, visokog dostojanstvenika kandake, kraljice etiopske koji bijaše nad svom njezinom riznicom.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (51, 8, 28, 'Vraćao se iz Jeruzalema, kamo je bio pošao pokloniti se; sjeđaše na svojim kolima i čitaše proroka Izaiju.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (51, 8, 29, 'Duh reče Filipu: \"Pođi i pridruži se tim kolima!\"');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (51, 8, 30, 'Filip pritrča i ču gdje onaj čita Izaiju proroka pa će mu: \"Razumiješ li što čitaš?\"');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (51, 8, 31, 'On odvrati: \"Kako bih mogao ako me tko ne uputi?\" Onda zamoli Filipa da se uspne i sjedne uza nj.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (51, 8, 32, 'A čitao je ovaj odlomak Pisma: Ko ovcu na klanje odvedoše ga, ko janje nijemo pred onim što ga striže on ne otvara svojih usta.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (51, 8, 33, 'U poniženju sud mu je uskraćen. Naraštaj njegov tko da opiše? Da, uklonjen je sa zemlje život njegov.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (51, 8, 34, 'Dvoranin se obrati Filipu pa će mu: \"Molim te, o kome to prorok govori? O sebi ili o kome drugom?');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (51, 8, 35, 'Filip prozbori te mu, pošavši od toga Pisma, navijesti evanđelje: Isusa.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (51, 8, 36, 'Putujući tako, stigoše do neke vode pa će dvoranin: \"Evo vode! Što priječi da se krstim?\"');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (51, 8, 37, '#');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (51, 8, 38, 'Zapovjedi da kola stanu pa obojica, Filip i dvoranin, siđoše u vodu te ga Filip krsti.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (51, 8, 39, 'A kad iziđoše iz vode, Duh Gospodnji ugrabi Filipa te ga dvoranin više ne vidje. On radosno nastavi svojim putom,');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (51, 8, 40, 'a Filip se nađe u Azotu. I kako je prolazio, navješćivaše evanđelje svim gradovima dok ne stiže u Cezareju.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (51, 9, 1, 'Savao pak, sveudilj zadahnut prijetnjom i pokoljem prema učenicima Gospodnjim, pođe k velikomu svećeniku,');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (51, 9, 2, 'zaiska od njega pisma za sinagoge u Damasku, da sve koje nađe od ovoga Puta, muževe i žene, okovane dovede u Jeruzalem.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (51, 9, 3, 'Kad se putujući približi Damasku, iznenada ga obasja svjetlost s neba.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (51, 9, 4, 'Sruši se na zemlju i začu glas što mu govoraše: \"Savle, Savle, zašto me progoniš?\"');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (51, 9, 5, 'On upita: \"Tko si, Gospodine?\" A on će: \"Ja sam Isus kojega ti progoniš!');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (51, 9, 6, 'Nego ustani, uđi u grad i reći će ti se što ti je činiti.\"');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (51, 9, 7, 'Njegovi suputnici ostadoše bez riječi: čuli su doduše glas, ali ne vidješe nikoga.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (51, 9, 8, 'Savao usta sa zemlje. Otvorenih očiju nije ništa vidio pa ga povedu za ruku i uvedu u Damask.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (51, 9, 9, 'Tri dana nije vidio, nije jeo ni pio.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (51, 9, 10, 'U Damasku bijaše neki učenik imenom Ananija. Njemu u viđenju reče Gospodin: \"Ananija!\" On se odazva: \"Evo me, Gospodine!\"');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (51, 9, 11, 'A Gospodin će mu: \"Ustani, pođi u ulicu zvanu Ravna i u kući Judinoj potraži Taržanina imenom Savla. Eno, moli se;');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (51, 9, 12, 'i u viđenju vidje čovjeka imenom Ananiju gdje ulazi i polaže na nj ruke da bi progledao.\"');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (51, 9, 13, 'Ananija odgovori: \"Gospodine, od mnogih sam čuo o tom čovjeku kolika je zla tvojim svetima učinio u Jeruzalemu.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (51, 9, 14, 'On ima od velikih svećenika i punomoć okovati sve koji prizivlju ime tvoje.\"');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (51, 9, 15, 'Gospodin mu odvrati: \"Pođi jer on mi je oruđe izabrano da ponese ime moje pred narode i kraljeve i sinove Izraelove.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (51, 9, 16, 'Ja ću mu uistinu pokazati koliko mu je za ime moje trpjeti.\"');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (51, 9, 17, 'Ananija ode, uđe u kuću, položi na nj ruke i reče: \"Savle, brate! Gospodin, Isus koji ti se ukaza na putu kojim si išao, posla me da progledaš i napuniš se Duha Svetoga.\"');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (51, 9, 18, 'I odmah mu s očiju spade nešto kao ljuske te on progleda pa usta, krsti se');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (51, 9, 19, 'i uzevši hrane, okrijepi se. Nekoliko dana provede s učenicima u Damasku.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (51, 9, 20, 'te odmah stade po sinagogama propovijedati Isusa, da je on Sin Božji.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (51, 9, 21, 'Koji ga god slušahu, izvan sebe govorahu: \"Nije li ovo onaj koji je u Jeruzalemu istrebljivao sve koji Ime ovo prizivlju, pa i ovamo zato došao da ih okovane odvede pred velike svećenike?\"');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (51, 9, 22, 'Savao pak, sve silniji, zbunjivaše Židove koji prebivahu u Damasku dokazujući: \"Ovo je Krist!\"');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (51, 9, 23, 'Pošto je minulo podosta vremena, odluče Židovi pogubiti ga,');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (51, 9, 24, 'ali Savao dozna za njihov naum. Nadzirahu i vrata danju i noću da bi ga pogubili,');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (51, 9, 25, 'ali ga učenici noću uzeše i preko zidina oprezno spustiše u košari.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (51, 9, 26, 'Kad je Savao došao u Jeruzalem, gledao se pridružiti učenicima, ali ga se svi bojahu: nisu vjerovali da je učenik.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (51, 9, 27, 'Tada ga Barnaba uze i povede k apostolima te im pripovjedi kako je Savao na putu vidio Gospodina koji mu je govorio i kako je u Damasku smjelo propovijedao u ime Isusovo.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (51, 9, 28, 'Od tada se s njima slobodno kretao po Jeruzalemu i smjelo propovijedao u ime Gospodnje.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (51, 9, 29, 'Govorio je i raspravljao sa Židovima grčkog jezika pa i oni snovahu pogubiti ga.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (51, 9, 30, 'Saznala to braća pa ga odvedoše u Cezareju i uputiše u Tarz.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (51, 9, 31, 'Crkva je po svoj Judeji, Galileji i Samariji uživala mir, izgrađivala se i napredovala u strahu Gospodnjem te rasla utjehom Svetoga Duha.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (51, 9, 32, 'Jednom Petar, obilazeći posvuda, siđe i k svetima u Lidi.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (51, 9, 33, 'Ondje nađe nekog čovjeka imenom Eneja, koji je osam godina ležao na postelji: bijaše uzet.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (51, 9, 34, 'Reče mu Petar: \"Eneja, ozdravlja te Isus Krist! Ustani i prostri sam sebi!\" On umah usta.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (51, 9, 35, 'Vidješe to svi žitelji Lide i Šarona te se obratiše Gospodinu.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (51, 9, 36, 'U Jopi pak bijaše učenica imenom Tabita, što prevedeno znači Košuta. Bijaše ona bogata dobrim djelima i milostinjama što ih je dijelila.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (51, 9, 37, 'Upravo u one dane obolje i umrije. Pošto je operu, izlože je u gornjoj sobi.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (51, 9, 38, 'A kako je Lida blizu Jope, učenici čuše da je Petar ondje i poslaše k njemu dva čovjeka s molbom: \"Dođi k nama, ne oklijevaj!\"');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (51, 9, 39, 'Petar usta i krenu s njima. Čim stiže, odvedoše ga u gornju sobu. Okružiše ga sve udovice te mu plačući pokazivahu haljine i odijela što ih je Košuta izrađivala dok je još bila s njima.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (51, 9, 40, 'Petar sve istjera van, kleknu, pomoli se pa se okrenu prema tijelu i reče: \"Tabita, ustani!\" Ona otvori oči, pogleda Petra i sjede.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (51, 9, 41, 'On joj pruži ruku i pridiže je. Onda pozove svete i udovice pa im je pokaza živu.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (51, 9, 42, 'Dozna se za to po svoj Jopi te mnogi povjerovaše u Gospodina.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (51, 9, 43, 'Petar osta neko vrijeme u Jopi u nekog Šimuna kožara.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (51, 10, 1, 'U Cezareji bijaše neki čovjek imenom Kornelije, satnik takozvane italske čete,');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (51, 10, 2, 'pobožan i bogobojazan sa svim svojim domom. Dijelio je mnoge milostinje narodu i bez prestanka se molio Bogu.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (51, 10, 3, 'U viđenju negdje oko devete ure dana ugleda on jasno anđela Božjega gdje dolazi k njemu i veli mu: \"Kornelije!\"');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (51, 10, 4, 'Zagleda se u nj pa mu prestrašen reče: \"Što je, Gospodine?\" A on njemu: \"Molitve su tvoje i milostinje uzišle kao žrtva podsjetnica pred Boga.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (51, 10, 5, 'Zato sada pošalji ljude u Jopu i dozovi Šimuna koji se zove Petar.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (51, 10, 6, 'On je gost u nekog Šimuna kožara čija je kuća uz more.\"');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (51, 10, 7, 'Čim ode anđeo koji mu je govorio, pozove on dvojicu slugu i jednoga pobožna, privržena vojnika,');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (51, 10, 8, 'sve im ispripovjedi i posla ih u Jopu.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (51, 10, 9, 'Sutradan, dok su oni putovali i približavali se gradu, oko šeste ure uziđe Petar na krov moliti.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (51, 10, 10, 'Ogladnje i zaželje se jela. Dok mu pripremahu, pade on u zanos.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (51, 10, 11, 'Gleda on nebo rastvoreno i posudu neku poput velika platna: uleknuta s četiri okrajka, silazi na zemlju.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (51, 10, 12, 'U njoj bijahu svakovrsni četveronošci, gmazovi zemaljski i ptice nebeske.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (51, 10, 13, 'I glas će mu neki: \"Ustaj, Petre! Kolji i jedi!\"');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (51, 10, 14, 'Petar odvrati: \"Nipošto, Gospodine! Ta nikad još ne okusih ništa okaljano i nečisto\".');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (51, 10, 15, 'A glas će mu opet, po drugi put: \"Što Bog očisti, ti ne zovi okaljanim!\"');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (51, 10, 16, 'To se ponovi do triput, a onda je posuda ponesena na nebo.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (51, 10, 17, 'Dok se Petar dvoumio što bi imalo značiti viđenje koje vidje, eto ljudi koje je poslao Kornelije: pošto se raspitaše za Šimunovu kuću, pojave se na vratima,');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (51, 10, 18, 'zovnu te upitaju je li ondje ugošćen neki Šimun, nazvan Petar.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (51, 10, 19, 'Dok je Petar sveudilj razmišljao o viđenju, reče mu Duh: \"Evo, neka te trojica traže.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (51, 10, 20, 'De ustani, siđi i pođi s njima ne skanjujući se jer ja sam ih poslao.\"');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (51, 10, 21, 'Petar siđe k ljudima i reče: \"Evo me! Ja sam onaj kojega tražite! Zbog čega ste došli?\"');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (51, 10, 22, 'Oni odgovore: \"Satnik Kornelije, muž pravedan i bogobojazan, za kojega svjedoči sav narod židovski, primi od svetog anđela naputak da te dozove u dom svoj i čuje od tebe riječi.\"');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (51, 10, 23, 'Tada ih Petar pozva unutra i ugosti. Sutradan usta i krenu s njima; pratila ga neka braća iz Jope.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (51, 10, 24, 'Drugi dan stiže u Cezareju. Kornelije ih je čekao sazvavši rodbinu i prisne prijatelje.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (51, 10, 25, 'Kad je Petar ulazio, pohrli mu Kornelije u susret, padne mu k nogama i pokloni se.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (51, 10, 26, 'Petar ga pridigne govoreći: \"Ustani! I ja sam čovjek.\"');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (51, 10, 27, 'I razgovarajući s njime, uđe i nađe sabrane mnoge');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (51, 10, 28, 'te im reče: \"Vi znate kako je Židovu zabranjeno družiti se sa strancem ili k njemu ulaziti, ali meni Bog pokaza da nikoga ne zovem okaljanim ili nečistim.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (51, 10, 29, 'Stoga, pozvan, i dođoh bez pogovora. Da čujemo dakle zbog čega me pozvaste!\"');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (51, 10, 30, 'Kornelije reče: \"Prije četiri dana baš u ovo doba, o devetoj uri, molio sam se u kući kad gle: čovjek neki u sjajnoj odjeći stane preda me');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (51, 10, 31, 'i reče: \'Kornelije, uslišana ti je molitva i milostinje su tvoje spomenute pred Bogom!');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (51, 10, 32, 'Pošalji dakle u Jopu i dozovi Šimuna koji se zove Petar. On je gost u kući Šimuna kožara uz more.\'');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (51, 10, 33, 'Odmah sam dakle poslao k tebi, a ti si dobro učinio što si došao. Evo nas dakle sviju pred Bogom da čujemo sve što ti zapovjedi Gospodin!\"');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (51, 10, 34, 'Petar tada prozbori i reče: \"Sad uistinu shvaćam da Bog nije pristran,');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (51, 10, 35, 'nego - u svakom je narodu njemu mio onaj koji ga se boji i čini pravdu.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (51, 10, 36, 'Riječ posla sinovima Izraelovim navješćujući im evanđelje: mir po Isusu Kristu; on je Gospodar sviju.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (51, 10, 37, 'Vi znate što se događalo po svoj Judeji, počevši od Galileje, nakon krštenja koje je propovijedao Ivan:');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (51, 10, 38, 'kako Isusa iz Nazareta Bog pomaza Duhom Svetim i snagom, njega koji je, jer Bog bijaše s njime, prošao zemljom čineći dobro i ozdravljajući sve kojima bijaše ovladao đavao.\"');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (51, 10, 39, '\"Mi smo svjedoci svega što on učini u zemlji judejskoj i Jeruzalemu. I njega smakoše, objesivši ga na drvo!');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (51, 10, 40, 'Bog ga uskrisi treći dan i dade mu da se očituje -');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (51, 10, 41, 'ne svemu narodu, nego svjedocima od Boga predodređenima - nama koji smo s njime zajedno jeli i pili pošto uskrsnu od mrtvih.\"');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (51, 10, 42, '\"On nam i naloži propovijedati narodu i svjedočiti: Ovo je onaj kojega Bog postavi sucem živih i mrtvih!\"');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (51, 10, 43, '\"Za nj svjedoče svi proroci: da tko god u nj vjeruje, po imenu njegovu prima oproštenje grijeha.\"');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (51, 10, 44, 'Dok je Petar još govorio te riječi, siđe Duh Sveti na sve koji su slušali tu besjedu.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (51, 10, 45, 'A vjernici iz obrezanja, koji dođoše zajedno s Petrom, začudiše se što se i na pogane izlio dar Duha Svetoga.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (51, 10, 46, 'Jer čuli su ih govoriti drugim jezicima i veličati Boga. Tada Petar reče:');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (51, 10, 47, '\"Može li tko uskratiti vodu da se ne krste ovi koji su primili Duha Svetoga kao i mi?\"');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (51, 10, 48, 'I zapovjedi da se krste u ime Isusa Krista. Tada ga zamole da ostane ondje nekoliko dana.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (51, 10, 49, '');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (51, 11, 1, 'Dočuli apostoli i braća po Judeji da i pogani primiše riječ Božju');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (51, 11, 2, 'pa kad Petar uziđe u Jeruzalem, uzeše mu obrezanici prigovarati:');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (51, 11, 3, '\"Ušao si, dobacivahu, k ljudima neobrezanima i jeo s njima!\"');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (51, 11, 4, 'Onda započe Petar te im izloži sve po redu:');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (51, 11, 5, '\"Molio sam se, reče, u Jopi kadli u zanosu ugledam viđenje: posudu neku poput velika platna, uleknuta s četiri okrajka, gdje silazi s neba i dolazi do mene.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (51, 11, 6, 'Zagledah se, promotrih je i vidjeh četvoronošce zemaljske, zvijeri i gmazove te ptice nebeske.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (51, 11, 7, 'Začuh i glas koji mi govoraše: \'Ustaj, Petre! Kolji i jedi!\'');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (51, 11, 8, 'Ja odvratih: \'Nipošto, Gospodine! Ta nikad mi još ništa okaljano ili nečisto ne uđe u usta.\'');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (51, 11, 9, 'A glas će s neba po drugi put: \'Što Bog očisti, ti ne zovi nečistim.\'');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (51, 11, 10, 'To se ponovi do triput, a onda se sve opet povuče na nebo.\"');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (51, 11, 11, '\"I odmah se, evo, pred kućom u kojoj bijah pojaviše tri čovjeka poslana iz Cezareje k meni.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (51, 11, 12, 'A Duh mi reče da pođem s njima ništa ne premišljajući. Sa mnom pođoše i ova šestorica braće te uđosmo u kuću tog čovjeka.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (51, 11, 13, 'On nam pripovjedi kako je u svojoj kući vidio anđela koji je stao preda nj i rekao: \'Pošalji u Jopu i dozovi Šimuna nazvanog Petar;');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (51, 11, 14, 'on će ti navijestiti riječi po kojima ćeš se spasiti ti i sav dom tvoj.\'\"');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (51, 11, 15, '\"I kad počeh govoriti, siđe na njih Duh Sveti kao ono na nas u početku.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (51, 11, 16, 'Sjetih se tada riječi Gospodnje: \'Ivan je, govoraše on, krstio vodom, a vi ćete biti kršteni Duhom Svetim.\'');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (51, 11, 17, 'Ako im je dakle Bog dao isti dar kao i nama koji povjerovasmo u Gospodina Isusa Krista, tko sam ja da bih se smio oprijeti Bogu?\"');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (51, 11, 18, 'Kad su to čuli, umiriše se te stadoše slaviti Boga govoreći: \"Dakle i poganima Bog dade obraćenje na život!\"');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (51, 11, 19, 'Oni dakle što ih rasprši nevolja nastala u povodu Stjepana dopriješe do Fenicije, Cipra i Antiohije, nikomu ne propovijedajući Riječi doli samo Židovima.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (51, 11, 20, 'Neki su od njih bili Ciprani i Cirenci. Kad stigoše u Antiohiju, propovijedahu i Grcima navješćujući evanđelje: Gospodina, Isusa.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (51, 11, 21, 'Ruka Gospodnja bijaše s njima te velik broj ljudi povjerova i obrati se Gospodinu.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (51, 11, 22, 'Vijest o tome doprije do Crkve u Jeruzalemu pa poslaše Barnabu u Antiohiju.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (51, 11, 23, 'Kad on stiže i vidje milost Božju, obradova se te potaknu sve da u odlučnosti srca ostanu uz Gospodina.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (51, 11, 24, 'Ta bijaše to muž čestit, pun Duha Svetoga i vjere. Znatno se mnoštvo prikloni Gospodinu.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (51, 11, 25, 'Barnaba se zatim zaputi u Tarz potražiti Savla.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (51, 11, 26, 'Kad ga nađe, odvede ga u Antiohiju. Punu su se godinu dana sastajali u toj Crkvi i poučavali poveće mnoštvo te se u Antiohiji učenici najprije prozvaše kršćanima.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (51, 11, 27, 'U one dane dođoše u Antiohiju neki proroci iz Jeruzalema.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (51, 11, 28, 'Jedan od njih, imenom Agab, usta i po Duhu pretkaza da će uskoro nastati velika glad po svem svijetu. Ona i nasta za Klaudija.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (51, 11, 29, 'Stoga će svatko od učenika, odlučiše, koliko smogne poslati da se posluži braći u Judeji.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (51, 11, 30, 'To i učiniše te poslaše starješinama po Barnabi i Savlu.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (51, 12, 1, 'U to vrijeme uze Herod zlostavljati neke od Crkve.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (51, 12, 2, 'Mačem pogubi Jakova, brata Ivanova.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (51, 12, 3, 'Kad vidje da je to drago Židovima, uhvati i Petra (bijahu upravo Dani beskvasnih kruhova).');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (51, 12, 4, 'Uhiti ga, baci u tamnicu i dade da ga čuvaju četiri vojničke četverostraže, nakan izvesti ga nakon Pashe pred narod.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (51, 12, 5, 'Petra su dakle čuvali u tamnici, a Crkva se svesrdno moljaše Bogu za njega.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (51, 12, 6, 'One noći kad ga je Herod kanio privesti, spavao je Petar između dva vojnika, okovan dvojim verigama, a stražari pred vratima čuvahu stražu.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (51, 12, 7, 'Kad eto: pojavi se anđeo Gospodnji te svjetlost obasja ćeliju. Anđeo udari Petra u rebra, probudi ga i reče: \"Ustaj brzo!\" I spadoše mu verige s ruku.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (51, 12, 8, 'Anđeo mu reče: \"Opaši se i priveži obuću!\" On učini tako. Onda će mu anđeo: \"Zaogrni se i hajde za mnom!\"');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (51, 12, 9, 'Petar izađe, pođe za njim, a nije znao da je zbilja što se događa po anđelu: činilo mu se da gleda viđenje.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (51, 12, 10, 'Prošavši prvu stražu, i drugu, dođoše do željeznih vrata koja vode u grad. Ona im se sama otvore te oni izađu, prođu jednu ulicu, a onda anđeo odjednom odstupi od njega.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (51, 12, 11, 'Petar pak, došavši k sebi, reče: \"Sad uistinu znam da je Gospodin poslao anđela svoga i izbavio me iz Herodove ruke i od svega što je očekivao židovski narod.\"');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (51, 12, 12, 'Kad je to uočio, zaputi se kući Marije, majke Ivana nazvanog Marko. Ondje se mnogi bijahu sabrali i molili.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (51, 12, 13, 'Kad Petar pokuca na dvorišna vrata, dođe prisluhnuti sluškinja imenom Ruža.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (51, 12, 14, 'Kad prepozna Petrov glas, od radosti i ne otvori vrata, nego utrča i javi da je Petar pred vratima.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (51, 12, 15, 'Oni joj rekoše: \"Mahnitaš!\" Ali je ona uporno tvrdila da je tako. Nato će oni: \"Bit će njegov anđeo!\"');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (51, 12, 16, 'Petar nastavi kucati. Kad napokon otvoriše i ugledaše ga, ostadoše izvan sebe.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (51, 12, 17, 'On im rukom mahnu neka šute pa im pripovjedi kako ga Gospodin izvede iz tamnice te dometnu: \"Javite to Jakovu i braći!\" Onda izađe i ode u drugo mjesto.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (51, 12, 18, 'Kad se razdani, nasta među vojnicima uzbuna nemalena što li se s Petrom dogodilo.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (51, 12, 19, 'Herod ga stade tražiti, a kad ga ne nađe, sasluša stražare i naredi da se smaknu. Onda siđe iz Judeje u Cezareju i ondje osta.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (51, 12, 20, 'A bio je u žestoku sukobu s Tircima i Sidoncima. Oni zajednički dođoše k njemu i pošto pridobiše kraljevskoga komornika Blasta, zaiskaše mir, jer je njihova zemlja dobivala živež od kraljeve.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (51, 12, 21, 'U određeni dan sjede Herod odjeven u kraljevsko ruho na prijestol i stade im govoriti.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (51, 12, 22, 'Narod izvikivaše: \"Božji glas, a ne ljudski!\"');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (51, 12, 23, 'Umah ga, zbog toga što ne dade slavu Bogu, udari anđeo Gospodnji te on rascrvotočen izdahnu.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (51, 12, 24, 'Riječ je pak Božja rasla i širila se.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (51, 12, 25, 'Barnaba i Savao, pošto obaviše služenje u Jeruzalemu, vratiše se uzevši sa sobom Ivana zvanog Marko.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (51, 13, 1, 'U antiohijskoj je Crkvi bilo proroka i učitelja: Barnaba, Šimun zvani Niger, Lucije Cirenac, Manahen, suothranjenik Heroda četverovlasnika, i Savao.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (51, 13, 2, 'Dok su jednom obavljali službu Božju i postili, reče Duh Sveti: \"De mi odlučite Barnabu i Savla za djelo na koje sam ih pozvao.\"');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (51, 13, 3, 'Onda su postili, molili, položili na njih ruke i otpustili ih.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (51, 13, 4, 'Poslani od Svetoga Duha siđu u Seleuciju, a odande odjedre na Cipar.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (51, 13, 5, 'Kad se nađoše u Salamini, navješćivahu riječ Božju u židovskim sinagogama. Imali su i Ivana za poslužitelja.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (51, 13, 6, 'Pošto pak prođoše sav otok do Pafa, nađoše nekog vračara, nazoviproroka, Židova, imenom Barjesu.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (51, 13, 7, 'On bijaše uz namjesnika Sergija Pavla, čovjeka razborita. Sergije dozva Barnabu i Savla te zaiska čuti riječ Božju,');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (51, 13, 8, 'ali im se usprotivi Elim, Vračar - tako mu se ime prevodi - nastojeći odvratiti namjesnika od vjere.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (51, 13, 9, 'Savao pak, zvan i Pavao, pun Duha Svetoga, ošinu ga pogledom');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (51, 13, 10, 'i reče: \"Pun svake lukavosti i prevrtljivosti, sine đavolski, neprijatelju svake pravednosti, zar nikako da prestaneš iskrivljavati ravne putove Gospodnje?');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (51, 13, 11, 'Evo stoga sada ruke Gospodnje na tebi: oslijepljet ćeš i neko vrijeme nećeš gledati sunca!\" Odmah pade na nj mrak i tama te on glavinjajući stade tražiti ruke vodilje.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (51, 13, 12, 'Videći što se dogodilo, povjerova tada namjesnik, zanesen naukom Gospodnjim.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (51, 13, 13, 'Pošto se Pavao i oni oko njega otisnuše od Pafa, stigoše u Pergu pamfilijsku. Ivan ih napusti te se vrati u Jeruzalem.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (51, 13, 14, 'Oni pak krenuše iz Perge i stigoše u Antiohiju pizidijsku. U dan subotni ušli su u sinagogu i sjeli.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (51, 13, 15, 'Nakon čitanja Zakona i Proroka pošalju nadstojnici sinagoge k njima: \"Braćo, rekoše, ima li u vas koja riječ utjehe za narod, govorite!\"');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (51, 13, 16, 'Nato usta Pavao, dadne rukom znak i reče: \"Izraelci i vi koji se Boga bojite, čujte!');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (51, 13, 17, 'Bog naroda ovoga, Izraela, izabra oce naše i uzdiže narod za boravka u zemlji egipatskoj te ga ispruženom rukom izvede iz nje.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (51, 13, 18, 'Oko četrdeset ga je godina na rukama nosio u pustinji');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (51, 13, 19, 'pa pošto zatre sedam naroda u zemlji kanaanskoj, ubaštini ga u zemlji njihovoj');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (51, 13, 20, 'za kakve četiri stotine i pedeset godina. Nakon toga dade im suce - do Samuela proroka.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (51, 13, 21, 'Onda zaiskaše kralja pa im Bog za četrdeset godina dade Šaula, sina Kiševa, iz plemena Benjaminova.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (51, 13, 22, 'Pošto svrgnu njega, podiže im za kralja Davida za kojega posvjedoči: Nađoh Davida, sina Jišajeva, čovjeka po svom srcu, koji će ispuniti sve moje želje.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (51, 13, 23, 'Iz njegova potomstva izvede Bog po svom obećanju Izraelu Spasitelja, Isusa.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (51, 13, 24, 'Pred njegovim je dolaskom Ivan propovijedao krštenje obraćenja svemu narodu izraelskomu.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (51, 13, 25, 'A kad je Ivan dovršavao svoju trku, govorio je: \'Nisam ja onaj za koga me vi držite. Nego za mnom evo dolazi onaj komu ja nisam dostojan odriješiti obuće na nogama.\'\"');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (51, 13, 26, '\"Braćo, sinovi roda Abrahamova, vi i oni koji se među vama Boga boje, nama je upravljena ova Riječ spasenja.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (51, 13, 27, 'Doista, žitelji Jeruzalema i glavari njihovi ne upoznaše njega ni riječi proročkih što se čitaju svake subote pa ih, osudivši ga, ispuniše.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (51, 13, 28, 'Premda ne nađoše nikakva razloga smrti, zatražiše od Pilata da ga smakne.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (51, 13, 29, 'Pošto pak izvršiše sve što je o njemu napisano, skinuše ga s drveta i položiše u grob.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (51, 13, 30, 'Ali Bog ga uskrisi od mrtvih.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (51, 13, 31, 'On se mnogo dana ukazivao onima koji s njim bijahu uzašli iz Galileje u Jeruzalem. Oni su sada njegovi svjedoci pred narodom.\"');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (51, 13, 32, '\"I mi vam navješćujemo evanđelje: obećanje dano ocima');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (51, 13, 33, 'Bog je ispunio djeci, nama, uskrisivši Isusa, kao što je i pisano u Psalmu drugom: Ti si Sin moj, danas te rodih.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (51, 13, 34, 'Da ga pak uskrisi od mrtvih te se on više nikad neće vratiti u trulež, rekao je ovime: Dat ću vama svetinje Davidove, pouzdane.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (51, 13, 35, 'Zato i na drugome mjestu kaže: Nećeš dati da Svetac tvoj ugleda truleži.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (51, 13, 36, 'David doista, pošto u svom naraštaju posluži volji Božjoj, preminu, pridruži se ocima svojim i vidje trulež,');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (51, 13, 37, 'a Onaj koga Bog uskrisi ne vidje truleži.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (51, 13, 38, '/');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (51, 13, 39, 'Neka vam dakle braćo, znano bude: po Ovome vam se navješćuje oproštenje grijeha! Po Ovome se tko god vjeruje, opravdava od svega od čega se po Mojsijevu zakonu niste mogli opravdati!');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (51, 13, 40, 'Pazite da se ne zbude što je rečeno u Prorocima:');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (51, 13, 41, 'Obazrite se, preziratelji, snebijte se i nestanite! Jer djelo činim u dane vaše, djelo u koje ne biste vjerovali da vam ga tko ispriča.\"');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (51, 13, 42, 'Na izlasku su ih molili da im iduće subote o tome govore.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (51, 13, 43, 'A pošto se skup raspustio, mnogi Židovi i bogobojazne pridošlice pođoše za Pavlom i Barnabom koji su ih nagovarali ustrajati u milosti Božjoj.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (51, 13, 44, 'Iduće se subote gotovo sav grad zgrnu čuti riječ Gospodnju.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (51, 13, 45, 'Kad su Židovi ugledali mnoštvo, puni zavisti psujući suprotstavljali su se onomu što je Pavao govorio.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (51, 13, 46, 'Na to im Pavao i Barnaba smjelo rekoše: \"Trebalo je da se najprije vama navijesti riječ Božja. Ali kad je odbacujete i sami sebe ne smatrate dostojnima života vječnoga, obraćamo se evo poganima.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (51, 13, 47, 'Jer ovako nam je zapovjedio Gospodin: Postavih te za svjetlost poganima, da budeš na spasenje do nakraj zemlje.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (51, 13, 48, 'Pogani koji su slušali radovali su se i slavili riječ Gospodnju te povjerovaše oni koji bijahu određeni za život vječni.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (51, 13, 49, 'Riječ se pak Gospodnja pronese po svoj onoj pokrajini.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (51, 13, 50, 'Ali Židovi potakoše ugledne bogobojazne žene i prvake gradske te zametnuše progon protiv Pavla i Barnabe pa ih izbaciše iz svoga kraja.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (51, 13, 51, 'Oni pak stresu prašinu s nogu protiv njih pa odu u Ikonij.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (51, 13, 52, 'A učenici su se ispunjali radošću i Duhom Svetim.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (51, 14, 1, 'U Ikoniju isto tako uđoše u židovsku sinagogu i govorahu tako da povjerova veliko mnoštvo Židova i Grka.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (51, 14, 2, 'Ali nepokorni Židovi razdražiše i podjariše pogane protiv braće.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (51, 14, 3, 'Oni se ipak zadržaše duže vremena, smjeli u Gospodinu koji je svjedočio za Riječ milosti svoje, davao da se po njihovim rukama događaju znamenja i čudesa.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (51, 14, 4, 'Mnoštvo se gradsko podvoji: jedni bijahu za Židove, drugi za apostole.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (51, 14, 5, 'Pogani i Židovi sa svojim glavarima navališe da zlostave i kamenuju apostole.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (51, 14, 6, 'Kada to opaziše, prebjegoše oni u likaonske gradove Listru i Derbu i okolicu.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (51, 14, 7, 'Ondje su navješćivali evanđelje.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (51, 14, 8, 'U Listri je sjedio neki čovjek uzetih nogu, hrom od majčine utrobe; nikada nije hodao.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (51, 14, 9, 'Čuo je Pavla gdje govori.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (51, 14, 10, 'Pavao ga pronikne pogledom, vidje da ima vjeru u spasenje pa mu iza glasa reče: \"Uspravi se na noge!\" On skoči i prohoda.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (51, 14, 11, 'Kad mnoštvo ugleda što učini Pavao, povika likaonski: \"Bogovi u ljudskom obličju siđoše k nama!\"');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (51, 14, 12, 'I nazvaše Barnabu Zeusom, a Pavla Hermesom jer je Pavao vodio riječ.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (51, 14, 13, 'A svećenik Zeusa Predgradskoga dovede pred vrata bikove i vijence te u zajednici s narodom htjede žrtvovati.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (51, 14, 14, 'Kada su to dočuli apostoli Barnaba i Pavao, razdriješe haljine i uletješe u narod vičući:');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (51, 14, 15, '\"Ljudi, što to radite? I mi smo smrtnici, baš kao i vi! Navješćujemo vam da se od tih ispraznosti obratite k Bogu živomu koji stvori nebo i zemlju, more i sve što je u njima.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (51, 14, 16, 'On je u prošlim naraštajima pustio da svi pogani pođu svojim putovima.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (51, 14, 17, 'Ipak ne ostavi sebe neposvjedočena: dobročinstva iskazuje, s neba vam kišu daje i vremena plodonosna, napunja hranom i radošću srca vaša.\"');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (51, 14, 18, 'I tako govoreći, jedva sklonuše mnoštvo da im ne žrtvuje.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (51, 14, 19, 'Uto iz Antiohije i Ikonija nadođu neki Židovi, pridobiju svjetinu te kamenuju Pavla i odvuku ga izvan grada misleći da je mrtav.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (51, 14, 20, 'Kad ga pak okružiše učenici, usta on i uđe u grad. Sutradan ode s Barnabom u Derbu.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (51, 14, 21, 'Pošto navijestiše evanđelje tomu gradu i mnoge učiniše učenicima, vratiše se u Listru, u Ikonij i u Antiohiju.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (51, 14, 22, 'Učvršćivali su duše učenika bodreći ih da ustraju u vjeri jer da nam je kroz mnoge nevolje ući u kraljevstvo Božje.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (51, 14, 23, 'Postavljali su im po crkvama starješine te ih, nakon molitve i posta, povjeravahu Gospodinu u kojega su povjerovali.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (51, 14, 24, 'Pošto su prešli Pizidiju, stigoše u Pamfiliju.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (51, 14, 25, 'U Pergi navijestiše Riječ pa siđu u Ataliju.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (51, 14, 26, 'Odande pak odjedriše u Antiohiju, odakle ono bijahu povjereni milosti Božjoj za djelo koje izvršiše.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (51, 14, 27, 'Kada stigoše, sabraše Crkvu i pripovjediše što sve učini Bog po njima: da i poganima otvori vrata vjere.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (51, 14, 28, 'I proveli su nemalo vremena s učenicima.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (51, 15, 1, 'Uto neki siđoše iz Judeje i počeše učiti braću: \"Ako se ne obrežete po običaju Mojsijevu, ne možete se spasiti.\"');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (51, 15, 2, 'Kad između njih te Pavla i Barnabe nasta prepirka i raspra nemalena, odrediše da Pavao i Barnaba i još neki drugi između njih uzađu u Jeruzalem k apostolima i starješinama poradi tog pitanja.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (51, 15, 3, 'Oni su dakle, ispraćeni od Crkve, prolazili kroz Feniciju i Samariju pripovijedajući o obraćenju pogana i donoseći svoj braći veliku radost.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (51, 15, 4, 'Kada pak stigoše u Jeruzalem, primi ih Crkva, apostoli i starješine. Ispripovjediše što sve Bog učini po njima.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (51, 15, 5, 'Onda ustanu neki od onih što iz farizejske sljedbe bijahu prigrlili vjeru pa reknu: \"Treba ih obrezati i zapovjediti im da opslužuju Zakon Mojsijev.\"');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (51, 15, 6, 'Nato se apostoli i starješine sastanu da to razmotre.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (51, 15, 7, 'Nakon duge raspre ustade Petar i reče im: \"Braćo, vi znate kako me Bog od najprvih dana između vas izabra da iz mojih usta pogani čuju riječ evanđelja i uzvjeruju.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (51, 15, 8, 'I Bog, Poznavatelj srdaca, posvjedoči za njih: dade im Duha Svetoga kao i nama.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (51, 15, 9, 'Nikakve razlike nije pravio između nas i njih: vjerom očisti njihova srca.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (51, 15, 10, 'Što dakle sada iskušavate Boga stavljajući učenicima na vrat jaram kojeg ni oci naši ni mi nismo mogli nositi?');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (51, 15, 11, 'Vjerujemo, naprotiv: po milosti smo Gospodina Isusa spašeni, baš kao i oni.\"');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (51, 15, 12, 'Nato sve mnoštvo umuknu. Slušali su Barnabu i Pavla koji pripovjedahu kolika je znamenja i čudesa Bog po njima učinio među poganima.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (51, 15, 13, 'Kad oni ušutješe, progovori Jakov: \"Poslušajte me, braćo!');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (51, 15, 14, 'Šimun je izložio kako se Bog već na početku pobrinu između pogana uzeti narod imenu svojemu.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (51, 15, 15, 'S time su u skladu riječi Proroka. Ovako je doista pisano:');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (51, 15, 16, 'Nakon toga vratit ću se i opet podići pali šator Davidov, iz ruševina ga podići, opet ga sazidati');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (51, 15, 17, 'da preostali ljudi potraže Gospodina i svi pogani na koje je zazvano ime moje, govori Gospodin, koji to');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (51, 15, 18, 'obznanjuje odvijeka.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (51, 15, 19, 'Zato smatram da ne valja dodijavati onima koji se s poganstva obraćaju k Bogu,');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (51, 15, 20, 'nego im poručiti da se uzdržavaju od mesa okaljana idolima, od bludništva, od udavljenoga i od krvi.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (51, 15, 21, 'Ta Mojsije od pradavnih naraštaja ima po gradovima propovjednike koji ga u sinagogama svake subote čitaju.\"');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (51, 15, 22, 'Tad apostoli i starješine zajedno sa svom Crkvom zaključe izabrati neke muževe između sebe i poslati ih u Antiohiju s Pavlom i Barnabom. Bijahu to Juda zvani Barsaba, i Sila, muževi vodeći među braćom.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (51, 15, 23, 'Po njima pošalju ovo pismo: \"Apostoli i starješine, braća, braći iz poganstva po Antiohiji, Siriji i Ciliciji - pozdrav!\"');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (51, 15, 24, '\"Budući da smo čuli kako vas neki od naših, ali bez našega naloga, nekakvim izjavama smetoše i duše vam uznemiriše,');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (51, 15, 25, 'zaključismo jednodušno izabrati neke muževe i poslati ih k vama zajedno s našim ljubljenim Barnabom i Pavlom,');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (51, 15, 26, 'ljudima koji su svoje živote izložili za ime Gospodina našega Isusa Krista.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (51, 15, 27, 'Šaljemo vam dakle Judu i Silu. Oni će vam i usmeno priopćiti to isto.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (51, 15, 28, 'Zaključismo Duh Sveti i mi ne nametati vam nikakva tereta osim onoga što je potrebno:');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (51, 15, 29, 'uzdržavati se od mesa žrtvovana idolima, od krvi, od udavljenoga i od bludništva. Budete li se toga držali, dobro ćete učiniti. Živjeli!\"');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (51, 15, 30, 'Oni su se dakle oprostili i sišli u Antiohiju; sabrali su mnoštvo i predali pismo.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (51, 15, 31, 'Kad ga pročitaše, svi se obradovaše zbog ohrabrenja.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (51, 15, 32, 'Juda i Sila, i sami proroci, mnogim riječima ohrabriše i utvrdiše braću.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (51, 15, 33, 'Neko se vrijeme zadrže pa se onda s mirom od braće vrate onima koji ih poslaše.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (51, 15, 34, '#');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (51, 15, 35, 'A Pavao i Barnaba ostadoše u Antiohiji naučavajući i navješćujući zajedno s mnogima drugima riječ Gospodnju.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (51, 15, 36, 'Nakon nekog vremena reče Pavao Barnabi: \"Vratimo se i pohodimo braću po svim gradovima u kojima smo navješćivali riječ Gospodnju, da vidimo kako su!\"');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (51, 15, 37, 'Barnaba je htio povesti i Ivana zvanog Marko.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (51, 15, 38, 'Pavao pak nije smatrao uputnim sa sobom voditi onoga koji se u Pamfiliji odvojio od njih te nije s njima pošao na djelo.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (51, 15, 39, 'Spopade ih takva ogorčenost da se raziđoše: Barnaba povede Marka i otplovi na Cipar,');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (51, 15, 40, 'a Pavao sebi izabra Silu pa od braće povjeren milosti Gospodnjoj');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (51, 15, 41, 'proputova Siriju i Ciliciju, utvrđujući Crkve.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (51, 16, 1, 'Stiže tako u Derbu i Listru. Ondje, gle, bijaše učenik neki imenom Timotej, sin neke pokrštene Židovke i oca Grka.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (51, 16, 2, 'Uživao je dobar glas među braćom u Listri i Ikoniju.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (51, 16, 3, 'Pavao htjede da on pođe s njime pa ga uze i obreza zbog Židova koji bijahu u onim mjestima. Jer svi su znali da mu je otac Grk.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (51, 16, 4, 'I kako su prolazili gradovima, predavali su im za opsluživanje odredbe koje su apostoli i starješine utvrdili u Jeruzalemu.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (51, 16, 5, 'Tako se Crkve učvršćivahu u vjeri i broj im se danomice povećavao.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (51, 16, 6, 'Prođoše Frigiju i galacijski kraj jer ih je Duh Sveti spriječio propovijedati riječ u Aziji.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (51, 16, 7, 'Kad su došli do Mizije, htjedoše u Bitiniju, ali im ne dopusti Duh Isusov.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (51, 16, 8, 'Onda prođoše Miziju i siđoše u Troadu.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (51, 16, 9, 'Noću je Pavao imao viđenje: Makedonac neki stajaše i zaklinjaše ga: \"Prijeđi u Makedoniju i pomozi nam!\"');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (51, 16, 10, 'Nakon viđenja nastojasmo odmah otputovati u Makedoniju, uvjereni da nas Bog zove navješćivati im evanđelje.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (51, 16, 11, 'Otplovismo iz Troade i zaputismo se ravno u Samotraku pa sutradan u Neapol,');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (51, 16, 12, 'a odande u naseobinu Filipe - grad prvog dijela Makedonije. U tom se gradu zadržasmo nekoliko dana.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (51, 16, 13, 'U dan subotni iziđosmo izvan gradskih vrata k rijeci, gdje smo mislili da će biti bogomolja. Sjedosmo i stadosmo govoriti okupljenim ženama.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (51, 16, 14, 'Slušala je tako i neka bogobojazna žena imenom Lidija, prodavačica grimiza iz grada Tijatire. Gospodin joj otvori srce, te ona prihvati što je Pavao govorio.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (51, 16, 15, 'Pošto se pak krsti ona i njezin dom, zamoli: \"Ako smatrate da sam vjerna Gospodinu, uđite u moj dom i ostanite u njemu.\" I prisili nas.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (51, 16, 16, 'Jednom nas na putu u bogomolju sretne neka ropkinja koja je imala duha vračarskoga i gatajući donosila veliku dobit svojim gospodarima.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (51, 16, 17, 'Pošla je za Pavlom i za nama te vikala: \"Ovi su ljudi sluge Boga Svevišnjega; navješćuju vam put spasenja.\"');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (51, 16, 18, 'To je činila mnogo dana. Pavlu to napokon dodija pa se okrenu i reče duhu: \"Zapovijedam ti u ime Isusa Krista: iziđi iz nje!\" I iziđe toga časa.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (51, 16, 19, 'Kad njezini gospodari vidješe da im nesta nade u dobit, pograbiše Pavla i Silu te ih odvukoše na trg pred glavare.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (51, 16, 20, 'Privedoše ih pretorima i rekoše: \"Ovi ljudi uznemiruju naš grad. Židovi su');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (51, 16, 21, 'te šire običaje kojih mi Rimljani ne smijemo ni prihvatiti ni držati.\"');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (51, 16, 22, 'Nato svjetina nahrupi na njih, a pretori trgoše s njih odijelo i zapovjediše da se išibaju.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (51, 16, 23, 'Pošto ih izudaraše, bace ih u tamnicu i zapovjede tamničaru da ih pomno čuva.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (51, 16, 24, 'Primivši takvu zapovijed, uze ih on i baci u nutarnju tamnicu, a noge im stavi u klade.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (51, 16, 25, 'Oko ponoći su Pavao i Sila molili pjevajući hvalu Bogu, a uznici ih slušali.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (51, 16, 26, 'Odjednom nasta potres velik te se poljuljaše temelji zatvora, umah se otvoriše sva vrata, i svima spadoše okovi.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (51, 16, 27, 'Tamničar se prenu oda sna pa kad ugleda tamnička vrata otvorena, trgnu mač i samo što se ne ubi misleći da su uznici pobjegli.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (51, 16, 28, 'Ali Pavao povika iza glasa: \"Ne čini sebi nikakva zla! Svi smo ovdje!\"');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (51, 16, 29, 'Onaj nato zaiska svjetlo, uleti i dršćući baci se pred Pavla i Silu;');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (51, 16, 30, 'izvede ih i upita: \"Gospodo, što mi je činiti da se spasim?\"');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (51, 16, 31, 'Oni će mu: \"Vjeruj u Gospodina Isusa i spasit ćeš se - ti i dom tvoj!\"');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (51, 16, 32, 'Onda navijestiše riječ Gospodnju njemu i svima u domu njegovu.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (51, 16, 33, 'Te iste noćne ure uze ih, opra im rane pa se odmah krsti - on i svi njegovi.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (51, 16, 34, 'Onda ih uvede u dom, prostre stol te se zajedno sa svim domom obradova što je povjerovao Bogu.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (51, 16, 35, 'Kad se razdani, poslaše pretori liktore s porukom: \"Pusti te ljude!\"');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (51, 16, 36, 'Tamničar to priopći Pavlu: \"Pretori, reče, poručiše da vas pustim. Iziđite dakle sad i pođite u miru!\"');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (51, 16, 37, 'Nato im Pavao odvrati: \"Javno su nas neosuđene išibali, nas rimske građane, i bacili u tamnicu. A sada da nas potajno izbace? Nipošto, nego neka oni sami dođu i izvedu nas!\"');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (51, 16, 38, 'Liktori to jave pretorima. Oni su se uplašili kada doznaše da su Rimljani.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (51, 16, 39, 'Zato dođu da ih nagovore pa ih izvedu i zamole da odu iz grada.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (51, 16, 40, 'Izišavši iz tamnice, oni pođu k Lidiji, pogledaju i obodre braću pa odu.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (51, 17, 1, 'Prošavši kroz Amfipol i Apoloniju, stigoše u Solun, gdje bijaše židovska sinagoga.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (51, 17, 2, 'Po običaju uđe Pavao onamo. Tri je subote s njima raspravljao na temelju Pisama.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (51, 17, 3, 'Tumačio je i izlagao: \"Trebalo je da Krist trpi i uskrsne od mrtvih. Taj Krist jest Isus koga vam ja navješćujem.\"');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (51, 17, 4, 'Neki se od njih uvjeriše pa se pridružiše Pavlu i Sili; tako i veliko mnoštvo bogobojaznih Grka i nemalo uglednih žena.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (51, 17, 5, 'Židove nato spopade zavist pa pridobiše neke opake uličnjake, potakoše ih i pobuniše grad te nahrupiše u kuću Jasonovu tražeći da se Pavao i Sila izvedu pred narod.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (51, 17, 6, 'Kako ih ne nađoše, odvukoše Jasona i neke od braće pred gradske glavare vičući: \"Evo i ovdje onih koji pobuniše sav svijet.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (51, 17, 7, 'Jason ih je ugostio. Svi oni rade protiv carskih odredaba: tvrde da postoji drugi kralj - Isus.\"');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (51, 17, 8, 'Time uzbuniše svjetinu i glavare koji su to čuli');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (51, 17, 9, 'te oni od Jasona i ostalih uzeše jamčevinu pa ih pustiše.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (51, 17, 10, 'Braća su pak brže-bolje noću odaslala Pavla i Silu u Bereju. Kad su stigli, odoše u židovsku sinagogu.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (51, 17, 11, 'Ovi su Židovi bili plemenitiji od solunskih: primili su Riječ sa svom spremnošću i danomice istraživali Pisma, da li je to tako.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (51, 17, 12, 'Mnogi od njih stoga povjerovaše, a tako i nemalo uglednih grčkih žena i muževa.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (51, 17, 13, 'Ali kad su solunski Židovi doznali da Pavao i u Bereji navješćuje riječ Božju, odoše te i ondje podjariše i uzbuniše svjetinu.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (51, 17, 14, 'Braća tada brže-bolje uputiše Pavla k moru. Sila pak i Timotej ostadoše ondje.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (51, 17, 15, 'Pratioci dovedoše Pavla do Atene pa se vratiše noseći Sili i Timoteju zapovijed da što prije dođu k njemu.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (51, 17, 16, 'Dok ih je u Ateni iščekivao, ogorči se Pavao u duši promatrajući kako je grad pokumiren.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (51, 17, 17, 'Međutim raspravljaše u sinagogi sa Židovima i bogobojaznima, a na trgu svaki dan s onima koji bi se ondje zatekli.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (51, 17, 18, 'Dobacivahu mu i neki od epikurejskih i stoičkih filozofa. Jedni su govorili: \"Što bi htjela reći ta čavka?\" Drugi pak: \"Navješćuje, čini se, neke tuđe bogove.\" Jer navješćivaše Isusa i uskrsnuće.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (51, 17, 19, 'Onda su ga uzeli i odveli na Areopag i upitali: \"Bismo li mogli znati kakav to nov nauk naučavaš?');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (51, 17, 20, 'Čudnovatim nam nekim tvrdnjama uši puniš. Željeli bismo stoga znati što bi to imalo biti.\"');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (51, 17, 21, 'Nijedan Atenjanin ni doseljeni stranac ni na što drugo ne trati vrijeme nego na pripovijedanje i slušanje novosti.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (51, 17, 22, 'Tada Pavao stade posred Areopaga i reče: \"Atenjani! U svemu ste, vidim, nekako veoma bogoljubni.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (51, 17, 23, 'Doista, prolazeći i promatrajući vaše svetinje nađoh i žrtvenik s natpisom: Nepoznatom Bogu. Što dakle ne poznajete, a štujete, to vam ja navješćujem.\"');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (51, 17, 24, '\"Bog koji stvori svijet i sve na njemu, on, neba i zemlje Gospodar, ne prebiva u rukotvorenim hramovima;');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (51, 17, 25, 'i ne poslužuju ga ljudske ruke, kao da bi što trebao, on koji svima daje život, dah i - sve.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (51, 17, 26, 'Od jednoga sazda cijeli ljudski rod da prebiva po svem licu zemlje; ustanovi određena vremena i međe prebivanja njihova');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (51, 17, 27, 'da traže Boga, ne bi li ga kako napipali i našli. Ta nije daleko ni od koga od nas.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (51, 17, 28, 'U njemu doista živimo, mičemo se i jesmo, kao što i neki od vaših pjesnika rekoše: \"Njegov smo čak i rod!\"');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (51, 17, 29, '\"Ako smo dakle rod Božji, ne smijemo smatrati da je božanstvo slično zlatu, srebru ili kamenu, liku isklesanu umijećem i maštom ljudskom.\"');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (51, 17, 30, '\"I ne obazirući se na vremena neznanja, nutka sada Bog ljude da se svi i posvuda obrate');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (51, 17, 31, 'jer ustanovi Dan u koji će suditi svijetu po pravdi, po Čovjeku kojega odredi, pred svima ovjerovi uskrisivši ga od mrtvih.\"');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (51, 17, 32, 'Kad čuše \"uskrsnuće od mrtvih\", jedni se stadoše rugati, a drugi rekoše: \"Još ćemo te o tom slušati!\"');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (51, 17, 33, 'Tako se Pavao povuče od njih.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (51, 17, 34, 'Neki ipak prionuše uza nj i povjerovaše; među njima i Dionizije Areopagit, neka žena imenom Damara i drugi s njima.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (51, 18, 1, 'Nakon toga napusti Pavao Atenu i ode u Korint.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (51, 18, 2, 'Ondje nađe nekog Židova imenom Akvilu, rodom iz Ponta, koji netom bijaše došao iz Italije sa svojom ženom Priscilom jer je Klaudije naredio da svi Židovi napuste Rim. Pohodio ih je');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (51, 18, 3, 'i, kako bijahu istog zanimanja, ostao kod njih i radio. Po zanimanju bijahu šatorari.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (51, 18, 4, 'Svake je pak subote raspravljao u sinagogi i uvjeravao Židove i Grke.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (51, 18, 5, 'Kad iz Makedonije pristigoše Sila i Timotej, Pavao se potpuno posveti Riječi svjedočeći Židovima da Isus jest Krist.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (51, 18, 6, 'Kako se pak oni stadoše protiviti i huliti, otrese on haljine i reče im: \"Krv vaša na glave vaše! Ja sam nedužan. Od sada idem k poganima.\"');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (51, 18, 7, 'I ode odande te prijeđe u kuću nekoga bogobojazna čovjeka, imenom Ticija Justa, čija kuća bijaše tik do sinagoge.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (51, 18, 8, 'A nadstojnik sinagoge Krisp povjerova Gospodinu zajedno sa svim svojim domom. I mnogi od Korinćana koji su to slušali povjerovaše i pokrstiše se.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (51, 18, 9, 'Jedne noći reče Gospodin Pavlu u viđenju: \"Ne boj se, nego govori i ne daj se ušutkati!');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (51, 18, 10, 'Ta ja sam s tobom i nitko se neće usuditi da ti naudi. Jer mnogo je naroda mojega u ovome gradu.\"');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (51, 18, 11, 'Tako se zadrža godinu i šest mjeseci naučavajući među njima riječ Božju.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (51, 18, 12, 'Ali dok je Galion bio prokonzul Ahaje, navališe Židovi jednodušno na Pavla, dovukoše ga u sudnicu');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (51, 18, 13, 'i rekoše: \"Ovaj potiče ljude da protiv zakona štuju Boga.\"');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (51, 18, 14, 'Pavao samo što nije zaustio kadli Galion reče Židovima: \"Da je posrijedi zločin kakav ili nedjelo opako, saslušao bih vas, Židovi, kako je pravo;');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (51, 18, 15, 'je li pak raspra o riječi i imenima i o nekom vašem zakonu, proviđajte sami; u tome ja ne želim biti sudac.\"');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (51, 18, 16, 'I otpremi ih iz sudnice.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (51, 18, 17, 'A oni svi pograbiše nadstojnika sinagoge Sostena i stadoše ga šibati pred sudnicom. Galion nije za to ništa mario.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (51, 18, 18, 'Pavao osta još podosta vremena, a onda se oprosti s braćom pa pošto se u Kenhreji ošiša jer imaše zavjet, zaplovi prema Siriji, a s njime i Priscila i Akvila.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (51, 18, 19, 'Stigoše u Efez. Tu ih ostavi, a on uđe u sinagogu i stade raspravljati sa Židovima.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (51, 18, 20, 'Oni ga zamole da ostanu duže vremena, ali on ne pristade,');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (51, 18, 21, 'nego se oprosti: \"Još ću se, reče, vratiti k vama, bude li Božja volja.\" I otplovi iz Efeza.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (51, 18, 22, 'Kad stiže u Cezareju, uziđe pozdraviti Crkvu pa onda siđe u Antiohiju.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (51, 18, 23, 'Neko se vrijeme zadrža pa onda ode i zareda galacijskim područjem i Frigijom utvrđujući sve učenike.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (51, 18, 24, 'Uto neki Židov imenom Apolon, rodom Aleksandrijac, čovjek rječit i upućen u Pisma, stiže u Efez.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (51, 18, 25, 'On bijaše upućen u Put Gospodnji pa je vatrene duše govorio i naučavao pomno o Isusu, premda je znao samo za Ivanovo krštenje.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (51, 18, 26, 'Poče on tako smjelo govoriti u sinagogi. Čuše ga Priscila i Akvila, uzeše ga k sebi i pomnije mu izložiše Put Božji.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (51, 18, 27, 'A kad je nakanio otići u Ahaju, ohrabriše ga braća i napisaše učenicima da ga prime. Kad je stigao onamo, uvelike je koristio vjernicima po milosti');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (51, 18, 28, 'jer je snažno pobijao Židove javno pokazujući iz Pisama da Isus jest Krist.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (51, 19, 1, 'Dok je Apolon bio u Korintu, Pavao, pošto prođe gornje krajeve, dođe u Efez, nađe neke učenike');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (51, 19, 2, 'pa ih upita: \"Jeste li primili Duha Svetoga kad ste povjerovali?\" Oni će mu: \"Ta ni čuli nismo da ima Duh Sveti.\"');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (51, 19, 3, 'Nato će on: \"Kako ste onda kršteni?\" \"Krštenjem Ivanovim\", odvrate oni.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (51, 19, 4, 'Nato će Pavao: \"Ivan je krstio krštenjem obraćenja govoreći narodu da vjeruje u Onoga koji za njim dolazi, to jest u Isusa.\"');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (51, 19, 5, 'Čuvši to, krste se u ime Gospodina Isusa,');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (51, 19, 6, 'pa kad Pavao položi na njih ruke, dođe Duh Sveti na njih te stanu govoriti drugim jezicima i prorokovati.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (51, 19, 7, 'Bijaše u svemu dvanaestak muževa.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (51, 19, 8, 'Onda Pavao uđe u sinagogu te je tri mjeseca hrabro raspravljao i uvjeravao o kraljevstvu Božjem.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (51, 19, 9, 'Ali kako neki, okorjeli i nepokorni, ocrnjivahu ovaj Put pred mnoštvom, odstupi od njih, odvoji učenike i danomice raspravljaše u školi nekog Tirana.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (51, 19, 10, 'Trajalo je to dvije godine, tako da su svi azijski žitelji, Židovi i Grci, čuli riječ Božju.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (51, 19, 11, 'Bog je pak činio čudesa nesvakidašnja po rukama Pavlovima');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (51, 19, 12, 'tako da bi na bolesnike stavljali rupce ili rublje s Pavlova tijela pa bi s njih nestajalo bolesti i zli duhovi iz njih izlazili.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (51, 19, 13, 'Zato i neki Židovi zaklinjaoci-potukači pokušaše zazvati ime Gospodina Isusa nad one koji imahu zle duhove. Govorili su: \"Zaklinjem vas Isusom koga Pavao propovijeda.\"');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (51, 19, 14, 'To činjaše sedam sinova nekog Skeve, židovskoga velikog svećenika.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (51, 19, 15, 'Zli im duh odvrati: \"Isusa poznajem i Pavla znam, ali tko ste vi?\"');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (51, 19, 16, 'I čovjek u kome bijaše zli duh, nasrnu na njih i nadjača ih te oni goli i izranjeni pobjegoše iz one kuće.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (51, 19, 17, 'Doznaše to svi žitelji efeški, Židovi i Grci, pa ih sve obuze strah te se stade veličati ime Gospodina Isusa.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (51, 19, 18, 'Mnogi pak od onih koji su povjerovali dolazili su ispovijedati i očitovati svoja djela.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (51, 19, 19, 'I podosta onih koji su se bavili praznovjerjem donosili su knjige i spaljivali ih pred svima. Procijeniše ih te nađoše da vrijede pedeset tisuća srebrnjaka.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (51, 19, 20, 'TAko se snagom Gospodnjom Riječ širila i jačala.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (51, 19, 21, 'Pošto se to ispuni, naumi Pavao preko Makedonije i Ahaje otići u Jeruzalem te reče: \"Pošto budem ondje, trebat će da i Rim vidim.\"');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (51, 19, 22, 'Onda posla u Makedoniju dvojicu svojih poslužitelja, Timoteja i Erasta, a on provede još neko vrijeme u Aziji.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (51, 19, 23, 'Nekako u ono doba nasta nemalena pobuna protiv ovog Puta.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (51, 19, 24, 'Neki srebrar, imenom Demetrije, izrađivao je srebrne hramiće Artemidine i namicao obrtnicima nemalu dobit.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (51, 19, 25, 'Skupi on njih i sve koji su se bavili takvim poslom te im reče: \"Ljudi, vi znate, u ovom je umijeću naše blagostanje.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (51, 19, 26, 'A vidite i čujete da je taj Pavao ne samo u Efezu nego gotovo i u svoj Aziji uvjerio i preokrenuo poveliko mnoštvo govoreći da nema bogova rukama izdjeljanih.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (51, 19, 27, 'Tako prijeti opasnost ne samo da na zao glas dođe naše zanimanje, nego i to da se ništa neće držati do hrama velike božice Artemide te će nestati veličanstva one koju štuje sva Azija i sav svijet.\"');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (51, 19, 28, 'Čuvši to, razgnjeve se pa poviču: \"Velika je Artemida efeška!\"');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (51, 19, 29, 'Sav se grad uskomeša; jednodušno nahrupe u kazalište vukući sa sobom Makedonce Gaja i Aristarha, suputnike Pavlove.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (51, 19, 30, 'Kad je Pavao htio među narod, ne dopustiše mu učenici.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (51, 19, 31, 'Čak i neki azijarsi, njegovi prijatelji, poslaše k njemu i zamoliše da ne dolazi u kazalište.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (51, 19, 32, 'Jedni su izvikivali jedno, drugi drugo jer je skup bio uskomešan te mnogi nisu ni znali zašto su se strčali.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (51, 19, 33, 'Neki iz svjetine uputiše nekog Aleksandra jer su ga Židovi gurali naprijed. Aleksandar pak mahnu rukom i htjede se obraniti pred narodom.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (51, 19, 34, 'Ali kada doznaše da je Židov, udarahu gotovo dva sata svi u jedan glas: \"Velika je Artemida efeška!\"');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (51, 19, 35, 'Onda tajnik umiri svjetinu pa reče: \"Efežani! Tko to od ljudi ne zna da je grad Efez čuvar hrama velike Artemide i kipa s neba palog?');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (51, 19, 36, 'Budući dakle da je to neporecivo, valja da budete mirni te ništa brzopleto ne činite.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (51, 19, 37, 'Doveli ste ove ljude, a nisu ni svetokradice ni hulitelji naše božice.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (51, 19, 38, 'Ako pak Demetrije i njegovi obrtnici imaju protiv koga kakvu tužbu, sudovi se sastaju, a tu su i prokonzuli. Neka se tuže!');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (51, 19, 39, 'Ištete li pak što drugo, u zakonitu će se skupu riješiti.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (51, 19, 40, 'Ta izlažemo se opasnosti da za ovo današnje budemo optuženi s pobune jer nema nikakva razloga kojim bismo mogli opravdati ovu strku.\" To rekavši, raspusti skup.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (51, 19, 41, '');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (51, 20, 1, 'Kad se sleže metež, posla Pavao po učenike, ohrabri ih, pozdravi i otputova u Makedoniju.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (51, 20, 2, 'Prešavši one krajeve, hrabreći braću besjedom mnogom, dođe u Grčku');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (51, 20, 3, 'i provede ondje tri mjeseca. Upravo kad je htio otploviti u Siriju, postaviše mu Židovi zasjedu pa odluči vratiti se preko Makedonije.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (51, 20, 4, 'Pratili su ga: Sopater Pirov, Berejac, Solunjani Aristarh i Sekund, Gaj Derbanin, Timotej i Azijci Tihik i Trofim.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (51, 20, 5, 'Oni odoše prije te nas dočekaše u Troadi.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (51, 20, 6, 'Mi pak nakon dana Beskvasnih kruhova otplovismo iz Filipa i nakon pet dana dođosmo k njima u Troadu gdje proboravismo sedam dana.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (51, 20, 7, 'U prvi dan tjedna, kad se sabrasmo lomiti kruh, Pavao im govoraše i kako je sutradan kanio otputovati, probesjedi sve do ponoći.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (51, 20, 8, 'U gornjoj sobi gdje smo se sabrali bijaše dosta svjetiljaka.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (51, 20, 9, 'Na prozoru je sjedio neki mladić imenom Eutih. Kako je Pavao dulje govorio, utone on u dubok san. Svladan snom, pade s trećeg kata dolje. Digoše ga mrtva.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (51, 20, 10, 'Pavao siđe, nadnese se nad dječaka, obujmi ga i reče: \"Ne uznemirujte se! Duša je još u njemu!\"');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (51, 20, 11, 'Zatim se pope pa pošto razlomi kruh i blagova, dugo je još zborio, sve do zore. Tad otputova.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (51, 20, 12, 'Mladića odvedoše živa, neizmjerno utješeni.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (51, 20, 13, 'Mi pak pođosmo naprijed lađom: otplovismo u As. Odande smo imali povesti Pavla - tako je odredio kad se spremao poći pješice.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (51, 20, 14, 'Kad nam se u Asu pridruži, uzesmo ga i stigosmo u Mitilenu.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (51, 20, 15, 'Odande odjedrismo sutradan i stigosmo nadomak Hija, prekosutra krenusmo u Sam, a idućeg dana stigosmo u Milet.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (51, 20, 16, 'Jer Pavao je odlučio mimoići Efez da se ne bi zadržao u Aziji: žurio se da, uzmogne li, na dan Pedesetnice bude u Jeruzalemu.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (51, 20, 17, 'Ipak iz Mileta posla u Efez po starješine Crkve.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (51, 20, 18, 'Kad stigoše, reče im: \"Vi znate kako sam se sve vrijeme, od prvog dana kada stupih u Aziju, ponašao među vama:');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (51, 20, 19, 'služio sam Gospodinu sa svom poniznošću u suzama i kušnjama koje me zadesiše zbog zasjeda židovskih;');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (51, 20, 20, 'ništa korisno nisam propustio navijestiti vam i naučiti vas - javno i po kućama;');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (51, 20, 21, 'upozoravao sam Židove i Grke da se obrate k Bogu i da vjeruju u Gospodina našega Isusa.\"');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (51, 20, 22, '\"A sad, evo, okovan Duhom idem u Jeruzalem. Što će me u njemu zadesiti, ne znam,');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (51, 20, 23, 'osim što mi Duh Sveti u svakom gradu jamči da me čekaju okovi i nevolje.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (51, 20, 24, 'Ali ni najmanje mi nije do života, samo da dovršim trku svoju i službu koju primih od Gospodina Isusa: svjedočiti za evanđelje milosti Božje.\"');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (51, 20, 25, '\"I sad, evo, znam: nećete više vidjeti lica moga, svi vi posred kojih prođoh propovijedajući Kraljevstvo.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (51, 20, 26, 'Zato vam u ovaj dan današnji jamčim: čist sam od krvi sviju');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (51, 20, 27, 'jer nisam propustio navijestiti vam ništa od svega nauma Božjega.\"');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (51, 20, 28, '\"Pazite na sebe i na sve stado u kojem vas Duh Sveti postavi nadglednicima, da pasete Crkvu Božju koju steče krvlju svojom.\"');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (51, 20, 29, '\"Ja znam da će nakon mog odlaska među vas uljesti vuci okrutni koji ne štede stada,');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (51, 20, 30, 'a između vas će samih ustati ljudi koji će iskrivljavati nauk da bi odvukli učenike za sobom.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (51, 20, 31, 'Zato bdijte imajući na pameti da sam tri godine bez prestanka noću i danju suze lijevajući urazumljivao svakoga od vas.\"');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (51, 20, 32, '\"I sada vas povjeravam Bogu i Riječi milosti njegove koja je kadra izgraditi vas i dati vam baštinu među svima posvećenima.\"');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (51, 20, 33, '\"Ni za čijim srebrom, zlatom ili ruhom nisam hlepio.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (51, 20, 34, 'Sami znate: za potrebe moje i onih koji su sa mnom zasluživale su ove ruke.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (51, 20, 35, 'U svemu vam pokazah: tako se trudeći treba se zauzimati za nemoćne i na pameti imati riječi Gospodina Isusa jer on reče: \'Blaženije je davati nego primati.\'\"');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (51, 20, 36, 'Kada to doreče, klekne te se zajedno sa svima njima pomoli.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (51, 20, 37, 'Tad svi briznuše u velik plač, obisnuše Pavlu oko vrata i stadoše ga cjelivati,');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (51, 20, 38, 'ražalošćeni nadasve riječju koju im reče: da više neće vidjeti lica njegova. Zatim ga ispratiše na lađu.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (51, 21, 1, 'Pošto se otrgosmo od njih, zaplovismo. Jedreći ravno, stigosmo na Kos, a sutradan na Rod pa odande u Pataru.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (51, 21, 2, 'Kad nađosmo lađu za Feniciju, popesmo se i otplovismo.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (51, 21, 3, 'Kad bijasmo napomol Cipru, ostavismo ga slijeva jedreći prema Siriji. Pristadosmo u Tiru jer je ondje lađa imala iskrcati tovar.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (51, 21, 4, 'Pronađosmo učenike i ostadosmo ondje sedam dana. Oni po Duhu nagovarahu Pavla da ne uzlazi u Jeruzalem.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (51, 21, 5, 'Ali kad nam istekoše dani, ipak otputovasmo. Ispratiše nas svi, sa ženama i djecom, do izvan grada. Na žalu klekosmo i pomolismo se.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (51, 21, 6, 'Pozdravismo se, popesmo se na lađu, a oni se vratiše kući.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (51, 21, 7, 'Tako dovršismo plovidbu. Iz Tira stigosmo u Ptolemaidu. Pozdravili smo braću i ostali jedan dan u njih.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (51, 21, 8, 'Sutradan otputovasmo i stigosmo u Cezareju. Uđosmo u kuću Filipa evanđelista, jednog od sedmorice, i ostadosmo kod njega.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (51, 21, 9, 'On je imao četiri kćeri djevice koje su prorokovale.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (51, 21, 10, 'Kako smo se zadržali mnogo dana, siđe iz Judeje neki prorok imenom Agab,');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (51, 21, 11, 'dođe k nama, uze Pavlov pojas, sveza sebi noge i ruke te reče: \"Ovo govori Duh Sveti: Čovjeka čiji je ovo pojas ovako će svezati Židovi u Jeruzalemu i predati u ruke pogana.\"');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (51, 21, 12, 'Kada smo to čuli, stadosmo mi i mještani zaklinjati Pavla da ne uzlazi u Jeruzalem.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (51, 21, 13, 'Nato on odvrati: \"Što plačete i parate mi srce? Ta spreman sam ne samo biti svezan nego i umrijeti u Jeruzalemu za ime Gospodina Isusa.\"');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (51, 21, 14, 'A kako se nije dao nagovoriti, ušutjesmo rekavši: \"Gospodnja budi volja!\"');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (51, 21, 15, 'Nakon tih dana spremismo se i uzađosmo u Jeruzalem.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (51, 21, 16, 'S nama pođoše i učenici iz Cezareje pa nas odvedoše k nekomu Mnasonu Cipraninu, starom učeniku, da u njega odsjednemo.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (51, 21, 17, 'Kad stigosmo u Jeruzalem, primiše nas braća radosno.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (51, 21, 18, 'Sutradan ode Pavao zajedno s nama k Jakovu. Nađoše se ondje i sve starješine.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (51, 21, 19, 'Pošto ih pozdravi, stade im potanko izlagati što učini Bog među poganima po njegovoj službi.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (51, 21, 20, 'Pošto su ga oni poslušali, dadoše slavu Bogu pa mu rekoše: \"Vidiš, brate: deseci su tisuća Židova povjerovali i svi su revnitelji Zakona.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (51, 21, 21, 'A o tebi im je dojavljeno da sve Židove koji su među poganima upućuješ na otpad od Mojsija učeći ih da ne obrezuju djece i ne žive po običajima.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (51, 21, 22, 'Što dakle? Čut će svakako da si došao.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (51, 21, 23, 'Učini stoga što ti kažemo. U nas su četiri čovjeka koji imaju zavjet.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (51, 21, 24, 'Njih uzmi, s njima se zajedno posveti, plati za njih da se ošišaju pa će svi spoznati da nema ništa od onoga što im je o tebi dojavljeno, nego da si i ti na pravu putu i da opslužuješ Zakon.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (51, 21, 25, 'A što se tiče pogana koji povjerovaše - poslali smo što odlučismo: da se klone mesa žrtvovana idolima, krvi, udavljenoga i bludništva.\"');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (51, 21, 26, 'Nato Pavao uze one ljude, sutradan se s njima zajedno posveti, uđe u Hram, oglasi svršetak dana posvećenja nakon kojih će se za svakoga od njih prinijeti prinos.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (51, 21, 27, 'Kad se upravo navršavalo tih sedam dana, neki ga Židovi iz Azije opaze u Hramu, uzbune sav narod pa podignu na nj ruke');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (51, 21, 28, 'vičući: \"Izraelci, u pomoć! Evo čovjeka koji sve posvuda poučava protiv naroda, Zakona i ovoga mjesta pa je još i Grke uveo u Hram i oskvrnuo ovo sveto mjesto.\"');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (51, 21, 29, 'Jer prije su s njime u Gradu vidjeli Trofima Efežanina i mislili da je Pavao njega uveo u Hram.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (51, 21, 30, 'Sav se grad uskomeša, nasta strka naroda. Pograbe Pavla i odvuku ga izvan Hrama pa odmah pozatvaraju vrata.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (51, 21, 31, 'Dok su mu o glavi radili, dođe do tisućnika čete glas da je sav Jeruzalem uzavreo.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (51, 21, 32, 'On odmah uze vojnike i satnike pa otrča dolje k njima. Oni pak kako ugledaše tisućnika i vojnike, prestadoše udarati Pavla.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (51, 21, 33, 'Onda se tisućnik približi, uhvati ga, zapovjedi da ga okuju dvojim verigama pa stade ispitivati tko je i što je učinio.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (51, 21, 34, 'Iz svjetine su jedni izvikivali ovo, drugi ono. Kako zbog graje nije mogao saznati ništa pouzdano, zapovjedi da se odvede u vojarnu.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (51, 21, 35, 'Kad se Pavao pojavi na stubama, morali su ga vojnici nositi zbog silovitosti svjetine.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (51, 21, 36, 'Jer mnoštvo je naroda išlo za njima i vikalo: \"Smakni ga!\"');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (51, 21, 37, 'Upravo na ulazu u vojarnu reče Pavao tisućniku: \"Smijem li nešto reći?\" On ga upita: \"Zar znaš grčki?');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (51, 21, 38, 'Ti dakle nisi onaj Egipćanin koji je prije nekoliko dana pobunio i u pustinju odveo one četiri tisuće bodežara?\"');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (51, 21, 39, 'Pavao odvrati: \"Ja sam Židov iz Tarza cilicijskoga, građanin grada znamenitoga. Molim te, dopusti mi progovoriti narodu.\"');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (51, 21, 40, 'Kad mu on dopusti, Pavao stojeći na stubama mahnu rukom narodu pa kad nasta velika tišina, prozbori hebrejskim jezikom:');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (51, 22, 1, '\"Braćo i oci, poslušajte što ću vam sad u svoju obranu reći.\"');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (51, 22, 2, 'Kad čuše da im govori hebrejskim jezikom, još većma utihnuše. On nastavi:');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (51, 22, 3, '\"Ja sam Židov, rođen u Tarzu cilicijskom, ali odrastao u ovom gradu, do nogu Gamalielovih odgojen točno po otačkom Zakonu; bijah revnitelj Božji kao što ste svi vi još danas.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (51, 22, 4, 'Ovaj sam Put na smrt progonio, u okove bacao i predavao u tamnice muževe i žene,');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (51, 22, 5, 'kako mi to može posvjedočiti i veliki svećenik i sve starješinstvo. Od njih sam i pisma dobio za braću u Damasku pa se zaputio da i one ondje okovane dovedem u Jeruzalem da se kazne.\"');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (51, 22, 6, '\"Dok sam tako putovao i približavao se Damasku, s neba me oko podneva iznenada obasja svjetlost velika.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (51, 22, 7, 'Sruših se na tlo i začuh glas što mi govoraše: \'Savle, Savle, zašto me progoniš?\'');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (51, 22, 8, 'Ja odgovorih: \'Tko si, Gospodine?\' Reče mi: \'Ja sam Isus Nazarećanin koga ti progoniš.\'');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (51, 22, 9, 'Oni koji bijahu sa mnom svjetlost doduše primijetiše, ali ne čuše glasa Onoga koji mi govoraše.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (51, 22, 10, 'Rekoh nato: \'Što mi je činiti, Gospodine?\' Gospodin će mi: \'Ustani, pođi u Damask i ondje će ti se reći što ti je određeno učiniti.\'');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (51, 22, 11, 'Kako od sjaja one svjetlosti obnevidjeh, pratioci me povedoše za ruku te stigoh u Damask.\"');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (51, 22, 12, '\"Neki Ananija, čovjek po Zakonu pobožan i na dobru glasu u Židova ondje nastanjenih -');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (51, 22, 13, 'dođe k meni, pristupi mi i reče: \'Savle, brate, progledaj!\' I ja se u taj čas zagledah u nj.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (51, 22, 14, 'A on će: \'Bog otaca naših predodredi te da upoznaš volju njegovu, da vidiš Pravednika i čuješ glas iz usta njegovih');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (51, 22, 15, 'jer bit ćeš mu pred svim ljudima svjedokom onoga što si vidio i čuo.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (51, 22, 16, 'I što sad oklijevaš? Ustani, krsti se i operi grijehe svoje, prizivljući Ime njegovo!\'\"');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (51, 22, 17, '\"Pošto se vratih u Jeruzalem, dok sam se jednom molio u Hramu, padoh u zanos');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (51, 22, 18, 'i vidjeh Gospodina gdje mi govori: \'Pohiti, žurno izađi iz Jeruzalema jer neće primiti tvoga svjedočanstva o meni.\'');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (51, 22, 19, 'Ja rekoh: \'Gospodine, oni znaju da sam ja u tamnice bacao i bičevao po sinagogama one koji vjeruju u te.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (51, 22, 20, 'I dok se prolijevala krv Stjepana, svjedoka tvoga, i ja sam ondje stajao i odobravao te čuvao haljine onih koji ga ubijahu.\'');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (51, 22, 21, 'Nato mi reče: \'Pođi jer ću te poslati daleko k poganima!\'');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (51, 22, 22, 'Slušali su ga sve do te riječi, a tada podigoše glas: \"Ukloni takva sa zemlje! Nije pravo da živi!\"');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (51, 22, 23, 'Kako oni stadoše bučiti, odbacivati haljine i vitlati prašinu u zrak,');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (51, 22, 24, 'zapovjedi tisućnik da Pavla uvedu u vojarnu pa odredi da ga bičevima ispitaju kako bi doznao zašto tako viču protiv njega.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (51, 22, 25, 'Kad ga remenjem rastegoše, reče on nazočnom satniku: \"Rimskoga građanina, i još neosuđena, smijete bičevati?\"');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (51, 22, 26, 'Kad je to čuo satnik, priđe tisućniku i dojavi mu: \"Što si to nakanio? Ovaj je čovjek Rimljanin!\"');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (51, 22, 27, 'Tisućnik tada priđe Pavlu pa mu reče: \"Reci mi, jesi li Rimljanin!\" On odvrati: \"Da.\"');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (51, 22, 28, 'Tisućnik dometnu: \"Ja stekoh to građanstvo za skupe novce.\" Pavao nato reče: \"Ja sam se pak s njim i rodio.\"');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (51, 22, 29, 'Brže stoga odstupe od njega oni koji su ga imali ispitivati. I tisućnik se preplaši kad sazna da je Pavao Rimljanin, a on ga bijaše okovao.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (51, 22, 30, 'Sutradan pak kad je htio točno saznati za što ga Židovi optužuju, odriješi ga pa zapovjedi da se sastanu veliki svećenici i sve Vijeće te privede Pavla i postavi ga pred njih.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (51, 23, 1, 'Pavao uprije pogled u Vijeće i reče: \"Braćo, ja sam posve mirne savjesti živio pred Bogom sve do dana današnjega.\"');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (51, 23, 2, 'Nato veliki svećenik Ananija naredi onima što stajahu uza nj da ga udare po ustima.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (51, 23, 3, 'Onda mu Pavao reče: \"Udarit će Bog tebe, zide obijeljeni! Ti li sjediš da me po Zakonu sudiš, a protuzakonito zapovijedaš da me biju?\"');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (51, 23, 4, 'Oni što su ondje stajali rekoše nato: \"Zar velikog svećenika Božjega da pogrđuješ?\"');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (51, 23, 5, 'Pavao odvrati: \"Nisam znao, braćo, da je veliki svećenik. Ta pisano je: Glavara naroda svoga ne proklinji.\"');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (51, 23, 6, 'Pavao je znao da su oni dijelom saduceji, a dijelom farizeji pa povika u Vijeću: \"Braćo, ja sam farizej, sin farizeja. Sudi mi se zbog nade, uskrsnuća mrtvih.\"');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (51, 23, 7, 'Tek što je on to rekao, nasta razmirica između farizeja i saduceja i mnoštvo se razdijeli.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (51, 23, 8, 'Jer saduceji vele da nema uskrsnuća, ni anđela, ni duha, a farizeji sve to priznaju.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (51, 23, 9, 'Nasta velika graja te ustadoše neki pismoznanci farizejske stranke i zaoštre boj govoreći: \"Ništa zlo ne nalazimo na tom čovjeku! A što ako mu je duh govorio, ili anđeo?\"');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (51, 23, 10, 'Kad razmirica posta još većom, poboja se tisućnik da Pavla ne rastrgaju pa zapovjedi da vojska siđe, otme ga ispred njih i povede u vojarnu.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (51, 23, 11, 'Iduće noći pristupi mu Gospodin i reče: \"Hrabro samo! Jer kao što si za me svjedočio u Jeruzalemu tako treba da i u Rimu posvjedočiš!\"');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (51, 23, 12, 'Kad osvanu dan, skovaše Židovi urotu i zakleše se da neće ni jesti ni piti dok ne ubiju Pavla.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (51, 23, 13, 'Bilo je više od četrdeset onih koji su skovali tu zavjeru.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (51, 23, 14, 'Oni odu k velikim svećenicima i starješinama pa reknu: \"Zakletvom se zaklesmo ništa ne okusiti dok ne ubijemo Pavla.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (51, 23, 15, 'Stoga vi sada zajedno s Vijećem predočite tisućniku neka vam ga dovede kao da kanite točnije razaznati njegov slučaj. A mi smo spremni pogubiti ga prije negoli se i približi.\"');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (51, 23, 16, 'Ali sin Pavlove sestre doču za zavjeru, približi se i uđe u vojarnu dojaviti Pavlu.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (51, 23, 17, 'Pavao pak pozove jednog satnika i reče mu: \"Ovog mladića odvedi k tisućniku: ima mu nešto dojaviti.\"');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (51, 23, 18, 'On ga uze, odvede k tisućniku i reče mu: \"Uznik me Pavao pozva i zaiska da ovog mladića privedem k tebi; ima ti nešto reći.\"');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (51, 23, 19, 'Tisućnik ga prihvati za ruku, povede nasamo pa ga upita: \"Što mi imaš dojaviti?\"');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (51, 23, 20, '\"Židovi su se, reče on, dogovorili da te zamole da im sutra Pavla dovedeš u Vijeće kao da se kane točnije raspitati o njemu.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (51, 23, 21, 'Ne vjeruj im! U zasjedi ga čeka više od četrdeset onih koji se zakleše da neće jesti ni piti dok ga ne smaknu. Već su spremni, samo čekaju tvoju privolu.\"');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (51, 23, 22, 'Tisućnik onda otpusti mladića i zapovjedi mu: \"Nikomu ne kazuj da si mi to dojavio.\"');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (51, 23, 23, 'Zatim dozva dva satnika i reče im: \"Pripravite dvjesta vojnika, sedamdeset konjanika i dvjesta strijelaca da nakon treće noćne ure pođu u Cezareju.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (51, 23, 24, 'Neka se pripravi živina na koju će se posaditi Pavao te živ i zdrav dovesti k upravitelju Feliksu.\"');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (51, 23, 25, 'Napisa i pismo ovoga sadržaja:');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (51, 23, 26, '\"Klaudije Lizija vrlom upravitelju Feliksu - pozdrav!');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (51, 23, 27, 'Ovoga čovjeka Židovi uhvatiše i tek što ga ne smakoše kadli s vojskom pritrčah i istrgoh im ga kada doznah da je Rimljanin.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (51, 23, 28, 'Htjedoh saznati za što ga okrivljuju pa ga dovedoh u njihovo Vijeće.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (51, 23, 29, 'Utvrdih da ga okrivljuju za nešto prijeporno u njihovu zakonu i da nema nikakve krivnje kojom bi zaslužio smrt ili okove.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (51, 23, 30, 'Kad mi pak dojaviše da su protiv njega skovali zavjeru, poslah ga k tebi, a tužitelje uputih neka se tebi obrate protiv njega.\"');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (51, 23, 31, 'Vojnici dakle, po primljenoj naredbi uzeše Pavla i odvedoše ga noću u Antipatridu.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (51, 23, 32, 'Sutradan ostave konjanike da s njime pođu dalje, a oni se vratiše u vojarnu.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (51, 23, 33, 'Kad konjanici stigoše u Cezareju, uručiše upravitelju pismo i privedoše mu Pavla.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (51, 23, 34, 'Pošto upravitelj pročita pismo, zapita iz koje je pokrajine. Kad sazna da je iz Cilicije:');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (51, 23, 35, '\"Saslušat ću te, reče, kad pristignu i tužitelji tvoji.\" Onda zapovjedi čuvati ga u dvoru Herodovu.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (51, 24, 1, 'Nakon pet dana siđe veliki svećenik Ananija s nekim starješinama i odvjetnikom, nekim Tertulom te izniješe upravitelju tužbu protiv Pavla.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (51, 24, 2, 'Pošto dozvaše Pavla, poče ga Tertul optuživati: \"Veliki mir što ga po tebi, vrli Felikse, uživamo i boljitak što tvojom providnošću narodu ovomu nastaje,');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (51, 24, 3, 'u svemu i posvuda primamo sa svom zahvalnošću.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (51, 24, 4, 'Ali, da ti dulje ne dodijavam, molim te da nas u svojoj blagonaklonosti ukratko poslušaš.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (51, 24, 5, 'Utvrdismo da je ovaj čovjek kuga, da pokreće bune među svim Židovima po svijetu, da je kolovođa nazaretske sljedbe,');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (51, 24, 6, 'da je čak i Hram pokušao oskvrnuti pa ga uhitismo.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (51, 24, 7, '#');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (51, 24, 8, 'Od njega, ako ga o svemu tomu ispitaš, možeš saznati za što ga mi optužujemo.\"');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (51, 24, 9, 'Podržaše ga i Židovi tvrdeći da je tako.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (51, 24, 10, 'Nato Pavao odvrati pošto mu upravitelj kimnu da govori: \"Kako znam da si već mnogo godina sudac narodu ovomu, mirne se duše branim.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (51, 24, 11, 'Ta možeš se osvjedočiti da nema više od dvanaest dana otkad uzađoh u Jeruzalem da se poklonim.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (51, 24, 12, 'A nisu me našli ni u Hramu da s kim raspravljam ili bunu podižem, ni u sinagogama, ni po gradu.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (51, 24, 13, 'I ne mogu ti dokazati ono za što me sada optužuju.\"');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (51, 24, 14, '\"Jamčim ti, naprotiv, ovo: Putom koji nazivaju sljedbom služim otačkom Bogu vjerujući u sve što je u Zakonu i u Prorocima napisano,');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (51, 24, 15, 'uzdajući se u Boga da će uskrsnuti pravednici i nepravednici, što oni i sami očekuju.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (51, 24, 16, 'Zato se i ja trudim uvijek imati savjest besprijekornu pred Bogom i pred ljudima.\"');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (51, 24, 17, '\"Nakon više godina dođoh da donesem milostinju za svoj narod i prinose;');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (51, 24, 18, 'dok sam ih prinosio, nađoše me posvećena u Hramu, a ne sa svjetinom ni u metežu.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (51, 24, 19, 'Ali neki Židovi iz Azije - da, trebalo bi da se oni pojave pred tobom i optuže me ako što imaju protiv mene.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (51, 24, 20, 'Ili neka ovi sami kažu: koji su zločin na meni našli kad sam stajao pred Vijećem,');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (51, 24, 21, 'osim možda one jedne riječi koju doviknuh među njima stojeći: Zbog uskrsnuća mrtvih sudi mi se danas pred vama!\"');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (51, 24, 22, 'Nato Feliks, koji je točno znao sve o ovom Putu, odgodi njihovu parnicu rekavši: \"Kada dođe tisućnik Lizija, riješit ću vaš spor.\"');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (51, 24, 23, 'Satniku pak naredi da se Pavao čuva, ali da uživa olakšice i da se nikomu od njegovih ne brani posluživati ga.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (51, 24, 24, 'Nakon nekoliko dana stigne i Feliks sa svojom ženom Druzilom koja bijaše Židovka; posla po Pavla i posluša ga o vjeri u Isusa Krista.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (51, 24, 25, 'Kad Pavao stade raspravljati o pravednosti, uzdržljivosti i budućem Sudu, Feliks uplašen reče: \"Zasad idi, a kad nađem vremena, pozvat ću te.\"');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (51, 24, 26, 'Ujedno se nadao da će mu Pavao dati novaca. Zato ga je češće pozivao i s njim razgovarao.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (51, 24, 27, 'Nakon dvije godine dobi Feliks za nasljednika Porcija Festa. Hoteći ugoditi Židovima, ostavi Feliks Pavla u okovima.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (51, 25, 1, 'Fest dakle tri dana nakon dolaska u provinciju uziđe iz Cezareje u Jeruzalem.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (51, 25, 2, 'Veliki mu svećenici i prvaci židovski izniješe tužbu protiv Pavla te ga zaklinjahu');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (51, 25, 3, 'ištući milost protiv Pavla: da ga pošalje u Jeruzalem. Jer spremali su zasjedu da ga putom smaknu.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (51, 25, 4, 'Ali Fest odvrati kako Pavao treba da ostane zatvoren u Cezareji, a i on da će uskoro onamo.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (51, 25, 5, '\"Ovlašteni dakle među vama, reče, neka sa mnom siđu pa ako na tom čovjeku ima krivnje, neka ga tuže.\"');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (51, 25, 6, 'Pošto se u njih zadrži najviše osam ili deset dana, siđe u Cezareju. Sutradan sjede na sudačku stolicu i zapovjedi da se dovede Pavao.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (51, 25, 7, 'Kad se on pojavi, okružiše ga Židovi koji su sišli iz Jeruzalema i izniješe protiv njega mnoge i teške optužbe kojih ne mogahu dokazati.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (51, 25, 8, 'Pavao se branio: \"Ničim se nisam ogriješio ni o židovski Zakon, ni o Hram, ni o cara.\"');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (51, 25, 9, 'Nato Fest hoteći ugoditi Židovima, odvrati Pavlu: \"Hoćeš li u Jeruzalem da ti se ondje za to sudi preda mnom?\"');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (51, 25, 10, 'A Pavao će: \"Stojim pred sudom carevim, gdje treba da mi se sudi. Židovima ništa ne skrivih, kao što i ti veoma dobro znaš.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (51, 25, 11, 'Ako sam pak doista što skrivio i učinio štogod što zavređuje smrt, ne izmičem smrti; ako li pak ne stoji ono za što me ovi tuže, nitko me ne može njima izručiti. Na cara se prizivljem!\"');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (51, 25, 12, 'Tada se Fest posavjetova s vijećem pa odgovori: \"Na cara si se prizvao, pred cara ćeš ići!\"');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (51, 25, 13, 'Nekoliko dana poslije dođu kralj Agripa i Berenika u Cezareju da pozdrave Festa.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (51, 25, 14, 'Kako se ondje zadržaše nekoliko dana, izloži Fest kralju to o Pavlu: \"Ima neki čovjek, reče, što ga je Feliks ostavio uznikom.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (51, 25, 15, 'Kad bijah u Jeruzalemu, izniješe veliki svećenici i starješine protiv njega tužbu i zatražiše osudu.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (51, 25, 16, 'Odgovorih im da u Rimljana nije običaj izručivati kojega čovjeka prije negoli se, optužen, suoči s tužiteljima i dobije prigodu da se brani od optužbe.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (51, 25, 17, 'Pošto zajedno dođosmo ovamo, bez ikakva odgađanja sjedoh ja sutradan na sudačku stolicu i zapovjedih dovesti toga čovjeka.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (51, 25, 18, 'Tužitelji ga okružiše, ali ne izniješe tužbe ni za jedno od zlodjela koja sam ja naslućivao,');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (51, 25, 19, 'nego su protiv njega imali nešto prijeporno o svojoj vjeri i o nekom Isusu koji je umro, a Pavao tvrdi da je živ.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (51, 25, 20, 'Ne snalazeći se u takvoj raspravi, upitah bi li htio u Jeruzalem da mu se ondje za to sudi.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (51, 25, 21, 'Budući da se Pavao prizivom podložio presudi njegova Veličanstva, zapovjedih da ga čuvaju dok ga ne pošaljem caru.\"');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (51, 25, 22, 'Na to će Agripa Festu: \"Htio bih i ja čuti toga čovjeka.\" \"Sutra ćeš ga, reče, čuti.\"');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (51, 25, 23, 'Sutradan dakle dođu Agripa i Berenika s velikim sjajem te uđu u dvoranu zajedno s tisućnicima i najuglednijim gradskim muževima. Kad na zapovijed Festovu dovedu Pavla,');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (51, 25, 24, 'reče Fest: \"Agripa, kralju, i vi svi ovdje s nama nazočni, gledajte ovoga čovjeka! Zbog njega me sav narod židovski salijetao i u Jeruzalemu i ovdje vičući da on ne smije više živjeti.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (51, 25, 25, 'Ali ja nađoh da nije učinio ništa čime bi zaslužio smrt pa kad se on sam prizvao na njegovo Veličanstvo, odlučih poslati mu ga.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (51, 25, 26, 'Ja nemam ništa pouzdano o njemu napisati Gospodaru. Zato ga izvedoh pred vas, ponajpače preda te, kralju Agripa, da bih nakon ove istrage imao što napisati.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (51, 25, 27, 'Čini mi se doista besmislenim poslati uznika, a ne naznačiti optužbu protiv njega.\"');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (51, 26, 1, 'Nato Agripa reče Pavlu: \"Dopušta ti se o sebi govoriti.\" Pavao ispruži ruku i stade se braniti:');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (51, 26, 2, '\"Smatram se sretnim što se u svemu za što me Židovi optužuju mogu, evo, danas braniti pred tobom, kralju Agripa,');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (51, 26, 3, 'jer ti najbolje poznaješ židovske običaje i zadjevice. Zato me, molim, velikodušno poslušaj.\"');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (51, 26, 4, '\"Dakle, život moj od najranije mladosti proveden u narodu mojem, u Jeruzalemu, znaju svi Židovi.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (51, 26, 5, 'Poznaju me odavna te mogu, ako samo hoće, svjedočiti da sam po najstrožoj sljedbi naše vjere živio kao farizej.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (51, 26, 6, 'I sada stojim pred sudom zbog nade u obećanje koje Bog dade ocima našim');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (51, 26, 7, 'i kojemu se dovinuti nada dvanaest plemena naših, svesrdno noću i danju služeći Bogu. Za tu me nadu, kralju, tuže Židovi.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (51, 26, 8, 'Zašto nevjerojatnim smatrate da Bog mrtve uskrisuje?\"');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (51, 26, 9, '\"Pa i ja sam nekoć smatrao da mi se svim silama boriti protiv imena Isusa Nazarećanina.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (51, 26, 10, 'To sam i činio u Jeruzalemu: mnoge sam svete, pošto od velikih svećenika dobih punomoć, u tamnice zatvorio, dao svoj glas kad su ih ubijali');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (51, 26, 11, 'i po svim ih sinagogama često mučenjem prisiljavao psovati i, prekomjerno bijesan na njih, progonio sam ih čak i u tuđim gradovima.\"');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (51, 26, 12, '\"Radi toga pođoh u Damask s punomoći i ovlaštenjem velikih svećenika');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (51, 26, 13, 'kadli u pol bijela dana na putu vidjeh, kralju, kako s neba svjetlost od sunca sjajnija obasja mene i moje suputnike.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (51, 26, 14, 'Pošto popadasmo na zemlju, začuh glas što mi govoraše hebrejskim jezikom: \'Savle, Savle, zašto me progoniš? Teško ti se protiv ostana praćakati.\'');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (51, 26, 15, 'Ja odvratih: \'Tko si, Gospodine?\' Gospodin će mi: \'Ja sam Isus koga ti progoniš!');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (51, 26, 16, 'Nego ustani, na noge se jer zato ti se ukazah da te postavim za poslužitelja i svjedoka onoga što si vidio i što ću ti pokazati.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (51, 26, 17, 'Izbavit ću te od naroda i od pogana kojima te šaljem');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (51, 26, 18, 'da im otvoriš oči pa se obrate od tame k svjetlosti, od vlasti Sotonine k Bogu te po vjeri u mene prime oproštenje grijeha i baštinu među posvećenima.\'\"');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (51, 26, 19, '\"Otada, kralju Agripa, ne bijah neposlušan nebeskom viđenju.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (51, 26, 20, 'Nego najprije onima u Damasku pa onda i u Jeruzalemu, svoj zemlji židovskoj i poganima navješćivah da se pokaju i obrate k Bogu i čine djela dostojna obraćenja.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (51, 26, 21, 'Zbog toga me Židovi uhvatiše u Hramu i pokušaše ubiti.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (51, 26, 22, 'Ali s pomoću Božjom sve do dana današnjega svjedočim, evo, malu i veliku, ne govoreći ništa osim onoga što Proroci govorahu i Mojsije da se ima zbiti:');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (51, 26, 23, 'da će Krist trpjeti i da će on, prvouskrsli od mrtvih, svjetlost navješćivati narodu i poganima.\"');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (51, 26, 24, 'Dok se on tako branio, Fest će mu u sav glas: \"Mahnitaš, Pavle! Veliko ti znanje mozgom zavrnulo.\"');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (51, 26, 25, '\"Ne mahnitam, vrli Feste, odvrati Pavao, nego riječi istine i razbora kazujem.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (51, 26, 26, 'Ta znade za to kralj komu s pouzdanjem govorim. Ništa mu od toga, uvjeren sam, nije nepoznato; jer nije se to dogodilo u kakvu zakutku.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (51, 26, 27, 'Vjeruješ li, kralju Agripa, Prorocima? Znam da vjeruješ!\"');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (51, 26, 28, 'Agripa će Pavlu: \"Zamalo pa me uvjeri te kršćaninom postah!\"');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (51, 26, 29, 'Pavao pak: \"Dao Bog te i za malo i za mnogo, ne samo ti nego i svi koji me danas slušaju postali ovakvima kakav sam ja, osim ovih okova!\"');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (51, 26, 30, 'Nato usta kralj, upravitelj, Berenika i oni koji su s njima zasjedali.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (51, 26, 31, 'Udaljujući se govorili su među sobom: \"Ovaj čovjek ne čini ništa čime bi zaslužio smrt ili okove.\"');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (51, 26, 32, 'Agripa pak reče Festu: \"Ovaj bi čovjek mogao biti pušten da se nije prizvao na cara.\"');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (51, 27, 1, 'Kad je odlučeno da odjedrimo u Italiju, predadoše i Pavla i neke druge uznike satniku carske čete, imenom Juliju.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (51, 27, 2, 'Popesmo se na neku adramitsku lađu koja je imala ploviti u azijska mjesta pa otplovismo. S nama je bio Aristarh Makedonac, Solunjanin.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (51, 27, 3, 'Sutradan doplovismo u Sidon. Julije, koji je s Pavlom čovječno postupao, dopusti mu poći k prijateljima da se pobrinu za nj.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (51, 27, 4, 'Odande smo otplovili, jedrili uz Cipar - jer su nam vjetrovi bili protivni -');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (51, 27, 5, 'pa preplovili more duž Cilicije i Pamfilije i stigli u Miru licijsku.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (51, 27, 6, 'Ondje satnik nađe neku aleksandrijsku lađu za Italiju i ukrca nas na nju.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (51, 27, 7, 'Više smo dana plovili sporo i jedva doprli do Knida. Kako nam vjetar ne dade pristati, doplovismo pod Kretu kod Salmone');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (51, 27, 8, 'pa jedva jedvice ploveći uza nju, stigosmo na neko mjesto zvano Dobra pristaništa, blizu kojega je grad Laseja.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (51, 27, 9, 'Kad je nakon duljeg vremena plovidba već postala pogibeljna jer je Post već bio izminuo, opominjaše Pavao:');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (51, 27, 10, '\"Ljudi, govorio im je, vidim da će plovidba biti nezgodna i na veliku štetu ne samo za tovar i lađu nego i za naše živote.\"');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (51, 27, 11, 'Ali je satnik više vjerovao kormilaru i brodovlasniku negoli Pavlovim riječima.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (51, 27, 12, 'A kako luka nije bila prikladna za zimovanje, većina je predlagala da odande otplove ne bi li kako doprli do kretske luke Feniksa, što gleda prema jugozapadu i sjeverozapadu, pa ondje prezimili.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (51, 27, 13, 'Uto duhne blagi južnjak i oni, misleći da bi mogli ostvariti naum, digoše sidro i zaploviše tik uz Kretu.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (51, 27, 14, 'Ali nedugo zatim razbjesni se žestok vjetar zvan sjeveroistočnjak.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (51, 27, 15, 'Zahvati lađu te mu nije mogla odoljeti pa se prepustismo da nas nosi.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (51, 27, 16, 'Prolazeći ispod nekog otočića zvanog Kauda, jedva uspjesmo dohvatiti čamac.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (51, 27, 17, 'Podigoše ga pa upotrijebiše snast da potpašu lađu. Bojeći se pak da se ne nasuču u Sirti, spustiše prvenjaču. Tako ih je nosilo.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (51, 27, 18, 'Budući da nas je oluja silovito udarala, sutradan se riješiše tovara,');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (51, 27, 19, 'a treći dan svojim rukama izbaciše brodsku opremu.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (51, 27, 20, 'Kako se pak više dana nije pomaljalo ni sunce ni zvijezde, a oluja bjesnjela nemalena, bila je već propala svaka nada da ćemo se spasiti.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (51, 27, 21, 'Ni jelo se već dugo nije. Onda usta Pavao posred njih i reče: \"Trebalo je, ljudi, poslušati me, ne se otiskivati od Krete i izbjeći ovu nepogodu i štetu.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (51, 27, 22, 'Sada vas pak opominjem: razvedrite se jer ni živa duša između vas neće stradati, nego samo lađa.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (51, 27, 23, 'Noćas mi se ukaza anđeo Boga čiji sam i komu služim');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (51, 27, 24, 'te reče: \'Ne boj se, Pavle! Pred cara ti je stati i evo Bog ti daruje sve koji plove s tobom.\'');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (51, 27, 25, 'Zato razvedrite se, ljudi! Vjerujem Bogu: bit će kako mi je rečeno.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (51, 27, 26, 'Ali treba da se nasučemo na neki otok.\"');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (51, 27, 27, 'Bijaše već četrnaesta noć što smo bili tamo-amo gonjani po Jadranu kad oko ponoći naslutiše mornari da im se primiče neka zemlja.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (51, 27, 28, 'Bacivši olovnicu, nađoše dvadeset hvati dubine; malo poslije baciše je opet i nađoše ih petnaest.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (51, 27, 29, 'Kako se bojahu da ne naletimo na grebene, baciše s krme četiri sidra iščekujući da se razdani.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (51, 27, 30, 'Kad su mornari bili naumili uteći iz lađe i počeli spuštati čamac u more pod izlikom da s pramca kane spustiti sidra,');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (51, 27, 31, 'reče Pavao satniku i vojnicima: \"Ako ovi ne ostanu na lađi, vi se spasiti ne možete!\"');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (51, 27, 32, 'Nato vojnici presjekoše užad čamca i pustiše da padne.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (51, 27, 33, 'Do pred svanuće nutkao je Pavao sve da uzmu hrane: \"Četrnaesti je danas dan, reče, što bez jela čekate, ništa ne okusivši.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (51, 27, 34, 'Stoga vas molim: založite nešto jer to je za vaš spas. Ta nikome od vas ni vlas s glave neće propasti.\"');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (51, 27, 35, 'Rekavši to, uze kruh, pred svima zahvali Bogu, razlomi i stade jesti.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (51, 27, 36, 'Svi se razvedre te i oni uzmu hrane.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (51, 27, 37, 'A svih nas je u lađi bilo dvjesta sedamdeset i šest duša.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (51, 27, 38, 'Jednom nasićeni, stanu rasterećivati lađu bacajući žito u more.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (51, 27, 39, 'Kad osvanu, mornari ne prepoznaše zemlje; razabraše neki zaljev ravne obale pa odluče, bude li moguće, u nj zavesti lađu.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (51, 27, 40, 'Odriješe sidra i ostave ih u moru. Istodobno popuste i spone kormila, razapnu prvenjaču prema vjetru pa udare k obali.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (51, 27, 41, 'Ali naletješe na plićak i nasukaše brod: pramac, nasađen, osta nepomičan, a krmu razdiraše žestina valova.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (51, 27, 42, 'Tada vojnici naumiše poubijati sužnje da ne bi koji isplivao i pobjegao,');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (51, 27, 43, 'ali im satnik, hoteći spasiti Pavla, omete naum: zapovjedi da oni koji znaju plivati najprvi poskaču i izađu na kraj,');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (51, 27, 44, 'a ostali će, tko na daskama, tko na olupinama lađe. Tako svi živi i zdravi prispješe na kopno.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (51, 28, 1, 'Jednom spašeni, doznasmo da se otok zove Malta.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (51, 28, 2, 'Urođenici nam iskazivahu nesvakidašnje čovjekoljublje. Zapališe krijes i okupiše nas oko njega jer je počela kiša i bilo zima.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (51, 28, 3, 'Pavao nakupi naramak granja i baci na krijes kadli zbog vrućine izađe zmija i pripije mu se za ruku.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (51, 28, 4, 'Kad su urođenici vidjeli gdje mu životinja visi o ruci, govorili su među sobom: \"Ovaj je čovjek zacijelo ubojica: umakao je moru i Pravda mu ne da živjeti.\"');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (51, 28, 5, 'Ali on otrese životinju u vatru i ne bi mu ništa;');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (51, 28, 6, 'a oni očekivahu da će oteći i umah se srušiti mrtav. Pošto su dugo čekali i vidjeli da mu se ništa neobično nije dogodilo, promijeniše mišljenje te stadoše govoriti da je bog.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (51, 28, 7, 'U okolici onoga mjesta bilo je imanje prvaka otoka, imenom Publija. On nas je primio i tri dana uljudno gostio.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (51, 28, 8, 'A Publijeva je oca uhvatila ognjica i srdobolja pa je ležao. Pavao uđe k njemu, pomoli se, stavi na nj ruke i izliječi ga.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (51, 28, 9, 'Nakon toga su dolazili i drugi koji na otoku bijahu bolesni te ozdravljali.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (51, 28, 10, 'Oni nas mnogim počastima počastiše i na odlasku nam priskrbiše što je potrebno.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (51, 28, 11, 'Nakon tri mjeseca otplovismo aleksandrijskom lađom koja je prezimila na otoku i imala za znak Dioskure.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (51, 28, 12, 'Doplovismo u Sirakuzu i ostadosmo ondje tri dana.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (51, 28, 13, 'Odande ploveći uz obalu, stigosmo u Regij. Sutradan okrenu južnjak te za dva dana stigosmo u Puteole.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (51, 28, 14, 'Ondje nađosmo braću koja nas zamoliše da ostanemo u njih sedam dana. Tako stigosmo u Rim.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (51, 28, 15, 'Kada su tamošnja braća čula za nas, iziđoše nam u susret do Apijeva trga i Triju gostionica. Kad ih Pavao ugleda, zahvali Bogu i ohrabri se.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (51, 28, 16, 'A kad uđosmo u Rim, Pavlu su dopustili stanovati zasebno, zajedno s vojnikom koji ga je čuvao.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (51, 28, 17, 'Nakon tri dana sazva on židovske prvake. Kad se sabraše, reče im: \"Ja, braćo, ne učinih ništa protiv naroda ni običaja otačkih, a ipak me okovana u Jeruzalemu predadoše u ruke Rimljana.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (51, 28, 18, 'Oni me nakon istrage htjedoše pustiti jer nije na meni bilo ništa čime bih bio zaslužio smrt.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (51, 28, 19, 'Kako se Židovi tome opriješe, bio sam prisiljen prizvati se na cara; ne dakle stoga što bih imao bilo za što tužiti svoj narod.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (51, 28, 20, 'S toga dakle razloga zamolih vidjeti vas i obratiti vam se jer zbog nade Izraelove nosim ove verige.\"');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (51, 28, 21, 'Oni mu odvrate: \"Mi o tebi nismo primili nikakva pisma iz Judeje niti nam je tko od pristigle braće o tebi što zlo javio ili rekao.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (51, 28, 22, 'Nego htjeli bismo od tebe čuti što misliš jer o toj sljedbi znamo samo da joj se posvuda proturječi.\"');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (51, 28, 23, 'Nato urekoše dan pa dođoše mnogi k njemu u stan. Izlagao im je i svjedočio o kraljevstvu Božjemu te ih od jutra do večeri iz Mojsijeva Zakona i Proroka uvjeravao o Isusu.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (51, 28, 24, 'I jedne uvjeriše njegove riječi, a drugi nisu vjerovali.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (51, 28, 25, 'Nesložni tako među sobom, stadoše se razilaziti kadli im Pavao reče još jednu riječ: \"Lijepo Duh Sveti po Izaiji proroku reče ocima vašim:');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (51, 28, 26, 'Idi k tomu narodu i reci mu: Slušat ćete, slušati - i nećete razumjeti; gledat ćete, gledati - i nećete vidjeti!');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (51, 28, 27, 'Jer usalilo se srce naroda ovoga: uši začepiše, oči zatvoriše da očima ne vide, ušima ne čuju, srcem ne razumiju te se ne obrate pa ih izliječim.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (51, 28, 28, 'Neka vam je dakle svima znano: poganima je poslano ovo spasenje Božje; oni će poslušati!\"');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (51, 28, 29, '#');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (51, 28, 30, 'Pavao osta pune dvije godine u svom unajmljenom stanu gdje je primao sve koji su dolazili k njemu,');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (51, 28, 31, 'propovijedao kraljevstvo Božje i naučavao o Gospodinu Isusu Kristu sa svom slobodom, nesmetano.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (52, 1, 1, 'Pavao, sluga Krista Isusa, pozvan za apostola, odlučen za evanđelje Božje -');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (52, 1, 2, 'koje Bog unaprijed obećavaše po svojim prorocima u Pismima svetim');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (52, 1, 3, 'o Sinu svome, potomku Davidovu po tijelu,');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (52, 1, 4, 'postavljenu Sinom Božjim, u snazi, po Duhu posvetitelju uskrsnućem od mrtvih, o Isusu Kristu, Gospodinu našemu,');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (52, 1, 5, 'po komu primismo milost i apostolstvo da na slavu imena njegova k poslušnosti vjere privodimo sve pogane');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (52, 1, 6, 'među kojima ste i vi pozvanici Isusa Krista:');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (52, 1, 7, 'svima u Rimu, miljenicima Božjim, pozvanicima, svetima. Milost vam i mir od Boga, Oca našega, i Gospodina Isusa Krista.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (52, 1, 8, 'Ponajprije zahvaljujem Bogu mojemu po Isusu Kristu za sve vas: što se vaša vjera navješćuje po svem svijetu.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (52, 1, 9, 'Doista, svjedok mi je Bog - komu duhom svojim služim u evanđelju Sina njegova - da vas se');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (52, 1, 10, 'u svojim molitvama neprekidno spominjem i uvijek molim ne bi li mi se već jednom s voljom Božjom nekako posrećilo doći k vama.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (52, 1, 11, 'Jer čeznem vidjeti vas da vam predam nešto dara duhovnoga te se ojačate, zapravo -');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (52, 1, 12, 'da se zajedno s vama ohrabrim zajedničkom vjerom, vašom i mojom.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (52, 1, 13, 'A ne bih htio, braćo, da ne znate: često sam bio nakanio doći k vama - i sve dosad bio spriječen - da i među vama uberem koji plod kao i među drugim narodima.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (52, 1, 14, 'Dužnik sam Grcima i barbarima, mudracima i neznalicama.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (52, 1, 15, 'Odatle moja nakana da i vama u Rimu navijestim evanđelje.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (52, 1, 16, 'Ne stidim se, uistinu, evanđelja: ono je snaga Božja na spasenje svakomu tko vjeruje - Židovu najprije, pa Grku.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (52, 1, 17, 'Jer pravednost se Božja od vjere k vjeri u njemu otkriva kao što je pisano: Pravednik će od vjere živjeti.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (52, 1, 18, 'Otkriva se doista s neba gnjev Božji na svaku bezbožnost i nepravednost ljudi koji istinu sputavaju nepravednošću.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (52, 1, 19, 'Jer što se o Bogu može spoznati, očito im je: Bog im očitova.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (52, 1, 20, 'Uistinu, ono nevidljivo njegovo, vječna njegova moć i božanstvo, onamo od stvaranja svijeta, umom se po djelima razabire tako da nemaju isprike.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (52, 1, 21, 'Jer premda upoznaše Boga, ne iskazaše mu kao Bogu ni slavu ni zahvalnost, nego ishlapiše u mozganjima svojim te se pomrači bezumno srce njihovo.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (52, 1, 22, 'Gradeći se mudrima, poludješe i');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (52, 1, 23, 'zamijeniše slavu neraspadljivog Boga likom, obličjem raspadljiva čovjeka, i ptica, i četveronožaca, i gmazova.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (52, 1, 24, 'Zato ih je Bog po pohotama srdaca njihovih predao nečistoći te sami obeščašćuju svoja tijela,');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (52, 1, 25, 'oni što su Istinu - Boga zamijenili lažju, častili i štovali stvorenje umjesto Stvoritelja, koji je blagoslovljen u vjekove. Amen.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (52, 1, 26, 'Stoga ih je Bog predao sramotnim strastima: njihove žene zamijeniše naravno općenje protunaravnim,');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (52, 1, 27, 'a tako su i muškarci napustili naravno općenje sa ženom i raspalili se pohotom jedni za drugima te muškarci s muškarcima sramotno čine i sami na sebi primaju zasluženu plaću svoga zastranjenja.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (52, 1, 28, 'I kako nisu smatrali vrijednim držati se spoznaje Boga, predade ih Bog nevaljanu umu te čine što ne dolikuje,');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (52, 1, 29, 'puni svake nepravde, pakosti, lakomosti, zloće; puni zavisti, ubojstva, svađe, prijevare, zlonamjernosti; došaptavači,');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (52, 1, 30, 'klevetnici, mrzitelji Boga, drznici, oholice, preuzetnici, izmišljači zala, roditeljima neposlušni,');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (52, 1, 31, 'nerazumni, nevjerni, bešćutni, nemilosrdni.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (52, 1, 32, 'Znaju za odredbu Božju - da smrt zaslužuju koji takvo što čine - a oni ne samo da to čine nego i povlađuju onima koji čine.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (52, 2, 1, 'Zato nemaš isprike, čovječe koji sudiš, tko god ti bio. Jer time što drugoga sudiš, sebe osuđuješ: ta to isto činiš ti što sudiš.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (52, 2, 2, 'Znamo pak: Bog po istini sudi one koji takvo što čine.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (52, 2, 3, 'Misliš li da ćeš izbjeći sudu Božjemu, ti čovječe što sudiš one koji takvo što čine, a sam to isto činiš?');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (52, 2, 4, 'Ili prezireš bogatstvo dobrote, strpljivosti i velikodušnosti njegove ne shvaćajući da te dobrota Božja k obraćenju privodi?');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (52, 2, 5, 'Tvrdokornošću svojom i srcem koje neće obraćenja zgrćeš na se gnjev za Dan gnjeva i objavljenja pravedna suda Boga');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (52, 2, 6, 'koji će uzvratiti svakom po djelima:');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (52, 2, 7, 'onima koji postojanošću u dobrim djelima ištu slavu, čast i neraspadljivost - život vječni;');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (52, 2, 8, 'buntovnicima pak i nepokornima istini, a pokornima nepravdi - gnjev i srdžba!');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (52, 2, 9, 'Nevolja i tjeskoba na svaku dušu čovječju koja čini zlo, na Židova najprije, pa na Grka;');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (52, 2, 10, 'a slava, čast i mir svakomu koji čini dobro, Židovu najprije, pa Grku!');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (52, 2, 11, 'Ta u Boga nema pristranosti.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (52, 2, 12, 'Uistinu koji bez Zakona sagriješiše, bez Zakona će i propasti; i koji pod Zakonom sagriješiše, po Zakonu će biti suđeni.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (52, 2, 13, 'Ne, pred Bogom nisu pravedni slušatelji Zakona, nego - izvršitelji će Zakona biti opravdani.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (52, 2, 14, 'Ta kad se god pogani, koji nemaju Zakona, po naravi drže Zakona, i nemajući Zakona, oni su sami sebi Zakon:');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (52, 2, 15, 'pokazuju da je ono što Zakon nalaže upisano u srcima njihovim. O tom svjedoči i njihova savjest, a i prosuđivanja kojima se među sobom optužuju ili brane.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (52, 2, 16, 'To će se očitovati na Dan u koji će, po mojem evanđelju, Bog po Isusu Kristu suditi ono što je skriveno u ljudima.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (52, 2, 17, 'Ako pak ti koji se Židovom nazivaš, koji mirno počivaš na Zakonu i dičiš se Bogom,');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (52, 2, 18, 'koji poznaješ Volju i iz Zakona poučen razlučuješ što je bolje');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (52, 2, 19, 'te si uvjeren da si vođa slijepih, svjetlo onih u tami,');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (52, 2, 20, 'odgojitelj nerazumnih, učitelj nejačadi jer u Zakonu imaš oličenje znanja i istine;');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (52, 2, 21, 'ti, dakle, koji drugoga učiš, sam sebe ne učiš! Ti koji propovijedaš da se ne krade, kradeš!');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (52, 2, 22, 'Ti koji zabranjuješ preljub, preljub počinjaš! Ti komu su odvratni kumiri, pljačkaš hramove!');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (52, 2, 23, 'Ti koji se Zakonom dičiš, kršenjem toga Zakona Boga obeščašćuješ!');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (52, 2, 24, 'Doista, kako je pisano, ime se Božje zbog vas huli među narodima.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (52, 2, 25, 'Da, obrezanje koristi ako vršiš Zakon; ako pak kršiš Zakon, obrezanje tvoje postalo je neobrezanje.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (52, 2, 26, 'Ako dakle neobrezani opslužuje propise Zakona, neće li se njegovo neobrezanje smatrati obrezanjem?');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (52, 2, 27, 'I onaj koji je podrijetlom neobrezanik, a ispunja Zakon, sudit će tebi koji si, uza sve slovo i obrezanje, prijestupnik Zakona.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (52, 2, 28, 'Ta nije Židov tko je Židov naizvana i nije obrezanje ono izvana,');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (52, 2, 29, 'na tijelu, nego pravi je Židov u nutrini i pravo je obrezanje u srcu, po duhu, ne po slovu. Pohvala mu nije od ljudi, nego od Boga.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (52, 3, 1, 'Koja je dakle prednost Židova? Ili kakva korist od obrezanja?');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (52, 3, 2, 'Velika u svakom pogledu. Ponajprije: povjerena su im obećanja Božja.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (52, 3, 3, 'Da, a što ako su se neki iznevjerili? Neće li njihova nevjernost obeskrijepiti vjernost Božju?');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (52, 3, 4, 'Nipošto! Nego neka Bog bude istinit, a svaki čovjek lažac, kao što je pisano: Da pravedan budeš po obećanjima svojim i pobijediš kada te sudili budu.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (52, 3, 5, 'Ako pak naša nepravednost ističe Božju pravednost, što ćemo na to reći? Nije li onda - po ljudsku govorim - nepravedan Bog koji daje maha gnjevu?');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (52, 3, 6, 'Nipošto! Ta kako će inače Bog suditi svijet?');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (52, 3, 7, 'Ako je, doista, istina Božja po mojoj lažljivosti obilno zasjala njemu na slavu, zašto da ja još budem suđen kao grešnik?');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (52, 3, 8, 'I zar da ne \"činimo zlo da dođe dobro\", kako nas kleveću i kako neki kažu da govorimo? Sud ih pravedni čeka!');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (52, 3, 9, 'Što dakle? Imamo li prednost? Ne baš! Jer upravo optužismo sve, i Židove i Grke, da su pod grijehom,');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (52, 3, 10, 'kao što je pisano: Nema pravedna ni jednoga,');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (52, 3, 11, 'nema razumna, nema ga tko bi Boga tražio.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (52, 3, 12, 'Svi skrenuše, svi se zajedno pokvariše, nitko da čini dobro - nijednoga nema.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (52, 3, 13, 'Grob otvoren grlo je njihovo, jezikom lažno laskaju, pod usnama im je otrov ljutičin,');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (52, 3, 14, 'usta im puna kletve i grkosti;');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (52, 3, 15, 'noge im hitre da krv proliju,');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (52, 3, 16, 'razvaline i nevolja na njinim su putima,');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (52, 3, 17, 'put mira oni ne poznaju,');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (52, 3, 18, 'straha Božjega nemaju pred očima.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (52, 3, 19, 'A znamo: što god Zakon veli, govori onima pod Zakonom, da svaka usta umuknu i sav svijet bude krivac pred Bogom.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (52, 3, 20, 'Zato se po djelima Zakona nitko neće opravdati pred njim. Uistinu, po Zakonu - samo spoznaja grijeha!');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (52, 3, 21, 'Sada se pak izvan Zakona očitovala pravednost Božja, posvjedočena Zakonom i Prorocima,');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (52, 3, 22, 'pravednost Božja po vjeri Isusa Krista, prema svima koji vjeruju. Ne, nema razlike!');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (52, 3, 23, 'Svi su zaista sagriješili i potrebna im je slava Božja;');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (52, 3, 24, 'opravdani su besplatno, njegovom milošću po otkupljenju u Kristu Isusu.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (52, 3, 25, 'Njega je Bog izložio da krvlju svojom bude Pomirilište po vjeri. Htio je tako očitovati svoju pravednost kojom je u svojoj božanskoj strpljivosti propuštao dotadašnje grijehe;');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (52, 3, 26, 'htio je očitovati svoju pravednost u sadašnje vrijeme - da bude pravedan i da opravdava onoga koji je od vjere Isusove.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (52, 3, 27, 'Gdje je dakle hvastanje? Isključeno je. Po kojem zakonu? Po zakonu djela? Ne, nego po zakonu vjere.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (52, 3, 28, 'Smatramo zaista da se čovjek opravdava vjerom bez djela Zakona.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (52, 3, 29, 'Ili je Bog samo Bog Židova? Nije li i pogana? Da, i pogana.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (52, 3, 30, 'Jer jedan je Bog: on će opravdati obrezane zbog vjere i neobrezane po vjeri.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (52, 3, 31, 'Obeskrepljujemo li dakle Zakon po vjeri? Nipošto! Naprotiv, Zakon utvrđujemo.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (52, 4, 1, 'Što ćemo dakle reći? Što je Abraham, otac naš, našao po tijelu?');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (52, 4, 2, 'Doista, ako je Abraham po djelima opravdan, ima se čime dičiti - ali ne pred Bogom.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (52, 4, 3, 'Ta što veli Pismo? Povjerova Abraham Bogu i uračuna mu se u pravednost.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (52, 4, 4, 'Onomu tko radi ne računa se plaća kao milost, nego kao dug.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (52, 4, 5, 'Onomu tko ne radi, a vjeruje u Onoga koji opravdava bezbožnika, vjera se uračunava u pravednost,');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (52, 4, 6, 'kao što i David blaženim proglašuje čovjeka kojemu Bog uračunava pravednost bez djela:');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (52, 4, 7, 'Blaženi oni kojima je zločin otpušten, kojima je grijeh pokriven!');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (52, 4, 8, 'Blago čovjeku komu Gospodin ne ubraja krivnju.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (52, 4, 9, 'Ide li dakle ovo blaženstvo samo obrezane ili i neobrezane? Ta velimo: Vjera se Abrahamu uračuna u pravednost.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (52, 4, 10, 'A kako mu se uračuna? Već obrezanu ili još neobrezanu? Ne obrezanu, nego neobrezanu!');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (52, 4, 11, 'I znak obrezanja primi kao pečat pravednosti koju je po vjeri zadobio još neobrezan, da bude ocem svih vjernika: neobrezanih - te im se uračuna pravednost -');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (52, 4, 12, 'i ocem obrezanih, ne onih koji su samo obrezani, nego onih koji uz to idu stopama vjere još neobrezana oca našeg Abrahama.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (52, 4, 13, 'Doista, obećanje da će biti baštinik svijeta nije Abrahamu ili njegovu potomstvu dano na temelju nekog zakona, nego na temelju pravednosti vjere.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (52, 4, 14, 'Jer ako su baštinici oni iz Zakona, prazna je vjera, jalovo obećanje.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (52, 4, 15, 'Ta Zakon rađa gnjev; gdje pak nema Zakona, nema ni prekršaja.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (52, 4, 16, 'Zato - zbog vjere da bude po milosti to obećanje zajamčeno svemu potomstvu, ne potomstvu samo po Zakonu, nego i po vjeri Abrahama, koji je otac svih nas -');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (52, 4, 17, 'kao što je pisano: Ocem mnoštva naroda ja te postavljam - pred Onim komu povjerova, pred Bogom koji oživljuje mrtve i zove da bude ono što nije.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (52, 4, 18, 'U nadi protiv svake nade povjerova Abraham da postane ocem naroda mnogih po onom što je rečeno: Toliko će biti tvoje potomstvo.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (52, 4, 19, 'Nepokolebljivom vjerom promotri on tijelo svoje već obamrlo - bilo mu je blizu sto godina - i obamrlost krila Sarina.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (52, 4, 20, 'Ali pred Božjim obećanjem nije nevjeran dvoumio, nego se vjerom ojačao davši slavu Bogu,');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (52, 4, 21, 'posve uvjeren da on može učiniti što je obećao.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (52, 4, 22, 'Zato mu se i uračuna u pravednost.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (52, 4, 23, 'Ali nije samo za nj napisano: Uračuna mu se,');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (52, 4, 24, 'nego i za nas kojima se ima uračunati, nama što vjerujemo u Onoga koji od mrtvih uskrisi Isusa, Gospodina našega,');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (52, 4, 25, 'koji je predan za opačine naše i uskrišen radi našeg opravdanja.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (52, 5, 1, 'Opravdani dakle vjerom, u miru smo s Bogom po Gospodinu našem Isusu Kristu.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (52, 5, 2, 'Po njemu imamo u vjeri i pristup u ovu milost u kojoj stojimo i dičimo se nadom slave Božje.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (52, 5, 3, 'I ne samo to! Mi se dičimo i u nevoljama jer znamo: nevolja rađa postojanošću,');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (52, 5, 4, 'postojanost prokušanošću, prokušanost nadom.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (52, 5, 5, 'Nada pak ne postiđuje. Ta ljubav je Božja razlivena u srcima našim po Duhu Svetom koji nam je dan!');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (52, 5, 6, 'Doista, dok mi još bijasmo nemoćni, Krist je, već u to vrijeme, za nas bezbožnike umro.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (52, 5, 7, 'Zbilja, jedva bi tko za pravedna umro; možda bi se za dobra tko i odvažio umrijeti.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (52, 5, 8, 'A Bog pokaza ljubav svoju prema nama ovako: dok još bijasmo grešnici, Krist za nas umrije.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (52, 5, 9, 'Koliko li ćemo se više sada, pošto smo opravdani krvlju njegovom, spasiti po njemu od srdžbe?');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (52, 5, 10, 'Doista, ako se s Bogom pomirismo po smrti Sina njegova dok još bijasmo neprijatelji, mnogo ćemo se više, pomireni, spasiti životom njegovim.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (52, 5, 11, 'I ne samo to! Dičimo se u Bogu po Gospodinu našemu Isusu Kristu po kojem zadobismo pomirenje.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (52, 5, 12, 'Zbog toga, kao što po jednom Čovjeku uđe u svijet grijeh i po grijehu smrt, i time što svi sagriješiše, na sve ljude prijeđe smrt...');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (52, 5, 13, 'Doista, do Zakona bilo je grijeha u svijetu, ali se grijeh ne ubraja kad nema zakona.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (52, 5, 14, 'Da, ali smrt je od Adama do Mojsija doista kraljevala i nad onima koji ne sagriješiše prekršajem sličnim kao Adam, koji je pralik Onoga koji ima doći.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (52, 5, 15, 'Ali s darom nije kao s grijehom. Jer ako su grijehom jednoga mnogi umrli, mnogo se obilatije na sve razlila milost Božja, milost darovana u jednom čovjeku, Isusu Kristu.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (52, 5, 16, 'I dar - to nije kao kad je ono jedan sagriješio: jer presuda nakon jednoga grijeha posta osudom, a dar nakon mnogih grijeha - opravdanjem.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (52, 5, 17, 'Uistinu, ako grijehom jednoga smrt zakraljeva - po jednome, mnogo će više oni koji primaju izobilje milosti i dara pravednosti kraljevati u životu - po Jednome, Isusu Kristu.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (52, 5, 18, 'Dakle, grijeh jednoga - svim ljudima na osudu, tako i pravednost Jednoga - svim ljudima na opravdanje, na život!');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (52, 5, 19, 'Doista, kao što su neposluhom jednoga čovjeka mnogi postali grešnici tako će i posluhom Jednoga mnogi postati pravednici.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (52, 5, 20, 'A zakon nadođe da se umnoži grijeh. Ali gdje se umnožio grijeh, nadmoćno izobilova milost:');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (52, 5, 21, 'kao što grijeh zakraljeva smrću, da tako i milost kraljuje pravednošću za život vječni po Isusu Kristu Gospodinu našemu.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (52, 6, 1, 'Što ćemo dakle reći? Da ostanemo u grijehu da milost izobiluje?');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (52, 6, 2, 'Nipošto! Jednom umrli grijehu, kako da još živimo u njemu?');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (52, 6, 3, 'Ili zar ne znate: koji smo god kršteni u Krista Isusa, u smrt smo njegovu kršteni.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (52, 6, 4, 'Krštenjem smo dakle zajedno s njime ukopani u smrt da kao što Krist slavom Očevom bi uskrišen od mrtvih, i mi tako hodimo u novosti života.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (52, 6, 5, 'Ako smo doista s njime srasli po sličnosti smrti njegovoj, očito ćemo srasti i po sličnosti njegovu uskrsnuću.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (52, 6, 6, 'Ovo znamo: naš je stari čovjek zajedno s njim raspet da onemoća ovo grešno tijelo te više ne robujemo grijehu.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (52, 6, 7, 'Ta tko umre, opravdan je od grijeha.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (52, 6, 8, 'Pa ako umrijesmo s Kristom, vjerujemo da ćemo i živjeti zajedno s njime.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (52, 6, 9, 'Znamo doista: Krist uskrišen od mrtvih, više ne umire, smrt njime više ne gospoduje.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (52, 6, 10, 'Što umrije, umrije grijehu jednom zauvijek; a što živi, živi Bogu.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (52, 6, 11, 'Tako i vi: smatrajte sebe mrtvima grijehu, a živima Bogu u Kristu Isusu!');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (52, 6, 12, 'Neka dakle ne kraljuje grijeh u vašem smrtnom tijelu da slušate njegove požude;');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (52, 6, 13, 'i ne predajite grijehu udova svojih za oružje nepravde, nego sebe, od mrtvih oživjele, predajte Bogu i udove svoje dajte Bogu za oružje pravednosti.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (52, 6, 14, 'Valjda grijeh neće vama gospodovati! Ta niste pod Zakonom nego pod milošću!');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (52, 6, 15, 'Što dakle? Da griješimo jer nismo pod Zakonom nego pod milošću? Nipošto!');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (52, 6, 16, 'Ne znate li: ako se komu predate za robove, na poslušnost, robovi ste onoga koga slušate: bilo grijeha - na smrt, bilo poslušnosti - na pravednost.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (52, 6, 17, 'Bijaste robovi grijeha, ali ste, hvala Bogu, od srca poslušali ono pravilo nauka kojemu ste povjereni;');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (52, 6, 18, 'da, oslobođeni grijeha, postadoste sluge pravednosti.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (52, 6, 19, 'Po ljudsku govorim zbog vaše ljudske slabosti: kao što nekoć predadoste udove svoje za robove nečistoći i bezakonju - do bezakonja, tako sada predajte udove svoje za robove pravednosti - do posvećenja.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (52, 6, 20, 'Uistinu, kad bijaste robovi grijeha, \"slobodni\" bijaste od pravednosti.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (52, 6, 21, 'Pa kakav ste plod onda imali? Onoga se sada stidite jer svršetak je tomu - smrt.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (52, 6, 22, 'Sada pak pošto ste oslobođeni grijeha i postali sluge Božje, imate plod svoj za posvećenje, a svršetak - život vječni.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (52, 6, 23, 'Jer plaća je grijeha smrt, a dar Božji jest život vječni u Kristu Isusu, Gospodinu našem.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (52, 7, 1, 'Ili zar ne znate, braćo - poznavaocima zakona govorim - da zakon gospodari čovjekom samo za vrijeme njegova života.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (52, 7, 2, 'Doista, udana je žena vezana zakonom dok joj muž živi; umre li joj muž, riješena je zakona o mužu.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (52, 7, 3, 'Dakle: dok joj muž živi, zvat će se, očito, preljubnicom pođe li za drugoga. Ako li joj pak muž umre, slobodna je od zakona te nije preljubnica pođe li za drugoga.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (52, 7, 4, 'Tako, braćo moja, i vi po tijelu Kristovu umrijeste Zakonu da pripadnete drugomu, Onomu koji je od mrtvih uskrišen, te plodove donosimo Bogu.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (52, 7, 5, 'Doista, dok bijasmo u tijelu, grešne su strasti, Zakonom izazvane, djelovale u našim udovima te smrti donosile plodove;');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (52, 7, 6, 'sada pak umrijevši onomu što nas je sputavalo, riješeni smo Zakona te služimo u novosti Duha, a ne u stareži slova.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (52, 7, 7, 'Što ćemo dakle reći? Je li Zakon grijeh? Nipošto! Nego: grijeha ne spoznah doli po Zakonu jer za požudu ne bih znao da Zakon nije govorio: Ne poželi!');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (52, 7, 8, 'A grijeh je, uhvativši priliku, po zapovijedi u meni prouzročio svakovrsnu požudu. Ta bez zakona grijeh je mrtav.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (52, 7, 9, 'Da, ja sam nekoć živio bez zakona. Ali kad je došla zapovijed, grijeh oživje.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (52, 7, 10, 'Ja pak umrijeh i ustanovi se: zapovijed dana za život bi mi na smrt.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (52, 7, 11, 'Doista grijeh, uhvativši priliku, zapovijeđu me zavede, njome me i ubi.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (52, 7, 12, 'Tako: Zakon je svet, i zapovijed je sveta, i pravedna, i dobra.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (52, 7, 13, 'Pa zar se to dobro meni u smrt prometnu? Nipošto! Nego: grijeh, da se grijehom očituje, po tom dobru uzrokuje mi smrt - da grijeh po zapovijedi postane najvećim grešnikom.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (52, 7, 14, 'Zakon je, znamo, duhovan; ja sam pak tjelesan, prodan pod grijeh.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (52, 7, 15, 'Zbilja ne razumijem što radim: ta ne činim ono što bih htio, nego što mrzim - to činim.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (52, 7, 16, 'Ako li pak činim što ne bih htio, slažem se sa Zakonom, priznajem da je dobar.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (52, 7, 17, 'Onda to ne činim više ja, nego grijeh koji prebiva u meni.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (52, 7, 18, 'Doista znam da dobro ne prebiva u meni, to jest u mojem tijelu. Uistinu: htjeti mi ide, ali ne i činiti dobro.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (52, 7, 19, 'Ta ne činim dobro koje bih htio, nego zlo koje ne bih htio - to činim.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (52, 7, 20, 'Ako li pak činim ono što ne bih htio, nipošto to ne radim ja, nego grijeh koji prebiva u meni.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (52, 7, 21, 'Nalazim dakle ovaj zakon: kad bih htio činiti dobro, nameće mi se zlo.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (52, 7, 22, 'Po nutarnjem čovjeku s užitkom se slažem sa Zakonom Božjim,');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (52, 7, 23, 'ali opažam u svojim udovima drugi zakon koji vojuje protiv zakona uma moga i zarobljuje me zakonom grijeha koji je u mojim udovima.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (52, 7, 24, 'Jadan li sam ja čovjek! Tko će me istrgnuti iz ovoga tijela smrtonosnoga?');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (52, 7, 25, 'Hvala Bogu po Isusu Kristu Gospodinu našem! Ja, dakle, umom ja služim zakonu Božjemu, a tijelom zakonu grijeha.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (52, 8, 1, 'Nikakve dakle sada osude onima koji su u Kristu Isusu!');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (52, 8, 2, 'Ta zakon Duha života u Kristu Isusu oslobodi me zakona grijeha i smrti.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (52, 8, 3, 'Uistinu, što je bilo nemoguće Zakonu, jer je zbog tijela onemoćao, Bog je učinio: poslavši Sina svoga u obličju grešnoga tijela i s obzirom na grijeh, osudi grijeh u tijelu');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (52, 8, 4, 'da se pravednost Zakona ispuni u nama koji ne živimo po tijelu nego po Duhu.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (52, 8, 5, 'Da, oni koji žive po tijelu, teže za onim što je tjelesno; a koji po Duhu, za onim što je Duhovo:');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (52, 8, 6, 'težnja je tijela smrt, a težnja Duha život i mir.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (52, 8, 7, 'Jer težnja je tijela protivna Bogu: zakonu se Božjemu ne podvrgava, a i ne može.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (52, 8, 8, 'Oni pak koji su u tijelu, ne mogu se Bogu svidjeti.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (52, 8, 9, 'A vi niste u tijelu, nego u Duhu, ako Duh Božji prebiva u vama. A nema li tko Duha Kristova, taj nije njegov.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (52, 8, 10, 'I ako je Krist u vama, tijelo je doduše mrtvo zbog grijeha, ali Duh je život zbog pravednosti.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (52, 8, 11, 'Ako li Duh Onoga koji uskrisi Isusa od mrtvih prebiva u vama, Onaj koji uskrisi Krista od mrtvih oživit će i smrtna tijela vaša po Duhu svome koji prebiva u vama.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (52, 8, 12, 'Dakle, braćo, dužnici smo, ali ne tijelu da po tijelu živimo!');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (52, 8, 13, 'Jer ako po tijelu živite, umrijeti vam je, ako li pak Duhom usmrćujete tjelesna djela, živjet ćete.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (52, 8, 14, 'Svi koje vodi Duh Božji sinovi su Božji.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (52, 8, 15, 'Ta ne primiste duh robovanja da se opet bojite, nego primiste Duha posinstva u kojem kličemo: \"Abba! Oče!\"');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (52, 8, 16, 'Sam Duh susvjedok je s našim duhom da smo djeca Božja;');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (52, 8, 17, 'ako pak djeca, onda i baštinici, baštinici Božji, a subaštinici Kristovi, kada doista s njime zajedno trpimo, da se zajedno s njime i proslavimo.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (52, 8, 18, 'Smatram, uistinu: sve patnje sadašnjega vremena nisu ništa prema budućoj slavi koja se ima očitovati u nama.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (52, 8, 19, 'Doista, stvorenje sa svom žudnjom iščekuje ovo objavljenje sinova Božjih:');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (52, 8, 20, 'stvorenje je uistinu podvrgnuto ispraznosti - ne po svojoj volji, nego zbog onoga koji ga podvrgnu - ali u nadi.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (52, 8, 21, 'Jer i stvorenje će se osloboditi robovanja pokvarljivosti da sudjeluje u slobodi i slavi djece Božje.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (52, 8, 22, 'Jer znamo: sve stvorenje zajedno uzdiše i muči se u porođajnim bolima sve do sada.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (52, 8, 23, 'Ali ne samo ono! I mi koji imamo prvine Duha, i mi u sebi uzdišemo iščekujući posinstvo, otkupljenje svoga tijela.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (52, 8, 24, 'Ta u nadi smo spašeni! Nada pak koja se vidi nije nada. Jer što tko gleda, kako da se tomu i nada?');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (52, 8, 25, 'Nadamo li se pak onomu čega ne gledamo, postojano to iščekujemo.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (52, 8, 26, 'Tako i Duh potpomaže našu nemoć. Doista ne znamo što da molimo kako valja, ali se sam Duh za nas zauzima neizrecivim uzdasima.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (52, 8, 27, 'A Onaj koji proniče srca zna koja je želja Duha - da se on po Božju zauzima za svete.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (52, 8, 28, 'Znamo pak da Bog u svemu na dobro surađuje s onima koji ga ljube, s onima koji su odlukom njegovom pozvani.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (52, 8, 29, 'Jer koje predvidje, te i predodredi da budu suobličeni slici Sina njegova te da on bude prvorođenac među mnogom braćom.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (52, 8, 30, 'Koje pak predodredi, te i pozva; koje pozva, te i opravda; koje opravda, te i proslavi.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (52, 8, 31, 'Što ćemo dakle na to reći? Ako je Bog za nas, tko će protiv nas?');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (52, 8, 32, 'Ta on ni svojega Sina nije poštedio, nego ga je za sve nas predao! Kako nam onda s njime neće sve darovati?');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (52, 8, 33, 'Tko će optužiti izabranike Božje? Bog opravdava!');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (52, 8, 34, 'Tko će osuditi? Krist Isus umrije, štoviše i uskrsnu, on je i zdesna Bogu - on se baš zauzima za nas!');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (52, 8, 35, 'Tko će nas rastaviti od ljubavi Kristove? Nevolja? Tjeskoba? Progonstvo? Glad? Golotinja? Pogibao? Mač?');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (52, 8, 36, 'Kao što je pisano: Poradi tebe ubijaju nas dan za danom i mi smo im ko ovce za klanje.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (52, 8, 37, 'U svemu tome nadmoćno pobjeđujemo po onome koji nas uzljubi.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (52, 8, 38, 'Uvjeren sam doista: ni smrt ni život, ni anđeli ni vlasti, ni sadašnjost ni budućnost, ni sile,');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (52, 8, 39, 'ni dubina ni visina, ni ikoji drugi stvor neće nas moći rastaviti od ljubavi Božje u Kristu Isusu Gospodinu našem.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (52, 9, 1, 'Istinu govorim u Kristu, ne lažem; susvjedok mi je savjest moja u Duhu Svetom:');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (52, 9, 2, 'silna mi je tuga i neprekidna bol u srcu.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (52, 9, 3, 'Da, htio bih ja sam proklet biti, odvojen od Krista, za braću svoju, sunarodnjake svoje po tijelu.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (52, 9, 4, 'Oni su Izraelci, njihovo je posinstvo, i Slava, i Savezi, i zakonodavstvo, i bogoštovlje, i obećanja;');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (52, 9, 5, 'njihovi su i oci, od njih je, po tijelu, i Krist, koji je iznad svega, Bog blagoslovljen u vjekove. Amen.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (52, 9, 6, 'Ali ne kao da se izjalovila riječ Božja. Jer nisu Izrael svi koji potječu od Izraela;');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (52, 9, 7, 'i nisu svi djeca Abrahamova zato što su njegovo potomstvo, nego po Izaku će ti se nazivati potomstvo;');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (52, 9, 8, 'to jest: djeca tijela nisu i djeca Božja, nego - djeca obećanja računaju se u potomstvo.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (52, 9, 9, 'Evo doista riječi obećanja: U ovo ću doba doći i Sara će imati sina.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (52, 9, 10, 'Ali ne samo to! I Rebeka je s jednim, s Izakom, ocem našim, zanijela.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (52, 9, 11, 'Pa kad još blizanci ne bijahu rođeni niti učiniše što dobro ili zlo - da bi trajnom ostala odluka Božja o izabranju:');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (52, 9, 12, 'ne po djelima, nego po onome tko poziva - rečeno joj je: Stariji će služiti mlađemu,');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (52, 9, 13, 'kako je pisano: Jakova sam zavolio, a Ezav mi omrznu.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (52, 9, 14, 'Što ćemo dakle reći? Možda da u Boga ima nepravde? Nipošto!');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (52, 9, 15, 'Ta Mojsiju veli: Smilovat ću se komu hoću da se smilujem; sažalit ću se nad kim hoću da se sažalim.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (52, 9, 16, 'Nije dakle do onoga koji hoće ni do onoga koji trči, nego do Boga koji se smiluje.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (52, 9, 17, 'Jer Pismo veli faraonu: Zato te upravo podigoh da na tebi pokažem svoju moć i da se razglasi ime moje po svoj zemlji.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (52, 9, 18, 'Tako dakle: smiluje se komu hoće, a otvrdnjuje koga hoće.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (52, 9, 19, 'Da, reći ćeš mi: Što se onda još tuži? Ta tko se to volji njegovoj odupro?');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (52, 9, 20, 'Čovječe, tko si ti zapravo da se pravdaš s Bogom? Zar da djelo rekne tvorcu: \"Što si me ovakvim načinio?\"');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (52, 9, 21, 'Ili zar lončar nema vlasti nad glinom da od istoga tijesta načini posudu sad časnu, sad nečasnu.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (52, 9, 22, 'A što ako je Bog, hoteći očitovati gnjev i obznaniti svoju moć u silnoj strpljivosti podnosio posude gnjeva, dozrele za propast,');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (52, 9, 23, 'da obznani bogatstvo slave svoje na posudama milosrđa, koje unaprijed pripravi za slavu,');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (52, 9, 24, 'na nama koje pozva ne samo između Židova nego i između pogana?');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (52, 9, 25, 'Tako i u Hošeji veli: Ne-narod moj prozvat ću narodom mojim i Neljubljenu ljubljenom.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (52, 9, 26, 'Na mjestu gdje im je rečeno: Vi niste moj narod prozvat će se sinovi Boga živoga.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (52, 9, 27, 'Izaija pak proglasuje o Izraelu: Zaista, sinova će Izraelovih brojem biti kao pijeska morskog - Ostatak će se spasiti;');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (52, 9, 28, 'jer riječ će ispuniti i uskoro izvršiti Gospodin na zemlji.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (52, 9, 29, 'Tako je Izaija i prorekao: Da nam Gospodin nad Vojskama ne ostavi sjeme, ko Sodoma bismo bili i Gomori nalik.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (52, 9, 30, 'Što ćemo dakle reći? Da pogani koji nisu tražili pravednosti stekoše pravednost, pravednost po vjeri.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (52, 9, 31, 'Izrael pak koji je tražio neki zakon pravednosti, nije do zakona dopro.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (52, 9, 32, 'Zašto? Jer nije tražio po vjeri, nego kao po djelima. Spotakoše se o kamen spoticanja,');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (52, 9, 33, 'kao što je pisano: Evo postavljam na Sionu kamen spoticanja i stijenu posrtanja. Ali tko u nj vjeruje, neće se postidjeti.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (52, 10, 1, 'Braćo! Želja je srca moga i molitva Bogu za njih: da se spase.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (52, 10, 2, 'Svjedočim doista za njih: imaju revnosti Božje, ali ne u pravom razumijevanju.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (52, 10, 3, 'Ne priznajući, doista, Božje pravednosti i tražeći uspostaviti svoju, pravednosti se Božjoj ne podložiše.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (52, 10, 4, 'Jer dovršetak je Zakona Krist - na opravdanje svakomu tko vjeruje.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (52, 10, 5, 'Da, Mojsije piše o onoj pravednosti iz Zakona: Tko je vrši, naći će život u njoj.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (52, 10, 6, 'A pravednost iz vjere ovako veli: Nemoj reći u srcu svom: Tko će se popeti na nebo - to jest Krista svesti?');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (52, 10, 7, 'Ili: Tko će sići u bezdan - to jest izvesti Krista od mrtvih?');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (52, 10, 8, 'Nego što veli? Blizu ti je Riječ, u ustima tvojim i u srcu tvome - to jest Riječ vjere koju propovijedamo.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (52, 10, 9, 'Jer ako ustima ispovijedaš da je Isus Gospodin, i srcem vjeruješ da ga je Bog uskrisio od mrtvih, bit ćeš spašen.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (52, 10, 10, 'Doista, srcem vjerovati opravdava, a ustima ispovijedati spasava.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (52, 10, 11, 'Jer veli Pismo: Tko god u nj vjeruje, neće se postidjeti.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (52, 10, 12, 'Nema uistinu razlike između Židova i Grka jer jedan je Gospodin sviju, bogat prema svima koji ga prizivlju.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (52, 10, 13, 'Jer: Tko god prizove ime Gospodnje, bit će spašen.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (52, 10, 14, 'Ali kako da prizovu onoga u koga ne povjerovaše? A kako da povjeruju u onoga koga nisu čuli? Kako pak da čuju bez propovjednika?');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (52, 10, 15, 'A kako propovijedati bez poslanja? Tako je pisano: Kako li su ljupke noge onih koji donose blagovijest dobra.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (52, 10, 16, 'Ali nisu svi poslušali blagovijesti - evanđelja! Zaista, Izaija veli: Gospodine, tko povjerova našoj poruci?');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (52, 10, 17, 'Dakle: vjera po poruci, a poruka riječju Kristovom.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (52, 10, 18, 'Nego pitam: Zar nisu čuli? Dapače! Po svoj zemlji razliježe se jeka, riječi njihove sve do nakraj svijeta.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (52, 10, 19, 'Onda pitam: Zar Izrael nije shvatio? Najprije Mojsije veli: Ja ću vas na ljubomor izazvati pukom ništavnim, razdražit ću vas glupim nekim narodom.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (52, 10, 20, 'Izaija pak hrabro veli: Nađoše me koji me ne tražahu, objavih se onima koji me ne pitahu.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (52, 10, 21, 'A Izraelu veli: Cio dan pružah ruku narodu nepokornom i buntovnom.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (52, 11, 1, 'Pitam dakle: Zar je Bog odbacio narod svoj? Nipošto? Ta i ja sam Izraelac, iz potomstva Abrahamova, plemena Benjaminova.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (52, 11, 2, 'Nije Bog odbacio naroda svojega koga predvidje. Ili zar ne znate što veli Pismo, ono o Iliji - kako se tuži Bogu na Izraela:');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (52, 11, 3, 'Gospode, proroke tvoje pobiše, žrtvenike tvoje porušiše; ja ostadoh sam i još mi o glavi rade.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (52, 11, 4, 'Pa što mu veli Božji glas? Ostavih sebi sedam tisuća ljudi koji ne prignuše koljena pred Baalom.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (52, 11, 5, 'Tako dakle i u sadašnje vrijeme postoji Ostatak po milosnom izboru.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (52, 11, 6, 'Ako pak po milosti, nije po djelima; inače milost nije više milost!');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (52, 11, 7, 'Što dakle? Što Izrael ište, to nije postigao, ali izabrani postigoše. Ostali pak otvrdnuše,');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (52, 11, 8, 'kao što je pisano: Dade im Bog duh obamrlosti, oči da ne vide, uši da ne čuju sve do dana današnjega.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (52, 11, 9, 'I David veli: Nek im stol pred njima bude zamkom, i mrežom, i stupicom, i plaćom.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (52, 11, 10, 'Nek im potamne oči da ne vide i leđa im zauvijek pogni!');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (52, 11, 11, 'Pitam dakle: jesu li posrnuli da propadnu? Nipošto! Naprotiv: po njihovu posrtaju spasenje poganima da se tako oni, Židovi, izazovu na ljubomor.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (52, 11, 12, 'Pa ako je njihov posrtaj bogatstvo za svijet, i njihovo smanjenje bogatstvo za pogane, koliko li će više to biti njihov puni broj?');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (52, 11, 13, 'Vama pak, poganima, velim: ja kao apostol pogana službu svoju proslavljam');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (52, 11, 14, 'ne bih li na ljubomor izazvao njih, tijelo svoje, i spasio neke od njih.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (52, 11, 15, 'Jer ako je njihovo odbačenje izmirenje svijeta, što li će biti njihovo prihvaćanje ako ne oživljenje od mrtvih?');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (52, 11, 16, 'Ako li su prvine svete, sveto je i tijesto; ako li je korijen svet, svete su i grane.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (52, 11, 17, 'Pa ako su neke grane odlomljene, a ti, divlja maslina, pricijepljen umjesto njih, postao suzajedničar korijena, sočnosti masline,');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (52, 11, 18, 'ne uznosi se nad grane. Ako li se hoćeš uznositi - ne nosiš ti korijena, nego korijen tebe.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (52, 11, 19, 'Reći ćeš na to: grane su odlomljene da se ja pricijepim.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (52, 11, 20, 'Dobro! Oni su zbog nevjere odlomljeni, a ti po vjeri stojiš. Ne uznosi se, nego strahuj!');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (52, 11, 21, 'Jer ako Bog ne poštedje prirodnih grana, ni tebe neće poštedjeti.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (52, 11, 22, 'Promotri dakle dobrotu i strogost Božju: strogost na palima, a dobrotu Božju na sebi ako ostaneš u toj dobroti, inače ćeš i ti biti odsječen.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (52, 11, 23, 'A i oni, ako ne ostanu u nevjeri, bit će pricijepljeni; ta moćan je Bog da ih opet pricijepi.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (52, 11, 24, 'Doista, ako si ti, po naravi divlja maslina, odsječen pa mimo narav pricijepljen na pitomu maslinu, koliko li će lakše oni po naravi biti pricijepljeni na vlastitu maslinu!');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (52, 11, 25, 'Jer ne bih htio, braćo, da budete sami po sebi pametni, a da ne znate ovo otajstvo: djelomično je otvrdnuće zadesilo Izraela dok punina pogana ne uđe.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (52, 11, 26, 'I tako će se cio Izrael spasiti, kako je pisano: Doći će sa Siona Otkupitelj, odvratit će bezbožnost od Jakova.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (52, 11, 27, 'I to će biti moj Savez s njima, kad uklonim grijehe njihove.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (52, 11, 28, 'U pogledu evanđelja oni su, istina, protivnici poradi vas, ali u pogledu izabranja oni su ljubimci poradi otaca.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (52, 11, 29, 'Ta neopozivi su dari i poziv Božji!');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (52, 11, 30, 'Doista, kao što vi nekoć bijaste neposlušni Bogu, a sada po njihovoj neposlušnosti zadobiste milosrđe');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (52, 11, 31, 'tako i oni sada po milosrđu vama iskazanu postadoše neposlušni da i oni sada zadobiju milosrđe.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (52, 11, 32, 'Jer Bog je sve zatvorio u neposlušnost da se svima smiluje.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (52, 11, 33, 'O dubino bogatstva, i mudrosti, i spoznanja Božjega! Kako li su nedokučivi sudovi i neistraživi putovi njegovi!');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (52, 11, 34, 'Doista, tko spozna misao Gospodnju, tko li mu bi savjetnikom?');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (52, 11, 35, 'Ili: tko ga darom preteče da bi mu se uzvratiti moralo?');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (52, 11, 36, 'Jer sve je od njega i po njemu i za njega! Njemu slava u vjekove! Amen.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (52, 12, 1, 'Zaklinjem vas, braćo, milosrđem Božjim: prikažite svoja tijela za žrtvu živu, svetu, Bogu milu - kao svoje duhovno bogoslužje.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (52, 12, 2, 'Ne suobličujte se ovomu svijetu, nego se preobrazujte obnavljanjem svoje pameti da mognete razabirati što je volja Božja, što li je dobro, Bogu milo, savršeno.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (52, 12, 3, 'Da, po milosti koja mi je dana svakomu između vas velim: ne precjenjujte se više no što se treba cijeniti, nego cijenite se razumno, kako je već komu Bog odmjerio mjeru vjere.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (52, 12, 4, 'Jer kao što u jednom tijelu imamo mnogo udova, a nemaju svi isto djelovanje,');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (52, 12, 5, 'tako smo i mi, mnogi, jedno tijelo u Kristu, a pojedinci udovi jedan drugomu.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (52, 12, 6, 'Dare pak imamo različite po milosti koja nam je dana: je li to prorokovanje - neka je primjereno vjeri;');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (52, 12, 7, 'je li služenje - neka je u služenju; je li poučavanje - u poučavanju;');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (52, 12, 8, 'je li hrabrenje - u hrabrenju; tko dijeli, neka je darežljiv; tko je predstojnik - revan; tko iskazuje milosrđe - radostan!');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (52, 12, 9, 'Ljubav nehinjena! Zazirite oda zla, prianjajte uz dobro!');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (52, 12, 10, 'Srdačno se ljubite pravim bratoljubljem! Pretječite jedni druge poštovanjem!');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (52, 12, 11, 'U revnosti budite hitri, u duhu gorljivi, Gospodinu služite!');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (52, 12, 12, 'U nadi budite radosni, u nevolji strpljivi, u molitvi postojani!');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (52, 12, 13, 'Pritječite u pomoć svetima u nuždi, gajite gostoljubivost!');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (52, 12, 14, 'Blagoslivljajte svoje progonitelje, blagoslivljajte, a ne proklinjite!');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (52, 12, 15, 'Radujte se s radosnima, plačite sa zaplakanima!');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (52, 12, 16, 'Budite istomišljenici među sobom! Neka vas ne zanosi što je visoko, nego privlači što je ponizno. Ne umišljajte si da ste mudri!');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (52, 12, 17, 'Nikome zlo za zlo ne vraćajte; zauzimajte se za dobro pred svim ljudima!');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (52, 12, 18, 'Ako je moguće, koliko je do vas, u miru budite sa svim ljudima!');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (52, 12, 19, 'Ne osvećujte se, ljubljeni, nego dajte mjesta Božjem gnjevu. Ta pisano je: Moja je odmazda, ja ću je vratiti, veli Gospodin.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (52, 12, 20, 'Naprotiv: Ako je gladan neprijatelj tvoj, nahrani ga, i ako je žedan, napoj ga! Činiš li tako, ugljevlje mu ražareno zgrćeš na glavu.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (52, 12, 21, 'Ne daj se pobijediti zlom, nego dobrim svladavaj zlo.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (52, 13, 1, 'Svaka duša neka se podlaže vlastima nad sobom. Jer nema vlasti doli od Boga: koje postoje, od Boga su postavljene.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (52, 13, 2, 'Stoga tko se suprotstavlja vlasti, Božjoj se odredbi protivi; koji se pak protive, sami će na se navući osudu.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (52, 13, 3, 'Vladari doista nisu strah i trepet zbog dobra, nego zbog zla djela. Hoćeš li se ne bojati vlasti? Dobro čini pa ćeš imati pohvalu od nje!');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (52, 13, 4, 'Ta Božji je ona poslužitelj - tebi na dobro. Ako li zlo činiš, strahuj! Ne nosi uzalud mača! Božji je ona poslužitelj: gnjev njegov iskaljuje na onome koji zlo čini.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (52, 13, 5, 'Treba se stoga podlagati, ne samo zbog gnjeva nego i zbog savjesti.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (52, 13, 6, 'Zato i poreze plaćate: ta službenici su Božji oni koji se time bave.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (52, 13, 7, 'Dajte svakomu što mu pripada: komu porez - porez, komu carina - carina, komu poštovanje - poštovanje, komu čast - čast.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (52, 13, 8, 'Nikomu ništa ne dugujte, osim da jedni druge ljubite. Jer tko drugoga ljubi, ispunio je Zakon.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (52, 13, 9, 'Uistinu: Ne čini preljuba! Ne ubij! Ne ukradi! Ne poželi! i ima li koja druga zapovijed, sažeta je u ovoj riječi: Ljubi svoga bližnjega kao sebe samoga.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (52, 13, 10, 'Ljubav bližnjemu zla ne čini. Punina dakle Zakona jest ljubav.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (52, 13, 11, 'To tim više što shvaćate ovaj čas: vrijeme je već da se oda sna prenemo jer nam je sada spasenje bliže nego kad povjerovasmo.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (52, 13, 12, 'Noć poodmače, dan se približi! Odložimo dakle djela tame i zaodjenimo se oružjem svjetlosti.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (52, 13, 13, 'Kao po danu pristojno hodimo, ne u pijankama i pijančevanjima, ne u priležništvima i razvratnostima, ne u svađi i ljubomoru,');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (52, 13, 14, 'nego zaodjenite se Gospodinom Isusom Kristom i, u brizi za tijelo, ne pogodujte požudama.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (52, 14, 1, 'Slaboga u vjeri prigrlite, ali ne da se prepirete o mišljenjima.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (52, 14, 2, 'Netko vjeruje da smije sve jesti, slabi opet jede samo povrće.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (52, 14, 3, 'Tko jede, neka ne prezire onoga tko ne jede; tko pak ne jede, neka ne sudi onoga tko jede. Ta Bog ga je prigrlio.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (52, 14, 4, 'Tko si ti da sudiš tuđega slugu? Svojemu Gospodaru i stoji i pada! A stajat će jer moćan je Gospodin da ga podrži.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (52, 14, 5, 'Netko razlikuje dan od dana, nekomu je opet svaki dan jednak. Samo nek je svatko posve uvjeren u svoje mišljenje.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (52, 14, 6, 'Tko na dan misli, poradi Gospodina misli; i tko jede, poradi Gospodina jede: zahvaljuje Bogu. I tko ne jede, poradi Gospodina ne jede i - zahvaljuje Bogu.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (52, 14, 7, 'Jer nitko od nas sebi ne živi, nitko sebi ne umire.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (52, 14, 8, 'Doista, ako živimo, Gospodinu živimo, i ako umiremo, Gospodinu umiremo. Živimo li dakle ili umiremo - Gospodinovi smo.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (52, 14, 9, 'Ta Krist zato umrije i oživje da gospodar bude i mrtvima i živima.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (52, 14, 10, 'A ti, što sudiš brata svoga? Ili ti, što prezireš brata svoga? Ta svi ćemo stati pred sudište Božje.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (52, 14, 11, 'Jer pisano je: Života mi moga, govori Gospodin, prignut će se preda mnom svako koljeno i svaki će jezik priznati Boga.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (52, 14, 12, 'Svaki će dakle od nas za sebe Bogu dati račun.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (52, 14, 13, 'Dakle, ne sudimo više jedan drugoga, nego radije sudite o tome da ne valja postavljati bratu stupice ili spoticala.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (52, 14, 14, 'Znam i uvjeren sam u Gospodinu: ništa samo od sebe nije nečisto. Samo je onomu nečisto tko to smatra nečistim.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (52, 14, 15, 'Doista, ako je poradi hrane tvoj brat ražalošćen, već nisi na putu ljubavi. Ne upropašćuj tom svojom hranom onoga za koga je Krist umro!');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (52, 14, 16, 'Nemojte da se pogrđuje vaše dobro!');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (52, 14, 17, 'Ta kraljevstvo Božje nije jelo ili piće, nego pravednost, mir i radost u Duhu Svetome.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (52, 14, 18, 'Da, tko tako Kristu služi, mio je Bogu i cijene ga ljudi.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (52, 14, 19, 'Nastojmo stoga promicati mir i uzajamno izgrađivanje!');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (52, 14, 20, 'Ne razaraj djela Božjega poradi hrane! Sve je, istina, čisto, ali je zlo za onoga tko na sablazan jede.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (52, 14, 21, 'Dobro je ne jesti mesa i ne piti vina i ne uzimati ništa o što se tvoj brat spotiče.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (52, 14, 22, 'Ti imaš uvjerenje. Za sebe ga imaj pred Bogom. Blago onomu tko samoga sebe ne osuđuje u onom na što se odlučuje!');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (52, 14, 23, 'Jede li tko dvoumeći, osudio se jer ne radi iz uvjerenja. A sve što nije iz uvjerenja, grijeh je.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (52, 15, 1, 'Mi jaki treba da nosimo slabosti slabih, a ne da sebi ugađamo.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (52, 15, 2, 'Svaki od nas neka ugađa bližnjemu na dobro, na izgrađivanje.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (52, 15, 3, 'Ta ni Krist nije sebi ugađao, nego kao što je pisano: Poruge onih koji se rugaju tebi padoše na me.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (52, 15, 4, 'Uistinu, što je nekoć napisano, nama je za pouku napisano da po postojanosti i utjesi Pisama imamo nadu.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (52, 15, 5, 'A Bog postojanosti i utjehe dao vam da međusobno budete složni po Kristu Isusu');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (52, 15, 6, 'te jednodušno, iz jednoga grla, slavite Boga i Oca Gospodina našega Isusa Krista.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (52, 15, 7, 'Prigrljujte jedni druge kao što je Krist prigrlio vas na slavu Božju.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (52, 15, 8, 'Krist je, velim, postao poslužitelj obrezanika za istinu Božju da ispuni obećanja dana ocima,');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (52, 15, 9, 'a pogani da za milosrđe proslave Boga, kao što je pisano: Zato ću te slaviti među pucima i psalam pjevati tvome imenu.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (52, 15, 10, 'I još veli: Kličite, puci, s njegovim narodom.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (52, 15, 11, 'I još: Hvalite, svi puci, Gospodina, slavili ga svi narodi!');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (52, 15, 12, 'Izaija opet veli: Pojavit će se Jišajev izdanak, dignut da vlada narodima, u njemu je nada narodima.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (52, 15, 13, 'A Bog nade napunio vas svakom radošću i mirom u vjeri da izobilujete u nadi snagom Duha Svetoga.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (52, 15, 14, 'Ja sam, braćo moja, uvjeren: vi ste i sami puni čestitosti, ispunjeni svakim znanjem, sposobni jedni druge urazumljivati.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (52, 15, 15, 'Ipak vam djelomično smionije napisah da vas na poznato nekako podsjetim poradi milosti koja mi je dana od Boga -');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (52, 15, 16, 'da budem bogoslužnik Krista Isusa među poganima, svećenik evanđelja Božjega te prinos pogana postane ugodan, posvećen Duhom Svetim.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (52, 15, 17, 'Imam se dakle čime dičiti u Kristu Isusu s obzirom na ono što je Božje.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (52, 15, 18, '/');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (52, 15, 19, 'Jer ne bih se usudio govoriti o nečemu što Krist riječju i djelom, snagom znamenja i čudesa, snagom Duha nije po meni učinio da k poslušnosti privede pogane. Tako sam od Jeruzalema pa uokolo sve do Ilirika pronio evanđelje Kristovo,');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (52, 15, 20, 'i to tako da sam se trsio navješćivati evanđelje ne gdje se već spominjao Krist - da ne bih gradio na temeljima drugih -');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (52, 15, 21, 'nego, kako je pisano: Vidjet će ga oni kojima nije naviješten, shvatiti oni koji za nj nisu čuli.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (52, 15, 22, 'Time sam ponajčešće i bio spriječen doći k vama.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (52, 15, 23, 'Sad mi pak više nema mjesta u ovim krajevima, a živa mi je želja, ima već mnogo godina, doći k vama');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (52, 15, 24, 'kad pođem u Španjolsku. Nadam se doista da ću vas na proputovanju posjetiti i da ćete me onamo otpraviti pošto mi se najprije bar donekle ispuni želja biti s vama.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (52, 15, 25, 'Ali sad idem u Jeruzalem da poslužim svetima.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (52, 15, 26, 'Makedonija i Ahaja odlučiše očitovati neko zajedništvo prema siromašnim svetima u Jeruzalemu.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (52, 15, 27, 'Da, odlučiše, a i dužnici su im. Jer ako su pogani postali sudionicima njihovih duhovnih dobara, dužni su im u tjelesnima poslužiti.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (52, 15, 28, 'Pošto dakle to obavim - ovaj im plod zapečaćen uručim - uputit ću se u Španjolsku i usput k vama.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (52, 15, 29, 'A kada dođem k vama, doći ću, znam, s puninom blagoslova Kristova.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (52, 15, 30, 'Ali zaklinjem vas, braćo, Gospodinom Isusom Kristom i ljubavlju Duha: suborci mi budite u molitvama Bogu upravljenima za me,');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (52, 15, 31, 'da umaknem onim nevjernima u Judeji i da moja pomoć Jeruzalemu bude po volji svetima');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (52, 15, 32, 'te s Božjom voljom radosno dođem k vama i s vama zajedno odahnem.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (52, 15, 33, 'Bog mira sa svima vama! Amen.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (52, 16, 1, 'Preporučujem vam Febu, sestru našu, poslužiteljicu Crkve u Kenhreji:');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (52, 16, 2, 'primite je u Gospodinu kako dolikuje svetima i priskočite joj u pomoć u svemu što od vas ustreba jer je i ona bila zaštitnicom mnogima i meni samomu.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (52, 16, 3, 'Pozdravite Prisku i Akvilu, suradnike moje u Kristu Isusu.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (52, 16, 4, 'Oni su za moj život podmetnuli svoj vrat; zahvaljujem im ne samo ja nego i sve Crkve pogana.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (52, 16, 5, 'Pozdravite i Crkvu u njihovoj kući. Pozdravite ljubljenog mi Epeneta koji je prvina Azije za Krista.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (52, 16, 6, 'Pozdravite Mariju koja se mnogo trudila za vas.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (52, 16, 7, 'Pozdravite Andronika i Juniju, rođake i suuznike moje; oni su ugledni među apostolima i prije mene bili su u Kristu.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (52, 16, 8, 'Pozdravite Amplijata, ljubljenoga moga u Gospodinu.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (52, 16, 9, 'Pozdravite Urbana, suradnika moga u Kristu, i ljubljenog mi Staha.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (52, 16, 10, 'Pozdravite Apela, prokušanoga u Kristu. Pozdravite Aristobulove.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (52, 16, 11, 'Pozdravite Herodiona, rođaka moga. Pozdravite Narcisove koji su u Gospodinu.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (52, 16, 12, 'Pozdravite Trifenu i Trifozu koje se trude u Gospodinu. Pozdravite ljubljenu Persidu koja se mnogo trudila u Gospodinu.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (52, 16, 13, 'Pozdravite Rufa, izabranika u Gospodinu, i majku njegovu i moju.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (52, 16, 14, 'Pozdravite Asinkrita, Flegonta, Herma, Patrobu, Hermu i braću koja su s njima.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (52, 16, 15, 'Pozdravite Filologa i Juliju, Nereja i njegovu sestru, i Olimpu, i sve svete koji su s njima.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (52, 16, 16, 'Pozdravite jedni druge cjelovom svetim. Pozdravljaju vas sve Crkve Kristove.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (52, 16, 17, 'Zaklinjem vas, braćo, čuvajte se onih koji siju razdore i sablazni mimo nauk u kojem ste poučeni, i klonite ih se.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (52, 16, 18, 'Jer takvi ne služe Gospodinu našemu Kristu, nego svom trbuhu te lijepim i laskavim riječima zavode srca nedužnih.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (52, 16, 19, 'Doista, vaša je poslušnost doprla do sviju. Zbog vas se dakle radujem i htio bih da budete mudri za dobro, a bezazleni za zlo.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (52, 16, 20, 'Bog mira satrt će ubrzo Sotonu pod vašim nogama. Milost Gospodina Isusa s vama!');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (52, 16, 21, 'Pozdravlja vas Timotej, suradnik moj, i Lucije, Jason i Sosipater, rođaci moji.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (52, 16, 22, 'Pozdravljam vas u Gospodinu ja, Tercije, koji napisah ovu poslanicu.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (52, 16, 23, 'Pozdravlja vas Gaj, gostoprimac moj i cijele Crkve. Pozdravlja vas Erast, gradski blagajnik, i brat Kvart.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (52, 16, 24, '#');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (52, 16, 25, 'Onomu koji vas može učvrstiti - po mojem evanđelju i propovijedanju Isusa Krista, po objavljenju Otajstva prešućenog drevnim vremenima,');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (52, 16, 26, 'a sada očitovanog i po proročkim pismima odredbom vječnoga Boga svim narodima obznanjenog za poslušnost, vjeru -');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (52, 16, 27, 'jedinomu Mudromu, Bogu, po Isusu Kristu: Njemu slava u vijeke! Amen.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (53, 1, 1, 'Pavao, po Božjoj volji pozvan za apostola Krista Isusa, i brat Sosten');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (53, 1, 2, 'Crkvi Božjoj u Korintu - posvećenima u Kristu Isusu, pozvanicima, svetima, sa svima što na bilo kojemu mjestu prizivlju ime Isusa Krista, Gospodina našega, njihova i našega.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (53, 1, 3, 'Milost vam i mir od Boga, Oca našega, i Gospodina Isusa Krista!');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (53, 1, 4, 'Zahvaljujem Bogu svojemu svagda za vas zbog milosti Božje koja vam je dana u Kristu Isusu:');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (53, 1, 5, 'u njemu se obogatiste u svemu - u svakoj riječi i svakom spoznanju.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (53, 1, 6, 'Kako li se svjedočanstvo o Kristu utvrdilo u vama');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (53, 1, 7, 'te ne oskudijevate ni na jednom daru čekajući Objavljenje Gospodina našega Isusa Krista!');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (53, 1, 8, 'On će vas učiniti i postojanima do kraja, besprigovornima u Dan Gospodina našega Isusa Krista.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (53, 1, 9, 'Vjeran je Bog koji vas pozva u zajedništvo Sina svojega Isusa Krista, Gospodina našega.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (53, 1, 10, 'Zaklinjem vas, braćo, imenom Gospodina našega Isusa Krista: svi budite iste misli; neka ne bude među vama razdora, nego budite savršeno istog osjećanja i istog mišljenja.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (53, 1, 11, 'Jer Klojini mi, braćo moja, o vama rekoše da među vama ima svađa.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (53, 1, 12, 'Mislim to što svaki od vas govori: \"Ja sam Pavlov\", \"A ja Apolonov\", \"A ja Kefin\", \"A ja Kristov\".');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (53, 1, 13, 'Zar je Krist razdijeljen? Zar je Pavao raspet za vas? Ili ste u Pavlovo ime kršteni?');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (53, 1, 14, 'Hvala Bogu što ne krstih nikoga od vas, osim Krispa i Gaja;');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (53, 1, 15, 'da ne bi tko rekao da ste u moje ime kršteni.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (53, 1, 16, 'A da, krstih i Stefanin dom. Inače ne znam krstih li koga drugoga.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (53, 1, 17, 'Jer ne posla me Krist krstiti, nego navješćivati evanđelje, i to ne mudrošću besjede, da se ne obeskrijepi križ Kristov.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (53, 1, 18, 'Uistinu, besjeda o križu ludost je onima koji propadaju, a nama spašenicima sila je Božja.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (53, 1, 19, 'Ta pisano je: Upropastit ću mudrost mudrih, i odbacit ću umnost umnih.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (53, 1, 20, 'Gdje je mudrac? Gdje je književnik? Gdje je istraživač ovoga svijeta? Zar ne izludi Bog mudrost svijeta?');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (53, 1, 21, 'Doista, kad svijet u mudrosti Božjoj Boga ne upozna mudrošću, svidjelo se Bogu ludošću propovijedanja spasiti vjernike.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (53, 1, 22, 'Jer i Židovi znake ištu i Grci mudrost traže,');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (53, 1, 23, 'a mi propovijedamo Krista raspetoga: Židovima sablazan, poganima ludost,');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (53, 1, 24, 'pozvanima pak - i Židovima i Grcima - Krista, Božju snagu i Božju mudrost.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (53, 1, 25, 'Jer ludo Božje mudrije je od ljudi i slabo Božje jače je od ljudi.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (53, 1, 26, 'Ta gledajte, braćo, sebe, pozvane: nema mnogo mudrih po tijelu, nema mnogo snažnih, nema mnogo plemenitih.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (53, 1, 27, 'Nego lude svijeta izabra Bog da posrami mudre, i slabe svijeta izabra Bog da posrami jake;');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (53, 1, 28, 'i neplemenite svijeta i prezrene izabra Bog, i ono što nije, da uništi ono što jest,');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (53, 1, 29, 'da se nijedan smrtnik ne bi hvalio pred Bogom.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (53, 1, 30, 'Od njega je da vi jeste u Kristu Isusu, koji nama posta mudrost od Boga, i pravednost, i posvećenje, i otkupljenje,');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (53, 1, 31, 'da bude kako je pisano: Tko se hvali, u Gospodu neka se hvali.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (53, 2, 1, 'I ja kada dođoh k vama, braćo, ne dođoh s uzvišenom besjedom ili mudrošću navješćivati vam svjedočanstvo Božje');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (53, 2, 2, 'jer ne htjedoh među vama znati što drugo osim Isusa Krista, i to raspetoga.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (53, 2, 3, 'I ja priđoh k vama slab, u strahu i u veliku drhtanju.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (53, 2, 4, 'I besjeda moja i propovijedanje moje ne bijaše u uvjerljivim riječima mudrosti, nego u pokazivanju Duha i snage');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (53, 2, 5, 'da se vjera vaša ne temelji na mudrosti ljudskoj nego na snazi Božjoj.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (53, 2, 6, 'Mudrost doduše navješćujemo među zrelima, ali ne mudrost ovoga svijeta, ni knezova ovoga svijeta koji propadaju,');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (53, 2, 7, 'nego navješćujemo Mudrost Božju, u Otajstvu, sakrivenu; onu koju predodredi Bog prije vjekova za slavu našu,');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (53, 2, 8, 'a koje nijedan od knezova ovoga svijeta nije upoznao. Jer da su je upoznali, ne bi Gospodina slave razapeli.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (53, 2, 9, 'Nego, kako je pisano: Što oko ne vidje, i uho ne ču, i u srce čovječje ne uđe, to pripravi Bog onima koji ga ljube.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (53, 2, 10, 'A nama to Bog objavi po Duhu jer Duh sve proniče, i dubine Božje.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (53, 2, 11, 'Jer tko od ljudi zna što je u čovjeku osim duha čovječjega u njemu? Tako i što je u Bogu, nitko ne zna osim Duha Božjega.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (53, 2, 12, 'A mi, mi ne primismo duha svijeta, nego Duha koji je od Boga da znamo čime nas je obdario Bog.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (53, 2, 13, 'To i navješćujemo, ne naučenim riječima čovječje mudrosti, nego naukom Duha izlažući duhovno duhovnima.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (53, 2, 14, 'Naravan čovjek ne prima što je od Duha Božjega; njemu je to ludost i ne može spoznati jer po Duhu valja prosuđivati.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (53, 2, 15, 'Duhovan pak prosuđuje sve, a njega nitko ne prosuđuje.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (53, 2, 16, 'Jer tko spozna misao Gospodnju, tko da ga pouči? A mi imamo misao Kristovu.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (53, 3, 1, 'I ja, braćo, nisam mogao govoriti vama kao duhovnima, nego kao tjelesnima, kao nejačadi u Kristu.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (53, 3, 2, 'Mlijekom vas napojih, ne jelom: još ne mogoste, a ni sada još ne možete');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (53, 3, 3, 'jer još ste tjelesni. Doista, dok je među vama zavist i prepiranje, zar niste tjelesni, zar po ljudsku ne postupate?');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (53, 3, 4, 'Jer kad jedan govori: \"Ja sam Pavlov\", a drugi: \"Ja Apolonov\", niste li odveć ljudi?');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (53, 3, 5, 'Ta što je Apolon? Što je Pavao? Poslužitelji po kojima povjerovaste - kako već komu Gospodin dade.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (53, 3, 6, 'Ja zasadih, Apolon zali, ali Bog dade rasti.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (53, 3, 7, 'Tako niti je što onaj tko sadi ni onaj tko zalijeva, nego Bog koji daje rasti.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (53, 3, 8, 'Tko sadi i tko zalijeva, jedno su; a svaki će po svome trudu primiti plaću.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (53, 3, 9, 'Jer Božji smo suradnici: Božja ste njiva, Božja građevina.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (53, 3, 10, 'Po milosti Božjoj koja mi je dana ja kao mudri graditelj postavih temelj, a drugi naziđuje; ali svaki neka pazi kako naziđuje.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (53, 3, 11, 'Jer nitko ne može postaviti drugoga temelja osim onoga koji je postavljen, a taj je Isus Krist.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (53, 3, 12, 'Naziđuje li tko na ovom temelju zlatom, srebrom, dragim kamenjem, drvom, sijenom, slamom -');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (53, 3, 13, 'svačije će djelo izići na svjetlo. Onaj će Dan pokazati jer će se u ognju očitovati. I kakvo je čije djelo, oganj će iskušati.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (53, 3, 14, 'Ostane li djelo, primit će plaću onaj tko ga je nazidao.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (53, 3, 15, 'Izgori li čije djelo, taj će štetovati; ipak, on će se sam spasiti, ali kao kroz oganj.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (53, 3, 16, 'Ne znate li? Hram ste Božji i Duh Božji prebiva u vama.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (53, 3, 17, 'Ako tko upropašćuje hram Božji, upropastit će njega Bog. Jer hram je Božji svet, a to ste vi.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (53, 3, 18, 'Nitko neka se ne vara. Ako tko misli da je mudar među vama na ovome svijetu, neka bude lud da bude mudar.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (53, 3, 19, 'Jer mudrost ovoga svijeta ludost je pred Bogom. Ta pisano je: On hvata mudre u njihovu lukavstvu.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (53, 3, 20, 'I opet: Gospodin poznaje namisli mudrih, one su isprazne.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (53, 3, 21, 'Zato neka se nitko ne hvasta ljudima jer sve je vaše.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (53, 3, 22, 'Bio Pavao, ili Apolon, ili Kefa, bio svijet, ili život, ili smrt, ili sadašnje, ili buduće: sve je vaše,');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (53, 3, 23, 'vi Kristovi, a Krist Božji.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (53, 4, 1, 'Tako, neka nas svatko smatra službenicima Kristovim i upraviteljima otajstava Božjih.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (53, 4, 2, 'A od upravitelja iziskuje se napokon da budu vjerni.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (53, 4, 3, 'Meni pak nije nimalo do toga da me sudite vi ili bilo koji ljudski sud; a ni ja sam sebe ne sudim.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (53, 4, 4, 'Doista, ničega sebi nisam svjestan, no time nisam opravdan: moj je sudac Gospodin.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (53, 4, 5, 'Zato ne sudite ništa prije vremena dok ne dođe Gospodin koji će iznijeti na vidjelo što je sakriveno u tami i razotkriti nakane srdaca. I tada će svatko primiti pohvalu od Boga.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (53, 4, 6, 'Time, braćo, smjerah na sebe i Apolona radi vas: da na nama naučite onu \"Ne preko onoga što je pisano\" te se ne nadimate jednim protiv drugoga.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (53, 4, 7, 'Ta tko tebi daje prednost? Što imaš da nisi primio? Ako si primio, što se hvastaš kao da nisi primio?');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (53, 4, 8, 'Već ste siti, već se obogatiste, bez nas se zakraljiste! Kamo sreće da se zakraljiste da i mi s vama zajedno kraljujemo!');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (53, 4, 9, 'Jer Bog je, čini mi se, nas apostole prikazao posljednje, kao na smrt osuđene, jer postali smo prizor svijetu, i anđelima, i ljudima -');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (53, 4, 10, 'mi ludi poradi Krista, vi mudri u Kristu; mi slabi, vi jaki; vi čašćeni, mi prezreni;');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (53, 4, 11, 'sve do ovoga časa i gladujemo, i žeđamo, i goli smo, i pljuskaju nas, i beskućnici smo,');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (53, 4, 12, 'i patimo se radeći svojim rukama. Proklinjani blagoslivljamo, proganjani ustrajavamo,');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (53, 4, 13, 'pogrđivani tješimo. Kao smeće svijeta postasmo, svačiji izmet sve do sada.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (53, 4, 14, 'Ne pišem ovoga da vas postidim, nego da vas kao ljubljenu svoju djecu urazumim.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (53, 4, 15, 'Jer da imate u Kristu i deset tisuća učitelja, ipak ne biste imali više otaca. Ta u Kristu Isusu po evanđelju ja vas rodih!');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (53, 4, 16, 'Zaklinjem vas, dakle: nasljedovatelji moji budite.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (53, 4, 17, 'Zato upravo poslah k vama Timoteja, koji mi je dijete ljubljeno i vjerno u Gospodinu, da vas podsjeti na naputke moje, u Kristu, kako posvuda u svakoj crkvi učim.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (53, 4, 18, 'Neki se uzniješe kao da ja neću doći k vama.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (53, 4, 19, 'Ipak, eto me ubrzo k vama, ako Gospodin htjedne, i rasudit ću ne riječi onih nadutih, nego krepost.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (53, 4, 20, 'Ta nije u riječi kraljevstvo Božje, nego u kreposti.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (53, 4, 21, 'Što želite? Da k vama dođem sa šibom ili s ljubavlju i duhom blagosti?');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (53, 5, 1, 'Općenito se čuje o bludnosti među vama, i to takvoj bludnosti kakve nema ni među poganima: da netko ima očevu ženu.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (53, 5, 2, 'I vi mi se uznijeli, mjesto da žalujete pa da se iskorijeni iz vaše sredine onaj koji takvo djelo počini.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (53, 5, 3, 'A ja, i nenazočan tijelom, ali nazočan duhom, već sam presudio kao nazočan onoga koji je takvo što počinio.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (53, 5, 4, 'Pošto se u ime Gospodina našega Isusa Krista okupite vi i moj duh, snagom Gospodina našega Isusa,');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (53, 5, 5, 'neka se takav preda Sotoni na propast tijela da bi se spasio duh u Dan Gospodina Isusa.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (53, 5, 6, 'Ne valja vam hvastanje! Zar ne znate da malo kvasca sve tijesto ukvasa?');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (53, 5, 7, 'Očistite stari kvasac da budete novo tijesto, kao što i jeste beskvasni jer već je žrtvovana Pasha naša, Krist.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (53, 5, 8, 'Zato svetkujmo, ne sa starim kvascem ni s kvascem zloće i pakosti, nego s beskvasnim kruhovima čistoće i istine.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (53, 5, 9, 'Napisah vam u poslanici da se ne miješate s bludnicima -');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (53, 5, 10, 'ne općenito s bludnicima ovoga svijeta, ili lakomcima, ili razbojnicima, ili idolopoklonicima jer biste inače morali iz svijeta izići.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (53, 5, 11, 'Napisah vam zapravo da se ne miješate s nazovibratom koji bi bio bludnik, ili lakomac, ili idolopoklonik, ili pogrđivač, ili pijanica, ili razbojnik. S takvim ni za stol!');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (53, 5, 12, 'Što spada na me suditi one vani? Ne sudite li vi one koji su unutra?');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (53, 5, 13, 'A one vani sudit će Bog. Iskorijenite opakoga iz svoje sredine.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (53, 6, 1, 'Tko bi se od vas u sporu s drugim usudio parničiti se pred nepravednima, a ne pred svetima?');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (53, 6, 2, 'Ili zar ne znate da će sveti suditi svijet? Pa ako ćete vi suditi svijet, zar niste vrijedni suditi sitnice?');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (53, 6, 3, 'Ne znate li da ćemo suditi anđele, kamo li ne ono svagdanje?');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (53, 6, 4, 'A vi, kad imate sporove o svagdanjem, sucima postavljate one do kojih Crkva ništa ne drži!');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (53, 6, 5, 'Vama na sramotu govorim. Tako? Zar nema među vama ni jednoga mudra koji bi mogao rasuditi među braćom?');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (53, 6, 6, 'Nego brat se s bratom parniči, i to pred nevjernicima?');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (53, 6, 7, 'Zapravo, već vam je to nedostatak što se parničite među sobom. Zašto radije ne trpite nepravdu? Zašto se radije ne pustite oplijeniti?');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (53, 6, 8, 'Nego vi činite nepravdu i plijenite, i to braću.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (53, 6, 9, 'Ili zar ne znate da nepravednici neće baštiniti kraljevstva Božjega? Ne varajte se! Ni bludnici, ni idolopoklonici, ni preljubnici, ni mekoputnici, ni muškoložnici,');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (53, 6, 10, 'ni kradljivci, ni lakomci, ni pijanice, ni psovači, ni razbojnici neće baštiniti kraljevstva Božjega.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (53, 6, 11, 'To evo, bijahu neki od vas, ali oprali ste se, ali posvetili ste se, ali opravdali ste se u imenu Gospodina našega Isusa Krista i u Duhu Boga našega.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (53, 6, 12, '\"Sve mi je dopušteno!\" Ali - sve ne koristi. \"Sve mi je dopušteno!\" Ali - neću da mnome išta vlada.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (53, 6, 13, '\"Jela trbuhu, a trbuh jelima; Bog će i jedno i drugo uništiti.\" Ali ne tijelo bludnosti, nego Gospodinu, i Gospodin tijelu!');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (53, 6, 14, 'Ta Bog koji je Gospodina uskrisio i nas će uskrisiti snagom njegovom.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (53, 6, 15, 'Ne znate li da su tijela vaša udovi Kristovi? Hoću li dakle uzeti udove Kristove i učiniti ih udovima bludničinim? Nipošto!');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (53, 6, 16, 'Ili zar ne znate: tko uz bludnicu prione, jedno je tijelo? Jer veli se: Bit će njih dvoje jedno tijelo.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (53, 6, 17, 'A tko prione uz Gospodina, jedan je duh.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (53, 6, 18, 'Bježite od bludnosti! Svaki grijeh koji učini čovjek, izvan tijela je, a bludnik griješi protiv svojega tijela.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (53, 6, 19, 'Ili zar ne znate? Tijelo vaše hram je Duha Svetoga koji je u vama, koga imate od Boga, te niste svoji.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (53, 6, 20, 'Jer kupljeni ste otkupninom. Proslavite dakle Boga u tijelu svojem!');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (53, 7, 1, 'Sada o onome što ste mi pisali. Dobro je čovjeku ne dotaći ženu.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (53, 7, 2, 'Ipak, zbog bludnosti, neka svaki ima svoju ženu i svaka neka ima svoga muža.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (53, 7, 3, 'Muž neka vrši dužnost prema ženi, a tako i žena prema mužu.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (53, 7, 4, 'Žena nije gospodar svoga tijela, nego muž, a tako ni muž nije gospodar svoga tijela, nego žena.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (53, 7, 5, 'Ne uskraćujte se jedno drugome, osim po dogovoru, povremeno, da se posvetite molitvi pa se opet združite da vas Sotona ne bi napastovao zbog vaše neizdržljivosti.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (53, 7, 6, 'Ali to velim kao dopuštenje, ne kao zapovijed.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (53, 7, 7, 'A htio bih da svi ljudi budu kao i ja; ali svatko ima svoj dar od Boga, ovaj ovako, onaj onako.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (53, 7, 8, 'Neoženjenima pak i udovicama velim: dobro im je ako ostanu kao i ja.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (53, 7, 9, 'Ako li se ne mogu uzdržati, neka se žene, udaju. Jer bolje je ženiti se negoli izgarati.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (53, 7, 10, 'A oženjenima zapovijedam, ne ja, nego Gospodin: žena neka se od muža ne rastavlja -');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (53, 7, 11, 'ako se ipak rastavi, neka ostane neudana ili neka se s mužem pomiri - i muž neka ne otpušta žene.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (53, 7, 12, 'Ostalima pak velim - ja, ne Gospodin: ima li koji brat ženu nevjernicu i ona privoli stanovati s njime, neka je ne otpušta.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (53, 7, 13, 'I žena koja ima muža nevjernika te on privoli stanovati s njome, neka ne otpušta muža.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (53, 7, 14, 'Ta muž nevjernik posvećen je ženom i žena nevjernica posvećena je bratom. Inače bi djeca vaša bila nečista, a ovako - sveta su.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (53, 7, 15, 'Ako li se nevjernik hoće rastaviti, neka se rastavi; brat ili sestra u takvim prilikama nisu vezani: ta na mir nas je pozvao Bog.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (53, 7, 16, 'Jer što znaš, ženo, hoćeš li spasiti muža? Ili što znaš, mužu, hoćeš li spasiti ženu?');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (53, 7, 17, 'U drugome svatko neka živi kako mu je Gospodin dodijelio, kako ga je Bog pozvao. Tako određujem po svim crkvama.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (53, 7, 18, 'Je li tko pozvan kao obrezan, neka ne prepravlja obrezanja. Ako je pozvan kao neobrezan, neka se ne obrezuje.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (53, 7, 19, 'Obrezanje nije ništa i neobrezanje nije ništa, nego - držanje Božjih zapovijedi.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (53, 7, 20, 'Svatko neka ostane u onom zvanju u koje je pozvan.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (53, 7, 21, 'Jesi li pozvan kao rob? Ne brini! Nego, ako i možeš postati slobodan, radije se okoristi.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (53, 7, 22, 'Jer tko je u Gospodinu pozvan kao rob, slobodnjak je Gospodnji. Tako i tko je pozvan kao slobodnjak, rob je Kristov.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (53, 7, 23, 'Otkupninom ste kupljeni: ne budite robovi ljudima.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (53, 7, 24, 'Svatko u čemu je pozvan, braćo, u tome neka i ostane pred Bogom.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (53, 7, 25, 'O djevicama nemam zapovijedi, nego dajem savjet kao čovjek po milosrđu Gospodnjem vrijedan povjerenja.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (53, 7, 26, 'Smatram dakle: dobro je to zbog sadašnje nevolje, dobro je čovjeku tako biti.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (53, 7, 27, 'Jesi li vezan za ženu? Ne traži rastave. Jesi li slobodan od žene? Ne traži žene.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (53, 7, 28, 'Ali ako se i oženiš, nisi sagriješio; i djevica ako se uda, nije sagriješila. Ali takvi će imati tjelesnu nevolju, a ja bih vas rado poštedio.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (53, 7, 29, 'Ovo hoću reći, braćo: Vrijeme je kratko. Odsele i koji imaju žene, neka budu kao da ih nemaju;');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (53, 7, 30, 'i koji plaču, kao da ne plaču; i koji se vesele, kao da se ne vesele; i koji kupuju, kao da ne posjeduju;');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (53, 7, 31, 'i koji uživaju ovaj svijet, kao da ga ne uživaju, jer - prolazi obličje ovoga svijeta.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (53, 7, 32, 'A rado bih da budete bezbrižni. Neoženjen se brine za Gospodnje, kako da ugodi Gospodinu.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (53, 7, 33, 'A oženjen se brine za svjetovno, kako da ugodi ženi,');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (53, 7, 34, 'pa je razdijeljen. I žena neudana i djevica brine se za Gospodnje, da bude sveta i tijelom i duhom; a udana se brine za svjetovno, kako da ugodi mužu.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (53, 7, 35, 'Ovo pak govorim vama na korist, ne da vam postavim zamku, nego da primjerno i nesmetano budete privrženi Gospodinu.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (53, 7, 36, 'Misli li tko da je nepriličan prema svojoj djevici kad je preživotan i s njome mora biti, neka čini što je nakanio, ne griješi: neka se uzmu.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (53, 7, 37, 'Tko je pak nepokolebljivo stalan u srcu te nema potrebe, a u vlasti mu je volja pa to odluči u svom srcu - čuvati svoju djevicu - dobro čini.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (53, 7, 38, 'Tako, tko se oženi svojom djevicom, dobro čini, a tko se ne oženi, bolje čini.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (53, 7, 39, 'Žena je vezana dokle živi muž njezin. Umre li muž, slobodna je: neka se uda za koga hoće, samo u Gospodinu.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (53, 7, 40, 'Bit će ipak blaženija ostane li onako, po mojem savjetu. A mislim da i ja imam Duha Božjega.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (53, 8, 1, 'U pogledu mesa žrtvovana idolima, znamo, svi posjedujemo znanje. Ali znanje nadima, a ljubav izgrađuje.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (53, 8, 2, 'Ako tko misli da što zna, još ne zna kako treba znati.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (53, 8, 3, 'A ljubi li tko Boga, Bog ga poznaje.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (53, 8, 4, 'Dakle, u pogledu blagovanja mesa žrtvovana idolima, znamo: nema idola na svijetu i nema Boga do Jednoga.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (53, 8, 5, 'Jer sve kad bi i bilo nazovibogova ili na nebu ili na zemlji - kao što ima mnogo \"bogova\" i mnogo \"gospodara\"! -');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (53, 8, 6, 'nama je jedan Bog, Otac, od koga je sve, a mi za njega; i jedan Gospodin, Isus Krist, po kome je sve, i mi po njemu.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (53, 8, 7, 'Ali nemaju svi toga znanja. Neki, navikli na idole, još jedu meso kao idolima žrtvovano i njihova se savjest kalja jer je nejaka.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (53, 8, 8, 'A k Bogu nas ne privodi jelo. Niti što gubimo ako ne jedemo; niti što dobivamo ako jedemo.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (53, 8, 9, 'A pazite da ne bi možda ta vaša sloboda bila spoticaj nejakima.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (53, 8, 10, 'Jer vidi li tko tebe koji imaš znanje za stolom u hramu idolskomu, neće li se njegova savjest, jer je nejaka, \"izgraditi\" da jede žrtvovano idolima?');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (53, 8, 11, 'I s tvoga znanja propada nejaki, brat za kojega je Krist umro.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (53, 8, 12, 'Tako griješeći protiv braće i ranjavajući njihovu nejaku savjest, protiv Krista griješite.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (53, 8, 13, 'Zato ako jelo sablažnjava brata moga, ne, neću jesti mesa dovijeka da brata svoga ne sablaznim.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (53, 9, 1, 'Nisam li ja slobodan? Nisam li apostol? Nisam li vidio Isusa, Gospodina našega? Niste li vi djelo moje u Gospodinu?');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (53, 9, 2, 'Ako drugima nisam apostol, vama svakako jesam. Ta vi ste pečat mojega apostolstva u Gospodinu.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (53, 9, 3, 'Moj odgovor mojim tužiteljima jest ovo:');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (53, 9, 4, 'Zar nemamo prava jesti i piti?');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (53, 9, 5, 'Zar nemamo prava ženu vjernicu voditi sa sobom kao i drugi apostoli i braća Gospodnja i Kefa?');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (53, 9, 6, 'Ili samo ja i Barnaba nemamo prava ne raditi?');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (53, 9, 7, 'Tko ikada vojuje o svojem trošku? Tko sadi vinograd pa roda njegova ne jede? Ili tko pase stado pa od mlijeka stada ne jede?');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (53, 9, 8, 'Zar to govorim po ljudsku? Ne kaže li to i Zakon?');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (53, 9, 9, 'Jer u Mojsijevu zakonu piše: Ne zavezuj usta volu koji vrši! Zar je Bogu do volova?');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (53, 9, 10, 'Ne govori li on baš radi nas? Doista, radi nas je napisano, jer tko ore, u nadi treba da ore; i tko vrši, u nadi da će dobiti dio.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (53, 9, 11, 'Ako smo mi vama sijali dobra duhovna, veliko li je nešto ako vam požanjemo tjelesna?');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (53, 9, 12, 'Ako drugi sudjeluju u vašim dobrima, zašto ne bismo mi mogli još većma. Ali nismo se poslužili tim pravom, nego sve teglimo da ne bismo postavili kakvu zapreku evanđelju Kristovu?');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (53, 9, 13, 'Ne znate li: koji obavljaju svetinje, od svetišta se hrane; i koji žrtveniku služe, sa žrtvenikom dijele?');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (53, 9, 14, 'Tako je i Gospodin onima koji evanđelje navješćuju odredio od evanđelja živjeti.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (53, 9, 15, 'No ja se ničim od toga nisam poslužio. A i ne napisah toga da bi se tako postupilo prema meni. Radije umrijeti, nego... Te mi slave nitko neće oduzeti!');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (53, 9, 16, 'Jer što navješćujem evanđelje, nije mi na hvalu, ta dužnost mi je. Doista, jao meni ako evanđelja ne navješćujem.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (53, 9, 17, 'Jer ako to činim iz vlastite pobude, ide me plaća; ako li ne iz vlastite pobude - služba je to koja mi je povjerena.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (53, 9, 18, 'Koja mi je dakle plaća? Da propovijedajući pružam evanđelje besplatno ne služeći se svojim pravom u evanđelju.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (53, 9, 19, 'Jer premda slobodan od sviju, sam sebe svima učinih slugom da ih što više steknem.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (53, 9, 20, 'Bijah Židovima Židov da Židove steknem; onima pod Zakonom, kao da sam pod Zakonom - premda ja nisam pod Zakonom - da one pod Zakonom steknem;');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (53, 9, 21, 'onima bez Zakona, kao da sam bez zakona - premda nisam bez Božjega zakona, nego u Kristovu zakonu - da steknem one bez Zakona;');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (53, 9, 22, 'bijah nejakima nejak da nejake steknem. Svima bijah sve da pošto-poto neke spasim.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (53, 9, 23, 'A sve činim poradi evanđelja da bih i ja bio suzajedničar u njemu.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (53, 9, 24, 'Ne znate li: trkači u trkalištu svi doduše trče, ali jedan prima nagradu? Tako trčite da dobijete.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (53, 9, 25, 'Svaki natjecatelj sve moguće izdržava; oni da dobiju raspadljiv vijenac, mi neraspadljiv.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (53, 9, 26, 'Ja dakle tako trčim - ne kao besciljno, tako udaram šakom - ne kao da mlatim vjetar,');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (53, 9, 27, 'nego krotim svoje tijelo i zarobljavam da sam ne budem isključen pošto sam drugima propovijedao.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (53, 10, 1, 'Jer ne bih, braćo, htio da budete u neznanju: oci naši svi bijahu pod oblakom, i svi prijeđoše kroz more,');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (53, 10, 2, 'i svi su se na Mojsija krstili u oblaku i u moru,');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (53, 10, 3, 'i svi su isto duhovno jelo jeli,');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (53, 10, 4, 'i svi su isto duhovno piće pili. A pili su iz duhovne stijene koja ih je pratila; stijena bijaše Krist.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (53, 10, 5, 'Ali većina njih nije bila po volji Bogu: ta poubijani su po pustinji.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (53, 10, 6, 'To bijahu pralikovi naši: da ne žudimo za zlima kao što su žudjeli oni.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (53, 10, 7, 'I ne budite idolopoklonici kao neki od njih, kako je pisano: Posjeda narod da jede i pije pa ustadoše da igraju.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (53, 10, 8, 'I ne podajimo se bludu kao što se neki od njih bludu podaše i padoše u jednom danu dvadeset i tri tisuće.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (53, 10, 9, 'I ne iskušavajmo Gospodina kao što su ga neki od njih iskušavali te od zmija izginuli.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (53, 10, 10, 'I ne mrmljajte kao što neki od njih mrmljahu te izgiboše od Zatornika.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (53, 10, 11, 'Sve se to, kao pralik, događalo njima, a napisano je za upozorenje nama, koje su zapala posljednja vremena.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (53, 10, 12, 'Tko dakle misli da stoji, neka pazi da ne padne.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (53, 10, 13, 'Nije vas zahvatila druga kušnja osim ljudske. Ta vjeran je Bog: neće pustiti da budete kušani preko svojih sila, nego će s kušnjom dati i ishod da možete izdržati.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (53, 10, 14, 'Zato, ljubljeni moji, bježite od idolopoklonstva.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (53, 10, 15, 'Kao razumnima velim: sudite sami što govorim.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (53, 10, 16, 'Čaša blagoslovna koju blagoslivljamo nije li zajedništvo krvi Kristove? Kruh koji lomimo nije li zajedništvo tijela Kristova?');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (53, 10, 17, 'Budući da je jedan kruh, jedno smo tijelo mi mnogi; ta svi smo dionici jednoga kruha.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (53, 10, 18, 'Gledajte Izraela po tijelu! Koji blaguju žrtve nisu li zajedničari žrtvenika?');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (53, 10, 19, 'Što dakle hoću reći? Idolska žrtva da je nešto? Ili idol da je nešto?');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (53, 10, 20, 'Naprotiv, da pogani vrazima žrtvuju, ne Bogu. A neću da budete zajedničari vražji.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (53, 10, 21, 'Ne možete piti čašu Gospodnju i čašu vražju. Ne možete biti sudionici stola Gospodnjega i stola vražjega.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (53, 10, 22, 'Ili da izazivamo ljubomor Gospodnji? Zar smo jači od njega?');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (53, 10, 23, '\"Sve je slobodno!\" Ali - sve ne koristi. \"Sve je dopušteno!\" Ali - sve ne saziđuje.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (53, 10, 24, 'Nitko neka ne traži svoje, nego dobro drugoga.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (53, 10, 25, 'Sve što se prodaje na tržnici, jedite ništa ne ispitujući poradi savjesti.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (53, 10, 26, 'Ta Gospodnja je zemlja i sve na njoj!');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (53, 10, 27, 'Pozove li vas koji nevjernik i želite se odazvati, jedite što vam se ponudi ništa ne ispitujući poradi savjesti.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (53, 10, 28, 'Ako vam tko reče: \"To je žrtvovano\", ne jedite poradi onoga koji vas je upozorio, i savjesti.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (53, 10, 29, 'Savjesti mislim, ne svoje, nego onoga drugoga. Ta zašto da moju slobodu druga savjest sudi?');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (53, 10, 30, 'Ako sa zahvalom sudjelujem, zašto da me grde zbog onoga za što zahvaljujem?');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (53, 10, 31, 'Dakle, ili jeli, ili pili, ili drugo što činili, sve na slavu Božju činite.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (53, 10, 32, 'Ne budite na sablazan ni Židovima, ni Grcima, ni Crkvi Božjoj,');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (53, 10, 33, 'kao što i ja svima u svemu ugađam ne tražeći svoju korist, nego što koristi mnogima na spasenje.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (53, 11, 1, 'Nasljedovatelji moji budite, kao što sam i ja Kristov.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (53, 11, 2, 'Hvalim vas što me se u svemu sjećate i držite se predaja kako vam predadoh.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (53, 11, 3, 'Ali htio bih da znate: svakomu je mužu glava Krist, glava ženi muž, a glava Kristu Bog.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (53, 11, 4, 'Svaki muž koji se moli ili prorokuje pokrivene glave sramoti glavu svoju.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (53, 11, 5, 'Svaka pak žena koja se moli ili prorokuje gologlava sramoti glavu svoju. Ta to je isto kao da je obrijana.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (53, 11, 6, 'Jer ako se žena ne pokriva, neka se šiša; ako li je pak ružno ženi šišati se ili brijati, neka se pokrije.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (53, 11, 7, 'A muž ne mora pokrivati glave, ta slika je i slava Božja; a žena je slava muževa.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (53, 11, 8, 'Jer nije muž od žene, nego žena od muža.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (53, 11, 9, 'I nije stvoren muž radi žene, nego žena radi muža.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (53, 11, 10, 'Zato žena treba da ima \"vlast\" na glavi poradi anđela.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (53, 11, 11, 'Ipak, u Gospodinu - ni žena bez muža, ni muž bez žene!');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (53, 11, 12, 'Jer kao što je žena od muža, tako je i muž po ženi; a sve je od Boga.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (53, 11, 13, 'Sami sudite dolikuje li da se žena gologlava Bogu moli?');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (53, 11, 14, 'Ne uči li nas i sama narav da je mužu sramota ako goji kosu?');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (53, 11, 15, 'A ženi je dika ako je goji jer kosa joj je dana mjesto prijevjesa.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (53, 11, 16, 'Ako je kome do prepirke, takva običaja mi nemamo, a ni Crkve Božje.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (53, 11, 17, 'Kad već dajem ta upozorenja, ne mogu pohvaliti što se ne sastajete na bolje, nego na gore.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (53, 11, 18, 'Ponajprije čujem, djelomično i vjerujem: kad se okupite na Sastanak, da su među vama razdori.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (53, 11, 19, 'Treba doista da i podjela bude među vama da se očituju prokušani među vama.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (53, 11, 20, 'Kad se dakle tako zajedno sastajete, to nije blagovanje Gospodnje večere:');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (53, 11, 21, 'ta svatko se pri blagovanju prihvati svoje večere te jedan gladuje, a drugi se opija.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (53, 11, 22, 'Zar nemate kuća da jedete i pijete? Ili Crkvu Božju prezirete i postiđujete one koji nemaju? Što da vam kažem? Da vas pohvalim? U tom vas ne hvalim.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (53, 11, 23, 'Doista, ja od Gospodina primih što vama predadoh: Gospodin Isus one noći kad bijaše predan uze kruh,');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (53, 11, 24, 'zahvalivši razlomi i reče: \"Ovo je tijelo moje - za vas. Ovo činite meni na spomen.\"');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (53, 11, 25, 'Tako i čašu po večeri govoreći: \"Ova čaša novi je Savez u mojoj krvi. Ovo činite kad god pijete, meni na spomen.\"');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (53, 11, 26, 'Doista, kad god jedete ovaj kruh i pijete čašu, smrt Gospodnju navješćujete dok on ne dođe.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (53, 11, 27, 'Stoga, tko god jede kruh ili pije čašu Gospodnju nedostojno, bit će krivac tijela i krvi Gospodnje.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (53, 11, 28, 'Neka se dakle svatko ispita pa tada od kruha jede i iz čaše pije.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (53, 11, 29, 'Jer tko jede i pije, sud sebi jede i pije ako ne razlikuje Tijela.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (53, 11, 30, 'Zato su među vama mnogi nejaki i nemoćni, i spavaju mnogi.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (53, 11, 31, 'Jer kad bismo sami sebe sudili, ne bismo bili suđeni.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (53, 11, 32, 'A kad nas sudi Gospodin, odgaja nas da ne budemo sa svijetom osuđeni.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (53, 11, 33, 'Zato, braćo moja, kad se sastajete na blagovanje, pričekajte jedni druge.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (53, 11, 34, 'Je li tko gladan, kod kuće neka jede da se ne sastajete na osudu. Drugo ću urediti kada dođem.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (53, 12, 1, 'O darima Duha ne bih, braćo, htio da budete u neznanju.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (53, 12, 2, 'Znate kako ste se dok bijaste pogani, zavedeni, zanosili nijemim idolima.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (53, 12, 3, 'Zato vam obznanjujem: nitko tko u Duhu Božjem govori ne kaže: \"Prokletstvo Isusu\". I nitko ne može reći: \"Gospodin Isus\" osim u Duhu Svetom.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (53, 12, 4, 'Različiti su dari, a isti Duh;');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (53, 12, 5, 'i različite službe, a isti Gospodin;');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (53, 12, 6, 'i različita djelovanja, a isti Bog koji čini sve u svima.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (53, 12, 7, 'A svakomu se daje očitovanje Duha na korist.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (53, 12, 8, 'Doista, jednomu se po Duhu daje riječ mudrosti, drugomu riječ spoznanja po tom istom Duhu;');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (53, 12, 9, 'drugomu vjera u tom istom Duhu, drugomu dari liječenja u tom jednom Duhu;');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (53, 12, 10, 'drugomu čudotvorstva, drugomu prorokovanje, drugomu razlučivanje duhova, drugomu različiti jezici, drugomu tumačenje jezika.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (53, 12, 11, 'A sve to djeluje jedan te isti Duh dijeleći svakomu napose kako hoće.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (53, 12, 12, 'Doista, kao što je tijelo jedno te ima mnogo udova, a svi udovi tijela iako mnogi, jedno su tijelo - tako i Krist.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (53, 12, 13, 'Ta u jednom Duhu svi smo u jedno tijelo kršteni, bilo Židovi, bilo Grci, bilo robovi, bilo slobodni. I svi smo jednim Duhom napojeni.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (53, 12, 14, 'Ta ni tijelo nije jedan ud, nego mnogi.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (53, 12, 15, 'Rekne li noga: \"Nisam ruka, nisam od tijela\", zar zbog toga nije od tijela?');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (53, 12, 16, 'I rekne li uho: \"Nisam oko, nisam od tijela\", zar zbog toga nije od tijela?');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (53, 12, 17, 'Kad bi sve tijelo bilo oko, gdje bi bio sluh? Kad bi sve bilo sluh, gdje bi bio njuh?');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (53, 12, 18, 'A ovako, Bog je rasporedio udove, svaki od njih u tijelu, kako je htio.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (53, 12, 19, 'Kad bi svi bili jedan ud, gdje bio bilo tijelo?');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (53, 12, 20, 'A ovako, mnogi udovi - jedno tijelo!');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (53, 12, 21, 'Ne može oko reći ruci: \"Ne trebam te\", ili pak glava nogama: \"Ne trebam vas.\"');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (53, 12, 22, 'Naprotiv, mnogo su potrebniji udovi tijela koji izgledaju slabiji.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (53, 12, 23, 'A udove koje smatramo nečasnijima, okružujemo većom čašću. I s nepristojnima se pristojnije postupa,');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (53, 12, 24, 'a pristojni toga ne trebaju. Nego, Bog je tako sastavio tijelo da je posljednjem udu dao izobilniju čast');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (53, 12, 25, 'da ne bude razdora u tijelu, nego da se udovi jednako brinu jedni za druge.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (53, 12, 26, 'I ako trpi jedan ud, trpe zajedno svi udovi; ako li se slavi jedan ud, raduju se zajedno svi udovi.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (53, 12, 27, 'A vi ste tijelo Kristovo i, pojedinačno, udovi.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (53, 12, 28, 'I neke postavi Bog u Crkvi: prvo za apostole, drugo za proroke, treće za učitelje; onda čudesa, onda dari liječenja; zbrinjavanja, upravljanja, razni jezici.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (53, 12, 29, 'Zar su svi apostoli? Zar svi proroci? Zar svi učitelji? Zar svi čudotvorci?');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (53, 12, 30, 'Zar svi imaju dare liječenja? Zar svi govore jezike? Zar svi tumače?');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (53, 12, 31, 'Čeznite za višim darima! A evo vam puta najizvrsnijega!');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (53, 13, 1, 'Kad bih sve jezike ljudske govorio i anđeoske, a ljubavi ne bih imao, bio bih mjed što ječi ili cimbal što zveči.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (53, 13, 2, 'Kad bih imao dar prorokovanja i znao sva otajstva i sve spoznanje; i kad bih imao svu vjeru da bih i gore premještao, a ljubavi ne bih imao - ništa sam!');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (53, 13, 3, 'I kad bih razdao sav svoj imutak i kad bih predao tijelo svoje da se sažeže, a ljubavi ne bih imao - ništa mi ne bi koristilo.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (53, 13, 4, 'Ljubav je velikodušna, dobrostiva je ljubav, ne zavidi, ljubav se ne hvasta, ne nadima se;');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (53, 13, 5, 'nije nepristojna, ne traži svoje, nije razdražljiva, ne pamti zlo;');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (53, 13, 6, 'ne raduje se nepravdi, a raduje se istini;');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (53, 13, 7, 'sve pokriva, sve vjeruje, svemu se nada, sve podnosi.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (53, 13, 8, 'Ljubav nikad ne prestaje. Prorokovanja? Uminut će. Jezici? Umuknut će. Spoznanje? Uminut će.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (53, 13, 9, 'Jer djelomično je naše spoznanje, i djelomično prorokovanje.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (53, 13, 10, 'A kada dođe ono savršeno, uminut će ovo djelomično.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (53, 13, 11, 'Kad bijah nejače, govorah kao nejače, mišljah kao nejače, rasuđivah kao nejače. A kad postadoh zreo čovjek, odbacih ono nejačko.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (53, 13, 12, 'Doista, sada gledamo kroza zrcalo, u zagonetki, a tada - licem u lice! Sada spoznajem djelomično, a tada ću spoznati savršeno, kao što sam i spoznat!');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (53, 13, 13, 'A sada: ostaju vjera, ufanje i ljubav - to troje - ali najveća je među njima ljubav.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (53, 14, 1, 'Težite za ljubavlju, čeznite za darima Duha, a najvećma da prorokujete.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (53, 14, 2, 'Jer tko govori drugim jezikom, ne govori ljudima nego Bogu: nitko ga ne razumije jer Duhom govori stvari tajanstvene.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (53, 14, 3, 'Tko pak prorokuje, ljudima govori: izgrađuje, hrabri, tješi.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (53, 14, 4, 'Tko govori drugim jezikom, sam sebe izgrađuje, a tko prorokuje, Crkvu izgrađuje.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (53, 14, 5, 'A htio bih da vi svi govorite drugim jezicima, ali većma da prorokujete. Jer veći je tko prorokuje, negoli tko govori drugim jezicima, osim ako protumači Crkvi radi izgrađivanja.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (53, 14, 6, 'A sada, braćo, kad bih došao k vama govoreći drugim jezicima, što bi vam koristilo kad vam ne bih priopćio bilo otkrivenje, bilo spoznanje, bilo proroštvo, bilo nauk?');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (53, 14, 7, 'Ako neživa glazbala, svirala ili citra, ne daju razgovijetna glasa, kako će se razabrati što se to izvodi na svirali ili citri?');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (53, 14, 8, 'Ili ako trublja daje nejasan glas, tko će se spremiti na boj?');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (53, 14, 9, 'Tako i vi, ako jezikom ne budete jasno zborili, kako će se razabrati što se govori? Govorit ćete u vjetar.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (53, 14, 10, 'Toliko, recimo, ima na svijetu vrsta glasova i - nijedan bez značenja.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (53, 14, 11, 'Ako dakle ne znam značenja glasa, bit ću sugovorniku tuđinac, a sugovornik tuđinac meni.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (53, 14, 12, 'Tako i vi, budući da čeznete za darima Duha, nastojte njima obilovati radi izgrađivanja Crkve.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (53, 14, 13, 'Stoga tko govori drugim jezikom, neka se moli da može protumačiti.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (53, 14, 14, 'Jer ako se drugim jezikom molim, moj se duh moli, ali um je moj neplodan.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (53, 14, 15, 'Što dakle? Molit ću se duhom, molit ću se i umom; pjevat ću hvalospjeve duhom, ali pjevat ću ih i umom.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (53, 14, 16, 'Jer ako Boga blagoslivljaš duhom, kako će neupućen reći \"Amen\" na tvoju zahvalnicu? Ne zna što govoriš.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (53, 14, 17, 'Ti doduše lijepo zahvaljuješ, ali se drugi ne izgrađuje.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (53, 14, 18, 'Hvala Bogu, ja govorim drugim jezicima većma nego svi vi.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (53, 14, 19, 'Ali draže mi je u Crkvi reći pet riječi po svojoj pameti, da i druge poučim, negoli deset tisuća riječi drugim jezikom.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (53, 14, 20, 'Braćo, ne budite djeca pameću, nego nejačad pakošću, a zreli pameću!');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (53, 14, 21, 'U Zakonu je pisano: Drugim jezicima i drugim usnama govorit ću ovomu narodu pa me ni tako neće poslušati, govori Gospodin.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (53, 14, 22, 'Tako drugi jezici nisu znak vjernicima, nego nevjernicima; a prorokovanje vjernicima, ne nevjernicima.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (53, 14, 23, 'Ako se dakle skupi sva Crkva zajedno i svi govore drugim jezicima, a uđu neupućeni ili nevjernici, neće li reći da mahnitate?');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (53, 14, 24, 'Ako pak svi prorokuju, a uđe koji nevjernik ili neupućen, sve ga prekorava, sve ga osuđuje.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (53, 14, 25, 'Tajne se njegova srca očituju te će pasti ničice i pokloniti se Bogu priznajući: Zaista, Bog je u vama.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (53, 14, 26, 'Što dakle braćo? Kad se skupite te poneki ima hvalospjev, poneki ima nauk, ima otkrivenje, ima jezik, ima tumačenje - sve neka bude radi izgrađivanja.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (53, 14, 27, 'Ako tko govori drugim jezikom - dvojica, najviše trojica, i to jedan za drugim - jedan neka tumači;');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (53, 14, 28, 'ako pak ne bi bilo tumača, neka šuti u Crkvi, neka govori sam sebi i Bogu.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (53, 14, 29, 'Od proroka pak neka govore dvojica ili trojica, drugi neka rasuđuju.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (53, 14, 30, 'Ali ako drugomu uza nj bude što objavljeno, prvi neka šuti.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (53, 14, 31, 'A možete jedan po jedan svi prorokovati da svi budu poučeni i svi ohrabreni.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (53, 14, 32, 'Proročki su duhovi prorocima podložni');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (53, 14, 33, 'jer Bog nije Bog nesklada, nego Bog mira. Kao u svim Crkvama svetih, žene na Sastancima neka šute.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (53, 14, 34, 'Nije im dopušteno govoriti, nego neka budu podložne, kako i Zakon govori.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (53, 14, 35, 'Žele li što saznati, neka kod kuće pitaju svoje muževe jer ružno je da žena govori na Sastanku.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (53, 14, 36, 'Ili zar je riječ Božja od vas proizašla, zar je samo k vama došla?');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (53, 14, 37, 'Smatra li tko da je prorok ili duhom obdaren, neka zna: što vam pišem, Gospodnja je zapovijed.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (53, 14, 38, 'Tko to ne prizna, ne priznaje se.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (53, 14, 39, 'Zato, braćo moja, težite prorokovati i ne priječite da se govori drugim jezicima!');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (53, 14, 40, 'A sve neka bude dostojno i uredno.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (53, 15, 1, 'Dozivljem vam, braćo, u pamet evanđelje koje vam navijestih, koje primiste, u kome stojite,');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (53, 15, 2, 'po kojem se spasavate, ako držite što sam vam navijestio; osim ako uzalud povjerovaste.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (53, 15, 3, 'Doista, predadoh vam ponajprije što i primih: Krist umrije za grijehe naše po Pismima;');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (53, 15, 4, 'bi pokopan i uskrišen treći dan po Pismima;');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (53, 15, 5, 'ukaza se Kefi, zatim dvanaestorici.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (53, 15, 6, 'Potom se ukaza braći, kojih bijaše više od pet stotina zajedno; većina ih još i sada živi, a neki usnuše.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (53, 15, 7, 'Zatim se ukaza Jakovu, onda svim apostolima.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (53, 15, 8, 'Najposlije, kao nedonoščetu, ukaza se i meni.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (53, 15, 9, 'Da, ja sam najmanji među apostolima i nisam dostojan zvati se apostolom jer sam progonio Crkvu Božju.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (53, 15, 10, 'Ali milošću Božjom jesam što jesam i njegova milost prema meni ne bijaše zaludna; štoviše, trudio sam se više nego svi oni - ali ne ja, nego milost Božja sa mnom.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (53, 15, 11, 'Ili dakle ja ili oni: tako propovijedamo, tako vjerujete.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (53, 15, 12, 'No ako se propovijeda da je Krist od mrtvih uskrsnuo, kako neki među vama govore da nema uskrsnuća mrtvih?');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (53, 15, 13, 'Ako nema uskrsnuća mrtvih, ni Krist nije uskrsnuo.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (53, 15, 14, 'Ako pak Krist nije uskrsnuo, uzalud je doista propovijedanje naše, uzalud i vjera vaša.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (53, 15, 15, 'Zatekli bismo se i kao lažni svjedoci Božji što posvjedočismo protiv Boga: da je uskrisio Krista, kojega nije uskrisio, ako doista mrtvi ne uskršavaju.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (53, 15, 16, 'Jer ako mrtvi ne uskršavaju, ni Krist nije uskrsnuo.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (53, 15, 17, 'A ako Krist nije uskrsnuo, uzaludna je vjera vaša, još ste u grijesima.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (53, 15, 18, 'Onda i oni koji usnuše u Kristu, propadoše.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (53, 15, 19, 'Ako se samo u ovom životu u Krista ufamo, najbjedniji smo od svih ljudi.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (53, 15, 20, 'Ali sada: Krist uskrsnu od mrtvih, prvina usnulih!');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (53, 15, 21, 'Doista po čovjeku smrt, po Čovjeku i uskrsnuće od mrtvih!');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (53, 15, 22, 'Jer kao što u Adamu svi umiru, tako će i u Kristu svi biti oživljeni.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (53, 15, 23, 'Ali svatko u svom redu: prvina Krist, a zatim koji su Kristovi, o njegovu Dolasku;');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (53, 15, 24, 'potom - svršetak, kad preda kraljevstvo Bogu i Ocu, pošto obeskrijepi svako Vrhovništvo, svaku Vlast i Silu.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (53, 15, 25, 'Doista, on treba da kraljuje dok ne podloži sve neprijatelje pod noge svoje.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (53, 15, 26, 'Kao posljednji neprijatelj bit će obeskrijepljena Smrt');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (53, 15, 27, 'jer sve podloži nogama njegovim. A kad veli: Sve je podloženo, jasno - sve osim Onoga koji mu je sve podložio.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (53, 15, 28, 'I kad mu sve bude podloženo, tada će se i on sam, Sin, podložiti Onomu koji je njemu sve podložio da Bog bude sve u svemu.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (53, 15, 29, 'Što onda čine oni koji se krste za mrtve? Ako mrtvi uopće ne uskršavaju, što se krste za njih?');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (53, 15, 30, 'Što se onda i mi svaki čas izlažemo pogiblima?');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (53, 15, 31, 'Dan za danom umirem, tako mi slave vaše, braćo, koju imam u Kristu Isusu, Gospodinu našem!');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (53, 15, 32, 'Ako sam se po ljudsku borio sa zvijerima u Efezu, kakva mi korist? Ako mrtvi ne uskršavaju, jedimo i pijmo jer sutra nam je umrijeti.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (53, 15, 33, 'Ne varajte se: \"Zli razgovori kvare dobre običaje.\"');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (53, 15, 34, 'Otrijeznite se kako valja i ne griješite jer neki, na sramotu vam kažem, ne znaju za Boga.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (53, 15, 35, 'Ali reći će netko: Kako uskršavaju mrtvi? I s kakvim li će tijelom doći?');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (53, 15, 36, 'Bezumniče! Što siješ, ne oživljuje ako ne umre.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (53, 15, 37, 'I što siješ, ne siješ tijelo buduće, već golo zrno, pšenice - recimo - ili čega drugoga.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (53, 15, 38, 'A Bog mu daje tijelo kakvo hoće, i to svakom sjemenu svoje tijelo.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (53, 15, 39, 'Nije svako tijelo isto tijelo; drugo je tijelo čovječje, drugo tijelo stoke, drugo tijelo ptičje, a drugo riblje.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (53, 15, 40, 'Ima tjelesa nebeskih i tjelesa zemaljskih, ali drugi je sjaj nebeskih, a drugi zemaljskih.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (53, 15, 41, 'Drugi je sjaj sunca, drugi sjaj mjeseca i drugi sjaj zvijezda; jer zvijezda se od zvijezde razlikuje u sjaju.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (53, 15, 42, 'Tako i uskrsnuće mrtvih: sije se u raspadljivosti, uskršava u neraspadljivosti;');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (53, 15, 43, 'sije se u sramoti, uskršava u slavi; sije se u slabosti, uskršava u snazi;');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (53, 15, 44, 'sije se tijelo naravno, uskršava tijelo duhovno. Ako ima tijelo naravno, ima i duhovno.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (53, 15, 45, 'Tako je i pisano: Prvi čovjek, Adam, postade živa duša, posljednji Adam - duh životvorni.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (53, 15, 46, 'Ali ne bi najprije duhovno, nego naravno pa onda duhovno.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (53, 15, 47, 'Prvi je čovjek od zemlje, zemljan; drugi čovjek - s neba.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (53, 15, 48, 'Kakav je zemljani takvi su i zemljani, a kakav je nebeski takvi su i nebeski.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (53, 15, 49, 'I kao što smo nosili sliku zemljanoga, nosit ćemo i sliku nebeskoga.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (53, 15, 50, 'A ovo, braćo, tvrdim: tijelo i krv ne mogu baštiniti kraljevstva Božjega i raspadljivost ne baštini neraspadljivosti.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (53, 15, 51, 'Evo otajstvo vam kazujem: svi doduše nećemo usnuti, ali svi ćemo se izmijeniti.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (53, 15, 52, 'Odjednom, u tren oka, na posljednju trublju - jer zatrubit će - i mrtvi će uskrsnuti neraspadljivi i mi ćemo se izmijeniti.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (53, 15, 53, 'Jer ovo raspadljivo treba da se obuče u neraspadljivost i ovo smrtno da se obuče u besmrtnost.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (53, 15, 54, 'A kad se ovo raspadljivo obuče u neraspadljivost i ovo smrtno obuče u besmrtnost, tada će se obistiniti riječ napisana: Pobjeda iskapi smrt.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (53, 15, 55, 'Gdje je, smrti, pobjeda tvoja? Gdje je, smrti, žalac tvoj?');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (53, 15, 56, 'Žalac je smrti grijeh, snaga je grijeha Zakon.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (53, 15, 57, 'A hvala Bogu koji nam daje pobjedu po Gospodinu našem Isusu Kristu!');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (53, 15, 58, 'Tako, braćo moja ljubljena, budite postojani, nepokolebljivi, i obilujte svagda u djelu Gospodnjem znajući da trud vaš nije neplodan u Gospodinu.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (53, 16, 1, 'U pogledu sabiranja za svete, i vi činite kako odredih crkvama galacijskim.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (53, 16, 2, 'Svakoga prvog dana u tjednu neka svaki od vas kod sebe na stranu stavlja i skuplja što uzmogne da se ne sabire istom kada dođem.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (53, 16, 3, 'A kada dođem, poslat ću s preporučnicom one koje odaberete da odnesu vašu ljubav u Jeruzalem.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (53, 16, 4, 'Bude li vrijedno da i ja pođem, poći će sa mnom.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (53, 16, 5, 'A k vama ću doći kad prođem Makedoniju; Makedonijom ću samo proći,');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (53, 16, 6, 'a kod vas ću se možda zadržati ili čak zimovati da me otpratite kamo god pođem.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (53, 16, 7, 'Ne bih vas doista htio tek na prolazu vidjeti jer se nadam neko vrijeme proboraviti kod vas, dopusti li Gospodin.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (53, 16, 8, 'U Efezu ću ostati do Pedesetnice');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (53, 16, 9, 'jer vrata mi se otvoriše velika i uspješna, a protivnika mnogo.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (53, 16, 10, 'Ako dođe Timotej, gledajte da bude kod vas bez bojazni jer radi djelo Gospodnje kao i ja.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (53, 16, 11, 'Neka ga dakle nitko ne prezre. A ispratite ga u miru da dođe k meni jer ga s braćom iščekujem.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (53, 16, 12, 'A što se tiče brata Apolona: mnogo sam ga nagovarao da ode k vama s braćom. I nikako mu ne bijaše s voljom da sada dođe, no doći će kad mu bude zgodno.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (53, 16, 13, 'Bdijte postojani u vjeri, muževni budite, čvrsti.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (53, 16, 14, 'Sve vaše neka bude u ljubavi!');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (53, 16, 15, 'Zaklinjem vas, braćo - znate dom Stefanin, da je prvina Ahaje i da se posvetiše posluživanju svetih -');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (53, 16, 16, 'da se i vi pokoravate takvima i svakomu tko surađuje i trudi se.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (53, 16, 17, 'Radujem se s dolaska Stefanina i Fortunatova i Ahajikova jer oni nadoknadiše vašu nenazočnost:');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (53, 16, 18, 'umiriše duh moj i vaš. Cijenite dakle takve.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (53, 16, 19, 'Pozdravljaju vas crkve azijske. Pozdravljaju vas mnogo u Gospodinu Akvila i Priska zajedno s Crkvom u njihovu domu.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (53, 16, 20, 'Pozdravljaju vas sva braća. Pozdravite jedni druge cjelovom svetim.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (53, 16, 21, 'Pozdrav mojom rukom, Pavlovom.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (53, 16, 22, 'Ako tko ne ljubi Gospodina, neka bude proklet. Marana tha!');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (53, 16, 23, 'Milost Gospodina Isusa s vama!');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (53, 16, 24, 'Ljubav moja sa svima vama u Kristu Isusu!');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (54, 1, 1, 'Pavao, po volji Božjoj apostol Krista Isusa, i brat Timotej: Crkvi Božjoj u Korintu sa svima svetima u svoj Ahaji.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (54, 1, 2, 'Milost vam i mir od Boga, Oca našega, i Gospodina Isusa Krista!');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (54, 1, 3, 'Blagoslovljen Bog i Otac Gospodina našega Isusa Krista, Otac milosrđa i Bog svake utjehe!');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (54, 1, 4, 'On nas tješi u svakoj našoj nevolji da bismo i mi sve koji su u nevolji mogli tješiti onom utjehom kojom nas same tješi Bog.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (54, 1, 5, 'Jer kao što su obilate patnje Kristove u nama, tako je po Kristu obilata i utjeha naša.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (54, 1, 6, 'Bili mi nevoljama pritisnuti za vašu je to utjehu i spasenje; bili utješeni, za vašu je utjehu - djelotvornu: da strpljivo podnesete iste patnje koje i mi podnosimo.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (54, 1, 7, 'I tako je stamena nada naša o vama jer znamo: kao što ste zajedničari patnja tako ste i utjehe.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (54, 1, 8, 'Ne bismo doista htjeli, braćo, da ne znate za nevolju koja nas je snašla u Aziji. Bijasmo prekomjerno, preko snage, opterećeni te smo već strepili i za život.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (54, 1, 9, 'Ali u sebi prihvatismo i smrtnu osudu da se ne bismo uzdali u same sebe, nego u Boga koji uskrisuje mrtve.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (54, 1, 10, 'On nas je od takve smrti izbavio i izbavit će nas; u njega se uzdamo, on će nas i dalje izbavljati.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (54, 1, 11, 'A i vi ćete nam pomagati molitvom da bi mnogi za nas zahvaljivali Bogu na milosti koja nam je darovana posredovanjem mnogih.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (54, 1, 12, 'A ovo je naša slava: svjedočansto naše savjesti da smo u svijetu živjeli - osobito prema vama - u svetosti i iskrenosti Božjoj, ne u mudrosti tjelesnoj, nego u Božjoj milosti.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (54, 1, 13, 'Ta i ne pišemo vam drugo doli ovo što čitate i razumijete; a nadam se da ćete i do kraja razumjeti,');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (54, 1, 14, 'kao što nas djelomično i razumjeste: da smo mi vaša slava kao i vi naša u Dan Gospodina našega Isusa.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (54, 1, 15, 'U tom uvjerenju namjeravao sam najprije doći k vama');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (54, 1, 16, 'i preko vas prijeći u Makedoniju pa se opet, da biste imali i drugu milost, iz Makedonije vratiti k vama da me vi otpratite u Judeju.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (54, 1, 17, 'Pa jesam li možda bio lakomislen kad sam to namjeravao? Ili što namjeravam, po tijelu namjeravam te je u mene istodobno \"Da, da!\" i \"Ne, ne!\"?');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (54, 1, 18, 'Bog je svjedok: naša riječ vama nije \"Da!\" i \"Ne!\"');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (54, 1, 19, 'jer Sin Božji, Isus Krist, koga mi - ja i Silvan i Timotej - vama navijestismo nije bio \"Da!\" i \"Ne!\" nego u njemu bijaše \"Da!\".');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (54, 1, 20, 'Doista, sva obećanja Božja u njemu su \"Da!\". I stoga po njemu i naš \"Amen!\" Bogu na slavu!');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (54, 1, 21, 'A Bog je onaj koji nas zajedno s vama utvrđuje za Krista; on nas i pomaza,');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (54, 1, 22, 'on nas i zapečati i u srca naša dade zalog - Duha.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (54, 1, 23, 'A ja prizivljem Boga za svjedoka: duše mi, da vas poštedim, nisam više dolazio u Korint.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (54, 1, 24, 'Ta mi nismo gospodari vaše vjere, nego suradnici vaše radosti. Ta u vjeri ste postojani.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (54, 2, 1, 'Odlučih dakle u sebi da neću k vama opet sa žalošću.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (54, 2, 2, 'Jer ako ja vas ražalostim, a tko će mene obradovati ako ne onaj koga ja žalostim?');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (54, 2, 3, 'Zato vam to i napisah da me, kada dođem, ne ražaloste oni koji bi mi imali biti na radost. Uzdam se doista u sve vas, da je moja radost - radost svih vas.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (54, 2, 4, 'Pisah vam uistinu uz mnoge suze, iz velike nevolje i tjeskobe srca, ne da se ražalostite, nego da upoznate moju preveliku ljubav prema vama.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (54, 2, 5, 'Ako me tko ražalostio, nije ražalostio mene, nego u neku ruku - da ne pretjeram - sve vas.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (54, 2, 6, 'Dosta je takvu ona kazna od većine');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (54, 2, 7, 'pa ga vi radije pomilujte i utješite da ga pretjerana žalost ne shrva.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (54, 2, 8, 'Zato vas molim, iskažite mu ljubav.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (54, 2, 9, 'Ta zato vam i pisah da vidim jeste li prokušani, jeste li u svemu poslušni.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (54, 2, 10, 'Komu dakle vi što oprostite, tomu i ja; jer i ja, ako kome što oprostih, oprostih poradi vas - pred Kristom,');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (54, 2, 11, 'da nas ne nadmudri Sotona. Ta znamo njegove namjere!');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (54, 2, 12, 'Kada dođoh u Troadu poradi evanđelja Kristova, premda mi se otvoriše vrata u Gospodinu,');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (54, 2, 13, 'ne bijaše mi duši spokoja što ne nađoh Tita, brata svoga; oprostih se stoga s njima i pođoh u Makedoniju.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (54, 2, 14, 'Ali hvala Bogu koji nas u Kristu uvijek proslavlja te širi po nama na svakome mjestu miris svoga spoznanja.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (54, 2, 15, 'Da, Kristov smo miomiris Bogu i među onima koji se spasavaju i među onima koji propadaju:');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (54, 2, 16, 'ovima miris iz smrti za smrt, onima miris iz života za život. A tko je za to podoban?');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (54, 2, 17, 'Uistinu, mi nismo kao mnogi koji trguju riječju Božjom, nego iskreno - kao od Boga pred Bogom - u Kristu govorimo.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (54, 3, 1, 'Počinjemo li opet sami sebe preporučivati? Ili trebamo li, kao neki, preporučna pisma na vas ili od vas?');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (54, 3, 2, 'Vi ste pismo naše, upisano u srcima vašim; znaju ga i čitaju svi ljudi.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (54, 3, 3, 'Vi ste, očito, pismo Kristovo kojemu mi poslužismo, napisano ne crnilom, nego Duhom Boga živoga; ne na pločama kamenim, nego na pločama od mesa, u srcima.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (54, 3, 4, 'Takvo pouzdanje imamo po Kristu u Boga.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (54, 3, 5, 'Ne kao da smo sami sobom, kao od sebe, sposobni što pomisliti, nego naša je sposobnost od Boga.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (54, 3, 6, 'On nas osposobi za poslužitelje novoga Saveza, ne slova, nego Duha; jer slovo ubija, a Duh oživljuje.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (54, 3, 7, 'Pa ako je smrtonosna služba, slovima uklesana u kamenju, bila tako slavna da sinovi Izraelovi nisu mogli pogledati u lice Mojsijevo zbog prolazne slave lica njegova,');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (54, 3, 8, 'koliko li će slavnija biti služba Duha.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (54, 3, 9, 'Jer ako je služba osude bila slavna, mnogo je slavnija služba pravednosti.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (54, 3, 10, 'I zbilja, nije ni bilo proslavljeno ono što je u toj mjeri proslavljeno, ako se usporedi s uzvišenijom slavom.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (54, 3, 11, 'Jer ako je ono prolazno bilo slavno, mnogo je slavnije ovo što ostaje.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (54, 3, 12, 'Imajući dakle takvo pouzdanje, nastupamo sa svom otvorenošću,');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (54, 3, 13, 'a ne kao Mojsije koji je stavljao prijevjes na lice da sinovi Izraelovi ne vide svršetak prolaznoga.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (54, 3, 14, 'Ali otvrdnu im pamet. Doista, do dana današnjega zastire taj prijevjes čitanje Staroga zavjeta: nije im otkriveno da je u Kristu prestao.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (54, 3, 15, 'Naprotiv, kad god se čita Mojsije, do danas prijevjes zastire srce njihovo.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (54, 3, 16, 'Ali kad se Izrael obrati Gospodinu, skinut će se prijevjes.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (54, 3, 17, 'Gospodin je Duh, a gdje je Duh Gospodnji, ondje je sloboda.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (54, 3, 18, 'A svi mi, koji otkrivenim licem odrazujemo slavu Gospodnju, po Duhu se Gospodnjem preobražavamo u istu sliku - iz slave u slavu.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (54, 4, 1, 'Zato, budući da po milosrđu imamo ovu službu, ne malakšemo.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (54, 4, 2, 'Ali odrekosmo se sramotnoga prikrivanja: ne nastupamo lukavo niti izopačujemo riječ Božju, nego se objavljivanjem istine preporučujemo svakoj savjesti ljudskoj pred Bogom.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (54, 4, 3, 'Ako je i zastrto evanđelje naše, u onima je zastrto koji propadaju:');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (54, 4, 4, 'u onima kojima bog ovoga svijeta oslijepi pameti nevjerničke da ne zasvijetli svjetlost evanđelja slave Krista koji je slika Božja.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (54, 4, 5, 'Jer ne propovijedamo same sebe, nego Krista Isusa Gospodinom, a sebe slugama vašim poradi Isusa.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (54, 4, 6, 'Ta Bog koji reče: Neka iz tame svjetlost zasine!, on zasvijetli u srcima našim da nam spoznanje slave Božje zasvijetli na licu Kristovu.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (54, 4, 7, 'To pak blago imamo u glinenim posudama da izvanredna ona snaga bude očito Božja, a ne od nas.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (54, 4, 8, 'U svemu pritisnuti, ali ne pritiješnjeni; dvoumeći, ali ne zdvajajući;');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (54, 4, 9, 'progonjeni, ali ne napušteni; obarani, ali ne oboreni -');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (54, 4, 10, 'uvijek umiranje Isusovo u tijelu pronosimo da se i život Isusov u tijelu našem očituje.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (54, 4, 11, 'Doista, mi se živi uvijek na smrt predajemo poradi Isusa da se i život Isusov očituje u našem smrtnom tijelu.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (54, 4, 12, 'Tako smrt djeluje u nama, život u vama.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (54, 4, 13, 'A budući da imamo isti duh vjere kao što je pisano: Uzvjerovah, zato besjedim, i mi vjerujemo pa zato i besjedimo.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (54, 4, 14, 'Ta znamo: onaj koji je uskrisio Gospodina Isusa i nas će s Isusom uskrisiti i zajedno s vama uza se postaviti.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (54, 4, 15, 'A sve je to za vas: da milost - umnožena - zahvaljivanjem mnogih izobiluje Bogu na slavu.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (54, 4, 16, 'Zato ne malakšemo. Naprotiv, ako se naš izvanji čovjek i raspada, nutarnji se iz dana u dan obnavlja.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (54, 4, 17, 'Ta ova malenkost naše časovite nevolje donosi nam obilato, sve obilatije, breme vječne slave');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (54, 4, 18, 'jer nama nije do vidljivog nego do nevidljivog: ta vidljivo je privremeno, a nevidljivo - vječno.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (54, 5, 1, 'Znamo doista: ako se razruši naš zemaljski dom, šator, imamo zdanje od Boga, dom nerukotvoren, vječan na nebesima.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (54, 5, 2, 'U ovome doista stenjemo i čeznemo da se povrh njega zaodjenemo svojim nebeskim obitavalištem;');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (54, 5, 3, 'dakako, ako se nađemo obučeni, ne goli.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (54, 5, 4, 'Da, i mi koji smo u ovom šatoru, stenjemo opterećeni jer nećemo da budemo svučeni, nego da se još obučemo da život iskapi što je smrtno.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (54, 5, 5, 'A zato nas je sazdao Bog - on koji nam dade zalog Duha.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (54, 5, 6, 'Uvijek smo stoga puni pouzdanja makar i znamo: naseljeni u tijelu, iseljeni smo od Gospodina.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (54, 5, 7, 'Ta u vjeri hodimo, ne u gledanju.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (54, 5, 8, 'Da, puni smo pouzdanja i najradije bismo se iselili iz tijela i naselili kod Gospodina.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (54, 5, 9, 'Zato se i trsimo da mu omilimo, bilo naseljeni, bilo iseljeni.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (54, 5, 10, 'Jer svima nam se pojaviti pred sudištem Kristovim da svaki dobije što je kroz tijelo zaradio, bilo dobro, bilo zlo.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (54, 5, 11, 'Prožeti dakle strahom Gospodnjim uvjeravamo ljude; razotkriveni smo Bogu, a nadam se - i vašim savjestima.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (54, 5, 12, 'Ne preporučujemo vam opet sami sebe, nego vam dajemo prigodu ponositi se nama, da imate odgovor za one koji se diče licem, a ne srcem.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (54, 5, 13, 'Doista, ako bijasmo \"izvan sebe\" - Bogu bijasmo; ako li \"pri sebi\" - vama bijasmo.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (54, 5, 14, 'Jer ljubav nas Kristova obuzima kad promatramo ovo: jedan za sve umrije, svi dakle umriješe;');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (54, 5, 15, 'i za sve umrije da oni koji žive ne žive više sebi, nego onomu koji za njih umrije i uskrsnu.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (54, 5, 16, 'Stoga mi od sada nikoga ne poznajemo po tijelu; ako smo i poznavali po tijelu Krista, sada ga tako više ne poznajemo.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (54, 5, 17, 'Dakle, je li tko u Kristu, nov je stvor. Staro uminu, novo, gle, nasta!');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (54, 5, 18, 'A sve je od Boga koji nas sa sobom pomiri po Kristu i povjeri nam službu pomirenja.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (54, 5, 19, 'Jer Bog je u Kristu svijet sa sobom pomirio ne ubrajajući im opačina njihovih i polažući u nas riječ pomirenja.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (54, 5, 20, 'Kristovi smo dakle poslanici; Bog vas po nama nagovara. Umjesto Krista zaklinjemo: dajte, pomirite se s Bogom!');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (54, 5, 21, 'Njega koji ne okusi grijeha Bog za nas grijehom učini da mi budemo pravednost Božja u njemu.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (54, 6, 1, 'Kao suradnici opominjemo vas da ne primite uzalud milosti Božje.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (54, 6, 2, 'Jer on veli: U vrijeme milosti usliših te i u dan spasa pomogoh ti. Evo sad je vrijeme milosno, evo sad je vrijeme spasa.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (54, 6, 3, 'Ni u čemu ne dajemo nikakve sablazni da se ne kudi ova služba,');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (54, 6, 4, 'nego se u svemu iskazujemo kao poslužitelji Božji: velikom postojanošću u nevoljama, u potrebama, u tjeskobama,');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (54, 6, 5, 'pod udarcima, u tamnicama, u bunama, u naporima, u bdjenjima, u postovima,');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (54, 6, 6, 'u čistoći, u spoznanju, u velikodušnosti, u dobroti, u Duhu Svetomu, u ljubavi nehinjenoj,');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (54, 6, 7, 'u riječi istinitoj, u snazi Božjoj; oružjem pravde zdesna i slijeva;');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (54, 6, 8, 'slavom i sramotom; zlim i dobrim glasom; kao zavodnici, a istiniti;');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (54, 6, 9, 'kao nepoznati, a poznati; kao umirući, a evo živimo; kao kažnjeni, a ne ubijeni;');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (54, 6, 10, 'kao žalosni, a uvijek radosni; kao siromašni, a mnoge obogaćujemo; kao oni koji ništa nemaju, a sve posjeduju.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (54, 6, 11, 'Usta su naša otvorena vama, Korinćani, srce naše rašireno.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (54, 6, 12, 'Nije vam tijesno u nama, ali je tijesno u vašim grudima.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (54, 6, 13, 'Za uzdarje - kao djeci govorim - raširite se i vi.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (54, 6, 14, 'Ne ujarmljujte se s nevjernicima. Ta što ima pravednost s bezakonjem? Ili kakvo zajedništvo svjetlo s tamom?');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (54, 6, 15, 'Kakvu slogu Krist s Belijarom? Ili kakav dio vjernik s nevjernikom?');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (54, 6, 16, 'Kakav sporazum hram Božji s idolima? Jer mi smo hram Boga živoga, kao što reče Bog: Prebivat ću u njima i hoditi među njima; i bit ću Bog njihov, a oni narod moj.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (54, 6, 17, 'Zato iziđite iz njihove sredine i odvojite se, govori Gospodin, i ništa nečisto ne dotičite i ja ću vas primiti.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (54, 6, 18, 'I bit ću vam otac i vi ćete mi biti sinovi i kćeri, veli Gospodin Svemogući.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (54, 7, 1, 'Dakle, budući da imamo ta obećanja, očistimo se, ljubljeni, od svake ljage tijela i duha te dovršimo posvećenje u strahu Božjemu.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (54, 7, 2, 'Shvatite nas! Nikomu nismo nanijeli nepravde, nikoga nismo upropastili, nikoga zakinuli.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (54, 7, 3, 'Ne govorim da osudim. Ta rekoh već: u srcima ste našim te umiremo i živimo zajedno.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (54, 7, 4, 'Veliko je moje pouzdanje u vas, uvelike se vama ponosim. Pun sam utjehe, obilujem radošću uza svu nevolju našu.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (54, 7, 5, 'Doista, i kada dođosmo u Makedoniju, nikakva spokoja nije imalo tijelo naše, nego nevolje odasvud: izvana borbe, iznutra strepnje.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (54, 7, 6, 'Ali Bog, tješitelj poniznih, utješi nas dolaskom Titovim.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (54, 7, 7, 'Ne samo dolaskom njegovim, nego i utjehom kojom se utješi zbog vas: obavijesti nas o vašoj čežnji, vašem jadikovanju, vašoj žarkoj ljubavi prema meni tako da se još većma obradovah.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (54, 7, 8, 'Doista, ako sam vas i ožalostio onom poslanicom, nije mi žao; ako mi i bijaše žao - vidim uistinu da vas je ta poslanica makar i načas ožalostila -');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (54, 7, 9, 'sad se radujem, ne što ste se ožalostili, nego što ste se ožalostili na obraćenje. Jer ožalostili ste se po Božju te zbog nas ni u čemu niste štetovali.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (54, 7, 10, 'Jer žalost po Božju rađa neopozivo spasonosnim obraćenjem, a žalost svjetovna rađa smrću.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (54, 7, 11, 'Gle, doista baš to što ste se po Božju ožalostili, kolikom gorljivošću urodi među vama, pa opravdavanjem, pa ogorčenjem, pa strahom, pa čežnjom, pa revnošću, pa kažnjavanjem. Svime ste time pokazali da ste u onome nedužni.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (54, 7, 12, 'Ako sam vam dakle pisao, nisam to zbog uvreditelja ni zbog uvrijeđenoga, nego zbog toga da vam se očituje vaša gorljivost za nas pred Bogom.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (54, 7, 13, 'To nas je utješilo. A povrh te naše utjehe još se mnogo više obradovasmo zbog radosti Titove jer svi vi okrijepiste duh njegov.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (54, 7, 14, 'Doista, ako sam mu se što vama pohvalio, ne postidjeh se, nego kao što smo po istini vama govorili, tako je istina bila i pohvala naša pred Titom.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (54, 7, 15, 'I njegovo je srce prema vama još nježnije kad se sjeti poslušnosti svih vas, kako ga sa strahom i trepetom primiste.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (54, 7, 16, 'Radujem se što se u svemu mogu pouzdati u vas.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (54, 8, 1, 'Priopćujemo vam, braćo, milost Božju koja je dana crkvama makedonskim:');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (54, 8, 2, 'unatoč mnogim kušnjama i nevoljama izobilna njihova radost i skrajnje siromaštvo preli se u bogatstvo darežljivosti.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (54, 8, 3, 'Svjedočim uistinu: oni su nas dragovoljno - po svojim mogućnostima i preko mogućnosti -');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (54, 8, 4, 'veoma usrdno molili za milost zajedništva u ovom posluživanju svetih.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (54, 8, 5, 'I to ne samo kako se nadasmo, nego same sebe predadoše najprvo Gospodinu, a onda nama, po volji Božjoj.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (54, 8, 6, 'Zato zamolismo Tita da kao što je započeo, tako i dovrši među vama i to djelo darežljivosti.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (54, 8, 7, 'Stoga kao što se u svemu odlikujete - u vjeri, i riječi, i spoznanju, i svakoj gorljivosti, i u ljubavi svojoj prema nama - odlikujte se i u ovoj darežljivosti.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (54, 8, 8, 'Ne zapovijedam, nego gorljivošću drugih prokušavam istinitost vaše ljubavi.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (54, 8, 9, 'Ta poznate darežljivost Gospodina našega Isusa Krista! Premda bogat, radi vas posta siromašan, da se vi njegovim siromaštvom obogatite.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (54, 8, 10, 'Time dajem samo savjet: to doista dolikuje vama koji već prošle godine prvi to započeste, ne samo činom nego i odlukom.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (54, 8, 11, 'Sada dovršite to djelo da kao što spremno odlučiste, tako prema mogućnostima i dovršite.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (54, 8, 12, 'Jer ima li spremnosti, mila je po onom što ima, a ne po onom čega nema.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (54, 8, 13, 'Ne dakako: drugima olakšica, vama oskudica, nego - jednakost!');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (54, 8, 14, 'U sadašnjem trenutku vaš suvišak za njihovu oskudicu da jednom njihov suvišak bude za vašu oskudicu - te bude jednakost,');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (54, 8, 15, 'kao što je pisano: Nije ništa preteklo onome koji bijaše nakupio mnogo, a niti je nedostajalo onome koji bijaše nakupio manje.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (54, 8, 16, 'A hvala Bogu koji je stavio jednaku gorljivost za vas u srce Titovo.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (54, 8, 17, 'On je prihvatio i molbu, ali budući da je veoma revan, otiđe k vama i dragovoljno.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (54, 8, 18, 'S njime pak šaljemo brata kojega s evanđelja slave sve crkve.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (54, 8, 19, 'Štoviše, crkve ga izabraše za našeg suputnika u ovom djelu darežljivosti kojemu služimo - na slavu samoga Gospodina i na našu želju');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (54, 8, 20, 'kako bismo izbjegli da nas tko ne prekori zbog ovog obilja kojim raspolažemo.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (54, 8, 21, 'Doista, revno nastojimo oko dobra ne samo pred Gospodinom nego i pred ljudima.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (54, 8, 22, 'Šaljemo s njima i našega brata koji je, kako smo u mnogome često iskusili, gorljiv, a sada je još mnogo gorljiviji zbog velikoga pouzdanja u vas.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (54, 8, 23, 'A Tito? Moj je drug i suradnik za vas. A braća naša? Poslanici su crkava, slava Kristova.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (54, 8, 24, 'Pružite im dakle pred crkvama dokaz svoje ljubavi i toga da se s pravom vama ponosimo.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (54, 9, 1, 'A o posluživanju svetih suvišno je da vam pišem.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (54, 9, 2, 'Ta poznajem vašu spremnost s koje se vama ponosim pred Makedoncima: \"Ahaja je spremna od prošle godine.\" I vaša gorljivost potaknu mnoge.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (54, 9, 3, 'Ipak šaljem braću da se u tome pogledu ne opovrgne što se vama ponosimo; da budete spremni kao što sam tvrdio te se -');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (54, 9, 4, 'ako sa mnom dođu Makedonci i nađu vas nespremne - ne osramotimo s preuzetnosti mi, da ne kažemo vi.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (54, 9, 5, 'Smatrao sam dakle potrebnim zamoliti braću da unaprijed pođu k vama i da pripreme vaš još prije obećani dar te bude pripravan - kao dar darežljivosti, a ne škrtosti.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (54, 9, 6, 'Ta eno: tko sije oskudno, oskudno će i žeti; a tko sije obilato, obilato će i žeti.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (54, 9, 7, 'Svatko neka dade kako je srcem odlučio; ne sa žalošću ili na silu jer Bog ljubi vesela darivatelja.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (54, 9, 8, 'A Bog vas može obilato obdariti svakovrsnim darom da u svemu svagda imate svega dovoljno za se i izobilno za svako dobro djelo -');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (54, 9, 9, 'kao što je pisano: Rasipno dijeli, daje sirotinji, pravednost njegova ostaje dovijeka.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (54, 9, 10, 'A onaj koji pribavlja sjeme sijaču i kruh za jelo, pribavit će i umnožiti sjeme vaše i povećati plodove pravednosti vaše.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (54, 9, 11, 'Tako ćete se u svemu obogatiti za svakovrsnu darežljivost koja se, našim posredovanjem, izvija u zahvalnicu Bogu.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (54, 9, 12, 'Jer ovo bogoslužno posluživanje ne samo da podmiruje oskudicu svetih nego se i obilno prelijeva u mnoge zahvalnice Bogu.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (54, 9, 13, 'Osvjedočeni ovim posluživanjem, slave Boga zbog vašega pokornog ispovijedanja evanđelja Kristova i zbog velikodušnog zajedništva prema njima i prema svima.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (54, 9, 14, 'A moleći se za vas, čeznu za vama zbog preobilne milosti Božje na vama.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (54, 9, 15, 'Hvala Bogu na njegovu neizrecivom daru!');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (54, 10, 1, 'Ja, Pavao, osobno vas zaklinjem blagošću i obazrivošću Kristovom - ja koji sam licem u lice među vama \"skroman\", a nenazočan prema vama \"odvažan\" -');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (54, 10, 2, 'molim da, jednom nazočan, ne moram biti odvažan smionošću kojom se kanim osmjeliti protiv nekih što smatraju da mi po tijelu živimo.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (54, 10, 3, 'Jer iako živimo u tijelu, ne vojujemo po tijelu.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (54, 10, 4, 'Ta oružje našega vojevanja nije tjelesno, nego božanski snažno za rušenje utvrda. Obaramo mudrovanja');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (54, 10, 5, 'i svaku oholost koja se podiže protiv spoznanja Boga i zarobljujemo svaki um na pokornost Kristu;');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (54, 10, 6, 'i spremni smo kazniti svaku nepokornost čim bude savršena vaša pokornost.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (54, 10, 7, 'Gledajte što je očito! Ako je tko uvjeren da je \"Kristov\", neka sam ponovno promisli ovo: kako je on Kristov, tako smo i mi.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (54, 10, 8, 'Kad bih se doista i malo više pohvalio našom vlašću - koju nam Gospodin dade za vaše izgrađivanje, a ne rušenje - ne bih se morao stidjeti.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (54, 10, 9, 'Samo da se ne bi činilo kao da vas zastrašujem poslanicama!');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (54, 10, 10, 'Jer \"poslanice su, kaže, stroge i snažne, ali tjelesna nazočnost nemoćna i riječ bezvrijedna\".');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (54, 10, 11, 'Takav neka promisli ovo: kakvi smo nenazočni riječju u poslanicama, takvi smo i nazočni djelom.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (54, 10, 12, 'Ne usuđujemo se, doista, izjednačiti ili usporediti s nekima koji sami sebe preporučuju, ali nisu razumni jer sami sebe sobom mjere i sami sebe sa sobom uspoređuju.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (54, 10, 13, 'Mi se pak nećemo hvaliti u bezmjerje, nego po mjeri, mjerilu što nam ga odmjeri Bog kao mjeru: doprijeti sve do vas.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (54, 10, 14, 'Jer mi ne posežemo preko svoga, kao da još nismo stigli do vas. Ta prvi doista doprijesmo do vas s evanđeljem Kristovim.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (54, 10, 15, 'Ne hvalimo se u bezmjerje, tuđim naporima. A nadamo se da ćemo s uzrastom vaše vjere među vama i mi - po našem mjerilu - prerasti u izobilje:');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (54, 10, 16, 'i preko vaših granica navijestiti evanđelje, a ne hvastati se onim što je već učinjeno na tuđem području.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (54, 10, 17, 'Tko se hvali, u Gospodinu neka se hvali.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (54, 10, 18, 'Ta nije prokušan tko sam sebe preporučuje, nego koga preporučuje Gospodin.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (54, 11, 1, 'O kad biste podnijeli nešto malo bezumlja mojega! Da, podnesite me!');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (54, 11, 2, 'Ljubomoran sam doista na vas Božjim ljubomorom: ta zaručih vas s jednim mužem, kao čistu djevicu privedoh vas Kristu.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (54, 11, 3, 'Ali se bojim da se - kao što zmija zavede Evu svojom lukavštinom - misli vaše ne pokvare i odmetnu od iskrenosti prema Kristu.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (54, 11, 4, 'Uistinu, ako tko dođe i propovijeda drugog Isusa, kojega mi nismo propovijedali - ili ako drugoga Duha primate, kojega niste primili; ili drugo evanđelje, koje niste prigrlili - takva lijepo podnosÄite.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (54, 11, 5, 'Smatram, eto, da ni u čemu nisam manji od \"nadapostola\".');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (54, 11, 6, 'Jer ako sam i nevješt u govoru, nisam u znanju; naprotiv, u svemu vam ga i pred svima očitovasmo.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (54, 11, 7, 'Ili sam grijeh počinio što sam vam - ponizujući sebe da se vi uzvisite - besplatno navješćivao Božje evanđelje?');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (54, 11, 8, 'Druge sam crkve plijenio, od njih primao potporu da bih mogao vama služiti. I dok bijah u vas, premda u oskudici, nikomu nisam bio na teret.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (54, 11, 9, 'U oskudici su mi pomogla braća koja dođoše iz Makedonije. U svemu sam se čuvao da vam ne budem težak, a i čuvat ću se.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (54, 11, 10, 'Istine mi Kristove u meni, ove mi hvale nitko neće oduzeti u ahajskim krajevima.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (54, 11, 11, 'Zašto? Jer vas ne ljubim? Bog znade!');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (54, 11, 12, 'A što činim, i dalje ću činiti da izbijem izliku onima koji izliku traže ne bi li se s nama izjednačili u onom čime se hvastaju.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (54, 11, 13, 'Jer takvi su ljudi lažni apostoli, himbeni radnici, prerušuju se u apostole Kristove.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (54, 11, 14, 'I nikakvo čudo! Ta sam se Sotona prerušuje u anđela svjetla.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (54, 11, 15, 'Ništa osobito dakle ako se i službenici njegovi prerušuju u službenike pravednosti. Svršetak će im biti po djelima njihovim.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (54, 11, 16, 'Opet velim: da me tko ne bi smatrao bezumnim! Uostalom, primite me makar i kao bezumna da se i ja nešto malo pohvalim.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (54, 11, 17, 'Što govorim, ne govorim po Gospodnju, nego kao u bezumlju, u ovoj hvalisavoj smionosti.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (54, 11, 18, 'Budući da se mnogi hvale po ljudsku, i ja ću se hvaliti.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (54, 11, 19, 'Ta rado podnosÄite bezumne, vi umni!');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (54, 11, 20, 'Da, podnosÄite ako vas tko zarobljava, ako vas tko proždire, ako tko otima, ako se tko uznosi, ako vas tko po obrazu bije.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (54, 11, 21, 'Na sramotu govorim: bili smo, biva, slabi! Ipak, čime se god tko osmjeljuje - u bezumlju govorim - osmjeljujem se i ja!');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (54, 11, 22, 'Hebreji su? I ja sam! Izraelci su? I ja sam! Potomstvo su Abrahamovo? I ja sam!');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (54, 11, 23, 'Poslužitelji su Kristovi? Kao mahnit govorim: ja još više! U naporima - preobilno; u tamnicama - preobilno; u batinama - prekomjerno; u smrtnim pogiblima - često.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (54, 11, 24, 'Od Židova primio sam pet puta po četrdeset manje jednu.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (54, 11, 25, 'Triput sam bio šiban, jednom kamenovan, triput doživio brodolom, jednu noć i dan proveo sam u bezdanu.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (54, 11, 26, 'Česta putovanja, pogibli od rijeka, pogibli od razbojnika, pogibli od sunarodnjaka, pogibli od pogana, pogibli u gradu, pogibli u pustinji, pogibli na moru, pogibli od lažne braće;');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (54, 11, 27, 'u trudu i naporu, često u nespavanju, u gladu i žeđi, često u postovima, u studeni i golotinji!');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (54, 11, 28, 'Osim toga, uz drugo, salijetanje svakodnevno, briga za sve crkve.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (54, 11, 29, 'Tko je slab, a ja da ne budem slab? Tko se sablažnjuje, a ja da ne izgaram?');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (54, 11, 30, 'Treba li se hvaliti, svojom ću se slabošću hvaliti.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (54, 11, 31, 'Bog i Otac Gospodina Isusa, blagoslovljen u vijeke, zna da ne lažem.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (54, 11, 32, 'U Damasku namjesnik kralja Arete čuvaše grad damaščanski hoteći me uhvatiti.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (54, 11, 33, 'Ali kroz prozor spustiše me u košari preko zida te umakoh njegovim rukama.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (54, 12, 1, 'Hvaliti se treba? Ne koristi doduše ali - dolazim na viđenje i objave Gospodnje.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (54, 12, 2, 'Znam čovjeka u Kristu: prije četrnaest godina - da li u tijelu, ne znam; da li izvan tijela, ne znam, Bog zna - taj je bio ponesen do trećeg neba.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (54, 12, 3, 'I znam da je taj čovjek - da li u tijelu, da li izvan tijela, ne znam, Bog zna -');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (54, 12, 4, 'bio ponesen u raj i čuo neizrecive riječi, kojih čovjek ne smije govoriti.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (54, 12, 5, 'Time ću se hvaliti, a samim se sobom neću hvaliti osim slabostima svojim.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (54, 12, 6, 'Uistinu, kad bih se i htio hvaliti, ne bih bio bezuman; istinu bih govorio. Ali se uzdržavam da ne bi tko mislio o meni više nego što vidi na meni ili što čuje od mene.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (54, 12, 7, 'I da se zbog uzvišenosti objava ne bih uzoholio, dan mi je trn u tijelu, anđeo Sotonin, da me udara da se ne uzoholim.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (54, 12, 8, 'Za to sam triput molio Gospodina, da odstupi od mene. A on mi reče:');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (54, 12, 9, '\"Dosta ti je moja milost jer snaga se u slabosti usavršuje.\" Najradije ću se dakle još više hvaliti svojim slabostima da se nastani u meni snaga Kristova.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (54, 12, 10, 'Zato uživam u slabostima, uvredama, poteškoćama, progonstvima, tjeskobama poradi Krista. Jer kad sam slab, onda sam jak.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (54, 12, 11, 'Postao sam bezuman! Vi me natjeraste. Ta trebalo je da me vi preporučite jer ni u čemu nisam manji od \"nadapostola\", premda nisam ništa.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (54, 12, 12, 'Znamenja apostolstva moga ostvarena su među vama u posvemašnjoj postojanosti: znakovima i čudesima i silnim djelima.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (54, 12, 13, 'Ta u čemu ste to manji od drugih crkava, osim što vam ja nisam bio na teret? Oprostite mi ovu \"nepravdu\".');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (54, 12, 14, 'Evo, spremam se treći put doći k vama i neću vam biti na teret jer ne ištem vaše, nego vas. Djeca doista nisu dužna stjecati roditeljima, nego roditelji djeci.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (54, 12, 15, 'A ja ću najradije trošiti i istrošiti se za duše vaše. Ako vas više ljubim, zar da budem manje ljubljen?');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (54, 12, 16, 'Ali neka! Ja vas nisam opterećivao, nego, \"lukav\" kako jesam, \"na prijevaru vas uhvatih\".');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (54, 12, 17, 'Da vas možda nisam zakinuo po kome od onih koje poslah k vama?');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (54, 12, 18, 'Zamolio sam Tita i poslao s njime brata. Da vas možda Tit nije u čemu zakinuo? Zar nismo hodili u istom duhu? I istim stopama?');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (54, 12, 19, 'Odavna smatrate da se pred vama branimo. Pred Bogom u Kristu govorimo: sve je to, ljubljeni, za vaše izgrađivanje.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (54, 12, 20, 'Bojim se doista da vas kada dođem, možda neću naći kakve bih htio i da ćete vi mene naći kakva ne biste htjeli: da ne bi možda bilo svađa, zavisti, žestina, spletkarenja, klevetanja, došaptavanja, nadimanja, buna;');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (54, 12, 21, 'da me opet kada dođem, ne bi ponizio Bog moj kod vas kako ne bih morao oplakivati mnoge koji su prije sagriješili, a nisu se pokajali za nečistoću i bludnost i razvratnost koju počiniše.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (54, 13, 1, 'Evo treći put idem k vama. Svaka presuda neka počiva na iskazu dvojice ili trojice svjedoka.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (54, 13, 2, 'Onima koji su prije sagriješili i svima drugima rekoh već i opet - kao onda drugi put nazočan, tako i sada nenazočan - unaprijed velim: ako opet dođem, neću štedjeti.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (54, 13, 3, 'Jer vi tražite dokaz da u meni govori Krist koji prema vama nije nemoćan, nego je snažan među vama.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (54, 13, 4, 'I raspet bi, istina, po slabosti, ali živi po snazi Božjoj. I mi smo, istina, slabi u njemu, ali ćemo po snazi Božjoj živjeti s njime za vas.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (54, 13, 5, 'Same sebe ispitujte, jeste li u vjeri! Same sebe provjeravajte! Zar ne spoznajete sami sebe: da je Isus Krist u vama? Inače niste pravi.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (54, 13, 6, 'A spoznat ćete, nadam se, da smo mi pravi.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (54, 13, 7, 'Molimo se Bogu da ne činite nikakva zla; ne da se mi pokažemo pravi, nego da vi dobro činite, pa izašli mi i kao nepravi.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (54, 13, 8, 'Ta ništa ne možemo protiv istine, nego samo za istinu.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (54, 13, 9, 'Da, radujemo se kad smo mi slabi, a vi jaki. Za to se i molimo, za vaše usavršavanje.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (54, 13, 10, 'To vam nenazočan pišem zato da nazočan ne bih morao oštro nastupiti vlašću koju mi Gospodin dade za izgrađivanje, a ne za rušenje.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (54, 13, 11, 'Uostalom, braćo, radujte se, usavršujte se, tješite se, složni budite, mir njegujte i Bog ljubavi i mira bit će s vama.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (54, 13, 12, 'Pozdravite jedni druge svetim cjelovom. Pozdravljaju vas svi sveti.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (54, 13, 13, 'Milost Gospodina Isusa Krista, ljubav Boga i zajedništvo Duha Svetoga sa svima vama!');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (55, 1, 1, 'Pavao, apostol - ne od ljudi ni po kojem čovjeku, nego po Isusu Kristu i Bogu Ocu koji ga uskrisi od mrtvih -');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (55, 1, 2, 'i sva braća koja su sa mnom: Crkvama u Galaciji.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (55, 1, 3, 'Milost vam i mir od Boga, Oca našega, i Gospodina Isusa Krista,');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (55, 1, 4, 'koji sam sebe dade za grijehe naše da nas istrgne iz sadašnjega svijeta opakoga kao što je volja Boga i Oca našega,');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (55, 1, 5, 'komu slava u vijeke vjekova! Amen.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (55, 1, 6, 'Čudim se da od Onoga koji vas pozva na milost Kristovu tako brzo prelazite na neko drugo evanđelje,');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (55, 1, 7, 'koje uostalom i ne postoji. Postoje samo neki koji vas zbunjuju i hoće prevratiti evanđelje Kristovo.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (55, 1, 8, 'Ali kad bismo vam mi, ili kad bi vam anđeo s neba navješćivao neko evanđelje mimo onoga koje vam mi navijestismo, neka je proklet!');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (55, 1, 9, 'Što smo već rekli, to sad i ponavljam: navješćuje li vam tko neko evanđelje mimo onoga koje primiste, neka je proklet.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (55, 1, 10, 'Doista, nastojim li ovo pridobiti ljude ili Boga? Ili idem li za tim da ljudima ugodim? Kad bih sveudilj nastojao ljudima ugađati, ne bih bio Kristov sluga.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (55, 1, 11, 'Obznanjujem vam, braćo: evanđelje koje sam navješćivao nije od ljudi,');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (55, 1, 12, 'niti ga ja od kojeg čovjeka primih ili naučih, nego objavom Isusa Krista.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (55, 1, 13, 'Ta čuli ste za moje negdašnje ponašanje u židovstvu: preko svake sam mjere progonio i pustošio Crkvu Božju');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (55, 1, 14, 'te sam u židovstvu, prerevno odan otačkim predajama, nadmašio mnoge vršnjake u svojem narodu.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (55, 1, 15, 'Ali kad se Onomu koji me odvoji već od majčine utrobe i pozva milošću svojom, svidjelo');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (55, 1, 16, 'otkriti mi Sina svoga da ga navješćujem među poganima, odmah, ne posavjetovah se s tijelom i krvlju');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (55, 1, 17, 'i ne uziđoh u Jeruzalem k onima koji bijahu apostoli prije mene, nego odoh u Arabiju pa se opet vratih u Damask.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (55, 1, 18, 'Onda nakon tri godine uziđoh u Jeruzalem potražiti Kefu i ostadoh kod njega petnaest dana.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (55, 1, 19, 'Od apostola ne vidjeh nikoga drugog osim Jakova, brata Gospodinova.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (55, 1, 20, 'Što vam pišem, Bog mi je svjedok, ne lažem.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (55, 1, 21, 'Zatim dođoh u krajeve sirijske i cilicijske.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (55, 1, 22, 'Osobno pak bijah nepoznat Kristovim crkvama u Judeji.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (55, 1, 23, 'One su samo čule: \"Negdašnji naš progonitelj sada navješćuje vjeru koju je nekoć pustošio\"');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (55, 1, 24, 'i slavile su Boga zbog mene.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (55, 2, 1, 'Zatim nakon četrnaest godina opet uziđoh u Jeruzalem s Barnabom, a povedoh sa sobom i Tita.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (55, 2, 2, 'Uziđoh po objavi i izložih im - napose uglednijima - evanđelje koje propovijedam među poganima da ne bih možda, ili da nisam, trčao uzalud.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (55, 2, 3, 'Čak ni Tit, pratilac moj, premda Grk, nije bio prisiljen obrezati se,');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (55, 2, 4, 'i to radi uljeza, lažne braće, koja se ušuljaše da vrebaju slobodu koju imamo u Kristu Isusu, ne bi li nas učinili robovima.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (55, 2, 5, 'Ne, ni načas im nismo popustili, nismo se podložili: da istina evanđelja ostane kod vas!');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (55, 2, 6, 'A oni koji štogod znače - bili oni što bili, nije mi do toga, Bog ne gleda tko je tko - ti uglednici, uistinu, ništa nisu pridometnuli.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (55, 2, 7, 'Nego naprotiv, vidjevši da mi je povjereno evanđelje za neobrezane, kao Petru za obrezane -');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (55, 2, 8, 'jer Onaj koji je bio na djelu po Petrovu apostolstvu među obrezanima, bio je na djelu i po meni među poganima -');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (55, 2, 9, 'i spoznavši milost koja mi je dana, Jakov, Kefa i Ivan, smatrani stupovima, pružiše meni i Barnabi desnice zajedništva: mi ćemo među pogane, a oni među obrezane!');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (55, 2, 10, 'Samo neka se sjećamo siromaha, što sam revno i činio.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (55, 2, 11, 'A kad Kefa stiže u Antiohiju, u lice mu se usprotivih jer je zavrijedio osudu:');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (55, 2, 12, 'doista, prije nego stigoše neki od Jakova, blagovao je zajedno s poganima; a kad oni dođoše, počeo se povlačiti i odvajati bojeći se onih iz obrezanja.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (55, 2, 13, 'Za njim se povedoše i ostali Židovi te je i Barnaba zaveden tom prijetvornošću.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (55, 2, 14, 'Ali kad vidjeh da ne hode ravno, po istini evanđelja, rekoh Kefi pred svima: \"Ako ti, Židov, poganski živiš, a ne židovski, kako možeš siliti pogane da se požidove?\"');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (55, 2, 15, 'Mi smo podrijetlom Židovi, a ne \"grešnici iz poganstva\".');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (55, 2, 16, 'Ali znamo: čovjek se ne opravdava po djelima Zakona, nego vjerom u Isusa Krista. Zato i mi u Krista Isusa povjerovasmo da se opravdamo po vjeri u Krista, a ne po djelima Zakona jer se po djelima Zakona nitko neće opravdati.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (55, 2, 17, 'Ako se pak po tome što zaiskasmo opravdati se u Kristu očitovalo da smo i mi grešnici, nije li onda Krist u službi grijeha? Nipošto!');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (55, 2, 18, 'Doista, ako ponovno gradim što sam bio srušio, pokazujem da sam prijestupnik.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (55, 2, 19, 'Ta po Zakonu ja Zakonu umrijeh da Bogu živim. S Kristom sam razapet.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (55, 2, 20, 'Živim, ali ne više ja, nego živi u meni Krist. A što sada živim u tijelu, u vjeri živim u Sina Božjega koji me ljubio i predao samoga sebe za mene.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (55, 2, 21, 'Ne dokidam milosti Božje! Doista, ako je opravdanje po Zakonu, onda je Krist uzalud umro.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (55, 3, 1, 'O bezumni Galaćani, tko li vas opčara? A pred očima vam je Isus Krist bio ocrtan kao Raspeti.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (55, 3, 2, 'Ovo bih samo htio doznati od vas: jeste li primili Duha po djelima Zakona ili po vjeri u Poruku?');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (55, 3, 3, 'Tako li ste bezumni? Započeli ste u Duhu pa da sada u tijelu dovršite?');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (55, 3, 4, 'Zar ste toliko toga uzalud doživjeli? A kad bi doista bilo uzalud!');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (55, 3, 5, 'Onaj dakle koji vam daje Duha i čini među vama silna djela, čini li to zbog djela Zakona ili zbog vjere u Poruku?');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (55, 3, 6, 'Tako Abraham povjerova Bogu i uračuna mu se u pravednost.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (55, 3, 7, 'Shvatite dakle: oni od vjere, to su sinovi Abrahamovi.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (55, 3, 8, 'A Pismo, predvidjevši da Bog po vjeri opravdava pogane, unaprijed navijesti Abrahamu: U tebi će blagoslovljeni biti svi narodi.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (55, 3, 9, 'Tako: oni od vjere blagoslivlju se s vjernikom Abrahamom.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (55, 3, 10, 'Doista, koji su god od djela Zakona, pod prokletstvom su. Ta pisano je: Proklet tko se god ne drži i tko ne vrši svega što je napisano u Knjizi Zakona.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (55, 3, 11, 'A da se pred Bogom nitko ne opravdava Zakonom, očito je jer: Pravednik će od vjere živjeti.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (55, 3, 12, 'Zakon pak nije od vjere, nego veli: Tko ga vrši, u njemu će naći život.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (55, 3, 13, 'Krist nas otkupi od prokletstva Zakona, postavši za nas prokletstvom - jer pisano je: Proklet je tko god visi na drvetu -');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (55, 3, 14, 'da u Kristu Isusu na pogane dođe blagoslov Abrahamov: da Obećanje, Duha, primimo po vjeri.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (55, 3, 15, 'Braćo, po ljudsku govorim: već i ljudski valjan savez nitko ne poništava niti mu što dodaje.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (55, 3, 16, 'A ova su obećanja dana Abrahamu i potomstvu njegovu. Ne veli se: \"i potomcima\" kao o mnogima, nego kao o jednomu: I potomstvu tvojem, to jest Kristu.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (55, 3, 17, 'Ovo hoću kazati: Saveza koji je Bog valjano sklopio ne obeskrepljuje Zakon, koji je nastao četiri stotine i trideset godina poslije, i ne dokida obećanja.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (55, 3, 18, 'Doista, ako se baština zadobiva po Zakonu, ne zadobiva se po obećanju. A Abrahama je Bog po obećanju obdario.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (55, 3, 19, 'Čemu onda Zakon? Dometnut je poradi prekršaja dok ne dođe potomstvo komu je namijenjeno obećanje; sastavljen je po anđelima preko posrednika.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (55, 3, 20, 'Posrednika pak nema gdje je samo jedan. A Bog je jedan.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (55, 3, 21, 'Zar je dakle Zakon protiv obećanja Božjih? Nipošto! Jer da je dan Zakon koji bi mogao oživljavati, pravednost bi doista proizlazila iz Zakona.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (55, 3, 22, 'Ali je Pismo sve zatvorilo pod grijeh da se, po vjeri u Isusa Krista, obećano dade onima koji vjeruju.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (55, 3, 23, 'Prije dolaska vjere, pod Zakonom zatvoreni, bili smo čuvani za vjeru koja se imala objaviti.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (55, 3, 24, 'Tako nam je Zakon bio nadzirateljem sve do Krista da se po vjeri opravdamo.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (55, 3, 25, 'A otkako je nadošla vjera, nismo više pod nadzirateljem.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (55, 3, 26, 'Uistinu, svi ste sinovi Božji, po vjeri u Kristu Isusu.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (55, 3, 27, 'Doista, koji ste god u Krista kršteni, Kristom se zaodjenuste.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (55, 3, 28, 'Nema više: Židov - Grk! Nema više: rob - slobodnjak! Nema više: muško - žensko! Svi ste vi Jedan u Kristu Isusu!');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (55, 3, 29, 'Ako li ste Kristovi, onda ste Abrahamovo potomstvo, baštinici po obećanju.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (55, 4, 1, 'Hoću reći: sve dok je baštinik maloljetan, ništa se ne razlikuje od roba premda je gospodar svega:');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (55, 4, 2, 'pod skrbnicima je i upraviteljima sve do dana koji je odredio otac.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (55, 4, 3, 'Tako i mi: dok bijasmo maloljetni, robovasmo počelima svijeta.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (55, 4, 4, 'A kada dođe punina vremena, odasla Bog Sina svoga: od žene bi rođen, Zakonu podložan');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (55, 4, 5, 'da podložnike Zakona otkupi te primimo posinstvo.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (55, 4, 6, 'A budući da ste sinovi, odasla Bog u srca vaša Duha Sina svoga koji kliče: \"Abba! Oče!\"');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (55, 4, 7, 'Tako više nisi rob nego sin; ako pak sin, onda i baštinik po Bogu.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (55, 4, 8, 'Onda dok još niste poznavali Boga, služili ste bogovima koji po naravi to nisu.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (55, 4, 9, 'Ali sada kad ste spoznali Boga - zapravo, kad je Bog spoznao vas - kako se sad opet vraćate k nemoćnim i bijednim počelima i opet im, ponovno, hoćete robovati?');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (55, 4, 10, 'Dane pomno opslužujete, i mjesece, i vremena, i godine!');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (55, 4, 11, 'Sve se bojim za vas! Da se možda nisam uzalud trudio oko vas!');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (55, 4, 12, 'Postanite, braćo, molim vas, kao ja jer i ja postadoh kao vi. Ničim me niste povrijedili.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (55, 4, 13, 'Znate: prvi sam vam put za bolesti navješćivao evanđelje.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (55, 4, 14, 'Svoju kušnju, moje tijelo, niste ni prezreli ni odbacili, nego ste me primili kao anđela Božjega, kao Krista Isusa.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (55, 4, 15, 'Gdje je sada ono vaše blaženstvo? Svjedočim vam doista: kad bi bilo moguće, oči biste svoje bili iskopali i dali mi ih.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (55, 4, 16, 'Tako? Postadoh li vam neprijateljem propovijedajući vam istinu?');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (55, 4, 17, 'Oni revnuju za vas, ne časno, nego - odvojiti vas hoće da onda vi za njih revnujete.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (55, 4, 18, 'Dobro je da se za vas revnuje u dobru uvijek, a ne samo kad sam nazočan kod vas,');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (55, 4, 19, 'dječice moja, koju ponovno u trudovima rađam dok se Krist ne oblikuje u vama.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (55, 4, 20, 'Htio bih sada biti kod vas, pa i jezik promijeniti, jer ne znam što bih s vama.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (55, 4, 21, 'Recite mi vi, koji želite biti pod Zakonom, zar ne čujete Zakona?');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (55, 4, 22, 'Ta pisano je da je Abraham imao dva sina, jednoga od ropkinje i jednoga od slobodne.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (55, 4, 23, 'Ali onaj od ropkinje rođen je po tijelu, a onaj od slobodne snagom obećanja.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (55, 4, 24, 'To je slika. Doista, te žene dva su Saveza: jedan s brda Sinaja, koji rađa za ropstvo - to je Hagara.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (55, 4, 25, 'Jer Hagara znači brdo Sinaj u Arabiji i odgovara sadašnjem Jeruzalemu jer robuje zajedno sa svojom djecom.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (55, 4, 26, 'Onaj pak Jeruzalem gore slobodan je; on je majka naša.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (55, 4, 27, 'Pisano je doista: Kliči, nerotkinjo, koja ne rađaš, podvikuj od radosti, ti što ne znaš za trudove! Jer osamljena više djece ima negoli udana.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (55, 4, 28, 'Vi ste, braćo, kao Izak, djeca obećanja.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (55, 4, 29, 'I kao što je onda onaj po tijelu rođeni progonio onoga po duhu rođenoga, tako je i sada.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (55, 4, 30, 'Nego, što veli Pismo? Otjeraj sluškinju i sina njezina jer sin sluškinje ne smije biti baštinik sa sinom slobodne.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (55, 4, 31, 'Zato, braćo, nismo djeca ropkinje nego slobodne.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (55, 5, 1, 'Za slobodu nas Krist oslobodi! Držite se dakle i ne dajte se ponovno u jaram ropstva!');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (55, 5, 2, 'Evo ja, Pavao, velim vam: ako se obrežete, Krist vam ništa neće koristiti.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (55, 5, 3, 'I ponovno jamčim svakom čovjeku koji se obreže: dužan je opsluživati sav Zakon.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (55, 5, 4, 'Prekinuli ste s Kristom vi koji se u Zakonu mislite opravdati; iz milosti ste ispali.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (55, 5, 5, 'Jer mi po Duhu iz vjere očekujemo pravednost, nadu svoju.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (55, 5, 6, 'Uistinu, u Kristu Isusu ništa ne vrijedi ni obrezanje ni neobrezanje, nego - vjera ljubavlju djelotvorna.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (55, 5, 7, 'Dobro ste trčali; tko li vas je samo spriječio da se više ne pokoravate istini?');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (55, 5, 8, 'Ta pobuda nije od Onoga koji vas zove!');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (55, 5, 9, 'Malo kvasca cijelo tijesto ukvasa.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (55, 5, 10, 'Ja se uzdam u vas u Gospodinu: vi nećete drukčije misliti. A tko vas zbunjuje, snosit će osudu, tko god bio.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (55, 5, 11, 'A ja, braćo, ako sveudilj propovijedam obrezanje, zašto me sveudilj progone? Onda je obeskrijepljena sablazan križa!');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (55, 5, 12, 'Uškopili se oni koji vas podbunjuju!');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (55, 5, 13, 'Doista vi ste, braćo, na slobodu pozvani! Samo neka ta sloboda ne bude izlikom tijelu, nego - ljubavlju služite jedni drugima.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (55, 5, 14, 'Ta sav je Zakon ispunjen u jednoj jedinoj riječi, u ovoj: Ljubi bližnjega svoga kao sebe samoga!');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (55, 5, 15, 'Ako li pak jedni druge grizete i glođete, pazite da jedni druge ne proždrete.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (55, 5, 16, 'Hoću reći: po Duhu živite pa nećete ugađati požudi tijela!');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (55, 5, 17, 'Jer tijelo žudi protiv Duha, a Duh protiv tijela. Doista, to se jedno drugomu protivi da ne činite što hoćete.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (55, 5, 18, 'Ali ako vas Duh vodi, niste pod Zakonom.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (55, 5, 19, 'A očita su djela tijela. To su: bludnost, nečistoća, razvratnost,');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (55, 5, 20, 'idolopoklonstvo, vračanje, neprijateljstva, svađa, ljubomor, srdžbe, spletkarenja, razdori, strančarenja,');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (55, 5, 21, 'zavisti, pijančevanja, pijanke i tome slično. Unaprijed vam kažem, kao što vam već rekoh: koji takvo što čine, kraljevstva Božjega neće baštiniti.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (55, 5, 22, 'Plod je pak Duha: ljubav, radost, mir, velikodušnost, uslužnost, dobrota, vjernost,');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (55, 5, 23, 'blagost, uzdržljivost. Protiv tih nema zakona.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (55, 5, 24, 'Koji su Kristovi, razapeše tijelo sa strastima i požudama.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (55, 5, 25, 'Ako živimo po Duhu, po Duhu se i ravnajmo!');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (55, 5, 26, 'Ne hlepimo za taštom slavom! Ne izazivajmo jedni druge, ne zaviđajmo jedni drugima!');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (55, 6, 1, 'Braćo, ako se tko i zatekne u kakvu prijestupu, vi, duhovni, takva ispravljajte u duhu blagosti. A pazi na samoga sebe da i ti ne podlegneš napasti.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (55, 6, 2, 'Nosite jedni bremena drugih i tako ćete ispuniti zakon Kristov!');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (55, 6, 3, 'Jer misli li tko da jest štogod, a nije ništa, sam sebe vara.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (55, 6, 4, 'Svatko neka ispita sam svoje djelo pa će onda u samom sebi imati čime se dičiti, a ne u usporedbi s drugim.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (55, 6, 5, 'Ta svatko će nositi svoj teret.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (55, 6, 6, 'Koji se uči Riječi, neka sva dobra dijeli sa svojim učiteljem.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (55, 6, 7, 'Ne varajte se: Bog se ne da izrugivati! Što tko sije, to će i žeti!');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (55, 6, 8, 'Doista, tko sije u tijelo svoje, iz tijela će žeti raspadljivost, a tko sije u duh, iz duha će žeti život vječni.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (55, 6, 9, 'Neka nam ne dozlogrdi činiti dobro: ako ne sustanemo, u svoje ćemo vrijeme žeti!');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (55, 6, 10, 'Dakle, dok imamo vremena, činimo dobro svima, ponajpače domaćima u vjeri.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (55, 6, 11, 'Gledajte kolikim vam slovima pišem svojom rukom.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (55, 6, 12, 'Svi koji se hoće praviti važni tijelom, sile vas na obrezanje, samo da zbog križa Kristova ne bi trpjeli progonstvo.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (55, 6, 13, 'Ta ni sami obrezani ne opslužuju Zakona, ali hoće da se vi obrežete da bi se mogli ponositi vašim tijelom.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (55, 6, 14, 'A ja, Bože sačuvaj da bih se ičim ponosio osim križem Gospodina našega Isusa Krista po kojem je meni svijet raspet i ja svijetu.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (55, 6, 15, 'Uistinu, niti je što obrezanje niti neobrezanje, nego - novo stvorenje.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (55, 6, 16, 'A na sve koji se ovoga pravila budu držali, i na sveg Izraela Božjega - mir i milosrđe!');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (55, 6, 17, 'Ubuduće neka mi nitko ne dodijava jer ja na svom tijelu nosim biljege Isusove!');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (55, 6, 18, 'Milost Gospodina našega Isusa Krista s duhom vašim, braćo! Amen');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (56, 1, 1, 'Pavao, po volji Božjoj apostol Krista Isusa: svetima koji su u Efezu i vjernima u Isusu Kristu.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (56, 1, 2, 'Milost vam i mir od Boga, Oca našega, i Gospodina Isusa Krista!');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (56, 1, 3, 'Blagoslovljen Bog i Otac Gospodina našega Isusa Krista, on koji nas blagoslovi svakim blagoslovom duhovnim u nebesima, u Kristu.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (56, 1, 4, 'Tako: u njemu nas sebi izabra prije postanka svijeta da budemo sveti i bez mane pred njim;');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (56, 1, 5, 'u ljubavi nas predodredi za posinstvo, za sebe, po Isusu Kristu, dobrohotnošću svoje volje,');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (56, 1, 6, 'na hvalu Slave svoje milosti. Njome nas zamilova u Ljubljenome');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (56, 1, 7, 'u kome, njegovom krvlju, imamo otkupljenje, otpuštenje prijestupa po bogatstvu njegove milosti.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (56, 1, 8, 'Nju preobilno u nas uli zajedno sa svom mudrošću i razumijevanjem');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (56, 1, 9, 'obznanivši nam otajstvo svoje volje po dobrohotnom naumu svojem što ga prije u njemu zasnova');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (56, 1, 10, 'da se provede punina vremena: uglaviti u Kristu sve - na nebesima i na zemlji.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (56, 1, 11, 'U njemu, u kome i nama - predodređenima po naumu Onoga koji sve izvodi po odluci svoje volje - u dio pade');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (56, 1, 12, 'da budemo na hvalu Slave njegove - mi koji smo se već prije nadali u Kristu.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (56, 1, 13, 'U njemu ste i vi, pošto ste čuli Riječ istine - evanđelje spasenja svoga - u njemu ste, prigrlivši vjeru, opečaćeni Duhom obećanim, Svetim,');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (56, 1, 14, 'koji je zalog naše baštine: otkupljenja, posvojenja - na hvalu Slave njegove.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (56, 1, 15, 'Zato i ja, otkad sam čuo za vašu vjeru u Gospodinu Isusu i za ljubav prema svima svetima,');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (56, 1, 16, 'ne prestajem zahvaljivati za vas i sjećati vas se u svojim molitvama:');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (56, 1, 17, 'Bog Gospodina našega Isusa Krista, Otac Slave, dao vam Duha mudrosti i objave kojom ćete ga spoznati;');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (56, 1, 18, 'prosvijetlio vam oči srca da upoznate koje li nade u pozivu njegovu, koje li bogate slave u baštini njegovoj među svetima');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (56, 1, 19, 'i koje li prekomjerne veličine u moći njegovoj prema nama koji vjerujemo: ona je primjerena djelotvornosti sile i snage njegove');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (56, 1, 20, 'koju na djelu pokaza u Kristu, kad ga uskrisi od mrtvih i posjede sebi zdesna na nebesima');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (56, 1, 21, 'iznad svakog Vrhovništva i Vlasti i Moći i Gospodstva i svakog imena imenovana ne samo na ovom svijetu nego i u budućemu.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (56, 1, 22, 'Sve mu podloži pod noge, a njega postavi - nad svime - Glavom Crkvi,');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (56, 1, 23, 'koja je Tijelo njegovo, punina Onoga koji sve u svima ispunja.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (56, 2, 1, 'I vi bijaste mrtvi zbog prijestupa i grijeha');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (56, 2, 2, 'u kojima ste nekoć živjeli po Eonu ovoga svijeta, po Knezu vlasti zraka, po tomu duhu koji sada djeluje u sinovima neposlušnima.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (56, 2, 3, 'Među njima smo i mi nekoć živjeli u požudama tijela svoga, udovoljavajući prohtjevima tijela i ćudi, te po naravi bijasmo djeca gnjeva kao i drugi.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (56, 2, 4, 'Ali Bog, bogat milosrđem, zbog velike ljubavi kojom nas uzljubi,');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (56, 2, 5, 'nas koji bijasmo mrtvi zbog prijestupa, oživi zajedno s Kristom - milošću ste spašeni! -');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (56, 2, 6, 'te nas zajedno s njim uskrisi i posadi na nebesima u Kristu Isusu:');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (56, 2, 7, 'da u dobrohotnosti prema nama u Kristu Isusu pokaže budućim vjekovima preobilno bogatstvo milosti svoje.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (56, 2, 8, 'Ta milošću ste spašeni po vjeri! I to ne po sebi! Božji je to dar!');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (56, 2, 9, 'Ne po djelima, da se ne bi tko hvastao.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (56, 2, 10, 'Njegovo smo djelo, stvoreni u Kristu Isusu za dobra djela, koja Bog unaprijed pripravi da u njima živimo.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (56, 2, 11, 'Spominjite se stoga da nekoć bijaste neznabošci u tijelu - neobrezanicima su vas zvali oni koji se zovu obrezani, rukom, na tijelu -');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (56, 2, 12, 'i da u ono vrijeme bijaste izvan Krista, udaljeni od građanstva izraelskoga, tuđi Savezima obećanja, bez nade bijaste i neznabošci na svijetu.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (56, 2, 13, 'Sada pak, u Kristu Isusu, vi koji nekoć bijaste daleko, dođoste blizu - po Krvi Kristovoj.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (56, 2, 14, 'Doista, on je mir naš, on koji od dvoga učini jedno: pregradu razdvojnicu, neprijateljstvo razori u svome tijelu.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (56, 2, 15, 'Zakon zapovijedi s propisima obeskrijepi da u sebi, uspostavljajući mir, od dvojice sazda jednoga novog čovjeka');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (56, 2, 16, 'te obojicu u jednome Tijelu izmiri s Bogom po križu, ubivši u sebi neprijateljstvo.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (56, 2, 17, 'I dođe te navijesti mir vama daleko i mir onima blizu,');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (56, 2, 18, 'jer po njemu jedni i drugi u jednome Duhu imamo pristup Ocu.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (56, 2, 19, 'Tako dakle više niste tuđinci ni pridošlice, nego sugrađani ste svetih i ukućani Božji');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (56, 2, 20, 'nazidani na temelju apostola i proroka, a zaglavni je kamen sam Krist Isus.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (56, 2, 21, 'U njemu je sva građevina povezana i raste u hram svet u Gospodinu.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (56, 2, 22, 'U njemu ste i vi ugrađeni u prebivalište Božje u Duhu.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (56, 3, 1, 'Radi toga ja, Pavao, sužanj Krista Isusa za vas pogane...');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (56, 3, 2, 'Zacijelo ste čuli za rasporedbu milosti Božje koja mi je dana za vas:');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (56, 3, 3, 'objavom mi je obznanjeno otajstvo, kako netom ukratko opisah.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (56, 3, 4, 'Čitajući to, možete dokučiti kako ja shvaćam Kristovo otajstvo,');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (56, 3, 5, 'koje nije bilo obznanjeno sinovima ljudskim drugih naraštaja. Ono je sada u Duhu objavljeno svetim njegovim apostolima i prorocima:');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (56, 3, 6, 'da su pogani subaštinici i \"sutijelo\" i sudionici obećanja u Kristu Isusu - po evanđelju,');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (56, 3, 7, 'kojega postadoh poslužiteljem darom milosti Božje koja mi je dana djelotvornošću snage njegove.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (56, 3, 8, 'Meni, najmanjemu od svih svetih, dana je ova milost: poganima biti blagovjesnikom neistraživog bogatstva Kristova');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (56, 3, 9, 'i osvijetliti rasporedbu otajstva, pred vjekovima skrivena u Bogu, koji sve stvori,');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (56, 3, 10, 'da sada - po Crkvi - Vrhovništvima i Vlastima na nebesima bude obznanjena mnogolika mudrost Božja');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (56, 3, 11, 'zasnovana - po naumu o vjekovima - u Kristu Isusu Gospodinu našemu.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (56, 3, 12, 'U njemu, s pouzdanjem po vjeri u njega, imamo slobodan pristup.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (56, 3, 13, 'Zato ne klonite, molim, s nevolja mojih za vas! One su slava vaša!');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (56, 3, 14, 'Zato prigibam koljena pred Ocem,');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (56, 3, 15, 'od koga ime svakom očinstvu na nebu i na zemlji:');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (56, 3, 16, 'neka vam dadne po bogatstvu Slave svoje ojačati se po Duhu njegovu u snazi za unutarnjeg čovjeka');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (56, 3, 17, 'da po vjeri Krist prebiva u srcima vašim te u ljubavi ukorijenjeni i utemeljeni');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (56, 3, 18, 'mognete shvatiti sa svima svetima što je Dužina i Širina i Visina i Dubina');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (56, 3, 19, 'te spoznati nadspoznatljivu ljubav Kristovu da se ispunite do sve Punine Božje.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (56, 3, 20, 'Onomu pak koji snagom u nama djelatnom može učiniti mnogo izobilnije nego li mi moliti ili zamisliti -');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (56, 3, 21, 'Njemu slava u Crkvi i u Kristu Isusu za sva pokoljenja vijeka vjekovječnoga! Amen.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (56, 4, 1, 'Zaklinjem vas dakle ja, sužanj u Gospodinu: sa svom poniznošću i blagošću, sa strpljivošću živite dostojno poziva kojim ste pozvani!');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (56, 4, 2, 'Podnosite jedni druge u ljubavi;');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (56, 4, 3, 'trudite se sačuvati jedinstvo Duha svezom mira!');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (56, 4, 4, 'Jedno tijelo i jedan Duh - kao što ste i pozvani na jednu nadu svog poziva!');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (56, 4, 5, 'Jedan Gospodin! Jedna vjera! Jedan krst!');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (56, 4, 6, 'Jedan Bog i Otac sviju, nad svima i po svima i u svima!');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (56, 4, 7, 'A svakomu je od nas dana milost po mjeri dara Kristova.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (56, 4, 8, 'Zato veli: Na visinu uzađe vodeći sužnje, dade dare ljudima.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (56, 4, 9, 'Ono \"uzađe\" - što drugo znači doli to da i siđe u donje krajeve, na zemlju?');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (56, 4, 10, 'Koji siđe, isti je onaj koji i uzađe ponad svih nebesa da sve ispuni.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (56, 4, 11, 'On i \"dade\" jedne za apostole, druge za proroke, jedne opet za evanđeliste, a druge za pastire i učitelje');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (56, 4, 12, 'da opremi svete za djelo služenja, za izgrađivanje Tijela Kristova');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (56, 4, 13, 'dok svi ne prispijemo do jedinstva vjere i spoznaje Sina Božjega, do čovjeka savršena, do mjere uzrasta punine Kristove:');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (56, 4, 14, 'da više ne budemo nejačad kojom se valovi poigravaju i koje goni svaki vjetar nauka u ovom kockanju ljudskom, u lukavosti što put krči zabludi.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (56, 4, 15, 'Nego, istinujući u ljubavi da poradimo te sve uzraste u Njega, koji je Glava, Krist,');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (56, 4, 16, 'od kojega sve Tijelo, usklađeno i povezano svakovrsnim zglobom zbrinjavanja po djelotvornosti primjerenoj svakomu pojedinom dijelu, promiče svoj rast na saziđivanje u ljubavi.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (56, 4, 17, 'Ovo govorim i zaklinjem u Gospodinu: ne živite više kao što pogani žive - u ispraznosti pameti njihove:');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (56, 4, 18, 'zamračena uma, udaljeni od života Božjega, sve zbog neznanja koje je u njima, zbog okorjelosti srca njihova.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (56, 4, 19, 'Sami su sebe otupili i podali se razvratnosti da bi u pohlepi počinjali svaku nečistoću.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (56, 4, 20, 'Vi pak ne naučiste tako Krista,');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (56, 4, 21, 'ako ste ga doista čuli i u njemu bili poučeni kako je istina u Isusu:');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (56, 4, 22, 'da vam je odložiti prijašnje ponašanje, starog čovjeka, koga varave požude vode u propast,');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (56, 4, 23, 'a obnavljati se duhom svoje pameti');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (56, 4, 24, 'i obući novog čovjeka, po Bogu stvorena u pravednosti i svetosti istine.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (56, 4, 25, 'Zato odložite laž i govorite istinu jedan drugomu jer udovi smo jedni drugima.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (56, 4, 26, 'Srdite se, ali ne griješite! Sunce nek ne zađe nad vašom srdžbom');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (56, 4, 27, 'i ne dajite mjesta đavlu.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (56, 4, 28, 'Tko je krao, neka više ne krade, nego neka se radije trudi svojim rukama priskrbljivati da ima što podijeliti s potrebnim.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (56, 4, 29, 'Nikakva nevaljala riječ neka ne izlazi iz vaših usta, nego samo dobra, da prema potrebi saziđuje i milost iskaže slušateljima.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (56, 4, 30, 'I ne žalostite Duha Svetoga, Božjega, kojim ste opečaćeni za Dan otkupljenja!');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (56, 4, 31, 'Daleko od vas svaka gorčina, i srdžba, i gnjev, i vika, i hula sa svom opakošću!');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (56, 4, 32, 'Naprotiv! Budite jedni drugima dobrostivi, milosrdni; praštajte jedni drugima kao što i Bog u Kristu nama oprosti.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (56, 5, 1, 'Budite dakle nasljedovatelji Božji kao djeca ljubljena');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (56, 5, 2, 'i hodite u ljubavi kao što je i Krist ljubio vas i sebe predao za nas kao prinos i žrtvu Bogu na ugodan miris.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (56, 5, 3, 'A bludnost i svaka nečistoća ili pohlepa neka se i ne spominje među vama, kako dolikuje svetima!');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (56, 5, 4, 'Ni prostota, ni ludorija, ni dvosmislica, što se ne priliči, nego radije zahvaljivanje!');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (56, 5, 5, 'Jer dobro znajte ovo: nijedan bludnik, ili bestidnik, ili pohlepnik - taj idolopoklonik - nema baštine u kraljevstvu Kristovu i Božjemu.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (56, 5, 6, 'Nitko neka vas ispraznim riječima ne zavarava: zbog toga dolazi gnjev Božji na sinove neposlušne.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (56, 5, 7, 'Nemajte dakle ništa s njima!');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (56, 5, 8, 'Da, nekoć bijaste tama, a sada ste svjetlost u Gospodinu: kao djeca svjetlosti hodite -');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (56, 5, 9, 'plod je svjetlosti svaka dobrota, pravednost i istina -');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (56, 5, 10, 'i odlučite se za ono što je milo Gospodinu.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (56, 5, 11, 'A nemajte udjela u jalovim djelima tame, nego ih dapače raskrinkavajte,');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (56, 5, 12, 'jer što potajno čine, sramota je i govoriti.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (56, 5, 13, 'A sve što se raskrinka, pod svjetlošću postaje sjajno; što je pak sjajno, svjetlost je.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (56, 5, 14, 'Zato veli: \"Probudi se, ti što spavaš, ustani od mrtvih i zasvijetljet će ti Krist.\"');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (56, 5, 15, 'Razmotrite dakle pomno kako živite! Ne kao ludi, nego kao mudri!');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (56, 5, 16, 'Iskupljujte vrijeme jer dani su zli!');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (56, 5, 17, 'Zato ne budite nerazumni, nego shvatite što je volja Gospodnja!');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (56, 5, 18, 'I ne opijajte se vinom u kojem je razuzdanost, nego - punite se Duhom!');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (56, 5, 19, 'Razgovarajte među sobom psalmima, hvalospjevima i duhovnim pjesmama! Pjevajte i slavite Gospodina u svom srcu!');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (56, 5, 20, 'Svagda i za sve zahvaljujte Bogu i Ocu u imenu Gospodina našega Isusa Krista!');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (56, 5, 21, 'Podložni budite jedni drugima u strahu Kristovu!');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (56, 5, 22, 'Žene svojim muževima kao Gospodinu!');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (56, 5, 23, 'Jer muž je glava žene kao i Krist Glava Crkve - On, Spasitelj Tijela.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (56, 5, 24, 'Pa kao što se Crkva podlaže Kristu, tako i žene muževima u svemu!');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (56, 5, 25, 'Muževi, ljubite svoje žene kao što je Krist ljubio Crkvu te sebe predao za nju');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (56, 5, 26, 'da je posveti, očistivši je kupelji vode uz riječ');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (56, 5, 27, 'te sebi predvede Crkvu slavnu, bez ljage i nabora ili čega takva, nego da bude sveta i bez mane.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (56, 5, 28, 'Tako treba da i muževi ljube svoje žene kao svoja tijela. Tko ljubi svoju ženu, sebe ljubi.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (56, 5, 29, 'Ta nitko nikada ne mrzi svoga tijela, nego ga hrani i njeguje kao i Krist Crkvu.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (56, 5, 30, 'Doista, mi smo udovi njegova Tijela!');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (56, 5, 31, 'Stoga će čovjek ostaviti oca i majku da prione uza svoju ženu; dvoje njih bit će jedno tijelo.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (56, 5, 32, 'Otajstvo je to veliko! Ja smjeram na Krista i na Crkvu.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (56, 5, 33, 'Dakle, neka svaki od vas ljubi svoju ženu kao samog sebe, a žena neka poštuje svog muža.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (56, 6, 1, 'Djeco, slušajte svoje roditelje u Gospodinu jer to je pravedno.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (56, 6, 2, 'Poštuj oca svoga i majku - to je prva zapovijed s obećanjem:');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (56, 6, 3, 'da ti dobro bude i da dugo živiš na zemlji.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (56, 6, 4, 'A vi, očevi, ne srdite djece svoje, nego ih odgajajte stegom i urazumljivanjem Gospodnjim!');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (56, 6, 5, 'Robovi, slušajte svoje zemaljske gospodare kao Krista - sa strahom i trepetom, u jednostavnosti srca.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (56, 6, 6, 'Ne naoko, kao oni koji se ulaguju ljudima, nego kao sluge Kristove koje zdušno vrše volju Božju;');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (56, 6, 7, 'dragovoljno služe - kao Gospodinu, a ne ljudima,');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (56, 6, 8, 'znajući da će svatko, bio on rob ili slobodnjak, učini li što dobro, za to dobiti plaću od Gospodina.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (56, 6, 9, 'I vi, gospodari, isto se tako vladajte prema njima: kanite se prijetnje, znajući da je i njihov i vaš Gospodar na nebesima i da u njega nema pristranosti.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (56, 6, 10, 'Ubuduće jačajte se u Gospodinu i u silnoj snazi njegovoj.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (56, 6, 11, 'Obucite svu opremu Božju da se mognete oduprijeti lukavstvima đavlovim.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (56, 6, 12, 'Jer nije nam se boriti protiv krvi i mesa, nego protiv Vrhovništava, protiv Vlasti, protiv upravljača ovoga mračnoga svijeta, protiv zlih duhova po nebesima.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (56, 6, 13, 'Zbog toga posegnite za svom opremom Božjom da uzmognete odoljeti u dan zli i održati se kada sve nadvladate.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (56, 6, 14, 'Držite se dakle! Opašite bedra istinom, obucite oklop pravednosti,');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (56, 6, 15, 'potpašite noge spremnošću za evanđelje mira!');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (56, 6, 16, 'U svemu imajte uza se štit vjere: njime ćete moći ugasiti ognjene strijele Zloga.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (56, 6, 17, 'Uzmite i kacigu spasenja i mač Duha, to jest Riječ Božju.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (56, 6, 18, 'Svakovrsnom se molitvom i prošnjom u svakoj prigodi u Duhu molite. Poradi toga i bdijte sa svom ustrajnošću i molitvom za sve svete,');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (56, 6, 19, 'i za me, da mi se otvore usta i dade riječ hrabro obznaniti otajstvo evanđelja');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (56, 6, 20, 'kojeg sam poslanik u okovima, da se ohrabrim o njemu kako treba govoriti.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (56, 6, 21, 'A da i vi znate što je sa mnom, kako mi je, o svemu će vas obavijestiti Tihik, ljubljeni brat i vjerni poslužitelj u Gospodinu.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (56, 6, 22, 'Njega šaljem k vama baš zato da znate kako smo i da ohrabri srca vaša.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (56, 6, 23, 'Mir braći i ljubav, s vjerom, od Boga Oca i Gospodina Isusa Krista!');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (56, 6, 24, 'Milost sa svima koji ljube Gospodina našega Isusa Krista - u neraspadljivosti.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (57, 1, 1, 'Pavao i Timotej, sluge Krista Isusa, svima svetima u Kristu Isusu koji su u Filipima, s nadglednicima i poslužiteljima.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (57, 1, 2, 'Milost vam i mir od Boga, Oca našega, i Gospodina Isusa Krista!');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (57, 1, 3, 'Zahvaljujem Bogu svomu kad vas se god sjetim.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (57, 1, 4, 'Uvijek se u svakoj svojoj molitvi za vas s radošću molim');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (57, 1, 5, 'zbog vašeg udjela u evanđelju od onoga prvog dana sve do sada -');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (57, 1, 6, 'uvjeren u ovo: Onaj koji otpoče u vama dobro djelo, dovršit će ga do Dana Krista Isusa.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (57, 1, 7, 'I pravo je da tako osjećam o svima vama! Ta ja vas nosim u srcu jer u okovima mojim i u obrani i utvrđivanju evanđelja svi ste vi suzajedničari moje milosti.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (57, 1, 8, 'Bog mi je doista svjedok koliko žudim za svima vama srcem Isusa Krista!');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (57, 1, 9, 'I molim za ovo: da ljubav vaša sve više i više raste u spoznanju i potpunu pronicanju');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (57, 1, 10, 'te mognete prosuditi što je najbolje da budete čisti i besprijekorni za Dan Kristov,');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (57, 1, 11, 'puni ploda pravednosti po Isusu Kristu - na slavu i hvalu Božju.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (57, 1, 12, 'A hoću da znate, braćo: ovaj se moj udes pače okrenuo u napredovanje evanđelja');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (57, 1, 13, 'tako da se moji okovi u Kristu razglasiše u svem pretoriju i među svima drugima,');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (57, 1, 14, 'a većina braće u Gospodinu, ohrabrena mojim okovima, još se više usuđuje neustrašivo zboriti Riječ.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (57, 1, 15, 'Neki, istina, propovijedaju Krista iz zavisti i nadmetanja, a neki iz dobre volje:');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (57, 1, 16, 'ovi iz ljubavi jer znaju da sam ovdje za obranu evanđelja;');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (57, 1, 17, 'oni pak Krista navješćuju iz suparništva, neiskreno - misleći da će tako otežati nevolju mojih okova.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (57, 1, 18, 'Pa što onda? Samo se na svaki način, bilo himbeno, bilo istinito, Krist navješćuje. I tome se radujem, a i radovat ću se.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (57, 1, 19, 'Jer znadem: po vašoj molitvi i pomoći Duha Isusa Krista to će mi biti na spasenje,');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (57, 1, 20, 'kako željno i očekujem i nadam se da se ni zbog čega neću smesti, nego da će se mojom posvemašnjom odvažnošću - kako uvijek tako i sada - Krist uzveličati u mome tijelu, bilo životom, bilo smrću.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (57, 1, 21, 'Ta meni je živjeti Krist, a umrijeti dobitak!');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (57, 1, 22, 'A ako mi živjeti u tijelu omogućuje plodno djelovanje, što da odaberem? Ne znam!');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (57, 1, 23, 'Pritiješnjen sam od ovoga dvoga: želja mi je otići i s Kristom biti jer to je mnogo, mnogo bolje;');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (57, 1, 24, 'ali ostati u tijelu potrebnije je poradi vas.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (57, 1, 25, 'U to uvjeren, znam da ću ostati i biti uz vas sve, za vaš napredak i na radost vjere,');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (57, 1, 26, 'da ponos vaš mnome poraste u Kristu Isusu kad opet dođem k vama.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (57, 1, 27, 'Samo se ponašajte dostojno evanđelja Kristova, pa - došao ja i vidio vas ili nenazočan slušao što je s vama - da mogu utvrditi kako ste postojani u jednome duhu i jednodušno se zajednički borite za evanđeosku vjeru');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (57, 1, 28, 'ne plašeći se ni u čemu protivnika. To je njima najava njihove propasti, a vašega spasenja, i to od Boga.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (57, 1, 29, 'Jer vama je dana milost: \"za Krista\", ne samo u njega vjerovati nego za njega i trpjeti,');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (57, 1, 30, 'isti boj bijući koji na meni vidjeste i sada o meni čujete.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (57, 2, 1, 'Ima li dakle u Kristu kakve utjehe, ima li kakva ljubazna bodrenja, ima li kakva zajedništva Duha, ima li kakva srca i samilosti,');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (57, 2, 2, 'ispunite me radošću: složni budite, istu ljubav njegujte, jednodušni, jedne misli budite;');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (57, 2, 3, 'nikakvo suparništvo ni umišljenost, nego - u poniznosti jedni druge smatrajte višima od sebe;');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (57, 2, 4, 'ne starajte se samo svaki za svoje, nego i za ono što se tiče drugih!');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (57, 2, 5, 'Neka u vama bude isto mišljenje kao i u Kristu Isusu:');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (57, 2, 6, 'On, trajni lik Božji, nije se kao plijena držao svoje jednakosti s Bogom,');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (57, 2, 7, 'nego sam sebe \"oplijeni\" uzevši lik sluge, postavši ljudima sličan; obličjem čovjeku nalik,');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (57, 2, 8, 'ponizi sam sebe, poslušan do smrti, smrti na križu.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (57, 2, 9, 'Zato Bog njega preuzvisi i darova mu ime, ime nad svakim imenom,');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (57, 2, 10, 'da se na ime Isusovo prigne svako koljeno nebesnika, zemnika i podzemnika.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (57, 2, 11, 'I svaki će jezik priznati: \"Isus Krist jest Gospodin!\" - na slavu Boga Oca.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (57, 2, 12, 'Tako, ljubljeni moji, poslušni kako uvijek bijaste, ne samo kao ono za moje nazočnosti nego mnogo više sada, za moje nenazočnosti, sa strahom i trepetom radite oko svoga spasenja!');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (57, 2, 13, 'Da, Bog u svojoj dobrohotnosti izvodi u vama i htjeti i djelovati.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (57, 2, 14, 'Sve činite bez mrmljanja i oklijevanja');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (57, 2, 15, 'da budete besprijekorni i čisti, djeca Božja neporočna posred poroda izopačena i lukava u kojem svijetlite kao svjetlila u svijetu');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (57, 2, 16, 'držeći riječ Života meni na ponos za Dan Kristov, što nisam zaludu trčao niti se zaludu trudio.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (57, 2, 17, 'Naprotiv, ako se ja i izlijevam za žrtvu i bogoslužje, za vjeru vašu, radostan sam i radujem se sa svima vama.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (57, 2, 18, 'A tako i vi budite radosni i radujte se sa mnom.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (57, 2, 19, 'Nadam se u Gospodinu Isusu da ću vam uskoro poslati Timoteja da mi odlane kad saznam što je s vama.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (57, 2, 20, 'Nikoga doista nemam tako srodne duše tko bi se kao on svojski za vas pobrinuo');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (57, 2, 21, 'jer svi traže svoje, a ne ono što je Isusa Krista.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (57, 2, 22, 'A prokušanost vam je njegova poznata: kao dijete s ocem služio je sa mnom evanđelju.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (57, 2, 23, 'Njega se dakle nadam poslati tek što razvidim što je sa mnom.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (57, 2, 24, 'A uvjeren sam u Gospodinu da ću i sam uskoro doći.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (57, 2, 25, 'Smatrao sam potrebnim poslati k vama Epafrodita, brata, suradnika i suborca moga kojega ste poslali da mi poslužuje u potrebi.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (57, 2, 26, 'Jer je čeznuo za svima vama i bio zabrinut što ste saznali da je obolio.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (57, 2, 27, 'I doista je gotovo na smrt bio obolio, ali Bog mu se smilovao, ne samo njemu nego i meni, da me ne zadesi žalost na žalost.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (57, 2, 28, 'Brže ga dakle poslah da se, pošto ga vidite, opet obradujete, i ja da budem manje žalostan.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (57, 2, 29, 'Primite ga dakle u Gospodinu sa svom radosti i poštujte takve');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (57, 2, 30, 'jer se za djelo Kristovo smrti sasvim približio, životnoj se pogibli izložio da nadopuni ono u čemu me vi ne mogoste poslužiti.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (57, 3, 1, 'Uostalom, braćo moja, radujte se u Gospodinu! Pisati vam jedno te isto meni nije dosadno, a za vas je sigurnije.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (57, 3, 2, 'Čuvajte se tih pasa, čuvajte se tih opakih radnika, čuvajte se te osakaćenosti!');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (57, 3, 3, 'Jer mi smo obrezanje, mi koji u Duhu Božjemu obavljamo bogoslužje i dičimo se Kristom Isusom, a ne pouzdajemo se u tijelo,');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (57, 3, 4, 'iako bih se ja mogao pouzdati i u tijelo. Smatra li tko drugi da se može uzdati u tijelo, ja još više:');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (57, 3, 5, 'obrezan osmog dana, od roda sam Izraelova, plemena Benjaminova, Hebrej od Hebreja; po Zakonu farizej,');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (57, 3, 6, 'po revnosti progonitelj Crkve, po pravednosti zakonskoj besprijekoran.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (57, 3, 7, 'Ali što mi god bijaše dobitak, to poradi Krista smatram gubitkom.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (57, 3, 8, 'Štoviše, čak sve gubitkom smatram zbog onoga najizvrsnijeg, zbog spoznanja Isusa Krista, Gospodina mojega, radi kojega sve izgubih i otpadom smatram: da Krista steknem');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (57, 3, 9, 'i u njemu se nađem - ne svojom pravednošću, onom od Zakona, nego pravednošću po vjeri u Krista, onom od Boga, na vjeri utemeljenoj -');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (57, 3, 10, 'da upoznam njega i snagu uskrsnuća njegova i zajedništvo u patnjama njegovim,');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (57, 3, 11, 'ne bih li kako, suobličen smrti njegovoj, prispio k uskrsnuću od mrtvih.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (57, 3, 12, 'Ne kao da sam već postigao ili dopro do savršenstva, nego - hitim ne bih li kako dohvatio jer sam i zahvaćen od Krista.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (57, 3, 13, 'Braćo, ja nipošto ne smatram da sam već dohvatio. Jedno samo: što je za mnom, zaboravljam, za onim što je preda mnom, prežem,');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (57, 3, 14, 'k cilju hitim, k nagradi višnjeg poziva Božjeg u Kristu Isusu.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (57, 3, 15, 'Koji smo god zreli, ovako mislimo! I ako što drukčije mislite, Bog će vam ovako objaviti.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (57, 3, 16, 'Samo, držimo se onoga do čega smo stigli!');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (57, 3, 17, 'Braćo! Nasljedovatelji moji budite i promatrajte one koji žive po uzoru koji imate u nama.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (57, 3, 18, 'Jer često sam vam govorio, a sada i plačući govorim: mnogi žive kao neprijatelji križa Kristova.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (57, 3, 19, 'Svršetak im je propast, bog im je trbuh, slava u sramoti - jer misle na zemaljsko.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (57, 3, 20, 'Naša je pak domovina na nebesima, odakle iščekujemo Spasitelja, Gospodina našega Isusa Krista:');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (57, 3, 21, 'snagom kojom ima moć sve sebi podložiti on će preobraziti ovo naše bijedno tijelo i suobličiti ga tijelu svomu slavnomu.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (57, 4, 1, 'Stoga, braćo moja ljubljena i željkovana, radosti moja i vijenče moj, tako - čvrsto stojte u Gospodinu.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (57, 4, 2, 'Evodiju zaklinjem, i Sintihu zaklinjem da budu složne u Gospodinu.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (57, 4, 3, 'Da, molim i tebe, čestiti druže, pomaži im jer su se one u evanđelju borile zajedno sa mnom, i s Klementom i ostalim mojim suradnicima, kojih su imena u knjizi Života.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (57, 4, 4, 'Radujte se u Gospodinu uvijek! Ponavljam: radujte se!');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (57, 4, 5, 'Blagost vaša neka je znana svim ljudima! Gospodin je blizu!');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (57, 4, 6, 'Ne budite zabrinuti ni za što, nego u svemu - molitvom i prošnjom, sa zahvaljivanjem - očitujte svoje molbe Bogu.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (57, 4, 7, 'I mir Božji koji je iznad svakog razuma čuvat će srca vaša i vaše misli u Kristu Isusu.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (57, 4, 8, 'Uostalom, braćo, što je god istinito, što god časno, što god pravedno, što god čisto, što god ljubazno, što god hvalevrijedno; je li što krepost, je li što pohvala - to nek vam je na srcu!');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (57, 4, 9, 'Što ste naučili, i primili, i čuli, i vidjeli na meni - to činite i Bog mira bit će s vama!');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (57, 4, 10, 'Uvelike se obradovah u Gospodinu što ste napokon procvali te mislite na me; mislili ste i prije, ali niste imali prigode.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (57, 4, 11, 'Govorim to ne zbog oskudice, ta naučen sam u svakoj prigodi biti zadovoljan.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (57, 4, 12, 'Znam i oskudijevati, znam i obilovati! Na sve sam i na svašta navikao: i sit biti i gladovati, i obilovati i oskudijevati.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (57, 4, 13, 'Sve mogu u Onome koji me jača!');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (57, 4, 14, 'Ipak, lijepo je od vas što sa mnom podijeliste moju nevolju.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (57, 4, 15, 'A i vi, Filipljani, znate: u početku evanđelja, kad otputovah iz Makedonije, nijedna mi se Crkva nije pridružila u pogledu izdataka i primitaka, doli vi jedini.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (57, 4, 16, 'Čak ste mi i u Solun i jednom, i dvaput, za potrebe poslali.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (57, 4, 17, 'Ne, ne tražim dara; tražim samo plod izobilan u vašu korist.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (57, 4, 18, 'Imam svega i u izobilju; namiren sam otkad po Epafroditu primih ono od vas, miris ugodan, žrtvu milu, ugodnu Bogu.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (57, 4, 19, 'A Bog moj ispunit će svaku vašu potrebu po bogatstvu svome, veličanstveno, u Kristu Isusu.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (57, 4, 20, 'Bogu pak, Ocu našemu, slava u vijeke vjekova! Amen.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (57, 4, 21, 'Pozdravite svakoga svetog u Kristu Isusu. Pozdravljaju vas braća koja su sa mnom.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (57, 4, 22, 'Pozdravljaju vas svi sveti, ponajpače oni iz careva dvora.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (57, 4, 23, 'Milost Gospodina Isusa Krista s duhom vašim!');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (58, 1, 1, 'Pavao, po volji Božjoj apostol Krista Isusa, i brat Timotej:');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (58, 1, 2, 'Kološanima, svetoj i vjernoj braći u Kristu. Milost vam i mir od Boga, Oca našega!');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (58, 1, 3, 'Zahvaljujemo Bogu, Ocu Gospodina našega Isusa Krista, svagda za vas moleći.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (58, 1, 4, 'Jer čuli smo za vašu vjeru u Kristu Isusu i za ljubav koju gajite prema svima svetima');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (58, 1, 5, 'poradi nade koja vam je pohranjena u nebesima. Za nju ste već čuli u Riječi istine -');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (58, 1, 6, 'evanđelju koje je do vas doprlo te plodove nosi i raste, kao što po svem svijetu, tako i među vama od dana kad ste čuli i spoznali milost Božju po istini,');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (58, 1, 7, 'kako ste naučili od ljubljenog Epafre, sluge zajedno s nama; on je umjesto nas, vjeran poslužitelj Kristov,');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (58, 1, 8, 'on nas je i obavijestio o vašoj ljubavi u Duhu.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (58, 1, 9, 'Zato i mi, od dana kada to čusmo, neprestano za vas molimo i ištemo da se ispunite spoznajom volje Njegove u svoj mudrosti i shvaćanju duhovnome:');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (58, 1, 10, 'da živite dostojno Gospodina i posve mu ugodite, plodni svakim dobrim djelom i rastući u spoznaji Božjoj;');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (58, 1, 11, 'osnaženi svakom snagom, po sili Slave njegove, za svaku postojanost i strpljivost;');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (58, 1, 12, 's radošću zahvaljujući Ocu koji vas osposobi za dioništvo u baštini svetih u svjetlosti.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (58, 1, 13, 'On nas izbavi iz vlasti tame i prenese u kraljevstvo Sina, ljubavi svoje,');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (58, 1, 14, 'u kome imamo otkupljenje, otpuštenje grijeha.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (58, 1, 15, 'On je slika Boga nevidljivoga, Prvorođenac svakog stvorenja.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (58, 1, 16, 'Ta u njemu je sve stvoreno na nebesima i na zemlji, vidljivo i nevidljivo, bilo Prijestolja, bilo Gospodstva, bilo Vrhovništva, bilo Vlasti - sve je po njemu i za njega stvoreno:');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (58, 1, 17, 'on je prije svega i sve stoji u njemu.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (58, 1, 18, 'On je Glava Tijela, Crkve; on je Početak, Prvorođenac od mrtvih, da u svemu bude Prvak.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (58, 1, 19, 'Jer svidjelo se Bogu u njemu nastaniti svu Puninu');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (58, 1, 20, 'i po njemu - uspostavivši mir krvlju križa njegova - izmiriti sa sobom sve, bilo na zemlji, bilo na nebesima.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (58, 1, 21, 'I vas, nekoć po zlim djelima udaljene i neprijateljski raspoložene,');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (58, 1, 22, 'sada u ljudskom tijelu Kristovu, po smrti, sa sobom izmiri da vas k sebi privede svete, bez mane i besprigovorne.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (58, 1, 23, 'Samo ako ostanete u vjeri utemeljeni, stalni i nepoljuljani u nadi evanđelja koje čuste, koje se propovijeda svakom stvorenju pod nebom, a ja mu, Pavao, postadoh poslužiteljem.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (58, 1, 24, 'Radujem se sada dok trpim za vas i u svom tijelu dopunjam što nedostaje mukama Kristovim za Tijelo njegovo, za Crkvu.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (58, 1, 25, 'Njoj ja postadoh poslužiteljem po rasporedbi Božjoj koja mi je dana za vas da potpuno pronesem Riječ Božju -');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (58, 1, 26, 'otajstvo pred vjekovima i pred naraštajima skriveno, a sada očitovano svetima njegovim.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (58, 1, 27, 'Njima Bog htjede obznaniti kako li je slavom bogato to otajstvo među poganima: to jest Krist u vama, nada slave!');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (58, 1, 28, 'Njega mi navješćujemo, opominjući svakoga čovjeka, poučavajući svakoga čovjeka u svoj mudrosti da bismo svakoga čovjeka doveli do savršenstva u Kristu.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (58, 1, 29, 'Za to se i trudim i borim njegovom djelotvornošću koja u meni snažno djeluje.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (58, 2, 1, 'Htio bih uistinu da znate koliko mi se boriti za vas, za one u Laodiceji i za sve koji me nisu vidjeli licem u lice:');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (58, 2, 2, 'da se ohrabre srca njihova, povezana u ljubavi, te se vinu do svega bogatstva, punine shvaćanja, do spoznanja otajstva Božjega - Krista,');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (58, 2, 3, 'u kojem su sva bogatstva mudrosti i spoznaje skrivena.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (58, 2, 4, 'To govorim zato da vas tko ne prevari zavodljivim riječima.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (58, 2, 5, 'Jer ako sam tijelom nenazočan, duhom sam ipak s vama: s radošću promatram vaš red i čvrstoću vaše vjere u Krista.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (58, 2, 6, 'Kao što primiste Krista Isusa, Gospodina, tako u njemu živite:');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (58, 2, 7, 'ukorijenjeni i nazidani na njemu i učvršćeni vjerom kako ste poučeni, obilujte zahvaljivanjem.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (58, 2, 8, 'Pazite da vas tko ne odvuče mudrovanjem i ispraznim zavaravanjem što se oslanja na predaju ljudsku, na \"počela svijeta\", a ne na Krista.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (58, 2, 9, 'Jer u njemu tjelesno prebiva sva punina božanstva; te ste i vi');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (58, 2, 10, 'ispunjeni u njemu, koji je glava svakoga Vrhovništva i Vlasti.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (58, 2, 11, 'U njemu ste i obrezani obrezanjem nerukotvorenim - svukoste tijelo puteno - obrezanjem Kristovim:');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (58, 2, 12, 's njime suukopani u krštenju, u njemu ste i suuskrsli po vjeri u snagu Boga koji ga uskrisi od mrtvih.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (58, 2, 13, 'On i vas, koji bijaste mrtvi zbog prijestupa i neobrezanosti svoga tijela, i vas on oživi zajedno s njime. Milostivo nam je oprostio sve prijestupe,');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (58, 2, 14, 'izbrisao zadužnicu koja propisima bijaše protiv nas, protivila nam se. Nju on ukloni pribivši je na križ.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (58, 2, 15, 'Skinu Vrhovništva i Vlasti, javno to pokaza: u pobjedničkoj ih povorci s njime vodi.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (58, 2, 16, 'Neka vas dakle nitko ne sudi po jelu ili po piću, po blagdanima, mlađacima ili subotama.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (58, 2, 17, 'To je tek sjena onoga što dolazi, a zbiljnost jest - tijelo Kristovo.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (58, 2, 18, 'Nitko neka vas ne podcjenjuje zato što on sam uživa u \"poniznosti i štovanju anđela\", zadubljuje se u svoja viđenja, bezrazložno se nadima tjelesnom pameću svojom,');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (58, 2, 19, 'a ne drži se Glave, Njega od kojeg sve Tijelo, zglobovima i svezama zbrinuto i povezano, raste rastom Božjim.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (58, 2, 20, 'Ako ste s Kristom umrli za počela svijeta, zašto se, kao da još u ovom svijetu živite, dajete pod propise:');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (58, 2, 21, '\"Ne diraj, ne kušaj, ne dotiči\"?');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (58, 2, 22, 'Sve će to uporabom propasti. Uredbe i nauci ljudski!');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (58, 2, 23, 'Po samozvanu bogoštovlju, poniznosti i trapljenju tijela sve to doduše slovi kao mudrost, ali nema nikakve vrijednosti, samo zasićuje tijelo.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (58, 3, 1, 'Ako ste suuskrsli s Kristom, tražite što je gore, gdje Krist sjedi zdesna Bogu!');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (58, 3, 2, 'Za onim gore težite, ne za zemaljskim!');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (58, 3, 3, 'Ta umrijeste i život je vaš skriven s Kristom u Bogu!');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (58, 3, 4, 'Kad se pojavi Krist, život vaš, tada ćete se i vi s njime pojaviti u slavi.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (58, 3, 5, 'Umrtvite dakle udove svoje zemaljske: bludnost, nečistoću, strasti, zlu požudu i pohlepu - to idolopoklonstvo!');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (58, 3, 6, 'Zbog toga dolazi gnjev Božji na sinove neposlušne.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (58, 3, 7, 'Tim ste putom i vi nekoć hodili, kad ste u tome živjeli.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (58, 3, 8, 'Ali sada i vi odložite sve! Gnjev, srdžba, opakost, hula, prostota van iz vaših usta!');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (58, 3, 9, 'Ne varajte jedni druge! Jer svukoste staroga čovjeka s njegovim djelima');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (58, 3, 10, 'i obukoste novoga, koji se obnavlja za spoznanje po slici svoga Stvoritelja!');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (58, 3, 11, 'Tu više nema: Grk - Židov, obrezanje - neobrezanje, barbar - skit, rob - slobodnjak, nego sve i u svima - Krist.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (58, 3, 12, 'Zaodjenite se dakle - kao izabranici Božji, sveti i ljubljeni - u milosrdno srce, dobrostivost, poniznost, blagost, strpljivost');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (58, 3, 13, 'te podnosite jedni druge praštajući ako tko ima protiv koga kakvu pritužbu! Kao što je Gospodin vama oprostio, tako i vi!');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (58, 3, 14, 'A povrh svega - ljubav! To je sveza savršenstva.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (58, 3, 15, 'I mir Kristov neka upravlja srcima vašim - mir na koji ste pozvani u jednom tijelu! I zahvalni budite!');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (58, 3, 16, 'Riječ Kristova neka u svem bogatstvu prebiva u vama! U svakoj se mudrosti poučavajte i urazumljujte! Psalmima, hvalospjevima, pjesmama duhovnim od srca pjevajte hvalu Bogu!');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (58, 3, 17, 'I sve što god riječju ili djelom činite, sve činite u imenu Gospodina Isusa, zahvaljujući Bogu Ocu po njemu!');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (58, 3, 18, 'Žene, pokoravajte se svojim muževima kao što dolikuje u Gospodinu!');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (58, 3, 19, 'Muževi, ljubite svoje žene i ne budite osorni prema njima.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (58, 3, 20, 'Djeco, slušajte roditelje u svemu, ta to je milo u Gospodinu!');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (58, 3, 21, 'Očevi, ne ogorčujte svoje djece da ne klonu duhom.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (58, 3, 22, 'Robovi, slušajte u svemu svoje zemaljske gospodare! Ne naoko, kao oni koji se ulaguju ljudima, nego u jednostavnosti srca, bojeći se Gospodina.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (58, 3, 23, 'Što god radite, zdušno činite, kao Gospodinu, a ne ljudima,');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (58, 3, 24, 'znajući da ćete od Gospodina primiti nagradu, baštinu. Gospodinu Kristu služite.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (58, 3, 25, 'Doista, nepravedniku će se uzvratiti što je nepravedno učinio. Ne, nema pristranosti!');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (58, 4, 1, 'Gospodari, pružajte svojim robovima što je pravo i pravično, znajući da i vi imate Gospodina na nebu!');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (58, 4, 2, 'U molitvi ustrajte, bdijte u njoj u zahvaljivanju!');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (58, 4, 3, 'Molite ujedno i za nas: da nam Bog otvori vrata riječi te propovijedamo otajstvo Kristovo, za koje sam i okovan;');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (58, 4, 4, 'da ga očitujem propovijedajući kako treba.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (58, 4, 5, 'Mudro se ponašajte prema onima vani: iskupljujte vrijeme!');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (58, 4, 6, 'Riječ neka vam je uvijek ljubazna, solju začinjena: znajte svakomu odgovoriti kako treba.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (58, 4, 7, 'Što je sa mnom - o svemu će vas obavijestiti Tihik, ljubljeni brat, vjerni poslužitelj i sa mnom sluga u Gospodinu.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (58, 4, 8, 'Njega šaljem k vama baš zato da znate kako smo i da ohrabri srca vaša.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (58, 4, 9, 'Šaljem ga s Onezimom, vjernim i ljubljenim bratom, koji je vaš zemljak: oni će vam priopćiti kako je ovdje.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (58, 4, 10, 'Pozdravlja vas Aristarh, suuznik moj. I Marko, nećak Barnabin, o kome primiste naredbe: dođe li k vama, lijepo ga primite.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (58, 4, 11, 'Pozdravlja vas i Isus, zvani Just. Od onih koji su iz obrezanja samo su mi ovi suradnici na kraljevstvu Božjemu, oni mi bijahu utjehom.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (58, 4, 12, 'Pozdravlja vas Epafra, vaš zemljak, sluga Krista Isusa; on se uvijek bori za vas u molitvama: da se održite, savršeni i ispunjeni, u posvemašnjoj volji Božjoj.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (58, 4, 13, 'Svjedočim doista za nj: mnogo se trudi za vas i za one u Laodiceji i one u Hierapolu.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (58, 4, 14, 'Pozdravlja vas Luka, ljubljeni liječnik, i Dema.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (58, 4, 15, 'Pozdravite braću u Laodiceji, i Nimfu i Crkvu u njezinoj kući.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (58, 4, 16, 'A kad se ova poslanica pročita kod vas, pobrinite se da se pročita i u Laodicejskoj crkvi, i vi da pročitate onu iz Laodiceje.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (58, 4, 17, 'I recite Arhipu: \"Pazi na službu koju si primio u Gospodinu: ispuni je!\"');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (58, 4, 18, 'Pozdrav mojom rukom, Pavlovom! Spominjite se mojih okova! Milost s vama!');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (59, 1, 1, 'Pavao, Silvan i Timotej Crkvi Solunjana u Bogu Ocu i Gospodinu Isusu Kristu. Milost vam i mir!');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (59, 1, 2, 'Zahvaljujemo uvijek Bogu za sve vas i bez prestanka vas se sjećamo u svojim molitvama');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (59, 1, 3, 'spominjući se vaše djelotvorne vjere, zauzete ljubavi i postojane nade u Gospodinu našem Isusu Kristu, pred Bogom i Ocem našim.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (59, 1, 4, 'Svjesni smo, braćo od Boga ljubljena, vašeg izabranja');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (59, 1, 5, 'jer evanđelje naše nije k vama došlo samo u riječi nego i u snazi, u Duhu Svetome i mnogostrukoj punini. Takvi smo, kao što znate, poradi vas među vama bili.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (59, 1, 6, 'I vi postadoste nasljedovatelji naši i Gospodinovi: sve u nevolji mnogoj prigrliste Riječ s radošću Duha Svetoga');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (59, 1, 7, 'tako da postadoste uzorom svim vjernicima u Makedoniji i Ahaji.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (59, 1, 8, 'Od vas je doista ne samo riječ Gospodnja odjeknula po Makedoniji i Ahaji, nego se i vaša vjera u Boga posvuda tako proširila te nije potrebno da o tome govorimo.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (59, 1, 9, 'Oni sami o nama pripovijedaju: kako dođosmo k vama, kako se od idola obratiste k Bogu da biste služili Bogu živomu i istinskomu');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (59, 1, 10, 'i iščekivali s nebesa Sina njegova koga uskrisi od mrtvih, Isusa koji nas izbavlja od gnjeva što dolazi.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (59, 2, 1, 'Sami doista znate, braćo: naš dolazak k vama nije bio uzaludan.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (59, 2, 2, 'Naprotiv, i pošto smo, kako znate, u Filipima trpjeli i bili pogrđeni, odvažismo se u Bogu našemu iznijeti vam, uz tešku borbu, evanđelje Božje.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (59, 2, 3, 'Uistinu, naše poticanje ne proistječe iz zablude, ni nečistoće, ni prijevare,');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (59, 2, 4, 'nego kako je Bog prosudio povjeriti nam evanđelje, tako ga i navješćujemo - ne kao da želimo ugoditi ljudima, nego Bogu koji prosuđuje srca naša.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (59, 2, 5, 'Nikada se zaista kako znate, ne poslužismo ni laskavom riječju ni - Bog nam je svjedok - prikrivenom pohlepom.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (59, 2, 6, 'Niti smo od ljudi iskali slavu - ni od vas, ni od drugih -');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (59, 2, 7, 'premda smo se mogli nametnuti kao Kristovi apostoli. Ali bili smo među vama nježni kao majka što hrani i njeguje svoju djecu.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (59, 2, 8, 'Tako, puni ljubavi prema vama, htjedosmo vam predati ne samo evanđelje Božje nego i naše duše jer ste nam omiljeli.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (59, 2, 9, 'Sjećate se doista, braćo, našega truda i napora. Propovijedali smo vam evanđelje Božje i radili noću i danju da ne bismo opteretili koga od vas.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (59, 2, 10, 'Svjedoci ste vi i Bog kako smo se sveto, pravedno i besprijekorno vladali prema vama, vjernicima.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (59, 2, 11, 'Kao što znate, svakoga smo od vas kao otac svoju djecu,');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (59, 2, 12, 'poticali, sokolili i zaklinjali da živite dostojno Boga koji vas pozva u svoje kraljevstvo i slavu.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (59, 2, 13, 'Zato, eto, i mi bez prestanka zahvaljujemo Bogu što ste, kad od nas primiste riječ poruke Božje, primili ne riječ ljudsku, nego kakva uistinu jest, riječ Božju koja i djeluje u vama, vjernicima.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (59, 2, 14, 'Doista, vi ste, braćo, postali nasljedovatelji crkava Božjih koje su u Judeji u Kristu Isusu: i vi isto trpite od svojih suplemenika što i oni od Židova,');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (59, 2, 15, 'koji su i Gospodina Isusa i proroke ubili, i nas progonili, te Bogu ne ugađaju i svim se ljudima protive');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (59, 2, 16, 'kad nam priječe propovijedati poganima da se spase, da bi tako u svako vrijeme navršili mjeru zlodjela svojih. Ali sručio se na njih konačni gnjev.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (59, 2, 17, 'A mi, braćo, pošto smo za kratko vrijeme ostali bez vas - licem, ne srcem - brže se bolje, u silnoj čežnji, požurismo ugledati vaše lice.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (59, 2, 18, 'Zaista, htjedosmo k vama - ja, Pavao, i jednom i dvaput - ali nas je spriječio Sotona.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (59, 2, 19, 'Ta tko li će biti naša nada, radost ili vijenac dični - zar možda ne i vi? - pred Gospodinom našim Isusom o njegovu Dolasku?');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (59, 2, 20, 'Vi ste doista slava naša i radost!');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (59, 3, 1, 'Zato kad više ne mogosmo izdržati, pristadosmo ostati u Ateni sami');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (59, 3, 2, 'te poslasmo Timoteja, brata našega i suradnika Božjega u Kristovu evanđelju, da vas učvrsti i ohrabri u vjeri');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (59, 3, 3, 'da se nitko ne pokoleba u tim nevoljama. Ta i sami znate da smo za to određeni:');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (59, 3, 4, 'doista, kad smo bili kod vas, pretkazivali smo kako nas imaju zadesiti nevolje, što se, kako znate, i dogodilo.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (59, 3, 5, 'Zbog toga i ja, ne mogavši više izdržati, poslah da saznam o vašoj vjeri, da vas možda Zavodnik nije zaveo te je naš trud postao uzaludan.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (59, 3, 6, 'A sada kad se Timotej od vas k nama vratio i donio nam radosnu vijest o vašoj vjeri i ljubavi, i da nas se sveudilj ugodno sjećate i čeznete vidjeti nas, kao i mi vas -');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (59, 3, 7, 'zbog toga smo, braćo, nad vama, vašom vjerom, bili utješeni uza svu svoju tjeskobu i nevolju.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (59, 3, 8, 'Da, sada živimo kada ste vi postojani u Gospodinu!');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (59, 3, 9, 'I kojom bismo zahvalom mogli Bogu uzvratiti za vas, za svu radost kojom se zbog vas radujemo pred Bogom svojim,');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (59, 3, 10, 'dok noću i danju najusrdnije molimo da vidimo vaše lice i nadoknadimo manjkavosti vaše vjere?');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (59, 3, 11, 'A sam Bog i Otac naš i Gospodin naš Isus upravio naš put prema vama!');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (59, 3, 12, 'Vama pak Gospodin dao te jedni prema drugima i prema svima rasli i obilovali ljubavlju kakva je i naša prema vama.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (59, 3, 13, 'Učvrstio vam srca da budu besprijekorno sveta pred Bogom i Ocem našim o Dolasku Gospodina našega Isusa i svih svetih njegovih s njime.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (59, 4, 1, 'Uostalom, braćo, molimo vas i zaklinjemo u Gospodinu Isusu: primili ste od nas kako treba da živite da biste ugodili Bogu. Vi tako i živite pa sve više napredujete!');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (59, 4, 2, 'Ta znate koje smo vam zapovijedi dali u Gospodinu Isusu.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (59, 4, 3, 'Doista, ovo je volja Božja: vaše posvećenje - da se uzdržavate od bludnosti,');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (59, 4, 4, 'da svatko od vas zna svoje tijelo posjedovati u svetosti i poštovanju,');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (59, 4, 5, 'a ne u pohotnoj strasti kao pogani koji ne poznaju Boga,');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (59, 4, 6, 'pa time ne prikraćivati i varati svoga brata. Jer Gospodin je osvetnik za sve to, kao što vam već rekosmo i posvjedočismo.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (59, 4, 7, 'Bog nas, doista, nije pozvao na nečistoću, nego na svetost.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (59, 4, 8, 'Prema tome, tko to odbacuje, ne odbacuje čovjeka nego Boga koji svoga Duha Svetoga udahnjuje u vas.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (59, 4, 9, 'A o bratoljublju vam nije potrebno pisati. Ta i sami ste od Boga naučili ljubiti jedni druge,');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (59, 4, 10, 'a to doista i činite prema svoj braći u cijeloj Makedoniji. Samo vas, braćo, potičemo da u tom još više uznapredujete');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (59, 4, 11, 'pa da se trsite mirno živjeti, svoje činiti i raditi svojim rukama, kako smo vam zapovijedili,');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (59, 4, 12, 'te tako časno živite prema onima vani i nikoga ne trebate.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (59, 4, 13, 'Nećemo da budete u neznanju, braćo, o onima koji su usnuli, da ne tugujete kao drugi koji nemaju nade.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (59, 4, 14, 'Doista, ako vjerujemo da je Isus umro i uskrsnuo, onda će Bog i one koji usnuše u Isusu, privesti zajedno s njime.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (59, 4, 15, 'Ovo vam uistinu velimo po riječi Gospodnjoj: mi živi, preostali za Dolazak Gospodnji, nećemo preteći onih koji su usnuli.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (59, 4, 16, 'Jer sam će Gospodin - na zapovijed, na glas arkanđelov, na zov trublje Božje - sići s neba. I najprije će uskrsnuti mrtvi u Kristu,');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (59, 4, 17, 'a zatim ćemo mi živi, preostali, zajedno s njima biti poneseni na oblacima u susret Gospodinu, u zrak. I tako ćemo uvijek biti s Gospodinom.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (59, 4, 18, 'Tješite se dakle uzajamno ovim riječima!');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (59, 5, 1, 'A o vremenima i trenucima nije, braćo, potrebno pisati vam.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (59, 5, 2, 'Ta i sami dobro znate da Dan Gospodnji dolazi baš kao kradljivac u noći.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (59, 5, 3, 'Dok još budu govorili: \"Mir i sigurnost\", zadesit će ih iznenadna propast kao trudovi trudnicu i neće umaći.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (59, 5, 4, 'Ali vi, braćo, niste u tami, da bi vas Dan mogao zaskočiti kao kradljivac:');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (59, 5, 5, 'ta svi ste vi sinovi svjetlosti i sinovi dana. Nismo doista od noći ni od tame.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (59, 5, 6, 'Onda i ne spavajmo kao ostali, nego bdijmo i trijezni budimo.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (59, 5, 7, 'Jer koji spavaju, noću spavaju; i koji se opijaju, noću se opijaju.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (59, 5, 8, 'A mi koji smo od dana, budimo trijezni, obucimo oklop vjere i ljubavi i stavimo kacigu, nadu spasenja!');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (59, 5, 9, 'Ta Bog nas nije odredio za gnjev, nego da imamo spasenje po Gospodinu našem Isusu Kristu,');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (59, 5, 10, 'koji je za nas umro da - bdjeli ili spavali - zajedno s njime živimo.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (59, 5, 11, 'Zato, tješite se uzajamno i izgrađujte jedan drugoga, kako i činite.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (59, 5, 12, 'Molimo vas, braćo: priznajte one koji se trude među vama, koji su vam predstojnici u Gospodinu i opominju vas;');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (59, 5, 13, 's ljubavlju ih nadasve cijenite poradi njihova djela! Gajite mir među sobom!');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (59, 5, 14, 'Potičemo vas, braćo: opominjite neuredne, sokolite malodušne, podržavajte slabe, budite velikodušni prema svima!');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (59, 5, 15, 'Pazite da tko komu zlo zlom ne uzvrati, nego uvijek promičite dobro jedni prema drugima i prema svima.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (59, 5, 16, 'Uvijek se radujte!');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (59, 5, 17, 'Bez prestanka se molite!');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (59, 5, 18, 'U svemu zahvaljujte! Jer to je za vas volja Božja u Kristu Isusu.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (59, 5, 19, 'Duha ne trnite,');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (59, 5, 20, 'proroštava ne prezirite!');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (59, 5, 21, 'Sve provjeravajte: dobro zadržite,');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (59, 5, 22, 'svake se sjene zla klonite!');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (59, 5, 23, 'A sam Bog mira neka vas posvema posveti i cijelo vaše biće - duh vaš i duša i tijelo - neka se besprijekornim, savršenim sačuva za Dolazak Gospodina našega Isusa Krista.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (59, 5, 24, 'Vjeran je Onaj tko vas poziva: on će to i učiniti.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (59, 5, 25, 'Braćo, molite i za nas!');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (59, 5, 26, 'Pozdravite svu braću cjelovom svetim.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (59, 5, 27, 'Zaklinjem vas u Gospodinu: neka se ova poslanica pročita svoj braći.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (59, 5, 28, 'Milost Gospodina našega Isusa Krista s vama!');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (60, 1, 1, 'Pavao, Silvan i Timotej Crkvi Solunjana u Bogu Ocu našemu i Gospodinu Isusu Kristu.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (60, 1, 2, 'Milost vam i mir od Boga Oca i Gospodina Isusa Krista!');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (60, 1, 3, 'Zahvaljivati moramo Bogu uvijek za vas, braćo, kao što dolikuje jer izvanredno raste vaša vjera i množi se ljubav svakoga od vas prema drugima,');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (60, 1, 4, 'tako da se mi sami po crkvama Božjim vama ponosimo zbog vaše postojanosti i vjere u svim progonstvima i nevoljama koje podnosite.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (60, 1, 5, 'One su najava pravednog Suda Božjega: da ćete se naći dostojni kraljevstva Božjega za koje i trpite.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (60, 1, 6, 'Jer pravo je da Bog vašim mučiteljima mukom,');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (60, 1, 7, 'a vama, mučenima, zajedno s nama spokojem uzvrati kad se Gospodin Isus objavi s nama, zajedno s anđelima svoje moći,');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (60, 1, 8, 'u ognju žarkome i osveti se onima koji ne poznaju Boga i ne pokoravaju se evanđelju Gospodina našega Isusa.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (60, 1, 9, 'Oni će biti kažnjeni vječnom propašću, daleko od lica Gospodnjega i od slave njegova veličanstva,');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (60, 1, 10, 'kada - u onaj Dan - dođe da se proslavi u svojim svetima i da se prodiči u svima koji povjerovaše. Jer povjerovalo se svjedočanstvu našemu među vama.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (60, 1, 11, 'Zato i molimo uvijek za vas da vas Bog učini dostojnima poziva i snažno dovede do punine svako vaše nastojanje oko dobra i djelo vaše vjere');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (60, 1, 12, 'te da se proslavi ime Gospodina našega Isusa u vama i vi u njemu - po milosti Boga našega i Gospodina Isusa Krista.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (60, 2, 1, 'A što se tiče Dolaska Gospodina našega Isusa Krista i našeg okupljanja oko njega, molimo vas, braćo:');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (60, 2, 2, 'ne dajte se brzo pokolebati u svom shvaćanju niti uznemiriti ni nekim duhom, ni nekom riječju, ni nekim tobože našim pismom, kao da će sad-na Dan Gospodnji.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (60, 2, 3, 'Neka vas nitko ne zavede ni na koji način. Jer ako prije ne dođe onaj otpad i ne otkrije se Čovjek bezakonja, Sin propasti,');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (60, 2, 4, 'Protivnik, onaj koji uzdiže sebe protiv svega što se zove Bog ili svetinja, dotle da i u Božji hram zasjedne gradeći se Bogom...');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (60, 2, 5, 'Ne sjećate li se, to sam vam govorio dok sam još bio među vama?');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (60, 2, 6, 'I sada znate što ga zadržava da bi se pojavio tek u svoje vrijeme.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (60, 2, 7, 'Doista, otajstvo bezakonja već je na djelu, samo ima tko da ga sada zadržava dok ne bude uklonjen.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (60, 2, 8, 'Tada će se otkriti Bezakonik. Njega će Gospodin Isus pogubiti dahom usta i uništiti pojavkom Dolaska svoga -');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (60, 2, 9, 'njega koji djelovanjem Sotoninim dolazi sa svom silom, lažnim znamenjima i čudesima');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (60, 2, 10, 'i sa svim nepravednim zavaravanjem onih koji propadaju poradi toga što ne prihvatiše ljubavi prema istini da bi se spasili.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (60, 2, 11, 'I zato im Bog šalje djelovanje zavodničko da povjeruju laži');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (60, 2, 12, 'te budu osuđeni svi koji nisu povjerovali istini, nego su se odlučili za nepravednost.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (60, 2, 13, 'Mi pak moramo uvijek zahvaljivati Bogu za vas, braćo od Gospodina ljubljena, što vas je od početka odabrao za spasenje, posvećenjem u Duhu i vjerom u istinu.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (60, 2, 14, 'Da, na to vas pozva po našem evanđelju - na posjedovanje slave Gospodina našega Isusa Krista.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (60, 2, 15, 'Stoga braćo, čvrsto stojte i držite se predaja u kojima ste poučeni bilo našom riječju, bilo pismom.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (60, 2, 16, 'A sam Gospodin naš Isus Krist i Bog, Otac naš, koji nas uzljubi i koji nam po milosti dade trajno ohrabrenje i dobru nadu,');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (60, 2, 17, 'neka ohrabri vaša srca i neka ih učvrsti u svakom dobru djelu i riječi!');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (60, 3, 1, 'Uostalom, molite, braćo, za nas da riječ Gospodnja trči i proslavlja se kao i u vas');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (60, 3, 2, 'i da se oslobodimo nezgodnih i opakih ljudi. Jer nemaju svi vjere!');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (60, 3, 3, 'Ali, vjeran je Gospodin koji će nas učvrstiti i sačuvati od Zloga.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (60, 3, 4, 'A uzdamo se, u Gospodinu, u vas: da vršite i da ćete vršiti ono što vam zapovijedamo.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (60, 3, 5, 'A Gospodin neka upravi srca vaša k ljubavi Božjoj i postojanosti Kristovoj.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (60, 3, 6, 'Zapovijedamo vam, braćo, u ime Gospodina Isusa Krista da se klonite svakoga brata što živi neuredno i ne po predaji koju primiste od nas.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (60, 3, 7, 'Ta sami znate kako nas treba nasljedovati. Jer dok bijasmo među vama, nismo živjeli neuredno:');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (60, 3, 8, 'ničiji kruh nismo badava jeli, nego smo u trudu i naporu noću i danju radili da ne bismo opteretili koga od vas.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (60, 3, 9, 'Ne što ne bismo imali prava, nego da vam sebe damo za uzor koji ćete nasljedovati.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (60, 3, 10, 'Doista, dok bijasmo u vas, ovo vam zapovijedasmo: Tko neće da radi, neka i ne jede!');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (60, 3, 11, 'A čujemo da neki od vas žive neuredno: ništa ne rade, nego dangube.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (60, 3, 12, 'Takvima zapovijedamo i zaklinjemo ih u Gospodinu Isusu Kristu: neka s mirom rade i svoj kruh jedu.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (60, 3, 13, 'Vama pak, braćo, neka ne dodija činiti dobro.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (60, 3, 14, 'Ako li se tko ne pokorava našoj riječi u ovoj poslanici, zabilježite ga, ne drugujte s njime, da se postidi,');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (60, 3, 15, 'ali ga ne smatrajte neprijateljem, nego ga urazumljujte kao brata.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (60, 3, 16, 'A sam Gospodin mira dao vam mir zauvijek i na svaki način! Gospodin sa svima vama!');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (60, 3, 17, 'Pozdrav mojom rukom, Pavlovom. Ovo je znak u svakoj poslanici: ovako pišem.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (60, 3, 18, 'Milost Gospodina našega Isusa Krista sa svima vama!');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (61, 1, 1, 'Pavao, apostol Krista Isusa po nalogu Boga, Spasitelja našega, i Krista Isusa, nade naše,');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (61, 1, 2, 'Timoteju, pravomu sinu u vjeri: milost, milosrđe i mir od Boga Oca i Krista Isusa, Gospodina našega!');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (61, 1, 3, 'Kao što sam te zamolio kad sam odlazio u Makedoniju, ostani u Efezu da zapovijediš nekima neka ne naučavaju drugih nauka');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (61, 1, 4, 'i neka se ne zanose beskrajnim bajkama i rodoslovljima, koja više pogoduju rasprama negoli rasporedbi Božjoj po vjeri.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (61, 1, 5, 'Svrha je te zapovijedi ljubav iz čista srca, dobre savjesti i vjere neprijetvorne.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (61, 1, 6, 'To su neki promašili i zastranili u praznorječje;');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (61, 1, 7, 'htjeli bi biti učitelji Zakona, a ne razumiju ni što govore ni što tvrde.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (61, 1, 8, 'A mi znamo da je Zakon dobar ako se tko njime služi zakonito,');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (61, 1, 9, 'svjestan toga da je Zakon tu ne za pravednika nego za bezakonike i nepokornike, nepobožnike i grešnike, bezbožnike i svetogrdnike, ocoubojice i materoubojice, koljače,');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (61, 1, 10, 'bludnike, muškoložnike, trgovce ljudima, varalice, krivokletnike, i ima li još što protivno zdravom nauku -');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (61, 1, 11, 'po evanđelju Slave blaženoga Boga koje je meni povjereno.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (61, 1, 12, 'Zahvalan sam Onome koji mi dade snagu - Kristu Isusu, Gospodinu našemu - jer me smatrao vrijednim povjerenja, kad u službu postavi mene');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (61, 1, 13, 'koji prije bijah hulitelj, progonitelj i nasilnik. Ali pomilovan sam jer sam to u neznanju učinio, još u nevjeri.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (61, 1, 14, 'I milost Gospodina našega preobilovala je zajedno s vjerom i ljubavlju, u Kristu Isusu.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (61, 1, 15, 'Vjerodostojna je riječ i vrijedna da se posve prihvati: Isus Krist dođe na svijet spasiti grešnike, od kojih sam prvi ja.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (61, 1, 16, 'A pomilovan sam zato da na meni prvome Isus Krist pokaže svu strpljivost i pruži primjer svima koji će povjerovati u njega za život vječni.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (61, 1, 17, 'A Kralju vjekova, besmrtnome, nevidljivome, jedinome Bogu čast i slava u vijeke vjekova. Amen.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (61, 1, 18, 'Taj ti zadatak predajem, sine Timoteju, u skladu s proroštvima nekoć nad tobom izrečenima: na njih oslonjen, bij boj plemeniti');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (61, 1, 19, 'imajući vjeru i dobru savjest, koju su neki odbacili i doživjeli brodolom vjere.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (61, 1, 20, 'Među njima je Himenej i Aleksandar, koje sam predao Sotoni da nauče ne huliti.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (61, 2, 1, 'Dakle, preporučujem prije svega da se obavljaju prošnje, molitve, molbenice i zahvalnice za sve ljude,');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (61, 2, 2, 'za kraljeve i sve koji su na vlasti, da provodimo miran i spokojan život u svoj bogoljubnosti i ozbiljnosti.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (61, 2, 3, 'To je dobro i ugodno pred Spasiteljem našim Bogom,');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (61, 2, 4, 'koji hoće da se svi ljudi spase i dođu do spoznanja istine.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (61, 2, 5, 'Jer jedan je Bog, jedan je i posrednik između Boga i ljudi, čovjek - Krist Isus,');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (61, 2, 6, 'koji sebe samoga dade kao otkup za sve. To je u svoje vrijeme dano svjedočanstvo,');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (61, 2, 7, 'za koje sam ja postavljen propovjednikom i apostolom - istinu govorim, ne lažem - učiteljem naroda u vjeri i istini.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (61, 2, 8, 'Hoću dakle da muškarci mole na svakome mjestu, podižući čiste ruke bez srdžbe i raspre;');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (61, 2, 9, 'isto tako žene - u doličnu držanju: neka se rese stidljivošću i razborom, ne pletenicama i zlatom ili biserjem ili skupocjenim odijelom,');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (61, 2, 10, 'nego - dobrim djelima, kako dolikuje ženama koje ispovijedaju bogoljubnost.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (61, 2, 11, 'Žena neka u miru prima pouku sa svom podložnošću.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (61, 2, 12, 'Poučavati pak ženi ne dopuštam, ni vladati nad mužem, nego - neka bude na miru.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (61, 2, 13, 'Jer prvi je oblikovan Adam, onda Eva;');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (61, 2, 14, 'i Adam nije zaveden, a žena je, zavedena, učinila prekršaj.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (61, 2, 15, 'A spasit će se rađanjem djece ako ustraje u vjeri, ljubavi i posvećivanju, s razborom.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (61, 3, 1, 'Vjerodostojna je riječ: teži li tko za nadgledništvom, časnu službu želi.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (61, 3, 2, 'Treba stoga da nadglednik bude besprijekoran, jedne žene muž, trijezan, razuman, sređen, gostoljubiv, sposoban poučavati,');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (61, 3, 3, 'ne vinu sklon, ne nasilan nego popustljiv, ne ratoboran, ne srebroljubac;');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (61, 3, 4, 'da svojom kućom dobro upravlja i sinove drži u pokornosti sa svom ozbiljnošću -');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (61, 3, 5, 'a ne zna li netko svojom kućom upravljati, kako će se brinuti za Crkvu Božju? -');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (61, 3, 6, 'ne novoobraćenik da se ne bi uzoholio i pao pod osudu đavlovu.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (61, 3, 7, 'A treba da ima i lijepo svjedočanstvo od onih vani, da ne bi u rug upao i zamku đavlovu.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (61, 3, 8, 'Ðakoni isto tako treba da budu ozbiljni, ne dvolični, ne odani mnogom vinu ni prljavu dobitku -');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (61, 3, 9, 'imajući otajstvo vjere u čistoj savjesti.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (61, 3, 10, 'I neka se najprije iskušavaju, pa onda, budu li besprigovorni, neka obavljaju službu.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (61, 3, 11, 'Žene isto tako neka budu ozbiljne, ne klevetnice nego trijezne, vjerne u svemu.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (61, 3, 12, 'đakoni neka budu jedne žene muževi, neka dobro upravljaju djecom i svojim kućama.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (61, 3, 13, 'Jer oni koji dobro obavljaju službu, stječu častan položaj i veliku smjelost u vjeri, vjeri u Isusu Kristu.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (61, 3, 14, 'Ovo ti pišem u nadi da ću ubrzo doći k tebi,');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (61, 3, 15, 'a okasnim li, da znaš kako se treba vladati u kući Božjoj, koja je Crkva Boga živoga, stup i uporište istine.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (61, 3, 16, 'Da, po sveopćem uvjerenju, veliko je Otajstvo pobožnosti: On, očitovan u tijelu, opravdan u Duhu, viđen od anđela, propovijedan među narodima, vjerovan u svijetu, uznesen u slavu.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (61, 4, 1, 'Duh izričito govori da će u posljednja vremena neki otpasti od vjere i prikloniti se prijevarnim duhovima i zloduhovskim naucima.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (61, 4, 2, 'A sve to pod utjecajem himbe lažljivaca otupjele savjesti');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (61, 4, 3, 'koji zabranjuju ženiti se i nameću uzdržavati se od jela što ih je Bog stvorio da ih sa zahvalnošću uzimaju oni koji vjeruju i znaju istinu.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (61, 4, 4, 'Doista, svako je Božje stvorenje dobro i ne valja odbaciti ništa što se uzima sa zahvalnošću');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (61, 4, 5, 'jer se posvećuje riječju Božjom i molitvom.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (61, 4, 6, 'To izlaži braći i bit ćeš dobar poslužitelj Krista Isusa, hranjen riječima vjere i dobroga nauka za kojim postojano ideš.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (61, 4, 7, 'Svjetovne pak i bablje priče odbijaj! Vježbaj se u pobožnosti!');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (61, 4, 8, 'Uistinu, tjelesno vježbanje malo čemu koristi, a pobožnost je svemu korisna jer joj je obećan život - sadašnji i budući.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (61, 4, 9, 'Vjerodostojna je to riječ i vrijedna da se posve prihvati.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (61, 4, 10, 'Ta za to se trudimo i borimo jer se pouzdajemo u Boga živoga koji je Spasitelj svih ljudi, ponajpače vjernika.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (61, 4, 11, 'Zapovijedaj to i naučavaj!');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (61, 4, 12, 'Nitko neka ne prezire tvoje mladosti, nego budi uzor vjernicima u riječi, u vladanju, u ljubavi, u vjeri, u čistoći.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (61, 4, 13, 'Dok ne dođem, posveti se čitanju, poticanju, poučavanju.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (61, 4, 14, 'Ne zanemari milosnog dara koji je u tebi, koji ti je dan po proroštvu zajedno s polaganjem ruku starješinstva.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (61, 4, 15, 'Oko toga nastoj, sav u tom budi da tvoj napredak bude svima očit.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (61, 4, 16, 'Pripazi na samog sebe i na poučavanje! Ustraj u tome! Jer to vršeći, spasit ćeš i sebe i one koji te slušaju.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (61, 5, 1, 'Na starca se ne otresaj, nego ga nagovaraj kao oca, mladiće kao braću,');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (61, 5, 2, 'starice kao majke, djevojke kao sestre - u svoj čistoći.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (61, 5, 3, 'Udovice poštuj - one koje su zaista udovice.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (61, 5, 4, 'Ako li ipak koja udovica ima djecu ili unuke, neka najprije oni znaju očitovati svoju pobožnost prema vlastitom domu i uzdarjem uzvraćati roditeljima jer to je ugodno Bogu.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (61, 5, 5, 'A ona koja je zaista udovica, posve sama, pouzdaje se u Boga, odana prošnjama i molitvama noć i dan;');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (61, 5, 6, 'ona, naprotiv, koja provodi lagodan život, živa je već umrla.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (61, 5, 7, 'I to naglašuj da budu besprijekorne.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (61, 5, 8, 'Ako li se tkogod za svoje, navlastito za ukućane, ne stara, zanijekao je vjeru i gori je od nevjernika.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (61, 5, 9, 'U popis neka se unosi udovica ne mlađa od šezdeset godina, jednog muža žena,');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (61, 5, 10, 'koja ima svjedočanstvo dobrih djela: da je djecu odgojila, da je bila gostoljubiva, da je svetima noge prala, da je nevoljnima pomagala, da se svakom dobru djelu posvećivala.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (61, 5, 11, 'Mlađe pak udovice odbijaj jer kad ih požuda odvrati od Krista, hoće se udati,');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (61, 5, 12, 'pa zasluže osudu što su pogazile prvotnu vjernost.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (61, 5, 13, 'A uz to se, obilazeći po kućama, nauče biti besposlene, i ne samo besposlene, nego i brbljave i nametljive, govoreći što ne bi smjele.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (61, 5, 14, 'Hoću dakle da se mlađe udaju, djecu rađaju, da budu kućevne te ne daju protivniku nikakva povoda za pogrđivanje.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (61, 5, 15, 'Jer već su neke zastranile za Sotonom.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (61, 5, 16, 'Ako koja vjernica ima udovica, neka im pomaže, a neka se ne opterećuje Crkva, da uzmogne pomoći onima koje su zaista udovice.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (61, 5, 17, 'Starješine koji su dobri predstojnici dostojni su dvostruke časti, ponajpače oni koji se trude oko Riječi i poučavanja.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (61, 5, 18, 'Pismo doista veli: Volu koji vrši ne zavezuj usta! I: Vrijedan je radnik plaće svoje.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (61, 5, 19, 'Protiv starješine ne primaj tužbe, osim na osnovi dvaju ili triju svjedoka.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (61, 5, 20, 'One koji griješe, pred svima ukori da i drugi imaju straha!');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (61, 5, 21, 'Zaklinjem te pred Bogom i Kristom Isusom i izabranim anđelima da se toga držiš bez predrasude i ništa ne činiš po naklonosti.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (61, 5, 22, 'Ruku prebrzo ni na koga ne polaži i ne budi dionikom tuđih grijeha! Sebe čistim čuvaj!');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (61, 5, 23, 'Ne pij više samo vode, nego uzimaj malo vina poradi želuca i čestih svojih slabosti.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (61, 5, 24, 'Grijesi nekih ljudi očiti su i prije suda, nekih pak samo nakon njega.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (61, 5, 25, 'Tako su i dobra djela očita, a bila i drukčija, ne mogu se sakriti.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (61, 6, 1, 'Koji su pod jarmom, robovi, neka svoje gospodare smatraju svake časti dostojnima da se ne bi pogrđivalo ime Božje i nauk.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (61, 6, 2, 'A oni kojima su gospodari vjernici, neka ih ne cijene manje zato što su braća, nego neka im još više služe jer ti koji primaju njihovo dobročinstvo vjernici su i ljubljena braća. To naučavaj i preporučuj!');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (61, 6, 3, 'A tko drukčije naučava i ne prianja uza zdrave riječi, riječi Gospodina našega Isusa Krista, i nauk u skladu s pobožnošću,');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (61, 6, 4, 'nadut je, puka neznalica, samo boluje od raspra i rječoborstava, od kojih nastaje zavist, svađa, pogrde, zla sumnjičenja,');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (61, 6, 5, 'razračunavanja ljudi pokvarene pameti i lišenih istine, što pobožnost smatraju dobitkom.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (61, 6, 6, 'Pa i jest dobitak velik pobožnost, zadovoljna onim što ima!');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (61, 6, 7, 'Ta ništa nismo donijeli na svijet te iz njega ništa ni iznijeti ne možemo!');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (61, 6, 8, 'Imamo li dakle hranu i odjeću, zadovoljimo se time.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (61, 6, 9, 'Jer oni koji se hoće bogatiti, upadaju u napast, zamku i mnoge nerazumne i štetne požude što ljude strovaljuju u zator i propast.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (61, 6, 10, 'Zaista, korijen svih zala jest srebroljublje; njemu odani, mnogi odlutaše od vjere i sami sebe isprobadaše mukama mnogima.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (61, 6, 11, 'A ti se, Božji čovječe, toga kloni! Teži za pravednošću, pobožnošću, vjerom, ljubavlju, postojanošću, krotkošću!');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (61, 6, 12, 'Bij dobar boj vjere, osvoji vječni život na koji si pozvan i radi kojega si dao ono lijepo svjedočanstvo pred mnogim svjedocima!');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (61, 6, 13, 'Zapovijedam pred Bogom koji svemu život daje i pred Kristom Isusom koji pred Poncijem Pilatom posvjedoči lijepo svjedočanstvo:');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (61, 6, 14, 'čuvaj Zapovijed, neokaljano i besprijekorno, do Pojavka Gospodina našega Isusa Krista.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (61, 6, 15, 'Njega će u svoje vrijeme pokazati On, Blaženi i jedini Vladar, Kralj kraljeva i Gospodar gospodara,');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (61, 6, 16, 'koji jedini ima besmrtnost, prebiva u svjetlu nedostupnu, koga nitko od ljudi ne vidje niti ga vidjeti može. Njemu čast i vlast vjekovječna! Amen.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (61, 6, 17, 'Onima koji su u sadašnjem svijetu bogati zapovijedaj neka ne budu bahati i neka se ne uzdaju u nesigurno bogatstvo, nego u Boga koji nam sve bogato daje na uživanje;');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (61, 6, 18, 'neka dobro čine, neka se bogate dobrim djelima, neka budu darežljivi, zajedničari -');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (61, 6, 19, 'prikupljajući sebi lijepu glavnicu za budućnost da osvoje onaj pravi život.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (61, 6, 20, 'Timoteju, poklad čuvaj kloneći se svjetovnoga praznoglasja i proturječja nekog nazovispoznanja,');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (61, 6, 21, 'koje su neki ispovijedali pa od vjere zastranili. Milost s vama');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (62, 1, 1, 'Pavao, apostol Krista Isusa voljom Božjom, po obećanju života, života u Kristu Isusu,');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (62, 1, 2, 'Timoteju, ljubljenom sinu: milost, milosrđe i mir od Boga Oca i Krista Isusa, Gospodina našega.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (62, 1, 3, 'Zahvalan sam Bogu, kojemu onamo od predaka čiste savjesti služim, dok te se neprestano spominjem u svojim molitvama noć i dan.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (62, 1, 4, 'Sjetim se tvojih suza i zaželim vidjeti te da se napunim radosti');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (62, 1, 5, 'imajući na pameti neprijetvornu vjeru koja je u tebi - onu vjeru koja je najprije prebivala u tvojoj baki Loidi i tvojoj majci Euniki, a uvjeren sam, i u tebi.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (62, 1, 6, 'Poradi toga podsjećam te: raspiruj milosni dar Božji koji je u tebi po polaganju mojih ruku.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (62, 1, 7, 'Jer nije nam Bog dao duha bojažljivosti, nego snage, ljubavi i razbora.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (62, 1, 8, 'Ne stidi se stoga svjedočanstva za Gospodina našega, ni mene, sužnja njegova. Nego zlopati se zajedno sa mnom za evanđelje, po snazi Boga');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (62, 1, 9, 'koji nas je spasio i pozvao pozivom svetim - ne po našim djelima, nego po svojem naumu i milosti koja nam je dana u Kristu Isusu prije vremena vjekovječnih,');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (62, 1, 10, 'a očitovana je sada pojavkom Spasitelja našega Krista Isusa, koji obeskrijepi smrt i učini da zasja život i neraspadljivost - po evanđelju');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (62, 1, 11, 'za koje sam ja postavljen propovjednikom, apostolom i učiteljem.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (62, 1, 12, 'Poradi toga i ovo trpim, ali se ne stidim jer znam komu sam povjerovao i uvjeren sam da je on moćan poklad moj sačuvati za onaj Dan.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (62, 1, 13, 'Uzorom neka ti budu zdrave riječi koje si od mene čuo u vjeri i ljubavi u Kristu Isusu.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (62, 1, 14, 'Lijepi poklad čuvaj po Duhu Svetom koji prebiva u nama.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (62, 1, 15, 'Napustiše me, to znaš, svi u Aziji, među njima i Figel i Hermogen.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (62, 1, 16, 'Neka Gospodin milosrđem podari Oneziforov dom jer me često osvježivao i nije se stidio mojih okova,');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (62, 1, 17, 'nego kad je bio u Rimu, brižljivo me potražio i našao.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (62, 1, 18, 'Dao mu Gospodin naći milosrđe u Gospodina u onaj Dan! A koliko je usluga u Efezu iskazao, to ti najbolje znaš.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (62, 2, 1, 'Ti se dakle, dijete moje, jačaj milošću u Kristu Isusu');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (62, 2, 2, 'i što si od mene po mnogim svjedocima čuo, to predaj vjernim ljudima koji će biti podobni i druge poučiti.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (62, 2, 3, 'S njima se zlopati kao dobar vojnik Krista Isusa.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (62, 2, 4, 'Tko vojuje, ne zapleće se u svagdanje poslove kako bi se vojskovođi svidio.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (62, 2, 5, 'I natječe li se tko, ne ovjenčava se ako se zakonito ne natječe.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (62, 2, 6, 'Ratar koji se trudi treba da prvi primi od uroda.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (62, 2, 7, 'Shvati što govorim! Ta dat će ti Gospodin razum u svemu.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (62, 2, 8, 'Spominji se Isusa Krista, uskrsla od mrtvih, od potomstva Davidova - po mojem evanđelju.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (62, 2, 9, 'Za nj se ja zlopatim sve do okova, kao zločinac. Ali riječ Božja nije okovana!');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (62, 2, 10, 'Stoga sve podnosim radi izabranih, da i oni postignu spasenje, spasenje u Kristu Isusu, zajedno s vječnom slavom.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (62, 2, 11, 'Vjerodostojna je riječ: Ako s njime umrijesmo, s njime ćemo i živjeti.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (62, 2, 12, 'Ako ustrajemo, s njime ćemo i kraljevati. Ako ga zaniječemo, i on će zanijekati nas.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (62, 2, 13, 'Ako ne budemo vjerni, on vjeran ostaje. Ta ne može sebe zanijekati!');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (62, 2, 14, 'Na to podsjećaj zaklinjući pred Bogom neka ne bude rječoborstva: ničemu ne koristi, a na propast je onima koji slušaju.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (62, 2, 15, 'Uznastoj da kao prokušan staneš pred Boga kao radnik koji se nema čega stidjeti, koji ispravno reže riječ istine.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (62, 2, 16, 'Svjetovnih se pak praznorječja kloni: sve će više provaljivati prema bezbožnosti');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (62, 2, 17, 'i riječ će njihova kao rak-rana izgrizati. Od njih su Himenej i Filet,');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (62, 2, 18, 'koji zastraniše od istine tvrdeći da je uskrsnuće već bilo te nekima prevraćaju vjeru.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (62, 2, 19, 'Ipak čvrsti temelj Božji stoji - pod ovim je pečatom: Poznaje Gospodin one koji su njegovi i neka se kloni zloće tko god imenuje ime Gospodnje.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (62, 2, 20, 'Pa u velikoj kući ima posuda ne samo zlatnih i srebrnih, nego i drvenih i glinenih; i jedne su časne, druge pak nečasne.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (62, 2, 21, 'Očisti li se dakle tko od toga, bit će posuda časna, posvećena, korisna Gospodaru, za svako dobro djelo prikladna.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (62, 2, 22, 'A mladenačkih se strastvenosti kloni! Teži za pravednošću, vjerom, ljubavlju, mirom sa svima koji iz čista srca prizivlju Gospodina.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (62, 2, 23, 'Lude pak i neobuzdane raspre odbijaj znajući da rađaju svađama.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (62, 2, 24, 'A sluga Gospodnji treba da se ne svađa, nego da bude nježan prema svima, sposoban poučavati, zlo podnositi,');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (62, 2, 25, 'da s blagošću preodgaja protivnike, ne bi li ih Bog podario obraćenjem te spoznaju istinu');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (62, 2, 26, 'i ponovno budu trijezni izvan zamke đavla koji ih drži robljem svoje volje.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (62, 3, 1, 'A ovo znaj: u posljednjim danima nastat će teška vremena.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (62, 3, 2, 'Ljudi će doista biti sebeljupci, srebroljupci, preuzetnici, oholice, hulitelji, roditeljima neposlušni, nezahvalnici, bezbožnici,');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (62, 3, 3, 'bešćutnici, nepomirljivci, klevetnici, neobuzdanici, goropadnici, neljubitelji dobra,');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (62, 3, 4, 'izdajice, brzopletnici, naduti, ljubitelji užitka više nego ljubitelji Boga.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (62, 3, 5, 'Imaju obličje pobožnosti, ali snage su se njezine odrekli. I njih se kloni!');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (62, 3, 6, 'Od njih su doista oni što se uvlače u kuće i zarobljuju ženice, natovarene grijesima, vodane najrazličitijim strastima:');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (62, 3, 7, 'one uvijek uče, a nikako ne mogu doći do spoznaje istine.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (62, 3, 8, 'Kao što se Janes i Jambres suprotstaviše Mojsiju, tako se i ovi, ljudi pokvarena uma, u vjeri neprokušani, suprotstavljaju istini.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (62, 3, 9, 'Ali neće više napredovati jer bezumlje će ovih postati očito, kako se to i onima dogodilo.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (62, 3, 10, 'A ti si pošao za nmom u poučavanju, u ponašanju, u naumu, u vjeri, u strpljivosti, u ljubavi, u postojanosti;');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (62, 3, 11, 'u progonstvima, u patnjama koje su me zadesile u Antiohiji, u Ikoniju, u Listri. Kakva li sam progonstva podnio! I iz svih me izbavio Gospodin!');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (62, 3, 12, 'A i svi koji hoće živjeti pobožno u Kristu Isusu, bit će progonjeni.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (62, 3, 13, 'Zli pak ljudi i vračari napredovat će sve više u zlu - kao zavodnici i zavedeni.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (62, 3, 14, 'Ti, naprotiv, ostani u onome u čemu si poučen i čemu si vjeru dao, svjestan od koga si sve poučen');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (62, 3, 15, 'i da od malena poznaješ Sveta pisma koja su vrsna učiniti te mudrim tebi na spasenje po vjeri, vjeri u Kristu Isusu.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (62, 3, 16, 'Sve Pismo, bogoduho, korisno je za poučavanje, uvjeravanje, popravljanje, odgajanje u pravednosti,');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (62, 3, 17, 'da čovjek Božji bude vrstan, za svako dobro djelo podoban.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (62, 4, 1, 'Zaklinjem te pred Bogom i Kristom Isusom, koji će suditi žive i mrtve, zaklinjem te pojavkom njegovim i kraljevstvom njegovim:');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (62, 4, 2, 'propovijedaj Riječ, uporan budi - bilo to zgodno ili nezgodno - uvjeravaj, prijeti, zapovijedaj sa svom strpljivošću i poukom.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (62, 4, 3, 'Jer doći će vrijeme kad ljudi neće podnositi zdrava nauka nego će sebi po vlastitim požudama nagomilavati učitelje kako im godi ušima;');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (62, 4, 4, 'od istine će uho odvraćati, a bajkama se priklanjati.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (62, 4, 5, 'Ti, naprotiv, budi trijezan u svemu, zlopati se, djelo izvrši blagovjesničko, služenje svoje posve ispuni!');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (62, 4, 6, 'Jer ja se već prinosim za žrtvu ljevanicu, prispjelo je vrijeme moga odlaska.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (62, 4, 7, 'Dobar sam boj bio, trku završio, vjeru sačuvao.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (62, 4, 8, 'Stoga, pripravljen mi je vijenac pravednosti kojim će mi u onaj Dan uzvratiti Gospodin, pravedan sudac; ne samo meni, nego i svima koji s ljubavlju čekaju njegov pojavak.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (62, 4, 9, 'Nastoj što prije doći k meni!');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (62, 4, 10, 'Jer Dema me, zaljubljen u sadašnji svijet, napustio i otišao u Solun; Krescencije u Galaciju, Tit u Dalmaciju.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (62, 4, 11, 'Luka je jedini sa mnom. Marka uzmi i dovedi sa sobom jer mi je koristan za služenje.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (62, 4, 12, 'Tihika sam poslao u Efez.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (62, 4, 13, 'Kabanicu koju ostavih u Troadi kod Karpa, kada dođeš, donesi. I knjige, osobito pergamene.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (62, 4, 14, 'Aleksandar kovač nanio mi je mnogo zla. Uzvratio mu Gospodin po njegovim djelima!');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (62, 4, 15, 'Njega se i ti čuvaj jer se veoma usprotivio našim riječima.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (62, 4, 16, 'Za prve moje obrane nitko ne bijaše uza me, svi me napustiše. Ne uračunalo im se!');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (62, 4, 17, 'Ali Gospodin je stajao uza me, on me krijepio da se po meni potpuno razglasi Poruka te je čuju svi narodi; i izbavljen sam iz usta lavljih.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (62, 4, 18, 'Izbavit će me Gospodin od svakoga zla djela i spasiti za svoje nebesko kraljevstvo. Njemu slava u vijeke vjekova! Amen!');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (62, 4, 19, 'Pozdravi Prisku i Akvilu i Oneziforov dom!');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (62, 4, 20, 'Erast osta u Korintu, a Trofima ostavih u Miletu bolesna.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (62, 4, 21, 'Nastoj doći prije zime. Pozdravlja te Eubul, Pudencije, Lino, Klaudija i sva braća.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (62, 4, 22, 'Gospodin s duhom tvojim. Milost s vama!');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (63, 1, 1, 'Pavao, sluga Božji i apostol Isusa Krista poradi vjere izabranika Božjih i spoznanja istine usmjerene k pobožnosti');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (63, 1, 2, 'u nadi života vječnoga što ga, prije vremena vjekovječnih, obeća Bog, On koji ne laže,');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (63, 1, 3, 'a u svoje doba očitova riječ svoju u propovijedanju koje je meni povjereno po odredbi Spasitelja našega, Boga:');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (63, 1, 4, 'Titu, pravomu sinu po zajedničkoj vjeri, milost i mir od Boga i Krista Isusa, Spasitelja našega!');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (63, 1, 5, 'Poradi toga ostavih te na Kreti da urediš preostalo te po gradovima postaviš starješine kako sam ti ja odredio:');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (63, 1, 6, 'je li tko besprigovoran, jedne žene muž, jesu li mu djeca vjernici i ne pod optužbom raskalašenosti ili nepokorna...');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (63, 1, 7, 'Jer nadstojnik kao Božji upravitelj treba da bude besprigovoran: ne samoživ, ne jedljiv, ne vinu sklon, ni nasilju, ni prljavu dobitku,');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (63, 1, 8, 'nego gostoljubiv, ljubitelj dobra, razuman, pravedan, svet, uzdržljiv,');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (63, 1, 9, 'priljubljen uz vjerodostojnu riječ nauka da može i hrabriti u zdravom nauku i uvjeravati protivnike.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (63, 1, 10, 'Jer mnogi su nepokorni, praznorječni i zavodnici, ponajpače oni iz obrezanja.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (63, 1, 11, 'Njima treba začepiti usta jer cijele domove prevraćaju naučavajući što ne bi smjeli, i to poradi prljava dobitka.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (63, 1, 12, 'Reče netko od njih, njihov vlastiti prorok: \"Krećani uvijek lašci, opake zvijeri, trbusi dangubni.\"');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (63, 1, 13, 'Svjedočanstvo je to istinito. Zato ih karaj oštro da budu zdravi u vjeri,');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (63, 1, 14, 'da ne prianjaju uza židovske bajke i propise ljudi koji se odvraćaju od istine.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (63, 1, 15, 'Sve je čisto čistima; okaljanima pak i nevjernima ništa čisto, nego su im okaljani i razum i savjest.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (63, 1, 16, 'Ispovijedaju da Boga poznaju, ali djelima ga niječu - odvratni, neposlušni i za koje god dobro djelo nepodesni.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (63, 2, 1, 'Ti, naprotiv, govori što se priliči zdravu nauku:');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (63, 2, 2, 'starci da budu trijezni, ozbiljni, razumni, zdrave vjere, ljubavi, postojanosti;');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (63, 2, 3, 'starice isto tako - vladanja kakvo dolikuje svetima: ne klevetnice, ne ropkinje mnogog vina, nego učiteljice dobra');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (63, 2, 4, 'da urazumljuju mlađe neka ljube svoje muževe, djecu,');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (63, 2, 5, 'neka budu razumne, čiste, kućevne, dobre, podložne svojim muževima da se riječ Božja ne bi pogrđivala.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (63, 2, 6, 'Mladiće isto tako potiči da budu razumni.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (63, 2, 7, 'U svemu se pokaži uzorom dobrih djela: u poučavanju - nepokvarljivost, ozbiljnost,');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (63, 2, 8, 'riječ zdrava, besprigovorna da se onaj nasuprot postidi nemajući o nama reći ništa zlo.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (63, 2, 9, 'Robovi neka se svojim gospodarima u svemu podlažu, ugađaju im, ne proturječe,');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (63, 2, 10, 'ne pronevjeruju, nego neka im iskazuju svaku dobru vjernost da u svemu budu ures nauku Spasitelja našega, Boga.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (63, 2, 11, 'Pojavila se doista milost Božja, spasiteljica svih ljudi;');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (63, 2, 12, 'odgojila nas da se odreknemo bezbožnosti i svjetovnih požuda te razumno, pravedno i pobožno živimo u sadašnjem svijetu,');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (63, 2, 13, 'iščekujući blaženu nadu i pojavak slave velikoga Boga i Spasitelja našega Isusa Krista.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (63, 2, 14, 'On sebe dade za nas da nas otkupi od svakoga bezakonja i očisti sebi Narod izabrani koji revnuje oko dobrih djela.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (63, 2, 15, 'To govori, zapovijedaj, karaj sa svom vlašću. Nitko neka te ne prezire.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (63, 3, 1, 'Podsjećaj ih da se podlažu poglavarstvima, vlastima, da slušaju, da budu spremni na svako dobro djelo,');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (63, 3, 2, 'nikoga da ne pogrđuju, da budu neratoborni, popustljivi, da očituju svaku blagost prema svim ljudima.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (63, 3, 3, 'Jer i mi nekoć bijasmo nerazumni, nepokorni, lutalice, robovi raznih požuda i naslada, živjeli smo u zlu i zavisti, odvratni bili, mrzili jedni druge.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (63, 3, 4, 'Ali kad se pojavila dobrostivost i čovjekoljublje Spasitelja našega, Boga,');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (63, 3, 5, 'on nas spasi ne po djelima što ih u pravednosti mi učinismo, nego po svojem milosrđu: kupelji novoga rođenja i obnavljanja po Duhu Svetom');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (63, 3, 6, 'koga bogato izli na nas po Isusu Kristu, Spasitelju našemu,');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (63, 3, 7, 'da opravdani njegovom milošću budemo, po nadi, baštinici života vječnoga.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (63, 3, 8, 'Vjerodostojna je ovo riječ i hoću da to uporno tvrdiš te da oni koji su povjerovali Bogu uznastoje prednjačiti dobrim djelima. To je dobro i korisno ljudima.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (63, 3, 9, 'A ludih se raspra, i rodoslovlja, i svađa, i sukoba zakonskih kloni: beskorisni su i isprazni.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (63, 3, 10, 'S krivovjercem nakon prvoga i drugog upozorenja prekini');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (63, 3, 11, 'znajući da je izopačen i da griješi: on sam sebe osuđuje.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (63, 3, 12, 'Kad pošaljem k tebi Artemu ili Tihika, požuri se k meni u Nikopol jer sam odlučio ondje prezimiti.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (63, 3, 13, 'Zenu, pravnika, i Apolona brižljivo opremi da im ništa ne ponestane.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (63, 3, 14, 'A i naši neka se uče prednjačiti dobrim djelima u životnim potrebama da ne budu neplodni.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (63, 3, 15, 'Pozdravljaju te svi koji su sa mnom. Pozdravi one koji nas ljube u vjeri. Milost sa svima vama!');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (64, 1, 1, 'Pavao, sužanj Isusa Krista, i brat Timotej: ljubljenom Filemonu, suradniku našemu,');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (64, 1, 2, 'i sestri Apiji, i Arhipu, suborcu našem, i Crkvi u tvojoj kući.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (64, 1, 3, 'Milost vam i mir od Boga, Oca našega, i Gospodina Isusa Krista!');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (64, 1, 4, 'Zahvaljujem svagda Bogu svojemu spominjući te se u svojim molitvama');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (64, 1, 5, 'jer čujem za tvoju ljubav i vjeru koju imaš prema Gospodinu Isusu Kristu i prema svima svetima.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (64, 1, 6, 'Nek zajedništvo tvoje vjere bude djelotvorno u spoznanju svakoga mogućeg dobra među vama poradi Krista!');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (64, 1, 7, 'Uvelike si me doista obradovao i utješio svojom ljubavlju jer si, brate, okrijepio srca svetih.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (64, 1, 8, 'Stoga, premda imam punu slobodu u Kristu da ti zapovjedim što ti je činiti,');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (64, 1, 9, 'poradi ljubavi radije molim, kakav već jesam, Pavao, starac, a sada i sužanj Krista Isusa.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (64, 1, 10, 'Molim te za svoje dijete koje rodih u okovima, za Onezima,');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (64, 1, 11, 'negda tebi nekorisna, a sada i tebi i meni veoma korisna.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (64, 1, 12, 'Šaljem ti ga - njega, srce svoje.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (64, 1, 13, 'Htjedoh ga zadržati kod sebe da mi mjesto tebe posluži u okovima evanđelja.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (64, 1, 14, 'Ali ne htjedoh preko tvoje volje da ne bi tvoja dobrota bila od nevolje, nego od dobre volje.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (64, 1, 15, 'Možda baš zato bi za čas odijeljen da ga dobiješ zauvijek -');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (64, 1, 16, 'ne kao roba, nego više od roba, kao brata ljubljenoga, osobito meni, a koliko više tebi, i po tijelu i po Gospodinu.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (64, 1, 17, 'Smatraš li me dakle drugom, primi ga kao mene.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (64, 1, 18, 'Ako ti je u čemu skrivio ili ti je što dužan, to meni upiši.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (64, 1, 19, 'Ja, Pavao, potpisujem svojom rukom: ja ću platiti. Da ti ne reknem da mi i samoga sebe duguješ!');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (64, 1, 20, 'Hajde, brate, da se tobom okoristim u Gospodinu: okrijepi srce moje u Kristu!');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (64, 1, 21, 'Uzdajući se u tvoju poslušnost, napisah ti uvjeren da ćeš još više učiniti, nego te molim.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (64, 1, 22, 'K tome, pripravi mi obitavalište jer se nadam da ću vam po vašim molitvama biti darovan.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (64, 1, 23, 'Pozdravlja te Epafra, moj suuznik u Kristu Isusu,');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (64, 1, 24, 'Marko, Aristarh, Dema i Luka, moji suradnici.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (64, 1, 25, 'Milost Gospodina našega Isusa Krista s duhom vašim!');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (65, 1, 1, 'Više puta i na više načina Bog nekoć govoraše ocima po prorocima;');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (65, 1, 2, 'konačno, u ove dane, progovori nama u Sinu. Njega postavi baštinikom svega; Njega po kome sazda svjetove.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (65, 1, 3, 'On, koji je odsjaj Slave i otisak Bića njegova te sve nosi snagom riječi svoje, pošto očisti grijehe, sjede zdesna Veličanstvu u visinama;');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (65, 1, 4, 'postade toliko moćniji od anđela koliko je uzvišenije nego oni baštinio ime.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (65, 1, 5, 'Ta kome od anđela ikad reče: Ti si sin moj, danas te rodih; ili pak: Ja ću njemu biti otac, a on će meni biti sin.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (65, 1, 6, 'A opet, kad uvodi Prvorođenca u svijet, govori: Nek pred njim nice padnu svi anđeli Božji.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (65, 1, 7, 'Za anđele veli: Anđele čini vjetrovima, sluge svoje plamenom ognjenim,');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (65, 1, 8, 'ali za Sina: Prijestolje je tvoje, Bože, u vijeke vjekova, i pravedno žezlo - žezlo je tvog kraljevstva.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (65, 1, 9, 'Ti ljubiš pravednost, a mrziš bezakonje, stoga Bog, Bog tvoj, tebe pomaza uljem radosti kao nikog od tvojih drugova.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (65, 1, 10, 'I: Ti u početku, Gospodine, utemelji zemlju i nebo je djelo ruku tvojih.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (65, 1, 11, 'Propast će, ti ćeš ostati, sve će ostarjeti kao odjeća.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (65, 1, 12, 'Mijenjaš ih poput haljine, kao odjeću, i nestaju. A ti si uvijek isti - godinama tvojim nema kraja.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (65, 1, 13, 'Za koga pak od anđela ikad reče: Sjedi mi zdesna dok ne položim neprijatelje tvoje za podnožje nogama tvojim!');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (65, 1, 14, 'Svi ti zar nisu služnički duhovi što se šalju služiti za one koji imaju baštiniti spasenje?');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (65, 2, 1, 'Zato treba da mi svesrdnije prianjamo uz ono što čusmo da ne bismo promašili.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (65, 2, 2, 'Jer ako je riječ po anđelima izrečena bila čvrsta te je svaki prijestup i neposluh primio pravednu plaću,');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (65, 2, 3, 'kako li ćemo mi umaći ako zanemarimo toliko spasenje? Spasenje koje je počeo propovijedati Gospodin, koje su nam potvrdili slušatelji,');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (65, 2, 4, 'a suposvjedočio Bog znamenjima i čudesima, najrazličitijim silnim djelima i darivanjima Duha Svetoga po svojoj volji.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (65, 2, 5, 'Nije doista anđelima podložio budući svijet o kojem govorimo.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (65, 2, 6, 'Netko negdje posvjedoči: Što je čovjek da ga se spominješ, sin čovječji te ga pohađaš.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (65, 2, 7, 'Ti ga tek za malo učini manjim od anđela, slavom i časti njega ovjenča,');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (65, 2, 8, 'njemu pod noge sve podloži. Kad mu, doista, sve podloži, ništa ne ostavi što mu ne bi bilo podloženo. Sad još ne vidimo da mu je sve podloženo,');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (65, 2, 9, 'ali Njega, za malo manjeg od anđela, Isusa, vidimo zbog pretrpljene smrti slavom i časti ovjenčana da milošću Božjom bude svakome na korist što je on smrt okusio.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (65, 2, 10, 'Dolikovalo je doista da Onaj radi kojega je sve i po kojemu je sve - kako bi mnoge sinove priveo k slavi - po patnjama do savršenstva dovede Početnika njihova spasenja.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (65, 2, 11, 'Ta i Posvetitelj i posvećeni - svi su od jednoga! Zato se on i ne stidi zvati ih braćom,');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (65, 2, 12, 'kad veli: Braći ću svojoj naviještat ime tvoje, hvalit ću te usred zbora.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (65, 2, 13, 'I još: Ja ću se u njega uzdati, i još: Evo, ja i djeca koju mi Bog dade.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (65, 2, 14, 'Pa budući da djeca imaju zajedničku krv i meso, i sam on tako postade u tome sudionikom da smrću obeskrijepi onoga koji imaše moć smrti, to jest đavla,');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (65, 2, 15, 'pa oslobodi one koji - od straha pred smrću - kroza sav život bijahu podložni ropstvu.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (65, 2, 16, 'Ta ne zauzima se dašto za anđele, nego se zauzima za potomstvo Abrahamovo.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (65, 2, 17, 'Stoga je trebalo da u svemu postane braći sličan, da milosrdan bude i ovjerovljen Veliki svećenik u odnosu prema Bogu kako bi okajavao grijehe naroda.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (65, 2, 18, 'Doista, u čemu je iskušan trpio, može iskušavanima pomoći.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (65, 3, 1, 'Stoga, braćo sveta, sudionici nebeskoga poziva, promotrite Apostola i Velikoga svećenika naše vjere - Isusa:');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (65, 3, 2, 'on je ovjerovljen kod Onoga koji ga postavi kao ono i Mojsije u svoj kući njegovoj.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (65, 3, 3, 'Dostojan je doista toliko veće slave od Mojsija koliko veću čast od kuće ima onaj tko ju je sagradio.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (65, 3, 4, 'Jer svaku kuću tkogod gradi, a sve je sagradio Bog.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (65, 3, 5, 'Da, i Mojsije bijaše ovjerovljen u svoj kući njegovoj kao služnik da posvjedoči za ono što je imalo biti rečeno,');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (65, 3, 6, 'ali Krist - kao Sin, nad kućom njegovom. Njegova smo kuća mi ako sačuvamo smjelost i ponos nade.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (65, 3, 7, 'Zato, kao što veli Duh Sveti: Danas ako glas mu čujete,');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (65, 3, 8, 'ne budite srca tvrda kao u Pobuni, kao u dan iskušenja u pustinji');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (65, 3, 9, 'gdje me kušnjom iskušavahu očevi vaši premda gledahu djela moja');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (65, 3, 10, 'četrdeset godina. Zato mi dodija naraštaj onaj pa rekoh: Uvijek su nestalna srca i ne proniču moje putove.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (65, 3, 11, 'Tako se zakleh u svom gnjevu: Nikad neće ući u moj počinak!');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (65, 3, 12, 'Pazite, braćo, da ne bi u koga od vas srce bilo opako, nevjerno, odmetnulo se od Boga živoga.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (65, 3, 13, 'Pače hrabrite jedni druge dan za danom dok još odjekuje ono Danas da ne otvrdne tko od vas zaveden grijehom.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (65, 3, 14, 'Doista, sudionici smo Kristovi postali ako, dakako, ono prvo imanje stalnim sačuvamo');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (65, 3, 15, 'kad je rečeno: Danas ako glas mu čujete, ne budite srca tvrda kao u Pobuni!');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (65, 3, 16, 'Jer, koji su to čuli pa se pobunili? Zar ne svi koji su pod Mojsijem izašli iz Egipta?');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (65, 3, 17, 'Koji li mu dodijavahu četrdeset godina? Zar ne oni koji sagriješiše, kojih mrtva tijela popadaše u pustinji?');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (65, 3, 18, 'Kojima se zakle da neće ući u njegov počinak, ako li ne nepokornima?');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (65, 3, 19, 'I vidimo da ne mogoše ući zbog nevjere.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (65, 4, 1, 'Bojmo se dakle da se, dok ostaje obećanje o ulasku u njegov Počinak, za koga od vas ne bi utvrdilo kako je zakasnio.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (65, 4, 2, 'Jer nama je naviještena blagovijest kao i njima, ali njima Riječ poruke nije uskoristila jer se vjerom nisu pridružili onima koji su poslušali.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (65, 4, 3, 'U Počinak doista ulazimo mi koji povjerovasmo, prema onom što je rekao: Tako se zakleh u svom gnjevu: Nikad neće ući u moj počinak, premda su djela od postanka svijeta dovršena.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (65, 4, 4, 'Rekao je doista negdje o sedmom danu ovako: I počinu Bog sedmoga dana od svih djela svojih.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (65, 4, 5, 'A ovdje opet: Nikad neće ući u moj počinak.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (65, 4, 6, 'Preostaje dakle da neki imaju u nj ući, a oni koji su prvi primili blagovijest ne uđoše zbog nepokornosti.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (65, 4, 7, 'Zato Bog ponovno određuje jedan dan, Danas, u Davidu nakon toliko vremena govoreći, kako je već rečeno: Danas ako glas mu čujete, ne budite srca tvrda.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (65, 4, 8, 'Zbilja, da je Jošua njih u Počinak uveo, ne bi Bog nakon toga govorio o drugome danu.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (65, 4, 9, 'Dakle: preostaje neki subotni počinak narodu Božjemu!');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (65, 4, 10, 'Zaista, tko uđe u njegov počinak, počinuo je od djela svojih kao ono i Bog od svojih.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (65, 4, 11, 'Pohitimo dakle ući u taj Počinak da nitko ne padne po uzoru na takvu nepokornost.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (65, 4, 12, 'Živa je, uistinu, Riječ Božja i djelotvorna; oštrija je od svakoga dvosjekla mača; prodire dotle da dijeli dušu i duh, zglobove i moždinu te prosuđuje nakane i misli srca.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (65, 4, 13, 'Nema stvorenja njoj skrivena. Sve je, naprotiv, golo i razgoljeno očima Onoga komu nam je dati račun.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (65, 4, 14, 'Imajući dakle velikoga Velikog svećenika koji prodrije kroz nebesa - Isusa, Sina Božjega - čvrsto se držimo vjere.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (65, 4, 15, 'Ta nemamo takva Velikog svećenika koji ne bi mogao biti supatnik u našim slabostima, nego poput nas iskušavana svime, osim grijehom.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (65, 4, 16, 'Pristupajmo dakle smjelo Prijestolju milosti da primimo milosrđe i milost nađemo za pomoć u pravi čas!');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (65, 5, 1, 'Svaki veliki svećenik, zaista, od ljudi uzet, za ljude se postavlja u odnosu prema Bogu da prinosi darove i žrtve za grijehe.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (65, 5, 2, 'On može primjereno suosjećati s onima koji su u neznanju i zabludi jer je i sam zaogrnut slabošću.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (65, 5, 3, 'Zato mora i za narod i za sebe prinositi okajnice.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (65, 5, 4, 'I nitko sam sebi ne prisvaja tu čast, nego je prima od Boga, pozvan kao Aron.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (65, 5, 5, 'Tako i Krist ne proslavi sam sebe postavši svećenik, nego ga proslavi Onaj koji mu reče: Ti si sin moj, danas te rodih,');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (65, 5, 6, 'po onome što pak drugdje veli: Zauvijek ti si svećenik po redu Melkisedekovu.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (65, 5, 7, 'On je u dane svoga zemaljskog života sa silnim vapajem i suzama prikazivao molitve i prošnje Onomu koji ga je mogao spasiti od smrti. I bi uslišan zbog svoje predanosti:');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (65, 5, 8, 'premda je Sin, iz onoga što prepati, naviknu slušati');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (65, 5, 9, 'i, postigavši savršenstvo, posta svima koji ga slušaju začetnik vječnoga spasenja -');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (65, 5, 10, 'proglašen od Boga Velikim svećenikom po redu Melkisedekovu.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (65, 5, 11, 'O tome nas čeka besjeda velika, ali teško ju je riječima izložiti jer ste tvrdih ušiju.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (65, 5, 12, 'Pa trebalo bi doista da nakon toliko vremena već budete učitelji, a ono treba da tkogod vas ponovno poučava početnička počela kazivanja Božjih. Takvi ste: mlijeka vam treba, a ne tvrde hrane.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (65, 5, 13, 'Doista, tko je god još pri mlijeku, ne zna ništa o nauku pravednosti jer - nejače je.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (65, 5, 14, 'A za zrele je tvrda hrana, za one koji imaju iskustvom izvježbana čula za rasuđivanje dobra i zla.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (65, 6, 1, 'Stoga mimoiđimo početnički nauk o Kristu i uzdignimo se k savršenome ne postavljajući iznovice temelja: obraćenje od mrtvih djela i vjera u Boga,');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (65, 6, 2, 'naučavanje o krštenjima i polaganje ruku, uskrsnuće mrtvih i vječni sud.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (65, 6, 3, 'To ćemo pak učiniti, dakako, ako Bog da.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (65, 6, 4, 'Zaista, onima koji su jednom prosvijetljeni, i okusili dar nebeski, i postali dionici Duha Svetoga,');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (65, 6, 5, 'i okusili Lijepu riječ Božju i snage budućega svijeta,');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (65, 6, 6, 'pa otpali, nemoguće je opet se obnoviti na obraćenje kad oni sami ponovno razapinju Sina Božjega i ruglu ga izvrgavaju.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (65, 6, 7, 'Jer zemlja koja se napije kiše što na nju često pada i rađa raslinjem korisnim onima za koje se i obrađuje, prima blagoslov od Boga;');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (65, 6, 8, 'ona pak koja donosi trnje i drač, odbačena je, blizu prokletstvu a svršetak joj je: \"U oganj!\"');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (65, 6, 9, 'A uvjereni smo, ljubljeni, sve ako tako i govorimo, da je s vama dobro i da ste na putu spasenja.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (65, 6, 10, 'Ta Bog nije nepravedan da bi zaboravio vaše djelo i ljubav što je iskazaste njegovu imenu posluživši i poslužujući svetima.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (65, 6, 11, 'Želimo ipak da svatko od vas sve do svršetka pokazuje tu istu gorljivost za ispunjenje nade');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (65, 6, 12, 'te ne omlitavite, nego budete nasljedovatelji onih koji po vjeri i strpljivosti baštine obećano.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (65, 6, 13, 'Doista, kad je Bog Abrahamu davao obećanje, jer se nije imao kime većim zakleti, zakle se samim sobom:');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (65, 6, 14, 'Uistinu, blagosloviti, blagoslovit ću te i umnožiti, umnožit ću te.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (65, 6, 15, 'I tako Abraham, strpljiv, postiže obećano.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (65, 6, 16, 'Ljudi se doista kunu onim tko je veći i zakletva im je, kao potkrepa, kraj svake raspre.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (65, 6, 17, 'Tako i Bog: htio je baštinicima obećanja obilatije pokazati nepromjenljivost svoje odluke pa zato zajamči zakletvom');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (65, 6, 18, 'da bismo po dva nepromjenljiva čina - u kojima je nemoguće da bi Bog prevario - mi pribjeglice imali snažno ohrabrenje da se držimo ponuđene nade.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (65, 6, 19, 'Ona nam je kao pouzdano i čvrsto sidro duše što ulazi u unutrašnjost iza zavjese,');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (65, 6, 20, 'kamo je kao preteča za nas ušao Isus postavši zauvijek Veliki svećenik po redu Melkisedekovu.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (65, 7, 1, 'Doista, taj Melkisedek, kralj šalemski, svećenik Boga Svevišnjega što je izašao u susret Abrahamu koji se vraćao s poraza kraljeva i blagoslovio ga,');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (65, 7, 2, 'i komu Abraham odijeli desetinu od svega; on koji u prijevodu znači najprije \"kralj pravednosti\", a zatim i kralj šalemski, to jest \"kralj mira\";');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (65, 7, 3, 'on, bez oca, bez majke, bez rodoslovlja; on, kojemu dani nemaju početka ni život kraja - sličan Sinu Božjemu, ostaje svećenik zasvagda.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (65, 7, 4, 'Pa promotrite koliki li je taj komu Abraham, rodozačetnik, dade desetinu od najboljega.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (65, 7, 5, 'Istina, i oni sinovi Levijevi, koji primaju svećeništvo imaju zakonsku zapovijed da ubiru desetinu od naroda, to jest od svoje braće premda su i ona izašla iz boka Abrahamova.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (65, 7, 6, 'Ali on, koji nije iz njihova rodoslovlja, ubra desetinu od Abrahama i blagoslovi njega, nosioca obećanja!');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (65, 7, 7, 'A posve je neprijeporno: veći blagoslivlja manjega.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (65, 7, 8, 'K tome, ovdje desetinu primaju smrtni ljudi, a ondje onaj, za kojega se svjedoči da živi.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (65, 7, 9, 'I u Abrahamu se, tako reći, ubire desetina i od Levija koji inače desetinu prima');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (65, 7, 10, 'jer još bijaše u boku očevu kad mu u susret iziđe Melkisedek.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (65, 7, 11, 'Da se dakle savršenstvo postiglo po levitskom svećeništvu - jer na temelju njega narod je dobio Zakon - koja bi onda bila potreba da se po redu Melkisedekovu postavi drugi svećenik i da se ne imenuje po redu Aronovu?');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (65, 7, 12, 'Doista kad se mijenja svećeništvo, nužno se mijenja i Zakon.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (65, 7, 13, 'Jer onaj o kojemu se to veli pripadao je drugom plemenu, od kojega se nitko nije posvetio žrtveniku.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (65, 7, 14, 'Poznato je da je Gospodin naš potekao od Jude, plemena za koje Mojsije ništa ne reče s obzirom na svećenike.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (65, 7, 15, 'To je još očitije ako se drugi svećenik postavlja po sličnosti s Melkisedekom:');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (65, 7, 16, 'postao je svećenikom ne po Zakonu tjelesne uredbe, nego snagom neuništiva života.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (65, 7, 17, 'Ta svjedoči se: Zauvijek ti si svećenik po redu Melkisedekovu.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (65, 7, 18, 'Dokida se dakle prijašnja uredba zbog njezine nemoći i beskorisnosti -');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (65, 7, 19, 'jer Zakon nije ništa priveo k savršenstvu - a uvodi se bolja nada, po kojoj se približujemo Bogu.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (65, 7, 20, 'I to se nije zbilo bez zakletve. Jer oni su bez zakletve postali svećenicima,');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (65, 7, 21, 'a on sa zakletvom Onoga koji mu reče: Zakleo se Gospodin i neće se pokajati: \"Zauvijek ti si svećenik\".');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (65, 7, 22, 'Utoliko je Isus i postao jamac boljega Saveza.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (65, 7, 23, 'K tomu, mnogo je bilo svećenika jer ih je smrt priječila trajno ostati.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (65, 7, 24, 'A on, jer ostaje dovijeka, ima neprolazno svećeništvo.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (65, 7, 25, 'Zato i može do kraja spasavati one koji po njemu pristupaju k Bogu - uvijek živ da se za njih zauzima.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (65, 7, 26, 'Takav nam Veliki svećenik i bijaše potreban - svet, nedužan, neokaljan, odijeljen od grešnika i uzvišeniji od nebesa -');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (65, 7, 27, 'koji ne treba da kao oni veliki svećenici danomice prinosi žrtve najprije za svoje grijehe, a onda za grijehe naroda. To on učini jednom prinijevši samoga sebe.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (65, 7, 28, 'Zakon doista postavi za velike svećenike ljude podložne slabosti, a riječ zakletve - nakon Zakona - Sina zauvijek usavršena.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (65, 8, 1, 'A glavno u ovom izlaganju jest: takva imamo Velikog svećenika koji sjede zdesna prijestolja Veličanstva na nebesima');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (65, 8, 2, 'kao bogoslužnik Svetinje i Šatora istinskoga što ga podiže Gospodin, a ne čovjek.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (65, 8, 3, 'Doista, svaki se veliki svećenik postavlja da prinosi darove i žrtve. Odatle je potrebno da i on ima što bi prinio.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (65, 8, 4, 'Svakako, da je na zemlji, ne bi bio svećenik jer postoje oni koji po Zakonu prinose darove.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (65, 8, 5, 'Oni služe slici i sjeni onoga nebeskoga, kako je upućen Mojsije kad se spremao praviti šator: Pazi, veli doista, načini sve po praliku koji ti je pokazan na brdu.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (65, 8, 6, 'Ovako mu pak dopalo uzvišenije bogosluženje koliko je Posrednik boljega Saveza, koji je uzakonjen na boljim obećanjima.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (65, 8, 7, 'Da je, zbilja, onaj prvi bio besprijekoran, ne bi se drugome tražilo mjesto.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (65, 8, 8, 'Doista, kudeći ih veli: Evo dolaze dani - govori Gospodin - kad ću s domom Izraelovim i s domom Judinim dovršiti novi Savez.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (65, 8, 9, 'Ne Savez kakav učinih s ocima njihovim u dan kad ih uzeh za ruku da ih izvedem iz zemlje egipatske jer oni ne ustrajaše u mom Savezu pa i ja zanemarih njih - govori Gospodin.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (65, 8, 10, 'Nego, ovo je Savez kojim ću se svezati s domom Izraelovim nakon ovih dana - govori Gospodin: Zakone ću svoje staviti u dušu njihovu i upisati ih u njihova srca. I bit ću Bog njihov, a oni narod moj.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (65, 8, 11, 'I neće više nitko učiti sugrađanina i nitko brata svoga govoreći: \"Spoznaj Gospodina\", ta svi će me poznavati, malo i veliko,');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (65, 8, 12, 'jer ću se smilovati bezakonjima njihovim i grijeha se njihovih neću više spominjati.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (65, 8, 13, 'Kad veli novi, ostari onaj prvi. Što pak stÓari i dotrajava, blizu je nestanku.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (65, 9, 1, 'I onaj prvi je, svakako, imao bogoštovne uredbe i Svetinju, ali ovosvjetsku.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (65, 9, 2, 'Šator je uistinu bio uređen: prvi, u kojem bijaše svijećnjak, stol i prinos kruhova, a zove se Svetinja;');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (65, 9, 3, 'iza druge pak zavjese bio je Šator zvan Svetinja nad svetinjama -');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (65, 9, 4, 'u njoj zlatni kadionik i Kovčeg saveza, sav optočen zlatom, a u njemu zlatna posuda s manom i štap Aronov, koji je ono procvao, i ploče Saveza;');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (65, 9, 5, 'povrh njega pak kerubi Slave što osjenjuju Pomirilište. O tom ne treba sada potanko govoriti.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (65, 9, 6, 'Pošto je to tako uređeno, u prvi Šator stalno ulaze svećenici obavljati bogoslužje,');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (65, 9, 7, 'a u drugi jednom godišnje samo veliki svećenik, i to ne bez krvi koju prinosi za sebe i za nepažnje naroda.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (65, 9, 8, 'Time Duh Sveti očituje da još nije otkriven put u Svetinju dok još postoji prvi Šator.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (65, 9, 9, 'To je slika za sadašnje vrijeme: prinose se darovi i žrtve koje ne mogu u savjesti usavršiti bogoslužnika -');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (65, 9, 10, 'sve same na ićima i pićima i raznim pranjima utemeljene tjelesne uredbe, nametnute do časa ispravka.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (65, 9, 11, 'Krist se pak pojavi kao Veliki svećenik budućih dobara pa po većem i savršenijem Šatoru - nerukotvorenu, koji nije od ovoga stvorenja -');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (65, 9, 12, 'i ne po krvi jaraca i junaca, nego po svojoj uđe jednom zauvijek u Svetinju i nađe vječno otkupljenje.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (65, 9, 13, 'Doista, ako već poškropljena krv jaraca i bikova i pepeo juničin posvećuje onečišćene, daje tjelesnu čistoću,');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (65, 9, 14, 'koliko će više krv Krista - koji po Duhu vječnom samoga sebe bez mane prinese Bogu - očistiti savjest našu od mrtvih djela, na službu Bogu živomu!');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (65, 9, 15, 'A radi ovoga je Posrednik novoga Saveza: da po smrti za otkupljenje prekršaja iz starog Saveza pozvani zadobiju obećanu vječnu baštinu.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (65, 9, 16, 'Jer gdje je posrijedi savez-oporuka, potrebno je dokazati smrt oporučitelja.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (65, 9, 17, 'Oporuka je doista valjana tek nakon smrti: nikad ne vrijedi dok oporučitelj živi.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (65, 9, 18, 'Stoga ni onaj prvi Savez nije bez krvi ustanovljen.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (65, 9, 19, 'Pošto je svemu narodu priopćio svaku zapovijed zakonsku, uze Mojsije krv junaca i jaraca s vodom i grimiznom vunom i izopom te samu Knjigu i sav narod poškropi');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (65, 9, 20, 'govoreći: Ovo je krv Saveza koji vam odredi Bog;');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (65, 9, 21, 'a onda krvlju slično poškropi i Šator i sve bogoslužno posuđe.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (65, 9, 22, 'I gotovo se sve po zakonu čisti krvlju i bez prolijevanja krvi nema oproštenja.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (65, 9, 23, 'Ako se dakle time čiste slike onoga što je na nebu, potrebno je da se samo to nebesko čisti žrtvama od tih uspješnijima.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (65, 9, 24, 'Krist doista ne uđe u rukotvorenu Svetinju, protulik one istinske, nego u samo nebo: da se sada pojavi pred licem Božjim za nas.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (65, 9, 25, 'Ne da mnogo puta prinosi samoga sebe kao što veliki svećenik svake godine ulazi u Svetinju s tuđom krvlju;');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (65, 9, 26, 'inače bi bilo trebalo da trpi mnogo puta od postanka svijeta. No sada se pojavio, jednom na svršetku vjekova, da grijeh dokine žrtvom svojom.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (65, 9, 27, 'I kao što je ljudima jednom umrijeti, a potom na sud,');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (65, 9, 28, 'tako i Krist: jednom se prinese da grijehe mnogih ponese, a drugi će se put - bez obzira na grijeh - ukazati onima koji ga iščekuju sebi na spasenje.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (65, 10, 1, 'Budući da Zakon ima tek sjenu budućih dobara, a ne sam lik zbiljnosti, on uistinu žrtvama koje se - iz godine u godinu iste - neprestano prinose ne može nikada usavršiti one što pristupaju.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (65, 10, 2, 'Ta ne bi li se prestale prinositi kad bogoslužnici, jednom očišćeni, ne bi više imali nikakve svijesti grijeha?');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (65, 10, 3, 'Ali po njima se iz godine u godinu podsjeća na grijehe.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (65, 10, 4, 'Jer krv bikova i jaraca nikako ne može odnijeti grijeha.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (65, 10, 5, 'Zato On ulazeći u svijet veli: Žrtva i prinos ne mile ti se, nego si mi tijelo pripravio;');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (65, 10, 6, 'paljenice i okajnice ne sviđaju ti se.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (65, 10, 7, 'Tada rekoh: \"Evo dolazim!\" U svitku knjige piše za mene: \"Vršiti, Bože, volju tvoju!\"');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (65, 10, 8, 'Pošto gore reče: Žrtve i prinosi, paljenice i okajnice - koje se po Zakonu prinose - ne mile ti se i ne sviđaju,');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (65, 10, 9, 'veli zatim: Evo dolazim vršiti volju tvoju! Dokida prvo da uspostavi drugo.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (65, 10, 10, 'U toj smo volji posvećeni prinosom tijela Isusa Krista jednom zauvijek.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (65, 10, 11, 'I svaki je svećenik dan za danom u bogoslužju te učestalo prinosi iste žrtve, koje nikako ne mogu odnijeti grijeha.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (65, 10, 12, 'A ovaj, pošto je prinio jednu jedincatu žrtvu za grijehe, zauvijek sjede zdesna Bogu');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (65, 10, 13, 'čekajući otad dok se neprijatelji ne podlože za podnožje nogama njegovim.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (65, 10, 14, 'Jednim uistinu prinosom zasvagda usavrši posvećene.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (65, 10, 15, 'A to nam svjedoči i Duh Sveti. Pošto je doista rekao:');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (65, 10, 16, '\"Ovo je Savez kojim ću se svezati s njima nakon ovih dana\", Gospodin govori: \"Zakone ću svoje staviti u njihova srca i upisati ih u dušu njihovu.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (65, 10, 17, 'I grijeha se njihovih i bezakonja njihovih neću više spominjati.\"');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (65, 10, 18, 'A gdje su grijesi oprošteni, nema više prinosa za njih.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (65, 10, 19, 'Imamo dakle, braćo, slobodan ulaz u Svetinju po krvi Isusovoj -');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (65, 10, 20, 'put nov i živ što nam ga On otvori kroz zavjesu, to jest svoje tijelo;');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (65, 10, 21, 'imamo i Velikog svećenika nad kućom Božjom.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (65, 10, 22, 'Pristupajmo stoga s istinitim srcem u punini vjere, srdaca škropljenjem očišćenih od zle savjesti i tijela oprana čistom vodom.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (65, 10, 23, 'Čuvajmo nepokolebljivu vjeru nade jer je vjeran Onaj koji dade obećanje.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (65, 10, 24, 'I pazimo jedni na druge da se potičemo na ljubav i dobra djela');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (65, 10, 25, 'te ne propuštamo svojih sastanaka, kako je u nekih običaj, nego se hrabrimo, to više što više vidite da se bliži Dan.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (65, 10, 26, 'Jer ako svojevoljno griješimo pošto primismo spoznanje istine, nema više žrtve za grijehe,');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (65, 10, 27, 'nego strašno isčekivanje suda i bijesa ognja što će proždrijeti protivnike.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (65, 10, 28, 'Je li tko prekršio Zakon Mojsijev, bez milosrđa biva pogubljen na osnovi dvojice ili trojice svjedoka.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (65, 10, 29, 'Zamislite koliko li će goru kaznu zavrijediti tko Sina Božjega pogazi, i nečistom smatra krv Saveza kojom je posvećen, i Duha milosti pogrdi?');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (65, 10, 30, 'Ta poznajemo Onoga koji je rekao: Moja je odmazda, ja ću je vratiti; i još: Sudit će Gospodin svome puku.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (65, 10, 31, 'Strašno je upasti u ruke Boga živoga.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (65, 10, 32, 'A spomenite se onih prvih dana kada ste, tek prosvijetljeni, izdržali veliku patničku borbu:');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (65, 10, 33, 'ovamo javno izvrgnuti porugama i nevoljama, onamo postavši zajedničari onih s kojima se tako postupalo.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (65, 10, 34, 'I doista, sa sužnjevima ste suosjećali i s radošću prihvatili otimanje dobara znajući da imate bolji, trajan posjed.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (65, 10, 35, 'Ne gubite dakle pouzdanja! Pripada mu velika plaća!');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (65, 10, 36, 'Postojanosti vam uistinu treba da biste vršeći volju Božju zadobili obećano.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (65, 10, 37, 'Jer još malo, sasvim malo, i Onaj koji dolazi doći će i neće zakasniti');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (65, 10, 38, 'A pravednik će moj od vjere živjeti, ako li pak otpadne, ne mili se on duši mojoj.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (65, 10, 39, 'A mi nismo od onih koji otpadaju, sebi na propast, nego od onih koji vjeruju na spas duše.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (65, 11, 1, 'A vjera je već neko imanje onoga čemu se nadamo, uvjerenost u zbiljnosti kojih ne vidimo.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (65, 11, 2, 'Zbog nje stari primiše svjedočanstvo.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (65, 11, 3, 'Vjerom spoznajemo da su svjetovi uređeni riječju Božjom tako te ovo vidljivo ne posta od nečega pojavnoga.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (65, 11, 4, 'Vjerom Abel prinese Bogu bolju žrtvu nego Kain. Po njoj primi svjedočanstvo da je pravedan - Bog nad njegovim darovima posvjedoči - po njoj i mrtav još govori.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (65, 11, 5, 'Vjerom Henok bi prenesen da ne vidi smrti te iščeznu jer ga je prenio Bog. Doista, prije prijenosa primio je svjedočanstvo da omilje Bogu.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (65, 11, 6, 'A bez vjere nemoguće je omiljeti Bogu jer tko mu pristupa, vjerovati mora da postoji i da je platac onima koji ga traže.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (65, 11, 7, 'Vjerom Noa, upućen u ono što još ne bijaše vidljivo, predano sagradi korablju na spasenje svoga doma. Time osudi svijet i postade baštinikom vjerničke pravednosti.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (65, 11, 8, 'Vjerom pozvan, Abraham posluša i zaputi se u kraj koji je imao primiti u baštinu, zaputi se ne znajući kamo ide.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (65, 11, 9, 'Vjerom se kao pridošlica naseli u obećanoj zemlji kao u tuđini, prebivajući pod šatorima s Izakom i Jakovom, subaštinicima istog obećanja,');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (65, 11, 10, 'jer iščekivaše onaj utemeljeni Grad kojemu je graditelj i tvorac Bog.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (65, 11, 11, 'Vjerom i Sara unatoč svojoj dobi zadobi moć da začne jer vjernim smatraše Onoga koji joj dade obećanje.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (65, 11, 12, 'Zato od jednoga, i to obamrla, nasta mnoštvo poput zvijezda na nebu i pijeska nebrojena na obali morskoj.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (65, 11, 13, 'U vjeri svi su oni umrli, a da nisu zadobili obećanja, već su ih samo izdaleka vidjeli i pozdravili priznavši da su stranci i pridošlice na zemlji.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (65, 11, 14, 'Doista, koji tako govore, jasno očituju da domovinu traže.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (65, 11, 15, 'Dakako, da su mislili na onu iz koje su izišli, imali bi još prilike vratiti se u nju.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (65, 11, 16, 'Ali sada oni čeznu za boljom, to jest nebeskom. Stoga se Bog ne stidi zvati se Bogom njihovim: ta pripravio im je Grad.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (65, 11, 17, 'Vjerom Abraham, kušan, prikaza Izaka. Jedinca prikazivaše on koji je primio obećanje,');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (65, 11, 18, 'kome bi rečeno: Po Izaku će ti se nazivati potomstvo! -');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (65, 11, 19, 'uvjeren da Bog može i od mrtvih uskrisiti. Zato ga u predslici i ponovno zadobi.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (65, 11, 20, 'Vjerom baš u pogledu budućnosti Izak blagoslovi Jakova i Ezava.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (65, 11, 21, 'Vjerom Jakov, umirući, blagoslovi oba sina Josipova i duboko se prignu oslonjen na vrh svojega štapa.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (65, 11, 22, 'Vjerom Josip na umoru napomenu ono o izlasku sinova Izraelovih i dade zapovijed o svojim kostima.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (65, 11, 23, 'Vjerom su Mojsija netom rođena tri mjeseca krili njegovi roditelji jer vidješe da je djetešce lijepo i nisu se bojali kraljeve naredbe.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (65, 11, 24, 'Vjerom Mojsije, već odrastao, odbi zvati se sinom kćeri faraonove.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (65, 11, 25, 'Radije izabra biti zlostavljan zajedno s Božjim narodom, nego se časovito okoristiti grijehom.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (65, 11, 26, 'Većim je bogatstvom od blaga egipatskih smatrao muku Kristovu jer je gledao na plaću.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (65, 11, 27, 'Vjerom napusti Egipat, ne bojeći se bijesa kraljeva, postojan kao da Nevidljivoga vidi.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (65, 11, 28, 'Vjerom je obavio pashu i škropljenje krvlju da Zatornik ne dotakne prvenaca Izraelovih.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (65, 11, 29, 'Vjerom prođoše Crvenim morem kao po suhu, što i Egipćani pokušaše, ali se potopiše.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (65, 11, 30, 'Vjerom zidine jerihonske padoše nakon sedmodnevnoga ophoda.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (65, 11, 31, 'Vjerom Rahaba, bludnica, ne propade zajedno s nepokornicima jer s mirom primi uhode.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (65, 11, 32, 'I što još da kažem? Ta ponestat će mi vremena, počnem li raspredati o Gideonu, Baraku, Samsonu, Jiftahu, Davidu, pa Samuelu i prorocima,');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (65, 11, 33, 'koji su po vjeri osvojili kraljevstva, odjelotvorili pravednost, zadobili obećano, začepili ralje lavovima,');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (65, 11, 34, 'pogasili žestinu ognja, umakli oštrici mača, oporavili se od slabosti, ojačali u boju, odbili navale tuđinaca.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (65, 11, 35, 'Žene su po uskrsnuću ponovno zadobile svoje pokojne. Drugi pak, stavljeni na muke, ne prihvatiše oslobođenja da bi ih zapalo bolje uskrsnuće.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (65, 11, 36, 'Drugi su opet iskusili izrugivanja i bičeve, pa i okove i tamnicu.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (65, 11, 37, 'Kamenovani su, piljeni, poubijani oštricom mača, potucali se u runima, u kozjim kožusima, u oskudici, potlačeni, zlostavljani -');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (65, 11, 38, 'svijet ih ne bijaše dostojan - vrludali po pustinjama, gorama, pećinama i pukotinama zemaljskim.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (65, 11, 39, 'I svi oni po vjeri, istina, primiše svjedočanstvo, ali ne zadobiše obećano');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (65, 11, 40, 'jer Bog je za nas predvidio nešto bolje da oni bez nas ne dođu do savršenstva.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (65, 12, 1, 'Zato i mi, okruženi tolikim oblakom svjedoka, odložimo svaki teret i grijeh koji nas sapinje te postojano trčimo u borbu koja je pred nama!');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (65, 12, 2, 'Uprimo pogled u Početnika i Dovršitelja vjere, Isusa, koji umjesto radosti što je stajala pred njim podnese križ, prezrevši sramotu te sjedi zdesna prijestolja Božjega.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (65, 12, 3, 'Doista pomno promotrite njega, koji podnese toliko protivljenje grešnika protiv sebe, da - premoreni - ne klonete duhom.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (65, 12, 4, 'Ta još se do krvi ne oduprijeste u borbi protiv grijeha.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (65, 12, 5, 'Pa zar ste zaboravili opomenu koja vam je kao sinovima upravljena: Sine moj, ne omalovažavaj stege Gospodnje i ne kloni kad te on ukori.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (65, 12, 6, 'Jer koga Gospodin ljubi, onoga i stegom odgaja, šiba sina koga voli.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (65, 12, 7, 'Poradi vašega odgajanja trpite. Bog s vama postupa kao sa sinovima: a ima li koji sin kojega otac stegom ne odgaja?');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (65, 12, 8, 'Pa ako niste pod stegom, na kojoj su svi imali udjela, onda ste kopilad, a ne djeca.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (65, 12, 9, 'Zatim, tjelesne smo oce imali odgojiteljima i poštovali ih. Pa nećemo li se kudikamo više podlagati Ocu duhova te živjeti?');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (65, 12, 10, 'Oni su nas doista nešto malo dana stegom odgajali kako se njima činilo, a On - nama na korist, da postanemo sudionici njegove svetosti.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (65, 12, 11, 'Isprva se doduše čini da nijedno odgajanje nije radost, nego žalost, ali onima koji su njime uvježbani poslije donosi mironosni plod pravednosti.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (65, 12, 12, 'Zato uspravite ruke klonule i koljena klecava,');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (65, 12, 13, 'poravnite staze za noge svoje da se hromo ne iščaši, nego, štoviše, da ozdravi.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (65, 12, 14, 'Nastojte oko mira sa svima! I oko posvećenja bez kojega nitko neće vidjeti Gospodina!');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (65, 12, 15, 'Pripazite da se tko ne sustegne od milosti Božje, da kakav gorki korijen ne proklija pa ne unese zabunu i ne zarazi mnoge,');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (65, 12, 16, 'da tko ne postane bludnik ili svetogrdnik kao Ezav, koji za jedan jedini obrok proda svoje prvorodstvo.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (65, 12, 17, 'Ta znate da je i poslije, kad je htio baštiniti blagoslov, odbačen jer nije našao mogućnosti promjene premda ju je sa suzama tražio.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (65, 12, 18, 'Jer niste pristupili opipljivoj gori i usplamtjelu ognju, ni mraku, tami i vihoru,');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (65, 12, 19, 'ni ječanju trublje i tutnjavi riječi. - Koji su je slušali, zamoliše da im se više ne govori');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (65, 12, 20, 'jer nisu podnosili naredbe: Ako se ma i živinče dotakne brda, neka se kamenuje!');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (65, 12, 21, 'I prizor bijaše tako strašan da Mojsije reče: \"Strah me je i dršćem!\" -');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (65, 12, 22, 'Nego, vi ste pristupili gori Sionu i gradu Boga živoga, Jeruzalemu nebeskom, nebrojenim tisućama anđela, svečanom skupu,');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (65, 12, 23, 'Crkvi prvorođenaca zapisanih na nebu, Bogu, sucu sviju, dusima savršenih pravednika');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (65, 12, 24, 'i Posredniku novog Saveza - Isusu - i krvi škropljeničkoj što snažnije govori od Abelove.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (65, 12, 25, 'Pazite da ne odbijete Onoga koji vam govori! Jer ako ne umakoše oni što su odbili onoga koji je na zemlji davao upute, kudikamo ćemo manje mi ako se okrenemo od Onoga koji ih daje s nebesa.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (65, 12, 26, 'Njegov glas tada zemlju uzdrma, sada pak obećava: Još jednom ja ću potresti ne samo zemlju nego i nebo.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (65, 12, 27, 'Ono \"još jednom\" pokazuje da će, kao stvoreno, uminuti ono uzdrmano da ostane ono neuzdrmljivo.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (65, 12, 28, 'Zato jer smo primili kraljevstvo neuzdrmljivo, iskazujmo zahvalnost iz koje služimo Bogu kako je njemu milo, s predanjem i strahopoštovanjem.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (65, 12, 29, 'Jer Bog je naš oganj što proždire.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (65, 13, 1, 'Bratoljublje neka je trajno!');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (65, 13, 2, 'Gostoljublja ne zaboravljajte: njime neki, i ne znajući, ugostiše anđele!');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (65, 13, 3, 'Sjećajte se uznika kao suuznici; zlostavljanih - ta i sami ste u tijelu!');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (65, 13, 4, 'Ženidba neka bude u časti u sviju i postelja neokaljana! Jer bludnicima će i preljubnicima suditi Bog.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (65, 13, 5, 'U življenju ne budite srebroljupci, zadovoljni onim što imate! Ta on je rekao: Ne, neću te zapustiti i neću te ostaviti.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (65, 13, 6, 'Zato možemo pouzdano reći: Gospodin mi je pomoćnik, ja ne strahujem: što mi tko može?');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (65, 13, 7, 'Spominjite se svojih glavara koji su vam nevješćivali riječ Božju: promatrajući kraj njihova života, nasljedujte njihovu vjeru.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (65, 13, 8, 'Isus Krist jučer i danas isti je - i uvijeke.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (65, 13, 9, 'Ne dajte se zanijeti različitim tuđim naucima! Jer bolje je srce utvrđivati milošću nego jelima, koja nisu koristila onima što su ih obdržavali.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (65, 13, 10, 'Imamo žrtvenik s kojega nemaju pravo jesti služitelji Šatora.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (65, 13, 11, 'Jer tijela životinja, kojih krv veliki svećenik unosi za grijeh u Svetinju, spaljuju se izvan tabora.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (65, 13, 12, 'Zato i Isus, da bi vlastitom krvlju posvetio narod, trpio je izvan vrata.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (65, 13, 13, 'Stoga iziđimo k njemu izvan tabora noseći njegovu muku');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (65, 13, 14, 'jer nemamo ovdje trajna grada, nego onaj budući tražimo.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (65, 13, 15, 'Po njemu dakle neprestano prinosimo Bogu žrtvu hvalbenu, to jest plod usana što ispovijedaju ime njegovo.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (65, 13, 16, 'Dobrotvornosti i zajedništva ne zaboravljajte jer takve su žrtve mile Bogu!');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (65, 13, 17, 'Poslušni budite svojim glavarima i podložni jer oni bdiju nad vašim dušama kao oni koji će polagati račun; neka to čine s radošću, a ne uzdišući jer vam to ne bi bilo korisno.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (65, 13, 18, 'Molite za nas! Uvjereni smo doista da imamo dobru savjest i u svemu se želimo dobro ponašati.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (65, 13, 19, 'Usrdnije vas pak molim: učinite to kako bih vam se što brže vratio.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (65, 13, 20, 'A Bog mira, koji po krvi vječnoga Saveza od mrtvih izvede velikoga Pastira ovaca, Gospodina našega Isusa,');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (65, 13, 21, 'osposobio vas za svako dobro djelo da vršite volju njegovu, činio u nama što je njemu milo, po Isusu Kristu, komu slava u vijeke vjekova. Amen.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (65, 13, 22, 'Molim vas, braćo, podnesite ovu riječ ohrabrenja: ta samo vam ukratko napisah!');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (65, 13, 23, 'Znajte: naš je brat Timotej oslobođen. Ako uskoro stigne, s njime ću vas pohoditi.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (65, 13, 24, 'Pozdravite sve svoje glavare i sve svete! Pozdravljaju vas ovi iz Italije.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (65, 13, 25, 'Milost sa svima vama!');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (66, 1, 1, 'Jakov, sluga Boga i Gospodina Isusa Krista: dvanaestorma plemena Raseljeništva pozdrav.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (66, 1, 2, 'Pravom radošću smatrajte, braćo moja, kad upadnete u razne kušnje');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (66, 1, 3, 'znajući da prokušanost vaše vjere rađa postojanošću.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (66, 1, 4, 'Ali neka postojanost bude na djelu savršena da budete savršeni i potpuni, bez ikakva nedostataka.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (66, 1, 5, 'Nedostaje li komu od vas mudrosti, neka ište od Boga, koji svima daje rado i bez negodovanja, i dat će mu se.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (66, 1, 6, 'Ali neka ište s vjerom, bez ikakva kolebanja. Jer kolebljivac je sličan morskom valovlju, uzburkanu i gonjenu.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (66, 1, 7, 'Neka takav ne misli da će primiti što od Gospodina -');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (66, 1, 8, 'čovjek duše dvoumne, nepostojan na svim putovima svojim.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (66, 1, 9, 'Neka se brat niska soja ponosi svojim uzvišenjem,');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (66, 1, 10, 'a bogataš svojim poniženjem. Ta proći će kao cvijet trave:');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (66, 1, 11, 'sunce ogranu žarko te usahnu trava i cvijet njezin uvenu; dražest mu lica propade. Tako će i bogataš na stazama svojim usahnuti.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (66, 1, 12, 'Blago čovjeku koji trpi kušnju: prokušan, primit će vijenac života koji je Gospodin obećao onima što ga ljube.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (66, 1, 13, 'Neka nitko u napasti ne rekne: \"Bog me napastuje.\" Ta Bog ne može biti napastovan na zlo, i ne napastuje nikoga.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (66, 1, 14, 'Nego svakoga napastuje njegova požuda koja ga privlači i mami.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (66, 1, 15, 'Požuda zatim, zatrudnjevši, rađa grijehom, a grijeh izvršen rađa smrću.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (66, 1, 16, 'Ne varajte se, braćo moja ljubljena!');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (66, 1, 17, 'Svaki dobar dar, svaki savršen poklon odozgor je, silazi od Oca svjetlila u kome nema promjene ni sjene od mijene.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (66, 1, 18, 'Po svom naumu on nas porodi riječju Istine da budemo prvina neka njegovih stvorova.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (66, 1, 19, 'Znajte, braćo moja ljubljena! Svatko neka bude brz da sluša, spor da govori, spor na srdžbu.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (66, 1, 20, 'Jer srdžba čovjekova ne čini pravde Božje.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (66, 1, 21, 'Zato odložite svaku prljavštinu i preostalu zloću i sa svom krotkošću primite usađenu riječ koja ima moć spasiti duše vaše.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (66, 1, 22, 'Budite vršitelji riječi, a ne samo slušatelji, zavaravajući sami sebe.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (66, 1, 23, 'Jer ako je tko slušatelj riječi, a ne i izvršitelj, sličan je čovjeku koji motri svoje rođeno lice u zrcalu:');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (66, 1, 24, 'promotri se, ode i odmah zaboravi kakav bijaše.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (66, 1, 25, 'A koji se oglÄedÄa u savršenom zakonu slobode i uza nj prione, ne kao zaboravan slušatelj nego djelotvoran izvršitelj, blažen će biti u svem djelovanju svome.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (66, 1, 26, 'Smatra li se tko bogoljubnim, a ne obuzdava svoga jezika, nego zavarava srce svoje, isprazna je njegova bogoljubnost.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (66, 1, 27, 'Bogoljubnost čista i neokaljana jest: zauzimati se za sirote i udovice u njihovoj nevolji, čuvati se neokaljanim od ovoga svijeta.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (66, 2, 1, 'Braćo moja, vjeru Gospodina našega Isusa Krista slavnoga ne miješajte s pristranošću!');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (66, 2, 2, 'Dođe li na vaš sastanak čovjek sa zlatnim prstenjem, u sjajnoj odjeći, a dođe i siromah u bijednoj odjeći');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (66, 2, 3, 'i vi se zagledate u onoga što nosi sjajnu odjeću te reknete: \"Ti lijepo ovdje sjedni!\", a siromahu reknete: \"Ti stani - ili sjedni - ondje, podno podnožja moga!\",');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (66, 2, 4, 'niste li u sebi pristrano sudili te postali suci što naopako sude?');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (66, 2, 5, 'Čujte, braćo moja ljubljena: nije li Bog one koji su svijetu siromašni izabrao da budu bogataši u vjeri i baštinici Kraljevstva što ga je obećao onima koji ga ljube?');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (66, 2, 6, 'A vi prezreste siromaha! Ne tlače li vas upravo bogataši? Ne vuku li vas baš oni na sudove?');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (66, 2, 7, 'Ne psuju li oni lijepo Ime na vas zazvano?');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (66, 2, 8, 'Ako doista izvršujete kraljevski zakon po Pismu: Ljubi bližnjega svoga kao sebe samoga, dobro činite;');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (66, 2, 9, 'ako li ste pristrani, grijeh činite i Zakon vas osuđuje kao prijestupnike.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (66, 2, 10, 'Ta tko sav Zakon uščuva, a u jednome samo posrne, postao je krivac svega.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (66, 2, 11, 'Jer tko reče: Ne čini preljuba, reče i: Ne ubij. Ako dakle i ne činiš preljuba, a ubiješ, postao si prijestupnik Zakona.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (66, 2, 12, 'Tako govorite i tako činite kao oni koji imaju biti suđeni po zakonu slobode.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (66, 2, 13, 'Jer nemilosrdan je sud onomu tko ne čini milosrđa; a milosrđe likuje nad sudom.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (66, 2, 14, 'Što koristi, braćo moja, ako tko rekne da ima vjeru, a djela nema? Može li ga vjera spasiti?');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (66, 2, 15, 'Ako su koji brat ili sestra goli i bez hrane svagdanje');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (66, 2, 16, 'pa im tkogod od vas rekne: \"Hajdete u miru, grijte se i sitite\", a ne dadnete im što je potrebno za tijelo, koja korist?');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (66, 2, 17, 'Tako i vjera: ako nema djela, mrtva je u sebi.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (66, 2, 18, 'Inače, mogao bi tko reći: \"Ti imaš vjeru, a ja imam djela. Pokaži mi svoju vjeru bez djela, a ja ću tebi djelima pokazati svoju vjeru.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (66, 2, 19, 'Ti vjeruješ da je jedan Bog? Dobro činiš! I đavli vjeruju, i dršću.\"');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (66, 2, 20, 'Hoćeš li spoznati, šuplja glavo, da je vjera bez djela jalova?');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (66, 2, 21, 'Zar se Abraham, otac naš, ne opravda djelima, kad na žrtvenik prinese Izaka, sina svoga?');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (66, 2, 22, 'Vidiš: vjera je surađivala s djelima njegovim i djelima se vjera usavršila');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (66, 2, 23, 'te se ispunilo Pismo koje veli: Povjerova Abraham Bogu i uračuna mu se u pravednost pa prijatelj Božji posta.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (66, 2, 24, 'Gledajte: čovjek se opravdava djelima, a ne samom vjerom.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (66, 2, 25, 'Ne opravda li se slično, djelima, i Rahaba bludnica kad primi glasnike i drugim ih putom izvede?');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (66, 2, 26, 'Jer kao što je tijelo bez duha mrtvo, tako je i vjera bez djela mrtva.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (66, 3, 1, 'Neka vas, braćo moja, ne bude mnogo učitelja! Ta znate: bit ćemo strože suđeni.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (66, 3, 2, 'Doista, svi mnogo griješimo. Ako tko u govoru ne griješi, savršen je čovjek, vrstan zauzdati i cijelo tijelo.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (66, 3, 3, 'Ubacimo li uzde u usta konjima da ih sebi upokorimo, upravljamo i cijelim tijelom njihovim.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (66, 3, 4, 'Evo i lađa: tolike su i silni ih vjetrovi gone, a neznatno ih kormilo upravlja kamo kormilarova volja hoće.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (66, 3, 5, 'Tako i jezik: malen je ud, a velikim se može ponositi. Evo: kolicna vatra koliku šumu zapali!');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (66, 3, 6, 'I jezik je vatra, svijet nepravda jezik je među našim udovima, kalja cijelo tijelo te, zapaljen od pakla, zapaljuje kotač života.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (66, 3, 7, 'Doista, sav rod zvijeri i ptica, gmazova i morskih životinja dade se ukrotiti, i rod ih je ljudski ukrotio,');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (66, 3, 8, 'a jezik - zlo nemirno, pun otrova smrtonosnog - nitko od ljudi ne može ukrotiti.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (66, 3, 9, 'Njime blagoslivljamo Gospodina i Oca, njime i proklinjemo ljude na sliku Božju stvorene:');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (66, 3, 10, 'iz istih usta izlazi blagoslov i prokletstvo. Ne smije se, braćo moja, tako događati!');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (66, 3, 11, 'Zar vrelo na isti otvor šiklja slatko i gorko?');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (66, 3, 12, 'Može li, braćo moja, smokva roditi maslinama ili trs smokvama? Ni slan izvor ne može dati slatke vode.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (66, 3, 13, 'Je li tko mudar i razborit među vama? Neka dobrim življenjem pokaže svoja djela u mudroj blagosti.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (66, 3, 14, 'Ako u srcu imate gorku zavist i svadljivost, ne uznosite se i ne lažite protiv istine!');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (66, 3, 15, 'Nije to mudrost koja odozgor silazi, nego zemaljska, ljudska, đavolska.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (66, 3, 16, 'Ta gdje je zavist i svadljivost, ondje je nered i svako zlo djelo.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (66, 3, 17, 'A mudrost odozgor ponajprije čista je, zatim mirotvorna, milostiva, poučljiva, puna milosrđa i dobrih plodova, postojana, nehinjena.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (66, 3, 18, 'Plod se pak pravednosti u miru sije onima koji tvore mir.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (66, 4, 1, 'Odakle ratovi, odakle borbe među vama? Zar ne odavde: od pohota što vojuju u udovima vašim?');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (66, 4, 2, 'Žudite, a nemate; ubijate i hlepite, a ne možete postići; borite se i ratujete. Nemate jer ne ištete.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (66, 4, 3, 'Ištete, a ne primate jer rđavo ištete: da u pohotama svojim potratite.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (66, 4, 4, 'Preljubnici! Ne znate li da je prijateljstvo sa svijetom neprijateljstvo prema Bogu? Tko god dakle hoće da bude prijatelj svijeta, promeće se u neprijatelja Božjega.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (66, 4, 5, 'Ili mislite da Pismo uzalud veli: Ljubomorno čezne za duhom što ga nastani u nama?');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (66, 4, 6, 'A daje on i veću milost. Zato govori: Bog se oholima protivi, a poniznima daje milost.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (66, 4, 7, 'Podložite se dakle Bogu! Oduprite se đavlu i pobjeći će od vas!');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (66, 4, 8, 'Približite se Bogu i on će se približiti vama! Očistite ruke, grešnici! Očistite srca, dvoličnjaci!');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (66, 4, 9, 'Zakukajte, protužite, proplačite! Smijeh vaš nek se u plač obrati i radost u žalost!');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (66, 4, 10, 'Ponizite se pred Gospodinom i on će vas uzvisiti!');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (66, 4, 11, 'Ne ogovarajte, braćo, jedni druge! Tko ogovara ili sudi brata svoga, ogovara i sudi Zakon. A sudiš li Zakon, nisi vršitelj nego sudac Zakona.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (66, 4, 12, 'Jedan je Zakonodavac i Sudac: Onaj koji može spasiti i pogubiti. A tko si ti da sudiš bližnjega?');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (66, 4, 13, 'De sada, vi što govorite: \"Danas ili sutra otići ćemo u taj i taj grad, provesti ondje godinu, trgovati i zaraditi\",');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (66, 4, 14, 'a ne znate što će sutra biti. Ta što je vaš život? Dašak ste što se načas pojavi i zatim nestane!');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (66, 4, 15, 'Umjesto da govorite: \"Htjedne li Gospodin, živjet ćemo i učiniti ovo ili ono\",');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (66, 4, 16, 'vi se razmećete svojim hvastanjima! Svako je takvo hvastanje opako.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (66, 4, 17, 'Znati dakle dobro činiti, a ne činiti - grijeh je.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (66, 5, 1, 'De sada, bogataši, proplačite i zakukajte zbog nevolja koje će vas zadesiti!');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (66, 5, 2, 'Bogatstvo vam istrunu, haljine vaše postadoše hrana moljcima,');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (66, 5, 3, 'zlato vam i srebro zarđa i rđa će njihova biti svjedočanstvo protiv vas te će kao vatra izjesti tijela vaša! Zgrnuste blago u posljednje dane!');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (66, 5, 4, 'Evo: plaća kosaca vaših njiva - koju im uskratiste - viče i vapaji žetelaca dopriješe do ušiju Gospoda nad Vojskama.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (66, 5, 5, 'Raskošno ste na zemlji i razvratno živjeli, utoviste srca svoja za dan klanja!');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (66, 5, 6, 'Osudiste i ubiste pravednika: on vam se ne suprotstavlja!');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (66, 5, 7, 'Strpite se dakle, braćo, do Dolaska Gospodnjega! Evo: ratar iščekuje dragocjeni urod zemlje, strpljiv je s njime dok ne dobije kišu ranu i kasnu.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (66, 5, 8, 'Strpite se i vi, očvrsnite srca jer se Dolazak Gospodnji približio!');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (66, 5, 9, 'Ne tužite se jedni na druge da ne budete osuđeni! Evo: sudac stoji pred vratima!');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (66, 5, 10, 'Za uzor strpljivosti i podnošenja zala uzmite, braćo, proroke koji su govorili u ime Gospodnje.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (66, 5, 11, 'Eto: blaženima nazivamo one koji ustrajaše. Za postojanost Jobovu čuste i nakanu Gospodnju vidjeste jer milostiv je Gospodin i milosrdan!');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (66, 5, 12, 'Prije svega, braćo moja, ne zaklinjite se ni nebom ni zemljom, ni ikojom drugom zakletvom. Vaše \"da\" neka bude \"da\", i \"ne\" - \"ne\", da ne padnete pod sud.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (66, 5, 13, 'Pati li tko među vama? Neka moli! Je li tko radostan? Neka pjeva hvalospjeve!');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (66, 5, 14, 'Boluje li tko među vama? Neka dozove starješine Crkve! Oni neka mole nad njim mažući ga uljem u ime Gospodnje');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (66, 5, 15, 'pa će molitva vjere spasiti nemoćnika; Gospodin će ga podići, i ako je sagriješio, oprostit će mu se.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (66, 5, 16, 'Ispovijedajte dakle jedni drugima grijehe i molite jedni za druge da ozdravite! Mnogo može žarka molitva pravednikova.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (66, 5, 17, 'Ilija bijaše čovjek baš kao i mi; usrdno se pomoli da ne bude kiše i kiše nije bilo na zemlji tri godine i šest mjeseci.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (66, 5, 18, 'Zatim se ponovno pomoli te nebo dade kišu i zemlja iznese urod svoj.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (66, 5, 19, 'Braćo moja, odluta li tko od vas od istine pa ga tkogod vrati,');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (66, 5, 20, 'znajte: tko vrati grešnika s lutalačkog puta njegova, spasit će dušu njegovu od smrti i pokriti mnoštvo grijeha.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (67, 1, 1, 'Petar, apostol Isusa Krista: putnicima Raseljeništva u Pontu, Galaciji, Kapadociji, Aziji i Bitiniji,');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (67, 1, 2, 'po predznanju Boga Oca, posvećenjem Duha izabranima da budu poslušni te poškropljeni krvlju Isusa Krista. Punina vam milosti i mira!');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (67, 1, 3, 'Blagoslovljen Bog i Otac Gospodina našega Isusa Krista koji nas po velikom milosrđu svojemu uskrsnućem Isusa Krista od mrtvih nanovo rodi za životnu nadu,');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (67, 1, 4, 'za baštinu neraspadljivu, neokaljanu i neuvelu, pohranjenu na nebesima za vas,');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (67, 1, 5, 'vas koje snaga Božja po vjeri čuva za spasenje, spremno da se objavi u posljednje vrijeme.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (67, 1, 6, 'Zbog toga se radujte, makar se sada možda trebalo malo i žalostiti zbog različitih kušnja:');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (67, 1, 7, 'da prokušanost vaše vjere - dragocjenija od propadljivog zlata, koje se ipak u vatri kuša - stekne hvalu, slavu i čast o Objavljenju Isusa Krista.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (67, 1, 8, 'Njega vi ljubite iako ga ne vidjeste; u njega, iako ga još ne gledate, vjerujete te klikćete od radosti neizrecive i proslavljene');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (67, 1, 9, 'što postigoste svrhu svoje vjere: spasenje duša.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (67, 1, 10, 'To su spasenje istraživali i pronicali proroci koji prorokovahu o milosti vama namijenjenoj.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (67, 1, 11, 'Pronicali su na koje ili kakvo je vrijeme smjerao Duh Kristov u njima koji je unaprijed svjedočio o Kristovim patnjama te slavama što su nakon njih imale doći:');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (67, 1, 12, 'bi im objavljeno da ne sebi nego vama poslužuju ono što vam sada u Duhu Svetom s neba poslanom navijestiše vaši blagovjesnici, a nada što se i anđeli žude nadviti.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (67, 1, 13, 'Zato opašite bokove pameti svoje, trijezni budite i savršeno se pouzdajte u milost koju vam donosi Objavljenje Isusa Krista.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (67, 1, 14, 'Kao poslušna djeca ne supriličujte se prijašnjim požudama iz doba neznanja.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (67, 1, 15, 'Naprotiv, kao što je svet Onaj koji vas pozva, i vi budite sveti u svemu življenju.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (67, 1, 16, 'Ta pisano je: Budite sveti jer sam ja svet.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (67, 1, 17, 'Ako dakle Ocem nazivate njega koji nepristrano svakoga po djelu sudi, vrijeme svoga proputovanja proživite u bogobojaznosti.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (67, 1, 18, 'Ta znate da od svog ispraznog načina života, što vam ga oci namriješe, niste otkupljeni nečim raspadljivim, srebrom ili zlatom,');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (67, 1, 19, 'nego dragocjenom krvlju Krista, Jaganjca nevina i bez mane.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (67, 1, 20, 'On bijaše doduše predviđen prije postanka svijeta, ali se očitova na kraju vremena radi vas');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (67, 1, 21, 'koji po njemu vjerujete u Boga koji ga uskrisi od mrtvih te mu dade slavu da vjera vaša i nada bude u Bogu.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (67, 1, 22, 'Pošto ste posluhom istini očistili duše svoje za nehinjeno bratoljublje, od srca žarko ljubite jedni druge.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (67, 1, 23, 'Ta nanovo ste rođeni, ne iz sjemena raspadljiva nego neraspadljiva: riječju Boga koji živi i ostaje.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (67, 1, 24, 'Doista, svako je tijelo kao trava, sva mu slava ko cvijet poljski: sahne trava, vene cvijet,');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (67, 1, 25, 'ali Riječ Gospodnja ostaje dovijeka. Ta pak riječ jest evanđelje koje vam je naviješteno.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (67, 2, 1, 'Odložite dakle svaku zloću i svaku prijevaru, himbe i zavisti i sva klevetanja.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (67, 2, 2, 'Kao novorođenčad žudite za duhovnim, nepatvorenim mlijekom da po njemu uzrastete za spasenje,');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (67, 2, 3, 'ako ste doista okusili kako je dobar Gospodin.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (67, 2, 4, 'Pristupite k njemu, Kamenu živomu što ga, istina, ljudi odbaciše, ali je u očima Božjim izabran, dragocjen,');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (67, 2, 5, 'pa se kao živo kamenje ugrađujte u duhovni Dom za sveto svećenstvo da prinosite žrtve duhovne, ugodne Bogu po Isusu Kristu.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (67, 2, 6, 'Stoga stoji u Pismu: Evo postavljam na Sionu kamen odabrani, dragocjeni kamen ugaoni: Tko u nj vjeruje, ne, neće se postidjeti.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (67, 2, 7, 'Vama dakle koji vjerujete - čast! A onima koji ne vjeruju - kamen koji odbaciše graditelji postade kamen zaglavni');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (67, 2, 8, 'i kamen spoticanja, stijena posrtanja; oni se o nj spotiču, neposlušni Riječi, za što su i određeni.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (67, 2, 9, 'A vi ste rod izabrani, kraljevsko svećenstvo, sveti puk, narod stečeni da naviještate silna djela Onoga koji vas iz tame pozva k divnom svjetlu svojemu;');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (67, 2, 10, 'vi, nekoć Ne-narod, a sada Narod Božji; vi Ne-mili, a sada Mili.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (67, 2, 11, 'Ljubljeni! Zaklinjem vas da se kao pridošlice i putnici klonite putenih požuda koje vojuju protiv duše;');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (67, 2, 12, 'življenje vaše među poganima neka bude uzorno da upravo onim za što vas sada potvaraju kao zločince, pošto promotre vaša dobra djela, proslave Boga u dan pohoda.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (67, 2, 13, 'Pokoravajte se svakoj ljudskoj ustanovi radi Gospodina: bilo kralju kao vrhovniku,');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (67, 2, 14, 'bilo upraviteljima jer ih on šalje da kazne zločince, a pohvale one koji dobro čine.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (67, 2, 15, 'Doista, ovo je Božja volja: da čineći dobro ušutkate neznanje bezumnika.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (67, 2, 16, 'Kao slobodni ljudi - ali ne kao oni kojima je sloboda tek pokrivalom zloće, već kao Božje sluge -');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (67, 2, 17, 'sve poštujte, bratstvo ljubite, Boga se bojte, kralja častite!');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (67, 2, 18, 'Sluge, budite sa svim poštovanjem pokorni gospodarima, ne samo dobrima i blagima nego i naopakima.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (67, 2, 19, 'To je uistinu milost ako tko radi savjesti, radi Boga podnosi nevolje trpeći nepravedno.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (67, 2, 20, 'Kakve li slave doista ako za grijehe udarani strpljivo podnosite? No ako dobro čineći trpite pa strpljivo podnosite, to je Bogu milo.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (67, 2, 21, 'Ta na to ste pozvani jer i Krist je trpio za vas i ostavio vam primjer da idete stopama njegovim.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (67, 2, 22, 'On koji grijeha ne učini nit mu usta prijevaru izustiše;');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (67, 2, 23, 'on koji na uvredu nije uvredom uzvraćao i mučen nije prijetio, prepuštajući to Sucu pravednom;');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (67, 2, 24, 'on koji u tijelu svom grijehe naše ponese na drvo da umrijevši grijesima pravednosti živimo; on čijom se modricom izliječiste.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (67, 2, 25, 'Doista, poput ovaca lutaste, ali se sada obratiste k pastiru i čuvaru duša svojih.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (67, 3, 1, 'Tako i vi, žene, pokoravajte se svojim muževima: ako su neki od njih možda neposlušni Riječi, da i bez riječi budu pridobiveni življenjem vas žena,');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (67, 3, 2, 'pošto promotre vaše bogoljubno i čisto življenje.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (67, 3, 3, 'Vaš nakit neka ne bude izvanjski - pletenje kose, kićenje zlatom ili oblačenje haljina.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (67, 3, 4, 'Nego: čovjek skrovita srca, neprolazne ljepote, blaga i smirena duha. To je pred Bogom dragocjeno.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (67, 3, 5, 'Tako su se doista i nekoć svete žene, zaufane u Boga, resile: pokoravale su se muževima.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (67, 3, 6, 'Sara se tako pokori Abrahamu te ga nazva gospodarom. Njezina ste djeca ako činite dobro ne bojeći se nikakva zastrašivanja.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (67, 3, 7, 'Tako i vi, muževi, obazrivo živite sa svojim ženama, kao sa slabijim spolom, te im iskazujte čast kao subaštinicima milosti Života da ne spriječite svojih molitava.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (67, 3, 8, 'Napokon, budite svi jednodušni, puni suosjećanja i bratske ljubavi, milosrdni, ponizni!');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (67, 3, 9, 'Ne vraćajte zlo za zlo ni uvredu za uvredu! Naprotiv, blagoslivljajte jer ste na to i pozvani da baštinite blagoslov!');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (67, 3, 10, 'Doista, tko želi ljubiti život i naužit se dana sretnih, nek suspregne jezik oda zla i usne od riječi prijevarnih;');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (67, 3, 11, 'zla nek se kloni, a čini dobro, mir neka traži i za njim ide:');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (67, 3, 12, 'jer oči Gospodnje gledaju pravedne, uši mu slušaju vapaje njihove, a lice se Gospodnje okreće protiv zločinaca.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (67, 3, 13, 'Pa tko da vam naudi ako revnujete za dobro?');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (67, 3, 14, 'Nego, morali i trpjeti zbog svoje pravednosti, blago vama! No ne bojte se njihova zastrašivanja i ne plašite se!');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (67, 3, 15, 'Naprotiv, Gospodin - Krist neka vam bude svet, u srcima vašim, te budite uvijek spremni na odgovor svakomu koji od vas zatraži obrazloženje nade koja je u vama,');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (67, 3, 16, 'ali blago i s poštovanjem, dobre savjesti da oni koji ozloglašuju vaš dobar život u Kristu, upravo onim budu postiđeni za što vas potvaraju.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (67, 3, 17, 'Ta uspješnije je trpjeti, ako je to Božja volja, čineći dobro, nego čineći zlo.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (67, 3, 18, 'Doista, i Krist jednom za grijehe umrije, pravedan za nepravedne, da vas privede k Bogu - ubijen doduše u tijelu, ali oživljen u duhu.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (67, 3, 19, 'U njemu otiđe i propovijedati duhovima u tamnici');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (67, 3, 20, 'koji bijahu nekoć nepokorni, kad ih ono Božja strpljivost iščekivaše, u vrijeme Noino, dok se gradila korablja u kojoj nekolicina, to jest osam duša, bi spašena vodom.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (67, 3, 21, 'Njezin protulik, krštenje - ne odlaganje tjelesne nečistoće, nego molitva za dobru savjest upravljena Bogu - i vas sada spasava po uskrsnuću Isusa Krista');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (67, 3, 22, 'koji, uzašavši na nebo, jest zdesna Bogu, pošto mu bijahu pokoreni anđeli, vlasti i sile.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (67, 4, 1, 'Dakle, budući da je Krist trpio u tijelu, i vi se oboružajte istim mišljenjem - jer tko trpi u tijelu okanio se grijeha -');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (67, 4, 2, 'da vrijeme što vam u tijelu još preostaje proživite ne više po ljudskim požudama nego po Božjoj volji.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (67, 4, 3, 'Dosta je uistinu što ste u prošlom vremenu vršili volju pogana, hodeći u razvratnostima, požudama, pijančevanjima, pijankama, opijanjima i bezakoničkim idolopoklonstvima.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (67, 4, 4, 'Stoga se čude što se ne slijevate u tu istu rijeku raskalašenosti te proklinju.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (67, 4, 5, 'Polagat će oni račun Onomu tko je već spreman suditi žive i mrtve.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (67, 4, 6, 'Zato je i mrtvima naviješteno evanđelje da osuđeni doduše po ljudsku, u tijelu, žive po Božju - u duhu.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (67, 4, 7, 'Približio se svršetak svega! Osvijestite se i otrijeznite za molitvu!');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (67, 4, 8, 'Prije svega imajte žarku ljubav jedni prema drugima jer ljubav pokriva mnoštvo grijeha!');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (67, 4, 9, 'Gostoljubivo primajte jedni druge bez mrmljanja!');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (67, 4, 10, 'Jedni druge poslužujte - svatko po primljenom daru - kao dobri upravitelji različitih Božjih milosti!');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (67, 4, 11, 'Govori li tko? Neka govori kao riječi Božje! Poslužuje li tko? Neka poslužuje kao snagom koju daje Bog da se u svemu slavi Bog po Isusu Kristu, komu slava i vlast u vijeke vijekova! Amen.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (67, 4, 12, 'Ljubljeni! Ne čudite se požaru što bukti među vama da vas iskuša, kao da vam se događa štogod neobično!');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (67, 4, 13, 'Naprotiv, radujte se kao zajedničari Kristovih patnja da i o Objavljenju njegove slave mognete radosno klicati.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (67, 4, 14, 'Pogrđuju li vas zbog imena Kristova, blago vama, jer Duh Slave, Duh Božji u vama počiva.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (67, 4, 15, 'Tek neka nitko od vas ne trpi kao ubojica, ili kradljivac, ili zločinac, ili makar i kao nametljivac;');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (67, 4, 16, 'ako li kao kršćanin, neka se ne stidi, nego slavi Boga zbog tog imena.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (67, 4, 17, 'Ta vrijeme je da započne Sud - od doma Božjega. No ako već od vas započinje, kakav je onda svršetak onih što nisu poslušni Božjem evanđelju?');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (67, 4, 18, 'I ako se pravednik jedva spasava, opak i grešnik gdje da se pojavi?');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (67, 4, 19, 'Stoga oni koji po volji Božjoj trpe, neka dobrim djelima povjere duše svoje vjernom Stvoritelju.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (67, 5, 1, 'Starješine dakle među vama opominjem, ja sustarješina i svjedok Kristovih patnja, a zato i zajedničar slave koja se ima očitovati:');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (67, 5, 2, 'pasite povjereno vam stado Božje, nadgledajte ga - ne prisilno, nego dragovoljno, po Božju; ne radi prljava dobitka, nego oduševljeno;');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (67, 5, 3, 'i ne kao gospodari Baštine nego kao uzori stada.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (67, 5, 4, 'Pa kad se pojavi Natpastir, primit ćete neuveli vijenac slave.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (67, 5, 5, 'Tako i vi, mladići, podložite se starješinama; svi se jedni prema drugima pripašite poniznošću jer Bog se oholima protivi, a poniznima daruje milost.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (67, 5, 6, 'Ponizite se dakle pod snažnom rukom Božjom da vas uzvisi u pravo vrijeme.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (67, 5, 7, 'Svu svoju brigu povjerite njemu jer on se brine za vas.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (67, 5, 8, 'Otrijeznite se! Bdijte! Protivnik vaš, đavao, kao ričući lav obilazi tražeći koga da proždre.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (67, 5, 9, 'Oprite mu se stameni u vjeri znajući da takve iste patnje podnose vaša braća po svijetu.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (67, 5, 10, 'A Bog svake milosti, koji vas pozva na vječnu slavu u Kristu, on će vas, pošto malo potrpite, usavršiti, učvrstiti, ojačati, utvrditi.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (67, 5, 11, 'Njemu vlast u vijeke vjekova! Amen.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (67, 5, 12, 'Pišem vam ukratko, po Silvanu, koga smatram bratom vjernim, da vas ohrabrim i posvjedočim kako je ovo istinska milost Božja. Nje se držite!');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (67, 5, 13, 'Pozdravlja vas suizabranica u Babilonu i Marko, sin moj.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (67, 5, 14, 'Pozdravite jedni druge cjelovom ljubavi! Mir svima vama koji ste u Kristu!');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (68, 1, 1, 'Šimun Petar, sluga i apostol Isusa Krista, onima koje pravednošću Boga našega i Spasitelja Isusa Krista zapade ista dragocjena vjera kao i nas.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (68, 1, 2, 'Punina vam milosti i mira po spoznaji Boga i Isusa, Gospodina našega!');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (68, 1, 3, 'Doista, po spoznaji njega, koji nas pozva slavom svojom i krepošću, božanska nas je snaga njegova obdarila svime za život i pobožnost.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (68, 1, 4, 'Time smo obdareni dragocjenim, najvećim obećanjima da po njima postanete zajedničari božanske naravi umakavši pokvarenosti koja je u svijetu zbog požude.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (68, 1, 5, 'Zbog toga svim marom prionite: vjerom osigurajte krepost, krepošću spoznaje,');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (68, 1, 6, 'spoznanjem uzdržljivost, uzdržljivošću postojanost, postojanošću pobožnost,');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (68, 1, 7, 'pobožnošću bratoljublje, bratoljubljem ljubav.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (68, 1, 8, 'Jer ako to imate i u tom napredujete, nećete biti besposleni i neplodni za spoznanje Isusa Krista.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (68, 1, 9, 'A tko toga nema, slijep je, kratkovidan; zaboravio je da je očišćen od svojih prijašnjih grijeha.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (68, 1, 10, 'Zato, braćo, to revnije uznastojte učvrstiti svoj poziv i izabranje: to čineći - ne, nećete posrnuti nikada!');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (68, 1, 11, 'Tako će vam se bogato osigurati ulazak u vječno kraljevstvo Gospodina našega i Spasitelja Isusa Krista.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (68, 1, 12, 'Zato ću vas uvijek na to podsjećati premda to znate i utvrđeni ste u primljenoj istini.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (68, 1, 13, 'Pravo je, mislim, da vas dok sam u ovom šatoru, budim opomenom,');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (68, 1, 14, 'svjestan da ću brzo napustiti svoj šator, kako mi i Gospodin naš Isus Krist očitova.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (68, 1, 15, 'A pobrinut ću se da se i nakon mojeg izlaska uvijek toga sjećate.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (68, 1, 16, 'Ta nismo vam navijestili snagu i Dolazak Gospodina našega Isusa Krista slijedeći izmudrene priče, nego kao očevici njegova veličanstva.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (68, 1, 17, 'Od Oca je doista primio čast i slavu kad mu ono od uzvišene Slave doprije ovaj glas: Ovo je Sin moj, Ljubljeni moj, u njemu mi sva milina!');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (68, 1, 18, 'Taj glas, koji s neba dopiraše, čusmo mi koji bijasmo s njime na Svetoj gori.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (68, 1, 19, 'Tako nam je potvrđena proročka riječ te dobro činite što uza nju prianjate kao uza svjetiljku što svijetli na mrklu mjestu - dok Dan ne osvane i Danica se ne pomoli u srcima vašim.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (68, 1, 20, 'Ponajprije znajte ovo: nijedno se proroštvo Pisma ne može tumačiti samovoljno');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (68, 1, 21, 'jer nikada proroštvo ne bi ljudskom voljom doneseno, nego su Duhom Svetim poneseni ljudi od Boga govorili.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (68, 2, 1, 'Bilo je u narodu i lažnih proroka, kao što će i među vama biti lažnih učitelja, onih koji će prokrijumčariti pogubna krivovjerja, zanijekati Gospodina koji ih otkupi, i navući na se brzu propast.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (68, 2, 2, 'I mnogi će se povesti za njihovim razvratnostima. Zbog njih će se kuditi put istine.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (68, 2, 3, 'U svojoj će vas lakomosti kupovati izmišljotinama. Njihova osuda već odavna nije dokona i propast im ne drijema.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (68, 2, 4, 'Doista, ako Bog anđela koji sagriješiše nije poštedio nego ih je sunovratio u Tartar i predao mračnom bezdanu da budu čuvani za sud;');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (68, 2, 5, 'ako staroga svijeta ne poštedje, nego sačuva - osmoga - Nou, glasnika pravednosti, sručivši potop na svijet bezbožni;');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (68, 2, 6, 'ako gradove Sodomu i Gomoru u pepeo pretvori, osudi i za primjer budućim bezbožnicima postavi;');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (68, 2, 7, 'ako pravednog Lota, premorena razvratnim življenjem onih razularenika, oslobodi -');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (68, 2, 8, 'pravedniku se doista dan za danom duša razdirala dok je gledao i slušao bezakonička djela onih među kojima je boravio -');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (68, 2, 9, 'umije Gospod i pobožnike iz napasti izbaviti, a nepravednike za kaznu na Dan sudnji sačuvati,');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (68, 2, 10, 'ponajpače one koji u prljavoj požudi idu za puti i preziru Veličanstvo. Preuzetnici, drznici i ne trepnu pogrđujući Slave,');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (68, 2, 11, 'dok anđeli, iako jakošću i snagom od njih veći, ne izriču protiv njih pred Gospodinom pogrdna suda.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (68, 2, 12, 'Oni pak kao nerazumne životinje, po naravi rođene za lov i istrebljenje, pogrđuju što ne poznaju. Istim će istrebljenjem i oni biti istrebljeni;');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (68, 2, 13, 'zadesit će ih nepravda, plaća nepravednosti. Užitkom smatraju razvratnost u pol bijela dana. Ljage i sramote! Naslađuju se prijevarama svojim dok se s vama goste.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (68, 2, 14, 'Oči su im pune preljubnice, nikako da se nasite grijeha; mame duše nepostojane, srce im je uvježbano u lakomstvu, prokleti sinovi!');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (68, 2, 15, 'Zabludiše, napustivši ravan put, te pođoše putom Bosorova sina Bileama, koji prigrli plaću nepravednosti,');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (68, 2, 16, 'ali primi i ukor za svoje nedjelo: nijemo živinče ljudskim glasom prozbori i spriječi prorokovo bezumlje.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (68, 2, 17, 'Oni su izvori bezvodni, oblaci vjetrom gonjeni; za njih se čuva mrkla tmina.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (68, 2, 18, 'Naklapajući naduvene ispraznosti, požudama putenim, razvratnostima mame one što netom odbjegoše od onih koji žive u zabludi.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (68, 2, 19, 'Obećavaju im slobodu, a sami su robovi pokvarenosti. Jer svatko robuje onomu tko ga svlada.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (68, 2, 20, 'Doista, pošto su po spoznaji Gospodina našega i Spasitelja Isusa Krista odbjegli od prljavština svijeta, ako se opet u njih upleću i daju se svladati, ovo im je potonje gore od onoga prvoga.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (68, 2, 21, 'Bilo bi im doista bolje da nisu spoznali puta pravednosti, negoli, pošto ga spoznaše, okrenuti leđa svetoj zapovijedi koja im je predana.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (68, 2, 22, 'Dogodilo im se što veli istinita izreka: \"Pas se vraća svojoj bljuvotini i okupana svinja valjanju u blatu.\"');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (68, 3, 1, 'Ljubljeni, pišem evo već drugu poslanicu. U objema opomenom budim vaš zdrav razbor');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (68, 3, 2, 'da se sjetite riječi što ih prorekoše sveti proroci i zapovijedi apostola vaših, zapovijedi Gospodinove i Spasiteljeve.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (68, 3, 3, 'Znajte ponajprije ovo: u posljednje će se dane pojaviti podrugljivi izrugivači; povoditi će se za svojim požudama');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (68, 3, 4, 'i pitati: \"Što je s obećanjem njegova Dolaska? Jer i otkad Oci pomriješe, sve ostaje kao što bijaše od početka stvorenja.\"');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (68, 3, 5, 'Ta oni naumice zaboravljaju da nebesa bijahu odavna i da zemlja na Božju riječ posta iz vode i po vodi.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (68, 3, 6, 'Na isti način ondašnji svijet propade vodom potopljen.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (68, 3, 7, 'A sadašnja nebesa i zemlja istom su riječju pohranjena za oganj i čuvaju se za Dan suda i propasti bezbožnih ljudi.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (68, 3, 8, 'Jedno, ljubljeni, ne smetnite s uma: jedan je dan kod Gospodina kao tisuću godina, a tisuću godina kao jedan dan.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (68, 3, 9, 'Ne kasni Gospodin ispuniti obećanje, kako ga neki sporim smatraju, nego je strpljiv prema vama jer neće da tko propadne, nego hoće da svi prispiju k obraćenju.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (68, 3, 10, 'Kao tat će doći Dan Gospodnji u koji će nebesa trijeskom uminuti, počela se, užarena, raspasti, a zemlja i djela na njoj razotkriti.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (68, 3, 11, 'Kad se sve tako ima raspasti, kako li treba da se svi vi ističete u svetu življenju i pobožnosti');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (68, 3, 12, 'iščekujući i pospješujući dolazak Dana Božjega u koji će se nebesa, zapaljena, raspasti i počela, užarena, rastaliti.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (68, 3, 13, 'Ta po obećanju njegovu iščekujemo nova nebesa i zemlju novu, gdje pravednost prebiva.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (68, 3, 14, 'Zato, ljubljeni, dok to iščekujete, uznastojte da mu budete neokaljani i besprijekorni, u miru.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (68, 3, 15, 'A strpljivost Gospodina našega spasenjem smatrajte, kako vam i ljubljeni brat naš Pavao napisa po mudrosti koja mu je dana.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (68, 3, 16, 'Tako u svim poslanicama gdje o tome govori. U njima ima ponešto nerazumljivo, što neupućeni i nepostojani iskrivljuju, kao i ostala Pisma - sebi na propast.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (68, 3, 17, 'Vi dakle, ljubljeni pošto ste upozoreni, čuvajte se da ne biste, zavedeni bludnjom razularenika, otpali od svoje postojanosti.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (68, 3, 18, 'A rastite u milosti i spoznanju Gospodina našega i Spasitelja Isusa Krista! Njemu slava i sada i do u dan vječnosti! Amen!');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (69, 1, 1, 'Što bijaše od početka, što smo čuli, što smo vidjeli očima svojim, što razmotrismo i ruke naše opipaše o Riječi, Životu -');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (69, 1, 2, 'da, Život se očitova, i vidjeli smo i svjedočimo, i navješćujemo vam Život vječni, koji bijaše kod Oca i očitova se nama -');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (69, 1, 3, 'što smo vidjeli i čuli, navješćujemo i vama da i vi imate zajedništvo s nama. A naše je zajedništvo s Ocem i sa Sinom njegovim Isusom Kristom.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (69, 1, 4, 'I to vam pišemo da radost naša bude potpuna.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (69, 1, 5, 'A ovo je navještaj koji smo čuli od njega i navješćujemo vama: Bog je svjetlost i tame u njemu nema nikakve!');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (69, 1, 6, 'Reknemo li da imamo zajedništvo s njim, a u tami hodimo, lažemo i ne činimo istine.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (69, 1, 7, 'Ako u svjetlosti hodimo, kao što je on u svjetlosti, imamo zajedništvo jedni s drugima i krv Isusa, Sina njegova, čisti nas od svakoga grijeha.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (69, 1, 8, 'Reknemo li da grijeha nemamo, sami sebe varamo i istine nema u nama.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (69, 1, 9, 'Ako priznamo grijehe svoje, vjeran je on i pravedan: otpustit će nam grijehe i očistiti nas od svake nepravde.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (69, 1, 10, 'Reknemo li da nismo zgriješili, pravimo ga lašcem i riječi njegove nema u nama.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (69, 2, 1, 'Dječice moja, ovo vam pišem da ne griješite. Ako tko i sagriješi, zagovornika imamo kod Oca - Isusa Krista, Pravednika.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (69, 2, 2, 'On je pomirnica za grijeha naše, i ne samo naše, nego i svega svijeta.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (69, 2, 3, 'I po ovom znamo da ga poznajemo: ako zapovijedi njegove čuvamo.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (69, 2, 4, 'Tko veli: \"Poznajem ga\", a zapovijedi njegovih ne čuva, lažac je, u njemu nema istine.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (69, 2, 5, 'A tko čuva riječ njegovu, u njemu je zaista savršena ljubav Božja. Po tom znamo da smo u njemu.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (69, 2, 6, 'Tko veli da u njemu ostaje, valja mu ići putom kojim je on hodio.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (69, 2, 7, 'Ljubljeni, pišem vam ne novu zapovijed, nego staru zapovijed, koju ste imali od početka. Ta stara zapovijed jest riječ koju ste čuli.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (69, 2, 8, 'A opet, novu vam zapovijed pišem - obistinjuje se u njemu i vama - jer tama prolazi, svjetlost istinita već svijetli.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (69, 2, 9, 'Tko veli da je u svjetlosti, a mrzi brata svojega, u tami je sve do sada.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (69, 2, 10, 'Tko ljubi brata svojega, u svjetlosti ostaje i sablazni u njemu nema.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (69, 2, 11, 'A tko mrzi brata svojega, u tami je, u tami hodi i ne zna kamo ide jer mu tama zaslijepi oči.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (69, 2, 12, 'Pišem vama, dječice, jer su vam grijesi oprošteni po njegovu imenu.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (69, 2, 13, 'Pišem vama, oci, jer upoznaste onoga koji je od početka. Pišem vama, mladići, jer ste pobijedili Zloga.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (69, 2, 14, 'Napisah vama, djeco, jer upoznaste Oca. Napisah vama, oci, jer upoznaste onoga koji je od početka. Napisah vama, mladići, jer ste jaki i riječ Božja u vama ostaje i pobijedili ste Zloga.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (69, 2, 15, 'Ne ljubite svijeta ni što je u svijetu. Ako tko ljubi svijet, nema u njemu ljubavi Očeve.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (69, 2, 16, 'Jer što je god svjetovno - požuda tijela, i požuda očiju, i oholost života - nije od Oca, nego od svijeta.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (69, 2, 17, 'Svijet prolazi i požuda njegova, a tko čini volju Božju, ostaje dovijeka.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (69, 2, 18, 'Djeco, posljednji je čas! I, kako ste čuli, dolazi Antikrist. I sad su se već mnogi antikristi pojavili. Odatle znamo da je posljednji čas.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (69, 2, 19, 'Od nas iziđoše, ali ne bijahu od nas. Jer kad bi bili od nas, ostali bi s nama; ali neka se očituje da nisu od nas.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (69, 2, 20, 'A vi imate Pomazanje od Svetoga, i znanje svi imate.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (69, 2, 21, 'Ne pisah vam zato što ne biste znali istine, nego jer je znate i jer znate da nikakva laž nije od istine.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (69, 2, 22, 'Tko je lažac, ako ne onaj koji tvrdi da Isus nije Krist? Antikrist je onaj');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (69, 2, 23, 'tko niječe Oca i Sina. Svaki koji niječe Sina, nema ni Oca, a tko priznaje Sina, ima i Oca.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (69, 2, 24, 'A vi - što čuste od početka, u vama nek ostane. Ako u vama ostane što čuste od početka, i vi ćete ostati u Sinu i Ocu.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (69, 2, 25, 'A ovo je obećanje koje nam on obeća: život vječni.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (69, 2, 26, 'Ovo vam napisah o onima koji vas zavode.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (69, 2, 27, 'A vi - Pomazanje koje primiste od njega u vama ostaje i ne treba da vas itko poučava. Nego njegovo vas Pomazanje uči o svemu, a istinito je i nije laž, pa kao što vas je ono naučilo, ostanite u Njemu.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (69, 2, 28, 'I sada, dječice, ostanite u njemu da budemo puni pouzdanja kad se pojavi te se ne postidimo pred njim o njegovu dolasku.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (69, 2, 29, 'Ako znate da je on Pravednik, znate i da je svaki koji čini pravdu od njega rođen.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (69, 3, 1, 'Gledajte koliku nam je ljubav darovao Otac: djeca se Božja zovemo, i jesmo. A svijet nas ne poznaje zato što ne poznaje njega.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (69, 3, 2, 'Ljubljeni, sad smo djeca Božja i još se ne očitova što ćemo biti. Znamo: kad se očituje, bit ćemo njemu slični, jer vidjet ćemo ga kao što jest.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (69, 3, 3, 'I tko god ima tu nadu u njemu, čisti se kao što je on čist.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (69, 3, 4, 'Tko god čini grijeh, čini i bezakonje; ta grijeh je bezakonje.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (69, 3, 5, 'I znate: on se pojavi da odnese grijehe i grijeha nema u njemu.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (69, 3, 6, 'Tko god u njemu ostaje, ne griješi. Tko god griješi, nije ga vidio nit upoznao.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (69, 3, 7, 'Dječice, nitko neka vas ne zavede! Tko čini pravdu, pravedan je kao što je On pravedan.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (69, 3, 8, 'Tko čini grijeh, od đavla je jer đavao griješi od početka. Zato se pojavi Sin Božji: da razori djela đavolska.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (69, 3, 9, 'Tko god je rođen od Boga, ne čini grijeha jer njegovo sjeme ostaje u njemu; ne može griješiti jer je rođen od Boga.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (69, 3, 10, 'Po ovom se raspoznaju djeca Božja i djeca đavolska: tko god ne čini pravde i tko ne ljubi brata, nije od Boga.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (69, 3, 11, 'Jer ovo je navještaj koji čuste od početka: da ljubimo jedni druge.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (69, 3, 12, 'Ne kao Kajin, koji bijaše od Zloga i ubi brata svog. A zašto ga ubi? Jer mu djela bijahu zla, a bratova pravedna.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (69, 3, 13, 'Ne čudite se, braćo ako vas svijet mrzi.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (69, 3, 14, 'Mi znamo da smo iz smrti prešli u život jer ljubimo braću; tko ne ljubi, ostaje u smrti.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (69, 3, 15, 'Tko god mrzi brata svoga, ubojica je. A znate da nijedan ubojica nema u sebi trajnoga, vječnoga života.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (69, 3, 16, 'Po ovom smo upoznali Ljubav: on je za nas položio život svoj. I mi smo dužni živote položiti za braću.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (69, 3, 17, 'Tko ima dobra ovoga svijeta i vidi brata svoga u potrebi pa zatvori pred njim srce - kako ljubav Božja ostaje u njemu?');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (69, 3, 18, 'Dječice, ne ljubimo riječju i jezikom, već djelom i istinom.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (69, 3, 19, 'Po tom ćemo znati da smo od istine. I umirit ćemo pred njim srce svoje');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (69, 3, 20, 'ako nas ono bilo u čem osuđuje. Jer Bog je veći od našega srca i znade sve.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (69, 3, 21, 'Ljubljeni, ako nas srce ne osuđuje, možemo zaufano k Bogu.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (69, 3, 22, 'I što god ištemo, primamo od njega jer zapovijedi njegove čuvamo i činimo što je njemu drago.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (69, 3, 23, 'I ovo je zapovijed njegova: da vjerujemo u ime Sina njegova Isusa Krista i da ljubimo jedni druge kao što nam je dao zapovijed.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (69, 3, 24, 'I tko čuva zapovijedi njegove, u njemu ostaje, i On u njemu. I po ovom znamo da on ostaje u nama: po Duhu kojeg nam je dao.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (69, 4, 1, 'Ljubljeni, ne vjerujte svakom duhu, nego provjeravajte duhove jesu li od Boga, jer su mnogi lažni proroci izišli u svijet.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (69, 4, 2, 'Po ovom prepoznajete Duha Božjega: svaki duh koji ispovijeda da je Isus Krist došao u tijelu, od Boga je.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (69, 4, 3, 'A nijedan duh koji ne ispovijeda takva Isusa, nije od Boga: on je Antikristov, a za nj ste čuli da dolazi i sad je već na svijetu.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (69, 4, 4, 'Vi ste, dječice, od Boga i pobijedili ste ih jer je moćniji Onaj koji je u vama nego onaj koji je u svijetu.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (69, 4, 5, 'Oni su od svijeta, zato iz svijeta govore i svijet ih sluša.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (69, 4, 6, 'Mi smo od Boga. Tko poznaje Boga, nas sluša, a tko nije od Boga, ne sluša nas. Po tom prepoznajemo Duha istine i duha zablude.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (69, 4, 7, 'Ljubljeni, ljubimo jedni druge jer ljubav je od Boga; i svaki koji ljubi, od Boga je rođen i poznaje Boga.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (69, 4, 8, 'Tko ne ljubi, ne upozna Boga jer Bog je ljubav.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (69, 4, 9, 'U ovom se očitova ljubav Božja u nama: Bog Sina svoga jedinorođenoga posla u svijet da živimo po njemu.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (69, 4, 10, 'U ovom je ljubav: ne da smo mi ljubili Boga, nego - on je ljubio nas i poslao Sina svoga kao pomirnicu za grijehe naše.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (69, 4, 11, 'Ljubljeni, ako je Bog tako ljubio nas, i mi smo dužni ljubiti jedni druge.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (69, 4, 12, 'Boga nitko nikada ne vidje. Ako ljubimo jedni druge, Bog ostaje u nama, i ljubav je njegova u nama savršena.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (69, 4, 13, 'Po ovom znamo da ostajemo u njemu i on u nama: od Duha nam je svoga dao.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (69, 4, 14, 'I mi smo vidjeli i svjedočimo da je Otac poslao Sina kao Spasitelja svijeta.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (69, 4, 15, 'Tko ispovijeda da je Isus Sin Božji, Bog ostaje u njemu, i on u Bogu.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (69, 4, 16, 'I mi smo upoznali ljubav koju Bog ima prema nama i povjerovali joj. Bog je ljubav i tko ostaje u ljubavi, u Bogu ostaje, i Bog u njemu.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (69, 4, 17, 'U ovom je savršenstvo naše uzajamne ljubavi: imamo pouzdanje na Sudnji dan jer kakav je on, takvi smo i mi u ovom svijetu.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (69, 4, 18, 'Straha u ljubavi nema, nego savršena ljubav izgoni strah; jer strah je muka i tko se boji, nije savršen u ljubavi.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (69, 4, 19, 'Mi ljubimo jer on nas prije uzljubi.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (69, 4, 20, 'Rekne li tko: \"Ljubim Boga\", a mrzi brata svog, lažac je. Jer tko ne ljubi svoga brata kojega vidi, Boga kojega ne vidi ne može ljubiti.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (69, 4, 21, 'I ovu zapovijed imamo od njega: Tko ljubi Boga, da ljubi i brata svoga.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (69, 5, 1, 'Tko god vjeruje: \"Isus je Krist\", od Boga je rođen. I tko god ljubi roditelja, ljubi i rođenoga.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (69, 5, 2, 'Po ovom znamo da ljubimo djecu Božju: kad Boga ljubimo i zapovijedi njegove vršimo.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (69, 5, 3, 'Jer ljubav je Božja ovo: zapovijedi njegove čuvati. A zapovijedi njegove nisu teške.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (69, 5, 4, 'Jer sve što je od Boga rođeno, pobjeđuje svijet. I ovo je pobjeda što pobijedi svijet: vjera naša.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (69, 5, 5, 'Ta tko to pobjeđuje svijet ako ne onaj tko vjeruje da je Isus Sin Božji?');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (69, 5, 6, 'On, Isus Krist, dođe kroz vodu i krv. Ne samo u vodi nego - u vodi i krvi. I Duh je koji svjedoči jer Duh je istina.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (69, 5, 7, 'Jer troje je što svjedoči:');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (69, 5, 8, 'Duh, voda i krv; i to je troje jedno.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (69, 5, 9, 'Ako primamo svjedočanstvo ljudi, svjedočanstvo je Božje veće. Jer ovo je svjedočanstvo Božje, kojim je svjedočio za Sina svoga:');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (69, 5, 10, 'Tko vjeruje u Sina Božjega, ima to svjedočanstvo Božje u sebi. Tko ne vjeruje Bogu, učinio ga je lašcem jer nije vjerovao u svjedočanstvo kojim je svjedočio Bog za Sina svoga.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (69, 5, 11, 'I ovo je svjedočanstvo: Bog nam je dao život vječni; i taj je život u Sinu njegovu.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (69, 5, 12, 'Tko ima Sina, ima život; tko nema Sina Božjega, nema života.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (69, 5, 13, 'To napisah vama koji vjerujete u ime Sina Božjega da znate da imate život vječni.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (69, 5, 14, 'I ovo je pouzdanje koje imamo u njega: ako što ištemo po volji njegovoj, uslišava nas.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (69, 5, 15, 'I znamo li da nas uslišava u svemu što ištemo, znamo da već imamo što smo od njega iskali.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (69, 5, 16, 'Vidi li tko brata svojega gdje čini grijeh koji nije na smrt, neka ište i dat će mu život - onima koji čine grijeh što nije na smrt. Ima grijeh što je na smrt; za nj ne velim da moli.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (69, 5, 17, 'Svaka je nepravda grijeh. A postoji grijeh koji nije na smrt.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (69, 5, 18, 'Znamo: tko god je rođen od Boga, ne griješi; nego Rođeni od Boga čuva ga i Zli ga se ne dotiče.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (69, 5, 19, 'Znamo: od Boga smo, a sav je svijet pod Zlim.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (69, 5, 20, 'Znamo: Sin je Božji došao i dao nam razum da poznamo Istinitoga. I mi smo u Istinitom, u Sinu njegovu, Isusu Kristu. On je Bog istiniti i Život vječni.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (69, 5, 21, 'Dječice, klonite se idola!');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (70, 1, 1, 'Starješina izabranoj Gospođi i djeci njezinoj koju ja ljubim u Istini - a ne samo ja nego i svi koji upoznaše Istinu -');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (70, 1, 2, 'radi Istine koja ostaje u nama i bit će s nama dovijeka.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (70, 1, 3, 'Bila s nama milost, milosrđe i mir od Boga Oca i od Sina Očeva Isusa Krista u istini i ljubavi!');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (70, 1, 4, 'Obradovah se veoma što sam među tvojom djecom našao takve koji hode u istini, kao što primismo zapovijed od Oca.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (70, 1, 5, 'I sada te molim, Gospođo, ne kao da ti novu zapovijed pišem, nego onu koju smo imali od početka: da ljubimo jedni druge.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (70, 1, 6, 'A ovo je ta ljubav: da živimo po zapovijedima njegovim. To je zapovijed, kao što čuste od početka, da u njoj živite.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (70, 1, 7, 'Jer iziđoše na svijet mnogi zavodnici koji ne ispovijedaju Isusa Krista koji dolazi u tijelu. To je zavodnik i Antikrist.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (70, 1, 8, 'Čuvajte se da ne izgubite što ste stekli, nego da primite potpunu plaću.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (70, 1, 9, 'Tko god pretjera i ne ostane u nauku Kristovu, nema Boga. Tko ostaje u nauku, ima i Oca i Sina.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (70, 1, 10, 'Ako tko dolazi k vama i ne donosi tog nauka, ne primajte ga u kuću i ne pozdravljajte ga.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (70, 1, 11, 'Jer tko ga pozdravlja, sudjeluje u njegovim zlim djelima.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (70, 1, 12, 'Mnogo bih vam imao pisati, ali ne htjedoh na papiru i crnilom, nego se nadam da ću doći k vama i iz usta u usta govoriti da radost vaša bude potpuna.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (70, 1, 13, 'Pozdravljaju te djeca tvoje izabrane sestre.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (71, 1, 1, 'Starješina ljubljenom Gaju koga ljubim u Istini.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (71, 1, 2, 'Ljubljeni! Želim ti u svemu dobro i da budeš zdrav, kao što je dobro tvojoj duši.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (71, 1, 3, 'Veoma se obradovah kada dođoše braća i posvjedočiše za tvoju istinu: kako ti živiš po Istini.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (71, 1, 4, 'Čuti da moja djeca po Istini žive! - nema mi veće radosti od toga.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (71, 1, 5, 'Ljubljeni, pravi si vjernik u svemu što činiš za braću, i to za došljake.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (71, 1, 6, 'Oni posvjedočiše tvoju ljubav pred Crkvom i dobro ćeš učiniti ako ih ispratiš Boga dostojno.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (71, 1, 7, 'Jer poradi Imena iziđoše i ne primaju ništa od pogana.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (71, 1, 8, 'Mi smo dakle dužni takve primati da budemo suradnici Istine.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (71, 1, 9, 'Pisao sam nešto Crkvi: ali Diotref, koji hoće da bude prvi među njima, ne prima nas.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (71, 1, 10, 'Zato ako dođem, spočitnut ću mu djela koja čini naklapajući zlobne riječi o nama. Ni to mu nije dosta, nego ne prima braće, a onima koji bi to htjeli, brani i izgoni ih iz Crkve.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (71, 1, 11, 'Ljubljeni! Ne nasljeduj zlo, nego dobro. Tko dobro čini, od Boga je; tko zlo čini, nije vidio Boga.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (71, 1, 12, 'Za Demetrija svjedoče svi, i sama Istina, a i mi svjedočimo. A znaš da je naše svjedočanstvo istinito.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (71, 1, 13, 'Mnogo bih ti imao pisati, ali neću da ti pišem crnilom i perom.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (71, 1, 14, 'Nadam se da ću te uskoro vidjeti pa ćemo iz usta u usta govoriti.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (71, 1, 15, 'Mir tebi! Pozdravljaju te prijatelji. Pozdravi prijatelje poimence.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (72, 1, 1, 'Juda, sluga Isusa Krista, brat Jakovljev: ljubljenima u Bogu, Ocu, čuvanima za Isusa Krista - pozvanima.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (72, 1, 2, 'Obilovali milošću, mirom i ljubavlju!');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (72, 1, 3, 'Ljubljeni! Dok sam u svojoj brižljivosti kanio pisati vam o našem zajedničkom spasenju, osjetio sam potrebu da vas pismom potaknem da vojujete za vjeru koja je jednom zauvijek predana svetima.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (72, 1, 4, 'Jer ušuljali se neki, odavna već zapisani za ovaj sud, bezbožnici koji milost Boga našega promeću u razuzdanost i niječu jedinoga gospodara i Gospodina našega Isusa Krista.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (72, 1, 5, 'Želim vas podsjetiti, premda jednom zauvijek sve znate, kako je Gospodin izbavio narod iz Egipta, a zatim uništio nevjerne.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (72, 1, 6, 'I anđele, koji nisu čuvali svojeg dostojanstva nego su ostavili svoje prebivalište, sačuvao je za sud velikoga Dana, okovane u mraku vječnim okovima;');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (72, 1, 7, 'kao Sodoma i Gomora i okolni gradovi, koji su se poput njih podali bludu i otišli za drugom pÓuti, stoje za primjer, ispaštajući kaznu u vječnom ognju.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (72, 1, 8, 'Uza sve to i ovi sanjari jednako skvrne tijelo, zabacuju Veličanstvo, pogrđuju Slave.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (72, 1, 9, 'Kad se Mihael arkanđeo s đavlom prepirao za tijelo Mojsijevo, nije se usudio izreći pogrdan sud protiv njega, nego reče: \"Spriječio te Gospodin!\"');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (72, 1, 10, 'A ovi pogrđuju ono što ne poznaju; a što po naravi kao nerazumne životinje poznaju, u tom trunu.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (72, 1, 11, 'Jao njima! Putom Kajinovim pođoše, i zabludi se Bileamovoj za plaću podaše, i propadoše od pobune Korahove.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (72, 1, 12, 'Oni su ljage na vašim agapama, bezobzirno se s vama gosteći i napasajući se; oblaci bezvodni što ih vjetrovi raznose, stabla besplodna u kasnoj jeseni, dvaput usahla, iskorijenjena,');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (72, 1, 13, 'bijesno morsko valovlje što ispjenjuje svoje sramote, zvijezde lutalice kojima je spremljena crna tmina dovijeka.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (72, 1, 14, 'O njima prorokova sedmi od Adama, Henok: \"Gle, dođe Gospodin sa Desttisućama svojim');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (72, 1, 15, 'suditi svima i pokarati sve bezbožnike za sva njihova bezbožna djela kojima bezbožno sagriješiše i za sve drzovite riječi koje grešni bezbožnici izrekoše protiv njega.\"');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (72, 1, 16, 'To su rogoborni nezadovoljnici koji hode putom svojih požuda, usta im zbore naduto, ulaguju se u lice radi dobitka.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (72, 1, 17, 'A vi, ljubljeni, sjetite se riječi što ih prorekoše apostoli Gospodina našega Isusa Krista.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (72, 1, 18, 'Oni vam govorahu: \"U posljednje će vrijeme biti podrugljivaca koji će se povoditi za bezbožnim požudama svojim.\"');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (72, 1, 19, 'To su sijači razdora, sjetilnici koji nemaju Duha.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (72, 1, 20, 'A vi, ljubljeni, naziđujte se na presvetoj vjeri svojoj moleći se u Duhu Svetom,');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (72, 1, 21, 'uščuvajte se u ljubavi Božjoj, iščekujući milosrđe Gospodina našega Isusa Krista za vječni život.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (72, 1, 22, 'I jedne, svadljivce, karajte,');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (72, 1, 23, 'druge spasavajte otimajući ih ognju, trećima se pak smilujte sa strahom, mrzeći i haljinu puti okaljanu.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (72, 1, 24, 'Onomu koji vas može očuvati od pada i besprijekorne postaviti pred svoju Slavu u klicanju -');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (72, 1, 25, 'jedinomu Bogu, Spasitelju našemu, po Isusu Kristu, Gospodinu našemu: slava, veličanstvo, vlast i moć i prije svakoga vijeka, i sada, i u sve vijeke. Amen.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (73, 1, 1, 'Otkrivenje Isusa Krista: njemu ga dade Bog da on pokaže slugama svojim ono što se ima dogoditi ubrzo. I on to označi poslavši svog anđela sluzi svomu Ivanu');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (73, 1, 2, 'koji posvjedoči za riječ Božju i za svjedočanstvo Isusa Krista - za sve što vidje.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (73, 1, 3, 'Blago onomu koji čita i onima što slušaju riječi ovog proroštva te čuvaju što je u njem napisano. Jer vrijeme je blizu!');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (73, 1, 4, 'Ivan sedmerim crkvama u Aziji. Milost vam i mir od Onoga koji jest i koji bijaše i koji dolazi i od sedam duhova što su pred Prijestoljem njegovim');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (73, 1, 5, 'i od Isusa Krista, Svjedoka vjernoga, Prvorođenca od mrtvih, Vladara nad kraljevima zemaljskim. Njemu koji nas ljubi, koji nas krvlju svojom otkupi od naših grijeha');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (73, 1, 6, 'te nas učini kraljevstvom, svećenicima Bogu i Ocu svojemu: Njemu slava i vlast u vijeke vjekova! Amen!');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (73, 1, 7, 'Gle, dolazi s oblacima i gledat će ga svako oko, svi koji su ga proboli, i naricat će nad njim sva plemena zemaljska. Da! Amen.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (73, 1, 8, 'Ja sam Alfa i Omega, govori Gospodin Bog - Onaj koji jest i koji bijaše i koji dolazi, Svevladar.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (73, 1, 9, 'Ja, Ivan, brat vaš i suzajedničar u nevolji, kraljevstvu i postojanosti, u Isusu: bijah na otoku zvanu Patmos radi riječi Božje i svjedočanstva Isusova.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (73, 1, 10, 'Zanijeh se u duhu u dan Gospodnji i začuh iza sebe jak glas, kao glas trublje.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (73, 1, 11, 'Govoraše: \"Što vidiš, napiši u knjigu i pošalji sedmerim crkvama: U Efez, Smirnu, Pergam, Tijatiru, Sard, Filadelfiju, Laodiceju.\"');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (73, 1, 12, 'Okrenuh se da vidim glas koji govoraše sa mnom. I okrenuvši se, vidjeh sedam zlatnih svijećnjaka,');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (73, 1, 13, 'a posred svijećnjaka netko kao Sin Čovječji, odjeven u dugu haljinu, oko prsiju opasan zlatnim pojasom;');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (73, 1, 14, 'glava mu i vlasi bijele poput bijele vune, poput snijega, a oči mu kao plamen ognjeni;');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (73, 1, 15, 'noge mu nalik mjedi uglađenoj, kao u peći užarenoj, a glas mu kao šum voda mnogih;');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (73, 1, 16, 'u desnici mu sedam zvijezda, iz usta mu izlazi mač dvosječan, oštar, a lice mu kao kad sunce sjaji u svoj svojoj snazi.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (73, 1, 17, 'Kad ga vidjeh, padoh mu k nogama kao mrtav. A on stavi na me desnicu govoreći: \"Ne boj se! Ja sam Prvi i Posljednji,');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (73, 1, 18, 'i Živi! Mrtav bijah, a evo živim u vijeke vjekova te imam ključe Smrti, i Podzemlja.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (73, 1, 19, 'Napiši dakle što si vidio: ono što jest i što se ima dogoditi poslije.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (73, 1, 20, 'Glede tajne onih sedam zvijezda koje vidje u mojoj desnici i sedam zlatnih svijećnjaka: sedam zvijezda anđeli su sedam crkava, sedam svijećnjaka sedam je crkava.\"');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (73, 2, 1, 'Anđelu Crkve u Efezu napiši: \"Ovo govori Onaj koji drži sedam zvijezda u desnici, Onaj koji stupa posred sedam zlatnih svijećnjaka:');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (73, 2, 2, 'Znam tvoja djela, tvoj trud i postojanost tvoju i da ne možeš podnijeti opakih. Iskušao si one koji se prave apostolima, a nisu, i otkrio si da su lažljivci.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (73, 2, 3, 'Postojan si, podnio si za ime moje i nisi smalaksao.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (73, 2, 4, 'Ali imam protiv tebe: prvu si ljubav svoju ostavio.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (73, 2, 5, 'Spomeni se dakle odakle si pao, obrati se i čini prva djela. Inače dolazim k tebi i - uklonit ću tvoj svijećnjak s mjesta njegova ako se ne obratiš.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (73, 2, 6, 'Ali ovo imaš: mrziš nikolaitska djela koja i ja mrzim.\"');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (73, 2, 7, '\"Tko ima uho, nek posluša što Duh govori crkvama! Pobjedniku ću dati jesti od stabla života koje je u raju Božjem.\"');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (73, 2, 8, 'I anđelu Crkve u Smirni napiši: \"Ovo govori Prvi i Posljednji, Onaj koji bijaše mrtav i oživje:');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (73, 2, 9, 'Znam tvoju nevolju i siromaštvo - ali ti si bogat! - i pogrde od onih koji se nazivaju Židovima, a nisu, nego su sinagoga Sotonina.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (73, 2, 10, 'Ne boj se onoga što ti je trpjeti! Evo, Sotona, će neke od vas baciti u tamnicu da budete iskušani. Bit ćete u nevolji deset dana. Budi vjeran do smrti i dat ću ti vijenac života.\"');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (73, 2, 11, '\"Tko ima uho, nek posluša što Duh govori crkvama! Pobjedniku neće nauditi druga smrt.\"');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (73, 2, 12, 'I anđelu Crkve u Pergamu napiši: \"Ovo govori Onaj u koga je mač dvosjek, oštar:');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (73, 2, 13, 'Znam gdje prebivaš - ondje gdje je Sotonino prijestolje - a čvrsto se držiš moga imena te nisi zanijekao moje vjere ni u one dane kad je Antipa, moj svjedok, vjerni moj, ubijen kod vas - gdje Sotona prebiva.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (73, 2, 14, 'Ali imam nešto malo protiv tebe: imaš ondje nekih što drže nauk Bileama što pouči Balaka da stupicu stavi sinovima Izraelovim te blaguju od mesa žrtvovana idolima i bludu se podadu.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (73, 2, 15, 'Tako i ti imaš takvih koji drže nauk nikolaitski.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (73, 2, 16, 'Obrati se dakle! Inače dolazim ubrzo k tebi da ratujem s njima mačem usta svojih.\"');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (73, 2, 17, '\"Tko ima uho, nek posluša što Duh govori crkvama! Pobjedniku ću dati mane sakrivene i bijel ću mu kamen dati, a na kamenu napisano ime novo koje nitko ne zna doli onaj koji ga prima.\"');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (73, 2, 18, 'I anđelu Crkve u Tijatiri napiši: \"Ovo govori Sin Božji, Onaj u koga su oči kao plamen ognjeni, a noge mu nalik na mjed uglađenu:');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (73, 2, 19, 'Znam tvoja djela: tvoju ljubav, i vjeru, i služenje, i postojanost - i tvoja posljednja djela obilatija od prvašnjih.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (73, 2, 20, 'Ali imam protiv tebe: puštaš ženu Jezabelu, koja se pravi proročicom, da uči i zavodi moje sluge te se bludu podaju i blaguju od mesa žrtvovana idolima.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (73, 2, 21, 'Dadoh joj vremena za obraćenje, ali ona neće da se obrati od bludnosti svoje.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (73, 2, 22, 'Evo, bacam je na postelju, a bludne drugare njene u veliku nevolju ako se ne odvrate od njezinih djela;');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (73, 2, 23, 'i djecu ću joj smrću pobiti. I znat će sve crkve: Ja sam Onaj koji istražuje bubrege i srca - i dat ću vam svakomu po djelima.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (73, 2, 24, 'Vama pak velim - vama drugim u Tijatiri koji ne drže ovog nauka te ne upoznaše takozvanih dubina sotonskih: Ne stavljam na vas drugoga bremena');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (73, 2, 25, 'nego - što imate, čvrsto držite dok ne dođem.\"');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (73, 2, 26, '\"Pobjedniku, onomu što do kraja bude vršio moja djela, dat ću vlast nad narodima');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (73, 2, 27, 'i vladat će njima palicom gvozdenom, kao posuđe glineno satirati ih -');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (73, 2, 28, 'kao što i ja to primih od Oca svoga. I dat ću mu zvijezdu Danicu.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (73, 2, 29, 'Tko ima uho, nek posluša što Duh govori crkvama!\"');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (73, 3, 1, 'I anđelu Crkve u Sardu napiši: \"Ovo govori Onaj koji ima sedam duhova Božjih i sedam zvijezda: Znam tvoja djela: imaš ime da živiš, a mrtav si.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (73, 3, 2, 'Budan budi i utvrdi ostatak koji tek što ne umre. Doista, ne nađoh da su ti djela pred Bogom mojim savršena.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (73, 3, 3, 'Spomeni se dakle: kako si primio Riječ i poslušao, tako je i čuvaj - i obrati se. Ne budeš li dakle budan, doći ću kao tat, a nećeš znati u koji ću čas doći na te.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (73, 3, 4, 'Ali imaš u Sardu nekolicinu imena što ne okaljaše svojih haljina; oni će hoditi sa mnom u bjelini jer su dostojni.\"');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (73, 3, 5, '\"Tako će pobjednik biti odjeven u bijele haljine i neću izbrisati imena njegova iz knjige života i priznat ću ime njegovo pred Ocem svojim i anđelima njegovim.\"');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (73, 3, 6, '\"Tko ima uho, nek posluša što Duh govori crkvama!\"');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (73, 3, 7, 'I anđelu Crkve u Filadelfiji napiši: \"Ovo govori Sveti, Istiniti, Onaj koji ima ključ Davidov i kad otvori, nitko neće zatvoriti; kad zatvori, nitko neće otvoriti:');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (73, 3, 8, 'Znam tvoja djela. Evo, otvorio sam pred tobom vrata kojih nitko zatvoriti ne može. Doista, malena je tvoja snaga, a očuvao si moju riječ i nisi zatajio mog imena.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (73, 3, 9, 'Evo, dovest ću neke iz sinagoge Sotonine - koji sebe zovu Židovi, a nisu, nego lažu - evo, prisilit ću ih da dođu da ti se do nogu poklone te upoznaju da te ja ljubim.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (73, 3, 10, 'Budući da si očuvao moju riječ o postojanosti, i ja ću očuvati tebe od časa kušnje koji ima doći na sav svijet da se iskušaju svi pozemljari.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (73, 3, 11, 'Dolazim ubrzo. Čvrsto drži što imaš da ti nitko ne ugrabi vijenca.\"');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (73, 3, 12, '\"Pobjednika ću postaviti stupom u hramu Boga moga i odande on više neće izići i napisat ću na njemu ime Boga svoga i ime grada Boga svoga, novog Jeruzalema koji siđe s neba od Boga mojega, i ime moje novo.\"');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (73, 3, 13, '\"Tko ima uho, nek posluša što Duh govori crkvama!\"');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (73, 3, 14, 'I anđelu Crkve u Laodiceji napiši: \"Ovo govori Amen, Svjedok vjerni i istiniti, Početak Božjeg stvorenja:');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (73, 3, 15, 'Znam tvoja djela: nisi ni studen ni vruć. O da si studen ili vruć!');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (73, 3, 16, 'Ali jer si mlak, ni vruć ni studen, povratit ću te iz usta.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (73, 3, 17, 'Govoriš: \'Bogat sam, obogatih se, ništa mi ne treba!\' A ne znaš da si nevolja i bijeda, i ubog, i slijep, i gol.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (73, 3, 18, 'Savjetujem ti: kupi od mene zlata u vatri žežena da se obogatiš i bijele haljine da se odjeneš da se ne vidi tvoja sramotna golotinja; i pomasti da oči pomažeš i vidiš.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (73, 3, 19, 'Ja korim i odgajam one koje ljubim. Revan budi i obrati se!');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (73, 3, 20, 'Evo, na vratima stojim i kucam; posluša li tko glas moj i otvori mi vrata, unići ću k njemu i večerati s njim i on sa mnom.\"');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (73, 3, 21, '\"Pobjednika ću posjesti sa sobom na prijestolje svoje, kao što i ja, pobijedivši, sjedoh s Ocem svojim na prijestolje njegovo.\"');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (73, 3, 22, '\"Tko ima uho, nek posluša što Duh govori crkvama!\"');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (73, 4, 1, 'Nakon toga vidjeh: gle, vrata otvorena na nebu! A onaj prijašnji glas, što ga ono začuh kao glas trublje što govoraše sa mnom, reče: \"Uziđi ovamo i pokazat ću ti što se ima dogoditi nakon ovoga!\"');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (73, 4, 2, 'I odmah se u duhu zanijeh kad gle: prijestolje stajaše na nebu i na prijestolje Netko sjede.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (73, 4, 3, 'Taj što sjede bijaše nalik na jaspis i sard. A uokolo prijestolja duga slična smaragdu.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (73, 4, 4, 'Uokolo prijestolja dvadeset i četiri prijestolja, a na prijestolja sjedoše dvadeset i četiri starješine, obučene u bijele haljine, sa zlatnim vijencima na glavi.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (73, 4, 5, 'Od prijestolja izlaze munje, i glasovi, i gromovi; pred prijestoljem gori sedam ognjenih zubalja, to jest sedam duhova Božjih,');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (73, 4, 6, 'a pred prijestoljem kao neko stakleno more, nalik na prozirac. U sredini prijestolja, oko prijestolja, četiri bića, sprijeda i straga puna očiju:');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (73, 4, 7, 'prvo biće slično lavu, drugo biće slično juncu, treće biće s licem kao čovječjim, četvrto biće slično letećem orlu.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (73, 4, 8, 'Ta su četiri bića - u svakoga po šest krila - sve naokolo i iznutra puna očiju. Bez predaha dan i noć govore: \"Svet! Svet! Svet Gospodin, Bog Svevladar, Onaj koji bijaše i koji jest i koji dolazi!\"');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (73, 4, 9, 'I kad god bića dadu slavu i čast pohvalnicu Onomu koji sjedi na prijestolju, Živomu u vijeke vjekova,');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (73, 4, 10, 'dvadeset i četiri starješine padnu ničice pred Onim koji sjedi na prijestolju i poklone se njemu - Živomu u vijeke vjekova. I stavljaju svoje vijence pred prijestolje govoreći:');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (73, 4, 11, '\"Dostojan si, Gospodine, Bože naš, primiti slavu i čast i moć! Jer ti si sve stvorio, i tvojom voljom sve postade i bi stvoreno!\"');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (73, 5, 1, 'I vidjeh: na desnici Onoga koji sjedi na prijestolju - knjiga, iznutra i izvana ispisana, zapečaćena sa sedam pečata!');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (73, 5, 2, 'I vidjeh snažna anđela gdje iza glasa proglašuje: \"Tko je dostojan otvoriti knjigu i otpečatiti pečate njezine?\"');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (73, 5, 3, 'I nitko - ni na nebu, ni na zemlji, ni pod zemljom - nije mogao otvoriti knjige i pogledati u nju.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (73, 5, 4, 'Briznem u plač jer se nitko ne nađe dostojan otvoriti knjigu i pogledati u nju.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (73, 5, 5, 'A jedan od starješina reče: \"Ne plači! Evo, pobijedi Lav iz plemena Judina, Korijen Davidov, on će otvoriti knjigu i sedam pečata njezinih.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (73, 5, 6, 'I vidjeh: posred prijestolja i četiriju bića i posred starješina stoji, kao zaklan, Jaganjac sa sedam rogova i sedam očiju, to jest sedam duhova Božjih, po svoj zemlji poslanih.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (73, 5, 7, 'On pristupi te iz desnice Onoga koji sjedi na prijestolju uzme knjigu.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (73, 5, 8, 'A kad on uze knjigu, četiri bića i dvadeset i četiri starješine padoše ničice pred Jaganjca. U svakoga bijahu citre i zlatne posudice pune kada, to jest molitava svetačkih.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (73, 5, 9, 'Pjevaju oni pjesmu novu: \"Dostojan si uzeti knjigu i otvoriti pečate njezine jer si bio zaklan i otkupio, krvlju svojom, za Boga ljude iz svakoga plemena i jezika, puka i naroda;');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (73, 5, 10, 'učinio si ih Bogu našemu kraljevstvom i svećenicima i kraljevat će na zemlji.\"');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (73, 5, 11, 'I vidjeh, i začuh glas anđela mnogih uokolo prijestolja, i bića i starješina. Bijaše ih na mirijade mirijada i tisuće tisuća.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (73, 5, 12, 'Klicahu iza glasa: \"Dostojan je zaklani Jaganjac primiti moć, i bogatstvo, i mudrost, i snagu, i čast, i slavu, i blagoslov!\"');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (73, 5, 13, 'I začujem: sve stvorenje, i na nebu, i na zemlji, i pod zemljom, i u moru - sve na njima i u njima govori: \"Onomu koji sjedi na prijestolju i Jaganjcu blagoslov i čast, i slava i vlast u vijeke vjekova!\"');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (73, 5, 14, 'I četiri bića ponavljahu: \"Amen!\" A starješine padnu ničice i poklone se.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (73, 6, 1, 'I vidjeh: kad Jaganjac otvori prvi od sedam pečata, začujem gdje prvo od četiri bića govori glasom kao gromovnim: \"Dođi!\"');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (73, 6, 2, 'Pogledam, a ono konj bijelac i u njegova konjanika luk. I dan mu je vijenac te kao pobjednik pođe da pobijedi.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (73, 6, 3, 'Kad Jaganjac otvori drugi pečat, začujem drugo biće gdje govori: \"Dođi!\"');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (73, 6, 4, 'I iziđe drugi konj, riđan. I njegovu je konjaniku dano dignuti mir sa zemlje da se ljudi među sobom pokolju. I dan mu je mač velik.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (73, 6, 5, 'Kad Jaganjac otvori treći pečat, začujem treće biće gdje govori: \"Dođi!\" Pogledam, a ono konj vranac i njegovu konjaniku u ruci tezulja.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (73, 6, 6, 'Tada začujem kao neki glas isred četiriju bića gdje govori: \"Mjera pšenice za denar! Tri mjere ječma za denar! A ulju i vinu ne udi!\"');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (73, 6, 7, 'Kad Jaganjac otvori četvrti pečat, začujem glas četvrtoga bića gdje govori: \"Dođi!\"');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (73, 6, 8, 'Pogledam, a ono konj sivac; konjaniku njegovu ime je \"Smrt\" i prati ga Podzemlje. Dana im je vlast nad četvrtinom zemlje: ubijati mačem i glađu i smrću i zvijerima zemaljskim.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (73, 6, 9, 'Kad Jaganjac otvori peti pečat, vidjeh pod žrtvenikom duše zaklanih zbog riječi Božje i zbog svjedočanstva što ga imahu.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (73, 6, 10, 'Vikahu iza glasa: \"Ta dokle, Gospodaru sveti i istiniti! Zar nećeš suditi i osvetiti krv našu na pozemljarima?\"');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (73, 6, 11, 'I svakome je od njih dana bijela haljina i rečeno im je neka se strpe još malo vremena dok se ne ispuni broj njihovih sudrugova u službi i braće njihove koja imaju biti pobijena kao i oni.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (73, 6, 12, 'I vidjeh: kad Jaganjac otvori šesti pečat, potres velik nasta. I sunce pocrnje kao dlakava kostrijet, sav mjesec posta kao krv.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (73, 6, 13, 'I zvijezde padoše s neba na zemlju kao što smokva smokvice stresa kad je potrese žestok vjetar.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (73, 6, 14, 'Nebo iščeznu kao savijena knjiga, a sve se planine i otoci pokrenuše s mjesta.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (73, 6, 15, 'Kraljevi zemaljski, i velikaši, i vojvode, i bogataši, i mogućnici, rob i slobodnjak - svi se sakriše u spilje i pećine gorske');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (73, 6, 16, 'govoreći gorama i pećinama: \"Padnite na nas i sakrijte nas od lica Onoga koji sjedi na prijestolju i od srdžbe Jaganjčeve.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (73, 6, 17, 'Jer dođe Dan onaj veliki srdžbe njihove i tko će opstati!\"');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (73, 7, 1, 'Nakon toga vidjeh: četiri anđela stoje na četiri kraja zemlje zadržavajući četiri vjetra zemaljska da nikakav vjetar ne puše ni zemljom ni morem nit ikojim drvećem.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (73, 7, 2, 'I vidjeh drugoga jednog anđela gdje uzlazi od istoka sunčeva s pečatom Boga živoga. On povika iza glasa onoj četvorici anđela kojima bi dano nauditi zemlji i moru:');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (73, 7, 3, '\"Ne udite ni zemlji ni moru ni drveću dok ne opečatimo sluge Boga našega na čelima!\"');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (73, 7, 4, 'I začujem broj opečaćenih - sto četrdeset i četiri tisuće opečaćenih iz svih plemena sinova Izraelovih:');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (73, 7, 5, 'iz plemena Judina dvanaest tisuća opečaćenih, iz plemena Rubenova dvanaest tisuća, iz plemena Gadova dvanaest tisuća,');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (73, 7, 6, 'iz plemena Ašerova dvanaest tisuća, iz plemena Naftalijeva dvanest tisuća, iz plemena Manašeova dvanaest tisuća,');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (73, 7, 7, 'iz plemena Šimunova dvanaest tisuća, iz plemena Levijeva dvanaest tisuća, iz plemena Jisakarova dvanaest tisuća,');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (73, 7, 8, 'iz plemena Zebulunova dvanaest tisuća, iz plemena Josipova dvanaest tisuća, iz plemena Benjaminova dvanaest tisuća opečaćenih.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (73, 7, 9, 'Nakon toga vidjeh: eno velikoga mnoštva, što ga nitko ne mogaše izbrojiti, iz svakoga naroda, i plemena, i puka, i jezika! Stoje pred prijestoljem i pred Jaganjcem odjeveni u bijele haljine; palme im u rukama.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (73, 7, 10, 'Viču iz glasa: \"Spasenje Bogu našemu koji sjedi na prijestolju i Jaganjcu!\"');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (73, 7, 11, 'I svi anđeli, što stajahu uokolo prijestolja i starješina i četiriju bića, padoše pred prijestoljem ničice, na svoja lica,');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (73, 7, 12, 'i pokloniše se Bogu govoreći: \"Amen! Blagoslov i slava, i mudrost, i zahvalnica, i čast, i moć i snaga Bogu našemu u vijeke vjekova. Amen.\"');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (73, 7, 13, 'I jedan me od starješina upita: \"Ovi odjeveni u bijele haljine, tko su i odakle dođoše?\"');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (73, 7, 14, 'Odgovorih mu: \"Gospodine moj, ti to znaš.\" A on će mi: \"Oni dođoše iz nevolje velike i oprali su haljine svoje i ubijelili ih u krvi Jaganjčevoj.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (73, 7, 15, 'Zato su pred prijestoljem Božjim i služe mu dan i noć u hramu njegovu, i Onaj koji sjedi na prijestolju razapet će Šator svoj nad njima.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (73, 7, 16, 'Neće više gladovati ni žeđati, neće ih više paliti sunce nit ikakva žega');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (73, 7, 17, 'jer - Jaganjac koji je posred prijestolja bit će pastir njihov i vodit će ih na izvore voda života. I otrt će Bog svaku suzu s očiju njihovih.\"');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (73, 8, 1, 'Kad Jaganjac otvori sedmi pečat, nasta muk na nebu oko pola sata.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (73, 8, 2, 'I vidjeh: sedmorici anđela što stoje pred Bogom dano je sedam trubalja.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (73, 8, 3, 'I drugi jedan anđeo pristupi i sa zlatnom kadionicom stane na žrtvenik. I dano mu je mnogo kada da ga s molitvama svih svetih prinese na zlatni žrtvenik pred prijestoljem.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (73, 8, 4, 'I vinu se dim kadni s molitvama svetih iz ruke anđelove pred lice Božje.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (73, 8, 5, 'Anđeo uze kadionicu, napuni je vatrom sa žrtvenika i prosu na zemlju. I udariše gromovi, i glasovi, i munje, i potres.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (73, 8, 6, 'A sedam anđela sa sedam trubalja pripremiše se da zatrube.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (73, 8, 7, 'Prvi zatrubi. I nastadoše tuča i oganj, pomiješani s krvlju, i budu bačeni na zemlju. I trećina zemlje izgorje, i trećina stabala izgorje, i sva zelena trava izgorje.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (73, 8, 8, 'Drugi anđeo zatrubi. I nešto kao gora velika, ognjem zapaljena, bačeno bi u more. I trećina se mora pretvori u krv');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (73, 8, 9, 'te izginu trećina stvorenja što u moru žive i trećina lađa propade.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (73, 8, 10, 'Treći anđeo zatrubi. I pade s neba zvijezda velika - gorjela je kao zublja - pade na trećinu rijeka i na izvore voda.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (73, 8, 11, 'Zvijezdi je ime Pelin. I trećina se voda pretvori u pelin te mnoštvo ljudi poginu od zagorčenih voda.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (73, 8, 12, 'Četvrti anđeo zatrubi. I bi udarena trećina sunca i trećina mjeseca i trećina zvijezda te pomrčaše za trećinu. I dan izgubi trećinu svoga sjaja, a tako i noć.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (73, 8, 13, 'I vidjeh i začuh orla: letio posred neba i vikao iza glasa: \"Jao! Jao! Jao pozemljarima od novih glasova trubalja preostale trojice anđela koji će sad-na zatrubiti!\"');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (73, 9, 1, 'Peti anđeo zatrubi. I vidjeh: zvijezda je s neba na zemlju pala i dani su joj ključi zjala Bezdanova.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (73, 9, 2, 'Ona otvori zjalo Bezdanovo i vinu se iz zjala dim kao dim iz peći goleme te pomrča sunce i zrak od dima iz zjala.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (73, 9, 3, 'Iz dima pak iziđoše na zemlju skakavci i dana im je moć kakvu imaju štipavci zemaljski.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (73, 9, 4, 'I zapovjeđeno im je da ne ude travi zemaljskoj nit ikojem zelenilu nit ikojem stablu, nego samo ljudima koji nemaju pečata Božjega na čelu.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (73, 9, 5, 'I dano im je ne da ih ubijaju, nego samo da ih muče pet mjeseci, a muka njihova da bude kao muka od uboda štipavaca.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (73, 9, 6, 'U one će dane ljudi iskati smrt, ali je neće naći; poželjet će umrijeti, ali smrt će bježati od njih.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (73, 9, 7, 'Skakavci bijahu izgledom nalik na konje za boj spremne. Na glavama im kao neki zlatni vijenci, lica im kao u ljudi,');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (73, 9, 8, 'kose kao u žena, a zubi kao u lavova.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (73, 9, 9, 'Imahu oklope kao od željeza, a šum krila njihovih kao štropot bojnih kola s mnogo konja što u boj jure.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (73, 9, 10, 'Repovi im kao u štipavaca, sa žalcima, a u repovima im moć da ude ljudima pet mjeseci.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (73, 9, 11, 'Nad njima je kralj, anđeo Bezdana, hebrejski mu ime Abadon, grčki Apolion - Upropastitelj.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (73, 9, 12, 'Prvi Jao prođe. Evo, za njim dolaze još dva druga Jao.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (73, 9, 13, 'Šesti anđeo zatrubi. I začujem neki glas iz rogova zlatnoga žrtvenika pred Bogom.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (73, 9, 14, 'Govoraše šestom anđelu koji je držao trublju: \"Odriješi ona četiri anđela svezana na Rijeci velikoj, Eufratu.\"');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (73, 9, 15, 'I odriješena bijahu četiri anđela, spremna za taj čas i dan i mjesec i godinu, da pobiju trećinu ljudi.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (73, 9, 16, 'A broj četa konjaničkih, kako sam čuo, bijaše dvije mirijade mirijada.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (73, 9, 17, 'Ovako u viđenju vidjeh konje i njihove jahače: imahu oklope ognjene, plavetne i sumporne boje; glave im kao u lavova, iz usta im sukljao oganj, dim i sumpor.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (73, 9, 18, 'Od ovih triju zala poginu trećina ljudi - od ognja, dima i sumpora što sukljahu konjima iz usta.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (73, 9, 19, 'Doista, snaga je ovim konjima u ustima i repovima: repovi im kao u zmija, s glavama kojima ude.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (73, 9, 20, 'Ipak, preostali ljudi, što ne poginuše od tih zala, ne obratiše se od djela ruku svojih, da se više ne klanjaju zlodusima i kumirima - ni zlatnima, ni srebrnima, ni mjedenima, ni kamenima ni drvenima koji niti vide niti čuju nit hodaju -');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (73, 9, 21, 'i ne obratiše se od svojih ubojstava ni od svojih čaranja ni od svoga bluda niti od svojih krađa.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (73, 10, 1, 'I vidjeh drugoga jednog, snažnog anđela: silazio s neba ogrnut oblakom, na glavi mu duga, lice mu kao sunce, a noge kao ognjeno stupovlje;');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (73, 10, 2, 'u ruci drži otvorenu knjižicu. I zakorači desnom nogom na more, lijevom na zemlju pa povika iza glasa kao kad lav riče.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (73, 10, 3, 'I kad povika, oglasi se sedam gromova tutnjavom.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (73, 10, 4, 'A kad se oglasi sedam gromova, htjedoh pisati, ali začujem glas s neba: \"Zapečati to što prozbori sedam gromova! Toga ne piši!\"');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (73, 10, 5, 'I onaj anđeo što ga vidjeh gdje stoji na moru i zemlji, podiže k nebu desnicu');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (73, 10, 6, 'i zakle se Živim u vijeke vjekova, koji stvori nebo i sve što je na njemu, zemlju i sve što je na njoj, more i sve što je u njemu: \"Neće više biti vremena!');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (73, 10, 7, 'Nego - u dane kad se oglasi sedmi anđeo, čim zatrubi, dovršit će se otajstvo Božje kao što on to navijesti slugama svojim prorocima.\"');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (73, 10, 8, 'I glas što ga začuh s neba opet prozbori sa mnom: \"Idi, uzmi otvorenu knjigu iz ruke anđela što stoji na moru i na zemlji!\"');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (73, 10, 9, 'Pristupim k anđelu i zamolim ga da mi dade knjižicu. A on će mi: \"Uzmi je i progutaj! Zagorčit će ti utrobu, ali će ti u ustima biti slatka kao med.\"');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (73, 10, 10, 'Uzeh knjižicu iz ruke anđelove i progutah je. I bijaše mi u ustima kao med slatka, ali kad je progutah, zagorči mi utrobu.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (73, 10, 11, 'I rečeno mi je: \"Treba da ponovno prorokuješ proti pucima i narodima i kraljevima mnogim!\"');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (73, 11, 1, 'I dana mi je trska slična palici i rečeno mi je: \"Ustani i izmjeri hram Božji i žrtvenik i poklonike u njemu!');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (73, 11, 2, 'Vanjsko dvorište hrama mimoiđi, ne mjeri ga jer je dano poganima: gazit će svetim gradom četrdeset i dva mjeseca.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (73, 11, 3, 'I ja ću poslati dva svoja svjedoka da, obučeni u kostrijet, prorokuju tisuću dvjesta i šezdeset dana.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (73, 11, 4, 'Oni su dvije masline i dva svijećnjaka što stoje pred Gospodarom zemlje.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (73, 11, 5, 'Ako im tko hoće nauditi, oganj suče iz usta njihovih i proždire njihove neprijatelje. Doista, htjedne li im tko nauditi, tako treba da pogine.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (73, 11, 6, 'Oni imaju vlast zaključati nebo da ne pada kiša dok prorokuju; imaju vlast pretvoriti vode u krv i udariti zemlju kojim god zlom kad god htjednu.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (73, 11, 7, 'A kada dovrše svoje svjedočanstvo, Zvijer koja izlazi iz Bezdana zaratit će s njima, pobijediti ih i ubiti.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (73, 11, 8, 'I njihova će trupla ležati na trgu grada velikoga koji se duhovno zove Sodoma i Egipat, gdje je i Gospodin njihov raspet.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (73, 11, 9, 'Ljudi iz svih puka i plemena i jezika i naroda gledat će njihova trupla tri i pol dana i neće dopustiti da im se trupla u grob polože.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (73, 11, 10, 'Pozemljari će se radovati i veseliti zbog njihove nesreće i darivati jedan drugoga jer su ta dva proroka zadavala muku pozemljarima.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (73, 11, 11, 'Ali nakon tri i pol dana duh životni od Boga uđe u njih i stadoše na noge te strah velik obuze one koji ih promatrahu.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (73, 11, 12, 'I začuše glas s neba silan: \"Uziđite ovamo!\" I uziđoše na oblaku u nebo na očigled svojih neprijatelja.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (73, 11, 13, 'U taj čas nasta velik potres: pade desetina grada, a u potresu poginu sedam tisuća ljudi. Preživjele spopade strah te proslaviše Boga nebeskoga.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (73, 11, 14, 'Drugi Jao prođe. Evo, treći Jao dolazi ubrzo!');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (73, 11, 15, 'I sedmi anđeo zatrubi. I na nebu odjeknuše silni glasovi: \"Uspostavljeno je nad svijetom kraljevstvo Gospodara našega i Pomazanika njegova i kraljevat će u vijeke vjekova!\"');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (73, 11, 16, 'Tada dvadeset i četiri starješine, što pred Bogom sjedoše na prijestolja,');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (73, 11, 17, 'padoše ničice i pokloniše se Bogu govoreći. \"Zahvaljujemo ti, Gospodaru, Bože, Svevladaru, koji jesi i koji bijaše, zato što uze u ruke moć svoju veliku i zakralji se!');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (73, 11, 18, 'Gnjevili se narodi, ali dođe srdžba tvoja i čas da se sudi mrtvima i naplata dade slugama tvojim prorocima i svetima i svima koji se boje imena tvojega, malima i velikima; i da se unište oni koji kvare zemlju.\"');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (73, 11, 19, 'I otvori se hram Božji na nebu i pokaza se Kovčeg saveza njegova u hramu njegovu te udare munje i glasovi i gromovi i potres i tuča velika.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (73, 12, 1, 'I znamenje veliko pokaza se na nebu: Žena odjevena suncem, mjesec joj pod nogama, a na glavi vijenac od dvanaest zvijezda.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (73, 12, 2, 'Trudna viče u porođajnim bolima i mukama rađanja.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (73, 12, 3, 'I pokaza se drugo znamenje na nebu: gle, Zmaj velik, ognjen, sa sedam glava i deset rogova; na glavama mu sedam kruna,');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (73, 12, 4, 'a rep mu povlači trećinu zvijezda nebeskih - i obori ih na zemlju. Zmaj stade pred Ženu koja imaše roditi da joj, čim rodi, proždre Dijete.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (73, 12, 5, 'I ona porodi sina, muškića, koji će vladati svim narodima palicom gvozdenom. I Dijete njeno bi uzeto k Bogu i prijestolju njegovu.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (73, 12, 6, 'A Žena pobježe u pustinju gdje joj Bog pripravi sklonište da se ondje hrani tisuću dvjesta i šezdeset dana.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (73, 12, 7, 'I nasta rat na nebu: Mihael i njegovi anđeli zarate se sa Zmajem. Zmaj uđe u rat i anđeli njegovi,');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (73, 12, 8, 'ali ne nadvlada. I ne bijaše im više mjesta na nebu.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (73, 12, 9, 'Zbačen je Zmaj veliki, Stara zmija - imenom Ðavao, Sotona, zavodnik svega svijeta. Bačen je na zemlju, a s njime su bačeni i anđeli njegovi.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (73, 12, 10, 'I začujem glas na nebu silan: \"Sada nasta spasenje i snaga i kraljevstvo Boga našega i vlast Pomazanika njegova! Jer zbačen je tužitelj braće naše koji ih je dan i noć optuživao pred Bogom našim.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (73, 12, 11, 'Ali oni ga pobijediše krvlju Jaganjčevom i riječju svojega svjedočanstva: nisu ljubili života svoga - sve do smrti.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (73, 12, 12, 'Zato veselite se, nebesa i svi nebesnici! A jao vama, zemljo i more, jer Ðavao siđe k vama, gnjevan veoma, znajući da ima malo vremena!\"');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (73, 12, 13, 'Kad Zmaj vidje da je zbačen na zemlju, stade progoniti Ženu koja rodi muškića.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (73, 12, 14, 'No Ženi bijahu dana dva velika krila orlujska da odleti u pustinju, u svoje sklonište gdje se, sklonjena od Zmije, hrani jedno vrijeme i dva vremena i polovicu vremena.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (73, 12, 15, 'I Zmija iz usta pusti za Ženom vodu poput rijeke da je rijeka odnese.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (73, 12, 16, 'Ali zemlja priteče u pomoć Ženi: otvori usta i popi rijeku što je Zmaj pusti iz usta.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (73, 12, 17, 'I razgnjevi se Zmaj na Ženu pa ode i zarati se s ostatkom njezina potomstva, s onima što čuvaju Božje zapovijedi i drže svjedočanstvo Isusovo.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (73, 12, 18, 'I stade na morski žal.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (73, 13, 1, 'I vidjeh: iz mora Zvijer izlazi sa deset rogova i sedam glava; na rogovima joj deset kruna, na glavama bogohulna imena.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (73, 13, 2, 'Ta Zvijer što je vidjeh bijaše nalik na leoparda, noge joj kao medvjeđe, usta kao usta lavlja. Zmaj joj dade svoju silu i prijestolje i vlast veliku.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (73, 13, 3, 'Jedna joj glava bijaše kao na smrt zaklana, ali joj se smrtna rana zaliječila. Sva se zemlja, začuđena, zanijela za Zvijeri');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (73, 13, 4, 'i svi se pokloniše Zmaju koji dade takvu vlast Zvijeri. Pokloniše se i Zvijeri govoreći: \"Tko je kao Zvijer! Tko bi smio ratovati s njom?\"');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (73, 13, 5, 'I dana su joj usta da govori drskosti i hule i dana joj je vlast da to čini četrdeset i dva mjeseca.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (73, 13, 6, 'I ona otvori usta da huli Boga, da huli ime njegovo, njegov Šator i nebesnike.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (73, 13, 7, 'I dano joj je da se zarati sa svecima i da ih pobijedi. Dana joj je vlast nad svakim plemenom i pukom i jezikom i narodom:');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (73, 13, 8, 'da joj se poklone svi pozemljari, oni kojima ime nije zapisano u knjizi života zaklanog Jaganjca, od postanka svijeta.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (73, 13, 9, 'Tko ima uho, nek posluša!');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (73, 13, 10, 'Je li tko za progonstvo, u progonstvo će ići! Je li tko za mač, da bude pogubljen, mačem će biti pogubljen! U tom je postojanost i vjera svetih.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (73, 13, 11, 'I vidjeh: druga jedna Zvijer uzlazi iz zemlje, ima dva roga poput jaganjca, a govori kao Zmaj.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (73, 13, 12, 'Vrši svu vlast one prve Zvijeri, u njenoj nazočnosti. Prisiljava zemlju i sve pozemljare da se poklone prvoj Zvijeri kojoj ono zacijeli smrtna rana.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (73, 13, 13, 'Čini znamenja velika: i oganj spušta s neba na zemlju naočigled ljudi.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (73, 13, 14, 'Tako zavodi pozemljare znamenjima koja joj je dano činiti u nazočnosti Zvijeri: svjetuje pozemljarima da načine kip Zvijeri koja bijaše udarena mačem, ali preživje.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (73, 13, 15, 'I dano joj je udahnuti život kipu Zvijeri te kip Zvijeri progovori i poubija sve koji se god ne klanjaju kipu Zvijeri.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (73, 13, 16, 'Ona postiže da se svima - malima i velikima, bogatima i ubogima, slobodnjacima i robovima - udari žig na desnicu ili na čelo,');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (73, 13, 17, 'i da nitko ne mogne kupovati ili prodavati osim onog koji nosi žig s imenom Zvijeri ili s brojem imena njezina.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (73, 13, 18, 'U ovome je mudrost: u koga je uma, nek odgoneta broj Zvijeri. Broj je to jednog čovjeka, a broj mu je šest stotina šezdeset i šest.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (73, 14, 1, 'I vidjeh: gle, Jaganjac stoji na gori Sionu, a s njime sto četrdeset i četiri tisuće - na čelima im napisano ime njegovo i ime Oca njegova!');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (73, 14, 2, 'I začujem s neba glas, kao šum voda mnogih i tutnjavu silna groma; glas taj koji začuh bijaše kao glas citraša što sviraju na citrama.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (73, 14, 3, 'Pjevali su pjesmu novu pred prijestoljem i pred četiri bića i pred starješinama. Nitko ne mogaše naučiti te pjesme doli one sto četrdeset i četiri tisuće - otkupljeni sa zemlje.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (73, 14, 4, 'Ti se ne okaljaše sa ženama, djevci su! Oni prate Jaganjca kamo god pođe. Otkupljeni su od ljudi kao prvine Bogu i Jaganjcu;');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (73, 14, 5, 'na ustima se njihovim laž ne nađe, neporočni su.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (73, 14, 6, 'I vidjeh: drugi jedan anđeo leti posred neba s evanđeljem vječnim da ga proglasi svim pozemljarima, svakom narodu i plemenu i jeziku i puku.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (73, 14, 7, 'Viče iza glasa: \"Bojte se Boga i dajte mu slavu jer dođe čas suda njegova! I poklonite se njemu koji stvori nebo i zemlju i more i izvore voda!\"');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (73, 14, 8, 'Za njim eto drugog anđela koji govori: \"Pade, pade Babilon, veliki koji vinom gnjeva i bluda svojega opi sve narode!\"');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (73, 14, 9, 'Za njima eto i trećeg anđela koji vikaše iza glasa: \"Tko god se klanja Zvijeri i kipu njezinu te primi žig na čelo ili ruku,');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (73, 14, 10, 'pit će vino gnjeva Božjega, nerazvodnjeno, natočeno već u čaši srdžbe njegove! I bit će udaren na muke u ognju i sumporu svetim anđelima naočigled i naočigled Jaganjcu.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (73, 14, 11, 'Dim muke njihove suklja u vijeke vjekova. Ni danju ni noću nemaju počinka oni koji se klanjaju Zvijeri i kipu njezinu i tko god primi žig s imenom njezinim.\"');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (73, 14, 12, 'U tom je postojanost svetih - onih što čuvaju zapovijedi Božje i vjeru Isusovu.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (73, 14, 13, 'I začujem glas s neba: \"Piši! Od sada blaženi mrtvi koji umiru u Gospodinu! Da, govori Duh, neka otpočinu od svojih trudova! Jer prate ih djela njihova!\"');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (73, 14, 14, 'I vidjeh: gle, bijel oblak, a na oblak sjede Netko kao Sin Čovječji; na glavi mu zlatan vijenac, u ruci oštar srp.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (73, 14, 15, 'I drugi jedan anđeo iziđe iz hrama vičući iza glasa onomu što sjedi na oblaku: \"Mahni srpom i žanji jer dođe čas žetvi, zrela je žetva zemaljska!\"');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (73, 14, 16, 'I onaj što sjedi na oblaku baci srp na zemlju i zemlja bi požnjevena.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (73, 14, 17, 'I drugi jedan anđeo iziđe iz hrama nebeskoga. I on imaše oštar srp.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (73, 14, 18, 'I od žrtvenika iziđe drugi anđeo - onaj koji ima vlast nad ognjem - pa povika iza glasa onomu, s oštrim srpom: \"Mahni oštrim srpom i poberi grozdove u vinogradu zemaljskom jer sazri grožđe!\"');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (73, 14, 19, 'I anđeo baci srp na zemlju i obra vinograd zemaljski, a obrano baci u veliku kacu gnjeva Božjega.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (73, 14, 20, 'Gazila se kaca izvan grada te poteče krv iz kace konjima do uzda, tisuću i šest stotina stadija uokolo.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (73, 15, 1, 'I vidjeh drugo znamenje na nebu, veliko i čudesno: sedam anđela sa sedam zala posljednjih - s njima se navršuje gnjev Božji.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (73, 15, 2, 'I vidjeh kao neko more od prozirca pomiješano s ognjem. Oni koji pobijediše Zvijer i kip njezin i broj imena njezina stoje u moru od prozirca s citrama Božjim u ruci.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (73, 15, 3, 'Pjevaju pjesmu Mojsija, sluge Božjega, i pjesmu Jaganjčevu: \"Velika su i čudesna djela tvoja, Gospodine, Bože, Svevladaru! Pravedni su i istiniti putovi tvoji, Kralju naroda!');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (73, 15, 4, 'Tko da te se ne boji, Gospodine, tko da ne slavi ime tvoje! Ti si jedini svet! I zato svi će narodi doći i klanjati se pred tobom jer se očitovahu pravedna djela tvoja!\"');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (73, 15, 5, 'Nakon toga vidjeh: otvori se hram Šatora svjedočanstva na nebu!');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (73, 15, 6, 'Iziđe sedam anđela sa sedam zala iz hrama; odjeveni bijahu u blistav bijeli lan, oko prsiju opasani zlatnim pojasom.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (73, 15, 7, 'Jedno od četiri bića dade sedmorici anđela sedam zlatnih čaša, punih gnjeva Boga koji živi u vijeke vjekova.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (73, 15, 8, 'I hram se napuni dimom od Slave Božje i od njegove snage te nitko ne mogaše ući u hram dok se ne navrši sedam zala sedmorice anđela.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (73, 16, 1, 'I začujem iz hrama jak glas koji viknu sedmorici anđela: \"Hajdete, izlijte sedam čaša gnjeva Božjega na zemlju!\"');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (73, 16, 2, 'Ode prvi i izli svoju čašu na zemlju. I pojavi se čir, koban i bolan, na ljudima što nose žig Zvijerin i klanjaju se kipu njezinu.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (73, 16, 3, 'Drugi izli svoju čašu na more. I ono posta krv kao krv mrtvačeva te izginu sve živo u moru.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (73, 16, 4, 'Treći izli svoju čašu na rijeke i izvore voda. I postadoše krv.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (73, 16, 5, 'I začujem anđela voda gdje govori: \"Pravedan si, Ti koji jesi i koji bijaše, Sveti, što si tako dosudio!');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (73, 16, 6, 'Oni su prolili krv svetih i proroka i stoga ih krvlju napajaš! Zavrijedili su!\"');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (73, 16, 7, 'I začujem žrtvenik kako govori: \"Da, Gospode, Bože, Svevladaru! Istiniti su i pravedni sudovi tvoji!\"');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (73, 16, 8, 'Četvrti izli svoju čašu na sunce. I suncu je dano da pali ljude ognjem.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (73, 16, 9, 'I silna je žega palila ljude te su hulili ime Boga koji ima vlast nad tim zlima, ali se ne obratiše da mu slavu dadu.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (73, 16, 10, 'Peti izli svoju čašu na prijestolje Zvijeri. I kraljevstvo joj prekriše tmine. Ljudi su grizli jezike od muke');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (73, 16, 11, 'i hulili Boga nebeskoga zbog muka i čireva, ali se ne obratiše od djela svojih.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (73, 16, 12, 'Šesti izli svoju čašu na Eufrat, rijeku veliku. I presahnu voda te načini prolaz kraljima s istoka sunčeva.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (73, 16, 13, 'I vidjeh: iz usta Zmajevih i iz usta Zvijerinih i iz usta Lažnoga proroka izlaze tri duha nečista, kao žabe.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (73, 16, 14, 'To su dusi zloduha što čine znamenja, a pođoše sabrati kraljeve svega svijeta na rat za Dan veliki Boga Svevladara.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (73, 16, 15, 'Evo dolazim kao tat! Blažen onaj koji bdije i čuva haljine svoje da ne ide gol te mu se ne vidi sramota!');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (73, 16, 16, 'I skupiše ih na mjesto koje se hebrejski zove Harmagedon.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (73, 16, 17, 'I sedmi izli svoju čašu na zrak. Uto iz hrama, s prijestolja, iziđe jak glas i viknu: \"Svršeno je!\"');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (73, 16, 18, 'I udariše munje i glasovi i gromovi i nasta potres velik, kakva ne bijaše otkako je ljudi - tako bijaše silan potres taj.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (73, 16, 19, 'I prasnu natroje grad veliki i gradovi naroda padoše. Spomenu se Bog Babilona velikoga da mu dade piti iz čaše vina gnjevne srdžbe Božje.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (73, 16, 20, 'I pobjegoše svi otoci, iščezoše gore,');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (73, 16, 21, 'a iz neba se spusti na ljude tuča velika, poput talenta. Ljudi su hulili Boga zbog zla tuče jer zlo njezino bijaše silno veliko.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (73, 17, 1, 'I dođe jedan od sedam anđela što nose sedam čaša i prozbori mi: \"Dođi pokazat ću ti sud nad Bludnicom velikom što sjedi nad vodama velikim,');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (73, 17, 2, 's kojom su bludničili kraljevi zemlje i pozemljari se opiše vinom bluda njezina.\"');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (73, 17, 3, 'I odnese me u duhu u pustinju. Tu vidjeh Ženu koja sjede na skrletnu Zvijer, punu bogohulnih imena, sa sedam glava i deset rogova.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (73, 17, 4, 'Žena bijaše odjevena u grimiz i skrlet, sva u zlatu, dragom kamenju i biserju. U ruci joj zlatna čaša puna gnusobe i nečisti bluda njezina.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (73, 17, 5, 'Na čelo joj napisano ime - tajna: \"Babilon veliki, mati bludnica i gnusoba zemljinih.\"');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (73, 17, 6, 'I vidjeh: Žena je pijana od krvi svetih i od krvi svjedoka Isusovih. Kad je vidjeh, čudom se silnim začudih.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (73, 17, 7, 'Nato će mi anđeo: \"Što se čudiš? Ja ću ti kazati tajnu te žene i Zvijeri koja je nosi, Zvijeri sa sedam glava i deset rogova.\"');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (73, 17, 8, '\"Zvijer koju vidje bijaše i više nije; zamalo izlazi iz Bezdana i ide u propast. I zapanjit će se pozemljari - oni kojima ime, od postanka svijeta, nije zapisano u knjigu života - kad vide da Zvijer bijaše i više nije, a opet je tu.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (73, 17, 9, 'Tu se hoće mudre pameti! Sedam glava sedam je bregova na kojima žena sjedi. A i sedam kraljeva:');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (73, 17, 10, 'pet ih već pade, jedan jest, a jedan još ne dođe: kada dođe, ostati mu je zamalo.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (73, 17, 11, 'I Zvijer koja bijaše i više nije, osma je, a iz broja je njih sedmero, i ide u propast.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (73, 17, 12, 'Deset rogova što ih vidje deset je kraljeva; oni još ne primiše kraljevstva, ali će - samo za jedan sat - primiti vlast kao kraljevi zajedno sa Zvijeri.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (73, 17, 13, 'Jedne su misli: svu svoju silu i vlast predati Zvijeri.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (73, 17, 14, 'Ratovat će protiv Jaganjca, ali će ih pobijediti Jaganjac - i njegovi pozvanici, izabranici, vjernici - jer on je Gospodar gospodara i Kralj kraljeva.\"');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (73, 17, 15, 'I reče mi anđeo: \"Vode što ih vidje, na kojima Bludnica sjedi, to su puci i mnoštva i narodi i jezici.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (73, 17, 16, 'I onih deset rogova što ih vidje i Zvijer - oni će zamrziti Bludnicu, opustošiti je i ogoliti, najesti se mesa njezina i ognjem je spaliti.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (73, 17, 17, 'Jer Bog im u srce stavi izvršiti naum njegov: da jednodušno predadu kraljevstvo svoje Zvijeri dok se ne ispune riječi Božje.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (73, 17, 18, 'Žena koju vidje grad je veliki što kraljuje nad kraljevima zemaljskim.\"');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (73, 18, 1, 'Nakon toga vidjeh: jedan drugi anđeo silazi s neba s moći velikom! Sva se zemlja zasvijetlila od njegova sjaja.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (73, 18, 2, 'On povika iza glasa: \"Pade, pade Babilon veliki - Bludnica - i postade prebivalištem zloduha, nastambom svih duhova nečistih, nastambom svih ptica nečistih mrskih');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (73, 18, 3, 'jer se gnjevnim vinom bluda njezina opiše narodi; s njom su bludničili svi kraljevi zemaljski, a trgovci se zemaljski obogatiše od silna raskošja njezina.\"');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (73, 18, 4, 'Začujem i drugi glas s neba: \"Iziđite iz nje, narode moj, da vas ne zadese zla njezina te ne budete suzajedničari grijeha njezinih!');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (73, 18, 5, 'Jer njezini grijesi do neba dopriješe i spomenu se Bog zločina njezinih.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (73, 18, 6, 'Vratite joj milo za drago, naplatite joj dvostruko po djelima! U čašu u koju je ona natakala natočite dvostruko!');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (73, 18, 7, 'Koliko se razmetala sjajem i raskoši, toliko joj zadajte muka i jada! Jer u srcu je svome govorila: \'Na prijestolju sjedim kao kraljica i nikad neću obudovjeti, jad me nikada zadesiti neće!\'');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (73, 18, 8, 'Stoga u isti će je dan zla zadesiti: smrt i jad i glad te će sva u ognju biti spaljena. Jer silan je Gospod, Bog, Sudac njezin!\"');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (73, 18, 9, 'I plakat će i naricati za njom kraljevi zemlje što su s njome bludničili i raskošno živjeli kad gledali budu dim požara njezina.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (73, 18, 10, 'Prestrašeni mukama njezinim, izadaleka će stajati i naricati: \"Jao, jao, grade veliki, Babilone, grade silni! Kako li te u tren oka stiže osuda!\"');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (73, 18, 11, 'I trgovci zemaljski plaču nad njom i tuguju jer im trga nitko više ne kupuje:');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (73, 18, 12, 'ni zlata, ni srebra, ni dragoga kamenja, ni biserja, ni tanana lana, ni grimiza, ni svile, ni skrleta: nit ikakva mirisava drveta, nit ikakva predmeta od slonove kosti, nit ikakva predmeta od skupocjena drveta, nit od mjedi, nit od željeza, nit od mramora;');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (73, 18, 13, 'ni cimeta, ni balzama, ni miomirisa, ni pomasti, ni tamjana, ni vina, ni ulja, ni bijeloga brašna, ni pšenice; ni goveda, ni ovaca, ni konja, ni kočija, ni roblja nit ikoje žive duše.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (73, 18, 14, '\"Voće za kojim ti duša žudjela pobježe od tebe, sav raskoš i sjaj propade ti - ne, nema ga više!\"');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (73, 18, 15, 'Trgovci što svim tim trgovahu, što ih ona obogati, izdaleka će stajati, prestrašeni mukama njezinim, plakat će i tugovati:');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (73, 18, 16, '\"Jao, jao, grade veliki, odjeveni nekoć u lan tanan i grimiz i skrlet, nakićeni zlatom i dragim kamenjem i biserjem!');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (73, 18, 17, 'U tren oka opustje toliko bogatstvo!\" I svi kormilari i putnici, svi mornari i moreplovci izdaleka stoje');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (73, 18, 18, 'i, gledajući dim njezina požara, zapomažu: \"Koji li je grad sličan gradu ovom velikom?\"');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (73, 18, 19, 'I posuše glavu pepelom te plačući i tugujući viknuše: \"Jao, jao, grada li velikoga! Dragocjenostima se njegovim obogatiše svi posjednici morskih brodova, a evo - u tren oka opustje!\"');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (73, 18, 20, 'Veseli se nad njom, nebo, i svi sveti i apostoli i proroci jer Bog osudivši nju, vama pravo dosudi!');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (73, 18, 21, 'I jedan snažan anđeo uze kamen, velik poput mlinskoga kamena, i baci ga u more govoreći: \"Tako će silovito biti strovaljen Babilon, grad veliki, i nikada ga više biti neće!\"');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (73, 18, 22, '\"Glas citraša i pjevača i svirača i trubljača u tebi se više neće čuti! Obrtnik vješt kojem god umijeću u tebi se više neće naći! Klopot žrvnja u tebi se više neće čuti!');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (73, 18, 23, 'Svjetlost svjetiljke u tebi više neće sjati! Glas zaručnika i zaručnice u tebi se više neće čuti! Jer trgovci tvoji bijahu velikaši zemlje i čaranja tvoja zavedoše sve narode;');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (73, 18, 24, 'i u tebi se našla krv proroka i svetaca i svih zaklanih na zemlji.\"');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (73, 19, 1, 'Nakon toga začujem kao jak glas silnoga mnoštva na nebu: \"Aleluja! Spasenje i slava i moć Bogu našemu!');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (73, 19, 2, 'Doista, istiniti su i pravedni sudovi njegovi jer osudi veliku Bludnicu, što pokvari zemlju bludom svojim, i osveti na njoj krv slugu svojih!\"');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (73, 19, 3, 'I ponove: \"Aleluja! Dim njezin suklja u vijeke vjekova!\"');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (73, 19, 4, 'Nato starješine, njih dvadesetčetvorica, i ona četiri bića padoše ničice i p okloniše se Bogu, koji sjedi na prijestolju, govoreći: \"Amen! Aleluja!\"');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (73, 19, 5, 'I s prijestolja iziđe glas: \"Hvalite Boga našega, sve sluge njegove, svi koji se njega bojite, i mali i veliki!\"');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (73, 19, 6, 'I začuh kao glas silna mnoštva i kao šum voda mnogih i kao prasak gromova silnih: \"Aleluja! Zakraljeva Gospod, Bog naš Svevladar!');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (73, 19, 7, 'Radujmo se i kličimo i slavu mu dajmo jer dođe svadba Jaganjčeva, opremila se Zaručnica njegova!');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (73, 19, 8, 'Dano joj je odjenuti se u lan tanan, blistav i čist!\" A lan - pravedna su djela svetih.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (73, 19, 9, 'I reče mi: \"Piši! Blago onima koji su pozvani na svadbenu gozbu Jaganjčevu!\" I reče mi: \"Ove su riječi istinite, Božje.\"');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (73, 19, 10, 'Padoh mu pred noge da mu se poklonim. A on će mi: \"Nipošto! Sluga sam kao i ti i braća tvoja koja imaju svjedočanstvo Isusovo. Bogu se pokloni!\" Jer svjedočanstvo Isusovo duh je proročki.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (73, 19, 11, 'I vidjeh: nebo otvoreno - i gle, konj bijelac, a na nj sjeo On, zvani Vjerni i Istiniti, a sudi i vojuje po pravdi;');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (73, 19, 12, 'oči mu plamen ognjeni, na glavi mu mnoge krune; nosi napisano ime kojeg nitko ne zna doli on sam;');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (73, 19, 13, 'ogrnut je ogrtačem krvlju natopljenim; ime mu: Riječ Božja.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (73, 19, 14, 'Prate ga na bijelcima Vojske nebeske, odjevene u lan tanan, bijel i čist.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (73, 19, 15, 'Iz usta mu izlazi oštar mač kojim će posjeći narode. Vladat će njima palicom gvozdenom. On gazi u kaci gnjevne srdžbe Boga Svevladara.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (73, 19, 16, 'Na ogrtač, o boku, napisano mu ime: \"Kralj kraljeva i Gospodar gospodara.\"');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (73, 19, 17, 'I vidjeh jednog anđela: stajaše na suncu vičući iza glasa svim pticama što nebom lete: \"Ovamo! Skupite se na veliku gozbu Božju');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (73, 19, 18, 'da se najedete mesa kraljeva, i mesa vojvoda, i mesa mogućnika, i mesa konja i konjanika njihovih, i mesa svih mogućih ljudi, slobodnjaka i robova, malih i velikih!\"');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (73, 19, 19, 'I vidjeh: Zvijer i kraljevi zemlje i vojske njihove skupiše se u boj da se zarate s Onim što sjedi na konju i s vojskom njegovom.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (73, 19, 20, 'I Zvijer bi uhvaćena, a s njom i Lažni prorok koji je u njenoj nazočnosti činio znamenja i njima zavodio one što su primili žig Zvijeri i klanjali se njezinu kipu. Živi su oboje bačeni u ognjeno jezero što gori sumporom.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (73, 19, 21, 'A drugi su posječeni mačem što iziđe iz usta Onoga koji sjedi na konju i sve se ptice nasitiše mesa njihova.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (73, 20, 1, 'I vidjeh anđela: siđe s neba s ključima Bezdana i s velikim okovima u ruci.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (73, 20, 2, 'Zgrabi Zmaja, Staru zmiju, to jest Ðavla, Sotonu, i okova ga za tisuću godina.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (73, 20, 3, 'Baci ga u Bezdan koji nad njim zatvori i zapečati da više ne zavodi narode dok se ne navrši tisuću godina. Nakon toga ima biti odriješen za malo vremena.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (73, 20, 4, 'I vidjeh prijestolja - onima što sjedoše na njih dano je suditi - i duše pogubljenih zbog svjedočanstva Isusova i zbog Riječi Božje i sve koji se ne pokloniše Zvijeri ni kipu njezinu te ne primiše žiga na čela svoja ni na ruke. Oni oživješe i zakraljevaše s Kristom tisuću godina.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (73, 20, 5, 'Drugi mrtvi ne oživješe dok se ne navrši tisuću godina. To je ono prvo uskrsnuće.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (73, 20, 6, 'Blažen i svet onaj tko je dionik toga prvog uskrsnuća! Nad njim druga smrt nema vlasti: oni će biti svećenici Božji i Kristovi i s njime će kraljevati tisuću godina.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (73, 20, 7, 'A kad se navrši tisuću godina, Sotona će iz svoga zatvora biti pušten:');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (73, 20, 8, 'izići će zavesti narode sa četiri kraja zemlje, Goga i Magoga, i skupiti ih u boj. Bit će ih kao pijeska morskoga.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (73, 20, 9, 'Skupiše se na prostrano polje zemlje i opkoliše tabor svetih i ljubljeni grad. Ali oganj siđe s neba te ih proguta.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (73, 20, 10, 'A njihov zavodnik, Ðavao, bačen bi u jezero ognjeno i sumporno, gdje se nalaze i Zvijer i Lažni prorok: ondje će se mučiti danju i noću u vijeke vjekova.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (73, 20, 11, 'I vidjeh veliko bijelo prijestolje i Onoga što sjede na nj: pred licem njegovim pobježe zemlja i nebo; ni mjesta im se više ne nađe.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (73, 20, 12, 'I vidjeh mrtve, velike i male: stoje pred prijestoljem, a knjige se otvoriše. I otvori se jedna druga knjiga, knjiga života. I mrtvi bijahu suđeni po onome što stoji napisano u knjigama, po djelima svojim.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (73, 20, 13, 'More predade svoje mrtvace, a Smrt i Podzemlje svoje: i svaki bi suđen po djelima svojim.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (73, 20, 14, 'A Smrt i Podzemlje bili su bačeni u jezero ognjeno. Jezero ognjeno - to je druga smrt:');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (73, 20, 15, 'tko se god ne nađe zapisan u knjizi života, bio je bačen u jezero ognjeno.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (73, 21, 1, 'I vidjeh novo nebo i novu zemlju jer - prvo nebo i prva zemlja uminu; ni mora više nema.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (73, 21, 2, 'I Sveti grad, novi Jeruzalem, vidjeh: silazi s neba od Boga, opremljen kao zaručnica nakićena za svoga muža.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (73, 21, 3, 'I začujem jak glas s prijestolja: \"Evo Šatora Božjeg s ljudima! On će prebivati s njima: oni će biti narod njegov, a on će biti Bog s njima.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (73, 21, 4, 'I otrt će im svaku suzu s očiju te smrti više neće biti, ni tuge, ni jauka, ni boli više neće biti jer - prijašnje uminu.\"');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (73, 21, 5, 'Tada Onaj što sjedi na prijestolju reče: \"Evo, sve činim novo!\" I doda: \"Napiši: Ove su riječi vjerne i istinite.\"');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (73, 21, 6, 'I još mi reče: \"Svršeno je! Ja sam Alfa i Omega, Početak i Svršetak! Ja ću žednomu dati s izvora vode života zabadava.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (73, 21, 7, 'To će biti baština pobjednikova. I ja ću njemu biti Bog, a on meni sin.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (73, 21, 8, 'Kukavicama pak, nevjernima i okaljanima, ubojicama, bludnicima, vračarima i idolopoklonicima i svim lažljivcima udio je u jezeru što gori ognjem i sumporom. To je druga smrt.\"');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (73, 21, 9, 'I dođe jedan od sedam anđela što imaju sedam čaša punih zala konačnih te progovori sa mnom: \"Dođi, pokazat ću ti Zaručnicu, Ženu Jaganjčevu!\"');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (73, 21, 10, 'I prenese me u duhu na goru veliku, visoku i pokaza mi sveti grad Jeruzalem: silazi s neba od Boga,');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (73, 21, 11, 'sav u slavi Božjoj, blistav poput dragoga kamena, kamena slična kristalnom jaspisu;');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (73, 21, 12, 'okružen zidinama velikim i visokim, sa dvanaest vrata: na vratima dvanaest anđela i napisana imena dvanaest plemena Izraelovih.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (73, 21, 13, 'Od istoka vrata troja, od sjevera vrata troja, od juga vrata troja, od zapada vrata troja.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (73, 21, 14, 'Gradske su zidine imale dvanaest temelja, a na njima dvanaest imena dvanaestorice apostola Jaganjčevih.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (73, 21, 15, 'Moj subesjednik imaše mjeru, zlatnu trsku, da izmjeri grad, vrata njegova i zidine.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (73, 21, 16, 'Grad se stere u četvorini: dužina mu jednaka širini. On izmjeri trskom grad: dvanaest tisuća stadija - dužina mu i širina i visina jednaka.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (73, 21, 17, 'Izmjeri i njegove zidine: sto četrdeset i četiri lakta po čovjekovoj mjeri kojom je mjerio anđeo.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (73, 21, 18, 'Zidine su gradske sagrađene od jaspisa, a sam grad od čistoga zlata, slična čistu staklu.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (73, 21, 19, 'Temelji su gradskih zidina urešeni svakovrsnim dragim kamenjem: prvi je temelj od jaspisa, drugi od safira, treći od kalcedona, četvrti od smaragda,');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (73, 21, 20, 'peti od sardoniksa, šesti od sarda, sedmi od krizolita, osmi od berila, deveti od topaza, deseti od krizopraza, jedanaesti od hijacinta, dvanaesti od ametista.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (73, 21, 21, 'Dvanaest vrata - dvanaest bisera: svaka od svoga bisera. A gradski trg - čisto zlato, kao prozirno staklo.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (73, 21, 22, 'Hrama u gradu ne vidjeh. Ta Gospod, Bog, Svevladar, hram je njegov - i Jaganjac!');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (73, 21, 23, 'I gradu ne treba ni sunca ni mjeseca da mu svijetle. Ta Slava ga Božja obasjala i svjetiljka mu Jaganjac!');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (73, 21, 24, 'Narodi će hoditi u svjetlosti njegovoj, a kraljevi zemaljski u nj donositi slavu svoju.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (73, 21, 25, 'Vrata mu se ne zatvaraju obdan, a noći ondje i nema.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (73, 21, 26, 'U nj će se donijeti slava i čast naroda.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (73, 21, 27, 'Ali u nj neće unići ništa nečisto i nijedan tko čini gadost i laž, nego samo oni koji su zapisani u Jaganjčevoj knjizi života.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (73, 22, 1, 'I pokaza mi rijeku vode života, bistru kao prozirac: izvire iz prijestolja Božjeg i Jaganjčeva.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (73, 22, 2, 'Posred gradskoga trga, s obje strane rijeke, stablo života što rodi dvanaest puta, svakog mjeseca svoj rod. A lišće stabla za zdravlje je narodima.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (73, 22, 3, 'I neće više biti nikakva prokletstva. I prijestolje će Božje i Jaganjčevo biti u gradu i sluge će mu se njegove klanjati');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (73, 22, 4, 'i gledati lice njegovo, a ime će im njegovo biti na čelima.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (73, 22, 5, 'Noći više biti neće i neće trebati svjetla od svjetiljke ni svjetla sunčeva: obasjavat će ih Gospod Bog i oni će kraljevati u vijeke vjekova.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (73, 22, 6, 'I reče mi: \"Ove su riječi vjerne i istinite jer Gospod Bog, nadahnitelj proroka, posla svoga anđela da on pokaže slugama njegovim što se ima dogoditi ubrzo.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (73, 22, 7, 'I evo, dolazim ubrzo! Blago onomu koji čuva riječi proroštva ove knjige!\"');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (73, 22, 8, 'Ja, Ivan, čuo sam i vidio sve ovo. I kad sam to vidio i čuo, padoh pred noge anđelu koji mi to pokaza da mu se poklonim.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (73, 22, 9, 'A on će mi: \"Nipošto! Sluga sam kao i ti i braća tvoja proroci i svi koji čuvaju riječi ove knjige. Bogu se pokloni!\"');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (73, 22, 10, 'A zatim će mi: \"Ne zapečati riječi proroštva ove knjige jer - vrijeme je blizu!');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (73, 22, 11, 'Nepravednik neka samo i dalje čini nepravdu! Okaljan neka se i dalje kalja! Pravednik neka i dalje živi pravedno! Svet neka se i dalje posvećuje!\"');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (73, 22, 12, '\"Evo, dolazim ubrzo i plaća moja sa mnom: naplatit ću svakom po njegovu djelu!\"');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (73, 22, 13, '\"Ja sam Alfa i Omega, Prvi i Posljednji, Početak i Svršetak!');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (73, 22, 14, 'Blago onima koji peru svoje haljine: imat će pravo na stablo života i na vrata će smjeti u grad!');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (73, 22, 15, 'Vani pak ostaju psi i vračari, bludnice, ubojice i idolopoklonici i tko god ljubi i čini laž.\"');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (73, 22, 16, '\"Ja, Isus, poslah anđela svoga posvjedočiti ovo po crkvama. Ja sam korijen i izdanak Davidov, sjajna zvijezda Danica.\"');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (73, 22, 17, 'I Duh i Zaručnica govore: \"Dođi!\" I tko ovo čuje, neka rekne: \"Dođi!\" Tko je žedan, neka dođe; tko hoće, neka zahvati vode života zabadava!');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (73, 22, 18, 'Ja svjedočim svakomu tko sluša riječi proroštva u ovoj knjizi: Tko ovomu što doda, Bog će njemu dodati zla napisana u ovoj knjizi.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (73, 22, 19, 'I tko oduzme od riječi proroštva u ovoj knjizi, Bog će mu oduzeti udio na stablu života i na svetom gradu - na svemu što je napisano u ovoj knjizi.');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (73, 22, 20, 'Svjedok za sve ovo govori: \"Da, dolazim ubrzo!\" Amen! Dođi, Gospodine Isuse!');
INSERT INTO `CroSaric_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (73, 22, 21, 'Milost Gospodina Isusa sa svima!');
